function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Warm gradient background - amber twilight
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(45, 25, 40), color(180, 100, 50), inter * 0.6);
    stroke(c);
    line(0, y, width, y);
  }

  // Add atmospheric texture
  noStroke();
  for (let i = 0; i < 50000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.003, y * 0.003);
    fill(255, 200, 150, n * 15);
    ellipse(x, y, random(1, 3));
  }

  // Draw the dissolving figure
  drawDissolvingFigure();

  // Draw flower field
  drawFlowerField();

  // Add light rays from above
  drawLightRays();

  // Final atmospheric layer
  for (let i = 0; i < 20000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.005, y * 0.005, 0.5);
    fill(255, 220, 180, n * 8);
    ellipse(x, y, random(2, 5));
  }
}

function drawDissolvingFigure() {
  // Figure center
  let figureX = width / 2;
  let figureY = height * 0.4;

  // Draw figure as particles that become more dispersed toward edges
  for (let i = 0; i < 15000; i++) {
    // Create human-like shape with noise
    let angle = random(TWO_PI);
    let baseRadius = random(50, 280);

    // Shape the figure - head, torso, suggestion of arms
    let shapeY = sin(angle) * baseRadius;
    let shapeX = cos(angle) * baseRadius * 0.6;

    // Adjust for human proportions
    if (shapeY < -100) {
      // Head region - smaller
      shapeX *= 0.4;
      shapeY *= 0.8;
    } else if (shapeY > 100) {
      // Lower body dissolving more
      shapeX *= 1.2 + noise(i * 0.01) * 0.5;
    }

    let px = figureX + shapeX;
    let py = figureY + shapeY;

    // Add dissolution effect - particles drift away
    let distFromCenter = dist(px, py, figureX, figureY);
    let dissolution = map(distFromCenter, 0, 300, 0, 1);
    dissolution = constrain(dissolution, 0, 1);

    // More dissolution at bottom
    let yDissolution = map(py, figureY - 200, figureY + 400, 0, 1);
    yDissolution = constrain(yDissolution, 0, 1);

    let totalDissolution = dissolution * 0.5 + yDissolution * 0.5;

    // Drift particles outward and downward as they dissolve
    let drift = totalDissolution * 150;
    px += (noise(i * 0.02, 0) - 0.5) * drift * 2;
    py += noise(i * 0.02, 100) * drift;

    // Color - warm flesh tones fading to flower colors
    let r = lerp(200, 255, totalDissolution) + random(-20, 20);
    let g = lerp(160, 180, totalDissolution) + random(-20, 20);
    let b = lerp(140, 200, totalDissolution) + random(-20, 20);
    let alpha = map(totalDissolution, 0, 1, 180, 40);

    fill(r, g, b, alpha);
    noStroke();
    let size = map(totalDissolution, 0, 1, 2, 6);
    ellipse(px, py, size);
  }

  // Inner glow/light within figure
  for (let i = 0; i < 3000; i++) {
    let angle = random(TWO_PI);
    let r = random(100);
    let px = figureX + cos(angle) * r * 0.6;
    let py = figureY + sin(angle) * r - 50;

    let alpha = map(r, 0, 100, 60, 10);
    fill(255, 240, 220, alpha);
    ellipse(px, py, random(3, 8));
  }
}

function drawFlowerField() {
  // Ground layer
  for (let y = height * 0.6; y < height; y += 2) {
    for (let x = 0; x < width; x += 3) {
      let n = noise(x * 0.01, y * 0.01);
      let g = map(n, 0, 1, 30, 70);
      fill(40, g, 30, 150);
      noStroke();
      ellipse(x + random(-2, 2), y, random(4, 8), random(2, 4));
    }
  }

  // Grass blades
  for (let i = 0; i < 3000; i++) {
    let x = random(width);
    let baseY = map(x, 0, width, height * 0.65, height * 0.6) + random(0, height * 0.4);
    baseY = constrain(baseY, height * 0.55, height);

    let grassHeight = random(30, 100);
    let sway = noise(x * 0.01, i * 0.1) * 30 - 15;

    stroke(30 + random(20), 60 + random(30), 20 + random(20), 150);
    strokeWeight(1);
    noFill();

    beginShape();
    for (let j = 0; j <= 10; j++) {
      let t = j / 10;
      let gx = x + sway * t * t;
      let gy = baseY - grassHeight * t;
      curveVertex(gx, gy);
    }
    endShape();
  }

  // Flowers - various types
  for (let i = 0; i < 800; i++) {
    let x = random(width);
    let baseY = height * 0.6 + random(height * 0.4);

    // Flowers closer to figure are more luminous
    let distToFigure = dist(x, baseY, width/2, height * 0.5);
    let luminosity = map(distToFigure, 0, 600, 1.3, 0.8);

    let flowerType = floor(random(4));
    let stemHeight = random(60, 150);
    let flowerY = baseY - stemHeight;

    // Skip if too high
    if (flowerY < height * 0.45) continue;

    // Stem
    stroke(40, 70, 30, 180);
    strokeWeight(1.5);
    let sway = noise(x * 0.02, i) * 20 - 10;

    noFill();
    beginShape();
    curveVertex(x, baseY);
    curveVertex(x, baseY);
    curveVertex(x + sway * 0.3, baseY - stemHeight * 0.5);
    curveVertex(x + sway, flowerY);
    curveVertex(x + sway, flowerY);
    endShape();

    let fx = x + sway;
    let fy = flowerY;

    noStroke();

    if (flowerType === 0) {
      // Poppy-like
      let size = random(15, 30);
      for (let p = 0; p < 5; p++) {
        let pAngle = p * TWO_PI / 5 + random(0.2);
        let pr = constrain(220 * luminosity + random(-20, 20), 0, 255);
        let pg = constrain(80 * luminosity + random(-20, 20), 0, 255);
        let pb = constrain(60 * luminosity + random(-20, 20), 0, 255);
        fill(pr, pg, pb, 200);
        ellipse(fx + cos(pAngle) * size * 0.3, fy + sin(pAngle) * size * 0.3, size, size * 0.7);
      }
      fill(40, 30, 20);
      ellipse(fx, fy, size * 0.3);
    } else if (flowerType === 1) {
      // Daisy-like
      let size = random(10, 20);
      for (let p = 0; p < 12; p++) {
        let pAngle = p * TWO_PI / 12;
        fill(255, 250, 240, 200);
        push();
        translate(fx + cos(pAngle) * size * 0.5, fy + sin(pAngle) * size * 0.5);
        rotate(pAngle);
        ellipse(0, 0, size * 0.8, size * 0.3);
        pop();
      }
      let yr = constrain(240 * luminosity, 0, 255);
      let yg = constrain(200 * luminosity, 0, 255);
      fill(yr, yg, 100);
      ellipse(fx, fy, size * 0.5);
    } else if (flowerType === 2) {
      // Small clustered flowers
      let clr = constrain(200 * luminosity + random(55), 0, 255);
      let clg = constrain(150 * luminosity + random(50), 0, 255);
      let clb = constrain(180 * luminosity + random(75), 0, 255);
      fill(clr, clg, clb, 180);
      for (let c = 0; c < 7; c++) {
        ellipse(fx + random(-8, 8), fy + random(-8, 8), random(4, 8));
      }
    } else {
      // Bell-shaped
      let size = random(12, 22);
      let br = constrain(180 * luminosity + random(40), 0, 255);
      let bg = constrain(140 * luminosity + random(60), 0, 255);
      let bb = constrain(200 * luminosity + random(55), 0, 255);
      fill(br, bg, bb, 190);
      arc(fx, fy, size, size * 1.2, 0, PI);
      fill(255, 255, 220, 100);
      ellipse(fx, fy + size * 0.3, size * 0.3, size * 0.2);
    }
  }

  // Flowers emerging from figure area - the transformation
  for (let i = 0; i < 150; i++) {
    let angle = random(TWO_PI);
    let r = random(100, 350);
    let x = width/2 + cos(angle) * r * 0.7;
    let y = height * 0.4 + sin(angle) * r * 0.5 + r * 0.3;

    if (y < height * 0.3 || y > height * 0.75) continue;

    // These flowers glow more
    noStroke();
    let glowSize = random(20, 40);

    // Glow
    for (let g = glowSize; g > 0; g -= 2) {
      fill(255, 220, 180, map(g, 0, glowSize, 30, 2));
      ellipse(x, y, g);
    }

    // Flower
    let petalCount = floor(random(5, 9));
    for (let p = 0; p < petalCount; p++) {
      let pAngle = p * TWO_PI / petalCount + random(0.1);
      fill(255, 200 + random(55), 180 + random(40), 220);
      push();
      translate(x, y);
      rotate(pAngle);
      ellipse(8, 0, 16, 8);
      pop();
    }
    fill(255, 240, 200);
    ellipse(x, y, 8);
  }
}

function drawLightRays() {
  // Soft light rays from upper area
  for (let i = 0; i < 15; i++) {
    let x = width * 0.3 + random(width * 0.4);
    let rayWidth = random(50, 150);

    for (let y = 0; y < height * 0.7; y += 5) {
      let alpha = map(y, 0, height * 0.7, 25, 0);
      let spread = map(y, 0, height * 0.7, 0, rayWidth);
      fill(255, 240, 200, alpha);
      noStroke();
      ellipse(x + (noise(i, y * 0.01) - 0.5) * 100, y, spread, 10);
    }
  }

  // Floating particles in light
  for (let i = 0; i < 500; i++) {
    let x = random(width);
    let y = random(height * 0.7);
    let size = random(2, 6);
    let alpha = random(30, 100);
    fill(255, 250, 230, alpha);
    noStroke();
    ellipse(x, y, size);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep twilight gradient background
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c1 = color(15, 10, 35);
    let c2 = color(45, 25, 50);
    let c = lerpColor(c1, c2, inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Atmospheric haze layers
  noStroke();
  for (let i = 0; i < 50; i++) {
    let y = random(height * 0.3, height);
    let h = random(100, 400);
    fill(60, 40, 70, 5);
    ellipse(random(width), y, random(200, 800), h);
  }

  // Ground - dark earth
  fill(20, 15, 25);
  beginShape();
  vertex(0, height);
  for (let x = 0; x <= width; x += 20) {
    let y = height - 200 + noise(x * 0.003) * 150;
    vertex(x, y);
  }
  vertex(width, height);
  endShape(CLOSE);

  // Ground texture
  for (let i = 0; i < 3000; i++) {
    let x = random(width);
    let baseY = height - 200 + noise(x * 0.003) * 150;
    let y = random(baseY, height);
    fill(30 + random(20), 20 + random(15), 30 + random(20), random(50, 150));
    ellipse(x, y, random(2, 8), random(2, 6));
  }

  // Dissolving flowers - main subjects
  let flowerPositions = [
    {x: 300, y: 1500, size: 280, decay: 0.3},
    {x: 800, y: 1400, size: 350, decay: 0.5},
    {x: 1200, y: 1550, size: 260, decay: 0.7},
    {x: 500, y: 1650, size: 200, decay: 0.4},
    {x: 1000, y: 1600, size: 220, decay: 0.6},
    {x: 1400, y: 1480, size: 240, decay: 0.8}
  ];

  // Draw stems first
  for (let flower of flowerPositions) {
    drawStem(flower.x, flower.y, flower.size, flower.decay);
  }

  // Draw flowers
  for (let flower of flowerPositions) {
    drawDissolvingFlower(flower.x, flower.y, flower.size, flower.decay);
  }

  // Ascending particles - souls rising
  for (let i = 0; i < 2000; i++) {
    let x = random(width);
    let y = random(0, height * 0.85);
    let size = random(1, 6);
    let alpha = map(y, height * 0.85, 0, 50, 255);

    // Particles get more golden/white as they rise
    let r = map(y, height, 0, 180, 255);
    let g = map(y, height, 0, 100, 240);
    let b = map(y, height, 0, 120, 200);

    fill(r, g, b, alpha * random(0.3, 1));
    noStroke();
    ellipse(x, y, size, size * random(1, 2));
  }

  // Luminous streams rising from flowers
  for (let flower of flowerPositions) {
    drawParticleStream(flower.x, flower.y - flower.size * 0.3, flower.decay);
  }

  // Ethereal light from above
  for (let i = 0; i < 20; i++) {
    let x = width/2 + random(-400, 400);
    let y = random(-100, 300);
    let r = random(300, 600);

    for (let j = r; j > 0; j -= 10) {
      fill(255, 250, 240, map(j, r, 0, 0, 3));
      ellipse(x, y, j, j * 1.5);
    }
  }

  // Foreground shadow plants - silhouettes
  drawSilhouettePlants();

  // Final dust motes
  for (let i = 0; i < 500; i++) {
    let x = random(width);
    let y = random(height);
    let size = random(1, 3);
    fill(255, 255, 240, random(20, 80));
    ellipse(x, y, size);
  }

  // Vignette
  drawVignette();
}

function drawStem(x, y, size, decay) {
  let stemHeight = size * 1.2;
  let startY = y + size * 0.3;

  stroke(30, 50, 30, 200 * (1 - decay * 0.5));
  strokeWeight(map(size, 200, 350, 4, 8));
  noFill();

  beginShape();
  for (let i = 0; i <= 20; i++) {
    let t = i / 20;
    let sx = x + sin(t * PI * 0.3) * 20 + noise(i * 0.3, x * 0.01) * 15;
    let sy = startY + t * stemHeight;
    vertex(sx, sy);
  }
  endShape();

  // Leaves
  for (let i = 0; i < 3; i++) {
    let ly = startY + stemHeight * (0.3 + i * 0.25);
    let lx = x + sin((0.3 + i * 0.25) * PI * 0.3) * 20;
    let dir = (i % 2 === 0) ? 1 : -1;

    fill(25, 45, 25, 180 * (1 - decay * 0.5));
    noStroke();
    beginShape();
    vertex(lx, ly);
    bezierVertex(lx + dir * 40, ly - 20, lx + dir * 60, ly + 10, lx + dir * 30, ly + 25);
    bezierVertex(lx + dir * 15, ly + 15, lx + dir * 5, ly + 5, lx, ly);
    endShape(CLOSE);
  }
}

function drawDissolvingFlower(x, y, size, decay) {
  // Petal colors - deep reds and purples fading to light
  let petalColors = [
    color(140, 40, 60),
    color(160, 50, 80),
    color(120, 30, 70),
    color(180, 60, 90),
    color(100, 40, 80)
  ];

  // Draw petals
  let petalCount = 12;
  for (let layer = 3; layer >= 0; layer--) {
    let layerSize = size * (0.4 + layer * 0.2);

    for (let i = 0; i < petalCount; i++) {
      let angle = (TWO_PI / petalCount) * i + layer * 0.15;
      let px = x + cos(angle) * layerSize * 0.3;
      let py = y + sin(angle) * layerSize * 0.2;

      drawDissolvingPetal(px, py, angle, layerSize * 0.5, decay, petalColors[i % petalColors.length], layer);
    }
  }

  // Center of flower
  let centerDecay = decay * 0.5;
  for (let i = 0; i < 100; i++) {
    let angle = random(TWO_PI);
    let dist = random(size * 0.15) * (1 - centerDecay);
    let px = x + cos(angle) * dist;
    let py = y + sin(angle) * dist * 0.6;

    if (random() > centerDecay * 0.5) {
      fill(60, 40, 20, random(150, 255));
      ellipse(px, py, random(3, 8));
    }
  }
}

function drawDissolvingPetal(x, y, angle, size, decay, col, layer) {
  push();
  translate(x, y);
  rotate(angle - HALF_PI);

  // Solid part of petal (diminishes with decay)
  let solidPortion = 1 - decay;

  if (solidPortion > 0.1) {
    noStroke();

    for (let i = 0; i < 50 * solidPortion; i++) {
      let t = random();
      let w = sin(t * PI) * size * 0.4;
      let px = random(-w, w);
      let py = t * size * solidPortion;

      let c = color(red(col), green(col), blue(col), random(100, 220));
      fill(c);
      ellipse(px, -py, random(3, 10), random(4, 12));
    }
  }

  // Dissolving particles
  let particleCount = floor(80 * decay);
  for (let i = 0; i < particleCount; i++) {
    let t = random(solidPortion, 1);
    let baseW = sin(t * PI) * size * 0.4;
    let px = random(-baseW * 1.5, baseW * 1.5);
    let py = t * size + random(size * decay * 0.5);

    // Particles fade from petal color to golden light
    let fadeT = map(t, solidPortion, 1, 0, 1);
    let r = lerp(red(col), 255, fadeT);
    let g = lerp(green(col), 220, fadeT);
    let b = lerp(blue(col), 180, fadeT);
    let a = map(fadeT, 0, 1, 200, 50);

    fill(r, g, b, a);
    let pSize = map(fadeT, 0, 1, 6, 2);
    ellipse(px, -py, pSize, pSize * random(1, 2));
  }

  pop();
}

function drawParticleStream(x, y, intensity) {
  let streamHeight = 800 + intensity * 400;
  let particleCount = floor(300 * intensity);

  for (let i = 0; i < particleCount; i++) {
    let t = random();
    let py = y - t * streamHeight;
    let spread = map(t, 0, 1, 20, 150);
    let px = x + random(-spread, spread) + sin(t * 5 + x * 0.01) * 30;

    // Color transitions from warm to pure light
    let r = lerp(200, 255, t);
    let g = lerp(150, 250, t);
    let b = lerp(130, 240, t);
    let a = map(t, 0, 1, 180, 30);

    fill(r, g, b, a);
    noStroke();
    let size = map(t, 0, 1, 5, 2);
    ellipse(px, py, size, size * random(1.5, 3));
  }
}

function drawSilhouettePlants() {
  // Foreground grass and plants as dark silhouettes
  fill(10, 8, 15);
  noStroke();

  // Left cluster
  for (let i = 0; i < 40; i++) {
    let x = random(-50, 200);
    let baseY = height - 50;
    let h = random(100, 300);
    let sway = random(-30, 30);

    beginShape();
    vertex(x - 3, baseY);
    bezierVertex(x - 2, baseY - h * 0.5, x + sway, baseY - h * 0.8, x + sway * 1.2, baseY - h);
    bezierVertex(x + sway, baseY - h * 0.8, x + 2, baseY - h * 0.5, x + 3, baseY);
    endShape(CLOSE);
  }

  // Right cluster
  for (let i = 0; i < 40; i++) {
    let x = random(width - 200, width + 50);
    let baseY = height - 50;
    let h = random(100, 300);
    let sway = random(-30, 30);

    beginShape();
    vertex(x - 3, baseY);
    bezierVertex(x - 2, baseY - h * 0.5, x + sway, baseY - h * 0.8, x + sway * 1.2, baseY - h);
    bezierVertex(x + sway, baseY - h * 0.8, x + 2, baseY - h * 0.5, x + 3, baseY);
    endShape(CLOSE);
  }
}

function drawVignette() {
  // Create vignette effect
  noFill();
  for (let i = 0; i < 150; i++) {
    let alpha = map(i, 0, 150, 0, 100);
    stroke(5, 3, 15, alpha);
    strokeWeight(20);

    let offset = i * 15;
    rect(-offset/2, -offset/2, width + offset, height + offset, 100);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Warm golden gradient background
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(255, 220, 180), color(180, 140, 100), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Atmospheric haze layers
  noStroke();
  for (let i = 0; i < 50; i++) {
    let y = map(i, 0, 50, 400, height);
    fill(255, 240, 200, 15);
    ellipse(width/2 + noise(i * 0.5) * 400 - 200, y, 800 + noise(i) * 400, 100);
  }

  // Ground plane - earth tones
  for (let y = height * 0.6; y < height; y++) {
    for (let x = 0; x < width; x += 3) {
      let n = noise(x * 0.01, y * 0.01);
      let earthColor = lerpColor(
        color(120, 80, 50),
        color(90, 70, 45),
        n
      );
      fill(earthColor);
      noStroke();
      rect(x, y, 4, 4);
    }
  }

  // The dissolving figure - central composition
  drawDissolvingFigure();

  // Wildflowers throughout
  drawFlowerField();

  // Light rays from above
  drawLightRays();

  // Floating particles - matter transforming
  drawParticles();

  // Soft vignette
  drawVignette();
}

function drawDissolvingFigure() {
  let centerX = width / 2;
  let baseY = height * 0.75;

  // Figure made of organic, dissolving shapes
  // Lower body - more solid
  for (let i = 0; i < 800; i++) {
    let angle = noise(i * 0.1) * TWO_PI;
    let radius = noise(i * 0.05, 1) * 150;
    let y = baseY - noise(i * 0.02) * 400;
    let x = centerX + cos(angle) * radius * map(y, baseY, baseY - 500, 1, 0.3);

    // Dissolution increases toward top
    let dissolution = map(y, baseY, baseY - 600, 0, 1);
    dissolution = constrain(dissolution, 0, 1);

    if (random() > dissolution * 0.7) {
      let size = map(dissolution, 0, 1, 25, 5);
      let alpha = map(dissolution, 0, 1, 180, 40);

      // Warm flesh tones dissolving into earth
      let fleshColor = lerpColor(
        color(200, 160, 140, alpha),
        color(180, 140, 100, alpha),
        noise(i * 0.3)
      );
      fill(fleshColor);
      noStroke();
      ellipse(x, y, size * random(0.8, 1.2), size * random(0.8, 1.2));
    }
  }

  // Ethereal upper form - almost gone
  for (let i = 0; i < 300; i++) {
    let y = baseY - 400 - random(300);
    let spreadX = map(y, baseY - 400, baseY - 700, 80, 250);
    let x = centerX + random(-spreadX, spreadX);

    fill(255, 240, 220, random(20, 60));
    noStroke();
    ellipse(x, y, random(3, 15), random(3, 15));
  }

  // Connection tendrils to flowers
  stroke(180, 150, 120, 60);
  strokeWeight(1);
  for (let i = 0; i < 40; i++) {
    let startX = centerX + random(-100, 100);
    let startY = baseY - random(100, 300);
    let endX = startX + random(-200, 200);
    let endY = baseY + random(50, 200);

    noFill();
    beginShape();
    for (let t = 0; t <= 1; t += 0.1) {
      let x = lerp(startX, endX, t) + noise(t * 5, i) * 30 - 15;
      let y = lerp(startY, endY, t);
      vertex(x, y);
    }
    endShape();
  }
}

function drawFlowerField() {
  // Background flowers - distant
  for (let i = 0; i < 200; i++) {
    let x = random(width);
    let y = random(height * 0.55, height * 0.7);
    drawFlower(x, y, random(8, 15), 0.5);
  }

  // Midground flowers
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = random(height * 0.65, height * 0.85);
    drawFlower(x, y, random(12, 25), 0.7);
  }

  // Foreground flowers - larger, more detailed
  for (let i = 0; i < 150; i++) {
    let x = random(width);
    let y = random(height * 0.8, height);
    drawFlower(x, y, random(20, 40), 1);
  }

  // Flowers emerging from figure
  for (let i = 0; i < 80; i++) {
    let x = width/2 + random(-200, 200);
    let y = height * 0.6 + random(300);
    drawFlower(x, y, random(15, 35), 1);
  }
}

function drawFlower(x, y, size, detail) {
  let flowerType = floor(random(5));

  // Stem
  if (detail > 0.6 && random() > 0.3) {
    stroke(80, 100, 60, 150);
    strokeWeight(size * 0.08);
    let stemHeight = size * random(1.5, 3);
    noFill();
    beginShape();
    for (let t = 0; t <= 1; t += 0.2) {
      vertex(x + noise(t * 3, y * 0.01) * 10 - 5, y + t * stemHeight);
    }
    endShape();
  }

  noStroke();

  if (flowerType === 0) {
    // Poppy-like
    let petalColor = color(220 + random(35), 80 + random(40), 70 + random(30), 200 * detail);
    fill(petalColor);
    for (let j = 0; j < 5; j++) {
      let angle = j * TWO_PI / 5 + random(0.2);
      let px = x + cos(angle) * size * 0.4;
      let py = y + sin(angle) * size * 0.3;
      ellipse(px, py, size * 0.6, size * 0.5);
    }
    fill(40, 30, 30, 200);
    ellipse(x, y, size * 0.25, size * 0.25);

  } else if (flowerType === 1) {
    // Daisy-like
    fill(255, 250, 240, 200 * detail);
    for (let j = 0; j < 12; j++) {
      let angle = j * TWO_PI / 12;
      let px = x + cos(angle) * size * 0.35;
      let py = y + sin(angle) * size * 0.35;
      push();
      translate(px, py);
      rotate(angle);
      ellipse(0, 0, size * 0.15, size * 0.4);
      pop();
    }
    fill(255, 200, 80, 220);
    ellipse(x, y, size * 0.3, size * 0.3);

  } else if (flowerType === 2) {
    // Lavender-like
    fill(180, 150, 200, 180 * detail);
    for (let j = 0; j < 8; j++) {
      let yOff = j * size * 0.15;
      let xOff = noise(j, x * 0.1) * 6 - 3;
      ellipse(x + xOff, y - yOff, size * 0.25, size * 0.2);
    }

  } else if (flowerType === 3) {
    // Wild rose
    let roseColor = color(240, 180, 190, 190 * detail);
    fill(roseColor);
    for (let j = 0; j < 5; j++) {
      let angle = j * TWO_PI / 5 + 0.3;
      let px = x + cos(angle) * size * 0.25;
      let py = y + sin(angle) * size * 0.25;
      ellipse(px, py, size * 0.5, size * 0.5);
    }
    fill(255, 220, 100, 200);
    ellipse(x, y, size * 0.2, size * 0.2);

  } else {
    // Simple wildflower
    let wildColor = color(
      random(200, 255),
      random(100, 200),
      random(100, 180),
      180 * detail
    );
    fill(wildColor);
    for (let j = 0; j < 6; j++) {
      let angle = j * TWO_PI / 6;
      let px = x + cos(angle) * size * 0.3;
      let py = y + sin(angle) * size * 0.3;
      ellipse(px, py, size * 0.35, size * 0.35);
    }
    fill(255, 230, 150, 220);
    ellipse(x, y, size * 0.2, size * 0.2);
  }
}

function drawLightRays() {
  for (let i = 0; i < 8; i++) {
    let x1 = width * 0.3 + i * 80 + random(50);
    let x2 = x1 + random(-200, 200);

    for (let j = 0; j < 20; j++) {
      let alpha = map(j, 0, 20, 25, 5);
      let w = map(j, 0, 20, 5, 80);
      stroke(255, 250, 220, alpha);
      strokeWeight(w);
      line(x1, 0, x2, height * 0.7);
    }
  }
}

function drawParticles() {
  // Rising particles - soul/matter ascending
  for (let i = 0; i < 500; i++) {
    let x = width/2 + random(-400, 400);
    let y = random(height * 0.3, height * 0.9);
    let size = random(2, 8);

    // Concentration near figure
    let distFromCenter = abs(x - width/2);
    if (random() * 400 > distFromCenter) {
      let alpha = map(y, height * 0.9, height * 0.3, 150, 30);
      let particleColor = lerpColor(
        color(200, 170, 140, alpha),
        color(255, 240, 200, alpha),
        map(y, height * 0.9, height * 0.3, 0, 1)
      );
      fill(particleColor);
      noStroke();
      ellipse(x, y, size, size);
    }
  }
}

function drawVignette() {
  // Soft dark edges
  for (let i = 0; i < 100; i++) {
    let alpha = map(i, 0, 100, 60, 0);
    noFill();
    stroke(60, 40, 30, alpha);
    strokeWeight(20);
    rect(i * 2, i * 2, width - i * 4, height - i * 4, 50);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep earth background
  background(25, 20, 18);

  // Textured earth gradient
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x += 3) {
      let n = noise(x * 0.003, y * 0.003);
      let earthR = map(y, 0, height, 35, 15) + n * 20;
      let earthG = map(y, 0, height, 25, 10) + n * 15;
      let earthB = map(y, 0, height, 22, 8) + n * 10;
      stroke(earthR, earthG, earthB, 180);
      point(x + random(-1, 1), y);
    }
  }

  // Soft moonlight from upper right
  noStroke();
  for (let i = 0; i < 50; i++) {
    let alpha = map(i, 0, 50, 3, 0);
    fill(200, 195, 180, alpha);
    ellipse(1400, 200, 800 + i * 30, 800 + i * 30);
  }

  // The reclining figure - made of leaves
  drawFigure();

  // Scattered leaves around and from figure
  drawScatteredLeaves();

  // Growing plants emerging from figure
  drawNewGrowth();

  // Floating particles - dust, pollen, souls
  drawParticles();

  // Root systems below
  drawRoots();

  // Final texture overlay
  applyTexture();
}

function drawFigure() {
  // Figure reclines from lower left toward center
  // Built from overlapping leaf shapes

  let figureLeaves = [];

  // Torso area - dense leaves
  for (let i = 0; i < 300; i++) {
    let t = random(1);
    let x = lerp(400, 900, t) + random(-80, 80);
    let y = lerp(1400, 1300, t) + random(-60, 60);
    let size = random(20, 50);
    let angle = random(TWO_PI);
    figureLeaves.push({x, y, size, angle, type: 'torso'});
  }

  // Head area - smaller, more delicate
  for (let i = 0; i < 100; i++) {
    let angle = random(TWO_PI);
    let r = random(80);
    let x = 320 + cos(angle) * r * 0.8;
    let y = 1350 + sin(angle) * r;
    let size = random(10, 30);
    figureLeaves.push({x, y, size, angle: random(TWO_PI), type: 'head'});
  }

  // Arms - reaching upward, dissolving
  for (let i = 0; i < 150; i++) {
    let t = random(1);
    // Right arm reaching up
    let x = lerp(700, 950, t) + random(-30, 30) * (1 + t);
    let y = lerp(1350, 1000, t) + random(-30, 30) * (1 + t);
    let size = random(10, 35) * (1 - t * 0.5);
    figureLeaves.push({x, y, size, angle: random(TWO_PI), type: 'arm', dissolve: t});
  }

  // Legs - fading into earth
  for (let i = 0; i < 200; i++) {
    let t = random(1);
    let x = lerp(900, 1300, t) + random(-50, 50);
    let y = lerp(1450, 1600, t) + random(-40, 40);
    let size = random(15, 40) * (1 - t * 0.3);
    figureLeaves.push({x, y, size, angle: random(TWO_PI), type: 'legs', dissolve: t});
  }

  // Sort by size for depth
  figureLeaves.sort((a, b) => b.size - a.size);

  // Draw all figure leaves
  for (let leaf of figureLeaves) {
    drawLeaf(leaf.x, leaf.y, leaf.size, leaf.angle, leaf.dissolve || 0);
  }
}

function drawLeaf(x, y, size, angle, dissolve) {
  push();
  translate(x, y);
  rotate(angle);

  // Autumn colors - oranges, reds, browns, some yellows
  let colorChoice = random();
  let r, g, b;

  if (colorChoice < 0.3) {
    // Deep red
    r = random(120, 160);
    g = random(30, 60);
    b = random(20, 40);
  } else if (colorChoice < 0.5) {
    // Orange
    r = random(180, 220);
    g = random(80, 120);
    b = random(30, 50);
  } else if (colorChoice < 0.7) {
    // Brown
    r = random(90, 130);
    g = random(60, 90);
    b = random(40, 60);
  } else if (colorChoice < 0.85) {
    // Yellow ochre
    r = random(190, 220);
    g = random(150, 180);
    b = random(50, 80);
  } else {
    // Dark burgundy
    r = random(80, 110);
    g = random(20, 40);
    b = random(30, 50);
  }

  let alpha = map(dissolve, 0, 1, 220, 80);

  noStroke();
  fill(r, g, b, alpha);

  // Leaf shape
  beginShape();
  for (let a = 0; a < TWO_PI; a += 0.1) {
    let leafR = size * (0.5 + 0.5 * cos(a)) * (1 + 0.2 * sin(a * 3));
    let lx = cos(a) * leafR;
    let ly = sin(a) * leafR * 0.6;
    vertex(lx, ly);
  }
  endShape(CLOSE);

  // Leaf vein
  stroke(r * 0.6, g * 0.6, b * 0.6, alpha * 0.5);
  strokeWeight(size * 0.03);
  line(-size * 0.4, 0, size * 0.4, 0);

  pop();
}

function drawScatteredLeaves() {
  // Leaves drifting away from figure
  for (let i = 0; i < 200; i++) {
    let x = random(100, 1500);
    let y = random(800, 1900);

    // Avoid dense figure area somewhat
    let distFromFigure = dist(x, y, 600, 1400);
    if (distFromFigure < 200 && random() > 0.3) continue;

    let size = random(8, 25);
    let angle = random(TWO_PI);
    let dissolve = map(distFromFigure, 200, 800, 0.2, 0.8);

    drawLeaf(x, y, size, angle, dissolve);
  }

  // Petals - more delicate, floating upward
  for (let i = 0; i < 100; i++) {
    let x = random(200, 1200);
    let y = random(400, 1300);
    drawPetal(x, y, random(5, 15), random(TWO_PI));
  }
}

function drawPetal(x, y, size, angle) {
  push();
  translate(x, y);
  rotate(angle);

  // Pale pinks and whites
  let r = random(220, 255);
  let g = random(200, 230);
  let b = random(210, 240);

  noStroke();
  fill(r, g, b, random(100, 180));

  ellipse(0, 0, size, size * 2);

  pop();
}

function drawNewGrowth() {
  // Stems and shoots emerging from the figure
  let growthPoints = [
    {x: 500, y: 1380},
    {x: 650, y: 1320},
    {x: 800, y: 1350},
    {x: 450, y: 1300},
    {x: 750, y: 1280},
    {x: 600, y: 1250},
    {x: 900, y: 1200},
    {x: 550, y: 1200},
  ];

  for (let pt of growthPoints) {
    drawPlantStem(pt.x, pt.y);
  }
}

function drawPlantStem(baseX, baseY) {
  let stemHeight = random(150, 400);
  let segments = 20;

  // Draw stem
  strokeWeight(random(2, 4));
  noFill();

  let points = [];
  for (let i = 0; i <= segments; i++) {
    let t = i / segments;
    let x = baseX + sin(t * PI + random(0.5)) * 30 * t;
    let y = baseY - t * stemHeight;
    points.push({x, y});
  }

  // Gradient green stem
  for (let i = 0; i < points.length - 1; i++) {
    let t = i / points.length;
    let g = lerp(60, 140, t);
    let r = lerp(40, 80, t);
    let b = lerp(30, 60, t);
    stroke(r, g, b, lerp(200, 255, t));
    line(points[i].x, points[i].y, points[i+1].x, points[i+1].y);
  }

  // Small leaves along stem
  for (let i = 5; i < points.length - 2; i += 3) {
    if (random() > 0.5) {
      drawSmallLeaf(points[i].x, points[i].y, random([-1, 1]));
    }
  }

  // Bud or small flower at top
  let topPt = points[points.length - 1];
  if (random() > 0.3) {
    drawBud(topPt.x, topPt.y);
  }
}

function drawSmallLeaf(x, y, dir) {
  push();
  translate(x, y);
  rotate(dir * PI / 4);

  noStroke();
  fill(70, 120, 50, 200);

  beginShape();
  vertex(0, 0);
  bezierVertex(dir * 10, -5, dir * 20, -3, dir * 25, 0);
  bezierVertex(dir * 20, 3, dir * 10, 5, 0, 0);
  endShape();

  pop();
}

function drawBud(x, y) {
  noStroke();

  // Soft new growth - pale green or hints of color
  if (random() > 0.5) {
    // Green bud
    fill(100, 150, 80, 220);
    ellipse(x, y, 8, 12);
    fill(80, 130, 60, 220);
    ellipse(x - 2, y, 6, 10);
  } else {
    // Hint of flower
    fill(220, 180, 190, 180);
    for (let i = 0; i < 5; i++) {
      let a = (i / 5) * TWO_PI - PI/2;
      ellipse(x + cos(a) * 5, y + sin(a) * 5, 6, 10);
    }
  }
}

function drawParticles() {
  // Floating particles - like souls or pollen or dust
  noStroke();

  for (let i = 0; i < 500; i++) {
    let x = random(width);
    let y = random(height);
    let size = random(1, 4);

    // Denser near figure, rising upward
    let figDist = dist(x, y, 600, 1300);
    let density = map(figDist, 0, 800, 0.8, 0.2);

    if (random() > density) continue;

    // Golden/warm particles
    let alpha = random(30, 100);
    if (y < 800) {
      // Higher particles are more ethereal
      fill(255, 240, 200, alpha * 0.5);
    } else {
      fill(255, 220, 180, alpha);
    }

    ellipse(x, y, size, size);
  }

  // Larger glowing orbs - sparse
  for (let i = 0; i < 20; i++) {
    let x = random(200, 1000);
    let y = random(300, 1200);

    for (let j = 0; j < 10; j++) {
      let alpha = map(j, 0, 10, 20, 0);
      fill(255, 240, 220, alpha);
      let s = map(j, 0, 10, 5, 30);
      ellipse(x, y, s, s);
    }
  }
}

function drawRoots() {
  // Subtle root network at bottom
  stroke(50, 35, 30, 100);
  strokeWeight(1);

  // Main roots descending
  let rootStarts = [
    {x: 400, y: 1500},
    {x: 600, y: 1550},
    {x: 800, y: 1480},
    {x: 1000, y: 1600},
    {x: 1200, y: 1650},
  ];

  for (let root of rootStarts) {
    drawRootBranch(root.x, root.y, PI/2 + random(-0.3, 0.3), random(100, 200), 3);
  }
}

function drawRootBranch(x, y, angle, length, depth) {
  if (depth <= 0 || length < 10) return;

  let endX = x + cos(angle) * length;
  let endY = y + sin(angle) * length;

  // Curved root
  noFill();
  stroke(60, 45, 35, 60 + depth * 20);
  strokeWeight(depth * 0.5);

  let midX = (x + endX) / 2 + random(-20, 20);
  let midY = (y + endY) / 2 + random(-10, 10);

  beginShape();
  vertex(x, y);
  quadraticVertex(midX, midY, endX, endY);
  endShape();

  // Branch off
  if (random() > 0.3) {
    drawRootBranch(endX, endY, angle + random(-0.5, 0.5), length * random(0.5, 0.8), depth - 1);
  }
  if (random() > 0.5) {
    drawRootBranch(endX, endY, angle + random(-0.8, 0.8), length * random(0.4, 0.6), depth - 1);
  }
}

function applyTexture() {
  // Subtle canvas texture
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let noiseVal = random(-8, 8);
    pixels[i] += noiseVal;
    pixels[i + 1] += noiseVal;
    pixels[i + 2] += noiseVal;
  }
  updatePixels();

  // Vignette
  noStroke();
  for (let i = 0; i < 100; i++) {
    let alpha = map(i, 0, 100, 0, 40);
    fill(10, 8, 5, alpha);
    let margin = i * 10;
    beginShape();
    vertex(0, 0);
    vertex(width, 0);
    vertex(width, height);
    vertex(0, height);
    beginContour();
    ellipse(width/2, height/2, width - margin, height - margin);
    endContour();
    endShape(CLOSE);
  }

  // Simplified vignette with rectangles
  for (let i = 0; i < 50; i++) {
    let alpha = map(i, 0, 50, 2, 0);
    fill(5, 3, 2, alpha);
    rect(0, 0, width, i * 20);
    rect(0, height - i * 20, width, i * 20);
    rect(0, 0, i * 15, height);
    rect(width - i * 15, 0, i * 15, height);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Warm amber gradient background
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(45, 25, 15), color(180, 120, 60), inter * 0.3 + 0.1);
    stroke(c);
    line(0, y, width, y);
  }

  // Add atmospheric texture
  noStroke();
  for (let i = 0; i < 50000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.003, y * 0.003);
    fill(200, 150, 80, n * 15);
    ellipse(x, y, random(1, 3));
  }

  // Ground field - darker earth tones at bottom
  for (let y = height * 0.6; y < height; y++) {
    for (let x = 0; x < width; x += 3) {
      let n = noise(x * 0.01, y * 0.01);
      let darkness = map(y, height * 0.6, height, 0, 1);
      fill(60 - darkness * 30, 45 - darkness * 20, 30 - darkness * 15, n * 100);
      noStroke();
      ellipse(x + random(-2, 2), y, random(2, 6), random(2, 8));
    }
  }

  // Dissolving figure - centered, emerging/merging with flowers
  let figureX = width / 2;
  let figureY = height * 0.45;

  // Figure made of particles that disperse upward
  for (let i = 0; i < 8000; i++) {
    let angle = random(TWO_PI);
    let baseRadius = random(50, 280);

    // Human silhouette shape modifier
    let yOffset = cos(angle) * baseRadius * 1.8;
    let xOffset = sin(angle) * baseRadius * 0.6;

    // Head
    if (yOffset < -180) {
      let headFactor = map(yOffset, -180, -320, 1, 0.3);
      xOffset *= headFactor;
    }

    // Shoulders
    if (yOffset > -180 && yOffset < -100) {
      xOffset *= map(abs(yOffset + 140), 0, 40, 1.3, 1);
    }

    // Dispersal effect - particles float away more at top
    let dispersal = map(yOffset, -300, 300, 1, 0);
    dispersal = pow(dispersal, 2);
    let scatter = dispersal * random(0, 400);
    xOffset += random(-scatter, scatter);
    yOffset -= dispersal * random(0, 200);

    let px = figureX + xOffset;
    let py = figureY + yOffset;

    // Color varies from warm flesh to flower colors as it disperses
    let fleshColor = color(180, 130, 100, 150);
    let petalColor = color(
      random([200, 220, 180, 160]),
      random([80, 100, 120, 90]),
      random([80, 100, 70, 85]),
      100
    );

    let c = lerpColor(fleshColor, petalColor, dispersal + random(0.2));
    fill(c);
    noStroke();

    let size = map(dispersal, 0, 1, 2, 6);
    ellipse(px, py, size, size);
  }

  // Flowers throughout - denser at bottom, sparse toward dissolving figure
  drawFlowerField();

  // Light rays from above
  drawLightRays();

  // Floating particles/spores
  drawSpores();
}

function drawFlowerField() {
  // Background flowers (smaller, distant)
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = random(height * 0.5, height);
    let size = random(5, 15);
    drawFlower(x, y, size, 0.5);
  }

  // Main flowers
  for (let i = 0; i < 500; i++) {
    let x = random(width);
    let y = random(height * 0.55, height);

    // More flowers at bottom
    let density = map(y, height * 0.55, height, 0.3, 1);
    if (random() > density) continue;

    // Avoid center where figure is (mostly)
    let distFromCenter = abs(x - width/2);
    if (y < height * 0.7 && distFromCenter < 200 && random() > 0.3) continue;

    let size = random(15, 45);
    drawFlower(x, y, size, 1);
  }

  // Stems and grass
  for (let i = 0; i < 1000; i++) {
    let x = random(width);
    let baseY = random(height * 0.7, height + 50);

    stroke(45 + random(-10, 10), 60 + random(-10, 10), 30 + random(-10, 10), 150);
    strokeWeight(random(1, 2));
    noFill();

    beginShape();
    let swayAmount = random(-30, 30);
    for (let j = 0; j < 5; j++) {
      let t = j / 4;
      let stemX = x + sin(t * PI) * swayAmount;
      let stemY = baseY - t * random(50, 150);
      curveVertex(stemX, stemY);
    }
    endShape();
  }
}

function drawFlower(x, y, size, alpha) {
  push();
  translate(x, y);

  // Flower types
  let flowerType = floor(random(4));

  let colors = [
    color(200, 80, 80, 200 * alpha),   // Red
    color(220, 180, 100, 200 * alpha), // Yellow
    color(180, 100, 150, 200 * alpha), // Pink
    color(230, 200, 180, 200 * alpha), // Cream
    color(190, 90, 70, 200 * alpha),   // Coral
  ];

  let petalColor = random(colors);
  let centerColor = color(80, 60, 40, 200 * alpha);

  noStroke();

  if (flowerType === 0) {
    // Simple 5-petal flower
    fill(petalColor);
    for (let i = 0; i < 5; i++) {
      let angle = (TWO_PI / 5) * i + random(-0.1, 0.1);
      let px = cos(angle) * size * 0.4;
      let py = sin(angle) * size * 0.4;
      ellipse(px, py, size * 0.5, size * 0.7);
    }
    fill(centerColor);
    ellipse(0, 0, size * 0.3);
  } else if (flowerType === 1) {
    // Daisy-like
    fill(petalColor);
    for (let i = 0; i < 12; i++) {
      let angle = (TWO_PI / 12) * i;
      push();
      rotate(angle);
      ellipse(0, -size * 0.3, size * 0.15, size * 0.4);
      pop();
    }
    fill(200, 180, 80, 200 * alpha);
    ellipse(0, 0, size * 0.35);
  } else if (flowerType === 2) {
    // Rose-like spiral
    for (let i = 0; i < 20; i++) {
      let angle = i * 0.5;
      let radius = i * size * 0.025;
      let px = cos(angle) * radius;
      let py = sin(angle) * radius;
      fill(red(petalColor) - i * 2, green(petalColor) - i, blue(petalColor) - i, alpha * 180);
      ellipse(px, py, size * 0.25, size * 0.2);
    }
  } else {
    // Poppy-like
    fill(petalColor);
    for (let i = 0; i < 4; i++) {
      let angle = (TWO_PI / 4) * i + PI/4;
      push();
      rotate(angle);
      ellipse(0, -size * 0.25, size * 0.6, size * 0.7);
      pop();
    }
    fill(30, 30, 30, 200 * alpha);
    ellipse(0, 0, size * 0.25);
  }

  pop();
}

function drawLightRays() {
  // Soft golden light rays from upper center
  for (let i = 0; i < 15; i++) {
    let angle = map(i, 0, 15, -PI/4, PI/4) + random(-0.05, 0.05);
    let rayWidth = random(50, 150);

    for (let j = 0; j < 100; j++) {
      let t = j / 100;
      let rayLength = height * 0.8;
      let x = width/2 + cos(angle + PI/2) * t * rayLength;
      let y = t * rayLength;

      let alpha = sin(t * PI) * 15;
      fill(255, 220, 150, alpha);
      noStroke();
      ellipse(x, y, rayWidth * (1 - t * 0.5), 10);
    }
  }
}

function drawSpores() {
  // Floating particles rising upward
  for (let i = 0; i < 500; i++) {
    let x = random(width);
    let y = random(height);

    // More particles near the dissolving figure
    let distFromFigure = dist(x, y, width/2, height * 0.4);
    let probability = map(distFromFigure, 0, 500, 1, 0.2);
    if (random() > probability) continue;

    let size = random(2, 8);
    let alpha = random(50, 150);

    // Warm golden spores
    fill(255, 230, 180, alpha);
    noStroke();
    ellipse(x, y, size, size);

    // Soft glow
    fill(255, 220, 150, alpha * 0.3);
    ellipse(x, y, size * 2, size * 2);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep gradient background - from warm life to cold void
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(45, 8, t);
    let g = lerp(35, 12, t);
    let b = lerp(50, 25, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Subtle cosmic texture
  for (let i = 0; i < 3000; i++) {
    let x = random(width);
    let y = random(height);
    let alpha = random(5, 25);
    let size = random(1, 3);
    noStroke();
    fill(255, 250, 240, alpha);
    ellipse(x, y, size, size);
  }

  // The threshold - a horizontal band of luminosity
  let thresholdY = height * 0.42;
  for (let y = thresholdY - 200; y < thresholdY + 200; y++) {
    let dist = abs(y - thresholdY);
    let alpha = map(dist, 0, 200, 40, 0);
    stroke(255, 245, 230, alpha);
    for (let x = 0; x < width; x++) {
      let n = noise(x * 0.003, y * 0.005);
      if (random() < 0.3 + n * 0.2) {
        point(x, y);
      }
    }
  }

  // The figure - dissolving upward
  let figureBaseY = height * 0.85;
  let figureCenterX = width * 0.5;

  // Draw figure from bottom to top, increasing dissolution
  for (let i = 0; i < 80000; i++) {
    // Figure proportions
    let t = random();
    let figureHeight = height * 0.55;
    let yPos = figureBaseY - t * figureHeight;

    // Calculate dissolution factor (more dissolved at top)
    let dissolution = pow(t, 1.5);

    // Figure silhouette width at this height
    let bodyWidth;
    let relativeY = t;

    if (relativeY < 0.15) {
      // Legs/base
      bodyWidth = lerp(180, 120, relativeY / 0.15);
    } else if (relativeY < 0.5) {
      // Torso
      let torsoT = (relativeY - 0.15) / 0.35;
      bodyWidth = lerp(120, 160, sin(torsoT * PI));
    } else if (relativeY < 0.7) {
      // Shoulders to neck
      let shoulderT = (relativeY - 0.5) / 0.2;
      bodyWidth = lerp(160, 60, shoulderT);
    } else {
      // Head
      let headT = (relativeY - 0.7) / 0.3;
      bodyWidth = 70 * sin(headT * PI);
    }

    // Add noise to silhouette
    let noiseOffset = noise(yPos * 0.01, i * 0.0001) * 50 * dissolution;
    bodyWidth += noiseOffset;

    // Calculate x position within silhouette
    let spreadFactor = 1 + dissolution * 3;
    let xOffset = (random() - 0.5) * bodyWidth * spreadFactor;
    let xPos = figureCenterX + xOffset;

    // Skip if too far from figure center (creates dissolution effect)
    let distFromCenter = abs(xOffset);
    if (distFromCenter > bodyWidth * 0.5 && random() > (1 - dissolution)) {
      continue;
    }

    // Particle properties
    let particleSize = lerp(4, 1, dissolution) * random(0.5, 1.5);

    // Color gradient from warm (bottom) to cool/transparent (top)
    let warmth = 1 - dissolution;
    let r = lerp(80, 200, warmth) + random(-20, 20);
    let g = lerp(70, 160, warmth) + random(-15, 15);
    let b = lerp(90, 140, warmth) + random(-10, 10);
    let alpha = lerp(10, 180, warmth * warmth);

    // Add some bright particles (life essence)
    if (random() < 0.02 * warmth) {
      r = 255;
      g = lerp(200, 250, random());
      b = lerp(180, 220, random());
      alpha = random(100, 200);
      particleSize *= 1.5;
    }

    // Dispersing particles above threshold
    if (yPos < thresholdY) {
      let aboveThreshold = (thresholdY - yPos) / (thresholdY - height * 0.2);
      xPos += (noise(xPos * 0.01, yPos * 0.01) - 0.5) * 400 * aboveThreshold;
      yPos += (noise(xPos * 0.02, yPos * 0.02) - 0.5) * 100 * aboveThreshold;
      alpha *= (1 - aboveThreshold * 0.7);
    }

    noStroke();
    fill(r, g, b, alpha);
    ellipse(xPos, yPos, particleSize, particleSize);
  }

  // Rising particles - souls/essence dispersing
  for (let i = 0; i < 500; i++) {
    let x = figureCenterX + (noise(i * 0.5) - 0.5) * 600;
    let y = random(height * 0.1, thresholdY + 100);
    let size = random(2, 8);
    let alpha = map(y, height * 0.1, thresholdY, 10, 60);

    // Warm golden particles
    fill(255, lerp(220, 180, random()), lerp(150, 100, random()), alpha);
    noStroke();
    ellipse(x, y, size, size);
  }

  // Void above - subtle darker region
  for (let i = 0; i < 2000; i++) {
    let x = random(width);
    let y = random(height * 0.3);
    let alpha = map(y, 0, height * 0.3, 30, 5);
    fill(5, 5, 15, alpha);
    noStroke();
    ellipse(x, y, random(10, 40), random(10, 40));
  }

  // Light rays from threshold
  for (let i = 0; i < 15; i++) {
    let angle = map(i, 0, 15, -PI * 0.3, PI * 0.3) - PI/2;
    let startX = width * 0.5 + (noise(i) - 0.5) * 400;
    let startY = thresholdY;

    for (let j = 0; j < 100; j++) {
      let dist = j * 8;
      let x = startX + cos(angle) * dist + (noise(i, j * 0.1) - 0.5) * 50;
      let y = startY + sin(angle) * dist;
      let alpha = map(j, 0, 100, 25, 0);
      let size = map(j, 0, 100, 3, 15);

      fill(255, 250, 240, alpha);
      noStroke();
      ellipse(x, y, size, size);
    }
  }

  // Shadow beneath figure - grounding in existence
  for (let i = 0; i < 5000; i++) {
    let x = figureCenterX + (random() - 0.5) * 400;
    let y = figureBaseY + random(20, 150);
    let distFromCenter = abs(x - figureCenterX);
    let alpha = map(distFromCenter, 0, 200, 40, 5);
    alpha *= map(y, figureBaseY, figureBaseY + 150, 1, 0);

    fill(10, 8, 20, alpha);
    noStroke();
    ellipse(x, y, random(5, 20), random(3, 10));
  }

  // Final atmospheric haze
  for (let y = 0; y < height; y += 2) {
    let alpha = 3 + noise(y * 0.01) * 5;
    stroke(20, 18, 30, alpha);
    line(0, y, width, y);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep gradient background - from warm life to cool void
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(45, 35, 50), color(8, 8, 15), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // The dissolving figure - a form losing its coherence
  drawDissolvingForm();

  // Particles rising/falling - matter returning to field
  drawParticles();

  // The threshold - where form meets formlessness
  drawThreshold();

  // Soft luminous glow at center - consciousness diffusing
  drawInnerLight();

  // Final mist overlay
  drawMist();
}

function drawDissolvingForm() {
  push();
  translate(width/2, height * 0.4);

  // Multiple layers of the dissolving figure
  for (let layer = 0; layer < 15; layer++) {
    let alpha = map(layer, 0, 14, 60, 5);
    let spread = map(layer, 0, 14, 0, 150);

    noFill();

    // Warm tones for inner layers, cool for outer
    let r = map(layer, 0, 14, 180, 60);
    let g = map(layer, 0, 14, 140, 70);
    let b = map(layer, 0, 14, 130, 100);

    stroke(r, g, b, alpha);
    strokeWeight(map(layer, 0, 14, 2, 0.5));

    // Draw organic dissolving shape
    beginShape();
    for (let angle = 0; angle < TWO_PI; angle += 0.02) {
      let baseRadius = 200 + sin(angle * 3) * 50 + cos(angle * 2) * 30;
      let noiseVal = noise(cos(angle) * 2 + layer * 0.1, sin(angle) * 2, layer * 0.05);
      let dissolution = map(layer, 0, 14, 0, 1);

      // Form breaks apart more at edges and top
      let verticalFactor = map(sin(angle), -1, 1, 0.5, 1.5);
      let r_modified = baseRadius + noiseVal * spread * verticalFactor;

      // Add fragmentation
      if (random() < dissolution * 0.3) {
        r_modified += random(-30, 80) * dissolution;
      }

      let x = cos(angle) * r_modified + random(-spread * 0.1, spread * 0.1);
      let y = sin(angle) * r_modified * 1.3 + random(-spread * 0.1, spread * 0.1);

      curveVertex(x, y);
    }
    endShape(CLOSE);
  }

  // Inner structure hints - like bones or essence fading
  for (let i = 0; i < 50; i++) {
    let angle = random(TWO_PI);
    let dist = random(50, 180);
    let x = cos(angle) * dist * random(0.8, 1.2);
    let y = sin(angle) * dist * 1.3 * random(0.8, 1.2);

    stroke(200, 180, 170, random(10, 40));
    strokeWeight(random(0.5, 2));

    let len = random(10, 40);
    let ang = angle + random(-0.5, 0.5);
    line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }

  pop();
}

function drawParticles() {
  // Particles that are both rising and dissolving
  for (let i = 0; i < 2000; i++) {
    let baseX = width/2 + randomGaussian(0, 200);
    let baseY = height * 0.4 + randomGaussian(0, 300);

    // Particles drift upward and outward
    let drift = noise(baseX * 0.005, baseY * 0.005, i * 0.01);
    let driftAngle = map(drift, 0, 1, -PI * 0.7, -PI * 0.3);
    let driftDist = map(baseY, height * 0.7, height * 0.1, 0, 300);
    driftDist = max(0, driftDist);

    let x = baseX + cos(driftAngle) * driftDist * noise(i * 0.1);
    let y = baseY + sin(driftAngle) * driftDist * noise(i * 0.1 + 100);

    // Color shifts from warm to cool as particles rise
    let heightRatio = map(y, height * 0.8, height * 0.1, 0, 1);
    heightRatio = constrain(heightRatio, 0, 1);

    let r = lerp(190, 80, heightRatio);
    let g = lerp(150, 100, heightRatio);
    let b = lerp(140, 140, heightRatio);
    let a = map(heightRatio, 0, 1, 80, 20) * random(0.5, 1.5);

    // Distance from center affects visibility
    let distFromCenter = dist(x, y, width/2, height * 0.4);
    a *= map(distFromCenter, 0, 500, 1, 0.2);

    noStroke();
    fill(r, g, b, a);

    let size = random(1, 4) * map(heightRatio, 0, 1, 1, 0.3);
    ellipse(x, y, size, size);
  }
}

function drawThreshold() {
  // A soft horizontal zone where form transitions
  push();

  for (let i = 0; i < 100; i++) {
    let y = height * 0.65 + randomGaussian(0, 80);
    let x = random(width * 0.1, width * 0.9);
    let w = random(50, 300);

    let distFromCenter = abs(x - width/2);
    let alpha = map(distFromCenter, 0, width/2, 30, 5);

    stroke(100, 90, 110, alpha);
    strokeWeight(random(0.5, 1.5));

    // Wavy threshold line
    beginShape();
    for (let px = x - w/2; px < x + w/2; px += 5) {
      let py = y + noise(px * 0.01, i * 0.1) * 20 - 10;
      curveVertex(px, py);
    }
    endShape();
  }

  pop();
}

function drawInnerLight() {
  // Soft glowing core - consciousness/essence
  push();
  translate(width/2, height * 0.38);

  // Multiple soft ellipses
  for (let i = 30; i > 0; i--) {
    let size = i * 15;
    let alpha = map(i, 30, 0, 2, 25);

    // Warm inner glow
    let r = map(i, 30, 0, 80, 220);
    let g = map(i, 30, 0, 70, 190);
    let b = map(i, 30, 0, 90, 170);

    noStroke();
    fill(r, g, b, alpha);

    let wobbleX = noise(i * 0.2) * 20 - 10;
    let wobbleY = noise(i * 0.2 + 50) * 20 - 10;

    ellipse(wobbleX, wobbleY, size * 1.2, size * 1.5);
  }

  // Small bright points within - like stars or memories
  for (let i = 0; i < 30; i++) {
    let angle = random(TWO_PI);
    let dist = random(20, 100);
    let x = cos(angle) * dist;
    let y = sin(angle) * dist * 1.2;

    fill(240, 220, 210, random(30, 80));
    noStroke();
    ellipse(x, y, random(2, 6), random(2, 6));
  }

  pop();
}

function drawMist() {
  // Soft atmospheric layers
  for (let y = height; y > 0; y -= 2) {
    let alpha = map(y, height, 0, 15, 2);
    let noiseVal = noise(y * 0.003);

    stroke(20, 25, 35, alpha * noiseVal);
    strokeWeight(2);

    for (let x = 0; x < width; x += 20) {
      let localNoise = noise(x * 0.005, y * 0.005);
      if (localNoise > 0.45) {
        let len = localNoise * 30;
        line(x, y, x + len, y);
      }
    }
  }

  // Soft vignette
  for (let i = 0; i < 50; i++) {
    let alpha = map(i, 0, 50, 8, 0);
    noFill();
    stroke(5, 5, 12, alpha);
    strokeWeight(20);

    let offset = i * 15;
    rect(offset, offset, width - offset * 2, height - offset * 2, 100);
  }

  // Subtle grain texture
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let grain = random(-8, 8);
    pixels[i] += grain;
    pixels[i + 1] += grain;
    pixels[i + 2] += grain;
  }
  updatePixels();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep gradient background - from deep blue-black to warmer horizon
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c1 = color(8, 12, 25);
    let c2 = color(45, 35, 50);
    let c = lerpColor(c1, c2, inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Subtle texture overlay
  for (let i = 0; i < 50000; i++) {
    let x = random(width);
    let y = random(height);
    let alpha = random(5, 15);
    stroke(255, 245, 230, alpha);
    point(x, y);
  }

  // The threshold line - a subtle horizon
  let horizonY = height * 0.72;
  for (let x = 0; x < width; x++) {
    let y = horizonY + noise(x * 0.005) * 30 - 15;
    let alpha = map(abs(x - width/2), 0, width/2, 60, 10);
    stroke(180, 150, 130, alpha);
    strokeWeight(1);
    point(x, y);
  }

  // Soft glow behind figure
  noStroke();
  for (let r = 500; r > 0; r -= 5) {
    let alpha = map(r, 500, 0, 0, 25);
    fill(200, 180, 160, alpha);
    ellipse(width/2, height * 0.55, r * 1.2, r * 1.5);
  }

  // Define human silhouette parameters
  let figureX = width / 2;
  let figureBaseY = height * 0.75;
  let figureHeight = height * 0.45;
  let figureWidth = width * 0.15;

  // Particle system for the figure
  let particles = [];

  // Generate particles that form the figure
  for (let i = 0; i < 15000; i++) {
    // Create body shape using parametric curves
    let t = random(1);
    let bodyY = figureBaseY - t * figureHeight;

    // Width varies along body
    let widthAtY;
    let relativeY = t;

    if (relativeY < 0.15) {
      // Legs
      widthAtY = figureWidth * 0.3;
    } else if (relativeY < 0.45) {
      // Torso
      widthAtY = figureWidth * map(relativeY, 0.15, 0.45, 0.4, 0.6);
    } else if (relativeY < 0.55) {
      // Shoulders
      widthAtY = figureWidth * 0.65;
    } else if (relativeY < 0.65) {
      // Neck
      widthAtY = figureWidth * 0.2;
    } else {
      // Head
      let headT = map(relativeY, 0.65, 1, 0, PI);
      widthAtY = figureWidth * 0.35 * sin(headT);
    }

    let bodyX = figureX + random(-widthAtY, widthAtY);

    // Calculate dissolution factor - higher = more dissolved
    let dissolution = map(relativeY, 0, 1, 0, 1);
    dissolution = pow(dissolution, 1.5);

    // Add noise-based displacement that increases with height
    let noiseScale = 0.008;
    let noiseDisplacement = dissolution * 300;
    let nx = noise(bodyX * noiseScale, bodyY * noiseScale, 0) - 0.5;
    let ny = noise(bodyX * noiseScale, bodyY * noiseScale, 100) - 0.5;

    let finalX = bodyX + nx * noiseDisplacement * 2;
    let finalY = bodyY + ny * noiseDisplacement - dissolution * random(100);

    // Some particles escape upward
    if (random(1) < dissolution * 0.5) {
      finalY -= random(50, 400) * dissolution;
      finalX += random(-150, 150) * dissolution;
    }

    particles.push({
      x: finalX,
      y: finalY,
      size: random(1, 4) * (1 - dissolution * 0.5),
      alpha: map(dissolution, 0, 1, 255, 50) * random(0.5, 1),
      dissolution: dissolution
    });
  }

  // Draw particles
  noStroke();
  for (let p of particles) {
    // Color shifts from warm earth tones at bottom to cool ethereal at top
    let r = lerp(180, 220, p.dissolution) + random(-20, 20);
    let g = lerp(140, 200, p.dissolution) + random(-20, 20);
    let b = lerp(120, 210, p.dissolution) + random(-20, 20);

    fill(r, g, b, p.alpha);
    ellipse(p.x, p.y, p.size, p.size);
  }

  // Rising particles above the figure - souls/essence ascending
  for (let i = 0; i < 3000; i++) {
    let x = figureX + random(-250, 250);
    let y = random(height * 0.1, height * 0.4);

    // Cluster toward center column
    let distFromCenter = abs(x - figureX);
    if (random(1) > map(distFromCenter, 0, 250, 1, 0.1)) continue;

    let size = random(0.5, 3);
    let alpha = random(30, 120);

    // Ethereal colors
    let c = random(1);
    let r, g, b;
    if (c < 0.5) {
      r = 220 + random(-20, 20);
      g = 210 + random(-20, 20);
      b = 200 + random(-10, 30);
    } else {
      r = 200 + random(-20, 20);
      g = 190 + random(-20, 30);
      b = 220 + random(-10, 20);
    }

    fill(r, g, b, alpha);
    ellipse(x, y, size, size);
  }

  // Subtle ground shadow
  for (let i = 0; i < 2000; i++) {
    let x = figureX + random(-200, 200);
    let y = figureBaseY + random(10, 100);
    let alpha = map(y, figureBaseY, figureBaseY + 100, 40, 0);
    alpha *= map(abs(x - figureX), 0, 200, 1, 0);
    fill(20, 15, 25, alpha);
    ellipse(x, y, random(2, 6), random(1, 3));
  }

  // Delicate light rays from above
  stroke(255, 250, 240, 8);
  strokeWeight(1);
  for (let i = 0; i < 50; i++) {
    let x1 = figureX + random(-300, 300);
    let y1 = 0;
    let x2 = figureX + random(-100, 100);
    let y2 = height * 0.5 + random(-100, 100);

    for (let j = 0; j < 20; j++) {
      let t = j / 20;
      let x = lerp(x1, x2, t);
      let y = lerp(y1, y2, t);
      point(x + random(-2, 2), y);
    }
  }

  // Distant floating particles - like stars or distant souls
  for (let i = 0; i < 500; i++) {
    let x = random(width);
    let y = random(height * 0.5);
    let size = random(1, 2.5);
    let alpha = random(40, 100);

    fill(240, 235, 255, alpha);
    noStroke();
    ellipse(x, y, size, size);
  }

  // Final atmospheric haze
  for (let y = 0; y < height; y += 2) {
    let alpha = 3;
    if (y > height * 0.6) {
      alpha = map(y, height * 0.6, height, 3, 15);
    }
    fill(60, 50, 70, alpha);
    noStroke();
    rect(0, y, width, 2);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep background gradient - from dark earth to void
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let c = lerpColor(color(15, 12, 20), color(5, 5, 10), t);
    stroke(c);
    line(0, y, width, y);
  }

  // Atmospheric mist layers
  noStroke();
  for (let i = 0; i < 50; i++) {
    let y = map(i, 0, 50, height * 0.3, height);
    let alpha = map(i, 0, 50, 5, 20);
    fill(40, 35, 50, alpha);
    ellipse(width/2 + noise(i * 0.5) * 400 - 200, y, 
            noise(i * 0.3 + 100) * 800 + 400, 
            noise(i * 0.3 + 200) * 200 + 100);
  }

  // The threshold - a luminous horizontal band
  drawThreshold();

  // Dissolving forms rising/falling
  drawDissolvingForms();

  // Particle field - matter returning to void
  drawParticleField();

  // Central figure - partially dissolved
  drawCentralForm();

  // Light rays from beyond
  drawLightRays();

  // Final dust overlay
  drawDust();
}

function drawThreshold() {
  // Horizontal band of light - the boundary
  for (let y = height * 0.35; y < height * 0.5; y++) {
    let distFromCenter = abs(y - height * 0.425) / (height * 0.075);
    let alpha = (1 - distFromCenter) * 60;
    let brightness = 180 + (1 - distFromCenter) * 75;

    for (let x = 0; x < width; x++) {
      let n = noise(x * 0.003, y * 0.005);
      let localAlpha = alpha * n * 1.5;
      stroke(brightness, brightness - 20, brightness + 30, localAlpha);
      point(x, y);
    }
  }

  // Soft glow
  noStroke();
  for (let i = 0; i < 20; i++) {
    let spread = i * 15;
    fill(200, 180, 220, 3);
    ellipse(width/2, height * 0.42, width + spread, 150 + spread);
  }
}

function drawDissolvingForms() {
  // Abstract shapes that lose coherence as they approach the threshold
  for (let i = 0; i < 15; i++) {
    let baseX = noise(i * 10) * width;
    let baseY = noise(i * 10 + 50) * height * 0.5 + height * 0.45;
    let dissolution = map(baseY, height * 0.45, height, 0, 1);
    dissolution = constrain(dissolution, 0, 1);

    // Draw fragmenting shape
    let size = noise(i * 3) * 150 + 50;
    let fragments = floor(map(dissolution, 0, 1, 1, 30));

    for (let f = 0; f < fragments; f++) {
      let fx = baseX + (noise(i, f * 0.5) - 0.5) * size * dissolution * 3;
      let fy = baseY + (noise(i + 100, f * 0.5) - 0.5) * size * dissolution * 2;
      let fsize = size / fragments * (1 + noise(f) * 2);

      let alpha = map(dissolution, 0, 1, 80, 10);
      let hue = noise(i * 0.5, f * 0.1) * 40 + 20;
      fill(hue, hue - 10, hue + 20, alpha);
      noStroke();

      beginShape();
      for (let a = 0; a < TWO_PI; a += PI/4) {
        let r = fsize * (0.5 + noise(cos(a) + i, sin(a) + f) * 0.5);
        vertex(fx + cos(a) * r, fy + sin(a) * r);
      }
      endShape(CLOSE);
    }
  }
}

function drawParticleField() {
  // Particles dispersing - matter returning to void
  for (let i = 0; i < 3000; i++) {
    let x = noise(i * 0.1) * width;
    let y = noise(i * 0.1 + 1000) * height;

    let distFromThreshold = abs(y - height * 0.42) / height;
    let size = noise(i * 0.5) * 4 + 1;

    // Particles are denser near threshold, dispersing away
    let density = 1 - distFromThreshold * 1.5;
    if (random() > density) continue;

    let brightness = map(y, 0, height, 220, 40);
    let alpha = map(distFromThreshold, 0, 0.5, 150, 20);

    // Color shift
    let r = brightness + noise(i) * 30 - 15;
    let g = brightness - 20 + noise(i + 500) * 20;
    let b = brightness + 20;

    noStroke();
    fill(r, g, b, alpha);
    ellipse(x, y, size, size);
  }
}

function drawCentralForm() {
  // A figure at the threshold - half present, half dissolved
  let centerX = width * 0.5;
  let centerY = height * 0.55;

  // Lower body - more solid
  for (let y = centerY + 100; y < centerY + 400; y++) {
    let progress = (y - centerY - 100) / 300;
    let solidness = progress * 0.8 + 0.2;

    let bodyWidth = 80 * (1 - progress * 0.3);

    for (let x = centerX - bodyWidth; x < centerX + bodyWidth; x++) {
      let distFromCenter = abs(x - centerX) / bodyWidth;
      let n = noise(x * 0.02, y * 0.02);

      if (n > 0.3 + (1 - solidness) * 0.5) {
        let brightness = 60 + (1 - distFromCenter) * 40;
        let alpha = solidness * 200 * (1 - distFromCenter * 0.5);
        stroke(brightness, brightness - 10, brightness + 15, alpha);
        point(x, y);
      }
    }
  }

  // Upper body - dissolving into light
  for (let y = centerY - 150; y < centerY + 100; y++) {
    let progress = map(y, centerY - 150, centerY + 100, 0, 1);
    let dissolution = 1 - progress;

    let bodyWidth = 60 + progress * 30;

    for (let x = centerX - bodyWidth * 2; x < centerX + bodyWidth * 2; x++) {
      let distFromCenter = abs(x - centerX) / bodyWidth;
      if (distFromCenter > 1 + dissolution * 2) continue;

      let n = noise(x * 0.03, y * 0.03);
      let threshold = dissolution * 0.7;

      if (n > threshold && random() > dissolution * 0.5) {
        let brightness = map(dissolution, 0, 1, 70, 200);
        let alpha = map(dissolution, 0, 1, 180, 30) * (1 - distFromCenter * 0.3);

        let scatter = dissolution * 50;
        let px = x + (noise(x * 0.1, y * 0.1) - 0.5) * scatter;
        let py = y + (noise(x * 0.1 + 100, y * 0.1) - 0.5) * scatter;

        stroke(brightness + 20, brightness, brightness + 40, alpha);
        strokeWeight(1 + dissolution * 2);
        point(px, py);
      }
    }
  }
  strokeWeight(1);

  // Head region - mostly dispersed light
  for (let i = 0; i < 500; i++) {
    let angle = noise(i) * TWO_PI * 2;
    let dist = noise(i + 100) * 120;
    let x = centerX + cos(angle) * dist + (noise(i * 0.5) - 0.5) * 100;
    let y = centerY - 180 + sin(angle) * dist * 0.6 + (noise(i * 0.5 + 50) - 0.5) * 80;

    let size = noise(i * 0.3) * 8 + 2;
    let alpha = map(dist, 0, 120, 100, 20);

    noStroke();
    fill(220, 200, 230, alpha);
    ellipse(x, y, size, size);
  }
}

function drawLightRays() {
  // Subtle rays emanating from above the threshold
  for (let i = 0; i < 30; i++) {
    let x = noise(i * 7) * width;
    let startY = 0;
    let endY = height * 0.5 + noise(i * 3) * height * 0.3;

    let rayWidth = noise(i * 2) * 50 + 10;

    for (let y = startY; y < endY; y++) {
      let progress = y / endY;
      let alpha = (1 - progress) * 15 * noise(i);
      let xOffset = (noise(y * 0.002, i) - 0.5) * 100;

      stroke(230, 220, 250, alpha);
      strokeWeight(rayWidth * (1 - progress * 0.5));
      point(x + xOffset, y);
    }
  }
  strokeWeight(1);
}

function drawDust() {
  // Final overlay of cosmic dust
  for (let i = 0; i < 5000; i++) {
    let x = random(width);
    let y = random(height);
    let size = random(0.5, 2);
    let alpha = random(10, 40);

    // Slight warm/cool variation
    let temp = noise(x * 0.01, y * 0.01);
    let r = 150 + temp * 50;
    let g = 140 + temp * 30;
    let b = 160 + (1 - temp) * 40;

    noStroke();
    fill(r, g, b, alpha);
    ellipse(x, y, size, size);
  }

  // Vignette
  for (let i = 0; i < 50; i++) {
    let alpha = map(i, 0, 50, 0, 100);
    noFill();
    stroke(5, 5, 15, alpha);
    strokeWeight(20);
    let inset = i * 15;
    rect(inset, inset, width - inset * 2, height - inset * 2, 100);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep gradient background - from warm life to cool void
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(45, 35, 50), color(8, 10, 18), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Subtle cosmic dust in background
  noStroke();
  for (let i = 0; i < 3000; i++) {
    let x = random(width);
    let y = random(height);
    let alpha = random(5, 25);
    let size = random(0.5, 2);
    fill(255, 250, 240, alpha);
    ellipse(x, y, size, size);
  }

  // The threshold - a soft horizontal glow
  let thresholdY = height * 0.55;
  for (let i = 0; i < 200; i++) {
    let spread = map(i, 0, 200, 300, 0);
    let alpha = map(i, 0, 200, 1, 8);
    stroke(180, 160, 140, alpha);
    strokeWeight(1);
    let yOff = map(noise(i * 0.02), 0, 1, -20, 20);
    line(0, thresholdY + spread + yOff, width, thresholdY + spread + yOff);
    line(0, thresholdY - spread + yOff, width, thresholdY - spread + yOff);
  }

  // Figure emerging/dissolving - positioned at threshold
  let figureX = width * 0.5;
  let figureY = height * 0.48;

  // Draw the dissolving figure from bottom to top
  // More solid at bottom, dispersing toward top

  // Core figure silhouette with particle dissolution
  for (let i = 0; i < 50000; i++) {
    // Figure shape using mathematical form
    let t = random(-PI, 0);
    let figureWidth = sin(t) * 180 * (1 + 0.3 * sin(t * 3));
    let figureHeight = -t / PI * 600;

    let baseX = figureX + random(-figureWidth, figureWidth) * 0.5;
    let baseY = figureY + figureHeight;

    // Calculate dissolution based on height
    let dissolution = map(baseY, figureY + 600, figureY - 200, 0, 1);
    dissolution = constrain(dissolution, 0, 1);
    dissolution = pow(dissolution, 1.5);

    // Displace particles more as they rise
    let displaceX = (noise(baseX * 0.005, baseY * 0.005) - 0.5) * dissolution * 400;
    let displaceY = (noise(baseX * 0.005 + 100, baseY * 0.005) - 0.5) * dissolution * 300 - dissolution * 150;

    let finalX = baseX + displaceX;
    let finalY = baseY + displaceY;

    // Skip particles that have fully dissolved
    if (random() > 1 - dissolution * 0.7 && dissolution > 0.5) continue;

    // Color transitions from warm (life) to cool (void)
    let warmth = map(dissolution, 0, 1, 1, 0);
    let r = lerp(60, 200, warmth) + random(-20, 20);
    let g = lerp(70, 150, warmth) + random(-20, 20);
    let b = lerp(90, 120, warmth) + random(-10, 10);
    let alpha = map(dissolution, 0, 1, 180, 30) * random(0.5, 1);

    fill(r, g, b, alpha);
    noStroke();
    let size = map(dissolution, 0, 1, 2.5, 1) * random(0.5, 1.5);
    ellipse(finalX, finalY, size, size);
  }

  // Head area - more defined but still dissolving
  let headY = figureY - 180;
  let headRadius = 70;

  for (let i = 0; i < 15000; i++) {
    let angle = random(TWO_PI);
    let r = random(headRadius);
    let baseX = figureX + cos(angle) * r * (1 + 0.1 * sin(angle * 2));
    let baseY = headY + sin(angle) * r * 1.2;

    let upwardDissolution = map(baseY, headY + headRadius, headY - headRadius, 0.3, 1);
    upwardDissolution = constrain(upwardDissolution, 0, 1);

    let displaceX = (noise(baseX * 0.01, baseY * 0.01 + 500) - 0.5) * upwardDissolution * 250;
    let displaceY = (noise(baseX * 0.01 + 200, baseY * 0.01 + 500) - 0.5) * upwardDissolution * 200 - upwardDissolution * 200;

    let finalX = baseX + displaceX;
    let finalY = baseY + displaceY;

    if (random() > 1 - upwardDissolution * 0.6 && upwardDissolution > 0.6) continue;

    let warmth = map(upwardDissolution, 0, 1, 0.8, 0);
    let red = lerp(70, 190, warmth) + random(-15, 15);
    let grn = lerp(75, 140, warmth) + random(-15, 15);
    let blu = lerp(95, 115, warmth) + random(-10, 10);
    let alpha = map(upwardDissolution, 0, 1, 160, 20);

    fill(red, grn, blu, alpha);
    noStroke();
    ellipse(finalX, finalY, random(1, 2.5), random(1, 2.5));
  }

  // Particles streaming upward into the void
  for (let i = 0; i < 2000; i++) {
    let startX = figureX + random(-100, 100);
    let startY = headY - headRadius + random(-50, 0);

    let streamLength = random(50, 400);
    let drift = (noise(i * 0.1) - 0.5) * 300;

    let endX = startX + drift;
    let endY = startY - streamLength;

    let steps = floor(streamLength / 3);
    for (let j = 0; j < steps; j++) {
      let t = j / steps;
      let x = lerp(startX, endX, t) + (noise(i + j * 0.05) - 0.5) * 50;
      let y = lerp(startY, endY, t);

      let alpha = map(t, 0, 1, 80, 0) * random(0.3, 1);
      fill(150, 140, 160, alpha);
      noStroke();
      ellipse(x, y, random(0.5, 2), random(0.5, 2));
    }
  }

  // Soft inner glow where figure was most present
  for (let i = 0; i < 100; i++) {
    let glowRadius = map(i, 0, 100, 400, 10);
    let alpha = map(i, 0, 100, 1, 3);
    noFill();
    stroke(200, 180, 160, alpha);
    strokeWeight(4);
    ellipse(figureX, figureY + 100, glowRadius, glowRadius * 1.8);
  }

  // Remnant warmth - embers of what was
  for (let i = 0; i < 500; i++) {
    let x = figureX + random(-150, 150);
    let y = figureY + random(200, 500);
    let ember = noise(x * 0.01, y * 0.01);
    if (ember > 0.6) {
      fill(220, 160, 100, random(20, 60));
      noStroke();
      ellipse(x, y, random(2, 5), random(2, 5));
    }
  }

  // Void particles - what awaits
  for (let i = 0; i < 1500; i++) {
    let x = random(width);
    let y = random(0, height * 0.3);
    let depth = noise(x * 0.003, y * 0.003);
    if (depth > 0.4) {
      fill(100, 110, 140, random(10, 40));
      noStroke();
      ellipse(x, y, random(1, 4), random(1, 4));
    }
  }

  // Final atmospheric haze
  for (let y = 0; y < height; y += 2) {
    let alpha = 3 + 5 * noise(y * 0.005);
    stroke(20, 25, 40, alpha);
    strokeWeight(2);
    for (let x = 0; x < width; x += 10) {
      let drift = noise(x * 0.002, y * 0.002) * 20;
      point(x + drift, y);
    }
  }

  // Soft vignette
  for (let i = 0; i < 150; i++) {
    noFill();
    let alpha = map(i, 0, 150, 15, 0);
    stroke(5, 5, 10, alpha);
    strokeWeight(10);
    let inset = i * 5;
    rect(inset, inset, width - inset * 2, height - inset * 2, 100);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Dark gradient background
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(10, 8, 20), color(40, 25, 45), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Central light portal
  drawPortal();

  // Mist layers
  drawMist();

  // Silhouette figure
  drawFigure();

  // Ravens
  drawRavens();

  // Wilted flowers foreground
  drawFlowers();

  // Floating particles / souls
  drawParticles();

  // Vignette
  drawVignette();
}

function drawPortal() {
  push();
  translate(width / 2, height * 0.4);
  noStroke();

  for (let i = 80; i > 0; i--) {
    let alpha = map(i, 80, 0, 5, 60);
    let size = map(i, 80, 0, 900, 50);
    let golden = color(255, 220, 150, alpha);
    fill(golden);
    ellipse(0, 0, size * 0.7, size * 1.3);
  }

  // Inner bright core
  for (let i = 30; i > 0; i--) {
    let alpha = map(i, 30, 0, 20, 255);
    fill(255, 250, 240, alpha);
    ellipse(0, 0, i * 3, i * 5);
  }
  pop();
}

function drawMist() {
  noStroke();
  for (let layer = 0; layer < 5; layer++) {
    for (let i = 0; i < 200; i++) {
      let x = random(width);
      let y = random(height * 0.5, height * 0.8);
      let s = random(100, 400);
      let n = noise(x * 0.003, y * 0.003, layer);
      let alpha = n * 25;
      fill(180, 170, 190, alpha);
      ellipse(x, y, s, s * 0.3);
    }
  }
}

function drawFigure() {
  push();
  translate(width / 2, height * 0.55);
  fill(0, 0, 0, 200);
  noStroke();

  // Head
  ellipse(0, -180, 70, 85);

  // Body / cloak
  beginShape();
  vertex(-60, -140);
  bezierVertex(-100, -50, -120, 100, -90, 280);
  bezierVertex(-50, 300, 50, 300, 90, 280);
  bezierVertex(120, 100, 100, -50, 60, -140);
  endShape(CLOSE);

  // Flowing cloak edges
  for (let i = 0; i < 8; i++) {
    let xOff = random(-80, 80);
    let yStart = random(100, 250);
    beginShape();
    noFill();
    stroke(0, 0, 0, 150);
    strokeWeight(random(2, 6));
    vertex(xOff, yStart);
    bezierVertex(xOff + random(-40, 40), yStart + 50, 
                 xOff + random(-60, 60), yStart + 100,
                 xOff + random(-50, 50), yStart + 150);
    endShape();
  }
  pop();
}

function drawRavens() {
  let positions = [
    {x: 300, y: 350, s: 0.8},
    {x: 1300, y: 400, s: 0.7},
    {x: 450, y: 550, s: 0.5},
    {x: 1150, y: 300, s: 0.6}
  ];

  for (let p of positions) {
    drawRaven(p.x, p.y, p.s);
  }
}

function drawRaven(x, y, s) {
  push();
  translate(x, y);
  scale(s);
  fill(5, 5, 15);
  noStroke();

  // Body
  ellipse(0, 0, 60, 35);

  // Head
  ellipse(25, -10, 30, 25);

  // Beak
  triangle(40, -10, 55, -8, 40, -5);

  // Wings
  beginShape();
  vertex(-10, -5);
  bezierVertex(-50, -60, -100, -40, -80, 10);
  vertex(-10, 5);
  endShape(CLOSE);

  beginShape();
  vertex(-10, 5);
  bezierVertex(-60, 50, -90, 30, -70, -5);
  vertex(-10, -5);
  endShape(CLOSE);

  // Tail
  triangle(-30, 0, -60, 15, -55, -10);

  pop();
}

function drawFlowers() {
  // Ground
  noStroke();
  for (let i = 0; i < 100; i++) {
    let x = random(width);
    let y = random(height * 0.85, height);
    fill(20, 15, 25, 200);
    ellipse(x, y, random(50, 200), random(20, 40));
  }

  // Wilted flowers
  for (let i = 0; i < 25; i++) {
    let x = random(100, width - 100);
    let y = random(height * 0.82, height * 0.95);
    drawWiltedFlower(x, y, random(0.5, 1.2));
  }
}

function drawWiltedFlower(x, y, s) {
  push();
  translate(x, y);
  scale(s);

  // Stem
  stroke(40, 50, 35);
  strokeWeight(3);
  noFill();
  let bend = random(-30, 30);
  bezier(0, 0, bend, -40, bend * 1.5, -80, bend + random(-20, 20), -120);

  // Drooping flower head
  let headX = bend + random(-20, 20);
  let headY = -120;

  noStroke();
  // Petals
  let petalColor = random() > 0.5 ? 
    color(80, 40, 50, 180) : color(70, 60, 80, 180);
  fill(petalColor);

  for (let p = 0; p < 5; p++) {
    push();
    translate(headX, headY);
    rotate(p * TWO_PI / 5 + PI * 0.7);
    ellipse(12, 0, 25, 12);
    pop();
  }

  // Center
  fill(50, 35, 30);
  ellipse(headX, headY, 15, 12);

  pop();
}

function drawParticles() {
  noStroke();
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = random(height);
    let distToCenter = dist(x, y, width/2, height * 0.4);

    if (distToCenter < 400) {
      let alpha = map(distToCenter, 0, 400, 200, 20);
      let size = map(distToCenter, 0, 400, 6, 2);
      fill(255, 240, 200, alpha);
      ellipse(x, y, size + noise(x * 0.01, y * 0.01) * 4);
    } else if (random() > 0.7) {
      fill(200, 180, 220, random(20, 60));
      ellipse(x, y, random(1, 4));
    }
  }
}

function drawVignette() {
  noFill();
  for (let i = 0; i < 150; i++) {
    let alpha = map(i, 0, 150, 0, 180);
    stroke(5, 3, 10, alpha);
    strokeWeight(10);
    let offset = i * 5;
    rect(-offset, -offset, width + offset * 2, height + offset * 2, 100);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Background gradient - earth to light
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c1 = color(45, 25, 35);
    let c2 = color(180, 140, 80);
    let c = lerpColor(c1, c2, pow(inter, 0.7));
    stroke(c);
    line(0, y, width, y);
  }

  // Atmospheric mist layers
  noStroke();
  for (let i = 0; i < 500; i++) {
    let x = random(width);
    let y = random(height * 0.3, height);
    let s = random(100, 400);
    let alpha = random(5, 20);
    let brightness = map(y, height * 0.3, height, 60, 200);
    fill(brightness, brightness - 20, brightness - 40, alpha);
    ellipse(x, y, s, s * 0.4);
  }

  // Central light portal
  let portalX = width / 2;
  let portalY = height * 0.35;
  for (let r = 600; r > 0; r -= 3) {
    let alpha = map(r, 600, 0, 0, 180);
    let gold = map(r, 600, 0, 150, 255);
    fill(gold, gold - 30, gold - 100, alpha);
    noStroke();
    ellipse(portalX, portalY, r, r * 1.8);
  }

  // Light rays
  for (let i = 0; i < 40; i++) {
    let angle = map(i, 0, 40, -PI * 0.4, PI * 0.4) + PI / 2;
    let len = random(400, 900);
    for (let j = 0; j < len; j += 2) {
      let x = portalX + cos(angle) * j;
      let y = portalY + sin(angle) * j;
      let alpha = map(j, 0, len, 60, 0) * noise(i * 0.5, j * 0.01);
      fill(255, 230, 180, alpha);
      noStroke();
      ellipse(x, y, random(3, 8), random(3, 8));
    }
  }

  // Dark trees/forest silhouettes on sides
  fill(20, 15, 25);
  noStroke();
  for (let i = 0; i < 15; i++) {
    let x = i < 7 ? random(-50, 350) : random(width - 350, width + 50);
    let h = random(800, 1600);
    let w = random(40, 120);
    drawTree(x, height, w, h);
  }

  // Ground - dark earth
  for (let y = height * 0.75; y < height; y++) {
    for (let x = 0; x < width; x += 3) {
      let n = noise(x * 0.005, y * 0.01);
      let darkness = map(y, height * 0.75, height, 50, 20);
      let c = color(darkness + n * 30, darkness - 5 + n * 20, darkness - 10 + n * 15, 200);
      fill(c);
      noStroke();
      rect(x, y, 4, 4);
    }
  }

  // Path leading to light
  beginShape();
  fill(60, 50, 45, 180);
  noStroke();
  vertex(width * 0.35, height);
  vertex(width * 0.65, height);
  vertex(width * 0.52, height * 0.6);
  vertex(width * 0.48, height * 0.6);
  endShape(CLOSE);

  // Figure silhouette
  drawFigure(width / 2, height * 0.65);

  // Ravens
  drawRaven(300, 400, 0.8);
  drawRaven(1250, 350, -0.6);
  drawRaven(450, 550, 0.4);

  // Floating particles - souls/dust
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = random(height * 0.2, height * 0.8);
    let s = random(1, 4);
    let distToCenter = dist(x, y, portalX, portalY);
    let alpha = map(distToCenter, 0, 500, 200, 20);
    fill(255, 240, 200, alpha);
    noStroke();
    ellipse(x, y, s, s);
  }

  // Veil texture overlay
  for (let i = 0; i < 2000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.01, y * 0.01);
    fill(255, 250, 240, n * 15);
    noStroke();
    ellipse(x, y, random(2, 6), random(2, 6));
  }
}

function drawTree(x, baseY, w, h) {
  fill(15, 10, 20);
  beginShape();
  vertex(x - w / 2, baseY);
  for (let y = baseY; y > baseY - h; y -= 20) {
    let wobble = noise(x * 0.01, y * 0.01) * 30 - 15;
    let taper = map(y, baseY, baseY - h, w / 2, 5);
    vertex(x - taper + wobble, y);
  }
  vertex(x, baseY - h - random(50));
  for (let y = baseY - h; y < baseY; y += 20) {
    let wobble = noise(x * 0.01 + 100, y * 0.01) * 30 - 15;
    let taper = map(y, baseY, baseY - h, w / 2, 5);
    vertex(x + taper + wobble, y);
  }
  vertex(x + w / 2, baseY);
  endShape(CLOSE);

  // Branches
  for (let i = 0; i < 8; i++) {
    let branchY = baseY - random(h * 0.3, h * 0.9);
    let branchLen = random(50, 200);
    let dir = random() > 0.5 ? 1 : -1;
    stroke(15, 10, 20);
    strokeWeight(random(2, 6));
    let bx = x + dir * random(10, 30);
    line(bx, branchY, bx + dir * branchLen, branchY - random(-30, 50));
  }
  noStroke();
}

function drawFigure(x, y) {
  fill(10, 5, 15, 230);
  noStroke();

  // Cloak body
  beginShape();
  vertex(x, y - 180);
  bezierVertex(x - 60, y - 150, x - 80, y - 50, x - 70, y + 150);
  vertex(x + 70, y + 150);
  bezierVertex(x + 80, y - 50, x + 60, y - 150, x, y - 180);
  endShape(CLOSE);

  // Head
  ellipse(x, y - 200, 50, 60);

  // Cloak folds
  stroke(5, 0, 10, 100);
  strokeWeight(2);
  for (let i = 0; i < 8; i++) {
    let fx = x + random(-50, 50);
    let fy1 = y - random(100, 150);
    let fy2 = y + random(50, 140);
    line(fx, fy1, fx + random(-20, 20), fy2);
  }
  noStroke();

  // Ethereal glow around figure
  for (let r = 200; r > 0; r -= 10) {
    fill(255, 220, 150, map(r, 200, 0, 0, 3));
    ellipse(x, y - 50, r, r * 1.5);
  }
}

function drawRaven(x, y, rot) {
  push();
  translate(x, y);
  rotate(rot);
  fill(5, 0, 10);
  noStroke();

  // Body
  ellipse(0, 0, 60, 30);

  // Head
  ellipse(-25, -8, 25, 22);

  // Beak
  triangle(-38, -8, -50, -5, -38, -3);

  // Wings
  beginShape();
  vertex(0, -5);
  vertex(-30, -40);
  vertex(-10, -35);
  vertex(10, -50);
  vertex(20, -30);
  vertex(40, -45);
  vertex(30, -10);
  endShape(CLOSE);

  beginShape();
  vertex(0, 5);
  vertex(-20, 35);
  vertex(0, 30);
  vertex(20, 45);
  vertex(25, 20);
  endShape(CLOSE);

  // Tail
  triangle(30, 0, 70, -10, 70, 10);

  pop();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Sky gradient - dusk
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(15, 10, 35), color(45, 25, 50), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Ground - dark earth
  noStroke();
  for (let y = height * 0.7; y < height; y++) {
    for (let x = 0; x < width; x += 3) {
      let n = noise(x * 0.01, y * 0.01);
      fill(20 + n * 15, 15 + n * 10, 10 + n * 8, 200);
      rect(x, y, 4, 4);
    }
  }

  // Dead tree silhouette
  stroke(15, 10, 20);
  strokeWeight(25);
  drawBranch(300, height * 0.7, -PI/2, 180, 8);

  // Wilting flowers
  for (let i = 0; i < 40; i++) {
    let x = random(100, width - 100);
    let baseY = height * 0.68 + random(50);
    let wiltAngle = random(-0.3, 0.5);
    let stemHeight = random(150, 350);
    let decay = random(0.3, 1);

    drawWiltingFlower(x, baseY, stemHeight, wiltAngle, decay);
  }

  // Rising particles - souls
  for (let i = 0; i < 800; i++) {
    let x = random(width);
    let y = random(height * 0.1, height * 0.75);
    let size = random(2, 8);
    let alpha = map(y, height * 0.75, 0, 50, 255);

    let n = noise(x * 0.005, y * 0.005);
    if (n > 0.4) {
      fill(255, 220, 180, alpha * n);
      noStroke();
      ellipse(x, y, size, size * 1.5);
    }
  }

  // Falling petals
  for (let i = 0; i < 150; i++) {
    let x = random(width);
    let y = random(height * 0.3, height * 0.85);
    drawFallingPetal(x, y, random(TWO_PI), random(0.5, 1));
  }

  // Mist layer
  for (let y = height * 0.6; y < height * 0.8; y += 2) {
    for (let x = 0; x < width; x += 5) {
      let n = noise(x * 0.008, y * 0.01);
      let alpha = map(n, 0, 1, 0, 40);
      fill(200, 180, 210, alpha);
      noStroke();
      ellipse(x, y, random(20, 60), random(10, 30));
    }
  }

  // Moon - death's eye
  let moonX = width * 0.75;
  let moonY = height * 0.15;
  for (let r = 200; r > 0; r -= 2) {
    let alpha = map(r, 200, 0, 5, 80);
    fill(255, 250, 240, alpha);
    noStroke();
    ellipse(moonX, moonY, r, r);
  }
  fill(255, 252, 245);
  ellipse(moonX, moonY, 80, 80);

  // Light rays from moon
  for (let i = 0; i < 20; i++) {
    let angle = random(PI * 0.3, PI * 0.9);
    let len = random(300, 800);
    stroke(255, 250, 240, 10);
    strokeWeight(random(2, 15));
    line(moonX, moonY, moonX + cos(angle) * len, moonY + sin(angle) * len);
  }
}

function drawBranch(x, y, angle, len, weight) {
  if (len < 10) return;

  let endX = x + cos(angle) * len;
  let endY = y + sin(angle) * len;

  strokeWeight(weight);
  stroke(20, 15, 25);
  line(x, y, endX, endY);

  let branches = floor(random(2, 4));
  for (let i = 0; i < branches; i++) {
    let newAngle = angle + random(-0.7, 0.7);
    let newLen = len * random(0.5, 0.75);
    drawBranch(endX, endY, newAngle, newLen, weight * 0.7);
  }
}

function drawWiltingFlower(x, baseY, stemHeight, wiltAngle, decay) {
  // Stem
  stroke(30 + decay * 40, 50 + decay * 30, 20);
  strokeWeight(3);
  noFill();
  beginShape();
  for (let t = 0; t <= 1; t += 0.1) {
    let sx = x + sin(t * PI + wiltAngle) * 20 * t;
    let sy = baseY - t * stemHeight;
    curveVertex(sx, sy);
  }
  endShape();

  // Flower head
  let headX = x + sin(PI + wiltAngle) * 20;
  let headY = baseY - stemHeight;

  push();
  translate(headX, headY);
  rotate(wiltAngle + PI/2);

  // Petals
  let petalCount = floor(random(5, 9));
  for (let i = 0; i < petalCount; i++) {
    let angle = (TWO_PI / petalCount) * i;
    let petalLen = random(15, 35) * decay;
    let droop = (1 - decay) * random(0.5, 1.5);

    push();
    rotate(angle + droop);

    // Petal color - fading
    let r = lerp(80, 200, decay) + random(-20, 20);
    let g = lerp(60, 100, decay) + random(-20, 20);
    let b = lerp(70, 120, decay) + random(-10, 10);

    fill(r, g, b, 180 * decay);
    noStroke();
    ellipse(petalLen/2, 0, petalLen, petalLen * 0.4);
    pop();
  }

  // Center
  fill(50, 40, 30);
  ellipse(0, 0, 12, 12);
  pop();
}

function drawFallingPetal(x, y, rot, opacity) {
  push();
  translate(x, y);
  rotate(rot);

  let r = random(150, 220);
  let g = random(80, 140);
  let b = random(100, 160);

  fill(r, g, b, 150 * opacity);
  noStroke();
  ellipse(0, 0, random(8, 20), random(4, 10));
  pop();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Gradient background - cold to warm
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let c1 = color(15, 20, 35);
    let c2 = color(45, 25, 50);
    let c3 = color(180, 120, 60);
    let c;
    if (t < 0.5) {
      c = lerpColor(c1, c2, t * 2);
    } else {
      c = lerpColor(c2, c3, (t - 0.5) * 2);
    }
    stroke(c);
    line(0, y, width, y);
  }

  // Veil - horizontal mist
  noStroke();
  for (let i = 0; i < 200; i++) {
    let y = height * 0.45 + noise(i * 0.1) * 200 - 100;
    let x = noise(i * 0.2, 100) * width;
    let s = noise(i * 0.15) * 300 + 50;
    fill(255, 240, 220, 8);
    ellipse(x, y, s, s * 0.3);
  }

  // Figure base - dissolving human form
  let figureX = width / 2;
  let figureY = height * 0.65;

  // Body particles - dense at bottom, sparse at top
  for (let i = 0; i < 15000; i++) {
    let angle = noise(i * 0.01) * TWO_PI;
    let baseRadius = noise(i * 0.005, 10) * 150;

    // Body shape modulation
    let yOffset = noise(i * 0.008) * 500 - 100;
    let verticalPos = yOffset / 500;

    // Dissolution factor - more scattered as we go up
    let dissolution = map(verticalPos, -0.2, 1, 0.1, 3);
    dissolution = constrain(dissolution, 0.1, 3);

    let scatter = noise(i * 0.02, 20) * 100 * dissolution;

    // Torso shape
    let bodyWidth = 80 + sin(verticalPos * PI) * 60;
    bodyWidth *= noise(i * 0.01, 5);

    let px = figureX + cos(angle) * bodyWidth + noise(i * 0.03) * scatter - scatter/2;
    let py = figureY + yOffset + noise(i * 0.03, 30) * scatter - scatter/2;

    // Skip if too scattered at top
    if (py < height * 0.2 && random() > 0.3) continue;

    // Color transition - flesh to light
    let colorT = map(py, height * 0.8, height * 0.2, 0, 1);
    colorT = constrain(colorT, 0, 1);

    let fleshColor = color(180, 140, 120);
    let lightColor = color(255, 230, 180);
    let particleColor = lerpColor(fleshColor, lightColor, colorT);

    let alpha = map(dissolution, 0.1, 3, 180, 40);
    particleColor.setAlpha(alpha);

    fill(particleColor);
    let size = map(dissolution, 0.1, 3, 4, 2);
    size *= noise(i * 0.05) + 0.5;
    ellipse(px, py, size, size);
  }

  // Rising particles - souls ascending
  for (let i = 0; i < 800; i++) {
    let t = i / 800;
    let baseX = figureX + noise(i * 0.1) * 300 - 150;
    let baseY = height * 0.5 - t * height * 0.45;

    let drift = noise(i * 0.05, t * 10) * 200 - 100;
    let px = baseX + drift;
    let py = baseY + noise(i * 0.08) * 50;

    let alpha = map(t, 0, 1, 150, 30);
    let size = map(t, 0, 1, 5, 2);

    fill(255, 220, 150, alpha);
    ellipse(px, py, size, size);

    // Glow
    fill(255, 200, 100, alpha * 0.2);
    ellipse(px, py, size * 4, size * 4);
  }

  // Shadow beneath - earthly anchor
  for (let i = 0; i < 3000; i++) {
    let angle = random(TWO_PI);
    let r = random() * random() * 250;
    let px = figureX + cos(angle) * r * 1.5;
    let py = height * 0.85 + sin(angle) * r * 0.3;

    fill(10, 15, 25, 50);
    ellipse(px, py, 8, 3);
  }

  // Light rays from above
  for (let i = 0; i < 30; i++) {
    let x = width * 0.3 + noise(i * 0.5) * width * 0.4;
    let w = noise(i * 0.3, 50) * 40 + 10;

    for (let y = 0; y < height * 0.5; y += 2) {
      let alpha = map(y, 0, height * 0.5, 15, 0);
      alpha *= noise(i * 0.2, y * 0.01);
      fill(255, 240, 200, alpha);
      let xOff = noise(i, y * 0.005) * 100 - 50;
      rect(x + xOff, y, w, 3);
    }
  }

  // Final atmospheric haze
  for (let i = 0; i < 100; i++) {
    let x = random(width);
    let y = random(height * 0.6);
    let s = random(100, 400);
    fill(255, 240, 220, 3);
    ellipse(x, y, s, s * 0.5);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Background gradient - deep blues to golden light
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(10, 15, 35), color(25, 20, 40), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Golden light portal in upper center
  drawPortal();

  // Mist layers
  drawMist();

  // Dead tree with one blooming branch
  drawTree();

  // Silhouette figure walking toward light
  drawFigure();

  // Ravens
  drawRavens();

  // Falling petals and particles
  drawParticles();

  // Vignette
  drawVignette();
}

function drawPortal() {
  push();
  translate(width/2, 400);
  noStroke();

  for (let i = 50; i > 0; i--) {
    let alpha = map(i, 50, 0, 5, 60);
    let size = i * 25;
    fill(255, 220, 150, alpha);
    ellipse(0, 0, size, size * 1.5);
  }

  // Inner bright core
  for (let i = 20; i > 0; i--) {
    let alpha = map(i, 20, 0, 50, 255);
    fill(255, 250, 230, alpha);
    ellipse(0, 0, i * 8, i * 12);
  }
  pop();
}

function drawMist() {
  noStroke();
  for (let layer = 0; layer < 5; layer++) {
    for (let i = 0; i < 100; i++) {
      let x = random(width);
      let y = map(layer, 0, 5, height * 0.5, height * 0.9) + random(-100, 100);
      let w = random(200, 500);
      let h = random(30, 80);
      let alpha = random(5, 20);
      fill(200, 210, 230, alpha);
      ellipse(x, y, w, h);
    }
  }
}

function drawTree() {
  push();
  translate(200, height);
  stroke(20, 15, 25);
  strokeWeight(3);

  // Main trunk
  drawBranch(0, 0, -PI/2, 250, 40, 0);

  // Blooming branch
  push();
  translate(-30, -600);
  drawBloomingBranch();
  pop();

  pop();
}

function drawBranch(x, y, angle, len, weight, depth) {
  if (depth > 8 || len < 10) return;

  let x2 = x + cos(angle) * len;
  let y2 = y + sin(angle) * len;

  stroke(30 + depth * 5, 20 + depth * 3, 35 + depth * 3);
  strokeWeight(weight);
  line(x, y, x2, y2);

  let branches = floor(random(2, 4));
  for (let i = 0; i < branches; i++) {
    let newAngle = angle + random(-0.7, 0.7);
    let newLen = len * random(0.6, 0.8);
    let newWeight = weight * 0.7;
    drawBranch(x2, y2, newAngle, newLen, newWeight, depth + 1);
  }
}

function drawBloomingBranch() {
  stroke(60, 40, 50);
  strokeWeight(8);

  beginShape();
  noFill();
  curveVertex(0, 0);
  curveVertex(0, 0);
  curveVertex(40, -50);
  curveVertex(100, -80);
  curveVertex(160, -70);
  curveVertex(160, -70);
  endShape();

  // Blossoms
  noStroke();
  let blossomPositions = [
    [50, -55], [80, -75], [120, -78], [150, -72], [100, -60], [140, -65]
  ];

  for (let pos of blossomPositions) {
    drawBlossom(pos[0], pos[1]);
  }
}

function drawBlossom(x, y) {
  push();
  translate(x, y);

  for (let i = 0; i < 5; i++) {
    push();
    rotate(i * TWO_PI / 5);
    fill(255, 200, 210, 200);
    ellipse(0, -8, 10, 16);
    pop();
  }

  fill(255, 220, 150);
  ellipse(0, 0, 8, 8);
  pop();
}

function drawFigure() {
  push();
  translate(width/2, 1300);
  noStroke();
  fill(15, 10, 20);

  // Cloak body
  beginShape();
  vertex(-60, 0);
  bezierVertex(-80, 150, -100, 350, -90, 500);
  vertex(90, 500);
  bezierVertex(100, 350, 80, 150, 60, 0);
  endShape(CLOSE);

  // Head
  ellipse(0, -30, 50, 60);

  // Hood
  beginShape();
  vertex(-50, -10);
  bezierVertex(-60, -60, -30, -90, 0, -95);
  bezierVertex(30, -90, 60, -60, 50, -10);
  bezierVertex(30, 10, -30, 10, -50, -10);
  endShape(CLOSE);

  // Flowing fabric details
  stroke(25, 20, 30);
  strokeWeight(2);
  for (let i = 0; i < 8; i++) {
    let sx = map(i, 0, 7, -50, 50);
    beginShape();
    noFill();
    curveVertex(sx, 50);
    curveVertex(sx, 50);
    curveVertex(sx + random(-20, 20), 200);
    curveVertex(sx + random(-30, 30), 400);
    curveVertex(sx + random(-20, 20), 500);
    endShape();
  }
  pop();
}

function drawRavens() {
  drawRaven(1200, 350, 0.8, 0.3);
  drawRaven(1350, 500, 0.6, -0.2);
  drawRaven(300, 600, 0.5, 0.1);
}

function drawRaven(x, y, scale, rot) {
  push();
  translate(x, y);
  rotate(rot);
  scale(scale, scale);
  noStroke();
  fill(10, 8, 15);

  // Body
  ellipse(0, 0, 80, 40);

  // Head
  ellipse(-35, -10, 35, 30);

  // Beak
  triangle(-50, -10, -70, -5, -50, 0);

  // Wings
  beginShape();
  vertex(0, -10);
  bezierVertex(40, -50, 80, -40, 100, -20);
  bezierVertex(70, -15, 40, -5, 0, 10);
  endShape(CLOSE);

  beginShape();
  vertex(0, 10);
  bezierVertex(40, 50, 80, 40, 100, 20);
  bezierVertex(70, 15, 40, 5, 0, -10);
  endShape(CLOSE);

  // Tail
  beginShape();
  vertex(40, 0);
  vertex(80, -10);
  vertex(90, 0);
  vertex(80, 10);
  endShape(CLOSE);

  pop();
}

function drawParticles() {
  noStroke();

  // Golden dust particles
  for (let i = 0; i < 200; i++) {
    let x = random(width);
    let y = random(height * 0.6);
    let size = random(2, 6);
    let alpha = random(50, 200);
    let distFromCenter = dist(x, y, width/2, 400);

    if (distFromCenter < 500) {
      fill(255, 220, 150, alpha);
      ellipse(x, y, size);
    }
  }

  // Falling petals
  for (let i = 0; i < 30; i++) {
    let x = random(50, 400);
    let y = random(200, 1200);

    push();
    translate(x, y);
    rotate(random(TWO_PI));
    fill(255, 200, 210, random(100, 200));
    ellipse(0, 0, random(8, 15), random(5, 10));
    pop();
  }
}

function drawVignette() {
  noStroke();
  for (let i = 0; i < 200; i++) {
    let alpha = map(i, 0, 200, 150, 0);
    fill(5, 5, 15, alpha);

    let thickness = map(i, 0, 200, 300, 0);

    rect(0, 0, thickness, height);
    rect(width - thickness, 0, thickness, height);
    rect(0, 0, width, thickness * 0.7);
    rect(0, height - thickness, width, thickness);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep background gradient - from material world to luminous unknown
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c1 = color(10, 15, 35);
    let c2 = color(45, 25, 50);
    let c = lerpColor(c1, c2, inter);
    stroke(c);
    line(0, y, width, y);
  }

  // The threshold - a vertical luminous membrane
  drawThreshold();

  // The dissolving figure
  drawDissolvingFigure();

  // Floating particles - matter becoming light
  drawParticles();

  // Atmospheric depth
  drawAtmosphere();

  // Light rays from beyond
  drawLightRays();
}

function drawThreshold() {
  noStroke();
  // Soft vertical glow in the center-right
  for (let i = 100; i > 0; i--) {
    let alpha = map(i, 100, 0, 0, 30);
    let xOffset = map(i, 100, 0, 200, 0);
    fill(255, 220, 150, alpha);
    beginShape();
    for (let y = 0; y <= height; y += 20) {
      let nx = noise(y * 0.002, i * 0.1) * 100;
      let x = width * 0.6 + nx - xOffset;
      vertex(x, y);
    }
    for (let y = height; y >= 0; y -= 20) {
      let nx = noise(y * 0.002, i * 0.1) * 100;
      let x = width * 0.6 + nx + xOffset;
      vertex(x, y);
    }
    endShape(CLOSE);
  }
}

function drawDissolvingFigure() {
  // Figure positioned left of threshold, dissolving toward it
  let centerX = width * 0.35;
  let centerY = height * 0.45;

  // Body silhouette made of particles with varying dissolution
  for (let i = 0; i < 15000; i++) {
    // Human form parameters
    let t = random(TWO_PI);
    let bodyY = random(-380, 450);
    let bodySection;

    // Head
    if (bodyY < -280) {
      let headRadius = map(bodyY, -380, -280, 0, 85);
      headRadius = 85 - abs(bodyY + 330) * 0.85;
      bodySection = headRadius * (0.8 + random(0.4));
    }
    // Neck
    else if (bodyY < -220) {
      bodySection = 35 + random(15);
    }
    // Shoulders and torso
    else if (bodyY < 50) {
      let torsoWidth = 140 - abs(bodyY + 85) * 0.3;
      torsoWidth = constrain(torsoWidth, 80, 160);
      bodySection = torsoWidth * (0.7 + random(0.6));
    }
    // Hips and legs
    else {
      let legSpread = map(bodyY, 50, 450, 0, 120);
      let legWidth = 45 - bodyY * 0.03;
      legWidth = max(legWidth, 15);
      // Two legs
      if (random() > 0.5) {
        bodySection = -legSpread/2 + random(-legWidth, legWidth);
      } else {
        bodySection = legSpread/2 + random(-legWidth, legWidth);
      }
      // Convert to radius-like for consistency
      bodySection = abs(bodySection) + random(20);
    }

    let angle = random(TWO_PI);
    let radius = random(bodySection);
    let px = centerX + cos(angle) * radius * 0.6;
    let py = centerY + bodyY;

    // Dissolution increases toward the right (toward threshold)
    let dissolutionFactor = map(px, centerX - 100, width * 0.6, 0, 1);
    dissolutionFactor = constrain(dissolutionFactor, 0, 1);
    dissolutionFactor = pow(dissolutionFactor, 1.5);

    // Particles drift right and scatter as they dissolve
    let drift = dissolutionFactor * random(50, 300);
    let scatter = dissolutionFactor * random(-100, 100);
    px += drift;
    py += scatter * 0.5;

    // Color transition: deep blue flesh to golden light
    let baseColor = color(30, 45, 80);
    let midColor = color(100, 70, 90);
    let lightColor = color(255, 210, 120);

    let particleColor;
    if (dissolutionFactor < 0.5) {
      particleColor = lerpColor(baseColor, midColor, dissolutionFactor * 2);
    } else {
      particleColor = lerpColor(midColor, lightColor, (dissolutionFactor - 0.5) * 2);
    }

    // Size decreases then increases (becoming light particles)
    let size = map(dissolutionFactor, 0, 0.5, 4, 2);
    if (dissolutionFactor > 0.5) {
      size = map(dissolutionFactor, 0.5, 1, 2, 5);
    }
    size *= random(0.5, 1.5);

    // Alpha varies
    let alpha = map(dissolutionFactor, 0, 1, 200, 150);
    alpha *= random(0.6, 1);

    noStroke();
    fill(red(particleColor), green(particleColor), blue(particleColor), alpha);
    ellipse(px, py, size, size);
  }
}

function drawParticles() {
  // Additional floating particles throughout
  for (let i = 0; i < 3000; i++) {
    let x = random(width);
    let y = random(height);

    // More particles near the threshold
    let thresholdDist = abs(x - width * 0.6);
    if (random() > map(thresholdDist, 0, 400, 0.2, 0.9)) {
      // Particle properties based on position
      let rightSide = x > width * 0.6;

      let size = random(1, 4);
      let alpha = random(30, 120);

      if (rightSide) {
        // Golden particles in the light
        fill(255, 220, 150, alpha);
        size *= 1.5;
      } else {
        // Dusty blue particles in the material world
        fill(60, 80, 120, alpha * 0.7);
      }

      noStroke();
      ellipse(x, y, size, size);
    }
  }
}

function drawAtmosphere() {
  // Subtle fog layers
  noStroke();
  for (let i = 0; i < 50; i++) {
    let y = random(height);
    let h = random(100, 400);

    for (let j = 0; j < 20; j++) {
      let alpha = map(j, 0, 20, 8, 0);
      let spread = map(j, 0, 20, 0, h/2);

      let fogColor = y < height/2 ? color(20, 30, 50, alpha) : color(40, 30, 45, alpha);
      fill(fogColor);

      let x1 = noise(y * 0.01, i) * width * 0.3;
      let x2 = width - noise(y * 0.01, i + 100) * width * 0.3;

      beginShape();
      vertex(x1, y - spread);
      bezierVertex(width * 0.3, y - spread * 0.5, width * 0.7, y + spread * 0.5, x2, y + spread);
      vertex(x2, y + spread);
      bezierVertex(width * 0.7, y + spread * 1.5, width * 0.3, y - spread * 0.5, x1, y - spread);
      endShape(CLOSE);
    }
  }
}

function drawLightRays() {
  // Soft rays emanating from beyond the threshold
  for (let i = 0; i < 15; i++) {
    let startY = random(-200, height + 200);
    let startX = width + 100;

    for (let j = 30; j > 0; j--) {
      let alpha = map(j, 30, 0, 0, 15);
      let weight = map(j, 30, 0, 100, 2);

      stroke(255, 230, 180, alpha);
      strokeWeight(weight);

      let endX = width * 0.3 + random(-100, 100);
      let endY = startY + random(-300, 300);

      line(startX, startY, endX, endY);
    }
  }

  // Restore
  noStroke();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep gradient background - from warm life to cold unknown
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c1 = color(45, 20, 40);
    let c2 = color(10, 15, 35);
    let c = lerpColor(c1, c2, inter);
    stroke(c);
    line(0, y, width, y);
  }

  // The veil - a luminous threshold
  noStroke();
  for (let i = 0; i < 200; i++) {
    let x = width / 2 + noise(i * 0.1) * 400 - 200;
    let y = height * 0.45 + noise(i * 0.1 + 100) * 200 - 100;
    let size = noise(i * 0.05) * 300 + 50;
    let alpha = noise(i * 0.03) * 30 + 10;
    fill(200, 180, 220, alpha);
    ellipse(x, y, size, size * 0.3);
  }

  // The dissolving figure - emerging from below
  let figureBaseY = height * 0.7;
  let figureCenterX = width / 2;

  // Body mass - darker, more solid at bottom
  for (let i = 0; i < 8000; i++) {
    let angle = random(TWO_PI);
    let bodyY = figureBaseY + random(-400, 200);
    let widthAtY = map(bodyY, figureBaseY - 400, figureBaseY + 200, 80, 180);
    let dist = random(widthAtY);
    let x = figureCenterX + cos(angle) * dist * 0.6;
    let y = bodyY;

    let dissolution = map(y, figureBaseY + 200, figureBaseY - 500, 0, 1);
    dissolution = constrain(dissolution, 0, 1);

    // Warm colors for the living part
    let r = lerp(180, 80, dissolution) + random(-20, 20);
    let g = lerp(120, 50, dissolution) + random(-15, 15);
    let b = lerp(100, 60, dissolution) + random(-10, 10);
    let alpha = lerp(200, 50, dissolution * dissolution);

    let size = lerp(8, 2, dissolution) + random(2);

    fill(r, g, b, alpha);
    noStroke();
    ellipse(x, y, size, size);
  }

  // Head area
  let headY = figureBaseY - 350;
  for (let i = 0; i < 2000; i++) {
    let angle = random(TWO_PI);
    let dist = random(80);
    let x = figureCenterX + cos(angle) * dist * 0.8;
    let y = headY + sin(angle) * dist * 1.1;

    let r = 160 + random(-30, 30);
    let g = 100 + random(-20, 20);
    let b = 90 + random(-15, 15);

    fill(r, g, b, 150);
    ellipse(x, y, random(3, 7), random(3, 7));
  }

  // The dissolution - particles rising and dispersing
  for (let i = 0; i < 15000; i++) {
    let startX = figureCenterX + random(-100, 100);
    let startY = figureBaseY - 300 + random(-150, 50);

    let progress = random(1);
    let drift = noise(i * 0.01, progress * 2) * 600 - 300;
    let rise = progress * progress * 800;

    let x = startX + drift + noise(i * 0.02) * 200 - 100;
    let y = startY - rise;

    if (y < 0 || y > height) continue;

    // Transition from warm flesh tones to cool ethereal blue-white
    let r = lerp(180, 150, progress) + random(-20, 20);
    let g = lerp(110, 170, progress) + random(-15, 15);
    let b = lerp(90, 220, progress) + random(-10, 30);
    let alpha = lerp(180, 20, progress * progress);

    let size = lerp(5, 1.5, progress) + noise(i) * 2;

    fill(r, g, b, alpha);
    noStroke();
    ellipse(x, y, size, size);
  }

  // Luminous particles above the veil - the transformed
  for (let i = 0; i < 3000; i++) {
    let x = width/2 + (noise(i * 0.1) - 0.5) * 1200;
    let y = noise(i * 0.1 + 50) * height * 0.5;

    let brightness = noise(i * 0.05) * 100 + 155;
    let alpha = noise(i * 0.03) * 60 + 20;

    fill(brightness, brightness + 20, brightness + 40, alpha);
    let size = noise(i * 0.02) * 4 + 1;
    ellipse(x, y, size, size);
  }

  // Ethereal glow at the threshold
  for (let i = 0; i < 100; i++) {
    let x = width/2 + (noise(i * 0.3) - 0.5) * 800;
    let y = height * 0.4 + (noise(i * 0.3 + 10) - 0.5) * 150;
    let size = noise(i * 0.1) * 200 + 100;

    fill(220, 210, 240, 8);
    ellipse(x, y, size, size * 0.4);
  }

  // Fine mist connecting figure to beyond
  stroke(180, 170, 200, 15);
  strokeWeight(0.5);
  for (let i = 0; i < 500; i++) {
    let x1 = figureCenterX + random(-80, 80);
    let y1 = figureBaseY - 400 + random(-50, 50);

    let x2 = x1 + (noise(i * 0.1) - 0.5) * 400;
    let y2 = y1 - random(200, 600);

    let cx1 = lerp(x1, x2, 0.3) + random(-100, 100);
    let cy1 = lerp(y1, y2, 0.3);
    let cx2 = lerp(x1, x2, 0.7) + random(-100, 100);
    let cy2 = lerp(y1, y2, 0.7);

    noFill();
    bezier(x1, y1, cx1, cy1, cx2, cy2, x2, y2);
  }

  // Deep shadow at the base - the earth, the origin
  for (let y = height * 0.85; y < height; y++) {
    let alpha = map(y, height * 0.85, height, 0, 200);
    stroke(15, 10, 20, alpha);
    line(0, y, width, y);
  }

  // Roots or tendrils holding the figure
  stroke(60, 40, 50, 80);
  strokeWeight(2);
  noFill();
  for (let i = 0; i < 30; i++) {
    let startX = figureCenterX + random(-150, 150);
    let startY = figureBaseY + 150;

    beginShape();
    for (let j = 0; j < 10; j++) {
      let t = j / 9;
      let x = startX + noise(i, j * 0.3) * 100 - 50;
      let y = startY + t * 300;
      curveVertex(x, y);
    }
    endShape();
  }

  // Subtle golden light from above - hope or destination
  for (let i = 0; i < 50; i++) {
    let x = width/2 + (noise(i * 0.5) - 0.5) * 600;
    let y = noise(i * 0.5 + 20) * 300;
    let size = noise(i * 0.2) * 150 + 50;

    fill(255, 240, 200, 5);
    ellipse(x, y, size, size);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep gradient background - from warm life to cold infinity
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let c1 = color(45, 20, 40);
    let c2 = color(10, 15, 45);
    let c = lerpColor(c1, c2, t);
    stroke(c);
    line(0, y, width, y);
  }

  // The veil - a subtle threshold
  noStroke();
  for (let i = 0; i < 200; i++) {
    let y = height * 0.45 + sin(i * 0.1) * 50 + random(-30, 30);
    let x = map(i, 0, 200, -50, width + 50);
    fill(255, 255, 255, 3);
    ellipse(x, y, random(100, 300), random(5, 20));
  }

  // Dissolving figure - the being crossing over
  let centerX = width / 2;
  let figureTop = height * 0.25;
  let figureBottom = height * 0.85;

  // Particle system for the figure
  let particles = [];

  // Generate figure shape with particles
  for (let i = 0; i < 15000; i++) {
    let t = random();
    let figureY = lerp(figureTop, figureBottom, t);

    // Figure silhouette width varies with height
    let bodyWidth;
    if (t < 0.1) {
      // Head
      bodyWidth = map(t, 0, 0.1, 20, 80);
    } else if (t < 0.15) {
      // Neck
      bodyWidth = map(t, 0.1, 0.15, 80, 40);
    } else if (t < 0.45) {
      // Torso
      bodyWidth = map(t, 0.15, 0.45, 60, 150);
    } else if (t < 0.5) {
      // Waist
      bodyWidth = map(t, 0.45, 0.5, 150, 80);
    } else {
      // Lower body dissolving
      bodyWidth = map(t, 0.5, 1, 100, 200);
    }

    // Dissolution increases toward bottom
    let dissolution = pow(t, 1.5);
    bodyWidth += dissolution * 200;

    let figureX = centerX + random(-bodyWidth, bodyWidth);

    // Add noise-based displacement
    let noiseVal = noise(figureX * 0.005, figureY * 0.005);
    figureX += (noiseVal - 0.5) * dissolution * 400;
    figureY += (noise(figureX * 0.01, figureY * 0.01) - 0.5) * dissolution * 100;

    particles.push({
      x: figureX,
      y: figureY,
      t: t,
      size: random(2, 8) * (1 + dissolution * 2)
    });
  }

  // Draw particles
  for (let p of particles) {
    let dissolution = pow(p.t, 1.5);

    // Color transition: warm flesh tones to ethereal blue-white
    let warmColor = color(220, 160, 140, 200);
    let midColor = color(180, 140, 180, 150);
    let coldColor = color(150, 180, 220, 80);
    let etherColor = color(200, 220, 255, 30);

    let c;
    if (dissolution < 0.3) {
      c = lerpColor(warmColor, midColor, dissolution / 0.3);
    } else if (dissolution < 0.6) {
      c = lerpColor(midColor, coldColor, (dissolution - 0.3) / 0.3);
    } else {
      c = lerpColor(coldColor, etherColor, (dissolution - 0.6) / 0.4);
    }

    noStroke();
    fill(c);
    ellipse(p.x, p.y, p.size, p.size);
  }

  // Rising particles - soul ascending
  for (let i = 0; i < 3000; i++) {
    let baseY = random(height * 0.3, height * 0.9);
    let drift = map(baseY, height * 0.3, height * 0.9, 300, 50);
    let x = centerX + random(-drift, drift);
    let y = baseY - random(0, 200);

    let alpha = map(y, height * 0.1, height * 0.9, 10, 60);
    let size = random(1, 4);

    fill(255, 250, 240, alpha);
    noStroke();
    ellipse(x, y, size, size);
  }

  // Light rays from above - the beyond
  for (let i = 0; i < 50; i++) {
    let x1 = width / 2 + random(-200, 200);
    let y1 = random(-50, 100);
    let x2 = x1 + random(-400, 400);
    let y2 = height * 0.5 + random(-100, 100);

    for (let j = 0; j < 20; j++) {
      let t = j / 20;
      let x = lerp(x1, x2, t);
      let y = lerp(y1, y2, t);
      let alpha = sin(t * PI) * 15;
      fill(255, 250, 245, alpha);
      noStroke();
      ellipse(x, y, random(20, 60), random(20, 60));
    }
  }

  // Darkness at the edges - the frame of existence
  drawingContext.shadowBlur = 0;
  for (let i = 0; i < 150; i++) {
    let alpha = map(i, 0, 150, 40, 0);
    noFill();
    stroke(5, 5, 20, alpha);
    strokeWeight(10);
    rect(i * 2, i * 2, width - i * 4, height - i * 4, 50);
  }

  // Subtle organic veins - the residue of life
  stroke(60, 40, 50, 30);
  strokeWeight(1);
  for (let i = 0; i < 100; i++) {
    let x = random(width);
    let y = random(height * 0.6, height);
    beginShape();
    noFill();
    for (let j = 0; j < 50; j++) {
      let nx = x + noise(i, j * 0.1) * 100 - 50;
      let ny = y - j * 5;
      vertex(nx, ny);
    }
    endShape();
  }

  // Final luminous points - stars or souls
  for (let i = 0; i < 200; i++) {
    let x = random(width);
    let y = random(height * 0.4);
    let size = random(1, 3);
    let brightness = random(150, 255);
    fill(brightness, brightness, brightness - 20, random(50, 150));
    noStroke();
    ellipse(x, y, size, size);
  }

  // Central glow where figure meets the beyond
  for (let i = 0; i < 100; i++) {
    let radius = 400 - i * 4;
    let alpha = i * 0.3;
    fill(255, 250, 240, alpha);
    noStroke();
    ellipse(centerX, height * 0.35, radius, radius * 0.6);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Background gradient - from deep darkness to golden light
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(10, 45, t);
    let g = lerp(5, 30, t);
    let b = lerp(25, 50, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Golden light emanating from upper right
  for (let i = 0; i < 50; i++) {
    let x = width * 0.75 + random(-200, 200);
    let y = height * 0.15 + random(-150, 150);
    let radius = random(100, 600);
    for (let r = radius; r > 0; r -= 5) {
      let alpha = map(r, 0, radius, 15, 0);
      noStroke();
      fill(255, 200, 100, alpha);
      ellipse(x, y, r, r);
    }
  }

  // Define the dissolving figure - centered lower
  let figureX = width * 0.45;
  let figureY = height * 0.55;

  // Create body shape points
  let bodyPoints = [];

  // Head
  for (let a = 0; a < TWO_PI; a += 0.1) {
    let r = 80;
    let px = figureX + cos(a) * r * 0.9;
    let py = figureY - 350 + sin(a) * r;
    bodyPoints.push({x: px, y: py, part: 'head'});
  }

  // Neck and shoulders
  for (let i = 0; i < 20; i++) {
    let t = i / 20;
    let py = figureY - 270 + t * 50;
    let w = lerp(40, 180, t);
    bodyPoints.push({x: figureX - w, y: py, part: 'body'});
    bodyPoints.push({x: figureX + w, y: py, part: 'body'});
  }

  // Torso
  for (let i = 0; i < 50; i++) {
    let t = i / 50;
    let py = figureY - 220 + t * 300;
    let w = lerp(180, 120, t * t);
    bodyPoints.push({x: figureX - w + random(-10, 10), y: py, part: 'body'});
    bodyPoints.push({x: figureX + w + random(-10, 10), y: py, part: 'body'});
  }

  // Arms
  for (let side = -1; side <= 1; side += 2) {
    for (let i = 0; i < 40; i++) {
      let t = i / 40;
      let px = figureX + side * (150 + t * 120);
      let py = figureY - 180 + t * 200 + sin(t * PI) * 50 * side;
      bodyPoints.push({x: px, y: py, part: 'arm'});
    }
  }

  // Particles emanating from figure - the dissolution
  let particles = [];

  // Dense particles forming the figure
  for (let i = 0; i < 15000; i++) {
    let py = figureY - 450 + random(550);
    let heightRatio = (py - (figureY - 450)) / 550;

    // Figure width at this height
    let w;
    if (py < figureY - 350) {
      w = 0;
    } else if (py < figureY - 270) {
      let t = (py - (figureY - 350)) / 80;
      w = 80 * sin(t * PI);
    } else if (py < figureY - 220) {
      let t = (py - (figureY - 270)) / 50;
      w = lerp(40, 180, t);
    } else {
      let t = (py - (figureY - 220)) / 300;
      w = lerp(180, 120, t * t);
    }

    if (w > 0) {
      let px = figureX + random(-w, w);

      // Dissolution factor - increases toward top and right
      let dissolveFactor = noise(px * 0.003, py * 0.003) * 0.7 + 
                          map(px, figureX - 200, figureX + 300, 0, 0.5) +
                          map(py, figureY + 100, figureY - 450, 0, 0.6);
      dissolveFactor = constrain(dissolveFactor, 0, 1);

      // Offset particles based on dissolution
      let offsetX = dissolveFactor * random(50, 400) * (0.5 + noise(i * 0.1));
      let offsetY = dissolveFactor * random(-300, 100);

      let finalX = px + offsetX;
      let finalY = py + offsetY;

      particles.push({
        x: finalX,
        y: finalY,
        size: random(1, 6) * (1 - dissolveFactor * 0.5),
        dissolution: dissolveFactor,
        origX: px,
        origY: py
      });
    }
  }

  // Draw atmospheric particles in background
  for (let i = 0; i < 3000; i++) {
    let x = random(width);
    let y = random(height);
    let s = random(0.5, 2);
    let alpha = random(10, 40);
    noStroke();
    fill(200, 180, 150, alpha);
    ellipse(x, y, s, s);
  }

  // Draw the main figure particles
  for (let p of particles) {
    let baseColor;

    if (p.dissolution < 0.3) {
      // Solid figure - deep purples and blues
      baseColor = color(
        40 + p.dissolution * 100,
        20 + p.dissolution * 60,
        60 + p.dissolution * 40,
        map(p.dissolution, 0, 0.3, 255, 200)
      );
    } else if (p.dissolution < 0.7) {
      // Transitioning - warm oranges and golds
      let t = map(p.dissolution, 0.3, 0.7, 0, 1);
      baseColor = color(
        lerp(140, 255, t),
        lerp(80, 180, t),
        lerp(100, 80, t),
        map(p.dissolution, 0.3, 0.7, 200, 120)
      );
    } else {
      // Fully dissolved - golden light particles
      baseColor = color(
        255,
        200 + random(55),
        100 + random(50),
        map(p.dissolution, 0.7, 1, 120, 30)
      );
    }

    noStroke();
    fill(baseColor);
    ellipse(p.x, p.y, p.size, p.size);
  }

  // Add flowing lines suggesting movement/transition
  stroke(255, 200, 120, 30);
  strokeWeight(1);
  noFill();
  for (let i = 0; i < 100; i++) {
    beginShape();
    let startX = figureX + random(-100, 100);
    let startY = figureY + random(-200, 100);
    for (let j = 0; j < 50; j++) {
      let t = j / 50;
      let x = startX + t * 500 + noise(i, j * 0.1) * 100;
      let y = startY - t * 300 + noise(i + 100, j * 0.1) * 150;
      let alpha = sin(t * PI) * 40;
      stroke(255, 200, 120, alpha);
      curveVertex(x, y);
    }
    endShape();
  }

  // Subtle vignette
  for (let i = 0; i < 100; i++) {
    let alpha = map(i, 0, 100, 0, 80);
    noFill();
    stroke(5, 0, 15, alpha);
    strokeWeight(20);
    rect(i * 10 - 500, i * 10 - 500, width - i * 20 + 1000, height - i * 20 + 1000, 500);
  }

  // Final dust motes catching light
  for (let i = 0; i < 500; i++) {
    let x = random(width * 0.4, width);
    let y = random(height * 0.6);
    let s = random(1, 4);
    noStroke();
    fill(255, 220, 150, random(20, 80));
    ellipse(x, y, s, s);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Gradient background - from deep earth to ethereal light
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(245, 240, 230), color(45, 35, 30), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Luminous mist at top - the threshold
  drawMist();

  // Forest of dissolving trees
  drawTrees();

  // Fallen leaves and new growth at bottom
  drawForestFloor();

  // Floating particles - souls or spores
  drawParticles();

  // Light rays from above
  drawLightRays();

  // Subtle vignette
  drawVignette();
}

function drawMist() {
  for (let i = 0; i < 500; i++) {
    let x = random(width);
    let y = random(height * 0.5);
    let size = random(100, 400);
    let alpha = map(y, 0, height * 0.5, 40, 5);
    noStroke();
    fill(255, 250, 240, alpha);
    ellipse(x, y, size, size * 0.6);
  }
}

function drawTrees() {
  // Background trees - more dissolved
  for (let i = 0; i < 15; i++) {
    let x = random(width);
    drawTree(x, height, random(150, 250), 0.3, true);
  }

  // Middle trees
  for (let i = 0; i < 10; i++) {
    let x = random(width);
    drawTree(x, height, random(250, 400), 0.6, true);
  }

  // Foreground trees - more solid at base, dissolving upward
  for (let i = 0; i < 7; i++) {
    let x = 100 + i * 220 + random(-50, 50);
    drawTree(x, height + 50, random(400, 600), 1, false);
  }
}

function drawTree(x, y, maxHeight, opacity, background) {
  let trunkWidth = map(maxHeight, 150, 600, 15, 45);

  // Draw trunk dissolving upward
  for (let i = 0; i < maxHeight; i++) {
    let yPos = y - i;
    let dissolve = map(i, 0, maxHeight, 0, 1);
    dissolve = pow(dissolve, 1.5);

    let noiseVal = noise(x * 0.01, i * 0.02);
    let currentWidth = trunkWidth * (1 - dissolve * 0.7) * map(noiseVal, 0, 1, 0.8, 1.2);

    // Skip drawing based on dissolution
    if (random() < dissolve * 0.8) continue;

    let alpha = opacity * 255 * (1 - dissolve * 0.9);
    let baseColor = background ? color(60, 50, 45, alpha) : color(35, 28, 25, alpha);

    stroke(baseColor);
    strokeWeight(currentWidth * (1 - dissolve * 0.5));

    let xOffset = noise(i * 0.05, x) * 20 - 10;
    point(x + xOffset, yPos);
  }

  // Branches
  let numBranches = floor(random(5, 12));
  for (let b = 0; b < numBranches; b++) {
    let branchY = y - random(maxHeight * 0.3, maxHeight * 0.9);
    let branchLength = random(50, 150);
    let direction = random() > 0.5 ? 1 : -1;

    drawBranch(x, branchY, branchLength, direction, opacity, maxHeight, y);
  }
}

function drawBranch(x, y, length, dir, opacity, treeHeight, treeBase) {
  let segments = 20;
  let dissolveBase = map(treeBase - y, 0, treeHeight, 0, 1);

  for (let i = 0; i < segments; i++) {
    let t = i / segments;
    let dissolve = dissolveBase + t * 0.3;

    if (random() < dissolve * 0.6) continue;

    let bx = x + dir * t * length + noise(y * 0.1, i * 0.2) * 15;
    let by = y - t * length * 0.3 + noise(x * 0.1, i * 0.2) * 10;

    let alpha = opacity * 255 * (1 - dissolve);
    stroke(45, 38, 35, alpha);
    strokeWeight(map(t, 0, 1, 8, 1) * (1 - dissolve));
    point(bx, by);
  }
}

function drawForestFloor() {
  // Fallen leaves
  for (let i = 0; i < 800; i++) {
    let x = random(width);
    let y = random(height * 0.75, height);
    let size = random(5, 20);

    // Autumn colors - death colors
    let colors = [
      color(139, 69, 19, 180),  // brown
      color(160, 82, 45, 180),  // sienna
      color(184, 134, 11, 150), // dark goldenrod
      color(205, 133, 63, 150), // peru
      color(85, 60, 42, 200),   // dark brown
    ];

    let c = random(colors);
    noStroke();
    fill(c);

    push();
    translate(x, y);
    rotate(random(TWO_PI));
    ellipse(0, 0, size, size * 0.6);
    pop();
  }

  // New growth - small green shoots among decay
  for (let i = 0; i < 100; i++) {
    let x = random(width);
    let y = random(height * 0.85, height - 20);

    stroke(60, 100, 50, 200);
    strokeWeight(2);

    let shootHeight = random(10, 30);
    let curve = random(-5, 5);

    noFill();
    beginShape();
    for (let j = 0; j < 10; j++) {
      let t = j / 9;
      let sx = x + curve * sin(t * PI);
      let sy = y - t * shootHeight;
      vertex(sx, sy);
    }
    endShape();

    // Small leaf
    fill(70, 120, 55, 180);
    noStroke();
    ellipse(x + curve, y - shootHeight, 6, 10);
  }
}

function drawParticles() {
  // Floating particles - ascending souls/spores
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = random(height);

    let size = random(2, 8);
    let alpha = map(y, height, 0, 50, 200);

    // Golden/white particles
    let c = random() > 0.3 ? 
      color(255, 248, 220, alpha) : 
      color(255, 215, 150, alpha);

    noStroke();
    fill(c);
    ellipse(x, y, size, size);

    // Glow
    fill(red(c), green(c), blue(c), alpha * 0.3);
    ellipse(x, y, size * 3, size * 3);
  }
}

function drawLightRays() {
  // Divine light rays from above
  for (let i = 0; i < 8; i++) {
    let x1 = random(width * 0.2, width * 0.8);
    let x2 = x1 + random(-200, 200);

    for (let j = 0; j < 50; j++) {
      let t = j / 50;
      let y = t * height * 0.7;
      let xPos = lerp(x1, x2, t);
      let rayWidth = map(t, 0, 1, 20, 150);

      let alpha = 15 * (1 - t);
      noStroke();
      fill(255, 250, 230, alpha);
      ellipse(xPos, y, rayWidth, 30);
    }
  }
}

function drawVignette() {
  // Subtle dark vignette at edges
  for (let i = 0; i < 100; i++) {
    let alpha = map(i, 0, 100, 60, 0);
    noFill();
    stroke(20, 15, 10, alpha);
    strokeWeight(20);

    let offset = i * 15;
    rect(offset, offset, width - offset * 2, height - offset * 2, 50);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Background gradient - night sky to earth
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c1 = color(15, 10, 25);
    let c2 = color(45, 30, 20);
    let c = lerpColor(c1, c2, inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Moon glow
  noStroke();
  for (let r = 300; r > 0; r -= 5) {
    let alpha = map(r, 300, 0, 0, 30);
    fill(200, 190, 170, alpha);
    ellipse(1200, 200, r, r);
  }
  fill(240, 235, 220);
  ellipse(1200, 200, 120, 120);

  // Ground layer
  drawGround();

  // Dead tree
  drawDeadTree(300, 1400);

  // Wilting flowers with falling petals and seeds
  for (let i = 0; i < 12; i++) {
    let x = 200 + i * 110 + random(-30, 30);
    let y = 1500 + random(-100, 100);
    let decay = random(0.3, 1);
    drawWiltingFlower(x, y, decay);
  }

  // Falling petals
  for (let i = 0; i < 80; i++) {
    drawFallingPetal(random(100, 1500), random(400, 1700));
  }

  // Seeds floating down
  for (let i = 0; i < 60; i++) {
    drawSeed(random(100, 1500), random(600, 1850));
  }

  // New sprouts emerging from soil
  for (let i = 0; i < 15; i++) {
    let x = 150 + i * 100 + random(-20, 20);
    drawSprout(x, 1850 + random(-30, 30));
  }

  // Roots visible in soil
  drawRoots();

  // Mist/fog layer
  drawMist();

  // Fireflies/spirits
  for (let i = 0; i < 40; i++) {
    drawSpirit(random(width), random(300, 1600));
  }
}

function drawGround() {
  noStroke();
  // Soil layers
  for (let y = 1750; y < height; y++) {
    for (let x = 0; x < width; x += 3) {
      let n = noise(x * 0.01, y * 0.01);
      let r = 35 + n * 30;
      let g = 25 + n * 20;
      let b = 15 + n * 15;
      fill(r, g, b);
      rect(x, y, 4, 2);
    }
  }

  // Grass-like texture at soil line
  for (let x = 0; x < width; x += 5) {
    let yBase = 1750 + noise(x * 0.02) * 30;
    stroke(30, 35, 20);
    strokeWeight(1);
    for (let j = 0; j < 3; j++) {
      let h = random(10, 30);
      line(x + j * 2, yBase, x + j * 2 + random(-5, 5), yBase - h);
    }
  }
}

function drawDeadTree(x, y) {
  stroke(40, 30, 25);
  strokeWeight(1);
  noFill();

  // Main trunk
  fill(35, 28, 22);
  beginShape();
  vertex(x - 40, y);
  vertex(x - 50, y - 400);
  vertex(x - 30, y - 600);
  vertex(x + 10, y - 650);
  vertex(x + 30, y - 600);
  vertex(x + 40, y - 400);
  vertex(x + 35, y);
  endShape(CLOSE);

  // Branches
  stroke(35, 28, 22);
  drawBranch(x - 30, y - 500, -60, 200, 8, 4);
  drawBranch(x + 20, y - 550, 45, 180, 7, 4);
  drawBranch(x - 10, y - 620, -30, 150, 5, 3);
  drawBranch(x + 5, y - 600, 70, 120, 4, 3);

  // Texture on trunk
  for (let i = 0; i < 50; i++) {
    let tx = x + random(-35, 30);
    let ty = y - random(50, 580);
    stroke(25, 20, 15, 150);
    strokeWeight(random(1, 3));
    line(tx, ty, tx + random(-5, 5), ty + random(5, 20));
  }
}

function drawBranch(x, y, angle, len, weight, depth) {
  if (depth <= 0 || len < 10) return;

  strokeWeight(weight);
  stroke(35 + random(-5, 5), 28 + random(-5, 5), 22);

  let endX = x + cos(radians(angle)) * len;
  let endY = y + sin(radians(angle)) * len * 0.6;

  // Draw curved branch
  noFill();
  beginShape();
  vertex(x, y);
  let midX = (x + endX) / 2 + random(-20, 20);
  let midY = (y + endY) / 2 + random(-10, 10);
  quadraticVertex(midX, midY, endX, endY);
  endShape();

  // Recursive branches
  drawBranch(endX, endY, angle - random(20, 50), len * 0.7, weight * 0.6, depth - 1);
  drawBranch(endX, endY, angle + random(20, 50), len * 0.6, weight * 0.5, depth - 1);
}

function drawWiltingFlower(x, y, decay) {
  // Stem - bent with decay
  stroke(60 - decay * 30, 70 - decay * 40, 30);
  strokeWeight(3);
  noFill();

  let bendAmount = decay * 100;
  beginShape();
  vertex(x, y);
  quadraticVertex(x + bendAmount * 0.3, y - 100, x + bendAmount, y - 200 + decay * 50);
  endShape();

  // Flower head position
  let headX = x + bendAmount;
  let headY = y - 200 + decay * 50;

  // Wilting petals
  let petalCount = floor(random(5, 9));
  for (let i = 0; i < petalCount; i++) {
    let angle = (TWO_PI / petalCount) * i + decay * 0.5;
    let petalDroop = decay * PI * 0.4;

    push();
    translate(headX, headY);
    rotate(angle + petalDroop);

    // Petal color fading with decay
    let r = lerp(180, 80, decay) + random(-20, 20);
    let g = lerp(100, 50, decay) + random(-10, 10);
    let b = lerp(120, 40, decay) + random(-10, 10);
    fill(r, g, b, 200 - decay * 100);
    noStroke();

    // Curled, wilting petal shape
    beginShape();
    vertex(0, 0);
    let petalLen = 40 - decay * 15;
    bezierVertex(10, -petalLen * 0.3, 15 + decay * 10, -petalLen * 0.7, 5 + decay * 20, -petalLen);
    bezierVertex(-5 + decay * 5, -petalLen * 0.8, -10, -petalLen * 0.3, 0, 0);
    endShape();
    pop();
  }

  // Center of flower
  fill(60, 40, 30);
  noStroke();
  ellipse(headX, headY, 15 - decay * 5, 15 - decay * 5);

  // Seeds in center for highly decayed flowers
  if (decay > 0.6) {
    for (let i = 0; i < 8; i++) {
      let sx = headX + random(-8, 8);
      let sy = headY + random(-8, 8);
      fill(40, 35, 25);
      ellipse(sx, sy, 3, 4);
    }
  }

  // Leaves on stem
  for (let i = 0; i < 2; i++) {
    let leafY = y - 50 - i * 60;
    let leafX = x + (bendAmount * (1 - (y - leafY) / 200));

    push();
    translate(leafX, leafY);
    rotate(random(-0.5, 0.5) + decay * 0.8 * (i % 2 == 0 ? 1 : -1));

    fill(50 - decay * 20, 60 - decay * 30, 25, 180);
    noStroke();
    beginShape();
    vertex(0, 0);
    bezierVertex(15, -10, 25, -5, 30, 5);
    bezierVertex(20, 10, 10, 8, 0, 0);
    endShape();
    pop();
  }
}

function drawFallingPetal(x, y) {
  push();
  translate(x, y);
  rotate(random(TWO_PI));

  let decay = random(0.3, 1);
  let r = lerp(200, 100, decay);
  let g = lerp(120, 60, decay);
  let b = lerp(140, 50, decay);

  fill(r, g, b, 100 + random(50));
  noStroke();

  let size = random(8, 20);
  beginShape();
  vertex(0, 0);
  bezierVertex(size * 0.4, -size * 0.3, size * 0.6, -size * 0.5, size * 0.3, -size);
  bezierVertex(0, -size * 0.7, -size * 0.2, -size * 0.4, 0, 0);
  endShape();
  pop();
}

function drawSeed(x, y) {
  push();
  translate(x, y);
  rotate(random(-0.3, 0.3));

  // Seed body
  fill(50, 40, 30);
  noStroke();
  ellipse(0, 0, 4, 7);

  // Seed fluff/wings for wind dispersal
  stroke(200, 190, 170, 100);
  strokeWeight(0.5);
  for (let i = 0; i < 12; i++) {
    let angle = -PI / 2 + random(-0.5, 0.5);
    let len = random(10, 25);
    let endX = cos(angle + random(-0.3, 0.3)) * len;
    let endY = sin(angle) * len - 3;
    line(0, -3, endX, endY);
  }
  pop();
}

function drawSprout(x, y) {
  // Small green sprout emerging
  stroke(70, 100, 45);
  strokeWeight(2);
  noFill();

  let h = random(20, 50);
  let curve = random(-10, 10);

  beginShape();
  vertex(x, y);
  quadraticVertex(x + curve * 0.5, y - h * 0.5, x + curve, y - h);
  endShape();

  // Small leaf
  push();
  translate(x + curve, y - h);
  rotate(curve * 0.02);

  fill(80, 120, 50, 200);
  noStroke();
  beginShape();
  vertex(0, 0);
  bezierVertex(8, -5, 12, -3, 10, 5);
  bezierVertex(5, 3, 2, 2, 0, 0);
  endShape();

  // Second tiny leaf
  rotate(PI + 0.3);
  scale(0.6);
  beginShape();
  vertex(0, 0);
  bezierVertex(8, -5, 12, -3, 10, 5);
  bezierVertex(5, 3, 2, 2, 0, 0);
  endShape();
  pop();
}

function drawRoots() {
  stroke(50, 35, 25, 150);

  for (let i = 0; i < 20; i++) {
    let startX = random(100, 1500);
    let startY = 1800 + random(50);

    strokeWeight(random(1, 4));
    noFill();

    beginShape();
    vertex(startX, startY);
    let segments = floor(random(3, 7));
    let curX = startX;
    let curY = startY;

    for (let j = 0; j < segments; j++) {
      curX += random(-40, 40);
      curY += random(20, 50);
      vertex(curX, curY);
    }
    endShape();

    // Smaller root branches
    for (let j = 0; j < 3; j++) {
      let bx = startX + random(-30, 30);
      let by = startY + random(30, 100);
      strokeWeight(1);
      line(bx, by, bx + random(-20, 20), by + random(10, 30));
    }
  }
}

function drawMist() {
  noStroke();
  for (let i = 0; i < 100; i++) {
    let x = random(width);
    let y = random(1200, 1700);
    let w = random(100, 400);
    let h = random(30, 80);

    fill(180, 180, 190, random(5, 15));
    ellipse(x, y, w, h);
  }
}

function drawSpirit(x, y) {
  // Glowing orb representing departing life/spirits
  noStroke();

  let size = random(3, 12);

  // Outer glow
  for (let r = size * 4; r > 0; r -= 2) {
    let alpha = map(r, size * 4, 0, 0, 30);
    fill(255, 250, 200, alpha);
    ellipse(x, y, r, r);
  }

  // Core
  fill(255, 255, 240, 200);
  ellipse(x, y, size, size);
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Twilight gradient background
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c1 = color(25, 20, 50);
    let c2 = color(60, 40, 80);
    let c3 = color(30, 25, 45);
    let c;
    if (inter < 0.5) {
      c = lerpColor(c1, c2, inter * 2);
    } else {
      c = lerpColor(c2, c3, (inter - 0.5) * 2);
    }
    stroke(c);
    line(0, y, width, y);
  }

  // Moon with halo
  drawMoon();

  // Distant hills
  drawHills();

  // Fog layer
  drawFog(1400, 150);

  // Dead tree
  drawTree(250, 1300, 400);
  drawTree(1400, 1350, 300);

  // Gravestones
  drawGravestone(400, 1500, 120, 180);
  drawGravestone(700, 1550, 100, 150);
  drawGravestone(1000, 1480, 140, 200);
  drawGravestone(1250, 1520, 90, 130);

  // Withered and new flowers
  drawFlowers();

  // Crows
  drawCrow(300, 950);
  drawCrow(350, 920);

  // Ground
  drawGround();

  // Falling leaves
  drawFallingLeaves();

  // Mist particles
  drawMist();

  // Vignette
  drawVignette();
}

function drawMoon() {
  // Halo
  noStroke();
  for (let r = 300; r > 0; r -= 5) {
    let alpha = map(r, 0, 300, 50, 0);
    fill(200, 180, 220, alpha);
    ellipse(1200, 300, r * 2, r * 2);
  }
  // Moon
  fill(230, 220, 240);
  ellipse(1200, 300, 150, 150);
  // Craters
  fill(210, 200, 220, 100);
  ellipse(1180, 280, 30, 30);
  ellipse(1220, 320, 20, 20);
  ellipse(1190, 330, 15, 15);
}

function drawHills() {
  noStroke();
  // Far hill
  fill(40, 35, 60);
  beginShape();
  vertex(0, 1200);
  for (let x = 0; x <= width; x += 20) {
    let y = 1100 + noise(x * 0.003) * 150;
    vertex(x, y);
  }
  vertex(width, 1200);
  endShape(CLOSE);

  // Near hill
  fill(35, 30, 55);
  beginShape();
  vertex(0, 1350);
  for (let x = 0; x <= width; x += 20) {
    let y = 1200 + noise(x * 0.004 + 100) * 200;
    vertex(x, y);
  }
  vertex(width, 1350);
  endShape(CLOSE);
}

function drawTree(x, baseY, h) {
  stroke(30, 25, 40);
  strokeWeight(1);

  function branch(x1, y1, len, angle, depth) {
    if (depth === 0 || len < 5) return;

    let x2 = x1 + cos(angle) * len;
    let y2 = y1 + sin(angle) * len;

    strokeWeight(map(depth, 0, 8, 1, 15));
    stroke(30 + depth * 2, 25 + depth * 2, 40 + depth * 2);
    line(x1, y1, x2, y2);

    let newLen = len * random(0.6, 0.8);
    let branches = floor(random(2, 4));

    for (let i = 0; i < branches; i++) {
      let newAngle = angle + random(-0.8, 0.8);
      branch(x2, y2, newLen, newAngle, depth - 1);
    }
  }

  // Main trunk
  strokeWeight(20);
  stroke(25, 20, 35);
  line(x, baseY, x, baseY - h * 0.4);

  branch(x, baseY - h * 0.4, h * 0.3, -PI/2 + random(-0.3, 0.3), 7);
}

function drawGravestone(x, y, w, h) {
  noStroke();

  // Shadow
  fill(20, 15, 30, 100);
  ellipse(x, y + 10, w * 1.5, 30);

  // Stone body
  fill(60, 55, 70);
  beginShape();
  vertex(x - w/2, y);
  vertex(x - w/2, y - h * 0.7);
  // Rounded top
  for (let a = PI; a >= 0; a -= 0.1) {
    let px = x + cos(a) * w/2;
    let py = y - h * 0.7 + sin(a) * h * 0.3;
    vertex(px, py);
  }
  vertex(x + w/2, y);
  endShape(CLOSE);

  // Moss and age marks
  fill(45, 60, 45, 150);
  for (let i = 0; i < 15; i++) {
    let mx = x + random(-w/2.5, w/2.5);
    let my = y - random(10, h * 0.5);
    ellipse(mx, my, random(5, 15), random(5, 10));
  }

  // Cracks
  stroke(40, 35, 50);
  strokeWeight(1);
  for (let i = 0; i < 3; i++) {
    let cx = x + random(-w/3, w/3);
    let cy = y - random(h * 0.2, h * 0.6);
    beginShape();
    noFill();
    for (let j = 0; j < 5; j++) {
      vertex(cx + random(-10, 10), cy + j * 10);
    }
    endShape();
  }
}

function drawFlowers() {
  // Withered flowers near graves
  for (let i = 0; i < 40; i++) {
    let x = random(300, 1300);
    let y = random(1450, 1600);
    drawWitheredFlower(x, y);
  }

  // New sprouts - hope
  for (let i = 0; i < 20; i++) {
    let x = random(350, 1200);
    let y = random(1500, 1650);
    drawSprout(x, y);
  }
}

function drawWitheredFlower(x, y) {
  stroke(80, 50, 60);
  strokeWeight(2);

  // Bent stem
  noFill();
  beginShape();
  for (let i = 0; i < 5; i++) {
    let py = y - i * 10;
    let px = x + sin(i * 0.5) * 10;
    curveVertex(px, py);
  }
  endShape();

  // Drooping petals
  noStroke();
  fill(100, 60, 70, 180);
  let fx = x + sin(2) * 10;
  let fy = y - 40;
  for (let a = 0; a < TWO_PI; a += PI/3) {
    let px = fx + cos(a + PI/2) * 8;
    let py = fy + sin(a + PI/2) * 12;
    ellipse(px, py, 6, 10);
  }
}

function drawSprout(x, y) {
  stroke(60, 100, 60);
  strokeWeight(2);
  noFill();

  // Small stem
  beginShape();
  vertex(x, y);
  vertex(x + random(-3, 3), y - 15);
  endShape();

  // Tiny leaves
  fill(70, 120, 70, 200);
  noStroke();
  ellipse(x - 4, y - 12, 8, 4);
  ellipse(x + 4, y - 14, 8, 4);
}

function drawCrow(x, y) {
  fill(15, 10, 20);
  noStroke();

  // Body
  ellipse(x, y, 40, 25);

  // Head
  ellipse(x + 18, y - 8, 20, 18);

  // Beak
  fill(50, 45, 55);
  triangle(x + 28, y - 8, x + 40, y - 6, x + 28, y - 4);

  // Eye
  fill(200, 180, 100);
  ellipse(x + 22, y - 10, 5, 5);
  fill(0);
  ellipse(x + 22, y - 10, 2, 2);

  // Wing
  fill(20, 15, 25);
  beginShape();
  vertex(x - 10, y);
  vertex(x - 25, y + 15);
  vertex(x - 15, y + 12);
  vertex(x - 5, y + 15);
  vertex(x + 5, y + 5);
  endShape(CLOSE);

  // Tail
  beginShape();
  vertex(x - 20, y);
  vertex(x - 35, y + 5);
  vertex(x - 30, y - 2);
  vertex(x - 35, y - 5);
  vertex(x - 20, y - 5);
  endShape(CLOSE);
}

function drawGround() {
  noStroke();

  // Main ground
  for (let y = 1600; y < height; y += 2) {
    for (let x = 0; x < width; x += 4) {
      let n = noise(x * 0.01, y * 0.01);
      let c = lerpColor(color(35, 30, 45), color(50, 40, 55), n);
      fill(c);
      rect(x, y, 4, 2);
    }
  }

  // Grass tufts
  stroke(40, 50, 40);
  strokeWeight(1);
  for (let i = 0; i < 200; i++) {
    let gx = random(width);
    let gy = random(1550, 1750);
    for (let j = 0; j < 5; j++) {
      let gh = random(10, 25);
      let angle = random(-0.3, 0.3);
      line(gx + j * 2, gy, gx + j * 2 + sin(angle) * gh, gy - gh);
    }
  }
}

function drawFog(y, h) {
  noStroke();
  for (let i = 0; i < 100; i++) {
    let fx = random(width);
    let fy = y + random(-h/2, h/2);
    let fs = random(100, 300);
    fill(80, 70, 100, random(5, 20));
    ellipse(fx, fy, fs, fs * 0.3);
  }
}

function drawFallingLeaves() {
  noStroke();
  for (let i = 0; i < 30; i++) {
    let x = random(width);
    let y = random(400, 1400);
    let size = random(5, 12);
    let rot = random(TWO_PI);

    push();
    translate(x, y);
    rotate(rot);
    fill(80, 50, 50, 180);
    ellipse(0, 0, size, size * 0.5);
    pop();
  }
}

function drawMist() {
  noStroke();
  for (let i = 0; i < 500; i++) {
    let x = random(width);
    let y = random(height);
    let alpha = map(y, 0, height, 2, 10);
    fill(150, 140, 170, alpha);
    ellipse(x, y, random(2, 8), random(2, 8));
  }
}

function drawVignette() {
  noStroke();
  for (let r = 1200; r > 0; r -= 10) {
    let alpha = map(r, 0, 1200, 0, 100);
    fill(10, 5, 20, alpha);
    ellipse(width/2, height/2, width + 400 - r, height + 400 - r);
  }

  // Edge darkening
  for (let i = 0; i < 100; i++) {
    let alpha = map(i, 0, 100, 150, 0);
    fill(10, 5, 20, alpha);
    rect(0, 0, i, height);
    rect(width - i, 0, i, height);
    rect(0, 0, width, i);
    rect(0, height - i, width, i);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep earth background gradient
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(15, 12, 20), color(35, 25, 20), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Soil texture at bottom
  drawSoil();

  // Dead roots underground
  drawRoots();

  // Withered stems
  drawWitheredStems();

  // Falling and decomposing petals
  drawFallingPetals();

  // Dying flowers
  drawDyingFlowers();

  // Seeds in soil - promise of rebirth
  drawSeeds();

  // Subtle light from above
  drawLight();

  // Floating particles - dust and spores
  drawParticles();

  // Vignette
  drawVignette();
}

function drawSoil() {
  for (let i = 0; i < 8000; i++) {
    let x = random(width);
    let y = random(height * 0.65, height);
    let size = random(2, 8);
    let darkness = random(20, 50);
    let r = darkness + random(-10, 20);
    let g = darkness * 0.7;
    let b = darkness * 0.5;
    noStroke();
    fill(r, g, b, random(100, 200));
    ellipse(x, y, size, size * random(0.5, 1.5));
  }

  // Organic matter in soil
  for (let i = 0; i < 500; i++) {
    let x = random(width);
    let y = random(height * 0.7, height);
    stroke(60, 40, 30, 150);
    strokeWeight(random(1, 3));
    let len = random(10, 30);
    let angle = random(TWO_PI);
    line(x, y, x + cos(angle) * len, y + sin(angle) * len);
  }
}

function drawRoots() {
  stroke(45, 35, 30);
  strokeWeight(2);
  noFill();

  for (let i = 0; i < 15; i++) {
    let startX = random(200, width - 200);
    let startY = height * 0.6 + random(50);

    beginShape();
    let x = startX;
    let y = startY;
    for (let j = 0; j < 50; j++) {
      vertex(x, y);
      x += random(-15, 15);
      y += random(5, 20);
      if (y > height) break;
    }
    endShape();

    // Root branches
    let branches = int(random(3, 7));
    for (let b = 0; b < branches; b++) {
      let bx = startX + random(-50, 50);
      let by = startY + random(50, 200);
      strokeWeight(1);
      beginShape();
      for (let j = 0; j < 20; j++) {
        vertex(bx, by);
        bx += random(-10, 10);
        by += random(3, 15);
      }
      endShape();
    }
  }
}

function drawWitheredStems() {
  for (let i = 0; i < 12; i++) {
    let baseX = random(100, width - 100);
    let baseY = height * 0.65;

    // Brown, dried stem
    strokeWeight(random(3, 8));
    noFill();

    let points = [];
    let x = baseX;
    let y = baseY;
    let stemHeight = random(400, 700);

    for (let j = 0; j < 30; j++) {
      points.push({x: x, y: y});
      let progress = j / 30;
      x += noise(i * 10 + j * 0.1) * 30 - 15;
      // Stems bend under weight of death
      x += sin(progress * PI) * random(-20, 20);
      y -= stemHeight / 30;
    }

    // Draw stem with gradient from dark to lighter brown
    for (let j = 0; j < points.length - 1; j++) {
      let progress = j / points.length;
      let c = lerpColor(color(50, 35, 25), color(80, 55, 35), progress);
      stroke(c);
      strokeWeight(map(j, 0, points.length, 8, 2));
      line(points[j].x, points[j].y, points[j+1].x, points[j+1].y);
    }

    // Dried leaves on stem
    for (let j = 5; j < points.length - 5; j += 4) {
      if (random() > 0.4) {
        drawWitheredLeaf(points[j].x, points[j].y, random(-1, 1));
      }
    }
  }
}

function drawWitheredLeaf(x, y, dir) {
  push();
  translate(x, y);
  rotate(dir * random(0.3, 0.8) + PI/4);

  noStroke();
  fill(55, 40, 25, 200);

  // Curled, dried leaf shape
  beginShape();
  for (let a = 0; a < TWO_PI; a += 0.2) {
    let r = 15 + sin(a * 2) * 10;
    r *= noise(a + x) * 1.5;
    // Curl effect
    r *= map(a, 0, TWO_PI, 1, 0.3);
    vertex(cos(a) * r, sin(a) * r * 2);
  }
  endShape(CLOSE);

  pop();
}

function drawDyingFlowers() {
  // Main dying flowers at various stages
  let flowerPositions = [
    {x: 300, y: 350, size: 1.2, decay: 0.8},
    {x: 800, y: 280, size: 1.5, decay: 0.6},
    {x: 1200, y: 400, size: 1.0, decay: 0.9},
    {x: 500, y: 500, size: 0.8, decay: 0.7},
    {x: 1000, y: 450, size: 1.1, decay: 0.5},
    {x: 1400, y: 550, size: 0.9, decay: 0.85},
    {x: 200, y: 600, size: 0.7, decay: 0.95}
  ];

  for (let f of flowerPositions) {
    drawDecayingFlower(f.x, f.y, f.size, f.decay);
  }
}

function drawDecayingFlower(x, y, size, decay) {
  push();
  translate(x, y);
  scale(size);

  // Drooping head rotation based on decay
  rotate(decay * 0.5);

  let petalCount = 8;

  // Petals - withered and curling
  for (let i = 0; i < petalCount; i++) {
    let angle = (TWO_PI / petalCount) * i;
    let petalDecay = decay + noise(i + x) * 0.3;
    petalDecay = constrain(petalDecay, 0, 1);

    push();
    rotate(angle);

    // Petal color fades and browns
    let freshColor = color(180, 80, 100);
    let deadColor = color(60, 40, 35);
    let petalColor = lerpColor(freshColor, deadColor, petalDecay);

    noStroke();
    fill(petalColor);

    // Wilted petal shape
    beginShape();
    let petalLength = 80 * (1 - petalDecay * 0.3);
    let petalWidth = 35 * (1 - petalDecay * 0.4);

    // Curling edges
    for (let t = 0; t <= 1; t += 0.1) {
      let px = t * petalLength;
      let curl = sin(t * PI) * petalWidth * (1 - petalDecay * 0.5);
      curl += noise(t * 5 + i) * 10 * petalDecay;
      vertex(px, curl);
    }
    for (let t = 1; t >= 0; t -= 0.1) {
      let px = t * petalLength;
      let curl = sin(t * PI) * petalWidth * (1 - petalDecay * 0.5);
      curl += noise(t * 5 + i + 100) * 10 * petalDecay;
      vertex(px, -curl);
    }
    endShape(CLOSE);

    // Decay spots on petals
    fill(40, 30, 25, 150);
    for (let s = 0; s < 5 * decay; s++) {
      let sx = random(10, petalLength - 10);
      let sy = random(-petalWidth/2, petalWidth/2);
      ellipse(sx, sy, random(5, 15), random(5, 15));
    }

    pop();
  }

  // Center of flower - seed head
  fill(40, 30, 25);
  noStroke();
  ellipse(0, 0, 40, 40);

  // Seeds in center
  fill(30, 25, 20);
  for (let i = 0; i < 20; i++) {
    let angle = random(TWO_PI);
    let r = random(5, 18);
    ellipse(cos(angle) * r, sin(angle) * r, 5, 7);
  }

  pop();
}

function drawFallingPetals() {
  for (let i = 0; i < 80; i++) {
    let x = random(width);
    let y = random(height * 0.2, height * 0.75);
    let size = random(15, 40);
    let decay = random(0.5, 1);

    push();
    translate(x, y);
    rotate(random(TWO_PI));

    // Falling petal color
    let c = lerpColor(
      color(150, 70, 90, 180),
      color(50, 35, 30, 150),
      decay
    );
    fill(c);
    noStroke();

    // Petal shape
    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.3) {
      let r = size * (0.5 + 0.5 * sin(a * 2));
      r *= noise(a + i) * 1.2;
      vertex(cos(a) * r, sin(a) * r * 0.6);
    }
    endShape(CLOSE);

    pop();
  }
}

function drawSeeds() {
  // Seeds buried in soil - hope of new life
  for (let i = 0; i < 40; i++) {
    let x = random(100, width - 100);
    let y = random(height * 0.75, height - 50);

    push();
    translate(x, y);
    rotate(random(TWO_PI));

    // Seed glow - subtle life force
    let glowSize = random(20, 40);
    for (let g = glowSize; g > 0; g -= 2) {
      fill(100, 80, 50, map(g, 0, glowSize, 30, 0));
      noStroke();
      ellipse(0, 0, g, g * 0.6);
    }

    // Seed body
    fill(60, 50, 35);
    ellipse(0, 0, 12, 8);

    // Tiny root beginning to emerge from some seeds
    if (random() > 0.6) {
      stroke(70, 60, 45);
      strokeWeight(1);
      let rootLen = random(10, 25);
      bezier(0, 4, 5, 10, -3, 15, random(-5, 5), 4 + rootLen);
    }

    pop();
  }
}

function drawLight() {
  // Ethereal light from above - passage of soul
  noStroke();

  // Main light beam
  for (let i = 0; i < 50; i++) {
    let alpha = map(i, 0, 50, 15, 0);
    fill(255, 240, 200, alpha);

    let topWidth = 200 + i * 15;
    let bottomWidth = 400 + i * 20;
    let yStart = -50;
    let yEnd = height * 0.5;

    beginShape();
    vertex(width/2 - topWidth/2, yStart);
    vertex(width/2 + topWidth/2, yStart);
    vertex(width/2 + bottomWidth/2, yEnd);
    vertex(width/2 - bottomWidth/2, yEnd);
    endShape(CLOSE);
  }

  // Light particles
  for (let i = 0; i < 100; i++) {
    let x = width/2 + random(-300, 300);
    let y = random(0, height * 0.5);
    let size = random(2, 6);
    fill(255, 250, 220, random(50, 150));
    ellipse(x, y, size, size);
  }
}

function drawParticles() {
  // Dust, spores, and ash floating
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = random(height);
    let size = random(1, 4);

    // Color varies from light dust to dark ash
    let t = noise(x * 0.01, y * 0.01);
    let c;
    if (t > 0.6) {
      c = color(200, 190, 170, random(30, 80)); // Light dust
    } else if (t > 0.3) {
      c = color(100, 80, 60, random(40, 100)); // Pollen/spores
    } else {
      c = color(40, 35, 30, random(50, 120)); // Ash
    }

    fill(c);
    noStroke();
    ellipse(x, y, size, size);
  }
}

function drawVignette() {
  // Dark vignette around edges
  noFill();
  for (let i = 0; i < 150; i++) {
    let alpha = map(i, 0, 150, 100, 0);
    stroke(10, 8, 15, alpha);
    strokeWeight(10);

    let offset = i * 3;
    rect(offset, offset, width - offset * 2, height - offset * 2, 50);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep twilight gradient background
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(25, 20, 45), color(60, 45, 50), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Ground with organic texture
  drawGround();

  // The dissolving tree
  drawTree();

  // Rising particles (souls/memories)
  drawRisingParticles();

  // Birds in the sky
  drawBirds();

  // Soft overlay atmosphere
  drawAtmosphere();
}

function drawGround() {
  noStroke();
  for (let i = 0; i < 8000; i++) {
    let x = random(width);
    let baseY = height - 350 + noise(x * 0.005) * 100;
    let y = random(baseY, height);
    let size = random(2, 8);
    let alpha = map(y, baseY, height, 50, 150);
    fill(45 + random(-10, 10), 35 + random(-10, 10), 30 + random(-10, 10), alpha);
    ellipse(x, y, size, size * 0.6);
  }

  // Roots spreading into ground
  stroke(55, 40, 35, 100);
  strokeWeight(1);
  for (let i = 0; i < 50; i++) {
    let startX = width/2 + random(-150, 150);
    let startY = height - 350 + random(50);
    drawRoot(startX, startY, random(80, 200), random(TWO_PI * 0.3, TWO_PI * 0.7));
  }
}

function drawRoot(x, y, len, angle) {
  let segments = floor(len / 5);
  let px = x, py = y;
  for (let i = 0; i < segments; i++) {
    let progress = i / segments;
    let nx = px + cos(angle) * 5;
    let ny = py + sin(angle) * 5;
    let alpha = map(progress, 0, 1, 80, 10);
    stroke(55, 40, 35, alpha);
    strokeWeight(map(progress, 0, 1, 2, 0.5));
    line(px, py, nx, ny);
    px = nx;
    py = ny;
    angle += random(-0.3, 0.3);
  }
}

function drawTree() {
  let baseX = width / 2;
  let baseY = height - 350;

  // Main trunk - dissolving effect
  drawDissolvingTrunk(baseX, baseY);

  // Branches
  drawBranches(baseX, baseY - 400, 300, -HALF_PI, 6);
}

function drawDissolvingTrunk(x, y) {
  for (let i = 0; i < 15000; i++) {
    let ty = random(y - 500, y);
    let progress = map(ty, y - 500, y, 0, 1);
    let dissolve = map(ty, y - 500, y, 0.9, 0.1);

    // Trunk gets narrower at top
    let trunkWidth = map(ty, y - 500, y, 30, 80);

    // Dissolution effect - particles scatter more at bottom
    let scatter = progress * 60 * random(0.5, 1.5);
    let tx = x + random(-trunkWidth, trunkWidth) + (random() < dissolve ? random(-scatter, scatter) : 0);

    // Skip some particles based on dissolution
    if (random() < dissolve * 0.3) continue;

    let size = random(1, 4);
    let baseColor = color(70 + random(-15, 15), 55 + random(-10, 10), 45 + random(-10, 10));
    let alpha = map(progress, 0, 1, 180, 50) * (random() < dissolve ? random(0.3, 0.7) : 1);

    noStroke();
    fill(red(baseColor), green(baseColor), blue(baseColor), alpha);
    ellipse(tx, ty, size, size);
  }
}

function drawBranches(x, y, len, angle, depth) {
  if (depth <= 0 || len < 10) return;

  let endX = x + cos(angle) * len;
  let endY = y + sin(angle) * len;

  // Draw branch as particles
  let steps = floor(len / 3);
  for (let i = 0; i < steps; i++) {
    let t = i / steps;
    let px = lerp(x, endX, t);
    let py = lerp(y, endY, t);
    let branchWidth = map(t, 0, 1, depth * 3, depth);

    for (let j = 0; j < depth * 2; j++) {
      let bx = px + random(-branchWidth, branchWidth);
      let by = py + random(-branchWidth, branchWidth);
      let size = random(1, 3);
      let alpha = random(80, 150);
      noStroke();
      fill(65 + random(-10, 10), 50 + random(-10, 10), 40 + random(-10, 10), alpha);
      ellipse(bx, by, size, size);
    }
  }

  // Create child branches
  let branches = floor(random(2, 4));
  for (let i = 0; i < branches; i++) {
    let newAngle = angle + random(-0.8, 0.8);
    let newLen = len * random(0.5, 0.75);
    let branchX = lerp(x, endX, random(0.4, 0.9));
    let branchY = lerp(y, endY, random(0.4, 0.9));
    drawBranches(branchX, branchY, newLen, newAngle, depth - 1);
  }
}

function drawRisingParticles() {
  // Light particles rising from tree
  for (let i = 0; i < 800; i++) {
    let baseX = width/2 + random(-200, 200);
    let startY = height - 400;
    let endY = random(100, startY);
    let y = random(endY, startY);

    let drift = noise(i * 0.1, y * 0.005) * 200 - 100;
    let x = baseX + drift;

    let progress = map(y, startY, 100, 0, 1);
    let size = map(progress, 0, 1, 2, 6);
    let alpha = map(progress, 0, 1, 200, 40);

    // Golden warm light
    let r = 255;
    let g = 220 + random(-20, 20);
    let b = 150 + random(-30, 30);

    noStroke();
    // Glow effect
    fill(r, g, b, alpha * 0.3);
    ellipse(x, y, size * 3, size * 3);
    fill(r, g, b, alpha);
    ellipse(x, y, size, size);
  }

  // Particles dissolving from trunk base
  for (let i = 0; i < 500; i++) {
    let x = width/2 + random(-150, 150);
    let y = height - 350 + random(-100, 150);
    let size = random(1, 4);
    let alpha = random(30, 100);

    noStroke();
    fill(200, 180, 140, alpha);
    ellipse(x, y, size, size);
  }
}

function drawBirds() {
  // Flock of birds in spiral pattern
  let centerX = width / 2 + 200;
  let centerY = 400;

  for (let i = 0; i < 60; i++) {
    let angle = i * 0.5 + noise(i) * 2;
    let radius = 50 + i * 4 + noise(i * 0.3) * 50;
    let x = centerX + cos(angle) * radius;
    let y = centerY + sin(angle) * radius * 0.5 - i * 2;

    let birdSize = map(i, 0, 60, 8, 20);
    let alpha = map(i, 0, 60, 200, 80);

    drawBird(x, y, birdSize, angle + HALF_PI, alpha);
  }

  // Additional scattered birds
  for (let i = 0; i < 25; i++) {
    let x = random(100, width - 100);
    let y = random(80, 500);
    let size = random(6, 15);
    let alpha = random(60, 150);
    drawBird(x, y, size, random(TWO_PI), alpha);
  }
}

function drawBird(x, y, size, angle, alpha) {
  push();
  translate(x, y);
  rotate(angle);
  noStroke();
  fill(20, 15, 25, alpha);

  // Simple bird silhouette
  beginShape();
  vertex(0, 0);
  vertex(-size, -size * 0.4);
  vertex(-size * 0.3, 0);
  vertex(-size, size * 0.4);
  endShape(CLOSE);

  // Wing
  beginShape();
  vertex(-size * 0.2, 0);
  vertex(-size * 0.6, -size * 0.6);
  vertex(-size * 0.5, 0);
  vertex(-size * 0.6, size * 0.6);
  endShape(CLOSE);

  pop();
}

function drawAtmosphere() {
  // Soft fog/mist near ground
  noStroke();
  for (let i = 0; i < 3000; i++) {
    let x = random(width);
    let y = random(height - 500, height - 200);
    let size = random(20, 80);
    let alpha = random(5, 20);
    fill(80, 70, 90, alpha);
    ellipse(x, y, size, size * 0.5);
  }

  // Vignette effect
  for (let i = 0; i < 50; i++) {
    let alpha = map(i, 0, 50, 30, 0);
    noFill();
    stroke(10, 5, 20, alpha);
    strokeWeight(20);
    rectMode(CENTER);
    rect(width/2, height/2, width - i * 30, height - i * 35, 100);
  }

  // Subtle light rays from top
  for (let i = 0; i < 8; i++) {
    let x = width/2 + random(-300, 300);
    let rayWidth = random(50, 150);

    for (let y = 0; y < height * 0.6; y += 5) {
      let alpha = map(y, 0, height * 0.6, 15, 0);
      let spread = map(y, 0, height * 0.6, 0, rayWidth);
      noStroke();
      fill(255, 240, 200, alpha);
      ellipse(x + random(-spread, spread), y, random(3, 10), random(3, 10));
    }
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Sky gradient - from warm to cold to void
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r, g, b;
    if (t < 0.3) {
      r = lerp(180, 80, t / 0.3);
      g = lerp(100, 50, t / 0.3);
      b = lerp(60, 70, t / 0.3);
    } else if (t < 0.6) {
      let tt = (t - 0.3) / 0.3;
      r = lerp(80, 20, tt);
      g = lerp(50, 15, tt);
      b = lerp(70, 40, tt);
    } else {
      let tt = (t - 0.6) / 0.4;
      r = lerp(20, 5, tt);
      g = lerp(15, 5, tt);
      b = lerp(40, 15, tt);
    }
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Distant mountains/void
  noStroke();
  for (let layer = 0; layer < 5; layer++) {
    let baseY = 500 + layer * 80;
    let alpha = 30 + layer * 15;
    fill(10 + layer * 5, 5 + layer * 3, 20 + layer * 5, alpha);
    beginShape();
    vertex(0, height);
    for (let x = 0; x <= width; x += 10) {
      let y = baseY + noise(x * 0.003, layer * 10) * 150 - 50;
      vertex(x, y);
    }
    vertex(width, height);
    endShape(CLOSE);
  }

  // River of darkness
  let riverY = 900;
  for (let y = riverY; y < height; y++) {
    let t = (y - riverY) / (height - riverY);
    let darkness = lerp(25, 3, t);
    let blueHint = lerp(35, 8, t);
    stroke(darkness * 0.8, darkness * 0.6, blueHint);
    line(0, y, width, y);
  }

  // River reflections and ripples
  for (let i = 0; i < 800; i++) {
    let x = random(width);
    let y = random(riverY + 50, height);
    let t = (y - riverY) / (height - riverY);
    let len = random(20, 100) * (1 - t * 0.5);
    let alpha = random(10, 40) * (1 - t);
    stroke(60, 40, 50, alpha);
    strokeWeight(random(1, 3));
    line(x, y, x + len, y);
  }

  // Glowing horizon line
  strokeWeight(2);
  for (let i = 0; i < 50; i++) {
    let alpha = 50 - i;
    stroke(200, 120, 60, alpha);
    line(0, riverY - i, width, riverY - i);
  }

  // The boat - simple silhouette
  drawBoat(800, 1100);

  // Dead tree on the left
  drawDeadTree(150, 850, 350);

  // Smaller dead tree on right
  drawDeadTree(1450, 900, 200);

  // Falling leaves - golden, representing life fading
  for (let i = 0; i < 150; i++) {
    let x = random(width);
    let y = random(200, 1400);
    let size = random(5, 20);
    let t = y / 1400;

    // Leaves fade from gold to dark as they fall
    let r = lerp(220, 60, t);
    let g = lerp(160, 30, t);
    let b = lerp(40, 20, t);
    let alpha = lerp(255, 50, t);

    fill(r, g, b, alpha);
    noStroke();
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    drawLeaf(size);
    pop();
  }

  // Birds flying into the void
  for (let i = 0; i < 12; i++) {
    let x = 600 + random(-200, 400);
    let y = 150 + random(200) + i * 30;
    let size = map(y, 150, 450, 25, 8);
    let alpha = map(y, 150, 450, 200, 50);
    drawBird(x, y, size, alpha);
  }

  // Mist/fog layers
  for (let layer = 0; layer < 10; layer++) {
    let y = riverY - 50 + layer * 30;
    for (let x = 0; x < width; x += 5) {
      let n = noise(x * 0.005, layer * 0.5);
      let alpha = n * 30;
      fill(80, 60, 70, alpha);
      noStroke();
      ellipse(x, y + noise(x * 0.01) * 50, random(50, 150), random(20, 40));
    }
  }

  // Light particles - souls or memories
  for (let i = 0; i < 100; i++) {
    let x = random(width);
    let y = random(riverY);
    let size = random(2, 6);
    let alpha = random(50, 150);
    let glow = random(20, 50);

    // Soft glow
    for (let g = glow; g > 0; g -= 5) {
      fill(255, 220, 180, alpha * (1 - g / glow) * 0.3);
      noStroke();
      ellipse(x, y, size + g, size + g);
    }
    fill(255, 240, 200, alpha);
    ellipse(x, y, size, size);
  }

  // Reflection of the boat
  push();
  translate(0, 1100 * 2);
  scale(1, -1);
  drawBoat(800, 1100);
  pop();

  // Overlay for depth
  for (let y = height * 0.7; y < height; y++) {
    let t = (y - height * 0.7) / (height * 0.3);
    fill(0, 0, 10, t * 100);
    noStroke();
    rect(0, y, width, 1);
  }

  // Vignette effect
  drawVignette();
}

function drawBoat(x, y) {
  push();
  translate(x, y);

  // Boat body
  fill(20, 15, 10);
  noStroke();
  beginShape();
  vertex(-80, 0);
  vertex(-60, 30);
  vertex(60, 30);
  vertex(80, 0);
  vertex(60, -5);
  vertex(-60, -5);
  endShape(CLOSE);

  // Figure in boat - hooded
  fill(15, 10, 8);
  beginShape();
  vertex(-10, -5);
  vertex(-20, -60);
  vertex(-15, -90);
  vertex(0, -100);
  vertex(15, -90);
  vertex(20, -60);
  vertex(10, -5);
  endShape(CLOSE);

  // Cloak draping
  beginShape();
  vertex(-20, -60);
  vertex(-35, -20);
  vertex(-25, 0);
  vertex(25, 0);
  vertex(35, -20);
  vertex(20, -60);
  endShape(CLOSE);

  // Oar
  stroke(30, 20, 15);
  strokeWeight(4);
  line(40, -30, 150, 50);

  fill(35, 25, 20);
  noStroke();
  ellipse(155, 55, 30, 50);

  pop();
}

function drawDeadTree(x, baseY, h) {
  push();
  translate(x, baseY);

  stroke(25, 18, 15);
  strokeWeight(1);
  fill(20, 15, 12);

  // Main trunk
  beginShape();
  vertex(-25, 0);
  vertex(-20, -h * 0.4);
  vertex(-15, -h * 0.7);
  vertex(-5, -h);
  vertex(5, -h * 0.95);
  vertex(15, -h * 0.6);
  vertex(20, -h * 0.3);
  vertex(25, 0);
  endShape(CLOSE);

  // Branches
  stroke(20, 15, 12);
  drawBranch(-15, -h * 0.7, -h * 0.3, -60, 4, 3);
  drawBranch(15, -h * 0.6, -h * 0.25, 50, 4, 3);
  drawBranch(-10, -h * 0.85, -h * 0.2, -40, 3, 2);
  drawBranch(5, -h * 0.9, -h * 0.15, 30, 3, 2);
  drawBranch(-5, -h, -h * 0.1, -20, 2, 2);

  // Reflection in water
  if (baseY < 950) {
    let reflY = 900 + (900 - baseY);
    push();
    translate(0, reflY - baseY + 50);
    scale(1, 0.5);

    for (let i = 0; i < 20; i++) {
      let ry = i * 15;
      let alpha = map(i, 0, 20, 40, 5);
      let offsetX = noise(i * 0.3) * 20 - 10;
      stroke(15, 10, 8, alpha);
      strokeWeight(2);
      line(-10 + offsetX, ry, 10 + offsetX, ry);
    }
    pop();
  }

  pop();
}

function drawBranch(startX, startY, length, angle, weight, depth) {
  if (depth <= 0) return;

  let endX = startX + cos(radians(angle - 90)) * length;
  let endY = startY + sin(radians(angle - 90)) * length;

  strokeWeight(weight);
  line(startX, startY, endX, endY);

  if (depth > 1) {
    drawBranch(endX, endY, length * 0.6, angle - 25, weight * 0.6, depth - 1);
    drawBranch(endX, endY, length * 0.5, angle + 30, weight * 0.6, depth - 1);
  }
}

function drawLeaf(size) {
  beginShape();
  vertex(0, -size);
  bezierVertex(size * 0.5, -size * 0.5, size * 0.5, size * 0.5, 0, size);
  bezierVertex(-size * 0.5, size * 0.5, -size * 0.5, -size * 0.5, 0, -size);
  endShape(CLOSE);
}

function drawBird(x, y, size, alpha) {
  stroke(20, 15, 25, alpha);
  strokeWeight(size * 0.15);
  noFill();

  // Simple bird silhouette - two arcs
  beginShape();
  vertex(x - size, y + size * 0.3);
  quadraticVertex(x - size * 0.3, y - size * 0.2, x, y);
  endShape();

  beginShape();
  vertex(x, y);
  quadraticVertex(x + size * 0.3, y - size * 0.2, x + size, y + size * 0.3);
  endShape();
}

function drawVignette() {
  let maxDist = dist(0, 0, width / 2, height / 2);

  for (let r = maxDist; r > 0; r -= 10) {
    let alpha = map(r, 0, maxDist, 0, 180);
    noFill();
    stroke(0, 0, 5, alpha * 0.3);
    strokeWeight(20);
    ellipse(width / 2, height / 2, r * 2, r * 2 * 1.25);
  }

  // Extra darkness at corners
  noStroke();
  for (let i = 0; i < 50; i++) {
    let alpha = 5;
    fill(0, 0, 5, alpha);
    rect(0, 0, width * (1 - i / 100), height * (1 - i / 100));
    rect(width * i / 100, height * i / 100, width, height);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep gradient background - from dark earth to lighter void
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(15, 12, 20), color(45, 40, 55), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // The dissolving figure
  drawDissolvingFigure();

  // Particles flowing upward and outward - the returning
  drawReturningParticles();

  // Soft mist at the bottom - the earth
  drawMist();

  // Subtle light from above
  drawLight();
}

function drawDissolvingFigure() {
  let centerX = width / 2;
  let baseY = height * 0.75;

  // The figure is built from many layers, each more dissolved toward the top
  for (let layer = 0; layer < 200; layer++) {
    let y = baseY - layer * 4;
    let dissolveAmount = map(y, baseY, baseY - 800, 0, 1);
    dissolveAmount = constrain(dissolveAmount, 0, 1);
    dissolveAmount = pow(dissolveAmount, 0.7);

    // Figure width varies to create human silhouette
    let figureWidth = getFigureWidth(baseY - y);

    // Draw particles that make up this horizontal slice
    let particleCount = floor(map(dissolveAmount, 0, 1, 80, 20));

    for (let i = 0; i < particleCount; i++) {
      let baseX = centerX + map(i, 0, particleCount - 1, -figureWidth/2, figureWidth/2);

      // Displacement increases with dissolution
      let noiseVal = noise(baseX * 0.01, y * 0.01, layer * 0.1);
      let displaceX = (noiseVal - 0.5) * dissolveAmount * 300;
      let displaceY = (noise(baseX * 0.02, y * 0.02) - 0.3) * dissolveAmount * 150;

      let px = baseX + displaceX;
      let py = y + displaceY;

      // Color shifts from warm flesh tones to cool void colors
      let warmColor = color(180, 140, 120, 255);
      let coolColor = color(100, 110, 140, 0);
      let particleColor = lerpColor(warmColor, coolColor, dissolveAmount * 0.9);

      // Size decreases as it dissolves
      let size = map(dissolveAmount, 0, 1, 8, 2);
      size *= random(0.5, 1.5);

      noStroke();
      fill(particleColor);
      ellipse(px, py, size, size * random(1, 1.5));
    }
  }

  // Add some denser core in the lower body
  for (let i = 0; i < 3000; i++) {
    let angle = random(TWO_PI);
    let r = random(1) * random(1) * 150;
    let y = baseY - random(1) * random(1) * 300;
    let figWidth = getFigureWidth(baseY - y) * 0.4;

    let px = centerX + cos(angle) * r * (figWidth / 150);
    let py = y;

    let alpha = map(r, 0, 150, 60, 10);
    fill(160, 130, 115, alpha);
    noStroke();
    ellipse(px, py, random(2, 6), random(2, 6));
  }
}

function getFigureWidth(heightFromBase) {
  // Creates a human-like silhouette
  let h = heightFromBase;

  if (h < 0) return 0;
  if (h < 150) {
    // Legs and lower body
    return map(h, 0, 150, 120, 180);
  } else if (h < 350) {
    // Torso
    return map(h, 150, 350, 180, 160);
  } else if (h < 450) {
    // Shoulders
    let t = map(h, 350, 450, 0, PI);
    return 160 + sin(t) * 80;
  } else if (h < 550) {
    // Neck
    return map(h, 450, 550, 160, 70);
  } else if (h < 700) {
    // Head
    let t = map(h, 550, 700, 0, PI);
    return 70 + sin(t) * 60;
  } else if (h < 800) {
    // Above head - dissolving
    return map(h, 700, 800, 70, 0);
  }
  return 0;
}

function drawReturningParticles() {
  // Particles that have already "returned" - floating in the void
  for (let i = 0; i < 2000; i++) {
    let x = random(width);
    let baseY = random(height * 0.6);

    // They drift upward and outward from center
    let distFromCenter = abs(x - width/2);
    let noiseVal = noise(x * 0.005, baseY * 0.005);

    let y = baseY + (noiseVal - 0.5) * 100;

    // Smaller, fainter, cooler colors
    let alpha = map(baseY, 0, height * 0.6, 10, 40);
    alpha *= map(distFromCenter, 0, width/2, 1.2, 0.5);

    let hue = map(noise(x * 0.01, y * 0.01), 0, 1, 200, 280);
    colorMode(HSB, 360, 100, 100, 255);
    fill(hue, 20, 60, alpha);
    colorMode(RGB, 255);

    noStroke();
    let size = random(1, 4);
    ellipse(x, y, size, size);
  }

  // Streams of particles rising from the figure
  for (let stream = 0; stream < 30; stream++) {
    let startX = width/2 + random(-100, 100);
    let startY = height * 0.4 + random(-50, 50);

    let x = startX;
    let y = startY;

    for (let j = 0; j < 50; j++) {
      x += (noise(x * 0.01, y * 0.01, stream) - 0.5) * 20;
      y -= random(5, 15);

      let alpha = map(j, 0, 50, 50, 5);
      fill(140, 130, 150, alpha);
      noStroke();
      ellipse(x, y, random(2, 5), random(2, 5));
    }
  }
}

function drawMist() {
  // Ground mist - where we come from and return to
  for (let i = 0; i < 5000; i++) {
    let x = random(width);
    let y = height - random(1) * random(1) * random(1) * 400;

    let noiseVal = noise(x * 0.003, y * 0.003);
    y += (noiseVal - 0.5) * 50;

    let alpha = map(y, height, height - 400, 40, 0);
    fill(60, 55, 70, alpha);
    noStroke();
    ellipse(x, y, random(10, 40), random(5, 15));
  }
}

function drawLight() {
  // Soft light from above - not divine, just the void receiving
  for (let i = 0; i < 100; i++) {
    let y = random(height * 0.3);
    let x = width/2 + (random(1) - 0.5) * pow(random(1), 0.5) * width * 0.8;

    let alpha = map(y, 0, height * 0.3, 15, 3);
    fill(200, 195, 210, alpha);
    noStroke();
    ellipse(x, y, random(50, 200), random(20, 60));
  }

  // Central glow where figure dissolves into
  for (let r = 500; r > 0; r -= 10) {
    let alpha = map(r, 0, 500, 8, 0);
    fill(180, 170, 190, alpha);
    noStroke();
    ellipse(width/2, height * 0.2, r * 1.5, r);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep void gradient background
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(15, 12, 20), color(5, 3, 8), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Subtle cosmic dust in background
  noStroke();
  for (let i = 0; i < 3000; i++) {
    let x = random(width);
    let y = random(height);
    let alpha = random(5, 25);
    let size = random(0.5, 2);
    fill(100, 80, 120, alpha);
    ellipse(x, y, size);
  }

  // The river of dissolution - flowing downward
  drawRiverOfSouls();

  // Dissolving particles - the main subject
  drawDissolvingEntities();

  // Floating remnants
  drawRemnants();

  // Soft light from above - the origin
  drawOriginLight();

  // Fine dust settling
  drawSettlingDust();
}

function drawOriginLight() {
  // Soft ethereal glow at top
  for (let i = 50; i > 0; i--) {
    let alpha = map(i, 50, 0, 0, 15);
    let size = map(i, 50, 0, 800, 50);
    fill(255, 250, 240, alpha);
    noStroke();
    ellipse(width/2, -100, size, size * 0.6);
  }

  // Light rays descending
  for (let i = 0; i < 20; i++) {
    let x = width/2 + random(-300, 300);
    let startY = 0;
    let endY = random(200, 600);
    let alpha = random(3, 10);

    stroke(255, 250, 230, alpha);
    strokeWeight(random(1, 4));
    line(x, startY, x + random(-50, 50), endY);
  }
}

function drawRiverOfSouls() {
  // Flowing streams of fading essence
  for (let stream = 0; stream < 8; stream++) {
    let baseX = random(200, width - 200);
    let points = [];
    let x = baseX;
    let y = 0;

    while (y < height) {
      points.push({x: x, y: y});
      y += random(5, 15);
      x += map(noise(x * 0.005, y * 0.003, stream), 0, 1, -30, 30);
    }

    // Draw the stream with fading particles
    for (let i = 0; i < points.length; i++) {
      let p = points[i];
      let progress = p.y / height;

      // Particles become more dispersed and faint as they descend
      let spread = map(progress, 0, 1, 10, 150);
      let particleCount = floor(map(progress, 0, 1, 15, 3));

      for (let j = 0; j < particleCount; j++) {
        let px = p.x + randomGaussian(0, spread);
        let py = p.y + random(-10, 10);
        let alpha = map(progress, 0, 1, 80, 5);
        let size = map(progress, 0, 1, 8, 2);

        // Color shifts from warm to cold as it descends
        let r = map(progress, 0, 1, 255, 60);
        let g = map(progress, 0, 1, 220, 50);
        let b = map(progress, 0, 1, 200, 80);

        fill(r, g, b, alpha);
        noStroke();
        ellipse(px, py, size * random(0.5, 1.5));
      }
    }
  }
}

function drawDissolvingEntities() {
  // Main dissolving forms at various stages
  let entities = [
    {x: 400, y: 400, stage: 0.2, size: 180},
    {x: 1200, y: 350, stage: 0.15, size: 150},
    {x: 800, y: 700, stage: 0.4, size: 220},
    {x: 300, y: 900, stage: 0.55, size: 160},
    {x: 1100, y: 850, stage: 0.5, size: 190},
    {x: 600, y: 1100, stage: 0.65, size: 170},
    {x: 1000, y: 1200, stage: 0.7, size: 140},
    {x: 450, y: 1400, stage: 0.8, size: 130},
    {x: 850, y: 1500, stage: 0.85, size: 120},
    {x: 1150, y: 1550, stage: 0.75, size: 145},
    {x: 650, y: 1750, stage: 0.92, size: 100},
    {x: 950, y: 1850, stage: 0.95, size: 80},
  ];

  for (let e of entities) {
    drawSingleEntity(e.x, e.y, e.stage, e.size);
  }
}

function drawSingleEntity(cx, cy, dissolutionStage, baseSize) {
  // An entity dissolving - more dissolved = more scattered, fainter
  let particleCount = floor(map(dissolutionStage, 0, 1, 500, 100));
  let maxSpread = map(dissolutionStage, 0, 1, baseSize * 0.3, baseSize * 2);
  let coreIntensity = map(dissolutionStage, 0, 1, 1, 0.1);

  // Core glow
  if (dissolutionStage < 0.7) {
    for (let i = 20; i > 0; i--) {
      let alpha = map(i, 20, 0, 0, 30 * coreIntensity);
      let size = map(i, 20, 0, baseSize * 0.8, baseSize * 0.1) * (1 - dissolutionStage * 0.5);

      let r = map(dissolutionStage, 0, 1, 255, 150);
      let g = map(dissolutionStage, 0, 1, 245, 120);
      let b = map(dissolutionStage, 0, 1, 230, 140);

      fill(r, g, b, alpha);
      noStroke();
      ellipse(cx, cy, size);
    }
  }

  // Dissolving particles
  for (let i = 0; i < particleCount; i++) {
    let angle = random(TWO_PI);
    let dist = abs(randomGaussian(0, maxSpread * 0.4));

    // Particles drift downward more as dissolution progresses
    let drift = dissolutionStage * random(50, 150);

    let px = cx + cos(angle) * dist + randomGaussian(0, dissolutionStage * 30);
    let py = cy + sin(angle) * dist + drift * random(0.5, 1.5);

    // Alpha decreases with dissolution and distance
    let distFactor = map(dist, 0, maxSpread, 1, 0.3);
    let alpha = map(dissolutionStage, 0, 1, 150, 20) * distFactor;

    // Size decreases with dissolution
    let size = map(dissolutionStage, 0, 1, 6, 1.5) * random(0.5, 1.5);

    // Color: warm center, cool edges; shifts cooler with dissolution
    let distRatio = dist / maxSpread;
    let r = map(dissolutionStage, 0, 1, 255, 100) * map(distRatio, 0, 1, 1, 0.6);
    let g = map(dissolutionStage, 0, 1, 240, 80) * map(distRatio, 0, 1, 1, 0.7);
    let b = map(dissolutionStage, 0, 1, 220, 120);

    fill(r, g, b, alpha);
    noStroke();
    ellipse(px, py, size);
  }

  // Trailing particles falling from entity
  let trailCount = floor(dissolutionStage * 80);
  for (let i = 0; i < trailCount; i++) {
    let tx = cx + randomGaussian(0, baseSize * 0.3);
    let ty = cy + random(baseSize * 0.5, baseSize * 2 + dissolutionStage * 200);
    let alpha = map(ty - cy, 0, baseSize * 2, 40, 5);
    let size = random(1, 3);

    fill(180, 160, 170, alpha);
    ellipse(tx, ty, size);
  }
}

function drawRemnants() {
  // Scattered fragments throughout
  for (let i = 0; i < 200; i++) {
    let x = random(width);
    let y = random(height);
    let yFactor = y / height;

    // More remnants in lower portions
    if (random() > yFactor * 0.3) continue;

    let alpha = map(yFactor, 0, 1, 40, 15);
    let size = random(2, 8) * map(yFactor, 0, 1, 1, 0.5);

    let r = random(80, 150);
    let g = random(70, 120);
    let b = random(100, 140);

    fill(r, g, b, alpha);
    noStroke();
    ellipse(x, y, size);
  }
}

function drawSettlingDust() {
  // Fine particles near the bottom - what remains
  for (let i = 0; i < 2000; i++) {
    let x = random(width);
    let y = map(pow(random(), 0.5), 0, 1, height * 0.6, height);

    let yFactor = map(y, height * 0.6, height, 0, 1);
    let alpha = random(5, 25) * yFactor;
    let size = random(0.5, 2);

    fill(60, 50, 70, alpha);
    noStroke();
    ellipse(x, y, size);
  }

  // Subtle ground mist
  for (let y = height - 150; y < height; y++) {
    let alpha = map(y, height - 150, height, 0, 20);
    stroke(30, 25, 40, alpha);
    for (let x = 0; x < width; x += 2) {
      let n = noise(x * 0.01, y * 0.01);
      if (n > 0.4) {
        point(x, y);
      }
    }
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep void gradient background
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(5, 5, 20), color(0, 0, 0), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // The abyss - a subtle vortex at the bottom
  drawAbyss();

  // Rising and falling souls
  drawSouls();

  // Central luminous moment - peak of existence
  drawPeakOfExistence();

  // Dissolving particles returning to void
  drawDissolving();

  // Subtle fog layers
  drawFog();
}

function drawAbyss() {
  push();
  translate(width / 2, height + 200);
  noFill();
  for (let i = 0; i < 80; i++) {
    let radius = 300 + i * 15;
    let alpha = map(i, 0, 80, 40, 0);
    stroke(20, 10, 40, alpha);
    strokeWeight(2);
    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.05) {
      let r = radius + noise(i * 0.1, a * 2) * 100;
      let x = cos(a) * r;
      let y = sin(a) * r * 0.3;
      vertex(x, y);
    }
    endShape(CLOSE);
  }
  pop();
}

function drawSouls() {
  // Souls rising from the deep
  for (let i = 0; i < 500; i++) {
    let baseX = random(width);
    let baseY = random(height * 0.5, height);

    let pathOffset = noise(i * 0.1) * 400 - 200;
    let x = baseX + sin(baseY * 0.005 + i) * pathOffset * 0.3;

    // Souls get brighter as they rise, then fade
    let lifeCycle = map(baseY, height, height * 0.5, 0, 1);
    let brightness = sin(lifeCycle * PI) * 255;
    let size = map(lifeCycle, 0, 1, 1, 4) * random(0.5, 1.5);

    // Color shift from cold to warm and back
    let r = map(sin(lifeCycle * PI), 0, 1, 100, 255);
    let g = map(sin(lifeCycle * PI), 0, 1, 80, 200);
    let b = map(cos(lifeCycle * PI * 0.5), 0, 1, 150, 255);

    noStroke();
    fill(r, g, b, brightness * 0.7);
    ellipse(x, baseY, size, size);

    // Glow
    fill(r, g, b, brightness * 0.1);
    ellipse(x, baseY, size * 4, size * 4);
  }
}

function drawPeakOfExistence() {
  // The moment of fullest life - a band of light
  let centerY = height * 0.35;

  for (let i = 0; i < 300; i++) {
    let x = random(width * 0.1, width * 0.9);
    let y = centerY + random(-100, 100);
    let distFromCenter = abs(y - centerY);
    let brightness = map(distFromCenter, 0, 100, 255, 50);

    let size = random(2, 8);

    // Golden white at peak
    noStroke();
    fill(255, 240, 220, brightness * 0.8);
    ellipse(x, y, size, size);

    // Larger glow
    fill(255, 220, 180, brightness * 0.15);
    ellipse(x, y, size * 5, size * 5);
  }

  // Subtle horizontal glow band
  noStroke();
  for (let y = centerY - 150; y < centerY + 150; y++) {
    let alpha = map(abs(y - centerY), 0, 150, 30, 0);
    fill(255, 250, 240, alpha);
    rect(0, y, width, 1);
  }
}

function drawDissolving() {
  // Particles above the peak, fading into nothingness
  for (let i = 0; i < 400; i++) {
    let x = random(width);
    let y = random(0, height * 0.4);

    let fadeProgress = map(y, height * 0.4, 0, 0, 1);
    let alpha = (1 - fadeProgress) * 150;
    let size = (1 - fadeProgress) * random(1, 5);

    // Becoming more blue/cold as they fade
    let r = map(fadeProgress, 0, 1, 200, 50);
    let g = map(fadeProgress, 0, 1, 180, 60);
    let b = map(fadeProgress, 0, 1, 200, 120);

    noStroke();
    fill(r, g, b, alpha);
    ellipse(x, y, size, size);

    // Dispersing trails
    if (random() > 0.7) {
      fill(r, g, b, alpha * 0.3);
      for (let j = 0; j < 3; j++) {
        let tx = x + random(-20, 20);
        let ty = y + random(-10, 10);
        ellipse(tx, ty, size * 0.5, size * 0.5);
      }
    }
  }
}

function drawFog() {
  // Ethereal fog layers
  noStroke();
  for (let layer = 0; layer < 5; layer++) {
    for (let i = 0; i < 50; i++) {
      let x = noise(layer, i * 0.3) * width;
      let y = noise(layer + 10, i * 0.3) * height;
      let size = noise(layer + 20, i * 0.1) * 400 + 100;

      let alpha = 5 + layer * 2;
      fill(30, 20, 50, alpha);
      ellipse(x, y, size, size * 0.6);
    }
  }

  // Final vignette
  drawVignette();
}

function drawVignette() {
  noStroke();
  let maxDist = dist(0, 0, width / 2, height / 2);

  for (let r = maxDist; r > 0; r -= 10) {
    let alpha = map(r, maxDist, maxDist * 0.5, 100, 0);
    alpha = constrain(alpha, 0, 100);
    fill(0, 0, 10, alpha);
    ellipse(width / 2, height / 2, r * 2, r * 2 * (height / width));
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep gradient background - from dark earth to void
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(8, 25, t * t);
    let g = lerp(5, 20, t * t);
    let b = lerp(15, 45, t * t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Horizon glow - dim amber light
  noStroke();
  for (let i = 0; i < 100; i++) {
    let y = map(i, 0, 100, height * 0.55, height * 0.7);
    let alpha = map(i, 0, 100, 25, 0);
    let w = map(i, 0, 100, width * 1.2, width * 0.3);
    fill(80, 50, 30, alpha);
    ellipse(width / 2, y, w, 20);
  }

  // Ground - dark textured earth
  for (let x = 0; x < width; x += 2) {
    for (let y = height * 0.65; y < height; y += 2) {
      let n = noise(x * 0.01, y * 0.01);
      let darkness = map(y, height * 0.65, height, 0.3, 1);
      let c = n * 25 * (1 - darkness);
      fill(c + 5, c + 3, c + 8, 200);
      noStroke();
      rect(x, y, 2, 2);
    }
  }

  // Rising particles - souls ascending
  let particles = [];
  for (let i = 0; i < 3000; i++) {
    let x = random(width);
    let groundY = height * 0.65 + noise(x * 0.005) * 100;
    let startY = groundY + random(-50, 200);
    let progress = random(1);
    let y = lerp(startY, -100, progress * progress);

    // Particles fade as they rise
    let size = map(progress, 0, 1, random(2, 6), random(0.5, 2));
    let alpha = map(progress, 0, 1, 255, 0);
    alpha *= map(y, height * 0.7, 0, 1, 0.3);

    // Color shifts from warm to cool as particles rise
    let warmth = map(progress, 0, 1, 1, 0);
    let r = lerp(60, 180, warmth) + random(-20, 20);
    let g = lerp(70, 140, warmth) + random(-15, 15);
    let b = lerp(120, 100, warmth) + random(-10, 30);

    // Slight horizontal drift based on noise
    x += (noise(i * 0.1, progress * 2) - 0.5) * 150;

    particles.push({x, y, size, alpha, r, g, b, progress});
  }

  // Draw particles with glow
  for (let p of particles) {
    // Outer glow
    noStroke();
    for (let j = 3; j > 0; j--) {
      fill(p.r, p.g, p.b, p.alpha * 0.1 / j);
      ellipse(p.x, p.y, p.size * j * 2, p.size * j * 2);
    }
    // Core
    fill(p.r + 50, p.g + 50, p.b + 30, p.alpha);
    ellipse(p.x, p.y, p.size, p.size);
  }

  // Ethereal mist layers
  for (let layer = 0; layer < 5; layer++) {
    let baseY = height * (0.5 + layer * 0.08);
    for (let x = 0; x < width; x += 10) {
      let y = baseY + noise(x * 0.003, layer * 10) * 150;
      let alpha = 15 - layer * 2;
      fill(40, 45, 70, alpha);
      noStroke();
      ellipse(x, y, random(100, 300), random(30, 80));
    }
  }

  // Delicate threads - connections dissolving
  stroke(100, 90, 120, 15);
  strokeWeight(0.5);
  for (let i = 0; i < 200; i++) {
    let x1 = random(width);
    let y1 = random(height * 0.3, height * 0.7);
    let x2 = x1 + random(-200, 200);
    let y2 = y1 - random(100, 400);

    noFill();
    beginShape();
    for (let t = 0; t <= 1; t += 0.05) {
      let x = lerp(x1, x2, t) + noise(i, t * 5) * 50 - 25;
      let y = lerp(y1, y2, t);
      vertex(x, y);
    }
    endShape();
  }

  // Vignette - drawing focus inward
  for (let i = 0; i < 400; i++) {
    let alpha = map(i, 0, 400, 0, 100);
    noFill();
    stroke(5, 3, 10, alpha * 0.3);
    strokeWeight(3);
    let margin = i * 2;
    rect(-margin, -margin, width + margin * 2, height + margin * 2, 500);
  }

  // Final atmospheric haze at top
  for (let y = 0; y < height * 0.3; y++) {
    let alpha = map(y, 0, height * 0.3, 40, 0);
    stroke(15, 15, 25, alpha);
    line(0, y, width, y);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep gradient background - from warm dark earth to cold void
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(35, 8, t);
    let g = lerp(25, 8, t);
    let b = lerp(30, 15, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Subtle noise texture overlay
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let n = random(-8, 8);
    pixels[i] += n;
    pixels[i + 1] += n;
    pixels[i + 2] += n;
  }
  updatePixels();

  // Rising and dissolving souls/particles
  let particles = [];
  for (let i = 0; i < 800; i++) {
    let x = random(width);
    let baseY = random(height * 1.2);
    particles.push({
      x: x,
      y: baseY,
      size: random(3, 60),
      drift: random(-200, 200),
      life: random(0.3, 1)
    });
  }

  // Sort by y to create depth
  particles.sort((a, b) => b.y - a.y);

  // Draw dissolving circles
  for (let p of particles) {
    let progress = 1 - (p.y / (height * 1.2));
    let dissolve = pow(progress, 1.5);

    // Position drifts as it rises
    let currentX = p.x + p.drift * dissolve * noise(p.x * 0.01, p.y * 0.01);
    let currentY = p.y;

    // Size shrinks then disperses
    let currentSize = p.size * (1 - dissolve * 0.7);

    // Colors fade from warm life to cold void
    let lifeColor = color(180, 80, 70, 255 * p.life);
    let midColor = color(100, 90, 110, 200 * p.life);
    let deathColor = color(30, 30, 45, 50 * p.life);

    let col;
    if (progress < 0.4) {
      col = lerpColor(lifeColor, midColor, progress / 0.4);
    } else {
      col = lerpColor(midColor, deathColor, (progress - 0.4) / 0.6);
    }

    // Draw the dissolving form
    noStroke();

    // Main body
    fill(col);

    // As it dissolves, break into fragments
    if (dissolve > 0.3) {
      let fragments = floor(map(dissolve, 0.3, 1, 1, 12));
      for (let f = 0; f < fragments; f++) {
        let angle = noise(p.x + f, p.y + f) * TWO_PI * 2;
        let dist = dissolve * currentSize * random(0.5, 2);
        let fx = currentX + cos(angle) * dist;
        let fy = currentY + sin(angle) * dist * 0.5;
        let fs = currentSize * random(0.1, 0.4) * (1 - dissolve);

        let fragAlpha = alpha(col) * (1 - dissolve);
        fill(red(col), green(col), blue(col), fragAlpha);
        ellipse(fx, fy, fs, fs * random(0.8, 1.2));
      }
    }

    // Core circle with soft edge
    if (dissolve < 0.8) {
      for (let r = currentSize; r > 0; r -= currentSize * 0.1) {
        let a = map(r, 0, currentSize, alpha(col), alpha(col) * 0.1);
        fill(red(col), green(col), blue(col), a * (1 - dissolve));
        ellipse(currentX, currentY, r, r * (1 + dissolve * 0.3));
      }
    }
  }

  // Add ethereal wisps rising upward
  for (let w = 0; w < 150; w++) {
    let baseX = random(width);
    let baseY = random(height);

    stroke(255, 255, 255, random(5, 25));
    strokeWeight(random(0.5, 2));
    noFill();

    beginShape();
    let wx = baseX;
    let wy = baseY;
    for (let i = 0; i < 20; i++) {
      let n = noise(wx * 0.005, wy * 0.005, w * 0.1);
      wx += map(n, 0, 1, -15, 15);
      wy -= random(5, 20);
      let alpha = map(i, 0, 20, 30, 0);
      stroke(200, 200, 220, alpha);
      curveVertex(wx, wy);
    }
    endShape();
  }

  // Vignette effect
  drawingContext.globalCompositeMode = 'multiply';
  for (let r = max(width, height); r > 0; r -= 5) {
    let alpha = map(r, 0, max(width, height), 0, 100);
    noStroke();
    fill(0, 0, 0, alpha * 0.03);
    ellipse(width/2, height/2, r * 2, r * 2);
  }
  drawingContext.globalCompositeMode = 'source-over';

  // Final soft glow at the very top - the void
  for (let y = 0; y < 400; y++) {
    let alpha = map(y, 0, 400, 60, 0);
    stroke(5, 5, 12, alpha);
    line(0, y, width, y);
  }

  // Delicate floating remnants near top
  for (let i = 0; i < 50; i++) {
    let x = random(width);
    let y = random(300);
    let s = random(1, 4);
    let a = map(y, 0, 300, 10, 40);

    fill(150, 140, 160, a);
    noStroke();
    ellipse(x, y, s, s);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep warm gradient background
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(25, 15, 35), color(45, 20, 30), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Two centers of gravity
  let center1 = { x: width * 0.35, y: height * 0.45 };
  let center2 = { x: width * 0.65, y: height * 0.55 };

  // Draw gravitational field lines
  noFill();
  for (let i = 0; i < 150; i++) {
    let angle = random(TWO_PI);
    let radius = random(100, 700);
    let startX = width/2 + cos(angle) * radius;
    let startY = height/2 + sin(angle) * radius * 1.2;

    stroke(255, 180, 160, 15);
    strokeWeight(1);

    beginShape();
    let x = startX;
    let y = startY;
    for (let j = 0; j < 100; j++) {
      let d1 = dist(x, y, center1.x, center1.y);
      let d2 = dist(x, y, center2.x, center2.y);

      let fx = 0, fy = 0;

      // Attraction to center1
      fx += (center1.x - x) / (d1 * d1) * 5000;
      fy += (center1.y - y) / (d1 * d1) * 5000;

      // Attraction to center2
      fx += (center2.x - x) / (d2 * d2) * 5000;
      fy += (center2.y - y) / (d2 * d2) * 5000;

      let mag = sqrt(fx*fx + fy*fy);
      if (mag > 0) {
        fx = fx/mag * 5;
        fy = fy/mag * 5;
      }

      curveVertex(x, y);
      x += fx + noise(x*0.01, y*0.01) * 2 - 1;
      y += fy + noise(x*0.01, y*0.01, 100) * 2 - 1;
    }
    endShape();
  }

  // Shared atmosphere - overlapping auras
  drawingContext.globalCompositeMode = 'screen';

  // First presence aura
  for (let r = 400; r > 0; r -= 4) {
    let alpha = map(r, 0, 400, 40, 0);
    noStroke();
    fill(180, 60, 90, alpha);
    ellipse(center1.x, center1.y, r * 1.5, r * 1.5);
  }

  // Second presence aura
  for (let r = 400; r > 0; r -= 4) {
    let alpha = map(r, 0, 400, 40, 0);
    noStroke();
    fill(60, 100, 180, alpha);
    ellipse(center2.x, center2.y, r * 1.5, r * 1.5);
  }

  drawingContext.globalCompositeMode = 'source-over';

  // Connecting threads between the two
  for (let i = 0; i < 80; i++) {
    let t = i / 80;
    let offset1 = random(-80, 80);
    let offset2 = random(-80, 80);

    let x1 = center1.x + offset1;
    let y1 = center1.y + offset1 * 0.5;
    let x2 = center2.x + offset2;
    let y2 = center2.y + offset2 * 0.5;

    let midX = (x1 + x2) / 2 + random(-50, 50);
    let midY = (y1 + y2) / 2 + random(-100, 100);

    stroke(255, 200, 180, random(20, 60));
    strokeWeight(random(0.5, 2));
    noFill();

    beginShape();
    curveVertex(x1, y1);
    curveVertex(x1, y1);
    curveVertex(midX, midY);
    curveVertex(x2, y2);
    curveVertex(x2, y2);
    endShape();
  }

  // The two presences - organic, imperfect forms
  drawPresence(center1.x, center1.y, 120, color(220, 80, 100), color(255, 150, 140));
  drawPresence(center2.x, center2.y, 110, color(80, 120, 200), color(150, 180, 255));

  // Particles flowing between them
  for (let i = 0; i < 500; i++) {
    let t = random(1);
    let px = lerp(center1.x, center2.x, t);
    let py = lerp(center1.y, center2.y, t);

    px += noise(i * 0.1, t * 5) * 200 - 100;
    py += noise(i * 0.1 + 100, t * 5) * 200 - 100;

    let particleColor = lerpColor(
      color(255, 150, 150, 150),
      color(150, 180, 255, 150),
      t
    );

    noStroke();
    fill(particleColor);
    let size = random(2, 8);
    ellipse(px, py, size, size);
  }

  // Golden threads of connection at the merge point
  let mergeX = (center1.x + center2.x) / 2;
  let mergeY = (center1.y + center2.y) / 2;

  for (let i = 0; i < 30; i++) {
    let angle = random(TWO_PI);
    let len = random(50, 200);

    stroke(255, 220, 180, 100);
    strokeWeight(random(1, 3));

    let x1 = mergeX + cos(angle) * 20;
    let y1 = mergeY + sin(angle) * 20;
    let x2 = mergeX + cos(angle) * len;
    let y2 = mergeY + sin(angle) * len;

    line(x1, y1, x2, y2);
  }

  // Soft glow at merge point
  for (let r = 150; r > 0; r -= 3) {
    noStroke();
    fill(255, 230, 200, map(r, 0, 150, 30, 0));
    ellipse(mergeX, mergeY, r, r);
  }
}

function drawPresence(cx, cy, baseSize, darkColor, lightColor) {
  // Organic, imperfect form
  push();
  translate(cx, cy);

  // Outer glow layers
  for (let layer = 5; layer > 0; layer--) {
    noStroke();
    let layerSize = baseSize + layer * 30;
    let alpha = map(layer, 0, 5, 80, 10);
    fill(red(lightColor), green(lightColor), blue(lightColor), alpha);

    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.1) {
      let r = layerSize + noise(cos(a) * 2 + cx * 0.01, sin(a) * 2 + cy * 0.01) * 40;
      let x = cos(a) * r;
      let y = sin(a) * r;
      curveVertex(x, y);
    }
    endShape(CLOSE);
  }

  // Core form
  for (let layer = 3; layer > 0; layer--) {
    let layerSize = baseSize * (layer / 3);
    let c = lerpColor(darkColor, lightColor, 1 - layer/3);
    fill(c);
    noStroke();

    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.1) {
      let r = layerSize + noise(cos(a) * 3 + layer, sin(a) * 3 + cx * 0.01) * 20;
      let x = cos(a) * r;
      let y = sin(a) * r;
      curveVertex(x, y);
    }
    endShape(CLOSE);
  }

  // Inner light
  fill(255, 255, 240, 200);
  noStroke();
  ellipse(0, 0, baseSize * 0.3, baseSize * 0.3);

  pop();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep gradient background
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(15, 10, 35), color(45, 20, 60), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Field lines showing gravitational pull between two bodies
  noFill();
  for (let i = 0; i < 200; i++) {
    let startX = random(width);
    let startY = random(height);

    beginShape();
    let x = startX;
    let y = startY;

    for (let j = 0; j < 100; j++) {
      // Two attractors
      let ax1 = 550, ay1 = 850;
      let ax2 = 1050, ay2 = 1150;

      let d1 = dist(x, y, ax1, ay1);
      let d2 = dist(x, y, ax2, ay2);

      let angle1 = atan2(ay1 - y, ax1 - x);
      let angle2 = atan2(ay2 - y, ax2 - x);

      let influence1 = 1 / (d1 * 0.01 + 1);
      let influence2 = 1 / (d2 * 0.01 + 1);

      let angle = (angle1 * influence1 + angle2 * influence2) / (influence1 + influence2);
      angle += noise(x * 0.003, y * 0.003) * PI * 0.5;

      let alpha = map(min(d1, d2), 0, 500, 60, 15);
      let hue = map(d1 / (d1 + d2), 0, 1, 0, 60);
      stroke(lerpColor(color(180, 100, 120, alpha), color(100, 140, 180, alpha), d1 / (d1 + d2)));
      strokeWeight(0.8);

      vertex(x, y);
      x += cos(angle) * 8;
      y += sin(angle) * 8;

      if (x < 0 || x > width || y < 0 || y > height) break;
      if (d1 < 120 || d2 < 120) break;
    }
    endShape();
  }

  // Warm sphere (left)
  drawSphere(550, 850, 200, color(220, 90, 70), color(180, 50, 40), color(255, 180, 140));

  // Cool sphere (right)
  drawSphere(1050, 1150, 180, color(70, 100, 180), color(40, 60, 140), color(150, 180, 255));

  // Connection glow between spheres
  drawConnection(550, 850, 1050, 1150);

  // Particle field
  for (let i = 0; i < 500; i++) {
    let px = random(width);
    let py = random(height);
    let d1 = dist(px, py, 550, 850);
    let d2 = dist(px, py, 1050, 1150);

    if (d1 > 220 && d2 > 200) {
      let size = random(1, 4);
      let alpha = map(min(d1, d2), 200, 800, 180, 20);
      let c = lerpColor(color(255, 200, 180, alpha), color(180, 200, 255, alpha), d1 / (d1 + d2));
      fill(c);
      noStroke();
      ellipse(px, py, size, size);
    }
  }

  // Soft vignette
  drawVignette();
}

function drawSphere(cx, cy, r, baseColor, shadowColor, highlightColor) {
  noStroke();

  // Outer glow
  for (let i = 80; i > 0; i--) {
    let alpha = map(i, 80, 0, 0, 30);
    fill(red(baseColor), green(baseColor), blue(baseColor), alpha);
    ellipse(cx, cy, r * 2 + i * 4, r * 2 + i * 4);
  }

  // Main sphere with gradient
  for (let i = r; i > 0; i--) {
    let inter = map(i, r, 0, 0, 1);
    let c = lerpColor(shadowColor, baseColor, inter);
    fill(c);
    let offsetX = map(i, r, 0, -r * 0.2, 0);
    let offsetY = map(i, r, 0, r * 0.2, 0);
    ellipse(cx + offsetX, cy + offsetY, i * 2, i * 2);
  }

  // Highlight
  fill(highlightColor);
  ellipse(cx - r * 0.35, cy - r * 0.35, r * 0.5, r * 0.4);

  // Softer secondary highlight
  fill(red(highlightColor), green(highlightColor), blue(highlightColor), 100);
  ellipse(cx - r * 0.2, cy - r * 0.5, r * 0.3, r * 0.2);

  // Surface texture
  for (let i = 0; i < 100; i++) {
    let angle = random(TWO_PI);
    let dist = random(r * 0.9);
    let px = cx + cos(angle) * dist;
    let py = cy + sin(angle) * dist;
    let alpha = map(dist, 0, r, 40, 10);
    fill(255, alpha);
    ellipse(px, py, random(2, 6), random(2, 6));
  }
}

function drawConnection(x1, y1, x2, y2) {
  // Glowing connection stream
  let midX = (x1 + x2) / 2;
  let midY = (y1 + y2) / 2;

  for (let i = 0; i < 80; i++) {
    let t = i / 80;
    let px = bezierPoint(x1, midX, midX, x2, t);
    let py = bezierPoint(y1, midY - 100, midY + 100, y2, t);

    let offset = noise(t * 5, i * 0.1) * 60 - 30;
    px += offset;
    py += noise(t * 5 + 100, i * 0.1) * 60 - 30;

    let warmth = map(t, 0, 1, 1, 0);
    let c = lerpColor(color(255, 150, 120, 80), color(120, 150, 255, 80), 1 - warmth);

    fill(c);
    noStroke();
    let size = sin(t * PI) * 30 + 5;
    ellipse(px, py, size, size);
  }

  // Bright core particles along connection
  for (let i = 0; i < 30; i++) {
    let t = random(0.1, 0.9);
    let px = bezierPoint(x1, midX, midX, x2, t);
    let py = bezierPoint(y1, midY - 100, midY + 100, y2, t);
    px += random(-40, 40);
    py += random(-40, 40);

    fill(255, 255, 240, random(100, 200));
    ellipse(px, py, random(3, 8), random(3, 8));
  }
}

function drawVignette() {
  noFill();
  for (let i = 0; i < 400; i++) {
    let alpha = map(i, 0, 400, 0, 150);
    stroke(10, 5, 25, alpha);
    strokeWeight(4);
    rectMode(CENTER);
    rect(width/2, height/2, width - i * 2, height - i * 2.5, 50);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep twilight gradient background
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(15, 10, 35), color(45, 25, 60), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Atmospheric particles in background
  noStroke();
  for (let i = 0; i < 800; i++) {
    let x = random(width);
    let y = random(height);
    let s = random(1, 4);
    let alpha = random(20, 60);
    fill(255, 220, 200, alpha);
    ellipse(x, y, s, s);
  }

  // Two orbital centers
  let center1 = createVector(580, 850);
  let center2 = createVector(1020, 1150);

  // Draw gravitational field lines between them
  stroke(255, 180, 160, 15);
  strokeWeight(1);
  for (let i = 0; i < 150; i++) {
    let t = random(1);
    let startX = lerp(center1.x, center2.x, t) + random(-300, 300);
    let startY = lerp(center1.y, center2.y, t) + random(-300, 300);

    let x = startX;
    let y = startY;

    beginShape();
    noFill();
    for (let j = 0; j < 100; j++) {
      vertex(x, y);

      let toCenter1 = p5.Vector.sub(center1, createVector(x, y));
      let toCenter2 = p5.Vector.sub(center2, createVector(x, y));

      let d1 = max(toCenter1.mag(), 50);
      let d2 = max(toCenter2.mag(), 50);

      toCenter1.normalize().mult(8000 / (d1 * d1));
      toCenter2.normalize().mult(8000 / (d2 * d2));

      let force = p5.Vector.add(toCenter1, toCenter2);
      force.normalize().mult(5);

      x += force.x + noise(x * 0.005, y * 0.005) * 2 - 1;
      y += force.y + noise(y * 0.005, x * 0.005) * 2 - 1;
    }
    endShape();
  }

  // First luminous form - warm spectrum
  drawLuminousForm(center1, 180, [
    color(255, 120, 80, 180),
    color(255, 180, 100, 150),
    color(255, 220, 180, 100),
    color(255, 100, 120, 120)
  ]);

  // Second luminous form - cool spectrum leaning warm
  drawLuminousForm(center2, 160, [
    color(200, 100, 180, 180),
    color(255, 150, 200, 150),
    color(180, 120, 200, 100),
    color(255, 180, 220, 120)
  ]);

  // Shared light between them - the space of connection
  drawConnectionGlow(center1, center2);

  // Orbital rings around each form
  drawOrbits(center1, 220, color(255, 200, 150, 60));
  drawOrbits(center2, 200, color(220, 150, 200, 60));

  // Particles flowing between the two forms
  drawFlowingParticles(center1, center2);

  // Inner cores - brightest points
  noStroke();
  for (let i = 50; i > 0; i--) {
    let alpha = map(i, 50, 0, 5, 255);
    fill(255, 250, 240, alpha);
    ellipse(center1.x, center1.y, i * 1.5, i * 1.5);
  }

  for (let i = 45; i > 0; i--) {
    let alpha = map(i, 45, 0, 5, 255);
    fill(255, 240, 250, alpha);
    ellipse(center2.x, center2.y, i * 1.4, i * 1.4);
  }

  // Delicate threads of connection
  stroke(255, 220, 200, 30);
  strokeWeight(0.5);
  for (let i = 0; i < 50; i++) {
    let angle1 = random(TWO_PI);
    let angle2 = random(TWO_PI);
    let r1 = random(30, 150);
    let r2 = random(30, 130);

    let x1 = center1.x + cos(angle1) * r1;
    let y1 = center1.y + sin(angle1) * r1;
    let x2 = center2.x + cos(angle2) * r2;
    let y2 = center2.y + sin(angle2) * r2;

    let midX = (x1 + x2) / 2 + random(-50, 50);
    let midY = (y1 + y2) / 2 + random(-50, 50);

    noFill();
    beginShape();
    curveVertex(x1, y1);
    curveVertex(x1, y1);
    curveVertex(midX, midY);
    curveVertex(x2, y2);
    curveVertex(x2, y2);
    endShape();
  }
}

function drawLuminousForm(center, baseRadius, colors) {
  noStroke();

  // Multiple layered organic shapes
  for (let layer = 0; layer < 25; layer++) {
    let radius = baseRadius * map(layer, 0, 25, 2.5, 0.3);
    let alpha = map(layer, 0, 25, 10, 80);
    let c = colors[layer % colors.length];
    c.setAlpha(alpha);
    fill(c);

    beginShape();
    for (let angle = 0; angle < TWO_PI; angle += 0.05) {
      let noiseVal = noise(
        cos(angle) * 2 + center.x * 0.01 + layer * 0.1,
        sin(angle) * 2 + center.y * 0.01,
        layer * 0.05
      );
      let r = radius * (0.7 + noiseVal * 0.6);
      let x = center.x + cos(angle) * r;
      let y = center.y + sin(angle) * r;
      vertex(x, y);
    }
    endShape(CLOSE);
  }
}

function drawConnectionGlow(c1, c2) {
  let midX = (c1.x + c2.x) / 2;
  let midY = (c1.y + c2.y) / 2;

  noStroke();
  for (let i = 200; i > 0; i--) {
    let alpha = map(i, 200, 0, 2, 40);
    fill(255, 200, 220, alpha);

    let spreadX = map(i, 200, 0, 400, 20);
    let spreadY = map(i, 200, 0, 300, 15);

    let angle = atan2(c2.y - c1.y, c2.x - c1.x);

    push();
    translate(midX, midY);
    rotate(angle);
    ellipse(0, 0, spreadX, spreadY);
    pop();
  }
}

function drawOrbits(center, radius, col) {
  noFill();
  strokeWeight(1);

  for (let i = 0; i < 5; i++) {
    let r = radius + i * 35;
    let alpha = map(i, 0, 5, 80, 20);
    col.setAlpha(alpha);
    stroke(col);

    beginShape();
    for (let angle = 0; angle < TWO_PI; angle += 0.02) {
      let noiseR = noise(cos(angle) + i, sin(angle) + i, center.x * 0.001) * 30;
      let x = center.x + cos(angle) * (r + noiseR);
      let y = center.y + sin(angle) * (r + noiseR) * 0.6;
      vertex(x, y);
    }
    endShape(CLOSE);
  }
}

function drawFlowingParticles(c1, c2) {
  noStroke();

  for (let i = 0; i < 300; i++) {
    let t = random(1);
    let baseX = lerp(c1.x, c2.x, t);
    let baseY = lerp(c1.y, c2.y, t);

    let perpAngle = atan2(c2.y - c1.y, c2.x - c1.x) + HALF_PI;
    let offset = (noise(t * 5, i * 0.1) - 0.5) * 200;

    let x = baseX + cos(perpAngle) * offset + random(-30, 30);
    let y = baseY + sin(perpAngle) * offset + random(-30, 30);

    let size = random(2, 8);
    let alpha = random(40, 150);

    let col = lerpColor(
      color(255, 180, 150),
      color(220, 160, 220),
      t
    );
    col.setAlpha(alpha);
    fill(col);

    ellipse(x, y, size, size);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep twilight background gradient
  for (let y = 0; y <= height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(25, 20, 45), color(45, 30, 60), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Add subtle noise texture to background
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let n = random(-8, 8);
    pixels[i] += n;
    pixels[i + 1] += n;
    pixels[i + 2] += n;
  }
  updatePixels();

  // The glow between - the third presence
  let centerX = width / 2;
  let centerY = height / 2;

  noStroke();
  for (let r = 500; r > 0; r -= 2) {
    let alpha = map(r, 0, 500, 60, 0);
    fill(255, 180, 140, alpha);
    ellipse(centerX, centerY, r * 1.3, r);
  }

  // Two orbital forms
  let form1X = centerX - 280;
  let form1Y = centerY - 100;
  let form2X = centerX + 280;
  let form2Y = centerY + 100;

  // Draw connecting threads of light between forms
  for (let i = 0; i < 50; i++) {
    let t = i / 50;
    let startX = form1X + random(-80, 80);
    let startY = form1Y + random(-120, 120);
    let endX = form2X + random(-80, 80);
    let endY = form2Y + random(-120, 120);

    stroke(255, 200, 170, 15);
    strokeWeight(random(1, 3));

    let midX = centerX + random(-50, 50);
    let midY = centerY + random(-50, 50);

    noFill();
    beginShape();
    curveVertex(startX, startY);
    curveVertex(startX, startY);
    curveVertex(midX, midY);
    curveVertex(endX, endY);
    curveVertex(endX, endY);
    endShape();
  }

  // Form 1 - warm presence
  drawForm(form1X, form1Y, color(220, 100, 80), color(255, 180, 120), 1);

  // Form 2 - cool presence
  drawForm(form2X, form2Y, color(80, 100, 180), color(140, 180, 220), 2);

  // Particles floating between
  for (let i = 0; i < 200; i++) {
    let px = random(width * 0.2, width * 0.8);
    let py = random(height * 0.25, height * 0.75);
    let d1 = dist(px, py, form1X, form1Y);
    let d2 = dist(px, py, form2X, form2Y);

    let c;
    if (d1 < d2) {
      c = lerpColor(color(255, 180, 120), color(255, 220, 200), d1 / 400);
    } else {
      c = lerpColor(color(140, 180, 220), color(200, 210, 240), d2 / 400);
    }

    fill(red(c), green(c), blue(c), random(40, 120));
    noStroke();
    let size = random(2, 8);
    ellipse(px, py, size, size);
  }

  // Soft vignette
  drawVignette();
}

function drawForm(x, y, innerCol, outerCol, seed) {
  push();
  translate(x, y);

  // Outer glow
  for (let r = 350; r > 0; r -= 3) {
    let alpha = map(r, 0, 350, 100, 0);
    fill(red(outerCol), green(outerCol), blue(outerCol), alpha);
    noStroke();

    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.1) {
      let noiseVal = noise(cos(a) * 2 + seed * 10, sin(a) * 2 + seed * 10, r * 0.01);
      let rad = r * (0.7 + noiseVal * 0.5);
      let px = cos(a) * rad;
      let py = sin(a) * rad * 1.4;
      vertex(px, py);
    }
    endShape(CLOSE);
  }

  // Inner core
  for (let r = 120; r > 0; r -= 2) {
    let inter = map(r, 0, 120, 1, 0);
    let c = lerpColor(color(255, 250, 245), innerCol, inter);
    fill(c);
    noStroke();

    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.15) {
      let noiseVal = noise(cos(a) + seed * 5, sin(a) + seed * 5, r * 0.02);
      let rad = r * (0.8 + noiseVal * 0.3);
      let px = cos(a) * rad;
      let py = sin(a) * rad * 1.3;
      vertex(px, py);
    }
    endShape(CLOSE);
  }

  pop();
}

function drawVignette() {
  noFill();
  for (let i = 0; i < 150; i++) {
    let alpha = map(i, 0, 150, 0, 100);
    stroke(15, 10, 25, alpha);
    strokeWeight(10);
    let offset = i * 5;
    rect(-offset, -offset, width + offset * 2, height + offset * 2, 0);
  }
}

function setup() {
  createCanvas(1600, 2000);
