}

function draw() {
  // Warm, intimate background
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(45, 35, 50), color(85, 55, 45), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Add texture to background
  for (let i = 0; i < 50000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.003, y * 0.003);
    stroke(255, 240, 220, n * 15);
    point(x, y);
  }

  // Golden foundation - pooled light at base
  noStroke();
  for (let i = 0; i < 200; i++) {
    let baseY = height - 300 + random(-50, 150);
    let spread = map(i, 0, 200, 400, 100);
    fill(255, 200, 100, 3);
    ellipse(width/2 + random(-100, 100), baseY, spread + random(100), spread * 0.3);
  }

  // Left figure - deep rose/burgundy tones
  drawFigure(width * 0.38, height * 0.45, -0.15, 
             color(140, 45, 65), color(180, 70, 85), color(90, 25, 40));

  // Right figure - deep blue/teal tones
  drawFigure(width * 0.62, height * 0.45, 0.15, 
             color(45, 80, 120), color(70, 120, 140), color(30, 50, 80));

  // Blending zone where they meet - the permeable edges
  drawBlendingZone();

  // Soft light from connection point
  for (let i = 0; i < 100; i++) {
    let cx = width/2;
    let cy = height * 0.5;
    fill(255, 220, 180, 2);
    ellipse(cx + random(-80, 80), cy + random(-150, 150), random(50, 200));
  }

  // Delicate threads connecting the figures
  stroke(255, 200, 150, 40);
  strokeWeight(1);
  for (let i = 0; i < 50; i++) {
    let y = height * 0.3 + i * 8;
    let x1 = width * 0.42 + noise(i * 0.5) * 30;
    let x2 = width * 0.58 - noise(i * 0.5 + 100) * 30;
    let cy = y + sin(i * 0.3) * 20;
    bezier(x1, y, width * 0.48, cy - 20, width * 0.52, cy + 20, x2, y);
  }

  // Final atmospheric layer
  for (let i = 0; i < 10000; i++) {
    let x = random(width);
    let y = random(height);
    let d = dist(x, y, width/2, height * 0.5);
    if (d < 400) {
      stroke(255, 240, 220, random(5, 15));
      point(x, y);
    }
  }
}

function drawFigure(centerX, centerY, lean, mainColor, lightColor, darkColor) {
  push();
  translate(centerX, centerY);
  rotate(lean);

  // Build figure from many soft shapes
  for (let layer = 0; layer < 80; layer++) {
    let yOff = map(layer, 0, 80, -350, 450);
    let widthMod = sin(map(layer, 0, 80, 0, PI)) * 180 + 40;

    for (let i = 0; i < 30; i++) {
      let x = random(-widthMod, widthMod) * 0.7;
      let y = yOff + random(-30, 30);
      let s = random(30, 80);

      let n = noise(x * 0.01, y * 0.01, layer * 0.1);
      let c;
      if (n < 0.4) c = darkColor;
      else if (n > 0.7) c = lightColor;
      else c = mainColor;

      fill(red(c), green(c), blue(c), random(10, 25));
      noStroke();
      ellipse(x, y, s, s * random(0.8, 1.5));
    }
  }

  // Inner glow
  for (let i = 0; i < 50; i++) {
    fill(255, 220, 200, 5);
    ellipse(random(-40, 40), random(-100, 100), random(20, 60));
  }

  pop();
}

function drawBlendingZone() {
  let zoneX = width / 2;

  // Where colors merge - neither fully one nor the other
  for (let i = 0; i < 3000; i++) {
    let x = zoneX + random(-120, 120);
    let y = height * 0.25 + random(500);

    let n = noise(x * 0.01, y * 0.01);
    let c;
    if (n < 0.5) {
      // Rose bleeding into center
      c = color(140 + random(40), 45 + random(30), 65 + random(40), random(15, 35));
    } else {
      // Blue bleeding into center
      c = color(45 + random(30), 80 + random(40), 120 + random(30), random(15, 35));
    }

    fill(c);
    noStroke();
    ellipse(x, y, random(10, 40));
  }

  // Purple emergence - the new color created by meeting
  for (let i = 0; i < 1000; i++) {
    let x = zoneX + random(-80, 80);
    let y = height * 0.35 + random(300);
    fill(120 + random(30), 60 + random(30), 110 + random(30), random(10, 25));
    ellipse(x, y, random(15, 45));
  }
}

