  // The space between - where love manifests
  let betweenX = (form1X + form2X) / 2;
  let betweenY = (form1Y + form2Y) / 2;

  // Draw gravitational field lines - the bending of space
  noFill();
  for (let i = 0; i < 80; i++) {
    let angle = map(i, 0, 80, 0, TWO_PI);
    let radius = 150 + random(400);

    beginShape();
    for (let t = 0; t < 100; t++) {
      let progress = t / 100;
      let x = lerp(form1X + cos(angle) * radius, form2X + cos(angle + PI) * radius, progress);
      let y = lerp(form1Y + sin(angle) * radius, form2Y + sin(angle + PI) * radius, progress);

      // Curve toward the center
      let pull = sin(progress * PI) * 80;
      x += (betweenX - x) * pull * 0.003;
      y += (betweenY - y) * pull * 0.003;

      let alpha = sin(progress * PI) * 40 + 20;
      stroke(255, 180, 140, alpha);
      strokeWeight(0.5);
      vertex(x, y);
    }
    endShape();
  }

  // Form 1 - warm presence (rose/coral)
  drawPresence(form1X, form1Y, color(200, 80, 90), color(255, 140, 120), 1);

  // Form 2 - cool presence (deep blue/violet)  
  drawPresence(form2X, form2Y, color(80, 70, 160), color(140, 120, 200), 2);

  // The third light - born from proximity
  drawSharedLight(betweenX, betweenY, form1X, form1Y, form2X, form2Y);

  // Particles of exchange - what passes between
  drawExchangeParticles(form1X, form1Y, form2X, form2Y);

  // Soft radiance halos
  drawHalo(form1X, form1Y, color(255, 120, 100, 3), 500);
  drawHalo(form2X, form2Y, color(120, 100, 255, 3), 500);

  // Texture overlay
  for (let i = 0; i < 50000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.01, y * 0.01);
    stroke(255, n * 8);
    point(x, y);
  }
}

function drawPresence(cx, cy, innerColor, outerColor, seed) {
  push();
  // Layered organic form
  for (let layer = 20; layer >= 0; layer--) {
    let size = map(layer, 0, 20, 80, 280);
    let alpha = map(layer, 0, 20, 255, 20);
    let c = lerpColor(innerColor, outerColor, layer / 20);
    c.setAlpha(alpha);
    fill(c);
    noStroke();

    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.1) {
      let r = size;
      let noiseVal = noise(cos(a) * 2 + seed * 10, sin(a) * 2 + seed * 10, layer * 0.1);
      r += noiseVal * 60 - 30;
      r += sin(a * 3 + seed) * 20;
      let x = cx + cos(a) * r;
      let y = cy + sin(a) * r;
      vertex(x, y);
    }
    endShape(CLOSE);
  }

  // Inner glow core
  for (let i = 50; i > 0; i--) {
    let alpha = map(i, 0, 50, 200, 0);
    fill(255, 240, 230, alpha);
    noStroke();
    ellipse(cx, cy, i * 1.5, i * 1.5);
  }
  pop();
}

function drawSharedLight(cx, cy, x1, y1, x2, y2) {
  push();
  // The emergent light between - golden/white warmth
  for (let i = 60; i > 0; i--) {
    let size = i * 4;
    let alpha = map(i, 0, 60, 180, 0);

    // Blend of both colors creating gold
    let c = color(255, 220, 180, alpha);
    fill(c);
    noStroke();

    let offsetX = noise(i * 0.1) * 30 - 15;
    let offsetY = noise(i * 0.1 + 100) * 30 - 15;
    ellipse(cx + offsetX, cy + offsetY, size * 1.2, size);
  }

  // Bright core
  for (let i = 25; i > 0; i--) {
    let alpha = map(i, 0, 25, 255, 100);
    fill(255, 250, 240, alpha);
    noStroke();
    ellipse(cx, cy, i * 2, i * 2);
  }
  pop();
}

function drawExchangeParticles(x1, y1, x2, y2) {
  // Particles flowing between the two forms
  for (let i = 0; i < 200; i++) {
    let t = random(1);
    let x = lerp(x1, x2, t);
    let y = lerp(y1, y2, t);

    // Curve toward center
    let midX = (x1 + x2) / 2;
    let midY = (y1 + y2) / 2;
    let curve = sin(t * PI) * 100;

    let perpX = -(y2 - y1);
    let perpY = (x2 - x1);
    let perpLen = sqrt(perpX * perpX + perpY * perpY);
    perpX /= perpLen;
    perpY /= perpLen;

    x += perpX * curve * random(-0.5, 0.5);
    y += perpY * curve * random(-0.5, 0.5);

    // Add noise displacement
    x += noise(i * 0.1, t) * 60 - 30;
    y += noise(i * 0.1 + 50, t) * 60 - 30;

    // Color gradient from one to other
    let c;
    if (t < 0.5) {
      c = lerpColor(color(255, 140, 120), color(255, 220, 180), t * 2);
    } else {
      c = lerpColor(color(255, 220, 180), color(140, 120, 200), (t - 0.5) * 2);
    }

    let size = random(2, 8);
    let alpha = sin(t * PI) * 200 + 55;
    c.setAlpha(alpha);

    noStroke();
    fill(c);
    ellipse(x, y, size, size);
  }
}

function drawHalo(cx, cy, c, maxRadius) {
  noFill();
  for (let r = maxRadius; r > 50; r -= 2) {
    stroke(c);
    strokeWeight(3);

    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.05) {
      let noiseVal = noise(cos(a) + cx * 0.001, sin(a) + cy * 0.001, r * 0.005);
      let radius = r + noiseVal * 50;
      let x = cx + cos(a) * radius;
      let y = cy + sin(a) * radius;
      vertex(x, y);
    }
    endShape(CLOSE);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep twilight background gradient
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(15, 20, 45), color(45, 25, 50), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Two main bodies - distinct yet drawn together
  let body1X = width * 0.35;
  let body1Y = height * 0.45;
  let body2X = width * 0.65;
  let body2Y = height * 0.55;

  // Gravitational field lines - the bent space between
  noFill();
  for (let i = 0; i < 60; i++) {
    let angle = map(i, 0, 60, 0, TWO_PI);
    let radius = 150 + i * 8;

    strokeWeight(0.5);
    stroke(255, 255, 255, 15);

    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.05) {
      let distTo1 = dist(body1X + cos(a) * radius, body1Y + sin(a) * radius, body1X, body1Y);
      let distTo2 = dist(body1X + cos(a) * radius, body1Y + sin(a) * radius, body2X, body2Y);
      let pull = 30 / (distTo2 * 0.01 + 1);
      let px = body1X + cos(a) * (radius + pull * sin(a * 2));
      let py = body1Y + sin(a) * (radius + pull * cos(a * 3));
      vertex(px, py);
    }
    endShape(CLOSE);
  }

  // Shared warmth - the resonance zone
  let meetX = (body1X + body2X) / 2;
  let meetY = (body1Y + body2Y) / 2;

  for (let i = 200; i > 0; i--) {
    let alpha = map(i, 0, 200, 80, 0);
    let warm = lerpColor(color(255, 180, 100, alpha), color(255, 100, 80, alpha), i/200);
    noStroke();
    fill(warm);
    ellipse(meetX, meetY, i * 2.5, i * 1.8);
  }

  // Streaming particles - shared becoming
  for (let i = 0; i < 800; i++) {
    let t = random(1);
    let px = lerp(body1X, body2X, t);
    let py = lerp(body1Y, body2Y, t);

    let offset = noise(i * 0.1, t * 5) * 100 - 50;
    let curve = sin(t * PI) * 80;
    py += offset + curve * (noise(i * 0.05) - 0.5) * 2;
    px += (noise(i * 0.08, 100) - 0.5) * 60;

    let particleSize = random(1, 4);
    let alpha = map(abs(t - 0.5), 0, 0.5, 200, 50);

    let particleColor = lerpColor(
      color(100, 150, 255, alpha),
      color(255, 150, 180, alpha),
      t
    );

    noStroke();
    fill(particleColor);
    ellipse(px, py, particleSize, particleSize);
  }

  // Body 1 - blue-violet presence
  drawBody(body1X, body1Y, 180, color(80, 100, 200), color(150, 130, 220), color(200, 180, 255));

  // Body 2 - rose-coral presence  
  drawBody(body2X, body2Y, 180, color(200, 90, 100), color(220, 140, 130), color(255, 190, 180));

  // Orbital traces - the dance
  noFill();
  strokeWeight(1);
  for (let j = 0; j < 8; j++) {
    let orbitAlpha = map(j, 0, 8, 60, 10);
    stroke(255, 220, 200, orbitAlpha);

    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.02) {
      let r1 = 250 + j * 25 + noise(a * 2, j) * 30;
      let r2 = 200 + j * 20 + noise(a * 2 + 100, j) * 30;
      let cx = meetX + cos(a + j * 0.3) * 50;
      let cy = meetY + sin(a + j * 0.3) * 30;
      let px = cx + cos(a) * r1;
      let py = cy + sin(a) * r2;
      vertex(px, py);
    }
    endShape(CLOSE);
  }

  // Light rays emanating from connection
  for (let i = 0; i < 40; i++) {
    let angle = random(TWO_PI);
    let len = random(200, 500);
    let sw = random(1, 3);

    stroke(255, 230, 200, random(10, 40));
    strokeWeight(sw);

    let x1 = meetX + cos(angle) * 50;
    let y1 = meetY + sin(angle) * 50;
    let x2 = meetX + cos(angle) * len;
    let y2 = meetY + sin(angle) * len;

    line(x1, y1, x2, y2);
  }

  // Delicate connecting threads
  stroke(255, 255, 255, 30);
  strokeWeight(0.5);
  for (let i = 0; i < 50; i++) {
    let startAngle = random(TWO_PI);
    let endAngle = random(TWO_PI);
    let x1 = body1X + cos(startAngle) * 90;
    let y1 = body1Y + sin(startAngle) * 90;
    let x2 = body2X + cos(endAngle) * 90;
    let y2 = body2Y + sin(endAngle) * 90;

    noFill();
    beginShape();
    vertex(x1, y1);
    let midX = meetX + random(-50, 50);
    let midY = meetY + random(-50, 50);
    quadraticVertex(midX, midY, x2, y2);
    endShape();
  }

  // Small luminous dots scattered
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = random(height);
    let d = dist(x, y, meetX, meetY);
    let alpha = map(d, 0, 600, 150, 20);
    alpha = constrain(alpha, 20, 150);

    fill(255, 255, 240, alpha * random(0.5, 1));
    noStroke();
    ellipse(x, y, random(1, 3), random(1, 3));
  }
}

function drawBody(x, y, size, innerColor, midColor, outerColor) {
  // Outer glow
  for (let i = size + 100; i > size; i--) {
    let alpha = map(i, size, size + 100, 40, 0);
    let glowColor = color(
      red(outerColor),
      green(outerColor),
      blue(outerColor),
      alpha
    );
    noStroke();
    fill(glowColor);
    ellipse(x, y, i * 2, i * 2);
  }

  // Main body gradient
  for (let i = size; i > 0; i--) {
    let inter = map(i, 0, size, 0, 1);
    let c;
    if (inter < 0.5) {
      c = lerpColor(innerColor, midColor, inter * 2);
    } else {
      c = lerpColor(midColor, outerColor, (inter - 0.5) * 2);
    }
    noStroke();
    fill(c);
    ellipse(x, y, i * 2, i * 2);
  }

  // Inner luminosity
  for (let i = 0; i < 20; i++) {
    let angle = random(TWO_PI);
    let dist = random(size * 0.3, size * 0.8);
    let dotX = x + cos(angle) * dist;
    let dotY = y + sin(angle) * dist;
    let dotSize = random(2, 8);

    fill(255, 255, 255, random(30, 80));
    noStroke();
    ellipse(dotX, dotY, dotSize, dotSize);
  }

  // Core brightness
  fill(255, 255, 255, 60);
  ellipse(x - size * 0.2, y - size * 0.2, size * 0.4, size * 0.4);
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep warm background - like twilight intimacy
  background(35, 28, 42);

  // Subtle atmospheric gradient
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(45, 35, 55), color(25, 22, 35), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Add texture to background
  for (let i = 0; i < 50000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.003, y * 0.003);
    fill(255, 240, 230, n * 8);
    noStroke();
    ellipse(x, y, random(1, 3));
  }

  // The two forms - positioned to lean toward each other
  let centerY = height * 0.48;
  let leftCenterX = width * 0.32;
  let rightCenterX = width * 0.68;

  // Draw the luminous space between first (so forms overlay it)
  drawThreshold(width * 0.5, centerY);

  // Left form - warm rose and coral tones
  drawForm(leftCenterX, centerY, 1, [
    color(180, 70, 90),
    color(210, 95, 85),
    color(165, 55, 75),
    color(230, 130, 100)
  ]);

  // Right form - deep blue and violet tones
  drawForm(rightCenterX, centerY, -1, [
    color(65, 85, 145),
    color(90, 75, 130),
    color(50, 95, 160),
    color(110, 90, 155)
  ]);

  // Draw the interpenetrating edges - where colors mix
  drawInterpenetration(leftCenterX, rightCenterX, centerY);

  // Final glow in the threshold
  drawCentralGlow(width * 0.5, centerY);

  // Delicate particles floating between
  drawParticles(width * 0.5, centerY);
}

function drawForm(cx, cy, dir, colors) {
  // Each form is built of many organic layers
  push();
  translate(cx, cy);

  // Slight lean toward center
  rotate(dir * 0.08);

  // Core mass - multiple overlapping organic shapes
  for (let layer = 0; layer < 25; layer++) {
    let baseSize = map(layer, 0, 25, 320, 80);
    let alpha = map(layer, 0, 25, 25, 60);
    let col = colors[layer % colors.length];

    fill(red(col), green(col), blue(col), alpha);
    noStroke();

    beginShape();
    let points = 80;
    for (let i = 0; i < points; i++) {
      let angle = map(i, 0, points, 0, TWO_PI);
      let xoff = cos(angle) * 2 + layer * 0.5;
      let yoff = sin(angle) * 2 + layer * 0.5;
      let r = baseSize;

      // Organic variation
      r += noise(xoff, yoff, layer * 0.1) * 80 - 40;

      // Extend toward the other form (toward center of canvas)
      let towardCenter = cos(angle - dir * PI * 0.5);
      if (towardCenter > 0) {
        r += towardCenter * 60 * noise(layer * 0.3 + i * 0.1);
      }

      // Vertical elongation
      let vertStretch = abs(sin(angle));
      r += vertStretch * 100;

      let x = cos(angle) * r;
      let y = sin(angle) * r * 1.3;
      curveVertex(x, y);
    }
    endShape(CLOSE);
  }

  // Inner luminosity
  for (let i = 0; i < 15; i++) {
    let size = map(i, 0, 15, 180, 20);
    let alpha = map(i, 0, 15, 20, 80);
    fill(255, 240, 230, alpha);
    ellipse(dir * 20, -30, size * 1.2, size * 1.6);
  }

  pop();
}

function drawThreshold(cx, cy) {
  // The space between - glowing with potential
  push();
  translate(cx, cy);

  // Soft vertical glow
  for (let i = 0; i < 40; i++) {
    let w = map(i, 0, 40, 300, 10);
    let h = map(i, 0, 40, 700, 200);
    let alpha = map(i, 0, 40, 8, 35);

    // Warm golden light mixed with both forms' colors
    let r = lerp(255, 200, i / 40);
    let g = lerp(220, 160, i / 40);
    let b = lerp(200, 180, i / 40);

    fill(r, g, b, alpha);
    noStroke();
    ellipse(0, 0, w, h);
  }

  pop();
}

function drawInterpenetration(leftX, rightX, cy) {
  // Where the two forms meet - colors bleeding into each other
  let midX = (leftX + rightX) / 2;

  // Rose particles drifting right
  for (let i = 0; i < 800; i++) {
    let t = random(0.3, 0.7);
    let x = lerp(leftX + 150, midX + 80, t);
    let y = cy + random(-350, 350);

    let n = noise(x * 0.01, y * 0.01, 1);
    if (n > 0.4) {
      let size = random(2, 12) * n;
      let alpha = map(t, 0.3, 0.7, 60, 15);
      fill(200, 85, 95, alpha);
      noStroke();
      ellipse(x + random(-20, 20), y, size);
    }
  }

  // Blue particles drifting left
  for (let i = 0; i < 800; i++) {
    let t = random(0.3, 0.7);
    let x = lerp(rightX - 150, midX - 80, t);
    let y = cy + random(-350, 350);

    let n = noise(x * 0.01, y * 0.01, 2);
    if (n > 0.4) {
      let size = random(2, 12) * n;
      let alpha = map(t, 0.3, 0.7, 60, 15);
      fill(75, 90, 150, alpha);
      noStroke();
      ellipse(x + random(-20, 20), y, size);
    }
  }

  // Mixed color zone in the middle
  for (let i = 0; i < 500; i++) {
    let x = midX + random(-100, 100);
    let y = cy + random(-300, 300);
    let n = noise(x * 0.008, y * 0.008, 3);

    // Violet - the blend of red and blue
    let size = random(3, 15) * n;
    fill(160, 100, 140, 30 * n);
    noStroke();
    ellipse(x, y, size);
  }
}

function drawCentralGlow(cx, cy) {
  // The brightest point - where love is most present
  push();
  translate(cx, cy);

  // Outer halo
  for (let i = 0; i < 30; i++) {
    let size = map(i, 0, 30, 250, 30);
    let alpha = map(i, 0, 30, 5, 50);
    fill(255, 235, 220, alpha);
    noStroke();
    ellipse(0, 0, size, size * 1.4);
  }

  // Core light
  for (let i = 0; i < 15; i++) {
    let size = map(i, 0, 15, 60, 8);
    let alpha = map(i, 0, 15, 40, 120);
    fill(255, 250, 245, alpha);
    ellipse(0, 0, size, size * 1.2);
  }

  pop();
}

function drawParticles(cx, cy) {
  // Small luminous particles floating in the threshold
  for (let i = 0; i < 150; i++) {
    let angle = random(TWO_PI);
    let dist = random(30, 200);
    let x = cx + cos(angle) * dist * 0.8;
    let y = cy + sin(angle) * dist * 1.5;

    let n = noise(x * 0.02, y * 0.02, 5);
    let size = random(2, 6) * n;
    let alpha = random(40, 120) * n;

    fill(255, 245, 235, alpha);
    noStroke();
    ellipse(x, y, size);

    // Tiny glow around each
    fill(255, 240, 220, alpha * 0.3);
    ellipse(x, y, size * 2.5);
  }

  // A few larger, more defined particles
  for (let i = 0; i < 20; i++) {
    let x = cx + random(-120, 120);
    let y = cy + random(-250, 250);

    for (let j = 0; j < 5; j++) {
      let size = map(j, 0, 5, 20, 4);
      let alpha = map(j, 0, 5, 15, 60);
      fill(255, 250, 240, alpha);
      noStroke();
      ellipse(x, y, size);
    }
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Warm, luminous background gradient
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(255, 248, 240), color(255, 235, 220), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Soft atmospheric glow in the center
  drawingContext.filter = 'none';
  noStroke();
  for (let r = 800; r > 0; r -= 2) {
    let alpha = map(r, 800, 0, 0, 40);
    fill(255, 200, 180, alpha);
    ellipse(width/2, height/2, r * 2, r * 2.2);
  }

  // The two forms - abstract, organic shapes leaning toward each other
  drawForm1();
  drawForm2();

  // The resonant space between - particles of light and color
  drawResonantSpace();

  // Delicate threads of connection
  drawConnections();

  // Soft overlay atmosphere
  drawAtmosphere();

  // Subtle texture
  addTexture();
}

function drawForm1() {
  // Left form - warm reds and oranges
  push();
  translate(500, 1000);

  // Soft glow
  noStroke();
  for (let i = 20; i > 0; i--) {
    fill(220, 100, 80, 3);
    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.1) {
      let r = 280 + i * 8 + noise(a * 2, 1) * 100;
      let x = cos(a) * r * 0.8;
      let y = sin(a) * r * 1.2;
      vertex(x, y);
    }
    endShape(CLOSE);
  }

  // Main body - layered organic shape
  for (let layer = 5; layer >= 0; layer--) {
    let baseAlpha = map(layer, 5, 0, 60, 200);
    fill(200 + layer * 10, 80 + layer * 10, 70 + layer * 5, baseAlpha);
    noStroke();
    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.05) {
      let r = 200 - layer * 25 + noise(a * 3 + layer, 2) * 80;
      // Lean toward center
      let lean = map(cos(a), -1, 1, -30, 60);
      let x = cos(a) * r * 0.75 + lean;
      let y = sin(a) * r * 1.1;
      vertex(x, y);
    }
    endShape(CLOSE);
  }

  // Inner warmth
  for (let i = 0; i < 15; i++) {
    let px = random(-80, 80) + 20;
    let py = random(-150, 150);
    let s = random(20, 60);
    fill(255, 150, 100, random(40, 100));
    noStroke();
    ellipse(px, py, s, s * random(0.8, 1.2));
  }

  pop();
}

function drawForm2() {
  // Right form - cool blues and purples leaning left
  push();
  translate(1100, 1000);

  // Soft glow
  noStroke();
  for (let i = 20; i > 0; i--) {
    fill(100, 120, 200, 3);
    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.1) {
      let r = 280 + i * 8 + noise(a * 2, 5) * 100;
      let x = cos(a) * r * 0.8;
      let y = sin(a) * r * 1.2;
      vertex(x, y);
    }
    endShape(CLOSE);
  }

  // Main body
  for (let layer = 5; layer >= 0; layer--) {
    let baseAlpha = map(layer, 5, 0, 60, 200);
    fill(90 + layer * 8, 100 + layer * 12, 180 + layer * 10, baseAlpha);
    noStroke();
    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.05) {
      let r = 200 - layer * 25 + noise(a * 3 + layer, 7) * 80;
      // Lean toward center (opposite direction)
      let lean = map(cos(a), -1, 1, 60, -30);
      let x = cos(a) * r * 0.75 + lean;
      let y = sin(a) * r * 1.1;
      vertex(x, y);
    }
    endShape(CLOSE);
  }

  // Inner depth
  for (let i = 0; i < 15; i++) {
    let px = random(-80, 80) - 20;
    let py = random(-150, 150);
    let s = random(20, 60);
    fill(150, 170, 255, random(40, 100));
    noStroke();
    ellipse(px, py, s, s * random(0.8, 1.2));
  }

  pop();
}

function drawResonantSpace() {
  // The space between - where colors merge and light dances
  let centerX = width / 2;
  let centerY = height / 2;

  // Floating particles of blended color
  for (let i = 0; i < 300; i++) {
    let x = centerX + random(-200, 200);
    let y = centerY + random(-500, 500);
    let distFromCenter = abs(x - centerX);

    // Blend between warm and cool based on position
    let warmth = map(x, centerX - 200, centerX + 200, 1, 0);
    let r = lerp(130, 220, warmth);
    let g = lerp(130, 120, warmth);
    let b = lerp(220, 100, warmth);

    let size = random(3, 25) * map(distFromCenter, 0, 200, 1.5, 0.3);
    let alpha = random(30, 120) * map(distFromCenter, 0, 200, 1, 0.3);

    noStroke();
    fill(r, g, b, alpha);
    ellipse(x, y, size, size * random(0.9, 1.1));
  }

  // Luminous center glow - the light created between
  for (let r = 150; r > 0; r -= 3) {
    let alpha = map(r, 150, 0, 0, 60);
    fill(255, 220, 240, alpha);
    noStroke();
    ellipse(centerX, centerY, r * 1.5, r * 2.5);
  }

  // Golden light particles in the very center
  for (let i = 0; i < 50; i++) {
    let angle = random(TWO_PI);
    let dist = random(10, 100);
    let x = centerX + cos(angle) * dist * 0.7;
    let y = centerY + sin(angle) * dist * 1.5;
    let s = random(2, 12);
    fill(255, 240, 200, random(80, 200));
    noStroke();
    ellipse(x, y, s, s);
  }
}

function drawConnections() {
  // Delicate threads between the forms
  stroke(255, 200, 200, 30);
  strokeWeight(1);
  noFill();

  for (let i = 0; i < 40; i++) {
    let y1 = 600 + random(800);
    let y2 = 600 + random(800);
    let x1 = 580 + noise(i * 0.5, 1) * 50;
    let x2 = 1020 - noise(i * 0.5, 2) * 50;

    let ctrlX1 = lerp(x1, x2, 0.3) + random(-30, 30);
    let ctrlY1 = lerp(y1, y2, 0.3) + random(-50, 50);
    let ctrlX2 = lerp(x1, x2, 0.7) + random(-30, 30);
    let ctrlY2 = lerp(y1, y2, 0.7) + random(-50, 50);

    let alpha = random(15, 50);
    stroke(255, 180 + random(40), 180 + random(40), alpha);
    strokeWeight(random(0.5, 2));

    bezier(x1, y1, ctrlX1, ctrlY1, ctrlX2, ctrlY2, x2, y2);
  }

  // A few stronger connections
  for (let i = 0; i < 8; i++) {
    let y1 = 800 + random(400);
    let y2 = 800 + random(400);
    let x1 = 600;
    let x2 = 1000;

    let midX = width/2;
    let midY = (y1 + y2) / 2 + random(-100, 100);

    stroke(255, 230, 220, 40);
    strokeWeight(random(1, 3));

    bezier(x1, y1, midX, y1, midX, y2, x2, y2);
  }
}

function drawAtmosphere() {
  // Soft floating elements throughout
  noStroke();

  // Upper region - lighter, more ethereal
  for (let i = 0; i < 100; i++) {
    let x = random(width);
    let y = random(height * 0.4);
    let s = random(10, 50);
    let alpha = random(10, 40);
    fill(255, 240, 230, alpha);
    ellipse(x, y, s, s * random(0.8, 1.5));
  }

  // Lower region - grounding warmth
  for (let i = 0; i < 80; i++) {
    let x = random(width);
    let y = height * 0.7 + random(height * 0.3);
    let s = random(15, 60);
    let alpha = random(10, 35);
    fill(230, 200, 190, alpha);
    ellipse(x, y, s, s * random(0.8, 1.2));
  }

  // Scattered light motes
  for (let i = 0; i < 150; i++) {
    let x = random(width);
    let y = random(height);
    let s = random(1, 5);
    let alpha = random(50, 150);
    fill(255, 255, 240, alpha);
    ellipse(x, y, s, s);
  }
}

function addTexture() {
  // Subtle organic texture overlay
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let noiseVal = random(-8, 8);
    pixels[i] = constrain(pixels[i] + noiseVal, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + noiseVal, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + noiseVal, 0, 255);
  }
  updatePixels();

  // Soft vignette
  noFill();
  for (let i = 0; i < 80; i++) {
    let alpha = map(i, 0, 80, 0, 25);
    stroke(40, 30, 35, alpha);
    strokeWeight(10);
    rect(i * 5, i * 5, width - i * 10, height - i * 10, 100);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep twilight background gradient
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(25, 20, 45), color(45, 30, 60), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Two centers of being
  let center1 = { x: width * 0.35, y: height * 0.45 };
  let center2 = { x: width * 0.65, y: height * 0.55 };

  // Core colors for each being
  let palette1 = [
    color(220, 80, 60, 180),   // warm coral
    color(255, 140, 90, 150),  // soft orange
    color(255, 200, 150, 120), // pale peach
    color(180, 50, 70, 160)    // deep rose
  ];

  let palette2 = [
    color(60, 100, 180, 180),  // deep blue
    color(100, 160, 220, 150), // sky blue
    color(150, 200, 230, 120), // pale cyan
    color(70, 60, 140, 160)    // violet
  ];

  // Draw atmospheric glow behind everything
  drawAtmosphericGlow(center1, center2);

  // Draw the interconnecting threads first (behind the forms)
  drawConnectionThreads(center1, center2);

  // Draw each being as layered organic forms
  drawBeing(center1, palette1, 1);
  drawBeing(center2, palette2, -1);

  // Draw the merging zone where they meet
  drawMergingZone(center1, center2, palette1, palette2);

  // Draw floating particles of shared light
  drawSharedLight(center1, center2);

  // Subtle texture overlay
  drawTextureOverlay();

  // Soft vignette
  drawVignette();
}

function drawAtmosphericGlow(c1, c2) {
  noStroke();

  // Glow from first being
  for (let r = 600; r > 0; r -= 8) {
    let alpha = map(r, 600, 0, 0, 30);
    fill(255, 120, 100, alpha);
    ellipse(c1.x, c1.y, r * 1.2, r);
  }

  // Glow from second being
  for (let r = 600; r > 0; r -= 8) {
    let alpha = map(r, 600, 0, 0, 30);
    fill(100, 150, 255, alpha);
    ellipse(c2.x, c2.y, r * 1.2, r);
  }

  // Shared glow in the middle
  let midX = (c1.x + c2.x) / 2;
  let midY = (c1.y + c2.y) / 2;
  for (let r = 400; r > 0; r -= 6) {
    let alpha = map(r, 400, 0, 0, 25);
    fill(200, 150, 220, alpha);
    ellipse(midX, midY, r, r * 1.3);
  }
}

function drawBeing(center, palette, direction) {
  push();
  translate(center.x, center.y);

  // Multiple layered organic shapes
  for (let layer = 5; layer >= 0; layer--) {
    let baseSize = 180 + layer * 50;
    let col = palette[layer % palette.length];

    // Draw organic flowing shape
    for (let ring = 0; ring < 8; ring++) {
      let size = baseSize - ring * 15;
      let alpha = map(ring, 0, 8, 80, 20);
      let c = color(red(col), green(col), blue(col), alpha);
      fill(c);
      noStroke();

      beginShape();
      for (let a = 0; a < TWO_PI; a += 0.05) {
        let xoff = cos(a) * 2 + layer;
        let yoff = sin(a) * 2 + layer;
        let r = size + noise(xoff, yoff, ring * 0.5) * 80 - 40;

        // Extend toward the other being
        if (cos(a) * direction > 0) {
          r += 40 * cos(a) * direction;
        }

        let x = cos(a) * r;
        let y = sin(a) * r * 1.1;
        curveVertex(x, y);
      }
      endShape(CLOSE);
    }
  }

  // Inner luminous core
  for (let r = 80; r > 0; r -= 4) {
    let alpha = map(r, 80, 0, 50, 200);
    fill(255, 250, 240, alpha);
    ellipse(0, 0, r, r * 1.1);
  }

  pop();
}

function drawConnectionThreads(c1, c2) {
  // Flowing threads between the two beings
  for (let i = 0; i < 50; i++) {
    let startAngle = random(-PI/3, PI/3);
    let endAngle = random(PI - PI/3, PI + PI/3);

    let startR = random(100, 200);
    let endR = random(100, 200);

    let x1 = c1.x + cos(startAngle) * startR;
    let y1 = c1.y + sin(startAngle) * startR;
    let x2 = c2.x + cos(endAngle) * endR;
    let y2 = c2.y + sin(endAngle) * endR;

    // Control points for organic curves
    let midX = (x1 + x2) / 2 + random(-100, 100);
    let midY = (y1 + y2) / 2 + random(-150, 150);

    // Gradient along the thread
    let steps = 50;
    noFill();

    for (let s = 0; s < steps - 1; s++) {
      let t1 = s / steps;
      let t2 = (s + 1) / steps;

      // Bezier interpolation
      let px1 = bezierPoint(x1, midX, midX, x2, t1);
      let py1 = bezierPoint(y1, midY, midY, y2, t1);
      let px2 = bezierPoint(x1, midX, midX, x2, t2);
      let py2 = bezierPoint(y1, midY, midY, y2, t2);

      // Color gradient from warm to cool
      let col = lerpColor(
        color(255, 150, 120, 40),
        color(120, 150, 255, 40),
        t1
      );

      stroke(col);
      strokeWeight(random(1, 3));
      line(px1, py1, px2, py2);
    }
  }
}

function drawMergingZone(c1, c2, p1, p2) {
  let midX = (c1.x + c2.x) / 2;
  let midY = (c1.y + c2.y) / 2;

  // The zone where identities blur and new colors emerge
  noStroke();

  for (let i = 0; i < 300; i++) {
    let angle = random(TWO_PI);
    let dist = random(200);
    let x = midX + cos(angle) * dist * 1.5 + random(-30, 30);
    let y = midY + sin(angle) * dist + random(-30, 30);

    // Distance from each center influences color
    let d1 = dist(x, y, c1.x, c1.y);
    let d2 = dist(x, y, c2.x, c2.y);
    let blend = map(d1, d1 + d2 > 0 ? 0 : 1, d1 + d2, 0, 1);
    blend = constrain(blend, 0, 1);

    // Create new colors that neither being has alone
    let newColor;
    if (random() < 0.5) {
      // Violet - the meeting of warm and cool
      newColor = color(
        180 + random(-30, 30),
        100 + random(-30, 30),
        200 + random(-30, 30),
        random(60, 120)
      );
    } else {
      // Soft magenta - another emergent color
      newColor = color(
        220 + random(-20, 20),
        130 + random(-40, 40),
        180 + random(-30, 30),
        random(60, 120)
      );
    }

    fill(newColor);
    let size = random(5, 25);
    ellipse(x, y, size, size * random(0.8, 1.2));
  }

  // Luminous center of meeting
  for (let r = 120; r > 0; r -= 3) {
    let alpha = map(r, 120, 0, 10, 100);
    fill(255, 220, 240, alpha);
    let wobble = noise(r * 0.05) * 30;
    ellipse(midX, midY, r + wobble, r * 1.2 + wobble);
  }
}

function drawSharedLight(c1, c2) {
  // Particles that float in the space between and around
  let midX = (c1.x + c2.x) / 2;
  let midY = (c1.y + c2.y) / 2;

  for (let i = 0; i < 200; i++) {
    let x = random(width);
    let y = random(height);

    // More particles near the beings and their meeting
    let d1 = dist(x, y, c1.x, c1.y);
    let d2 = dist(x, y, c2.x, c2.y);
    let dMid = dist(x, y, midX, midY);

    let probability = map(min(d1, d2, dMid), 0, 500, 1, 0.1);

    if (random() < probability) {
      let size = random(2, 8);
      let alpha = random(100, 200);

      // Color based on proximity
      let col;
      if (d1 < d2 && d1 < dMid) {
        col = color(255, 200, 180, alpha);
      } else if (d2 < d1 && d2 < dMid) {
        col = color(180, 200, 255, alpha);
      } else {
        col = color(240, 210, 255, alpha);
      }

      noStroke();
      fill(col);
      ellipse(x, y, size);

      // Soft glow around particle
      fill(red(col), green(col), blue(col), alpha * 0.3);
      ellipse(x, y, size * 3);
    }
  }
}

function drawTextureOverlay() {
  // Subtle organic texture
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let noiseVal = random(-8, 8);
    pixels[i] = constrain(pixels[i] + noiseVal, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + noiseVal, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + noiseVal, 0, 255);
  }
  updatePixels();
}

function drawVignette() {
  // Soft darkening around edges
  noFill();
  for (let i = 0; i < 150; i++) {
    let alpha = map(i, 0, 150, 0, 60);
    stroke(20, 15, 35, alpha);
    strokeWeight(10);

    let offset = i * 5;
    rect(-offset/2, -offset/2, width + offset, height + offset, 200);
  }
}

function dist(x1, y1, x2, y2) {
  return sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2);
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep background gradient
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(15, 10, 35), color(45, 20, 60), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Ambient particles in background
  noStroke();
  for (let i = 0; i < 500; i++) {
    let x = random(width);
    let y = random(height);
    let s = random(1, 4);
    let alpha = random(30, 80);
    fill(255, 200, 220, alpha);
    ellipse(x, y, s, s);
  }

  // Central glow - love's radiance
  let cx = width / 2;
  let cy = height / 2 - 100;

  for (let r = 800; r > 0; r -= 5) {
    let alpha = map(r, 0, 800, 60, 0);
    let hue = map(r, 0, 800, 30, 300);
    fill(hueToRGB(hue, 0.7, 0.5, alpha));
    noStroke();
    ellipse(cx, cy, r * 2, r * 2);
  }

  // Two intertwining figures - abstract flame forms
  drawFigure(cx - 120, cy + 200, -1, color(220, 80, 100), color(255, 180, 100));
  drawFigure(cx + 120, cy + 200, 1, color(180, 60, 120), color(255, 150, 80));

  // Intertwining ribbons of connection
  drawRibbons(cx, cy);

  // Central heart-like bloom where figures meet
  drawBloom(cx, cy - 50);

  // Floating petals of shared moments
  for (let i = 0; i < 80; i++) {
    let angle = random(TWO_PI);
    let dist = random(100, 700);
    let x = cx + cos(angle) * dist;
    let y = cy + sin(angle) * dist * 0.8;
    let size = random(10, 40);
    let alpha = map(dist, 100, 700, 200, 50);
    drawPetal(x, y, size, random(TWO_PI), alpha);
  }

  // Golden threads of connection
  stroke(255, 215, 150, 40);
  strokeWeight(1);
  for (let i = 0; i < 100; i++) {
    let x1 = cx - 150 + random(-50, 50);
    let y1 = cy + random(-200, 300);
    let x2 = cx + 150 + random(-50, 50);
    let y2 = cy + random(-200, 300);
    bezier(x1, y1, x1 + random(-100, 100), y1 + random(-100, 100),
           x2 + random(-100, 100), y2 + random(-100, 100), x2, y2);
  }

  // Luminous particles around center
  for (let i = 0; i < 300; i++) {
    let angle = random(TWO_PI);
    let dist = random(50, 400);
    let x = cx + cos(angle) * dist;
    let y = cy + sin(angle) * dist * 0.7;
    let s = random(2, 8);
    let alpha = map(dist, 50, 400, 255, 50);
    fill(255, 255, 200, alpha);
    noStroke();
    ellipse(x, y, s, s);
  }
}

function drawFigure(x, y, dir, c1, c2) {
  noStroke();
  for (let i = 0; i < 50; i++) {
    let t = i / 50;
    let yOff = -t * 600;
    let xOff = sin(t * PI * 2) * 80 * dir;
    let size = map(t, 0, 1, 180, 40);
    let c = lerpColor(c1, c2, t);
    c.setAlpha(map(i, 0, 50, 150, 80));
    fill(c);

    let nx = noise(i * 0.1, 0) * 40 - 20;
    let ny = noise(i * 0.1, 100) * 30 - 15;

    ellipse(x + xOff + nx, y + yOff + ny, size, size * 1.3);
  }
}

function drawRibbons(cx, cy) {
  noFill();
  for (let r = 0; r < 20; r++) {
    let alpha = map(r, 0, 20, 100, 30);
    stroke(255, 180, 200, alpha);
    strokeWeight(map(r, 0, 20, 8, 2));

    beginShape();
    for (let t = 0; t <= 1; t += 0.02) {
      let angle = t * PI * 3;
      let radius = 50 + t * 200 + r * 10;
      let x = cx + cos(angle) * radius * (0.5 + noise(t * 3, r) * 0.5);
      let y = cy + sin(angle) * radius * 0.6 - t * 100;
      curveVertex(x, y);
    }
    endShape();
  }
}

function drawBloom(x, y) {
  noStroke();
  // Outer glow
  for (let r = 200; r > 0; r -= 10) {
    let alpha = map(r, 0, 200, 100, 0);
    fill(255, 100, 120, alpha);
    ellipse(x, y, r, r * 0.9);
  }

  // Petals
  for (let i = 0; i < 12; i++) {
    let angle = (TWO_PI / 12) * i;
    push();
    translate(x, y);
    rotate(angle);
    for (let j = 0; j < 5; j++) {
      let alpha = map(j, 0, 5, 180, 60);
      fill(255, 150 + j * 20, 180, alpha);
      ellipse(0, -40 - j * 15, 30 - j * 3, 80 - j * 10);
    }
    pop();
  }

  // Center
  fill(255, 230, 200);
  ellipse(x, y, 60, 60);
  fill(255, 200, 150);
  ellipse(x, y, 40, 40);
}

function drawPetal(x, y, size, angle, alpha) {
  push();
  translate(x, y);
  rotate(angle);
  noStroke();
  fill(255, 180, 190, alpha);
  beginShape();
  vertex(0, -size);
  bezierVertex(size * 0.5, -size * 0.5, size * 0.5, size * 0.5, 0, size);
  bezierVertex(-size * 0.5, size * 0.5, -size * 0.5, -size * 0.5, 0, -size);
  endShape(CLOSE);
  pop();
}

function hueToRGB(h, s, l, a) {
  h = h % 360;
  let c = (1 - abs(2 * l - 1)) * s;
  let x = c * (1 - abs((h / 60) % 2 - 1));
  let m = l - c / 2;
  let r, g, b;

  if (h < 60) { r = c; g = x; b = 0; }
  else if (h < 120) { r = x; g = c; b = 0; }
  else if (h < 180) { r = 0; g = c; b = x; }
  else if (h < 240) { r = 0; g = x; b = c; }
  else if (h < 300) { r = x; g = 0; b = c; }
  else { r = c; g = 0; b = x; }

  return color((r + m) * 255, (g + m) * 255, (b + m) * 255, a);
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep romantic background gradient
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(20, 10, 40), color(60, 20, 50), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Two intertwining figures - abstract flowing forms
  drawFlowingFigure(width * 0.35, height * 0.5, color(200, 60, 80), color(255, 150, 100), -1);
  drawFlowingFigure(width * 0.65, height * 0.5, color(60, 100, 180), color(100, 200, 220), 1);

  // Central fusion glow
  drawFusionCenter();

  // Floating particles of shared energy
  drawLoveParticles();

  // Soft vignette
  drawVignette();
}

function drawFlowingFigure(centerX, centerY, col1, col2, direction) {
  noStroke();

  for (let layer = 0; layer < 50; layer++) {
    let alpha = map(layer, 0, 50, 180, 20);
    let spread = map(layer, 0, 50, 0, 150);

    beginShape();
    for (let t = 0; t < TWO_PI * 3; t += 0.05) {
      let noiseVal = noise(t * 0.5, layer * 0.1, direction);
      let r = 100 + sin(t * 2) * 80 + noiseVal * 100 + spread;
      let x = centerX + cos(t) * r * 0.8 + sin(t * 3) * 50 * direction;
      let y = centerY + sin(t) * r * 1.5 + cos(t * 2) * 30;

      // Lean towards center
      x += direction * map(layer, 0, 50, 50, 200);

      let inter = map(sin(t), -1, 1, 0, 1);
      let c = lerpColor(col1, col2, inter);
      fill(red(c), green(c), blue(c), alpha);

      curveVertex(x, y);
    }
    endShape(CLOSE);
  }
}

function drawFusionCenter() {
  let cx = width / 2;
  let cy = height / 2;

  // Glowing heart-like fusion
  for (let i = 100; i > 0; i--) {
    let alpha = map(i, 100, 0, 5, 200);
    let size = i * 4;

    let r = map(i, 100, 0, 200, 255);
    let g = map(i, 100, 0, 60, 220);
    let b = map(i, 100, 0, 100, 180);

    fill(r, g, b, alpha);
    noStroke();

    // Organic fusion shape
    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.1) {
      let noiseR = noise(a * 2, i * 0.05) * 50;
      let baseR = size + noiseR;
      let x = cx + cos(a) * baseR * 0.6;
      let y = cy + sin(a) * baseR * 0.8;
      curveVertex(x, y);
    }
    endShape(CLOSE);
  }

  // Bright core
  for (let i = 30; i > 0; i--) {
    fill(255, 255, 240, map(i, 30, 0, 50, 255));
    ellipse(cx, cy, i * 3, i * 4);
  }
}

function drawLoveParticles() {
  for (let i = 0; i < 300; i++) {
    let angle = random(TWO_PI);
    let dist = random(100, 800);
    let x = width/2 + cos(angle) * dist * 0.9;
    let y = height/2 + sin(angle) * dist * 1.2;

    let size = random(2, 8);
    let alpha = random(100, 255);

    // Colors blend between warm and cool
    let t = noise(x * 0.01, y * 0.01);
    let c = lerpColor(color(255, 180, 150), color(150, 180, 255), t);

    fill(red(c), green(c), blue(c), alpha);
    noStroke();
    ellipse(x, y, size, size);
  }
}

function drawVignette() {
  for (let i = 0; i < 400; i++) {
    let alpha = map(i, 0, 400, 0, 150);
    noFill();
    stroke(10, 5, 20, alpha);
    strokeWeight(3);
    ellipse(width/2, height/2, width + 400 - i * 3, height + 500 - i * 3.5);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Gradient background - twilight sky
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c1 = color(45, 20, 60);
    let c2 = color(180, 100, 80);
    let c3 = color(255, 180, 120);
    let c;
    if (inter < 0.5) {
      c = lerpColor(c1, c2, inter * 2);
    } else {
      c = lerpColor(c2, c3, (inter - 0.5) * 2);
    }
    stroke(c);
    line(0, y, width, y);
  }

  // Atmospheric texture
  for (let i = 0; i < 50000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.003, y * 0.003);
    let alpha = map(n, 0, 1, 0, 30);
    stroke(255, 200, 150, alpha);
    point(x, y);
  }

  // Two intertwined figures
  let centerX = width / 2;
  let centerY = height * 0.55;

  // Draw embracing forms with flowing brushstrokes
  drawFigures(centerX, centerY);

  // Golden light particles around figures
  for (let i = 0; i < 2000; i++) {
    let angle = random(TWO_PI);
    let radius = random(100, 500);
    let x = centerX + cos(angle) * radius + random(-50, 50);
    let y = centerY + sin(angle) * radius * 0.8 + random(-50, 50);
    let size = random(1, 4);
    let alpha = map(radius, 100, 500, 100, 20);
    fill(255, 220, 180, alpha);
    noStroke();
    ellipse(x, y, size);
  }

  // Soft glow at center
  drawingContext.shadowBlur = 100;
  drawingContext.shadowColor = 'rgba(255, 180, 120, 0.3)';
  noFill();
  stroke(255, 200, 150, 30);
  strokeWeight(50);
  ellipse(centerX, centerY, 400, 500);
  drawingContext.shadowBlur = 0;
}

function drawFigures(cx, cy) {
  // First figure - warm tones
  push();
  translate(cx - 80, cy);
  drawFlowingForm(color(180, 60, 70), color(220, 120, 100), 1);
  pop();

  // Second figure - cool tones merging to warm
  push();
  translate(cx + 80, cy);
  drawFlowingForm(color(100, 70, 140), color(180, 100, 130), -1);
  pop();

  // Intertwining strokes where they meet
  for (let i = 0; i < 500; i++) {
    let t = random(1);
    let y = map(t, 0, 1, cy - 350, cy + 400);
    let xOffset = sin(t * PI * 2 + noise(t * 3) * 2) * 100;
    let x = cx + xOffset + random(-30, 30);

    let c1 = color(180, 60, 70, 100);
    let c2 = color(100, 70, 140, 100);
    let mixed = lerpColor(c1, c2, noise(x * 0.01, y * 0.01));

    stroke(mixed);
    strokeWeight(random(2, 15));
    let len = random(20, 60);
    let angle = noise(x * 0.01, y * 0.01) * PI;
    line(x, y, x + cos(angle) * len, y + sin(angle) * len);
  }
}

function drawFlowingForm(c1, c2, dir) {
  for (let i = 0; i < 800; i++) {
    let t = random(1);
    let y = map(t, 0, 1, -350, 400);
    let w = sin(t * PI) * 150 + noise(t * 5) * 50;
    let x = dir * w * 0.3 + noise(y * 0.01, i * 0.1) * 60 - 30;

    let c = lerpColor(c1, c2, t + random(-0.2, 0.2));
    c.setAlpha(random(80, 180));

    stroke(c);
    strokeWeight(random(3, 20));

    let len = random(30, 80);
    let angle = noise(x * 0.02, y * 0.02) * TWO_PI + dir * 0.5;

    beginShape();
    curveVertex(x, y);
    curveVertex(x, y);
    curveVertex(x + cos(angle) * len * 0.5, y + sin(angle) * len * 0.5);
    curveVertex(x + cos(angle) * len, y + sin(angle) * len);
    curveVertex(x + cos(angle) * len, y + sin(angle) * len);
    endShape();
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep warm gradient background
  for (let y = 0; y < height; y++) {
