    let c = lerpColor(color(45, 20, 40), color(25, 15, 35), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Draw flowing forms
  drawFlowingForm(width * 0.35, height * 0.5, color(180, 50, 70), color(220, 120, 80), -1);
  drawFlowingForm(width * 0.65, height * 0.5, color(40, 60, 120), color(100, 140, 180), 1);

  // Draw intersection glow
  drawIntersectionGlow();

  // Add luminous particles
  drawParticles();

  // Soft vignette
  drawVignette();
}

function drawFlowingForm(centerX, centerY, baseColor, highlightColor, direction) {
  push();
  noStroke();

  for (let layer = 0; layer < 50; layer++) {
    let alpha = map(layer, 0, 50, 180, 10);
    let size = map(layer, 0, 50, 1, 1.5);

    beginShape();
    for (let angle = 0; angle < TWO_PI; angle += 0.02) {
      let baseRadius = 250 + layer * 4;
      let noiseVal = noise(
        cos(angle) * 2 + layer * 0.05 + direction,
        sin(angle) * 2 + layer * 0.05,
        layer * 0.02
      );

      let flowOffset = sin(angle * 3 + layer * 0.1) * 80;
      let verticalStretch = map(sin(angle), -1, 1, 0.7, 1.4);

      let r = (baseRadius * noiseVal * verticalStretch + flowOffset) * size;

      // Lean towards center
      let leanX = direction * layer * 2;

      let x = centerX + cos(angle) * r * 0.8 + leanX;
      let y = centerY + sin(angle) * r * 1.2;

      let colorMix = map(noiseVal, 0.3, 0.7, 0, 1);
      let c = lerpColor(baseColor, highlightColor, colorMix);
      fill(red(c), green(c), blue(c), alpha);

      vertex(x, y);
    }
    endShape(CLOSE);
  }
  pop();
}

function drawIntersectionGlow() {
  push();
  noStroke();
  let centerX = width / 2;
  let centerY = height * 0.5;

  for (let i = 0; i < 100; i++) {
    let radius = map(i, 0, 100, 300, 5);
    let alpha = map(i, 0, 100, 5, 60);

    let r = 200 + i;
    let g = 150 + i * 0.5;
    let b = 180 + i * 0.3;

    fill(r, g, b, alpha);

    beginShape();
    for (let angle = 0; angle < TWO_PI; angle += 0.1) {
      let noiseR = noise(cos(angle) + i * 0.01, sin(angle) + i * 0.01) * 50;
      let x = centerX + cos(angle) * (radius + noiseR) * 0.6;
      let y = centerY + sin(angle) * (radius + noiseR) * 1.2;
      vertex(x, y);
    }
    endShape(CLOSE);
  }
  pop();
}

function drawParticles() {
  push();
  noStroke();

  for (let i = 0; i < 500; i++) {
    let angle = random(TWO_PI);
    let dist = random(100, 600);
    let x = width/2 + cos(angle) * dist * random(0.5, 1.5);
    let y = height/2 + sin(angle) * dist * random(0.8, 1.5);

    let size = random(2, 8);
    let alpha = random(50, 200);

    let colorChoice = random();
    if (colorChoice < 0.33) {
      fill(255, 200, 180, alpha);
    } else if (colorChoice < 0.66) {
      fill(180, 200, 255, alpha);
    } else {
      fill(255, 230, 220, alpha);
    }

    ellipse(x, y, size, size);
  }
  pop();
}

function drawVignette() {
  push();
  noStroke();
  for (let r = max(width, height); r > 0; r -= 10) {
    let alpha = map(r, 0, max(width, height), 0, 150);
    fill(20, 10, 25, alpha * 0.3);
    ellipse(width/2, height/2, r * 2, r * 2.5);
  }
  pop();
}

