function drawFigure(cx, cy, c1, c2, dir) {
  noStroke();

  // Body form - organic flowing shape
  for (let layer = 0; layer < 50; layer++) {
    let alpha = map(layer, 0, 50, 180, 20);
    let size = map(layer, 0, 50, 0, 150);
    fill(lerpColor(c1, c2, layer/50), alpha);

    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.1) {
      let xoff = cos(a) * 2 + 5;
      let yoff = sin(a) * 2 + 5;
      let r = 150 + noise(xoff, yoff, layer * 0.1) * 100 + size;
      r += sin(a * 3 + dir) * 30;
      let x = cx + cos(a) * r * 0.7 + dir * layer * 0.5;
      let y = cy + sin(a) * r - layer * 3;
      curveVertex(x, y);
    }
    endShape(CLOSE);
  }

  // Inner glow
  for (let i = 0; i < 20; i++) {
    let alpha = map(i, 0, 20, 100, 0);
    fill(255, 220, 200, alpha);
    let r = map(i, 0, 20, 50, 200);
    ellipse(cx + dir * 20, cy - 100, r, r * 1.3);
  }
}

function drawBlendZone() {
  // Where the two figures meet - creates new color
  for (let i = 0; i < 500; i++) {
    let x = 800 + randomGaussian(0, 80);
    let y = 800 + randomGaussian(0, 200);
    let size = random(5, 30);
    let alpha = random(30, 100);

    // Purple blend of red and blue
    fill(200, 120, 180, alpha);
    noStroke();
    ellipse(x, y, size, size);
  }

  // Golden sparks at intersection
  for (let i = 0; i < 100; i++) {
    let x = 800 + randomGaussian(0, 50);
    let y = 750 + randomGaussian(0, 100);
    let size = random(2, 8);
    fill(255, 230, 150, random(100, 200));
    ellipse(x, y, size, size);
  }
}

function drawRoots() {
  stroke(100, 70, 60);
  strokeWeight(2);

  for (let i = 0; i < 30; i++) {
    let startX = 800 + random(-200, 200);
    let startY = 1300 + random(0, 100);

    let x = startX;
    let y = startY;

    beginShape();
    noFill();
    for (let j = 0; j < 50; j++) {
      stroke(100, 70, 60, map(j, 0, 50, 150, 0));
      strokeWeight(map(j, 0, 50, 4, 1));
      vertex(x, y);
      x += random(-15, 15);
      y += random(10, 20);
    }
    endShape();
  }
}

function drawParticles() {
  noStroke();
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = random(height);
    let size = random(1, 5);
    let alpha = random(50, 150);

    let hue = random([
      color(255, 180, 180, alpha),
      color(180, 180, 255, alpha),
      color(255, 230, 180, alpha)
    ]);
    fill(hue);
    ellipse(x, y, size, size);
  }
}

function drawVignette() {
  noFill();
  for (let i = 0; i < 200; i++) {
    let alpha = map(i, 0, 200, 0, 150);
    stroke(20, 10, 30, alpha);
    strokeWeight(10);
    let offset = i * 5;
    rect(-offset/2, -offset/2, width + offset, height + offset, 100);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep background gradient
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(10, 5, 30), color(40, 10, 50), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Two soul centers
  let soul1 = { x: width * 0.35, y: height * 0.45 };
  let soul2 = { x: width * 0.65, y: height * 0.55 };

  // Draw gravitational field lines
  drawGravitationalField(soul1, soul2);

  // Draw interconnecting threads
  drawThreads(soul1, soul2);

  // Draw aura layers for both souls
  drawAura(soul1.x, soul1.y, color(255, 100, 120), color(255, 200, 100));
  drawAura(soul2.x, soul2.y, color(100, 150, 255), color(200, 100, 255));

  // Draw the merging zone
  drawMergingZone(soul1, soul2);

  // Draw soul cores
  drawSoulCore(soul1.x, soul1.y, color(255, 180, 190));
  drawSoulCore(soul2.x, soul2.y, color(180, 200, 255));

  // Add floating particles
  drawParticles(soul1, soul2);

  // Add subtle texture overlay
  addTexture();
}

function drawGravitationalField(s1, s2) {
  noFill();
  for (let i = 0; i < 60; i++) {
    let angle = map(i, 0, 60, 0, TWO_PI);
    for (let r = 50; r < 600; r += 15) {
      let distortion = getDistortion(s1.x + cos(angle) * r, s1.y + sin(angle) * r, s1, s2);
      let alpha = map(r, 50, 600, 40, 5);
      stroke(255, 150, 200, alpha);
      strokeWeight(0.5);

      let x1 = s1.x + cos(angle + distortion) * r;
      let y1 = s1.y + sin(angle + distortion) * r;
      let x2 = s1.x + cos(angle + distortion) * (r + 10);
      let y2 = s1.y + sin(angle + distortion) * (r + 10);
      line(x1, y1, x2, y2);
    }
  }

  for (let i = 0; i < 60; i++) {
    let angle = map(i, 0, 60, 0, TWO_PI);
    for (let r = 50; r < 600; r += 15) {
      let distortion = getDistortion(s2.x + cos(angle) * r, s2.y + sin(angle) * r, s1, s2);
      let alpha = map(r, 50, 600, 40, 5);
      stroke(150, 180, 255, alpha);
      strokeWeight(0.5);

      let x1 = s2.x + cos(angle - distortion) * r;
      let y1 = s2.y + sin(angle - distortion) * r;
      let x2 = s2.x + cos(angle - distortion) * (r + 10);
      let y2 = s2.y + sin(angle - distortion) * (r + 10);
      line(x1, y1, x2, y2);
    }
  }
}

function getDistortion(x, y, s1, s2) {
  let d1 = dist(x, y, s1.x, s1.y);
  let d2 = dist(x, y, s2.x, s2.y);
  let midX = (s1.x + s2.x) / 2;
  let midY = (s1.y + s2.y) / 2;
  let dMid = dist(x, y, midX, midY);
  return map(dMid, 0, 500, 0.5, 0) * noise(x * 0.005, y * 0.005);
}

function drawAura(cx, cy, innerCol, outerCol) {
  for (let r = 400; r > 20; r -= 3) {
    let inter = map(r, 400, 20, 0, 1);
    let c = lerpColor(outerCol, innerCol, inter);
    c.setAlpha(map(r, 400, 20, 2, 60));
    noStroke();
    fill(c);

    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.05) {
      let noiseVal = noise(cos(a) * 2 + 5, sin(a) * 2 + 5, r * 0.01);
      let radius = r + noiseVal * 50 - 25;
      let x = cx + cos(a) * radius;
      let y = cy + sin(a) * radius;
      vertex(x, y);
    }
    endShape(CLOSE);
  }
}

function drawThreads(s1, s2) {
  for (let i = 0; i < 80; i++) {
    let offset1 = random(-100, 100);
    let offset2 = random(-100, 100);

    let x1 = s1.x + random(-50, 50);
    let y1 = s1.y + offset1;
    let x2 = s2.x + random(-50, 50);
    let y2 = s2.y + offset2;

    let midX = (x1 + x2) / 2 + random(-30, 30);
    let midY = (y1 + y2) / 2 + random(-50, 50);

    let col = lerpColor(color(255, 150, 180, 30), color(150, 180, 255, 30), random(1));
    stroke(col);
    strokeWeight(random(0.5, 2));
    noFill();

    beginShape();
    curveVertex(x1, y1);
    curveVertex(x1, y1);
    curveVertex(midX, midY);
    curveVertex(x2, y2);
    curveVertex(x2, y2);
    endShape();
  }
}

function drawMergingZone(s1, s2) {
  let midX = (s1.x + s2.x) / 2;
  let midY = (s1.y + s2.y) / 2;

  for (let i = 0; i < 200; i++) {
    let angle = random(TWO_PI);
    let r = random(150);
    let x = midX + cos(angle) * r + random(-20, 20);
    let y = midY + sin(angle) * r + random(-20, 20);

    let size = random(2, 15);
    let alpha = map(r, 0, 150, 100, 20);

    let col = lerpColor(color(255, 180, 200), color(180, 200, 255), noise(x * 0.01, y * 0.01));
    col.setAlpha(alpha);

    noStroke();
    fill(col);
    ellipse(x, y, size, size);
  }

  // Golden light at center
  for (let r = 80; r > 0; r -= 2) {
    let alpha = map(r, 80, 0, 5, 80);
    fill(255, 220, 180, alpha);
    noStroke();
    ellipse(midX, midY, r * 2, r * 2);
  }
}

function drawSoulCore(cx, cy, col) {
  // Outer glow
  for (let r = 120; r > 0; r -= 2) {
    let alpha = map(r, 120, 0, 5, 200);
    let c = color(red(col), green(col), blue(col), alpha);
    noStroke();
    fill(c);
    ellipse(cx, cy, r * 2, r * 2);
  }

  // Inner bright core
  fill(255, 255, 255, 200);
  ellipse(cx, cy, 30, 30);
  fill(255, 255, 255, 255);
  ellipse(cx, cy, 15, 15);
}

function drawParticles(s1, s2) {
  for (let i = 0; i < 500; i++) {
    let x = random(width);
    let y = random(height);

    let d1 = dist(x, y, s1.x, s1.y);
    let d2 = dist(x, y, s2.x, s2.y);
    let dMid = dist(x, y, (s1.x + s2.x) / 2, (s1.y + s2.y) / 2);

    let influence = map(min(d1, d2, dMid), 0, 500, 1, 0);
    influence = constrain(influence, 0, 1);

    if (random(1) < influence * 0.8) {
      let size = random(1, 4) * influence;
      let alpha = random(50, 200) * influence;

      let col;
      if (d1 < d2) {
        col = color(255, 180, 200, alpha);
      } else {
        col = color(180, 200, 255, alpha);
      }

      noStroke();
      fill(col);
      ellipse(x, y, size, size);
    }
  }
}

function addTexture() {
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let noiseVal = random(-10, 10);
    pixels[i] = constrain(pixels[i] + noiseVal, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + noiseVal, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + noiseVal, 0, 255);
  }
  updatePixels();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep cosmic background gradient
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(10, 5, 30), color(40, 15, 50), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Gravitational field lines
  noFill();
  let center1 = {x: width * 0.35, y: height * 0.42};
  let center2 = {x: width * 0.65, y: height * 0.52};

  // Draw warped spacetime grid
  strokeWeight(0.5);
  for (let i = 0; i < 80; i++) {
    let baseY = map(i, 0, 80, -200, height + 200);
    beginShape();
    for (let x = -50; x <= width + 50; x += 5) {
      let distortion1 = getDistortion(x, baseY, center1.x, center1.y, 180);
      let distortion2 = getDistortion(x, baseY, center2.x, center2.y, 160);
      let y = baseY + distortion1 + distortion2;
      let alpha = map(abs(baseY - height/2), 0, height/2, 60, 10);
      stroke(180, 140, 200, alpha);
      vertex(x, y);
    }
    endShape();
  }

  // Vertical field lines
  for (let i = 0; i < 60; i++) {
    let baseX = map(i, 0, 60, -100, width + 100);
    beginShape();
    for (let y = -50; y <= height + 50; y += 5) {
      let distortion1 = getDistortionX(baseX, y, center1.x, center1.y, 150);
      let distortion2 = getDistortionX(baseX, y, center2.x, center2.y, 130);
      let x = baseX + distortion1 + distortion2;
      let alpha = map(abs(baseX - width/2), 0, width/2, 50, 10);
      stroke(140, 160, 200, alpha);
      vertex(x, y);
    }
    endShape();
  }

  // Connection streams between the two souls
  for (let s = 0; s < 150; s++) {
    let t = random(1);
    let startX = lerp(center1.x, center2.x, t);
    let startY = lerp(center1.y, center2.y, t) + random(-300, 300);

    strokeWeight(random(0.3, 1.5));
    let hue1 = color(255, 100, 120, 40);
    let hue2 = color(100, 150, 255, 40);
    stroke(lerpColor(hue1, hue2, t));

    noFill();
    beginShape();
    let px = startX;
    let py = startY;
    for (let i = 0; i < 100; i++) {
      let angle1 = atan2(center1.y - py, center1.x - px);
      let angle2 = atan2(center2.y - py, center2.x - px);
      let d1 = dist(px, py, center1.x, center1.y);
      let d2 = dist(px, py, center2.x, center2.y);
      let influence1 = 1 / (d1 + 50);
      let influence2 = 1 / (d2 + 50);
      let angle = (angle1 * influence1 + angle2 * influence2) / (influence1 + influence2);
      angle += noise(px * 0.005, py * 0.005) * PI - PI/2;
      px += cos(angle) * 8;
      py += sin(angle) * 8;
      vertex(px, py);
    }
    endShape();
  }

  // First luminous soul (warm)
  drawSoul(center1.x, center1.y, 180, color(255, 80, 100), color(255, 200, 150));

  // Second luminous soul (cool)
  drawSoul(center2.x, center2.y, 160, color(80, 100, 255), color(150, 200, 255));

  // Shared glow where gravitational fields overlap
  let midX = (center1.x + center2.x) / 2;
  let midY = (center1.y + center2.y) / 2;

  for (let r = 400; r > 0; r -= 4) {
    let alpha = map(r, 0, 400, 30, 0);
    noStroke();
    fill(255, 180, 220, alpha);
    ellipse(midX, midY, r * 1.5, r);
  }

  // Particle field representing shared essence
  for (let i = 0; i < 2000; i++) {
    let angle = random(TWO_PI);
    let radius = pow(random(1), 0.5) * 600;
    let px = midX + cos(angle) * radius * 1.2;
    let py = midY + sin(angle) * radius * 0.8;

    let d1 = dist(px, py, center1.x, center1.y);
    let d2 = dist(px, py, center2.x, center2.y);

    let warmth = map(d1, 0, 400, 1, 0);
    let coolness = map(d2, 0, 400, 1, 0);

    let c = lerpColor(
      color(255, 150, 180),
      color(150, 180, 255),
      coolness / (warmth + coolness + 0.001)
    );

    let size = random(1, 4) * map(radius, 0, 600, 1.5, 0.3);
    let alpha = map(radius, 0, 600, 200, 20);

    noStroke();
    fill(red(c), green(c), blue(c), alpha);
    ellipse(px, py, size, size);
  }

  // Orbital paths suggesting eternal dance
  noFill();
  strokeWeight(1);
  for (let o = 0; o < 8; o++) {
    let orbitRadius = 200 + o * 40;
    let offsetX = (center2.x - center1.x) / 2;
    let offsetY = (center2.y - center1.y) / 2;

    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.02) {
      let r = orbitRadius + sin(a * 3 + o) * 30 + noise(a + o) * 50;
      let x = midX + cos(a) * r * 1.3;
      let y = midY + sin(a) * r * 0.9;
      let alpha = map(o, 0, 8, 80, 20);
      stroke(255, 220, 240, alpha);
      vertex(x, y);
    }
    endShape(CLOSE);
  }

  // Stars in background
  for (let i = 0; i < 500; i++) {
    let x = random(width);
    let y = random(height);
    let d1 = dist(x, y, center1.x, center1.y);
    let d2 = dist(x, y, center2.x, center2.y);

    if (d1 > 250 && d2 > 220) {
      let size = random(0.5, 2.5);
      let brightness = random(100, 255);
      noStroke();
      fill(brightness, brightness, brightness + random(50), random(100, 200));
      ellipse(x, y, size, size);
    }
  }

  // Final luminous highlights
  drawHighlights(center1.x, center1.y, color(255, 200, 180));
  drawHighlights(center2.x, center2.y, color(180, 200, 255));
}

function getDistortion(x, y, cx, cy, strength) {
  let d = dist(x, y, cx, cy);
  if (d < 1) d = 1;
  return strength * 100 / (d + 100) * (y > cy ? 1 : -1) * map(d, 0, 500, 1, 0.1);
}

function getDistortionX(x, y, cx, cy, strength) {
  let d = dist(x, y, cx, cy);
  if (d < 1) d = 1;
  return strength * 80 / (d + 80) * (x > cx ? 1 : -1) * map(d, 0, 400, 1, 0.1);
}

function drawSoul(x, y, size, innerColor, outerColor) {
  // Outer glow
  for (let r = size * 3; r > 0; r -= 3) {
    let alpha = map(r, 0, size * 3, 50, 0);
    let c = lerpColor(innerColor, outerColor, map(r, 0, size * 3, 0, 1));
    noStroke();
    fill(red(c), green(c), blue(c), alpha);
    ellipse(x, y, r * 2, r * 2);
  }

  // Core with texture
  for (let i = 0; i < 500; i++) {
    let angle = random(TWO_PI);
    let radius = pow(random(1), 2) * size;
    let px = x + cos(angle) * radius;
    let py = y + sin(angle) * radius;
    let alpha = map(radius, 0, size, 255, 50);
    let psize = map(radius, 0, size, 8, 1);

    let c = lerpColor(innerColor, outerColor, radius / size);
    noStroke();
    fill(red(c), green(c), blue(c), alpha);
    ellipse(px, py, psize, psize);
  }

  // Bright center
  fill(255, 255, 255, 200);
  ellipse(x, y, size * 0.3, size * 0.3);
  fill(255, 255, 255, 100);
  ellipse(x, y, size * 0.5, size * 0.5);
}

function drawHighlights(x, y, c) {
  for (let i = 0; i < 30; i++) {
    let angle = random(TWO_PI);
    let radius = random(80, 200);
    let px = x + cos(angle) * radius;
    let py = y + sin(angle) * radius;

    noStroke();
    fill(red(c), green(c), blue(c), random(50, 150));
    ellipse(px, py, random(2, 6), random(2, 6));
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  background(10, 8, 20);

  // Deep background gradient
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(15, 10, 35), color(5, 5, 15), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Gravitational field lines
  noFill();
  let cx1 = 550, cy1 = 850;
  let cx2 = 1050, cy2 = 1150;

  for (let i = 0; i < 200; i++) {
    let angle = random(TWO_PI);
    let startDist = random(800, 1200);
    let x = width/2 + cos(angle) * startDist;
    let y = height/2 + sin(angle) * startDist;

    stroke(255, 180, 200, 8);
    strokeWeight(0.5);
    beginShape();
    for (let j = 0; j < 500; j++) {
      vertex(x, y);
      let d1 = dist(x, y, cx1, cy1) + 1;
      let d2 = dist(x, y, cx2, cy2) + 1;
      let fx = (cx1 - x) / (d1 * d1) * 800 + (cx2 - x) / (d2 * d2) * 800;
      let fy = (cy1 - y) / (d1 * d1) * 800 + (cy2 - y) / (d2 * d2) * 800;
      x += fx * 2;
      y += fy * 2;
      if (d1 < 80 || d2 < 80) break;
    }
    endShape();
  }

  // Shared luminous field between the two beings
  drawingContext.globalCompositeMode = 'lighter';
  for (let i = 0; i < 3000; i++) {
    let t = random(1);
    let px = lerp(cx1, cx2, t) + randomGaussian(0, 60 * sin(t * PI));
    let py = lerp(cy1, cy2, t) + randomGaussian(0, 60 * sin(t * PI));
    let brightness = sin(t * PI) * 255;
    let size = random(1, 4) * sin(t * PI);
    noStroke();
    fill(255, 220, 240, brightness * 0.3);
    ellipse(px, py, size);
  }

  // First celestial body - warm tones
  drawCelestialBody(cx1, cy1, 120, color(255, 100, 80), color(255, 200, 150));

  // Second celestial body - cool tones
  drawCelestialBody(cx2, cy2, 100, color(80, 100, 255), color(180, 200, 255));

  // Orbital particles between them
  for (let i = 0; i < 800; i++) {
    let t = random(1);
    let orbitX = lerp(cx1, cx2, t);
    let orbitY = lerp(cy1, cy2, t);
    let angle = random(TWO_PI);
    let orbitDist = 30 + sin(t * PI) * 150 * random(0.5, 1);
    let px = orbitX + cos(angle) * orbitDist * random(0.8, 1.2);
    let py = orbitY + sin(angle) * orbitDist * random(0.8, 1.2);
    let particleColor = lerpColor(color(255, 150, 120), color(150, 180, 255), t);
    particleColor.setAlpha(random(50, 200));
    noStroke();
    fill(particleColor);
    ellipse(px, py, random(1, 5));
  }

  // Ethereal connecting threads
  for (let i = 0; i < 50; i++) {
    let offset1 = random(-60, 60);
    let offset2 = random(-60, 60);
    stroke(255, 220, 230, 20);
    strokeWeight(random(0.5, 2));
    noFill();
    beginShape();
    for (let t = 0; t <= 1; t += 0.02) {
      let x = lerp(cx1, cx2, t);
      let y = lerp(cy1 + offset1, cy2 + offset2, t);
      let wave = sin(t * PI * 3 + i) * 40 * sin(t * PI);
      let nx = noise(t * 3, i * 0.1) * 60 - 30;
      vertex(x + nx, y + wave);
    }
    endShape();
  }

  // Ambient particles throughout
  for (let i = 0; i < 500; i++) {
    let x = random(width);
    let y = random(height);
    let d1 = dist(x, y, cx1, cy1);
    let d2 = dist(x, y, cx2, cy2);
    let brightness = map(min(d1, d2), 0, 600, 255, 20);
    fill(255, 200, 220, brightness * 0.3);
    noStroke();
    ellipse(x, y, random(1, 3));
  }

  drawingContext.globalCompositeMode = 'source-over';
}

function drawCelestialBody(cx, cy, radius, coreColor, glowColor) {
  // Outer glow
  for (let r = radius * 5; r > radius; r -= 3) {
    let alpha = map(r, radius, radius * 5, 60, 0);
    let c = lerpColor(coreColor, glowColor, map(r, radius, radius * 5, 0, 1));
    c.setAlpha(alpha);
    noStroke();
    fill(c);
    ellipse(cx, cy, r * 2);
  }

  // Core with texture
  for (let i = 0; i < 2000; i++) {
    let angle = random(TWO_PI);
    let r = randomGaussian(0, radius * 0.4);
    r = constrain(abs(r), 0, radius);
    let x = cx + cos(angle) * r;
    let y = cy + sin(angle) * r;
    let bright = map(r, 0, radius, 1, 0.3);
    let c = lerpColor(color(255), coreColor, map(r, 0, radius, 0, 1));
    c.setAlpha(bright * 255);
    noStroke();
    fill(c);
    ellipse(x, y, random(1, 4));
  }

  // Bright center
  fill(255, 255, 255, 200);
  ellipse(cx, cy, radius * 0.3);
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep background gradient
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(10, 5, 25), color(25, 10, 35), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Two soul centers
  let soul1 = { x: 580, y: 850 };
  let soul2 = { x: 1020, y: 1150 };

  // Draw gravitational field lines
  drawGravitationalField(soul1, soul2);

  // Draw intermingling auras
  drawAuras(soul1, soul2);

  // Draw the souls themselves
  drawSoul(soul1.x, soul1.y, color(255, 180, 120), color(255, 100, 80));
  drawSoul(soul2.x, soul2.y, color(120, 180, 255), color(80, 100, 255));

  // Draw the light born between them
  drawSharedLight(soul1, soul2);

  // Particle field
  drawParticles(soul1, soul2);

  // Soft vignette
  drawVignette();
}

function drawGravitationalField(s1, s2) {
  noFill();
  for (let i = 0; i < 60; i++) {
    let angle = map(i, 0, 60, 0, TWO_PI);

    for (let r = 50; r < 600; r += 15) {
      let alpha = map(r, 50, 600, 40, 5);
      stroke(255, 200, 220, alpha);
      strokeWeight(0.5);

      beginShape();
      for (let t = 0; t < 100; t++) {
        let progress = t / 100;
        let x1 = s1.x + cos(angle + progress * 0.5) * r * (1 - progress * 0.3);
        let y1 = s1.y + sin(angle + progress * 0.5) * r * (1 - progress * 0.3);
        let x2 = s2.x + cos(angle + PI + progress * 0.5) * r * (1 - progress * 0.3);
        let y2 = s2.y + sin(angle + PI + progress * 0.5) * r * (1 - progress * 0.3);

        let x = lerp(x1, x2, progress);
        let y = lerp(y1, y2, progress);
        x += noise(t * 0.1, i * 0.1) * 30 - 15;
        y += noise(t * 0.1 + 100, i * 0.1) * 30 - 15;

        curveVertex(x, y);
      }
      endShape();
    }
  }
}

function drawAuras(s1, s2) {
  // Soul 1 aura - warm
  for (let layer = 0; layer < 50; layer++) {
    let radius = 400 - layer * 6;
    let alpha = map(layer, 0, 50, 3, 15);

    noStroke();
    for (let a = 0; a < TWO_PI; a += 0.02) {
      let r = radius + noise(a * 2, layer * 0.1) * 80;
      let x = s1.x + cos(a) * r;
      let y = s1.y + sin(a) * r;

      // Extend toward soul2
      let distToS2 = dist(x, y, s2.x, s2.y);
      if (distToS2 < 500) {
        r += map(distToS2, 500, 0, 0, 100);
        x = s1.x + cos(a) * r;
        y = s1.y + sin(a) * r;
      }

      fill(255, 150 + layer * 2, 100, alpha);
      ellipse(x, y, 8, 8);
    }
  }

  // Soul 2 aura - cool
  for (let layer = 0; layer < 50; layer++) {
    let radius = 400 - layer * 6;
    let alpha = map(layer, 0, 50, 3, 15);

    noStroke();
    for (let a = 0; a < TWO_PI; a += 0.02) {
      let r = radius + noise(a * 2 + 50, layer * 0.1) * 80;
      let x = s2.x + cos(a) * r;
      let y = s2.y + sin(a) * r;

      let distToS1 = dist(x, y, s1.x, s1.y);
      if (distToS1 < 500) {
        r += map(distToS1, 500, 0, 0, 100);
        x = s2.x + cos(a) * r;
        y = s2.y + sin(a) * r;
      }

      fill(100, 150 + layer * 2, 255, alpha);
      ellipse(x, y, 8, 8);
    }
  }
}

function drawSoul(x, y, c1, c2) {
  // Core glow
  for (let r = 200; r > 0; r -= 2) {
    let alpha = map(r, 200, 0, 0, 255);
    let c = lerpColor(c2, c1, map(r, 200, 0, 0, 1));
    noStroke();
    fill(red(c), green(c), blue(c), alpha * 0.3);

    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.1) {
      let radius = r + noise(a * 3, r * 0.02) * 20;
      let px = x + cos(a) * radius;
      let py = y + sin(a) * radius;
      vertex(px, py);
    }
    endShape(CLOSE);
  }

  // Bright center
  fill(255, 255, 240, 200);
  noStroke();
  ellipse(x, y, 40, 40);
  fill(255, 255, 255);
  ellipse(x, y, 20, 20);
}

function drawSharedLight(s1, s2) {
  let midX = (s1.x + s2.x) / 2;
  let midY = (s1.y + s2.y) / 2;

  // The new light born from union
  for (let layer = 0; layer < 80; layer++) {
    let radius = 250 - layer * 2.5;
    let alpha = map(layer, 0, 80, 2, 20);

    noStroke();

    for (let a = 0; a < TWO_PI; a += 0.03) {
      let r = radius + noise(a * 4, layer * 0.05 + 200) * 60;
      let x = midX + cos(a) * r;
      let y = midY + sin(a) * r;

      // Color blend - purple/magenta from mixing warm and cool
      let purple = color(220, 130, 255, alpha);
      let gold = color(255, 220, 150, alpha);
      let c = lerpColor(purple, gold, noise(a, layer * 0.1));

      fill(c);
      ellipse(x, y, 10, 10);
    }
  }

  // Central bright point of union
  for (let r = 100; r > 0; r -= 2) {
    let alpha = map(r, 100, 0, 10, 200);
    fill(255, 220, 255, alpha);
    noStroke();
    ellipse(midX, midY, r, r);
  }

  fill(255);
  ellipse(midX, midY, 15, 15);
}

function drawParticles(s1, s2) {
  let midX = (s1.x + s2.x) / 2;
  let midY = (s1.y + s2.y) / 2;

  for (let i = 0; i < 800; i++) {
    let angle = random(TWO_PI);
    let dist1 = random(50, 700);

    let baseX, baseY, c;
    let choice = random();

    if (choice < 0.33) {
      baseX = s1.x;
      baseY = s1.y;
      c = color(255, 180 + random(75), 100 + random(50), random(50, 150));
    } else if (choice < 0.66) {
      baseX = s2.x;
      baseY = s2.y;
      c = color(100 + random(50), 180 + random(75), 255, random(50, 150));
    } else {
      baseX = midX;
      baseY = midY;
      c = color(255, 180 + random(75), 255, random(50, 150));
    }

    let x = baseX + cos(angle) * dist1;
    let y = baseY + sin(angle) * dist1;

    if (x > 0 && x < width && y > 0 && y < height) {
      noStroke();
      fill(c);
      let size = random(1, 5);
      ellipse(x, y, size, size);
    }
  }
}

function drawVignette() {
  for (let r = 1200; r < 1800; r += 2) {
    let alpha = map(r, 1200, 1800, 0, 150);
    noFill();
    stroke(10, 5, 25, alpha);
    strokeWeight(4);
    ellipse(width/2, height/2, r * 1.6, r * 2);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep warm background
  background(25, 20, 35);

  // Create subtle textured background
  for (let i = 0; i < 50000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.003, y * 0.003);
    stroke(40 + n * 20, 30 + n * 15, 50 + n * 20, 15);
    point(x, y);
  }

  // Two luminous presences - left and right
  let leftCenter = { x: 550, y: 1000 };
  let rightCenter = { x: 1050, y: 1000 };

  // Draw the threshold space between - the vibrant interval
  drawThreshold(leftCenter, rightCenter);

  // Draw the two presences
  drawPresence(leftCenter.x, leftCenter.y, color(180, 80, 60), color(255, 180, 120));
  drawPresence(rightCenter.x, rightCenter.y, color(60, 80, 160), color(120, 180, 255));

  // Resonance particles in the threshold
  drawResonance(leftCenter, rightCenter);

  // Soft overall glow
  drawAtmosphere();
}

function drawPresence(cx, cy, baseColor, lightColor) {
  noStroke();

  // Outer glow layers
  for (let r = 400; r > 0; r -= 4) {
    let alpha = map(r, 400, 0, 0, 40);
    let inter = map(r, 400, 0, 0, 1);
    let c = lerpColor(baseColor, lightColor, inter);
    fill(red(c), green(c), blue(c), alpha);

    // Organic shape using noise
    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.05) {
      let n = noise(cx * 0.01 + cos(a) * 2, cy * 0.01 + sin(a) * 2, r * 0.01);
      let radius = r * (0.8 + n * 0.4);
      let x = cx + cos(a) * radius;
      let y = cy + sin(a) * radius;
      vertex(x, y);
    }
    endShape(CLOSE);
  }

  // Inner luminous core
  for (let r = 80; r > 0; r -= 2) {
    let alpha = map(r, 80, 0, 100, 255);
    fill(255, 250, 240, alpha);
    ellipse(cx, cy, r, r);
  }

  // Emanating particles
  for (let i = 0; i < 200; i++) {
    let angle = random(TWO_PI);
    let dist = random(50, 350);
    let n = noise(i * 0.5, cx * 0.01);
    dist *= (0.5 + n);
    let x = cx + cos(angle) * dist;
    let y = cy + sin(angle) * dist;
    let size = random(1, 4);
    let alpha = map(dist, 50, 350, 180, 20);
    fill(red(lightColor), green(lightColor), blue(lightColor), alpha);
    noStroke();
    ellipse(x, y, size, size);
  }
}

function drawThreshold(left, right) {
  let midX = (left.x + right.x) / 2;
  let midY = (left.y + right.y) / 2;

  // The threshold - a vertical luminous band
  noStroke();

  for (let i = 0; i < 100; i++) {
    let x = midX + random(-60, 60);
    let yStart = random(300, 600);
    let yEnd = random(1400, 1700);

    for (let y = yStart; y < yEnd; y += 3) {
      let n = noise(x * 0.02, y * 0.01, i * 0.1);
      let xOff = sin(y * 0.01 + i) * 30 * n;

      // Golden light in the threshold
      let alpha = map(abs(y - midY), 0, 600, 60, 10) * n;
      fill(255, 220, 180, alpha);
      ellipse(x + xOff, y, 8 * n, 8 * n);
    }
  }

  // Vertical luminous streams
  for (let i = 0; i < 30; i++) {
    let x = midX + random(-80, 80);
    let streamAlpha = random(20, 50);

    beginShape();
    noFill();
    stroke(255, 230, 200, streamAlpha);
    strokeWeight(random(1, 3));

    for (let y = 200; y < 1800; y += 10) {
      let n = noise(x * 0.01, y * 0.005, i);
      let xPos = x + sin(y * 0.008 + i) * 40 * n;
      vertex(xPos, y);
    }
    endShape();
  }
}

function drawResonance(left, right) {
  let midX = (left.x + right.x) / 2;

  // Particles that float in the threshold space
  for (let i = 0; i < 500; i++) {
    let t = random(1);
    let x = lerp(left.x + 100, right.x - 100, t);
    let y = random(400, 1600);

    let distToMid = abs(x - midX);
    let inThreshold = distToMid < 100;

    let n = noise(x * 0.01, y * 0.01, i * 0.1);

    if (inThreshold) {
      // Golden particles in threshold
      let size = random(2, 6);
      let alpha = random(100, 200);
      fill(255, 230, 180, alpha);
      noStroke();
      ellipse(x + n * 20, y, size, size);
    } else {
      // Colored particles near each presence
      let size = random(1, 4);
      let alpha = random(50, 150);
      if (x < midX) {
        fill(255, 180, 140, alpha);
      } else {
        fill(140, 180, 255, alpha);
      }
      noStroke();
      ellipse(x, y, size, size);
    }
  }

  // Connecting wisps
  for (let i = 0; i < 50; i++) {
    let y = random(500, 1500);
    let n = noise(i * 0.3, y * 0.01);

    noFill();
    stroke(255, 240, 220, 20 + n * 30);
    strokeWeight(1 + n * 2);

    beginShape();
    for (let t = 0; t <= 1; t += 0.02) {
      let x = lerp(left.x, right.x, t);
      let yOff = sin(t * PI) * 50 * noise(t * 5, i);
      let xOff = noise(t * 3, i * 0.5, y * 0.01) * 40 - 20;
      curveVertex(x + xOff, y + yOff);
    }
    endShape();
  }
}

function drawAtmosphere() {
  // Subtle vignette
  noStroke();
  for (let r = 1500; r > 0; r -= 10) {
    let alpha = map(r, 1500, 0, 30, 0);
    fill(15, 10, 25, alpha);
    ellipse(width/2, height/2, r * 2, r * 2.5);
  }

  // Floating dust particles throughout
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.005, y * 0.005);
    let size = random(1, 3);
    fill(255, 250, 240, 30 + n * 40);
    noStroke();
    ellipse(x, y, size, size);
  }

  // Top and bottom fade
  for (let y = 0; y < 300; y++) {
    let alpha = map(y, 0, 300, 180, 0);
    stroke(25, 20, 35, alpha);
    line(0, y, width, y);
    line(0, height - y, width, height - y);
  }
}

function setup() {
