function drawBird(x, y, dir, scale) {
  push();
  translate(x, y);
  scale(scale * dir, scale);

  // Body
  fill(40, 35, 50);
  noStroke();
  beginShape();
  vertex(0, 0);
  vertex(-60, -5);
  vertex(-80, 0);
  vertex(-60, 8);
  vertex(0, 5);
  endShape(CLOSE);

  // Head
  ellipse(5, 0, 25, 20);

  // Beak
  fill(255, 180, 100);
  triangle(18, 0, 10, -3, 10, 3);

  // Eye
  fill(255);
  ellipse(10, -2, 8, 8);
  fill(20);
  ellipse(11, -2, 4, 4);

  // Wing up
  fill(50, 45, 60);
  beginShape();
  vertex(-20, -5);
  vertex(-50, -60);
  vertex(-30, -50);
  vertex(-10, -55);
  vertex(0, -45);
  vertex(-5, -5);
  endShape(CLOSE);

  // Wing feather details
  stroke(70, 65, 80);
  strokeWeight(1);
  line(-20, -10, -40, -50);
  line(-15, -10, -25, -48);
  line(-25, -8, -48, -55);

  // Tail
  noStroke();
  fill(45, 40, 55);
  beginShape();
  vertex(-70, 0);
  vertex(-110, -15);
  vertex(-100, 0);
  vertex(-110, 15);
  endShape(CLOSE);

  pop();
}

function drawFeather(x, y, size, angle) {
  push();
  translate(x, y);
  rotate(angle);

  // Feather shaft
  stroke(60, 50, 70);
  strokeWeight(1);
  line(0, -size/2, 0, size/2);

  // Feather barbs
  noStroke();
  let c = color(80 + random(40), 70 + random(30), 90 + random(40), 150);
  fill(c);

  beginShape();
  vertex(0, -size/2);
  bezierVertex(size/4, -size/4, size/3, 0, size/5, size/3);
  vertex(0, size/2);
  bezierVertex(-size/5, size/3, -size/3, 0, -size/4, -size/4);
  endShape(CLOSE);

  pop();
}

function drawFlightTrail(mx, my) {
  // Subtle dotted heart-shaped trail
  noFill();
  stroke(255, 200, 180, 60);
  strokeWeight(2);

  // Left curve (bird 1's path)
  beginShape();
  for (let t = 0; t <= 1; t += 0.02) {
    let x = lerp(100, mx - 80, t);
    let y = lerp(my + 300, my - 20, t);
    y += sin(t * PI) * -100;
    point(x, y);
  }
  endShape();

  // Right curve (bird 2's path)
  beginShape();
  for (let t = 0; t <= 1; t += 0.02) {
    let x = lerp(width - 100, mx + 80, t);
    let y = lerp(my + 300, my + 10, t);
    y += sin(t * PI) * -100;
    point(x, y);
  }
  endShape();
}

function setup() {
