function drawTree(x, y, angle, len, weight, col) {
  stroke(col);
  strokeWeight(weight);

  let endX = x + cos(angle) * len;
  let endY = y + sin(angle) * len;

  // Main trunk with slight curve
  noFill();
  beginShape();
  for (let i = 0; i <= 10; i++) {
    let t = i / 10;
    let px = lerp(x, endX, t) + noise(i * 0.3, x * 0.01) * 15 - 7.5;
    let py = lerp(y, endY, t);
    vertex(px, py);
  }
  endShape();

  if (len > 15) {
    let newLen = len * 0.72;
    let newWeight = weight * 0.7;

    // Branches leaning toward each other for trees
    let branchAngle1 = angle - 0.35 + random(-0.1, 0.1);
    let branchAngle2 = angle + 0.35 + random(-0.1, 0.1);

    drawTree(endX, endY, branchAngle1, newLen, newWeight, col);
    drawTree(endX, endY, branchAngle2, newLen, newWeight, col);

    if (random() > 0.5 && len > 40) {
      drawTree(endX, endY, angle + random(-0.2, 0.2), newLen * 0.8, newWeight, col);
    }
  }
}

function drawRoots() {
  // Intertwined root system underground
  let rootColor = color(70, 50, 35, 200);

  // Left tree roots
  drawRootSystem(550, height * 0.7, 8, rootColor, 1);

  // Right tree roots  
  drawRootSystem(1050, height * 0.7, 8, rootColor, -1);

  // Connecting roots in the middle
  stroke(70, 50, 35, 150);
  strokeWeight(4);
  noFill();
  for (let i = 0; i < 5; i++) {
    beginShape();
    let startX = 550 + random(50, 150);
    let endX = 1050 - random(50, 150);
    let midY = height * 0.75 + random(100, 300);

    curveVertex(startX, height * 0.7 + 50);
    curveVertex(startX, height * 0.7 + 50);
    curveVertex(lerp(startX, endX, 0.3), midY + random(-30, 30));
    curveVertex(lerp(startX, endX, 0.7), midY + random(-30, 30));
    curveVertex(endX, height * 0.7 + 50);
    curveVertex(endX, height * 0.7 + 50);
    endShape();
  }
}

function drawRootSystem(x, y, depth, col, dir) {
  if (depth <= 0) return;

  stroke(col);
  strokeWeight(depth * 0.8);

  let len = 30 + depth * 15;
  let angle = PI/2 + random(-0.5, 0.5) + dir * 0.2;

  let endX = x + cos(angle) * len;
  let endY = y + sin(angle) * len;

  line(x, y, endX, endY);

  if (depth > 1) {
    drawRootSystem(endX, endY, depth - 1 - floor(random(2)), col, dir);
    if (random() > 0.3) {
      drawRootSystem(endX, endY, depth - 2, col, dir * 0.5);
    }
  }
}

