function drawTree(x, y, angle, len, weight, branches, col) {
  if (len < 10) return;

  let endX = x + cos(angle) * len;
  let endY = y + sin(angle) * len;

  stroke(col);
  strokeWeight(weight);
  noFill();

  // Draw branch with slight curve
  beginShape();
  for (let i = 0; i <= 10; i++) {
    let t = i / 10;
    let px = lerp(x, endX, t);
    let py = lerp(y, endY, t);
    let offset = sin(t * PI) * noise(px * 0.01, py * 0.01) * 15;
    vertex(px + offset, py);
  }
  endShape();

  branches.push({x: endX, y: endY, angle: angle});

  if (len > 20) {
    let branches1 = random(1, 3);
    for (let i = 0; i < branches1; i++) {
      let newAngle = angle + random(-0.5, 0.5);
      let newLen = len * random(0.6, 0.8);
      drawTree(endX, endY, newAngle, newLen, weight * 0.7, branches, col);
    }
  }
}

function drawRoots(x, y, dir) {
  stroke(60, 40, 25);
  strokeWeight(3);

  for (let i = 0; i < 8; i++) {
    let angle = PI/2 + random(-0.8, 0.8) + dir * 0.3;
    let len = random(100, 250);
    let startX = x + random(-30, 30);

    noFill();
    beginShape();
    let px = startX;
    let py = y;
    for (let j = 0; j < 20; j++) {
      vertex(px, py);
      px += cos(angle) * len/20 + random(-5, 5);
      py += sin(angle) * len/20 + random(2, 8);
      angle += random(-0.1, 0.1);
    }
    endShape();
  }
}

function drawSharedRoots() {
  stroke(55, 38, 28);
  strokeWeight(4);
  noFill();

  // Roots that meet in the middle
  for (let i = 0; i < 5; i++) {
    beginShape();
    let startX = 600 + random(-20, 20);
    let startY = height * 0.7 + random(50, 150);
    let endX = 1000 + random(-20, 20);
    let endY = height * 0.7 + random(50, 150);
    let midY = max(startY, endY) + random(50, 150);

    curveVertex(startX, startY - 50);
    curveVertex(startX, startY);
    curveVertex(800 + random(-50, 50), midY);
    curveVertex(endX, endY);
    curveVertex(endX, endY - 50);
    endShape();
  }
}

function drawIntertwinedBranches() {
  stroke(65, 42, 32);
  strokeWeight(6);
  noFill();

  // Branches reaching toward each other
  for (let i = 0; i < 4; i++) {
    let y1 = height * 0.3 + i * 80;
    beginShape();
    curveVertex(620, y1 - 50);
    curveVertex(650 + random(20), y1);
    curveVertex(750 + random(-20, 20), y1 - 30 + random(-20, 20));
    curveVertex(850 + random(-20, 20), y1 + random(-20, 20));
    curveVertex(950 + random(20), y1 + 20);
    curveVertex(980, y1 + 70);
    endShape();
  }
}

function drawLeaves(cx, cy, radius, col) {
  noStroke();

  for (let i = 0; i < 600; i++) {
    let angle = random(TWO_PI);
    let r = random(radius) * sqrt(random());
    let x = cx + cos(angle) * r;
    let y = cy + sin(angle) * r * 1.2;

    let leafCol = color(
      red(col) + random(-30, 30),
      green(col) + random(-20, 20),
      blue(col) + random(-20, 20),
      random(100, 200)
    );
    fill(leafCol);

    push();
    translate(x, y);
    rotate(random(TWO_PI));
    ellipse(0, 0, random(8, 20), random(4, 10));
    pop();
  }
}

function drawFallingLeaves() {
  noStroke();

  for (let i = 0; i < 40; i++) {
    let x = random(400, 1200);
    let y = random(height * 0.5, height * 0.75);
    let col = color(
      random(170, 210),
      random(70, 110),
      random(60, 100),
      random(150, 220)
    );
    fill(col);

    push();
    translate(x, y);
    rotate(random(TWO_PI));
    ellipse(0, 0, random(10, 18), random(5, 10));
    pop();
  }
}

function drawLightRays() {
  noStroke();

  for (let i = 0; i < 8; i++) {
    let x = random(200, 1400);
    fill(255, 220, 180, 15);

    beginShape();
    vertex(x, 0);
    vertex(x + 100, 0);
    vertex(x + 150 + random(100), height * 0.7);
    vertex(x - 50 + random(100), height * 0.7);
    endShape(CLOSE);
  }
}

function drawHeartLeaves() {
  // Create heart shape with overlapping leaves in the center
  let cx = 800;
  let cy = height * 0.35;

  noStroke();
  for (let i = 0; i < 80; i++) {
    // Heart parametric equation
    let t = random(TWO_PI);
    let scale = random(0.3, 1) * 40;
    let hx = 16 * pow(sin(t), 3);
    let hy = -(13 * cos(t) - 5 * cos(2*t) - 2 * cos(3*t) - cos(4*t));

    let x = cx + hx * scale / 16 * random(0.8, 1.2);
    let y = cy + hy * scale / 16 * random(0.8, 1.2);

    fill(220, 80, 80, random(100, 180));
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    ellipse(0, 0, random(12, 22), random(6, 12));
    pop();
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Sky gradient - warm sunset colors
  for (let y = 0; y < height * 0.7; y++) {
    let inter = map(y, 0, height * 0.7, 0, 1);
    let c = lerpColor(color(255, 180, 120), color(255, 120, 100), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Ground
  for (let y = height * 0.7; y < height; y++) {
    let inter = map(y, height * 0.7, height, 0, 1);
    let c = lerpColor(color(80, 60, 40), color(40, 30, 20), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Draw underground roots
  drawRoots(650, height * 0.7, -PI/2, 180, 8, color(60, 40, 25));
  drawRoots(950, height * 0.7, -PI/2, 180, 8, color(60, 40, 25));

  // Intertwining roots in the middle
  drawConnectingRoots();

  // Draw two trees
  let tree1X = 650;
  let tree2X = 950;
  let groundY = height * 0.7;

