  drawTrunk(tree2X, groundY, -PI/2 - 0.1, 320, 12, color(75, 50, 30));

  // Branches meeting at top
  drawBranches(tree1X - 30, groundY - 300, 0.3, 6, color(85, 55, 35));
  drawBranches(tree2X + 30, groundY - 300, -0.3, 6, color(75, 50, 30));

