}

function drawTrunk(x, y, angle, len, weight, col) {
  stroke(col);
  strokeWeight(weight);

  let endX = x + cos(angle) * len;
  let endY = y + sin(angle) * len;

  // Draw curved trunk
  noFill();
  beginShape();
  for (let i = 0; i <= 20; i++) {
    let t = i / 20;
    let px = lerp(x, endX, t);
    let py = lerp(y, endY, t);
    px += sin(t * PI) * 20 * (x < 800 ? 1 : -1);
    py += noise(t * 3) * 10;
    curveVertex(px, py);
  }
  endShape();

  // Sub-branches
  if (len > 50) {
    let midX = x + cos(angle) * len * 0.6 + sin(angle * PI) * 15 * (x < 800 ? 1 : -1);
    let midY = y + sin(angle) * len * 0.6;

    for (let i = 0; i < 3; i++) {
      let newAngle = angle + random(-0.5, 0.5) + (x < 800 ? 0.3 : -0.3);
      let newLen = len * random(0.3, 0.5);
      strokeWeight(weight * 0.6);

      let bx = midX + cos(newAngle) * newLen;
      let by = midY + sin(newAngle) * newLen;
      line(midX, midY, bx, by);
    }
  }
}

function drawBranches(x, y, baseAngle, depth, col) {
  if (depth <= 0) return;

  stroke(col);
  strokeWeight(depth * 1.5);

  let len = depth * 25 + random(10, 30);
  let angle = -PI/2 + baseAngle + random(-0.3, 0.3);

  let endX = x + cos(angle) * len;
  let endY = y + sin(angle) * len;

  line(x, y, endX, endY);

  if (depth > 1) {
    drawBranches(endX, endY, baseAngle + random(0.2, 0.5), depth - 1, col);
    drawBranches(endX, endY, baseAngle - random(0.2, 0.5), depth - 1, col);
  }
}

function drawRoots(x, y, angle, len, depth, col) {
  if (depth <= 0) return;

  stroke(col);
  strokeWeight(depth);

  let endX = x + cos(angle + PI) * len * 0.5;
  let endY = y + sin(angle + PI) * len * 0.3 + len * 0.3;

  // Curved root
  noFill();
  beginShape();
  for (let i = 0; i <= 10; i++) {
    let t = i / 10;
    let px = lerp(x, endX, t);
    let py = lerp(y, endY, t);
    px += noise(t * 5 + depth) * 30 - 15;
    curveVertex(px, py);
  }
  endShape();

  if (depth > 2) {
    drawRoots(endX, endY, angle + random(-0.8, -0.2), len * 0.7, depth - 2, col);
    drawRoots(endX, endY, angle + random(0.2, 0.8), len * 0.7, depth - 2, col);
  }
}

function drawConnectingRoots() {
  stroke(60, 40, 25);
  noFill();

  for (let i = 0; i < 8; i++) {
    strokeWeight(random(2, 5));
    let y1 = height * 0.75 + random(50, 350);
    let x1 = 650 + random(-50, 50);
    let x2 = 950 + random(-50, 50);

    beginShape();
    curveVertex(x1, y1);
    curveVertex(x1, y1);
    curveVertex(750 + random(-30, 30), y1 + random(-30, 30));
    curveVertex(850 + random(-30, 30), y1 + random(-30, 30));
    curveVertex(x2, y1);
    curveVertex(x2, y1);
    endShape();
  }
}

function drawLeaves(cx, cy, col1, col2) {
  noStroke();

  for (let i = 0; i < 800; i++) {
    let angle = random(TWO_PI);
    let r = random(50, 350);
    let x = cx + cos(angle) * r * 1.3;
    let y = cy + sin(angle) * r * 0.8;

    // Choose color based on position
    let col = x < cx ? col1 : col2;
    // Blend in the middle
    if (abs(x - cx) < 100) {
      col = lerpColor(col1, col2, map(x, cx - 100, cx + 100, 0, 1));
    }

    fill(red(col) + random(-20, 20), green(col) + random(-20, 20), blue(col) + random(-20, 20), random(150, 220));

    // Leaf shape
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    ellipse(0, 0, random(8, 20), random(15, 35));
    pop();
  }
}

function drawFallingLeaves() {
  noStroke();

  for (let i = 0; i < 40; i++) {
    let x = random(400, 1200);
    let y = random(height * 0.3, height * 0.68);

    let col = random() < 0.5 ? color(180, 80, 90, 180) : color(220, 100, 80, 180);
    fill(col);

    push();
    translate(x, y);
    rotate(random(TWO_PI));
    ellipse(0, 0, random(6, 12), random(12, 20));
    pop();
  }
}

function drawGlow(x, y) {
  noStroke();
  for (let r = 200; r > 0; r -= 5) {
    let alpha = map(r, 0, 200, 30, 0);
    fill(255, 200, 150, alpha);
    ellipse(x, y, r * 2, r * 1.5);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Sky gradient - stormy to warm
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(45, 180, t);
    let g = lerp(55, 100, t);
    let b = lerp(85, 70, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Warm glow on horizon
  noStroke();
  for (let i = 300; i > 0; i--) {
    let alpha = map(i, 300, 0, 0, 80);
    fill(255, 180, 100, alpha);
    ellipse(width * 0.7, height * 0.75, i * 4, i * 2);
  }

  // Storm clouds
  drawClouds();

  // Rain streaks
  stroke(200, 210, 230, 30);
  strokeWeight(1);
  for (let i = 0; i < 500; i++) {
    let x = random(width);
    let y = random(height * 0.7);
    let len = random(20, 60);
    line(x, y, x - 10, y + len);
  }

  // Distant mountains
  fill(60, 50, 70, 180);
  noStroke();
  beginShape();
  vertex(0, height * 0.85);
  for (let x = 0; x <= width; x += 20) {
    let y = height * 0.78 + noise(x * 0.003) * 150;
    vertex(x, y);
  }
  vertex(width, height * 0.85);
  endShape(CLOSE);

  // Home light - warm window in distance
  fill(255, 220, 150);
  noStroke();
  for (let i = 50; i > 0; i--) {
    let alpha = map(i, 50, 0, 10, 255);
    fill(255, 200, 100, alpha);
    ellipse(width * 0.72, height * 0.76, i * 2, i * 1.5);
  }
  rect(width * 0.715, height * 0.755, 15, 12);

  // Two birds flying together
  drawBird(width * 0.45, height * 0.38, 1.2, true);  // Leading bird
  drawBird(width * 0.32, height * 0.45, 1.0, false); // Following bird

  // Light rays through clouds
  drawLightRays();

  // Atmospheric particles
  for (let i = 0; i < 200; i++) {
    let x = random(width);
    let y = random(height);
    let s = random(1, 3);
    fill(255, 255, 230, random(20, 60));
    noStroke();
    ellipse(x, y, s, s);
  }
}

function drawClouds() {
  for (let i = 0; i < 15; i++) {
    let cx = random(width);
    let cy = random(height * 0.1, height * 0.5);
    let darkness = map(cy, 0, height * 0.5, 40, 80);

    for (let j = 0; j < 20; j++) {
      let x = cx + random(-200, 200);
      let y = cy + random(-50, 50);
      let r = random(50, 150);
      fill(darkness, darkness + 10, darkness + 20, 30);
      noStroke();
      ellipse(x, y, r, r * 0.6);
    }
  }
}

function drawBird(x, y, scale, isLeader) {
  push();
  translate(x, y);
  scale(scale, scale);

  // Bird body
  fill(30, 25, 35);
  noStroke();

  // Body
  beginShape();
  vertex(0, 0);
  bezierVertex(30, -5, 50, 0, 60, 5);
  bezierVertex(50, 10, 30, 8, 0, 3);
  endShape(CLOSE);

  // Head
  ellipse(55, 3, 20, 15);

  // Beak
  fill(80, 60, 40);
  triangle(65, 3, 75, 5, 65, 7);

  // Wings up
  fill(35, 30, 40);
  beginShape();
  vertex(20, 0);
  bezierVertex(10, -30, -20, -60, -40, -80);
  bezierVertex(-30, -60, 0, -30, 30, -5);
  endShape(CLOSE);

  beginShape();
  vertex(20, 3);
  bezierVertex(10, 33, -20, 63, -35, 75);
  bezierVertex(-25, 55, 5, 30, 30, 8);
  endShape(CLOSE);

  // Wing details
  stroke(50, 45, 55);
  strokeWeight(1);
  for (let i = 0; i < 5; i++) {
    let startX = 15 - i * 5;
    let startY = -5 - i * 10;
    line(startX, startY, startX - 20, startY - 25);
  }

  // Tail feathers
  noStroke();
  fill(25, 20, 30);
  beginShape();
  vertex(0, 2);
  vertex(-25, -5);
  vertex(-30, 2);
  vertex(-25, 9);
  endShape(CLOSE);

  pop();
}

function drawLightRays() {
  let centerX = width * 0.7;
  let centerY = height * 0.75;

  for (let i = 0; i < 12; i++) {
    let angle = map(i, 0, 12, -PI * 0.4, PI * 0.1);
    let len = random(400, 800);

    let x2 = centerX + cos(angle) * len;
    let y2 = centerY + sin(angle) * len;

    for (let w = 30; w > 0; w -= 5) {
      stroke(255, 220, 150, map(w, 30, 0, 2, 15));
      strokeWeight(w);
      line(centerX, centerY, x2, y2);
    }
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep warm gradient background
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(25, 20, 35), color(45, 25, 40), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Subtle atmospheric glow
  noStroke();
  for (let i = 0; i < 50; i++) {
    let x = random(width);
    let y = random(height);
    let s = random(100, 400);
    let alpha = random(3, 8);
    fill(255, 200, 150, alpha);
    ellipse(x, y, s, s);
  }

  // Two flowing forms representing two beings
  drawFlowingForm(550, 1000, color(200, 80, 120), color(255, 150, 180), -1);
  drawFlowingForm(1050, 1000, color(80, 120, 200), color(150, 180, 255), 1);

  // The merging space - where they meet
  drawMergingLight();

  // Particle streams flowing between forms
  drawParticleStreams();

  // Soft luminous particles throughout
  drawAmbientParticles();

  // Central warm glow where forms meet
  drawCentralGlow();
}

function drawFlowingForm(centerX, centerY, baseColor, lightColor, direction) {
  push();
  noStroke();

  // Multiple layered flowing shapes
  for (let layer = 0; layer < 15; layer++) {
    let layerOffset = layer * 20;
    let alpha = map(layer, 0, 15, 60, 15);

    beginShape();
    for (let angle = 0; angle < TWO_PI; angle += 0.02) {
      let noiseVal = noise(
        cos(angle) * 2 + layer * 0.3,
        sin(angle) * 2 + layer * 0.3,
        layer * 0.1
      );

      let baseRadius = 200 + layerOffset;
      let radiusVariation = noiseVal * 150 + sin(angle * 3) * 50;
      let r = baseRadius + radiusVariation;

      // Stretch toward center (where they meet)
      let stretchFactor = 1 + cos(angle - direction * PI/2) * 0.4;
      r *= stretchFactor;

      let x = centerX + cos(angle) * r * 0.8;
      let y = centerY + sin(angle) * r * 1.2;

      // Vertical flow distortion
      y += sin(angle * 2 + layer * 0.5) * 100;

      let c = lerpColor(baseColor, lightColor, noiseVal);
      fill(red(c), green(c), blue(c), alpha);
      vertex(x, y);
    }
    endShape(CLOSE);
  }

  // Inner luminous core
  for (let i = 0; i < 8; i++) {
    let coreAlpha = map(i, 0, 8, 80, 10);
    let coreSize = map(i, 0, 8, 100, 300);
    fill(red(lightColor), green(lightColor), blue(lightColor), coreAlpha);
    ellipse(centerX, centerY, coreSize, coreSize * 1.5);
  }

  pop();
}

function drawMergingLight() {
  push();
  noStroke();

  let mergeX = width / 2;
  let mergeY = height / 2;

  // Layered glow where the two forms meet
  for (let i = 0; i < 30; i++) {
    let size = map(i, 0, 30, 50, 600);
    let alpha = map(i, 0, 30, 100, 5);

    // Purple-pink blend color (mixture of red and blue)
    let r = 180 + sin(i * 0.3) * 40;
    let g = 120 + cos(i * 0.2) * 30;
    let b = 200 + sin(i * 0.4) * 30;

    fill(r, g, b, alpha);

    let offsetX = noise(i * 0.5) * 100 - 50;
    let offsetY = noise(i * 0.5 + 100) * 150 - 75;

    ellipse(mergeX + offsetX, mergeY + offsetY, size * 1.2, size * 1.8);
  }

  pop();
}

function drawParticleStreams() {
  push();
  noStroke();

  // Streams from left form to center
  for (let i = 0; i < 200; i++) {
    let t = random(1);
    let startX = 550 + random(-100, 100);
    let startY = 1000 + random(-300, 300);
    let endX = 800 + random(-50, 50);
    let endY = 1000 + random(-200, 200);

    let x = lerp(startX, endX, t);
    let y = lerp(startY, endY, t);

    // Add flowing motion
    x += sin(t * PI * 2 + i * 0.1) * 30;
    y += cos(t * PI + i * 0.1) * 50;

    let size = random(2, 8) * (1 - abs(t - 0.5) * 2);
    let alpha = random(50, 150) * (1 - abs(t - 0.5));

    fill(255, 150, 180, alpha);
    ellipse(x, y, size, size);
  }

  // Streams from right form to center
  for (let i = 0; i < 200; i++) {
    let t = random(1);
    let startX = 1050 + random(-100, 100);
    let startY = 1000 + random(-300, 300);
    let endX = 800 + random(-50, 50);
    let endY = 1000 + random(-200, 200);

    let x = lerp(startX, endX, t);
    let y = lerp(startY, endY, t);

    x += sin(t * PI * 2 + i * 0.1) * 30;
    y += cos(t * PI + i * 0.1) * 50;

    let size = random(2, 8) * (1 - abs(t - 0.5) * 2);
    let alpha = random(50, 150) * (1 - abs(t - 0.5));

    fill(150, 180, 255, alpha);
    ellipse(x, y, size, size);
  }

  pop();
}

function drawAmbientParticles() {
  push();
  noStroke();

  for (let i = 0; i < 500; i++) {
    let x = random(width);
    let y = random(height);

    let distToCenter = dist(x, y, width/2, height/2);
    let probability = map(distToCenter, 0, 800, 1, 0.1);

    if (random() < probability) {
      let size = random(1, 4);
      let alpha = random(30, 100);

      // Color based on position
      if (x < width/2) {
        fill(255, 180, 200, alpha);
      } else {
        fill(180, 200, 255, alpha);
      }

      // Near center, use blended color
      if (distToCenter < 300) {
        fill(220, 180, 220, alpha * 1.5);
      }

      ellipse(x, y, size, size);
    }
  }

  pop();
}

function drawCentralGlow() {
  push();
  noStroke();

  let cx = width / 2;
  let cy = height / 2;

  // Warm golden light at the very center
  for (let i = 0; i < 20; i++) {
    let size = map(i, 0, 20, 20, 250);
    let alpha = map(i, 0, 20, 120, 5);

    fill(255, 220, 180, alpha);
    ellipse(cx, cy, size, size * 1.3);
  }

  // Tiny bright core
  fill(255, 250, 240, 200);
  ellipse(cx, cy, 15, 20);

  pop();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep warm gradient background
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(15, 10, 25), color(35, 15, 30), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Center point - the heart of love
  let centerX = width / 2;
  let centerY = height / 2;

  // Draw subtle radial glow from center
  noStroke();
  for (let r = 600; r > 0; r -= 2) {
    let alpha = map(r, 0, 600, 60, 0);
    fill(255, 180, 120, alpha);
    ellipse(centerX, centerY, r * 2, r * 2);
  }

  // Inner warm glow
  for (let r = 200; r > 0; r -= 1) {
    let alpha = map(r, 0, 200, 255, 100);
    fill(255, 220, 180, alpha * 0.3);
    ellipse(centerX, centerY, r * 2, r * 2);
  }

  // Draw flowing paths converging to center
  let numPaths = 180;

  for (let i = 0; i < numPaths; i++) {
    // Start from edges
    let angle = random(TWO_PI);
    let startDist = random(900, 1200);
    let startX = centerX + cos(angle) * startDist;
    let startY = centerY + sin(angle) * startDist;

    // Path properties
    let pathColor = getWarmColor(i);
    let points = [];

    // Generate spiral path toward center
    let x = startX;
    let y = startY;
    let steps = int(random(150, 300));

    for (let j = 0; j < steps; j++) {
      points.push({x: x, y: y});

      // Direction toward center with spiral drift
      let toCenter = atan2(centerY - y, centerX - x);
      let noiseVal = noise(x * 0.003, y * 0.003, i * 0.1);
      let drift = map(noiseVal, 0, 1, -PI/2, PI/2);

      let distToCenter = dist(x, y, centerX, centerY);
      let spiralStrength = map(distToCenter, 0, 1000, 0.1, 0.8);

      let finalAngle = toCenter + drift * spiralStrength;
      let speed = map(distToCenter, 0, 1000, 1, 5);

      x += cos(finalAngle) * speed;
      y += sin(finalAngle) * speed;

      if (distToCenter < 50) break;
    }

    // Draw the path with gradient
    noFill();
    strokeWeight(random(0.5, 2));

    for (let j = 1; j < points.length; j++) {
      let progress = j / points.length;
      let alpha = map(progress, 0, 1, 30, 200);
      let distToCenter = dist(points[j].x, points[j].y, centerX, centerY);
      alpha *= map(distToCenter, 0, 500, 1.5, 0.5);

      stroke(red(pathColor), green(pathColor), blue(pathColor), alpha);
      line(points[j-1].x, points[j-1].y, points[j].x, points[j].y);
    }

    // Draw glowing particle at path end
    if (points.length > 0) {
      let endPoint = points[points.length - 1];
      let glowSize = random(3, 8);
      noStroke();
      for (let g = glowSize; g > 0; g -= 0.5) {
        let glowAlpha = map(g, 0, glowSize, 200, 0);
        fill(255, 240, 200, glowAlpha);
        ellipse(endPoint.x, endPoint.y, g * 2, g * 2);
      }
    }
  }

  // Add scattered stars/particles in background
  for (let i = 0; i < 500; i++) {
    let x = random(width);
    let y = random(height);
    let distToCenter = dist(x, y, centerX, centerY);

    if (distToCenter > 300) {
      let size = random(1, 3);
      let alpha = map(distToCenter, 300, 1000, 50, 150);
      alpha *= random(0.5, 1);

      noStroke();
      fill(255, 250, 240, alpha);
      ellipse(x, y, size, size);
    }
  }

  // Central bright core
  noStroke();
  for (let r = 80; r > 0; r -= 0.5) {
    let alpha = map(r, 0, 80, 255, 50);
    let warmth = map(r, 0, 80, 255, 200);
    fill(255, warmth, warmth * 0.7, alpha * 0.5);
    ellipse(centerX, centerY, r * 2, r * 2);
  }

  // Brightest center point
  fill(255, 255, 250, 255);
  ellipse(centerX, centerY, 20, 20);

  // Add some floating particles around center
  for (let i = 0; i < 100; i++) {
    let angle = random(TWO_PI);
    let dist = random(60, 250);
    let x = centerX + cos(angle) * dist;
    let y = centerY + sin(angle) * dist;
    let size = random(2, 5);
    let alpha = map(dist, 60, 250, 200, 50);

    noStroke();
    fill(255, 230, 200, alpha);
    ellipse(x, y, size, size);
  }

  // Soft vignette
  for (let i = 0; i < 100; i++) {
    let alpha = map(i, 0, 100, 0, 80);
    noFill();
    stroke(10, 5, 15, alpha);
    strokeWeight(20);
    let size = map(i, 0, 100, max(width, height) * 1.5, max(width, height) * 0.5);
    ellipse(centerX, centerY, size, size);
  }
}

function getWarmColor(seed) {
  let colors = [
    color(255, 150, 100),  // warm orange
    color(255, 200, 150),  // soft peach
    color(255, 180, 180),  // soft pink
    color(255, 220, 180),  // cream
    color(255, 160, 140),  // coral
    color(250, 200, 200),  // blush
    color(255, 190, 120),  // golden
    color(240, 180, 170),  // dusty rose
  ];
  return colors[seed % colors.length];
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep cosmic background
  setGradientBackground();

  // Distant stars
  drawStars();

  // Soft nebula clouds
  drawNebula();

  // Two luminous beings approaching each other
  let being1X = 580;
  let being1Y = 950;
  let being2X = 1020;
  let being2Y = 1050;

  // The light between them - born from relationship
  drawSharedLight(being1X, being1Y, being2X, being2Y);

  // Connection threads
  drawConnectionThreads(being1X, being1Y, being2X, being2Y);

  // The two beings - complete yet choosing closeness
  drawBeing(being1X, being1Y, color(255, 180, 140), color(255, 120, 80), -0.3);
  drawBeing(being2X, being2Y, color(140, 180, 255), color(80, 120, 255), 0.3);

  // Floating particles around
  drawFloatingParticles();

  // Soft vignette
  drawVignette();
}

function setGradientBackground() {
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(8, 15, 35), color(20, 30, 60), inter);
    stroke(c);
    line(0, y, width, y);
  }
}

function drawStars() {
  noStroke();
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = random(height);
    let s = random(0.5, 2.5);
    let alpha = random(50, 180);
    fill(255, 255, 255, alpha);
    ellipse(x, y, s, s);
  }

  // A few brighter stars
  for (let i = 0; i < 20; i++) {
    let x = random(width);
    let y = random(height);
    let s = random(2, 4);
    fill(255, 255, 255, 100);
    ellipse(x, y, s * 2, s * 2);
    fill(255, 255, 255, 200);
    ellipse(x, y, s, s);
  }
}

function drawNebula() {
  noStroke();
  for (let i = 0; i < 5000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.003, y * 0.003);

    if (n > 0.45) {
      let alpha = map(n, 0.45, 0.7, 0, 25);
      let hueShift = noise(x * 0.002, y * 0.002 + 100);

      let r = map(hueShift, 0, 1, 60, 120);
      let g = map(hueShift, 0, 1, 40, 80);
      let b = map(hueShift, 0, 1, 100, 160);

      fill(r, g, b, alpha);
      let s = map(n, 0.45, 0.7, 10, 40);
      ellipse(x, y, s, s);
    }
  }
}

function drawSharedLight(x1, y1, x2, y2) {
  let midX = (x1 + x2) / 2;
  let midY = (y1 + y2) / 2;

  // The light that belongs to neither but exists because of both
  noStroke();
  for (let r = 400; r > 0; r -= 4) {
    let alpha = map(r, 0, 400, 60, 0);
    let warmth = map(r, 0, 400, 255, 200);
    fill(255, warmth, 200, alpha);

    let distort = noise(r * 0.02) * 30;
    ellipse(midX + distort - 15, midY + distort - 15, r * 1.2, r * 0.8);
  }

  // Core glow
  for (let r = 100; r > 0; r -= 2) {
    let alpha = map(r, 0, 100, 150, 0);
    fill(255, 250, 240, alpha);
    ellipse(midX, midY, r, r * 0.7);
  }
}

function drawConnectionThreads(x1, y1, x2, y2) {
  noFill();

  for (let i = 0; i < 15; i++) {
    let offset1 = (noise(i * 0.5) - 0.5) * 100;
    let offset2 = (noise(i * 0.5 + 100) - 0.5) * 100;

    let alpha = map(i, 0, 15, 80, 20);
    stroke(255, 220, 200, alpha);
    strokeWeight(map(i, 0, 15, 3, 1));

    let startX = x1 + offset1 * 0.5;
    let startY = y1 + offset1 * 0.3;
    let endX = x2 + offset2 * 0.5;
    let endY = y2 + offset2 * 0.3;

    let midX = (startX + endX) / 2;
    let midY = (startY + endY) / 2 + (noise(i * 0.3) - 0.5) * 80;

    beginShape();
    curveVertex(startX - 50, startY);
    curveVertex(startX, startY);
    curveVertex(midX, midY);
    curveVertex(endX, endY);
    curveVertex(endX + 50, endY);
    endShape();
  }
}

function drawBeing(x, y, colorOuter, colorInner, lean) {
  push();
  translate(x, y);
  rotate(lean);

  // Outer aura - multiple layers
  noStroke();
  for (let r = 350; r > 0; r -= 5) {
    let alpha = map(r, 0, 350, 0, 40);
    let c = lerpColor(colorInner, colorOuter, map(r, 0, 350, 0, 1));
    c.setAlpha(alpha);
    fill(c);

    let nx = noise(r * 0.01, x * 0.01) * 40 - 20;
    let ny = noise(r * 0.01 + 50, y * 0.01) * 40 - 20;

    ellipse(nx, ny, r, r * 1.3);
  }

  // Core body - organic shape
  for (let r = 150; r > 0; r -= 3) {
    let alpha = map(r, 0, 150, 255, 100);
    let c = lerpColor(color(255, 255, 255), colorInner, map(r, 0, 150, 0, 1));
    c.setAlpha(alpha);
    fill(c);

    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.1) {
      let rNoise = noise(cos(a) + 1, sin(a) + 1, r * 0.02) * 20;
      let rr = r + rNoise;
      let px = cos(a) * rr * 0.8;
      let py = sin(a) * rr * 1.1;
      vertex(px, py);
    }
    endShape(CLOSE);
  }

  // Inner light
  for (let r = 50; r > 0; r -= 2) {
    let alpha = map(r, 0, 50, 255, 150);
    fill(255, 255, 255, alpha);
    ellipse(0, 0, r, r * 1.2);
  }

  pop();
}

function drawFloatingParticles() {
  noStroke();

  for (let i = 0; i < 200; i++) {
    let angle = random(TWO_PI);
    let dist = random(100, 700);
    let centerX = 800;
    let centerY = 1000;

    let x = centerX + cos(angle) * dist + (noise(i * 0.1) - 0.5) * 400;
    let y = centerY + sin(angle) * dist + (noise(i * 0.1 + 50) - 0.5) * 400;

    let s = random(2, 8);
    let alpha = random(30, 120);

    // Mix of warm and cool particles
    if (random() > 0.5) {
      fill(255, 200, 150, alpha);
    } else {
      fill(150, 200, 255, alpha);
    }

    ellipse(x, y, s, s);

    // Glow
    fill(255, 255, 255, alpha * 0.3);
    ellipse(x, y, s * 2, s * 2);
  }
}

function drawVignette() {
  noFill();
  for (let i = 0; i < 200; i++) {
    let alpha = map(i, 0, 200, 0, 150);
    stroke(5, 10, 25, alpha);
    strokeWeight(10);

    let margin = -i * 5;
    rect(margin, margin, width - 2 * margin, height - 2 * margin, 100);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep warm gradient background
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c1 = color(15, 10, 25);
    let c2 = color(45, 20, 35);
    let c = lerpColor(c1, c2, inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Center point - the warm core
  let centerX = width / 2;
  let centerY = height / 2;

  // Draw the warm glowing center
  noStroke();
  for (let r = 400; r > 0; r -= 2) {
    let alpha = map(r, 400, 0, 0, 80);
    let warmth = map(r, 400, 0, 0, 1);
    fill(255, 180 + warmth * 75, 120 + warmth * 80, alpha);
    ellipse(centerX, centerY, r * 2, r * 2);
  }

  // Inner bright core
  for (let r = 80; r > 0; r -= 1) {
    let alpha = map(r, 80, 0, 100, 255);
    fill(255, 250, 240, alpha);
    ellipse(centerX, centerY, r * 2, r * 2);
  }

  // Particles flowing toward center
  let particles = [];

  // Create particles at various distances
  for (let i = 0; i < 800; i++) {
    let angle = random(TWO_PI);
    let dist = random(150, 950);
    let x = centerX + cos(angle) * dist;
    let y = centerY + sin(angle) * dist;

    // Size based on distance - closer ones slightly larger
    let size = map(dist, 150, 950, 8, 3) + random(-1, 2);

    particles.push({
      x: x,
      y: y,
      size: size,
      dist: dist,
      angle: angle,
      hue: random(0, 60) // warm hues
    });
  }

  // Draw orbital trails - curved lines showing movement toward center
  stroke(255, 200, 150, 15);
  strokeWeight(1);
  noFill();

  for (let i = 0; i < 200; i++) {
    let startAngle = random(TWO_PI);
    let startDist = random(400, 900);
    let spiralTightness = random(0.3, 0.8);

    beginShape();
    for (let t = 0; t < 100; t++) {
      let progress = t / 100;
      let currentDist = startDist * (1 - progress * 0.6);
      let currentAngle = startAngle + progress * PI * spiralTightness;
      let x = centerX + cos(currentAngle) * currentDist;
      let y = centerY + sin(currentAngle) * currentDist;

      // Add subtle noise
      x += noise(t * 0.1, i) * 20 - 10;
      y += noise(t * 0.1 + 100, i) * 20 - 10;

      vertex(x, y);
    }
    endShape();
  }

  // Draw connecting threads between nearby particles
  for (let i = 0; i < particles.length; i++) {
    for (let j = i + 1; j < particles.length; j++) {
      let d = dist(particles[i].x, particles[i].y, particles[j].x, particles[j].y);
      if (d < 50 && d > 10) {
        let alpha = map(d, 10, 50, 40, 5);
        stroke(255, 220, 180, alpha);
        strokeWeight(0.5);
        line(particles[i].x, particles[i].y, particles[j].x, particles[j].y);
      }
    }
  }

  // Draw particles with glow
  for (let p of particles) {
    // Glow
    noStroke();
    for (let r = p.size * 3; r > 0; r -= 1) {
      let alpha = map(r, p.size * 3, 0, 0, 100);
      let distFactor = map(p.dist, 150, 950, 1, 0.3);
      fill(255, 200 + p.hue, 150, alpha * distFactor);
      ellipse(p.x, p.y, r * 2, r * 2);
    }

    // Core
    let brightness = map(p.dist, 150, 950, 255, 180);
    fill(brightness, brightness - 20, brightness - 50);
    ellipse(p.x, p.y, p.size, p.size);
  }

  // Add some brighter, closer particles
  for (let i = 0; i < 50; i++) {
    let angle = random(TWO_PI);
    let dist = random(100, 200);
    let x = centerX + cos(angle) * dist;
    let y = centerY + sin(angle) * dist;
    let size = random(4, 10);

    // Strong glow
    noStroke();
    for (let r = size * 4; r > 0; r -= 1) {
      let alpha = map(r, size * 4, 0, 0, 150);
      fill(255, 240, 220, alpha);
      ellipse(x, y, r * 2, r * 2);
    }

    fill(255, 255, 250);
    ellipse(x, y, size, size);
  }

  // Outer scattered particles - those still far but beginning to turn
  for (let i = 0; i < 300; i++) {
    let angle = random(TWO_PI);
    let dist = random(600, 1000);
    let x = centerX + cos(angle) * dist;
    let y = centerY + sin(angle) * dist;

    // Only draw if within canvas
    if (x > 0 && x < width && y > 0 && y < height) {
      let size = random(1, 3);
      let alpha = map(dist, 600, 1000, 150, 30);

      noStroke();
      fill(255, 200, 170, alpha);
      ellipse(x, y, size, size);

      // Small tail showing direction toward center
      let toCenter = atan2(centerY - y, centerX - x);
      stroke(255, 200, 170, alpha * 0.3);
      strokeWeight(0.5);
      let tailLen = random(10, 30);
      line(x, y, x - cos(toCenter) * tailLen, y - sin(toCenter) * tailLen);
    }
  }

  // Soft vignette
  noStroke();
  for (let r = 1200; r > 0; r -= 5) {
    let alpha = map(r, 1200, 0, 60, 0);
    fill(10, 5, 20, alpha);
    ellipse(centerX, centerY, r * 2 + 800, r * 2 + 1000);
  }

  // Edge darkening
  for (let i = 0; i < 100; i++) {
    let alpha = map(i, 0, 100, 0, 80);
    noFill();
    stroke(10, 5, 20, alpha);
    strokeWeight(10);
    rect(i * 5, i * 5, width - i * 10, height - i * 10, 50);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep warm gradient background
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(25, 20, 35), color(45, 25, 40), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Two luminous forms - distinct yet connected
  let center1X = width * 0.38;
  let center1Y = height * 0.48;
  let center2X = width * 0.62;
  let center2Y = height * 0.52;

  // Draw subtle connection field first
  drawConnectionField(center1X, center1Y, center2X, center2Y);

  // Draw flowing particles between the two forms
  drawFlowingParticles(center1X, center1Y, center2X, center2Y);

  // Draw the two main luminous forms
  drawLuminousForm(center1X, center1Y, color(255, 180, 120), color(255, 100, 80));
  drawLuminousForm(center2X, center2Y, color(180, 200, 255), color(100, 120, 255));

  // Draw the intersection glow - where love manifests
  drawIntersectionGlow(center1X, center1Y, center2X, center2Y);

  // Add ambient particles throughout
  drawAmbientParticles();

  // Subtle vignette
  drawVignette();
}

function drawLuminousForm(cx, cy, coreColor, edgeColor) {
  // Multiple layered glows
  for (let layer = 0; layer < 50; layer++) {
    let radius = map(layer, 0, 50, 350, 20);
    let alpha = map(layer, 0, 50, 3, 40);

    noStroke();
    let c = lerpColor(edgeColor, coreColor, map(layer, 0, 50, 0, 1));
    c.setAlpha(alpha);

    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.05) {
      let noiseVal = noise(cos(a) * 2 + cx * 0.01, sin(a) * 2 + cy * 0.01, layer * 0.1);
      let r = radius * (0.8 + noiseVal * 0.4);
      let x = cx + cos(a) * r;
      let y = cy + sin(a) * r;
      vertex(x, y);
    }
    endShape(CLOSE);
  }

  // Inner bright core
  for (let i = 0; i < 20; i++) {
    let r = map(i, 0, 20, 80, 5);
    let alpha = map(i, 0, 20, 20, 150);
    fill(255, 255, 240, alpha);
    noStroke();
    ellipse(cx, cy, r, r);
  }
}

function drawConnectionField(x1, y1, x2, y2) {
  // Subtle field lines connecting the two forms
  for (let i = 0; i < 100; i++) {
    let t = random();
    let spread = sin(t * PI) * 150;

    let baseX = lerp(x1, x2, t);
    let baseY = lerp(y1, y2, t);

    for (let j = 0; j < 30; j++) {
      let offsetY = map(j, 0, 30, -spread, spread);
      let noiseVal = noise(t * 5, j * 0.1, i * 0.05);
      let offsetX = (noiseVal - 0.5) * 100;

      let px = baseX + offsetX;
      let py = baseY + offsetY;

      let distToCenter = abs(offsetY) / spread;
      let alpha = map(distToCenter, 0, 1, 15, 2);

      let c = lerpColor(color(255, 180, 120), color(180, 200, 255), t);
      c.setAlpha(alpha);

      noStroke();
      fill(c);
      ellipse(px, py, random(2, 5), random(2, 5));
    }
  }
}

function drawFlowingParticles(x1, y1, x2, y2) {
  // Particles that seem to flow between the two forms
  for (let i = 0; i < 500; i++) {
    let t = random();
    let perpOffset = (noise(i * 0.1, t * 3) - 0.5) * 300 * sin(t * PI);

    let baseX = lerp(x1, x2, t);
    let baseY = lerp(y1, y2, t);

    let angle = atan2(y2 - y1, x2 - x1) + HALF_PI;
    let px = baseX + cos(angle) * perpOffset;
    let py = baseY + sin(angle) * perpOffset;

    let size = random(1, 4) * sin(t * PI);
    let alpha = map(sin(t * PI), 0, 1, 10, 60);

    let c = lerpColor(color(255, 200, 150), color(200, 220, 255), t);
    c.setAlpha(alpha);

    noStroke();
    fill(c);
    ellipse(px, py, size, size);
  }
}

function drawIntersectionGlow(x1, y1, x2, y2) {
  // The warm glow where the two forms meet
  let midX = (x1 + x2) / 2;
  let midY = (y1 + y2) / 2;

  // Layered glow effect
  for (let layer = 0; layer < 40; layer++) {
    let radius = map(layer, 0, 40, 280, 10);
    let alpha = map(layer, 0, 40, 5, 50);

    // Warm white/gold color for intersection
    let c = lerpColor(
      color(255, 220, 180),
      color(255, 250, 240),
      map(layer, 0, 40, 0, 1)
    );
    c.setAlpha(alpha);

    noStroke();
    fill(c);

    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.1) {
      let noiseVal = noise(cos(a) * 2 + layer * 0.1, sin(a) * 2, 100);
      let r = radius * (0.7 + noiseVal * 0.6);
      let x = midX + cos(a) * r;
      let y = midY + sin(a) * r;
      vertex(x, y);
    }
    endShape(CLOSE);
  }

  // Sparkles in the intersection
  for (let i = 0; i < 200; i++) {
    let angle = random(TWO_PI);
    let dist = random(150) * sqrt(random());
    let px = midX + cos(angle) * dist;
    let py = midY + sin(angle) * dist;

    let size = random(1, 4);
    let alpha = random(50, 200);

    fill(255, 255, 240, alpha);
    noStroke();
    ellipse(px, py, size, size);
  }
}

function drawAmbientParticles() {
  // Scattered particles throughout the canvas
  for (let i = 0; i < 800; i++) {
    let x = random(width);
    let y = random(height);

    let noiseVal = noise(x * 0.003, y * 0.003);
    let size = map(noiseVal, 0, 1, 0.5, 3);
    let alpha = map(noiseVal, 0, 1, 10, 50);

    // Color based on position
    let t = map(x, 0, width, 0, 1);
    let c = lerpColor(color(255, 180, 150), color(180, 200, 255), t);
    c.setAlpha(alpha);

    noStroke();
    fill(c);
    ellipse(x, y, size, size);
  }
}

function drawVignette() {
  // Soft vignette effect
  for (let i = 0; i < 100; i++) {
    let alpha = map(i, 0, 100, 0, 80);
    noFill();
    stroke(20, 15, 30, alpha);
    strokeWeight(20);

    let offset = i * 15;
    rect(-offset, -offset, width + offset * 2, height + offset * 2, 200);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Sky gradient - from warm life to cold void
  for (let y = 0; y < height / 2; y++) {
    let t = y / (height / 2);
    let r = lerp(45, 220, pow(1 - t, 1.5));
    let g = lerp(20, 120, pow(1 - t, 2));
    let b = lerp(60, 60, 1 - t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Ground gradient - dark earth
  for (let y = height / 2; y < height; y++) {
    let t = (y - height / 2) / (height / 2);
    let r = lerp(50, 10, t);
    let g = lerp(30, 5, t);
    let b = lerp(40, 15, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Atmospheric fog/mist layers
  noStroke();
  for (let i = 0; i < 200; i++) {
    let x = random(width);
    let y = random(height * 0.3, height * 0.6);
    let s = random(100, 400);
    let alpha = random(3, 12);
    fill(180, 160, 140, alpha);
    ellipse(x, y, s, s * 0.3);
  }

  // Draw the tree
  let treeX = width * 0.5;
  let treeY = height * 0.5;

  // Draw roots (mirror of branches, below ground)
  drawBranch(treeX, treeY, PI / 2, 180, 18, 8, true);

  // Draw branches above
  drawBranch(treeX, treeY, -PI / 2, 180, 18, 8, false);

  // Draw trunk
  noStroke();
  for (let i = -20; i <= 20; i++) {
    let x = treeX + i;
    let alpha = map(abs(i), 0, 20, 200, 0);
    let w = map(abs(i), 0, 20, 1, 0.3);
    stroke(30 + abs(i), 20 + abs(i) * 0.5, 15, alpha);
    strokeWeight(w);
    // Trunk with slight curve
    let yTop = treeY - 160;
    let yBot = treeY + 160;
    for (let y = yTop; y < yBot; y++) {
      let t = (y - yTop) / (yBot - yTop);
      let xOff = sin(t * PI) * 5 + noise(y * 0.01, i * 0.1) * 10;
      point(x + xOff, y);
    }
  }

  // Trunk texture
  strokeWeight(1);
  for (let i = 0; i < 500; i++) {
    let y = random(treeY - 150, treeY + 150);
    let xOff = random(-18, 18);
    let t = (y - (treeY - 150)) / 300;
    let x = treeX + xOff + sin(t * PI) * 5;
    let c = random(20, 60);
    stroke(c, c * 0.7, c * 0.5, random(50, 180));
    point(x, y);
  }

  // Falling/rising petals
  for (let i = 0; i < 600; i++) {
    let px, py;
    let falling = random() > 0.4;

    if (falling) {
      // Petals falling down and scattering
      px = treeX + random(-500, 500);
      py = random(treeY - 400, height * 0.48);
    } else {
      // Petals rising from below - the dead returning
      px = treeX + random(-500, 500);
      py = random(height * 0.52, treeY + 500);
    }

    let dist_from_center = abs(px - treeX);
    if (random() > map(dist_from_center, 0, 500, 0.2, 0.9)) {
      let size = random(2, 8);
      let lifeColor = falling;

      if (lifeColor) {
        // Living side: warm colors
        let r = random(180, 255);
        let g = random(50, 150);
        let b = random(40, 90);
        let a = random(80, 220);
        fill(r, g, b, a);
      } else {
        // Death side: pale, ghostly
        let v = random(150, 240);
        let a = random(40, 150);
        fill(v, v * 0.95, v * 1.05, a);
      }

      noStroke();
      push();
      translate(px, py);
      rotate(random(TWO_PI));
      ellipse(0, 0, size, size * 1.5);
      pop();
    }
  }

  // Scattered ground flowers on the living side (upper half, left)
  for (let i = 0; i < 150; i++) {
    let fx = random(0, width);
    let fy = random(height * 0.47, height * 0.55);
    let proximity = 1 - min(abs(fx - treeX) / (width * 0.5), 1);
    if (random() < proximity * 0.5) {
      let size = random(3, 10);
      let r = random(180, 255);
      let g = random(60, 180);
      let b = random(60, 120);
      fill(r, g, b, random(100, 200));
      noStroke();
      for (let p = 0; p < 5; p++) {
        let angle = (TWO_PI / 5) * p;
        ellipse(fx + cos(angle) * size * 0.5, fy + sin(angle) * size * 0.5, size * 0.6, size * 0.6);
      }
    }
  }

  // Light rays from upper left - life force
  for (let i = 0; i < 30; i++) {
    let angle = random(-0.3, 0.8);
    let length = random(400, 1200);
    let startX = random(-100, width * 0.3);
    let startY = random(-100, 100);
    stroke(255, 220, 180, random(2, 8));
    strokeWeight(random(20, 80));
    line(startX, startY, startX + cos(angle) * length, startY + sin(angle) * length);
  }

  // Dark particles rising from bottom - dissolution
  for (let i = 0; i < 400; i++) {
    let px = random(width);
    let py = random(height * 0.7, height);
    let size = random(1, 4);
    let alpha = map(py, height * 0.7, height, 10, 60);
    fill(20, 10, 30, alpha);
    noStroke();
    ellipse(px, py, size, size);
  }

  // Vignette
  drawVignette();

  // Final atmospheric haze at horizon
  noStroke();
  for (let y = height * 0.45; y < height * 0.55; y++) {
    let t = 1 - abs(y - height * 0.5) / (height * 0.05);
    fill(160, 140, 130, t * 15);
    rect(0, y, width, 1);
  }

  // Add luminous glow around tree
  for (let i = 0; i < 50; i++) {
    let angle = random(TWO_PI);
    let dist = random(50, 200);
    let gx = treeX + cos(angle) * dist;
    let gy = treeY + sin(angle) * dist * 0.5;
    fill(255, 240, 200, random(2, 8));
    noStroke();
    ellipse(gx, gy, random(30, 100), random(30, 100));
  }
}

function drawBranch(x, y, angle, len, weight, depth, isRoot) {
  if (depth <= 0 || len < 5) return;

  let dirMult = isRoot ? 1 : 1;
  let endX = x + cos(angle) * len * dirMult;
  let endY = y + sin(angle) * len * dirMult;

  // Branch color: darker for roots, warmer for branches
  let c;
  if (isRoot) {
    c = color(25 + depth * 3, 15 + depth * 2, 10 + depth, 200);
  } else {
    c = color(40 + depth * 5, 25 + depth * 3, 15 + depth * 2, 200);
  }

  stroke(c);
  strokeWeight(weight);
  line(x, y, endX, endY);

  // Add some organic texture along the branch
  for (let i = 0; i < len / 5; i++) {
    let t = random();
    let bx = lerp(x, endX, t);
    let by = lerp(y, endY, t);
    let nc = random(-15, 15);
    stroke(red(c) + nc, green(c) + nc, blue(c) + nc, random(50, 150));
    strokeWeight(random(0.5, weight * 0.5));
    point(bx + random(-weight / 2, weight / 2), by + random(-weight / 2, weight / 2));
  }

  // Branching
  let branches = depth > 5 ? floor(random(2, 4)) : floor(random(1, 3));
  for (let i = 0; i < branches; i++) {
    let newAngle = angle + random(-0.6, 0.6);
    // Slight tendency to spread outward
    if (isRoot) {
      newAngle = angle + random(-0.5, 0.5);
      // Roots tend downward
      if (sin(newAngle) < 0) newAngle = angle + random(-0.3, 0.7);
    } else {
      // Branches tend upward
      if (sin(newAngle) > 0) newAngle = angle + random(-0.7, 0.3);
    }

    let newLen = len * random(0.6, 0.8);
    let newWeight = weight * random(0.5, 0.75);

    drawBranch(endX, endY, newAngle, newLen, newWeight, depth - 1, isRoot);
  }

  // Leaf clusters or root wisps at terminal branches
  if (depth <= 2) {
    noStroke();
    for (let i = 0; i < 8; i++) {
      let lx = endX + random(-20, 20);
      let ly = endY + random(-20, 20);
      let size = random(3, 15);
      if (isRoot) {
        // Ghostly wisps
        fill(200, 190, 210, random(10, 40));
        ellipse(lx, ly, size * 2, size * 3);
      } else {
        // Living foliage / dying leaves
        let season = noise(lx * 0.01, ly * 0.01);
        if (season > 0.5) {
          // Autumn dying
          fill(random(180, 240), random(60, 120), random(30, 60), random(60, 160));
        } else {
          // Still green
          fill(random(40, 100), random(100, 180), random(30, 70), random(60, 160));
        }
        ellipse(lx, ly, size, size);
      }
    }
  }
}

function drawVignette() {
  noStroke();
  let maxDist = dist(0, 0, width / 2, height / 2);
  for (let r = maxDist; r > 0; r -= 5) {
    let alpha = map(r, maxDist, maxDist * 0.4, 180, 0);
    alpha = max(0, alpha);
    fill(5, 2, 10, alpha);
    ellipse(width / 2, height / 2, r * 2, r * 2 * (height / width));
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Sky gradient - warm left, pale/void right
  for (let y = 0; y < height * 0.6; y++) {
    for (let x = 0; x < width; x++) {
      let tx = x / width;
      let ty = y / (height * 0.6);

      // Left sky: deep twilight amber/purple
      let lr = lerp(45, 180, ty);
      let lg = lerp(20, 100, ty);
      let lb = lerp(60, 60, ty);

      // Right sky: pale, almost white void
      let rr = lerp(220, 245, ty);
      let rg = lerp(215, 240, ty);
      let rb = lerp(225, 242, ty);

      // Smooth transition
      let blend = smoothstep(0.3, 0.7, tx);
      let r = lerp(lr, rr, blend);
      let g = lerp(lg, rg, blend);
      let b = lerp(lb, rb, blend);

      // Add subtle noise texture
      let n = noise(x * 0.003, y * 0.003) * 15 - 7.5;
      set(x, y, color(r + n, g + n, b + n));
    }
  }

  // Ground
  for (let y = floor(height * 0.6); y < height; y++) {
    for (let x = 0; x < width; x++) {
      let tx = x / width;
      let ty = (y - height * 0.6) / (height * 0.4);

      // Left ground: rich dark earth
      let lr = lerp(50, 30, ty);
      let lg = lerp(35, 18, ty);
      let lb = lerp(25, 15, ty);

      // Right ground: fading pale
      let rr = lerp(200, 235, ty);
      let rg = lerp(195, 230, ty);
      let rb = lerp(200, 235, ty);

      let blend = smoothstep(0.3, 0.7, tx);
      let r = lerp(lr, rr, blend);
      let g = lerp(lg, rg, blend);
      let b = lerp(lb, rb, blend);

      let n = noise(x * 0.005, y * 0.005) * 20 - 10;
      set(x, y, color(r + n, g + n, b + n));
    }
  }
  updatePixels();

  // Draw the tree trunk
  drawTrunk(780, height * 0.6, 780, height * 0.25, 28);

  // Draw branches - left side (alive, colorful)
  drawBranches(780, height * 0.25, -1);
  // Draw branches - right side (dissolving)
  drawBranches(780, height * 0.25, 1);

  // Draw roots below ground - mirroring branches
  drawRoots(780, height * 0.6);

  // Draw leaves on left side (warm autumn colors)
  drawLeavesAlive();

  // Draw dissolving particles on right side
  drawDissolvingLeaves();

  // Falling leaves in transition zone
  drawFallingLeaves();

  // Add atmospheric haze on right side
  for (let i = 0; i < 3000; i++) {
    let x = random(width * 0.5, width);
    let y = random(0, height);
    let tx = (x - width * 0.5) / (width * 0.5);
    let a = tx * random(5, 25);
    noStroke();
    fill(240, 238, 235, a);
    ellipse(x, y, random(20, 80), random(20, 80));
  }

  // Vignette on left side
  for (let i = 0; i < 2000; i++) {
    let x = random(0, width * 0.3);
    let y = random(0, height);
    let tx = 1 - x / (width * 0.3);
    let a = tx * random(3, 15);
    noStroke();
    fill(15, 5, 20, a);
    ellipse(x, y, random(30, 100), random(30, 100));
  }
}

function smoothstep(edge0, edge1, x) {
  let t = constrain((x - edge0) / (edge1 - edge0), 0, 1);
  return t * t * (3 - 2 * t);
}

function drawTrunk(x1, y1, x2, y2, w) {
  // Trunk with texture
  for (let i = 0; i < 80; i++) {
    let t = i / 80;
    let xOff = noise(t * 3, 0) * 10 - 5;
    let baseW = lerp(w, w * 0.5, t);

    let yy = lerp(y1, y2, t);
    let xx = lerp(x1, x2, t) + xOff;

    // Left half dark bark, right half fading
    let leftColor = color(45 + noise(t * 5) * 20, 30 + noise(t * 5, 1) * 15, 20 + noise(t * 5, 2) * 10);
    let rightColor = color(160 + noise(t * 5) * 30, 155 + noise(t * 5, 1) * 25, 160 + noise(t * 5, 2) * 20, lerp(255, 80, t * 0.3));

    for (let dx = -baseW; dx <= baseW; dx++) {
      let px = xx + dx;
      let blend = smoothstep(770, 800, px);
      let c = lerpColor(leftColor, rightColor, blend);

      // bark texture
      let barkNoise = noise(px * 0.1, yy * 0.05) * 30 - 15;
      stroke(red(c) + barkNoise, green(c) + barkNoise, blue(c) + barkNoise, alpha(c));
      point(px, yy);
    }
  }

  // Thicker trunk with more detail
  noStroke();
  for (let i = 0; i < 500; i++) {
    let t = random();
    let yy = lerp(y1, y2, t);
    let baseW = lerp(w, w * 0.5, t);
    let xx = lerp(x1, x2, t) + noise(t * 3) * 10 - 5;
    let dx = random(-baseW, baseW);
    let px = xx + dx;

    let blend = smoothstep(760, 810, px);
    let barkN = noise(px * 0.08, yy * 0.04);

    let leftC = color(40 + barkN * 30, 28 + barkN * 20, 18 + barkN * 10);
    let rightC = color(170 + barkN * 30, 165 + barkN * 25, 170 + barkN * 20, lerp(200, 60, blend));

    let c = lerpColor(leftC, rightC, blend);
    fill(c);
    ellipse(px, yy, random(3, 8), random(2, 6));
  }
}

function drawBranches(startX, startY, side) {
  // side: -1 for left, 1 for right
  let branches = [];

  // Main branches
  let numMain = 5;
  for (let i = 0; i < numMain; i++) {
    let angle = side === -1 ? random(-PI * 0.8, -PI * 0.15) : random(-PI * 0.85, -PI * 0.2);
    let len = random(120, 280);
    let startYOff = i * 40 - 60;
    branches.push({
      x: startX + side * random(0, 15),
      y: startY + startYOff,
      angle: angle,
      len: len,
      weight: random(5, 12),
      depth: 0
    });
  }

  // Recursively draw branches
  for (let b of branches) {
    drawBranchRecursive(b.x, b.y, b.angle, b.len, b.weight, 0, 4, side);
  }
}

function drawBranchRecursive(x, y, angle, len, weight, depth, maxDepth, side) {
  if (depth > maxDepth || len < 10) return;

  let endX = x + cos(angle) * len;
  let endY = y + sin(angle) * len;

  let isRight = side === 1;

  for (let i = 0; i < max(1, floor(len / 3)); i++) {
    let t = i / max(1, floor(len / 3));
    let px = lerp(x, endX, t);
    let py = lerp(y, endY, t);
    let w = lerp(weight, weight * 0.4, t);

    if (isRight) {
      // Dissolving effect - more dissolution further from trunk
      let dist = abs(px - 780) / 400;
      let dissolveChance = constrain(dist * 0.6, 0, 0.85);
      if (random() < dissolveChance) continue;

      let alpha_val = lerp(180, 30, dist);
      let grayVal = lerp(120, 200, dist);
      stroke(grayVal + random(-10, 10), grayVal + random(-10, 10), grayVal + random(-5, 10), alpha_val);
    } else {
      let barkN = noise(px * 0.05, py * 0.05);
      stroke(50 + barkN * 30, 35 + barkN * 20, 25 + barkN * 10);
    }
    strokeWeight(w + random(-1, 1));
    point(px, py);

    // Draw width of branch
    for (let d = -w/2; d <= w/2; d++) {
      let perpX = px + cos(angle + HALF_PI) * d;
      let perpY = py + sin(angle + HALF_PI) * d;

      if (isRight) {
        let dist = abs(perpX - 780) / 400;
        let dissolveChance = constrain(dist * 0.7, 0, 0.9);
        if (random() < dissolveChance) continue;
        let alpha_val = lerp(160, 20, dist);
        let grayVal = lerp(130, 210, dist);
        stroke(grayVal, grayVal - 5, grayVal + 5, alpha_val);
      } else {
        let barkN = noise(perpX * 0.05, perpY * 0.05);
        stroke(45 + barkN * 35, 32 + barkN * 22, 22 + barkN * 12);
      }
      strokeWeight(1);
      point(perpX, perpY);
    }
  }

  // Sub-branches
  let numSub = floor(random(2, 4));
  for (let i = 0; i < numSub; i++) {
    let newAngle = angle + random(-0.5, 0.5);
    let newLen = len * random(0.4, 0.7);
    let branchPoint = random(0.3, 0.8);
    let bx = lerp(x, endX, branchPoint);
    let by = lerp(y, endY, branchPoint);
    drawBranchRecursive(bx, by, newAngle, newLen, weight * 0.5, depth + 1, maxDepth, side);
  }
}

function drawRoots(startX, startY) {
  let numRoots = 8;
  for (let i = 0; i < numRoots; i++) {
    let side = i < 4 ? -1 : 1;
    let angle = side === -1 ? random(PI * 0.15, PI * 0.85) : random(PI * 0.15, PI * 0.85);
    let len = random(100, 250);
    let weight = random(3, 8);
    drawRootRecursive(startX + random(-15, 15), startY + random(-5, 10), angle, len, weight, 0, 3, side);
  }
}

function drawRootRecursive(x, y, angle, len, weight, depth, maxDepth, side) {
  if (depth > maxDepth || len < 15) return;

  let endX = x + cos(angle) * len;
  let endY = y + sin(angle) * len;

  let isRight = side === 1;

  for (let i = 0; i < max(1, floor(len / 2)); i++) {
    let t = i / max(1, floor(len / 2));
    let px = lerp(x, endX, t);
    let py = lerp(y, endY, t);
    let w = lerp(weight, weight * 0.3, t);

    let waveX = sin(t * 4 + depth) * 5;
    px += waveX;

    for (let d = -w/2; d <= w/2; d++) {
      let perpX = px + cos(angle + HALF_PI) * d;
      let perpY = py + sin(angle + HALF_PI) * d;

      if (isRight) {
        let dist = abs(perpX - 780) / 400;
        let dissolveChance = constrain(dist * 0.5, 0, 0.8);
        if (random() < dissolveChance) continue;
        let alpha_val = lerp(140, 20, dist);
        let grayVal = lerp(140, 210, dist);
        stroke(grayVal, grayVal - 3, grayVal + 3, alpha_val);
      } else {
        let rootN = noise(perpX * 0.04, perpY * 0.04);
        stroke(55 + rootN * 25, 38 + rootN * 18, 25 + rootN * 12);
      }
      strokeWeight(1);
      point(perpX, perpY);
    }
  }

  let numSub = floor(random(1, 3));
  for (let i = 0; i < numSub; i++) {
    let newAngle = angle + random(-0.4, 0.4);
    let newLen = len * random(0.4, 0.65);
    let branchPoint = random(0.4, 0.8);
    let bx = lerp(x, endX, branchPoint);
    let by = lerp(y, endY, branchPoint);
    drawRootRecursive(bx, by, newAngle, newLen, weight * 0.5, depth + 1, maxDepth, side);
  }
}

function drawLeavesAlive() {
  noStroke();

  // Autumn palette
  let colors = [
    [200, 50, 20],   // deep red
    [220, 100, 20],  // orange
    [240, 170, 30],  // golden
    [180, 40, 40],   // crimson
    [160, 90, 20],   // brown-orange
    [230, 140, 50],  // amber
    [150, 30, 30],   // dark red
  ];

  // Cluster leaves around left branch areas
  for (let i = 0; i < 4000; i++) {
    let angle = random(-PI, -PI * 0.1);
    let dist = random(30, 320);
    let baseX = 780 + cos(angle) * dist * random(0.3, 1);
    let baseY = height * 0.25 - 40 + sin(angle) * dist * random(0.5, 1);

    // Only left side
    if (baseX > 790) continue;
    if (baseY > height * 0.55 || baseY < height * 0.05) continue;

    let ci = floor(random(colors.length));
    let c = colors[ci];
    let n = noise(baseX * 0.01, baseY * 0.01);

    let size = random(4, 14);
    let alpha_val = random(150, 255);

    fill(c[0] + n * 30 - 15, c[1] + n * 20 - 10, c[2] + n * 10, alpha_val);

    // Leaf shape
    push();
    translate(baseX, baseY);
    rotate(random(TWO_PI));
    ellipse(0, 0, size, size * 0.6);
    pop();
  }

  // Some scattered glowing leaves for depth
  for (let i = 0; i < 500; i++) {
    let x = random(200, 770);
    let y = random(height * 0.08, height * 0.52);
    let ci = floor(random(colors.length));
    let c = colors[ci];
    let size = random(2, 6);
    fill(c[0], c[1], c[2], random(40, 120));
    ellipse(x, y, size, size * 0.7);
  }
}

function drawDissolvingLeaves() {
  noStroke();

  // Particles that dissolve into nothing on right side
  for (let i = 0; i < 5000; i++) {
    let angle = random(-PI * 0.9, -PI * 0.05);
    let dist = random(30, 400);
    let baseX = 780 + cos(angle) * dist * random(0.3, 1.2);
    let baseY = height * 0.25 - 40 + sin(angle) * dist * random(0.5, 1);

    // Only right side
    if (baseX < 790) continue;
    if (baseY > height * 0.6 || baseY < height * 0.02) continue;

    let distFromCenter = (baseX - 790) / (width - 790);

    // Dissolve probability increases with distance
    if (random() < distFromCenter * 0.6) continue;

    // Transition from warm to gray to white
    let warmth = 1 - constrain(distFromCenter * 1.5, 0, 1);

    let r = lerp(210, 230, distFromCenter) + random(-10, 10);
    let g = lerp(160 * warmth + 180 * (1-warmth), 225, distFromCenter) + random(-10, 10);
    let b = lerp(80 * warmth + 190 * (1-warmth), 230, distFromCenter) + random(-5, 5);
    let a = lerp(180, 10, distFromCenter * 1.2);

    let size = lerp(random(3, 10), random(1, 4), distFromCenter);

    fill(r, g, b, a);
    ellipse(baseX, baseY, size, size * random(0.4, 0.8));
  }
}

function drawFallingLeaves() {
  noStroke();

  // Leaves in transition - falling from tree and transforming
  for (let i = 0; i < 300; i++) {
    let x = random(500, 1100);
    let y = random(height * 0.2, height * 0.65);

    let tx = (x - 500) / 600;

    // Falling trajectory - slight curve
    let fallProgress = (y - height * 0.2) / (height * 0.45);

    // Color transitions from warm to gray
    let warmth = 1 - constrain(tx, 0, 1);
    let r = lerp(190, 220, tx);
    let g = lerp(80, 200, tx);
    let b = lerp(20, 210, tx);
    let a = lerp(200, 40, tx * 0.8);

    let size = lerp(8, 3, tx);

    fill(r + random(-15, 15), g + random(-15, 15), b + random(-10, 10), a);

    push();
    translate(x, y);
    rotate(random(TWO_PI));
    // Leaf shape that becomes more point-like as it dissolves
    if (warmth > 0.4) {
      beginShape();
      vertex(0, -size/2);
      bezierVertex(size/2, -size/4, size/2, size/4, 0, size/2);
      bezierVertex(-size/2, size/4, -size/2, -size/4, 0, -size/2);
      endShape(CLOSE);
    } else {
      ellipse(0, 0, size, size * 0.5);
    }
    pop();
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Sky gradient - from warm living gold to cold ashen gray
  for (let y = 0; y < height * 0.65; y++) {
    let t = y / (height * 0.65);
    let r = lerp(45, 220, pow(t, 0.4));
    let g = lerp(20, 160, pow(t, 0.5));
    let b = lerp(60, 80, pow(t, 0.7));

    // Left side warm, right side cold
    for (let x = 0; x < width; x++) {
      let xt = x / width;
      let coldness = pow(xt, 0.8);
      let fr = lerp(r, r * 0.4 + 60, coldness);
      let fg = lerp(g, g * 0.3 + 50, coldness);
      let fb = lerp(b, b * 0.5 + 70, coldness);

      // Add subtle noise texture
      let n = noise(x * 0.003, y * 0.003) * 20 - 10;
      stroke(fr + n, fg + n, fb + n);
      point(x, y);
    }
  }

  // Ground
  for (let y = height * 0.65; y < height; y++) {
    let t = (y - height * 0.65) / (height * 0.35);
    for (let x = 0; x < width; x++) {
      let xt = x / width;
      let coldness = pow(xt, 0.8);

      // Warm earth to cold dark
      let r = lerp(70, 25, t) + noise(x * 0.01, y * 0.01) * 30;
      let g = lerp(50, 15, t) + noise(x * 0.01 + 100, y * 0.01) * 20;
      let b = lerp(30, 20, t) + noise(x * 0.01 + 200, y * 0.01) * 15;

      r = lerp(r, r * 0.5 + 20, coldness);
      g = lerp(g, g * 0.4 + 15, coldness);
      b = lerp(b, b * 0.6 + 25, coldness);

      stroke(r, g, b);
      point(x, y);
    }
  }

  // Draw the tree
  let treeX = width * 0.45;
  let treeGround = height * 0.65;

  // Roots (mirror of branches, below ground)
  drawRoots(treeX, treeGround, -PI / 2, 180, 8, 0);

  // Trunk
  noStroke();
  for (let i = -25; i <= 25; i++) {
    let w = abs(i) / 25;
    let alpha = (1 - w * w) * 255;
    let darkness = 20 + w * 30;
    fill(darkness, darkness - 5, darkness + 5, alpha);
    let trunkTop = treeGround - 350;
    beginShape();
    vertex(treeX + i * 1.8, treeGround + 20);
    bezierVertex(
      treeX + i * 1.6, treeGround - 100,
      treeX + i * 1.2, treeGround - 200,
      treeX + i * 0.8, trunkTop
    );
    vertex(treeX + i * 0.8, trunkTop);
    vertex(treeX + i * 1.8, treeGround + 20);
    endShape(CLOSE);
  }

  // Branches
  drawBranches(treeX, treeGround - 340, -PI / 2, 160, 9, 0);

  // Falling petals - scattered across the scene
  drawPetals();

  // Atmospheric haze layers
  for (let y = 0; y < height; y++) {
    let horizonDist = abs(y - height * 0.65);
    if (horizonDist < 100) {
      let hazeAlpha = (1 - horizonDist / 100) * 40;
      stroke(180, 160, 140, hazeAlpha);
      line(0, y, width, y);
    }
  }

  // Soft light rays from upper left
  drawLightRays();

  // Vignette
  drawVignette();
}

function drawBranches(x, y, angle, len, depth, side) {
  if (depth <= 0 || len < 3) return;

  let endX = x + cos(angle) * len;
  let endY = y + sin(angle) * len;

  // Branch thickness based on depth
  let sw = map(depth, 0, 9, 0.5, 22);

  // Color: darker for main branches, more gray-purple for thin ones
  let lifeAmount = map(x, 0, width, 1, 0);
  let r = lerp(40, 55, 1 - depth / 9) + lifeAmount * 15;
  let g = lerp(30, 40, 1 - depth / 9) + lifeAmount * 10;
  let b = lerp(35, 50, 1 - depth / 9);

  stroke(r, g, b, 220);
  strokeWeight(sw);
  noFill();

  // Slight curve
  let midX = (x + endX) / 2 + random(-len * 0.1, len * 0.1);
  let midY = (y + endY) / 2 + random(-len * 0.08, len * 0.08);

  beginShape();
  vertex(x, y);
  quadraticVertex(midX, midY, endX, endY);
  endShape();

  // Branch into 2-3 sub-branches
  let numBranches = depth > 5 ? 3 : 2;
  let spreadBase = PI * 0.25;

  for (let i = 0; i < numBranches; i++) {
    let newAngle = angle + map(i, 0, numBranches - 1, -spreadBase, spreadBase);
    newAngle += random(-0.15, 0.15);

    // Slight upward bias
    if (newAngle > -0.1) newAngle -= 0.3;

    let newLen = len * random(0.6, 0.78);

    // On the right (death) side, branches droop and thin more
    let deathInfluence = map(endX, 0, width, 0, 1);
    if (deathInfluence > 0.5) {
      newAngle += (deathInfluence - 0.5) * 0.4;
      newLen *= lerp(1, 0.85, deathInfluence);
    }

    drawBranches(endX, endY, newAngle, newLen, depth - 1, i);
  }

  // Leaf clusters at branch tips
  if (depth <= 3) {
    let lifeT = map(endX, 0, width, 1, 0);
    lifeT = constrain(lifeT, 0, 1);

    let numLeaves = floor(lifeT * 12) + 1;
    noStroke();
    for (let i = 0; i < numLeaves; i++) {
      let lx = endX + random(-20, 20);
      let ly = endY + random(-20, 15);
      let sz = random(4, 14) * lifeT;

      // Colors: warm on left (alive), sparse gray on right (dead)
      if (lifeT > 0.3) {
        let leafR = lerp(180, 60, random(1)) + random(-20, 20);
        let leafG = lerp(80, 140, random(1)) + random(-15, 15);
        let leafB = lerp(30, 50, random(1));
        let leafA = lifeT * 200;
        fill(leafR, leafG, leafB, leafA);
        ellipse(lx, ly, sz, sz * 1.3);
      } else if (random(1) > 0.6) {
        fill(80, 70, 65, 100);
        ellipse(lx, ly, sz * 0.5, sz * 0.7);
      }
    }
  }
}

function drawRoots(x, y, angle, len, depth, side) {
  if (depth <= 0 || len < 3) return;

  let endX = x + cos(-angle - PI) * len * 0.8;
  let endY = y - sin(-angle - PI) * len * 0.8;

  // Ensure roots go downward
  if (endY < y && depth > 6) endY = y + abs(endY - y);

  let sw = map(depth, 0, 8, 0.5, 18);

  // Roots are darker, more earth-toned
  let r = 40 + noise(endX * 0.01, endY * 0.01) * 25;
  let g = 30 + noise(endX * 0.01 + 50, endY * 0.01) * 15;
  let b = 25 + noise(endX * 0.01 + 100, endY * 0.01) * 15;

  // Fade roots as they go deeper
  let depthFade = map(endY, treeGroundY(), height, 220, 40);

  stroke(r, g, b, depthFade);
  strokeWeight(sw);
  noFill();

  let midX = (x + endX) / 2 + random(-len * 0.12, len * 0.12);
  let midY = (y + endY) / 2 + random(-len * 0.05, len * 0.05);

  beginShape();
  vertex(x, y);
  quadraticVertex(midX, midY, endX, endY);
  endShape();

  let numBranches = depth > 5 ? 3 : 2;
  let spread = PI * 0.3;

  for (let i = 0; i < numBranches; i++) {
    let baseAngle = PI / 2; // downward
    let newAngle = baseAngle + map(i, 0, numBranches - 1, -spread, spread);
    newAngle += random(-0.2, 0.2);

    let newLen = len * random(0.55, 0.75);

    let newEndX = endX + cos(newAngle) * newLen;
    let newEndY = endY + sin(newAngle) * newLen;

    if (newEndY > endY - 5) {
      drawRootSegment(endX, endY, newAngle, newLen, depth - 1);
    }
  }

  // Small glowing dots at root tips (life below)
  if (depth <= 2) {
    noStroke();
    let glowR = 160 + random(-30, 30);
    let glowG = 120 + random(-20, 20);
    let glowB = 60;
    for (let g2 = 20; g2 > 0; g2--) {
      fill(glowR, glowG, glowB, map(g2, 20, 0, 5, 30));
      ellipse(endX, endY, g2, g2);
    }
  }
}

function drawRootSegment(x, y, angle, len, depth) {
  if (depth <= 0 || len < 3) return;

  let endX = x + cos(angle) * len;
  let endY = y + sin(angle) * len;

  if (endY < y) endY = y + 5;
  endY = min(endY, height - 20);

  let sw = map(depth, 0, 8, 0.3, 12);
  let depthFade = map(endY, treeGroundY(), height, 200, 20);

  stroke(45, 32, 28, depthFade);
  strokeWeight(sw);
  noFill();

  let midX = (x + endX) / 2 + random(-8, 8);
  let midY = (y + endY) / 2 + random(-5, 5);

  beginShape();
  vertex(x, y);
  quadraticVertex(midX, midY, endX, endY);
  endShape();

  let numB = 2;
  for (let i = 0; i < numB; i++) {
    let na = angle + random(-0.5, 0.5);
    if (sin(na) < 0.1) na = PI / 2 + random(-0.4, 0.4);
    drawRootSegment(endX, endY, na, len * random(0.5, 0.7), depth - 1);
  }

  if (depth <= 2) {
    noStroke();
    for (let g2 = 15; g2 > 0; g2--) {
      fill(150, 110, 50, map(g2, 15, 0, 3, 25));
      ellipse(endX, endY, g2, g2);
    }
  }
}

function treeGroundY() {
  return height * 0.65;
}

function drawPetals() {
  noStroke();

  for (let i = 0; i < 400; i++) {
    let px = random(width);
    let py = random(height * 0.1, height * 0.75);

    // More petals on the left (living) side, but some drift right
    let density = map(px, 0, width, 0.9, 0.15);
    if (random(1) > density) continue;

    let sz = random(3, 10);

    // Petal direction: some fall down, some float up
    let goingUp = random(1) < 0.35;

    // Color based on position
    let lifeT = map(px, 0, width, 1, 0);
    let r, g, b, a;

    if (lifeT > 0.4) {
      // Living side: warm reds, oranges, pinks
      let palette = floor(random(4));
      if (palette === 0) { r = 200; g = 60; b = 70; }
      else if (palette === 1) { r = 220; g = 130; b = 60; }
      else if (palette === 2) { r = 210; g = 80; b = 100; }
      else { r = 180; g = 50; b = 60; }
      r += random(-25, 25);
      g += random(-15, 15);
      b += random(-10, 10);
      a = random(120, 230);
    } else {
      // Dying side: pale, desaturated
      r = 140 + random(-20, 20);
      g = 120 + random(-20, 20);
      b = 110 + random(-15, 15);
      a = random(40, 120);
    }

    fill(r, g, b, a);

    push();
    translate(px, py);
    rotate(random(TWO_PI));

    // Draw petal shape
    beginShape();
    for (let angle = 0; angle < TWO_PI; angle += 0.3) {
      let rad = sz * (1 + 0.3 * sin(angle * 2.5));
      vertex(cos(angle) * rad * 0.6, sin(angle) * rad);
    }
    endShape(CLOSE);
    pop();

    // Slight trail for falling petals
    if (!goingUp && sz > 5) {
      stroke(r, g, b, a * 0.3);
      strokeWeight(0.5);
      let trailLen = random(10, 30);
      line(px, py, px + random(-5, 5), py - trailLen);
      noStroke();
    }
  }

  // A few petals rising on the left side (life force)
  for (let i = 0; i < 60; i++) {
    let px = random(width * 0.05, width * 0.4);
    let py = random(height * 0.05, height * 0.5);
    let sz = random(2, 7);

    fill(200 + random(-20, 20), 70 + random(-20, 20), 80 + random(-15, 15), random(80, 180));
    push();
    translate(px, py);
    rotate(random(TWO_PI));
    ellipse(0, 0, sz, sz * 1.5);
    pop();

    // Upward trail
    stroke(200, 80, 80, 40);
    strokeWeight(0.4);
    line(px, py, px + random(-3, 3), py + random(8, 20));
    noStroke();
  }
}

function drawLightRays() {
  // Soft golden light rays from upper-left
  let rayOriginX = -100;
  let rayOriginY = -100;

  for (let i = 0; i < 12; i++) {
    let angle = map(i, 0, 12, 0.3, 1.1);
    let rayLen = random(1200, 2200);

    let endRayX = rayOriginX + cos(angle) * rayLen;
    let endRayY = rayOriginY + sin(angle) * rayLen;

    let rayWidth = random(40, 120);

    for (let w = -rayWidth / 2; w < rayWidth / 2; w++) {
      let alpha = (1 - abs(w) / (rayWidth / 2)) * 8;

      let perpAngle = angle + PI / 2;
      let sx = rayOriginX + cos(perpAngle) * w;
      let sy = rayOriginY + sin(perpAngle) * w;
      let ex = endRayX + cos(perpAngle) * w;
      let ey = endRayY + sin(perpAngle) * w;

      stroke(255, 220, 150, alpha);
      strokeWeight(1);
      line(sx, sy, ex, ey);
    }
  }
}

function drawVignette() {
  noStroke();
  // Dark vignette around edges
  let maxDist = dist(0, 0, width / 2, height / 2);

  for (let r = 0; r < 60; r++) {
    let alpha = map(r, 0, 60, 35, 0);

    // Top
    fill(10, 5, 15, alpha);
    rect(0, r * 2, width, 3);

    // Bottom
    fill(5, 2, 10, alpha);
    rect(0, height - r * 3, width, 3);

    // Left
    fill(10, 5, 15, alpha * 0.5);
    rect(r * 2, 0, 3, height);

    // Right - stronger (death side)
    fill(5, 2, 10, alpha * 1.2);
    rect(width - r * 3, 0, 3, height);
  }

  // Extra darkness on right side
  for (let x = width * 0.7; x < width; x++) {
    let t = map(x, width * 0.7, width, 0, 1);
    stroke(10, 5, 15, t * t * 50);
    line(x, 0, x, height);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Sky gradient - left side warm/alive, right side cold/fading
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let tx = x / width;
      let ty = y / height;

      // Living side (left): warm golden sunset
      let lr = lerp(255, 180, ty) * 0.9;
      let lg = lerp(180, 80, ty) * 0.85;
      let lb = lerp(120, 60, ty) * 0.7;

      // Death side (right): cold grey-blue
      let dr = lerp(140, 50, ty) * 0.7;
      let dg = lerp(140, 50, ty) * 0.7;
      let db = lerp(160, 70, ty) * 0.8;

      // Blend based on x position with soft transition
      let blend = smoothstep(0.3, 0.7, tx);
      let r = lerp(lr, dr, blend);
      let g = lerp(lg, dg, blend);
      let b = lerp(lb, db, blend);

      // Add subtle noise texture
      let n = noise(x * 0.003, y * 0.003) * 20 - 10;
      set(x, y, color(r + n, g + n, b + n));
    }
  }
  updatePixels();

  // Ground
  drawGround();

  // Falling petals / particles throughout
  drawFallingPetals();

  // The tree
  drawTree(width * 0.48, height * 0.58);

  // Foreground petals on ground
  drawGroundPetals();

  // Overlay: subtle vignette
  drawVignette();

  // Atmospheric particles / dust motes
  drawDustMotes();
}

function smoothstep(edge0, edge1, x) {
  let t = constrain((x - edge0) / (edge1 - edge0), 0, 1);
  return t * t * (3 - 2 * t);
}

function drawGround() {
  noStroke();
  for (let y = height * 0.58; y < height; y++) {
    for (let x = 0; x < width; x += 2) {
      let tx = x / width;
      let ty = (y - height * 0.58) / (height * 0.42);
      let blend = smoothstep(0.3, 0.7, tx);

      let n = noise(x * 0.005, y * 0.005) * 40;

      // Living ground: rich earth with green
      let lr = 60 + 40 * ty + n * 0.5;
      let lg = 80 - 20 * ty + n * 0.3;
      let lb = 30 + n * 0.2;

      // Death ground: grey ash
      let dr = 70 + 20 * ty + n * 0.3;
      let dg = 65 + 15 * ty + n * 0.3;
      let db = 65 + 15 * ty + n * 0.3;

      let r = lerp(lr, dr, blend);
      let g = lerp(lg, dg, blend);
      let b = lerp(lb, db, blend);

      fill(r, g, b);
      noStroke();
      rect(x, y, 2, 1);
    }
  }

  // Grass tufts on living side
  for (let i = 0; i < 600; i++) {
    let gx = random(0, width * 0.6);
    let gy = random(height * 0.6, height);
    let tx = gx / width;
    let alph = map(tx, 0, 0.6, 200, 20);
    let grassH = random(10, 40);

    stroke(40 + random(30), 90 + random(50), 20 + random(20), alph);
    strokeWeight(random(1, 2.5));
    let sway = noise(gx * 0.01, gy * 0.01) * 10 - 5;
    line(gx, gy, gx + sway, gy - grassH);
  }

  // Dead grass/sticks on death side
  for (let i = 0; i < 300; i++) {
    let gx = random(width * 0.5, width);
    let gy = random(height * 0.6, height);
    let tx = gx / width;
    let alph = map(tx, 0.5, 1, 30, 150);
    let grassH = random(5, 25);

    stroke(90 + random(30), 80 + random(20), 70 + random(20), alph);
    strokeWeight(random(0.5, 1.5));
    let sway = noise(gx * 0.01, gy * 0.01) * 15 - 7;
    line(gx, gy, gx + sway, gy - grassH);
  }
}

function drawTree(tx, ty) {
  // Draw the main tree using recursive branching
  let trunkColor = color(50, 35, 25);

  // Start with trunk
  push();
  translate(tx, ty);
  drawBranch(0, 0, -PI / 2, 160, 28, 0, trunkColor);
  pop();

  // Roots
  push();
  translate(tx, ty);
  for (let i = 0; i < 7; i++) {
    let ang = random(PI * 0.1, PI * 0.9);
    let rootLen = random(60, 140);
    drawRoot(0, 0, ang, rootLen, random(6, 12));
  }
  pop();
}

function drawBranch(x, y, angle, len, thickness, depth, col) {
  if (depth > 10 || len < 4 || thickness < 0.5) return;

  let endX = x + cos(angle) * len;
  let endY = y + sin(angle) * len;

  // Determine which side of canvas this branch is on for color
  let worldX = width * 0.48 + endX;
  let sideFactor = smoothstep(0.3, 0.7, worldX / width);

  // Branch color: brown on living side, grey on death side
  let r = lerp(50, 80, sideFactor) + random(-5, 5);
  let g = lerp(35, 75, sideFactor) + random(-5, 5);
  let b = lerp(25, 70, sideFactor) + random(-5, 5);

  stroke(r, g, b);
  strokeWeight(thickness);
  noFill();

  // Slightly curved branch
  let midX = (x + endX) / 2 + random(-len * 0.1, len * 0.1);
  let midY = (y + endY) / 2 + random(-len * 0.1, len * 0.1);

  beginShape();
  vertex(x, y);
  quadraticVertex(midX, midY, endX, endY);
  endShape();

  // Leaves/blossoms on living side, bare or sparse on death side
  if (depth > 4 && len < 30) {
    let leafWorldX = width * 0.48 + endX;
    let leafSide = leafWorldX / width;

    if (leafSide < 0.55) {
      // Living side: colorful leaves and blossoms
      let numLeaves = floor(random(2, 6));
      for (let i = 0; i < numLeaves; i++) {
        let lx = endX + random(-15, 15);
        let ly = endY + random(-15, 10);
        noStroke();

        let leafType = random();
        if (leafType < 0.4) {
          // Green leaf
          fill(30 + random(40), 120 + random(80), 20 + random(30), 180 + random(75));
          ellipse(lx, ly, random(6, 14), random(4, 10));
        } else if (leafType < 0.7) {
          // Pink blossom
          fill(220 + random(35), 100 + random(60), 120 + random(50), 170 + random(85));
          drawFlower(lx, ly, random(4, 10));
        } else {
          // White/yellow blossom
          fill(240 + random(15), 220 + random(35), 150 + random(60), 160 + random(90));
          drawFlower(lx, ly, random(3, 8));
        }
      }
    } else if (leafSide < 0.65) {
      // Transition zone: some withering leaves
      let numLeaves = floor(random(1, 3));
      for (let i = 0; i < numLeaves; i++) {
        let lx = endX + random(-12, 12);
        let ly = endY + random(-12, 8);
        noStroke();
        let fade = map(leafSide, 0.55, 0.65, 0, 1);
        let gr = lerp(60, 140, fade);
        let gg = lerp(140, 110, fade);
        let gb = lerp(30, 60, fade);
        fill(gr + random(20), gg + random(20), gb + random(20), 120 + random(60));
        ellipse(lx, ly, random(4, 10), random(3, 8));
      }
    }
    // Death side: bare branches, no leaves
  }

  // Branching
  let numBranches = random() < 0.3 ? 3 : 2;
  for (let i = 0; i < numBranches; i++) {
    let newAngle = angle + random(-0.6, 0.6);
    let newLen = len * random(0.6, 0.8);
    let newThick = thickness * random(0.5, 0.75);
    drawBranch(endX, endY, newAngle, newLen, newThick, depth + 1, col);
  }
}

function drawRoot(x, y, angle, len, thickness) {
  if (len < 8 || thickness < 1) return;

  let endX = x + cos(angle) * len;
  let endY = y + sin(angle) * len;

  let worldX = width * 0.48 + endX;
  let sideFactor = smoothstep(0.3, 0.7, worldX / width);

  let r = lerp(45, 70, sideFactor);
  let g = lerp(30, 60, sideFactor);
  let b = lerp(20, 55, sideFactor);

  stroke(r, g, b);
  strokeWeight(thickness);
  noFill();

  let midX = (x + endX) / 2 + random(-len * 0.15, len * 0.15);
  let midY = (y + endY) / 2 + random(-len * 0.05, len * 0.05);

  beginShape();
  vertex(x, y);
  quadraticVertex(midX, midY, endX, endY);
  endShape();

  // Sub-roots
  if (random() < 0.6) {
    let newAngle = angle + random(-0.5, 0.5);
    drawRoot(endX, endY, newAngle, len * random(0.5, 0.7), thickness * 0.6);
  }
  if (random() < 0.3) {
    let newAngle = angle + random(-0.7, 0.7);
    drawRoot(endX, endY, newAngle, len * random(0.4, 0.6), thickness * 0.5);
  }
}

function drawFlower(x, y, size) {
  push();
  translate(x, y);
  for (let i = 0; i < 5; i++) {
    let ang = (TWO_PI / 5) * i + random(-0.2, 0.2);
    let px = cos(ang) * size * 0.6;
    let py = sin(ang) * size * 0.6;
    ellipse(px, py, size, size * 0.7);
  }
  pop();
}

function drawFallingPetals() {
  noStroke();
  for (let i = 0; i < 200; i++) {
    let px = random(width * 0.05, width * 0.65);
    let py = random(height * 0.05, height * 0.95);

    let tx = px / width;
    let distFromTree = dist(px, py, width * 0.48, height * 0.4);
    if (distFromTree > 500 && random() > 0.3) continue;

    let petalType = random();
    let size = random(3, 9);
    let alpha = random(80, 200);

    // Mostly pink/white petals falling
    if (petalType < 0.5) {
      fill(230 + random(25), 140 + random(60), 150 + random(50), alpha);
    } else if (petalType < 0.8) {
      fill(255, 240 + random(15), 220 + random(30), alpha);
    } else {
      // Some petals turning grey as they fall toward death side
      let grey = lerp(200, 130, smoothstep(0.3, 0.7, tx));
      fill(grey + random(20), grey - 10 + random(15), grey - 5 + random(15), alpha * 0.7);
    }

    push();
    translate(px, py);
    rotate(random(TWO_PI));
    ellipse(0, 0, size, size * 0.5);
    pop();
  }

  // Dissolving particles on the death side — petals becoming dust
  for (let i = 0; i < 150; i++) {
    let px = random(width * 0.5, width * 0.95);
    let py = random(height * 0.1, height * 0.85);
    let size = random(1, 5);
    let alpha = random(30, 100);
    let grey = random(100, 180);

    fill(grey, grey - 10, grey + 10, alpha);
    ellipse(px, py, size, size);
  }
}

function drawGroundPetals() {
  noStroke();
  // Dense layer of petals on ground, transforming from colorful to grey
  for (let i = 0; i < 400; i++) {
    let px = random(width * 0.1, width * 0.9);
    let py = random(height * 0.6, height * 0.95);
    let tx = px / width;
    let blend = smoothstep(0.3, 0.7, tx);

    let size = random(3, 10);
    let alpha = random(100, 220);

    // Color transitions from vibrant to grey
    let r = lerp(210 + random(40), 100 + random(30), blend);
    let g = lerp(100 + random(60), 90 + random(20), blend);
    let b = lerp(110 + random(50), 85 + random(20), blend);

    fill(r, g, b, alpha);
    push();
    translate(px, py);
    rotate(random(TWO_PI));
    ellipse(0, 0, size, size * random(0.4, 0.7));
    pop();

    // Some petals sprouting tiny green shoots on ground (rebirth)
    if (blend > 0.4 && blend < 0.8 && random() < 0.08) {
      stroke(50 + random(30), 100 + random(50), 30, 150);
      strokeWeight(1);
      let shootH = random(5, 15);
      line(px, py, px + random(-3, 3), py - shootH);
      noStroke();
      fill(60 + random(30), 120 + random(50), 30 + random(20), 180);
      ellipse(px + random(-3, 3), py - shootH, 4, 3);
    }
  }
}

function drawDustMotes() {
  // Luminous dust particles catching light
  noStroke();
  for (let i = 0; i < 100; i++) {
    let px = random(width);
    let py = random(height * 0.6);
    let size = random(2, 6);
    let tx = px / width;
    let blend = smoothstep(0.3, 0.7, tx);

    // Warm light particles on left, cold on right
    let r = lerp(255, 180, blend);
    let g = lerp(230, 190, blend);
    let b = lerp(180, 210, blend);
    let alpha = random(20, 70);

    fill(r, g, b, alpha);
    ellipse(px, py, size, size);

    // Soft glow
    fill(r, g, b, alpha * 0.3);
    ellipse(px, py, size * 3, size * 3);
  }
}

function drawVignette() {
  // Soft dark vignette around edges
  noStroke();
  let cx = width / 2;
  let cy = height / 2;
  let maxDist = dist(0, 0, cx, cy);

  for (let r = maxDist; r > maxDist * 0.5; r -= 2) {
    let alpha = map(r, maxDist * 0.5, maxDist, 0, 80);
    fill(10, 5, 15, alpha);
    ellipse(cx, cy, r * 2, r * 2 * (height / width));
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Sky gradient - living side (left) warm, dead side (right) cold
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let tx = x / width;
      let ty = y / height;

      // Living sky (warm golden)
      let lr = lerp(255, 180, ty);
      let lg = lerp(200, 100, ty);
      let lb = lerp(120, 60, ty);

      // Dead sky (ashen grey-violet)
      let dr = lerp(180, 50, ty);
      let dg = lerp(170, 40, ty);
      let db = lerp(180, 55, ty);

      let r = lerp(lr, dr, tx);
      let g = lerp(lg, dg, tx);
      let b = lerp(lb, db, tx);

      set(x, y, color(r, g, b));
    }
  }
  updatePixels();

  // Ground
  drawGround();

  // Distant trees/fog
  drawDistantElements();

  // Main tree
  drawTree(800, 1400, -PI/2, 220, 18, 0);

  // Falling petals/leaves
  drawFallingPetals();

  // Roots visible above ground
  drawRoots(800, 1420);

  // Atmospheric overlay
  drawAtmosphere();
}

function drawGround() {
  // Ground with transition
  for (let y = 1350; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let tx = x / width;
      let ty = (y - 1350) / (height - 1350);
      let n = noise(x * 0.005, y * 0.005) * 0.3;

      // Living ground (rich earth, green)
      let lr = 60 + 40 * ty + n * 60;
      let lg = 90 - 30 * ty + n * 40;
      let lb = 30 + n * 20;

      // Dead ground (grey, ashen)
      let dr = 70 + 20 * ty + n * 30;
      let dg = 65 + 15 * ty + n * 25;
      let db = 60 + 15 * ty + n * 25;

      let r = lerp(lr, dr, tx);
      let g = lerp(lg, dg, tx);
      let b = lerp(lb, db, tx);

      // Add some texture
      let tex = noise(x * 0.02, y * 0.02) * 20 - 10;

      set(x, y, color(r + tex, g + tex, b + tex));
    }
  }
  updatePixels();

  // Ground plants on living side
  noStroke();
  for (let i = 0; i < 300; i++) {
    let gx = random(0, 700);
    let gy = random(1380, 1900);
    let gh = random(15, 50);
    let vitality = 1 - gx / 800;

    stroke(40 + random(30), 80 + random(60) * vitality, 20 + random(20), 150);
    strokeWeight(1.5);
    let sway = noise(gx * 0.01, i) * 0.3 - 0.15;
    line(gx, gy, gx + sin(sway) * gh * 0.3, gy - gh);
  }

  // Dead plants on right side
  for (let i = 0; i < 200; i++) {
    let gx = random(900, 1600);
    let gy = random(1380, 1900);
    let gh = random(10, 40);
    let decay = (gx - 800) / 800;

    stroke(100 + random(30) * decay, 90 + random(20) * decay, 80 + random(20) * decay, 120);
    strokeWeight(1);
    let sway = noise(gx * 0.01, i) * 0.5 - 0.25;
    line(gx, gy, gx + sin(sway) * gh * 0.4, gy - gh);
  }
}

function drawDistantElements() {
  // Distant trees on living side
  for (let i = 0; i < 15; i++) {
    let tx = random(50, 600);
    let ty = random(1200, 1370);
    let th = random(80, 200);
    let tw = random(40, 80);
    let vitality = 1 - tx / 800;

    noStroke();
    fill(50 + random(20), 70 + random(30) * vitality, 40 + random(20), 60);
    ellipse(tx, ty - th * 0.6, tw * 1.5, th);
    fill(60, 45, 30, 60);
    rect(tx - 3, ty, 6, -th * 0.3);
  }

  // Dead distant trees on right side
  for (let i = 0; i < 12; i++) {
    let tx = random(1000, 1550);
    let ty = random(1200, 1370);
    let th = random(60, 160);

    stroke(80, 70, 65, 50);
    strokeWeight(2);
    noFill();
    line(tx, ty, tx, ty - th);
    line(tx, ty - th * 0.6, tx + random(-30, 30), ty - th * 0.85);
    line(tx, ty - th * 0.75, tx + random(-25, 25), ty - th * 0.95);
  }
}

function drawTree(x, y, angle, len, weight, depth) {
  if (depth > 12 || len < 3) return;

  let endX = x + cos(angle) * len;
  let endY = y + sin(angle) * len;

  // Color transitions based on x position (left=alive, right=dead)
  let midX = (x + endX) / 2;
  let tx = constrain(midX / width, 0, 1);

  // Living bark: warm brown
  let lr = 70, lg2 = 50, lb = 30;
  // Dead bark: grey
  let dr = 90, dg = 85, db = 80;

  let cr = lerp(lr, dr, tx);
  let cg = lerp(lg2, dg, tx);
  let cb = lerp(lb, db, tx);

  stroke(cr, cg, cb);
  strokeWeight(weight);
  line(x, y, endX, endY);

  // Add bark texture for thick branches
  if (weight > 4) {
    for (let t = 0; t < 1; t += 0.1) {
      let bx = lerp(x, endX, t);
      let by = lerp(y, endY, t);
      let n = noise(bx * 0.05, by * 0.05, depth) * 20 - 10;
      stroke(cr + n, cg + n, cb + n, 100);
      strokeWeight(weight * 0.3);
      let perpAngle = angle + PI / 2;
      let offset = (random() - 0.5) * weight;
      point(bx + cos(perpAngle) * offset, by + sin(perpAngle) * offset);
    }
  }

  if (depth < 5) {
    // Main branches
    let branches = depth < 2 ? 3 : 2;
    for (let i = 0; i < branches; i++) {
      let spread = map(i, 0, branches - 1, -0.5, 0.5);
      if (branches == 2) spread = random(-0.5, 0.5);
      let newAngle = angle + spread + random(-0.15, 0.15);
      let newLen = len * random(0.65, 0.8);
      let newWeight = weight * 0.7;
      drawTree(endX, endY, newAngle, newLen, newWeight, depth + 1);
    }
  } else {
    // Smaller branches
    let numBranches = floor(random(1, 4));
    for (let i = 0; i < numBranches; i++) {
      let newAngle = angle + random(-0.8, 0.8);
      let newLen = len * random(0.5, 0.75);
      let newWeight = max(weight * 0.6, 0.5);
      drawTree(endX, endY, newAngle, newLen, newWeight, depth + 1);
    }

    // Leaves/blossoms on living side, bare or bone-white on dead side
    if (depth > 7 && len < 20) {
      drawFoliage(endX, endY, tx);
    }
  }
}

function drawFoliage(x, y, deathFactor) {
  noStroke();
  let n = noise(x * 0.01, y * 0.01);

  if (deathFactor < 0.4) {
    // Living: lush greens and blossoms
    for (let i = 0; i < 8; i++) {
      let ox = random(-20, 20);
      let oy = random(-20, 15);
      let s = random(5, 15);

      if (random() < 0.3) {
        // Blossoms - pinks and whites
        fill(220 + random(35), 150 + random(60), 160 + random(50), 180);
      } else {
        // Leaves
        fill(40 + random(40), 100 + random(80), 30 + random(30), 160);
      }
      ellipse(x + ox, y + oy, s, s * 0.7);
    }
  } else if (deathFactor < 0.6) {
    // Transition: autumn colors, some falling
    for (let i = 0; i < 5; i++) {
      let ox = random(-15, 15);
      let oy = random(-15, 15);
      let s = random(4, 12);
      let autumn = random();
      if (autumn < 0.3) {
        fill(200 + random(55), 100 + random(60), 20 + random(30), 150);
      } else if (autumn < 0.6) {
        fill(180 + random(40), 60 + random(40), 20 + random(20), 140);
      } else {
        fill(160 + random(60), 150 + random(50), 100 + random(40), 100);
      }
      ellipse(x + ox, y + oy, s, s * 0.7);
    }
  } else {
    // Dead side: very sparse, bone-white remnants
    if (random() < 0.15) {
      for (let i = 0; i < 2; i++) {
        let ox = random(-10, 10);
        let oy = random(-10, 10);
        let s = random(3, 7);
        fill(200 + random(40), 195 + random(40), 185 + random(40), 80);
        ellipse(x + ox, y + oy, s, s * 0.6);
      }
    }
  }
}

function drawFallingPetals() {
  noStroke();
  for (let i = 0; i < 400; i++) {
    let startX = random(300, 1100);
    let startY = random(400, 1600);

    let tx = startX / width;
    let fallProgress = (startY - 400) / 1200;

    // Petals transition from colored to white as they fall and move right
    let deathAmount = constrain(tx + fallProgress * 0.3, 0, 1);

    let size = random(3, 10);

    let r, g, b, a;
    if (deathAmount < 0.3) {
      // Pink blossoms
      r = 230 + random(25);
      g = 140 + random(60);
      b = 150 + random(50);
      a = 160 - fallProgress * 40;
    } else if (deathAmount < 0.6) {
      // Transitioning - pale, desaturating
      r = 220 + random(30);
      g = 190 + random(30);
      b = 170 + random(40);
      a = 140 - fallProgress * 30;
    } else {
      // Bone white / ash
      let grey = 200 + random(40);
      r = grey;
      g = grey - random(10);
      b = grey - random(15);
      a = 100 - fallProgress * 30;
    }

    fill(r, g, b, max(a, 20));

    // Petal shape
    push();
    translate(startX, startY);
    rotate(random(TWO_PI));

    ellipse(0, 0, size, size * 0.5);
    pop();
  }
}

function drawRoots(x, y) {
  // Visible roots spreading into both worlds
  let rootData = [];
  for (let i = 0; i < 8; i++) {
    let angle = random(PI * 0.1, PI * 0.9);
    let rootLen = random(150, 350);
    let side = i < 4 ? -1 : 1;

    stroke(65, 45, 30);
    strokeWeight(random(4, 10));
    noFill();

    beginShape();
    let rx = x;
    let ry = y;
    let segments = 8;
    for (let j = 0; j <= segments; j++) {
      let t = j / segments;
      let targetX = x + cos(angle) * rootLen * t * side;
      let targetY = y + sin(angle * 0.5) * rootLen * t * 0.3 + t * 60;
      rx = lerp(rx, targetX, 0.4) + random(-5, 5);
      ry = lerp(ry, targetY, 0.4) + random(-3, 3);

      let rtx = constrain(rx / width, 0, 1);
      let cr = lerp(65, 85, rtx);
      let cg = lerp(45, 80, rtx);
      let cb = lerp(30, 75, rtx);
      stroke(cr, cg, cb, 200 - t * 100);
      strokeWeight(max((1 - t) * 8, 1));

      curveVertex(rx, ry);
    }
    endShape();
  }
}

function drawAtmosphere() {
  // Soft mist / atmosphere
  noStroke();
  for (let i = 0; i < 2000; i++) {
    let ax = random(width);
    let ay = random(height);
    let tx = ax / width;
    let ty = ay / height;

    let n = noise(ax * 0.002, ay * 0.002) ;

    if (n > 0.45) {
      let s = n * 80;
      // Warm mist on left, cool on right
      let r = lerp(255, 180, tx);
      let g = lerp(230, 175, tx);
      let b = lerp(200, 185, tx);
      fill(r, g, b, 3 + n * 5);
      ellipse(ax, ay, s, s);
    }
  }

  // Vignette
  drawingContext.save();
  let gradient = drawingContext.createRadialGradient(800, 1000, 400, 800, 1000, 1200);
  gradient.addColorStop(0, 'rgba(0,0,0,0)');
  gradient.addColorStop(1, 'rgba(0,0,0,0.4)');
  drawingContext.fillStyle = gradient;
  drawingContext.fillRect(0, 0, width, height);
  drawingContext.restore();

  // Subtle light rays from upper left
  for (let i = 0; i < 8; i++) {
    let rayAngle = PI * 0.2 + i * 0.06;
    let rayX = 200 + i * 40;
    let rayLen = 900 + random(300);

    stroke(255, 240, 200, 5);
    strokeWeight(random(20, 60));
    line(rayX, 0, rayX + cos(rayAngle) * rayLen, sin(rayAngle) * rayLen);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Sky gradient - left warm, right cold
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let tx = x / width;
      let ty = y / height;

      // Left side: golden warm
      let lr = lerp(255, 220, ty);
      let lg = lerp(200, 120, ty);
      let lb = lerp(80, 60, ty);

      // Right side: dark purple
      let rr = lerp(80, 20, ty);
      let rg = lerp(50, 10, ty);
      let rb = lerp(120, 60, ty);

      let r = lerp(lr, rr, tx);
      let g = lerp(lg, rg, tx);
      let b = lerp(lb, rb, tx);

      // Add noise texture
      let n = noise(x * 0.003, y * 0.003) * 30 - 15;
      set(x, y, color(r + n, g + n, b + n));
    }
  }
  updatePixels();

  // Sun on left side
  drawSun(300, 350, 180);

  // Moon on right side
  drawMoon(1300, 300, 80);

  // Distant mountains
  drawMountains();

  // River at bottom
  drawRiver();

  // Floating petals in river
  drawPetals();

  // The great tree
  drawTree();

  // Birds rising from dead side
  drawBirds();

  // Atmospheric fog/mist
  drawMist();

  // Varnish effect - subtle grain
  drawGrain();
}

function drawSun(cx, cy, r) {
  noStroke();
  for (let i = r * 3; i > 0; i--) {
    let t = i / (r * 3);
    let a = (1 - t) * 60;
    fill(255, 220, 100, a);
    ellipse(cx, cy, i * 2, i * 2);
  }
  fill(255, 240, 180);
  ellipse(cx, cy, r, r);
  // rays
  for (let angle = 0; angle < TWO_PI; angle += PI / 12) {
    let len = r * 1.5 + random(r);
    stroke(255, 220, 100, 40);
    strokeWeight(2);
    line(cx, cy, cx + cos(angle) * len, cy + sin(angle) * len);
  }
  noStroke();
}

function drawMoon(cx, cy, r) {
  noStroke();
  for (let i = r * 4; i > 0; i--) {
    let t = i / (r * 4);
    let a = (1 - t) * 30;
    fill(180, 180, 220, a);
    ellipse(cx, cy, i * 2, i * 2);
  }
  fill(220, 220, 240);
  ellipse(cx, cy, r * 2, r * 2);
  // crescent shadow
  fill(60, 40, 90);
  ellipse(cx + r * 0.5, cy - r * 0.1, r * 1.7, r * 1.9);

  // craters
  fill(200, 200, 220, 80);
  ellipse(cx - r * 0.3, cy - r * 0.2, r * 0.2, r * 0.2);
  ellipse(cx - r * 0.5, cy + r * 0.3, r * 0.15, r * 0.15);
}

function drawMountains() {
  // Layer 1 - far
  for (let layer = 0; layer < 3; layer++) {
    let baseY = 900 + layer * 120;
    beginShape();
    noStroke();
    let alpha = 60 + layer * 40;
    if (layer === 0) fill(100, 80, 120, alpha);
    else if (layer === 1) fill(70, 60, 100, alpha);
    else fill(50, 40, 80, alpha);

    vertex(0, height);
    for (let x = 0; x <= width; x += 5) {
      let n = noise(x * 0.002 + layer * 100, layer * 50);
      let y = baseY - n * 300 + layer * 50;
      vertex(x, y);
    }
    vertex(width, height);
    endShape(CLOSE);
  }
}

function drawRiver() {
  // Dark flowing river at bottom
  for (let y = 1500; y < 2000; y++) {
    for (let x = 0; x < width; x += 2) {
      let ty = (y - 1500) / 500;
      let wave = sin(x * 0.01 + noise(x * 0.005, y * 0.008) * 5) * 20;
      let tx = x / width;

      // Left side: dark gold water, right: deep indigo
      let r = lerp(60, 15, tx) + wave * 0.3;
      let g = lerp(50, 10, tx) + wave * 0.2;
      let b = lerp(40, 40, tx) + abs(wave) * 0.5;

      let n = noise(x * 0.01, y * 0.01) * 40;
      // Reflective highlights
      let highlight = pow(noise(x * 0.008, y * 0.015), 3) * 80;

      let lr = lerp(lerp(80, 30, tx), r, ty) + n - 20 + highlight;
      let lg = lerp(lerp(70, 20, tx), g, ty) + n - 20 + highlight * 0.7;
      let lbb = lerp(lerp(50, 50, tx), b, ty) + n - 10 + highlight * 0.5;

      noStroke();
      fill(lr, lg, lbb, 200);
      rect(x, y + wave * ty, 2, 1);
    }
  }

  // River edge - organic shore line
  noStroke();
  for (let x = 0; x < width; x += 3) {
    let shoreY = 1500 + noise(x * 0.005) * 60 - 30;
    let tx = x / width;
    fill(lerp(90, 30, tx), lerp(70, 25, tx), lerp(50, 35, tx), 180);
    ellipse(x, shoreY, random(8, 20), random(4, 10));
  }
}

function drawPetals() {
  for (let i = 0; i < 120; i++) {
    let px = random(width);
    let py = random(1520, 1950);
    let sz = random(4, 14);
    let tx = px / width;

    push();
    translate(px, py);
    rotate(random(TWO_PI));

    // Petals: warm on left, pale on right
    let r = lerp(220, 180, tx) + random(-20, 20);
    let g = lerp(140, 160, tx) + random(-20, 20);
    let b = lerp(100, 170, tx) + random(-20, 20);
    let a = random(80, 180);

    fill(r, g, b, a);
    noStroke();
    ellipse(0, 0, sz, sz * 0.5);
    ellipse(0, 0, sz * 0.5, sz);
    pop();
  }
}

function drawTree() {
  let treeX = 800;
  let treeBaseY = 1500;

  // Roots going into water
  drawRoots(treeX, treeBaseY);

  // Main trunk
  drawBranch(treeX, treeBaseY, -HALF_PI, 220, 12, 0);
}

function drawRoots(x, y) {
  stroke(60, 40, 30);
  strokeWeight(1);
  for (let i = 0; i < 15; i++) {
    let angle = random(0, PI);
    let len = random(80, 250);
    let cx = x + random(-40, 40);
    let rootPts = [];
    let px = cx, py = y;
    rootPts.push({ x: px, y: py });
    let a = angle;
    for (let j = 0; j < 8; j++) {
      a += random(-0.3, 0.3);
      px += cos(a) * (len / 8);
      py += sin(a) * (len / 8);
      rootPts.push({ x: px, y: py });
    }

    noFill();
    let w = random(3, 12);
    for (let j = 0; j < rootPts.length - 1; j++) {
      let t = j / rootPts.length;
      strokeWeight(w * (1 - t));
      let tx = rootPts[j].x / width;
      let rr = lerp(80, 40, tx);
      let gg = lerp(55, 25, tx);
      let bb = lerp(35, 25, tx);
      stroke(rr, gg, bb, 200);
      line(rootPts[j].x, rootPts[j].y, rootPts[j + 1].x, rootPts[j + 1].y);
    }
  }
}

function drawBranch(x, y, angle, len, weight, depth) {
  if (depth > 10 || len < 8) {
    // Draw leaves or bare ends
    drawLeafCluster(x, y, x < 800);
    return;
  }

  let endX = x + cos(angle) * len;
  let endY = y + sin(angle) * len;

  // Color depends on side
  let isAlive = x < 800;

  for (let i = 0; i < 3; i++) {
    let offX = random(-2, 2);
    let offY = random(-2, 2);
    if (isAlive) {
      stroke(70 + depth * 5, 45 + depth * 3, 25 + depth * 2, 180);
    } else {
      stroke(50 + depth * 4, 40 + depth * 3, 35 + depth * 2, 160);
    }
    strokeWeight(weight - i * 0.5);
    noFill();

    // Slight curve
    let midX = (x + endX) / 2 + random(-10, 10);
    let midY = (y + endY) / 2 + random(-10, 10);
    beginShape();
    vertex(x + offX, y + offY);
    quadraticVertex(midX, midY, endX + offX, endY + offY);
    endShape();
  }

  // Bark texture
  if (weight > 5) {
    for (let t = 0; t < 1; t += 0.1) {
      let bx = lerp(x, endX, t) + random(-weight / 2, weight / 2);
      let by = lerp(y, endY, t) + random(-weight / 2, weight / 2);
      stroke(40, 25, 15, 60);
      strokeWeight(1);
      line(bx, by, bx + random(-3, 3), by + random(-3, 3));
    }
  }

  let branches = depth < 3 ? floor(random(2, 4)) : floor(random(1, 3));
  for (let i = 0; i < branches; i++) {
    let newAngle = angle + random(-0.7, 0.7);
    // Bias: left branches go left, right go right slightly
    if (depth > 1) {
      if (endX < 800) newAngle -= random(0, 0.15);
      else newAngle += random(0, 0.15);
    }
    let newLen = len * random(0.55, 0.78);
    let newWeight = weight * 0.68;
    drawBranch(endX, endY, newAngle, newLen, newWeight, depth + 1);
  }
}

function drawLeafCluster(x, y, alive) {
  if (alive) {
    // Lush green-gold leaves
    for (let i = 0; i < 8; i++) {
      let lx = x + random(-25, 25);
      let ly = y + random(-25, 25);
      let sz = random(5, 18);
      noStroke();
      let g = random(120, 200);
      let r = random(60, 140);
      fill(r, g, random(30, 70), random(100, 200));
      push();
      translate(lx, ly);
      rotate(random(TWO_PI));
      ellipse(0, 0, sz, sz * 0.4);
      pop();
    }
    // Some blossoms
    if (random() < 0.3) {
      for (let i = 0; i < 3; i++) {
        fill(255, random(150, 220), random(150, 200), random(100, 180));
        ellipse(x + random(-15, 15), y + random(-15, 15), random(4, 10), random(4, 10));
      }
    }
  } else {
    // Dead side: bare, maybe a few withered leaves
    if (random() < 0.15) {
      noStroke();
      fill(100, 70, 50, random(60, 120));
      push();
      translate(x + random(-10, 10), y + random(-10, 10));
      rotate(random(TWO_PI));
      ellipse(0, 0, random(4, 10), random(2, 5));
      pop();
    }
  }
}

function drawBirds() {
  // Birds ascending from the dead (right) side
  let birds = [];
  for (let i = 0; i < 18; i++) {
    birds.push({
      x: random(900, 1500),
      y: random(100, 900),
      sz: random(8, 25),
      angle: random(-0.3, 0.3)
    });
  }
  // Sort by y so higher birds are smaller (perspective)
  birds.sort((a, b) => a.y - b.y);

  for (let b of birds) {
    let t = b.y / 900;
    push();
    translate(b.x, b.y);
    rotate(b.angle);
    noFill();
    // Birds transition from dark to luminous as they rise
    let brightness = lerp(240, 80, t);
    let alpha = lerp(220, 100, t);
    stroke(brightness, brightness, brightness + 30, alpha);
    strokeWeight(lerp(1.5, 2.5, t));

    // Simple bird shape - two arcs
    let s = b.sz;
    beginShape();
    vertex(-s, s * 0.3);
    quadraticVertex(-s * 0.3, -s * 0.4, 0, 0);
    endShape();
    beginShape();
    vertex(0, 0);
    quadraticVertex(s * 0.3, -s * 0.4, s, s * 0.3);
    endShape();

    // Glow for higher birds
    if (b.y < 400) {
      noStroke();
      fill(220, 220, 255, 20);
      ellipse(0, 0, s * 3, s * 3);
    }
    pop();
  }
}

function drawMist() {
  noStroke();
  for (let i = 0; i < 80; i++) {
    let mx = random(width);
    let my = random(1200, 1600);
    let sz = random(100, 400);
    let tx = mx / width;
    let r = lerp(200, 80, tx);
    let g = lerp(180, 60, tx);
    let b = lerp(140, 100, tx);
    fill(r, g, b, random(5, 20));
    ellipse(mx, my, sz, sz * 0.3);
  }

  // Upper atmospheric haze
  for (let i = 0; i < 40; i++) {
    let mx = random(width);
    let my = random(0, 500);
    let sz = random(200, 600);
    let tx = mx / width;
    fill(lerp(255, 60, tx), lerp(220, 40, tx), lerp(160, 80, tx), random(3, 12));
    ellipse(mx, my, sz, sz * 0.4);
  }
}

function drawGrain() {
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let grain = random(-8, 8);
    pixels[i] += grain;
    pixels[i + 1] += grain;
    pixels[i + 2] += grain;
  }
  updatePixels();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Background gradient: dark earth at bottom to golden light at top
  for (let y = 0; y < height; y++) {
    let t = y / height; // 0 at top, 1 at bottom
    let r, g, b;
    if (t > 0.7) {
      // Bottom: deep dark reds and browns
      let bt = map(t, 0.7, 1, 0, 1);
      r = lerp(80, 25, bt);
      g = lerp(20, 8, bt);
      b = lerp(15, 5, bt);
    } else if (t > 0.35) {
      // Middle: transition zone, muted purples and ochres
      let mt = map(t, 0.35, 0.7, 0, 1);
      r = lerp(180, 80, mt);
      g = lerp(120, 20, mt);
      b = lerp(80, 15, mt);
    } else {
      // Top: golden light to near white
      let tt = map(t, 0, 0.35, 0, 1);
      r = lerp(255, 180, tt);
      g = lerp(245, 120, tt);
      b = lerp(220, 80, tt);
    }
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Atmospheric haze layers with noise
  for (let layer = 0; layer < 15; layer++) {
    for (let y = 0; y < height; y += 2) {
      for (let x = 0; x < width; x += 2) {
        let n = noise(x * 0.002 + layer * 10, y * 0.003 + layer * 5);
        if (n > 0.55) {
          let t = y / height;
          let alpha = map(n, 0.55, 1, 0, 8);
          if (t < 0.3) {
            fill(255, 240, 200, alpha);
          } else {
            fill(60, 10, 10, alpha);
          }
          noStroke();
          rect(x, y, 2, 2);
        }
      }
    }
  }

  // Central light beam / column of dissolution
  for (let i = 0; i < 80000; i++) {
    let cy = random(height);
    let t = cy / height; // 0=top, 1=bottom
    let spreadX = map(t, 0, 1, 400, 120);
    let cx = width / 2 + randomGaussian(0, spreadX);

    let n = noise(cx * 0.005, cy * 0.005, 0.5);
    let alpha;
    let r, g, b;

    if (t < 0.25) {
      // Top: bright golden-white light
      r = lerp(255, 255, n);
      g = lerp(250, 220, n);
      b = lerp(230, 160, n);
      alpha = map(t, 0, 0.25, 50, 25) * n;
    } else if (t < 0.55) {
      // Middle: amber dissolving
      r = lerp(240, 200, n);
      g = lerp(160, 80, n);
      b = lerp(60, 30, n);
      alpha = 20 * n;
    } else {
      // Lower: deep red embers
      r = lerp(160, 100, n);
      g = lerp(30, 10, n);
      b = lerp(10, 5, n);
      alpha = map(t, 0.55, 1, 20, 35) * n;
    }

    noStroke();
    fill(r, g, b, alpha);
    let sz = random(2, 8);
    ellipse(cx, cy, sz, sz);
  }

  // The dissolving figure — a human silhouette breaking apart into particles
  // Figure center around (800, 1200), standing/floating
  let figCenterX = 800;
  let figTopY = 700;
  let figBottomY = 1550;

  // Define body shape using ellipses along spine
  // We'll create a point cloud that forms a figure then dissolve upper parts
  let bodyPoints = [];

  // Head
  for (let i = 0; i < 3000; i++) {
    let a = random(TWO_PI);
    let headR = 75;
    let rx = headR * (0.85 + 0.15 * noise(a * 2, 1));
    let ry = headR * (1.0 + 0.1 * noise(a * 2, 2));
    let rr = random(1) < 0.8 ? random(0, 1) : random(0, 1);
    rr = pow(rr, 0.5);
    let px = figCenterX + cos(a) * rx * rr;
    let py = figTopY + 80 + sin(a) * ry * rr;
    bodyPoints.push({ x: px, y: py, part: 'head' });
  }

  // Neck
  for (let i = 0; i < 800; i++) {
    let px = figCenterX + randomGaussian(0, 22);
    let py = random(figTopY + 155, figTopY + 210);
    bodyPoints.push({ x: px, y: py, part: 'neck' });
  }

  // Torso
  for (let i = 0; i < 12000; i++) {
    let ty = random(figTopY + 210, figTopY + 550);
    let tNorm = map(ty, figTopY + 210, figTopY + 550, 0, 1);
    let torsoW = lerp(70, 100, sin(tNorm * PI)) + 20;
    let px = figCenterX + randomGaussian(0, torsoW * 0.4);
    bodyPoints.push({ x: px, y: ty, part: 'torso' });
  }

  // Shoulders and arms
  for (let side = -1; side <= 1; side += 2) {
    // Shoulder
    for (let i = 0; i < 2000; i++) {
      let sy = figTopY + 220 + randomGaussian(0, 25);
      let sx = figCenterX + side * (90 + randomGaussian(30, 20));
      bodyPoints.push({ x: sx, y: sy, part: 'arm' });
    }
    // Upper arm
    for (let i = 0; i < 2500; i++) {
      let t2 = random(0, 1);
      let ay = lerp(figTopY + 240, figTopY + 420, t2);
      let ax = figCenterX + side * (110 + t2 * 30 + randomGaussian(0, 15));
      bodyPoints.push({ x: ax, y: ay, part: 'arm' });
    }
    // Forearm hanging or slightly out
    for (let i = 0; i < 2000; i++) {
      let t2 = random(0, 1);
      let ay = lerp(figTopY + 420, figTopY + 580, t2);
      let ax = figCenterX + side * (140 + t2 * (-20) + randomGaussian(0, 12));
      bodyPoints.push({ x: ax, y: ay, part: 'arm' });
    }
  }

  // Hips and legs
  for (let side = -1; side <= 1; side += 2) {
    for (let i = 0; i < 5000; i++) {
      let t2 = random(0, 1);
      let ly = lerp(figTopY + 520, figBottomY, t2);
      let legSpread = lerp(25, 40, t2);
      let legW = lerp(35, 20, t2);
      let lx = figCenterX + side * legSpread + randomGaussian(0, legW * 0.4);
      bodyPoints.push({ x: lx, y: ly, part: 'leg' });
    }
  }

  // Now draw the figure: lower parts are solid/dark, upper parts dissolve into particles rising
  for (let i = 0; i < bodyPoints.length; i++) {
    let p = bodyPoints[i];
    let yNorm = map(p.y, figTopY, figBottomY, 0, 1); // 0=top of figure, 1=bottom

    // Dissolution: top of figure dissolves more
    // Particles at top drift upward and scatter
    let dissolve = map(yNorm, 0, 0.6, 1, 0);
    dissolve = constrain(dissolve, 0, 1);

    let drawX = p.x;
    let drawY = p.y;

    // Apply dissolution displacement
    if (dissolve > 0) {
      let nOff = noise(p.x * 0.01, p.y * 0.01, 3);
      drawX += (nOff - 0.5) * dissolve * 300;
      drawY -= dissolve * random(0, 350);
      // Some particles skip (fully dissolved)
      if (random(1) < dissolve * 0.5) continue;
    }

    // Color: bottom is dark flesh/earth, top becomes golden/luminous
    let r2, g2, b2, a2;
    if (yNorm > 0.6) {
      // Solid lower body — dark, earthy
      let shade = noise(p.x * 0.02, p.y * 0.02) * 0.4 + 0.3;
      r2 = lerp(40, 90, shade);
      g2 = lerp(15, 35, shade);
      b2 = lerp(10, 20, shade);
      a2 = lerp(220, 180, random(1));
    } else {
      // Dissolving upper body — transitioning to gold/light
      let shade = noise(p.x * 0.015, p.y * 0.015 + 10);
      r2 = lerp(90, 240, dissolve * shade + dissolve * 0.5);
      g2 = lerp(30, 180, dissolve * shade + dissolve * 0.3);
      b2 = lerp(15, 80, dissolve * shade);
      a2 = lerp(200, 40, dissolve);
    }

    noStroke();
    let sz2 = lerp(4, 2, dissolve) + random(-0.5, 0.5);
    if (dissolve > 0.3) sz2 = random(1.5, 4);
    fill(r2, g2, b2, a2);
    ellipse(drawX, drawY, sz2, sz2);
  }

  // Rising particles above the figure — souls/essence ascending
  for (let i = 0; i < 25000; i++) {
    let py = random(100, figTopY + 300);
    let t3 = map(py, figTopY + 300, 100, 0, 1); // 0 near figure, 1 at top
    let spread = lerp(100, 350, t3);
    let px = figCenterX + randomGaussian(0, spread);

    let n2 = noise(px * 0.008, py * 0.008, 7);
    px += (n2 - 0.5) * 150;

    let r3 = lerp(220, 255, t3);
    let g3 = lerp(140, 245, t3);
    let b3 = lerp(50, 210, t3);
    let a3 = lerp(50, 15, t3) * (n2 * 0.5 + 0.5);

    if (random(1) < 0.3) {
      // Brighter sparkle
      r3 = 255; g3 = lerp(230, 255, random(1)); b3 = lerp(180, 230, random(1));
      a3 = random(30, 80);
    }

    noStroke();
    fill(r3, g3, b3, a3);
    let sz3 = random(1, 5) * (1 - t3 * 0.5);
    ellipse(px, py, sz3, sz3);
  }

  // Ground / earth at bottom — dark textured
  for (let i = 0; i < 40000; i++) {
    let py = random(1500, 2000);
    let px = random(0, width);
    let tBottom = map(py, 1500, 2000, 0, 1);
    let n3 = noise(px * 0.005, py * 0.008, 20);

    let r4 = lerp(45, 15, tBottom) * (n3 * 0.5 + 0.5);
    let g4 = lerp(20, 5, tBottom) * (n3 * 0.5 + 0.5);
    let b4 = lerp(12, 3, tBottom) * (n3 * 0.5 + 0.5);
    let a4 = lerp(80, 160, tBottom);

    // Some reddish undertones
    if (n3 > 0.6) {
      r4 += 30;
      g4 += 5;
    }

    noStroke();
    fill(r4, g4, b4, a4);
    let sz4 = random(2, 7);
    ellipse(px, py, sz4, sz4);
  }

  // Subtle dark vignette
  for (let i = 0; i < 30; i++) {
    let alpha = map(i, 0, 30, 6, 0);
    noFill();
    stroke(0, 0, 0, alpha);
    strokeWeight(40);
    let inset = i * 40;
    rect(inset - 20, inset - 20, width - 2 * inset + 40, height - 2 * inset + 40, 10);
  }

  // Central glow at top
  for (let r = 500; r > 0; r -= 2) {
    let a5 = map(r, 500, 0, 0, 12);
    noStroke();
    fill(255, 245, 220, a5);
    ellipse(width / 2, 0, r * 2.5, r * 1.5);
  }

  // Floating embers / sparks near the dissolution zone
  for (let i = 0; i < 500; i++) {
    let px = figCenterX + randomGaussian(0, 200);
    let py = random(figTopY - 100, figTopY + 500);
    let n4 = noise(px * 0.02, py * 0.02, 50);
    if (n4 > 0.45) {
      let brightness = map(n4, 0.45, 1, 150, 255);
      fill(brightness, brightness * 0.6, brightness * 0.2, random(60, 180));
      noStroke();
      let sz5 = random(1.5, 4);
      ellipse(px, py, sz5, sz5);
    }
  }

  // Final soft overlay: a thin warm glaze over everything
  noStroke();
  fill(200, 150, 80, 8);
  rect(0, 0, width, height);
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Sky gradient - left golden, right purple
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let tx = x / width;
      let ty = y / height;

      // Left side: golden warm
      let lr = lerp(255, 180, ty);
      let lg = lerp(200, 100, ty);
      let lb = lerp(80, 60, ty);

      // Right side: deep purple/dark
      let rr = lerp(80, 20, ty);
      let rg = lerp(40, 10, ty);
      let rb = lerp(120, 60, ty);

      let r = lerp(lr, rr, tx);
      let g = lerp(lg, rg, tx);
      let b = lerp(lb, rb, tx);

      set(x, y, color(r, g, b));
    }
  }
  updatePixels();

  // Distant mountains
  drawMountains();

  // River at bottom
  drawRiver();

  // Tree
  drawTree(width / 2, height * 0.72, -PI / 2, 160, 12);

  // Roots going into river
  drawRoots(width / 2, height * 0.72);

  // Floating petals in river
  drawPetals();

  // Birds dissolving into stardust
  drawBirds();

  // Stars on the dark side
  drawStars();

  // Light rays on golden side
  drawLightRays();

  // Atmospheric haze
  drawHaze();
}

function drawMountains() {
  // Far mountains
  fill(60, 40, 80, 120);
  noStroke();
  beginShape();
  vertex(0, height * 0.55);
  for (let x = 0; x <= width; x += 10) {
    let y = height * 0.55 - noise(x * 0.003, 0) * 200 - noise(x * 0.001) * 100;
    vertex(x, y);
  }
  vertex(width, height * 0.55);
  endShape(CLOSE);

  // Near mountains
  fill(40, 30, 50, 150);
  beginShape();
  vertex(0, height * 0.6);
  for (let x = 0; x <= width; x += 10) {
    let y = height * 0.6 - noise(x * 0.004, 5) * 150 - noise(x * 0.0015, 3) * 80;
    vertex(x, y);
  }
  vertex(width, height * 0.6);
  endShape(CLOSE);
}

function drawRiver() {
  for (let y = height * 0.72; y < height; y++) {
    for (let x = 0; x < width; x += 2) {
      let ty = map(y, height * 0.72, height, 0, 1);
      let tx = x / width;
      let n = noise(x * 0.005, y * 0.008) * 40;

      let r = lerp(20, 10, ty) + n * 0.3;
      let g = lerp(30, 15, ty) + n * 0.2;
      let b = lerp(60, 30, ty) + n;

      // Reflection of golden side
      let golden = (1 - tx) * 0.3;
      r += golden * 60;
      g += golden * 40;

      // Slight purple reflection on right
      b += tx * 20;

      noStroke();
      fill(r, g, b, 220);
      rect(x, y, 2, 1);
    }
  }

  // Water ripples
  stroke(255, 255, 255, 20);
  strokeWeight(1);
  for (let i = 0; i < 200; i++) {
    let rx = random(width);
    let ry = random(height * 0.74, height);
    let rw = random(20, 80);
    noFill();
    arc(rx, ry, rw, random(3, 8), 0, PI);
  }
}

function drawTree(x, y, angle, len, depth) {
  if (depth <= 0 || len < 4) return;

  let endX = x + cos(angle) * len;
  let endY = y + sin(angle) * len;

  let isLeftSide = x < width / 2;
  let sideFactor = map(x, 0, width, 1, 0);

  let sw = map(depth, 0, 12, 1, 28);
  strokeWeight(sw);

  // Living side (left): brown-green; Dead side (right): grey-white
  if (isLeftSide) {
    let r = lerp(80, 60, sideFactor);
    let g = lerp(50, 40, sideFactor);
    let b = lerp(30, 20, sideFactor);
    stroke(r, g, b);
  } else {
    let grey = lerp(100, 160, 1 - sideFactor);
    stroke(grey, grey - 10, grey - 5);
  }

  // Add slight curve with noise
  let midX = (x + endX) / 2 + noise(x * 0.01, y * 0.01) * 15 - 7;
  let midY = (y + endY) / 2 + noise(y * 0.01, x * 0.01) * 15 - 7;

  noFill();
  beginShape();
  vertex(x, y);
  quadraticVertex(midX, midY, endX, endY);
  endShape();

  // Leaves on living side, bare on dead side
  if (depth <= 3 && isLeftSide && endX < width * 0.55) {
    drawLeafCluster(endX, endY, len * 0.6);
  }

  // Dead branch details on right side
  if (depth <= 3 && !isLeftSide && endX > width * 0.5) {
    // small broken twigs
    stroke(140, 130, 125, 150);
    strokeWeight(1);
    for (let t = 0; t < 3; t++) {
      let ta = angle + random(-0.8, 0.8);
      let tl = random(5, 15);
      line(endX, endY, endX + cos(ta) * tl, endY + sin(ta) * tl);
    }
  }

  if (depth > 1) {
    let branches = depth > 6 ? 2 : floor(random(2, 4));
    for (let i = 0; i < branches; i++) {
      let newAngle = angle + random(-0.7, 0.7);
      // Bias branches to spread
      if (i === 0) newAngle = angle - random(0.2, 0.6);
      if (i === 1) newAngle = angle + random(0.2, 0.6);

      let newLen = len * random(0.6, 0.78);
      drawTree(endX, endY, newAngle, newLen, depth - 1);
    }
  }
}

function drawLeafCluster(x, y, size) {
  noStroke();
  for (let i = 0; i < 25; i++) {
    let lx = x + random(-size, size);
    let ly = y + random(-size, size);
    let ls = random(4, 12);

    // Various greens and some autumn gold
    let palette = random();
    if (palette < 0.5) {
      fill(30 + random(40), 100 + random(80), 20 + random(30), 180);
    } else if (palette < 0.8) {
      fill(100 + random(50), 120 + random(60), 10 + random(20), 160);
    } else {
      fill(180 + random(50), 140 + random(40), 20, 150);
    }

    ellipse(lx, ly, ls, ls * 0.7);
  }
}

function drawRoots(x, y) {
  let rootCount = 8;
  for (let i = 0; i < rootCount; i++) {
    let angle = PI / 2 + map(i, 0, rootCount - 1, -0.8, 0.8);
    let len = random(80, 200);

    stroke(60, 40, 30, 200);
    strokeWeight(map(i, 0, rootCount, 8, 3));
    noFill();

    let cx = x;
    let cy = y;
    beginShape();
    vertex(cx, cy);
    for (let s = 0; s < 5; s++) {
      cx += cos(angle) * len / 5 + random(-10, 10);
      cy += sin(angle) * len / 5 + random(-5, 5);
      vertex(cx, cy);
    }
    endShape();

    // Sub-roots
    stroke(50, 35, 25, 150);
    strokeWeight(2);
    for (let s = 0; s < 3; s++) {
      let sx = x + cos(angle) * len * random(0.3, 0.8) + random(-20, 20);
      let sy = y + sin(angle) * len * random(0.3, 0.8);
      let sa = angle + random(-0.5, 0.5);
      let sl = random(20, 50);
      line(sx, sy, sx + cos(sa) * sl, sy + sin(sa) * sl);
    }
  }
}

function drawPetals() {
  noStroke();
  for (let i = 0; i < 150; i++) {
    let px = random(width);
    let py = random(height * 0.73, height * 0.95);
    let ps = random(4, 14);

    // Faded flower petals: pink, white, pale rose
    let palette = random();
    if (palette < 0.4) {
      fill(220, 150, 160, random(80, 180));
    } else if (palette < 0.7) {
      fill(240, 200, 200, random(60, 150));
    } else {
      fill(255, 220, 180, random(60, 140));
    }

    push();
    translate(px, py);
    rotate(random(TWO_PI));
    ellipse(0, 0, ps, ps * 0.5);
    // second petal
    rotate(PI / 3);
    ellipse(0, 0, ps * 0.8, ps * 0.4);
    pop();
  }
}

function drawBirds() {
  // Birds from dead side dissolving into particles
  for (let i = 0; i < 18; i++) {
    let bx = random(width * 0.45, width * 0.95);
    let by = random(height * 0.05, height * 0.45);

    let dissolution = map(by, height * 0.05, height * 0.45, 1, 0);
    dissolution = constrain(dissolution + map(bx, width * 0.5, width, 0, 0.5), 0, 1);

    if (dissolution < 0.5) {
      // More intact bird
      stroke(30, 20, 40, map(dissolution, 0, 0.5, 220, 100));
      strokeWeight(2);
      noFill();
      // Bird shape - simple V
      let bs = random(10, 25);
      beginShape();
      vertex(bx - bs, by + random(-3, 3));
      vertex(bx, by);
      vertex(bx + bs, by + random(-3, 3));
      endShape();
    }

    // Dissolving particles
    if (dissolution > 0.2) {
      let particleCount = floor(dissolution * 30);
      for (let p = 0; p < particleCount; p++) {
        let spread = dissolution * 40;
        let ppx = bx + random(-spread, spread);
        let ppy = by + random(-spread, spread);
        let ps = random(1, 4) * (1 - dissolution * 0.5);

        // Stardust colors
        let starColor = random();
        if (starColor < 0.5) {
          fill(255, 255, 220, random(50, 200) * dissolution);
        } else if (starColor < 0.8) {
          fill(200, 180, 255, random(50, 180) * dissolution);
        } else {
          fill(255, 200, 150, random(50, 160) * dissolution);
        }
        noStroke();
        ellipse(ppx, ppy, ps);
      }
    }
  }
}

function drawStars() {
  // Stars on the darker right side and upper area
  for (let i = 0; i < 400; i++) {
    let sx = random(width * 0.3, width);
    let sy = random(0, height * 0.6);

    let darkness = map(sx, width * 0.3, width, 0, 1) * map(sy, height * 0.6, 0, 0, 1);

    if (random() < darkness) {
      let ss = random(1, 3.5);
      let alpha = random(80, 255) * darkness;

      let starType = random();
      if (starType < 0.7) {
        fill(255, 255, 240, alpha);
      } else if (starType < 0.9) {
        fill(200, 200, 255, alpha);
      } else {
        fill(255, 220, 180, alpha);
      }
      noStroke();
      ellipse(sx, sy, ss);

      // Glow
      if (ss > 2.5) {
        fill(255, 255, 255, alpha * 0.2);
        ellipse(sx, sy, ss * 3);
      }
    }
  }
}

function drawLightRays() {
  // Golden light rays from upper left
  for (let i = 0; i < 12; i++) {
    let angle = random(0.3, 1.2);
    let startX = random(-100, width * 0.3);
    let startY = random(-100, height * 0.1);

    let rayLen = random(600, 1200);
    let rayWidth = random(30, 100);

    let endX = startX + cos(angle) * rayLen;
    let endY = startY + sin(angle) * rayLen;

    for (let w = rayWidth; w > 0; w -= 2) {
      let alpha = map(w, 0, rayWidth, 15, 2);
      stroke(255, 220, 120, alpha);
      strokeWeight(w);
      line(startX, startY, endX, endY);
    }
  }
}

function drawHaze() {
  // Atmospheric haze/mist near the ground and around the tree
  noStroke();
  for (let i = 0; i < 300; i++) {
    let hx = random(width);
    let hy = random(height * 0.6, height * 0.78);
    let hs = random(50, 200);

    let tx = hx / width;
    // Golden haze on left, purple on right
    let r = lerp(200, 80, tx);
    let g = lerp(170, 50, tx);
    let b = lerp(100, 100, tx);

    fill(r, g, b, random(5, 20));
    ellipse(hx, hy, hs, hs * 0.4);
  }

  // Additional texture - bark detail on main trunk
  drawBarkTexture();

  // Vignette
  drawVignette();
}

function drawBarkTexture() {
  let trunkX = width / 2;
  let trunkTop = height * 0.72 - 160;
  let trunkBot = height * 0.72;

  stroke(0, 0, 0, 30);
  strokeWeight(1);
  for (let i = 0; i < 100; i++) {
    let bx = trunkX + random(-14, 14);
    let by = random(trunkTop + 20, trunkBot);
    let bl = random(10, 30);
    line(bx, by, bx + random(-3, 3), by + bl);
  }
}

function drawVignette() {
  // Dark vignette around edges
  for (let i = 0; i < 80; i++) {
    let alpha = map(i, 0, 80, 40, 0);
    noFill();
    stroke(0, 0, 0, alpha);
    strokeWeight(10);
    rect(i * 3, i * 3, width - i * 6, height - i * 6, 20);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Sky gradient - deep twilight
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r, g, b;
    if (t < 0.4) {
      r = lerp(10, 45, t / 0.4);
      g = lerp(5, 20, t / 0.4);
      b = lerp(30, 60, t / 0.4);
    } else if (t < 0.55) {
      let tt = (t - 0.4) / 0.15;
      r = lerp(45, 120, tt);
      g = lerp(20, 50, tt);
      b = lerp(60, 70, tt);
    } else {
      let tt = (t - 0.55) / 0.45;
      r = lerp(120, 20, tt);
      g = lerp(50, 12, tt);
      b = lerp(70, 25, tt);
    }
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Distant misty hills
  noStroke();
  for (let layer = 0; layer < 4; layer++) {
    let baseY = 900 + layer * 80;
    let alpha = 30 + layer * 15;
    let col = color(30 - layer * 5, 15 - layer * 2, 40 - layer * 5, alpha);
    fill(col);
    beginShape();
    vertex(0, height);
    for (let x = 0; x <= width; x += 5) {
      let n = noise(x * 0.002 + layer * 100, layer * 50);
      let y = baseY + n * 200 - 100;
      vertex(x, y);
    }
    vertex(width, height);
    endShape(CLOSE);
  }

  // Ground - dark earth
  for (let y = 1200; y < height; y++) {
    for (let x = 0; x < width; x += 3) {
      let n = noise(x * 0.01, y * 0.01);
      let n2 = noise(x * 0.05, y * 0.05);
      let depth = map(y, 1200, height, 0, 1);
      let r = lerp(35, 15, depth) + n2 * 15;
      let g = lerp(20, 8, depth) + n2 * 8;
      let b = lerp(30, 12, depth) + n2 * 10;
      fill(r, g, b, 200);
      noStroke();
      rect(x, y, 3, 1);
    }
  }

  // Sleeping figures in the earth (subtle forms)
  drawSleepingFigures();

  // Moon / dim light source
  drawMoon(1150, 250, 120);

  // Stars
  for (let i = 0; i < 300; i++) {
    let sx = random(width);
    let sy = random(700);
    let sz = random(1, 3);
    let bright = random(100, 220);
    fill(bright, bright, bright + 30, random(100, 200));
    noStroke();
    ellipse(sx, sy, sz, sz);
  }

  // The great dead tree
  drawTree(800, 1200);

  // Falling golden petals
  drawFallingPetals();

  // Glowing flowers at the base
  drawGlowingFlowers();

  // Atmospheric fog
  for (let y = 900; y < 1400; y++) {
    let fogAlpha = sin(map(y, 900, 1400, 0, PI)) * 15;
    for (let x = 0; x < width; x += 10) {
      let n = noise(x * 0.005, y * 0.008);
      if (n > 0.45) {
        fill(60, 50, 70, fogAlpha * n);
        noStroke();
        rect(x, y, 10, 1);
      }
    }
  }

  // Vignette
  drawVignette();
}

function drawMoon(mx, my, mr) {
  // Glow
  for (let r = mr * 4; r > 0; r -= 2) {
    let a = map(r, 0, mr * 4, 40, 0);
    fill(200, 180, 150, a);
    noStroke();
    ellipse(mx, my, r * 2, r * 2);
  }
  // Moon body
  fill(220, 210, 190, 180);
  ellipse(mx, my, mr * 2, mr * 2);
  // Slight crescent shadow
  fill(10, 5, 30, 150);
  ellipse(mx + 40, my - 10, mr * 1.8, mr * 1.9);
}

function drawTree(tx, ty) {
  // Main trunk
  let branches = [];
  drawBranch(tx, ty, -PI / 2, 180, 45, 0, 8, branches);

  // Roots going into earth
  for (let i = 0; i < 7; i++) {
    let angle = PI / 2 + random(-0.8, 0.8);
    drawRoot(tx + random(-30, 30), ty, angle, 100 + random(80), 20 + random(15), 0, 5);
  }

  // Bark texture on trunk
  for (let i = 0; i < 500; i++) {
    let bx = tx + random(-50, 50);
    let by = ty - random(0, 400);
    let n = noise(bx * 0.1, by * 0.05);
    if (abs(bx - tx) < 30 + n * 20) {
      stroke(25 + n * 20, 15 + n * 10, 10 + n * 10, 80);
      strokeWeight(1);
      line(bx, by, bx + random(-3, 3), by + random(2, 8));
    }
  }
}

function drawBranch(x, y, angle, len, thickness, depth, maxDepth, branches) {
  if (depth > maxDepth || len < 8) return;

  let endX = x + cos(angle) * len;
  let endY = y + sin(angle) * len;

  // Draw branch with dark color
  let darkFactor = map(depth, 0, maxDepth, 0, 1);
  let r = lerp(20, 35, darkFactor);
  let g = lerp(12, 22, darkFactor);
  let b = lerp(10, 18, darkFactor);

  stroke(r, g, b);
  strokeWeight(thickness);
  noFill();

  // Slightly curved branch
  let midX = (x + endX) / 2 + random(-15, 15);
  let midY = (y + endY) / 2 + random(-10, 10);

  beginShape();
  vertex(x, y);
  quadraticVertex(midX, midY, endX, endY);
  endShape();

  branches.push({ x: endX, y: endY, depth: depth });

  // Branch splits
  let numChildren = depth < 3 ? floor(random(2, 4)) : floor(random(1, 3));
  for (let i = 0; i < numChildren; i++) {
    let newAngle = angle + random(-0.7, 0.7);
    let newLen = len * random(0.55, 0.75);
    let newThick = thickness * random(0.5, 0.7);
    drawBranch(endX, endY, newAngle, newLen, max(newThick, 1), depth + 1, maxDepth, branches);
  }

  // Small twigs at higher depths
  if (depth > 4) {
    for (let i = 0; i < 3; i++) {
      let twigAngle = angle + random(-1.2, 1.2);
      let twigLen = random(8, 25);
      let tx2 = endX + cos(twigAngle) * twigLen;
      let ty2 = endY + sin(twigAngle) * twigLen;
      stroke(30, 20, 18, 150);
      strokeWeight(max(thickness * 0.3, 0.5));
      line(endX, endY, tx2, ty2);
    }
  }
}

function drawRoot(x, y, angle, len, thickness, depth, maxDepth) {
  if (depth > maxDepth || len < 5) return;

  let endX = x + cos(angle) * len;
  let endY = y + sin(angle) * len;

  stroke(18, 10, 8, map(depth, 0, maxDepth, 255, 100));
  strokeWeight(thickness);

  let midX = (x + endX) / 2 + random(-20, 20);
  let midY = (y + endY) / 2 + random(-5, 10);

  noFill();
  beginShape();
  vertex(x, y);
  quadraticVertex(midX, midY, endX, endY);
  endShape();

  let numChildren = floor(random(1, 3));
  for (let i = 0; i < numChildren; i++) {
    let newAngle = angle + random(-0.5, 0.5);
    let newLen = len * random(0.5, 0.7);
    let newThick = thickness * random(0.4, 0.65);
    drawRoot(endX, endY, newAngle, newLen, max(newThick, 0.5), depth + 1, maxDepth);
  }
}

function drawSleepingFigures() {
  // Abstract curled forms suggesting sleeping bodies in the earth
  let figures = [
    { x: 350, y: 1600 },
    { x: 1050, y: 1700 },
    { x: 600, y: 1850 },
    { x: 1250, y: 1550 },
  ];

  for (let fig of figures) {
    push();
    translate(fig.x, fig.y);
    rotate(random(-0.3, 0.3));
    noFill();

    // Subtle curled form
    for (let j = 0; j < 8; j++) {
      stroke(40 + random(10), 25 + random(10), 20 + random(10), 25 + random(20));
      strokeWeight(random(1, 4));
      beginShape();
      for (let t = 0; t < TWO_PI; t += 0.1) {
        let r1 = 40 + 20 * sin(t * 2) + random(-3, 3);
        let r2 = 25 + 10 * cos(t * 3) + random(-3, 3);
        let px = r1 * cos(t) + random(-2, 2);
        let py = r2 * sin(t) + random(-2, 2);
        curveVertex(px, py);
      }
      endShape();
    }
    pop();
  }
}

function drawFallingPetals() {
  // Golden petals falling from branches
  for (let i = 0; i < 250; i++) {
    let px = random(300, 1300);
    let startY = random(200, 600);

    // Petals drift down in a path
    let py = lerp(startY, 1200 + random(-100, 50), random(0.3, 1.0));
    px += sin(py * 0.02 + i) * 60;

    let size = random(4, 12);
    let golden = random(0.5, 1.0);

    // Glow
    let glowR = lerp(200, 255, golden);
    let glowG = lerp(150, 200, golden);
    let glowB = lerp(50, 80, golden);

    for (let g = size * 3; g > 0; g -= 2) {
      fill(glowR, glowG, glowB, map(g, 0, size * 3, 30, 0));
      noStroke();
      ellipse(px, py, g, g);
    }

    // Petal shape
    push();
    translate(px, py);
    rotate(random(TWO_PI));
    fill(glowR, glowG, glowB, 200);
    noStroke();
    beginShape();
    vertex(0, -size / 2);
    bezierVertex(size / 2, -size / 3, size / 2, size / 3, 0, size / 2);
    bezierVertex(-size / 2, size / 3, -size / 2, -size / 3, 0, -size / 2);
    endShape(CLOSE);
    pop();
  }
}

function drawGlowingFlowers() {
  // Flowers at the base of the tree where petals have landed
  for (let i = 0; i < 80; i++) {
    let fx = 800 + random(-500, 500);
    let fy = 1180 + random(20, 200);

    // More flowers closer to tree
    let distFromTree = abs(fx - 800);
    if (random(1) > map(distFromTree, 0, 500, 0.9, 0.2)) continue;

    let flowerSize = random(6, 18);
    let hueShift = random(1);

    let fr, fg, fb;
    if (hueShift < 0.4) {
      // Golden
      fr = 255; fg = 200 + random(40); fb = 50 + random(40);
    } else if (hueShift < 0.7) {
      // Warm white
      fr = 240; fg = 230; fb = 200;
    } else {
      // Soft amber
      fr = 230; fg = 160 + random(40); fb = 60 + random(30);
    }

    // Glow on ground
    for (let g = flowerSize * 5; g > 0; g -= 3) {
      fill(fr, fg, fb, map(g, 0, flowerSize * 5, 15, 0));
      noStroke();
      ellipse(fx, fy, g, g * 0.6);
    }

    // Stem
    stroke(40, 70, 30, 150);
    strokeWeight(1.5);
    let stemH = random(15, 40);
    noFill();
    beginShape();
    vertex(fx, fy);
    quadraticVertex(fx + random(-8, 8), fy - stemH / 2, fx + random(-3, 3), fy - stemH);
    endShape();

    let flowerCX = fx + random(-3, 3);
    let flowerCY = fy - stemH;

    // Petals
    push();
    translate(flowerCX, flowerCY);
    let numPetals = floor(random(5, 8));
    for (let p = 0; p < numPetals; p++) {
      let pAngle = (TWO_PI / numPetals) * p + random(-0.1, 0.1);
      push();
      rotate(pAngle);
      fill(fr, fg, fb, 180);
      noStroke();
      ellipse(0, -flowerSize * 0.4, flowerSize * 0.4, flowerSize * 0.7);
      pop();
    }
    // Center
    fill(fr + 20, fg + 10, fb, 220);
    noStroke();
    ellipse(0, 0, flowerSize * 0.3, flowerSize * 0.3);
    pop();

    // Light emanating from flower
    fill(fr, fg, fb, 8);
    noStroke();
    ellipse(flowerCX, flowerCY, flowerSize * 8, flowerSize * 8);
  }

  // Extra scattered tiny light flowers further out
  for (let i = 0; i < 50; i++) {
    let fx = random(100, 1500);
    let fy = random(1250, 1500);
    let s = random(2, 6);
    let bright = random(0.5, 1);
    fill(255 * bright, 200 * bright, 60 * bright, 100);
    noStroke();
    ellipse(fx, fy, s, s);
    fill(255 * bright, 200 * bright, 60 * bright, 15);
    ellipse(fx, fy, s * 6, s * 6);
  }
}

function drawVignette() {
  // Dark edges
  let maxDist = dist(0, 0, width / 2, height / 2);
  for (let r = maxDist; r > maxDist * 0.4; r -= 3) {
    let a = map(r, maxDist * 0.4, maxDist, 0, 120);
    noFill();
    stroke(5, 2, 15, a);
    strokeWeight(6);
    ellipse(width / 2, height / 2, r * 2, r * 2 * (height / width));
  }

  // Top and bottom extra darkness
  for (let y = 0; y < 150; y++) {
    let a = map(y, 0, 150, 120, 0);
    stroke(5, 2, 15, a);
    strokeWeight(1);
    line(0, y, width, y);
  }
  for (let y = height; y > height - 100; y--) {
    let a = map(y, height, height - 100, 100, 0);
    stroke(5, 2, 10, a);
    strokeWeight(1);
    line(0, y, width, y);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep earth background
  background(15, 10, 8);

  // Painterly layering approach
  // Layer 1: Deep earth tones
  drawEarthLayers();
  // Layer 2: The dissolving figure
  drawDissolvingFigure();
  // Layer 3: Roots descending
  drawRoots();
  // Layer 4: Flowers ascending
  drawFlowers();
  // Layer 5: Atmospheric glazing
  drawGlazing();
  // Layer 6: Final details - petals, spores, light
  drawDetails();
}

function drawEarthLayers() {
  // Rich soil layers with horizontal brushstrokes
  for (let i = 0; i < 8000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.002, y * 0.002);
    let yNorm = y / height;

    // Color gradient: dark sky top -> earth middle -> deep earth bottom
    let r, g, b, a;
    if (yNorm < 0.15) {
      // Night sky
      r = lerp(8, 20, n);
      g = lerp(5, 15, n);
      b = lerp(25, 45, n);
      a = random(30, 80);
    } else if (yNorm < 0.4) {
      // Surface transition
      r = lerp(25, 55, n);
      g = lerp(20, 40, n);
      b = lerp(15, 30, n);
      a = random(20, 60);
    } else {
      // Deep earth
      r = lerp(30, 65, n);
      g = lerp(18, 35, n);
      b = lerp(10, 22, n);
      a = random(25, 70);
    }

    noStroke();
    fill(r, g, b, a);
    let bw = random(10, 80);
    let bh = random(3, 12);
    ellipse(x, y, bw, bh);
  }
}

function drawDissolvingFigure() {
  // A reclining figure dissolving into earth, centered around y=700-1200
  let figCenterX = 800;
  let figCenterY = 850;

  // Body outline defined by organic noise shape
  for (let i = 0; i < 25000; i++) {
    let angle = random(TWO_PI);
    let r = random(1);
    // Elongated horizontal body shape
    let bx = figCenterX + cos(angle) * r * 450 + noise(i * 0.01) * 80;
    let by = figCenterY + sin(angle) * r * 180 + noise(i * 0.01 + 100) * 60;

    // Head region (left side)
    let headDist = dist(bx, by, figCenterX - 350, figCenterY - 60);
    let inHead = headDist < 120;

    // Torso
    let torsoDist = dist(bx, by, figCenterX, figCenterY);
    let inTorso = (abs(bx - figCenterX) < 280 && abs(by - figCenterY) < 150);

    // Legs (right side, spreading)
    let legZone = bx > figCenterX + 100 && abs(by - figCenterY) < 180;

    let inBody = inHead || inTorso || legZone;
    if (!inBody) continue;

    // Dissolution factor: more dissolved at extremities and bottom
    let dissolveFactor = noise(bx * 0.005, by * 0.005) * 0.6 +
      (by - (figCenterY - 180)) / 400 * 0.4;
    dissolveFactor = constrain(dissolveFactor, 0, 1);

    // Colors: warm flesh -> purple decomposition -> earth
    let fleshR, fleshG, fleshB;
    if (dissolveFactor < 0.4) {
      // Warm flesh / ochre
      let t = dissolveFactor / 0.4;
      fleshR = lerp(180, 120, t);
      fleshG = lerp(130, 70, t);
      fleshB = lerp(90, 80, t);
    } else if (dissolveFactor < 0.7) {
      // Purple decomposition
      let t = (dissolveFactor - 0.4) / 0.3;
      fleshR = lerp(120, 80, t);
      fleshG = lerp(70, 35, t);
      fleshB = lerp(80, 90, t);
    } else {
      // Earth
      let t = (dissolveFactor - 0.7) / 0.3;
      fleshR = lerp(80, 50, t);
      fleshG = lerp(35, 30, t);
      fleshB = lerp(90, 20, t);
    }

    let nv = noise(bx * 0.01, by * 0.01, 3);
    fleshR += (nv - 0.5) * 40;
    fleshG += (nv - 0.5) * 30;
    fleshB += (nv - 0.5) * 20;

    let alph = lerp(140, 30, dissolveFactor) + random(-20, 20);
    fill(fleshR, fleshG, fleshB, alph);
    noStroke();
    let sz = random(3, 14) * lerp(1, 2.5, dissolveFactor);
    ellipse(bx + random(-3, 3), by + random(-3, 3), sz, sz * random(0.5, 1.5));
  }

  // Ribcage / bone hints showing through
  for (let rib = 0; rib < 7; rib++) {
    let ry = figCenterY - 60 + rib * 30;
    let rxStart = figCenterX - 100;
    for (let j = 0; j < 80; j++) {
      let t = j / 80;
      let rx = rxStart + t * 200;
      let ribY = ry + sin(t * PI) * (-20 - rib * 3);
      let n = noise(rx * 0.02, ry * 0.02);
      if (n > 0.35) {
        fill(200, 190, 170, random(10, 50));
        noStroke();
        ellipse(rx + random(-2, 2), ribY + random(-2, 2), random(2, 6), random(1, 3));
      }
    }
  }
}

function drawRoots() {
  // Roots growing downward from and through the figure
  let rootOrigins = [];
  for (let i = 0; i < 35; i++) {
    rootOrigins.push({
      x: random(400, 1200),
      y: random(750, 1000)
    });
  }

  for (let ro of rootOrigins) {
    drawSingleRoot(ro.x, ro.y, random(300, 800), random(-PI * 0.3, PI * 0.3) + HALF_PI, random(3, 8), 0);
  }
}

function drawSingleRoot(startX, startY, len, angle, thickness, depth) {
  if (depth > 5 || thickness < 0.5 || len < 10) return;

  let segments = floor(len / 5);
  let cx = startX;
  let cy = startY;
  let curAngle = angle;

  for (let i = 0; i < segments; i++) {
    let t = i / segments;
    curAngle += (noise(cx * 0.01, cy * 0.01, depth) - 0.5) * 0.3;
    let nx = cx + cos(curAngle) * 5;
    let ny = cy + sin(curAngle) * 5;

    let th = thickness * (1 - t * 0.7);
    let darkFactor = noise(cx * 0.005, cy * 0.005);
    let rr = lerp(60, 35, darkFactor);
    let rg = lerp(45, 20, darkFactor);
    let rb = lerp(25, 10, darkFactor);

    stroke(rr, rg, rb, lerp(120, 40, t));
    strokeWeight(th);
    line(cx, cy, nx, ny);

    // Branching
    if (random() < 0.015 && t > 0.2) {
      let branchAngle = curAngle + random(-0.8, 0.8);
      drawSingleRoot(cx, cy, len * random(0.2, 0.5), branchAngle, th * 0.6, depth + 1);
    }

    cx = nx;
    cy = ny;
  }

  // Fine root hairs at the end
  for (let h = 0; h < 5; h++) {
    let ha = curAngle + random(-1, 1);
    let hl = random(5, 20);
    stroke(50, 30, 15, 40);
    strokeWeight(0.5);
    line(cx, cy, cx + cos(ha) * hl, cy + sin(ha) * hl);
  }
}

function drawFlowers() {
  // Flowers growing upward from the figure into the dark sky
  let flowerStems = [];
  for (let i = 0; i < 18; i++) {
    flowerStems.push({
      baseX: random(350, 1250),
      baseY: random(680, 820),
      height: random(200, 650),
      type: floor(random(3))
    });
  }

  noStroke();
  for (let fs of flowerStems) {
    // Draw stem
    let stemPts = [];
    let sx = fs.baseX;
    let sy = fs.baseY;
    let stemSegments = floor(fs.height / 4);

    for (let i = 0; i <= stemSegments; i++) {
      let t = i / stemSegments;
      sx += (noise(fs.baseX * 0.01 + i * 0.05) - 0.5) * 6;
      sy = fs.baseY - t * fs.height;
      stemPts.push({ x: sx, y: sy });

      // Stem painting
      let stemThick = lerp(5, 1.5, t);
      let gn = noise(sx * 0.01, sy * 0.01);
      let sr = lerp(25, 50, gn);
      let sg = lerp(50, 90, gn);
      let sb = lerp(20, 40, gn);
      fill(sr, sg, sb, lerp(160, 80, t));
      ellipse(sx + random(-1, 1), sy, stemThick, random(3, 6));

      // Small leaves along stem
      if (random() < 0.04 && t > 0.1 && t < 0.8) {
        drawLeaf(sx, sy, random(15, 35), random() > 0.5 ? 1 : -1);
      }
    }

    // Draw flower head at top
    let topPt = stemPts[stemPts.length - 1];
    if (fs.type === 0) {
      drawPoppy(topPt.x, topPt.y);
    } else if (fs.type === 1) {
      drawWildflower(topPt.x, topPt.y);
    } else {
      drawSeedHead(topPt.x, topPt.y);
    }
  }

  // Small ground flowers near the body
  for (let i = 0; i < 40; i++) {
    let gx = random(300, 1300);
    let gy = random(650, 780);
    drawTinyFlower(gx, gy);
  }
}

function drawLeaf(x, y, size, dir) {
  noStroke();
  for (let i = 0; i < 20; i++) {
    let t = random();
    let lx = x + t * size * dir;
    let ly = y + sin(t * PI) * size * 0.3 * (random() > 0.5 ? 1 : -1);
    let gn = noise(lx * 0.05, ly * 0.05);
    fill(lerp(30, 70, gn), lerp(60, 110, gn), lerp(20, 50, gn), random(60, 120));
    ellipse(lx, ly, random(3, 8), random(2, 5));
  }
}

function drawPoppy(x, y) {
  // Deep red poppy - symbol of death and remembrance
  let petalCount = floor(random(5, 8));
  for (let p = 0; p < petalCount; p++) {
    let pa = (p / petalCount) * TWO_PI + random(-0.2, 0.2);
    let pDist = random(15, 40);
    let px = x + cos(pa) * pDist;
    let py = y + sin(pa) * pDist;

    for (let d = 0; d < 60; d++) {
      let dx = px + random(-20, 20);
      let dy = py + random(-15, 15);
      let dd = dist(dx, dy, px, py);
      if (dd < 18) {
        let nv = noise(dx * 0.05, dy * 0.05);
        let pr = lerp(160, 220, nv);
        let pg = lerp(10, 40, nv);
        let pb = lerp(15, 35, nv);
        fill(pr, pg, pb, random(80, 180));
        ellipse(dx, dy, random(3, 10), random(3, 8));
      }
    }
  }

  // Dark center
  for (let c = 0; c < 30; c++) {
    fill(15, 5, 10, random(100, 200));
    ellipse(x + random(-8, 8), y + random(-8, 8), random(2, 6), random(2, 6));
  }
}

function drawWildflower(x, y) {
  // Purple/violet wildflower
  let petals = floor(random(8, 15));
  for (let p = 0; p < petals; p++) {
    let pa = (p / petals) * TWO_PI + random(-0.3, 0.3);
    let pDist = random(5, 25);

    for (let d = 0; d < 30; d++) {
      let along = random(0.2, 1);
      let spread = random(-8, 8) * along;
      let dx = x + cos(pa) * pDist * along + cos(pa + HALF_PI) * spread;
      let dy = y + sin(pa) * pDist * along + sin(pa + HALF_PI) * spread;
      let nv = noise(dx * 0.08, dy * 0.08);
      fill(lerp(100, 170, nv), lerp(40, 80, nv), lerp(140, 220, nv), random(60, 160));
      ellipse(dx, dy, random(2, 7), random(2, 7));
    }
  }

  // Yellow center
  for (let c = 0; c < 15; c++) {
    fill(220, 200, 60, random(100, 200));
    ellipse(x + random(-4, 4), y + random(-4, 4), random(1, 4), random(1, 4));
  }
}

function drawSeedHead(x, y) {
  // Dandelion-like seed head - dispersal, ephemerality
  for (let s = 0; s < 40; s++) {
    let sa = random(TWO_PI);
    let sr = random(5, 30);
    let sx = x + cos(sa) * sr;
    let sy = y + sin(sa) * sr;

    // Tiny seed line
    stroke(200, 190, 170, random(30, 80));
    strokeWeight(0.5);
    let lineLen = random(8, 20);
    line(x, y, sx, sy);

    // Tuft at end
    noStroke();
    for (let t = 0; t < 5; t++) {
      fill(220, 215, 200, random(20, 60));
      ellipse(sx + random(-3, 3), sy + random(-3, 3), random(1, 3), random(1, 3));
    }
  }
}

function drawTinyFlower(x, y) {
  noStroke();
  let petals = floor(random(4, 7));
  let col = random();
  for (let p = 0; p < petals; p++) {
    let pa = (p / petals) * TWO_PI;
    let px = x + cos(pa) * 5;
    let py = y + sin(pa) * 4;
    if (col < 0.33) {
      fill(180, 160, 60, random(60, 120));
    } else if (col < 0.66) {
      fill(200, 200, 210, random(60, 120));
    } else {
      fill(160, 50, 70, random(60, 120));
    }
    ellipse(px, py, random(3, 7), random(3, 7));
  }
}

function drawGlazing() {
  // Atmospheric glazing layers for mood
  // Top: dark blue-black vignette
  for (let i = 0; i < 3000; i++) {
    let x = random(width);
    let y = random(height * 0.3);
    let yNorm = y / (height * 0.3);
    let a = lerp(60, 5, yNorm);
    fill(5, 3, 20, a);
    noStroke();
    ellipse(x, y, random(20, 100), random(10, 40));
  }

  // Bottom: deep earth darkness
  for (let i = 0; i < 2000; i++) {
    let x = random(width);
    let y = random(height * 0.7, height);
    let yNorm = (y - height * 0.7) / (height * 0.3);
    let a = lerp(5, 50, yNorm);
    fill(10, 5, 3, a);
    noStroke();
    ellipse(x, y, random(20, 100), random(10, 40));
  }

  // Vignette edges
  for (let i = 0; i < 4000; i++) {
    let edge = floor(random(4));
    let x, y;
    if (edge === 0) { x = random(width * 0.15); y = random(height); }
    else if (edge === 1) { x = random(width * 0.85, width); y = random(height); }
    else if (edge === 2) { x = random(width); y = random(height * 0.08); }
    else { x = random(width); y = random(height * 0.92, height); }

    let edgeDist = min(x, width - x, y, height - y) / 200;
    let a = lerp(40, 0, constrain(edgeDist, 0, 1));
    fill(5, 2, 8, a);
    noStroke();
    ellipse(x, y, random(30, 120), random(20, 60));
  }

  // Warm glow around the body center
  for (let i = 0; i < 1500; i++) {
    let angle = random(TWO_PI);
    let r = random(1) * 300;
    let gx = 800 + cos(angle) * r;
    let gy = 850 + sin(angle) * r * 0.6;
    let d = dist(gx, gy, 800, 850) / 300;
    let a = lerp(15, 0, d);
    fill(160, 100, 50, a);
    noStroke();
    ellipse(gx, gy, random(20, 60), random(15, 40));
  }
}

function drawDetails() {
  // Floating spores / particles of life
  for (let i = 0; i < 200; i++) {
    let x = random(width);
    let y = random(100, 800);
    let sz = random(1, 3);
    let n = noise(x * 0.01, y * 0.01, 10);
    fill(220, 210, 180, lerp(10, 60, n));
    noStroke();
    ellipse(x, y, sz, sz);
  }

  // Subtle moths / night insects near flowers
  for (let m = 0; m < 6; m++) {
    let mx = random(400, 1200);
    let my = random(150, 600);
    drawMoth(mx, my, random(8, 18));
  }

  // Fungi growing from the body
  for (let f = 0; f < 15; f++) {
    let fx = random(500, 1100);
    let fy = random(750, 920);
    drawFungus(fx, fy);
  }

  // Worms / small creatures in the earth
  for (let w = 0; w < 12; w++) {
    let wx = random(300, 1300);
    let wy = random(950, 1600);
    drawWorm(wx, wy);
  }

  // Final thin paint drips downward - decomposition
  for (let d = 0; d < 30; d++) {
    let dx = random(400, 1200);
    let dy = random(800, 1000);
    let dripLen = random(50, 300);
    let dripColor = random() > 0.5 ?
      color(80, 30, 40, 20) :
      color(50, 25, 15, 25);
    stroke(dripColor);
    strokeWeight(random(0.5, 2));
    let cx = dx;
    for (let s = 0; s < dripLen; s++) {
      let nx = cx + (noise(dx * 0.1, s * 0.05) - 0.5) * 2;
      let ny = dy + s;
      point(nx, ny);
      cx = nx;
    }
  }

  noStroke();

  // Moonlight subtle suggestion at top
  for (let i = 0; i < 800; i++) {
    let angle = random(TWO_PI);
    let r = random(1) * 80;
    let lx = 1100 + cos(angle) * r;
    let ly = 100 + sin(angle) * r;
    let d = dist(lx, ly, 1100, 100) / 80;
    fill(200, 200, 220, lerp(25, 0, d));
    ellipse(lx, ly, random(2, 8), random(2, 8));
  }
}

function drawMoth(x, y, size) {
  noStroke();
  // Simple impressionist moth
  for (let w = 0; w < 2; w++) {
    let dir = w === 0 ? -1 : 1;
    for (let i = 0; i < 15; i++) {
      let wx = x + dir * random(2, size);
      let wy = y + random(-size * 0.5, size * 0.5);
      fill(160, 150, 130, random(15, 40));
      ellipse(wx, wy, random(2, 5), random(2, 4));
    }
  }
}

function drawFungus(x, y) {
  noStroke();
  // Small shelf fungus
  let fw = random(10, 25);
  let fh = random(5, 12);
  for (let i = 0; i < 30; i++) {
    let fx = x + random(-fw / 2, fw / 2);
    let fy = y + random(-fh / 2, fh / 2);
    // Check semicircle shape
    if ((fy - y) > 0 || dist(fx, fy, x, y) < fw / 2) {
      let n = noise(fx * 0.1, fy * 0.1);
      fill(lerp(180, 220, n), lerp(170, 200, n), lerp(140, 160, n), random(60, 140));
      ellipse(fx, fy, random(2, 6), random(2, 4));
    }
  }
}

function drawWorm(x, y) {
  stroke(140, 100, 90, 40);
  strokeWeight(random(1.5, 3));
  noFill();
  beginShape();
  let wx = x;
  let wy = y;
  for (let i = 0; i < 15; i++) {
    wx += random(-3, 5);
    wy += random(-2, 2);
    curveVertex(wx, wy);
  }
  endShape();
  noStroke();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Sky gradient - deep indigo to amber at horizon
  for (let y = 0; y < 1400; y++) {
    let t = y / 1400;
    let r = lerp(15, 180, pow(t, 2.5));
    let g = lerp(10, 100, pow(t, 3));
    let b = lerp(60, 40, pow(t, 1.5));
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Ground gradient
  for (let y = 1400; y < height; y++) {
    let t = (y - 1400) / 600;
    let r = lerp(50, 20, t);
    let g = lerp(35, 10, t);
    let b = lerp(25, 8, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Distant hazy horizon glow
  noStroke();
  for (let i = 0; i < 80; i++) {
    let alpha = map(i, 0, 80, 40, 0);
    fill(200, 120, 40, alpha);
    ellipse(800, 1400, 1800 - i * 15, 100 - i * 1);
  }

  // Stars in sky
  for (let i = 0; i < 200; i++) {
    let sx = random(width);
    let sy = random(800);
    let sa = map(sy, 0, 800, 200, 20);
    let ss = random(1, 3);
    fill(220, 220, 255, sa);
    noStroke();
    ellipse(sx, sy, ss, ss);
  }

  // Leaf river on ground
  drawLeafRiver();

  // Draw the tree
  drawTree();

  // Particles dispersing from right side of tree
  drawDispersingParticles();

  // Falling leaves
  drawFallingLeaves();

  // Birds emerging from dissolving branches
  drawBirds();

  // Atmospheric dust/mist
  drawAtmosphere();
}

function drawLeafRiver() {
  // A winding river of fallen leaves on the ground
  for (let i = 0; i < 3000; i++) {
    let t = random(0, 1);
    let baseX = lerp(600, 1600, t);
    let baseY = lerp(1500, 1950, t);
    // Winding path
    let windOffset = sin(t * 5) * 80 + sin(t * 12) * 30;
    let spreadX = random(-40, 40);
    let spreadY = random(-15, 15);
    let lx = baseX + windOffset + spreadX;
    let ly = baseY + spreadY;

    let leafSize = random(3, 10);
    let r = random(120, 200);
    let g = random(40, 80);
    let b = random(10, 30);
    let a = random(80, 200);
    fill(r, g, b, a);
    noStroke();
    push();
    translate(lx, ly);
    rotate(random(TWO_PI));
    ellipse(0, 0, leafSize, leafSize * 0.6);
    pop();
  }
}

function drawTree() {
  // Main trunk
  let startX = 700;
  let startY = 1450;

  // Roots
  drawRoots(startX, startY);

  // Trunk and branches using recursive structure
  stroke(45, 30, 20);
  drawBranch(startX, startY, -PI / 2, 180, 28, 0, 12);
}

function drawRoots(x, y) {
  let numRoots = 7;
  for (let i = 0; i < numRoots; i++) {
    let angle = map(i, 0, numRoots - 1, PI * 0.55, PI * 0.95) + random(-0.1, 0.1);
    let rootLen = random(100, 220);
    let thickness = random(8, 18);
    drawRootBranch(x, y, angle, rootLen, thickness, 0, 4);
  }
}

function drawRootBranch(x, y, angle, len, thickness, depth, maxDepth) {
  if (depth > maxDepth || thickness < 1.5) return;

  let endX = x + cos(angle) * len;
  let endY = y + sin(angle) * len;

  stroke(40, 25, 15, map(depth, 0, maxDepth, 255, 100));
  strokeWeight(thickness);
  noFill();

  // Draw slightly curved root
  let midX = (x + endX) / 2 + random(-15, 15);
  let midY = (y + endY) / 2 + random(-5, 10);
  beginShape();
  vertex(x, y);
  quadraticVertex(midX, midY, endX, endY);
  endShape();

  // Sub-roots
  let numSub = floor(random(1, 3));
  for (let i = 0; i < numSub; i++) {
    let newAngle = angle + random(-0.5, 0.5);
    let newLen = len * random(0.4, 0.7);
    drawRootBranch(endX, endY, newAngle, newLen, thickness * 0.6, depth + 1, maxDepth);
  }
}

function drawBranch(x, y, angle, len, thickness, depth, maxDepth) {
  if (depth > maxDepth || thickness < 1) return;

  let endX = x + cos(angle) * len;
  let endY = y + sin(angle) * len;

  // Calculate dissolution factor based on x position (right side dissolves)
  let dissolveFactor = map(endX, 500, 1200, 0, 1);
  dissolveFactor = constrain(dissolveFactor, 0, 1);

  // Higher depth branches on right side may disappear
  if (depth > 3 && dissolveFactor > 0.5 && random() < dissolveFactor * 0.6) {
    // Spawn particles instead
    for (let p = 0; p < 5; p++) {
      let pt = random();
      let px = lerp(x, endX, pt) + random(-20, 20);
      let py = lerp(y, endY, pt) + random(-20, 20);
      noStroke();
      fill(45, 30, 20, random(40, 150));
      ellipse(px, py, random(2, 6));
    }
    return;
  }

  // Draw branch
  let alpha = map(dissolveFactor, 0, 1, 255, 80);
  let barkR = lerp(55, 35, depth / maxDepth);
  let barkG = lerp(38, 22, depth / maxDepth);
  let barkB = lerp(28, 15, depth / maxDepth);
  stroke(barkR, barkG, barkB, alpha);
  strokeWeight(thickness);

  // Slight curve
  let midX = (x + endX) / 2 + random(-8, 8);
  let midY = (y + endY) / 2 + random(-8, 8);

  noFill();
  beginShape();
  vertex(x, y);
  quadraticVertex(midX, midY, endX, endY);
  endShape();

  // Bark texture
  if (thickness > 5) {
    for (let t = 0; t < 5; t++) {
      let bt = random();
      let bx = lerp(x, endX, bt) + random(-thickness / 3, thickness / 3);
      let by = lerp(y, endY, bt) + random(-thickness / 3, thickness / 3);
      stroke(30, 18, 10, 60);
      strokeWeight(1);
      line(bx, by, bx + random(-5, 5), by + random(-5, 5));
    }
  }

  // Branches
  let numBranches = depth < 3 ? floor(random(2, 4)) : floor(random(1, 3));
  for (let i = 0; i < numBranches; i++) {
    let newAngle = angle + random(-0.7, 0.7);
    // Bias left side branches upward, right side more spread
    if (endX < 700) {
      newAngle = angle + random(-0.6, 0.3);
    }
    let newLen = len * random(0.55, 0.75);
    let newThick = thickness * random(0.5, 0.7);
    drawBranch(endX, endY, newAngle, newLen, newThick, depth + 1, maxDepth);
  }

  // Remaining leaves on left side
  if (depth > 6 && endX < 650 && random() < 0.7) {
    for (let l = 0; l < 3; l++) {
      let lx = endX + random(-15, 15);
      let ly = endY + random(-15, 15);
      noStroke();
      let lr = random(100, 180);
      let lg = random(50, 100);
      let lb = random(10, 40);
      fill(lr, lg, lb, random(100, 220));
      push();
      translate(lx, ly);
      rotate(random(TWO_PI));
      ellipse(0, 0, random(5, 14), random(3, 8));
      pop();
    }
  }
}

function drawDispersingParticles() {
  // Particles streaming from the right side of the tree, as if dissolving
  for (let i = 0; i < 2000; i++) {
    let originX = random(750, 1100);
    let originY = random(300, 1200);

    // Flow direction: up and to the right
    let drift = random(0, 400);
    let px = originX + drift + random(-30, 30);
    let py = originY - drift * 0.3 + random(-50, 50);

    // Size decreases with distance
    let sz = map(drift, 0, 400, random(2, 8), random(0.5, 2));

    // Alpha decreases with distance
    let a = map(drift, 0, 400, random(100, 220), random(10, 60));

    // Color ranges from bark to dust
    let t = drift / 400;
    let r = lerp(50, 80, t) + random(-10, 10);
    let g = lerp(32, 50, t) + random(-10, 10);
    let b = lerp(22, 35, t) + random(-10, 10);

    noStroke();
    fill(r, g, b, a);
    ellipse(px, py, sz, sz);
  }
}

function drawFallingLeaves() {
  for (let i = 0; i < 100; i++) {
    let lx = random(300, 900);
    let ly = random(600, 1500);

    // Gentle falling trajectory
    lx += sin(ly * 0.01 + i) * 40;

    let sz = random(4, 12);
    let r = random(130, 200);
    let g = random(50, 90);
    let b = random(10, 40);
    let a = random(60, 200);

    noStroke();
    fill(r, g, b, a);
    push();
    translate(lx, ly);
    rotate(random(TWO_PI));
    beginShape();
    vertex(0, -sz / 2);
    bezierVertex(sz / 2, -sz / 4, sz / 2, sz / 4, 0, sz / 2);
    bezierVertex(-sz / 2, sz / 4, -sz / 2, -sz / 4, 0, -sz / 2);
    endShape(CLOSE);
    pop();
  }
}

function drawBirds() {
  // Birds emerging from the dissolving top-right area
  for (let i = 0; i < 18; i++) {
    let bx = random(800, 1400);
    let by = random(50, 600);

    // Further birds are smaller
    let dist = sqrt(pow(bx - 900, 2) + pow(by - 400, 2));
    let bSize = map(dist, 0, 700, 20, 6);
    bSize = constrain(bSize, 5, 22);

    let a = map(dist, 0, 700, 220, 40);

    stroke(20, 15, 10, a);
    strokeWeight(map(bSize, 5, 22, 1, 2.5));
    noFill();

    push();
    translate(bx, by);
    let wingAngle = random(0.2, 0.5);
    // Left wing
    beginShape();
    vertex(-bSize, bSize * wingAngle);
    quadraticVertex(-bSize * 0.3, -bSize * 0.3, 0, 0);
    endShape();
    // Right wing
    beginShape();
    vertex(bSize, bSize * wingAngle);
    quadraticVertex(bSize * 0.3, -bSize * 0.3, 0, 0);
    endShape();
    pop();
  }
}

function drawAtmosphere() {
  // Soft mist/dust layers
  noStroke();
  for (let i = 0; i < 300; i++) {
    let mx = random(width);
    let my = random(1200, 1600);
    let ms = random(50, 200);
    let ma = random(2, 10);
    fill(150, 100, 60, ma);
    ellipse(mx, my, ms, ms * 0.3);
  }

  // Vignette
  for (let i = 0; i < 60; i++) {
    let t = i / 60;
    noFill();
    stroke(0, 0, 0, (1 - t) * 8);
    strokeWeight(20);
    rectMode(CENTER);
    rect(width / 2, height / 2, width - i * 25, height - i * 32, 100);
  }

  // Subtle noise texture overlay
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let n = random(-8, 8);
    pixels[i] += n;
    pixels[i + 1] += n;
    pixels[i + 2] += n;
  }
  updatePixels();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Sky gradient - from deep purple at top to dying ember at horizon
  for (let y = 0; y < 1300; y++) {
    let t = y / 1300;
    let r = lerp(10, 90, t);
    let g = lerp(5, 30, t);
    let b = lerp(30, 50, t);
    // Add a warm glow near horizon
    if (t > 0.7) {
      let ht = map(t, 0.7, 1, 0, 1);
      r = lerp(r, 140, ht * 0.6);
      g = lerp(g, 50, ht * 0.4);
      b = lerp(b, 35, ht * 0.3);
    }
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Ground gradient
  for (let y = 1300; y < height; y++) {
    let t = (y - 1300) / 700;
    let r = lerp(60, 20, t);
    let g = lerp(30, 10, t);
    let b = lerp(25, 8, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Distant horizon glow
  noStroke();
  for (let i = 0; i < 80; i++) {
    let alpha = map(i, 0, 80, 40, 0);
    fill(140, 55, 30, alpha);
    ellipse(800, 1300, 1800 - i * 15, 60 - i * 0.5);
  }

  // Ground texture
  for (let i = 0; i < 15000; i++) {
    let x = random(width);
    let y = random(1280, height);
    let nv = noise(x * 0.005, y * 0.005);
    let sz = random(1, 3);
    let alpha = random(10, 40);
    fill(40 + nv * 30, 20 + nv * 15, 15 + nv * 10, alpha);
    noStroke();
    ellipse(x, y, sz, sz * 0.5);
  }

  // Draw the main dead tree
  drawTree(780, 1320, -HALF_PI, 220, 22, 0);

  // Scattered fallen leaves on the ground
  drawFallenLeaves();

  // Roots dissolving into dust
  drawRoots(780, 1320);

  // Crows on branches
  drawCrows();

  // Dust particles rising from base
  drawDust();

  // Atmospheric fog/mist
  for (let y = 1200; y < 1400; y++) {
    let t = 1 - abs(y - 1300) / 100;
    t = max(0, t);
    fill(50, 25, 30, t * 15);
    noStroke();
    rect(0, y, width, 1);
  }

  // Vignette
  drawVignette();
}

let branchEnds = [];

function drawTree(x, y, angle, len, thickness, depth) {
  if (depth > 12 || len < 4 || thickness < 0.5) {
    branchEnds.push({ x: x, y: y });
    return;
  }

  let segments = 8;
  let px = x, py = y;
  let curAngle = angle;

  for (let i = 0; i < segments; i++) {
    let t = i / segments;
    let segLen = len / segments;
    curAngle += random(-0.05, 0.05);
    let nx = px + cos(curAngle) * segLen;
    let ny = py + sin(curAngle) * segLen;

    let curThick = lerp(thickness, thickness * 0.7, t);

    // Dark bark color with variation
    let nv = noise(px * 0.01, py * 0.01, depth * 0.5);
    let r = 35 + nv * 25;
    let g = 20 + nv * 15;
    let b = 15 + nv * 10;

    stroke(r, g, b);
    strokeWeight(curThick);
    line(px, py, nx, ny);

    // Bark texture
    if (curThick > 3) {
      for (let j = 0; j < 2; j++) {
        let bx = lerp(px, nx, random());
        let by = lerp(py, ny, random());
        let off = random(-curThick * 0.3, curThick * 0.3);
        let perpX = -sin(curAngle) * off;
        let perpY = cos(curAngle) * off;
        stroke(r - 10, g - 8, b - 5, 100);
        strokeWeight(1);
        point(bx + perpX, by + perpY);
      }
    }

    px = nx;
    py = ny;
  }

  // Branching
  let numBranches = depth < 3 ? floor(random(2, 4)) : floor(random(1, 3));
  if (depth > 6) numBranches = floor(random(1, 3));

  for (let i = 0; i < numBranches; i++) {
    let branchAngle = angle + random(-0.8, 0.8);
    if (depth === 0) branchAngle = angle + random(-0.5, 0.5);
    let branchLen = len * random(0.55, 0.75);
    let branchThick = thickness * random(0.5, 0.7);

    // Slight upward bias for main branches
    if (depth < 2 && sin(branchAngle) > 0) {
      branchAngle -= 0.3;
    }

    drawTree(px, py, branchAngle, branchLen, branchThick, depth + 1);
  }
}

function drawRoots(x, y) {
  let numRoots = 12;
  for (let i = 0; i < numRoots; i++) {
    let angle = map(i, 0, numRoots, PI * 0.1, PI * 0.9);
    angle += random(-0.15, 0.15);
    let len = random(80, 200);
    let thickness = random(4, 12);

    let px = x, py = y;
    let segments = 15;
    let curAngle = angle;

    for (let s = 0; s < segments; s++) {
      let t = s / segments;
      let segLen = len / segments;
      curAngle += random(-0.1, 0.1);
      let nx = px + cos(curAngle) * segLen;
      let ny = py + sin(curAngle) * segLen;

      let curThick = lerp(thickness, 0, t);
      let alpha = lerp(255, 0, pow(t, 0.7));

      let nv = noise(px * 0.02, py * 0.02);
      stroke(40 + nv * 20, 22 + nv * 10, 15 + nv * 8, alpha);
      strokeWeight(curThick);
      line(px, py, nx, ny);

      // Dust particles near dissolving ends
      if (t > 0.5) {
        for (let d = 0; d < 3; d++) {
          let dx = nx + random(-20, 20);
          let dy = ny + random(-20, 10);
          let da = alpha * 0.3 * random(0.3, 1);
          noStroke();
          fill(50 + nv * 20, 30 + nv * 10, 20, da);
          ellipse(dx, dy, random(1, 4), random(1, 4));
        }
      }

      px = nx;
      py = ny;
    }
  }
}

function drawFallenLeaves() {
  for (let i = 0; i < 300; i++) {
    let x = random(200, 1400);
    let y = random(1300, 1700);

    // Distance from tree base affects color
    let distFromTree = dist(x, y, 780, 1320);
    let colorT = constrain(map(distFromTree, 50, 500, 0, 1), 0, 1);

    // From golden to ash
    let r, g, b;
    if (colorT < 0.5) {
      let t2 = colorT / 0.5;
      r = lerp(180, 120, t2);
      g = lerp(130, 70, t2);
      b = lerp(30, 25, t2);
    } else {
      let t2 = (colorT - 0.5) / 0.5;
      r = lerp(120, 55, t2);
      g = lerp(70, 40, t2);
      b = lerp(25, 30, t2);
    }

    let alpha = random(80, 200);
    let sz = random(4, 12);

    push();
    translate(x, y);
    rotate(random(TWO_PI));
    noStroke();
    fill(r, g, b, alpha);

    // Leaf shape
    beginShape();
    vertex(0, -sz * 0.5);
    bezierVertex(sz * 0.4, -sz * 0.3, sz * 0.4, sz * 0.3, 0, sz * 0.5);
    bezierVertex(-sz * 0.4, sz * 0.3, -sz * 0.4, -sz * 0.3, 0, -sz * 0.5);
    endShape(CLOSE);

    // Leaf vein
    stroke(r - 20, g - 15, b - 10, alpha * 0.5);
    strokeWeight(0.5);
    line(0, -sz * 0.4, 0, sz * 0.4);
    pop();
  }
}

function drawCrows() {
  // Place crows at some branch ends
  let crowPositions = [];
  if (branchEnds.length > 0) {
    // Pick some high branch ends
    let candidates = branchEnds.filter(p => p.y < 800);
    for (let i = 0; i < min(7, candidates.length); i++) {
      let idx = floor(random(candidates.length));
      crowPositions.push(candidates[idx]);
      candidates.splice(idx, 1);
    }
  }

  // Add a few flying crows in the sky
  crowPositions.push({ x: 300, y: 350 });
  crowPositions.push({ x: 450, y: 280 });
  crowPositions.push({ x: 1200, y: 400 });
  crowPositions.push({ x: 1050, y: 300 });

  for (let i = 0; i < crowPositions.length; i++) {
    let p = crowPositions[i];
    let sz = map(p.y, 0, 1300, 8, 20);
    sz = constrain(sz, 8, 25);
    drawCrow(p.x, p.y, sz, i < 7);
  }
}

function drawCrow(x, y, sz, perched) {
  push();
  translate(x, y);

  fill(10, 8, 12);
  noStroke();

  if (perched) {
    // Perched crow - simple silhouette
    // Body
    ellipse(0, 0, sz * 1.5, sz);
    // Head
    ellipse(sz * 0.5, -sz * 0.3, sz * 0.7, sz * 0.6);
    // Beak
    triangle(sz * 0.8, -sz * 0.3, sz * 1.2, -sz * 0.25, sz * 0.8, -sz * 0.15);
    // Tail
    triangle(-sz * 0.5, 0, -sz * 1.2, sz * 0.2, -sz * 0.7, -sz * 0.2);
  } else {
    // Flying crow - V shape wings
    stroke(10, 8, 12);
    strokeWeight(sz * 0.15);
    noFill();
    let wingSpan = sz * 1.5;
    // Left wing
    beginShape();
    vertex(-wingSpan, -sz * 0.3);
    quadraticVertex(-wingSpan * 0.5, -sz * 0.6, 0, 0);
    endShape();
    // Right wing
    beginShape();
    vertex(wingSpan, -sz * 0.3);
    quadraticVertex(wingSpan * 0.5, -sz * 0.6, 0, 0);
    endShape();
    // Body
    fill(10, 8, 12);
    noStroke();
    ellipse(0, 0, sz * 0.4, sz * 0.3);
  }
  pop();
}

function drawDust() {
  // Particles rising from the base of the tree
  for (let i = 0; i < 500; i++) {
    let x = 780 + random(-150, 150);
    let baseY = 1320;
    let y = baseY + random(-50, 200);
    let nv = noise(x * 0.01, y * 0.01, i * 0.1);

    // Some particles drift upward
    y -= nv * 100;

    let sz = random(1, 4);
    let alpha = random(20, 80) * (1 - constrain(map(y, 1100, 1400, 0, 1), 0, 1));
    alpha = max(alpha, 5);

    noStroke();
    fill(70 + nv * 30, 40 + nv * 20, 25 + nv * 15, alpha);
    ellipse(x, y, sz, sz);
  }

  // Falling leaves in the air
  for (let i = 0; i < 40; i++) {
    let x = random(400, 1200);
    let y = random(400, 1300);
    let nv = noise(x * 0.005, y * 0.005, i);
    let sz = random(3, 8);
    let alpha = random(40, 120);

    let r = lerp(160, 80, nv);
    let g = lerp(110, 45, nv);
    let b = lerp(30, 25, nv);

    push();
    translate(x, y);
    rotate(random(TWO_PI));
    noStroke();
    fill(r, g, b, alpha);
    ellipse(0, 0, sz, sz * 0.5);
    pop();
  }
}

function drawVignette() {
  // Radial vignette
  let cx = width / 2;
  let cy = height / 2;
  let maxDist = dist(0, 0, cx, cy);

  noStroke();
  for (let r = maxDist; r > maxDist * 0.3; r -= 2) {
    let t = map(r, maxDist * 0.3, maxDist, 0, 1);
    t = pow(t, 1.5);
    fill(0, 0, 0, t * 4);
    ellipse(cx, cy, r * 2, r * 2);
  }

  // Extra darkening at corners
  for (let i = 0; i < 30; i++) {
    let alpha = map(i, 0, 30, 15, 0);
    fill(0, 0, 0, alpha);
    rect(0, 0, width, height);
    // Shrink slightly with each pass but as a gradient
  }

  // Top and bottom edge darkening
  for (let y = 0; y < 200; y++) {
    let alpha = map(y, 0, 200, 80, 0);
    fill(0, 0, 0, alpha);
    rect(0, y, width, 1);
  }
  for (let y = height - 200; y < height; y++) {
    let alpha = map(y, height - 200, height, 0, 100);
    fill(0, 0, 0, alpha);
    rect(0, y, width, 1);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Sky gradient - dusky, somber
  for (let y = 0; y < 1400; y++) {
    let t = y / 1400;
    let r = lerp(45, 180, t * t);
    let g = lerp(30, 100, t * t);
    let b = lerp(60, 60, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Ground gradient
  for (let y = 1400; y < height; y++) {
    let t = (y - 1400) / 600;
    let r = lerp(80, 30, t);
    let g = lerp(55, 18, t);
    let b = lerp(30, 12, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Distant misty hills
  noStroke();
  for (let layer = 0; layer < 4; layer++) {
    let baseY = 1200 - layer * 120;
    let alpha = 40 + layer * 15;
    fill(60 - layer * 10, 40 - layer * 5, 50 - layer * 5, alpha);
    beginShape();
    vertex(0, height);
    for (let x = 0; x <= width; x += 5) {
      let n = noise(x * 0.002 + layer * 10, layer * 3.7);
      let y = baseY + n * 250;
      vertex(x, y);
    }
    vertex(width, height);
    endShape(CLOSE);
  }

  // Ground texture with noise
  for (let i = 0; i < 8000; i++) {
    let x = random(width);
    let y = random(1380, height);
    let n = noise(x * 0.01, y * 0.01);
    let sz = random(1, 4);
    fill(60 + n * 50, 35 + n * 30, 15 + n * 15, 80);
    noStroke();
    ellipse(x, y, sz, sz);
  }

  // Fallen leaves on ground
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = random(1420, 1900);
    let distFromTree = abs(x - 800);
    if (distFromTree < 500 && random() < 0.7 || random() < 0.3) {
      drawFallenLeaf(x, y);
    }
  }

  // Leaf pile at tree base
  for (let i = 0; i < 200; i++) {
    let angle = random(TWO_PI);
    let r = random(30, 250);
    let x = 800 + cos(angle) * r;
    let y = 1450 + sin(angle) * r * 0.3 + random(-20, 20);
    drawFallenLeaf(x, y);
  }

  // Draw the main dead tree
  drawTree(800, 1430, -HALF_PI, 180, 12, 0);

  // Small green sprouts at base
  for (let i = 0; i < 7; i++) {
    let sx = 750 + i * 18 - 20 + random(-10, 10);
    let sy = 1460 + random(-5, 10);
    drawSprout(sx, sy);
  }

  // More sprouts scattered
  for (let i = 0; i < 4; i++) {
    let sx = 650 + random(300);
    let sy = 1470 + random(20);
    drawSprout(sx, sy);
  }

  // Crows in the sky
  drawCrows();

  // Atmospheric fog/mist
  for (let y = 1300; y < 1500; y++) {
    let t = 1 - abs(y - 1400) / 100;
    t = max(0, t);
    fill(120, 80, 60, t * 25);
    noStroke();
    rect(0, y, width, 1);
  }

  // Vignette
  drawVignette();

  // Dust particles in light
  for (let i = 0; i < 150; i++) {
    let x = random(width);
    let y = random(800, 1500);
    let sz = random(1, 3);
    let a = random(20, 80);
    fill(200, 170, 120, a);
    noStroke();
    ellipse(x, y, sz, sz);
  }

  // Subtle light rays from upper left
  drawLightRays();
}

function drawTree(x, y, angle, len, thickness, depth) {
  if (len < 4 || depth > 14) return;

  let endX = x + cos(angle) * len;
  let endY = y + sin(angle) * len;

  // Dark bark color with slight variation
  let barkR = 45 + depth * 3 + random(-5, 5);
  let barkG = 28 + depth * 2 + random(-3, 3);
  let barkB = 15 + depth * 1 + random(-2, 2);

  stroke(barkR, barkG, barkB);
  strokeWeight(thickness);
  strokeCap(ROUND);
  line(x, y, endX, endY);

  // Bark texture on thicker branches
  if (thickness > 5) {
    for (let i = 0; i < 3; i++) {
      let t = random(0.1, 0.9);
      let bx = lerp(x, endX, t);
      let by = lerp(y, endY, t);
      stroke(barkR - 15, barkG - 10, barkB - 5, 100);
      strokeWeight(thickness * 0.3);
      let perpX = -sin(angle) * thickness * 0.4;
      let perpY = cos(angle) * thickness * 0.4;
      line(bx - perpX, by - perpY, bx + perpX, by + perpY);
    }
  }

  // Branching
  let branches = depth < 3 ? floor(random(2, 4)) : floor(random(1, 4));

  for (let i = 0; i < branches; i++) {
    let newAngle = angle + random(-0.7, 0.7);
    if (depth === 0) {
      newAngle = angle + random(-0.5, 0.5);
    }
    let lenMult = random(0.55, 0.78);
    let thickMult = random(0.55, 0.75);

    // Slight curve by adding intermediate segments
    let branchStartT = depth < 2 ? random(0.6, 0.9) : random(0.7, 1.0);
    let startX = lerp(x, endX, branchStartT);
    let startY = lerp(y, endY, branchStartT);

    drawTree(startX, startY, newAngle, len * lenMult, thickness * thickMult, depth + 1);
  }

  // Dead small twigs at higher depths
  if (depth > 5 && random() < 0.4) {
    let twigAngle = angle + random(-1.2, 1.2);
    let twigLen = random(5, 20);
    stroke(55, 35, 20, 150);
    strokeWeight(1);
    line(endX, endY, endX + cos(twigAngle) * twigLen, endY + sin(twigAngle) * twigLen);
  }

  // A few remaining dried leaves on some branch tips
  if (depth > 8 && random() < 0.15) {
    noStroke();
    fill(120 + random(40), 60 + random(30), 20, 150);
    let leafSize = random(4, 10);
    ellipse(endX, endY, leafSize, leafSize * 1.5);
  }

  // Roots at base
  if (depth === 0) {
    for (let i = 0; i < 8; i++) {
      let rootAngle = PI * 0.1 + random(PI * 0.8);
      let rootLen = random(80, 220);
      let rootThick = random(8, 25);
      drawRoot(x, y, rootAngle, rootLen, rootThick, 0);
    }
  }
}

function drawRoot(x, y, angle, len, thickness, depth) {
  if (len < 5 || depth > 5) return;

  let endX = x + cos(angle) * len;
  let endY = y + sin(angle) * len;

  let barkR = 40 + depth * 5;
  let barkG = 25 + depth * 3;
  let barkB = 12 + depth * 2;

  stroke(barkR, barkG, barkB);
  strokeWeight(thickness);
  strokeCap(ROUND);
  line(x, y, endX, endY);

  let branches = floor(random(1, 3));
  for (let i = 0; i < branches; i++) {
    let newAngle = angle + random(-0.5, 0.5);
    drawRoot(endX, endY, newAngle, len * random(0.5, 0.7), thickness * 0.6, depth + 1);
  }
}

function drawFallenLeaf(x, y) {
  push();
  translate(x, y);
  rotate(random(TWO_PI));
  let leafType = random();
  let r, g, b;
  if (leafType < 0.3) {
    r = 140 + random(50);
    g = 70 + random(30);
    b = 15 + random(15);
  } else if (leafType < 0.6) {
    r = 160 + random(40);
    g = 110 + random(30);
    b = 20 + random(15);
  } else {
    r = 80 + random(30);
    g = 50 + random(20);
    b = 20 + random(10);
  }
  let a = random(120, 220);
  fill(r, g, b, a);
  noStroke();
  let sz = random(4, 12);
  beginShape();
  vertex(0, -sz);
  bezierVertex(sz * 0.6, -sz * 0.6, sz * 0.6, sz * 0.3, 0, sz);
  bezierVertex(-sz * 0.6, sz * 0.3, -sz * 0.6, -sz * 0.6, 0, -sz);
  endShape(CLOSE);
  // Leaf vein
  stroke(r - 20, g - 15, b - 5, a * 0.5);
  strokeWeight(0.5);
  line(0, -sz * 0.8, 0, sz * 0.8);
  pop();
}

function drawSprout(x, y) {
  push();
  translate(x, y);

  // Stem
  stroke(50, 120, 40);
  strokeWeight(2);
  noFill();
  let stemH = random(20, 45);
  beginShape();
  vertex(0, 0);
  let cx = random(-5, 5);
  curveVertex(0, 0);
  curveVertex(0, 0);
  curveVertex(cx, -stemH * 0.5);
  curveVertex(cx * 0.5, -stemH);
  curveVertex(cx * 0.5, -stemH);
  endShape();

  // Two small leaves
  noStroke();
  fill(60, 150, 50, 200);

  push();
  translate(cx * 0.5, -stemH);
  rotate(-0.3);
  ellipse(-6, -2, 12, 5);
  pop();

  push();
  translate(cx * 0.5, -stemH);
  rotate(0.3);
  ellipse(6, -2, 12, 5);
  pop();

  // Tiny center bud
  fill(80, 180, 60, 220);
  ellipse(cx * 0.5, -stemH - 2, 4, 6);

  pop();
}

function drawCrows() {
  let crows = [
    {x: 300, y: 180, sz: 1.2},
    {x: 420, y: 120, sz: 0.9},
    {x: 500, y: 200, sz: 0.7},
    {x: 250, y: 280, sz: 0.6},
    {x: 180, y: 150, sz: 0.8},
    {x: 550, y: 300, sz: 0.5},
    {x: 380, y: 350, sz: 0.5},
    {x: 150, y: 320, sz: 0.4},
    {x: 650, y: 160, sz: 0.6},
    {x: 480, y: 80, sz: 0.5},
    {x: 100, y: 220, sz: 0.45},
    {x: 700, y: 250, sz: 0.35},
  ];

  for (let c of crows) {
    drawCrow(c.x, c.y, c.sz);
  }
}

function drawCrow(x, y, sz) {
  push();
  translate(x, y);
  scale(sz);

  noFill();
  stroke(15, 10, 10);
  strokeWeight(2.5);
  strokeCap(ROUND);

  // Left wing
  beginShape();
  vertex(-25, 5);
  bezierVertex(-18, -8, -8, -12, 0, 0);
  endShape();

  // Right wing
  beginShape();
  vertex(0, 0);
  bezierVertex(8, -12, 18, -8, 25, 5);
  endShape();

  // Body hint
  fill(15, 10, 10);
  noStroke();
  ellipse(0, 2, 6, 4);

  pop();
}

function drawVignette() {
  // Corner darkness
  let maxDist = dist(0, 0, width / 2, height / 2);

  noStroke();
  for (let r = maxDist; r > 0; r -= 5) {
    let t = map(r, maxDist * 0.5, maxDist, 0, 1);
    t = constrain(t, 0, 1);
    fill(0, 0, 0, t * 4);
    ellipse(width / 2, height / 2, r * 2, r * 2);
  }

  // Extra darkening at edges
  for (let i = 0; i < 50; i++) {
    let a = map(i, 0, 50, 8, 0);
    fill(0, 0, 0, a);
    rect(0, 0, width, i * 10);
    rect(0, height - i * 10, width, i * 10);
    rect(0, 0, i * 8, height);
    rect(width - i * 8, 0, i * 8, height);
  }
}

function drawLightRays() {
  push();
  blendMode(ADD);

  for (let i = 0; i < 12; i++) {
    let angle = random(0.3, 0.9);
    let startX = random(-100, 400);
    let startY = random(-50, 200);

    let rayLength = random(1200, 1800);
    let endX = startX + cos(angle) * rayLength;
    let endY = startY + sin(angle) * rayLength;

    for (let w = 0; w < 40; w++) {
      let alpha = map(w, 0, 40, 3, 0);
      stroke(200, 160, 100, alpha);
      strokeWeight(w * 2);
      line(startX, startY, endX, endY);
    }
  }

  blendMode(BLEND);
  pop();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Sky gradient - dark, somber
  for (let y = 0; y < 1000; y++) {
    let t = y / 1000;
    let r = lerp(10, 45, t);
    let g = lerp(5, 25, t);
    let b = lerp(30, 50, t);
    stroke(r, g, b);
    line(0, y, 1600, y);
  }

  // Ground level at y=1000, underground gradient
  for (let y = 1000; y < 2000; y++) {
    let t = (y - 1000) / 1000;
    let r = lerp(45, 15, t);
    let g = lerp(25, 8, t);
    let b = lerp(30, 12, t);
    stroke(r, g, b);
    line(0, y, 1600, y);
  }

  // Ground surface line with texture
  noStroke();
  for (let x = 0; x < 1600; x++) {
    let yOff = noise(x * 0.005) * 40 - 20;
    fill(50, 30, 25, 200);
    rect(x, 995 + yOff, 1, 15);
  }

  // Draw underground bones/skulls
  drawBones();

  // Draw underground roots merging with bones
  drawRoots(800, 1000, PI / 2, 120, 8, true);

  // Draw the tree above ground
  drawTree(800, 1000, -PI / 2, 180, 12);

  // Falling leaves / golden particles
  drawFallingLeaves();

  // Atmospheric particles in sky
  drawAtmosphere();

  // Moon/dim light source
  drawMoon();

  // Ground fog
  drawFog();
}

function drawMoon() {
  // Dim pale moon upper right
  let mx = 1200, my = 180, mr = 80;
  noStroke();
  // Glow
  for (let r = 200; r > 0; r -= 2) {
    let a = map(r, 0, 200, 25, 0);
    fill(180, 170, 150, a);
    ellipse(mx, my, r * 2, r * 2);
  }
  fill(200, 190, 170, 40);
  ellipse(mx, my, mr * 2, mr * 2);
}

function drawTree(x, y, angle, len, depth) {
  if (depth <= 0 || len < 4) return;

  let x2 = x + cos(angle) * len;
  let y2 = y + sin(angle) * len;

  let sw = map(depth, 0, 12, 1, 28);
  stroke(35 + depth * 3, 22 + depth * 2, 18 + depth, 230);
  strokeWeight(sw);
  noFill();

  // Draw slightly curved branch
  beginShape();
  let midX = (x + x2) / 2 + random(-8, 8);
  let midY = (y + y2) / 2 + random(-8, 8);
  curveVertex(x, y);
  curveVertex(x, y);
  curveVertex(midX, midY);
  curveVertex(x2, y2);
  curveVertex(x2, y2);
  endShape();

  // Bark texture
  if (sw > 5) {
    for (let i = 0; i < len / 3; i++) {
      let t = random();
      let bx = lerp(x, x2, t) + random(-sw / 3, sw / 3);
      let by = lerp(y, y2, t) + random(-sw / 3, sw / 3);
      stroke(25, 15, 10, 80);
      strokeWeight(1);
      line(bx, by, bx + random(-3, 3), by + random(-6, 2));
    }
  }

  // Branching
  let branches = depth > 8 ? floor(random(2, 4)) : floor(random(1, 4));
  for (let i = 0; i < branches; i++) {
    let newAngle = angle + random(-0.6, 0.6);
    // Bias upward
    if (depth > 6) newAngle = angle + random(-0.4, 0.4);
    let newLen = len * random(0.6, 0.78);
    drawTree(x2, y2, newAngle, newLen, depth - 1);
  }

  // Dead branch ends - small twigs
  if (depth <= 2) {
    stroke(50, 35, 25, 150);
    strokeWeight(1);
    for (let i = 0; i < 3; i++) {
      let ta = angle + random(-1, 1);
      let tl = random(5, 20);
      line(x2, y2, x2 + cos(ta) * tl, y2 + sin(ta) * tl);
    }
  }
}

function drawRoots(x, y, angle, len, depth, withBones) {
  if (depth <= 0 || len < 3) return;

  let x2 = x + cos(angle) * len;
  let y2 = y + sin(angle) * len;

  let sw = map(depth, 0, 8, 1, 22);

  // Roots are darker, more organic
  stroke(40 + depth * 2, 20 + depth, 15, 200);
  strokeWeight(sw);
  noFill();

  beginShape();
  let midX = (x + x2) / 2 + random(-12, 12);
  let midY = (y + y2) / 2 + random(-5, 5);
  curveVertex(x, y);
  curveVertex(x, y);
  curveVertex(midX, midY);
  curveVertex(x2, y2);
  curveVertex(x2, y2);
  endShape();

  // Occasionally merge with bone-like structures
  if (withBones && depth < 5 && random() < 0.3) {
    drawSmallBone(x2 + random(-20, 20), y2 + random(-10, 10), random(TWO_PI), random(15, 40));
  }

  let branches = floor(random(2, 4));
  for (let i = 0; i < branches; i++) {
    let newAngle = angle + random(-0.7, 0.7);
    let newLen = len * random(0.55, 0.75);
    drawRoots(x2, y2, newAngle, newLen, depth - 1, withBones);
  }

  // Root tips fade into thin tendrils
  if (depth <= 1) {
    stroke(35, 18, 12, 100);
    strokeWeight(0.5);
    for (let i = 0; i < 4; i++) {
      let ta = angle + random(-0.8, 0.8);
      let tl = random(8, 30);
      let tx = x2 + cos(ta) * tl;
      let ty = y2 + sin(ta) * tl;
      line(x2, y2, tx, ty);
    }
  }
}

function drawSmallBone(x, y, angle, len) {
  push();
  translate(x, y);
  rotate(angle);
  noFill();
  stroke(160, 150, 130, 100);
  strokeWeight(3);
  line(-len / 2, 0, len / 2, 0);
  // Bone ends (knobs)
  fill(160, 150, 130, 80);
  noStroke();
  ellipse(-len / 2, -3, 8, 8);
  ellipse(-len / 2, 3, 8, 8);
  ellipse(len / 2, -3, 8, 8);
  ellipse(len / 2, 3, 8, 8);
  pop();
}

function drawBones() {
  // Scattered skeletal remains underground
  // Skulls
  for (let i = 0; i < 8; i++) {
    let sx = random(200, 1400);
    let sy = random(1200, 1850);
    let sz = random(25, 55);
    drawSkull(sx, sy, sz);
  }

  // Scattered bones
  for (let i = 0; i < 30; i++) {
    let bx = random(100, 1500);
    let by = random(1050, 1900);
    drawSmallBone(bx, by, random(TWO_PI), random(20, 60));
  }

  // Ribcage fragments
  for (let i = 0; i < 4; i++) {
    let rx = random(250, 1350);
    let ry = random(1300, 1800);
    drawRibFragment(rx, ry, random(-0.3, 0.3));
  }
}

function drawSkull(x, y, s) {
  push();
  translate(x, y);
  let alpha = map(y, 1100, 1900, 90, 40);

  // Cranium
  noFill();
  stroke(170, 155, 135, alpha);
  strokeWeight(2);
  ellipse(0, -s * 0.1, s * 1.1, s * 1.2);

  // Jaw area
  beginShape();
  curveVertex(-s * 0.35, s * 0.2);
  curveVertex(-s * 0.35, s * 0.2);
  curveVertex(-s * 0.25, s * 0.5);
  curveVertex(0, s * 0.6);
  curveVertex(s * 0.25, s * 0.5);
  curveVertex(s * 0.35, s * 0.2);
  curveVertex(s * 0.35, s * 0.2);
  endShape();

  // Eye sockets
  fill(20, 10, 8, alpha);
  noStroke();
  ellipse(-s * 0.18, -s * 0.1, s * 0.28, s * 0.25);
  ellipse(s * 0.18, -s * 0.1, s * 0.28, s * 0.25);

  // Nose cavity
  triangle(-s * 0.06, s * 0.1, s * 0.06, s * 0.1, 0, s * 0.25);

  // Crack lines
  stroke(140, 125, 110, alpha * 0.6);
  strokeWeight(1);
  let cx = random(-s * 0.2, s * 0.2);
  let cy = random(-s * 0.4, -s * 0.1);
  for (let j = 0; j < 3; j++) {
    let ex = cx + random(-s * 0.3, s * 0.3);
    let ey = cy + random(-s * 0.2, s * 0.2);
    line(cx, cy, ex, ey);
    cx = ex;
    cy = ey;
  }

  pop();
}

function drawRibFragment(x, y, rot) {
  push();
  translate(x, y);
  rotate(rot);
  noFill();
  stroke(155, 140, 120, 60);
  strokeWeight(2.5);
  for (let i = 0; i < 5; i++) {
    let yOff = i * 12;
    let w = 50 - i * 4;
    arc(0, yOff, w, 25, PI + 0.3, TWO_PI - 0.3);
  }
  pop();
}

function drawFallingLeaves() {
  noStroke();
  for (let i = 0; i < 120; i++) {
    let lx = random(200, 1400);
    let ly = random(100, 980);
    let ls = random(3, 10);

    // Golden, amber leaves
    let r = random(180, 240);
    let g = random(140, 200);
    let b = random(30, 80);
    let a = map(ly, 100, 980, 200, 60);

    // Glow around leaf
    fill(r, g, b, a * 0.3);
    ellipse(lx, ly, ls * 4, ls * 4);

    // Leaf shape
    fill(r, g, b, a);
    push();
    translate(lx, ly);
    rotate(random(TWO_PI));
    beginShape();
    vertex(0, -ls);
    bezierVertex(ls * 0.6, -ls * 0.5, ls * 0.6, ls * 0.5, 0, ls);
    bezierVertex(-ls * 0.6, ls * 0.5, -ls * 0.6, -ls * 0.5, 0, -ls);
    endShape(CLOSE);
    pop();
  }

  // Some leaves that have almost become pure light (dots)
  for (let i = 0; i < 60; i++) {
    let px = random(300, 1300);
    let py = random(50, 950);
    let ps = random(2, 5);
    let a = random(40, 160);
    fill(220, 190, 80, a);
    ellipse(px, py, ps, ps);
    // Tiny glow
    fill(220, 190, 80, a * 0.2);
    ellipse(px, py, ps * 3, ps * 3);
  }
}

function drawAtmosphere() {
  // Subtle stars/particles in sky
  noStroke();
  for (let i = 0; i < 100; i++) {
    let sx = random(1600);
    let sy = random(600);
    let ss = random(1, 3);
    fill(200, 195, 180, random(20, 80));
    ellipse(sx, sy, ss, ss);
  }

  // Nebula-like wisps
  for (let i = 0; i < 15; i++) {
    let wx = random(1600);
    let wy = random(100, 500);
    let ws = random(100, 300);
    fill(60, 30, 70, 8);
    ellipse(wx, wy, ws, ws * 0.4);
  }
}

function drawFog() {
  noStroke();
  // Ground fog near surface
  for (let i = 0; i < 50; i++) {
    let fx = random(-100, 1700);
    let fy = random(920, 1050);
    let fw = random(150, 400);
    let fh = random(20, 60);
    fill(80, 70, 65, random(5, 20));
    ellipse(fx, fy, fw, fh);
  }

  // Underground mist/earth layers
  for (let i = 0; i < 30; i++) {
    let ux = random(1600);
    let uy = random(1050, 1900);
    let uw = random(100, 300);
    let uh = random(10, 40);
    fill(50, 30, 20, random(5, 15));
    ellipse(ux, uy, uw, uh);
  }

  // Vignette
  drawVignette();
}

function drawVignette() {
  noStroke();
  let cx = 800, cy = 1000;
  let maxR = 1500;
  for (let r = maxR; r > 600; r -= 5) {
    let a = map(r, 600, maxR, 0, 40);
    fill(0, 0, 0, a);
    ellipse(cx, cy, r * 2, r * 2.2);
  }

  // Extra darkness at corners
  fill(0, 0, 0, 60);
  rect(0, 0, 200, 200);
  rect(1400, 0, 200, 200);
  rect(0, 1800, 200, 200);
  rect(1400, 1800, 200, 200);

  // Soft gradient borders
  for (let i = 0; i < 80; i++) {
    let a = map(i, 0, 80, 30, 0);
    fill(0, 0, 0, a);
    rect(0, i * 2, 1600, 2);
    rect(0, 1998 - i * 2, 1600, 2);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Sky gradient - deep indigo to dawn light
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(15, 45, pow(1 - t, 2)) + lerp(0, 30, t);
    let g = lerp(10, 25, pow(1 - t, 2)) + lerp(0, 15, t);
    let b = lerp(60, 90, pow(1 - t, 2)) + lerp(0, 10, t);

    // Add a subtle warm glow at horizon area (around y = 1400)
    let horizonDist = abs(y - 1350) / 600;
    let horizonGlow = exp(-horizonDist * horizonDist * 3);
    r += horizonGlow * 80;
    g += horizonGlow * 40;
    b += horizonGlow * 20;

    stroke(r, g, b);
    line(0, y, width, y);
  }

  noStroke();

  // Stars in upper sky
  for (let i = 0; i < 300; i++) {
    let sx = random(width);
    let sy = random(height * 0.6);
    let sa = map(sy, 0, height * 0.6, 200, 20);
    let ss = random(1, 3);
    fill(220, 220, 255, sa);
    ellipse(sx, sy, ss, ss);
  }

  // Subtle nebula/mist in sky
  for (let i = 0; i < 5000; i++) {
    let x = random(width);
    let y = random(height * 0.7);
    let n = noise(x * 0.002, y * 0.003);
    if (n > 0.55) {
      let a = map(n, 0.55, 1, 0, 15);
      fill(100, 70, 120, a);
      ellipse(x, y, random(20, 60), random(20, 60));
    }
  }

  // Ground - dark earth
  for (let y = 1400; y < height; y++) {
    let t = (y - 1400) / 600;
    for (let x = 0; x < width; x += 2) {
      let n = noise(x * 0.005, y * 0.005);
      let r = lerp(35, 15, t) + n * 20;
      let g = lerp(25, 8, t) + n * 10;
      let b = lerp(20, 5, t) + n * 8;
      fill(r, g, b);
      noStroke();
      rect(x, y, 2, 1);
    }
  }

  // Underground river - glowing veins beneath surface
  stroke(40, 80, 120, 60);
  strokeWeight(1);
  noFill();
  for (let r = 0; r < 15; r++) {
    let baseY = 1600 + r * 25;
    beginShape();
    for (let x = 0; x < width; x += 5) {
      let y = baseY + noise(x * 0.003 + r * 10, r * 0.5) * 100 - 50;
      let glow = noise(x * 0.01, r * 2);
      stroke(30 + glow * 40, 60 + glow * 60, 100 + glow * 60, 30 + glow * 40);
      curveVertex(x, y);
    }
    endShape();
  }

  // Underground river glow spots
  for (let i = 0; i < 800; i++) {
    let x = random(width);
    let y = random(1500, 2000);
    let n = noise(x * 0.005, y * 0.005 + 100);
    if (n > 0.5) {
      let a = map(n, 0.5, 1, 0, 50);
      fill(40, 100, 140, a);
      noStroke();
      ellipse(x, y, random(3, 15), random(3, 15));
    }
  }

  // Draw the tree
  drawTree(800, 1400, -PI / 2, 180, 12);

  // Birds emerging from tree top area - they dissolve from branches
  let birds = [];
  for (let i = 0; i < 80; i++) {
    let angle = random(-PI * 0.8, -PI * 0.2);
    let dist = random(100, 800);
    let bx = 800 + cos(angle) * dist + random(-200, 200);
    let by = 1400 + sin(angle) * dist + random(-100, 50);
    // Birds higher up are more formed, lower ones more fragmentary
    let formedness = map(by, 1200, 300, 0, 1);
    formedness = constrain(formedness, 0, 1);
    birds.push({ x: bx, y: by, f: formedness, s: random(5, 20) * (0.5 + formedness * 0.5) });
  }

  // Sort by y for layering
  birds.sort((a, b) => b.y - a.y);

  for (let bird of birds) {
    drawBird(bird.x, bird.y, bird.s, bird.f);
  }

  // Falling leaves / particles that transition between leaves and birds
  for (let i = 0; i < 120; i++) {
    let x = random(200, 1400);
    let y = random(400, 1500);
    let n = noise(x * 0.01, y * 0.01, 50);
    let s = random(3, 12);
    let isBird = n > 0.5 && y < 1000;

    if (isBird) {
      let a = map(y, 400, 1000, 180, 40);
      drawBird(x, y, s, map(y, 400, 1000, 1, 0.2));
    } else {
      // Falling leaf
      let t = map(y, 400, 1500, 0, 1);
      let r = lerp(80, 40, t);
      let g = lerp(50, 20, t);
      let b = lerp(30, 15, t);
      let a = lerp(150, 30, t);
      fill(r, g, b, a);
      noStroke();
      push();
      translate(x, y);
      rotate(noise(x, y) * TWO_PI);
      ellipse(0, 0, s, s * 0.5);
      pop();
    }
  }

  // Roots connecting to underground rivers
  drawRoots(800, 1400, 8);

  // Atmospheric fog near ground
  for (let i = 0; i < 3000; i++) {
    let x = random(width);
    let y = random(1300, 1500);
    let n = noise(x * 0.003, y * 0.005 + 200);
    let a = n * 20;
    fill(60, 50, 70, a);
    noStroke();
    ellipse(x, y, random(30, 100), random(10, 30));
  }

  // Subtle light rays from horizon
  for (let i = 0; i < 20; i++) {
    let angle = random(-PI * 0.15, PI * 0.15) - PI / 2;
    let startX = random(400, 1200);
    let startY = 1350;
    let len = random(400, 900);
    let endX = startX + cos(angle) * len;
    let endY = startY + sin(angle) * len;

    for (let j = 0; j < 3; j++) {
      stroke(255, 200, 130, 3);
      strokeWeight(random(10, 40));
      line(startX + random(-20, 20), startY, endX + random(-20, 20), endY);
    }
  }

  // Dust motes / spirit particles rising
  for (let i = 0; i < 500; i++) {
    let x = random(width);
    let y = random(height * 0.8);
    let n = noise(x * 0.01 + 300, y * 0.01);
    if (n > 0.6) {
      let s = random(1, 4);
      let a = map(n, 0.6, 1, 20, 100);
      let warmth = map(y, 0, height * 0.8, 0.3, 1);
      fill(200 * warmth + 55, 180 * warmth + 30, 120 * warmth + 50, a);
      noStroke();
      ellipse(x, y, s, s);
    }
  }
}

function drawTree(x, y, angle, len, depth) {
  if (depth <= 0 || len < 3) return;

  let endX = x + cos(angle) * len;
  let endY = y + sin(angle) * len;

  // Tree color - dark, slightly warm
  let w = map(depth, 0, 12, 1, 18);

  // As branches get thinner, they start to dissolve/fragment
  if (depth > 4) {
    // Solid trunk and main branches
    stroke(30 + depth * 2, 20 + depth, 15 + depth, 220);
    strokeWeight(w);
    line(x, y, endX, endY);

    // Bark texture
    for (let i = 0; i < w; i++) {
      let t = random();
      let px = lerp(x, endX, t) + random(-w / 2, w / 2);
      let py = lerp(y, endY, t) + random(-w / 2, w / 2);
      let n = noise(px * 0.05, py * 0.05);
      stroke(20 + n * 30, 15 + n * 15, 10 + n * 10, 100);
      strokeWeight(1);
      point(px, py);
    }
  } else {
    // Dissolving branches - drawn as particles
    let steps = int(len / 2);
    for (let i = 0; i < steps; i++) {
      let t = i / steps;
      let px = lerp(x, endX, t);
      let py = lerp(y, endY, t);
      // Dissolution increases toward tips
      let dissolution = map(depth, 4, 0, 0, 1) + t * 0.5;
      dissolution = constrain(dissolution, 0, 1);

      if (random() > dissolution * 0.7) {
        let scatter = dissolution * 8;
        noStroke();
        fill(40, 25, 20, map(dissolution, 0, 1, 180, 30));
        let s = w * (1 - dissolution * 0.5);
        ellipse(px + random(-scatter, scatter), py + random(-scatter, scatter), s, s);
      }

      // Some particles fly off as proto-birds
      if (dissolution > 0.3 && random() > 0.85) {
        let flyX = px + random(-30, 30);
        let flyY = py + random(-40, -5);
        let birdSize = random(3, 8);
        drawBird(flyX, flyY, birdSize, dissolution * 0.5);
      }
    }
  }

  // Branching
  let branches = depth > 8 ? 2 : (random() > 0.7 ? 3 : 2);

  for (let i = 0; i < branches; i++) {
    let newAngle = angle + random(-0.6, 0.6);
    // Tendency to go upward
    if (depth > 6) newAngle = angle + random(-0.4, 0.4);

    let newLen = len * random(0.6, 0.8);
    let branchDepth = depth - 1;

    // Some branches are dead/broken (shorter)
    if (random() > 0.8 && depth < 8) {
      newLen *= 0.4;
      branchDepth = max(0, branchDepth - 2);
    }

    drawTree(endX, endY, newAngle, newLen, branchDepth);
  }
}

function drawRoots(x, y, depth) {
  if (depth <= 0) return;

  let numRoots = depth > 6 ? 4 : (random() > 0.5 ? 3 : 2);

  for (let i = 0; i < numRoots; i++) {
    let angle = random(PI * 0.1, PI * 0.9); // Downward
    let len = random(40, 120) * (depth / 8);
    let endX = x + cos(angle) * len;
    let endY = y + sin(angle) * len;

    let w = map(depth, 0, 8, 1, 10);

    // Root color with bioluminescent hints
    let glowN = noise(endX * 0.01, endY * 0.01 + 500);
    let r = 25 + glowN * 15;
    let g = 18 + glowN * 30;
    let b = 15 + glowN * 40;
    let a = map(depth, 0, 8, 80, 200);

    stroke(r, g, b, a);
    strokeWeight(w);
    noFill();

    // Curved roots
    beginShape();
    let steps = 10;
    for (let s = 0; s <= steps; s++) {
      let t = s / steps;
      let px = lerp(x, endX, t) + noise(s * 0.3 + i * 10, depth) * 20 - 10;
      let py = lerp(y, endY, t) + noise(s * 0.3 + i * 10 + 100, depth) * 15;
      curveVertex(px, py);
    }
    endShape();

    // Glow at root tips near water
    if (depth < 4 && endY > 1600) {
      noStroke();
      fill(30, 80, 120, 40);
      ellipse(endX, endY, 20, 20);
      fill(50, 120, 160, 20);
      ellipse(endX, endY, 35, 35);
    }

    drawRoots(endX, endY, depth - 1);
  }
}

function drawBird(x, y, s, formedness) {
  // formedness: 0 = just a dot/fragment, 1 = clear bird silhouette
  noStroke();

  let a = constrain(formedness * 200 + 30, 30, 220);

  if (formedness > 0.6) {
    // More formed bird
    fill(20, 15, 25, a);
    push();
    translate(x, y);
    let wingAngle = noise(x * 0.01, y * 0.01) * 0.4 + 0.1;
    // Body
    ellipse(0, 0, s * 0.6, s * 0.3);
    // Wings
    beginShape();
    vertex(0, 0);
    vertex(-s * 0.8, -s * wingAngle * 2);
    vertex(-s * 0.3, -s * 0.05);
    endShape(CLOSE);
    beginShape();
    vertex(0, 0);
    vertex(s * 0.8, -s * wingAngle * 2);
    vertex(s * 0.3, -s * 0.05);
    endShape(CLOSE);
    pop();
  } else if (formedness > 0.3) {
    // Semi-formed - V shape
    stroke(25, 18, 22, a);
    strokeWeight(max(1, s * 0.1));
    noFill();
    let wingSpan = s * 0.8;
    let wingDip = s * 0.2;
    line(x - wingSpan, y + wingDip, x, y);
    line(x, y, x + wingSpan, y + wingDip);
  } else {
    // Just a particle/fragment
    fill(30, 20, 25, a * 0.5);
    ellipse(x, y, s * 0.3, s * 0.3);
  }
}

let cnv;
function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // Sky gradient - deep indigo to bruised violet
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(12, 38, t);
    let g = lerp(14, 22, t);
    let b = lerp(38, 55, t);
    if (y > height * 0.62) {
      let t2 = (y - height*0.62) / (height*0.38);
      r = lerp(38, 8, t2);
      g = lerp(22, 10, t2);
      b = lerp(55, 18, t2);
    }
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Distant mist
  noStroke();
  for (let i = 0; i < 400; i++) {
    let x = random(width);
    let y = random(height*0.45, height*0.65);
    fill(180, 170, 180, random(2, 10));
    ellipse(x, y, random(200, 500), random(20, 60));
  }

  // Moon - pale, low
  let mx = width*0.68, my = height*0.32;
  for (let r = 240; r > 0; r -= 4) {
    let a = map(r, 240, 0, 0, 40);
    fill(230, 225, 210, a);
    ellipse(mx, my, r*2);
  }
  fill(240, 235, 220);
  ellipse(mx, my, 160);
  fill(220, 215, 200);
  ellipse(mx-10, my+8, 150);

  // Horizon line - dark shore of water
  let horizonY = height * 0.62;

  // Water reflections
  noStroke();
  for (let i = 0; i < 300; i++) {
    let y = random(horizonY, height);
    let x = random(width);
    let t = (y - horizonY) / (height - horizonY);
    let w = random(30, 180) * (1 + t);
    fill(200, 195, 185, random(5, 25) * (1-t*0.7));
    ellipse(x, y, w, 2);
  }

  // Moon reflection shimmer
  for (let i = 0; i < 80; i++) {
    let y = random(horizonY, height*0.95);
    let t = (y - horizonY) / (height - horizonY);
    let w = random(40, 220);
    fill(230, 225, 210, random(10, 50) * (1-t*0.5));
    ellipse(mx + random(-40, 40), y, w, 2);
  }

  // Dark far shore / trees silhouette
  fill(6, 8, 18);
  beginShape();
  vertex(0, horizonY);
  for (let x = 0; x <= width; x += 8) {
    let n = noise(x*0.004, 10) * 60;
    let spikes = 0;
    if (noise(x*0.01, 20) > 0.55) spikes = noise(x*0.02, 30) * 120;
    vertex(x, horizonY - n - spikes + 20);
  }
  vertex(width, horizonY);
  endShape(CLOSE);

  // Bare trees on shore
  for (let i = 0; i < 12; i++) {
    let tx = random(width);
    let th = random(80, 220);
    drawBareTree(tx, horizonY + 5, th);
  }

  // The boat - small, drifting
  let boatX = width * 0.42;
  let boatY = height * 0.78;
  drawBoat(boatX, boatY);

  // Figure lying in boat (shrouded)
  push();
  translate(boatX, boatY);
  fill(220, 215, 200, 230);
  beginShape();
  vertex(-110, -8);
  bezierVertex(-90, -22, 90, -22, 110, -8);
  bezierVertex(100, -4, -100, -4, -110, -8);
  endShape(CLOSE);
  // subtle folds
  stroke(180, 175, 160, 120);
  strokeWeight(1);
  noFill();
  for (let i = -90; i < 90; i += 15) {
    line(i, -12, i+5, -8);
  }
  noStroke();
  pop();

  // Ferryman - tall dark figure standing
  drawFerryman(boatX + 95, boatY - 15);

  // Lilies / pale flowers on water surface
  for (let i = 0; i < 25; i++) {
    let x = random(width);
    let y = random(horizonY + 20, height - 40);
    let s = map(y, horizonY, height, 0.3, 1.2);
    drawLily(x, y, s);
  }

  // The moth - luminous, rising
  drawMoth(width*0.55, height*0.45, 1);

  // Smaller moths ascending
  drawMoth(width*0.48, height*0.38, 0.5);
  drawMoth(width*0.6, height*0.28, 0.35);
  drawMoth(width*0.52, height*0.2, 0.25);

  // Grain / atmosphere
  for (let i = 0; i < 8000; i++) {
    let x = random(width), y = random(height);
    fill(255, random(3, 15));
    rect(x, y, 1, 1);
  }
  for (let i = 0; i < 4000; i++) {
    let x = random(width), y = random(height);
    fill(0, random(5, 20));
    rect(x, y, 1, 1);
  }

  // Vignette
  for (let r = 0; r < 600; r += 4) {
    noFill();
    stroke(0, map(r, 0, 600, 60, 0));
    strokeWeight(4);
    ellipse(width/2, height/2, width*1.4 + r, height*1.4 + r);
  }
}

function drawBareTree(x, baseY, h) {
  stroke(4, 6, 14);
  strokeWeight(2);
  noFill();
  drawBranch(x, baseY, -PI/2, h, 4);
  noStroke();
}

function drawBranch(x, y, angle, len, depth) {
  if (depth <= 0 || len < 4) return;
  let x2 = x + cos(angle)*len;
  let y2 = y + sin(angle)*len;
  strokeWeight(depth);
  line(x, y, x2, y2);
  drawBranch(x2, y2, angle - random(0.2, 0.5), len*0.7, depth-1);
  drawBranch(x2, y2, angle + random(0.2, 0.5), len*0.7, depth-1);
  if (random() < 0.3) drawBranch(x2, y2, angle + random(-0.2, 0.2), len*0.6, depth-1);
}

function drawBoat(cx, cy) {
  noStroke();
  fill(10, 8, 15);
  beginShape();
  vertex(cx - 130, cy);
  bezierVertex(cx - 150, cy + 25, cx + 150, cy + 25, cx + 130, cy);
  vertex(cx + 115, cy + 4);
  bezierVertex(cx + 100, cy + 18, cx - 100, cy + 18, cx - 115, cy + 4);
  endShape(CLOSE);
  // waterline reflection
  fill(60, 55, 65, 80);
  ellipse(cx, cy + 28, 280, 10);
}

function drawFerryman(x, y) {
  noStroke();
  fill(4, 4, 10);
  // robe
  beginShape();
  vertex(x - 22, y);
  vertex(x - 35, y + 90);
  vertex(x + 35, y + 90);
  vertex(x + 22, y);
  endShape(CLOSE);
  // hood/head
  beginShape();
  vertex(x - 22, y);
  bezierVertex(x - 30, y - 50, x + 30, y - 50, x + 22, y);
  endShape(CLOSE);
  // pole
  stroke(20, 16, 14);
  strokeWeight(3);
  line(x + 15, y - 30, x + 55, y + 140);
  noStroke();
}

function drawLily(x, y, s) {
  push();
  translate(x, y);
  scale(s, s*0.5);
  noStroke();
  // pad
  fill(15, 25, 20, 180);
  ellipse(0, 0, 40, 28);
  // flower
  fill(230, 225, 215, 220);
  for (let i = 0; i < 5; i++) {
    push();
    rotate(i * TWO_PI/5);
    ellipse(0, -5, 6, 14);
    pop();
  }
  fill(240, 220, 160);
  ellipse(0, -2, 5, 5);
  pop();
}

function drawMoth(cx, cy, scl) {
  push();
  translate(cx, cy);
  scale(scl);
  noStroke();
  // glow
  for (let r = 180; r > 0; r -= 6) {
    fill(240, 230, 200, map(r, 180, 0, 0, 12));
    ellipse(0, 0, r*2);
  }
  // wings - pale, moth-like
  fill(235, 225, 205, 240);
  // upper wings
  beginShape();
  vertex(0, 0);
  bezierVertex(-80, -40, -90, 10, -10, 15);
  endShape(CLOSE);
  beginShape();
  vertex(0, 0);
  bezierVertex(80, -40, 90, 10, 10, 15);
  endShape(CLOSE);
  // lower wings
  fill(215, 205, 185, 230);
  beginShape();
  vertex(-5, 10);
  bezierVertex(-55, 25, -45, 55, -5, 35);
  endShape(CLOSE);
  beginShape();
  vertex(5, 10);
  bezierVertex(55, 25, 45, 55, 5, 35);
  endShape(CLOSE);
  // wing spots
  fill(90, 70, 80, 180);
  ellipse(-40, -5, 10, 14);
  ellipse(40, -5, 10, 14);
  // body
  fill(30, 25, 30);
  ellipse(0, 10, 8, 40);
  // head
  ellipse(0, -8, 9, 9);
  // antennae
  stroke(30, 25, 30);
  strokeWeight(1);
  noFill();
  bezierVertex;
  line(0, -10, -10, -22);
  line(0, -10, 10, -22);
  noStroke();
  pop();
}

