  // The wading figure - silhouette
  let fx=700, fy=1500;
  noStroke();
  // reflection first
  push();
  fill(10,8,20,180);
  // reflected body
  ellipse(fx,fy+260,70,30);
  for(let i=0;i<40;i++){
