  bezierVertex(fx+60,1540, fx-60,1540, fx-80,1520);
  endShape(CLOSE);

  // Faint head highlight - bone pale
  fill(200,180,160,80);
  ellipse(fx,1150,50,70);
  fill(230,210,185,40);
