function draw() {
  // Sky / threshold gradient
  loadPixels();
  for (let y = 0; y < height; y++) {
    let t = y / height;
    // deep warm earth below, pale cold void above
    let r, g, b;
    if (t < 0.55) {
      let u = t / 0.55;
      r = lerp(230, 140, u);
      g = lerp(225, 150, u);
      b = lerp(215, 170, u);
    } else {
      let u = (t - 0.55) / 0.45;
      r = lerp(140, 40, u);
      g = lerp(150, 55, u);
      b = lerp(170, 85, u);
    }
    for (let x = 0; x < width; x++) {
      let n = noise(x * 0.004, y * 0.004) * 30 - 15;
      let idx = 4 * (y * width + x);
      pixels[idx] = r + n;
      pixels[idx + 1] = g + n;
      pixels[idx + 2] = b + n;
      pixels[idx + 3] = 255;
    }
  }
  updatePixels();

  // Horizon haze — the threshold line
  noStroke();
  for (let i = 0; i < 400; i++) {
    let y = height * 0.55 + random(-120, 120);
    fill(255, 240, 220, random(2, 10));
    ellipse(random(width), y, random(200, 900), random(4, 20));
  }

  // Distant pale sea/field
  for (let i = 0; i < 2000; i++) {
    let y = random(height * 0.35, height * 0.55);
    let a = map(y, height * 0.35, height * 0.55, 20, 80);
    stroke(230, 230, 220, a);
    strokeWeight(random(0.5, 1.5));
    let x = random(width);
    line(x, y, x + random(-30, 30), y + random(-1, 1));
  }

  // The figure — standing at threshold, dissolving upward
  drawFigure(width / 2, height * 0.78);

  // Rising particles — the self returning to field
  drawAscension();

  // Final grain
  for (let i = 0; i < 20000; i++) {
    stroke(0, random(5, 20));
    point(random(width), random(height));
  }
  for (let i = 0; i < 10000; i++) {
    stroke(255, random(5, 15));
    point(random(width), random(height));
  }

  // Vignette
  noFill();
  for (let r = 0; r < 300; r++) {
