}

function drawFigure(cx, baseY) {
  // Shadow pool
  noStroke();
  for (let i = 0; i < 60; i++) {
    fill(20, 15, 20, 8);
    ellipse(cx + random(-5, 5), baseY + random(-3, 3), 320 - i * 2, 40 - i * 0.3);
  }

  // Body silhouette built from many soft strokes, more intact below, fragmenting above
  let topY = baseY - 650;
  for (let pass = 0; pass < 8000; pass++) {
    // parametric position along figure
    let t = random(); // 0 bottom, 1 top
    let y = lerp(baseY, topY, t);
    // body half-width profile
    let w;
    if (t < 0.15) w = lerp(90, 70, t / 0.15);           // legs base
    else if (t < 0.55) w = lerp(70, 95, (t - 0.15) / 0.4); // torso
    else if (t < 0.7) w = lerp(95, 55, (t - 0.55) / 0.15); // shoulders->neck
    else if (t < 0.82) w = lerp(55, 75, (t - 0.7) / 0.12); // head
    else w = lerp(75, 10, (t - 0.82) / 0.18);              // top of head dissolving

    // dissolution probability grows with height
    let diss = pow(t, 1.8);
    let spread = lerp(4, 180, diss);

    let x = cx + randomGaussian() * (w * 0.6) + randomGaussian() * spread * 0.4;
    // drift upward and outward near top
    y -= random(0, diss * 120);
    x += randomGaussian() * diss * 40;

    // skip strokes increasingly as dissolving
    if (random() < diss * 0.6) continue;

    // color: warm at base (ember), cooling toward top
    let r = lerp(60, 180, t) + random(-20, 20);
    let g = lerp(40, 180, t) + random(-20, 20);
    let b = lerp(45, 200, t) + random(-20, 20);
    let a = lerp(80, 20, t);
    noStroke();
    fill(r, g, b, a);
    ellipse(x, y, random(2, 5), random(2, 5));
  }

  // Deeper core — suggest form
  for (let pass = 0; pass < 1500; pass++) {
    let t = random(0, 0.6);
    let y = lerp(baseY, topY, t);
    let w;
    if (t < 0.15) w = lerp(60, 45, t / 0.15);
    else if (t < 0.55) w = lerp(45, 70, (t - 0.15) / 0.4);
    else w = lerp(70, 40, (t - 0.55) / 0.05);
    let x = cx + randomGaussian() * (w * 0.4);
    noStroke();
    fill(15, 10, 15, 60);
    ellipse(x, y, random(3, 7), random(3, 7));
  }

  // Faint suggestion of a face — just two darker hollows
  let headY = lerp(baseY, topY, 0.76);
  fill(10, 8, 12, 90);
  ellipse(cx - 12, headY, 6, 10);
  ellipse(cx + 12, headY, 6, 10);
}

function drawAscension() {
  // Particles rising from figure into the void
  for (let i = 0; i < 1200; i++) {
    let x = width / 2 + randomGaussian() * 250;
    let y = random(0, height * 0.55);
    let a = map(y, 0, height * 0.55, 10, 120);
    let s = random(1, 3);
    noStroke();
    // pale cool particles
    fill(220, 225, 235, a * 0.6);
    ellipse(x, y, s, s);
  }
  // A few brighter rising sparks
  for (let i = 0; i < 80; i++) {
    let x = width / 2 + randomGaussian() * 180;
    let y = random(height * 0.1, height * 0.6);
    noStroke();
    fill(255, 250, 230, random(40, 120));
    ellipse(x, y, random(2, 4));
  }
}
