    let n = random(-12, 12);
    pixels[idx]   = constrain(pixels[idx]   + n, 0, 255);
    pixels[idx+1] = constrain(pixels[idx+1] + n, 0, 255);
    pixels[idx+2] = constrain(pixels[idx+2] + n, 0, 255);
  }
  updatePixels();

  // --- The Threshold: a vertical luminous doorway ---
  let doorX = width / 2;
  let doorY = height * 0.52;
  let doorW = 340;
  let doorH = 1150;

