  noStroke();
  for (let r = 900; r > 0; r -= 6) {
    let a = map(r, 0, 900, 40, 0);
    fill(230, 220, 200, a);
    ellipse(doorX, doorY, r * 1.1, r * 1.8);
  }

  // The doorway itself — arched top
  for (let i = 0; i < doorW/2; i++) {
    let t = i / (doorW/2);
    let a = pow(1 - t, 1.4) * 255;
    fill(255, 248, 230, a);
    let w = doorW - i * 2;
    let h = doorH - i * 2;
    let x = doorX - w/2;
    let y = doorY - h/2;
    rect(x, y + w/2, w, h - w/2);
    arc(doorX, y + w/2, w, w, PI, TWO_PI);
  }

  // Bright threshold core
  fill(255, 253, 245, 255);
  let cw = 60;
  rect(doorX - cw/2, doorY - doorH/2 + cw/2, cw, doorH - cw/2);
  arc(doorX, doorY - doorH/2 + cw/2, cw, cw, PI, TWO_PI);

  // --- The ground: faint horizon ---
  noStroke();
  for (let y = height * 0.82; y < height; y++) {
