function drawDissolvingFigure(fx, fy) {
  noStroke();
  // Figure is built from many small dots; density decreases with height.
  // Base points define a simple standing silhouette.
  let topY = fy - 520;      // head top
  let headR = 55;
  let shoulderY = fy - 410;
  let shoulderW = 170;
  let hipY = fy - 180;
  let hipW = 130;
  let footY = fy;

  for (let i = 0; i < 9000; i++) {
    // random vertical position along figure
    let y = random(topY - 20, footY);
    let dissolve = map(y, footY, topY - 20, 0, 1); // 0 at feet, 1 at head
    // probability of a dot decreasing as we go up
    if (random() < pow(1 - dissolve, 1.6) * 0.9 + 0.05) {
      let w;
      if (y < shoulderY - 40) {
        // head region
        let hy = map(y, topY, shoulderY - 40, 0, 1);
        w = sqrt(max(0, 1 - pow(hy * 2 - 1, 2))) * headR;
      } else if (y < shoulderY + 20) {
        // neck/shoulder transition
        let t = map(y, shoulderY - 40, shoulderY + 20, 0, 1);
        w = lerp(headR * 0.4, shoulderW/2, t);
      } else if (y < hipY) {
        let t = map(y, shoulderY + 20, hipY, 0, 1);
        w = lerp(shoulderW/2, hipW/2, t);
      } else {
        let t = map(y, hipY, footY, 0, 1);
        w = lerp(hipW/2, hipW/2.4, t);
      }
      let x = fx + randomGaussian(0, w * 0.55);
      if (abs(x - fx) > w) continue;

      // color: ashen near top (warmer, lighter), dark near bottom
      let warmth = dissolve;
      let r = lerp(25, 240, warmth) + random(-15, 15);
      let g = lerp(22, 220, warmth) + random(-15, 15);
      let b = lerp(28, 190, warmth) + random(-15, 15);
      let a = lerp(230, 140, warmth);
      fill(r, g, b, a);
      ellipse(x, y, random(1.5, 3.5));
    }
  }

  // A few bright motes drifting off the head
  for (let i = 0; i < 300; i++) {
    let y = random(topY - 200, topY + 30);
    let x = fx + randomGaussian(0, 60);
    let a = map(y, topY - 200, topY + 30, 20, 180);
    fill(255, 240, 210, a);
    ellipse(x, y, random(1, 2.5));
  }
