function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  paint();
}

function paint() {
  // Sky gradient — pale, warm, dim
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(230, 180, t);
    let g = lerp(215, 160, t);
    let b = lerp(195, 150, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Soft horizon glow
  noStroke();
  for (let i = 0; i < 200; i++) {
    let a = map(i, 0, 200, 40, 0);
    fill(255, 240, 215, a);
    ellipse(width / 2, height * 0.62, 1800 - i * 6, 400 - i * 1.5);
  }

  // Distant pale horizon line
  stroke(210, 200, 185, 120);
  strokeWeight(1);
  line(0, height * 0.62, width, height * 0.62);

  // Ground — quiet shore, mirroring sky
  noStroke();
  for (let y = height * 0.62; y < height; y++) {
    let t = (y - height * 0.62) / (height * 0.38);
    let r = lerp(185, 95, t);
    let g = lerp(170, 85, t);
    let b = lerp(155, 80, t);
    fill(r, g, b);
    rect(0, y, width, 1);
  }

  // Subtle reflections / ripples on ground
  for (let i = 0; i < 400; i++) {
    let y = random(height * 0.62, height);
    let x = random(width);
    let len = random(20, 180);
    stroke(255, 240, 220, random(10, 40));
    strokeWeight(0.5);
    line(x, y, x + len, y);
  }

  // The figure — standing, dissolving upward and outward
  drawFigure(width / 2, height * 0.78);

  // Drifting particles — the unbinding
  drawParticles();

  // Final soft atmospheric wash
  noStroke();
  for (let i = 0; i < 5000; i++) {
    let x = random(width);
    let y = random(height);
    fill(255, 245, 225, random(3, 10));
    ellipse(x, y, random(1, 2.5));
  }
}

function drawFigure(cx, baseY) {
  noStroke();
  // Figure built from many small shapes, denser at base, sparser toward head/top
  let figHeight = 520;
  let topY = baseY - figHeight;

  for (let i = 0; i < 9000; i++) {
    // vertical position: more weight low
    let v = pow(random(), 0.6); // 0 = top, 1 = bottom
    let y = lerp(topY, baseY, 1 - v);

    // width profile (silhouette): head, shoulders, torso, legs
    let prof = silhouette(v);
    if (prof <= 0) continue;

    // horizontal scatter — more scatter near top (dissolving)
    let scatter = lerp(90, 4, v); // top dissolves wider
    let x = cx + randomGaussian() * (prof * 0.5 + scatter * (1 - v) * 0.4);
    // probability of existing decreases toward top
    if (random() > lerp(0.25, 1.0, v)) continue;

    // color: warm dust at bottom, luminous pale at top
    let r = lerp(255, 110, v);
    let g = lerp(235, 95, v);
    let b = lerp(200, 85, v);
    let a = lerp(80, 180, v);
    fill(r, g, b, a);
    ellipse(x, y, random(1.5, 4));
  }
}

function silhouette(v) {
  // v: 0 at top (head), 1 at bottom (feet)
  // returns half-width in pixels
  if (v < 0.12) {
    // head
    let t = v / 0.12;
    return 45 * sin(t * PI);
  } else if (v < 0.18) {
    // neck
    return 20;
  } else if (v < 0.45) {
    // shoulders → torso
    let t = (v - 0.18) / 0.27;
    return lerp(95, 70, t);
  } else if (v < 0.55) {
    // waist
    return lerp(70, 55, (v - 0.45) / 0.10);
  } else {
    // legs — slight taper
    let t = (v - 0.55) / 0.45;
    return lerp(60, 40, t);
  }
}

function drawParticles() {
  noStroke();
  // Particles rising and drifting to one side (the horizon)
  for (let i = 0; i < 2500; i++) {
    let originX = width / 2 + randomGaussian() * 60;
    let originY = random(height * 0.3, height * 0.78);
    // drift upward and toward horizon center
    let driftY = (height * 0.78 - originY);
    let x = originX + randomGaussian() * driftY * 0.25;
    let y = originY - random(0, 30);

    let lum = map(y, height * 0.78, height * 0.3, 160, 255);
    let a = map(y, height * 0.78, height * 0.3, 160, 20);
    fill(lum, lum * 0.95, lum * 0.85, a);
    ellipse(x, y, random(1, 3));
  }

  // A few brighter motes — individual souls of dust
  for (let i = 0; i < 300; i++) {
    let x = width / 2 + randomGaussian() * 300;
    let y = random(height * 0.35, height * 0.7);
    fill(255, 250, 230, random(80, 180));
    ellipse(x, y, random(2, 4.5));
  }
}
