  fill(5,7,12,180);
  beginShape();
  vertex(-280,5);
  bezierVertex(-260,60,-150,80,0,80);
  bezierVertex(150,80,260,60,280,5);
  endShape(CLOSE);
  fill(10,15,25,100);
  for(let i=0;i<40;i++){
    let y=random(10,120);
    rect(random(-270,270),y,random(20,80),1);
  }
  pop();

  // Passeur encapuchonné
  push();
  translate(W*0.5+80,H*0.68-5);
  noStroke();
  fill(5,6,10);
  // corps/robe
  beginShape();
  vertex(-50,0);
  bezierVertex(-60,-80,-55,-180,-40,-240);
  bezierVertex(-35,-280,-20,-310,0,-320);
  bezierVertex(20,-310,35,-280,40,-240);
  bezierVertex(55,-180,60,-80,50,0);
  endShape(CLOSE);
  // capuche
  fill(2,3,6);
  beginShape();
  vertex(-45,-260);
  bezierVertex(-50,-310,-30,-350,0,-355);
  bezierVertex(30,-350,50,-310,45,-260);
  bezierVertex(30,-280,-30,-280,-45,-260);
  endShape(CLOSE);
  // ombre visage
  fill(0,0,0);
  ellipse(0,-305,50,60);

  // rame
  stroke(15,18,25);
  strokeWeight(6);
  line(30,-200,180,100);
  noStroke();
  fill(15,18,25);
  ellipse(180,100,40,15);
  pop();

  // Deuxième silhouette assise — l'âme
  push();
  translate(W*0.5-120,H*0.68-5);
  noStroke();
  fill(20,25,40,220);
  beginShape();
  vertex(-30,0);
  bezierVertex(-40,-60,-35,-120,-20,-150);
  bezierVertex(-10,-165,10,-165,20,-150);
  bezierVertex(35,-120,40,-60,30,0);
  endShape(CLOSE);
  // tête inclinée
  fill(25,30,45,230);
  ellipse(-5,-165,35,40);
  pop();

  // Particules — âmes qui s'élèvent
  noStroke();
  for(let i=0;i<60;i++){
    let x=W*0.5+random(-400,400);
    let y=random(H*0.3,H*0.65);
    let s=random(2,5);
    let a=random(80,180);
    fill(240,220,180,a);
    ellipse(x,y,s,s);
    fill(240,220,180,a*0.3);
    ellipse(x,y,s*3,s*3);
  }

  // Brume basse finale
  for(let i=0;i<5000;i++){
    let x=random(W);
    let y=H*0.6+random(-40,40)+noise(x*0.002)*30;
    fill(180,170,160,15);
    ellipse(x,y,random(5,20));
  }

  // Vignette
  for(let i=0;i<150;i++){
    noFill();
    stroke(0,0,0,4);
    strokeWeight(i*2);
    rect(i,i,W-i*2,H-i*2);
  }

  // Grain
  noStroke();
  for(let i=0;i<20000;i++){
    fill(random(255),random(20));
    rect(random(W),random(H),1,1);
  }
}

let cnv;
function setup() {
  cnv = createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // === CIEL ===
  // dégradé vertical lourd, cendré
  for (let y = 0; y < 1200; y++) {
    let t = y / 1200;
    let r = lerp(25, 95, t);
    let g = lerp(28, 90, t);
    let b = lerp(40, 85, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // halo lunaire / lueur lointaine
  let cx = 1050, cy = 520;
  noStroke();
  for (let r = 420; r > 0; r -= 4) {
    let a = map(r, 420, 0, 0, 55);
    fill(230, 225, 205, a);
    ellipse(cx, cy, r * 2, r * 1.6);
  }
  // disque pâle
  fill(240, 232, 210, 180);
  ellipse(cx, cy, 160, 160);
  fill(245, 238, 220, 220);
  ellipse(cx - 10, cy - 10, 110, 110);

  // nuages / brume horizontale
  for (let i = 0; i < 180; i++) {
    let y = random(200, 1150);
    let x = random(-200, width + 200);
    let w = random(300, 900);
    let h = random(25, 90);
    let a = random(10, 45);
    let c = random(60, 130);
    fill(c, c, c + 10, a);
    ellipse(x, y, w, h);
  }

  // brume basse près de l'eau
  for (let i = 0; i < 300; i++) {
    let y = random(1050, 1250);
    let x = random(-100, width + 100);
    let w = random(400, 1100);
    let h = random(15, 50);
    fill(180, 180, 175, random(8, 30));
    ellipse(x, y, w, h);
  }

  // === EAU ===
  for (let y = 1200; y < height; y++) {
    let t = (y - 1200) / (height - 1200);
    let r = lerp(35, 8, t);
    let g = lerp(38, 10, t);
    let b = lerp(48, 15, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // reflet de la lueur sur l'eau
  for (let i = 0; i < 400; i++) {
    let y = 1200 + pow(random(), 1.5) * 600;
    let xoff = random(-180, 180);
    let x = cx + xoff * (1 + (y - 1200) / 400);
    let w = random(20, 180);
    let a = map(y, 1200, 1800, 90, 0);
    stroke(230, 222, 200, a);
    strokeWeight(random(0.5, 1.8));
    line(x - w / 2, y, x + w / 2, y);
  }

  // ondulations horizontales
  noFill();
  for (let i = 0; i < 220; i++) {
    let y = 1210 + pow(random(), 1.3) * 780;
    let x1 = random(0, width);
    let len = random(40, 320);
    let a = map(y, 1200, 2000, 60, 20);
    stroke(150, 155, 165, a);
    strokeWeight(random(0.3, 1.2));
    let yy = y + sin(x1 * 0.01) * 2;
    line(x1, yy, x1 + len, yy + random(-1, 1));
  }

  // === BARQUE ===
  push();
  translate(600, 1420);
  // ombre sous la barque
  noStroke();
  fill(0, 0, 0, 120);
  ellipse(220, 90, 700, 50);

  // coque (forme allongée)
  fill(20, 18, 22);
  beginShape();
  vertex(0, 20);
  bezierVertex(60, 70, 380, 75, 450, 20);
  bezierVertex(430, 55, 380, 90, 220, 95);
  bezierVertex(100, 95, 40, 70, 0, 20);
  endShape(CLOSE);

  // rebord
  stroke(55, 50, 55);
  strokeWeight(2);
  noFill();
  beginShape();
  vertex(0, 20);
  bezierVertex(60, 55, 380, 60, 450, 20);
  endShape();

  // intérieur sombre
  noStroke();
  fill(10, 9, 12);
  beginShape();
  vertex(20, 25);
  bezierVertex(80, 50, 370, 55, 435, 25);
  bezierVertex(380, 65, 90, 65, 20, 25);
  endShape(CLOSE);
  pop();

  // === PASSEUR ===
  push();
  translate(820, 1180);

  // rame
  stroke(25, 20, 18);
  strokeWeight(7);
  line(-30, 20, 260, 310);
  // pale de la rame dans l'eau
  noStroke();
  fill(18, 15, 14);
  push();
  translate(260, 310);
  rotate(PI / 4);
  ellipse(0, 0, 60, 18);
  pop();

  // corps / robe sombre
  fill(8, 8, 12);
  beginShape();
  vertex(-80, 240);      // bas gauche
  bezierVertex(-90, 150, -70, 60, -40, 20);  // côté gauche montant
  bezierVertex(-20, -10, 20, -10, 40, 20);   // épaules / capuche
  bezierVertex(70, 60, 90, 150, 100, 240);   // côté droit
  bezierVertex(60, 250, -40, 250, -80, 240);
  endShape(CLOSE);

  // capuche (ombre intérieure, pas de visage)
  fill(0, 0, 0);
  beginShape();
  vertex(-25, 10);
  bezierVertex(-30, -5, -15, -18, 0, -18);
  bezierVertex(15, -18, 30, -5, 25, 10);
  bezierVertex(20, 35, -20, 35, -25, 10);
  endShape(CLOSE);

  // plis du vêtement
  stroke(20, 18, 22);
  strokeWeight(1.5);
  noFill();
  bezier(-40, 40, -55, 110, -60, 180, -55, 235);
  bezier(0, 30, 5, 110, 10, 180, 8, 240);
  bezier(40, 40, 55, 110, 65, 180, 70, 235);

  pop();

  // === DÉTAIL : vaguelettes autour de la barque ===
  stroke(180, 180, 180, 90);
  strokeWeight(1);
  noFill();
  for (let i = 0; i < 40; i++) {
    let x = 600 + random(-50, 500);
    let y = 1510 + random(-10, 40);
    line(x, y, x + random(20, 60), y + random(-1, 1));
  }

  // === GRAIN GÉNÉRAL ===
  noStroke();
  for (let i = 0; i < 9000; i++) {
    let x = random(width);
    let y = random(height);
    let a = random(5, 25);
    fill(0, 0, 0, a);
    rect(x, y, 1, 1);
  }
  for (let i = 0; i < 4000; i++) {
    let x = random(width);
    let y = random(height);
    let a = random(5, 20);
    fill(255, 250, 230, a);
    rect(x, y, 1, 1);
  }

  // vignette
  for (let r = 0; r < 400; r += 4) {
    noFill();
    stroke(0, 0, 0, map(r, 0, 400, 80, 0));
    strokeWeight(4);
    rect(r / 2, r / 2, width - r, height - r);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Ciel dégradé crépusculaire
  for (let y = 0; y < 1200; y++) {
    let t = y / 1200;
    let r = lerp(40, 180, pow(t, 1.3));
    let g = lerp(30, 130, pow(t, 1.5));
    let b = lerp(55, 110, pow(t, 0.8));
    stroke(r, g, b);
    line(0, y, 1600, y);
  }

  // Brume / nuages
  noStroke();
  for (let i = 0; i < 400; i++) {
    let x = random(1600);
    let y = random(200, 1150);
    let w = random(200, 600);
    let h = random(20, 70);
    let a = noise(x * 0.002, y * 0.003) * 80;
    fill(220, 200, 170, a);
    ellipse(x, y, w, h);
  }

  // Halo lunaire
  let mx = 1150, my = 500;
  for (let r = 300; r > 0; r -= 4) {
    let a = map(r, 0, 300, 90, 0);
    fill(240, 220, 180, a);
    ellipse(mx, my, r * 2, r * 2);
  }
  fill(245, 235, 210);
  ellipse(mx, my, 160, 160);

  // Reflets dans le ciel sur l'eau
  for (let y = 1200; y < 2000; y++) {
    let t = (y - 1200) / 800;
    let r = lerp(60, 15, t);
    let g = lerp(55, 15, t);
    let b = lerp(75, 25, t);
    stroke(r, g, b);
    line(0, y, 1600, y);
  }

  // Reflet de la lune sur l'eau
  noStroke();
  for (let i = 0; i < 60; i++) {
    let y = 1200 + i * 10 + random(-3, 3);
    let w = 180 - i * 1.5 + random(-20, 20);
    let a = map(i, 0, 60, 120, 0);
    fill(240, 220, 180, a);
    ellipse(mx + random(-8, 8), y, w, 4);
  }

  // Ondulations de l'eau
  stroke(180, 170, 150, 25);
  strokeWeight(1);
  for (let i = 0; i < 300; i++) {
    let y = random(1210, 2000);
    let x1 = random(1600);
    let len = random(30, 180);
    let a = map(y, 1210, 2000, 60, 10);
    stroke(200, 190, 170, a);
    line(x1, y, x1 + len, y + random(-1, 1));
  }

  // Ligne d'horizon - montagnes lointaines
  noStroke();
  fill(25, 25, 45);
  beginShape();
  vertex(0, 1200);
  for (let x = 0; x <= 1600; x += 10) {
    let y = 1200 - noise(x * 0.003) * 80 - 20;
    vertex(x, y);
  }
  vertex(1600, 1200);
  endShape(CLOSE);

  fill(15, 15, 30);
  beginShape();
  vertex(0, 1210);
  for (let x = 0; x <= 1600; x += 8) {
    let y = 1210 - noise(x * 0.006 + 100) * 40;
    vertex(x, y);
  }
  vertex(1600, 1210);
  endShape(CLOSE);

  // Barque
  let bx = 700, by = 1340;
  fill(10, 8, 15);
  beginShape();
  vertex(bx - 220, by);
  bezierVertex(bx - 180, by + 50, bx + 180, by + 50, bx + 220, by);
  bezierVertex(bx + 150, by - 10, bx - 150, by - 10, bx - 220, by);
  endShape(CLOSE);

  // Reflet de la barque
  fill(10, 8, 15, 120);
  beginShape();
  vertex(bx - 200, by + 8);
  bezierVertex(bx - 160, by + 40, bx + 160, by + 40, bx + 200, by + 8);
  endShape(CLOSE);

  // Silhouette voilée - le passeur
  push();
  translate(bx + 30, by);
  fill(8, 8, 18);
  // robe
  beginShape();
  vertex(-90, 0);
  bezierVertex(-110, -120, -100, -280, -70, -340);
  bezierVertex(-60, -380, -40, -400, -20, -410);
  vertex(20, -410);
  bezierVertex(40, -400, 60, -380, 70, -340);
  bezierVertex(100, -280, 110, -120, 90, 0);
  endShape(CLOSE);

  // Capuche
  fill(5, 5, 12);
  beginShape();
  vertex(-55, -340);
  bezierVertex(-70, -400, -40, -445, 0, -445);
  bezierVertex(40, -445, 70, -400, 55, -340);
  bezierVertex(40, -360, -40, -360, -55, -340);
  endShape(CLOSE);

  // Ombre du visage
  fill(0, 0, 0, 200);
  ellipse(0, -395, 55, 70);

  // Bras tendu portant la lumière
  fill(8, 8, 18);
  beginShape();
  vertex(30, -340);
  bezierVertex(80, -350, 140, -340, 170, -310);
  bezierVertex(160, -295, 150, -290, 140, -290);
  bezierVertex(100, -300, 60, -310, 30, -310);
  endShape(CLOSE);

  // Lumière / âme dans la main
  let lx = 175, ly = -310;
  for (let r = 120; r > 0; r -= 2) {
    let a = map(r, 0, 120, 180, 0);
    fill(255, 230, 170, a * 0.4);
    ellipse(lx, ly, r * 2, r * 2);
  }
  fill(255, 245, 210);
  ellipse(lx, ly, 30, 30);
  fill(255, 255, 240);
  ellipse(lx, ly, 14, 14);

  // Plis de la robe
  stroke(20, 18, 30, 180);
  strokeWeight(2);
  noFill();
  for (let i = 0; i < 8; i++) {
    let px = -70 + i * 20;
    beginShape();
    for (let y = -300; y < 0; y += 10) {
      let ox = sin(y * 0.02 + i) * 4;
      vertex(px + ox, y);
    }
    endShape();
  }
  pop();

  // Rame
  stroke(15, 12, 20);
  strokeWeight(6);
  line(bx - 80, by - 350, bx - 180, by + 40);
  noStroke();
  fill(15, 12, 20);
  ellipse(bx - 185, by + 50, 40, 15);

  // Particules de lumière flottantes (âmes)
  noStroke();
  for (let i = 0; i < 40; i++) {
    let px = random(1600);
    let py = random(400, 1300);
    let s = random(2, 6);
    let a = random(100, 200);
    fill(255, 230, 180, a);
    ellipse(px, py, s, s);
    fill(255, 230, 180, a * 0.3);
    ellipse(px, py, s * 3, s * 3);
  }

  // Brume basse sur l'eau
  for (let i = 0; i < 200; i++) {
    let x = random(1600);
    let y = random(1200, 1400);
    let w = random(150, 400);
    fill(180, 170, 160, 15);
    ellipse(x, y, w, 20);
  }

  // Vignettage
  for (let r = 1200; r > 700; r -= 5) {
    let a = map(r, 700, 1200, 0, 120);
    fill(0, 0, 10, a * 0.05);
    ellipse(800, 1000, r * 2.5, r * 2.5);
  }

  // Coins sombres
  for (let i = 0; i < 4; i++) {
    push();
    let cx = (i % 2) * 1600;
    let cy = floor(i / 2) * 2000;
    for (let r = 800; r > 0; r -= 10) {
      fill(0, 0, 5, 1.2);
      ellipse(cx, cy, r * 2, r * 2);
    }
    pop();
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Ciel dégradé : bleu nuit profond vers ocre pâle à l'horizon
  for (let y = 0; y < 1200; y++) {
    let t = y / 1200;
    let r = lerp(12, 160, pow(t, 1.8));
    let g = lerp(14, 130, pow(t, 1.8));
    let b = lerp(32, 95, pow(t, 1.6));
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Brume stellaire / poussière dans le ciel
  noStroke();
  for (let i = 0; i < 1200; i++) {
    let x = random(width);
    let y = random(0, 1100);
    let a = random(10, 60);
    fill(230, 210, 170, a);
    circle(x, y, random(0.5, 2.5));
  }

  // Halo lunaire / lumière pâle à l'horizon
  let cx = 1050, cy = 1050;
  for (let r = 420; r > 0; r -= 2) {
    let a = map(r, 0, 420, 90, 0);
    fill(240, 225, 180, a);
    circle(cx, cy, r * 2);
  }
  fill(250, 240, 210, 230);
  circle(cx, cy, 180);

  // Reflet du halo sur l'eau
  for (let i = 0; i < 80; i++) {
    let y = 1200 + i * 8;
    let w = 300 - i * 2.5;
    if (w < 0) break;
    let a = map(i, 0, 80, 110, 0);
    fill(240, 220, 170, a);
    ellipse(cx, y, w, 6);
  }

  // Eau noire
  for (let y = 1200; y < height; y++) {
    let t = (y - 1200) / (height - 1200);
    let r = lerp(18, 4, t);
    let g = lerp(20, 5, t);
    let b = lerp(30, 8, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Ondulations sur l'eau
  noFill();
  for (let i = 0; i < 400; i++) {
    let y = random(1210, height);
    let x = random(width);
    let w = random(20, 180);
    let t = map(y, 1200, height, 0, 1);
    let a = lerp(80, 15, t);
    stroke(180, 160, 120, a * random(0.3, 1));
    strokeWeight(random(0.3, 1.2));
    line(x, y, x + w, y + random(-1, 1));
  }

  // Brume basse sur l'eau
  noStroke();
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = 1180 + random(-30, 60);
    let s = random(40, 180);
    fill(180, 170, 150, random(5, 20));
    ellipse(x, y, s, s * 0.3);
  }

  // Montagnes lointaines sombres
  fill(15, 18, 30);
  beginShape();
  vertex(0, 1200);
  let mx = 0;
  while (mx < width) {
    let h = 1100 + noise(mx * 0.003) * 120 - 60;
    vertex(mx, h);
    mx += 20;
  }
  vertex(width, 1200);
  endShape(CLOSE);

  // Deuxième ligne de collines plus proche
  fill(8, 10, 20);
  beginShape();
  vertex(0, 1210);
  mx = 0;
  while (mx < width) {
    let h = 1170 + noise(mx * 0.005 + 100) * 70;
    vertex(mx, h);
    mx += 15;
  }
  vertex(width, 1210);
  endShape(CLOSE);

  // Barque au premier plan
  drawBoat(600, 1450);

  // Silhouettes : le passeur et le corps
  drawFerryman(720, 1270);
  drawBody(520, 1420);

  // Dissolution : particules qui s'élèvent du corps vers le ciel
  for (let i = 0; i < 600; i++) {
    let t = random();
    let x = 540 + random(-30, 150) + sin(t * 10) * 20 * t;
    let y = 1400 - t * 900;
    let a = lerp(180, 0, t);
    let sz = lerp(3, 0.5, t);
    fill(230, 210, 170, a);
    noStroke();
    circle(x, y, sz);
  }

  // Grain / texture générale pour unifier
  for (let i = 0; i < 25000; i++) {
    let x = random(width);
    let y = random(height);
    let a = random(5, 25);
    fill(random(200, 240), random(190, 220), random(160, 200), a);
    noStroke();
    rect(x, y, 1, 1);
  }

  // Vignette sombre
  for (let r = 0; r < 600; r += 2) {
    noFill();
    stroke(0, 0, 0, map(r, 0, 600, 60, 0));
    strokeWeight(2);
    rect(r, r, width - 2 * r, height - 2 * r);
  }
}

function drawBoat(x, y) {
  noStroke();
  // Coque
  fill(20, 15, 12);
  beginShape();
  vertex(x - 250, y);
  bezierVertex(x - 200, y + 70, x + 450, y + 70, x + 500, y);
  bezierVertex(x + 420, y + 20, x - 180, y + 20, x - 250, y);
  endShape(CLOSE);
  // Reflet sur la coque
  fill(60, 50, 35, 120);
  beginShape();
  vertex(x - 230, y - 2);
  bezierVertex(x - 180, y + 8, x + 420, y + 8, x + 470, y - 2);
  bezierVertex(x + 400, y + 2, x - 170, y + 2, x - 230, y - 2);
  endShape(CLOSE);
  // Rebord sombre
  fill(5, 3, 2);
  ellipse(x + 125, y + 2, 500, 10);
}

function drawFerryman(x, y) {
  noStroke();
  // Grande silhouette encapuchonnée
  fill(10, 8, 15);
  // Robe
  beginShape();
  vertex(x - 80, y + 180);
  bezierVertex(x - 110, y + 100, x - 60, y + 40, x - 30, y + 20);
  vertex(x - 20, y - 20);
  bezierVertex(x - 60, y - 60, x - 50, y - 130, x, y - 150);
  bezierVertex(x + 50, y - 160, x + 90, y - 100, x + 70, y - 30);
  vertex(x + 80, y + 30);
  bezierVertex(x + 120, y + 70, x + 140, y + 130, x + 100, y + 180);
  endShape(CLOSE);
  // Capuchon ombre intérieure
  fill(0, 0, 0);
  ellipse(x + 10, y - 110, 70, 90);
  // Bras tenant la rame (vague)
  fill(12, 10, 18);
  beginShape();
  vertex(x + 60, y - 40);
  bezierVertex(x + 120, y - 60, x + 180, y - 40, x + 200, y);
  bezierVertex(x + 170, y + 10, x + 100, y, x + 70, y - 10);
  endShape(CLOSE);
  // Rame
  stroke(30, 22, 15);
  strokeWeight(6);
  line(x + 190, y - 10, x + 380, y + 240);
  noStroke();
  fill(25, 18, 12);
  ellipse(x + 385, y + 250, 50, 20);
}

function drawBody(x, y) {
  noStroke();
  // Corps allongé recouvert d'un linceul pâle
  fill(190, 175, 140);
  beginShape();
  vertex(x - 20, y);
  bezierVertex(x + 20, y - 25, x + 280, y - 15, x + 320, y - 5);
  bezierVertex(x + 310, y + 5, x + 30, y + 10, x - 20, y);
  endShape(CLOSE);
  // Ombres du linceul
  fill(130, 115, 85, 180);
  beginShape();
  vertex(x + 20, y - 5);
  bezierVertex(x + 80, y + 5, x + 200, y + 3, x + 300, y - 2);
  bezierVertex(x + 220, y + 8, x + 80, y + 10, x + 20, y - 5);
  endShape(CLOSE);
  // Bosses (tête, corps)
  fill(170, 155, 125);
  ellipse(x + 30, y - 10, 60, 25);
  ellipse(x + 140, y - 8, 90, 20);
  ellipse(x + 260, y - 5, 70, 15);
  // Zone qui se dissout (vers la droite/haut)
  for (let i = 0; i < 300; i++) {
    let px = x + random(100, 320);
    let py = y + random(-30, 5);
    let a = random(30, 150);
    fill(200, 185, 150, a);
    circle(px, py, random(1, 4));
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // --- CIEL : dégradé crépusculaire ---
  for (let y = 0; y < 1200; y++) {
    let t = y / 1200;
    let r = lerp(180, 40, t) + lerp(30, 0, t) * sin(t*3);
    let g = lerp(90, 25, t);
    let b = lerp(70, 55, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Halo rougeoyant à l'horizon
  noStroke();
  for (let i = 300; i > 0; i -= 2) {
    fill(220, 110, 70, 3);
    ellipse(width/2, 1200, i*6, i*1.5);
  }

  // Lune pâle
  for (let i = 60; i > 0; i--) {
    fill(230, 220, 200, 4);
    ellipse(1150, 450, i*4, i*4);
  }
  fill(240, 232, 215);
  ellipse(1150, 450, 140, 140);
  fill(200, 190, 170, 80);
  ellipse(1170, 440, 40, 30);
  ellipse(1130, 470, 25, 20);

  // Nuages diffus
  for (let i = 0; i < 40; i++) {
    let x = random(width);
    let y = random(200, 900);
    let w = random(200, 500);
    fill(30, 25, 40, random(20, 60));
    ellipse(x, y, w, w*0.25);
  }

  // --- EAU : miroir sombre ---
  for (let y = 1200; y < 2000; y++) {
    let t = (y - 1200) / 800;
    let r = lerp(35, 10, t);
    let g = lerp(30, 8, t);
    let b = lerp(45, 15, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Reflet de la lune
  noStroke();
  for (let i = 0; i < 30; i++) {
    fill(230, 220, 200, 8);
    let yy = 1210 + i*8;
    let ww = 120 - i*2 + random(-10, 10);
    ellipse(1150 + random(-5,5), yy, ww, 3);
  }

  // Reflet du halo
  for (let i = 0; i < 50; i++) {
    fill(180, 90, 60, 4);
    ellipse(width/2, 1210 + i*6, 400 - i*4, 2);
  }

  // Ondulations de l'eau
  stroke(60, 55, 70, 90);
  strokeWeight(1);
  for (let i = 0; i < 400; i++) {
    let y = random(1210, 2000);
    let x = random(width);
    let len = random(20, 120);
    let alpha = map(y, 1210, 2000, 100, 20);
    stroke(80, 75, 90, alpha);
    line(x, y, x + len, y);
  }

  // --- RIVE LOINTAINE avec lumière pâle ---
  noStroke();
  fill(20, 20, 35);
  beginShape();
  vertex(0, 1200);
  for (let x = 0; x <= width; x += 20) {
    let n = noise(x * 0.003) * 40;
    vertex(x, 1190 - n);
  }
  vertex(width, 1200);
  endShape(CLOSE);

  // Lumière lointaine
  for (let i = 80; i > 0; i--) {
    fill(255, 230, 180, 3);
    ellipse(400, 1180, i*3, i*2);
  }
  fill(255, 240, 200);
  ellipse(400, 1180, 20, 10);

  // Reflet de cette lumière
  for (let i = 0; i < 40; i++) {
    fill(255, 220, 170, 6);
    ellipse(400, 1210 + i*5, 60 - i, 2);
  }

  // --- BARQUE ---
  push();
  translate(900, 1420);
  fill(10, 8, 12);
  noStroke();
  beginShape();
  vertex(-220, 0);
  bezierVertex(-240, 30, -180, 50, -100, 55);
  vertex(180, 55);
  bezierVertex(240, 50, 250, 20, 220, 0);
  endShape(CLOSE);
  // Reflet barque
  fill(5, 4, 8, 180);
  beginShape();
  vertex(-200, 55);
  bezierVertex(-180, 90, 150, 95, 200, 55);
  endShape(CLOSE);
  pop();

  // --- LE PASSEUR (silhouette encapuchonnée) ---
  push();
  translate(920, 1180);
  noStroke();
  // Reflet dans l'eau (flou)
  push();
  translate(0, 480);
  scale(1, -0.7);
  fill(0, 0, 5, 120);
  beginShape();
  vertex(-70, 0);
  bezierVertex(-90, 60, -100, 140, -80, 240);
  vertex(80, 240);
  bezierVertex(100, 140, 90, 60, 70, 0);
  bezierVertex(60, -30, 30, -50, 0, -50);
  bezierVertex(-30, -50, -60, -30, -70, 0);
  endShape(CLOSE);
  pop();

  // Robe
  fill(5, 3, 8);
  beginShape();
  vertex(-75, 20);
  bezierVertex(-110, 90, -130, 180, -100, 240);
  vertex(100, 240);
  bezierVertex(130, 180, 110, 90, 75, 20);
  bezierVertex(60, -10, 30, -30, 0, -30);
  bezierVertex(-30, -30, -60, -10, -75, 20);
  endShape(CLOSE);

  // Capuche (ombre intérieure)
  fill(0, 0, 2);
  ellipse(0, -5, 70, 85);

  // Rame
  stroke(25, 20, 15);
  strokeWeight(6);
  line(60, 30, 280, -120);
  // Pale
  noStroke();
  fill(20, 15, 10);
  push();
  translate(280, -120);
  rotate(-0.6);
  ellipse(0, 0, 60, 18);
  pop();
  pop();

  // --- CORBEAUX S'ÉLEVANT ---
  noStroke();
  fill(0);
  for (let i = 0; i < 14; i++) {
    let bx = 600 + i * 40 + random(-30, 30);
    let by = 900 - i * 45 + random(-20, 20);
    let s = map(i, 0, 14, 1.2, 0.4);
    push();
    translate(bx, by);
    scale(s);
    rotate(random(-0.3, 0.3));
    // Ailes en V
    beginShape();
    vertex(-25, 0);
    quadraticVertex(-15, -8, 0, -2);
    quadraticVertex(15, -8, 25, 0);
    quadraticVertex(15, 2, 0, 0);
    quadraticVertex(-15, 2, -25, 0);
    endShape(CLOSE);
    pop();
  }

  // --- BRUME au-dessus de l'eau ---
  for (let i = 0; i < 300; i++) {
    let y = 1180 + random(-20, 80);
    let x = random(width);
    fill(180, 170, 170, random(5, 20));
    ellipse(x, y, random(80, 250), random(8, 20));
  }

  // --- GRAIN / TEXTURE globale ---
  for (let i = 0; i < 8000; i++) {
    let x = random(width);
    let y = random(height);
    fill(random(255), random(50, 150));
    rect(x, y, 1, 1);
  }

  // Vignettage
  for (let i = 0; i < 200; i++) {
    noFill();
    stroke(0, 0, 0, 3);
    strokeWeight(2);
    rect(i, i, width - i*2, height - i*2);
  }
}

let canvas;
function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Fond : dégradé vertical, terre profonde vers bleu laiteux
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(28, 190, pow(t, 1.4));
    let g = lerp(22, 200, pow(t, 1.3));
    let b = lerp(26, 210, pow(t, 1.1));
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Texture de bruit subtile sur toute la toile
  noStroke();
  for (let i = 0; i < 90000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.004, y * 0.004);
    let a = map(n, 0, 1, 0, 40);
    fill(255, 240, 220, a * 0.3);
    rect(x, y, 2, 2);
  }

  // Le seuil : ouverture lumineuse verticale, décalée
  let cx = width * 0.55;
  let cy = height * 0.42;
  let doorW = 280;
  let doorH = 900;

  // halo extérieur
  for (let r = 600; r > 0; r -= 4) {
    let alpha = map(r, 0, 600, 90, 0);
    fill(230, 235, 245, alpha);
    ellipse(cx, cy, r * 1.2, r * 2.1);
  }

  // noyau du seuil
  for (let r = doorW; r > 0; r -= 2) {
    let t = r / doorW;
    let col = lerp(255, 180, t);
    fill(col, col - 5, col - 15, 240 * (1 - t) + 20);
    ellipse(cx, cy, r, r * (doorH / doorW));
  }

  // coeur très lumineux
  fill(255, 253, 245, 255);
  ellipse(cx, cy, 90, 320);

  // Silhouette qui se dissout — en bas à gauche du seuil
  drawDissolvingFigure(cx - 180, cy + 180);

  // Particules de dissolution — flux vers le seuil
  drawParticles(cx - 180, cy + 180, cx, cy);

  // Sol / horizon suggéré
  noStroke();
  for (let i = 0; i < 20000; i++) {
    let x = random(width);
    let y = random(height * 0.75, height);
    let n = noise(x * 0.002, y * 0.002);
    fill(40 + n * 30, 35 + n * 25, 30 + n * 20, 60);
    rect(x, y, 3, 2);
  }

  // Voile atmosphérique final
  for (let i = 0; i < 300; i++) {
    noStroke();
    fill(200, 210, 220, 3);
    let y = random(height);
    rect(0, y, width, random(10, 80));
  }

  // Vignette douce
  for (let r = 0; r < 800; r += 8) {
    noFill();
    stroke(10, 8, 15, map(r, 0, 800, 60, 0));
    strokeWeight(10);
    rect(r, r, width - 2 * r, height - 2 * r);
  }
}

function drawDissolvingFigure(fx, fy) {
  noStroke();
  // La figure : ombre humaine stylisée, de plus en plus fragmentée vers le haut
  let bodyH = 700;
  let headR = 70;

  for (let i = 0; i < 25000; i++) {
    // position normalisée sur la silhouette
    let t = random(1); // 0 = bas, 1 = haut
    let bodyY = fy + bodyH * 0.5 - t * bodyH;
    let bodyW = 130 - t * 40;

    // cohérence silhouette
    let xOff = random(-bodyW / 2, bodyW / 2);

    // dissolution : plus t est grand, plus on s'écarte
    let dissolve = pow(t, 2.2);
    xOff += random(-1, 1) * dissolve * 180;
    let yOff = random(-1, 1) * dissolve * 60;

    // direction vers le seuil (haut-droite)
    xOff += dissolve * 120;
    yOff -= dissolve * 80;

    let x = fx + xOff;
    let y = bodyY + yOff;

    // tête
    if (t > 0.78) {
      let hx = fx + random(-headR, headR) + dissolve * 140;
      let hy = fy - bodyH * 0.5 + random(-headR, headR) - dissolve * 90;
      let d = dist(hx, hy, fx, fy - bodyH * 0.5);
      if (d < headR + dissolve * 100) {
        let alpha = map(dissolve, 0, 1, 220, 10);
        fill(20, 18, 25, alpha);
        rect(hx, hy, 2, 2);
      }
    } else {
      let alpha = map(dissolve, 0, 1, 230, 15);
      // Teinte : sombre en bas, claire en haut (se transforme en lumière)
      let r = lerp(25, 220, dissolve);
      let g = lerp(22, 225, dissolve);
      let b = lerp(28, 230, dissolve);
      fill(r, g, b, alpha);
      rect(x, y, 2, 2);
    }
  }
}

function drawParticles(fx, fy, tx, ty) {
  noStroke();
  for (let i = 0; i < 4000; i++) {
    let t = random(1);
    // interpolation courbe entre figure et seuil
    let px = lerp(fx, tx, t) + sin(t * PI * 2 + i) * 40 * (1 - abs(t - 0.5) * 2);
    let py = lerp(fy - 200, ty, t) + cos(t * PI * 3 + i * 0.3) * 30;
    px += random(-15, 15);
    py += random(-15, 15);
    let alpha = map(t, 0, 1, 180, 40) * random(0.3, 1);
    let shade = lerp(80, 255, t);
    fill(shade, shade - 5, shade - 15, alpha);
    let s = random(1, 3);
    rect(px, py, s, s);
  }

  // quelques particules plus lumineuses
  for (let i = 0; i < 800; i++) {
    let t = random(0.4, 1);
    let px = lerp(fx, tx, t) + random(-60, 60);
    let py = lerp(fy - 200, ty, t) + random(-50, 50);
    fill(255, 250, 230, random(40, 150));
    ellipse(px, py, random(1, 4), random(1, 4));
  }
}

let cnv;
function setup() {
  cnv = createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  pixelDensity(1);
}

function draw() {
  // Deep background - void
  background(8, 10, 18);

  // Vertical gradient - from deep void to warm horizon
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(5, 25, t);
    let g = lerp(8, 15, t);
    let b = lerp(20, 25, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // The corridor - perspective walls converging to the light
  let vpX = width / 2;
  let vpY = height * 0.45;

  // Ground mist
  for (let i = 0; i < 40000; i++) {
    let x = random(width);
    let y = random(height * 0.55, height);
    let d = dist(x, y, vpX, vpY);
    let a = map(d, 0, 1200, 0, 60);
    stroke(30, 25, 40, a);
    point(x, y);
  }

  // Corridor shadow walls - left and right
  // Use many thin dark polygons receding to vanishing point
  noStroke();
  for (let i = 0; i < 60; i++) {
    let t = i / 60;
    let edgeX_left = lerp(0, vpX - 180, t);
    let edgeX_right = lerp(width, vpX + 180, t);
    let yTop = lerp(0, vpY - 160, t);
    let yBot = lerp(height, vpY + 180, t);

    let shade = lerp(0, 35, t);
    fill(shade, shade * 0.9, shade * 1.1, 8);
    // left wall slab
    quad(0, yTop, edgeX_left, yTop, edgeX_left, yBot, 0, yBot);
    quad(width, yTop, edgeX_right, yTop, edgeX_right, yBot, width, yBot);
  }

  // Darken corridor edges more
  for (let i = 0; i < 25; i++) {
    let a = 12;
    fill(0, 0, 0, a);
    let m = i * 6;
    rect(0, 0, m, height);
    rect(width - m, 0, m, height);
  }

  // The threshold - a glowing portal of light
  // Big soft radial glow
  for (let r = 900; r > 0; r -= 2) {
    let a = map(r, 0, 900, 90, 0);
    let col = lerpColor(color(255, 230, 180), color(60, 40, 30), r / 900);
    col.setAlpha(a * 0.15);
    fill(col);
    ellipse(vpX, vpY, r * 1.4, r * 1.8);
  }

  // Core of the light - almost white
  for (let r = 260; r > 0; r -= 1) {
    let t = r / 260;
    let col = lerpColor(color(255, 250, 230), color(255, 200, 140), t);
    col.setAlpha(map(r, 0, 260, 255, 10));
    fill(col);
    ellipse(vpX, vpY, r * 0.9, r * 1.3);
  }

  // The archway / doorway shape - subtle darker frame around the light
  push();
  noFill();
  for (let i = 0; i < 40; i++) {
    stroke(20, 15, 25, 90 - i * 2);
    strokeWeight(1);
    let w = 360 + i * 4;
    let h = 520 + i * 6;
    // arched top rectangle
    beginShape();
    vertex(vpX - w/2, vpY + h/2);
    vertex(vpX - w/2, vpY - h/4);
    bezierVertex(vpX - w/2, vpY - h/2 - 60, vpX + w/2, vpY - h/2 - 60, vpX + w/2, vpY - h/4);
    vertex(vpX + w/2, vpY + h/2);
    endShape();
  }
  pop();

  // Figures dissolving - walking toward the light
  // Draw several silhouettes along the corridor, progressively smaller and more dispersed
  drawFigure(vpX - 320, height * 0.78, 1.0, 0.0);
  drawFigure(vpX + 280, height * 0.82, 0.95, 0.05);
  drawFigure(vpX - 140, height * 0.68, 0.55, 0.25);
  drawFigure(vpX + 120, height * 0.66, 0.5, 0.3);
  drawFigure(vpX - 60, height * 0.58, 0.3, 0.55);
  drawFigure(vpX + 50, height * 0.56, 0.28, 0.6);
  drawFigure(vpX - 20, height * 0.51, 0.18, 0.8);
  drawFigure(vpX + 15, height * 0.50, 0.17, 0.85);

  // Particles rising from figures - dissolution
  for (let i = 0; i < 8000; i++) {
    let x = vpX + random(-500, 500) * pow(random(), 2) * (random() < 0.5 ? -1 : 1);
    let y = random(height * 0.4, height * 0.95);
    let dCenter = dist(x, y, vpX, vpY);
    let n = noise(x * 0.004, y * 0.004);
    if (n > 0.45) {
      let a = map(dCenter, 0, 800, 180, 10);
      let warmth = map(dCenter, 0, 900, 1, 0);
      let r = lerp(80, 255, warmth);
      let g = lerp(70, 220, warmth);
      let b = lerp(90, 170, warmth);
      stroke(r, g, b, a * 0.6);
      strokeWeight(random(0.5, 1.8));
      point(x, y);
    }
  }

  // Light rays emanating
  push();
  blendMode(SCREEN);
  for (let i = 0; i < 80; i++) {
    let ang = random(TWO_PI);
    let len = random(300, 1400);
    let x2 = vpX + cos(ang) * len;
    let y2 = vpY + sin(ang) * len * 1.1;
    stroke(255, 230, 180, random(4, 14));
    strokeWeight(random(0.5, 2));
    line(vpX, vpY, x2, y2);
  }
  pop();

  // Floor reflection of light
  push();
  blendMode(SCREEN);
  for (let r = 600; r > 0; r -= 3) {
    let a = map(r, 0, 600, 40, 0);
    fill(255, 220, 170, a * 0.2);
    noStroke();
    ellipse(vpX, height * 0.92, r * 2.2, r * 0.3);
  }
  pop();

  // Floating ember particles near the light
  for (let i = 0; i < 400; i++) {
    let ang = random(TWO_PI);
    let rad = random(50, 600) * pow(random(), 1.5);
    let x = vpX + cos(ang) * rad * 0.8;
    let y = vpY + sin(ang) * rad;
    let bright = random(150, 255);
    noStroke();
    fill(bright, bright * 0.85, bright * 0.55, random(80, 200));
    ellipse(x, y, random(1, 3.5), random(1, 3.5));
  }

  // Overall soft vignette
  push();
  noFill();
  for (let i = 0; i < 180; i++) {
    stroke(0, 0, 10, 4);
    strokeWeight(1);
    rect(i, i, width - i * 2, height - i * 2);
  }
  pop();

  // Film grain
  for (let i = 0; i < 60000; i++) {
    stroke(255, random(5, 15));
    point(random(width), random(height));
  }
  for (let i = 0; i < 40000; i++) {
    stroke(0, random(10, 25));
    point(random(width), random(height));
  }
}

function drawFigure(cx, cy, scale, dissolve) {
  // A simple human silhouette - head + body - progressively dissolving
  let headR = 38 * scale;
  let bodyH = 180 * scale;
  let bodyW = 60 * scale;

  push();
  noStroke();
  // Base silhouette as scattered dots (dissolution)
  let density = lerp(600, 100, dissolve);
  for (let i = 0; i < density; i++) {
    // Head
    if (random() < 0.3) {
      let a = random(TWO_PI);
      let rr = random(headR);
      let px = cx + cos(a) * rr + random(-dissolve * 40, dissolve * 40);
      let py = cy - bodyH + sin(a) * rr + random(-dissolve * 40, dissolve * 40);
      let shade = lerp(15, 60, random());
      let warm = dissolve * 180;
      fill(shade + warm * 0.5, shade + warm * 0.4, shade + warm * 0.3, random(150, 230) * (1 - dissolve * 0.5));
      ellipse(px, py, random(1.5, 3.5));
    } else {
      // Body (tapered)
      let t = random();
      let w = bodyW * (1 - t * 0.3);
      let px = cx + random(-w/2, w/2) + random(-dissolve * 50, dissolve * 50);
      let py = cy - bodyH + headR + t * bodyH + random(-dissolve * 50, dissolve * 50);
      let shade = lerp(10, 50, random());
      let warm = dissolve * 180;
      fill(shade + warm * 0.5, shade + warm * 0.4, shade + warm * 0.3, random(140, 220) * (1 - dissolve * 0.5));
      ellipse(px, py, random(1.5, 3.5));
    }
  }
  pop();
}

let c;
function setup(){
  createCanvas(1600,2000);
  randomSeed(1); noiseSeed(1);
  noLoop();
}

function draw(){
  // --- Mur du fond : bleu-gris froid, pigmenté
  for(let y=0;y<height;y++){
    let t=y/height;
    let r=lerp(38,22,t);
    let g=lerp(44,30,t);
    let b=lerp(54,40,t);
    stroke(r,g,b);
    line(0,y,width,y);
  }
  // texture du mur
  noStroke();
  for(let i=0;i<60000;i++){
    let x=random(width), y=random(height);
    let n=noise(x*0.004,y*0.004);
    let v=(n-0.5)*30;
    fill(40+v,46+v,56+v,60);
    rect(x,y,1.5,1.5);
  }
  // taches d'humidité
  for(let i=0;i<40;i++){
    let x=random(width), y=random(height*0.7);
    let r=random(80,260);
    for(let j=0;j<40;j++){
      fill(25,28,34,6);
      ellipse(x+random(-20,20),y+random(-20,20),r,r*0.7);
    }
  }

  // --- Sol : plancher en perspective
  push();
  let horizon = height*0.55;
  // teinte du sol
  for(let y=horizon;y<height;y++){
    let t=(y-horizon)/(height-horizon);
    let r=lerp(28,58,t);
    let g=lerp(26,46,t);
    let b=lerp(30,42,t);
    stroke(r,g,b);
    line(0,y,width,y);
  }
  // lattes en perspective (point de fuite vers la porte)
  let vpX = width*0.5;
  let vpY = horizon;
  for(let i=-20;i<=20;i++){
    let xBottom = width/2 + i*110;
    stroke(15,14,18,180);
    strokeWeight(2);
    line(vpX,vpY,xBottom,height);
  }
  // lignes transversales du plancher
  for(let k=1;k<30;k++){
    let t = pow(k/30,2.2);
    let y = lerp(horizon,height,t);
    stroke(15,14,18,160);
    strokeWeight(1+ t*2);
    line(0,y,width,y);
  }
  // grain du bois
  noStroke();
  for(let i=0;i<40000;i++){
    let x=random(width), y=random(horizon,height);
    let n=noise(x*0.01,y*0.03);
    fill(20,18,22,n*80);
    rect(x,y,2,1);
  }
  pop();

  // --- Jonction mur/sol : plinthe ombrée
  noStroke();
  for(let y=0;y<30;y++){
    fill(10,10,14,200-y*6);
    rect(0,horizon+y,width,1);
  }

  // --- Porte entrouverte au centre, légèrement décentrée
  let doorCX = width*0.5;
  let doorTop = height*0.18;
  let doorBot = horizon;
  let doorW = 420;

  // cadre extérieur de la porte (chambranle sombre)
  fill(12,10,14);
  rect(doorCX-doorW/2-28, doorTop-28, doorW+56, doorBot-doorTop+28);

  // panneau de porte fermé (côté gauche, dans l'ombre)
  push();
  fill(18,16,20);
  let leftDoorW = doorW*0.55;
  rect(doorCX-doorW/2, doorTop, leftDoorW, doorBot-doorTop);
  // panneaux sculptés
  stroke(8,7,10); strokeWeight(3); noFill();
  rect(doorCX-doorW/2+20, doorTop+30, leftDoorW-40, (doorBot-doorTop)*0.45-30);
  rect(doorCX-doorW/2+20, doorTop+(doorBot-doorTop)*0.5, leftDoorW-40, (doorBot-doorTop)*0.45);
  pop();

  // ouverture lumineuse (fente)
  let openX = doorCX-doorW/2+leftDoorW;
  let openW = doorW - leftDoorW;

  // halo lumineux débordant sur le sol et le mur
  push();
  noStroke();
  for(let i=200;i>0;i--){
    let a = map(i,0,200,0,8);
    fill(255,230,170,a);
    ellipse(openX+openW/2, doorBot, openW*2 + i*4, 300 + i*2);
  }
  // halo vertical autour de la porte
  for(let i=300;i>0;i--){
    let a = map(i,0,300,0,4);
    fill(255,220,160,a);
    ellipse(openX+openW/2, (doorTop+doorBot)/2, openW*1.5+i*3, (doorBot-doorTop)+i*4);
  }
  pop();

  // la lumière elle-même dans l'embrasure
  push();
  // dégradé chaud dans l'ouverture
  for(let y=doorTop;y<doorBot;y++){
    let t=(y-doorTop)/(doorBot-doorTop);
    let r=lerp(255,250,t);
    let g=lerp(240,210,t);
    let b=lerp(200,150,t);
    stroke(r,g,b);
    line(openX,y,openX+openW,y);
  }
  // cœur plus intense
  noStroke();
  for(let i=0;i<60;i++){
    fill(255,250,230,6);
    ellipse(openX+openW*0.5, (doorTop+doorBot)*0.55, openW*0.9, (doorBot-doorTop)*0.9);
  }
  // particules de poussière dans la lumière
  for(let i=0;i<400;i++){
    let x = openX + random(openW);
    let y = random(doorTop,doorBot);
    fill(255,240,210,random(40,160));
    ellipse(x,y,random(1,3));
  }
  pop();

  // battant droit entrouvert (en perspective, vu de biais)
  push();
  fill(14,12,16);
  stroke(6,5,8); strokeWeight(2);
  // petit panneau incliné suggérant l'ouverture
  beginShape();
  vertex(openX+openW, doorTop);
  vertex(openX+openW+70, doorTop+20);
  vertex(openX+openW+70, doorBot-10);
  vertex(openX+openW, doorBot);
  endShape(CLOSE);
  // tranche éclairée du battant
  noStroke();
  fill(180,150,100,180);
  beginShape();
  vertex(openX+openW, doorTop);
  vertex(openX+openW+8, doorTop+6);
  vertex(openX+openW+8, doorBot-4);
  vertex(openX+openW, doorBot);
  endShape(CLOSE);
  pop();

  // ombre portée de la porte entrouverte sur le sol
  push();
  noStroke();
  fill(0,0,0,120);
  beginShape();
  vertex(openX+openW, doorBot);
  vertex(openX+openW+70, doorBot);
  vertex(openX+openW+200, doorBot+80);
  vertex(openX+openW-20, doorBot+40);
  endShape(CLOSE);
  pop();

  // flaque de lumière projetée sur le plancher
  push();
  noStroke();
  for(let i=80;i>0;i--){
    let a = map(i,0,80,0,6);
    fill(255,220,160,a);
    beginShape();
    let cx = openX+openW/2;
    vertex(cx - openW*0.4 - i*2, doorBot);
    vertex(cx + openW*0.4 + i*2, doorBot);
    vertex(cx + openW*1.2 + i*4, doorBot + 180 + i*2);
    vertex(cx - openW*1.2 - i*4, doorBot + 180 + i*2);
    endShape(CLOSE);
  }
  pop();

  // --- Vignettage général (froid, fermé)
  push();
  noStroke();
  for(let i=0;i<300;i++){
    fill(0,0,0,2);
    ellipse(width/2,height/2,width*2+i*3,height*2+i*3);
  }
  // obscurité des bords
  for(let i=0;i<width;i++){
    let d = min(i,width-i)/width;
    let a = map(d,0,0.25,180,0);
    if(a>0){ stroke(0,0,0,a); line(i,0,i,height); }
  }
  for(let j=0;j<height;j++){
    let d = min(j,height-j)/height;
    let a = map(d,0,0.2,160,0);
    if(a>0){ stroke(0,0,0,a); line(0,j,width,j); }
  }
  pop();

  // grain final
  noStroke();
  for(let i=0;i<30000;i++){
    fill(255,255,255,random(0,12));
    rect(random(width),random(height),1,1);
  }
  for(let i=0;i<30000;i++){
    fill(0,0,0,random(0,14));
    rect(random(width),random(height),1,1);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Fond : ténèbres profondes avec grain
  background(8, 6, 12);

  // Brume atmosphérique sombre
  for (let i = 0; i < 80000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.002, y * 0.002);
    let a = n * 40;
    stroke(20 + n * 15, 15 + n * 10, 25 + n * 20, a);
    point(x, y);
  }

  // Couloir : perspective centrale, point de fuite légèrement haut
  let vx = width / 2;
  let vy = height * 0.42;

  // Sol et murs du couloir — dégradé radial sombre vers une clarté centrale
  drawCorridor(vx, vy);

  // La porte entrouverte au fond
  drawDoor(vx, vy);

  // Halo lumineux qui sort de la porte
  drawHalo(vx, vy);

  // Particules de poussière suspendues dans la lumière
  drawDust(vx, vy);

  // Vignettage
  drawVignette();

  // Grain final
  drawGrain();
}

function drawCorridor(vx, vy) {
  // Murs latéraux en trapèzes concentriques
  for (let i = 60; i > 0; i--) {
    let t = i / 60;
    let w = lerp(20, width * 1.4, t);
    let h = lerp(20, height * 1.4, t);
    let x1 = vx - w / 2;
    let x2 = vx + w / 2;
    let y1 = vy - h * 0.45;
    let y2 = vy + h * 0.55;

    let shade = lerp(255, 15, t);
    let warmth = lerp(1.0, 0.6, t);

    noStroke();

    // Mur gauche
    fill(shade * 0.35 * warmth, shade * 0.3 * warmth, shade * 0.28 * warmth);
    quad(x1, y1, vx - lerp(8, 400, t), vy - lerp(8, 300, t),
         vx - lerp(8, 400, t), vy + lerp(8, 400, t), x1, y2);

    // Mur droit
    fill(shade * 0.33 * warmth, shade * 0.28 * warmth, shade * 0.26 * warmth);
    quad(x2, y1, vx + lerp(8, 400, t), vy - lerp(8, 300, t),
         vx + lerp(8, 400, t), vy + lerp(8, 400, t), x2, y2);

    // Plafond
    fill(shade * 0.2, shade * 0.18, shade * 0.22);
    quad(x1, y1, x2, y1,
         vx + lerp(8, 400, t), vy - lerp(8, 300, t),
         vx - lerp(8, 400, t), vy - lerp(8, 300, t));

    // Sol
    fill(shade * 0.28, shade * 0.24, shade * 0.22);
    quad(x1, y2, x2, y2,
         vx + lerp(8, 400, t), vy + lerp(8, 400, t),
         vx - lerp(8, 400, t), vy + lerp(8, 400, t));
  }

  // Texture irrégulière sur les murs — fissures, imperfections
  stroke(0, 0, 0, 120);
  strokeWeight(1);
  for (let i = 0; i < 400; i++) {
    let side = random() < 0.5 ? -1 : 1;
    let depth = random(0.1, 0.9);
    let sx = lerp(vx + side * 400, vx + side * 20, depth);
    let sy = vy + random(-200, 300) * (1 - depth);
    let len = random(10, 60) * (1 - depth);
    line(sx, sy, sx + random(-len, len), sy + random(-len, len));
  }
}

function drawDoor(vx, vy) {
  // Cadre sombre de la porte
  let dw = 110;
  let dh = 200;
  noStroke();
  fill(0, 0, 0);
  rect(vx - dw / 2 - 6, vy - dh / 2 - 6, dw + 12, dh + 12);

  // L'intérieur de la porte : ouverture asymétrique (entrouverte)
  // Partie fermée (sombre)
  fill(5, 4, 8);
  rect(vx - dw / 2, vy - dh / 2, dw * 0.35, dh);

  // Partie ouverte : lumière intense
  // Dégradé de lumière
  for (let i = 0; i < dh; i++) {
    let t = i / dh;
    let edge = sin(t * PI);
    let r = 255;
    let g = 245 - edge * 10;
    let b = 220 - edge * 30;
    fill(r, g, b, 255);
    rect(vx - dw / 2 + dw * 0.35, vy - dh / 2 + i, dw * 0.65, 1);
  }

  // Cœur blanc pur de la lumière
  for (let i = 0; i < 40; i++) {
    let a = map(i, 0, 40, 220, 0);
    fill(255, 255, 250, a);
    ellipse(vx + dw * 0.1, vy, dw * 0.5 + i * 0.5, dh * 0.95 + i * 0.6);
  }

  // Bord vertical de la porte entrouverte — fine arête lumineuse
  stroke(255, 250, 230, 200);
  strokeWeight(2);
  line(vx - dw / 2 + dw * 0.35, vy - dh / 2, vx - dw / 2 + dw * 0.35, vy + dh / 2);
  noStroke();
}

function drawHalo(vx, vy) {
  // Grand halo diffus autour de la porte
  for (let r = 800; r > 0; r -= 4) {
    let t = r / 800;
    let a = pow(1 - t, 2.5) * 30;
    fill(255, 240, 215, a);
    noStroke();
    ellipse(vx + 15, vy, r * 1.2, r);
  }

  // Rayons de lumière subtils qui s'étalent dans le couloir
  push();
  translate(vx + 15, vy);
  for (let i = 0; i < 24; i++) {
    let ang = random(TWO_PI);
    let len = random(300, 900);
    let w = random(20, 80);
    noStroke();
    for (let k = 0; k < 20; k++) {
      let t = k / 20;
      let a = (1 - t) * 15;
      fill(255, 240, 210, a);
      push();
      rotate(ang);
      ellipse(len * t, 0, w * (1 + t * 3), w * (1 + t * 3));
      pop();
    }
  }
  pop();

  // Reflet sur le sol
  for (let i = 0; i < 300; i++) {
    let t = i / 300;
    let a = (1 - t) * 60;
    fill(255, 235, 200, a);
    noStroke();
    ellipse(vx + 15, vy + 180 + i, 300 - i * 0.5, 20);
  }
}

function drawDust(vx, vy) {
  // Particules suspendues, plus denses près de la lumière
  for (let i = 0; i < 3000; i++) {
    let dx = randomGaussian(0, 300);
    let dy = randomGaussian(0, 400);
    let x = vx + dx;
    let y = vy + dy;
    let d = dist(x, y, vx, vy);
    let brightness = map(d, 0, 700, 255, 20, true);
    let size = random(0.5, 2.5);
    noStroke();
    fill(255, 240, 210, brightness * 0.5);
    ellipse(x, y, size, size);
  }

  // Quelques particules plus grandes et lumineuses
  for (let i = 0; i < 80; i++) {
    let dx = randomGaussian(0, 200);
    let dy = randomGaussian(0, 250);
    let x = vx + dx;
    let y = vy + dy;
    let size = random(1.5, 4);
    fill(255, 250, 230, random(100, 200));
    noStroke();
    ellipse(x, y, size, size);
    // petit halo
    fill(255, 240, 210, 20);
    ellipse(x, y, size * 4, size * 4);
  }
}

function drawVignette() {
  for (let r = 0; r < 1200; r += 4) {
    let t = r / 1200;
    let a = pow(t, 3) * 2;
    noFill();
    stroke(0, 0, 5, a);
    strokeWeight(6);
    ellipse(width / 2, height / 2, width * 1.8 - r * 1.2, height * 1.8 - r * 1.2);
  }
}

function drawGrain() {
  for (let i = 0; i < 40000; i++) {
    let x = random(width);
    let y = random(height);
    let a = random(10, 35);
    stroke(random(200, 255), random(190, 240), random(170, 220), a);
    point(x, y);
  }
  // Grain sombre
  for (let i = 0; i < 25000; i++) {
    stroke(0, 0, 0, random(20, 60));
    point(random(width), random(height));
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Fond sombre dégradé
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(8, 18, t);
    let g = lerp(10, 14, t);
    let b = lerp(20, 22, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Texture de bruit sombre
  loadPixels();
  for (let i = 0; i < 40000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.002, y * 0.002);
    let a = n * 30;
    set(x, y, color(a + 15, a + 15, a + 25, 180));
  }
  updatePixels();

  // Le seuil : porte verticale de lumière
  let cx = width / 2;
  let doorW = 180;
  let doorTop = 180;
  let doorBot = height - 220;

  // Halo large autour de la porte
  noStroke();
  for (let r = 900; r > 0; r -= 6) {
    let a = map(r, 0, 900, 55, 0);
    fill(220, 225, 240, a);
    ellipse(cx, height / 2, r * 1.2, r * 2.2);
  }

  // Noyau de la porte, très lumineux
  for (let w = doorW; w > 0; w -= 2) {
    let a = map(w, 0, doorW, 255, 0);
    fill(245, 245, 230, a);
    rect(cx - w / 2, doorTop + (doorW - w) * 0.3, w, doorBot - doorTop - (doorW - w) * 0.6, w / 2);
  }

  // Cœur blanc pur
  fill(255, 252, 240, 255);
  rect(cx - 20, doorTop + 40, 40, doorBot - doorTop - 80, 20);

  // Particules : la matière qui se défait
  for (let i = 0; i < 2600; i++) {
    let side = random() < 0.5 ? -1 : 1;
    // Distance à la porte, biaisée vers elle
    let d = pow(random(), 1.6) * 700;
    let x = cx + side * d + random(-20, 20);
    let y = random(doorTop - 100, doorBot + 100) + random(-40, 40);

    // Attraction vers le seuil : taille et lumière décroissent avec la distance
    let prox = 1 - constrain(d / 700, 0, 1);
    let sz = random(0.5, 3.5) + prox * 3;
    let bright = 120 + prox * 135;
    let alpha = 80 + prox * 160;

    // Légère traînée horizontale vers la porte
    let trail = prox * random(10, 50);
    stroke(bright, bright, bright * 0.95, alpha * 0.4);
    strokeWeight(sz * 0.6);
    line(x, y, x - side * trail, y + random(-2, 2));

    noStroke();
    fill(bright, bright, bright * 0.95, alpha);
    ellipse(x, y, sz, sz);
  }

  // Quelques particules plus grosses, plus proches du seuil
  for (let i = 0; i < 180; i++) {
    let side = random() < 0.5 ? -1 : 1;
    let d = pow(random(), 2.5) * 300;
    let x = cx + side * d;
    let y = random(doorTop, doorBot);
    let prox = 1 - d / 300;
    let sz = random(2, 6) + prox * 4;
    noStroke();
    fill(255, 253, 240, 120 + prox * 100);
    ellipse(x, y, sz, sz);
  }

  // Brume basse
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = random(height * 0.7, height);
    let sz = random(80, 260);
    noStroke();
    fill(30, 32, 45, 8);
    ellipse(x, y, sz, sz * 0.4);
  }

  // Brume haute
  for (let i = 0; i < 200; i++) {
    let x = random(width);
    let y = random(0, height * 0.35);
    let sz = random(100, 300);
    noStroke();
    fill(40, 42, 55, 7);
    ellipse(x, y, sz, sz * 0.5);
  }

  // Vignette
  for (let r = 0; r < 800; r += 4) {
    let a = map(r, 0, 800, 0, 180);
    noFill();
    stroke(0, 0, 0, 180 - a);
    strokeWeight(6);
    ellipse(width / 2, height / 2, width * 1.4 + r * 2, height * 1.4 + r * 2);
  }

  // Lueur finale subtile au centre vertical
  noStroke();
  for (let r = 400; r > 0; r -= 10) {
    fill(230, 230, 220, 3);
    ellipse(cx, height / 2, r * 2, r * 3);
  }
}

let cnv;
function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Sky - gradient from deep indigo to misty grey-blue
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r, g, b;
    if (t < 0.55) {
      let u = t / 0.55;
      r = lerp(18, 90, u);
      g = lerp(22, 110, u);
      b = lerp(40, 125, u);
    } else {
      let u = (t - 0.55) / 0.45;
      r = lerp(90, 40, u);
      g = lerp(110, 55, u);
      b = lerp(125, 75, u);
    }
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Stars
  noStroke();
  for (let i = 0; i < 180; i++) {
    let x = random(width);
    let y = random(0, height * 0.5);
    let s = random(0.5, 2.5);
    fill(255, 255, 230, random(80, 220));
    ellipse(x, y, s, s);
    if (random() < 0.1) {
      fill(255, 255, 230, 40);
      ellipse(x, y, s * 4, s * 4);
    }
  }

  // Moon - pale, slightly obscured
  let mx = width * 0.72, my = height * 0.28, mr = 180;
  for (let r = mr * 1.6; r > mr; r -= 2) {
    let a = map(r, mr, mr * 1.6, 60, 0);
    fill(230, 225, 210, a);
    ellipse(mx, my, r * 2, r * 2);
  }
  fill(235, 230, 215, 230);
  ellipse(mx, my, mr * 2, mr * 2);
  // moon shadow (crescent-ish softness)
  fill(90, 100, 115, 40);
  ellipse(mx + 40, my - 20, mr * 1.8, mr * 1.8);

  // Fog bands in sky
  for (let i = 0; i < 25; i++) {
    let y = random(height * 0.1, height * 0.6);
    fill(200, 205, 215, random(10, 35));
    ellipse(random(width), y, random(400, 900), random(40, 90));
  }

  // Far shore - barely visible
  noStroke();
  fill(55, 65, 80, 180);
  beginShape();
  vertex(0, height * 0.58);
  for (let x = 0; x <= width; x += 20) {
    let n = noise(x * 0.002, 10) * 40;
    vertex(x, height * 0.58 + n);
  }
  vertex(width, height * 0.62);
  vertex(width, height * 0.6);
  endShape(CLOSE);

  // Far shore trees silhouette
  fill(35, 45, 60, 200);
  for (let x = 0; x < width; x += 8) {
    let n = noise(x * 0.01, 5);
    let h = n * 60 + 10;
    let baseY = height * 0.58 + noise(x * 0.002, 10) * 40;
    triangle(x - 4, baseY, x + 4, baseY, x, baseY - h);
  }

  // Water surface
  let waterTop = height * 0.6;
  for (let y = waterTop; y < height; y++) {
    let t = (y - waterTop) / (height - waterTop);
    let r = lerp(45, 20, t);
    let g = lerp(60, 30, t);
    let b = lerp(80, 45, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Water reflections / ripples
  noFill();
  for (let i = 0; i < 400; i++) {
    let y = random(waterTop, height);
    let t = (y - waterTop) / (height - waterTop);
    let len = random(30, 200) * (1 - t * 0.5);
    let x = random(width);
    stroke(180, 190, 205, random(10, 60) * (1 - t));
    strokeWeight(random(0.5, 1.5));
    line(x, y, x + len, y);
  }

  // Reflected star-light below moon
  for (let i = 0; i < 40; i++) {
    let y = waterTop + i * 8 + random(-2, 2);
    let w = random(60, 220) * (1 - i / 50);
    stroke(230, 225, 210, random(30, 90) * (1 - i / 50));
    strokeWeight(random(1, 2.5));
    line(mx - w / 2 + random(-15, 15), y, mx + w / 2 + random(-15, 15), y);
  }

  // Mist layer over water
  noStroke();
  for (let i = 0; i < 60; i++) {
    let y = random(waterTop - 20, waterTop + 180);
    fill(210, 215, 225, random(8, 30));
    ellipse(random(width), y, random(500, 1100), random(30, 70));
  }

  // The boat
  push();
  let bx = width * 0.38, by = height * 0.73;
  translate(bx, by);

  // Boat reflection
  push();
  scale(1, -0.6);
  translate(0, -10);
  fill(15, 20, 30, 120);
  beginShape();
  vertex(-180, 0);
  quadraticVertex(-220, 40, -150, 55);
  vertex(150, 55);
  quadraticVertex(220, 40, 180, 0);
  endShape(CLOSE);
  pop();

  // Boat hull
  fill(20, 22, 30);
  stroke(10, 12, 18);
  strokeWeight(2);
  beginShape();
  vertex(-200, 0);
  quadraticVertex(-230, 35, -160, 50);
  vertex(160, 50);
  quadraticVertex(230, 35, 200, 0);
  endShape(CLOSE);

  // Hull highlight
  noStroke();
  fill(50, 55, 70, 150);
  beginShape();
  vertex(-195, -2);
  quadraticVertex(0, -8, 195, -2);
  quadraticVertex(0, 2, -195, -2);
  endShape(CLOSE);

  // Lantern pole
  stroke(25, 20, 15);
  strokeWeight(4);
  line(0, 0, 0, -140);
  // Hook
  noFill();
  arc(-12, -140, 24, 24, 0, PI);

  // Lantern body
  let lx = -24, ly = -128;
  noStroke();
  // Glow
  for (let r = 260; r > 0; r -= 8) {
    let a = map(r, 0, 260, 90, 0);
    fill(255, 200, 120, a * 0.4);
    ellipse(lx, ly, r, r);
  }

  // Lantern frame
  fill(30, 25, 20);
  rect(lx - 18, ly - 22, 36, 44, 4);
  // Light inside
  fill(255, 220, 150, 240);
  rect(lx - 12, ly - 16, 24, 32, 2);
  // Flame
  fill(255, 240, 200);
  ellipse(lx, ly, 8, 14);
  fill(255, 255, 220, 200);
  ellipse(lx, ly - 2, 4, 8);
  // Frame bars
  stroke(20, 15, 10);
  strokeWeight(1.5);
  line(lx - 18, ly, lx + 18, ly);
  line(lx, ly - 22, lx, ly + 22);
  noStroke();
  // Top
  fill(30, 25, 20);
  rect(lx - 22, ly - 28, 44, 8, 2);
  rect(lx - 10, ly - 36, 20, 8, 2);

  // Figure - cloaked, seated, bowed
  noStroke();
  fill(15, 18, 25);
  beginShape();
  vertex(40, 10);
  quadraticVertex(30, -40, 55, -80);
  quadraticVertex(70, -110, 95, -115);
  quadraticVertex(120, -110, 130, -70);
  quadraticVertex(135, -20, 125, 10);
  endShape(CLOSE);
  // Hood shadow
  fill(5, 8, 12);
  ellipse(90, -85, 35, 40);

  pop();

  // Floating petals / embers on water near boat
  for (let i = 0; i < 30; i++) {
    let px = bx + random(-400, 400);
    let py = by + random(20, 300);
    if (py < height) {
      fill(255, 180, 120, random(60, 180));
      noStroke();
      ellipse(px, py, random(2, 5), random(1, 2));
    }
  }

  // Vignette
  noFill();
  for (let r = 0; r < 300; r += 2) {
    stroke(0, 0, 10, r * 0.25);
    rect(r, r, width - 2 * r, height - 2 * r);
  }

  // Subtle grain
  for (let i = 0; i < 4000; i++) {
    stroke(255, random(5, 15));
    point(random(width), random(height));
  }
}

const sketch = (p) => {
  p.setup = () => {
    p.createCanvas(1600, 2000);
    p.randomSeed(1);
    p.noiseSeed(1);
    p.noLoop();
    drawPainting();
  };

  function drawPainting() {
    // Sky gradient - cold dawn
    for (let y = 0; y < 2000; y++) {
      let t = y / 2000;
      let r = p.lerp(40, 180, Math.pow(t, 1.5));
      let g = p.lerp(50, 175, Math.pow(t, 1.3));
      let b = p.lerp(75, 170, Math.pow(t, 1.1));
      if (y > 1100) {
        // water region, slightly darker
        let wt = (y - 1100) / 900;
        r = p.lerp(130, 60, wt);
        g = p.lerp(140, 70, wt);
        b = p.lerp(155, 90, wt);
      }
      p.stroke(r, g, b);
      p.line(0, y, 1600, y);
    }

    // Soft fog layers horizontally
    p.noStroke();
    for (let i = 0; i < 40; i++) {
      let y = p.random(200, 1400);
      let h = p.random(30, 120);
      let alpha = p.random(8, 25);
      p.fill(230, 230, 225, alpha);
      p.rect(0, y, 1600, h);
    }

    // Distant pale light / sun behind fog
    for (let r = 400; r > 0; r -= 4) {
      let a = p.map(r, 0, 400, 80, 0);
      p.fill(240, 235, 215, a);
      p.ellipse(800, 900, r * 2, r * 2);
    }

    // Far shore silhouettes (figures on the bank - left side, barely visible)
    drawFarShore();

    // Water reflections - horizontal streaks
    for (let i = 0; i < 300; i++) {
      let y = p.random(1150, 2000);
      let x = p.random(0, 1600);
      let w = p.random(20, 200);
      let alpha = p.random(10, 40);
      let shade = p.random(140, 200);
      p.stroke(shade, shade, shade - 10, alpha);
      p.strokeWeight(p.random(0.5, 2));
      p.line(x, y, x + w, y);
    }

    // Light reflection in water (vertical shimmer from sun)
    p.noStroke();
    for (let i = 0; i < 80; i++) {
      let y = 1150 + i * 10;
      let w = p.map(i, 0, 80, 60, 300);
      let a = p.map(i, 0, 80, 60, 5);
      p.fill(240, 230, 200, a);
      p.ellipse(800, y, w, 4);
    }

    // The boat and figure - central, slightly below middle
    drawBoat(760, 1320);

    // Lantern glow
    drawLanternGlow(820, 1240);

    // Foreground mist
    for (let i = 0; i < 20; i++) {
      p.fill(200, 200, 205, p.random(5, 20));
      p.ellipse(p.random(0, 1600), p.random(1300, 2000), p.random(300, 700), p.random(60, 150));
    }

    // Vignette
    for (let r = 1200; r > 600; r -= 4) {
      let a = p.map(r, 600, 1200, 0, 60);
      p.noFill();
      p.stroke(20, 25, 40, a);
      p.strokeWeight(4);
      p.ellipse(800, 1000, r * 2.4, r * 2.6);
    }

    // Grain
    p.noStroke();
    for (let i = 0; i < 8000; i++) {
      p.fill(p.random(255), p.random(10, 30));
      p.rect(p.random(1600), p.random(2000), 1, 1);
    }
  }

  function drawFarShore() {
    p.noStroke();
    // bank
    p.fill(90, 95, 105, 180);
    p.beginShape();
    p.vertex(0, 1120);
    for (let x = 0; x <= 600; x += 10) {
      let y = 1120 + p.noise(x * 0.01) * 20 - 5;
      p.vertex(x, y);
    }
    p.vertex(600, 1180);
    p.vertex(0, 1180);
    p.endShape(p.CLOSE);

    // tiny figures on shore
    for (let i = 0; i < 5; i++) {
      let x = 80 + i * 90 + p.random(-20, 20);
      let y = 1115;
      p.fill(50, 55, 70, 200);
      p.ellipse(x, y - 18, 6, 6);
      p.rect(x - 3, y - 14, 6, 16, 2);
    }

    // trees/posts - bare
    for (let i = 0; i < 3; i++) {
      let x = 40 + i * 180;
      p.stroke(60, 65, 75, 180);
      p.strokeWeight(2);
      p.line(x, 1120, x + p.random(-5, 5), 1050);
      // branches
      for (let b = 0; b < 4; b++) {
        let by = 1060 + b * 10;
        p.line(x, by, x + p.random(-20, 20), by - p.random(10, 20));
      }
      p.noStroke();
    }
  }

  function drawBoat(cx, cy) {
    p.push();
    p.translate(cx, cy);

    // reflection of boat (soft)
    p.noStroke();
    p.fill(30, 35, 50, 80);
    p.beginShape();
    p.vertex(-180, 10);
    p.bezierVertex(-150, 40, 150, 40, 180, 10);
    p.bezierVertex(140, 5, -140, 5, -180, 10);
    p.endShape(p.CLOSE);

    // boat hull
    p.fill(25, 28, 38);
    p.beginShape();
    p.vertex(-200, 0);
    p.bezierVertex(-180, -30, -100, -40, 0, -40);
    p.bezierVertex(100, -40, 180, -30, 200, 0);
    p.bezierVertex(150, 20, -150, 20, -200, 0);
    p.endShape(p.CLOSE);

    // hull inner shadow
    p.fill(15, 18, 25);
    p.beginShape();
    p.vertex(-170, -5);
    p.bezierVertex(-150, -25, -90, -32, 0, -32);
    p.bezierVertex(90, -32, 150, -25, 170, -5);
    p.bezierVertex(130, 5, -130, 5, -170, -5);
    p.endShape(p.CLOSE);

    // figure standing - the ferryman / soul
    p.fill(20, 22, 30);
    // robe
    p.beginShape();
    p.vertex(-30, -40);
    p.vertex(-45, -180);
    p.vertex(-25, -200);
    p.vertex(25, -200);
    p.vertex(45, -180);
    p.vertex(30, -40);
    p.endShape(p.CLOSE);

    // hood
    p.fill(10, 12, 18);
    p.ellipse(0, -205, 55, 60);
    p.fill(0, 0, 0);
    p.ellipse(0, -200, 35, 40);

    // pole
    p.stroke(40, 42, 50);
    p.strokeWeight(3);
    p.line(60, -230, 140, 40);
    p.noStroke();

    // lantern hanging from pole or held
    // small hook at front of boat
    p.stroke(30, 32, 40);
    p.strokeWeight(2);
    p.line(60, -100, 60, -150);
    p.noStroke();

    p.pop();
  }

  function drawLanternGlow(lx, ly) {
    // big halo
    p.noStroke();
    for (let r = 300; r > 0; r -= 3) {
      let a = p.map(r, 0, 300, 90, 0);
      p.fill(255, 210, 140, a * 0.5);
      p.ellipse(lx, ly, r * 2, r * 2);
    }

    // lantern body
    p.fill(60, 45, 30);
    p.rect(lx - 14, ly - 20, 28, 40, 4);
    // glass with light
    p.fill(255, 220, 150, 240);
    p.rect(lx - 10, ly - 16, 20, 32, 2);
    // bright core
    p.fill(255, 245, 210);
    p.ellipse(lx, ly, 10, 14);
    // top cap
    p.fill(50, 38, 25);
    p.rect(lx - 16, ly - 24, 32, 6, 2);
    // bottom
    p.rect(lx - 16, ly + 18, 32, 6, 2);

    // reflection of light on water below boat
    for (let i = 0; i < 40; i++) {
      let y = 1360 + i * 12;
      let a = p.map(i, 0, 40, 100, 0);
      let w = 40 + p.noise(i * 0.3) * 60;
      p.fill(255, 215, 150, a);
      p.ellipse(lx + 20, y, w, 5);
    }
  }
};

