let canvas;

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // 渐变天空 - 从深灰蓝到暖灰
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r, g, b;
    if (t < 0.5) {
      // 上半部分：深灰蓝到雾灰
      let tt = t / 0.5;
      r = lerp(45, 165, tt);
      g = lerp(55, 160, tt);
      b = lerp(75, 155, tt);
    } else {
      // 下半部分：雾灰到水面深色
      let tt = (t - 0.5) / 0.5;
      r = lerp(165, 55, tt);
      g = lerp(160, 65, tt);
      b = lerp(155, 80, tt);
    }
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // 远山/雾中彼岸 - 隐约的轮廓
  noStroke();
  for (let i = 0; i < 3; i++) {
    let yBase = 850 + i * 30;
    fill(120 - i * 10, 125 - i * 10, 130 - i * 10, 80 - i * 20);
    beginShape();
    vertex(0, yBase);
    for (let x = 0; x <= width; x += 20) {
      let y = yBase + noise(x * 0.002, i) * 60 - 30;
      vertex(x, y);
    }
    vertex(width, yBase + 200);
    vertex(0, yBase + 200);
    endShape(CLOSE);
  }

  // 雾气层
  for (let i = 0; i < 200; i++) {
    let x = random(width);
    let y = random(750, 1050);
    let s = random(100, 400);
    fill(180, 180, 180, random(5, 15));
    ellipse(x, y, s, s * 0.3);
  }

  // 水面光线水平线条
  for (let i = 0; i < 300; i++) {
    let y = random(1000, height);
    let x = random(width);
    let len = random(20, 150);
    let alpha = map(y, 1000, height, 20, 80);
    stroke(200, 210, 220, alpha * random(0.3, 1));
    strokeWeight(random(0.5, 1.5));
    line(x, y, x + len, y);
  }

  // 月亮/苍白的太阳
  noStroke();
  let moonX = 1100;
  let moonY = 600;
  for (let r = 180; r > 0; r -= 2) {
    let a = map(r, 180, 0, 0, 180);
    fill(230, 225, 210, a * 0.3);
    ellipse(moonX, moonY, r * 2, r * 2);
  }
  fill(240, 235, 220, 220);
  ellipse(moonX, moonY, 160, 160);

  // 月亮在水面的倒影
  for (let i = 0; i < 40; i++) {
    let y = 1050 + i * 8;
    let w = 160 + sin(i * 0.3) * 20;
    let alpha = map(i, 0, 40, 100, 0);
    fill(240, 235, 220, alpha);
    ellipse(moonX, y, w * (1 - i * 0.01), 3);
  }

  // 水面涟漪
  noFill();
  for (let i = 0; i < 5; i++) {
    stroke(200, 210, 220, 60 - i * 10);
    strokeWeight(1);
    let cx = 700;
    let cy = 1400;
    ellipse(cx, cy, 200 + i * 80, 30 + i * 12);
  }

  for (let i = 0; i < 3; i++) {
    stroke(200, 210, 220, 50);
    strokeWeight(1);
    ellipse(1200, 1600, 150 + i * 60, 20 + i * 8);
  }

  // 小舟
  push();
  translate(700, 1380);

  // 船的倒影
  noStroke();
  fill(30, 35, 45, 120);
  beginShape();
  vertex(-180, 20);
  quadraticVertex(-150, 80, -100, 90);
  vertex(100, 90);
  quadraticVertex(150, 80, 180, 20);
  endShape(CLOSE);

  // 船身主体
  fill(25, 22, 20);
  beginShape();
  vertex(-180, 0);
  quadraticVertex(-150, -35, -100, -40);
  vertex(100, -40);
  quadraticVertex(150, -35, 180, 0);
  quadraticVertex(150, 15, 100, 18);
  vertex(-100, 18);
  quadraticVertex(-150, 15, -180, 0);
  endShape(CLOSE);

  // 船内阴影
  fill(15, 12, 10);
  beginShape();
  vertex(-160, -5);
  quadraticVertex(-135, -30, -95, -33);
  vertex(95, -33);
  quadraticVertex(135, -30, 160, -5);
  quadraticVertex(135, 5, 95, 8);
  vertex(-95, 8);
  quadraticVertex(-135, 5, -160, -5);
  endShape(CLOSE);

  // 船上的灯 - 柱子
  stroke(40, 35, 30);
  strokeWeight(3);
  line(-20, -30, -20, -90);

  // 灯罩
  noStroke();
  fill(50, 45, 40);
  rect(-35, -110, 30, 25, 2);

  // 灯光
  fill(255, 200, 100, 200);
  ellipse(-20, -95, 20, 25);

  // 灯光辐射
  for (let r = 80; r > 0; r -= 4) {
    let a = map(r, 80, 0, 0, 60);
    fill(255, 200, 100, a);
    ellipse(-20, -95, r * 2, r * 2);
  }

  // 更亮的核心
  fill(255, 240, 200, 255);
  ellipse(-20, -95, 8, 12);

  pop();

  // 远处的另一只船(更小,更模糊)
  push();
  translate(1250, 1200);
  scale(0.4);
  fill(50, 55, 65, 180);
  beginShape();
  vertex(-180, 0);
  quadraticVertex(-150, -35, -100, -40);
  vertex(100, -40);
  quadraticVertex(150, -35, 180, 0);
  quadraticVertex(150, 15, 100, 18);
  vertex(-100, 18);
  quadraticVertex(-150, 15, -180, 0);
  endShape(CLOSE);

  // 远船微光
  fill(255, 210, 130, 150);
  ellipse(0, -30, 15, 15);
  pop();

  // 漂浮的花瓣/灰烬 - 象征逝去的生命
  for (let i = 0; i < 25; i++) {
    let x = random(width);
    let y = random(400, 1800);
    let s = random(3, 10);
    fill(240, 220, 200, random(100, 200));
    noStroke();
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    ellipse(0, 0, s, s * 0.4);
    pop();
  }

  // 前景水面的暗涌
  noStroke();
  for (let i = 0; i < 100; i++) {
    let x = random(width);
    let y = random(1700, height);
    fill(20, 25, 35, random(30, 80));
    ellipse(x, y, random(40, 200), random(3, 8));
  }

  // 整体氛围的暗角
  for (let i = 0; i < 100; i++) {
    noFill();
    stroke(20, 20, 30, 3);
    strokeWeight(i * 2);
    rect(i, i, width - i * 2, height - i * 2);
  }

  // 细微的噪点质感
  for (let i = 0; i < 3000; i++) {
    let x = random(width);
    let y = random(height);
    stroke(255, random(5, 15));
    strokeWeight(1);
    point(x, y);
  }
}

