  // 光晕
  for (let r = 120; r > 0; r -= 3) {
    let a = map(r, 120, 0, 0, 100);
    fill(255, 220, 150, a * 0.3);
    ellipse(0, -40, r * 2);
  }
  // 灯芯
  fill(255, 240, 200);
  ellipse(0, -40, 20);
  fill(255, 255, 230);
  ellipse(0, -40, 10);

  // 光柱向上
  for (let i = 0; i < 60; i++) {
    let a = map(i, 0, 60, 80, 0);
    stroke(255, 230, 170, a);
    strokeWeight(1);
    let spread = i * 1.5;
    line(-spread, -40 - i * 8, spread, -40 - i * 8);
  }

  // 船上人影（坐着，低头）
  noStroke();
  fill(15, 15, 20);
  // 身体
  beginShape();
  vertex(-30, -30);
  vertex(30, -30);
  vertex(40, 5);
  vertex(-40, 5);
  endShape(CLOSE);
  // 头
  ellipse(0, -55, 35, 40);
  // 兜帽阴影
  fill(5, 5, 10);
  arc(0, -55, 38, 42, PI + 0.3, TWO_PI - 0.3);

  pop();

  // 远处漂浮的光点（灵魂）
  noStroke();
  for (let i = 0; i < 15; i++) {
    let x = random(width);
    let y = random(300, 1100);
    let s = random(2, 6);
    for (let r = s * 4; r > 0; r -= 1) {
      let a = map(r, s * 4, 0, 0, 180);
      fill(255, 240, 210, a * 0.2);
      ellipse(x, y, r);
    }
    fill(255, 250, 230, 200);
    ellipse(x, y, s);
  }

  // 雾气层
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = random(800, 1300);
    noStroke();
    fill(200, 205, 215, random(3, 12));
    ellipse(x, y, random(100, 300), random(20, 60));
  }

  // 顶部暗角
  for (let i = 0; i < 200; i++) {
    noStroke();
    fill(0, 0, 10, 1);
    rect(0, 0, width, i);
  }

  // 底部暗角
  for (let i = 0; i < 150; i++) {
    noStroke();
    fill(0, 0, 5, 2);
    rect(0, height - i, width, i);
  }
}

let canvas;
function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // 天空渐变 - 灰蓝到暖灰
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r, g, b;
    if (t < 0.55) {
      let tt = t / 0.55;
      r = lerp(185, 155, tt);
      g = lerp(180, 165, tt);
      b = lerp(175, 175, tt);
    } else {
      let tt = (t - 0.55) / 0.45;
      r = lerp(130, 70, tt);
      g = lerp(140, 85, tt);
      b = lerp(150, 95, tt);
    }
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // 远山雾气中若隐若现
  noStroke();
  for (let i = 0; i < 3; i++) {
    let yBase = 1050 + i * 30;
    let alpha = 40 - i * 10;
    fill(90, 100, 110, alpha);
    beginShape();
    vertex(0, yBase + 100);
    for (let x = 0; x <= width; x += 20) {
      let y = yBase + noise(x * 0.002 + i * 10) * 150 - 60;
      vertex(x, y);
    }
    vertex(width, yBase + 100);
    vertex(width, height);
    vertex(0, height);
    endShape(CLOSE);
  }

  // 雾气
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = random(950, 1200);
    let r = random(80, 200);
    fill(200, 205, 210, random(8, 20));
    ellipse(x, y, r, r * 0.4);
  }

  // 水面
  let waterTop = 1150;
  for (let y = waterTop; y < height; y++) {
    let t = (y - waterTop) / (height - waterTop);
    let r = lerp(80, 35, t);
    let g = lerp(95, 50, t);
    let b = lerp(110, 65, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // 水面波纹
  noFill();
  for (let i = 0; i < 180; i++) {
    let y = random(waterTop, height);
    let x = random(width);
    let len = random(30, 180);
    let alpha = map(y, waterTop, height, 90, 30);
    stroke(200, 210, 215, alpha);
    strokeWeight(random(0.5, 1.5));
    let yy = y + sin(x * 0.01) * 2;
    line(x, yy, x + len, yy);
  }

  // 水中倒影 - 淡淡的山影
  noStroke();
  for (let i = 0; i < 2; i++) {
    fill(60, 70, 80, 25);
    beginShape();
    vertex(0, waterTop);
    for (let x = 0; x <= width; x += 20) {
      let y = waterTop + (waterTop - (1050 + noise(x * 0.002 + i * 10) * 150 - 60));
      vertex(x, y + i * 20);
    }
    vertex(width, waterTop);
    endShape(CLOSE);
  }

  // 船 - 位于画面中偏下
  let boatX = 800;
  let boatY = 1380;
  drawBoat(boatX, boatY);

  // 船的倒影
  push();
  translate(boatX, boatY * 2 + 30);
  scale(1, -1);
  translate(-boatX, -boatY);
  drawBoatReflection(boatX, boatY);
  pop();

  // 灯
  drawLantern(boatX - 30, boatY - 110);

  // 灯光晕
  drawGlow(boatX - 30, boatY - 90);

  // 落花漂浮
  drawPetals();

  // 远景的孤鸟
  stroke(50, 55, 65, 180);
  strokeWeight(2);
  noFill();
  for (let i = 0; i < 3; i++) {
    let bx = 300 + i * 80 + random(-20, 20);
    let by = 700 + random(-30, 30);
    let s = 15;
    noFill();
    beginShape();
    vertex(bx - s, by);
    quadraticVertex(bx - s/2, by - s/2, bx, by);
    quadraticVertex(bx + s/2, by - s/2, bx + s, by);
    endShape();
  }

  // 整体柔光
  noStroke();
  for (let i = 0; i < 50; i++) {
    fill(255, 240, 210, 3);
    ellipse(boatX, boatY - 80, 600 + i * 20, 400 + i * 15);
  }

  // 暗角
  for (let i = 0; i < 100; i++) {
    noFill();
    stroke(20, 25, 35, 3);
    strokeWeight(2);
    rect(i, i, width - 2 * i, height - 2 * i);
  }
}

function drawBoat(x, y) {
  push();
  translate(x, y);
  noStroke();
  // 船身阴影
  fill(25, 30, 38);
  beginShape();
  vertex(-180, 0);
  quadraticVertex(-200, 35, -150, 50);
  vertex(150, 50);
  quadraticVertex(200, 35, 180, 0);
  quadraticVertex(0, -10, -180, 0);
  endShape(CLOSE);
  // 船身上缘
  fill(55, 45, 40);
  beginShape();
  vertex(-180, 0);
  quadraticVertex(0, -15, 180, 0);
  quadraticVertex(0, -5, -180, 0);
  endShape(CLOSE);
  // 船内
  fill(40, 32, 28);
  ellipse(0, -2, 340, 12);
  // 木纹
  stroke(70, 55, 45, 120);
  strokeWeight(1);
  for (let i = 0; i < 5; i++) {
    let yy = 10 + i * 8;
    line(-175 + i * 5, yy, 175 - i * 5, yy);
  }
  // 小桅杆底座
  noStroke();
  fill(45, 35, 30);
  rect(-35, -15, 10, 15);
  pop();
}

function drawBoatReflection(x, y) {
  push();
  translate(x, y);
  noStroke();
  fill(25, 30, 38, 80);
  beginShape();
  vertex(-180, 0);
  quadraticVertex(-200, 35, -150, 50);
  vertex(150, 50);
  quadraticVertex(200, 35, 180, 0);
  endShape(CLOSE);
  // 擦除倒影，用水的颜色波纹
  for (let i = 0; i < 15; i++) {
    stroke(60, 75, 90, 120);
    strokeWeight(random(1, 2));
    let yy = random(0, 60);
    line(random(-180, 0), yy, random(0, 180), yy);
  }
  pop();
}

function drawLantern(x, y) {
  push();
  translate(x, y);
  // 杆
  stroke(35, 28, 25);
  strokeWeight(3);
  line(30, 10, 30, 110);
  // 悬挂线
  stroke(30, 25, 22);
  strokeWeight(1);
  line(0, 5, 30, 15);
  // 灯笼主体
  noStroke();
  fill(180, 90, 50, 230);
  ellipse(0, 25, 50, 60);
  // 灯笼顶
  fill(40, 30, 25);
  rect(-15, -8, 30, 8);
  // 灯笼底
  fill(40, 30, 25);
  rect(-12, 52, 24, 6);
  // 灯笼光亮
  fill(255, 210, 140, 200);
  ellipse(0, 25, 35, 45);
  fill(255, 240, 200, 220);
  ellipse(0, 22, 20, 28);
  // 灯笼纹
  stroke(80, 40, 20, 150);
  strokeWeight(0.8);
  noFill();
  for (let i = -20; i <= 20; i += 8) {
    line(-20, 25 + i, 20, 25 + i);
  }
  pop();
}

function drawGlow(x, y) {
  noStroke();
  for (let i = 40; i > 0; i--) {
    fill(255, 200, 130, 3);
    ellipse(x, y, i * 15, i * 15);
  }
  // 水面反射光
  for (let i = 0; i < 30; i++) {
    fill(255, 200, 130, 4);
    ellipse(x, 1400 + i * 5, 250 - i * 3, 15);
  }
}

function drawPetals() {
  noStroke();
  for (let i = 0; i < 60; i++) {
    let x = random(width);
    let y = random(1200, height);
    let s = random(6, 14);
    let a = random(TWO_PI);
    push();
    translate(x, y);
    rotate(a);
    // 阴影
    fill(50, 30, 35, 100);
    ellipse(1, 1, s, s * 0.5);
    // 花瓣
    let c = random();
    if (c < 0.5) fill(220, 180, 185, 220);
    else if (c < 0.8) fill(200, 150, 160, 210);
    else fill(240, 210, 200, 220);
    ellipse(0, 0, s, s * 0.5);
    pop();
  }
  // 空中飘落几片
  for (let i = 0; i < 15; i++) {
    let x = random(width);
    let y = random(600, 1150);
    let s = random(5, 10);
    let a = random(TWO_PI);
    push();
    translate(x, y);
    rotate(a);
    fill(220, 180, 185, 180);
    ellipse(0, 0, s, s * 0.5);
    pop();
  }
}

let cnv;
function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // 房间的墙 - 暖褐色，带噪点
  drawWall();

  // 地板
  drawFloor();

  // 夕阳从窗照入的光斑（暗示另一个光源）
  drawSunPatch();

  // 门框和门
  drawDoor();

  // 门缝溢出的光
  drawDoorLight();

  // 整体颗粒感
  drawGrain();

  // 暗角
  drawVignette();
}

function drawWall() {
  // 墙壁渐变
  for (let y = 0; y < 1600; y++) {
    let t = y / 1600;
    let r = lerp(78, 52, t);
    let g = lerp(58, 42, t);
    let b = lerp(48, 38, t);
    stroke(r, g, b);
    line(0, y, 1600, y);
  }
  // 墙面纹理
  for (let i = 0; i < 40000; i++) {
    let x = random(1600);
    let y = random(1600);
    let n = noise(x * 0.005, y * 0.005);
    stroke(60 + n * 30, 45 + n * 25, 38 + n * 20, 40);
    point(x, y);
  }
  // 墙上细裂纹
  stroke(30, 20, 15, 80);
  strokeWeight(1);
  for (let i = 0; i < 15; i++) {
    let x = random(1600);
    let y = random(200, 1400);
    let len = random(40, 160);
    let a = random(TWO_PI);
    let px = x, py = y;
    for (let j = 0; j < len; j++) {
      let nx = px + cos(a) * 2;
      let ny = py + sin(a) * 2;
      line(px, py, nx, ny);
      a += random(-0.3, 0.3);
      px = nx; py = ny;
    }
  }
}

function drawFloor() {
  // 地板透视
  for (let y = 1600; y < 2000; y++) {
    let t = (y - 1600) / 400;
    let r = lerp(45, 25, t);
    let g = lerp(32, 18, t);
    let b = lerp(25, 14, t);
    stroke(r, g, b);
    line(0, y, 1600, y);
  }
  // 地板木纹线
  stroke(20, 14, 10, 150);
  strokeWeight(1);
  for (let i = 0; i < 25; i++) {
    let y = 1600 + i * 16 + random(-4, 4);
    line(0, y, 1600, y + random(-2, 2));
  }
  // 地板光线反射（从门来的光）
  push();
  noStroke();
  for (let i = 0; i < 60; i++) {
    let alpha = map(i, 0, 60, 90, 0);
    fill(255, 240, 200, alpha);
    let w = 180 + i * 6;
    beginShape();
    vertex(800 - w/2, 1600 + i * 7);
    vertex(800 + w/2, 1600 + i * 7);
    vertex(800 + w/2 + 10, 1600 + (i+1) * 7);
    vertex(800 - w/2 - 10, 1600 + (i+1) * 7);
    endShape(CLOSE);
  }
  pop();
}

function drawSunPatch() {
  // 左侧墙上来自画外窗户的暖色光斑
  push();
  noStroke();
  for (let i = 0; i < 80; i++) {
    let alpha = map(i, 0, 80, 50, 0);
    fill(220, 140, 80, alpha);
    ellipse(200 + i * 0.5, 900 + i * 2, 400 - i * 2, 600 - i * 3);
  }
  pop();
}

function drawDoor() {
  // 门框 - 位于画面中央
  let doorX = 640;
  let doorY = 400;
  let doorW = 320;
  let doorH = 1200;

  // 门框外侧阴影
  push();
  noStroke();
  fill(20, 12, 8);
  rect(doorX - 40, doorY - 20, doorW + 80, doorH + 20);

  // 门框
  fill(35, 22, 15);
  rect(doorX - 25, doorY, doorW + 50, doorH);

  // 门框内侧
  fill(15, 10, 7);
  rect(doorX, doorY, doorW, doorH);
  pop();

  // 门（半开状态）- 门扉倾斜透视
  push();
  // 门的轮廓：左边贴着门框左侧，右边向画面外倾斜打开
  let hingeX = doorX;
  let hingeTop = doorY;
  let hingeBot = doorY + doorH;
  // 门打开的角度，右边缘向观者倾斜
  let openEdgeX = doorX + 140;
  let openEdgeTopY = doorY + 30;
  let openEdgeBotY = doorY + doorH - 30;

  noStroke();
  fill(30, 20, 14);
  beginShape();
  vertex(hingeX, hingeTop);
  vertex(openEdgeX, openEdgeTopY);
  vertex(openEdgeX, openEdgeBotY);
  vertex(hingeX, hingeBot);
  endShape(CLOSE);

  // 门板纹理
  stroke(15, 10, 7, 180);
  strokeWeight(1);
  for (let i = 1; i < 6; i++) {
    let t = i / 6;
    let x1 = lerp(hingeX, openEdgeX, t);
    let y1 = lerp(hingeTop, openEdgeTopY, t);
    let x2 = lerp(hingeX, openEdgeX, t);
    let y2 = lerp(hingeBot, openEdgeBotY, t);
    line(x1, y1, x2, y2);
  }
  // 门板横线
  stroke(50, 35, 22, 100);
  for (let i = 1; i < 4; i++) {
    let t = i / 4;
    let y1 = lerp(hingeTop, hingeBot, t);
    let y2 = lerp(openEdgeTopY, openEdgeBotY, t);
    line(hingeX, y1, openEdgeX, y2);
  }

  // 门把手
  noStroke();
  fill(180, 140, 80);
  let hx = lerp(hingeX, openEdgeX, 0.85);
  let hy = lerp(hingeTop, openEdgeTopY, 0.85) + (hingeBot - openEdgeBotY) * 0 + 600;
  // 重新计算：把手在门中间高度
  let ht = 0.55;
  let hxt = lerp(hingeX, openEdgeX, 0.88);
  let hyt = lerp(lerp(hingeTop, hingeBot, ht), lerp(openEdgeTopY, openEdgeBotY, ht), 0.88);
  ellipse(hxt, hyt, 18, 24);
  fill(100, 70, 30);
  ellipse(hxt, hyt, 8, 12);
  pop();
}

function drawDoorLight() {
  let doorX = 640;
  let doorY = 400;
  let doorW = 320;
  let doorH = 1200;
  let openEdgeX = doorX + 140;
  let openEdgeTopY = doorY + 30;
  let openEdgeBotY = doorY + doorH - 30;

  push();
  noStroke();
  // 门外的光 - 门缝区域（从打开的门边缘到门框右侧）
  // 构建梯形光区

  // 多层光晕从内向外
  for (let layer = 0; layer < 40; layer++) {
    let expand = layer * 8;
    let alpha = map(layer, 0, 40, 180, 0);
    fill(255, 248, 225, alpha);
    beginShape();
    vertex(openEdgeX - expand * 0.3, openEdgeTopY - expand);
    vertex(doorX + doorW + expand, doorY - expand);
    vertex(doorX + doorW + expand, doorY + doorH + expand);
    vertex(openEdgeX - expand * 0.3, openEdgeBotY + expand);
    endShape(CLOSE);
  }

  // 核心强光
  for (let layer = 0; layer < 20; layer++) {
    let alpha = map(layer, 0, 20, 255, 100);
    fill(255, 253, 240, alpha);
    let shrink = layer * 2;
    beginShape();
    vertex(openEdgeX + shrink, openEdgeTopY + shrink);
    vertex(doorX + doorW - shrink, doorY + shrink);
    vertex(doorX + doorW - shrink, doorY + doorH - shrink);
    vertex(openEdgeX + shrink, openEdgeBotY - shrink);
    endShape(CLOSE);
  }

  // 最亮核心 - 纯白
  fill(255, 255, 250);
  beginShape();
  vertex(openEdgeX + 10, openEdgeTopY + 20);
  vertex(doorX + doorW - 5, doorY + 15);
  vertex(doorX + doorW - 5, doorY + doorH - 15);
  vertex(openEdgeX + 10, openEdgeBotY - 20);
  endShape(CLOSE);

  // 光溢出到地板上 - 梯形光痕
  for (let i = 0; i < 50; i++) {
    let alpha = map(i, 0, 50, 120, 0);
    fill(255, 245, 210, alpha);
    let spread = i * 8;
    beginShape();
    vertex(openEdgeX - spread * 0.2, openEdgeBotY - 10);
    vertex(doorX + doorW + spread * 0.3, doorY + doorH);
    vertex(doorX + doorW + spread * 2, 2000);
    vertex(openEdgeX - spread * 1.5, 2000);
    endShape(CLOSE);
  }

  // 光溢出到墙壁上
  for (let i = 0; i < 60; i++) {
    let alpha = map(i, 0, 60, 80, 0);
    fill(255, 240, 200, alpha);
    ellipse(doorX + doorW + 100 + i, doorY + doorH / 2, 400 + i * 4, 1400 + i * 6);
  }

  // 光粒子 - 门口的尘埃光
  for (let i = 0; i < 300; i++) {
    let t = random();
    let x = lerp(openEdgeX, doorX + doorW, random());
    let y = lerp(openEdgeTopY, openEdgeBotY, random()) + random(-30, 30);
    let s = random(1, 4);
    fill(255, 250, 220, random(80, 200));
    ellipse(x, y, s, s);
  }

  // 光线向外辐射
  for (let i = 0; i < 20; i++) {
    let alpha = random(10, 40);
    stroke(255, 250, 220, alpha);
    strokeWeight(random(1, 3));
    let cx = (openEdgeX + doorX + doorW) / 2;
    let cy = (doorY + doorH / 2);
    let a = random(-PI/6, PI/6);
    let len = random(300, 700);
    line(cx, cy, cx + cos(a) * len * 1.5, cy + sin(a) * len);
  }
  pop();
}

function drawGrain() {
  push();
  for (let i = 0; i < 60000; i++) {
    let x = random(1600);
    let y = random(2000);
    stroke(random(255), random(50, 200));
    point(x, y);
  }
  pop();
}

function drawVignette() {
  push();
  noFill();
  for (let i = 0; i < 300; i++) {
    stroke(0, map(i, 0, 300, 80, 0));
    strokeWeight(2);
    rect(i, i, 1600 - i * 2, 2000 - i * 2);
  }
  pop();
}

let cnv;
function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  // --- Background: dim dusk room ---
  // Vertical gradient from warm umber to deep shadow
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(58, 22, t);
    let g = lerp(40, 16, t);
    let b = lerp(30, 18, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Floor
  push();
  noStroke();
  for (let y = height * 0.72; y < height; y++) {
    let t = (y - height * 0.72) / (height * 0.28);
    let r = lerp(45, 18, t);
    let g = lerp(32, 14, t);
    let b = lerp(24, 12, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }
  // floor boards - perspective lines
  stroke(10, 8, 6, 120);
  strokeWeight(1.2);
  let vx = width / 2;
  let vy = height * 0.55;
  for (let i = -8; i <= 8; i++) {
    let fx = width / 2 + i * 140;
    line(vx, vy, fx, height);
  }
  pop();

  // --- Wall texture noise ---
  push();
  noStroke();
  for (let i = 0; i < 9000; i++) {
    let x = random(width);
    let y = random(height * 0.72);
    let n = noise(x * 0.003, y * 0.003);
    fill(20 + n * 30, 16 + n * 22, 14 + n * 18, 40);
    rect(x, y, 2, 2);
  }
  pop();

  // --- Door frame ---
  let doorX = width * 0.32;
  let doorY = height * 0.18;
  let doorW = width * 0.36;
  let doorH = height * 0.62;

  // frame outer
  push();
  noStroke();
  fill(28, 20, 16);
  rect(doorX - 40, doorY - 40, doorW + 80, doorH + 40);
  // inner recess
  fill(12, 9, 8);
  rect(doorX - 10, doorY - 10, doorW + 20, doorH + 10);
  pop();

  // --- The light beyond the door ---
  // The door is half-open: left half is door panel, right half is light opening
  let hingeX = doorX;
  let openEdge = doorX + doorW * 0.42; // where light pours out
  let lightLeft = openEdge;
  let lightRight = doorX + doorW;
  let lightTop = doorY;
  let lightBottom = doorY + doorH;

  // Fill opening with intense white-gold light with soft gradient
  push();
  noStroke();
  for (let y = lightTop; y < lightBottom; y++) {
    for (let x = lightLeft; x < lightRight; x += 1) {
      // handled below with rects for speed
    }
  }
  // radial-ish light
  for (let r = 600; r > 0; r -= 4) {
    let cx = (lightLeft + lightRight) / 2;
    let cy = (lightTop + lightBottom) / 2 - 80;
    let t = r / 600;
    let alpha = map(t, 0, 1, 255, 0);
    fill(255, 252, 235, alpha * 0.08);
    ellipse(cx, cy, r * 2, r * 2.4);
  }
  // Clip-ish: redraw bright core inside opening
  fill(255, 253, 240);
  rect(lightLeft, lightTop, lightRight - lightLeft, lightBottom - lightTop);

  // subtle vertical fade inside opening
  for (let y = lightTop; y < lightBottom; y++) {
    let t = (y - lightTop) / (lightBottom - lightTop);
    let a = 80 * Math.abs(t - 0.45);
    fill(230, 210, 170, a);
    rect(lightLeft, y, lightRight - lightLeft, 1);
  }
  pop();

  // --- Light spill onto floor ---
  push();
  noStroke();
  let spillTopX1 = lightLeft;
  let spillTopX2 = lightRight;
  let spillBotX1 = lightLeft - 180;
  let spillBotX2 = lightRight + 420;
  let spillY1 = doorY + doorH;
  let spillY2 = height;

  for (let i = 0; i < 60; i++) {
    let t = i / 60;
    let a = (1 - t) * 90;
    fill(255, 240, 200, a);
    let y1 = lerp(spillY1, spillY2, t);
    let y2 = lerp(spillY1, spillY2, t + 1 / 60);
    let xL1 = lerp(spillTopX1, spillBotX1, t);
    let xR1 = lerp(spillTopX2, spillBotX2, t);
    let xL2 = lerp(spillTopX1, spillBotX1, t + 1 / 60);
    let xR2 = lerp(spillTopX2, spillBotX2, t + 1 / 60);
    quad(xL1, y1, xR1, y1, xR2, y2, xL2, y2);
  }
  pop();

  // --- The door panel (half open, angled) ---
  push();
  // door panel - a parallelogram suggesting perspective
  let d_tl = { x: hingeX, y: doorY };
  let d_bl = { x: hingeX, y: doorY + doorH };
  let d_tr = { x: openEdge - 20, y: doorY + 30 };
  let d_br = { x: openEdge - 20, y: doorY + doorH - 10 };

  // door base color
  noStroke();
  fill(40, 28, 22);
  quad(d_tl.x, d_tl.y, d_tr.x, d_tr.y, d_br.x, d_br.y, d_bl.x, d_bl.y);

  // door shading - darker on hinge side
  for (let i = 0; i < 40; i++) {
    let t = i / 40;
    let a = (1 - t) * 60;
    fill(10, 6, 5, a);
    let x1 = lerp(d_tl.x, d_tr.x, t);
    let x2 = lerp(d_tl.x, d_tr.x, t + 1 / 40);
    let yt1 = lerp(d_tl.y, d_tr.y, t);
    let yt2 = lerp(d_tl.y, d_tr.y, t + 1 / 40);
    let yb1 = lerp(d_bl.y, d_br.y, t);
    let yb2 = lerp(d_bl.y, d_br.y, t + 1 / 40);
    quad(x1, yt1, x2, yt2, x2, yb2, x1, yb1);
  }

  // wood grain
  stroke(20, 12, 8, 100);
  strokeWeight(1);
  noFill();
  for (let i = 0; i < 25; i++) {
    let yy = doorY + (doorH / 25) * i + random(-6, 6);
    let yy2 = doorY + 30 + ((doorH - 40) / 25) * i + random(-6, 6);
    line(hingeX + 4, yy, openEdge - 24, yy2);
  }

  // door panels (two rectangles)
  stroke(15, 8, 6);
  strokeWeight(3);
  noFill();
  // upper panel
  let p1x1 = hingeX + 40;
  let p1y1 = doorY + 60;
  let p1x2 = openEdge - 60;
  let p1y2 = doorY + doorH * 0.45;
  quad(p1x1, p1y1, p1x2, p1y1 + 15, p1x2, p1y2 + 10, p1x1, p1y2);
  // lower panel
  let p2y1 = doorY + doorH * 0.52;
  let p2y2 = doorY + doorH - 60;
  quad(p1x1, p2y1, p1x2, p2y1 + 12, p1x2, p2y2 + 5, p1x1, p2y2);

  // door handle
  noStroke();
  fill(200, 170, 90);
  ellipse(openEdge - 50, doorY + doorH * 0.5, 22, 22);
  fill(120, 90, 40);
  ellipse(openEdge - 50, doorY + doorH * 0.5 + 2, 14, 14);
  pop();

  // --- Rim light on door edge ---
  push();
  stroke(255, 240, 200, 220);
  strokeWeight(4);
  line(openEdge - 20, doorY + 30, openEdge - 20, doorY + doorH - 10);
  stroke(255, 250, 230, 120);
  strokeWeight(10);
  line(openEdge - 20, doorY + 30, openEdge - 20, doorY + doorH - 10);
  pop();

  // --- Dust motes floating in the light ---
  push();
  noStroke();
  for (let i = 0; i < 400; i++) {
    let x = random(lightLeft - 100, lightRight + 300);
    let y = random(doorY, height);
    // more dust where light is
    let inLight = x > lightLeft - 50 && y > doorY + doorH * 0.3;
    let a = inLight ? random(120, 220) : random(10, 60);
    fill(255, 245, 220, a);
    let s = random(1, 3.5);
    ellipse(x, y, s, s);
  }
  // larger glowing motes
  for (let i = 0; i < 40; i++) {
    let x = random(lightLeft - 50, lightRight + 200);
    let y = random(doorY + 100, height - 100);
    fill(255, 250, 230, 40);
    ellipse(x, y, random(8, 16), random(8, 16));
    fill(255, 255, 245, 180);
    ellipse(x, y, 2, 2);
  }
  pop();

  // --- Light beam volumetric ---
  push();
  noStroke();
  blendMode(ADD);
  for (let i = 0; i < 30; i++) {
    let t = i / 30;
    fill(255, 230, 180, 8);
    let x1 = lightLeft;
    let x2 = lightRight;
    let xL = lerp(x1, x1 - 200, t);
    let xR = lerp(x2, x2 + 500, t);
    let yT = doorY + 30;
    let yB = lerp(doorY + doorH, height, t);
    quad(x1, yT, x2, yT, xR, yB, xL, yB);
  }
  blendMode(BLEND);
  pop();

  // --- Vignette ---
  push();
  noFill();
  for (let i = 0; i < 200; i++) {
    stroke(0, 0, 0, 3);
    strokeWeight(1);
    rect(i, i, width - i * 2, height - i * 2);
  }
  pop();

  // --- Final subtle grain ---
  push();
  noStroke();
  for (let i = 0; i < 20000; i++) {
    let x = random(width);
    let y = random(height);
    fill(255, 255, 255, random(5, 15));
    rect(x, y, 1, 1);
  }
  pop();
}

let canvas;
function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // 背景：深蓝灰的虚空，带有微弱渐变
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(18, 32, t);
    let g = lerp(22, 30, t);
    let b = lerp(35, 38, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // 添加噪声质感（像灰尘、像时间）
  loadPixels();
  for (let i = 0; i < 40000; i++) {
    let x = floor(random(width));
    let y = floor(random(height));
    let idx = 4 * (y * width + x);
    let n = random(-15, 15);
    pixels[idx] = constrain(pixels[idx] + n, 0, 255);
    pixels[idx+1] = constrain(pixels[idx+1] + n, 0, 255);
    pixels[idx+2] = constrain(pixels[idx+2] + n, 0, 255);
  }
  updatePixels();

  // 远处的微光粒子（星尘、消散的生命）
  noStroke();
  for (let i = 0; i < 1200; i++) {
    let x = random(width);
    let y = random(height);
    let d = random(1, 3);
    let a = random(20, 100);
    fill(220, 215, 200, a);
    circle(x, y, d);
  }

  // 门槛的位置与几何
  let cx = width / 2;
  let cy = height / 2 - 50;
  let doorW = 420;
  let doorH = 720;
  let tilt = -0.08; // 轻微倾斜

  // 门外的光晕（多层径向）
  push();
  translate(cx, cy);
  rotate(tilt);
  for (let r = 900; r > 0; r -= 8) {
    let t = r / 900;
    let alpha = map(t, 0, 1, 60, 0);
    // 暖白光从门里渗出
    fill(255, 240, 210, alpha * 0.35);
    noStroke();
    ellipse(0, 0, r * 2.2, r * 1.6);
  }
  pop();

  // 门内的光（矩形）
  push();
  translate(cx, cy);
  rotate(tilt);

  // 门内从中心到边缘的渐变光
  for (let i = 0; i < doorW/2; i++) {
    let t = i / (doorW/2);
    let a = lerp(255, 180, t);
    fill(255, lerp(250, 220, t), lerp(230, 180, t), a);
    noStroke();
    rect(-i-1, -doorH/2, 2, doorH);
    rect(i, -doorH/2, 2, doorH);
  }
  // 门的中心最亮
  fill(255, 253, 240);
  rect(-30, -doorH/2, 60, doorH);

  // 门的边缘——不是硬边，而是溶解的
  for (let i = 0; i < 800; i++) {
    let side = random([-1, 1]);
    let edgeX = side * doorW/2 + random(-25, 25);
    let edgeY = random(-doorH/2 - 20, doorH/2 + 20);
    let a = random(60, 200);
    fill(255, 240, 210, a);
    noStroke();
    circle(edgeX, edgeY, random(1, 4));
  }
  // 门顶和门底的溶解
  for (let i = 0; i < 400; i++) {
    let topBot = random([-1, 1]);
    let ex = random(-doorW/2 - 20, doorW/2 + 20);
    let ey = topBot * doorH/2 + random(-25, 25);
    let a = random(60, 200);
    fill(255, 240, 210, a);
    noStroke();
    circle(ex, ey, random(1, 4));
  }
  pop();

  // 门前的粒子场——向门流动的生命碎片
  push();
  translate(cx, cy);
  rotate(tilt);
  for (let i = 0; i < 3500; i++) {
    // 粒子分布在门周围，越靠近门越亮
    let angle = random(TWO_PI);
    let dist = random(0, 1100);
    dist = pow(dist / 1100, 0.7) * 1100;
    let px = cos(angle) * dist;
    let py = sin(angle) * dist * 0.9;

    // 粒子颜色：靠近门的偏暖白，远处的偏冷灰
    let distFromDoor = dist / 1100;
    let r = lerp(255, 120, distFromDoor);
    let g = lerp(240, 125, distFromDoor);
    let b = lerp(210, 140, distFromDoor);
    let a = random(40, 180) * (1 - distFromDoor * 0.6);

    // 不要覆盖门内
    if (abs(px) < doorW/2 - 10 && abs(py) < doorH/2 - 10) continue;

    fill(r, g, b, a);
    noStroke();
    let s = random(1, 3.5) * (1 - distFromDoor * 0.3);
    circle(px, py, s);
  }
  pop();

  // 此岸——底部有一点隐约的地面暗示
  push();
  noStroke();
  for (let y = height - 300; y < height; y++) {
    let t = (y - (height - 300)) / 300;
    fill(10, 12, 20, t * 180);
    rect(0, y, width, 1);
  }
  pop();

  // 一个孤立的小影子——站立者（极小，几乎看不见）
  push();
  translate(cx - 180, height - 280);
  fill(8, 10, 15, 220);
  noStroke();
  // 简化人形
  ellipse(0, -60, 18, 22);
  rect(-10, -48, 20, 55, 3);
  pop();

  // 顶部的更深的暗，强调门作为光源
  push();
  noStroke();
  for (let y = 0; y < 400; y++) {
    let t = 1 - y / 400;
    fill(8, 10, 18, t * 120);
    rect(0, y, width, 1);
  }
  pop();

  // 整体的轻微暗角
  push();
  noFill();
  for (let r = 0; r < 300; r++) {
    stroke(5, 8, 15, r * 0.3);
    strokeWeight(2);
    noFill();
    rect(r, r, width - r*2, height - r*2);
  }
  pop();
}

let cnv;
function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // === 墙壁：暖灰褐色，带噪点 ===
  background(58, 50, 45);

  // 墙面渐变
  for (let y = 0; y < 2000; y++) {
    let t = y / 2000;
    let r = lerp(72, 38, t);
    let g = lerp(62, 32, t);
    let b = lerp(54, 28, t);
    stroke(r, g, b);
    line(0, y, 1600, y);
  }

  // 墙面纹理噪点
  noStroke();
  for (let i = 0; i < 40000; i++) {
    let x = random(1600);
    let y = random(2000);
    let n = noise(x * 0.005, y * 0.005);
    let a = random(5, 25);
    fill(255, 240, 220, a * n);
    rect(x, y, 2, 2);
  }

  // === 地板 ===
  // 地平线
  let floorY = 1400;

  // 地板基色
  for (let y = floorY; y < 2000; y++) {
    let t = (y - floorY) / (2000 - floorY);
    let r = lerp(42, 28, t);
    let g = lerp(34, 22, t);
    let b = lerp(28, 18, t);
    stroke(r, g, b);
    line(0, y, 1600, y);
  }

  // 地板木纹（透视线）
  let vpX = 800;
  let vpY = floorY;
  for (let i = -20; i <= 20; i++) {
    let x = 800 + i * 90;
    stroke(20, 15, 12, 180);
    strokeWeight(1.5);
    line(x, 2000, vpX, vpY);
  }

  // 地板横向板缝（透视）
  for (let k = 1; k < 15; k++) {
    let y = floorY + pow(k / 14, 1.6) * (2000 - floorY);
    stroke(18, 13, 10, 150);
    strokeWeight(1);
    line(0, y, 1600, y);
  }

  // === 门框 ===
  let doorCX = 800;
  let doorW = 440;
  let doorH = 900;
  let doorTop = floorY - doorH;
  let doorLeft = doorCX - doorW / 2;
  let doorRight = doorCX + doorW / 2;

  // 门框阴影（门框外侧）
  noStroke();
  fill(25, 20, 17);
  let frameT = 40;
  rect(doorLeft - frameT, doorTop - frameT, doorW + frameT * 2, frameT); // 上
  rect(doorLeft - frameT, doorTop - frameT, frameT, doorH + frameT);     // 左
  rect(doorRight, doorTop - frameT, frameT, doorH + frameT);             // 右

  // === 门洞内的光 ===
  // 从门内发出的光：中心亮白，向外渐变为暖黄再到墙色
  // 用径向渐变
  let lightCX = doorCX;
  let lightCY = doorTop + doorH * 0.55;

  for (let r = 800; r > 0; r -= 2) {
    let t = r / 800;
    let rr = lerp(255, 80, t);
    let gg = lerp(250, 60, t);
    let bb = lerp(230, 45, t);
    let a = lerp(255, 0, t);
    fill(rr, gg, bb, a);
    noStroke();
    // 只在门内可见：使用裁剪通过绘制全圆但后面覆盖
    ellipse(lightCX, lightCY, r * 2, r * 2);
  }

  // 覆盖门外区域（恢复墙面）——通过重绘门外的墙壁遮挡
  // 使用一个遮罩：画一个大矩形，中间挖门洞
  noStroke();
  // 上
  for (let y = 0; y < doorTop; y++) {
    let t = y / 2000;
    let rr = lerp(72, 38, t);
    let gg = lerp(62, 32, t);
    let bb = lerp(54, 28, t);
    stroke(rr, gg, bb);
    line(0, y, 1600, y);
  }
  // 左
  noStroke();
  for (let y = doorTop; y < floorY; y++) {
    let t = y / 2000;
    let rr = lerp(72, 38, t);
    let gg = lerp(62, 32, t);
    let bb = lerp(54, 28, t);
    stroke(rr, gg, bb);
    line(0, y, doorLeft, y);
    line(doorRight, y, 1600, y);
  }

  // 重新画噪点在墙上（避免被遮罩覆盖的太干净）
  noStroke();
  for (let i = 0; i < 15000; i++) {
    let x = random(1600);
    let y = random(2000);
    // 跳过门洞内
    if (x > doorLeft && x < doorRight && y > doorTop && y < floorY) continue;
    let n = noise(x * 0.005, y * 0.005);
    let a = random(5, 20);
    fill(255, 240, 220, a * n);
    rect(x, y, 2, 2);
  }

  // 重新画门框（覆盖）
  noStroke();
  fill(25, 20, 17);
  rect(doorLeft - frameT, doorTop - frameT, doorW + frameT * 2, frameT);
  rect(doorLeft - frameT, doorTop - frameT, frameT, doorH + frameT);
  rect(doorRight, doorTop - frameT, frameT, doorH + frameT);

  // 门框高光
  fill(45, 38, 32);
  rect(doorLeft - frameT, doorTop - frameT, doorW + frameT * 2, 4);
  rect(doorLeft - frameT, doorTop - frameT, 4, doorH + frameT);

  // === 门槛阴影 ===
  noStroke();
  fill(15, 10, 8);
  rect(doorLeft - 5, floorY - 8, doorW + 10, 12);

  // === 光投射到地板上的梯形光斑 ===
  // 从门洞底部向外延展的光
  push();
  noStroke();
  // 多层叠加形成光束
  for (let i = 0; i < 60; i++) {
    let t = i / 60;
    let topY = floorY;
    let botY = floorY + 50 + t * 500;
    let topL = doorLeft + 20;
    let topR = doorRight - 20;
    let spread = 80 + t * 200;
    let botL = topL - spread;
    let botR = topR + spread;
    let a = lerp(80, 0, t);
    fill(255, 240, 210, a);
    quad(topL, topY, topR, topY, botR, botY, botL, botY);
  }
  pop();

  // === 光斑的噪点和尘埃 ===
  noStroke();
  for (let i = 0; i < 2000; i++) {
    let y = random(floorY, floorY + 500);
    let t = (y - floorY) / 500;
    let spread = 80 + t * 200;
    let x = random(doorLeft - spread + 20, doorRight + spread - 20);
    let a = random(0, 60) * (1 - t);
    fill(255, 245, 220, a);
    ellipse(x, y, 2, 2);
  }

  // === 空中漂浮的尘埃（在光束中） ===
  for (let i = 0; i < 300; i++) {
    let x = random(doorLeft - 50, doorRight + 50);
    let y = random(doorTop + 100, floorY);
    // 只在门内或靠近门的区域
    if (x < doorLeft || x > doorRight) continue;
    let brightness = random(150, 255);
    let size = random(1, 4);
    fill(255, 250, 230, brightness);
    noStroke();
    ellipse(x, y, size, size);
  }

  // 光束中的尘埃
  for (let i = 0; i < 150; i++) {
    let t = random();
    let y = floorY + t * 400;
    let spread = 80 + (t) * 200;
    let x = random(doorLeft - spread, doorRight + spread);
    let a = random(100, 220) * (1 - t * 0.7);
    fill(255, 250, 225, a);
    noStroke();
    ellipse(x, y, random(1, 3), random(1, 3));
  }

  // === 墙上的微弱反光（门框周围被照亮） ===
  for (let r = 300; r > 0; r -= 3) {
    let t = r / 300;
    let a = (1 - t) * 15;
    fill(255, 230, 190, a);
    noStroke();
    ellipse(doorCX, doorTop + doorH * 0.5, r * 2.5, r * 2);
  }

  // === 墙角阴影（暗角） ===
  for (let r = 1200; r > 600; r -= 4) {
    let t = (r - 600) / 600;
    let a = t * 1.2;
    fill(0, 0, 0, a);
    noStroke();
    ellipse(800, 1000, r * 2.2, r * 2.4);
  }

  // 四角加深
  for (let i = 0; i < 4; i++) {
    let cx = (i % 2) * 1600;
    let cy = floor(i / 2) * 2000;
    for (let r = 800; r > 0; r -= 4) {
      let t = r / 800;
      let a = (1 - t) * 0.8;
      fill(0, 0, 0, a);
      noStroke();
      ellipse(cx, cy, r * 2, r * 2);
    }
  }

  // === 最后一层整体颗粒感 ===
  for (let i = 0; i < 20000; i++) {
    let x = random(1600);
    let y = random(2000);
    let a = random(0, 15);
    fill(random(200, 255), random(190, 240), random(170, 220), a);
    noStroke();
    rect(x, y, 1, 1);
  }
}

let cnv;
function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // --- 房间墙壁（暖色）---
  // 背景渐变：昏黄温暖
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(60, 30, t);
    let g = lerp(40, 20, t);
    let b = lerp(28, 15, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // 墙面纹理噪点
  noStroke();
  for (let i = 0; i < 8000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.005, y * 0.005);
    fill(80 + n * 40, 55 + n * 25, 35 + n * 15, 40);
    rect(x, y, 2, 2);
  }

  // --- 地板 ---
  push();
  noStroke();
  for (let y = 1500; y < 2000; y++) {
    let t = (y - 1500) / 500;
    fill(lerp(35, 15, t), lerp(22, 10, t), lerp(15, 8, t));
    rect(0, y, width, 1);
  }
  // 地板木纹
  stroke(20, 12, 8, 120);
  strokeWeight(1);
  for (let i = 0; i < 40; i++) {
    let y = 1500 + i * 13 + random(-3, 3);
    line(0, y, width, y + random(-2, 2));
  }
  pop();

  // --- 门框 ---
  // 门位于画面中心偏右，门半开，露出另一侧的光
  let doorX = 500;      // 门框左边
  let doorY = 350;      // 门框上边
  let doorW = 700;      // 门框宽
  let doorH = 1400;     // 门框高

  // 门框阴影（在墙上投下的边缘）
  noStroke();
  fill(15, 8, 5, 180);
  rect(doorX - 40, doorY - 40, doorW + 80, 40); // 上阴影
  rect(doorX - 40, doorY - 40, 40, doorH + 40); // 左阴影

  // 门框木头
  fill(55, 32, 20);
  rect(doorX - 60, doorY - 60, doorW + 120, 60); // 上框
  rect(doorX - 60, doorY - 60, 60, doorH + 60);  // 左框
  rect(doorX + doorW, doorY - 60, 60, doorH + 60); // 右框

  // --- 门洞内部：白光 ---
  // 这是"另一侧"，近乎纯白但带有极淡的冷调
  // 使用径向渐变模拟从门口向内的强光
  let cx = doorX + doorW * 0.55;
  let cy = doorY + doorH * 0.45;
  for (let r = 1500; r > 0; r -= 2) {
    let t = r / 1500;
    let c = lerp(255, 230, t);
    let cb = lerp(255, 235, t);
    fill(c, c, cb);
    // 裁剪在门洞内
    push();
    // 用矩形裁剪
    drawingContext.save();
    drawingContext.beginPath();
    drawingContext.rect(doorX, doorY, doorW, doorH);
    drawingContext.clip();
    noStroke();
    ellipse(cx, cy + 200, r * 1.4, r * 1.6);
    drawingContext.restore();
    pop();
  }

  // 在门洞内加极淡的噪点让白不是死白
  push();
  drawingContext.save();
  drawingContext.beginPath();
  drawingContext.rect(doorX, doorY, doorW, doorH);
  drawingContext.clip();
  for (let i = 0; i < 3000; i++) {
    let x = random(doorX, doorX + doorW);
    let y = random(doorY, doorY + doorH);
    noStroke();
    fill(200, 200, 210, 15);
    rect(x, y, 2, 2);
  }
  drawingContext.restore();
  pop();

  // --- 半开的门（木门向内开，遮住门洞左侧一部分）---
  push();
  // 门是立体的：用梯形模拟透视
  // 门的铰链在左侧门框上，门向房间内（朝观者）打开约 40 度
  // 近端（靠观者）在左，远端（铰链）在右上/右下
  let hingeTopX = doorX;
  let hingeTopY = doorY;
  let hingeBotX = doorX;
  let hingeBotY = doorY + doorH;
  // 门打开的角度造成近端伸出
  let nearTopX = doorX - 320;
  let nearTopY = doorY + 60;
  let nearBotX = doorX - 320;
  let nearBotY = doorY + doorH - 60;

  // 门板主体（深色木头，正面受房间暖光照）
  noStroke();
  fill(45, 28, 18);
  beginShape();
  vertex(hingeTopX, hingeTopY);
  vertex(nearTopX, nearTopY);
  vertex(nearBotX, nearBotY);
  vertex(hingeBotX, hingeBotY);
  endShape(CLOSE);

  // 门板上的面板装饰（两个凹陷方格）
  fill(32, 20, 12);
  // 上面板
  beginShape();
  vertex(lerp(hingeTopX, nearTopX, 0.2), lerp(hingeTopY, nearTopY, 0.2) + 80);
  vertex(lerp(hingeTopX, nearTopX, 0.8), lerp(hingeTopY, nearTopY, 0.8) + 80);
  vertex(lerp(hingeBotX, nearBotX, 0.8), lerp(hingeBotY, nearBotY, 0.8) - 800);
  vertex(lerp(hingeBotX, nearBotX, 0.2), lerp(hingeBotY, nearBotY, 0.2) - 800);
  endShape(CLOSE);
  // 下面板
  beginShape();
  vertex(lerp(hingeTopX, nearTopX, 0.2), lerp(hingeTopY, nearTopY, 0.2) + 760);
  vertex(lerp(hingeTopX, nearTopX, 0.8), lerp(hingeTopY, nearTopY, 0.8) + 760);
  vertex(lerp(hingeBotX, nearBotX, 0.8), lerp(hingeBotY, nearBotY, 0.8) - 80);
  vertex(lerp(hingeBotX, nearBotX, 0.2), lerp(hingeBotY, nearBotY, 0.2) - 80);
  endShape(CLOSE);

  // 门边高光（光从门洞里泄出，照亮门的内缘）
  // 门的"背面"边缘贴近门洞，从里面漏出的白光让这个边缘发亮
  stroke(240, 240, 235, 200);
  strokeWeight(6);
  noFill();
  line(hingeTopX, hingeTopY, hingeBotX, hingeBotY);

  // 门板木纹
  stroke(25, 15, 8, 100);
  strokeWeight(1);
  for (let i = 0; i < 15; i++) {
    let t = i / 15;
    let x1 = lerp(hingeTopX, hingeBotX, t) + random(-2, 2);
    let y1 = lerp(hingeTopY, hingeBotY, t);
    let x2 = lerp(nearTopX, nearBotX, t) + random(-2, 2);
    let y2 = lerp(nearTopY, nearBotY, t);
    line(x1, y1, x2, y2);
  }
  pop();

  // --- 光从门洞泄到地板上的梯形光斑 ---
  push();
  // 光斑：从门口向房间内（向下、向左）投射
  let lightShape = [
    {x: doorX + doorW * 0.4, y: doorY + doorH},
    {x: doorX + doorW, y: doorY + doorH},
    {x: doorX + doorW + 250, y: height},
    {x: doorX - 400, y: height}
  ];
  // 多层叠加做渐变
  for (let i = 0; i < 20; i++) {
    let alpha = 12;
    noStroke();
    fill(255, 250, 230, alpha);
    beginShape();
    for (let p of lightShape) {
      vertex(p.x, p.y);
    }
    endShape(CLOSE);
  }
  pop();

  // --- 悬浮的尘埃（在光束中可见）---
  push();
  noStroke();
  for (let i = 0; i < 400; i++) {
    let x, y;
    // 在门洞附近和光束区域
    if (random() < 0.5) {
      // 门洞附近
      x = random(doorX - 100, doorX + doorW + 100);
      y = random(doorY + 200, doorY + doorH);
    } else {
      // 光束里
      x = random(doorX - 300, doorX + doorW + 200);
      y = random(doorY + doorH - 100, height - 50);
    }
    let size = random(2, 6);
    let bright = random(200, 255);
    fill(bright, bright - 10, bright - 30, random(80, 180));
    ellipse(x, y, size, size);
  }
  pop();

  // --- 门洞上缘和侧缘的强光溢出（发光效果）---
  push();
  // 右边缘（门框内侧）发光
  for (let i = 0; i < 30; i++) {
    noStroke();
    fill(255, 255, 250, 8);
    rect(doorX + doorW - i * 2, doorY, i * 4, doorH);
    rect(doorX, doorY - i, doorW, i * 2);
  }
  pop();

  // --- 整体暗角 ---
  push();
  noFill();
  for (let i = 0; i < 200; i++) {
    stroke(0, 0, 0, 3);
    strokeWeight(1);
    rect(i, i, width - i * 2, height - i * 2);
  }
  pop();

  // --- 画面颗粒感 ---
  push();
  noStroke();
  for (let i = 0; i < 15000; i++) {
    let x = random(width);
    let y = random(height);
    fill(0, 0, 0, random(10, 30));
    rect(x, y, 1, 1);
  }
  for (let i = 0; i < 5000; i++) {
    let x = random(width);
    let y = random(height);
    fill(255, 240, 220, random(5, 20));
    rect(x, y, 1, 1);
  }
  pop();
}

