let W=1600,H=2000;
function setup(){
  createCanvas(W,H);
  randomSeed(1); noiseSeed(1);
  noLoop();
  pixelDensity(1);

  // Sky gradient - warm left, cool right meeting in the middle
  loadPixels();
  for(let y=0;y<H;y++){
    for(let x=0;x<W;x++){
      let t = x/W;
      // warm pink-orange to cool violet-blue
      let warm = color(245, 180, 160);
      let cool = color(120, 130, 190);
      let mid  = color(230, 170, 180);
      let c;
      let tt = t;
      // soft meeting
      let blend = 1 - Math.pow(Math.abs(tt-0.5)*2, 1.4);
      let base = lerpColor(warm, cool, tt);
      c = lerpColor(base, mid, blend*0.5);
      // vertical fade darker at bottom
      let vy = y/H;
      let darken = lerpColor(c, color(60,50,80), vy*0.55);
      // soft noise grain
      let n = noise(x*0.004, y*0.004);
      darken = lerpColor(darken, color(255,230,210), (n-0.5)*0.15);
      let idx = (x+y*W)*4;
      pixels[idx]=red(darken);
      pixels[idx+1]=green(darken);
      pixels[idx+2]=blue(darken);
      pixels[idx+3]=255;
    }
  }
  updatePixels();

  // Horizon / shore band
  noStroke();
  for(let y=1250;y<1400;y++){
    let t=(y-1250)/150;
    let c=lerpColor(color(200,160,170,180), color(80,60,90,255), t);
    fill(c);
    rect(0,y,W,1);
  }

  // Reflective water below
  loadPixels();
  for(let y=1400;y<H;y++){
    for(let x=0;x<W;x++){
      let idx=(x+y*W)*4;
      let srcY = 1400 - (y-1400)*0.6;
      srcY = constrain(srcY,0,1399);
      let sidx=(x+Math.floor(srcY)*W)*4;
      let r=pixels[sidx], g=pixels[sidx+1], b=pixels[sidx+2];
      let ripple = sin(y*0.05 + noise(x*0.01,y*0.01)*6)*0.15+0.85;
      let dark = (y-1400)/(H-1400);
      r = r*ripple*(1-dark*0.6) + 20*dark;
      g = g*ripple*(1-dark*0.6) + 15*dark;
      b = b*ripple*(1-dark*0.6) + 40*dark;
      pixels[idx]=r; pixels[idx+1]=g; pixels[idx+2]=b; pixels[idx+3]=255;
    }
  }
  updatePixels();

  // Two abstract figures as pooled color
  drawFigure(640, 1100, color(220,90,110,230), color(255,200,170,200), -0.15);
  drawFigure(960, 1100, color(90,110,200,230), color(180,200,255,200), 0.15);

  // where they meet - exchange of light
  blendMode(SCREEN);
  for(let i=0;i<60;i++){
    let x = 800 + randomGaussian()*80;
    let y = 950 + randomGaussian()*140;
    let r = random(20,120);
    fill(255, 220, 200, 20);
    noStroke();
    ellipse(x,y,r,r*1.2);
  }
  blendMode(BLEND);

  // soft floating particles - breath between them
  for(let i=0;i<200;i++){
    let x = random(W);
    let y = random(200, 1300);
    let s = random(1,4);
    let a = random(40,140);
    fill(255, 240, 220, a);
    noStroke();
    ellipse(x,y,s,s);
  }

  // single quiet sun/moon above them
  noStroke();
  for(let r=180;r>0;r-=2){
    let a = map(r,0,180,180,0);
    fill(255, 230, 200, a*0.08);
    ellipse(800, 520, r*2, r*2);
  }
  fill(255,240,215,220);
  ellipse(800,520,110,110);

  // subtle vignette
  for(let r=0;r<800;r+=4){
    noFill();
    stroke(10,5,20, map(r,0,800,0,60));
    strokeWeight(4);
    ellipse(W/2,H/2, W*1.6+r, H*1.6+r);
  }

  // faint edge darkening corners
  noStroke();
  for(let i=0;i<4;i++){
    let cx = (i%2)*W, cy = Math.floor(i/2)*H;
    for(let r=600;r>0;r-=20){
      fill(10,5,25, map(r,0,600,0,40));
      ellipse(cx,cy,r*2,r*2);
    }
  }
}

function drawFigure(cx, cy, c1, c2, lean){
  noStroke();
  // body as stacked soft ellipses
  for(let i=0;i<400;i++){
    let t = i/400;
    let y = cy + 420*(t-0.5) + sin(t*3)*20;
    let xoff = lean * 180 * (1-t) + sin(t*5)*15;
    let w = 260 * (1 - Math.pow(Math.abs(t-0.4)*1.6,1.8));
    w = max(w, 20);
    let c = lerpColor(c1, c2, t*0.8 + noise(i*0.05)*0.3);
    c.setAlpha(140);
    fill(c);
    ellipse(cx+xoff, y, w, 30);
  }
  // head
  let headY = cy - 230;
  let headX = cx + lean*180;
  for(let r=90;r>0;r-=3){
    let a = map(r,0,90,220,40);
    let c = lerpColor(c2, color(255,235,220), 0.3);
    c.setAlpha(a*0.4);
    fill(c);
    ellipse(headX, headY, r*2, r*2.1);
  }
  // inner glow heart area
  blendMode(SCREEN);
  for(let r=120;r>0;r-=6){
    fill(255,200,180, 8);
    ellipse(cx + lean*120, cy-20, r*2, r*2);
  }
  blendMode(BLEND);
}
