let cnv;
function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep dusk background gradient
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(18, 42, t);
    let g = lerp(22, 30, t);
    let b = lerp(48, 55, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Subtle noise texture for painterly feel
  noStroke();
  for (let i = 0; i < 9000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.004, y * 0.004);
    fill(255, 240, 220, n * 18);
    ellipse(x, y, random(1, 3));
  }

  // Window frame — a large arched interior
  push();
  let wx = 200, wy = 260, ww = 1200, wh = 1480;
  // Window interior (night sky beyond)
  noStroke();
  // vertical gradient inside window
  for (let y = wy; y < wy + wh; y++) {
    let t = (y - wy) / wh;
    let r = lerp(10, 28, t);
    let g = lerp(14, 20, t);
    let b = lerp(38, 42, t);
    fill(r, g, b);
    rect(wx, y, ww, 1);
  }

  // Arch mask: top is arched — draw dusk background over corners
  fill(red(get(0,0)), green(get(0,0)), blue(get(0,0)));
  // Repaint arch corners with dusk gradient by clipping with shapes:
  // simpler: draw dusk-colored arcs covering corners
  noStroke();
  for (let i = 0; i < 2; i++) {
    let cx = (i === 0) ? wx : wx + ww;
    for (let r = 0; r < 600; r++) {
      let yy = wy + r;
      let t = yy / height;
      let rr = lerp(18, 42, t);
      let gg = lerp(22, 30, t);
      let bb = lerp(48, 55, t);
      fill(rr, gg, bb);
      // corner cover rectangles with arch cut
      // skip — handled below via arch overlay
    }
  }

  // Draw an arch overlay: cover top corners of window with background color
  // Use a shape: rectangle top with semicircle cut
  // Easier: draw background-colored shape covering corners
  push();
  noStroke();
  // Top-left corner
  beginShape();
  vertex(wx, wy);
  vertex(wx + ww/2, wy);
  // arch curve
  for (let a = -PI; a <= 0; a += 0.02) {
    let ax = wx + ww/2 + cos(a) * ww/2;
    let ay = wy + ww/2 + sin(a) * ww/2;
    vertex(ax, ay);
  }
  vertex(wx + ww, wy);
  vertex(wx + ww, wy - 10);
  vertex(wx, wy - 10);
  endShape(CLOSE);
  // Fill with dusk gradient-ish color
  // Actually we want to erase arch corners back to dusk background
  pop();

  // Simpler: draw dusk over corners by sampling background columns
  loadPixels();
  pop();

  // Redo with cleaner approach: draw everything fresh
  // Reset and redraw properly
  drawScene();
}

function drawScene() {
  // Background dusk gradient
  noStroke();
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(20, 45, t);
    let g = lerp(24, 32, t);
    let b = lerp(52, 58, t);
    fill(r, g, b);
    rect(0, y, width, 1);
  }

  // Grainy texture
  for (let i = 0; i < 12000; i++) {
    let x = random(width);
    let y = random(height);
    fill(255, 235, 210, random(5, 25));
    ellipse(x, y, random(1, 2.5));
  }

  // Window arch interior
  let wx = 240, wy = 300, ww = 1120, wh = 1420;
  let archR = ww / 2;
  let archCy = wy + archR;

  // Clip region: arched window
  push();
  // Draw window interior shape
  beginShape();
  vertex(wx, wy + wh);
  vertex(wx, archCy);
  for (let a = PI; a <= PI * 2; a += 0.01) {
    vertex(wx + archR + cos(a) * archR, archCy + sin(a) * archR);
  }
  vertex(wx + ww, archCy);
  vertex(wx + ww, wy + wh);
  endShape(CLOSE);
  // Fill above shape with night interior gradient
  // Use drawingContext clip
  drawingContext.save();
  drawingContext.beginPath();
  drawingContext.moveTo(wx, wy + wh);
  drawingContext.lineTo(wx, archCy);
  drawingContext.arc(wx + archR, archCy, archR, PI, 2*PI);
  drawingContext.lineTo(wx + ww, wy + wh);
  drawingContext.closePath();
  drawingContext.clip();

  // Night sky gradient inside window
  for (let y = wy - 50; y < wy + wh + 10; y++) {
    let t = (y - (wy - 50)) / (wh + 60);
    let r = lerp(8, 30, t);
    let g = lerp(10, 22, t);
    let b = lerp(32, 45, t);
    fill(r, g, b);
    rect(wx - 5, y, ww + 10, 1);
  }

  // Distant stars
  for (let i = 0; i < 180; i++) {
    let x = wx + random(ww);
    let y = wy + random(wh * 0.7);
    let s = random(1, 3);
    fill(255, 240, 210, random(100, 220));
    ellipse(x, y, s);
  }

  // Distant hills silhouette
  fill(14, 16, 32);
  beginShape();
  vertex(wx, wy + wh * 0.72);
  for (let x = wx; x <= wx + ww; x += 20) {
    let y = wy + wh * 0.72 + noise(x * 0.004) * 80 - 40;
    vertex(x, y);
  }
  vertex(wx + ww, wy + wh);
  vertex(wx, wy + wh);
  endShape(CLOSE);

  // Sill inside the window (near)
  fill(30, 22, 28);
  rect(wx, wy + wh - 120, ww, 120);

  // Two lamps — glowing orbs, warm colors, slightly leaning toward each other
  let lx1 = wx + ww * 0.36;
  let lx2 = wx + ww * 0.64;
  let ly  = wy + wh * 0.58;

  // Lamp bases (simple stems)
  stroke(40, 28, 24);
  strokeWeight(6);
  line(lx1, ly + 90, lx1 + 10, wy + wh - 120);
  line(lx2, ly + 90, lx2 - 10, wy + wh - 120);
  noStroke();
  fill(50, 34, 28);
  ellipse(lx1 + 10, wy + wh - 118, 90, 20);
  ellipse(lx2 - 10, wy + wh - 118, 90, 20);

  // Glow halos — big soft radial
  drawGlow(lx1, ly, 520, color(255, 170, 90));
  drawGlow(lx2, ly, 520, color(255, 140, 180));

  // Overlap zone — third color (warm amber-pink)
  drawGlow((lx1 + lx2)/2, ly, 360, color(255, 210, 160), 0.6);

  // Lamp orbs themselves
  // Left: warm gold
  for (let r = 180; r > 0; r -= 2) {
    let a = map(r, 0, 180, 255, 0);
    fill(255, 200, 120, a * 0.25);
    ellipse(lx1, ly, r);
  }
  fill(255, 240, 200);
  ellipse(lx1, ly, 90);
  fill(255, 255, 230);
  ellipse(lx1, ly, 55);

  // Right: warm rose
  for (let r = 180; r > 0; r -= 2) {
    let a = map(r, 0, 180, 255, 0);
    fill(255, 170, 190, a * 0.25);
    ellipse(lx2, ly, r);
  }
  fill(255, 215, 220);
  ellipse(lx2, ly, 90);
  fill(255, 245, 240);
  ellipse(lx2, ly, 55);

  drawingContext.restore();
  pop();

  // Window frame (arched)
  noFill();
  stroke(18, 14, 20);
  strokeWeight(22);
  // Arch top
  arc(wx + archR, archCy, ww, ww, PI, 2*PI);
  // Sides
  line(wx, archCy, wx, wy + wh);
  line(wx + ww, archCy, wx + ww, wy + wh);
  // Bottom
  line(wx - 11, wy + wh, wx + ww + 11, wy + wh);
  // Mullions — a cross dividing panes
  strokeWeight(14);
  line(wx, archCy + (wh - archR) * 0.5 + 40, wx + ww, archCy + (wh - archR) * 0.5 + 40);
  line(wx + archR, wy + 10, wx + archR, wy + wh);

  // Inner shadow on frame
  noStroke();
  fill(0, 0, 0, 60);
  // soft edges
  for (let i = 0; i < 20; i++) {
    noFill();
    stroke(0, 0, 0, 10);
    strokeWeight(2);
    arc(wx + archR, archCy, ww - i*2, ww - i*2, PI, 2*PI);
    line(wx + i, archCy, wx + i, wy + wh);
    line(wx + ww - i, archCy, wx + ww - i, wy + wh);
  }

  // Warm light spilling onto floor/wall in front of window
  noStroke();
  for (let r = 900; r > 0; r -= 10) {
    let a = map(r, 0, 900, 120, 0);
    fill(255, 180, 130, a * 0.08);
    ellipse(width/2, wy + wh + 180, r * 1.6, r * 0.6);
  }

  // Floor
  fill(28, 20, 24);
  rect(0, wy + wh + 10, width, height - (wy + wh + 10));
  // Floor warm glow reflection
  for (let r = 800; r > 0; r -= 8) {
    let a = map(r, 0, 800, 90, 0);
    fill(255, 170, 120, a * 0.06);
    ellipse(width/2, wy + wh + 120, r * 1.8, r * 0.7);
  }

  // Final vignette
  for (let r = 1200; r < 1800; r += 4) {
    noFill();
    stroke(0, 0, 0, 3);
    strokeWeight(4);
    ellipse(width/2, height/2, r * 1.6, r * 2);
  }
}

function drawGlow(x, y, maxR, col, intensity) {
  intensity = intensity || 1;
  noStroke();
  for (let r = maxR; r > 0; r -= 4) {
    let a = map(r, 0, maxR, 80, 0) * intensity;
    fill(red(col), green(col), blue(col), a * 0.5);
    ellipse(x, y, r);
  }
}

