function drawReflection(x, y, col) {
  let baseY = height * 0.78;
  let dy = baseY - y;
  let ry = baseY + dy * 0.4;
  noStroke();
  for (let i = 20; i > 0; i--) {
    let a = map(i, 0, 20, 2, 25);
    fill(red(col), green(col), blue(col), a);
    ellipse(x, ry + i * 6, 60 - i * 2, 8);
