function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // Deep background - night of being
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(8, 24, t);
    let g = lerp(6, 14, t);
    let b = lerp(20, 32, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Scattered stars - the vastness
  noStroke();
  for (let i = 0; i < 400; i++) {
    let x = random(width);
    let y = random(height);
    let s = random(0.3, 2.2);
    let a = random(40, 180);
    fill(255, 250, 230, a);
    circle(x, y, s);
  }

  // Two centers of gravity
  let cx1 = width * 0.38;
  let cy1 = height * 0.46;
  let cx2 = width * 0.62;
  let cy2 = height * 0.54;

  // Field lines curving between them - the orbit/pull
  push();
  blendMode(ADD);
  for (let i = 0; i < 220; i++) {
    let angle = random(TWO_PI);
    let r0 = random(20, 380);
    let sx = cx1 + cos(angle) * r0;
    let sy = cy1 + sin(angle) * r0;
    drawFieldLine(sx, sy, cx1, cy1, cx2, cy2, color(230, 140, 90, 18));
  }
  for (let i = 0; i < 220; i++) {
    let angle = random(TWO_PI);
    let r0 = random(20, 380);
    let sx = cx2 + cos(angle) * r0;
    let sy = cy2 + sin(angle) * r0;
    drawFieldLine(sx, sy, cx2, cy2, cx1, cy1, color(90, 150, 230, 18));
  }
  pop();

  // Two glowing orbs - two distinct beings
  drawOrb(cx1, cy1, 180, color(255, 160, 110), color(220, 70, 60));
  drawOrb(cx2, cy2, 180, color(130, 180, 255), color(60, 90, 200));

  // The third light - where fields overlap, born of neither
  let mx = (cx1 + cx2) / 2;
  let my = (cy1 + cy2) / 2;
  push();
  blendMode(ADD);
  for (let r = 300; r > 0; r -= 2) {
    let a = map(r, 0, 300, 90, 0);
    fill(255, 240, 210, a);
    noStroke();
    circle(mx, my, r);
  }
  for (let r = 60; r > 0; r -= 1) {
    let a = map(r, 0, 60, 255, 0);
    fill(255, 250, 235, a);
    circle(mx, my, r);
  }
  pop();

  // Subtle dust motes near the union
  noStroke();
  for (let i = 0; i < 180; i++) {
    let a = random(TWO_PI);
    let d = randomGaussian(0, 160);
    let x = mx + cos(a) * d;
    let y = my + sin(a) * d * 0.6;
    fill(255, 230, 190, random(30, 120));
    circle(x, y, random(0.5, 2));
  }

  // Vignette - the frame of mystery
  push();
  noFill();
  for (let i = 0; i < 180; i++) {
    stroke(5, 4, 15, 4);
    strokeWeight(i * 2);
    noFill();
    rect(-i, -i, width + 2 * i, height + 2 * i);
  }
  pop();
}

function drawFieldLine(sx, sy, ax, ay, bx, by, col) {
  stroke(col);
  strokeWeight(0.7);
  noFill();
  let x = sx, y = sy;
  for (let step = 0; step < 90; step++) {
    let dxa = ax - x, dya = ay - y;
    let da = sqrt(dxa * dxa + dya * dya) + 1;
    let dxb = bx - x, dyb = by - y;
    let db = sqrt(dxb * dxb + dyb * dyb) + 1;
    // pull toward own center, slight pull toward partner (orbital influence)
    let fx = (dxa / da) * 2.0 + (dxb / db) * 0.6;
    let fy = (dya / da) * 2.0 + (dyb / db) * 0.6;
    // tangential component for orbit
    let tx = -fy, ty = fx;
    let nx = x + fx * 0.5 + tx * 1.8;
    let ny = y + fy * 0.5 + ty * 1.8;
    line(x, y, nx, ny);
    x = nx; y = ny;
    if (x < 0 || x > width || y < 0 || y > height) break;
  }
}

function drawOrb(cx, cy, R, cInner, cOuter) {
  push();
  blendMode(ADD);
  noStroke();
  for (let r = R * 2.2; r > 0; r -= 2) {
    let t = r / (R * 2.2);
    let a = pow(1 - t, 2.4) * 60;
    fill(red(cOuter), green(cOuter), blue(cOuter), a);
    circle(cx, cy, r);
  }
  pop();
  noStroke();
  for (let r = R; r > 0; r -= 1) {
    let t = r / R;
    let c = lerpColor(cInner, cOuter, t);
    fill(c);
    circle(cx, cy, r);
  }
  // highlight
  fill(255, 255, 240, 180);
  circle(cx - R * 0.18, cy - R * 0.22, R * 0.25);
  fill(255, 255, 255, 80);
  circle(cx - R * 0.22, cy - R * 0.28, R * 0.12);
}

