      let d=sqrt(dx*dx+dy*dy)/1200;
      let base = 8 + n*18 - d*10 + n2*20;
      let r = base + 6;
      let g = base + 2;
      let b = base + 18;
      let idx=(x+y*width)*4;
      pixels[idx]=r; pixels[idx+1]=g; pixels[idx+2]=b; pixels[idx+3]=255;
    }
  }
  updatePixels();

  // Two centers
  let A = {x:640, y:900, hue:[255,160,110]};  // warm amber
  let B = {x:980, y:1120, hue:[150,180,255]}; // cool blue

