  drawBridge(A,B);

  // Soft halos
  drawGlow(A.x,A.y,520,A.hue,0.9);
  drawGlow(B.x,B.y,520,B.hue,0.9);

  // Overlap warmth
  let mx=(A.x+B.x)/2, my=(A.y+B.y)/2;
  drawGlow(mx,my,340,[255,210,180],0.35);

  // Cores
