    let y = 1380 + sin(t * PI) * -40;
    fill(255, 240, 200, 220);
    ellipse(x, y, random(2, 5));
  }

  // Sol — herbe sombre suggérée par traits
  stroke(30, 40, 55);
  strokeWeight(1);
  for (let i = 0; i < 2500; i++) {
    let x = random(width);
    let y = random(1650, 2000);
    let h = random(5, 25);
    stroke(lerp(40, 20, random()), lerp(50, 30, random()), lerp(60, 40, random()), 180);
    line(x, y, x + random(-2, 2), y - h);
  }
  noStroke();

  // Reflet chaud au sol sous les figures
  for (let i = 0; i < 60; i++) {
    fill(220, 120, 80, 3);
    ellipse(800, 1780, 900 - i * 10, 100 - i);
  }

  // Vignettage
  for (let i = 0; i < 300; i++) {
    noFill();
    stroke(0, 0, 0, 2);
    strokeWeight(2);
    ellipse(width / 2, height / 2, width + 400 - i * 4, height + 400 - i * 4);
  }
  noStroke();

  // Craquelures / touches de pinceau sur toute la toile
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = random(height);
    let len = random(10, 60);
    let ang = random(TWO_PI);
    stroke(255, 240, 220, random(5, 25));
    strokeWeight(random(0.5, 1.5));
    line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }
}

function drawFigure(cx, cy, tilt, cBody, cGlow) {
  push();
  translate(cx, cy);
  rotate(tilt);

  // halo chaud autour
  noStroke();
  for (let i = 30; i > 0; i--) {
    fill(red(cGlow), green(cGlow), blue(cGlow), 4);
    ellipse(0, -100, 300 + i * 10, 500 + i * 10);
  }

  // corps — forme allongée style flamme
  fill(cBody);
  beginShape();
  vertex(-80, 200);
  bezierVertex(-140, 50, -120, -100, -40, -250);
  bezierVertex(-10, -320, 10, -320, 40, -250);
  bezierVertex(120, -100, 140, 50, 80, 200);
  bezierVertex(40, 240, -40, 240, -80, 200);
  endShape(CLOSE);

  // nuances intérieures
  fill(red(cGlow), green(cGlow), blue(cGlow), 180);
  beginShape();
  vertex(-50, 150);
  bezierVertex(-90, 30, -80, -80, -25, -200);
  bezierVertex(-5, -250, 5, -250, 25, -200);
  bezierVertex(80, -80, 90, 30, 50, 150);
  bezierVertex(20, 180, -20, 180, -50, 150);
  endShape(CLOSE);

  // tête — petite sphère lumineuse
  for (let r = 70; r > 0; r -= 2) {
    let t = r / 70;
    fill(lerp(255, red(cGlow), 1 - t), lerp(240, green(cGlow), 1 - t), lerp(200, blue(cGlow), 1 - t), 230);
    ellipse(0, -300, r * 2);
  }

  // cœur lumineux dans la poitrine
  for (let r = 25; r > 0; r -= 1) {
    fill(255, 230, 180, map(r, 0, 25, 220, 40));
    ellipse(0, -80, r * 2);
  }

  pop();
}

