function drawRiver(cfg) {
  for (let s = 0; s < cfg.strands; s++) {
    let offset = map(s, 0, cfg.strands, -cfg.thicknessBase, cfg.thicknessBase);
    let col = cfg.palette[floor(random(cfg.palette.length))];
    let alpha = random(40, 160);
    stroke(col[0], col[1], col[2], alpha);
    strokeWeight(random(1, 3.2));
    noFill();

    beginShape();
    let steps = 120;
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      // Trajectoire courbe (Bezier-like)
      let cx1 = lerp(cfg.startX, cfg.endX, 0.33) + cfg.sway;
      let cy1 = lerp(cfg.startY, cfg.endY, 0.33) - 80;
      let cx2 = lerp(cfg.startX, cfg.endX, 0.66) + cfg.sway * 0.3;
      let cy2 = lerp(cfg.startY, cfg.endY, 0.66) + 40;

      let x = bezierPoint(cfg.startX, cx1, cx2, cfg.endX, t);
      let y = bezierPoint(cfg.startY, cy1, cy2, cfg.endY, t);

      // Décalage perpendiculaire (épaisseur du courant)
      let tx = bezierTangent(cfg.startX, cx1, cx2, cfg.endX, t);
      let ty = bezierTangent(cfg.startY, cy1, cy2, cfg.endY, t);
      let len = sqrt(tx * tx + ty * ty);
      let nx = -ty / len;
      let ny = tx / len;

      // Épaisseur variable : fine au départ, large au centre
      let swell = sin(t * PI) * 1.4 + 0.3;
      let localOffset = offset * swell;

      // Bruit organique
      let nz = noise(t * 3 + s * 0.05, s * 0.1) - 0.5;
      localOffset += nz * 80 * swell;

      let px = x + nx * localOffset;
      let py = y + ny * localOffset;

      curveVertex(px, py);
    }
    endShape();
  }

  // Points lumineux le long du courant
  for (let i = 0; i < 300; i++) {
    let t = random(0.1, 1);
    let cx1 = lerp(cfg.startX, cfg.endX, 0.33) + cfg.sway;
    let cy1 = lerp(cfg.startY, cfg.endY, 0.33) - 80;
    let cx2 = lerp(cfg.startX, cfg.endX, 0.66) + cfg.sway * 0.3;
    let cy2 = lerp(cfg.startY, cfg.endY, 0.66) + 40;
    let x = bezierPoint(cfg.startX, cx1, cx2, cfg.endX, t);
    let y = bezierPoint(cfg.startY, cy1, cy2, cfg.endY, t);
    let swell = sin(t * PI) * 1.4 + 0.3;
    let off = random(-cfg.thicknessBase, cfg.thicknessBase) * swell;
    let tx = bezierTangent(cfg.startX, cx1, cx2, cfg.endX, t);
    let ty = bezierTangent(cfg.startY, cy1, cy2, cfg.endY, t);
    let len = sqrt(tx * tx + ty * ty);
    let nx = -ty / len;
    let ny = tx / len;
    let px = x + nx * off;
    let py = y + ny * off;
    let col = cfg.palette[floor(random(cfg.palette.length))];
    noStroke();
    fill(col[0] + 30, col[1] + 30, col[2] + 30, random(100, 220));
    circle(px, py, random(2, 6));
  }
}

function drawConfluence() {
  // Flux descendant après la rencontre : tresse violet-doré
  let startX = width / 2;
  let startY = height / 2 + 60;
  let endX = width / 2;
  let endY = height + 100;

  let palette = [
    [180, 90, 150],
    [220, 140, 160],
    [240, 180, 130],
    [150, 110, 200],
    [255, 200, 170],
    [120, 140, 210]
  ];

  for (let s = 0; s < 220; s++) {
    let col = palette[floor(random(palette.length))];
    stroke(col[0], col[1], col[2], random(50, 170));
    strokeWeight(random(1, 3));
    noFill();
    beginShape();
    let steps = 100;
    let phase = random(TWO_PI);
    let amp = random(60, 220);
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let y = lerp(startY, endY, t);
      let widen = pow(t, 0.7);
      let x = startX + sin(t * PI * 2.2 + phase) * amp * widen;
      x += (noise(t * 2 + s * 0.1, s) - 0.5) * 80;
      curveVertex(x, y);
    }
    endShape();
  }

  // Gouttes / étincelles de la fusion
  for (let i = 0; i < 500; i++) {
    let t = random(0, 1);
    let y = lerp(startY, endY, t);
    let x = startX + random(-250 * pow(t, 0.7), 250 * pow(t, 0.7));
    let col = palette[floor(random(palette.length))];
    noStroke();
    fill(col[0] + 20, col[1] + 20, col[2] + 20, random(120, 230));
    circle(x, y, random(2, 7));
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Fond : dégradé nuit profonde vers prune
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(18, 42, t);
    let g = lerp(14, 20, t);
    let b = lerp(34, 48, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Grain de fond
  noStroke();
  for (let i = 0; i < 9000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.003, y * 0.003);
    fill(255, 230, 210, n * 25);
    rect(x, y, 2, 2);
  }

  // Poussière d'étoiles diffuses
  for (let i = 0; i < 400; i++) {
    let x = random(width);
    let y = random(height);
    let s = random(0.5, 2.2);
    fill(255, 240, 220, random(40, 140));
    ellipse(x, y, s, s);
  }

  // Centres des deux noyaux
  let cx1 = width * 0.40;
  let cy1 = height * 0.46;
  let cx2 = width * 0.60;
  let cy2 = height * 0.54;

  // Champ d'interférence : lignes courbes entre les deux
  push();
  blendMode(ADD);
  for (let i = 0; i < 220; i++) {
    let a = random(TWO_PI);
    let r = random(80, 520);
    let x0 = (cx1 + cx2) / 2 + cos(a) * r * 0.6;
    let y0 = (cy1 + cy2) / 2 + sin(a) * r;
    noFill();
    stroke(180, 120, 160, 18);
    strokeWeight(1);
    beginShape();
    for (let t = 0; t <= 1; t += 0.05) {
      let x = lerp(x0, (cx1 + cx2) / 2, t) + sin(t * PI * 2 + i) * 30;
      let y = lerp(y0, (cy1 + cy2) / 2, t) + cos(t * PI * 3 + i) * 30;
      vertex(x, y);
    }
    endShape();
  }
  pop();

  // Halo du noyau 1 (chaud, ambre-rose)
  drawHalo(cx1, cy1, 650, [255, 170, 120], [230, 90, 130]);

  // Halo du noyau 2 (froid, cyan-violet)
  drawHalo(cx2, cy2, 650, [140, 200, 240], [120, 110, 220]);

  // Zone de chevauchement : lumière dorée douce
  push();
  blendMode(SCREEN);
  let mx = (cx1 + cx2) / 2;
  let my = (cy1 + cy2) / 2;
  for (let r = 300; r > 0; r -= 6) {
    let a = map(r, 0, 300, 90, 0);
    fill(255, 220, 160, a);
    noStroke();
    ellipse(mx, my, r * 2.2, r * 1.4);
  }
  pop();

  // Noyau 1 : disque dense
  drawCore(cx1, cy1, 180, [255, 220, 180], [240, 110, 110]);

  // Noyau 2 : disque dense
  drawCore(cx2, cy2, 180, [210, 230, 255], [110, 120, 220]);

  // Filaments orbitaux autour des deux
  drawOrbit(cx1, cy1, cx2, cy2, 255, 180, 140);
  drawOrbit(cx2, cy2, cx1, cy1, 160, 190, 255);

  // Petites particules lumineuses au centre
  push();
  blendMode(ADD);
  for (let i = 0; i < 300; i++) {
    let a = random(TWO_PI);
    let r = random(0, 260);
    let x = mx + cos(a) * r * 1.4;
    let y = my + sin(a) * r * 0.8;
    let s = random(1, 4);
    fill(255, 230, 190, random(80, 200));
    noStroke();
    ellipse(x, y, s, s);
  }
  pop();

  // Vignette
  push();
  noFill();
  for (let i = 0; i < 180; i++) {
    stroke(10, 6, 20, 2.5);
    strokeWeight(1);
    rect(i, i, width - i * 2, height - i * 2);
  }
  pop();

  // Grain final
  noStroke();
  for (let i = 0; i < 20000; i++) {
    fill(random(255), random(50, 110));
    rect(random(width), random(height), 1, 1);
  }
}

function drawHalo(cx, cy, maxR, cInner, cOuter) {
  push();
  blendMode(ADD);
  noStroke();
  for (let r = maxR; r > 0; r -= 4) {
    let t = r / maxR;
    let col = lerpColor(color(cInner[0], cInner[1], cInner[2]),
                       color(cOuter[0], cOuter[1], cOuter[2]), t);
    let a = (1 - t) * 40;
    fill(red(col), green(col), blue(col), a);
    ellipse(cx, cy, r * 2, r * 2);
  }
  pop();
}

function drawCore(cx, cy, maxR, cInner, cOuter) {
  push();
  noStroke();
  for (let r = maxR; r > 0; r -= 2) {
    let t = r / maxR;
    let col = lerpColor(color(cInner[0], cInner[1], cInner[2]),
                       color(cOuter[0], cOuter[1], cOuter[2]), t);
    fill(red(col), green(col), blue(col), 220 - t * 100);
    ellipse(cx + random(-1, 1), cy + random(-1, 1), r * 2, r * 2);
  }
  // Highlight
  fill(255, 255, 240, 200);
  ellipse(cx - maxR * 0.25, cy - maxR * 0.25, maxR * 0.5, maxR * 0.4);
  pop();
}

function drawOrbit(cx, cy, tx, ty, rC, gC, bC) {
  push();
  blendMode(ADD);
  noFill();
  let angleToOther = atan2(ty - cy, tx - cx);
  for (let i = 0; i < 6; i++) {
    stroke(rC, gC, bC, 40 + i * 5);
    strokeWeight(1.2);
    push();
    translate(cx, cy);
    rotate(angleToOther + random(-0.3, 0.3));
    let rx = 260 + i * 25;
    let ry = 90 + i * 12;
    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.05) {
      let nx = cos(a) * rx + random(-4, 4);
      let ny = sin(a) * ry + random(-4, 4);
      vertex(nx, ny);
    }
    endShape(CLOSE);
    pop();
  }
  pop();
}

let cnv;
function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Fond nuit profonde avec dégradé
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(18, 32, t);
    let g = lerp(14, 20, t);
    let b = lerp(40, 55, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Texture de respiration (grain de noise)
  loadPixels();
  for (let i = 0; i < 90000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.002, y * 0.002);
    let a = map(n, 0, 1, 0, 40);
    stroke(255, 240, 220, a * random(0.3, 1));
    point(x, y);
  }

  // Deux centres
  let cxA = width * 0.38;
  let cyA = height * 0.42;
  let cxB = width * 0.64;
  let cyB = height * 0.58;

  // Champ de particules entre les deux (orbites)
  drawField(cxA, cyA, cxB, cyB);

  // Halos diffus
  drawHalo(cxA, cyA, 520, color(255, 180, 120, 18), color(255, 90, 60, 0));
  drawHalo(cxB, cyB, 520, color(130, 180, 255, 18), color(60, 90, 200, 0));

  // Noyaux de lumière
  drawCore(cxA, cyA, 180, color(255, 230, 190), color(255, 120, 70));
  drawCore(cxB, cyB, 170, color(220, 235, 255), color(90, 130, 230));

  // Filaments reliant
  drawFilaments(cxA, cyA, cxB, cyB);

  // Poussière d'étoiles
  for (let i = 0; i < 1400; i++) {
    let x = random(width);
    let y = random(height);
    let s = random(0.3, 2.2);
    let a = random(40, 200);
    noStroke();
    fill(255, 250, 230, a);
    circle(x, y, s);
  }

  // Vignettage
  for (let r = 0; r < 400; r += 2) {
    noFill();
    stroke(10, 8, 20, map(r, 0, 400, 80, 0));
    rect(r, r, width - 2 * r, height - 2 * r);
  }
}

function drawHalo(cx, cy, R, c1, c2) {
  noStroke();
  for (let r = R; r > 0; r -= 3) {
    let t = r / R;
    let c = lerpColor(c1, c2, 1 - t);
    fill(c);
    circle(cx, cy, r * 2);
  }
}

function drawCore(cx, cy, R, cIn, cOut) {
  noStroke();
  for (let r = R; r > 0; r -= 1) {
    let t = r / R;
    let c = lerpColor(cIn, cOut, t);
    c.setAlpha(map(t, 0, 1, 255, 30));
    fill(c);
    circle(cx, cy, r * 2);
  }
  // cœur ultra-brillant
  fill(255, 255, 240, 230);
  circle(cx, cy, R * 0.35);
}

function drawField(ax, ay, bx, by) {
  // particules qui orbitent et hésitent entre les deux pôles
  for (let i = 0; i < 9000; i++) {
    let t = random();
    // position de départ biaisée vers la ligne qui relie
    let mx = lerp(ax, bx, t) + random(-300, 300);
    let my = lerp(ay, by, t) + random(-250, 250);

    // perturbation par noise
    let n = noise(mx * 0.003, my * 0.003);
    let ang = n * TWO_PI * 2;
    let rad = random(0, 180) * (1 - abs(0.5 - t) * 1.2);
    let x = mx + cos(ang) * rad;
    let y = my + sin(ang) * rad;

    // couleur selon proximité
    let dA = dist(x, y, ax, ay);
    let dB = dist(x, y, bx, by);
    let ratio = dA / (dA + dB);
    let warm = color(255, 170, 110);
    let cool = color(140, 180, 255);
    let c = lerpColor(warm, cool, ratio);
    c.setAlpha(random(30, 120));
    noStroke();
    fill(c);
    circle(x, y, random(1, 3));
  }
}

function drawFilaments(ax, ay, bx, by) {
  // courbes fines reliant les deux noyaux
  for (let k = 0; k < 40; k++) {
    let offset = random(-180, 180);
    let midx = (ax + bx) / 2 + random(-60, 60);
    let midy = (ay + by) / 2 + offset;

    noFill();
    let c = lerpColor(color(255, 200, 150), color(180, 200, 255), random());
    c.setAlpha(random(20, 70));
    stroke(c);
    strokeWeight(random(0.5, 1.5));
    beginShape();
    for (let t = 0; t <= 1; t += 0.02) {
      let x = bezierPoint(ax, ax + 100, bx - 100, bx, t);
      let y = bezierPoint(ay, midy, midy, by, t);
      // léger bruit
      x += (noise(t * 5, k) - 0.5) * 20;
      y += (noise(t * 5, k + 10) - 0.5) * 20;
      vertex(x, y);
    }
    endShape();
  }
}

