    fill(255, 245, 220, random(100, 220));
    circle(x, y, random(1.2, 3.5));
  }

  // Horizon diffus
  for (let i = 0; i < 400; i++) {
    let y = height * 0.78 + random(-40, 40);
    fill(60, 40, 70, 8);
    rect(0, y, width, random(2, 8));
  }

  // Positions des deux présences
  let cx1 = width * 0.38;
  let cy1 = height * 0.52;
  let cx2 = width * 0.62;
  let cy2 = height * 0.50;

  // Auras larges qui se chevauchent
  drawAura(cx1, cy1, 820, color(255, 140, 90), color(255, 60, 110));
  drawAura(cx2, cy2, 820, color(120, 180, 255), color(80, 100, 220));

  // Zone de rencontre lumineuse
  blendMode(SCREEN);
  for (let r = 400; r > 0; r -= 6) {
    let a = map(r, 0, 400, 60, 0);
    fill(255, 230, 200, a);
    ellipse((cx1 + cx2) / 2, (cy1 + cy2) / 2, r * 1.6, r);
  }
  blendMode(BLEND);

  // Corps des deux présences — formes douces, verticales
  drawPresence(cx1, cy1, color(255, 200, 170), color(200, 70, 90), 1);
  drawPresence(cx2, cy2, color(200, 220, 255), color(70, 90, 180), -1);

  // Fils ténus entre les deux (traits de lumière)
  stroke(255, 240, 220, 70);
  strokeWeight(1);
  noFill();
  for (let i = 0; i < 40; i++) {
    let t = i / 40;
    beginShape();
    for (let s = 0; s <= 1; s += 0.02) {
      let x = lerp(cx1, cx2, s) + sin(s * PI * 3 + i) * 20 * sin(s * PI);
      let y = lerp(cy1, cy2, s) + cos(s * PI * 2 + i * 0.7) * 30 * sin(s * PI);
      vertex(x, y);
    }
    endShape();
  }

  // Grain final
  noStroke();
  for (let i = 0; i < 20000; i++) {
    fill(0, random(10, 30));
    rect(random(width), random(height), 1, 1);
  }
  for (let i = 0; i < 8000; i++) {
    fill(255, random(5, 20));
    rect(random(width), random(height), 1, 1);
  }

  // Vignettage
  for (let r = 0; r < 600; r += 4) {
    noFill();
    stroke(10, 8, 20, map(r, 0, 600, 90, 0));
    strokeWeight(4);
    ellipse(width / 2, height / 2, width * 1.4 + r, height * 1.4 + r);
  }
}

function drawAura(cx, cy, maxR, cInner, cOuter) {
  noStroke();
  for (let r = maxR; r > 0; r -= 4) {
    let t = r / maxR;
    let c = lerpColor(cInner, cOuter, t);
    c.setAlpha(map(t, 0, 1, 55, 0));
    fill(c);
    let wobble = noise(r * 0.01, cx * 0.001) * 30;
    ellipse(cx, cy, r * 2 + wobble, r * 2.2 + wobble);
  }
}

function drawPresence(cx, cy, cLight, cDark, dir) {
  noStroke();
  // Halo intérieur
  for (let r = 260; r > 0; r -= 3) {
    let t = r / 260;
    let c = lerpColor(cLight, cDark, t);
    c.setAlpha(map(t, 0, 1, 200, 0));
    fill(c);
    let w = r * 1.4 + sin(r * 0.05) * 8;
    let h = r * 2.2;
    ellipse(cx + dir * sin(r * 0.02) * 6, cy, w, h);
  }
  // Noyau lumineux
  for (let r = 90; r > 0; r -= 2) {
    let a = map(r, 0, 90, 255, 0);
    fill(255, 245, 220, a);
    ellipse(cx, cy - 20, r * 0.9, r * 1.6);
  }
  // Petites particules autour
  for (let i = 0; i < 120; i++) {
    let ang = random(TWO_PI);
    let rad = random(80, 320);
    let x = cx + cos(ang) * rad;
    let y = cy + sin(ang) * rad * 1.1;
    fill(red(cLight), green(cLight), blue(cLight), random(40, 160));
    circle(x, y, random(1, 4));
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Fond : nuit profonde, chaude, avec un léger dégradé
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(18, 38, t);
    let g = lerp(14, 20, t);
    let b = lerp(32, 28, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Grain / étoiles diffuses
  noStroke();
  for (let i = 0; i < 1800; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.003, y * 0.003);
    fill(255, 220, 180, n * 40);
    ellipse(x, y, random(0.5, 2.2));
  }

  // Quelques étoiles plus vives, lointaines
  for (let i = 0; i < 90; i++) {
    let x = random(width);
    let y = random(height * 0.6);
    fill(255, 240, 210, random(80, 180));
    ellipse(x, y, random(1.5, 3.5));
  }

  // Le halo central — la lumière née entre les deux
  let cx = width / 2;
  let cy = height / 2 + 40;

  // Grand halo diffus
  for (let r = 900; r > 0; r -= 6) {
    let a = map(r, 0, 900, 55, 0);
    let col = lerpColor(color(255, 210, 130, a), color(255, 150, 90, a * 0.6), r / 900);
    fill(col);
    ellipse(cx, cy, r * 1.6, r * 1.3);
  }

  // Coeur du halo — blanc doré
  for (let r = 260; r > 0; r -= 3) {
    let a = map(r, 0, 260, 220, 0);
    fill(255, 240, 200, a);
    ellipse(cx, cy, r, r);
  }
  fill(255, 250, 230, 255);
  ellipse(cx, cy, 70, 70);

  // Rayons subtils
  push();
  translate(cx, cy);
  for (let i = 0; i < 60; i++) {
    let ang = random(TWO_PI);
    let len = random(300, 900);
    stroke(255, 220, 160, random(5, 20));
    strokeWeight(random(0.5, 2));
    line(0, 0, cos(ang) * len, sin(ang) * len);
  }
  pop();

  // Les deux présences — formes abstraites, courbes, se penchant l'une vers l'autre
  drawFigure(cx - 300, cy + 120, -1, color(70, 110, 160), color(180, 200, 240));
  drawFigure(cx + 300, cy + 120, 1, color(160, 70, 90), color(240, 190, 180));

  // Particules de lumière qui montent entre les deux
  noStroke();
  for (let i = 0; i < 400; i++) {
    let t = random();
    let x = cx + random(-120, 120) + sin(t * 10) * 30;
    let y = cy + 300 - t * 700 + random(-20, 20);
    let a = (1 - t) * 200;
    fill(255, 220, 160, a);
    ellipse(x, y, random(2, 6));
  }

  // Vignettage doux
  for (let r = max(width, height); r > 600; r -= 8) {
    noFill();
    stroke(0, 0, 0, 3);
    ellipse(width / 2, height / 2, r * 2.2, r * 2.4);
  }
}

function drawFigure(x, y, dir, cDark, cLight) {
  // Une forme ovoïde penchée, abstraite, comme une silhouette agenouillée
  push();
  translate(x, y);
  rotate(dir * 0.25);

  // Ombre portée
  noStroke();
  fill(0, 0, 0, 80);
  ellipse(0, 420, 380, 60);

  // Corps : empilement de couches pour une texture peinte
  for (let i = 0; i < 180; i++) {
    let t = i / 180;
    let w = lerp(260, 120, t);
    let h = lerp(300, 60, t);
    let yy = lerp(300, -300, t);
    let c = lerpColor(cDark, cLight, t * 0.9);
    c.setAlpha(230);
    fill(c);
    ellipse(random(-3, 3), yy + random(-2, 2), w + random(-6, 6), h);
  }

  // Tête / sommet lumineux (penché vers le centre)
  let headX = -dir * 40;
  let headY = -320;
  for (let r = 120; r > 0; r -= 2) {
    let a = map(r, 0, 120, 255, 0);
    let c = lerpColor(cLight, color(255, 240, 210), 0.6);
    c.setAlpha(a);
    fill(c);
    ellipse(headX, headY, r, r);
  }
  fill(255, 245, 220);
  ellipse(headX, headY, 50, 50);

  // Coup de pinceau de lumière le long du bord intérieur (face au halo)
  noFill();
  for (let i = 0; i < 40; i++) {
    stroke(255, 220, 170, 60 - i);
    strokeWeight(2 + i * 0.3);
    let s = -dir;
    bezier(s * 80, -280,
           s * 160, -120,
           s * 140, 100,
           s * 60, 300);
  }

  // Touches de pinceau texturées
  noStroke();
  for (let i = 0; i < 300; i++) {
    let px = random(-130, 130);
    let py = random(-280, 280);
    let d = dist(px, py, 0, 0);
    if (d < 180) {
      let c = lerpColor(cDark, cLight, random());
      c.setAlpha(random(30, 100));
      fill(c);
      ellipse(px, py, random(3, 10), random(2, 6));
    }
  }

  pop();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep background - nocturnal, intimate
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(12, 28, t);
    let g = lerp(8, 20, t);
    let b = lerp(30, 45, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Soft noise texture over background
  noStroke();
  for (let i = 0; i < 8000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.002, y * 0.002);
    fill(255, 240, 220, n * 15);
    ellipse(x, y, random(1, 3));
  }

  // Two centers - the two presences
  let c1 = { x: width * 0.38, y: height * 0.48 };
  let c2 = { x: width * 0.62, y: height * 0.52 };

  // The invisible field between them - the space of love
  drawField(c1, c2);

  // Luminous halos
  drawHalo(c1.x, c1.y, 320, color(255, 180, 140));
  drawHalo(c2.x, c2.y, 320, color(180, 200, 255));

  // The two orbs - distinct but curved toward each other
  drawOrb(c1.x, c1.y, 110, color(255, 200, 160), color(220, 100, 90));
  drawOrb(c2.x, c2.y, 110, color(200, 220, 255), color(100, 130, 220));

  // Filaments - threads of connection
  drawFilaments(c1, c2);

  // Floating particles - the vibration of the in-between
  drawParticles(c1, c2);

  // Vignette
  drawVignette();
}

function drawField(c1, c2) {
  let mx = (c1.x + c2.x) / 2;
  let my = (c1.y + c2.y) / 2;
  noStroke();
  for (let r = 600; r > 0; r -= 4) {
    let a = map(r, 0, 600, 40, 0);
    fill(255, 220, 200, a * 0.3);
    ellipse(mx, my, r * 2.2, r * 1.4);
  }
  // curved light lines bending between
  for (let i = 0; i < 60; i++) {
    let t = i / 60;
    stroke(255, 230, 210, 20 + noise(i * 0.1) * 30);
    noFill();
    strokeWeight(0.6);
    beginShape();
    for (let s = 0; s <= 1; s += 0.02) {
      let x = lerp(c1.x, c2.x, s);
      let baseY = lerp(c1.y, c2.y, s);
      let curve = sin(s * PI) * (80 - i * 2.5);
      let n = noise(i * 0.3, s * 3) * 20;
      let y = baseY + curve + n - 40;
      vertex(x, y);
    }
    endShape();
  }
}

function drawHalo(cx, cy, maxR, col) {
  noStroke();
  for (let r = maxR; r > 0; r -= 3) {
    let a = map(r, 0, maxR, 60, 0);
    fill(red(col), green(col), blue(col), a * 0.5);
    ellipse(cx, cy, r * 2);
  }
}

function drawOrb(cx, cy, radius, colLight, colDark) {
  noStroke();
  // outer glow
  for (let r = radius * 1.6; r > radius; r -= 1) {
    let a = map(r, radius, radius * 1.6, 80, 0);
    fill(red(colLight), green(colLight), blue(colLight), a);
    ellipse(cx, cy, r * 2);
  }
  // body with gradient
  for (let r = radius; r > 0; r -= 1) {
    let t = r / radius;
    let c = lerpColor(colDark, colLight, 1 - t * 0.7);
    fill(c);
    ellipse(cx, cy, r * 2);
  }
  // highlight
  fill(255, 255, 240, 120);
  ellipse(cx - radius * 0.3, cy - radius * 0.35, radius * 0.6, radius * 0.5);
  fill(255, 255, 255, 180);
  ellipse(cx - radius * 0.35, cy - radius * 0.4, radius * 0.25, radius * 0.2);
}

function drawFilaments(c1, c2) {
  stroke(255, 230, 200, 80);
  strokeWeight(0.8);
  noFill();
  for (let i = 0; i < 25; i++) {
    beginShape();
    let offset = random(-60, 60);
    let curve = random(-120, 60);
    for (let s = 0; s <= 1; s += 0.02) {
      let x = lerp(c1.x, c2.x, s) + sin(s * PI * 2 + i) * 10;
      let y = lerp(c1.y, c2.y, s) + sin(s * PI) * curve + offset * sin(s * PI);
      let n = (noise(i * 0.5, s * 2) - 0.5) * 30;
      vertex(x + n, y + n);
    }
    endShape();
  }
}

function drawParticles(c1, c2) {
  noStroke();
  let mx = (c1.x + c2.x) / 2;
  let my = (c1.y + c2.y) / 2;
  for (let i = 0; i < 400; i++) {
    let angle = random(TWO_PI);
    let dist = randomGaussian(0, 180);
    let x = mx + cos(angle) * dist * 1.5;
    let y = my + sin(angle) * dist * 0.8;
    let size = random(1, 4);
    let bright = random(150, 255);
    fill(255, bright * 0.9, bright * 0.75, random(80, 200));
    ellipse(x, y, size);
  }
  // scattered stars across whole canvas
  for (let i = 0; i < 200; i++) {
    let x = random(width);
    let y = random(height);
    let s = random(0.5, 2.5);
    fill(255, 240, 220, random(60, 180));
    ellipse(x, y, s);
  }
}

function drawVignette() {
  noFill();
  for (let r = 0; r < 600; r++) {
    stroke(5, 3, 15, r * 0.15);
    let w = width + 400 - r * 2;
    let h = height + 400 - r * 2;
    rect((width - w) / 2, (height - h) / 2, w, h);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  pixelDensity(1);
}

function draw() {
  // Nuit profonde avec dégradé
  loadPixels();
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let d = dist(x, y, width/2, height/2) / (width*0.7);
      let n = noise(x*0.003, y*0.003) * 20;
      let r = 8 + (1-d)*18 + n;
      let g = 6 + (1-d)*14 + n*0.8;
      let b = 20 + (1-d)*30 + n*1.2;
      let idx = (y*width + x)*4;
      pixels[idx] = r;
      pixels[idx+1] = g;
      pixels[idx+2] = b;
      pixels[idx+3] = 255;
    }
  }
  updatePixels();

  // Étoiles lointaines
  for (let i = 0; i < 400; i++) {
    let x = random(width);
    let y = random(height);
    let s = random(0.5, 2.2);
    let a = random(60, 180);
    noStroke();
    fill(255, 240, 220, a);
    circle(x, y, s);
  }

  // Deux centres lumineux
  let cx1 = width*0.38, cy1 = height*0.48;
  let cx2 = width*0.62, cy2 = height*0.52;

  // Halo partagé (troisième espace) - chaud doré
  let mx = (cx1+cx2)/2, my = (cy1+cy2)/2;
  for (let r = 900; r > 0; r -= 4) {
    let t = r/900;
    let a = (1-t)*(1-t) * 55;
    noStroke();
    fill(255, 210, 140, a);
    ellipse(mx, my, r*1.4, r*0.9);
  }

  // Halos individuels
  drawHalo(cx1, cy1, 650, [255, 150, 180]);  // rose chaud
  drawHalo(cx2, cy2, 650, [180, 200, 255]);  // bleu lumineux

  // Zone d'intersection — lueur plus intense
  for (let r = 400; r > 0; r -= 3) {
    let t = r/400;
    let a = (1-t) * 35;
    noStroke();
    fill(255, 230, 200, a);
    circle(mx, my, r);
  }

  // Noyaux
  drawCore(cx1, cy1, [255, 200, 220], [255, 100, 150]);
  drawCore(cx2, cy2, [220, 230, 255], [120, 160, 255]);

  // Filaments reliant les deux noyaux - lignes de force
  stroke(255, 220, 180, 90);
  noFill();
  for (let i = 0; i < 40; i++) {
    strokeWeight(random(0.3, 1.2));
    let offset = random(-80, 80);
    beginShape();
    for (let t = 0; t <= 1; t += 0.02) {
      let x = lerp(cx1, cx2, t);
      let y = lerp(cy1, cy2, t) + sin(t*PI)*offset + noise(t*3, i)*30 - 15;
      vertex(x, y);
    }
    endShape();
  }

  // Particules lumineuses flottantes dans l'espace entre
  for (let i = 0; i < 300; i++) {
    let t = random();
    let x = lerp(cx1, cx2, t) + random(-200, 200);
    let y = lerp(cy1, cy2, t) + random(-250, 250) + sin(t*PI)*random(-100,100);
    let s = random(1, 4);
    noStroke();
    fill(255, random(200,240), random(150,200), random(100, 220));
    circle(x, y, s);
    fill(255, 240, 200, 40);
    circle(x, y, s*3);
  }

  // Petites poussières éparses
  for (let i = 0; i < 1500; i++) {
    let x = random(width);
    let y = random(height);
    let d1 = dist(x, y, cx1, cy1);
    let d2 = dist(x, y, cx2, cy2);
    let dm = min(d1, d2);
    if (dm > 300 && random() < 0.6) {
      noStroke();
      fill(255, 230, 210, random(20, 80));
      circle(x, y, random(0.5, 1.8));
    }
  }

  // Voile atmosphérique final
  noStroke();
  for (let i = 0; i < 20; i++) {
    fill(255, 200, 180, 3);
    let x = random(width);
    let y = random(height);
    ellipse(x, y, random(400, 900), random(200, 500));
  }
}

function drawHalo(cx, cy, maxR, col) {
  for (let r = maxR; r > 0; r -= 3) {
    let t = r/maxR;
    let a = (1-t)*(1-t) * 70;
    noStroke();
    fill(col[0], col[1], col[2], a);
    circle(cx, cy, r);
  }
}

function drawCore(cx, cy, inner, outer) {
  for (let r = 180; r > 0; r -= 2) {
    let t = r/180;
    let a = (1-t) * 180;
    noStroke();
    let cr = lerp(inner[0], outer[0], t);
    let cg = lerp(inner[1], outer[1], t);
    let cb = lerp(inner[2], outer[2], t);
    fill(cr, cg, cb, a);
    circle(cx, cy, r);
  }
  // cœur blanc
  fill(255, 255, 245, 240);
  circle(cx, cy, 40);
  fill(255, 255, 255, 255);
  circle(cx, cy, 18);
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Fond nocturne profond, vibrant
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(18, 42, t);
    let g = lerp(14, 22, t);
    let b = lerp(38, 55, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Grain de fond (poussière d'étoiles diffuse)
  noStroke();
  for (let i = 0; i < 4000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.002, y * 0.002);
    fill(255, 240, 220, n * 25);
    ellipse(x, y, random(1, 2.5));
  }

  // Deux centres : gauche (plus chaud, rouge-orangé) et droit (plus froid, bleu-violet)
  let cxA = width * 0.38;
  let cyA = height * 0.48;
  let cxB = width * 0.62;
  let cyB = height * 0.52;

  // Champ lumineux entre les deux (seuil)
  let mx = (cxA + cxB) / 2;
  let my = (cyA + cyB) / 2;
  for (let r = 900; r > 0; r -= 6) {
    let a = map(r, 0, 900, 55, 0);
    fill(255, 220, 170, a);
    ellipse(mx, my, r * 1.6, r);
  }

  // Halos autour de chaque présence
  drawHalo(cxA, cyA, 700, [255, 120, 80], [255, 200, 140]);
  drawHalo(cxB, cyB, 700, [120, 150, 255], [180, 200, 255]);

  // Filaments entre les deux (respiration partagée)
  drawFilaments(cxA, cyA, cxB, cyB);

  // Noyau A
  drawCore(cxA, cyA, 180, [255, 180, 130], [230, 80, 60]);
  // Noyau B
  drawCore(cxB, cyB, 180, [200, 210, 255], [90, 100, 200]);

  // Étoiles ponctuelles brillantes
  for (let i = 0; i < 180; i++) {
    let x = random(width);
    let y = random(height);
    let s = random(1, 3);
    fill(255, 250, 230, random(120, 220));
    ellipse(x, y, s);
  }

  // Vignette
  for (let r = 0; r < 600; r += 4) {
    noFill();
    stroke(10, 8, 20, map(r, 0, 600, 80, 0));
    strokeWeight(4);
    ellipse(width / 2, height / 2, width * 1.8 - r * 2, height * 1.8 - r * 2);
  }
  noStroke();

  // Texture pinceau subtile
  for (let i = 0; i < 15000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.004, y * 0.004);
    fill(255, 240, 220, n * 10);
    rect(x, y, 2, 2);
  }
}

function drawHalo(cx, cy, maxR, colInner, colOuter) {
  for (let r = maxR; r > 0; r -= 4) {
    let t = r / maxR;
    let a = pow(1 - t, 2) * 90;
    let cr = lerp(colInner[0], colOuter[0], t);
    let cg = lerp(colInner[1], colOuter[1], t);
    let cb = lerp(colInner[2], colOuter[2], t);
    fill(cr, cg, cb, a);
    let wobble = noise(r * 0.01, cx * 0.001) * 40;
    ellipse(cx, cy, r * 2 + wobble, r * 2 + wobble);
  }
}

function drawCore(cx, cy, maxR, cInner, cOuter) {
  for (let r = maxR; r > 0; r -= 2) {
    let t = r / maxR;
    let cr = lerp(cInner[0], cOuter[0], t);
    let cg = lerp(cInner[1], cOuter[1], t);
    let cb = lerp(cInner[2], cOuter[2], t);
    fill(cr, cg, cb, 200 - t * 100);
    ellipse(cx, cy, r * 2, r * 2);
  }
  // point de lumière
  fill(255, 250, 240, 230);
  ellipse(cx - maxR * 0.2, cy - maxR * 0.2, maxR * 0.4);
}

function drawFilaments(x1, y1, x2, y2) {
  for (let k = 0; k < 60; k++) {
    let steps = 120;
    let offsetSeed = random(1000);
    let hueMix = random();
    let col;
    if (hueMix < 0.33) col = color(255, 180, 140, 90);
    else if (hueMix < 0.66) col = color(180, 170, 230, 80);
    else col = color(255, 220, 180, 70);
    stroke(col);
    strokeWeight(random(0.5, 2));
    noFill();
    beginShape();
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let bx = lerp(x1, x2, t);
      let by = lerp(y1, y2, t);
      let n1 = noise(offsetSeed + t * 3) - 0.5;
      let n2 = noise(offsetSeed + 100 + t * 3) - 0.5;
      let amp = sin(t * PI) * 220;
      bx += n1 * amp;
      by += n2 * amp * 0.8;
      curveVertex(bx, by);
    }
    endShape();
  }

  // Petites particules le long du seuil
  noStroke();
  for (let i = 0; i < 400; i++) {
    let t = random();
    let bx = lerp(x1, x2, t);
    let by = lerp(y1, y2, t);
    bx += random(-180, 180) * sin(t * PI);
    by += random(-140, 140) * sin(t * PI);
    fill(255, random(200, 240), random(150, 200), random(80, 180));
    ellipse(bx, by, random(1, 4));
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Fond nocturne profond, dégradé
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(18, 35, t);
    let g = lerp(14, 20, t);
    let b = lerp(38, 55, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Grain / poussière cosmique
  noStroke();
  for (let i = 0; i < 4000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.002, y * 0.002);
    fill(255, 240, 220, n * 40);
    circle(x, y, random(0.5, 2));
  }

  // Étoiles lointaines
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = random(height);
    fill(255, 250, 230, random(80, 220));
    circle(x, y, random(0.5, 2.5));
  }

  // Deux centres - les deux présences
  let cx = width / 2;
  let cy = height / 2;
  let d = 340;
  let a1x = cx - d;
  let a1y = cy + 60;
  let a2x = cx + d;
  let a2y = cy - 60;

  // Champ lumineux entre les deux - lignes de force
  drawField(a1x, a1y, a2x, a2y);

  // Halos extérieurs
  drawHalo(a1x, a1y, 420, color(230, 120, 160), color(80, 40, 90, 0));
  drawHalo(a2x, a2y, 420, color(255, 200, 120), color(90, 60, 40, 0));

  // Orbites - ellipses fines autour du centre commun
  push();
  translate(cx, cy);
  noFill();
  for (let i = 0; i < 24; i++) {
    let a = map(i, 0, 24, 0, PI);
    push();
    rotate(a);
    let alpha = map(i % 6, 0, 6, 15, 50);
    stroke(255, 220, 230, alpha);
    strokeWeight(0.6);
    ellipse(0, 0, d * 2.5 + i * 3, 160 + i * 2);
    pop();
  }
  pop();

  // Les deux corps lumineux
  drawOrb(a1x, a1y, 180, color(255, 140, 180), color(180, 60, 110));
  drawOrb(a2x, a2y, 180, color(255, 210, 140), color(200, 110, 50));

  // Lumière centrale née entre les deux
  push();
  blendMode(ADD);
  for (let r = 300; r > 0; r -= 6) {
    let a = map(r, 300, 0, 0, 90);
    fill(255, 240, 220, a);
    noStroke();
    ellipse(cx, cy, r * 1.4, r * 0.8);
  }
  blendMode(BLEND);
  pop();

  // Petites particules attirées entre les deux
  for (let i = 0; i < 600; i++) {
    let t = random();
    let x = lerp(a1x, a2x, t) + random(-80, 80) * sin(t * PI);
    let y = lerp(a1y, a2y, t) + random(-50, 50) * sin(t * PI);
    let c = lerpColor(color(255, 160, 190), color(255, 220, 150), t);
    fill(red(c), green(c), blue(c), random(100, 220));
    noStroke();
    circle(x, y, random(1, 3.5));
  }

  // Vignettage
  drawVignette();
}

function drawField(x1, y1, x2, y2) {
  push();
  noFill();
  for (let i = 0; i < 180; i++) {
    let offset = map(i, 0, 180, -220, 220);
    let mx = (x1 + x2) / 2;
    let my = (y1 + y2) / 2 + offset;
    let alpha = map(abs(offset), 0, 220, 60, 5);
    let c = lerpColor(color(255, 160, 190), color(255, 220, 160), (offset + 220) / 440);
    stroke(red(c), green(c), blue(c), alpha);
    strokeWeight(random(0.3, 1.2));
    beginShape();
    for (let t = 0; t <= 1; t += 0.02) {
      let x = lerp(x1, x2, t);
      let bulge = sin(t * PI) * offset;
      let y = lerp(y1, y2, t) + bulge + noise(t * 3, i * 0.1) * 20 - 10;
      curveVertex(x, y);
    }
    endShape();
  }
  pop();
}

function drawHalo(x, y, r, c1, c2) {
  noStroke();
  for (let i = r; i > 0; i -= 2) {
    let t = i / r;
    let c = lerpColor(c1, c2, t);
    fill(red(c), green(c), blue(c), (1 - t) * 60);
    circle(x, y, i * 2);
  }
}

function drawOrb(x, y, r, cBright, cDark) {
  noStroke();
  for (let i = r * 1.8; i > 0; i -= 1) {
    let t = i / (r * 1.8);
    let c = lerpColor(cBright, cDark, t);
    fill(red(c), green(c), blue(c), (1 - t) * 180);
    circle(x, y, i);
  }
  // Noyau brillant
  fill(255, 250, 240, 240);
  circle(x - r * 0.15, y - r * 0.15, r * 0.4);
  fill(255, 255, 255, 180);
  circle(x - r * 0.2, y - r * 0.2, r * 0.15);
}

function drawVignette() {
  noFill();
  for (let i = 0; i < 300; i++) {
    stroke(10, 8, 20, i * 0.4);
    strokeWeight(2);
    rect(i, i, width - i * 2, height - i * 2);
  }
}

let cnv;
function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Sky gradient - dusk
  for (let y = 0; y < 1200; y++) {
    let t = y / 1200;
    let r = lerp(250, 240, t);
    let g = lerp(200, 150, t);
    let b = lerp(170, 160, t);
    stroke(r, g, b);
    line(0, y, 1600, y);
  }

  // Soft sun
  noStroke();
  for (let i = 80; i > 0; i--) {
    fill(255, 230, 190, 4);
    ellipse(800, 900, i * 8, i * 8);
  }
  fill(255, 240, 210);
  ellipse(800, 900, 180, 180);

  // Ground gradient (soil)
  for (let y = 1200; y < 2000; y++) {
    let t = (y - 1200) / 800;
    let r = lerp(110, 50, t);
    let g = lerp(75, 30, t);
    let b = lerp(55, 25, t);
    stroke(r, g, b);
    line(0, y, 1600, y);
  }

  // Ground line with subtle texture
  stroke(70, 50, 35, 180);
  strokeWeight(2);
  for (let x = 0; x < 1600; x += 3) {
    let yy = 1200 + sin(x * 0.01) * 4 + noise(x * 0.02) * 10;
    point(x, yy);
  }

  // Distant hills
  noStroke();
  fill(130, 110, 120, 180);
  beginShape();
  vertex(0, 1200);
  for (let x = 0; x <= 1600; x += 20) {
    let y = 1200 - 80 - noise(x * 0.003) * 120;
    vertex(x, y);
  }
  vertex(1600, 1200);
  endShape(CLOSE);

  fill(100, 80, 95, 200);
  beginShape();
  vertex(0, 1200);
  for (let x = 0; x <= 1600; x += 20) {
    let y = 1200 - 30 - noise(x * 0.005 + 100) * 70;
    vertex(x, y);
  }
  vertex(1600, 1200);
  endShape(CLOSE);

  // Draw roots first (behind trees)
  drawRoots();

  // Draw two trees
  drawTree(560, 1200, -1);
  drawTree(1040, 1200, 1);

  // Floating particles / warm atmosphere
  noStroke();
  for (let i = 0; i < 120; i++) {
    let x = random(1600);
    let y = random(1200);
    fill(255, 230, 190, random(30, 90));
