  }

  // Subtle vignette
  for (let i = 0; i < 200; i++) {
    noFill();
    stroke(30, 20, 30, 2);
    strokeWeight(2);
    rect(i, i, 1600 - 2*i, 2000 - 2*i);
  }
}

function drawTree(baseX, baseY, dir) {
  // Trunk
  stroke(60, 40, 30);
  strokeWeight(1);
  fill(80, 55, 40);

  // Main trunk shape
  beginShape();
  vertex(baseX - 40, baseY);
  bezierVertex(baseX - 35, baseY - 200, baseX - 25, baseY - 400, baseX - 15, baseY - 600);
  bezierVertex(baseX - 10, baseY - 700, baseX - 8, baseY - 750, baseX - 5, baseY - 800);
  vertex(baseX + 5, baseY - 800);
  bezierVertex(baseX + 8, baseY - 750, baseX + 10, baseY - 700, baseX + 15, baseY - 600);
  bezierVertex(baseX + 25, baseY - 400, baseX + 35, baseY - 200, baseX + 40, baseY);
  endShape(CLOSE);

  // Trunk texture
  stroke(50, 35, 25, 150);
  strokeWeight(1);
  for (let i = 0; i < 40; i++) {
    let y = baseY - random(0, 800);
    let x = baseX + random(-30, 30);
    line(x, y, x + random(-5, 5), y - random(10, 30));
  }

  // Branches
  drawBranch(baseX, baseY - 600, -PI/2 + dir * 0.3, 180, 8);
  drawBranch(baseX, baseY - 700, -PI/2 - dir * 0.2, 200, 8);
  drawBranch(baseX, baseY - 500, -PI/2 + dir * 0.6, 140, 6);
  drawBranch(baseX, baseY - 800, -PI/2 + dir * 0.1, 160, 7);

  // Foliage - soft clouds of leaves
  noStroke();
  let leafColors = [
    [140, 160, 110, 180],
    [120, 140, 90, 180],
    [160, 170, 120, 180],
    [100, 120, 80, 200],
    [180, 160, 100, 160]
  ];

  for (let i = 0; i < 400; i++) {
    let angle = random(TWO_PI);
    let radius = random(0, 220);
    let cx = baseX + dir * 40 + cos(angle) * radius * (1 + dir * 0.2);
    let cy = baseY - 750 + sin(angle) * radius * 0.9;
    let c = random(leafColors);
    fill(c[0], c[1], c[2], c[3]);
    ellipse(cx, cy, random(15, 35), random(15, 35));
  }

  // Highlight leaves (warm sunlight)
  for (let i = 0; i < 100; i++) {
    let angle = random(-PI/2 - 0.5, -PI/2 + 0.5);
    let radius = random(100, 220);
    let cx = baseX + cos(angle) * radius;
    let cy = baseY - 750 + sin(angle) * radius * 0.9;
    fill(255, 220, 160, 120);
    ellipse(cx, cy, random(10, 25));
  }
}

function drawBranch(x, y, angle, len, w) {
  if (len < 20 || w < 1) return;
  let x2 = x + cos(angle) * len;
  let y2 = y + sin(angle) * len;
  stroke(50, 35, 25);
  strokeWeight(w);
  line(x, y, x2, y2);

  if (len > 40) {
    drawBranch(x2, y2, angle + random(0.3, 0.6), len * 0.7, w * 0.6);
    drawBranch(x2, y2, angle - random(0.3, 0.6), len * 0.7, w * 0.6);
  }
}

function drawRoots() {
  // Two root systems that intertwine beneath
  drawRootSystem(560, 1200, -1);
  drawRootSystem(1040, 1200, 1);

  // Interlocking central roots - the heart of the painting
  stroke(180, 120, 80, 200);
  strokeWeight(5);
  noFill();

  // Weaving roots in the middle
  for (let i = 0; i < 15; i++) {
    let startX = 560 + random(-20, 60);
    let endX = 1040 + random(-60, 20);
    let startY = 1250 + random(0, 400);
    let endY = 1250 + random(0, 400);
    let midY = (startY + endY) / 2 + random(-100, 100);
    let midX = 800 + random(-80, 80);

    strokeWeight(random(2, 6));
    stroke(160 + random(-30, 30), 110 + random(-20, 20), 70, random(150, 220));
    beginShape();
    noFill();
    vertex(startX, startY);
    bezierVertex(startX + 200, midY, endX - 200, midY, endX, endY);
    endShape();
  }

  // Small heart-like glow at intertwining point
  noStroke();
  for (let i = 30; i > 0; i--) {
    fill(255, 180, 120, 5);
    ellipse(800, 1500, i * 6, i * 6);
  }
}

function drawRootSystem(baseX, baseY, dir) {
  stroke(140, 95, 60);
  for (let i = 0; i < 8; i++) {
    let angle = PI/2 + random(-0.8, 0.8) + dir * 0.3;
    drawRoot(baseX + random(-30, 30), baseY + 20, angle, random(150, 300), random(4, 8));
  }
}

function drawRoot(x, y, angle, len, w) {
  if (len < 15 || w < 0.5) return;
  let segments = 8;
  let px = x, py = y;
  stroke(130 + random(-20, 20), 90 + random(-15, 15), 55, 220);
  strokeWeight(w);
  for (let i = 0; i < segments; i++) {
    let t = (i + 1) / segments;
    let nx = x + cos(angle) * len * t + random(-8, 8);
    let ny = y + sin(angle) * len * t + random(-8, 8);
    line(px, py, nx, ny);
    px = nx;
    py = ny;
  }

  if (len > 60) {
    drawRoot(px, py, angle + random(-0.7, 0.7), len * 0.6, w * 0.65);
    if (random() < 0.7) {
      drawRoot(px, py, angle + random(-0.7, 0.7), len * 0.5, w * 0.55);
    }
  }
}

let canvas;
function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Sky gradient - warm dusk
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(250, 230, t);
    let g = lerp(200, 150, t);
    let b = lerp(170, 120, t);
    if (t > 0.65) {
      let t2 = (t - 0.65) / 0.35;
      r = lerp(230, 90, t2);
      g = lerp(150, 70, t2);
      b = lerp(120, 55, t2);
    }
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Sun
  let sunX = width / 2;
  let sunY = height * 0.45;
  noStroke();
  for (let i = 30; i > 0; i--) {
    fill(255, 220, 160, 8);
    ellipse(sunX, sunY, i * 20, i * 20);
  }
  fill(255, 240, 200);
  ellipse(sunX, sunY, 180, 180);

  // Ground
  let groundY = height * 0.72;
  noStroke();
  for (let y = groundY; y < height; y++) {
    let t = (y - groundY) / (height - groundY);
    let r = lerp(80, 30, t);
    let g = lerp(55, 20, t);
    let b = lerp(45, 20, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Underground roots connecting - gentle handhold
  drawRoots(width * 0.38, groundY, width * 0.62, groundY);

  // Shadows
  noStroke();
  fill(20, 15, 15, 80);
  ellipse(width * 0.38, groundY + 10, 400, 40);
  ellipse(width * 0.62, groundY + 10, 400, 40);

  // Two trees
  drawTree(width * 0.38, groundY, -1);
  drawTree(width * 0.62, groundY, 1);

  // Soft light overlay
  noStroke();
  for (let i = 0; i < 200; i++) {
    let x = random(width);
    let y = random(height * 0.7);
    fill(255, 230, 180, random(10, 40));
    ellipse(x, y, random(2, 6));
  }

  // Vignette
  for (let i = 0; i < 80; i++) {
    noFill();
    stroke(20, 10, 20, 3);
    strokeWeight(2);
    rect(i, i, width - i * 2, height - i * 2);
  }
}

function drawRoots(x1, y1, x2, y2) {
  stroke(40, 25, 20, 180);
  strokeWeight(3);
  noFill();
  // Main root connection
  for (let i = 0; i < 12; i++) {
    let yOff = 20 + i * 25;
    beginShape();
    for (let t = 0; t <= 1; t += 0.02) {
      let x = lerp(x1, x2, t);
      let y = y1 + yOff + sin(t * PI) * (60 + i * 8) + noise(t * 3, i) * 20;
      curveVertex(x, y);
    }
    endShape();
  }
  // Side roots
  strokeWeight(2);
  for (let i = 0; i < 20; i++) {
    let sx = x1 + random(-150, -20);
    let sy = y1 + random(10, 300);
    let ex = sx + random(-200, -50);
    let ey = sy + random(50, 200);
    line(sx, sy, ex, ey);
    let sx2 = x2 + random(20, 150);
    let sy2 = y1 + random(10, 300);
    let ex2 = sx2 + random(50, 200);
    let ey2 = sy2 + random(50, 200);
    line(sx2, sy2, ex2, ey2);
  }
}

function drawTree(x, y, dir) {
  // Trunk - lean slightly toward each other
  stroke(50, 35, 28);
  strokeWeight(60);
  noFill();
  let trunk = [];
  let cx = x, cy = y;
  for (let i = 0; i < 20; i++) {
    trunk.push({x: cx, y: cy});
    cx += dir * -2 + random(-1, 1);
    cy -= 35;
  }
  beginShape();
  for (let p of trunk) curveVertex(p.x, p.y);
  endShape();

  // Trunk texture
  strokeWeight(2);
  stroke(30, 20, 15, 150);
  for (let i = 0; i < 40; i++) {
    let py = y - random(0, 700);
    let px = x + map(y - py, 0, 700, 0, dir * -40) + random(-25, 25);
    line(px, py, px + random(-5, 5), py + random(10, 30));
  }

  // Branches and foliage
  let topX = trunk[trunk.length - 1].x;
  let topY = trunk[trunk.length - 1].y;

  drawBranches(topX, topY, -PI/2 + dir * 0.1, 180, 5);

  // Foliage clusters
  drawFoliage(topX + dir * -80, topY - 50, 220);
  drawFoliage(topX + dir * 60, topY - 80, 180);
  drawFoliage(topX - 40, topY - 180, 240);
  drawFoliage(topX + dir * -140, topY + 40, 160);
  drawFoliage(topX + dir * 100, topY + 20, 170);
  drawFoliage(topX, topY - 260, 200);
}

function drawBranches(x, y, angle, len, depth) {
  if (depth <= 0 || len < 15) return;
  let x2 = x + cos(angle) * len;
  let y2 = y + sin(angle) * len;
  stroke(45, 30, 22);
  strokeWeight(depth * 3);
  line(x, y, x2, y2);
  drawBranches(x2, y2, angle - random(0.2, 0.6), len * 0.7, depth - 1);
  drawBranches(x2, y2, angle + random(0.2, 0.6), len * 0.7, depth - 1);
  if (random() > 0.5) {
    drawBranches(x2, y2, angle + random(-0.3, 0.3), len * 0.6, depth - 1);
  }
}

function drawFoliage(cx, cy, size) {
  noStroke();
  for (let i = 0; i < 180; i++) {
    let a = random(TWO_PI);
    let r = random(size);
    let px = cx + cos(a) * r;
    let py = cy + sin(a) * r * 0.85;
    let n = noise(px * 0.01, py * 0.01);
    let gr = lerp(60, 140, n);
    let rr = lerp(100, 180, n);
    fill(rr, gr, 50, 180);
    ellipse(px, py, random(15, 35));
  }
  // Highlights
  for (let i = 0; i < 60; i++) {
    let a = random(-PI, 0);
    let r = random(size * 0.7);
    let px = cx + cos(a) * r;
    let py = cy + sin(a) * r * 0.85 - 20;
    fill(240, 200, 100, 150);
    ellipse(px, py, random(10, 25));
  }
}

