    let y = height * 0.7 + noise(x * 0.002) * 80 - 40;
    vertex(x, y);
  }
  vertex(width, height);
  vertex(0, height);
  endShape(CLOSE);

  // Ground
  fill(35, 25, 30);
  rect(0, height * 0.72, width, height * 0.28);

  // Underground section - roots intertwining
  // Soil texture
  for (let i = 0; i < 3000; i++) {
    let x = random(width);
    let y = random(height * 0.72, height);
    fill(60, 40, 45, random(30, 80));
    ellipse(x, y, random(2, 5));
  }

  // Draw roots - they reach toward each other and intertwine
  let leftBase = { x: width * 0.35, y: height * 0.72 };
  let rightBase = { x: width * 0.65, y: height * 0.72 };

  drawRoots(leftBase.x, leftBase.y, 1);
  drawRoots(rightBase.x, rightBase.y, -1);

  // Central intertwined roots - the heart of love
  drawHeartRoots(width / 2, height * 0.85);

  // Trees trunks
  drawTree(leftBase.x, leftBase.y, 1);
  drawTree(rightBase.x, rightBase.y, -1);

  // Two small figures beneath
  drawFigure(width / 2 - 40, height * 0.71, color(40, 30, 50));
  drawFigure(width / 2 + 40, height * 0.71, color(50, 35, 55));

  // Fireflies / love sparks
  for (let i = 0; i < 40; i++) {
