    let y = random(height * 0.3, height * 0.7);
    fill(255, 230, 180, random(100, 200));
    noStroke();
    ellipse(x, y, random(3, 7));
    fill(255, 230, 180, 30);
    ellipse(x, y, random(12, 20));
  }

  // Vignette
  for (let i = 0; i < 100; i++) {
    noFill();
    stroke(0, 3);
    rect(i, i, width - 2 * i, height - 2 * i);
  }
}

function drawTree(x, y, dir) {
  // Trunk leaning slightly toward partner
  stroke(25, 18, 20);
  strokeWeight(1);
  fill(45, 30, 28);
  beginShape();
  let h = height * 0.55;
  for (let t = 0; t <= 1; t += 0.02) {
    let tx = x - dir * t * 40 + sin(t * 3) * 8;
    let ty = y - t * h;
    let w = lerp(50, 15, t);
    vertex(tx - w, ty);
  }
  for (let t = 1; t >= 0; t -= 0.02) {
    let tx = x - dir * t * 40 + sin(t * 3) * 8;
    let ty = y - t * h;
    let w = lerp(50, 15, t);
    vertex(tx + w, ty);
  }
  endShape(CLOSE);

  // Branches and foliage
  let topX = x - dir * 40 + sin(3) * 8;
  let topY = y - h;
  drawBranches(topX, topY, -PI / 2 + dir * 0.2, 180, 5);

  // Foliage clusters
  for (let i = 0; i < 80; i++) {
    let angle = random(TWO_PI);
    let r = random(30, 180);
    let fx = topX + cos(angle) * r + random(-20, 20);
    let fy = topY + sin(angle) * r * 0.9 - 40;
    let col = color(random(80, 140), random(50, 90), random(90, 140), 180);
    fill(col);
    noStroke();
    ellipse(fx, fy, random(25, 60), random(25, 55));
  }

  // Blossoms - pink petals of love
  for (let i = 0; i < 40; i++) {
    let angle = random(TWO_PI);
    let r = random(20, 170);
    let fx = topX + cos(angle) * r;
    let fy = topY + sin(angle) * r * 0.9 - 40;
    fill(255, 180, 190, 220);
    ellipse(fx, fy, random(6, 12));
    fill(255, 220, 220, 180);
    ellipse(fx, fy, random(3, 6));
  }
}

function drawBranches(x, y, angle, len, depth) {
  if (depth <= 0 || len < 5) return;
  let x2 = x + cos(angle) * len;
  let y2 = y + sin(angle) * len;
  stroke(30, 20, 22);
  strokeWeight(map(depth, 0, 5, 1, 5));
  line(x, y, x2, y2);
  drawBranches(x2, y2, angle - random(0.3, 0.6), len * 0.7, depth - 1);
  drawBranches(x2, y2, angle + random(0.3, 0.6), len * 0.7, depth - 1);
}

function drawRoots(x, y, dir) {
  stroke(60, 40, 35);
  noFill();
  for (let i = 0; i < 8; i++) {
    let angle = PI / 2 + random(-0.8, 0.8);
    let len = random(100, 300);
    strokeWeight(random(2, 6));
    let px = x, py = y;
    for (let t = 0; t < len; t += 5) {
      let nx = px + cos(angle) * 5 + random(-2, 2);
      let ny = py + sin(angle) * 5 + random(-1, 3);
      line(px, py, nx, ny);
      px = nx; py = ny;
      angle += random(-0.1, 0.1);
    }
  }
}

function drawHeartRoots(cx, cy) {
  // Two root systems meeting and intertwining
  stroke(80, 50, 45);
  noFill();
  for (let i = 0; i < 20; i++) {
    strokeWeight(random(2, 5));
    let startX = random(width * 0.3, width * 0.4);
    let startY = height * 0.75 + random(0, 50);
    let endX = random(width * 0.6, width * 0.7);
    let endY = height * 0.75 + random(0, 50);
    let ctrlY = cy + random(-30, 80);
    beginShape();
    noFill();
    for (let t = 0; t <= 1; t += 0.02) {
      let x = bezierPoint(startX, cx - 30 + random(-10, 10), cx + 30 + random(-10, 10), endX, t);
      let y = bezierPoint(startY, ctrlY, ctrlY, endY, t);
      vertex(x + random(-1, 1), y + random(-1, 1));
    }
    endShape();
  }

  // Heart shape formed by roots
  stroke(140, 60, 70, 180);
  strokeWeight(3);
  noFill();
  beginShape();
  for (let a = 0; a < TWO_PI; a += 0.05) {
    let r = 40;
    let hx = cx + r * 16 * pow(sin(a), 3) / 16;
    let hy = cy - r * (13 * cos(a) - 5 * cos(2*a) - 2*cos(3*a) - cos(4*a)) / 16;
    vertex(hx, hy);
  }
  endShape(CLOSE);

  fill(180, 70, 80, 100);
  noStroke();
  beginShape();
  for (let a = 0; a < TWO_PI; a += 0.05) {
    let r = 38;
    let hx = cx + r * 16 * pow(sin(a), 3) / 16;
    let hy = cy - r * (13 * cos(a) - 5 * cos(2*a) - 2*cos(3*a) - cos(4*a)) / 16;
    vertex(hx, hy);
  }
  endShape(CLOSE);
}

function drawFigure(x, y, col) {
  fill(col);
  noStroke();
  // Body
  ellipse(x, y - 15, 20, 40);
  // Head
  ellipse(x, y - 45, 18, 18);
}

