  stroke(60, 45, 35);
  strokeWeight(40);
  noFill();
  let trunkTop = baseY - 350;
  beginShape();
  for (let t = 0; t <= 1; t += 0.05) {
    let x = baseX + lean * t * t * 30;
    let y = baseY - t * 350;
    curveVertex(x, y);
  }
  endShape();

  // Branches
  strokeWeight(1);
  drawBranch(baseX + lean * 30, trunkTop, -PI/2 + lean * 0.1, 180, 18);
}

function drawBranch(x, y, angle, len, thickness) {
  if (len < 8 || thickness < 1) {
    // Draw leaves cluster
    noStroke();
    for (let i = 0; i < 15; i++) {
      let lx = x + random(-30, 30);
      let ly = y + random(-30, 30);
      fill(random(80, 140), random(100, 160), random(70, 110), random(180, 230));
      ellipse(lx, ly, random(15, 30), random(15, 30));
    }
    // Some warmer leaves
    for (let i = 0; i < 5; i++) {
      let lx = x + random(-25, 25);
      let ly = y + random(-25, 25);
      fill(random(200, 240), random(140, 180), random(90, 130), 200);
      ellipse(lx, ly, random(10, 20), random(10, 20));
    }
    return;
  }

  let x2 = x + cos(angle) * len;
  let y2 = y + sin(angle) * len;

  stroke(60, 45, 35);
  strokeWeight(thickness);
  line(x, y, x2, y2);

  let branches = random() < 0.3 ? 3 : 2;
  for (let i = 0; i < branches; i++) {
    let newAngle = angle + random(-0.7, 0.7);
    let newLen = len * random(0.6, 0.8);
    drawBranch(x2, y2, newAngle, newLen, thickness * 0.7);
  }
}

function drawRoots() {
