  drawRoot(500, 1080, PI/2 + 0.3, 120, 20, 'left');
  drawRoot(500, 1080, PI/2 + 0.6, 100, 15, 'left');
  drawRoot(500, 1080, PI/2 - 0.1, 110, 16, 'left');
  drawRoot(500, 1080, PI/2 + 0.9, 90, 12, 'left');

