  drawRoot(1100, 1080, PI/2 - 0.6, 100, 15, 'right');
  drawRoot(1100, 1080, PI/2 + 0.1, 110, 16, 'right');
  drawRoot(1100, 1080, PI/2 - 0.9, 90, 12, 'right');
}

function drawRoot(x, y, angle, len, thickness, side) {
  if (len < 6 || thickness < 0.5) return;

  // Curve roots toward center (800, 1500) for intertwining effect
  let targetX = 800;
  let targetY = 1500;
  let dx = targetX - x;
  let pullFactor = 0;
  if (y > 1200 && y < 1700) {
    pullFactor = (side === 'left') ? 0.015 : -0.015;
    if (side === 'left') pullFactor = dx > 0 ? 0.02 : 0;
    if (side === 'right') pullFactor = dx < 0 ? -0.02 : 0;
  }

  let segments = 8;
  let px = x, py = y;
  for (let i = 1; i <= segments; i++) {
    angle += random(-0.15, 0.15) + pullFactor;
    let segLen = len / segments;
    let nx = px + cos(angle) * segLen;
    let ny = py + sin(angle) * segLen;

    stroke(45, 30, 22);
    strokeWeight(thickness * (1 - i/segments * 0.3));
    line(px, py, nx, ny);

    px = nx;
    py = ny;
  }

  // Branch out
  let branches = random() < 0.4 ? 3 : 2;
  for (let i = 0; i < branches; i++) {
    let newAngle = angle + random(-0.9, 0.9);
    let newLen = len * random(0.55, 0.75);
    drawRoot(px, py, newAngle, newLen, thickness * 0.65, side);
  }

  // Small root hairs
  if (random() < 0.3) {
    stroke(45, 30, 22, 150);
    strokeWeight(0.5);
    for (let i = 0; i < 4; i++) {
      let ha = angle + random(-PI, PI);
      line(px, py, px + cos(ha) * 8, py + sin(ha) * 8);
    }
  }
}

