function drawTree(baseX, baseY, dir) {
  // Trunk
  stroke(70, 50, 45);
  strokeWeight(1);
  fill(95, 70, 55);
  beginShape();
  vertex(baseX - 35, baseY);
  bezierVertex(baseX - 30, baseY - 200, baseX - 25, baseY - 400, baseX - 18, baseY - 600);
  bezierVertex(baseX - 15, baseY - 700, baseX - 12, baseY - 750, baseX - 8, baseY - 800);
  vertex(baseX + 8, baseY - 800);
  bezierVertex(baseX + 12, baseY - 750, baseX + 15, baseY - 700, baseX + 18, baseY - 600);
  bezierVertex(baseX + 25, baseY - 400, baseX + 30, baseY - 200, baseX + 35, baseY);
  endShape(CLOSE);

  // Trunk texture
  stroke(55, 38, 30, 150);
  strokeWeight(1);
  for (let y = baseY; y > baseY - 800; y -= 8) {
    let w = map(y, baseY - 800, baseY, 20, 60);
    line(baseX - w/2 + random(-3, 3), y, baseX - w/2 + random(-3, 3), y - 15);
    line(baseX + w/4 + random(-3, 3), y, baseX + w/4 + random(-3, 3), y - 15);
  }

  // Branches
  drawBranch(baseX, baseY - 800, -PI/2 + dir * 0.1, 180, 12);
}

function drawBranch(x, y, angle, len, thickness) {
  if (len < 10 || thickness < 1) {
    drawLeafCluster(x, y);
    return;
  }

  let x2 = x + cos(angle) * len;
  let y2 = y + sin(angle) * len;

  stroke(70, 50, 45);
  strokeWeight(thickness);
  line(x, y, x2, y2);

  // Occasional leaf along branch
  if (len < 60 && random() < 0.4) {
    drawLeafCluster(x2, y2);
  }

  let numBranches = random() < 0.7 ? 2 : 3;
  for (let i = 0; i < numBranches; i++) {
    let newAngle = angle + random(-0.9, 0.9);
    let newLen = len * random(0.6, 0.8);
    let newThick = thickness * 0.7;
    drawBranch(x2, y2, newAngle, newLen, newThick);
  }
}

function drawLeafCluster(x, y) {
  noStroke();
  for (let i = 0; i < 25; i++) {
    let ox = random(-40, 40);
    let oy = random(-40, 40);
    let r = random(150, 220);
    let g = random(140, 200);
    let b = random(100, 150);
    fill(r, g, b, 180);
    ellipse(x + ox, y + oy, random(8, 18), random(8, 18));
  }
  // Highlights
  for (let i = 0; i < 10; i++) {
    let ox = random(-30, 30);
    let oy = random(-30, 30);
    fill(240, 220, 160, 150);
    ellipse(x + ox, y + oy - 10, random(4, 10));
  }
}

function drawRoots() {
  let groundY = 1350;
  // Two root systems that intertwine
  stroke(60, 40, 35);

  drawRoot(550, groundY, PI/2 + 0.3, 200, 14, 0);
  drawRoot(1050, groundY, PI/2 - 0.3, 200, 14, 0);

  // Fine hair roots everywhere
  stroke(80, 55, 45, 150);
  strokeWeight(0.5);
  for (let i = 0; i < 300; i++) {
    let x = random(200, 1400);
    let y = random(groundY + 20, 1950);
    let a = random(TWO_PI);
    let l = random(10, 40);
    line(x, y, x + cos(a) * l, y + sin(a) * l);
  }
}

function drawRoot(x, y, angle, len, thickness, depth) {
  if (len < 8 || thickness < 0.5 || depth > 7) return;

  let steps = 10;
  let px = x, py = y;
  let curAngle = angle;

  stroke(55, 38, 32);
  strokeWeight(thickness);
  noFill();

  beginShape();
  vertex(x, y);
  for (let i = 1; i <= steps; i++) {
    let t = i / steps;
    curAngle += random(-0.15, 0.15);
    let nx = px + cos(curAngle) * (len / steps);
    let ny = py + sin(curAngle) * (len / steps);
    // Keep roots going downward overall but allow lateral
    ny = max(ny, py);
    vertex(nx, ny);
    px = nx; py = ny;
  }
  endShape();

  let endX = px, endY = py;

  // Branch out
  let numBranches = depth < 2 ? 3 : 2;
  for (let i = 0; i < numBranches; i++) {
    let newAngle = curAngle + random(-1.0, 1.0);
    // bias center roots to reach toward middle (intertwining)
    if (depth < 3) {
      let centerPull = (800 - endX) * 0.0008;
      newAngle += centerPull;
    }
    let newLen = len * random(0.6, 0.85);
    let newThick = thickness * 0.72;
    drawRoot(endX, endY, newAngle, newLen, newThick, depth + 1);
  }
}

