const sketch = (p) => {
  p.setup = () => {
    p.createCanvas(1600, 2000);
    p.randomSeed(1);
    p.noiseSeed(1);
    p.noLoop();
    drawPainting(p);
  };
};

function drawPainting(p) {
  // Deep background gradient
  for (let y = 0; y < p.height; y++) {
    let t = y / p.height;
    let r = p.lerp(12, 28, t);
    let g = p.lerp(8, 14, t);
    let b = p.lerp(30, 42, t);
    p.stroke(r, g, b);
    p.line(0, y, p.width, y);
  }

  // Background star-dust noise field
  p.noStroke();
  for (let i = 0; i < 4000; i++) {
    let x = p.random(p.width);
    let y = p.random(p.height);
    let n = p.noise(x * 0.002, y * 0.002);
    let a = p.pow(n, 3) * 180;
    p.fill(255, 240, 220, a * 0.3);
    p.circle(x, y, p.random(0.5, 2));
  }

  // Two centers of gravity
  let c1 = { x: 560, y: 900, col: p.color(255, 120, 150) };
  let c2 = { x: 1080, y: 1120, col: p.color(120, 180, 255) };

  // Curved field lines showing gravitational pull between them
  p.noFill();
  for (let i = 0; i < 260; i++) {
    let startAngle = p.random(p.TWO_PI);
    let startR = p.random(40, 700);
    let ox, oy, target, other;
    if (p.random() < 0.5) {
      ox = c1.x + p.cos(startAngle) * startR;
      oy = c1.y + p.sin(startAngle) * startR;
      target = c1; other = c2;
    } else {
      ox = c2.x + p.cos(startAngle) * startR;
      oy = c2.y + p.sin(startAngle) * startR;
      target = c2; other = c1;
    }

    let px = ox, py = oy;
    let col = p.lerpColor(target.col, other.col, 0.3);
    p.stroke(p.red(col), p.green(col), p.blue(col), 40);
    p.strokeWeight(p.random(0.5, 1.5));
    p.beginShape();
    for (let s = 0; s < 220; s++) {
      p.vertex(px, py);
      let dx1 = target.x - px, dy1 = target.y - py;
      let d1 = p.sqrt(dx1*dx1+dy1*dy1) + 1;
      let dx2 = other.x - px, dy2 = other.y - py;
      let d2 = p.sqrt(dx2*dx2+dy2*dy2) + 1;
      let fx = dx1/(d1*d1)*8000 + dx2/(d2*d2)*4000;
      let fy = dy1/(d1*d1)*8000 + dy2/(d2*d2)*4000;
      let n = p.noise(px*0.003, py*0.003, s*0.01);
      let ang = n * p.TWO_PI * 2;
      fx += p.cos(ang) * 0.8;
      fy += p.sin(ang) * 0.8;
      let mag = p.sqrt(fx*fx+fy*fy);
      if (mag > 3) { fx = fx/mag*3; fy = fy/mag*3; }
      px += fx; py += fy;
      if (px<0||px>p.width||py<0||py>p.height) break;
    }
    p.endShape();
  }

  // Luminous dust particles following the bent space
  for (let i = 0; i < 9000; i++) {
    let x = p.random(p.width);
    let y = p.random(p.height);
    let dx1 = c1.x - x, dy1 = c1.y - y;
    let d1 = p.sqrt(dx1*dx1+dy1*dy1);
    let dx2 = c2.x - x, dy2 = c2.y - y;
    let d2 = p.sqrt(dx2*dx2+dy2*dy2);
    let influence = 1/(d1+50) + 1/(d2+50);
    if (p.random() < influence * 80) {
      let col;
      if (d1 < d2) col = c1.col; else col = c2.col;
      let mix = p.constrain(p.abs(d1-d2)/400, 0, 1);
      if (mix < 0.4) col = p.lerpColor(c1.col, c2.col, 0.5);
      p.fill(p.red(col), p.green(col), p.blue(col), p.random(40, 180));
      p.noStroke();
      p.circle(x, y, p.random(0.8, 2.5));
    }
  }

  // The two glowing orbs with soft halos
  drawOrb(p, c1.x, c1.y, 180, c1.col);
  drawOrb(p, c2.x, c2.y, 210, c2.col);

  // The third thing: the bright region between them
  let mx = (c1.x + c2.x) / 2;
  let my = (c1.y + c2.y) / 2 - 20;
  for (let r = 300; r > 0; r -= 2) {
    let a = p.map(r, 0, 300, 90, 0);
    p.fill(255, 245, 230, a);
    p.noStroke();
    p.ellipse(mx, my, r * 1.4, r);
  }
  // Core of the third light
  for (let r = 60; r > 0; r -= 1) {
    let a = p.map(r, 0, 60, 255, 0);
    p.fill(255, 250, 240, a);
    p.circle(mx, my, r);
  }

  // Subtle vignette
  for (let r = p.width; r > p.width*0.5; r -= 2) {
    let a = p.map(r, p.width*0.5, p.width, 0, 80);
    p.noFill();
    p.stroke(10, 5, 20, a);
    p.strokeWeight(2);
    p.ellipse(p.width/2, p.height/2, r*2, r*2.2);
  }
}

function drawOrb(p, x, y, size, col) {
  p.noStroke();
  // Outer halo
  for (let r = size * 2.5; r > 0; r -= 2) {
    let t = r / (size * 2.5);
    let a = p.pow(1 - t, 2.5) * 80;
    p.fill(p.red(col), p.green(col), p.blue(col), a);
    p.circle(x, y, r);
  }
  // Core
  for (let r = size * 0.6; r > 0; r -= 1) {
    let t = r / (size * 0.6);
    let c = p.lerpColor(p.color(255, 255, 240), col, t);
    p.fill(p.red(c), p.green(c), p.blue(c), 255);
    p.circle(x, y, r);
  }
}

new p5(sketch);

let canvas;
function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();

  // Background - deep warm night
  background(18, 14, 28);

  // Subtle noise texture background
  drawBackgroundGlow();

  // Two centers of gravity
  let c1 = {x: 620, y: 950, r: 180, hue: [255, 140, 160]};
  let c2 = {x: 1050, y: 1100, r: 160, hue: [255, 200, 130]};

  // Draw the field between them - the space that love creates
  drawField(c1, c2);

  // Draw gravitational lines connecting them
  drawConnectingLines(c1, c2);

  // Particles drawn toward both
  drawParticles(c1, c2);

  // The two glowing presences
  drawPresence(c1);
  drawPresence(c2);

  // Final atmospheric grain
  drawGrain();
}

function drawBackgroundGlow() {
  // soft radial gradient-like wash
  for (let i = 0; i < 400; i++) {
    let x = random(width);
    let y = random(height);
    let r = random(100, 400);
    noStroke();
    fill(40, 25, 55, 3);
    ellipse(x, y, r, r);
  }
}

function drawField(c1, c2) {
  // Visualize the curved space between the two centers
  loadPixels();
  let step = 4;
  for (let x = 0; x < width; x += step) {
    for (let y = 0; y < height; y += step) {
      let d1 = dist(x, y, c1.x, c1.y);
      let d2 = dist(x, y, c2.x, c2.y);
      let field = 1/(d1*0.01 + 1) + 1/(d2*0.01 + 1);

      if (field > 0.08) {
        let t = constrain((field - 0.08) * 3, 0, 1);
        let r = lerp(c1.hue[0], c2.hue[0], d1/(d1+d2)) * t * 0.4;
        let g = lerp(c1.hue[1], c2.hue[1], d1/(d1+d2)) * t * 0.3;
        let b = lerp(c1.hue[2], c2.hue[2], d1/(d1+d2)) * t * 0.3;

        noStroke();
        fill(r + 20, g + 15, b + 30, 40);
        rect(x, y, step, step);
      }
    }
  }
}

function drawConnectingLines(c1, c2) {
  // Curved threads of connection
  let numLines = 80;
  for (let i = 0; i < numLines; i++) {
    let t = i / numLines;
    let angle1 = random(TWO_PI);
    let angle2 = random(TWO_PI);
    let r1 = c1.r * random(0.5, 1.1);
    let r2 = c2.r * random(0.5, 1.1);

    let x1 = c1.x + cos(angle1) * r1;
    let y1 = c1.y + sin(angle1) * r1;
    let x2 = c2.x + cos(angle2) * r2;
    let y2 = c2.y + sin(angle2) * r2;

    // Midpoint pulled toward the shared center
    let mx = (x1 + x2) / 2 + random(-60, 60);
    let my = (y1 + y2) / 2 - random(40, 180);

    noFill();
    let alpha = random(15, 55);
    stroke(255, 220, 200, alpha);
    strokeWeight(random(0.3, 1.2));

    beginShape();
    for (let s = 0; s <= 1; s += 0.02) {
      let a = lerp(x1, mx, s);
      let b = lerp(mx, x2, s);
      let c = lerp(y1, my, s);
      let d = lerp(my, y2, s);
      let px = lerp(a, b, s);
      let py = lerp(c, d, s);
      vertex(px, py);
    }
    endShape();
  }
}

function drawParticles(c1, c2) {
  // Floating particles caught in the field
  for (let i = 0; i < 1800; i++) {
    let x = random(width);
    let y = random(height);
    let d1 = dist(x, y, c1.x, c1.y);
    let d2 = dist(x, y, c2.x, c2.y);
    let influence = 1/(d1 + 1) + 1/(d2 + 1);

    if (random() < influence * 300) {
      let closer = d1 < d2 ? c1 : c2;
      let bright = map(min(d1, d2), 0, 500, 255, 60);
      noStroke();
      fill(closer.hue[0], closer.hue[1], closer.hue[2], random(80, 200));
      let sz = random(0.8, 2.8);
      ellipse(x, y, sz, sz);
    }
  }

  // A few bright drifters between
  for (let i = 0; i < 300; i++) {
    let t = random();
    let mx = lerp(c1.x, c2.x, t) + random(-200, 200);
    let my = lerp(c1.y, c2.y, t) + random(-200, 200) - 50 * sin(t * PI);
    noStroke();
    fill(255, 230, 200, random(100, 220));
    let sz = random(1, 3);
    ellipse(mx, my, sz, sz);
  }
}

function drawPresence(c) {
  // Outer soft halo
  for (let i = 60; i > 0; i--) {
    let a = map(i, 0, 60, 0, 25);
    noStroke();
    fill(c.hue[0], c.hue[1], c.hue[2], a);
    ellipse(c.x, c.y, c.r * 2 + i * 8, c.r * 2 + i * 8);
  }

  // Core
  for (let i = c.r; i > 0; i -= 2) {
    let t = i / c.r;
    let r = lerp(255, c.hue[0], t);
    let g = lerp(245, c.hue[1], t);
    let b = lerp(230, c.hue[2], t);
    noStroke();
    fill(r, g, b, 200);
    ellipse(c.x, c.y, i * 2, i * 2);
  }

  // Bright center
  fill(255, 250, 240, 240);
  noStroke();
  ellipse(c.x, c.y, c.r * 0.4, c.r * 0.4);
  fill(255, 255, 255, 255);
  ellipse(c.x, c.y, c.r * 0.15, c.r * 0.15);
}

function drawGrain() {
  for (let i = 0; i < 8000; i++) {
    let x = random(width);
    let y = random(height);
    noStroke();
    fill(255, 240, 220, random(5, 20));
    rect(x, y, 1, 1);
  }

  // Vignette
  for (let i = 0; i < 80; i++) {
    noFill();
    stroke(10, 5, 20, 8);
    strokeWeight(2);
    rect(i, i, width - i * 2, height - i * 2);
  }
}

