  for (let i = 0; i < 120; i++) {
    let x = random(width);
    let y = random(0, 600);
    let a = random(40, 160) * (1 - y / 600);
    fill(255, 255, 240, a);
    ellipse(x, y, random(1, 3));
  }

  // Water
  for (let y = 1200; y < 2000; y++) {
    let t = (y - 1200) / 800;
    let r = lerp(45, 15, t);
    let g = lerp(45, 20, t);
    let b = lerp(70, 35, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Reflection of light on water
  noStroke();
  for (let y = 1200; y < 1700; y += 3) {
    let w = map(y, 1200, 1700, 160, 20) * noise(y * 0.05);
    let a = map(y, 1200, 1700, 120, 0);
    fill(230, 200, 150, a);
    ellipse(800 + random(-15, 15), y, w, 5);
  }

  // Ripples
  stroke(255, 255, 255, 15);
  noFill();
  for (let i = 0; i < 60; i++) {
    let y = random(1210, 1980);
    let x = random(width);
    let w = random(40, 200);
    strokeWeight(random(0.5, 1.5));
    arc(x, y, w, w * 0.15, 0, PI);
  }

  // The boat
  push();
  translate(800, 1320);
  // Boat reflection
  noStroke();
  fill(10, 10, 20, 100);
  beginShape();
  vertex(-150, 10);
  bezierVertex(-80, 60, 80, 60, 150, 10);
  bezierVertex(100, 50, -100, 50, -150, 10);
  endShape(CLOSE);

  // Hull
  fill(20, 18, 28);
  beginShape();
  vertex(-150, 0);
  bezierVertex(-80, -45, 80, -45, 150, 0);
  bezierVertex(100, 25, -100, 25, -150, 0);
  endShape(CLOSE);

  // Standing figure (ferryman) with pole
  fill(8, 8, 14);
  // pole
  strokeWeight(5);
  stroke(8, 8, 14);
  line(40, -30, 90, -230);
  noStroke();
  // body
  beginShape();
  vertex(10, -25);
  bezierVertex(0, -120, 35, -170, 25, -200);
  vertex(55, -200);
  bezierVertex(50, -150, 60, -90, 55, -25);
  endShape(CLOSE);
  // head
  ellipse(40, -210, 28, 34);

  pop();

  // Mist layer near horizon
  noStroke();
  for (let i = 0; i < 40; i++) {
    let x = random(width);
    let y = random(1150, 1260);
    fill(200, 200, 210, random(5, 20));
    ellipse(x, y, random(200, 500), random(30, 70));
  }

  // Vignette
  for (let r = 0; r < 1000; r += 5) {
    let a = map(r, 600, 1200, 0, 120);
    a = constrain(a, 0, 120);
    noFill();
    stroke(0, 0, 10, a * 0.05);
    strokeWeight(5);
    ellipse(800, 1000, (1600 - r) * 2.0, (2000 - r) * 1.8);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Vertical gradient: warm dense bottom to cool open top
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(30, 180, pow(t, 1.3));
    let g = lerp(25, 120, pow(t, 1.1));
    let b = lerp(40, 60, 1 - t);
    // cool top
    let r2 = lerp(200, 40, t);
    let g2 = lerp(215, 30, t);
    let b2 = lerp(230, 45, t);
    let cr = lerp(r2, r, t);
    let cg = lerp(g2, g, t);
    let cb = lerp(b2, b, t);
    stroke(cr, cg, cb);
    line(0, y, width, y);
  }

  // The threshold: a glowing vertical opening
  let cx = width / 2;
  noStroke();
  for (let i = 120; i > 0; i--) {
    let a = map(i, 0, 120, 60, 0);
    fill(240, 245, 250, a);
    let w = i * 2.2;
    let h = height * 0.9;
    ellipse(cx, height * 0.42, w, h);
  }

  // Solid "self" at the bottom, dissolving into particles upward
  for (let i = 0; i < 9000; i++) {
    // probability of existing decreases with height
    let yBase = random(height * 0.3, height);
    let t = 1 - yBase / height; // 0 bottom .. ~0.7 top
    // gather near center column, loosen upward
    let spread = lerp(90, 650, t);
    let x = cx + random(-spread, spread) * (0.4 + noise(yBase * 0.003) * 1.2);
    let y = yBase - noise(x * 0.004, yBase * 0.004) * 300 * t;

    // skip some upper particles to thin out
    if (random() < t * 0.7) continue;

    let size = lerp(7, 1.5, t);
    // color shifts from warm ember to pale light
    let r = lerp(230, 235, t);
    let g = lerp(140, 240, t);
    let b = lerp(90, 250, t);
    let alpha = lerp(200, 40, t);
    noStroke();
    fill(r, g, b, alpha);
    ellipse(x, y, size, size);
  }

  // Faint rising motes drifting into the openness above
  for (let i = 0; i < 400; i++) {
    let y = random(0, height * 0.5);
    let x = cx + random(-700, 700);
    let a = map(y, 0, height * 0.5, 10, 70);
    fill(250, 252, 255, a);
    noStroke();
    ellipse(x, y, random(1, 3));
  }

  // Soft vignette
  noFill();
  for (let i = 0; i < 200; i++) {
    stroke(10, 10, 20, map(i, 0, 200, 40, 0));
    strokeWeight(2);
    rect(i, i, width - i * 2, height - i * 2);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Vertical gradient: warm dense bottom to cool open top
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(210, 30, t);
    let g = lerp(140, 40, t);
    let b = lerp(90, 70, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // The vast cool field above (subtle luminosity)
  noStroke();
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = random(0, height * 0.45);
    let s = random(1, 4);
    let a = map(y, 0, height * 0.45, 120, 10);
    fill(220, 225, 235, a);
    ellipse(x, y, s, s);
  }

  // The threshold band - a soft horizon of light
  let horizon = height * 0.52;
  for (let y = horizon - 120; y < horizon + 120; y++) {
    let d = abs(y - horizon) / 120;
    let a = (1 - d) * 90;
    stroke(255, 240, 220, a);
    line(0, y, width, y);
  }

  // The figure: a human form at center dissolving upward into particles
  let cx = width / 2;
  let figTop = horizon - 60;
  let figBottom = height * 0.9;

  // Dense lower body: solid, warm, intact
  noStroke();
  for (let i = 0; i < 9000; i++) {
    let yy = random(figBottom, horizon + 20);
    let tt = map(yy, figBottom, horizon, 0, 1); // 0 bottom,1 near horizon
    // body width - narrows as it rises
    let bw = lerp(170, 90, tt);
    let xx = cx + random(-bw, bw) * (0.5 + 0.5 * (1 - tt));
    // dissolution probability increases upward
    if (random() < tt * tt * 0.6) continue;
    let a = lerp(230, 120, tt);
    fill(40, 30, 35, a);
    let s = lerp(3, 1.5, tt);
    ellipse(xx, yy, s, s);
  }

  // The scattering: particles rising and spreading above the figure
  for (let i = 0; i < 6000; i++) {
    let life = random(1); // 0 just leaving, 1 far gone
    let yy = lerp(figTop, height * 0.08, life);
    // spread widens as they rise
    let spread = lerp(70, 650, pow(life, 0.8));
    let drift = (noise(i * 0.1, life * 2) - 0.5) * spread * 2;
    let xx = cx + drift;
    let a = lerp(200, 8, life);
    // color shifts warm->cool as they join the field
    let r = lerp(90, 180, life);
    let g = lerp(70, 195, life);
    let b = lerp(80, 215, life);
    fill(r, g, b, a);
    let s = lerp(3, 1, life);
    noStroke();
    ellipse(xx, yy, s, s);
  }

  // Faint suggestion of head where outline last holds
  noStroke();
  for (let i = 0; i < 1200; i++) {
    let ang = random(TWO_PI);
    let rr = random(0, 45);
    let xx = cx + cos(ang) * rr;
    let yy = figTop - 30 + sin(ang) * rr * 1.1;
    let a = map(rr, 0, 45, 160, 10);
    fill(60, 45, 50, a);
    ellipse(xx, yy, 2, 2);
  }

  // Soft vignette
  for (let i = 0; i < 200; i++) {
    noFill();
    stroke(10, 10, 20, 2);
    rect(i, i, width - i * 2, height - i * 2);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Upper: the void / beyond
  // Lower: the warm world of the living
  // Horizon threshold around y = 1150

  // --- Sky / the beyond ---
  for (let y = 0; y < 1150; y++) {
    let t = y / 1150;
    let r = lerp(12, 40, t);
    let g = lerp(14, 34, t);
    let b = lerp(30, 48, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // faint stars / dispersed souls
  noStroke();
  for (let i = 0; i < 900; i++) {
    let x = random(width);
    let y = random(1150);
    let n = noise(x * 0.004, y * 0.004);
    let a = map(n, 0, 1, 0, 180) * (1 - y / 1150) * 0.9;
    fill(230, 225, 210, a * random(0.3, 1));
    let s = random(1, 3.5);
    circle(x, y, s);
  }

  // soft luminous mist gathering near the horizon (dissolution)
  for (let i = 0; i < 4000; i++) {
    let x = random(width);
    let y = 1150 - abs(randomGaussian() * 220);
    if (y < 0) continue;
    let d = 1 - (1150 - y) / 400;
    fill(200, 190, 175, 6 + d * 8);
    circle(x, y, random(3, 10));
  }

  // --- The living world (lower) ---
  for (let y = 1150; y < height; y++) {
    let t = (y - 1150) / (height - 1150);
    let r = lerp(120, 60, t);
    let g = lerp(70, 28, t);
    let b = lerp(40, 20, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // warm ground texture
  for (let i = 0; i < 6000; i++) {
    let x = random(width);
    let y = random(1150, height);
    let n = noise(x * 0.006, y * 0.006);
    fill(150 * n + 40, 90 * n + 20, 40 * n + 10, 40);
    circle(x, y, random(2, 7));
  }

  // --- The path toward the threshold ---
  noStroke();
  for (let i = 0; i < 2500; i++) {
    let t = random();
    let y = lerp(height, 1150, t);
    let w = lerp(380, 20, t);
    let cx = width / 2 + sin(t * 1.2) * 30;
    let x = cx + random(-w / 2, w / 2);
    let bright = lerp(90, 200, t);
    fill(bright, bright * 0.9, bright * 0.7, 50);
    circle(x, y, random(2, 6));
  }

  // --- The small light we carry ---
  let lx = width / 2 + 20;
  let ly = 1280;
  for (let r = 160; r > 0; r -= 4) {
    let a = map(r, 0, 160, 120, 0);
    fill(255, 230, 170, a * 0.5);
    circle(lx, ly, r);
  }
  fill(255, 245, 210);
  circle(lx, ly, 14);

  // --- The threshold glow (horizon line dissolving) ---
  for (let i = 0; i < 3000; i++) {
    let x = random(width);
    let y = 1150 + randomGaussian() * 40;
    fill(210, 180, 150, 10);
    circle(x, y, random(2, 8));
  }

  // faint vignette
  for (let i = 0; i < 1; i++) {
    noFill();
    for (let r = 0; r < 700; r += 6) {
      stroke(5, 5, 10, map(r, 0, 700, 60, 0));
      strokeWeight(14);
      ellipse(width / 2, height / 2, width + r * 2.2, height + r * 2.2);
    }
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Sky gradient: warm below to deep cool above
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(15, 210, pow(1 - t, 1.6));
    let g = lerp(22, 150, pow(1 - t, 1.5));
    let b = lerp(40, 110, pow(1 - t, 1.3));
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Faint distant stars / particles of continuity high up
  noStroke();
  for (let i = 0; i < 400; i++) {
    let x = random(width);
    let y = random(0, height * 0.55);
    let a = map(y, 0, height * 0.55, 180, 20);
    fill(255, 250, 230, a * random(0.3, 1));
    circle(x, y, random(1, 3.5));
  }

  // The doorway: a glowing arch in the lower-center
  let cx = width / 2;
  let doorW = 520;
  let doorTop = 760;
  let doorBottom = height - 120;

  // warm glow halo behind the door
  for (let r = 620; r > 0; r -= 6) {
    let a = map(r, 0, 620, 70, 0);
    fill(255, 210, 150, a);
    ellipse(cx, (doorTop + doorBottom) / 2, r * 1.4, r * 1.8);
  }

  // The lit room behind the threshold
  push();
  noStroke();
  fill(255, 236, 200);
  beginShape();
  vertex(cx - doorW / 2, doorBottom);
  vertex(cx - doorW / 2, doorTop + 180);
  bezierVertex(cx - doorW / 2, doorTop, cx + doorW / 2, doorTop, cx + doorW / 2, doorTop + 180);
  vertex(cx + doorW / 2, doorBottom);
  endShape(CLOSE);
  pop();

  // Dissolving figure standing in the doorway
  let fx = cx;
  let fyTop = 1040;
  let fyBottom = doorBottom - 40;

  // Build figure as a column of particles that thin toward the top
  for (let i = 0; i < 9000; i++) {
    // vertical position, more density at bottom
    let v = pow(random(), 0.6);
    let y = lerp(fyTop, fyBottom, v);
    // figure silhouette width profile
    let bodyT = (y - fyTop) / (fyBottom - fyTop);
    let wProfile = sin(bodyT * PI) * 70 + 55;
    // head region narrows
    if (bodyT < 0.18) wProfile = 60 * sin(map(bodyT, 0, 0.18, 0, PI));
    let x = fx + random(-1, 1) * wProfile;

    // dissolution: upper parts drift and scatter
    let scatter = pow(1 - v, 2);
    x += random(-1, 1) * scatter * 260;
    y -= random(0, 1) * scatter * 420;

    // probability a particle survives decreases upward
    if (random() < scatter * 0.75) continue;

    let a = lerp(230, 40, scatter);
    // color shifts from dark warm body to pale light as it rises
    let r = lerp(40, 255, scatter);
    let g = lerp(30, 240, scatter);
    let b = lerp(55, 210, scatter);
    fill(r, g, b, a);
    circle(x, y, random(1.5, 4) * (1 - scatter * 0.4));
  }

  // Rising particles above the figure drifting toward the stars
  for (let i = 0; i < 1400; i++) {
    let t = random();
    let y = lerp(fyTop, 300, t);
    let spread = lerp(90, 500, t);
    let x = cx + random(-spread, spread);
    let a = lerp(160, 15, t);
    fill(255, 245, 225, a);
    circle(x, y, random(1, 3));
  }

  // Soft threshold light beam rising from the door
  push();
  blendMode(SCREEN);
  for (let i = 0; i < 60; i++) {
    let w = map(i, 0, 60, doorW, 40);
    let a = map(i, 0, 60, 2, 14);
    fill(255, 225, 180, a);
    noStroke();
    let yTop = map(i, 0, 60, doorTop + 120, 260);
    quad(cx - w / 2, doorBottom, cx + w / 2, doorBottom,
         cx + w * 0.3, yTop, cx - w * 0.3, yTop);
  }
  pop();

  // Darkened foreground floor to ground the scene
  noStroke();
  for (let y = doorBottom; y < height; y++) {
    let t = (y - doorBottom) / (height - doorBottom);
    fill(10, 12, 20, 255 * t);
    rect(0, y, width, 1);
  }

  // subtle vignette
  push();
  noFill();
  for (let r = 0; r < 300; r++) {
    stroke(5, 6, 15, map(r, 0, 300, 60, 0));
    ellipse(width / 2, height / 2, width + r * 4, height + r * 4);
  }
  pop();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep background: night below, pale threshold above
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(230, 12, t);
    let g = lerp(222, 16, t);
    let b = lerp(210, 34, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // The threshold of light — a vertical glowing gateway
  let cx = width / 2;
  noStroke();
  for (let i = 0; i < 260; i++) {
    let a = map(i, 0, 260, 90, 0);
    let w = map(i, 0, 260, 60, 620);
    fill(255, 248, 230, a * 0.5);
    ellipse(cx, height * 0.30, w, height * 1.4);
  }

  // Rising particles — the self dissolving into the whole
  for (let i = 0; i < 2600; i++) {
    let base = random(height * 0.55, height * 0.95);
    let n = noise(i * 0.05, base * 0.002);
    let spread = map(base, height * 0.55, height, 50, 260);
    let x = cx + map(n, 0, 1, -spread, spread) + random(-20, 20);
    // particles drift upward and fan out toward the light
    let rise = map(base, height * 0.55, height, 0.0, 1.0);
    let y = lerp(base, height * 0.18, rise * random(0.2, 1.0) * 0.4);
    let s = map(base, height * 0.55, height, 1.5, 6) * random(0.5, 1.3);
    let warmth = map(y, height * 0.15, height, 1, 0);
    fill(lerp(255, 240, warmth), lerp(240, 170, warmth), lerp(220, 120, warmth), random(40, 160));
    ellipse(x, y, s, s);
  }

  // The figure — warm, loosening at the edges
  push();
  translate(cx, height * 0.70);
  for (let layer = 0; layer < 40; layer++) {
    let f = layer / 40;
    let alpha = map(layer, 0, 40, 160, 0);
    fill(235, 150, 90, alpha * 0.55);
    noStroke();
    beginShape();
    for (let a = -PI; a <= PI; a += 0.12) {
      let bodyR = 120 + 70 * sin(a * 2);
      // taper into a head/shoulders silhouette
      let shape = 1;
      if (a > 0) shape = map(a, 0, PI, 1.0, 0.3);
      else shape = map(a, -PI, 0, 0.3, 1.0);
      let edge = noise(cos(a) * 1.5 + layer * 0.3, sin(a) * 1.5) ;
      let r = (bodyR * shape) * (1 + f * 1.4) + edge * 60 * f;
      let x = cos(a) * r * 0.8;
      let y = sin(a) * r * 1.3 - 120 * f; // drift upward
      vertex(x, y);
    }
    endShape(CLOSE);
  }
  // head glow
  fill(250, 200, 140, 120);
  ellipse(0, -170, 150, 170);
  pop();

  // Soft vignette to hold the composition
  noFill();
  for (let i = 0; i < 180; i++) {
    stroke(8, 10, 20, i * 0.6);
    let m = i * 2.4;
    rect(-m, -m, width + m * 2, height + m * 2);
  }

  // A faint highest point of light — the far side
  noStroke();
  for (let i = 0; i < 120; i++) {
    fill(255, 255, 250, 3);
    ellipse(cx, height * 0.12, i * 3, i * 2);
  }
}

function setup() {
