  rect(-8, -70, 16, 70, 4);
  ellipse(0, -78, 22, 24);
  // rame
  stroke(10, 8, 12);
  strokeWeight(5);
  line(20, -40, 95, 40);
  noStroke();
  pop();

  // Feuilles qui tombent et dérivent
  for (let i = 0; i < 60; i++) {
    let x = random(width);
    let y = random(200, 1200);
    let s = random(6, 16);
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    fill(random(120, 180), random(50, 90), random(30, 50), random(120, 220));
    ellipse(0, 0, s, s * 0.5);
    pop();
  }
  // Feuilles sur l'eau
  for (let i = 0; i < 40; i++) {
    let x = random(width);
    let y = random(1210, 1900);
    let s = random(5, 12);
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    fill(random(90, 150), random(40, 70), random(25, 40), 160);
    ellipse(0, 0, s, s * 0.4);
    pop();
  }

  // Oiseaux lointains, points sombres
  stroke(40, 40, 50, 180);
  strokeWeight(2);
  noFill();
  for (let i = 0; i < 12; i++) {
    let x = random(width);
    let y = random(250, 600);
    let w = random(14, 26);
    arc(x - w / 4, y, w / 2, w / 3, PI, TWO_PI);
    arc(x + w / 4, y, w / 2, w / 3, PI, TWO_PI);
  }
  noStroke();

  // Vignette
  for (let i = 0; i < 300; i++) {
    let a = map(i, 0, 300, 60, 0);
    stroke(5, 5, 10, a * 0.03);
    noFill();
    strokeWeight(2);
    rect(i, i, width - 2 * i, height - 2 * i);
  }
}

function drawShore(baseX, left) {
  push();
  noStroke();
  let dir = left ? 1 : -1;
  // masse de terre sombre
  fill(20, 15, 18);
  beginShape();
  vertex(baseX, 2000);
  vertex(baseX, 1250);
  for (let t = 0; t <= 1; t += 0.1) {
    let x = baseX + dir * (260 - t * 180);
    let y = 1250 + t * 50 + noise(t * 3 + (left ? 0 : 10)) * 40;
    vertex(x, y);
  }
  vertex(baseX + dir * 80, 2000);
  endShape(CLOSE);

  // lueur rouge des vivants
  for (let i = 0; i < 25; i++) {
    let x = baseX + dir * random(20, 200);
    let y = random(1300, 1900);
    let a = random(20, 70);
    fill(150, 50, 35, a);
    ellipse(x, y, random(30, 90), random(20, 60));
  }
  pop();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Ciel dégradé : nuit profonde vers aube pâle à l'horizon
  for (let y = 0; y < 1200; y++) {
    let t = y / 1200;
    let r = lerp(15, 120, pow(t, 2.2));
    let g = lerp(18, 110, pow(t, 2.5));
    let b = lerp(30, 115, pow(t, 2.0));
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Halo de lumière lointaine (le seuil)
  noStroke();
  for (let r = 420; r > 0; r -= 4) {
    let a = map(r, 0, 420, 90, 0);
    fill(230, 215, 180, a);
    ellipse(800, 1180, r * 2.2, r * 1.4);
  }

  // Eaux noires
  for (let y = 1200; y < 2000; y++) {
    let t = (y - 1200) / 800;
    let c = lerp(25, 6, t);
    stroke(c, c + 4, c + 10);
    line(0, y, width, y);
  }

  // Reflet de la lumière sur l'eau
  noStroke();
  for (let i = 0; i < 200; i++) {
    let y = 1200 + random(0, 500);
    let w = map(y, 1200, 1700, 300, 40) * random(0.3, 1);
    let a = map(y, 1200, 1700, 70, 5) * random();
    fill(210, 195, 160, a);
    rect(800 - w / 2 + random(-30, 30), y, w, random(1, 3));
  }

  // Arbre mort à gauche
  drawTree(260, 1250);

  // Corbeaux qui s'envolent
  for (let i = 0; i < 14; i++) {
    let x = 300 + i * 70 + random(-40, 40);
    let y = 300 + i * 35 - random(0, 200) + noise(i) * 150;
    let s = map(i, 0, 14, 34, 10);
    drawCrow(x, y, s);
  }

  // Barque et passeur
  drawBoat(800, 1500);

  // Vignettage
  noFill();
  for (let i = 0; i < 300; i++) {
