    rect(m, m, width - 2 * m, height - 2 * m);
  }
}

function drawTree(x, baseY) {
  stroke(10, 10, 14);
  strokeWeight(22);
  line(x, baseY, x, baseY - 400);
  // branches
  branch(x, baseY - 400, -90, 180, 14, 0);
}

function branch(x, y, ang, len, w, depth) {
  if (depth > 4 || len < 12) return;
  let x2 = x + cos(radians(ang)) * len;
  let y2 = y + sin(radians(ang)) * len;
  strokeWeight(w);
  stroke(8, 8, 12);
  line(x, y, x2, y2);
  branch(x2, y2, ang - random(20, 40), len * 0.75, w * 0.7, depth + 1);
  branch(x2, y2, ang + random(20, 40), len * 0.72, w * 0.7, depth + 1);
}

function drawCrow(x, y, s) {
  stroke(5, 5, 8);
  strokeWeight(s * 0.14);
  noFill();
  // ailes en V
  let flap = random(-0.3, 0.1);
  arc(x - s * 0.5, y, s, s * 0.9, PI + 0.3 + flap, TWO_PI - 0.3);
  arc(x + s * 0.5, y, s, s * 0.9, PI + 0.3, TWO_PI - 0.3 - flap);
}

function drawBoat(x, y) {
  // Coque
  noStroke();
  fill(6, 6, 10);
  beginShape();
  vertex(x - 140, y);
  bezierVertex(x - 110, y + 45, x + 110, y + 45, x + 140, y);
  vertex(x + 115, y + 8);
  bezierVertex(x + 90, y + 32, x - 90, y + 32, x - 115, y + 8);
  endShape(CLOSE);

  // Passeur (silhouette encapuchonnée, debout)
  fill(4, 4, 8);
  beginShape();
  vertex(x + 15, y);
  vertex(x + 15, y - 170);
  bezierVertex(x + 15, y - 210, x - 25, y - 210, x - 25, y - 170);
  vertex(x - 25, y);
  endShape(CLOSE);
  // tête
  ellipse(x - 5, y - 185, 44, 54);

  // Rame
  stroke(4, 4, 8);
  strokeWeight(7);
  line(x - 20, y - 120, x - 150, y + 60);

  // Léger reflet sur le passeur venant de la lumière
  noStroke();
  fill(120, 115, 100, 40);
  ellipse(x + 10, y - 100, 10, 160);
}

