function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Vertical gradient: warm dense life below, pale luminous beyond above
  for (let y = 0; y < height; y++) {
    let t = y / height;
    // top: luminous near-white; bottom: deep warm earth
    let r = lerp(245, 40, t);
    let g = lerp(243, 24, t);
    let b = lerp(235, 30, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Soft halo of light in upper region (the threshold)
  noStroke();
  for (let i = 0; i < 260; i++) {
    let cx = width / 2 + random(-500, 500);
    let cy = random(-100, 650);
    let rad = random(80, 420);
    let a = map(cy, -100, 650, 20, 2);
    fill(255, 252, 245, a);
    ellipse(cx, cy, rad, rad);
  }

  // The rising, dissolving matter of life
  // Dense fragments at bottom, thinning and lightening upward
  let particles = 4200;
  for (let i = 0; i < particles; i++) {
    // bias towards lower-center, fanning out as it rises
    let base = pow(random(), 0.6); // 0 bottom .. 1 top
    let y = lerp(height + 50, -50, base);
    let spread = lerp(260, 820, base);
    let x = width / 2 + random(-spread, spread) + sin(base * 6 + i) * 40 * (1 - base);

    // density/noise driven presence — gaps appear higher up
    let n = noise(x * 0.002, y * 0.002, i * 0.01);
    if (n < base * 0.75) continue; // dissolve into light

    let s = lerp(14, 1.5, base) * random(0.4, 1.3);

    // colour: warm vibrant below → pale gold → white above
    let r = lerp(200, 255, base) + random(-20, 20);
    let g = lerp(70, 250, base) + random(-20, 20);
    let b = lerp(40, 240, base) + random(-10, 20);
    let a = lerp(230, 12, base);

    fill(constrain(r,0,255), constrain(g,0,255), constrain(b,0,255), a);
    ellipse(x, y, s, s);
  }

  // Occasional brighter embers near the base (the warmth of being)
  for (let i = 0; i < 400; i++) {
    let y = random(height * 0.55, height);
    let x = width / 2 + random(-300, 300) * random();
    let s = random(2, 9);
    fill(255, random(120, 200), random(40, 90), random(60, 180));
    ellipse(x, y, s, s);
  }

  // A faint vertical column of light — the passage itself
  for (let i = 0; i < 1200; i++) {
    let y = random(-50, height * 0.75);
    let x = width / 2 + random(-120, 120) * random();
    let a = map(y, -50, height * 0.75, 40, 2);
    fill(255, 255, 250, a);
    ellipse(x, y, random(2, 6), random(2, 6));
  }

  // Soft vignette to focus the ascent
  for (let i = 0; i < 200; i++) {
    noFill();
    stroke(20, 15, 15, 2);
    let m = i * 2;
    rect(-m, -m, width + 2 * m, height + 2 * m);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Dégradé vertical : obscurité en bas vers clarté en haut
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(230, 18, t);
    let g = lerp(222, 20, t);
    let b = lerp(205, 30, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Brume de fond, couches douces
  noStroke();
  for (let i = 0; i < 4000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.002, y * 0.002);
    let t = y / height;
    let a = map(n, 0, 1, 0, 40) * (1 - t * 0.5);
    let c = lerp(200, 40, t);
    fill(c, c * 0.98, c * 0.9, a);
    ellipse(x, y, random(2, 8));
  }

  // Le seuil : une porte de lumière au centre-haut
  let cx = width / 2;
  let doorTop = height * 0.18;
  let doorBottom = height * 0.62;
  let doorW = width * 0.22;

  // Halo rayonnant autour de la porte
  for (let r = 600; r > 0; r -= 4) {
    let a = map(r, 0, 600, 90, 0);
    fill(255, 252, 240, a * 0.25);
    ellipse(cx, (doorTop + doorBottom) / 2, r * 1.4, r * 2);
  }

  // Corps de la porte (lumineux, dissous aux bords)
  for (let y = doorTop; y < doorBottom; y += 1) {
    let ty = (y - doorTop) / (doorBottom - doorTop);
    let w = doorW * (0.8 + 0.4 * sin(ty * PI));
    for (let x = cx - w; x < cx + w; x += 2) {
      let edge = 1 - abs(x - cx) / w;
      let a = 180 * pow(edge, 1.5) * (1 - ty * 0.3);
      fill(255, 250, 235, a);
      rect(x, y, 2, 1);
    }
  }

  // Particules qui montent : la matière qui se défait et s'allège
  for (let i = 0; i < 2500; i++) {
    let baseX = cx + random(-doorW * 1.3, doorW * 1.3);
    let baseY = random(doorBottom * 0.3, doorBottom);
    // dispersion verticale : plus on monte, plus les particules s'écartent et pâlissent
    let riseT = random();
    let y = lerp(baseY, doorTop - 200, riseT);
    let drift = (noise(baseX * 0.01, i * 0.1) - 0.5) * 300 * riseT;
    let x = baseX + drift;

    let size = lerp(7, 1, riseT);
    let tv = y / height;
    let c = lerp(90, 255, 1 - tv);
    let a = lerp(160, 10, riseT);
    fill(c, c * 0.99, c * 0.9, a);
    ellipse(x, y, size);
  }

  // Masse dense en bas : ce qui fut lourd
  for (let i = 0; i < 3000; i++) {
    let x = random(width);
    let y = random(height * 0.7, height);
    let t = (y - height * 0.7) / (height * 0.3);
    let a = map(t, 0, 1, 10, 70);
    fill(10, 10, 15, a);
    ellipse(x, y, random(3, 12));
  }

  // Fines traces montantes, comme des souffles
  stroke(255, 250, 235, 25);
  strokeWeight(1);
  for (let i = 0; i < 60; i++) {
    let x0 = cx + random(-doorW, doorW);
    let y0 = random(doorBottom * 0.5, doorBottom);
    let px = x0, py = y0;
    for (let s = 0; s < 120; s++) {
      let nx = px + (noise(px * 0.01, py * 0.01 + i) - 0.5) * 6;
      let ny = py - random(1, 4);
      line(px, py, nx, ny);
      px = nx; py = ny;
      if (py < doorTop - 150) break;
    }
  }

  // Lumière centrale concentrée, le point le plus clair
  noStroke();
  for (let r = 180; r > 0; r -= 3) {
    let a = map(r, 0, 180, 120, 0);
    fill(255, 255, 248, a * 0.3);
    ellipse(cx, doorTop + 60, r, r);
  }

  // Vignette douce pour recentrer le regard
  for (let r = 1400; r > 900; r -= 5) {
    let a = map(r, 900, 1400, 0, 60);
    noFill();
    stroke(5, 5, 10, a * 0.15);
    strokeWeight(6);
    ellipse(width / 2, height / 2, r * 1.6, r * 1.9);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Vertical gradient: dark earthy base rising to pale luminous sky
  for (let y = 0; y < height; y++) {
    let t = y / height;
    // bottom: deep dense matter, top: dissolving light
    let r = lerp(240, 18, t);
    let g = lerp(236, 20, t);
    let b = lerp(228, 30, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // A faint horizon glow near upper-mid: the threshold
  noStroke();
  let hy = height * 0.30;
  for (let i = 0; i < 400; i++) {
    let rad = i * 3;
    let a = map(i, 0, 400, 40, 0);
    fill(255, 250, 235, a * 0.4);
    ellipse(width * 0.5, hy, rad * 2.4, rad);
  }

  // The dissolving form: a dense mass at the bottom
  // that breaks into particles rising and fading into light.
  let cx = width * 0.5;

  for (let i = 0; i < 90000; i++) {
    // vertical position biased toward bottom for density
    let yr = pow(random(), 0.6);
    let y = lerp(height * 0.95, height * 0.05, 1 - yr);
    let t = 1 - (y / height); // 0 bottom ... 1 top

    // horizontal spread increases as particles rise (dispersion)
    let spread = lerp(90, 650, pow(t, 1.3));
    let nx = noise(y * 0.002, i * 0.0001);
    let x = cx + (random(-1, 1) * spread) * (0.5 + nx);

    // skip to carve a vaguely body-like column lower down
    let bodyWidth = lerp(260, 40, t);
    if (t < 0.45) {
      if (abs(x - cx) > bodyWidth) continue;
    }

    // particle fades as it rises
    let alpha = lerp(230, 6, pow(t, 1.4));
    // color shifts from dark matter to warm light
    let pr = lerp(30, 255, pow(t, 1.1));
    let pg = lerp(28, 245, pow(t, 1.1));
    let pb = lerp(35, 220, pow(t, 1.1));

    let sz = lerp(3.2, 0.6, t) * random(0.5, 1.4);

    noStroke();
    fill(pr, pg, pb, alpha);
    ellipse(x, y, sz, sz);
  }

  // Scattered higher sparks released into the luminous field
  for (let i = 0; i < 6000; i++) {
    let y = random(0, height * 0.35);
    let t = 1 - (y / height);
    let x = cx + random(-1, 1) * lerp(300, 780, t);
    let a = random(2, 30);
    fill(255, 252, 240, a);
    noStroke();
    ellipse(x, y, random(0.5, 1.8));
  }

  // Subtle grain over everything for a painted texture
  for (let i = 0; i < 40000; i++) {
    let x = random(width);
    let y = random(height);
    let v = random(-12, 12);
    stroke(128 + v, 128 + v, 128 + v, 12);
    point(x, y);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Vertical gradient: dark warm earth below to luminous pale above
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(245, 28, t);
    let g = lerp(240, 20, t);
    let b = lerp(230, 30, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Luminous halo near the top — the clarity one dissolves into
  noStroke();
  for (let i = 0; i < 300; i++) {
    let rad = 900 - i * 3;
    let a = map(i, 0, 300, 0, 40);
    fill(255, 250, 235, a * 0.6);
    ellipse(width / 2, height * 0.12, rad, rad * 0.8);
  }

  // The dense woven mass of life at the bottom, unravelling upward
  let baseY = height * 0.95;
  for (let f = 0; f < 420; f++) {
    let x = random(width);
    let life = random(0.3, 1.0);
    let topReach = lerp(baseY, height * 0.2, life);
    let warmth = random();

    let r = lerp(180, 60, warmth);
    let gg = lerp(60, 30, warmth);
    let bb = lerp(50, 40, warmth);

    let px = x;
    let py = baseY;
    let step = 10;
    for (let y = baseY; y > topReach; y -= step) {
      let prog = map(y, baseY, topReach, 0, 1);
      // thicker, denser below; thinning above
      let sw = lerp(3.5, 0.3, prog) * life;
      let alpha = lerp(230, 0, prog);
      let drift = (noise(x * 0.01, y * 0.004, f) - 0.5) * lerp(8, 90, prog);
      let nx = x + drift + map(prog, 0, 1, 0, (x - width / 2) * 0.15);
      stroke(r, gg, bb, alpha);
      strokeWeight(sw);
      line(px, py, nx, y);
      px = nx;
      py = y;
    }
  }

  // Rising particles — matter transformed, drifting into light
  noStroke();
  for (let i = 0; i < 1400; i++) {
    let p = random();
    let y = lerp(height * 0.75, height * 0.08, p);
    let spread = lerp(120, 650, p);
    let x = width / 2 + random(-spread, spread) + (noise(i) - 0.5) * 200;
    let sz = lerp(5, 0.6, p) * random(0.5, 1.5);
    let alpha = lerp(200, 20, p) * random(0.4, 1);
    let warmth = 1 - p;
    fill(
      lerp(255, 200, warmth),
      lerp(250, 110, warmth),
      lerp(235, 80, warmth),
      alpha
    );
    ellipse(x, y, sz, sz);
  }

  // Faint suspended motes in the upper silence
  for (let i = 0; i < 400; i++) {
    let x = random(width);
    let y = random(height * 0.35);
    let sz = random(0.5, 2.5);
    fill(255, 255, 250, random(10, 70));
    ellipse(x, y, sz, sz);
  }

  // Soft vignette to hold the composition
  for (let i = 0; i < 200; i++) {
    noFill();
    stroke(20, 18, 25, 1.2);
    strokeWeight(4);
    ellipse(width / 2, height / 2, width + 400 - i * 6, height + 400 - i * 6);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Fond : ténèbres chaudes à gauche, clarté froide à droite
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x += 4) {
      let t = x / width;
      let n = noise(x * 0.002, y * 0.002) * 0.15;
      let r = lerp(40, 225, t) + n * 100;
      let g = lerp(25, 228, t) + n * 80;
      let b = lerp(30, 235, t) + n * 60;
      stroke(r, g, b);
      strokeWeight(4);
      point(x, y);
    }
  }

  // Le seuil lumineux vertical
  let sx = width * 0.58;
  noStroke();
  for (let i = 0; i < 300; i++) {
    let a = map(i, 0, 300, 0, 90);
    fill(255, 252, 240, a * 0.5);
    let w = map(i, 0, 300, 10, 420);
    rect(sx - w / 2, 0, w, height);
  }
  // coeur du seuil
  for (let i = 0; i < 60; i++) {
    fill(255, 255, 250, 8);
    rect(sx - 6 - i, 0, 12 + i * 2, height);
  }

  // Particules : la forme qui se dissout (côté vie)
  for (let i = 0; i < 2600; i++) {
    let px = random(width * 0.05, sx);
    let py = random(height);
    let edge = px / sx;
    // probabilité d'exister diminue près du seuil
    if (random() > edge * 0.6 + 0.2) {
      let n = noise(px * 0.01, py * 0.01);
      let r = lerp(230, 255, n);
      let gg = lerp(90, 200, n * edge);
      let b = lerp(40, 120, n);
      fill(r, gg, b, random(60, 200));
      let s = random(2, 9) * (1 - edge * 0.5);
      ellipse(px, py, s, s);
    }
  }

  // La silhouette franchissant le seuil
  push();
  translate(sx - 40, height * 0.5);
  // corps dissolvant : fait de points qui se raréfient vers le haut/droite
  for (let i = 0; i < 4000; i++) {
    // forme humaine simplifiée via champ
    let u = random();
    let v = random();
    let bodyX, bodyY;
    if (v < 0.18) { // tête
      let ang = random(TWO_PI);
      bodyX = cos(ang) * random(45);
      bodyY = -340 + sin(ang) * random(55);
    } else { // tronc + jambes
      bodyX = random(-70, 70);
      bodyY = map(v, 0.18, 1, -280, 420);
      bodyX *= map(bodyY, -280, 420, 1, 0.5);
    }
    // dissolution : les points vers le haut-droite s'évaporent
    let dissolve = map(bodyY, -340, 420, 1, 0.3) + random(-0.2, 0.2);
    if (random() > dissolve) continue;
    let drift = map(bodyY, -340, 420, 60, 5);
    let dx = bodyX + random(-drift, drift * 2);
    let dy = bodyY + random(-drift * 0.5, drift * 0.5);
    let bright = map(dy, -340, 420, 255, 60);
    fill(bright, bright * 0.95, bright * 0.85, random(90, 220));
    noStroke();
    ellipse(dx, dy, random(3, 8), random(3, 8));
  }
  pop();

  // Lueurs ascendantes au-delà du seuil (l'au-delà)
  for (let i = 0; i < 400; i++) {
    let px = random(sx + 100, width);
    let py = random(height);
    fill(255, 255, 250, random(10, 70));
    ellipse(px, py, random(2, 10), random(8, 40));
  }

  // Vignette douce
  noFill();
  for (let i = 0; i < 180; i++) {
    stroke(10, 8, 12, 2);
    strokeWeight(2);
    rect(i, i, width - i * 2, height - i * 2);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  // Sky gradient: twilight into darkness
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r, g, b;
    if (t < 0.5) {
      let u = t / 0.5;
      r = lerp(40, 120, u);
      g = lerp(30, 70, u);
      b = lerp(60, 80, u);
    } else {
      let u = (t - 0.5) / 0.5;
      r = lerp(120, 15, u);
      g = lerp(70, 18, u);
      b = lerp(80, 30, u);
    }
    stroke(r, g, b);
    line(0, y, width, y);
  }

  let horizon = height * 0.5;

  // Faint distant shore (far bank)
  noStroke();
  fill(25, 20, 35, 200);
  beginShape();
  vertex(0, horizon);
  for (let x = 0; x <= width; x += 20) {
    let h = noise(x * 0.002, 10) * 40;
    vertex(x, horizon - h - 10);
  }
  vertex(width, horizon);
  endShape(CLOSE);

  // Pale moon/light low on horizon
  let mx = width * 0.5, my = horizon - 20;
  for (let r = 180; r > 0; r -= 4) {
    fill(230, 200, 150, map(r, 0, 180, 40, 0));
    ellipse(mx, my, r * 2);
  }
  fill(240, 220, 180);
  ellipse(mx, my, 70);

  // Water
  for (let y = horizon; y < height; y++) {
    let t = (y - horizon) / (height - horizon);
    let r = lerp(15, 5, t);
    let g = lerp(18, 8, t);
    let b = lerp(30, 15, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Shimmering reflection of light on water
  for (let y = horizon; y < height; y += 3) {
    let t = (y - horizon) / (height - horizon);
    let w = 40 + t * 120;
    let wobble = sin(y * 0.3) * (10 + t * 40) * noise(y * 0.05);
    let alpha = map(t, 0, 1, 90, 0);
    stroke(230, 200, 150, alpha);
    strokeWeight(2 + t * 2);
    line(mx + wobble - w / 2, y, mx + wobble + w / 2, y);
  }
  strokeWeight(1);

  // Near shore (foreground bank, where the living stand)
  noStroke();
  fill(10, 8, 14);
  beginShape();
  vertex(0, height);
  vertex(0, height * 0.92);
  for (let x = 0; x <= width * 0.35; x += 20) {
    let h = noise(x * 0.004, 50) * 30;
    vertex(x, height * 0.92 - h);
  }
  vertex(width * 0.35, height);
  endShape(CLOSE);

  // A lone mourner on the near shore (silhouette)
  push();
  fill(5, 4, 8);
  let px = width * 0.14, py = height * 0.9;
  ellipse(px, py - 90, 34, 40);           // head
  beginShape();                            // body/cloak
  vertex(px - 30, py);
  vertex(px - 22, py - 70);
  vertex(px, py - 85);
  vertex(px + 22, py - 70);
  vertex(px + 30, py);
  endShape(CLOSE);
  pop();

  // The boat crossing toward the light
  push();
  let bx = width * 0.5, by = horizon + 110;
  // boat reflection
  noStroke();
  fill(0, 0, 0, 80);
  beginShape();
  vertex(bx - 120, by + 20);
  vertex(bx + 120, by + 20);
  vertex(bx + 70, by + 70);
  vertex(bx - 70, by + 70);
  endShape(CLOSE);
  // boat hull
  fill(8, 6, 10);
  beginShape();
  vertex(bx - 130, by);
  vertex(bx + 130, by);
  vertex(bx + 80, by + 34);
  vertex(bx - 80, by + 34);
  endShape(CLOSE);
  // ferryman silhouette
  fill(4, 3, 6);
  ellipse(bx + 60, by - 60, 22, 26);
  beginShape();
  vertex(bx + 45, by);
  vertex(bx + 50, by - 50);
  vertex(bx + 70, by - 50);
  vertex(bx + 75, by);
  endShape(CLOSE);
  // the pole/oar
  stroke(4, 3, 6);
  strokeWeight(5);
  line(bx + 70, by - 40, bx + 150, by + 30);
  noStroke();

  // the dying lantern on the boat
  let lx = bx - 70, ly = by - 20;
  for (let r = 90; r > 0; r -= 4) {
    fill(255, 180, 90, map(r, 0, 90, 35, 0));
    ellipse(lx, ly, r * 2);
  }
  fill(255, 210, 140);
  ellipse(lx, ly, 20);
  fill(255, 240, 200);
  ellipse(lx, ly, 9);
  pop();

  // Drifting embers / dissolving particles rising from the boat
  for (let i = 0; i < 60; i++) {
    let a = random(TWO_PI);
    let d = random(0, 300);
    let ex = width * 0.5 - 70 + cos(a) * d * 0.5;
    let ey = by0(horizon) - 20 - abs(sin(a)) * d - random(0, 150);
    let s = random(1, 4);
    let al = map(d, 0, 300, 180, 10);
    fill(255, 190, 120, al);
    noStroke();
    ellipse(ex, ey, s);
  }

  // Subtle vignette
  for (let r = 0; r < 600; r += 6) {
    noFill();
    stroke(0, 0, 0, map(r, 0, 600, 30, 0));
    strokeWeight(6);
    ellipse(width / 2, height / 2, width + 400 - r, height + 400 - r);
  }
}

function by0(h) {
  return h + 110;
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Sky: warm gold above fading to pale horizon
  for (let y = 0; y < 1000; y++) {
    let t = y / 1000;
    let c = lerpColor(color(230, 180, 90), color(220, 210, 180), t);
    stroke(c);
    line(0, y, width, y);
  }
  // Water: pale horizon fading to deep blue below
  for (let y = 1000; y < height; y++) {
    let t = (y - 1000) / 1000;
    let c = lerpColor(color(150, 170, 190), color(20, 30, 60), t);
    stroke(c);
    line(0, y, width, y);
  }

  // Sun / pale light disc near horizon
  noStroke();
  for (let r = 260; r > 0; r -= 2) {
    let a = map(r, 0, 260, 200, 0);
    fill(255, 245, 220, a * 0.5);
    ellipse(800, 980, r * 2.2, r * 2.2);
  }
  fill(250, 240, 215);
  ellipse(800, 980, 180, 180);

  // Reflection of light on water
  for (let i = 0; i < 400; i++) {
    let y = 1000 + random(0, 980);
    let spread = map(y, 1000, 1980, 20, 260);
    let x = 800 + random(-spread, spread);
    let a = map(y, 1000, 1980, 160, 0);
    stroke(250, 240, 215, a);
    strokeWeight(random(1, 3));
    let len = random(10, 40);
    line(x - len, y, x + len, y);
  }

  // Rising memory-lights (soft orbs drifting up)
  noStroke();
  for (let i = 0; i < 60; i++) {
    let x = random(width);
    let y = random(100, 950);
    let s = random(3, 14);
    let a = map(y, 100, 950, 20, 120);
    fill(255, 250, 230, a);
    ellipse(x, y, s, s);
  }

  // Ripples around the boat
  noFill();
  for (let i = 0; i < 6; i++) {
    let rw = 120 + i * 90;
    let a = map(i, 0, 6, 120, 0);
    stroke(220, 230, 240, a);
    strokeWeight(2);
    ellipse(760, 1320, rw * 2, rw * 0.5);
  }

  // The small boat
  push();
  translate(760, 1310);
  // hull
  fill(25, 20, 30);
  noStroke();
  beginShape();
  vertex(-110, 0);
  bezierVertex(-70, 35, 70, 35, 110, 0);
  bezierVertex(70, 18, -70, 18, -110, 0);
  endShape(CLOSE);
  // a tiny glowing light on the boat
  for (let r = 40; r > 0; r -= 2) {
    let a = map(r, 0, 40, 180, 0);
    fill(255, 240, 200, a);
    ellipse(0, -18, r, r);
  }
  fill(255, 250, 230);
  ellipse(0, -18, 14, 14);
  pop();

  // Faint distant far shore (barely visible line of shapes)
  noStroke();
  fill(200, 195, 175, 80);
  beginShape();
  vertex(0, 960);
  for (let x = 0; x <= width; x += 40) {
    let h = 960 - noise(x * 0.004) * 30;
    vertex(x, h);
  }
  vertex(width, 960);
  endShape(CLOSE);
}

function setup() {
