  noStroke();
  fill(40, 35, 55, 180);
  beginShape();
  vertex(0, horizon);
  for (let x = 0; x <= width; x += 20) {
    let h = noise(x * 0.002, 10) * 40;
    vertex(x, horizon - h);
  }
  vertex(width, horizon);
  endShape(CLOSE);

  // Sun/moon - a pale dying light near horizon
