  for (let r = 180; r > 0; r -= 4) {
    let a = map(r, 180, 0, 0, 60);
    fill(255, 230, 190, a);
    ellipse(width * 0.5, horizon - 30, r, r);
  }
  fill(255, 240, 210, 200);
  ellipse(width * 0.5, horizon - 30, 90, 90);

