    let t = (y - horizon) / (height - horizon);
    let r = lerp(60, 12, t);
    let g = lerp(55, 20, t);
    let b = lerp(80, 40, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Reflection of light on water
  noStroke();
  for (let y = horizon; y < height * 0.7; y += 3) {
    let w = map(y, horizon, height * 0.7, 20, 160);
    let a = map(y, horizon, height * 0.7, 120, 0);
    let wob = sin(y * 0.3) * 15;
    fill(255, 230, 190, a);
    ellipse(width * 0.5 + wob, y, w, 4);
  }

  // Ripples spreading on the water (traces of the departed)
  let cx = width * 0.5;
  let cy = height * 0.74;
  noFill();
  for (let i = 0; i < 7; i++) {
    let rad = 60 + i * 90;
    let a = map(i, 0, 7, 100, 10);
    stroke(200, 200, 220, a);
    strokeWeight(2);
    ellipse(cx, cy, rad * 2.2, rad * 0.7);
  }

  // The empty boat
  drawBoat(width * 0.5, height * 0.66, 360);

  // Faint drifting particles / spirits rising
  noStroke();
  for (let i = 0; i < 40; i++) {
    let px = cx + random(-200, 200);
    let py = height * 0.66 - random(0, 350);
    let s = random(2, 7);
    let a = map(py, height * 0.66, height * 0.3, 90, 0);
    fill(230, 230, 245, a);
    ellipse(px, py, s, s);
  }
}

function drawBoat(x, y, w) {
  push();
  translate(x, y);

  // Hull
  noStroke();
  fill(25, 22, 30);
  beginShape();
  vertex(-w / 2, 0);
  bezierVertex(-w / 2.2, 45, -w / 4, 70, 0, 72);
  bezierVertex(w / 4, 70, w / 2.2, 45, w / 2, 0);
  bezierVertex(w / 3, 14, -w / 3, 14, -w / 2, 0);
  endShape(CLOSE);

  // Inner shadow
  fill(45, 40, 52);
  beginShape();
  vertex(-w / 2 + 20, 4);
  bezierVertex(-w / 4, 44, w / 4, 44, w / 2 - 20, 4);
  bezierVertex(w / 3, 14, -w / 3, 14, -w / 2 + 20, 4);
  endShape(CLOSE);

  // A small pole with a dying lantern at the stern
  stroke(30, 26, 34);
  strokeWeight(6);
  line(w / 2 - 40, 6, w / 2 - 40, -120);

  // Lantern glow - almost extinguished
  noStroke();
  for (let r = 70; r > 0; r -= 3) {
    let a = map(r, 70, 0, 0, 80);
    fill(255, 200, 120, a);
    ellipse(w / 2 - 40, -125, r, r);
  }
  fill(255, 210, 140, 180);
  ellipse(w / 2 - 40, -125, 22, 28);

  // Reflection of boat
  push();
  scale(1, -1);
  translate(0, 20);
  fill(25, 22, 30, 70);
  beginShape();
  vertex(-w / 2, 0);
  bezierVertex(-w / 2.2, 45, -w / 4, 70, 0, 72);
  bezierVertex(w / 4, 70, w / 2.2, 45, w / 2, 0);
  bezierVertex(w / 3, 14, -w / 3, 14, -w / 2, 0);
  endShape(CLOSE);
  pop();

  pop();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  // 天空渐变：上冷蓝，下暖
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(40, 200, t);
    let g = lerp(55, 150, t);
    let b = lerp(90, 120, t);
    // 彼岸冷，此岸暖
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // 远处光晕（落日/将熄之光）
  let sunY = height * 0.42;
  noStroke();
  for (let i = 220; i > 0; i -= 2) {
    let a = map(i, 0, 220, 90, 0);
    fill(255, 210, 160, a * 0.4);
    ellipse(width * 0.5, sunY, i * 2.4, i * 2.4);
  }
  fill(255, 225, 185, 200);
  ellipse(width * 0.5, sunY, 160, 160);

  // 水面：从远到近
  let waterTop = height * 0.5;
  for (let y = waterTop; y < height; y++) {
    let t = (y - waterTop) / (height - waterTop);
    let r = lerp(60, 30, t);
    let g = lerp(70, 40, t);
    let b = lerp(110, 70, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // 水面倒影的光带
  noStroke();
  for (let y = waterTop; y < height; y += 3) {
    let t = (y - waterTop) / (height - waterTop);
    let wob = sin(y * 0.08) * (6 + t * 30);
    let a = map(t, 0, 1, 70, 5);
    fill(255, 215, 170, a);
    let w = (20 + t * 120);
    ellipse(width * 0.5 + wob, y, w, 3);
  }

  // 散落的将熄光点（记忆/烛火）
  for (let i = 0; i < 40; i++) {
    let x = random(width);
    let y = random(waterTop + 40, height);
    let s = random(3, 12) * (1 + (y - waterTop) / height);
    let a = random(30, 120);
    fill(255, 200, 150, a);
    noStroke();
    ellipse(x, y, s, s * 0.5);
    fill(255, 240, 210, a * 0.6);
    ellipse(x, y, s * 0.4, s * 0.25);
  }

  // 空舟
  drawBoat(width * 0.52, waterTop + 70, 220);

  // 低垂的雾气，让彼岸渐隐
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = random(waterTop - 80, waterTop + 60);
    let a = random(5, 25);
    fill(200, 200, 210, a);
    noStroke();
    ellipse(x, y, random(40, 140), random(10, 30));
  }

  // 整体暗角
  for (let i = 0; i < 400; i++) {
    let a = i / 400;
    noFill();
    stroke(10, 10, 25, 2);
    rect(i * 0.5, i * 0.6, width - i, height - i * 1.2, 20);
  }
}

function drawBoat(cx, cy, len) {
  push();
  translate(cx, cy);
  // 倒影
  push();
  scale(1, -0.5);
  translate(0, -cy * 0 - 20);
  fill(20, 20, 35, 80);
  noStroke();
  beginShape();
  vertex(-len / 2, 0);
  vertex(len / 2, 0);
  vertex(len / 2 - 25, 26);
  vertex(-len / 2 + 25, 26);
  endShape(CLOSE);
  pop();

  // 船身
  noStroke();
  fill(25, 22, 30);
  beginShape();
  vertex(-len / 2, 0);
  vertex(len / 2, 0);
  vertex(len / 2 - 25, 26);
  vertex(-len / 2 + 25, 26);
  endShape(CLOSE);

  // 船内侧高光
  fill(60, 55, 65);
  beginShape();
  vertex(-len / 2 + 6, 2);
  vertex(len / 2 - 6, 2);
  vertex(len / 2 - 25, 8);
  vertex(-len / 2 + 25, 8);
  endShape(CLOSE);

  // 一支立起的长桨（无人持握）
  stroke(30, 26, 34);
  strokeWeight(6);
  line(len * 0.2, 4, len * 0.35, -120);
  pop();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // 暮色渐变背景
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(230, 120, t);
    let g = lerp(200, 130, t);
    let b = lerp(180, 150, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // 地平线雾气
  noStroke();
  for (let i = 0; i < 60; i++) {
    let yy = height * 0.72 + random(-40, 40);
    fill(200, 190, 180, 8);
    ellipse(random(width), yy, random(300, 700), random(60, 120));
  }

  // 蒲公英花茎
  let stemX = width * 0.42;
  let stemBaseY = height * 0.95;
  let headX = width * 0.42;
  let headY = height * 0.42;

  stroke(90, 100, 80);
  strokeWeight(6);
  noFill();
  beginShape();
  for (let i = 0; i <= 20; i++) {
    let t = i / 20;
    let x = lerp(stemBaseY, headY, t);
    let px = lerp(stemX, headX, t) + sin(t * 3) * 25 * (1 - t);
    let py = lerp(stemBaseY, headY, t);
    curveVertex(px, py);
  }
  endShape();

  // 花托
  fill(100, 110, 85);
  noStroke();
  ellipse(headX, headY, 30, 30);

  // 蒲公英冠毛（未飘走的）
  let seeds = 180;
  for (let i = 0; i < seeds; i++) {
    let ang = random(TWO_PI);
    let rad = random(40, 180);
    // 右侧和上方的种子已飘走，留下空缺
    let side = cos(ang);
    if (side > 0.1 && random() < 0.75) continue;

    let ex = headX + cos(ang) * rad;
    let ey = headY + sin(ang) * rad * 0.9;

    // 绒毛茎
    stroke(240, 240, 235, 160);
    strokeWeight(1);
    line(headX + cos(ang) * 12, headY + sin(ang) * 12, ex, ey);

    drawFluff(ex, ey, 14, 200);
  }

  // 飘散的种子
  for (let i = 0; i < 70; i++) {
    let t = i / 70;
    // 从花向右上方飘散，越远越稀疏
    let baseX = headX + random(80, 1000) * (1 - t * 0.2);
    let baseY = headY - random(0, 350) + random(-80, 120);
    let px = baseX + noise(i * 0.3) * 200;
    let py = baseY + sin(i) * 60;

    if (px > width || py < 0) continue;

    let alpha = map(px, headX, width, 220, 60);

    // 种子核
    stroke(120, 100, 80, alpha);
    strokeWeight(2);
    let fx = px + 10;
    let fy = py - 12;
    line(px, py, fx, fy);

    drawFluff(fx, fy, random(8, 16), alpha);
  }
}

function drawFluff(x, y, r, alpha) {
  stroke(250, 250, 245, alpha * 0.8);
  strokeWeight(0.8);
  let n = 10;
  for (let j = 0; j < n; j++) {
    let a = (j / n) * TWO_PI + random(-0.1, 0.1);
    let len = r * random(0.7, 1.1);
    line(x, y, x + cos(a) * len, y + sin(a) * len);
  }
  noStroke();
  fill(255, 255, 250, alpha * 0.5);
  ellipse(x, y, 3, 3);
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  // 垂直渐变：下方深暗，上方明亮虚空
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(240, 18, t);
    let g = lerp(236, 20, t);
    let b = lerp(220, 30, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // 门槛的光缝（中部的水平光带）
  noStroke();
  for (let i = 0; i < 300; i++) {
    let yy = 760 + i * 0.9;
    let a = map(i, 0, 300, 90, 0);
    fill(255, 250, 235, a);
    rect(0, yy, width, 2);
  }

  let cx = width / 2;
  let baseY = 1500; // 人形脚部

  // 人形的轮廓点集合（用噪声让边缘粗糙）
  // 身体部分实心而暗，向上逐渐溶解为微粒
  drawFigure(cx, baseY);

  // 上升的微粒云：从胸口向上飘散消失在光里
  for (let i = 0; i < 9000; i++) {
    let prog = random(); // 0底部 1顶部
    // 越往上越稀疏，越亮
    let y = lerp(baseY - 100, 150, Math.pow(prog, 0.6));
    // 水平扩散随高度增加
    let spread = lerp(90, 420, prog);
    let n = noise(i * 0.05, prog * 3);
    let x = cx + map(n, 0, 1, -spread, spread) + random(-30, 30);

    // 微粒在接近人形上部才密集
    let bodyMask = figureWidth(y, baseY);
    let near = abs(x - cx) < bodyMask + spread * 0.5;

    let alpha = lerp(140, 8, prog) * random(0.3, 1);
    if (!near) alpha *= 0.3;

    let c = lerp(50, 255, prog);
    fill(c, c - 5, c - 15, alpha);
    let s = lerp(4, 1, prog);
    ellipse(x, y, s, s);
  }
}

// 人形宽度随高度变化（简单的人体剖面）
function figureWidth(y, baseY) {
  let h = baseY - y; // 从脚往上的高度
  let total = 950;
  let f = constrain(h / total, 0, 1);
  // 腿、躯干、头的宽度包络
  let w;
  if (f < 0.45) w = lerp(55, 120, f / 0.45);       // 腿到臀
  else if (f < 0.82) w = lerp(120, 95, (f - 0.45) / 0.37); // 躯干
  else if (f < 0.9) w = lerp(95, 30, (f - 0.82) / 0.08);   // 颈
  else w = lerp(70, 10, (f - 0.9) / 0.1);          // 头
  return w;
}

function drawFigure(cx, baseY) {
  noStroke();
  // 实心暗色身体，底部最实，向上变淡
  for (let h = 0; h < 950; h += 2) {
    let y = baseY - h;
    let f = h / 950;
    let w = figureWidth(y, baseY);
    // 溶解系数：越高越碎
    let dissolve = Math.pow(f, 1.4);

    // 用多个小块组成一行，上部开始缺失
    let step = 4;
    for (let x = -w; x < w; x += step) {
      let edge = 1 - abs(x) / w;
      let nn = noise((x + 500) * 0.02, h * 0.02);
      // 上部按概率丢弃像素块
      if (nn < dissolve * 0.9 + 0.05) continue;
      if (edge < random() * dissolve) continue;

      let a = lerp(230, 30, f) * (0.5 + edge * 0.5);
      let c = lerp(15, 120, f);
      fill(c, c, c + 5, a);
      rect(cx + x, y, step, 2);
    }
  }

  // 身体底部投影淡化到地面
  for (let i = 0; i < 200; i++) {
    let a = map(i, 0, 200, 60, 0);
    fill(5, 5, 8, a);
    ellipse(cx, baseY + i * 1.2, 260 - i, 40 - i * 0.15);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  // 背景：下暖上冷的渐变
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(40, 18, t) + lerp(20, 0, t);
    let g = lerp(30, 20, t);
    let b = lerp(28, 45, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // 下方：完整温暖的"身体"——密集的暖色微粒聚成形
  // 上方：离散冷却的微尘，逐渐飘散
  let cx = width / 2;

  for (let i = 0; i < 26000; i++) {
    // 垂直分布，偏向下方更密
    let v = pow(random(), 0.6);        // 0底部密 1顶部疏
    let y = height - v * height * 1.05;

    // 消散程度随高度增加
    let dissolve = constrain((height - y) / height, 0, 1);

    // 水平：下方聚拢，上方扩散
    let spread = lerp(180, 620, pow(dissolve, 1.3));
    let n = noise(i * 0.01, dissolve * 3);
    let x = cx + (randomGaussian() * spread) + (n - 0.5) * 400 * dissolve;

    // 顶部的粒子被向上"抽离"
    let rise = dissolve * dissolve * 180;
    y -= rise * random();

    // 颜色：由暖转冷
    let warm = color(235, 170, 120, 70);
    let cool = color(150, 180, 210, 30);
    let c = lerpColor(warm, cool, pow(dissolve, 0.9));

    // 上方粒子更透明、更小
    let a = lerp(90, 12, dissolve);
    c.setAlpha(a * random(0.4, 1));

    let sz = lerp(5.5, 1.2, dissolve) * random(0.5, 1.3);

    noStroke();
    fill(c);
    ellipse(x, y, sz, sz);
  }

  // 一道微弱的"门槛"光，横贯中间偏上——过渡之处
  let gy = height * 0.42;
  noStroke();
  for (let i = 0; i < 400; i++) {
    let a = map(i, 0, 400, 0, 255);
    let band = 160;
    let yy = gy + sin(a) * 0;
    fill(255, 245, 230, 1.5);
    rect(0, gy - band + i * (band * 2 / 400), width, 2);
  }

  // 顶部几粒孤独远去的光点
  for (let i = 0; i < 60; i++) {
    let x = cx + randomGaussian() * 500;
    let y = random(0, height * 0.3);
    fill(210, 225, 240, random(10, 40));
    ellipse(x, y, random(1, 3));
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  // Background gradient: deep below, pale above (threshold)
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(230, 18, t);
    let g = lerp(228, 22, t);
    let b = lerp(222, 32, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Soft horizon glow (the threshold)
  noStroke();
  for (let i = 0; i < 300; i++) {
    let yy = height * 0.42 + random(-120, 120);
    let a = map(abs(yy - height * 0.42), 0, 120, 14, 0);
    fill(255, 250, 240, a);
    ellipse(width / 2, yy, width * 1.4, 160);
  }

  // The dissolving figure: particles dense below, scattering upward
  let cx = width / 2;
  let N = 9000;
  for (let i = 0; i < N; i++) {
    // vertical position: more density low, thinning high
    let v = pow(random(), 0.6); // 0 bottom-ish to 1 top
    let y = lerp(height * 0.96, height * 0.08, v);

    // horizontal spread grows as it rises (outline dissolves)
    let spread = lerp(70, 520, pow(v, 1.5));
    let nx = noise(i * 0.01, v * 2);
    let x = cx + (random(-1, 1)) * spread * (0.5 + nx);

    // body concentration near center-low
    let bodyPull = (1 - v) * 0.6;
    x = lerp(x, cx + random(-40, 40), bodyPull);

    // fading: dense/bright low, faint high
    let alpha = lerp(200, 6, v) * (0.6 + random(0.4));
    let sz = lerp(5.5, 1.2, v);

    // color shifts from warm body to cool void
    let r = lerp(245, 120, v);
    let g = lerp(238, 130, v);
    let b = lerp(225, 160, v);

    noStroke();
    fill(r, g, b, alpha);
    ellipse(x, y, sz, sz);
  }

  // A few rising sparks that reach the top and vanish
  for (let i = 0; i < 400; i++) {
    let v = random();
    let y = lerp(height * 0.4, -20, v);
    let x = cx + random(-700, 700) * random();
    let alpha = lerp(90, 0, v);
    fill(255, 252, 245, alpha);
    ellipse(x, y, random(1, 3));
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  // vertical gradient: dense dark below, luminous pale above
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(245, 28, t);
    let g = lerp(240, 26, t);
    let b = lerp(230, 34, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // the threshold: a soft horizontal band of light around 0.42
  let thy = height * 0.42;
  for (let y = thy - 160; y < thy + 160; y++) {
    let d = abs(y - thy) / 160;
    let a = (1 - d) * 90;
    stroke(255, 252, 240, a);
    line(0, y, width, y);
  }

  // the living mass: dense warm interwoven strokes rising from below,
  // dissolving as they approach the threshold
  for (let i = 0; i < 9000; i++) {
    // base position, more density low
    let bx = random(width);
    let by = lerp(height, thy - 40, pow(random(), 1.6));

    let life = constrain((height - by) / (height - (thy - 40)), 0, 1);

    // as strokes rise, they thin out and lighten
    let alpha = map(life, 0, 1, 180, 8);
    let len = map(life, 0, 1, 34, 6);
    let weight = map(life, 0, 1, 2.4, 0.4);

    // smoke-like drift via noise
    let n = noise(bx * 0.002, by * 0.002, i * 0.01);
    let ang = -HALF_PI + (n - 0.5) * PI * 1.3 * (0.3 + life);

    // warm living color fading toward pale
    let r = lerp(120, 230, life) + random(-20, 20);
    let g = lerp(60, 225, life) + random(-15, 15);
    let b = lerp(50, 220, life) + random(-10, 10);

    stroke(r, g, b, alpha);
    strokeWeight(weight);

    let x2 = bx + cos(ang) * len;
    let y2 = by + sin(ang) * len;
    line(bx, by, x2, y2);
  }

  // faint motes above the threshold — remnants almost gone
  noStroke();
  for (let i = 0; i < 400; i++) {
    let x = random(width);
    let y = random(0, thy - 20);
    let t = y / thy;
    let a = map(t, 0, 1, 2, 40);
    fill(255, 253, 245, a);
    circle(x, y, random(1, 4));
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  // 背景渐变：上方浓夜，下方澄明
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r, g, b;
    if (t < 0.5) {
      let k = t / 0.5;
      r = lerp(12, 60, k);
      g = lerp(16, 72, k);
      b = lerp(34, 96, k);
    } else {
      let k = (t - 0.5) / 0.5;
      r = lerp(120, 236, k);
      g = lerp(150, 240, k);
      b = lerp(180, 246, k);
    }
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // 中间界线：模糊的渡口
  let mid = height * 0.5;
  noStroke();
  for (let i = 0; i < 400; i++) {
    let yy = mid + random(-120, 120);
    let a = map(abs(yy - mid), 0, 120, 70, 0);
    fill(255, 255, 255, a);
    let xx = random(width);
    ellipse(xx, yy, random(30, 160), random(2, 8));
  }

  // 光点渡过：下密上稀，从形状走向无形
  for (let i = 0; i < 2600; i++) {
    let x = random(width);
    // 分布偏向整幅画，但形态随高度变化
    let y = random(height);
    let t = y / height;

    // 上方（夜色）：光点密集、清晰、冷色
    // 下方（澄明）：光点稀疏、融化、暖白
    let keep;
    if (t < 0.45) {
      keep = random() < 0.9;
    } else if (t < 0.55) {
      keep = random() < 0.4;
    } else {
      keep = random() < 0.25;
    }
    if (!keep) continue;

    let n = noise(x * 0.004, y * 0.004);
    let size = lerp(6, 1, t) * (0.5 + n);
    let alpha;
    let cr, cg, cb;

    if (t < 0.5) {
      alpha = map(t, 0, 0.5, 220, 120);
      cr = 200 + n * 55;
      cg = 215 + n * 40;
      cb = 240;
    } else {
      alpha = map(t, 0.5, 1, 120, 30) * (0.6 + n * 0.6);
      cr = 255;
      cg = 255;
      cb = 252;
      size *= (1.5 - t * 0.5);
    }

    noStroke();
    fill(cr, cg, cb, alpha);
    ellipse(x, y, size, size);
  }

  // 一道上升的微光柱，连接两岸
  for (let i = 0; i < 600; i++) {
    let cx = width * 0.5 + sin(i * 0.05) * (40 + i * 0.1);
    let y = map(i, 0, 600, height * 0.95, height * 0.05);
    let a = map(i, 0, 600, 60, 5);
    fill(255, 255, 255, a);
    noStroke();
    let s = map(i, 0, 600, 5, 1);
    ellipse(cx + random(-20, 20), y, s, s);
  }

  // 最下方的澄明：化入纯净
  noStroke();
  for (let i = 0; i < 300; i++) {
    let y = random(height * 0.85, height);
    let a = map(y, height * 0.85, height, 0, 40);
    fill(255, 255, 255, a);
    ellipse(random(width), y, random(100, 400), random(10, 40));
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Sky gradient
  for (let y = 0; y < 1200; y++) {
    let t = y / 1200;
    let r = lerp(40, 230, t);
    let g = lerp(30, 150, t);
    let b = lerp(70, 120, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Warm glow between the trees
  noStroke();
  for (let r = 600; r > 0; r -= 4) {
    let a = map(r, 0, 600, 90, 0);
    fill(255, 220, 140, a);
    ellipse(800, 850, r * 1.4, r);
  }

  // Soil
  for (let y = 1200; y < 2000; y++) {
    let t = (y - 1200) / 800;
    stroke(lerp(70, 30, t), lerp(45, 20, t), lerp(40, 25, t));
    line(0, y, width, y);
  }
  // ground line glow
  noStroke();
  fill(255, 210, 150, 40);
  ellipse(800, 1200, 1400, 160);

  // Braided roots underground
  strokeWeight(14);
  noFill();
  for (let i = 0; i < 6; i++) {
    stroke(60 + i * 8, 35, 30);
    let off = i * 20 - 50;
    beginShape();
    for (let y = 1200; y < 1900; y += 20) {
      let x = 800 + sin((y + off) * 0.02) * (120 + off * 0.3)
              + noise(i, y * 0.01) * 60 - 30;
      vertex(x, y);
    }
    endShape();
  }

  // Left tree trunk
  drawTree(560, 1200, -1);
  // Right tree trunk
  drawTree(1040, 1200, 1);

  // Falling leaves / warmth particles
  for (let i = 0; i < 60; i++) {
    let x = random(width);
    let y = random(200, 1150);
    let s = random(6, 16);
    fill(255, random(160, 220), random(90, 140), random(120, 200));
    noStroke();
    ellipse(x, y, s, s * 0.7);
  }
}

function drawTree(baseX, baseY, dir) {
  stroke(50, 30, 25);
  strokeWeight(60);
  noFill();
  // trunk leaning toward center
  beginShape();
  let topX = baseX + dir * -40;
  for (let t = 0; t <= 1; t += 0.05) {
    let x = lerp(baseX, topX + dir * 60, t);
    let y = lerp(baseY, 760, t);
    vertex(x, y);
  }
  endShape();

  branch(topX + dir * 60, 760, dir * 90 + (dir>0?-120:0), 170, 34, dir);
}

function branch(x, y, angle, len, w, dir) {
  if (w < 3) return;
  let rad = radians(angle);
  let x2 = x + cos(rad) * len;
  let y2 = y + sin(rad) * len;
  stroke(55, 33, 28);
  strokeWeight(w);
  line(x, y, x2, y2);

  if (w < 12) {
    noStroke();
    fill(255, 180 + random(-30, 30), 100, 200);
    ellipse(x2, y2, 30, 22);
  }

  branch(x2, y2, angle - 28 + random(-8, 8), len * 0.75, w * 0.68, dir);
  branch(x2, y2, angle + 28 + random(-8, 8), len * 0.75, w * 0.68, dir);
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep night background
  background(14, 12, 28);

  // Two centers of love
  let aX = 580, aY = 820;
  let bX = 1040, bY = 1200;

  // Shared field: glowing overlap between the two
  for (let y = 0; y < height; y += 5) {
    for (let x = 0; x < width; x += 5) {
      let dA = dist(x, y, aX, aY);
      let dB = dist(x, y, bX, bY);
      // field strength from both centers
      let fA = 220000 / (dA * dA + 8000);
      let fB = 220000 / (dB * dB + 8000);
      let overlap = fA * fB * 0.9;
      let warm = constrain(overlap, 0, 1);
      if (warm > 0.02) {
        noStroke();
        fill(255 * warm, 180 * warm, 120 * warm, 60 * warm);
        rect(x, y, 5, 5);
      }
    }
  }

  // Draw the two glowing orbs
  drawOrb(aX, aY, 150, color(255, 150, 120), color(255, 90, 70));
  drawOrb(bX, bY, 130, color(150, 180, 255), color(90, 120, 255));

  // Gentle connecting filaments
  stroke(255, 220, 190, 40);
  strokeWeight(1.2);
  noFill();
  for (let i = 0; i < 14; i++) {
    let t = i / 13;
    let sway = sin(t * PI) * (60 + i * 5);
    beginShape();
    for (let s = 0; s <= 1; s += 0.05) {
      let x = lerp(aX, bX, s) + sin(s * PI) * sway * (i % 2 ? 1 : -1) * 0.4;
      let y = lerp(aY, bY, s) - sin(s * PI) * 80;
      curveVertex(x, y);
    }
    endShape();
  }

  // Scattered stars around them
  for (let i = 0; i < 160; i++) {
    let x = random(width);
    let y = random(height);
    let dA = dist(x, y, aX, aY);
    let dB = dist(x, y, bX, bY);
    if (dA > 200 && dB > 200) {
      let s = random(0.5, 2.5);
      noStroke();
      fill(255, 255, 255, random(40, 180));
      ellipse(x, y, s, s);
    }
  }
}

function drawOrb(cx, cy, r, inner, outer) {
  noStroke();
  // outer halo
  for (let i = 8; i > 0; i--) {
    let rr = r * (1 + i * 0.35);
    let a = map(i, 0, 8, 90, 0);
    fill(red(outer), green(outer), blue(outer), a);
    ellipse(cx, cy, rr * 2, rr * 2);
  }
  // core gradient
  for (let i = r; i > 0; i -= 3) {
    let t = i / r;
    let c = lerpColor(inner, outer, t);
    fill(red(c), green(c), blue(c), 230);
    ellipse(cx, cy, i * 2, i * 2);
  }
  // bright center
  fill(255, 255, 255, 220);
  ellipse(cx - r * 0.2, cy - r * 0.2, r * 0.4, r * 0.4);
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Sky gradient
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(250, 240, t);
    let g = lerp(225, 170, t);
    let b = lerp(200, 150, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  let groundY = 1150;

  // Underground gradient
  for (let y = groundY; y < height; y++) {
    let t = (y - groundY) / (height - groundY);
    let r = lerp(90, 45, t);
    let g = lerp(55, 25, t);
    let b = lerp(50, 30, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Warm glow where roots meet
  let cx = 800, cy = 1500;
  noStroke();
  for (let i = 220; i > 0; i -= 4) {
    fill(255, 180, 90, 6);
    ellipse(cx, cy, i * 2.2, i * 2);
  }

  // Draw roots underground
  drawRoots(700, groundY, cx, cy, 1);
  drawRoots(900, groundY, cx, cy, -1);

  // Intertwined root knot at center
  stroke(60, 35, 30);
  noFill();
  for (let a = 0; a < 40; a++) {
    strokeWeight(random(2, 6));
    stroke(70 + random(30), 45 + random(20), 35, 200);
    let ang = random(TWO_PI);
    let x = cx + cos(ang) * random(20, 140);
    let y = cy + sin(ang) * random(20, 120);
    bezier(cx, cy, cx + random(-60, 60), cy + random(-60, 60),
           x + random(-40, 40), y + random(-40, 40), x, y);
  }

  // Two trunks rising
  drawTrunk(700, groundY);
  drawTrunk(900, groundY);

  // Canopies - two blended into one
  drawCanopy(700, 620, color(220, 120, 140));
  drawCanopy(900, 580, color(150, 160, 210));
  drawCanopy(800, 500, color(255, 200, 150), 260);

  // Sun
  noStroke();
  fill(255, 240, 200, 180);
  ellipse(1250, 320, 260, 260);
  fill(255, 250, 230);
  ellipse(1250, 320, 180, 180);
}

function drawTrunk(baseX, groundY) {
  noStroke();
  fill(80, 50, 40);
  beginShape();
  vertex(baseX - 45, groundY);
  bezierVertex(baseX - 30, groundY - 200, baseX - 20, groundY - 350, baseX - 25, 700);
  vertex(baseX + 25, 700);
  bezierVertex(baseX + 20, groundY - 350, baseX + 30, groundY - 200, baseX + 45, groundY);
  endShape(CLOSE);
}

function drawRoots(startX, startY, cx, cy, dir) {
  stroke(70, 42, 34);
  noFill();
  for (let i = 0; i < 14; i++) {
    strokeWeight(random(2, 7));
    let ex = cx + random(-200, 200) * dir;
    let ey = cy + random(-120, 220);
    bezier(startX, startY,
           startX + random(-80, 80), startY + random(100, 250),
           ex + random(-60, 60), ey - random(60, 160),
           ex, ey);
  }
}

function drawCanopy(cx, cy, col, sz) {
  sz = sz || 230;
  noStroke();
  for (let i = 0; i < 400; i++) {
    let ang = random(TWO_PI);
    let rad = random(sz) * sqrt(random());
    let x = cx + cos(ang) * rad;
    let y = cy + sin(ang) * rad * 0.9;
    let a = map(rad, 0, sz, 160, 20);
    fill(red(col) + random(-20, 20), green(col) + random(-20, 20),
         blue(col) + random(-20, 20), a);
    ellipse(x, y, random(14, 34), random(14, 34));
  }
}

