function drawTrunk(x, baseY, dir) {
  stroke(70, 45, 35);
  noFill();
  strokeWeight(40);
  beginShape();
  for (let t = 0; t <= 1; t += 0.05) {
    let yy = lerp(baseY, 780, t);
    let xx = x + dir * sin(t * PI) * 60;
    vertex(xx, yy);
  }
  endShape();
}

function drawRoots(x, startY, tx, ty, depth, dir) {
  if (depth <= 0) return;
  let ex = lerp(x, tx, 0.35) + dir * random(-30, 30);
  let ey = lerp(startY, ty, 0.35) + random(-20, 60);
  stroke(60, 40, 35, 180);
  strokeWeight(depth * 2.5);
  noFill();
  beginShape();
  vertex(x, startY);
  let cx = (x + ex) / 2 + random(-40, 40);
  let cy = (startY + ey) / 2;
  quadraticVertex(cx, cy, ex, ey);
  endShape();
  drawRoots(ex, ey, tx, ty, depth - 1, dir);
  if (random() < 0.6) drawRoots(ex, ey, tx, ty, depth - 2, -dir);
}

function drawCanopy(cx, cy, rad, col) {
  noStroke();
  for (let i = 0; i < 400; i++) {
    let a = random(TWO_PI);
    let rr = rad * sqrt(random());
    let px = cx + cos(a) * rr * 1.3;
    let py = cy + sin(a) * rr;
    let shade = lerp(0.6, 1, random());
    fill(red(col) * shade, green(col) * shade, blue(col) * shade, 200);
    ellipse(px, py, random(10, 26), random(10, 26));
  }
}

function heartShape(x, y, s) {
  beginShape();
  for (let a = 0; a < TWO_PI; a += 0.1) {
    let px = 16 * pow(sin(a), 3);
    let py = 13 * cos(a) - 5 * cos(2 * a) - 2 * cos(3 * a) - cos(4 * a);
    vertex(x + px * s / 16, y - py * s / 16);
  }
  endShape(CLOSE);
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Twilight gradient background
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(40, 180, t) + 20 * sin(t * 3);
    let g = lerp(30, 90, t);
    let b = lerp(70, 80, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Warm glow in the center
  noStroke();
  let cx = width / 2, cy = height * 0.42;
  for (let i = 300; i > 0; i -= 2) {
    let a = map(i, 0, 300, 90, 0);
    fill(255, 210, 150, a);
    ellipse(cx, cy, i * 3, i * 3);
  }

  // Scattered soft stars
  for (let i = 0; i < 120; i++) {
    let x = random(width), y = random(height * 0.6);
    fill(255, 240, 220, random(40, 160));
    ellipse(x, y, random(2, 6));
  }

  // Ground
  fill(25, 20, 35);
  rect(0, height * 0.72, width, height * 0.28);

  // Two trees leaning toward each other
  drawTree(cx - 260, height * 0.72, -1, color(90, 50, 70));
  drawTree(cx + 260, height * 0.72, 1, color(70, 50, 90));

  // Tangled roots beneath
  stroke(120, 70, 60, 180);
  strokeWeight(5);
  noFill();
  for (let i = 0; i < 14; i++) {
    let sx = cx - 260 + random(-40, 40);
    let ex = cx + 260 + random(-40, 40);
    let my = height * 0.72 + random(60, 320);
    beginShape();
    vertex(sx, height * 0.72);
    bezierVertex(cx - 100, my, cx + 100, my + random(-80, 80), ex, height * 0.72);
    endShape();
  }

  // Two glowing hearts of light meeting at the warm center
  noStroke();
  drawHeart(cx, cy, 70, color(255, 170, 140, 220));
  drawHeart(cx, cy, 40, color(255, 230, 200, 240));
}

function drawTree(baseX, baseY, dir, col) {
  stroke(col);
  strokeWeight(34);
  noFill();
  // trunk leaning toward center
  let topX = baseX + dir * 160;
  let topY = baseY - 560;
  beginShape();
  vertex(baseX, baseY);
  bezierVertex(baseX + dir * 30, baseY - 250, baseX + dir * 100, baseY - 400, topX, topY);
  endShape();

  // branches
  branch(topX, topY, -PI / 2 + dir * 0.6, 150, 18, col);
}

function branch(x, y, angle, len, w, col) {
  if (len < 14) return;
  let x2 = x + cos(angle) * len;
  let y2 = y + sin(angle) * len;
  stroke(col);
  strokeWeight(w);
  line(x, y, x2, y2);

  // blossom buds
  if (len < 50) {
    noStroke();
    fill(255, 200, 170, 200);
    ellipse(x2, y2, random(8, 18));
    stroke(col);
  }

  branch(x2, y2, angle - random(0.3, 0.6), len * 0.72, w * 0.7, col);
  branch(x2, y2, angle + random(0.3, 0.6), len * 0.72, w * 0.7, col);
}

function drawHeart(x, y, s, col) {
  fill(col);
  beginShape();
  for (let a = 0; a < TWO_PI; a += 0.05) {
    let hx = 16 * pow(sin(a), 3);
    let hy = -(13 * cos(a) - 5 * cos(2 * a) - 2 * cos(3 * a) - cos(4 * a));
    vertex(x + hx * s / 16, y + hy * s / 16);
  }
  endShape(CLOSE);
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
