  for (let y = 0; y < height; y++) {
    let t = y / height;
    let c = lerpColor(color(18, 20, 40), color(40, 25, 55), t);
    stroke(c);
    line(0, y, width, y);
  }

  // soft scattered stars of distant feeling
  noStroke();
  for (let i = 0; i < 400; i++) {
    let x = random(width);
    let y = random(height);
    let a = random(20, 90);
    fill(255, 240, 220, a);
    circle(x, y, random(1, 3));
  }

  let cx = width / 2;
  let cyA = height / 2 - 120;
  let cyB = height / 2 + 120;

