  drawOrb(cx + 230, cyB, 360, color(90, 150, 230));   // cool one

  // the third light born between them
  push();
  blendMode(SCREEN);
  let bx = cx;
  let by = (cyA + cyB) / 2;
  for (let r = 420; r > 0; r -= 6) {
    let a = map(r, 0, 420, 70, 0);
    fill(255, 230, 190, a);
    noStroke();
    circle(bx, by, r);
  }
  pop();

  // tender threads connecting them
  push();
  blendMode(SCREEN);
  stroke(255, 220, 200, 18);
  noFill();
  for (let i = 0; i < 40; i++) {
    let o = map(i, 0, 40, -160, 160);
    beginShape();
