  pop();
}

function drawOrb(x, y, size, col) {
  push();
  blendMode(SCREEN);
  for (let r = size; r > 0; r -= 4) {
    let t = r / size;
    let a = map(t, 0, 1, 180, 0);
    fill(red(col), green(col), blue(col), a);
    noStroke();
    circle(x, y, r);
  }
  // bright core
  fill(255, 250, 245, 200);
  circle(x, y, size * 0.12);
  pop();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep dusk background
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let c = lerpColor(color(18, 22, 46), color(40, 24, 50), t);
    stroke(c);
    line(0, y, width, y);
  }

  // Two centers
  let ax = width * 0.36, ay = height * 0.44;
  let bx = width * 0.64, by = height * 0.56;
  let midx = (ax + bx) / 2, midy = (ay + by) / 2;

  // The glowing field between them
  noStroke();
  for (let r = 620; r > 0; r -= 4) {
    let a = map(r, 0, 620, 90, 0);
    fill(255, 225, 160, a * 0.6);
    ellipse(midx, midy, r * 1.4, r);
  }

  // Soft particle haze in the shared space
  for (let i = 0; i < 2600; i++) {
    let ang = random(TWO_PI);
    let rad = random(1) * random(1) * 540;
    let px = midx + cos(ang) * rad * 1.2;
    let py = midy + sin(ang) * rad;
    let d = dist(px, py, midx, midy);
    let a = map(d, 0, 540, 120, 0);
    fill(255, random(200, 240), random(150, 200), a * 0.5);
    circle(px, py, random(1, 4));
  }

  // The two beings — warm and cool, keeping their own color
  drawOrb(ax, ay, 300, color(230, 90, 120), color(255, 180, 160));
  drawOrb(bx, by, 300, color(90, 150, 230), color(170, 210, 255));

  // Reaching tendrils of light between them
  stroke(255, 230, 190, 80);
  noFill();
  for (let i = 0; i < 40; i++) {
    let off = random(-120, 120);
    beginShape();
    let steps = 24;
    for (let s = 0; s <= steps; s++) {
      let t = s / steps;
      let x = lerp(ax, bx, t);
      let y = lerp(ay, by, t) + sin(t * PI) * off;
      let n = (noise(i * 0.3, t * 3) - 0.5) * 60;
      curveVertex(x + n, y + n);
    }
    strokeWeight(random(0.5, 2));
    endShape();
  }
}

function drawOrb(x, y, size, core, glow) {
  noStroke();
  for (let r = size; r > 0; r -= 3) {
    let t = r / size;
    let c = lerpColor(core, color(red(glow), green(glow), blue(glow), 0), t);
    c.setAlpha((1 - t) * 180 + 20);
    fill(c);
    circle(x, y, r);
  }
  // bright nucleus
  fill(255, 255, 240, 230);
  circle(x, y, size * 0.18);
}

function setup() {
