}

function draw() {
  // Deep twilight ground
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(18, 40, t);
    let g = lerp(20, 24, t);
    let b = lerp(38, 46, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Two centers
  let ax = width * 0.38, ay = height * 0.44;
  let bx = width * 0.62, by = height * 0.56;

  // The glowing field between them
  noStroke();
  let mx = (ax + bx) / 2, my = (ay + by) / 2;
  for (let i = 220; i > 0; i--) {
    let rad = i * 3.2;
    let a = map(i, 0, 220, 55, 0);
    fill(255, 150, 90, a * 0.5);
    ellipse(mx, my, rad * 1.4, rad);
  }

  // Draw each center as radiating warmth
  drawHeartGlow(ax, ay, 255, 110, 90);
  drawHeartGlow(bx, by, 255, 180, 120);

  // Soft threads of exchange
  stroke(255, 210, 170, 40);
  strokeWeight(1.2);
  noFill();
  for (let k = 0; k < 40; k++) {
    let off = map(k, 0, 40, -1, 1);
    beginShape();
    for (let s = 0; s <= 1; s += 0.05) {
      let x = lerp(ax, bx, s);
      let y = lerp(ay, by, s);
      let bow = sin(s * PI) * off * 160;
      let perpx = -(by - ay), perpy = (bx - ax);
      let len = sqrt(perpx * perpx + perpy * perpy);
      x += perpx / len * bow;
      y += perpy / len * bow;
      vertex(x, y);
    }
    endShape();
  }

  // Bright cores
  noStroke();
  fill(255, 230, 200, 200);
  ellipse(ax, ay, 44, 44);
  ellipse(bx, by, 44, 44);
  fill(255, 255, 240);
  ellipse(ax, ay, 18, 18);
  ellipse(bx, by, 18, 18);

  // Floating particles in the shared field
  randomSeed(1);
  for (let i = 0; i < 160; i++) {
    let s = random();
    let x = lerp(ax, bx, s) + random(-200, 200);
    let y = lerp(ay, by, s) + random(-200, 200);
    let d = dist(x, y, mx, my);
    let a = map(d, 0, 500, 180, 0);
    fill(255, 200, 160, a);
    ellipse(x, y, random(1.5, 4));
  }
}

function drawHeartGlow(cx, cy, r, g, b) {
