  blendMode(ADD);
  noStroke();
  drawGlow(ax, ay, 520, color(220, 90, 60));   // warm red
  drawGlow(bx, by, 520, color(60, 120, 210));   // cool blue

  // The bright meeting space between them
  let mx = (ax + bx) / 2, my = (ay + by) / 2;
  drawGlow(mx, my, 360, color(255, 230, 180));
  drawGlow(mx, my, 200, color(255, 255, 240));
  blendMode(BLEND);

  // Fine connective filaments reaching across the space
  for (let i = 0; i < 260; i++) {
    let t = random();
    let startX = lerp(ax, mx, random(0.3));
    let startY = lerp(ay, my, random(0.3));
    let endX = lerp(bx, mx, random(0.3));
    let endY = lerp(by, my, random(0.3));
    let col = lerpColor(color(255, 150, 120, 40), color(150, 190, 255, 40), t);
    stroke(col);
    strokeWeight(random(0.4, 1.4));
    noFill();
    let cx = mx + random(-120, 120);
    let cy = my + random(-120, 120);
    beginShape();
    vertex(startX, startY);
    quadraticVertex(cx, cy, endX, endY);
    endShape();
