    let sx = mx + cos(ang) * r;
    let sy = my + sin(ang) * r * 1.1;
    fill(255, 245, 210, random(80, 200));
    ellipse(sx, sy, random(2, 6));
  }

  // Gentle vignette
  blendMode(MULTIPLY);
  for (let r = 0; r < 900; r += 6) {
    let a = map(r, 400, 900, 255, 180, true);
    stroke(a);
    noFill();
    ellipse(width / 2, height / 2, width * 1.6 - r, height * 1.6 - r);
  }
