  let ax = width * 0.38, ay = height * 0.42;
  let bx = width * 0.64, by = height * 0.60;

  // The curved field between them: field lines
  noFill();
  for (let i = 0; i < 90; i++) {
    let off = map(i, 0, 89, -1, 1);
    stroke(120 + 60 * noise(i * 0.1), 100, 160, 22);
