    beginShape();
    for (let s = 0; s <= 1; s += 0.02) {
      // interpolate between the two centers with a bowed offset
      let x = lerp(ax, bx, s);
      let y = lerp(ay, by, s);
      let bow = sin(s * PI) * off * 520;
      let nx = -(by - ay), ny = (bx - ax);
      let len = sqrt(nx * nx + ny * ny);
      nx /= len; ny /= len;
      vertex(x + nx * bow, y + ny * bow);
    }
    endShape();
  }

  // Glows
  drawGlow(ax, ay, 520, color(255, 180, 90));   // warm
  drawGlow(bx, by, 520, color(120, 180, 255));  // cool

  // Overlap: the third glow
