function drawTree(x, y, angle, len, depth, c1, c2) {
  if (depth === 0) {
    // Feuillage / fleur
    noStroke();
    let c = lerpColor(c1, c2, random());
    c.setAlpha(200);
    fill(c);
    ellipse(x, y, random(14, 30), random(14, 30));
    return;
  }

  let x2 = x + cos(angle) * len;
  let y2 = y + sin(angle) * len;

  let c = lerpColor(c1, c2, map(depth, 0, 9, 0, 1));
  stroke(c);
  strokeWeight(depth * 1.6);
  line(x, y, x2, y2);

  // branche vers le centre plus marquée
  let spread = 0.45;
  drawTree(x2, y2, angle - spread + random(-0.1, 0.1), len * 0.78, depth - 1, c1, c2);
  drawTree(x2, y2, angle + spread * 0.6 + random(-0.1, 0.1), len * 0.72, depth - 1, c1, c2);
  if (depth > 4) {
    drawTree(x2, y2, angle + random(-0.2, 0.2), len * 0.6, depth - 2, c1, c2);
  }
}

