function drawRoots(x, y, col, dir) {
  stroke(col);
  strokeWeight(14);
  noFill();
  for (let i = 0; i < 6; i++) {
    let angle = dir * (PI / 2 + random(-0.6, 0.6));
    let len = random(120, 260);
    let ex = x + cos(angle) * len;
    let ey = y + abs(sin(angle)) * len * 0.8;
    strokeWeight(random(6, 14));
    line(x, y, ex, ey);
    line(ex, ey, ex + dir * random(20, 60), ey + random(30, 70));
  }
}

function drawTrunk(x, baseY, topY, col, dir) {
  noStroke();
  fill(col);
  beginShape();
  vertex(x - 45, baseY);
  for (let y = baseY; y > topY; y -= 20) {
    let t = (baseY - y) / (baseY - topY);
    let w = lerp(45, 18, t);
    let sway = sin(t * 3) * 40 * dir * t;
    vertex(x + sway - w, y);
  }
  vertex(x + 60 * dir - 18, topY);
  vertex(x + 60 * dir + 18, topY);
  for (let y = topY; y < baseY; y += 20) {
    let t = (baseY - y) / (baseY - topY);
    let w = lerp(45, 18, t);
    let sway = sin(t * 3) * 40 * dir * t;
    vertex(x + sway + w, y);
  }
  vertex(x + 45, baseY);
  endShape(CLOSE);

  // Branches montantes qui convergent vers le centre
  stroke(col);
  noFill();
  for (let i = 0; i < 7; i++) {
    let by = lerp(topY + 100, topY, i / 7);
    let bx = x + 60 * dir;
    strokeWeight(random(4, 10));
    let ex = lerp(bx, 800, random(0.3, 0.9));
    let ey = by - random(100, 250);
    bezier(bx, by, bx + dir * 40, by - 60, ex - dir * 30, ey + 40, ex, ey);
  }
}

function drawFoliage(cx, cy, dark, light) {
  noStroke();
  for (let i = 0; i < 260; i++) {
    let a = random(TWO_PI);
    let r = random(0, 240) * sqrt(random());
    let x = cx + cos(a) * r;
    let y = cy + sin(a) * r * 0.9;
    let c = lerpColor(dark, light, random());
    c.setAlpha(random(90, 180));
    fill(c);
    ellipse(x, y, random(14, 40));
  }
}

