function drawTree(x, base, lean, trunkCol, leafCol) {
  push();
  translate(x, base);
  rotate(lean);
  branch(0, 0, -340, 55, trunkCol, leafCol, 0);
  pop();
}

function branch(x, y, len, thick, tc, lc, depth) {
  if (depth > 8 || thick < 2) {
    // feuillage
    noStroke();
    for (let i = 0; i < 10; i++) {
      fill(red(lc), green(lc), blue(lc), 120);
      circle(x + random(-40, 40), y + random(-40, 40), random(20, 50));
    }
    return;
  }
  let ex = x + len * sin(noise(depth, x) * 2 - 1) * 0.4;
  let ey = y + len;
  stroke(tc);
  strokeWeight(thick);
  line(x, y, ex, ey);
  let n = depth < 2 ? 2 : (random() < 0.7 ? 2 : 1);
  for (let i = 0; i < n; i++) {
    let spread = map(i, 0, max(n - 1, 1), -0.7, 0.7);
    push();
    translate(ex, ey);
    rotate(spread + random(-0.2, 0.2));
    branch(0, 0, len * 0.72, thick * 0.68, tc, lc, depth + 1);
    pop();
  }
}

function drawRoots(x, y, tx, ty, dir) {
  stroke(55, 42, 38, 180);
