  for (let i = 0; i < 6; i++) {
    strokeWeight(random(3, 10));
    let cx = (x + tx) / 2 + random(-100, 100) * dir;
    let cy = y + random(80, 300);
    let ex = tx + random(-120, 120);
    let ey = ty + random(100, 400);
    bezier(x, y, cx, cy, cx + random(-80, 80), cy + 80, ex, ey);
  }
}

