  for (let x = 0; x <= width; x += 20) {
    vertex(x, height * 0.82 + noise(x * 0.01) * 40 - 20);
  }
  vertex(width, height);
  vertex(0, height);
  endShape(CLOSE);

  // Deux arbres qui penchent l'un vers l'autre
  drawTree(width * 0.30, height * 0.82, -PI / 2 - 0.22, 150, 8, true);
  drawTree(width * 0.70, height * 0.82, -PI / 2 + 0.22, 150, 8, false);

  // Coeur de lumière dans le vide central
  push();
  translate(width / 2, height * 0.46);
  noStroke();
  for (let i = 40; i > 0; i--) {
    fill(255, 210, 150, 3);
    heart(0, 0, i * 7);
  }
  fill(255, 240, 200, 120);
  heart(0, 0, 90);
  pop();
}

function drawTree(x, y, angle, len, depth, left) {
  if (depth === 0) {
    // Feuillage
    noStroke();
    let c = left ? color(180, 120, 150, 90) : color(150, 110, 170, 90);
    fill(c);
    let s = random(20, 45);
    ellipse(x, y, s, s);
    return;
  }

  let x2 = x + cos(angle) * len;
  let y2 = y + sin(angle) * len;

  stroke(45, 32, 35);
  strokeWeight(depth * 2.2);
  line(x, y, x2, y2);

  let bias = left ? 0.05 : -0.05;
  let spread = map(depth, 8, 1, 0.3, 0.75);

  drawTree(x2, y2, angle - spread + bias, len * 0.76, depth - 1, left);
  drawTree(x2, y2, angle + spread + bias, len * 0.76, depth - 1, left);
  if (depth > 4 && random() > 0.4) {
    drawTree(x2, y2, angle + bias, len * 0.7, depth - 1, left);
  }
}

function heart(cx, cy, size) {
  beginShape();
  for (let a = 0; a < TWO_PI; a += 0.05) {
    let x = 16 * pow(sin(a), 3);
    let y = -(13 * cos(a) - 5 * cos(2 * a) - 2 * cos(3 * a) - cos(4 * a));
    vertex(cx + x * size / 32, cy + y * size / 32);
  }
  endShape(CLOSE);
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Fond nocturne profond
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(12, 28, t);
    let g = lerp(14, 20, t);
    let b = lerp(32, 40, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Grain d'ambiance
  noStroke();
  for (let i = 0; i < 9000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.002, y * 0.002);
    fill(255, 255, 255, n * 14);
    circle(x, y, random(0.5, 2));
  }

  // Deux centres : les deux "gravités"
  let ax = 600, ay = 780;
  let bx = 1000, by = 1240;

  // Le champ entre les deux : le vrai sujet
  drawField(ax, ay, bx, by);

  // Lignes de force courbées entre les deux présences
  drawTension(ax, ay, bx, by);

  // Présence A : chaude
  drawPresence(ax, ay, 230, color(255, 150, 90), color(255, 210, 120));
  // Présence B : froide
  drawPresence(bx, by, 230, color(110, 170, 255), color(170, 220, 255));

  // Étincelle centrale : l'entre-deux lumineux
  let mx = (ax + bx) / 2;
  let my = (ay + by) / 2;
  drawSpark(mx, my);

  // Vignette douce
  drawVignette();
}

function drawField(ax, ay, bx, by) {
  noStroke();
  for (let i = 0; i < 2600; i++) {
    let t = random();
    // point distribué le long de l'axe, avec dispersion
    let x = lerp(ax, bx, t) + random(-260, 260);
    let y = lerp(ay, by, t) + random(-260, 260);
    let da = dist(x, y, ax, ay);
    let db = dist(x, y, bx, by);
    let proximity = 1 / (1 + abs(da - db) * 0.01);
    let warmth = db / (da + db);
    let r = lerp(120, 255, warmth);
    let g = lerp(160, 190, warmth);
    let b = lerp(255, 150, warmth);
    fill(r, g, b, proximity * 90);
    circle(x, y, random(2, 9));
  }
}

function drawTension(ax, ay, bx, by) {
  let mx = (ax + bx) / 2;
  let my = (ay + by) / 2;
  for (let i = 0; i < 46; i++) {
    let off = map(i, 0, 45, -1, 1);
    let cx = mx + off * 420 - 60;
    let cy = my - off * 300;
    let warm = (i % 2 === 0);
    let c = warm ? color(255, 180, 120, 60) : color(150, 200, 255, 60);
    stroke(c);
    strokeWeight(map(abs(off), 0, 1, 2.4, 0.5));
    noFill();
    beginShape();
    for (let t = 0; t <= 1; t += 0.05) {
      let x = bezierPoint(ax, cx, cx, bx, t);
      let y = bezierPoint(ay, cy, cy, by, t);
      vertex(x, y);
    }
    endShape();
  }
}

function drawPresence(cx, cy, rad, coreCol, haloCol) {
  noStroke();
  // halo rayonnant
  for (let r = rad * 2.4; r > 0; r -= 6) {
    let a = map(r, 0, rad * 2.4, 70, 0);
    fill(red(haloCol), green(haloCol), blue(haloCol), a);
    circle(cx, cy, r);
  }
  // noyau
  for (let r = rad; r > 0; r -= 4) {
    let t = r / rad;
    let c = lerpColor(color(255), coreCol, t);
    fill(red(c), green(c), blue(c), 255 - t * 40);
    circle(cx, cy, r);
  }
  // coeur blanc
  fill(255, 255, 255, 230);
  circle(cx, cy, rad * 0.22);
}

function drawSpark(mx, my) {
  noStroke();
  for (let r = 300; r > 0; r -= 5) {
    let a = map(r, 0, 300, 90, 0);
    fill(255, 245, 230, a * 0.6);
    circle(mx, my, r);
  }
  // rayons fins
  push();
  translate(mx, my);
  stroke(255, 250, 240, 160);
  for (let i = 0; i < 16; i++) {
    let ang = (TWO_PI / 16) * i + 0.2;
    let len = 60 + noise(i) * 140;
    strokeWeight(map(i % 2, 0, 1, 2, 0.8));
    line(0, 0, cos(ang) * len, sin(ang) * len);
  }
  pop();
  fill(255);
  noStroke();
  circle(mx, my, 34);
}

function drawVignette() {
  noFill();
  for (let r = 0; r < 700; r += 2) {
    let a = map(r, 0, 700, 90, 0);
    stroke(8, 8, 18, a);
    strokeWeight(2);
    ellipse(width / 2, height / 2, width * 1.6 - r, height * 1.6 - r);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Fond : espace profond en dégradé
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(14, 30, t);
    let g = lerp(10, 18, t);
    let b = lerp(28, 40, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Poussière d'étoiles
  noStroke();
  for (let i = 0; i < 1400; i++) {
    let x = random(width);
    let y = random(height);
    let s = random(0.5, 2.5);
    let a = random(20, 120);
    fill(255, 255, 240, a);
    ellipse(x, y, s, s);
  }

  // Deux centres : positions
  let cA = createVector(560, 820);
  let cB = createVector(1060, 1200);

  // La courbure de l'espace entre eux : lignes de champ
  push();
  for (let k = -14; k <= 14; k++) {
    let col = lerpColor(color(255, 170, 90, 28), color(120, 180, 255, 28), (k + 14) / 28);
    stroke(col);
    strokeWeight(1.2);
    noFill();
    beginShape();
    for (let s = 0; s <= 1; s += 0.01) {
      // interpolation courbée par une attraction centrale
      let base = p5.Vector.lerp(cA, cB, s);
      let perp = createVector(-(cB.y - cA.y), cB.x - cA.x).normalize();
      // la déformation est max au milieu, module le fil
      let bend = sin(s * PI) * k * 16;
      let x = base.x + perp.x * bend;
      let y = base.y + perp.y * bend;
      curveVertex(x, y);
    }
    endShape();
  }
  pop();

  // Le fil tendre qui les relie
  stroke(255, 230, 200, 150);
  strokeWeight(3);
  noFill();
  beginShape();
  for (let s = 0; s <= 1; s += 0.01) {
    let base = p5.Vector.lerp(cA, cB, s);
    let perp = createVector(-(cB.y - cA.y), cB.x - cA.x).normalize();
    let bend = sin(s * PI) * 40;
    curveVertex(base.x + perp.x * bend, base.y + perp.y * bend);
  }
  endShape();

  // Territoire partagé : halo au point milieu
  let mid = p5.Vector.lerp(cA, cB, 0.5);
  noStroke();
  for (let r = 260; r > 0; r -= 4) {
    let a = map(r, 0, 260, 50, 0);
    fill(255, 220, 210, a * 0.5);
    ellipse(mid.x, mid.y, r, r);
  }

  // Centre A : lumière chaude (orange/or)
  drawBody(cA, color(255, 180, 90), color(255, 120, 40), 190);

  // Centre B : lumière froide (bleu/cyan)
  drawBody(cB, color(130, 190, 255), color(70, 130, 240), 210);

  // Petites orbites d'étincelles autour de chaque centre
  drawSparks(cA, color(255, 200, 140), 230, 9);
  drawSparks(cB, color(170, 210, 255), 250, 11);
}

function drawBody(c, inner, outer, size) {
  noStroke();
  // halo externe
  for (let r = size * 1.8; r > size; r -= 3) {
    let a = map(r, size, size * 1.8, 60, 0);
    fill(red(outer), green(outer), blue(outer), a);
    ellipse(c.x, c.y, r, r);
  }
  // corps en dégradé radial
  for (let r = size; r > 0; r -= 2) {
    let t = r / size;
    let col = lerpColor(inner, outer, t);
    fill(col);
    ellipse(c.x, c.y, r, r);
  }
  // reflet
  fill(255, 255, 255, 180);
  ellipse(c.x - size * 0.18, c.y - size * 0.18, size * 0.22, size * 0.22);
}

function drawSparks(c, col, radius, n) {
  noStroke();
  for (let i = 0; i < n; i++) {
    let ang = random(TWO_PI);
    let rad = radius + random(-30, 60);
    let x = c.x + cos(ang) * rad;
    let y = c.y + sin(ang) * rad;
    let s = random(3, 8);
    fill(red(col), green(col), blue(col), random(100, 220));
    ellipse(x, y, s, s);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Fond : nuit profonde avec dégradé
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(14, 32, t);
    let g = lerp(12, 20, t);
    let b = lerp(28, 40, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Poussière d'étoiles
  noStroke();
  for (let i = 0; i < 1400; i++) {
    let x = random(width);
    let y = random(height);
    let s = random(0.5, 2.5);
    let a = random(20, 120);
    fill(255, 250, 240, a);
    ellipse(x, y, s, s);
  }

  // Deux foyers
  let c1 = createVector(width * 0.38, height * 0.44);
  let c2 = createVector(width * 0.64, height * 0.58);

  // Champ gravitationnel partagé : lignes d'orbite
  blendMode(ADD);
  for (let k = 0; k < 110; k++) {
    let phase = map(k, 0, 110, 0, TWO_PI);
    let steps = 240;
    let warm = lerp(255, 180, k / 110);
    let cool = lerp(140, 220, k / 110);
    stroke(warm, 120, cool, 14);
    strokeWeight(1);
    noFill();
    beginShape();
    for (let i = 0; i <= steps; i++) {
      let a = map(i, 0, steps, 0, TWO_PI) + phase * 0.0;
      // courbe de Cassini-like : orbite autour des deux foyers
      let rr = 420 + 90 * sin(a * 2 + phase);
      let bias = sin(a + phase);
      // interpolation du centre selon l'angle
      let cx = lerp(c1.x, c2.x, 0.5 + 0.5 * cos(a));
      let cy = lerp(c1.y, c2.y, 0.5 + 0.5 * cos(a));
      let x = cx + cos(a + phase * 0.3) * rr * (0.6 + 0.2 * bias);
      let y = cy + sin(a + phase * 0.3) * rr * (0.6 + 0.2 * bias);
      curveVertex(x, y);
    }
    endShape(CLOSE);
  }

  // Halo lumineux de chaque foyer
  drawGlow(c1.x, c1.y, 300, color(255, 150, 90));
  drawGlow(c2.x, c2.y, 300, color(100, 170, 255));

  // Coeur des foyers
  for (let r = 60; r > 0; r -= 2) {
    let a = map(r, 0, 60, 255, 0);
    fill(255, 220, 190, a * 0.8);
    ellipse(c1.x, c1.y, r, r);
    fill(200, 225, 255, a * 0.8);
    ellipse(c2.x, c2.y, r, r);
  }
  fill(255, 245, 235);
  ellipse(c1.x, c1.y, 22, 22);
  fill(240, 248, 255);
  ellipse(c2.x, c2.y, 22, 22);

  // Le champ entre les deux : don de lumière
  for (let i = 0; i < 500; i++) {
    let t = random();
    let x = lerp(c1.x, c2.x, t) + random(-40, 40);
    let y = lerp(c1.y, c2.y, t) + random(-40, 40);
    let col = lerpColor(color(255, 160, 110), color(120, 180, 255), t);
    fill(red(col), green(col), blue(col), 30);
    ellipse(x, y, random(2, 6));
  }

  blendMode(BLEND);

  // Vignettage doux
  noFill();
  for (let r = 0; r < 400; r++) {
    stroke(10, 8, 20, r * 0.18);
    ellipse(width / 2, height / 2, width * 2 - r * 4, height * 2 - r * 4);
  }
}

function drawGlow(x, y, size, col) {
  noStroke();
  for (let r = size; r > 0; r -= 3) {
    let a = map(r, 0, size, 40, 0);
    fill(red(col), green(col), blue(col), a);
    ellipse(x, y, r, r);
  }
}

function setup() {
