  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(12, 30, t);
    let g = lerp(14, 20, t);
    let b = lerp(32, 40, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Poussière d'étoiles lointaines
  noStroke();
  for (let i = 0; i < 1400; i++) {
    let x = random(width);
    let y = random(height);
    let a = random(10, 90);
    let s = random(0.5, 2.2);
    fill(230, 235, 255, a);
    ellipse(x, y, s, s);
  }

  // Deux centres : les deux présences
  let cxA = width * 0.36, cyA = height * 0.42;
  let cxB = width * 0.64, cyB = height * 0.58;

  // Le champ lumineux entre les deux (l'intervalle vibrant)
  let mx = (cxA + cxB) / 2;
  let my = (cyA + cyB) / 2;
  push();
  for (let i = 0; i < 90; i++) {
    let rad = 520 - i * 5;
    let alpha = map(i, 0, 90, 2, 30);
    fill(255, 210, 140, alpha * 0.25);
    ellipse(mx, my, rad * 1.1, rad * 0.9);
  }
  pop();

  // Courbure de l'espace : lignes de champ courbées autour des centres
  drawField(cxA, cyA, cxB, cyB);

  // Les fils invisibles qui se cherchent
  stroke(255, 225, 180, 60);
  strokeWeight(1);
  noFill();
  for (let i = 0; i < 40; i++) {
    let o1 = random(-40, 40);
    let o2 = random(-40, 40);
    let bend = random(-120, 120);
    beginShape();
    vertex(cxA + o1, cyA + o1 * 0.5);
    quadraticVertex(mx + bend, my + bend * 0.3, cxB + o2, cyB + o2 * 0.5);
    endShape();
  }

  // Présence A — bleu froid
  drawPresence(cxA, cyA, 180, 150, 190, 255);
  // Présence B — rose chaleur
  drawPresence(cxB, cyB, 180, 255, 170, 190);

  // Halo central le plus intense : ce qui naît entre elles
  noStroke();
  for (let i = 0; i < 60; i++) {
    let rad = 160 - i * 2.4;
    fill(255, 240, 210, 10);
    ellipse(mx, my, rad, rad);
  }
  fill(255, 250, 235, 180);
  ellipse(mx, my, 24, 24);
}

function drawPresence(cx, cy, size, cr, cg, cb) {
  noStroke();
  for (let i = 0; i < 120; i++) {
    let rad = size - i * 1.3;
    let a = map(i, 0, 120, 2, 50);
    fill(cr, cg, cb, a * 0.4);
    ellipse(cx, cy, rad, rad);
  }
  fill(255, 255, 255, 200);
  ellipse(cx, cy, 30, 30);
  fill(cr, cg, cb, 120);
  ellipse(cx, cy, 55, 55);
}

function drawField(ax, ay, bx, by) {
  noFill();
  for (let i = 0; i < 120; i++) {
    let gx = random(width);
    let gy = random(height);
    stroke(180, 190, 230, 22);
    strokeWeight(0.8);
    beginShape();
    let px = gx, py = gy;
    for (let step = 0; step < 50; step++) {
      // vecteur courbé par les deux masses
      let dax = ax - px, day = ay - py;
      let dbx = bx - px, dby = by - py;
      let da = max(dist(px, py, ax, ay), 20);
      let db = max(dist(px, py, bx, by), 20);
      let fx = dax / (da * da) * 2000 + dbx / (db * db) * 2000;
      let fy = day / (da * da) * 2000 + dby / (db * db) * 2000;
      // composante perpendiculaire pour l'orbite
      let perpx = -fy, perpy = fx;
      px += perpx * 0.4 + random(-2, 2);
      py += perpy * 0.4 + random(-2, 2);
      if (px < 0 || px > width || py < 0 || py > height) break;
      vertex(px, py);
    }
    endShape();
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Fond nocturne profond, dégradé vertical
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(18, 40, t);
    let g = lerp(20, 28, t);
    let b = lerp(42, 50, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Poussière d'étoiles légère
  noStroke();
  for (let i = 0; i < 900; i++) {
    let x = random(width);
    let y = random(height);
    let a = random(10, 70);
    fill(230, 230, 255, a);
    circle(x, y, random(1, 2.5));
  }

  // Les deux présences : deux centres
  let ax = width * 0.33, ay = height * 0.48;
  let bx = width * 0.67, by = height * 0.52;

  // Halo chaleureux entre les deux (l'espace vibrant)
  let mx = (ax + bx) / 2;
  let my = (ay + by) / 2;
  for (let r = 520; r > 0; r -= 4) {
    let t = r / 520;
    let a = (1 - t) * 26;
    fill(255, 180, 120, a);
    circle(mx, my, r);
  }

  // Présence A — teinte froide-rose
  drawPresence(ax, ay, 300, color(255, 120, 150), color(120, 90, 220));
  // Présence B — teinte chaude-ambre
  drawPresence(bx, by, 320, color(255, 190, 90), color(220, 110, 140));

  // Le fil invisible : fines lignes qui se penchent l'une vers l'autre
  blendMode(ADD);
  for (let i = 0; i < 60; i++) {
    let t = i / 59;
    let sway = sin(t * PI) * 90;
    let y1 = lerp(ay, my, t) - sway * 0.3;
    let y2 = lerp(by, my, t) - sway * 0.3;
    // depuis A vers le centre
    stroke(255, 200, 160, 10 + 20 * sin(t * PI));
    strokeWeight(1);
    let cx = lerp(ax, mx, t);
    let cy = lerp(ay, my, t) + sin(t * PI) * -60;
    point(cx, cy);
    let dx = lerp(bx, mx, t);
    let dy = lerp(by, my, t) + sin(t * PI) * -60;
    point(dx, dy);
  }

  // Deux courbes qui s'inclinent pour se rencontrer sans se toucher
  noFill();
  for (let k = 0; k < 40; k++) {
    let off = k * 1.2;
    let alpha = map(k, 0, 40, 55, 4);
    stroke(255, 170, 130, alpha);
    strokeWeight(1.2);
    beginShape();
    for (let t = 0; t <= 1; t += 0.02) {
      let x = lerp(ax + 150, mx - 10, t);
      let y = lerp(ay, my, t) - sin(t * HALF_PI) * (120 - off);
      curveVertex(x, y);
    }
    endShape();
    beginShape();
    for (let t = 0; t <= 1; t += 0.02) {
      let x = lerp(bx - 150, mx + 10, t);
      let y = lerp(by, my, t) - sin(t * HALF_PI) * (120 - off);
      curveVertex(x, y);
    }
    endShape();
  }
  blendMode(BLEND);

  // Point tiède central : le lieu de la rencontre
  for (let r = 70; r > 0; r -= 2) {
    let t = r / 70;
    fill(255, 240, 210, (1 - t) * 180);
    noStroke();
    circle(mx, my, r);
  }
  fill(255, 250, 235, 230);
  circle(mx, my, 14);

  // Vignette douce
  noFill();
  for (let r = 0; r < 500; r++) {
    stroke(10, 12, 28, map(r, 0, 500, 0, 0.5));
    let d = max(width, height) + 400 - r * 2;
    strokeWeight(2);
    ellipse(width / 2, height / 2, d, d * 1.25);
  }
}

function drawPresence(cx, cy, size, inner, outer) {
  noStroke();
  for (let r = size; r > 0; r -= 3) {
    let t = r / size;
    let c = lerpColor(inner, outer, t);
    c.setAlpha((1 - t) * 90);
    fill(c);
    circle(cx, cy, r);
  }
  // Noyau lumineux
  for (let r = 60; r > 0; r -= 2) {
