function branchRoot(x, y, ang, len, w, groundY) {
  if (len < 14 || w < 1) return;
  let nx = x + cos(ang) * len;
  let ny = y + sin(ang) * len;
  ny = max(ny, y + 10); // push downward
  strokeWeight(w);
  line(x, y, nx, ny);
  branchRoot(nx, ny, ang + random(-0.5, 0.2), len*0.75, w*0.7, groundY);
  if (random() < 0.8)
