  translate(nx, ny);
  let n = random() < 0.5 ? 2 : 3;
  for (let i = 0; i < n; i++) {
    branch(ang + random(-0.6, 0.6), len * random(0.6, 0.78), w * 0.7);
  }
  pop();
}

