function drawTree(baseX, baseY, dir) {
  stroke(74, 52, 42);
  strokeWeight(34);
  branch(baseX, baseY, -90 + dir * 8, 230, 0, dir);
}

function branch(x, y, angle, len, depth, dir) {
  if (depth > 7 || len < 14) {
    // leaves
    noStroke();
    for (let i = 0; i < 6; i++) {
      let lx = x + randomGaussian(0, 22);
      let ly = y + randomGaussian(0, 22);
      fill(120 + random(60), 150 + random(50), 90 + random(40), 200);
      ellipse(lx, ly, random(18, 34));
    }
    return;
  }
  let rad = radians(angle);
  let x2 = x + cos(rad) * len;
  let y2 = y + sin(rad) * len;
  strokeWeight(map(depth, 0, 7, 32, 3));
  stroke(74 - depth * 2, 52 - depth, 42);
  line(x, y, x2, y2);

  let n = random() < 0.5 ? 2 : 3;
  for (let i = 0; i < n; i++) {
    let spread = random(18, 40) * (i % 2 === 0 ? 1 : -1);
    branch(x2, y2, angle + spread + dir * 4, len * random(0.68, 0.8), depth + 1, dir);
  }
}

function drawRoots(baseX, baseY, dir) {
  // roots pull toward center (width/2)
  root(baseX, baseY, 90 - dir * 6, 190, 0, dir);
}

function root(x, y, angle, len, depth, dir) {
  if (depth > 7 || len < 12) return;
  // bias angle toward the center as it goes deeper
  let centerPull = map(x, 0, width, -14, 14);
  angle += centerPull * (depth / 7);

  let rad = radians(angle);
  let x2 = x + cos(rad) * len;
  let y2 = y + sin(rad) * len;

  strokeWeight(map(depth, 0, 7, 24, 2));
  stroke(60 - depth, 42 - depth, 36, 230);
  // slight curve
  let mx = (x + x2) / 2 + randomGaussian(0, 10);
  let my = (y + y2) / 2;
  noFill();
  beginShape();
  curveVertex(x, y);
  curveVertex(x, y);
  curveVertex(mx, my);
  curveVertex(x2, y2);
  curveVertex(x2, y2);
  endShape();

  let n = random() < 0.4 ? 1 : 2;
  for (let i = 0; i < n; i++) {
    let spread = random(20, 50) * (i % 2 === 0 ? 1 : -1);
    root(x2, y2, angle + spread, len * random(0.7, 0.85), depth + 1, dir);
  }
}

