function drawRoots(x, y, dir, len) {
  stroke(60, 42, 30, 180);
  strokeWeight(10);
  noFill();
  let branches = 5;
  for (let i = 0; i < branches; i++) {
    let angle = PI/2 + dir * (0.15 + i * 0.28);
    let ex = x + cos(angle) * len * (0.7 + random(0.6)) * dir;
    // roots reach toward center to intertwine
    let reach = map(i, 0, branches, 0.3, 1.0);
    let tx = lerp(x, 800, reach * 0.9) + random(-40, 40);
    let ty = y + len * (0.5 + i * 0.09);
    strokeWeight(map(i, 0, branches, 9, 2));
    beginShape();
    vertex(x, y);
    let cx1 = x + (tx - x) * 0.3 + random(-30, 30);
    let cy1 = y + (ty - y) * 0.4;
    let cx2 = x + (tx - x) * 0.7;
    let cy2 = y + (ty - y) * 0.8 + random(-20, 20);
    bezierVertex(cx1, cy1, cx2, cy2, tx, ty);
    endShape();
  }
}

function drawTree(x, y, lean, len, depth) {
  stroke(70, 48, 35);
  strokeWeight(depth * 2.6);
  branch(x, y, -PI/2 + lean, len, depth);
}

function branch(x, y, angle, len, depth) {
  if (depth <= 0) return;
  let x2 = x + cos(angle) * len;
  let y2 = y + sin(angle) * len;

  strokeWeight(max(1, depth * 2.6));
  stroke(70, 48, 35);
  line(x, y, x2, y2);

  if (depth <= 3) {
    // leaves / blossoms
    noStroke();
    let n = floor(random(3, 7));
    for (let i = 0; i < n; i++) {
      let lx = x2 + random(-45, 45);
      let ly = y2 + random(-45, 45);
      let c = random();
      if (c < 0.5) fill(230, 120, 140, 200);
      else if (c < 0.8) fill(250, 180, 190, 200);
      else fill(255, 230, 180, 200);
      ellipse(lx, ly, random(18, 36));
    }
  }

  let nb = (depth > 6) ? 2 : floor(random(2, 4));
  for (let i = 0; i < nb; i++) {
    let na = angle + random(-0.5, 0.5);
    let nl = len * random(0.65, 0.78);
    branch(x2, y2, na, nl, depth - 1);
  }
}

