    let r = random(40, 1100);
    let src = random() < 0.5 ? a : b;
    let p = createVector(src.x + cos(ang) * r, src.y + sin(ang) * r);

    let hue = random() < 0.5 ? color(255, 120, 150) : color(120, 180, 255);
    stroke(red(hue), green(hue), blue(hue), 42);

    beginShape();
    noFill();
    for (let step = 0; step < 90; step++) {
      vertex(p.x, p.y);
      let da = p5.Vector.sub(a, p);
      let db = p5.Vector.sub(b, p);
      let fa = da.copy().setMag(900 / (da.magSq() * 0.004 + 40));
      let fb = db.copy().setMag(900 / (db.magSq() * 0.004 + 40));
      let swirl = createVector(-(da.y + db.y), da.x + db.x).setMag(2.4);
      let move = fa.add(fb).add(swirl);
      p.add(move.limit(6));
      if (p.x < -200 || p.x > width + 200 || p.y < -200 || p.y > height + 200) break;
    }
    endShape();
  }

  // glowing cores
  drawCore(a.x, a.y, color(255, 150, 170));
  drawCore(b.x, b.y, color(150, 190, 255));

  // soft connecting tension
  noFill();
  for (let g = 0; g < 40; g++) {
    stroke(230, 210, 230, 8);
    strokeWeight(1);
    let off = (g - 20) * 2.2;
    bezier(a.x, a.y,
           (a.x + b.x) / 2 + off, a.y - 80 + off,
           (a.x + b.x) / 2 - off, b.y + 80 - off,
           b.x, b.y);
  }
}

function drawCore(x, y, col) {
  noStroke();
  for (let r = 260; r > 0; r -= 4) {
    let alpha = map(r, 0, 260, 180, 0);
    fill(red(col), green(col), blue(col), alpha * 0.5);
    ellipse(x, y, r, r);
  }
  fill(255, 245, 240, 230);
  ellipse(x, y, 40, 40);
}

