    stroke(c);
    line(0, y, width, y);
  }

  let ax = 640, ay = 1000;   // core A
  let bx = 960, by = 1000;   // core B

  // field lines between the two attractors
  blendMode(ADD);
  let N = 420;
  for (let i = 0; i < N; i++) {
    let startA = random() < 0.5;
    let sx, sy, ex, ey;
    let ang = random(TWO_PI);
    let r = random(60, 260);
    if (startA) {
      sx = ax + cos(ang) * r; sy = ay + sin(ang) * r * 1.3;
      ex = bx + cos(ang + PI) * r * 0.6; ey = by + sin(ang + PI) * r;
    } else {
      sx = bx + cos(ang) * r; sy = by + sin(ang) * r * 1.3;
      ex = ax + cos(ang + PI) * r * 0.6; ey = ay + sin(ang + PI) * r;
    }

    let hue = lerp(10, 50, random());
    let col = color(255, 120 + hue * 2, 150, 14);
    stroke(col);
    strokeWeight(random(0.6, 1.8));
    noFill();

    // curved line bowing toward center
    let mx = (sx + ex) / 2 + random(-40, 40);
    let my = (sy + ey) / 2 + random(-60, 60);
    beginShape();
    for (let t = 0; t <= 1; t += 0.05) {
      let x = bezierPoint(sx, sx, mx, ex, t);
      let y = bezierPoint(sy, my, my, ey, t);
      vertex(x, y);
    }
    endShape();
  }

  // the central glow — what they create together
  let cx = (ax + bx) / 2, cy = (ay + by) / 2;
  for (let r = 300; r > 0; r -= 4) {
    let a = map(r, 0, 300, 90, 0);
    fill(255, 220, 180, a * 0.5);
    noStroke();
    ellipse(cx, cy, r * 1.6, r);
  }

  // the two cores, kept whole and separate
  drawCore(ax, ay, color(120, 200, 255));
  drawCore(bx, by, color(255, 150, 120));

  blendMode(BLEND);

  // quiet scattered stars
  for (let i = 0; i < 160; i++) {
    let x = random(width), y = random(height);
    let d = dist(x, y, cx, cy);
    if (d > 350) {
      fill(255, random(40, 140));
      noStroke();
      circle(x, y, random(1, 3));
    }
  }
}

function drawCore(x, y, col) {
