function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // background gradient
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let c = lerpColor(color(14, 12, 30), color(32, 16, 40), t);
    stroke(c);
    line(0, y, width, y);
  }

  // two centers
  let ax = width * 0.40, ay = height * 0.44;
  let bx = width * 0.60, by = height * 0.56;

  let colA = color(255, 90, 120);   // warm rose
  let colB = color(80, 160, 255);   // cool blue

  // soft background glow of the field (blend color between)
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 20000; i++) {
    let ang = random(TWO_PI);
    // choose which center with field influence
    let pick = random() < 0.5;
    let cx = pick ? ax : bx;
    let cy = pick ? ay : by;
    let col = pick ? colA : colB;

    // spiraling orbit radius
    let base = random() * random() * 520;
    let swirl = ang + base * 0.012 * (pick ? 1 : -1);
    let r = base;
    let x = cx + cos(swirl) * r;
    let y = cy + sin(swirl) * r * 0.9;

    // distance to the other center -> blend to create third color
    let ocx = pick ? bx : ax;
    let ocy = pick ? by : ay;
    let d = dist(x, y, ocx, ocy);
    let blend = constrain(map(d, 0, 700, 1, 0), 0, 1) * 0.6;
    let mixed = lerpColor(col, color(255, 230, 180), blend);

    let alpha = map(base, 0, 520, 60, 2);
    fill(red(mixed), green(mixed), blue(mixed), alpha);
    let sz = map(base, 0, 520, 1.5, 6);
    ellipse(x, y, sz, sz);
  }

  // bright cores
  for (let g = 0; g < 2; g++) {
    let cx = g === 0 ? ax : bx;
    let cy = g === 0 ? ay : by;
    let col = g === 0 ? colA : colB;
    for (let r = 120; r > 0; r -= 2) {
      let a = map(r, 0, 120, 120, 0);
      fill(red(col), green(col), blue(col), a);
      ellipse(cx, cy, r * 2, r * 2);
    }
    fill(255, 255, 255, 220);
    ellipse(cx, cy, 30, 30);
  }

  // interweaving orbital threads connecting the two
  blendMode(BLEND);
  noFill();
  for (let k = 0; k < 90; k++) {
    let phase = map(k, 0, 90, 0, TWO_PI);
    let t = k / 90;
    let col = lerpColor(colA, colB, t);
    stroke(red(col), green(col), blue(col), 40);
    strokeWeight(1);
    beginShape();
    for (let s = 0; s <= 1.0; s += 0.02) {
      let ang = s * TWO_PI + phase;
      let midx = lerp(ax, bx, s);
      let midy = lerp(ay, by, s);
      let rad = 180 * sin(s * PI);
      let x = midx + cos(ang) * rad;
      let y = midy + sin(ang) * rad * 0.8;
      vertex(x, y);
    }
    endShape();
  }

  // gentle vignette
  blendMode(BLEND);
  noFill();
  for (let r = 0; r < 500; r++) {
    stroke(10, 8, 20, map(r, 0, 500, 0, 60));
    ellipse(width / 2, height / 2, width + r * 2, height + r * 2);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

const HOR = 1430;

function skyCol(t) {
  const stops = [
    [0.00, 8, 10, 22],
    [0.32, 24, 27, 52],
    [0.60, 62, 52, 84],
    [0.80, 130, 96, 104],
    [0.92, 204, 150, 120],
    [1.00, 242, 208, 162]
  ];
  t = constrain(t, 0, 1);
  for (let i = 0; i < stops.length - 1; i++) {
    if (t >= stops[i][0] && t <= stops[i + 1][0]) {
      let u = map(t, stops[i][0], stops[i + 1][0], 0, 1);
      let e = u * u * (3 - 2 * u);
      return color(
        lerp(stops[i][1], stops[i + 1][1], e),
        lerp(stops[i][2], stops[i + 1][2], e),
        lerp(stops[i][3], stops[i + 1][3], e)
      );
    }
  }
  return color(0);
}

function ridgeY(x) {
  return HOR + (noise(x * 0.0011, 50) - 0.5) * 46 + (noise(x * 0.004, 90) - 0.5) * 10;
}

function leafShape(x, y, s, a, c) {
  push();
  translate(x, y);
  rotate(a);
  noStroke();
  fill(c);
  beginShape();
  vertex(0, -s);
  bezierVertex(s * 0.85, -s * 0.35, s * 0.85, s * 0.35, 0, s);
  bezierVertex(-s * 0.85, s * 0.35, -s * 0.85, -s * 0.35, 0, -s);
  endShape();
  pop();
}

function branch(len, w, d) {
  const segs = 3;
  for (let i = 0; i < segs; i++) {
    const sl = len / segs;
    rotate(random(-0.055, 0.055));
    strokeWeight(max(0.7, w * (1 - 0.3 * i / segs)));
    line(0, 0, 0, -sl);
    translate(0, -sl);
  }
  if (d <= 0 || w < 1.1) return;
  const n = d > 7 ? 2 : (random() < 0.28 ? 3 : 2);
  for (let k = 0; k < n; k++) {
    let a;
    if (k === 0) a = random(0.20, 0.55);
    else if (k === 1) a = -random(0.20, 0.55);
    else a = random(-0.16, 0.16);
    push();
    rotate(a);
    branch(len * random(0.63, 0.77), w * random(0.54, 0.68), d - 1);
    pop();
  }
}

function draw() {
  noStroke();

  // ---------- SKY ----------
  for (let y = 0; y < HOR + 60; y++) {
    let t = y / (HOR + 60);
    let c = skyCol(t);
    let n = (noise(y * 0.01, 3) - 0.5) * 10;
    stroke(red(c) + n, green(c) + n * 0.8, blue(c) + n * 0.6);
    line(0, y, width, y);
  }

  // soft cloud banding
  for (let i = 0; i < 2600; i++) {
    let x = random(-200, width + 200);
    let y = random(120, HOR - 10);
    let dens = noise(x * 0.0013, y * 0.0055, 11);
    if (dens < 0.52) continue;
    let t = y / (HOR + 60);
    let base = skyCol(t);
    let up = random() < 0.55;
    let c = color(
      red(base) + (up ? 42 : -26),
      green(base) + (up ? 32 : -22),
      blue(base) + (up ? 30 : -16),
      map(dens, 0.52, 0.95, 2, 16)
    );
    noStroke();
    fill(c);
    ellipse(x, y, random(180, 640), random(5, 22));
  }

  // ---------- LOW SUN / MOON ----------
  let sx = 1095, sy = 1238;
  noStroke();
  for (let r = 620; r > 0; r -= 4) {
    let a = pow(1 - r / 620, 2.6) * 26;
    fill(255, 226, 180, a);
    ellipse(sx, sy, r * 2, r * 1.75);
  }
  for (let r = 132; r > 0; r -= 2) {
    let a = map(r, 132, 0, 10, 110);
    fill(255, 243, 219, a);
    ellipse(sx, sy, r * 2, r * 2);
  }

  // haze bands near horizon
  for (let i = 0; i < 900; i++) {
    let y = HOR - pow(random(), 1.7) * 230;
    noStroke();
    fill(238, 206, 176, random(3, 11));
    ellipse(random(-100, width + 100), y, random(300, 900), random(3, 11));
  }

  // ---------- DISTANT TREES ----------
  for (let i = 0; i < 9; i++) {
    let x = 1180 + i * 52 + random(-14, 14);
    let h = random(16, 40);
    let gy = ridgeY(x);
    fill(14, 13, 18, 190);
    noStroke();
    ellipse(x, gy - h * 0.55, h * 0.55, h);
    rect(x - 1, gy - h * 0.6, 2.2, h * 0.6);
  }

  // ---------- GROUND ----------
  drawingContext.save();
  drawingContext.beginPath();
  drawingContext.moveTo(0, height);
  for (let x = 0; x <= width; x += 4) drawingContext.lineTo(x, ridgeY(x));
  drawingContext.lineTo(width, height);
  drawingContext.closePath();
  drawingContext.clip();

  for (let y = HOR - 60; y < height; y++) {
    let t = constrain(map(y, HOR - 40, height, 0, 1), 0, 1);
    let r = lerp(52, 9, pow(t, 0.55));
    let g = lerp(44, 9, pow(t, 0.55));
    let b = lerp(42, 12, pow(t, 0.55));
    stroke(r, g, b);
    line(0, y, width, y);
  }
  // ground texture
  for (let i = 0; i < 7000; i++) {
    let y = HOR - 40 + pow(random(), 0.6) * (height - HOR + 60);
    let x = random(-50, width + 50);
    let t = constrain(map(y, HOR, height, 0, 1), 0, 1);
    let up = random() < 0.5;
    stroke(
      lerp(56, 12, t) + (up ? 20 : -8),
      lerp(48, 12, t) + (up ? 16 : -8),
      lerp(46, 15, t) + (up ? 12 : -6),
      random(8, 34)
    );
    strokeWeight(random(1, 4));
    let len = random(20, 150) * (0.4 + t);
    line(x, y, x + len, y + random(-2, 2));
  }
  drawingContext.restore();

  // grass fringe
  for (let x = -10; x < width + 10; x += 2.2) {
    let gy = ridgeY(x);
    if (random() < 0.55) {
      stroke(9, 9, 12, random(140, 255));
      strokeWeight(random(0.8, 2.0));
      let h = random(5, 26) * (random() < 0.12 ? 1.8 : 1);
      noFill();
      let bend = random(-9, 9);
      beginShape();
      vertex(x, gy + 4);
      quadraticVertex(x + bend * 0.4, gy - h * 0.6, x + bend, gy - h);
      endShape();
    }
  }

  // ---------- TREE ----------
  push();
  stroke(10, 10, 15);
  strokeCap(ROUND);
  noFill();
  translate(612, 1452);
  branch(332, 54, 10);
  pop();
  // base flare
  noStroke();
  fill(10, 10, 15);
  ellipse(612, 1452, 118, 26);
  ellipse(612, 1440, 72, 30);

  // ---------- THE LEAVING ----------
  const p0x = 648, p0y = 770, p1x = 900, p1y = 470, p2x = 1250, p2y = 560, p3x = 1520, p3y = 215;
  const N = 220;
  for (let i = 0; i < N; i++) {
    let t = pow(i / N, 0.92);
    let bx = bezierPoint(p0x, p1x, p2x, p3x, t);
    let by = bezierPoint(p0y, p1y, p2y, p3y, t);
    let spread = 18 + 210 * pow(t, 1.3);
    let x = bx + random(-spread, spread) + (noise(i * 0.09, 7) - 0.5) * spread;
    let y = by + random(-spread * 0.7, spread * 0.7);
    let s = lerp(11, 2.2, pow(t, 0.65)) * random(0.7, 1.25);
    let a = lerp(240, 18, pow(t, 0.85)) * random(0.6, 1.1);
    let near = color(13, 12, 18);
    let far = color(196, 168, 146);
    let c = lerpColor(near, far, constrain(pow(t, 1.1), 0, 1));
    c.setAlpha(a);
    leafShape(x, y, s, random(TWO_PI), c);
  }
  // a few close to the crown, still dark and clustered
  for (let i = 0; i < 46; i++) {
    let x = 612 + random(-180, 190);
    let y = 760 + random(-120, 200);
    leafShape(x, y, random(4, 10), random(TWO_PI), color(12, 11, 16, random(140, 240)));
  }
  // a few falling
  for (let i = 0; i < 18; i++) {
    let x = 560 + random(-130, 190);
    let y = 1080 + random(0, 330);
    leafShape(x, y, random(3.5, 8), random(TWO_PI), color(14, 13, 18, random(90, 200)));
  }

  // ---------- VIGNETTE ----------
  let g = drawingContext.createRadialGradient(820, 1080, 260, 820, 1080, 1480);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(0.62, 'rgba(0,0,0,0.14)');
  g.addColorStop(1, 'rgba(6,5,10,0.62)');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(0, 0, width, height);

  // ---------- GRAIN ----------
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let n = random(-11, 11);
    pixels[i] += n;
    pixels[i + 1] += n;
    pixels[i + 2] += n * 0.9;
  }
  updatePixels();
}

