function draw() {}

const HOR = 1252, SX = 690, SY = 1252;

function ss(a, b, x) { let t = constrain((x - a) / (b - a), 0, 1); return t * t * (3 - 2 * t); }

function gradStops(t, stops) {
  for (let i = 0; i < stops.length - 1; i++) {
    if (t <= stops[i + 1][0] || i === stops.length - 2) {
      let a = stops[i], b = stops[i + 1];
      let u = constrain((t - a[0]) / (b[0] - a[0]), 0, 1);
      u = u * u * (3 - 2 * u);
      return [lerp(a[1][0], b[1][0], u), lerp(a[1][1], b[1][1], u), lerp(a[1][2], b[1][2], u)];
    }
  }
}

function skyRGB(x, y) {
  let t = constrain(y / HOR, 0, 1);
  let c = gradStops(t, [
    [0.00, [14, 16, 32]],
    [0.30, [33, 33, 56]],
    [0.58, [78, 63, 88]],
    [0.80, [146, 105, 106]],
    [0.93, [206, 150, 118]],
    [1.00, [238, 192, 150]]
  ]);
  let n = noise(x * 0.0011, y * 0.0075);
  let n2 = noise(x * 0.0045 + 40, y * 0.028 + 40);
  let v = n * 0.82 + n2 * 0.18;
  let band = ss(0.50, 0.72, v);
  let fade = ss(0.05, 0.33, t) * (1 - ss(0.84, 1.0, t));
  let m = band * fade * 0.78;
  let cc = [c[0] * 0.55 + 14, c[1] * 0.52 + 12, c[2] * 0.62 + 22];
  c = [lerp(c[0], cc[0], m), lerp(c[1], cc[1], m), lerp(c[2], cc[2], m)];
  let dx = (x - SX) * 0.75, dy = (y - SY) * 1.3;
  let d = sqrt(dx * dx + dy * dy);
  let g = exp(-d / 300) * 1.1 + exp(-d / 950) * 0.42;
  c[0] += 255 * g * 0.95;
  c[1] += 200 * g * 0.76;
  c[2] += 150 * g * 0.50;
  return c;
}

function waterRGB(x, y) {
  let dy = y - HOR;
  let depth = constrain(dy / (height - HOR), 0, 1);
  let wob = (noise(x * 0.0035, dy * 0.016 + 99) - 0.5) * (40 + 280 * depth);
  let ry = HOR - dy * (0.62 + 0.26 * depth);
  let c = skyRGB(x + wob, max(ry, 2));
  let k = 0.47 - 0.27 * depth;
  c = [c[0] * k, c[1] * k * 0.97, c[2] * k * 1.10 + 7 * (1 - depth)];
  let s = noise(x * 0.0022 + 5, y * 0.09 + 5);
  let band = pow(ss(0.52, 0.86, s), 2);
  let colw = exp(-abs(x - SX) / (165 + dy * 1.35));
  let hl = band * colw * (1 - 0.35 * depth);
  c[0] += 235 * hl; c[1] += 178 * hl; c[2] += 118 * hl;
  let fine = (noise(x * 0.004 + 300, y * 0.35 + 300) - 0.5) * 10 * (1 - depth * 0.6);
  c[0] += fine; c[1] += fine; c[2] += fine;
  return c;
}

function base() {
  loadPixels();
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let c = (y < HOR) ? skyRGB(x, y) : waterRGB(x, y);
      let i = 4 * (y * width + x);
      pixels[i] = constrain(c[0], 0, 255);
      pixels[i + 1] = constrain(c[1], 0, 255);
      pixels[i + 2] = constrain(c[2], 0, 255);
      pixels[i + 3] = 255;
    }
  }
  updatePixels();
}

