      pixels[i] = constrain(pixels[i] * v + g, 0, 255);
      pixels[i + 1] = constrain(pixels[i + 1] * v + g, 0, 255);
      pixels[i + 2] = constrain(pixels[i + 2] * v + g, 0, 255);
    }
  }
  updatePixels();
}

let W = 1600, H = 2000;
let horizonY = 1380;
let sunX = 1060, sunY = 1235, sunR = 108;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
}

function draw() {
  background(8, 10, 14);
  strokeCap(ROUND);
  skyAndWater();
  sunGlow();
  reflection();
  horizonBand();
  painterly(23000);
  sandbar();
  tree();
  figure();
  particles();
  finish();
}

function skyAndWater() {
  strokeWeight(1);
  let top = color(9, 11, 18), mid = color(27, 33, 45), hor = color(124, 110, 98);
  let wtop = color(60, 57, 56), wbot = color(7, 9, 13);
  for (let y = 0; y < H; y++) {
    let c;
    if (y < horizonY) {
      let t = y / horizonY;
      if (t < 0.6) c = lerpColor(top, mid, pow(t / 0.6, 1.2));
      else c = lerpColor(mid, hor, pow((t - 0.6) / 0.4, 1.7));
    } else {
      let t = (y - horizonY) / (H - horizonY);
      c = lerpColor(wtop, wbot, pow(t, 0.45));
    }
    stroke(c);
    line(0, y, W, y);
  }
}

function sunGlow() {
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 70; i++) {
    let t = i / 69;
    let r = lerp(sunR * 10, sunR * 1.05, t);
    fill(24, 19, 12, 7 + 26 * pow(t, 3));
    ellipse(sunX, sunY, r * 2, r * 1.7);
  }
  for (let i = 0; i < 26; i++) {
    let t = i / 25;
    let r = lerp(sunR * 1.35, sunR * 0.72, t);
    fill(70, 62, 48, 10 + 30 * t);
    ellipse(sunX, sunY, r * 2, r * 2);
  }
  pop();
}

function reflection() {
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 300; i++) {
    let t = pow(random(), 1.3);
    let y = horizonY + t * (H - horizonY) * 0.96;
    let spread = lerp(26, 330, t);
    let x = sunX + randomGaussian() * spread * 0.55;
    fill(86, 73, 54, lerp(58, 5, t));
    ellipse(x, y, random(20, 170) * (1 - t * 0.45), random(2, 7));
  }
  pop();
}

function horizonBand() {
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 500; i++) {
    let x = random(W);
    let d = abs(x - sunX) / W;
    fill(78, 70, 58, 44 * (1 - d));
    ellipse(x, horizonY + random(-3, 2), random(30, 130), random(1, 3));
  }
  pop();
}

function painterly(n) {
  loadPixels();
  for (let i = 0; i < n; i++) {
    let x = random(W), y = random(H);
    let px = constrain(floor(x), 0, W - 1);
    let py = constrain(floor(y), 0, H - 1);
    let idx = 4 * (py * W + px);
    let r = pixels[idx], g = pixels[idx + 1], b = pixels[idx + 2];
    let j = randomGaussian() * 9;
    let ang = (noise(x * 0.0012, y * 0.0016) - 0.5) * 1.1;
    let len = random(18, 80);
    if (y > horizonY) { ang *= 0.2; len *= 1.6; }
    strokeWeight(random(2, 8));
    stroke(r + j, g + j * 0.9, b + j * 0.8, random(14, 38));
    let dx = cos(ang) * len * 0.5, dy = sin(ang) * len * 0.5;
    line(x - dx, y - dy, x + dx, y + dy);
  }
}

function sandbar() {
  noStroke();
  fill(17, 18, 21, 130);
  ellipse(905, 1437, 540, 32);
  fill(10, 11, 14, 110);
  ellipse(905, 1447, 430, 22);
}

function tree() {
  stroke(10, 11, 15, 238);
  branch(305, 1394, 212, -HALF_PI - 0.06, 44, 10);
}

function branch(x, y, len, a, w, d) {
  if (d <= 0 || len < 7 || w < 0.6) return;
  let steps = 3, cx = x, cy = y, ca = a;
  for (let s = 0; s < steps; s++) {
    let na = ca + randomGaussian() * 0.07;
    let nx = cx + cos(na) * len / steps;
    let ny = cy + sin(na) * len / steps;
    strokeWeight(max(0.7, lerp(w, w * 0.72, s / steps)));
    line(cx, cy, nx, ny);
    cx = nx; cy = ny; ca = na;
  }
  let nb = (d > 7) ? 2 : (random() < 0.33 ? 3 : 2);
  for (let k = 0; k < nb; k++) {
    let sgn = (k === 0) ? 1 : (k === 1 ? -1 : random([-1, 1]));
    branch(cx, cy, len * random(0.6, 0.82),
      ca + sgn * random(0.12, 0.55) + randomGaussian() * 0.05,
      w * random(0.58, 0.72), d - 1);
  }
}

function figure() {
  let fx = 905, fy = 1430, h = 86;
  noStroke();
  for (let i = 0; i < 44; i++) {
    let t = i / 44;
    fill(9, 10, 13, 55 * (1 - t));
    ellipse(fx + randomGaussian() * 2.2, fy + t * 58, 20 * (1 - t * 0.5), 4);
  }
  fill(9, 10, 13, 248);
  beginShape();
  vertex(fx - 9, fy);
  vertex(fx - 10, fy - h * 0.45);
  vertex(fx - 7.5, fy - h * 0.68);
  vertex(fx - 4, fy - h * 0.76);
  vertex(fx + 4, fy - h * 0.76);
  vertex(fx + 7.5, fy - h * 0.68);
  vertex(fx + 10, fy - h * 0.45);
  vertex(fx + 9, fy);
  endShape(CLOSE);
  rect(fx - 3.5, fy - h * 0.84, 7, 11);
  ellipse(fx, fy - h * 0.88, 16, 19);
}

function particles() {
  let darkC = color(18, 19, 23);
  let paleC = color(232, 214, 180);
  push();
  noStroke();
  for (let i = 0; i < 520; i++) {
    let ox = 305 + randomGaussian() * 185;
    let oy = 1035 + randomGaussian() * 155;
    let t = pow(random(), 0.75);
    let tx = sunX + randomGaussian() * 250;
    let ty = sunY + randomGaussian() * 180;
    let x = lerp(ox, tx, t) + randomGaussian() * 14;
    let y = lerp(oy, ty, t) - sin(t * PI) * random(70, 240) + randomGaussian() * 12;
    let s = lerp(9.5, 2.0, t) * random(0.7, 1.3);
    let c = lerpColor(darkC, paleC, pow(t, 0.9));
    let a = 230 * (1 - 0.55 * t);
    if (t > 0.45) {
      push();
      blendMode(ADD);
      fill(red(c) * 0.22, green(c) * 0.2, blue(c) * 0.16, 55 * t);
      ellipse(x, y, s * 6, s * 6);
      pop();
    }
    fill(red(c), green(c), blue(c), a);
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    ellipse(0, 0, s * 1.5, s * 0.75);
    pop();
  }
  pop();
}

function finish() {
  loadPixels();
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      let i = 4 * (y * W + x);
      let dx = (x - W * 0.5) / (W * 0.62);
      let dy = (y - H * 0.5) / (H * 0.62);
      let r = sqrt(dx * dx + dy * dy);
      let v = constrain(1 - 0.58 * constrain(r - 0.55, 0, 2), 0.3, 1);
      let g = randomGaussian() * 4.5;
      pixels[i] = constrain(pixels[i] * v + g, 0, 255);
      pixels[i + 1] = constrain(pixels[i + 1] * v + g * 0.95, 0, 255);
      pixels[i + 2] = constrain(pixels[i + 2] * v + g * 0.9, 0, 255);
    }
  }
  updatePixels();
}

let W = 1600, H = 2000;
const HZ = 1430, GX = 1070, CX = 700, TOPY = 636, FOOT = 1452;
let bgBuf;

function setup() {
  createCanvas(W, H);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function ss(t) { t = constrain(t, 0, 1); return t * t * (3 - 2 * t); }

function cxAt(y) { return CX + 7 * sin((y - TOPY) * 0.0032) - 4; }

function halfW(y) {
  if (y < TOPY || y > FOOT) return 0;
  const hc = 702, hry = 66, hrx = 56;
  if (y < hc + hry - 6) {
    let d = constrain((y - hc) / hry, -1, 1);
    let w = hrx * sqrt(1 - d * d);
    let neck = y > hc ? lerp(0, 26, constrain((y - (hc + 30)) / 30, 0, 1)) : 0;
    return max(w, neck);
  }
  if (y < 792) return 26 + (y - 762) * 0.1;
  if (y < 848) return lerp(29, 120, ss((y - 792) / 56));
  if (y < 1130) return lerp(120, 92, (y - 848) / 282);
  let t = (y - 1130) / (FOOT - 1130);
  return lerp(92, 134, t * t * 0.8 + t * 0.2);
}

function snapshot() { loadPixels(); return pixels.slice(); }

function sampAt(buf, x, y) {
  x = constrain(floor(x), 0, W - 1);
  y = constrain(floor(y), 0, H - 1);
  const i = 4 * (y * W + x);
  return [buf[i], buf[i + 1], buf[i + 2]];
}

function draw() {
  noStroke();
  skyLayer();
  glowLayer();
  groundLayer();
  waterStreaks();
  painterly(9000);
  bgBuf = snapshot();
  drawFigure();
  rimLight();
  contactShadow();
  figureReflection();
  mistBand();
  motes();
  finalPass();
}

function skyLayer() {
  for (let y = 0; y < HZ; y++) {
    let t = y / HZ, c;
    if (t < 0.58) c = lerpColor(color(4, 5, 12), color(26, 29, 48), ss(t / 0.58));
    else c = lerpColor(color(26, 29, 48), color(96, 84, 88), ss((t - 0.58) / 0.42));
    stroke(c);
    line(0, y, W, y);
  }
  noStroke();
}

function glowLayer() {
  let g = drawingContext.createRadialGradient(GX, HZ + 30, 10, GX, HZ + 30, 880);
  g.addColorStop(0, 'rgba(255,218,158,0.92)');
  g.addColorStop(0.16, 'rgba(228,162,102,0.52)');
  g.addColorStop(0.44, 'rgba(150,98,76,0.22)');
  g.addColorStop(1, 'rgba(40,40,60,0)');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(0, 0, W, HZ + 2);
}

function groundLayer() {
  for (let y = HZ; y < H; y++) {
    let t = (y - HZ) / (H - HZ);
    let c = lerpColor(color(36, 33, 41), color(5, 5, 9), pow(t, 0.55));
    stroke(c);
    line(0, y, W, y);
  }
  noStroke();
  let g = drawingContext.createRadialGradient(GX, HZ, 10, GX, HZ, 760);
  g.addColorStop(0, 'rgba(250,200,140,0.50)');
  g.addColorStop(0.25, 'rgba(200,132,86,0.22)');
  g.addColorStop(1, 'rgba(0,0,0,0)');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(0, HZ, W, 640);
}

function waterStreaks() {
  for (let i = 0; i < 1000; i++) {
    let r = pow(random(), 1.8);
    let y = HZ + 3 + r * (H - HZ);
    let x = random(-120, W);
    let w = random(60, 540), h = random(1, 4.5);
    let d = abs(x + w / 2 - GX) / 720;
    let lightAmt = constrain(1 - d, 0, 1) * constrain(1 - (y - HZ) / 440, 0, 1);
    if (random() < 0.45 + 0.45 * lightAmt) fill(255, 220, 180, 5 + 30 * lightAmt * random());
    else fill(4, 5, 9, random(10, 55));
    rect(x, y, w, h);
  }
  for (let i = 0; i < 160; i++) {
    let y = HZ + pow(random(), 2.2) * 420;
    fill(230, 206, 182, random(4, 16));
    rect(random(-100, W), y, random(120, 700), random(0.8, 2));
  }
}

function painterly(n) {
  let buf = snapshot();
  for (let i = 0; i < n; i++) {
    let x = random(W), y = random(H);
    let c = sampAt(buf, x, y);
    let j = random(-16, 16);
    let a = noise(x * 0.0012, y * 0.0012) * TWO_PI;
    let ang = a * 0.22 + random(-0.1, 0.1);
    push();
    translate(x, y);
    rotate(ang * 0.5);
    fill(c[0] + j, c[1] + j * 0.95, c[2] + j * 0.88, random(16, 44));
    ellipse(0, 0, random(30, 115), random(5, 14));
    pop();
  }
}

function solidity(x, y) {
  let w = max(halfW(y), 1);
  let s = constrain(map(y, 640, 1180, 0.05, 1), 0, 1);
  s = pow(s, 1.25);
  let e = abs(x - cxAt(y)) / w;
  s *= 1 - 0.5 * e * e;
  s += 0.30 * (noise(x * 0.011, y * 0.009) - 0.5);
  if (y > 1200) s = 1;
  return constrain(s, 0, 1);
}

function drawFigure() {
  noStroke();
  fill(8, 9, 14);
  beginShape();
  for (let y = TOPY; y <= FOOT; y += 4) {
    let w = halfW(y) + (noise(y * 0.03, 1) - 0.5) * 7;
    vertex(cxAt(y) - w, y);
  }
  for (let y = FOOT; y >= TOPY; y -= 4) {
    let w = halfW(y) + (noise(y * 0.03, 9) - 0.5) * 7;
    vertex(cxAt(y) + w, y);
  }
  endShape(CLOSE);

  for (let i = 0; i < 9000; i++) {
    let y = random(TOPY, FOOT);
    let w = halfW(y);
    if (w <= 0) continue;
    let x = cxAt(y) + random(-w, w);
    let v = noise(x * 0.01, y * 0.006);
    fill(5 + v * 18, 6 + v * 19, 11 + v * 24, random(30, 90));
    push();
    translate(x, y);
    rotate(random(-0.3, 0.3));
    ellipse(0, 0, random(8, 28), random(4, 10));
    pop();
  }

  for (let i = 0; i < 70000; i++) {
    let y = random(TOPY - 12, 1235);
    let w = halfW(y);
    if (w <= 0) continue;
    let x = cxAt(y) + random(-w - 4, w + 4);
    if (random() > solidity(x, y)) {
      let c = sampAt(bgBuf, x, y);
      let j = random(-8, 8);
      fill(c[0] + j, c[1] + j, c[2] + j, random(150, 255));
      ellipse(x, y, random(4, 13), random(4, 10));
    }
  }
}

function rimLight() {
  for (let y = TOPY; y < FOOT; y += 2) {
    let w = halfW(y);
    if (w <= 0) continue;
    let x = cxAt(y) + w;
    let s = solidity(x - 4, y);
    if (random() < s * 0.9) {
      fill(242, 198, 148, 18 + 95 * s * random());
      ellipse(x + random(-2, 2), y + random(-2, 2), random(3, 7), random(3, 9));
    }
    if (random() < s * 0.25) {
      let xl = cxAt(y) - w;
      fill(120, 128, 150, 10 + 40 * s * random());
      ellipse(xl + random(-2, 2), y, random(2, 5), random(3, 7));
    }
  }
}

function contactShadow() {
  for (let i = 0; i < 40; i++) {
    fill(3, 4, 7, 16);
    ellipse(cxAt(FOOT) + random(-10, 10), FOOT + random(-4, 12), random(240, 380), random(18, 44));
  }
}

function figureReflection() {
  for (let i = 0; i < 9000; i++) {
    let d = pow(random(), 1.5) * 310;
    let y = FOOT + d;
    if (y > H) continue;
    let ys = FOOT - d * 1.5;
    let w = halfW(ys);
    if (w <= 0) continue;
    let x = cxAt(ys) + random(-w, w) * 1.05 + random(-7, 7);
    let fade = constrain(1 - d / 310, 0, 1);
    let s = solidity(x, ys);
    fill(5, 6, 10, 8 + 75 * fade * s * random());
    ellipse(x, y + random(-2, 2), random(10, 36), random(2, 5));
  }
}

function mistBand() {
  let g = drawingContext.createLinearGradient(0, HZ - 130, 0, HZ + 60);
  g.addColorStop(0, 'rgba(210,182,164,0)');
  g.addColorStop(0.6, 'rgba(222,192,168,0.16)');
  g.addColorStop(1, 'rgba(200,170,150,0)');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(0, HZ - 130, W, 190);
}

function motes() {
  for (let i = 0; i < 1500; i++) {
    let yb = random(620, 1180);
    let rise = pow(random(), 1.6) * 640;
    let y = yb - rise;
    if (y < 30) continue;
    let spread = 26 + rise * 0.42;
    let x = cxAt(yb) + randomGaussian() * spread * 0.5 + rise * 0.22 + random(-10, 10);
    let fade = constrain(1 - rise / 660, 0, 1);
    let sz = random(1.6, 5.2) * (0.5 + fade * 0.8);
    let c = lerpColor(color(255, 226, 178), color(168, 178, 196), random());
    if (random() < 0.09) {
      fill(255, 218, 168, 8 + 22 * fade);
      ellipse(x, y, sz * 6, sz * 6);
    }
    fill(red(c), green(c), blue(c), 20 + 175 * fade * random());
    ellipse(x, y, sz, sz * random(0.8, 1.3));
  }
}

function finalPass() {
  let g = drawingContext.createRadialGradient(800, 1050, 300, 800, 1050, 1260);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(0.6, 'rgba(0,0,0,0.18)');
  g.addColorStop(1, 'rgba(0,0,0,0.62)');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(0, 0, W, H);

  for (let i = 0; i < 90000; i++) {
    stroke(random(40, 255), random(4, 14));
    point(random(W), random(H));
  }
  noStroke();
}

let W = 1600, H = 2000;
let FY = 1180;
let WX1 = 365, WX2 = 845, WY1 = 285, WY2 = 885;
let P0 = [575, 1248], P1 = [1180, 1228], P2 = [1470, 1875], P3 = [700, 1940];

const G = {
  BL: [762, 1432], BR: [1026, 1414], FR: [1070, 1504], FL: [740, 1522],
  BLb: [736, 1700], BRb: [1042, 1678], FLb: [704, 1800], FRb: [1108, 1776],
  TL: [748, 1090], TR: [1018, 1074], C: [883, 1026]
};

const MAIN = {
  noStroke: () => noStroke(),
  fill: (a, b, c, d) => fill(a, b, c, d),
  ellipse: (a, b, c, d) => ellipse(a, b, c, d),
  quad: (a, b, c, d, e, f, g, h) => quad(a, b, c, d, e, f, g, h)
};

function setup() {
