}
function draw() {}

/* ---------- helpers ---------- */
function lerpPt(a, b, t) { return [lerp(a[0], b[0], t), lerp(a[1], b[1], t)]; }

function brush(x, y, len, ang, w, c, a) {
  push();
  translate(x, y);
  rotate(ang);
  noStroke();
  fill(red(c), green(c), blue(c), a);
  let n = constrain(floor(len / 9), 3, 16);
  for (let i = 0; i < n; i++) {
    let t = i / (n - 1);
    let xx = lerp(-len / 2, len / 2, t) + random(-2, 2);
    let yy = random(-1.6, 1.6);
    let ww = w * (0.55 + 0.45 * sin(t * PI));
    ellipse(xx, yy, ww * 1.15, ww);
  }
  pop();
}

function limb(g, x1, y1, x2, y2, w1, w2, c, a) {
  g.noStroke();
  g.fill(red(c), green(c), blue(c), a);
  let d = dist(x1, y1, x2, y2);
  let n = max(2, floor(d / 3));
  for (let i = 0; i <= n; i++) {
    let t = i / n;
    let w = lerp(w1, w2, t);
    g.ellipse(lerp(x1, x2, t) + random(-0.7, 0.7), lerp(y1, y2, t) + random(-0.7, 0.7), w, w);
  }
}

function railPt(t) {
  let x = (1 - t) * (1 - t) * G.TL[0] + 2 * (1 - t) * t * G.C[0] + t * t * G.TR[0];
  let y = (1 - t) * (1 - t) * G.TL[1] + 2 * (1 - t) * t * G.C[1] + t * t * G.TR[1];
  return [x, y];
}

function poolPt(u, v) {
  let top = lerpPt(P0, P1, u);
  let bot = lerpPt(P3, P2, u);
  return lerpPt(top, bot, v);
}

function insetQuad(Q, t) {
  let cx = (Q[0][0] + Q[1][0] + Q[2][0] + Q[3][0]) / 4;
  let cy = (Q[0][1] + Q[1][1] + Q[2][1] + Q[3][1]) / 4;
  return Q.map(p => [lerp(p[0], cx, t), lerp(p[1], cy, t)]);
}

function quadA(q, j) {
  quad(q[0][0] + random(-j, j), q[0][1] + random(-j, j),
       q[1][0] + random(-j, j), q[1][1] + random(-j, j),
       q[2][0] + random(-j, j), q[2][1] + random(-j, j),
       q[3][0] + random(-j, j), q[3][1] + random(-j, j));
}

/* ---------- painting ---------- */
function paintAll() {
  noStroke();
  background(14, 13, 16);
  paintWall();
  paintFloor();
  paintBase();
  paintSeams(80);
  paintWindow();
  paintBeam();
  paintPool();
  paintSeams(42);
  paintPaneShadows();
  paintShadow();
  paintChair();
