}

function paintWall() {
  for (let i = 0; i < 5600; i++) {
    let x = random(-60, W + 60);
    let y = random(-60, FY + 40);
    let d = dist(x, y, 605, 585);
    let g = 92 * Math.exp(-d / 390) + 34 * Math.exp(-d / 1000);
    let n = noise(x * 0.0014, y * 0.0014);
    let n2 = noise(x * 0.006, y * 0.006 + 40);
    let b = 16 + 14 * n + 6 * n2;
    let c = color(b * 1.14 + g * 0.95, b * 1.03 + g * 1.0, b * 1.0 + g * 1.1);
    brush(x, y, random(70, 230), HALF_PI + random(-0.14, 0.14), random(9, 28), c, random(10, 28));
  }
  for (let i = 0; i < 2600; i++) {
    let x = random(-60, W + 60), y = random(-60, FY);
    let d = dist(x, y, 605, 585);
    if (d < 760 && random() < 0.85) continue;
    brush(x, y, random(90, 260), HALF_PI + random(-0.22, 0.22), random(14, 42),
          color(9, 8, 12), random(5, 15));
  }
}

function paintFloor() {
  for (let i = 0; i < 5200; i++) {
    let x = random(-70, W + 70);
    let y = random(FY - 20, H + 50);
    let n = noise(x * 0.002, y * 0.004 + 10);
    let b = 11 + 13 * n;
    let d = dist(x, y, 1020, 1560);
    let g = 22 * Math.exp(-d / 620);
    let c = color(b * 1.5 + g, b * 1.2 + g, b * 0.95 + g * 0.95);
    brush(x, y, random(90, 300), random(-0.05, 0.05), random(10, 30), c, random(12, 32));
