}

function paintBase() {
  for (let i = 0; i < 1300; i++) {
    let x = random(-40, W + 40);
    let y = FY - random(0, 62);
    let d = abs(x - 760);
    let g = 26 * Math.exp(-d / 420);
    brush(x, y, random(60, 200), random(-0.03, 0.03), random(10, 24),
          color(20 + g, 19 + g, 20 + g), random(18, 45));
  }
  for (let i = 0; i < 500; i++) {
    let x = random(-40, W + 40);
    let d = abs(x - 700);
    let g = 48 * Math.exp(-d / 460);
    brush(x, FY - 60 + random(-3, 3), random(40, 140), 0, random(3, 7),
