}

function paintSeams(a) {
  let vpx = 700, vpy = 1010;
  for (let k = -9; k <= 9; k++) {
    let bx = 700 + k * 245;
    let t1 = (FY - 8 - vpy) / (2000 - vpy);
    let t2 = (2050 - vpy) / (2000 - vpy);
    let x1 = lerp(vpx, bx, t1), y1 = FY - 8;
    let x2 = lerp(vpx, bx, t2), y2 = 2050;
    let n = 70;
    for (let i = 0; i <= n; i++) {
      let t = i / n;
      let x = lerp(x1, x2, t), y = lerp(y1, y2, t);
      let w = lerp(2.4, 7, t);
      noStroke();
      fill(5, 4, 6, a);
      ellipse(x + random(-1, 1), y, w * 1.5, w);
      fill(70, 64, 56, a * 0.22);
      ellipse(x + w * 1.7, y, w * 1.1, w * 0.8);
    }
