}

function paintWindow() {
  blendMode(ADD);
  noStroke();
  for (let i = 40; i >= 1; i--) {
    let t = i / 40;
    let e = t * t * 310;
    fill(26 * (1 - t) + 5, 29 * (1 - t) + 6, 34 * (1 - t) + 8, 16);
    rect(WX1 - e, WY1 - e * 0.85, (WX2 - WX1) + 2 * e, (WY2 - WY1) + 1.7 * e, 60);
