    let t = constrain((y - WY1) / (WY2 - WY1), 0, 1);
    let n = noise(x * 0.005, y * 0.005 + 90);
    let b = lerp(238, 192, t) + 12 * n - 6;
    brush(x, y, random(40, 150), random(-0.12, 0.12), random(10, 28),
          color(b * 0.92, b * 0.96, b), random(40, 100));
