  fill(14, 13, 16, 255);
  rect(WX1 - 26, WY1 - 26, WX2 - WX1 + 52, 26);
  rect(WX1 - 26, WY2, WX2 - WX1 + 52, 28);
  rect(WX1 - 26, WY1 - 26, 26, WY2 - WY1 + 54);
  rect(WX2, WY1 - 26, 28, WY2 - WY1 + 54);

  blendMode(ADD);
  for (let i = 0; i < 1100; i++) {
