function paintBeam() {
  blendMode(ADD);
  noStroke();
  let outer = [[WX1 - 10, WY1 + 10], [WX2 + 10, WY1 + 10], [1510, 1910], [650, 1980]];
  let inner = [[WX1 + 150, WY1 + 200], [WX2 - 150, WY1 + 200], [1270, 1830], [880, 1880]];
