function darkBand(ua, ub, va, vb) {
  noStroke();
  for (let p = 0; p < 4; p++) {
    let j = p * 2.6;
    fill(8, 7, 10, 22);
    let A = poolPt(ua, va), B = poolPt(ub, va), C = poolPt(ub, vb), D = poolPt(ua, vb);
    quad(A[0] - j, A[1] - j, B[0] + j, B[1] - j, C[0] + j, C[1] + j, D[0] - j, D[1] + j);
  }
}

function paintPaneShadows() {
  for (let k = 1; k <= 2; k++) {
    let u = k / 3;
    darkBand(u - 0.014, u + 0.014, -0.02, 1.02);
  }
  darkBand(-0.02, 1.02, 0.404, 0.446);
}

function renderChair(g, T, c, a, ws) {
  const L = (p1, p2, w1, w2) => {
    let A = T(p1), B = T(p2);
    limb(g, A[0], A[1], B[0], B[1], w1 * ws, w2 * ws, c, a);
  };
  const E = (p, w) => {
    let A = T(p);
    g.noStroke();
    g.fill(red(c), green(c), blue(c), a);
    g.ellipse(A[0] + random(-0.6, 0.6), A[1], w * ws, w * ws * 0.95);
  };

  L(G.BL, G.BLb, 18, 13);
  L(G.BR, G.BRb, 18, 13);
  L(G.FL, G.FLb, 21, 15);
  L(G.FR, G.FRb, 21, 15);

  L(lerpPt(G.FL, G.FLb, 0.55), lerpPt(G.FR, G.FRb, 0.55), 10, 10);
  L(lerpPt(G.BL, G.BLb, 0.62), lerpPt(G.BR, G.BRb, 0.62), 9, 9);
  L(lerpPt(G.BL, G.BLb, 0.62), lerpPt(G.FL, G.FLb, 0.55), 9, 10);
  L(lerpPt(G.BR, G.BRb, 0.62), lerpPt(G.FR, G.FRb, 0.55), 9, 10);

  L(G.BL, G.TL, 21, 15);
  L(G.BR, G.TR, 21, 15);

  for (let i = 1; i <= 6; i++) {
    let t = i / 7;
    let b = [lerp(G.BL[0], G.BR[0], t), lerp(G.BL[1], G.BR[1], t) - 4];
    L(b, railPt(t), 9, 8);
  }
  for (let i = 0; i <= 44; i++) {
    let t = i / 44, p = railPt(t);
    E([p[0], p[1] + 185], 13);
  }
  for (let i = 0; i <= 56; i++) E(railPt(i / 56), 23);

  let s = [T(G.BL), T(G.BR), T(G.FR), T(G.FL)];
  g.noStroke();
  g.fill(red(c), green(c), blue(c), a);
  g.quad(s[0][0], s[0][1], s[1][0], s[1][1], s[2][0], s[2][1], s[3][0], s[3][1]);
  let f1 = T(G.FL), f2 = T(G.FR);
  g.quad(f1[0], f1[1], f2[0], f2[1], f2[0] + 2, f2[1] + 24 * ws, f1[0] - 2, f1[1] + 26 * ws);
}

function paintShadow() {
  let sg = createGraphics(W / 2, H / 2);
  sg.pixelDensity(1);
  sg.clear();
  const sp = p => {
    let h = max(0, 1770 - p[1]);
    return [p[0] + 0.54 * h, 1775 + 0.30 * h];
  };
  sg.push();
  sg.scale(0.5);
  renderChair(sg, sp, color(0, 0, 0), 255, 1.2);
  sg.pop();
  sg.filter(BLUR, 5);
  push();
  tint(255, 255, 255, 150);
  image(sg, 0, 0, W, H);
  pop();
  noTint();

  noStroke();
  let feet = [G.BLb, G.BRb, G.FLb, G.FRb];
  for (let f of feet) {
    for (let i = 0; i < 16; i++) {
      fill(6, 5, 8, 24);
      ellipse(f[0] + 12 + random(-5, 5), f[1] + 6 + random(-3, 3), random(30, 80), random(12, 26));
    }
  }
}

function paintChair() {
  const D = color(12, 11, 15);
  renderChair(MAIN, p => p, D, 255, 1.0);

  // lit seat plane
  noStroke();
  let s = [G.BL, G.BR, G.FR, G.FL];
  let q = insetQuad(s, 0.14);
  fill(44, 42, 40, 120);
  quadA(q, 2);
  fill(58, 56, 52, 60);
  quadA(insetQuad(s, 0.38), 2);

  // rim light from the window
  let rc = color(132, 140, 146);
  limb(MAIN, G.TL[0] - 8, G.TL[1] + 10, G.BL[0] - 10, G.BL[1] - 12, 5, 4, rc, 70);
  limb(MAIN, G.BL[0] - 10, G.BL[1] + 10, G.BLb[0] - 9, G.BLb[1] - 24, 5, 3, rc, 44);
  limb(MAIN, G.FL[0] - 11, G.FL[1] + 10, G.FLb[0] - 9, G.FLb[1] - 26, 6, 4, rc, 60);
  limb(MAIN, G.FL[0] + 2, G.FL[1] + 6, G.FR[0] - 2, G.FR[1] + 6, 5, 4, rc, 46);
  for (let i = 0; i <= 54; i++) {
    let t = i / 54, p = railPt(t);
    noStroke();
    fill(132, 140, 146, 52 * (1 - t * 0.5));
    ellipse(p[0] - 2, p[1] - 9 + random(-1, 1), 7, 5);
  }
  for (let i = 1; i <= 6; i++) {
    let t = i / 7;
    let b = [lerp(G.BL[0], G.BR[0], t), lerp(G.BL[1], G.BR[1], t) - 4];
    let tp = railPt(t);
    limb(MAIN, b[0] - 4, b[1] - 6, tp[0] - 4, tp[1] + 10, 2.5, 2, rc, 26);
  }
}

function paintMotes() {
  blendMode(ADD);
  noStroke();
  let B = [[WX1 + 20, WY1 + 110], [WX2 - 20, WY1 + 110], [1460, 1900], [690, 1950]];
  for (let i = 0; i < 700; i++) {
    let u = random(), v = pow(random(), 0.85);
    let p = lerpPt(lerpPt(B[0], B[1], u), lerpPt(B[3], B[2], u), v);
    let s = random(2, 6);
    let br = random(26, 120) * (1 - abs(u - 0.5) * 0.9);
    fill(br * 0.86, br * 0.93, br, 62);
    ellipse(p[0], p[1], s, s * 0.95);
  }
  for (let i = 0; i < 40; i++) {
    let u = random(0.15, 0.85), v = random(0.1, 0.95);
    let p = lerpPt(lerpPt(B[0], B[1], u), lerpPt(B[3], B[2], u), v);
    fill(60, 66, 72, 30);
    ellipse(p[0], p[1], random(10, 22), random(10, 22));
  }
  blendMode(BLEND);
}

function finish() {
  // soft glaze
  blendMode(BLEND);
  noStroke();
  for (let i = 0; i < 900; i++) {
    let x = random(-40, W + 40), y = random(-40, H + 40);
    let d = dist(x, y, 760, 1150);
    if (d < 620) continue;
    fill(10, 9, 12, 9);
    ellipse(x, y, random(90, 320), random(90, 320));
  }

  loadPixels();
  let cx = 760, cy = 1150;
  let maxd = 0;
  let cs = [[0, 0], [W, 0], [0, H], [W, H]];
  for (let c of cs) maxd = max(maxd, dist(c[0], c[1], cx, cy));
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      let i = 4 * (y * W + x);
      let dx = x - cx, dy = y - cy;
      let d = Math.sqrt(dx * dx + dy * dy) / maxd;
      let v = 1 - 0.72 * Math.pow(d, 1.9);
      let gr = (random() - 0.5) * 13;
      pixels[i] = constrain(pixels[i] * v + gr, 0, 255);
      pixels[i + 1] = constrain(pixels[i + 1] * v + gr, 0, 255);
      pixels[i + 2] = constrain(pixels[i + 2] * v + gr * 1.05, 0, 255);
    }
  }
  updatePixels();
}

// "Cendre" — p5.js 1.11 — 1600 x 2000 static painting
let CW = 1600, CH = 2000;
let cxF = 690, byF = 1500, hF = 620;
let glowX = 900, horizonY = 1398;
let parts = [], grad = [];

function setup() {
  createCanvas(CW, CH);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noiseDetail(4, 0.55);
  rectMode(CENTER);
  noStroke();
  noLoop();
}

function draw() {
  grad = buildGrad();
  buildBody();
  paintSky();
  paintStrokes();
  paintFarShore();
  paintWater();
  paintReflection();
  paintCastShadow();
  paintFigure();
  paintAsh();
  paintPlume();
  paintHaze();
  finishPass();
}

/* ---------- helpers ---------- */
function ss(a, b, x) { let t = constrain((x - a) / (b - a), 0, 1); return t * t * (3 - 2 * t); }
function smin(a, b, k) { let h = constrain(0.5 + 0.5 * (b - a) / k, 0, 1); return lerp(b, a, h) - k * h * (1 - h); }
function seg(x0, y0, x1, y1, r) { return { x0: x0, y0: y0, x1: x1, y1: y1, r: r }; }

function buildGrad() {
  const stops = [
    [0, [7, 8, 14]], [380, [12, 13, 21]], [830, [27, 24, 29]],
    [1120, [62, 44, 38]], [1300, [122, 80, 50]], [1395, [152, 102, 62]],
    [1403, [70, 50, 42]], [1490, [44, 32, 29]], [1720, [22, 17, 17]], [1999, [9, 8, 10]]
  ];
  let t = [];
  for (let y = 0; y < CH; y++) {
    let i = 0;
    while (i < stops.length - 2 && y > stops[i + 1][0]) i++;
    let y0 = stops[i][0], c0 = stops[i][1], y1 = stops[i + 1][0], c1 = stops[i + 1][1];
    let u = constrain((y - y0) / (y1 - y0), 0, 1);
    u = u * u * (3 - 2 * u);
    t.push([lerp(c0[0], c1[0], u), lerp(c0[1], c1[1], u), lerp(c0[2], c1[2], u)]);
  }
  return t;
}

function skyCol(x, y) {
  let b = grad[constrain(Math.floor(y), 0, CH - 1)];
  let kH = Math.exp(-Math.pow((y - horizonY + 6) / 175, 2));
  let kB = Math.exp(-Math.pow((y - horizonY) / 540, 2));
  let gx = Math.exp(-Math.pow((x - glowX) / 430, 2));
  let gx2 = Math.exp(-Math.pow((x - glowX) / 950, 2));
  let add = kH * gx * 168 + kB * gx2 * 42;
  if (y > horizonY) add *= 0.78;
  return [b[0] + add, b[1] + add * 0.6, b[2] + add * 0.3];
}

function buildBody() {
  const s = hF, c = cxF, b = byF;
  parts = [
    seg(c, b - 0.938 * s, c, b - 0.905 * s, 0.060 * s),
    seg(c, b - 0.872 * s, c, b - 0.822 * s, 0.034 * s),
    seg(c - 0.082 * s, b - 0.788 * s, c + 0.082 * s, b - 0.790 * s, 0.054 * s),
    seg(c, b - 0.780 * s, c - 0.004 * s, b - 0.500 * s, 0.086 * s),
    seg(c - 0.112 * s, b - 0.752 * s, c - 0.126 * s, b - 0.445 * s, 0.031 * s),
    seg(c + 0.112 * s, b - 0.752 * s, c + 0.127 * s, b - 0.448 * s, 0.031 * s),
    seg(c - 0.047 * s, b - 0.520 * s, c - 0.040 * s, b - 0.006 * s, 0.043 * s),
    seg(c + 0.047 * s, b - 0.520 * s, c + 0.041 * s, b - 0.006 * s, 0.043 * s)
  ];
}

function sdBody(px, py) {
  let d = 1e9;
  for (let i = 0; i < parts.length; i++) {
    const p = parts[i];
    let vx = p.x1 - p.x0, vy = p.y1 - p.y0;
    let wx = px - p.x0, wy = py - p.y0;
    let L = vx * vx + vy * vy;
    let t = L > 0 ? Math.min(1, Math.max(0, (wx * vx + wy * vy) / L)) : 0;
    let dx = wx - t * vx, dy = wy - t * vy;
    let dd = Math.sqrt(dx * dx + dy * dy) - p.r;
    d = smin(d, dd, 14);
  }
  return d;
}

function erosion(x, y) {
  let f1 = noise(x * 0.0075, y * 0.0075);
  let f2 = noise(x * 0.027 + 50, y * 0.027);
  return constrain((f1 * 0.65 + f2 * 0.35 - 0.5) * 2.1 + 0.5, 0, 1);
}
function solidity(y) { return 1 - ss(0.24, 0.99, (byF - y) / hF); }

/* ---------- layers ---------- */
function paintSky() {
  loadPixels();
  for (let y = 0; y < CH; y++) {
    let nA = 0, nB = 0, nC = 0;
    for (let x = 0; x < CW; x++) {
      if ((x & 3) === 0) {
        nA = noise(x * 0.0011, y * 0.0032);
        nB = noise(x * 0.0006 + 40, y * 0.013 + 10);
        nC = noise(x * 0.0025 + 90, y * 0.06 + 5);
      }
      let c = skyCol(x, y);
      let r = c[0], g = c[1], b = c[2];
      let f = 0.84 + 0.34 * nA;
      r *= f; g *= f; b *= f;
      let band = (nB - 0.5) * 20 * Math.exp(-Math.pow((y - horizonY) / 620, 2));
      r += band; g += band * 0.7; b += band * 0.45;
      if (y > horizonY) {
        let rip = (nC - 0.5) * 26 * constrain(1 - (y - horizonY) / 640, 0, 1);
        r += rip * 1.1; g += rip * 0.7; b += rip * 0.4;
      }
      let i = 4 * (y * CW + x);
      pixels[i] = constrain(r, 0, 255);
      pixels[i + 1] = constrain(g, 0, 255);
      pixels[i + 2] = constrain(b, 0, 255);
      pixels[i + 3] = 255;
    }
  }
  updatePixels();
}

function paintStrokes() {
  for (let i = 0; i < 4200; i++) {
    let y = random(-20, CH + 20);
    let x = random(-150, CW + 150);
    let c = skyCol(constrain(x, 0, CW - 1), constrain(y, 0, CH - 1));
    let warm = random(-16, 20);
    let len = random(70, 480) * (y > horizonY ? 1.4 : 1.0);
    let th = random(2, 15);
    push();
    translate(x, y);
    rotate(random(-0.035, 0.035));
    fill(constrain(c[0] + warm * 1.2, 0, 255), constrain(c[1] + warm * 0.6, 0, 255),
         constrain(c[2] + warm * 0.25, 0, 255), random(8, 26));
    rect(0, 0, len, th);
    pop();
  }
}

function paintFarShore() {
  for (let x = -10; x < CW + 10; x += 2) {
    let hgt = 3 + 13 * noise(x * 0.0022, 9) + 6 * noise(x * 0.012, 3);
    fill(26, 19, 18, 170);
    rect(x, horizonY - hgt * 0.5 + 1, 3, hgt);
  }
}

function paintWater() {
  for (let i = 0; i < 2800; i++) {
    let dy = Math.pow(random(), 1.25);
    let y = horizonY + 3 + dy * (CH - horizonY);
    let x = glowX + randomGaussian() * (150 + 760 * dy);
    let w = random(40, 520) * (0.3 + dy * 1.7);
    let th = random(1.2, 4.5) + dy * 5;
    let g = Math.exp(-Math.pow((x - glowX) / (250 + 950 * dy), 2)) * (1 - dy * 0.72);
    fill(215 + random(-25, 25), 158, 100, random(5, 46) * g + random(1, 5));
    rect(x, y, w, th);
  }
  for (let i = 0; i < 2200; i++) {
    let dy = Math.pow(random(), 0.9);
    let y = horizonY + 4 + dy * (CH - horizonY);
    let x = random(-100, CW + 100);
    fill(9, 8, 11, random(6, 34) * (0.3 + dy));
    rect(x, y, random(60, 600), random(1.2, 6) + dy * 4);
  }
}

function paintReflection() {
  const x0 = Math.floor(cxF - 0.32 * hF), x1 = Math.ceil(cxF + 0.32 * hF);
  const y0 = Math.floor(byF - 1.0 * hF);
  for (let y = y0; y <= byF; y++) {
    let sol = solidity(y);
    if (sol < 0.015) continue;
    let yy = byF + (byF - y) * 0.80;
    if (yy > CH + 4) continue;
    let wob = Math.sin(yy * 0.04) * 6 + (noise(yy * 0.02, 3) - 0.5) * 30;
    let band = 0.35 + 0.65 * noise(yy * 0.085, 7);
    let fade = constrain(1 - (yy - byF) / 600, 0, 1);
    for (let x = x0; x <= x1; x++) {
      let d = sdBody(x, y);
      if (d > 0.6) continue;
      let cov = constrain(0.6 - d, 0, 1);
      let a = sol * band * cov * fade * erosion(x, y) * 1.5;
      if (a < 0.01) continue;
      fill(8, 7, 11, constrain(165 * a, 0, 190));
      rect(x + wob, yy, 1.3, 1.9);
    }
  }
}

function paintCastShadow() {
  for (let i = 0; i < 80; i++) {
    let t = i / 79;
    fill(7, 6, 9, 22 * Math.pow(1 - t, 1.6));
    ellipse(cxF + 10 * t + (noise(t * 4, 11) - 0.5) * 18, byF + 8 + t * 300,
            210 * (1 - 0.3 * t) + 70 * t, 46 - 18 * t);
  }
}

function paintFigure() {
  const x0 = Math.floor(cxF - 0.32 * hF), x1 = Math.ceil(cxF + 0.32 * hF);
  const y0 = Math.floor(byF - 1.03 * hF), y1 = Math.ceil(byF + 6);
  for (let y = y0; y <= y1; y++) {
    let t = (byF - y) / hF;
    let sol = solidity(y);
    for (let x = x0; x <= x1; x++) {
      let d = sdBody(x, y);
      if (d > 1.3) continue;
      let cov = constrain(0.65 - d, 0, 1);
      let field = erosion(x, y);
      let a = constrain(sol * 1.32 - (field - 0.5) * 1.05, 0, 1);
      a *= constrain(0.68 + 0.55 * noise(x * 0.06, y * 0.06), 0, 1.25);
      if (a < 0.006) continue;
      let rimS = ss(-15, -0.5, d);
      let m = Math.pow(rimS, 2.3) * (0.18 + 0.52 * t);
      let br = lerp(9, 34, t), bg = lerp(8, 25, t), bb = lerp(11, 23, t);
      fill(lerp(br, 226, m), lerp(bg, 160, m), lerp(bb, 102, m), constrain(255 * a * cov, 0, 255));
      rect(x + 0.5, y + 0.5, 1.15, 1.15);
    }
  }
}

function paintAsh() {
  for (let i = 0; i < 180000; i++) {
    let x = cxF + randomGaussian() * 0.17 * hF;
    let y = random(byF - 1.02 * hF, byF - 0.12 * hF);
    let d = sdBody(x, y);
    if (d > 24) continue;
    let t = (byF - y) / hF;
    let field = erosion(x, y);
    let a = constrain(solidity(y) * 1.32 - (field - 0.5) * 1.05, 0, 1);
    let diss = constrain(1 - a, 0, 1) * ss(0.16, 0.55, t);
    if (random() > diss * 0.6) continue;
    let rise = Math.pow(random(), 1.8) * (70 + 840 * t);
    let ang = noise(x * 0.0030, y * 0.0030 + 77) - 0.5;
    let xx = x + ang * rise * 1.6 + rise * 0.13 + randomGaussian() * 7;
    let yy = y - rise;
    let fade = constrain(1 - rise / 900, 0, 1);
    let aa = (5 + 26 * fade) * (0.35 + 0.85 * random());
    fill(lerp(146, 198, fade), lerp(140, 158, fade), lerp(144, 124, fade), aa);
    rect(xx, yy, random(1, 2.6), random(1, 2.4));
  }
}

function paintPlume() {
  for (let i = 0; i < 90000; i++) {
    let u = Math.pow(random(), 0.78);
    let yy = (byF - 0.95 * hF) - u * 1020;
    let spread = 34 + 540 * Math.pow(u, 0.9);
    let xx = cxF + randomGaussian() * spread * 0.45 + Math.sin(u * 2.5) * 130 * u + 70 * u;
    if (xx < -40 || xx > CW + 40 || yy < -20) continue;
    let dens = Math.pow(1 - u, 1.6) * (0.3 + 0.95 * noise(xx * 0.0035, yy * 0.0035, 5));
    if (random() > dens * 0.5) continue;
    let aa = (4 + 20 * (1 - u)) * (0.3 + 0.9 * random());
    fill(lerp(176, 142, u), lerp(160, 142, u), lerp(140, 148, u), aa);
    rect(xx, yy, random(1, 2.3), random(1, 2.1));
  }
}

function paintHaze() {
  for (let i = 0; i < 520; i++) {
    let y = horizonY + randomGaussian() * 230;
    let x = glowX + randomGaussian() * 520;
    let g = Math.exp(-Math.pow((x - glowX) / 700, 2)) * Math.exp(-Math.pow((y - horizonY) / 300, 2));
    fill(224, 166, 108, 7 * g + 1.2);
    ellipse(x, y, random(300, 1100), random(40, 190));
  }
}

function finishPass() {
  loadPixels();
  for (let y = 0; y < CH; y++) {
    let dy = (y - 1010) / 1010;
    for (let x = 0; x < CW; x++) {
      let dx = (x - 790) / 790;
      let v = 1 - 0.62 * Math.pow(dx * dx * 0.92 + dy * dy * 0.98, 1.3);
      v = constrain(v, 0.26, 1);
      let i = 4 * (y * CW + x);
      let gr = (random() - 0.5) * 13;
      pixels[i] = constrain(pixels[i] * v + gr + 3, 0, 255);
      pixels[i + 1] = constrain(pixels[i + 1] * v + gr + 2.5, 0, 255);
      pixels[i + 2] = constrain(pixels[i + 2] * v + gr + 6, 0, 255);
    }
  }
  updatePixels();
}

// "La barque vide" — p5.js 1.11 — toile 1600 x 2000

const W = 1600, H = 2000;
const HOR = 1285;   // ligne d'horizon
const GX  = 700;    // centre de la lueur
const BX  = 600;    // position de la barque

function setup() {
  createCanvas(W, H);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  colorMode(RGB, 255);
  noLoop();
}

// --- pinceau : chaîne de touches le long d'une direction ---
function brush(x, y, len, ang, th, c, a) {
  const n = max(3, floor(len / 18));
  const r = red(c), g = green(c), b = blue(c);
  noStroke();
  for (let i = 0; i < n; i++) {
    const t = (n === 1) ? 0 : i / (n - 1) - 0.5;
    const px = x + cos(ang) * len * t + random(-2.2, 2.2);
    const py = y + sin(ang) * len * t + random(-2.2, 2.2);
    let f = 1 - abs(t) * 1.45; if (f < 0) f = 0;
    fill(r, g, b, a * (0.3 + 0.7 * f));
    push();
    translate(px, py);
    rotate(ang + random(-0.05, 0.05));
    ellipse(0, 0, th * 1.6, th * (0.55 + 0.45 * f));
    pop();
  }
}

function softDab(x, y, s, c, a) {
  noStroke();
  const r = red(c), g = green(c), b = blue(c);
  fill(r, g, b, a * 0.35); ellipse(x, y, s * 2.1, s * 2.1);
  fill(r, g, b, a);        ellipse(x, y, s, s);
}

function draw() {
  background(10, 11, 17);

  // ---------------- CIEL ----------------
  for (let i = 0; i < 9000; i++) {
    const x = random(-160, W + 160);
    const y = random(-140, HOR + 26);
    const t = constrain(y / HOR, 0, 1);
    let c = lerpColor(color(12, 13, 21), color(47, 51, 63), pow(t, 2.0));
    const dx = (x - GX) / 1020, dy = (y - (HOR + 40)) / 640;
    let gl = constrain(1 - sqrt(dx * dx + dy * dy), 0, 1);
    gl = pow(gl, 2.4);
    c = lerpColor(c, color(198, 182, 153), gl * 0.80);
    const n = noise(x * 0.0011, y * 0.0016);
    c = lerpColor(c, color(6, 7, 12), constrain((0.52 - n) * 1.1, 0, 0.5));
    brush(x, y, random(70, 310), random(-0.09, 0.09), random(10, 36), c, random(5, 19));
  }

  // nuées sombres, longues et basses
  for (let i = 0; i < 1400; i++) {
    const y = random(-80, HOR - 60);
    const x = random(-200, W + 200);
    const band = noise(y * 0.004, 3.7);
    if (band > 0.52) continue;
    const c = lerpColor(color(9, 10, 16), color(30, 32, 42), random());
    brush(x, y, random(260, 760), random(-0.025, 0.025), random(14, 44), c, random(3, 11));
  }

  // cœur de la lueur à l'horizon
  for (let i = 0; i < 2600; i++) {
    const a = random(TWO_PI);
    const rr = pow(random(), 0.55);
    const x = GX + cos(a) * rr * 820;
    const y = HOR + 30 + sin(a) * rr * 330;
    if (y > HOR + 12) continue;
    const f = pow(1 - rr, 2.0);
    const c = lerpColor(color(150, 138, 118), color(226, 212, 184), f);
    brush(x, y, random(60, 220), random(-0.05, 0.05), random(10, 30), c, 3 + f * 16);
  }

  // ---------------- EAU ----------------
  for (let i = 0; i < 8000; i++) {
    const y = HOR + pow(random(), 0.85) * (H - HOR + 12);
    const x = random(-180, W + 180);
    const t = constrain((y - HOR) / (H - HOR), 0, 1);
    let c = lerpColor(color(60, 64, 74), color(6, 7, 12), pow(t, 0.52));
    let rg = constrain(1 - abs(x - GX) / (250 + t * 760), 0, 1) * constrain(1 - t * 1.45, 0, 1);
    rg = pow(rg, 1.8) * noise(x * 0.010, y * 0.022 + 5);
    c = lerpColor(c, color(190, 172, 142), rg * 0.85);
    const n = noise(x * 0.002, y * 0.006 + 9);
    c = lerpColor(c, color(4, 5, 9), constrain((0.5 - n) * 1.0, 0, 0.45));
    brush(x, y, random(120, 540), random(-0.012, 0.012), random(5, 19), c, random(7, 21));
  }

  // éclats brisés du reflet
  for (let i = 0; i < 900; i++) {
    const t = pow(random(), 1.5);
    const y = HOR + 6 + t * 470;
    const x = GX + randomGaussian() * (90 + t * 320);
    const a = (1 - t) * 26 * random(0.2, 1);
    const c = lerpColor(color(120, 112, 98), color(232, 220, 196), random());
    brush(x, y, random(20, 150), 0, random(2, 7), c, a);
  }

  // brume sur la ligne d'horizon
  for (let i = 0; i < 2200; i++) {
    const x = random(-120, W + 120);
    const y = HOR + randomGaussian() * 11;
    const gl = constrain(1 - abs(x - GX) / 900, 0, 1);
    const c = lerpColor(color(46, 48, 56), color(222, 208, 182), pow(gl, 1.6));
    brush(x, y, random(90, 420), 0, random(2, 9), c, random(4, 16) * (0.3 + gl));
  }

  // ---------------- LA BARQUE ----------------
  push();
  translate(BX, HOR - 5);

  // reflet sombre
  noStroke();
  for (let i = 0; i < 260; i++) {
    const t = pow(random(), 1.4);
    const y = 8 + t * 120;
    const x = randomGaussian() * (46 + t * 40);
    fill(5, 6, 10, (1 - t) * 60 * random(0.3, 1));
    ellipse(x, y, random(20, 90), random(2, 6));
  }

  // coque
  fill(5, 5, 9, 242);
  beginShape();
  vertex(-82, -13);
  bezierVertex(-42, 19, 42, 21, 88, -15);
  bezierVertex(42, -1, -40, -2, -82, -13);
  endShape(CLOSE);

  // bords adoucis
  for (let i = 0; i < 420; i++) {
    const u = random(-82, 88);
    const yb = 16 * (1 - pow(u / 85, 2)) + random(-3, 3);
    fill(5, 5, 9, random(20, 90));
    ellipse(u, yb * 0.5 + random(-8, 8), random(6, 20), random(3, 9));
  }

  // mince arête de lumière sur le plat-bord
  for (let i = 0; i < 260; i++) {
    const u = random(-78, 84);
    const yv = -11 + 10 * (1 - pow(u / 82, 2)) * 0.25 + random(-1.2, 1.2);
    fill(214, 198, 170, random(10, 58) * (0.35 + 0.65 * noise(u * 0.02, 12)));
    ellipse(u, yv, random(3, 12), random(1.2, 3));
  }
  pop();

  // ---------------- LA POUSSIÈRE QUI MONTE ----------------
  for (let i = 0; i < 700; i++) {
    const h = pow(random(), 0.9) * 1180;
    const y = HOR - 30 - h;
    const x = BX + h * 0.13 + randomGaussian() * (26 + h * 0.20);
    const a = map(h, 0, 1180, 30, 0, true) * random(0.2, 1);
    softDab(x, y, map(h, 0, 1180, 46, 14) * random(0.6, 1.4), color(196, 186, 168), a * 0.5);
  }
  for (let i = 0; i < 1500; i++) {
    const h = pow(random(), 0.8) * 1200;
    const y = HOR - 26 - h;
    const x = BX + h * 0.13 + randomGaussian() * (24 + h * 0.19);
    const a = map(h, 0, 1200, 72, 0, true) * random(0.25, 1);
    const s = map(h, 0, 1200, 7.5, 1.6) * random(0.5, 1.35);
    softDab(x, y, s, color(244, 234, 214), a);
  }

  // ---------------- GRAIN, TOILE, VIGNETTE ----------------
  loadPixels();
  const cx = W * 0.5, cy = H * 0.47;
  const maxd = sqrt(cx * cx + cy * cy);
  for (let y = 0; y < H; y++) {
    const dy = y - cy;
    const weaveY = sin(y * 2.3);
    for (let x = 0; x < W; x++) {
      const idx = 4 * (y * W + x);
      const dx = x - cx;
      const d = sqrt(dx * dx + dy * dy) / maxd;
      const v = 1 - 0.56 * pow(d, 2.3);
      const g = (random() - 0.5) * 15 + (sin(x * 1.9) + weaveY) * 1.7;
      pixels[idx]     = constrain(pixels[idx]     * v + g, 0, 255);
      pixels[idx + 1] = constrain(pixels[idx + 1] * v + g, 0, 255);
      pixels[idx + 2] = constrain(pixels[idx + 2] * v + g * 0.9, 0, 255);
    }
  }
  updatePixels();
}

// "La barque vide" — p5.js 1.11
let W = 1600, H = 2000, HZ = 1180, SX = 1010;

const SKY = [
  [0.00, [11, 13, 20]],
  [0.30, [24, 29, 41]],
  [0.55, [46, 50, 62]],
  [0.75, [92, 90, 94]],
  [0.90, [168, 148, 118]],
  [1.00, [232, 213, 176]]
];
const WAT = [
  [0.00, [172, 154, 126]],
  [0.05, [92, 92, 96]],
  [0.18, [46, 50, 62]],
  [0.45, [28, 32, 42]],
  [0.75, [18, 21, 28]],
  [1.00, [11, 13, 18]]
];

function setup() {
  createCanvas(W, H);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noStroke();
  ellipseMode(CENTER);

  paintSky();
  paintClouds();
  paintGlow();
  paintShore();
  paintWater();
  paintLightPath();
  paintBoat();
  paintBirds();
  paintReeds();
  finish();

  noLoop();
}

function draw() {}

/* ---------- helpers ---------- */

function grad(stops, t) {
  t = constrain(t, 0, 1);
  for (let i = 0; i < stops.length - 1; i++) {
    if (t >= stops[i][0] && t <= stops[i + 1][0]) {
      let u = map(t, stops[i][0], stops[i + 1][0], 0, 1);
      u = u * u * (3 - 2 * u);
      let a = stops[i][1], b = stops[i + 1][1];
      return [lerp(a[0], b[0], u), lerp(a[1], b[1], u), lerp(a[2], b[2], u)];
    }
  }
  return stops[stops.length - 1][1];
}

function jit3(c, amt) {
  return [c[0] + random(-amt, amt), c[1] + random(-amt, amt), c[2] + random(-amt, amt)];
}

function mix3(a, b, t) {
  return [lerp(a[0], b[0], t), lerp(a[1], b[1], t), lerp(a[2], b[2], t)];
}

// painterly stroke: a chain of soft touches
function brush(x, y, len, ang, w, c, a, j) {
  let n = max(3, floor(len / max(2, w * 0.35)));
  for (let i = 0; i < n; i++) {
    let t = i / (n - 1);
    let px = x + cos(ang) * len * (t - 0.5) + random(-j, j);
    let py = y + sin(ang) * len * (t - 0.5) + random(-j, j);
    let f = pow(sin(t * PI), 0.55);
    let cc = jit3(c, 6);
    fill(cc[0], cc[1], cc[2], a * f * random(0.5, 1));
    ellipse(px, py, w * random(0.75, 1.25), w * random(0.5, 0.9));
  }
}

/* ---------- layers ---------- */

function paintSky() {
  for (let y = 0; y <= HZ + 2; y++) {
    let c = grad(SKY, y / HZ);
    fill(c[0], c[1], c[2]);
    rect(0, y, W, 1);
  }
  for (let i = 0; i < 1700; i++) {
    let y = random(-20, HZ);
    let c = grad(SKY, y / HZ);
    brush(random(-80, W + 80), y, random(140, 520), random(-0.05, 0.05),
          random(12, 44), jit3(c, 14), random(5, 20), 5);
  }
}

function paintClouds() {
  let bands = [[140, 250], [330, 210], [500, 170], [660, 140], [800, 108], [920, 76], [1035, 48]];
  let dark = [28, 32, 44];
  let warm = [205, 176, 132];
  for (let b = 0; b < bands.length; b++) {
    let by = bands[b][0], th = bands[b][1];
    let count = 420;
    for (let i = 0; i < count; i++) {
      let x = random(-140, W + 140);
      let ny = noise(x * 0.0022, b * 12.7) * th;
      let y = by + ny - th * 0.45;
      let lowness = constrain(map(y, 560, HZ, 0, 1), 0, 1);
      let near = constrain(map(abs(x - SX), 120, 820, 1, 0), 0, 1);
      let wm = lowness * near;
      let c = mix3(dark, warm, wm * 0.75);
      c = mix3([16, 19, 28], c, constrain(map(y, 60, 500, 0.45, 1), 0.45, 1));
      brush(x, y, random(110, 460), random(-0.045, 0.045),
            random(12, 38), jit3(c, 10), random(4, 16), 7);
    }
  }
  // faint warm veil just over the horizon
  for (let i = 0; i < 500; i++) {
    let x = SX + randomGaussian() * 420;
    let y = HZ - abs(randomGaussian()) * 150;
    brush(x, y, random(160, 520), random(-0.02, 0.02), random(14, 40),
          [220, 196, 156], random(3, 10), 5);
  }
}

function paintGlow() {
  for (let i = 0; i < 300; i++) {
    let t = i / 299;
    let r = lerp(820, 40, t);
    fill(246, 226, 188, 1.4 + pow(t, 2.2) * 5.5);
    ellipse(SX, HZ - 12, r * 2.3, r * 1.0);
  }
  for (let i = 0; i < 60; i++) {
    let t = i / 59;
    fill(253, 245, 224, 4);
    ellipse(SX, HZ - 8, lerp(330, 60, t), lerp(96, 24, t));
  }
}

function paintShore() {
  for (let x = -10; x < W + 10; x += 4) {
    let h = 5 + noise(x * 0.0035, 77) * 20 + (x < 620 ? 10 * noise(x * 0.001, 9) : 0);
    let gap = constrain(map(abs(x - SX), 70, 430, 0, 1), 0, 1);
    let a = 170 * gap;
    if (a < 2) continue;
    fill(24, 28, 38, a);
    rect(x, HZ - h, 5.5, h + 5);
  }
  for (let i = 0; i < 300; i++) {
    let x = random(-40, W + 40);
    let gap = constrain(map(abs(x - SX), 70, 430, 0, 1), 0, 1);
    if (gap < 0.1) continue;
    brush(x, HZ - random(0, 16), random(40, 180), random(-0.02, 0.02),
          random(5, 14), [30, 34, 45], random(10, 40) * gap, 3);
  }
}

function paintWater() {
  for (let y = HZ; y < H; y++) {
    let c = grad(WAT, (y - HZ) / (H - HZ));
    fill(c[0], c[1], c[2]);
    rect(0, y, W, 1);
  }
  for (let i = 0; i < 2800; i++) {
    let t = pow(random(), 0.7);
    let y = HZ + t * (H - HZ);
    let c = grad(WAT, t);
    brush(random(-120, W + 120), y, random(120, 720) * (0.45 + t),
          random(-0.012, 0.012), random(5, 22), jit3(c, 10), random(7, 24), 2);
  }
}

function paintLightPath() {
  for (let y = HZ + 2; y < H; y += 5) {
    let d = (y - HZ) / (H - HZ);
    let spread = 52 + d * 580;
    for (let k = 0; k < 15; k++) {
      let x = SX + randomGaussian() * spread * 0.55;
      let g = exp(-pow((x - SX) / spread, 2) * 1.7);
      let n = noise(x * 0.009, y * 0.03);
      let a = g * (1 - d * 0.82) * n * n * 85;
      if (a < 1.2) continue;
      brush(x, y + random(-3, 3), random(28, 70 + d * 240), 0,
            random(3, 11) * (0.6 + d), [250, 233, 197], a, 1.6);
    }
  }
  for (let i = 0; i < 140; i++) {
    let y = HZ + abs(randomGaussian()) * 90;
    let x = SX + randomGaussian() * 110;
    brush(x, y, random(20, 110), 0, random(3, 8), [255, 246, 222), 0][0] ? [255,246,222] : [255,246,222], random(20, 70), 1);
  }
}

function paintBoat() {
  let bx = 905, by = 1268;

  // broken reflection under the hull
  for (let i = 0; i < 260; i++) {
    let t = pow(random(), 0.8);
    let y = by + 42 + t * 200;
    let w = random(24, 190) * (1 - t * 0.45);
    let a = (1 - t) * 120 * random(0.35, 1);
    brush(bx + randomGaussian() * 90, y, w, 0, random(4, 15), [13, 15, 21], a, 2);
  }

  let top = (x) => by + 2 - 28 * pow((x - bx) / 172, 2);

  // hull, drawn several times with tiny offsets for a soft edge
  for (let p = 0; p < 4; p++) {
    let ox = random(-2, 2), oy = random(-2, 2);
    fill(8, 10, 14, p === 0 ? 255 : 110);
    beginShape();
    curveVertex(bx - 168 + ox, by - 26 + oy);
    curveVertex(bx - 168 + ox, by - 26 + oy);
    curveVertex(bx - 118 + ox, by - 6 + oy);
    curveVertex(bx - 40 + ox, by + 2 + oy);
    curveVertex(bx + 52 + ox, by + 1 + oy);
    curveVertex(bx + 130 + ox, by - 11 + oy);
    curveVertex(bx + 176 + ox, by - 30 + oy);
    curveVertex(bx + 142 + ox, by + 22 + oy);
    curveVertex(bx + 60 + ox, by + 41 + oy);
    curveVertex(bx - 30 + ox, by + 45 + oy);
    curveVertex(bx - 112 + ox, by + 34 + oy);
    curveVertex(bx - 160 + ox, by + 10 + oy);
    curveVertex(bx - 160 + ox, by + 10 + oy);
    endShape(CLOSE);
  }

  // rim of light along the gunwale
  for (let x = bx - 166; x <= bx + 174; x += 3) {
    let y = top(x);
    fill(252, 236, 202, random(18, 72));
    ellipse(x + random(-1, 1), y - 2 + random(-1, 1), random(3, 7), random(2, 4));
  }

  // the oar, left resting across the boat
  let ox1 = bx - 86, oy1 = by + 4, ox2 = bx + 236, oy2 = by - 62;
  for (let i = 0; i < 90; i++) {
    let t = i / 89;
    let x = lerp(ox1, ox2, t), y = lerp(oy1, oy2, t);
    fill(9, 11, 15, 230);
    ellipse(x, y, lerp(9, 6, t), lerp(9, 6, t));
  }
  push();
  translate(ox2 + 16, oy2 - 4);
  rotate(-0.2);
  fill(8, 10, 14, 240);
  ellipse(0, 0, 70, 22);
  pop();
  for (let i = 0; i < 26; i++) {
    let t = random();
    fill(250, 234, 200, random(10, 40));
    ellipse(lerp(ox1, ox2, t), lerp(oy1, oy2, t) - 4, random(3, 6), random(2, 3));
  }
}

function paintBirds() {
  let n = 8;
  noFill();
  for (let i = 0; i < n; i++) {
    let t = i / (n - 1);
    let x = lerp(440, 110, t) + random(-28, 28);
    let y = lerp(510, 268, t) + random(-36, 36) - sin(t * PI) * 36;
    let s = lerp(18, 4.5, t);
    let a = lerp(135, 42, t);
    stroke(24, 28, 38, a);
    strokeWeight(max(1, s * 0.17));
    push();
    translate(x, y);
    rotate(random(-0.14, 0.14));
    beginShape();
    curveVertex(-s, -s * 0.16);
    curveVertex(-s, -s * 0.16);
    curveVertex(-s * 0.45, s * 0.13);
    curveVertex(0, -s * 0.06);
    curveVertex(s * 0.45, s * 0.13);
    curveVertex(s, -s * 0.16);
    curveVertex(s, -s * 0.16);
    endShape();
    pop();
  }
  noStroke();
}

function blade(x0, y0, h, bend, w, a) {
  let steps = floor(h / 3);
  for (let i = 0; i < steps; i++) {
    let t = i / steps;
    let px = x0 + bend * t * t + random(-1, 1);
    let py = y0 - h * t;
    let s = max(1.2, w * (1 - t) + 1);
    fill(6, 8, 12, a * (0.6 + 0.4 * (1 - t)));
    ellipse(px, py, s, s * 1.4);
  }
  if (random() < 0.5) {
    fill(6, 8, 12, a);
    push();
    translate(x0 + bend, y0 - h);
    rotate(atan2(-h, bend) + HALF_PI);
    ellipse(0, -6, w * 0.9, 24);
    pop();
  }
}

function paintReeds() {
  for (let i = 0; i < 24; i++) {
    blade(random(-40, 380), H + 14, random(150, 450), random(-70, 95),
          random(5, 12), random(150, 235));
  }
  for (let i = 0; i < 9; i++) {
    blade(random(1370, 1660), H + 14, random(90, 250), random(-90, 40),
          random(4, 9), random(110, 190));
  }
  for (let i = 0; i < 260; i++) {
    let y = H - abs(randomGaussian()) * 180;
    brush(random(-100, W + 100), y, random(150, 600), random(-0.01, 0.01),
          random(8, 24), [10, 12, 17], random(8, 26), 2);
  }
}

function finish() {
  loadPixels();
  let nv = 0;
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      let idx = 4 * (y * W + x);
      let nx = (x - W * 0.5) / (W * 0.5);
      let ny = (y - H * 0.52) / (H * 0.5);
      let r2 = nx * nx * 0.95 + ny * ny * 0.8;
      let v = 1 - 0.52 * pow(constrain(r2, 0, 1.4), 1.4);
      if ((x & 1) === 0) nv = (noise(x * 0.03, y * 0.03) - 0.5) * 16;
      let g = nv + random(-7, 7) + sin(x * 0.8) * 1.6 + sin(y * 0.73) * 1.6;
      pixels[idx] = constrain(pixels[idx] * v + g, 0, 255);
      pixels[idx + 1] = constrain(pixels[idx + 1] * v + g, 0, 255);
      pixels[idx + 2] = constrain(pixels[idx + 2] * v + g * 0.95, 0, 255);
    }
  }
  updatePixels();
}

let W = 1600, H = 2000;
const HORIZON = 1402;
const BX0 = 560, BX1 = 1052, BASE = 1506;

const STOPS = [
  [0.00, 236, 228, 210],
  [0.13, 216, 205, 185],
  [0.30, 180, 166, 148],
  [0.46, 134, 120, 108],
  [0.60, 86, 74, 68],
  [0.70, 54, 45, 42],
  [1.00, 16, 13, 13]
];

function setup() {
  createCanvas(W, H);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noStroke();
  noLoop();
}

function draw() {
  paintSky();
  skyBrush();
  mistBands();
  paintGround();
  groundEdge();
  groundBrush();
  column();
  halo();
  shroud();
  ascent();
  finish();
}

function rampCol(t) {
  t = constrain(t, 0, 1);
  for (let i = 0; i < STOPS.length - 1; i++) {
    let a = STOPS[i], b = STOPS[i + 1];
    if (t >= a[0] && t <= b[0]) {
      let u = (t - a[0]) / (b[0] - a[0]);
      u = u * u * (3 - 2 * u);
      return [lerp(a[1], b[1], u), lerp(a[2], b[2], u), lerp(a[3], b[3], u)];
    }
  }
  let L = STOPS[STOPS.length - 1];
  return [L[1], L[2], L[3]];
}

function baseCol(x, y) {
  let c = rampCol(y / H);
  let r = c[0], g = c[1], b = c[2];
  let dx = (x - 790) / 1060, dy = (y - 430) / 740;
  let gl = exp(-(dx * dx + dy * dy) * 1.55);
  r += 64 * gl; g += 56 * gl; b += 40 * gl;
  let ex = (x - 800) / 640, ey = (y - (HORIZON - 50)) / 240;
  let g2 = exp(-(ex * ex + ey * ey) * 1.3);
  r += 42 * g2; g += 32 * g2; b += 21 * g2;
  return [r, g, b];
}

function paintSky() {
  loadPixels();
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      let c = baseCol(x, y);
      let n = (noise(x * 0.0032, y * 0.0032) - 0.5) * 17;
      let i = 4 * (y * W + x);
      pixels[i] = constrain(c[0] + n, 0, 255);
      pixels[i + 1] = constrain(c[1] + n * 0.95, 0, 255);
      pixels[i + 2] = constrain(c[2] + n * 0.85, 0, 255);
      pixels[i + 3] = 255;
    }
  }
  updatePixels();
}

function skyBrush() {
  for (let i = 0; i < 9000; i++) {
    let x = random(-120, W + 120);
    let y = random(-80, HORIZON + 50);
    let c = baseCol(x, y);
    let j = random(-24, 24);
    push();
    translate(x, y);
    rotate((noise(x * 0.0012, y * 0.0012, 10) - 0.5) * 1.5);
    fill(c[0] + j, c[1] + j * 0.95, c[2] + j * 0.85, random(5, 24));
    ellipse(0, 0, random(70, 310), random(5, 17));
    pop();
  }
}

function mistBands() {
  for (let i = 0; i < 90; i++) {
    let y = HORIZON - pow(random(), 1.5) * 560 - random(10, 60);
    let c = baseCol(W / 2, y);
    let up = random() < 0.5 ? 1 : -1;
    fill(c[0] + up * 16, c[1] + up * 14, c[2] + up * 11, random(4, 13));
    ellipse(random(200, W - 200), y, random(500, 1700), random(8, 44));
  }
}

function paintGround() {
  for (let y = HORIZON - 5; y < H; y++) {
    let t = constrain((y - HORIZON) / (H - HORIZON), 0, 1);
    let k = pow(t, 0.45);
    let r = lerp(46, 10, k), g = lerp(38, 9, k), b = lerp(34, 9, k);
    let w = exp(-sq((y - HORIZON) / 170));
    fill(r + 11 * w, g + 8 * w, b + 5 * w);
    rect(0, y, W, 1.2);
  }
}

function groundEdge() {
  for (let i = 0; i < 1400; i++) {
    let x = random(-20, W + 20);
    let hy = HORIZON + (noise(x * 0.004, 7) - 0.5) * 17;
    fill(44, 36, 32, random(50, 140));
    ellipse(x, hy - random(0, 6), random(10, 48), random(2, 7));
    let c = baseCol(x, HORIZON - 8);
    fill(c[0], c[1], c[2], random(25, 85));
    ellipse(x, hy + random(0, 5), random(10, 46), random(2, 6));
  }
}

function groundBrush() {
  for (let i = 0; i < 5200; i++) {
    let y = HORIZON + pow(random(), 0.8) * (H - HORIZON);
    let x = random(-60, W + 60);
    let t = (y - HORIZON) / (H - HORIZON);
    let base = lerp(40, 11, pow(t, 0.45));
    let warm = exp(-sq((y - HORIZON) / 200)) * exp(-sq((x - 800) / 620));
    let j = (noise(x * 0.004, y * 0.006, 21) - 0.5) * 34;
    fill(base + j + 14 * warm, (base + j) * 0.9 + 10 * warm, (base + j) * 0.82 + 6 * warm, random(10, 40));
    push();
    translate(x, y);
    rotate((noise(x * 0.002, y * 0.002, 44) - 0.5) * 0.5);
    ellipse(0, 0, random(60, 340), random(3, 13));
    pop();
  }
}

function column() {
  for (let i = 0; i < 260; i++) {
    let y = random(420, 1430);
    let p = constrain(map(y, 1430, 420, 1, 0), 0, 1);
    fill(206, 192, 164, 2.1 * p);
    ellipse(800 + randomGaussian() * 40, y, random(140, 560), random(90, 300));
  }
}

function halo() {
  for (let i = 0; i < 260; i++) {
    let rw = random(220, 1150);
    fill(126, 108, 84, 2.4);
    ellipse(806, BASE - 18, rw, rw * 0.30);
  }
}

function profile(u) {
  if (u <= 0 || u >= 1) return 0;
  let h = 50 * pow(sin(PI * u), 0.45);
  h += 32 * exp(-sq((u - 0.17) / 0.085));
  h += 13 * exp(-sq((u - 0.80) / 0.065));
  h += 9 * exp(-sq((u - 0.47) / 0.13));
  h *= 1 + (noise(u * 7, 3.3) - 0.5) * 0.10;
  return h;
}

function clothLum(x, y, v) {
  let fold = noise(x * 0.010, y * 0.030, 11);
  return 58 + 150 * pow(v, 0.75) + (fold - 0.5) * 85;
}

function shroud() {
  for (let i = 0; i < 520; i++) {
    let x = random(BX0 - 100, BX1 + 130);
    let u = (x - BX0) / (BX1 - BX0);
    let f = exp(-sq((u - 0.55) / 0.58));
    fill(6, 5, 5, 55 * f);
    ellipse(x, BASE + random(-4, 24), random(70, 230), random(6, 19));
  }

  for (let x = BX0; x <= BX1; x += 1.0) {
    let u = (x - BX0) / (BX1 - BX0);
    let h = profile(u);
    if (h < 1.5) continue;
    let edge = constrain(pow(sin(PI * u), 0.35) * 1.7, 0, 1);
    for (let y = BASE; y > BASE - h; y -= 1.6) {
      let v = (BASE - y) / h;
      let l = clothLum(x, y, v);
      fill(l * 1.04, l * 0.99, l * 0.88, 255 * edge);
      rect(x, y, 1.5, 2.1);
    }
  }

  for (let i = 0; i < 2600; i++) {
    let u = random(0.02, 0.98);
    let h = profile(u);
    if (h < 2) continue;
    let v = pow(random(), 0.8);
    let x = BX0 + u * (BX1 - BX0);
    let y = BASE - h * v;
    let l = clothLum(x, y, v);
    let slope = (profile(u + 0.012) - profile(u - 0.012)) / (0.024 * (BX1 - BX0));
    push();
    translate(x, y);
    rotate(atan(-slope) * (0.3 + 0.7 * v));
    fill(l * 1.05 + random(-14, 14), l * 0.99, l * 0.87, random(18, 62));
    ellipse(0, 0, random(10, 44), random(2, 7));
    pop();
  }

  for (let u = 0.03; u < 0.97; u += 0.0018) {
    let x = BX0 + u * (BX1 - BX0);
    let y = BASE - profile(u);
    let a = 62 * pow(sin(PI * u), 0.5);
    fill(228, 218, 198, a * random(0.35, 1));
    ellipse(x + random(-2, 2), y + random(-1, 2.5), random(3, 10), random(2, 4.5));
  }
}

function ascent() {
  for (let s = 0; s < 200; s++) {
    let u = random(0.08, 0.93);
    let x = BX0 + u * (BX1 - BX0) + randomGaussian() * 7;
    let y = BASE - profile(u) - random(0, 16);
    let sd = random(100);
    let life = random(0.3, 1);
    let vx = randomGaussian() * 0.35;
    for (let k = 0; k < 900; k++) {
      let p = constrain(map(y, 1480, 150, 0, 1), 0, 1);
      let n = noise(x * 0.0016, y * 0.0016, sd * 0.03);
      vx += (n - 0.5) * 0.26 + (800 - x) * 0.000016 * (1 - p);
      vx *= 0.985;
      x += vx * (0.6 + p * 2.4);
      y -= 1.5 + p * 2.6;
      if (y < 150 || x < -60 || x > W + 60) break;
      let a = 44 * pow(1 - p, 1.5) * life;
      if (a < 0.5) continue;
      let c = baseCol(x, y);
      let m = pow(p, 0.65);
      fill(lerp(238, c[0], m), lerp(229, c[1], m), lerp(208, c[2], m), a);
      let r = (1.8 + p * 9) * random(0.6, 1.4);
      ellipse(x, y, r, r * random(0.7, 1.3));
    }
  }
}

function finish() {
  loadPixels();
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      let i = 4 * (y * W + x);
      let dx = (x - W / 2) / (W * 0.64), dy = (y - H * 0.47) / (H * 0.68);
      let d = sqrt(dx * dx + dy * dy);
      let v = 1 - 0.58 * pow(constrain(d - 0.33, 0, 2), 1.5);
      let g = (random() - 0.5) * 15 + (sin(x * 1.93) + sin(y * 2.11)) * 1.9;
      pixels[i] = constrain(pixels[i] * v + g, 0, 255);
      pixels[i + 1] = constrain(pixels[i + 1] * v + g * 0.95, 0, 255);
      pixels[i + 2] = constrain(pixels[i + 2] * v + g * 0.9, 0, 255);
    }
  }
  updatePixels();
}

let W = 1600, H = 2000, HOR = 1600, FIGX = 620;

const STOPS = [
  [0,    [9, 9, 15]],
  [420,  [14, 13, 21]],
  [900,  [27, 23, 29]],
  [1250, [64, 46, 42]],
  [1460, [146, 112, 78]],
  [1570, [232, 204, 154]],
  [1600, [241, 217, 171]],
  [1626, [148, 118, 86]],
  [1720, [62, 48, 40]],
  [1880, [26, 20, 20]],
  [2000, [10, 9, 10]]
];

function setup() {
  createCanvas(W, H);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function ss(a, b, x) {
  let t = constrain((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
}

function bgColorAt(y) {
  y = constrain(y, 0, H);
  for (let i = 0; i < STOPS.length - 1; i++) {
    if (y <= STOPS[i + 1][0]) {
      let t = (y - STOPS[i][0]) / (STOPS[i + 1][0] - STOPS[i][0]);
      t = t * t * (3 - 2 * t);
      let a = STOPS[i][1], b = STOPS[i + 1][1];
      return [lerp(a[0], b[0], t), lerp(a[1], b[1], t), lerp(a[2], b[2], t)];
    }
  }
  return STOPS[STOPS.length - 1][1];
}

function brush(x, y, len, ang, wd, r, g, b, a) {
  let steps = max(3, floor(len / 5));
  for (let i = 0; i < steps; i++) {
    let t = i / (steps - 1);
    let k = sin(t * PI);
    let jx = (noise(x * 0.01 + t * 2.3, y * 0.011) - 0.5) * wd * 1.3;
    let jy = (noise(x * 0.011 + 5.7, y * 0.01 + t * 2.3) - 0.5) * wd * 1.3;
    let px = x + cos(ang) * len * (t - 0.5) + jx;
    let py = y + sin(ang) * len * (t - 0.5) + jy;
    fill(r, g, b, a * (0.3 + 0.7 * k));
    ellipse(px, py, wd * (0.55 + 0.45 * k), wd * (0.45 + 0.4 * k));
  }
}

function limbG(g, x1, y1, x2, y2, w1, w2) {
  let n = 46;
  for (let i = 0; i <= n; i++) {
    let t = i / n;
    g.ellipse(lerp(x1, x2, t), lerp(y1, y2, t), lerp(w1, w2, t), lerp(w1, w2, t));
  }
}

function toneFor(lum) {
  let dark = [20, 15, 15], mid = [176, 120, 66], pale = [246, 234, 208];
  if (lum < 0.55) {
    let t = lum / 0.55;
    return [lerp(dark[0], mid[0], t), lerp(dark[1], mid[1], t), lerp(dark[2], mid[2], t)];
  }
  let t = (lum - 0.55) / 0.45;
  return [lerp(mid[0], pale[0], t), lerp(mid[1], pale[1], t), lerp(mid[2], pale[2], t)];
}

// ---------- layers ----------

