function figureAndAshes() {
  let fw = 360, fh = 560;
  let g = createGraphics(fw, fh);
  g.pixelDensity(1);
  g.background(0);
  g.noStroke();
  g.fill(255);

  // head + neck
  g.ellipse(180, 44, 58, 76);
  g.ellipse(180, 90, 28, 34);
  // torso
  for (let i = 0; i <= 60; i++) {
    let t = i / 60;
    let y = lerp(102, 300, t);
    let w;
    if (t < 0.5) w = lerp(130, 102, t / 0.5);
    else w = lerp(102, 126, (t - 0.5) / 0.5);
    g.ellipse(180, y, w, w * 0.5);
  }
  // arms
  limbG(g, 180 - 58, 114, 180 - 70, 206, 32, 26);
  limbG(g, 180 - 70, 206, 180 - 60, 292, 26, 19);
  limbG(g, 180 + 58, 114, 180 + 72, 208, 32, 26);
  limbG(g, 180 + 72, 208, 180 + 64, 296, 26, 19);
  // legs
  limbG(g, 180 - 28, 286, 180 - 36, 412, 54, 42);
  limbG(g, 180 - 36, 412, 180 - 34, 532, 42, 27);
  limbG(g, 180 + 28, 286, 180 + 38, 414, 54, 42);
  limbG(g, 180 + 38, 414, 180 + 36, 534, 42, 27);
  g.ellipse(180 - 38, 548, 60, 22);
  g.ellipse(180 + 42, 550, 60, 22);

  g.loadPixels();

  // warm halo in the dissolving zone
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 30; i++) {
    fill(210, 150, 90, 3);
    ellipse(FIGX + random(-40, 90), random(1150, 1380), random(260, 760), random(200, 520));
  }
  blendMode(BLEND);

  let ox = FIGX - fw / 2;
  let oy = HOR - fh;
  let N = 190000;
  noStroke();
  for (let i = 0; i < N; i++) {
    let px = random(fw), py = random(fh);
    let idx = 4 * (floor(py) * fw + floor(px));
    if (g.pixels[idx] < 128) continue;

    let t = 1 - py / fh;
    let tn = t + (noise(px * 0.013, py * 0.013) - 0.5) * 0.26;
    let d = ss(0.40, 1.03, tn);
    let fx = ox + px + randomGaussian() * 2.2;
    let fy = oy + py + randomGaussian() * 2.2;
    let freed = random() < d;

    if (freed) {
      if (random() < d * 0.42) continue;
      let s = pow(d, 1.35);
      let a1 = noise(px * 0.009, py * 0.009, 7.1) * TWO_PI * 2;
      fx += randomGaussian() * s * 72 + cos(a1) * s * 46 + s * s * 150;
      fy += -pow(random(), 0.55) * s * 540 - s * 50 + sin(a1) * s * 30;
    }

    let lum = ss(1530, 1080, fy);
    let c = toneFor(lum);
    let a, sz;
    if (freed) {
      a = 170 * (1 - 0.45 * d) * (0.45 + 0.55 * ss(700, 1250, fy));
      sz = random(1.6, 4.4) * (1 - 0.25 * d);
    } else {
      a = 222;
      sz = random(2.3, 5.4);
    }
    fill(c[0] + random(-10, 12), c[1] + random(-10, 10), c[2] + random(-12, 10), a);
    ellipse(fx, fy, sz, sz * random(0.75, 1.25));
  }

  // a few painterly strokes re-knitting the solid body
  for (let i = 0; i < 160; i++) {
    let py = random(0.45, 1.0) * fh;
    let t = 1 - py / fh;
    let hw = 70 * (1 - 0.25 * t);
    let px = 180 + randomGaussian() * hw * 0.55;
    let idx = 4 * (floor(constrain(py, 0, fh - 1)) * fw + floor(constrain(px, 0, fw - 1)));
    if (g.pixels[idx] < 128) continue;
    let lum = ss(1530, 1080, oy + py);
    let c = toneFor(lum);
    brush(ox + px, oy + py, random(20, 90), random(-1.8, -1.3), random(5, 14),
      c[0], c[1], c[2], random(30, 90));
  }
}

function highMotes() {
