function grainAndVignette() {
  loadPixels();
  for (let y = 0; y < H; y++) {
    let dy = (y - H * 0.53) / (H * 0.5);
    for (let x = 0; x < W; x++) {
      let i = 4 * (y * W + x);
      let dx = (x - W * 0.5) / (W * 0.5);
      let r = sqrt(dx * dx * 1.05 + dy * dy * 0.8);
      let v = 1 - 0.62 * pow(constrain(r - 0.33, 0, 2), 1.5);
      let gr = random(-10, 10);
      pixels[i] = constrain(pixels[i] * v + gr, 0, 255);
      pixels[i + 1] = constrain(pixels[i + 1] * v + gr * 0.95, 0, 255);
      pixels[i + 2] = constrain(pixels[i + 2] * v + gr * 0.85, 0, 255);
    }
  }
  updatePixels();
}

let W = 1600, H = 2000;
const CX = 700, HOR = 1680;
let X0 = 460, X1 = 960, Y0 = 460, Y1 = 1710;
let MW, MH, mask, wob;

function setup() {
  createCanvas(W, H);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function draw() {
  background(12, 12, 16);
  drawSky();
  drawGlow();
  drawGround();
  drawShadow();
  buildMask();
  drawFigure();
  drawMotes();
  drawGrain();
  drawVignette();
}

/* ---------- helpers ---------- */
function curveAt(k, t) {
  t = constrain(t, 0, 1);
  for (let i = 0; i < k.length - 1; i++) {
    if (t <= k[i + 1][0]) {
      let u = (t - k[i][0]) / (k[i + 1][0] - k[i][0]);
      u = u * u * (3 - 2 * u);
      return lerp(k[i][1], k[i + 1][1], u);
    }
  }
  return k[k.length - 1][1];
}
function ss(t) { t = constrain(t, 0, 1); return t * t * (3 - 2 * t); }

/* ---------- sky ---------- */
function drawSky() {
  noFill();
  for (let y = 0; y < HOR; y++) {
    let t = y / HOR;
    let r, g, b;
    if (t < 0.52) {
      let u = ss(t / 0.52);
      r = lerp(16, 62, u); g = lerp(20, 61, u); b = lerp(31, 70, u);
    } else {
      let u = ss((t - 0.52) / 0.48);
      r = lerp(62, 231, Math.pow(u, 1.25));
      g = lerp(61, 203, Math.pow(u, 1.45));
      b = lerp(70, 168, Math.pow(u, 1.7));
    }
    let n = noise(y * 0.0045, 5.7);
    let m = 0.90 + 0.21 * n;
    stroke(r * m, g * m, b * m);
    line(0, y, W, y);
  }
  // soft horizontal haze bands
  noStroke();
  for (let i = 0; i < 70; i++) {
    let y = 760 + Math.pow(random(), 1.6) * 880;
    let h = random(10, 60);
    let w = random(500, 1900);
    let x = random(-200, W + 200);
    let a = random(3, 11);
    fill(240, 222, 198, a);
    ellipse(x, y, w, h);
    fill(40, 42, 54, a * 0.6);
    ellipse(x + random(-300, 300), y + random(-30, 30), w * 0.8, h * 0.7);
  }
}

/* ---------- low sun ---------- */
function drawGlow() {
  noStroke();
  let gx = 1125, gy = 1648;
  for (let i = 0; i < 210; i++) {
    let f = i / 210;
    let r = lerp(940, 16, Math.pow(f, 0.8));
    fill(252, 209, 156, 1.5);
    ellipse(gx, gy, r * 2, r * 1.18);
  }
}

/* ---------- ground ---------- */
function drawGround() {
  noFill();
  for (let y = HOR; y < H; y++) {
    let t = (y - HOR) / (H - HOR);
    let u = Math.pow(t, 0.65);
    let r = lerp(138, 24, u), g = lerp(118, 20, u), b = lerp(100, 20, u);
    let n = noise(y * 0.01, 22.3);
    let m = 0.88 + 0.26 * n;
    stroke(r * m, g * m, b * m);
    line(0, y, W, y);
  }
  // earth texture
  noStroke();
  for (let i = 0; i < 26000; i++) {
    let y = HOR + Math.pow(random(), 0.6) * (H - HOR);
    let x = random(-40, W + 40);
    let t = (y - HOR) / (H - HOR);
    let a = random(4, 26) * (1 - t * 0.5);
    if (random() < 0.5) fill(230, 208, 180, a * 0.8);
    else fill(14, 11, 10, a);
    rect(x, y, random(2, 26), 1.2);
  }
}

/* ---------- long shadow ---------- */
function drawShadow() {
  noStroke();
  for (let i = 0; i < 1400; i++) {
    let s = Math.pow(random(), 0.75);
    let x = lerp(CX, 40, s) + random(-18, 18);
    let y = lerp(HOR + 6, 1985, Math.pow(s, 1.35)) + random(-10, 10);
    let w = lerp(78, 240, s);
    let h = lerp(16, 72, s);
    let a = (1 - s) * 16 + 2;
    fill(16, 12, 12, a);
    ellipse(x, y, w, h);
  }
  // contact darkness under the feet
  for (let i = 0; i < 300; i++) {
    let a = random(4, 16);
    fill(12, 9, 9, a);
    ellipse(CX + random(-30, 30), HOR + random(-6, 14), random(60, 230), random(10, 34));
  }
}

/* ---------- figure silhouette ---------- */
function inFig(x, y, w) {
  let dx = x - CX - w;
  let ax = Math.abs(dx);
  // head
  let hx = dx / 56, hy = (y - 598) / 73;
  if (hx * hx + hy * hy <= 1) return true;
  // neck
  if (y > 640 && y < 718 && ax < 25) return true;
  // torso
  if (y >= 700 && y <= 1110) {
    let t = (y - 700) / 410;
    let hw = curveAt([[0, 72], [0.06, 150], [0.17, 145], [0.45, 110], [0.74, 129], [1, 120]], t);
    if (ax < hw) return true;
  }
  // arms
  if (y >= 724 && y <= 1172) {
    let t = (y - 724) / 448;
    let ac = curveAt([[0, 128], [0.4, 142], [0.8, 136], [1, 117]], t);
    let ar = curveAt([[0, 37], [0.5, 27], [0.85, 20], [1, 14]], t);
    if (Math.abs(ax - ac) < ar) return true;
  }
  // legs
  if (y > 1110 && y <= 1692) {
    let t = (y - 1110) / 582;
    let outer = curveAt([[0, 122], [0.3, 89], [0.62, 72], [0.88, 62], [1, 67]], t);
    let inner = curveAt([[0, 11], [0.25, 18], [0.6, 26], [1, 31]], t);
    if (ax < outer && ax > inner) return true;
  }
  // feet
  if (y > 1648 && y < 1694) {
    for (let s = -1; s <= 1; s += 2) {
      let fx = (dx - s * 46) / 41, fy = (y - 1670) / 23;
      if (fx * fx + fy * fy < 1) return true;
    }
  }
  return false;
}

function buildMask() {
  MW = X1 - X0; MH = Y1 - Y0;
  mask = new Uint8Array(MW * MH);
  wob = new Float32Array(MH);
  for (let j = 0; j < MH; j++) {
    let y = Y0 + j;
    wob[j] = (noise(y * 0.0035, 3.1) - 0.5) * 16;
  }
  for (let j = 0; j < MH; j++) {
    let y = Y0 + j, w = wob[j];
    for (let i = 0; i < MW; i++) {
      if (inFig(X0 + i, y, w)) mask[j * MW + i] = 1;
    }
  }
}
function mAt(i, j) {
  if (i < 0 || j < 0 || i >= MW || j >= MH) return 0;
  return mask[j * MW + i];
}

function dissolveAt(y) {
  return constrain(map(y, 1400, 500, 0, 0.97), 0, 0.97);
}

function drawFigure() {
  noStroke();
  for (let j = 0; j < MH; j++) {
    let y = Y0 + j;
    let d = dissolveAt(y);
    for (let i = 0; i < MW; i++) {
      if (!mask[j * MW + i]) continue;
      let x = X0 + i;
      let edge = (!mAt(i - 6, j) || !mAt(i + 6, j) || !mAt(i, j - 6) || !mAt(i, j + 6)) ? 1 : 0;
      let p = constrain(d + edge * 0.24, 0, 1);
      if (random() < p) {
        // a particle that has let go
        let k = Math.pow(random(), 1.7);
        let rise = k * (90 + 1180 * Math.pow(d, 1.15));
        let lat = (noise(x * 0.0016, (y - rise) * 0.0013, 7.3) - 0.5) * rise * 1.55;
        let nx = x + lat + Math.sin(rise * 0.011 + x * 0.013) * 9;
        let ny = y - rise;
        if (ny < -20) continue;
        let f = constrain(rise / 980, 0, 1);
        let r = lerp(24, 236, Math.pow(f, 0.8));
        let g = lerp(20, 216, Math.pow(f, 0.85));
        let b = lerp(19, 190, Math.pow(f, 0.9));
        let a = (135 - 112 * f) * (0.55 + 0.45 * random());
        fill(r, g, b, a);
        rect(nx, ny, 1.5, 1.5);
      } else {
        let v = 1 + random(14);
        fill(16 + v, 13 + v * 0.85, 13 + v * 0.8, 212 + random(40));
        rect(x, y, 1.6, 1.6);
      }
    }
  }
  // a few bright sparks rising
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 900; i++) {
    let y = random(260, 1360);
    let d = dissolveAt(y);
    let x = CX + randomGaussian() * (70 + 320 * d) + 20;
    let a = random(8, 34) * (0.4 + d);
    fill(150, 128, 96, a);
    ellipse(x, y, random(1.5, 4.5), random(1.5, 4.5));
  }
  blendMode(BLEND);
}

/* ---------- drifting dust in the air ---------- */
function drawMotes() {
  noStroke();
  for (let i = 0; i < 38000; i++) {
    let x = random(W), y = random(-10, HOR - 10);
    let col = Math.exp(-Math.pow((x - 740) / 470, 2));
    let hgt = map(y, HOR, 180, 1, 0.22);
    let p = 0.1 + 0.9 * col * hgt;
    if (random() > p * 0.55) continue;
    let bright = random() < 0.62;
    let a = random(5, 30) * (0.4 + 0.6 * hgt);
    if (bright) fill(242, 226, 202, a);
    else fill(20, 18, 22, a * 1.1);
    rect(x, y, random(1, 2.2), random(1, 2.2));
  }
}

/* ---------- surface grain ---------- */
function drawGrain() {
  noStroke();
  for (let i = 0; i < 130000; i++) {
    let x = random(W), y = random(H);
    let a = random(3, 15);
    if (random() < 0.5) fill(255, 250, 240, a * 0.55);
    else fill(0, 0, 0, a);
    rect(x, y, 1, 1);
  }
}

/* ---------- vignette ---------- */
function drawVignette() {
  noFill();
  for (let i = 0; i < 330; i++) {
    let a = 2.0 * Math.pow(1 - i / 330, 1.6);
    stroke(8, 6, 9, a);
    rect(i * 0.5, i * 0.5, W - i, H - i);
  }
  noStroke();
  fill(30, 22, 18, 10);
  rect(0, 0, W, H);
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(1600, 2000);
  noLoop();
  paint();
}

function draw() {}

function paint() {
  const H = 1424; // horizon

  // ---------- SKY GRADIENT ----------
  const stops = [
    [0.00, [8, 10, 26]],
    [0.26, [22, 24, 54]],
    [0.50, [58, 42, 66]],
    [0.72, [128, 72, 70]],
    [0.88, [206, 128, 82]],
    [1.00, [248, 192, 128]]
  ];
  noStroke();
  for (let y = 0; y < H; y++) {
    let t = y / H;
    let c = sampleRamp(stops, t);
    stroke(c[0], c[1], c[2]);
    line(0, y, width, y);
  }

  // ---------- CLOUD BANDS ----------
  noStroke();
  for (let b = 0; b < 9; b++) {
    let by = 180 + b * 140 + random(-40, 40);
    let n = 90;
    for (let i = 0; i < n; i++) {
      let x = random(-200, 1800);
      let yy = by + (noise(x * 0.0012, b * 7.7) - 0.5) * 140;
      let w = random(180, 900);
      let h = random(10, 46) * (1 - b * 0.04);
      let dark = yy > 1000 ? 1 : 0;
      if (dark) fill(70, 36, 34, random(6, 16));
      else fill(16, 14, 34, random(6, 18));
      ellipse(x, yy, w, h);
    }
  }
  // thin bright streaks near horizon
  for (let i = 0; i < 60; i++) {
    let yy = random(H - 260, H - 12);
    let x = random(-100, 1700);
    let w = random(200, 800);
    let h = random(3, 10);
    fill(255, 215, 160, random(8, 26));
    ellipse(x, yy, w, h);
  }

  // ---------- CORONA + BLACK SUN ----------
  const sx = 800, sy = 548, sr = 236;
  blendMode(ADD);
  noFill();
  for (let r = sr; r < sr + 620; r += 2) {
    let d = r - sr;
    let a = 30 * Math.exp(-d / 130) + 6 * Math.exp(-d / 420);
    stroke(255, 206, 158, a);
    strokeWeight(2.4);
    ellipse(sx, sy, r * 2, r * 2);
  }
  // soft rays
  for (let i = 0; i < 160; i++) {
    let ang = random(TWO_PI);
    let len = random(sr + 10, sr + 520);
    stroke(255, 200, 150, random(3, 11));
    strokeWeight(random(1, 4));
    let x1 = sx + cos(ang) * (sr + 6), y1 = sy + sin(ang) * (sr + 6);
    let x2 = sx + cos(ang) * len, y2 = sy + sin(ang) * len;
    line(x1, y1, x2, y2);
  }
  blendMode(BLEND);

  // disc
  noStroke();
  fill(6, 5, 9);
  ellipse(sx, sy, sr * 2, sr * 2);
  noFill();
  stroke(255, 228, 196, 170);
  strokeWeight(2.2);
  ellipse(sx, sy, sr * 2 + 3, sr * 2 + 3);
  noStroke();

  // ---------- GROUND ----------
  // ridge
  fill(24, 18, 20);
  beginShape();
  vertex(-10, height + 10);
  vertex(-10, H);
  for (let x = -10; x <= 1610; x += 8) {
    let y = H - 6 + (noise(x * 0.0024, 11.3) - 0.5) * 26 + (noise(x * 0.011, 3.1) - 0.5) * 7;
    vertex(x, y);
  }
  vertex(1610, height + 10);
  endShape(CLOSE);

  // ground vertical gradient
  for (let y = H - 10; y < height; y++) {
    let t = constrain((y - (H - 10)) / (height - H + 10), 0, 1);
    let c = sampleRamp([
      [0.0, [78, 50, 42]],
      [0.18, [46, 30, 30]],
      [0.55, [24, 17, 19]],
      [1.0, [11, 9, 11]]
    ], t);
    stroke(c[0], c[1], c[2], 215);
    line(0, y, width, y);
  }
  noStroke();

  // ground texture strokes
  for (let i = 0; i < 9000; i++) {
    let t = pow(random(), 1.6);
    let y = lerp(H - 4, height + 20, t);
    let x = random(-20, 1620);
    let w = random(6, 70) * (0.4 + t * 1.6);
    let h = random(0.8, 2.6);
    let lightness = (1 - t) * 90 * random(0.2, 1);
    if (random() < 0.5) fill(60 + lightness, 42 + lightness * 0.8, 38 + lightness * 0.7, random(10, 46));
    else fill(8, 6, 8, random(10, 60));
    push();
    translate(x, y);
    rotate(random(-0.12, 0.12));
    rect(-w / 2, -h / 2, w, h);
    pop();
  }
  // stones
  for (let i = 0; i < 260; i++) {
    let t = pow(random(), 1.3);
    let y = lerp(H + 6, height - 10, t);
    let x = random(0, 1600);
    let s = random(2, 9) * (0.5 + t);
    fill(10, 8, 9, 170);
    ellipse(x, y, s * 1.6, s);
    fill(120, 92, 74, 40 * (1 - t) + 10);
    ellipse(x - s * 0.2, y - s * 0.22, s * 0.9, s * 0.45);
  }

  // ---------- EMBER GLOW AT BASE ----------
  const bx = 782, by = H - 2;
  blendMode(ADD);
  noStroke();
  for (let r = 260; r > 0; r -= 3) {
    let a = 16 * Math.exp(-r / 80);
    fill(255, 120, 40, a);
    ellipse(bx, by, r * 2.2, r * 1.05);
  }
  blendMode(BLEND);

  // ---------- ASH PLUME ----------
  for (let i = 0; i < 6000; i++) {
    let t = pow(random(), 0.78);
    let k = floor(random(6));
    let y = lerp(by + 6, 70, t);
    let spread = 16 + 300 * pow(t, 1.35);
    let drift = (noise(t * 2.1 + k * 0.7, k * 17.3) - 0.5) * 760 * pow(t, 1.45);
    let wob = (noise(t * 9.0, k * 5.1 + 40) - 0.5) * 90 * pow(t, 1.1);
    let x = bx + randomGaussian() * spread * 0.45 + drift + wob;
    if (x < -30 || x > 1630) continue;

    let a = (240 * pow(1 - t, 1.6) + 14) * random(0.25, 1.0);
    let s = (8.0 * pow(1 - t, 1.0) + 1.0) * random(0.35, 1.3);

    let col;
    if (t < 0.16 && random() < 0.55) {
      col = [255, 150 + random(80), 60 + random(50)];
      a *= 1.1;
    } else {
      let lt = constrain(t * 1.25, 0, 1);
      col = [
        lerp(52, 206, lt) + random(-16, 16),
        lerp(44, 198, lt) + random(-16, 16),
        lerp(42, 196, lt) + random(-16, 16)
      ];
    }
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    noStroke();
    fill(col[0], col[1], col[2], a);
    if (random() < 0.7) rect(-s * 0.5, -s * 0.22, s, s * 0.45, s * 0.2);
    else ellipse(0, 0, s, s * 0.7);
    pop();
  }

  // settled ash near base
  for (let i = 0; i < 900; i++) {
    let x = bx + randomGaussian() * 230;
    let y = by + abs(randomGaussian()) * 70 + random(-6, 6);
    if (y > height) continue;
    fill(180, 172, 166, random(10, 70));
    ellipse(x, y, random(1, 4), random(1, 3));
  }

  // ---------- LONE WITNESS ----------
  let fx = 1192, fy = H + 14, fh = 58;
  noStroke();
  fill(6, 5, 7, 70);
  ellipse(fx, fy + 3, fh * 0.52, fh * 0.1);
  fill(8, 6, 9, 240);
  ellipse(fx, fy - fh * 0.9, fh * 0.2, fh * 0.23);
  beginShape();
  vertex(fx - fh * 0.14, fy);
  vertex(fx - fh * 0.115, fy - fh * 0.52);
  vertex(fx - fh * 0.095, fy - fh * 0.80);
  vertex(fx + fh * 0.095, fy - fh * 0.80);
  vertex(fx + fh * 0.115, fy - fh * 0.52);
  vertex(fx + fh * 0.14, fy);
  endShape(CLOSE);

  // ---------- ATMOSPHERIC HAZE OVER HORIZON ----------
  blendMode(ADD);
  noStroke();
  for (let y = H - 120; y < H + 40; y++) {
    let d = abs(y - (H - 20)) / 120;
    let a = 16 * (1 - constrain(d, 0, 1));
    fill(255, 190, 140, a);
    rect(0, y, width, 1);
  }
  blendMode(BLEND);

  // ---------- GRAIN + VIGNETTE ----------
  loadPixels();
  for (let y = 0; y < height; y++) {
    let dy = (y - 980) / 1060;
    for (let x = 0; x < width; x++) {
      let idx = 4 * (x + y * width);
      let dx = (x - 800) / 820;
      let d = Math.sqrt(dx * dx + dy * dy);
      let v = 1 - 0.46 * constrain(d - 0.52, 0, 1.5);
      let g = random(-9, 9);
      pixels[idx] = constrain(pixels[idx] * v + g, 0, 255);
      pixels[idx + 1] = constrain(pixels[idx + 1] * v + g, 0, 255);
      pixels[idx + 2] = constrain(pixels[idx + 2] * v + g, 0, 255);
    }
  }
  updatePixels();
}

function sampleRamp(stops, t) {
  t = constrain(t, 0, 1);
  for (let i = 0; i < stops.length - 1; i++) {
    let a = stops[i], b = stops[i + 1];
    if (t >= a[0] && t <= b[0]) {
      let u = (t - a[0]) / (b[0] - a[0]);
      u = u * u * (3 - 2 * u);
      return [
        lerp(a[1][0], b[1][0], u),
        lerp(a[1][1], b[1][1], u),
        lerp(a[1][2], b[1][2], u)
      ];
    }
  }
  return stops[stops.length - 1][1];
}

