function drawSky() {
  const SK = [
    [0.00, [8, 10, 22]],
    [0.30, [26, 26, 46]],
    [0.55, [60, 48, 66]],
    [0.75, [122, 86, 90]],
    [0.88, [184, 132, 110]],
    [0.96, [224, 178, 138]],
    [1.00, [246, 218, 180]]
  ];
  noFill();
  for (let y = 0; y < HZ; y++) {
    let c = gradCol(SK, y / HZ);
    stroke(c[0], c[1], c[2]);
    line(0, y, W, y);
  }
}

function drawClouds() {
  noStroke();
  // dark drifting bands
  for (let y = 0; y < HZ; y += 4) {
    let fade = 0.35 + 0.65 * (1 - y / HZ) * 1.0;
    for (let x = 0; x < W; x += 8) {
      let n = noise(x * 0.0015, y * 0.011, 3.7);
      let band = noise(y * 0.0045, 11.2);
      let v = n * 0.68 + band * 0.42;
      let a = constrain((v - 0.56) * 320, 0, 1) * 95 * fade;
      if (a > 1) {
        fill(22, 20, 34, a);
        rect(x, y, 9, 5);
      }
    }
  }
  // warm lit edges low in the sky
  for (let y = HZ - 420; y < HZ; y += 4) {
    let f = pow(1 - (HZ - y) / 420, 1.6);
    for (let x = 0; x < W; x += 8) {
      let n = noise(x * 0.0012 + 40, y * 0.013 + 9, 1.3);
      let a = constrain((n - 0.58) * 260, 0, 1) * 55 * f;
      if (a > 1) {
        fill(250, 214, 172, a);
        rect(x, y, 9, 5);
      }
    }
  }
}

function drawGlow() {
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 70; i++) {
    let r = 980 * (1 - i / 70);
    fill(62, 42, 24, 4);
    ellipse(GX, HZ - 20, r * 2.1, r * 1.35);
  }
  for (let i = 0; i < 30; i++) {
    let r = 260 * (1 - i / 30);
    fill(70, 54, 34, 5);
    ellipse(GX, HZ - 28, r * 2.0, r * 1.1);
  }
  pop();
}

function drawWater() {
  const WT = [
    [0.00, [150, 124, 110]],
    [0.12, [104, 86, 84]],
    [0.35, [52, 46, 54]],
    [0.65, [26, 24, 32]],
    [1.00, [8, 9, 15]]
  ];
  for (let y = HZ; y < H; y++) {
    let d = (y - HZ) / (H - HZ);
    let c = gradCol(WT, pow(d, 0.62));
    stroke(c[0], c[1], c[2]);
    line(0, y, W, y);
  }
}

function drawHaze() {
  noFill();
  for (let y = HZ - 170; y < HZ + 110; y++) {
    let a = exp(-pow((y - HZ) / 72, 2)) * 78;
    let side = 0.55 + 0.45 * exp(-pow((GX - 800) / 1400, 2));
    stroke(238, 212, 180, a * side);
    line(0, y, W, y);
  }
}

function drawLightPath() {
  for (let y = HZ + 2; y < H; y += 3) {
    let d = (y - HZ) / (H - HZ);
    let halfw = 70 + d * 660;
    let baseA = pow(1 - d, 1.9) * 185;
    let n = 18 + floor(d * 26);
    for (let i = 0; i < n; i++) {
      let u = randomGaussian(0, 0.46);
      if (abs(u) > 1.5) continue;
      let x = GX + u * halfw;
      let len = 12 + random(55 + d * 190);
      let a = baseA * exp(-u * u * 1.5) * random(0.15, 1.0);
      if (a < 1) continue;
      stroke(255, 228, 192, a);
      strokeWeight(random(1, 2.8));
      line(x - len / 2, y, x + len / 2, y);
    }
  }
  strokeWeight(1);
}

function drawWaterStreaks() {
  for (let i = 0; i < 1400; i++) {
    let d = pow(random(), 1.8);
    let y = HZ + 4 + d * (H - HZ - 6);
    let len = 60 + random(520) * (0.4 + d);
    let x = random(-100, W + 100);
    let dark = random() < 0.55;
    let a = random(6, 34) * (0.5 + 0.8 * (1 - d));
    if (dark) stroke(6, 8, 14, a);
    else stroke(206, 178, 156, a * 0.7);
    strokeWeight(random(1, 3.2));
    line(x, y, x + len, y);
  }
  strokeWeight(1);
}

