function drawVignette() {
  noStroke();
  for (let y = 0; y < H; y += 10) {
    for (let x = 0; x < W; x += 10) {
      let dx = (x + 5 - W * 0.52) / (W * 0.66);
      let dy = (y + 5 - H * 0.50) / (H * 0.68);
      let r = sqrt(dx * dx + dy * dy);
      let a = constrain((r - 0.50) * 160, 0, 118) + random(-3, 3);
