/* ---------- helpers ---------- */

function glowAdd(x, y, r, c, a, steps) {
  blendMode(ADD);
  noStroke();
  for (let i = steps; i > 0; i--) {
    let t = i / steps;
    fill(red(c), green(c), blue(c), a * pow(1 - t, 2.2));
    ellipse(x, y, r * t * 2, r * t * 2);
  }
  blendMode(BLEND);
}

function waxCol(nd, y, extra) {
  let sh = pow(max(0, cos(nd * 1.42)), 0.55);
  let dir = constrain(0.80 - 0.60 * nd, 0, 1.4);
  let b = 0.06 + 0.98 * sh * dir + extra;
  let fy = map(y, candTop, candBot, 1.05, 0.46);
  b *= fy;
  b *= 0.93 + 0.14 * noise(nd * 7 + 3, y * 0.02);
  let warm = constrain(1 - (y - candTop) / 110, 0, 1);
  warm = warm * warm;
  let c = lerpColor(color(24, 22, 24), color(238, 229, 208), constrain(b, 0, 1));
  c = lerpColor(c, color(255, 176, 110), warm * 0.33 * constrain(b * 1.4, 0, 1));
  let rim = pow(constrain((nd - 0.70) / 0.30, 0, 1), 2);
  c = lerpColor(c, color(132, 146, 170), rim * 0.40);
  return c;
}

/* ---------- background ---------- */

function bgWash() {
  noStroke();
  for (let y = 0; y < H; y += 2) {
    let t = y / H;
    let c = lerpColor(color(20, 22, 30), color(27, 21, 18), pow(t, 1.2));
    fill(c);
    rect(0, y, W, 2.5);
  }
  for (let i = 0; i < 3500; i++) {
    let x = random(-120, W + 120), y = random(-120, H + 120);
    let n = noise(x * 0.0012, y * 0.0012);
    let r = random(40, 430);
    let b = (n - 0.5) * 30;
    fill(28 + b, 27 + b * 0.9, 33 + b * 0.8, random(2, 6));
    ellipse(x, y, r, r * random(0.6, 1.4));
  }
  glowAdd(430, 620, 780, color(56, 72, 102), 11, 44);
  glowAdd(1200, 1260, 640, color(52, 46, 62), 7, 36);
}

function tablePlane() {
  noStroke();
  for (let y = edgeY; y < H; y += 2) {
    let t = (y - edgeY) / (H - edgeY);
    let c = lerpColor(color(36, 30, 27), color(9, 8, 9), pow(t, 0.55));
    fill(c);
    rect(0, y, W, 2.5);
  }
  for (let i = 0; i < 40; i++) {
    fill(96, 86, 78, 2.2);
    rect(0, edgeY + i * 0.7, W, 1.4);
  }
  for (let i = 0; i < 1000; i++) {
    let y = edgeY + pow(random(), 1.3) * (H - edgeY);
    let x = random(-200, W);
    let len = random(60, 460);
    stroke(255, 238, 216, random(1, 5) * map(y, edgeY, H, 1, 0.12));
    strokeWeight(random(1, 3));
    line(x, y, x + len, y + random(-1, 1));
  }
  noStroke();
}

function baseShadow() {
  noStroke();
  for (let i = 0; i < 60; i++) {
    let t = i / 60;
    fill(4, 4, 6, 9 * (1 - t));
    ellipse(cx + 60 * t + 20, candBot - 2, 330 * (1 - 0.5 * t), 46 * (1 - 0.5 * t));
  }
}

function reflection() {
  noStroke();
  for (let i = 0; i < 130; i++) {
    let t = i / 130;
    fill(214, 200, 178, 7.5 * (1 - t) * (1 - t));
    ellipse(cx + 8, candBot + 6 + t * 120, 150 * (1 - 0.35 * t), 28);
  }
}

/* ---------- candle ---------- */

function candleBody() {
  noStroke();
  for (let y = candTop; y <= candBot; y += 2) {
    let wl = (noise(y * 0.011, 5) - 0.5) * 8;
    let wr = (noise(y * 0.011, 55) - 0.5) * 8;
    let l = cx - halfW + wl, r = cx + halfW + wr;
    for (let x = l; x <= r; x += 2) {
      let nd = (x - cx) / halfW;
      fill(waxCol(nd, y, 0));
      rect(x, y, 2.4, 2.4);
    }
  }
}

function candleDrips() {
  let drips = [
    [-0.88, 1646, 104, 16], [-0.62, 1622, 56, 11], [-0.30, 1614, 34, 9],
    [0.74, 1638, 128, 18], [0.46, 1612, 44, 10], [0.92, 1700, 62, 13]
  ];
  noStroke();
  for (let d of drips) {
    let bx = cx + d[0] * halfW;
    let steps = 26;
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let y = d[1] + t * d[2];
      let w = d[3] * (1 - 0.45 * t) * (0.55 + 0.45 * sin(PI * min(1, t * 2.4)));
      let x = bx + (noise(d[1] * 0.01 + t * 2, 9) - 0.5) * 6;
      let nd = (x - cx) / halfW;
      fill(waxCol(nd * 0.85, y, 0.14));
      ellipse(x, y, w * 2, w * 2.1);
    }
  }
}

function candleTopSurface() {
  noStroke();
  push();
  translate(cx, candTop);
  for (let i = 0; i < 26; i++) {
    let t = i / 26;
    fill(lerpColor(color(224, 214, 194), color(168, 154, 136), t));
    ellipse(0, 0, halfW * 2 * (1 - t * 0.06), 36 * (1 - t * 0.06));
  }
  for (let i = 0; i < 22; i++) {
    let t = i / 22;
    fill(lerpColor(color(150, 134, 116), color(74, 62, 54), t), 230);
    ellipse(2, 4, 96 * (1 - t * 0.9), 22 * (1 - t * 0.9));
  }
  noFill();
  for (let i = 0; i < 14; i++) {
    stroke(246, 238, 220, 14);
    strokeWeight(2 + i * 0.4);
    arc(0, -1, halfW * 2 - 4, 34, PI * 1.05, PI * 1.85);
  }
  noStroke();
  pop();
  glowAdd(cx + 4, candTop + 2, 86, color(255, 128, 48), 16, 26);
}

function wick() {
  noFill();
  let pts = [
    [cx - 5, candTop + 14], [cx - 3, candTop + 4], [cx + 2, candTop - 16],
    [cx + 9, candTop - 33], [cx + 17, candTop - 44]
  ];
  stroke(16, 14, 14);
  strokeWeight(7);
  beginShape();
  curveVertex(pts[0][0], pts[0][1]);
  for (let p of pts) curveVertex(p[0], p[1]);
  curveVertex(pts[4][0], pts[4][1]);
  endShape();
  stroke(74, 66, 60, 110);
  strokeWeight(2.2);
  beginShape();
  curveVertex(pts[0][0] - 1.5, pts[0][1]);
  for (let p of pts) curveVertex(p[0] - 1.5, p[1]);
  curveVertex(pts[4][0] - 1.5, pts[4][1]);
  endShape();
  noStroke();
}

function emberGlow() {
  glowAdd(wickX, wickY, 150, color(255, 116, 36), 20, 34);
  glowAdd(wickX, wickY, 34, color(255, 164, 78), 34, 16);
  glowAdd(wickX, wickY, 9, color(255, 212, 158), 70, 8);
}

/* ---------- smoke ---------- */

function smoke() {
  const sx = wickX + 1, sy = wickY - 6, topY = 120;
  for (let s = 0; s < 780; s++) {
    let seed = random(9000);
    let x0 = sx + randomGaussian() * 2.2;
    let amp = random(8, 55);
    let freq = random(0.005, 0.016);
    let ph = random(TWO_PI);
    let endT = constrain(randomGaussian() * 0.22 + 0.72, 0.12, 1);
    let drift = randomGaussian() * 0.22;
    let wob = random(0.5, 1.6);
    let a0 = random(4, 13);
    let px = x0, py = sy;
    for (let y = sy; y > topY; y -= 5) {
      let t = (sy - y) / (sy - topY);
      if (t > endT) break;
      let sp = pow(t, 1.45);
      let nx = noise(seed, y * 0.0033) - 0.5;
      let x = x0 + sin(y * freq + ph) * amp * sp * wob + nx * 680 * sp + drift * (sy - y) * sp;
      let f = pow(1 - t / endT, 0.75);
      let a = a0 * f * (1 - 0.35 * t);
      let c = lerpColor(color(228, 208, 182), color(124, 138, 160), constrain(t * 1.5, 0, 1));
      stroke(red(c), green(c), blue(c), a);
      strokeWeight(0.9 + 9 * sp);
      line(px, py, x, y);
      px = x; py = y;
    }
  }
  for (let s = 0; s < 220; s++) {
    let seed = random(9000);
    let x0 = sx + randomGaussian() * 1.4;
    let endT = random(0.05, 0.26);
    let ph = random(TWO_PI);
    let px = x0, py = sy;
    for (let y = sy; y > topY; y -= 4) {
      let t = (sy - y) / (sy - topY);
      if (t > endT) break;
      let sp = pow(t, 1.3);
      let x = x0 + sin(y * 0.02 + ph) * 16 * sp + (noise(seed, y * 0.004) - 0.5) * 120 * sp;
      let a = random(8, 20) * pow(1 - t / endT, 0.6);
      stroke(236, 222, 200, a);
      strokeWeight(0.8 + 3.4 * sp);
      line(px, py, x, y);
      px = x; py = y;
    }
  }
  noStroke();
}

function motes() {
  const sy = wickY - 6, topY = 120;
  noStroke();
  for (let i = 0; i < 950; i++) {
    let t = pow(random(), 0.7);
    let y = sy - (sy - topY) * t;
    let x = cx + 17 + randomGaussian() * (26 + 340 * pow(t, 1.3));
    let a = random(8, 62) * (1 - t * 0.7);
    fill(238, 228, 208, a);
    ellipse(x, y, random(1, 3.2));
  }
}

/* ---------- finishing ---------- */

function vignette() {
  noFill();
  for (let i = 0; i < 300; i++) {
    stroke(5, 5, 8, 2.0);
    strokeWeight(7);
    ellipse(W / 2, H / 2 + 60, W * 2.05 - i * 5.0, H * 2.25 - i * 5.6);
  }
  noStroke();
}

function grain() {
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let n = (random() - 0.5) * 12;
    pixels[i] += n;
    pixels[i + 1] += n;
    pixels[i + 2] += n;
  }
  updatePixels();
}

const W = 1600, H = 2000;
const HOR = 1700, CX = 790, YTOP = 490, YFOOT = 1705;

function setup() {
  createCanvas(W, H);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function halfWidth(y) {
  if (y < YTOP || y > YFOOT) return 0;
  const headC = 585, headRy = 95, headRx = 70;
  const headBot = 640, neck = 695, shoulder = 780, waist = 1085, hip = 1180;
  let w;
  if (y < headBot) {
    let u = (y - headC) / headRy;
    u = constrain(u, -1, 1);
    w = headRx * sqrt(max(0, 1 - u * u));
  } else if (y < neck) {
    let t = (y - headBot) / (neck - headBot);
    w = lerp(57, 36, t);
  } else if (y < shoulder) {
    let t = (y - neck) / (shoulder - neck);
    t = t * t * (3 - 2 * t);
    w = lerp(36, 170, t);
  } else if (y < waist) {
    let t = (y - shoulder) / (waist - shoulder);
    w = lerp(170, 118, t);
  } else if (y < hip) {
    let t = (y - waist) / (hip - waist);
    w = lerp(118, 144, t);
  } else {
    let t = (y - hip) / (YFOOT - hip);
    w = lerp(144, 218, pow(t, 1.25));
  }
  return w;
}

function sky() {
  for (let y = 0; y < H; y++) {
    let c;
    if (y < HOR) {
      let t = y / HOR;
      if (t < 0.5) c = lerpColor(color(7, 9, 16), color(20, 24, 36), t / 0.5);
      else if (t < 0.88) c = lerpColor(color(20, 24, 36), color(46, 44, 51), (t - 0.5) / 0.38);
      else c = lerpColor(color(46, 44, 51), color(86, 70, 58), (t - 0.88) / 0.12);
    } else {
      let t = (y - HOR) / (H - HOR);
      c = lerpColor(color(36, 30, 29), color(9, 9, 12), pow(t, 0.6));
    }
    stroke(c);
    strokeWeight(1);
    line(0, y, W, y);
  }
}

function clouds() {
  noStroke();
  for (let i = 0; i < 1600; i++) {
    let x = random(-250, W + 250);
    let y = random(120, 1560);
    let n = noise(x * 0.0012, y * 0.0030);
    let a = map(n, 0, 1, 0, 17);
    if (y > 1350) a *= map(y, 1350, 1560, 1, 0.25);
    fill(13, 15, 25, a);
    ellipse(x, y, random(240, 760), random(36, 110));
  }
  for (let i = 0; i < 500; i++) {
    let x = random(-200, W + 200);
    let y = random(1280, 1690);
    let n = noise(x * 0.0018, y * 0.004);
    fill(92, 78, 66, map(n, 0, 1, 0, 11));
    ellipse(x, y, random(300, 820), random(22, 60));
  }
}

function stars() {
  for (let i = 0; i < 620; i++) {
    let x = random(W);
    let y = random(0, 1350);
    let a = random(6, 58) * map(y, 0, 1350, 1, 0.15);
    stroke(222, 224, 232, a);
    strokeWeight(random(1, 2.3));
    point(x, y);
  }
}

function horizonGlow() {
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 70; i++) {
    let f = i / 70;
    fill(42, 30, 20, 3);
    ellipse(810, HOR + 6, 2700 - f * 2050, 430 - f * 350);
  }
  blendMode(BLEND);
}

function ground() {
  for (let i = 0; i < 6500; i++) {
    let y = random(HOR, H);
    let t = (y - HOR) / (H - HOR);
    let x = random(-100, W);
    let len = random(18, 150) * (0.35 + t * 1.6);
    if (random() < 0.5) stroke(72, 62, 54, 11 * (1 - t * 0.6));
    else stroke(4, 5, 8, 20);
    strokeWeight(random(1, 3.2));
    line(x, y, x + len, y + random(-1.2, 1.2));
  }
  noStroke();
  for (let i = 0; i < 900; i++) {
    let x = random(W), y = random(HOR, H);
    fill(2, 3, 5, random(6, 22));
    ellipse(x, y, random(30, 180), random(6, 22));
  }
}

function shadowPool() {
  noStroke();
  for (let i = 0; i < 46; i++) {
    fill(3, 4, 6, 11);
    ellipse(CX + 8, 1742 + i * 1.8, 640 - i * 9, 132 - i * 2.2);
  }
  for (let i = 0; i < 26; i++) {
    fill(2, 2, 4, 14);
    ellipse(CX + 4, 1716 + i * 1.2, 330 - i * 7, 60 - i * 1.4);
  }
}

function figure() {
  strokeCap(ROUND);
  for (let i = 0; i < 300000; i++) {
    let y = random(YTOP, YFOOT);
    let w = halfWidth(y);
    if (w <= 0.5) continue;
    let xr = random(-1.06, 1.06);
    let x = CX + xr * w;
    let t = (y - YTOP) / (YFOOT - YTOP);

    let d = constrain(map(t, 0.0, 0.44, -0.18, 1.0), 0, 1);
    d = d * d * (3 - 2 * d);

    let e = 1 - pow(constrain(abs(x - CX) / w, 0, 1.4), 3.2);
    let n = (noise(x * 0.005, y * 0.005) + noise(x * 0.016, y * 0.016) * 0.55) / 1.55;
    let p = d * e * (0.40 + 0.85 * n);
    if (random() > p) continue;

    let c = lerpColor(color(30, 32, 40), color(10, 11, 15), constrain(t * 1.35, 0, 1));
    let r = red(c), g = green(c), b = blue(c);

    let fold = noise(x * 0.013, y * 0.0035);
    let fv = (fold - 0.5) * 26;
    r += fv; g += fv; b += fv * 1.1;

    let rim = (x - CX) / w;
    if (rim < -0.70) { r += 24; g += 28; b += 36; }
    if (rim > 0.80) { r += 14; g += 10; b += 6; }

    let halo = (1 - d) * 42;
    r += halo * 1.0; g += halo * 0.95; b += halo * 0.85;

    if (y > 1600) { let k = (y - 1600) / 105; r -= 6 * k; g -= 6 * k; b -= 6 * k; }

    stroke(constrain(r, 0, 255), constrain(g, 0, 255), constrain(b, 0, 255), random(140, 255));
    strokeWeight(random(1, 2.7));
    point(x, y);
  }
}

function motes() {
  blendMode(ADD);
  strokeCap(ROUND);
  for (let i = 0; i < 75000; i++) {
    let t0 = pow(random(), 1.7);
    let y0 = lerp(YTOP - 10, 1340, t0);
    let w0 = halfWidth(max(y0, YTOP + 1));
    if (w0 <= 0.5) continue;
    let x0 = CX + random(-1.2, 1.2) * w0;

    let rise = pow(random(), 2.1) * (820 * (1 - t0 * 0.55) + 90);
    let a = noise(x0 * 0.0022, y0 * 0.0022) * TWO_PI * 2.2;
    let dx = cos(a) * rise * 0.38 + rise * 0.10 + random(-18, 18);
    let x = x0 + dx;
    let y = y0 - rise + random(-10, 10);
    if (y < -20 || x < -40 || x > W + 40) continue;

    let fade = map(rise, 0, 900, 1, 0.04);
    fade = constrain(fade, 0, 1);
    let al = random(3, 34) * fade;

    let c;
    let roll = random();
    if (roll < 0.70) c = color(232, 224, 204);
    else if (roll < 0.94) c = color(170, 186, 208);
    else c = color(206, 132, 72);

    stroke(red(c), green(c), blue(c), al);
    strokeWeight(random(0.9, 2.4));
    point(x, y);
  }

  // a few brighter sparks near the dissolving head
  for (let i = 0; i < 1400; i++) {
    let y = random(300, 760);
    let x = CX + random(-260, 300) * (1 + (760 - y) / 900);
    let al = random(6, 60) * map(y, 300, 760, 0.25, 1);
    stroke(240, 232, 212, al);
    strokeWeight(random(1, 2.8));
    point(x, y);
  }
  blendMode(BLEND);
}

function finish() {
  loadPixels();
  for (let y = 0; y < H; y++) {
    let dy = (y - 980) / 1000;
    for (let x = 0; x < W; x++) {
      let idx = 4 * (y * W + x);
      let dx = (x - 800) / 800;
      let d = sqrt(dx * dx + dy * dy) / 1.414;
      let v = 1 - 0.64 * pow(d, 2.1);
      let g = random(-9, 9);
      pixels[idx] = constrain(pixels[idx] * v + g * 1.05, 0, 255);
      pixels[idx + 1] = constrain(pixels[idx + 1] * v + g, 0, 255);
      pixels[idx + 2] = constrain(pixels[idx + 2] * v + g * 0.92, 0, 255);
    }
  }
  updatePixels();
}

function draw() {
  noStroke();
  sky();
  clouds();
  stars();
  horizonGlow();
  ground();
  shadowPool();
  figure();
  motes();
  finish();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  background(5, 5, 10);

  // Upper warm realm - life
  for (let y = 0; y < 800; y++) {
    for (let x = 0; x < width; x += 3) {
      let n = noise(x * 0.003, y * 0.003);
      let r = map(n, 0, 1, 180, 255);
      let g = map(n, 0, 1, 80, 180);
      let b = map(n, 0, 1, 20, 100);
      let a = map(y, 0, 800, 200, 50);
      stroke(r, g, b, a);
      point(x, y);
    }
  }

  // Transitional gradient
  for (let y = 800; y < 1200; y++) {
    for (let x = 0; x < width; x += 2) {
      let progress = (y - 800) / 400;
      let n = noise(x * 0.004, y * 0.004);
      let r = map(progress, 0, 1, 180, 20) * n;
      let g = map(progress, 0, 1, 100, 10) * n;
      let b = map(progress, 0, 1, 60, 15) * n;
      let a = map(progress, 0, 1, 150, 30);
      stroke(r, g, b, a);
      point(x, y);
    }
  }

  // The figure - dissolving human form
  push();
  translate(800, 900);

  // Body particles dissolving upward
  for (let i = 0; i < 800; i++) {
    let angle = random(TWO_PI);
    let radius = randomGaussian(0, 60);
    let x = cos(angle) * radius;
    let y = sin(angle) * radius - random(0, 400);

    let drift = noise(i * 0.1) * 100 - 50;
    x += drift;

    letDistFromCenter = dist(x, y, 0, -100);
    let size = map(DistFromCenter, 0, 400, 4, 0.5);

    let alpha = map(y, 0, -400, 180, 0);

    if (y > -100) {
      fill(200, 100, 50, alpha);
    } else {
      let fade = map(y, -100, -400, 1, 0);
      fill(200 * fade, 100 * fade, 50 * fade, alpha * fade);
    }

    noStroke();
    ellipse(x, y, size, size);
  }

  // Core silhouette
  fill(80, 40, 20, 160);
  noStroke();
  ellipse(0, -180, 80, 90); // head
  ellipse(0, -80, 90, 160); // torso
  ellipse(-25, -40, 45, 120); // left arm
  ellipse(25, -40, 45, 120); // right arm
  ellipse(-20, 50, 50, 100); // left leg
  ellipse(20, 50, 50, 100); // right leg

  pop();

  // Ethereal wisps rising
  for (let i = 0; i < 50; i++) {
    let x = 800 + randomGaussian(0, 150);
    let startY = random(600, 1000);
    let endY = startY - random(300, 600);

    noFill();
    for (let a = 0; a < 255; a += 15) {
      let progress = a / 255;
      let y = lerp(startY, endY, progress);
      let xOffset = sin(progress * PI * 3) * 30;
      let alpha = map(progress, 0, 1, 80, 0);
      stroke(220, 150, 80, alpha);
      strokeWeight(2);
      point(x + xOffset, y);
    }
  }

  // Void below - consuming darkness
  for (let y = 1200; y < height; y++) {
    for (let x = 0; x < width; x += 5) {
      let n = noise(x * 0.005, y * 0.005);
      let darkness = map(y, 1200, height, 20, 5);
      stroke(darkness * n, darkness * n * 0.5, darkness * n, 50);
      point(x, y);
    }
  }

  // Scattered light particles fading into void
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = random(1000, height);
    let brightness = map(y, 1000, height, 100, 0);
    let size = random(1, 3);
    fill(brightness, brightness * 0.7, brightness * 0.5, random(50, 150));
    noStroke();
    ellipse(x, y, size, size);
  }
}

