function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  background(15, 12, 20);

  // Draw atmospheric gradient background
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(15, 180, pow(t, 2));
    let g = lerp(12, 160, pow(t, 2.5));
    let b = lerp(20, 140, pow(t, 1.8));
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Add light rays from above
  for (let i = 0; i < 50; i++) {
    let x = random(width);
    let alpha = random(5, 20);
    stroke(255, 250, 200, alpha);
    strokeWeight(random(1, 4));
    let startY = height * 0.3;
    let endY = height * random(0.6, 0.9);
    line(x, startY, x + random(-100, 100), endY);
  }

  // Draw the figure - lower body still solid
  let figureX = width / 2;
  let figureBottom = height * 0.75;
  let figureTop = height * 0.25;

  // Solid lower portion (legs and lower torso)
  fill(30, 25, 35);
  noStroke();

  // Legs
  let legWidth = 40;
  rect(figureX - 60, figureBottom - 300, legWidth, 300);
  rect(figureX + 20, figureBottom - 300, legWidth, 300);

  // Lower torso
  beginShape();
  vertex(figureX - 70, figureBottom - 300);
  vertex(figureX + 70, figureBottom - 300);
  vertex(figureX + 60, figureBottom - 450);
  vertex(figureX - 60, figureBottom - 450);
  endShape(CLOSE);

  // Mid torso - starting to fragment
  for (let y = figureBottom - 450; y > figureBottom - 650; y -= 3) {
    let progress = map(y, figureBottom - 450, figureBottom - 650, 0, 1);
    let scatter = progress * 60;

    for (let x = -50; x < 50; x += 4) {
      let xOffset = random(-scatter, scatter);
      let alpha = map(progress, 0, 1, 255, 100);
      fill(30 + progress * 60, 25 + progress * 80, 35 + progress * 90, alpha);

      let size = random(2, 6) * (1 - progress * 0.5);
      rect(figureX + x + xOffset, y, size, 3);
    }
  }

  // Upper body dissolving into particles
  for (let i = 0; i < 8000; i++) {
    let angle = random(TWO_PI);
    let distance = randomGaussian(0, 80);

    let baseY = figureBottom - 650 - random(500);
    let progress = map(baseY, figureBottom - 650, figureTop, 0, 1);
    progress = constrain(progress, 0, 1);

    let x = figureX + cos(angle) * distance * (1 + progress * 3);
    let y = baseY + random(-progress * 100, progress * 50);

    // Particles rise and scatter more as they go up
    let noiseVal = noise(x * 0.01, y * 0.01);
    x += (noiseVal - 0.5) * 200 * progress;
    y -= progress * random(100);

    let particleSize = random(1, 4) * (1 - progress * 0.7);

    // Color shift from dark to luminous
    let r = lerp(30, 255, progress);
    let g = lerp(25, 240, progress);
    let b = lerp(35, 200, progress);
    let alpha = lerp(200, 255, progress) * random(0.3, 1);

    fill(r, g, b, alpha);
    noStroke();
    circle(x, y, particleSize);
  }

  // Arms reaching up, fragmenting
  for (let side = -1; side <= 1; side += 2) {
    for (let i = 0; i < 100; i++) {
      let t = i / 100;
      let armY = figureBottom - 550 - t * 400;
      let armX = figureX + side * (60 + t * 100);

      let scatter = t * 150;
      let numParticles = 20;

      for (let j = 0; j < numParticles; j++) {
        let px = armX + random(-scatter, scatter);
        let py = armY + random(-20, 20);

