function drawBodyFragment(x, y, w, h, numFragments, gap, rotation, opacity) {
  push();
  translate(x, y);
  rotate(rotation);

  let fragmentHeight = h / numFragments;

  for (let i = 0; i < numFragments; i++) {
    let yPos = i * (fragmentHeight + gap);
    let offsetX = noise(i * 0.5, y * 0.01) * 20 - 10;
    let fragmentW = w + noise(i * 0.3) * 20 - 10;

    // Distance-based color shift
    let totalY = y + yPos;
    let colorShift = map(totalY, -200, 1000, 0, 1);
    colorShift = constrain(colorShift, 0, 1);

    let r = lerp(140, 220, colorShift);
    let g = lerp(130, 190, colorShift);
    let b = lerp(120, 160, colorShift);

    fill(r, g, b, opacity * 255 * (1 - colorShift * 0.5));
    stroke(r + 40, g + 40, b + 30, opacity * 180);
    strokeWeight(1);

    rect(offsetX, yPos, fragmentW, fragmentHeight - gap);
  }

  pop();
}

