function drawDissolvingFigure() {
  // Upper part - more solid human form
  let figurePoints = [];
  let centerX = 800;
  let startY = 300;

  // Generate figure outline (simplified human silhouette)
  for (let angle = 0; angle < TWO_PI; angle += 0.02) {
    let r;
    // Create rough human shape
    if (angle < PI * 0.3 || angle > PI * 1.7) {
      // Head
      r = 80 + sin(angle * 8) * 5;
    } else if (angle < PI * 0.7 || angle > PI * 1.3) {
      // Shoulders/arms
      r = 180 + sin(angle * 4) * 20;
    } else {
      // Body
      r = 120 + sin(angle * 6) * 15;
    }

    let x = centerX + cos(angle) * r;
    let y = startY + sin(angle) * r * 1.4;
    figurePoints.push({x: x, y: y, angle: angle});
  }

  // Draw figure with vertical gradient of dissolution
  for (let y = 200; y < 1400; y += 2) {
    let dissolveFactor = map(y, 200, 1400, 0, 1);
    dissolveFactor = pow(dissolveFactor, 1.5);

    let alpha = map(y, 200, 1200, 180, 0);
    alpha = constrain(alpha, 0, 180);

    // Figure color - pale flesh transitioning to ethereal blue
    let r = lerp(220, 180, dissolveFactor);
    let g = lerp(200, 190, dissolveFactor);
    let b = lerp(180, 220, dissolveFactor);

    stroke(r, g, b, alpha);
    strokeWeight(1 + dissolveFactor * 2);

    // Draw scanlines across figure with increasing noise
    let scanY = y;
    for (let x = centerX - 200; x < centerX + 200; x += 3) {
      let distFromCenter = abs(x - centerX);
      let figureWidth = map(scanY, 200, 1000, 150, 100) * (1 - dissolveFactor * 0.5);

      if (distFromCenter < figureWidth) {
        let noiseVal = noise(x * 0.01, scanY * 0.01) * dissolveFactor * 100;
        let offsetX = (random() - 0.5) * dissolveFactor * 60;
        let offsetY = (random() - 0.5) * dissolveFactor * 20;

        if (random() > dissolveFactor * 0.7) {
          point(x + offsetX + noiseVal, scanY + offsetY);
        }
      }
    }
  }

  // Draw more solid upper portion
  for (let y = 200; y < 700; y += 1) {
    let progress = map(y, 200, 700, 0, 1);
    stroke(220, 200, 180, 160 * (1 - progress * 0.5));
    strokeWeight(2);

    let width = map(y, 200, 700, 80, 150);
    for (let x = centerX - width; x < centerX + width; x += 2) {
      let distFromCenter = abs(x - centerX) / width;
      if (distFromCenter < 1 - progress * 0.3) {
        let noiseOffset = noise(x * 0.02, y * 0.02) * 10;
        point(x + noiseOffset, y);
      }
    }
  }
}

function drawVoid() {
  // Deep void at bottom
  for (let y = 1300; y < 2000; y += 1) {
    let alpha = map(y, 1300, 2000, 0, 200);
    stroke(0, 0, 0, alpha);
    strokeWeight(2);
    line(0, y, 1600, y);
  }

  // Swirling darkness
  for (let i = 0; i < 300; i++) {
    let x = random(1600);
    let y = random(1200, 2000);
    let size = random(20, 100);

    noFill();
    stroke(5, 8, 15, random(30, 80));
    strokeWeight(random(1, 3));

    beginShape();
    for (let angle = 0; angle < TWO_PI; angle += 0.2) {
      let r = size + noise(x * 0.01, y * 0.01, angle) * 30;
      let px = x + cos(angle) * r;
      let py = y + sin(angle) * r * 0.6;
      vertex(px, py);
    }
    endShape(CLOSE);
  }
}

function drawParticles() {
  // Particles falling/rising from figure
  for (let i = 0; i < 3000; i++) {
    let sourceY = random(400, 1200);
    let dissolveFactor = map(sourceY, 400, 1200, 0, 1);

    let x = 800 + randomGaussian() * (100 + dissolveFactor * 200);
    let y = sourceY + randomGaussian() * 300 * dissolveFactor;

    let size = random(1, 4) * (1 + dissolveFactor);

    // Color shift from flesh tones to deep blues/purples
    let r = lerp(200, 100, dissolveFactor);
    let g = lerp(180, 100, dissolveFactor);
    let b = lerp(170, 130, dissolveFactor);
    let alpha = random(50, 150) * (1 - dissolveFactor * 0.3);

    noStroke();
    fill(r, g, b, alpha);
    circle(x, y, size);

    // Trailing particles
    if (random() < 0.3) {
      let trailLength = random(10, 50);
      stroke(r, g, b, alpha * 0.3);
      strokeWeight(0.5);
      line(x, y, x + random(-10, 10), y + trailLength);
    }
  }

  // Dust motes in the void
  for (let i = 0; i < 500; i++) {
    let x = random(1600);
    let y = random(1100, 2000);
    let alpha = random(20, 100);

    noStroke();
    fill(150, 160, 180, alpha);
    circle(x, y, random(0.5, 2));
  }
}

