function drawDissolvingForm() {
  let centerX = width / 2;
  let startY = 800;

  // Create a humanoid silhouette that dissolves upward
  for (let layer = 0; layer < 150; layer++) {
    let progress = layer / 150;
    let y = startY - layer * 8;

    // Figure becomes more dispersed as it rises
    let dispersal = pow(progress, 1.5) * 400;
    let opacity = (1 - pow(progress, 0.8)) * 180;

    // Body width that narrows and fragments
    let baseWidth = 200 * (1 - progress * 0.3);

    for (let i = 0; i < 100; i++) {
      let angle = map(i, 0, 100, -PI, PI);
      let r = baseWidth * abs(sin(angle * 0.5));

      // Add noise-based displacement
      let noiseVal = noise(i * 0.1, layer * 0.05);
      let displacement = dispersal * noiseVal;

      let x = centerX + cos(angle) * r + randomGaussian(0, displacement);
      let yPos = y + randomGaussian(0, dispersal * 0.5);

      // Color transitions from warm (life) to cool (void)
      let r_col = map(progress, 0, 1, 180, 60);
      let g_col = map(progress, 0, 1, 140, 80);
      let b_col = map(progress, 0, 1, 120, 150);

      let size = map(progress, 0, 1, 3, 0.5);

      noStroke();
      fill(r_col, g_col, b_col, opacity * (1 - noiseVal * 0.5));
      circle(x, yPos, size);
    }
  }

  // Solid lower form (still cohesive)
  fill(140, 100, 90, 200);
  noStroke();

  // Draw legs and lower body
  beginShape();
  for (let angle = 0; angle < PI; angle += 0.1) {
    let r = 180 * sin(angle);
    let x = centerX + cos(angle - PI/2) * r;
    let y = startY + sin(angle) * 100 + 100;
    vertex(x, y);
  }
  endShape(CLOSE);

  // Torso
  ellipse(centerX, startY - 100, 280, 400);
  ellipse(centerX, startY - 300, 220, 280);

  // Head - beginning to fragment
  for (let i = 0; i < 200; i++) {
    let angle = random(TWO_PI);
    let r = randomGaussian(80, 15);
    let x = centerX + cos(angle) * r;
    let y = startY - 500 + sin(angle) * r;

    fill(160, 120, 110, random(100, 200));
    circle(x, y, random(2, 6));
  }
}

function drawParticleField() {
  // Dispersed particles throughout the upper canvas
  for (let i = 0; i < 3000; i++) {
    let x = randomGaussian(width / 2, width / 3);
    let y = random(0, 1000);

    // Density increases toward top (complete dispersal)
    let densityFactor = 1 - y / 1000;
    if (random() > densityFactor * 0.7) continue;

    let size = random(0.5, 2.5);
    let alpha = random(30, 150) * densityFactor;

    // Colors shift to cosmic blues and purples
    let hueShift = map(y, 0, 1000, 0, 1);
    let r_col = 60 + hueShift * 100;
    let g_col = 80 + hueShift * 60;
    let b_col = 150 + hueShift * 50;

    noStroke();
    fill(r_col, g_col, b_col, alpha);
    circle(x, y, size);
  }
}

function drawEnergyWaves() {
  // Subtle flowing waves suggesting transformation
  noFill();

  for (let wave = 0; wave < 30; wave++) {
    let yBase = map(wave, 0, 30, 400, 1200);

    stroke(100, 120, 180, 20);
    strokeWeight(1 + wave * 0.1);

    beginShape();
    for (let x = 0; x < width; x += 10) {
      let y = yBase + sin(x * 0.01 + wave * 0.5) * 50 * noise(x * 0.01, wave * 0.1);
      vertex(x, y);
    }
    endShape();
  }

  // Radial emanation from the dissolving point
  for (let i = 0; i < 50; i++) {
    let angle = map(i, 0, 50, 0, TWO_PI);
    let x1 = width / 2;
    let y1 = 300;
    let length = random(200, 600);
    let x2 = x1 + cos(angle) * length;
    let y2 = y1 + sin(angle) * length;

    stroke(80, 100, 140, random(5, 20));
    strokeWeight(random(0.5, 1.5));
    line(x1, y1, x2, y2);
  }
}

