    let progress = (y - startY) / 600;
    let figureWidth = 180 - progress * 60;

    for (let x = centerX - figureWidth; x < centerX + figureWidth; x += 2) {
      let distFromCenter = abs(x - centerX) / figureWidth;
      let alpha = (1 - distFromCenter) * (1 - progress * 0.3) * 255;

      let noiseVal = noise(x * 0.01, y * 0.01);
      let r = 60 + noiseVal * 40;
      let g = 50 + noiseVal * 30;
      let b = 55 + noiseVal * 35;

      stroke(r, g, b, alpha);
      strokeWeight(2);
      point(x, y);
    }
  }

  // Draw the dissolving middle section
  for (let y = 800; y < startY; y += 2) {
    let progress = (y - 800) / 400;
    let figureWidth = 200 - (1 - progress) * 80;
    let dissolveFactor = 1 - progress;

    for (let x = centerX - figureWidth; x < centerX + figureWidth; x += 1) {
      if (random(1) > dissolveFactor * 0.7) {
        let distFromCenter = abs(x - centerX) / figureWidth;
        let alpha = (1 - distFromCenter) * dissolveFactor * 200;

        let noiseVal = noise(x * 0.008, y * 0.008);
        let r = 65 + noiseVal * 50;
        let g = 55 + noiseVal * 40;
        let b = 60 + noiseVal * 45;

        stroke(r, g, b, alpha);
        strokeWeight(random(1, 3));
        point(x, y);
      }
    }
  }

  // Draw the head region dissolving
  for (let i = 0; i < 8000; i++) {
    let angle = random(TWO_PI);
    let radius = random(0, 150);
    let x = centerX + cos(angle) * radius;
    let y = 650 + sin(angle) * radius * 0.8;

    let distFromCenter = radius / 150;
    let alpha = (1 - distFromCenter) * random(100, 200);

    let noiseVal = noise(x * 0.01, y * 0.01);
    let r = 70 + noiseVal * 60;
    let g = 60 + noiseVal * 50;
    let b = 65 + noiseVal * 55;

    stroke(r, g, b, alpha);
    strokeWeight(random(1, 2.5));
    point(x, y);
  }

  // Draw particles dispersing upward
  for (let i = 0; i < 15000; i++) {
    let x = centerX + randomGaussian(0, 300);
    let y = random(100, 800);

    let distFromCenter = abs(x - centerX) / 400;
    let heightFactor = y / 800;

    let dispersal = (1 - heightFactor) * 0.8;
    if (random(1) < dispersal) continue;

    let size = random(0.5, 3) * heightFactor;
    let alpha = random(30, 150) * heightFactor * (1 - distFromCenter);

    let noiseVal = noise(x * 0.005, y * 0.005, i * 0.001);
    let r = 80 + noiseVal * 70;
    let g = 70 + noiseVal * 60;
    let b = 75 + noiseVal * 65;

    // Add drift
    x += noise(i * 0.1) * 100 - 50;

    stroke(r, g, b, alpha);
    strokeWeight(size);
    point(x, y);
  }

  // Add smaller particles in upper regions
  for (let i = 0; i < 8000; i++) {
    let x = random(200, 1400);
    let y = random(50, 600);

    let heightFactor = y / 600;
    let alpha = random(10, 80) * heightFactor;

    let noiseVal = noise(x * 0.003, y * 0.003);
    let r = 90 + noiseVal * 80;
    let g = 80 + noiseVal * 70;
    let b = 85 + noiseVal * 75;

    stroke(r, g, b, alpha);
    strokeWeight(random(0.5, 1.5));
    point(x, y);
  }

  // Add energy wisps
  for (let i = 0; i < 50; i++) {
    let startX = centerX + randomGaussian(0, 100);
    let startY = random(400, 1000);

    drawWisp(startX, startY, random(-0.5, 0.5));
  }
}

function drawWisp(startX, startY, drift) {
  let x = startX;
  let y = startY;

  for (let i = 0; i < 100; i++) {
    let progress = i / 100;
    let alpha = (1 - progress) * random(50, 120);

    let noiseVal = noise(x * 0.01, y * 0.01, i * 0.1);
    let r = 100 + noiseVal * 100;
    let g = 85 + noiseVal * 85;
    let b = 90 + noiseVal * 90;

    stroke(r, g, b, alpha);
    strokeWeight(random(0.5, 2));
    point(x, y);

    y -= random(3, 8);
    x += drift * 2 + noise(i * 0.1) * 4 - 2;
  }
}

function drawAtmosphere() {
  // Add subtle gradient layers
  for (let i = 0; i < 3000; i++) {
    let x = random(width);
    let y = random(height);

    let alpha = random(1, 8);

