    let y = 700 + sin(angle) * radius * 0.7;

    let alpha = (1 - radius / 600) * random(2, 10);

    stroke(140, 130, 135, alpha);
    strokeWeight(random(5, 20));
    point(x, y);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  background(25, 25, 30);

  // Create atmospheric gradient background
  for (let y = 0; y < height; y++) {
