function drawDissolvingFigure() {
  push();
  translate(width / 2, height * 0.4);

  // Draw figure as collection of particles that increase in chaos toward edges
  for (let i = 0; i < 15000; i++) {
    let angle = random(TWO_PI);
    let r = randomGaussian(0, 80);
    let x = r * cos(angle);
    let y = r * sin(angle) * 1.8; // Elongated form

    // Distance from center determines dissolution
    let distFromCenter = dist(x, y, 0, 0);
    let dissolutionFactor = distFromCenter / 200;

    // Add noise-based displacement that increases with distance
    let noiseScale = 0.01;
    let displacement = noise(x * noiseScale, y * noiseScale) * dissolutionFactor * 150;

    x += cos(angle) * displacement;
    y += sin(angle) * displacement;

    // Opacity decreases with dissolution
    let alpha = map(dissolutionFactor, 0, 2, 180, 0);
    alpha = constrain(alpha, 0, 180);

    // Color shifts from warm (life) to cool (void)
    let r = map(dissolutionFactor, 0, 2, 150, 80);
    let g = map(dissolutionFactor, 0, 2, 120, 90);
    let b = map(dissolutionFactor, 0, 2, 100, 120);

    noStroke();
    fill(r, g, b, alpha);
    circle(x, y, random(1, 3));
  }
  pop();
}

function drawThreshold() {
  push();
  // Horizontal threshold around middle
  let thresholdY = height * 0.5;

  for (let x = 0; x < width; x += 2) {
    let noiseVal = noise(x * 0.003, thresholdY * 0.001);
    let y = thresholdY + (noiseVal - 0.5) * 60;

    // Glowing line
    for (let j = 0; j < 8; j++) {
      let alpha = map(j, 0, 8, 100, 0);
      let weight = map(j, 0, 8, 1, 10);
      stroke(200, 180, 220, alpha);
      strokeWeight(weight);
      point(x, y);
    }
  }
  pop();
}

function drawFlowingParticles() {
  push();
  // Particles representing the continuous flow of matter
  for (let i = 0; i < 3000; i++) {
    let x = random(width);
    let y = random(height);

    // Create flow field
    let flowAngle = noise(x * 0.004, y * 0.004) * TWO_PI * 2;
    let flowStrength = noise(x * 0.002 + 100, y * 0.002 + 100) * 50;

    let dx = cos(flowAngle) * flowStrength;
    let dy = sin(flowAngle) * flowStrength;

    // Particles are traces
    let alpha = random(20, 80);
    noFill();

    // Bluish particles above threshold, reddish below
    if (y < height * 0.5) {
      stroke(100, 120, 180, alpha);
    } else {
      stroke(140, 100, 120, alpha);
    }

    strokeWeight(random(0.5, 1.5));

    for (let step = 0; step < 20; step++) {
      let px = x + dx * step * 0.1;
      let py = y + dy * step * 0.1;
      point(px, py);
    }
  }
  pop();
}

function drawWisps() {
  push();
  // Ethereal wisps crossing the threshold
  for (let i = 0; i < 50; i++) {
    let startX = random(width);
    let startY = random(height * 0.3, height * 0.7);

    noFill();
    beginShape();
    for (let t = 0; t < 100; t++) {
      let x = startX + noise(t * 0.1, i * 0.5) * 400 - 200;
      let y = startY + t * 5;

      let alpha = map(t, 0, 100, 60, 0);
      stroke(180, 170, 200, alpha);
      strokeWeight(map(t, 0, 100, 3, 0.5));

      if (t > 0) {
        vertex(x, y);
      }
    }
    endShape();
  }

  // Add soft organic shapes suggesting dissolution
  for (let i = 0; i < 100; i++) {
    let x = random(width);
    let y = random(height);
    let size = random(5, 40);

    let alpha = random(5, 25);
    noStroke();
    fill(150, 140, 160, alpha);

    beginShape();
    for (let angle = 0; angle < TWO_PI; angle += 0.3) {
      let r = size + noise(angle * 2, i) * size * 0.5;
      let px = x + cos(angle) * r;
      let py = y + sin(angle) * r;
      vertex(px, py);
    }
    endShape(CLOSE);
  }
  pop();
}

