    let alpha_val = map(dissolution, 0, 1, 180, 0);

    fill(r_col, g_col, b_col, alpha_val);
    noStroke();
    ellipse(x, y, 40 * (1 - dissolution * 0.7), 40 * (1 - dissolution * 0.7));
  }
