    let r_col = 150 * warmth + 40 * (1 - warmth);
    let g_col = 80 * warmth + 50 * (1 - warmth);
    let b_col = 40 * warmth + 70 * (1 - warmth);

    let alpha_val = map(y, 400, 1600, 120, 10);

    fill(r_col, g_col, b_col, alpha_val);
    noStroke();
    ellipse(x, y, size, size * 1.3);
