      let warmth = map(y, 1200, 0, 0, 1);
      let r_col = 180 * warmth + 30;
      let g_col = 90 * warmth + 40;
      let b_col = 50 * warmth + 60;

      let alpha_val = map(j, 0, 40, 60, 0);
      stroke(r_col, g_col, b_col, alpha_val);
      strokeWeight(3 - j * 0.05);

      if (j > 0) {
        vertex(x, y);
      }
