  let centerX = width / 2;
  let startY = 600;

  // Dessiner la silhouette humaine qui se dissout
  drawDissolvingFigure(centerX, startY);

  // Particules qui s'échappent
  drawParticles(centerX, startY);

  // Lueur subtile en haut
  drawGlow(centerX, 300);
}

function drawDissolvingFigure(x, y) {
  push();
  translate(x, y);

  // Parties du corps avec différents niveaux de dissolution
  for (let section = 0; section < 10; section++) {
    let yOffset = section * 80;
    let dissolveAmount = map(section, 0, 10, 0, 1);

    // Tête et corps supérieur plus solides
    if (section < 2) {
      drawBodySection(0, yOffset, 150, 80, dissolveAmount * 0.3);
    } else if (section < 5) {
      drawBodySection(0, yOffset, 140, 80, dissolveAmount * 0.6);
    } else {
      drawBodySection(0, yOffset, 130, 80, dissolveAmount);
    }
  }

  // Tête
  drawHead(0, -100);

  pop();
}

function drawHead(x, y) {
  push();
  translate(x, y);

  // Crâne avec texture
  for (let i = 0; i < 100; i++) {
    let angle = random(TWO_PI);
    let r = random(40, 60);
    let px = cos(angle) * r;
    let py = sin(angle) * r;

    let alpha = map(r, 40, 60, 80, 20);
    stroke(60, 80, 100, alpha);
    strokeWeight(random(1, 3));
    point(px, py);
  }

  // Contour de la tête
  noFill();
  stroke(70, 90, 110, 100);
  strokeWeight(2);
  ellipse(0, 0, 120, 140);

  // Yeux vides
  fill(20, 25, 35);
  noStroke();
  ellipse(-25, -10, 20, 25);
  ellipse(25, -10, 20, 25);

  pop();
}

function drawBodySection(x, y, w, h, dissolve) {
  push();
  translate(x, y);

  // Nombre de particules selon la dissolution
  let particles = int(map(dissolve, 0, 1, 500, 100));

  for (let i = 0; i < particles; i++) {
    let px = random(-w/2, w/2);
    let py = random(0, h);

    // Dispersion horizontale selon dissolution
    let scatter = dissolve * 200;
    px += randomGaussian(0, scatter);
    py += randomGaussian(0, scatter * 0.5);

    // Couleur bleu-gris froid
    let baseAlpha = map(dissolve, 0, 1, 120, 10);
    let alpha = baseAlpha * random(0.5, 1);

    // Variation de couleur
    let r = 50 + random(-20, 20);
    let g = 70 + random(-20, 20);
    let b = 95 + random(-10, 30);

    stroke(r, g, b, alpha);
    strokeWeight(random(0.5, 2.5));
    point(px, py);

    // Quelques traits pour suggérer le mouvement
    if (random() < 0.1 && dissolve > 0.3) {
      let len = random(5, 15);
      let angle = random(-PI/4, PI/4);
      line(px, py, px + cos(angle) * len, py + sin(angle) * len);
    }
  }

  pop();
}

function drawParticles(x, y) {
  // Particules qui s'envolent vers le haut
  for (let i = 0; i < 800; i++) {
    let px = x + randomGaussian(0, 150);
    let py = random(y - 200, y + 800);

    // Mouvement ascendant
    let drift = noise(px * 0.01, py * 0.01) * 100 - 50;
    px += drift;

    // Taille et opacité
    let size = random(0.5, 3);
    let alpha = random(10, 80);

    // Couleur froide
    let r = random(40, 80);
    let g = random(60, 100);
    let b = random(80, 130);

    stroke(r, g, b, alpha);
    strokeWeight(size);
    point(px, py);

    // Quelques particules avec traînée
    if (random() < 0.15) {
      let trailLen = random(10, 40);
      stroke(r, g, b, alpha * 0.3);
      strokeWeight(size * 0.5);
      line(px, py, px + random(-5, 5), py + trailLen);
    }
  }
}

function drawGlow(x, y) {
  // Lueur mystérieuse en haut
  push();

  for (let i = 0; i < 200; i++) {
    let angle = random(TWO_PI);
    let radius = randomGaussian(0, 100);
    let px = x + cos(angle) * radius;
    let py = y + sin(angle) * radius * 0.5;

    let alpha = map(abs(radius), 0, 200, 25, 0);
    stroke(140, 160, 200, alpha);
    strokeWeight(random(1, 2));
    point(px, py);
  }

  pop();
}

