function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  background(5, 8, 15);

  // Gradient de fond - du profond au moins profond
  for(let y = 0; y < height; y++) {
    let inter = y / height;
    let c = lerpColor(
      color(5, 8, 15),
      color(15, 20, 35),
      inter
    );
    stroke(c);
    line(0, y, width, y);
  }

  // Silhouette humaine qui se dissout
  push();
  translate(width/2, height/2 + 200);

  // Corps principal - forme humaine
  let bodyPoints = [];
  let numPoints = 200;

  // Créer contour humain simplifié
  for(let i = 0; i < numPoints; i++) {
    let angle = map(i, 0, numPoints, 0, TWO_PI);
    let r;

    // Forme approximative d'un corps humain
    if(angle < PI * 0.2 || angle > PI * 1.8) {
      // Tête
      r = 80 + sin(angle * 8) * 5;
    } else if(angle < PI * 0.6) {
      // Épaule et bras droit
      r = 120 + cos(angle * 3) * 40;
    } else if(angle < PI * 1.4) {
      // Corps et bras gauche
      r = 110 + sin(angle * 2) * 35;
    } else {
      // Retour vers tête
      r = 100 + cos(angle * 4) * 30;
    }

    let x = cos(angle) * r;
    let y = sin(angle) * r * 1.4 - 50;
    bodyPoints.push({x: x, y: y, angle: angle});
  }

  // Dessiner la dissolution en couches
  for(let layer = 0; layer < 150; layer++) {
    let dissolution = layer / 150;

    for(let pt of bodyPoints) {
      let noiseVal = noise(pt.x * 0.01, pt.y * 0.01, layer * 0.1);

      if(noiseVal > 0.3 - dissolution * 0.3) {
        let alpha = map(dissolution, 0, 1, 180, 0);
        let scatter = dissolution * 100;

        let x = pt.x + randomGaussian(0, scatter);
        let y = pt.y + randomGaussian(0, scatter) - dissolution * 400;

        // Transition couleur: chair -> bleu froid
        let r = lerp(60, 20, dissolution);
        let g = lerp(40, 30, dissolution);
        let b = lerp(35, 60, dissolution);

        fill(r, g, b, alpha * noiseVal);
        noStroke();

        let size = random(1, 4) * (1 - dissolution * 0.5);
        circle(x, y, size);
      }
    }
  }
  pop();

  // Particules flottantes - âmes ou cendres
  for(let i = 0; i < 800; i++) {
    let x = random(width);
    let y = random(height);

    let noiseVal = noise(x * 0.002, y * 0.002);

    if(noiseVal > 0.6) {
      let alpha = map(noiseVal, 0.6, 1, 10, 80);
      let size = random(0.5, 2.5);

      fill(180, 190, 220, alpha);
      noStroke();
      circle(x, y, size);
    }
  }

  // Voile de brume descendant
  for(let i = 0; i < 1000; i++) {
    let x = random(width);
    let y = random(height * 0.6);

    let n = noise(x * 0.003, y * 0.003);
    if(n > 0.4) {
      fill(10, 15, 25, 20);
      noStroke();
      ellipse(x, y, random(30, 80), random(10, 30));
    }
  }

  // Zone de lumière mourante en bas
  push();
  translate(width/2, height - 300);

  for(let i = 0; i < 300; i++) {
    let angle = random(TWO_PI);
    let radius = randomGaussian(0, 150);
    let x = cos(angle) * radius;
    let y = sin(angle) * radius * 0.3;

    let r = 80 + random(-20, 20);
    let g = 50 + random(-20, 20);
    let b = 20 + random(-10, 10);
    let alpha = 30 / (1 + abs(radius) * 0.01);

    fill(r, g, b, alpha);
    noStroke();
    circle(x, y, random(2, 8));
  }
  pop();

  // Texture atmosphérique
  for(let i = 0; i < 3000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.01, y * 0.01);

    stroke(255, n * 5);
    point(x, y);
  }
}

