    let y = 150 + randomGaussian(0, 100);
    let size = random(2, 8);
    let alpha = random(30, 150);
    noStroke();
    fill(180, 200, 220, alpha);
    ellipse(x, y, size, size);
  }

  // Silhouette humaine qui se dissout
  push();
  translate(width / 2, height * 0.6);

  // Corps principal - partie inférieure solide
  fill(25, 30, 45, 200);
  noStroke();

  // Jambes
  beginShape();
  vertex(-60, 300);
  vertex(-40, 100);
  vertex(-20, 0);
  vertex(20, 0);
  vertex(40, 100);
  vertex(60, 300);
  vertex(40, 300);
  vertex(30, 120);
  vertex(10, 20);
  vertex(-10, 20);
  vertex(-30, 120);
  vertex(-40, 300);
  endShape(CLOSE);

  // Torse
  beginShape();
  vertex(-70, 0);
  vertex(-60, -150);
  vertex(-50, -200);
  vertex(50, -200);
  vertex(60, -150);
  vertex(70, 0);
  vertex(40, 0);
  vertex(40, -180);
  vertex(-40, -180);
  vertex(-40, 0);
  endShape(CLOSE);

  // Bras
  beginShape();
  vertex(-50, -180);
  vertex(-80, -120);
  vertex(-100, -50);
  vertex(-90, -40);
  vertex(-70, -110);
  vertex(-45, -170);
  endShape(CLOSE);

  beginShape();
  vertex(50, -180);
  vertex(80, -120);
  vertex(100, -50);
  vertex(90, -40);
  vertex(70, -110);
  vertex(45, -170);
  endShape(CLOSE);

  // Tête - commence à se dissoudre
  fill(30, 35, 50, 180);
  ellipse(0, -250, 120, 140);

  // Particules de dissolution - partie supérieure du corps
  for (let i = 0; i < 800; i++) {
    let angle = random(TWO_PI);
    let r = randomGaussian(0, 50);
    let x = r * cos(angle);
    let y = -250 + r * sin(angle) - random(0, 400);

    let distFromCenter = dist(x, y, 0, -250);
    let alpha = map(distFromCenter, 0, 400, 180, 0);
    alpha = constrain(alpha, 0, 180);

    let size = random(1, 4);
    noStroke();

    let colorChoice = random(1);
    if (colorChoice < 0.6) {
      fill(60, 80, 110, alpha);
    } else {
      fill(120, 140, 180, alpha * 0.8);
    }

    ellipse(x, y, size, size);
  }

  // Flux de particules montantes
  for (let i = 0; i < 1500; i++) {
    let x = randomGaussian(0, 80);
    let y = random(-300, -900);

    let noiseVal = noise(x * 0.01, y * 0.01);
    x += map(noiseVal, 0, 1, -30, 30);

    let alpha = map(y, -300, -900, 150, 0);
    alpha = constrain(alpha, 0, 150);

    let size = random(0.5, 3);

    noStroke();
    if (random(1) < 0.7) {
      fill(100, 130, 170, alpha);
    } else {
      fill(150, 180, 210, alpha);
    }

    ellipse(x, y, size, size);

    // Trainées légères
    if (random(1) < 0.3) {
      stroke(100, 130, 170, alpha * 0.3);
      strokeWeight(0.5);
      line(x, y, x + random(-5, 5), y - random(10, 30));
    }
  }

  pop();

  // Particules ambiantes dans l'obscurité
  for (let i = 0; i < 400; i++) {
    let x = random(width);
    let y = random(height);
    let size = random(0.5, 2);
    let alpha = random(10, 60);
    noStroke();
    fill(80, 100, 130, alpha);
    ellipse(x, y, size, size);
  }

  // Voile mystérieux
  for (let i = 0; i < 50; i++) {
    let x = width / 2 + randomGaussian(0, 300);
    let y = random(height * 0.3, height * 0.8);
    let w = random(100, 300);
    let h = random(50, 150);
    let alpha = random(5, 20);
    noStroke();
    fill(40, 60, 90, alpha);
    ellipse(x, y, w, h);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  background(8, 5, 15);

  // Couches de profondeur cosmique
  for (let layer = 0; layer < 5; layer++) {
    for (let i = 0; i < 800; i++) {
      let x = random(width);
      let y = random(height);
      let brightness = random(100, 255);
      let size = random(0.5, 2) * (1 - layer * 0.15);
      noStroke();
      fill(brightness, brightness - 20, brightness - 40, random(40, 120));
      circle(x, y, size);
    }
  }

  // La forme de vie centrale en dissolution
  push();
  translate(width / 2, height * 0.4);

  // Particules qui s'échappent vers le haut
  for (let i = 0; i < 3000; i++) {
    let angle = random(TWO_PI);
    let distance = randomGaussian(0, 180);
    let x = cos(angle) * distance;
    let y = sin(angle) * distance;

    // Migration vers le haut
    let drift = map(distance, 0, 300, 0, -600);
    y += drift;

    // Gradient de couleur : chaud en bas, froid en haut
    let lifeAmount = constrain(map(y, 200, -800, 1, 0), 0, 1);
    let r = lerp(60, 180, lifeAmount);
    let g = lerp(20, 80, lifeAmount);
    let b = lerp(80, 40, lifeAmount);

    let alpha = map(abs(distance), 0, 300, 180, 0) * (1 - constrain(-y / 600, 0, 1) * 0.7);

    noStroke();
    fill(r, g, b, alpha);
    let size = random(1, 4) * map(abs(distance), 0, 300, 1.5, 0.3);
    circle(x, y, size);
  }
  pop();

  // Le voile - membrane ondulante
  for (let pass = 0; pass < 3; pass++) {
    beginShape();
    noFill();
    stroke(90, 60, 130, 25 + pass * 15);
    strokeWeight(2 - pass * 0.5);

    let yBase = height * 0.5 + pass * 40;
    for (let x = 0; x <= width; x += 5) {
      let n = noise(x * 0.003, pass * 0.5);
      let y = yBase + sin(x * 0.01 + pass) * 80 * n;
      y += noise(x * 0.005, pass * 2) * 100;
      vertex(x, y);
    }
    endShape();
  }

  // Flux de désintégration
  for (let i = 0; i < 150; i++) {
    let startX = random(width * 0.3, width * 0.7);
    let startY = random(height * 0.3, height * 0.5);

    noFill();
    stroke(100, 70, 140, random(10, 40));
    strokeWeight(random(0.5, 2));

    beginShape();
    let x = startX;
    let y = startY;
    for (let j = 0; j < 60; j++) {
      vertex(x, y);
      x += random(-3, 3);
      y += random(5, 15);

      if (y > height) break;
    }
    endShape();
  }

  // Zone d'intensité - dernier souffle
  push();
  translate(width / 2, height * 0.4);
  for (let i = 0; i < 500; i++) {
    let angle = random(TWO_PI);
    let r = randomGaussian(0, 50);
    let x = cos(angle) * r;
    let y = sin(angle) * r;

    noStroke();
    let heat = map(abs(r), 0, 100, 255, 0);
    fill(heat * 0.9, heat * 0.5, heat * 0.3, random(80, 160));
    circle(x, y, random(2, 8));
  }
  pop();

  // Profondeur infinie du bas - l'inconnu
  for (let y = height * 0.6; y < height; y += 2) {
    let alpha = map(y, height * 0.6, height, 0, 60);
    stroke(25, 15, 50, alpha);
    strokeWeight(2);

    for (let x = 0; x < width; x += random(10, 40)) {
      let n = noise(x * 0.01, y * 0.005);
      let len = random(5, 30) * n;
      line(x, y, x + len, y);
    }
  }

  // Fragments de mémoire - points lumineux dispersés
  for (let i = 0; i < 100; i++) {
    let x = random(width);
    let y = random(height * 0.5, height);

    noStroke();
    fill(200, 180, 150, random(30, 90));
    circle(x, y, random(1, 5));

    // Halo
    fill(200, 180, 150, random(5, 15));
    circle(x, y, random(10, 30));
  }

  // Énergie résiduelle - arcs subtils
  noFill();
  for (let i = 0; i < 40; i++) {
    stroke(80, 60, 110, random(10, 30));
    strokeWeight(random(0.5, 1.5));

    let x1 = random(width);
    let y1 = random(height * 0.3, height * 0.6);
    let x2 = x1 + random(-200, 200);
    let y2 = y1 + random(100, 400);

    bezier(
      x1, y1,
      x1 + random(-100, 100), y1 + random(50, 150),
      x2 + random(-100, 100), y2 - random(50, 150),
      x2, y2
    );
  }
}

