function drawDissolvingFigure(x, y, dissolution) {
  push();
  translate(x, y);

  let segments = 30;
  let figureHeight = 300;

  for(let i = 0; i < segments; i++) {
    let segY = map(i, 0, segments, -figureHeight/2, figureHeight/2);
    let progress = i / segments;

    // Plus on monte, plus la figure se dissout
    let dissolve = dissolution + progress * 0.5;
    dissolve = constrain(dissolve, 0, 1);

    let segWidth = 40 * (1 - dissolve);
    let offsetX = random(-dissolve * 50, dissolve * 50);
    let alpha = (1 - dissolve) * 100;

    if(alpha > 5) {
      noStroke();
      fill(60, 70, 80, alpha);

      let scatter = dissolve * 20;
      for(let p = 0; p < 5; p++) {
        let px = offsetX + random(-scatter, scatter);
        let py = segY + random(-2, 2);
        ellipse(px, py, segWidth/5 + random(-2, 2), 8);
      }
    }
  }
  pop();
}

function drawVeil(x, y, opacity) {
  push();
  noFill();

  let points = 40;
  let veilLength = height * 1.2;

  for(let layer = 0; layer < 3; layer++) {
    beginShape();
    for(let i = 0; i <= points; i++) {
      let py = map(i, 0, points, y, y + veilLength);
      let n = noise(x * 0.01, py * 0.005, layer);
      let px = x + map(n, 0, 1, -100, 100);

      let alpha = opacity * 30 * (1 - i/points);
      stroke(200, 210, 220, alpha);
      strokeWeight(1 + layer * 0.5);

      if(i > 0) {
        vertex(px, py);
      }
    }
    endShape();
  }
  pop();
}

function drawVoid(x, y, w, h) {
  push();

  // Centre absolu - le vide
  for(let r = 0; r < 80; r++) {
    let radius = map(r, 0, 80, 0, max(w, h) * 0.8);
    let alpha = map(r, 0, 80, 60, 0);

    noFill();
    stroke(5, 8, 12, alpha);
    strokeWeight(3);

    let sides = 60;
    beginShape();
    for(let i = 0; i <= sides; i++) {
      let angle = map(i, 0, sides, 0, TWO_PI);
      let n = noise(cos(angle) * 0.5, sin(angle) * 0.5, r * 0.1);
      let r2 = radius * (0.7 + n * 0.6);
      let px = x + cos(angle) * r2;
      let py = y + sin(angle) * r2;
      vertex(px, py);
    }
    endShape(CLOSE);
  }

  // Vide central profond
  noStroke();
  fill(2, 3, 5);
  ellipse(x, y, w * 0.3, h * 0.3);

  pop();
}

function drawMemoryTrace(x, y) {
  push();

  let traceLength = random(50, 200);
  let angle = random(TWO_PI);

  for(let i = 0; i < traceLength; i++) {
    let progress = i / traceLength;
    let alpha = (1 - progress) * random(20, 60);

    let px = x + cos(angle) * i;
    let py = y + sin(angle) * i;

    noStroke();
    fill(100, 110, 130, alpha);
    circle(px, py, 2 - progress * 1.5);

    angle += random(-0.1, 0.1);
  }

  pop();
}

function drawTimeFlow() {
  push();

  for(let flow = 0; flow < 15; flow++) {
    let startY = random(height * 0.2, height * 0.8);

    noFill();
    beginShape();

    for(let x = 0; x < width; x += 10) {
      let n = noise(x * 0.002, startY * 0.001, flow * 0.5);
      let y = startY + map(n, 0, 1, -150, 150);

      let alpha = map(n, 0, 1, 5, 25);
      stroke(80, 90, 110, alpha);
      strokeWeight(0.5);

      vertex(x, y);
    }

    endShape();
  }

  pop();
}

