function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  background(8, 10, 15);

  // Couches de profondeur - l'immensité qui accueille
  for (let layer = 0; layer < 5; layer++) {
    for (let i = 0; i < 3000; i++) {
      let x = random(width);
      let y = random(height);
      let alpha = random(1, 8) * (1 - layer * 0.15);
      let size = random(0.5, 2);
      noStroke();
      fill(20, 25, 35, alpha);
      circle(x, y, size);
    }
  }

  // La forme centrale - ce qui fut
  push();
  translate(width/2, height/2 - 100);

  // Corps de particules - dissolution progressive
  for (let r = 250; r >= 0; r -= 2) {
    let progress = 1 - r / 250;
    let dispersion = pow(progress, 2) * 300;
    let density = 1 - pow(progress, 0.7);

    let numParticles = int(density * 80);

    for (let i = 0; i < numParticles; i++) {
      let angle = random(TWO_PI);
      let distance = r + randomGaussian(0, dispersion);

      let x = cos(angle) * distance;
      let y = sin(angle) * distance;

      // Dérive selon le bruit de Perlin
      let drift = noise(x * 0.003, y * 0.003, r * 0.01) * 150;
      x += cos(angle + PI/2) * drift * progress;
      y += sin(angle + PI/2) * drift * progress;

      // Couleur: du blanc ivoire au bleu sombre
      let lifeColor = lerpColor(
        color(220, 215, 205),
        color(15, 20, 35),
        progress
      );

      let alpha = 255 * density * random(0.3, 1);
      let size = random(0.8, 3.5) * (1 - progress * 0.5);

      noStroke();
      fill(red(lifeColor), green(lifeColor), blue(lifeColor), alpha);
      circle(x, y, size);
    }
  }
  pop();

  // Le seuil - ligne de transformation
  push();
  noFill();
  for (let i = 0; i < 200; i++) {
    let y = height/2 + sin(i * 0.5) * 150;
    let alpha = 2 + sin(i * 0.1) * 1;
    stroke(140, 135, 125, alpha);
    strokeWeight(0.5);

    let startX = width/2 - 400 + noise(i * 0.1) * 100;
    let endX = width/2 + 400 + noise(i * 0.1 + 100) * 100;

    beginShape();
    for (let x = startX; x <= endX; x += 5) {
      let offset = noise(x * 0.003, y * 0.003, i * 0.5) * 30;
      vertex(x, y + offset);
    }
    endShape();
  }
  pop();

  // Particules errantes - ce qui dérive dans l'après
  for (let i = 0; i < 800; i++) {
    let x = random(width);
    let y = random(height * 0.6, height);

    let flow = noise(x * 0.002, y * 0.002) * TWO_PI * 2;
    let distance = random(5, 40);

    let x2 = x + cos(flow) * distance;
    let y2 = y + sin(flow) * distance;

    stroke(60, 70, 85, random(10, 40));
    strokeWeight(random(0.3, 1.2));
    line(x, y, x2, y2);

    noStroke();
    fill(80, 90, 105, random(20, 60));
    circle(x, y, random(0.5, 2));
  }

  // Voile final - l'oubli qui recouvre
  for (let y = height * 0.7; y < height; y += 1) {
    let alpha = map(y, height * 0.7, height, 0, 25);
    stroke(5, 8, 12, alpha);
    line(0, y, width, y);
  }
}

