function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Fond cosmique profond
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let c1 = color(5, 5, 15);
    let c2 = color(15, 5, 35);
    let c3 = color(45, 20, 60);
    let c;
    if (t < 0.5) {
      c = lerpColor(c1, c2, t * 2);
    } else {
      c = lerpColor(c2, c3, (t - 0.5) * 2);
    }
    stroke(c);
    line(0, y, width, y);
  }

  // Étoiles lointaines
  for (let i = 0; i < 800; i++) {
    let x = random(width);
    let y = random(height * 0.6);
    let brightness = random(100, 255);
    let size = random(0.5, 2);
    noStroke();
    fill(brightness, brightness, brightness + 20, random(100, 200));
    circle(x, y, size);
  }

  // La silhouette humaine en bas - forme dense
  push();
  translate(width / 2, height * 0.85);

  // Corps sombre et terrestre
  for (let layer = 0; layer < 50; layer++) {
    let alpha = map(layer, 0, 50, 180, 0);
    let expansion = map(layer, 0, 50, 0, 20);

    fill(40, 25, 20, alpha);
    noStroke();

    // Forme humaine stylisée
    beginShape();
    for (let angle = 0; angle < TWO_PI; angle += 0.1) {
      let r;
      if (angle < PI * 0.3 || angle > PI * 1.7) {
        // Tête
        r = 60 + expansion;
        let offsetY = -180;
        let x = cos(angle) * r;
        let y = sin(angle) * r + offsetY;
        vertex(x, y);
      } else if (angle >= PI * 0.3 && angle <= PI * 0.7) {
        // Épaule droite vers corps
        let t = map(angle, PI * 0.3, PI * 0.7, 0, 1);
        r = lerp(60, 100, t) + expansion;
        let offsetY = lerp(-180, -50, t);
        let x = cos(angle) * r;
        let y = sin(angle) * r + offsetY;
        vertex(x, y);
      } else if (angle > PI * 0.7 && angle < PI * 1.3) {
        // Corps
        r = 100 + expansion;
        let offsetY = -50;
        let x = cos(angle) * r;
        let y = sin(angle) * r + offsetY;
        vertex(x, y);
      } else {
        // Épaule gauche
        let t = map(angle, PI * 1.3, PI * 1.7, 0, 1);
        r = lerp(100, 60, t) + expansion;
        let offsetY = lerp(-50, -180, t);
        let x = cos(angle) * r;
        let y = sin(angle) * r + offsetY;
        vertex(x, y);
      }
    }
    endShape(CLOSE);
  }
  pop();

  // Particules de dissolution - la transformation
  let particles = [];
  let centerX = width / 2;
  let baseY = height * 0.85;

  // Génération des particules qui s'élèvent
  for (let i = 0; i < 8000; i++) {
    let angle = random(TWO_PI);
    let distFromCenter = randomGaussian(0, 80);
    let startX = centerX + cos(angle) * distFromCenter;
    let startY = baseY - 180 + sin(angle) * abs(distFromCenter) * 0.8;

    // Hauteur de montée
    let rise = random(100, 1200);
    let x = startX + random(-30, 30) * (rise / 400);
    let y = startY - rise;

    // Transition de couleur: du terrestre (rouge-orange) au cosmique (bleu-violet)
    let progress = constrain(rise / 1200, 0, 1);
    let r, g, b;

    if (progress < 0.3) {
      // Rouge-orange terrestre
      r = lerp(180, 255, progress / 0.3);
      g = lerp(60, 140, progress / 0.3);
      b = lerp(30, 60, progress / 0.3);
    } else if (progress < 0.6) {
      // Transition vers jaune-blanc
      let t = (progress - 0.3) / 0.3;
      r = lerp(255, 255, t);
      g = lerp(140, 240, t);
      b = lerp(60, 200, t);
    } else {
      // Vers bleu-violet cosmique
      let t = (progress - 0.6) / 0.4;
      r = lerp(255, 150, t);
      g = lerp(240, 180, t);
      b = lerp(200, 255, t);
    }

    particles.push({
      x: x,
      y: y,
      size: random(1, 5) * (1 - progress * 0.5),
      r: r,
      g: g,
      b: b,
      alpha: random(100, 255) * (1 - progress * 0.3)
    });
  }

  // Dessiner les particules
  for (let p of particles) {
    noStroke();
    fill(p.r, p.g, p.b, p.alpha);
    circle(p.x, p.y, p.size);

    // Halo léger
    fill(p.r, p.g, p.b, p.alpha * 0.3);
    circle(p.x, p.y, p.size * 2);
  }

  // Flux d'énergie ascendant
  for (let i = 0; i < 100; i++) {
    let x = centerX + randomGaussian(0, 50);
    let yStart = baseY - 100;
    let yEnd = random(50, 400);

    for (let y = yStart; y > yEnd; y -= 5) {
      let progress = map(y, yStart, yEnd, 0, 1);
      let r = lerp(255, 200, progress);
      let g = lerp(100, 200, progress);
      let b = lerp(50, 255, progress);
      let alpha = lerp(80, 0, progress);

      stroke(r, g, b, alpha);
      strokeWeight(random(0.5, 2));
      let xOffset = sin(y * 0.02 + i) * 10;
      point(x + xOffset, y);
    }
  }

  // Voile éthéré au sommet
  for (let y = 0; y < height * 0.4; y += 2) {
    for (let x = 0; x < width; x += 3) {
      let n = noise(x * 0.003, y * 0.003);
      if (n > 0.5) {
        let alpha = map(y, 0, height * 0.4, 50, 0) * (n - 0.5) * 2;
        stroke(200, 180, 255, alpha);
        strokeWeight(1);
        point(x, y);
      }
    }
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  background(245, 240, 235);

  // Gradient de fond subtil
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(245, 240, 235), color(205, 200, 195), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Zone supérieure : vie, forme, couleur
  for (let i = 0; i < 800; i++) {
    let x = random(width);
    let y = random(0, 500);
    let size = random(2, 20);
    let alpha = random(80, 200);

    fill(random(180, 220), random(100, 150), random(80, 120), alpha);
    noStroke();
    ellipse(x, y, size, size);
  }

  // Figures humaines stylisées qui se dissolvent
  for (let i = 0; i < 15; i++) {
    let x = map(i, 0, 14, 200, 1400);
    let y = 400 + i * 60;
    let dissolution = map(i, 0, 14, 0, 1);

    drawDissolvingFigure(x, y, dissolution);
  }

  // Zone médiane : transition, membrane
  drawMembrane();

  // Particules de dissolution
  for (let i = 0; i < 3000; i++) {
    let x = random(width);
    let y = random(400, 1600);

    let noiseVal = noise(x * 0.003, y * 0.003);
    let alpha = map(y, 400, 1600, 150, 10) * noiseVal;
    let size = map(y, 400, 1600, 3, 0.5);

    fill(120, 110, 100, alpha);
    noStroke();
    ellipse(x, y, size, size);
  }

  // Zone inférieure : silence, unité
  for (let y = 1600; y < height; y += 2) {
    let inter = map(y, 1600, height, 0, 1);
    let c = lerpColor(color(205, 200, 195), color(180, 175, 170), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Vagues d'effacement
  drawErasureWaves();

  // Voile final
  fill(245, 240, 235, 30);
  noStroke();
  rect(0, 0, width, height);
}

function drawDissolvingFigure(x, y, dissolution) {
  push();
  translate(x, y);

  let alpha = map(dissolution, 0, 1, 180, 0);
  let scatter = dissolution * 50;
  let parts = 20;

  // Tête
  for (let i = 0; i < parts; i++) {
    let offsetX = random(-scatter, scatter);
    let offsetY = random(-scatter, scatter);
    let size = map(dissolution, 0, 1, 25, 2);

    fill(80, 70, 60, alpha);
    noStroke();
    ellipse(offsetX, -40 + offsetY, size, size);
  }

  // Corps
  for (let i = 0; i < parts * 2; i++) {
    let offsetX = random(-scatter, scatter);
    let offsetY = random(-scatter, scatter);
    let size = map(dissolution, 0, 1, 15, 1);
    let yPos = random(-20, 40);

    fill(90, 80, 70, alpha);
    noStroke();
    ellipse(offsetX, yPos + offsetY, size, size);
  }

  pop();
}

function drawMembrane() {
  push();
  noFill();

  for (let i = 0; i < 50; i++) {
    let y = 900 + i * 15;
    let alpha = map(i, 0, 50, 60, 5);

    stroke(140, 130, 120, alpha);
    strokeWeight(map(i, 0, 50, 2, 0.5));

    beginShape();
    for (let x = 0; x <= width; x += 20) {
      let noiseVal = noise(x * 0.005, y * 0.005, i * 0.1);
      let yOffset = map(noiseVal, 0, 1, -30, 30);
      vertex(x, y + yOffset);
    }
    endShape();
  }

  pop();
}

function drawErasureWaves() {
  push();

  for (let wave = 0; wave < 8; wave++) {
    let baseY = 600 + wave * 150;

    for (let i = 0; i < 100; i++) {
      let x = random(width);
      let y = baseY + randomGaussian(0, 40);

      let size = random(10, 60);
      let alpha = random(10, 40);

      fill(220, 215, 210, alpha);
      noStroke();
      ellipse(x, y, size, size * 0.5);
    }
  }

  pop();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  background(0);

  // 绘制渐变背景
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c1 = color(255, 200, 80);
    let c2 = color(0, 0, 0);
    let c = lerpColor(c1, c2, pow(inter, 1.5));
    stroke(c);
    line(0, y, width, y);
  }

  // 绘制流动的粒子轨迹
  for (let i = 0; i < 800; i++) {
    let startX = random(width);
    let startY = random(height * 0.1, height * 0.4);

    let x = startX;
    let y = startY;

    let alpha = map(y, 0, height, 180, 0);

    noFill();
    beginShape();
    for (let step = 0; step < 200; step++) {
      let n = noise(x * 0.003, y * 0.003, i * 0.1);
      let angle = map(n, 0, 1, -PI, PI);

      angle += PI / 2 + random(-0.3, 0.3);

      let brightness = map(y, 0, height, 255, 0);
      let hue = map(y, 0, height, 60, 220);

      stroke(255, 150 + brightness * 0.4, 50, alpha * 0.3);
      strokeWeight(random(0.5, 2));

      vertex(x, y);

      x += cos(angle) * 3;
      y += sin(angle) * 3;

      if (y > height || x < 0 || x > width) break;
    }
    endShape();
  }

  // 绘制漂浮的光点（记忆/灵魂）
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = random(height);

    let size = random(2, 20);
    let brightness = map(y, 0, height, 255, 30);

    // 光晕效果
    for (let r = size * 3; r > 0; r -= size * 0.3) {
      let alpha = map(r, 0, size * 3, 150, 0);
      fill(255, 200 + brightness * 0.2, 100, alpha);
      noStroke();
      circle(x, y, r);
    }

    // 核心
    fill(255, 240, 200, 200);
    circle(x, y, size * 0.5);
  }

  // 绘制深渊的中心涡旋
  push();
  translate(width / 2, height * 0.85);

  for (let r = 400; r > 0; r -= 5) {
    let alpha = map(r, 0, 400, 100, 0);
    noFill();
    stroke(0, 0, 50, alpha);
    strokeWeight(2);

    beginShape();
    for (let angle = 0; angle < TWO_PI + 0.1; angle += 0.1) {
      let xoff = cos(angle) * r;
      let yoff = sin(angle) * r;

      let n = noise(xoff * 0.01, yoff * 0.01, r * 0.01);
      let radius = r + n * 20;

      let spiralAngle = angle + r * 0.01;

      let px = cos(spiralAngle) * radius;
      let py = sin(spiralAngle) * radius;

      vertex(px, py);
    }
    endShape(CLOSE);
  }
  pop();

  // 添加细微的纹理层
  for (let i = 0; i < 5000; i++) {
    let x = random(width);
    let y = random(height);
    let alpha = map(y, 0, height, 10, 2);
    stroke(255, alpha);
    strokeWeight(1);
    point(x, y);
  }
}

