function drawDeadTree() {
  push();
  translate(1100, 1620);

  // Tree trunk and branches
  drawBranch(0, 0, -90, 120, 25);

  pop();
}

function drawBranch(x, y, angle, len, thickness) {
  if (len < 8 || thickness < 1) return;

  let endX = x + cos(radians(angle)) * len;
  let endY = y + sin(radians(angle)) * len;

  stroke(0, 0, 0);
  strokeWeight(thickness);
  line(x, y, endX, endY);

  // Create branches
  let numBranches = int(random(2, 4));
  if (len > 20) {
    for (let i = 0; i < numBranches; i++) {
      let newAngle = angle + random(-45, 45);
      let newLen = len * random(0.5, 0.7);
      let newThickness = thickness * 0.7;
      drawBranch(endX, endY, newAngle, newLen, newThickness);
    }
  }
}

function drawSilhouette() {
  push();
  translate(500, 1550);

  noStroke();
  fill(0, 0, 0);

  // Head
  ellipse(0, -150, 40, 50);

  // Body
  beginShape();
  vertex(-15, -120);
  vertex(-20, -50);
  vertex(-25, 0);
  vertex(-18, 50);
  vertex(18, 50);
  vertex(25, 0);
  vertex(20, -50);
  vertex(15, -120);
  endShape(CLOSE);

  // Arms
  beginShape();
  vertex(-15, -100);
  vertex(-40, -80);
  vertex(-50, -40);
  vertex(-45, -35);
  vertex(-35, -75);
  vertex(-20, -95);
  endShape(CLOSE);

  beginShape();
  vertex(15, -100);
  vertex(40, -80);
  vertex(50, -40);
  vertex(45, -35);
  vertex(35, -75);
  vertex(20, -95);
  endShape(CLOSE);

  // Legs
  rect(-20, 50, 15, 60);
  rect(5, 50, 15, 60);

  pop();
}

