function drawDeadTree(x, bottom, top) {
  // Main trunk
  for (let y = bottom; y > top; y -= 5) {
    let progress = map(y, bottom, top, 0, 1);
    let w = map(y, bottom, top, 80, 20);
    let alpha = map(y, bottom, top, 255, 150);

    // Add decay effect
    let decay = noise(y * 0.01) * 20;

    noStroke();
    fill(60, 50, 45, alpha);
    rect(x - w/2 + decay, y, w, 5);

    // Add cracks and texture
    if (random() > 0.7) {
      stroke(40, 35, 30, alpha * 0.5);
      strokeWeight(1);
      line(x + random(-w/2, w/2), y, x + random(-w/2, w/2), y + random(5, 15));
    }
  }

  // Dead branches
  drawBranch(x, 1300, -45, 150, 25);
  drawBranch(x, 1200, 30, 120, 20);
  drawBranch(x, 1100, -60, 180, 30);
  drawBranch(x, 1000, 45, 100, 18);
  drawBranch(x, 900, -30, 140, 22);
}

function drawBranch(x, y, angle, length, thickness) {
  push();
  translate(x, y);
  rotate(radians(angle));

  for (let i = 0; i < length; i += 5) {
    let progress = i / length;
    let w = thickness * (1 - progress);
    let alpha = map(progress, 0, 1, 200, 50);

    noStroke();
    fill(55, 48, 42, alpha);
    rect(0, -w/2, 5, w);

    // Breaking apart effect at the end
    if (progress > 0.6 && random() > 0.5) {
      fill(50, 45, 40, alpha * 0.7);
      circle(i, random(-w, w), random(1, 3));
    }

    translate(5, 0);
  }
  pop();
}

function drawDispersingParticles(centerX, startY) {
  // Particles flowing upward and outward
  for (let i = 0; i < 5000; i++) {
    let angle = random(TWO_PI);
    let distance = random(0, 400);
    let x = centerX + cos(angle) * distance;
    let y = startY - random(0, 700) - distance * 0.3;

    let size = random(0.5, 4);
    let alpha = map(distance, 0, 400, 150, 0);
    alpha *= map(y, startY, startY - 700, 1, 0.2);

    let n = noise(i * 0.1, x * 0.01, y * 0.01);
    let colorShift = n * 30;

    fill(55 + colorShift, 48 + colorShift, 40 + colorShift, alpha);
    noStroke();
    circle(x, y, size);

    // Add some drift
    let drift = noise(i * 0.5) * 20 - 10;
    if (random() > 0.9) {
      stroke(50, 45, 40, alpha * 0.3);
      strokeWeight(0.5);
      line(x, y, x + drift, y - random(10, 30));
    }
  }
}

function drawRoots(x, y) {
  // Roots dissolving into the earth
  noFill();

  for (let i = 0; i < 8; i++) {
    let angle = map(i, 0, 8, 0, TWO_PI);
    let startX = x + cos(angle) * 40;
    let startY = y;

    drawSingleRoot(startX, startY, angle + PI/2, random(100, 200));
  }
}

function drawSingleRoot(x, y, angle, length) {
  let segments = int(length / 10);
  let currentX = x;
  let currentY = y;
  let currentAngle = angle;

  for (let i = 0; i < segments; i++) {
    let progress = i / segments;
    let alpha = map(progress, 0, 1, 180, 0);
    let weight = map(progress, 0, 1, 8, 1);

    stroke(50, 42, 38, alpha);
    strokeWeight(weight);

    let nextX = currentX + cos(currentAngle) * 10;
    let nextY = currentY + sin(currentAngle) * 10;

    line(currentX, currentY, nextX, nextY);

    // Add particle dissolution at the end
    if (progress > 0.5) {
      for (let j = 0; j < 3; j++) {
        let px = lerp(currentX, nextX, random());
        let py = lerp(currentY, nextY, random());
        let offset = random(20);
        fill(45, 38, 33, alpha * 0.5);
        noStroke();
        circle(px + random(-offset, offset), py + random(-offset, offset), random(1, 3));
      }
    }

    currentX = nextX;
    currentY = nextY;
    currentAngle += random(-0.3, 0.3);
  }
}

