function drawDisintegratingFigure() {
  let centerX = width / 2;
  let topY = 200;

  // 创建人形轮廓点
  let figurePoints = [];

  // 头部
  for (let angle = 0; angle < TWO_PI; angle += 0.1) {
    let x = centerX + cos(angle) * 60;
    let y = topY + 100 + sin(angle) * 70;
    figurePoints.push({x: x, y: y, stage: 0});
  }

  // 躯干和四肢的轮廓
  let bodyPath = [
    {x: centerX - 60, y: topY + 170}, // 左肩
    {x: centerX - 100, y: topY + 400}, // 左手
    {x: centerX - 60, y: topY + 350}, // 回到身体
    {x: centerX - 80, y: topY + 600}, // 左侧腰部
    {x: centerX - 90, y: topY + 950}, // 左脚
    {x: centerX - 50, y: topY + 950}, // 左脚内侧
    {x: centerX - 30, y: topY + 650}, // 裆部左
    {x: centerX + 30, y: topY + 650}, // 裆部右
    {x: centerX + 50, y: topY + 950}, // 右脚内侧
    {x: centerX + 90, y: topY + 950}, // 右脚
    {x: centerX + 80, y: topY + 600}, // 右侧腰部
    {x: centerX + 60, y: topY + 350}, // 回到身体
    {x: centerX + 100, y: topY + 400}, // 右手
    {x: centerX + 60, y: topY + 170}, // 右肩
  ];

  for (let i = 0; i < bodyPath.length; i++) {
    figurePoints.push({x: bodyPath[i].x, y: bodyPath[i].y, stage: 0});
  }

  // 为每个轮廓点生成粒子溶解效果
  for (let point of figurePoints) {
    let numParticles = 150;
    let distanceFromTop = point.y - topY;
    let dissolveAmount = map(distanceFromTop, 0, 1000, 0, 1);
    dissolveAmount = constrain(dissolveAmount, 0, 1);

    for (let i = 0; i < numParticles; i++) {
      let t = i / numParticles;
      let drift = pow(t, 1.5) * dissolveAmount * 300;

      let angle = noise(point.x * 0.01, point.y * 0.01, i * 0.1) * TWO_PI * 2;
      let distance = noise(point.x * 0.02, point.y * 0.02, i * 0.5) * drift;

      let px = point.x + cos(angle) * distance;
      let py = point.y + t * dissolveAmount * 400 + sin(angle) * distance * 0.3;

      // 颜色从暖色（生命）渐变到冷灰色（死亡）
      let lifeRatio = 1 - (py - topY) / 1200;
      lifeRatio = constrain(lifeRatio, 0, 1);

      let r = lerp(180, 60, 1 - lifeRatio);
      let g = lerp(80, 55, 1 - lifeRatio);
      let b = lerp(60, 65, 1 - lifeRatio);

      let alpha = map(t, 0, 1, 180, 20) * (1 - dissolveAmount * 0.5);

      let size = map(t, 0, 1, 3, 0.5) * map(dissolveAmount, 0, 1, 1, 0.3);

      noStroke();
      fill(r, g, b, alpha);
      circle(px, py, size);
    }
  }
}

function drawDust() {
  // 底部积累的尘埃层
  let dustY = 1700;

  for (let i = 0; i < 15000; i++) {
    let x = random(width);
