    if (y > 2000) continue;

    let density = exp(-pow(y - dustY, 2) / 8000);
    let alpha = random(10, 60) * density;

    let size = random(0.5, 2.5);

    let gray = random(50, 80);

    noStroke();
    fill(gray, gray, gray + 5, alpha);
    circle(x, y, size);
  }
}

