function drawDissolvingFigure() {
  let centerX = width / 2;
  let baseY = height * 0.75;

  // 定义人形轮廓点
  let figurePoints = [];

  // 头部
  for (let angle = 0; angle < TWO_PI; angle += 0.1) {
    let r = 60;
    let x = centerX + cos(angle) * r;
    let y = baseY - 400 + sin(angle) * r;
    figurePoints.push({x: x, y: y, region: 'head'});
  }

  // 躯干
  for (let y = baseY - 340; y < baseY - 100; y += 5) {
    let w = map(y, baseY - 340, baseY - 100, 50, 80);
    for (let x = centerX - w; x <= centerX + w; x += 5) {
      figurePoints.push({x: x, y: y, region: 'torso'});
    }
  }

  // 手臂
  for (let i = 0; i < 2; i++) {
    let side = i === 0 ? -1 : 1;
    for (let t = 0; t < 1; t += 0.02) {
      let x = centerX + side * (80 + t * 60);
      let y = baseY - 300 + t * 150;
      figurePoints.push({x: x, y: y, region: 'arm'});
    }
  }

  // 腿部
  for (let i = 0; i < 2; i++) {
    let side = i === 0 ? -1 : 1;
    for (let t = 0; t < 1; t += 0.02) {
      let x = centerX + side * (30 + t * 10);
      let y = baseY - 100 + t * 180;
      figurePoints.push({x: x, y: y, region: 'leg'});
    }
  }

  // 绘制溶解效果
  for (let point of figurePoints) {
    let distFromBottom = baseY - point.y;
    let dissolveAmount = map(distFromBottom, 0, 500, 1, 0);
    dissolveAmount = constrain(dissolveAmount, 0, 1);

    if (random() > dissolveAmount * 0.7) {
      let noiseVal = noise(point.x * 0.01, point.y * 0.01);
      let offsetX = map(noiseVal, 0, 1, -15, 15);
      let offsetY = map(noiseVal, 0, 1, -30, 10);

      // 颜色从暖到冷
      let hueVal = map(point.y, baseY, baseY - 500, 25, 220);
      colorMode(HSB);
      let alpha = map(dissolveAmount, 0, 1, 20, 150);
      fill(hueVal, 60, 80, alpha);
      noStroke();

      let size = random(2, 8) * dissolveAmount;
      circle(point.x + offsetX, point.y + offsetY, size);
    }
  }
  colorMode(RGB);
}

function drawParticles() {
  // 向上飘散的粒子
  for (let i = 0; i < 800; i++) {
    let x = width / 2 + randomGaussian(0, 200);
    let y = random(height * 0.1, height * 0.7);

    let distFromCenter = abs(x - width / 2);
    let alpha = map(distFromCenter, 0, 300, 100, 10);
    alpha = map(y, height * 0.7, height * 0.1, alpha, alpha * 0.3);

    colorMode(HSB);
    let hue = map(y, height * 0.7, height * 0.1, 25, 200);
    let sat = map(y, height * 0.7, height * 0.1, 70, 30);
    fill(hue, sat, 90, alpha);
    noStroke();

    let size = random(1, 5);
    circle(x, y, size);
  }
  colorMode(RGB);
}

function drawGlow() {
  // 顶部光源效果
  drawingContext.shadowBlur = 100;
  drawingContext.shadowColor = 'rgba(200, 180, 255, 0.3)';

  noStroke();
  fill(240, 230, 255, 30);
  ellipse(width / 2, height * 0.15, 400, 200);

  drawingContext.shadowBlur = 0;

  // 中心微光
  for (let i = 0; i < 50; i++) {
    let angle = random(TWO_PI);
    let r = randomGaussian(0, 100);
    let x = width / 2 + cos(angle) * r;
    let y = height * 0.4 + sin(angle) * r * 0.5;

    fill(255, 240, 200, random(10, 40));
    noStroke();
    circle(x, y, random(2, 6));
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  background(5, 5, 15);

  // 从上到下：生命到死亡的过渡

  // 上半部分：生命的混沌与密集
  for (let y = 0; y < 800; y++) {
    let progress = y / 800;
    let density = map(y, 0, 800, 150, 50);

    for (let i = 0; i < density; i++) {
      let x = random(width);
      let yPos = y + random(-30, 30);

      // 温暖的生命色彩
      let r = map(y, 0, 800, 220, 180);
      let g = map(y, 0, 800, 80, 60);
      let b = map(y, 0, 800, 40, 80);
      let a = map(y, 0, 800, 180, 120);

      stroke(r, g, b, a);
      strokeWeight(random(0.5, 2));

      let angle = noise(x * 0.003, y * 0.003) * TWO_PI * 4;
      let len = random(5, 25);

      push();
      translate(x, yPos);
      rotate(angle);
      line(0, 0, len, 0);
      pop();
    }
  }

  // 中部：过渡区域 - 漩涡状消散
  for (let y = 800; y < 1400; y++) {
    let progress = (y - 800) / 600;
    let density = map(y, 800, 1400, 50, 10);

    for (let i = 0; i < density; i++) {
      let x = random(width);
      let yPos = y + random(-50, 50);

      // 色彩从暖到冷的过渡
      let r = map(y, 800, 1400, 180, 60);
      let g = map(y, 800, 1400, 60, 50);
      let b = map(y, 800, 1400, 80, 140);
      let a = map(y, 800, 1400, 120, 40);

      stroke(r, g, b, a);
      strokeWeight(random(0.3, 1.5));

      // 螺旋式消散
      let centerX = width / 2;
      let angle = atan2(yPos - 1100, x - centerX) + noise(x * 0.002, y * 0.002) * PI;
      let len = random(3, 15) * (1 - progress);

      push();
      translate(x, yPos);
      rotate(angle);
      line(0, 0, len, 0);
      pop();
    }
  }

  // 添加漩涡中心的流动感
  for (let r = 50; r < 400; r += 15) {
    let points = r / 2;
    for (let i = 0; i < points; i++) {
      let angle = map(i, 0, points, 0, TWO_PI);
      let spiral = angle + r * 0.01;
      let x = width / 2 + cos(spiral) * r;
      let y = 1100 + sin(spiral) * r * 0.6;

      if (y > 800 && y < 1400) {
        let progress = (y - 800) / 600;
        let size = (1 - progress) * 3;

        fill(80, 60, 120, 60 * (1 - progress));
        noStroke();
        ellipse(x, y, size, size);
      }
    }
  }

  // 下半部分：虚空与寂静
  for (let y = 1400; y < 2000; y++) {
    let progress = (y - 1400) / 600;
    let density = map(y, 1400, 2000, 10, 1);

    for (let i = 0; i < density; i++) {
      let x = random(width);
      let yPos = y + random(-20, 20);

      // 深邃的冷色
      let r = map(y, 1400, 2000, 60, 10);
      let g = map(y, 1400, 2000, 50, 10);
      let b = map(y, 1400, 2000, 140, 30);
      let a = map(y, 1400, 2000, 40, 5);

      stroke(r, g, b, a);
      strokeWeight(random(0.2, 0.8));

      let len = random(2, 8) * (1 - progress);
      line(x, yPos, x + len, yPos);
    }
  }

  // 最底部：纯粹的虚空
  noStroke();
  for (let y = 1800; y < 2000; y++) {
    let a = map(y, 1800, 2000, 0, 255);
    fill(5, 5, 15, a);
    rect(0, y, width, 1);
  }

  // 添加微弱的星点，象征记忆的残留
  for (let i = 0; i < 100; i++) {
    let x = random(width);
    let y = random(1200, 1900);
    let size = random(0.5, 2);
    let brightness = random(100, 200);

    fill(brightness, brightness, brightness + 50, random(30, 100));
    noStroke();
    ellipse(x, y, size, size);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  background(5, 10, 25);

  drawDissolution();
}

function drawDissolution() {
  // 人形轮廓，从上到下逐渐消解
  let centerX = width / 2;
  let startY = 200;

  // 绘制多层粒子，形成从实体到虚无的过渡
  for (let layer = 0; layer < 150; layer++) {
    let progress = layer / 150;
    let y = startY + progress * 1500;
    let dissolution = pow(progress, 1.5);

    // 颜色从红色（生命）渐变到深蓝（虚空）
    let r = map(progress, 0, 1, 180, 20);
    let g = map(progress, 0, 1, 60, 30);
    let b = map(progress, 0, 1, 60, 80);
    let alpha = map(progress, 0, 1, 180, 20);

    // 人形的基本轮廓
    let numPoints = 60;
    for (let i = 0; i < numPoints; i++) {
      let angle = map(i, 0, numPoints, 0, TWO_PI);

      // 创建人形轮廓（头部、躯干、四肢）
      let baseRadius;
      if (progress < 0.15) {
        // 头部区域
        baseRadius = 80 + sin(angle * 1) * 20;
      } else if (progress < 0.5) {
        // 躯干
        baseRadius = 100 + sin(angle * 2) * 30;
      } else {
        // 下肢逐渐分叉
        baseRadius = 90 + sin(angle * 3) * 40;
      }

      // 随着进度增加，形态逐渐散开
      let scatter = dissolution * 400;
      let noiseVal = noise(i * 0.1, layer * 0.05) * scatter;
      let radius = baseRadius + noiseVal;

      // 粒子位置
      let x = centerX + cos(angle) * radius;
      let particleY = y + sin(angle * 2) * scatter * 0.5;

      // 粒子大小随消解程度变化
      let size = map(dissolution, 0, 1, 8, 1.5);
      size *= (1 + noise(i * 0.5, layer * 0.1) * 1.5);

      // 在高度消解区域添加随机漂移
      if (dissolution > 0.3) {
        x += (noise(i * 0.3, layer * 0.08) - 0.5) * scatter * 0.8;
        particleY += (noise(i * 0.4, layer * 0.09) - 0.5) * scatter * 0.6;
      }

      // 绘制粒子
      noStroke();
      fill(r, g, b, alpha * (1 - dissolution * 0.7));
      ellipse(x, particleY, size, size);

      // 添加一些连接线，表示尚未完全断裂的联系
      if (dissolution < 0.6 && i % 3 === 0) {
        let nextAngle = map(i + 1, 0, numPoints, 0, TWO_PI);
        let nextRadius = baseRadius + noise((i + 1) * 0.1, layer * 0.05) * scatter;
        let x2 = centerX + cos(nextAngle) * nextRadius;
        let y2 = y + sin(nextAngle * 2) * scatter * 0.5;

        stroke(r, g, b, alpha * 0.3 * (1 - dissolution));
        strokeWeight(0.5);
        line(x, particleY, x2, y2);
      }
    }
  }

  // 添加漂浮的碎片和能量粒子
  for (let i = 0; i < 800; i++) {
    let x = random(width);
    let y = random(height);
    let distFromCenter = dist(x, y, centerX, height / 2);
    let normalizedDist = distFromCenter / width;

    // 只在特定区域绘制
    if (y > 300) {
      let yProgress = (y - 300) / (height - 300);
      let size = random(1, 4) * (1 - yProgress * 0.5);

      let r = map(yProgress, 0, 1, 150, 30);
      let g = map(yProgress, 0, 1, 50, 40);
      let b = map(yProgress, 0, 1, 50, 100);
      let alpha = random(50, 150) * (1 - yProgress * 0.6);

      noStroke();
      fill(r, g, b, alpha);
      ellipse(x, y, size, size);
    }
  }

  // 在底部添加虚空感
  for (let y = 1500; y < height; y += 2) {
    let alpha = map(y, 1500, height, 30, 0);
    stroke(10, 20, 40, alpha);
    strokeWeight(2);
    line(0, y, width, y);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  background(5, 5, 15);

  // 绘制从生命到虚无的渐变粒子场
  for (let layer = 0; layer < 15; layer++) {
    for (let i = 0; i < 8000; i++) {
      let x = random(width);
      let y = random(height);

      // 垂直渐变：从上到下，从生命到死亡
      let lifeForce = 1 - (y / height);
      lifeForce = pow(lifeForce, 1.5);

      // 噪声场影响粒子分布
      let noiseVal = noise(x * 0.003, y * 0.003, layer * 0.5);
      let density = noiseVal * lifeForce;

      if (random() < density * 0.4) {
        // 颜色从温暖生命色到冷寂死亡色
        let hue = map(y, 0, height, 45, 240);
        hue += random(-20, 20);

        let sat = map(y, 0, height, 85, 15) * noiseVal;
        let bri = map(y, 0, height, 90, 5) * density;

        colorMode(HSB, 360, 100, 100);
        let alpha = map(y, 0, height, 180, 20) * density;

        fill(hue, sat, bri, alpha);
        noStroke();

        let size = random(1, 8) * lifeForce * noiseVal;
        circle(x, y, size);
      }
    }
  }

  // 绘制流动的能量线，表示生命力的消散
  for (let i = 0; i < 150; i++) {
    let startX = random(width);
    let startY = random(height * 0.3);

    let points = [];
    let x = startX;
    let y = startY;

    for (let j = 0; j < 100; j++) {
      points.push({x: x, y: y});

      let angle = noise(x * 0.005, y * 0.005, i * 0.1) * TWO_PI * 2;
      angle += PI / 2; // 偏向向下

      x += cos(angle) * 8;
      y += sin(angle) * 8;

      if (y > height || x < 0 || x > width) break;
    }

    // 绘制路径
    noFill();
    for (let j = 0; j < points.length - 1; j++) {
      let progress = j / points.length;
      let yProgress = points[j].y / height;

      let alpha = (1 - progress) * (1 - yProgress) * 100;

      colorMode(HSB, 360, 100, 100);
      let hue = map(points[j].y, 0, height, 50, 220);
      let sat = map(points[j].y, 0, height, 70, 10);
      let bri = map(points[j].y, 0, height, 80, 10);

      stroke(hue, sat, bri, alpha);
      strokeWeight(map(yProgress, 0, 1, 2, 0.5));

      line(points[j].x, points[j].y, points[j + 1].x, points[j + 1].y);
    }
  }

  // 添加深渊般的虚空中心
  let voidX = width / 2;
  let voidY = height * 0.75;

  for (let r = 300; r > 0; r -= 2) {
    let alpha = map(r, 300, 0, 0, 25);
    colorMode(RGB, 255);
    fill(5, 5, 15, alpha);
    noStroke();
    circle(voidX, voidY, r * 2);
  }

  // 添加细微的纹理
  colorMode(RGB, 255);
  for (let i = 0; i < 5000; i++) {
    let x = random(width);
    let y = random(height);
    let alpha = random(5, 15);
    stroke(255, alpha);
    strokeWeight(random(0.5, 1));
    point(x, y);
  }
}

