function drawDissolvingFigure() {
  let centerX = 800;
  let startY = 400;

  // 定义人形轮廓点
  let figurePoints = [];

  // 头部
  for (let a = 0; a < TWO_PI; a += 0.1) {
    let x = centerX + cos(a) * 80;
    let y = startY + 100 + sin(a) * 90;
    figurePoints.push({x: x, y: y, region: 0});
  }

  // 躯干和四肢的轮廓
  let bodyOutline = [
    {x: centerX - 80, y: startY + 190},
    {x: centerX - 120, y: startY + 350},
    {x: centerX - 100, y: startY + 500},
    {x: centerX - 90, y: startY + 650},
    {x: centerX - 70, y: startY + 800},
    {x: centerX - 50, y: startY + 950},
    {x: centerX, y: startY + 1000},
    {x: centerX + 50, y: startY + 950},
    {x: centerX + 70, y: startY + 800},
    {x: centerX + 90, y: startY + 650},
    {x: centerX + 100, y: startY + 500},
    {x: centerX + 120, y: startY + 350},
    {x: centerX + 80, y: startY + 190}
  ];

  figurePoints = figurePoints.concat(bodyOutline.map(p => ({...p, region: 1})));

  // 根据Y坐标绘制不同程度的消散
  for (let y = startY; y < startY + 1200; y += 2) {
    let dissolveFactor = map(y, startY, startY + 1200, 0, 1);
    dissolveFactor = pow(dissolveFactor, 1.5);

    // 计算这一行的人形宽度
    let leftEdge = centerX - 120 + dissolveFactor * 50;
    let rightEdge = centerX + 120 - dissolveFactor * 50;

    if (y < startY + 190) {
      leftEdge = centerX - 80 * (1 - dissolveFactor * 0.3);
      rightEdge = centerX + 80 * (1 - dissolveFactor * 0.3);
    }

    // 绘制粒子
    let particleCount = map(dissolveFactor, 0, 1, 80, 300);
    let spreadRange = map(dissolveFactor, 0, 1, 0, 400);

    for (let i = 0; i < particleCount; i++) {
      let baseX = lerp(leftEdge, rightEdge, i / particleCount);

      // 添加消散偏移
      let offsetX = randomGaussian(0, spreadRange * dissolveFactor);
      let offsetY = randomGaussian(0, spreadRange * dissolveFactor * 0.3);

      let px = baseX + offsetX;
      let py = y + offsetY;

      // 颜色从实体到虚无
      let opacity = map(dissolveFactor, 0, 1, 180, 0);
      opacity *= (1 - abs(offsetX) / (spreadRange * 2 + 1));

      if (opacity > 0) {
        // 粒子大小
        let size = map(dissolveFactor, 0, 1, 3, 0.5);
        size *= random(0.5, 1.5);

        // 颜色变化：从肉体色到金色能量
        let r, g, b;
        if (dissolveFactor < 0.3) {
          r = 180;
          g = 150;
          b = 140;
        } else if (dissolveFactor < 0.7) {
          let t = map(dissolveFactor, 0.3, 0.7, 0, 1);
          r = lerp(180, 220, t);
          g = lerp(150, 180, t);
          b = lerp(140, 100, t);
        } else {
          let t = map(dissolveFactor, 0.7, 1, 0, 1);
          r = lerp(220, 255, t);
          g = lerp(180, 200, t);
          b = lerp(100, 50, t);
        }

        // 添加发光效果
        if (dissolveFactor > 0.5 && random() > 0.7) {
          fill(r, g, b, opacity * 0.3);
          noStroke();
          circle(px, py, size * 3);
        }

        fill(r, g, b, opacity);
        noStroke();
        circle(px, py, size);
      }
    }
  }

  // 绘制飘散的远端粒子
  for (let i = 0; i < 2000; i++) {
    let py = random(startY + 800, 2000);
    let spreadY = map(py, startY + 800, 2000, 0, 1);

    let px = centerX + randomGaussian(0, 300 * spreadY);

    let opacity = random(5, 30) * (1 - spreadY);
    let size = random(0.3, 1.5) * (1 - spreadY * 0.5);

    fill(255, 200, 80, opacity);
    noStroke();
    circle(px, py, size);
  }
}

function drawAmbientParticles() {
  // 背景中的微粒，象征生命能量的流转
  for (let i = 0; i < 500; i++) {
