function drawDissolvingFigure(cx, cy) {
  let particles = [];

  // 创建人形轮廓的粒子
  // 头部
  for (let angle = 0; angle < TWO_PI; angle += 0.02) {
    let r = 80;
    let x = cx + cos(angle) * r;
    let y = cy - 300 + sin(angle) * r;
    particles.push({x: x, y: y, density: 1.0, baseX: x, baseY: y});
  }

  // 躯干
  for (let i = 0; i < 100; i++) {
    let t = map(i, 0, 100, 0, 1);
    let x = cx + random(-60, 60) * (1 - t * 0.3);
    let y = cy - 220 + t * 300;
    particles.push({x: x, y: y, density: 1.0, baseX: x, baseY: y});
  }

  // 左臂
  for (let i = 0; i < 60; i++) {
    let t = map(i, 0, 60, 0, 1);
    let x = cx - 60 - t * 120;
    let y = cy - 150 + t * 100;
    particles.push({x: x, y: y, density: 1.0, baseX: x, baseY: y});
  }

  // 右臂
  for (let i = 0; i < 60; i++) {
    let t = map(i, 0, 60, 0, 1);
    let x = cx + 60 + t * 120;
    let y = cy - 150 + t * 100;
    particles.push({x: x, y: y, density: 1.0, baseX: x, baseY: y});
  }

  // 左腿
  for (let i = 0; i < 80; i++) {
    let t = map(i, 0, 80, 0, 1);
    let x = cx - 40 - t * 20;
    let y = cy + 80 + t * 350;
    particles.push({x: x, y: y, density: 1.0, baseX: x, baseY: y});
  }

  // 右腿
  for (let i = 0; i < 80; i++) {
    let t = map(i, 0, 80, 0, 1);
    let x = cx + 40 + t * 20;
    let y = cy + 80 + t * 350;
    particles.push({x: x, y: y, density: 1.0, baseX: x, baseY: y});
  }

  // 添加填充粒子
  for (let i = 0; i < 3000; i++) {
    let x = cx + randomGaussian(0, 100);
    let y = cy + randomGaussian(-50, 200);
    let distFromCenter = dist(x, y, cx, cy);
    if (distFromCenter < 300) {
      particles.push({x: x, y: y, density: 0.8, baseX: x, baseY: y});
    }
  }

  // 对每个粒子施加溶解效果
  for (let p of particles) {
    let distFromCenter = dist(p.baseX, p.baseY, cx, cy);
    let dissolution = map(distFromCenter, 0, 400, 0, 1);
    dissolution = constrain(dissolution, 0, 1);

    // 添加噪声位移
    let noiseVal = noise(p.baseX * 0.005, p.baseY * 0.005);
    let displaceX = map(noiseVal, 0, 1, -1, 1) * dissolution * 300;
    let displaceY = map(noise(p.baseX * 0.003, p.baseY * 0.003 + 100), 0, 1, -1, 1) * dissolution * 300;

    p.x = p.baseX + displaceX;
    p.y = p.baseY + displaceY;

    // 计算颜色：从暖色到冷色
    let warmth = 1 - dissolution;
    let r = map(warmth, 0, 1, 20, 220);
    let g = map(warmth, 0, 1, 40, 150);
    let b = map(warmth, 0, 1, 80, 60);

    // 透明度随溶解度降低
    let alpha = map(dissolution, 0, 1, 180, 10) * p.density;

    // 粒子大小
    let size = map(dissolution, 0, 1, 2, 0.5);

    noStroke();
    fill(r, g, b, alpha);
    circle(p.x, p.y, size);

    // 添加发光效果
    if (warmth > 0.6) {
      fill(r, g, b, alpha * 0.3);
      circle(p.x, p.y, size * 3);
    }
  }

  // 绘制溶解流
  for (let i = 0; i < 50; i++) {
    let angle = random(TWO_PI);
    let startR = random(100, 200);
    let startX = cx + cos(angle) * startR;
    let startY = cy + sin(angle) * startR;

    for (let j = 0; j < 30; j++) {
      let t = j / 30;
      let x = startX + cos(angle) * t * 400;
      let y = startY + sin(angle) * t * 400;

      let alpha = map(t, 0, 1, 80, 0);
      let size = map(t, 0, 1, 3, 0.5);

      noStroke();
      fill(60, 80, 140, alpha);
      circle(x, y, size);
    }
  }
}

