function drawFlowingForm(startX, startY, segments, maxWidth, minWidth, col) {
  for (let i = 0; i < segments; i++) {
    let t = i / segments;
    let x = startX + sin(t * PI * 2 + startX * 0.01) * 200;
    let y = startY + t * 800 + cos(t * PI * 3) * 100;
    let w = lerp(maxWidth, minWidth, t);

    noStroke();
    fill(red(col), green(col), blue(col), alpha(col) * (1 - t * 0.3));
    ellipse(x, y, w, w);

    // Add texture
    for (let j = 0; j < 5; j++) {
      let nx = x + random(-w/3, w/3);
      let ny = y + random(-w/3, w/3);
      fill(red(col) + 30, green(col) + 30, blue(col) + 30, 40);
      ellipse(nx, ny, random(5, 15), random(5, 15));
    }
  }
}

function drawTendril(x1, y1, x2, y2, col) {
  let steps = 50;
  for (let i = 0; i < steps; i++) {
    let t = i / steps;
    let x = lerp(x1, x2, t);
    let y = lerp(y1, y2, t);

    x += sin(t * PI * 4) * 50;
    y += cos(t * PI * 3) * 30;

    let size = lerp(15, 3, t);
    noStroke();
    fill(red(col), green(col), blue(col), alpha(col) * (1 - t * 0.5));
    ellipse(x, y, size, size);
  }
}

