}

function drawIntertwiningForms() {
  // Left form - warm tones
  for (let layer = 0; layer < 50; layer++) {
    let alpha = map(layer, 0, 50, 15, 2);
    let offset = layer * 3;

    noStroke();
    fill(255, 100, 120, alpha);

    beginShape();
    for (let angle = 0; angle < TWO_PI; angle += 0.02) {
      let radius = 300 + offset;
      let xOff = cos(angle * 3) * 80;
      let yOff = sin(angle * 2) * 60;
      let n = noise(cos(angle) * 2, sin(angle) * 2, layer * 0.1) * 100;

      let x = width * 0.4 + (radius + n + xOff) * cos(angle);
      let y = height * 0.45 + (radius + n + yOff) * sin(angle) * 1.2;
      vertex(x, y);
    }
    endShape(CLOSE);
  }

  // Right form - cool tones
  for (let layer = 0; layer < 50; layer++) {
    let alpha = map(layer, 0, 50, 15, 2);
    let offset = layer * 3;

    noStroke();
    fill(100, 150, 255, alpha);

    beginShape();
    for (let angle = 0; angle < TWO_PI; angle += 0.02) {
      let radius = 300 + offset;
      let xOff = cos(angle * 2) * 70;
      let yOff = sin(angle * 3) * 70;
      let n = noise(cos(angle) * 2 + 10, sin(angle) * 2 + 10, layer * 0.1) * 100;

      let x = width * 0.6 + (radius + n + xOff) * cos(angle);
      let y = height * 0.55 + (radius + n + yOff) * sin(angle) * 1.2;
      vertex(x, y);
    }
    endShape(CLOSE);
  }
}

function drawGlowingCenter() {
  // Bright intersection glow
  let centerX = width * 0.5;
  let centerY = height * 0.5;

  for (let r = 250; r > 0; r -= 5) {
    let alpha = map(r, 0, 250, 40, 0);
    noStroke();
    fill(255, 220, 180, alpha);

    let variation = sin(r * 0.1) * 20;
    ellipse(centerX, centerY, r * 2 + variation, r * 2 + variation);
  }

  // Purple glow overlay
  for (let r = 200; r > 0; r -= 5) {
    let alpha = map(r, 0, 200, 25, 0);
    noStroke();
    fill(200, 150, 255, alpha);

    let variation = cos(r * 0.15) * 15;
    ellipse(centerX, centerY, r * 2 + variation, r * 2 + variation);
  }
}

function drawParticles() {
  // Floating particles representing shared moments
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = random(height);

    let distToCenter = dist(x, y, width * 0.5, height * 0.5);
    let brightness = map(distToCenter, 0, 800, 255, 50);

    let size = random(1, 4);

    if (distToCenter < 400) {
      fill(255, 240, 200, random(100, 200));
    } else if (x < width * 0.5) {
      fill(255, 150, 170, random(50, 150));
    } else {
      fill(150, 180, 255, random(50, 150));
    }

    noStroke();
    ellipse(x, y, size, size);

    // Soft glow
    fill(255, 255, 255, random(10, 30));
    ellipse(x, y, size * 2, size * 2);
  }

  // Flowing threads connecting the forms
  for (let i = 0; i < 40; i++) {
    let angle = random(TWO_PI);
    let startX = width * 0.4 + cos(angle) * 300;
    let startY = height * 0.45 + sin(angle) * 350;

    noFill();
    stroke(255, 200, 220, 30);
    strokeWeight(random(0.5, 2));

    beginShape();
    for (let t = 0; t <= 1; t += 0.05) {
      let x = lerp(startX, width * 0.6 + cos(angle + PI) * 300, t);
      let y = lerp(startY, height * 0.55 + sin(angle + PI) * 350, t);

      x += noise(t * 3, i) * 60 - 30;
      y += noise(t * 3 + 100, i) * 60 - 30;

      curveVertex(x, y);
    }
    endShape();
  }
}

