  // Right trunk rising
  drawBranch(colorRight, 200, 0, 180, -400, 40, 0, 8);

  pop();
}

function drawBranch(col, x1, y1, x2, y2, weight, depth, maxDepth) {
  if (depth > maxDepth) return;

  let alpha = map(depth, 0, maxDepth, 180, 20);
  stroke(red(col), green(col), blue(col), alpha);
  strokeWeight(weight * (1 - depth / maxDepth));

  // Draw organic curve
  noFill();
  beginShape();
  for (let t = 0; t <= 1; t += 0.1) {
    let x = lerp(x1, x2, t);
    let y = lerp(y1, y2, t);
    // Add organic noise
    x += noise(x * 0.01, y * 0.01, depth) * 30 - 15;
    y += noise(x * 0.01 + 100, y * 0.01, depth) * 20 - 10;
    curveVertex(x, y);
  }
  endShape();

  if (depth < maxDepth) {
    // Calculate split points
    let midX = (x1 + x2) / 2;
    let midY = (y1 + y2) / 2;

    // Create branches that reach toward each other
    let angle1 = atan2(y2 - y1, x2 - x1);
    let angle2 = angle1 + (depth % 2 == 0 ? -0.4 : 0.4);
    let angle3 = angle1 + (depth % 2 == 0 ? 0.4 : -0.4);

    let branchLength = dist(x1, y1, x2, y2) * 0.6;

    // Branch toward center (intertwining)
    let newX2 = x2 + cos(angle2) * branchLength;
    let newY2 = y2 + sin(angle2) * branchLength;
    drawBranch(col, x2, y2, newX2, newY2, weight * 0.7, depth + 1, maxDepth);

    // Branch outward
    let newX3 = x2 + cos(angle3) * branchLength * 0.8;
    let newY3 = y2 + sin(angle3) * branchLength * 0.8;
    drawBranch(col, x2, y2, newX3, newY3, weight * 0.6, depth + 1, maxDepth);
  }
}

function drawSharedMoments() {
  // Draw glowing particles in the space where forms meet
  for (let i = 0; i < 800; i++) {
    let x = 800 + randomGaussian() * 200;
    let y = 800 + randomGaussian() * 300;

