function drawVine(startX, startY, endX, endY, col) {
  let steps = 100;
  let prevX = startX;
  let prevY = startY;

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let x = lerp(startX, endX, t);
    let y = lerp(startY, endY, t);

    // Add organic waviness
    let noiseVal = noise(i * 0.1, startX * 0.01);
    x += map(noiseVal, 0, 1, -30, 30);

    // Varying thickness
    let thickness = map(t, 0, 1, 15, 35);

    // Color variation
    let r = red(col) + map(t, 0, 1, -20, 20);
    let g = green(col) + map(t, 0, 1, -20, 20);
    let b = blue(col) + map(t, 0, 1, -20, 20);
    let alpha = map(t, 0, 1, 200, 255);

    stroke(r, g, b, alpha);
    strokeWeight(thickness);

    if (i > 0) {
      line(prevX, prevY, x, y);
    }

    prevX = x;
    prevY = y;
  }

  // Add leaves along the vine
  for (let i = 0; i < 15; i++) {
    let t = i / 15;
    let x = lerp(startX, endX, t);
    let y = lerp(startY, endY, t);
    let noiseVal = noise(i * 0.1, startX * 0.01);
    x += map(noiseVal, 0, 1, -30, 30);

    drawLeaf(x, y, col);
  }
}

function drawLeaf(x, y, col) {
  push();
  translate(x, y);
  rotate(random(TWO_PI));

  let r = red(col) + random(-30, 30);
  let g = green(col) + random(-30, 30);
  let b = blue(col) + random(-30, 30);

  fill(r, g, b, 180);
  noStroke();

  beginShape();
  for (let a = 0; a < TWO_PI; a += 0.1) {
    let radius = 15 * sin(a) * cos(a);
    let xPos = radius * cos(a);
    let yPos = radius * sin(a) * 2;
    vertex(xPos, yPos);
  }
  endShape(CLOSE);

  pop();
}

function drawMergedForm(x, y) {
