function drawOrganicForm(startX, startY, width, direction, col1, col2) {
  push();
  noStroke();

  for (let y = startY; y > 200; y -= 20) {
    let progress = map(y, startY, 200, 0, 1);
    let curvature = sin(progress * PI) * 200 * direction;
    let x = startX + curvature;
    let w = width * (1 - progress * 0.4);

    // Gradient effect
    let c = lerpColor(col1, col2, progress);
    fill(c);

    // Draw flowing ribbons
    for (let i = 0; i < 5; i++) {
      let offset = (i - 2) * w / 8;
      let size = w / 5 + noise(y * 0.01, i) * 40;
      ellipse(x + offset, y, size, size * 1.2);
    }
  }
  pop();
}

function drawMergingZone() {
  push();
