function drawFlowingForm(x, y, size, col1, col2, direction) {
  noStroke();

  // Multiple layers creating depth
  for (let layer = 0; layer < 8; layer++) {
    let layerSize = size * (1 - layer * 0.08);
    let points = [];

    for (let angle = 0; angle < TWO_PI; angle += 0.1) {
      let xoff = cos(angle) * 2 + layer * 0.5;
      let yoff = sin(angle) * 2 + layer * 0.5;
      let n = noise(xoff, yoff) * 0.6 + 0.4;

      // Make it reach toward center
      let reachFactor = 1.0;
      if (direction < 0 && angle > PI * 0.3 && angle < PI * 0.7) {
        reachFactor = 1.3;
      } else if (direction > 0 && angle > PI * 1.3 && angle < PI * 1.7) {
        reachFactor = 1.3;
      }

      let r = layerSize * n * reachFactor;
      let px = x + cos(angle) * r;
      let py = y + sin(angle) * r;
      points.push({x: px, y: py});
    }

    let c = lerpColor(col1, col2, layer / 8);
    fill(c);

    beginShape();
    for (let p of points) {
      curveVertex(p.x, p.y);
    }
    curveVertex(points[0].x, points[0].y);
    curveVertex(points[1].x, points[1].y);
    endShape(CLOSE);
  }
}

function drawMergingSpace(leftX, rightX, centerY) {
  let midX = (leftX + rightX) / 2;

  // Create the intermingling space with gradient particles
  for (let i = 0; i < 3000; i++) {
    let t = i / 3000;
    let x = lerp(leftX, rightX, noise(i * 0.01) * 0.6 + 0.2);
    let y = centerY + (noise(i * 0.02, 100) - 0.5) * 400;

    let distFromCenter = abs(x - midX);
    let alpha = map(distFromCenter, 0, 200, 150, 0);
    alpha = constrain(alpha, 0, 150);

    let proximityY = abs(y - centerY);
    alpha *= map(proximityY, 0, 200, 1, 0);

    if (alpha > 5) {
      let col1 = color(180, 100, 150, alpha);
      let col2 = color(100, 150, 180, alpha);
      let blendedColor = lerpColor(col1, col2, noise(i * 0.05));

      fill(blendedColor);
      noStroke();
      let sz = random(2, 8) * map(distFromCenter, 0, 200, 2, 0.5);
      circle(x, y, sz);
    }
  }

  // Swirling merged forms
  for (let i = 0; i < 50; i++) {
    let angle = noise(i * 0.3) * TWO_PI;
    let radius = noise(i * 0.5) * 150;
    let x = midX + cos(angle) * radius;
    let y = centerY + sin(angle) * radius * 1.5;

    let col = lerpColor(
      color(180, 100, 150, 100),
      color(100, 150, 180, 100),
      noise(i * 0.1)
    );

    fill(col);
    noStroke();
    circle(x, y, random(20, 60));
  }
}

function drawRadiance(x, y) {
  // Soft radiating light from the center
  for (let ring = 0; ring < 15; ring++) {
    let radius = ring * 80 + 100;
    let alpha = map(ring, 0, 15, 40, 0);

    noFill();
    for (let a = 0; a < 360; a += 3) {
      let angle = radians(a);
      let n = noise(ring * 0.5, a * 0.05) * 20;
      let r = radius + n;

      stroke(250, 230, 200, alpha);
      strokeWeight(2);
      let x1 = x + cos(angle) * r;
      let y1 = y + sin(angle) * r;
      point(x1, y1);
    }
  }
}

function drawConnectingThreads(leftX, rightX, centerY) {
  // Delicate threads showing connection
  stroke(150, 100, 150, 60);
  strokeWeight(1);

  for (let i = 0; i < 100; i++) {
    let startY = centerY + (noise(i * 0.5) - 0.5) * 600;
    let endY = centerY + (noise(i * 0.5 + 100) - 0.5) * 600;

    let curve1X = lerp(leftX, rightX, 0.3);
    let curve1Y = lerp(startY, endY, noise(i * 0.3));
    let curve2X = lerp(leftX, rightX, 0.7);
    let curve2Y = lerp(startY, endY, noise(i * 0.3 + 50));

    noFill();
    beginShape();
    vertex(leftX, startY);
    bezierVertex(curve1X, curve1Y, curve2X, curve2Y, rightX, endY);
    endShape();
  }
}

function drawTransformParticles(leftX, rightX, centerY) {
  // Small particles showing transformation and exchange
  for (let i = 0; i < 200; i++) {
    let progress = noise(i * 0.1);
    let x = lerp(leftX, rightX, progress);

    let verticalSpread = map(abs(progress - 0.5), 0, 0.5, 300, 50);
    let y = centerY + (noise(i * 0.2, 500) - 0.5) * verticalSpread;

    let col;
    if (progress < 0.5) {
      col = lerpColor(
        color(180, 100, 150, 180),
        color(140, 125, 165, 180),
        progress * 2
      );
    } else {
      col = lerpColor(
        color(140, 125, 165, 180),
        color(100, 150, 180, 180),
        (progress - 0.5) * 2
      );
    }

    fill(col);
    noStroke();
    let size = noise(i * 0.15) * 6 + 2;
    circle(x, y, size);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  background(245, 240, 235);

  // Two central forms that merge and blend
  let centerX = width / 2;
  let centerY = height / 2;

  // Draw layered, dissolving forms
  for (let layer = 0; layer < 150; layer++) {
    let alpha = map(layer, 0, 150, 60, 2);

    // Left form - warm tones
    let offsetX1 = map(layer, 0, 150, -200, 100);
    let offsetY1 = map(layer, 0, 150, -100, 50);
    let size1 = map(layer, 0, 150, 800, 400);

    fill(220, 100 + layer * 0.8, 120, alpha);
    noStroke();

    beginShape();
    for (let angle = 0; angle < TWO_PI; angle += 0.1) {
      let xoff = cos(angle) * 2 + layer * 0.01;
      let yoff = sin(angle) * 2 + layer * 0.01;
      let r = size1 * (0.5 + noise(xoff, yoff, layer * 0.02) * 0.5);
      let x = centerX + offsetX1 + cos(angle) * r;
      let y = centerY + offsetY1 + sin(angle) * r * 1.2;
      vertex(x, y);
    }
    endShape(CLOSE);

    // Right form - cool tones
    let offsetX2 = map(layer, 0, 150, 200, -100);
    let offsetY2 = map(layer, 0, 150, 100, -50);
    let size2 = map(layer, 0, 150, 800, 400);

    fill(120, 150, 200 + layer * 0.5, alpha);

    beginShape();
    for (let angle = 0; angle < TWO_PI; angle += 0.1) {
      let xoff = cos(angle) * 2 + layer * 0.01 + 10;
      let yoff = sin(angle) * 2 + layer * 0.01 + 10;
      let r = size2 * (0.5 + noise(xoff, yoff, layer * 0.02) * 0.5);
      let x = centerX + offsetX2 + cos(angle) * r;
      let y = centerY + offsetY2 + sin(angle) * r * 1.2;
      vertex(x, y);
    }
    endShape(CLOSE);
  }

  // Merged center - where boundaries dissolve
  for (let layer = 0; layer < 100; layer++) {
    let alpha = map(layer, 0, 100, 40, 1);
    let size = map(layer, 0, 100, 600, 200);

    // Purple-pink merge
    fill(180, 120, 160, alpha);

    beginShape();
    for (let angle = 0; angle < TWO_PI; angle += 0.08) {
      let xoff = cos(angle) * 3 + layer * 0.015;
      let yoff = sin(angle) * 3 + layer * 0.015;
      let r = size * (0.6 + noise(xoff, yoff, layer * 0.03) * 0.4);
      let x = centerX + cos(angle) * r;
      let y = centerY + sin(angle) * r * 1.1;
      vertex(x, y);
    }
    endShape(CLOSE);
  }

  // Soft tendrils reaching outward
  for (let i = 0; i < 80; i++) {
    let angle = random(TWO_PI);
    let startDist = random(200, 400);
    let startX = centerX + cos(angle) * startDist;
    let startY = centerY + sin(angle) * startDist * 1.1;

    let hue1 = random([220, 120, 180]);
    let hue2 = random(80, 200);
    let hue3 = random(100, 220);

    noFill();
    for (let j = 0; j < 15; j++) {
      let alpha = map(j, 0, 15, 25, 2);
      stroke(hue1, hue2, hue3, alpha);
      strokeWeight(map(j, 0, 15, 8, 1));

      beginShape();
      for (let t = 0; t < 1; t += 0.02) {
        let nt = t * 5;
        let nx = startX + cos(angle + noise(nt, i * 0.1) - 0.5) * t * 300;
        let ny = startY + sin(angle + noise(nt, i * 0.1 + 100) - 0.5) * t * 350;
        let offsetX = noise(nx * 0.005, ny * 0.005, i * 0.1) * 50 - 25;
        let offsetY = noise(nx * 0.005 + 50, ny * 0.005 + 50, i * 0.1) * 50 - 25;
        curveVertex(nx + offsetX, ny + offsetY);
      }
      endShape();
    }
  }

  // Delicate particles - moments of connection
  for (let i = 0; i < 300; i++) {
    let px = random(width);
    let py = random(height);
    let distToCenter = dist(px, py, centerX, centerY);

    if (distToCenter < 600) {
      let alpha = map(distToCenter, 0, 600, 60, 10);
      let size = random(2, 8);

      fill(240, 200, 220, alpha);
      noStroke();
      ellipse(px, py, size);
    }
  }
}

function setup() {
