function drawMergingSpace() {
  for (let i = 0; i < 500; i++) {
    let angle = random(TWO_PI);
    let radius = randomGaussian(0, 100);
    let x = 800 + cos(angle) * radius;
    let y = 1000 + sin(angle) * radius;

    let size = randomGaussian(15, 5);

    noStroke();
    fill(240, 200, 220, 40);
    circle(x, y, size);
  }

  // Purple merging center
  for (let r = 150; r > 0; r -= 3) {
    noStroke();
    fill(200, 120, 200, 15);
    circle(800, 1000, r);
  }
}

function drawTendrils(from, to, col) {
  for (let i = 0; i < 15; i++) {
    let angle = map(i, 0, 15, -PI/3, PI/3);
    let baseAngle = atan2(to.y - from.y, to.x - from.x);

    noFill();
    stroke(red(col), green(col), blue(col), 100);
    strokeWeight(3);

    beginShape();
    for (let t = 0; t <= 1; t += 0.02) {
      let x = lerp(from.x, to.x, t);
      let y = lerp(from.y, to.y, t);

      let perpX = cos(baseAngle + angle) * sin(t * PI) * 150;
      let perpY = sin(baseAngle + angle) * sin(t * PI) * 150;

      x += perpX;
      y += perpY;

      curveVertex(x, y);
    }
    endShape();
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  background(12, 8, 18);

  // Two central forms representing beings
  let leftCenter = { x: 500, y: 1000 };
  let rightCenter = { x: 1100, y: 1000 };

  // Draw particle fields showing dissolution
  for (let i = 0; i < 15000; i++) {
    let angle = random(TWO_PI);
    let rad = randomGaussian(0, 180);

    // Left form particles
    let lx = leftCenter.x + cos(angle) * rad;
    let ly = leftCenter.y + sin(angle) * rad * 1.3;

    let distToRight = dist(lx, ly, rightCenter.x, rightCenter.y);
    let distToLeft = dist(lx, ly, leftCenter.x, leftCenter.y);

    // Particles dissolve more as they approach the other
    let dissolution = map(distToRight, 0, 600, 1, 0, true);

    if (distToLeft < 300) {
      let alpha = map(distToLeft, 0, 300, 180, 0) * (1 - dissolution * 0.7);
      let size = map(distToLeft, 0, 300, 8, 1) * (1 + dissolution * 2);

      let r = lerp(140, 255, dissolution);
      let g = lerp(100, 220, dissolution);
      let b = lerp(180, 180, dissolution);

      noStroke();
      fill(r, g, b, alpha);
      circle(lx, ly, size);
    }

    // Right form particles
    let rx = rightCenter.x + cos(angle) * rad;
    let ry = rightCenter.y + sin(angle) * rad * 1.3;

    let distToLeft2 = dist(rx, ry, leftCenter.x, leftCenter.y);
    let distToRight2 = dist(rx, ry, rightCenter.x, rightCenter.y);

    let dissolution2 = map(distToLeft2, 0, 600, 1, 0, true);

    if (distToRight2 < 300) {
      let alpha = map(distToRight2, 0, 300, 180, 0) * (1 - dissolution2 * 0.7);
      let size = map(distToRight2, 0, 300, 8, 1) * (1 + dissolution2 * 2);

      let r = lerp(180, 255, dissolution2);
      let g = lerp(120, 220, dissolution2);
      let b = lerp(140, 200, dissolution2);

      noStroke();
      fill(r, g, b, alpha);
      circle(rx, ry, size);
    }
  }

  // Draw the luminous space between - where boundaries meet
  for (let i = 0; i < 8000; i++) {
    let t = random(1);
    let midX = lerp(leftCenter.x, rightCenter.x, t);
    let midY = lerp(leftCenter.y, rightCenter.y, t);

    let offsetX = randomGaussian(0, 40);
    let offsetY = randomGaussian(0, 40);

    let px = midX + offsetX;
    let py = midY + offsetY;

    let distToLine = abs(offsetX * 0.7 + offsetY * 0.3);
    let intensity = map(distToLine, 0, 80, 255, 0, true);

    let centerDist = dist(px, py, 800, 1000);
    let glow = map(centerDist, 0, 300, 1.5, 0.3, true);

    noStroke();
    fill(255, 240, 200, intensity * glow * 0.4);
    circle(px, py, random(2, 8) * glow);
  }

  // Core forms - solid but dissolving at edges
  drawDissolvingForm(leftCenter.x, leftCenter.y, 140, 100, 180, -0.3);
  drawDissolvingForm(rightCenter.x, rightCenter.y, 180, 120, 140, 0.3);

  // Reaching tendrils between forms
  for (let i = 0; i < 50; i++) {
    let startAngle = random(-PI/3, PI/3);
    drawTendril(leftCenter.x, leftCenter.y, rightCenter.x, rightCenter.y, startAngle);
  }

  // Atmospheric glow
  drawingContext.filter = 'blur(2px)';
  fill(255, 240, 220, 8);
  noStroke();
  ellipse(800, 1000, 800, 600);
  drawingContext.filter = 'none';
}

function drawDissolvingForm(cx, cy, r, g, b, skew) {
  for (let radius = 180; radius > 0; radius -= 2) {
    let alpha = map(radius, 0, 180, 250, 0);
    let dissolution = map(radius, 0, 180, 0, 1);

    noStroke();
    fill(r, g, b, alpha);

    beginShape();
    for (let angle = 0; angle < TWO_PI; angle += 0.1) {
      let noiseFactor = noise(cos(angle) * 2, sin(angle) * 2, radius * 0.01);
      let r = radius * (1 + noiseFactor * dissolution * 0.3);
      let x = cx + cos(angle + skew) * r;
      let y = cy + sin(angle) * r * 1.3;
      vertex(x, y);
    }
    endShape(CLOSE);
  }
}

function drawTendril(x1, y1, x2, y2, angleOffset) {
  let steps = 40;
  let prevX = x1 + cos(angleOffset) * 80;
  let prevY = y1 + sin(angleOffset) * 80;

  for (let i = 1; i <= steps; i++) {
    let t = i / steps;
    let eased = t * t * (3 - 2 * t);

    let x = lerp(x1, x2, eased);
    let y = lerp(y1, y2, eased);

    let noiseVal = noise(i * 0.3, angleOffset * 10) - 0.5;
    x += noiseVal * 60 * sin(t * PI);
    y += noiseVal * 40 * sin(t * PI);

    let alpha = map(t, 0, 1, 120, 60) * sin(t * PI);
    stroke(220, 200, 230, alpha);
    strokeWeight(map(t, 0, 1, 3, 1));
    line(prevX, prevY, x, y);

    prevX = x;
    prevY = y;
  }
}

