  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  background(245, 240, 235);

  // Draw flowing, dissolving forms representing two beings merging
  drawDissolvingForms();

  // Add particle-like elements showing connection
  drawConnectionParticles();

  // Add soft organic shapes in the merged space
  drawMergedSpace();
