}

function drawDissolvingForms() {
  // Left form - warm colors (first being)
  for (let layer = 0; layer < 50; layer++) {
    let alpha = map(layer, 0, 50, 80, 5);
    let expansion = map(layer, 0, 50, 0, 150);

    noStroke();
    fill(220, 100, 120, alpha);

    beginShape();
    for (let angle = 0; angle < TWO_PI; angle += 0.1) {
      let xOffset = cos(angle) * 3;
      let yOffset = sin(angle) * 3;
      let r = 200 + expansion + noise(xOffset, yOffset, layer * 0.1) * 100;
      let x = 500 + cos(angle) * r;
      let y = 1000 + sin(angle) * r * 1.2;
      vertex(x, y);
    }
    endShape(CLOSE);
  }

  // Right form - cool colors (second being)
  for (let layer = 0; layer < 50; layer++) {
    let alpha = map(layer, 0, 50, 80, 5);
    let expansion = map(layer, 0, 50, 0, 150);

    noStroke();
    fill(100, 150, 220, alpha);

    beginShape();
    for (let angle = 0; angle < TWO_PI; angle += 0.1) {
      let xOffset = cos(angle) * 3 + 10;
      let yOffset = sin(angle) * 3 + 10;
      let r = 200 + expansion + noise(xOffset, yOffset, layer * 0.1) * 100;
      let x = 1100 + cos(angle) * r;
      let y = 1000 + sin(angle) * r * 1.2;
      vertex(x, y);
    }
    endShape(CLOSE);
  }
}

function drawConnectionParticles() {
  // Draw flowing particles between the forms
  for (let i = 0; i < 800; i++) {
    let t = i / 800;
    let x = lerp(500, 1100, t);
    let y = 1000 + sin(t * PI) * -200;

    // Add noise-based vertical offset
    let noiseVal = noise(i * 0.05, 100);
    y += (noiseVal - 0.5) * 400;

    // Color transition from warm to cool to merged purple
    let r, g, b;
    if (t < 0.5) {
      r = lerp(220, 160, t * 2);
      g = lerp(100, 125, t * 2);
      b = lerp(120, 220, t * 2);
    } else {
      r = lerp(160, 180, (t - 0.5) * 2);
      g = lerp(125, 100, (t - 0.5) * 2);
      b = lerp(220, 200, (t - 0.5) * 2);
    }

    let size = noise(i * 0.1) * 15 + 3;
    let alpha = noise(i * 0.08, 50) * 150 + 50;

    noStroke();
    fill(r, g, b, alpha);
    ellipse(x, y, size, size);
  }
}

function drawMergedSpace() {
  // Central merged area with new colors created by union
  for (let i = 0; i < 300; i++) {
    let angle = random(TWO_PI);
    let radius = randomGaussian(0, 120);
    let x = 800 + cos(angle) * radius;
    let y = 1000 + sin(angle) * radius;

    // Purple/magenta representing the merged entity
    let r = 180 + random(-30, 30);
    let g = 100 + random(-20, 20);
    let b = 200 + random(-30, 30);
    let alpha = random(30, 100);

    let size = randomGaussian(25, 10);

    noStroke();
    fill(r, g, b, alpha);
    ellipse(x, y, size, size);
  }

  // Add flowing tendrils representing ongoing connection
  for (let tendril = 0; tendril < 25; tendril++) {
    let startAngle = random(TWO_PI);
    let startX = 800 + cos(startAngle) * 150;
    let startY = 1000 + sin(startAngle) * 150;

    noFill();

    for (let weight = 15; weight > 0; weight -= 2) {
      let alpha = map(weight, 15, 0, 60, 5);
      stroke(170, 110, 200, alpha);
      strokeWeight(weight);

      beginShape();
      curveVertex(startX, startY);
      curveVertex(startX, startY);

      for (let step = 0; step < 8; step++) {
        let t = step / 8;
        let x = startX + cos(startAngle + t * PI * 0.5) * t * 300;
        let y = startY + sin(startAngle + t * PI * 0.5) * t * 300;
        x += noise(tendril * 10, step * 0.5, 0) * 50 - 25;
        y += noise(tendril * 10, step * 0.5, 100) * 50 - 25;
        curveVertex(x, y);
      }

      let endX = startX + cos(startAngle + PI * 0.5) * 300;
      let endY = startY + sin(startAngle + PI * 0.5) * 300;
      curveVertex(endX, endY);
      curveVertex(endX, endY);
      endShape();
    }
  }

  // Soft glow at the center
  for (let ring = 0; ring < 30; ring++) {
    let alpha = map(ring, 0, 30, 25, 0);
    let size = map(ring, 0, 30, 50, 350);
    noStroke();
    fill(255, 200, 220, alpha);
    ellipse(800, 1000, size, size);
  }
}

