function drawPainting() {
  // Fond dégradé chaud
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c1 = color(255, 200, 150);
    let c2 = color(180, 80, 120);
    let c = lerpColor(c1, c2, inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Deux formes organiques qui s'entrelacent
  let centerX = width / 2;
  let centerY = height / 2;

  // Forme 1 (gauche/rouge)
  drawOrganicForm(centerX - 150, centerY, 300, 400, color(220, 50, 70, 200), -0.3);

  // Forme 2 (droite/orange)
  drawOrganicForm(centerX + 150, centerY, 300, 400, color(255, 130, 50, 200), 0.3);

  // Zone de fusion centrale
  drawFusionZone(centerX, centerY);

  // Particules d'énergie
  drawEnergyParticles(centerX, centerY);

  // Aura lumineuse
  drawAura(centerX, centerY);
}

function drawOrganicForm(x, y, w, h, col, rotation) {
  push();
  translate(x, y);
  rotate(rotation);

  // Contour flou
  for (let i = 5; i > 0; i--) {
    fill(red(col), green(col), blue(col), 30);
    noStroke();
    beginShape();
    for (let angle = 0; angle < TWO_PI; angle += 0.1) {
      let r1 = w / 2 + noise(angle * 2, i * 0.1) * 60;
      let r2 = h / 2 + noise(angle * 2 + 100, i * 0.1) * 80;
      let px = cos(angle) * r1;
      let py = sin(angle) * r2;
      vertex(px, py);
    }
    endShape(CLOSE);
  }

  // Forme principale
  fill(col);
  noStroke();
  beginShape();
  for (let angle = 0; angle < TWO_PI; angle += 0.05) {
    let r1 = w / 2 + noise(angle * 3) * 40;
    let r2 = h / 2 + noise(angle * 3 + 50) * 60;
    let px = cos(angle) * r1;
    let py = sin(angle) * r2;
    vertex(px, py);
  }
  endShape(CLOSE);

  // Texture interne
  for (let i = 0; i < 100; i++) {
    let angle = random(TWO_PI);
    let r = random(0.3, 0.7);
    let px = cos(angle) * w * r / 2;
    let py = sin(angle) * h * r / 2;
    fill(255, 255, 200, random(50, 150));
    noStroke();
    ellipse(px, py, random(5, 20), random(5, 20));
  }

  pop();
}

function drawFusionZone(x, y) {
  push();
  translate(x, y);

  // Vagues d'énergie
  for (let i = 0; i < 8; i++) {
    noFill();
    stroke(255, 220, 100, 100 - i * 10);
    strokeWeight(3);
    beginShape();
    for (let angle = 0; angle < TWO_PI; angle += 0.1) {
      let r = 100 + i * 30 + noise(angle * 4, i * 0.5) * 40;
      let px = cos(angle) * r;
      let py = sin(angle) * r;
      vertex(px, py);
    }
    endShape(CLOSE);
  }

  // Centre lumineux
  for (let i = 8; i > 0; i--) {
    fill(255, 255, 200, 50);
    noStroke();
    ellipse(0, 0, i * 30, i * 30);
  }

  pop();
}

function drawEnergyParticles(x, y) {
  for (let i = 0; i < 200; i++) {
    let angle = random(TWO_PI);
    let radius = randomGaussian(300, 200);
    let px = x + cos(angle) * radius;
    let py = y + sin(angle) * radius;

    let size = random(2, 8);
    let brightness = random(150, 255);

    fill(255, brightness, brightness - 100, random(100, 200));
    noStroke();
    ellipse(px, py, size, size);
  }
}

function drawAura(x, y) {
  push();
  translate(x, y);

  // Lignes courbes rayonnantes
  for (let i = 0; i < 30; i++) {
    let angle = (TWO_PI / 30) * i;
    let col = lerpColor(color(255, 100, 100), color(255, 200, 100), noise(i * 0.2));
    stroke(red(col), green(col), blue(col), 60);
    strokeWeight(2);
    noFill();

    beginShape();
    for (let r = 200; r < 600; r += 10) {
      let offsetX = noise(r * 0.01, i) * 100 - 50;
      let offsetY = noise(r * 0.01, i + 100) * 100 - 50;
      let px = cos(angle) * r + offsetX;
      let py = sin(angle) * r + offsetY;
      curveVertex(px, py);
    }
    endShape();
  }

  pop();
}

