function drawRadialGlow(x, y, radius, r, g, b, maxAlpha) {
  for (let i = radius; i > 0; i -= 10) {
    let alpha = map(i, 0, radius, maxAlpha, 0);
    fill(r, g, b, alpha);
    noStroke();
    circle(x, y, i * 2);
  }
}

function drawOrganicForm(x, y, w, h, r, g, b, baseAlpha) {
  push();
  translate(x, y);

  for (let layer = 0; layer < 5; layer++) {
    let scale = 1 - layer * 0.15;
    let alpha = baseAlpha + layer * 20;

    fill(r + layer * 10, g + layer * 10, b - layer * 10, alpha);
    noStroke();

    beginShape();
    for (let angle = 0; angle < TWO_PI + 0.1; angle += 0.1) {
      let n1 = noise(cos(angle) * 2, sin(angle) * 2, layer * 0.5);
      let n2 = noise(cos(angle * 3) * 1.5, sin(angle * 3) * 1.5, layer * 0.3);
      let radiusW = (w / 2) * scale * (0.8 + n1 * 0.4);
      let radiusH = (h / 2) * scale * (0.8 + n2 * 0.4);

      let xPos = cos(angle) * radiusW;
      let yPos = sin(angle) * radiusH;
      vertex(xPos, yPos);
    }
    endShape(CLOSE);
  }
  pop();
}

function drawFusionZone() {
  // Cœur lumineux de la fusion
  for (let i = 0; i < 100; i++) {
    let angle = random(TWO_PI);
    let radius = randomGaussian(0, 80);
    let x = cos(angle) * radius;
    let y = sin(angle) * radius;

    let size = random(5, 25);
    let hue = random([0, 30, 45]);

    if (hue === 0) {
      fill(255, 220 + random(-20, 20), 180, random(150, 230));
    } else if (hue === 30) {
      fill(255, 180 + random(-20, 20), 200, random(130, 200));
    } else {
      fill(200, 180 + random(-20, 20), 255, random(130, 200));
    }

    noStroke();
    circle(x, y, size);
  }

  // Formes organiques entrelacées
  for (let i = 0; i < 8; i++) {
    let angle = (TWO_PI / 8) * i;
    push();
    rotate(angle);

    fill(255, 200, 180, 100);
    noStroke();

    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.2) {
      let r = 80 + noise(a * 2, i) * 60;
      let xPos = cos(a) * r;
      let yPos = sin(a) * r * 0.5 + 50;
      vertex(xPos, yPos);
    }
    endShape(CLOSE);
    pop();
  }
}

