function drawBeing(x, y, rotation, col1, col2) {
  push();
  translate(x, y);
  rotate(rotation);

  // Corps principal - forme organique
  for (let layer = 8; layer > 0; layer--) {
    let alpha = map(layer, 0, 8, 150, 20);
    let size = map(layer, 0, 8, 1, 1.4);

    fill(red(col1), green(col1), blue(col1), alpha);
    noStroke();

    beginShape();
    for (let angle = 0; angle < TWO_PI; angle += 0.1) {
      let r = 150 * size;
      let xoff = cos(angle) * 0.5;
      let yoff = sin(angle) * 0.5;
      let n = noise(xoff + 10, yoff + 10) * 0.3 + 0.85;
      let px = cos(angle) * r * n;
      let py = sin(angle) * r * n * 1.2;
      vertex(px, py);
    }
    endShape(CLOSE);
  }

  // Bras tendus
  for (let i = 0; i < 3; i++) {
    let angle = map(i, 0, 2, -0.3, 0.3);
    drawArm(angle, col1, col2);
  }

  // Coeur lumineux
  fill(255, 220, 180, 180);
  for (let r = 60; r > 0; r -= 10) {
    let alpha = map(r, 0, 60, 200, 30);
    fill(255, 200 + r, 150, alpha);
    circle(0, 0, r);
  }

  pop();
}

function drawArm(angle, col1, col2) {
  push();
  rotate(angle);

  for (let i = 0; i < 15; i++) {
    let t = i / 15;
    let x = t * 250;
    let y = sin(t * PI) * 30;
    let size = map(i, 0, 15, 40, 15);

    let col = lerpColor(col1, col2, t);
    fill(red(col), green(col), blue(col), 100);
    noStroke();
    ellipse(x, y, size, size * 0.8);
  }

  pop();
}

function drawFusion(x, y) {
  push();
  translate(x, y);

  // Explosion de lumière centrale
  for (let layer = 15; layer > 0; layer--) {
    let alpha = map(layer, 0, 15, 180, 10);
    let size = map(layer, 0, 15, 50, 400);

    // Gradient radial
    let col = lerpColor(
      color(255, 255, 200, alpha),
      color(255, 150, 200, alpha * 0.3),
      layer / 15
    );
    fill(col);
    noStroke();

    beginShape();
    for (let angle = 0; angle < TWO_PI; angle += 0.2) {
      let n = noise(cos(angle) * 2, sin(angle) * 2, layer * 0.1) * 0.4 + 0.8;
      let r = size * n;
      let px = cos(angle) * r;
      let py = sin(angle) * r;
      vertex(px, py);
    }
    endShape(CLOSE);
  }

  // Flammes montantes
  for (let i = 0; i < 50; i++) {
    let angle = random(TWO_PI);
    let dist = random(50, 150);
    let sx = cos(angle) * dist;
    let sy = sin(angle) * dist;

    drawFlame(sx, sy, random(-0.5, 0.5));
  }

  pop();
}

function drawFlame(x, y, rotation) {
  push();
  translate(x, y);
  rotate(rotation);

  let flameHeight = random(100, 300);
  let flameWidth = random(20, 50);

  for (let i = 0; i < 10; i++) {
    let t = i / 10;
    let fy = -t * flameHeight;
    let fw = flameWidth * (1 - t) * (1 + sin(t * PI * 3) * 0.3);

    let col = lerpColor(
      color(255, 200, 100, 150),
      color(255, 100, 150, 20),
      t
    );
    fill(col);
    noStroke();
    ellipse(0, fy, fw, fw * 1.5);
  }

  pop();
}

function drawGlows() {
  // Halos autour des êtres
  drawRadialGlow(600, 1000, color(255, 100, 120, 30), 500);
  drawRadialGlow(1000, 1000, color(120, 100, 255, 30), 500);
  drawRadialGlow(800, 1000, color(255, 220, 180, 50), 600);
}

function drawRadialGlow(x, y, col, maxSize) {
  push();
  translate(x, y);

  for (let r = maxSize; r > 0; r -= 20) {
    let alpha = map(r, 0, maxSize, 60, 0);
    fill(red(col), green(col), blue(col), alpha);
    noStroke();
    circle(0, 0, r);
  }

  pop();
}

function drawEnergyParticles() {
  // Particules flottantes autour de la fusion
  for (let i = 0; i < 200; i++) {
    let angle = random(TWO_PI);
    let dist = random(200, 600);
    let x = 800 + cos(angle) * dist;
    let y = 1000 + sin(angle) * dist;

    let n = noise(i * 0.1) * 3;
    let size = random(2, 8);

    if (n < 1) {
      fill(255, 180, 100, random(100, 200));
    } else if (n < 2) {
      fill(255, 120, 150, random(100, 200));
    } else {
      fill(180, 150, 255, random(100, 200));
    }

    noStroke();
    circle(x, y, size);

    // Traînée
    let tx = x + cos(angle + PI) * random(10, 30);
    let ty = y + sin(angle + PI) * random(10, 30);
    stroke(red(fill), green(fill), blue(fill), 50);
    strokeWeight(1);
    line(x, y, tx, ty);
  }

  // Flux d'énergie entre les deux êtres
  for (let i = 0; i < 100; i++) {
    let t = i / 100;
    let x = lerp(600, 1000, t);
    let y = 1000 + sin(t * PI * 3) * random(50, 150);

    let col = lerpColor(
      color(255, 100, 120),
      color(120, 100, 255),
      t
    );

    fill(red(col), green(col), blue(col), random(80, 150));
    noStroke();
    circle(x, y, random(3, 10));
  }
}

