function drawFigure(x, y, scale, col) {
  push();
  translate(x, y);
  scale(scale);

  // Corps
  fill(col);
  noStroke();

  // Torse
  beginShape();
  for (let a = 0; a < TWO_PI; a += 0.1) {
    let r = 120 + noise(a * 2, 0) * 30;
    let vx = cos(a) * r;
    let vy = sin(a) * r * 1.4;
    vertex(vx, vy);
  }
  endShape(CLOSE);

  // Tête
  ellipse(0, -180, 100, 120);

  // Bras enlacant
  for (let i = 0; i < 15; i++) {
    let t = i / 15;
    let bx = lerp(80, -100, t);
    let by = lerp(0, 100, t);
    let size = lerp(50, 30, t);

    let alpha = 150 + noise(i) * 100;
    let c = color(red(col), green(col), blue(col), alpha);
    fill(c);
    ellipse(bx, by, size, size);
  }

  // Effets de dissolution
  for (let i = 0; i < 50; i++) {
    let px = randomGaussian(0, 100);
    let py = randomGaussian(0, 150);
    let psize = random(10, 30);

    let alpha = random(50, 150);
    let c = color(red(col), green(col), blue(col), alpha);
    fill(c);
    ellipse(px, py, psize, psize);
  }

  pop();
}

