function draw() {
  background(245, 235, 220);

  // Gradient de fond
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c1 = color(245, 235, 220);
    let c2 = color(230, 210, 190);
    let c = lerpColor(c1, c2, inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Deux spirales entrelacées représentant deux êtres
  translate(width / 2, height / 2);

  // Première spirale - chaude (rouge-orange)
  drawSpiral(0, 0, 0, color(220, 80, 60), color(255, 160, 100), 150, 8, true);

  // Deuxième spirale - froide (bleu-violet)
  drawSpiral(0, 0, PI, color(80, 100, 180), color(150, 120, 200), 150, 8, false);

  // Particules lumineuses autour
  drawParticles();

  // Cœur central où les spirales se rencontrent
  drawCenter();
}

function drawSpiral(x, y, startAngle, c1, c2, numTurns, thickness, clockwise) {
  let maxRadius = 600;
  let turns = numTurns;
  let points = 2000;

  for (let i = 0; i < points; i++) {
    let progress = i / points;
    let angle = startAngle + (clockwise ? 1 : -1) * progress * TWO_PI * turns;
    let radius = progress * maxRadius;

    // Oscillation pour créer du mouvement
    let wave = sin(progress * TWO_PI * 3) * 20;
    radius += wave;

    let x1 = cos(angle) * radius;
    let y1 = sin(angle) * radius;

    // Couleur qui évolue
    let c = lerpColor(c1, c2, progress);

    // Épaisseur qui varie
    let sw = map(progress, 0, 1, thickness * 3, thickness * 0.5);
    sw += sin(progress * TWO_PI * 5) * 2;

    // Transparence
    let alpha = map(progress, 0, 1, 250, 100);
    fill(red(c), green(c), blue(c), alpha);
    noStroke();

    circle(x1, y1, sw);

    // Halo lumineux
    fill(red(c), green(c), blue(c), alpha * 0.2);
    circle(x1, y1, sw * 2.5);
  }
}

function drawParticles() {
  for (let i = 0; i < 300; i++) {
    let angle = random(TWO_PI);
    let radius = random(50, 700);
    let x = cos(angle) * radius;
    let y = sin(angle) * radius;

    let size = random(2, 8);
    let noiseVal = noise(x * 0.01, y * 0.01);

    // Couleurs dorées et lumineuses
    if (noiseVal > 0.5) {
      fill(255, 220, 150, random(100, 200));
    } else {
      fill(255, 255, 255, random(80, 150));
    }

    noStroke();
    circle(x, y, size);

    // Petit halo
    fill(255, 255, 255, 30);
    circle(x, y, size * 2);
  }
}

function drawCenter() {
  // Point de fusion au centre
  let layers = 15;

  for (let i = layers; i > 0; i--) {
    let size = map(i, 0, layers, 0, 100);
    let alpha = map(i, 0, layers, 200, 20);

    // Mélange des deux couleurs au centre
    let r = map(i, 0, layers, 220, 150);
    let g = map(i, 0, layers, 80, 110);
    let b = map(i, 0, layers, 120, 170);

    fill(r, g, b, alpha);
    noStroke();
    circle(0, 0, size);
  }

  // Lumière centrale
  for (let i = 8; i > 0; i--) {
    let size = map(i, 0, 8, 0, 60);
    let alpha = map(i, 0, 8, 150, 10);
    fill(255, 240, 200, alpha);
    circle(0, 0, size);
  }

  // Rayons qui partent du centre
  for (let i = 0; i < 12; i++) {
    let angle = (TWO_PI / 12) * i;
    strokeWeight(2);

    for (let j = 0; j < 100; j++) {
      let dist = j * 5;
      let alpha = map(j, 0, 100, 150, 0);
      stroke(255, 240, 200, alpha);

      let x1 = cos(angle) * dist;
      let y1 = sin(angle) * dist;
      let x2 = cos(angle) * (dist + 3);
      let y2 = sin(angle) * (dist + 3);

      line(x1, y1, x2, y2);
    }
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  background(15, 12, 25);

  // Deux essences qui s'entrelacent
  let centerX = width / 2;
  let centerY = height / 2;

  // Première essence - chaude (rouge orangé)
  drawEssence(centerX - 200, centerY, 
              [255, 100, 80], [255, 180, 100], 
              0, 400, 600);

  // Deuxième essence - fraîche (bleu violet)
  drawEssence(centerX + 200, centerY, 
              [80, 100, 255], [150, 100, 255], 
              PI, 400, 600);

  // Zone de fusion - lumière partagée
  drawFusion(centerX, centerY);

  // Particules d'union
  drawParticles(centerX, centerY);
}

function drawEssence(x, y, color1, color2, rotation, w, h) {
  push();
  translate(x, y);
  rotate(rotation);

  // Corps principal fluide
  for (let i = 0; i < 80; i++) {
    let t = i / 80;
    let alpha = 15 + sin(t * PI) * 25;

    let col = lerpColor(
      color(color1[0], color1[1], color1[2], alpha),
      color(color2[0], color2[1], color2[2], alpha),
      t
    );

    noStroke();
    fill(col);

    let yPos = map(t, 0, 1, -h/2, h/2);
    let xWidth = w/2 * sin(t * PI) * (1 + noise(t * 3) * 0.3);

    for (let j = 0; j < 20; j++) {
      let angle = map(j, 0, 20, -PI, PI);
      let r = xWidth * (1 + noise(t * 5, j * 0.1) * 0.4);
      let px = cos(angle) * r;
      let py = yPos + sin(angle) * r * 0.3;

      ellipse(px, py, 40, 40);
    }
  }

  // Flux interne
  for (let i = 0; i < 150; i++) {
    let t = i / 150;
    let yPos = map(t, 0, 1, -h/2, h/2);
    let xOff = noise(t * 8, i * 0.01) * 100 - 50;

    let col = lerpColor(
      color(color1[0], color1[1], color1[2], 60),
      color(color2[0], color2[1], color2[2], 30),
      noise(t * 3)
    );

    fill(col);
    noStroke();
    let size = 3 + noise(t * 10) * 8;
    ellipse(xOff, yPos, size, size);
  }

  pop();
}

function drawFusion(x, y) {
  push();
  translate(x, y);

  // Halo de fusion
  for (let i = 0; i < 100; i++) {
    let radius = map(i, 0, 100, 10, 350);
    let alpha = map(i, 0, 100, 40, 0);

    // Couleur mixte
    fill(220, 180, 180, alpha);
    noStroke();
    ellipse(0, 0, radius, radius);
  }

  // Vagues de connexion
  for (let r = 0; r < 300; r += 20) {
    noFill();

    for (let a = 0; a < TWO_PI; a += 0.1) {
      let n = noise(r * 0.01, a * 2, frameCount * 0.01);
      let rad = r + n * 30;
      let alpha = map(r, 0, 300, 50, 5);

      stroke(255, 220, 200, alpha);
      strokeWeight(2);

      let x1 = cos(a) * rad;
      let y1 = sin(a) * rad;
      let x2 = cos(a + 0.1) * rad;
      let y2 = sin(a + 0.1) * rad;

      line(x1, y1, x2, y2);
    }
  }

  // Centre lumineux
  for (let i = 0; i < 30; i++) {
    let radius = map(i, 0, 30, 5, 80);
    let alpha = map(i, 0, 30, 100, 0);
    fill(255, 240, 200, alpha);
    noStroke();
    ellipse(0, 0, radius, radius);
  }

  pop();
}

function drawParticles(x, y) {
  // Particules flottantes symbolisant les moments partagés
  for (let i = 0; i < 300; i++) {
    let angle = noise(i * 0.1) * TWO_PI;
    let radius = 200 + noise(i * 0.2, 100) * 500;

    let px = x + cos(angle) * radius;
    let py = y + sin(angle) * radius;

    let n = noise(i * 0.3);
    let col;
    if (n < 0.4) {
      col = color(255, 120, 100, 150);
    } else if (n < 0.7) {
      col = color(120, 120, 255, 150);
    } else {
      col = color(255, 240, 200, 180);
    }

    fill(col);
    noStroke();
    let size = 2 + noise(i * 0.5) * 6;
    ellipse(px, py, size, size);

    // Petit halo
    fill(red(col), green(col), blue(col), 30);
    ellipse(px, py, size * 3, size * 3);
  }

  // Fils de connexion subtils
  for (let i = 0; i < 50; i++) {
    let angle1 = noise(i * 0.15) * TWO_PI;
    let angle2 = noise(i * 0.15 + 50) * TWO_PI;
    let r1 = 250 + noise(i * 0.25) * 400;
    let r2 = 250 + noise(i * 0.25 + 100) * 400;

    let x1 = x + cos(angle1) * r1;
    let y1 = y + sin(angle1) * r1;
    let x2 = x + cos(angle2) * r2;
    let y2 = y + sin(angle2) * r2;

    stroke(255, 220, 200, 15);
    strokeWeight(1);
    line(x1, y1, x2, y2);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  background(15, 10, 25);

  // Couches de fond atmosphériques
  for (let i = 0; i < 50; i++) {
    let y = map(i, 0, 50, 0, height);
    let alpha = map(i, 0, 50, 0, 30);
    noStroke();
    fill(30, 15, 40, alpha);
    rect(0, y, width, 40);
  }

  // Particules lumineuses en arrière-plan
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = random(height);
    let size = random(1, 4);
    let alpha = random(30, 100);
    noStroke();
    fill(255, 200, 150, alpha);
    ellipse(x, y, size, size);
  }

  // Deux formes organiques principales qui s'entrelacent
  drawOrganicForm(600, 800, 400, 500, color(180, 60, 80), color(220, 90, 110), 0);
  drawOrganicForm(1000, 900, 420, 520, color(60, 100, 140), color(90, 140, 180), PI / 6);

  // Zone de fusion centrale
  drawFusionZone(800, 950, 350);

  // Fils de connexion subtils
  drawConnectionThreads();

  // Lumière émanante
  drawRadiance(800, 950);

  // Texture organique finale
