}

function drawOrganicForm(x, y, w, h, c1, c2, rotation) {
  push();
  translate(x, y);
  rotate(rotation);

  // Forme principale avec dégradé
  for (let i = 0; i < 40; i++) {
    let t = i / 40;
    let currentColor = lerpColor(c1, c2, t);
    fill(red(currentColor), green(currentColor), blue(currentColor), 180 - i * 3);
    noStroke();

    beginShape();
    for (let angle = 0; angle < TWO_PI; angle += 0.1) {
      let offset = noise(cos(angle) * 2, sin(angle) * 2, t) * 80;
      let r1 = w / 2 + offset * cos(angle * 3);
      let r2 = h / 2 + offset * sin(angle * 2);
      let px = r1 * cos(angle);
      let py = r2 * sin(angle);
      vertex(px * (1 - t * 0.1), py * (1 - t * 0.1));
    }
    endShape(CLOSE);
  }

  // Détails internes
  for (let j = 0; j < 30; j++) {
    let angle = random(TWO_PI);
    let radius = random(50, 150);
    let px = cos(angle) * radius;
    let py = sin(angle) * radius;

    stroke(red(c2), green(c2), blue(c2), 60);
    strokeWeight(random(1, 3));
    noFill();

    let size = random(10, 40);
    ellipse(px, py, size, size);
  }

  pop();
}

function drawFusionZone(x, y, size) {
  push();
  translate(x, y);

  // Halo lumineux
  for (let i = 0; i < 60; i++) {
    let t = i / 60;
    let r = size * (1 - t);
    noStroke();
    fill(255, 180, 120, 100 * (1 - t));
    ellipse(0, 0, r * 2, r * 2);
  }

  // Formes entrelacées au centre
  for (let i = 0; i < 50; i++) {
    let angle = map(i, 0, 50, 0, TWO_PI * 3);
    let radius = map(i, 0, 50, 0, size);
    let x1 = cos(angle) * radius;
    let y1 = sin(angle) * radius;
    let x2 = cos(angle + PI) * radius * 0.7;
    let y2 = sin(angle + PI) * radius * 0.7;

    stroke(255, 150, 180, 150);
    strokeWeight(2);
    line(x1, y1, x2, y2);
  }

  // Points d'énergie
  for (let i = 0; i < 100; i++) {
    let angle = random(TWO_PI);
    let radius = randomGaussian(0, size / 3);
    let px = cos(angle) * radius;
    let py = sin(angle) * radius;

    noStroke();
    fill(255, 200, 100, random(100, 200));
    ellipse(px, py, random(2, 6), random(2, 6));
  }

  pop();
}

function drawConnectionThreads() {
  stroke(200, 180, 220, 80);
  strokeWeight(1);
  noFill();

  for (let i = 0; i < 80; i++) {
    let x1 = 600 + random(-200, 200);
    let y1 = 800 + random(-300, 300);
    let x2 = 1000 + random(-200, 200);
    let y2 = 900 + random(-300, 300);

    bezier(
      x1, y1,
      x1 + random(-100, 300), y1 + random(-200, 200),
      x2 + random(-300, 100), y2 + random(-200, 200),
      x2, y2
    );
  }
}

function drawRadiance(x, y) {
  push();
  translate(x, y);

  // Rayons de lumière
  for (let i = 0; i < 30; i++) {
    let angle = random(TWO_PI);
    let length = random(300, 600);

    for (let j = 0; j < 20; j++) {
      let t = j / 20;
      let currentLength = length * t;
      let thickness = map(t, 0, 1, 15, 0);

      stroke(255, 220, 180, 50 * (1 - t));
      strokeWeight(thickness);

      let x1 = 0;
      let y1 = 0;
      let x2 = cos(angle) * currentLength;
      let y2 = sin(angle) * currentLength;

      line(x1, y1, x2, y2);
    }
  }

  pop();
}

function drawOrganicTexture() {
  // Texture atmosphérique finale
  for (let i = 0; i < 2000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.01, y * 0.01);

    if (n > 0.5) {
      noStroke();
      fill(255, 200, 220, random(10, 40));
      ellipse(x, y, random(1, 3), random(1, 3));
    }
  }

  // Voiles de couleur
  for (let i = 0; i < 5; i++) {
    let x = random(width);
    let y = random(height);
    let size = random(200, 500);

    noStroke();
    fill(random(180, 255), random(100, 200), random(150, 220), 15);
    ellipse(x, y, size, size);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  background(245, 240, 235);

  // Deux centres pour les deux essences
  let center1 = {x: 650, y: 1000};
  let center2 = {x: 950, y: 1000};

  // Dessiner les couches de fond atmosphériques
  for(let i = 0; i < 100; i++) {
    let alpha = map(i, 0, 100, 2, 0);
    let radius = map(i, 0, 100, 800, 100);

    // Essence chaude (orange/rouge)
    fill(220, 100, 80, alpha);
    noStroke();
    ellipse(center1.x, center1.y, radius, radius);

    // Essence fraîche (bleu/violet)
    fill(80, 120, 180, alpha);
    ellipse(center2.x, center2.y, radius, radius);
  }

  // Particules dansantes représentant l'énergie entre les deux
  for(let i = 0; i < 3000; i++) {
    let angle = random(TWO_PI);
    let r = randomGaussian(0, 200);
    let x = 800 + cos(angle) * r;
    let y = 1000 + sin(angle) * r;

    let d1 = dist(x, y, center1.x, center1.y);
    let d2 = dist(x, y, center2.x, center2.y);

    // Zone d'entrelacement
    if(d1 < 400 && d2 < 400) {
      let mixFactor = d1 / (d1 + d2);
      let r = lerp(220, 80, mixFactor);
      let g = lerp(100, 120, mixFactor);
      let b = lerp(80, 180, mixFactor);

      let size = map(d1 + d2, 0, 800, 8, 1);
      let alpha = map(d1 + d2, 0, 800, 40, 5);

      fill(r, g, b, alpha);
      noStroke();
      ellipse(x, y, size, size);
    }
  }

  // Lignes de flux organiques entre les deux centres
  for(let i = 0; i < 150; i++) {
    let startAngle = random(TWO_PI);
    let startDist = random(50, 300);
    let x1 = center1.x + cos(startAngle) * startDist;
    let y1 = center1.y + sin(startAngle) * startDist;

    let endAngle = random(TWO_PI);
    let endDist = random(50, 300);
    let x2 = center2.x + cos(endAngle) * endDist;
    let y2 = center2.y + sin(endAngle) * endDist;

    // Courbe de Bézier pour le flux
    let cx1 = lerp(x1, x2, 0.3) + random(-100, 100);
    let cy1 = lerp(y1, y2, 0.3) + random(-100, 100);
    let cx2 = lerp(x1, x2, 0.7) + random(-100, 100);
    let cy2 = lerp(y1, y2, 0.7) + random(-100, 100);

    noFill();
    stroke(150, 100, 130, random(5, 20));
    strokeWeight(random(0.5, 2));
    bezier(x1, y1, cx1, cy1, cx2, cy2, x2, y2);
  }

  // Formes organiques principales - essence 1 (chaude)
  for(let layer = 0; layer < 50; layer++) {
    let baseRadius = map(layer, 0, 50, 350, 50);
    beginShape();
    for(let a = 0; a < TWO_PI + 0.1; a += 0.1) {
      let xoff = cos(a) * 2;
      let yoff = sin(a) * 2;
      let n = noise(xoff + layer * 0.1, yoff + layer * 0.1);
      let r = baseRadius + map(n, 0, 1, -50, 50);
      let x = center1.x + cos(a) * r;
      let y = center1.y + sin(a) * r;
      vertex(x, y);
    }
    endShape(CLOSE);

    let alpha = map(layer, 0, 50, 15, 3);
    fill(220, 100, 80, alpha);
    noStroke();
    beginShape();
    for(let a = 0; a < TWO_PI + 0.1; a += 0.1) {
      let xoff = cos(a) * 2;
      let yoff = sin(a) * 2;
      let n = noise(xoff + layer * 0.1, yoff + layer * 0.1);
      let r = baseRadius + map(n, 0, 1, -50, 50);
      let x = center1.x + cos(a) * r;
      let y = center1.y + sin(a) * r;
      vertex(x, y);
    }
    endShape(CLOSE);
  }

  // Formes organiques principales - essence 2 (fraîche)
  for(let layer = 0; layer < 50; layer++) {
    let baseRadius = map(layer, 0, 50, 350, 50);
    beginShape();
    for(let a = 0; a < TWO_PI + 0.1; a += 0.1) {
      let xoff = cos(a) * 2 + 10;
      let yoff = sin(a) * 2 + 10;
      let n = noise(xoff + layer * 0.1, yoff + layer * 0.1);
      let r = baseRadius + map(n, 0, 1, -50, 50);
      let x = center2.x + cos(a) * r;
      let y = center2.y + sin(a) * r;
      vertex(x, y);
    }
    endShape(CLOSE);

    let alpha = map(layer, 0, 50, 15, 3);
    fill(80, 120, 180, alpha);
    noStroke();
    beginShape();
    for(let a = 0; a < TWO_PI + 0.1; a += 0.1) {
      let xoff = cos(a) * 2 + 10;
      let yoff = sin(a) * 2 + 10;
      let n = noise(xoff + layer * 0.1, yoff + layer * 0.1);
      let r = baseRadius + map(n, 0, 1, -50, 50);
      let x = center2.x + cos(a) * r;
      let y = center2.y + sin(a) * r;
      vertex(x, y);
    }
    endShape(CLOSE);
  }

  // Points lumineux dans la zone d'union
  for(let i = 0; i < 200; i++) {
    let x = 800 + randomGaussian(0, 100);
    let y = 1000 + randomGaussian(0, 100);

    let d1 = dist(x, y, center1.x, center1.y);
    let d2 = dist(x, y, center2.x, center2.y);

    if(d1 < 350 && d2 < 350) {
      let size = random(2, 12);
      let alpha = random(60, 150);
      fill(255, 255, 220, alpha);
      noStroke();
      ellipse(x, y, size, size);

      // Halo
      fill(255, 255, 220, alpha * 0.2);
      ellipse(x, y, size * 2, size * 2);
    }
  }

  // Texture de surface subtile
  for(let i = 0; i < 5000; i++) {
    let x = random(width);
    let y = random(height);
    let d1 = dist(x, y, center1.x, center1.y);
    let d2 = dist(x, y, center2.x, center2.y);

    if(d1 < 500 || d2 < 500) {
      stroke(random(100, 200), random(1, 3));
      strokeWeight(random(0.5, 1.5));
      point(x, y);
    }
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  background(15, 12, 25);

  // Particules d'ambiance
  for (let i = 0; i < 800; i++) {
    let x = random(width);
    let y = random(height);
    let size = random(0.5, 2.5);
    let alpha = random(30, 120);
    fill(255, 240, 200, alpha);
    noStroke();
    circle(x, y, size);
  }

  // Les deux forces entrelacées
  let centerX = width / 2;
  let startY = height * 0.85;
  let endY = height * 0.15;

  // Spirale rouge (chaleur, passion)
  drawSpiralForce(centerX, startY, endY, 0, color(220, 40, 60), color(255, 180, 100));

  // Spirale bleue (profondeur, tendresse)
  drawSpiralForce(centerX, startY, endY, PI, color(40, 80, 180), color(120, 200, 255));

  // Lumière naissante au sommet
  drawGlow(centerX, endY - 100);

  // Particules ascendantes
  for (let i = 0; i < 300; i++) {
    let progress = random(1);
    let y = lerp(startY, endY - 200, progress);
    let x = centerX + sin(progress * TWO_PI * 4 + random(TWO_PI)) * random(50, 200) * (1 - progress * 0.7);
    let size = random(1, 4) * (1 - progress * 0.5);
    let alpha = random(50, 150) * progress;

    if (random(1) > 0.5) {
      fill(255, 180, 120, alpha);
    } else {
      fill(150, 200, 255, alpha);
    }
    noStroke();
    circle(x, y, size);
  }
}

function drawSpiralForce(centerX, startY, endY, angleOffset, col1, col2) {
  let steps = 1000;

  for (let i = 0; i < steps; i++) {
    let progress = i / steps;
    let y = lerp(startY, endY, progress);

    // Rotation et expansion
    let rotations = 6;
    let angle = angleOffset + progress * TWO_PI * rotations;
    let radius = 80 + sin(progress * PI) * 150;

    // Ajout de variation organique
    let noiseVal = noise(progress * 3, angleOffset) * 30;
    radius += noiseVal;

    let x = centerX + cos(angle) * radius;

    // Couleur qui évolue
    let col = lerpColor(col1, col2, progress);

    // Épaisseur qui varie
    let thickness = 8 + sin(progress * PI * 2) * 6;

    // Dessin avec halo
    for (let j = 3; j > 0; j--) {
      stroke(red(col), green(col), blue(col), 40 / j);
      strokeWeight(thickness * j * 1.5);
      if (i > 0) {
        let prevProgress = (i - 1) / steps;
        let prevY = lerp(startY, endY, prevProgress);
        let prevAngle = angleOffset + prevProgress * TWO_PI * rotations;
        let prevRadius = 80 + sin(prevProgress * PI) * 150;
        prevRadius += noise(prevProgress * 3, angleOffset) * 30;
        let prevX = centerX + cos(prevAngle) * prevRadius;

        line(prevX, prevY, x, y);
      }
    }

    // Ligne centrale brillante
    stroke(col);
    strokeWeight(thickness);
    if (i > 0) {
      let prevProgress = (i - 1) / steps;
      let prevY = lerp(startY, endY, prevProgress);
      let prevAngle = angleOffset + prevProgress * TWO_PI * rotations;
      let prevRadius = 80 + sin(prevProgress * PI) * 150;
      prevRadius += noise(prevProgress * 3, angleOffset) * 30;
      let prevX = centerX + cos(prevAngle) * prevRadius;

      line(prevX, prevY, x, y);
    }
  }
}

function drawGlow(x, y) {
  noStroke();

  // Grand halo externe
  for (let r = 400; r > 0; r -= 10) {
    let alpha = map(r, 0, 400, 80, 0);
    fill(255, 240, 180, alpha);
    circle(x, y, r);
  }

  // Coeur lumineux
  for (let r = 150; r > 0; r -= 5) {
    let alpha = map(r, 0, 150, 200, 0);
    fill(255, 250, 220, alpha);
    circle(x, y, r);
  }

  // Point central brillant
  fill(255, 255, 240);
  circle(x, y, 30);

  // Rayons
  for (let a = 0; a < TWO_PI; a += TWO_PI / 24) {
    let len = 100 + noise(a * 10) * 80;
    stroke(255, 240, 200, 150);
    strokeWeight(2);
    let x2 = x + cos(a) * len;
    let y2 = y + sin(a) * len;
    line(x, y, x2, y2);

    // Extrémités des rayons
    noStroke();
    fill(255, 240, 200, 180);
    circle(x2, y2, 8);
  }
}

