function drawGlowBackground() {
  // 中心温暖光晕
  for (let i = 0; i < 8; i++) {
    let alpha = 15 - i * 1.5;
    let size = 800 + i * 150;

    // 橙色光晕
    fill(255, 180, 120, alpha);
    noStroke();
    ellipse(800, 1000, size, size);

    // 粉色光晕
    fill(255, 150, 180, alpha);
    ellipse(800, 1000, size * 0.8, size * 0.8);
  }
}

function drawFloatingLights() {
  for (let i = 0; i < 100; i++) {
    let x = random(width);
    let y = random(height);
    let size = random(3, 20);
    let hue = random(20, 40);

    // 柔和的光点
    for (let j = 0; j < 3; j++) {
      let alpha = 20 - j * 6;
      let s = size + j * 8;
      fill(255, 200 - hue * 2, 100 + hue, alpha);
      noStroke();
      ellipse(x, y, s, s);
    }
  }
}

function drawEmbracingFigures() {
  push();
  translate(800, 1000);

  // 左侧人形
  drawFigure(-150, 0, 1, color(255, 160, 140, 180));

  // 右侧人形
  drawFigure(150, 0, -1, color(255, 180, 160, 180));

  // 绘制拥抱的手臂
  drawArms();

  // 中心连接的心形能量
  drawHeartEnergy();

  pop();
}

function drawFigure(x, y, direction, col) {
  push();
  translate(x, y);
  scale(direction, 1);

  // 身体
  fill(col);
  noStroke();
  beginShape();
  for (let angle = 0; angle < TWO_PI; angle += 0.1) {
    let r = 80 + sin(angle * 3) * 5;
    let px = cos(angle) * r * 0.6;
    let py = sin(angle) * r + 100;
    vertex(px, py);
  }
  endShape(CLOSE);

  // 头部
  fill(col);
  ellipse(0, -50, 120, 140);

  // 柔和边缘光晕
  for (let i = 0; i < 3; i++) {
    noFill();
    stroke(255, 200, 150, 30 - i * 8);
    strokeWeight(8 - i * 2);
    ellipse(0, -50, 130 + i * 10, 150 + i * 10);
  }

  pop();
}

function drawArms() {
  stroke(255, 170, 150, 150);
  strokeWeight(25);
  noFill();

  // 左侧人物的手臂环绕
  beginShape();
  vertex(-150, 50);
  bezierVertex(-100, 100, 50, 150, 180, 100);
  endShape();

  // 右侧人物的手臂环绕
  beginShape();
  vertex(150, 50);
  bezierVertex(100, 100, -50, 150, -180, 100);
  endShape();

  // 手臂光晕
  strokeWeight(35);
  stroke(255, 200, 180, 50);
  beginShape();
  vertex(-150, 50);
  bezierVertex(-100, 100, 50, 150, 180, 100);
  endShape();

  beginShape();
  vertex(150, 50);
  bezierVertex(100, 100, -50, 150, -180, 100);
  endShape();
}

function drawHeartEnergy() {
  // 中心发光能量
  for (let i = 0; i < 50; i++) {
    let angle = random(TWO_PI);
    let r = random(30, 100);
    let x = cos(angle) * r;
    let y = sin(angle) * r;
    let size = random(2, 8);

    fill(255, 220, 150, random(80, 150));
    noStroke();
    ellipse(x, y, size, size);
  }

  // 核心光芒
  for (let i = 0; i < 5; i++) {
    fill(255, 240, 200, 40 - i * 6);
    ellipse(0, 0, 150 - i * 20, 150 - i * 20);
  }
}

function drawForegroundParticles() {
