  ellipse(800, 1700, 1200, 400);

  // 绘制两棵相依的树
  drawTree(650, 1600, -15, 180, 12);
  drawTree(950, 1600, 15, 180, 12);

  // 绘制交织的枝干（象征连接）
  stroke(100, 80, 60);
  strokeWeight(4);
  noFill();
  bezier(650, 1400, 750, 1200, 850, 1200, 950, 1400);
  bezier(680, 1300, 750, 1150, 850, 1150, 920, 1300);

  // 绘制心形的叶子簇
  drawHeartLeaves(800, 800);

  // 添加飘落的叶子
  for (let i = 0; i < 30; i++) {
    let x = random(200, 1400);
    let y = random(200, 1400);
    let size = random(8, 20);
    drawLeaf(x, y, size, random(TWO_PI));
  }

  // 添加光点
  for (let i = 0; i < 50; i++) {
    let x = random(width);
    let y = random(height * 0.6);
    let size = random(2, 6);
    noStroke();
    fill(255, 220, 150, random(100, 200));
    ellipse(x, y, size, size);
  }
}

function drawTree(x, y, angle, length, depth) {
  if (depth === 0) return;

  push();
  translate(x, y);
  rotate(radians(angle));

  let weight = map(depth, 0, 12, 1, 15);
  strokeWeight(weight);
  stroke(80 + depth * 5, 60 + depth * 3, 40 + depth * 2);
  line(0, 0, 0, -length);

  translate(0, -length);

  if (depth > 3) {
    drawTree(0, 0, angle - 25, length * 0.7, depth - 1);
    drawTree(0, 0, angle + 25, length * 0.7, depth - 1);

    if (random() > 0.6) {
      drawTree(0, 0, angle - 15, length * 0.6, depth - 1);
    }
  }

  // 在枝头添加叶子
  if (depth <= 4) {
    for (let i = 0; i < 3; i++) {
      let lx = random(-20, 20);
      let ly = random(-20, 20);
      drawLeaf(lx, ly, random(10, 18), random(TWO_PI));
    }
  }

  pop();
}

function drawLeaf(x, y, size, angle) {
  push();
  translate(x, y);
  rotate(angle);

  noStroke();
  fill(100, 150, 80, 180);
  ellipse(0, 0, size, size * 1.5);

  fill(120, 170, 100, 150);
  ellipse(-size * 0.2, 0, size * 0.6, size * 1.2);

  pop();
}

function drawHeartLeaves(centerX, centerY) {
  push();
  translate(centerX, centerY);

  // 绘制心形轮廓
  for (let angle = 0; angle < TWO_PI; angle += 0.1) {
    let t = angle;
    let x = 16 * pow(sin(t), 3) * 8;
    let y = -(13 * cos(t) - 5 * cos(2 * t) - 2 * cos(3 * t) - cos(4 * t)) * 8;

    // 在心形路径上绘制叶子
    if (random() > 0.7) {
      drawLeaf(x, y, random(15, 25), random(TWO_PI));
    }
  }

  // 填充心形内部的叶子
  for (let i = 0; i < 80; i++) {
    let angle = random(TWO_PI);
    let r = random(50, 120);
    let x = r * cos(angle);
    let y = r * sin(angle) - 30;

    if (y < 0 || abs(x) < 80) {
      drawLeaf(x, y, random(12, 22), random(TWO_PI));
    }
  }

  pop();
}

