function drawFigure(x, y, rotation, col) {
  push();
  translate(x, y);
  rotate(radians(rotation));

  // 头部
  fill(col);
  noStroke();
  ellipse(0, -180, 120, 140);

  // 颈部
  beginShape();
  vertex(-25, -120);
  vertex(25, -120);
  vertex(30, -80);
  vertex(-30, -80);
  endShape(CLOSE);

  // 身体
  beginShape();
  vertex(-30, -80);
  bezierVertex(-40, 0, -35, 100, -40, 200);
  vertex(40, 200);
  bezierVertex(35, 100, 40, 0, 30, -80);
  endShape(CLOSE);

  // 左臂
  push();
  translate(-30, -40);
  rotate(radians(-30));
  beginShape();
  vertex(0, 0);
  bezierVertex(-15, 50, -10, 100, -5, 150);
  vertex(5, 150);
  bezierVertex(0, 100, 5, 50, 0, 0);
  endShape(CLOSE);
  pop();

  // 右臂（环抱状）
  push();
  translate(30, -40);
  rotate(radians(45));
  beginShape();
  vertex(0, 0);
  bezierVertex(15, 50, 10, 100, 5, 150);
  vertex(-5, 150);
  bezierVertex(0, 100, -5, 50, 0, 0);
  endShape(CLOSE);
  pop();

  // 添加柔和边缘
  drawingContext.filter = 'blur(3px)';
  fill(col);
  ellipse(0, -180, 110, 130);
  drawingContext.filter = 'none';

  pop();
}

function drawHeartEnergy() {
  // 中心发光的心形能量
  for(let i = 0; i < 50; i++) {
    let offset = i * 8;
    let alpha = map(i, 0, 50, 100, 0);
    noFill();
    stroke(255, 180, 150, alpha);
    strokeWeight(2);

    beginShape();
    for(let a = 0; a < TWO_PI; a += 0.1) {
      let r = 80 + offset;
      let x = r * 16 * pow(sin(a), 3) / 16;
      let y = -r * (13 * cos(a) - 5 * cos(2*a) - 2 * cos(3*a) - cos(4*a)) / 16;
      vertex(x, y - 50);
    }
    endShape(CLOSE);
  }

  // 中心光点
  for(let i = 0; i < 30; i++) {
    let angle = random(TWO_PI);
    let radius = random(40, 120);
    let x = cos(angle) * radius;
    let y = sin(angle) * radius - 50;
    let size = random(3, 10);
    fill(255, 200, 100, random(80, 150));
    noStroke();
    ellipse(x, y, size, size);
  }
}

function drawLoveParticles() {
  // 漂浮的能量粒子
  for(let i = 0; i < 100; i++) {
    let angle = (i / 100) * TWO_PI * 3;
    let radius = 200 + noise(i * 0.1) * 200;
    let x = cos(angle) * radius;
    let y = sin(angle) * radius + noise(i * 0.2) * 100;

    let size = noise(i * 0.5) * 15 + 3;
    let alpha = noise(i * 0.3) * 150 + 50;

    noStroke();
    fill(255, 220, 180, alpha);
    ellipse(x, y, size, size);

    // 添加光晕
    fill(255, 180, 120, alpha * 0.3);
    ellipse(x, y, size * 2, size * 2);
  }

  // 连接线条
  stroke(255, 200, 150, 30);
  strokeWeight(1);
  for(let i = 0; i < 50; i++) {
    let angle1 = (i / 50) * TWO_PI;
    let angle2 = ((i + 1) / 50) * TWO_PI;
    let r1 = 250 + noise(i * 0.1) * 100;
    let r2 = 250 + noise((i + 1) * 0.1) * 100;

    let x1 = cos(angle1) * r1;
    let y1 = sin(angle1) * r1;
    let x2 = cos(angle2) * r2;
    let y2 = sin(angle2) * r2;

    line(x1, y1, x2, y2);
  }
}

