function drawFlowingLove() {
  // 左侧流动（温暖的红色系）
  for (let i = 0; i < 150; i++) {
    let startX = 200 + randomGaussian() * 80;
    let startY = 300 + randomGaussian() * 100;

    let points = [];
    let x = startX;
    let y = startY;

    for (let j = 0; j < 200; j++) {
      let angle = noise(x * 0.003, y * 0.003, i * 0.1) * TWO_PI * 3;
      let pullX = (width / 2 - x) * 0.0008;
      let pullY = (height / 2 + 200 - y) * 0.0005;

      x += cos(angle) * 3 + pullX * 10;
      y += sin(angle) * 3 + pullY * 10;

      points.push({x: x, y: y});
    }

    noFill();
    for (let k = 0; k < points.length - 1; k++) {
      let progress = k / points.length;
      let alpha = 15 * (1 - progress * 0.5);
      stroke(220, 80 + progress * 50, 90, alpha);
      strokeWeight(2 + random() * 3);
      line(points[k].x, points[k].y, points[k + 1].x, points[k + 1].y);
    }
  }

  // 右侧流动（温暖的橙黄色系）
  for (let i = 0; i < 150; i++) {
    let startX = 1400 + randomGaussian() * 80;
    let startY = 400 + randomGaussian() * 100;

    let points = [];
    let x = startX;
    let y = startY;

    for (let j = 0; j < 200; j++) {
      let angle = noise(x * 0.003 + 100, y * 0.003 + 100, i * 0.1) * TWO_PI * 3;
      let pullX = (width / 2 - x) * 0.0008;
      let pullY = (height / 2 + 200 - y) * 0.0005;

      x += cos(angle) * 3 + pullX * 10;
      y += sin(angle) * 3 + pullY * 10;

      points.push({x: x, y: y});
    }

    noFill();
    for (let k = 0; k < points.length - 1; k++) {
      let progress = k / points.length;
      let alpha = 15 * (1 - progress * 0.5);
      stroke(240, 160 + progress * 30, 70, alpha);
      strokeWeight(2 + random() * 3);
      line(points[k].x, points[k].y, points[k + 1].x, points[k + 1].y);
    }
  }

  // 中心交织区域
  for (let i = 0; i < 200; i++) {
    let angle = random(TWO_PI);
    let radius = randomGaussian() * 120 + 150;
    let startX = width / 2 + cos(angle) * radius;
    let startY = height / 2 + 200 + sin(angle) * radius;

    let points = [];
    let x = startX;
    let y = startY;

    for (let j = 0; j < 150; j++) {
      let flowAngle = noise(x * 0.004, y * 0.004, i * 0.05 + 500) * TWO_PI * 4;
      let pullX = (width / 2 - x) * 0.0003;
      let pullY = (height / 2 + 200 - y) * 0.0003;

      x += cos(flowAngle) * 2 + pullX * 5;
      y += sin(flowAngle) * 2 + pullY * 5;

      points.push({x: x, y: y});
    }

    noFill();
    for (let k = 0; k < points.length - 1; k++) {
      let progress = k / points.length;
      let alpha = 20 * (1 - progress * 0.6);

      let mixRatio = noise(points[k].x * 0.005, points[k].y * 0.005);
      let r = lerp(220, 240, mixRatio);
      let g = lerp(80, 160, mixRatio);
      let b = lerp(90, 70, mixRatio);

      stroke(r, g, b, alpha);
      strokeWeight(1.5 + random() * 2.5);
      line(points[k].x, points[k].y, points[k + 1].x, points[k + 1].y);
    }
  }
}

function drawParticles() {
  for (let i = 0; i < 3000; i++) {
    let x = random(width);
    let y = random(height);

    let distToCenter = dist(x, y, width / 2, height / 2 + 200);
    let intensity = map(distToCenter, 0, 800, 1, 0);
    intensity = constrain(intensity, 0, 1);

    if (random() < intensity * 0.6) {
      let noiseVal = noise(x * 0.01, y * 0.01);

      if (noiseVal < 0.4) {
        fill(220, 90, 100, random(60, 120));
      } else if (noiseVal > 0.6) {
        fill(240, 170, 80, random(60, 120));
      } else {
        fill(230, 130, 90, random(80, 150));
      }

      noStroke();
      let size = random(1, 4) * intensity;
      circle(x, y, size);
    }
  }
}

