function drawOrganicForm(x, y, size, c1, c2, offset) {
  push();
  translate(x, y);

  // 多层叠加创造深度
  for (let layer = 0; layer < 5; layer++) {
    let layerSize = size + layer * 20;
    let alpha = 30 - layer * 5;

    fill(red(c2), green(c2), blue(c2), alpha);
    noStroke();

    beginShape();
    for (let angle = 0; angle < TWO_PI; angle += 0.1) {
      let xoff = cos(angle) * 2 + offset;
      let yoff = sin(angle) * 2;
      let r = layerSize * (0.8 + noise(xoff, yoff, layer * 0.1) * 0.4);
      let px = r * cos(angle);
      let py = r * sin(angle);
      vertex(px, py);
    }
    endShape(CLOSE);
  }

  // 核心
  fill(c1);
  noStroke();
  beginShape();
  for (let angle = 0; angle < TWO_PI; angle += 0.1) {
    let xoff = cos(angle) * 2 + offset;
    let yoff = sin(angle) * 2;
    let r = size * 0.6 * (0.85 + noise(xoff, yoff) * 0.3);
    let px = r * cos(angle);
    let py = r * sin(angle);
    vertex(px, py);
  }
  endShape(CLOSE);

  pop();
}

function drawIntersectionTexture() {
  push();
  // 中心交融区域的细腻渐变
  for (let i = 0; i < 3000; i++) {
    let x = 800 + randomGaussian(0, 180);
    let y = 1000 + randomGaussian(0, 200);

    let d1 = dist(x, y, 500, 1000);
    let d2 = dist(x, y, 1100, 1000);

    if (d1 < 400 && d2 < 400) {
      let blend = map(x, 500, 1100, 0, 1);
      let r = lerp(255, 180, blend);
      let g = lerp(140, 140, blend);
      let b = lerp(120, 255, blend);
      let alpha = map(d1 + d2, 0, 800, 25, 2);

      fill(r, g, b, alpha);
      noStroke();
      let size = random(1, 4);
      ellipse(x, y, size, size);
    }
  }
  pop();
}

function drawFlowingLines() {
  push();
  // 从左向右流动的曲线
  for (let i = 0; i < 40; i++) {
    let startY = 700 + i * 15;
    let hue = map(i, 0, 40, 0, 360);

    noFill();

    for (let pass = 0; pass < 3; pass++) {
      strokeWeight(pass === 1 ? 1.5 : 0.8);

      if (pass === 1) {
        stroke(255, 150, 150, 120);
      } else {
        stroke(200, 180, 220, 60);
      }

      beginShape();
      for (let x = 400; x <= 1200; x += 5) {
        let noiseVal = noise(x * 0.003, startY * 0.003, i * 0.1);
        let y = startY + sin((x - 400) * 0.01 + i * 0.3) * 80 * noiseVal;

        let d1 = dist(x, y, 500, 1000);
        let d2 = dist(x, y, 1100, 1000);

        if (d1 < 350 || d2 < 350 || (x > 700 && x < 900)) {
          curveVertex(x, y);
        }
      }
      endShape();
    }
  }
  pop();
}

function drawBreathParticles() {
  push();
  // 周围飘散的温柔粒子
  for (let i = 0; i < 150; i++) {
    let angle = random(TWO_PI);
    let distance = random(450, 700);
    let centerX = 800;
    let centerY = 1000;

    let x = centerX + cos(angle) * distance;
    let y = centerY + sin(angle) * distance;

    let n = noise(x * 0.01, y * 0.01);
    let size = random(2, 8) * n;

    if (angle < PI) {
      fill(255, 160, 140, 80);
    } else {
      fill(170, 150, 255, 80);
    }

    noStroke();
    ellipse(x, y, size, size);

    // 小光晕
    fill(255, 255, 255, 30);
    ellipse(x, y, size * 1.5, size * 1.5);
  }

  // 添加细微的能量波纹
  noFill();
  for (let i = 0; i < 8; i++) {
    let radius = 400 + i * 60;
    stroke(255, 200, 200, 15 - i);
    strokeWeight(1);

    beginShape();
    for (let angle = 0; angle < TWO_PI; angle += 0.1) {
      let r = radius + sin(angle * 4 + i) * 20;
      let x = 800 + cos(angle) * r;
      let y = 1000 + sin(angle) * r;
      vertex(x, y);
    }
    endShape(CLOSE);
  }

  pop();
