  // 绘制多层光晕
  for (let layer = 0; layer < 150; layer++) {
    let alpha = map(layer, 0, 150, 35, 0);
    let size = map(layer, 0, 150, 50, 1200);

    // 左侧光源 - 偏暖橙色
    for (let i = 0; i < 8; i++) {
      let r = 255 - layer * 0.3;
      let g = 180 - layer * 0.8;
      let b = 60 - layer * 0.5;
      let offsetX = random(-5, 5);
      let offsetY = random(-5, 5);

      fill(r, g, b, alpha * 0.6);
      noStroke();
      ellipse(x1 + offsetX, y1 + offsetY, size, size);
    }

    // 右侧光源 - 偏粉红色
    for (let i = 0; i < 8; i++) {
      let r = 255 - layer * 0.2;
      let g = 100 - layer * 0.9;
      let b = 150 - layer * 0.4;
      let offsetX = random(-5, 5);
      let offsetY = random(-5, 5);

      fill(r, g, b, alpha * 0.6);
      noStroke();
      ellipse(x2 + offsetX, y2 + offsetY, size, size);
    }
  }

  // 绘制交融区域的粒子
  for (let i = 0; i < 3000; i++) {
    let angle = random(TWO_PI);
    let radius = randomGaussian(0, 180);
    let midX = (x1 + x2) / 2;
    let midY = (y1 + y2) / 2;

    let px = midX + cos(angle) * radius;
    let py = midY + sin(angle) * radius;

    let d1 = dist(px, py, x1, y1);
    let d2 = dist(px, py, x2, y2);

    // 根据到两个中心的距离混合颜色
    let mixFactor = d1 / (d1 + d2);
    let r = lerp(255, 255, mixFactor);
    let g = lerp(160, 120, mixFactor);
    let b = lerp(80, 180, mixFactor);

    let brightness = 1 / (1 + abs(radius) / 100);
    let particleAlpha = brightness * random(100, 200);

    fill(r, g, b, particleAlpha);
    noStroke();
    let particleSize = random(2, 12) * brightness;
    ellipse(px, py, particleSize, particleSize);
  }

  // 添加流动的能量线
  for (let i = 0; i < 100; i++) {
    let t = i / 100;
    let curveOffset = sin(t * PI) * 150;

    for (let j = 0; j < 50; j++) {
      let x = lerp(x1, x2, t);
      let y = lerp(y1, y2, t) + curveOffset * noise(i * 0.1, j * 0.1);

      let r = lerp(255, 255, t);
      let g = lerp(180, 100, t);
      let b = lerp(60, 150, t);
      let alpha = sin(t * PI) * 40;

      fill(r, g, b, alpha);
      noStroke();
      ellipse(x + randomGaussian(0, 15), y + randomGaussian(0, 15), 
              random(3, 10), random(3, 10));
    }
  }

  // 核心最亮部分
  drawingContext.shadowBlur = 100;
  drawingContext.shadowColor = 'rgba(255, 220, 150, 0.9)';

  fill(255, 240, 200, 200);
  noStroke();
  ellipse(x1, y1, 120, 120);

  fill(255, 200, 220, 200);
  ellipse(x2, y2, 120, 120);

  drawingContext.shadowBlur = 150;
  fill(255, 255, 240, 220);
  ellipse((x1 + x2) / 2, (y1 + y2) / 2, 180, 180);

  drawingContext.shadowBlur = 0;
}

