  let center1X = width * 0.35;
  let center1Y = height * 0.5;
  let center2X = width * 0.65;
  let center2Y = height * 0.5;

  // 交融中心
  let mergeX = width * 0.5;
  let mergeY = height * 0.5;

  // 绘制背景粒子氛围
  for (let i = 0; i < 3000; i++) {
    let x = random(width);
    let y = random(height);
    let dist1 = dist(x, y, center1X, center1Y);
    let dist2 = dist(x, y, center2X, center2Y);
    let distMerge = dist(x, y, mergeX, mergeY);

    let minDist = min(dist1, dist2, distMerge);
    let alpha = map(minDist, 0, 800, 30, 0);

    if (alpha > 0) {
      let size = random(1, 3);
      noStroke();
      fill(255, 255, 255, alpha * random(0.3, 1));
      circle(x, y, size);
    }
  }

  // 绘制左侧形体（蓝紫色）
  for (let r = 450; r > 0; r -= 2) {
    let alpha = map(r, 0, 450, 180, 0);
    let hueShift = map(r, 450, 0, 0, 30);

    noStroke();
    fill(150 + hueShift, 100 + hueShift, 255, alpha * 0.3);

    push();
    translate(center1X, center1Y);
    beginShape();
    for (let angle = 0; angle < TWO_PI; angle += 0.1) {
      let xoff = cos(angle) * 0.5;
      let yoff = sin(angle) * 0.5;
      let n = noise(xoff + 100, yoff + 100, r * 0.01) * 0.3 + 0.85;
      let radius = r * n;
      let x = cos(angle) * radius;
      let y = sin(angle) * radius;
      vertex(x, y);
    }
    endShape(CLOSE);
    pop();
  }

  // 绘制右侧形体（粉橙色）
  for (let r = 450; r > 0; r -= 2) {
    let alpha = map(r, 0, 450, 180, 0);
    let hueShift = map(r, 450, 0, 0, 30);

    noStroke();
    fill(255, 120 + hueShift, 150 + hueShift, alpha * 0.3);

    push();
    translate(center2X, center2Y);
    beginShape();
    for (let angle = 0; angle < TWO_PI; angle += 0.1) {
      let xoff = cos(angle) * 0.5;
      let yoff = sin(angle) * 0.5;
      let n = noise(xoff + 200, yoff + 200, r * 0.01) * 0.3 + 0.85;
      let radius = r * n;
      let x = cos(angle) * radius;
      let y = sin(angle) * radius;
      vertex(x, y);
    }
    endShape(CLOSE);
    pop();
  }

  // 绘制交融区域（温暖的金黄色光芒）
  for (let r = 500; r > 0; r -= 2) {
    let alpha = map(r, 0, 500, 200, 0);
    let brightness = map(r, 500, 0, 150, 255);

    noStroke();
    fill(255, brightness, 100 + brightness * 0.3, alpha * 0.4);

    push();
    translate(mergeX, mergeY);
    beginShape();
    for (let angle = 0; angle < TWO_PI; angle += 0.1) {
      let xoff = cos(angle) * 0.5;
      let yoff = sin(angle) * 0.5;
      let n = noise(xoff + 300, yoff + 300, r * 0.008) * 0.4 + 0.8;
      let radius = r * n;
      let x = cos(angle) * radius;
      let y = sin(angle) * radius;
      vertex(x, y);
    }
    endShape(CLOSE);
    pop();
  }

  // 从交融处散发的能量粒子
  for (let i = 0; i < 800; i++) {
    let angle = random(TWO_PI);
    let distance = randomGaussian(400, 200);
    if (distance < 0) distance = random(100);

    let x = mergeX + cos(angle) * distance;
    let y = mergeY + sin(angle) * distance;

    let size = random(2, 8);
    let distFromCenter = dist(x, y, mergeX, mergeY);
    let alpha = map(distFromCenter, 0, 800, 150, 0);

    if (alpha > 0) {
      noStroke();

      // 混合色彩
      let colorChoice = random(1);
      if (colorChoice < 0.4) {
        fill(255, 220, 150, alpha * random(0.5, 1));
      } else if (colorChoice < 0.7) {
        fill(255, 180, 200, alpha * random(0.5, 1));
      } else {
        fill(200, 150, 255, alpha * random(0.5, 1));
      }

      circle(x, y, size);
    }
  }

  // 添加连接线条，表现流动与联结
  for (let i = 0; i < 150; i++) {
    let angle = random(TWO_PI);
    let startDist = random(100, 300);
    let endDist = random(300, 600);

    let x1 = mergeX + cos(angle) * startDist;
    let y1 = mergeY + sin(angle) * startDist;
    let x2 = mergeX + cos(angle + random(-0.3, 0.3)) * endDist;
    let y2 = mergeY + sin(angle + random(-0.3, 0.3)) * endDist;

    stroke(255, 230, 180, random(10, 40));
    strokeWeight(random(0.5, 2));
    line(x1, y1, x2, y2);
  }

  // 中心最亮的光点
  for (let r = 60; r > 0; r -= 3) {
    let alpha = map(r, 0, 60, 255, 0);
    noStroke();
    fill(255, 255, 240, alpha);
    circle(mergeX, mergeY, r);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();

  background(252, 250, 245);

  // 两个源点
  let source1 = { x: 400, y: 1000, color: [220, 60, 100] };
  let source2 = { x: 1200, y: 1000, color: [60, 120, 200] };

  // 绘制流动的粒子系统
  for (let i = 0; i < 15000; i++) {
    let angle = random(TWO_PI);
    let distance = randomGaussian(0, 350);

    // 随机选择从哪个源点出发
    let source = random() < 0.5 ? source1 : source2;
    let otherSource = source === source1 ? source2 : source1;

    let x = source.x + cos(angle) * distance;
    let y = source.y + sin(angle) * distance;

    // 计算到另一个源点的影响
    let distToOther = dist(x, y, otherSource.x, otherSource.y);
    let influence = map(distToOther, 0, 800, 1, 0, true);

    // 颜色混合
    let r = lerp(source.color[0], otherSource.color[0], influence);
    let g = lerp(source.color[1], otherSource.color[1], influence);
    let b = lerp(source.color[2], otherSource.color[2], influence);

    // 使用噪声添加有机流动感
    let noiseVal = noise(x * 0.003, y * 0.003);
    x += (noiseVal - 0.5) * 100;
    y += (noiseVal - 0.5) * 100;

    // 透明度随距离变化
    let distFromSource = dist(x, y, source.x, source.y);
    let alpha = map(distFromSource, 0, 400, 25, 2, true);

    // 在交融区域增加亮度和饱和度
    if (influence > 0.3 && influence < 0.7) {
      alpha *= 1.5;
      r = lerp(r, 255, 0.2);
      g = lerp(g, 255, 0.1);
      b = lerp(b, 255, 0.1);
    }

    noStroke();
    fill(r, g, b, alpha);

    let size = random(1, 8) * (1 + influence);
    ellipse(x, y, size, size);
  }

  // 添加流动的线条
  for (let i = 0; i < 80; i++) {
    let startSide = random() < 0.5 ? source1 : source2;
    let endSide = startSide === source1 ? source2 : source1;

    let sx = startSide.x + randomGaussian(0, 200);
    let sy = startSide.y + randomGaussian(0, 200);
    let ex = endSide.x + randomGaussian(0, 200);
    let ey = endSide.y + randomGaussian(0, 200);

    strokeWeight(random(0.5, 2));
    noFill();

    for (let t = 0; t <= 1; t += 0.01) {
      let x = lerp(sx, ex, t);
      let y = lerp(sy, ey, t);

      let nr = lerp(startSide.color[0], endSide.color[0], t);
      let ng = lerp(startSide.color[1], endSide.color[1], t);
      let nb = lerp(startSide.color[2], endSide.color[2], t);

      stroke(nr, ng, nb, 15);

      let nx = x + noise(x * 0.01, y * 0.01, i) * 50;
      let ny = y + noise(x * 0.01, y * 0.01, i + 100) * 50;

      if (t > 0) {
        point(nx, ny);
      }
    }
  }

  // 添加中心的光晕
  let centerX = (source1.x + source2.x) / 2;
  let centerY = (source1.y + source2.y) / 2;

  for (let i = 0; i < 100; i++) {
    let radius = i * 3;
    let alpha = map(i, 0, 100, 8, 0);
    noFill();
    stroke(255, 220, 240, alpha);
    strokeWeight(2);
    ellipse(centerX, centerY, radius, radius);
  }
}

