function drawBackgroundNoise() {
  let noiseScale = 0.005;
  for (let i = 0; i < 80000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * noiseScale, y * noiseScale);
    let hue = 230 + n * 40;
    let sat = 40 + n * 30;
    let brt = 5 + n * 15;
    let alpha = n * 20;
    fill(hue, sat, brt, alpha);
    noStroke();
    circle(x, y, random(1, 4));
  }
}

function drawVessel() {
  const centerX = width / 2;
  const vesselBottom = height - 200;
  const vesselHeight = 1000;
  const maxRadius = 350;
  const numParticles = 250000;

  for (let i = 0; i < numParticles; i++) {
    let y = vesselBottom - random() * random() * vesselHeight;

    // Create the curved shape of the vessel
    let yNorm = (vesselBottom - y) / vesselHeight; // 0 at bottom, 1 at top
    let radiusFactor = (sin(yNorm * PI * 1.8 - PI / 2.5) + 1) / 2;
    radiusFactor = pow(radiusFactor, 1.2);
    let currentRadius = maxRadius * radiusFactor;

    let r = randomGaussian(0, currentRadius * 0.4);
    let angle = random(TWO_PI);
    let x = centerX + r * cos(angle);

    // Make the vessel fade and fracture towards the top
    let breakChance = pow(yNorm, 2.5);
    if (random() > breakChance) {
      let n = noise(x * 0.01, y * 0.01);
      let hue = 30 + n * 20;
      let sat = 10 + (1 - yNorm) * 40 + n * 10;
      let brt = 40 + n * 30;
      let alpha = (1 - yNorm) * 50 + n * 20;

      fill(hue, sat, brt, alpha);
      noStroke();
      circle(x + random(-2, 2), y + random(-2, 2), random(1, 4));
    }
  }
}

function drawEssence() {
  const startY = height - 1000;
  const startXCenter = width / 2;
  const startRadius = 250;
  const numStreams = 1200;

  for (let i = 0; i < numStreams; i++) {
    let x = startXCenter + randomGaussian(0, startRadius);
    let y = startY + randomGaussian(0, 50);

    const streamLength = 200 + random(1200);
    const curliness = random(0.001, 0.004);
    const speed = random(1, 3);
    const startAngle = noise(i * 0.1) * TWO_PI;

    for (let j = 0; j < streamLength; j++) {
      let progress = j / streamLength; // 0 to 1
      let angle = noise(x * curliness, y * curliness, i * 0.05) * 4 - 2;

      x += cos(angle + startAngle) * speed;
      y -= speed;

      if (y < 0) break;

      let n = noise(x * 0.05, y * 0.05);

      let hue = 45 + n * 15;
      let sat = 60 - progress * 50;
      let brt = 100;
      let alpha = (1 - progress) * (1 - progress) * 60;
      let size = (1 - progress) * 4 + 1;

      fill(hue, sat, brt, alpha);
      noStroke();
      circle(x, y, size);
    }
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  noStroke();

  // Define colors
  const bgColor1 = color(4, 8, 20);
  const bgColor2 = color(28, 24, 58);
  const particleColor1 = color(240, 228, 160); // Pale gold
  const particleColor2 = color(160, 192, 240); // Ethereal blue

  // --- Draw the textured background ---
  // Create a dark, noisy, cosmic void
  for (let i = 0; i < 50000; i++) {
    let x = random(width);
    let y = random(height);
    let noiseVal = noise(x * 0.001, y * 0.001);
    let c = lerpColor(bgColor1, bgColor2, noiseVal);
    let size = random(100, 400);
    let alpha = map(noiseVal, 0, 1, 5, 20);
    fill(red(c), green(c), blue(c), alpha);
    ellipse(x, y, size, size);
  }

  // --- Draw the dissolving form ---
  // A dense cloud of particles that forms a figure-like shape at the bottom
  // and dissipates as it rises.
  const numParticles = 300000;
  for (let i = 0; i < numParticles; i++) {
    // Y position is biased towards the bottom for the main form
    let y = height - pow(random(), 1.5) * height;

    // The horizontal spread (standard deviation) increases as particles rise
    let spread = map(y, height, 0, 50, 400);

    // The center of the form has a slight organic sway
    let centerX = width / 2 + (noise(y * 0.005) - 0.5) * 200;
    let x = randomGaussian(centerX, spread);

    // --- Determine particle properties based on Y position ---

    // Size decreases as particles rise
    let size = map(y, height, 0, 15, 1) * random(0.5, 1.5);
    size = max(1, size); // ensure minimum size

    // Opacity is higher at the bottom and fades out at the top
    let alpha = map(y, height, 0, 200, 5) * random(0.7, 1);

    // Color transitions from gold/warm at the base to blue/cool as it dissipates
    let colorAmount = map(y, height, height * 0.5, 0, 1, true);
    let particleColor = lerpColor(particleColor1, particleColor2, colorAmount);
    // Add some random color variation
    if (random() < 0.1) {
      particleColor = lerpColor(particleColor, color(255), 0.2);
    }

    fill(red(particleColor), green(particleColor), blue(particleColor), alpha);
    ellipse(x, y, size, size);
  }
}

