function draw() {
  // Draw the cool, cosmic background texture
  let bgNoiseScale = 0.002;
  for (let i = 0; i < 80000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * bgNoiseScale, y * bgNoiseScale);
    let hue = map(n, 0.2, 0.8, 220, 260); // Blues and purples
    let sat = map(y, 0, height, 50, 80);
    let brt = map(n, 0, 1, 5, 20);
    let alpha = random(10, 40);
    noStroke();
    fill(hue, sat, brt, alpha);
    circle(x, y, random(50, 150));
  }

  // Draw the dissolving form
  let numParticles = 400000;
  let centerX = width / 2;
  let figureWidth = width * 0.2;
  let flowNoiseScale = 0.005;

  for (let i = 0; i < numParticles; i++) {
    let y = random(height * 0.2, height);
    let x_prob = (y / height) * 0.8 + 0.2; // Figure is more defined at the bottom
    let x = centerX + (randomGaussian() * figureWidth * x_prob);

    // Calculate upward and outward flow based on noise
    let angle = noise(x * flowNoiseScale, y * flowNoiseScale) * TWO_PI * 4;
    let flowStrength = map(y, 0, height, height * 0.8, 0); // Stronger flow at the top
    let v = p5.Vector.fromAngle(angle);
    v.setMag(pow(noise(x * 0.002, y * 0.002), 3) * flowStrength);

    // Make the primary flow direction upward
    v.y = -abs(v.y);

    let finalX = x + v.x;
    let finalY = y + v.y;

    // Determine color based on original position and amount of dispersal
    let y_norm = map(y, height, height * 0.2, 0, 1);
    let startHue = lerp(10, 50, y_norm); // Reds to oranges
    let endHue = lerp(240, 300, y_norm); // Blues to magentas

    let dispersal = min(1, v.mag() / (height * 0.3));
    let finalHue = lerp(startHue, endHue, dispersal);
    let finalSat = lerp(90, 60, dispersal);
    let finalBrt = lerp(100, 15, dispersal * 1.2);
    let finalAlpha = lerp(15, 0, dispersal);

    noStroke();
    fill(finalHue, finalSat, finalBrt, finalAlpha);

    // Draw particle
    let particleSize = lerp(1, 6, 1 - y_norm) + random(1, 3);
    if (dispersal > 0.1) {
       particleSize *= (1-dispersal) * 2;
    }
    circle(finalX, finalY, particleSize);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();

  background(0);

  // Draw the cosmic, textured background
  loadPixels();
  let noiseScale = 0.003;
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let n = noise(x * noiseScale, y * noiseScale);
      let hue = map(n, 0, 1, 220, 280); // Blues to purples
      let saturation = 60 + noise(x * 0.01, y * 0.01) * 20;
      let brightness = map(n, 0, 1, 5, 20); // Dark
      let c = color(hue, saturation, brightness);
      set(x, y, c);
    }
  }
  updatePixels();

  noStroke();

  // Draw the dissolving figure as a cloud of particles
  let numParticles = 200000;
  for (let i = 0; i < numParticles; i++) {

    // Define the core vertical area of the figure
    let y = random(height * 0.35, height * 0.95);

    // Create a basic humanoid shape using a sine curve for width
    // Thicker around the torso/shoulders, thinner at base and head
    let normalizedY = map(y, height * 0.35, height * 0.95, 0, 1);
    let coreWidth = pow(sin(normalizedY * PI), 0.7) * 250;
    let x = width / 2 + random(-coreWidth, coreWidth);

    // Calculate displacement: particles disperse more as they go up
    let upwardBias = map(y, 0, height, 1, 0);
    let displacementStrength = pow(upwardBias, 2.5) * width * 0.8;

    // Apply Perlin noise for organic, swirling displacement
    let noiseX = (noise(x * 0.005, y * 0.005, 10) - 0.5) * displacementStrength;
    let noiseY = (noise(x * 0.005, y * 0.005, 20) - 0.6) * displacementStrength * 2; // Stronger upward pull

    let finalX = x + noiseX;
    let finalY = y + noiseY;

    // Determine color of the particle
    let hue = 35 + random(-10, 10); // Warm golds and oranges
    let saturation = 70 + random(-20, 20);
    let brightness = 90 + random(-10, 10);

    // Determine opacity: more transparent further from the core and higher up
    let distFromCenter = abs(finalX - width / 2);
    let alpha = map(distFromCenter, 0, width / 2, 60, 0, true);
    alpha *= map(finalY, 0, height, 0.1, 1, true); // Fade at the top
    alpha = pow(alpha/100, 1.5) * 100; // Curve the falloff

    // Determine size: smaller particles for a finer dust-like feel
    let particleSize = random(1, 4) * (alpha / 50);

    fill(hue, saturation, brightness, alpha);
    ellipse(finalX, finalY, particleSize, particleSize);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // Base background color
  background(10, 15, 25);

  // --- 1. Cosmic Dust Background ---
  // Creates a deep, textured background with subtle color variations.
  for (let i = 0; i < 80000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.001, y * 0.001);
    let size = random(5, 20);
    let alpha = map(n, 0, 1, 5, 20);

    let r = map(n, 0, 1, 10, 30);
    let g = map(n, 0, 1, 15, 40);
    let b = map(n, 0, 1, 25, 60);

    noStroke();
    fill(r, g, b, alpha);
    ellipse(x, y, size, size);
  }

  // --- 2. The Central Form (The "Vessel") ---
  // This is the core element, representing a life. It's more cohesive at the top
  // and starts to fray and dissolve towards the bottom.
  let centerX = width / 2;
  for (let y = 0; y < height; y += 2) {
    // The form's width and density decrease as it goes down the canvas.
    let cohesion = map(y, 0, height, 1, 0.1, true); 
    let horizontalSpread = map(y, 0, height, 20, 400);

    let particleCount = 20 * cohesion;

    for (let i = 0; i < particleCount; i++) {
      let xOffset = randomGaussian(0, horizontalSpread * 0.5);
      let x = centerX + xOffset;

      // Particles become dimmer and cooler towards the bottom.
      let warmness = map(y, 0, height, 1, 0, true);
      let r = lerpColor(color(50, 60, 80), color(255, 240, 200), warmness).levels[0];
      let g = lerpColor(color(50, 60, 80), color(255, 240, 200), warmness).levels[1];
      let b = lerpColor(color(50, 60, 80), color(200, 220, 255), warmness).levels[2];

      let size = random(2, 6) * cohesion;
      let alpha = random(50, 150) * cohesion;

      noStroke();
      fill(r, g, b, alpha);
      ellipse(x, y, size, size);
    }
  }

  // --- 3. The Unraveling Particles ---
  // These are the streams of particles flowing away from the central form,
  // showing the process of dissolution.
  let numStreams = 800;
  for (let i = 0; i < numStreams; i++) {
    // Particles originate from the lower 2/3 of the form.
    let startY = random(height * 0.3, height);
    let startX = centerX + randomGaussian(0, map(startY, 0, height, 20, 300));

    let streamLength = random(20, 200);
    let angle = random(PI * 0.25, PI * 0.75) + (random() > 0.5 ? PI/2 : -PI/2);
    let curl = random(-0.02, 0.02);

    let currentX = startX;
    let currentY = startY;

    // Determine the color based on the starting height.
    let warmness = map(startY, 0, height, 1, 0, true);
    let startR = lerpColor(color(50, 60, 80), color(255, 220, 180), warmness).levels[0];
    let startG = lerpColor(color(50, 60, 80), color(255, 220, 180), warmness).levels[1];
    let startB = lerpColor(color(50, 60, 80), color(180, 200, 240), warmness).levels[2];

    for (let j = 0; j < streamLength; j++) {
      let progress = j / streamLength;

      currentX += cos(angle) * 2;
      currentY += sin(angle) * 2;
      angle += curl + noise(currentX * 0.01, currentY * 0.01) * 0.1 - 0.05;

      let size = map(progress, 0, 1, random(1, 4), 0.5);
      let alpha = map(progress, 0, 1, random(40, 120), 0);

      // Particles fade into the background color.
      let r = lerp(startR, 15, progress);
      let g = lerp(startG, 20, progress);
      let b = lerp(startB, 35, progress);

      noStroke();
      fill(r, g, b, alpha);
      ellipse(currentX, currentY, size, size);
    }
  }

  // --- 4. Final Grain/Atmosphere ---
  // Adds a subtle grain over the entire image to unify the composition.
  for (let i = 0; i < 40000; i++) {
    let x = random(width);
    let y = random(height);
    let col = random() > 0.5 ? color(200, 220, 255, 15) : color(50, 60, 100, 10);
    noStroke();
    fill(col);
    rect(x, y, 1, 1);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();

  // Draw the vast, textured background
  background(240, 50, 10);
  for (let i = 0; i < 80000; i++) {
    let x = random(width);
    let y = random(height);
    let c = color(random(230, 250), random(30, 60), 5, random(5, 15));
    noStroke();
    fill(c);
    circle(x, y, random(1, 3));
  }

  // Draw the central "tapestry" of life unraveling
  let numStrands = 4000;
  for (let i = 0; i < numStrands; i++) {
    let x_base = width / 2 + random(-10, 10);
    let noise_x_offset = random(1000);
    let noise_y_offset = random(1000);
    let thick = random(0.5, 2.5);

    beginShape();
    noFill();
    for (let y = 0; y < height; y += 5) {
      let progress = y / height;

      // Unraveling effect: spread increases as we go down
      let spread = pow(progress, 2.5) * (width * 0.6);

      // Calculate position with noise
      let x_noise = (noise(noise_x_offset + progress * 2, noise_y_offset) - 0.5) * spread;
      let x = x_base + x_noise;

      // Color fades from vibrant to muted
      let h = lerp(45, 240, pow(progress, 2)); // Hue shifts from gold to deep blue
      let s = lerp(90, 30, progress); // Saturation decreases
      let b = lerp(100, 15, progress); // Brightness decreases
      let a = lerp(50, 2, progress) * (1 - pow(progress, 4)); // Alpha fades out, especially at the end

      strokeWeight(thick * (1 - progress * 0.8));
      stroke(h, s, b, a);
      vertex(x, y);
    }
    endShape();
  }

  // Add "dust" from the dissolved threads
  for (let i = 0; i < 50000; i++) {
    let y = random(height * 0.4, height);
    let progress = y / height;

    let x = random(width);
    let a = random(1, 20) * pow(progress, 3);
    let sz = random(1, 3);

    let h = lerp(45, 240, pow(progress, 2));
    let s = lerp(50, 20, progress);
    let b = lerp(40, 10, progress);

    fill(h, s, b, a);
    noStroke();
    circle(x, y, sz);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();

  // --- Background: A deep, textured void ---
  // We draw a "background" of very dark, subtly shifting noise to represent
  // the vast, indifferent universe to which everything returns.
  loadPixels();
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let noiseVal = noise(x * 0.005, y * 0.005);
      let hue = map(noiseVal, 0, 1, 220, 280); // Deep blues to purples
      let brightness = map(noiseVal, 0, 1, 1, 8);
      let sat = map(noiseVal, 0, 1, 10, 30);
      set(x, y, color(hue, sat, brightness));
    }
  }
  updatePixels();

  // --- The Core & Dissolution: A particle system ---
  // This represents the "life" or "structure" that is unraveling.
  // It's not a solid object, but a dense collection of points that
  // are being scattered by a gentle, cosmic "wind" (driven by noise).
  const numParticles = 80000;
  const coreX = width / 2;
  const coreY = height * 0.4;
  const coreSpread = width * 0.15;

  for (let i = 0; i < numParticles; i++) {
    // Generate particles clustered in a central, ovoid shape.
    let x = coreX + randomGaussian() * coreSpread;
    let y = coreY + randomGaussian() * (coreSpread * 1.2);

    // Calculate a "flow" based on Perlin noise. This creates a gentle,
    // coherent drift rather than pure random scattering.
    let noiseAngle = noise(x * 0.0008, y * 0.0008) * TWO_PI * 3;
    let distFromCore = dist(x, y, coreX, coreY);
    let flowStrength = map(distFromCore, 0, width / 2, 0, width * 1.2);

    // Apply the flow, with a slight downward pull to give a sense of settling.
    let finalX = x + cos(noiseAngle) * flowStrength;
    let finalY = y + sin(noiseAngle) * flowStrength + pow(flowStrength, 1.1) * 0.2;

    // Determine particle appearance based on its journey.
    // Particles farther from the core are dimmer and more faded.
    let finalDist = dist(finalX, finalY, coreX, coreY);
    let maxDist = width * 1.1;

    // Alpha (transparency) decreases with distance.
    let alpha = map(finalDist, 0, maxDist, 90, 0, true);
    // Brightness also decreases.
    let brightness = map(finalDist, 0, maxDist * 0.7, 100, 10, true);
    // Size gets smaller.
    let particleSize = map(finalDist, 0, maxDist, 2.5, 0.5, true);
    // Hue shifts slightly for a pearlescent effect.
    let hue = map(noise(x * 0.01, y * 0.01), 0, 1, 180, 260); // Cool, ethereal tones
    let saturation = map(finalDist, 0, maxDist, 40, 10, true);

    // Draw the particle.
    strokeWeight(particleSize);
    stroke(hue, saturation, brightness, alpha);
    point(finalX, finalY);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  let bgColor = color(5, 3, 15);
  background(bgColor);

  // Add subtle texture to the void
  for (let i = 0; i < 50000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.005, y * 0.005);
    let c = color(10, 8, 25, n * 15);
    noStroke();
    fill(c);
    circle(x, y, random(1, 4));
  }

  // Define color palettes for "life"
  const lifeColors = [
    color(110, 120, 40, 150), // Olive green
    color(160, 140, 70, 150), // Ochre
    color(50, 60, 20, 150),   // Dark forest green
    color(90, 80, 60, 150)    // Muted brown
  ];
  const highlightColors = [
    color(180, 50, 60, 180),  // Deep red
    color(60, 120, 130, 180) // Teal
  ];

  // Draw the "unraveling" strands of life
  for (let i = 0; i < 80000; i++) {
    let x = random(width);
    let y = height + random(20);

    // Choose a base color for this strand
    let baseColor = random(lifeColors);
    if (random() < 0.01) {
      baseColor = random(highlightColors);
    }

    let strandLength = random(50, 300);
    for (let j = 0; j < strandLength; j++) {
      // Determine fade factor based on vertical position
      // Fading begins around 80% down and is complete by 30% down
      let fadeThresholdStart = height * 0.8;
      let fadeThresholdEnd = height * 0.3;
      let fade = map(y, fadeThresholdStart, fadeThresholdEnd, 1.0, 0.0, true);

      // Strand has a chance to terminate based on its fade
      if (random() > fade * fade) {
        // Draw one last "ember" spark
        if (fade > 0.05 && fade < 0.3 && random() < 0.1) {
          fill(255, 220, 180, 150);
          noStroke();
          circle(x, y, random(1, 3));
        }
        break;
      }

      // Calculate color by interpolating between life color and void color
      let currentColor = lerpColor(bgColor, baseColor, fade);

      let sw = map(fade, 1, 0, 1.5, 0.5);
      strokeWeight(sw);
      stroke(currentColor);

      // Update position with Perlin noise for organic movement
      let angle = noise(x * 0.003, y * 0.003) * 4;
      let prevX = x;
      let prevY = y;
      x += cos(angle) * 2;
      y -= 1;

      line(x, y, prevX, prevY);

      if (y < 0) break;
    }
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();

  // Part 1: The deep, textured background representing the cosmic void
  background(0);
  drawingContext.filter = 'blur(2px)'; // Soften the background noise
  for (let i = 0; i < 200000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.001, y * 0.001);
    let hue = map(n, 0, 1, 220, 280);
    let bright = map(n, 0, 1, 0, 8);
    let alpha = map(dist(x, y, width / 2, height / 2), 0, width, 5, 2);
    stroke(hue, 80, bright, alpha);
    point(x, y);
  }
  drawingContext.filter = 'none';

  // Part 2: The central, complex form of "life" that is unraveling
  let centerX = width / 2;
  let centerY = height * 0.45;

  for (let i = 0; i < 400; i++) {
    let a = random(TWO_PI);
    let r = pow(random(), 3) * 400;
    let x = centerX + cos(a) * r;
    let y = centerY + sin(a) * r;

    let len = random(200, 800);
    for (let j = 0; j < len; j++) {
      let angle = noise(x * 0.005, y * 0.005, i * 0.01) * 4;
      let d = dist(x, y, centerX, centerY);

      let maxDist = 500;
      if (d < maxDist) {
        let strokeW = map(d, 0, maxDist, 3, 0.5);
        let hue = map(d, 0, maxDist, 40, 60);
        let sat = map(d, 0, maxDist, 10, 50);
        let bright = map(d, 0, maxDist, 100, 70);
        let alpha = map(d, 0, maxDist, 90, 10);

        stroke(hue, sat, bright, alpha);
        strokeWeight(strokeW);
        point(x, y);
      }

      x += cos(angle);
      y += sin(angle);
    }
  }

  // Part 3: The "dust" or "ash" - particles returning to the void
  let dustParticles = 30000;
  for (let i = 0; i < dustParticles; i++) {
    let startAngle = random(TWO_PI);
    let startRadius = pow(random(), 2) * 350;

    let x = centerX + cos(startAngle) * startRadius;
    let y = centerY + sin(startAngle) * startRadius + random(-50, 50);

    let life = random(50, 600);
    let xDrift = random(-0.2, 0.2);

    let startColor = color(50, 40, 100, 80);
    let endColor = color(240, 50, 5, 0);

    for (let j = 0; j < life; j++) {
      let progress = j / life;

      let currentSize = map(progress, 0, 1, 2, 0.1);
      let ySpeed = map(progress, 0, 1, 0.1, 2);

      let c = lerpColor(startColor, endColor, progress);

      noStroke();
      fill(c);
      circle(x, y, currentSize);

      y += ySpeed;
      x += xDrift + (noise(y * 0.01, i) - 0.5) * 0.5;

      if(y > height) break;
    }
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  colorMode(HSB, 360, 100, 100, 100);
  noStroke();
  background(240, 50, 5); // Deep, dark, slightly blue-purple background

  // Draw a textured, deep-space background
  // This adds depth and a sense of a vast, particle-filled void.
  for (let i = 0; i < 100000; i++) {
    let x = random(width);
    let y = random(height);
    let dia = random(1, 4);
    // Dark blues and purples for a cosmic dust feel
    fill(random(230, 260), random(30, 60), random(5, 15), random(1, 10));
    ellipse(x, y, dia, dia);
  }

  // Draw the central form - the "self" that is dissolving
  let numParticles = 400000;

  for (let i = 0; i < numParticles; i++) {
    // The y-position progresses through the canvas
    let y = map(i, 0, numParticles, -height * 0.1, height * 1.1);

    // Use Perlin noise to create an organic, wavering central spine
    let noiseFactor = map(y, 0, height, 0, 5);
    let centerX = width / 2 + map(noise(y * 0.001, 10), 0, 1, -150, 150);

    // Spread particles horizontally away from the spine
    let spread = pow(random(), 2.5) * (width / 2.5);
    let x = centerX + random(-spread, spread);

    // The distance from the central spine is key to the effect
    let distanceFromCenter = abs(x - centerX);

    // Fade out particles near the top and bottom of the canvas
    let verticalFade = 1;
    if (y < height * 0.1) {
      verticalFade = map(y, 0, height * 0.1, 0, 1);
    } else if (y > height * 0.9) {
      verticalFade = map(y, height * 0.9, height, 1, 0);
    }

    // --- Particle Appearance based on distance from the spine ---

    // SIZE: Particles are smaller the further they are
    let particleSize = map(distanceFromCenter, 0, width / 3, 6, 0.5, true);

    // ALPHA: Particles are more transparent the further they are
    let alpha = map(distanceFromCenter, 0, width / 2, 80, 0, true);
    alpha *= verticalFade; // Apply the top/bottom fade

    // COLOR: The core is warm (pale yellow/white), fading to cold (blue/purple)
    // The hue shifts from a warm yellow (60) to a cool blue (240).
    let hue = map(distanceFromCenter, 0, width / 3, 60, 240, true);
    // Saturation decreases towards the center, making the core almost white.
    let saturation = map(distanceFromCenter, 0, width / 3, 15, 60, true);
    // Brightness is higher at the core.
    let brightness = map(distanceFromCenter, 0, width / 3, 100, 20, true);

    fill(hue, saturation, brightness, alpha);
    ellipse(x, y, particleSize, particleSize);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  colorMode(HSB, 360, 100, 100, 1);
  noLoop();
}

function draw() {
  background(0);

  // 1. Ciel cosmique texturé
  for (let i = 0; i < 80000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.001, y * 0.001);
    let h = map(n, 0, 1, 220, 280); // Nuances de bleu à violet
    let s = 80 + random(-10, 10);
    let b = map(dist(x, y, width / 2, height / 2), 0, width, 5, 20) + n * 15;
    let a = random(0.1, 0.5);
    noStroke();
    fill(h, s, b, a);
    ellipse(x, y, random(1, 4), random(1, 4));
  }

  // 2. Source de lumière (nébuleuse / lune)
  let lightX = width * 0.7;
  let lightY = height * 0.3;
  let lightRadius = 400;
  for (let i = 0; i < 50000; i++) {
    let r = lightRadius * sqrt(random());
    let angle = random(TWO_PI);
    let x = lightX + r * cos(angle) * (1 + noise(i * 0.1) * 0.5);
    let y = lightY + r * sin(angle) * (1 + noise(i * 0.1 + 100) * 0.5);

    let d = dist(x, y, lightX, lightY);
    let a = map(d, 0, lightRadius * 1.5, 0.15, 0);
    let b = map(d, 0, lightRadius, 100, 80);
    let s = map(d, 0, lightRadius, 5, 20);

    noStroke();
    fill(50, s, b, a);
    ellipse(x, y, random(1, 5), random(1, 5));
  }

  // 3. Le sol / Le seuil
  noStroke();
  fill(240, 30, 5, 1);
  beginShape();
  vertex(0, height);
  let groundLevel = height * 0.85;
  for (let x = 0; x <= width; x += 10) {
    let y = groundLevel + noise(x * 0.005, 50) * 80 - 40;
    vertex(x, y);
  }
  vertex(width, height);
  endShape(CLOSE);

  // 4. La silhouette
  let figX = width * 0.3;
  let figY = groundLevel - 350; // Place la base de la figure sur le sol

  // 5. Particules se dissolvant
  let particleCount = 60000;
  for (let i = 0; i < particleCount; i++) {
    let startX = figX + randomGaussian(0, 30);
    let startY = figY + randomGaussian(0, 150) - 50;

    // Particules plus concentrées sur le haut du corps
    if (random() > 0.5) {
      startY = figY + randomGaussian(-150, 60);
    }

    let d_to_light = dist(startX, startY, lightX, lightY);

    let particleLife = random(50, 200);
    let p_size = random(0.5, 2.5);
    let p_hue = lerp(240, 50, random(0.7, 1.0)); // Mélange de la couleur de l'ombre et de la lumière
    let p_sat = lerp(40, 15, random(0.5));

    for (let j = 0; j < particleLife; j += 5) {
      let progress = j / particleLife;

      let currentX = lerp(startX, lightX, progress);
      let currentY = lerp(startY, lightY, progress);

      // Ajoute une turbulence au trajet
      currentX += (noise(i * 0.1, j * 0.01) - 0.5) * 150 * (1 - progress);
      currentY += (noise(i * 0.1 + 10, j * 0.01) - 0.5) * 150 * (1 - progress);

      let p_bright = lerp(10, 90, progress * progress);
      let p_alpha = (1 - progress) * 0.8;

      noStroke();
      fill(p_hue, p_sat, p_bright, p_alpha);
      ellipse(currentX, currentY, p_size, p_size);
    }
  }

  // Dessiner un noyau sombre pour la silhouette après les particules
  // pour qu'elle semble être la source.
  push();
  translate(figX, figY);
  noStroke();
  fill(240, 50, 4, 0.9);
  beginShape();
    // Tête et épaules
    vertex(-20, -180);
    curveVertex(-25, -220);
    curveVertex(0, -240);
    curveVertex(25, -220);
    vertex(20, -180);
    // Torse et bras
    vertex(50, -100);
    vertex(40, 50);
    // Jambes
    vertex(20, 200);
    vertex(-20, 200);
    vertex(-40, 50);
    vertex(-50, -100);
  endShape(CLOSE);
  pop();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // Arrière-plan sombre et texturé
  background(5, 4, 15);
  noStroke();
  for (let i = 0; i < 80000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.001, y * 0.001);
    let c = lerpColor(color(10, 8, 25), color(30, 25, 50), n);
    fill(red(c), green(c), blue(c), 15);
    ellipse(x, y, random(2, 6));
  }

  // La forme centrale qui se dissout
  let pillarX = width / 2;
  let pillarWidth = 350;
  let pillarTop = height * 0.55;
  let pillarBottom = height;

  for (let i = 0; i < 200000; i++) {
    let y = random(pillarTop, pillarBottom);
    let progress = (y - pillarTop) / (pillarBottom - pillarTop);

    // Rendre les bords flous et effrités
    let xOffset = (pow(random(), 2.5) * pillarWidth / 2) * (random() > 0.5 ? 1 : -1);
    // Réduire l'effritement vers le bas pour donner une base plus solide
    xOffset *= (1 - progress * 0.5);
    let x = pillarX + xOffset;

    let n = noise(x * 0.005, y * 0.005);
    let baseColor = lerpColor(color(90, 75, 60), color(40, 35, 30), n);

    fill(red(baseColor), green(baseColor), blue(baseColor), 30 * (1 - progress) + 10);
    ellipse(x, y, random(1, 4));
  }

  // Les particules qui montent et se transforment
  let particleCount = 6000;
  for (let i = 0; i < particleCount; i++) {
    let startX = pillarX + (random() - 0.5) * pillarWidth * 0.8;
    let startY = pillarTop - random(50);

    let y = random(height * 0.05, startY);

    // La progression de la particule dans son ascension
    let progress = map(y, startY, 0, 0, 1);
    progress = pow(progress, 0.7);

    // Mouvement sinueux basé sur le bruit
    let x = startX + (noise(y * 0.008, i * 0.1) - 0.5) * 300 * progress;

    // La couleur passe de la terre à la lumière
    let particleColor = lerpColor(color(180, 150, 110), color(255, 245, 220), progress);

    // La taille diminue en montant
    let particleSize = (1 - progress) * 6 + 1.5;

    // L'opacité est plus forte au milieu du trajet, pour un effet de "transformation"
    let alpha = 150 * sin(progress * PI);

    fill(red(particleColor), green(particleColor), blue(particleColor), alpha);
    ellipse(x, y, particleSize, particleSize);
  }

  // Lumière ambiante douce venant d'en haut
  for (let y = 0; y < height / 2; y += 10) {
    let progress = y / (height / 2);
    fill(200, 190, 170, 3 * (1 - progress));
    rect(0, y, width, 10);
  }
}

function setup() {
