  randomSeed(1);
  noiseSeed(1);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();

  // --- Arrière-plan cosmique et texturé ---
  background(0);
  for (let i = 0; i < 200000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.005, y * 0.005);
    let h = 220 + n * 60; // Teintes de bleu à violet
    let s = 20 + n * 40;
    let b = 5 + n * 15;
    let a = 50 + n * 50;
    stroke(h, s, b, a);
    point(x, y);
  }

  // --- La forme qui se dissout en particules ---
  let particleCount = 100000;
  let maxSteps = 400;
  let noiseScale = 0.001;

  for (let i = 0; i < particleCount; i++) {
    // Les particules naissent au centre-bas, dans une forme allongée
    let x = randomGaussian(width / 2, 80);
    let y = randomGaussian(height * 0.8, 150);

    for (let step = 0; step < maxSteps; step++) {
      // Le mouvement est guidé par un champ de bruit (Perlin noise flow field)
      let angle = noise(x * noiseScale, y * noiseScale, i * 0.01) * TWO_PI * 2;
      let vx = cos(angle) * 2;
      let vy = sin(angle) * 2 - 1.5; // Légère tendance à monter

      x += vx;
      y += vy;

      // Les particules s'estompent avec le temps/distance
      let progress = step / maxSteps;
      let alpha = 80 * (1 - progress * progress);
      let brightness = 100 - (progress * 50);
      let particleSize = 1.5 * (1 - progress);

      // La couleur varie légèrement pour un effet scintillant
      let h = 45 + random(-10, 10); // Teintes de jaune-orangé
      let s = 80 - progress * 60;

      if (alpha > 1 && particleSize > 0.1) {
        noStroke();
        fill(h, s, brightness, alpha);
        ellipse(x, y, particleSize, particleSize);
      } else {
        break; 
      }
    }
  }
}

