function draw() {
  // === 1. Arrière-plan sombre et texturé ===
  // Simule une toile profonde et vibrante, le vide cosmique.
  background(0);
  for (let i = 0; i < 80000; i++) {
    let x = random(width);
    let y = random(height);
    let noiseVal = noise(x * 0.001, y * 0.001);
    let h = 220 + noiseVal * 40; // Nuances de bleu-indigo-violet
    let s = 50 + noiseVal * 20;
    let b = 5 + noiseVal * 15;
    let alpha = 20 + noiseVal * 30;
    noStroke();
    fill(h, s, b, alpha);
    ellipse(x, y, random(50, 150), random(50, 150));
  }

  let centerX = width / 2;

  // === 2. La forme centrale, le corps de la vie ===
  // Couleurs chaudes et terrestres (sienne, ocre, rouge).
  // La partie basse est plus dense et cohérente.
  for (let i = 0; i < 90000; i++) {
    let y = height * 0.6 + random(height * 0.45);
    let y_norm = map(y, height * 0.6, height, 0, 1);

    let baseWidth = 350 * (1 - y_norm * 0.5);
    let x_offset = (noise(y * 0.005) - 0.5) * 200;
    let x = centerX + x_offset + (random() - 0.5) * baseWidth * (1 + (1 - y_norm));

    let h = 20 + random(-15, 25); // Gamme de orange-rouge-jaune
    let s = 70 + random(20);
    let b = 60 + random(30);
    let alpha = 5 + (1-y_norm) * 20 + random(10);
    let particleSize = 2 + (1-y_norm) * 15 + random(5);

    fill(h, s, b, alpha);
    noStroke();
    ellipse(x, y, particleSize, particleSize);
  }

  // === 3. La dissolution, la transition ===
  // Les particules s'élèvent et changent de couleur, devenant plus éthérées.
  for (let i = 0; i < 150000; i++) {
    // La position de départ est pondérée vers la partie supérieure de la forme.
    let y_start = pow(random(0, 1), 2.5);
    let y = map(y_start, 0, 1, height, 0);

    // Plus on monte, plus la dispersion horizontale est grande.
    let dispersion = pow(1 - y_start, 0.5) * (width * 0.8);
    let x_offset = (noise(y * 0.002) - 0.5) * 200;
    let x = centerX + x_offset + (random() - 0.5) * dispersion;

    // Transition des couleurs chaudes vers des couleurs lumineuses (or, cyan pâle)
    let hue_chaud = 30 + random(-15, 15);
    let hue_froid = 60 + random(-15, 30); // Or et jaunes pales
    let lerp_amount = constrain(map(y, height * 0.7, height * 0.1, 0, 1), 0, 1);
    let h = lerp(hue_chaud, hue_froid, lerp_amount);

    let s = lerp(80, 40, lerp_amount) + random(-10, 10);
    let b = lerp(70, 95, lerp_amount) + random(10);
    let alpha = lerp(15, 2, lerp_amount) + random(5);
    let particleSize = lerp(10, 1, lerp_amount) + random(3);

    fill(h, s, b, alpha);
    noStroke();
    ellipse(x, y, particleSize, particleSize);
  }
}

