function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();
}

function draw() {
  // --- 1. L'Abysse Cosmique (Arrière-plan) ---
  // Un fond sombre et profond, texturé avec du bruit pour évoquer un espace infini et vibrant.
  background(240, 60, 10);
  noStroke();
  for (let i = 0; i < 50000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.001, y * 0.001);
    let hue = map(n, 0, 1, 230, 260);
    let sat = map(y, 0, height, 70, 40);
    let bri = map(n, 0, 1, 5, 15);
    let alpha = map(dist(x, y, width / 2, height / 2), 0, width, 5, 20);
    fill(hue, sat, bri, alpha);
    ellipse(x, y, random(50, 200));
  }

  // --- 2. La Dissolution de l'Être (Particules) ---
  // Une cascade de particules représentant la vie, la conscience ou la mémoire.
  // Elles commencent chaudes et structurées en haut, puis se dispersent,
  // se refroidissent et s'estompent en descendant dans l'abysse.
  noFill();
  let particleCount = 80000;
  for (let i = 0; i < particleCount; i++) {
    // Le point de départ est plus concentré en haut et au centre.
    let startX = randomGaussian(width / 2, width * 0.15);
    let startY = pow(random(0, 1), 2.5) * height * 0.8;

    let x = startX;
    let y = startY;

    // Chaque particule est dessinée comme une petite ligne courbe qui tombe.
    let segmentLength = 20;
    beginShape();
    for (let j = 0; j < segmentLength; j++) {
      // La position le long de la chute (de 0 à 1)
      let fallProgress = map(y, 0, height, 0, 1);

      // Le mouvement est guidé par le bruit, donnant un aspect organique.
      let angle = noise(x * 0.002, y * 0.002, i * 0.1) * TWO_PI * 2;
      x += cos(angle) * 2;
      y += 1 + fallProgress * 3; // Tombe de plus en plus vite

      // Propriétés visuelles qui changent avec la descente (dissolution)
      let hue = map(fallProgress, 0, 0.7, 45, 240, true); // Jaune/Or -> Bleu
      let sat = map(fallProgress, 0, 1, 90, 50); // Désaturation
      let bri = map(fallProgress, 0, 1, 100, 20); // Assombrissement
      let alpha = map(fallProgress, 0, 1, 70, 5); // Devient transparent
      let weight = map(fallProgress, 0, 1, 1.5, 0.2); // S'affine

      strokeWeight(weight);
      stroke(hue, sat, bri, alpha);
      vertex(x, y);

      if (y > height) break;
    }
    endShape();
  }
}

function setup() {
