function draw() {
  // --- 1. The Deep Background (The Cosmic Void) ---
  // We build a deep, textured background representing the vast unknown.
  // It's not empty black, but full of subtle, deep colors.

  // Start with a base dark color
  background(240, 60, 10);

  // Add layers of noise to create texture and depth
  for (let i = 0; i < 50000; i++) {
    let x = random(width);
    let y = random(height);
    let noiseVal = noise(x * 0.001, y * 0.001);

    // Use noise to subtly vary hue and brightness
    let h = 240 + map(noiseVal, 0, 1, -20, 20);
    let s = 60 + random(-10, 10);
    let b = 10 + map(y, 0, height, 0, 15) * noiseVal; // Slightly brighter at the bottom

    noStroke();
    fill(h, s, b, 15);
    circle(x, y, random(50, 150));
  }

  // --- 2. The Unraveling Form (Life Dissolving) ---
  // This represents a complex life form or consciousness unraveling.
  // It starts as a bright, complex structure at the top and dissolves
  // into simpler particles that merge with the background.

  let numThreads = 7000;

  // Define the start and end colors for the life threads
  const colorStart = color(45, 30, 100); // Bright, warm light (life, memory)
  const colorEnd = color(245, 70, 20);   // Deep blue/purple (cosmic essence)

  for (let i = 0; i < numThreads; i++) {
    // Start threads in the upper-middle part of the canvas
    let x = width / 2 + randomGaussian(0, width / 7);
    let y = height * 0.2 + randomGaussian(0, height * 0.1);

    let lifeSpan = random(height * 0.5, height * 0.9);
    let noiseOffsetX = random(1000);
    let noiseOffsetY = random(1000);

    for (let j = 0; j < lifeSpan; j++) {
      // The progress of dissolution (0 = start, 1 = end)
      let progress = j / lifeSpan;

      // Calculate position using Perlin noise for organic drift
      let noiseFactor = map(progress, 0, 1, 0, 5);
      x += map(noise(noiseOffsetX), 0, 1, -1.5, 1.5) * noiseFactor;
      y += 1; // Always moving downwards
      noiseOffsetX += 0.005;

      // Stop if it goes off canvas
      if (y > height || x < 0 || x > width) break;

      // Color transitions from light to dark based on vertical position
      let yProgress = map(y, height * 0.2, height, 0, 1);
      let currentCol = lerpColor(colorStart, colorEnd, yProgress * yProgress);

      // Stroke weight and alpha decrease as the thread descends
      let strokeW = map(yProgress, 0, 1, 2.5, 0.1, true);
      let alpha = map(yProgress, 0, 1, 90, 20, true);

      stroke(hue(currentCol), saturation(currentCol), brightness(currentCol), alpha);
      strokeWeight(strokeW);
      point(x, y);
    }
  }
}

