    let y = random(height);
    let n = noise(x * 0.001, y * 0.001);
    let h = map(n, 0, 1, 220, 280); // Nuances de bleu à violet
    let s = random(10, 30);
    let b = random(5, 15);
    let alpha = random(10, 40);
    noStroke();
    fill(h, s, b, alpha);
    ellipse(x, y, random(50, 200), random(50, 200));
  }

  let centerX = width / 2;
  let centerY = height * 0.7;
  let coreRadius = 250;

  // Le "cœur" de la forme de vie - une structure cristalline et lumineuse
  strokeWeight(0.5);
  for (let i = 0; i < 20000; i++) {
    let angle = random(TWO_PI);
    let r = pow(random(), 2.5) * coreRadius;
    let x = centerX + cos(angle) * r;
    let y = centerY + sin(angle) * r;

    let n = noise(x * 0.01, y * 0.01);
    let hue = map(n, 0.3, 0.7, 40, 180); // Jaune-or à cyan
    let sat = map(dist(x, y, centerX, centerY), 0, coreRadius, 80, 20);
    let brt = map(dist(x, y, centerX, centerY), 0, coreRadius, 100, 70);
    let alpha = map(dist(x, y, centerX, centerY), 0, coreRadius, 60, 10);

    stroke(hue, sat, brt, alpha);
    let len = random(5, 25);
    let lineAngle = noise(x * 0.005, y * 0.005) * TWO_PI * 2;
    line(x, y, x + cos(lineAngle) * len, y + sin(lineAngle) * len);
  }

  // Les particules qui se défont et se dissolvent vers le haut
  let dissolutionHeight = height * 0.8;
  for (let i = 0; i < 6000; i++) {
    let startR = pow(random(), 2) * (coreRadius * 0.8);
    let startAngle = random(PI, TWO_PI); // Partent du haut du cœur
    let x = centerX + cos(startAngle) * startR;
    let y = centerY + sin(startAngle) * startR;

    let lifeSpan = random(200, dissolutionHeight);

    let startNoise = noise(x * 0.01, y * 0.01);
    let startHue = map(startNoise, 0.3, 0.7, 40, 180);
    let startSat = 80;
    let startBrt = 100;
    let startAlpha = random(50, 90);
    let startSize = random(1.5, 4);

    let endHue = 250; // Teinte de l'arrière-plan
    let endSat = 20;
    let endBrt = 10;
    let endAlpha = 0;
    let endSize = 0;

    for (let j = 0; j < lifeSpan; j += 4) {
      let progress = j / lifeSpan;

      let noiseAngle = noise(x * 0.003, y * 0.003, i * 0.1) * TWO_PI * 3;
      x += cos(noiseAngle) * 1.5;
      y += sin(noiseAngle) * 1.5 - (1.5 + progress * 2); // Mouvement ascendant général

      if (y < 0) break;

      let currentHue = lerp(startHue, endHue, progress);
      let currentSat = lerp(startSat, endSat, progress);
      let currentBrt = lerp(startBrt, endBrt, progress);
      let currentAlpha = lerp(startAlpha, endAlpha, progress);
      let currentSize = lerp(startSize, endSize, progress);

      noStroke();
      fill(currentHue, currentSat, currentBrt, currentAlpha);
      ellipse(x, y, currentSize);
    }
  }

  // Ajout d'une légère lueur ambiante pour unifier la scène
  for(let i = 0; i < 5; i++){
    fill(200, 50, 100, 2);
    noStroke();
    ellipse(centerX, centerY, coreRadius * 2.5 + i * 100);
  }
}

