      // Update previous position
      p.px = p.x;
      p.py = p.y;

      // Move based on Perlin noise flow field and downward pull
      let angle = noise(p.x * noiseScale, p.y * noiseScale) * TWO_PI * 4;
      let vx = cos(angle);
      let vy = sin(angle);

      // The further down, the more gravity and less flow
      let downwardForce = map(p.y, 0, height, 0.5, 2.5);

      p.x += vx * 1.5;
      p.y += vy * 0.5 + downwardForce;

      // Decrease life
      p.life -= 0.0005;

      // Draw the particle's trail
      if (p.life > 0) {
        let yRatio = p.y / height;

        let currentAlpha = map(p.life, 0, 1, 0, 200) * (1 - yRatio * 0.8);
        let currentStrokeWeight = map(p.life, 0, 1, 0.1, 2.5) * (1 - yRatio * 0.9);

        // Color transitions from gold to deep blue
        let lifeColor = lerpColor(c1, c2, p.life);
        let posColor = lerpColor(c1, c2, 1 - pow(yRatio, 2));

        // Combine life-based and position-based colors
        let finalColor = lerpColor(lifeColor, posColor, 0.5);
        finalColor.setAlpha(currentAlpha);

        stroke(finalColor);
        strokeWeight(currentStrokeWeight);
        line(p.px, p.py, p.x, p.y);
      }

      // Branching logic: more likely at the top
      if (p.life > 0.3 && p.y < height * 0.6) {
        if (random(1) < 0.012) {
          particles.push({
            x: p.x,
            y: p.y,
            px: p.x,
            py: p.y,
            life: p.life * random(0.8, 0.98),
          });
        }
      }

      // Remove dead or off-screen particles
      if (p.life <= 0 || p.y > height || p.x < 0 || p.x > width) {
        // Instead of removing, let it fade as a speck of dust
        let dustColor = lerpColor(c1, color(100), 0.2);
        dustColor.setAlpha(random(10, 40));
        fill(dustColor);
        noStroke();
        circle(p.x, p.y, random(0.5, 2));
        particles.splice(j, 1);
      }
    }
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();
}

function draw() {
  // --- 1. 背景：深邃、有机的宇宙 ---
  // 我们不用单一颜色填充，而是通过叠加大量半透明的噪点来创造深度和质感。
  background(230, 50, 10);
  let bgNoiseScale = 0.003;
  for (let i = 0; i < 50000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * bgNoiseScale, y * bgNoiseScale);
    let alpha = map(n, 0, 1, 0, 15);
    let size = map(n, 0, 1, 1, 15);
    fill(230, 30, 100, alpha);
    noStroke();
    ellipse(x, y, size, size);
  }

  // --- 2. 残骸：正在消散的有机形态 ---
  // 位于画面下方，作为粒子流的源头。
  // 使用多层、波动的曲线来表现其脆弱和正在分解的状态。
  let remnantCenterX = width / 2;
  let remnantCenterY = height * 0.85;
  let remnantRadius = 150;

  for (let j = 0; j < 20; j++) {
    push();
    translate(remnantCenterX, remnantCenterY);
    noFill();
    stroke(30, 10, 80, 5); // 枯萎的、低饱和度的颜色，非常透明
    strokeWeight(random(0.5, 3));

    beginShape();
    let noiseScale = 0.05 + j * 0.001;
    for (let angle = 0; angle < TWO_PI; angle += 0.1) {
      let r = remnantRadius + map(noise(cos(angle) * noiseScale + 10, sin(angle) * noiseScale + 20), 0, 1, -120, 120);
      r *= map(j, 0, 20, 0.5, 1.2); // 让不同层次的形状大小各异
      let x = r * cos(angle);
      let y = r * sin(angle) + pow(j, 1.5); // 增加一些垂直偏移，形成层次感
      curveVertex(x, y);
    }
    endShape(CLOSE);
    pop();
  }

  // --- 3. 粒子：升腾的生命精华/星尘 ---
  // 从残骸中涌出，向上飘散，最终融入宇宙。
  let particleCount = 80000;
  let noiseTime = 0;

  for (let i = 0; i < particleCount; i++) {
    // 粒子的初始位置在残骸附近
    let angle = random(TWO_PI);
    let radius = pow(random(1), 3) * remnantRadius; // 粒子更集中于中心
    let startX = remnantCenterX + radius * cos(angle);
    let startY = remnantCenterY + radius * sin(angle);

    // 向上移动的距离
    let journey = random(height * 0.95);
    let finalY = startY - journey;

    // 水平漂移，由噪声控制，模拟气流或能量场
    let drift = map(noise(startX * 0.002, startY * 0.002, noiseTime), 0, 1, -1, 1);
    let driftAmount = map(journey, 0, height, 0, width / 2.5);
    let finalX = startX + drift * driftAmount * map(noise(startY * 0.01), 0, 1, -1, 1);

    // 粒子的大小和透明度
    let pSize = random(0.5, 2.5);
    // 越往上，粒子越透明，仿佛正在融入背景
    let pAlpha = map(finalY, 0, height, 10, 80);

    // 绘制粒子
    fill(60, 20, 100, pAlpha); // 淡黄色，如同星光
    noStroke();
    ellipse(finalX, finalY, pSize, pSize);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);

  // Define colors
  const bgColorDeep = color(16, 0, 43); // Deepest space
  const bgColorMid = color(36, 0, 70);   // Mid-tone purple
  const mainColor = color(224, 222, 202, 200); // Pale, bone-like color
  const particleColor = color(200, 220, 255, 150); // Faint blue starlight

  // Draw a gradient background for the cosmos
  noStroke();
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(bgColorDeep, bgColorMid, inter);
    fill(c);
    rect(0, y, width, 1);
  }

  // Draw a subtle starfield/dust texture using noise
  strokeWeight(1.5);
  for (let i = 0; i < 40000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.005, y * 0.005);
    let alpha = map(n, 0, 1, 0, 50);
    stroke(255, alpha);
    point(x, y);
  }

  // Draw the central dissolving form
  stroke(mainColor);
  drawBranch(width / 2, height - 50, -PI / 2, height * 0.35, 12);

  // Draw the particles rising and unraveling from the form
  drawParticles(mainColor, particleColor);

  noLoop();
}

function drawBranch(x, y, angle, len, weight) {
  if (len < 4) {
    return;
  }

  strokeWeight(weight);

  let endX = x + cos(angle) * len;
  let endY = y + sin(angle) * len;
  line(x, y, endX, endY);

  let newLen = len * random(0.65, 0.85);
  let newWeight = weight * 0.7;

  // Branching logic
  let branches = floor(random(1, 4));
  for (let i = 0; i < branches; i++) {
    let newAngle = angle + random(-PI / 4, PI / 4);
    if(random() > 0.3){ // Main probability to branch
       drawBranch(endX, endY, newAngle, newLen, newWeight);
    }
  }
}

function drawParticles(c1, c2) {
  noStroke();

  // Draw a large number of particles
  for (let i = 0; i < 100000; i++) {
    // Start particles from the lower half of the canvas, clustered centrally
    let x = randomGaussian(width / 2, width / 5);
    let y = height - abs(randomGaussian(0, height / 2.5));

    if (y < 0) continue; // Skip particles that would start off-screen

    // Use noise to create a gentle, upward-drifting flow field
    let noiseFactor = 0.002;
    let offsetX = map(noise(x * noiseFactor, y * noiseFactor, 10), 0, 1, -150, 150);
    let offsetY = map(noise(x * noiseFactor, y * noiseFactor, 20), 0, 1, -height * 0.8, 0);

    let finalX = x + offsetX;
    let finalY = y + offsetY;

    if (finalY < 0) continue;

    // Properties change with height (as they rise)
    // As y decreases (moves up), particles become smaller, fainter, and more star-like
    let progress = map(finalY, height, 0, 0, 1);

    let particleSize = map(progress, 0, 1, 4, 0.5);
    particleSize = pow(particleSize, 1.2);

    let particleAlpha = map(progress, 0, 1, 200, 10);
    particleAlpha = pow(particleAlpha, 0.8);

    let currentColor = lerpColor(c1, c2, progress * progress);
    currentColor.setAlpha(particleAlpha);

    fill(currentColor);
    circle(finalX, finalY, particleSize * random(0.5, 1.5));
  }
}

