function drawDissolvingForm() {
  let centerX = width / 2;
  let centerY = height * 0.7;
  let formRadius = 150;

  // Draw the core of the fading form (subtle)
  for (let i = 0; i < 5; i++) {
    fill(180, 80, 100, 3 - i * 0.5);
    ellipse(centerX, centerY, formRadius * 2 + i * 50, formRadius * 2 + i * 50);
  }

  // Draw the remnants of the geometric "petals"
  let petalCount = 7;
  for (let i = 0; i < petalCount; i++) {
    if (random() > 0.4) { // Some petals are already gone
      let angle = (TWO_PI / petalCount) * i;
      let x1 = centerX + cos(angle) * (formRadius * 0.5);
      let y1 = centerY + sin(angle) * (formRadius * 0.5);
      let x2 = centerX + cos(angle - 0.2) * (formRadius * 1.8);
      let y2 = centerY + sin(angle - 0.2) * (formRadius * 1.8);
      let x3 = centerX + cos(angle + 0.2) * (formRadius * 1.8);
      let y3 = centerY + sin(angle + 0.2) * (formRadius * 1.8);

      noStroke();
      fill(180, 50, 100, random(5, 20));
      triangle(x1, y1, x2, y2, x3, y3);
    }
  }

  // Draw the streams of particles rising from the form
  let particleStreams = 400;
  for (let i = 0; i < particleStreams; i++) {
    let startAngle = random(TWO_PI);
    let startRadius = random(formRadius * 0.8);
    let x = centerX + cos(startAngle) * startRadius;
    let y = centerY + sin(startAngle) * startRadius;

    let life = 100 + random(400);
    let streamWeight = random(0.5, 3);

    let startHue = random(30, 60); // Golden/Yellow
    let startSat = random(80, 100);
    let startBright = 100;

    beginShape();
    noFill();
    for (let j = 0; j < life; j++) {
      // Flow field using noise
      let angle = noise(x * 0.001, y * 0.001) * TWO_PI * 2 - radians(90);

      let progress = j / life;

      // Particles fade and change color as they rise
      let currentHue = lerp(startHue, 240, progress * progress); // Fade to blue
      let currentSat = lerp(startSat, 30, progress);
      let currentBright = lerp(startBright, 60, progress);
      let currentAlpha = (1 - progress) * 80;

      strokeWeight(streamWeight * (1 - progress));
      stroke(currentHue, currentSat, currentBright, currentAlpha);

      vertex(x, y);

      x += cos(angle) * 3;
      y += sin(angle) * 3 - 2; // Add a general upward drift

      if (y < 0) break; // Stop if it goes off screen
    }
    endShape();
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // 深邃的宇宙背景
  background(5, 3, 15);
  drawingContext.shadowColor = color(150, 180, 255, 50);
  drawingContext.shadowBlur = 15;

  // 绘制星云和尘埃背景
  noStroke();
  for (let i = 0; i < 800; i++) {
    let x = random(width);
    let y = random(height);
    let r = random(100, 400);

    // 随机选择深蓝、深紫或近乎黑色的色调
    let c;
    let picker = random(1);
    if (picker < 0.4) {
      c = color(10, 5, 40, random(5, 15)); // 深蓝紫
    } else if (picker < 0.8) {
      c = color(40, 20, 60, random(5, 15)); // 稍亮的紫色
    } else {
      c = color(0, 0, 5, random(10, 20)); // 深邃的近黑
    }

    fill(c);
    ellipse(x, y, r, r);
  }

  // 定义形态和消散的参数
  let particleCount = 80000; // 粒子总数
  let coreColor = color(220, 210, 180); // 形态的核心颜色（骨白/米白）
  let sparkColor = color(255, 240, 200); // 闪亮粒子的颜色

  // 绘制从下到上消散的形态
  for (let i = 0; i < particleCount; i++) {
    // 粒子主要沿 Y 轴分布，底部更密集
    let y = height - pow(random(0, pow(height, 0.5)), 2);

    // 计算消散程度（y 越小，即位置越高，消散越剧烈）
    // 从画面 75% 处开始消散，到顶部达到最大
    let dissipation = map(y, height * 0.75, 0, 0, 1);
    dissipation = constrain(dissipation, 0, 1);

    // 基于 Perlin Noise 创建有机的主干形态
    let noiseFactor = noise(y * 0.002);
    let baseWidth = map(noiseFactor, 0, 1, 0, 250);

    // 粒子在主干内的基础位置
    let x = width / 2 + random(-baseWidth / 2, baseWidth / 2);

    // 根据消散程度，增加粒子的随机位移
    let offsetX = pow(random(-1, 1), 3) * dissipation * width * 0.6;
    let offsetY = -pow(dissipation, 2) * random(height * 0.3);

    x += offsetX;
    y += offsetY;

    // 根据消散程度调整粒子属性
    let particleSize = map(dissipation, 0, 1, random(1, 3), random(0.5, 2));
    let particleAlpha = map(dist(x, y, width / 2, y), 0, width / 2, 200, 0);
    particleAlpha = constrain(particleAlpha * (1.5 - dissipation), 0, 255);

    // 随机决定粒子是核心颜色还是闪光
    let c;
    if (random(1) < 0.02 && dissipation > 0.1) {
      // 少数粒子是明亮的火花
      c = sparkColor;
      c.setAlpha(particleAlpha * 0.8);
      drawingContext.shadowBlur = 10;
    } else {
      // 大多数粒子是核心颜色
      c = coreColor;
      c.setAlpha(particleAlpha);
      drawingContext.shadowBlur = 2;
    }

    fill(c);
    noStroke();
    ellipse(x, y, particleSize, particleSize);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  colorMode(HSB, 360, 100, 100, 100);
  background(230, 40, 5); // 深邃、近乎黑色的蓝色背景

  noStroke();

  const numParticles = 70000; // 粒子总数
  const particleStep = 500;   // 模拟每个粒子向上飘散的步数

  for (let i = 0; i < numParticles; i++) {
    // 粒子起始位置集中在底部中心，使用高斯分布创造核心感
    let x = randomGaussian(width / 2, width * 0.15);
    let y = height + 100 - abs(randomGaussian(0, height * 0.25));

    let lifespan = random(0.5, 1.0);

    for (let j = 0; j < particleStep; j++) {
      let progress = map(y, height, 0, 0, 1);

      // 当粒子超出一定寿命或画布时停止绘制
      if (progress > lifespan || y < 0) {
        break;
      }

      // 使用 Perlin 噪声创造有机、流动的轨迹
      let angle = noise(x * 0.001, y * 0.001) * 4 - 2; // -2 to 2 radians
      let speed = map(progress, 0, 1, 0.5, 3); // 越往上飘散越快

      x += cos(angle) * speed + (random() - 0.5) * 0.5;
      y -= speed;

      // 颜色：从底部的暖色（橙红）过渡到顶部的冷色（青蓝）
      let hue = lerp(15, 200, progress * progress);
      // 饱和度：逐渐降低
      let saturation = lerp(95, 40, progress);
      // 亮度：保持高亮，然后略微变暗
      let brightness = lerp(100, 90, progress);
      // 透明度：开始时不透明，向上逐渐消失
      let alpha = lerp(90, 0, pow(progress, 1.5));

      // 粒子大小：底部较大，顶部较小
      let particleSize = lerp(3, 0.5, progress);

      fill(hue, saturation, brightness, alpha);
      ellipse(x, y, particleSize, particleSize);
    }
  }

  noLoop();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  colorMode(HSB, 360, 100, 100, 100);
  background(240, 50, 5);
  noLoop();

  // Draw the cosmic background texture
  let bgNoiseScale = 0.002;
  for (let i = 0; i < 200000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * bgNoiseScale, y * bgNoiseScale);
    let h = 220 + n * 40; // Hues of deep blue and purple
    let s = 40 + n * 30;
    let b = 5 + n * 15;
    let alpha = 20 + n * 30;
    stroke(h, s, b, alpha);
    strokeWeight(random(1, 3));
    point(x, y);
  }

  // Draw the central form and its dissolution
  let numParticles = 250000;
  let coreBottom = height * 0.9;
  let coreTop = height * 0.1;
  let coreWidth = width * 0.2;

  for (let i = 0; i < numParticles; i++) {
    // Determine the particle's vertical position.
    // Skew the distribution towards the bottom to create a denser "source"
    let y = coreBottom - pow(random(), 1.5) * (coreBottom - coreTop);

    // The progress of dissolution (0 at the bottom, 1 at the top)
    let progress = map(y, coreBottom, coreTop, 0, 1);
    progress = constrain(progress, 0, 1);

    // Initial horizontal position based on a noisy sine wave to create an organic form
    let baseX = width / 2 +
      sin(y * 0.01) * coreWidth * 0.3 * (1 - progress * 0.5) +
      (noise(y * 0.005) - 0.5) * coreWidth;

    // As particles move up (progress increases), they spread out more
    let horizontalSpread = pow(progress, 2) * width * 1.2;
    let flowNoiseScale = 0.001;
    let flowStrength = pow(progress, 1.2) * height * 0.4;

    // Calculate displacement based on Perlin noise to create a "flow" field
    let noiseVal = noise(baseX * flowNoiseScale, y * flowNoiseScale);
    let angle = map(noiseVal, 0, 1, -PI, PI);
    let offsetX = cos(angle) * flowStrength + (random() - 0.5) * horizontalSpread;
    let offsetY = -progress * height * 0.1; // Slight upward drift

    let finalX = baseX + offsetX;
    let finalY = y + offsetY;

    // Determine color and transparency
    let h = 45 + (random() - 0.5) * 10;  // Pale gold/white
    let s = 15 - progress * 10;         // Desaturates as it dissolves
    let b = 90 + random() * 10;
    // Alpha is high at the bottom, fades to near-zero at the top
    let alpha = 80 * pow(1 - progress, 2.5);

    // Draw the particle
    strokeWeight(random(1, 2.5));
    stroke(h, s, b, alpha);
    point(finalX, finalY);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();
}

function draw() {
  // Part 1: Deep space background gradient
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(240, 50, 15), color(250, 60, 5));
    stroke(c);
    line(0, y, width, y);
  }

  // Part 2: Faint, distant stars
  noStroke();
  for (let i = 0; i < 5000; i++) {
    fill(0, 0, 100, random(5, 20));
    let x = random(width);
    let y = random(height);
    let s = random(0.5, 2.5);
    ellipse(x, y, s, s);
  }

  // Part 3: The "unraveling" life form
  // A dense cluster of particles on the left, which gets dispersed
  // and flows towards the right and up, fading out.
  let coreX = width * 0.35;
  let coreY = height * 0.55;
  let numParticles = 80000;

  for (let i = 0; i < numParticles; i++) {
    // Generate particles in a gaussian cluster around the core
    let x = randomGaussian(coreX, 150);
    let y = randomGaussian(coreY, 250);

    // Use Perlin noise to create a flow field, pushing particles
    // generally up and to the right, simulating a gentle drift.
    let noiseFactor = 0.001;
    let angle = noise(x * noiseFactor, y * noiseFactor) * 4; // Angle influenced by noise
    let magnitude = dist(x, y, coreX, coreY) * 0.8; // Particles further away are pushed more

    x += cos(angle) * magnitude;
    y += sin(angle) * magnitude - magnitude * 0.5; // Add a general upward drift

    // Determine particle properties based on distance from the original core
    let distanceFromCore = dist(x, y, coreX, coreY);

    // Closer particles are larger, brighter, and more opaque
    // Farther particles are smaller, dimmer, and more transparent
    let maxDist = 1200;
    let dNorm = constrain(distanceFromCore / maxDist, 0, 1);

    let particleSize = map(dNorm, 0, 1, 6, 0.1);
    let particleAlpha = map(dNorm, 0, 1, 80, 0);

    // Color transitions from a warm gold to a colder, pale yellow
    let startColor = color(45, 80, 100); // Warm gold
    let endColor = color(55, 30, 90);   // Pale, cool yellow
    let particleColor = lerpColor(startColor, endColor, dNorm * 1.2);

    fill(hue(particleColor), saturation(particleColor), brightness(particleColor), particleAlpha);
    noStroke();
    ellipse(x, y, particleSize, particleSize);
  }
}

function setup() {
