  for (let i = 0; i < 40000; i++) {
    let x = random(width);
    let y = random(height);
    let a = random(5, 25);
    let d = random(0.5, 1.5);
    stroke(240, 10, 100, a);
    strokeWeight(d);
    point(x, y);
  }

  // Number of life strands
  const numStrands = 4000;

  for (let i = 0; i < numStrands; i++) {
    let x = random(width * 0.2, width * 0.8);
    const startY = height + random(50);
    const noiseOffsetX = random(1000);
    const baseHue = random(40, 55); // Golden/Yellow range

    // Each strand is a series of points moving upwards
    for (let y = startY; y > -10; y -= 2) {
      // The probability of a point "breaking off" increases as it moves up
      let breakProbability = map(y, height, 0, 0.05, 1);

      // Calculate the position of the strand core
      let noiseFactor = map(y, height, 0, 0.003, 0.001);
      let sway = map(noise(y * noiseFactor, noiseOffsetX), 0, 1, -width * 0.4, width * 0.4);
      let currentX = x + sway;

      // Ensure it stays within a cone shape
      let coneFactor = map(y, height, 0, 1, 0);
      currentX = constrain(currentX, width / 2 - (width / 2 * coneFactor), width / 2 + (width / 2 * coneFactor));

      let alpha = map(y, height, 0, 90, 10);
      let weight = map(y, height, 0, 2, 0.5);

      // If the point breaks off, it becomes a scattered particle
      if (random() < breakProbability) {
        let particleSpread = map(y, height, 0, 0, width*0.7);
        let particleX = currentX + random(-particleSpread, particleSpread);
        let particleY = y + random(-particleSpread * 0.2, particleSpread * 0.2);

        let particleHue = map(y, height, 0, baseHue, 200); // Shift from gold to cyan
        let particleSaturation = map(y, height, 0, 80, 40);
        let particleBrightness = map(y, height, 0, 100, 90);
        let particleAlpha = alpha * 0.5 * random(0.5, 1);
        let particleWeight = weight * random(0.5, 1.2);

        stroke(particleHue, particleSaturation, particleBrightness, particleAlpha);
        strokeWeight(particleWeight);
        point(particleX, particleY);

      } else { // Otherwise, it's part of the main strand
        stroke(baseHue, 70, 100, alpha);
        strokeWeight(weight);
        point(currentX, y);
      }
    }
  }
}

