    let x = centerX + randomGaussian() * 80;
    let y = centerY + randomGaussian() * 80;

    // Choose particle color: mostly gold, some cyan
    let r, g, b;
    if (random() < 0.85) {
      // Golden particles
      r = 255;
      g = 220;
      b = 150;
