      // Use Perlin noise to create a flow field for particle movement
      let angle = noise(x * 0.002, y * 0.002) * TWO_PI * 2;
      let vx = cos(angle) * 1.5;
      let vy = sin(angle) * 1.5 + (progress * 2.5); // Add downward pull

      x += vx;
      y += vy;

      // Fade out and shrink as it moves
      let currentAlpha = lerp(180, 0, progress * progress);
      let currentSize = lerp(particleSize, 0, progress);

      if (currentAlpha < 1) break;

      fill(r, g, b, currentAlpha);
      ellipse(x, y, currentSize, currentSize);
    }
  }

  noLoop();
}

