function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // Define colors
  const bgColor1 = color(10, 10, 30); // Deep space blue
  const bgColor2 = color(40, 20, 60); // Dark violet
  const lifeColor = color(200, 150, 80, 200); // Warm, fading gold

  // --- 1. Draw the primordial background ---
  // A noisy texture representing the fundamental "stuff" of the universe
  loadPixels();
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let noiseVal = noise(x * 0.002, y * 0.002);
      let interColor = lerpColor(bgColor1, bgColor2, noiseVal);
      set(x, y, interColor);
    }
  }
  updatePixels();

  // --- 2. Draw the unraveling threads of life ---
  // Each "weaver" creates a thread that dissolves as it moves down
  let weavers = 2500;
  for (let i = 0; i < weavers; i++) {
    // Start near the top-center, where the structure is most coherent
    let x = width / 2 + random(-width * 0.2, width * 0.2);
    let y = random(height * 0.1, height * 0.3);

    let prevX = x;
    let prevY = y;

    // Each thread has a lifespan/length
    let lifeSpan = 150 + random(300);

    for (let j = 0; j < lifeSpan; j++) {
      // Progress of dissolution (0 at top, 1 at bottom)
      let progress = map(y, 0, height, 0, 1);

      // The angle of movement is guided by a noise field, creating flow
      // It becomes more chaotic (multiplied by progress) as it descends
      let angle = noise(x * 0.003, y * 0.003) * 4 * PI;
      angle += random(-progress, progress) * PI; // Add chaos

      let step = 3 + (1 - progress) * 5; // Steps are longer at the top
      x += cos(angle) * step;
      y += sin(angle) * step + progress * 4; // Gravity effect increases downwards

      // Fade properties based on progress
      let dissolutionFactor = pow(progress, 1.5); // Use pow() for a more dramatic fade at the end
      let currentColor = lerpColor(lifeColor, bgColor2, dissolutionFactor);
      let currentWeight = map(dissolutionFactor, 0, 1, 2.5, 0.1);
      let currentAlpha = map(dissolutionFactor, 0, 1, 80, 10);

      stroke(red(currentColor), green(currentColor), blue(currentColor), currentAlpha);
      strokeWeight(currentWeight);
      line(prevX, prevY, x, y);

      prevX = x;
      prevY = y;

      // Stop drawing if the thread goes off-screen
      if (y > height || x < 0 || x > width) {
        break;
      }
    }
  }

  // --- 3. Add a final grain layer for texture and unity ---
  // This blends the elements and gives a more analog feel
  for (let i = 0; i < 80000; i++) {
    let x = random(width);
    let y = random(height);
    let c = color(0, 0, 0, random(15));
    noStroke();
    fill(c);
    rect(x, y, 2, 2);
  }
}

