function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();

  background(240, 50, 5); // Deep, dark blue

  // Define the two "cores" of light
  const coreA = {
    pos: createVector(width * 0.35, height * 0.45),
    color: color(45, 90, 100), // Golden Yellow
    influence: width * 0.7
  };

  const coreB = {
    pos: createVector(width * 0.65, height * 0.55),
    color: color(320, 80, 100), // Vibrant Magenta
    influence: width * 0.7
  };

  // Draw the main nebula/connection
  let numParticles = 800000;
  for (let i = 0; i < numParticles; i++) {
    // Bias particle generation towards the center line between cores
    let t = pow(random(), 0.5);
    let startPos = p5.Vector.lerp(coreA.pos, coreB.pos, t);

    // Displace particles using Perlin noise to create organic swirls
    let noiseFactor = 0.0015;
    let angle = noise(startPos.x * noiseFactor, startPos.y * noiseFactor) * 8; // Multiplied for more swirling
    let magnitude = random(pow(random(), 2) * width * 0.6);
    let displacement = p5.Vector.fromAngle(angle * TWO_PI).mult(magnitude);
    let p = p5.Vector.add(startPos, displacement);

    // Calculate distance to each core
    let distA = p.dist(coreA.pos);
    let distB = p.dist(coreB.pos);

    // The color is a blend based on relative distance to each core
    let blendRatio = distA / (distA + distB);
    let particleColor = lerpColor(coreA.color, coreB.color, blendRatio);

    // Alpha and brightness are highest near the cores and fade out
    let totalInfluence = coreA.influence + coreB.influence;
    let totalDist = distA + distB;
    let alpha = map(totalDist, width * 0.2, width * 1.2, 35, 0, true);
    let particleSize = map(totalDist, width * 0.2, width * 1.2, 4, 1, true);

    // Add some noise to alpha for texture
    alpha *= noise(p.x * 0.01, p.y * 0.01);

    noStroke();
    fill(
      hue(particleColor),
      saturation(particleColor),
      brightness(particleColor),
      alpha
    );

    ellipse(p.x, p.y, particleSize, particleSize);
  }

  // Draw a few brighter "stars" or highlights for depth
  let numStars = 400;
  for (let i = 0; i < numStars; i++) {
    let x = random(width);
    let y = random(height);
    let d1 = dist(x, y, coreA.pos.x, coreA.pos.y);
    let d2 = dist(x, y, coreB.pos.x, coreB.pos.y);

    // Stars are brighter if they fall within the nebula
    if (d1 + d2 < width * 1.2) {
      let alpha = map(d1 + d2, 0, width * 1.2, 80, 10);
      let size = random(1, 2.5);
      fill(0, 0, 100, alpha * random(0.5, 1));
      noStroke();
      ellipse(x, y, size, size);
    }
  }
}

