function draw() {
  background(240, 30, 5);

  // Add a subtle texture to the background
  for (let i = 0; i < 50000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.01, y * 0.01);
    stroke(240, 30, 5 + n * 10, 50);
    point(x, y);
  }

  let focus1 = createVector(width * 0.35, height * 0.5);
  let focus2 = createVector(width * 0.65, height * 0.5);
  let noiseScale = 0.002;
  let resolution = 4;

  for (let y = 0; y < height; y += resolution) {
    for (let x = 0; x < width; x += resolution) {
      // Calculate distance to each focus point
      let d1 = dist(x, y, focus1.x, focus1.y);
      let d2 = dist(x, y, focus2.x, focus2.y);

      // Create two distinct, noisy "influence" fields
      let influence1 = noise(x * noiseScale, y * noiseScale, 10) * 600 - d1;
      let influence2 = noise(x * noiseScale + 100, y * noiseScale + 100, 20) * 600 - d2;

      let diff = influence1 - influence2;

      // The glow is strongest where the influences are equal
      let glow = pow(1 / (abs(diff) * 0.02 + 1), 3);

      let h, s, b;

      if (diff > 0) {
        // Form 1 (cooler side)
        h = 230; // Cool blue/violet
        s = 70 + glow * 20;
        b = 10 + diff * 0.1 + glow * 90;
      } else {
        // Form 2 (warmer side)
        h = 10; // Warm red/orange
        s = 85 + glow * 15;
        b = 10 + abs(diff) * 0.1 + glow * 90;
      }

      // Shift hue towards a golden yellow in the glowing area
      h = lerp(h, 45, glow);

      // Clamp values
      s = constrain(s, 0, 100);
      b = constrain(b, 0, 100);

      noStroke();
      fill(h, s, b, 90);
      rect(x, y, resolution, resolution);
    }
  }
}

