function drawStream(startX, startY, primaryPalette, secondaryPalette) {
  let numParticles = 40000;
  let center = createVector(width / 2, height / 2);
  let maxDist = dist(0, 0, center.x, center.y);

  for (let i = 0; i < numParticles; i++) {
    let p = createVector(
      startX + random(-width * 0.2, width * 0.2),
      startY + random(-height * 0.2, height * 0.2)
    );
    let pPrev = p.copy();

    let life = 50 + random(150);

    for (let j = 0; j < life; j++) {
      // Noise-driven angle for organic movement
      let noiseScale = 0.002;
      let angle = noise(p.x * noiseScale, p.y * noiseScale, i) * 4 * PI;

      // Vector pointing towards the center
      let toCenter = p5.Vector.sub(center, p);
      toCenter.normalize();

      // Combine noise and attraction to the center
      let move = p5.Vector.fromAngle(angle);
      move.lerp(toCenter, 0.4); // 0.4 is the strength of attraction
      move.mult(random(3, 8));

      p.add(move);

      // Determine color based on distance to center
      let d = dist(p.x, p.y, center.x, center.y);

      let currentPalette = primaryPalette;
      // Chance to switch to secondary palette increases near the center
      if (random() < map(d, maxDist * 0.6, 0, 0, 0.6, true)) {
        currentPalette = secondaryPalette;
      }

      let c = random(currentPalette);

      // Make strokes brighter and more opaque near the center
      let brightness = map(d, maxDist, 0, 80, 100, true);
      let alpha = map(d, maxDist, 0, 10, 60, true);

      stroke(hue(c), saturation(c), brightness, alpha);
      strokeWeight(map(d, maxDist, 0, 1, 2.5, true));

      // Draw the particle's path
      line(p.x, p.y, pPrev.x, pPrev.y);

      pPrev = p.copy();

      // Stop if particle goes off-screen
      if (p.x < 0 || p.x > width || p.y < 0 || p.y > height) {
        break;
      }
    }
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();

  // --- 1. Background ---
  // A dark, textured, nebula-like background.
  background(250, 20, 5); // Very dark purplish-blue
  noStroke();
  for (let i = 0; i < 50000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.001, y * 0.001);
    let hue = map(n, 0, 1, 220, 280); // Blues to purples
    let size = random(50, 200);
    fill(hue, 50, 10, 4);
    circle(x, y, size);
  }

  // --- 2. The Two Forms ---
  // Draw two intertwining streams of particles.
  // The color and intensity change as they get closer.
  let particles = 50000;

  for (let i = 0; i < particles; i++) {
    // Pick a random vertical position to place the next particle.
    // This builds up the image in a non-linear, painterly way.
    let y = random(height);

    // Determine color and properties based on vertical position.
    // As y decreases (moving up), the forms become hotter and brighter.
    let hue = map(y, height, height * 0.2, 260, -20); // Purple -> Red -> Orange/Yellow
    let sat = map(y, height, height * 0.4, 60, 100);
    let brt = map(y, height, height * 0.5, 70, 100);
    let alpha = map(y, height, 0, 15, 5);
    let weight = map(y, height, 0, 4, 1.5) + random(-1, 1);

    strokeWeight(max(1, weight));
    stroke(hue, sat, brt, alpha);

    // Calculate the paths for the two forms.
    // They are based on sine waves and noise for an organic, weaving motion.
    let baseOffset = map(y, height, 0, width * 0.2, 20); // Distance between forms
    let sway = sin(y * 0.0015) * width * 0.2; // Main weaving motion
    let fineNoise = (noise(y * 0.01) - 0.5) * 150; // Finer, more chaotic variation

    // Particle 1 (left stream)
    let x1 = width / 2 - baseOffset + sway + fineNoise;
    point(x1 + random(-25, 25), y + random(-25, 25));

    // Particle 2 (right stream)
    let x2 = width / 2 + baseOffset - sway - fineNoise;
    point(x2 + random(-25, 25), y + random(-25, 25));
  }

  // --- 3. Central Glow ---
  // Add a bright, glowing effect at the point of convergence to create a focal point.
  let glowY = height * 0.45;
  let glowX = width / 2 + (noise(glowY * 0.01) - 0.5) * 150;
  noStroke();
  for (let i = 0; i < 20; i++) {
    let size = random(200, 600) * (1 - i / 20);
    let alpha = 5 - i * 0.2;
    fill(45, 100, 100, alpha); // Bright, warm yellow
    circle(glowX + random(-50, 50), glowY + random(-50, 50), size);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();

  // Draw a deep, textured background
  background(240, 30, 5);
  for (let i = 0; i < 50000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.002, y * 0.002);
    let h = 230 + n * 40;
    let s = 20 + n * 20;
    let b = 5 + n * 15;
    let a = 10 + n * 20;
    noStroke();
    fill(h, s, b, a);
    ellipse(x, y, n * 80, n * 80);
  }

  // Define the core paths for the two currents using noise
  const path1 = (y) => width * 0.4 + noise(y * 0.0005, 10) * width * 0.25 - width * 0.125;
  const path2 = (y) => width * 0.6 + noise(y * 0.0005, 20) * width * 0.25 - width * 0.125;

  let particleCount = 700000;

  for (let i = 0; i < particleCount; i++) {
    let y = random(height * 1.2) - height * 0.1;

    // Decide which stream to draw a particle for
    let stream = random(1) > 0.5 ? 1 : 2;

    let baseX, particleX, particleY;
    let hue, sat, bri, alpha, size;

    if (stream === 1) { // Warm Stream (left)
      baseX = path1(y);
      particleX = baseX + (random(-1, 1) * random(-1, 1) * random(1)) * width * 0.2;

      let otherPathX = path2(y);
      let distToOther = abs(particleX - otherPathX);

      // Color logic based on distance to the other stream
      if (distToOther < 120) { // Interaction zone
        let influence = map(distToOther, 0, 120, 1, 0);
        hue = 340 + influence * 20;
        sat = 50 - influence * 30;
        bri = 90 + influence * 10;
        alpha = 2 + influence * 8;
        size = 10 + influence * 25;
      } else { // Core stream
        hue = 10 + random(-15, 25);
        if (hue < 0) hue += 360;
        sat = 80 + random(20);
        bri = 90 + random(10);
        alpha = random(1, 4);
        size = random(5, 20);
      }
    } else { // Cool Stream (right)
      baseX = path2(y);
      particleX = baseX + (random(-1, 1) * random(-1, 1) * random(1)) * width * 0.2;

      let otherPathX = path1(y);
      let distToOther = abs(particleX - otherPathX);

      if (distToOther < 120) { // Interaction zone
        let influence = map(distToOther, 0, 120, 1, 0);
        hue = 30 + influence * 20;
        sat = 40 - influence * 20;
        bri = 95 + influence * 5;
        alpha = 2 + influence * 8;
        size = 10 + influence * 25;
      } else { // Core stream
        hue = 230 + random(-30, 20);
        sat = 70 + random(30);
        bri = 85 + random(15);
        alpha = random(1, 4);
        size = random(5, 20);
      }
    }

    particleY = y + randomGaussian(0, 10);

    noStroke();
    fill(hue, sat, bri, alpha);
    ellipse(particleX, particleY, size, size);
  }
}

function setup() {
