  let noiseScale = 0.001;
  let stepLength = 2;
  let threadSteps = 250;

  // Central point of convergence
  let centerX = width / 2;
  let centerY = height * 0.55;
  let maxDist = dist(0, 0, centerX, centerY);

  // --- Draw the "Warm" side (from the right) ---
  for (let i = 0; i < numThreads; i++) {
    let x = random(width / 2, width);
    let y = random(-50, height * 0.4);

    for (let j = 0; j < threadSteps; j++) {
      let angle = noise(x * noiseScale, y * noiseScale) * TWO_PI * 2;

      let d = dist(x, y, centerX, centerY);

      // Color shifts towards white/gold at the center
      let hueVal = map(d, 0, maxDist, 45, 0); 
      let satVal = map(d, 0, maxDist, 30, 90);
      let brightVal = map(d, 0, maxDist, 100, 70);
      let alphaVal = map(d, 0, maxDist, 90, 10);

      strokeWeight(map(d, 0, maxDist, 0.5, 2.5));
      stroke(hueVal, satVal, brightVal, alphaVal);

      let nextX = x + cos(angle) * stepLength;
      let nextY = y + sin(angle) * stepLength;

      line(x, y, nextX, nextY);

      x = nextX;
      y = nextY;

      if (x < 0 || x > width || y < 0 || y > height) {
        break;
      }
    }
  }

  // --- Draw the "Cool" side (from the left) ---
  for (let i = 0; i < numThreads; i++) {
    let x = random(0, width / 2);
    let y = random(-50, height * 0.4);

    for (let j = 0; j < threadSteps; j++) {
      let angle = noise(x * noiseScale, y * noiseScale) * TWO_PI * 2;

      let d = dist(x, y, centerX, centerY);

      // Color shifts towards magenta/white at the center
      let hueVal = map(d, 0, maxDist, 330, 260);
      let satVal = map(d, 0, maxDist, 40, 90);
      let brightVal = map(d, 0, maxDist, 100, 60);
      let alphaVal = map(d, 0, maxDist, 90, 10);

      strokeWeight(map(d, 0, maxDist, 0.5, 2.5));
      stroke(hueVal, satVal, brightVal, alphaVal);

      let nextX = x + cos(angle) * stepLength;
      let nextY = y + sin(angle) * stepLength;

      line(x, y, nextX, nextY);

      x = nextX;
      y = nextY;

      if (x < 0 || x > width || y < 0 || y > height) {
        break;
      }
    }
  }

  noLoop();
}

