function draw() {
  background(240, 30, 5); // Deep, dark blue-gray

  // --- Background Stars/Texture ---
  for (let i = 0; i < 40000; i++) {
    let x = random(width);
    let y = random(height);
    let a = 10 + pow(random(1), 5) * 60;
    let s = 1 + pow(random(1), 4) * 2;
    let h = 220 + random(40);
    let sat = 10 + random(20);
    stroke(h, sat, 100, a);
    strokeWeight(s);
    point(x, y);
  }

  // --- The Two Beings/Energies ---
  // These are drawn as flows of particles or "threads" moving towards the center.

  // Being 1: Cool, from top-left
  drawFlow(8000, 0.1 * width, 0.1 * height, width / 2, height / 2, 220, 280, 0.005);

  // Being 2: Warm, from bottom-right
  drawFlow(8000, 0.9 * width, 0.9 * height, width / 2, height / 2, 340, 40, 0.005);

  // --- The Confluence/Core ---
  // A bright, energetic burst where the two flows meet.
  // Use ADD blend mode to create a glowing effect.
  blendMode(ADD);
  let centerX = width / 2;
  let centerY = height / 2;

  for (let i = 0; i < 2000; i++) {
    let angle = random(TWO_PI);
    let radius = pow(random(1), 2.5) * 300;
    let x1 = centerX;
    let y1 = centerY;
    let x2 = centerX + cos(angle) * radius;
    let y2 = centerY + sin(angle) * radius;

    let w = 1 + random(4);
    let a = 50 - (radius / 300) * 45;

    // Mix of warm and cool highlights
    let h = random() > 0.5 ? random(30, 60) : random(280, 310);
    stroke(h, 60, 100, a);
    strokeWeight(w);
    line(x1, y1, x2, y2);
  }

  // A central, brighter core
  for (let i = 0; i < 500; i++) {
    let angle = random(TWO_PI);
    let radius = pow(random(1), 3) * 100;
    let x1 = centerX;
    let y1 = centerY;
    let x2 = centerX + cos(angle) * radius;
    let y2 = centerY + sin(angle) * radius;

    stroke(50, 20, 100, 80);
    strokeWeight(1 + random(2));
    line(x1, y1, x2, y2);
  }

  blendMode(BLEND); // Reset blend mode
}

// Function to draw a flow of energy/threads
function drawFlow(num, startX, startY, endX, endY, hue1, hue2, noiseScale) {
  for (let i = 0; i < num; i++) {
    // Start each thread at a random point in a cluster around the start position
    let x = startX + (random() - 0.5) * 300;
    let y = startY + (random() - 0.5) * 300;

    // The "pull" vector towards the center
    let pullVec = createVector(endX - x, endY - y);
    pullVec.normalize();

    let segmentCount = 100 + random(200);
    let totalDist = dist(x, y, endX, endY);
    let stepLength = totalDist / segmentCount * random(0.8, 1.5);

    // Vary stroke weight and alpha for depth
    let sw = 0.5 + pow(random(), 3) * 3;
    let alpha = 10 + pow(random(), 2) * 40;

    beginShape();
    noFill();
    for (let j = 0; j < segmentCount; j++) {
      let progress = j / segmentCount;

      // Interpolate color along the path
      // Handle hue wrapping around 360
      let currentHue;
      if (abs(hue2 - hue1) > 180) {
        if (hue1 > hue2) hue2 += 360; else hue1 += 360;
      }
      currentHue = lerp(hue1, hue2, progress) % 360;

      stroke(currentHue, 70, 95, alpha);
      strokeWeight(sw);
      vertex(x, y);

      // Move the particle based on noise field and the pull towards center
      let noiseAngle = noise(x * noiseScale, y * noiseScale, i * 0.1) * TWO_PI * 2;
      let noiseVec = p5.Vector.fromAngle(noiseAngle);

      let finalVec = p5.Vector.add(pullVec.copy().mult(0.6), noiseVec.mult(0.4));
      finalVec.setMag(stepLength);

      x += finalVec.x;
      y += finalVec.y;
    }
    endShape();
  }
}

function setup() {
  createCanvas(1600, 2000);
