  noiseSeed(1);
  colorMode(HSB, 360, 100, 100, 100);
  background(240, 50, 5);

  const numParticles = 80000;
  const particles = [];
  const noiseScale = 0.0015;
  const center = createVector(width / 2, height / 2);

  // Generate particles for the two "souls"
  for (let i = 0; i < numParticles; i++) {
    let p;
    // Soul 1: Warm, from bottom-right
    if (i % 2 === 0) {
      let x = random(width * 0.7, width * 1.2);
      let y = random(height * 0.7, height * 1.2);
      let hue = random(15, 60);
      let sat = random(80, 100);
      let bri = random(80, 100);
      p = new Particle(x, y, color(hue, sat, bri, 2));
    } 
    // Soul 2: Cool, from top-left
    else {
      let x = random(-width * 0.2, width * 0.3);
      let y = random(-height * 0.2, height * 0.3);
      let hue = random(200, 260);
      let sat = random(70, 90);
      let bri = random(80, 100);
      p = new Particle(x, y, color(hue, sat, bri, 2));
    }
    particles.push(p);
  }

  // Simulate and draw the particles over time to build the image
  for (let t = 0; t < 200; t++) {
    for (const p of particles) {
      p.update(noiseScale, center);
      p.display(center);
    }
  }

  noLoop();
}

class Particle {
  constructor(x, y, c) {
    this.pos = createVector(x, y);
    this.baseColor = c;
    this.color = c;
    this.lifespan = random(150, 250);
  }

  update(noiseScale, center) {
    // Flow field force
    let angle = noise(this.pos.x * noiseScale, this.pos.y * noiseScale) * TWO_PI * 4;
    let flow = p5.Vector.fromAngle(angle);
    flow.mult(0.9);

    // Gravity towards center force
    let toCenter = p5.Vector.sub(center, this.pos);
    toCenter.normalize();
    toCenter.mult(0.2);

    // Apply forces
    this.pos.add(flow);
    this.pos.add(toCenter);

    this.lifespan--;
  }

  display(center) {
    if (this.lifespan > 0) {
      let distToCenter = dist(this.pos.x, this.pos.y, center.x, center.y);
      let maxDist = dist(0, 0, center.x, center.y);
      let normDist = 1 - (distToCenter / (maxDist * 0.8));
      normDist = constrain(normDist, 0, 1);

      // As particles get closer to the center, they get brighter and shift towards a central golden hue
      let currentHue = hue(this.color);
      let targetHue = 50; // Golden yellow
      let newHue = lerp(currentHue, targetHue, normDist * 0.5);

      let currentSat = saturation(this.color);
      let newSat = lerp(currentSat, 100, normDist);

      let currentBri = brightness(this.color);
      let newBri = lerp(currentBri, 100, normDist * 1.5);

      let newAlpha = alpha(this.color) + normDist * 5;

      noStroke();
      fill(newHue, newSat, newBri, newAlpha);
      ellipse(this.pos.x, this.pos.y, 2, 2);
    }
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();

  // Draw a dark, textured background
  background(260, 30, 10);
  for (let i = 0; i < 50000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.01, y * 0.01);
    stroke(260, 30, 10 + n * 5, 20);
    point(x, y);
  }

  // Define the two "cores" of love's energy
  const core1 = createVector(width * 0.42, height * 0.48);
  const core2 = createVector(width * 0.58, height * 0.52);

  // Define color palettes for each core
  const hue1 = 345; // Deep pink/red
  const hue2 = 40;  // Warm orange/yellow

  const noiseScale = 0.003;
  const numParticles = 4000;
  const stepsPerParticle = 200;
  const stepLength = 5;

  for (let i = 0; i < numParticles; i++) {
    let p = createVector(random(width), random(height));

    for (let j = 0; j < stepsPerParticle; j++) {
      // Get angle from Perlin noise flow field
      let angle = noise(p.x * noiseScale, p.y * noiseScale) * TWO_PI * 2;

      // Calculate distances to the cores
      let d1 = dist(p.x, p.y, core1.x, core1.y);
      let d2 = dist(p.x, p.y, core2.x, core2.y);

      // The total influence is strongest when close to either core
      let influenceDist = min(d1, d2);

      // Determine color properties based on core proximity
      let lerpAmt = d1 / (d1 + d2); // Ratio of distances
      let currentHue = lerp(hue1, hue2, lerpAmt);
      if (currentHue > 180) { // Wrap hue around the color wheel
        currentHue = currentHue - 360;
      }

      // Brightness and saturation are highest near the center of the form
      let maxDist = width * 0.35;
      let brightness = map(influenceDist, 0, maxDist, 100, 20, true);
      let saturation = map(influenceDist, 0, maxDist, 90, 40, true);
      let alpha = map(influenceDist, 0, maxDist, 25, 0, true);
      let weight = map(influenceDist, 0, maxDist, 2.5, 0.5, true);

      // Where the two fields merge, create a bright, almost white glow
      let overlapZone = 80;
      if (abs(d1 - d2) < overlapZone) {
        let overlapFactor = 1 - (abs(d1 - d2) / overlapZone);
        saturation = saturation - (40 * overlapFactor);
        brightness = brightness + (15 * overlapFactor);
        weight = weight + (1 * overlapFactor);
      }

      stroke(currentHue, saturation, brightness, alpha);
      strokeWeight(weight);

      // Draw a short line segment
      let nextP = createVector(p.x + cos(angle) * stepLength, p.y + sin(angle) * stepLength);
      line(p.x, p.y, nextP.x, nextP.y);

      // Update particle position
      p = nextP;

      // Stop if particle goes off-screen
      if (p.x < 0 || p.x > width || p.y < 0 || p.y > height) {
        break;
      }
    }
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);

  // Utiliser le mode HSB pour des transitions de couleur fluides
  // Teinte (Hue), Saturation, Luminosité (Brightness), Alpha (transparence)
  colorMode(HSB, 360, 100, 100, 100);

  // Un fond très sombre, bleu-violacé, pour représenter le vide ou l'individu seul
  background(250, 50, 10);
  noStroke();

  // Nombre de "filaments" ou "pinceaux" qui composeront l'image
  let numFilaments = 40000;

  for (let i = 0; i < numFilaments; i++) {
    // Alterner le point de départ entre le côté gauche et le côté droit
    let x, y;
    if (i % 2 === 0) {
      x = random(-100, width * 0.1);
      y = random(-100, height + 100);
    } else {
      x = random(width * 0.9, width + 100);
      y = random(-100, height + 100);
    }

    // Chaque filament est une courte série de points
    let steps = random(30, 80);
    let stepLength = 5;

    for (let j = 0; j < steps; j++) {
      // L'angle est déterminé par un champ de bruit (Perlin noise) pour un mouvement organique
      let angle = noise(x * 0.0005, y * 0.0005) * 4 * PI;

      // Déplacer le point
      x += cos(angle) * stepLength;
      y += sin(angle) * stepLength;

      // Ajouter une légère "attraction" vers l'axe vertical central
      // lerp (linear interpolation) tire doucement x vers le centre (width / 2)
      x = lerp(x, width / 2, 0.02);

      // La couleur et la taille dépendent de la distance au centre
      let distanceToCenter = abs(x - width / 2);

      // Normaliser la distance (de 0 au centre à 1 sur les bords)
      // Utiliser sqrt pour que la zone centrale chaude soit plus large et la transition plus douce
      let normDist = sqrt(distanceToCenter / (width / 2));

      // Calculer la teinte (hue) : chaude au centre, froide sur les bords
      // Le spectre va du jaune/orange (45) au rouge/magenta (vers -30, soit 330)
      let h = map(normDist, 0, 1, 45, -30);
      if (h < 0) h += 360; // Gérer le passage en dessous de 0 sur le cercle chromatique

      // Calculer la saturation : plus saturé au centre
      let s = map(normDist, 0, 1, 95, 50);

      // Calculer la luminosité : plus lumineux au centre
      let b = map(normDist, 0, 1, 100, 15);

      // Calculer la transparence : plus opaque au centre pour accumuler la lumière
      let a = map(normDist, 0, 1, 25, 2);

      // Calculer la taille du "pinceau" : plus grand au centre
      let size = map(normDist, 0, 1, 6, 1);

      // Appliquer la couleur et dessiner une particule
      fill(h, s, b, a);
      circle(x, y, size);
    }
  }

  // L'image est statique, donc on arrête la boucle de dessin
  noLoop();
}

