function drawVine(startX, hue, saturation, brightness, noiseSeedOffset) {
  let x = startX;
  let y = height;

  for (y = height + 100; y > -100; y -= 4) {
    let noiseVal = noise((y * 0.0008) + noiseSeedOffset, frameCount * 0.01);
    x += map(noiseVal, 0, 1, -4, 4);

    let thickness = 30 + 50 * noise(y * 0.001 + noiseSeedOffset + 200);

    // Dessiner plusieurs cercles pour un effet plus doux et pictural
    for (let i = 0; i < 15; i++) {
      let r = thickness * random(0.5, 1.1);
      let ang = random(TWO_PI);
      let dx = x + cos(ang) * r * 0.3;
      let dy = y + sin(ang) * r * 0.3;

      let currentHue = hue + map(noise(dx*0.005, dy*0.005), 0, 1, -10, 10);
      let currentSat = saturation + random(-10, 10);
      let currentBr = brightness + random(-10, 10);
      let alpha = 8 + random(10);

      // La couleur de la deuxième vigne (bleutée)
      if (noiseSeedOffset > 1000) {
        currentHue = 210 + map(noise(dx*0.005, dy*0.005), 0, 1, -15, 15);
      }

      fill(currentHue, currentSat, currentBr, alpha);
      noStroke();
      ellipse(dx, dy, r, r);
    }
  }
}

function addSparkles(num) {
  for (let i = 0; i < num; i++) {
    let vineChoice = random(1);
    let y = random(height * 0.1, height * 0.9);

    let x;
    if (vineChoice < 0.5) {
      // Point sur la première vigne
      let noiseVal = noise((y * 0.0008) + 1, frameCount * 0.01);
      x = width * 0.45 + map(noiseVal, 0, 1, -4 * (height - y) / 4, 4 * (height - y) / 4);
    } else {
      // Point sur la deuxième vigne
      let noiseVal = noise((y * 0.0008) + 1001, frameCount * 0.01);
      x = width * 0.55 + map(noiseVal, 0, 1, -4 * (height - y) / 4, 4 * (height - y) / 4);
    }

    x += random(-80, 80);
    y += random(-80, 80);

    let size = random(5, 15) * (1 - y/height) + 2;
    let alpha = random(40, 90);
    let br = random(90, 100);

    fill(50, 20, br, alpha);
    ellipse(x, y, size, size);

    // Cœur de l'éclat
    fill(60, 5, 100, alpha * 0.8);
    ellipse(x, y, size * 0.5, size * 0.5);
  }
}

function setup() {
