  let h = height;
  let noiseScale = 0.002;
  let particleSteps = 800;
  let stepLength = 3;

  // ===== COURANT CHAUD (Passion, Énergie) =====
  let numParticlesWarm = 800;
  for (let i = 0; i < numParticlesWarm; i++) {
    let x = random(-w * 0.1, w * 0.7);
    let y = random(-h * 0.1, h * 0.4);

    let particleHue = random(340, 380) % 360; // Teintes de rouge, magenta, orange
    let particleSat = random(80, 100);
    let particleBri = random(80, 100);
    let particleAlpha = random(3, 8);
    let particleSize = random(1, 4);

    noStroke();
    fill(particleHue, particleSat, particleBri, particleAlpha);

    for (let j = 0; j < particleSteps; j++) {
      let angle = noise(x * noiseScale, y * noiseScale) * TWO_PI * 2;

      // Biais pour diriger le flux vers le centre-droit
      let targetX = w * 0.7;
      let targetY = h * 0.6;
      let angleToTarget = atan2(targetY - y, targetX - x);
      angle = (angle * 0.7) + (angleToTarget * 0.3);

      x += cos(angle) * stepLength;
      y += sin(angle) * stepLength;

      if (x > w || x < 0 || y > h || y < 0) break;

      ellipse(x, y, particleSize, particleSize);
    }
  }

  // ===== COURANT FROID (Calme, Profondeur) =====
  let numParticlesCool = 800;
  for (let i = 0; i < numParticlesCool; i++) {
    let x = random(w * 0.3, w * 1.1);
    let y = random(h * 0.6, h * 1.1);

    let particleHue = random(190, 250); // Teintes de bleu, cyan
    let particleSat = random(70, 100);
    let particleBri = random(80, 100);
    let particleAlpha = random(3, 8);
    let particleSize = random(1, 4);

    noStroke();
    fill(particleHue, particleSat, particleBri, particleAlpha);

    for (let j = 0; j < particleSteps; j++) {
      let angle = noise(x * noiseScale, y * noiseScale) * TWO_PI * 2;

      // Biais pour diriger le flux vers le centre-gauche
      let targetX = w * 0.3;
      let targetY = h * 0.4;
      let angleToTarget = atan2(targetY - y, targetX - x);
      angle = (angle * 0.7) + (angleToTarget * 0.3);

      x += cos(angle) * stepLength;
      y += sin(angle) * stepLength;

      if (x > w || x < 0 || y > h || y < 0) break;

      ellipse(x, y, particleSize, particleSize);
    }
  }

  // ===== ÉTINCELLES DE LA RENCONTRE (Création, Synergie) =====
  let numSparks = 20000;
  for (let i = 0; i < numSparks; i++) {
    // Concentrer les étincelles dans la zone de rencontre
    let x = randomGaussian(w / 2, w / 5);
    let y = randomGaussian(h / 2, h / 5);

    let d = dist(x, y, w / 2, h / 2);
    let maxDist = dist(0, 0, w/2, h/2);

    // Probabilité d'une étincelle plus élevée près du centre
    if (random() > d / maxDist) {
        let sparkHue = random(260, 330); // Violets, magentas
        let sparkSat = random(50, 100);
        let sparkBri = 100;
        let sparkAlpha = random(20, 80);
        let sparkSize = random(1, 3);

        // Parfois, une étincelle blanche/jaune vif
        if (random() < 0.05) {
            sparkHue = 50;
            sparkSat = random(20, 80);
        }

        fill(sparkHue, sparkSat, sparkBri, sparkAlpha);
        noStroke();
        ellipse(x, y, sparkSize, sparkSize);
    }
  }

  noLoop();
}

function addBackgroundNoise() {
  let noiseDensity = 800000;
