    circle(random(width), random(height), random(1, 3));
  }

  let steps = 1000; // Nombre de pas le long de l'axe Y
  let particleCount = 100; // Nombre de particules par pas pour chaque flux

  // Paramètres pour le mouvement sinueux des flux
  let amplitude = width * 0.25;
  let frequency = 0.003;

  // Paramètres pour le bruit (Perlin noise) qui rend le mouvement organique
  let noiseScale = 0.001;
  let noiseStrength = 200;

  // Itération du bas vers le haut de la toile
  for (let i = 0; i <= steps; i++) {
    let y = map(i, 0, steps, height + 100, -100);

    // --- Calcul des positions centrales des deux flux ---
    // Le bruit est utilisé pour créer des variations non prévisibles et naturelles
    let noiseVal = noise(y * noiseScale);
    let noiseOffset = map(noiseVal, 0, 1, -noiseStrength, noiseStrength);

    // Position du flux chaud (droite)
    let x1 = width / 2 + amplitude * sin(y * frequency) + noiseOffset;

    // Position du flux froid (gauche), en opposition de phase
    let x2 = width / 2 - amplitude * sin(y * frequency + PI) - noiseOffset;

    // --- Dessin des particules pour chaque flux ---
    for (let j = 0; j < particleCount; j++) {

      // -- Flux 1 : CHAUD (Rouges, Oranges, Pinks) --
      let p1x = x1 + randomGaussian(0, 80); // Dispersion des particules
      let p1y = y + randomGaussian(0, 80);
      let size1 = random(2, 12) * (1 + noise(p1x * 0.01, p1y * 0.01));
      let hue1 = random(340, 370) % 360; // Teintes autour du rouge
      let sat1 = random(80, 100);
      let bri1 = random(80, 100);
      let alpha1 = random(2, 5);
      fill(hue1, sat1, bri1, alpha1);
      circle(p1x, p1y, size1);

      // -- Flux 2 : FROID (Bleus, Cyans, Violets) --
      let p2x = x2 + randomGaussian(0, 80);
      let p2y = y + randomGaussian(0, 80);
      let size2 = random(2, 12) * (1 + noise(p2x * 0.01, p2y * 0.01));
      let hue2 = random(200, 260); // Teintes autour du bleu/cyan
      let sat2 = random(80, 100);
      let bri2 = random(80, 100);
      let alpha2 = random(2, 5);
      fill(hue2, sat2, bri2, alpha2);
      circle(p2x, p2y, size2);
    }

    // --- L'Interaction : lueur là où les flux se rapprochent ---
    let distance = abs(x1 - x2);

    // Si la distance est faible, on ajoute des particules de "lumière"
    if (distance < 150) {
      let interactionAmount = map(distance, 150, 0, 0, 20);
      for (let k = 0; k < interactionAmount; k++) {
        let midX = (x1 + x2) / 2;
        let p3x = midX + randomGaussian(0, 40);
        let p3y = y + randomGaussian(0, 40);
        let size3 = random(5, 15);

        // Couleurs vives : magenta, jaune pâle, blanc
        let hue3 = random(45, 75); // Jaune/Or
        if(random() > 0.6) {
          hue3 = random(300, 330); // Magenta
        }
        let sat3 = random(20, 50);
        let bri3 = 100; // Très lumineux
        let alpha3 = random(5, 15) * map(distance, 150, 0, 0, 1);

        fill(hue3, sat3, bri3, alpha3);
        circle(p3x, p3y, size3);
      }
    }
  }
}

