    ellipse(x, y, 2, 2);
  }

  // Dessine les deux flux d'énergie qui s'entrelacent
  drawFlow(width * 0.2, height, 330, -PI / 2.5, 8000); // Flux chaud (magenta/rouge)
  drawFlow(width * 0.8, height, 200, -PI / 1.7, 8000); // Flux froid (cyan/bleu)

  noLoop();
