function drawFlow(startX, startY, hue, initialAngle, steps) {
  let x = startX;
  let y = startY;
  let angle = initialAngle;

  for (let i = 0; i < steps; i++) {
    // La direction est influencée par le bruit de Perlin pour un mouvement organique
    let noiseFactor = noise(x * 0.001, y * 0.001, i * 0.0005);
    angle += map(noiseFactor, 0, 1, -0.2, 0.2);

    // Tendance générale à monter
    x += cos(angle) * 3;
    y += sin(angle) * 3;

    // Garde le flux à l'intérieur de la toile avec une légère "poussée" vers le centre
    if (x < 0 || x > width) {
      angle = PI - angle;
      x = constrain(x, 0, width);
    }
     if (y < 0) {
      angle = -angle;
      y = constrain(y, 0, height);
    }

    // Dessine une "particule" de couleur semi-transparente
    let particleSize = random(15, 45) + sin(i * 0.01) * 10;
    let particleSat = 70 + random(30);
    let particleBri = 80 + random(20);
    let particleAlpha = 3 + noise(i * 0.1) * 4;

    fill(hue, particleSat, particleBri, particleAlpha);
    ellipse(x + random(-10, 10), y + random(-10, 10), particleSize, particleSize);
  }
}

