    let d = dist(x, y, width / 2, height / 2);
    let alpha = map(d, 0, width, 20, 0);
    let starSize = random(0.5, 1.5);
    fill(0, 0, 100, alpha);
    noStroke();
    ellipse(x, y, starSize, starSize);
  }

  // Configuration des deux flux
  const numParticles = 2500;
  const steps = 600;
  const noiseScale = 0.0015;
  const stepLength = 2;
  const hotspot = createVector(width / 2, height / 2 - 200);

  // Dessiner les deux flux d'énergie
  drawFlow(numParticles, steps, noiseScale, stepLength, hotspot, 'left');
  drawFlow(numParticles, steps, noiseScale, stepLength, hotspot, 'right');
}

function drawFlow(num, maxSteps, nScale, sLen, hot, side) {
  for (let i = 0; i < num; i++) {
    let startX, startY;
    if (side === 'left') {
      startX = random(0, width * 0.3);
      startY = random(height * 0.8, height);
    } else { // 'right'
      startX = random(width * 0.7, width);
      startY = random(height * 0.8, height);
    }

    let p = createVector(startX, startY);

    beginShape();
    noFill();
    for (let j = 0; j < maxSteps; j++) {
      let angle = noise(p.x * nScale, p.y * nScale) * TWO_PI * 2;
      let d = dist(p.x, p.y, hot.x, hot.y);

      // La couleur dépend de la proximité du "point chaud" central
      let hue = map(d, 0, width * 0.7, 0, 300); // 0 (rouge) au centre, 300 (magenta) loin
      hue = constrain(hue, 0, 300);
      if (hue > 50 && hue < 260) {
        hue = map(hue, 50, 260, 50, 260); // Ajustement pour une transition plus douce
      }

      let saturation = map(d, 0, width * 0.6, 100, 40);
      saturation = constrain(saturation, 40, 100);

      let brightness = map(d, 0, width * 0.3, 100, 60);
      brightness = constrain(brightness, 60, 100);

      let alpha = map(d, 0, width * 0.4, 25, 5);
      alpha = constrain(alpha, 5, 25);

      let weight = map(d, 0, width * 0.4, 1.5, 0.5);
      weight = constrain(weight, 0.5, 1.5);

      strokeWeight(weight);
      stroke(hue, saturation, brightness, alpha);
      vertex(p.x, p.y);

      // Mettre à jour la position de la particule
      let step = createVector(cos(angle) * sLen, sin(angle) * sLen);
      p.add(step);

      // Sortir si hors de l'écran
      if (p.x < 0 || p.x > width || p.y < 0 || p.y > height) {
        break;
      }
    }
    endShape();
  }
}

