    let n = noise(x * 0.005, y * 0.005);
    let h = 240 + n * 40; // Nuances de bleu/violet
    let s = 50 + n * 30;
    let b = 5 + n * 15;
    let a = random(5, 20);
    fill(h, s, b, a);
    noStroke();
    circle(x, y, random(1, 4));
  }

  // Les deux essences qui fusionnent
  // On utilise un système de particules pour chaque essence
  drawEssence(width * 0.25, height * 1.1, -1); // Essence de gauche
  drawEssence(width * 0.75, height * 1.1, 1);  // Essence de droite
}

function drawEssence(originX, originY, direction) {
  let targetX = width / 2 + random(-100, 100);
  let targetY = height * 0.4 + random(-100, 100);

  for (let i = 0; i < 80000; i++) {
    let progress = pow(random(1), 2.5); // Les particules se concentrent vers la cible

    let currentX = lerp(originX, targetX, progress);
    let currentY = lerp(originY, targetY, progress);

    // Perturbation par le bruit de Perlin pour un aspect organique
    let noiseFactor = 500 * (1 - progress);
    let noiseX = (noise(currentX * 0.002, currentY * 0.002, 10) - 0.5) * noiseFactor * direction;
    let noiseY = (noise(currentX * 0.002, currentY * 0.002, 20) - 0.5) * noiseFactor * 1.5;

    let x = currentX + noiseX;
    let y = currentY + noiseY;

    // Calcul de la couleur en fonction de la proximité du centre de la fusion
    let distToTarget = dist(x, y, targetX, targetY);
    let hue, saturation, brightness, alpha;

    if (distToTarget < 350) {
      // Zone d'incandescence
      let d = map(distToTarget, 0, 350, 1, 0);
      hue = 15 + d * 45; // De l'orange vif (15) au rouge (0) puis au jaune (60)
      saturation = 90 + d * 10;
      brightness = 100;
      alpha = 2 + pow(d, 2) * 20;
    } else {
      // Zone extérieure de l'essence
      let d = map(distToTarget, 350, 1200, 0, 1);
      hue = 330 - d * 30; // Du rose/magenta (330) au rouge
      saturation = 80;
      brightness = 90 + d * 10;
      alpha = map(progress, 0, 1, 0.1, 3);
    }

    // Assurer que la teinte reste dans les valeurs chaudes
    hue = (hue + 360) % 360;

    fill(hue, saturation, brightness, alpha);
    noStroke();

    let particleSize = 1 + (1 - progress) * 5 + map(distToTarget, 0, 350, 3, 0);
    circle(x, y, particleSize);
  }

  // Ajouter un halo central plus diffus
  for(let i = 0; i < 50; i++) {
    let r = random(20, 400);
    let ang = random(TWO_PI);
    let x = targetX + cos(ang) * r;
    let y = targetY + sin(ang) * r;

    let d = dist(x, y, targetX, targetY);
    let alpha = map(d, 0, 400, 5, 0);
    let size = map(d, 0, 400, 10, 50);
    let h = 30 + random(-15, 15);

    fill(h, 100, 100, alpha);
    noStroke();
    circle(x, y, size);
  }
}

function setup() {
  createCanvas(1600, 2000);
