  let core1Y = height * 0.45;

  for (let i = 0; i < numParticles; i++) {
    // Utilisation du bruit de Perlin pour créer une forme organique et fluide
    let angle = noise(i * 0.005, 10) * TWO_PI * 2;
    let radius = noise(i * 0.008, 20) * (width * 0.45);

    // Distorsion supplémentaire pour une forme moins circulaire
    let x = core1X + cos(angle) * radius * (1 + noise(i * 0.01) * 0.5);
    let y = core1Y + sin(angle) * radius * (1 + noise(i * 0.01) * 0.5);

    // Couleur chaude avec une transparence élevée pour créer de la profondeur
    let r = 200 + random(55);
    let g = 50 + random(100);
    let b = 10;
    fill(r, g, b, 10);

    let particleSize = 1 + random(4);
    ellipse(x, y, particleSize, particleSize);
  }

  // --- L'ENTITÉ 2 : Calme, profonde (Bleus, Cyans) ---
  // Positionnée sur la droite, légèrement en bas pour créer une dynamique
  let core2X = width * 0.65;
  let core2Y = height * 0.55;

  for (let i = 0; i < numParticles; i++) {
    // On utilise un offset différent dans le bruit pour obtenir une forme distincte
    let angle = noise(i * 0.005, 30) * TWO_PI * 2;
    let radius = noise(i * 0.008, 40) * (width * 0.4);

    let x = core2X + cos(angle) * radius * (1 + noise(i * 0.01, 5) * 0.5);
    let y = core2Y + sin(angle) * radius * (1 + noise(i * 0.01, 5) * 0.5);

    // Couleur froide
    let r = 10;
    let g = 100 + random(100);
    let b = 200 + random(55);
    fill(r, g, b, 10);

    let particleSize = 1 + random(4);
    ellipse(x, y, particleSize, particleSize);
  }

  // --- LA CONNEXION : La lumière qui naît de la rencontre ---
  // Centrée entre les deux entités, lumineuse et dorée
  let connectionX = (core1X + core2X) / 2;
  let connectionY = (core1Y + core2Y) / 2;

  for (let i = 0; i < numParticles / 2; i++) {
    // Forme plus concentrée mais rayonnante
    let angle = random(TWO_PI);
    // Un rayon qui suit une distribution non-uniforme pour créer un cœur brillant
    let radius = pow(random(1), 2) * (width * 0.3);

    // Bruit de Perlin pour un rayonnement plus organique
    let x = connectionX + cos(angle) * radius * (1 + (noise(i * 0.05) - 0.5) * 0.8);
    let y = connectionY + sin(angle) * radius * (1 + (noise(i * 0.05, 100) - 0.5) * 0.8);

    // Couleur dorée, lumineuse
    let r = 255;
    let g = 220 + random(35);
    let b = 150;
    fill(r, g, b, 12);

    let particleSize = 1 + random(5);
    ellipse(x, y, particleSize, particleSize);
  }

  noLoop(); // La peinture est statique
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();

  background(225, 30, 10); // Fond bleu nuit profond

  let w = width;
  let h = height;

  // Définir les deux "sources" d'énergie, l'une chaude, l'autre froide.
  const warmSource = { x: -w * 0.2, y: h * 0.3 };
  const coolSource = { x: w * 1.2, y: h * 0.7 };
  const colorWarm = color(340, 90, 100); // Magenta / Rouge
  const colorCool = color(190, 80, 100); // Cyan / Bleu

  const numParticles = 150000;
  const noiseScale = 0.001;

  // Dessiner les courants principaux
  for (let i = 0; i < numParticles; i++) {
    let x = random(w);
    let y = random(h);

    // La couleur est un mélange basé sur la proximité des deux sources
    let dWarm = dist(x, y, warmSource.x, warmSource.y);
    let dCool = dist(x, y, coolSource.x, coolSource.y);
    let ratio = dWarm / (dWarm + dCool);
    let baseColor = lerpColor(colorCool, colorWarm, ratio);

    // Le centre est plus brillant et plus saturé
    let dCenter = dist(x, y, w / 2, h / 2);
    let maxDist = dist(0, 0, w / 2, h / 2);
    let centerFactor = map(dCenter, 0, maxDist, 1, 0.2);

    let hVal = hue(baseColor);
    let sVal = saturation(baseColor) * pow(centerFactor, 0.5);
    let bVal = brightness(baseColor) * pow(centerFactor, 0.3);
    let alphaVal = map(dCenter, 0, maxDist, 8, 1) * random(0.5, 1.5);

    let particleColor = color(hVal, sVal, bVal, alphaVal);
    stroke(particleColor);
    strokeWeight(random(1, 2.5));

    // Mouvement basé sur le Perlin noise pour un effet de flux
    let angle = noise(x * noiseScale, y * noiseScale) * TWO_PI * 2;
    let len = map(dCenter, 0, maxDist, 15, 2);
    let vx = cos(angle) * len;
    let vy = sin(angle) * len;

    line(x, y, x + vx, y + vy);
  }

  // Ajouter un noyau central incandescent
  const coreParticles = 20000;
  for (let i = 0; i < coreParticles; i++) {
    let a = random(TWO_PI);
    let r = pow(random(), 3) * (w * 0.2);
    let x = w / 2 + cos(a) * r;
    let y = h / 2 + sin(a) * r;

    let dCenter = dist(x, y, w / 2, h / 2);
    let alpha = map(dCenter, 0, w * 0.2, 10, 0);

    // Le coeur est jaune/blanc, la couleur de la lumière pure
    let hVal = random(40, 60);
    let sVal = map(dCenter, 0, w*0.2, 20, 80);
    let bVal = 100;

    stroke(hVal, sVal, bVal, alpha * random(0.5, 1));
    strokeWeight(random(1, 3));
    point(x, y);
  }

  // Ajouter un léger grain pour la texture
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let grain = (random() - 0.5) * 15;
    pixels[i] = pixels[i] + grain;
    pixels[i + 1] = pixels[i + 1] + grain;
    pixels[i + 2] = pixels[i + 2] + grain;
  }
  updatePixels();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();
}

function draw() {
  // === 1. L'arrière-plan : un vide subtil et profond ===
  background(240, 80, 15); // Un bleu très sombre, presque noir

  // Ajout d'une texture de "poussière d'étoiles" pour donner de la profondeur
  for (let i = 0; i < 50000; i++) {
    let x = random(width);
    let y = random(height);
    let d = random(1, 3);
    let a = random(5, 20);
    let h = random(230, 280);
    noStroke();
    fill(h, 50, 50, a);
    ellipse(x, y, d, d);
  }

  // === 2. Le cœur : la source lumineuse et chaude ===
  let coreX = width / 2;
  let coreY = height * 0.45;

  // Création d'un halo doux et rayonnant
  for (let r = 800; r > 0; r -= 5) {
    let alpha = map(r, 0, 800, 10, 0);
    let hue = map(r, 0, 800, 45, 60); // Jaune-orangé chaud
    let sat = map(r, 0, 800, 80, 40);
    let br = map(r, 0, 800, 100, 60);
    fill(hue, sat, br, alpha);
    noStroke();
    ellipse(coreX, coreY, r, r);
  }

  // === 3. Les vrilles : l'amour qui se propage ===
  let walkers = [];
  const numWalkers = 2500;

  // Initialisation des "marcheurs" qui dessineront les vrilles
  for (let i = 0; i < numWalkers; i++) {
    let angle = random(TWO_PI);
    let radius = random(1, 5);
    walkers.push({
      pos: createVector(coreX + cos(angle) * radius, coreY + sin(angle) * radius),
      noiseOffsetX: random(1000),
      noiseOffsetY: random(1000),
      hue: random(330, 390) % 360, // Nuances de magenta, rose et rouge
      life: 1.0
    });
  }

  // Simulation de la propagation sur un grand nombre d'étapes
  const steps = 1200;
  for (let t = 0; t < steps; t++) {
    for (let i = walkers.length - 1; i >= 0; i--) {
      let w = walkers[i];

      // La direction est déterminée par le bruit de Perlin pour un mouvement organique
      let angle = noise(w.noiseOffsetX, w.noiseOffsetY) * TWO_PI * 2;
      let vel = p5.Vector.fromAngle(angle);

      // Une force pousse légèrement les vrilles vers l'extérieur
      let forceOut = p5.Vector.sub(w.pos, createVector(coreX, coreY));
      forceOut.normalize();
      forceOut.mult(0.1);
      vel.add(forceOut);
      vel.mult(map(t, 0, steps, 2.5, 0.5)); // Ralentit avec le temps

      w.pos.add(vel);

      // La vie de la particule diminue, affectant sa visibilité
      w.life -= 0.0007;
      if (w.life <= 0) {
        walkers.splice(i, 1);
        continue;
      }

      // Dessin de la particule
      let distFromCore = dist(w.pos.x, w.pos.y, coreX, coreY);
      let alpha = map(w.life, 0, 1, 0, 40) * map(distFromCore, 0, 1000, 1, 0.5, true);
      let sat = map(distFromCore, 0, 1200, 90, 60, true);
      let br = map(w.life, 0, 1, 50, 100);
      let d = map(w.life, 1, 0, 3, 0.5);

      // La couleur change légèrement avec le temps et la distance
      w.hue = (w.hue + 0.05) % 360;

      stroke(w.hue, sat, br, alpha);
      strokeWeight(d);
      point(w.pos.x, w.pos.y);

      // Probabilité de se diviser pour créer une nouvelle branche
      if (random(1) < 0.001 && walkers.length < 5000) {
        walkers.push({
          pos: w.pos.copy(),
          noiseOffsetX: random(1000),
          noiseOffsetY: random(1000),
          hue: (w.hue + random(-20, 20)) % 360,
          life: w.life * 0.8 // La nouvelle branche a une vie plus courte
        });
      }

      // Mise à jour des offsets pour le bruit de Perlin
      w.noiseOffsetX += 0.01;
      w.noiseOffsetY += 0.01;
    }
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();
}

function draw() {
  // --- 1. Background ---
  // Create a deep, dark blue gradient for a cosmic feel.
  let topColor = color(230, 50, 15);
  let bottomColor = color(250, 60, 5);
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(topColor, bottomColor);
    stroke(c);
    line(0, y, width, y);
  }

  // --- 2. Energy Flows ---
  // Use ADD blend mode to make overlapping lights brighter, creating a glow effect.
  blendMode(ADD);

  // Define parameters for the two sources of energy.
  const numStrands = 4000;
  const strandLength = 200;
  const noiseScale = 0.002;
  const stepSize = 5;

  // Left source (Cool color)
  const leftColor = color(200, 80, 70, 5);
  for (let i = 0; i < numStrands; i++) {
    let x = random(-100, width * 0.2);
    let y = random(height);

    noFill();
    stroke(leftColor);
    strokeWeight(random(0.5, 2));

    beginShape();
    for (let j = 0; j < strandLength; j++) {
      let angle = noise(x * noiseScale, y * noiseScale) * TWO_PI * 4;
      // Add a bias to move towards the center-right
      let biasX = map(x, 0, width, 1, 0) * 1.5; 
      let biasY = (height / 2 - y) * 0.005;

      x += cos(angle) * stepSize + biasX;
      y += sin(angle) * stepSize + biasY;

      if (x > width + 50 || x < -50 || y > height + 50 || y < -50) break;
      curveVertex(x, y);

      // As it approaches the center, add a brighter, warmer highlight
      let d = abs(x - width / 2);
      if (d < width * 0.2) {
        let alpha = map(d, width * 0.2, 0, 0, 15);
        stroke(50, 80, 100, alpha);
        strokeWeight(random(1, 2.5));
        point(x, y);
      }
    }
    endShape();
  }

  // Right source (Warm color)
  const rightColor = color(330, 70, 90, 5);
  for (let i = 0; i < numStrands; i++) {
    let x = random(width * 0.8, width + 100);
    let y = random(height);

    noFill();
    stroke(rightColor);
    strokeWeight(random(0.5, 2));

    beginShape();
    for (let j = 0; j < strandLength; j++) {
      let angle = noise(x * noiseScale, y * noiseScale) * TWO_PI * 4;
      // Add a bias to move towards the center-left
      let biasX = map(x, width, 0, -1, 0) * 1.5;
      let biasY = (height / 2 - y) * 0.005;

      x += cos(angle) * stepSize + biasX;
      y += sin(angle) * stepSize + biasY;

      if (x > width + 50 || x < -50 || y > height + 50 || y < -50) break;
      curveVertex(x, y);

      // As it approaches the center, add a brighter, warmer highlight
      let d = abs(x - width / 2);
      if (d < width * 0.2) {
        let alpha = map(d, width * 0.2, 0, 0, 15);
        stroke(50, 90, 100, alpha);
        strokeWeight(random(1, 2.5));
        point(x, y);
      }
    }
    endShape();
  }

  // --- 3. Central Glow & Stardust ---
  // Add a fine dust of particles to enhance the atmosphere.
  for (let i = 0; i < 20000; i++) {
    let x = random(width);
    let y = random(height);
    let d_center = dist(x, y, width / 2, height / 2);

    // Make particles in the center brighter and denser
    if (random() > d_center / (height * 0.7)) {
      let size = random(0.5, 2);
      let alpha = random(1, 10);
      // Give them a warm, golden color
      stroke(45, 100, 100, alpha);
      strokeWeight(size);
      point(x, y);
    }
  }
}

