      let h = random(340, 360);
      particles.push(new Particle(x, y, h));
    } else {
      // Source 2: Hotter, yellowish tones
      let x = width / 2 + random(80, 120);
      let y = height * 0.85 + random(-50, 50);
      let h = random(15, 45);
      particles.push(new Particle(x, y, h));
    }
  }
}

function draw() {
  // Draw a deep, textured background
  background(240, 50, 5);
  for (let i = 0; i < 50000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.01, y * 0.01);
    let c = color(240, 50, 5 + n * 10, 50);
    noStroke();
    fill(c);
    ellipse(x, y, 2, 2);
  }

  // Simulate and draw particle paths
  strokeWeight(1.5);
  for (let t = 0; t < simulationSteps; t++) {
