class Particle {
  constructor(x, y, h) {
    this.pos = createVector(x, y);
    this.history = [this.pos.copy()];
    this.baseHue = h;
    this.hue = h;
  }

  update() {
    // Curl noise field for organic flow
    let angle = noise(this.pos.x * noiseScale, this.pos.y * noiseScale) * TWO_PI * 3;
    let v = p5.Vector.fromAngle(angle);

    // Add a general upward force to guide the flow
    let upwardForce = createVector(0, -1.2);
    v.add(upwardForce);
    v.setMag(1);

    // Add a slight pull towards the center
    let centerPull = createVector(width / 2 - this.pos.x, height / 2 - this.pos.y);
    centerPull.setMag(0.05);
    v.add(centerPull);

    this.pos.add(v);
  }

  display(time) {
    // Draw a small line segment representing the particle's movement
    let prevPos = this.history[this.history.length - 1];
    if (p5.Vector.dist(this.pos, prevPos) > 0.1) {
      // Color fades and gets less saturated over time/distance from bottom
      let progress = 1 - (this.pos.y / height);
      let saturation = 60 + progress * 40;
      let brightness = 80 + progress * 20;

      // Alpha is low to create a smoky/ethereal effect
      // It's also higher at the beginning of the simulation
      let alpha = 8 - (time / simulationSteps) * 7;

      // Hue can shift slightly based on position
      let hueShift = map(noise(this.pos.x * 0.005, this.pos.y * 0.005), 0, 1, -5, 5);
      this.hue = (this.baseHue + hueShift + 360) % 360;

      stroke(this.hue, saturation, brightness, alpha);
      line(this.pos.x, this.pos.y, prevPos.x, prevPos.y);

      this.history.push(this.pos.copy());
      // Keep history short to save memory, though for a static image this is less critical
      if (this.history.length > 2) {
        this.history.splice(0, 1);
      }
    }
  }
}

