/**
 * 绘制一股上升的、烟雾状的能量流
 * @param {number} startX - 能量流的起始X坐标中心
 * @param {p5.Color} baseColor - 能量流的基础颜色
 * @param {number} noiseSeedOffset - 噪声种子偏移，以区分不同的能量流
 */
function drawPlume(startX, baseColor, noiseSeedOffset) {
  let particleCount = 45000;
  for (let i = 0; i < particleCount; i++) {
    // 粒子起始于画布底部，并在起始X坐标附近随机散布
    let x = startX + randomGaussian(0, width / 12);
    let y = height + random(-50, 50);

    // 每个粒子的生命周期不同，模拟了能量的动态感
    let life = 120 + random(180);
    for (let j = 0; j < life; j++) {
      let progress = j / life; // 0 to 1

      // 使用Perlin噪声计算一个飘忽不定的角度
      let noiseVal = noise(x * 0.005, y * 0.005 + noiseSeedOffset);
      let angle = map(noiseVal, 0, 1, -PI, PI);

      // 粒子在上升过程中会受到向画布中心的吸引力
      let pullToCenter = (width / 2 - x) * 0.0035;
      x += cos(angle) * 2.5 + pullToCenter;
      y -= 3.0; // 粒子向上移动

      // 如果粒子移出画布顶部，则停止绘制
      if (y < 0) break;

      // 设置填充色并绘制一个小的圆形粒子
      fill(baseColor);
      circle(x, y, random(2, 6));
    }
  }
}

/**
 * 在两个能量流交汇处绘制一个明亮的核心
 * @param {number} cx - 核心的中心X坐标
 * @param {number} cy - 核心的中心Y坐标
 * @param {number} radius - 核心的大致半径
 */
function drawCore(cx, cy, radius) {
  let particleCount = 20000;
  for (let i = 0; i < particleCount; i++) {
    // 使用 pow(random(), 2) 使粒子更集中于中心
    let r = pow(random(), 2) * radius;
    let a = random(TWO_PI);
    let x = cx + cos(a) * r;
    let y = cy + sin(a) * r;

    // 核心的颜色从温暖的橙色渐变到明亮的白色
    let coreColor1 = color(255, 150, 100);
    let coreColor2 = color(255, 255, 220);
    let lerpedColor = lerpColor(coreColor1, coreColor2, random());

    // 设置一个较高的透明度，让核心区域显得更亮
    fill(red(lerpedColor), green(lerpedColor), blue(lerpedColor), random(20, 120));
    circle(x, y, random(1, 5));
  }
}

