function drawSoulForm(centerX, baseHue, particleCount, spreadX, spreadY) {
  let centerY = height / 2 + 100;

  for (let i = 0; i < particleCount; i++) {
    // 使用高斯分布让粒子更集中在中心
    let x = randomGaussian(0, spreadX * 0.4);
    let y = randomGaussian(0, spreadY * 0.4);

    // 扭曲形状，使其更有机
    let angle = atan2(y, x);
    let distFromCenter = sqrt(x * x + y * y);
    let noiseFactor = noise(x * 0.005, y * 0.005);
    let distortedDist = distFromCenter * (1 + (noiseFactor - 0.5) * 0.8);

    let finalX = centerX + cos(angle) * distortedDist;
    let finalY = centerY + sin(angle) * distortedDist;

    // 越靠近中心越亮，越边缘越暗淡
    let d = dist(finalX, finalY, centerX, centerY);
    let alpha = map(d, 0, max(spreadX, spreadY), 5, 0, true);

    // 颜色变化
    let hue = baseHue + random(-10, 10);
    let sat = map(d, 0, spreadY, 90, 60, true) + random(-10, 10);
    let br = map(d, 0, spreadY, 100, 80, true);

    fill(hue, sat, br, alpha);
    let particleSize = random(2, 5) * (1 - d / spreadY) + 1;
    ellipse(finalX, finalY, particleSize, particleSize);
  }
}

