    let color = random(leftColors);
    walkers.push(new Walker(pos, color, 'left'));
  }

  // 初始化来自右侧的“行走者”
  for (let i = 0; i < numWalkersPerSide; i++) {
    let pos = createVector(random(width - 100, width + 100), random(height, height + 200));
    let color = random(rightColors);
    walkers.push(new Walker(pos, color, 'right'));
  }

  // 模拟并绘制所有路径
  for (let i = 0; i < numSteps; i++) {
