class Walker {
  constructor(pos, baseColor, side) {
    this.pos = pos;
    this.prevPos = pos.copy();
    this.baseColor = color(baseColor);
    this.side = side;

    // 添加透明度
    this.strokeColor = color(red(this.baseColor), green(this.baseColor), blue(this.baseColor), 15);
    this.noiseOffsetX = random(1000);
    this.noiseOffsetY = random(1000);
  }

  update() {
    this.prevPos = this.pos.copy();

    // 1. 基于柏林噪声的有机运动
    let angle = noise(this.pos.x * 0.001 + this.noiseOffsetX, this.pos.y * 0.001 + this.noiseOffsetY) * 4;
    let noiseVel = p5.Vector.fromAngle(radians(angle * 360));
    noiseVel.mult(2);

    // 2. 一个将它们向上和向中心拉的引力
    let target = createVector(width / 2, height / 3);
    let attraction = p5.Vector.sub(target, this.pos);
    attraction.setMag(0.1);

    // 结合运动
    this.pos.add(noiseVel);
    this.pos.add(attraction);

    // 3. 颜色混合逻辑
    // 离中心垂直线越近，越趋向于融合色
    let distanceFromCenter = abs(this.pos.x - width / 2);
    let blendAmount = map(distanceFromCenter, width / 2, 0, 0, 1, true);

    let targetColor = color(mergeColor);
    let blendedColor = lerpColor(this.baseColor, targetColor, blendAmount * blendAmount);

    this.strokeColor = color(red(blendedColor), green(blendedColor), blue(blendedColor), 15);
  }

  display() {
    if (this.pos.dist(this.prevPos) > 0) {
      stroke(this.strokeColor);
      strokeWeight(map(this.pos.y, height, 0, 1, 3));
      line(this.prevPos.x, this.prevPos.y, this.pos.x, this.pos.y);
    }
  }
}

