  drawFlows(source2, 15000, 35);
}

function drawFlows(source, numParticles, hueRange) {
  const noiseScale = 0.001;
  const stepLength = 2;
  const maxSteps = 400;

  for (let i = 0; i < numParticles; i++) {
    let angle = random(TWO_PI);
    let radius = pow(random(1), 2) * 100; // Concentrate starts near the center
    let x = source.x + cos(angle) * radius;
    let y = source.y + sin(angle) * radius;

    let h = source.hue + random(-hueRange / 2, hueRange / 2);
    if (h < 0) h += 360;
    if (h > 360) h -= 360;

    let s = random(80, 100);
    let b = random(90, 100);
    let a = random(3, 8);

    stroke(h, s, b, a);
    noFill();

    beginShape();
    vertex(x, y);
    for (let j = 0; j < maxSteps; j++) {
      let noiseAngle = noise(x * noiseScale, y * noiseScale) * TWO_PI * 2;
      x += cos(noiseAngle) * stepLength;
      y += sin(noiseAngle) * stepLength;

      // Break if it goes off-screen
      if (x < 0 || x > width || y < 0 || y > height) {
        break;
      }

      vertex(x, y);
    }
    endShape();
  }
}

