// We can leave draw() empty because all drawing is done in setup() for this static image.
function draw() {}

class Particle {
  constructor() {
    this.pos = createVector(random(width), random(height));
    this.vel = createVector(0, 0);
    this.acc = createVector(0, 0);
    this.maxSpeed = 2.5;
    this.history = [];
  }

  update() {
    // Noise-based flow field
    const angle = noise(this.pos.x * 0.001, this.pos.y * 0.001) * TWO_PI * 4;
    const force = p5.Vector.fromAngle(angle);
    force.setMag(0.1);
    this.applyForce(force);

    this.vel.add(this.acc);
    this.vel.limit(this.maxSpeed);
    this.pos.add(this.vel);
    this.acc.mult(0);

    // Edge handling
    if (this.pos.x > width) this.pos.x = 0;
    if (this.pos.x < 0) this.pos.x = width;
    if (this.pos.y > height) this.pos.y = 0;
    if (this.pos.y < 0) this.pos.y = height;
  }

  applyForce(force) {
    this.acc.add(force);
  }

  show() {
    // The "heart" or source of love, positioned slightly above the center
    const center = createVector(width / 2, height / 2 - 150);
    const d = dist(this.pos.x, this.pos.y, center.x, center.y);

    // Color and stroke weight are determined by distance to the center
    // Closer to the center: warmer, brighter, thicker
    // Farther from the center: cooler, dimmer, thinner

    // Hue maps from yellow/orange (close) to purple/blue (far)
    const hue = map(d, 0, width * 0.8, 45, 260);
    // Saturation is high, especially near the center
    const saturation = map(d, 0, width, 100, 70);
    // Brightness is high near the center, falls off
    const brightness = map(d * d, 0, (width / 2) * (width / 2), 100, 30);
    // Alpha creates a layered, ethereal effect
    const alpha = map(d, 0, width, 20, 5);
    // Stroke weight is thicker near the source
    const sw = map(d, 0, width, 2.5, 0.5);

    stroke(hue, saturation, brightness, alpha);
    strokeWeight(sw);
    point(this.pos.x, this.pos.y);
  }
}

