    if (baseHue < 0) baseHue += 360;

    for (let j = 0; j < pathLength; j++) {
      let angle = noise(p.x * noiseScale, p.y * noiseScale) * TWO_PI * 4;
      let noiseVector = p5.Vector.fromAngle(angle);

      let attractionVector = createVector(targetCore.x - p.x, targetCore.y - p.y);
      attractionVector.normalize();

      // Combine noise flow and attraction
      let finalVector = p5.Vector.lerp(noiseVector, attractionVector, attractionStrength);
      p.add(finalVector.mult(2));

      let progress = j / pathLength;

      let currentHue = (baseHue + progress * 10) % 360;
      let saturation = 60 + progress * 40;
      let brightness = 100 - progress * 20;
      let alpha = 8 - progress * 7;

      stroke(currentHue, saturation, brightness, alpha);
      strokeWeight(random(1, 2.5));
      point(p.x, p.y);
    }
  }
}

function drawCore(x, y, size, col) {
  noStroke();
  for (let i = size; i > 0; i -= 2) {
    let alpha = map(i, 0, size, 0, 20);
    let brightness = map(i, 0, size, 100, 80);
    fill(hue(col), saturation(col), brightness, alpha);
    ellipse(x, y, i, i);
  }
}

function drawGlow(x, y, size, col) {
  noStroke();
  for (let i = size; i > 0; i -= 10) {
    let a = map(i, 0, size, 0, 100);
    col.setAlpha(a * 0.03); // Low alpha for soft glow
    fill(col);
    ellipse(x, y, i, i);
  }
}

// NOTE: This sketch is designed for p5.js v1.x.
// The `p5.Vector.lerp` and other vector operations are standard.
// The resulting image is a static render due to `noLoop()`.

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();

  // A very dark, deep blue background
  background(230, 80, 15);

  // Add subtle texture to the background, like distant cosmic dust
  drawBackgroundTexture();

  // Draw the two main "entities" or "cores of being"
  // A warm, reddish nebula
  drawNebula(width * 0.3, height * 0.4, width * 0.25, 0, 40, 40000);
  // A cool, bluish nebula
  drawNebula(width * 0.7, height * 0.6, width * 0.25, 190, 230, 40000);

  // Draw the "connection" - the flow of energy between them
  drawConnectionFlow(5000);
}

function drawBackgroundTexture() {
  strokeWeight(1.5);
  for (let i = 0; i < 80000; i++) {
    let x = random(width);
    let y = random(height);
    let a = random(3, 10);
    let h = random(200, 280);
    let s = random(20, 50);
    let b = random(10, 20);
    stroke(h, s, b, a);
    point(x, y);
  }
}

function drawNebula(cx, cy, maxRadius, hueStart, hueEnd, particleCount) {
  strokeWeight(1.5);
  for (let i = 0; i < particleCount; i++) {
    // Distribute particles more towards the center
    let r = pow(random(1), 2.5) * maxRadius;
    let angle = random(TWO_PI);

    let x = cx + cos(angle) * r;
    let y = cy + sin(angle) * r;

    // Use noise to create organic, swirling patterns
    let noiseFactor = noise(x * 0.003, y * 0.003);
    let finalX = cx + (x - cx) * noiseFactor;
    let finalY = cy + (y - cy) * noiseFactor;

    let h = random(hueStart, hueEnd);
    let s = 80 + noise(x * 0.01, y * 0.01) * 20; // Saturation varies
    let b = 60 + noise(x * 0.02, y * 0.02) * 40; // Brightness varies
    let a = 15 * (1 - (r / maxRadius)) * noiseFactor; // More opaque towards center

    stroke(h, s, b, a);
    point(finalX, finalY);
  }
}

function drawConnectionFlow(lineCount) {
  let noiseScale = 0.001;
  let stepLength = 5;
  let numSteps = 150;

  for (let i = 0; i < lineCount; i++) {
    // Start lines randomly, but biased towards the center of the canvas
    let x = width / 2 + randomGaussian(0, width / 5);
    let y = height / 2 + randomGaussian(0, height / 5);

    strokeWeight(random(0.5, 1.2));
    let h = random(40, 60); // Golden-yellow hue
    let s = random(60, 100);
    let b = 100;

    beginShape();
    noFill();
    for (let j = 0; j < numSteps; j++) {
      let angle = noise(x * noiseScale, y * noiseScale, i * 0.01) * 4; // Swirly noise

      let alpha = map(j, 0, numSteps, 0, 25) * (1 - dist(x, y, width/2, height/2) / (width*0.8));
      alpha = constrain(alpha, 0, 25);
      stroke(h, s, b, alpha);

      vertex(x, y);

      x += cos(angle) * stepLength;
      y += sin(angle) * stepLength;

      // Stop drawing if the line goes off-canvas
      if (x < 0 || x > width || y < 0 || y > height) {
        break;
      }
    }
    endShape();
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();
}

function draw() {
  background(240, 50, 5);

  // Add a subtle, dark noise texture to the background for depth
  for (let i = 0; i < 50000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.001, y * 0.001);
    let c = color(240, 50, 5 + n * 10, 20);
    noStroke();
    fill(c);
    circle(x, y, random(1, 4));
  }

  let particles = [];
  let numParticles = 3000;
  let source1 = createVector(width * 0.35, height * 0.4);
  let source2 = createVector(width * 0.65, height * 0.6);

  for (let i = 0; i < numParticles; i++) {
    let p;
    if (random() > 0.5) {
      p = new Particle(source1.x, source1.y);
    } else {
      p = new Particle(source2.x, source2.y);
    }
    particles.push(p);
  }

  // We simulate the particle flow for a number of steps to create the static image
  let simulationSteps = 150;
  for (let t = 0; t < simulationSteps; t++) {
    for (let p of particles) {
      p.update();
      p.display();
    }
  }

  // Draw the glowing sources on top
  drawSource(source1);
  drawSource(source2);
