function drawSource(position) {
  let coreHue = 10;
  let coreSat = 90;
  let coreBri = 100;

  for (let i = 150; i > 0; i -= 2) {
    let alpha = map(i, 150, 0, 0, 25);
    let bri = map(i, 150, 0, 80, 100);
    let sat = map(i, 150, 0, 50, coreSat);
    let hue = coreHue + map(i, 150, 0, -10, 10);
    fill(hue % 360, sat, bri, alpha);
    noStroke();
    circle(position.x, position.y, i);
  }

  fill(coreHue, coreSat, coreBri, 100);
  circle(position.x, position.y, 15);
}


class Particle {
  constructor(x, y) {
    this.pos = createVector(x, y);
    this.vel = p5.Vector.random2D().mult(random(0.5, 1.5));
    this.acc = createVector(0, 0);
    this.lifespan = random(100, 250);
    this.age = 0;
    this.noiseScale = 0.001;
    this.maxSpeed = 2;
  }

  applyForce(force) {
    this.acc.add(force);
  }

  update() {
    // Flow field force based on Perlin noise
    let angle = noise(this.pos.x * this.noiseScale, this.pos.y * this.noiseScale) * TWO_PI * 3;
    let force = p5.Vector.fromAngle(angle);
    force.mult(0.1);
    this.applyForce(force);

    this.vel.add(this.acc);
    this.vel.limit(this.maxSpeed);
    this.pos.add(this.vel);
    this.acc.mult(0);
    this.age++;
  }

  display() {
    if (this.age < this.lifespan) {
      let progress = this.age / this.lifespan;

      // Color fades from red/pink to orange/yellow
      let hue = map(progress, 0, 1, 350, 30);
      let saturation = 90;
      let brightness = 100;

      // Fade out at the end of life
      let alpha = 15;
      if (progress > 0.7) {
        alpha = map(progress, 0.7, 1, 15, 0);
      }

      stroke(hue % 360, saturation, brightness, alpha);
      strokeWeight(map(progress, 0, 1, 2.5, 0.5));
      point(this.pos.x, this.pos.y);
    }
  }
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep atmospheric gradient background
  for (let y = 0; y <= height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(5, 5, 8), color(30, 20, 15), inter);
    stroke(c);
    strokeWeight(1);
    line(0, y, width, y);
  }

  let SUN_X = 800;
  let SUN_Y = 500;
  let SUN_R = 250;

  // The Burning Halo (energy radiating from behind the void)
  noFill();
  for (let i = 0; i < 50; i++) {
    let r = SUN_R + i * 5;
    let alphaVal = map(i, 0, 50, 35, 0);
    stroke(90, 15, 20, alphaVal);
    strokeWeight(4);
    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.1) {
      let nr = r + noise(cos(a) * 2, sin(a) * 2, i * 0.1) * 30;
      vertex(SUN_X + nr * cos(a), SUN_Y + nr * sin(a));
    }
    endShape(CLOSE);
  }

  // The Void (Absolute Death)
  fill(0);
  noStroke();
  beginShape();
  for (let a = 0; a < TWO_PI; a += 0.02) {
    // Organic, torn edge using Perlin noise
    let r = SUN_R - 5 + noise(cos(a) * 3, sin(a) * 3) * 15;
    vertex(SUN_X + r * cos(a), SUN_Y + r * sin(a));
  }
  endShape(CLOSE);

  // The Threads of Life
  for (let i = 0; i < 10000; i++) {
    let x = random(-400, width + 400);
    let y = random(1800, 2800);
    let resistance = random(0.5, 1.5);

    // Warm, earthly colors for life
    let hueInter = random(1);
    let lifeColor = lerpColor(color(180, 20, 10), color(230, 140, 20), hueInter);

    let cLifeA = color(red(lifeColor), green(lifeColor), blue(lifeColor), 25);
    let cTransA = color(150, 180, 220, 70); // Cooling down, spiritual transition
    let cWhiteA = color(255, 255, 255, 180); // Final flash of light
    let cVoid = color(0, 0, 0, 0); // Dissolution into nothingness

    let points = [];

    // Simulate the journey of each thread
    for (let step = 0; step < 2500; step++) {
      points.push({ x: x, y: y });

      let dx = SUN_X - x;
      let dy = SUN_Y - y;
      let d = sqrt(dx * dx + dy * dy);

      // Consumed by the void
      if (d < SUN_R - 10) {
        points.push({ x: x, y: y });
        break;
      }

      // Natural wandering of life (Noise flow)
      let nAngle = noise(x * 0.002, y * 0.002, step * 0.0005) * TWO_PI * 2;
      let nx = cos(nAngle) * 1.5;
      let ny = sin(nAngle) * 1.5 - 1.0;

      // Inescapable pull of the void (Inverse-square gravity)
      let pull = (500000 / (d * d)) / resistance;
      pull = constrain(pull, 0, 8);

      let gx = (dx / d) * pull;
      let gy = (dy / d) * pull;

      x += nx + gx;
      y += ny + gy;
    }

    // Render the thread with changing states of existence
    noFill();
    for (let j = 0; j < points.length - 1; j++) {
      let p1 = points[j];
      let p2 = points[j + 1];
      let d = dist(p1.x, p1.y, SUN_X, SUN_Y);
      let distRatio = constrain(map(d, SUN_R, 1500, 0, 1), 0, 1);

      let col;
      let w;

      if (distRatio > 0.3) {
        // Physical realm
        let lr = map(distRatio, 0.3, 1.0, 0, 1);
        col = lerpColor(cTransA, cLifeA, lr);
        w = map(distRatio, 0.3, 1.0, 0.5, 1.5);
      } else if (distRatio > 0.05) {
        // Event Horizon (Fading to light)
        let lr = map(distRatio, 0.05, 0.3, 0, 1);
        col = lerpColor(cWhiteA, cTransA, lr);
        w = map(distRatio, 0.05, 0.3, 0.1, 0.5);
      } else {
        // Crossing over (Fading to dark)
        let lr = map(distRatio, 0.0, 0.05, 0, 1);
        col = lerpColor(cVoid, cWhiteA, lr);
        w = map(distRatio, 0.0, 0.05, 0.0, 0.1);
      }

      stroke(col);
      strokeWeight(w);
      line(p1.x, p1.y, p2.x, p2.y);
    }
  }

  // Floating Embers (Memories left behind)
  for (let i = 0; i < 400; i++) {
    let ex = random(width);
    let ey = random(height);
    let d = dist(ex, ey, SUN_X, SUN_Y);
    if (d > SUN_R && ey > SUN_Y - 100) {
      let r = random(1, 3.5);
      let alphaVal = map(ey, 500, 2000, 0, 180);
      alphaVal = constrain(alphaVal, 0, 180);

      noStroke();
      fill(255, random(150, 200), 50, alphaVal);
      circle(ex, ey, r);
      // Soft glow
      fill(255, random(100, 150), 20, alphaVal / 3);
      circle(ex, ey, r * 4);
    }
  }

  // Canvas Grain / Ash Overlay (Painterly texture)
  noStroke();
  for (let i = 0; i < 300000; i++) {
    fill(random(200, 255), random(3, 10));
    rect(random(width), random(height), 1, 1);
  }

  // Vignette (Focusing the composition)
  noFill();
  for (let i = 0; i < 200; i++) {
    stroke(0, 0, 0, map(i, 0, 200, 200, 0));
    strokeWeight(2);
    rect(i, i, width - i * 2, height - i * 2);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  let cx = 800;
  let cy = 750;
  let voidRadius = 400;

  // Background Vertical Gradient
  for (let y = 0; y < height; y++) {
    let inter = y / height;
    let r = lerp(4, 15, inter);
    let g = lerp(4, 5, inter);
    let b = lerp(6, 5, inter);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Background Noise Texture
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let n = random(-8, 8);
    pixels[i] = constrain(pixels[i] + n, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + n, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + n, 0, 255);
  }
  updatePixels();

  // Geometric Cosmic Rays (The architecture of the universe)
  stroke(255, 8);
  strokeWeight(2);
  for (let a = 0; a < TWO_PI; a += PI / 45) {
    let r1 = voidRadius;
    let r2 = 2800;
    line(cx + cos(a) * r1, cy + sin(a) * r1, cx + cos(a) * r2, cy + sin(a) * r2);
  }

  // The Void's Corona (Outer Glow)
  noFill();
  for (let r = voidRadius * 2; r < voidRadius * 2 + 400; r += 4) {
    let alpha = map(r, voidRadius * 2, voidRadius * 2 + 400, 50, 0);
    stroke(200, 220, 255, alpha);
    strokeWeight(4);
    circle(cx, cy, r);
  }
  // Intense Inner Rim of the Corona
  for (let r = voidRadius * 2 - 20; r <= voidRadius * 2; r += 2) {
    let alpha = map(r, voidRadius * 2 - 20, voidRadius * 2, 0, 255);
    stroke(255, 255, 255, alpha);
    strokeWeight(2);
    circle(cx, cy, r);
  }

  // Color Palettes
  let lifeHex = [
    '#590909', '#8c1111', '#ba2a20', // Blood / Dark reds
    '#d95c14', '#f28f1d',           // Oranges
    '#f2c12e',                      // Gold
    '#0a2e3f', '#1b595a', '#297a72',// Deep teals
    '#2c1538', '#4b1d52'            // Dark purples
  ];
  let voidHex = ['#ffffff', '#e8f0ff', '#fff5e8', '#e0e0e0'];

  let lifeColors = lifeHex.map(h => color(h));
  let voidColors = voidHex.map(h => color(h));

  let numThreads = 15000;
  let maxSteps = 350;
  let noiseScale = 0.0015;
  let dust = [];

  // Generate and Draw Threads of Life
  for (let i = 0; i < numThreads; i++) {
    let x, y;
    let edge = random(1);

    // Distribute starting points to envelop the void from bottom and sides
    if (edge < 0.7) {
      x = random(-200, 1800);
      y = random(1800, 2200);
    } else if (edge < 0.85) {
      x = random(-400, -50);
      y = random(200, 2000);
    } else {
      x = random(1650, 2000);
      y = random(200, 2000);
    }

    let col = random(lifeColors);
    let vCol = random(voidColors);

    let r1 = red(col), g1 = green(col), b1 = blue(col);
    let r2 = red(vCol), g2 = green(vCol), b2 = blue(vCol);

    let weightBase = random(0.5, 3.0);
    if (random() < 0.05) weightBase = random(4, 7); // Occasional thick souls

    let alphaBase = random(50, 150);
    if (weightBase > 4) alphaBase = random(150, 255);

    let prevX = x;
    let prevY = y;

    for (let step = 0; step < maxSteps; step++) {
      let dx = cx - x;
      let dy = cy - y;
      let d = Math.sqrt(dx * dx + dy * dy);

      if (d < voidRadius - 2) break;

      let nx = dx / d;
      let ny = dy / d;

      // Clockwise tangent
      let tx = ny;
      let ty = -nx;

      let nAngle = noise(x * noiseScale, y * noiseScale, i * 0.001) * TWO_PI * 4;
      let nvx = Math.cos(nAngle);
      let nvy = Math.sin(nAngle);

      let spiralFactor = map(d, voidRadius, 2000, 2.5, 0.2);
      let pullFactor = map(d, voidRadius, 2000, 3.5, 1.2);
      let noiseFactor = map(d, voidRadius, 2000, 0.05, 1.5);

      let moveX = nx * pullFactor + tx * spiralFactor + nvx * noiseFactor;
      let moveY = ny * pullFactor + ty * spiralFactor + nvy * noiseFactor;

      let moveMag = Math.sqrt(moveX * moveX + moveY * moveY);
      let stepSize = map(d, voidRadius, 2000, 4, 8);

      moveX = (moveX / moveMag) * stepSize;
      moveY = (moveY / moveMag) * stepSize;

      x += moveX;
      y += moveY;

      // Color Mixing based on distance to the void
      let mix = map(d, voidRadius, 1600, 1, 0);
      if (mix < 0) mix = 0;
      if (mix > 1) mix = 1;
      mix = Math.pow(mix, 2.5); // Sharp transition to white near the void

      let curR = r1 + (r2 - r1) * mix;
      let curG = g1 + (g2 - g1) * mix;
      let curB = b1 + (b2 - b1) * mix;

      let currentAlpha = map(d, voidRadius, 2000, 255, alphaBase);
      if (currentAlpha < 0) currentAlpha = 0;
      if (currentAlpha > 255) currentAlpha = 255;

      // Fade out completely right at the event horizon
      if (d < voidRadius + 20) {
        let fade = map(d, voidRadius - 2, voidRadius + 20, 0, 1);
        if (fade < 0) fade = 0;
        if (fade > 1) fade = 1;
        currentAlpha *= fade;
      }

      // Fade out if it runs out of steps (doesn't reach the void)
      if (step > maxSteps - 50) {
        let stepFade = map(step, maxSteps - 50, maxSteps - 1, 1, 0);
        if (stepFade < 0) stepFade = 0;
        if (stepFade > 1) stepFade = 1;
        currentAlpha *= stepFade;
      }

      stroke(curR, curG, curB, currentAlpha);
      strokeWeight(map(d, voidRadius, 2000, weightBase * 0.2, weightBase));
      line(prevX, prevY, x, y);

      // Collect shatter/dust particles near the transition
      if (mix > 0.7 && random() < 0.03) {
        dust.push({
          x: x + random(-12, 12),
          y: y + random(-12, 12),
          r: curR, g: curG, b: curB,
          a: random(100, 255) * (currentAlpha / 255),
          rad: random(1.0, 3.5)
        });
      }

      prevX = x;
      prevY = y;
    }
  }

  // Draw the transition dust
  noStroke();
  for (let pt of dust) {
    fill(pt.r, pt.g, pt.b, pt.a);
    circle(pt.x, pt.y, pt.rad);
  }

  // The Absolute Void
  fill(0);
  noStroke();
  circle(cx, cy, voidRadius * 2);

  // Crisp, defining edge of the threshold
  noFill();
  stroke(255, 255, 255, 120);
  strokeWeight(1.5);
  circle(cx, cy, voidRadius * 2);
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // 1. Deep Space / Void Background
  background(8, 10, 15);
  strokeWeight(1);
  for (let i = 0; i < 150000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.002, y * 0.002);
    let d = dist(x, y, width / 2, height / 2);
    let darkAmt = constrain(map(d, 400, 1400, 0, 1), 0, 1);

    let r = lerp(20, 5, darkAmt) + n * 10;
    let g = lerp(35, 7, darkAmt) + n * 15;
    let b = lerp(60, 12, darkAmt) + n * 25;

    stroke(r, g, b, random(30, 100));
    point(x, y);
  }

  // 2. The Ground / Corporeal Threshold
  fill(5, 3, 4, 230);
  noStroke();
  beginShape();
  vertex(0, 2000);
  for (let x = 0; x <= 1600; x += 20) {
    let y = 1850 + noise(x * 0.003) * 150;
    let dip = map(abs(x - 800), 0, 800, 100, -50);
    vertex(x, y + dip);
  }
  vertex(1600, 2000);
  endShape(CLOSE);

  // 3. The Central Ascending Form (The Transitioning Soul)
  let numFibers = 12000;
  for (let i = 0; i < numFibers; i++) {
    // Distribute fibers around the center with higher density in the middle
    let startX = 800 + (random(-1, 1) + random(-1, 1) + random(-1, 1) + random(-1, 1)) * 90;
    let distFromCenter = abs(startX - 800);

    // Color gradient based on distance from core
    let baseCol;
    if (distFromCenter < 30) {
      baseCol = color(255, 230, 200); 
    } else if (distFromCenter < 70) {
      baseCol = color(210, 130, 30);  
    } else if (distFromCenter < 140) {
      baseCol = color(160, 40, 20);   
    } else {
      baseCol = color(60, 15, 15);    
    }

    // Ethereal colors for the dissolved upper state
    let etherCol;
    let rVal = random();
    if (rVal < 0.5) etherCol = color(120, 230, 255); 
    else if (rVal < 0.8) etherCol = color(255, 240, 160); 
    else etherCol = color(200, 200, 250); 

    let x = startX;
    let y = random(1850, 1950);
    let thickness = random(1.5, 4.5);
    let life = 255;
    let noiseOffset = random(1000);
    let breakPoint = random(700, 1200); // Varied elevation where form breaks down

    while (y > 0 && life > 0) {
      let transition = constrain(map(y, 1600, breakPoint - 200, 0, 1), 0, 1);
      let currentCol = lerpColor(baseCol, etherCol, transition);

      let alpha = map(transition, 0, 1, 60, 20);
      if (life < 100) alpha *= (life / 100.0);

      noStroke();
      fill(red(currentCol), green(currentCol), blue(currentCol), alpha);
      circle(x, y, thickness);

      let n = noise(x * 0.002, y * 0.002, noiseOffset);
      let structuralIntegrity = constrain(map(y, breakPoint + 300, breakPoint - 100, 1, 0), 0, 1);

      let dx = map(n, 0, 1, -4, 4);
      let dy = -random(1, 3);

      if (structuralIntegrity > 0.4) {
        // Tightly bound corporeal state
        dx += (800 - x) * 0.001; 
      } else {
        // Dissolution state driven by cosmic wind
        dx *= map(structuralIntegrity, 0.4, 0, 1.5, 6);
        life -= random(0.2, 1.5); 
      }

      x += dx;
      y += dy;
      thickness *= 0.998;
    }
  }

  // 4. Glowing Embers / Released Energy
  blendMode(ADD);
  for (let i = 0; i < 2000; i++) {
    let x = 800 + (random(-1, 1) + random(-1, 1)) * 250;
    let y = random(600, 1500);
    let size = random(1.5, 4);
    let c = random() > 0.6 ? color(255, 210, 120) : color(140, 240, 255);

    let life = random(100, 255);
    let px = x; 
    let py = y;

    while (life > 0) {
      stroke(red(c), green(c), blue(c), life);
      strokeWeight(size * (life / 255));

      let n = noise(x * 0.004, y * 0.004, i);
      x += map(n, 0, 1, -6, 6);
      y -= random(2, 6);

      line(px, py, x, y);
      px = x; 
      py = y;
      life -= random(4, 12);
    }
  }

  // 5. Painterly Canvas Texture Overlay
  blendMode(BLEND);
  strokeWeight(1);
  for (let i = 0; i < 400000; i++) {
    let x = random(width);
    let y = random(height);
    stroke(random() > 0.5 ? 255 : 0, random(4, 12));
    point(x, y);
  }
}

function setup() {
  createCanvas(1600, 2000);
  noLoop();
  randomSeed(1);
  noiseSeed(1);

  let voidX = 800;
  let voidY = 600;
  let voidR = 180;

  // Draw dark atmospheric background
  background(2, 3, 6);
  noStroke();
  for (let y = 0; y < height; y += 5) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(2, 3, 6), color(20, 10, 10), inter);
    fill(c);
    rect(0, y, width, 5);
  }

  // Vignette effect
  noStroke();
  for (let r = 2500; r > 600; r -= 50) {
    fill(0, 0, 5, 6);
    circle(width / 2, height / 2, r);
  }

  // Background noise texture
  fill(0, 0, 0, 30);
  for (let i = 0; i < 150000; i++) {
    let x = random(width);
    let y = random(height);
    circle(x, y, random(1, 3));
  }

  // Ethereal halos around the void
  for (let r = 180; r < 700; r += 10) {
    let alpha = map(r, 180, 700, 15, 0);
    fill(255, 180, 100, alpha); // inner gold glow
    circle(voidX, voidY, r * 2);
  }
  for (let r = 400; r < 1200; r += 20) {
    let alpha = map(r, 400, 1200, 10, 0);
    fill(50, 120, 255, alpha); // outer blue glow
    circle(voidX, voidY, r * 2);
  }

  // Generate color palette for the lifelines
  let palette = [];
  let cEarth = color(20, 5, 5, 60);
  let cBlood = color(120, 15, 15, 40);
  let cFire = color(255, 80, 10, 20);
  let cGold = color(255, 200, 50, 15);
  let cSpirit = color(80, 180, 255, 15);
  let cVoid = color(200, 220, 255, 0);

  for (let i = 0; i <= 1000; i++) {
    let t = i / 1000;
    let col;
    if (t < 0.1) col = lerpColor(cVoid, cSpirit, t / 0.1);
    else if (t < 0.25) col = lerpColor(cSpirit, cGold, (t - 0.1) / 0.15);
    else if (t < 0.55) col = lerpColor(cGold, cFire, (t - 0.25) / 0.3);
    else if (t < 0.8) col = lerpColor(cFire, cBlood, (t - 0.55) / 0.25);
    else col = lerpColor(cBlood, cEarth, (t - 0.8) / 0.2);
    palette.push(col);
  }

  // Simulate dissolving entity
  let numParticles = 25000;
  let steps = 180;

  for (let i = 0; i < numParticles; i++) {
    // Generate organic mound at the bottom
    let x = randomGaussian(800, 200);
    let y = randomGaussian(2000, 180);
    if (y > 2000) y = 2000 - (y - 2000); // fold back to create a floor

    let px = x;
    let py = y;
    let vx = 0;
    let vy = -2; // initial updraft

    for (let s = 0; s < steps; s++) {
      let oldX = px;
      let oldY = py;

      let dx = px - voidX;
      let dy = py - voidY;
      let d = sqrt(dx * dx + dy * dy);

      // Cease existence if swallowed by the event horizon
      if (d < voidR) break;

      // 3D noise for winding organic paths
      let n = noise(px * 0.0015, py * 0.0015, i * 0.0005);
      let angle = n * TWO_PI * 2.5;

      vx += cos(angle) * 0.5;
      vy += sin(angle) * 0.5;

      // Gravitational pull toward the singularity
      let pull = map(d, voidR, 1600, 1.8, 0);
      pull = max(pull, 0);
      vx -= (dx / d) * pull;
      vy -= (dy / d) * pull;

      // Tangential force to create an accretion disk swirl
      let swirl = map(d, voidR, 1600, 3.5, 0);
      swirl = max(swirl, 0);
      vx += (-dy / d) * swirl;
      vy += (dx / d) * swirl;

      // Physics damping and persistent updraft
      vx *= 0.85;
      vy *= 0.85;
      vy -= 0.15; 

      px += vx;
      py += vy;

      // Map color and thickness based on proximity to the void
      let pIndex = floor(map(d, voidR, 1600, 0, 1000));
      pIndex = constrain(pIndex, 0, 1000);

      stroke(palette[pIndex]);
      strokeWeight(map(d, voidR, 1600, 0.1, 3.0));

      line(oldX, oldY, px, py);
    }
  }

  // Draw the pure black Void (Event Horizon)
  fill(0);
  noStroke();
  circle(voidX, voidY, voidR * 2);

  // Sharp, fragile glowing rims of the singularity
  noFill();
  strokeWeight(1);
  stroke(255, 255, 255, 120);
  circle(voidX, voidY, voidR * 2 + 1);

  strokeWeight(4);
  stroke(100, 200, 255, 50);
  circle(voidX, voidY, voidR * 2 + 4);

  // Depth of field: Out-of-focus rising embers and ashes
  for (let i = 0; i < 200; i++) {
    let ex = random(width);
    let ey = random(height);
    let ed = dist(ex, ey, voidX, voidY);
    if (ed > voidR + 20) {
      let r = random(2, 8);
      fill(255, random(100, 200), 50, random(10, 60));
      noStroke();
      circle(ex, ey, r);
    }
  }
  for (let i = 0; i < 40; i++) {
    let ex = random(width);
    let ey = random(height);
    let ed = dist(ex, ey, voidX, voidY);
    if (ed > voidR + 50) {
      let r = random(15, 35);
      fill(255, 180, 50, random(3, 12));
      noStroke();
      circle(ex, ey, r);
    }
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // Background: The Deep Void
  background(4, 5, 7);

  // Draw a subtle halo at the origin of dissolution to represent lingering warmth
  noStroke();
  for (let r = 900; r > 0; r -= 15) {
    let alpha = map(r, 0, 900, 12, 0);
    fill(180, 40, 20, alpha);
    ellipse(800, 550, r, r * 0.85);
  }

  // The dying core (the last remnant of the structured self)
  fill(255, 240, 210, 255);
  ellipse(800, 550, 30, 30);
  fill(255, 140, 30, 150);
  ellipse(800, 550, 70, 70);
  fill(190, 20, 30, 80);
  ellipse(800, 550, 120, 120);

  // Core colors representing life, fading, and the void
  let palette = [
    color(255, 250, 230), // Brilliant soul / spark
    color(255, 150, 30),  // Burning life
    color(190, 20, 30),   // Physical tether / blood
    color(70, 15, 35),    // Fading warmth
    color(20, 25, 45),    // Cold dissolution
    color(4, 5, 7)        // The Void
  ];

  let getPaletteColor = function(t) {
    t = constrain(t, 0, 1);
    let idx = t * (palette.length - 1);
    let i = floor(idx);
    let j = min(i + 1, palette.length - 1);
    return lerpColor(palette[i], palette[j], idx - i);
  };

  // Particle system for the unraveling threads of life
  let numStrands = 40000;
  let maxSteps = 500;

  for (let i = 0; i < numStrands; i++) {
    // Distribute strands heavily in the center, tapering outward
    let rDist = abs(randomGaussian(0, 120));
    let theta = random(TWO_PI);
    let startX = 800 + rDist * cos(theta);
    let startY = 550 + rDist * sin(theta) * 0.7;

    let x = startX;
    let y = startY;

    // Base identity of the strand based on origin distance
    let lifeForce = map(rDist, 0, 400, 0, 0.5);

    let prevX = x;
    let prevY = y;
    let steps = random(150, maxSteps);

    for (let s = 0; s < steps; s++) {
      // Y-axis determines the transition from life (top) to death (bottom)
      let depthY = map(y, 550, 1900, 0, 1);
      let depthConstrained = constrain(depthY, 0, 1);

      // Color shifts along the palette as it falls into the void
      let colorStage = constrain(lifeForce + depthConstrained * 0.85, 0, 1);
      let c = getPaletteColor(colorStage);

      // Alpha fades with depth and the individual strand's lifespan
      let lifeFade = map(s, 0, steps, 1, 0);
      let noiseAlpha = map(noise(i * 0.1), 0, 1, 0.3, 1);
      let alphaVal = 255 * lifeFade * map(depthConstrained, 0, 1, 1, 0.05) * noiseAlpha;

      stroke(red(c), green(c), blue(c), alphaVal);

      // Thickness decays into nothingness
      let w = map(s, 0, steps, map(rDist, 0, 300, 3, 0.5), 0.1);
      strokeWeight(constrain(w, 0.1, 4));

      line(prevX, prevY, x, y);

      prevX = x;
      prevY = y;

      // Flow field calculation for organic unraveling
      let n = noise(x * 0.0015, y * 0.0015, i * 0.00003);
      let angle = map(n, 0, 1, -PI * 1.5, PI * 1.5);

      // Entropy and gravity increase as the entity falls deeper
      let turbulence = map(depthConstrained, 0, 1, 0.3, 4.5);

      // Gravity pulls strongly down, but at the very top (y < 550), it drifts upward slightly (the flame of life)
      let gravity = map(depthY, -0.1, 1, -0.5, 7);

      x += cos(angle) * turbulence;
      y += sin(angle) * turbulence + gravity;

      // Terminate early if completely faded or out of bounds
      if (alphaVal < 0.5 || y > 2000 || x < 0 || x > 1600 || y < 0) {
        break;
      }
    }
  }

  // Dispersing particles (scattered memories turning to dust)
  for (let i = 0; i < 10000; i++) {
    let px = random(0, 1600);
    let py = random(0, 2000);
    let d = dist(px, py, 800, 550);

    // More dust resides in the transition zone beneath the core
    let prob = constrain(map(d, 0, 1200, 1, 0), 0, 1) * constrain(map(py, 300, 1800, 1, 0), 0, 1);
    if (random() < prob * 0.35) {
      let s = random(0.5, 3.5);
      let c = getPaletteColor(random(0, 0.8));
      noStroke();
      fill(red(c), green(c), blue(c), random(30, 180));
      ellipse(px, py, s, s);
    }
  }

  // Post-processing: Vignette to focus the piece and emulate chiaroscuro
  noFill();
  for (let i = 0; i < 300; i++) {
    strokeWeight(6);
    stroke(0, 0, 0, map(i, 0, 300, 255, 0));
    rect(i * 2, i * 2, 1600 - i * 4, 2000 - i * 4);
  }

  // Post-processing: Film grain to emulate a physical painting texture
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let grain = random(-14, 14);
    pixels[i] = constrain(pixels[i] + grain, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + grain, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + grain, 0, 255);
  }
  updatePixels();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();

  // Fond profond
  background(8, 9, 11);

  let sinkX = 1000;
  let sinkY = 700;
  let voidRadius = 160;

  // Halo extérieur du vide
  noStroke();
  for (let diam = 1200; diam > voidRadius * 2; diam -= 15) {
    let glow = map(diam, 1200, voidRadius * 2, 0, 8);
    fill(15, 18, 25, glow);
    ellipse(sinkX, sinkY, diam, diam);
  }

  // Le vide absolu au centre
  for (let diam = voidRadius * 2; diam > 0; diam -= 4) {
    let v = map(diam, voidRadius * 2, 0, 8, 0);
    fill(v, v, v + 2);
    ellipse(sinkX, sinkY, diam, diam);
  }

  // Palettes de couleurs représentant la vitalité (Sang, Or, Océan, Esprit)
  let palettes = [
    [190, 30, 40],   
    [230, 100, 20],  
    [255, 180, 40],  
    [30, 150, 160],  
    [40, 60, 150],   
    [110, 40, 130]   
  ];

  let numPaths = 25000;

  for (let i = 0; i < numPaths; i++) {
    let x, y;
    // La majorité des flux proviennent du coin inférieur gauche
    if (random() < 0.75) {
      x = random(-600, width);
      y = random(1200, height + 800);
    } else {
      x = random(-600, width + 600);
      y = random(-200, height + 1000);
    }

    let p = random(palettes);
    let baseR = p[0] + random(-20, 20);
    let baseG = p[1] + random(-20, 20);
    let baseB = p[2] + random(-20, 20);

    let isHero = random() < 0.02; // Quelques fils plus intenses et résistants
    let weightMod = isHero ? random(2.0, 3.5) : random(0.5, 1.5);
    let alphaMod = isHero ? 1.8 : 1.0;

    let life = random(300, 800);
    let zOff = random(1000);

    let prevX = x;
    let prevY = y;

    for (let step = 0; step < life; step++) {
      let d = dist(x, y, sinkX, sinkY);
      let progress = step / life;

      if (d <= voidRadius) break; // Englouti par le vide
      if (x < -1000 || x > width + 1000 || y < -1000 || y > height + 1000) break;

      let distFactor = constrain(map(d, voidRadius, 1200, 0, 1), 0, 1);
      let lifeFade = sin(progress * PI);
      let alpha = 50 * distFactor * lifeFade * alphaMod;

      // Les couleurs se désaturent vers l'os/la cendre près du centre
      let r = lerp(230, baseR, distFactor);
      let g = lerp(230, baseG, distFactor);
      let b = lerp(240, baseB, distFactor);

      // Calcul du champ de vecteurs (Bruit + Attraction)
      let n = (noise(x * 0.0015, y * 0.0015, zOff) - 0.5) * TWO_PI;
      let angleToCenter = atan2(sinkY - y, sinkX - x);
      let deflection = map(d, voidRadius, 1500, PI / 2.2, 0); // Effet de spirale
      let baseAngle = angleToCenter + deflection;

      let noiseWeight = constrain(map(d, voidRadius + 50, 1500, 0.1, 1.5), 0, 1);
      let angle = baseAngle + n * noiseWeight;

      x += cos(angle) * 2.0;
      y += sin(angle) * 2.0;

      let dustStart = voidRadius + 160;

      if (d < dustStart && d > voidRadius) {
        // Zone de désintégration : la ligne se brise en poussière lumineuse
        let dustIntensity = map(d, dustStart, voidRadius, 0, 1);

        // Ligne fantomatique résiduelle
        stroke(r, g, b, alpha * (1 - dustIntensity));
        strokeWeight(weightMod);
        line(prevX, prevY, x, y);

        // Poussière d'âme
        stroke(255, 245, 230, 200 * dustIntensity * lifeFade * alphaMod);
        strokeWeight(random(1, 3) * weightMod);

        if (random() < dustIntensity * 0.6) {
          let j = dustIntensity * 18;
          point(x + random(-j, j), y + random(-j, j));
        }
      } else {
        // Fil de vie continu
        stroke(r, g, b, alpha);
        strokeWeight(weightMod);
        line(prevX, prevY, x, y);
      }

      prevX = x;
      prevY = y;
    }
  }

  // Post-traitement : Grain texturé et vignettage dramatique
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let px = (i / 4) % width;
    let py = floor((i / 4) / width);

    let dToCenter = dist(px, py, sinkX, sinkY);
    let vignette = map(dToCenter, 400, 1800, 0, -60);
    let n = (random() - 0.5) * 16; // Bruit type pellicule

    pixels[i] = constrain(pixels[i] + n + vignette, 0, 255);
    pixels[i+1] = constrain(pixels[i+1] + n + vignette, 0, 255);
    pixels[i+2] = constrain(pixels[i+2] + n + vignette, 0, 255);
  }
  updatePixels();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // Fond très sombre (le vide)
  background(6, 7, 10); 

  // Texture de fond (grain de la toile)
  for (let i = 0; i < 400000; i++) {
    stroke(255, random(1, 4));
    point(random(width), random(height));
  }

  // Lignes sombres et lourdes (le vide qui approche et écrase)
  for (let i = 0; i < 8000; i++) {
    let cx = random(width);
    let cy = random(height);
    let len = random(50, 200);
    for (let j = 0; j < len; j++) {
      let p = j / len;
      stroke(2, 2, 5, lerp(30, 0, p));
      strokeWeight(lerp(8, 1, p));
      let n = noise(cx * 0.001, cy * 0.001 + 100);
      let angle = n * TWO_PI * 4;
      let nx = cx + cos(angle) * 3;
      let ny = cy + sin(angle) * 3 + 1; // Poussée légère vers le bas
      line(cx, cy, nx, ny);
      cx = nx;
      cy = ny;
    }
  }

  // Le cœur de la vie qui s'effiloche, se disperse et monte vers le néant
  for (let i = 0; i < 25000; i++) {
    // Centre d'énergie vitale en bas
    let x = width * 0.5 + randomGaussian(0, 350);
    let y = height * 0.8 + randomGaussian(0, 250);

    let distFromCenter = dist(x, y, width * 0.5, height * 0.8);
    let intensity = map(distFromCenter, 0, 800, 1, 0, true);

    let length = random(100, 500);
    let cx = x;
    let cy = y;

    for (let j = 0; j < length; j++) {
      let progress = j / length;

      // La couleur passe de rouge/or vibrant à un noir/bleu froid
      let r = lerp(230 * intensity + 20, 4, progress);
      let g = lerp(50 * intensity + 10, 6, progress);
      let b = lerp(15 * intensity + 20, 10, progress);

      // L'opacité et l'épaisseur s'estompent (dissolution)
      let alpha = lerp(90 * intensity + 10, 0, progress);
      let sw = lerp(4.5 * intensity + 0.5, 0.1, progress);

      stroke(r, g, b, alpha);
      strokeWeight(sw);

      // Champ de bruit pour un mouvement organique et fluide
      let n = noise(cx * 0.0015, cy * 0.0015);
      let angle = n * TWO_PI * 5;

      let nx = cx + cos(angle) * 1.5;
      let ny = cy + sin(angle) * 1.5 - 3; // Forte aspiration vers le haut

      line(cx, cy, nx, ny);
      cx = nx;
      cy = ny;

      // Arrêt si la particule sort de la toile
      if (cx < 0 || cx > width || cy < 0 || cy > height) break;
    }
  }

  // Étincelles et cendres (les derniers fragments de conscience/souvenir)
  for (let i = 0; i < 4000; i++) {
     let x = width * 0.5 + randomGaussian(0, 450);
     let y = height * 0.8 + randomGaussian(0, 400);
     let distC = dist(x, y, width * 0.5, height * 0.8);

     // Plus dense près du centre
     if (random() > distC / 1000) {
       noStroke();
       let isGold = random() > 0.5;
       if (isGold) {
         fill(255, 180, 80, random(50, 200)); // Lueur dorée
       } else {
         fill(200, 50, 30, random(30, 150)); // Braise rouge
       }
       circle(x, y, random(0.5, 3.5));
     }
  }
}

let palettes;

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // Définition des couleurs de la "vie"
  palettes = [
    color(230, 57, 70),   // Rouge écarlate (passion, sang)
    color(244, 162, 97),  // Ambre/Or (chaleur, lumière)
    color(42, 157, 143),  // Sarcelle (souffle, nature)
    color(233, 196, 106), // Or brisé
    color(180, 190, 200)  // Cendre
  ];

  // Le centre de gravité de la mort (le Vide)
  let cx = width * 0.35;
  let cy = height * 0.35;

  // 1. Fond texturé et sombre (le néant environnant)
  loadPixels();
  for (let x = 0; x < width; x++) {
    for (let y = 0; y < height; y++) {
      let n = noise(x * 0.005, y * 0.005);
      let idx = (x + y * width) * 4;
      pixels[idx] = 8 + n * 20;     // R
      pixels[idx + 1] = 10 + n * 18; // G
      pixels[idx + 2] = 15 + n * 25; // B
      pixels[idx + 3] = 255;         // Alpha
    }
  }
  updatePixels();

  // 2. Le flux de la vie aspiré par le Vide
  let numStrands = 15000;
  for (let i = 0; i < numStrands; i++) {
    let px, py;

    // Distribution des points de départ (surtout en bas et à droite)
    let r = random();
    if (r < 0.5) {
      px = random(width * 0.4, width * 1.2);
      py = random(height * 0.4, height * 1.2);
    } else if (r < 0.8) {
      px = random(width);
      py = height + random(200);
    } else {
      px = width + random(200);
      py = random(height);
    }

    let baseColor = random(palettes);
    let maxSteps = random(40, 200);
    let strokeW = random(2, 12);

    // Quelques éclats d'âmes purs
    if (random() < 0.05) baseColor = color(255, 250, 240);

    for (let step = 0; step < maxSteps; step++) {
      let d = dist(px, py, cx, cy);

      // La ligne est complètement absorbée si elle est trop proche du centre
      if (d < 70) break;

      let angleToVoid = atan2(cy - py, cx - px);
      let nAngle = noise(px * 0.0015, py * 0.0015) * TWO_PI * 4;

      // Plus on s'approche de la mort, plus l'attraction est forte
      let pull = map(d, 70, 1800, 1, 0);
      pull = pow(pull, 1.8); // Courbe exponentielle pour l'effet gravitationnel

      // Effet de spirale
      let spiral = PI / random(2.5, 4.5);
      let targetAngle = angleToVoid + spiral;
      let angle = lerp(nAngle, targetAngle, pull);

      let nx = px + cos(angle) * random(6, 15);
      let ny = py + sin(angle) * random(6, 15);

      // Désaturation et assombrissement progressifs (perte de la vie)
      let life = map(d, 70, 1400, 0, 1);
      life = constrain(life, 0, 1);

      let voidColor = color(10, 10, 12);
      let strokeColor = lerpColor(voidColor, baseColor, life);

      // L'opacité varie pour imiter la touche d'un pinceau effiloché
      let alphaVal = map(life, 0, 1, 5, 200);
      let stepFade = sin(map(step, 0, maxSteps, 0, PI));
      strokeColor.setAlpha(alphaVal * stepFade);

      push();
      translate(px, py);
      rotate(angle);
      fill(strokeColor);
      noStroke();
      // Touche de peinture (empâtement)
      ellipse(0, 0, strokeW * map(life, 0, 1, 1, 3), strokeW * 0.4);
      pop();

      px = nx;
      py = ny;
    }
  }

  // 3. L'aura / l'horizon des événements (la transition)
  for (let i = 0; i < 300; i++) {
    let r = random(120, 500);
    let a = random(TWO_PI);
    let x = cx + cos(a) * r;
    let y = cy + sin(a) * r;
    let d = dist(x, y, cx, cy);
    let alpha = map(d, 120, 500, 40, 0);
    fill(240, 220, 200, alpha * 0.15);
    noStroke();
    circle(x, y, random(2, 15));
  }

  // 4. Le cœur du Vide (superposition de formes sombres organiques)
  for (let i = 0; i < 200; i++) {
    fill(4, 4, 5, 15);
    beginShape();
    let radBase = random(80, 320);
    let noiseOffset = random(100);
    for (let a = 0; a < TWO_PI; a += 0.05) {
      let r = radBase + noise(cos(a) * 1.5 + noiseOffset, sin(a) * 1.5 + noiseOffset) * 100;
      vertex(cx + cos(a) * r, cy + sin(a) * r);
    }
    endShape(CLOSE);
  }

  // 5. L'abîme absolu (silence central)
  noStroke();
  for (let r = 220; r > 0; r -= 2) {
    fill(0, 0, 0, map(r, 0, 220, 255, 0));
    circle(cx, cy, r);
  }

  // 6. Dernières étincelles (âmes sur le point de disparaître)
  for (let i = 0; i < 1500; i++) {
    let a = random(TWO_PI);
    let r = random(80, 250);
    let x = cx + cos(a) * r;
    let y = cy + sin(a) * r;
    let n = noise(x * 0.02, y * 0.02);
    if (n > 0.65) {
      fill(255, 255, 255, random(50, 255));
      circle(x, y, random(0.5, 2.5));
    }
  }

  // 7. Griffures et grain de la toile (pour l'aspect peinture physique)
  stroke(255, 255, 255, 7);
  strokeWeight(1);
  for (let i = 0; i < 30000; i++) {
    let x = random(width);
    let y = random(height);
    if (random() > 0.5) {
      line(x, y, x + random(-3, 3), y + random(10, 25));
    } else {
      line(x, y, x + random(10, 25), y + random(-3, 3));
    }
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // Couleur de fond (le vide insondable)
  background(6, 4, 8);

  // 1. Texture de la toile (grain)
  noStroke();
  for (let i = 0; i < 200000; i++) {
    fill(255, random(1, 4));
    circle(random(width), random(height), random(0.5, 2));
  }

  // 2. Sous-couche de peinture (ténèbres profondes et stries verticales)
  for (let i = 0; i < 1500; i++) {
    let x = random(width);
    let y = random(height);
    let len = random(100, 500);
    stroke(random(2, 10), random(0, 5), random(5, 15), random(5, 15));
    strokeWeight(random(10, 50));
    line(x, y, x, y - len);
  }

  let centerX = width / 2;
  let centerY = height * 0.75;

  // 3. Le cœur lumineux (l'étincelle de vie avant sa disparition)
  noStroke();
  for (let i = 0; i < 400; i++) {
    let cr = random(50, 350);
    let cx = centerX + randomGaussian(0, 50);
    let cy = centerY + randomGaussian(0, 50);
    fill(255, 180, 50, 3);
    circle(cx, cy, cr);
  }

  // 4. La Dissolution (Particules d'énergie se dispersant dans le vide)
  let colorStart = color(255, 255, 200);
  let colorMid1 = color(240, 60, 10);
  let colorMid2 = color(50, 15, 25);
  let colorEnd = color(6, 4, 8);

  let numParticles = 10000;
  for (let i = 0; i < numParticles; i++) {
    let r = abs(randomGaussian(0, 120));
    let theta = random(TWO_PI);
    let x = centerX + r * cos(theta);
    let y = centerY + r * sin(theta) * 0.6;

    let distCenter = dist(x, y, centerX, centerY);
    let maxLife = map(distCenter, 0, 300, 700, 200) + random(-50, 100);
    if (maxLife < 50) maxLife = 50;

    let vx = 0;
    let vy = 0;

    for (let j = 0; j < maxLife; j++) {
      let ratio = j / maxLife;

      // Champ de bruit pour le mouvement organique
      let n = noise(x * 0.0015, y * 0.0015, i * 0.0001);
      let angle = n * TWO_PI * 5;

      // Forces d'écoulement
      vx += cos(angle) * 0.12;
      vy += sin(angle) * 0.12;

      // Dérive vers le haut (l'élévation vers le néant)
      vy -= map(ratio, 0, 1, 0.05, 0.25);

      // Friction pour lisser le mouvement
      vx *= 0.93;
      vy *= 0.93;

      let nx = x + vx;
      let ny = y + vy;

      // Transition des couleurs (Vie -> Cendres -> Vide)
      let c;
      if (ratio < 0.15) {
        c = lerpColor(colorStart, colorMid1, ratio / 0.15);
      } else if (ratio < 0.45) {
        c = lerpColor(colorMid1, colorMid2, (ratio - 0.15) / 0.30);
      } else {
        c = lerpColor(colorMid2, colorEnd, (ratio - 0.45) / 0.55);
      }

      let alpha = map(ratio, 0, 1, 180, 0);
      c.setAlpha(alpha);
      stroke(c);

      // Le trait s'affine avec le temps
      let sw = map(ratio, 0, 1, random(2, 6), 0.1);
      strokeWeight(sw);

      line(x, y, nx, ny);

      // Poussière cosmique et cendres volatiles
      if (random() < 0.002 && ratio < 0.7) {
        noStroke();
        c.setAlpha(alpha * 1.5);
        fill(c);
        circle(x + random(-5, 5), y + random(-5, 5), random(1, 3.5));
      }

      x = nx;
      y = ny;

      // Arrêt si la particule sort de la toile
      if (x < 0 || x > width || y < 0 || y > height) break;
    }
  }

  // 5. Vignette finale (L'obscurité qui se referme sur les bords)
  noFill();
  for (let i = 0; i < 400; i++) {
    stroke(0, 0, 0, map(i, 0, 400, 200, 0));
    strokeWeight(3);
    rect(i, i, width - i * 2, height - i * 2);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // 1. Fond et dégradé atmosphérique de base
  noStroke();
  for (let y = 0; y < height; y += 4) {
    let c = lerpColor(color(120, 135, 150), color(5, 5, 8), y / height);
    fill(c);
    rect(0, y, width, 4);
  }

  let cx = width / 2;
  let cy = height * 0.68; // Le centre gravitationnel de la mort (Le Vide)

  // 2. Couches de peinture (Impasto / Flux)
  for (let i = 0; i < 220000; i++) {
    let x = random(width);
    let y = random(height);

    let d = dist(x, y, cx, cy);
    let n = noise(x * 0.001, y * 0.002);

    let alpha = random(10, 45);
    let weight = random(1, 4);
    let col;

    // Détermination des couleurs selon la zone
    if (d < 350) {
      // Au cœur du Vide : ténèbres écrasantes
      if (random() > 0.7) col = color(25, 5, 5, alpha);
      else col = color(2, 2, 3, alpha * 2);
    } 
    else if (d < 580 && y < cy) {
      // Horizon des événements : l'énergie s'échappe
      if (random() > 0.6) col = color(212, 175, 55, alpha * 1.8); // Or pur
      else if (random() > 0.3) col = color(242, 92, 5, alpha * 1.5); // Braise
      else col = color(138, 43, 26, alpha); // Rouille
    } 
    else if (y < height * 0.45) {
      // L'Éther (Cieux paisibles et froids)
      if (n < 0.3) col = color(225, 225, 220, alpha);
      else if (n < 0.6) col = color(130, 150, 165, alpha);
      else col = color(190, 170, 130, alpha * 0.8);
    } 
    else if (y < height * 0.75) {
      // La Déchirure (Zone de transition latérale)
      if (random() > 0.5) col = color(80, 25, 15, alpha);
      else col = color(35, 12, 12, alpha);
    } 
    else {
      // Les Abysses (La lourdeur terrestre s'effondrant)
      if (n < 0.4) col = color(22, 12, 10, alpha);
      else if (n < 0.7) col = color(15, 15, 18, alpha);
      else col = color(5, 5, 6, alpha);
    }

    stroke(col);
    strokeWeight(weight);
    noFill();

    let strokeLen = random(15, 90);
    beginShape();
    for (let j = 0; j < strokeLen; j += 5) {
      vertex(x, y);

      let currentD = dist(x, y, cx, cy);
      let angle;

      if (currentD < 320) {
        // Aspiration gravitationnelle vers l'intérieur
        angle = atan2(cy - y, cx - x) + (noise(x * 0.01, y * 0.01) - 0.5) * 0.8;
      } 
      else if (currentD < 580 && y < cy) {
        // Éruption directionnelle vers le haut et l'extérieur
        let vx = x - cx;
        let vy = y - cy - 250; 
        angle = atan2(vy, vx) + (noise(x * 0.005, y * 0.005) - 0.5) * 1.2;
      } 
      else if (y < height * 0.45) {
        // Nuages éthérés, dissolution calme et horizontale
        angle = noise(x * 0.002, y * 0.002) * TWO_PI;
      } 
      else if (y < height * 0.75) {
        // Agitation autour du seuil
        angle = -HALF_PI + (noise(x * 0.005, y * 0.005) - 0.5) * 2;
      } 
      else {
        // La sédimentation lourde vers le bas
        angle = HALF_PI + (noise(x * 0.003, y * 0.003) - 0.5);
      }

      x += cos(angle) * 4;
      y += sin(angle) * 4;
    }
    endShape();
  }

  // 3. Les Étincelles (Derniers souffles s'échappant du corps)
  for (let i = 0; i < 4500; i++) {
    let x = random(width);
    let y = random(height * 0.15, cy + 50);

    // Concentration sur le panache ascendant
    let d = dist(x, y, cx, cy);
    if (d > 450 && random() > 0.04) continue;

    stroke(255, random(220, 255), random(180, 255), random(60, 255));
    strokeWeight(random(1, 3.5));
    let h = random(15, 100);

    beginShape();
    for (let j = 0; j < h; j += 4) {
      vertex(x, y);
      x += (noise(x * 0.01, y * 0.01) - 0.5) * 3;
      y -= random(2, 6);
    }
    endShape();
  }

  // 4. Vignette (Cadrage oppressant aux bords)
  noFill();
  for (let d = 0; d < 600; d += 5) {
    stroke(2, 2, 3, map(d, 0, 600, 255, 0));
    strokeWeight(6);
    rect(d / 2, d / 2, width - d, height - d);
  }

  // 5. Grain global (Texture de toile picturale)
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let n = random(-16, 16);
    pixels[i] = constrain(pixels[i] + n, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + n, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + n, 0, 255);
  }
  updatePixels();
}

let shellParticles = [];
let energyParticles = [];

function setup() {
  createCanvas(1600, 2000);
  noLoop();
  randomSeed(1);
  noiseSeed(1);

  // Background
  background(5, 6, 10);
  noStroke();

  // Subtle deep void radial gradient
  for (let r = 2500; r > 0; r -= 20) {
    let inter = map(r, 0, 2500, 1, 0);
    fill(15 * inter, 20 * inter, 35 * inter, 15);
    circle(width / 2, height / 2, r);
  }

  // Ambient stardust / void particles
  for (let i = 0; i < 5000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.01, y * 0.01);
    if (n > 0.6) {
      fill(255, 255, 255, random(10, 60));
      circle(x, y, random(0.5, 2.5));
    }
  }

  // The Core (Physical Body / Existence)
  let cx = width / 2;
  let cy = height * 0.75; // Rooted heavily towards the bottom
  let maxR = 600;

  // Generate the structural points
  for (let i = 0; i < 150000; i++) {
    let r = maxR * sqrt(random());
    let theta = random(TWO_PI);

    // Organic noise deformation of the sphere's edges
    let rWarp = r + map(noise(theta * 3, r * 0.01), 0, 1, -80, 80);
    let x = cx + rWarp * cos(theta);
    let y = cy + rWarp * sin(theta);

    // Noise map to create deep cracks and fractures
    let n = noise(x * 0.005, y * 0.005);
    let isCrack = abs(n - 0.5) < 0.05;

    // Probability of a particle dissolving into energy
    let energyProb = 0;

    // Cracks leak intense energy
    if (isCrack) energyProb += 0.8;

    // The top part dissolves more rapidly into the void
    if (y < cy) {
      energyProb += map(y, cy, cy - maxR, 0, 0.7);
    }

    // The outer edges shed energy
    energyProb += map(r, 0, maxR, 0, 0.4);

    if (random() < energyProb) {
      energyParticles.push({ x: x, y: y });
    } else {
      shellParticles.push({ x: x, y: y, r: r });
    }
  }

  // Render Pass 1: The physical shell (Dark, heavy, earthy)
  blendMode(BLEND);
  for (let p of shellParticles) {
    let distRatio = p.r / maxR;
    let cVal = map(distRatio, 0, 1, 5, 45);
    fill(cVal + 15, cVal * 0.6, cVal * 0.6, 220); // Dark ember / obsidian tones
    noStroke();
    circle(p.x, p.y, random(2, 5));
  }

  // Render Pass 2: The escaping energy (Glowing, ethereal, ascending)
  blendMode(SCREEN);
  for (let p of energyParticles) {
    // Only draw flow lines for a fraction to balance aesthetics and performance
    if (random() < 0.06) {
      drawFlow(p.x, p.y);
    } else {
      // The rest form a glowing aura/mist in the cracks
      fill(255, random(100, 200), 50, random(30, 70));
      noStroke();
      circle(p.x, p.y, random(1, 3.5));
    }
  }
}

// Draw the upward journey of the soul/energy
function drawFlow(startX, startY) {
  let curX = startX;
  let curY = startY;
  let steps = random(100, 400);
  let weight = random(0.5, 2.5);
  let stepLength = 4;

  noFill();
  for (let j = 0; j < steps; j++) {
    // Noise flow field guiding particles upward
    let n = noise(curX * 0.002, curY * 0.002);
    let angle = map(n, 0, 1, -PI - 1, 1);

    // Gravity/Ascension bias forcing drift predominantly up
    angle = lerp(angle, -HALF_PI, 0.6);

    let nx = curX + cos(angle) * stepLength;
    let ny = curY + sin(angle) * stepLength;

    let prog = j / steps;
    let c = getEnergyColor(prog);

    // Fade out as it ascends and thins out
    stroke(c.r, c.g, c.b, c.a);
    strokeWeight(weight * (1 - prog));
    line(curX, curY, nx, ny);

    curX = nx;
    curY = ny;

    // Stop if it floats entirely out of bounds
    if (curX < 0 || curX > width || curY < 0) break;
  }
}

// Color gradient: Heat/Flesh -> Spirit/Cyan -> Void/Transparent
function getEnergyColor(p) {
  let c = { r: 0, g: 0, b: 0, a: 0 };
  if (p < 0.2) {
    // Embers
    let t = p / 0.2;
    c.r = lerp(150, 255, t);
    c.g = lerp(20, 100, t);
    c.b = lerp(10, 30, t);
    c.a = 35;
  } else if (p < 0.5) {
    // Transition to ethereal fire
    let t = (p - 0.2) / 0.3;
    c.r = lerp(255, 50, t);
    c.g = lerp(100, 150, t);
    c.b = lerp(30, 200, t);
    c.a = 30;
  } else if (p < 0.8) {
    // Pure spirit / cyan stardust
    let t = (p - 0.5) / 0.3;
    c.r = lerp(50, 10, t);
    c.g = lerp(150, 80, t);
    c.b = lerp(200, 255, t);
    c.a = lerp(30, 10, t);
  } else {
    // Fading into the abyss
    let t = (p - 0.8) / 0.2;
    c.r = lerp(10, 0, t);
    c.g = lerp(80, 20, t);
    c.b = lerp(255, 100, t);
    c.a = lerp(10, 0, t);
  }
  return c;
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // 1. Background Gradient (Deep Space / The Abyss)
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let r = map(inter, 0, 1, 0, 25);
    let g = map(inter, 0, 1, 2, 12);
    let b = map(inter, 0, 1, 5, 15);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  let voidX = width / 2;
  let voidY = 600;
  let voidR = 400;

  // 2. The Void (Aura and the absolute zero center)
  noStroke();
  // Outer soft corona
  for (let r = 900; r > 0; r -= 5) {
    let alpha = map(r, 0, 900, 255, 0);
    fill(10, 12, 18, alpha * 0.04);
    circle(voidX, voidY, r * 2);
  }
  // Inner dark event horizon
  for (let r = voidR; r > 0; r -= 2) {
    let alpha = map(r, 0, voidR, 255, 0);
    fill(0, 0, 0, alpha * 0.8);
    circle(voidX, voidY, r * 2);
  }

  // 3. The Flow (Life, Memories, Experiences dissolving into the void)
  let numPaths = 14000;
  for (let i = 0; i < numPaths; i++) {
    // Particles originate mostly from the bottom, some scattered
    let x = random(-300, width + 300);
    let y = random(1000, height + 1000);
    if (random() < 0.25) {
      x = random(-200, width + 200);
      y = random(500, 1000);
    }

    let life = random(100, 600); // Length of the path
    let thickness = random(0.5, 4.5);

    // Color palettes representing different aspects of life
    let cType = random();
    let baseR, baseG, baseB;
    if (cType < 0.35) {
      // Passion, pain, love (Crimson/Red)
      baseR = random(160, 240); baseG = random(30, 70); baseB = random(20, 50);
    } else if (cType < 0.65) {
      // Joy, wealth, warmth (Gold/Amber)
      baseR = random(200, 255); baseG = random(140, 190); baseB = random(30, 80);
    } else if (cType < 0.90) {
      // Peace, sadness, depth (Azure/Teal)
      baseR = random(10, 60); baseG = random(100, 160); baseB = random(150, 220);
    } else {
      // Neutral, ordinary moments (Ash/Dust)
      baseR = random(100, 140); baseG = random(100, 140); baseB = random(110, 150);
    }

    let speed = random(2, 7);

    for (let step = 0; step < life; step++) {
      let dx = voidX - x;
      let dy = voidY - y;
      let d = sqrt(dx * dx + dy * dy);

      // Break if entirely consumed by the void core
      if (d < 15) break;

      let angle = atan2(dy, dx);
      // Spiral tangent (swirling counter-clockwise into the center)
      let tangent = angle + HALF_PI;

      // Forces changing based on distance to the void
      let pull = map(d, 0, 1500, 1.8, 0.3);
      let swirl = map(d, 0, 800, 2.5, 0.05);
      swirl = constrain(swirl, 0, 2.5);

      // Organic noise turbulence
      let n = noise(x * 0.0015, y * 0.0015) * TWO_PI * 3;

      let vx = cos(angle) * pull + cos(tangent) * swirl + cos(n) * 1.2;
      let vy = sin(angle) * pull + sin(tangent) * swirl + sin(n) * 1.2;

      // Normalize and apply speed
      let mag = sqrt(vx * vx + vy * vy);
      vx = (vx / mag) * speed;
      vy = (vy / mag) * speed;

      let nextX = x + vx;
      let nextY = y + vy;

      // Dissolution effect: Colors fade to luminous white/ash as they get close
      let mixAmt = map(d, voidR * 1.5, voidR * 0.3, 0, 1);
      mixAmt = constrain(mixAmt, 0, 1);
      let curR = lerp(baseR, 245, mixAmt);
      let curG = lerp(baseG, 245, mixAmt);
      let curB = lerp(baseB, 255, mixAmt);

      // Opacity fades out into the void, and starts gently at birth
      let alpha = map(d, voidR * 0.15, voidR * 2, 0, 180);
      alpha = constrain(alpha, 0, 180);
      let lifeFade = map(step, 0, 20, 0, 1); // Fade in
      lifeFade = constrain(lifeFade, 0, 1);
      alpha *= lifeFade;

      // Stroke thins out as it gets consumed
      let currentThickness = thickness * map(d, 0, height, 0.2, 1.2);

      stroke(curR, curG, curB, alpha);
      strokeWeight(currentThickness);
      line(x, y, nextX, nextY);

      x = nextX;
      y = nextY;
    }
  }

  // 4. Ethereal Dust (Sparks of consciousness dissolving)
  for (let i = 0; i < 4000; i++) {
    let x = random(width);
    let y = random(height);
    let d = dist(x, y, voidX, voidY);
    if (d > 80 && d < 1400) {
      if (random() < 0.08) {
        let alpha = map(d, 80, 1400, 220, 0);
        stroke(255, 240, 200, alpha);
        strokeWeight(random(1, 4));
        point(x, y);
      }
    }
  }

  // 5. Painterly Texture (Film grain / Canvas feel)
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let noiseVal = random(-14, 14);
    pixels[i] = constrain(pixels[i] + noiseVal, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + noiseVal, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + noiseVal, 0, 255);
  }
  updatePixels();
}

function setup() {
    createCanvas(1600, 2000);
    randomSeed(1);
    noiseSeed(1);
    noLoop();
}

function draw() {
    // 绘制深幽的虚空背景渐变
    for (let y = 0; y < height; y++) {
        let inter = map(y, 0, height, 1, 0);
        let c = lerpColor(color(3, 4, 7), color(16, 20, 28), inter);
        stroke(c);
        line(0, y, width, y);
    }

    // 添加宇宙背景的微粒噪点
    stroke(255, 12);
    strokeWeight(1.5);
    for(let i = 0; i < 150000; i++) {
        point(random(width), random(height));
    }

    let nParticles = 18000;
    let c_dist = 6.1; 
    let goldenAngle = 137.508 * (Math.PI / 180.0);
    let seeds = [];

    // 初始化生命种子（斐波那契螺旋）及其熵值
    for (let i = 0; i < nParticles; i++) {
        let r = c_dist * Math.sqrt(i);
        let theta = i * goldenAngle;
        let sx = width / 2 + r * Math.cos(theta);
        let sy = height * 0.75 + r * Math.sin(theta);

        // 生命的色彩（中心最亮，边缘转为深红）
        let distNorm = i / nParticles;
        let rCol = map(distNorm, 0, 1, 255, 120);
        let gCol = map(distNorm, 0, 1, 240, 10);
        let bCol = map(distNorm, 0, 1, 150, 30);

        // 叠加噪点使色彩更具生命质感
        let nC = noise(sx * 0.01, sy * 0.01);
        rCol = constrain(rCol + (nC - 0.5) * 50, 0, 255);
        gCol = constrain(gCol + (nC - 0.5) * 50, 0, 255);
        bCol = constrain(bCol + (nC - 0.5) * 50, 0, 255);

        // 计算熵值：决定粒子是否解构及解构的程度
        let noiseFront = (noise(sx * 0.003, sy * 0.003) - 0.5) * 1000;
        let effectiveY = sy + noiseFront;
        let radialFactor = map(r, 0, 850, 0, 280);
        effectiveY -= radialFactor;

        let entropy = map(effectiveY, 1750, 850, 0, 1.2);
        entropy = constrain(entropy, 0, 1.2);

        // 极小概率产生未燃尽的“余烬”（灵魂碎片）
        let isEmber = (entropy > 0.1 && random() < 0.015);

        seeds.push({sx, sy, entropy, rCol, gCol, bCol, isEmber});
    }

    // 第一层：绘制解构后的尘埃与轨迹（死亡的风化）
    for (let i = 0; i < seeds.length; i++) {
        let s = seeds[i];
        let stepCount = map(s.entropy, 0, 1, 0, 450);

        if (stepCount > 2) {
            let cx_pos = s.sx;
            let cy_pos = s.sy;

            for (let j = 0; j < stepCount; j++) {
                let progress = j / stepCount;
                let alpha, sw;
                let currentC;

                if (s.isEmber) {
                    currentC = lerpColor(color(255, 230, 120), color(0, 180, 255), progress);
                    alpha = map(progress, 0, 1, 255, 0);
                    sw = map(progress, 0, 1, 3.5, 0.5);
                } else {
                    let ashColor = color(90, 95, 105);
                    if (progress < 0.35) {
                        currentC = lerpColor(color(s.rCol, s.gCol, s.bCol), ashColor, progress * 2.85);
                    } else {
                        currentC = lerpColor(ashColor, color(10, 12, 16), (progress - 0.35) * 1.5);
                    }
                    alpha = map(pow(progress, 1.5), 0, 1, 220, 0);
                    sw = map(progress, 0, 1, 2.0, 0.1);
                }

                let nScale = 0.0015;
                let n = noise(cx_pos * nScale, cy_pos * nScale, i * 0.00002);
                let angle = map(n, 0, 1, -PI, PI);

                // 向上的引力随熵值增加而变强
                let upwardForce = map(s.entropy, 0, 1, 1.5, 4.5) + progress * 3.5;
                let vx = cos(angle) * 2.2 + (cx_pos - width / 2) * 0.0008;
                let vy = sin(angle) * 2.2 - upwardForce;

                // 余烬具有更剧烈、不规则的挣扎运动
                if (s.isEmber) {
                    vx += (noise(cx_pos * 0.02, j * 0.05) - 0.5) * 2.5;
                    strokeWeight(sw * 2);
                    stroke(red(currentC), green(currentC), blue(currentC), alpha * 0.25);
                    line(cx_pos, cy_pos, cx_pos + vx, cy_pos + vy);
                }

                strokeWeight(sw);
                stroke(red(currentC), green(currentC), blue(currentC), alpha);

                let nx = cx_pos + vx;
                let ny = cy_pos + vy;
                line(cx_pos, cy_pos, nx, ny);

                cx_pos = nx;
                cy_pos = ny;

                if (cy_pos < -50 || alpha < 2) break;
            }
        }
    }

    // 第二层：绘制尚存的生命核心（完美的秩序）
    for (let i = 0; i < seeds.length; i++) {
        let s = seeds[i];
        if (s.entropy < 1.0) {
            let seedAlpha = map(s.entropy, 0, 0.8, 255, 0);
            let sz = map(s.entropy, 0, 0.8, 6.5, 0);

            noStroke();
            // 核心实心
            fill(s.rCol, s.gCol, s.bCol, seedAlpha);
            circle(s.sx, s.sy, sz);
            // 核心光晕
            fill(s.rCol, s.gCol, s.bCol, seedAlpha * 0.2);
            circle(s.sx, s.sy, sz * 2.8);
        }
    }
}

function setup() {
  createCanvas(1600, 2000);
  noLoop();
  randomSeed(1);
  noiseSeed(1);

  // 绘制静谧深邃的渐变背景
  background(5, 4, 7);
  for(let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(15, 12, 20), color(2, 1, 2), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // 使用 ADD 混合模式表现光影与能量
  blendMode(ADD);

  let cx = width / 2;
  let cy = 500;

  // 1. 流场：象征灵魂与能量的消散、坠落与流逝
  for (let i = 0; i < 25000; i++) {
    // 初始位置集中在核心区域
    let rInitial = random(0, 350);
    rInitial = rInitial * rInitial / 350; 
    let theta = random(TWO_PI);
    let x = cx + rInitial * cos(theta);
    let y = cy + rInitial * sin(theta);

    let maxSteps = random(150, 700);
    let px = x, py = y;

    // 一小部分代表着生命最后强烈的余辉（暗红/深橙）
    let isBlood = random() < 0.05;

    for (let step = 0; step < maxSteps; step++) {
      let n = noise(x * 0.0015, y * 0.002, i * 0.0001);
      let angle = map(n, 0, 1, -TWO_PI, TWO_PI);

      // 随着坠落，向下方的引力逐渐增强
      let gravity = map(y, cy, 2000, 0.5, 4.0);

      x += cos(angle) * 1.5 + (x - cx) * 0.0003;
      y += sin(angle) * 1.5 + gravity;

      let t = map(y, cy, 1900, 0, 1, true);
      let r, g, b;

      if (isBlood) {
        r = lerp(200, 50, t);
        g = lerp(20, 0, t);
        b = lerp(20, 0, t);
      } else {
        // 色彩随高度渐变：明亮(生) -> 炽热(蜕变) -> 暗淡(归无)
        if (t < 0.2) {
          let mt = map(t, 0, 0.2, 0, 1);
          r = lerp(60, 255, mt);
          g = lerp(180, 140, mt);
          b = lerp(255, 40, mt);
        } else if (t < 0.5) {
          let mt = map(t, 0.2, 0.5, 0, 1);
          r = lerp(255, 200, mt);
          g = lerp(140, 20, mt);
          b = lerp(40, 0, mt);
        } else {
          let mt = map(t, 0.5, 1.0, 0, 1);
          r = lerp(200, 10, mt);
          g = lerp(20, 0, mt);
          b = lerp(0, 0, mt);
        }
      }

      let alpha = map(t, 0, 1, 35, 0);
      if (isBlood) alpha *= 1.5;

      stroke(r, g, b, alpha);
      strokeWeight(map(t, 0, 1, 1.5, 0.2));
      line(px, py, x, y);

      px = x;
      py = y;

      if (y > 2000 || alpha <= 0.5) break;
    }
  }

  // 2. 破碎的几何晶体：象征物理躯壳与严密的意识结构
  let phi = Math.PI * (3 - Math.sqrt(5));
  let numPts = 600;
  let pts = [];

  // 斐波那契球面采样并叠加噪声以形成有机晶体形态
  for (let i = 0; i < numPts; i++) {
    let y = 1 - (i / (numPts - 1)) * 2;
    let radius = Math.sqrt(1 - y * y);
    let theta = phi * i;
    let rScale = 220; 

    let n = noise(cos(theta) * radius * 2, y * 2, sin(theta) * radius * 2);
    rScale *= map(n, 0, 1, 0.7, 1.3);

    let px = cx + cos(theta) * radius * rScale;
    let py = cy + y * rScale;
    let pz = sin(theta) * radius * rScale;

    // 结构的下半部分发生剧烈崩解
    if (py > cy + 20) {
      let fall = map(py, cy + 20, cy + 300, 0, 500);
      py += fall * random(0.5, 1.8);
      px += (px - cx) * random(0.2, 1.0);
    }

    pts.push({x: px, y: py, z: pz});
  }

  // 连接节点形成网状骨架与碎片
  for (let i = 0; i < numPts; i++) {
    for (let j = i + 1; j < numPts; j++) {
      let d = dist(pts[i].x, pts[i].y, pts[j].x, pts[j].y);
      if (d < 70) {
        let t = map(pts[i].y, cy - 250, cy + 400, 0, 1, true);
        let alpha = map(t, 0, 1, 150, 0); // 越往下越透明

        stroke(150, 220, 255, alpha);
        strokeWeight(map(d, 0, 70, 2, 0.1));
        line(pts[i].x, pts[i].y, pts[j].x, pts[j].y);

        // 随机生成半透明的面，增强立体感
        if (random() < 0.15) {
          for(let k = j + 1; k < numPts; k++) {
            let d2 = dist(pts[j].x, pts[j].y, pts[k].x, pts[k].y);
            let d3 = dist(pts[i].x, pts[i].y, pts[k].x, pts[k].y);
            if (d2 < 70 && d3 < 70) {
              fill(80, 150, 255, alpha * 0.15);
              noStroke();
              triangle(pts[i].x, pts[i].y, pts[j].x, pts[j].y, pts[k].x, pts[k].y);
            }
          }
        }
      }
    }
  }

  // 3. 向上升腾的微光点：象征解脱的微小精神碎片
  for(let i = 0; i < 300; i++) {
    let ox = cx + random(-400, 400);
    let oy = random(100, cy + 200);
    let d = dist(ox, oy, cx, cy);
    let a = map(d, 0, 500, 80, 0, true);
    fill(200, 240, 255, a);
    noStroke();
    circle(ox, oy, random(1, 4));
  }

  // 4. 全局胶片颗粒质感，赋予画作沉淀的时间感
  blendMode(BLEND);
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let n = random(-12, 12);
    pixels[i]   = constrain(pixels[i]   + n, 0, 255);
    pixels[i+1] = constrain(pixels[i+1] + n, 0, 255);
    pixels[i+2] = constrain(pixels[i+2] + n, 0, 255);
  }
  updatePixels();
}

let palette = [];

function setup() {
    createCanvas(1600, 2000);
    randomSeed(1);
    noiseSeed(1);
    noLoop();

    background(5, 7, 12);

    strokeWeight(1);
    for (let i = 0; i < 35000; i++) {
        let x = random(width);
        let y = random(height);
        let n = noise(x * 0.002, y * 0.01);
        stroke(255, n * 12);
        point(x, y);
    }

    let ctx = drawingContext;
    let grad = ctx.createRadialGradient(width / 2, height / 2, 400, width / 2, height / 2, 1400);
    grad.addColorStop(0, 'rgba(0,0,0,0)');
    grad.addColorStop(1, 'rgba(0,0,0,0.9)');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, width, height);

    blendMode(ADD);

    for (let i = 0; i <= 1000; i++) {
        let p = i / 1000;
        let c;
        if (p < 0.15) {
            c = lerpColor(color(255, 250, 240, 12), color(255, 180, 30, 8), p / 0.15);
        } else if (p < 0.4) {
            c = lerpColor(color(255, 180, 30, 8), color(220, 30, 40, 4), (p - 0.15) / 0.25);
        } else if (p < 0.7) {
            c = lerpColor(color(220, 30, 40, 4), color(15, 5, 25, 1.5), (p - 0.4) / 0.3);
        } else {
            c = lerpColor(color(15, 5, 25, 1.5), color(40, 130, 255, 3), (p - 0.7) / 0.3);
        }
        palette.push(c);
    }

    let cx = width / 2;
    let cy = 600;
    let numParticles = 35000;

    for (let i = 0; i < numParticles; i++) {
        let rBase = pow(random(), 1.5) * 550;
        let a = random(TWO_PI);
        let r = rBase + sin(a * 7) * 60; 
        let x = cx + r * cos(a);
        let y = cy + r * sin(a);

        let life = random(300, 900);
        let px = x;
        let py = y;

        for (let t = 0; t < life; t++) {
            let dx = x - cx;
            let dy = y - cy;
            let angle = atan2(dy, dx);

            let decay = map(y, cy, cy + 900, 0, 1);
            decay = constrain(decay, 0, 1);

            let cIndex = floor(decay * 1000);
            if (cIndex > 1000) cIndex = 1000;
            if (cIndex < 0) cIndex = 0;

            stroke(palette[cIndex]);
            strokeWeight(map(decay, 0, 1, 0.7, 0.2) + (i % 50 === 0 ? 0.6 : 0));

            let lifeRatio = t / life;
            if (lifeRatio > 0.8) {
                drawingContext.globalAlpha = map(lifeRatio, 0.8, 1.0, 1.0, 0.0);
            } else {
                drawingContext.globalAlpha = 1.0;
            }

            let tx = -sin(angle);
            let ty = cos(angle);
            let inward = 0.15;
            let sx = tx - cos(angle) * inward;
            let sy = ty - sin(angle) * inward + 0.3; 

            let n1 = noise(x * 0.002, y * 0.002, i * 0.0001) * TWO_PI * 6;
            let chaosSpread = map(y, cy, height, 1.0, 6.0);
            let fallX = cos(n1) * chaosSpread + (noise(x * 0.01 + 100, y * 0.01) * 2 - 1) * 2.0;
            let fallY = sin(n1) * 2.0 + map(y, cy, height, 1.5, 5.0);

            let vx = lerp(sx * 4.5, fallX, decay);
            let vy = lerp(sy * 4.5, fallY, decay);

            x += vx;
            y += vy;

            line(px, py, x, y);
            px = x;
            py = y;

            if (y > height + 100 || x < -100 || x > width + 100) break;
        }
    }
    drawingContext.globalAlpha = 1.0;
}

