  // Face
  fill(245, 235, 245, 120);
  ellipse(cx+52, cy-14, 55, 66);

  // Arm dissolving away to mist
  for (let i=0; i<8; i++) {
    fill(185, 160, 190, 60-6*i);
    ellipse(cx+35+17*i, cy+40+7*i, 34-2.3*i, 18-1.5*i);
  }
  pop();

  // The veil: Float mist above figure
  noStroke();
  for (let k = 0; k < 170; k++) {
    let x = cx + random(-180, 180);
    let y = cy - 80 + random(-45, 160);
    let r = map(noise(x*0.02, y*0.004+k), 0, 1, 42, 120);
    fill(220, 225, 245, 10 + random(13,40));
    ellipse(x, y, r+random(-12,12));
  }

  // Faint glowing forms rising
  for (let i=0; i<32; i++) {
    let px = cx + random(-100, 100);
    let py0 = cy - random(60, 220);
    let amp = random(9,18);
    let q = random(10,36);
    push();
    for (let j=0; j<q; j++) {
      let r = map(j,0,q-1, 26, 2);
      let py = py0 - j*19 +amp*sin(j*PI/10 + random(-0.1,0.12));
      fill(240, 245-(6*j), 255, 42 - j*1.6);
      ellipse(px + sin(j*PI/7)*8, py, r, r * map(noise(j, i),0,1,0.88,1.05));
    }
    pop();
  }

  // Distant suggestion of new form in upper right (suggestion of renewal)
  noStroke();
  for (let i=0; i<23; i++) {
    let px = width*0.80 + 20*cos(i*PI/15);
    let py = 170 + 60*sin(i*PI/15);
    fill(253, 250, 220, 90-3.2*i);
    ellipse(px, py, 60-2.5*i, 37-1.8*i);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);

  // Background gradient: warm to dark
  for(let y = 0; y < height; y++) {
    let lerpAmt = pow(y / height, 1.5);
    let c1 = color(220, 191, 146);
    let c2 = color(31, 29, 40);
    stroke(lerpColor(c1, c2, lerpAmt));
    line(0, y, width, y);
  }

  // Central eclipse: Black circle with halo
  let cx = width / 2;
  let cy = height * 0.55;
  let r1 = 530;
  let r2 = 610;
  for(let r = r2; r > r1; r -= 2) {
    let a = map(r, r2, r1, 0, 80);
    noFill();
    stroke(220, 176, 47, a);
    strokeWeight(4);
    ellipse(cx, cy, r, r);
  }
  noStroke();
  fill(22, 20, 30, 235);
  ellipse(cx, cy, r1, r1);

  // Drifting veil forms (wisp shapes)
  for(let j = 0; j < 5; j++) {
    let baseX = cx + random(-230, 230);
    let baseY = cy + random(-70, 210);
    let w = random(180, 350);
    let h = random(250, 460);
    let ww = random(60, 110);
    let fadeColor = lerpColor(color(240,215,170,40), color(70,50,90,45), random());
    noStroke();
    beginShape();
    for(let t = 0; t < 1.01; t += 0.06) {
      let ang = lerp(-PI/3, PI+PI/3, t);
      let rx = cos(ang) * w * 0.5 + noise(j*1.6+t*4)*ww;
      let ry = sin(ang) * h * 0.4 + noise(j*2.2+10+t*4)*ww;
      vertex(baseX + rx, baseY + ry);
    }
    for(let t = 1; t > -0.01; t -= 0.06) {
      let ang = lerp(PI+PI/3, -PI/3, t);
      let rx = 0.8 * cos(ang) * w * 0.22 + noise(j*1.7+t*2)*ww*0.35;
      let ry = 0.8 * sin(ang) * h * 0.42 + noise(j*2.3+5+t*2)*ww*0.32;
      vertex(baseX + rx, baseY + ry);
    }
    fill(fadeColor);
    endShape(CLOSE);
  }

  // Pale, translucent moths (symbols of the soul)
  for(let i = 0; i < 8; i++) {
    let ang = random(TWO_PI);
    let dist = random(210, 440);
    let mx = cx + cos(ang) * dist + random(-15,15);
    let my = cy + sin(ang) * dist + random(-13,13) + 75*(random()-0.5);
    drawMoth(mx, my, random(54, 92), random(45, 76), random(-0.6, 0.6), color(210,209,234, 120));
  }
  // One moth half dissolving into darkness
  drawMoth(cx + 13, cy + r1/2 + 82, 82, 64, 0.15, color(73,71,120,110), 0.5);

  // Shadow roots under the eclipse
  for(let k = 0; k < 23; k++) {
    let str = random(200, 470);
    let offset = map(k, 0, 23, -r1*0.5, r1*0.5);
    strokeWeight(map(noise(k*0.7),0,1,2,7));
    stroke(31,20,44, 109);
    noFill();
    beginShape();
    for(let t = 0; t < 1.03; t+=0.08) {
      let nx = cx + offset + sin(t*PI) * 20 * noise(k+5+t*6.1);
      let ny = cy + r1/1.97 + t*str + noise(k*0.8-t)*16;
      vertex(nx, ny);
    }
    endShape();
  }

  // Small white "doorway" slit at the base
  let slitW = 28, slitH = 130;
  fill(255,249,217, 224);
  noStroke();
  rectMode(CENTER);
  rect(cx, cy + r1/1.98 + 170, slitW, slitH, 16);
}

function drawMoth(x, y, w, h, rot, col, dissolve=1) {
  push();
  translate(x, y);
  rotate(rot);
  stroke(255,255,255, 35*dissolve);
  fill(red(col), green(col), blue(col), alpha(col)*dissolve);
  beginShape();
  for(let t = 0; t < 1.01; t += 0.11) {
    let ang = lerp(-PI*0.6, -PI*0.05, t);
    let rx = cos(ang) * w * 0.6 + noise(t*3)*9;
    let ry = sin(ang) * h * 0.7 - noise(t*3+2)*8;
    vertex(rx, ry);
  }
  for(let t = 0; t < 1.01; t += 0.11) {
    let ang = lerp(PI*0.05, PI*0.6, t);
    let rx = cos(ang) * w * 0.6 + noise(t*3+1)*8;
    let ry = sin(ang) * h * 0.7 - noise(t*3+4)*6;
    vertex(rx, ry);
  }
  endShape(CLOSE);
  // central spot
  fill(244,237,183,110*dissolve);
  ellipse(0, 0, w*0.25, h*0.36);
  pop();
}

