function drawBackground() {
  // Gradient from pale ochre (top) to deep blue-black (bottom)
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let c = lerpColor(color(255, 246, 221), color(20, 29, 48), pow(t, 2));
    stroke(c);
    line(0, y, width, y);
  }
}

function drawPathway() {
  // A soft, undulating path from the bottom center upward to light
  let cx = width / 2;
  let pathW = 240;
  for (let y = height * 0.62; y > height * 0.12; y -= 2) {
    let t = (y - height * 0.12) / (height * 0.5);
    let curve = sin(noise(y * 0.003) * PI * 0.4) * 80;
    let x1 = cx - pathW/2 + curve * (1 - t);
    let x2 = cx + pathW/2 + curve * (1 - t);
    let alph = map(y, height * 0.12, height * 0.62, 60, 220);
    let c = lerpColor(color(235, 227, 220, alph), color(158, 163, 173, alph), t);
    noStroke();
    fill(c);
    beginShape();
    vertex(x1, y);
    vertex(x2, y);
    vertex(x2, y+2);
    vertex(x1, y+2);
    endShape(CLOSE);
  }
}

function drawFigures() {
  // Draw three semi-transparent, ghostlike figures walking toward the light
  let baseY = height * 0.61;
  let cx = width / 2;
  let spacing = 65;
  for (let i = 0; i < 3; i++) {
    let x = cx + (i - 1) * spacing + random(-8,8);
    let y = baseY + random(-5,5) + (i == 1 ? 6 : 0);
    drawFigure(x, y, 90, 38, i);
  }
  // Draw one further, nearly dissolved
  drawFigure(cx + random(-14,14), height * 0.47, 70, 25, 3, 120);
}

function drawFigure(x, y, h, w, idx, alphaOverride) {
  push();
  translate(x, y);
  let waver = idx * 0.05;
  let baseCol = color(222, 222, 225, alphaOverride || 170 - idx*42);
  noStroke();
  // Outer silhouette
  beginShape();
  for (let angle = PI+QUARTER_PI; angle <= PI*2-QUARTER_PI; angle += 0.13) {
    let ox = (w/2 + noise(angle*1.8 + waver) * 5) * cos(angle); 
    let oy = (h/2 + noise(angle*2.5 - waver) * 4) * sin(angle); 
    vertex(ox, oy);
  }
  for (let angle = 0+QUARTER_PI; angle <= PI-QUARTER_PI; angle += 0.13) {
    let ox = (w/2 + noise(angle*1.8 + 20 + waver)*4) * cos(angle); 
    let oy = (h/2 + noise(angle*1.5 + 15 - waver)*8) * sin(angle); 
    vertex(ox, oy);
  }
  endShape(CLOSE);
  fill(200, 203, 215, (alphaOverride||120) - 23*idx);
  ellipse(0, -h/3, w*0.42, h*0.33); // Head
  pop();
}

function drawMist() {
  // Wispy, drifting mist across the path, esp. middle and foreground
  for (let l = 0; l < 7; l++) {
    let y = lerp(height * 0.35, height * 0.82, l/6);
    let alph = map(l, 0, 6, 38, 79);
    drawMistLayer(y, alph, l * 0.15 + 0.3);
  }
}

function drawMistLayer(yCenter, alph, noiseWave) {
  let pathW = 230 + noiseWave * 24;
  let cx = width/2;
  beginShape();
  noStroke();
  fill(233, 234, 241, alph);
  for (let x = cx-pathW; x <= cx+pathW; x += 7) {
    let t = (x-cx+pathW)/(2*pathW);
    let n = noise(x*0.003 + noiseWave, yCenter*0.005 + noiseWave);
    let y = yCenter + sin(t*PI)*22 + n*18;
    curveVertex(x, y);
  }
  for (let x = cx+pathW; x >= cx-pathW; x -= 7) {
    let t = (x-cx+pathW)/(2*pathW);
    let n = noise(x*0.003 + noiseWave + 30, yCenter*0.007 - noiseWave);
    let y = yCenter + 70 + n*7 + t*12;
    curveVertex(x, y);
  }
  endShape(CLOSE);
}

