}

function drawSea() {
  // Calm sea: blue faded, glassy, low waves
  let horizon = height * 0.62;
  for (let y = 0; y < height * 0.27; y++) {
    let t = map(y, 0, height * 0.27, 0, 1);
    let c1 = color(86, 123, 167, 110);
    let c2 = color(175, 197, 219, 100);
    stroke(lerpColor(c1, c2, t));
    line(0, horizon + y, width, horizon + y);
  }
  // Add glassy highlights and faint ripples
  noFill();
  for (let i = 0; i < 37; i++) {
    let waveY = horizon + random(-2, height * 0.27) * pow(i/37, 1.7);
    stroke(255, 255, 255, 80 - i*2);
    beginShape();
    for (let x = 0; x <= width; x += 32) {
      let yoff = noise(x * 0.002 + i, i * 0.1) * 8 * (1 - i/40);
      vertex(x, waveY + yoff);
    }
    endShape();
  }
}

function drawDarkShore() {
  // Dark silhouette of the shore in lower foreground -- curved, dissolving edges
  let base = height * 0.84;
  beginShape();
  for (let x = 0; x <= width; x += 16) {
    let n = noise(x * 0.005, 60);
    let yOffset = map(n, 0, 1, -28, 32);
    let fade = constrain(map(x, 0, width, 1, 0.85), 0.82, 1);
    vertex(x, base + yOffset * fade);
  }
  vertex(width, height);
  vertex(0, height);
  endShape(CLOSE);

  // Soften the very bottom with a semi-translucent fade layer
  for(let i=0;i<22;i++) {
    let alpha = map(i,0,21,22,0);
    noStroke();
    fill(33,32,38,alpha);
    rect(0,height-120+i*5,width,7);
  }
  // texture hints: pebbles, scattered, dissolving
  for(let i=0;i<370;i++) {
    let px = random(width);
    let py = random(base+14, height-6);
    let size = random(3, 18)*random(1,1.5);
    let fade = map(py, base+14, height-6, 0.92, 0.2);
    fill(40,32,37, 46*fade);
    ellipse(px, py, size, size*random(0.53,1));
