  for(let a=PI*1.27;a<PI*1.72;a+=0.09){
    let rx = 34 + noise(a*0.7,13)*4;
    let ry = 80 + noise(a*1.15,21)*7;
    vertex(cos(a)*rx,sin(a)*ry-26);
  }
  for(let a=PI*1.72;a>PI*1.27;a-=0.13){
    let rx = 23 + noise(a*0.81,91)*3;
    let ry = 44 + noise(a*1.06,41)*4;
    vertex(cos(a)*rx,sin(a)*ry+38);
  }
  endShape(CLOSE);
  // Head
  ellipse(0,-47,34,32);
  // Shoulder fade/haze
  for(let i=0;i<19;i++) {
    fill(245,247,240,12-i);
