}

function drawFadingBirds() {
  // A few distant, upward birds toward the light; increasingly faded
  let nBirds = 6;
  let baseX = width * 0.54;
  let baseY = height * 0.65;
  for(let i=0;i<nBirds;i++) {
    let t = i/(nBirds-1);
    let bx = lerp(baseX, width*0.58, t) + random(-17,14);
    let by = lerp(baseY, height*0.52, t) + random(-16,8);
    let s = lerp(62, 38, t) * random(0.97,1.06);
    let al = map(i,0,nBirds-1,186,40);
    stroke(222,225,230, al);
    strokeWeight(lerp(5,1.1,t));
    noFill();
    beginShape();
    let wings = [ -PI/7, 0, PI/7 ];
    for(let j=0;j<3;j++){
      let ang = wings[j];
      let rx = cos(ang)*s*0.73;
      let ry = sin(ang)*s*0.17;
      curveVertex(bx+rx, by+ry);
    }
    endShape();
  }
}

