    let x = width/2 + (i-2.5)*random(118,202);
    let y1 = height*0.34+random(-34,22), y2 = height*0.9+random(38,62);
    let sw = random(80, 230);
    let alpha = 46 + i*12;
    let grad = drawingContext.createLinearGradient(x, y1, x, y2);
    grad.addColorStop(0, color(32,42,62,0));
    grad.addColorStop(0.15, color(18,23,42, alpha/2));
    grad.addColorStop(0.75, color(38,39,48, alpha));
    grad.addColorStop(1, color(19,18,28, 0));
    drawingContext.save();
    drawingContext.globalAlpha = 0.27;
