}

function drawSilhouettes() {
  // Abstract suggestive forms: the border between "being" and "not"
  blendMode(MULTIPLY);
  for (let i = 0; i < 3; i++) {
    let baseX = width * 0.30 + i*width*0.21 + random(-11,11);
    let baseY = height * 0.785 + random(-7,7);
    let noiseScale = 0.0085+random(-0.002,0.003);
    fill(34,20,41, 203);
    beginShape();
    for (let a = PI*0.97; a < PI*2.03; a += 0.11) {
      let rad = width*0.13 
        + noise(i*90+a*1.4, i*21+a*0.17) * width*0.021;
      let x = baseX + cos(a) * rad;
      let y = baseY + sin(a) * rad * 0.82
        + noise(x*noiseScale,y*noiseScale) * 26 * sin(a-PI);
      vertex(x,y);
    }
    for (let a = PI*2.03; a > PI*0.97; a -= 0.12) {
      let rad = width*0.09 
        + noise((i+3)*81+a*0.21, (i+2)*11+a*0.20) * width*0.017;
      let x = baseX + cos(a) * rad;
      let y = baseY + sin(a) * rad * 0.70
        + noise(x*noiseScale*0.97, y*noiseScale*0.98) * 20;
      vertex(x,y);
    }
    endShape(CLOSE);
  }
  blendMode(BLEND);
}

