function drawHorizon() {
  // Misted horizon line
  let y0 = height * 0.72;
  for (let i = 0; i < width; i += 4) {
    let n = noise(i * 0.003, 140);
    let wav = map(n, 0, 1, -24, 24);
    let alpha = map(abs(wav), 0, 24, 110, 45);
    stroke(210, 210, 220, alpha);
    strokeWeight(3 + 2 * noise(i * 0.06));
    line(i, y0 + wav, i + 4, y0 + map(noise((i+4) * 0.003, 140), 0, 1, -24, 24));
