    stroke(220, 225, 235, baseAlpha);
    strokeWeight(24 - k * 0.32);
    for (let x = 0; x <= width; x += 16) {
      let nx = x * 0.004 + k * 0.08;
      let ny = k * 0.032;
      let y = veilY + noise(nx, ny) * 160 * map(k,0,48,1,0.4);
      curveVertex(x, y);
    }
    endShape();
  }
}

function drawSilhouettes() {
  // Abstracted dissolving form, center
  push();
  translate(width/2, height * 0.75);
  let mainR = 185;
  for (let s = 0; s < 3; s++) {
    let points = [];
    let off = random(1000);
    let dissolve = map(s, 0, 2, 0.87, 1.21);
    for (let t = 0; t < TWO_PI; t += PI / 42) {
      let n = noise(cos(t)*0.5 + 888 + off, sin(t)*0.5 + 20 + off, s*0.6+0.5);
      let r = mainR * dissolve * map(n, 0, 1, 0.79, 1.19);
      let yy = sin(t) * r;
      let xx = cos(t) * r;
      points.push([xx, yy]);
    }
    noStroke();
    fill(40,40, 52, map(s, 0, 2, 197,  35));
    beginShape();
    for (let i = 0; i < points.length; i++) {
      curveVertex(points[i][0]*1.08, points[i][1]);
    }
    endShape(CLOSE);
  }
  // Dissolving fringe at edges
  for (let i = 0; i < 70; i++) {
    let ang = random(TWO_PI);
    let rr = mainR * 1.19 + random(7, 42);
    let ex = cos(ang) * rr + random(-7,7);
    let ey = sin(ang) * rr + random(-7,7);
    let w = random(4, 18);
    let h = random(22, 50);
    let a = map(h, 22, 50, 43, 3);
    fill(60, 60, 84, a);
    noStroke();
    ellipse(ex, ey, w, h);
  }
  pop();
}

function drawFlowingLight() {
  // Gentle upward arcs above silhouette, hints of movement
  let xMid = width / 2;
  let yBase = height * 0.75 - 40;
  for (let i = 0; i < 33; i++) {
    let off = random(600);
    let len = random(170, 640);
    let yEnd = yBase - random(120, 255) - i*2;
    let xStart = xMid + random(-44,44);
    let xEnd = xStart + random(-len*0.19, len*0.19);
    let c = lerpColor(color(198,201,255, 85), color(229,223,252,13), i/33);
    stroke(c);
    strokeWeight(map(i, 0, 33, 7, 1.2));
    noFill();
    beginShape();
    for (let d = 0; d <= 1; d += 0.04) {
      let y = lerp(yBase, yEnd, d) - 17 * sin(TWO_PI * d + off) * (1-d);
      let x = lerp(xStart, xEnd, d) + 21 * sin(PI * d + off) * (1-d);
      curveVertex(x, y);
    }
    endShape();
  }
}

