  // Paint dark, subtle radial gradient with soft noise
  for (let y = 0; y < height; y += 2) {
    for (let x = 0; x < width; x += 2) {
      let dx = x - width/2;
      let dy = y - height*0.62;
      let distNorm = sqrt(dx*dx + dy*dy) / (width * 0.62);
      let n = noise(x*0.001, y*0.001) * 0.12 + 0.92;
      let base = lerp(9, 38, distNorm) * n;
      fill(base, base, base+7, 80);
      noStroke();
      rect(x, y, 2, 2);
    }
  }
}

function drawShapes() {
  // Draw the dissolving oval ('threshold')
  push();
  translate(width/2, height*0.62);
  let rW = 520;
  let rH = 950;
  noStroke();
  for (let k = 0; k < 140; k++) {
    let t = k/139;
    let alpha = pow(1-t,1.35);
    fill(206, 207, 209, 19 * alpha);
    blobShape(rW*lerp(1.09, 0.88, t), rH*lerp(1.06, 0.8, t), 0.18 * t + 0.04, 56 - t*41);
  }
  // Core – a glowing misty pale center
  for (let j = 0; j < 180; j++) {
    let t = 1-j/179;
    fill(255, 255, 240, 18*t*t);
    ellipse(0, 40, rW*0.57*t+100, rH*0.21*t+60);
  }
  pop();
}

function drawRays() {
  // Light rays: breaking through the threshold, signifying the unknown
  push();
  translate(width/2, height*0.62);
  for (let i = -4; i <= 4; i++) {
    let angle = map(i, -4, 4, -PI/3.3, PI/2.8) + random(-0.06, 0.05);
    let len = random(800,1400);
    let w = random(49, 184) * (1-abs(i)/5);
    let c = color(255,255,233, 20 + random(12,26));
    noStroke();
    push();
    rotate(angle);
    beginShape();
    fill(c);
    vertex(-w*0.055, 0);
    bezierVertex(-w*0.3, len*0.25, -w*0.15, len*0.81, 0, len);
    bezierVertex(w*0.15, len*0.81, w*0.3, len*0.25, w*0.055, 0);
    endShape(CLOSE);
    pop();
  }
  pop();
}

function blobShape(rw, rh, nudge, detail=65) {
  beginShape();
  for (let i = 0; i < detail; i++) {
    let ang = map(i, 0, detail, 0, PI*2);
    let nr = 1 + 0.17 * noise(cos(ang)*1.4 + nudge, sin(ang)*1.2 + nudge, frameCount*0.0005);
    let rx = rw * nr * cos(ang);
    let ry = rh * nr * sin(ang);
    vertex(rx, ry);
  }
  endShape(CLOSE);
}

function drawDissolution() {
  // Dissolving/cascading particles (form disintegrating & reforming at the threshold)
  let cx = width/2;
  let cy = height*0.62 + 200;
  for (let j = 0; j < 3700; j++) {
    let t = random();
    let a = random(TWO_PI);
    let rad = pow(random(), 0.62)*660 + 20;
    let rx = cos(a) * rad * lerp(1, 1.27, t);
    let ry = sin(a) * rad * lerp(1, 1.09, t) + random(-27,27);
    let p = map(ry, -400, 700, 0, 1);
    let sz = lerp(1.3, 6.5, pow(random(),2));
    let c = lerpColor(color(230,230,238, 19), color(20+10*t,22+4*t,30, 53-p*49), p);
    let px = lerp(cx, cx+rx, 0.97+0.04*random());
    let py = lerp(cy-90, cy+ry, 0.99+0.04*random());
    noStroke();
    fill(c);
    ellipse(px, py, sz + 2 * random(), sz + random(-1,2));
  }
}

