  for (let y = 0; y < height; y++) {
    let t = map(y, 0, height, 0, 1);
    let c1 = color(14, 24, 54);
    let c2 = color(205, 201, 191);
    let c = lerpColor(c1, c2, pow(t, 0.85));
    stroke(c);
    line(0, y, width, y);
