}

function drawPortal() {
  // Soft, glowing threshold in the center
  let cx = width/2, cy = height/2 + 180;
  let rx = 420, ry = 680;
  for (let i = 0; i < 100; i++) {
    let f = i / 100;
    let col = lerpColor(
      color(255, 255, 255, 12),
      color(220, 235, 240, 0),
      f
    );
    noFill();
    stroke(col);
    strokeWeight(30 - 28 * f);
    ellipse(cx, cy, rx + i*6, ry + i*12);
  }
  // Subtle light bleed
  for (let i = 0; i < 70; i++) {
    let alpha = map(i,0,69,28,0);
    fill(255,255,240, alpha * 0.5);
