function drawMist() {
  // Mist/energy flows, ambiguous, dissolving at the lower edge of the portal
  for (let k = 0; k < 1150; k++) {
    let ang = noise(k*0.036, k*0.0012+10) * TWO_PI * 1.7;
    let r = sqrt(random())*370 + 150;
    let px = width/2 + r*cos(ang);
    let py = height/2 + 360 + r*0.65*sin(ang) + random(-29,24);
