function drawFigures() {
  // Dissolving, partial forms near the threshold—neither fully material nor gone
  let fgCenters = [
    [width/2-120, height/2+450, 84],
    [width/2+135, height/2+405, 63],
    [width/2+6, height/2+277, 100],
  ];
  // Outlines & heads
  for (let i=0; i<fgCenters.length; i++) {
    let [x, y, h] = fgCenters[i];
