        if (t < PI+QUARTER_PI) vertex(nx, ny);
      }
      endShape();
    }
    // Head (partial, dissolving edge)
    for (let j=0; j<10; j++) {
      let rad = 28 - 1.5*j + 6*noise(i+j*1.9);
      fill(255,255,255, fade-9*j);
      stroke(210,220,240, fade-24*j);
      strokeWeight(2.7-j*0.17);
      ellipse(x, y-h*0.36 + 3*noise(i+j*0.72), rad, rad*0.98);
    }
    // Smeared lower edge, blending into mist
    for (let k=0; k<24; k++){
      let tx = x + random(-28,28) + 5*noise(k*0.7+i*9.2+4);
      let ty = y + h*0.44 + random(8,75)*noise(k*.99+i*1.6);
