// The Silence Between Waves
function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Background: gradient fading to darkness
  for (let y = 0; y < height; y++) {
    let c1 = color(20, 22, 35);   // Near-black indigo
    let c2 = color(230, 242, 255, 80); // Faded blue
    let inter = map(y, 0, height * 0.7, 0, 1);
    if (y > height * 0.7) inter = 1;
    let c = lerpColor(c2, c1, inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Distant "shoreline" arc: the departing edge of life
  noFill();
  stroke(40, 80, 110, 120);
  strokeWeight(5);
  arc(width / 2, height * 0.85, width * 1.2, 600, PI, TWO_PI);

  // Fainter secondary arc: vanishing memory
  stroke(70, 160, 220, 18);
  strokeWeight(2.5);
  arc(width / 2, height * 0.87, width * 1.25, 570, PI, TWO_PI);

  // Ethereal undulating waves—transitions
  for (let i = 0; i < 7; i++) {
    let baseY = height * 0.15 + i * 113 + noise(i) * 22;
    let amp = 34 + noise(i * 4.23) * 44;
    let freq = 0.0027 + i * 0.00054;
    let op = 60 - i * 5;
    stroke(180, 210, 235, op);
    strokeWeight(2.6 - i * 0.18);
    noFill();
    beginShape();
    for (let x = 0; x <= width; x += 8) {
      let y = baseY + sin(x * freq + noise(i, x * 0.0003) * PI) * amp * noise(i + x * 0.0002);
      curveVertex(x, y);
    }
    endShape();
  }

  // Dissolving shapes: the fading of presence
  for (let i = 0; i < 54; i++) {
    let t = i / 53;
    let cx = width / 2 + random(-430, 430) * pow(1 - t, 2.5);
    let cy = height * (0.26 + 0.34 * t) + random(-30, 24);
    let r = random(39, 90) * pow(1 - t, 0.7);
    let a = 140 * pow(1 - t, 1.5);
    noStroke();
    fill(220, 225, 252, a);
    ellipse(cx, cy, r, r * random(0.78,1.2));
  }

  // Central void: formlessness
  let voidRad = 300;
  for (let k = 0; k < 62; k++) {
    let rad = voidRad * (0.85 + k * 0.008);
    fill(18, 16, 32, map(k, 0, 61, 150, 30));
    noStroke();
    ellipse(width / 2, height * 0.55, rad, rad * random(1.05,1.13));
  }

  // Subtle inner glow, hinting at continuity
  for (let i = 0; i < 60; i++) {
    let rr = voidRad * 0.65 + i * 2.2;
    let alpha = map(i, 0, 59, 14, 0);
    fill(90, 150, 230, alpha);
    noStroke();
    ellipse(width / 2, height * 0.55, rr, rr);
  }

  // Faint stars—possibility
  for (let s = 0; s < 170; s++) {
    let ang = random(TWO_PI), d = random(width * 0.13, width * 0.49);
    let sx = width / 2 + cos(ang) * d;
    let sy = height * 0.07 + sin(ang) * (height * 0.21);
    fill(230, 245, 252, random(20, 60));
    noStroke();
    ellipse(sx, sy, random(2, 6), random(1, 7));
    if (random() < 0.13) {
      // Tiny trailing glow
      fill(200, 225, 255, 12);
      ellipse(sx, sy, random(11, 22), random(3, 13));
    }
  }
}

