function drawShroud(cx, cy, sz) {
  noStroke();
  for (let l = 0; l < 60; l++) {
    let alpha = 13 + (.8*l);
    fill(50+l*3, 50+l*3, 70+l*4, alpha);
    beginShape();
    for (let a = PI*1.12; a < PI*1.88; a += 0.07) {
      let r = sz * (0.75 + noise(a*0.7 + l*0.05)*0.26 + l/120);
      let x = cx + cos(a)*r;
      let y = cy + sin(a)*r*1.08;
      curveVertex(x, y);
    }
    for (let a = PI*1.88; a > PI*1.12; a -= 0.11) {
      let r = sz * (0.47 + noise(a*0.7 + l*0.09)*0.3 + l/180);
      let x = cx + cos(a)*r;
      let y = cy + sin(a)*r*1.12 + 180; // bas
      curveVertex(x, y);
    }
    endShape(CLOSE);
  }
  // visage suggéré
  fill(222, 222, 245, 9);
  ellipse(cx, cy-80, 70, 72);
  fill(172, 172, 198, 16);
  ellipse(cx, cy-90, 43, 51);
}

function drawRiver(cx, yBase, rw, rh, nW) {
  for (let j = 0; j < 48; j++) {
    beginShape();
    let fade = 120 - j*2.1;
    noStroke();
    fill(230, 225, 120, fade);
    for (let i = 0; i <= nW; i+=1) {
      let t = i/nW;
      let angle = PI/2 * (1-t) - QUARTER_PI*.45*noise(j*0.1 + i*0.03, j*0.09);
      let x = cx + lerp(-rw/2, rw/2, t) + sin(angle)*23*noise(j*0.12, i*0.1);
      let y = yBase + rh*(pow(t,1.15)) + random(-1,1) + 11*noise(j*.18, i*0.13);
      vertex(x, y + j*8 + 8*noise(j*.21, i*0.14));
    }
    for (let i = nW; i >= 0; i-=1) {
      let t = i/nW;
      let angle = PI/2 * (1-t) + QUARTER_PI*.38*noise(j*0.23 + i*0.09, j*0.06);
      let x = cx + lerp(-rw/4.3, rw/4.3, t) + sin(angle)*7;
      let y = yBase + rh*pow(t,1.11) + 8*noise(j*.13, i*0.11) ;
      vertex(x, y + j*14.6);
    }
    endShape(CLOSE);
  }
}

function drawOrbs(count, cx, cy, rw, rh) {
  for (let i = 0; i < count; i++) {
    let ang = random(PI*0.04, PI*0.96);
    let r = random(rw*0.40, rw*0.96);
    let x = cx + cos(ang)*r*(0.55 + random(-0.05, 0.05));
    let y = cy + sin(ang)*(rh*0.65 + random(-12,15));
    let sz = random(29, 52) * (0.8 + random(0.22));
    let colFade = lerpColor(color(240,221,180,27), color(110,130,210,33), random());
    noStroke();
    for (let j = 4; j > 0; j--) {
      fill(red(colFade), green(colFade), blue(colFade), 16-j*3);
      ellipse(x+random(-2,2), y+random(-2,2), sz*j*0.137, sz*j*0.161);
    }
  }
}

function drawTrees(count, center, y, spread, baseSize) {
  for (let i = 0; i < count; i++) {
    let x = center + spread*noise(i*1.2) - spread/2 + random(-32, 32);
    let h = random(188, 320) * lerp(0.7, 1.3, noise(i*0.42));
    let col = lerpColor(color(38,27,41, 90), color(82,76,112, 75), noise(i*0.36));
    drawTree(x, y, h, baseSize*noise(i*0.51), col);
  }
}

function drawTree(x, y, h, w, trunkCol) {
  push();
  stroke(trunkCol); strokeWeight(w*0.23);
  line(x, y, x, y-h);
  // Branches
  let nb = int(random(3,5));
  for (let i = 0; i < nb; i++) {
    let by = y-h*random(0.28, 0.82);
    let dir = random(-PI/3, PI/3);
    let bl = h*random(0.19, 0.41);
    let bx = x + cos(dir)*bl;
    strokeWeight(w*random(0.04, 0.19));
    line(x, by, bx, by-bl/1.9);
  }
  pop();
}

