    ellipse(width / 2, height * 0.11 + r * 18, width * 1.78 - r * 42, 240 - r * 8);
  }

  // Lignes fines — fil de la vie qui se dissout
  stroke(50, 32, 22, 27);
  strokeWeight(2.1);
  for (let l = 0; l < 15; l++) {
    let t0 = 0.33 + 0.34 * l / 14 + random(-0.027, 0.027);
    let x0 = width / 2 + random(-8, 8);
    let y0 = height * t0 + random(-14, 14);
    beginShape();
    for (let t = 0; t < 1.001; t += 0.03) {
      let a = map(t, 0, 1, -PI / 4, PI / 4);
      let x = x0 + 240 * t * noise(l, t * 1.99) * sin(a + l);
      let y = y0 + t * 490 * sin(a + t * 0.9 + l) + 25 * noise(l * 2, t * 1.2);
      curveVertex(x, y);
    }
    endShape();
  }
}

// The Last Embrace
function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  drawBackground();
  drawVortex();
  drawFigures();
  drawPetals();
}

function drawBackground() {
  for (let y = 0; y < height; y += 2) {
    let c = lerpColor(color(255,247,233), color(23,22,36), pow(map(y,0,height, 0,1),1.3));
    stroke(c);
    line(0, y, width, y);
  }
  for (let i=0; i<1200; i++) {
    let x = random(width);
    let y = random(height);
    let a = random(120,180);
    let s = random(10,40);
    noStroke();
    fill(255, 255, a, 15);
    ellipse(x,y,s,s);
  }
}

function drawVortex() {
  push();
  translate(width/2, height/2 + 150);
  let layers = 19;
  for (let l=layers; l>=1; l--) {
    let ratio = l/layers;
    let c = lerpColor(color(230,200,160,50), color(30,30,60,180), pow(ratio, 1.6));
    let r1 = map(l,1,layers, 220, 740);
    let r2 = r1 * map(noise(l*0.1+1),0,1, 0.80,1.18);
    noFill();
    strokeWeight(map(l,1,layers, 48,1));
    stroke(c);
    beginShape();
    for (let t=0; t<TWO_PI; t+=PI/180) {
      let rr = r2 + noise(t*2+l*4)*35*ratio;
      let tx = cos(t+ratio*2) * rr*1.1;
      let ty = sin(t-ratio*1.5) * rr*0.9;
      curveVertex(tx, ty);
    }
    endShape(CLOSE);
  }
  pop();
}

function drawFigures() {
  // Lying figure (death)
  push();
  translate(width/2 - 150, height/2 + 800);
  fill(35,34,51, 235);
  noStroke();
  beginShape();
  for (let i=0; i<=1; i+=0.005) {
    let x = lerp(0, 390, i) + sin(i*PI)*35;
    let y = 60*sin(i*PI) + 70*pow(i,2.7);
    if (i < 0.2) y += sin(i*12)*19*(1.0-i);
    if (i > 0.83) y -= 18*pow(map(i,0.83,1,0,1),1.7);
    vertex(x, y);
  }
  for (let i=1; i>=0; i-=0.005) {
    let x = lerp(0, 390, i) + 20 + cos(i*HALF_PI)*17 + i*7;
    let y = 168 + 37*cos(i*PI) - 50*pow(i,1.4) + sin(i*8)*8*(i);
    vertex(x, y);
  }
  endShape(CLOSE);
  // Head
  fill(56,58,92, 248);
  ellipse(50,34,77,93);
  pop();

  // Embracing spirit
  push();
  translate(width/2 + 10, height/2 + 730);
  let baseY = 0;
  noFill();
  stroke(220,205,230, 180);
  strokeWeight(22);
  for (let t=0; t<PI*1.05; t+=0.025) {
    let x = cos(t-0.4)*150 + sin(t*3.5)*8 + 40;
    let y = sin(t-0.5)*220 - t*26 + cos(t*5)*4 + baseY;
    line(x, y, x+cos(t-0.48)*37, y+sin(t-0.48)*29);
  }
  // Head (spirit)
  fill(238,233,248, 180);
  noStroke();
  ellipse(82, -47, 59, 68);
  pop();

  // Hand embracing
  push();
  translate(width/2 - 64, height/2 + 860);
  noFill();
  stroke(225,211,222, 190);
  strokeWeight(12.5);
  beginShape();
  for (let t=0; t<PI/2; t+=0.04) {
    let x = cos(t+0.7)*67 + 55 + noise(t*6)*5;
    let y = sin(t+0.7)*34 + 29 + noise(t*4)*8;
    curveVertex(x, y);
  }
  endShape();
  pop();
}

function drawPetals() {
  let c1 = color(255,235,210, 146);
  let c2 = color(90,23,42, 91);
  for (let i=0; i<19; i++) {
    let x = width/2 + random(-310, 310);
    let y = height/2 + 410 + random(-70,240);
    let a = random(TWO_PI);
    let s = random(43,106);
    push();
    translate(x,y);
    rotate(a);
    for (let j=0; j<6; j++) {
      let r = s*random(0.77,1.12);
      let c = lerpColor(c1, c2, random(0.14,0.44));
      fill(c);
      noStroke();
      beginShape();
      for (let k=0; k<TWO_PI; k+=PI/30) {
        let rr = r*noise(cos(k)*0.5+1, sin(k)*0.4+2, j*1.1)*map(sin(k),-1,1,0.23,1);
        let vx = cos(k) * rr * (0.76 + j*0.06);
        let vy = sin(k) * rr * (1 -j*0.04);
        curveVertex(vx, vy);
      }
      endShape(CLOSE);
      rotate(PI/3);
    }
    pop();
  }
}

function setup() {
