    }
    for(let i=nsteps-1;i>=0;i--){
      let t = i/(nsteps-1);
      let wx = sin(TWO_PI*(t+random(-0.02,0.02)))*amp*map(t,0,1,1,0.1)+ noise(i*0.17+10,j*0.12+10)*18;
      vertex(x0+wx+random(-4,4), y0+len*t+random(6,20));
    }
    endShape(CLOSE);
  }
  // Silhouette pâle au seuil
