    let cy = height*0.55 + random(-350,500);
    let rx = random(80,180);
    let ry = rx*random(0.33,1.3);
    let col = color(43,44,46, random(31,70));
    fill(col);
    let rot = random(-PI/3,PI/3);
    push();
    translate(cx,cy);
    rotate(rot);
    beginShape();
    for(let a=0;a<TWO_PI;a+=PI/20){
      let rrx = rx*0.92 + noise(a*2+cx,cy)*rx*0.08 + random(-3,3);
      let rry = ry*0.92 + noise(a*2+cy,cx)*ry*0.08 + random(-3,3);
      vertex(cos(a)*rrx,sin(a)*rry);
    }
    endShape(CLOSE);
    pop();
  }
  // Grains de lumière fine (le peu qui traverse)
  for(let k=0;k<550;k++){
