}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();

  // Background : deep blue-black fade to charcoal, vertical
  for (let y = 0; y < height; y++) {
    let c = lerpColor(color(14, 16, 32), color(35, 37, 44), y / height);
    stroke(c);
    line(0, y, width, y);
  }

  // Wisps (translucent veils)
  for (let i = 0; i < 45; i++) {
    let x0 = random(width * 0.15, width * 0.85);
    let y0 = random(height * 0.1, height * 0.85);
    let total = floor(random(24, 38));
    let diam = random(160, 360);
    let angleOff = random(TWO_PI);
    let col = color(190, 190, 220, 28 + random(12, 38));
    noFill();
    stroke(col);
    strokeWeight(random(3, 8));
    beginShape();
    for (let t = 0; t < total; t++) {
      let pct = t / (total - 1);
      let r = diam * (1 + 0.20 * noise(x0 * 0.001 + pct * 0.7, y0 * 0.001 - pct * 0.4, i)) + sin(angleOff + pct * TWO_PI) * 22;
      let ang = angleOff + pct * PI + sin(i + t * 0.14) * 0.15;
      let x = x0 + cos(ang) * r;
      let y = y0 + sin(ang) * r;
      curveVertex(x, y);
    }
    endShape();
  }

  // Soft central void (the "threshold")
  for (let r = 400; r > 10; r -= 3) {
    let alpha = map(r, 400, 10, 110, 5);
    let edgeCol = lerpColor(color(255,240,240, alpha), color(240, 230, 220, alpha*0.7), r/400);
    noStroke();
    fill(edgeCol);
    ellipse(width/2, height*0.56, r*2 * 1.06, r*2 * 0.96);
  }

  // Subtle star-like specks within "void"
  for (let i = 0; i < 120; i++) {
    let rr = random(0, 185);
    let theta = random(TWO_PI);
    let x = width/2 + cos(theta) * rr * 1.03;
    let y = height*0.56 + sin(theta) * rr * 0.95;
    noStroke();
    fill(255, 254, 235, random(80,155));
    ellipse(x, y, random(3,7), random(1,3));
  }

  // Faint horizon line suggesting limit/passage
  for (let o = 0; o < 19; o++) {
    let y = height*0.70 + o*2 - 8; // center
    stroke(170, 165, 180, 80 - o*4);
    strokeWeight(4.5 - o*0.2);
    line(width*0.24, y, width*0.76, y + random(-3,3));
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
