  for (let y = 0; y < height; y++) {
    let t = pow(y / height, 1.9);
    let c = lerpColor(color(20, 20, 30), color(240, 235, 225), t);
    stroke(c);
    line(0, y, width, y);
  }

  // "Voile" : brumes semi-transparentes superposées, comme des flux d'encre
  for (let k = 0; k < 18; k++) {
    let phase = random(PI);
    let alpha = map(k, 0, 17, 38, 15);
    let xoff = random(400, 1200);
    let yoff = random(200, 500);
    let col = lerpColor(
      color(80, 78, 110, alpha),
      color(220, 215, 200, alpha * 0.8),
      k / 17
    );
    noFill();
    stroke(col);
    strokeWeight(map(k, 0, 17, 230, 50));
    beginShape();
    for (let x = -150; x < width + 150; x += 16) {
      let nx = x * 0.00082 + phase;
      let y = height * 0.18 + k * 90 +
        noise(nx, phase + 1.5 * k) * 170 +
        map(sin(phase + x * 0.0009 + k), -1, 1, -30, 45);
      vertex(x + map(noise(x, k), 0, 1, -22, 22), y+map(noise(x*0.12, k),0,1,-10,20));
    }
    endShape();
  }

  // "Contours dissous" : traces-fils obliques, estompés sur la moitié inférieure
  for (let i = 0; i < 170; i++) {
    let x1 = random(80, width-80);
    let y1 = random(height*0.45, height*0.99);
    let len = random(140, 600);
    let angle = random(PI/5, (PI/5)*4);
    let x2 = x1 + len * cos(angle);
    let y2 = y1 + len * sin(angle)*random(0.91,1.1);
    stroke(lerpColor(color(220,210,180,18), color(40,30,60,45), random()));
    strokeWeight(random(2, 6));
    line(x1, y1, x2, y2);
