    let cx = width * random(0.28,0.75);
    let cy = height * random(0.56, 0.89);
    let baseR = random(120, 430);
    for (let j = 0; j < 6; j++) {
      let rr = baseR * pow(1.16, j);
      noFill();
      stroke(lerpColor(color(80,70,120,19), color(240,225,210,12), j / 5.0));
      strokeWeight(map(j,0,5,17,7));
      ellipse(cx + random(-30,30), cy + random(-30,30), rr, rr * random(0.91,1.09));
    }
  }

  // "Flux d'oubli": filaments pruinés en haut et milieu
  for (let i = 0; i < 22; i++) {
    let y0 = random((height*0.13),(height * 0.56));
    let x0 = map(i, 0, 21, 80, width-80) + sin(i) * 53;
    let len = random(190,400);
    stroke(220, 218, 220, 13+5*noise(i));
    strokeWeight(random(13,28));
    for(let j=0;j<25;j++){
      let frac = j/24;
      let x = x0 + sin(frac*PI*2 + i)*len*0.1*frac + random(-10,10);
      let y = y0 + frac*len + noise(i,j)*19;
      point(x,y);
    }
  }

  // "Portes aveugles" : taches pâles, évoquant des seuils
  for(let i=0; i<5; i++){
    let cx = width*random(0.40,0.65)+random(-30,30);
    let cy = height*random(0.26,0.81);
    let rr = random(60,160)+random(0,170);
    noStroke();
    fill(220,230,224,78);
    ellipse(cx,cy,rr, rr*random(0.85,1.14));
  }
}

