    pop();
    // Fils évanescents attachés à la trace
    stroke(0.93,0.79,0.33, 0.03+random(0.03));
    strokeWeight(random(1,2.4));
    noFill();
    let tails=random(2,4);
    for(let t=0;t<tails;t++){
      beginShape();
      let steps = int(random(4,8));
