    let sz = random(140, 340);
    let c = color(0,0,0,0.14 * random(0.9,1));
    noStroke();
    fill(c);
    ellipse(cx, cy, sz*random(1,1.3), sz*random(0.19,0.29));
  }

  // Un dernier voile très fin, ambiance froide-transparente
  for (let y = 0; y < height; y += 7){
    let alpha = 0.012*map(y,height*0.33,height,1,0,true);
    stroke(0.8,0.87,1, alpha);
    line(0, y, width, y);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
  drawBackground();
  drawVeil();
  drawShapesOfLife();
  drawMist();
  drawLight();
}

function drawBackground() {
  for (let y = 0; y < height; y++) {
    let c = lerpColor(color('#090E1B'), color('#EFE9DF'), y/height);
    stroke(c);
    line(0, y, width, y);
  }
}

function drawVeil() {
  push();
  let cx = width/2, cy = height/2;
  for (let i=0; i<55; i++) {
    let off = map(i,0,54,0,255);
    let veil = color(20+off,22+off*0.5,46+off*0.3, 14+off*0.45);
    noStroke();
    fill(veil);
    ellipse(cx, cy+70, 850+20*i, 1400+43*i);
  }
  pop();
}

function drawShapesOfLife() {
  let colors = [
    color('#BCE6D8'),
    color('#E1CCEC'),
    color('#CF7C5C'),
    color('#E5E32E'),
    color('#2E61A8'),
    color('#E678AB'),
    color('#74B070'),
    color('#DCE5EC'),
    color('#A7A0D4')
  ];

  let shapes = 8;
  for (let i=0; i<shapes; i++) {
    let ang = random(-PI/7, PI/7) + map(i,0,shapes-1,-PI/5,PI/5);
    let r = random(300,560);
    let cx = width/2 + cos(ang) * r * random(0.85,1);
    let cy = height/2 + sin(ang) * r * random(0.9,1.1) + random(-120,30);
    let sz = random(220, 420);
    let col = colors[i%colors.length];
    let rot = random(-PI/8, PI/8);

    push();
    translate(cx, cy);
    rotate(rot);
    noStroke();
    fill(lerpColor(col, color(40,44,70,90), 0.15 * i));
    beginShape();
    for (let t=0; t<TWO_PI; t+=PI/25) {
      let nr = sz * (0.54 + 0.44*noise(100 + 4*i + cos(t)*0.9, sin(t)*0.9));
      vertex(nr*cos(t), nr*sin(t));
    }
    endShape(CLOSE);
    pop();
  }
}

function drawMist() {
  noStroke();
  for (let i=0; i<155; i++) {
    let x = width/2 + random(-600,600);
    let y = height/2 + 50 + random(-650,650);
    let s = random(60,290);
    let alpha = map(i,0,99,28,6) * random(0.5, 1);
    fill(240,242,249, alpha);
    ellipse(x, y, s*random(0.7,1.2), s*random(0.6,1));
  }
}

function drawLight() {
  for (let i=0; i<5; i++) {
    let s = 720 + i*60;
    let alpha = 32-i*5;
    fill(255,248,236, alpha);
    noStroke();
    ellipse(width/2, height*0.16 + 60, s, s*0.72);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  // Background: pale wilderness with subtle gradients
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let col = lerpColor(color(215, 226, 235), color(165, 175, 178), inter);
    stroke(col);
    line(0, y, width, y);
  }

  // Faint hills in distance
  noStroke();
  for (let l = 0; l < 6; l++) {
    let baseY = 1000 + l * 100;
    let col = lerpColor(color(180, 190, 200, 50), color(160, 168, 173, 60), l/7);
    fill(col);
    beginShape();
    vertex(0, height);
    for (let x = 0; x <= width; x += 10) {
      let yoff = noise(x*0.002 + l*50, l*42.4) * 120 * (0.7+0.1*l);
      vertex(x, baseY + yoff + l*15);
    }
    vertex(width, height);
    endShape(CLOSE);
  }

  // Central fading figure
  let centerX = width/2;
  let centerY = 1280;
  push();
  translate(centerX, centerY);
  for(let t = 0; t < 70; t++){
    let alpha = map(t,0,69,18,120);
    fill(200, 222, 255, alpha);
    beginShape();
    for(let a=0; a<TWO_PI; a+=PI/32){
      let r = 170 + noise(cos(a)*0.7+t*0.13, sin(a)*0.7+t*0.13, t*0.1)*45 - t*2.3;
      vertex(cos(a)*r*0.7, sin(a)*r*1.7-t*6); // head, body
    }
    endShape(CLOSE);
  }
  // Arms
  stroke(220,255,255,90);
  strokeWeight(27);
  line(-60, 50, -120, 220);
  line(60, 50, 120, 210);
  // Lower
  noStroke();
  for (let i=0;i<10;i++){
    fill(210,215,225,26);
    ellipse(0,240+i*10,95-i*5,60-i*4);
  }
  pop();

  // Shadow merging with ground
  push();
  translate(centerX, centerY+210);
  for(let i=0;i<28;i++){
    fill(50,63,92,18-i*0.5);
    ellipse(0,15+i*5,320-i*10,38+i*7);
  }
  pop();

  // Black organic branches encroaching
  for (let b = 0; b < 13; b++) {
    drawBranch(
      random([false,true]) ? random(100,500) : random(width-500,width-100),
      random(1500,1900),
      centerX + random(-80,80),
      centerY + random(190, 260),
      random(8,19),
      b % 2 === 0 ? color(30,28,45,120) : color(12,13,22,90),
      random(0.9,1)
    );
  }

  // Subtle fog
  for (let f = 0; f < 25; f++) {
    fill(255,255,255,8+f*0.7);
    ellipse(width/2 + random(-620,620), 1550+random(-100,150), random(210,380), random(45,120));
  }

  // Distant faded birds—departure
  stroke(80,110,128,55);
  strokeWeight(2);
  noFill();
  for (let i=0;i<8;i++) {
    let bx = random(width*0.2,width*0.8);
    let by = random(430,800);
    let s = random(38,70);
    beginShape();
    for (let t=0; t<=PI; t+=PI/18) {
      let rx = map(t,0,PI,-s,s);
      let ry = sin(t)*s*0.35;
      vertex(bx+rx, by+ry);
    }
    endShape();
  }
}

function drawBranch(x1, y1, x2, y2, n, col, scale=1) {
  let cx = x1, cy = y1;
  stroke(col);
  strokeWeight(15*scale);
  noFill();
  for (let i = 0; i < n; i++) {
    let t = i / n;
    let nx = lerp(x1, x2, t) + sin(t*PI*1.2)*40*random(0.65,1.15)*scale;
    let ny = lerp(y1, y2, t) + cos(t*PI*1.6)*32*random(0.82,1.15)*scale;
    line(cx, cy, nx, ny);
    cx = nx, cy = ny;
    strokeWeight(lerp(15,7,i/n)*scale);
  }
  for (let j=0;j<random([2,3,4]);j++) {
    let t = random(0.6,1);
    let nx = lerp(x1, x2, t) + sin(t*PI*1.2)*36*scale;
    let ny = lerp(y1, y2, t) + cos(t*PI*1.6)*28*scale;
    strokeWeight(lerp(8,4,j/3)*scale);
    line(cx, cy, nx, ny);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
  background(30);

  // Draw ground fading upwards
  for (let y = height; y > height * 0.35; y -= 2) {
