    );
  }
}

// Tree branch recursive
function branch(x, y, angle, len, depth) {
  if (depth < 1) return;
  let x2 = x + cos(angle) * len;
  let y2 = y + sin(angle) * len;
  strokeWeight(map(depth, 1, 8, 1, 19));
  stroke(40 + depth * 3, 40 + depth * 2, 45 + depth * 1);
  line(x, y, x2, y2);
  if (depth > 2 && random() < 0.9) {
    branch(x2, y2, angle + random(-PI/5, -PI/11), len * random(0.66, 0.78), depth - 1);
    branch(x2, y2, angle + random(PI/15, PI/4), len * random(0.43, 0.64), depth - 2);
  } else if (depth > 1) {
    branch(x2, y2, angle + random(-PI/15, PI/15), len * 0.7, depth - 1);
  }
}

// Draw translucent ghostly spirit
function drawSpirit(cx, cy, w, h, alphaFac) {
  push();
  translate(cx, cy);
  for (let l = 0; l < 48; l++) {
    let alph = 20 + 180 * pow(0.65, l) * alphaFac;
    let xx = 0 + random(-13, 13), yy = 0 + random(-19, 19);
    noStroke();
    fill(240, 241, 245, alph);
    ellipse(xx, yy+h*0.19, w*0.57, h*0.73); //lower body
    ellipse(xx, yy-h*0.19, w*0.41, h*0.47); //chest
    ellipse(xx, yy-h*0.38, w*0.23, h*0.18); //head
    fill(230, alph * 0.8);
    ellipse(xx-w*0.16, yy-h*0.14, w*0.33, h*0.19); //arm left
    ellipse(xx+w*0.13, yy-h*0.01, w*0.28, h*0.16); //arm right
  }
  pop();
}

// Feather shape
function drawFeather(x, y, h, angle, col) {
  push();
  translate(x, y);
  rotate(angle);
  noStroke();
  for (let i = 0; i < 25; i++) {
    let t = i / 24;
    let r = 15 * (1 - pow(t, 1.8)) + random(-1, 1.7);
    fill(col);
    ellipse(r, t * h, 24 * (1-t) + 6, 7 + 7 * pow(1-t,2));
    ellipse(-r, t * h, 24*(1-t)+6, 7 + 7 * pow(1-t,2));
  }
  // Shaft
  stroke(230, 230, 255, alpha(col)*0.7);
  strokeWeight(3.6);
  line(0, 0, 0, h);
  pop();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
