}

function draw() {
  // Background - gradient nightfall
  for (let y = 0; y < height; y++) {
    let t = map(y, 0, height, 0, 1);
    let c1 = lerpColor(color(250, 210, 170), color(80, 75, 130), t*0.6);
    let c2 = lerpColor(color(80, 75, 130), color(25, 30, 45), (t-0.5)*2);
    let c = (y < height*0.65) ? c1 : c2;
    stroke(c);
    line(0, y, width, y);
  }

  // Glowing orb (fading warmth)
  for (let r = 600; r > 0; r -= 2) {
    let alpha = map(r, 0, 600, 0, 70);
    fill(245, 202, 176, alpha);
    noStroke();
    ellipse(width * 0.56, height * 0.43, r, r*0.77);
  }

  // Trees - thin, leafless, uneven
  stroke(40, 36, 30);
  strokeWeight(7);
  for (let i = 0; i < 5; i++) {
    let x = width * 0.19 + i*width*0.13 + random(-30,30);
    drawTree(x, height * 0.95, -PI / 2, 300 + random(40, 60), 7);
  }

  // Distant branches (lower opacity)
  for (let i = 0; i < 6; i++) {
    let x = width * 0.16 + i*width*0.16 + random(-20,20);
    push();
    stroke(30, 29, 44, 80);
    strokeWeight(4);
    drawTree(x, height * 0.91, -PI / 2, 170 + random(0, 40), 5, 0.7);
    pop();
  }

  // Blackbird - shadow
  push();
  translate(width * 0.5, height * 0.54);
  scale(2.1);
  drawBird();
  pop();
}

function drawTree(x, y, angle, len, thick, fade=1) {
  if (len < 20) return;
  push();
  translate(x, y);
  rotate(angle);
  strokeWeight(thick * fade);
  stroke(40, 36, 30, 170*fade);
  line(0, 0, 0, -len);
  let nex = 0, ney = -len;
  for (let i = 0; i < int(random(1, 3)); i++) {
    let theta = random(-PI/6, PI/6);
    let newlen = len * random(0.62, 0.80);
    let newthick = thick * random(0.63, 0.85);
    drawTree(nex, ney, theta, newlen, newthick, fade*0.83);
  }
  if (len > 45 && random(1) < 0.22) {
    // Knob
    noStroke();
    fill(66, 52, 44, 95);
    ellipse(nex, ney, thick*2, thick*2);
  }
  pop();
}

function drawBird() {
  // Bird body
  push();
  stroke(20, 17, 24);
  strokeWeight(1.5);
  fill(20, 17, 24, 255);
  beginShape();
  vertex(0, 0);
  bezierVertex(-23, 25, -60, 40, -55, -5);
  bezierVertex(-55, -50, -22, -48, 8, -22);
  bezierVertex(25, -52, 55, -39, 52, 0);
  bezierVertex(48, 12, 35, 17, 17, 10);
  endShape(CLOSE);

  // Left wing
  beginShape();
  vertex(-10, -22);
  bezierVertex(-120, -95, -50, 44, -10, 8);
  bezierVertex(-26, -15, -45, -75, -10, -22);
  endShape(CLOSE);

  // Right wing (partially open)
  beginShape();
  vertex(12, -18);
  bezierVertex(85, -55, 45, 34, 13, 4);
  bezierVertex(29, -11, 45, -45, 12, -18);
  endShape(CLOSE);

  // Tail
  beginShape();
  vertex(-8, 17);
  bezierVertex(-18, 33, 0, 48, 17, 20);
  bezierVertex(11, 37, 11, 37, 3, 16);
  endShape(CLOSE);

  // Eye - subtle glint
  fill(235, 238, 246, 60);
  noStroke();
  ellipse(27, -13, 5, 3);
  pop();
}

