function drawDoor(x, y, w, h, a) {
  push();
  translate(x, y);
  rotate(a);
  // 门主体（淡灰色）
  stroke(94,91,89,160);
  strokeWeight(8);
  fill(220,217,212,240);
  rect(0, 0, w, h, 12);

  // 门敞开一半
  push();
  translate(w*0.97, 0);
  rotate(radians(-36));
  fill(26,22,29,230);
  stroke(58,48,50,210);
  strokeWeight(7);
  rect(0, 0, w*0.45, h, 20, 0, 0, 22);
  pop();

  // 门后黑暗部分（比门更深更黑）
  noStroke();
  fill(11,9,17, 180);
  rect(w*0.34, h*0.02, w*0.58, h*0.96, 20, 15, 15, 20);

  pop();
}

function drawCrow(x, y, s, a) {
  push();
  translate(x, y);
  scale(s);
  rotate(a);

  // 身体
  fill(8,8,16); noStroke();
  ellipse(0, 0, 38, 74);

  // 翅膀
  push();
  rotate(-PI/14);
  ellipse(-17, -13, 38, 38);
  pop();

  ellipse(-14, 13, 29, 25);

  // 头
  ellipse(0, -40, 25, 22);

  // 喙
  fill(32,29,27);
  beginShape();
  vertex(5, -44);
  vertex(32, -50);
  vertex(19, -39);
  endShape(CLOSE);

  // 眼睛
  fill(212,191,89); ellipse(11, -43, 4,2);
  pop();
}

function drawBranches(x, y, a, len, t, depth) {
  push();
  translate(x, y);
  rotate(a);
  stroke(36,29,18, 204);
  strokeWeight(t);
  if (depth > 0 && len > 14) {
    line(0, 0, 0, -len);
    let n = floor(random(2,4));
    for (let i = 0; i < n; i++) {
      let newA = random(-PI/2, PI/2)/1.2;
      let newL = len * random(0.51, 0.78);
      let newT = t * 0.68;
      push();
      translate(0, -len * random(0.7,0.96));
      drawBranches(0,0,newA,newL,newT,depth-1);
      pop();
    }
  }
  pop();
}

