    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(20, 20, 30), color(170, 170, 170), inter * 0.5);
    stroke(c);
    line(0, y, width, y);
  }

  // 画多层模糊的“门”
  let cx = width / 2;
  let cy = height / 2;
  for (let i = 9; i >= 0; i--) {
    let a = 0.45 + i * 0.025;
    let c1 = lerpColor(color(250, 250, 250, 90), color(40, 50, 70, 80), i / 10);
    fill(c1);
    noStroke();
    let rx = 470 + i * 29;
    let ry = 580 + i * 33;
    ellipse(cx, cy - 30, rx * 2, ry * 2);
  }

  // 混沌的雾感层次
  for (let n = 0; n < 6000; n++) {
    let ang = random(TWO_PI);
    let r = sqrt(random(1)) * 800;
    let x = cx + cos(ang) * r + noise(n * 0.01, 10) * 140 * sin(ang * 1.5 + n);
    let y = cy - 30 + sin(ang) * r * 1.1 + noise(n * 0.01, 20) * 80 * cos(n * 0.8);

    let d = dist(cx, cy, x, y);
    let f = 1 - constrain(map(d, 420, 800, 0, 1), 0, 1);
    let alp = 30 + 110 * pow(f, 2);
    let sz = random(2, 22) * pow(1 - f, 1.7);

    fill(200 + random(-30, 30), 210 + random(-40, 30), 220 + random(-50, 35), alp);
    noStroke();
    ellipse(x, y, sz, sz * random(0.6, 1.6));
  }

  // 门内的深色虚空
  for (let n = 0; n < 2600; n++) {
    let rr = random(0, 400);
    let t = random(TWO_PI);
    let x = cx + cos(t) * rr * random(0.98,1.02) + random(-5,5);
    let y = cy - 35 + sin(t) * rr * 1.05 * random(0.98,1.02) + random(-5,5);

    let d1 = dist(x, y, cx, cy - 30);
    let fade = map(d1, 150, 400, 1, 0.15);
    if (random(1) < fade) {
      fill(30 + random(-15,8), 28 + random(-10,12), 50 + random(-11,12), random(42,51));
      ellipse(x, y, random(4, 16));
    }
  }

  // 门口内外模糊过渡的碎光
  for (let n = 0; n < 430; n++) {
    let a = random(TWO_PI);
    let rr = random(430, 650);
    let x = cx + cos(a) * rr + random(-38, 38);
    let y = cy - 33 + sin(a) * rr * 1.08 + random(-35, 42);

    let alp = random(90, 200);
    let cc = lerpColor(color(130, 150, 170), color(230, 250, 255), random(1));
    fill(red(cc), green(cc), blue(cc), alp);
    ellipse(x, y, random(20, 90), random(11, 42));
  }

  // 淡入淡出的雾色向外晕染
  for (let e = 0; e < 11; e++) {
    let opacity = map(e, 0, 10, 21, 3);
    fill(150, 150, 180, opacity);
    ellipse(cx, cy - 30, 1240 + e * 90, 1530 + e * 120);
  }
}

function setup() {
