      color(240, 243, 244),
      color(90, 96, 108),
      pow(y / height, 1.9)
    );
    stroke(c);
    line(0, y, width, y);
  }

  // 湖泊（朦胧的深渊）
  let lakeY = 1300;
  let lakeH = 420;
  for (let i = 0; i < lakeH; i++) {
    let alpha = map(i, 0, lakeH, 130, 40);
    noStroke();
    fill(60, 65, 70, alpha);
    beginShape();
    for (let x = 0; x <= width; x += 8) {
      let n = noise(x * 0.0007, i * 0.018 + 2.5);
      let yOffset = map(n, 0, 1, -30, 30);
      vertex(x, lakeY + i + yOffset);
    }
    vertex(width, lakeY + i + 40);
    vertex(0, lakeY + i + 40);
    endShape(CLOSE);
  }

  // 迷雾（死亡朦胧的边界）
  for (let l = 0; l < 40; l++) {
    let fogY = map(l, 0, 40, 800, 1600);
    let fogAlpha = map(l, 0, 40, 18, 60);
    fill(250, 250, 250, fogAlpha);
    noStroke();
    for (let i = 0; i < 12; i++) {
      let fx = random(width);
      let fr = random(240, 650);
      ellipse(fx, fogY+random(-60,60), fr, fr*random(0.62,0.95));
    }
  }

  // 湖中倒影（消融的生机、模糊的回声）
  for (let b = 0; b < 8; b++) {
    let px = width*0.25 + b*random(140,190);
    let py = lakeY-140+random(-30,30);
    let ph = random(100, 170);
    let pw = random(50, 105);

    // 上部淡色轮廓
    fill(200, 205, 210, 44);
    noStroke();
    ellipse(px, py, pw, ph*0.6);

    // 倒影
    for (let k = 0; k < 25; k++) {
      let fade = map(k, 0, 25, 40, 2);
      fill(100, 110, 127, fade);
      let nfy = lakeY + k*5 + noise(b*0.13, k*0.19) * 18;
      let nfw = pw*random(0.82,1.13);
      ellipse(px+random(-3,3), nfy, nfw, random(14,21));
    }
  }

  // 前景干枯枝影（消逝的痕迹）
  for (let t = 0; t < 16; t++) {
    let bx = width*0.11+random(-30,30) + t*random(75,95);
    let by = lakeY + lakeH - random(60,120);
    let len = random(80,320);
    let theta = random(-PI/2.4, -PI/3.2);
    drawBranch(bx, by, len, theta, 0);
  }
}

function drawBranch(x, y, len, angle, depth) {
  if (len < 24 || depth > 4) return;
  push();
  translate(x, y);
  rotate(angle);

  let c = lerpColor(color(80,85,90, 120), color(110,120,130, 30), depth/5.2);
  stroke(c);
  strokeWeight(map(len, 80, 320, 4.2, 7.2) / (depth+1.1));
  line(0, 0, 0, -len);

  if (depth < 1) {  // 主枝尾端点缀一点光斑
    noStroke();
    fill(245, 245, 249, 80);
    ellipse(0, -len+random(-3,3), random(13,20));
  }

  // 分叉
  let nBranches = 1 + floor(random(2));
  for (let i = 0; i < nBranches; i++) {
    let newLen = len * random(0.45, 0.68);
    let newAngle = random(-PI/5, PI/5);
    drawBranch(0, -len*random(0.68,0.93), newLen, newAngle, depth + 1);
  }
  pop();
}

