// 绘制中间模糊的“门”与虚空的渗透
function drawThreshold() {
  push();
  let cx = width / 2;
  let cy = height / 2 + 60;
  let w = 320;
  let h = 1240;
  noStroke();

  // 用多层白色和淡灰色垂直渐变
  for(let i=0; i<64; i++){
    let alpha = map(i,0,63,28,4);
    fill(255, alpha);
    rectMode(CENTER);
    rect(cx, cy, w + i * 30, h + i*10, 68 + i*2);
  }
  // 裂隙淡蓝中心
  fill(235,242,255,90);
  rect(cx,cy, w * 0.72, h*0.87,136);

  // 不规则边缘虚边
  for (let t = 0; t < 1; t += 0.004) {
    let ang = map(t, 0, 1, -HALF_PI, HALF_PI);
    let rx = w/2 * 1.055 + noise(t*9) * 22;
    let ry = h/2 * 1.035 + noise(t*9+90) * 20;
    let x = cx + rx * cos(ang);
    let y = cy + ry * sin(ang);
    fill(240,240,255,28);
    ellipse(x, y, random(16,39),random(8,20));
  }
  pop();

  // 门内的虚无感
  for (let i = 0; i < 1200; i++) {
    let rx = random(-w*0.32, w*0.32);
    let ry = random(-h*0.42, h*0.44);
    let d = dist(0,0,rx,ry);
    let alph = map(d, 0, w*0.32, 20, 0);
    fill(240, 245, 254, alph);
    ellipse(cx+rx, cy+ry, random(4,22), random(4,22));
  }
}

