function drawPortal() {
  // 背景：渐变到深蓝黑色，象征静谧的虚空
  for (let y = 0; y < height; y++) {
    let c = lerpColor(color(38,60,89), color(10,10,15), y/height);
    stroke(c);
    line(0, y, width, y);
  }

  // 虚空之门：中央黑色的宏大椭圆
  let portalW = width*0.68;
  let portalH = height*0.7;
  push();
  translate(width/2, height*0.56);

  // 叠加涟漪光晕：象征生与死的过渡
  for (let i=10; i>0; i--) {
    let alpha = map(i,10,1,32,140);
    let r1 = map(i,10,1,1.30,1.04);
    fill(210,225,245,alpha);
    noStroke();
    ellipse(0, 0, portalW*r1, portalH*r1);
  }

  // 门的核心 - 深黑色
  fill(0,13,23, 255);
  noStroke();
  ellipse(0, 0, portalW, portalH);

  pop();

  // 左右两侧生命之流
  drawLifeFlow(width*0.5-portalW*0.42, height*0.17, -1);
  drawLifeFlow(width*0.5+portalW*0.42, height*0.17, 1);

  // 门前渐明的光影
  for (let y=height*0.57; y<height*0.92; y+=2) {
    let alpha = map(y, height*0.57, height*0.92, 50, 2);
    stroke(228,230,254, alpha);
    strokeWeight(4);
    let lw = map(noise(y*0.004+83),0,1,70,160);
    line(width/2-lw/2, y, width/2+lw/2, y);
  }

  // 门内的消散粒子
  for (let i=0; i<340; i++) {
    let ang = random(TWO_PI);
    let r = random(portalW*0.05, portalW*0.32);
    let x = width/2 + r * cos(ang);
    let y = height*0.56 + 0.9*r * sin(ang);
    let sz = random(6,25);
    let alph = random(10, 60);
    noStroke();
    fill(24,34,38, alph);
    ellipse(x, y, sz, sz*0.8);
  }
}

function drawLifeFlow(cx, topY, dir) {
  // 多条有机线象征生的流动向门而去
  for (let k=0; k<20; k++) {
    let noisef = random(1000);
    let pCount = int(random(19,42));
    let pts = [];
    for (let i=0; i<pCount; i++) {
      let t = i/(pCount-1);
      let x = cx+dir*map(noise(noisef+t*1.7), 0,1, 0,81)*sin(t*PI)*random(0.8,1.9);
      let y = lerp(topY, height*0.55+random(-60,40), t);
      pts.push([x,y]);
    }
    noFill();
    stroke(lerpColor(color(170,200,250,60), color(12,28,64,70), k/20.0));
    strokeWeight(map(k,0,24,2,9));
    beginShape();
    for (let p of pts) {
      curveVertex(p[0], p[1]);
    }
    endShape();
  }
}

