    rect(0, y, width, 2);
  }

  // Two intertwined trees (lovers)
  drawTree(width * 0.48, height * 0.88, 170, -96, 0, 18, color(120, 70, 45), color(180, 120, 70));
  drawTree(width * 0.52, height * 0.88, 160, -84, 0, 16, color(105, 82, 54), color(146, 108, 84));

  // Petals and leaves floating (whimsical, love in the air)
