// Intertwined trees, recursive
function drawTree(x, y, len, angle, depth, maxDepth, col1, col2) {
  if(depth > maxDepth || len < 8) return;

  // Color gradation for trunk/branches
  let c = lerpColor(col1, col2, depth / maxDepth + map(noise(depth),0,1,-0.15,0.18));
  let t = map(depth, 0, maxDepth, 23, 6); // thickness

  push();
  translate(x, y);
  rotate(angle + sin(depth*19)*4);
  stroke(c);
  strokeWeight(t);
  noFill();

  // Main branch
  let branchLen = len * random(0.89, 1.02);
  line(0,0,0,-branchLen);

  // Deform branch end point for intertwining
  let tw = map(depth, 0, maxDepth, 0, 32) * sin(depth*18 + x*0.01);
  let bx = tw;
  let by = -branchLen;

  // Leaves and flowers at tips
  if(depth >= maxDepth-2) {
    if(random()<0.57) drawLeaf(bx, by, random(28,34), random(-12,12));
    if(random()<0.32) drawPetal(bx, by, random(16,28), random(-10,10));
    if(random()<0.17) drawAutumnLeaf(bx, by, random(19,30), random(-10,10));
  }
  // Next branches
  let branchCount = (depth < 6) ? 2 : int(random(1,3));
  for(let i=0;i<branchCount;i++){
    let nextLen = branchLen * random(0.77, 0.87);
    let nextAngle = random(-31,33) * (1-depth/18) + 16*sin(depth*14+i*9);
    if(depth<4 && random()<0.7) nextAngle *= 0.8;
    drawTree(bx, by, nextLen, nextAngle, depth+1, maxDepth, col1, col2);
  }
  pop();
}

// Petal (soft pink)
function drawPetal(x,y,s,rot) {
  push();
  translate(x,y);
  rotate(rot);
  noStroke();
  let cframe = lerpColor(color(255, 180, 210,180), color(255, 120, 180,210), random());
  fill(cframe);
  beginShape();
  for(let a=0;a<360;a+=25){
    let r = s*0.7 + noise(x*a, y*a)*s*0.14;
    let th = radians(a);
    let px = cos(th) * r * (1 + 0.18*sin(a*3));
    let py = sin(th) * r * (0.87 + 0.09*sin(a*5));
    curveVertex(px,py);
  }
  endShape(CLOSE);
  pop();
}

