// Helper: Draw a stylized heart, parametric shape
function drawHeart(x, y, s, col) {
  push();
  translate(x, y);
  scale(s/800.0);
  noStroke();
  fill(col);
  beginShape();
  for (let a = PI*0.03; a < TWO_PI-PI*0.03; a += PI/70) {
    let r = 340-18*sin(2*a)-38*cos(2.3*a);
    let px = 16 * pow(sin(a), 3);
    let py = -13 * cos(a) + 5 * cos(2*a) + 2 * cos(3*a) + cos(4*a);
    vertex(px*r, py*r);
  }
  endShape(CLOSE);

  // Soft highlight
  let g = drawingContext.createRadialGradient(0, -170, 5, 0, -120, 170);
  g.addColorStop(0, color(255, 245, 250, 150));
  g.addColorStop(1, color(255,245,250,0));
  drawingContext.globalAlpha = 0.35;
  drawingContext.fillStyle = g;
  ellipse(0, -110, 400, 280);
  drawingContext.globalAlpha = 1;
  pop();
}

// Helper: Draw intricate vein-like lines
function drawVeins(x, y, s, col, n, wiggle, dir) {
  noFill();
  stroke(col);
  strokeWeight(3);
  for (let i=0; i<n; i++) {
    beginShape();
    for (let t = 0; t <= 1; t += 0.028) {
      let a = lerp(PI*0.23, TWO_PI-PI*0.23, t);
      let heartR = 320-15*sin(2*a)-31*cos(2.6*a);
      let px = 16 * pow(sin(a), 3) * heartR;
      let py = (-13 * cos(a) + 5 * cos(2*a) + 2 * cos(3*a) + cos(4*a)) * heartR;

      let off = (noise(i*3+10+a*0.5) - 0.5)*60 + sin(a*2.2+i)*32*wiggle*dir;
      vertex(x + px*s/800 + off*0.21*dir, y + py*s/800 + off*0.12);
    }
    endShape();
  }
}

