function drawFigure(cx, cy, w, h, c1, c2, rot, bodyTilt) {
  push();
  translate(cx, cy);
  rotate(rot);

  // Lower body: abstract arc
  for (let i = 0; i < 45; i++) {
    let p = i / 44;
    let x = cos(PI + p*PI) * w * 0.65 * (1-0.13*p) * (1 + 0.06*noise(p*4+1, cy*0.001));
    let y = sin(PI + p*PI) * h * 0.38 * (1-0.23*p) + p*131;
    fill(lerpColor(c2, c1, 0.57*p));
    ellipse(x, y+30, 68-43*p, 136-106*p);
  }

  // "Body": soft ellipse, tilted
  push();
  translate(0, -h*0.13);
  rotate(bodyTilt);
  fill(c1);
  ellipse(0, 0, w*0.72, h*0.58);
  pop();

  // "Head": smaller ellipse, soften overlap
  fill(255,255,255,60);
  ellipse(0, -h*0.37, w*0.29, w*0.23);

  fill(lerpColor(c1, c2, 0.3));
  ellipse(0, -h*0.37, w*0.25, w*0.19);

  pop();
}

