// Heart with blended color field, optional highlight and shadow
function drawHeart(cx, cy, s, c1, c2, n1, n2, blur=38, gloss=true) {
  push();
  // Color gradient heart
  for (let k = 0; k < 78; k++) {
    let t = lerp(0.88,1.0,k/77);
    if (c1 && c2) fill(lerpColor(c1, c2, t), 170-(k*2));
    else fill(240,60);
    strokeWeight(0);
    beginShape();
    for (let a = PI*0.11; a < TWO_PI+PI*0.11; a+= PI/90){
      let nx = map(noise(n1*cos(a)*1.2 + t*8, n2*sin(a)*1.5 + t*3),0,1,0.95,1.12);
      let x = cx + cos(a)*(s/2)*nx*t;
      let y = cy + sin(a)*(s/2)*nx*t*0.91;
      // Heart shape formula warping
      let m = sin(a);
      let fx = x + 0.25*(s/2)*t*pow(m,3)*(sin(frameCount*0.002+nx*5)-1);
      let fy = y - (abs(cos(a))*0.3)*(s/6)*(1-t);
      vertex(fx, fy);
    }
    endShape(CLOSE);
  }
  // Subtle highlight
  if(gloss){
    noStroke();
    for(let i = 0; i < 16; i++){
      fill(255,255,255,18-i*1.1);
      ellipse(cx+s*0.11, cy-s*0.2, blur-i*3, blur-i*2.9);
    }
  }
  pop();
}

