// Gradient background helper
function setGradient(x, y, w, h, c1, c2, axis) {
  for (let i = y; i <= y + h; i++) {
    let inter = map(i, y, y + h, 0, 1);
    let c = lerpColor(c1, c2, inter);
    stroke(c);
    line(x, i, x + w, i);
  }
  noStroke();
}

// Draw glowing orb using layers of ellipses
function drawGlowOrb(x, y, r, c) {
  let layers = 18;
  for (let i = layers; i > 0; i--) {
    let alpha = map(i, layers, 0, alpha(c), 0);
    fill(red(c), green(c), blue(c), alpha);
    ellipse(x, y, r * i / layers);
  }
}

