    [0, 1, color(245, 98, 98, 44), color(95, 173, 255, 36)],
    [1, 3, color(95, 173, 255, 34), color(149, 255, 180, 26)],
    [0, 2, color(245, 98, 98, 26), color(252, 229, 117, 20)],
    [2, 3, color(252, 229, 117, 38), color(149, 255, 180, 28)]
  ];
  for (let i = 0; i < bandParams.length; i++) {
