// Draw a single flowing band between two centers (curved, organic)
function drawFlowingBand(cA, cB, c1, c2) {
  let steps = 90;
  let x1 = cA.x, y1 = cA.y;
  let x2 = cB.x, y2 = cB.y;
  let mx = (x1 + x2) / 2 + random(-120, 120);
  let my = (y1 + y2) / 2 + random(-120, 120);
  for (let j = 0; j < 10; j++) {
    let spread = 35 + random(0, 14);
    beginShape();
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let x = bezierPoint(x1, mx + random(-spread,spread), mx + random(-spread,spread), x2, t);
      let y = bezierPoint(y1, my + random(-spread,spread), my + random(-spread,spread), y2, t);
      let lw = lerp(32, 15, abs(t-0.5)*2) + random(-4,4);
      let cc = lerpColor(c1, c2, t);
      fill(cc);
      ellipse(x, y, lw, lw * random(0.50,0.72));
    }
    endShape();
  }
}

