// Trace un coeur stylisé
function drawHeartShape(x, y, size) {
  beginShape();
  for (let a = 0; a < TWO_PI; a += PI/60) {
    let r;
    if (a < PI) {
      r = size * 0.74 * (0.85 + 0.12*sin(a*2));
    } else {
      r = size * 0.99 * (0.78 + 0.18*sin(a));
    }
    let _x = x + r * 16 * pow(sin(a), 3) / 17;
    let _y = y - r * (13 * cos(a) - 5 * cos(2*a) - 2 * cos(3*a) - cos(4*a)) / 17;
    vertex(_x, _y);
  }
  endShape(CLOSE);
}

