  for(let a=PI*1.88; a>=PI*1.13; a-=0.02){
    let r = 120 + 10*sin(a*4) + noise(a*5-direction*2)*16;
    let x = cx + cos(a)*r*1.14 + direction*43;
    let y = cy + sin(a)*r*1.13 - 60;
