      let r = 370-interp*90 + 18*sin(3*a) + noise(a*2+direction*3+t)*29;
      let x = cx + cos(a)*r;
      let y = cy + sin(a)*r*1.21 + map(abs(a-PI*1.5),0,0.4,0,70);
