// Heart shape drawing function (centered at x,y)
function heartShape(x, y, s) {
  beginShape();
  for (let a=PI; a<=TWO_PI; a+=PI/50) {
    let vx = x + s*16 * pow(sin(a),3);
    let vy = y - s*(13*cos(a)-5*cos(2*a)-2*cos(3*a)-cos(4*a));
    vertex(vx, vy);
  }
  for (let a=TWO_PI; a>=PI; a-=PI/50) {
    let vx = x + s*16 * pow(sin(a),3);
    let vy = y - s*(13*cos(a)-5*cos(2*a)-2*cos(3*a)-cos(4*a));
    vertex(vx, vy);
  }
  endShape(CLOSE);
}

