function drawShape(cx, cy, w, h, nPts, nRings, c1, c2, detail, k1, k2, m1, m2, bias, flip) {
  push();
  for (let r=nRings; r>0; r--) {
    let f = r/nRings;
    let col = lerpColor(c1, c2, 0.09+(1-f)*0.84).levels;
    fill(col[0], col[1], col[2], map(f,0,1,90,235));
    beginShape();
    for (let i=0; i<=nPts; i++) {
      let a = map(i, 0, nPts, 0, TWO_PI);
      let nx = cos(a+m1+bias)*k1 + (flip?-m2:m2);
      let ny = sin(a-m2-bias)*k2;
      let d = 1 + noise(nx*f*2+2, ny*f*2-2, r*0.11)*detail*0.015 + (random(-.14,0.13));
      let rx = cx + cos(a)*w*f*d*0.5;
      let ry = cy + sin(a)*h*f*d*0.5;
      curveVertex(rx, ry);
    }
    endShape(CLOSE);
  }
  // add "painterly" marks
  for (let i=0; i<17; i++) {
    let t=random(0,TWO_PI), f=random(0.42,0.84);
    let rx=cx+cos(t)*w*0.38*f+random(-9,10);
    let ry=cy+sin(t)*h*0.44*f+random(-9,10);
    fill(lerpColor(c1,c2,random(0.3,0.95)));
    ellipse(rx, ry, random(8,22),random(5,16));
  }
  pop();
}

