// Dessine une nappe/flux d’énergie semi-transparente en courbes bruitées
function drawEnergyField(cx, cy, r, col) {
  push();
  noFill();
  strokeWeight(2.8);
  stroke(col);
  beginShape();
  for (let a = 0; a <= TWO_PI + 0.1; a += PI / 62) {
    let rnd = noise(cx * 0.08 + cos(a) * 3, cy * 0.1 + sin(a) * 3);
    let rn = r * (0.94 + 0.13 * rnd);
    let x = cx + cos(a) * rn;
    let y = cy + sin(a) * rn;
    curveVertex(x, y);
  }
  endShape(CLOSE);
  pop();
}

// Courant arc génératif, fluide et coloré
function drawArcFlow(cx, cy, r, weight, col) {
  push();
  noFill();
  stroke(col);
  strokeWeight(18 * weight);
  let phi0 = random(PI * 2);
  let phi1 = phi0 + random(.8, 1.9) * PI;
  beginShape();
  for (let a = phi0; a < phi1; a += 0.06 + random(0.02, 0.035)) {
    let rad = r * (0.94 + 0.10 * noise(a * 1.4, cx * 0.006, cy * 0.004));
    let x = cx + cos(a) * rad + random(-10, 10);
    let y = cy + sin(a) * rad + random(-10, 10);
    curveVertex(x, y);
  }
  endShape();
  pop();
}

// “Cœur” diffus (amas mou sans bord régulier)
function drawSoftCore(x, y, sz, col) {
  push();
  noStroke();
  for (let i = 0; i < 40; i++) {
    let alfa = red(col) + 10 * noise(i);
    fill(red(col), green(col), blue(col), alpha(col) * (1 - i / 42.0));
    let ox = x + random(-sz * .17, sz * .17);
    let oy = y + random(-sz * .17, sz * .17);
    ellipse(ox, oy, sz * (0.90 - i * 0.014));
  }
  pop();
}

