function drawHeartish(x, y, w, h, c, bulge, asym=1, rot=0) {
  push();
  translate(x, y);
  rotate(rot);
  fill(c);
  beginShape();
  for (let a=PI*0.05; a<TWO_PI-PI*0.05; a+=PI/55) {
    let r = 0.5*(sin(a)*sqrt(abs(cos(a))) / (sin(a)+1.4) - 2*sin(a)+2.06);
    r *= noise(5+bulge*a, a)*0.91 + 0.22*(noise(10+a,bulge) - 0.5);
    let vx = cos(a)*w*asym*0.43*r;
    let vy = sin(a)*h*0.42*r;
    curveVertex(vx, vy);
  }
  endShape(CLOSE);
  pop();
}

function drawWavyLine(x0,y0,x1,y1,col, sw, freq, t0){
  push();
  stroke(col);
  strokeWeight(sw);
  noFill();
  beginShape();
  for(let i=0;i<=1;i+=0.04){
    let nx = lerp(x0,x1,i);
    let ny = lerp(y0,y1,i);
    let ang = atan2(y1-y0, x1-x0);
    let mag = sin(i*PI)*12 + noise(t0+i*5)*14;
    nx += cos(ang-PI/2)*mag*sin(i*freq*800 + t0);
    ny += sin(ang-PI/2)*mag*cos(i*freq*1000-t0);
    curveVertex(nx,ny);
  }
  endShape();
  pop();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
  noStroke();
  background(250, 243, 240);

  // Fading background threads
  for (let i = 0; i < 17; i++) {
    let c = color(210 + i * 2, 200 + i * 3, 220 + i * 2, 80);
    for (let j = 0; j < 16; j++) {
      let xoff = 100 + i * 80 + random(-70, 70);
      let n = 950;
      beginShape();
      fill(c);
      for (let k = 0; k < n; k++) {
        let t = map(k, 0, n-1, 0, 1);
        let y = map(k, 0, n-1, 0, height);
        let x = xoff + noise(i * 0.3 + j * 0.25, y * 0.001 + j * 0.05) * 220 - 110 + sin(t * PI * 4 + i) * 35;
        vertex(x, y);
        // Striated effect
        if (k % 40 == 0) {
          ellipse(x, y, 5, 23);
        }
      }
      endShape();
    }
  }

  // Central moving color flows: symbolize connections, divergence, fusion
  for (let m = 0; m < 5; m++) {
    let p = [];
    let off = random(0.2, 1.8);
    let colz = [
      [245,84,125,180],[53,73,189,170],[255,190,72,185],[22,187,132,160],[255,133,29,170]
    ];
    let c0 = lerpColor(color(colz[m][0],colz[m][1],colz[m][2],colz[m][3]), color(255,255,255,40), 0.25);
    for (let i = 0; i < 170; i++) {
      let t = i / 169.0;
      let x = width/2 + sin(t * PI * (2+off)) * (350+120*t) + noise(m*0.9,t*1.1)*120;
      let y = 220 + t * (height-380) + sin(t*PI*8+off+m)*32
        + noise(m*1.5, t*1.25+off)*40;
      p.push({x: x, y: y});
    }
    // Wide stroke
    for (let d = 55; d > 7; d-=8) {
      let alphaF = map(d,55,7,0.1,0.65);
      fill(red(c0), green(c0), blue(c0), 150 * alphaF);
      beginShape();
      for (let i = 0; i < p.length; i++) {
        let perp = createVector(0,0);
        if (i > 0) {
          let prev = createVector(p[i].x - p[i-1].x, p[i].y - p[i-1].y).normalize();
          perp = createVector(-prev.y, prev.x);
        }
        vertex(p[i].x + perp.x*d, p[i].y + perp.y*d);
      }
      for (let i = p.length-1; i >= 0; i--) {
        let perp = createVector(0,0);
        if (i < p.length-1) {
          let n = createVector(p[i].x - p[i+1].x, p[i].y - p[i+1].y).normalize();
          perp = createVector(-n.y, n.x);
        }
        vertex(p[i].x - perp.x*d, p[i].y - perp.y*d);
      }
      endShape(CLOSE);
    }
  }

  // Circles: nodes - moments of encounter, individuality
  for (let i = 0; i < 14; i++) {
    let angle = map(i, 0, 14, PI/7, TWO_PI+PI/4);
    let r = map(noise(i*0.3), 0,1, 320, 690);
    let center = width/2 + cos(angle)*r;
    let ycenter = height/2 + sin(angle)*r * 0.75 + random(-30,30);
    let sz = map(sin(angle*2.4+2), -1, 1, 55, 160) + random(-8,20);
    let cset = [
      color(58,107,148,210), color(235,93,155,168), color(251,196,77,200), color(244,146,32,170), color(34,196,146,184)
    ];
    fill(cset[i%5]);
    ellipse(center, ycenter, sz, sz);
    // Glowy
    fill(red(cset[i%5]), green(cset[i%5]), blue(cset[i%5]), 55);
    ellipse(center, ycenter, sz*2.3, sz*2.15);
  }

  // Smaller touchpoints: brushstrokes of chance meetings
  for (let i = 0; i < 33; i++) {
    let x = random(240, width-240);
    let y = random(220, height-220);
    let angle = random(TWO_PI);
    let l = random(110, 240);
    let w = random(12,40);
    let cg = lerpColor(color(41,167,184,120), color(255, 143, 23,70), noise(i*0.07));
    push();
    translate(x, y);
    rotate(angle + noise(i*0.21) * PI/2);
    fill(cg);
    ellipse(0, 0, w, l);
    pop();
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  background(245, 237, 230);

  // Fond nuancé : flux doux
  for (let y = 0; y < height; y += 4) {
    let c = lerpColor(
      color(245, 237, 230),
      color(235, 216, 205),
      y / height
    );
    stroke(c);
    line(0, y, width, y);
  }

  // Centres d'émission : coeurs d'énergie
  let centers = [];
  for (let i = 0; i < 5; i++) {
    let a = random(TWO_PI);
    let r = random(200, 500);
    let x = width / 2 + cos(a) * r;
    let y = height * 0.52 + sin(a) * r * 0.8;
    centers.push({ x: x, y: y, hue: random(320, 360), lum: random(170, 200) });
  }
  centers.push({ x: width / 2, y: height * 0.52, hue: 345, lum: 230 });

  // Rayonnement organique
  for (let ci = 0; ci < centers.length; ci++) {
    let c = centers[ci];
    let points = 220 + int(random(60));
    let baseRad = random(90, 220);

    for (let i = 0; i < points; i++) {
      let t = lerp(-PI * 0.9, PI * 0.9, i / points);
      let off = noise(ci * 100 + i * 0.04, ci * 30) * 60;
      let r = baseRad + off;
      let px = c.x + cos(t) * r;
      let py = c.y + sin(t) * r * (1.05 + 0.13 * sin(ci + i * 0.13));
      let grad = lerpColor(
        color(`hsba(${c.hue}, 54%, ${c.lum}%, 0.41)`),
        color(`hsba(${(c.hue + 24) % 360}, 63%, 98%, 0.07)`),
        pow(abs(i / points - 0.5), 1.5) * 1.3
      );
      stroke(grad);
      strokeWeight(0.8 + pow(noise(i * 0.2, ci), 2) * 2);
      line(c.x, c.y, px, py);
    }
  }

  // Filaments interconnectés
  strokeWeight(2.5);
  for (let k = 0; k < 9; k++) {
    let c1 = centers[int(random(centers.length))];
    let c2 = centers[int(random(centers.length))];
    if (c1 === c2) continue;
    let hu = lerp(c1.hue, c2.hue, 0.5) + random(-6, 6);
    let lum = lerp(c1.lum, c2.lum, 0.7);
    stroke(`hsba(${hu},61%,${lum}%,0.33)`);
    noFill();
    beginShape();
    for (let t = 0; t <= 1; t += 0.05) {
      let x = bezierPoint(
        c1.x, width / 2 + random(-300, 300), width / 2 + random(-300, 300), c2.x, t
      );
      let y = bezierPoint(
        c1.y, c1.y + random(-300, 290), c2.y + random(-320, 310), c2.y, t
      );
      curveVertex(x, y);
    }
    endShape();
  }

  // Voile léger / fusion subtile
  for (let i = 0; i < 6; i++) {
    let cx = width / 2 + random(-18, 18);
    let cy = height / 2 + random(-100, 100);
    let col = color(
      `hsba(${337 + i * 6},57%,${224 + i * 8}%,0.05)`
    );
    noStroke();
    fill(col);
    ellipse(cx, cy, 870 + i * 80, 810 + i * 130);
  }

  // Touches lumineuses, "miracles"
  for (let i = 0; i < 64; i++) {
    let ang = random(TWO_PI);
    let r = random(190, width * 0.35);
    let x = width / 2 + cos(ang) * r + random(-28, 28);
    let y = height * 0.52 + sin(ang) * r * 0.68 + random(-22, 22);
    fill(255, 237, 247, 158);
    noStroke();
    ellipse(x, y, random(11, 25), random(8, 20));

    if (random() < 0.42) {
      fill(255, 153, 200, 140);
      ellipse(x + random(-5, 5), y + random(-5, 5), random(6, 13));
    }
  }
}

function setup() {
