  noStroke();

  // Palette 
  let bg = color(245, 239, 237);
  let rose = color(244, 172, 191, 210);
  let bleu = color(101, 191, 220, 180);
  let or = color(253, 206, 84, 180);
  let vert = color(158, 217, 186, 180);
  let mauve = color(150, 120, 212, 90);
  let blanc = color(255,255,255,70);

  // Fond
  background(bg);

  // Deux grands halos imbriqués
  for (let i = 350; i > 1; i -= 2) {
    fill(lerpColor(rose, bleu, map(i, 350, 1, 0, 1)));
