    fill(lerpColor(bleu, rose, map(i, 350, 1, 0, 1)));
    ellipse(width*0.57, height*0.56, i*4.2, i*5);
  }

  // Voies entrelacées (béziers, légèrement déformés)
  for (let k = 0; k < 3; k++) {
    push();
    let c = lerpColor(bleu, or, k/2.2);
    fill(c);
    beginShape();
    for (let t = 0; t <= 1; t += 0.02) {
      let x = bezierPoint(width*0.35, width*0.7, width*0.2, width*0.65, t);
      let y = bezierPoint(height*0.81, height*0.25, height*0.65, height*0.38, t);
      x += map(noise(t*4 + k*30), 0, 1, -30, 30);
      y += map(noise(t*3 + k*20), 0, 1, -22, 22);
      curveVertex(x + k*16, y + k*6);
    }
    for (let t = 1; t >= 0; t -= 0.02) {
      let x = bezierPoint(width*0.65, width*0.18, width*0.81, width*0.52, t);
      let y = bezierPoint(height*0.38, height*0.69, height*0.18, height*0.8, t);
      x += map(noise(t*5 + k*18 + 66), 0, 1, -28, 28);
      y += map(noise(t*4 + k*10 + 19), 0, 1, -30, 30);
      curveVertex(x - k*14, y - k*7);
    }
    endShape(CLOSE);
    pop();
  }

  // Petits noyaux : rencontres, coeurs abstraits
  for (let i = 0; i < 8; i++) {
    let cx = width * 0.40 + cos(TWO_PI*i/8+i)*140 + random(-15,15);
    let cy = height * 0.55 + sin(TWO_PI*i/8+i*1.3)*200 + random(-11,11);
    fill(or);
    ellipse(cx, cy, 56 + random(-18,12), 56 + random(-18,12));
    fill(255,210+random(-17,0));
    ellipse(cx-7, cy-4, 21+random(-4,7), 24+random(-4,7));
  }

  // Silhouettes incomplètes, juste des arcs proches
  strokeWeight(28);
  stroke(rose);
  noFill();
  arc(width*0.43, height*0.74, 210, 180, radians(-20), radians(160));
  stroke(bleu);
  arc(width*0.61, height*0.67, 168, 250, radians(170), radians(360));
  stroke(or);
  arc(width*0.54, height*0.36, 330, 100, radians(12), radians(127));
  noStroke();

  // Voile superposant doux
  for (let v = 0; v < 50; v++) {
    fill(lerpColor(mauve, blanc, random(0.3,0.82)));
    ellipse(
      width*0.49+random(-300,300), 
      height*0.48+random(-350,350), 
      random(96,210), 
      random(90,230)
    );
  }

  // Petites graines semées
  for (let i = 0; i < 70; i++) {
    fill(lerpColor(vert, or, random(0.25,0.8)));
    ellipse(
      width*0.42 + random(-320, 600),
      height*0.53 + random(-380, 320),
      random(13, 25), random(8,16)
    );
  }

  // Lumière centrale rassemblante
  for (let i = 50; i > 0; i--) {
    fill(255, 255, 240, 14);
    ellipse(width*0.505, height*0.55, i*23, i*20);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();

  // Background: deep violet gradient
  for (let y = 0; y < height; y++) {
    let c = lerpColor(color(30, 15, 60), color(220, 155, 190), map(y, 0, height, 0, 1));
    stroke(c);
    line(0, y, width, y);
  }

  // Draw softly glowing orbs for "hearts"
  drawGlowingOrb(700, 1100, 360, color(250, 120, 150, 160), color(255, 190, 210, 70));
  drawGlowingOrb(900, 940, 300, color(200, 105, 255, 110), color(170, 210, 240, 50));

  // Overlapping pulse where they meet
  drawPulse(800, 1030, 210, color(255, 230, 110, 105), color(255, 255, 230, 55));

  // Draw two flowing, intertwined ribbon forms
  drawRibbon(740, 1180, 950, 900, color(255,150,200,95), color(220,170,220,85));
  drawRibbon(920, 900, 670, 1200, color(190,160,255,90), color(160,220,255,85));

  // Sparkles around the orbs, representing "inner light" and connection
  drawSparkles(800, 1050, 370, 120);
}

function drawGlowingOrb(cx, cy, r, col1, col2) {
  noStroke();
  for (let rad = r * 1.2; rad > 0; rad -= 4) {
    let amt = map(rad, r * 1.2, 0, 0, 1);
    let c = lerpColor(col2, col1, amt);
    fill(c);
    ellipse(cx, cy, rad, rad);
  }
}

function drawPulse(cx, cy, maxr, col1, col2) {
  noStroke();
  for (let i = 0; i < 6; i++) {
    let f = i / 5;
    let c = lerpColor(col2, col1, 1 - f);
    fill(c);
    ellipse(cx, cy, maxr * (1 + f * 0.13), maxr * (1 + f * 0.13));
  }
}

function drawRibbon(x1, y1, x2, y2, baseCol, lightCol) {
  let steps = 80;
  let ctrlAX = lerp(x1, x2, 0.25) + random(-100, 100);
  let ctrlAY = lerp(y1, y2, 0.25) + random(-120, 120);
  let ctrlBX = lerp(x1, x2, 0.75) + random(-140, 140);
  let ctrlBY = lerp(y1, y2, 0.75) + random(-110, 110);

  for (let t = 0; t < 1; t += 1 / steps) {
    let x = bezierPoint(x1, ctrlAX, ctrlBX, x2, t);
    let y = bezierPoint(y1, ctrlAY, ctrlBY, y2, t);
    let w = 35 + 40 * sin(t * PI) + 10 * noise(t * 4 + random(100));
    let c = lerpColor(baseCol, lightCol, t);
    noStroke();
    fill(c);
    ellipse(x, y, w, w * 0.75);
  }

  // Soft highlight along the ribbon
  for (let t = 0; t < 1; t += 1 / steps) {
    let x = bezierPoint(x1, ctrlAX, ctrlBX, x2, t);
    let y = bezierPoint(y1, ctrlAY, ctrlBY, y2, t);
    noStroke();
    fill(255, 255, 255, map(sin(t * PI), 0, 1, 0, 34));
    ellipse(x, y-8, 13, 6);
  }
}

function drawSparkles(cx, cy, r, count) {
  for (let i = 0; i < count; i++) {
    let a = random(TWO_PI);
    let rr = r * pow(random(), 0.6);
    let x = cx + cos(a) * rr + random(-8, 8);
    let y = cy + sin(a) * rr + random(-8, 8);
    let sz = random(2, 11);
    let alp = map(sz, 2, 11, 120, 35) * random(0.7, 1);
    fill(255, 255, 240, alp);
    noStroke();
    ellipse(x, y, sz, sz);
    if (random() < 0.2) {
      stroke(255, 255, 210, 80);
      for (let j = 0; j < 2 + int(random(3)); j++) {
        let angle = random(TWO_PI);
        let len = random(10, 32);
        line(x, y, x + cos(angle) * len, y + sin(angle) * len);
      }
      noStroke();
    }
  }
}

