// Heart shape
function drawHeart(x, y, s) {
  beginShape();
  for (let a = 0; a < TWO_PI; a += 0.03) {
    let r = s * 0.28;
    let px = r * 16 * pow(sin(a), 3);
    let py = -r * (13 * cos(a) - 5 * cos(2 * a) - 2 * cos(3 * a) - cos(4 * a));
    vertex(x + px, y + py);
  }
  endShape(CLOSE);
}

// Simplified embracing figure, stylized
function drawEmbracingFigure(ox, oy, scaleF, mainCol, flip) {
  push();
  scale(scaleF * flip, scaleF);
  // Body
  fill(mainCol);
  noStroke();
  beginShape();
  vertex(-16, 95);
  bezierVertex(-55, 90, -58, 25, -18, -44);
  bezierVertex(8, -74, 50, -55, 59, -13); // head
  bezierVertex(69, 33, 30, 89, -16, 95);
  endShape(CLOSE);
  // Arm
  fill(lerpColor(mainCol, color(255, 240, 220), 0.6));
  beginShape();
  vertex(45, 23 + 4);
  bezierVertex(105, 70 + 3, 90, 115 + 6, 37, 87 + 4);
  bezierVertex(34, 81, 40, 45, 45, 23 + 4);
  endShape(CLOSE);
  // Head
  fill(lerpColor(mainCol, color(255, 225, 225), 0.5));
  ellipse(43, -36, 41, 42);
  pop();
}

