function drawAbstractHeart(x, y, s, c1, c2) {
  noStroke();
  // Soft base
  fill(c2);
  beginShape();
  for (let a = -PI/1.3; a < PI*1.31; a += 0.065) {
    let r = s * 0.43 * (1 - 0.6 * sin(a) * sin(a) + 0.2 * noise(sin(a+2)*1.7,cos(a-1.1)*2.1));
    let xs = x + r * 16/21 * sin(a) + random(-2,2);
    let ys = y - r * cos(a) - s*0.07 * cos(a*2) * sin(a/2);
    curveVertex(xs, ys);
  }
  endShape(CLOSE);
  // More saturated core
  fill(c1);
  beginShape();
  for (let a = -PI/1.35; a < PI*1.29; a += 0.12) {
    let r = s * 0.38 * (1 - 0.65 * sin(a) * sin(a) + 0.25 * noise(sin(a),cos(a*1.1)));
    let xs = x + r * 15/21 * sin(a) + random(-1,1);
    let ys = y - r * cos(a) - s*0.07 * cos(a*2) * sin(a/2);
    curveVertex(xs, ys);
  }
  endShape(CLOSE);
}

function drawAbstractHeartOutline(x, y, s, c) {
  noFill();
  stroke(c);
  beginShape();
  for (let a = -PI/1.3; a < PI*1.31; a += 0.04) {
    let r = s * 0.43 * (1 - 0.6 * sin(a) * sin(a) + 0.2 * noise(sin(a+2)*1.7,cos(a-1.1)*2.1));
    let xs = x + r * 16/21 * sin(a);
    let ys = y - r * cos(a) - s*0.07 * cos(a*2) * sin(a/2);
    curveVertex(xs, ys);
  }
  endShape(CLOSE);
}

