// 爱心
function drawHeart(cx, cy, size, col1, col2) {
  push();
  translate(cx, cy);
  beginShape();
  for (let a = -PI, step = PI/100; a < PI+0.02; a += step) {
    let x = 16 * pow(sin(a), 3);
    let y = - (13 * cos(a) - 5 * cos(2*a) - 2 * cos(3*a) - cos(4*a));
    x *= size * 0.047;
    y *= size * 0.05;
    let inter = sin((a + PI) / (2*PI));
    let c = lerpColor(col1, col2, inter);
    fill(c);
    stroke(c);
    strokeWeight(2);
    vertex(x, y);
  }
  endShape(CLOSE);
  pop();
}

// 手臂
function drawArm(cx, cy, length, angleOffset, flip) {
  push();
  translate(cx, cy);
  rotate(angleOffset);
  noFill();
  for (let i = 0; i < 23; i++) {
    let col = lerpColor(
      color(255, 170, 130, 69),
      color(195, 95, 105, 180),
      i/22.0
    );
    stroke(col);
    strokeWeight(19 - i * 0.8);
    beginShape();
    for (let t = 0; t <= 1; t+=0.06) {
      let theta = map(t, 0, 1, PI+0.1, 0);
      let x = cos(theta) * (length * (0.73-t*0.27)) * flip;
      let y = sin(theta) * (length * sqrt(1-t) * 0.46 - 18*t*t);
      x += noise(i*0.13, t*0.6)*8*flip - 6*flip*t;
      y += noise(i*0.18, t*0.92)*8 - 4*t;
      vertex(x, y);
    }
    endShape();
  }
  // 手指（简化为圆和线）
  strokeWeight(10);
  let tipx = flip * (length * 0.80);
  let tipy = -length*0.22 + 20;
  for (let f = 0; f < 4; f++) {
    let angle = map(f, 0, 3, PI/6, PI/2);
    let lx = tipx + cos(angle) * 35 * flip;
    let ly = tipy + sin(angle) * 11 + f*13;
    stroke(235, 195, 185, 205);
    line(tipx, tipy, lx, ly);
    fill(250,228,222,180);
    ellipse(lx, ly+15, 28, 16);
  }
  // 手掌
  fill(250, 224, 195, 240);
  noStroke();
  ellipse(tipx, tipy+25, 54, 52);
  pop();
}

// 爱心高光
function drawHeartHighlight(cx, cy, size) {
  push();
  translate(cx, cy);
  stroke(255, 248, 236, 90);
  strokeWeight(9);
  noFill();
  beginShape();
  for (let a = -PI/1.25; a < -PI/2.6; a += PI/150) {
    let x = 16 * pow(sin(a), 3);
    let y = -(13 * cos(a) - 5 * cos(2*a) - 2 * cos(3*a) - cos(4*a));
    x *= size * 0.047;
    y *= size * 0.05;
    vertex(x, y);
  }
  endShape();
  pop();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  background(248, 248, 250);

  // 花瓣参数
  let centers = [];
  let mainCore = createVector(width / 2, height / 2);
  let numShapes = 8;
  let radii = [500, 470, 410, 420, 350, 420, 400, 370]; // 形状大小
  let palette = [
    color(255, 94, 98, 90),   // 红
    color(255, 190, 70, 85),  // 橙
    color(129, 236, 126, 70), // 绿  
    color(65, 179, 240, 90),  // 蓝
    color(190, 125, 254, 80), // 紫
    color(255, 151, 203, 60), // 粉
    color(255, 238, 100, 62), // 黄
    color(59, 222, 217, 65)   // 青
  ];
  // 计算各中心点
  for (let i = 0; i < numShapes; i++) {
    let angle = map(i, 0, numShapes, 0, TWO_PI);
    let r = random(110, 190);
    let cx = mainCore.x + cos(angle) * r;
    let cy = mainCore.y + sin(angle) * r + random(-50, 50);
    centers.push(createVector(cx, cy));
  }

  // 绘制重叠的流体形状
  for (let i = 0; i < numShapes; i++) {
    drawBlobbyShape(
      centers[i].x,
      centers[i].y,
      radii[i],
      palette[i],
      0.37 + 0.06 * i
    );
  }

  // 绘制核心发光
  for (let i = 0; i < 14; i++) {
    let coreColor = color(255, 230, 212, 40 - i * 2.5);
    noStroke();
    fill(coreColor);
    ellipse(mainCore.x, mainCore.y, 270 - i * 14, 270 - i * 14);
  }

  // 绘制淡淡的“光环”
  for (let i = 1; i < 6; i++) {
    let haloColor = color(252, 207, 132, 13 - i * 2);
    noFill();
    stroke(haloColor);
    strokeWeight(12 - i * 2);
    ellipse(mainCore.x, mainCore.y, 430 + i * 38, 430 + i * 38.5);
  }

  // 最后增强中心的柔光
  for (let i = 0; i < 5; i++) {
    let glow = color(255, 222, 222, 28 - i * 5);
    noStroke();
    fill(glow);
    ellipse(mainCore.x, mainCore.y, 160 - i * 16, 160 - i * 16);
  }
}

function drawBlobbyShape(cx, cy, r, col, noisiness) {
  noStroke();
  fill(col);
  beginShape();
  let angleOff = random(TWO_PI);
  for (let a = 0; a < TWO_PI + 0.05; a += 0.04) {
    let nr = r * (0.82 + 0.28 * noise(noisiness * cos(a + angleOff), noisiness * sin(a + angleOff)));
    let x = cx + nr * cos(a);
    let y = cy + nr * sin(a);
    curveVertex(x, y);
  }
  endShape(CLOSE);
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
  blendMode(ADD);
  background(22, 18, 33);

  // Draw glowing, softly intersecting 'energy threads'
  for(let t=0; t<35; t++) {
    let clr = lerpColor(color(255,90,127,90), color(73,177,255,80), t/34);
    let nClump = int(random(2,5));
    for (let cl=0; cl<nClump; cl++) {
      let offx = random(-80,80);
      let offy = random(-150,150);
      let cx = width/2 + offx + random(-110,110);
      let cy = height/2 + offy + random(-110,110);
      let r = random(500,900);
      let ang0 = random(TWO_PI);
      drawThread(cx, cy, r, ang0, clr);
    }
  }

  // Draw soft, overlapping radiant circles (pulses of warmth)
  for(let k=0; k<14; k++) {
    let px = width/2 + cos(k*PI/7.2+random(-0.4,0.4))*random(220,650);
    let py = height/2 + sin(k*PI/7.2+random(-0.3,0.3))*random(320,750);
    let radius = random(160,270);
    let c2 = lerpColor(color(255,203,89,20), color(218,132,255,20), noise(k)*0.7+0.3);
    drawGlowCircle(px, py, radius, c2);
  }

  // Radiant center, echo of many presences
  for(let n=0; n<36; n++) {
    let a = n*PI/18 + random(-0.06,0.06);
    let rad = random(220,340);
    let x = width/2 + cos(a)*rad;
    let y = height/2 + sin(a)*rad;
    drawPetal(width/2, height/2, x, y, n%3);
  }

  // Glimmering points of connection
  for (let i=0; i<120; i++) {
    let px = width/2 + cos(random(TWO_PI))*random(200,760);
    let py = height/2 + sin(random(TWO_PI))*random(200,760);
    let cc = color(255,250,242,130);
    fill(cc);
    noStroke();
    ellipse(px, py, random(17,26), random(12,23));
