// One softly undulating curve as a thread
function drawThread(cx, cy, radius, ang0, clr) {
  noFill();
  stroke(clr);
  strokeWeight(random(20,55));
  beginShape();
  for(let i=0; i<=52; i++) {
    let a = ang0 + map(i,0,52,0,PI*random(1.1, 2.3));
    let rad =
      radius 
      + noise(cx*0.0009+i*0.047, cy*0.0009+i*0.055)*120 
      + sin(i*PI/13)*60*noise(cx-i, cy+i);
    let xx = cx + cos(a)*rad;
    let yy = cy + sin(a)*rad;
    curveVertex(xx, yy);
  }
  endShape();
}

// Glowing, diffused circle
function drawGlowCircle(x, y, r, c) {
  noStroke();
  for (let i=8; i>0; i--) {
    fill(red(c), green(c), blue(c), lerp(22,3,i/8));
    ellipse(x, y, r*i/4.6+i*9.2, r*i/4.6+i*11.7);
  }
}

// Radiant, petal-like strokes around the heart
function drawPetal(cx, cy, ex, ey, k) {
  let grad = drawingContext.createRadialGradient(cx, cy, 8, ex, ey, 110);
  if(k==0) {
    grad.addColorStop(0, "rgba(255,197,245,0.33)");
    grad.addColorStop(1, "rgba(100,242,255,0.08)");
  } else if(k==1) {
    grad.addColorStop(0, "rgba(255,234,103,0.23)");
    grad.addColorStop(1, "rgba(255,61,103,0.10)");
  } else {
    grad.addColorStop(0, "rgba(255,245,170,0.21)");
    grad.addColorStop(1, "rgba(193,153,255,0.09)");
  }
  drawingContext.save();
  drawingContext.globalAlpha = 0.7;
  drawingContext.beginPath();
  drawingContext.arc(ex, ey, 105, 0, TWO_PI);
  drawingContext.closePath();
  drawingContext.fillStyle = grad;
  drawingContext.fill();
  drawingContext.restore();
}

