function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  background(245, 242, 239);

  noFill();

  // 绘制中心光圈
  for (let r = 220; r > 20; r -= 6) {
    let c = lerpColor(color(250,203,174,50), color(255,147,180,120), r/220);
    stroke(c);
    strokeWeight(16 - r*0.065);
    ellipse(width/2, height/2, r*6, r*6.2);
  }

  // 交织线条
  for (let i = 0; i < 120; i++) {
    let baseAng = random(TWO_PI);
    let layer = floor(map(i, 0, 120, 1, 6));
    let hue = map(noise(i*0.14), 0, 1, 15, 350) % 360;
    let sat = map(layer, 1, 6, 80, 30);
    let bri = map(layer, 1, 6, 100, 85);
    let col = color(`hsb(${hue}, ${sat}%, ${bri}%)`);
    col.setAlpha(map(layer, 1, 6, 90, 22));
    stroke(col);
    strokeWeight(map(layer, 1, 6, 6.5, 1.8));

    let points = [];
    let numPts = floor(random(13, 24));
    for (let j = 0; j < numPts; j++) {
      let t = j/(numPts-1);
      let a = baseAng + noise(i*0.41, t*1.17)*PI*1.1 * (random() > 0.7? -1: 1);
      let rad = map(t,0,1,250+layer*120,550+layer*170) + noise(i*0.2, t*2+4)*55;
      let x = width/2 + cos(a) * rad;
      let y = height/2 + sin(a) * rad;
      // 增加一些漂移
      x += map(noise(i*1.2+t*8), 0,1, -15,15)*(6-layer);
      y += map(noise(i*2.3+t*8), 0,1, -15,15)*(6-layer);
      points.push([x, y]);
    }
    beginShape();
    curveVertex(points[0][0], points[0][1]);
    for (let j = 0; j < points.length; j++) {
      curveVertex(points[j][0], points[j][1]);
    }
    curveVertex(points[points.length-1][0], points[points.length-1][1]);
    endShape();
  }

  // 星芒光晕（象征脉冲扩散）
  push();
  blendMode(SOFT_LIGHT);
  for (let i = 0; i < 23; i++) {
    let alpha = map(i,0,22,120,10);
    stroke(255, 188, 145, alpha);
    strokeWeight(map(i,0,22,76,6));
    let angle = i*TWO_PI/23+random(-0.1, 0.1);
    let r1 = 0; let r2 = random(480, 610);
    line(
      width/2+cos(angle)*r1, height/2+sin(angle)*r1,
      width/2+cos(angle)*r2, height/2+sin(angle)*r2
    );
  }
  pop();

  // 内部漂浮柔软斑点
  for (let i = 0; i < 46; i++) {
    let ang = random(TWO_PI);
    let rad = random(50, 270);
    let cx = width/2 + cos(ang)*rad + random(-20,20);
    let cy = height/2 + sin(ang)*rad + random(-15,15);
    let clr = color(255, random(120,140), random(155,170), random(25,60));
    noStroke();
    for(let k=0;k<3;k++){
      fill(clr.levels[0],clr.levels[1],clr.levels[2], clr.levels[3]*(0.8-k*0.2));
      ellipse(cx+random(-5,5), cy+random(-5,5), random(45,60-k*10), random(31,47-k*8));
    }
  }
}

