function drawSpiral(cx, cy, r) {
  noFill();
  stroke(220, 220, 250, 200);
  strokeWeight(3);
  beginShape();
  let thetaStart = random(TWO_PI);
  for (let angle = thetaStart; angle < thetaStart + TWO_PI * 4; angle += 0.02) {
    let x = cx + r / (angle * 0.1) * cos(angle);
    let y = cy + r / (angle * 0.1) * sin(angle);
    curveVertex(x, y);
  }
  endShape();
}

function drawSwirls() {
  for (let i = 0; i < 1000; i++) {
    let x = random(width);
    let y = random(height);
    let size = noise(x * 0.005, y * 0.005) * 50;
    let angle = random(TWO_PI);
    drawSwirl(x, y, size, angle);
  }
}

function drawSwirl(x, y, size, angle) {
  push();
  translate(x, y);
  rotate(angle);
  noFill();
  stroke(150, 150, 200, 150);
  strokeWeight(2);
  beginShape();
  for (let a = 0; a < TWO_PI; a += 0.2) {
    let sx = cos(a) * size * sin(a * 5);
    let sy = sin(a) * size * sin(a * 5);
    vertex(sx, sy);
  }
  endShape();
  pop();
}

