function drawCircleForms(x, y, size) {
  noFill();
  strokeWeight(2);
  for (let i = 0; i < 50; i++) {
    let offsetX = random(-size * 0.1, size * 0.1);
    let offsetY = random(-size * 0.1, size * 0.1);
    let dia = size * random(0.3, 0.7);
    let edgeCol = lerpColor(color(110, 20, 30, 150), color(150, 110, 90, 150), random(1));
    stroke(edgeCol);
    ellipse(x + offsetX, y + offsetY, dia, dia);
  }
}

function drawVeil(cx, cy, dia) {
  for (let i = 0; i < 50; i++) {
    let angle = random(TWO_PI);
    let r = dia * 0.5 * sqrt(random());
    let x = cx + r * cos(angle);
    let y = cy + r * sin(angle);
    let opacity = map(dist(cx, cy, x, y), 0, dia * 0.5, 255, 30);

    let veilCol = lerpColor(color(240, 240, 245, opacity), color(200, 200, 220, opacity), random());
    stroke(veilCol);
    noFill();

    beginShape();
    for (let j = 0; j < 8; j++) {
      let offsetX = random(-20, 20);
      let offsetY = random(-20, 20);
      let posAngle = map(j, 0, 7, 0, TWO_PI);
      let posX = x + offsetX + (15 * cos(posAngle));
      let posY = y + offsetY + (15 * sin(posAngle));
      vertex(posX, posY);
    }
    endShape(CLOSE);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
