  let colors = [
    color(230, 57, 70, 200),  // crimson red
    color(255, 209, 102, 150),  // yellow
    color(34, 157, 97, 200),  // green
    color(59, 89, 152, 120),  // blue
    color(20, 20, 31, 170)  // dark ink
  ];

  drawBackgroundShapes(colors);
  drawMainForm(colors);
}

function drawBackgroundShapes(colors) {
  for (let i = 0; i < 50; i++) {
    let x = random(width);
    let y = random(height);
    let r = random(100, 300);
    fill(random(colors));
    noStroke();
    ellipse(x, y, r, r);
  }
}

function drawMainForm(colors) {
  push();
  translate(width / 2, height / 2);
  let points = [];
  let layers = 10;
  let maxR = 700;

  for (let i = 0; i < TWO_PI; i += TWO_PI / 100) {
    for (let layer = 0; layer < layers; layer++) {
      let offset = noise(layer * 10 + cos(i) * 2, layer * 10 + sin(i) * 2) * 300;
      let r = map(layer, 0, layers, 100, maxR) + offset;
      points.push(createVector(r * cos(i), r * sin(i)));
    }
  }

  for (let i = 0; i < layers - 1; i++) {
    beginShape(TRIANGLE_STRIP);
    for (let j = 0; j < points.length / layers; j++) {
      fill(lerpColor(colors[i % colors.length], colors[(i + 1) % colors.length], j / (points.length / layers)));
      let idx1 = i * points.length / layers + j;
      let idx2 = (i + 1) * points.length / layers + j;
      vertex(points[idx1].x, points[idx1].y);
      vertex(points[idx2].x, points[idx2].y);
    }
    endShape();
  }
  pop();
}

