    fill(petalColor);
    noStroke();
    rotate(angle);
    beginShape();
    for (let j = 0; j <= 19; j++) {
      let theta = map(j, 0, 19, 0, PI);
      let xx = (cos(theta) * petalWidth) / 2;
      let yy = sin(theta) * petalLength;
      vertex(xx, yy);
