function drawBranch(x, y, length, angle) {
  if (length < 5) return;
  let xEnd = x + cos(angle) * length;
  let yEnd = y - sin(angle) * length;
  line(x, y, xEnd, yEnd);

  let newLength = length * random(0.6, 0.8);
  drawBranch(xEnd, yEnd, newLength, angle - PI / 6);
  drawBranch(xEnd, yEnd, newLength, angle + PI / 4);
}

