function drawBranches(len, level) {
  if (level === 0) return;
  strokeWeight(6 * level / 10);
  let angle = PI / 4;

  for (let i = -1; i <= 1; i += 2) {
    push();
    rotate(i * angle * noise(frameCount * 0.001));
    line(0, 0, 0, -len);
    translate(0, -len);
    drawBranches(len * 0.68, level - 1);
    pop();
  }
