  noFill();
  strokeWeight(2);
  stroke(col);

  let angleOffset = random(TWO_PI);

  for (let i = 0; i < layers; i++) {
    beginShape();
    let noiseFactor = random(0.3, 1.0);
    for (let angle = 0; angle < TWO_PI; angle += PI / 50) {
      let r = size + 20 * noise(noiseFactor * cos(angle + angleOffset), noiseFactor * sin(angle + angleOffset), i * 0.1);
      let x = centerX + r * cos(angle);
      let y = centerY + r * sin(angle);
      curveVertex(x, y);
    }
    endShape(CLOSE);
  }
}
