  let colors = ['#FF9AA2', '#FFB7B2', '#FFDAC1', '#E2F0CB', '#B5EAD7', '#C7CEEA'];
  let shapes = 50;

  for (let i = 0; i < shapes; i++) {
    let x = random(width);
    let y = random(height);
    let size = random(80, 300);
    let col = color(random(colors));
    let alpha = random(100, 200);
    col.setAlpha(alpha);

    fill(col);
    beginShape();
    let offset = random(5, 10);
    for (let a = 0; a < TWO_PI; a += random(PI/20, PI/15)) {
      let r = size + noise(x * offset, y * offset) * 50;
      let sx = x + cos(a) * r;
      let sy = y + sin(a) * r;
      vertex(sx, sy);
    }
    endShape(CLOSE);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  drawLove();
}

function drawLove() {
  let cols = 16;
  let rows = 20;
  let tileSize = width / cols;

  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      let xpos = x * tileSize;
      let ypos = y * tileSize;

      let n = noise(x * 0.3, y * 0.3) * 6;
      drawBlob(xpos, ypos, n, tileSize);
    }
  }
}

function drawBlob(x, y, n, size) {
  push();
  translate(x + size / 2, y + size / 2);
  rotate(PI * random());

  let points = [];
  let layers = 6;
  for (let i = 0; i < layers; i++) {
    let alpha = map(i, 0, layers, 100, 255);
    let col = lerpColor(color(255, 128, 128, alpha), color(128, 200, 255, alpha), i / layers);

    beginShape();
    noFill();
    stroke(col);
    strokeWeight(3);

    for (let angle = 0; angle <= TWO_PI; angle += PI / 12) {
      let r = size * (0.3 + noise(cos(angle) * n, sin(angle) * n) * 0.5);
      let xpos = cos(angle) * r;
      let ypos = sin(angle) * r;
      vertex(xpos, ypos);
      points.push({ x: xpos, y: ypos });
    }

    endShape(CLOSE);
  }

  pop();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function draw() {
  drawSky();
  drawEclipse(800, 520, 360);
  drawHazeBand(880, 1280);
  drawArchGlow(800, 1120, 320, 580);
  drawRiver(800, 1120, 2000);
  drawArch(800, 1120, 320, 580, color(8, 9, 12));
  drawDistantSilhouettes();
  drawTree(360, 1640, -PI/2, 310, 16, 6);
  drawBoat(960, 1300, 46, 1);
  drawMist(800, 1140, 620, 360, 540);
  drawMoths(800, 1120, 180);
}

function drawSky() {
  noStroke();
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let c;
    if (t < 0.55) {
      c = lerpColor(color(12, 14, 22), color(28, 32, 41), t / 0.55);
    } else {
      c = lerpColor(color(28, 32, 41), color(16, 18, 23), (t - 0.55) / 0.45);
    }
    stroke(c);
    line(0, y, width, y);
  }
}

function drawEclipse(cx, cy, r) {
  // Subtle corona
  noFill();
  for (let i = 0; i < 170; i++) {
    let t = i / 169;
    let rad = r + t * 300;
    let a = map(1 - t, 0, 1, 2, 38);
    let glow = color(214, 178, 88, a);
    stroke(glow);
    strokeWeight(2 + 2.5 * (1 - t));
    ellipse(cx, cy, rad * 2, rad * 2);
  }
  // Irregular warm glare
  for (let k = 0; k < 80; k++) {
    let ang = TWO_PI * k / 80.0 + noise(k * 0.1) * 0.2;
    let rr = r + 170 + noise(k * 0.2, 8) * 120;
    let x = cx + cos(ang) * rr;
    let y = cy + sin(ang) * rr;
    stroke(230, 200, 120, 14);
    strokeWeight(1.8);
    point(x, y);
  }
  // Dark disc
  noStroke();
  fill(6, 7, 10);
  circle(cx, cy, r * 2 * 0.98);
}

function drawHazeBand(y1, y2) {
  // Horizontal haze around horizon
  for (let y = y1; y < y2; y += 2) {
    let t = map(y, y1, y2, 0, 1);
    let a = 18 * (1 - pow(t, 0.8));
    let c = color(200, 210, 222, a);
    stroke(c);
    strokeWeight(2);
    let n1 = (noise(y * 0.01, 30) - 0.5) * 80;
    line(0, y + n1, width, y + n1);
  }
}

function drawArchShape(cx, baseY, w, h) {
  // Composite rounded arch: rect + top circle
  let capR = w / 2;
  let bodyH = h - capR;
  let x = cx - w / 2;
  let y = baseY - bodyH;
  rect(x, y, w, bodyH);
  ellipse(cx, y, w, w);
}

function drawArchGlow(cx, baseY, w, h) {
  // Soft warm glow built from layered larger arches
  noStroke();
  for (let i = 28; i >= 1; i--) {
    let ww = w + i * 10;
    let hh = h + i * 8;
    let a = map(i, 1, 28, 2, 32);
    fill(220, 190, 110, a);
    push();
    drawArchShape(cx, baseY, ww, hh);
    pop();
  }
}

function drawArch(cx, baseY, w, h, col) {
  noStroke();
  fill(col);
  drawArchShape(cx, baseY, w, h);
  // Inner subtle cool rim
  noFill();
  for (let i = 0; i < 16; i++) {
    let ww = w - i * 6;
    let hh = h - i * 5;
    stroke(60, 70, 90, map(i, 0, 15, 70, 0));
    strokeWeight(1.2);
    push();
    beginShape();
    // approximate by drawing rect+ellipse outlines
    // Body
    let capR = ww / 2;
    let bodyH = hh - capR;
    let x = cx - ww / 2;
    let y = baseY - bodyH;
    // Outline body
    line(x, y, x, baseY);
    line(cx + ww / 2, y, cx + ww / 2, baseY);
    // Top arc
    noFill();
    arc(cx, y, ww, ww, PI, TWO_PI);
    pop();
  }
}

function drawRiver(centerX, yEnd, yStart) {
  let steps = 320;
  let ys = [];
  let ls = [];
  let rs = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;                // 0 at top (yEnd), 1 at bottom (yStart)
    let y = lerp(yEnd, yStart, t);
    let amp = 240 * pow(t, 1.15);
    let center = centerX + (noise(y * 0.003, 10) - 0.5) * 2 * amp + (noise(t * 1.7) - 0.5) * 28;
    let w = 24 + 640 * pow(t, 0.9);
    let edgeWander = (noise(y * 0.01, 55) - 0.5) * 36 * pow(t, 1.3);
    let left = center - w / 2 + edgeWander;
    let right = center + w / 2 + edgeWander * 0.2;
    ys.push(y);
    ls.push(left);
    rs.push(right);
  }

  // Fill river with layered quads for gradient and texture
  noStroke();
  for (let i = 0; i < steps; i++) {
    let t = i / steps;
    let c = lerpColor(color(66, 76, 90, 195), color(170, 184, 198, 220), pow(t, 1.5));
    fill(c);
    beginShape();
    vertex(ls[i], ys[i]);
    vertex(rs[i], ys[i]);
    vertex(rs[i + 1], ys[i + 1]);
    vertex(ls[i + 1], ys[i + 1]);
    endShape(CLOSE);
  }

  // Soft cooler banks to deepen edges
  for (let i = 0; i < steps - 1; i += 2) {
    let shade = map(i, 0, steps, 180, 60);
    stroke(20, 22, 28, shade);
    strokeWeight(3);
    line(ls[i], ys[i], ls[i + 1], ys[i + 1]);
    line(rs[i], ys[i], rs[i + 1], ys[i + 1]);
  }

  // Surface glints
  for (let k = 0; k < 240; k++) {
    let idx = floor(map(pow(random(), 1.3), 0, 1, 0, steps - 4));
    let fx = lerp(ls[idx], rs[idx], 0.15 + 0.7 * random());
    let fy = ys[idx] + random(-2, 2);
    let len = 10 + 40 * pow(idx / steps, 1.1) * random(0.4, 1);
    strokeWeight(1.5 + 0.6 * random());
    stroke(235, 240, 246, 90 + 80 * random());
    line(fx - len * 0.5, fy, fx + len * 0.5, fy);
  }

  // Faint vertical reflection glow beneath the arch
  noStroke();
  for (let i = 0; i < 60; i++) {
    let a = map(i, 0, 59, 28, 0);
    fill(220, 200, 140, a);
    let w = 30 + i * 10;
    let h = 18 + i * 14;
    ellipse(centerX, yEnd + 40 + i * 10, w, h);
  }
}

function drawDistantSilhouettes() {
  // Low, dark, distant ridges at the horizon to cradle the river
  noFill();
  for (let j = 0; j < 3; j++) {
    let y = 1080 + j * 18;
    stroke(12 + j * 6, 14 + j * 6, 18 + j * 6, 220);
    strokeWeight(2 + j);
    beginShape();
    for (let x = 0; x <= width; x += 6) {
      let n = noise(x * 0.004, j * 0.3) * 40;
      vertex(x, y + n);
    }
    endShape();
  }
}

function drawTree(x, y, ang, len, thick, depth) {
  push();
  translate(x, y);
  stroke(8, 9, 12, 235);
  branch(ang, len, thick, depth);
  pop();

  function branch(a, l, t, d) {
    push();
    rotate(a);
    strokeWeight(t);
    line(0, 0, 0, -l);
    translate(0, -l);
    if (d > 0 && l > 16) {
      let n = 2 + floor(random(2));
      for (let i = 0; i < n; i++) {
        let na = a + random(-PI / 4.2, -PI / 7) + i * random(PI / 10, PI / 7);
        let nl = l * random(0.58, 0.74);
        let nt = max(1, t * random(0.62, 0.75));
        branch(na - a, nl, nt, d - 1);
      }
      // Small thorny twigs
      for (let k = 0; k < 2; k++) {
        let ta = random(-PI / 3, PI / 3);
        let tl = l * random(0.18, 0.3);
        let tt = max(0.8, t * 0.4);
        push();
        rotate(ta);
        strokeWeight(tt);
        line(0, 0, 0, -tl);
        pop();
      }
    }
    pop();
  }
}

function drawBoat(x, y, s, dir) {
  push();
  translate(x, y);
  scale(dir, 1);
  noStroke();
  fill(12, 14, 18, 240);
  beginShape();
  vertex(-s * 1.4, 0);
  bezierVertex(-s * 0.6, s * 0.28, s * 0.6, s * 0.28, s * 1.3, 0);
  vertex(s * 0.9, s * 0.28);
  vertex(-s * 1.0, s * 0.28);
  endShape(CLOSE);

  // Mast
  stroke(12, 14, 18, 240);
  strokeWeight(max(1.2, s * 0.08));
  line(0, 0, 0, -s * 1.2);

  // Small lantern glow (life's last light)
  noStroke();
  fill(230, 200, 120, 150);
  ellipse(s * 0.16, -s * 0.7, s * 0.22, s * 0.22);
  fill(250, 230, 170, 70);
  ellipse(s * 0.16, -s * 0.7, s * 0.5, s * 0.5);
  pop();
}

function drawMoths(cx, baseY, count) {
  // Moths rising from river, clustering near the arch
  for (let i = 0; i < count; i++) {
    let ring = pow(random(), 1.9);
    let r = 30 + ring * 420 + random(-12, 12);
    let a = random(-PI * 0.1, PI * 1.1);
    let x = cx + cos(a) * r * random(0.8, 1.05) + (noise(i * 0.1) - 0.5) * 40;
    let y = baseY - 60 - sin(a) * r * random(0.6, 1.2);
    let s = 3 + pow(random(), 2.0) * 10;
    let rot = random(TWO_PI);
    let warm = color(238, 224, 186, 160 + random(60));
    let cool = color(240, 238, 230, 80);
    push();
    translate(x, y);
    rotate(rot);
    noStroke();
    fill(warm);
    triangle(-s, 0, s, 0, 0, -s * 1.7);
    fill(cool);
    ellipse(0, -s * 0.3, s * 1.2, s * 0.6);
    pop();
  }
}

function drawMist(cx, cy, w, h, count) {
  noStroke();
  for (let i = 0; i < count; i++) {
    let u = random(-1, 1);
    let v = random(-1, 1);
    let x = cx + u * w * 0.6 + (noise(i * 0.2, 3) - 0.5) * 140;
    let y = cy + v * h * 0.45 + (noise(i * 0.17, 7) - 0.5) * 120;
    let r = 60 + pow(random(), 2.2) * 240;
    let a = 6 + pow(1 - abs(u), 2.2) * 16 + random(0, 8);
    fill(210, 220, 232, a);
    ellipse(x, y, r, r * random(0.7, 1.2));
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  background(0);
  drawGradientBackground();
  drawStars(360);
  drawFogBand(720, 1340, 0.6);

  // Distant banks/ridges
  drawRidge(950, 90, 0.003, color(13, 19, 26, 255));
  drawRidge(1040, 70, 0.0023, color(9, 14, 20, 255));

  // Portal glow
  const portalX = width * 0.5;
  const portalY = 920;
  const portalW = 320;
  const portalH = 520;
  drawPortal(portalX, portalY, portalW, portalH);

  // River
  let yEnd = 1020;
  let yStart = height + 20;
  const river = buildRiver(yStart, yEnd);
  drawRiverShape(river.left, river.right, color(28, 39, 51, 230));
  drawRiverHighlights(yStart, yEnd);

  // Soft halo bleed near water
  drawWaterGlow(portalX, portalY + portalH * 0.45, portalW * 1.3, portalH * 0.6);

  // Boat and figure
  let yBoat = 1300;
  drawBoatAtY(yBoat, yStart, yEnd);

  // Moths around the portal
  drawMothsAroundPortal(portalX, portalY - portalH * 0.1, 60);

  // Foreground grasses
  drawGrasses();

  // Subtle vignette
  vignette();
}

function drawGradientBackground() {
  noStroke();
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let c1 = color(10, 12, 18);
    let c2 = color(16, 22, 29);
    let c = lerpColor(c1, c2, t);
    fill(c);
    rect(0, y, width, 1);
  }
}

function drawStars(n) {
  noStroke();
  for (let i = 0; i < n; i++) {
    let x = random(width);
    let y = random(0, 850);
    let r = random(0.5, 2.4);
    let twinkle = random(30, 110);
    fill(220, 235, 255, twinkle);
    ellipse(x, y, r, r);
    if (random() < 0.15) {
      fill(255, 250, 220, twinkle * 0.6);
      ellipse(x + random(-0.5, 0.5), y + random(-0.5, 0.5), r * 0.6, r * 0.6);
    }
  }
}

function drawFogBand(y1, y2, strength) {
  push();
  stroke(255);
  for (let y = y1; y <= y2; y += 2) {
    let g = gaussian(map(y, y1, y2, -1.3, 1.3));
    let a = map(noise(y * 0.01, 5), 0, 1, 6, 38) * g * 1.8 * strength;
    stroke(240, 245, 250, a);
    line(0, y, width, y);
  }
  pop();
}

function drawRidge(yBase, amp, scale, col) {
  noStroke();
  fill(col);
  beginShape();
  vertex(0, height);
  vertex(0, yBase + 120);
  for (let x = 0; x <= width; x += 8) {
    let y = yBase - noise(x * scale, yBase * 0.0007) * amp - noise(x * 0.02, 8) * 6;
    vertex(x, y);
  }
  vertex(width, yBase + 120);
  vertex(width, height);
  endShape(CLOSE);
}

function drawPortal(px, py, pw, ph) {
  push();
  noStroke();
  let inner = color(255, 246, 220);
  let mid = color(242, 210, 150);
  let outer = color(175, 128, 76);
  for (let i = 0; i <= 140; i++) {
    let t = i / 140;
    let w = lerp(pw * 1.7, 3, t);
    let h = lerp(ph * 1.7, 3, t);
    let col = lerpColor(outer, inner, pow(t, 1.25));
    let a = lerp(8, 130, pow(t, 1.35));
    fill(red(col), green(col), blue(col), a);
    ellipse(px, py, w, h);
  }
  // Soft inner aperture hint
  fill(255, 250, 236, 42);
  ellipse(px, py, pw * 0.7, ph * 0.7);

  // Subtle vertical beam haze
  for (let i = -6; i <= 6; i++) {
    let alpha = map(abs(i), 0, 6, 20, 2);
    fill(255, 245, 225, alpha);
    rect(px + i * 6 - 2, py - ph * 0.9, 4, ph * 1.8);
  }
  pop();
}

function drawWaterGlow(px, py, w, h) {
  push();
  noStroke();
  let inner = color(255, 246, 220, 40);
  let outer = color(175, 128, 76, 4);
  for (let i = 0; i <= 90; i++) {
    let t = i / 90;
    let ww = lerp(w * 1.8, w * 0.1, t) * 1.4;
    let hh = lerp(h * 0.9, 2, t);
    let col = lerpColor(outer, inner, pow(t, 1.4));
    fill(col);
    ellipse(px, py + t * 130, ww, hh);
  }
  pop();
}

function buildRiver(yStart, yEnd) {
  let left = [], right = [];
  for (let y = yStart; y >= yEnd; y -= 5) {
    let cx = centerXAt(y, yStart, yEnd);
    let hw = riverHalfWidthAt(y, yStart, yEnd);
    let jitterL = map(noise(y * 0.01 + 30), 0, 1, -12, 12);
    let jitterR = map(noise(y * 0.01 + 60), 0, 1, -12, 12);
    let lx = cx - hw + jitterL - noise(y * 0.05, 9) * 2.5;
    let rx = cx + hw + jitterR + noise(y * 0.05, 19) * 2.5;
    left.push({ x: lx, y: y });
    right.push({ x: rx, y: y });
  }
  return { left, right };
}

function drawRiverShape(left, right, col) {
  noStroke();
  fill(col);
  beginShape();
  for (let i = 0; i < left.length; i++) {
    vertex(left[i].x, left[i].y);
  }
  for (let i = right.length - 1; i >= 0; i--) {
    vertex(right[i].x, right[i].y);
  }
  endShape(CLOSE);
}

function drawRiverHighlights(yStart, yEnd) {
  push();
  strokeCap(ROUND);
  for (let y = yStart; y >= yEnd; y -= 10) {
    let cx = centerXAt(y, yStart, yEnd);
    let hw = riverHalfWidthAt(y, yStart, yEnd) * 0.78;
    let p = noise(y * 0.08, 12);
    if (p > 0.56) {
      let len = map(p, 0.56, 1, hw * 0.2, hw * 1.4);
      let a = map(p, 0.56, 1, 18, 70) * gaussian(map(y, yEnd, yStart, -1.2, 1.2));
      stroke(215, 228, 238, a);
      strokeWeight(map(p, 0.56, 1, 0.8, 2.2));
      line(cx - len * 0.5, y + random(-0.6, 0.6), cx + len * 0.5, y + random(-0.6, 0.6));
    }
  }
  pop();
}

function drawBoatAtY(yBoat, yStart, yEnd) {
  let cx = centerXAt(yBoat, yStart, yEnd);
  let hw = riverHalfWidthAt(yBoat, yStart, yEnd);
  let boatW = constrain(hw * 0.9, 70, 160);
  let boatH = boatW * 0.18;

  push();
  noStroke();
  // Hull
  fill(12, 15, 20, 245);
  beginShape();
  vertex(cx - boatW * 0.55, yBoat + boatH * 0.1);
  vertex(cx + boatW * 0.55, yBoat + boatH * 0.1);
  vertex(cx + boatW * 0.35, yBoat + boatH * 0.65);
  vertex(cx - boatW * 0.35, yBoat + boatH * 0.65);
  endShape(CLOSE);

  // Subtle rim
  stroke(28, 32, 38, 180);
  strokeWeight(2);
  line(cx - boatW * 0.5, yBoat + boatH * 0.12, cx + boatW * 0.5, yBoat + boatH * 0.12);
  noStroke();

  // Figure
  let fx = cx - boatW * 0.06;
  let fy = yBoat + boatH * 0.15;
  fill(18, 22, 28, 250);
  ellipse(fx, fy - boatH * 0.55, boatH * 0.55, boatH * 0.55); // head
  beginShape(); // body/cloak
  vertex(fx - boatH * 0.35, fy - boatH * 0.2);
  vertex(fx + boatH * 0.45, fy - boatH * 0.2);
  vertex(fx + boatH * 0.15, fy + boatH * 1.15);
  vertex(fx - boatH * 0.55, fy + boatH * 1.1);
  endShape(CLOSE);

  // Oar
  push();
  stroke(40, 46, 54, 220);
  strokeWeight(4);
  let angle = radians(-55);
  let ox1 = fx + cos(angle) * (boatW * 0.05);
  let oy1 = fy + sin(angle) * (boatW * 0.05);
  let ox2 = fx + cos(angle) * (boatW * 0.85);
  let oy2 = fy + sin(angle) * (boatW * 0.85);
  line(ox1, oy1, ox2, oy2);
  pop();

  // Small ripple by oar tip
  let tipX = fx + cos(angle) * (boatW * 0.85);
  let tipY = fy + sin(angle) * (boatW * 0.85);
  noFill();
  stroke(210, 224, 236, 70);
  strokeWeight(1.5);
  ellipse(tipX, tipY + 2, 18, 5);
  pop();
}

function drawMothsAroundPortal(px, py, count) {
  push();
  noStroke();
  for (let i = 0; i < count; i++) {
    let dx = randomGaussian(0, 120);
    let dy = randomGaussian(0, 90);
    let x = px + dx;
    let y = py + dy - abs(dx) * 0.05;
    let r = random(7, 16);
    let rot = random(-PI / 4, PI / 4) * 0.5;
    let glow = map(abs(dx) + abs(dy), 0, 260, 120, 10);
    fill(255, 242, 210, glow);
    drawMoth(x, y, r, rot);
    // tiny core
    fill(255, 250, 235, glow * 0.6);
    ellipse(x, y, r * 0.15, r * 0.15);
  }
  pop();
}

function drawMoth(x, y, r, rot) {
  push();
  translate(x, y);
  rotate(rot);
  noStroke();
  ellipse(-r * 0.25, 0, r * 0.6, r * 0.35);
  ellipse(r * 0.25, 0, r * 0.6, r * 0.35);
  pop();
}

function drawGrasses() {
  push();
  stroke(8, 10, 12, 230);
  strokeWeight(2);
  noFill();
  for (let i = 0; i < 140; i++) {
    let side = i % 2 === 0 ? 0 : width;
    let baseX = side === 0 ? random(-40, 300) : random(width - 300, width + 40);
    let baseY = height + random(0, 40);
    let h = random(120, 260);
    let bend = side === 0 ? random(60, 180) : -random(60, 180);
    bezier(
      baseX, baseY,
      baseX + bend * 0.3, baseY - h * 0.35,
      baseX + bend * 0.7, baseY - h * 0.7,
      baseX + bend, baseY - h
    );
    if (random() < 0.35) {
      let tipX = baseX + bend;
      let tipY = baseY - h;
      line(tipX - 6, tipY + 2, tipX + 4, tipY - 4);
    }
  }
  pop();
}

function vignette() {
  push();
  noStroke();
  for (let i = 0; i < 120; i++) {
    let t = i / 120;
    let a = map(t, 0, 1, 0, 120);
    fill(6, 8, 10, a * 0.5);
    let m = lerp(max(width, height) * 1.6, max(width, height) * 0.8, t);
    ellipse(width * 0.5, height * 0.5, m * 2.0, m * 2.2);
  }
  pop();
}

function centerXAt(y, yStart, yEnd) {
  let t = constrain((y - yEnd) / (yStart - yEnd), 0, 1);
  let amp = 220 * pow(t, 1.25);
  return width * 0.5 + map(noise(y * 0.002 + 10), 0, 1, -amp, amp);
}

function riverHalfWidthAt(y, yStart, yEnd) {
  let t = constrain((y - yEnd) / (yStart - yEnd), 0, 1);
  return map(pow(t, 0.9), 0, 1, 18, 235);
}

function gaussian(x) {
  // Simple bell around 0
  return exp(-0.5 * x * x);
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  colorMode(RGB, 255, 255, 255, 255);
  background(0);
  let W = width, H = height;

  // Sky gradient
  let skyTop = color(12, 14, 28);
  let skyBot = color(55, 40, 62);
  for (let y = 0; y < H; y++) {
    let t = constrain(y / (H * 0.9), 0, 1);
    let c = lerpColor(skyTop, skyBot, t);
    stroke(c);
    line(0, y, W, y);
  }

  // Sparse stars at upper sky
  strokeWeight(1);
  for (let y = 0; y < 800; y += 3) {
    for (let x = 0; x < W; x += 3) {
      let n = noise(x * 0.01, y * 0.012);
      if (n > 0.86 + noise(x * 0.02 + 10, y * 0.02 + 3) * 0.06) {
        let a = map(n, 0.86, 1, 40, 130);
        stroke(240, 240, 255, a);
        point(x, y);
        if (random() < 0.02) {
          // tiny twinkle cluster
          point(x + 1, y);
          point(x, y + 1);
        }
      }
    }
  }

  // Eclipse (black sun) with faint corona
  let sunC = createVector(W * 0.5, H * 0.26);
  let rInner = 180;
  noStroke();
  fill(0, 0, 0, 255);
  ellipse(sunC.x, sunC.y, rInner * 2, rInner * 2);

  // Subtle rim glow
  for (let i = 1; i <= 90; i++) {
    let rr = rInner + i * 1.3;
    let t = i / 90;
    let col = lerpColor(color(90, 75, 60, 8), color(160, 150, 140, 2), t);
    noFill();
    stroke(col);
    strokeWeight(1);
    ellipse(sunC.x, sunC.y, rr * 2, rr * 2);
  }

  // Corona wisps
  strokeWeight(1.2);
  for (let a = 0; a < TWO_PI; a += radians(2.5)) {
    let base = rInner + 100 + noise(cos(a) * 0.8 + 4, sin(a) * 0.8 + 7) * 60;
    let jitter = noise(cos(a) * 1.2 + 11, sin(a) * 1.2 + 21);
    let len = 12 + jitter * 60;
    let x1 = sunC.x + cos(a) * base;
    let y1 = sunC.y + sin(a) * base;
    let x2 = sunC.x + cos(a) * (base + len);
    let y2 = sunC.y + sin(a) * (base + len);
    let alpha = map(len, 12, 72, 12, 60);
    stroke(195, 185, 175, alpha * 0.5);
    line(x1, y1, x2, y2);
  }

  // Horizon mist band
  let horizonY = 1150;
  for (let y = int(horizonY - 220); y < horizonY + 80; y += 2) {
    let a = map(noise(y * 0.01, 1.7), 0, 1, 0, 60) * smoothstep(horizonY + 60, horizonY - 220, y);
    stroke(240, 235, 245, a);
    line(0, y, W, y);
  }

  // Ground gradient and texture
  let groundTop = color(58, 50, 60);
  let groundBot = color(22, 20, 18);
  for (let y = horizonY; y < H; y++) {
    let t = map(y, horizonY, H, 0, 1);
    let base = lerpColor(groundTop, groundBot, t);
    let n = noise(y * 0.02, 9.3);
    let shade = map(n, 0, 1, -10, 18);
    let c = color(
      red(base) + shade,
      green(base) + shade * 0.7,
      blue(base) + shade * 0.5
    );
    stroke(c);
    line(0, y, W, y);
    // subtle horizontal scratches
    if (random() < 0.02) {
      stroke(0, 8);
      line(random(W), y, random(W), y + 1);
    }
  }

  // Pool (still water)
  let poolC = createVector(W * 0.5, H * 0.78);
  let poolW = 940;
  let poolH = 220;
  noStroke();
  fill(8, 10, 14, 220);
  ellipse(poolC.x, poolC.y, poolW, poolH);

  // Pool shadow and edge darkening
  noFill();
  for (let i = 0; i < 18; i++) {
    let a = map(i, 0, 17, 45, 6);
    stroke(0, a);
    ellipse(poolC.x, poolC.y + i * 1.2, poolW - i * 12, poolH - i * 3);
  }

  // Ripples (quiet)
  for (let i = 0; i < 7; i++) {
    let t = i / 6;
    let a = map(t, 0, 1, 22, 6);
    noFill();
    stroke(205, 210, 220, a);
    let dW = poolW * (1 - t * 0.18);
    let dH = poolH * (1 - t * 0.18);
    ellipse(poolC.x, poolC.y - 6 - t * 10, dW, dH);
  }

  // Reflection hint from eclipse
  noStroke();
  fill(120, 110, 100, 18);
  ellipse(poolC.x - 40, poolC.y - 30, poolW * 0.3, poolH * 0.2);

  // Reeds around near shore
  drawReedsRing(poolC.x, poolC.y, poolW, poolH);

  // Stones (quiet cairns)
  drawStonePile(W * 0.23, H * 0.85, 1.0);
  drawStonePile(W * 0.77, H * 0.86, 0.96);

  // Moths spiraling from pool to eclipse
  drawMoths(poolC, sunC);

  // Foreground mist veils over ground and pool
  for (let y = int(H * 0.68); y < H; y += 3) {
    let f = noise(2 + y * 0.006);
    let a = map(f, 0, 1, 0, 28) * smoothstep(H, H * 0.72, y);
    stroke(240, 240, 250, a);
    line(0, y, W, y);
  }

  // Vignette
  vignette();
}

function drawReedsRing(cx, cy, w, h) {
  push();
  stroke(28, 26, 24, 150);
  strokeWeight(1.3);
  noFill();
  let startA = radians(210);
  let endA = radians(330);
  let count = 120;
  for (let i = 0; i < count; i++) {
    let a = lerp(startA, endA, i / (count - 1)) + random(-0.05, 0.05);
    let px = cx + (w * 0.5) * cos(a);
    let py = cy + (h * 0.5) * sin(a);
    let len = random(60, 180) * map(sin(a), -1, 1, 0.6, 1.2);
    let lean = map(px, cx - w * 0.5, cx + w * 0.5, 0.7, -0.7) + random(-0.2, 0.2);
    drawReed(px, py + 6, len, lean, i);
    if (random() < 0.2) {
      // denser tuft
      drawReed(px + random(-8, 8), py + 8, len * random(0.7, 1.1), lean + random(-0.15, 0.15), i * 10 + 13);
    }
  }
  pop();
}

function drawReed(x, y, len, lean, seed) {
  push();
  randomSeed(1 + seed * 9999);
  stroke(34, 32, 30, 160);
  let x1 = x, y1 = y;
  let x2 = x + len * 0.2 * lean, y2 = y - len * 0.5;
  let x3 = x + len * 0.42 * lean, y3 = y - len;
  bezier(x1, y1, x1, y1 - len * 0.4, x2, y2, x3, y3);

  // Leaf
  if (random() < 0.6) {
    stroke(40, 38, 36, 140);
    let lx1 = x + random(-6, 6);
    let ly1 = y - random(len * 0.2, len * 0.6);
    let lx2 = lx1 + random(-25, 25);
    let ly2 = ly1 - random(22, 48);
    bezier(lx1, ly1, lx1 + 10 * lean, ly1 - 12, lx2, ly2 + 8, lx2, ly2);
  }
  // Seed head
  if (random() < 0.35) {
    noStroke();
    fill(60, 58, 56, 180);
    ellipse(x3, y3, random(6, 10), random(10, 18));
  }
  pop();
}

function drawStonePile(x, y, scaleF) {
  push();
  let baseCol = color(62, 58, 64);
  let darkCol = color(28, 26, 28);
  let lightCol = color(160, 155, 150, 40);

  function stone(sx, sy, w, h) {
    push();
    translate(sx, sy);
    noStroke();
    fill(lerpColor(baseCol, darkCol, 0.35));
    ellipse(0, 0, w, h);
    // highlight
    fill(lerpColor(baseCol, color(190), 0.3));
    ellipse(-w * 0.18, -h * 0.18, w * 0.55, h * 0.45);
    // subtle cracks
    stroke(0, 18);
    strokeWeight(1);
    let ccount = int(random(1, 3));
    for (let i = 0; i < ccount; i++) {
      let ax = random(-w * 0.25, w * 0.25);
      let ay = random(-h * 0.1, h * 0.1);
      line(ax - w * 0.15, ay, ax + w * 0.15, ay + random(-3, 3));
    }
    pop();
  }

  // Stack stones
  let s = scaleF;
  stone(x, y, 200 * s, 70 * s);
  stone(x - 70 * s, y - 40 * s, 160 * s, 62 * s);
  stone(x + 60 * s, y - 50 * s, 140 * s, 58 * s);
  stone(x - 10 * s, y - 95 * s, 110 * s, 48 * s);
  if (random() < 0.8) stone(x + 20 * s, y - 130 * s, 80 * s, 38 * s);

  // Ambient shadow
  noStroke();
  fill(0, 30);
  ellipse(x + 10 * s, y + 30 * s, 260 * s, 50 * s);
  pop();
}

function drawMoths(poolC, sunC) {
  let N = 240;
  // Spiral path from pool to sun
  function pathPos(s) {
    s = constrain(s, 0, 1);
    let y = lerp(poolC.y - 40, sunC.y + 0, s);
    let amp = lerp(0, 220, s);
    let x = width * 0.5
      + sin(s * TWO_PI * 2.6 + s * 1.1) * amp * 0.35
      + cos(s * TWO_PI * 1.2) * amp * 0.1
      + (noise(s * 3.0, 8.1) - 0.5) * 40 * (1 - s * 0.7);
    return createVector(x, y);
  }

  for (let i = 0; i < N; i++) {
    let s = pow(random(), 0.85); // slightly denser near pool
    let p = pathPos(s);
    let p2 = pathPos(min(1, s + 0.01));
    let ang = atan2(p2.y - p.y, p2.x - p.x);
    let sc = map(s, 0, 1, 1.3, 0.5) * random(0.85, 1.2);
    let whiten = map(s, 0, 1, 220, 255);
    let a = map(s, 0, 1, 230, 140);

    // jitter
    p.x += randomGaussian() * 8 * (1 - s * 0.7);
    p.y += randomGaussian() * 4 * (1 - s * 0.5);

    drawMothShape(p.x, p.y, ang - HALF_PI, sc, color(whiten, whiten, whiten, a));
    // faint motion echo
    if (random() < 0.3) {
      let back = p5.Vector.lerp(p, p2, -0.6);
      drawMothShape(back.x, back.y, ang - HALF_PI, sc * 0.9, color(whiten, whiten, whiten, a * 0.18));
    }
  }
}

function drawMothShape(x, y, rot, sc, col) {
  push();
  translate(x, y);
  rotate(rot);
  scale(sc);
  noStroke();
  // Wings
  fill(col);
  let w = 12, h = 9;
  ellipse(-w * 0.7, 0, w * 1.5, h);
  ellipse(w * 0.7, 0, w * 1.5, h);
  // Body
  fill(60, 60, 70, alpha(col) * 0.8);
  rectMode(CENTER);
  rect(0, 0, 2.2, 12, 1);
  // Antennae
  stroke(120, 120, 130, alpha(col) * 0.6);
  strokeWeight(0.8);
  noFill();
  bezier(0, -4, -3, -8, -6, -9, -7, -10);
  bezier(0, -4, 3, -8, 6, -9, 7, -10);
  pop();
}

function vignette() {
  push();
  noFill();
  let maxR = max(width, height) * 0.9;
  for (let i = 0; i < 200; i++) {
    let t = i / 199;
    let a = map(t, 0, 1, 0, 120) * pow(t, 2.2);
    stroke(0, a);
    strokeWeight(2);
    rectMode(CENTER);
    rect(width / 2, height / 2, width * (1 + t * 0.3), height * (1 + t * 0.3), 40);
  }
  pop();
}

// Smoothstep helper
function smoothstep(edge0, edge1, x) {
  let t = constrain((x - edge0) / (edge1 - edge0), 0, 1);
  return t * t * (3 - 2 * t);
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  colorMode(HSB, 360, 100, 100, 100);
  angleMode(RADIANS);
  noLoop();
}

function draw() {
  drawSkyGradient();
  addStars(0.62, 0.16);
  drawEclipse(width * 0.5, height * 0.22, 260);

  // Far horizon glow band
  vGradRect(0, 1050, width, 240, color(30, 50, 25, 10), color(55, 40, 20, 4));

  // Foreground dusk wash
  vGradRect(0, 1350, width, 650, color(245, 25, 10, 18), color(260, 30, 6, 100));

  // Side trees
  push();
  stroke(230, 40, 20, 80);
  drawTree(190, 1550, 280, -PI/2 + 0.18, 0, 7);
  drawTree(width-190, 1580, 300, -PI/2 - 0.2, 0, 7);
  pop();

  // Central arch and inner light
  let archX = width * 0.5;
  let archBaseY = 1400;
  let archW = 640;
  let archH = 920;
  drawPortal(archX, archBaseY, archW, archH);

  // River from portal
  drawRiver(archX, archBaseY, 85, 210);

  // Lilies at bottom
  drawLiliesBand(120);

  // Moths near the threshold
  drawMoths(archX, archBaseY, 46);

  // Low mist/fog
  drawFog(0.6);

  // Subtle grain
  addGrain(2200, 6);
}

function drawSkyGradient() {
  let topC = color(230, 40, 7, 100);
  let midC = color(245, 35, 9, 100);
  let botC = color(265, 35, 8, 100);
  for (let y = 0; y < height; y++) {
    let t = y / (height - 1);
    let c = lerpColor(lerpColor(topC, midC, constrain(map(y, 0, height*0.6, 0, 1), 0, 1)), botC, constrain(map(y, height*0.6, height, 0, 1), 0, 1));
    stroke(c);
    line(0, y, width, y);
  }
}

function vGradRect(x, y, w, h, c1, c2) {
  for (let i = 0; i < h; i++) {
    let t = i / max(1, h - 1);
    let c = lerpColor(c1, c2, t);
    stroke(c);
    line(x, y + i, x + w, y + i);
  }
}

function addStars(threshold, density) {
  push();
  noStroke();
  for (let y = 0; y < height * 0.55; y += 6) {
    for (let x = 0; x < width; x += 6) {
      let n = noise(x * 0.002, y * 0.002);
      if (n > 1 - density && random() < map(y, 0, height*0.55, 0.22, 0.04)) {
        let b = map(n, 1 - density, 1, 60, 100);
        fill(210, 20, b, 85);
        let jitterX = random(-1.5, 1.5);
        let jitterY = random(-1.5, 1.5);
        ellipse(x + jitterX, y + jitterY, random(1.2, 2.4), random(1.2, 2.4));
      }
    }
  }
  pop();
}

function drawEclipse(cx, cy, R) {
  push();
  noFill();
  // Halo
  for (let i = 220; i > 0; i--) {
    let t = i / 220;
    let a = pow(1 - t, 2) * 22 + 6;
    stroke(210, 20, 90, a);
    ellipse(cx, cy, (R + 60 + i) * 2, (R + 60 + i) * 2);
  }
  // Subtle ring tint
  for (let i = 0; i < 60; i++) {
    let a = map(i, 0, 59, 35, 0);
    stroke(48, 40, 90, a);
    ellipse(cx, cy, (R + 18 + i) * 2, (R + 18 + i) * 2);
  }
  // Dark disk
  noStroke();
  fill(235, 40, 5, 98);
  ellipse(cx, cy, R * 2.02, R * 2.02);
  pop();
}

function drawPortal(x, baseY, w, h) {
  let r = w / 2;
  // Inner scene graphics
  let pg = createGraphics(w, h);
  pg.colorMode(HSB, 360, 100, 100, 100);
  pg.angleMode(RADIANS);

  // Radiant gradient inside
  for (let iy = 0; iy < h; iy++) {
    let t = iy / (h - 1);
    // Pale top to warm base
    let cTop = pg.color(55, 20, 100, 98);
    let cMid = pg.color(90, 20, 95, 98);
    let cBot = pg.color(45, 30, 90, 98);
    let c = lerpColor(lerpColor(cTop, cMid, constrain(map(iy, 0, h*0.6, 0, 1), 0, 1)), cBot, constrain(map(iy, h*0.6, h, 0, 1), 0, 1));
    pg.stroke(c);
    pg.line(0, iy, w, iy);
  }

  // Gentle radial glow
  pg.noFill();
  for (let i = 180; i > 0; i--) {
    let a = map(i, 0, 180, 0, 26);
    pg.stroke(56, 25, 100, a);
    pg.ellipse(w/2, h*0.35, i*2.6, i*2.4);
  }

  // Distant hills
  pg.noStroke();
  for (let k = 0; k < 3; k++) {
    let yy = h*0.65 + k*18;
    pg.fill(100, 25, 45 - k*3, 40 - k*6);
    pg.beginShape();
    pg.vertex(0, yy + 200);
    for (let ix = 0; ix <= w; ix += 6) {
      let n = noise(k*100 + ix*0.02, k*40 + 3);
      let yv = yy - n*40 - k*20;
      pg.vertex(ix, yv);
    }
    pg.vertex(w, yy + 200);
    pg.endShape(CLOSE);
  }

  // Small sprout at threshold
  let sy = h - 30;
  pg.stroke(110, 40, 30, 80);
  pg.strokeWeight(2);
  pg.noFill();
  pg.bezier(w/2, sy, w/2 + 4, sy - 20, w/2 - 4, sy - 46, w/2 + 2, sy - 62);
  pg.noStroke();
  pg.fill(110, 35, 70, 90);
  pg.push(); pg.translate(w/2 + 2, sy - 62); pg.rotate(-0.6);
  pg.ellipse(0, 0, 16, 8); pg.pop();
  pg.push(); pg.translate(w/2 + 2, sy - 62); pg.rotate(0.6);
  pg.ellipse(0, 0, 16, 8); pg.pop();

  // Floating dust
  pg.noStroke();
  for (let i = 0; i < 220; i++) {
    let px = random(40, w-40);
    let py = random(h*0.1, h*0.7);
    let a = map(py, h*0.1, h*0.7, 65, 12);
    pg.fill(55, 10, 100, a);
    pg.ellipse(px, py, random(1.2, 2.2), random(1.2, 2.2));
  }

  // Mask for arch shape
  let maskG = createGraphics(w, h);
  maskG.noStroke();
  maskG.fill(0);
  maskG.rect(0, 0, w, h);
  maskG.fill(255);
  let L = h - r;
  let yTopVert = h - L;
  maskG.beginShape();
  maskG.vertex(0, h);
  maskG.vertex(0, yTopVert);
  let da = PI / 100;
  for (let a = PI; a >= 0; a -= da) {
    let vx = w/2 + cos(a)*r;
    let vy = yTopVert - sin(a)*r;
    maskG.vertex(vx, vy);
  }
  maskG.vertex(w, yTopVert);
  maskG.vertex(w, h);
  maskG.endShape(CLOSE);

  let img = pg.get();
  let msk = maskG.get();
  img.mask(msk);
  image(img, x - w/2, baseY - h);

  // Arch frame
  push();
  noFill();
  stroke(230, 35, 12, 90);
  strokeWeight(44);
  // verticals
  let yTV = baseY - L;
  line(x - w/2, baseY, x - w/2, yTV);
  line(x + w/2, baseY, x + w/2, yTV);
  // top arc
  arc(x, yTV, w, w, PI, TWO_PI);
  // inner rim highlight
  stroke(230, 25, 18, 45);
  strokeWeight(16);
  line(x - w/2 + 8, baseY, x - w/2 + 8, yTV + 2);
  line(x + w/2 - 8, baseY, x + w/2 - 8, yTV + 2);
  arc(x, yTV + 1, w - 16, w - 16, PI, TWO_PI);
  pop();

  // Shadow under arch
  push();
  noStroke();
  for (let i = 0; i < 80; i++) {
    let a = map(i, 0, 79, 28, 0);
    fill(230, 40, 5, a);
    ellipse(x, baseY + 6 + i*0.8, w*0.8 + i*10, 20 + i*3);
  }
  pop();
}

function drawRiver(x0, y0, w0, w1) {
  // Build a meandering path downward using noise
  let pts = [];
  let steps = 220;
  let y = y0;
  let x = x0;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    y = y0 + t * (height - y0 + 40);
    let n = noise(0.003 * y, 4.2) - 0.5;
    let bend = 120 * n + 40 * sin(y * 0.004);
    x = x0 + bend * pow(1 - t, 0.2);
    pts.push({x, y});
  }

  // Layered strokes to simulate width and glow
  push();
  strokeCap(ROUND);
  for (let k = 8; k >= 0; k--) {
    let a = map(k, 8, 0, 18, 70);
    let b = map(k, 8, 0, 76, 100);
    let sHue = 200;
    stroke(sHue, 25, b, a);
    noFill();
    beginShape();
    for (let i = 0; i < pts.length; i++) {
      let t = i / (pts.length - 1);
      let w = lerp(w0, w1, t) + k * 6;
      strokeWeight(w);
      vertex(pts[i].x, pts[i].y);
    }
    endShape();
  }
  // Soft edges with darker overlay
  stroke(230, 40, 8, 30);
  beginShape();
  for (let i = 0; i < pts.length; i++) {
    let t = i / (pts.length - 1);
    let w = lerp(w0, w1, t) + 2;
    strokeWeight(w);
    vertex(pts[i].x, pts[i].y);
  }
  endShape();
  pop();
}

function drawTree(x, y, len, ang, layer, maxLayer) {
  if (layer > maxLayer || len < 12) return;
  let sw = map(layer, 0, maxLayer, 9, 1.2);
  strokeWeight(sw);
  stroke(235, 40, 15, 85);
  let nx = x + cos(ang) * len;
  let ny = y + sin(ang) * len;
  line(x, y, nx, ny);

  let branches = 2 + (layer > 2 ? int(random(0, 2)) : 0);
  for (let i = 0; i < branches; i++) {
    let aOff = random(-0.7, 0.7) * map(layer, 0, maxLayer, 0.6, 0.9);
    let newAng = ang + aOff;
    let newLen = len * random(0.62, 0.78);
    drawTree(nx, ny, newLen, newAng, layer + 1, maxLayer);
  }
}

function drawLiliesBand(count) {
  push();
  for (let i = 0; i < count; i++) {
    let x = map(i, 0, count-1, -40, width+40) + random(-20, 20);
    let y = random(height - 220, height - 40) + 30 * noise(i * 0.12);
    let s = random(0.6, 1.3);
    let r = random(-0.3, 0.3);
    drawLily(x, y, s, r);
  }
  pop();
}

function drawLily(x, y, s, rot) {
  push();
  translate(x, y);
  rotate(rot);
  scale(s);
  noStroke();
  // Petals
  for (let i = 0; i < 5; i++) {
    let a = i * TWO_PI / 5.0;
    push();
    rotate(a);
    fill(0, 0, 100, 85);
    ellipse(0, -10, 34, 18);
    pop();
  }
  // Inner shadow
  fill(230, 10, 85, 18);
  ellipse(0, 0, 18, 12);
  // Center
  fill(48, 60, 96, 90);
  ellipse(0, 0, 6, 6);
  // Leaves
  push();
  rotate(0.4);
  fill(110, 35, 35, 60);
  ellipse(20, 14, 36, 12);
  pop();
  push();
  rotate(-0.4);
  fill(110, 35, 30, 55);
  ellipse(-22, 16, 32, 10);
  pop();
  pop();
}

function drawMoths(cx, cy, count) {
  push();
  for (let i = 0; i < count; i++) {
    let ang = random(TWO_PI);
    let rad = random(40, 300);
    let x = cx + cos(ang) * rad + random(-10, 10);
    let y = cy - 200 + sin(ang) * rad*0.6 + random(-10, 10);
    let s = random(0.5, 1.1);
    let r = random(-PI, PI);
    let glow = map(rad, 40, 300, 80, 20);
    drawMoth(x, y, s, r, glow);
  }
  pop();
}

function drawMoth(x, y, s, rot, glow) {
  push();
  translate(x, y);
  rotate(rot);
  scale(s);
  noStroke();
  // Glow
  for (let i = 8; i > 0; i--) {
    fill(55, 10, 100, map(i, 8, 0, glow*0.35, 0));
    ellipse(0, 0, 10 + i*6, 6 + i*3);
  }
  // Body
  fill(230, 20, 60, 70);
  rectMode(CENTER);
  rect(0, 0, 2, 8, 1);
  // Wings
  fill(0, 0, 100, 95);
  push(); rotate(-0.2); ellipse(-6, 0, 14, 10); pop();
  push(); rotate(0.2); ellipse(6, 0, 14, 10); pop();
  pop();
}

function drawFog(strength) {
  push();
  noStroke();
  for (let i = 0; i < 1800; i++) {
    let x = random(-100, width + 100);
    let y = random(height * 0.55, height + 60);
    let n = noise(x * 0.003, y * 0.003);
    let a = map(n, 0, 1, 0, 16) * strength;
    fill(230, 20, 95, a);
    let w = 60 + 120 * n;
    let h = 20 + 50 * n;
    ellipse(x, y, w, h);
  }
  pop();
}

function addGrain(count, alpha) {
  loadPixels();
  // Draw sparse overlay grain as transparent points
  push();
  stroke(0, 0, 100, alpha);
  for (let i = 0; i < count; i++) {
    let x = int(random(width));
    let y = int(random(height));
    let b = random(60, 100);
    stroke(0, 0, b, alpha);
    point(x, y);
  }
  pop();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  colorMode(RGB, 255, 255, 255, 255);
  background(0);
  drawBackgroundGradient();
  drawMist();
  let cx = width * 0.5;
  let cy = height * 0.38;
  drawHalo(cx, cy, 420);
  // Subtle distant ground shapes
  drawDistantRidges();
  // Build luminous river path toward halo
  let path = buildPath(cy + 40);
  drawRiver(path);
  // Foreground stones
  drawStones(path);
  // Small ascending wings
  drawAscents(path, cy);
  // Bottom fog for depth
  drawBottomFog();
}

// Gradient sky
function drawBackgroundGradient() {
  let topCol = color(10, 14, 20);
  let botCol = color(36, 49, 59);
  for (let y = 0; y < height; y++) {
    let t = y / (height - 1);
    let c = lerpColor(topCol, botCol, pow(t, 0.85));
    stroke(c);
    line(0, y, width, y);
  }
}

// Soft noise mist
function drawMist() {
  push();
  blendMode(SCREEN);
  noFill();
  mistLayer(1100, 28, 1.35, color(50, 70, 88), 16, 0.00145, 0.9);
  mistLayer(900, 36, 1.1, color(25, 35, 48), 14, 0.0012, 0.6);
  mistLayer(700, 46, 0.95, color(90, 110, 130), 10, 0.00165, 0.5);
  pop();
}

function mistLayer(count, steps, stepSize, col, alpha, scale, jitter) {
  stroke(red(col), green(col), blue(col), alpha);
  strokeWeight(1.2);
  for (let i = 0; i < count; i++) {
    let x = random(width);
    let y = random(height);
    beginShape();
    for (let s = 0; s < steps; s++) {
      let ang = noise(x * scale, y * scale) * TAU * 2.0;
      x += cos(ang) * stepSize + (random(-jitter, jitter) * 0.15);
      y += sin(ang) * stepSize + (random(-jitter, jitter) * 0.15);
      vertex(x, y);
    }
    endShape();
  }
}

// Halo/eclipsed light
function drawHalo(cx, cy, R) {
  push();
  noStroke();
  // Outer glow
  for (let r = R; r > 0; r -= 2) {
    let inv = 1 - r / R;
    let a = map(pow(inv, 1.4), 0, 1, 2, 80);
    fill(232, 228, 208, a);
    ellipse(cx, cy, r * 2, r * 2);
  }
  // Dark inner disc to form a ring
  let inner = R * 0.64;
  for (let r = inner; r > 0; r -= 1) {
    let a = map(r, inner, 0, 0, 230);
    fill(14, 16, 20, a);
    ellipse(cx, cy, r * 2, r * 2);
  }
  // Veil arcs
  blendMode(SCREEN);
  stroke(245, 238, 216, 16);
  noFill();
  for (let k = 0; k < 60; k++) {
    let rr = R * random(0.85, 1.2);
    let a0 = random(-PI * 0.25, PI * 0.25);
    let a1 = a0 + random(PI * 0.4, PI * 0.8);
    strokeWeight(random(0.5, 1.2));
    arc(cx + random(-8, 8), cy + random(-6, 6), rr * 2, rr * 2, a0, a1);
  }
  pop();
}

// Distant low ridges at the horizon area
function drawDistantRidges() {
  push();
  noStroke();
  let baseY = height * 0.65;
  for (let layer = 0; layer < 3; layer++) {
    let yOff = baseY + layer * 40;
    let c = color(20 + layer * 6, 26 + layer * 7, 32 + layer * 8, 70 - layer * 18);
    fill(c);
    beginShape();
    vertex(0, yOff + 200);
    for (let x = 0; x <= width; x += 8) {
      let n = noise(x * 0.0015, layer * 1.2);
      let y = yOff - n * (60 - layer * 12);
      vertex(x, y);
    }
    vertex(width, yOff + 200);
    endShape(CLOSE);
  }
  pop();
}

// Build path of the luminous river
function buildPath(stopY) {
  let pts = [];
  let x = width * 0.5 + random(-30, 30);
  let y = height - 60;
  let len = 0;
  let amp = 2.6;
  while (y > stopY && len < 1400) {
    let n = noise(y * 0.003, len * 0.0007);
    let dx = map(n, 0, 1, -amp, amp);
    x += dx;
    y -= 2.25;
    x = constrain(x, 220, width - 220);
    pts.push(createVector(x, y));
    amp = map(y, height, 0, 3.2, 1.0);
    len++;
  }
  return pts;
}

function widthAtY(y, topY) {
  let w0 = 160;
  let w1 = 28;
  return map(y, height - 60, topY, w0, w1, true);
}

// Draw luminous river
function drawRiver(pts) {
  if (pts.length < 3) return;
  let topY = pts[pts.length - 1].y;
  // Soft bloom
  push();
  noStroke();
  blendMode(SCREEN);
  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    let w = widthAtY(p.y, topY);
    let a = map(i, 0, pts.length - 1, 20, 10);
    fill(250, 244, 210, a);
    ellipse(p.x + random(-0.5, 0.5), p.y + random(-0.5, 0.5), w * 2.4, w * 1.4);
  }
  // Core
  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    let w = widthAtY(p.y, topY);
    fill(245, 242, 220, 185);
    ellipse(p.x, p.y, w * 0.95, w * 0.7);
  }
  // Silky highlight line
  stroke(255, 252, 230, 42);
  noFill();
  beginShape();
  for (let i = 0; i < pts.length; i += 2) {
    vertex(pts[i].x, pts[i].y);
  }
  endShape();
  pop();
}

// Foreground stones (steles)
function drawStones(path) {
  push();
  let N = 11;
  let xs = [];
  for (let i = 0; i < N; i++) xs.push(map(i, 0, N - 1, 80, width - 80) + random(-30, 30));
  // Shuffle slightly
  xs.sort((a, b) => a - b);
  // Draw
  for (let i = 0; i < N; i++) {
    let x = xs[i] + random(-10, 10);
    let baseY = height - random(70, 160);
    let w = random(46, 92);
    let h = random(220, 420);
    // skip if overlaps center too much to keep river visible
    if (x > width * 0.45 && x < width * 0.55 && random() < 0.5) continue;
    drawStone(x, baseY, w, h, path);
  }
  pop();
}

function drawStone(cx, baseY, w, h, path) {
  push();
  let left = cx - w * 0.5;
  let right = cx + w * 0.5;
  let topY = baseY - h;
  // Build a softly irregular polygon
  let segs = 10;
  let leftPts = [];
  let rightPts = [];
  let seed = random(1000);
  for (let i = 0; i <= segs; i++) {
    let t = i / segs;
    let yy = lerp(topY + random(-8, 8) * (1 - t), baseY + random(-10, 10) * t, t);
    let jl = map(noise(seed + i * 0.2), 0, 1, -6, 6);
    let jr = map(noise(seed + 100 + i * 0.2), 0, 1, -6, 6);
    leftPts.push(createVector(left + jl, yy));
    rightPts.push(createVector(right + jr, yy));
  }
  // Dark body
  noStroke();
  fill(12, 14, 18, 240);
  beginShape();
  for (let i = 0; i < leftPts.length; i++) vertex(leftPts[i].x, leftPts[i].y);
  for (let i = rightPts.length - 1; i >= 0; i--) vertex(rightPts[i].x, rightPts[i].y);
  endShape(CLOSE);
  // Edge wear highlights facing the river
  let riverX = riverMedianX(path);
  let facingLeft = cx > riverX;
  let edgePts = facingLeft ? leftPts : rightPts;
  let innerPts = facingLeft ? rightPts : leftPts;
  let glowCol = color(240, 232, 206, 26);
  let strokes = 12;
  blendMode(SCREEN);
  for (let s = 0; s < strokes; s++) {
    let t = s / strokes;
    let a = 20 - s * 1.3;
    stroke(red(glowCol), green(glowCol), blue(glowCol), a);
    strokeWeight(1.5);
    beginShape();
    for (let i = 0; i < edgePts.length; i++) {
      let ex = lerp(edgePts[i].x, innerPts[i].x, 0.12 + t * 0.18);
      let ey = edgePts[i].y + sin(i * 0.7 + s) * 0.4;
      vertex(ex, ey);
    }
    endShape();
  }
  // Stone skin speckles
  blendMode(BLEND);
  noStroke();
  for (let k = 0; k < 130; k++) {
    let rx = random(left + 2, right - 2);
    let ry = random(topY + 4, baseY - 2);
    let a = random(8, 18);
    fill(30, 34, 40, a);
    rect(rx, ry, 1, 1);
  }
  pop();
}

function riverMedianX(path) {
  if (!path || path.length === 0) return width * 0.5;
  let sum = 0;
  let cnt = 0;
  for (let i = 0; i < path.length; i += 20) {
    sum += path[i].x;
    cnt++;
  }
  return cnt > 0 ? sum / cnt : width * 0.5;
}

// Ascending small winged flecks
function drawAscents(path, cy) {
  if (path.length < 20) return;
  push();
  blendMode(SCREEN);
  for (let i = 0; i < 85; i++) {
    let idx = floor(map(i, 0, 84, path.length * 0.45, path.length - 8) + random(-14, 14));
    idx = constrain(idx, 2, path.length - 3);
    let p0 = path[idx - 1];
    let p1 = path[idx + 1];
    let dir = p5.Vector.sub(p1, p0);
    let ang = atan2(dir.y, dir.x) - HALF_PI + random(-0.5, 0.5) * 0.4;
    let nrm = createVector(-dir.y, dir.x).normalize();
    let off = random(-80, 80);
    let pos = p5.Vector.add(path[idx], p5.Vector.mult(nrm, off));
    let tTop = map(pos.y, cy, height, 0, 1, true);
    let s = map(tTop, 0, 1, 5, 12) * map(abs(off), 0, 80, 1.0, 0.7, true);
    let col = color(245, 238, 220, map(tTop, 0, 1, 140, 90));
    drawWingedFleck(pos.x, pos.y, s, ang, col);
  }
  pop();
}

function drawWingedFleck(x, y, s, rot, col) {
  push();
  translate(x, y);
  rotate(rot);
  noStroke();
  fill(col);
  // wings
  beginShape();
  vertex(0, 0);
  bezierVertex(-s * 1.0, -s * 0.5, -s * 1.2, s * 0.2, -s * 0.8, s * 0.6);
  bezierVertex(-s * 0.2, s * 0.2, -s * 0.1, 0, 0, 0);
  endShape(CLOSE);
  beginShape();
  vertex(0, 0);
  bezierVertex(s * 1.0, -s * 0.5, s * 1.2, s * 0.2, s * 0.8, s * 0.6);
  bezierVertex(s * 0.2, s * 0.2, s * 0.1, 0, 0, 0);
  endShape(CLOSE);
  // faint body
  stroke(255, 245, 230, alpha(col) * 0.6);
  strokeWeight(0.7);
  line(0, -s * 0.2, 0, s * 0.25);
  pop();
}

// Ground fog to settle the base
function drawBottomFog() {
  push();
  noStroke();
  blendMode(SCREEN);
  for (let y = height - 280; y < height; y += 4) {
    let t = map(y, height - 280, height, 0, 1);
    let a = map(t, 0, 1, 0, 60);
    fill(240, 238, 220, a * 0.25);
    rect(0, y, width, 4);
  }
  blendMode(BLEND);
  pop();
}

function setup() {
  const W = 1600, H = 2000;
  createCanvas(W, H);
  randomSeed(1);
  noiseSeed(1);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();

  const cx = W / 2;
  const cy = H / 2;
  const voidW = 420;
  const voidH = 1600;

  // Background gradient
  let cTop = color(36, 22, 100, 100);   // warm, bright
  let cBot = color(230, 45, 10, 100);   // deep indigo
  noStroke();
  for (let y = 0; y < H; y++) {
    let t = y / (H - 1);
    let c = lerpColor(cTop, cBot, t);
    stroke(c);
    line(0, y, W, y);
  }

  // Subtle vertical mist to add depth
  noFill();
  for (let i = 0; i < 200; i++) {
    let x = random(-200, W + 200);
    let sw = random(40, 120);
    let a = map(i, 0, 199, 2, 6);
    stroke(230, 15, 95, a);
    line(x, -200, x + sw, H + 200);
  }

  function insideVoid(x, y, scale = 1) {
    let dx = x - cx;
    let dy = y - cy;
    let a = (voidW * 0.5) * scale;
    let b = (voidH * 0.5) * scale;
    return (dx * dx) / (a * a) + (dy * dy) / (b * b) <= 1;
  }

  // Threads drifting toward center
  drawThreads(900);

  // Motes drifting in the field
  drawMotes(1300);

  // Central void and soft gradient darkness
  drawVoidAndRim();

  // Distant ripples suggesting echo
  drawRipples(6);

  function drawThreads(n) {
    let cWarm = color(28, 40, 95, 100);
    let cCool = color(210, 25, 82, 100);
    for (let k = 0; k < n; k++) {
      let side = floor(random(4));
      let p;
      if (side === 0) p = createVector(-random(50, 220), random(-100, H + 100));
      else if (side === 1) p = createVector(W + random(50, 220), random(-100, H + 100));
      else if (side === 2) p = createVector(random(-100, W + 100), -random(50, 220));
      else p = createVector(random(-100, W + 100), H + random(50, 220));

      let steps = floor(random(140, 230));
      let prev = p.copy();
      let baseW = random(0.6, 1.8);

      for (let s = 0; s < steps; s++) {
        let toC = createVector(cx - p.x, cy - p.y);
        let d = toC.mag();
        let dir = toC.copy().normalize();

        let ang = noise(p.x * 0.001, p.y * 0.001) * TAU * 2.0;
        let curl = p5.Vector.fromAngle(ang).mult(0.8);

        let stepMag = map(d, 0, max(W, H) * 0.8, 0.45, 5.2);
        let v = dir.mult(stepMag).add(curl.mult(0.25));

        let np = p.copy().add(v);

        // Stop when reaching the threshold of the void
        if (insideVoid(np.x, np.y, 1.02)) break;

        // Color shifts with vertical position
        let tY = constrain(np.y / H, 0, 1);
        let col = lerpColor(cWarm, cCool, tY);

        // Fade as they approach the void
        let fade = map(d, 0, sqrt(W * W + H * H) * 0.5, 0.0, 1.0);
        let alpha = constrain(6 + fade * 26, 6, 32);

        stroke(hue(col), saturation(col), brightness(col), alpha);
        strokeWeight(baseW * map(k % 5, 0, 4, 0.9, 1.35));
        line(prev.x, prev.y, np.x, np.y);

        prev = np;
        p = np;

        // Occasional slight widening to suggest braids
        if (random() < 0.02) {
          strokeWeight(baseW * 1.8);
          stroke(hue(col), saturation(col), brightness(col), alpha * 0.6);
          point(np.x + sin(ang) * 0.6, np.y + cos(ang) * 0.6);
        }
      }
    }
  }

  function drawMotes(n) {
    noStroke();
    for (let i = 0; i < n; i++) {
      let x = random(-200, W + 200);
      let y = random(-200, H + 200);

      // Skip if inside void area (slightly expanded margin)
      if (insideVoid(x, y, 1.08)) continue;

      let d = dist(x, y, cx, cy);
      let maxD = sqrt((W * W) + (H * H)) * 0.6;

      let s = random(0.8, 2.4) * map(d, 0, maxD, 0.6, 1.3);
      let br = map(d, 0, maxD, 65, 100);
      let sat = map(d, 0, maxD, 8, 22);
      let al = constrain(map(d, 0, maxD, 10, 65), 8, 70);

      let hueBlend = lerp(36, 210, constrain(y / H, 0, 1));
      fill(hueBlend, sat, br, al * 0.2);
      ellipse(x, y, s * 4.5, s * 4.5);

      fill(hueBlend, sat, br, al);
      ellipse(x, y, s, s);
    }
  }

  function drawVoidAndRim() {
    // Core solid void
    noStroke();
    fill(0, 0, 0, 100);
    ellipse(cx, cy, voidW * 0.86, voidH * 0.86);

    // Deepening darkness toward center (stacked translucent ellipses)
    for (let i = 0; i < 180; i++) {
      let t = i / 179;
      let w = lerp(voidW * 1.45, voidW * 0.2, t);
      let h = lerp(voidH * 1.08, voidH * 0.18, t);
      fill(230, 80, 2, 4); // almost black in HSB
      ellipse(cx, cy, w, h);
    }

    // Luminous threshold rim
    noFill();
    for (let i = 0; i < 90; i++) {
      let t = i / 89;
      let w = voidW + i * 3.0;
      let h = voidH + i * 3.0;
      let sw = lerp(4.0, 0.35, t);
      let rimCol = lerpColor(color(200, 12, 100, 8), color(38, 18, 100, 6), t);
      stroke(rimCol);
      strokeWeight(sw);
      ellipse(cx, cy, w, h);
    }
  }

  function drawRipples(count) {
    noFill();
    for (let j = 1; j <= count; j++) {
      let f = 1.2 + j * 0.35;
      let w = voidW * f + j * 40;
      let h = voidH * f + j * 40;
      let c = color(210, 12, 95, map(j, 1, count, 5, 2));
      stroke(c);
      strokeWeight(0.8);
      ellipse(cx, cy, w, h);
    }
  }
}

