  // Static image; nothing to do here.
}

let W = 1600;
let H = 2000;

let cx, cy, ax, ay;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(W, H);
  noLoop();
}

function draw() {
  cx = width * 0.5;
  cy = height * 0.52;
  ax = width * 0.24;   // horizontal radius of the void
  ay = height * 0.26;  // vertical radius of the void

  colorMode(RGB, 255, 255, 255, 255);
  noStroke();
  background(0);

  // Background gradient
  drawBackground();

  // Subtle atmospheric grain
  drawAtmosphere();

  // Veils (semi-transparent vertical ribbons)
  drawVeils();

  // Faint star-like specks near top
  drawStars();

  // Central void (soft dark ellipse)
  drawVoid();

  // Halo ring around the threshold
  drawHalo();

  // Flowing threads drawn toward the threshold
  drawStreams();

  // Soft motes drifting upward around the threshold
  drawMotes();
}

function drawBackground() {
  let cTop = color(8, 9, 20);
  let cMid = color(22, 21, 34);
  let cBot = color(62, 52, 48);

  for (let y = 0; y < height; y++) {
    let t = y / (height - 1);
    let col;
    if (t < 0.62) {
      let k = smoothstep(0, 0.62, t);
      col = lerpColor(cTop, cMid, k);
    } else {
      let k = smoothstep(0.62, 1.0, t);
      col = lerpColor(cMid, cBot, k);
    }
    stroke(col);
    line(0, y, width, y);
  }
}

function drawAtmosphere() {
  // Soft, large, translucent blotches to add depth
  noStroke();
  for (let i = 0; i < 620; i++) {
    let x = random(-200, width + 200);
    let y = random(-200, height + 200);
    let r = random(70, 320);
    let base = map(y, 0, height, 0.5, 0.9);
    let b = 45 + 40 * base + random(-8, 8);
    let g = 40 + 35 * base + random(-8, 8);
    let a = random(8, 18);
    fill(30 + g, 30 + g * 0.8, 30 + b, a);
    ellipse(x, y, r, r);
  }
}

function drawVeils() {
  noStroke();
  for (let k = 0; k < 13; k++) {
    let w = random(60, 220);
    let off = random(-320, 320);
    let skew = random(-0.6, 0.6);
    let tint = color(210 + random(-10, 10), 210 + random(-10, 10), 220 + random(-10, 10), random(8, 18));
    fill(tint);
    beginShape();
    for (let y = -40; y <= height + 40; y += 18) {
      let n = noise(k * 1.8, y * 0.0015) - 0.5;
      let x = cx + off + n * w * 1.2 + skew * map(y, 0, height, -1, 1) * w * 0.3;
      vertex(x - w * 0.5, y);
    }
    for (let y = height + 40; y >= -40; y -= 18) {
      let n = noise(k * 1.8 + 100, y * 0.0015 + 100) - 0.5;
      let x = cx + off + n * w * 1.2 + skew * map(y, 0, height, -1, 1) * w * 0.3;
      vertex(x + w * 0.5, y);
    }
    endShape(CLOSE);
  }
}

function drawStars() {
  strokeWeight(1.2);
  for (let i = 0; i < 1400; i++) {
    let y = pow(random(), 2.0) * height * 0.35;
    let x = random(width);
    let tw = random(0.5, 1.1);
    let a = random(30, 90);
    stroke(220, 225, 240, a);
    point(x, y);
    if (random() < 0.18) {
      stroke(200, 210, 255, a * 0.6);
      line(x - tw, y, x + tw, y);
    }
  }
}

function drawVoid() {
  // Layer large, semi-transparent dark ellipses to form a soft-edged void
  noStroke();
  for (let i = 0; i < 180; i++) {
    let t = i / 179;
    let rx = lerp(ax * 1.38, ax * 0.15, t);
    let ry = lerp(ay * 1.38, ay * 0.15, t);
    let alpha = lerp(10, 30, t);
    fill(5, 6, 10, alpha);
    ellipse(cx, cy, rx * 2, ry * 2);
  }
  // Deepen the center subtly
  fill(0, 24);
  ellipse(cx, cy, ax * 0.9 * 2, ay * 0.9 * 2);
}

function drawHalo() {
  noFill();
  strokeCap(ROUND);
  // Inner luminous ring
  for (let i = 0; i < 44; i++) {
    let t = i / 43;
    let sw = 1 + pow(t, 1.6) * 18;
    strokeWeight(sw);
    stroke(235, 238, 250, lerp(120, 0, t));
    ellipse(cx, cy, ax * 2 + t * 36, ay * 2 + t * 36);
  }
  // Outer very faint aura
  for (let i = 0; i < 40; i++) {
    let t = i / 39;
    let sw = 1 + pow(t, 1.6) * 26;
    strokeWeight(sw);
    stroke(220, 230, 245, lerp(30, 0, t));
    ellipse(cx, cy, ax * 2.6 + t * 90, ay * 2.6 + t * 90);
  }
}

function drawStreams() {
  strokeCap(ROUND);
  let starts = [];

  // Bottom edge sources
  for (let i = 0; i < 420; i++) {
    let x = map(i, 0, 419, 40, width - 40) + random(-18, 18);
    let y = height - random(10, 40);
    starts.push(createVector(x, y));
  }
  // Side edges
  for (let i = 0; i < 280; i++) {
    let y = map(i, 0, 279, 60, height - 60) + random(-10, 10);
    starts.push(createVector(random(8, 32), y));
    starts.push(createVector(width - random(8, 32), y));
  }
  // Sparse top
  for (let i = 0; i < 160; i++) {
    let x = map(i, 0, 159, 30, width - 30) + random(-12, 12);
    let y = random(10, 50);
    starts.push(createVector(x, y));
  }

  for (let i = 0; i < starts.length; i++) {
    let p = starts[i].copy();
    let baseCol = startColorAt(p.x, p.y);
    let steps = floor(random(180, 320));
    let prev = p.copy();
    for (let s = 0; s < steps; s++) {
      let v = field(p.x, p.y);
      let step = 1.4;
      p.x += v.x * step;
      p.y += v.y * step;

      // Stop conditions: out of bounds or into the void
      if (p.x < -20 || p.x > width + 20 || p.y < -20 || p.y > height + 20) break;
      let e2 = ellipseNorm2(p.x, p.y, cx, cy, ax * 0.92, ay * 0.92);
      if (e2 < 1.0) break;

      // Color fading toward ashen near the threshold and over time
      let gray = color(200, 202, 210);
      let tStep = s / steps;
      let cf = lerpColor(baseCol, gray, tStep * 0.9);
      let ring = ellipseNorm2(p.x, p.y, cx, cy, ax * 1.0, ay * 1.0);
      let fadeN = constrain(map(ring, 0.95, 1.35, 0.0, 1.0), 0, 1);
      let alpha = 70 * (1.0 - tStep) * fadeN + 4;

      stroke(red(cf), green(cf), blue(cf), alpha);
      strokeWeight(0.9 + 0.4 * (1.0 - tStep));
      line(prev.x, prev.y, p.x, p.y);
      prev.set(p);
    }
  }
}

function drawMotes() {
  noStroke();
  for (let i = 0; i < 480; i++) {
    let a = random(TWO_PI);
    let r = (ax * 0.9 + random(-50, 220)) * (0.8 + 0.4 * random());
    let x = cx + cos(a) * r * 0.8 + random(-20, 20);
    let y = cy + sin(a) * r * 1.1 + random(-30, 30);
    let sz = random(1.2, 3.6);
    let alpha = random(10, 40) * (1.0 - constrain(map(ellipseNorm2(x, y, cx, cy, ax * 0.9, ay * 0.9), 0.8, 1.2, 1, 0), 0, 1));
    fill(220, 230, 240, alpha);
    ellipse(x, y, sz, sz);
  }
}

// Vector field directing flow toward the threshold with a gentle swirl
function field(x, y) {
  let dx = x - cx;
  let dy = y - cy;
  let dist = sqrt(dx * dx + dy * dy) + 1e-6;

  // Unit vector toward center
  let ux = -dx / dist;
  let uy = -dy / dist;

  // Swirl perpendicular to center direction
  let px = -uy;
  let py = ux;

  // Strength varies with normalized ellipse distance
  let e2 = ellipseNorm2(x, y, cx, cy, ax, ay);
  let rnorm = sqrt(e2);
  let swirlStrength = 0.65 / (1.0 + 4.0 * abs(rnorm - 1.0));

  // Noise drift
  let ang = noise(x * 0.0016, y * 0.0016) * TWO_PI * 2.0;
  let nx = cos(ang);
  let ny = sin(ang);

  // Assemble
  let vx = ux * 1.4 + px * swirlStrength + nx * 0.30;
  let vy = uy * 1.4 + py * swirlStrength + ny * 0.30;

  // Repulsion if inside the ring to prevent crossing deep into void
  if (e2 < 1.0) {
    let gx = (dx / (ax * ax));
    let gy = (dy / (ay * ay));
    let g = (1.0 - e2) * 7.5;
    vx += gx * g;
    vy += gy * g;
  }

  // Gentle damping far away
  let far = constrain(map(dist, 200, max(width, height) * 0.8, 1.0, 0.6), 0.6, 1.0);
  vx *= far;
  vy *= far;

  return { x: vx, y: vy };
}

function startColorAt(x, y) {
  // Three hues representing "life" tones that will fade toward ash
  let c1 = color(216, 154, 102); // ochre
  let c2 = color(130, 176, 143); // moss
  let c3 = color(118, 146, 210); // slate blue

  let m = noise(x * 0.002, y * 0.002);
  let c;
  if (m < 0.33) {
    let t = map(m, 0.0, 0.33, 0, 1);
    c = lerpColor(c1, c2, t);
  } else if (m < 0.66) {
    let t = map(m, 0.33, 0.66, 0, 1);
    c = lerpColor(c2, c3, t);
  } else {
    let t = map(m, 0.66, 1.0, 0, 1);
    c = lerpColor(c3, c1, t);
  }
  // Slight modulation by height (warmer low, cooler high)
  let hmod = constrain(map(y, 0, height, 0.2, 1.0), 0.2, 1.0);
  let warm = color(210, 150, 110);
  c = lerpColor(c, warm, (1.2 - hmod) * 0.25);
  return c;
}

function ellipseNorm2(x, y, cx, cy, ax, ay) {
  let dx = x - cx;
  let dy = y - cy;
  return (dx * dx) / (ax * ax) + (dy * dy) / (ay * ay);
}

function smoothstep(a, b, x) {
  let t = constrain((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();
}

function draw() {
  let w = width;
  let h = height;
  let cx = w * 0.5;
  let cy = h * 0.52;
  let baseR = 460;

  // Background gradient
  drawVerticalGradient(color(230, 30, 14, 100), color(240, 40, 4, 100));

  // Subtle veils
  drawVeilBlob(cx - 200, cy - 120, 900, 0.7, 0.0, color(230, 15, 10, 6));
  drawVeilBlob(cx + 260, cy + 60, 1050, 0.65, 0.3, color(230, 18, 8, 7));
  drawVeilBlob(cx, cy + 220, 1200, 0.6, 0.9, color(230, 10, 6, 5));

  // Flowing threads moving inward
  drawThreadsFlow(cx, cy, baseR, 320);

  // Central void and its luminous rim
  drawVoidAndRim(cx, cy, baseR);

  // Dust/motes near the threshold
  drawDust(cx, cy, baseR);

  // Vignette
  vignette();
}

function drawVerticalGradient(cTop, cBottom) {
  noStroke();
  for (let y = 0; y < height; y++) {
    let t = y / (height - 1);
    let c = lerpColor(cTop, cBottom, t);
    stroke(c);
    line(0, y, width, y);
  }
}

function drawVeilBlob(cx, cy, baseR, nFreq, rot, col) {
  noStroke();
  fill(col);
  beginShape();
  let steps = 520;
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * TWO_PI;
    let n = noise(cos(a + rot) * nFreq + 5.1, sin(a + rot) * nFreq - 3.7);
    let r = baseR * (0.86 + n * 0.32);
    let x = cx + cos(a) * r;
    let y = cy + sin(a) * r * 1.08;
    vertex(x, y);
  }
  endShape(CLOSE);
}

function drawVoidAndRim(cx, cy, r0) {
  // Distorted dark core
  noStroke();
  fill(230, 20, 0, 100);
  let k = 0.8;
  let amp = 58;
  let off = 12.3;
  beginShape();
  let steps = 720;
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * TWO_PI;
    let n = noise(cos(a) * k + off, sin(a) * k - off * 0.73);
    let r = r0 + (n - 0.5) * 2 * amp;
    let x = cx + cos(a) * r;
    let y = cy + sin(a) * r;
    vertex(x, y);
  }
  endShape(CLOSE);

  // Luminous porous rim
  let layers = 26;
  for (let i = 0; i < layers; i++) {
    let t = i / (layers - 1);
    let rr = r0 + t * 140;
    let aAmp = lerp(38, 10, t);
    let wt = lerp(2.0, 0.35, t);
    let br = lerp(16, 4, t);
    let sa = lerp(8, 4, t);
    let al = lerp(16, 2, t);
    stroke(212 + t * 12, sa, br, al);
    strokeWeight(wt);
    noFill();
    beginShape();
    for (let j = 0; j < steps; j++) {
      let a = (j / steps) * TWO_PI;
      let n = noise(cos(a) * (k + 0.12 * t) + off + t * 0.7, sin(a) * (k + 0.12 * t) - off * 0.73 - t * 0.5);
      let r = rr + (n - 0.5) * 2 * aAmp;
      let x = cx + cos(a) * r;
      let y = cy + sin(a) * r;
      vertex(x, y);
    }
    endShape(CLOSE);
  }
}

function drawThreadsFlow(cx, cy, r0, count) {
  // Flow field-driven threads from canvas edges toward the void
  for (let i = 0; i < count; i++) {
    let s = sampleEdgePoint();
    let pts = [];
    let x = s.x;
    let y = s.y;

    let maxSteps = 320 + floor(random(60));
    for (let j = 0; j < maxSteps; j++) {
      let d = dist(x, y, cx, cy);
      if (d < r0 + 36 + random(-6, 14)) break;
      if (x < -120 || x > width + 120 || y < -120 || y > height + 120) break;

      let ang = atan2(cy - y, cx - x);

      let n1 = noise(x * 0.0012, y * 0.0012);
      let swirl = map(n1, 0, 1, -1, 1) * 0.65;

      // Encourage tangential glide near the boundary
      let near = constrain(map(d, r0 + 260, r0 + 40, 0, 1), 0, 1);
      let bias = (noise(x * 0.002 + 10.0, y * 0.002 - 7.4) - 0.5) * 2.0;
      swirl += bias * 0.35 * near;

      let stepL = 3.2 + 5.6 * constrain(map(d, r0 + 1200, r0 + 60, 1, 0.2), 0.2, 1);

      x += cos(ang + swirl) * stepL;
      y += sin(ang + swirl) * stepL;
      pts.push({ x: x, y: y });
    }

    if (pts.length < 3) continue;

    // Color gradient from warm to pale-cool
    let h1 = random(28, 44);
    let s1 = random(34, 58);
    let b1 = random(74, 92);
    let h2 = random(208, 232);
    let s2 = random(8, 18);
    let b2 = random(88, 98);
    let a1 = random(42, 64);
    let a2 = random(6, 14);

    let cStart = color(h1, s1, b1, a1);
    let cEnd = color(h2, s2, b2, a2);

    // Draw polyline with taper and fade
    for (let k = 1; k < pts.length; k++) {
      let t = k / (pts.length - 1);
      let tt = easeInOutCubic(t);
      let col = lerpColor(cStart, cEnd, tt);
      stroke(col);
      strokeWeight(lerp(1.9, 0.35, tt));
      line(pts[k - 1].x, pts[k - 1].y, pts[k].x, pts[k].y);
    }
  }
}

function drawDust(cx, cy, r0) {
  noStroke();
  let count = 820;
  for (let i = 0; i < count; i++) {
    let a = random(TWO_PI);
    let rr = r0 + 84 + random(-24, 220);
    let x = cx + cos(a) * rr + random(-4, 4);
    let y = cy + sin(a) * rr + random(-4, 4);
    let sz = random(0.6, 2.2);
    let h = random(208, 232);
    let s = random(6, 16);
    let b = random(90, 100);
    let al = random(6, 18);
    fill(h, s, b, al);
    ellipse(x, y, sz, sz);
  }
}

function vignette() {
  let cx = width * 0.5;
  let cy = height * 0.5 + 60;
  noStroke();
  for (let i = 0; i < 120; i++) {
    let t = i / 119;
    let rx = width * (1 + t * 0.55);
    let ry = height * (1 + t * 0.55);
    fill(230, 30, 0, lerp(0, 8, t));
    ellipse(cx, cy, rx, ry);
  }
}

function sampleEdgePoint() {
  let side = floor(random(4));
  let m = 14;
  if (side === 0) return { x: random(width), y: -m };          // top
  if (side === 1) return { x: width + m, y: random(height) };  // right
  if (side === 2) return { x: random(width), y: height + m };  // bottom
  return { x: -m, y: random(height) };                         // left
}

function easeInOutCubic(t) {
  return t < 0.5 ? 4 * t * t * t : 1 - pow(-2 * t + 2, 3) / 2;
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  let cx = width * 0.5;
  let cy = height * 0.5;
  let R = 260; // radius of the central void

  // Palette
  let palette = [
    color(58, 168, 161),  // teal
    color(215, 163, 74),  // amber
    color(122, 92, 169),  // amethyst
    color(162, 59, 59),   // carmine
    color(107, 141, 94),  // moss
    color(185, 194, 201)  // fog
  ];

  // Background vertical gradient
  drawBackgroundGradient(color(8, 10, 16), color(22, 16, 14));

  // Subtle radial mist toward center
  drawRadialMist(cx, cy, color(80, 78, 86, 10), 920, 2.5);

  // Flowing strands spiraling toward the center
  drawFlow(cx, cy, R, palette);

  // Soft concentric, slightly broken rings (threshold)
  drawNoisyRings(cx, cy, R, palette);

  // Soft outer halo near the threshold
  drawHalo(cx, cy, R, palette);

  // Central void
  noStroke();
  fill(0);
  circle(cx, cy, R * 2);

  // Gentle edge emphasis: a very subtle inner rim fade (drawn outside the void)
  stroke(255, 240);
  strokeWeight(0.8);
  noFill();
  for (let k = 0; k < 14; k++) {
    let a = map(k, 0, 13, 32, 0);
    stroke(235, 220, 210, a);
    circle(cx, cy, (R + 2 + k * 1.2) * 2);
  }

  // Vignette to quiet the edges
  drawVignette();
}

function drawBackgroundGradient(cTop, cBottom) {
  noStroke();
  for (let y = 0; y < height; y++) {
    let t = y / (height - 1);
    let base = lerpColor(cTop, cBottom, t);
    // Subtle horizontal temperature drift
    let n = noise(y * 0.005) * 0.08;
    let r = red(base) * (1 - n) + 10 * n;
    let g = green(base) * (1 - n) + 8 * n;
    let b = blue(base) * (1 - n) + 6 * n;
    stroke(r, g, b);
    line(0, y, width, y);
  }
}

function drawRadialMist(cx, cy, c, maxR, step) {
  noStroke();
  for (let r = maxR; r > 0; r -= step) {
    let a = map(r, 0, maxR, 22, 0);
    fill(red(c), green(c), blue(c), a);
    circle(cx, cy, r * 2);
  }
}

function drawFlow(cx, cy, R, palette) {
  strokeCap(ROUND);
  strokeJoin(ROUND);

  let total = 4200; // number of strands
  let maxOuterR = hypot(max(cx, width - cx), max(cy, height - cy)) + 50;

  for (let i = 0; i < total; i++) {
    // Seed positions on a broad annulus
    let ang = random(TWO_PI);
    let rad = random(R + 480, maxOuterR);
    let x = cx + cos(ang) * rad;
    let y = cy + sin(ang) * rad;

    // Pick a base color by blending neighbors in the palette
    let idx = floor(random(palette.length));
    let c1 = palette[idx];
    let c2 = palette[(idx + 1) % palette.length];
    let baseCol = lerpColor(c1, c2, pow(random(), 1.2));

    // Each path gets a subtle personality
    let curlBias = random(-0.15, 0.15);
    let noiseScale = random(0.0012, 0.0022);
    let fragility = random(0.2, 0.8); // how easily strands "break"
    let maxSteps = floor(random(120, 240));

    let px = x, py = y;
    for (let s = 0; s < maxSteps; s++) {
      let dx = cx - px;
      let dy = cy - py;
      let rr = sqrt(dx * dx + dy * dy);

      if (rr <= R + 3) break;
      if (px < -120 || px > width + 120 || py < -120 || py > height + 120) break;

      // Vector field: attraction + swirl + noise
      let ux = dx / (rr + 1e-6);
      let uy = dy / (rr + 1e-6);

      // Perp for swirl
      let pxv = -uy;
      let pyv = ux;

      // Swirl strength varies with radius (more near center)
      let swirl = constrain(map(rr, R, max(width, height) * 0.7, 0.95, 0.25), 0.2, 1.0) + curlBias;

      // Noise drift
      let nvx = noise(px * noiseScale, py * noiseScale) - 0.5;
      let nvy = noise((px + 133.3) * noiseScale, (py + 271.7) * noiseScale) - 0.5;

      // Compose direction
      let vx = ux * 1.0 + pxv * swirl + nvx * 0.65;
      let vy = uy * 1.0 + pyv * swirl + nvy * 0.65;

      // Normalize
      let vm = sqrt(vx * vx + vy * vy) + 1e-6;
      vx /= vm; vy /= vm;

      // Step size scales with distance
      let step = constrain(map(rr, R, max(width, height) * 0.9, 0.45, 3.2), 0.4, 3.5);

      // Color that desaturates and darkens toward center
      let mixEdge = constrain(map(rr, R + 30, max(width, height) * 0.6, 0.0, 1.0), 0.0, 1.0);
      let innerCol = color(34, 38, 42);
      let cc = lerpColor(innerCol, baseCol, pow(mixEdge, 1.35));

      // Alpha varies with distance (thinner near center)
      let alpha = 8 + 52 * pow(mixEdge, 1.15);

      // Occasional "broken" fibers
      let gap = noise(px * 0.01, py * 0.01) > (0.86 + fragility * 0.08);

      // Subtle variation in thickness
      let sw = constrain(map(rr, R, max(width, height), 0.35, 1.2) + (noise(i * 0.01 + s * 0.02) - 0.5) * 0.15, 0.25, 1.5);

      if (!gap) {
        stroke(red(cc), green(cc), blue(cc), alpha);
        strokeWeight(sw);
        line(px, py, px + vx * step, py + vy * step);
      }

      px += vx * step;
      py += vy * step;
    }
  }
}

function drawNoisyRings(cx, cy, R, palette) {
  // Build a soft sequence of rings that feel like a threshold, slightly broken
  let rings = 12;
  for (let i = 0; i < rings; i++) {
    let baseR = R + 36 + i * 38;
    let wobble = 16 + i * 0.7;
    let stepA = 0.01 + i * 0.001;
    let col = ringColor(i, palette);
    let a = map(i, 0, rings - 1, 38, 8);
    stroke(red(col), green(col), blue(col), a);
    strokeWeight(map(i, 0, rings - 1, 0.9, 0.35));
    noFill();

    beginShape();
    for (let a = 0; a < TWO_PI + 0.001; a += stepA) {
      let nx = cos(a) * 0.8;
      let ny = sin(a) * 0.8;
      let n = noise(nx * 0.9 + i * 0.12, ny * 0.9 - i * 0.07);
      let rr = baseR + map(n, 0, 1, -wobble, wobble);
      // occasional micro breaks
      if (noise((a + i) * 1.7) > 0.992) {
        endShape();
        beginShape();
        continue;
      }
      let x = cx + cos(a) * rr;
      let y = cy + sin(a) * rr;
      vertex(x, y);
    }
    endShape(CLOSE);
  }
}

function ringColor(i, palette) {
  let p1 = palette[i % palette.length];
  let p2 = palette[(i + 2) % palette.length];
  let t = 0.35 + 0.4 * sin(i * 0.7);
  return lerpColor(p1, p2, t);
}

function drawHalo(cx, cy, R, palette) {
  noFill();
  let glowCount = 95;
  let outer = R + 160;
  for (let k = 0; k < glowCount; k++) {
    let t = k / (glowCount - 1);
    let rad = lerp(R + 10, outer, t);
    // Warm to cool along the halo
    let warm = color(230, 182, 120);
    let cool = color(120, 180, 175);
    let cc = lerpColor(warm, cool, pow(t, 0.85));
    let a = 28 * (1 - pow(t, 1.55));
    stroke(red(cc), green(cc), blue(cc), a);
    strokeWeight(1.0 - 0.6 * t);
    circle(cx, cy, rad * 2);
  }
}

function drawVignette() {
  // Radial darkening toward the edges
  noStroke();
  let layers = 16;
  for (let i = 0; i < layers; i++) {
    let t = i / (layers - 1);
    let a = 10 * pow(t, 1.8);
    fill(0, a);
    let margin = lerp(0, max(width, height) * 0.35, t);
    rect(-margin, -margin, width + margin * 2, height + margin * 2);
  }
}

// Utility
function hypot(a, b) {
  return sqrt(a * a + b * b);
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function draw() {
  background(0);
  drawBackground();
  let yb = computeRiverBoundary();
  drawStars();
  drawLatticeLeft();
  drawThreadsToVeil();
  drawCentralVeil();
  drawPetalsFlow();
  drawRiver(yb);
  drawGoldAlongBoundary(yb);
  vignette();
}

// Background gradient and subtle vertical haze
function drawBackground() {
  noStroke();
  for (let y = 0; y < height; y += 2) {
    let t = y / (height - 1);
    let c1 = color(8, 10, 16);
    let c2 = color(1, 2, 3);
    let c = lerpColor(c1, c2, pow(t, 1.25));
    fill(c);
    rect(0, y, width, 2);
  }

  // Subtle distant mist column behind the veil
  push();
  let cx = 950;
  for (let i = 0; i < 180; i++) {
    let w = map(i, 0, 179, width * 0.85, 60);
    let a = map(i, 0, 179, 6, 16);
    let yy = height * 0.25 + i * 10 + noise(i * 0.05) * 15;
    fill(20, 24, 32, a);
    rect(cx - w * 0.5, yy, w, 9);
  }
  pop();
}

function drawStars() {
  noStroke();
  let topH = height * 0.65;
  for (let i = 0; i < 3600; i++) {
    let y = pow(random(), 1.35) * topH;
    let x = random(width);
    let s = pow(random(), 2.0) * 2.6 + 0.2;
    let a = map(y, 0, topH, 200, 0) * random(0.3, 1);
    fill(220 + random(-10, 15), 230 + random(-10, 10), 255, a);
    ellipse(x, y, s, s);

    if (random() < 0.006) {
      // faint falling ash streaks
      let len = random(6, 22);
      let off = random(-0.8, 0.8);
      stroke(230, 235, 255, a * 0.35);
      strokeWeight(0.6);
      line(x + off, y - len * 0.5, x - off, y + len * 0.5);
      noStroke();
    }
  }
}

function drawLatticeLeft() {
  // A dissolving scaffold on the left
  let xStart = 130;
  let xEnd = 610;

  // Vertical broken lines
  stroke(170, 176, 190, 90);
  strokeWeight(1);
  for (let x = xStart; x <= xEnd; x += 70) {
    for (let y = 240; y < height - 280; y += 16) {
      let n = noise(x * 0.015, y * 0.015);
      let thresh = 0.53 + (y / height) * 0.12;
      if (n > thresh) {
        let j = map(noise(x * 0.02, y * 0.02, 3.1), 0, 1, -2.0, 2.0);
        let a = map(y, 240, height - 280, 130, 18);
        stroke(170, 176, 190, a);
        line(x + j, y, x + j, y + 14);
      }
    }
  }

  // Horizontal broken lines
  for (let y = 280; y <= height - 400; y += 80) {
    for (let x = xStart; x < xEnd; x += 16) {
      let n = noise(x * 0.015, y * 0.015, 10.5);
      let thresh = 0.54 + (x - xStart) / (xEnd - xStart) * 0.09;
      if (n > thresh) {
        let j = map(noise(x * 0.02, y * 0.02, 7.2), 0, 1, -2.5, 2.5);
        let a = map(y, 280, height - 400, 120, 22);
        stroke(165, 172, 188, a);
        line(x + j, y, x + j + 14, y);
      }
    }
  }

  // Shedding dust
  noStroke();
  for (let i = 0; i < 2200; i++) {
    let bx = random(xStart, xEnd);
    let by = random(260, height - 400);
    let n = noise(bx * 0.015, by * 0.015);
    if (n < 0.53 + (by / height) * 0.12) {
      let dx = -pow(random(), 2.0) * random(0, 80);
      let dy = random(-12, 12);
      let a = map(by, 260, height - 400, 120, 10) * random(0.2, 0.8);
      fill(180 + random(-8, 8), 186 + random(-8, 8), 198 + random(-8, 8), a);
      ellipse(bx + dx, by + dy, random(0.5, 1.8));
    }
  }
}

function drawThreadsToVeil() {
  // Gossamer threads releasing toward the center
  let cx = 950;
  let cy = 1000;
  let xStart = 150;
  let xEnd = 600;
  strokeWeight(0.6);

  for (let t = 0; t < 80; t++) {
    let x0 = random(xStart, xEnd);
    let y0 = random(320, height - 520);

    // Favor points where scaffold existed
    let n = noise(x0 * 0.015, y0 * 0.015);
    if (n < 0.55) continue;

    let x1 = cx + random(-120, 120);
    let y1 = cy + random(-200, 200);

    let c1x = x0 + random(40, 200);
    let c1y = y0 - random(-40, 160);
    let c2x = lerp(x1, x0, 0.35) + random(-90, 90);
    let c2y = lerp(y1, y0, 0.35) + random(-60, 60);

    for (let i = 0; i <= 130; i++) {
      let tt = i / 130;
      let bx = bezierPoint(x0, c1x, c2x, x1, tt);
      let by = bezierPoint(y0, c1y, c2y, y1, tt);
      let f = noise(bx * 0.01, by * 0.01, t * 0.1);
      if (f > 0.46 + tt * 0.25) {
        let a = map(tt, 0, 1, 45, 6);
        stroke(200, 210, 225, a);
        point(bx + random(-0.2, 0.2), by + random(-0.2, 0.2));
      }
    }
  }
}

function drawCentralVeil() {
  let cx = 950;
  let cy = 1020;

  // Soft luminous core
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 260; i++) {
    let t = i / 259;
    let w = lerp(900, 120, t) + noise(i * 0.08) * 14 - 7;
    let h = lerp(1500, 220, t) + noise(i * 0.08 + 100) * 22 - 11;
    let a = lerp(6, 28, 1 - t);
    fill(228 + random(-2, 2), 236 + random(-2, 2), 232 + random(-2, 2), a);
    ellipse(cx + map(noise(i * 0.06 + 30), 0, 1, -10, 10),
            cy + map(noise(i * 0.06 + 60), 0, 1, -12, 12),
            w, h);
  }

  // Vertical filaments
  strokeWeight(1.2);
  for (let k = -6; k <= 6; k++) {
    let ox = k * 26 + map(noise(k * 0.2 + 3), 0, 1, -8, 8);
    let baseA = 14 + (6 - abs(k)) * 3;
    stroke(240, 246, 244, baseA);
    for (let y = cy - 660; y < cy + 660; y += 4) {
      let x = cx + ox + map(noise(y * 0.01, k * 0.15), 0, 1, -8, 8);
      point(x, y);
    }
  }
  pop();

  // Halo edges
  noFill();
  stroke(210, 220, 225, 55);
  strokeWeight(2.2);
  ellipse(cx, cy, 620, 1420);
  stroke(210, 220, 225, 35);
  strokeWeight(1.2);
  ellipse(cx, cy, 820, 1620);
}

function drawPetalsFlow() {
  // Petals drifting toward the veil, dissolving as they near the center
  let paths = [
    { x0: 1320, y0: 1860, x1: 940, y1: 1060, c1x: 1500, c1y: 1420, c2x: 1120, c2y: 940 },
    { x0: 1480, y0: 1720, x1: 930, y1: 980,  c1x: 1560, c1y: 1260, c2x: 1080, c2y: 880 },
    { x0: 1240, y0: 1920, x1: 960, y1: 1100, c1x: 1400, c1y: 1600, c2x: 1120, c2y: 1040 }
  ];

  for (let p = 0; p < paths.length; p++) {
    let P = paths[p];
    let count = 90 + floor(random(0, 36));
    for (let i = 0; i < count; i++) {
      let t = (i + random(0.1, 0.9)) / (count + 1);
      let x = bezierPoint(P.x0, P.c1x, P.c2x, P.x1, t);
      let y = bezierPoint(P.y0, P.c1y, P.c2y, P.y1, t);
      x += map(noise(t * 8 + p * 10, i * 0.2), 0, 1, -30, 30);
      y += map(noise(t * 7 + 100 + p * 4, i * 0.2), 0, 1, -22, 22);

      let dx = bezierTangent(P.x0, P.c1x, P.c2x, P.x1, t);
      let dy = bezierTangent(P.y0, P.c1y, P.c2y, P.y1, t);
      let ang = atan2(dy, dx) + map(noise(t * 9 + 50), 0, 1, -0.15, 0.15);

      let sz = lerp(22, 6, t) * random(0.8, 1.3);
      let a = lerp(180, 26, pow(t, 1.2)) * random(0.7, 1.0);

      let tintChoice = random();
      let r = 235, g = 240, b = 238;
      if (tintChoice < 0.25) { r = 228; g = 236; b = 244; }
      if (tintChoice > 0.78) { r = 246; g = 242; b = 232; }

      drawPetal(x, y, sz * 1.9, sz * 0.8, ang, color(r, g, b, a));
      if (random() < 0.2) {
        // faint twin
        drawPetal(x + random(-4, 4), y + random(-3, 3), sz * 1.3, sz * 0.6, ang + random(-0.2, 0.2), color(r, g, b, a * 0.6));
      }
    }
  }
}

function drawPetal(x, y, len, wid, ang, col) {
  push();
  translate(x, y);
  rotate(ang);
  noStroke();
  fill(col);
  beginShape();
  vertex(0, 0);
  bezierVertex(len * 0.50, -wid, len, 0, len * 0.50, wid);
  bezierVertex(len * 0.18, wid * 0.48, -len * 0.18, wid * 0.48, 0, 0);
  endShape(CLOSE);
  pop();
}

function computeRiverBoundary() {
  let yb = new Array(width);
  let base = 1520;
  let amp = 140;
  let scl = 0.0017;
  for (let x = 0; x < width; x++) {
    let und = amp * (noise(x * scl, 30.1) - 0.5) * 2.0;
    let long = 40 * sin(x * 0.003 + 1.2);
    yb[x] = base + und + long + map(noise(x * 0.002, 9.2), 0, 1, -18, 18);
  }
  return yb;
}

function drawRiver(yb) {
  // Fill river (the underworld current)
  noStroke();
  fill(6, 6, 10, 255);
  beginShape();
  for (let x = 0; x < width; x += 4) {
    vertex(x, yb[x]);
  }
  vertex(width, height);
  vertex(0, height);
  endShape(CLOSE);

  // Edge glow
  stroke(220, 226, 232, 45);
  strokeWeight(1.4);
  noFill();
  beginShape();
  for (let x = 0; x < width; x += 6) {
    vertex(x, yb[x] - 1);
  }
  endShape();

  // Subtle currents inside
  for (let k = 0; k < 22; k++) {
    stroke(42, 52, 70, 32);
    strokeWeight(0.8);
    let off = random(1000);
    beginShape();
    for (let x = 0; x < width; x += 10) {
      let y = yb[x] + 18 + 70 * noise(x * 0.003 + off, k * 0.2) + 10 * sin(x * 0.01 + off * 3);
      if (y < height - 2) vertex(x, y);
    }
    endShape();
  }

  // Rising mist at the bank
  noStroke();
  for (let i = 0; i < 160; i++) {
    let a = map(i, 0, 159, 40, 0);
    fill(20, 24, 32, a);
    beginShape();
    for (let x = 0; x < width; x += 8) {
      let y = yb[x] - i * 4 + noise(x * 0.004, i * 0.03) * 6;
      vertex(x, y);
    }
    vertex(width, 0);
    vertex(0, 0);
    endShape(CLOSE);
  }
}

function drawGoldAlongBoundary(yb) {
  noStroke();
  for (let x = 0; x < width; x += 6) {
    if (random() < 0.06) {
      let y = yb[x] - random(2, 66);
      let a = random(120, 220);
      fill(212 + random(-6, 8), 188 + random(-6, 6), 108 + random(-8, 6), a);
      let s = random(1.2, 3.4);
      ellipse(x + random(-3, 3), y + random(-2, 2), s, s);
      if (random() < 0.35) {
        fill(250, 240, 180, a * 0.6);
        ellipse(x + random(-2, 2), y + random(-2, 2), s * 0.5, s * 0.5);
      }
    }
  }
}

function vignette() {
  // Edge darkening
  noFill();
  for (let i = 0; i < 60; i++) {
    let a = map(i, 0, 59, 0, 120);
    stroke(0, a * 0.5);
    strokeWeight(40);
    rect(-20 + i * 0.5, -20 + i * 0.5, width + 40 - i, height + 40 - i);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
  noStroke();
  drawScene();
}

function drawScene() {
  let W = width, H = height;
  let yH = 1100;

  // Sky and ground gradient
  drawSkyGroundGradient();

  // Distant ridge
  drawRidge(yH);

  // Mist layers around the horizon
  drawMist(yH);

  // Faint water/fog sheen
  drawHazeSheen(yH);

  // Portal
  let cx = W * 0.5;
  let cy = yH - 40;
  let pw = 280;
  let ph = 520;
  drawPortal(cx, cy, pw, ph);

  // Foreground grasses
  drawGrasses(yH);

  // Floating motes drifting to the portal
  drawMotes(cx, cy, pw, ph, yH);

  // Subtle vignette
  vignette();
}

function drawSkyGroundGradient() {
  let c1 = color(12, 9, 18);
  let c2 = color(34, 38, 58);
  let c3 = color(8, 7, 10);
  strokeWeight(1);

  for (let y = 0; y < height; y++) {
    let t = y / height;
    let base;
    if (t < 0.58) base = lerpColor(c1, c2, t / 0.58);
    else base = lerpColor(c2, c3, (t - 0.58) / (1 - 0.58));

    // Soft horizon glow
    let g = gaussian(t, 0.56, 0.055);
    let brighten = g * 80 + (noise(t * 12.0) - 0.5) * 12;
    let r = constrain(red(base) + brighten, 0, 255);
    let gC = constrain(green(base) + brighten * 0.9, 0, 255);
    let b = constrain(blue(base) + brighten * 1.15, 0, 255);

    stroke(r, gC, b, 255);
    line(0, y, width, y);
  }

  // Sparse distant specks only in upper sky
  let skyTop = height * 0.28;
  for (let i = 0; i < 900; i++) {
    let x = random(width);
    let y = random(skyTop);
    let n = noise(x * 0.01, y * 0.01);
    if (n > 0.6) {
      let a = map(n, 0.6, 1, 10, 60);
      let s = map(n, 0.6, 1, 0.4, 1.5);
      noStroke();
      fill(220, 230, 250, a);
      ellipse(x, y, s, s);
    }
  }
}

function drawRidge(yH) {
  // Distant silhouette ridge
  noStroke();
  let baseC = color(22, 20, 30, 255);
  fill(baseC);
  beginShape();
  vertex(-10, height + 10);
  for (let x = -20; x <= width + 20; x += 8) {
    let n = noise(x * 0.002, 5.31);
    let y = yH - 160 - n * 230;
    vertex(x, y);
  }
  vertex(width + 10, height + 10);
  endShape(CLOSE);

  // Fainter, farther ridge
  fill(30, 32, 48, 80);
  beginShape();
  vertex(-10, height + 10);
  for (let x = -20; x <= width + 20; x += 10) {
    let n = noise(x * 0.0016, 9.19);
    let y = yH - 250 - n * 140;
    vertex(x, y);
  }
  vertex(width + 10, height + 10);
  endShape(CLOSE);
}

function drawMist(yH) {
  // Layered mist bands
  for (let i = 0; i < 120; i++) {
    let t = i / 119;
    let baseY = lerp(yH - 300, yH + 260, t);
    let amp = lerp(90, 40, t);
    let dens = lerp(18, 5, t);
    let hueShift = lerp(220, 245, t);
    fill(hueShift, hueShift + 5, 250, dens);
    beginShape();
    vertex(-10, height + 10);
    for (let x = -20; x <= width + 20; x += 12) {
      let n = fbmNoise(x * 0.0025 + t * 0.4, t * 0.7, 3);
      let y = baseY + map(n, 0, 1, -amp, amp);
      vertex(x, y);
    }
    vertex(width + 10, height + 10);
    endShape(CLOSE);
  }
}

function drawHazeSheen(yH) {
  // Soft horizontal sheen suggesting water/fog
  noFill();
  for (let k = 0; k < 70; k++) {
    let y = yH + map(k, 0, 69, -120, 240) + noise(k * 0.09) * 30;
    let a = map(k, 0, 69, 24, 3);
    stroke(220, 228, 240, a);
    strokeWeight(map(k, 0, 69, 1.8, 0.4));
    let und = random(0.004, 0.01);
    beginShape();
    for (let x = -20; x <= width + 20; x += 7) {
      let yOff = (noise(x * und, k * 0.13) - 0.5) * map(k, 0, 69, 24, 6);
      curveVertex(x, y + yOff);
    }
    endShape();
  }
}

function drawPortal(cx, cy, w, h) {
  // Outer glow layers, slightly jittered to avoid a perfect glyph-like ring
  push();
  for (let i = 0; i < 90; i++) {
    let t = i / 89;
    let rx = w * (1 + 1.35 * t);
    let ry = h * (1 + 1.35 * t);
    let a = 30 * pow(1 - t, 1.8);
    let col = color(165 + 25 * t, 172 + 10 * t, 205 + 10 * t, a);
    fill(col);
    push();
    translate(cx + (noise(t * 2.3) - 0.5) * 8, cy + (noise(7.1 + t * 3.7) - 0.5) * 10);
    rotate((noise(13.5 + t * 4.1) - 0.5) * 0.08);
    ellipse(0, 0, rx, ry);
    pop();
  }
  pop();

  // Subtle inner halo irregularities
  for (let j = 0; j < 45; j++) {
    let t = j / 44;
    let rx = w * (0.96 + 0.18 * t);
    let ry = h * (0.96 + 0.18 * t);
    let a = 15 * pow(1 - t, 1.3);
    fill(210, 220, 240, a);
    push();
    translate(cx + (noise(90 + t * 2.2) - 0.5) * 4, cy + (noise(140 + t * 3.2) - 0.5) * 5);
    ellipse(0, 0, rx, ry);
    pop();
  }

  // Core void
  fill(3, 3, 5, 255);
  ellipse(cx, cy, w * 0.98, h * 0.98);

  // Whispers around the rim (wispy strokes)
  noFill();
  for (let s = 0; s < 120; s++) {
    let a = map(s, 0, 119, 20, 3);
    stroke(210, 220, 245, a);
    strokeWeight(map(s, 0, 119, 1.2, 0.4));
    let ang = random(TWO_PI);
    let r1 = max(w, h) * 0.55;
    let r2 = r1 + random(18, 60);
    let p1 = ellipsePoint(cx, cy, w * 0.55, h * 0.55, ang);
    let p2 = ellipsePoint(cx, cy, w * 0.65, h * 0.65, ang + random(-0.2, 0.2));
    line(p1.x, p1.y, p2.x, p2.y);
  }
  noStroke();
}

function drawGrasses(yH) {
  // Underlayer texture
  for (let i = 0; i < 3000; i++) {
    let x = random(width);
    let y = random(yH + 120, height);
    let a = random(4, 10);
    fill(20, 18, 24, a);
    rect(x, y, random(1, 3), random(1, 3));
  }

  // Blade field
  for (let i = 0; i < 2400; i++) {
    let x = random(-40, width + 40);
    let baseY = random(yH + 130, height - 8);
    let depth = map(baseY, yH + 130, height, 0, 1);
    let len = map(noise(x * 0.003, baseY * 0.002), 0, 1, 50, 240) * (0.6 + 0.6 * depth);
    let sway = (noise(x * 0.01, baseY * 0.01) - 0.5) * (26 + 44 * depth) + random(-8, 8);
    let thickness = map(depth, 0, 1, 0.4, 1.6);
    let c = lerpColor(color(28, 26, 34), color(80, 72, 66), depth);
    stroke(red(c), green(c), blue(c), map(depth, 0, 1, 120, 220));
    strokeWeight(thickness);
    noFill();

    let x0 = x;
    let y0 = baseY;
    let x1 = x - sway * 0.35;
    let y1 = baseY - len * 0.33;
    let x2 = x + sway * 0.55;
    let y2 = baseY - len * 0.7;
    let x3 = x + sway;
    let y3 = baseY - len;

    bezier(x0, y0, x1, y1, x2, y2, x3, y3);

    // Occasional seed tuft suggestion
    if (random() < 0.08 && depth > 0.35) {
      let tufts = int(random(3, 6));
      let headX = x3, headY = y3;
      for (let k = 0; k < tufts; k++) {
        let ang = random(-0.9, 0.9);
        let r = random(6, 12);
        stroke(180, 170, 155, 90);
        strokeWeight(0.6);
        line(headX, headY, headX + r * cos(ang), headY + r * sin(ang));
      }
    }
  }
  noStroke();
}

function drawMotes(cx, cy, pw, ph, yH) {
  // Luminous motes drifting toward the portal
  for (let i = 0; i < 320; i++) {
    let sx = random(width * 0.12, width * 0.88);
    let sy = random(yH + 220, height - 30);
    let dx = cx + random(-pw * 0.15, pw * 0.15);
    let dy = cy + random(-ph * 0.15, ph * 0.15);
    let steps = int(random(12, 24));
    let colWarm = color(245, 236, 210);
    for (let s = 0; s <= steps; s++) {
      let t = s / steps;
      // Ease and slight drift
      let et = easeInOutCubic(t);
      let x = lerp(sx, dx, et);
      let y = lerp(sy, dy, et);
      let curve = (noise(sx * 0.002 + t * 1.2, sy * 0.002) - 0.5) * (60 * (1 - t));
      x += curve * 0.35;
      y -= (1 - t) * 2;

      let a = 5 + 80 * sin(PI * t) * (0.6 + 0.4 * noise(i * 0.1));
      let sz = 0.6 + 2.6 * sin(PI * t) + noise(i * 0.13 + t) * 0.5;
      fill(red(colWarm), green(colWarm), blue(colWarm), a);
      ellipse(x, y, sz, sz);
    }
  }
}

function vignette() {
  // Soft darkening near edges
  let cx = width * 0.5;
  let cy = height * 0.5;
  let maxR = dist(0, 0, cx, cy);
  noStroke();
  for (let r = 0; r < 220; r++) {
    let t = r / 219;
    let a = map(t, 0, 1, 0, 90);
    fill(5, 3, 6, a * 0.25);
    let rx = width * (1 + t * 0.6);
    let ry = height * (1 + t * 0.6);
    ellipse(cx, cy, rx, ry);
  }
}

function gaussian(x, mu, sigma) {
  let z = (x - mu) / sigma;
  return exp(-0.5 * z * z);
}

function exp(n) {
  return Math.exp(n);
}

function fbmNoise(x, y, oct) {
  let v = 0;
  let a = 0.55;
  let f = 1.0;
  for (let i = 0; i < oct; i++) {
    v += a * noise(x * f, y * f);
    f *= 2.0;
    a *= 0.5;
  }
  return v / (1 - pow(0.5, oct));
}

function pow(a, b) {
  return Math.pow(a, b);
}

function ellipsePoint(cx, cy, rx, ry, ang) {
  return { x: cx + rx * cos(ang), y: cy + ry * sin(ang) };
}

function easeInOutCubic(t) {
  return t < 0.5 ? 4 * t * t * t : 1 - pow(-2 * t + 2, 3) / 2;
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
  drawScene();
}

function draw() {}

function drawScene() {
  let horizon = 1150;

  // Background gradients
  verticalGradient(0, horizon, color(10, 12, 18), color(42, 46, 62));
  verticalGradient(horizon, height, color(58, 60, 64), color(230, 224, 212));

  // Subtle vignetting
  vignette();

  // Mist near horizon
  fogBand(horizon - 180, 360, color(240, 240, 245, 18), 0.006, 0.02);

  // Ground texture bands
  groundBands(horizon + 40, height - 40);

  // Arch parameters
  let cx = 820;
  let baseY = 1320;
  let aw = 380;
  let ah = 560;
  let apexY = baseY - ah + aw / 2;

  // Soft glow behind arch
  glow(cx, apexY + 20, 420, color(235, 226, 214), 32);

  // Distant sun haze low on horizon behind arch
  hazeEllipse(cx + 40, horizon + 30, 540, 220, color(250, 244, 232, 12));

  // Arch
  drawArch(cx, baseY, aw, ah, color(2, 3, 5));
  archEdge(cx, baseY, aw, ah, color(220, 214, 206, 60), 3);

  // Faint arch shadow on ground
  archShadow(cx, baseY, aw, ah, horizon);

  // Tree silhouette on the right
  push();
  stroke(8, 8, 10);
  strokeCap(ROUND);
  strokeJoin(ROUND);
  branch(1260, baseY + 4, 340, -PI / 2 - 0.18, 18);
  pop();

  // Rising pale motes (moths/spirits)
  drawMotesCurve(createVector(180, 1860), createVector(360, 1320),
                 createVector(560, 880), createVector(cx - 20, apexY + 40), 70);

  // Crimson ribbon leading into the arch
  ribbonToArch(createVector(140, 1920), createVector(380, 1500),
               createVector(560, 1280), createVector(cx, baseY - 70),
               color(168, 20, 34), color(220, 80, 82));

  // Water-like soft ripples below horizon
  ripples(horizon + 120, height - 120, color(235, 232, 226, 14));

  // Grain overlay
  grain(18000, 12);
}

function verticalGradient(y1, y2, c1, c2) {
  noFill();
  for (let y = y1; y <= y2; y++) {
    let t = (y - y1) / max(1, (y2 - y1));
    stroke(lerpColor(c1, c2, t));
    line(0, y, width, y);
  }
}

function vignette() {
  push();
  noStroke();
  for (let r = max(width, height) * 0.9; r > 100; r -= 12) {
    let t = map(r, max(width, height) * 0.9, 100, 0, 1);
    fill(10, 10, 14, 10 * pow(t, 2));
    ellipse(width / 2, height / 2, r * 1.6, r * 2.0);
  }
  pop();
}

function fogBand(yTop, bandH, baseCol, nx = 0.008, ny = 0.02) {
  push();
  noStroke();
  for (let y = yTop; y < yTop + bandH; y += 2) {
    for (let x = 0; x < width; x += 6) {
      let n = noise(x * nx, y * ny);
      let a = map(n, 0, 1, 0, alpha(baseCol));
      fill(red(baseCol), green(baseCol), blue(baseCol), a);
      rect(x, y + map(n, 0, 1, -2, 2), 8, 3);
    }
  }
  pop();
}

function groundBands(y1, y2) {
  push();
  noStroke();
  for (let y = y1; y <= y2; y += 3) {
    let t = (y - y1) / max(1, (y2 - y1));
    let g = lerp(210, 235, t);
    let b = map(noise(y * 0.01), 0, 1, -6, 6);
    fill(g + b, g + b - 2, g + b - 6, 18 + 10 * (1 - t));
    rect(0, y + map(noise(y * 0.03), 0, 1, -1.2, 1.2), width, 2);
  }
  pop();
}

function glow(x, y, r, col, maxA) {
  push();
  noStroke();
  for (let i = r; i > 8; i -= 8) {
    let a = map(i, r, 8, maxA, 0);
    fill(red(col), green(col), blue(col), a);
    ellipse(x, y, i * 2, i * 1.6);
  }
  pop();
}

function hazeEllipse(x, y, w, h, col) {
  push();
  noStroke();
  for (let i = 0; i < 40; i++) {
    let t = i / 39;
    let a = (1 - t) * alpha(col);
    fill(red(col), green(col), blue(col), a);
    ellipse(x + map(noise(i * 0.2), 0, 1, -6, 6),
            y + map(noise(i * 0.2 + 100), 0, 1, -4, 4),
            w * (1 + t * 0.6),
            h * (1 + t * 0.6));
  }
  pop();
}

function drawArch(cx, baseY, w, h, col) {
  push();
  noStroke();
  fill(col);
  rect(cx - w / 2, baseY - h + w / 2, w, h - w / 2);
  arc(cx, baseY - h + w / 2, w, w, PI, 0, PIE);
  pop();
}

function archEdge(cx, baseY, w, h, scol, sw) {
  push();
  noFill();
  stroke(scol);
  strokeWeight(sw);
  // Sides
  line(cx - w / 2, baseY, cx - w / 2, baseY - h + w / 2);
  line(cx + w / 2, baseY, cx + w / 2, baseY - h + w / 2);
  // Top arc
  arc(cx, baseY - h + w / 2, w, w, PI, 0);
  pop();
}

function archShadow(cx, baseY, w, h, horizon) {
  push();
  noStroke();
  let sh = 220;
  for (let i = 0; i < sh; i++) {
    let t = i / (sh - 1);
    let a = 28 * (1 - t);
    let spread = map(t, 0, 1, w * 0.6, w * 1.6);
    fill(10, 10, 12, a);
    let y = baseY + i;
    if (y > horizon + 20) {
      rect(cx - spread / 2 + waveOffset(y, 0.6), y, spread, 1);
    }
  }
  pop();
}

function waveOffset(y, amp) {
  return sin(y * 0.03) * amp + map(noise(y * 0.01), 0, 1, -amp, amp);
}

function branch(x, y, len, ang, th) {
  if (len < 12 || th < 1.1) return;
  let sway = map(noise(x * 0.003, y * 0.003), 0, 1, -0.1, 0.1);
  let a = ang + sway * (len / 300);
  let x2 = x + cos(a) * len;
  let y2 = y + sin(a) * len;

  strokeWeight(th);
  line(x, y, x2, y2);

  // Knots and slight texture
  if (random() < 0.5) {
    strokeWeight(th * 0.6);
    line(lerp(x, x2, 0.6), lerp(y, y2, 0.6), lerp(x, x2, 0.64), lerp(y, y2, 0.64));
  }

  let nChildren = 2 + (len > 180 ? 1 : 0);
  for (let i = 0; i < nChildren; i++) {
    let na = a + random(-0.7, 0.7) + (i - 0.5) * 0.25;
    let nlen = len * random(0.58, 0.78);
    let nth = th * random(0.62, 0.78);
    branch(x2, y2, nlen, na, nth);
  }

  // Tiny twigs near tips
  if (len < 80 && random() < 0.8) {
    let ta = a + random(-0.9, 0.9);
    let tlen = len * random(0.35, 0.55);
    strokeWeight(max(0.6, th * 0.45));
    line(x2, y2, x2 + cos(ta) * tlen, y2 + sin(ta) * tlen);
  }
}

function drawMotesCurve(p0, p1, p2, p3, count) {
  for (let i = 0; i < count; i++) {
    let t = i / (count - 1);
    let pos = cubicBezier(p0, p1, p2, p3, t);
    let off = p5.Vector.fromAngle(map(noise(t * 6, i * 0.1), 0, 1, -PI, PI))
              .mult(map(noise(i * 0.2), 0, 1, 2, 18) * (1 - t));
    let pt = createVector(pos.x + off.x, pos.y + off.y);
    let s = map(noise(i * 0.31), 0, 1, 4, 10);
    let rot = map(noise(i * 0.17), 0, 1, -PI / 3, PI / 3);
    let alpha = map(t, 0, 1, 160, 60);
    drawMoth(pt.x, pt.y, s, rot, alpha);
  }
}

function cubicBezier(p0, p1, p2, p3, t) {
  let u = 1 - t;
  let tt = t * t;
  let uu = u * u;
  let uuu = uu * u;
  let ttt = tt * t;
  let x = uuu * p0.x + 3 * uu * t * p1.x + 3 * u * tt * p2.x + ttt * p3.x;
  let y = uuu * p0.y + 3 * uu * t * p1.y + 3 * u * tt * p2.y + ttt * p3.y;
  return createVector(x, y);
}

function drawMoth(x, y, s, rot, a) {
  push();
  translate(x, y);
  rotate(rot);
  noStroke();
  fill(245, 244, 240, a);
  ellipse(-s * 0.7, 0, s * 1.1, s * 0.6);
  ellipse( s * 0.7, 0, s * 1.1, s * 0.6);
  fill(220, 218, 214, a);
  ellipse(0, 0, s * 0.25, s * 0.8);
  pop();
}

function ribbonToArch(p0, p1, p2, p3, colMain, colHi) {
  let pts = [];
  let N = 200;
  for (let i = 0; i <= N; i++) {
    let t = i / N;
    let p = cubicBezier(p0, p1, p2, p3, t);
    let n = noise(t * 4.0, 9.3);
    let off = map(n, 0, 1, -22, 22) * (1 - pow(t, 1.6));
    let dir = cubicTangent(p0, p1, p2, p3, t);
    let normal = createVector(-dir.y, dir.x).normalize();
    p.add(p5.Vector.mult(normal, off));
    pts.push(p);
  }
  // Main stroke
  push();
  noFill();
  stroke(colMain);
  strokeWeight(8);
  strokeJoin(ROUND);
  strokeCap(ROUND);
  beginShape();
  for (let p of pts) curveVertex(p.x, p.y);
  endShape();

  // Highlight
  stroke(colHi);
  strokeWeight(3);
  beginShape();
  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    let f = map(i, 0, pts.length - 1, 0, 1);
    let yShift = -1.2 - 0.8 * sin(f * PI);
    curveVertex(p.x, p.y + yShift);
  }
  endShape();
  pop();
}

function cubicTangent(p0, p1, p2, p3, t) {
  let u = 1 - t;
  // derivative of cubic Bezier
  let x = 3 * u * u * (p1.x - p0.x) + 6 * u * t * (p2.x - p1.x) + 3 * t * t * (p3.x - p2.x);
  let y = 3 * u * u * (p1.y - p0.y) + 6 * u * t * (p2.y - p1.y) + 3 * t * t * (p3.y - p2.y);
  let v = createVector(x, y);
  if (v.mag() === 0) v = createVector(1, 0);
  return v.normalize();
}

function ripples(y1, y2, col) {
  push();
  noFill();
  stroke(col);
  for (let y = y1; y < y2; y += 8) {
    let a = map(y, y1, y2, alpha(col), 0);
    stroke(red(col), green(col), blue(col), a);
    let amp = map(y, y1, y2, 8, 1);
    beginShape();
    for (let x = 0; x <= width; x += 14) {
      let n = noise(x * 0.004, y * 0.01);
      let yy = y + sin(x * 0.03 + y * 0.01) * amp * 0.5 + map(n, 0, 1, -amp, amp) * 0.5;
      vertex(x, yy);
    }
    endShape();
  }
  pop();
}

function grain(count, a) {
  push();
  strokeWeight(1);
  for (let i = 0; i < count; i++) {
    let x = random(width);
    let y = random(height);
    let c = random() < 0.5 ? 0 : 255;
    stroke(c, a);
    point(x, y);
  }
  pop();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function draw() {
  colorMode(RGB, 255, 255, 255, 255);
  noStroke();

  // Background gradient (top -> mid -> bottom)
  let topC = color(11, 15, 25);
  let midC = color(183, 194, 201);
  let botC = color(90, 58, 46);
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let c;
    if (t < 0.55) {
      let u = map(t, 0, 0.55, 0, 1);
      c = lerpColor(topC, midC, u);
    } else {
      let u = map(t, 0.55, 1, 0, 1);
      c = lerpColor(midC, botC, u);
    }
    fill(c);
    rect(0, y, width, 1);
  }

  // Subtle distant glow behind the future portal zone
  glowEllipses(width * 0.62, 1150 - 380, 640, 300, color(230, 220, 205), 22, 0.32);

  // Mist layers around mid-height
  drawFogBand(860, 1320, 0.006, 0.01, color(220, 230, 235, 26));
  drawFogBand(900, 1250, 0.009, 0.017, color(210, 220, 228, 20));

  // Distant silhouettes of bare hills (soft)
  drawHorizonSilhouettes();

  // Meandering river of light
  drawRiver();

  // Portal/Arch as threshold
  drawArchPortal(width * 0.62, 1150, 440, 640);

  // Lilies and faint blooms on the river
  drawLilies();

  // Floating motes like rising memories
  scatterMotes();

  // Branch silhouettes framing from edges
  drawBranches();

  // Vignette
  vignette(70, color(0, 0, 0, 10));

  // Grain
  addGrain(42000);
}

function drawFogBand(y1, y2, sx, sy, baseCol) {
  noStroke();
  for (let y = y1; y < y2; y += 2) {
    for (let x = 0; x < width; x += 3) {
      let nx = x * sx;
      let ny = y * sy;
      let n = noise(nx, ny);
      // Wind-like flow
      let shift = (noise(nx * 0.3, ny * 0.3 + 100) - 0.5) * 80;
      let a = map(n, 0, 1, 0, alpha(baseCol));
      let c = color(red(baseCol), green(baseCol), blue(baseCol), a);
      fill(c);
      rect(x + shift, y + (n - 0.5) * 2, 3, 2);
    }
  }
}

function riverCenterX(t) {
  // Curvy center path using sin + noise
  let base = width * 0.5;
  let sway = 220 * sin(t * 2.3 + 0.4);
  let n = (noise(t * 1.2) - 0.5) * 260;
  return base + sway + n;
}

function riverY(t) {
  return lerp(height - 120, 1150, t);
}

function riverWidth(t) {
  let w = lerp(380, 38, t);
  return w * (0.86 + 0.22 * noise(t * 6.0));
}

function drawRiver() {
  noStroke();
  let steps = 460;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let x = riverCenterX(t);
    let y = riverY(t);
    let w = riverWidth(t);

    // Soft body of water
    let baseC = color(210, 225, 233, 36);
    let edgeC = color(150, 174, 190, 22);
    for (let k = 0; k < 6; k++) {
      let f = 1 - k * 0.12;
      fill(lerpColor(baseC, edgeC, k / 5));
      ellipse(x + (noise(t * 10 + k) - 0.5) * 4, y + (noise(t * 9 + k + 77) - 0.5) * 3, w * f, max(1.2, w * 0.22 * f));
    }

    // Occasional small glints
    if (random() < 0.14 && i % 3 === 0) {
      fill(240, 245, 250, 85);
      let gw = max(1.2, w * 0.05);
      ellipse(x + (random() - 0.5) * w * 0.4, y + (random() - 0.5) * 2.0, gw, gw * 0.5);
    }

    // Subtle horizontal ripples
    if (i % 8 === 0) {
      let ripW = w * (0.55 + 0.25 * noise(t * 8 + 50));
      let ripH = max(0.7, w * 0.06);
      fill(225, 235, 242, 16);
      ellipse(x, y + (noise(t * 12 + 13) - 0.5) * 6, ripW, ripH);
    }
  }
}

function drawArchPortal(cx, baseY, outerW, outerH) {
  // Outer stone
  let stone = color(210, 206, 206);
  let stoneShadow = color(80, 78, 85, 25);
  drawArchShape(cx, baseY, outerW, outerH, stone);

  // Stone texture (speckles)
  for (let i = 0; i < 1800; i++) {
    let px = cx + (random() - 0.5) * outerW * 0.92;
    let py = baseY - outerH + outerW * 0.5 + random() * (outerH - outerW * 0.5);
    if (pointInArch(px, py, cx, baseY, outerW, outerH)) {
      fill(stoneShadow);
      rect(px, py, 1, 1);
    }
  }

  // Inner void
  let innerW = outerW - 90;
  let innerH = outerH - 80;
  drawArchShape(cx, baseY, innerW, innerH, color(5, 6, 8));

  // Inner glow just inside the threshold
  for (let r = 0; r < 22; r++) {
    let t = r / 21;
    let c = color(240, 228, 210, map(1 - t, 0, 1, 18, 0));
    drawArchShape(cx, baseY, innerW - r * 2.2, innerH - r * 2.0, c);
  }

  // Faint water continuation inside the void
  let steps = 110;
  for (let i = 0; i <= steps; i++) {
    let tt = i / steps;
    let y = lerp(baseY - 60, baseY - innerH * 0.35, tt);
    let w = lerp(innerW * 0.38, innerW * 0.08, tt);
    fill(200, 220, 230, 18 * (1 - tt));
    ellipse(cx, y, w, w * 0.22);
  }

  // Halo around portal
  glowEllipses(cx, baseY - innerH * 0.55, innerW * 1.3, innerH * 0.6, color(255, 240, 220), 18, 0.24);
}

function drawArchShape(cx, baseY, w, h, colr) {
  noStroke();
  fill(colr);
  let r = w / 2;
  let topY = baseY - h + r;

  beginShape();
  // Left base
  vertex(cx - r, baseY);
  // Left inner corner before arc
  vertex(cx - r, topY);
  // Top semicircle
  let segs = 64;
  for (let i = 0; i <= segs; i++) {
    let a = PI - (i / segs) * PI;
    let vx = cx + cos(a) * r;
    let vy = topY + sin(a) * r;
    vertex(vx, vy);
  }
  // Right side down
  vertex(cx + r, topY);
  vertex(cx + r, baseY);
  endShape(CLOSE);
}

function pointInArch(px, py, cx, baseY, w, h) {
  let r = w / 2;
  let topY = baseY - h + r;
  // Inside rectangle sides
  if (py > topY && py < baseY && px > cx - r && px < cx + r) return true;
  // Inside semicircle
  if (py <= topY && py >= topY - r) {
    let dx = px - cx;
    let dy = py - topY;
    return dx * dx + dy * dy <= r * r && dy <= 0;
  }
  // On the arc band level
  if (py <= topY && py >= topY - r * 2) {
    let dx = px - cx;
    let dy = py - topY;
    return dx * dx + dy * dy <= r * r && dy <= 0;
  }
  return false;
}

function glowEllipses(x, y, w, h, baseColor, rings, strength) {
  noStroke();
  for (let i = 0; i < rings; i++) {
    let t = i / (rings - 1);
    let a = map(1 - t, 0, 1, 0, 40 * strength);
    fill(red(baseColor), green(baseColor), blue(baseColor), a);
    ellipse(x, y, w + i * w * 0.22, h + i * h * 0.22);
  }
}

function drawLilies() {
  let count = 46;
  for (let i = 0; i < count; i++) {
    let t = random(0.22, 0.8);
    let x = riverCenterX(t) + random(-1, 1) * riverWidth(t) * 0.35;
    let y = riverY(t) + random(-2, 2);
    let padW = random(18, 36) * (1 - t * 0.4);
    let padH = padW * random(0.55, 0.75);
    // Pad
    fill(40, 76, 58, 150);
    ellipse(x, y, padW, padH);
    // Light rim
    noFill();
    stroke(140, 180, 150, 90);
    strokeWeight(1);
    ellipse(x, y, padW * 0.96, padH * 0.96);
    noStroke();
    // Bloom
    if (random() < 0.5) {
      let bw = padW * random(0.18, 0.28);
      fill(250, 246, 240, 190);
      ellipse(x + random(-padW * 0.15, padW * 0.15), y + random(-padH * 0.1, padH * 0.1), bw, bw * 0.72);
    }
  }
}

function scatterMotes() {
  let topBand = 0.0;
  let midTop = 1050;
  // Upper stars
  for (let i = 0; i < 680; i++) {
    let x = random(width);
    let y = random(topBand, midTop * 0.6);
    let a = random(60, 140);
    let s = random(1, 2.2);
    fill(230, 235, 245, a);
    ellipse(x, y, s, s);
  }
  // Rising warm motes near fog/river
  for (let i = 0; i < 900; i++) {
    let t = random(0.18, 0.78);
    let x = riverCenterX(t) + (noise(t * 14 + i) - 0.5) * riverWidth(t) * 0.9;
    let y = riverY(t) - random(0, 120) * (0.6 + 0.4 * noise(i * 0.1));
    let warm = color(255, 220, 180, random(18, 70));
    fill(warm);
    let s = random(0.8, 2.4);
    ellipse(x, y, s, s * 0.9);
  }
}

function drawBranches() {
  // Left
  push();
  stroke(12, 12, 14, 180);
  drawBranch(width * 0.08, 260, radians(15), 260, 0);
  drawBranch(width * 0.14, 340, radians(28), 220, 0);
  pop();

  // Right
  push();
  stroke(12, 12, 14, 180);
  drawBranch(width * 0.92, 220, radians(165), 280, 0);
  drawBranch(width * 0.86, 320, radians(150), 230, 0);
  pop();
}

function drawBranch(x, y, ang, len, depth) {
  if (depth > 3 || len < 40) return;
  strokeWeight(map(depth, 0, 3, 7, 2));
  noFill();

  let segs = floor(map(len, 40, 300, 3, 6));
  let px = x;
  let py = y;
  for (let i = 0; i < segs; i++) {
    let t = i / segs;
    let l = len / segs;
    let jitter = (noise(px * 0.01, py * 0.01) - 0.5) * 0.7;
    let nx = px + cos(ang + jitter) * l;
    let ny = py + sin(ang + jitter) * l;

    line(px, py, nx, ny);

    // Small side twig
    if (random() < 0.35 - depth * 0.08) {
      let twigAng = ang + random(-0.9, 0.9);
      let twigLen = l * random(0.5, 0.9);
      let tx = lerp(px, nx, random(0.3, 0.8));
      let ty = lerp(py, ny, random(0.3, 0.8));
      strokeWeight(map(depth, 0, 3, 5, 1.2));
      line(tx, ty, tx + cos(twigAng) * twigLen, ty + sin(twigAng) * twigLen);
      strokeWeight(map(depth, 0, 3, 7, 2));
    }

    px = nx; py = ny;
  }

  // Recurse
  drawBranch(px, py, ang + random(-0.45, -0.15), len * random(0.6, 0.78), depth + 1);
  drawBranch(px, py, ang + random(0.15, 0.55), len * random(0.55, 0.75), depth + 1);
}

function drawHorizonSilhouettes() {
  noStroke();
  let baseY = 1220;
  for (let layer = 0; layer < 3; layer++) {
    let yOff = baseY + layer * 26;
    let c = color(20 + layer * 6, 22 + layer * 6, 24 + layer * 5, 140 - layer * 30);
    fill(c);
    beginShape();
    vertex(0, yOff + 60);
    for (let x = 0; x <= width; x += 12) {
      let n = noise(x * 0.002 + layer * 10, layer * 80) * 70;
      vertex(x, yOff - n);
    }
    vertex(width, yOff + 60);
    endShape(CLOSE);
  }
}

function vignette(steps, colr) {
  noStroke();
  for (let i = 0; i < steps; i++) {
    let m = map(i, 0, steps - 1, 0, 1);
    let a = map(m, 0, 1, 0, alpha(colr));
    fill(0, 0, 0, a);
    rect(i * 0.5, i * 0.5, width - i, height - i);
  }

  // Corner darkening
  let corners = 18;
  for (let i = 0; i < corners; i++) {
    let t = i / (corners - 1);
    let a = map(t, 0, 1, 10, 0);
    fill(0, 0, 0, a);
    ellipse(0, 0, width * 0.9 + i * 60, height * 0.9 + i * 60);
    ellipse(width, 0, width * 0.9 + i * 60, height * 0.9 + i * 60);
    ellipse(0, height, width * 0.9 + i * 60, height * 0.9 + i * 60);
    ellipse(width, height, width * 0.9 + i * 60, height * 0.9 + i * 60);
  }
}

function addGrain(n) {
  for (let i = 0; i < n; i++) {
    let x = random(width);
    let y = random(height);
    let g = random() < 0.5 ? random(8, 24) : random(0, 10);
    let a = random(12, 28);
    fill(g, g, g, a);
    rect(x, y, 1, 1);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();

  drawSky();
  drawStars(700);
  drawMoon(1200, 180, 130);

  let horizonY = 1360;
  drawGround(horizonY);

  // Portal
  let px = width * 0.53;
  let py = horizonY - 14;
  drawPortal(px, py, 360, 800, 90);

  // Mist around portal and ground
  drawMist(px, py - 260, 520, 1400);
  drawLowMist(horizonY, 1200);

  // Foreground textures
  drawPebbles(horizonY, 180);
  drawGrass(horizonY, 220);

  // Red thread guiding toward the portal
  drawThread(createVector(220, 1755), createVector(px - 6, py - 18));

  vignette();
  sprinkleDust(12000);
}

function draw() {}

// Sky gradient and atmosphere
function drawSky() {
  noStroke();
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let c;
    if (y < 800) {
      let c1 = color(10, 15, 28);
      let c2 = color(26, 22, 38);
      c = lerpColor(c1, c2, y / 800);
    } else if (y < 1300) {
      let u = (y - 800) / 500;
      let c1 = color(26, 22, 38);
      let c2 = color(140, 110, 84);
      c = lerpColor(c1, c2, u * 0.6);
    } else {
      let u = (y - 1300) / (height - 1300);
      let c1 = color(70, 56, 60);
      let c2 = color(22, 16, 20);
      c = lerpColor(c1, c2, u);
    }
    fill(c);
    rect(0, y, width, 1);
  }
}

function drawStars(n) {
  push();
  noStroke();
  for (let i = 0; i < n; i++) {
    let x = random(width);
    let y = random(0, 550);
    let s = random(0.5, 1.8);
    let b = random(200, 255);
    fill(b, b, b, random(30, 110));
    ellipse(x, y, s, s);
  }
  pop();
}

function drawMoon(x, y, d) {
  push();
  noStroke();
  fill(235, 236, 245, 36);
  ellipse(x, y, d * 1.3, d * 1.3);
  fill(235, 236, 245, 60);
  ellipse(x, y, d, d);
  fill(235, 236, 245, 100);
  ellipse(x + 4, y - 3, d * 0.7, d * 0.7);
  pop();
}

function drawGround(horizonY) {
  // Ground silhouette
  noStroke();
  fill(18, 14, 16);
  beginShape();
  vertex(0, height);
  for (let x = 0; x <= width; x += 8) {
    let n = noise(x * 0.0011, 4.2);
    let yH = horizonY - 40 + n * 80;
    vertex(x, yH);
  }
  vertex(width, height);
  endShape(CLOSE);

  // Ground tonal texture
  push();
  for (let i = 0; i < 1400; i++) {
    let x1 = random(width);
    let y1 = random(horizonY, height);
    let len = random(20, 90);
    let ang = random(-0.2, 0.2);
    stroke(28, 22, 25, random(20, 60));
    strokeWeight(random(0.4, 1.3));
    line(x1, y1, x1 + cos(ang) * len, y1 + sin(ang) * len * 0.15);
  }
  pop();

  // Distant haze at horizon
  push();
  noStroke();
  for (let i = 0; i < 90; i++) {
    let a = map(i, 0, 89, 10, 0);
    fill(180, 160, 140, a);
    rect(0, horizonY - 80 + i, width, 2);
  }
  pop();
}

function drawPortal(x, yBottom, w, h, steps) {
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < steps; i++) {
    let t = i / (steps - 1);
    let ww = lerp(w, w * 0.18, t * t);
    let hh = lerp(h, h * 0.64, t);
    let cOuter = color(88, 120, 188, 10);
    let cInner = color(255, 246, 232, 18);
    let col = lerpColor(cOuter, cInner, 1 - t);
    fill(col);
    archPolygon(x, yBottom, ww, hh, t);
  }

  // Inner soft glow column
  for (let i = 0; i < 80; i++) {
    let t = i / 79;
    let ww = w * 0.25 * (1 - t * 0.8);
    let hh = h * (0.7 + 0.2 * (1 - t));
    fill(250, 245, 238, 10);
    archPolygon(x + sin(t * 6) * 2.0, yBottom, ww, hh, 0.05 + 0.95 * t);
  }
  pop();
}

function archPolygon(x, yBottom, w, h, t) {
  let r = w / 2;
  let yTop = yBottom - h;
  beginShape();
  let cx = x;
  let cy = yTop + r;
  let rough = (1 - t) * 8;
  for (let a = PI; a >= 0; a -= PI / 72) {
    let vx = cx + r * cos(a);
    let vy = cy + r * sin(a);
    let j = (noise(vx * 0.01, vy * 0.01) - 0.5) * rough;
    vertex(vx, vy + j);
  }
  vertex(x + r, yBottom);
  vertex(x - r, yBottom);
  endShape(CLOSE);
}

function drawMist(cx, cy, radius, count) {
  push();
  blendMode(ADD);
  noFill();
  for (let i = 0; i < count; i++) {
    let a = random(TWO_PI);
    let rr = radius * sqrt(random());
    let sx = cx + cos(a) * rr * 0.9 + random(-100, 100);
    let sy = cy + sin(a) * rr * 0.4 + random(-60, 60);
    let px = sx;
    let py = sy;
    let steps = floor(random(26, 52));
    let sw = random(0.6, 1.6);
    strokeWeight(sw);
    let baseA = random(8, 22);
    for (let s = 0; s < steps; s++) {
      let ang = noise(px * 0.002, py * 0.002) * TWO_PI * 2.0;
      let vx = cos(ang);
      let vy = sin(ang) * 0.5 - 0.15;
      let nx = px + vx * 3.0;
      let ny = py + vy * 3.0;

      let d = dist(nx, ny, cx, cy);
      let aFade = constrain(map(d, 0, radius * 1.4, 28, 4), 4, 40);
      stroke(240, 245, 255, min(aFade, baseA));
      line(px, py, nx, ny);
      px = nx;
      py = ny;
      if (py < 80) break;
    }
  }
  pop();
}

function drawLowMist(horizonY, count) {
  push();
  blendMode(ADD);
  noFill();
  for (let i = 0; i < count; i++) {
    let x = random(width);
    let y = random(horizonY - 60, horizonY + 200);
    let len = random(120, 320);
    stroke(220, 215, 220, random(6, 16));
    strokeWeight(random(0.6, 1.2));
    let wig = random(0.006, 0.012);
    beginShape();
    for (let t = 0; t <= 1; t += 0.025) {
      let xx = x + t * len;
      let yy = y + sin(t * PI) * random(-8, 8) + (noise(xx * wig, y * 0.01) - 0.5) * 14;
      vertex(xx, yy);
    }
    endShape();
  }
  pop();
}

function drawPebbles(horizonY, count) {
  push();
  noStroke();
  for (let i = 0; i < count; i++) {
    let x = random(width);
    let y = random(horizonY + 24, height - 30);
    // Avoid clustering too much in the portal mouth to keep path
    if (x > width * 0.47 && x < width * 0.59) {
      if (random() < 0.7) continue;
    }
    let r = random(6, 28);
    let rot = random(TWO_PI);
    let shade = random(210, 245);
    let col = color(shade, shade - random(0, 20), shade - random(0, 30), random(140, 230));
    // Shadow
    fill(10, 8, 9, 120);
    ellipse(x + 2, y + 2, r * 1.3, r * 0.7);
    // Body
    drawPebbleShape(x, y, r, rot, col);
    // Highlights
    fill(255, 255, 255, 30);
    ellipse(x - r * 0.1, y - r * 0.15, r * 0.3, r * 0.2);
  }
  pop();
}

function drawPebbleShape(x, y, r, rot, col) {
  push();
  translate(x, y);
  rotate(rot);
  fill(col);
  beginShape();
  let squash = random(0.7, 1.1);
  let dents = random(0.05, 0.18);
  for (let a = 0; a < TWO_PI; a += TWO_PI / 22) {
    let rr = r * (0.82 + 0.25 * noise(cos(a) * 1.3 + x * 0.01, sin(a) * 1.3 + y * 0.01) * (1 - dents));
    let vx = cos(a) * rr;
    let vy = sin(a) * rr * squash;
    vertex(vx, vy);
  }
  endShape(CLOSE);
  pop();
}

function drawGrass(horizonY, count) {
  push();
  for (let i = 0; i < count; i++) {
    let x = random(width);
    // keep central path lighter in grass density
    if (x > width * 0.48 && x < width * 0.58 && random() < 0.65) continue;
    let yB = random(horizonY + 14, min(height - 6, horizonY + 340));
    let h = random(50, 220);
    let tone = random(24, 40);
    stroke(tone, tone - 3, tone - 1, random(80, 160));
    strokeWeight(random(0.6, 1.4));
    noFill();
    let cp1x = x + random(-30, 30);
    let cp1y = yB - h * random(0.3, 0.5);
    let cp2x = x + random(-40, 40);
    let cp2y = yB - h * random(0.6, 0.9);
    let tipx = x + random(-25, 25);
    let tipy = yB - h;
    bezier(x, yB, cp1x, cp1y, cp2x, cp2y, tipx, tipy);
  }
  pop();
}

function drawThread(p0, p3) {
  push();
  noFill();
  stroke(160, 30, 40, 220);
  strokeWeight(2.6);
  // Control points create a slow arc toward the portal
  let cp1 = createVector(420 + random(-30, 30), 1650 + random(-40, 40));
  let cp2 = createVector(p3.x - 180 + random(-40, 40), p3.y - 120 + random(-20, 20));
  // Draw the main line
  bezier(p0.x, p0.y, cp1.x, cp1.y, cp2.x, cp2.y, p3.x, p3.y);

  // Slight parallel glint for tactile feel
  stroke(230, 90, 96, 60);
  strokeWeight(1.1);
  let offset = 2.0;
  let last = null;
  beginShape();
  for (let t = 0; t <= 1.0; t += 0.02) {
    let pt = bezierPointVec(p0, cp1, cp2, p3, t);
    let tan = bezierTangentVec(p0, cp1, cp2, p3, t);
    let n = createVector(-tan.y, tan.x).normalize().mult(offset);
    vertex(pt.x + n.x, pt.y + n.y);
    last = pt;
  }
  endShape();
  pop();
}

function bezierPointVec(p0, p1, p2, p3, t) {
  let x = bezierPoint(p0.x, p1.x, p2.x, p3.x, t);
  let y = bezierPoint(p0.y, p1.y, p2.y, p3.y, t);
  return createVector(x, y);
}

function bezierTangentVec(p0, p1, p2, p3, t) {
  let x = bezierTangent(p0.x, p1.x, p2.x, p3.x, t);
  let y = bezierTangent(p0.y, p1.y, p2.y, p3.y, t);
  return createVector(x, y);
}

function vignette() {
  push();
  noStroke();
  for (let i = 0; i < 60; i++) {
    let a = map(i, 0, 59, 0, 200);
    fill(5, 5, 10, a * 0.5);
    let w = width * (1 + i * 0.08);
    let h = height * (1 + i * 0.08);
    ellipse(width / 2, height / 2 - 80, w, h);
  }
  pop();
}

function sprinkleDust(n) {
  push();
  noStroke();
  for (let i = 0; i < n; i++) {
    let x = random(width);
    let y = random(height);
    let a = random(8, 18);
    let c = random(210, 255);
    fill(c, c, c, a);
    rect(x, y, 1, 1);
  }
  pop();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  colorMode(HSL, 360, 100, 100, 1);
  noLoop();
  noStroke();

  drawBackground();
  drawSpeckles();
  drawHighMist();
  drawRiverPath();
  drawVoidAndHalo();
  drawRibbons();
  drawLowMist();
  drawGroundAndStones();
}

function draw() {}

function drawBackground() {
  // Vertical gradient from deep indigo to warm pale gray
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let h = 230 - 40 * t;     // hue shifts subtly
    let s = 20 + 15 * t;      // slight saturation rise
    let l = 8 + 86 * t;       // from very dark to bright
    fill(h, s, l, 1);
    rect(0, y, width, 1);
  }
}

function drawSpeckles() {
  // Sparse star-like speckles in upper half
  let n = 6000;
  for (let i = 0; i < n; i++) {
    let x = random(width);
    let y = random(height * 0.55);
    let a = random(0.02, 0.08);
    let l = random(70, 95);
    fill(220, 10, l, a);
    rect(x, y, 1, 1);
    if (random() < 0.12) {
      // tiny cluster blur
      fill(220, 8, l - 12, a * 0.4);
      rect(x + random(-1, 1), y + random(-1, 1), 1, 1);
    }
  }
}

function drawHighMist() {
  // Soft high-altitude mist bands
  noStroke();
  for (let k = 0; k < 35; k++) {
    let y0 = height * 0.18 + k * height * 0.015;
    let amp = 18 + k * 0.7;
    fill(220, 12, 92, 0.025);
    beginShape();
    for (let x = -60; x <= width + 60; x += 24) {
      let n = noise(x * 0.003, k * 0.2) * 2 - 1;
      let y = y0 + sin(x * 0.004 + k * 0.37) * amp * 0.22 + n * amp * 0.6;
      vertex(x, y);
    }
    vertex(width + 80, y0 + amp * 3.5);
    vertex(-80, y0 + amp * 3.5);
    endShape(CLOSE);
  }
}

function drawRiverPath() {
  // A narrowing, pale river-like path leading upward
  let cy = height * 0.52;
  let yStart = height * 0.92;
  let yEnd = cy + 200;
  let N = 260;

  let pts = [];
  for (let i = 0; i <= N; i++) {
    let t = i / N;
    let y = lerp(yStart, yEnd, t);
    let meander = (noise(t * 3.3) - 0.5) * 260 * pow(1 - t, 1.2);
    let x = width * 0.5 + meander;
    pts.push({ x, y });
  }

  // Build polygon from left and right offsets
  let lefts = [];
  let rights = [];
  for (let i = 0; i <= N; i++) {
    let p = pts[i];
    let p2 = pts[min(i + 1, N)];
    let ang = atan2(p2.y - p.y, p2.x - p.x) - HALF_PI;
    let w = lerp(520, 26, i / N);
    let cx = cos(ang), sy = sin(ang);
    lefts.push({ x: p.x + cx * w * 0.5, y: p.y + sy * w * 0.5 });
    rights.push({ x: p.x - cx * w * 0.5, y: p.y - sy * w * 0.5 });
  }

  // Base fill
  fill(210, 14, 92, 0.12);
  beginShape();
  for (let i = 0; i < lefts.length; i++) vertex(lefts[i].x, lefts[i].y);
  for (let i = rights.length - 1; i >= 0; i--) vertex(rights[i].x, rights[i].y);
  endShape(CLOSE);

  // Inner bright glaze layers
  for (let layer = 0; layer < 3; layer++) {
    let shrink = 0.82 - layer * 0.08;
    fill(210, 10, 96, 0.05 - layer * 0.01);
    beginShape();
    for (let i = 0; i <= N; i++) {
      let p = pts[i];
      let p2 = pts[min(i + 1, N)];
      let ang = atan2(p2.y - p.y, p2.x - p.x) - HALF_PI;
      let w = lerp(520, 26, i / N) * shrink;
      vertex(p.x + cos(ang) * w * 0.5, p.y + sin(ang) * w * 0.5);
    }
    for (let i = N; i >= 0; i--) {
      let p = pts[i];
      let p2 = pts[max(i - 1, 0)];
      let ang = atan2(p.y - p2.y, p.x - p2.x) - HALF_PI;
      let w = lerp(520, 26, i / N) * shrink;
      vertex(p.x - cos(ang) * w * 0.5, p.y - sin(ang) * w * 0.5);
    }
    endShape(CLOSE);
  }
}

function drawVoidAndHalo() {
  let cx = width * 0.5;
  let cy = height * 0.52;

  // Elliptical absorbing void (radial falloff)
  noStroke();
  for (let r = 520; r >= 0; r -= 2) {
    let a = map(r, 0, 520, 0.92, 0.0);
    fill(0, 0, 0, a);
    ellipse(cx, cy, r * 1.18, r * 0.88);
  }

  // Subtle inner sheen (cold)
  for (let r = 480; r >= 430; r -= 2) {
    let a = map(r, 480, 430, 0.03, 0.0);
    fill(220, 18, 16, a);
    ellipse(cx, cy, r * 1.18, r * 0.88);
  }

  // Warm halo ring
  for (let r = 560; r <= 760; r += 4) {
    let t = (r - 560) / 200;
    let hue = lerp(36, 300, smoothstep(0, 1, t));
    let lum = lerp(56, 38, t);
    let sat = lerp(60, 30, t);
    let a = lerp(0.18, 0.02, t);
    fill(hue, sat, lum, a);
    ellipse(cx, cy, r * 1.18, r * 0.88);
  }
}

function drawRibbons() {
  let cx = width * 0.5;
  let cy = height * 0.52;

  let palettes = [
    { h: 15, s: 58, l: 62 },   // ochre-ember
    { h: 260, s: 34, l: 62 },  // violet
    { h: 45, s: 62, l: 60 },   // golden
    { h: 190, s: 36, l: 56 },  // teal
    { h: 320, s: 28, l: 58 },  // mauve
    { h: 200, s: 20, l: 66 },  // soft blue
    { h: 8, s: 44, l: 58 }     // rust
  ];

  let nR = 220;
  for (let r = 0; r < nR; r++) {
    let pal = random(palettes);
    let baseA = random(0.06, 0.16);
    let sw = random(0.6, 2.2);

    // Start around a broad ellipse
    let ang = random(TAU);
    let rad = random(590, 820);
    let x = cx + cos(ang) * rad * 1.12;
    let y = cy + sin(ang) * rad * 0.92;

    let steps = 240 + floor(random(-30, 30));
    let stepLen = random(1.6, 2.6);

    let px = x, py = y;
    for (let i = 0; i < steps; i++) {
      // Tangent around center
      let rx = x - cx;
      let ry = y - cy;
      let mag = sqrt(rx * rx + ry * ry) + 1e-6;
      let tx = -ry / mag;
      let ty = rx / mag;

      // Noise modulation
      let n = noise(x * 0.002, y * 0.002);
      let bend = map(n, 0, 1, -0.7, 0.7);
      let ca = cos(bend), sa = sin(bend);
      let txx = tx * ca - ty * sa;
      let tyy = tx * sa + ty * ca;

      // Outward drift
      let ox = rx / mag;
      let oy = ry / mag;

      // Avoid the void (elliptical boundary)
      let ex = rx / (520 * 1.18);
      let ey = ry / (520 * 0.88);
      let d2 = ex * ex + ey * ey;

      let repel = 0;
      if (d2 < 1.04) repel = (1.04 - d2) * 7.0;

      // Update
      let vx = txx * stepLen + ox * 0.28 + ox * repel;
      let vy = tyy * stepLen + oy * 0.08 + oy * repel;

      let nx = x + vx;
      let ny = y + vy;

      // Draw segment
      stroke(pal.h, pal.s, pal.l, baseA * (1 - i / steps));
      strokeWeight(sw * (0.85 + 0.3 * noise(i * 0.03, r * 0.1)));
      line(x, y, nx, ny);

      // Advance
      px = x; py = y;
      x = nx; y = ny;

      // Stop if off-canvas far
      if (x < -120 || x > width + 120 || y < -120 || y > height + 120) break;
    }
  }
}

function drawLowMist() {
  // Low-lying mist near the threshold and river
  noStroke();
  for (let k = 0; k < 28; k++) {
    let y0 = height * 0.52 + 80 + k * 18;
    let amp = 22 + k * 0.9;
    fill(210, 12, 94, 0.028);
    beginShape();
    for (let x = -50; x <= width + 50; x += 18) {
      let n = noise(x * 0.004, k * 0.23) * 2 - 1;
      let y = y0 + sin(x * 0.006 + k * 0.41) * amp * 0.22 + n * amp * 0.7;
      vertex(x, y);
    }
    vertex(width + 60, y0 + amp * 3.2);
    vertex(-60, y0 + amp * 3.2);
    endShape(CLOSE);
  }
}

function drawGroundAndStones() {
  // Ground gradient darkening
  for (let y = height * 0.84; y < height; y++) {
    let t = map(y, height * 0.84, height, 0, 1);
    fill(220, 12, lerp(46, 24, t), 0.25);
    rect(0, y, width, 1);
  }

  // Subtle ripples where ground meets river
  noStroke();
  for (let i = 0; i < 22; i++) {
    let y = lerp(height * 0.84, height * 0.92, i / 21);
    fill(210, 10, 86, 0.04);
    rect(0, y + sin(i * 0.4) * 2, width, 2 + i * 0.3);
  }

  // Stones
  let stones = 64;
  for (let i = 0; i < stones; i++) {
    let sx = random(60, width - 60);
    let sy = random(height * 0.89, height * 0.985);
    let rw = random(26, 160);
    let rh = rw * random(0.5, 0.9);
    let h = 220 + random(-8, 8);
    let s = random(6, 14);
    let l = random(22, 42);

    // Shadow
    fill(h, s, l - 10, 0.3);
    ellipse(sx + rw * 0.08, sy + rh * 0.22, rw * 1.05, rh * 1.05);

    // Body
    fill(h, s, l, 0.85);
    drawBlobbyEllipse(sx, sy, rw, rh, 0.12);

    // Highlight
    fill(h, s, l + 22, 0.18);
    ellipse(sx - rw * 0.18, sy - rh * 0.22, rw * 0.5, rh * 0.42);

    // Edge glaze
    noFill();
    stroke(h, s, l + 10, 0.12);
    strokeWeight(1.2);
    ellipse(sx, sy, rw, rh);
    noStroke();
  }

  // Foreground vignette
  for (let y = height * 0.95; y < height; y++) {
    let t = map(y, height * 0.95, height, 0, 1);
    fill(220, 10, 8, 0.18 * t);
    rect(0, y, width, 1);
  }
}

function drawBlobbyEllipse(cx, cy, rw, rh, jitter) {
  // Slightly irregular ellipse for organic stone feel
  beginShape();
  let segs = 64;
  for (let i = 0; i < segs; i++) {
    let a = (i / segs) * TAU;
    let rjx = 1 + (noise(cx * 0.01 + cos(a), cy * 0.01 + sin(a)) - 0.5) * jitter;
    let rjy = 1 + (noise(cx * 0.01 - sin(a), cy * 0.01 - cos(a)) - 0.5) * jitter;
    let x = cx + cos(a) * rw * 0.5 * rjx;
    let y = cy + sin(a) * rh * 0.5 * rjy;
    vertex(x, y);
  }
  endShape(CLOSE);
}

function smoothstep(a, b, x) {
  let t = constrain((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  colorMode(HSL, 360, 100, 100, 1);
  noLoop();
}

let cx, cy, rCore;

function draw() {
  cx = width * 0.5;
  cy = height * 0.48;
  rCore = 320;

  drawGradient();
  addAtmosphereGrain();

  drawRiverTowardCenter();

  drawHorizonBand();

  drawThreadsToVoid();

  drawVoidAndHalo();

  scatterDust();
}

function drawGradient() {
  let cTop = color(230, 25, 8, 1);    // nuit bleu-noir
  let cBot = color(42, 18, 92, 1);    // aube sable
  noFill();
  for (let y = 0; y < height; y++) {
    let t = y / (height - 1);
    let cc = lerpColor(cTop, cBot, t);
    stroke(cc);
    line(0, y, width, y);
  }
}

function addAtmosphereGrain() {
  // Brouillard/grain très léger pour casser les aplats
  noStroke();
  for (let y = 0; y < height; y += 8) {
    for (let x = 0; x < width; x += 8) {
      let n = noise(x * 0.003, y * 0.003);
      let l = 10 + 50 * n;
      fill(230, 20, l, 0.035);
      let dx = (noise(x * 0.01 + 9.1, y * 0.01 + 3.7) - 0.5) * 2;
      let dy = (noise(x * 0.01 + 5.2, y * 0.01 + 6.3) - 0.5) * 2;
      ellipse(x + dx, y + dy, 8, 8);
    }
  }
}

function drawRiverTowardCenter() {
  // Ruban lumineux qui monte vers le centre: un "chemin" qui se dissout
  let p0 = createVector(width * 0.5, height * 0.98);
  let p1 = createVector(width * 0.5, height * 0.80);
  let p2 = createVector(width * 0.60, height * 0.65);
  let p3 = createVector(cx, cy + rCore * 0.3);

  for (let pass = 0; pass < 3; pass++) {
    let leftPts = [];
    let rightPts = [];
    let steps = 120;
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let x = bezierPoint(p0.x, p1.x, p2.x, p3.x, t);
      let y = bezierPoint(p0.y, p1.y, p2.y, p3.y, t);
      let tx = bezierTangent(p0.x, p1.x, p2.x, p3.x, t);
      let ty = bezierTangent(p0.y, p1.y, p2.y, p3.y, t);
      let ang = atan2(ty, tx);
      let nx = -sin(ang), ny = cos(ang);

      let baseW = lerp(280, 6, pow(t, 0.9));
      let jitter = (noise(t * 8 + pass * 1.7) - 0.5) * 0.28;
      let w = baseW * (0.9 + 0.4 * noise(t * 10 + 10.1 * pass)) * (1 + jitter);

      leftPts.push(createVector(x + nx * w * 0.5, y + ny * w * 0.5));
      rightPts.push(createVector(x - nx * w * 0.5, y - ny * w * 0.5));
    }
    fill(42, 35, 92, 0.07 + pass * 0.02);
    noStroke();
    beginShape();
    for (let v of leftPts) vertex(v.x, v.y);
    for (let i = rightPts.length - 1; i >= 0; i--) vertex(rightPts[i].x, rightPts[i].y);
    endShape(CLOSE);
  }

  // Voile de brume sur le ruban
  push();
  blendMode(SOFT_LIGHT);
  noStroke();
  for (let i = 0; i < 40; i++) {
    let t = i / 39;
    let x = bezierPoint(p0.x, p1.x, p2.x, p3.x, t);
    let y = bezierPoint(p0.y, p1.y, p2.y, p3.y, t);
    let size = lerp(420, 60, t) * (0.7 + 0.6 * noise(i * 0.3 + 4.2));
    fill(42, 10, 96, 0.02);
    ellipse(x + (noise(i * 0.7) - 0.5) * 40, y + (noise(i * 0.7 + 9.9) - 0.5) * 30, size, size * 0.6);
  }
  pop();
}

function drawHorizonBand() {
  // Liseré doré discret: le seuil
  push();
  let y0 = height * 0.75;
  for (let i = 0; i < 80; i++) {
    let yy = y0 + map(i, 0, 79, -16, 18) + (noise(i * 0.12 + 2.5) - 0.5) * 8;
    stroke(45, 70, 82, 0.05 + 0.02 * noise(i * 0.15));
    strokeWeight(1 + 0.4 * noise(i * 0.2 + 6.6));
    line(0, yy, width, yy);
  }
  pop();
}

function drawThreadsToVoid() {
  // Fils/trajectoires: tout converge, sans violence
  let N = 2200;
  for (let i = 0; i < N; i++) {
    let pos;
    if (random() < 0.72) {
      pos = createVector(random(width), random(height * 0.76, height * 0.98));
    } else {
      let side = random() < 0.5 ? -40 : width + 40;
      pos = createVector(side, random(height * 0.30, height * 0.95));
    }
    let prev = pos.copy();
    let steps = 90 + floor(noise(i * 0.03) * 40);
    for (let s = 0; s < steps; s++) {
      let toC = createVector(cx - pos.x, cy - pos.y);
      let d = toC.mag();
      if (d < rCore * 1.08) break;
      toC.normalize();

      let ang = noise(pos.x * 0.001, pos.y * 0.001) * TAU * 2.0;
      let swirl = p5.Vector.fromAngle(ang);
      let v = p5.Vector.add(p5.Vector.mult(toC, 1.6), p5.Vector.mult(swirl, 0.75));
      v.mult(0.9 + 0.35 * noise(i * 0.2 + s * 0.05));

      let next = p5.Vector.add(pos, v);

      let tt = constrain((d - rCore) / (max(width, height) - rCore), 0, 1);
      let light = lerp(90, 26, tt);
      let hue = lerp(208, 230, tt);
      let alpha = lerp(0.08, 0.02, tt) * 0.6;
      stroke(hue, 12, light, alpha);
      strokeWeight(0.7 + 1.0 * (1 - tt) * (0.5 + 0.5 * noise(i * 0.1)));
      line(prev.x, prev.y, next.x, next.y);

      prev = next;
      pos = next;
    }
  }
}

function drawVoidAndHalo() {
  // Halo doux
  push();
  blendMode(ADD);
  noFill();
  for (let g = 0; g < 60; g++) {
    let rr = rCore + g * 3;
    let a = map(g, 0, 59, 0.07, 0.004);
    stroke(220, 25, 82, a);
    strokeWeight(2);
    ellipse(cx, cy, rr * 2, rr * 2);
  }
  pop();

  // Cercle central: bouche sans dents
  noStroke();
  fill(230, 20, 4, 1);
  ellipse(cx, cy, rCore * 2, rCore * 2);

  // Anneaux irréguliers, comme des ondes qui ne reviennent pas
  for (let i = 0; i < 64; i++) {
    let rr = rCore + 10 + i * 12;
    let amp = map(i, 0, 63, 28, 6);
    let col = color(210, 12, map(i, 0, 63, 64, 80), 0.035);
    noisyRing(cx, cy, rr, amp, 0.9 + i * 0.03, col, 1.4);
  }

  // Voile interne, très léger, pour adoucir le bord
  push();
  blendMode(SOFT_LIGHT);
  for (let k = 0; k < 5; k++) {
    let rr = rCore + 4 + k * 4;
    fill(230, 10, 12 + k * 2, 0.05);
    noStroke();
    ellipse(cx, cy, rr * 2, rr * 2);
  }
  pop();
}

function noisyRing(xc, yc, rad, amp, k, col, w) {
  noFill();
  stroke(col);
  strokeWeight(w);
  beginShape();
  for (let a = 0; a < TWO_PI; a += 0.06) {
    let nx = cos(a) * k + 10.3;
    let ny = sin(a) * k + 4.7;
    let nr = rad + (noise(nx, ny) - 0.5) * amp;
    let x = xc + cos(a) * nr;
    let y = yc + sin(a) * nr;
    vertex(x, y);
  }
  endShape(CLOSE);
}

function scatterDust() {
  // Poussières/éclats lointains
  noStroke();
  let M = 1100;
  for (let i = 0; i < M; i++) {
    let x = random(-50, width + 50);
    let y = random(-50, height * 0.98);
    let d = dist(x, y, cx, cy);
    if (d < rCore * 1.1) continue;
    let l = lerp(88, 30, constrain(y / height, 0, 1)) + (noise(i * 0.13) - 0.5) * 6;
    let h = lerp(210, 235, constrain((y - cy + 800) / (height + 800), 0, 1));
    let a = 0.02 + 0.04 * pow(noise(x * 0.01, y * 0.01), 2);
    fill(h, 10, l, a);
    let sz = 1 + noise(i * 0.07) * 2;
    ellipse(x, y, sz, sz);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function draw() {
  colorMode(RGB, 255, 255, 255, 255);
  background(0);

  // Composition parameters
  const cx = width * 0.5;
  const cy = height * 0.52;
  const rx = 260;
  const ry = 420;

  // Background gradient
  drawBackground();

  // Subtle mist layers behind the portal
  drawVeilMists(cx, cy, rx, ry, 0.0015, 1400, 0.6);

  // Portal: void and faint rim
  drawPortal(cx, cy, rx, ry);

  // Flow field veils gravitating toward the void
  drawFlowVeils(cx, cy, rx, ry);

  // Horizon band (threshold)
  drawHorizon();

  // Cinder motes drifting toward the edge
  drawAsh(cx, cy, rx, ry);

  // Soft outer vignette
  vignette();
}

function drawBackground() {
  noStroke();
  let colTop = color(12, 15, 18);
  let colMid = color(22, 24, 30);
  let colBot = color(0, 0, 0);
  let midY = 900;
  for (let y = 0; y < height; y++) {
    let c;
    if (y < midY) {
      let t = y / midY;
      c = lerpColor(colTop, colMid, t);
    } else {
      let t = (y - midY) / (height - midY);
      c = lerpColor(colMid, colBot, t);
    }
    fill(red(c), green(c), blue(c), 255);
    rect(0, y, width, 1);
  }

  // Large, dim clouding to avoid flatness
  blendMode(ADD);
  for (let i = 0; i < 600; i++) {
    let x = random(-200, width + 200);
    let y = random(-200, height + 200);
    let r = random(120, 420);
    let a = random(4, 14);
    let tint = color(40, 50, 70, a);
    radialStamp(x, y, r, tint, 8);
  }
  blendMode(BLEND);
}

function drawPortal(cx, cy, rx, ry) {
  noStroke();
  fill(0);
  ellipse(cx, cy, rx * 2, ry * 2);

  // Faint luminous rim (memory of edges)
  noFill();
  for (let k = 0; k < 90; k++) {
    let a = map(k, 0, 90, 40, 0);
    stroke(200, 208, 220, a);
    strokeWeight(1.2 + k * 0.085);
    ellipse(cx, cy, (rx * 2) + k * 2.0, (ry * 2) + k * 2.0);
  }

  // Slight inner darkness deepening
  noStroke();
  for (let t = 0; t < 40; t++) {
    let a = map(t, 0, 40, 9, 0);
    fill(0, a);
    ellipse(cx, cy, (rx * 2) - t * 3.0, (ry * 2) - t * 3.0);
  }
}

function drawVeilMists(cx, cy, rx, ry, scale, count, alphaMul) {
  // Soft, wide strokes hinting at dissolution
  push();
  blendMode(SCREEN);
  strokeCap(ROUND);
  for (let i = 0; i < count; i++) {
    let x = random(width);
    let y = random(height);
    if (inPortal(x, y, cx, cy, rx, ry, 0)) continue;
    let steps = floor(random(12, 26));
    let sw = random(6, 18);
    strokeWeight(sw);
    let baseA = random(4, 12) * alphaMul;
    let col = random() < 0.7
      ? [200 + random(15), 210 + random(10), 225 + random(5), baseA]
      : [150 + random(30), 190 + random(35), 210 + random(25), baseA];
    stroke(col[0], col[1], col[2], col[3]);

    for (let s = 0; s < steps; s++) {
      let a = flowAngle(x, y, cx, cy, scale, 0.35);
      let nx = x + cos(a) * random(8, 16);
      let ny = y + sin(a) * random(8, 16);
      if (inPortal(nx, ny, cx, cy, rx, ry, -6)) break;
      line(x, y, nx, ny);
      x = nx; y = ny;
    }
  }
  pop();
}

function drawFlowVeils(cx, cy, rx, ry) {
  push();
  blendMode(BLEND);
  strokeCap(ROUND);

  let N = 4200;
  for (let i = 0; i < N; i++) {
    let x = random(width);
    let y = random(height);
    if (inPortal(x, y, cx, cy, rx, ry, 6)) continue;

    let steps = floor(random(55, 92));
    let sLen = random(1.05, 1.9);
    let sw = random(0.4, 1.2);
    strokeWeight(sw);

    // Slight cool or ash tone
    let useCool = random() < 0.4;
    let base = useCool
      ? [165 + random(20), 185 + random(25), 205 + random(35)]
      : [150 + random(25), 150 + random(25), 155 + random(15)];
    let aBase = random(18, 40);
    stroke(base[0], base[1], base[2], aBase);

    let px = x, py = y;
    for (let s = 0; s < steps; s++) {
      let a = flowAngle(x, y, cx, cy, 0.0018, 0.55);
      let nx = x + cos(a) * sLen;
      let ny = y + sin(a) * sLen;

      if (inPortal(nx, ny, cx, cy, rx, ry, -2)) break;

      // Slight brightening when grazing the rim
      let e = ellipNorm(nx, ny, cx, cy, rx, ry);
      let tEdge = constrain(1 - abs(e - 1) * 6.0, 0, 1);
      if (tEdge > 0.001) {
        let extra = tEdge * 30;
        stroke(
          min(base[0] + extra, 255),
          min(base[1] + extra, 255),
          min(base[2] + extra, 255),
          aBase + tEdge * 30
        );
      } else {
        stroke(base[0], base[1], base[2], aBase);
      }

      line(x, y, nx, ny);
      x = nx; y = ny;

      // Keep lines within canvas
      if (x < -10 || x > width + 10 || y < -10 || y > height + 10) break;
    }
  }
  pop();
}

function drawHorizon() {
  // Luminous threshold band
  let y0 = 1400;
  noStroke();
  fill(230, 230, 235, 12);
  rect(0, y0 - 64, width, 128);

  // Filamented lines
  for (let i = 0; i < 180; i++) {
    let yy = y0 - 64 + i * (128 / 180) + random(-0.8, 0.8);
    let amp = 10 + noise(i * 0.07) * 36;
    stroke(200 + random(25), 205 + random(20), 210 + random(15), random(8, 26));
    strokeWeight(random(0.45, 1.3));
    line(-20 + random(-4, 4), yy, width + 20 + random(-4, 4), yy + random(-0.6, 0.6));
    // Subtle waviness overlay
    if (random() < 0.2) {
      strokeWeight(1.8);
      stroke(220, 225, 235, 6);
      let ox = random(-6, 6);
      line(-20, yy + sin(i * 0.12) * 0.5 + ox * 0.02, width + 20, yy + sin(i * 0.12 + 0.6) * 0.5);
    }
  }
}

function drawAsh(cx, cy, rx, ry) {
  push();
  noStroke();
  let count = 2600;
  for (let i = 0; i < count; i++) {
    let x = random(-40, width + 40);
    let y = random(-40, height + 40);
    if (inPortal(x, y, cx, cy, rx, ry, -8)) continue;

    let e = ellipNorm(x, y, cx, cy, rx, ry);
    let nearRim = constrain(1.3 - abs(e - 1) * 3.5, 0, 1);
    let dens = nearRim * (0.5 + 0.5 * noise(x * 0.02, y * 0.02));
    if (random() < 0.55 * dens + 0.06) {
      let r = random(0.4, 1.6) * (0.6 + 0.8 * nearRim);
      let a = random(15, 80) * (0.4 + 0.6 * nearRim);
      let c = random() < 0.25
        ? [180 + random(40), 195 + random(40), 220 + random(20), a]
        : [210 + random(45), 210 + random(45), 215 + random(40), a];
      fill(c[0], c[1], c[2], c[3]);
      ellipse(x, y, r, r);
    }
  }
  pop();
}

function vignette() {
  push();
  noFill();
  blendMode(MULTIPLY);
  for (let k = 0; k < 70; k++) {
    let a = map(k, 0, 70, 0, 40);
    stroke(0, a);
    strokeWeight(40 + k * 2.2);
    rectMode(CENTER);
    rect(width / 2, height / 2, width - k * 10, height - k * 10, 40);
  }
  blendMode(BLEND);
  pop();
}

// Helpers

function inPortal(x, y, cx, cy, rx, ry, m) {
  let rxx = max(1, rx + m);
  let ryy = max(1, ry + m);
  let dx = (x - cx) / rxx;
  let dy = (y - cy) / ryy;
  return dx * dx + dy * dy <= 1;
}

function ellipNorm(x, y, cx, cy, rx, ry) {
  let dx = (x - cx) / rx;
  let dy = (y - cy) / ry;
  return sqrt(dx * dx + dy * dy); // ~1 near edge
}

function flowAngle(x, y, cx, cy, s, pull) {
  // Noise-directed with attraction to center
  let n = noise(x * s, y * s, 10);
  let aNoise = n * TAU * 2.0 - PI;
  let aToC = atan2(cy - y, cx - x);
  return angleLerp(aNoise, aToC, pull);
}

function angleLerp(a, b, t) {
  let d = atan2(sin(b - a), cos(b - a));
  return a + d * t;
}

function radialStamp(x, y, r, col, rings) {
  noFill();
  for (let i = 0; i < rings; i++) {
    let t = i / (rings - 1);
    let a = lerp(alpha(col), 0, t);
    stroke(red(col), green(col), blue(col), a);
    strokeWeight(2 + i * 2);
    ellipse(x, y, r * (1 + t), r * (1 + t));
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function draw() {
  background(10, 12, 18);
  drawVerticalDeepGradient();
  addSubtleClouds();
  drawPortal();
  drawHorizonMist();
  drawFlowLines();
  drawMotes();
  drawVignette();
  addGrain();
}

// Background vertical gradient, almost black with a faint temperature shift
function drawVerticalDeepGradient() {
  noStroke();
  let topCol = color(10, 13, 19);
  let botCol = color(7, 6, 10);
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let c = lerpColor(topCol, botCol, pow(t, 1.1));
    fill(c);
    rect(0, y, width, 1);
  }
}

// Subtle cloud texture to avoid flatness
function addSubtleClouds() {
  noStroke();
  for (let y = 0; y < height; y += 3) {
    for (let x = 0; x < width; x += 3) {
      let n = noise(x * 0.0018, y * 0.0018);
      if (n > 0.6) {
        let a = map(n, 0.6, 1, 3, 20);
        fill(12, 10, 16, a);
        rect(x, y, 3, 3);
      }
    }
  }
}

// Luminous central oval-veil (threshold)
function drawPortal() {
  let cx = width * 0.5;
  let cy = height * 0.58;

  // Layered translucent ellipses: wide to narrow
  noStroke();
  let layers = 130;
  for (let i = 0; i < layers; i++) {
    let t = i / (layers - 1);
    let a = lerp(width * 0.95, width * 0.22, t);
    let b = lerp(height * 1.35, height * 0.28, t);
    let wobble = (noise(t * 5.0) - 0.5) * 0.06;
    let aa = a * (1 + wobble * random(-1, 1));
    let bb = b * (1 + wobble * random(-1, 1));
    let col = color(235, 232, 225, map(1 - t, 0, 1, 2, 16));
    fill(col);
    ellipse(cx, cy, aa, bb);
  }

  // Inner core soft glow
  for (let i = 0; i < 80; i++) {
    let w = random(width * 0.02, width * 0.07);
    let h = random(height * 0.45, height * 0.7);
    let x = cx + random(-width * 0.03, width * 0.03);
    let y = cy + random(-height * 0.02, height * 0.02);
    fill(245, 242, 236, 10);
    ellipse(x, y, w, h);
  }

  // Veils: faint, curved vertical strokes inside the portal
  stroke(250, 246, 239, 12);
  strokeWeight(1.5);
  noFill();
  for (let k = 0; k < 40; k++) {
    let xoff = random(-width * 0.07, width * 0.07);
    let x1 = cx + xoff + random(-20, 20);
    let x2 = cx + xoff + random(-20, 20);
    let x3 = cx + xoff + random(-20, 20);
    let y1 = cy - height * 0.45;
    let y2 = cy;
    let y3 = cy + height * 0.45;
    bezier(
      x1, y1,
      x1 + random(-60, 60), y1 + random(100, 200),
      x2 + random(-60, 60), y2 + random(-100, 100),
      x3, y3
    );
  }

  // Faint rim highlights
  noFill();
  stroke(255, 252, 244, 30);
  strokeWeight(2);
  ellipse(cx, cy, width * 0.24, height * 0.32);
  stroke(255, 252, 244, 8);
  ellipse(cx, cy, width * 0.28, height * 0.38);
}

// The threshold haze (a quiet "shore") around a soft horizon
function drawHorizonMist() {
  let y0 = height * 0.62;
  noStroke();
  for (let i = -180; i <= 180; i++) {
    let y = y0 + i;
    let t = abs(i) / 180;
    let a = (1 - pow(t, 1.8)) * 26;
    fill(232, 228, 219, a);
    rect(0, y, width, 1);
  }

  // Subtle waviness
  stroke(235, 231, 223, 25);
  strokeWeight(1);
  noFill();
  for (let k = 0; k < 90; k++) {
    let amp = random(6, 22);
    let yy = y0 + random(-30, 30);
    beginShape();
    for (let x = -50; x <= width + 50; x += 6) {
      let n = noise(x * 0.002, k * 0.05);
      let y = yy + (n - 0.5) * amp;
      vertex(x, y);
    }
    endShape();
  }
}

// Particles/lines drifting toward the portal: contours dissolve into the threshold
function drawFlowLines() {
  let cx = width * 0.5;
  let cy = height * 0.58;
  let N = 5200;
  strokeWeight(0.7);
  for (let i = 0; i < N; i++) {
    let x = random(width);
    let y = random(height * 0.35, height * 0.95);
    let steps = int(random(40, 85));
    let px = x, py = y;
    let alphaBase = random(7, 22);
    for (let s = 0; s < steps; s++) {
      let dx = cx - x;
      let dy = cy - y;
      let r = Math.hypot(dx, dy) + 0.0001;
      let pull = 0.006 + 0.018 / (1 + r / 300);
      let ang = noise(x * 0.003, y * 0.003) * TAU * 2.0;
      let vx = cos(ang) * 0.7 + dx / r;
      let vy = sin(ang) * 0.7 + (dy / r) * 0.9;

      x += vx * pull * 200;
      y += vy * pull * 200;

      let t = constrain(map(r, 0, width * 0.6, 0, 1), 0, 1);
      let rr = lerp(245, 120, t);
      let gg = lerp(242, 110, t);
      let bb = lerp(236, 150, t);
      stroke(rr, gg, bb, alphaBase * (1 - s / steps));
      line(px, py, x, y);

      px = x; py = y;
      if (x < -50 || x > width + 50 || y < -50 || y > height + 50) break;
    }
  }
}

// Small motes shimmering near the portal’s edge
function drawMotes() {
  let cx = width * 0.5;
  let cy = height * 0.58;
  let a = width * 0.25;
  let b = height * 0.34;
  noStroke();
  for (let i = 0; i < 1400; i++) {
    let th = random(TAU);
    let rr = 1 + randomGaussian() * 0.2;
    let x = cx + a * rr * cos(th) + randomGaussian() * 6;
    let y = cy + b * rr * sin(th) + randomGaussian() * 6;
    let sz = max(0.4, randomGaussian() * 0.5 + 1.1);
    let alpha = random(40, 120);
    fill(250, 246, 239, alpha * 0.25);
    ellipse(x, y, sz, sz);
  }
}

// Dark vignette to cradle the central light
function drawVignette() {
  noFill();
  for (let i = 0; i < 120; i++) {
    let a = map(i, 0, 119, 0, 180);
    stroke(0, 0, 0, a * 0.4);
    strokeWeight(4);
    rect(-40 + i, -40 + i, width + 80 - 2 * i, height + 80 - 2 * i, 20);
  }
}

// Film grain for tactile stillness
function addGrain() {
  noStroke();
  let count = 15000;
  for (let i = 0; i < count; i++) {
    let x = random(width);
    let y = random(height);
    let bright = random() < 0.5;
    let a = random(6, 14);
    if (bright) fill(255, 255, 255, a);
    else fill(0, 0, 0, a * 0.7);
    rect(x, y, 1, 1);
  }
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  colorMode(HSL, 360, 100, 100, 1);
  noLoop();
  noStroke();
  smooth();
  angleMode(RADIANS);

  const cx = width * 0.5;
  const cy = height * 0.55;
  const rx = 310; // central void radii
  const ry = 430;

  drawBackgroundGradient();
  drawThresholdBands(cx, cy, rx, ry);
  drawDust(14000, cx, cy, rx, ry);
  drawVeilMistLayers(cx, cy);
  drawSwirlThreads(cx, cy, rx, ry);
  drawCentralVoidAndHalo(cx, cy, rx, ry);
  drawEchoArcs(cx, cy, rx, ry);
  drawVignette();
  sprinkleGrain(12000);
}

function draw() {}

function drawBackgroundGradient() {
  // Vertical gradient: warm pale top to deep cool bottom
  const topC = color(38, 18, 88, 1);
  const botC = color(230, 25, 7, 1);
  for (let y = 0; y < height; y++) {
    const t = y / (height - 1);
    const e = easeInOutQuad(t);
    const c = lerpColor(topC, botC, e);
    stroke(c);
    line(0, y, width, y);
  }

  // Subtle oblique wash to add painterly depth
  push();
  const wash = color(210, 30, 12, 0.15);
  fill(wash);
  for (let i = 0; i < 60; i++) {
    const x = map(i, 0, 59, -width * 0.2, width * 1.2);
    const y = height * 0.1 + sin(i * 0.13) * 40;
    const w = width * 0.3 + (i % 5) * 10;
    const h = height * 1.2;
    rect(x, y, w, h);
  }
  pop();
}

function drawThresholdBands(cx, cy, rx, ry) {
  // Multiple translucent horizons as "seuils"
  noFill();
  strokeCap(ROUND);
  for (let b = 0; b < 9; b++) {
    const yBase = map(b, 0, 8, height * 0.18, height * 0.9);
    const amp = 12 + b * 2.5;
    const thick = 2 + (8 - b) * 0.8;
    const hue = lerp(210, 35, b / 8);
    const sat = lerp(25, 20, b / 8);
    const lig = lerp(55, 75, b / 8);
    const alp = lerp(0.09, 0.03, b / 8);
    stroke(color(hue, sat, lig, alp));
    strokeWeight(thick);
    const freq = 0.002 + b * 0.0006;
    let ox = random(1000);
    beginShape();
    for (let x = -40; x <= width + 40; x += 6) {
      const n = noise(x * freq, b * 0.13 + ox);
      const y = yBase + (n - 0.5) * 2 * amp + sin(x * 0.004 + b) * amp * 0.12;
      vertex(x, y);
    }
    endShape();
  }

  // Soft veil along central latitudes
  for (let i = 0; i < 3; i++) {
    const y = cy + (i - 1) * 65;
    const h = 120 + i * 30;
    const c = color(45, 18, 85, 0.07 - i * 0.015);
    drawSoftBand(0, y - h / 2, width, h, c);
  }
}

function drawSoftBand(x, y, w, h, c) {
  const layers = 30;
  const baseL = lightness(c);
  const baseA = alpha(c);
  const colH = hue(c);
  const colS = saturation(c);
  for (let i = 0; i < layers; i++) {
    const t = i / (layers - 1);
    const fall = 1 - abs(t * 2 - 1);
    const a = baseA * pow(fall, 1.25) * 0.8;
    fill(color(colH, colS, baseL, a));
    rect(x, y + t * h, w, 2);
  }
}

function drawDust(count, cx, cy, rx, ry) {
  // Specks that avoid the central void
  strokeCap(ROUND);
  for (let i = 0; i < count; i++) {
    let x = random(-50, width + 50);
    let y = random(-50, height + 50);
    if (inEllipse(x, y, cx, cy, rx * 1.12, ry * 1.12)) continue;

    const dy = y / height;
    const edgeBias = constrain(map(dist(x, y, cx, cy), 0, max(width, height), 0.2, 1.0), 0, 1);
    const h = lerp(210, 45, smoothstep(0.0, 1.0, 1 - dy)) + random(-4, 4);
    const s = lerp(15, 25, edgeBias) + random(-5, 5);
    const l = lerp(75, 55, dy) + random(-10, 8);
    const a = 0.06 * edgeBias * random(0.4, 1.0);
    stroke(color(h, s, l, a));
    strokeWeight(random(0.5, 1.8));
    point(x, y);
  }
}

function drawVeilMistLayers(cx, cy) {
  // Wisps that cross the frame
  for (let k = 0; k < 60; k++) {
    const y0 = random(height * 0.05, height * 0.95);
    const amp = random(8, 28);
    const thick = random(8, 22);
    const hueV = random(200, 230);
    const ligV = random(68, 82);
    const aV = random(0.018, 0.045);
    stroke(color(hueV, 12, ligV, aV));
    strokeWeight(thick);
    noFill();
    beginShape();
    let ox = random(1000);
    for (let x = -100; x <= width + 100; x += 12) {
      const n = noise(x * 0.0016, y0 * 0.003 + ox);
      const y = y0 + (n - 0.5) * 2 * amp + sin(x * 0.003 + y0 * 0.001) * amp * 0.25;
      vertex(x, y);
    }
    endShape();
  }
}

function drawSwirlThreads(cx, cy, rx, ry) {
  // Flowing threads toward the center: cool and warm interwoven
  strokeCap(ROUND);
  const fields = [
    { h1: 210, s1: 35, l1: 65, h2: 230, s2: 25, l2: 18, count: 650, sw: [0.6, 1.6], alpha: [0.05, 0.16] },
    { h1: 35,  s1: 50, l1: 60, h2: 10,  s2: 35, l2: 15, count: 520, sw: [0.5, 1.4], alpha: [0.04, 0.12] }
  ];

  for (const F of fields) {
    for (let i = 0; i < F.count; i++) {
      let p = randomStartOutsideEllipse(cx, cy, rx * 1.2, ry * 1.2);
      let x = p.x, y = p.y;
      let steps = floor(random(140, 280));
      let prevx = x, prevy = y;
      const ns = 0.00125 + random(-0.00025, 0.00025);
      const swirlW = random(0.35, 0.85);
      const stepMin = 0.6;
      const stepMax = 2.4;
      let aBase = random(F.alpha[0], F.alpha[1]);
      strokeWeight(random(F.sw[0], F.sw[1]));

      for (let s = 0; s < steps; s++) {
        const dx = cx - x;
        const dy = cy - y;
        const distC = max(1, sqrt(dx * dx + dy * dy));
        const t = constrain(map(distC, 50, max(width, height) * 0.8, 1, 0), 0, 1);

        if (pointInEllipse(x, y, cx, cy, rx * 0.96, ry * 0.96)) break;

        // Vector to center
        let angToC = atan2(dy, dx);
        // Noise swirl
        let angSw = noise(x * ns, y * ns) * TWO_PI * 2.0 + noise(y * ns * 0.7, x * ns * 0.7) * 0.7;

        // Combine
        const vx = cos(angToC) + swirlW * cos(angSw);
        const vy = sin(angToC) + swirlW * sin(angSw);
        const mag = sqrt(vx * vx + vy * vy);
        let ux = vx / mag;
        let uy = vy / mag;

        const stepL = lerp(stepMax, stepMin, 1 - t) * (0.9 + noise(s * 0.07) * 0.2);

        x += ux * stepL;
        y += uy * stepL;

        // Color fade toward the center
        const h = lerp(F.h1, F.h2, 1 - t) + random(-3, 3);
        const sCol = lerp(F.s1, F.s2, 1 - t);
        const lCol = lerp(F.l1, F.l2, 1 - t);
        const aCol = aBase * (0.25 + t * 0.75);
        stroke(color(h, sCol, lCol, aCol));

        line(prevx, prevy, x, y);
        prevx = x; prevy = y;

        // Gentle jitter for organic feel
        x += (noise(y * 0.007) - 0.5) * 0.2;
        y += (noise(x * 0.007) - 0.5) * 0.2;

        // Early stop if lingering near center
        if (distC < 22 && s > 30) break;
      }
    }
  }
}

function drawCentralVoidAndHalo(cx, cy, rx, ry) {
  // Core darkness
  push();
  noStroke();
  fill(color(230, 30, 4, 1));
  ellipse(cx, cy, rx * 2.08, ry * 2.08);

  // Inner deepening
  for (let i = 0; i < 40; i++) {
    const t = i / 39;
    const a = 0.08 * (1 - t);
    fill(color(230, 25, 3, a));
    ellipse(cx, cy, rx * 2.08 - t * 10, ry * 2.08 - t * 14);
  }

  // Halo with additive strokes
  blendMode(ADD);
  noFill();
  for (let r = 0; r < 160; r++) {
    const rr = 1 + r / 160;
    const h = lerp(36, 210, r / 160);
    const s = lerp(40, 25, r / 160);
    const l = lerp(85, 70, r / 160);
    const a = lerp(0.20, 0.02, r / 160);
    stroke(color(h, s, l, a));
    strokeWeight(1.2 + (1 - r / 160) * 2.5);

    const jitter = 1.8;
    beginShape();
    for (let th = 0; th <= TWO_PI; th += 0.03) {
      const nx = cos(th), ny = sin(th);
      const jx = (noise(th * 0.7, r * 0.15) - 0.5) * jitter;
      const jy = (noise(th * 1.1 + 77, r * 0.12) - 0.5) * jitter;
      const ex = cx + (rx * rr + jx) * nx * 1.03;
      const ey = cy + (ry * rr + jy) * ny * 1.03;
      vertex(ex, ey);
    }
    endShape();
  }
  blendMode(BLEND);
  pop();
}

function drawEchoArcs(cx, cy, rx, ry) {
  noFill();
  strokeCap(ROUND);
  for (let i = 0; i < 36; i++) {
    const sc = 1.2 + i * 0.045;
    const h = lerp(210, 35, i / 36);
    const l = lerp(60, 78, i / 36);
    const a = lerp(0.045, 0.008, i / 36);
    stroke(color(h, 18, l, a));
    strokeWeight(1.2);
    const angSpan = random(PI * 0.55, PI * 0.9);
    const start = random(TWO_PI);
    const end = start + angSpan;
    arc(cx, cy, rx * 2 * sc, ry * 2 * sc, start, end);
  }
}

function drawVignette() {
  // Darken edges
  push();
  noFill();
  const layers = 22;
  for (let i = 0; i < layers; i++) {
    const t = i / (layers - 1);
    const pad = lerp(0, max(width, height) * 0.4, t);
    const a = lerp(0.0, 0.12, t) * 0.9;
    stroke(color(230, 30, 5, a));
    strokeWeight(60);
    rect(-pad, -pad, width + pad * 2, height + pad * 2, 40);
  }
  pop();
}

function sprinkleGrain(n) {
  // Fine film grain
  for (let i = 0; i < n; i++) {
    const x = random(width);
    const y = random(height);
    const g = random() < 0.5 ? 95 : 10;
    const l = g + random(-5, 5);
    const a = random(0.01, 0.03);
    stroke(color(0, 0, l, a));
    strokeWeight(random(0.3, 0.8));
    point(x, y);
  }
}

// Helpers

function randomStartOutsideEllipse(cx, cy, rx, ry) {
  // Start near canvas edges, bias to outside the central ellipse
  let x, y;
  for (let k = 0; k < 1000; k++) {
    const side = floor(random(4));
    if (side === 0) { x = random(-40, -10); y = random(-40, height + 40); }
    else if (side === 1) { x = random(width + 10, width + 40); y = random(-40, height + 40); }
    else if (side === 2) { x = random(-40, width + 40); y = random(-40, -10); }
    else { x = random(-40, width + 40); y = random(height + 10, height + 40); }
    if (!pointInEllipse(x, y, cx, cy, rx, ry)) break;
  }
  return { x, y };
}

function pointInEllipse(px, py, cx, cy, rx, ry) {
  const dx = px - cx;
  const dy = py - cy;
  return (dx * dx) / (rx * rx) + (dy * dy) / (ry * ry) <= 1.0;
}

function inEllipse(px, py, cx, cy, rx, ry) {
  return pointInEllipse(px, py, cx, cy, rx, ry);
}

function easeInOutQuad(t) {
  return t < 0.5 ? 2 * t * t : 1 - pow(-2 * t + 2, 2) / 2;
}

function smoothstep(edge0, edge1, x) {
  const t = constrain((x - edge0) / (edge1 - edge0), 0, 1);
  return t * t * (3 - 2 * t);
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function draw() {
  // Background vertical gradient
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let c1 = color(6, 7, 12);
    let c2 = color(18, 22, 35);
    let c3 = color(8, 10, 14);
    let c;
    if (t < 0.5) {
      c = lerpColor(c1, c2, map(t, 0, 0.5, 0, 1));
    } else {
      c = lerpColor(c2, c3, map(t, 0.5, 1, 0, 1));
    }
    stroke(c);
    line(0, y, width, y);
  }

  // Subtle horizontal veils
  noFill();
  for (let y = 300; y < 1700; y += 2) {
    let a = map(noise(y * 0.005), 0, 1, 5, 25);
    stroke(220, 230, 230, a);
    let xoff = map(noise(100 + y * 0.003), 0, 1, -120, 120);
    line(100 + xoff, y, width - 100 - xoff, y);
  }

  // Soft radial vignette base
  noStroke();
  for (let r = max(width, height) * 1.1; r > 200; r -= 20) {
    let alpha = map(r, max(width, height) * 1.1, 200, 0, 90);
    fill(0, alpha);
    ellipse(width / 2, height / 2, r * 1.7, r * 2.0);
  }

  // Portal parameters
  let cx = width / 2;
  let cy = height * 0.52;
  let rx = width * 0.22;
  let ry = height * 0.33;

  // Outer glow of the portal
  noStroke();
  for (let i = 0; i < 80; i++) {
    let t = i / 79;
    let rrX = rx * map(t, 0, 1, 1.8, 0.95);
    let rrY = ry * map(t, 0, 1, 1.8, 0.95);
    let col = lerpColor(color(30, 35, 50, 0), color(220, 220, 230, 14), t);
    fill(col);
    ellipse(cx, cy, rrX * 2, rrY * 2);
  }

  // Inner darkness
  for (let i = 0; i < 80; i++) {
    let t = i / 79;
    let rrX = rx * map(t, 0, 1, 0.95, 0.0);
    let rrY = ry * map(t, 0, 1, 0.95, 0.0);
    let col = lerpColor(color(240, 240, 245, 10), color(0, 0, 0, 220), t);
    fill(col);
    ellipse(cx, cy, rrX * 2, rrY * 2);
  }

  // Bright rim points (irregular)
  strokeWeight(3);
  for (let a = 0; a < TWO_PI; a += 0.01) {
    let nx = cos(a);
    let ny = sin(a);
    let rEdgeX = rx * (1 + 0.03 * noise(10 + nx * 2, 10 + ny * 2));
    let rEdgeY = ry * (1 + 0.03 * noise(20 + nx * 2, 20 + ny * 2));
    let x = cx + rEdgeX * nx;
    let y = cy + rEdgeY * ny;
    stroke(240, 240, 250, 60);
    point(x, y);
  }

  // Flow field threads converging toward the portal
  strokeWeight(0.5);
  let nParticles = 1800;
  for (let i = 0; i < nParticles; i++) {
    let side = floor(random(4));
    let x, y;
    if (side === 0) { x = random(width); y = -20; }
    else if (side === 1) { x = width + 20; y = random(height); }
    else if (side === 2) { x = random(width); y = height + 20; }
    else { x = -20; y = random(height); }

    let steps = 100;
    let px = x, py = y;

    for (let s = 0; s < steps; s++) {
      // Stop if inside portal ellipse
      let eVal = sq((px - cx) / rx) + sq((py - cy) / ry);
      if (eVal < 1.0) break;

      // Perlin field angle + gentle attraction
      let nAng = noise(px * 0.0015, py * 0.0015);
      let ang = map(nAng, 0, 1, -PI, PI);

      let dx = cx - px;
      let dy = cy - py;
      let d = sqrt(dx * dx + dy * dy);
      let ex = dx / (d + 0.0001);
      let ey = dy / (d + 0.0001);
      let pull = constrain(map(d, 0, max(width, height) * 0.9, 0.06, 0.3), 0.06, 0.3);

      let vx = cos(ang) * 0.8 + ex * pull;
      let vy = sin(ang) * 0.8 + ey * pull;

      // Color by distance
      let t = constrain(map(d, rx * 0.9, max(width, height), 0, 1), 0, 1);
      let r = lerp(180, 20, t);
      let g = lerp(210, 80, t);
      let b = lerp(220, 60, t);
      let alpha = lerp(35, 6, t) * (1 - 0.2 * noise(px * 0.01, py * 0.01));
      stroke(r, g, b, alpha);

      let nxp = px + vx * 2.0;
      let nyp = py + vy * 2.0;
      line(px, py, nxp, nyp);
      px = nxp; py = nyp;
    }
  }

  // Drifting motes
  noStroke();
  for (let i = 0; i < 2600; i++) {
    let a = random(TWO_PI);
    let rr = random(max(width, height) * 0.9);
    let x = cx + cos(a) * rr;
    let y = cy + sin(a) * rr * 0.9;
    let d2 = sq((x - cx) / rx) + sq((y - cy) / ry);
    if (d2 < 1.2) continue;
    let sz = random(0.5, 2.2);
    let fade = map(rr, 0, max(width, height) * 0.9, 60, 8);
    fill(220, 230, 235, fade);
    ellipse(x, y, sz, sz);
  }

  // Sea of forgetting: layered waves near bottom
  for (let k = 0; k < 8; k++) {
    let yBase = height * 0.74 + k * 28;
    let amp = 18 + k * 3;
    let sw = 1 + k * 0.25;
    stroke(30, 40, 50, 100 - k * 6);
    strokeWeight(sw);
    noFill();
    beginShape();
    for (let x = -50; x <= width + 50; x += 10) {
      let n = noise(x * 0.004, k * 0.3);
      let y = yBase + sin(x * 0.01 + k) * amp * 0.3 + (n - 0.5) * amp;
      vertex(x, y);
    }
    endShape();
  }

  // Darken below the sea
  noStroke();
  for (let y = int(height * 0.8); y <= height; y++) {
    let t = map(y, height * 0.8, height, 0, 1);
    fill(0, 0, 0, 120 * t);
    rect(0, y, width, 1);
  }

  // Fine glints near the rim
  strokeWeight(1.2);
  for (let i = 0; i < 1800; i++) {
    let a = random(TWO_PI);
    let rr = random(rx * 0.9, rx * 1.25);
    let x = cx + cos(a) * rr;
    let y = cy + sin(a) * rr * (ry / rx);
    let eVal = sq((x - cx) / rx) + sq((y - cy) / ry);
    if (eVal < 0.98 || eVal > 1.5) continue;
    stroke(240, 240, 250, random(30, 90));
    point(x, y);
  }

  // Corner vignette
  for (let i = 0; i < 80; i++) {
    let a = map(i, 0, 79, 0, 140);
    noFill();
    stroke(0, a);
    strokeWeight(40);
    rect(-30 - i * 2, -30 - i * 2, width + 60 + i * 4, height + 60 + i * 4, 80);
  }

  // Soft mist overlay
  noStroke();
  for (let y = 0; y < height; y += 3) {
    let a = 8 + 18 * noise(50 + y * 0.01);
    fill(200, 210, 220, a * 0.35);
    rect(0, y, width, 2);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  noStroke();
  colorMode(RGB, 255, 255, 255, 255);

  drawBackground();
  let cx = width * 0.5;
  let cy = height * 0.46;
  let rVoid = 240;

  drawHalo(cx, cy, rVoid + 10, 560);
  drawDistantDust(cx, cy, 620);

  drawRiver(cx, height * 1.02, height * 0.62);
  drawHorizonHaze(height * 0.60, height * 0.72);

  drawStonesAndShore();
  drawTree(width * 0.78, height * 0.96);

  placeMoths(cx, cy, rVoid);
  addForegroundGrasses();
  addForegroundDust();
}

function drawBackground() {
  let topC = color(9, 12, 22);
  let midC = color(21, 28, 44);
  let botC = color(28, 20, 24);
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let c;
    if (t < 0.45) {
      c = lerpColor(topC, midC, t / 0.45);
    } else {
      c = lerpColor(midC, botC, (t - 0.45) / (1 - 0.45));
    }
    stroke(c);
    line(0, y, width, y);
  }
  // Subtle cloud noise
  noStroke();
  for (let i = 0; i < 70000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.0015, y * 0.0018);
    let a = map(n, 0, 1, 0, 18);
    fill(10, 12, 16, a);
    rect(x, y, 1, 1);
  }
}

function drawHalo(cx, cy, rInner, rOuter) {
  noStroke();
  for (let r = rOuter; r > rInner; r -= 3) {
    let t = map(r, rOuter, rInner, 0, 1);
    let a = 6 + 70 * pow(1 - t, 1.6);
    let c = color(232, 225, 210, a);
    fill(c);
    ellipse(cx, cy, r * 2, r * 2);
  }
  // Slight warm rim
  for (let r = rInner + 40; r > rInner + 8; r -= 2) {
    let t = map(r, rInner + 40, rInner + 8, 0, 1);
    let a = 10 + 35 * (1 - t);
    fill(245, 235, 220, a);
    ellipse(cx, cy, r * 2, r * 2);
  }
  // Void disc
  fill(6, 8, 12);
  ellipse(cx, cy, (rInner - 10) * 2, (rInner - 10) * 2);

  // Gentle top-right glint
  push();
  translate(cx, cy);
  rotate(-PI / 8);
  for (let r = rInner + 40; r > rInner - 30; r -= 2.5) {
    let a = map(r, rInner + 40, rInner - 30, 0, 26);
    fill(240, 232, 220, a);
    arc(0, 0, r * 2.0, r * 2.0, -PI * 0.05, PI * 0.05, OPEN);
  }
  pop();
}

function drawDistantDust(cx, cy, radius) {
  noStroke();
  for (let i = 0; i < 3800; i++) {
    let ang = random(TWO_PI);
    let r = radius * sqrt(random());
    let x = cx + cos(ang) * r + (noise(i * 0.013) - 0.5) * 8;
    let y = cy + sin(ang) * r + (noise(i * 0.017) - 0.5) * 8;
    let gate = noise(x * 0.005, y * 0.005);
    if (gate > 0.52) {
      let a = map(gate, 0.52, 1, 8, 40);
      fill(238, 234, 222, a);
      rect(x, y, 1, 1);
    }
  }
}

function drawRiver(cx, yStart, yEnd) {
  let N = 300;
  let leftPts = [];
  let rightPts = [];
  let prev = null;
  for (let i = 0; i <= N; i++) {
    let y = map(i, 0, N, yStart, yEnd);
    let t = map(y, yStart, yEnd, 0, 1);
    let meander = map(t, 0, 1, 180, 40);
    let x = cx
      + (noise(10 + y * 0.0012) - 0.5) * meander * 1.2
      + sin(t * PI) * meander * 0.22
      + (noise(100 + y * 0.0021) - 0.5) * meander * 0.35;

    let w = map(t, 0, 1, 680, 10);
    let ang = -HALF_PI;
    if (prev) {
      ang = atan2(y - prev.y, x - prev.x);
    }
    let perp = ang - HALF_PI;
    let lx = x + cos(perp) * w * 0.5;
    let ly = y + sin(perp) * w * 0.5;
    let rx = x - cos(perp) * w * 0.5;
    let ry = y - sin(perp) * w * 0.5;

    leftPts.push({ x: lx, y: ly });
    rightPts.push({ x: rx, y: ry });
    prev = { x, y };
  }

  // Misty river fill
  noStroke();
  fill(232, 226, 214, 210);
  beginShape();
  for (let p of leftPts) vertex(p.x, p.y);
  for (let i = rightPts.length - 1; i >= 0; i--) vertex(rightPts[i].x, rightPts[i].y);
  endShape(CLOSE);

  // Edge softening mist
  for (let k = 0; k < 5; k++) {
    let a = 38 - k * 6;
    fill(234, 229, 219, a);
    beginShape();
    for (let p of leftPts) vertex(lerp(p.x, cx, 0.02 + k * 0.015), p.y - k * 0.6);
    for (let i = rightPts.length - 1; i >= 0; i--) {
      let p = rightPts[i];
      vertex(lerp(p.x, cx, 0.02 + k * 0.015), p.y - k * 0.6);
    }
    endShape(CLOSE);
  }

  // Inner luminous streaks
  stroke(250, 246, 238, 60);
  strokeWeight(1.2);
  for (let s = 0; s < 420; s++) {
    let tt = random(0.02, 0.98);
    let y = lerp(yStart, yEnd, tt);
    let t = map(y, yStart, yEnd, 0, 1);
    let meander = map(t, 0, 1, 180, 40);
    let x = cx
      + (noise(10 + y * 0.0012) - 0.5) * meander * 1.2
      + sin(t * PI) * meander * 0.22
      + (noise(100 + y * 0.0021) - 0.5) * meander * 0.35;
    let dx = (noise(11 + (y + 1) * 0.0012) - 0.5) * 2 - (noise(10 + y * 0.0012) - 0.5) * 2;
    let dy = -1;
    let ang = atan2(dy, dx);
    let len = map(t, 0, 1, 40, 6) * random(0.6, 1.2);
    let x2 = x + cos(ang) * len;
    let y2 = y + sin(ang) * len;
    line(x, y, x2, y2);
  }
  noStroke();
}

function drawHorizonHaze(y1, y2) {
  for (let y = y1; y <= y2; y += 1.5) {
    let t = map(y, y1, y2, 0, 1);
    let a = 40 * (1 - t) + 8;
    stroke(236, 232, 224, a);
    line(0, y, width, y);
  }
  noStroke();
}

function drawStonesAndShore() {
  // Stones on left bank
  for (let i = 0; i < 7; i++) {
    let bx = random(90, width * 0.28);
    let by = height * 0.96 + random(-8, 18);
    let w = random(40, 140) * (1 - i * 0.07);
    let h = random(120, 320) * (1 - i * 0.06);
    drawStone(bx, by, w, h, color(20, 24, 30, 240));
  }
  // Stones on right bank
  for (let i = 0; i < 5; i++) {
    let bx = random(width * 0.74, width * 0.92);
    let by = height * 0.97 + random(-10, 16);
    let w = random(50, 120) * (1 - i * 0.08);
    let h = random(150, 320) * (1 - i * 0.08);
    drawStone(bx, by, w, h, color(18, 22, 28, 240));
  }

  // Shore dark lip
  noFill();
  stroke(12, 14, 18, 130);
  strokeWeight(2.2);
  for (let x = 0; x < width; x += 3) {
    let y = height * 0.97 + noise(x * 0.003) * 6;
    line(x, y, x + 2, y + 0.5);
  }
  noStroke();
}

function drawStone(bx, by, w, h, col) {
  push();
  noStroke();
  fill(col);
  beginShape();
  let steps = 18;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let yy = by - h * t;
    let shapeW = w * (0.6 + 0.4 * cos(t * PI)) * (0.8 + 0.2 * noise(bx * 0.01, t * 3.1));
    let jitter = (noise(t * 5.1, bx * 0.02) - 0.5) * 10;
    vertex(bx - shapeW * 0.5 + jitter, yy);
  }
  for (let i = steps; i >= 0; i--) {
    let t = i / steps;
    let yy = by - h * t;
    let shapeW = w * (0.6 + 0.4 * cos(t * PI)) * (0.8 + 0.2 * noise(bx * 0.01 + 8.9, t * 3.3));
    let jitter = (noise(t * 4.7, bx * 0.03 + 7.1) - 0.5) * 10;
    vertex(bx + shapeW * 0.5 + jitter, yy);
  }
  endShape(CLOSE);

  // Slight rim light
  let rim = color(230, 224, 210, 26);
  fill(rim);
  beginShape();
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let yy = by - h * t * 0.92;
    let shapeW = w * 0.8 * (0.6 + 0.4 * cos(t * PI));
    vertex(bx - shapeW * 0.32, yy);
  }
  for (let i = steps; i >= 0; i--) {
    let t = i / steps;
    let yy = by - h * t * 0.92;
    let shapeW = w * 0.8 * (0.6 + 0.4 * cos(t * PI));
    vertex(bx - shapeW * 0.15, yy);
  }
  endShape(CLOSE);
  pop();
}

function drawTree(baseX, baseY) {
  push();
  stroke(10, 12, 16, 240);
  strokeCap(ROUND);
  branch(baseX, baseY, -PI * 0.48, 460, 10, 0);
  pop();
}

function branch(x, y, ang, len, w, depth) {
  if (len < 12 || depth > 9) return;
  strokeWeight(max(1, w));
  let nx = x + cos(ang) * len;
  let ny = y + sin(ang) * len;

  // Slight sway
  ny += -len * 0.05 * sin(noise(x * 0.01, y * 0.01) * TWO_PI);

  line(x, y, nx, ny);

  let nChild = 2 + (depth < 2 ? 1 : 0);
  for (let i = 0; i < nChild; i++) {
    let t = random(0.4, 0.9);
    let cx = lerp(x, nx, t);
    let cy = lerp(y, ny, t);
    let dang = random(-PI * 0.28, PI * 0.22) * (depth < 2 ? 1.2 : 1);
    let clen = len * random(0.36, 0.64);
    branch(cx, cy, ang + dang, clen, w * random(0.58, 0.74), depth + 1);
  }

  // Hanging twigs
  if (random() < 0.45 && len > 60) {
    let hx = lerp(x, nx, random(0.6, 0.95));
    let hy = lerp(y, ny, random(0.6, 0.95));
    let tlen = random(18, 46);
    strokeWeight(max(1, w * 0.3));
    line(hx, hy, hx + random(-6, 6), hy + tlen);
  }
}

function placeMoths(cx, cy, rVoid) {
  let p0 = createVector(width * 0.30, height * 0.95);
  let p1 = createVector(width * 0.56, height * 0.78);
  let p2 = createVector(cx - 80, cy + 60);
  let p3 = createVector(cx, cy - 10);

  let moths = 180;
  for (let i = 0; i < moths; i++) {
    let t = pow(random(), 0.7); // more near the end
    let pos = cubicBezier(p0, p1, p2, p3, t);
    let tan = cubicBezierTangent(p0, p1, p2, p3, t);
    let ang = atan2(tan.y, tan.x) - HALF_PI;
    let spread = lerp(120, 14, t);
    let jx = (noise(t * 6.2, i * 0.31) - 0.5) * spread;
    let jy = (noise(t * 7.1, i * 0.27 + 5.0) - 0.5) * spread * 0.8;
    let x = pos.x + jx;
    let y = pos.y + jy;

    let distToVoid = dist(x, y, cx, cy) - rVoid;
    if (distToVoid < -10) continue; // avoid drawing inside the void

    let sz = lerp(10, 3.5, t) * random(0.8, 1.3);
    let alpha = lerp(130, 28, t) * random(0.8, 1.1);
    drawMoth(x, y, sz, ang + random(-0.3, 0.3), alpha);
  }
}

function cubicBezier(p0, p1, p2, p3, t) {
  let x = pow(1 - t, 3) * p0.x + 3 * pow(1 - t, 2) * t * p1.x + 3 * (1 - t) * t * t * p2.x + t * t * t * p3.x;
  let y = pow(1 - t, 3) * p0.y + 3 * pow(1 - t, 2) * t * p1.y + 3 * (1 - t) * t * t * p2.y + t * t * t * p3.y;
  return createVector(x, y);
}

function cubicBezierTangent(p0, p1, p2, p3, t) {
  let x = -3 * pow(1 - t, 2) * p0.x + 3 * (pow(1 - t, 2) - 2 * (1 - t) * t) * p1.x + 3 * ((2 * (1 - t) * t - t * t) * p2.x) + 3 * t * t * p3.x;
  let y = -3 * pow(1 - t, 2) * p0.y + 3 * (pow(1 - t, 2) - 2 * (1 - t) * t) * p1.y + 3 * ((2 * (1 - t) * t - t * t) * p2.y) + 3 * t * t * p3.y;
  return createVector(x, y);
}

function drawMoth(x, y, s, rot, alpha) {
  push();
  translate(x, y);
  rotate(rot);
  noStroke();
  // wings
  fill(236, 231, 222, alpha);
  ellipse(-s * 0.42, 0, s * 0.84, s * 0.58);
  ellipse(s * 0.42, 0, s * 0.84, s * 0.58);
  // body
  fill(220, 214, 200, alpha * 0.95);
  ellipse(0, 0, s * 0.28, s * 0.72);
  pop();
}

function addForegroundGrasses() {
  stroke(9, 11, 14, 220);
  strokeCap(ROUND);
  // Left bank grasses
  for (let i = 0; i < 280; i++) {
    let bx = random(-40, width * 0.34);
    let by = height * 0.99 + random(-6, 10);
    let h = random(60, 220);
    let lean = random(-0.8, 0.2);
    let c1x = bx + random(-20, 10);
    let c1y = by - h * random(0.2, 0.45);
    let c2x = bx + h * lean * 0.4 + random(-10, 10);
    let c2y = by - h * random(0.6, 0.9);
    let ex = bx + h * lean + random(-6, 6);
    let ey = by - h + random(-6, 6);
    strokeWeight(random(1, 2.4));
    noFill();
    bezier(bx, by, c1x, c1y, c2x, c2y, ex, ey);
  }
  // Right bank grasses
  for (let i = 0; i < 220; i++) {
    let bx = random(width * 0.7, width + 40);
    let by = height * 0.99 + random(-6, 10);
    let h = random(60, 220);
    let lean = random(-0.2, 0.8);
    let c1x = bx + random(-10, 20);
    let c1y = by - h * random(0.2, 0.45);
    let c2x = bx + h * lean * 0.4 + random(-10, 10);
    let c2y = by - h * random(0.6, 0.9);
    let ex = bx + h * lean + random(-6, 6);
    let ey = by - h + random(-6, 6);
    strokeWeight(random(1, 2.4));
    noFill();
    bezier(bx, by, c1x, c1y, c2x, c2y, ex, ey);
  }
  noStroke();
}

function addForegroundDust() {
  noStroke();
  for (let i = 0; i < 2500; i++) {
    let x = random(width);
    let y = random(height * 0.45, height * 0.95);
    let n = noise(x * 0.003, y * 0.003);
    if (n > 0.62) {
      let a = map(n, 0.62, 1, 12, 46);
      fill(238, 234, 224, a);
      rect(x, y, 1, 1);
    }
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  colorMode(RGB, 255, 255, 255, 255);
  noStroke();
  drawBackgroundGradient();
  drawSkyMist();
  let portal = {
    x: width * 0.5,
    y: 1120,
    w: 420,
    h: 680
  };
  drawHorizonGlow(portal);
  let riverGeom = drawRiver(portal);
  drawPortal(portal);
  drawGrass(riverGeom.centerXForY, riverGeom.widthAtY, portal);
  drawCairn();
  drawAsh(riverGeom.centerXForY);
  addGrain(26000);
}

// Background gradient from deep blue-black to muted earth
function drawBackgroundGradient() {
  let cTop = color(8, 12, 16);
  let cBottom = color(28, 26, 27);
  for (let y = 0; y < height; y++) {
    let t = pow(y / height, 1.2);
    let c = lerpColor(cTop, cBottom, t);
    stroke(c);
    line(0, y, width, y);
  }
  noStroke();
}

// Subtle misty sky texture
function drawSkyMist() {
  let topLimit = 980;
  for (let i = 0; i < 1200; i++) {
    let x = random(width);
    let y = random(0, topLimit);
    let s = random(40, 220);
    let hue = 20 + random(14); // cool bluish gray
    fill(18 + hue, 24 + hue * 0.3, 30 + hue * 0.4, random(6, 14));
    ellipse(x, y, s * random(1.2, 1.8), s);
  }
  // A faint horizontal veil near the horizon
  for (let i = 0; i < 110; i++) {
    let y = 1040 + i * 2;
    let a = map(i, 0, 110, 10, 0);
    fill(200, 210, 220, a);
    rect(0, y, width, 2);
  }
}

// Gentle glow behind the portal
function drawHorizonGlow(portal) {
  push();
  translate(portal.x, portal.y + 20);
  noStroke();
  // Cool glow
  for (let i = 0; i < 180; i++) {
    let t = i / 180;
    let w = lerp(1200, 140, t);
    let h = w * 0.58;
    fill(178, 194, 206, lerp(10, 0, t));
    ellipse(0, 0, w, h);
  }
  // Warm inner hint
  for (let i = 0; i < 120; i++) {
    let t = i / 120;
    let w = lerp(820, 120, t);
    let h = w * 0.52;
    fill(230, 220, 210, lerp(12, 0, t));
    ellipse(0, 10, w, h);
  }
  pop();
}

// Compute center x for a given y (river meander)
function centerXForYFactory(portal) {
  return function(y) {
    let amp = map(constrain(y, portal.y + 80, height + 40), height + 40, portal.y + 80, 320, 60);
    let nx = noise(y * 0.002, 0.37);
    return width * 0.5 + (nx - 0.5) * 2 * amp;
  };
}

function widthAtYFactory(portal) {
  return function(y) {
    return map(constrain(y, portal.y + 90, height + 40), height + 40, portal.y + 90, 280, 22);
  };
}

// Draw the river as a tapering luminous ribbon
function drawRiver(portal) {
  let cxForY = centerXForYFactory(portal);
  let wForY = widthAtYFactory(portal);

  // Build centerline points from bottom to portal
  let pts = [];
  for (let y = height + 40; y >= portal.y + 90; y -= 10) {
    let x = cxForY(y);
    pts.push({ x: x, y: y });
  }

  // Build left and right banks
  let left = [];
  let right = [];
  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    let prev = i < pts.length - 1 ? pts[i + 1] : { x: cxForY(p.y + 10), y: p.y + 10 };
    let dx = p.x - prev.x;
    let dy = p.y - prev.y;
    let len = sqrt(dx * dx + dy * dy) + 0.0001;
    let nx = -dy / len;
    let ny = dx / len;
    let w = wForY(p.y);
    left.push({ x: p.x + nx * w * 0.5, y: p.y + ny * w * 0.5 });
    right.push({ x: p.x - nx * w * 0.5, y: p.y - ny * w * 0.5 });
  }

  // Fill river body
  noStroke();
  fill(230, 236, 240, 235);
  beginShape();
  for (let i = 0; i < left.length; i++) {
    vertex(left[i].x, left[i].y);
  }
  for (let i = right.length - 1; i >= 0; i--) {
    vertex(right[i].x, right[i].y);
  }
  endShape(CLOSE);

  // Inner soft shimmer along center
  stroke(245, 248, 250, 55);
  for (let i = 0; i < pts.length - 1; i++) {
    let a = pts[i];
    let b = pts[i + 1];
    let sw = map(a.y, height + 40, portal.y + 90, 6.5, 1.2);
    strokeWeight(sw);
    line(a.x, a.y, b.x, b.y);
  }

  // Edge darkening for depth
  stroke(40, 46, 52, 60);
  for (let i = 0; i < left.length - 1; i++) {
    let a = left[i], b = left[i + 1];
    let sw = map(a.y, height + 40, portal.y + 90, 1.8, 0.6);
    strokeWeight(sw);
    line(a.x, a.y, b.x, b.y);
  }
  for (let i = 0; i < right.length - 1; i++) {
    let a = right[i], b = right[i + 1];
    let sw = map(a.y, height + 40, portal.y + 90, 1.8, 0.6);
    strokeWeight(sw);
    line(a.x, a.y, b.x, b.y);
  }
  noStroke();

  return {
    centerXForY: cxForY,
    widthAtY: wForY
  };
}

// The dark oval portal swallowing the river
function drawPortal(portal) {
  push();
  noStroke();
  fill(4, 5, 7);
  ellipse(portal.x, portal.y, portal.w, portal.h);
  // Subtle rim light
  stroke(210, 220, 230, 30);
  noFill();
  strokeWeight(2);
  ellipse(portal.x, portal.y, portal.w + 4, portal.h + 4);
  pop();
}

// Sparse withered grass on the banks
function drawGrass(centerXForY, widthAtY, portal) {
  let n = 1800;
  for (let i = 0; i < n; i++) {
    let y = random(portal.y + 140, height - 40);
    let x = random(width);
    let cx = centerXForY(y);
    let w = widthAtY(y) * 0.6;
    if (abs(x - cx) < w) continue; // avoid river

    let len = random(20, 120) * pow(map(y, portal.y + 140, height, 0.2, 1), 1.2);
    let lean = random(-18, -6); // wind-leaning
    let thickness = map(y, portal.y + 140, height, 0.5, 1.6);
    stroke(25, 30, 33, map(y, portal.y + 140, height, 70, 140));
    strokeWeight(thickness);

    let x1 = x, y1 = y;
    let x2 = x + lean * 0.3, y2 = y - len * 0.35;
    let x3 = x + lean * 0.8, y3 = y - len * 0.75;
    let x4 = x + lean, y4 = y - len;

    noFill();
    bezier(x1, y1, x2, y2, x3, y3, x4, y4);

    // Occasional seed stem
    if (random() < 0.05) {
      strokeWeight(thickness * 0.7);
      line(x4, y4, x4 + random(-4, 4), y4 - random(6, 14));
    }
  }
}

// Small cairn of stones as a quiet marker
function drawCairn() {
  let baseX = width * 0.22;
  let baseY = height - 140;

  // Ground shadow
  noStroke();
  fill(0, 0, 0, 60);
  ellipse(baseX + 6, baseY + 34, 240, 38);

  let levels = 4;
  let y = baseY;
  for (let i = 0; i < levels; i++) {
    let w = lerp(180, 90, i / (levels - 1));
    let h = w * 0.48 + random(-4, 4);
    let ox = random(-8, 8);
    fill(10, 10, 12);
    noStroke();
    ellipse(baseX + ox, y, w, h);
    // tiny highlight
    fill(80, 90, 100, 30);
    ellipse(baseX + ox - w * 0.1, y - h * 0.15, w * 0.3, h * 0.22);
    y -= h * 0.68;
  }
}

// Drifting ash/petals
function drawAsh(centerXForY) {
  let n = 230;
  for (let i = 0; i < n; i++) {
    let y = random(980, height - 160);
    let cx = centerXForY(y);
    let x = cx + randomGaussian() * 220 + random(-260, 260) * 0.2;
    let a = random(-0.7, -0.2);
    let w = random(1.2, 2.1);
    let h = random(3.4, 6.2);
    push();
    translate(x, y);
    rotate(a + noise(x * 0.002, y * 0.002) * 0.4);
    noStroke();
    fill(200, 210, 215, random(40, 90));
    ellipse(0, 0, w, h);
    pop();
  }
}

// Fine film grain for texture
function addGrain(count) {
  strokeWeight(1);
  for (let i = 0; i < count; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.01, y * 0.01);
    if (random() < 0.5) {
      stroke(255, 255, 255, 8 * n);
    } else {
      stroke(0, 0, 0, 8 * (1 - n));
    }
    point(x, y);
  }
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  colorMode(RGB, 255, 255, 255, 255);
  noStroke();

  // Base gradient sky
  drawVerticalGradient(color(8, 10, 16), color(6, 7, 10));

  // Portal glow behind everything
  let cx = width * 0.5;
  let cy = 900;
  drawPortalGlow(cx, cy);

  // Distant haze behind cliffs (soft)
  for (let i = 0; i < 3; i++) {
    drawFogBand(860 + i * 40, 80 + i * 25, 18 - i * 3, 0.002 + i * 0.0006, 100 + i * 37);
  }

  // Cliffs framing the passage
  drawCliff('left', 0.13);
  drawCliff('right', 0.57);

  // Build and draw river
  let river = buildRiver(980);
  drawRiver(river);

  // Heavier mist hugging river
  for (let i = 0; i < 5; i++) {
    drawFogBand(1000 + i * 60, 120 + i * 30, 32 - i * 4, 0.0022 + i * 0.0008, 300 + i * 71);
  }

  // Rising motes toward the light
  drawRisingMotes(cx, cy);

  // Boat on the river
  drawBoatOnRiver(river);

  // Foreground flora (white lilies and grasses)
  drawForegroundFlora();

  // Subtle vignette
  vignette();

  // Fine grain
  filmGrain(6500, 18);
}

// ---------- Components ----------

function drawVerticalGradient(cTop, cBottom) {
  for (let y = 0; y < height; y++) {
    let t = y / (height - 1);
    let c = lerpColor(cTop, cBottom, t);
    stroke(c);
    line(0, y, width, y);
  }
  noStroke();
}

function drawPortalGlow(xc, yc) {
  push();
  translate(xc, yc);
  noStroke();
  for (let i = 0; i < 120; i++) {
    let t = i / 119;
    let s = lerp(70, 1100, pow(t, 1.6));
    let sy = lerp(180, 1500, pow(t, 1.6));
    let a = 190 * pow(1 - t, 2.1);
    fill(252, 248, 238, a);
    ellipse(0, 0, s, sy);
  }
  pop();
}

function drawCliff(side, off) {
  // Dark rock tone
  fill(10, 12, 16);
  beginShape();
  if (side === 'left') {
    vertex(0, 0);
    vertex(0, height);
    for (let y = height; y >= 220; y -= 8) {
      let yy = y * 0.002 + off;
      let edge = map(noise(yy), 0, 1, 160, 360) + pow((y / height), 1.6) * 120 + noise(y * 0.01 + 10.0) * 28;
      // ease in top to open the gap
      let topEase = constrain(map(y, 220, 520, 0.2, 1.0), 0.2, 1.0);
      vertex(edge * topEase, y);
    }
    vertex(0, 220);
  } else {
    vertex(width, height);
    vertex(width, 0);
    for (let y = 220; y <= height; y += 8) {
      let yy = y * 0.002 + off;
      let edge = width - (map(noise(yy), 0, 1, 170, 440) + pow((y / height), 1.6) * 150 + noise(y * 0.01 + 20.0) * 34);
      let topEase = constrain(map(y, 220, 520, 0.2, 1.0), 0.2, 1.0);
      vertex(lerp(width - 6, edge, topEase), y);
    }
    vertex(width, height);
  }
  endShape(CLOSE);

  // Subtle vertical texture
  push();
  stroke(20, 22, 28, 25);
  for (let i = 0; i < 90; i++) {
    let x;
    if (side === 'left') {
      x = map(i, 0, 89, 50, 420) + noise(i * 0.14 + off) * 40;
    } else {
      x = width - (map(i, 0, 89, 60, 460) + noise(i * 0.14 + off) * 40);
    }
    for (let y = 260; y < height; y += 18) {
      let dx = noise(x * 0.02, y * 0.02 + off) * 6 - 3;
      line(x + dx, y, x + dx, y + 8);
    }
  }
  pop();
}

function buildRiver(horizonY) {
  let N = 320;
  let pts = [];
  let leftPts = [];
  let rightPts = [];
  let widths = [];
  for (let i = 0; i < N; i++) {
    let t = i / (N - 1);
    let y = lerp(height + 120, horizonY, t);
    let sway = sin(t * PI * 1.05 - 0.25) * 220;
    let meander = map(noise(t * 1.2 + 5.0), 0, 1, -140, 140);
    let micro = map(noise(t * 7.0 + 2.3), 0, 1, -28, 28);
    let x = width * 0.5 + sway + meander + micro;
    pts.push(createVector(x, y));
    let w = lerp(300, 8, pow(t, 1.55));
    widths.push(w);
  }
  // build sides
  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    let p2 = pts[min(i + 1, pts.length - 1)];
    let dx = p2.x - p.x;
    let dy = p2.y - p.y;
    let len = sqrt(dx * dx + dy * dy) + 0.0001;
    let nx = -(dy / len);
    let ny = dx / len;
    let hw = widths[i] * 0.5;
    leftPts.push(createVector(p.x - nx * hw, p.y - ny * hw));
    rightPts.push(createVector(p.x + nx * hw, p.y + ny * hw));
  }
  return { center: pts, left: leftPts, right: rightPts, widths: widths, horizonY: horizonY };
}

function drawRiver(riv) {
  // Water body
  noStroke();
  fill(12, 16, 22);
  beginShape();
  for (let i = 0; i < riv.left.length; i++) {
    vertex(riv.left[i].x, riv.left[i].y);
  }
  for (let i = riv.right.length - 1; i >= 0; i--) {
    vertex(riv.right[i].x, riv.right[i].y);
  }
  endShape(CLOSE);

  // Specular highlight along center
  stroke(245, 248, 255, 36);
  strokeCap(ROUND);
  for (let i = 0; i < riv.center.length - 1; i += 2) {
    let p = riv.center[i];
    let q = riv.center[i + 1];
    let t = i / (riv.center.length - 1);
    let w = map(t, 0, 1, 12, 1.2);
    strokeWeight(w);
    line(p.x, p.y, q.x, q.y);
  }

  // Tiny ripples near the banks
  stroke(220, 230, 240, 18);
  for (let i = 0; i < 340; i++) {
    let t = random();
    let idx = floor(t * (riv.center.length - 2));
    let p = riv.center[idx];
    let w = riv.widths[idx];
    let side = random() < 0.5 ? -1 : 1;
    let off = side * (w * 0.45 + random(2, 14));
    let x = p.x + off + random(-10, 10);
    let y = p.y + random(-6, 6);
    strokeWeight(random(0.6, 1.4));
    line(x - random(10, 24), y, x + random(10, 24), y);
  }
}

function drawFogBand(yBase, amp, alpha, scaleX, off) {
  fill(255, 255, 255, alpha);
  beginShape();
  vertex(0, height);
  for (let x = 0; x <= width; x += 16) {
    let y = yBase + (noise(x * scaleX + off, yBase * 0.001 + off) - 0.5) * 2 * amp;
    vertex(x, y);
  }
  vertex(width, height);
  endShape(CLOSE);
}

function drawBoatOnRiver(riv) {
  // place near upper section
  let tBoat = 0.82;
  let idx = floor(tBoat * (riv.center.length - 2));
  let p = riv.center[idx].copy();
  let q = riv.center[idx + 1].copy();
  let ang = atan2(q.y - p.y, q.x - p.x);

  push();
  translate(p.x, p.y);
  rotate(ang);

  // Reflection first (under)
  push();
  scale(1, -0.7);
  translate(0, -8);
  fill(0, 0, 0, 40);
  noStroke();
  drawHullShape(120, 26);
  drawFigure(26);
  pop();

  // Hull
  fill(8, 8, 10, 255);
  noStroke();
  drawHullShape(120, 26);

  // Figure
  drawFigure(26);

  pop();
}

function drawHullShape(L, W) {
  beginShape();
  vertex(-L * 0.5, 0);
  vertex(-L * 0.33, -W * 0.52);
  vertex(L * 0.33, -W * 0.52);
  vertex(L * 0.5, 0);
  vertex(L * 0.33, W * 0.52);
  vertex(-L * 0.33, W * 0.52);
  endShape(CLOSE);
}

function drawFigure(W) {
  // Simple seated figure
  fill(6, 6, 8, 255);
  // head
  ellipse(-8, -W * 0.8 - 10, 18, 18);
  // torso
  beginShape();
  vertex(-16, -W * 0.6);
  vertex(6, -W * 0.6);
  vertex(-2, -W * 0.15);
  vertex(-18, -W * 0.15);
  endShape(CLOSE);
  // knee / legs
  beginShape();
  vertex(-8, -W * 0.15);
  vertex(10, -W * 0.15);
  vertex(4, W * 0.05);
  vertex(-10, W * 0.05);
  endShape(CLOSE);
}

function drawRisingMotes(cx, cy) {
  noStroke();
  for (let i = 0; i < 2200; i++) {
    let x = random(width * 0.18, width * 0.82);
    let y = random(700, 1500);
    let dx = x - cx;
    let dy = y - cy;
    let d = sqrt(dx * dx + dy * dy);
    let p = exp(-d / 340);
    if (random() < p * 0.42) {
      let a = 26 + random(-6, 10);
      fill(250, 248, 242, a);
      let sz = random(0.8, 2.6);
      // Slight drift upward
      let vx = (noise(x * 0.01, y * 0.01) - 0.5) * 2.0;
      ellipse(x + vx * 6, y - random(0, 8), sz, sz);
    }
  }
}

function drawForegroundFlora() {
  // Grasses
  for (let i = 0; i < 220; i++) {
    let leftSide = random() < 0.5;
    let x = leftSide ? random(30, width * 0.4 - 60) : random(width * 0.6 + 60, width - 30);
    let yTop = random(height - 300, height - 40);
    let baseY = height + random(10, 60);
    stroke(36, 54, 42, 120);
    strokeWeight(1.2);
    noFill();
    let bend = random(-40, 40);
    bezier(x, baseY, x + bend * 0.5, lerp(baseY, yTop, 0.4), x + bend, lerp(baseY, yTop, 0.8), x, yTop);
  }

  // Lilies
  noStroke();
  for (let i = 0; i < 95; i++) {
    let leftSide = random() < 0.5;
    let x = leftSide ? random(50, width * 0.38 - 50) : random(width * 0.62 + 50, width - 50);
    let y = random(height - 240, height - 60);
    drawLily(x, y, random(0.8, 1.25), random(TWO_PI));
  }
}

function drawLily(x, y, s, rot) {
  push();
  translate(x, y);
  rotate(rot);
  // petals
  for (let k = 0; k < 6; k++) {
    push();
    rotate((TWO_PI / 6) * k + random(-0.05, 0.05));
    fill(250, 250, 248, 215);
    ellipse(0, -14 * s, 16 * s, 34 * s);
    pop();
  }
  // inner shade
  fill(238, 240, 236, 160);
  ellipse(0, 0, 10 * s, 10 * s);
  // faint highlight
  fill(255, 255, 255, 110);
  ellipse(2 * s, -2 * s, 4 * s, 4 * s);
  pop();
}

function vignette() {
  push();
  translate(width * 0.5, height * 0.5);
  noStroke();
  let maxD = max(width, height);
  for (let i = 0; i < 60; i++) {
    let t = i / 59;
    let a = map(t, 0, 1, 0, 130);
    fill(0, a);
    let sx = lerp(maxD * 1.1, maxD * 1.7, t);
    let sy = lerp(maxD * 1.3, maxD * 2.0, t);
    ellipse(0, 0, sx, sy);
  }
  pop();
}

function filmGrain(n, alphaMax) {
  loadPixels();
  // Draw grain as subtle dark/light noise overlay via set()
  // To keep it efficient, draw small rects instead of per-pixel ops
  noStroke();
  for (let i = 0; i < n; i++) {
    let x = floor(random(width));
    let y = floor(random(height));
    let a = random(alphaMax);
    let val = random() < 0.5 ? 255 : 0;
    fill(val, val, val, a * 0.25);
    rect(x, y, 1, 1);
  }
}

// ---------- End ----------

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  colorMode(RGB, 255, 255, 255, 255);
  noStroke();

  // Background vertical gradient: deep blue-black to dusk violet
  let topCol = color(8, 10, 16);
  let botCol = color(24, 20, 28);
  for (let y = 0; y < height; y++) {
    let t = y / (height - 1);
    let c = lerpColor(topCol, botCol, t);
    stroke(c);
    line(0, y, width, y);
  }

  // Sparse stars in upper half
  drawStars(520);

  // Subtle distant haze bands
  drawHighHaze();

  // Central void (elliptical "door") with faint halo
  let cx = width * 0.5;
  let cy = height * 0.48;
  let voidW = 700;
  let voidH = 900;
  drawVoid(cx, cy, voidW, voidH);

  // Ambient fog around the scene
  drawFogFields(cx, cy, voidW, voidH);

  // Swarm of "moths" spiraling inward
  drawSpiralMoths(cx, cy, voidW, voidH);

  // A silver thread from the mortal shore to the edge of the void
  drawThreadToVoid(cx, cy, voidW, voidH);

  // Ground gloom at the bottom
  drawGround();

  // Vignette corners
  vignette();
}

function drawStars(n) {
  push();
  noStroke();
  for (let i = 0; i < n; i++) {
    let x = random(width);
    let y = random(height * 0.58);
    let k = noise(x * 0.002, y * 0.003);
    if (k < 0.45) continue; // clustered sparsity
    let s = random() < 0.85 ? random(0.7, 1.8) : random(1.8, 2.7);
    let a = map(k, 0.45, 1.0, 30, 120);
    fill(220 + random(-20, 20), 230 + random(-10, 10), 240, a);
    ellipse(x, y, s, s);
    if (random() < 0.06) {
      // soft glint
      fill(240, 245, 250, a * 0.35);
      ellipse(x, y, s * 3.2, s * 0.8);
    }
  }
  pop();
}

function drawHighHaze() {
  push();
  noStroke();
  for (let i = 0; i < 1800; i++) {
    let x = random(width);
    let y = random(height * 0.55);
    let n = noise(x * 0.002, y * 0.005);
    if (n > 0.56) {
      let s = map(n, 0.56, 1, 2, 18);
      fill(60, 70, 90, map(n, 0.56, 1, 2, 10));
      ellipse(x, y, s * 2, s);
    }
  }
  pop();
}

function drawVoid(cx, cy, voidW, voidH) {
  push();
  noStroke();
  // Outer halo (subtle, cooler)
  for (let i = 0; i < 280; i++) {
    let t = i / 279.0;
    let w = lerp(voidW * 1.7, voidW * 1.02, t);
    let h = lerp(voidH * 1.7, voidH * 1.02, t);
    let alpha = 10 * (1 - pow(t, 0.85));
    fill(28, 32, 44, alpha);
    ellipse(cx, cy, w, h);
  }

  // Gentle inner scatter near rim to soften
  for (let i = 0; i < 2200; i++) {
    let ang = random(TAU);
    let rr = randomGaussian() * 18 + (voidW * 0.5) * 0.98;
    let ex = cx + cos(ang) * rr * (voidW / (voidW + 1));
    let ey = cy + sin(ang) * rr * (voidH / (voidH + 1.5));
    fill(24, 26, 32, 8);
    ellipse(ex, ey, random(1, 3), random(1, 3));
  }

  // Solid void core
  fill(0);
  ellipse(cx, cy, voidW * 0.92, voidH * 0.92);

  // Slight feathered edge
  for (let i = 0; i < 120; i++) {
    let t = i / 119.0;
    let w = lerp(voidW * 0.98, voidW * 0.88, t);
    let h = lerp(voidH * 0.98, voidH * 0.88, t);
    let a = 10 * (1 - t);
    fill(0, a);
    ellipse(cx, cy, w, h);
  }
  pop();
}

function drawFogFields(cx, cy, voidW, voidH) {
  push();
  noStroke();
  // Fog clusters around and below the void
  fogCluster(cx - 180, cy + 170, 380, 200, 900, color(180, 188, 200, 8));
  fogCluster(cx + 120, cy + 260, 440, 240, 1100, color(170, 180, 195, 7));
  fogCluster(cx - 300, cy - 60, 300, 160, 600, color(160, 172, 190, 6));

  // Sparse drifting dust across the scene
  for (let i = 0; i < 2400; i++) {
    let x = random(width);
    let y = random(height);
    let nn = noise(x * 0.0018, y * 0.0012);
    if (nn > 0.63) {
      fill(210, 215, 225, map(nn, 0.63, 1, 2, 10));
      let s = map(nn, 0.63, 1, 0.5, 2.8);
      ellipse(x, y, s, s);
    }
  }
  pop();
}

function fogCluster(cx, cy, rx, ry, count, col) {
  fill(col);
  for (let i = 0; i < count; i++) {
    let x = cx + randomGaussian() * rx;
    let y = cy + randomGaussian() * ry;
    let s = abs(randomGaussian()) * 60 + 18;
    let a = alpha(col) * random(0.7, 1.0);
    fill(red(col), green(col), blue(col), a);
    ellipse(x, y, s, s * random(0.6, 1.0));
  }
}

function drawSpiralMoths(cx, cy, voidW, voidH) {
  push();
  // Two subtle swirls interleaved
  let N = 230;
  for (let i = 0; i < N; i++) {
    // Spiral radius towards void edge
    let t = i / (N - 1);
    let baseR = lerp(650, 120, t);
    let jitter = (noise(i * 0.12) - 0.5) * 28 + random(-6, 6);
    let r = baseR + jitter;

    // Angle evolution to create swirl
    let a = i * 0.34 + noise(i * 0.08) * 0.9 + 0.8;

    // Convert to ellipse-polar for visual balance
    let ex = cx + cos(a) * r * 1.0;
    let ey = cy + sin(a) * r * 0.78;

    // Orientation tangent to spiral
    let tangent = a + PI / 2 + (noise(i * 0.2) - 0.5) * 0.5;

    // Size scaling
    let sz = map(r, 650, 120, 3.6, 11.0) + random(-0.6, 0.6);

    // Color gradient: cooler far, warmer near
    let ct = constrain(map(r, 650, 120, 0, 1), 0, 1);
    let cFar = color(208, 210, 220);
    let cNear = color(255, 244, 220);
    let wingCol = lerpColor(cFar, cNear, pow(ct, 0.8));
    let glowAlpha = map(ct, 0, 1, 18, 38);

    // Occasional missing/ghost moth to imply fading
    let fadeProb = map(ct, 0, 1, 0.02, 0.18);
    let ghost = random() < fadeProb;

    // Draw glow
    noStroke();
    fill(red(wingCol), green(wingCol), blue(wingCol), glowAlpha);
    push();
    translate(ex, ey);
    rotate(tangent);
    ellipse(0, 0, sz * 3.2, sz * 2.0);
    pop();

    // Draw the moth
    drawMoth(ex, ey, tangent, sz, wingCol, ghost ? 0.5 : 1.0);

    // Tiny dust along the path
    if (random() < 0.45) {
      let dx = ex + random(-6, 6);
      let dy = ey + random(-6, 6);
      noStroke();
      fill(245, 238, 220, 18);
      ellipse(dx, dy, random(0.6, 1.8), random(0.6, 1.8));
    }
  }
  pop();
}

function drawMoth(x, y, ang, s, wingCol, intensity) {
  push();
  translate(x, y);
  rotate(ang + random(-0.08, 0.08));
  // subtle shadow
  noStroke();
  fill(0, 18 * intensity);
  ellipse(1, 2, s * 1.8, s * 0.9);

  // wings
  let edge = color(
    constrain(red(wingCol) - 20, 0, 255),
    constrain(green(wingCol) - 20, 0, 255),
    constrain(blue(wingCol) - 15, 0, 255),
    130 * intensity
  );
  stroke(edge);
  strokeWeight(0.6);
  fill(
    red(wingCol),
    green(wingCol),
    blue(wingCol),
    180 * intensity
  );
  let w = s * 1.2;
  let h = s * 0.7;

  // forewings
  ellipse(-s * 0.42, 0, w, h);
  ellipse(s * 0.42, 0, w, h);

  // hindwings
  fill(
    red(wingCol),
    green(wingCol),
    blue(wingCol),
    150 * intensity
  );
  ellipse(-s * 0.28, s * 0.15, s * 0.7, s * 0.5);
  ellipse(s * 0.28, s * 0.15, s * 0.7, s * 0.5);

  // body
  noStroke();
  fill(
    constrain(red(wingCol) - 30, 0, 255),
    constrain(green(wingCol) - 30, 0, 255),
    constrain(blue(wingCol) - 30, 0, 255),
    190 * intensity
  );
  ellipse(0, 0, s * 0.24, s * 0.9);
  pop();
}

function drawThreadToVoid(cx, cy, voidW, voidH) {
  // Bezier control points
  let x0 = width * 0.16, y0 = height * 0.86;
  let x1 = cx - voidW * 0.08, y1 = cy + voidH * 0.06;
  let c1x = x0 + width * 0.17, c1y = y0 - height * 0.33;
  let c2x = cx - voidW * 0.26, c2y = cy + voidH * 0.62;

  // Generate base points
  let pts = [];
  let N = 260;
  for (let i = 0; i <= N; i++) {
    let t = i / N;
    let bx = bezierPoint(x0, c1x, c2x, x1, t);
    let by = bezierPoint(y0, c1y, c2y, y1, t);
    pts.push(createVector(bx, by));
  }

  // Compute normals
  let norms = [];
  for (let i = 0; i <= N; i++) {
    let i0 = max(0, i - 1);
    let i1 = min(N, i + 1);
    let d = p5.Vector.sub(pts[i1], pts[i0]);
    d.normalize();
    norms.push(createVector(-d.y, d.x));
  }

  // Draw multiple strands
  for (let s = 0; s < 6; s++) {
    let prev = null;
    for (let i = 0; i <= N; i++) {
      let t = i / N;
      let amp = (1 - pow(t, 0.9)) * (4.2 + s * 0.55);
      let nval = noise(t * 3 + s * 10) * 2 - 1;
      let off = p5.Vector.mult(norms[i], nval * amp);
      let p = p5.Vector.add(pts[i], off);

      let w = lerp(2.0 + s * 0.2, 0.4, pow(t, 1.1));
      let a = lerp(160, 14, pow(t, 1.2));
      stroke(220, 230, 240, a);
      strokeWeight(w);
      if (prev) {
        line(prev.x, prev.y, p.x, p.y);
      }
      prev = p;

      // Frayed filaments near the end
      if (t > 0.86 && random() < 0.35) {
        let dir = p5.Vector.mult(norms[i], random(-1, 1));
        dir.rotate(random(-0.7, 0.7));
        dir.mult(random(6, 24) * (1 - (t - 0.86) / 0.14));
        stroke(210, 220, 235, a * 0.6);
        strokeWeight(w * 0.5);
        line(p.x, p.y, p.x + dir.x, p.y + dir.y);
      }
    }
  }

  // Subtle glow where the thread nears the void
  let gx = x1, gy = y1;
  noStroke();
  for (let i = 0; i < 35; i++) {
    let r = lerp(60, 6, i / 34.0);
    fill(230, 236, 248, 9);
    ellipse(gx, gy, r * 2.2, r * 1.6);
  }
}

function drawGround() {
  // Dark foot of the image with stony texture suggestion
  push();
  noStroke();
  let h0 = height * 0.92;
  for (let y = h0; y < height; y++) {
    let t = map(y, h0, height, 0, 1);
    let c = lerpColor(color(18, 16, 22), color(8, 8, 10), pow(t, 1.6));
    stroke(c);
    line(0, y, width, y);
  }

  // Pebble hints
  for (let i = 0; i < 180; i++) {
    let x = random(width);
    let y = random(height * 0.92, height * 0.99);
    let s = random(8, 28);
    let n = noise(x * 0.01, y * 0.02);
    fill(20 + n * 20, 18 + n * 18, 22 + n * 22, 200);
    ellipse(x, y, s * random(0.8, 1.3), s * random(0.4, 0.8));
    fill(220, 230, 240, 10);
    ellipse(x + s * 0.08, y - s * 0.1, s * 0.4, s * 0.18);
  }
  pop();
}

function vignette() {
  push();
  noStroke();
  let corners = [
    createVector(0, 0),
    createVector(width, 0),
    createVector(0, height),
    createVector(width, height)
  ];
  for (let k = 0; k < corners.length; k++) {
    let v = corners[k];
    for (let i = 0; i < 90; i++) {
      let r = lerp(500, 1500, i / 89.0);
      fill(0, lerp(16, 0, i / 89.0));
      ellipse(v.x, v.y, r, r);
    }
  }
  pop();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();

  // Palette
  let bgTop = color(12, 14, 24);
  let bgBottom = color(2, 2, 5);
  let pathCol = color(245, 246, 250, 235);
  let fogBase = color(190, 200, 210, 18);
  let stoneDark = color(18, 20, 28);
  let stoneMid = color(28, 30, 40);
  let glowIvory = color(245, 240, 226);
  let glowWhite = color(255, 255, 255);

  // Dimensions
  let w = width;
  let h = height;
  let archBaseY = 1320;  // base of the arch
  let archW = 360;
  let archH = 590;

  // 1) Background vertical gradient
  drawVerticalGradient(bgTop, bgBottom);

  // 2) Subtle star field in upper sky
  drawStars(1700, color(230, 235, 245, 30), 0, 820);

  // 3) Vignette to hold composition
  vignette(0.25);

  // 4) Precompute luminous path curve from bottom to arch base
  let pathSamples = computePathSamples(archBaseY);

  // 5) Distant ground haze first layers
  drawFogLayers(archBaseY, h, 8, fogBase, pathSamples);

  // 6) Luminous path
  drawLuminousPath(pathSamples, pathCol);

  // 7) Central arch glow (draw a dark frame first)
  drawArchShape(width/2, archBaseY, archW + 64, archH + 44, color(6, 7, 10, 245));
  drawArchGlow(width/2, archBaseY, archW, archH, glowIvory, glowWhite);

  // 8) Arch halo and motes
  archHalo(width/2, archBaseY, archW, archH);
  drawMotes(width/2, archBaseY, archW, archH);

  // 9) Tombstones on both sides, sorted by depth
  drawTombstones(pathSamples, archBaseY, stoneDark, stoneMid);

  // 10) Foreground fog layers to integrate
  drawFogLayers(archBaseY + 60, h, 6, fogBase, pathSamples);

  // 11) Foreground reeds along path edges
  drawReedsAlongPath(pathSamples);

  // 12) Final soft vignette
  vignette(0.35);
}

// Helpers

function drawVerticalGradient(c1, c2) {
  noFill();
  for (let y = 0; y < height; y++) {
    let t = y / (height - 1);
    stroke(lerpColor(c1, c2, t));
    line(0, y, width, y);
  }
}

function drawStars(count, col, y0, y1) {
  noStroke();
  for (let i = 0; i < count; i++) {
    let x = random(width);
    let y = random(y0, y1);
    let n = noise(x * 0.003, y * 0.003);
    if (n > 0.53) {
      let r = pow(random(), 3) * 2.3 + 0.2;
      fill(red(col), green(col), blue(col), map(n, 0.53, 1, 5, alpha(col)));
      circle(x, y, r);
    }
  }
}

function vignette(strength) {
  // radial darkening toward edges
  push();
  noStroke();
  let cx = width / 2;
  let cy = height / 2 - 100;
  let maxR = dist(0, 0, cx, cy) + dist(width, height, cx, cy);
  for (let i = 0; i < 140; i++) {
    let t = i / 139;
    let a = map(t, 0, 1, 0, 90 * strength);
    fill(5, 6, 10, a);
    let rW = lerp(width * 1.0, width * 2.3, t);
    let rH = lerp(height * 1.0, height * 2.5, t);
    ellipse(cx, cy, rW, rH);
  }
  pop();
}

function computePathSamples(archBaseY) {
  let pts = [];
  let y = height + 20;
  let yStep = -3.5;
  for (; y >= archBaseY; y += yStep) {
    let p = pathCenterAndWidthAtY(y, archBaseY);
    pts.push({ x: p.x, y: y, hw: p.hw });
  }
  return pts;
}

function pathCenterAndWidthAtY(y, archBaseY) {
  // t = 0 at arch base (far), 1 at bottom (near)
  let t = constrain((y - archBaseY) / (height - archBaseY), 0, 1);
  let amp = 34 + 230 * pow(t, 1.25);
  let x = width / 2 + (noise(y * 0.002 + 100) - 0.5) * 2 * amp;
  let hw = 16 + 180 * pow(t, 1.1);
  return { x, hw };
}

function drawLuminousPath(pts, col) {
  push();
  stroke(col);
  strokeCap(ROUND);
  noFill();
  for (let i = 0; i < pts.length - 1; i++) {
    let a = pts[i];
    let b = pts[i + 1];
    let hw = (a.hw + b.hw) * 0.98;
    let t = map(a.y, height, pts[pts.length - 1].y, 0, 1);
    let bright = 200 + 55 * (1 - t);
    stroke(255, 255, 255, constrain(bright, 120, 245));
    strokeWeight(max(2, hw * 2));
    line(a.x, a.y, b.x, b.y);
  }
  // Soft glow overlay
  noStroke();
  for (let i = 0; i < pts.length; i += 2) {
    let p = pts[i];
    let a = map(i, 0, pts.length - 1, 18, 5);
    fill(250, 250, 255, a);
    ellipse(p.x, p.y, p.hw * 3.2, p.hw * 1.2);
  }
  pop();
}

function drawArchShape(cx, baseY, w, h, col) {
  push();
  noStroke();
  fill(col);
  // Top semicircle center
  let topY = baseY - h;
  // Semicircle radius = w/2, center at (cx, topY + w/2)
  arc(cx, topY + w / 2, w, w, PI, 0, CHORD);
  rectMode(CORNERS);
  rect(cx - w / 2, topY + w / 2, cx + w / 2, baseY);
  pop();
}

function drawArchGlow(cx, baseY, w, h, cIvory, cWhite) {
  // inner luminous gradient via nested arch shapes
  let steps = 80;
  for (let i = steps; i >= 0; i--) {
    let t = i / steps; // 1 -> outer, 0 -> inner
    let ww = lerp(w * 0.1, w, t);
    let hh = lerp(h * 0.1, h, t);
    let c = lerpColor(cIvory, cWhite, pow(1 - t, 1.8));
    let a = 12 + 30 * pow(1 - t, 2.2);
    drawArchShape(cx, baseY, ww, hh, color(red(c), green(c), blue(c), a));
  }
  // Bright core slice
  drawArchShape(cx, baseY, w * 0.42, h * 0.92, color(255, 255, 255, 210));
  drawArchShape(cx, baseY, w * 0.30, h * 0.9, color(255, 255, 255, 235));
}

function archHalo(cx, baseY, w, h) {
  push();
  noStroke();
  let ox = cx;
  let oy = baseY - h * 0.55;
  for (let i = 0; i < 36; i++) {
    let t = i / 35;
    let a = 10 - 10 * t;
    fill(250, 248, 240, a);
    ellipse(ox, oy, w * (1.5 + t * 0.9), h * (0.9 + t * 0.9));
  }
  pop();
}

function drawMotes(cx, baseY, w, h) {
  push();
  noStroke();
  let yTop = baseY - h * 0.95;
  let yBottom = baseY - h * 0.15;
  for (let i = 0; i < 1200; i++) {
    let yy = random(yTop, yBottom);
    let t = map(yy, yBottom, yTop, 0, 1);
    let spread = w * (0.3 + 1.2 * pow(t, 1.4));
    let xx = cx + (noise(yy * 0.01, i * 0.01) - 0.5) * 2 * spread;
    let br = 200 + 55 * pow(1 - t, 1.8);
    let r = 0.6 + 2.2 * pow(random(), 2);
    fill(255, 255, 250, br);
    ellipse(xx, yy, r, r);
  }
  pop();
}

function drawTombstones(pathPts, archBaseY, cDark, cMid) {
  // Create stones distributed on both sides, avoid path area and arch interior
  let stones = [];
  let attempts = 1200;
  let target = 220;

  for (let k = 0; k < attempts && stones.length < target; k++) {
    let y = random(archBaseY + 40, height - 20);
    let pw = pathCenterAndWidthAtY(y, archBaseY);
    let side = random() < 0.5 ? -1 : 1;
    let margin = 28 + map(y, archBaseY, height, 0, 40);
    let x;
    if (side < 0) {
      x = random(60, pw.x - pw.hw - margin);
    } else {
      x = random(pw.x + pw.hw + margin, width - 60);
    }
    if (!isFinite(x)) continue;

    // Avoid near-arch central area
    let archBoxW = 0.6 * (width / 2);
    let ax = width / 2;
    if (abs(x - ax) < (0.38 * (pw.hw + 100)) && y < archBaseY + 120) continue;

    // size by depth
    let wS = map(y, archBaseY, height, 12, 54) * random(0.85, 1.35);
    let hS = wS * random(2.0, 4.6);
    let rot = randomGaussian() * 0.05;
    let shade = lerpColor(cDark, cMid, constrain(map(y, archBaseY, height, 0.1, 1.0), 0, 1));
    let n = noise(x * 0.003, y * 0.003);
    let lighten = map(n, 0, 1, -8, 16);
    let col = color(red(shade) + lighten, green(shade) + lighten, blue(shade) + lighten, 240);

    stones.push({ x, y, w: wS, h: hS, r: rot, c: col });
  }

  // Sort by y (far to near)
  stones.sort((a, b) => a.y - b.y);

  // Draw
  for (let s of stones) {
    drawTombstone(s.x, s.y, s.w, s.h, s.r, s.c);
    // Rim light facing the door
    let lightSide = (s.x < width / 2) ? 1 : -1;
    let lx = s.x + lightSide * s.w * 0.36;
    let ly = s.y - s.h * 0.5;
    noStroke();
    fill(240, 240, 250, 18);
    ellipse(lx, ly, s.w * 0.3, s.h * 0.9);
  }
}

function drawTombstone(x, baseY, wS, hS, rot, col) {
  push();
  translate(x, baseY);
  rotate(rot);
  noStroke();
  fill(col);
  let topY = -hS;
  // top semicircle
  arc(0, topY + wS / 2, wS, wS, PI, 0, CHORD);
  // shaft
  rectMode(CORNERS);
  rect(-wS / 2, topY + wS / 2, wS / 2, 0);
  // subtle vertical texture
  stroke(255, 255, 255, 10);
  for (let i = -1; i <= 1; i++) {
    let tx = i * wS * 0.2 + random(-0.5, 0.5);
    line(tx, topY + wS / 2 + 2, tx, -2);
  }
  pop();
}

function drawFogLayers(yStart, yEnd, layers, baseCol, pathPts) {
  push();
  noStroke();
  let rng = random(1000);
  for (let i = 0; i < layers; i++) {
    let t = i / max(1, layers - 1);
    let yb = lerp(yStart, yEnd, t * 0.96 + 0.04);
    let amp = lerp(16, 62, t);
    let alpha = lerp(8, 36, t);
    fill(red(baseCol), green(baseCol), blue(baseCol), alpha);

    beginShape();
    let x0 = -50;
    let x1 = width + 50;
    for (let x = x0; x <= x1; x += 22) {
      let n = noise(x * 0.01 + i * 0.2 + rng, yb * 0.004);
      let yy = yb + (n - 0.5) * 2 * amp;
      vertex(x, yy);
    }
    vertex(x1, yEnd + 80);
    vertex(x0, yEnd + 80);
    endShape(CLOSE);

    // Add brighter mist near the luminous path
    if (pathPts) {
      let seg = pathPts[floor(map(i, 0, layers - 1, 0, pathPts.length - 1))];
      let px = seg ? seg.x : width / 2;
      let py = yb;
      let pw = seg ? seg.hw : 80;
      let g = 18 + 10 * t;
      fill(245, 246, 255, 16 + 12 * (1 - t));
      ellipse(px, py, pw * 3.6, g * 4);
    }
  }
  pop();
}

function drawReedsAlongPath(pts) {
  push();
  stroke(220, 225, 235, 40);
  strokeWeight(1.2);
  for (let i = 0; i < pts.length; i += 20) {
    let p = pts[i];
    let sideDir = random() < 0.5 ? -1 : 1;
    let edgeX = p.x + sideDir * (p.hw + random(8, 26));
    let h = random(18, 70) * map(p.y, pts[0].y, pts[pts.length - 1].y, 1.0, 0.4);
    let bends = 3;
    let x = edgeX, y = p.y;
    let dir = sideDir * 0.8;
    for (let k = 0; k < bends; k++) {
      let nx = x + dir * random(1, 6);
      let ny = y - h / bends;
      line(x, y, nx, ny);
      x = nx; y = ny;
      dir *= 0.6;
    }
  }
  pop();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function draw() {
  drawBackground();
  let cx = width * 0.5;
  let cy = height * 0.41;
  let coreR = 320;
  let horizonY = height * 0.56;

  dustLayer(15000, 0, height * 0.72, color(220, 230, 255, 0.06));
  drawHaze(horizonY);
  drawVoid(cx, cy, coreR);
  ripples(horizonY, cx);

  drawPebbles(7);

  flowInto(cx, cy, coreR, horizonY, 5600);

  vignette(140);
  grain(22000);
}

// Background gradient
function drawBackground() {
  for (let y = 0; y < height; y++) {
    let t = y / (height - 1);
    let r = lerp(12, 3, t);
    let g = lerp(16, 3, t);
    let b = lerp(28, 6, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }
}

// Subtle dust
function dustLayer(n, y0, y1, c) {
  stroke(c);
  strokeWeight(1);
  for (let i = 0; i < n; i++) {
    let x = random(width);
    let y = random(y0, y1);
    point(x, y);
  }
}

// Haze near horizon
function drawHaze(hy) {
  push();
  noFill();
  strokeWeight(1);
  for (let j = 0; j < 120; j++) {
    let a = map(j, 0, 119, 0.05, 0.0);
    stroke(230, 235, 250, a);
    let y = hy - 140 + j * 2;
    beginShape();
    for (let x = -20; x <= width + 20; x += 10) {
      let n = noise(x * 0.003, y * 0.02);
      let yy = y + (n - 0.5) * 26;
      curveVertex(x, yy);
    }
    endShape();
  }
  pop();
}

// Central void with glow
function drawVoid(cx, cy, coreR) {
  push();
  noStroke();
  // Outer waning glow
  blendMode(ADD);
  for (let r = coreR + 24; r < 900; r += 4) {
    let a = map(r, coreR + 24, 900, 0.22, 0.0);
    let wobble = 1.01 + (noise(r * 0.01) - 0.5) * 0.02;
    fill(160, 190, 255, a * 0.16);
    ellipse(cx, cy, r * 2, r * 2 * wobble);
  }
  // Subtle rays
  stroke(200, 215, 255, 0.025);
  strokeWeight(1);
  for (let i = 0; i < 260; i++) {
    let ang = random(TWO_PI);
    let r1 = coreR + 40 + random(120);
    let r2 = r1 + random(90, 280);
    let x1 = cx + cos(ang) * r1;
    let y1 = cy + sin(ang) * r1;
    let x2 = cx + cos(ang + (noise(i * 0.11) - 0.5) * 0.12) * r2;
    let y2 = cy + sin(ang + (noise(i * 0.13) - 0.5) * 0.12) * r2;
    line(x1, y1, x2, y2);
  }
  pop();

  // Black core
  push();
  noStroke();
  fill(0);
  ellipse(cx, cy, coreR * 2, coreR * 2);
  pop();

  // Soft rim
  push();
  noFill();
  stroke(50, 70, 110, 0.22);
  strokeWeight(2.2);
  ellipse(cx, cy, coreR * 2.06, coreR * 2.06);
  pop();
}

// Water-like ripples below horizon
function ripples(hy, cx) {
  push();
  noFill();
  for (let k = 0; k < 64; k++) {
    let a = map(k, 0, 63, 0.16, 0.0);
    stroke(180, 200, 230, a);
    strokeWeight(max(0.15, 1.0 - k * 0.014));
    let amp = 1 + k * 2.8;
    beginShape();
    for (let x = -10; x <= width + 10; x += 6) {
      let base = hy + k * 6.5;
      let n = noise(x * 0.006, k * 0.21);
      let sway = sin((x * 0.01) + (k * 0.45)) * (1.4 + k * 0.12);
      let y = base + sway + (n - 0.5) * amp;
      vertex(x, y);
    }
    endShape();
  }
  pop();
}

// Pebbles / eroded forms near the bottom
function drawPebbles(count) {
  for (let i = 0; i < count; i++) {
    let r = random(60, 180);
    let x = random(120, width - 120);
    let y = random(height * 0.70, height * 0.92);
    let k = random(1000);
    blob(x, y, r, k);
  }
}

function blob(cx, cy, baseR, k) {
  push();
  noStroke();
  fill(26, 27, 31);
  beginShape();
  let steps = 140;
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * TWO_PI;
    let nx = cos(a) * 0.6, ny = sin(a) * 0.6;
    let rr = baseR * (0.82 + noise(nx + k, ny + k) * 0.38);
    let x = cx + cos(a) * rr;
    let y = cy + sin(a) * rr * 0.9;
    vertex(x, y);
  }
  endShape(CLOSE);

  // Erosion highlight
  for (let t = 0; t < 46; t++) {
    let a = map(t, 0, 45, 0.08, 0);
    fill(120, 130, 160, a);
    let w = baseR * 2.2 - t * 12;
    let h = baseR * 1.2 - t * 6;
    if (w > 0 && h > 0) {
      ellipse(cx - baseR * 0.22, cy - baseR * 0.36, w, h);
    }
  }
  pop();
}

// Flow field of traces drawn toward the void
function flowInto(cx, cy, coreR, hy, N) {
  push();
  strokeCap(ROUND);
  for (let i = 0; i < N; i++) {
    let x = random(width);
    let y = random(height);
    // Avoid starting too close to the core
    if (dist(x, y, cx, cy) < coreR * 1.6) { i--; continue; }
    let life = int(random(60, 120));
    for (let s = 0; s < life; s++) {
      let dx = cx - x;
      let dy = cy - y;
      let d = sqrt(dx * dx + dy * dy);
      if (d < coreR * 1.22) break;
      let ang = atan2(dy, dx);
      // Swirl from noise
      let swirl = (noise(x * 0.002, y * 0.002) - 0.5) * PI * 0.8;
      let theta = ang + swirl;
      let step = constrain(map(d, coreR * 1.2, 1400, 0.22, 1.7), 0.16, 1.8);

      let nx = x + cos(theta) * step;
      let ny = y + sin(theta) * step;

      let a = constrain(map(d, coreR * 1.2, 1500, 0.0, 0.24), 0, 0.24);
      stroke(200 + random(-8, 8), 210 + random(-8, 8), 230 + random(-5, 5), a * 0.7);
      let w = constrain(map(d, 220, 1600, 0.22, 0.85), 0.16, 0.9);
      strokeWeight(w);
      line(x, y, nx, ny);

      x = nx; y = ny;
      if (x < -5 || x > width + 5 || y < -5 || y > height + 5) break;
    }
  }
  pop();
}

// Edge darkening
function vignette(margin) {
  push();
  noStroke();
  // Left and right
  for (let k = 0; k < margin; k++) {
    let a = map(k, 0, margin - 1, 0.0, 0.26);
    fill(0, a * 0.9);
    rect(k, 0, 1, height);
    rect(width - 1 - k, 0, 1, height);
  }
  // Top and bottom
  for (let k = 0; k < margin; k++) {
    let a = map(k, 0, margin - 1, 0.0, 0.26);
    fill(0, a * 0.9);
    rect(0, k, width, 1);
    rect(0, height - 1 - k, width, 1);
  }
  pop();
}

// Fine grain overlay
function grain(n) {
  push();
  strokeWeight(1);
  for (let i = 0; i < n; i++) {
    let x = random(width);
    let y = random(height);
    let v = random(8, 28);
    stroke(v, v, v, 20 / 255);
    point(x, y);
  }
  pop();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function draw() {
  let cx = width * 0.5;
  let cy = height * 0.56;
  let R0 = 240;

  drawBackground();
  drawVignette(width/2, height*0.55);

  // Early faint glow and atmosphere
  drawHalo(cx, cy, R0);

  // Flowing filaments bending toward the void
  drawFlows(cx, cy, R0);

  // Distant dust
  drawDust(cx, cy, R0);

  // Absolute center: the silent void (mask everything beneath)
  noStroke();
  fill(0);
  ellipse(cx, cy, R0 * 2, R0 * 2);

  // Subtle inner rim glints
  drawInnerRim(cx, cy, R0);
}

// ---------- Background and Vignette ----------
function drawBackground() {
  let c0 = color(9, 12, 18);
  let c1 = color(15, 18, 24);
  let c2 = color(26, 20, 20);

  for (let y = 0; y < height; y++) {
    let t = y / height;
    let col;
    if (t < 0.55) {
      col = lerpColor(c0, c1, t / 0.55);
    } else {
      col = lerpColor(c1, c2, (t - 0.55) / 0.45);
    }
    stroke(col);
    line(0, y, width, y);
  }

  // Soft central lift to avoid flatness
  noStroke();
  let lift = color(40, 42, 48, 12);
  fill(lift);
  ellipse(width * 0.5, height * 0.6, width * 0.8, height * 0.7);
}

function drawVignette(cx, cy) {
  push();
  noStroke();
  // Radial darkening at edges using large translucent ellipses
  let maxR = max(width, height) * 1.7;
  for (let i = 0; i < 200; i++) {
    let r = map(i, 0, 199, max(width, height) * 0.9, maxR);
    let a = map(i, 0, 199, 0, 60);
    fill(0, a);
    ellipse(cx, cy, r * 1.1, r);
  }
  pop();
}

// ---------- Halo and Dust ----------
function drawHalo(cx, cy, R0) {
  push();
  // Irregular luminous ring diminishing outward
  for (let i = 0; i < 20000; i++) {
    let a = random(TAU);
    let rr = R0 + pow(random(), 2.0) * 520; // more near the core rim
    let x = cx + cos(a) * rr;
    let y = cy + sin(a) * rr;

    // Tangential jitter by noise for breathing edges
    let n = noise(x * 0.003, y * 0.003);
    let off = (n - 0.5) * 28 * constrain((rr - R0) / 520, 0, 1);
    x += cos(a + HALF_PI) * off;
    y += sin(a + HALF_PI) * off;

    let t = constrain((rr - (R0 + 30)) / 500, 0, 1);
    let r = lerp(235, 160, t);
    let g = lerp(236, 190, t);
    let b = lerp(232, 210, t);
    let alpha = lerp(18, 10, t);
    stroke(r, g, b, alpha);
    strokeWeight(random(0.3, 1.2));
    point(x, y);
  }
  pop();
}

function drawDust(cx, cy, R0) {
  push();
  for (let i = 0; i < 3200; i++) {
    let x = random(width);
    let y = random(height);
    let d = dist(x, y, cx, cy);
    if (d < R0 + 180) continue;

    let ed = constrain((d - (R0 + 180)) / (max(width, height) * 0.9), 0, 1);
    let a = 60 * pow(ed, 1.5) * random(0.6, 1.0);
    if (a < 4) continue;
    stroke(230, 232, 236, a);
    strokeWeight(random(0.3, 0.9));
    point(x, y);
  }
  pop();
}

// ---------- Flow Field ----------
function fieldVec(x, y, cx, cy) {
  let dx = x - cx;
  let dy = y - cy;
  let d = sqrt(dx * dx + dy * dy) + 1e-6;

  // Base noisy direction
  let a = noise(x * 0.0015, y * 0.0015) * TAU * 2.0;
  let vx = cos(a);
  let vy = sin(a);

  // Tangential swirl around the center
  let sx = -dy / d;
  let sy = dx / d;
  let swirlMag = 1.2 / (1 + d * 0.004);

  // Radial pull inward
  let rx = -dx / d;
  let ry = -dy / d;
  let radialMag = 1.4 / (1 + d * 0.003);

  vx = vx * 0.4 + sx * swirlMag + rx * radialMag;
  vy = vy * 0.4 + sy * swirlMag + ry * radialMag;

  // Small curl variation
  let n1 = noise(x * 0.006, y * 0.006);
  let th2 = n1 * TAU * 1.5;
  vx += cos(th2) * 0.2;
  vy += sin(th2) * 0.2;

  return createVector(vx, vy);
}

function drawFlows(cx, cy, R0) {
  push();
  strokeCap(ROUND);

  function drawOne(x, y, maxSteps, baseAlpha) {
    let px = x;
    let py = y;
    for (let k = 0; k < maxSteps; k++) {
      let d = dist(x, y, cx, cy);
      if (d < R0 + 8) break;
      if (x < -60 || x > width + 60 || y < -60 || y > height + 60) break;

      let v = fieldVec(x, y, cx, cy);

      // Near the void, favor tangential bending
      if (d < R0 + 200) {
        let fac = (R0 + 200 - d) / 200;
        let tx = -(y - cy) / max(d, 1e-6);
        let ty = (x - cx) / max(d, 1e-6);
        v.x = v.x * (1 - fac * 0.7) + tx * (0.6 + 1.2 * fac);
        v.y = v.y * (1 - fac * 0.7) + ty * (0.6 + 1.2 * fac);
      }

      let stepLen = 1.2 + 1.8 * (1 - exp(-d / 400));
      let nx = x + v.x * stepLen;
      let ny = y + v.y * stepLen;

      let tCl = constrain((d - R0) / (max(width, height) * 0.6), 0, 1);
      let rr = lerp(215, 140, tCl * 0.7);
      let gg = lerp(224, 170, tCl * 0.7);
      let bb = lerp(235, 190, tCl * 0.7);
      let alpha = (8 + 24 * tCl) * baseAlpha;

      stroke(rr, gg, bb, alpha);
      strokeWeight(0.6 + 0.35 * (1 - tCl));
      line(px, py, nx, ny);

      px = nx;
      py = ny;
      x = nx;
      y = ny;
    }
  }

  // Seeds from edges
  for (let i = 0; i < 450; i++) {
    let y = map(i, 0, 449, height * 0.05, height * 0.95) + random(-10, 10);
    drawOne(20 + random(0, 10), y, 230 + int(random(40)), 1.0);
  }
  for (let i = 0; i < 450; i++) {
    let y = map(i, 0, 449, height * 0.05, height * 0.95) + random(-10, 10);
    drawOne(width - 20 - random(0, 10), y, 230 + int(random(40)), 1.0);
  }
  for (let i = 0; i < 700; i++) {
    let x = map(i, 0, 699, 40, width - 40) + random(-15, 15);
    drawOne(x, height - 25, 250 + int(random(60)), 1.0);
  }
  for (let i = 0; i < 300; i++) {
    let x = random(20, width - 20);
    drawOne(x, 25, 180 + int(random(50)), 0.9);
  }

  // Seeds near the void, bending around it
  for (let i = 0; i < 320; i++) {
    let a = random(TAU);
    let r = R0 + random(70, 300);
    let x = cx + cos(a) * r + random(-3, 3);
    let y = cy + sin(a) * r + random(-3, 3);
    drawOne(x, y, 140 + int(random(100)), 0.85);
  }

  pop();
}

// ---------- Inner Rim ----------
function drawInnerRim(cx, cy, R0) {
  push();
  // Speckled glints just outside the void to suggest a boundary
  for (let i = 0; i < 9000; i++) {
    let a = random(TAU);
    let rr = R0 + random(2, 52);
    let x = cx + cos(a) * rr;
    let y = cy + sin(a) * rr;
    let n = noise(x * 0.01, y * 0.01);
    let br = lerp(200, 240, n);
    let al = lerp(12, 36, 1 - rr / (R0 + 52));
    stroke(br, br + 5, br + 10, al);
    strokeWeight(random(0.3, 0.8));
    point(x, y);
  }
  pop();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);

  createCanvas(1600, 2000);
  pixelDensity(1);
  colorMode(HSB, 360, 100, 100, 1);
  noLoop();
}

function draw() {
  // Base parameters
  const cx = width * 0.5;
  const cy = height * 0.62;
  const coreR = 420;

  backgroundGradient();
  subtleDust(5200, 0.05);

  // Outer halo that hints at memory and echo
  drawHalo(cx, cy, coreR, 240);

  // Soft deepening toward the lower abyss
  deepenLower(cy, 0.0, 0.6);

  // Threads of lives/moments drawn toward the center
  flowInto(cx, cy, coreR);

  // The silent door (void)
  drawCore(cx, cy, coreR);

  // A breath-thin rim of light around the edge
  innerRim(cx, cy, coreR);
}

// --------- Painting blocks ---------

function backgroundGradient() {
  // Top to bottom: faint cool light to near-black
  const cTop = color(210, 8, 98, 1);
  const cBot = color(230, 30, 4, 1);
  for (let y = 0; y < height; y++) {
    const t = y / (height - 1);
    const c = lerpColor(cTop, cBot, pow(t, 1.25));
    stroke(c);
    line(0, y, width, y);
  }

  // Gentle side vignettes
  noStroke();
  for (let i = 0; i < 180; i++) {
    const a = map(i, 0, 179, 0.0, 0.08);
    fill(230, 40, 0, a);
    const w = width * map(i, 0, 179, 1.8, 1.02);
    const h = height * map(i, 0, 179, 1.8, 1.02);
    ellipse(width * 0.5, height * 0.48, w, h);
  }
}

function subtleDust(count, alpha) {
  stroke(0, 0, 100, alpha);
  strokeWeight(1);
  for (let i = 0; i < count; i++) {
    const x = random(-50, width + 50);
    const y = random(-50, height * 0.75);
    point(x, y);
  }

  // Sparse darker motes lower down
  stroke(230, 15, 20, alpha * 0.8);
  for (let i = 0; i < count * 0.35; i++) {
    const x = random(-50, width + 50);
    const y = random(height * 0.55, height + 50);
    point(x, y);
  }
}

function drawHalo(cx, cy, r, thickness) {
  noFill();
  strokeCap(ROUND);
  const layers = thickness;
  for (let i = 0; i < layers; i++) {
    const t = i / (layers - 1);
    const rr = r + 12 + i;
    // A cool spectral edge fading outward
    const hue = lerp(215, 265, t);
    const sat = lerp(18, 8, t);
    const bri = lerp(80, 40, t);
    const a = pow(1 - t, 1.8) * 0.18 + 0.005;
    stroke(hue, sat, bri, a);
    strokeWeight(1 + (1 - t) * 1.2);
    ellipse(cx, cy, rr * 2, rr * 2);
  }
}

function deepenLower(cy, topAlpha, bottomAlpha) {
  // Vertical darkening from just above center to bottom, to suggest fertile unknown
  const startY = int(cy + 90);
  const endY = height;
  noStroke();
  for (let y = startY; y < endY; y++) {
    const t = (y - startY) / (endY - startY);
    const a = lerp(topAlpha, bottomAlpha, pow(t, 1.6));
    fill(230, 40, 0, a);
    rect(0, y, width, 1);
  }
}

function flowInto(cx, cy, r) {
  // Field-driven threads moving toward the core
  const particles = [];
  const Ntop = 900;
  const Nside = 260;
  const noiseScale = 0.0019;

  // Top sources
  for (let i = 0; i < Ntop; i++) {
    particles.push({
      x: random(0, width),
      y: constrain(randomGaussian(height * 0.22, height * 0.12), 40, height * 0.5),
      hue: 210 + random(-6, 6),
      sat: 6 + random(0, 10),
      bri: 96 + random(-6, 3),
      w: random(0.5, 1.2),
      a: random(0.06, 0.16)
    });
  }
  // Side sources (left and right), feeding inward
  for (let i = 0; i < Nside; i++) {
    const side = i < Nside / 2 ? -1 : 1;
    particles.push({
      x: side < 0 ? -20 : width + 20,
      y: random(height * 0.18, height * 0.62),
      hue: 210 + random(-8, 8),
      sat: 8 + random(0, 12),
      bri: 92 + random(-8, 2),
      w: random(0.6, 1.4),
      a: random(0.06, 0.14)
    });
  }

  strokeCap(ROUND);

  for (let p of particles) {
    let x = p.x;
    let y = p.y;

    const maxSteps = 360 + int(random(-40, 80));
    const baseStep = random(1.4, 2.4);
    let drawn = false;

    beginShape();
    for (let s = 0; s < maxSteps; s++) {
      const dx = cx - x;
      const dy = cy - y;
      const d = sqrt(dx * dx + dy * dy);

      // Stop if reached the edge of the void or too far out
      if (d < r + 6 || x < -80 || x > width + 80 || y < -80 || y > height + 80) break;

      // Direction from noise
      const ang = noise(x * noiseScale, y * noiseScale) * TWO_PI * 3.5;
      const vNoise = p5.Vector.fromAngle(ang);

      // Direction to center
      const vTo = createVector(dx, dy);
      vTo.normalize();

      // Blend factor: stronger attraction nearer the core
      const tAttr = constrain(map(d, width * 0.75, r * 1.35, 0.12, 0.86), 0.12, 0.86);

      // Slight spiral bias near the edge of the void
      const swirlAmt = constrain(map(d, r * 3.2, r * 1.1, 0.0, 0.35), 0.0, 0.35);
      const vSwirl = createVector(-vTo.y, vTo.x).mult(swirlAmt);

      // Combined direction
      let dir = p5.Vector.lerp(vNoise, vTo.copy().add(vSwirl).normalize(), tAttr);
      dir.normalize();

      // Step damped as it nears the core
      const step = baseStep * (0.65 + 0.35 * (d / (r * 3.0)));
      x += dir.x * step;
      y += dir.y * step;

      // Stroke style varies with proximity; brighter near the edge of the void
      const edgeT = constrain(map(d, r * 1.8, r * 1.02, 0, 1), 0, 1);
      stroke(p.hue, p.sat + 6 * edgeT, p.bri + 6 * edgeT, p.a * (0.55 + 0.45 * edgeT));
      strokeWeight(p.w * (0.8 + 0.6 * (1 - edgeT)));

      vertex(x, y);
      drawn = true;
    }
    endShape();

    // Occasional echo thread with dimmer stroke
    if (drawn && random() < 0.08) {
      stroke(p.hue, p.sat, p.bri - 10, p.a * 0.6);
      strokeWeight(p.w * 0.7);
      noFill();
      beginShape();
      let xx = p.x + random(-8, 8);
      let yy = p.y + random(-8, 8);
      for (let s = 0; s < 120; s++) {
        const dx = cx - xx;
        const dy = cy - yy;
        const d = sqrt(dx * dx + dy * dy);
        if (d < r + 10) break;
        const ang = noise(xx * noiseScale, yy * noiseScale) * TWO_PI * 3.5 + 0.2;
        let dir = p5.Vector.fromAngle(ang);
        dir = p5.Vector.lerp(dir, createVector(dx, dy).normalize(), 0.7);
        dir.normalize();
        const step = 1.2 * (0.65 + 0.35 * (d / (r * 3.0)));
        xx += dir.x * step;
        yy += dir.y * step;
        vertex(xx, yy);
      }
      endShape();
    }
  }
}

function drawCore(cx, cy, r) {
  noStroke();
  fill(230, 40, 0, 1); // pure black in HSB space
  ellipse(cx, cy, r * 2, r * 2);
}

function innerRim(cx, cy, r) {
  noFill();
  for (let i = 0; i < 14; i++) {
    const t = i / 13;
    const a = lerp(0.08, 0.0, t);
    stroke(210, 8, 100, a);
    strokeWeight(1.2 - t * 0.8);
    ellipse(cx, cy, (r * 2) + i * 1.4, (r * 2) + i * 1.4);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  colorMode(RGB, 255, 255, 255, 255);
  noLoop();
}

function draw() {
  background(0);
  drawVerticalAbyss();
  drawLowFog();
  drawRoots();
  drawPillar();
  drawAscentParticles();
  drawTopDust();
  vignette();
}

function drawVerticalAbyss() {
  // Deep vertical gradient: from near-black to warm earth
  let topC = color(6, 8, 12);
  let botC = color(34, 18, 12);
  noStroke();
  for (let y = 0; y < height; y++) {
    let t = y / (height - 1);
    let c = lerpColor(topC, botC, t);
    fill(c);
    rect(0, y, width, 1);
  }
}

function drawLowFog() {
  // Horizontal veils of faint fog
  noStroke();
  for (let y = 0; y < height; y += 2) {
    let n = noise(0.003 * y, 0.31);
    let a = map(n, 0, 1, 0, 26);
    fill(220, 224, 230, a);
    rect(0, y, width, 2);
  }

  // Layered drifting mist bands
  for (let i = 0; i < 5; i++) {
    let y0 = map(i, 0, 4, height * 0.15, height * 0.85);
    let h = random(160, 320);
    let aBase = random(8, 18);
    for (let y = y0 - h / 2; y <= y0 + h / 2; y++) {
      let t = (y - (y0 - h / 2)) / h;
      let fall = 1 - abs(2 * t - 1);
      let nx = noise(0.0015 * y, i * 1.37) * 0.4;
      fill(230, 232, 236, aBase * pow(fall, 2) + nx * 10);
      rect(0, y, width, 1);
    }
  }
}

function drawPillar() {
  // Soft pale vertical "threshold" made of translucent rectangles and filaments
  rectMode(CENTER);
  noStroke();
  for (let k = 0; k < 90; k++) {
    let t = k / 89;
    let w = lerp(520, 110, t) + (noise(10 + k * 0.08) - 0.5) * 60;
    let a = 10 * (1 - t) + 3;
    fill(236, 236, 228, a);
    let h = height * lerp(0.82, 0.94, 1 - t);
    let r = 80;
    rect(width / 2 + (noise(20 + k * 0.05) - 0.5) * 18, height * 0.52, w, h, r);
  }

  // Filament beziers to texture the threshold
  noFill();
  for (let i = 0; i < 850; i++) {
    let ti = i / 849;
    let w = lerp(320, 90, ti);
    let x0 = width / 2 - w * 0.5 + (noise(100 + i * 0.01) - 0.5) * w * 0.3;
    let x3 = width / 2 + w * 0.5 + (noise(200 + i * 0.01) - 0.5) * w * 0.3;
    let y0 = height * 0.96 + (noise(300 + i * 0.015) - 0.5) * 40;
    let y3 = height * 0.08 + (noise(400 + i * 0.015) - 0.5) * 40;
    let cx1 = width / 2 - w * 0.7 + (noise(500 + i * 0.02) - 0.5) * w * 0.9;
    let cy1 = height * 0.68 + (noise(600 + i * 0.02) - 0.5) * 120;
    let cx2 = width / 2 + w * 0.7 + (noise(700 + i * 0.02) - 0.5) * w * 0.9;
    let cy2 = height * 0.34 + (noise(800 + i * 0.02) - 0.5) * 120;
    stroke(238, 236, 228, 7 + noise(i * 0.017) * 8);
    strokeWeight(0.7 + noise(i * 0.03) * 1.8);
    bezier(x0, y0, cx1, cy1, cx2, cy2, x3, y3);
  }
}

function drawRoots() {
  // Tangled lines at the bottom (the residue of forms)
  let walkers = 380;
  let sc = 0.0022;
  for (let s = 0; s < walkers; s++) {
    let x = constrain(randomGaussian(width * 0.5, width * 0.42), 0, width);
    let y = random(height * 0.70, height * 0.97);
    let len = floor(random(80, 180));
    let thick = random(0.6, 1.5);
    let warm = color(168, 112, 78, 22);
    let dark = color(50, 26, 20, 30);
    let gld = color(184, 150, 80, 26);
    let huePick = random();
    strokeWeight(thick);
    beginShape();
    for (let i = 0; i < len; i++) {
      let a = noise(x * sc, y * sc) * TAU * 4.0;
      let step = 2.2 + noise(1000 + x * sc, 1000 + y * sc) * 2.0;
      x += cos(a) * step * 0.9 + (noise(2000 + x * sc) - 0.5) * 0.6;
      y += sin(a) * step * 0.6 + (noise(3000 + y * sc) - 0.5) * 0.6;
      if (y < height * 0.58) break;
      let t = i / len;
      let c1 = lerpColor(dark, warm, smoothstep(0, 1, t));
      let c2 = lerpColor(c1, gld, pow(t, 3) * 0.6);
      stroke(red(c2), green(c2), blue(c2), alpha(c2));
      vertex(x, y);
    }
    endShape();
  }

  // Occasional brighter "kintsugi" filaments
  noFill();
  for (let k = 0; k < 30; k++) {
    let x0 = random(0, width);
    let y0 = random(height * 0.8, height * 0.98);
    let x3 = x0 + random(-300, 300);
    let y3 = y0 - random(180, 420);
    let cx1 = lerp(x0, x3, 0.3) + (noise(k * 0.2) - 0.5) * 200;
    let cy1 = lerp(y0, y3, 0.2) + (noise(10 + k * 0.2) - 0.5) * 160;
    let cx2 = lerp(x0, x3, 0.7) + (noise(20 + k * 0.2) - 0.5) * 200;
    let cy2 = lerp(y0, y3, 0.8) + (noise(30 + k * 0.2) - 0.5) * 160;
    stroke(205, 176, 106, 26);
    strokeWeight(0.9);
    bezier(x0, y0, cx1, cy1, cx2, cy2, x3, y3);
  }
}

function drawAscentParticles() {
  // Particles rising, thinning into the dark via curl-noise flow
  let count = 2700;
  let fieldScale = 0.0016;
  for (let i = 0; i < count; i++) {
    let x = constrain(randomGaussian(width * 0.5, width * 0.42), -50, width + 50);
    let y = random(height * 0.58, height * 0.98);
    let steps = floor(random(80, 180));
    let baseSize = random(0.7, 2.6);
    let drift = random(-0.3, 0.3);
    for (let s = 0; s < steps; s++) {
      let nx = x * fieldScale, ny = y * fieldScale;
      let v = curl2D(nx, ny);
      let mag = 1.9 + noise(4000 + nx, 4000 + ny) * 1.2;
      x += v.x * mag + drift * 0.2;
      y += v.y * mag - 0.7; // upward bias
      if (x < -80 || x > width + 80 || y < -80) break;
      let t = s / steps;
      let fadeTop = constrain(map(y, height * 0.2, height * 0.0, 1, 0), 0, 1);
      let alphaP = 26 * (1 - pow(t, 1.6)) * (0.3 + 0.7 * fadeTop);
      let colA = color(216, 199, 176, alphaP);
      let colB = color(70, 66, 64, alphaP * 0.8);
      let c = lerpColor(colA, colB, pow(t, 1.2));
      noStroke();
      fill(red(c), green(c), blue(c), alpha(c));
      let r = baseSize * lerp(1.2, 0.4, t);
      ellipse(x, y, r, r);
    }
  }
}

function drawTopDust() {
  // Sparse dust in upper half
  noStroke();
  for (let i = 0; i < 900; i++) {
    let x = random(0, width);
    let y = random(0, height * 0.55);
    let a = random(2, 12) * (1 - smoothstep(0, height * 0.55, y));
    fill(230, 232, 240, a);
    let r = random(0.4, 1.4);
    ellipse(x, y, r, r);
  }
}

function vignette() {
  // Darken edges softly
  noFill();
  for (let k = 0; k < 58; k++) {
    let t = k / 57;
    stroke(0, 0, 0, 10);
    strokeWeight(34);
    let inset = t * 340;
    rect(inset - 40, inset - 40, width - 2 * inset + 80, height - 2 * inset + 80, 90);
  }
  // Subtle grounding shadow at bottom
  noStroke();
  for (let y = height * 0.85; y < height; y++) {
    let t = (y - height * 0.85) / (height * 0.15);
    let a = 60 * pow(t, 1.2);
    fill(0, 0, 0, a);
    rect(0, y, width, 1);
  }
}

// Utility: smoothstep
function smoothstep(edge0, edge1, x) {
  let t = constrain((x - edge0) / (edge1 - edge0), 0, 1);
  return t * t * (3 - 2 * t);
}

// 2D curl of noise field
function curl2D(x, y) {
  let e = 0.0008;
  let n1 = noise(x + e, y);
  let n2 = noise(x - e, y);
  let n3 = noise(x, y + e);
  let n4 = noise(x, y - e);
  let dx = (n1 - n2) / (2 * e);
  let dy = (n3 - n4) / (2 * e);
  // Rotate gradient 90 degrees to get a swirl-like flow
  return createVector(dy, -dx);
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  background(0);
  drawBackgroundGradient();
  drawDistantStars();
  let portal = drawPortal(width/2, height*0.45, 380, 600);
  drawMist(980, 1320);
  drawFlowField(portal);
  vignette();
  grain(180000);
}

// Background: deep to dim gradient
function drawBackgroundGradient() {
  for (let y = 0; y < height; y++) {
    let t = y / (height - 1);
    let r = lerp(8, 28, t);
    let g = lerp(10, 26, t);
    let b = lerp(16, 34, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }
}

// Subtle stars/motes in the upper region
function drawDistantStars() {
  push();
  noStroke();
  for (let i = 0; i < 1100; i++) {
    let x = random(width);
    let y = random(height * 0.08, height * 0.35);
    let a = random(10, 28);
    fill(235, 238, 245, a);
    let s = random() < 0.1 ? random(1.2, 1.8) : random(0.5, 1.1);
    ellipse(x, y + noise(x * 0.01) * 0.6, s, s);
  }
  pop();
}

// Portal with soft halo
function drawPortal(cx, cy, w, h) {
  push();
  noStroke();

  // Outer soft halo
  for (let i = 36; i >= 1; i--) {
    let t = i / 36;
    let a = 6 + (1 - t) * 12; // outer lighter alpha
    fill(228, 232, 240, a);
    let ew = w * (1 + t * 1.05);
    let eh = h * (1 + t * 1.05);
    ellipse(cx, cy, ew, eh);
  }

  // Subtle inner glow ring
  for (let i = 0; i < 12; i++) {
    let t = i / 11.0;
    let e = easeInOutQuad(t);
    let a = map(i, 0, 11, 12, 2);
    fill(240, 242, 248, a);
    ellipse(cx, cy, w * (1.1 + e * 0.12), h * (1.1 + e * 0.12));
  }

  // Core darkness
  fill(5, 6, 8);
  ellipse(cx, cy, w, h);

  // Deep core
  fill(2, 2, 4);
  ellipse(cx, cy, w * 0.86, h * 0.86);
  pop();

  return { x: cx, y: cy, w: w, h: h };
}

// Horizontal mist band as a threshold
function drawMist(yStart, yEnd) {
  push();
  for (let y = yStart; y < yEnd; y += 2) {
    let nrow = noise(100 + y * 0.01);
    let drift = map(nrow, 0, 1, -1.5, 1.5);
    for (let x = -50; x < width + 50; x += 6) {
      let n = noise(x * 0.004, y * 0.016);
      if (n > 0.44) {
        let a = map(n, 0.44, 1, 0, 26, true);
        stroke(233, 236, 242, a);
        let jitterX = (noise(x * 0.05, y * 0.05) - 0.5) * 2.0;
        line(x + jitterX, y + drift, x + 5 + jitterX, y + drift + (noise(x * 0.02) - 0.5) * 1.2);
      }
    }
  }
  pop();
}

// Flow field of lines dissolving into the portal
function drawFlowField(portal) {
  let cx = portal.x, cy = portal.y, pw = portal.w, ph = portal.h;
  let rBreak = pw * 0.8;
  let seeds = [];

  // Bottom seeds
  for (let i = 0; i < 900; i++) {
    seeds.push({ x: random(-40, width + 40), y: random(1680, 1980), steps: 400, a: 38 });
  }

  // Side seeds
  for (let i = 0; i < 380; i++) {
    seeds.push({ x: random(-20, 40), y: random(120, height - 80), steps: 360, a: 32 });
    seeds.push({ x: random(width - 40, width + 20), y: random(120, height - 80), steps: 360, a: 32 });
  }

  // Mid seeds (noise islands)
  for (let i = 0; i < 220; i++) {
    let y = random(1050, 1500);
    let x = random(0, width);
    if (noise(x * 0.002, y * 0.002) > 0.48) {
      seeds.push({ x: x, y: y, steps: 320, a: 28 });
    }
  }

  push();
  for (let s of seeds) {
    drawStream(s.x, s.y, s.steps, s.a, cx, cy, rBreak, pw, ph);
  }
  pop();
}

function drawStream(x0, y0, maxSteps, baseAlpha, cx, cy, rBreak, pw, ph) {
  let pos = createVector(x0 + random(-2, 2), y0 + random(-2, 2));
  let prev = pos.copy();
  let inBreak = false;
  let broken = 0;
  let maxBreak = 22 + floor(random(10));

  for (let i = 0; i < maxSteps; i++) {
    // bounds
    if (pos.x < -80 || pos.x > width + 80 || pos.y < -80 || pos.y > height + 80) break;

    let d = dist(pos.x, pos.y, cx, cy);
    let dir = fieldDir(pos.x, pos.y, cx, cy);

    // step length varies with distance
    let stepLen = map(d, 140, 1400, 1.1, 3.1, true);
    // slight turbulence
    let j = (noise(pos.x * 0.02, pos.y * 0.02) - 0.5) * 0.35;
    dir.rotate(j * 0.7);
    let next = p5.Vector.add(pos, p5.Vector.mult(dir, stepLen));

    // stroke styling
    let fade = map(d, 1200, 260, baseAlpha, baseAlpha * 0.08, true);
    let cool = 220 + (noise(i * 0.01) * 20);
    stroke(cool, cool + 6, cool + 14, fade);
    let sw = map(y0, 1650, 1980, 1.2, 0.5, true);
    sw *= map(d, 200, 1400, 0.5, 1.1, true);
    strokeWeight(sw);

    if (!inBreak) {
      line(pos.x, pos.y, next.x, next.y);
      // Enter break-up near the portal boundary
      if (d < rBreak) {
        inBreak = true;
      }
    } else {
      // Dissolution: grains drifting with slight radial pull
      let toC = createVector(cx - pos.x, cy - pos.y);
      let dn = toC.mag();
      toC.normalize();
      let pull = map(dn, 40, rBreak, 0.9, 0.1, true);
      let tangent = createVector(-toC.y, toC.x);
      let drift = p5.Vector.add(p5.Vector.mult(toC, pull * 0.6), p5.Vector.mult(tangent, 0.15));
      next = p5.Vector.add(pos, p5.Vector.mult(drift, stepLen * 0.95));

      noStroke();
      let a = map(dn, 40, rBreak, 42, 12, true);
      fill(235, 238, 246, a);
      let sz = map(dn, 40, rBreak, 0.6, 2.2, true);
      ellipse(pos.x + random(-0.6, 0.6), pos.y + random(-0.6, 0.6), sz, sz);
      broken++;
      if (broken > maxBreak || dn < pw * 0.5) {
        // fade into the core darkness
        if (dn < pw * 0.5) {
          fill(5, 6, 8, 40);
          ellipse(pos.x, pos.y, 2, 2);
        }
        break;
      }
    }

    prev.set(pos);
    pos.set(next);
  }
}

// Flow field direction combining noise, attraction, and gentle swirl
function fieldDir(x, y, cx, cy) {
  let a = noise(x * 0.00125, y * 0.00115) * TAU * 1.8 - PI;
  let v = p5.Vector.fromAngle(a);

  let toC = createVector(cx - x, cy - y);
  let d = toC.mag();
  toC.normalize();
  let tangent = createVector(-toC.y, toC.x);

  let m = constrain(map(d, 120, 1100, 0.92, 0.25), 0.25, 0.92);
  let res = p5.Vector.mult(v, 1 - m)
    .add(p5.Vector.mult(toC, m * 1.12))
    .add(p5.Vector.mult(tangent, 0.06 * (1 - m)));
  res.normalize();
  return res;
}

// Soft vignette
function vignette() {
  push();
  noStroke();
  let cx = width * 0.5, cy = height * 0.6;
  for (let i = 0; i < 42; i++) {
    let t = i / 41;
    let a = map(t, 0, 1, 0, 85);
    fill(0, 0, 0, a * 0.06);
    let ew = width * (1 + t * 1.7);
    let eh = height * (1 + t * 1.3);
    ellipse(cx, cy, ew, eh);
  }
  pop();
}

// Grain overlay
function grain(count) {
  push();
  strokeWeight(1);
  blendMode(SOFT_LIGHT);
  for (let i = 0; i < count; i++) {
    let x = random(width);
    let y = random(height);
    let v = 200 + random(-25, 25);
    stroke(v, v, v, random(12, 24));
    point(x, y);
  }
  pop();
}

function easeInOutQuad(t) {
  return t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();
  noStroke();
}

function draw() {
  backgroundGradient();
  paintAtmosphere();

  // Auras
  let leftC = createVector(width * 0.39, height * 0.52);
  let rightC = createVector(width * 0.61, height * 0.52);

  softBlob(leftC.x, leftC.y, 460, {h: 338, s: 45, b: 60}, {h: 348, s: 60, b: 85}, 130);
  softBlob(rightC.x, rightC.y, 460, {h: 18, s: 50, b: 60}, {h: 28, s: 70, b: 85}, 130);

  // Petal-forms (two presences)
  drawPresence(leftC.x, leftC.y, 0, 1, 42, [330, 355], [55, 75], [65, 95]);
  drawPresence(rightC.x, rightC.y, PI, -1, 42, [10, 35], [55, 75], [65, 95]);

  // Threads between
  connectiveThreads(leftC, rightC, 230);

  // Shared glow
  sharedFlame(createVector(width * 0.5, height * 0.52));

  // Ground/foundation
  foundation();

  // Subtle sparkles
  sparkles(createVector(width * 0.5, height * 0.52), 420, 240);
}

function backgroundGradient() {
  // Plum to deep blue vertical gradient
  let topCol = color(300, 35, 16);
  let botCol = color(220, 50, 10);
  for (let y = 0; y < height; y++) {
    let t = y / (height - 1);
    let c = lerpColor(topCol, botCol, t);
    stroke(c);
    line(0, y, width, y);
  }
  noStroke();

  // Large faint corner vignettes
  push();
  blendMode(MULTIPLY);
  for (let i = 0; i < 4; i++) {
    let cx = (i % 2 === 0) ? -200 : width + 200;
    let cy = (i < 2) ? -200 : height + 200;
    let base = color(230, 40, 10, 40);
    for (let r = 1000; r > 100; r -= 80) {
      let a = map(r, 100, 1000, 0, 18);
      fill(hue(base), saturation(base), brightness(base), a);
      ellipse(cx, cy, r * 2, r * 2);
    }
  }
  pop();
}

function paintAtmosphere() {
  // Subtle noise wisps to break uniformity
  push();
  let layers = 70;
  for (let i = 0; i < layers; i++) {
    let t = i / (layers - 1);
    let y = lerp(-200, height + 200, t);
    let col = color(230, 25, lerp(22, 10, t), 6);
    fill(col);
    let xoff = noise(t * 1.8) * 200 - 100;
    rect(-100 + xoff, y, width + 200, 16 + noise(t * 2.3) * 40);
  }
  pop();
}

function softBlob(cx, cy, r, c1, c2, layers) {
  push();
  for (let i = 0; i < layers; i++) {
    let t = i / (layers - 1);
    let h = lerpHue(c1.h, c2.h, smoothstep(0, 1, t));
    let s = lerp(c1.s, c2.s, t);
    let b = lerp(c1.b, c2.b, t);
    let a = 10 + 18 * (1 - t);
    fill(h, s, b, a);
    let rad = lerp(r * 1.1, r * 0.25, t) + random(-r * 0.03, r * 0.03);
    let ang = random(TWO_PI);
    let d = (r * 0.06) * t;
    let ox = cos(ang) * d;
    let oy = sin(ang) * d;
    ellipse(cx + ox, cy + oy, rad * 2, rad * 2);
  }
  pop();
}

function drawPresence(cx, cy, meanAngle, side, count, hueRange, satRange, briRange) {
  push();
  for (let i = 0; i < count; i++) {
    let a = randomGaussian(meanAngle, 0.55 + 0.25 * (i / count));
    let len = random(260, 520) * (0.8 + 0.4 * noise(i * 0.2));
    let w = random(70, 165) * (0.9 + 0.3 * sin(i * 0.3));
    let hx = random(hueRange[0], hueRange[1]);
    let sx = random(satRange[0], satRange[1]);
    let bx = random(briRange[0], briRange[1]);
    let alpha = 14 + random(6);
    let offR = random(0, 80);
    let offA = random(TWO_PI);
    let ox = cos(offA) * offR * 0.9 * side;
    let oy = sin(offA) * offR * 0.6;
    fill(hx, sx, bx, alpha);
    drawPetal(cx + ox, cy + oy + random(-40, 40), a, len, w);

    // Occasional rim highlight
    if (random() < 0.35) {
      noFill();
      stroke(hx, sx * 0.7, min(100, bx + 10), 16);
      strokeWeight(random(0.6, 1.2));
      drawPetalOutline(cx + ox, cy + oy, a, len * 0.98, w * 0.95);
      noStroke();
    }
  }
  pop();
}

function drawPetal(x, y, angle, len, w) {
  push();
  translate(x, y);
  rotate(angle);
  beginShape();
  vertex(0, 0);
  bezierVertex(len * 0.25, -w, len * 0.78, -w * 0.25, len, 0);
  bezierVertex(len * 0.78, w * 0.25, len * 0.25, w, 0, 0);
  endShape(CLOSE);
  pop();
}

function drawPetalOutline(x, y, angle, len, w) {
  push();
  translate(x, y);
  rotate(angle);
  beginShape();
  vertex(0, 0);
  bezierVertex(len * 0.25, -w, len * 0.78, -w * 0.25, len, 0);
  bezierVertex(len * 0.78, w * 0.25, len * 0.25, w, 0, 0);
  endShape();
  pop();
}

function connectiveThreads(leftC, rightC, n) {
  push();
  blendMode(SCREEN);
  strokeCap(ROUND);
  for (let i = 0; i < n; i++) {
    let baseY = lerp(leftC.y - 260, leftC.y + 260, random());
    let jitter = random(-40, 40);
    let x1 = leftC.x + random(-110, 30);
    let x2 = rightC.x + random(-30, 110);
    let y1 = baseY + jitter * 0.6;
    let y2 = baseY - jitter * 0.6;
    let c1x = lerp(x1, width * 0.5, 0.6) + random(-40, 20);
    let c2x = lerp(x2, width * 0.5, 0.6) + random(20, 40);
    let c1y = y1 - random(60, 220);
    let c2y = y2 + random(60, 220);

    let t = abs((baseY - leftC.y) / 260);
    let h = lerpHue(18, 345, 0.5 + 0.5 * sin(i * 0.17 + t * 2.0));
    let s = 40 + 30 * (1 - t);
    let b = 70 + 25 * (1 - t);
    let a = 14 + 18 * (1 - t);
    stroke(h, s, b, a);
    strokeWeight(0.7 + 1.8 * pow(1 - t, 2) * random(0.6, 1.1));
    noFill();
    bezier(x1, y1, c1x, c1y, c2x, c2y, x2, y2);
  }
  pop();
}

function sharedFlame(center) {
  push();
  blendMode(ADD);
  for (let i = 0; i < 200; i++) {
    let t = i / 199;
    let rad = lerp(260, 12, easeOutCubic(t));
    let hh = lerpHue(22, 345, 0.4 + 0.6 * t);
    let ss = 60 + 30 * (1 - t);
    let bb = 70 + 30 * (1 - 0.7 * t);
    let aa = 10 + 18 * pow(1 - t, 1.4);
    fill(hh, ss, bb, aa);
    let ox = randomGaussian(0, 3.5) * (1 - 0.6 * t);
    let oy = randomGaussian(0, 5) * (1 - 0.6 * t);
    ellipse(center.x + ox, center.y + oy, rad * 2, rad * 2);
  }

  // Inner pulse
  for (let i = 0; i < 70; i++) {
    let r = random(6, 22);
    let hh = lerpHue(20, 45, random());
    fill(hh, 20, 100, 30);
    ellipse(center.x + random(-2, 2), center.y + random(-3, 3), r * 2, r * 2);
  }
  pop();
}

function sparkles(center, spread, count) {
  push();
  blendMode(SCREEN);
  for (let i = 0; i < count; i++) {
    let ang = random(TWO_PI);
    let d = pow(random(), 0.6) * spread;
    let x = center.x + cos(ang) * d + random(-2, 2);
    let y = center.y + sin(ang) * d + random(-2, 2);
    let r = random(0.8, 2.6);
    fill(48, 15, 100, 18 + random(14));
    ellipse(x, y, r * 2, r * 2);
  }
  pop();
}

function foundation() {
  push();
  let yTop = height * 0.76;
  let yBot = height * 0.98;
  for (let y = yTop; y < yBot; y += random(2, 7)) {
    let t = map(y, yTop, yBot, 0, 1);
    let h = lerpHue(320, 210, t * 0.7);
    let s = 35 + 25 * (1 - t);
    let b = lerp(22, 8, t);
    let a = 12 + 18 * (1 - t);
    fill(h, s, b, a);
    let x1 = -60 + noise(y * 0.01) * 120;
    let x2 = width + 60 - noise(1000 + y * 0.01) * 120;
    let wiggle = 8 + 18 * (1 - t);
    let y2 = y + random(-wiggle, wiggle);
    rect(min(x1, x2), min(y, y2), abs(x2 - x1), abs(y2 - y));
  }

  // Anchoring dark base
  let baseCol = color(220, 45, 8, 60);
  for (let i = 0; i < 6; i++) {
    fill(hue(baseCol), saturation(baseCol), brightness(baseCol), 30 - i * 3);
    rect(-50, height - 80 - i * 12, width + 100, 40 + i * 28);
  }
  pop();
}

function lerpHue(h1, h2, t) {
  // Shortest hue interpolation
  let d = ((h2 - h1 + 540) % 360) - 180;
  return (h1 + d * t + 360) % 360;
}

function smoothstep(a, b, x) {
  let t = constrain((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
}

function easeOutCubic(t) {
  return 1 - pow(1 - t, 3);
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  colorMode(HSB, 360, 100, 100, 1);
  noLoop();
}

function draw() {
  // Background: deep night gradient with subtle texture
  drawBackground();
  scatterTexture(16000);

  // Warm central halo
  blendMode(SCREEN);
  centralHalo(width * 0.5, height * 0.56, 820, 1.2, color(38, 60, 60, 0.035));
  blendMode(BLEND);

  // Paths for two embracing figures
  let L0 = createVector(width * 0.32, height * 0.80);
  let L1 = createVector(width * 0.20, height * 0.55);
  let L2 = createVector(width * 0.45, height * 0.55);
  let L3 = createVector(width * 0.36, height * 0.26);

  let R0 = mirrorX(L0);
  let R1 = mirrorX(L1);
  let R2 = mirrorX(L2);
  let R3 = mirrorX(L3);

  let N = 180;
  let leftPath = makePath(L0, L1, L2, L3, N);
  let rightPath = makePath(R0, R1, R2, R3, N);

  // Paint two figures with layered strokes
  drawFigure(leftPath, {
    baseHue: 18, // coral/peach
    maxRadius: 150,
    seed: 101,
    coreCenter: createVector(width * 0.5, height * 0.53),
    coreRadius: 260
  });

  drawFigure(rightPath, {
    baseHue: 320, // magenta
    maxRadius: 150,
    seed: 202,
    coreCenter: createVector(width * 0.5, height * 0.53),
    coreRadius: 260
  });

  // Shared inner glow at the meeting point
  blendMode(SCREEN);
  sharedCoreGlow(width * 0.5, height * 0.53, 320, 0.78);
  blendMode(BLEND);

  // Floating sparks
  blendMode(SCREEN);
  sparks(width * 0.5, height * 0.53, 240, 240);
  blendMode(BLEND);

  // Edge vignette
  vignette(260, 0.25);
}

// Utilities and painters

function drawBackground() {
  let cTop = color(260, 40, 15, 1);
  let cBottom = color(350, 45, 18, 1);
  noStroke();
  for (let y = 0; y < height; y++) {
    let t = y / (height - 1);
    let c = lerpColor(cTop, cBottom, t);
    stroke(c);
    line(0, y, width, y);
  }

  // Subtle radial coolness near top
  blendMode(SCREEN);
  noStroke();
  let cx = width * 0.52;
  let cy = height * 0.18;
  for (let r = 680; r > 40; r -= 18) {
    let a = map(r, 40, 680, 0.02, 0.0015);
    fill(210, 30, 18, a);
    ellipse(cx + noise(r) * 8 - 4, cy + noise(r + 1000) * 8 - 4, r * 1.6, r);
  }
  blendMode(BLEND);
}

function scatterTexture(count) {
  noStroke();
  for (let i = 0; i < count; i++) {
    let x = random(width);
    let y = random(height);
    let t = y / height;
    let base = lerpColor(color(260, 35, 18, 1), color(350, 40, 22, 1), t);
    let h = hue(base) + random(-6, 6);
    let s = saturation(base) + random(-8, 8);
    let b = brightness(base) + random(-6, 6);
    let a = random(0.01, 0.028);
    fill(h, s, b, a);
    let w = random(1.2, 3.5);
    let hgt = w * random(0.6, 1.6);
    ellipse(x + random(-1.2, 1.2), y + random(-1.0, 1.0), w, hgt);
  }
}

function centralHalo(cx, cy, radius, yScale, col) {
  noStroke();
  for (let r = radius; r > 60; r -= 18) {
    let a = alpha(col) * map(r, 60, radius, 0.9, 0.02);
    fill(hue(col), saturation(col), brightness(col), a);
    let jitterX = (noise(r * 0.11) - 0.5) * 6;
    let jitterY = (noise(r * 0.09 + 999) - 0.5) * 6;
    ellipse(cx + jitterX, cy + jitterY, r * 1.6, r * yScale);
  }
}

function makePath(p0, p1, p2, p3, steps) {
  let arr = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let x = bezierPoint(p0.x, p1.x, p2.x, p3.x, t);
    let y = bezierPoint(p0.y, p1.y, p2.y, p3.y, t);
    let dx = bezierTangent(p0.x, p1.x, p2.x, p3.x, t);
    let dy = bezierTangent(p0.y, p1.y, p2.y, p3.y, t);
    let tan = createVector(dx, dy);
    tan.normalize();
    let nor = createVector(-tan.y, tan.x);
    arr.push({ pos: createVector(x, y), tan: tan.copy(), nor: nor.copy(), t: t });
  }
  return arr;
}

function drawFigure(path, cfg) {
  let baseHue = cfg.baseHue;
  let baseR = cfg.maxRadius;
  let coreC = cfg.coreCenter.copy();
  let coreR = cfg.coreRadius;
  let seed = cfg.seed || 0;

  // Multilayer soft fill
  noStroke();
  for (let pass = 0; pass < 8; pass++) {
    let passVar = pass / 7;
    for (let i = 0; i < path.length; i++) {
      let node = path[i];
      let t = node.t;
      let center = node.pos;
      let tan = node.tan;
      let nor = node.nor;

      let r = radiusProfile(t, baseR) * map(noise(seed * 0.013 + t * 2.7 + pass * 0.21), 0, 1, 0.85, 1.15);
      let nStrokes = floor(map(r, 0, baseR, 4, 30));

      for (let s = 0; s < nStrokes; s++) {
        let d = clamp(randomGaussian(0, r * 0.45), -r, r);
        let along = randomGaussian(0, r * 0.06);
        let p = p5.Vector.add(center, p5.Vector.mult(nor, d));
        p.add(p5.Vector.mult(tan, along));

        let prox = dist(p.x, p.y, coreC.x, coreC.y);
        let nearCore = prox < coreR;

        let tight = 1 - abs(d) / (r + 0.0001);
        let w = map(tight, 0, 1, r * 0.05, r * 0.22) * random(0.75, 1.25);
        let hgt = w * random(0.6, 1.6);

        let hueJitter = random(-8, 8) + map(abs(d) / (r + 1e-5), 0, 1, 0, -6);
        let sJitter = random(-6, 6);
        let bJitter = random(-8, 8);

        let h = baseHue + hueJitter;
        let sCol = 70 + sJitter + passVar * 8;
        let bCol = 72 + bJitter + passVar * 6;

        if (nearCore) {
          bCol += map(prox, 0, coreR, 20, 0);
          if (random() < 0.17) {
            // occasional golden kiss near overlap
            h = 38 + random(-6, 6);
            sCol = 60 + random(-8, 10);
            bCol = 78 + random(-4, 8);
          }
        }

        fill(h, sCol, bCol, 0.08 * map(pass, 0, 7, 0.85, 1));
        push();
        translate(p.x, p.y);
        rotate(tan.heading() + randomGaussian(0, 0.28));
        ellipse(0, 0, w, hgt);
        pop();
      }
    }
  }

  // Edge accents (subtle boundary strength)
  for (let i = 0; i < path.length; i += 2) {
    let node = path[i];
    let t = node.t;
    let r = radiusProfile(t, baseR) * 1.02;
    let tan = node.tan;
    let nor = node.nor;

    let pL = p5.Vector.add(node.pos, p5.Vector.mult(nor, r));
    let pR = p5.Vector.add(node.pos, p5.Vector.mult(nor, -r));

    let nEdge = 1 + floor(random(1, 3));
    for (let k = 0; k < nEdge; k++) {
      let len = random(8, 22);
      let off = random(-6, 6);
      let side = random() < 0.5 ? pL : pR;
      let start = p5.Vector.add(side, p5.Vector.mult(tan, off));
      let end = p5.Vector.add(start, p5.Vector.mult(tan, len));
      stroke(baseHue + random(-12, 10), 50 + random(-10, 14), 28 + random(-8, 10), random(0.12, 0.22));
      strokeWeight(random(1, 2.4));
      line(start.x, start.y, end.x, end.y);
    }
  }

  // Soft aura around each figure
  blendMode(SCREEN);
  noStroke();
  for (let i = 0; i < path.length; i += 2) {
    let node = path[i];
    let t = node.t;
    let tan = node.tan;
    let glowR = radiusProfile(t, baseR) * 1.28;
    let a = map(glowR, 0, baseR * 1.28, 0.02, 0.006);
    fill(baseHue, 35, 70, a);
    push();
    translate(node.pos.x, node.pos.y);
    rotate(tan.heading());
    ellipse(0, 0, glowR * 1.9, glowR * 1.3);
    pop();
  }
  blendMode(BLEND);
}

function sharedCoreGlow(cx, cy, size, yScale) {
  noStroke();
  // Pink-gold breathing core
  for (let r = size; r > 8; r -= 12) {
    let t = r / size;
    let g = color(38, 70, 86, 0.035 * t);
    let p = color(320, 60, 88, 0.028 * t);
    let mix = lerpColor(g, p, 0.45 + 0.25 * sin((1 - t) * PI));
    fill(mix);
    ellipse(cx + (noise(r * 0.2) - 0.5) * 4, cy + (noise(r * 0.2 + 999) - 0.5) * 4, r * 2.2, r * 2.2 * yScale);
  }
}

function sparks(cx, cy, rx, ry) {
  noStroke();
  for (let i = 0; i < 240; i++) {
    let ang = random(TWO_PI);
    let rad = pow(random(), 0.5) * random(10, max(rx, ry));
    let x = cx + cos(ang) * rad * random(0.6, 1.0);
    let y = cy + sin(ang) * rad * random(0.6, 1.0);
    let choice = random();
    let c;
    if (choice < 0.5) c = color(38 + random(-6, 6), 70, 92, random(0.18, 0.32));
    else c = color(320 + random(-8, 8), 65, 96, random(0.16, 0.28));
    fill(c);
    let s = random(1.2, 3.4);
    ellipse(x, y, s, s);
    if (random() < 0.25) {
      // tiny tail
      stroke(hue(c), saturation(c), brightness(c), alpha(c) * 0.6);
      strokeWeight(1.2);
      let tailLen = random(3, 9);
      let a = random(TWO_PI);
      line(x, y, x + cos(a) * tailLen, y + sin(a) * tailLen);
      noStroke();
    }
  }
}

function vignette(margin, strength) {
  noStroke();
  // Top
  for (let y = 0; y < margin; y++) {
    let a = strength * (1 - y / margin) * 0.5;
    fill(0, 0, 0, a);
    rect(0, y, width, 1);
  }
  // Bottom
  for (let y = height - margin; y < height; y++) {
    let a = strength * (1 - (height - y) / margin) * 0.5;
    fill(0, 0, 0, a);
    rect(0, y, width, 1);
  }
  // Left
  for (let x = 0; x < margin; x++) {
    let a = strength * (1 - x / margin) * 0.5;
    fill(0, 0, 0, a);
    rect(x, 0, 1, height);
  }
  // Right
  for (let x = width - margin; x < width; x++) {
    let a = strength * (1 - (width - x) / margin) * 0.5;
    fill(0, 0, 0, a);
    rect(x, 0, 1, height);
  }
}

function radiusProfile(t, maxR) {
  // Taper at ends, fuller center
  let s = pow(sin(PI * constrain(t, 0, 1)), 0.9);
  let n = map(noise(t * 3.1), 0, 1, 0.92, 1.08);
  return maxR * s * n;
}

function mirrorX(v) {
  return createVector(width - v.x, v.y);
}

function clamp(v, a, b) {
  return max(a, min(b, v));
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  colorMode(HSB, 360, 100, 100, 1);
  noLoop();

  // Helpers
  function withAlpha(c, a) {
    let cc = color(c);
    cc.setAlpha(a);
    return cc;
  }
  function lerpC(a, b, t) {
    return lerpColor(a, b, t);
  }

  // Background palette
  let bgDeep = color(270, 60, 8, 1);   // deep indigo
  let bgWarm = color(330, 35, 22, 1);  // plum ember

  // Base background
  noStroke();
  fill(bgDeep);
  rect(0, 0, width, height);

  // Radial, velvety wash
  let cx = width * 0.5;
  let cy = height * 0.58;
  for (let i = 0; i < 260; i++) {
    let t = i / 259;
    let col = lerpC(bgDeep, bgWarm, pow(t, 1.55));
    fill(withAlpha(col, 0.12));
    let w = width * 2.2 * (1 - 0.85 * t);
    let h = height * 2.6 * (1 - 0.85 * t);
    ellipse(cx, cy, w, h);
  }

  // Diagonal soft strokes to add atmosphere
  for (let i = 0; i < 140; i++) {
    let ang = radians(-25 + random(-5, 5));
    let rx = random(-200, width + 200);
    let ry = random(-200, height + 200);
    let wlen = random(300, 1200);
    let thick = random(2, 8);
    let ct = lerpC(bgWarm, bgDeep, random(0.25, 0.9));
    let a = random(0.02, 0.06);
    push();
      translate(rx, ry);
      rotate(ang);
      noStroke();
      fill(withAlpha(ct, a));
      rect(0, 0, wlen, thick);
    pop();
  }

  // Blob parameters (two leaning beings)
  let left = { cx: 720, cy: 1100, r: 390, sx: 0.92, sy: 1.2, rot: -0.18, offx: 2.13, offy: 5.31 };
  let right = { cx: 880, cy: 1080, r: 390, sx: 0.92, sy: 1.2, rot: 0.18, offx: 7.47, offy: 1.83 };

  // Blob palettes
  let leftA = color(6, 72, 85, 1);    // coral-rose outer
  let leftB = color(350, 40, 98, 1);  // pale blush inner
  let rightA = color(310, 50, 80, 1); // violet outer
  let rightB = color(336, 62, 95, 1); // fuchsia inner

  // Soft halos behind each figure (subtle glow)
  blendMode(ADD);
  function aura(p, col, yLift) {
    for (let j = 0; j < 80; j++) {
      let t = j / 79;
      let a = 0.012 * (1 - t);
      fill(withAlpha(col, a));
      let w = p.r * 2.2 * (1 - 0.42 * t);
      let h = p.r * 2.4 * (1 - 0.42 * t);
      let jx = p.cx + (noise(j * 0.07) - 0.5) * 4 * (1 - t);
      let jy = p.cy + yLift + (noise(100 + j * 0.07) - 0.5) * 4 * (1 - t);
      ellipse(jx, jy, w, h);
    }
  }
  aura(left, leftA, -30);
  aura(right, rightA, -20);
  blendMode(BLEND);

  // Blob drawing
  function blobVertex(p, ang, radScale) {
    let amp = 0.18;
    let rr = p.r * radScale * (0.88 + amp * noise(p.offx + cos(ang) * 1.4, p.offy + sin(ang) * 1.4));
    let x = p.cx + cos(ang + p.rot) * rr * p.sx;
    let y = p.cy + sin(ang + p.rot) * rr * p.sy;
    return { x, y };
  }
  function drawBlobLayers(p, cA, cB, layers) {
    noStroke();
    for (let l = 0; l < layers; l++) {
      let t = l / max(1, layers - 1);
      let col = lerpC(cA, cB, t);
      let a = 0.65 * (1 - t) * 0.8 + 0.06;
      fill(withAlpha(col, a));
      beginShape();
      let step = TWO_PI / 240;
      for (let a0 = 0; a0 < TWO_PI + 0.001; a0 += step) {
        // Slight layer-specific drift for painterly depth
        let ang = a0 + t * 0.25;
        let radScale = 1 - 0.065 * l;
        let v = blobVertex(p, ang, radScale);
        vertex(v.x, v.y);
      }
      endShape(CLOSE);
    }
  }
  drawBlobLayers(left, leftA, leftB, 8);
  drawBlobLayers(right, rightA, rightB, 8);

  // Shared glow at the overlap (a warm heart of light)
  let mx = (left.cx + right.cx) * 0.5;
  let my = (left.cy + right.cy) * 0.5 - 40;
  blendMode(ADD);
  for (let i = 0; i < 220; i++) {
    let t = i / 219;
    let colG = lerpC(color(10, 85, 100, 1), color(42, 82, 100, 1), t);
    fill(withAlpha(colG, 0.055 * (1 - t)));
    let w = lerp(540, 70, t);
    let h = lerp(420, 50, t);
    let jx = mx + (noise(i * 0.07) - 0.5) * 20 * (1 - t);
    let jy = my + (noise(100 + i * 0.07) - 0.5) * 20 * (1 - t);
    ellipse(jx, jy, w, h);
  }
  blendMode(BLEND);

  // Connecting threads (chosen bonds)
  function blobPoint(p, ang) {
    // Use base contour (matches blobVertex noise field)
    let v = blobVertex(p, ang, 1);
    return v;
  }
  let N = 70;
  for (let i = 0; i < N; i++) {
    let aL = random(-0.7, 0.7);
    let aR = PI + aL + random(-0.15, 0.15);
    let pL = blobPoint(left, aL);
    let pR = blobPoint(right, aR);

    let mx12x = (pL.x + pR.x) / 2;
    let up = random(160, 300);
    let c1x = lerp(pL.x, mx12x, 0.3) + random(-30, 30);
    let c1y = pL.y - up;
    let c2x = lerp(pR.x, mx12x, 0.3) + random(-30, 30);
    let c2y = pR.y - up + random(-20, 20);

    let t = i / (N - 1);
    let colLine = lerpC(leftB, rightB, t);
    noFill();
    stroke(withAlpha(colLine, 0.25 * (0.3 + 0.7 * sin(t * PI))));
    strokeWeight(1 + random(0.0, 0.8));
    bezier(pL.x, pL.y, c1x, c1y, c2x, c2y, pR.x, pR.y);
  }

  // Dusting of light around the union
  for (let i = 0; i < 900; i++) {
    let ang = random(TWO_PI);
    let rr = pow(random(), 1.5) * 480;
    let px = mx + cos(ang) * rr * 1.2;
    let py = my + sin(ang) * rr * 0.9;
    let cc = lerpC(color(10, 70, 100, 1), color(300, 20, 100, 1), random(0.1, 0.9));
    noStroke();
    fill(withAlpha(cc, 0.15));
    let sz = random(1, 3);
    ellipse(px + random(-0.5, 0.5), py + random(-0.5, 0.5), sz, sz);
  }

  // Gentle vignette to cradle the scene
  for (let i = 0; i < 60; i++) {
    let t = i / 60;
    noStroke();
    fill(0, 0, 0, 0.03 * (1 - t));
    rect(-10, -10, width + 20, 40 + t * height * 0.5); // top
    rect(-10, height - (40 + t * height * 0.5), width + 20, 40 + t * height * 0.5); // bottom
    rect(-10, -10, 40 + t * width * 0.5, height + 20); // left
    rect(width - (40 + t * width * 0.5), -10, 40 + t * width * 0.5, height + 20); // right
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  colorMode(RGB, 255, 255, 255, 255);
  noLoop();
  noStroke();
  drawScene();
}

function drawScene() {
  drawBackground();

  const left = createVector(620, 1080);
  const right = createVector(1020, 920);
  const mid = p5.Vector.lerp(left, right, 0.5);

  // Subtle ambient glow
  blendMode(SCREEN);
  radialGradient(mid.x, mid.y, 700, color(255, 210, 230, 50), color(255, 190, 210, 0), 50);
  blendMode(BLEND);

  // Two luminous, soft bodies
  drawOrb(left.x, left.y, 380, color(255, 108, 128), color(255, 178, 165), 0.73);
  drawOrb(right.x, right.y, 360, color(120, 130, 255), color(198, 120, 255), 9.37);

  // Overlap highlight
  blendMode(SCREEN);
  radialGradient(mid.x, mid.y, 260, color(255, 240, 255, 90), color(255, 240, 255, 0), 32);
  blendMode(BLEND);

  // Threads that lean toward each other
  drawThreads(left, right, 640, color(255, 160, 170, 90), color(190, 170, 255, 80));
  drawThreads(right, left, 640, color(190, 170, 255, 90), color(255, 160, 170, 80));

  // Embrace ribbon enclosing both
  const axisAngle = atan2(right.y - left.y, right.x - left.x);
  const rx = dist(left.x, left.y, right.x, right.y) * 0.62 + 270;
  const ry = 430;
  drawEmbrace(createVector(mid.x, mid.y + 6), axisAngle, rx, ry, color(255, 220, 200));

  // Petal-like sparks around the union
  drawPetals(mid, 420);

  // Gentle specks
  drawSpecks(1100);

  // Vignette to cradle the scene
  vignette(width * 0.5, height * 0.54);
}

function drawBackground() {
  let stops = [
    { t: 0.0,  c: color(12, 10, 35) },     // deep indigo
    { t: 0.55, c: color(55, 28, 74) },     // plum
    { t: 1.0,  c: color(250, 192, 186) }   // soft blush
  ];
  for (let y = 0; y < height; y++) {
    let t = y / (height - 1);
    let col = lerpColorStops(t, stops);
    stroke(col);
    line(0, y, width, y);
  }
}

function lerpColorStops(t, stops) {
  t = constrain(t, 0, 1);
  for (let i = 0; i < stops.length - 1; i++) {
    let a = stops[i];
    let b = stops[i + 1];
    if (t >= a.t && t <= b.t) {
      let lt = (t - a.t) / (b.t - a.t);
      return lerpColor(a.c, b.c, lt);
    }
  }
  if (t < stops[0].t) return stops[0].c;
  return stops[stops.length - 1].c;
}

function radialGradient(x, y, r, c1, c2, steps) {
  push();
  noStroke();
  for (let i = 0; i < steps; i++) {
    let t = i / (steps - 1);
    let c = lerpColor(c1, c2, t);
    fill(c);
    let rr = r * t;
    ellipse(x, y, rr * 2, rr * 2);
  }
  pop();
}

function drawOrb(cx, cy, r, cMain, cAlt, seed) {
  push();
  noStroke();
  // Base glow
  blendMode(SCREEN);
  radialGradient(
    cx, cy, r * 1.55,
    color(red(cMain), green(cMain), blue(cMain), 40),
    color(red(cMain), green(cMain), blue(cMain), 0),
    42
  );
  blendMode(BLEND);

  let layers = 82;
  let stepAng = TWO_PI / 160;
  for (let i = 0; i < layers; i++) {
    let t = i / (layers - 1);
    let col = lerpColor(cMain, cAlt, t * 0.75);
    col = color(red(col), green(col), blue(col), 18 + (1 - t) * 20);
    fill(col);
    let rr = r * (0.96 + 0.18 * t) * (0.90 + 0.06 * noise(seed + i * 0.13));
    beginShape();
    for (let a = 0; a <= TWO_PI + stepAng; a += stepAng) {
      let nx = cos(a);
      let ny = sin(a);
      let ns = 0.0065;
      let wav = (noise((cx + nx * r) * ns + seed * 2.3 + i * 0.031,
                       (cy + ny * r) * ns + seed * 3.7 + i * 0.026) - 0.5);
      let d = 1.0 + 0.28 * wav + 0.07 * sin(a * 3.0 + i * 0.08);
      let x = cx + nx * rr * d;
      let y = cy + ny * rr * d;
      vertex(x, y);
    }
    endShape(CLOSE);
  }

  // Soft inner sheen
  blendMode(SCREEN);
  radialGradient(
    cx, cy, r * 0.85,
    color(255, 245, 250, 32),
    color(255, 245, 250, 0),
    26
  );
  blendMode(BLEND);
  pop();
}

function drawThreads(a, b, count, cA, cB) {
  push();
  blendMode(SCREEN);
  noFill();
  let scale = 0.0018;
  let stepLen = 2.0;

  for (let i = 0; i < count; i++) {
    let baseAng = random(TWO_PI);
    let ring = 170 + random(-40, 60);
    let start = createVector(
      a.x + cos(baseAng) * ring + random(-30, 30),
      a.y + sin(baseAng) * ring + random(-30, 30)
    );

    let pos = start.copy();
    let prev = pos.copy();
    let steps = 120 + floor(random(40));

    for (let s = 0; s < steps; s++) {
      let nAng = noise(pos.x * scale, pos.y * scale) * TWO_PI * 2.0;
      let dirTo = atan2(b.y - pos.y, b.x - pos.x);
      let ang = lerpAngle(nAng, dirTo, 0.28 + 0.12 * noise(100 + i * 0.07, s * 0.03));
      let v = p5.Vector.fromAngle(ang);
      v.mult(stepLen * (0.86 + 0.36 * noise(200 + pos.x * scale, 200 + pos.y * scale)));
      pos.add(v);

      if (pos.x < -50 || pos.x > width + 50 || pos.y < -50 || pos.y > height + 50) break;

      let p = s / steps;
      let col = lerpColor(cA, cB, p);
      stroke(red(col), green(col), blue(col), 28);
      strokeWeight(1.3 - 0.95 * p + 0.25 * noise(300 + i * 0.1, s * 0.05));
      line(prev.x, prev.y, pos.x, pos.y);
      prev.set(pos);

      // Gentle pull toward the other
      pos.x += 0.22 * cos(dirTo) * (1 - p);
      pos.y += 0.22 * sin(dirTo) * (1 - p);
    }
  }
  blendMode(BLEND);
  pop();
}

function lerpAngle(a, b, t) {
  let d = atan2(sin(b - a), cos(b - a));
  return a + d * t;
}

function drawEmbrace(mid, angle, rx, ry, colInner) {
  push();
  translate(mid.x, mid.y);
  rotate(angle);
  noStroke();

  let layers = 32;
  for (let l = 0; l < layers; l++) {
    let t = l / (layers - 1);
    let alpha = 18 * (1 - t * 0.9);
    fill(red(colInner), green(colInner), blue(colInner), alpha);
    beginShape();
    let pts = 220;
    for (let i = 0; i < pts; i++) {
      let a = (i / pts) * TWO_PI;
      // Hug shape: peanut-like ring guided by two foci
      let baseR = 1.0 + 0.26 * cos(2 * a);
      let dx = cos(a) * rx * baseR;
      let dy = sin(a) * ry * (0.68 + 0.32 * cos(a));
      let ns = 0.0062;
      let k = 1 + 0.08 * noise(300 + dx * ns + l * 0.11, 300 + dy * ns + l * 0.07) - 0.04;
      vertex(dx * k, dy * k);
    }
    endShape(CLOSE);
  }

  // Whispered outline
  stroke(255, 210, 200, 25);
  strokeWeight(2);
  noFill();
  beginShape();
  let pts = 260;
  for (let i = 0; i < pts; i++) {
    let a = (i / pts) * TWO_PI;
    let baseR = 1.0 + 0.26 * cos(2 * a);
    let dx = cos(a) * rx * baseR;
    let dy = sin(a) * ry * (0.68 + 0.32 * cos(a));
    let ns = 0.0062;
    let k = 1 + 0.06 * noise(300 + dx * ns, 300 + dy * ns) - 0.03;
    vertex(dx * k, dy * k);
  }
  endShape(CLOSE);
  pop();
}

function drawPetals(center, count) {
  push();
  blendMode(SCREEN);
  noStroke();
  let palette = [
    color(255, 170, 180, 90),
    color(255, 210, 190, 80),
    color(230, 160, 255, 80),
    color(255, 235, 200, 70)
  ];

  for (let i = 0; i < count; i++) {
    let ang = random(TWO_PI);
    let rad = 120 + pow(random(), 1.8) * 520;
    let x = center.x + cos(ang) * rad + random(-8, 8);
    let y = center.y + sin(ang) * rad + random(-8, 8);
    let sz = 6 + pow(random(), 2) * 26;
    let c = palette[floor(random(palette.length))];

    fill(c);
    push();
    translate(x, y);
    rotate(ang + random(-0.4, 0.4));
    ellipse(0, 0, sz * 0.6, sz * 0.18);
    pop();
  }
  blendMode(BLEND);
  pop();
}

function drawSpecks(count) {
  push();
  blendMode(SCREEN);
  for (let i = 0; i < count; i++) {
    let x = random(width);
    let y = random(height);
    let a = (0.6 + 0.4 * noise(x * 0.004, y * 0.004)) * 50;
    stroke(255, 240, 250, a);
    strokeWeight(random(0.4, 1.1));
    point(x, y);
    if (random() < 0.06) {
      strokeWeight(random(1.4, 2.6));
      point(x + random(-0.5, 0.5), y + random(-0.5, 0.5));
    }
  }
  blendMode(BLEND);
  pop();
}

function vignette(cx, cy) {
  push();
  noStroke();
  let inner = color(0, 0, 0, 0);
  let outer = color(0, 0, 0, 140);
  radialGradient(cx, cy, max(width, height) * 0.78, inner, outer, 84);
  pop();
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // Colors
  let bgTop = color(16, 22, 48);
  let bgBot = color(40, 10, 20);
  let warm1 = color(255, 146, 96);
  let warm2 = color(208, 36, 84);
  let cool1 = color(64, 198, 210);
  let cool2 = color(92, 78, 180);
  let glowPeach = color(255, 210, 170);
  let glowRose = color(255, 170, 150);
  let whiteGlow = color(250, 245, 240);

  // Background gradient
  verticalGradient(bgTop, bgBot);

  // Central gentle warm field
  radialGlow(width * 0.5, height * 0.55, 900, color(255, 160, 130), 14, 90);

  // Painterly interwoven bodies
  blendMode(SCREEN);
  blob(680, 1120, 560, 42, warm1, warm2, 0.9, 0.28, -0.3);
  blob(960, 1080, 540, 40, cool1, cool2, 1.0, 0.26, 0.25);

  // Shared luminous core
  radialGlow(width * 0.5, height * 0.56, 360, glowPeach, 18, 120);
  radialGlow(width * 0.5 + 10, height * 0.56 - 8, 220, glowRose, 20, 120);
  blendMode(ADD);
  radialGlow(width * 0.5 - 5, height * 0.555, 110, whiteGlow, 22, 70);
  blendMode(BLEND);

  // Embracing ribbons converging to the center
  strokeCap(ROUND);
  strokeJoin(ROUND);
  let center = createVector(width * 0.5, height * 0.56);

  // Warm ribbons from left/below
  for (let i = 0; i < 18; i++) {
    let sx = random(220, 680);
    let sy = height - random(120, 420);
    let colA = color(255, 180, 80);
    let colB = color(232, 48, 124);
    let ws = random(4.0, 7.0);
    let we = random(0.8, 2.2);
    drawRibbon(createVector(sx, sy), center.copy().add(-random(0, 60), random(-40, 40)), colA, colB, ws, we, random(1000));
  }

  // Cool ribbons from right/below
  for (let i = 0; i < 18; i++) {
    let sx = random(920, 1380);
    let sy = height - random(110, 420);
    let colA = color(64, 220, 210);
    let colB = color(110, 98, 235);
    let ws = random(4.0, 7.0);
    let we = random(0.8, 2.2);
    drawRibbon(createVector(sx, sy), center.copy().add(random(0, 60), random(-40, 40)), colA, colB, ws, we, random(1000, 2000));
  }

  // Gentle counterflow arcs, like an orbit
  push();
  blendMode(SOFT_LIGHT);
  noFill();
  for (let i = 0; i < 7; i++) {
    let t = i / 6;
    let c = lerpColor(warm2, cool2, t);
    stroke(red(c), green(c), blue(c), 60 - t * 40);
    strokeWeight(18 - t * 10);
    let rx = 540 + t * 40;
    let ry = 380 + t * 60;
    arc(width * 0.5, height * 0.56, rx * 2, ry * 2, -PI * 0.15, PI + PI * 0.15);
  }
  pop();

  // Sparkles at the union
  blendMode(ADD);
  sparkles(center.x, center.y, 600, 200, 120, color(255, 240, 220), 14, 70);
  sparkles(center.x - 90, center.y + 40, 380, 260, 140, lerpColor(warm1, warm2, 0.6), 10, 60);
  sparkles(center.x + 90, center.y - 30, 380, 260, 140, lerpColor(cool1, cool2, 0.5), 10, 60);
  blendMode(BLEND);

  // Edge vignette
  vignette(180);

  // Subtle grain to unify
  subtleGrain(0.06, 90);
}

// --------- Helpers ---------
function verticalGradient(c1, c2) {
  noStroke();
  for (let y = 0; y < height; y++) {
    let t = y / (height - 1);
    let c = lerpColor(c1, c2, t);
    fill(c);
    rect(0, y, width, 1);
  }
}

function radialGlow(x, y, r, col, maxAlpha, steps) {
  noStroke();
  for (let i = 0; i < steps; i++) {
    let t = i / (steps - 1);
    let rr = lerp(r, 0, easeOutQuad(t));
    let a = (1 - t) * maxAlpha;
    let cc = color(red(col), green(col), blue(col), a);
    fill(cc);
    ellipse(x, y, rr * 2, rr * 2);
  }
}

function blob(cx, cy, R, layers, cA, cB, noiseScale, amp, rot) {
  noStroke();
  let npts = 200;
  for (let j = 0; j < layers; j++) {
    let t = j / (layers - 1);
    let c = lerpColor(cA, cB, t);
    let a = 26 * (1 - t) + 6;
    fill(color(red(c), green(c), blue(c), a));
    let base = R * (1 - 0.008 * j);
    beginShape();
    for (let i = 0; i < npts; i++) {
      let ang = (i / npts) * TWO_PI + rot + t * 0.35;
      let ns = noise(
        cos(ang) * noiseScale + 2.17,
        sin(ang) * noiseScale + 0.93,
        t * 1.7 + 0.31
      );
      let rr = base * (0.86 + amp * (ns - 0.3));
      let x = cx + rr * cos(ang);
      let y = cy + rr * sin(ang);
      vertex(x, y);
    }
    endShape(CLOSE);
  }
}

function drawRibbon(start, target, colA, colB, wStart, wEnd, seed) {
  let pos = start.copy();
  let prev = pos.copy();
  let steps = 230;
  let stopped = false;

  // Use additive light to glow, briefly, then blend to normal
  push();
  blendMode(ADD);
  for (let i = 0; i < steps; i++) {
    let t = i / (steps - 1);
    let toC = p5.Vector.sub(target, pos);
    let d = toC.mag();
    if (d < 24) { stopped = true; break; }

    let baseAng = toC.heading();
    let swirl = map(noise(seed, i * 0.05), 0, 1, -1.1, 1.1);
    let drift = (t - 0.5) * 0.5;
    let ang = baseAng + swirl * 0.35 + drift;

    let stepLen = lerp(10, 4.5, t) + map(noise(seed + 99, i * 0.04), 0, 1, -1.2, 1.2);
    pos.x += cos(ang) * stepLen;
    pos.y += sin(ang) * stepLen;

    let c = lerpColor(colA, colB, t);
    stroke(red(c), green(c), blue(c), 90);
    strokeWeight(lerp(wStart, wEnd, t));
    line(prev.x, prev.y, pos.x, pos.y);
    prev.set(pos.x, pos.y);
  }
  pop();

  // Final soft tail in blend mode for subtle body
  if (!stopped) {
    for (let i = 0; i < 40; i++) {
      let t = i / 39;
      let jitter = map(noise(seed + 200, i * 0.06), 0, 1, -0.6, 0.6);
      let c = lerpColor(colA, colB, 0.6 + 0.4 * t);
      stroke(red(c), green(c), blue(c), 30);
      strokeWeight(lerp(wEnd * 0.9, 0.4, t));
      let ang = atan2(target.y - pos.y, target.x - pos.x) + jitter * 0.3;
      let stepLen = lerp(4.5, 1.5, t);
      let nx = pos.x + cos(ang) * stepLen;
      let ny = pos.y + sin(ang) * stepLen;
      line(pos.x, pos.y, nx, ny);
      pos.set(nx, ny);
    }
  }
}

function sparkles(x, y, count, spreadX, spreadY, col, minA, maxA) {
  noStroke();
  for (let i = 0; i < count; i++) {
    let sx = x + randomGaussian() * spreadX;
    let sy = y + randomGaussian() * spreadY;
    let r = pow(random(), 2) * 3.5 + 0.6;
    let a = random(minA, maxA);
    fill(color(red(col), green(col), blue(col), a));
    ellipse(sx, sy, r, r);
  }
}

function vignette(edge) {
  noStroke();
  // Top and bottom
  for (let i = 0; i < edge; i++) {
    let a = map(i, 0, edge, 120, 0);
    fill(0, a);
    rect(0, i, width, 1);
    rect(0, height - 1 - i, width, 1);
  }
  // Left and right
  for (let i = 0; i < edge; i++) {
    let a = map(i, 0, edge, 120, 0);
    fill(0, a);
    rect(i, 0, 1, height);
    rect(width - 1 - i, 0, 1, height);
  }
}

function subtleGrain(strength, alpha) {
  // Light procedural grain to unify layers
  noStroke();
  for (let y = 0; y < height; y += 2) {
    for (let x = 0; x < width; x += 2) {
      let n = noise(x * 0.004, y * 0.004);
      let v = (n - 0.5) * 255 * strength;
      fill(120 + v, 120 + v, 120 + v, alpha * 0.05);
      rect(x, y, 2, 2);
    }
  }
}

function easeOutQuad(t) {
  return 1 - (1 - t) * (1 - t);
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  colorMode(RGB, 255);
  backgroundGradient();
  let cx = width * 0.5;
  let cy = height * 0.56;

  radialGlow(cx, cy);
  sideGlows(cx, cy);

  petals(cx, cy);

  flowThreads(cx, cy);

  goldenSeams(cx, cy);

  bokehOrbs(cx, cy);
}

// ---------- Background ----------
function backgroundGradient() {
  let topC = color('#0a0822');
  let botC = color('#2d0b18');
  strokeWeight(1);
  for (let y = 0; y < height; y++) {
    let t = y / (height - 1);
    let c = lerpColor(topC, botC, t);
    stroke(c);
    line(0, y, width, y);
  }

  // Subtle vignette
  noFill();
  let vign = color(0, 0, 0);
  push();
  blendMode(MULTIPLY);
  for (let i = 0; i < 90; i++) {
    let t = i / 89;
    let a = pow(t, 1.8) * 70;
    stroke(red(vign), green(vign), blue(vign), a);
    let inset = t * 240;
    rect(inset, inset, width - inset * 2, height - inset * 2);
  }
  pop();
}

// ---------- Glows ----------
function radialGlow(cx, cy) {
  push();
  blendMode(SCREEN);
  noStroke();

  let warms = [color('#ffd6b5'), color('#ffb3a7'), color('#ff8da1'), color('#ff6f91')];
  let ambers = [color('#ffd39a'), color('#ffc16e'), color('#ffb25b')];

  for (let i = 0; i < 140; i++) {
    let u = i / 139;
    let r = lerp(width * 0.78, width * 0.06, pow(u, 1.15));
    let c1 = gradList(warms, pow(u, 0.7));
    let c2 = gradList(ambers, 1 - pow(u, 3.0));
    let c = lerpColor(c1, c2, 0.45);
    let a = 26 * (1 - pow(u, 1.4));
    fill(red(c), green(c), blue(c), a);
    let wobbleX = 1 + 0.22 * sin(u * PI);
    let wobbleY = 1 + 0.38 * cos(u * PI * 0.75 + 0.3);
    ellipse(cx, cy, r * wobbleX * 2, r * wobbleY * 2.4);
  }

  // Inner soft core
  for (let i = 0; i < 60; i++) {
    let u = i / 59;
    let r = lerp(width * 0.26, width * 0.02, u);
    let c = gradList([color('#fff2de'), color('#ffd4ba'), color('#ffb79c')], u);
    let a = 50 * (1 - u);
    fill(red(c), green(c), blue(c), a);
    ellipse(cx, cy, r * 1.4, r * 1.2);
  }
  pop();
}

function sideGlows(cx, cy) {
  push();
  blendMode(SCREEN);
  noStroke();
  let offsets = [
    {x: -160, y: -120, scale: 0.72},
    {x: +160, y: -100, scale: 0.72}
  ];
  let cools = [color('#6bdde6'), color('#8fe8ff'), color('#b7eaff')];
  for (let k = 0; k < offsets.length; k++) {
    let ox = cx + offsets[k].x;
    let oy = cy + offsets[k].y;
    let s = offsets[k].scale;
    for (let i = 0; i < 70; i++) {
      let u = i / 69;
      let r = lerp(width * 0.28 * s, width * 0.02 * s, u);
      let c = gradList(cools, 1 - pow(u, 1.2));
      fill(red(c), green(c), blue(c), 28 * (1 - u));
      ellipse(ox, oy, r * 1.35, r);
    }
  }
  pop();
}

// ---------- Petals as luminous arcs ----------
function petals(cx, cy) {
  push();
  strokeCap(ROUND);
  strokeJoin(ROUND);
  blendMode(OVERLAY);

  let N = 44;
  let baseD = min(width, height) * 0.95;

  for (let p = 0; p < N; p++) {
    let ang = (p / N) * TWO_PI;
    let span = 0.65 + 0.55 * pow(noise(100 + p * 0.12), 1.5);
    let dx = baseD * (0.54 + 0.26 * sin(ang * 1.7 + 0.8));
    let dy = baseD * (0.32 + 0.30 * cos(ang * 1.3 - 0.4));

    // Color drift: cool at edges, warm across the center
    let tcol = 0.5 + 0.5 * sin(ang * 2.0 - HALF_PI) * 0.9;
    tcol = constrain(tcol, 0, 1);
    let cA = color('#6bdde6');
    let cB = color('#ffb36b');
    let c = lerpColor(cA, cB, tcol);

    for (let j = 0; j < 3; j++) {
      let w = 60 - j * 16 + 10 * noise(200 + p * 0.11 + j);
      stroke(red(c), green(c), blue(c), 38 - j * 10);
      strokeWeight(w);
      let off = (j - 1) * 0.07;
      arc(cx, cy, dx * (1 + off), dy * (1 + off), ang - span * 0.5, ang + span * 0.5);
    }
  }
  pop();
}

// ---------- Flow field threads ----------
function flowThreads(cx, cy) {
  push();
  blendMode(BLEND);
  strokeCap(ROUND);

  let particles = 5200;
  let steps = 140;
  let sMin = 1.5, sMax = 2.8;
  let maxR = max(width, height) * 0.65;
  let cool = color('#78e3ff');
  let warm = color('#ffb36b');

  for (let i = 0; i < particles; i++) {
    let pos = seededStart(cx, cy);
    let x = pos.x;
    let y = pos.y;
    let px = x, py = y;

    let stepLen = lerp(sMin, sMax, random(0.9));
    for (let k = 0; k < steps; k++) {
      let v = fieldDir(x, y, cx, cy);
      let r = dist(x, y, cx, cy);
      let rn = constrain(r / maxR, 0, 1);
      let tcol = 1 - pow(rn, 0.65);
      let c = lerpColor(cool, warm, tcol);
      let alpha = 12 + 28 * pow(1 - rn, 2.0);
      let sw = 0.7 + 0.9 * pow(1 - rn, 2.5);
      strokeWeight(sw);
      stroke(red(c), green(c), blue(c), alpha);
      let nx = x + v.x * stepLen;
      let ny = y + v.y * stepLen;

      line(px, py, nx, ny);
      // Mirror across vertical axis
      let mpx = width - px;
      let mnx = width - nx;
      line(mpx, py, mnx, ny);

      px = nx; py = ny;
      x = nx; y = ny;

      if (x < -20 || x > width + 20 || y < -20 || y > height + 20) break;
    }
  }
  pop();
}

function seededStart(cx, cy) {
  // Mix of near-center and wide starts
  if (random() < 0.68) {
    let r = abs(randomGaussian()) * 280 + 40;
    let a = random(TWO_PI);
    return { x: cx + cos(a) * r, y: cy + sin(a) * r };
  } else {
    return { x: random(width), y: random(height) };
  }
}

function fieldDir(x, y, cx, cy) {
  let dx = x - cx;
  let dy = y - cy;
  let r = sqrt(dx * dx + dy * dy) + 0.0001;

  // Noise orientation
  let s = 0.0023;
  let na = noise(x * s, y * s) * TWO_PI * 2.5;

  let nx = cos(na);
  let ny = sin(na);

  // Swirl around center
  let sx = -dy / r;
  let sy = dx / r;

  // Gentle pull toward center
  let ax = -dx / r;
  let ay = -dy / r;

  // Weights vary with radius to tighten near the center
  let rn = constrain(r / (max(width, height) * 0.65), 0, 1);
  let kSwirl = 1.65 * (0.5 + 0.5 * (1 - rn));
  let kNoise = 0.9;
  let kAttract = 0.22 + 0.3 * (1 - rn);

  let vx = nx * kNoise + sx * kSwirl + ax * kAttract;
  let vy = ny * kNoise + sy * kSwirl + ay * kAttract;

  let m = sqrt(vx * vx + vy * vy) + 1e-6;
  return { x: vx / m, y: vy / m };
}

// ---------- Golden seams (repairs) ----------
function goldenSeams(cx, cy) {
  push();
  blendMode(ADD);
  strokeCap(ROUND);
  let paths = 14;
  for (let i = 0; i < paths; i++) {
    let r0 = 120 + random(360);
    let a0 = random(TWO_PI);
    let x = cx + cos(a0) * r0 * (0.9 + 0.2 * random());
    let y = cy + sin(a0) * r0 * (0.9 + 0.2 * random());
    let segs = 60 + floor(random(40));
    let w0 = 1.2 + random(2.6);
    let gold = color('#ffd77e');
    let ember = color('#ffb85c');

    let px = x, py = y;
    for (let k = 0; k < segs; k++) {
      let g = goldenField(x, y, cx, cy);
      let step = 2.0 + 0.8 * noise(700 + i * 0.2 + k * 0.13);
      let nx = x + g.x * step;
      let ny = y + g.y * step;

      let t = k / (segs - 1);
      let c = lerpColor(ember, gold, 0.4 + 0.6 * t);
      let a = 75 * (1 - pow(1 - t, 2.0));
      stroke(red(c), green(c), blue(c), a);
      strokeWeight(w0 * (0.8 + 0.6 * sin(t * PI)));
      line(px, py, nx, ny);

      // Mirror seam
      line(width - px, py, width - nx, ny);

      px = nx; py = ny;
      x = nx; y = ny;

      if (x < -30 || x > width + 30 || y < -30 || y > height + 30) break;
    }
  }
  pop();
}

function goldenField(x, y, cx, cy) {
  let dx = x - cx;
  let dy = y - cy;
  let r = sqrt(dx * dx + dy * dy) + 0.0001;

  let s = 0.004;
  let base = noise(x * s, y * s) * TWO_PI * 6.0;
  let vx = cos(base);
  let vy = sin(base);

  // Bias to curve along the swirl and slightly inward
  let sx = -dy / r;
  let sy = dx / r;
  let ax = -dx / r * 0.2;
  let ay = -dy / r * 0.2;

  vx = vx * 0.5 + sx * 0.6 + ax * 0.2;
  vy = vy * 0.5 + sy * 0.6 + ay * 0.2;

  let m = sqrt(vx * vx + vy * vy) + 1e-6;
  return { x: vx / m, y: vy / m };
}

// ---------- Bokeh orbs ----------
function bokehOrbs(cx, cy) {
  push();
  noStroke();
  blendMode(SCREEN);

  let warms = [color('#ffd6b5'), color('#ffb790'), color('#ff9b7a'), color('#ff8aa1')];
  let cools = [color('#86e7ff'), color('#b1f1ff'), color('#cddfff')];

  let n = 160;
  for (let i = 0; i < n; i++) {
    let rr = random(18, 42) * (random() < 0.75 ? 1 : 1.6);
    let a = random(TWO_PI);
    let r = (random() < 0.8) ? random(40, 360) : random(360, 620);
    let x = cx + cos(a) * r + random(-12, 12);
    let y = cy + sin(a) * r + random(-12, 12);

    let t = 0.5 + 0.5 * sin(a * 2.0);
    let c1 = gradList(warms, t);
    let c2 = gradList(cools, 1 - t);
    let c = lerpColor(c2, c1, 0.65);

    for (let k = 0; k < 3; k++) {
      let u = k / 2;
      let alpha = 22 - k * 7;
      fill(red(c), green(c), blue(c), alpha);
      ellipse(x, y, rr * (1 - u * 0.35), rr * (1 - u * 0.35));
      // Mirror
      ellipse(width - x, y, rr * (1 - u * 0.35), rr * (1 - u * 0.35));
    }
  }
  pop();
}

// ---------- Utilities ----------
function gradList(list, t) {
  t = constrain(t, 0, 1);
  if (list.length === 1) return list[0];
  let seg = 1 / (list.length - 1);
  let i = floor(t / seg);
  let f = (t - i * seg) / seg;
  if (i >= list.length - 1) return list[list.length - 1];
  return lerpColor(list[i], list[i + 1], f);
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  colorMode(RGB, 255, 255, 255, 255);
}

function draw() {
  let W = width, H = height;
  background(11, 15, 30);

  // Background glows
  push();
  noStroke();
  blendMode(SCREEN);
  drawGlow(W * 0.33, H * 0.52, 1200, color(255, 120, 90), 90);
  drawGlow(W * 0.67, H * 0.52, 1200, color(120, 160, 255), 90);
  drawGlow(W * 0.50, H * 0.52, 900, color(255, 230, 180), 90);
  pop();

  // Subtle bond web behind main weave
  drawBondWeb(W, H, 260);

  // Pulse rings
  drawPulseRings(W, H);

  // Intertwining weave
  push();
  blendMode(SCREEN);
  drawWeave(W, H);
  pop();

  // Central soft glow to unify crossings
  push();
  blendMode(SCREEN);
  drawGlow(W * 0.5, H * 0.52, 520, color(255, 240, 210), 70);
  pop();

  // Speckles
  drawSpecks(W, H, 800);
}

// --------- Helpers ---------
function drawGlow(x, y, r, col, layers) {
  noStroke();
  for (let i = layers; i >= 1; i--) {
    let t = i / layers;
    let rr = r * t;
    let a = 3 + 140 * pow(1 - t, 2.2);
    let c = color(red(col), green(col), blue(col), a);
    fill(c);
    ellipse(x, y, rr, rr);
  }
}

function paletteLerp(cols, t) {
  t = constrain(t, 0, 0.999999);
  let n = cols.length - 1;
  let f = t * n;
  let i = floor(f);
  let tt = f - i;
  return lerpColor(cols[i], cols[i + 1], tt);
}

function drawWeave(W, H) {
  let N = 72;
  let steps = 150;
  let stepLen = 7.0;

  let warm = [color(255, 106, 128), color(255, 167, 108), color(255, 234, 170)];
  let cool = [color(96, 230, 220), color(114, 142, 255), color(184, 132, 255)];

  for (let i = 0; i < N; i++) {
    let t = i / (N - 1);

    // Left stream
    {
      let sy = H * 0.22 + t * H * 0.56 + map(noise(i * 0.15), 0, 1, -60, 60);
      let sx = -120 + map(noise(100 + i * 0.15), 0, 1, -50, 200);
      let target = createVector(
        W * 0.5 + map(noise(200 + i * 0.12), 0, 1, -60, 60),
        H * 0.5 + map(noise(300 + i * 0.12), 0, 1, -140, 140)
      );
      drawPathSegments(createVector(sx, sy), target, steps, stepLen, warm, i * 0.77 + 0.13);
    }
    // Right stream
    {
      let sy2 = H * 0.22 + (1 - t) * H * 0.56 + map(noise(400 + i * 0.15), 0, 1, -60, 60);
      let sx2 = W + 120 - map(noise(500 + i * 0.15), 0, 1, -50, 200);
      let target2 = createVector(
        W * 0.5 + map(noise(600 + i * 0.12), 0, 1, -60, 60),
        H * 0.5 + map(noise(700 + i * 0.12), 0, 1, -140, 140)
      );
      drawPathSegments(createVector(sx2, sy2), target2, steps, stepLen, cool, 1000 + i * 0.91);
    }
  }

  // Gentle arcs hinting at crossings around the center
  for (let k = 0; k < 80; k++) {
    let ang = random(TAU);
    let r = 260 + random(-120, 120);
    let a1 = ang - random(0.1, 0.6), a2 = ang + random(0.1, 0.6);
    let p1 = createVector(W * 0.5 + cos(a1) * r, H * 0.5 + sin(a1) * r);
    let p2 = createVector(W * 0.5 + cos(a2) * r, H * 0.5 + sin(a2) * r);
    stroke(255, 210, 220, 18);
    strokeWeight(random(0.6, 1.4));
    noFill();
    bezier(p1.x, p1.y, W * 0.5, H * 0.5, W * 0.5, H * 0.5, p2.x, p2.y);
  }
}

function drawPathSegments(start, target, steps, stepLen, palette, seed) {
  let pos = start.copy();
  let center = createVector(width * 0.5, height * 0.5);

  for (let s = 0; s < steps; s++) {
    let to = p5.Vector.sub(target, pos);
    let d = to.mag();
    let toVec = to.copy().setMag(map(d, 0, 900, 0.4, 2.5, true));

    let ang = noise(pos.x * 0.0012, pos.y * 0.0012, seed * 0.07 + s * 0.01) * TAU * 2.0;
    let flow = p5.Vector.fromAngle(ang).mult(1.4 + 0.6 * sin(s * 0.07 + seed));

    let cp = p5.Vector.sub(pos, center);
    let swirl = createVector(-cp.y, cp.x);
    let swirlMag = 0.6 * (1.0 / (0.5 + cp.mag() / 500));
    swirl.setMag(swirlMag);

    let vel = p5.Vector.add(toVec, flow).add(swirl).limit(stepLen);
    let next = p5.Vector.add(pos, vel);

    let u = s / steps;
    let c = paletteLerp(palette, u);
    let glow = pow(1 - abs(0.5 - u) * 2, 1.6);
    c.setAlpha(18 + 70 * glow);
    stroke(c);
    strokeWeight(0.7 + 2.1 * pow(glow, 1.5));
    line(pos.x, pos.y, next.x, next.y);

    pos = next;
  }
}

function drawBondWeb(W, H, n) {
  let nodes = [];
  for (let i = 0; i < n; i++) {
    let a = random(TAU);
    let rr = constrain(220 + randomGaussian() * 140, 80, 520);
    let x = W * 0.5 + cos(a) * rr + map(noise(800 + i * 0.11), 0, 1, -24, 24);
    let y = H * 0.5 + sin(a) * rr + map(noise(900 + i * 0.11), 0, 1, -24, 24);
    nodes.push(createVector(x, y));
  }

  for (let i = 0; i < n; i++) {
    let choices = [];
    for (let k = 0; k < 20; k++) {
      let j = floor(random(n));
      if (j === i) continue;
      let d = p5.Vector.dist(nodes[i], nodes[j]);
      choices.push({ j, d });
    }
    choices.sort((a, b) => a.d - b.d);
    let m = 3;
    for (let c = 0; c < m && c < choices.length; c++) {
      let j = choices[c].j;
      let d = choices[c].d;
      let a = map(d, 0, 240, 70, 6, true);
      stroke(255, 210, 220, a);
      strokeWeight(map(d, 0, 240, 1.1, 0.3, true));
      line(nodes[i].x, nodes[i].y, nodes[j].x, nodes[j].y);
    }
  }
}

function drawPulseRings(W, H) {
  let bases = [170, 270, 370];
  for (let b = 0; b < bases.length; b++) {
    let base = bases[b];
    noFill();
    stroke(255, 210 - b * 20, 170 + b * 10, 26);
    strokeWeight(1.2 + (b === 0 ? 0.6 : 0));
    beginShape();
    let seg = 260;
    for (let a = 0; a <= seg; a++) {
      let th = a / seg * TAU;
      let r = base + 18 * noise(50 + cos(th) * 0.8 + b * 2, 50 + sin(th) * 0.8 + b * 2, b * 0.2) - 9;
      let x = W * 0.5 + cos(th) * r;
      let y = H * 0.5 + sin(th) * r;
      curveVertex(x, y);
    }
    endShape(CLOSE);
  }
}

function drawSpecks(W, H, count) {
  push();
  blendMode(SCREEN);
  noStroke();
  for (let i = 0; i < count; i++) {
    let rr = pow(random(), 1.8) * 780;
    let ang = random(TAU);
    let x = W * 0.5 + cos(ang) * rr + random(-1.5, 1.5);
    let y = H * 0.5 + sin(ang) * rr + random(-1.5, 1.5);
    let sz = random(0.8, 2.8);

    let c1 = color(255, 200, 220);
    let c2 = color(200, 220, 255);
    let c = lerpColor(c1, c2, random());
    let a = random(20, 90);
    c.setAlpha(a);
    fill(c);
    ellipse(x, y, sz, sz);

    fill(red(c), green(c), blue(c), a * 0.2);
    ellipse(x, y, sz * 3.0, sz * 3.0);
  }
  pop();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();
  noStroke();

  let cx = width * 0.5;
  let cy = height * 0.6;

  // Background vertical gradient
  drawVerticalGradient(
    color(260, 38, 10, 100),
    color(270, 35, 3, 100)
  );

  // Subtle vignetting
  vignette(0.85, 0.9);

  // Radial golden glow at the heart
  radialGlow(cx, cy, 540, 720);

  // Soft ambient cool halos to temper the warmth
  coolHalos(cx, cy, 880, 8);

  // Interlaced translucent ribbons from left and right
  drawRibbons(cx, cy, -1, 120); // warm side
  drawRibbons(cx, cy,  1, 120); // cool side

  // Flowing swarms weaving toward the shared center
  drawSwarms(cx, cy, -1, 1200); // warm currents
  drawSwarms(cx, cy,  1, 1200); // cool currents

  // Permeable protective rings
  drawRings(cx, cy, 10);

  // Inner scintillae
  sparkles(cx, cy, 700);
}

function drawVerticalGradient(cTop, cBot) {
  for (let y = 0; y < height; y++) {
    let t = y / (height - 1);
    stroke(lerpColor(cTop, cBot, t));
    line(0, y, width, y);
  }
  noStroke();
}

function vignette(inner = 0.9, falloff = 0.85) {
  push();
  blendMode(MULTIPLY);
  noStroke();
  let maxR = dist(0, 0, width * 0.5, height * 0.5) * 1.4;
  for (let i = 0; i < 200; i++) {
    let t = i / 199.0;
    let r = lerp(maxR * inner, maxR, t);
    let a = map(t, 0, 1, 0, 38) * pow(t, 1.5);
    fill(260, 40, 5, a);
    ellipse(width * 0.5, height * 0.5, r * 2, r * 2);
  }
  pop();
}

function radialGlow(cx, cy, r, layers) {
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < layers; i++) {
    let t = i / (layers - 1);
    let tt = 1 - t;
    let rad = lerp(r, 8, t);
    let jitter = (1 - t) * 10;
    let x = cx + random(-jitter, jitter);
    let y = cy + random(-jitter, jitter);
    // Warm white core to amber edge
    let h = 32 + 18 * tt;    // 32..50
    let s = 70 - 60 * tt;    // 70..10
    let b = 35 + 65 * tt;    // 35..100
    let a = 5 + 12 * tt;     // 5..17
    fill(h, s, b, a);
    ellipse(x, y, rad * 2, rad * 2);
  }
  pop();
}

function coolHalos(cx, cy, r, count) {
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < count; i++) {
    let rr = r * random(0.65, 1.0);
    let wob = random(-40, 40);
    let h = random(200, 230);
    let s = random(20, 40);
    let b = random(12, 30);
    let a = random(6, 16);
    fill(h, s, b, a);
    ellipse(cx + random(-20, 20), cy + random(-20, 20), (rr + wob) * 2, (rr - wob * 0.7) * 2);
  }
  pop();
}

function drawRibbons(cx, cy, side, count) {
  push();
  noFill();
  for (let i = 0; i < count; i++) {
    let x0 = side < 0 ? -random(20, 160) : width + random(20, 160);
    let y0 = random(height * 0.45, height * 0.95);

    let x1 = lerp(x0, cx, random(0.18, 0.4)) + side * random(60, 240);
    let y1 = lerp(y0, cy, random(0.1, 0.5)) - random(80, 280);

    let x2 = lerp(x0, cx, random(0.55, 0.92)) - side * random(20, 220);
    let y2 = lerp(y0, cy, random(0.5, 1.0)) + random(-160, 160);

    let x3 = cx + random(-140, 140);
    let y3 = cy + random(-140, 140);

    let w = random(0.7, 3.2);
    strokeWeight(w);

    let c = side < 0 ? warmCol(random(), 18) : coolCol(random(), 18);
    stroke(c);

    bezier(x0, y0, x1, y1, x2, y2, x3, y3);

    // Soft twin for body
    strokeWeight(w * 0.55);
    let c2 = side < 0 ? warmCol(random(), 10) : coolCol(random(), 10);
    stroke(c2);
    bezier(x0 + random(-2, 2), y0 + random(-2, 2),
           x1 + random(-3, 3), y1 + random(-3, 3),
           x2 + random(-3, 3), y2 + random(-3, 3),
           x3 + random(-2, 2), y3 + random(-2, 2));
  }
  pop();
}

function drawSwarms(cx, cy, side, n) {
  push();
  let colTo = color(44, 12, 100, 26); // luminous near-center
  let scale = 0.00155;
  for (let i = 0; i < n; i++) {
    let x = side < 0 ? random(-50, 180) : width - random(-50, 180);
    let y = random(height * 0.25, height * 0.95);
    let prevX = x;
    let prevY = y;

    let life = floor(random(130, 190));
    let sw = random(0.6, 1.6);
    let colFrom = side < 0 ? warmCol(random(), random(14, 28)) : coolCol(random(), random(14, 28));

    for (let s = 0; s < life; s++) {
      let ang = fieldAngle(x, y, cx, cy, scale);
      let sp = 1.0 + 0.9 * noise(x * 0.004 + i * 0.01, y * 0.004 - i * 0.013);
      x += Math.cos(ang) * sp;
      y += Math.sin(ang) * sp;

      let d = dist(x, y, cx, cy);
      let t = constrain(map(d, 800, 80, 0, 1), 0, 1);
      let tt = pow(t, 0.6);
      let c = lerpColor(colFrom, colTo, tt);

      stroke(c);
      strokeWeight(sw * (0.9 + 0.2 * tt));
      line(prevX, prevY, x, y);

      prevX = x;
      prevY = y;

      if (x < -200 || x > width + 200 || y < -200 || y > height + 200) break;
    }
  }
  pop();
}

function fieldAngle(x, y, cx, cy, sc) {
  let aR = Math.atan2(cy - y, cx - x); // radial toward center
  let tan = aR + HALF_PI;              // tangential
  let d = dist(x, y, cx, cy);
  let orbitBias = constrain(map(d, 1200, 120, 0.1, 0.7), 0.1, 0.7);

  let swirl = (noise(x * sc, y * sc) - 0.5) * PI * 0.9;

  let a = blendAngles(aR, tan, orbitBias) + swirl;
  return a;
}

function blendAngles(a, b, w) {
  let v1 = p5.Vector.fromAngle(a);
  let v2 = p5.Vector.fromAngle(b);
  let v = p5.Vector.lerp(v1, v2, w);
  return v.heading();
}

function drawRings(cx, cy, count) {
  push();
  translate(cx, cy);
  for (let i = 0; i < count; i++) {
    push();
    let t = i / max(1, (count - 1));
    let base = lerp(140, 700, t);
    let rx = base * random(0.94, 1.08);
    let ry = base * random(0.82, 1.12);
    rotate(random(-0.08, 0.08));

    noFill();
    let h = 260 + random(-8, 12);
    let s = random(6, 16);
    let b = random(36, 62);
    let a = 8 + (1 - t) * 10;
    stroke(h, s, b, a);
    strokeWeight(0.9 + (1 - t) * 0.6);

    beginShape();
    for (let a0 = 0; a0 < TWO_PI + 0.03; a0 += 0.03) {
      let nx = Math.cos(a0) * 3 + i * 0.31;
      let ny = Math.sin(a0) * 3 - i * 0.17;
      let wob = (noise(nx, ny) - 0.5) * 18 * pow(1 - t, 0.8);
      let x = (rx + wob) * Math.cos(a0);
      let y = (ry + wob) * Math.sin(a0);
      curveVertex(x, y);
    }
    endShape(CLOSE);
    pop();
  }
  pop();
}

function sparkles(cx, cy, n) {
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < n; i++) {
    let r = random(2, 260);
    let ang = random(TWO_PI);
    let x = cx + Math.cos(ang) * r * random(0.9, 1.05);
    let y = cy + Math.sin(ang) * r * random(0.9, 1.05);
    let sz = random(0.8, 3.2) * map(r, 0, 260, 2.2, 0.6);
    let a = random(18, 40) * map(r, 0, 260, 1.0, 0.25);
    fill(46, random(8, 22), 100, a);
    ellipse(x, y, sz, sz);
  }
  pop();
}

function warmCol(t, a=20) {
  // Amber to soft gold
  let h = 14 + 18 * t;
  let s = 55 + 35 * (1 - t * 0.7);
  let b = 70 + 28 * t;
  return color(h, s, b, a);
}

function coolCol(t, a=20) {
  // Indigo to teal
  let h = 205 + 25 * t;
  let s = 40 + 30 * (1 - t * 0.4);
  let b = 65 + 30 * t;
  return color(h, s, b, a);
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  colorMode(RGB, 255, 255, 255, 255);

  drawScene();
}

let leftC, rightC, centerC;
let bgTop, bgBottom;
let colWarm, colCool, colLight, colWarmDeep, colCoolDeep;

function drawScene() {
  // palette
  bgTop = color(16, 12, 32);
  bgBottom = color(6, 6, 14);
  colWarm = color(255, 120, 140, 90);
  colCool = color(70, 210, 205, 90);
  colLight = color(255, 238, 220, 110);
  colWarmDeep = color(255, 80, 110, 80);
  colCoolDeep = color(60, 160, 220, 80);

  leftC = createVector(width * 0.37, height * 0.53);
  rightC = createVector(width * 0.63, height * 0.55);
  centerC = p5.Vector.lerp(leftC, rightC, 0.5);

  drawBackgroundGradient(bgTop, bgBottom);
  drawVignette();

  push();
  blendMode(SCREEN);
  drawOrb(leftC.x, leftC.y, 420, colWarm, 90, 0.10);
  drawOrb(rightC.x, rightC.y, 400, colCool, 90, 0.10);
  drawOrb(centerC.x, centerC.y, 260, colLight, 110, 0.06);
  pop();

  push();
  blendMode(SCREEN);
  drawThreads(leftC, rightC, 340, 330, colWarm, colCool);
  pop();

  drawFlow(centerC, 1500);

  push();
  blendMode(SCREEN);
  drawEmbers(180, centerC, 520);
  pop();

  // a quiet, softening veil to unify
  softVeil(centerC, 600, color(255, 230, 220, 14), 18);
}

function drawBackgroundGradient(c1, c2) {
  noStroke();
  for (let y = 0; y < height; y++) {
    let t = y / (height - 1);
    let c = lerpColor(c1, c2, t);
    stroke(c);
    line(0, y, width, y);
  }
  // subtle diagonal warmth/cool glow
  push();
  blendMode(SCREEN);
  noStroke();
  let gWarm = color(80, 30, 40, 20);
  let gCool = color(30, 50, 70, 20);
  radialGlow(width * 0.28, height * 0.35, 780, gCool, 160);
  radialGlow(width * 0.72, height * 0.75, 860, gWarm, 160);
  pop();
}

function drawVignette() {
  // darken edges for focus
  push();
  noStroke();
  for (let i = 0; i < 160; i++) {
    let t = i / 159;
    let a = pow(t, 2.2) * 70;
    fill(0, 0, 0, a);
    rectMode(CENTER);
    let w = lerp(width, width * 1.12, t);
    let h = lerp(height, height * 1.12, t);
    rect(width / 2, height / 2, w, h);
  }
  pop();
}

function radialGlow(cx, cy, r, colr, layers) {
  noStroke();
  for (let i = 0; i < layers; i++) {
    let t = i / (layers - 1);
    let a = alpha(colr) * (1 - t) * 0.12;
    let cc = color(red(colr), green(colr), blue(colr), a);
    fill(cc);
    let rr = r * (0.2 + 0.8 * (1 - t));
    ellipse(cx, cy, rr * 2, rr * 2);
  }
}

function drawOrb(cx, cy, baseR, colr, layers, turb) {
  noStroke();
  for (let i = 0; i < layers; i++) {
    let t = i / (layers - 1);
    let r = baseR * (1 - 0.36 * t);
    let a = map(i, 0, layers - 1, alpha(colr), 2);
    let c = color(red(colr), green(colr), blue(colr), a);
    fill(c);

    beginShape();
    let step = 0.2;
    for (let ang = 0; ang < TWO_PI + 0.0001; ang += step) {
      let nx = (cos(ang) * 0.5 + 0.5) * 1.2 + i * 0.03 + cx * 0.00013;
      let ny = (sin(ang) * 0.5 + 0.5) * 1.2 + i * 0.03 + cy * 0.00013;
      let n = noise(nx, ny);
      let rr = r * (1 + (n - 0.5) * 2 * turb * (1 - t));
      let x = cx + rr * cos(ang);
      let y = cy + rr * sin(ang);
      curveVertex(x, y);
    }
    endShape(CLOSE);
  }
}

function drawThreads(L, R, rL, rR, warm, cool) {
  let dirLR = atan2(R.y - L.y, R.x - L.x);
  let dirRL = atan2(L.y - R.y, L.x - R.x);
  let count = 92;

  for (let k = 0; k < count; k++) {
    let u = (k + 0.5) / count;
    let jitter = (noise(k * 0.21 + 4) - 0.5) * 0.5;
    let angL = dirLR + map(u, 0, 1, -PI / 2, PI / 2) + jitter;
    let angR = dirRL + map(1 - u, 0, 1, -PI / 2, PI / 2) - jitter * 0.7;

    let pL = createVector(L.x + rL * cos(angL), L.y + rL * sin(angL));
    let pR = createVector(R.x + rR * cos(angR), R.y + rR * sin(angR));

    let vx = pR.x - pL.x;
    let vy = pR.y - pL.y;
    let d = Math.max(1, sqrt(vx * vx + vy * vy));
    let ndx = vx / d, ndy = vy / d;
    let nx = -ndy, ny = ndx;

    let bend = (noise(k * 0.15 + 10) - 0.5) * d * 0.6;
    let c1x = pL.x + ndx * d * 0.28 + nx * bend * 0.40;
    let c1y = pL.y + ndy * d * 0.28 + ny * bend * 0.40;
    let c2x = pR.x - ndx * d * 0.28 + nx * bend * -0.38;
    let c2y = pR.y - ndy * d * 0.28 + ny * bend * -0.38;

    let sw = map(abs(u - 0.5), 0, 0.5, 2.2, 0.9);

    // draw as short segments with gradient color
    let segs = 70;
    for (let i = 0; i < segs; i++) {
      let t1 = i / segs;
      let t2 = (i + 1) / segs;
      let x1 = bezierPoint(pL.x, c1x, c2x, pR.x, t1);
      let y1 = bezierPoint(pL.y, c1y, c2y, pR.y, t1);
      let x2 = bezierPoint(pL.x, c1x, c2x, pR.x, t2);
      let y2 = bezierPoint(pL.y, c1y, c2y, pR.y, t2);

      // avoid drawing inside the innermost calm
      if (dist((x1 + x2) * 0.5, (y1 + y2) * 0.5, centerC.x, centerC.y) < 150) continue;

      let mix = constrain((x1 - L.x) / (R.x - L.x), 0, 1);
      let aWarm = color(red(warm), green(warm), blue(warm), 80);
      let aCool = color(red(cool), green(cool), blue(cool), 80);
      let cc = lerpColor(aWarm, aCool, mix);

      stroke(cc);
      strokeWeight(sw);
      line(x1, y1, x2, y2);
    }
  }
}

function drawFlow(center, seeds) {
  let leftX = leftC.x;
  let rightX = rightC.x;

  for (let s = 0; s < seeds; s++) {
    let x = random(width * 0.12, width * 0.88);
    let y = random(height * 0.18, height * 0.86);

    // slight bias toward the corridor between centers
    let corridor = map(abs((x - (leftX + rightX) * 0.5)) / (rightX - leftX), 0, 0.5, 1, 0.2);
    if (random() > corridor) continue;

    let steps = 110;
    let stepLen = 4;
    let px = x, py = y;

    for (let i = 0; i < steps; i++) {
      let ang = noise(px * 0.0021, py * 0.0021) * TWO_PI * 2.4;
      let toC = atan2(center.y - py, center.x - px);
      let w = 0.42;
      let a = ang * (1 - w) + toC * w;

      let nx = px + cos(a) * stepLen;
      let ny = py + sin(a) * stepLen;

      // stop near core or out of bounds
      if (dist(nx, ny, center.x, center.y) < 160) break;
      if (nx < -20 || nx > width + 20 || ny < -20 || ny > height + 20) break;

      let mix = constrain((px - leftX) / (rightX - leftX), 0, 1);
      let warmThin = color(255, 130, 150, 18);
      let coolThin = color(80, 210, 210, 18);
      let cc = lerpColor(warmThin, coolThin, mix);
      stroke(cc);
      strokeWeight(0.9);
      line(px, py, nx, ny);

      px = nx; py = ny;
    }
  }
}

function drawEmbers(n, center, radius) {
  noStroke();
  for (let i = 0; i < n; i++) {
    let ang = random(TWO_PI);
    let r = radius * sqrt(random());
    let x = center.x + cos(ang) * r + random(-40, 40);
    let y = center.y + sin(ang) * r + random(-40, 40);
    let sz = random(2, 8);

    let choose = random();
    let base;
    if (choose < 0.45) base = color(255, 180, 150, 70);
    else if (choose < 0.9) base = color(120, 220, 210, 70);
    else base = color(255, 245, 230, 90);

    for (let k = 5; k >= 1; k--) {
      let a = alpha(base) * pow(k / 5, 2);
      fill(red(base), green(base), blue(base), a * 0.5);
      ellipse(x, y, sz * k * 0.8, sz * k * 0.8);
    }
  }
}

function softVeil(center, r, colr, layers) {
  push();
  noStroke();
  for (let i = 0; i < layers; i++) {
    let t = i / (layers - 1);
    let a = alpha(colr) * (1 - t);
    fill(red(colr), green(colr), blue(colr), a);
    let rr = r * (0.2 + 0.8 * t);
    ellipse(center.x, center.y, rr * 2.0, rr * 1.72);
  }
  pop();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  colorMode(RGB, 255, 255, 255, 255);
  noStroke();
  smooth();

  // Palettes
  const cools = [
    color(18, 21, 45),
    color(35, 43, 93),
    color(47, 68, 124),
    color(63, 52, 122),
    color(38, 27, 66)
  ];
  const warms = [
    color(255, 198, 179),
    color(255, 160, 149),
    color(236, 92, 120),
    color(255, 191, 112),
    color(255, 223, 208),
    color(223, 120, 189)
  ];
  const gold = color(255, 205, 120);
  const ember = color(255, 240, 220);

  // Composition anchors (two subtle attractors)
  const a1 = createVector(width * 0.47, height * 0.56);
  const a2 = createVector(width * 0.53, height * 0.58);
  const mid = p5.Vector.add(a1, a2).mult(0.5);

  // 1) Deep twilight background gradient
  drawVerticalGradient(cools[0], cools[cools.length - 1]);

  // 2) Central radial warmth
  drawRadialBloom(mid.x, mid.y, 1050, warms[0], color(0, 0, 0, 0), 420);

  // 3) Overlapping soft circles (a luminous "between")
  push();
  blendMode(ADD);
  softCircle(a1.x, a1.y, 960, color(255, 170, 150, 16), 16);
  softCircle(a2.x, a2.y, 960, color(255, 150, 190, 14), 16);
  softCircle(mid.x, mid.y, 700, color(255, 220, 180, 24), 24);
  softCircle(mid.x, mid.y - 80, 520, color(255, 230, 210, 28), 24);
  pop();

  // 4) Flowing threads drawn by a gentle field (weave of difference)
  drawThreads(a1, a2, mid, warms, cools);

  // 5) Subtle "mends" — bright seams that accept fracture
  drawSeams(mid, gold);

  // 6) Embers in the shared space
  drawEmbers(mid, ember);

  // 7) Vignette to cradle the center
  vignette();
}

// Helpers

function drawVerticalGradient(topCol, bottomCol) {
  noStroke();
  for (let y = 0; y < height; y += 3) {
    const t = y / (height - 1);
    const c = lerpColor(topCol, bottomCol, easeInOutCubic(t));
    fill(c);
    rect(0, y, width, 3);
  }
}

function drawRadialBloom(cx, cy, r, inner, outer, layers) {
  noStroke();
  for (let i = layers; i >= 0; i--) {
    const t = i / layers;
    const c = lerpColor(inner, outer, t);
    const rr = r * (0.2 + 0.9 * t);
    fill(red(c), green(c), blue(c), 20 + 20 * (1 - t));
    ellipse(cx, cy, rr * 2, rr * 2);
  }
}

function softCircle(cx, cy, d, col, layers) {
  noStroke();
  for (let i = 0; i < layers; i++) {
    const t = i / (layers - 1);
    const alpha = map(1 - t, 0, 1, alpha(col) * 0.05, alpha(col));
    const dd = d * (0.3 + 0.7 * t + 0.02 * noise(cx * 0.001, cy * 0.001, i * 0.1));
    const c = color(red(col), green(col), blue(col), alpha);
    fill(c);
    ellipse(cx, cy, dd, dd);
  }
}

function drawThreads(a1, a2, mid, warms, cools) {
  const N = 9000;
  const steps = 34;
  const stepLen = 1.35;

  for (let i = 0; i < N; i++) {
    let start;
    if (random() < 0.74) {
      const sx = randomGaussian(mid.x, width * 0.2);
      const sy = randomGaussian(mid.y, height * 0.24);
      start = createVector(sx, sy);
    } else {
      start = createVector(random(width), random(height));
    }

    let p = start.copy();
    let prev = p.copy();

    const col = threadColor(p.x, p.y, mid, warms, cools, i);
    const sw = 0.35 + 0.95 * pow(random(), 3);
    strokeCap(ROUND);
    strokeJoin(ROUND);
    strokeWeight(sw);

    for (let s = 0; s < steps; s++) {
      const v = fieldVector(p.x, p.y, a1, a2, mid);
      p.add(v.mult(stepLen));

      if (p.x < -10 || p.x > width + 10 || p.y < -10 || p.y > height + 10) break;

      // Color modulation by proximity to the shared space
      const d = dist(p.x, p.y, mid.x, mid.y);
      const hot = constrain(1 - d / 900, 0, 1);
      const a = 20 + 85 * pow(hot, 1.6) + 10 * noise(i * 0.01 + s * 0.03);
      const cc = color(red(col), green(col), blue(col), a);
      stroke(cc);
      line(prev.x, prev.y, p.x, p.y);
      prev.set(p);
    }
  }

  // Some longer connective strands
  const bonds = 220;
  for (let k = 0; k < bonds; k++) {
    const y = randomGaussian(mid.y, height * 0.22);
    const x1 = randomGaussian(width * 0.18, width * 0.08);
    const x2 = randomGaussian(width * 0.82, width * 0.08);
    const lift = random(-140, 140);

    const c = lerpColor(
      color(255, 210, 170, 18),
      color(235, 120, 160, 18),
      0.5 + 0.5 * noise(k * 0.2)
    );
    strokeWeight(0.7 + 1.3 * random());
    stroke(c);
    noFill();

    const cx1 = lerp(x1, (x1 + x2) / 2, 0.35);
    const cx2 = lerp(x2, (x1 + x2) / 2, 0.35);
    bezier(
      x1, y + random(-30, 30),
      cx1, y - lift,
      cx2, y + lift,
      x2, y + random(-30, 30)
    );
  }
}

function fieldVector(x, y, a1, a2, mid) {
  // Noise-based flow with gentle attraction and a soft curl around the shared space
  const nx = x * 0.0008;
  const ny = y * 0.0008;
  let ang = noise(nx, ny) * TWO_PI * 2.0 + noise(nx * 0.7, ny * 0.7) * TWO_PI * 0.3;
  let v = p5.Vector.fromAngle(ang);

  const p = createVector(x, y);
  const to1 = p5.Vector.sub(a1, p);
  const to2 = p5.Vector.sub(a2, p);

  const m1 = 0.12 / (to1.mag() / 160 + 1.2);
  const m2 = 0.12 / (to2.mag() / 160 + 1.2);

  to1.normalize().mult(m1);
  to2.normalize().mult(m2);

  const d = p5.Vector.sub(p, mid);
  const swirl = createVector(-d.y, d.x);
  const sm = 0.2 / (d.mag() / 220 + 1.0);
  if (swirl.mag() > 0) swirl.setMag(sm);

  v.mult(0.9).add(to1).add(to2).add(swirl);
  if (v.mag() === 0) v.set(0.0001, 0.0001);
  return v.normalize();
}

function threadColor(x, y, mid, warms, cools, seed) {
  const d = dist(x, y, mid.x, mid.y);
  const t = constrain(d / 900, 0, 1);
  const coolMix = paletteMix(cools, noise(x * 0.001, y * 0.001, seed * 0.003));
  const warmMix = paletteMix(warms, noise(x * 0.0015 + 10, y * 0.0015 + 20, seed * 0.007));
  const mixAmt = pow(1 - t, 1.2);
  const c = lerpColor(coolMix, warmMix, mixAmt);
  return c;
}

function paletteMix(pal, tt) {
  const t = constrain(tt, 0, 1);
  const idx = t * (pal.length - 1);
  const a = floor(idx);
  const b = min(a + 1, pal.length - 1);
  const lt = idx - a;
  return lerpColor(pal[a], pal[b], lt);
}

function drawSeams(mid, gold) {
  push();
  blendMode(ADD);
  strokeCap(ROUND);
  const seams = 140;
  for (let i = 0; i < seams; i++) {
    const base = p5.Vector.add(mid, createVector(randomGaussian(0, 220), randomGaussian(0, 170)));
    const len = random(50, 220);
    const ang = random(TWO_PI);
    const p1 = p5.Vector.add(base, p5.Vector.fromAngle(ang).mult(len * 0.5));
    const p4 = p5.Vector.add(base, p5.Vector.fromAngle(ang + PI).mult(len * 0.5));

    // Slightly jagged control points to feel repaired, not pristine
    const jitter = () => random(-40, 40);
    const p2 = createVector(lerp(p1.x, base.x, 0.6) + jitter(), lerp(p1.y, base.y, 0.6) + jitter());
    const p3 = createVector(lerp(p4.x, base.x, 0.6) + jitter(), lerp(p4.y, base.y, 0.6) + jitter());

    const a = 24 + 64 * pow(constrain(1 - dist(base.x, base.y, mid.x, mid.y) / 700, 0, 1), 2);
    const c = color(red(gold), green(gold), blue(gold), a);
    stroke(c);
    strokeWeight(0.9 + 1.6 * random());
    noFill();
    bezier(p1.x, p1.y, p2.x, p2.y, p3.x, p3.y, p4.x, p4.y);
  }
  pop();
}

function drawEmbers(mid, ember) {
  push();
  blendMode(ADD);
  noStroke();
  const E = 350;
  for (let i = 0; i < E; i++) {
    const r = abs(randomGaussian(0, 260));
    const ang = random(TWO_PI);
    const p = p5.Vector.add(mid, p5.Vector.fromAngle(ang).mult(r));
    const d = dist(p.x, p.y, mid.x, mid.y);
    const hot = constrain(1 - d / 620, 0, 1);
    const a = 10 + 70 * pow(hot, 2.1) * random(0.6, 1);
    const rad = 1 + 3.5 * pow(hot, 1.6) * random(0.6, 1.2);
    fill(red(ember), green(ember), blue(ember), a);
    ellipse(p.x + random(-2, 2), p.y + random(-2, 2), rad * 2, rad * 2);
  }
  pop();
}

function vignette() {
  // Edge darkening to hold the gaze near the shared space
  push();
  noFill();
  for (let i = 0; i < 80; i++) {
    const a = map(i, 0, 79, 0, 85);
    stroke(0, 0, 0, a);
    strokeWeight(8);
    rect(-20 - i * 3, -20 - i * 3, width + (i * 3) * 2 + 40, height + (i * 3) * 2 + 40, 40);
  }
  pop();
}

function easeInOutCubic(t) {
  return t < 0.5 ? 4 * t * t * t : 1 - pow(-2 * t + 2, 3) / 2;
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  backgroundGradient();
  centerGlows();
  grain(4200);

  drawEmbrace();

  bridgeGlow();
  grain(1800);
}

function backgroundGradient() {
  let cTop = color('#0b0f1f');   // deep night blue
  let cBot = color('#140914');   // deep plum
  for (let y = 0; y < height; y++) {
    let t = y / (height - 1);
    let c = lerpColor(cTop, cBot, t);
    stroke(c);
    line(0, y, width, y);
  }

  // Subtle outer vignette using large translucent ellipses
  push();
  noStroke();
  fill(0, 26);
  ellipse(-200, -200, 900, 900);
  ellipse(width + 200, -200, 900, 900);
  ellipse(-200, height + 200, 900, 900);
  ellipse(width + 200, height + 200, 900, 900);
  pop();
}

function centerGlows() {
  push();
  blendMode(SCREEN);
  // Warm heart-center glow
  radialGlow(width * 0.5, height * 0.58, 820, color(255, 214, 165), color(255, 77, 109, 10));
  radialGlow(width * 0.52, height * 0.6, 520, color(255, 236, 220), color(255, 180, 190, 5));
  // Cool counter-glow to balance
  radialGlow(width * 0.36, height * 0.86, 540, color(78, 205, 196, 50), color(13, 59, 102, 0));
  pop();
}

function radialGlow(cx, cy, r, cInner, cOuter) {
  push();
  noStroke();
  let steps = 90;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let rr = r * (1 - t);
    let cc = lerpColor(cInner, cOuter, t);
    let a = 120 * (1 - t) * (1 - t);
    fill(red(cc), green(cc), blue(cc), a);
    ellipse(cx, cy, rr * 2, rr * 2);
  }
  pop();
}

function drawEmbrace() {
  let warm1 = color('#ff4d6d');
  let warm2 = color('#ffd6a5');
  let cool1 = color('#0d3b66');
  let cool2 = color('#4ecdc4');

  // Draw cool ribbon first (depth)
  drawRibbonLayered(pathR, cool1, cool2, 230, 60, 22, 12);

  // Draw warm ribbon on top
  drawRibbonLayered(pathL, warm1, warm2, 230, 60, 22, 12);

  // Luminous inner filaments
  push();
  blendMode(SCREEN);
  strokeCap(ROUND);

  stroke(200, 255, 245, 130);
  strokeWeight(12);
  drawPath(pathR, 0.0027);

  stroke(255, 234, 220, 170);
  strokeWeight(14);
  drawPath(pathL, 0.0027);

  // Subtle secondary filaments
  stroke(255, 255, 255, 30);
  strokeWeight(4);
  drawPath(pathL, 0.0036);
  drawPath(pathR, 0.0036);
  pop();
}

function drawRibbonLayered(func, colStart, colEnd, thickMax, thickMin, layers, jitterMag) {
  push();
  noFill();
  strokeCap(ROUND);

  // Soft underglow pass
  push();
  blendMode(SCREEN);
  let glowCol = lerpColor(colStart, colEnd, 0.55);
  stroke(red(glowCol), green(glowCol), blue(glowCol), 26);
  strokeWeight(thickMax * 1.25);
  drawPathJitter(func, 0.0036, jitterMag * 0.6, 0.2);
  pop();

  // Main body layers
  for (let i = 0; i < layers; i++) {
    let k = i / (layers - 1);
    let w = lerp(thickMax, thickMin, k);
    let cc = lerpColor(colStart, colEnd, pow(k, 0.7));
    let a = 220 - k * 160;
    stroke(red(cc), green(cc), blue(cc), a);
    strokeWeight(w);
    drawPathJitter(func, 0.0035, jitterMag * (1 - k), 0.0);
  }
  pop();
}

function drawPathJitter(func, step, jitter, breathe) {
  beginShape();
  for (let t = 0; t <= 1; t += step) {
    let p = func(t);
    let n = normalAt(func, t);
    let j = (noise(t * 10 + 7) - 0.5) * 2 * jitter;
    let bx = (noise(t * 2 + 100) - 0.5) * breathe * 10.0;
    let by = (noise(t * 2 + 200) - 0.5) * breathe * 10.0;
    curveVertex(p.x + n.x * j + bx, p.y + n.y * j + by);
  }
  endShape();
}

function drawPath(func, step) {
  beginShape();
  // Duplicate endpoints for smoother curveVertex handling
  let p0 = func(0);
  curveVertex(p0.x, p0.y);
  for (let t = 0; t <= 1; t += step) {
    let p = func(t);
    curveVertex(p.x, p.y);
  }
  let p1 = func(1);
  curveVertex(p1.x, p1.y);
  endShape();
}

function pathL(t) {
  let y = lerp(520, 1680, t) + 30 * sin(TWO_PI * t * 1.10);
  let x = width * 0.5 - 360 + 240 * sin(PI * t) - 40 * noise(6 * t + 10);
  return createVector(x, y);
}

function pathR(t) {
  let y = lerp(500, 1660, t) + 30 * sin(TWO_PI * t * 1.05 + 1.0);
  let x = width * 0.5 + 360 - 240 * sin(PI * t) + 40 * noise(6 * t + 110);
  return createVector(x, y);
}

function normalAt(func, t) {
  let eps = 0.001;
  let t1 = constrain(t - eps, 0, 1);
  let t2 = constrain(t + eps, 0, 1);
  let p1 = func(t1);
  let p2 = func(t2);
  let v = createVector(p2.x - p1.x, p2.y - p1.y);
  if (v.mag() < 1e-6) v = createVector(1, 0);
  v.normalize();
  return createVector(-v.y, v.x);
}

function bridgeGlow() {
  push();
  blendMode(SCREEN);
  noStroke();

  let L = pathL(0.5);
  let R = pathR(0.5);

  for (let s = 0; s <= 1; s += 0.05) {
    let base = p5.Vector.lerp(L, R, s);
    let offY = sin(PI * s) * 60;
    let px = base.x + (noise(s * 3 + 20) - 0.5) * 22;
    let py = base.y - offY + (noise(s * 5 + 40) - 0.5) * 22;

    let t = abs(0.5 - s);
    let rad = 180 * (1 - t * 1.1);
    let cMix = lerpColor(color('#ffd6a5'), color('#d1fff2'), s);

    fill(red(cMix), green(cMix), blue(cMix), 40);
    ellipse(px, py, rad, rad);

    fill(255, 245, 235, 18);
    ellipse(px, py, rad * 0.6, rad * 0.6);
  }
  pop();
}

function grain(count) {
  push();
  noStroke();
  for (let i = 0; i < count; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.002, y * 0.002);
    let a = map(n, 0, 1, 4, 18);
    let pick = n + noise(x * 0.004 + 5, y * 0.004 + 5) - 1;
    let c1 = color(255, 230, 220, a);
    let c2 = color(160, 220, 215, a * 0.7);
    let cc = (pick > 0) ? c1 : c2;
    fill(cc);
    let r = random(0.4, 1.7);
    ellipse(x, y, r, r);
  }
  pop();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  backgroundGradient();
  glazeClouds();
  centralGlow(width * 0.5, height * 0.55, 600, color(255, 230, 210), 140);
  drawRibbons();
  drawConnectingThreads();
  scatterDust(1200);
  vignette(220);
}

// Background vertical gradient: blush -> apricot -> deep violet
function backgroundGradient() {
  noStroke();
  for (let y = 0; y < height; y++) {
    let t = y / (height - 1);
    let cTop = color(252, 232, 227);
    let cMid = color(255, 192, 150);
    let cBot = color(38, 22, 54);
    let c;
    if (t < 0.55) {
      c = lerpColor(cTop, cMid, t / 0.55);
    } else {
      c = lerpColor(cMid, cBot, (t - 0.55) / 0.45);
    }
    stroke(c);
    line(0, y, width, y);
  }
  noStroke();
}

// Soft translucent color clouds for painterly base
function glazeClouds() {
  let cols = [
    color(255, 210, 180, 14),
    color(248, 170, 190, 16),
    color(200, 165, 235, 12),
    color(255, 240, 205, 10),
    color(210, 235, 230, 8)
  ];
  push();
  blendMode(SOFT_LIGHT);
  for (let i = 0; i < 34; i++) {
    let cx = width * 0.5 + randomGaussian() * width * 0.22;
    let cy = height * 0.58 + randomGaussian() * height * 0.20;
    let r = random(220, 560);
    let col = cols[floor(random(cols.length))];
    let layers = floor(random(4, 9));
    for (let k = 0; k < layers; k++) {
      let rr = r * random(0.7, 1.2) * (1 - k / (layers * 3));
      organicBlob(cx + random(-20, 20), cy + random(-20, 20), rr, col, 70);
    }
  }
  pop();
}

// Draw a softly irregular blob with noise-perturbed perimeter
function organicBlob(cx, cy, r, col, steps) {
  noStroke();
  let c = color(red(col), green(col), blue(col), alpha(col));
  fill(c);
  beginShape();
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * TWO_PI;
    let nx = cos(a) * 0.6;
    let ny = sin(a) * 0.6;
    let nr = r * (0.82 + 0.22 * noise(cx * 0.001 + nx, cy * 0.001 + ny, i * 0.05));
    let x = cx + cos(a) * nr;
    let y = cy + sin(a) * nr;
    vertex(x, y);
  }
  endShape(CLOSE);
}

// Central soft glow
function centralGlow(x, y, r, baseCol, strength) {
  push();
  blendMode(ADD);
  noStroke();
  let layers = 80;
  for (let i = layers; i >= 1; i--) {
    let t = i / layers;
    let rad = r * pow(t, 0.7);
    let a = strength * pow(t, 2.4);
    fill(red(baseCol), green(baseCol), blue(baseCol), a);
    ellipse(x, y, rad * 2, rad * 1.6);
  }
  pop();
}

// Bezier helpers
function bezPos(p, t) {
  let x = bezierPoint(p[0].x, p[1].x, p[2].x, p[3].x, t);
  let y = bezierPoint(p[0].y, p[1].y, p[2].y, p[3].y, t);
  return createVector(x, y);
}
function bezTan(p, t) {
  let tx = bezierTangent(p[0].x, p[1].x, p[2].x, p[3].x, t);
  let ty = bezierTangent(p[0].y, p[1].y, p[2].y, p[3].y, t);
  let v = createVector(tx, ty);
  v.normalize();
  return v;
}

// Draw two intertwined ribbons
function drawRibbons() {
  let L = [
    createVector(360, 1900),
    createVector(420, 1400),
    createVector(760, 980),
    createVector(800, 260)
  ];
  let R = [
    createVector(1240, 1900),
    createVector(1180, 1400),
    createVector(840, 900),
    createVector(820, 220)
  ];

  // Underpainting halos for each ribbon
  push();
  blendMode(SOFT_LIGHT);
  ribbonGlow(L, 170, color(255, 160, 120, 32));
  ribbonGlow(R, 170, color(200, 150, 255, 28));
  pop();

  // Left ribbon: crimson -> amber
  drawRibbonStrip(
    L,
    70, 28,
    color(216, 47, 68),
    color(255, 164, 90),
    0.015
  );

  // Right ribbon: violet -> rose
  drawRibbonStrip(
    R,
    70, 28,
    color(90, 70, 210),
    color(245, 120, 180),
    0.017
  );

  // Soft inner gleam on both ribbons
  push();
  blendMode(ADD);
  ribbonGleam(L, 0.65, color(255, 210, 180, 30));
  ribbonGleam(R, 0.65, color(240, 190, 255, 26));
  pop();
}

// Build a ribbon by sweeping quads along a bezier path
function drawRibbonStrip(P, wStart, wEnd, cA, cB, nFreq) {
  noStroke();
  let steps = 150;
  let dt = 1 / steps;
  let prevL = null, prevR = null;

  for (let i = 0; i <= steps; i++) {
    let t = i * dt;
    let pos = bezPos(P, t);
    let tan = bezTan(P, t);
    // Slight wandering
    let phi = (noise(t * 5.0 + 7.3) - 0.5) * 0.5;
    let nx = -tan.y * cos(phi) - tan.x * sin(phi) * 0.05;
    let ny = tan.x * cos(phi) - tan.y * sin(phi) * 0.05;
    let n = createVector(nx, ny).normalize();

    let w = lerp(wStart, wEnd, t);
    w *= 0.92 + 0.18 * noise(t * 6.0, 3.1);
    let left = createVector(pos.x + n.x * w, pos.y + n.y * w);
    let right = createVector(pos.x - n.x * w, pos.y - n.y * w);

    let cc = lerpColor(cA, cB, pow(t, 0.8));
    let a = 158 - 30 * abs(0.5 - t);
    fill(red(cc), green(cc), blue(cc), a);

    if (prevL && prevR) {
      beginShape();
      vertex(prevL.x, prevL.y);
      vertex(prevR.x, prevR.y);
      vertex(right.x, right.y);
      vertex(left.x, left.y);
      endShape(CLOSE);
    }
    prevL = left;
    prevR = right;

    // Feathered edges
    if (i % 5 === 0 && i < steps - 2) {
      let fea = 26;
      fill(red(cc), green(cc), blue(cc), fea);
      let epos = createVector(pos.x + n.x * w * 0.0, pos.y + n.y * w * 0.0);
      ellipse(epos.x, epos.y, w * 0.5, w * 0.38);
    }
  }
}

// Glow trail beneath a ribbon
function ribbonGlow(P, radius, col) {
  let layers = 26;
  for (let i = 0; i < layers; i++) {
    let t = (i + 1) / layers;
    let p = bezPos(P, t * 0.9 + 0.05);
    let a = alpha(col) * (1 - t);
    noStroke();
    fill(red(col), green(col), blue(col), a);
    ellipse(p.x, p.y, radius * (1 - 0.8 * t) * 1.2, radius * (1 - 0.8 * t));
  }
}

// Gleam along ribbon centerline
function ribbonGleam(P, scale, col) {
  noStroke();
  for (let t = 0.06; t <= 0.96; t += 0.02) {
    let p = bezPos(P, t);
    let w = 40 * (1 - 0.6 * t) + 12;
    fill(red(col), green(col), blue(col), alpha(col));
    ellipse(p.x, p.y, w * scale, w * 0.6 * scale);
  }
}

// Gentle threads connecting the two ribbons
function drawConnectingThreads() {
  let L = [
    createVector(360, 1900),
    createVector(420, 1400),
    createVector(760, 980),
    createVector(800, 260)
  ];
  let R = [
    createVector(1240, 1900),
    createVector(1180, 1400),
    createVector(840, 900),
    createVector(820, 220)
  ];

  push();
  blendMode(ADD);
  for (let k = 0; k < 16; k++) {
    let t = 0.26 + k * 0.038 + random(-0.01, 0.012);
    t = constrain(t, 0.18, 0.95);
    let pl = bezPos(L, t);
    let pr = bezPos(R, constrain(t * 0.97 + 0.02, 0, 1));
    let mid = p5.Vector.lerp(pl, pr, 0.5);
    let lift = map(t, 0, 1, 180, -60) + random(-40, 40);
    let cp1 = createVector(mid.x + random(-80, 80), mid.y - lift);
    let cp2 = createVector(mid.x + random(-80, 80), mid.y - lift * 0.8);

    stroke(255, 220, 210, 36 + random(0, 20));
    strokeWeight(1.4);
    noFill();
    bezier(pl.x, pl.y, cp1.x, cp1.y, cp2.x, cp2.y, pr.x, pr.y);
  }
  pop();
}

// Subtle star-dust
function scatterDust(n) {
  push();
  noStroke();
  for (let i = 0; i < n; i++) {
    let x = random(width);
    let y = random(height * 0.98);
    let m = noise(x * 0.0012, y * 0.0012);
    if (random() < m * m * 0.08) {
      let sz = random(0.8, 2.2) * (0.6 + 0.4 * m);
      let a = 18 + 70 * pow(m, 3);
      fill(255, 240, 220, a);
      ellipse(x, y, sz, sz);
    }
  }
  pop();
}

// Edge vignette
function vignette(strength) {
  push();
  noStroke();
  let maxR = max(width, height) * 1.55;
  for (let i = 0; i < 140; i++) {
    let t = i / 139;
    let a = strength * pow(t, 2.2) / 140;
    fill(10, 8, 20, a * 2.2);
    let r = lerp(maxR * 0.6, maxR, t);
    ellipse(width / 2, height / 2, r, r * 1.1);
  }
  pop();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  colorMode(RGB, 255, 255, 255, 255);
  noStroke();
  background(0);

  // Background vertical gradient
  let cTop = color(18, 14, 40);
  let cBottom = color(255, 205, 175);
  verticalGradient(cTop, cBottom);

  // Soft central glow
  push();
  blendMode(SCREEN);
  radialGlow(width * 0.5, height * 0.48, 680, color(255, 140, 170, 26), 120);
  radialGlow(width * 0.5, height * 0.54, 520, color(255, 200, 150, 24), 120);
  pop();

  // Subtle horizon haze
  push();
  blendMode(SCREEN);
  for (let i = 0; i < 60; i++) {
    let y = lerp(900, 1300, i / 59);
    let alpha = 10 * (1 - abs(0.5 - i / 59) * 2);
    fill(255, 180, 160, alpha);
    rect(0, y, width, 8);
  }
  pop();

  // Lovers’ silhouettes
  let leftCol = color(255, 108, 92, 180);
  let rightCol = color(95, 94, 220, 180);

  push();
  blendMode(SCREEN);
  drawLover(-1, leftCol);
  drawLover(1, rightCol);
  pop();

  // Heart-like inner glow (subtle)
  push();
  blendMode(SCREEN);
  heartGlow(width * 0.5, height * 0.52, 230, color(255, 180, 210, 26), 5);
  radialGlow(width * 0.5, height * 0.52, 380, color(255, 160, 190, 20), 90);
  pop();

  // Interlacing ribbons between figures
  push();
  blendMode(SCREEN);
  drawRibbons(78);
  pop();

  // Floating petals
  push();
  blendMode(SCREEN);
  drawPetals(140);
  pop();

  // Edge vignette (corners)
  push();
  blendMode(MULTIPLY);
  cornerVignette(48);
  pop();

  // Soft film grain
  push();
  blendMode(OVERLAY);
  grain(42000, 12);
  pop();
}

function verticalGradient(c1, c2) {
  for (let y = 0; y < height; y++) {
    let t = y / (height - 1);
    // Gentle S-curve for softness
    let tt = smoothstep(0, 1, t);
    let c = lerpColor(c1, c2, tt);
    stroke(c);
    line(0, y, width, y);
  }
}

function radialGlow(cx, cy, r, col, steps) {
  noStroke();
  for (let i = steps; i >= 1; i--) {
    let t = i / steps;
    let a = alpha(col) * t;
    fill(red(col), green(col), blue(col), a);
    circle(cx, cy, r * 2 * t);
  }
}

function heartGlow(cx, cy, s, col, layers) {
  // Draw multiple soft hearts, growing outward with decreasing alpha
  for (let i = 0; i < layers; i++) {
    let t = i / max(1, layers - 1);
    let size = s * (1 + t * 0.45);
    let a = alpha(col) * (1 - t);
    fill(red(col), green(col), blue(col), a);
    beginShape();
    let segs = 200;
    for (let k = 0; k <= segs; k++) {
      let u = map(k, 0, segs, 0, TWO_PI);
      // Parametric heart (scaled and softened)
      let x = 16 * pow(sin(u), 3);
      let y = 13 * cos(u) - 5 * cos(2 * u) - 2 * cos(3 * u) - cos(4 * u);
      let jitter = noise(u * 0.7 + i * 0.3) * 0.8;
      let px = cx + (x * size * 0.9) / 16 + jitter;
      let py = cy - (y * size * 0.9) / 16 + jitter;
      vertex(px, py);
    }
    endShape(CLOSE);
  }
}

function drawLover(side, col) {
  let s = side; // -1 for left, 1 for right
  let cx = width * 0.5;
  // Base silhouette anchors (roughly torso-to-legs outer loop then closing)
  let pts = [];
  pts.push(createVector(cx + s * 260, 520));  // crown
  pts.push(createVector(cx + s * 360, 700));  // shoulder
  pts.push(createVector(cx + s * 220, 900));  // inner arm
  pts.push(createVector(cx + s * 120, 1050)); // embrace inward
  pts.push(createVector(cx + s * 220, 1250));// waist in
  pts.push(createVector(cx + s * 380, 1400));// outer hip
  pts.push(createVector(cx + s * 320, 1600));// knee
  pts.push(createVector(cx + s * 150, 1850));// inner foot
  pts.push(createVector(cx + s * 500, 1850));// outer foot
  pts.push(createVector(cx + s * 600, 1600));// outer calf
  pts.push(createVector(cx + s * 560, 1350));// outer hip higher
  pts.push(createVector(cx + s * 520, 900)); // outer shoulder
  pts.push(createVector(cx + s * 420, 600)); // back of head
  pts.push(createVector(cx + s * 260, 520)); // close to crown

  // Jitter and smooth using noise-based offsets
  let jPts = [];
  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    let n = noise(p.x * 0.004, p.y * 0.004);
    let ang = map(n, 0, 1, -PI, PI);
    let mag = map(noise(i * 0.21 + (s < 0 ? 3.17 : 6.41)), 0, 1, -1, 1) * 16;
    let px = p.x + cos(ang) * mag;
    let py = p.y + sin(ang) * mag;
    jPts.push(createVector(px, py));
  }

  // Soft fill
  noStroke();
  fill(col);
  curvedShape(jPts);

  // Subtle inner highlight stroke along inner curve
  stroke(red(col), green(col), blue(col), 70);
  strokeWeight(3);
  noFill();
  let innerPathIdx = [1, 2, 3, 4, 5, 6, 7];
  beginShape();
  for (let k = 0; k < innerPathIdx.length; k++) {
    let id = innerPathIdx[k];
    let v = jPts[id];
    curveVertex(v.x, v.y);
  }
  endShape();

  // Gentle rim light
  stroke(255, 210, 205, 28);
  strokeWeight(2);
  let rimIdx = [8, 9, 10, 11, 12, 13];
  beginShape();
  for (let k = 0; k < rimIdx.length; k++) {
    let id = rimIdx[k];
    let v = jPts[id];
    curveVertex(v.x, v.y);
  }
  endShape();
}

function curvedShape(pts) {
  beginShape();
  // Duplicate ends for smooth curve
  curveVertex(pts[0].x, pts[0].y);
  for (let i = 0; i < pts.length; i++) {
    curveVertex(pts[i].x, pts[i].y);
  }
  curveVertex(pts[pts.length - 1].x, pts[pts.length - 1].y);
  endShape(CLOSE);
}

function drawRibbons(count) {
  for (let i = 0; i < count; i++) {
    let t = i / max(1, count - 1);
    let yBase = lerp(820, 1220, t) + map(noise(t * 3.2), 0, 1, -40, 40);
    let xL = 800 - 320 + map(noise(t * 2.1 + 5.3), 0, 1, -70, 40);
    let xR = 800 + 320 + map(noise(t * 2.1 + 9.7), 0, 1, -40, 70);

    let cA = color(255, 110, 100);
    let cB = color(120, 110, 245);
    let cc = lerpColor(cA, cB, 0.5 + 0.5 * sin(t * PI));
    let a = 28 * (0.2 + 0.8 * (1 - abs(0.5 - t) * 2));
    stroke(red(cc), green(cc), blue(cc), a);
    strokeWeight(1.2 + 2.2 * pow(1 - abs(0.5 - t) * 2, 2));
    noFill();

    let c1x = lerp(xL, 800 - 120, 0.6) + map(noise(i * 0.12), 0, 1, -40, 40);
    let c1y = yBase - 220 + map(noise(i * 0.13 + 8.1), 0, 1, -80, 40);
    let c2x = lerp(800 + 120, xR, 0.6) + map(noise(i * 0.12 + 5.7), 0, 1, -40, 40);
    let c2y = yBase - 200 + map(noise(i * 0.13 + 3.9), 0, 1, -40, 80);

    bezier(xL, yBase, c1x, c1y, c2x, c2y, xR, yBase + map(noise(i * 0.14 + 2.4), 0, 1, -30, 30));
  }
}

function drawPetals(n) {
  let cols = [
    color(255, 230, 238, 110),
    color(255, 208, 220, 95),
    color(255, 245, 232, 85),
    color(255, 190, 205, 80)
  ];
  for (let i = 0; i < n; i++) {
    let x = randomGaussian(width * 0.5, 260);
    let y = random(740, 1380);
    let r = random(10, 26);
    let ang = random(TWO_PI);
    let c = cols[i % cols.length];
    drawPetalShape(x, y, r, ang, c);
  }
}

function drawPetalShape(x, y, r, ang, col) {
  push();
  translate(x, y);
  rotate(ang);
  noStroke();
  fill(col);
  beginShape();
  vertex(0, -r * 0.9);
  bezierVertex(r * 0.7, -r * 0.5, r * 0.7, r * 0.5, 0, r * 0.9);
  bezierVertex(-r * 0.7, r * 0.5, -r * 0.7, -r * 0.5, 0, -r * 0.9);
  endShape(CLOSE);

  // slight inner sheen
  fill(255, 255, 255, 22);
  ellipse(0, -r * 0.25, r * 0.6, r * 0.22);
  pop();
}

function cornerVignette(steps) {
  let corners = [
    createVector(0, 0),
    createVector(width, 0),
    createVector(0, height),
    createVector(width, height)
  ];
  for (let c = 0; c < corners.length; c++) {
    let v = corners[c];
    for (let i = steps; i >= 1; i--) {
      let t = i / steps;
      let d = max(width, height) * (0.6 + 1.2 * t);
      fill(0, 0, 0, 6 * t);
      circle(v.x, v.y, d);
    }
  }
}

function grain(count, alphaVal) {
  strokeWeight(1);
  for (let i = 0; i < count; i++) {
    let x = random(width);
    let y = random(height);
    let g = random() < 0.5 ? 240 : 20;
    stroke(g, alphaVal);
    point(x, y);
  }
}

function smoothstep(edge0, edge1, x) {
  let t = constrain((x - edge0) / (edge1 - edge0), 0, 1);
  return t * t * (3 - 2 * t);
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  colorMode(HSL, 360, 100, 100, 1);
  noLoop();
  compose();
}

function compose() {
  backgroundGradient();
  centralGlow();

  // Two luminous lobes approaching each other
  organicLobe(width * 0.44, height * 0.55, 480, {h1:345, s1:70, l1:52, h2:20, s2:90, l2:62}, 46, 0.08, 1.12);
  organicLobe(width * 0.58, height * 0.50, 470, {h1:205, s1:70, l1:48, h2:265, s2:55, l2:52}, 46, 0.08, 1.08);

  // Soft embracement arcs
  embraceArcs();

  // Flowing lines drawn by a gentle field, converging toward the center
  flowFieldRibbons("left", 900, 120);
  flowFieldRibbons("right", 900, 120);

  // Golden seams (kintsugi) crossing the meeting area
  goldenSeams(34);

  // Small sparks near the union
  sparks(1600);

  // Soft finishing veil
  finishingVeil();
}

function backgroundGradient() {
  let cTop = color(245, 60, 8, 1);   // deep indigo
  let cMid = color(315, 35, 18, 1);  // plum
  let cBot = color(260, 50, 10, 1);  // night violet

  noFill();
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let col;
    if (t < 0.55) col = lerpColor(cTop, cMid, t / 0.55);
    else col = lerpColor(cMid, cBot, (t - 0.55) / 0.45);
    stroke(col);
    line(0, y, width, y);
  }

  // Side darkening vignette
  push();
  noStroke();
  for (let i = 0; i < 120; i++) {
    let a = map(i, 0, 119, 0.22, 0);
    fill(260, 50, 6, a);
    let w = map(i, 0, 119, width * 1.3, width * 0.9);
    let h = map(i, 0, 119, height * 1.3, height * 1.0);
    ellipse(width / 2, height / 2, w, h);
  }
  pop();
}

function centralGlow() {
  push();
  blendMode(ADD);
  noStroke();
  for (let r = max(width, height) * 1.1; r > 40; r -= 28) {
    let a = map(r, 40, max(width, height) * 1.1, 0.28, 0.0);
    fill(0, 0, 100, a * 0.45);
    ellipse(width * 0.5, height * 0.52, r * 0.56, r * 0.45);
  }
  pop();
}

function organicLobe(cx, cy, baseR, hsl, layers, baseAlpha, yStretch) {
  // hsl: {h1,s1,l1,h2,s2,l2}
  noStroke();
  let off1 = random(1000), off2 = random(1000);
  for (let i = 0; i < layers; i++) {
    let t = i / (layers - 1);
    let h = lerp(hsl.h1, hsl.h2, t);
    let s = lerp(hsl.s1, hsl.s2, t);
    let l = lerp(hsl.l1, hsl.l2, t);
    let a = baseAlpha * (1.0 - t * 0.7);
    fill(h, s, l, a);
    beginShape();
    let verts = 180;
    let ns = 1.5;
    let rBase = baseR * lerp(1.0, 0.7, t * 0.9);
    for (let k = 0; k < verts; k++) {
      let ang = (k / verts) * TWO_PI;
      let nx = cos(ang) * ns + off1 + i * 0.05;
      let ny = sin(ang) * ns + off2 + i * 0.05;
      let wobble = 0.78 + 0.25 * noise(nx, ny);
      let rr = rBase * wobble;
      let x = cx + cos(ang) * rr;
      let y = cy + sin(ang) * rr * yStretch;
      vertex(x, y);
    }
    endShape(CLOSE);
  }
}

function embraceArcs() {
  push();
  noFill();
  blendMode(SCREEN);
  for (let i = 0; i < 20; i++) {
    let w = 900 + i * 18;
    let h = 760 + i * 22;
    stroke(350, 60, 55, 0.05);
    strokeWeight(30 - i);
    arc(width * 0.5 - 40 - i * 3, height * 0.58, w, h, PI + 0.2, TWO_PI - 0.2);
  }
  for (let i = 0; i < 20; i++) {
    let w = 900 + i * 18;
    let h = 760 + i * 22;
    stroke(210, 55, 50, 0.05);
    strokeWeight(30 - i);
    arc(width * 0.5 + 40 + i * 3, height * 0.50, w, h, PI + 0.2, TWO_PI - 0.2);
  }
  pop();
}

function flowFieldRibbons(side, count, steps) {
  push();
  blendMode(ADD);
  noFill();
  let center = createVector(width * 0.5, height * 0.52);
  for (let i = 0; i < count; i++) {
    let x = side === "left" ? random(120, width * 0.45) : random(width * 0.55, width - 120);
    let y = random(260, height - 260);
    let p = createVector(x, y);
    let prev = p.copy();

    // Base hues for sides
    let baseH = side === "left" ? 12 : 210;  // warm vs cool
    let targetH = 45; // toward golden near center

    let sw = random(0.6, 1.6);
    strokeWeight(sw);

    for (let s = 0; s < steps; s++) {
      let toC = p5.Vector.sub(center, p);
      let d = toC.mag();
      let att = constrain(map(d, 900, 0, 0.0, 0.6), 0, 0.6);
      let ang = noise(p.x * 0.0015, p.y * 0.0015) * TAU * 4.0 - PI + atan2(toC.y, toC.x) * att;

      // color along path
      let closeness = constrain(map(d, 700, 120, 0, 1), 0, 1);
      let h = lerp(baseH, targetH, pow(closeness, 1.5));
      let sCol = lerp(70, 95, closeness);
      let lCol = lerp(45, 65, closeness);
      let alpha = 0.06 + 0.12 * closeness;

      stroke(h, sCol, lCol, alpha);

      let stepLen = 2.0 + 1.2 * (1.0 - closeness);
      p.x += cos(ang) * stepLen;
      p.y += sin(ang) * stepLen;

      line(prev.x, prev.y, p.x, p.y);
      prev.set(p.x, p.y);

      if (p.x < 40 || p.x > width - 40 || p.y < 40 || p.y > height - 40) break;
      if (d < 90) break;
    }
  }
  pop();
}

function goldenSeams(n) {
  push();
  blendMode(SCREEN);
  for (let i = 0; i < n; i++) {
    let y0 = random(180, height - 180);
    let x0 = random(width * 0.35, width * 0.46);
    let x3 = width - x0 + random(-30, 30);
    let y3 = y0 + random(-200, 200);

    let cx1 = width * 0.50 + random(-120, 120);
    let cy1 = y0 + random(-140, 140);
    let cx2 = width * 0.50 + random(-120, 120);
    let cy2 = y3 + random(-140, 140);

    // Glow
    stroke(45, 100, 65, 0.06);
    strokeWeight(random(6, 12));
    noFill();
    bezier(x0, y0, cx1, cy1, cx2, cy2, x3, y3);

    // Mid
    stroke(45, 100, 62, 0.12);
    strokeWeight(random(2.2, 3.8));
    bezier(x0, y0, cx1, cy1, cx2, cy2, x3, y3);

    // Bright core
    stroke(45, 98, 70, 0.6);
    strokeWeight(1.2);
    bezier(x0, y0, cx1, cy1, cx2, cy2, x3, y3);

    // Occasional branching
    if (random() < 0.35) {
      let t = random(0.2, 0.8);
      let bx = bezPoint(x0, cx1, cx2, x3, t);
      let by = bezPoint(y0, cy1, cy2, y3, t);
      let bx2 = bx + random(-80, 80);
      let by2 = by + random(-120, 120);
      stroke(45, 98, 70, 0.5);
      strokeWeight(1.0);
      bezier(bx, by, (bx + bx2) / 2, (by + by2) / 2, bx2, by2, bx2 + random(-20, 20), by2 + random(-20, 20));
    }
  }
  pop();
}

function sparks(n) {
  push();
  noStroke();
  blendMode(ADD);
  for (let i = 0; i < n; i++) {
    let a = random(TWO_PI);
    let r = pow(random(), 0.8) * 520; // denser near center
    let x = width * 0.5 + cos(a) * r * 0.9;
    let y = height * 0.52 + sin(a) * r * 0.7;
    let warm = random() < 0.55;
    let h = warm ? random(20, 55) : random(200, 260);
    let s = warm ? random(70, 100) : random(60, 85);
    let l = random(65, 92);
    let al = random(0.08, 0.25);
    fill(h, s, l, al);
    let d = random(0.5, 2.2);
    ellipse(x, y, d, d);
  }
  pop();
}

function finishingVeil() {
  push();
  blendMode(OVERLAY);
  noStroke();
  for (let i = 0; i < 60; i++) {
    let a = map(i, 0, 59, 0.12, 0);
    fill(0, 0, 100, a * 0.2);
    let w = map(i, 0, 59, width * 0.9, width * 0.6);
    let h = map(i, 0, 59, height * 0.6, height * 0.45);
    ellipse(width * 0.5, height * 0.5, w, h);
  }
  pop();
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();

  backgroundLayer();
  centralGlow();
  defineRibbons();
  drawRibbons();
  drawThreads(140);
  drawSparks(160);
  addDust(900);
  vignette();
}

let L = null;
let R = null;

function backgroundLayer() {
  noStroke();
  // Vertical dusk gradient
  for (let y = 0; y < height; y += 2) {
    let t = y / height;
    let cTop = color(315, 35, 12, 100);   // plum
    let cBot = color(250, 35, 8, 100);    // deep indigo
    let c = lerpColor(cTop, cBot, t);
    stroke(c);
    line(0, y, width, y);
  }
  // Subtle mottled twilight using broad translucent passes
  noStroke();
  for (let i = 0; i < 260; i++) {
    let x = random(-200, width + 200);
    let y = random(-200, height + 200);
    let r = random(200, 520);
    let h = 260 + random(-10, 10);
    let s = 25 + random(-5, 5);
    let b = 12 + random(-4, 4);
    fill(h, s, b, 8);
    ellipse(x, y, r * 1.6, r);
  }
}

function centralGlow() {
  // Warm inner bloom suggesting life/heat
  let cx = width * 0.5;
  let cy = height * 0.56;
  let Rg = 900;
  noStroke();
  for (let i = Rg; i > 0; i -= 10) {
    let t = 1 - i / Rg;
    let h = 18 + t * 8;
    let s = 55 + t * 20;
    let b = min(65 + t * 30, 100);
    let a = 4 + 42 * pow(1 - t, 1.4);
    fill(h, s, b, a);
    ellipse(cx, cy, i * 2.0, i * 2.3);
  }
}

function defineRibbons() {
  // Define two embracing ribbon centerlines via quadratic beziers
  L = {
    p0: createVector(500, 1500),
    p1: createVector(920, 900),
    cp: createVector((500 + 920) / 2 - 260, (1500 + 900) / 2 - 220)
  };
  R = {
    p0: createVector(1100, 1500),
    p1: createVector(680, 900),
    cp: createVector((1100 + 680) / 2 + 260, (1500 + 900) / 2 - 220)
  };
}

function qBezier(p0, cp, p1, t) {
  // Quadratic Bezier point
  let u = 1 - t;
  return createVector(
    u * u * p0.x + 2 * u * t * cp.x + t * t * p1.x,
    u * u * p0.y + 2 * u * t * cp.y + t * t * p1.y
  );
}

function qTangent(p0, cp, p1, t) {
  // Derivative of quadratic Bezier
  let dx = 2 * (1 - t) * (cp.x - p0.x) + 2 * t * (p1.x - cp.x);
  let dy = 2 * (1 - t) * (cp.y - p0.y) + 2 * t * (p1.y - cp.y);
  return createVector(dx, dy);
}

function drawRibbon(def, wMax, colA, colB, tilt) {
  noStroke();
  let steps = 220;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let pos = qBezier(def.p0, def.cp, def.p1, t);
    let tan = qTangent(def.p0, def.cp, def.p1, t);
    let ang = atan2(tan.y, tan.x) + tilt;
    let w = wMax * pow(sin(PI * t), 0.85) * (0.6 + 0.45 * noise(100 + t * 3.0));
    let c = lerpColor(colA, colB, t);
    push();
    translate(pos.x, pos.y);
    rotate(ang);
    fill(hue(c), saturation(c), brightness(c), 22 + 10 * (0.5 - abs(0.5 - t)));
    ellipse(0, 0, w, w * 0.62);
    pop();
  }
  // Soft inner sheen
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    if (t < 0.25 || t > 0.78) continue;
    let pos = qBezier(def.p0, def.cp, def.p1, t);
    let tan = qTangent(def.p0, def.cp, def.p1, t);
    let ang = atan2(tan.y, tan.x) + tilt;
    let w = wMax * 0.35 * pow(sin(PI * t), 0.85);
    let glow = color(48, 60, 100, 16 + 20 * smoothstep(0.25, 0.55, t) * (1 - smoothstep(0.55, 0.78, t)));
    push();
    translate(pos.x, pos.y);
    rotate(ang);
    fill(glow);
    ellipse(0, 0, w, w * 0.45);
    pop();
  }
}

function drawRibbons() {
  let leftA = color(340, 70, 68, 35);  // rose
  let leftB = color(18, 85, 92, 42);   // coral-gold
  let rightA = color(305, 65, 70, 35); // magenta-violet
  let rightB = color(10, 80, 92, 42);  // warm peach
  drawRibbon(L, 320, leftA, leftB, -0.05);
  drawRibbon(R, 320, rightA, rightB, 0.05);
  // Gentle overlap veil at the cradle area
  noStroke();
  let cx = width * 0.5, cy = height * 0.98 - 1000;
  for (let i = 360; i > 0; i -= 12) {
    let t = 1 - i / 360;
    fill(22, 30, 95, 8 * (1 - t));
    ellipse(800, 1030, i * 2.2, i * 1.4);
  }
}

function drawThreads(n) {
  // Golden connective filaments between ribbons
  for (let i = 0; i < n; i++) {
    let t1 = 0.35 + pow(random(), 0.8) * 0.58;
    let t2 = 0.35 + pow(random(), 0.8) * 0.58;
    let pL = qBezier(L.p0, L.cp, L.p1, t1);
    let pR = qBezier(R.p0, R.cp, R.p1, t2);

    let midx = (pL.x + pR.x) * 0.5;
    let midy = (pL.y + pR.y) * 0.5;
    let jitter = 90 + 60 * noise(i * 0.13);
    let ang = random(-PI / 3, PI / 3);

    let c1 = createVector(
      midx + cos(ang) * jitter + random(-40, 40),
      midy + sin(ang) * jitter + random(-40, 40)
    );
    let c2 = createVector(
      midx - cos(ang) * jitter + random(-40, 40),
      midy - sin(ang) * jitter + random(-40, 40)
    );

    let sw = random(0.6, 1.8);
    stroke(44, 65, 100, 26 + 18 * random());
    strokeWeight(sw);
    noFill();
    bezier(pL.x, pL.y, c1.x, c1.y, c2.x, c2.y, pR.x, pR.y);

    // Tiny knots hint where thread meets the form
    noStroke();
    fill(44, 65, 100, 30);
    ellipse(pL.x, pL.y, 2 + sw * 1.2, 2 + sw * 1.2);
    ellipse(pR.x, pR.y, 2 + sw * 1.2, 2 + sw * 1.2);
  }
}

function drawSparks(count) {
  // Luminous motes around the embrace
  let cx = 800, cy = 1050;
  for (let i = 0; i < count; i++) {
    let a = random(TWO_PI);
    let r = 50 + 260 * pow(random(), 0.6);
    let x = cx + cos(a) * r + random(-10, 10);
    let y = cy + sin(a) * r + random(-10, 10);
    let hueBase = 38 + random(-8, 10);
    let s = 60 + random(-10, 15);
    let b = 90 + random(-5, 8);
    glowDot(x, y, random(2.5, 6.5), color(hueBase, s, b, 70));
  }
  // A denser inner cluster
  for (let i = 0; i < 80; i++) {
    let x = cx + random(-60, 60);
    let y = cy + random(-50, 50);
    glowDot(x, y, random(3.5, 8), color(48, 70, 100, 80));
  }
}

function glowDot(x, y, r, col) {
  noStroke();
  for (let k = 6; k >= 1; k--) {
    let t = k / 6;
    let a = alpha(col) * pow(t, 2) * 0.6;
    fill(hue(col), saturation(col), brightness(col), a);
    ellipse(x, y, r * (0.6 + t * 0.8), r * (0.6 + t * 0.8));
  }
  fill(hue(col), saturation(col), 100, 70);
  ellipse(x, y, r * 0.4, r * 0.4);
}

function addDust(n) {
  // Fine grain to tie layers
  noStroke();
  for (let i = 0; i < n; i++) {
    let x = random(width);
    let y = random(height);
    let nb = noise(x * 0.002, y * 0.002);
    let h = 300 + nb * 60;
    let s = 8 + nb * 14;
    let b = 40 + nb * 30;
    fill(h, s, b, 10 + 20 * nb);
    let sz = random(0.8, 1.8);
    ellipse(x, y, sz, sz);
  }
}

function vignette() {
  // Edge darkening for focus
  noStroke();
  let corners = [
    { x: -200, y: -200 },
    { x: width + 200, y: -200 },
    { x: -200, y: height + 200 },
    { x: width + 200, y: height + 200 }
  ];
  for (let i = 0; i < corners.length; i++) {
    let c = corners[i];
    for (let r = 1400; r > 200; r -= 60) {
      let t = 1 - (r - 200) / 1200;
      fill(260, 30, 5, 6 + 22 * t);
      ellipse(c.x, c.y, r * 1.4, r * 1.4);
    }
  }
}

// Smoothstep helper
function smoothstep(a, b, x) {
  let t = constrain((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  colorMode(HSB, 360, 100, 100, 1);
  noLoop();
}

function draw() {
  background(0, 0, 0, 1);
  smooth();
  strokeCap(ROUND);
  strokeJoin(ROUND);

  // Composition anchors
  const mid = createVector(width * 0.5, height * 0.5);
  const A = createVector(width * 0.36, height * 0.62);
  const B = createVector(width * 0.64, height * 0.38);

  // Background gradient
  drawVerticalGradient([
    { y: 0,     c: color(260, 45, 7, 1) },   // deep violet
    { y: 0.45,  c: color(280, 35, 10, 1) },  // night plum
    { y: 0.78,  c: color(320, 28, 12, 1) },  // dusk mauve
    { y: 1.0,   c: color(12, 55, 10, 1) }    // ember umber
  ]);

  // Large opposing glows (two entities)
  blendMode(ADD);
  drawRadialGlow(A.x, A.y, 900, color(24, 80, 95, 0.18), 120);
  drawRadialGlow(B.x, B.y, 900, color(195, 70, 90, 0.16), 120);

  // Shared luminous core
  drawRadialGlow(mid.x, mid.y, 520, color(38, 75, 100, 0.18), 120);
  drawRadialGlow(mid.x, mid.y, 240, color(12, 85, 100, 0.22), 80);

  blendMode(BLEND);

  // Veil: braided embrace (noisy rings around the shared space)
  for (let i = 0; i < 9; i++) {
    const r = 220 + i * 22;
    const amp = 22 + i * 2.5;
    const hueBase = lerp(18, 205, i / 8.0);
    const sat = lerp(85, 55, i / 8.0);
    const bri = lerp(88, 65, i / 8.0);
    const a = lerp(0.10, 0.035, i / 8.0);
    stroke(color(hueBase, sat, bri, a));
    noFill();
    strokeWeight(1.1 - i * 0.08);
    noisyRing(mid.x, mid.y, r, amp, 420, 0.0022, 0.9 + i * 0.03);
  }

  // Flow field threads weaving between A and B
  drawWeaveField(A, B, mid);

  // Soft dust and sparks
  drawDust(18000, 0.015);
  drawSparkCluster(mid.x, mid.y, 420, 650, 1600);

  // Gentle vignette
  vignette(0.22);
}

// Utilities

function drawVerticalGradient(stops) {
  // stops: array of {y: fraction, c: color}
  for (let y = 0; y < height; y++) {
    const t = y / (height - 1);
    const c = sampleGradient(stops, t);
    stroke(c);
    line(0, y, width, y);
  }
}

function sampleGradient(stops, t) {
  if (t <= stops[0].y) return stops[0].c;
  if (t >= stops[stops.length - 1].y) return stops[stops.length - 1].c;
  for (let i = 0; i < stops.length - 1; i++) {
    const a = stops[i];
    const b = stops[i + 1];
    if (t >= a.y && t <= b.y) {
      const u = (t - a.y) / (b.y - a.y);
      return lerpColor(a.c, b.c, u);
    }
  }
  return stops[stops.length - 1].c;
}

function drawRadialGlow(cx, cy, r, c, steps) {
  noStroke();
  for (let i = steps; i >= 1; i--) {
    const t = i / steps;
    const rr = r * t;
    const a = alpha(c) * pow(t, 2.2);
    const col = color(hue(c), saturation(c), brightness(c), a);
    fill(col);
    ellipse(cx, cy, rr, rr);
  }
}

function noisyRing(cx, cy, r, amp, pts, scale, curl) {
  beginShape();
  for (let i = 0; i <= pts; i++) {
    const th = (i / pts) * TAU;
    let x = cx + cos(th) * r;
    let y = cy + sin(th) * r;
    const n = noise(x * scale, y * scale);
    const wob = (n - 0.5) * 2 * amp;
    const wx = x + cos(th) * wob;
    const wy = y + sin(th) * wob;
    const ang = atan2(wy - cy, wx - cx) + HALF_PI;
    const fx = wx + cos(ang) * wob * 0.08 * curl;
    const fy = wy + sin(ang) * wob * 0.08 * curl;
    curveVertex(fx, fy);
  }
  endShape();
}

function drawWeaveField(A, B, M) {
  const nSeeds = 1100;
  const steps = 170;
  const scale = 0.0016;

  // Seed regions around edges and near A/B halos
  let seeds = [];
  for (let i = 0; i < nSeeds; i++) {
    const choice = floor(random(6));
    let x, y;
    if (choice === 0) { // left band
      x = random(-60, 160);
      y = random(-100, height + 100);
    } else if (choice === 1) { // right band
      x = random(width - 160, width + 60);
      y = random(-100, height + 100);
    } else if (choice === 2) { // top band
      x = random(-100, width + 100);
      y = random(-60, 120);
    } else if (choice === 3) { // bottom band
      x = random(-100, width + 100);
      y = random(height - 120, height + 60);
    } else if (choice === 4) { // near A
      const a = random(TAU);
      const rr = random(240, 420);
      x = A.x + cos(a) * rr;
      y = A.y + sin(a) * rr;
    } else { // near B
      const a = random(TAU);
      const rr = random(240, 420);
      x = B.x + cos(a) * rr;
      y = B.y + sin(a) * rr;
    }
    seeds.push(createVector(x, y));
  }

  blendMode(SCREEN);
  for (let i = 0; i < seeds.length; i++) {
    let p = seeds[i].copy();
    let prev = p.copy();
    const baseW = random(0.5, 1.4);
    for (let s = 0; s < steps; s++) {
      const v = fieldVector(p.x, p.y, A, B, M, scale);
      const n = noise(p.x * scale * 1.8, p.y * scale * 1.8);
      const speed = 1.3 + n * 1.1;
      p.x += cos(v) * speed;
      p.y += sin(v) * speed;

      // Color by bias toward A or B
      const dA = dist(p.x, p.y, A.x, A.y);
      const dB = dist(p.x, p.y, B.x, B.y);
      const bias = constrain((dB - dA) / 600.0, -1, 1); // [-1..1]
      const u = (bias + 1) * 0.5; // [0..1]
      const h = lerp(200, 18, u);
      const sCol = lerp(55, 88, 1 - abs(bias));
      const bCol = 42 + 48 * exp(-sq(dist(p.x, p.y, M.x, M.y)) / sq(540));
      const aCol = 0.05 + 0.04 * exp(-sq(dist(p.x, p.y, M.x, M.y)) / sq(480));

      stroke(color(h, sCol, bCol, aCol));
      const w = baseW * (0.6 + 0.6 * exp(-sq(dist(p.x, p.y, M.x, M.y)) / sq(520)));
      strokeWeight(w);

      line(prev.x, prev.y, p.x, p.y);
      prev.set(p);

      if (p.x < -150 || p.x > width + 150 || p.y < -150 || p.y > height + 150) break;
    }
  }
  blendMode(BLEND);
}

function fieldVector(x, y, A, B, M, scale) {
  // Base noise orientation
  const n = noise(x * scale, y * scale);
  let a = map(n, 0, 1, -PI, PI);

  // Swirl around shared center
  const swirl = atan2(y - M.y, x - M.x) + HALF_PI;

  // Attraction toward the nearer focus
  const dA = dist(x, y, A.x, A.y);
  const dB = dist(x, y, B.x, B.y);
  const toward = (dA < dB) ? atan2(A.y - y, A.x - x) : atan2(B.y - y, B.x - x);

  // Gentle drift along AB axis
  const axis = atan2(B.y - A.y, B.x - A.x);

  // Blend angles
  a = lerpAngle(a, swirl, 0.38);
  a = lerpAngle(a, toward, 0.25);
  a = lerpAngle(a, axis, 0.12);

  return a;
}

function lerpAngle(a, b, t) {
  const d = atan2(sin(b - a), cos(b - a));
  return a + d * t;
}

function drawDust(count, alphaBase) {
  noStroke();
  for (let i = 0; i < count; i++) {
    const x = random(-40, width + 40);
    const y = random(-40, height + 40);
    const n = noise(x * 0.003, y * 0.003);
    const w = 0.6 + n * 1.2;
    const h = 0.6 + (1 - n) * 1.2;
    const hueVar = lerp(200, 25, n);
    const bri = 8 + 42 * pow(n, 2.0);
    const a = alphaBase * (0.4 + 0.6 * pow(n, 1.8));
    fill(color(hueVar, 18 + 20 * n, bri, a));
    ellipse(x, y, w, h);
  }
}

function drawSparkCluster(cx, cy, rIn, rOut, count) {
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < count; i++) {
    const a = random(TAU);
    const r = sqrt(random()) * (rOut - rIn) + rIn;
    const x = cx + cos(a) * r + (noise(i * 0.01) - 0.5) * 4;
    const y = cy + sin(a) * r + (noise(i * 0.01 + 1000) - 0.5) * 4;
    const t = (r - rIn) / (rOut - rIn);
    const h = lerp(35, 195, t);
    const b = lerp(100, 65, t);
    const s = lerp(85, 55, t);
    const al = lerp(0.08, 0.015, t) * random(0.6, 1);
    fill(color(h, s, b, al));
    const sz = 1 + 2.4 * pow(1 - t, 2) * random(0.5, 1.2);
    ellipse(x, y, sz, sz);
  }
  blendMode(BLEND);
}

function vignette(strength) {
  noFill();
  const steps = 50;
  for (let i = 0; i < steps; i++) {
    const t = i / (steps - 1);
    const a = strength * pow(t, 1.8) * 0.9;
    stroke(0, 0, 0, a);
    strokeWeight(80 * (1 - t));
    rect(0, 0, width, height);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
  noStroke();
  drawPainting();
}

function draw() {}

function drawPainting() {
  // Background vertical gradient
  let topCol = color(10, 14, 34);
  let botCol = color(18, 8, 28);
  for (let y = 0; y < height; y++) {
    let t = y / (height - 1);
    stroke(lerpColor(topCol, botCol, t));
    line(0, y, width, y);
  }
  noStroke();

  // Positions
  let leftCx = 560, leftCy = 1150, leftR = 720;
  let rightCx = 1040, rightCy = 870, rightR = 720;
  let midCx = 800, midCy = 1000;

  // Warm and cool auras with SCREEN blend
  blendMode(SCREEN);
  radialGradient(leftCx, leftCy, leftR,
                 color(255, 142, 92, 220),
                 color(120, 35, 28, 0), 420);
  radialGradient(rightCx, rightCy, rightR,
                 color(100, 170, 255, 220),
                 color(30, 40, 110, 0), 420);

  // Gentle bridging haze
  radialGradient((leftCx + rightCx) / 2, (leftCy + rightCy) / 2, 580,
                 color(230, 120, 200, 80),
                 color(120, 40, 100, 0), 260);
  blendMode(BLEND);

  // Subtle background texture fog
  push();
  noStroke();
  for (let i = 0; i < 1800; i++) {
    let x = random(width), y = random(height);
    let d = random(20, 80);
    let a = 6 + 12 * pow(noise(x * 0.002, y * 0.002), 2);
    fill(40, 30, 60, a);
    ellipse(x, y, d, d);
  }
  pop();

  // Flow field lines: threads of attraction
  let warmLine = color(255, 150, 110);
  let coolLine = color(110, 160, 255);

  // Draw flows from edges, left source, right source
  drawFlows(700, "edges", warmLine, coolLine, leftCx, leftCy, rightCx, rightCy, midCx, midCy);
  drawFlows(900, "left", warmLine, coolLine, leftCx, leftCy, rightCx, rightCy, midCx, midCy);
  drawFlows(900, "right", warmLine, coolLine, leftCx, leftCy, rightCx, rightCy, midCx, midCy);

  // Soft cross-ribbons (semi-transparent bezier veils)
  push();
  noFill();
  strokeWeight(2);
  for (let k = 0; k < 24; k++) {
    let t = k / 23;
    let c = lerpColor(color(255, 160, 120), color(120, 170, 255), t);
    c.setAlpha(28);
    stroke(c);
    let x1 = leftCx + cos(TWO_PI * t) * (leftR * 0.7);
    let y1 = leftCy + sin(TWO_PI * t) * (leftR * 0.35);
    let x4 = rightCx + cos(TWO_PI * (1 - t)) * (rightR * 0.7);
    let y4 = rightCy + sin(TWO_PI * (1 - t)) * (rightR * 0.35);
    let x2 = lerp(x1, midCx, 0.6) + noise(t * 3.1) * 140 - 70;
    let y2 = lerp(y1, midCy, 0.6) + noise(100 + t * 2.8) * 180 - 90;
    let x3 = lerp(x4, midCx, 0.6) + noise(200 + t * 2.3) * 140 - 70;
    let y3 = lerp(y4, midCy, 0.6) + noise(300 + t * 2.6) * 180 - 90;
    bezier(x1, y1, x2, y2, x3, y3, x4, y4);
  }
  pop();

  // Central glow and sparks
  blendMode(ADD);
  radialGradient(midCx, midCy, 330,
                 color(255, 244, 210, 130),
                 color(255, 200, 120, 0), 300);
  radialGradient(midCx, midCy, 160,
                 color(255, 255, 255, 140),
                 color(255, 220, 160, 0), 200);

  // Sparks
  for (let i = 0; i < 1400; i++) {
    let ang = random(TWO_PI);
    let rad = pow(random(), 1.8) * 300;
    let x = midCx + cos(ang) * rad + random(-1, 1);
    let y = midCy + sin(ang) * rad + random(-1, 1);
    let sz = random(1, 2.4);
    let ca = color(255, 230, 170, random(18, 70));
    fill(ca);
    noStroke();
    ellipse(x, y, sz, sz);
  }
  blendMode(BLEND);

  // Subtle vignetting
  vignette(midCx, midCy, max(width, height) * 0.95, color(0, 0, 0, 0), color(0, 0, 0, 90), 340);

  // Quiet hairline "scars" (very subtle)
  push();
  stroke(20, 18, 30, 22);
  strokeWeight(0.6);
  noFill();
  for (let i = 0; i < 48; i++) {
    let x1 = random(-100, width + 100);
    let y1 = random(-100, height + 100);
    let x2 = lerp(x1, midCx, random(0.3, 0.8)) + random(-40, 40);
    let y2 = lerp(y1, midCy, random(0.3, 0.8)) + random(-40, 40);
    let cx1 = lerp(x1, x2, 0.3) + random(-120, 120);
    let cy1 = lerp(y1, y2, 0.3) + random(-80, 80);
    let cx2 = lerp(x1, x2, 0.7) + random(-120, 120);
    let cy2 = lerp(y1, y2, 0.7) + random(-80, 80);
    bezier(x1, y1, cx1, cy1, cx2, cy2, x2, y2);
  }
  pop();
}

function radialGradient(cx, cy, r, innerCol, outerCol, steps) {
  push();
  noStroke();
  for (let i = steps; i >= 1; i--) {
    let t = i / steps;
    let c = lerpColor(innerCol, outerCol, 1 - t);
    fill(c);
    let d = r * t * 2;
    ellipse(cx, cy, d, d);
  }
  pop();
}

function vignette(cx, cy, r, centerCol, edgeCol, steps) {
  push();
  noStroke();
  for (let i = 1; i <= steps; i++) {
    let t = i / steps;
    let c = lerpColor(centerCol, edgeCol, t);
    fill(c);
    let d = r * t * 2.2; // extend beyond edges
    ellipse(cx, cy, d, d);
  }
  pop();
}

function drawFlows(count, mode, warmLine, coolLine, leftCx, leftCy, rightCx, rightCy, midCx, midCy) {
  push();
  // Flow parameters
  let stepsPer = 120;
  let scale = 0.0016;
  let stepMag = 0.8;
  let attractStrength = 0.0006;

  for (let i = 0; i < count; i++) {
    // Starting point
    let x, y;
    if (mode === "edges") {
      let side = floor(random(4));
      if (side === 0) { x = random(-50, 0); y = random(-50, height + 50); }
      else if (side === 1) { x = random(width, width + 50); y = random(-50, height + 50); }
      else if (side === 2) { x = random(-50, width + 50); y = random(-50, 0); }
      else { x = random(-50, width + 50); y = random(height, height + 50); }
    } else if (mode === "left") {
      let ang = random(TWO_PI);
      let rad = sqrt(random()) * (leftCx < width ? 0.85 : 1) * (min(width, height) * 0.6);
      x = leftCx + cos(ang) * (random(0.2, 0.8) * 0.9 * rad);
      y = leftCy + sin(ang) * (random(0.2, 0.8) * 0.6 * rad);
    } else {
      let ang = random(TWO_PI);
      let rad = sqrt(random()) * (min(width, height) * 0.6);
      x = rightCx + cos(ang) * (random(0.2, 0.8) * 0.9 * rad);
      y = rightCy + sin(ang) * (random(0.2, 0.8) * 0.6 * rad);
    }

    let px = x, py = y;
    for (let s = 0; s < stepsPer; s++) {
      // Flow angle from noise
      let a = noise(x * scale, y * scale) * TWO_PI * 2.0 +
              noise((x + 1000) * scale, (y - 1000) * scale) * PI * 0.5;

      // Flow step
      let vx = cos(a) * stepMag;
      let vy = sin(a) * stepMag;

      // Attraction to shared center
      let dx = midCx - x;
      let dy = midCy - y;
      let ax = dx * attractStrength;
      let ay = dy * attractStrength;

      // Slight breathing
      let breathe = 0.5 + 0.5 * sin((i * 13.7 + s) * 0.012);
      let jx = (noise(x * 0.01, y * 0.01) - 0.5) * 0.2 * breathe;
      let jy = (noise(999 + x * 0.01, 999 + y * 0.01) - 0.5) * 0.2 * breathe;

      let nx = x + vx + ax + jx;
      let ny = y + vy + ay + jy;

      // Color blend based on proximity to sources
      let dl = dist(x, y, leftCx, leftCy);
      let dr = dist(x, y, rightCx, rightCy);
      let t = dl / (dl + dr + 0.0001);
      let cc = lerpColor(warmLine, coolLine, t);

      // Alpha by closeness to center, and path progress
      let dc = dist(x, y, midCx, midCy);
      let aBase = map(dc, 0, 1000, 185, 16);
      aBase = constrain(aBase, 10, 185);
      let fadeTail = pow(1 - s / stepsPer, 0.3);
      let alpha = aBase * fadeTail * 0.32;
      cc.setAlpha(alpha);

      // Stroke weight taper
      let w = 1.4 * (1 - s / stepsPer) + 0.2;

      stroke(cc);
      strokeWeight(w);
      line(x, y, nx, ny);

      x = nx; y = ny;

      // stop if off canvas far
      if (x < -120 || x > width + 120 || y < -120 || y > height + 120) break;
    }
  }
  pop();
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // Background
  drawBackground();

  // Core positions (two attractors)
  const A = createVector(width * 0.62, height * 0.56); // right
  const B = createVector(width * 0.38, height * 0.54); // left
  const MID = p5.Vector.add(A, B).mult(0.5);

  // Swirling embrace (flow field strokes)
  drawEmbraceFlow(A, B, MID);

  // Subtle connective filaments
  drawFilaments(A, B);

  // Halo around the union
  drawCoreGlow(MID);

  // Texture and vignette
  addGrain(48000);
  vignette();
}

function drawBackground() {
  noStroke();
  const cInner = color('#ffd3c1');
  const cMid   = color('#8c3b67');
  const cOuter = color('#0a0b21');

  // Radial, slightly vertical ellipse gradient
  const cx = width * 0.5;
  const cy = height * 0.56;
  const r  = max(width, height) * 0.95;

  for (let i = r; i > 0; i -= 4) {
    let t = i / r;
    let col;
    if (t > 0.6) {
      const tt = map(t, 0.6, 1, 0, 1);
      col = lerpColor(cMid, cOuter, pow(tt, 0.9));
    } else {
      const tt = map(t, 0, 0.6, 0, 1);
      col = lerpColor(cInner, cMid, pow(tt, 1.4));
    }
    fill(col);
    ellipse(cx, cy, i * 2.0, i * 2.3);
  }

  // Soft underglow sweep
  push();
  blendMode(ADD);
  const sweep = color('#ffb7a5'); sweep.setAlpha(14);
  fill(sweep);
  noStroke();
  for (let k = 0; k < 8; k++) {
    const w = width * (0.9 + k * 0.04);
    const h = height * (0.18 + k * 0.01);
    ellipse(width * 0.5, height * (0.58 + k * 0.01), w, h);
  }
  pop();
}

function drawEmbraceFlow(A, B, MID) {
  const warm = [
    color('#ff5f6d'), // coral rose
    color('#ffc371'), // amber
    color('#ff8a9a'), // petal
    color('#f06eaa'), // magenta rose
    color('#ffb1a8')  // blush
  ];
  const cool = [
    color('#4facfe'), // sky
    color('#00f2fe'), // cyan
    color('#7b5cff'), // violet
    color('#6dd5ed'), // pastel aqua
    color('#8ec5fc')  // ice
  ];

  push();
  blendMode(ADD);
  strokeCap(ROUND);
  noFill();

  // Left and right groups
  const groups = [
    {center: B.copy(), rx: 520, ry: 740, palette: warm, n: 720, steps: [90, 150], weight: [0.6, 2.6]},
    {center: A.copy(), rx: 520, ry: 740, palette: cool, n: 720, steps: [90, 150], weight: [0.6, 2.6]}
  ];

  for (let g = 0; g < groups.length; g++) {
    const G = groups[g];
    for (let i = 0; i < G.n; i++) {
      const start = sampleEllipse(G.center, G.rx, G.ry);
      const c = lerpColor(
        randomFrom(G.palette),
        randomFrom(G.palette),
        0.35 + 0.5 * easeInOutCubic(random())
      );
      c.setAlpha(20 + random(10)); // translucence
      stroke(c);

      const steps = floor(lerp(G.steps[0], G.steps[1], easeInOutCubic(random())));
      let p = start.copy();
      let prev = p.copy();
      for (let s = 0; s < steps; s++) {
        const v = field(p, A, B, MID);
        const stepLen = 1.2 + 0.6 * sin((s / steps) * PI);
        p.add(p5.Vector.mult(v, stepLen));

        const w = lerp(G.weight[0], G.weight[1], sin((s / steps) * PI));
        strokeWeight(w);

        // Occasionally modulate color slightly along stroke
        if (s % 16 === 0) {
          const cc = c.levels.slice();
          const jitter = random(-10, 10);
          stroke(cc[0] + jitter, cc[1] + jitter, cc[2] + jitter, c._getAlpha());
        }

        line(prev.x, prev.y, p.x, p.y);
        prev.set(p);

        // Stop if outside margins
        if (p.x < -40 || p.x > width + 40 || p.y < -40 || p.y > height + 40) break;
      }
    }
  }
  pop();
}

function field(p, A, B, MID) {
  // Vector field: two counter-rotating swirls + gentle attraction + noise curl
  const toA = p5.Vector.sub(p, A);
  const toB = p5.Vector.sub(p, B);
  const dA = max(1, toA.mag());
  const dB = max(1, toB.mag());

  // Perpendicular swirl components (opposed directions)
  const swirlA = createVector(-toA.y, toA.x).mult(1 / (dA * 0.85));
  const swirlB = createVector(toB.y, -toB.x).mult(1 / (dB * 0.85));

  // Convergence toward the shared middle
  const toM = p5.Vector.sub(MID, p).mult(0.0012);

  // Gentle pull toward each focus
  const pullA = p5.Vector.sub(A, p).mult(0.00022);
  const pullB = p5.Vector.sub(B, p).mult(0.00022);

  // Organic curl from noise
  const n = noise(p.x * 0.0013, p.y * 0.0013);
  const ang = map(n, 0, 1, -PI, PI);
  const curl = createVector(cos(ang), sin(ang)).mult(0.45);

  let v = createVector(0, 0);
  v.add(swirlA);
  v.add(swirlB);
  v.add(toM);
  v.add(pullA);
  v.add(pullB);
  v.add(curl);

  v.limit(2.4);
  return v;
}

function sampleEllipse(c, rx, ry) {
  // Uniform sampling inside an ellipse
  const a = random(TWO_PI);
  const r = sqrt(random()); // bias toward center
  const x = c.x + cos(a) * rx * r;
  const y = c.y + sin(a) * ry * r;
  return createVector(x, y);
}

function randomFrom(arr) {
  return arr[floor(random(arr.length))];
}

function drawFilaments(A, B) {
  push();
  blendMode(ADD);
  noFill();
  const N = 90;
  const AB = p5.Vector.sub(A, B);
  const L = AB.mag();
  const dir = AB.copy().normalize();
  const perp = createVector(-dir.y, dir.x);

  for (let i = 0; i < N; i++) {
    const ra = 170 + random(110);
    const rb = 170 + random(110);
    const a1 = random(TWO_PI);
    const a2 = a1 + random(-0.6, 0.6);

    const P1 = p5.Vector.add(B, createVector(cos(a1) * rb, sin(a1) * rb));
    const P4 = p5.Vector.add(A, createVector(cos(a2) * ra, sin(a2) * ra));

    const bend = (0.18 + 0.1 * sin(i * 0.7)) * L;
    let P2 = p5.Vector.lerp(P1, P4, 0.35).add(p5.Vector.mult(perp, bend * (0.4 + 0.6 * random())));
    let P3 = p5.Vector.lerp(P1, P4, 0.65).add(p5.Vector.mult(perp, -bend * (0.3 + 0.7 * random())));

    const col1 = color('#ffd9cf');
    const col2 = color('#cbe9ff');
    const c = lerpColor(col1, col2, 0.45 + 0.25 * sin(i * 0.4));
    c.setAlpha(22 + random(18));
    stroke(c);

    strokeWeight(0.6 + 0.7 * pow(sin((i / N) * PI), 1.3));
    bezier(P1.x, P1.y, P2.x, P2.y, P3.x, P3.y, P4.x, P4.y);
  }
  pop();
}

function drawCoreGlow(MID) {
  push();
  blendMode(ADD);
  noStroke();

  const cw = color('#ffd6c6');
  const cc = color('#c7eaff');
  let maxR = 700;

  for (let r = maxR; r > 24; r -= 12) {
    const t = r / maxR;
    let col = lerpColor(cw, cc, 0.45 + 0.25 * sin(t * TWO_PI));
    col.setAlpha(map(t, 0, 1, 16, 0));
    fill(col);
    ellipse(MID.x, MID.y, r * 2.0, r * 1.72);
  }

  // Small inner heart of warmth
  const inner = color('#ffb9a8'); inner.setAlpha(46);
  fill(inner);
  ellipse(MID.x, MID.y + 10, 120, 100);
  pop();
}

function addGrain(n) {
  push();
  noStroke();
  // Light flecks
  for (let i = 0; i < n * 0.7; i++) {
    const x = random(width);
    const y = random(height);
    const g = random(220, 255);
    fill(g, g, g, 10);
    rect(x, y, 1, 1);
  }
  // Dark flecks
  for (let i = 0; i < n * 0.3; i++) {
    const x = random(width);
    const y = random(height);
    const g = random(0, 40);
    fill(g, g, g, 8);
    rect(x, y, 1, 1);
  }
  pop();
}

function vignette() {
  push();
  blendMode(MULTIPLY);
  noStroke();
  const cx = width * 0.5;
  const cy = height * 0.56;

  const maxR = max(width, height) * 1.25;
  for (let i = 0; i <= 480; i++) {
    const t = i / 480;
    const gray = lerp(255, 40, pow(t, 1.35));
    fill(gray, gray, gray, 10);
    ellipse(cx, cy, lerp(width * 0.7, maxR * 2.0, t), lerp(height * 0.7, maxR * 2.3, t));
  }
  pop();
}

// Easing utility
function easeInOutCubic(x) {
  return x < 0.5 ? 4 * x * x * x : 1 - pow(-2 * x + 2, 3) / 2;
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  colorMode(HSB, 360, 100, 100, 100);
  noStroke();
  noLoop();
}

function draw() {
  drawPainting();
}

function drawPainting() {
  let cA = createVector(width * 0.38, height * 0.58);
  let cB = createVector(width * 0.62, height * 0.42);
  let cM = p5.Vector.lerp(cA, cB, 0.5);

  // Background gradient
  verticalGradient(
    color(230, 30, 8, 100),   // top: deep indigo
    color(40, 18, 98, 100)    // bottom: warm cream
  );

  // Diagonal blush wash
  blendMode(SOFT_LIGHT);
  angledWash(color(345, 35, 95, 24), -PI/6, 0.65); // rose veil
  blendMode(BLEND);

  // Twin cores glow (reciprocity)
  radialGlow(cA.x, cA.y, 520, color(18, 85, 95, 38), color(18, 85, 95, 0), 120);
  radialGlow(cB.x, cB.y, 520, color(195, 45, 92, 34), color(195, 45, 92, 0), 120);

  // Shared basin glow
  radialGlow(cM.x, cM.y, 900, color(320, 25, 95, 14), color(320, 25, 95, 0), 160);

  // Flow field layers (entanglement)
  let layers = [
    { z: 0.12,   from: color(14, 85, 96, 18),  to: color(330, 45, 98, 10), scale: 0.0018, w: 1.1 },
    { z: 10.37,  from: color(190, 50, 90, 18), to: color(225, 35, 85, 10), scale: 0.0016, w: 1.0 },
    { z: 5.71,   from: color(35, 65, 95, 18),  to: color(12, 80, 88, 10),  scale: 0.0014, w: 0.9 },
    { z: 20.83,  from: color(300, 35, 90, 16), to: color(10, 70, 95, 10),  scale: 0.0019, w: 0.9 }
  ];

  blendMode(ADD);
  for (let i = 0; i < layers.length; i++) {
    drawFlowLayer(layers[i], cA, cB);
  }
  blendMode(BLEND);

  // Filaments between centers (commitment threads)
  drawBridges(cA, cB);

  // Kintsugi-like fractures (scars mended in gold)
  drawGoldCracks();

  // Memory speckles
  drawSpeckles();

  // Soft halos breathing
  softHalos(cA, 6, 120, color(0, 0, 100, 4));
  softHalos(cB, 6, 120, color(0, 0, 100, 4));

  // Subtle vignette to cradle the scene
  vignette(color(230, 30, 8, 0), color(230, 25, 4, 24), 90);
}

// Utilities

function verticalGradient(cTop, cBot) {
  noStroke();
  for (let y = 0; y < height; y++) {
    let t = y / (height - 1);
    let c = lerpColor(cTop, cBot, t);
    fill(c);
    rect(0, y, width, 1);
  }
}

function angledWash(col, angle, coverage) {
  push();
  translate(width/2, height/2);
  rotate(angle);
  let w = width * 1.8;
  let h = height * coverage * 1.6;
  for (let i = 0; i < 120; i++) {
    let t = i / 119;
    let a = map(smoothstep(0,1,t), 0, 1, alpha(col), 0);
    fill(hue(col), saturation(col), brightness(col), a);
    rectMode(CENTER);
    rect(0, 0, w, h * (1 - 0.7*t), 20);
  }
  pop();
}

function radialGlow(cx, cy, r, cInner, cOuter, steps) {
  noStroke();
  for (let i = steps; i >= 0; i--) {
    let t = i / steps;
    let rr = r * (0.2 + 0.8 * t);
    let c = lerpColor(cInner, cOuter, 1 - t);
    fill(c);
    ellipse(cx, cy, rr * 2, rr * 2);
  }
}

function drawFlowLayer(layer, cA, cB) {
  let nParticles = 2300;
  let steps = 90;
  let s = layer.scale;
  strokeWeight(layer.w);
  for (let p = 0; p < nParticles; p++) {
    // Seed near edges to encourage inward weaving
    let pos = edgeSeed();
    let x = pos.x;
    let y = pos.y;
    let col = lerpColor(layer.from, layer.to, random(1));
    col.setAlpha(alpha(col) * random(0.8, 1));
    stroke(col);
    let speed = random(0.9, 1.8);
    let jitter = random(-0.12, 0.12);
    for (let k = 0; k < steps; k++) {
      let ang = noise(x * s, y * s, layer.z) * TAU * 2.0 - PI + jitter;
      let vx = Math.cos(ang);
      let vy = Math.sin(ang);

      // attraction toward two centers with soft falloff
      let toA = createVector(cA.x - x, cA.y - y);
      let toB = createVector(cB.x - x, cB.y - y);
      let dA = max(1, toA.mag());
      let dB = max(1, toB.mag());
      toA.normalize().mult(0.8 * 1.0 / (1 + dA / 380));
      toB.normalize().mult(0.8 * 1.0 / (1 + dB / 380));

      let v = createVector(vx, vy).mult(speed).add(toA).add(toB);
      let nx = x + v.x;
      let ny = y + v.y;

      // fade color slightly along the path
      if (k % 8 === 0) {
        let tt = k / steps;
        let cc = lerpColor(layer.from, layer.to, tt);
        cc.setAlpha(alpha(col) * (0.6 + 0.4 * (1 - tt)));
        stroke(cc);
      }

      point(nx, ny);
      x = nx; y = ny;

      if (x < -50 || x > width + 50 || y < -50 || y > height + 50) break;
    }
  }
}

function drawBridges(cA, cB) {
  let N = 160;
  for (let i = 0; i < N; i++) {
    let t = i / (N - 1);
    let p0 = p5.Vector.add(cA, p5.Vector.fromAngle(random(TAU)).mult(random(4, 42)));
    let p3 = p5.Vector.add(cB, p5.Vector.fromAngle(random(TAU)).mult(random(4, 42)));

    let dir = p5.Vector.sub(p3, p0);
    let norm = createVector(-dir.y, dir.x).normalize();
    let bulge = (noise(i * 0.12) - 0.5) * 2;
    let amp = map(sin(t * PI), 0, 1, 60, 260) * (0.6 + 0.4 * random());
    let p1 = p5.Vector.lerp(p0, p3, 0.25).add(p5.Vector.mult(norm, amp * bulge));
    let p2 = p5.Vector.lerp(p0, p3, 0.75).add(p5.Vector.mult(norm, -amp * bulge * 0.9));

    let hueMix = lerp(14, 195, t);
    let sat = lerp(80, 45, t) * (0.7 + 0.3 * random());
    let bri = lerp(96, 90, t) * (0.85 + 0.15 * random());
    let alphaC = 10 + 40 * pow(sin(t * PI), 1.2) * random(0.6, 1.0);

    noFill();
    stroke(hueMix, sat, bri, alphaC);
    strokeWeight(0.7 + 1.9 * pow(sin(t * PI), 1.1) * (0.7 + 0.3 * random()));
    bezier(p0.x, p0.y, p1.x, p1.y, p2.x, p2.y, p3.x, p3.y);
  }
}

function drawGoldCracks() {
  let n = 12;
  for (let i = 0; i < n; i++) {
    let pts = [];
    let p = edgeSeed();
    let dirAng = random(TAU);
    let step = random(3.0, 7.0);
    let len = floor(random(220, 520));
    let sc = 0.004 + random(-0.001, 0.001);
    let z = random(1000);

    for (let k = 0; k < len; k++) {
      let a = noise(p.x * sc, p.y * sc, z) * TAU * 2 - PI;
      a = lerp(a, dirAng, 0.25);
      let jitter = (noise(p.x * 0.03, p.y * 0.03) - 0.5) * 0.8;
      a += jitter;
      p.x += cos(a) * step;
      p.y += sin(a) * step;
      if (p.x < -60 || p.x > width + 60 || p.y < -60 || p.y > height + 60) break;
      pts.push({x: p.x, y: p.y});
      // occasional branch kink
      if (random() < 0.01) dirAng += random(-0.7, 0.7);
    }

    if (pts.length < 8) continue;

    // base seam
    noFill();
    stroke(45, 62, 92, 40);
    strokeWeight(random(1.4, 2.8));
    beginShape();
    for (let q of pts) vertex(q.x, q.y);
    endShape();

    // highlight vein
    stroke(48, 50, 100, 32);
    strokeWeight(random(0.6, 1.2));
    beginShape();
    for (let j = 0; j < pts.length; j++) {
      if (j % 2 === 0) continue; // broken mica shimmer
      let q = pts[j];
      vertex(q.x + random(-0.6, 0.6), q.y + random(-0.6, 0.6));
    }
    endShape();
  }
}

function drawSpeckles() {
  let N = 900;
  noStroke();
  for (let i = 0; i < N; i++) {
    let x = random(width);
    let y = random(height);
    let edgeBias = min(min(x, width - x), min(y, height - y)) / (min(width, height) * 0.5);
    let a = map(edgeBias, 0, 1, 26, 6) * random(0.6, 1.0);
    fill(0, 0, 100, a);
    let r = random(0.4, 1.8);
    ellipse(x + random(-0.4, 0.4), y + random(-0.4, 0.4), r, r);
  }
}

function softHalos(center, rings, baseR, col) {
  noStroke();
  for (let i = 0; i < rings; i++) {
    let rr = baseR * (1 + i * random(0.4, 0.9));
    let steps = 60;
    for (let j = steps; j >= 0; j--) {
      let t = j / steps;
      let a = alpha(col) * (0.2 + 0.8 * pow(t, 1.4));
      fill(hue(col), saturation(col), brightness(col), a);
      ellipse(center.x, center.y, rr * t * 2, rr * t * 2);
    }
  }
}

function vignette(cInner, cOuter, steps) {
  push();
  noStroke();
  for (let i = 0; i < steps; i++) {
    let t = i / (steps - 1);
    let c = lerpColor(cInner, cOuter, t);
    fill(c);
    let m = map(t, 0, 1, 0.9, 1.25);
    rectMode(CENTER);
    rect(width/2, height/2, width * m, height * m, 40);
  }
  pop();
}

function edgeSeed() {
  let side = floor(random(4));
  if (side === 0) return createVector(random(width), -10);
  if (side === 1) return createVector(width + 10, random(height));
  if (side === 2) return createVector(random(width), height + 10);
  return createVector(-10, random(height));
}

// Smoothstep utility
function smoothstep(a, b, x) {
  x = constrain((x - a) / (b - a), 0, 1);
  return x * x * (3 - 2 * x);
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  colorMode(HSB, 360, 100, 100, 1);
  noStroke();

  const cx = width * 0.5;
  const cy = height * 0.5;

  // Base nocturne
  background(220, 60, 6, 1);

  // Gradient radial sombre
  push();
  noStroke();
  for (let i = 260; i >= 0; i--) {
    const t = i / 260;
    const r = lerp(max(width, height) * 1.3, 0, t);
    const br = lerp(6, 12, 1 - pow(t, 1.4));
    fill(220, 45, br, 0.28);
    ellipse(cx, cy, r, r * 1.06);
  }
  pop();

  // Larges voiles de couleur: deux rives (froid/chaud)
  drawColorWashes(cx, cy);

  // Filaments qui se cherchent et se mêlent
  drawFilaments(cx, cy);

  // Halo central, respiration
  drawCentralGlow(cx, cy);

  // Veines dorées (kintsugi)
  drawGoldSeams(cx, cy);

  // Poussières de lumière
  drawSpeckles(cx, cy);

  noLoop();
}

function draw() {}

// Couche de voiles colorés
function drawColorWashes(cx, cy) {
  // FROID (gauche)
  for (let i = 0; i < 170; i++) {
    const x = width * 0.26 + randomGaussian() * 80;
    const y = cy + randomGaussian() * 280;
    const w = random(520, 1150);
    const h = w * random(0.8, 1.4);
    fill(random(195, 210), random(35, 68), random(35, 62), 0.085);
    ellipse(x, y, w, h);
  }
  // CHAUD (droite)
  for (let i = 0; i < 170; i++) {
    const x = width * 0.74 + randomGaussian() * 80;
    const y = cy + randomGaussian() * 280;
    const w = random(520, 1150);
    const h = w * random(0.8, 1.4);
    fill(random(10, 22), random(55, 85), random(55, 92), 0.085);
    ellipse(x, y, w, h);
  }
  // Voile central doux pour unir
  for (let i = 0; i < 120; i++) {
    const ang = random(TWO_PI);
    const rr = random(40, 380);
    const x = cx + cos(ang) * rr * random(0.8, 1.2);
    const y = cy + sin(ang) * rr * random(0.8, 1.2);
    const w = random(280, 680);
    const h = w * random(0.8, 1.3);
    fill(random(18, 38), random(25, 60), random(70, 96), 0.06);
    ellipse(x, y, w, h);
  }
}

// Filaments interconnectés
function drawFilaments(cx, cy) {
  const sc = 0.0016;
  const pathsPerSide = 1500;

  // Couleurs de départ
  const coolA = color(200, 60, 70, 0.14);
  const warmA = color(14, 75, 86, 0.14);
  const goldA = color(42, 58, 100, 0.24);

  strokeCap(ROUND);

  // Groupe gauche (froid)
  for (let p = 0; p < pathsPerSide; p++) {
    let x = random(width * 0.03, width * 0.32) + randomGaussian() * 12;
    let y = cy + randomGaussian() * 520;
    let px = x, py = y;
    const steps = floor(random(65, 120));
    const sw = random(0.6, 1.3);
    for (let i = 0; i < steps; i++) {
      const d = dist(x, y, cx, cy);
      const mixT = constrain(1 - d / 720, 0, 1);
      const c = lerpColor(coolA, goldA, pow(mixT, 1.6));
      strokeWeight(sw * (0.9 + 0.25 * noise(x * 0.01, y * 0.01)));
      stroke(c);

      const aN = noise(x * sc, y * sc) * TWO_PI * 2.0;
      const aS = atan2(y - cy, x - cx) + HALF_PI;
      let vx = cos(aN) * 0.6 + cos(aS) * 0.9 + (cx - x) * 0.00085;
      let vy = sin(aN) * 0.6 + sin(aS) * 0.9 + (cy - y) * 0.00085;
      const m = sqrt(vx * vx + vy * vy) + 1e-9;
      vx /= m; vy /= m;
      const step = 1.6 + noise(x * 0.003, y * 0.003) * 0.6;

      const nx = x + vx * step + random(-0.18, 0.18);
      const ny = y + vy * step + random(-0.18, 0.18);

      line(px, py, nx, ny);
      px = x; py = y;
      x = nx; y = ny;

      if (x < -40 || x > width + 40 || y < -40 || y > height + 40) break;
      if (d < 22) break;
    }
  }

  // Groupe droit (chaud)
  for (let p = 0; p < pathsPerSide; p++) {
    let x = random(width * 0.68, width * 0.97) + randomGaussian() * 12;
    let y = cy + randomGaussian() * 520;
    let px = x, py = y;
    const steps = floor(random(65, 120));
    const sw = random(0.6, 1.3);
    for (let i = 0; i < steps; i++) {
      const d = dist(x, y, cx, cy);
      const mixT = constrain(1 - d / 720, 0, 1);
      const c = lerpColor(warmA, goldA, pow(mixT, 1.6));
      strokeWeight(sw * (0.9 + 0.25 * noise(x * 0.01, y * 0.01 + 10)));
      stroke(c);

      const aN = noise(x * sc + 1000, y * sc + 200) * TWO_PI * 2.0;
      const aS = atan2(y - cy, x - cx) + HALF_PI;
      let vx = cos(aN) * 0.6 + cos(aS) * 0.9 + (cx - x) * 0.00085;
      let vy = sin(aN) * 0.6 + sin(aS) * 0.9 + (cy - y) * 0.00085;
      const m = sqrt(vx * vx + vy * vy) + 1e-9;
      vx /= m; vy /= m;
      const step = 1.6 + noise(x * 0.003 + 10, y * 0.003 + 10) * 0.6;

      const nx = x + vx * step + random(-0.18, 0.18);
      const ny = y + vy * step + random(-0.18, 0.18);

      line(px, py, nx, ny);
      px = x; py = y;
      x = nx; y = ny;

      if (x < -40 || x > width + 40 || y < -40 || y > height + 40) break;
      if (d < 22) break;
    }
  }
}

// Halo central
function drawCentralGlow(cx, cy) {
  push();
  blendMode(SCREEN);
  noStroke();
  // Pulsations douces
  for (let i = 0; i < 16; i++) {
    const t = i / 15;
    const r = lerp(780, 140, t);
    fill(35 + random(-4, 6), 42 + random(-6, 10), 96, 0.045 * (1 - t));
    ellipse(cx, cy, r, r * 0.98);
  }
  // Coeur plus chaud
  for (let i = 0; i < 10; i++) {
    const t = i / 9;
    const r = lerp(320, 60, t);
    fill(18 + random(-2, 3), 56 + random(-5, 8), 100, 0.06 * (1 - t));
    ellipse(cx, cy, r, r * 0.96);
  }
  pop();
}

// Veines dorées, réparations visibles
function drawGoldSeams(cx, cy) {
  const seams = 6;
  for (let s = 0; s < seams; s++) {
    // Départ sur un bord
    const edge = floor(random(4));
    let x, y;
    if (edge === 0) { x = -20; y = random(height); }
    else if (edge === 1) { x = width + 20; y = random(height); }
    else if (edge === 2) { x = random(width); y = -20; }
    else { x = random(width); y = height + 20; }

    let vx = 0, vy = 0;
    let px = x, py = y;
    const steps = 460;
    // Ombre brune
    push();
    noFill();
    for (let pass = 0; pass < 2; pass++) {
      // Pass 0: ombre; Pass 1: or
      if (pass === 0) {
        stroke(42, 40, 30, 0.35);
        strokeWeight(3.2);
      } else {
        stroke(45, 60, 100, 0.85);
        strokeWeight(1.2);
      }
      x = px; y = py; vx = 0; vy = 0;
      for (let i = 0; i < steps; i++) {
        const ang = noise(x * 0.002 + s * 10, y * 0.002 + s * 30) * TWO_PI * 3.0 - PI * 1.5;
        const toC = createVector(cx - x, cy - y).mult(0.0009);
        const nv = p5.Vector.fromAngle(ang, 1);
        vx = vx * 0.7 + nv.x * 0.7 + toC.x;
        vy = vy * 0.7 + nv.y * 0.7 + toC.y;
        const m = sqrt(vx * vx + vy * vy) + 1e-9;
        const step = 2.2;
        const nx = x + (vx / m) * step;
        const ny = y + (vy / m) * step;

        // Petites variations d'épaisseur et d'éclat
        if (pass === 1) {
          const flicker = 0.9 + 0.3 * noise(i * 0.05, s * 4);
          stroke(45, 60, 100, 0.65 * flicker);
          strokeWeight(1.0 + 0.4 * noise(i * 0.06 + 50));
        }

        line(x, y, nx, ny);
        x = nx; y = ny;

        if (x < -50 || x > width + 50 || y < -50 || y > height + 50) break;
      }
    }
    pop();
  }
}

// Poussières de lumière
function drawSpeckles(cx, cy) {
  push();
  blendMode(SCREEN);
  noStroke();

  // Nuage central chaud
  for (let i = 0; i < 1200; i++) {
    const ang = random(TWO_PI);
    const r = pow(random(), 1.2) * 640;
    const x = cx + cos(ang) * r * random(0.95, 1.05);
    const y = cy + sin(ang) * r * random(0.95, 1.05);
    const b = random(90, 100);
    const s = random(0.8, 2.2);
    fill(random(28, 46), random(18, 45), b, random(0.25, 0.8));
    ellipse(x, y, s, s);
  }

  // Quelques étincelles froides en périphérie
  for (let i = 0; i < 700; i++) {
    const x = random(width);
    const y = random(height);
    const d = dist(x, y, cx, cy);
    if (d > 600) {
      const s = random(0.6, 1.6);
      fill(random(190, 210), random(12, 28), random(70, 95), random(0.08, 0.22));
      ellipse(x, y, s, s);
    }
  }
  pop();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function draw() {
  colorMode(RGB, 255, 255, 255, 255);
  smooth();
  drawBackground();

  let left = createVector(width * 0.35, height * 0.5);
  let right = createVector(width * 0.65, height * 0.5);
  let mid = p5.Vector.add(left, right).mult(0.5);

  // Glows
  radialGlow(left.x, left.y, 820,
             color(255, 220, 150, 220),
             color(255, 150, 120, 110),
             color(40, 20, 30, 0));
  radialGlow(right.x, right.y, 820,
             color(255, 150, 220, 220),
             color(255, 120, 160, 110),
             color(30, 20, 50, 0));

  // Cores
  push();
  blendMode(ADD);
  coreGlow(left.x, left.y, 240, color(255, 210, 120, 140), color(255, 120, 80, 0));
  coreGlow(right.x, right.y, 240, color(255, 140, 210, 140), color(255, 90, 150, 0));
  pop();

  // Flowing bridges
  drawBridges(left, right, 240, true);
  drawBridges(right, left, 240, true);

  // Halos
  drawHalos(left, color(255, 190, 120, 40));
  drawHalos(right, color(255, 140, 200, 40));

  // Shared glow at the middle
  radialGlow(mid.x, mid.y, 300,
             color(255, 190, 230, 40),
             color(200, 140, 220, 18),
             color(0, 0, 0, 0));

  // Soft dust around the bridge
  sprinkle(mid, 650, color(255, 210, 240, 18), color(255, 180, 220, 6));

  // Subtle vignette
  vignette(120, 60);
}

function drawBackground() {
  let topCol = color(14, 16, 28);
  let bottomCol = color(24, 10, 34);
  noStroke();
  for (let y = 0; y < height; y++) {
    let t = y / (height - 1);
    let c = lerpColor(topCol, bottomCol, t);
    fill(c);
    rect(0, y, width, 1);
  }
  // Gentle vertical haze
  push();
  blendMode(SOFT_LIGHT);
  for (let i = 0; i < 180; i++) {
    let yy = noise(i * 0.11) * height;
    let a = 8 + 18 * noise(i * 0.31);
    fill(255, 255, 255, a);
    rect(0, yy, width, 1);
  }
  pop();
}

function radialGlow(cx, cy, rMax, cInner, cMid, cOuter) {
  noStroke();
  for (let r = rMax; r > 0; r -= 3) {
    let t = 1 - r / rMax; // 0 at edge, 1 at center
    let c;
    if (t < 0.55) {
      c = lerpColor(cOuter, cMid, t / 0.55);
    } else {
      c = lerpColor(cMid, cInner, (t - 0.55) / 0.45);
    }
    let a = map(r, 0, rMax, 220, 0);
    let cc = color(red(c), green(c), blue(c), a);
    fill(cc);
    ellipse(cx, cy, r * 2, r * 2);
  }
}

function coreGlow(cx, cy, rMax, cInner, cOuter) {
  noStroke();
  for (let r = rMax; r > 0; r -= 2) {
    let t = 1 - r / rMax;
    let c = lerpColor(cOuter, cInner, t);
    let a = map(r, 0, rMax, 160, 0);
    fill(red(c), green(c), blue(c), a);
    ellipse(cx, cy, r * 2, r * 2);
  }
}

function drawBridges(src, dst, count, luminous) {
  let ns = 0.0016;
  let maxSteps = 440;
  let stepLen = 2.1;
  let repelW = 0.38;
  let attractW = 1.22;

  let cA = color(255, 190, 120, 16); // from src
  let cB = color(255, 130, 200, 16); // to dst

  push();
  if (luminous) blendMode(ADD);
  strokeCap(ROUND);
  strokeJoin(ROUND);

  for (let i = 0; i < count; i++) {
    // Seeds on a facing semi-ring
    let baseR = 140 + random(220);
    let ang = random(-HALF_PI * 0.96, HALF_PI * 0.96);
    // bias seed a little toward the inner side between src and dst
    let dirToDst = atan2(dst.y - src.y, dst.x - src.x);
    let start = p5.Vector.fromAngle(dirToDst + ang).mult(baseR).add(src);

    let p = start.copy();
    let prev = p.copy();
    let reached = false;
    for (let s = 0; s < maxSteps; s++) {
      // Field = attract to dst, repel from src, plus gentle curl noise
      let toD = p5.Vector.sub(dst, p).normalize().mult(attractW);
      let fromS = p5.Vector.sub(p, src).normalize().mult(repelW);
      let theta = map(noise(p.x * ns, p.y * ns), 0, 1, -PI, PI);
      let curl = p5.Vector.fromAngle(theta).mult(0.55);

      let v = p5.Vector.add(toD, fromS).add(curl);
      v.normalize().mult(stepLen);

      p.add(v);

      // stop conditions
      if (dist(p.x, p.y, dst.x, dst.y) < 120) { reached = true; break; }
      if (p.x < -40 || p.x > width + 40 || p.y < -40 || p.y > height + 40) break;

      // Color progression
      let t = s / maxSteps;
      let cc = lerpColor(cA, cB, t);
      // Slight pulse based on curl for texture
      let pulse = 0.7 + 0.6 * noise(i * 0.13, s * 0.035);
      let w = 0.7 + 1.4 * (1.0 - abs(0.5 - t) * 1.8) * pulse;
      strokeWeight(w);
      stroke(red(cc), green(cc), blue(cc), alpha(cc));
      line(prev.x, prev.y, p.x, p.y);
      prev.set(p);
    }

    // If not quite reached, add a faint taper toward dst
    if (!reached) {
      let taper = p5.Vector.sub(dst, p).setMag(12 + random(12));
      let q = p5.Vector.add(p, taper);
      let cc = lerpColor(cA, cB, 0.95);
      strokeWeight(0.8);
      stroke(red(cc), green(cc), blue(cc), 10);
      line(p.x, p.y, q.x, q.y);
    }
  }
  pop();
}

function drawHalos(center, c) {
  noFill();
  push();
  blendMode(SCREEN);
  for (let k = 0; k < 7; k++) {
    let r = 260 + k * 48;
    let a = 30 - k * 3;
    stroke(red(c), green(c), blue(c), a);
    strokeWeight(1.2 + 0.6 * noise(k * 0.5));
    ellipse(center.x, center.y, r * 2, r * 2);
  }
  pop();
}

function sprinkle(mid, n, c1, c2) {
  noStroke();
  push();
  blendMode(SOFT_LIGHT);
  for (let i = 0; i < n; i++) {
    let ang = random(TWO_PI);
    let rad = 40 + pow(random(), 0.6) * 420; // denser near center
    let p = p5.Vector.fromAngle(ang).mult(rad).add(mid);
    let t = noise(p.x * 0.003, p.y * 0.003);
    let c = lerpColor(c1, c2, t);
    fill(red(c), green(c), blue(c), alpha(c));
    let sz = 0.8 + random(2.6) * (1.2 - t);
    ellipse(p.x, p.y, sz, sz);
  }
  pop();
}

function vignette(rings, maxAlpha) {
  noFill();
  push();
  blendMode(MULTIPLY);
  for (let i = 0; i < rings; i++) {
    let m = i;
    let a = map(i, 0, rings - 1, 0, maxAlpha);
    stroke(0, a);
    strokeWeight(1);
    rect(m, m, width - 2 * m, height - 2 * m, 6);
  }
  pop();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  colorMode(RGB, 255, 255, 255, 255);
  background(0);
  drawBackground();
  blendMode(SCREEN);

  // Bodies made of soft ellipses leaning toward center
  drawBody('left');
  drawBody('right');

  // Gentle threads that meet across the center
  drawThreads();

  // Shared luminous core
  drawCore();

  // Tiny sparks near the meeting area
  drawSparks();

  // Subtle vignette
  blendMode(MULTIPLY);
  vignette();
  blendMode(BLEND);
}

const yMin = 220;
const yMax = 1780;
const yRange = yMax - yMin;

function drawBackground() {
  // Vertical gradient
  let topC = color(12, 16, 40);
  let botC = color(42, 16, 44);
  noStroke();
  for (let y = 0; y < height; y++) {
    let t = y / (height - 1);
    let c = lerpColor(topC, botC, t);
    fill(c);
    rect(0, y, width, 1);
  }

  // Radial dusk glow
  let cx = width * 0.5;
  let cy = height * 0.53;
  let maxR = 1200;
  for (let r = maxR; r > 0; r -= 6) {
    let a = map(r, maxR, 0, 0, 40);
    fill(160, 110, 200, a * 0.35);
    ellipse(cx, cy, r * 2.2, r * 1.6);
    fill(255, 200, 160, a * 0.25);
    ellipse(cx, cy, r * 1.6, r * 1.2);
  }
}

function envY(y) {
  let t = (y - yMin) / yRange;
  t = constrain(t, 0, 1);
  return pow(sin(PI * t), 1.05);
}

function bodyCenter(side, y) {
  let dir = side === 'left' ? -1 : 1;
  let t = (y - yMin) / yRange;
  let base = 280;
  let centerPull = -dir * 115 * envY(y);
  let sw = (noise(y * 0.0015 + (side === 'left' ? 10.1 : 20.2)) * 2 - 1) * 90 * envY(y);
  let arc = dir * (t - 0.5) * 90;
  return width * 0.5 + dir * base + centerPull + sw + arc;
}

function thicknessAt(y) {
  return 60 + 220 * envY(y);
}

function palLeft(t) {
  // teal -> cobalt -> violet
  let c1 = color(32, 200, 205);
  let c2 = color(60, 100, 255);
  let c3 = color(150, 105, 255);
  return lerp3(c1, c2, c3, t);
}

function palRight(t) {
  // peach -> magenta -> crimson
  let c1 = color(255, 175, 125);
  let c2 = color(255, 95, 165);
  let c3 = color(255, 75, 100);
  return lerp3(c1, c2, c3, t);
}

function lerp3(c1, c2, c3, t) {
  t = constrain(t, 0, 1);
  if (t < 0.5) return lerpColor(c1, c2, t * 2);
  return lerpColor(c2, c3, (t - 0.5) * 2);
}

function drawBody(side) {
  noStroke();
  let seedShift = side === 'left' ? 111 : 222;

  for (let pass = 0; pass < 2; pass++) {
    for (let y = yMin; y <= yMax; y += 12) {
      let e = envY(y);
      let cx = bodyCenter(side, y);
      let t = (y - yMin) / yRange;
      let colT = constrain(0.25 + 0.7 * e + 0.15 * noise(y * 0.003 + seedShift + pass * 7.7), 0, 1);
      let col = side === 'left' ? palLeft(colT) : palRight(colT);

      let baseW = thicknessAt(y);
      let j = (noise(y * 0.02 + seedShift) - 0.5) * 18;
      let w = baseW + j + (pass === 0 ? 28 : 0);
      let h = w * (0.48 + noise(y * 0.01 + seedShift + 99) * 0.08);

      let a = 10 + 18 * e + (pass === 0 ? 6 : 0);
      let c = color(red(col), green(col), blue(col), a);
      fill(c);
      ellipse(cx + (pass === 0 ? (side === 'left' ? 4 : -4) : 0), y, w, h);
    }
  }
}

function drawThreads() {
  let N = 420;
  for (let i = 0; i < N; i++) {
    let y = randomGaussian(height * 0.52, height * 0.2);
    y = constrain(y, yMin + 20, yMax - 20);

    let e = envY(y);
    let tcol = constrain(0.3 + 0.7 * e + random(-0.05, 0.05), 0, 1);

    let cL = palLeft(tcol);
    let cR = palRight(tcol);
    let mix = constrain(0.45 + (e * 0.4) + random(-0.08, 0.08), 0, 1);
    let c = lerpColor(cL, cR, mix);
    let a = 12 + 28 * e;
    c.setAlpha(a);

    stroke(c);
    strokeWeight(0.6 + random(0, 1.2));

    let x1 = bodyCenter('left', y) + 0.26 * thicknessAt(y) + random(-8, 10);
    let x2 = bodyCenter('right', y) - 0.26 * thicknessAt(y) + random(-10, 8);

    let cp1x = x1 - random(10, 80);
    let cp2x = x2 + random(10, 80);
    let cp1y = y + random(-90, 90);
    let cp2y = y + random(-90, 90);

    noFill();
    bezier(x1, y, cp1x, cp1y, cp2x, cp2y, x2, y + random(-6, 6));

    // occasional double-pass for glow
    if (random() < 0.25) {
      let ca = color(red(c), green(c), blue(c), a * 0.6);
      stroke(ca);
      strokeWeight(0.3 + random(0, 0.8));
      bezier(x1 + random(-2, 2), y + random(-2, 2),
             cp1x + random(-4, 4), cp1y + random(-6, 6),
             cp2x + random(-4, 4), cp2y + random(-6, 6),
             x2 + random(-2, 2), y + random(-2, 2));
    }
  }
}

function drawCore() {
  let cx = width * 0.5;
  let cy = height * 0.52;
  noStroke();

  // Outer soft halo
  for (let r = 360; r > 100; r -= 6) {
    let t = map(r, 360, 100, 0, 1);
    let c = lerpColor(color(180, 140, 255, 10), color(255, 200, 160, 14), t);
    fill(c);
    ellipse(cx, cy, r * 2.1, r * 1.4);
  }

  // Inner bright heart of light (no text, only glow)
  for (let r = 120; r > 0; r -= 3) {
    let a = map(r, 120, 0, 18, 90);
    fill(255, 230, 200, a);
    ellipse(cx, cy, r * 2, r * 1.5);
  }
}

function drawSparks() {
  let cx = width * 0.5;
  let cy = height * 0.52;
  noStroke();
  let N = 320;
  for (let i = 0; i < N; i++) {
    let rx = randomGaussian(0, 240);
    let ry = randomGaussian(0, 160);
    let x = cx + rx;
    let y = cy + ry;
    let base = random(1.2, 3.2);
    let warm = color(255, 220, 190, random(40, 110));
    let cool = color(210, 230, 255, random(30, 90));
    let c = lerpColor(warm, cool, random(0.2, 0.8));
    fill(red(c), green(c), blue(c), alpha(c) * 0.6);
    ellipse(x, y, base * 2.4, base * 2.4);
    fill(red(c), green(c), blue(c), alpha(c));
    ellipse(x, y, base, base);
  }
}

function vignette() {
  noFill();
  let steps = 40;
  for (let i = 0; i < steps; i++) {
    let t = i / (steps - 1);
    let a = map(t, 0, 1, 0, 80);
    stroke(10, 8, 16, a);
    strokeWeight(60);
    rectMode(CENTER);
    rect(width / 2, height / 2, width + i * 30, height + i * 30);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  colorMode(RGB, 255, 255, 255, 255);
  noStroke();
  backgroundGradient();

  // Subtle distant dust
  drawDust(900);

  // Two luminous bodies approaching
  let cx1 = 600, cx2 = 1000, cy = 1000, r = 520;

  blendMode(SCREEN);
  radialGradient(cx1, cy, r, color('#ff6fa6'), color('#2a1330'), 420, 1.7);
  radialGradient(cx2, cy, r, color('#ffb36b'), color('#2a1330'), 420, 1.7);

  // Central shared glow (the union)
  radialGradient(width*0.5, cy, 260, color('#fff2d9'), color(255, 210, 140, 0), 280, 1.4);
  blendMode(BLEND);

  // Threads connecting both sides
  drawThreads(720, cx1, cx2, cy, r);

  // Soft sparks near the union
  drawSparks(220, width*0.5, cy, 260);

  // Gentle vignette to cradle the light
  vignette(width*0.5, cy, max(width, height)*0.78, 0.0, 0.55);
}

// ---------- Background ----------
function backgroundGradient() {
  let topC = color('#0a0f2a');
  let midC = color('#1b0e1c');
  let botC = color('#0a0f2a');

  let midY = height * 0.55;
  for (let y = 0; y < height; y+=2) {
    let c;
    if (y < midY) {
      let t = y / midY;
      c = lerpColor(topC, midC, t);
    } else {
      let t = (y - midY) / (height - midY);
      c = lerpColor(midC, botC, t);
    }
    stroke(c);
    line(0, y, width, y);
  }

  // Faint dusk clouds
  noStroke();
  for (let i = 0; i < 120; i++) {
    let x = random(width);
    let y = random(height);
    let rr = random(120, 380);
    let cc = color(40+random(10), 20+random(10), 50+random(20), random(10, 28));
    fill(cc);
    ellipse(x, y, rr, rr);
  }
}

// ---------- Radial gradient helper ----------
function radialGradient(cx, cy, r, innerCol, outerCol, steps, power) {
  noStroke();
  for (let i = steps; i >= 1; i--) {
    let t = i / steps;            // 1 at edge, -> 0 toward center
    let amt = pow(1 - t, power);  // 0 at edge, -> 1 at center
    let c = lerpColor(outerCol, innerCol, amt);
    let a = 255 * amt;
    fill(red(c), green(c), blue(c), a);
    ellipse(cx, cy, (r * 2 * t), (r * 2 * t));
  }
}

// ---------- Dust ----------
function drawDust(n) {
  noStroke();
  for (let i = 0; i < n; i++) {
    let x = random(width);
    let y = random(height);
    let s = random(0.6, 2.2);
    let glow = 40 + 180 * pow(noise(x*0.0015, y*0.0015), 2);
    let hueBias = random() < 0.35 ? color(200, 170, 255) : color(255, 220, 200);
    fill(red(hueBias), green(hueBias), blue(hueBias), glow * 0.25);
    ellipse(x, y, s, s);
  }
}

// ---------- Threads ----------
function drawThreads(n, cx1, cx2, cy, r) {
  strokeCap(ROUND);
  strokeJoin(ROUND);

  let startX = cx1 - r * 0.42;
  let endX   = cx2 + r * 0.42;

  let cA = color('#ff6fa6');
  let cB = color('#ffd08a');
  let cC = color('#ff9f80');

  for (let i = 0; i < n; i++) {
    let seed = random(1000, 10000);
    let baseY = cy + randomGaussian(0, 160);
    let amp = random(60, 160);
    let waviness = random(1.0, 2.2);
    let bend = random(-0.002, 0.002);

    // color palette blending
    let m = random();
    let col = m < 0.5
      ? lerpColor(cA, cB, m*2)
      : lerpColor(cB, cC, (m-0.5)*2);
    let alpha = 32 + random(22, 96);
    stroke(red(col), green(col), blue(col), alpha);
    strokeWeight(random(0.6, 2.1));

    noFill();
    beginShape();
    let steps = 160;
    for (let j = 0; j <= steps; j++) {
      let t = j / steps;
      let x = lerp(startX, endX, t);

      // Curve pulls gently toward center
      let pull = -40 * pow((t - 0.5), 2) + 10;

      // Flow-field wiggle
      let n1 = noise(t * 1.7, seed) - 0.5;
      let n2 = noise(t * 3.2 + 100, seed * 0.5 + 30) - 0.5;
      let wig = (n1 * 0.7 + n2 * 0.3) * 2.0;

      // Modulate by bell shape to tighten near the center
      let bell = sin(PI * t);
      let y = baseY + wig * amp * bell * waviness + pull + bend * (x - width * 0.5) * (x - width * 0.5) * 0.0002;

      vertex(x, y);
    }
    endShape();

    // Occasional brighter ribbon for depth
    if (random() < 0.06) {
      let cc = lerpColor(col, color('#ffe6bf'), 0.6);
      stroke(red(cc), green(cc), blue(cc), 28);
      strokeWeight(random(3.0, 6.0));
      beginShape();
      for (let j = 0; j <= steps; j++) {
        let t = j / steps;
        let x = lerp(startX, endX, t);
        let n1 = noise(t * 1.7, seed+999) - 0.5;
        let bell = sin(PI * t);
        let y = baseY + n1 * amp * 0.5 * bell - 10 * pow(t - 0.5, 2);
        vertex(x, y);
      }
      endShape();
    }
  }
}

// ---------- Sparks near union ----------
function drawSparks(count, cx, cy, r) {
  noStroke();
  for (let i = 0; i < count; i++) {
    let a = random(TWO_PI);
    let rr = r * pow(random(), 0.8) * 0.9;
    let x = cx + cos(a) * rr * random(0.2, 1.0);
    let y = cy + sin(a) * rr * random(0.2, 1.0);

    let s = random(1.2, 3.6);
    let c = random() < 0.5 ? color('#fff2d9') : color('#ffd8a8');
    fill(red(c), green(c), blue(c), random(90, 190));
    ellipse(x, y, s, s);

    // tiny glow halo
    fill(red(c), green(c), blue(c), 20);
    ellipse(x, y, s*3.2, s*3.2);
  }
}

// ---------- Vignette ----------
function vignette(cx, cy, r, innerAlpha, outerAlpha) {
  let steps = 220;
  let inner = color(0, 0, 0, 255 * innerAlpha);
  let outer = color(0, 0, 0, 255 * outerAlpha);
  for (let i = 1; i <= steps; i++) {
    let t = i / steps;
    let c = lerpColor(inner, outer, t);
    fill(c);
    ellipse(cx, cy, r * t * 2, r * t * 2);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();
  smooth();
}

function draw() {
  let cx = width * 0.5;
  let cy = height * 0.55;

  // Background vertical gradient
  for (let y = 0; y < height; y++) {
    let t = y / (height - 1);
    let c1 = color(258, 38, 10);   // deep indigo
    let c2 = color(280, 28, 18);   // dusky violet
    let c = lerpColor(c1, c2, t);
    stroke(c);
    line(0, y, width, y);
  }

  // Soft central warm glow
  noStroke();
  for (let i = 0; i < 120; i++) {
    let tt = i / 119;
    let r = lerp(50, 980, tt);
    let a = 22 * (1 - pow(tt, 1.35));
    fill(26, 55, 95, a); // warm amber glow
    ellipse(cx, cy, r * 1.25, r);
  }
  for (let i = 0; i < 80; i++) {
    let tt = i / 79;
    let r = lerp(40, 600, tt);
    let a = 18 * (1 - pow(tt, 1.2));
    fill(345, 40, 100, a); // rosy inner glow
    ellipse(cx, cy - 30, r, r * 0.8);
  }

  // Subtle vignette
  for (let i = 0; i < 140; i++) {
    let tt = i / 139;
    let a = 10 * pow(tt, 1.4);
    fill(260, 40, 8, a);
    let m = lerp(max(width, height) * 1.05, max(width, height) * 1.8, tt);
    ellipse(cx, cy + 60, m * 1.3, m * 1.15);
  }

  // Two approaching flows (left and right)
  strokeCap(ROUND);
  drawFlowFieldSide(-1, cx, cy); // left
  drawFlowFieldSide(1, cx, cy);  // right

  // Edge shimmer near the shared space, without crossing the gap
  drawShimmer(cx, cy);

  // Gentle floating specks for atmosphere
  noiseTexture();
}

// FLOW FIELD FOR EACH SIDE
function drawFlowFieldSide(side, cx, cy) {
  let count = 1500;
  let hueBase = side < 0 ? 335 : 28; // magenta vs amber
  let maxR = 900;
  let gapR = 92; // leave breathing space at center
  let swirlScale = 0.002;

  for (let i = 0; i < count; i++) {
    // start positions
    let sx, sy;
    if (side < 0) {
      sx = random(cx - 780, cx - 150);
    } else {
      sx = random(cx + 150, cx + 780);
    }
    // concentrate around the middle with gentle spread
    sy = cy + randomGaussian() * 260;

    let p = createVector(sx, sy);

    // color jitter per strand
    let hJ = random(-6, 6);
    let sJ = random(-8, 8);
    let bJ = random(-6, 6);

    let steps = floor(random(70, 125));
    let len = random(4.0, 7.2);

    // base alpha and weight
    let baseAlpha = random(10, 24);
    let wFar = random(3.0, 7.0);

    // sometimes longer, silkier strands
    if (random() < 0.18) {
      steps += floor(random(40, 80));
      baseAlpha *= 0.75;
      wFar *= 0.8;
    }

    let prev = p.copy();
    for (let k = 0; k < steps; k++) {
      let d = dist(p.x, p.y, cx, cy);

      // Stop near center to preserve the gap
      if (d < gapR + random(-6, 6)) break;

      // Prevent crossing the midline
      if (side < 0 && p.x >= cx - 10) break;
      if (side > 0 && p.x <= cx + 10) break;

      // Flow direction: blend of inward pull and side-specific swirl
      let dir = flowDir(p.x, p.y, cx, cy, side, swirlScale);
      let jitterA = map(noise(p.x * 0.007, p.y * 0.007, k * 0.01), 0, 1, -0.35, 0.35);
      dir.rotate(jitterA);
      let stepLen = len * map(d, maxR, 0, 1.15, 0.42);
      p.add(dir.mult(stepLen));

      // color and weight by proximity
      let t = constrain(map(d, maxR, gapR, 0, 1), 0, 1);
      let s = lerp(62 + sJ, 18 + sJ, pow(1 - t, 0.8));
      let b = lerp(68 + bJ, 100 + bJ, pow(1 - t, 1.2));

      stroke(hueBase + hJ, s, b, baseAlpha * (0.65 + 0.35 * (1 - t)));
      let w = lerp(wFar, 0.6, pow(1 - t, 1.1));
      strokeWeight(w);

      line(prev.x, prev.y, p.x, p.y);
      prev.set(p.x, p.y);
    }

    // Soft shoulder bloom at far ends to give body
    if (random() < 0.12) {
      let d0 = dist(sx, sy, cx, cy);
      let t0 = constrain(map(d0, maxR, gapR, 0, 1), 0, 1);
      let s0 = lerp(58, 18, pow(1 - t0, 0.8));
      let b0 = lerp(64, 98, pow(1 - t0, 1.1));
      fill(hueBase, s0, b0, 10);
      noStroke();
      let rr = random(18, 36);
      ellipse(sx + random(-6, 6), sy + random(-6, 6), rr * 1.4, rr);
    }
  }
}

function flowDir(x, y, cx, cy, side, swirlScale) {
  let px = x;
  let py = y;
  let vx = cx - px;
  let vy = cy - py;
  let mag = sqrt(vx * vx + vy * vy) + 0.0001;
  vx /= mag;
  vy /= mag;

  // Tangential component for embrace-like curl
  let tx = -vy;
  let ty = vx;

  // Noise-based angle modulation
  let n = noise(px * swirlScale, py * swirlScale);
  let n2 = noise(px * swirlScale * 0.6 + 10, py * swirlScale * 0.6 + 3.7);
  let swirl = map(n, 0, 1, -0.6, 0.6) + map(n2, 0, 1, -0.35, 0.35);

  // Blend inward pull and side-specific swirl around center
  let inwardW = 0.86;
  let swirlW = 0.54 * side;

  let dx = vx * inwardW + tx * swirlW + swirl * 0.08;
  let dy = vy * inwardW + ty * swirlW + swirl * 0.08;

  let dm = sqrt(dx * dx + dy * dy) + 0.0001;
  dx /= dm;
  dy /= dm;

  return createVector(dx, dy);
}

// Shimmering edge near the gap (does not cross the empty space)
function drawShimmer(cx, cy) {
  noStroke();
  for (let i = 0; i < 400; i++) {
    let ang = random(-PI * 0.4, PI * 0.4);
    let r = random(102, 150);
    let side = random() < 0.5 ? -1 : 1;
    let x = cx + cos(ang) * r * 0.8 + side * random(16, 42);
    let y = cy + sin(ang) * r * 0.6 + random(-22, 22);
    let a = random(22, 50);
    let hue = side < 0 ? 338 : 26;
    fill(hue, 18, 100, a);
    let sz = random(1.4, 3.6);
    ellipse(x, y, sz, sz);
  }

  // Central breath-like glow, preserving the gap
  for (let i = 0; i < 35; i++) {
    let t = i / 34;
    let w = lerp(220, 120, t);
    let h = lerp(160, 80, t);
    let a = 10 * (1 - t);
    noStroke();
    fill(20, 8, 100, a);
    ellipse(cx, cy, w, h);
  }
}

// Subtle grain and floating dust
function noiseTexture() {
  for (let i = 0; i < 16000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.01, y * 0.01);
    let a = map(n, 0, 1, 0, 6);
    noStroke();
    fill(0, 0, 100, a);
    rect(x, y, 1, 1);
  }

  // Few larger soft motes
  for (let i = 0; i < 220; i++) {
    let x = random(width);
    let y = random(height);
    let a = random(6, 14);
    fill(0, 0, 100, a);
    noStroke();
    let r = random(1.5, 3.5);
    ellipse(x, y, r, r);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
  colorMode(RGB, 255, 255, 255, 255);
}

function draw() {
  // background gradient with subtle noise texture
  noStroke();
  for (let y = 0; y < height; y += 2) {
    let t = y / (height - 1);
    let n = (noise(0.3, t * 3.0) - 0.5) * 0.2;
    let cTop = color(10, 12, 24);
    let cBottom = color(28, 10, 22);
    let c = lerpColor(cTop, cBottom, constrain(t * 0.9 + n, 0, 1));
    fill(c);
    rect(0, y, width, 2);
  }

  // parameters for two luminous beings
  let L = { x: 520, y: 1240, r: 420 };
  let R = { x: 1100, y: 780, r: 420 };

  let colLCore = color(255, 150, 160);
  let colLEdge = color(255, 90, 140);
  let colRCore = color(150, 160, 255);
  let colREdge = color(95, 130, 255);

  // additive glows
  blendMode(ADD);
  radialGlow(L.x, L.y, L.r, colLCore, colLEdge, 300, 0.02, 1.04);
  radialGlow(R.x, R.y, R.r, colRCore, colREdge, 300, 0.02, 0.96);

  // petal-like aura around each orb
  let faceL = atan2(R.y - L.y, R.x - L.x);
  let faceR = atan2(L.y - R.y, L.x - R.x);
  ringPetals(L.x, L.y, L.r, 900, colLCore, faceL, 1.6);
  ringPetals(R.x, R.y, R.r, 900, colRCore, faceR, 1.6);

  // gentle background stardust
  stardust(1200, color(230, 220, 255), 0.08);

  // weaving threads between the two
  let colThreadL = color(255, 140, 180);
  let colThreadR = color(140, 170, 255);
  for (let k = 0; k < 360; k++) {
    let rs = L.r * random(0.08, 0.85);
    let re = R.r * random(0.08, 0.85);
    let aL = faceL + randomGaussian(0, 0.9);
    let aR = faceR + randomGaussian(0, 0.9);
    let sx = L.x + cos(aL) * rs;
    let sy = L.y + sin(aL) * rs;
    let ex = R.x + cos(aR) * re;
    let ey = R.y + sin(aR) * re;
    let amp = random(60, 240);
    let steps = floor(random(70, 120));
    let sizeBase = random(0.9, 1.8);
    drawThread(sx, sy, ex, ey, amp, steps, sizeBase, colThreadL, colThreadR);
  }

  // a few broader, softer ribbons to hint an embrace
  for (let k = 0; k < 36; k++) {
    let rs = L.r * random(0.15, 0.75);
    let re = R.r * random(0.15, 0.75);
    let aL = faceL + randomGaussian(0, 0.6);
    let aR = faceR + randomGaussian(0, 0.6);
    let sx = L.x + cos(aL) * rs;
    let sy = L.y + sin(aL) * rs;
    let ex = R.x + cos(aR) * re;
    let ey = R.y + sin(aR) * re;
    softRibbon(sx, sy, ex, ey, random(80, 200), color(255, 160, 180, 16), color(160, 180, 255, 16));
  }

  // shared luminous middle — brighter but gentle
  let mid = { x: (L.x + R.x) * 0.5, y: (L.y + R.y) * 0.5 };
  radialGlow(mid.x, mid.y, 200, color(255, 240, 250), color(200, 180, 240), 180, 0.03, 1.0);

  // light grains near overlap to add breath
  clusteredGrain(mid.x, mid.y, 3600, 240, color(255, 230, 250, 10), color(220, 230, 255, 10));

  // faint outer halo tying both together
  outerHalo((L.x + R.x) / 2, (L.y + R.y) / 2, 1100, color(120, 120, 200, 6), 120);

  blendMode(BLEND);
}

// Helpers

function radialGlow(cx, cy, radius, cInner, cOuter, steps, noiseAmt, yStretch) {
  push();
  translate(cx, cy);
  scale(1, yStretch || 1);
  noStroke();
  for (let j = 0; j < steps; j++) {
    let t = j / (steps - 1); // 0: outer, 1: inner
    let ease = pow(t, 0.85);
    let r = lerp(radius, 0, ease);
    let jitter = (noise(cx * 0.002 + t * 5.7, cy * 0.002) - 0.5) * radius * noiseAmt * (1 - t);
    let rr = max(0, r + jitter);
    let col = lerpColor(cOuter, cInner, t);
    let a = 3 + 95 * pow(t, 2.2);
    col.setAlpha(a);
    fill(col);
    ellipse(0, 0, rr * 2, rr * 2);
  }
  pop();
}

function ringPetals(cx, cy, r, count, baseCol, facingAngle, spread) {
  noStroke();
  for (let i = 0; i < count; i++) {
    let ang = facingAngle + randomGaussian(0, spread);
    let rr = r * random(0.6, 1.15);
    let px = cx + cos(ang) * rr + randomGaussian(0, 6);
    let py = cy + sin(ang) * rr + randomGaussian(0, 6);
    let sz = random(2, 7);
    let c = color(red(baseCol), green(baseCol), blue(baseCol));
    c.setAlpha(random(6, 22));
    fill(c);
    ellipse(px, py, sz, sz);
  }
}

function stardust(n, base, density) {
  noStroke();
  for (let i = 0; i < n; i++) {
    let x = random(width);
    let y = random(height);
    let v = noise(x * 0.002, y * 0.002);
    if (v < 0.4 || random() > density) continue;
    let b = lerpColor(color(200, 200, 240), base, random(0.4, 1));
    b.setAlpha(random(4, 14));
    fill(b);
    let s = random(0.6, 1.8);
    ellipse(x, y, s, s);
  }
}

function drawThread(sx, sy, ex, ey, amp, steps, sizeBase, cStart, cEnd) {
  let vMag = dist(sx, sy, ex, ey);
  let dir = atan2(ey - sy, ex - sx);
  let norm = dir + HALF_PI;
  let sgn = random() < 0.5 ? -1 : 1;
  let c1 = {
    x: sx + cos(dir) * vMag * 0.28 + cos(norm) * amp * sgn,
    y: sy + sin(dir) * vMag * 0.28 + sin(norm) * amp * sgn
  };
  let c2 = {
    x: sx + cos(dir) * vMag * 0.72 - cos(norm) * amp * sgn * 0.85,
    y: sy + sin(dir) * vMag * 0.72 - sin(norm) * amp * sgn * 0.85
  };
  noStroke();
  for (let i = 0; i < steps; i++) {
    let t = i / (steps - 1);
    let x = bezierPoint(sx, c1.x, c2.x, ex, t);
    let y = bezierPoint(sy, c1.y, c2.y, ey, t);
    let w = sin(PI * t);
    let dn = (noise(x * 0.003 + t * 2.0, y * 0.003) - 0.5);
    x += cos(norm) * dn * amp * 0.15 * w;
    y += sin(norm) * dn * amp * 0.15 * w;
    let cc = lerpColor(cStart, cEnd, t);
    let a = 6 + 18 * pow(w, 1.8) * random(0.7, 1.0);
    cc.setAlpha(a);
    fill(cc);
    let sz = 0.7 + sizeBase * w * random(0.7, 1.3);
    ellipse(x, y, sz, sz);
  }
}

function softRibbon(sx, sy, ex, ey, amp, colA, colB) {
  let vMag = dist(sx, sy, ex, ey);
  let dir = atan2(ey - sy, ex - sx);
  let norm = dir + HALF_PI;
  let sgn = random() < 0.5 ? -1 : 1;
  let c1 = {
    x: sx + cos(dir) * vMag * 0.25 + cos(norm) * amp * sgn,
    y: sy + sin(dir) * vMag * 0.25 + sin(norm) * amp * sgn
  };
  let c2 = {
    x: sx + cos(dir) * vMag * 0.75 - cos(norm) * amp * sgn * 0.8,
    y: sy + sin(dir) * vMag * 0.75 - sin(norm) * amp * sgn * 0.8
  };
  let steps = 120;
  noFill();
  for (let pass = 0; pass < 2; pass++) {
    let cc = pass === 0 ? colA : colB;
    stroke(cc);
    strokeWeight(pass === 0 ? 2.2 : 1.2);
    beginShape();
    for (let i = 0; i < steps; i++) {
      let t = i / (steps - 1);
      let x = bezierPoint(sx, c1.x, c2.x, ex, t);
      let y = bezierPoint(sy, c1.y, c2.y, ey, t);
      let w = sin(PI * t);
      let dn = (noise(x * 0.002, y * 0.002 + pass * 10) - 0.5) * amp * 0.08 * w;
      x += cos(norm) * dn;
      y += sin(norm) * dn;
      vertex(x, y);
    }
    endShape();
  }
}

function clusteredGrain(cx, cy, count, radius, colA, colB) {
  noStroke();
  for (let i = 0; i < count; i++) {
    let ang = random(TAU);
    let rr = radius * pow(random(), 0.6);
    let x = cx + cos(ang) * rr + randomGaussian(0, 1.2);
    let y = cy + sin(ang) * rr + randomGaussian(0, 1.2);
    let t = rr / radius;
    let c = lerpColor(colA, colB, t);
    c.setAlpha(8 + 10 * (1 - t));
    fill(c);
    ellipse(x, y, random(0.7, 1.8), random(0.7, 1.8));
  }
}

function outerHalo(cx, cy, r, col, steps) {
  push();
  noStroke();
  for (let i = 0; i < steps; i++) {
    let t = i / (steps - 1);
    let rr = lerp(r * 1.2, r * 0.6, t);
    let c = color(red(col), green(col), blue(col), 6 * (1 - t));
    fill(c);
    ellipse(cx, cy, rr * 2, rr * 2);
  }
  pop();
}

let atrs = [];
let hc = {x: 0, y: 0, rx: 0, ry: 0};
let center;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();

  center = createVector(width * 0.5, height * 0.55);
  hc.x = center.x;
  hc.y = center.y + 20;
  hc.rx = 320;
  hc.ry = 240;

  // Attractors: 多个温柔的引力中心
  atrs = [
    {x: width * 0.38, y: height * 0.42, str: 30, swirl: 70},
    {x: width * 0.62, y: height * 0.58, str: 32, swirl: -65},
    {x: width * 0.50, y: height * 0.76, str: 26, swirl: 50}
  ];

  drawBackground();
  drawFlows();
  drawAura();
  drawKintsugiCracks();
  subtleVignette();
}

function drawBackground() {
  noStroke();
  // 柔和的径向背景：中心温暖，边缘深邃
  let cx = center.x, cy = center.y;
  let rmax = dist(0, 0, width, height) * 0.75;
  let inner = color(22, 30, 96, 100);   // 温暖浅色
  let mid   = color(270, 25, 40, 100);  // 中间过渡
  let outer = color(260, 40, 12, 100);  // 深蓝紫
  for (let r = rmax; r > 0; r -= 3) {
    let t = r / rmax;
    let c;
    if (t < 0.55) {
      c = lerpColor(inner, mid, smoothstep(0, 0.55, t));
    } else {
      c = lerpColor(mid, outer, smoothstep(0.55, 1.0, t));
    }
    fill(c);
    ellipse(cx, cy, r * 2, r * 2);
  }

  // 轻薄的暖雾，靠近中心
  let layers = 7;
  for (let i = 0; i < layers; i++) {
    let rr = rmax * (0.42 + 0.1 * i);
    fill(20, 40, 90, 5);
    ellipse(cx + random(-10, 10), cy + random(-8, 8), rr * 1.1, rr * 1.0);
  }
}

function drawFlows() {
  // 三层关系流：外层清凉，中层过渡，内层温暖
  let layers = [
    {count: 3200, steps: 90, alphaMin: 6, alphaMax: 14, swMin: 0.5, swMax: 1.2, speed: 0.95, edgeBias: 0.75},
    {count: 2700, steps: 110, alphaMin: 8, alphaMax: 18, swMin: 0.6, swMax: 1.4, speed: 1.00, edgeBias: 0.40},
    {count: 2400, steps: 130, alphaMin: 10, alphaMax: 22, swMin: 0.6, swMax: 1.6, speed: 1.05, edgeBias: 0.20}
  ];
  for (let L of layers) {
    for (let i = 0; i < L.count; i++) {
      let p = spawnPoint(L.edgeBias);
      let prev = p.copy();
      let broken = false;
      let colorTweak = random(-0.03, 0.03);
      for (let s = 0; s < L.steps; s++) {
        if (outOfBounds(p)) { broken = true; break; }

        // 中心留白的温柔边界：在空白内不涂抹并被轻推开
        if (insideHollow(p.x, p.y, 1.0)) {
          let dir = createVector((p.x - hc.x) / hc.rx, (p.y - hc.y) / hc.ry);
          if (dir.magSq() > 0) dir.normalize().mult(2.5);
          p.add(dir);
          prev = p.copy();
          continue;
        }

        let v = field(p.x, p.y);
        let mag = v.mag();
        let stepLen = constrain(map(mag, 0, 8, 0.5, 2.6), 0.5, 2.6) * L.speed * (0.85 + random(0, 0.35));
        if (mag > 0) v.setMag(stepLen);
        // 细小的随机性：让关系更有呼吸感
        let nAng = noise(p.x * 0.002, p.y * 0.002, i * 0.001) * TAU * 0.18;
        let jitter = p5.Vector.fromAngle(nAng).mult(0.15);
        p.add(v).add(jitter);

        // 颜色：由亲近度在清凉—紫—温暖之间过渡
        let t = closenessWarmth(p);
        t = constrain(t + colorTweak, 0, 1);
        let h = hueBlend(t);
        let sCol, bCol;
        sCol = lerp(40, 88, smoothstep(0.1, 0.95, t));
        bCol = lerp(65, 98, smoothstep(0.2, 1.0, t));
        let aCol = lerp(L.alphaMin, L.alphaMax, smoothstep(0.0, 1.0, t));
        stroke(h, sCol, bCol, aCol);
        let w = lerp(L.swMin, L.swMax, smoothstep(0.0, 1.0, t)) * (0.9 + random(-0.1, 0.25));
        strokeWeight(w);
        if (!insideHollow(prev.x, prev.y, 1.0) && !insideHollow(p.x, p.y, 1.0)) {
          line(prev.x, prev.y, p.x, p.y);
        }
        prev = p.copy();
      }
      if (broken) continue;
    }
  }
}

function drawAura() {
  // 环绕留白的拥抱式光晕
  blendMode(ADD);
  noFill();

  for (let k = 0; k < 90; k++) {
    let wt = 0.9 + 0.6 * (k / 90);
    let alpha = 5 + 6 * (1 - k / 90);
    stroke(40, 80, 100, alpha);
    strokeWeight(1.2 * wt);
    beginShape();
    let segs = 360;
    for (let i = 0; i <= segs; i++) {
      let a = (i / segs) * TAU;
      let nx = cos(a), ny = sin(a);
      let j1 = (noise(nx * 0.8 + 5.1, ny * 0.8 + 8.3, k * 0.07) - 0.5) * 18;
      let j2 = (noise(nx * 1.1 + 2.7, ny * 1.1 + 1.9, k * 0.09) - 0.5) * 14;
      let rx = hc.rx + j1 * 0.7 + j2 * 0.3 + 10 * (k / 90);
      let ry = hc.ry + j1 * 0.5 + j2 * 0.5 + 8 * (k / 90);
      let x = hc.x + rx * cos(a);
      let y = hc.y + ry * sin(a);
      vertex(x, y);
    }
    endShape();
  }
  blendMode(BLEND);
}

function drawKintsugiCracks() {
  // 修复过的痕迹：金色细脉，避开留白
  for (let i = 0; i < 12; i++) {
    let pts = generateCrackPath();
    // 基线
    noFill();
    stroke(42, 90, 75, 35);
    strokeWeight(1.3);
    drawCrackPolyline(pts, false);
    // 高光
    blendMode(ADD);
    stroke(45, 90, 100, 28);
    strokeWeight(0.7);
    drawCrackPolyline(pts, true);
    blendMode(BLEND);
  }
}

function subtleVignette() {
  // 四角轻微收边，聚焦中心
  noStroke();
  for (let i = 0; i < 120; i++) {
    let t = i / 119;
    let a = 0.0 + 14 * pow(t, 2);
    fill(260, 50, 5, a);
    let m = map(t, 0, 1, 0, 180);
    rect(-m, -m, width + 2 * m, height + 2 * m, 40);
  }
}

/* ----- Helpers ----- */

function spawnPoint(edgeBias) {
  // edgeBias 越大越可能从边缘生成
  if (random() < edgeBias) {
    let side = floor(random(4));
    let m = 40;
    if (side === 0) return createVector(random(-m, width + m), -m);
    if (side === 1) return createVector(width + m, random(-m, height + m));
    if (side === 2) return createVector(random(-m, width + m), height + m);
    return createVector(-m, random(-m, height + m));
  } else {
    // 分布略偏向吸引子附近
    let which = atrs[floor(random(atrs.length))];
    let r = random(60, 550);
    let a = random(TAU);
    let x = which.x + r * cos(a) + random(-50, 50);
    let y = which.y + r * sin(a) + random(-50, 50);
    x = constrain(x, -20, width + 20);
    y = constrain(y, -20, height + 20);
    if (insideHollow(x, y, 1.05)) return spawnPoint(edgeBias); // 避开留白
    return createVector(x, y);
  }
}

function outOfBounds(p) {
  let m = 80;
  return p.x < -m || p.x > width + m || p.y < -m || p.y > height + m;
}

function insideHollow(x, y, expandFactor) {
  let dx = (x - hc.x) / (hc.rx * expandFactor);
  let dy = (y - hc.y) / (hc.ry * expandFactor);
  return dx * dx + dy * dy < 1.0;
}

function field(x, y) {
  let v = createVector(0, 0);
  for (let a of atrs) {
    let dx = a.x - x;
    let dy = a.y - y;
    let d = sqrt(dx * dx + dy * dy) + 0.0001;
    let ux = dx / d, uy = dy / d;
    let f = a.str / (d * 0.65 + 120);
    v.x += ux * f;
    v.y += uy * f;
    // 轻旋：围绕吸引子的小幅环绕
    let perpX = -uy, perpY = ux;
    let sw = a.swirl / (d * 0.85 + 60);
    v.x += perpX * sw;
    v.y += perpY * sw;
  }
  // 全局噪声流
  let sc = 0.0015;
  let ang = noise(x * sc, y * sc) * TAU * 2 + noise(x * sc * 0.5, y * sc * 0.5) * PI;
  v.add(p5.Vector.fromAngle(ang, 0.35));

  // 轻微回归整体中心：让所有线彼此靠拢但不拥堵
  let dcmx = center.x - x, dcmy = center.y - y;
  let dd = sqrt(dcmx * dcmx + dcmy * dcmy) + 0.0001;
  let pull = 0.8 / (dd * 0.002 + 8);
  v.x += (dcmx / dd) * pull;
  v.y += (dcmy / dd) * pull;

  return v;
}

function closenessWarmth(p) {
  // 与吸引子最近距离映射为温暖度
  let dmin = 1e9;
  for (let a of atrs) {
    let d = dist(p.x, p.y, a.x, a.y);
    if (d < dmin) d = dmin = d;
  }
  let t = constrain(1 - dmin / 900, 0, 1);
  // 距离留白越近，温度略提升（柔软的边界）
  let dx = (p.x - hc.x) / hc.rx, dy = (p.y - hc.y) / hc.ry;
  let e = dx * dx + dy * dy;
  let nearHole = constrain(map(e, 1.2, 2.2, 0.25, 0), 0, 0.25);
  return constrain(t + nearHole, 0, 1);
}

function hueBlend(t) {
  // 在清凉(210) — 紫(280) — 温暖(22) 之间平滑过渡
  if (t < 0.5) {
    return lerp(210, 280, smoothstep(0.0, 0.5, t));
  } else {
    return lerp(280, 22, smoothstep(0.5, 1.0, t));
  }
}

function generateCrackPath() {
  // 从画布一边到另一边的多段曲线，尽量绕过留白
  let pts = [];
  let side = floor(random(4));
  let m = 40;
  let start;
  if (side === 0) start = createVector(random(0, width), -m);
  else if (side === 1) start = createVector(width + m, random(0, height));
  else if (side === 2) start = createVector(random(0, width), height + m);
  else start = createVector(-m, random(0, height));
  let end = createVector(width - start.x + random(-60, 60), height - start.y + random(-60, 60));
  end.x = constrain(end.x, -m, width + m);
  end.y = constrain(end.y, -m, height + m);

  let segs = 6 + floor(random(3));
  pts.push(start.copy());
  let prev = start.copy();
  for (let i = 1; i < segs; i++) {
    let t = i / (segs - 1);
    let tgt = p5.Vector.lerp(start, end, t);
    // 噪声扰动
    let ang = noise(t * 3.1, start.x * 0.001 + i * 0.2, start.y * 0.001 - i * 0.17) * TAU;
    let amp = 60 * (0.3 + 0.7 * sin(t * PI));
    let offset = p5.Vector.fromAngle(ang).mult(amp);
    let p = p5.Vector.add(tgt, offset);
    // 尝试绕开留白
    if (insideHollow(p.x, p.y, 1.0)) {
      let dir = createVector((p.x - hc.x) / hc.rx, (p.y - hc.y) / hc.ry);
      if (dir.magSq() > 0) dir.normalize().mult(180);
      p.add(dir);
    }
    // 限定在画布附近
    p.x = constrain(p.x, -m, width + m);
    p.y = constrain(p.y, -m, height + m);
    // 平滑与上一点
    let mid = p5.Vector.lerp(prev, p, 0.6);
    pts.push(mid);
    prev = mid.copy();
  }
  pts.push(end.copy());
  return pts;
}

function drawCrackPolyline(pts, skipInside) {
  // 将多段路径细分并绘制，跳过留白区域
  let fine = [];
  // 细分
  for (let i = 0; i < pts.length - 1; i++) {
    let a = pts[i];
    let b = pts[i + 1];
    let steps = 20;
    for (let t = 0; t <= steps; t++) {
      let p = p5.Vector.lerp(a, b, t / steps);
      fine.push(p);
    }
  }
  // 绘制
  for (let i = 0; i < fine.length - 1; i++) {
    let a = fine[i], b = fine[i + 1];
    let ma = marginToHollow(a.x, a.y);
    let mb = marginToHollow(b.x, b.y);
    // 略避留白并在边缘变亮
    if (skipInside && (ma < 0 || mb < 0)) continue;
    let edgeGlow = smoothstep(0.0, 0.25, min(ma, mb));
    push();
    if (!skipInside) {
      // 基线稍暗，靠近留白减粗
      let w = 1.3 + 0.8 * (1 - edgeGlow);
      strokeWeight(w);
    } else {
      // 高光更细，靠近留白更亮
      let aAlpha = lerp(10, 45, 1 - edgeGlow);
      let c = color(45, 90, 100, aAlpha);
      stroke(c);
      strokeWeight(0.7);
    }
    line(a.x, a.y, b.x, b.y);
    pop();
  }
}

function marginToHollow(x, y) {
  // >0 表示在留白外，值越小越靠近边界；<0 表示在留白内
  let dx = (x - hc.x) / hc.rx;
  let dy = (y - hc.y) / hc.ry;
  return (dx * dx + dy * dy) - 1.0;
}

function smoothstep(a, b, x) {
  let t = constrain((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(2);
  noLoop();
}

function draw() {
  drawScene();
}

function drawScene() {
  let cx = width * 0.5;
  let cy = height * 0.52;

  drawBackgroundGradient();
  push();
  colorMode(HSB, 360, 100, 100, 1);
  drawCenterGlow(cx, cy, 1.25, 0.92, 260, 18, 350);
  pop();

  drawFlowField(cx, cy);
  drawOrbs(cx, cy);

  // Re-soften and unify the core light after threads and orbs
  push();
  colorMode(HSB, 360, 100, 100, 1);
  drawCenterGlow(cx, cy, 1.05, 0.84, 160, 20, 330);
  pop();

  addDust(cx, cy);
}

// ---------- Background ----------
function drawBackgroundGradient() {
  push();
  colorMode(RGB, 255, 255, 255, 1);
  let top = color(10, 12, 26, 1);   // deep indigo
  let mid = color(14, 8, 24, 1);    // dark violet
  let bot = color(8, 6, 18, 1);     // near-black blue
  for (let y = 0; y < height; y++) {
    let t = y / (height - 1);
    let c;
    if (t < 0.55) {
      c = lerpColor(top, mid, t / 0.55);
    } else {
      c = lerpColor(mid, bot, (t - 0.55) / 0.45);
    }
    stroke(c);
    line(0, y, width, y);
  }
  pop();
}

// ---------- Center Glow ----------
function drawCenterGlow(cx, cy, sx, sy, layers, hueA, hueB) {
  blendMode(SCREEN);
  noStroke();
  for (let i = 0; i < layers; i++) {
    let t = i / (layers - 1);
    // Soft ellipse radii
    let r = lerp(980, 120, t);
    let rx = r * sx;
    let ry = r * sy;

    // Warm shift from amber to rose
    let h = lerp(hueA, hueB, t * 0.85);
    let s = lerp(55, 32, t);
    let b = lerp(40, 100, easeOutCubic(t));
    let a = lerp(0.012, 0.08, t * t);
    fill(h, s, b, a);
    ellipse(cx, cy, rx, ry);
  }
  blendMode(BLEND);
}

// ---------- Flow Field Threads ----------
function drawFlowField(cx, cy) {
  push();
  colorMode(HSB, 360, 100, 100, 1);
  strokeCap(ROUND);
  strokeJoin(ROUND);

  // Group 1: cool threads journeying inward from the edges
  let g1 = {
    count: 1200,
    from: 'edges',
    dir: 1, // inward
    steps: 260,
    stepLen: 1.35,
    stopR: 180,
    swMin: 0.6,
    swMax: 1.25,
    colorGen: function() {
      // cool hues cyan -> lavender
      let h = lerp(190, 265, random());
      let s = lerp(45, 65, random());
      let v = lerp(60, 90, random());
      let a = lerp(0.05, 0.11, random());
      return color(h, s, v, a);
    }
  };

  // Group 2: warm threads breathing outward from near the core
  let g2 = {
    count: 800,
    from: 'core',
    dir: -1, // outward
    steps: 220,
    stepLen: 1.25,
    stopOut: 0.62 * dist(0, 0, width, height),
    swMin: 0.7,
    swMax: 1.8,
    colorGen: function() {
      // warm hues amber -> rose
      let mix = random();
      let h = lerp(16, 345, pow(mix, 0.7));
      let s = lerp(65, 80, random());
      let v = lerp(80, 100, random());
      let a = lerp(0.06, 0.14, random());
      return color(h, s, v, a);
    }
  };

  drawFlowGroup(g1, cx, cy);
  drawFlowGroup(g2, cx, cy);

  pop();
}

function drawFlowGroup(g, cx, cy) {
  for (let i = 0; i < g.count; i++) {
    let pos = startPos(g.from, cx, cy);
    let col = g.colorGen();
    let sw = random(g.swMin, g.swMax);

    stroke(col);
    strokeWeight(sw);
    noFill();
    beginShape();
    for (let s = 0; s < g.steps; s++) {
      vertex(pos.x, pos.y);

      let ang = fieldAngle(pos.x, pos.y, cx, cy, g.dir);
      let spd = g.stepLen + noise(pos.x * 0.0013, pos.y * 0.0013) * 0.9;
      pos.x += Math.cos(ang) * spd;
      pos.y += Math.sin(ang) * spd;

      // Stop conditions
      let d = dist(pos.x, pos.y, cx, cy);
      if (g.dir === 1 && d < (g.stopR + random(50, 140))) break;
      if (g.dir === -1) {
        let limit = g.stopOut || 0.62 * dist(0, 0, width, height);
        if (d > limit) break;
      }
      if (pos.x < -60 || pos.x > width + 60 || pos.y < -60 || pos.y > height + 60) break;
    }
    endShape();
  }
}

function startPos(from, cx, cy) {
  if (from === 'edges') {
    let m = 40;
    let side = floor(random(4));
    if (side === 0) return { x: random(width), y: random(m) }; // top band
    if (side === 1) return { x: random(width), y: height - random(m) }; // bottom band
    if (side === 2) return { x: random(m), y: random(height) }; // left band
    return { x: width - random(m), y: random(height) }; // right band
  } else {
    // near core
    let r = random(120, 360);
    let a = random(TWO_PI);
    let ex = 1.12, ey = 0.95; // elliptical spread
    return { x: cx + Math.cos(a) * r * ex, y: cy + Math.sin(a) * r * ey };
  }
}

function fieldAngle(x, y, cx, cy, dir) {
  // Base flow from noise
  let s = 0.00062;
  let base = noise(x * s, y * s) * TWO_PI * 2.0;

  // Attraction to or away from center
  let toC = Math.atan2(cy - y, cx - x);
  let target = (dir === 1) ? toC : toC + PI;

  // Blend and perturb
  let a = angleLerp(base, target, 0.34);
  a += (noise(x * s * 2.71 + 11.7, y * s * 2.71 - 9.3) - 0.5) * 0.7;
  return a;
}

function angleLerp(a, b, t) {
  let d = wrapAngle(b - a);
  return a + d * t;
}

function wrapAngle(a) {
  while (a <= -PI) a += TWO_PI;
  while (a > PI) a -= TWO_PI;
  return a;
}

// ---------- Orbs (breathing points) ----------
function drawOrbs(cx, cy) {
  push();
  colorMode(HSB, 360, 100, 100, 1);
  blendMode(SCREEN);
  noStroke();

  let count = 78;
  for (let i = 0; i < count; i++) {
    let r = random(110, 720);
    let a = random(TWO_PI);
    let ex = 1.18;
    let ey = 0.92;
    let x = cx + Math.cos(a) * r * ex;
    let y = cy + Math.sin(a) * r * ey;

    let sz = lerp(18, 6, constrain(map(r, 110, 720, 0, 1), 0, 1)) * random(0.9, 1.25);

    // Color shifts: warmer near the center ring, cooler farther out
    let t = constrain(map(r, 120, 720, 0, 1), 0, 1);
    let h = lerp(20, 200, pow(t, 0.9)); // amber -> teal
    // occasional rose accents
    if (random() < 0.18 && r < 420) h = lerp(330, 355, random());
    let s = lerp(70, 55, t);
    let v = lerp(98, 85, t);
    let core = color(h, s, v, 0.22);
    let glow = color(h, s * 0.8, min(100, v + 5), 0.06);

    drawOrb(x, y, sz, glow, core, cx, cy);
  }

  pop();
}

function drawOrb(x, y, r, glowCol, coreCol, cx, cy) {
  // Soft outer glow
  for (let i = 0; i < 9; i++) {
    let t = i / 8;
    let rr = lerp(r * 3.2, r * 1.1, t);
    let c = color(
      hue(glowCol),
      saturation(glowCol),
      brightness(glowCol),
      lerp(0.01, 0.06, t)
    );
    fill(c);
    ellipse(x, y, rr, rr);
  }
  // Core disc
  fill(coreCol);
  ellipse(x, y, r * 1.05, r * 1.05);

  // A gentle highlight offset away from center (as if light from the core)
  let ang = Math.atan2(y - cy, x - cx);
  let hx = x + Math.cos(ang) * (-r * 0.25);
  let hy = y + Math.sin(ang) * (-r * 0.25);
  let hi = color(0, 0, 100, 0.08);
  fill(hi);
  ellipse(hx, hy, r * 0.6, r * 0.6);
}

// ---------- Dust / breath speckles ----------
function addDust(cx, cy) {
  push();
  colorMode(HSB, 360, 100, 100, 1);
  noStroke();
  blendMode(SCREEN);
  let n = 620;
  for (let i = 0; i < n; i++) {
    // bias more speckles near center
    let a = random(TWO_PI);
    let rr = pow(random(), 1.6) * 820 + 80;
    let ex = 1.2, ey = 0.95;
    let x = cx + Math.cos(a) * rr * ex + random(-2, 2);
    let y = cy + Math.sin(a) * rr * ey + random(-2, 2);
    let d = dist(x, y, cx, cy);
    let t = constrain(map(d, 80, 900, 0, 1), 0, 1);

    let h = lerp(25, 210, t);
    let s = lerp(40, 30, t);
    let v = lerp(100, 85, t);
    let apha = lerp(0.12, 0.04, t) * random(0.5, 1);
    fill(h, s, v, apha);

    let sz = random(0.8, 1.9) * lerp(1.5, 1.0, t);
    ellipse(x, y, sz, sz);
  }
  blendMode(BLEND);
  pop();
}

// ---------- Easing ----------
function easeOutCubic(t) {
  return 1 - pow(1 - t, 3);
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function draw() {
  colorMode(RGB, 255, 255, 255, 255);

  // Key points (two foci and a shared center)
  const L = createVector(width * 0.28, height * 0.72);
  const R = createVector(width * 0.72, height * 0.72);
  const C = createVector(width * 0.5, height * 0.52);

  // Palettes
  const warm = [
    color('#FF6B6B'),
    color('#FFA552'),
    color('#FFD166'),
    color('#FF8FA3'),
    color('#F7B267')
  ];
  const cool = [
    color('#4ECDC4'),
    color('#5FA8D3'),
    color('#7B2CBF'),
    color('#2E8BC0'),
    color('#8A8AFF')
  ];
  const cGold = color('#FFF3C4');
  const bgTop = color(12, 16, 40);
  const bgBot = color(8, 12, 28);

  // Background gradient
  noStroke();
  for (let y = 0; y < height; y++) {
    let t = y / (height - 1);
    let c = lerpColor(bgTop, bgBot, t);
    stroke(red(c), green(c), blue(c), 255);
    line(0, y, width, y);
  }
  noStroke();

  // Soft radial glow helper
  function radialGlow(cx, cy, r, cInner, cOuter, steps, aMul) {
    aMul = aMul || 1.0;
    noStroke();
    for (let i = steps; i >= 1; i--) {
      let t = i / steps;
      let col = lerpColor(cInner, cOuter, t);
      let a = (14 * pow(t, 1.4)) * aMul;
      fill(red(col), green(col), blue(col), a);
      ellipse(cx, cy, r * 2 * t, r * 2 * t);
    }
  }

  // Base soft wells and center glow (additive for luminosity)
  blendMode(ADD);
  radialGlow(L.x, L.y, 520, color(255, 170, 120), color(80, 20, 10), 120, 1.0);
  radialGlow(R.x, R.y, 520, color(120, 200, 255), color(10, 20, 50), 120, 1.0);
  radialGlow(C.x, C.y, 460, color(255, 245, 210), color(40, 30, 10), 120, 0.9);

  // Utility functions
  function pick(arr) {
    return arr[floor(random(arr.length))];
  }
  function expf(x) { return Math.exp(x); }
  function clamp(a, lo, hi) { return max(lo, min(hi, a)); }

  // Axis utilities
  const ax = R.x - L.x, ay = R.y - L.y;
  const aLen = sqrt(ax * ax + ay * ay);
  const ux = ax / aLen, uy = ay / aLen;

  // Vector field step
  function fieldStep(x, y) {
    const ns = 0.0016;
    const a = noise(x * ns, y * ns) * TWO_PI * 4.0;
    let vx = cos(a) * 0.9;
    let vy = sin(a) * 0.9;

    // Swirl around center, strongest near center, fades outward
    let dx = x - C.x, dy = y - C.y;
    let d = sqrt(dx * dx + dy * dy) + 1e-6;
    let swirlFx = 1.0 - clamp(d / 900.0, 0.0, 1.0);
    let swx = -dy / d, swy = dx / d;
    vx += swx * 1.2 * swirlFx;
    vy += swy * 1.2 * swirlFx;

    // Gentle pull to center
    vx += (-dx / d) * 0.45;
    vy += (-dy / d) * 0.45;

    // Attraction to the line between L and R, strongest mid-span
    let px = x - L.x, py = y - L.y;
    let t = px * ux + py * uy; // projection scalar
    let cxp = L.x + ux * t, cyp = L.y + uy * t;
    let axx = cxp - x, axy = cyp - y;
    let da = sqrt(axx * axx + axy * axy) + 1e-6;
    let bellT = 1.0 - abs(t - aLen * 0.5) / (aLen * 0.5);
    bellT = clamp(bellT, 0.0, 1.0);
    vx += (axx / da) * 0.9 * bellT;
    vy += (axy / da) * 0.9 * bellT;

    // Soft mutual "space": repulsion very near each focus
    function repulse(Fx, Fy) {
      let rx = x - Fx, ry = y - Fy;
      let rd = sqrt(rx * rx + ry * ry) + 1e-6;
      let sR = 120.0;
      let w = expf(-(rd * rd) / (2 * sR * sR)); // peak at center
      vx += (rx / rd) * 2.0 * w;
      vy += (ry / rd) * 2.0 * w;
    }
    repulse(L.x, L.y);
    repulse(R.x, R.y);

    // Normalize and scale step
    let mag = sqrt(vx * vx + vy * vy) + 1e-6;
    vx /= mag; vy /= mag;
    let step = 1.2 + noise(x * 0.01 + 13.1, y * 0.01 + 7.2) * 0.6;
    return { x: vx * step, y: vy * step };
  }

  // Particle drawing
  function drawSwarm(count, sampler, stepCountMin, stepCountMax) {
    for (let i = 0; i < count; i++) {
      let p = sampler();
      let prevx = p.x, prevy = p.y;

      let cW = pick(warm);
      let cC = pick(cool);

      let steps = floor(random(stepCountMin, stepCountMax));
      let thick = random(0.6, 1.4);

      for (let s = 0; s < steps; s++) {
        // Stop at margins
        if (p.x < -60 || p.y < -60 || p.x > width + 60 || p.y > height + 60) break;

        // Influence weights
        let dL = dist(p.x, p.y, L.x, L.y);
        let dR = dist(p.x, p.y, R.x, R.y);
        let wL = expf(-dL / 300.0);
        let wR = expf(-dR / 300.0);
        let mixT = wR / (wL + wR + 1e-6);

        let baseCol = lerpColor(cW, cC, mixT);

        // Brighten toward shared center
        let dC = dist(p.x, p.y, C.x, C.y);
        let m = expf(- (dC * dC) / (2 * 320 * 320)); // gaussian
        let col = lerpColor(baseCol, cGold, m * 0.5);

        // Subtle breathing in thickness/alpha
        let a = 6 + 38 * m;
        let w = thick + m * 0.6;

        stroke(red(col), green(col), blue(col), a);
        strokeWeight(w);
        line(prevx, prevy, p.x, p.y);

        let v = fieldStep(p.x, p.y);
        prevx = p.x;
        prevy = p.y;
        p.x += v.x;
        p.y += v.y;
      }
    }
  }

  // Samplers
  function sampleNear(v, rMin, rMax) {
    return function () {
      let ang = random(TWO_PI);
      let rr = random(rMin, rMax);
      let x = v.x + cos(ang) * rr;
      let y = v.y + sin(ang) * rr;
      return createVector(x, y);
    };
  }
  function sampleEdges() {
    // Distributed around edges and upper half to drape toward the middle
    let side = floor(random(4));
    let x, y;
    if (side === 0) { // top
      x = random(-80, width + 80);
      y = random(-40, 120);
    } else if (side === 1) { // left
      x = random(-80, -20);
      y = random(0, height);
    } else if (side === 2) { // right
      x = random(width + 20, width + 80);
      y = random(0, height);
    } else { // slightly above mid-bottom
      x = random(-80, width + 80);
      y = random(height * 0.45, height * 0.65);
    }
    return createVector(x, y);
  }

  // Draw particles (additive for luminous weaving)
  blendMode(ADD);
  drawSwarm(2200, sampleNear(L, 80, 240), 120, 180);
  drawSwarm(2200, sampleNear(R, 80, 240), 120, 180);
  drawSwarm(2600, sampleEdges, 110, 160);

  // Soft stardust at the confluence
  noStroke();
  for (let i = 0; i < 2200; i++) {
    let ang = random(TWO_PI);
    let rr = pow(random(), 0.55) * 320; // biased toward center
    let x = C.x + cos(ang) * rr + random(-3, 3);
    let y = C.y + sin(ang) * rr + random(-3, 3);
    let sz = random(0.6, 2.0);
    let glow = 90 + random(80);
    fill(255, 240, 210, glow);
    ellipse(x, y, sz, sz);
  }

  // Return to normal blend and add a very gentle vignette to focus the gaze
  blendMode(BLEND);
  // Vignette
  let vignSteps = 80;
  for (let i = 0; i < vignSteps; i++) {
    let t = i / (vignSteps - 1);
    let a = 8 * pow(t, 1.8);
    noFill();
    stroke(0, 0, 0, a);
    let padX = lerp(0, 260, t);
    let padY = lerp(0, 260, t);
    rect(padX, padY, width - padX * 2, height - padY * 2);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
  colorMode(RGB, 255, 255, 255, 1);
  angleMode(RADIANS);
}

function draw() {
  background(8, 7, 20);

  // Base radial dusk background
  drawRadialGradient(width * 0.5, height * 0.6, max(width, height) * 0.9,
                     color(46, 20, 55, 0.9),
                     color(10, 8, 20, 1.0));

  // Subtle vertical warmth
  drawVerticalVeil(color(255, 120, 150, 0.03), color(120, 130, 255, 0.03));

  // Soft luminous wells (two sources and a shared core)
  blendMode(ADD);
  softBlob(width * 0.32, height * 0.62, 300,
           color(255, 160, 90, 0.05), 380);
  softBlob(width * 0.68, height * 0.62, 300,
           color(150, 120, 255, 0.05), 380);
  softBlob(width * 0.50, height * 0.58, 420,
           color(255, 200, 220, 0.05), 500);

  // Breathing rings around the shared core
  drawPulseRings(width * 0.5, height * 0.58);

  // Intertwined flow field streams from both sides toward a shared center
  strokeCap(ROUND);
  strokeJoin(ROUND);

  let leftSrc = createVector(width * 0.25, height * 0.62);
  let rightSrc = createVector(width * 0.75, height * 0.62);
  let center = createVector(width * 0.5, height * 0.56);

  // Warm and cool threads blending into a shared glow
  drawStreams(leftSrc, center, 460, [
    color(255, 150, 120, 0.20),
    color(255, 180, 100, 0.20),
    color(255, 95, 180, 0.20),
    color(255, 220, 140, 0.20)
  ], color(255, 220, 240, 0.30));

  drawStreams(rightSrc, center, 460, [
    color(120, 180, 255, 0.20),
    color(170, 140, 255, 0.20),
    color(140, 200, 230, 0.20),
    color(200, 160, 255, 0.20)
  ], color(255, 220, 240, 0.30));

  // Shared weave in the middle: thin cross-bridges
  drawBridges(center, 180);

  // Soft vignette to hold the eye
  blendMode(MULTIPLY);
  vignette();

  // Gentle sparks near the convergence
  blendMode(ADD);
  sparks(center, 1200);

  // Final whisper of glow
  softBlob(width * 0.5, height * 0.58, 260,
           color(255, 230, 250, 0.05), 260);

  blendMode(BLEND);
}

/* Helpers */

function drawRadialGradient(cx, cy, r, cInner, cOuter) {
  noStroke();
  let steps = 400;
  for (let i = steps; i >= 1; i--) {
    let t = i / steps;
    let c = lerpColor(cInner, cOuter, 1 - t);
    fill(c);
    let rr = r * t;
    ellipse(cx, cy, rr * 2, rr * 2);
  }
}

function drawVerticalVeil(topC, botC) {
  noStroke();
  let bands = 220;
  for (let i = 0; i <= bands; i++) {
    let t = i / bands;
    let c = lerpColor(topC, botC, t);
    fill(c);
    rect(0, t * height, width, height / bands + 2);
  }
}

function softBlob(x, y, r, col, count) {
  noStroke();
  for (let i = 0; i < count; i++) {
    let rr = r * (0.15 + 0.85 * pow(random(), 2));
    let ang = random(TWO_PI);
    let dx = cos(ang) * rr * 0.25 * random(0.6, 1.2);
    let dy = sin(ang) * rr * 0.25 * random(0.6, 1.2);
    let sz = rr * random(0.12, 0.28);
    let jitter = rr * 0.02;
    let cx = x + dx + random(-jitter, jitter);
    let cy = y + dy + random(-jitter, jitter);
    let c = color(
      red(col),
      green(col),
      blue(col),
      alpha(col) * random(0.3, 1.0)
    );
    fill(c);
    ellipse(cx, cy, sz, sz * random(0.8, 1.3));
  }
}

function drawPulseRings(cx, cy) {
  noFill();
  let rings = 22;
  for (let i = 0; i < rings; i++) {
    let t = i / (rings - 1);
    let r = 80 + t * 540 + sin(i * 0.7) * 8;
    let col = lerpColor(color(255, 160, 140, 0.05), color(160, 180, 255, 0.04), t);
    stroke(col);
    strokeWeight(1.5 - t * 1.2);
    ellipse(cx, cy, r * 2.0, r * 2.0 * (0.92 + 0.06 * sin(t * PI)));
  }
}

function fieldAngle(x, y, center) {
  // Smooth turbulent field + gentle attraction to center
  let s = 0.0006;
  let n = noise(x * s, y * s);
  let flow = n * TWO_PI * 2.0;

  // Curl-ish tweak using orthogonal noise lookups
  let n2 = noise(x * s * 0.7 + 100, y * s * 0.7 - 50);
  flow += (n2 - 0.5) * 0.9;

  let grav = atan2(center.y - y, center.x - x);
  // Distance-based attraction strength
  let d = dist(x, y, center.x, center.y);
  let g = constrain(map(d, 0, 1200, 0.70, 0.25), 0.2, 0.8);

  return lerpAngle(flow, grav, g);
}

function lerpAngle(a, b, t) {
  let x = cos(a) * (1 - t) + cos(b) * t;
  let y = sin(a) * (1 - t) + sin(b) * t;
  return atan2(y, x);
}

function drawStreams(src, center, count, palette, glowCol) {
  for (let i = 0; i < count; i++) {
    let ang = random(-PI * 0.55, PI * 0.55);
    let rad = random(30, 320) * pow(random(), 0.6);
    let start = createVector(
      src.x + cos(ang) * rad + random(-8, 8),
      src.y + sin(ang) * rad + random(-8, 8)
    );

    let steps = floor(random(110, 170));
    let stepLen = random(2.2, 3.6);
    let jitter = random(0.05, 0.35);

    // Color progression from source hue to shared glow
    let base = random(palette);
    let endC = glowCol;

    let x = start.x;
    let y = start.y;
    let px = x, py = y;

    for (let j = 0; j < steps; j++) {
      let t = j / (steps - 1);
      // Slight bias to lift flows upward a little near the center
      let a = fieldAngle(x, y, center) + sin(j * 0.07 + i * 0.013) * 0.08;

      let k = noise(x * 0.003, y * 0.003, j * 0.01) - 0.5;
      x += cos(a) * stepLen + k * jitter * 3;
      y += sin(a) * stepLen + k * jitter * 2;

      // Fade-in/fade-out alpha shaping
      let fade = smoothstep(0.03, 0.18, t) * (1.0 - smoothstep(0.76, 1.0, t));

      let col = lerpColor(base, endC, pow(t, 1.6));
      let sw = 2.1 * (1.0 - t) + 0.3;

      stroke(red(col), green(col), blue(col), alpha(col) * (0.9 * fade + 0.05));
      strokeWeight(sw);
      line(px, py, x, y);

      // Occasional tiny glow dots along the path
      if (random() < 0.004 && j > steps * 0.25 && j < steps * 0.9) {
        noStroke();
        fill(255, 240, 255, 0.06 * fade);
        let s = random(2, 5);
        ellipse(x, y, s, s);
        stroke(255, 240, 255, 0.02 * fade);
        strokeWeight(1);
        point(x, y);
      }

      px = x; py = y;

      if (x < -50 || x > width + 50 || y < -50 || y > height + 50) break;
    }
  }
}

function drawBridges(center, n) {
  // Fine filaments weaving across the convergence
  blendMode(ADD);
  for (let i = 0; i < n; i++) {
    let r1 = random(60, 260);
    let r2 = random(60, 260);
    let a1 = random(-PI * 0.6, PI * 0.6);
    let a2 = a1 + random(-0.8, 0.8);

    let p1 = createVector(
      center.x + cos(a1) * r1 * random(0.6, 1.2),
      center.y + sin(a1) * r1 * random(0.6, 1.2)
    );
    let p2 = createVector(
      center.x + cos(a2) * r2 * random(0.6, 1.2),
      center.y + sin(a2) * r2 * random(0.6, 1.2)
    );

    let m1 = p5.Vector.lerp(p1, center, random(0.35, 0.75));
    let m2 = p5.Vector.lerp(p2, center, random(0.35, 0.75));

    let t = random();
    let c = lerpColor(color(255, 180, 160, 0.08), color(170, 190, 255, 0.08), t);
    stroke(c);
    strokeWeight(random(0.5, 1.3));
    noFill();
    bezier(p1.x, p1.y, m1.x, m1.y, m2.x, m2.y, p2.x, p2.y);
  }
  blendMode(ADD);
}

function vignette() {
  noFill();
  let rings = 60;
  for (let i = 0; i < rings; i++) {
    let t = i / (rings - 1);
    let a = pow(t, 2.2) * 0.3;
    stroke(0, 0, 0, a);
    strokeWeight(40 * (1 - t) + 8);
    rect(-40 + i * 1.2, -40 + i * 1.2, width + 80 - i * 2.4, height + 80 - i * 2.4, 80);
  }
}

function sparks(center, count) {
  noStroke();
  for (let i = 0; i < count; i++) {
    // Sample around center with heavier density near it
    let r = pow(random(), 1.7) * 520 + random(-2, 2);
    let a = random(TWO_PI);
    let x = center.x + cos(a) * r + random(-1.5, 1.5);
    let y = center.y + sin(a) * r + random(-1.5, 1.5);

    let twinkle = random(0.02, 0.08);
    fill(255, 245, 255, twinkle);
    let s = random(0.6, 1.8) * (1.2 - r / 900);
    ellipse(x, y, s, s);

    // Soft halo
    fill(255, 200, 255, twinkle * 0.25);
    ellipse(x, y, s * 4, s * 4);
  }
}

// Smoothstep utility
function smoothstep(edge0, edge1, x) {
  let t = constrain((x - edge0) / (edge1 - edge0), 0, 1);
  return t * t * (3 - 2 * t);
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(2);
  colorMode(HSL, 360, 100, 100, 1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  noStroke();
}

function draw() {
  let W = width;
  let H = height;
  let CX = W * 0.5;
  let CY = H * 0.52;

  // Background vertical gradient
  let topC = color(260, 35, 10, 1.0);   // deep violet
  let botC = color(215, 40, 8, 1.0);    // deep blue
  drawVerticalGradient(0, 0, W, H, topC, botC);

  // Subtle radial warmth at center
  radialGlow(CX, CY, 900, color(28, 85, 62, 0.22), color(260, 35, 10, 0));

  // Vesica-like overlapping presence
  let R = 720;
  push();
  blendMode(SCREEN);
  noStroke();
  fill(color(330, 65, 60, 0.18)); // warm-magenta
  ellipse(CX - 260, CY, R * 2, R * 2);
  fill(color(200, 70, 58, 0.18)); // teal-cyan
  ellipse(CX + 260, CY, R * 2, R * 2);

  // Core soft white glow
  fill(color(0, 0, 100, 0.12));
  ellipse(CX, CY, 520, 520);
  fill(color(35, 90, 70, 0.10));
  ellipse(CX, CY, 740, 740);
  pop();

  // Embracing ripples (organic rings)
  drawRippleRings(CX, CY, 11);

  // Bond threads weaving from both sides
  drawBondThreads(CX, CY, 230);

  // Ambient flow lines
  drawFlowField(CX, CY, 120);

  // Speckles of shared moments
  drawSpeckles(CX, CY, 2200);
}

function drawVerticalGradient(x, y, w, h, c1, c2) {
  noFill();
  for (let i = 0; i < h; i++) {
    let t = i / (h - 1);
    let c = lerpColor(c1, c2, t);
    stroke(c);
    line(x, y + i, x + w, y + i);
  }
  noStroke();
}

function radialGlow(cx, cy, radius, innerC, outerC) {
  noStroke();
  let steps = 90;
  for (let i = steps; i >= 1; i--) {
    let t = i / steps;
    let r = radius * t;
    let c = lerpColor(innerC, outerC, 1 - pow(t, 1.6));
    fill(hue(c), saturation(c), lightness(c), alpha(c));
    ellipse(cx, cy, r * 2, r * 2);
  }
}

function drawRippleRings(cx, cy, num) {
  push();
  blendMode(SCREEN);
  noFill();
  strokeCap(ROUND);
  for (let i = 0; i < num; i++) {
    let baseR = 180 + i * 85;
    let amp = 12 + i * 2.2;
    let sw = 0.9 + i * 0.06;
    let warm = color(28, 90, 70, 0.05);
    let cool = color(200, 60, 70, 0.05);
    let c = lerpColor(warm, cool, i / (num - 1));
    stroke(c);
    strokeWeight(sw);
    beginShape();
    let seed = 100 + i * 13.37;
    for (let a = 0; a <= TWO_PI + 0.002; a += 0.012) {
      let nx = cos(a) * 0.6 + seed;
      let ny = sin(a) * 0.6 + seed * 0.23;
      let jitter = (noise(nx, ny) - 0.5) * 2 * amp;
      let rr = baseR + jitter;
      let x = cx + rr * cos(a);
      let y = cy + rr * sin(a) * 1.02;
      vertex(x, y);
    }
    endShape(CLOSE);
  }
  pop();
}

function drawBondThreads(cx, cy, count) {
  strokeCap(ROUND);
  for (let i = 0; i < count; i++) {
    let yBase = cy + randomGaussian() * (height * 0.22);
    let x1 = random(-120, width * 0.18);
    let x2 = random(width * 0.82, width + 120);
    let y1 = yBase + random(-90, 90);
    let y2 = yBase + random(-90, 90);

    let pull = 0.84 + random(-0.06, 0.06);
    let c1x = lerp(x1, cx, pull) + map(noise(i * 0.11, 3.1), 0, 1, -180, 180);
    let c2x = lerp(x2, cx, pull) + map(noise(i * 0.11, 6.2), 0, 1, -180, 180);
    let c1y = lerp(y1, cy, 0.55) + map(noise(i * 0.09, 1.8), 0, 1, -140, 140);
    let c2y = lerp(y2, cy, 0.55) + map(noise(i * 0.09, 4.7), 0, 1, -140, 140);

    let tA = 0.22 + random(-0.06, 0.06);
    let tB = 0.22 + random(-0.06, 0.06);
    let cA = color(330 + random(-6, 6), 70 + random(-8, 8), 60 + random(-10, 6), tA);
    let cB = color(200 + random(-6, 6), 70 + random(-8, 8), 60 + random(-10, 6), tB);
    let thick = random(0.7, 2.2);

    bezierGradient(x1, y1, c1x, c1y, c2x, c2y, x2, y2, cA, cB, thick, cx, cy);
  }
}

function bezierGradient(x1, y1, cx1, cy1, cx2, cy2, x2, y2, cA, cB, baseW, cx, cy) {
  let steps = 90;
  let px = x1;
  let py = y1;
  for (let s = 1; s <= steps; s++) {
    let t = s / steps;
    let x = bezierPoint(x1, cx1, cx2, x2, t);
    let y = bezierPoint(y1, cy1, cy2, y2, t);
    let tt = (s - 0.5) / steps;
    let baseC = lerpColor(cA, cB, tt);

    let d = dist(x, y, cx, cy);
    let f = constrain(map(d, 0, 320, 1, 0), 0, 1);
    let w = baseW * (0.7 + 1.1 * f);

    // Softly drift hue toward warmth near center
    let warmed = lerpColor(baseC, color(28, 90, 76, 0.8), f * 0.35);
    // Then mix with white to bloom
    let glow = lerpColor(warmed, color(0, 0, 100, 0.8), f * 0.45);

    stroke(glow);
    strokeWeight(w);
    line(px, py, x, y);

    px = x;
    py = y;
  }
}

function drawFlowField(cx, cy, linesCount) {
  // Gentle orbit-like flows looping through the center
  push();
  strokeCap(ROUND);
  for (let i = 0; i < linesCount; i++) {
    let a0 = random(TWO_PI);
    let rad = 520 + random(-160, 240);
    let x0 = cx + cos(a0) * rad;
    let y0 = cy + sin(a0) * rad * 1.06;

    let segs = 140;
    let step = 7.0 + random(-1.6, 1.6);
    let px = x0;
    let py = y0;

    for (let s = 0; s < segs; s++) {
      let ang = flowAngle(px, py, cx, cy, i * 0.002);
      let nx = px + cos(ang) * step;
      let ny = py + sin(ang) * step;

      let d = dist(nx, ny, cx, cy);
      let f = constrain(map(d, 120, 780, 1, 0), 0, 1);
      let c = lerpColor(color(210, 30, 72, 0.06), color(30, 70, 70, 0.08), f);
      stroke(c);
      strokeWeight(0.8 + 1.2 * f);
      line(px, py, nx, ny);

      px = nx;
      py = ny;
    }
  }
  pop();
}

function flowAngle(x, y, cx, cy, z) {
  // Curl-ish angle around center, shaped by noise and subtle attraction
  let vx = x - cx;
  let vy = y - cy;
  let ang = atan2(vy, vx) + HALF_PI; // orbit direction
  let n = noise(x * 0.0016, y * 0.0016, z);
  ang += map(n, 0, 1, -0.7, 0.7);
  // Slight pull inward
  let d = dist(x, y, cx, cy);
  ang = lerp(ang, atan2(cy - y, cx - x), constrain(map(d, 0, 900, 0.14, 0.02), 0.02, 0.2));
  return ang;
}

function drawSpeckles(cx, cy, count) {
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < count; i++) {
    let a = random(TWO_PI);
    let r = pow(random(), 2.2) * 760;
    let x = cx + cos(a) * r + map(noise(i * 0.21), 0, 1, -6, 6);
    let y = cy + sin(a) * r * 1.02 + map(noise(i * 0.29), 0, 1, -6, 6);

    let near = constrain(map(dist(x, y, cx, cy), 0, 500, 1, 0), 0, 1);
    let sz = random(0.7, 2.6) * (0.7 + 0.8 * near);

    let pick = random();
    let c;
    if (pick < 0.55) c = color(0, 0, 100, 0.07 + 0.22 * near);          // soft white
    else if (pick < 0.78) c = color(30, 90, 70, 0.05 + 0.20 * near);     // warm
    else c = color(200, 70, 70, 0.05 + 0.20 * near);                     // cool

    fill(c);
    ellipse(x, y, sz, sz);
  }
  pop();
}

// p5.js 1.11 — 1600x2000 still image
let W = 1600, H = 2000;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  colorMode(HSB, 360, 100, 100, 1);
  noLoop();
  drawPainting();
}

function draw() {}

function drawPainting() {
  background(230, 35, 6);

  // Sky gradient
  for (let y = 0; y < H; y++) {
    let t = y / (H - 1);
    let h = lerp(232, 260, pow(t, 0.9));
    let s = lerp(45, 30, t);
    let b = lerp(10, 4, t);
    stroke(h, s, b, 1);
    line(0, y, W, y);
  }

  // Distant haze near horizon
  let horizonY = int(H * 0.62);
  for (let i = 0; i < 9000; i++) {
    let x = random(W);
    let y = horizonY + randomGaussian() * 55;
    let a = constrain(map(abs(y - horizonY), 0, 140, 0.12, 0.0), 0, 0.12);
    stroke(45, 18, 18, a);
    point(x, y);
  }

  // Soft texture wash
  addPaperGrain(0.08, 0.035);

  // Ground mass
  noStroke();
  for (let y = horizonY; y < H; y++) {
    let t = (y - horizonY) / (H - horizonY);
    let h = lerp(250, 30, pow(t, 1.2));
    let s = lerp(30, 55, t);
    let b = lerp(7, 12, t);
    fill(h, s, b, 1);
    rect(0, y, W, 2);
  }

  // River/path leading to doorway
  drawRiver();

  // Doorway/void
  drawVoid(W * 0.5, H * 0.52, 520, 780);

  // A pale figure dissolving upward
  drawDissolvingFigure(W * 0.5, H * 0.66);

  // Moths around the rim light
  for (let i = 0; i < 44; i++) {
    let ang = random(TWO_PI);
    let r = random(240, 520);
    let x = W * 0.5 + cos(ang) * r * random(0.8, 1.1);
    let y = H * 0.52 + sin(ang) * r * random(0.7, 1.1);
    drawMoth(x, y, random(0.6, 1.4));
  }

  // Foreground remnants: petals, brittle stems, bone-curves
  drawForegroundRelics();

  // Final glazing to unify
  glaze(250, 18, 10, 0.22);
  addPaperGrain(0.06, 0.03);
}

function drawRiver() {
  // Painterly ribbon with cool highlights, guiding eye toward the void
  let cx = W * 0.5;
  let y0 = H * 0.99;
  let y1 = H * 0.46;
  let steps = 520;

  for (let i = 0; i < steps; i++) {
    let t = i / (steps - 1);
    let y = lerp(y0, y1, pow(t, 0.9));
    let w = lerp(560, 180, pow(t, 1.15));

    let bend = (noise(t * 2.1, 0.2) - 0.5) * 240;
    let x = cx + bend * (1 - t);

    // Layer strokes across width
    let layers = 10;
    for (let k = 0; k < layers; k++) {
      let u = (k / (layers - 1)) * 2 - 1; // -1..1
      let edge = pow(abs(u), 1.7);
      let wx = x + u * w * 0.5;
      let jitterY = randomGaussian() * 1.2;

      let cool = 215 + noise(t * 3.0, k * 0.2) * 18;
      let sat = lerp(18, 30, t);
      let bri = lerp(22, 10, t) - edge * 6;
      let a = lerp(0.14, 0.05, t) * (1 - edge * 0.65);

      stroke(cool, sat, bri, a);
      strokeWeight(1.8 + random() * 1.6);
      line(wx - random(10, 40), y + jitterY, wx + random(10, 40), y + jitterY);
    }
  }

  // Thin highlight thread near center
  for (let i = 0; i < 2400; i++) {
    let t = random();
    let y = lerp(H * 0.98, H * 0.47, pow(t, 0.9));
    let bend = (noise(t * 2.4, 0.8) - 0.5) * 200;
    let x = W * 0.5 + bend * (1 - t) + randomGaussian() * 9;
    let a = 0.05 * (1 - t);
    stroke(200, 10, 55, a);
    strokeWeight(random(0.6, 1.4));
    point(x, y);
  }
}

function drawVoid(cx, cy, w, h) {
  // Rim glow
  for (let i = 0; i < 140; i++) {
    let t = i / 139;
    let ww = w + t * 260;
    let hh = h + t * 340;
    let a = (1 - t) * 0.06;
    noFill();
    stroke(45, 18, 24, a);
    strokeWeight(2.2);
    ellipse(cx, cy, ww, hh);
  }

  // Dark interior with depth
  noStroke();
  for (let i = 0; i < 220; i++) {
    let t = i / 219;
    let ww = lerp(w, w * 0.38, pow(t, 1.15));
    let hh = lerp(h, h * 0.34, pow(t, 1.15));
    let a = lerp(0.75, 0.98, t);
    fill(250, 28, lerp(3.5, 0.5, t), a);
    ellipse(cx + (noise(t * 2.2, 0.3) - 0.5) * 16,
            cy + (noise(t * 2.2, 0.9) - 0.5) * 22,
            ww, hh);
  }

  // Subtle warm edge on one side (like a last ember)
  for (let i = 0; i < 2600; i++) {
    let ang = random(-PI * 0.6, PI * 0.6);
    let rr = random(w * 0.44, w * 0.68);
    let x = cx + cos(ang) * rr;
    let y = cy + sin(ang) * rr * (h / w);
    let a = random(0.02, 0.07);
    stroke(28, 65, 26, a);
    strokeWeight(random(0.6, 1.6));
    point(x + randomGaussian() * 1.2, y + randomGaussian() * 1.2);
  }
}

function drawDissolvingFigure(x, y) {
  // Body core (translucent)
  push();
  translate(x, y);

  // Underpaint silhouette
  noStroke();
  for (let i = 0; i < 90; i++) {
    let t = i / 89;
    let yy = lerp(240, -220, t);
    let ww = lerp(140, 70, t) + (noise(t * 2.6, 0.4) - 0.5) * 28;
    let hh = lerp(18, 14, t);
    let a = lerp(0.14, 0.02, t);
    fill(200, 10, 82, a);
    ellipse((noise(t * 2.1, 1.1) - 0.5) * 40, yy, ww, hh);
  }

  // Head glow
  for (let i = 0; i < 120; i++) {
    let t = i / 119;
    let r = lerp(36, 160, t);
    let a = (1 - t) * 0.055;
    stroke(200, 8, 85, a);
    strokeWeight(2);
    noFill();
    ellipse(0, -250, r, r * 1.05);
  }

  // Dissolve into a flock-like scatter
  for (let i = 0; i < 520; i++) {
    let t = random();
    let yy = lerp(-120, -640, pow(t, 1.1));
    let spread = lerp(40, 520, pow(t, 1.2));
    let xx = randomGaussian() * spread * 0.32 + (noise(t * 3.0, 2.0) - 0.5) * 120;
    let a = lerp(0.10, 0.0, t);

    // bird-ish wedge stroke
    let sz = lerp(9, 2, t) * random(0.7, 1.2);
    stroke(205, 10, 88, a);
    strokeWeight(1.2);
    line(xx - sz, yy, xx, yy - sz * 0.55);
    line(xx + sz, yy, xx, yy - sz * 0.55);
  }

  // A faint shadow in the river
  pop();
  noStroke();
  for (let i = 0; i < 120; i++) {
    let t = i / 119;
    let a = lerp(0.12, 0, t);
    fill(250, 25, 2, a);
    ellipse(x + (noise(t * 2.0, 7.0) - 0.5) * 60, y + 250 + t * 50, 220 - t * 120, 46 - t * 20);
  }
}

function drawMoth(x, y, sc) {
  push();
  translate(x, y);
  rotate((noise(x * 0.002, y * 0.002) - 0.5) * 1.5);
  scale(sc);

  // Wing dust
  for (let i = 0; i < 34; i++) {
    let ang = random(TWO_PI);
    let r = random(3, 18);
    let px = cos(ang) * r;
    let py = sin(ang) * r;
    stroke(50, 15, 75, random(0.02, 0.07));
    strokeWeight(random(0.6, 1.4));
    point(px, py);
  }

  // Wings (soft triangles)
  noStroke();
  fill(45, 15, 78, 0.08);
  beginShape();
  vertex(0, 0);
  vertex(-34, -10);
  vertex(-24, 14);
  endShape(CLOSE);
  beginShape();
  vertex(0, 0);
  vertex(34, -10);
  vertex(24, 14);
  endShape(CLOSE);

  // Body
  fill(40, 15, 60, 0.10);
  ellipse(0, 2, 10, 20);

  // Rim catch
  stroke(48, 10, 90, 0.06);
  strokeWeight(1);
  noFill();
  arc(-14, 0, 34, 20, -PI * 0.2, PI * 0.8);
  arc(14, 0, 34, 20, PI * 0.2, PI * 1.2);

  pop();
}

function drawForegroundRelics() {
  // Petals scattered like embers turned cold
  for (let i = 0; i < 220; i++) {
    let x = random(W);
    let y = random(H * 0.72, H * 0.98);
    let s = random(10, 34);
    let rot = random(TWO_PI);
    let hue = random(10, 28);
    let sat = random(55, 75);
    let bri = random(18, 34);
    let a = random(0.04, 0.12);

    push();
    translate(x, y);
    rotate(rot);
    noStroke();
    fill(hue, sat, bri, a);
    beginShape();
    vertex(-s * 0.55, 0);
    bezierVertex(-s * 0.2, -s * 0.6, s * 0.2, -s * 0.55, s * 0.55, 0);
    bezierVertex(s * 0.2, s * 0.7, -s * 0.25, s * 0.55, -s * 0.55, 0);
    endShape(CLOSE);

    fill(hue, sat * 0.6, bri * 0.7, a * 0.8);
    ellipse(0, 0, s * 0.18, s * 0.18);
    pop();
  }

  // Wilted stems
  stroke(35, 25, 22, 0.10);
  strokeWeight(2);
  for (let i = 0; i < 32; i++) {
    let x0 = random(W * 0.1, W * 0.9);
    let y0 = random(H * 0.78, H * 0.98);
    let len = random(140, 320);
    let x1 = x0 + random(-120, 120);
    let y1 = y0 - len;
    let cx = lerp(x0, x1, 0.5) + random(-90, 90);
    let cy = lerp(y0, y1, 0.5) + random(-60, 60);
    noFill();
    beginShape();
    vertex(x0, y0);
    quadraticVertex(cx, cy, x1, y1);
    endShape();
  }

  // Bone-like curves (suggestion, not literal)
  for (let i = 0; i < 16; i++) {
    let x = random(W * 0.08, W * 0.92);
    let y = random(H * 0.78, H * 0.97);
    let s = random(120, 240);
    drawBoneCurve(x, y, s);
  }

  // A single withered flower near bottom
  drawWitheredFlower(W * 0.24, H * 0.92, 1.15);
}

function drawBoneCurve(x, y, s) {
  push();
  translate(x, y);
  rotate(random(-0.6, 0.6));
  noFill();
  for (let k = 0; k < 10; k++) {
    let t = k / 9;
    let a = lerp(0.12, 0.02, t);
    stroke(45, 10, 70, a);
    strokeWeight(3.2 - t * 2.2);

    beginShape();
    for (let i = 0; i < 28; i++) {
      let u = i / 27;
      let xx = lerp(-s * 0.5, s * 0.5, u);
      let yy = sin(u * PI) * (s * 0.12) - cos(u * PI * 2) * (s * 0.04);
      yy += (noise(u * 2.8, k * 0.4) - 0.5) * 10;
      vertex(xx, yy);
    }
    endShape();
  }
  pop();
}

function drawWitheredFlower(x, y, sc) {
  push();
  translate(x, y);
  scale(sc);
  rotate(-0.35);

  // Stem
  noFill();
  stroke(35, 25, 22, 0.16);
  strokeWeight(3);
  beginShape();
  vertex(0, 190);
  quadraticVertex(-40, 60, -10, -80);
  endShape();

  // Drooping head
  translate(-10, -85);
  rotate(-0.55);

  // Petals: dark, curled
  for (let i = 0; i < 8; i++) {
    let ang = (TWO_PI / 8) * i + random(-0.1, 0.1);
    let r = random(30, 55);
    let px = cos(ang) * r;
    let py = sin(ang) * r;
    push();
    translate(px, py);
    rotate(ang + 0.6);
    noStroke();
    fill(18, 60, 20, 0.10);
    beginShape();
    vertex(0, 0);
    bezierVertex(26, -8, 22, 26, 0, 34);
    bezierVertex(-18, 22, -12, 6, 0, 0);
    endShape(CLOSE);
    pop();
  }

  // Center
  noStroke();
  for (let i = 0; i < 120; i++) {
    let a = random(0.03, 0.09);
    fill(28, 40, 18, a);
    ellipse(randomGaussian() * 10, randomGaussian() * 10, random(2, 6), random(2, 6));
  }

  pop();
}

function glaze(h, s, b, a) {
  noStroke();
  fill(h, s, b, a);
  rect(0, 0, W, H);
}

function addPaperGrain(alphaA, alphaB) {
  // Two layers: fine noise + occasional fibers
  loadPixels();
  // Lightweight: draw with points instead of direct pixel writes
  // Fine speckle
  for (let i = 0; i < 52000; i++) {
    let x = random(W);
    let y = random(H);
    let n = noise(x * 0.01, y * 0.01);
    let a = lerp(alphaB, alphaA, n);
    stroke(40, 10, 92, a * 0.35);
    strokeWeight(1);
    point(x, y);
  }
  // Fibers
  stroke(45, 8, 85, 0.06);
  strokeWeight(1);
  for (let i = 0; i < 2400; i++) {
    let x = random(W);
    let y = random(H);
    let len = random(10, 34);
    let ang = random(TWO_PI);
    line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }
}

// p5.js 1.11 - 1600x2000 still painting (no text)
let W = 1600, H = 2000;

function setup() {
  createCanvas(W, H);
  pixelDensity(2);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  background(10, 12, 20);

  // Atmosphere gradient
  paintVerticalGradient(color(8, 10, 18), color(220, 210, 195), 0.0);

  // Subtle cloud veils
  for (let i = 0; i < 26; i++) {
    let y = random(H * 0.05, H * 0.65);
    let h = random(70, 220);
    let a = random(10, 22);
    paintCloudBand(y, h, a);
  }

  // Distant horizon haze
  paintHaze(H * 0.52, H * 0.12, color(245, 238, 225), 22);

  // The river of light (center path)
  drawRiver();

  // The threshold / arch in distance
  drawArch();

  // Foreground ground plane and soil texture
  drawGround();

  // Fallen flower: life spent, returned to earth
  drawFallenFlower();

  // A pale moth near the path (fragile witness)
  drawMoth();

  // Overall paper texture
  paperTexture(90000);

  // Vignette for focus
  vignette();
}

function paintVerticalGradient(topC, bottomC, jitter) {
  noStroke();
  for (let y = 0; y < H; y++) {
    let t = y / (H - 1);
    let c = lerpColor(topC, bottomC, smoothstep(0.0, 1.0, t));
    let rr = red(c) + random(-jitter, jitter);
    let gg = green(c) + random(-jitter, jitter);
    let bb = blue(c) + random(-jitter, jitter);
    fill(constrain(rr, 0, 255), constrain(gg, 0, 255), constrain(bb, 0, 255));
    rect(0, y, W, 1);
  }
}

function paintCloudBand(yCenter, bandH, alphaMax) {
  noStroke();
  let steps = 120;
  for (let i = 0; i < steps; i++) {
    let yy = yCenter + map(i, 0, steps - 1, -bandH / 2, bandH / 2);
    let t = i / (steps - 1);
    let a = alphaMax * (1 - abs(2 * t - 1));
    let col = color(200, 205, 220, a);
    fill(col);
    beginShape();
    vertex(0, yy);
    let segs = 32;
    for (let s = 0; s <= segs; s++) {
      let x = (W / segs) * s;
      let n = noise(x * 0.002, yy * 0.006);
      let wobble = map(n, 0, 1, -25, 25);
      vertex(x, yy + wobble);
    }
    vertex(W, yy);
    vertex(W, yy + 3);
    vertex(0, yy + 3);
    endShape(CLOSE);
  }
}

function paintHaze(y, h, c, a) {
  noStroke();
  for (let i = 0; i < 60; i++) {
    let yy = y + random(-h / 2, h / 2);
    let hh = random(10, 60);
    fill(red(c), green(c), blue(c), random(a * 0.3, a));
    rect(0, yy, W, hh);
  }
}

function drawRiver() {
  push();
  noStroke();

  // River shape via ribbons; brighter near horizon
  let riverTopY = H * 0.46;
  let riverBottomY = H * 0.98;

  for (let i = 0; i < 120; i++) {
    let t = i / 119;
    let y = lerp(riverTopY, riverBottomY, t);

    // River width expands toward viewer
    let wBase = lerp(W * 0.10, W * 0.78, pow(t, 1.2));
    let xCenter = W * 0.52 + riverMeander(y);

    // Soft edges
    let edge = lerp(40, 140, t);
    let brightness = lerp(240, 205, t);
    let warmth = lerp(240, 190, t);
    let a = lerp(30, 10, t) + random(-2, 2);

    // Add slight ripples using noise
    let ripple = map(noise(0.002 * y, 0.7), 0, 1, -18, 18);
    let left = xCenter - wBase / 2 + ripple;
    let right = xCenter + wBase / 2 + ripple;

    // Layered wash
    fill(brightness, warmth, 190, a);
    rect(left - edge, y, (right - left) + 2 * edge, 6);
  }

  // Glimmer specks along the path
  for (let i = 0; i < 5000; i++) {
    let y = random(riverTopY, riverBottomY);
    let t = (y - riverTopY) / (riverBottomY - riverTopY);
    let wBase = lerp(W * 0.08, W * 0.72, pow(t, 1.15));
    let xCenter = W * 0.52 + riverMeander(y);
    let x = xCenter + randomGaussian() * (wBase * 0.18);
    if (abs(x - xCenter) > wBase * 0.52) continue;

    let a = lerp(60, 8, t) * random(0.4, 1.0);
    let sz = lerp(2.2, 1.0, t) * random(0.6, 1.4);
    fill(255, 245, 220, a);
    ellipse(x, y + random(-2, 2), sz, sz);
  }
  pop();
}

function riverMeander(y) {
  let t = y / H;
  let n1 = noise(t * 1.2, 0.2);
  let n2 = noise(t * 3.0, 2.1);
  return (n1 - 0.5) * 160 + (n2 - 0.5) * 80;
}

function drawArch() {
  push();
  let cx = W * 0.52;
  let cy = H * 0.45;
  let archW = W * 0.20;
  let archH = H * 0.20;

  // Misty glow behind the arch
  noStroke();
  for (let i = 0; i < 120; i++) {
    let r = lerp(10, archW * 0.85, i / 119);
    fill(255, 248, 232, 10);
    ellipse(cx, cy + archH * 0.10, r, r * 0.85);
  }

  // Stone silhouette with painterly edges
  for (let layer = 0; layer < 8; layer++) {
    let jitter = layer * 2.0;
    let col = color(25 + layer * 3, 24 + layer * 3, 32 + layer * 4, 160 - layer * 10);
    fill(col);
    beginShape();
    // left base
    let baseY = cy + archH * 0.62 + random(-jitter, jitter);
    let leftX = cx - archW * 0.55 + random(-jitter, jitter);
    vertex(leftX, baseY);

    // left pillar up
    vertex(cx - archW * 0.50 + random(-jitter, jitter), cy + archH * 0.15 + random(-jitter, jitter));

    // arch curve
    let steps = 28;
    for (let i = 0; i <= steps; i++) {
      let a = map(i, 0, steps, PI, 0);
      let x = cx + cos(a) * (archW * 0.50 + random(-jitter, jitter));
      let y = cy + sin(a) * (archH * 0.48 + random(-jitter, jitter));
      vertex(x, y);
    }

    // right pillar down
    vertex(cx + archW * 0.50 + random(-jitter, jitter), cy + archH * 0.15 + random(-jitter, jitter));
    vertex(cx + archW * 0.55 + random(-jitter, jitter), baseY);

    // close
    endShape(CLOSE);
  }

  // Opening cut-out (dark interior) with faint inner glow
  blendMode(MULTIPLY);
  fill(8, 9, 14, 220);
  archCutout(cx, cy, archW * 0.65, archH * 0.75);
  blendMode(BLEND);

  // Inner light gradient
  for (let i = 0; i < 80; i++) {
    let t = i / 79;
    let a = lerp(24, 0, t);
    fill(255, 250, 238, a);
    archCutout(cx, cy + 2, archW * (0.60 - t * 0.10), archH * (0.70 - t * 0.12));
  }

  pop();
}

function archCutout(cx, cy, w, h) {
  noStroke();
  beginShape();
  let baseY = cy + h * 0.55;
  vertex(cx - w * 0.28, baseY);
  vertex(cx - w * 0.28, cy + h * 0.10);
  // semi-ellipse top
  let steps = 30;
  for (let i = 0; i <= steps; i++) {
    let a = map(i, 0, steps, PI, 0);
    let x = cx + cos(a) * (w * 0.28);
    let y = cy + sin(a) * (h * 0.38);
    vertex(x, y);
  }
  vertex(cx + w * 0.28, cy + h * 0.10);
  vertex(cx + w * 0.28, baseY);
  endShape(CLOSE);
}

function drawGround() {
  push();
  noStroke();

  // Ground gradient from mid to bottom
  for (let y = H * 0.55; y <= H; y += 3) {
    let t = (y - H * 0.55) / (H * 0.45);
    let c1 = color(40, 33, 30);
    let c2 = color(18, 16, 18);
    let c = lerpColor(c1, c2, pow(t, 1.3));
    fill(red(c), green(c), blue(c), 140);
    rect(0, y, W, 3);
  }

  // Soil speckles and grit
  for (let i = 0; i < 45000; i++) {
    let y = random(H * 0.58, H);
    let x = random(W);
    let t = (y - H * 0.58) / (H * 0.42);
    let a = lerp(10, 30, t) * random(0.2, 1.0);
    let r = lerp(70, 30, t) + random(-10, 10);
    let g = lerp(55, 25, t) + random(-10, 10);
    let b = lerp(50, 25, t) + random(-10, 10);
    fill(constrain(r, 0, 255), constrain(g, 0, 255), constrain(b, 0, 255), a);
    let sz = random(0.8, 2.4);
    ellipse(x, y, sz, sz);
  }

  // Dark silhouettes framing the river
  drawBanks();

  pop();
}

function drawBanks() {
  push();
  noStroke();
  let y0 = H * 0.60;

  for (let side = -1; side <= 1; side += 2) {
    for (let layer = 0; layer < 10; layer++) {
      let a = 28 - layer * 2;
      fill(8, 7, 10, a);

      beginShape();
      let startX = (side < 0) ? 0 : W;
      vertex(startX, y0);

      let steps = 22;
      for (let i = 0; i <= steps; i++) {
        let t = i / steps;
        let y = lerp(y0, H * 0.95, t);
        let riverW = lerp(W * 0.18, W * 0.82, pow((y - H * 0.46) / (H * 0.52), 1.2));
        let cx = W * 0.52 + riverMeander(y);
        let edgeX = cx + side * (riverW / 2);

        let bulge = map(noise(t * 1.6, 10 + side * 3 + layer * 0.2), 0, 1, -120, 120);
        let x = edgeX + side * (160 + layer * 14) + bulge;

        vertex(constrain(x, -200, W + 200), y);
      }

      vertex(startX, H);
      vertex(startX, y0 + 200);
      endShape(CLOSE);
    }
  }
  pop();
}

function drawFallenFlower() {
  push();
  let baseX = W * 0.28;
  let baseY = H * 0.84;

  // Stem (broken) with dry ink-like strokes
  for (let k = 0; k < 18; k++) {
    let a = 60 - k * 2.2;
    stroke(55, 50, 45, a);
    strokeWeight(2.2 - k * 0.07);
    noFill();

    let x1 = baseX + random(-6, 6);
    let y1 = baseY + random(-6, 6);
    let x2 = baseX + 280 + random(-10, 10);
    let y2 = baseY - 110 + random(-10, 10);

    let cx1 = baseX + 120 + random(-35, 35);
    let cy1 = baseY - 40 + random(-35, 35);
    let cx2 = baseX + 200 + random(-35, 35);
    let cy2 = baseY - 140 + random(-35, 35);

    bezier(x1, y1, cx1, cy1, cx2, cy2, x2, y2);
  }

  // Break point fibers
  noStroke();
  for (let i = 0; i < 220; i++) {
    let x = baseX + 90 + random(-25, 25);
    let y = baseY - 25 + random(-20, 20);
    fill(210, 200, 180, random(10, 35));
    ellipse(x, y, random(1, 3), random(1, 3));
  }

  // Leaves (wilted)
  for (let i = 0; i < 2; i++) {
    let lx = baseX + 150 + i * 70;
    let ly = baseY - 60 - i * 20;
    wiltedLeaf(lx, ly, random(140, 180), random(70, 90), i === 0 ? -0.7 : -0.2);
  }

  // Blossom head (fallen): muted, bruised petals
  let headX = baseX + 320;
  let headY = baseY - 140;
  for (let p = 0; p < 9; p++) {
    let ang = -0.8 + p * 0.28 + random(-0.08, 0.08);
    let r = 70 + random(-10, 14);
    let px = headX + cos(ang) * 18 + random(-4, 4);
    let py = headY + sin(ang) * 18 + random(-4, 4);
    petal(px, py, r, r * random(0.65, 0.9), ang, p);
  }

  // Dark center
  for (let i = 0; i < 160; i++) {
    let a = random(TWO_PI);
    let rr = random(0, 26);
    let x = headX + cos(a) * rr;
    let y = headY + sin(a) * rr;
    fill(35, 26, 26, random(35, 90));
    ellipse(x, y, random(2, 5), random(2, 5));
  }

  // Fallen petals scattered
  for (let i = 0; i < 12; i++) {
    let x = baseX + random(-60, 380);
    let y = baseY + random(40, 220);
    smallPetal(x, y, random(20, 42), random(-1.2, 0.2));
  }

  pop();
}

function wiltedLeaf(x, y, len, wid, rot) {
  push();
  translate(x, y);
  rotate(rot);
  noStroke();
  for (let i = 0; i < 28; i++) {
    let t = i / 27;
    let a = lerp(38, 6, t);
    let c1 = color(60, 58, 42, a);
    let c2 = color(30, 30, 24, a);
    let c = lerpColor(c1, c2, t);
    fill(c);
    beginShape();
    let steps = 18;
    for (let s = 0; s <= steps; s++) {
      let u = s / steps;
      let yy = (u - 0.5) * wid * (1 - t * 0.7);
      let xx = u * len * (1 - t * 0.08);
      let pinch = 1 - pow(abs(u - 0.5) * 2, 1.6);
      vertex(xx + noise(u * 2, t * 2) * 2, yy * pinch + noise(u * 4, 20 + t) * 2);
    }
    for (let s = steps; s >= 0; s--) {
      let u = s / steps;
      let yy = (u - 0.5) * wid * (1 - t * 0.7);
      let xx = u * len * (1 - t * 0.08);
      let pinch = 1 - pow(abs(u - 0.5) * 2, 1.6);
      vertex(xx + noise(u * 2, 40 + t * 2) * 2, -yy * pinch + noise(u * 4, 60 + t) * 2);
    }
    endShape(CLOSE);
  }

  // Vein hints
  stroke(120, 110, 90, 18);
  strokeWeight(1.2);
  noFill();
  for (let k = 0; k < 6; k++) {
    let yy = map(k, 0, 5, -wid * 0.22, wid * 0.22);
    bezier(0, 0, len * 0.25, yy * 0.2, len * 0.65, yy * 0.6, len * 0.98, yy);
  }
  pop();
}

function petal(x, y, w, h, ang, idx) {
  push();
  translate(x, y);
  rotate(ang);
  noStroke();

  // Bruised palette
  let base = color(210, 190, 175, 28);
  let bruise = color(120, 85, 95, 18);
  let shadow = color(60, 45, 52, 16);

  for (let l = 0; l < 32; l++) {
    let t = l / 31;
    let ww = w * (1 - t * 0.55);
    let hh = h * (1 - t * 0.55);
    let c = lerpColor(base, bruise, 0.45 + 0.35 * noise(idx * 0.5, t * 1.6));
    if (t > 0.7) c = lerpColor(c, shadow, (t - 0.7) / 0.3);

    fill(red(c), green(c), blue(c), alpha(c) * (1 - t * 0.35));

    beginShape();
    let steps = 24;
    for (let i = 0; i <= steps; i++) {
      let a = map(i, 0, steps, -PI * 0.9, 0);
      let rx = cos(a) * ww * 0.55;
      let ry = sin(a) * hh * 0.55;
      vertex(rx + noise(i * 0.08, t * 2.0) * 3, ry + noise(i * 0.12, 50 + t) * 3);
    }
    for (let i = steps; i >= 0; i--) {
      let a = map(i, 0, steps, 0, PI * 0.9);
      let rx = cos(a) * ww * 0.18 + ww * 0.45;
      let ry = sin(a) * hh * 0.45;
      vertex(rx + noise(i * 0.08, 20 + t * 2.0) * 3, ry + noise(i * 0.12, 80 + t) * 3);
    }
    endShape(CLOSE);
  }
  pop();
}

function smallPetal(x, y, s, rot) {
  push();
  translate(x, y);
  rotate(rot + random(-0.2, 0.2));
  noStroke();
  for (let i = 0; i < 18; i++) {
    let t = i / 17;
    let a = lerp(18, 4, t);
    fill(205, 185, 172, a);
    ellipse(0, 0, s * (1 - t * 0.35), s * 0.55 * (1 - t * 0.35));
  }
  // Bruise edge
  for (let i = 0; i < 22; i++) {
    fill(110, 80, 90, random(6, 14));
    let px = random(-s * 0.45, s * 0.45);
    let py = random(-s * 0.18, s * 0.18);
    ellipse(px, py, random(2, 5), random(2, 5));
  }
  pop();
}

function drawMoth() {
  push();
  let x = W * 0.60;
  let y = H * 0.70;

  // Place moth near river edge
  let y2 = y;
  let riverTopY = H * 0.46;
  let riverBottomY = H * 0.98;
  let t = (y2 - riverTopY) / (riverBottomY - riverTopY);
  let wBase = lerp(W * 0.08, W * 0.72, pow(constrain(t, 0, 1), 1.15));
  let cx = W * 0.52 + riverMeander(y2);
  x = cx + wBase * 0.46;

  // Glow from the river
  noStroke();
  for (let i = 0; i < 60; i++) {
    let r = lerp(6, 70, i / 59);
    fill(255, 247, 230, 5);
    ellipse(x - 10, y + 10, r, r);
  }

  // Body
  fill(60, 55, 60, 90);
  ellipse(x, y, 16, 46);

  // Wings (chalky)
  for (let layer = 0; layer < 26; layer++) {
    let a = 24 - layer * 0.7;
    fill(235, 230, 220, a);
    wing(x, y, 1, 120 - layer * 1.2, 90 - layer * 1.0, -0.35);
    wing(x, y, -1, 120 - layer * 1.2, 90 - layer * 1.0, 0.35);
  }

  // Wing dust specks
  for (let i = 0; i < 800; i++) {
    let px = x + random(-120, 120);
    let py = y + random(-70, 80);
    let dx = (px - x) / 120;
    let dy = (py - y) / 85;
    if (dx * dx + dy * dy > 1.0) continue;
    let aa = 10 * (1.0 - (dx * dx + dy * dy)) * random(0.4, 1.2);
    fill(255, 250, 240, aa);
    ellipse(px, py, random(1, 2.2), random(1, 2.2));
  }

  pop();
}

function wing(x, y, side, w, h, rot) {
  push();
  translate(x, y);
  rotate(rot);
  beginShape();
  let steps = 28;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let a = lerp(-PI * 0.15, PI * 0.95, t);
    let rx = cos(a) * w * 0.5 * side;
    let ry = sin(a) * h * 0.55;
    let n = noise(3 + i * 0.08, 8);
    vertex(rx + (n - 0.5) * 7, ry + (n - 0.5) * 7);
  }
  // inner return curve
  for (let i = steps; i >= 0; i--) {
    let t = i / steps;
    let a = lerp(PI * 0.95, -PI * 0.15, t);
    let rx = cos(a) * w * 0.18 * side + side * 30;
    let ry = sin(a) * h * 0.22 + 10;
    let n = noise(10 + i * 0.08, 18);
    vertex(rx + (n - 0.5) * 6, ry + (n - 0.5) * 6);
  }
  endShape(CLOSE);
  pop();
}

function paperTexture(n) {
  push();
  noStroke();
  for (let i = 0; i < n; i++) {
    let x = random(W);
    let y = random(H);
    let g = 235 + random(-25, 10);
    let a = random(2, 10);
    fill(g, g, g, a);
    rect(x, y, 1, 1);

    if (i % 4 === 0) {
      let g2 = 40 + random(-10, 10);
      fill(g2, g2, g2, random(1, 4));
      rect(x + random(-2, 2), y + random(-2, 2), 1, 1);
    }
  }
  pop();
}

function vignette() {
  push();
  noStroke();
  // soft vignette with large translucent ellipses
  for (let i = 0; i < 90; i++) {
    let t = i / 89;
    let a = lerp(0, 38, t);
    fill(0, 0, 0, a);
    let ww = lerp(W * 0.90, W * 1.25, t);
    let hh = lerp(H * 0.92, H * 1.30, t);
    ellipse(W * 0.52, H * 0.58, ww, hh);
  }
  pop();
}

function smoothstep(a, b, x) {
  x = constrain((x - a) / (b - a), 0, 1);
  return x * x * (3 - 2 * x);
}

// p5.js 1.11 - 1600x2000 still image
let W = 1600, H = 2000;

function setup() {
  createCanvas(W, H);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  background(8, 10, 16);

  paintGradientSky();
  paintClouds();
  paintMoon();
  paintDistantHills();
  paintMistLayers();
  paintPathAndBridge();
  paintFigures();
  paintRiver();
  paintTree();
  paintFallingPetals();
  paintVignette();
  paintFilmGrain();
}

function paintGradientSky() {
  noStroke();
  for (let y = 0; y < H; y++) {
    let t = y / H;
    // night indigo -> bruised violet -> near-black
    let r = lerp(10, 4, t);
    let g = lerp(14, 6, t);
    let b = lerp(28, 10, t);
    if (t > 0.55) {
      let tt = (t - 0.55) / 0.45;
      r = lerp(6, 2, tt);
      g = lerp(9, 3, tt);
      b = lerp(18, 6, tt);
    }
    fill(r, g, b);
    rect(0, y, W, 1);
  }

  // subtle warm band near horizon
  for (let i = 0; i < 240; i++) {
    let y = H * 0.55 + i;
    let a = map(i, 0, 240, 50, 0);
    fill(60, 40, 36, a);
    rect(0, y, W, 1);
  }
}

function paintClouds() {
  noStroke();
  let layers = 6;
  for (let k = 0; k < layers; k++) {
    let yBase = lerp(H * 0.06, H * 0.52, k / (layers - 1));
    let scale = lerp(0.0009, 0.0016, k / (layers - 1));
    let alpha = lerp(26, 10, k / (layers - 1));
    let cloudHue = lerpColor(color(32, 28, 44, 0), color(18, 18, 28, 0), k / (layers - 1));

    for (let x = -80; x < W + 80; x += 14) {
      let n = noise(x * scale, yBase * scale, 10 + k * 0.7);
      let lift = pow(n, 2.2) * 180;
      let y = yBase - lift;
      let w = 44 + n * 130;
      let h = 18 + n * 80;
      let c = color(red(cloudHue), green(cloudHue), blue(cloudHue), alpha);
      fill(c);
      ellipse(x + (k * 9), y, w, h);
    }
  }

  // vertical atmospheric veil
  for (let i = 0; i < 6500; i++) {
    let x = random(W);
    let y = random(H * 0.62);
    let a = random(2, 10);
    fill(14, 14, 20, a);
    circle(x, y, random(6, 34));
  }
}

function paintMoon() {
  push();
  translate(W * 0.73, H * 0.19);
  noStroke();

  // glow
  for (let i = 0; i < 40; i++) {
    let a = map(i, 0, 39, 34, 0);
    fill(170, 162, 142, a);
    circle(0, 0, 520 + i * 18);
  }

  // disc
  fill(176, 170, 154, 220);
  circle(0, 0, 500);

  // texture (craters)
  for (let i = 0; i < 160; i++) {
    let ang = random(TWO_PI);
    let rad = pow(random(), 0.65) * 220;
    let x = cos(ang) * rad;
    let y = sin(ang) * rad;
    let s = random(8, 46);
    let shade = random(0.78, 1.03);
    fill(150 * shade, 146 * shade, 134 * shade, random(35, 90));
    circle(x, y, s);
  }

  // partial eclipse / shadow bite
  fill(6, 7, 10, 190);
  circle(-120, 40, 520);

  pop();
}

function paintDistantHills() {
  noStroke();
  // far ridge
  fill(12, 12, 18, 210);
  beginShape();
  vertex(0, H * 0.60);
  for (let x = 0; x <= W; x += 20) {
    let n = noise(x * 0.002, 5.1);
    let y = H * 0.58 + n * 90;
    vertex(x, y);
  }
  vertex(W, H * 0.75);
  vertex(0, H * 0.75);
  endShape(CLOSE);

  // second ridge (darker)
  fill(8, 8, 12, 240);
  beginShape();
  vertex(0, H * 0.67);
  for (let x = 0; x <= W; x += 18) {
    let n = noise(x * 0.0023, 9.4);
    let y = H * 0.65 + n * 110;
    vertex(x, y);
  }
  vertex(W, H * 0.90);
  vertex(0, H * 0.90);
  endShape(CLOSE);
}

function paintMistLayers() {
  noStroke();
  // layered fog bands
  for (let k = 0; k < 11; k++) {
    let y0 = lerp(H * 0.58, H * 0.90, k / 10);
    let amp = lerp(18, 64, k / 10);
    let a = lerp(70, 12, k / 10);
    fill(26, 24, 30, a);
    beginShape();
    vertex(0, y0);
    for (let x = 0; x <= W; x += 14) {
      let n = noise(x * 0.003, y0 * 0.003, 30 + k * 0.5);
      vertex(x, y0 + (n - 0.5) * amp);
    }
    vertex(W, y0 + 220);
    vertex(0, y0 + 220);
    endShape(CLOSE);
  }

  // brighter center mist where the path leads
  for (let i = 0; i < 3800; i++) {
    let x = randomGaussian(W * 0.53, 230);
    let y = randomGaussian(H * 0.74, 260);
    if (x < -50 || x > W + 50 || y < 0 || y > H) continue;
    let d = dist(x, y, W * 0.53, H * 0.72);
    let a = map(d, 0, 700, 46, 0);
    fill(70, 62, 56, a);
    circle(x, y, random(10, 40));
  }
}

function paintPathAndBridge() {
  // a pale, worn path curving into fog + a thin bridge line
  noFill();
  strokeCap(ROUND);

  // path glow underpaint
  for (let k = 0; k < 9; k++) {
    let sw = 90 - k * 8;
    let a = 14 - k * 1.2;
    stroke(110, 96, 82, a);
    strokeWeight(sw);
    curvedPath();
  }

  // path core
  for (let k = 0; k < 4; k++) {
    stroke(64, 54, 46, 24 - k * 4);
    strokeWeight(20 - k * 3);
    curvedPath();
  }

  // bridge rail (thin, almost threadlike)
  for (let s = 0; s < 2; s++) {
    stroke(140, 120, 92, 90 - s * 30);
    strokeWeight(2.2 - s * 0.7);
    noFill();
    beginShape();
    let yBase = H * 0.73 + s * 12;
    for (let i = 0; i <= 40; i++) {
      let t = i / 40;
      let x = lerp(W * 0.22, W * 0.86, t);
      let y = lerp(yBase + 80, yBase - 30, t) - sin(t * PI) * 34;
      vertex(x, y);
    }
    endShape();
  }

  // faint planks / ripples on bridge
  stroke(120, 104, 86, 30);
  strokeWeight(1);
  for (let i = 0; i < 70; i++) {
    let t = i / 69;
    let x = lerp(W * 0.26, W * 0.84, t);
    let y = lerp(H * 0.80, H * 0.71, t) - sin(t * PI) * 24;
    line(x - 10, y + 8, x + 10, y - 8);
  }
}

function curvedPath() {
  beginShape();
  for (let i = 0; i <= 70; i++) {
    let t = i / 70;
    // path centerline
    let x = bezierPoint(W * 0.52, W * 0.46, W * 0.58, W * 0.52, t);
    let y = bezierPoint(H * 1.02, H * 0.90, H * 0.70, H * 0.60, t);
    // small waviness
    let w = (noise(t * 2.4, 12.3) - 0.5) * 24;
    vertex(x + w, y);
  }
  endShape();
}

function paintFigures() {
  // silhouettes walking into fog; no faces, no details
  // place them on/near the bridge region
  let figures = [
    { t: 0.35, s: 1.05 },
    { t: 0.44, s: 0.95 },
    { t: 0.53, s: 0.85 },
    { t: 0.61, s: 0.75 },
    { t: 0.70, s: 0.65 }
  ];

  for (let i = 0; i < figures.length; i++) {
    let t = figures[i].t;
    let s = figures[i].s;

    let x = lerp(W * 0.28, W * 0.83, t);
    let y = lerp(H * 0.80, H * 0.71, t) - sin(t * PI) * 24;

    let fog = map(t, 0.3, 0.75, 170, 40);
    let alpha = 140 - (t * 80);
    alpha = constrain(alpha, 35, 140);

    // soft halo that eats edges
    noStroke();
    for (let k = 0; k < 10; k++) {
      let a = map(k, 0, 9, 18, 0);
      fill(60, 54, 50, a);
      ellipse(x, y - 30 * s, 28 * s + k * 7, 80 * s + k * 12);
    }

    // body
    fill(7, 7, 10, alpha);
    ellipse(x, y - 42 * s, 22 * s, 52 * s);
    // head
    ellipse(x + random(-1, 1), y - 78 * s, 18 * s, 20 * s);

    // suggestion of cloak (torn)
    fill(6, 6, 9, alpha - 20);
    beginShape();
    vertex(x - 14 * s, y - 52 * s);
    vertex(x - 26 * s, y - 30 * s);
    vertex(x - 10 * s, y - 4 * s);
    vertex(x + 18 * s, y - 10 * s);
    vertex(x + 24 * s, y - 34 * s);
    vertex(x + 12 * s, y - 54 * s);
    endShape(CLOSE);

    // blend them into fog
    fill(30, 28, 32, fog * 0.22);
    ellipse(x, y - 45 * s, 64 * s, 120 * s);
  }
}

function paintRiver() {
  // Dark river in foreground, reflecting broken moonlight
  noStroke();

  // base water shape
  fill(4, 4, 7, 255);
  beginShape();
  vertex(0, H * 0.78);
  for (let x = 0; x <= W; x += 16) {
    let n = noise(x * 0.0022, 40.2);
    let y = H * 0.80 + n * 80;
    vertex(x, y);
  }
  vertex(W, H);
  vertex(0, H);
  endShape(CLOSE);

  // reflective streaks
  for (let i = 0; i < 2200; i++) {
    let x = random(W);
    let y = random(H * 0.80, H);
    let n = noise(x * 0.006, y * 0.008, 7.7);
    let a = pow(n, 3.0) * 90;
    let c = lerpColor(color(34, 30, 28, 0), color(118, 102, 86, 0), n);
    fill(red(c), green(c), blue(c), a);
    rect(x, y, random(6, 34), random(1, 3));
  }

  // slow eddies
  for (let i = 0; i < 420; i++) {
    let x = random(W);
    let y = random(H * 0.82, H);
    let r = random(20, 110);
    let a = random(6, 18);
    noFill();
    stroke(60, 52, 46, a);
    strokeWeight(random(0.8, 2.0));
    arc(x, y, r, r * random(0.5, 0.9), random(TWO_PI), random(TWO_PI));
  }
}

function paintTree() {
  // Withered tree on left foreground: stark, skeletal but organic
  push();
  translate(W * 0.14, H * 0.86);

  // trunk shadow
  strokeCap(ROUND);
  for (let k = 0; k < 5; k++) {
    stroke(0, 0, 0, 50 - k * 8);
    strokeWeight(34 - k * 5);
    line(0, 0, 40, -320);
  }

  // trunk core
  stroke(14, 12, 16, 230);
  strokeWeight(18);
  line(0, 0, 40, -320);

  // main branches
  drawBranch(40, -320, -PI * 0.78, 240, 14);
  drawBranch(40, -320, -PI * 0.38, 210, 12);
  drawBranch(40, -280, -PI * 0.55, 180, 11);

  // subtle root hints
  stroke(8, 8, 12, 200);
  strokeWeight(6);
  line(-10, 0, -90, 40);
  line(10, 0, 70, 60);
  line(0, 0, -30, 80);

  pop();
}

function drawBranch(x, y, ang, len, w) {
  if (len < 22) return;

  let x2 = x + cos(ang) * len;
  let y2 = y + sin(ang) * len;

  // bark jitter strokes for painterly feel
  for (let s = 0; s < 3; s++) {
    let j1 = random(-2, 2);
    let j2 = random(-2, 2);
    stroke(12, 10, 14, 220);
    strokeWeight(max(1, w + random(-2, 2)));
    line(x + j1, y + j2, x2 + j2, y2 + j1);
  }

  // branch splits
  let n = noise(x * 0.01, y * 0.01, len * 0.02);
  let split = map(n, 0, 1, 0.35, 0.65);

  let ang1 = ang + random(-0.55, -0.15) * split;
  let ang2 = ang + random(0.15, 0.55) * (1 - split);

  drawBranch(x2, y2, ang1, len * random(0.62, 0.78), w * 0.72);
  drawBranch(x2, y2, ang2, len * random(0.60, 0.76), w * 0.70);

  // occasional tiny twig
  if (random() < 0.35) {
    let ang3 = ang + random(-0.9, 0.9);
    drawBranch(x2, y2, ang3, len * random(0.30, 0.45), w * 0.45);
  }
}

function paintFallingPetals() {
  // Pale petals/ash drifting downward over water: life reduced to small, weightless forms
  noStroke();
  for (let i = 0; i < 900; i++) {
    let x = random(W);
    let y = random(H * 0.64, H);
    let drift = (noise(x * 0.005, y * 0.005, 90) - 0.5) * 40;
    let s = random(5, 18);
    let a = map(y, H * 0.64, H, 18, 52);
    let warm = noise(x * 0.01, y * 0.01, 3.3);
    let col = lerpColor(color(150, 132, 112, 0), color(210, 192, 162, 0), warm);
    fill(red(col), green(col), blue(col), a);
    push();
    translate(x + drift, y);
    rotate((noise(x * 0.01, y * 0.01, 11) - 0.5) * 1.8);
    ellipse(0, 0, s * 1.3, s * 0.7);
    pop();
  }

  // a few brighter, near-field petals
  for (let i = 0; i < 70; i++) {
    let x = random(W);
    let y = random(H * 0.82, H * 0.98);
    let s = random(18, 44);
    fill(220, 204, 174, 45);
    push();
    translate(x, y);
    rotate(random(-0.8, 0.8));
    ellipse(0, 0, s * 1.2, s * 0.55);
    pop();
  }
}

function paintVignette() {
  noStroke();
  // Darken edges to focus attention on the crossing
  for (let i = 0; i < 14; i++) {
    let a = map(i, 0, 13, 0, 80);
    fill(0, 0, 0, a);
    rect(i * 18, i * 20, W - i * 36, H - i * 40, 60);
  }

  // extra corner shade
  for (let i = 0; i < 1600; i++) {
    let x = random(W);
    let y = random(H);
    let d = min(
      dist(x, y, 0, 0),
      dist(x, y, W, 0),
      dist(x, y, 0, H),
      dist(x, y, W, H)
    );
    let a = map(d, 0, 900, 26, 0);
    if (a > 0) {
      fill(0, 0, 0, a);
      circle(x, y, random(20, 120));
    }
  }
}

function paintFilmGrain() {
  // gentle grain and tiny scratches (no text)
  loadPixels();
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      let idx = 4 * (y * W + x);
      let g = (noise(x * 0.02, y * 0.02, 123) - 0.5) * 10;
      pixels[idx] = constrain(pixels[idx] + g, 0, 255);
      pixels[idx + 1] = constrain(pixels[idx + 1] + g, 0, 255);
      pixels[idx + 2] = constrain(pixels[idx + 2] + g, 0, 255);
    }
  }
  updatePixels();

  // a few faint vertical scratches
  noFill();
  stroke(180, 170, 150, 14);
  strokeWeight(1);
  for (let i = 0; i < 10; i++) {
    let x = random(W);
    beginShape();
    for (let y = 0; y <= H; y += 40) {
      let w = (noise(x * 0.01, y * 0.005, i * 10) - 0.5) * 10;
      vertex(x + w, y);
    }
    endShape();
  }
}

// p5.js 1.11 — 1600×2000 still image
let tex, layer;

function setup() {
  randomSeed(1);
  noiseSeed(1);

  createCanvas(1600, 2000);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();

  tex = createGraphics(width, height);
  tex.colorMode(HSB, 360, 100, 100, 100);
  layer = createGraphics(width, height);
  layer.colorMode(HSB, 360, 100, 100, 100);
}

function draw() {
  background(0, 0, 5);

  drawSky();
  drawDistantHaze();
  drawRiverAndBanks();
  drawPathToDoor();
  drawDoor();
  drawFigureAndDissolve();
  drawFlowersLifeToWither();
  drawForegroundVignette();
  overlayTexture();
}

function drawSky() {
  // Gradient dusk sky
  for (let y = 0; y < height; y += 2) {
    let t = y / height;
    let cTop = color(228, 55, 10, 100);  // near-black indigo
    let cMid = color(240, 45, 18, 100);  // deep blue
    let cLow = color(32, 55, 30, 100);   // muted ember near horizon

    let c;
    if (t < 0.62) c = lerpColor(cTop, cMid, t / 0.62);
    else c = lerpColor(cMid, cLow, (t - 0.62) / 0.38);

    stroke(c);
    line(0, y, width, y);
  }

  // Cloud wisps (noise-based, painterly)
  noStroke();
  for (let k = 0; k < 180; k++) {
    let cx = random(width);
    let cy = random(height * 0.62);
    let w = random(180, 520);
    let h = random(40, 120);
    let baseA = random(4, 12);
    let hue = 235 + random(-10, 10);
    let sat = 18 + random(0, 10);
    let bri = 55 + random(-8, 8);

    for (let i = 0; i < 120; i++) {
      let a = baseA * (1 - i / 120);
      fill(hue, sat, bri, a);
      let nx = (noise((cx + i * 7) * 0.002, (cy + i * 11) * 0.002) - 0.5) * 90;
      let ny = (noise((cx + i * 13) * 0.002, (cy + i * 5) * 0.002) - 0.5) * 50;
      ellipse(cx + random(-w/2, w/2) + nx, cy + random(-h/2, h/2) + ny, random(30, 90), random(12, 50));
    }
  }

  // Subtle overhead grain gradient
  for (let y = 0; y < height * 0.75; y += 3) {
    let t = y / (height * 0.75);
    stroke(235, 18, 80, 3 * (1 - t));
    line(0, y + random(-1, 1), width, y + random(-1, 1));
  }
}

function drawDistantHaze() {
  // Horizon haze band
  noStroke();
  for (let y = int(height * 0.56); y < int(height * 0.72); y += 3) {
    let t = (y - height * 0.56) / (height * 0.16);
    let a = 18 * (1 - abs(t - 0.5) * 2);
    fill(30, 25, 85, a);
    rect(0, y, width, 3);
  }

  // Far silhouettes
  stroke(220, 25, 10, 55);
  strokeWeight(2);
  for (let i = 0; i < 14; i++) {
    let x0 = map(i, 0, 13, -80, width + 80);
    let y0 = height * 0.67 + sin(i * 0.6) * 12 + random(-6, 6);
    let x1 = x0 + random(40, 110);
    let y1 = y0 + random(-6, 10);
    line(x0, y0, x1, y1);
  }
}

function drawRiverAndBanks() {
  // River: reflective, dark, calm
  noStroke();
  for (let y = int(height * 0.64); y < height; y++) {
    let t = (y - height * 0.64) / (height * 0.36);
    let hue = lerp(225, 210, t);
    let sat = lerp(55, 35, t);
    let bri = lerp(12, 8, t);
    fill(hue, sat, bri, 100);
    rect(0, y, width, 1);
  }

  // Reflection streaks
  for (let i = 0; i < 600; i++) {
    let x = random(width);
    let y = random(height * 0.66, height);
    let t = (y - height * 0.66) / (height * 0.34);
    let a = 10 * (1 - t);
    stroke(32, 30, 70, a);
    strokeWeight(random(1, 3));
    line(x, y, x + random(-60, 60), y + random(-2, 2));
  }

  // Banks: left more alive, right more barren
  drawBank(true);
  drawBank(false);
}

function drawBank(isLeft) {
  let side = isLeft ? -1 : 1;
  let baseX = isLeft ? width * 0.2 : width * 0.8;
  let bankY0 = height * 0.72;

  noStroke();
  for (let i = 0; i < 220; i++) {
    let x = baseX + side * random(0, width * 0.34);
    let y = random(bankY0, height * 0.98);
    let t = (y - bankY0) / (height * 0.26);
    let hue = isLeft ? lerp(115, 95, t) : lerp(45, 30, t);
    let sat = isLeft ? lerp(55, 35, t) : lerp(25, 15, t);
    let bri = isLeft ? lerp(22, 10, t) : lerp(16, 7, t);
    let a = 18;
    fill(hue, sat, bri, a);
    ellipse(x, y, random(30, 120), random(14, 60));
  }
}

function drawPathToDoor() {
  // A pale path narrowing toward the doorway
  let y0 = height * 0.78;
  let y1 = height * 0.50;
  let xMid = width * 0.5;

  noStroke();
  for (let y = int(y1); y < int(y0); y++) {
    let t = (y - y1) / (y0 - y1);
    let w = lerp(width * 0.10, width * 0.62, t);
    let xL = xMid - w * 0.5;
    let xR = xMid + w * 0.5;

    let hue = lerp(35, 28, t);
    let sat = lerp(18, 10, t);
    let bri = lerp(26, 12, t);
    let a = lerp(30, 8, t);

    fill(hue, sat, bri, a);
    rect(xL, y, xR - xL, 1);
  }

  // Pebble/ash specks
  for (let i = 0; i < 1200; i++) {
    let y = random(height * 0.54, height * 0.90);
    let t = (y - height * 0.54) / (height * 0.36);
    let w = lerp(width * 0.08, width * 0.68, t);
    let x = width * 0.5 + random(-w * 0.5, w * 0.5);
    let a = lerp(14, 3, t);
    noStroke();
    fill(32, 8, 92, a);
    ellipse(x, y, random(1, 4), random(1, 4));
  }
}

function drawDoor() {
  let cx = width * 0.5;
  let cy = height * 0.56;
  let w = width * 0.34;
  let h = height * 0.48;

  // Glow behind
  noStroke();
  for (let i = 0; i < 80; i++) {
    let t = i / 79;
    let a = 14 * (1 - t);
    fill(32, 35, 80, a);
    ellipse(cx, cy + h * 0.06, w * (1.10 + t * 0.35), h * (0.95 + t * 0.28));
  }

  // Door opening: deep void
  noStroke();
  fill(230, 35, 3, 98);
  drawArch(cx, cy, w, h);

  // Rim light
  stroke(34, 20, 86, 35);
  strokeWeight(6);
  noFill();
  drawArchOutline(cx, cy, w * 1.01, h * 1.01);

  // Inner stars/embers (no text)
  clipArchAndDrawStars(cx, cy, w * 0.92, h * 0.92);
}

function drawArch(cx, cy, w, h) {
  // Rounded arch shape
  beginShape();
  let left = cx - w * 0.5;
  let right = cx + w * 0.5;
  let bottom = cy + h * 0.5;
  let top = cy - h * 0.05;

  vertex(left, bottom);
  vertex(left, cy + h * 0.05);

  // Top semicircle via points
  let rx = w * 0.5;
  let ry = h * 0.45;
  for (let a = PI; a <= TWO_PI; a += 0.03) {
    let x = cx + cos(a) * rx;
    let y = top + sin(a) * ry;
    vertex(x, y);
  }

  vertex(right, cy + h * 0.05);
  vertex(right, bottom);
  endShape(CLOSE);
}

function drawArchOutline(cx, cy, w, h) {
  beginShape();
  let left = cx - w * 0.5;
  let right = cx + w * 0.5;
  let bottom = cy + h * 0.5;
  let top = cy - h * 0.05;

  vertex(left, bottom);
  vertex(left, cy + h * 0.05);

  let rx = w * 0.5;
  let ry = h * 0.45;
  for (let a = PI; a <= TWO_PI; a += 0.02) {
    let x = cx + cos(a) * rx;
    let y = top + sin(a) * ry;
    vertex(x, y);
  }

  vertex(right, cy + h * 0.05);
  vertex(right, bottom);
  endShape();
}

function clipArchAndDrawStars(cx, cy, w, h) {
  layer.clear();
  layer.push();
  layer.noStroke();
  layer.fill(0);
  // Create a mask-like area by drawing stars only within the arch bounds.
  // We'll just test points with an implicit arch equation rather than true clip.
  for (let i = 0; i < 1600; i++) {
    let x = random(cx - w * 0.55, cx + w * 0.55);
    let y = random(cy - h * 0.48, cy + h * 0.52);
    if (!pointInArch(x, y, cx, cy, w, h)) continue;

    let t = map(y, cy - h * 0.48, cy + h * 0.52, 0, 1);
    let hue = lerp(38, 220, t) + random(-6, 6);
    let sat = lerp(25, 20, t);
    let bri = lerp(85, 55, t);
    let a = lerp(20, 8, t);

    layer.fill(hue, sat, bri, a);
    let r = random(1, 3.2);
    layer.ellipse(x, y, r, r);

    if (random() < 0.08) {
      layer.stroke(hue, sat, bri, a * 0.9);
      layer.strokeWeight(1);
      layer.line(x - random(6, 20), y + random(-2, 2), x + random(6, 20), y + random(-2, 2));
      layer.noStroke();
    }
  }

  // A faint vertical drift inside
  layer.noStroke();
  for (let i = 0; i < 140; i++) {
    let x = random(cx - w * 0.45, cx + w * 0.45);
    let y = random(cy - h * 0.42, cy + h * 0.48);
    if (!pointInArch(x, y, cx, cy, w, h)) continue;
    let a = 10;
    layer.fill(200, 25, 70, a);
    layer.ellipse(x + random(-6, 6), y + random(-60, 60), random(18, 60), random(40, 140));
  }

  layer.pop();
  image(layer, 0, 0);
}

function pointInArch(x, y, cx, cy, w, h) {
  // Arch: rectangle + top ellipse
  let left = cx - w * 0.5;
  let right = cx + w * 0.5;
  let bottom = cy + h * 0.5;
  let midY = cy + h * 0.05;
  let topCenterY = cy - h * 0.05;

  if (x < left || x > right || y > bottom) return false;

  if (y >= midY) return true;

  // Ellipse check for the dome
  let rx = w * 0.5;
  let ry = h * 0.45;
  let dx = (x - cx) / rx;
  let dy = (y - topCenterY) / ry;
  return (dx * dx + dy * dy) <= 1.0;
}

function drawFigureAndDissolve() {
  let cx = width * 0.5;
  let baseY = height * 0.80;

  // Cloaked figure silhouette facing doorway
  noStroke();
  for (let i = 0; i < 220; i++) {
    let t = i / 219;
    let y = lerp(baseY, height * 0.60, t);
    let w = lerp(width * 0.22, width * 0.06, t);
    let x = cx + (noise(t * 3.2) - 0.5) * 30;
    let a = lerp(18, 55, t);
    fill(230, 25, 6, a);
    ellipse(x, y, w * random(0.85, 1.05), random(10, 26));
  }

  // Subtle edge light on cloak
  stroke(34, 18, 82, 22);
  strokeWeight(3);
  noFill();
  beginShape();
  for (let i = 0; i <= 60; i++) {
    let t = i / 60;
    let y = lerp(baseY, height * 0.61, t);
    let x = cx - lerp(width * 0.11, width * 0.02, t) + sin(t * 3.1) * 10;
    vertex(x, y);
  }
  endShape();

  // Dissolving moth/bird-like fragments rising
  noStroke();
  for (let i = 0; i < 1600; i++) {
    let t = i / 1600;
    let x = cx + randomGaussian() * lerp(28, 170, t);
    let y = lerp(height * 0.72, height * 0.34, pow(t, 1.35)) + random(-18, 18);

    // Bias: more originate from figure area
    if (y > height * 0.76) continue;
    if (random() < 0.25 && dist(x, y, cx, height * 0.70) > 260) continue;

    let drift = noise(x * 0.002, y * 0.002) - 0.5;
    x += drift * 55;

    let size = random(4, 16) * (1.05 - t);
    let hue = lerp(36, 220, t) + random(-10, 10);
    let sat = lerp(25, 10, t);
    let bri = lerp(78, 55, t);
    let a = lerp(28, 5, t);

    // simple winged mark
    fill(hue, sat, bri, a);
    push();
    translate(x, y);
    rotate(drift * 1.2 + random(-0.6, 0.6));
    ellipse(-size * 0.35, 0, size * 0.85, size * 0.55);
    ellipse(size * 0.35, 0, size * 0.85, size * 0.55);
    pop();

    if (random() < 0.10) {
      stroke(hue, sat, bri, a * 0.8);
      strokeWeight(1);
      line(x, y, x + random(-12, 12), y + random(-28, -6));
      noStroke();
    }
  }
}

function drawFlowersLifeToWither() {
  // Left: fuller flowers; Right: brittle stems
  let yBase = height * 0.92;
  let leftX0 = width * 0.10;
  let leftX1 = width * 0.46;
  let rightX0 = width * 0.54;
  let rightX1 = width * 0.92;

  // Stems
  for (let i = 0; i < 46; i++) {
    let x = random(leftX0, leftX1);
    drawStem(x, yBase, random(height * 0.62, height * 0.82), true);
  }
  for (let i = 0; i < 56; i++) {
    let x = random(rightX0, rightX1);
    drawStem(x, yBase, random(height * 0.64, height * 0.86), false);
  }

  // Blooms left (some fresh, some bruised)
  for (let i = 0; i < 34; i++) {
    let x = random(leftX0, leftX1);
    let y = random(height * 0.64, height * 0.84);
    if (noise(x * 0.004, y * 0.004) < 0.45) continue;
    drawBloom(x, y, random(26, 64), true);
  }

  // Fallen petals crossing toward the path/door (life shedding)
  for (let i = 0; i < 520; i++) {
    let t = i / 520;
    let x = lerp(width * 0.24, width * 0.62, random());
    let y = lerp(height * 0.82, height * 0.98, random());
    x += (noise(x * 0.003, y * 0.003) - 0.5) * 90;
    let a = 18 * (1 - (y - height * 0.82) / (height * 0.16));
    noStroke();
    fill(332 + random(-10, 10), 22 + random(0, 10), 72 + random(-10, 5), a);
    push();
    translate(x, y);
    rotate(random(-1.5, 1.5));
    ellipse(0, 0, random(6, 18), random(3, 9));
    pop();
  }

  // Right: dust/seed drift
  for (let i = 0; i < 900; i++) {
    let x = random(rightX0, rightX1);
    let y = random(height * 0.70, height * 0.98);
    let t = (y - height * 0.70) / (height * 0.28);
    let a = lerp(10, 2, t);
    fill(45, 10, 85, a);
    ellipse(x + (noise(x * 0.01, y * 0.01) - 0.5) * 20, y, random(1, 3), random(1, 3));
  }
}

function drawStem(x, y0, yTop, alive) {
  let steps = 42;
  let sway = alive ? 22 : 14;

  let hue = alive ? 110 : 45;
  let sat = alive ? 50 : 16;
  let bri = alive ? 22 : 18;

  stroke(hue, sat, bri, alive ? 55 : 45);
  strokeWeight(alive ? 3 : 2);

  let px = x;
  let py = y0;
  for (let i = 1; i <= steps; i++) {
    let t = i / steps;
    let y = lerp(y0, yTop, t);
    let nx = (noise(x * 0.004, t * 2.4) - 0.5) * sway;
    let xx = x + nx + sin(t * 3.2) * (alive ? 6 : 3);
    line(px, py, xx, y);
    px = xx;
    py = y;
  }

  // Sparse leaves on alive stems
  if (alive && random() < 0.7) {
    noStroke();
    for (let k = 0; k < int(random(2, 5)); k++) {
      let t = random(0.35, 0.8);
      let y = lerp(y0, yTop, t);
      let nx = (noise(x * 0.004, t * 2.4) - 0.5) * sway;
      let xx = x + nx;
      fill(112, 35, 26, 35);
      push();
      translate(xx, y);
      rotate(random(-1.2, 1.2));
      ellipse(0, 0, random(14, 34), random(6, 18));
      pop();
    }
  }

  // Dry thorns on barren stems
  if (!alive && random() < 0.65) {
    stroke(38, 12, 60, 30);
    strokeWeight(1);
    for (let k = 0; k < int(random(1, 4)); k++) {
      let t = random(0.25, 0.9);
      let y = lerp(y0, yTop, t);
      let nx = (noise(x * 0.004, t * 2.4) - 0.5) * sway;
      let xx = x + nx;
      let dir = random() < 0.5 ? -1 : 1;
      line(xx, y, xx + dir * random(10, 26), y + random(-8, 8));
    }
  }
}

function drawBloom(x, y, s, alive) {
  // Painterly petals
  let petals = int(random(7, 12));
  let baseHue = alive ? 332 + random(-18, 10) : 18 + random(-10, 10);
  let baseSat = alive ? 35 + random(-8, 10) : 12 + random(0, 8);
  let baseBri = alive ? 75 + random(-12, 6) : 55 + random(-10, 8);

  noStroke();
  for (let p = 0; p < petals; p++) {
    let ang = (TWO_PI * p) / petals + random(-0.2, 0.2);
    let rr = s * random(0.32, 0.55);
    let px = x + cos(ang) * rr;
    let py = y + sin(ang) * rr;

    for (let i = 0; i < 24; i++) {
      let t = i / 23;
      let a = 18 * (1 - t);
      fill(baseHue + random(-8, 8), baseSat + random(-8, 8), baseBri + random(-10, 10), a);
      push();
      translate(px, py);
      rotate(ang + random(-0.3, 0.3));
      ellipse(random(-6, 6), random(-5, 5), s * random(0.28, 0.6), s * random(0.12, 0.32));
      pop();
    }
  }

  // center
  fill(42, 25, alive ? 70 : 60, 35);
  ellipse(x, y, s * 0.36, s * 0.36);
  fill(42, 18, alive ? 85 : 70, 18);
  ellipse(x + random(-2, 2), y + random(-2, 2), s * 0.18, s * 0.18);
}

function drawForegroundVignette() {
  // Darken corners like a canvas vignette
  noStroke();
  for (let i = 0; i < 120; i++) {
    let t = i / 119;
    let a = 18 * t;
    fill(230, 35, 2, a);
    rect(0 + i * 5, 0 + i * 6, width - i * 10, height - i * 12);
  }

  // Soft mist near bottom
  for (let i = 0; i < 220; i++) {
    let x = random(width);
    let y = random(height * 0.86, height);
    let a = random(4, 10);
    fill(32, 15, 85, a);
    ellipse(x, y, random(120, 520), random(40, 160));
  }
}

function overlayTexture() {
  tex.clear();
  tex.noStroke();

  // Paper grain
  for (let i = 0; i < 240000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.006, y * 0.006);
    let a = 6 + n * 10;
    let bri = 88 + (n - 0.5) * 10;
    tex.fill(35, 8, bri, a);
    tex.rect(x, y, 1, 1);
  }

  // Vertical glaze strokes
  tex.stroke(30, 10, 95, 5);
  tex.strokeWeight(2);
  for (let i = 0; i < 1800; i++) {
    let x = random(width);
    let y0 = random(-200, height);
    let len = random(80, 420);
    tex.line(x, y0, x + random(-6, 6), y0 + len);
  }

  blendMode(MULTIPLY);
  image(tex, 0, 0);
  blendMode(BLEND);

  // Final subtle tonal unify
  noStroke();
  fill(230, 20, 8, 10);
  rect(0, 0, width, height);
}

// p5.js 1.11 - still painting, 1600x2000
let W = 1600, H = 2000;

function setup() {
  createCanvas(W, H);
  pixelDensity(2);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  background(8, 9, 14);

  // Palette
  const cSkyTop = color(10, 12, 20);
  const cSkyMid = color(22, 26, 44);
  const cSkyLow = color(14, 16, 26);

  const cMist = color(210, 214, 220, 28);
  const cBone = color(232, 228, 214);
  const cAsh = color(38, 36, 40);
  const cSoil = color(20, 18, 20);
  const cRust = color(120, 62, 52);
  const cGold = color(190, 168, 110);

  // Offscreen for texture / soft layers
  let tex = createGraphics(W, H);
  tex.pixelDensity(2);
  tex.clear();

  drawSky();
  drawDistantGlow();
  drawGround();
  drawPath();

  // Mist layers
  for (let i = 0; i < 7; i++) {
    drawMistBand(map(i, 0, 6, H * 0.52, H * 0.88), 120 + i * 18, 0.65 - i * 0.06);
  }

  // Threshold (door/arch)
  drawThreshold();

  // Tree silhouette (living world, but withered)
  drawTree(W * 0.18, H * 0.60, H * 0.40);

  // Figure and dissolution
  drawFigure(W * 0.50, H * 0.76);

  // Moths/embers drifting upward (transition)
  drawMoths();

  // Star dust and upper grain
  drawStars();

  // Overall grain
  addGrain(25000, 20);
  addGrain(90000, 10);

  // Subtle vignette
  vignette();
}

// ---------- Sky ----------
function drawSky() {
  noStroke();
  // Vertical gradient using bands
  for (let y = 0; y < H; y++) {
    let t = y / (H - 1);
    let col;
    if (t < 0.55) {
      col = lerpColor(color(10, 12, 20), color(22, 26, 44), smoothstep(0.0, 0.55, t));
    } else {
      col = lerpColor(color(22, 26, 44), color(14, 16, 26), smoothstep(0.55, 1.0, t));
    }
    fill(red(col), green(col), blue(col));
    rect(0, y, W, 1);
  }

  // A dim, eclipsed "sun" (absence)
  push();
  blendMode(SCREEN);
  let cx = W * 0.72, cy = H * 0.22;
  for (let i = 0; i < 26; i++) {
    let r = 30 + i * 18;
    let a = 14 - i * 0.45;
    fill(90, 80, 110, a);
    ellipse(cx, cy, r * 2, r * 2);
  }
  pop();

  // Dark core of eclipse
  noStroke();
  fill(6, 7, 10, 235);
  ellipse(W * 0.72, H * 0.22, 180, 180);
}

// ---------- Distant glow near horizon ----------
function drawDistantGlow() {
  push();
  blendMode(SCREEN);
  noStroke();
  let hx = W * 0.50, hy = H * 0.52;
  for (let i = 0; i < 22; i++) {
    let r = 180 + i * 55;
    let a = 18 - i * 0.6;
    fill(130, 120, 150, max(0, a));
    ellipse(hx, hy, r * 2.2, r * 1.2);
  }
  pop();
}

// ---------- Ground ----------
function drawGround() {
  noStroke();
  // Base
  fill(18, 16, 18);
  rect(0, H * 0.55, W, H * 0.45);

  // Undulating terrain with noise strips
  for (let y = int(H * 0.55); y < H; y += 2) {
    let t = map(y, H * 0.55, H, 0, 1);
    let d = 10 + 40 * t;
    let shade = lerpColor(color(22, 19, 20), color(10, 9, 10), t);
    fill(red(shade), green(shade), blue(shade), 160);
    beginShape();
    vertex(0, y);
    for (let x = 0; x <= W; x += 40) {
      let n = noise(x * 0.002, y * 0.004);
      let yy = y + (n - 0.5) * d;
      vertex(x, yy);
    }
    vertex(W, y + 50);
    vertex(0, y + 50);
    endShape(CLOSE);
  }

  // Sparse dead grass strokes
  stroke(40, 35, 38, 55);
  strokeWeight(1);
  for (let i = 0; i < 3800; i++) {
    let x = random(W);
    let y = random(H * 0.62, H * 0.98);
    let h = random(6, 26);
    let lean = random(-6, 6);
    line(x, y, x + lean, y - h);
  }
  noStroke();
}

// ---------- Path / river of ash ----------
function drawPath() {
  // A pale path leading to the threshold (like a dry riverbed)
  let topY = H * 0.54;
  let botY = H * 0.98;

  for (let y = topY; y <= botY; y += 3) {
    let t = map(y, topY, botY, 0, 1);
    let halfW = lerp(110, 360, t);
    let center = W * 0.5 + (noise(y * 0.002) - 0.5) * 90;
    let left = center - halfW;
    let right = center + halfW;

    // Edge softness
    for (let k = 0; k < 7; k++) {
      let a = 14 - k * 2.2;
      fill(210, 206, 192, max(0, a));
      rect(left - k * 8, y, (right - left) + k * 16, 3);
    }

    // Inner ash texture
    let specks = int(2 + 6 * t);
    for (let s = 0; s < specks; s++) {
      let x = random(left, right);
      let a = 22 + 60 * (1 - t);
      fill(230, 226, 214, a);
      ellipse(x, y + random(-2, 2), random(1, 2.2), random(1, 2.2));
    }
  }

  // Scattered stones like pauses
  for (let i = 0; i < 90; i++) {
    let y = random(H * 0.60, H * 0.95);
    let t = map(y, H * 0.60, H * 0.95, 0, 1);
    let halfW = lerp(130, 330, t);
    let center = W * 0.5 + (noise(y * 0.002) - 0.5) * 90;
    let x = random(center - halfW * 0.85, center + halfW * 0.85);
    let r = random(4, 14) * (0.6 + t * 0.9);

    let col = lerpColor(color(120, 110, 105), color(40, 36, 38), random());
    noStroke();
    fill(red(col), green(col), blue(col), 140);
    ellipse(x, y, r * 1.4, r);
  }
}

// ---------- Mist ----------
function drawMistBand(y0, thickness, strength) {
  push();
  noStroke();
  blendMode(SCREEN);
  for (let i = 0; i < 140; i++) {
    let y = y0 + random(-thickness * 0.55, thickness * 0.55);
    let t = constrain(map(abs(y - y0), 0, thickness * 0.55, 1, 0), 0, 1);
    let a = 20 * strength * t;

    fill(210, 214, 220, a);
    let x1 = random(-200, W * 0.2);
    let x2 = random(W * 0.8, W + 200);
    let w = random(W * 0.8, W * 1.3);
    let h = random(40, 130);
    ellipse((x1 + x2) * 0.5 + random(-140, 140), y, w, h);
  }
  pop();
}

// ---------- Threshold (arch/door) ----------
function drawThreshold() {
  let cx = W * 0.5;
  let baseY = H * 0.58;
  let archW = 420;
  let archH = 620;

  // Outer halo (inviting but cold)
  push();
  blendMode(SCREEN);
  noStroke();
  for (let i = 0; i < 26; i++) {
    let r = i / 25;
    let w = archW + r * 280;
    let h = archH + r * 300;
    fill(170, 160, 190, 10 - i * 0.28);
    archShape(cx, baseY, w, h);
  }
  pop();

  // Stone frame
  noStroke();
  for (let i = 0; i < 14; i++) {
    let r = i / 13;
    let w = archW + r * 40;
    let h = archH + r * 42;
    let col = lerpColor(color(30, 28, 32), color(16, 14, 16), r);
    fill(red(col), green(col), blue(col), 210);
    archShape(cx, baseY, w, h);
  }

  // Inner void
  fill(4, 5, 7, 250);
  archShape(cx, baseY, archW * 0.78, archH * 0.82);

  // Inner faint depth gradient specks (like distant dust)
  push();
  clipArch(cx, baseY, archW * 0.78, archH * 0.82);
  blendMode(SCREEN);
  noStroke();
  for (let i = 0; i < 1200; i++) {
    let x = random(cx - archW * 0.35, cx + archW * 0.35);
    let y = random(baseY - archH * 0.95, baseY);
    let nn = noise(x * 0.006, y * 0.006);
    let a = 10 + 45 * pow(nn, 2.2);
    fill(180, 170, 200, a);
    ellipse(x, y, random(0.8, 2.0), random(0.8, 2.0));
  }
  pop();

  // Subtle "floor" lip
  noStroke();
  fill(10, 10, 12, 220);
  rectMode(CENTER);
  rect(cx, baseY + 8, archW * 0.82, 18, 9);
  rectMode(CORNER);
}

function archShape(cx, baseY, w, h) {
  // Draw an arch silhouette: rectangle + semicircle
  let topY = baseY - h;
  beginShape();
  // Left base
  vertex(cx - w * 0.5, baseY);
  // Left side up
  vertex(cx - w * 0.5, topY + w * 0.5);
  // Arc
  let steps = 70;
  for (let i = 0; i <= steps; i++) {
    let a = PI + (i / steps) * PI; // PI..2PI
    let x = cx + cos(a) * (w * 0.5);
    let y = (topY + w * 0.5) + sin(a) * (w * 0.5);
    vertex(x, y);
  }
  // Right side down
  vertex(cx + w * 0.5, topY + w * 0.5);
  vertex(cx + w * 0.5, baseY);
  endShape(CLOSE);
}

function clipArch(cx, baseY, w, h) {
  drawingContext.save();
  drawingContext.beginPath();
  let topY = baseY - h;
  // left side
  drawingContext.moveTo(cx - w * 0.5, baseY);
  drawingContext.lineTo(cx - w * 0.5, topY + w * 0.5);
  // arc
  drawingContext.arc(cx, topY + w * 0.5, w * 0.5, PI, TWO_PI);
  // right side
  drawingContext.lineTo(cx + w * 0.5, baseY);
  drawingContext.closePath();
  drawingContext.clip();
  // Will be restored by pop() caller, but we need a custom restore:
  // We'll intercept with pop() by calling drawingContext.restore in a custom wrapper.
  // Instead, do not use p5 pop here; do manual restore at end of clipped drawing using unclipArch.
}

function unclipArch() {
  drawingContext.restore();
}

// Override pop() usage around clipArch: we used save(), so ensure restore after drawing.
function popAfterClip() { unclipArch(); }

// ---------- Tree ----------
function drawTree(x, yBase, height) {
  push();
  noStroke();
  fill(10, 10, 12, 240);

  // Trunk
  let trunkW = 80;
  beginShape();
  vertex(x - trunkW * 0.30, yBase);
  vertex(x - trunkW * 0.10, yBase - height * 0.30);
  vertex(x - trunkW * 0.05, yBase - height * 0.58);
  vertex(x - trunkW * 0.12, yBase - height * 0.86);
  vertex(x + trunkW * 0.06, yBase - height);
  vertex(x + trunkW * 0.18, yBase - height * 0.84);
  vertex(x + trunkW * 0.12, yBase - height * 0.56);
  vertex(x + trunkW * 0.24, yBase - height * 0.28);
  vertex(x + trunkW * 0.38, yBase);
  endShape(CLOSE);

  // Branches: crooked strokes
  stroke(8, 8, 10, 235);
  strokeWeight(7);
  strokeCap(ROUND);
  for (let i = 0; i < 14; i++) {
    let bx = x + random(-30, 40);
    let by = yBase - random(height * 0.35, height * 0.98);
    let len = random(140, 360);
    let ang = random(-PI * 0.95, -PI * 0.15);
    drawBranch(bx, by, len, ang, 7);
  }

  // Fine twigs
  strokeWeight(2);
  for (let i = 0; i < 90; i++) {
    let bx = x + random(-40, 60);
    let by = yBase - random(height * 0.48, height * 0.98);
    let len = random(40, 140);
    let ang = random(-PI * 1.05, -PI * 0.05);
    drawBranch(bx, by, len, ang, 2);
  }

  // A few hanging "leaves" (dead petals) near base
  noStroke();
  for (let i = 0; i < 40; i++) {
    let px = x + random(-220, 70);
    let py = random(yBase - 30, yBase + 140);
    let s = random(6, 22);
    fill(70, 40, 40, random(60, 120));
    ellipse(px, py, s * 0.9, s * 0.55);
  }

  pop();
}

function drawBranch(x, y, len, ang, w) {
  let steps = int(len / 14);
  let px = x, py = y;
  for (let i = 0; i < steps; i++) {
    let t = i / max(1, steps - 1);
    let a = ang + (noise(x * 0.01 + i * 0.12, y * 0.01) - 0.5) * 0.7;
    let step = len / steps;
    let nx = px + cos(a) * step;
    let ny = py + sin(a) * step;
    strokeWeight(max(0.5, w * (1 - t)));
    line(px, py, nx, ny);
    px = nx; py = ny;
  }
}

// ---------- Figure ----------
function drawFigure(cx, cy) {
  // Standing near the path, facing the threshold
  // Body as a soft silhouette, edges dissolving upward.
  push();
  noStroke();

  // Shadow on ground
  fill(0, 0, 0, 90);
  ellipse(cx, cy + 130, 240, 80);

  // Cloak base
  for (let i = 0; i < 34; i++) {
    let t = i / 33;
    let w = lerp(160, 100, t);
    let h = lerp(320, 240, t);
    let a = lerp(210, 0, t);
    fill(12, 12, 16, a);
    ellipse(cx + (noise(i * 0.2) - 0.5) * 10, cy - t * 90, w, h);
  }

  // Head/hood void
  fill(5, 6, 8, 230);
  ellipse(cx, cy - 170, 78, 92);

  // A thin rim-light on the figure (cold bone)
  push();
  blendMode(SCREEN);
  noFill();
  stroke(220, 214, 200, 28);
  strokeWeight(2);
  beginShape();
  for (let a = -PI * 0.15; a <= PI * 1.15; a += 0.08) {
    let rx = 78, ry = 210;
    let x = cx + cos(a) * rx * 0.62;
    let y = cy - 60 + sin(a) * ry * 0.62;
    vertex(x, y);
  }
  endShape();
  pop();

  // Dissolving fragments (from shoulders upward)
  push();
  blendMode(SCREEN);
  for (let i = 0; i < 1800; i++) {
    let t = random();
    let x = cx + randomGaussian(0, 38) + (noise(i * 0.02) - 0.5) * 30;
    let y = cy - 230 - t * 320 + random(-20, 20);
    let drift = (1 - t) * 120;
    x += (noise(i * 0.03, y * 0.003) - 0.5) * drift + t * 40;
    let s = random(1.0, 4.2) * (0.6 + (1 - t));
    let a = 10 + 40 * (1 - t);
    fill(220, 210, 190, a);
    ellipse(x, y, s, s * random(0.8, 1.4));
  }
  pop();

  pop();
}

// ---------- Moths ----------
function drawMoths() {
  // A drifting swarm moving from figure toward sky and threshold
  let originX = W * 0.50;
  let originY = H * 0.62;

  push();
  blendMode(SCREEN);
  noStroke();

  for (let i = 0; i < 1700; i++) {
    let t = pow(random(), 0.65);
    let y = lerp(H * 0.78, H * 0.12, t);
    let x = originX + (noise(i * 0.02, t * 2.2) - 0.5) * lerp(120, 620, t)
                      + sin(t * 4.2 + i * 0.03) * lerp(0, 70, t);
    // bias toward the threshold center
    x = lerp(x, W * 0.50, 0.35 * t);

    let s = lerp(5.2, 1.6, t) * random(0.55, 1.15);

    // warm/cool mix
    let warm = random() < 0.25;
    if (warm) fill(190, 168, 110, lerp(70, 10, t));
    else fill(200, 210, 230, lerp(60, 8, t));

    // simple moth: two wings
    let ang = noise(i * 0.04, t * 1.1) * TWO_PI;
    let dx = cos(ang) * s * 0.9;
    let dy = sin(ang) * s * 0.35;
    ellipse(x - dx, y - dy, s * 1.2, s * 0.75);
    ellipse(x + dx, y + dy, s * 1.2, s * 0.75);

    // tiny body
    fill(220, 220, 230, lerp(40, 6, t));
    ellipse(x, y, s * 0.55, s * 0.55);
  }
  pop();
}

// ---------- Stars ----------
function drawStars() {
  push();
  blendMode(SCREEN);
  noStroke();

  // Sparse stars
  for (let i = 0; i < 1600; i++) {
    let x = random(W);
    let y = random(H * 0.02, H * 0.55);
    let n = noise(x * 0.006, y * 0.006);
    if (n < 0.55) continue;
    let s = random(0.8, 2.2) * map(n, 0.55, 0.85, 0.7, 1.4);
    let a = map(n, 0.55, 1.0, 8, 42);
    fill(210, 220, 240, a);
    ellipse(x, y, s, s);
  }

  // A faint band (like dust) that also reads as breath
  for (let i = 0; i < 9000; i++) {
    let t = random();
    let x = lerp(-100, W + 100, t);
    let y = H * 0.26 + sin(t * 2.4) * 70 + (noise(t * 3.0) - 0.5) * 120;
    y += randomGaussian(0, 80);
    if (y < 0 || y > H * 0.6) continue;
    let a = 2.5;
    fill(200, 210, 240, a);
    rect(x, y, 1, 1);
  }

  pop();
}

// ---------- Grain ----------
function addGrain(count, alphaMax) {
  noStroke();
  for (let i = 0; i < count; i++) {
    let x = random(W);
    let y = random(H);
    let v = random(0, 255);
    fill(v, v, v, random(0, alphaMax));
    rect(x, y, 1, 1);
  }
}

// ---------- Vignette ----------
function vignette() {
  push();
  noStroke();
  for (let i = 0; i < 22; i++) {
    let t = i / 21;
    let a = 10 + 24 * t;
    fill(0, 0, 0, a);
    rect(-i * 10, -i * 10, W + i * 20, H + i * 20, 80);
  }
  pop();
}

// ---------- Utilities ----------
function smoothstep(e0, e1, x) {
  let t = constrain((x - e0) / (e1 - e0), 0, 1);
  return t * t * (3 - 2 * t);
}

// Fix the clip restore: p5 pop() won't restore our manual save. Wrap clipped drawing properly.
function pop() {
  // p5's pop exists; we shadowed it accidentally if we define pop().
  // Avoid shadowing by not defining it. This function intentionally left empty.
}

// p5.js 1.11 — static generative painting, 1600×2000
let W = 1600, H = 2000;

function setup() {
  createCanvas(W, H);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  randomSeed(1);
  noiseSeed(1);

  // Base gradient sky
  drawSky();

  // Distant haze + eclipse
  drawEclipse();

  // Central threshold/doorway
  drawThreshold();

  // Dead branches framing
  drawBranches();

  // Foreground field with wilted flowers and falling petals
  drawField();

  // Moth-like fragile presence near the threshold
  drawMoth();

  // Atmospheric grain + vignette
  addGrain(0.085);
  vignette();
}

function drawSky() {
  background(7, 7, 12);

  // Vertical gradient with subtle color drift
  noStroke();
  for (let y = 0; y < H; y++) {
    let t = y / (H - 1);
    // Deep indigo to near-black with a cold green trace
    let r = lerp(10, 4, t);
    let g = lerp(12, 6, t);
    let b = lerp(26, 10, t);
    // Add a faint bruised band in the middle
    let band = exp(-pow((t - 0.52) / 0.18, 2));
    r += 12 * band;
    g += 7 * band;
    b += 5 * band;
    fill(r, g, b, 255);
    rect(0, y, W, 1);
  }

  // Misty horizontal veils
  blendMode(SOFT_LIGHT);
  for (let i = 0; i < 180; i++) {
    let y = random(H * 0.05, H * 0.8);
    let h = random(10, 55);
    let a = random(6, 18);
    fill(170, 150, 140, a);
    rect(0, y, W, h);
  }
  blendMode(BLEND);

  // Fine dust points
  stroke(220, 210, 200, 10);
  strokeWeight(1);
  for (let i = 0; i < 9000; i++) {
    let x = random(W);
    let y = random(H * 0.82);
    if (random() < 0.65) point(x, y);
  }
}

function drawEclipse() {
  push();
  translate(W * 0.62, H * 0.26);

  // Glow halo
  noStroke();
  for (let i = 0; i < 70; i++) {
    let t = i / 69;
    let rad = lerp(280, 40, t);
    let a = lerp(0, 34, t);
    fill(210, 196, 182, a);
    ellipse(0, 0, rad, rad);
  }

  // Pale disc
  fill(208, 196, 186, 145);
  ellipse(0, 0, 180, 180);

  // Occluding dark body (eclipse)
  fill(12, 12, 18, 210);
  ellipse(-30, 22, 150, 150);

  // Thin rim light
  noFill();
  stroke(220, 205, 190, 55);
  strokeWeight(2);
  arc(0, 0, 182, 182, -PI * 0.15, PI * 0.85);

  pop();

  // Low fog under eclipse
  blendMode(OVERLAY);
  noStroke();
  for (let i = 0; i < 120; i++) {
    let y = random(H * 0.25, H * 0.55);
    let x = random(W);
    let w = random(220, 720);
    let h = random(12, 40);
    let a = random(5, 14);
    fill(160, 145, 135, a);
    ellipse(x, y, w, h);
  }
  blendMode(BLEND);
}

function drawThreshold() {
  let cx = W * 0.5;
  let cy = H * 0.56;

  // Ground haze behind
  noStroke();
  for (let i = 0; i < 120; i++) {
    let y = lerp(H * 0.48, H * 0.78, i / 119);
    let a = lerp(22, 0, i / 119);
    fill(120, 105, 95, a);
    rect(0, y, W, 3);
  }

  // Door geometry
  let doorW = W * 0.26;
  let doorH = H * 0.48;
  let x0 = cx - doorW / 2;
  let y0 = cy - doorH / 2;

  // Outer aura
  blendMode(SCREEN);
  noStroke();
  for (let i = 0; i < 60; i++) {
    let t = i / 59;
    let pad = lerp(140, 10, t);
    let a = lerp(0, 55, t);
    fill(210, 192, 176, a);
    rect(x0 - pad, y0 - pad, doorW + pad * 2, doorH + pad * 2, 12);
  }
  blendMode(BLEND);

  // Dark interior with slight depth gradient
  noStroke();
  for (let i = 0; i < 220; i++) {
    let t = i / 219;
    let yy = y0 + t * doorH;
    let a = 255;
    let r = lerp(10, 3, t);
    let g = lerp(10, 3, t);
    let b = lerp(14, 4, t);
    fill(r, g, b, a);
    rect(x0, yy, doorW, doorH / 220 + 1);
  }

  // Inner rim light + hairline cracks
  stroke(220, 205, 190, 95);
  strokeWeight(2);
  noFill();
  rect(x0 + 8, y0 + 8, doorW - 16, doorH - 16, 10);

  // Uneven glow along edges
  for (let k = 0; k < 900; k++) {
    let side = random();
    let x, y;
    if (side < 0.25) { // left
      x = x0 + random(0, 18);
      y = y0 + random(0, doorH);
    } else if (side < 0.5) { // right
      x = x0 + doorW - random(0, 18);
      y = y0 + random(0, doorH);
    } else if (side < 0.75) { // top
      x = x0 + random(0, doorW);
      y = y0 + random(0, 18);
    } else { // bottom
      x = x0 + random(0, doorW);
      y = y0 + doorH - random(0, 18);
    }
    let n = noise(x * 0.006, y * 0.006);
    stroke(220, 204, 188, 35 + 60 * n);
    point(x, y);
  }

  // A thin, slanted shadow crossing the door like a veil
  push();
  clip(() => rect(x0, y0, doorW, doorH));
  blendMode(MULTIPLY);
  noStroke();
  for (let i = 0; i < 140; i++) {
    let t = i / 139;
    let y = y0 + doorH * (0.15 + 0.75 * t);
    let x = x0 + doorW * (0.05 + 0.25 * sin(t * PI));
    fill(0, 0, 0, 10);
    ellipse(x + doorW * 0.35, y, doorW * 1.2, 18);
  }
  blendMode(BLEND);
  pop();
}

function drawBranches() {
  // Branches from upper corners, charcoal-like
  strokeCap(ROUND);

  // Left set
  for (let i = 0; i < 9; i++) {
    let x0 = random(W * 0.02, W * 0.20);
    let y0 = random(H * 0.02, H * 0.26);
    let x1 = random(W * 0.28, W * 0.48);
    let y1 = random(H * 0.25, H * 0.50);
    drawBranch(x0, y0, x1, y1, random(8, 14));
  }

  // Right set
  for (let i = 0; i < 9; i++) {
    let x0 = random(W * 0.80, W * 0.98);
    let y0 = random(H * 0.03, H * 0.28);
    let x1 = random(W * 0.52, W * 0.72);
    let y1 = random(H * 0.25, H * 0.52);
    drawBranch(x0, y0, x1, y1, random(8, 14));
  }
}

function drawBranch(x0, y0, x1, y1, w0) {
  let steps = 120;
  let px = x0, py = y0;

  for (let i = 1; i <= steps; i++) {
    let t = i / steps;
    // Curved path with noise jitter
    let cx = lerp(x0, x1, t) + (noise(t * 2.1, x0 * 0.002) - 0.5) * 70 * (1 - t);
    let cy = lerp(y0, y1, t) + (noise(t * 2.1, y0 * 0.002 + 9.1) - 0.5) * 55 * (1 - t);

    let w = lerp(w0, 1.2, t);
    strokeWeight(w);
    let a = lerp(90, 22, t);
    stroke(30, 26, 28, a);
    line(px, py, cx, cy);

    // Dry bark highlights
    if (random() < 0.15) {
      strokeWeight(max(0.8, w * 0.25));
      stroke(170, 150, 130, 18);
      line(px + random(-2, 2), py + random(-2, 2), cx + random(-2, 2), cy + random(-2, 2));
    }

    // Small twigs
    if (i > 20 && i < 95 && random() < 0.05) {
      let ang = random(-1.2, 1.2);
      let len = random(18, 60) * (1 - t);
      let tx = cx + cos(ang) * len;
      let ty = cy + sin(ang) * len;
      strokeWeight(max(0.8, w * 0.35));
      stroke(26, 22, 24, a * 0.75);
      line(cx, cy, tx, ty);
    }

    px = cx; py = cy;
  }
}

function drawField() {
  let horizon = H * 0.70;

  // Distant ground gradient
  noStroke();
  for (let y = horizon; y < H; y++) {
    let t = (y - horizon) / (H - horizon);
    let r = lerp(35, 18, t);
    let g = lerp(26, 14, t);
    let b = lerp(24, 12, t);
    fill(r, g, b, 255);
    rect(0, y, W, 1);
  }

  // Ashy fog near horizon
  blendMode(SOFT_LIGHT);
  for (let i = 0; i < 180; i++) {
    let x = random(W);
    let y = random(horizon - 40, horizon + 140);
    let w = random(220, 900);
    let h = random(18, 65);
    fill(160, 145, 135, random(4, 11));
    ellipse(x, y, w, h);
  }
  blendMode(BLEND);

  // Grass strokes
  for (let layer = 0; layer < 3; layer++) {
    let count = layer === 0 ? 7000 : (layer === 1 ? 5200 : 3600);
    for (let i = 0; i < count; i++) {
      let x = random(W);
      let y = random(horizon + 10, H);
      let t = (y - horizon) / (H - horizon);
      let len = lerp(8, 95, t) * (0.65 + 0.7 * random());
      let tilt = lerp(-0.7, 0.7, noise(x * 0.003, y * 0.004, layer * 2.0));
      let x2 = x + tilt * len * 0.55;
      let y2 = y - len;

      let a = lerp(18, 70, t) * (layer === 2 ? 1.0 : 0.85);
      let r = lerp(70, 30, t) + random(-6, 6);
      let g = lerp(52, 22, t) + random(-6, 6);
      let b = lerp(46, 20, t) + random(-6, 6);

      stroke(r, g, b, a);
      strokeWeight(0.7 + 1.2 * t);
      line(x, y, x2, y2);
    }
  }

  // Wilted flowers clustered around the threshold
  let cx = W * 0.5;
  let cy = H * 0.56;
  for (let i = 0; i < 28; i++) {
    let side = random() < 0.5 ? -1 : 1;
    let x = cx + side * random(W * 0.12, W * 0.38);
    let y = random(H * 0.74, H * 0.96);
    drawWiltedFlower(x, y, random(140, 260), random(0.8, 1.3));
  }

  // Scatter petals like pale fragments
  for (let i = 0; i < 1400; i++) {
    let x = random(W);
    let y = random(horizon + 40, H);
    if (random() < 0.65) continue;
    let t = (y - horizon) / (H - horizon);
    let a = 10 + 55 * t * random();
    fill(210, 196, 182, a);
    noStroke();
    let s = random(2, 8) * (0.5 + 0.9 * t);
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    ellipse(0, 0, s * 1.6, s);
    pop();
  }

  // Dark puddle-like shapes: absorption, not reflection
  blendMode(MULTIPLY);
  noStroke();
  for (let i = 0; i < 22; i++) {
    let x = random(W * 0.18, W * 0.82);
    let y = random(H * 0.78, H * 0.98);
    let w = random(140, 380);
    let h = random(40, 140);
    fill(0, 0, 0, random(18, 42));
    ellipse(x, y, w, h);
  }
  blendMode(BLEND);
}

function drawWiltedFlower(x, y, len, scaleF) {
  push();
  translate(x, y);

  // Stem
  let sway = random(-0.6, 0.6);
  let x0 = 0, y0 = 0;
  let x1 = sway * 40, y1 = -len * 0.55;
  let x2 = sway * 65, y2 = -len;

  stroke(70, 55, 45, 95);
  strokeWeight(3.0 * scaleF);
  noFill();
  beginShape();
  for (let i = 0; i <= 60; i++) {
    let t = i / 60;
    let xx = bezierPoint(x0, x1, x2, x2 + random(-6, 6), t);
    let yy = bezierPoint(y0, y1, y2, y2 + random(-6, 6), t);
    vertex(xx, yy);
  }
  endShape();

  // Leaves (drooping)
  stroke(62, 48, 40, 65);
  strokeWeight(2.2 * scaleF);
  for (let k = 0; k < 2; k++) {
    let ly = -len * random(0.25, 0.55);
    let dir = (k === 0 ? -1 : 1) * random(0.8, 1.3);
    let lx = dir * random(12, 26);
    let l2x = dir * random(45, 85);
    let l2y = ly + random(40, 90);
    noFill();
    beginShape();
    vertex(0, ly);
    quadraticVertex(lx, ly + 10, l2x, l2y);
    endShape();
  }

  // Head (withered)
  let hx = x2 * 0.75;
  let hy = y2;
  translate(hx, hy);
  rotate(sway * 0.9 + random(-0.25, 0.25));

  // Dark core
  noStroke();
  fill(18, 16, 18, 180);
  ellipse(0, 0, 30 * scaleF, 22 * scaleF);

  // Petals (faded, some missing)
  for (let p = 0; p < 10; p++) {
    if (random() < 0.28) continue;
    let ang = (TWO_PI * p) / 10 + random(-0.12, 0.12);
    let rad = random(18, 34) * scaleF;
    let w = random(10, 18) * scaleF;
    let h = random(22, 36) * scaleF;

    let fade = random(0.45, 1.0);
    fill(205, 190, 176, 70 * fade);
    stroke(120, 105, 95, 25 * fade);
    strokeWeight(1);

    push();
    rotate(ang);
    translate(rad, 0);
    rotate(random(-0.5, 0.5));
    ellipse(0, 0, h, w);
    pop();
  }

  // Falling fragments near head
  noStroke();
  for (let i = 0; i < 12; i++) {
    if (random() < 0.4) continue;
    let fx = random(-60, 60) * scaleF;
    let fy = random(10, 120) * scaleF;
    fill(215, 200, 188, random(18, 55));
    push();
    translate(fx, fy);
    rotate(random(TWO_PI));
    ellipse(0, 0, random(4, 10) * scaleF, random(2, 6) * scaleF);
    pop();
  }

  pop();
}

function drawMoth() {
  let cx = W * 0.50;
  let cy = H * 0.58;
  let x = cx + random(-40, 40);
  let y = cy + random(-40, 40);

  push();
  translate(x, y);
  rotate(random(-0.25, 0.25));

  // Soft aura (as if attracted to the threshold)
  blendMode(SCREEN);
  noStroke();
  for (let i = 0; i < 40; i++) {
    let t = i / 39;
    fill(210, 196, 182, lerp(0, 40, t));
    ellipse(0, 0, lerp(120, 20, t), lerp(90, 14, t));
  }
  blendMode(BLEND);

  // Body
  noStroke();
  fill(20, 18, 20, 160);
  ellipse(0, 0, 10, 34);

  // Wings (charcoal + dust)
  for (let s = -1; s <= 1; s += 2) {
    push();
    scale(s, 1);
    rotate(-0.2 + random(-0.05, 0.05));

    fill(25, 22, 26, 130);
    beginShape();
    vertex(0, -6);
    bezierVertex(50, -40, 92, -10, 86, 24);
    bezierVertex(78, 56, 40, 60, 8, 22);
    bezierVertex(-2, 10, -2, 4, 0, -6);
    endShape(CLOSE);

    // Pale dust specks on wing
    stroke(220, 205, 190, 28);
    strokeWeight(1);
    for (let i = 0; i < 220; i++) {
      let wx = random(8, 84);
      let wy = random(-34, 52);
      if (random() < 0.55) continue;
      point(wx, wy);
    }

    pop();
  }

  pop();
}

function addGrain(amount) {
  loadPixels();
  let d = pixelDensity();
  let n = 4 * (W * d) * (H * d);
  for (let i = 0; i < n; i += 4) {
    let g = (random() - 0.5) * 255 * amount;
    pixels[i] = constrain(pixels[i] + g, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + g, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + g, 0, 255);
  }
  updatePixels();
}

function vignette() {
  noStroke();
  blendMode(MULTIPLY);
  let steps = 80;
  for (let i = 0; i < steps; i++) {
    let t = i / (steps - 1);
    let a = lerp(0, 95, t);
    fill(0, 0, 0, a);
    rect(-i * 7, -i * 7, W + i * 14, H + i * 14, 40);
  }
  blendMode(BLEND);

  // Slight vertical darkening at bottom
  noStroke();
  blendMode(MULTIPLY);
  for (let y = 0; y < H; y++) {
    let t = y / (H - 1);
    let a = 70 * pow(t, 2.2);
    fill(0, 0, 0, a);
    rect(0, y, W, 1);
  }
  blendMode(BLEND);
}

// p5.js 1.11 — fixed image, 1600×2000
let W = 1600, H = 2000;

function setup() {
  createCanvas(W, H);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  colorMode(HSB, 360, 100, 100, 1);
  background(220, 35, 6);

  // Background gradient (deep dusk to soot)
  for (let y = 0; y < H; y++) {
    let t = y / (H - 1);
    let h = lerp(220, 28, pow(t, 1.2));
    let s = lerp(28, 18, t);
    let b = lerp(9, 5, t);
    stroke(h, s, b, 1);
    line(0, y, W, y);
  }

  // Subtle turbulent haze
  noStroke();
  for (let i = 0; i < 900; i++) {
    let x = random(W), y = random(H);
    let n = noise(x * 0.0016, y * 0.0016);
    let r = random(120, 420) * (0.3 + 0.9 * n);
    let a = 0.015 + 0.03 * n;
    fill(210 + 25 * n, 18 + 25 * n, 12 + 10 * n, a);
    ellipse(x, y, r, r * random(0.6, 1.2));
  }

  // Floor / lower mass (earthy darkness)
  push();
  let floorTop = H * 0.70;
  for (let y = floorTop; y < H; y++) {
    let t = (y - floorTop) / (H - floorTop);
    let h = lerp(25, 18, t);
    let s = lerp(28, 22, t);
    let b = lerp(7, 3.5, t);
    stroke(h, s, b, 1);
    line(0, y, W, y);
  }
  pop();

  // Cracks / veins on the floor
  stroke(30, 18, 16, 0.10);
  strokeWeight(2);
  for (let k = 0; k < 24; k++) {
    let x0 = random(W);
    let y0 = random(H * 0.78, H * 0.97);
    let x = x0, y = y0;
    beginShape();
    for (let j = 0; j < 14; j++) {
      let ang = -PI / 2 + (noise(k * 10, j * 0.6) - 0.5) * 1.6;
      let step = random(22, 55);
      x += cos(ang) * step;
      y += sin(ang) * step * random(0.7, 1.25);
      vertex(x, y);
      if (x < -100 || x > W + 100 || y < floorTop - 100 || y > H + 100) break;
    }
    endShape();
  }

  // Central "threshold" (arched doorway)
  let cx = W * 0.5;
  let cy = H * 0.52;
  let dw = W * 0.52;
  let dh = H * 0.62;
  let archTop = cy - dh * 0.40;
  let archBottom = cy + dh * 0.45;

  // Shadow around the threshold
  push();
  noStroke();
  for (let i = 0; i < 55; i++) {
    let t = i / 54;
    let padX = lerp(dw * 0.52, dw * 0.80, t);
    let padY = lerp(dh * 0.52, dh * 0.88, t);
    fill(225, 22, 5, 0.05 * (1 - t));
    drawArchedPanel(cx, cy, padX, padY, 0.50);
  }
  pop();

  // The luminous interior
  push();
  noStroke();
  for (let i = 0; i < 120; i++) {
    let t = i / 119;
    let iw = lerp(dw * 0.42, dw * 0.18, pow(t, 1.2));
    let ih = lerp(dh * 0.50, dh * 0.20, pow(t, 1.1));
    let h = lerp(42, 200, t);
    let s = lerp(12, 18, t);
    let b = lerp(22, 9, t);
    let a = 0.05;
    fill(h, s, b, a);
    drawArchedPanel(cx, cy, iw, ih, 0.55);
  }
  pop();

  // Interior glow core (cold bone-light)
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 18; i++) {
    let t = i / 17;
    let x = cx + randomGaussian() * (dw * 0.03);
    let y = cy - dh * 0.06 + randomGaussian() * (dh * 0.05);
    let r = lerp(dw * 0.22, dw * 0.08, t);
    fill(210, 12, 28, 0.06 * (1 - t));
    ellipse(x, y, r, r * 1.25);
  }
  blendMode(BLEND);
  pop();

  // A near-absence silhouette at the base, dissolving
  push();
  noStroke();
  let baseY = H * 0.76;
  for (let i = 0; i < 260; i++) {
    let t = i / 259;
    let y = lerp(baseY, H * 0.92, t);
    let w = lerp(W * 0.22, W * 0.46, t);
    let xJ = (noise(i * 0.05) - 0.5) * 40;
    fill(25, 22, 2.5 + 2.0 * (1 - t), 0.08);
    ellipse(cx + xJ, y, w, w * 0.33);
  }
  pop();

  // Dust rising inside the threshold (the "leaving")
  push();
  let left = cx - dw * 0.21;
  let right = cx + dw * 0.21;
  let top = cy - dh * 0.26;
  let bottom = cy + dh * 0.30;

  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 24000; i++) {
    let u = random();
    let v = random();
    let x = lerp(left, right, u);
    let y = lerp(bottom, top, pow(v, 1.25)); // denser near bottom
    let n = noise(x * 0.008, y * 0.008);
    let gate = smoothstep(0.12, 0.88, n);
    if (random() > gate) continue;

    let drift = (noise(100 + y * 0.004, 50) - 0.5) * 85;
    x += drift * (1 - (y - top) / (bottom - top));

    let a = 0.018 + 0.05 * pow((bottom - y) / (bottom - top), 1.4);
    let r = 1.2 + 3.8 * random() * (0.4 + 0.8 * n);
    let hh = lerp(40, 205, (bottom - y) / (bottom - top));
    fill(hh, 10 + 10 * n, 18 + 28 * random(), a);
    circle(x, y, r);
  }
  blendMode(BLEND);
  pop();

  // Wilting flowers on both sides (fragile life)
  drawWiltedFlower(W * 0.18, H * 0.78, -1);
  drawWiltedFlower(W * 0.82, H * 0.78, 1);

  // Brushy texture overlay (oil-like strokes)
  push();
  blendMode(MULTIPLY);
  for (let i = 0; i < 52000; i++) {
    let x = random(W), y = random(H);
    let n = noise(x * 0.0022, y * 0.0022);
    let ang = noise(x * 0.003, y * 0.003) * TWO_PI * 2.0;
    let len = 6 + 40 * pow(n, 1.6);
    let w = 0.6 + 2.6 * n;

    let h = lerp(215, 26, y / H) + (n - 0.5) * 22;
    let s = lerp(18, 26, y / H) + 10 * (n - 0.5);
    let b = lerp(14, 7, y / H) + 7 * (n - 0.5);
    let a = 0.028;

    stroke(h, constrain(s, 0, 60), constrain(b, 0, 30), a);
    strokeWeight(w);
    line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }
  blendMode(BLEND);
  pop();

  // Vignette
  vignette(0.78, 0.62);

  // Fine grain
  addGrain(0.06);
}

function drawArchedPanel(cx, cy, w, h, roundness) {
  // Arch made from a rounded rect + top ellipse
  let rx = w * roundness;
  let ry = rx;

  // Body
  let bodyTop = cy - h * 0.12;
  let bodyH = h * 0.62;
  rectMode(CENTER);
  rect(cx, cy + h * 0.15, w, bodyH, rx, rx, rx, rx);

  // Top arch
  ellipse(cx, cy - h * 0.18, w, h * 0.55);
}

function drawWiltedFlower(x0, y0, side) {
  push();
  noFill();

  // Stem
  let stemCol = color(35, 30, 14, 0.55);
  stroke(stemCol);
  strokeWeight(6);
  let x1 = x0 + side * 70;
  let y1 = y0 - 260;
  bezier(x0, y0, x0 + side * 40, y0 - 140, x1 - side * 30, y1 + 110, x1, y1);

  // Secondary thin twigs
  stroke(35, 25, 18, 0.35);
  strokeWeight(2.2);
  for (let k = 0; k < 5; k++) {
    let t = (k + 1) / 6;
    let px = bezierPoint(x0, x0 + side * 40, x1 - side * 30, x1, t);
    let py = bezierPoint(y0, y0 - 140, y1 + 110, y1, t);
    let a = -PI / 2 + side * 0.5 + (noise(k * 2.2) - 0.5) * 0.6;
    let L = 60 + 80 * (1 - t);
    line(px, py, px + cos(a) * L, py + sin(a) * L);
  }

  // Drooping petals (pale, bruised)
  push();
  translate(x1, y1);
  rotate(side * 0.1);
  let petalBase = color(35, 10, 26, 0.18);
  let petalEdge = color(210, 6, 26, 0.12);

  for (let i = 0; i < 9; i++) {
    let ang = -PI / 2 + (i - 4) * 0.18 + (noise(i * 0.3) - 0.5) * 0.12;
    let L = 160 + 70 * noise(i * 0.25);
    strokeWeight(5);
    stroke(petalEdge);
    let xA = cos(ang) * (L * 0.15), yA = sin(ang) * (L * 0.15);
    let xB = cos(ang) * (L * 0.55), yB = sin(ang) * (L * 0.55) + 40;
    let xC = cos(ang) * (L * 0.95), yC = sin(ang) * (L * 0.95) + 95;

    beginShape();
    for (let t = 0; t <= 1.0001; t += 0.06) {
      let xx = bezierPoint(0, xA, xB, xC, t);
      let yy = bezierPoint(0, yA, yB, yC, t);
      let wob = (noise(i * 10, t * 3) - 0.5) * 10;
      vertex(xx + wob, yy);
    }
    endShape();

    // Petal fill suggestion
    stroke(petalBase);
    strokeWeight(10);
    line(xA * 0.7, yA * 0.7, xC * 0.9, yC * 0.9);
  }

  // Small dark core
  noStroke();
  fill(30, 22, 6, 0.55);
  ellipse(0, 18, 46, 32);
  pop();

  pop();
}

function vignette(strength, softness) {
  push();
  noStroke();
  blendMode(MULTIPLY);
  let cx = W * 0.5, cy = H * 0.52;
  let maxR = dist(0, 0, W, H) * 0.62;
  for (let i = 0; i < 120; i++) {
    let t = i / 119;
    let r = lerp(maxR * softness, maxR * 1.25, t);
    let a = strength * 0.018 * pow(t, 1.35);
    fill(220, 30, 5, a);
    ellipse(cx, cy, r * 2.05, r * 2.45);
  }
  blendMode(BLEND);
  pop();
}

function addGrain(amount) {
  loadPixels();
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      let idx = 4 * (y * W + x);
      let g = (random() - 0.5) * 255 * amount;
      pixels[idx + 0] = constrain(pixels[idx + 0] + g, 0, 255);
      pixels[idx + 1] = constrain(pixels[idx + 1] + g, 0, 255);
      pixels[idx + 2] = constrain(pixels[idx + 2] + g, 0, 255);
    }
  }
  updatePixels();
}

function smoothstep(a, b, x) {
  let t = constrain((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
}

// p5.js 1.11 — fixed image 1600×2000
let W = 1600, H = 2000;

function setup() {
  createCanvas(W, H);
  pixelDensity(2);
  randomSeed(1);
  noiseSeed(1);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();
}

function draw() {
  background(230, 40, 6, 100);

  gradientBackground();
  distantMist();
  addGrain(140000);

  drawDoorway();
  drawFloorDissolve();

  drawWiltedBouquet(width * 0.40, height * 0.78, 1.0);
  drawWiltedBouquet(width * 0.58, height * 0.80, 0.85);

  drawMoth(width * 0.52, height * 0.34, 0.95);
  drawAsh(2600);

  vignette();
}

function gradientBackground() {
  let topC = color(232, 45, 10, 100);
  let midC = color(250, 38, 8, 100);
  let botC = color(215, 55, 5, 100);

  noStroke();
  for (let y = 0; y < height; y++) {
    let t = y / (height - 1);
    let c;
    if (t < 0.55) c = lerpColor(topC, midC, t / 0.55);
    else c = lerpColor(midC, botC, (t - 0.55) / 0.45);
    fill(hue(c), saturation(c), brightness(c), 100);
    rect(0, y, width, 1);
  }

  // cold, faint vertical aura near center
  push();
  blendMode(SCREEN);
  for (let i = 0; i < 80; i++) {
    let x = width * 0.5 + randomGaussian(0, width * 0.06);
    let w = random(width * 0.01, width * 0.06);
    let a = random(1.2, 3.2);
    fill(200 + random(-10, 10), 30, 18, a);
    rect(x - w * 0.5, 0, w, height);
  }
  pop();
}

function distantMist() {
  noStroke();
  push();
  blendMode(ADD);
  for (let k = 0; k < 260; k++) {
    let y = random(height * 0.05, height * 0.85);
    let x = random(width);
    let w = random(width * 0.10, width * 0.55);
    let h = random(height * 0.01, height * 0.05);
    let n = noise(x * 0.0012, y * 0.0015);
    let a = map(n, 0, 1, 0.5, 3.0);
    fill(210, 18, 22, a);
    ellipse(x, y, w, h);
  }
  pop();
}

function addGrain(n) {
  loadPixels();
  for (let i = 0; i < n; i++) {
    let x = floor(random(width));
    let y = floor(random(height));
    let idx = 4 * (y * width + x);

    let g = random(-18, 18);
    pixels[idx + 0] = constrain(pixels[idx + 0] + g, 0, 255);
    pixels[idx + 1] = constrain(pixels[idx + 1] + g, 0, 255);
    pixels[idx + 2] = constrain(pixels[idx + 2] + g, 0, 255);
    // alpha untouched
  }
  updatePixels();

  // sparse dust flecks
  push();
  noStroke();
  for (let i = 0; i < 3000; i++) {
    let x = random(width);
    let y = random(height);
    let a = random(0.5, 2.5);
    fill(40, 5, 92, a);
    rect(x, y, 1, 1);
  }
  pop();
}

function vignette() {
  push();
  noStroke();
  blendMode(MULTIPLY);
  for (let i = 0; i < 40; i++) {
    let t = i / 39;
    let a = lerp(0, 22, t);
    fill(240, 40, 2, a);
    rect(t * -40, t * -60, width + t * 80, height + t * 120);
  }
  pop();

  // corners deepen
  push();
  blendMode(MULTIPLY);
  noStroke();
  for (let i = 0; i < 24; i++) {
    let a = 4;
    fill(230, 30, 3, a);
    ellipse(0, 0, width * (0.55 + i * 0.06), height * (0.55 + i * 0.06));
    ellipse(width, 0, width * (0.55 + i * 0.06), height * (0.55 + i * 0.06));
    ellipse(0, height, width * (0.55 + i * 0.06), height * (0.55 + i * 0.06));
    ellipse(width, height, width * (0.55 + i * 0.06), height * (0.55 + i * 0.06));
  }
  pop();
}

function drawDoorway() {
  let cx = width * 0.52;
  let cy = height * 0.38;
  let dw = width * 0.44;
  let dh = height * 0.56;
  let r = min(dw, dh) * 0.18;

  // halo edge
  push();
  noFill();
  strokeCap(ROUND);
  for (let i = 0; i < 18; i++) {
    let a = map(i, 0, 17, 18, 1);
    stroke(200, 18, 55, a);
    strokeWeight(map(i, 0, 17, 22, 2));
    roundedRect(cx - dw * 0.5, cy - dh * 0.5, dw, dh, r);
  }
  pop();

  // inner void
  push();
  noStroke();
  for (let i = 0; i < 80; i++) {
    let t = i / 79;
    let w = lerp(dw * 0.88, dw * 0.68, t);
    let h = lerp(dh * 0.90, dh * 0.74, t);
    let a = lerp(92, 100, t);
    fill(230, 35, lerp(7, 2, t), a);
    roundedRect(cx - w * 0.5, cy - h * 0.5, w, h, r * 0.85);
  }
  pop();

  // subtle vertical “breath” inside
  push();
  blendMode(SCREEN);
  noStroke();
  for (let i = 0; i < 220; i++) {
    let x = cx + randomGaussian(0, dw * 0.12);
    let y = cy + randomGaussian(0, dh * 0.18);
    let nn = noise(x * 0.004, y * 0.004);
    let a = map(nn, 0, 1, 0.2, 2.2);
    fill(195, 12, 65, a);
    ellipse(x, y, random(dw * 0.02, dw * 0.11), random(dh * 0.01, dh * 0.06));
  }
  pop();
}

function drawFloorDissolve() {
  let cx = width * 0.52;
  let y0 = height * 0.64;
  let y1 = height * 0.98;

  // floor plane (cold stone)
  push();
  noStroke();
  for (let i = 0; i < 120; i++) {
    let t = i / 119;
    let y = lerp(y0, y1, t);
    let w = lerp(width * 0.18, width * 1.18, t);
    let a = lerp(30, 75, t);
    fill(215, 18, lerp(14, 6, t), a);
    rect(cx - w * 0.5, y, w, (y1 - y0) / 120 + 2);
  }
  pop();

  // cracks + dissolving edges
  push();
  stroke(210, 18, 10, 45);
  strokeWeight(2);
  noFill();

  for (let k = 0; k < 55; k++) {
    let startX = cx + randomGaussian(0, width * 0.10);
    let startY = random(y0 + height * 0.02, y1 - height * 0.02);
    beginShape();
    let steps = floor(random(18, 48));
    let x = startX, y = startY;
    for (let i = 0; i < steps; i++) {
      let tt = (y - y0) / (y1 - y0);
      let spread = lerp(width * 0.006, width * 0.03, tt);
      x += randomGaussian(0, spread);
      y += random(height * 0.002, height * 0.012);
      vertex(x, y);
      if (random() < 0.05) break;
    }
    endShape();
  }
  pop();

  // dust where the floor “breaks”
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 4200; i++) {
    let y = random(y0, y1);
    let t = (y - y0) / (y1 - y0);
    let w = lerp(width * 0.20, width * 1.25, t);
    let x = cx + randomGaussian(0, w * 0.33);
    let edge = abs(x - cx) / (w * 0.5);
    let dissolve = pow(constrain(edge, 0, 1), 1.6);

    if (random() < dissolve * 0.65) {
      let a = lerp(0.2, 5.5, dissolve);
      fill(45, 6, 95, a);
      rect(x, y, 1.2, 1.2);
    }
  }
  pop();
}

function drawWiltedBouquet(bx, by, s) {
  push();
  translate(bx, by);
  scale(s);

  // shadow mass
  push();
  blendMode(MULTIPLY);
  noStroke();
  fill(235, 30, 3, 42);
  ellipse(0, 40, 520, 220);
  pop();

  // stems
  stroke(105, 38, 26, 85);
  strokeWeight(5);
  strokeCap(ROUND);
  for (let i = 0; i < 9; i++) {
    let x0 = random(-70, 70);
    let y0 = random(70, 120);
    let x1 = x0 + random(-60, 60);
    let y1 = y0 - random(240, 360);
    let x2 = x1 + random(-120, 120);
    let y2 = y1 - random(120, 240);

    noFill();
    bezier(x0, y0, x0 + random(-40, 40), y0 - random(80, 140),
           x1 + random(-80, 80), y1 - random(80, 140),
           x2, y2);

    // small thorns / fractures
    strokeWeight(2);
    for (let k = 0; k < 7; k++) {
      let t = random(0.1, 0.95);
      let px = bezierPoint(x0, x0 + random(-40, 40), x1 + random(-80, 80), x2, t);
      let py = bezierPoint(y0, y0 - random(80, 140), y1 - random(80, 140), y2, t);
      let ang = random(-PI * 0.9, PI * 0.9);
      let len = random(8, 18);
      stroke(95, 35, 18, 55);
      line(px, py, px + cos(ang) * len, py + sin(ang) * len);
    }
    stroke(105, 38, 26, 85);
    strokeWeight(5);

    // blooms (wilted)
    drawWiltedBloom(x2, y2, random(0.75, 1.2));
  }

  // wrapping cloth (a hint of shroud)
  push();
  noStroke();
  fill(18, 12, 92, 10);
  beginShape();
  vertex(-220, 130);
  bezierVertex(-140, 40, -120, -20, -40, -20);
  bezierVertex(60, -20, 90, 60, 180, 90);
  bezierVertex(140, 160, 40, 170, -220, 130);
  endShape(CLOSE);

  fill(215, 10, 70, 8);
  beginShape();
  vertex(-200, 120);
  bezierVertex(-110, 55, -85, 20, -30, 20);
  bezierVertex(70, 18, 100, 80, 165, 98);
  bezierVertex(110, 140, 20, 150, -200, 120);
  endShape(CLOSE);
  pop();

  pop();
}

function drawWiltedBloom(x, y, sc) {
  push();
  translate(x, y);
  scale(sc);

  let baseHue = random([8, 18, 32, 350]); // bruised reds/oranges
  let sat = random(35, 65);
  let bri = random(22, 45);

  // center
  noStroke();
  fill(38, 35, 18, 85);
  ellipse(0, 0, 26, 22);

  // drooping petals
  for (let p = 0; p < 8; p++) {
    let ang = (TWO_PI * p) / 8 + random(-0.12, 0.12);
    let len = random(70, 120);
    let wid = random(22, 36);

    let droop = random(0.35, 0.9);
    let tipX = cos(ang) * len * 0.55;
    let tipY = sin(ang) * len * 0.55 + len * droop;

    push();
    rotate(ang);

    // petal body
    beginShape();
    fill(baseHue + random(-10, 10), sat, bri, 62);
    vertex(0, 0);
    bezierVertex(wid, len * 0.12, wid * 0.85, len * 0.35 + len * droop * 0.25, 0, len * 0.55 + len * droop);
    bezierVertex(-wid * 0.85, len * 0.35 + len * droop * 0.25, -wid, len * 0.12, 0, 0);
    endShape(CLOSE);

    // bruises
    blendMode(MULTIPLY);
    for (let b = 0; b < 6; b++) {
      let bx = random(-wid * 0.35, wid * 0.35);
      let by = random(len * 0.10, len * 0.55 + len * droop * 0.85);
      let ba = random(8, 20);
      fill(260, 35, 18, ba);
      ellipse(bx, by, random(10, 22), random(14, 30));
    }
    blendMode(BLEND);

    // torn edge
    noFill();
    stroke(30, 10, 92, 18);
    strokeWeight(1.4);
    beginShape();
    for (let i = 0; i <= 22; i++) {
      let t = i / 22;
      let xx = sin(t * PI) * wid * (0.9 + random(-0.12, 0.12));
      let yy = (len * 0.55 + len * droop) * t + random(-2, 2);
      vertex(xx, yy);
    }
    endShape();

    pop();
  }

  // falling fragments around bloom
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 90; i++) {
    let rx = randomGaussian(0, 55);
    let ry = randomGaussian(40, 70);
    let a = random(0.6, 4.0);
    fill(35, 10, 96, a);
    rect(rx, ry, random(1, 3), random(1, 3));
  }
  pop();

  pop();
}

function drawMoth(mx, my, sc) {
  push();
  translate(mx, my);
  scale(sc);

  // glow
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 30; i++) {
    let a = map(i, 0, 29, 10, 0.2);
    fill(200, 12, 65, a);
    ellipse(0, 0, 160 + i * 26, 120 + i * 20);
  }
  pop();

  // body
  noStroke();
  fill(35, 10, 12, 85);
  ellipse(0, 10, 22, 66);
  fill(35, 10, 18, 85);
  ellipse(0, -22, 18, 24);

  // wings (soft, powdery)
  drawWing(-1);
  drawWing(1);

  // antennae
  stroke(35, 12, 14, 70);
  strokeWeight(2);
  noFill();
  bezier(0, -30, -10, -70, -40, -75, -55, -60);
  bezier(0, -30, 10, -70, 40, -75, 55, -60);

  pop();
}

function drawWing(side) {
  push();
  scale(side, 1);

  let wingC1 = color(210, 10, 32, 65);
  let wingC2 = color(35, 10, 92, 22);

  noStroke();
  beginShape();
  fill(wingC1);
  vertex(0, 0);
  bezierVertex(140, -70, 230, 40, 170, 140);
  bezierVertex(120, 220, 20, 210, -10, 120);
  bezierVertex(-40, 50, -15, 20, 0, 0);
  endShape(CLOSE);

  // powder texture
  push();
  blendMode(SCREEN);
  for (let i = 0; i < 1600; i++) {
    let x = random(-10, 210);
    let y = random(-70, 230);
    let inside = pointInWing(x, y);
    if (!inside) continue;
    let n = noise((x + 900) * 0.01, (y + 900) * 0.01);
    let a = map(n, 0, 1, 0.3, 4.0);
    let c = lerpColor(wingC2, color(200, 8, 85, 40), n);
    fill(hue(c), saturation(c), brightness(c), a);
    rect(x, y, 1.2, 1.2);
  }
  pop();

  // veins
  stroke(215, 8, 18, 26);
  strokeWeight(1.5);
  noFill();
  for (let k = 0; k < 8; k++) {
    let a = map(k, 0, 7, -0.6, 1.0);
    beginShape();
    for (let i = 0; i < 18; i++) {
      let t = i / 17;
      let x = lerp(5, 185, t);
      let y = lerp(0, 165, t) + sin(t * 3.6 + a) * (12 + k) - t * 18;
      vertex(x, y);
    }
    endShape();
  }

  pop();
}

function pointInWing(x, y) {
  // rough inclusion to avoid expensive polygon checks:
  // a soft ellipse + wedge condition that approximates the wing silhouette.
  let e = sq((x - 110) / 140) + sq((y - 70) / 160);
  if (e > 1.15) return false;
  if (x < -25 || y < -95 || y > 260) return false;
  if (y < -10 && x > 150) return false;
  return true;
}

function drawAsh(n) {
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < n; i++) {
    let x = random(width);
    let y = random(height);
    let nn = noise(x * 0.0022, y * 0.0022);
    let a = map(nn, 0, 1, 0.1, 4.2);
    let sz = map(nn, 0, 1, 0.6, 2.6);
    let warm = noise((x + 333) * 0.003, (y + 777) * 0.003);
    let h = lerp(35, 215, warm);
    fill(h, 8, 98, a);
    rect(x, y, sz, sz);
  }
  pop();

  // a few drifting threads
  push();
  stroke(40, 6, 92, 10);
  strokeWeight(1);
  noFill();
  for (let k = 0; k < 140; k++) {
    let x = random(width);
    let y = random(height);
    let len = random(40, 120);
    beginShape();
    for (let i = 0; i < 12; i++) {
      let t = i / 11;
      let xx = x + sin(t * 6 + noise(x * 0.003, y * 0.003) * 4) * 10 + t * len;
      let yy = y + cos(t * 5 + noise(x * 0.004, y * 0.004) * 3) * 8 + t * len * 0.25;
      vertex(xx, yy);
    }
    endShape();
  }
  pop();
}

function roundedRect(x, y, w, h, r) {
  r = min(r, w * 0.5, h * 0.5);
  beginShape();
  vertex(x + r, y);
  vertex(x + w - r, y);
  quadraticVertex(x + w, y, x + w, y + r);
  vertex(x + w, y + h - r);
  quadraticVertex(x + w, y + h, x + w - r, y + h);
  vertex(x + r, y + h);
  quadraticVertex(x, y + h, x, y + h - r);
  vertex(x, y + r);
  quadraticVertex(x, y, x + r, y);
  endShape(CLOSE);
}

// p5.js 1.11 — image fixe 1600×2000
let W = 1600, H = 2000;

function setup() {
  createCanvas(W, H);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  background(8, 10, 14);

  gradientBackdrop();
  texturedWash();
  distantGlow();
  riverPath();
  portalForm();
  emberThreads();
  mothsAndAsh();
  foregroundVeil();
  vignette();
  addGrain(26);
}

function gradientBackdrop() {
  noStroke();
  for (let y = 0; y < H; y++) {
    let t = y / (H - 1);
    let r = lerp(6, 18, pow(t, 0.8));
    let g = lerp(8, 22, pow(t, 0.9));
    let b = lerp(14, 28, pow(t, 1.05));
    fill(r, g, b);
    rect(0, y, W, 1);
  }

  // brume froide
  for (let i = 0; i < 10; i++) {
    let cy = lerp(H * 0.18, H * 0.62, i / 9);
    let a = 16 - i;
    fill(190, 205, 220, a);
    rect(0, cy, W, H * 0.06);
  }
}

function texturedWash() {
  // lavis granuleux
  noStroke();
  for (let k = 0; k < 14000; k++) {
    let x = random(W);
    let y = random(H);
    let n = noise(x * 0.0018, y * 0.0018);
    let a = 10 + 22 * n;
    let cold = color(40, 52, 66, a);
    let warm = color(60, 48, 36, a * 0.75);
    let c = lerpColor(cold, warm, pow(noise(x * 0.0024, y * 0.0022 + 5), 2));
    fill(c);
    circle(x, y, random(1, 4.2));
  }

  // traînées de brosse longues, très transparentes
  strokeWeight(1);
  for (let s = 0; s < 2500; s++) {
    let x0 = random(W);
    let y0 = random(H);
    let ang = map(noise(x0 * 0.001, y0 * 0.001), 0, 1, -PI * 0.4, PI * 0.4);
    let len = random(30, 180);
    let x1 = x0 + cos(ang) * len;
    let y1 = y0 + sin(ang) * len;
    let a = random(8, 22);
    stroke(120, 130, 145, a);
    line(x0, y0, x1, y1);
  }
}

function distantGlow() {
  // lune presque effacée / halo haut
  let cx = W * 0.63;
  let cy = H * 0.18;
  noStroke();

  for (let i = 0; i < 220; i++) {
    let t = i / 219;
    let r = lerp(16, 520, t);
    let a = lerp(38, 0, pow(t, 1.3));
    fill(210, 220, 235, a);
    circle(cx, cy, r);
  }

  // éclipse partielle sombre
  fill(12, 14, 18, 240);
  circle(cx + 40, cy + 20, 210);

  // couronne froide
  for (let i = 0; i < 140; i++) {
    let t = i / 139;
    let r = lerp(170, 360, t);
    let a = lerp(40, 0, t);
    fill(170, 195, 220, a);
    circle(cx, cy, r);
  }
}

function riverPath() {
  // chemin/ruisseau clair vers le centre: le vivant conduit au seuil
  noFill();
  for (let i = 0; i < 140; i++) {
    let t = i / 139;
    let y = lerp(H * 1.02, H * 0.55, t);
    let x = W * 0.52 + sin(t * 3.2 + 0.8) * (160 - 120 * t);
    let w = lerp(520, 70, pow(t, 1.15));

    let a = lerp(28, 10, t);
    stroke(160, 175, 190, a);
    strokeWeight(max(1, w * 0.008));
    beginShape();
    for (let j = 0; j < 8; j++) {
      let tt = j / 7;
      let xx = x + (tt - 0.5) * w;
      let yy = y + (noise(tt * 2.5, t * 3.0) - 0.5) * 18;
      curveVertex(xx, yy);
    }
    endShape();
  }

  // reflets chauds discrets
  strokeWeight(1);
  for (let k = 0; k < 1800; k++) {
    let t = random();
    let y = lerp(H * 0.95, H * 0.58, t);
    let x = W * 0.52 + sin(t * 3.2 + 0.8) * (160 - 120 * t) + randomGaussian() * 90 * (1 - t);
    let a = 10 + 18 * (1 - t);
    stroke(210, 170, 110, a);
    line(x, y, x + random(-18, 18), y + random(-2, 2));
  }
}

function portalForm() {
  // forme centrale: porte/absence
  let cx = W * 0.52;
  let cy = H * 0.62;
  let w = W * 0.34;
  let h = H * 0.54;

  // halo de bord
  noStroke();
  for (let i = 0; i < 130; i++) {
    let t = i / 129;
    let a = lerp(38, 0, pow(t, 1.1));
    let grow = lerp(0, 80, t);
    fill(175, 150, 115, a);
    blob(cx, cy, w + grow, h + grow, 0.035 + t * 0.015, 10);
  }

  // intérieur noir profond
  fill(5, 6, 8, 250);
  blob(cx, cy, w * 0.98, h * 0.98, 0.05, 12);

  // velours: couches noires nuancées
  for (let i = 0; i < 90; i++) {
    let t = i / 89;
    let a = lerp(16, 0, t);
    fill(10, 12, 16, a);
    blob(cx + (noise(i * 0.2) - 0.5) * 10, cy + (noise(i * 0.2 + 7) - 0.5) * 10,
         w * (0.96 - t * 0.12), h * (0.96 - t * 0.12), 0.06, 10);
  }

  // fêlures lumineuses au bord (sans signes lisibles)
  strokeWeight(2);
  for (let k = 0; k < 55; k++) {
    let side = random() < 0.5 ? -1 : 1;
    let px = cx + side * (w * 0.44 + random(-12, 12));
    let py = cy + random(-h * 0.45, h * 0.45);
    let ang = side > 0 ? PI : 0;
    let len = random(80, 260);
    for (let s = 0; s < 7; s++) {
      let tt = s / 6;
      let x = px + cos(ang + (noise(k, s * 0.2) - 0.5) * 0.7) * len * tt;
      let y = py + sin((noise(k + 3, s * 0.2) - 0.5) * 0.9) * len * tt;
      stroke(220, 185, 120, 42 * (1 - tt));
      point(x, y);
    }
  }
}

function emberThreads() {
  // fils chauds: mémoire / chaleur résiduelle autour du seuil
  strokeWeight(1);
  for (let i = 0; i < 2400; i++) {
    let x = random(W);
    let y = random(H);
    let d = dist(x, y, W * 0.52, H * 0.62);
    if (d > W * 0.45) continue;
    if (d < W * 0.10 && random() < 0.75) continue;

    let n = noise(x * 0.002, y * 0.002);
    let a = 10 + 35 * pow(1 - d / (W * 0.45), 1.7) * n;
    stroke(210, 165, 95, a);

    let ang = map(noise(x * 0.0012 + 9, y * 0.0012), 0, 1, -PI, PI);
    let len = random(12, 80) * (0.4 + n);
    line(x, y, x + cos(ang) * len, y + sin(ang) * len * 0.6);
  }
}

function mothsAndAsh() {
  // papillons pâles / cendres: vie fragile autour du noir
  noStroke();
  for (let i = 0; i < 210; i++) {
    let x = random(W);
    let y = random(H * 0.06, H * 0.92);
    let d = dist(x, y, W * 0.52, H * 0.62);
    let p = pow(constrain(1 - d / (W * 0.7), 0, 1), 1.5);
    if (random() > p) continue;

    if (random() < 0.55) {
      // cendre
      let a = 18 + 40 * p;
      fill(200, 205, 210, a);
      circle(x, y, random(1.2, 4.8));
    } else {
      // "moth" abstrait: deux ailes floues
      let s = random(10, 34) * (0.4 + 1.2 * p);
      let rot = random(-0.8, 0.8);
      push();
      translate(x, y);
      rotate(rot);
      for (let k = 0; k < 24; k++) {
        let tt = k / 23;
        let a = lerp(55, 0, pow(tt, 1.4)) * (0.4 + p);
        fill(220, 224, 230, a);
        ellipse(-s * 0.22, 0, s * (0.8 - tt * 0.45), s * (0.52 - tt * 0.25));
        ellipse( s * 0.22, 0, s * (0.8 - tt * 0.45), s * (0.52 - tt * 0.25));
      }
      // corps
      fill(35, 36, 40, 90);
      ellipse(0, 0, s * 0.12, s * 0.55);
      pop();
    }
  }
}

function foregroundVeil() {
  // rideau sombre bas: proximité, poids, finitude
  noStroke();
  for (let y = int(H * 0.68); y < H; y++) {
    let t = (y - H * 0.68) / (H * 0.32);
    let a = 35 + 170 * pow(t, 1.2);
    fill(6, 7, 9, a);
    rect(0, y, W, 1);
  }

  // silhouettes végétales sèches (abstraites)
  stroke(12, 12, 14, 170);
  strokeWeight(2);
  for (let i = 0; i < 140; i++) {
    let x = random(W);
    let y0 = random(H * 0.78, H);
    let h = random(60, 260);
    let bend = random(-0.8, 0.8);
    let steps = 22;
    let px = x, py = y0;
    for (let s = 1; s <= steps; s++) {
      let tt = s / steps;
      let nx = x + bend * 60 * pow(tt, 1.4) + (noise(x * 0.01, y0 * 0.01 + tt * 2) - 0.5) * 14;
      let ny = y0 - h * tt;
      line(px, py, nx, ny);
      px = nx; py = ny;

      if (random() < 0.18 && tt > 0.25 && tt < 0.9) {
        let bx = nx + random(-50, 50);
        let by = ny - random(10, 55);
        stroke(12, 12, 14, 120);
        line(nx, ny, bx, by);
        stroke(12, 12, 14, 170);
      }
    }
  }
}

function vignette() {
  noStroke();
  for (let i = 0; i < 220; i++) {
    let t = i / 219;
    let a = lerp(0, 210, pow(t, 1.7));
    fill(0, 0, 0, a * 0.25);
    rect(0, 0, W, H);
    // masque radial approximé par grands ellipses sombres
    fill(0, 0, 0, a * 0.38);
    ellipse(W * 0.5, H * 0.55, W * (1.35 + t * 0.55), H * (1.65 + t * 0.75));
  }
}

function addGrain(amount) {
  loadPixels();
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      let idx = 4 * (y * W + x);
      let g = (noise(x * 0.02, y * 0.02) - 0.5) * amount;
      pixels[idx + 0] = constrain(pixels[idx + 0] + g, 0, 255);
      pixels[idx + 1] = constrain(pixels[idx + 1] + g, 0, 255);
      pixels[idx + 2] = constrain(pixels[idx + 2] + g, 0, 255);
    }
  }
  updatePixels();
}

function blob(cx, cy, w, h, freq, oct) {
  beginShape();
  let steps = 220;
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * TWO_PI;
    let ux = cos(a);
    let uy = sin(a);
    let n = 0;
    let amp = 1;
    let sumAmp = 0;

    let sx = (cx + ux * w * 0.5) * freq;
    let sy = (cy + uy * h * 0.5) * freq;

    for (let o = 0; o < oct; o++) {
      n += amp * (noise(sx, sy) - 0.5);
      sumAmp += amp;
      amp *= 0.55;
      sx *= 2.0;
      sy *= 2.0;
    }
    n /= max(0.0001, sumAmp);

    let rr = 1.0 + n * 0.85;
    let x = cx + ux * (w * 0.5) * rr;
    let y = cy + uy * (h * 0.5) * rr;
    curveVertex(x, y);
  }
  endShape(CLOSE);
}

// p5.js 1.11 — 1600×2000 — image fixe, aucune ressource externe
let W = 1600, H = 2000;

function setup() {
  createCanvas(W, H);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  background(6, 7, 10);

  // --- Palette
  const cDeep = color(8, 10, 18);
  const cInk = color(14, 16, 28);
  const cBlue = color(18, 25, 45);
  const cAsh = color(80, 86, 100);
  const cBone = color(206, 201, 186);
  const cRust = color(120, 62, 52);
  const cMoss = color(55, 75, 70);

  // --- Base gradient (ciel/mer)
  let horizonY = int(H * 0.56);
  for (let y = 0; y < H; y++) {
    let t = y / (H - 1);
    let g1 = lerpColor(cDeep, cBlue, constrain(map(t, 0.0, 0.55, 0, 1), 0, 1));
    let g2 = lerpColor(cInk, cDeep, constrain(map(t, 0.55, 1.0, 0, 1), 0, 1));
    let col = (y < horizonY) ? g1 : g2;
    stroke(red(col), green(col), blue(col), 255);
    line(0, y, W, y);
  }

  // --- Brume au niveau de l'horizon
  noStroke();
  for (let i = 0; i < 1400; i++) {
    let x = random(W);
    let y = random(horizonY - 120, horizonY + 140);
    let r = random(20, 130);
    let a = random(6, 18);
    fill(170, 175, 190, a);
    ellipse(x, y, r * 1.3, r);
  }

  // --- Texture du ciel (nuées)
  push();
  blendMode(SOFT_LIGHT);
  for (let i = 0; i < 2400; i++) {
    let x = random(-120, W + 120);
    let y = random(-80, horizonY + 60);
    let n = noise(x * 0.0012, y * 0.0012);
    let r = random(40, 200) * (0.4 + 0.9 * n);
    let a = 10 + 35 * n;
    fill(30 + 40 * n, 34 + 55 * n, 60 + 70 * n, a);
    ellipse(x, y, r * 1.4, r);
  }
  pop();

  // --- Mer : vaguelettes par traits
  push();
  strokeCap(ROUND);
  for (let i = 0; i < 7000; i++) {
    let y = random(horizonY + 10, H - 40);
    let x = random(-50, W + 50);
    let t = map(y, horizonY, H, 0, 1);
    let len = random(10, 90) * (0.25 + 0.9 * (1 - t));
    let amp = (1 - t) * 10 + 2;
    let n = noise(x * 0.003, y * 0.002);
    let a = 10 + 55 * (1 - t) * n;
    let col = lerpColor(color(16, 18, 30), color(8, 9, 14), t);
    stroke(red(col) + 20 * n, green(col) + 20 * n, blue(col) + 35 * n, a);
    strokeWeight(0.6 + 1.2 * (1 - t));
    let x2 = x + len;
    let y2 = y + sin(x * 0.02 + n * 7) * amp;
    line(x, y, x2, y2);
  }
  pop();

  // --- Reflet sombre vertical (couloir d'absence)
  push();
  blendMode(MULTIPLY);
  noStroke();
  for (let i = 0; i < 900; i++) {
    let x = random(W * 0.35, W * 0.65);
    let y = random(horizonY, H);
    let t = map(y, horizonY, H, 0, 1);
    let w = random(80, 320) * (0.6 + 0.8 * (1 - t));
    let h = random(60, 260);
    let a = 6 + 26 * (1 - t);
    fill(5, 6, 10, a);
    ellipse(x, y, w, h);
  }
  pop();

  // --- Barque (forme simple, presque engloutie)
  drawBoat(W * 0.52, H * 0.70, W * 0.62, H * 0.78, cRust);

  // --- Silhouette (la mort comme présence : manteau, vide, crâne suggéré)
  drawCloakedFigure(W * 0.52, H * 0.60, 520);

  // --- Filins / roseaux noirs (fragiles, comme des aiguilles)
  push();
  stroke(10, 10, 14, 130);
  strokeWeight(2);
  for (let i = 0; i < 48; i++) {
    let x0 = random(W * 0.07, W * 0.93);
    let y0 = random(H * 0.78, H * 0.98);
    let h = random(120, 420);
    let sway = random(-80, 80);
    let x1 = x0 + sway * 0.15;
    let y1 = y0 - h * 0.45;
    let x2 = x0 + sway;
    let y2 = y0 - h;
    bezier(x0, y0, x1, y1, x1, y1, x2, y2);
  }
  pop();

  // --- Papillons/mîtes pâles autour du manteau (fragiles, poussière vivante)
  drawMoths(W * 0.52, H * 0.58, 520);

  // --- Cendre / poussière générale
  push();
  noStroke();
  for (let i = 0; i < 14000; i++) {
    let x = random(W);
    let y = random(H);
    let t = map(y, 0, H, 0, 1);
    let a = (y < horizonY) ? (3 + 10 * (1 - t)) : (6 + 16 * (1 - t));
    let s = random(0.6, 1.8);
    let tone = 160 + 60 * noise(x * 0.006, y * 0.006);
    fill(tone, tone, tone + 5, a);
    rect(x, y, s, s);
  }
  pop();

  // --- Vignette (resserre, comme une paupière)
  vignette(0.78);

  // --- Petites fissures lumineuses (faibles, comme des souvenirs)
  push();
  blendMode(SCREEN);
  stroke(140, 160, 190, 22);
  strokeWeight(1);
  for (let i = 0; i < 140; i++) {
    let x = random(W);
    let y = random(horizonY - 160, H - 120);
    let n = noise(x * 0.002, y * 0.002);
    if (n < 0.56) continue;
    let len = random(40, 180);
    let a = random(TWO_PI);
    let x2 = x + cos(a) * len;
    let y2 = y + sin(a) * len * 0.35;
    line(x, y, x2, y2);
  }
  pop();
}

function drawBoat(x1, y1, x2, y2, cRust) {
  push();
  let cx = (x1 + x2) / 2;
  let cy = (y1 + y2) / 2;

  // Ombre sous la coque
  noStroke();
  fill(0, 0, 0, 55);
  ellipse(cx, cy + 60, (x2 - x1) * 1.08, 140);

  // Coque (base)
  beginShape();
  fill(25, 18, 20, 210);
  stroke(40, 28, 30, 120);
  strokeWeight(2);
  vertex(x1, y1);
  bezierVertex(x1 + 140, y1 + 110, x2 - 140, y2 + 110, x2, y2);
  bezierVertex(x2 - 70, y2 + 70, x1 + 70, y1 + 70, x1, y1);
  endShape(CLOSE);

  // Liseré rouille
  stroke(red(cRust), green(cRust), blue(cRust), 90);
  strokeWeight(1.6);
  noFill();
  beginShape();
  for (let i = 0; i <= 26; i++) {
    let t = i / 26;
    let x = lerp(x1, x2, t);
    let y = lerp(y1, y2, t) + 28 + 10 * sin(t * PI);
    y += (noise(t * 3.1, 9.2) - 0.5) * 10;
    vertex(x, y);
  }
  endShape();

  // Planches intérieures (traits)
  stroke(70, 55, 55, 90);
  strokeWeight(1);
  for (let i = 0; i < 22; i++) {
    let t = (i + 0.5) / 22;
    let xL = lerp(x1 + 30, x2 - 30, t);
    let yTop = lerp(y1 + 25, y2 + 25, t);
    let yBot = yTop + 60 + 25 * sin(t * PI);
    yTop += (noise(t * 4.7, 2.2) - 0.5) * 10;
    yBot += (noise(t * 4.7, 5.2) - 0.5) * 12;
    line(xL, yTop, xL, yBot);
  }
  pop();
}

function drawCloakedFigure(cx, cy, size) {
  push();

  // Manteau : grande masse sombre, texturée
  let topY = cy - size * 0.55;
  let botY = cy + size * 0.62;

  // Sous-couche
  noStroke();
  fill(6, 7, 10, 230);
  beginShape();
  vertex(cx - size * 0.32, cy - size * 0.38);
  bezierVertex(cx - size * 0.52, cy - size * 0.08, cx - size * 0.55, cy + size * 0.28, cx - size * 0.22, cy + size * 0.62);
  bezierVertex(cx - size * 0.02, cy + size * 0.72, cx + size * 0.02, cy + size * 0.72, cx + size * 0.22, cy + size * 0.62);
  bezierVertex(cx + size * 0.55, cy + size * 0.28, cx + size * 0.52, cy - size * 0.08, cx + size * 0.32, cy - size * 0.38);
  bezierVertex(cx + size * 0.18, cy - size * 0.60, cx - size * 0.18, cy - size * 0.60, cx - size * 0.32, cy - size * 0.38);
  endShape(CLOSE);

  // Texture de plis
  stroke(20, 22, 30, 70);
  strokeWeight(1.2);
  strokeCap(ROUND);
  for (let i = 0; i < 900; i++) {
    let x = random(cx - size * 0.38, cx + size * 0.38);
    let y = random(cy - size * 0.42, cy + size * 0.62);
    let dx = (x - cx) / (size * 0.4);
    let dy = (y - cy) / (size * 0.65);
    let inside = (dx * dx + dy * dy) < 1.0 ? 1 : 0;
    if (!inside) continue;
    let n = noise(x * 0.006, y * 0.006);
    let len = random(18, 70) * (0.4 + 0.9 * n);
    let ang = PI / 2 + (noise(x * 0.004, 99 + y * 0.004) - 0.5) * 1.1;
    let x2 = x + cos(ang) * len;
    let y2 = y + sin(ang) * len;
    stroke(18 + 20 * n, 20 + 20 * n, 28 + 30 * n, 35 + 70 * n);
    line(x, y, x2, y2);
  }

  // Capuche (proche)
  noStroke();
  fill(8, 9, 12, 240);
  beginShape();
  vertex(cx - size * 0.18, cy - size * 0.36);
  bezierVertex(cx - size * 0.32, cy - size * 0.36, cx - size * 0.35, cy - size * 0.20, cx - size * 0.24, cy - size * 0.07);
  bezierVertex(cx - size * 0.14, cy + size * 0.05, cx + size * 0.14, cy + size * 0.05, cx + size * 0.24, cy - size * 0.07);
  bezierVertex(cx + size * 0.35, cy - size * 0.20, cx + size * 0.32, cy - size * 0.36, cx + size * 0.18, cy - size * 0.36);
  bezierVertex(cx + size * 0.05, cy - size * 0.55, cx - size * 0.05, cy - size * 0.55, cx - size * 0.18, cy - size * 0.36);
  endShape(CLOSE);

  // Visage : vide + crâne suggéré (os pâle dans l'ombre)
  // Vide interne
  fill(0, 0, 0, 210);
  ellipse(cx, cy - size * 0.14, size * 0.30, size * 0.26);

  // "Os" subtil : deux creux (orbites) en négatif et arête légère
  push();
  blendMode(SCREEN);
  noStroke();
  // halo d'os
  for (let i = 0; i < 120; i++) {
    let x = randomGaussian(cx, size * 0.06);
    let y = randomGaussian(cy - size * 0.16, size * 0.05);
    let r = random(10, 36);
    let a = random(6, 16);
    fill(190, 186, 170, a);
    ellipse(x, y, r * 1.1, r);
  }
  pop();

  // Orbites (assombries)
  noStroke();
  fill(0, 0, 0, 170);
  ellipse(cx - size * 0.06, cy - size * 0.16, size * 0.07, size * 0.06);
  ellipse(cx + size * 0.06, cy - size * 0.16, size * 0.07, size * 0.06);

  // Arête nasale suggérée
  push();
  stroke(220, 214, 198, 50);
  strokeWeight(2);
  line(cx, cy - size * 0.14, cx, cy - size * 0.06);
  pop();

  // Bord de capuche plus clair
  push();
  noFill();
  stroke(90, 92, 105, 60);
  strokeWeight(2);
  beginShape();
  for (let i = 0; i <= 30; i++) {
    let t = i / 30;
    let ang = lerp(PI * 1.05, PI * -0.05, t);
    let rx = size * 0.19;
    let ry = size * 0.15;
    let x = cx + cos(ang) * rx;
    let y = (cy - size * 0.20) + sin(ang) * ry;
    x += (noise(t * 6.1, 12.3) - 0.5) * 8;
    y += (noise(t * 6.1, 32.3) - 0.5) * 8;
    vertex(x, y);
  }
  endShape();
  pop();

  // Ombre portée (décrochage du monde)
  push();
  blendMode(MULTIPLY);
  noStroke();
  for (let i = 0; i < 240; i++) {
    let x = random(cx - size * 0.45, cx + size * 0.45);
    let y = random(cy + size * 0.10, cy + size * 0.85);
    let d = dist(x, y, cx, cy + size * 0.35);
    let a = max(0, 45 - d * 0.12);
    fill(0, 0, 0, a);
    ellipse(x, y, random(50, 180), random(40, 150));
  }
  pop();

  pop();
}

function drawMoths(cx, cy, size) {
  push();
  // Zone autour du visage/poitrine
  for (let i = 0; i < 520; i++) {
    let ang = random(TWO_PI);
    let rad = pow(random(), 0.55) * size * 0.55;
    let x = cx + cos(ang) * rad + randomGaussian(0, 18);
    let y = cy + sin(ang) * rad * 0.85 + randomGaussian(0, 18);

    // évite trop bas (près de la barque)
    if (y > cy + size * 0.55) continue;

    let n = noise(x * 0.008, y * 0.008);
    if (n < 0.35) continue;

    let s = random(7, 22) * (0.55 + 0.9 * n);
    let alpha = 18 + 70 * n;

    // corps
    noStroke();
    fill(210, 206, 192, alpha * 0.35);
    ellipse(x, y, s * 0.20, s * 0.55);

    // ailes (deux ellipses)
    let wing = s * random(0.8, 1.3);
    let tilt = (noise(x * 0.01, y * 0.01) - 0.5) * 0.9;
    push();
    translate(x, y);
    rotate(tilt);
    fill(225, 221, 208, alpha * 0.28);
    ellipse(-wing * 0.28, 0, wing * 0.72, wing * 0.52);
    ellipse(+wing * 0.28, 0, wing * 0.72, wing * 0.52);

    // poussière autour
    for (let k = 0; k < 3; k++) {
      fill(235, 232, 224, alpha * 0.10);
      ellipse(randomGaussian(0, wing * 0.25), randomGaussian(0, wing * 0.18), random(2, 5), random(2, 5));
    }
    pop();
  }
  pop();
}

function vignette(strength) {
  push();
  noStroke();
  let cx = W / 2, cy = H / 2;
  let maxR = dist(0, 0, cx, cy) * 1.25;
  for (let i = 0; i < 260; i++) {
    let t = i / 259;
    let r = lerp(maxR * 0.55, maxR, t);
    let a = pow(t, 1.7) * 255 * strength * 0.35;
    fill(0, 0, 0, a);
    ellipse(cx, cy, r * 2.0, r * 2.35);
  }
  pop();
}

// p5.js 1.11
let W = 1600, H = 2000;

function setup() {
  createCanvas(W, H);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  drawScene();
}

function draw() {}

function drawScene() {
  background(8, 10, 14);

  drawVerticalGradient(color(10, 12, 18), color(2, 3, 6));
  drawDistantGlow();
  drawMistSky();
  drawEclipse(width * 0.56, height * 0.30, 360);

  let horizon = height * 0.57;
  drawHorizon(horizon);

  drawFarGraves(horizon);
  drawWater(horizon);
  drawShore(horizon);
  drawDeadTree(width * 0.18, horizon + 250, 520);

  addAsh(5200);
  addGrain(0.09);
  vignette();
}

function drawVerticalGradient(cTop, cBot) {
  noStroke();
  for (let y = 0; y < height; y++) {
    let t = y / (height - 1);
    let c = lerpColor(cTop, cBot, pow(t, 1.15));
    fill(red(c), green(c), blue(c));
    rect(0, y, width, 1);
  }
}

function drawDistantGlow() {
  push();
  blendMode(ADD);
  noStroke();
  let cx = width * 0.52;
  let cy = height * 0.34;
  for (let i = 0; i < 36; i++) {
    let r = 80 + i * 26;
    let a = 16 * exp(-i * 0.08);
    fill(40, 55, 65, a);
    ellipse(cx, cy, r * 2.2, r * 1.9);
  }
  pop();
}

function drawMistSky() {
  push();
  noStroke();
  for (let k = 0; k < 120; k++) {
    let y = random(height * 0.05, height * 0.60);
    let x = random(-200, width + 200);
    let w = random(240, 900);
    let h = random(60, 190);
    let n = noise(x * 0.002, y * 0.002, k * 0.02);
    let a = 26 * n;
    fill(120, 140, 150, a);
    ellipse(x, y, w, h);
  }

  // faint streaks
  for (let i = 0; i < 140; i++) {
    let y = random(height * 0.08, height * 0.58);
    let x0 = random(-200, width + 200);
    let x1 = x0 + random(200, 900);
    let n = noise(i * 0.07, y * 0.004);
    stroke(150, 165, 170, 18 * n);
    strokeWeight(random(1, 3));
    line(x0, y, x1, y + random(-10, 10));
  }
  pop();
}

function drawEclipse(cx, cy, r) {
  push();
  noStroke();

  // halo ring
  blendMode(ADD);
  for (let i = 0; i < 28; i++) {
    let rr = r * (1.05 + i * 0.09);
    let a = 22 * exp(-i * 0.10);
    fill(70, 95, 105, a);
    ellipse(cx, cy, rr * 2.0, rr * 2.0);
  }
  blendMode(BLEND);

  // dim disc
  fill(210, 220, 225, 20);
  ellipse(cx, cy, r * 2.02, r * 2.02);

  // black sun
  fill(4, 5, 8, 240);
  ellipse(cx, cy, r * 1.86, r * 1.86);

  // subtle corona irregularity
  blendMode(ADD);
  for (let a = 0; a < TWO_PI; a += 0.012) {
    let n = noise(cos(a) * 1.2 + 10, sin(a) * 1.2 + 10);
    let rr = r * 1.05 + 90 * pow(n, 2.2);
    let x = cx + cos(a) * rr;
    let y = cy + sin(a) * rr;
    stroke(120, 155, 165, 18 * n);
    strokeWeight(1.2);
    point(x, y);
  }
  pop();
}

function drawHorizon(hy) {
  push();
  stroke(170, 180, 185, 18);
  strokeWeight(2);
  line(0, hy, width, hy);

  // distant band
  noStroke();
  for (let i = 0; i < 28; i++) {
    let y = hy - 70 + i * 6;
    let a = 10 * exp(-i * 0.07);
    fill(90, 105, 110, a);
    rect(0, y, width, 6);
  }
  pop();
}

function drawFarGraves(hy) {
  push();
  noStroke();
  let baseY = hy - 10;

  for (let i = 0; i < 32; i++) {
    let x = random(width * 0.45, width * 0.98);
    let w = random(18, 46);
    let h = random(32, 92);
    let y = baseY - h + random(-6, 6);
    let fog = noise(x * 0.003, y * 0.01);
    let c = lerpColor(color(35, 40, 44, 200), color(18, 22, 26, 240), 0.6);
    fill(red(c), green(c), blue(c), 120 + 80 * fog);
    roundedRect(x, y, w, h, w * 0.45);
  }

  // a few leaning stones
  for (let i = 0; i < 10; i++) {
    let x = random(width * 0.55, width * 0.95);
    let w = random(22, 54);
    let h = random(40, 110);
    let y = baseY - h + random(-10, 10);
    push();
    translate(x + w / 2, y + h / 2);
    rotate(random(-0.18, 0.18));
    fill(18, 22, 26, 210);
    roundedRect(-w / 2, -h / 2, w, h, w * 0.45);
    pop();
  }

  pop();
}

function drawWater(hy) {
  push();
  noStroke();

  // water gradient
  for (let y = hy; y < height; y++) {
    let t = (y - hy) / (height - hy);
    let c = lerpColor(color(6, 9, 12), color(1, 2, 3), pow(t, 0.8));
    fill(red(c), green(c), blue(c), 255);
    rect(0, y, width, 1);
  }

  // reflection of eclipse (blurred)
  let cx = width * 0.56;
  let cy = hy + (hy - height * 0.30) * 0.82;
  push();
  blendMode(ADD);
  for (let i = 0; i < 44; i++) {
    let w = 90 + i * 22;
    let h = 22 + i * 10;
    let a = 16 * exp(-i * 0.08);
    fill(50, 80, 90, a);
    ellipse(cx + random(-18, 18), cy + random(-10, 10), w * 2.2, h);
  }
  pop();

  // ripples / vertical broken strokes
  for (let i = 0; i < 12000; i++) {
    let x = random(width);
    let y = random(hy, height);
    let t = (y - hy) / (height - hy);
    let n = noise(x * 0.008, y * 0.010);
    let a = (10 + 30 * n) * (1.0 - t * 0.75);
    let len = random(6, 26) * (0.35 + (1 - t) * 0.9);
    stroke(110, 130, 135, a);
    strokeWeight(1);
    line(x, y, x + random(-2, 2), y + len);
  }

  // darker current bands
  noStroke();
  for (let b = 0; b < 40; b++) {
    let y = lerp(hy + 20, height - 40, b / 39);
    let n = noise(b * 0.15);
    let a = 20 * (0.3 + n);
    fill(0, 0, 0, a);
    beginShape();
    vertex(0, y);
    for (let x = 0; x <= width; x += 40) {
      let yy = y + (noise(x * 0.003, b * 0.2) - 0.5) * 50;
      vertex(x, yy);
    }
    vertex(width, y + 60);
    vertex(0, y + 60);
    endShape(CLOSE);
  }

  pop();
}

function drawShore(hy) {
  push();
  noStroke();

  // foreground shore silhouette
  fill(0, 0, 0, 220);
  beginShape();
  vertex(0, hy + 240);
  vertex(width * 0.10, hy + 190);
  vertex(width * 0.20, hy + 210);
  vertex(width * 0.32, hy + 160);
  vertex(width * 0.46, hy + 205);
  vertex(width * 0.60, hy + 150);
  vertex(width * 0.78, hy + 190);
  vertex(width, hy + 140);
  vertex(width, height);
  vertex(0, height);
  endShape(CLOSE);

  // thin wet edge highlight
  stroke(120, 135, 140, 40);
  strokeWeight(2);
  for (let i = 0; i < 140; i++) {
    let x = map(i, 0, 139, 0, width);
    let y = hy + 175 + (noise(i * 0.05, 9) - 0.5) * 60;
    point(x, y);
  }

  pop();
}

function drawDeadTree(x, y, h) {
  push();
  stroke(0, 0, 0, 240);
  strokeWeight(18);
  strokeCap(ROUND);

  // trunk
  let x0 = x, y0 = y;
  let x1 = x + 60, y1 = y - h * 0.55;
  let x2 = x - 10, y2 = y - h * 1.0;
  bezier(x0, y0, x + 40, y - h * 0.25, x + 20, y - h * 0.7, x2, y2);

  // bark shadow fill
  strokeWeight(9);
  stroke(20, 22, 26, 200);
  bezier(x0 + 8, y0, x + 46, y - h * 0.25, x + 26, y - h * 0.7, x2 + 6, y2);

  // main branches
  stroke(0, 0, 0, 235);
  strokeWeight(9);
  branch(x2, y2, -PI * 0.65, h * 0.32, 5);
  branch(x2 + 40, y2 + 60, -PI * 0.25, h * 0.26, 5);
  branch(x2 - 30, y2 + 90, -PI * 0.92, h * 0.22, 5);

  // hanging twigs like ash
  strokeWeight(2);
  stroke(0, 0, 0, 160);
  for (let i = 0; i < 220; i++) {
    let px = x + random(-40, 160);
    let py = y - random(h * 0.2, h * 0.95);
    if (random() < 0.55) continue;
    let len = random(18, 90);
    line(px, py, px + random(-10, 10), py + len);
  }

  pop();
}

function branch(x, y, ang, len, depth) {
  if (depth <= 0 || len < 12) return;
  let x2 = x + cos(ang) * len;
  let y2 = y + sin(ang) * len;
  line(x, y, x2, y2);

  let n1 = noise(x * 0.01, y * 0.01, depth * 0.3);
  let n2 = noise(x * 0.01 + 5, y * 0.01 + 5, depth * 0.3);
  let a1 = ang + lerp(-0.7, -0.15, n1);
  let a2 = ang + lerp(0.15, 0.7, n2);

  let w = max(1.4, depth * 1.6);
  strokeWeight(w);

  branch(x2, y2, a1, len * (0.68 + n1 * 0.12), depth - 1);
  branch(x2, y2, a2, len * (0.66 + n2 * 0.12), depth - 1);

  if (random() < 0.35) {
    let a3 = ang + random(-0.25, 0.25);
    branch(x2, y2, a3, len * random(0.35, 0.55), depth - 2);
  }
}

function addAsh(count) {
  push();
  noStroke();
  for (let i = 0; i < count; i++) {
    let x = random(width);
    let y = random(height);
    let t = y / height;
    // more ash near water and mid air
    let bias = exp(-pow((t - 0.62) / 0.22, 2));
    if (random() > 0.25 + 0.75 * bias) continue;

    let s = random(1, 4) * (0.4 + bias);
    let a = (12 + 50 * bias) * random(0.2, 1.0);
    fill(190, 200, 205, a);
    ellipse(x, y, s, s * random(0.6, 1.4));
  }
  pop();
}

function addGrain(strength) {
  loadPixels();
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let idx = 4 * (y * width + x);
      let n = (noise(x * 0.04, y * 0.04) - 0.5) * 255 * strength;
      pixels[idx + 0] = constrain(pixels[idx + 0] + n, 0, 255);
      pixels[idx + 1] = constrain(pixels[idx + 1] + n, 0, 255);
      pixels[idx + 2] = constrain(pixels[idx + 2] + n, 0, 255);
    }
  }
  updatePixels();
}

function vignette() {
  push();
  noStroke();
  blendMode(MULTIPLY);
  let cx = width / 2, cy = height / 2;
  for (let i = 0; i < 26; i++) {
    let t = i / 25;
    let a = 18 * pow(t, 1.7);
    fill(0, 0, 0, a);
    ellipse(cx, cy, width * (1.05 + t * 0.55), height * (1.05 + t * 0.65));
  }
  pop();
}

function roundedRect(x, y, w, h, r) {
  // no text, only geometry
  beginShape();
  vertex(x + r, y);
  vertex(x + w - r, y);
  quadraticVertex(x + w, y, x + w, y + r);
  vertex(x + w, y + h - r);
  quadraticVertex(x + w, y + h, x + w - r, y + h);
  vertex(x + r, y + h);
  quadraticVertex(x, y + h, x, y + h - r);
  vertex(x, y + r);
  quadraticVertex(x, y, x + r, y);
  endShape(CLOSE);
}

// p5.js 1.11 — static painting, no text rendered
let W = 1600, H = 2000;

function setup() {
  createCanvas(W, H);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  background(5, 6, 10);

  drawBackgroundGradient();
  drawDistantFog();
  drawVignette();
  drawGround();
  drawLilyStillLife();
  drawMoth();
  drawBoneFragment();
  addGrain(280000);
}

function drawBackgroundGradient() {
  // Deep indigo to near-black, slightly greenish at bottom
  for (let y = 0; y < H; y++) {
    let t = y / (H - 1);
    let r = lerp(10, 3, t);
    let g = lerp(12, 6, t);
    let b = lerp(24, 10, t);
    stroke(r, g, b);
    line(0, y, W, y);
  }

  // Subtle vertical light shaft (faint, like distant windowless glow)
  noStroke();
  for (let i = 0; i < 1200; i++) {
    let x = W * 0.52 + randomGaussian() * 90;
    let y = H * 0.20 + random() * H * 0.75;
    let a = 6 + random() * 10;
    fill(150, 160, 190, a);
    ellipse(x, y, 120 + random() * 260, 80 + random() * 240);
  }
}

function drawDistantFog() {
  // Fog band around mid height
  noStroke();
  for (let k = 0; k < 9000; k++) {
    let x = random(W);
    let y = H * 0.42 + randomGaussian() * 120;
    let n = noise(x * 0.002, y * 0.003);
    let a = 10 + 40 * pow(n, 2);
    fill(120, 130, 150, a * 0.30);
    ellipse(x, y, 40 + 140 * n, 18 + 80 * n);
  }

  // Low mist touching ground
  for (let k = 0; k < 9000; k++) {
    let x = random(W);
    let y = H * 0.63 + randomGaussian() * 90;
    let n = noise(100 + x * 0.003, 200 + y * 0.006);
    let a = 6 + 30 * n;
    fill(140, 150, 170, a * 0.25);
    ellipse(x, y, 30 + 120 * n, 12 + 60 * n);
  }
}

function drawVignette() {
  noStroke();
  // Dark corners
  for (let i = 0; i < 220; i++) {
    let t = i / 219;
    let a = 90 * pow(t, 1.8);
    fill(0, 0, 0, a);
    rect(0, 0, W, H);
  }
  // Slight cool center haze
  for (let i = 0; i < 120; i++) {
    let t = i / 119;
    let a = 14 * (1 - t);
    fill(90, 110, 140, a);
    ellipse(W * 0.52, H * 0.45, W * (0.55 + t * 0.7), H * (0.45 + t * 0.7));
  }
}

function drawGround() {
  // Base earth
  noStroke();
  fill(6, 6, 8, 255);
  rect(0, H * 0.60, W, H * 0.40);

  // Textured soil layers
  for (let y = int(H * 0.58); y < H; y += 2) {
    let t = map(y, H * 0.58, H, 0, 1);
    let base = lerp(18, 6, t);
    stroke(base, base + 1, base + 2, 200);
    for (let x = 0; x < W; x += 8) {
      let n = noise(x * 0.004, y * 0.01);
      let jitter = (n - 0.5) * 10;
      line(x, y + jitter, x + 8, y + jitter);
    }
  }

  // Pebbles and clods
  noStroke();
  for (let i = 0; i < 1800; i++) {
    let x = random(W);
    let y = random(H * 0.62, H * 0.98);
    let n = noise(x * 0.01, y * 0.01);
    let s = 2 + 18 * pow(n, 2.3);
    let a = 20 + 90 * pow(n, 2);
    fill(10 + 18 * n, 10 + 16 * n, 12 + 16 * n, a);
    ellipse(x, y, s * (0.8 + random() * 0.7), s * (0.7 + random() * 0.8));
  }

  // Shallow depression where the flower lies
  for (let i = 0; i < 140; i++) {
    let t = i / 139;
    let a = 60 * (1 - t);
    fill(0, 0, 0, a);
    ellipse(W * 0.54, H * 0.76, 780 + t * 260, 260 + t * 160);
  }
}

function drawLilyStillLife() {
  // Shadow under lily
  noStroke();
  for (let i = 0; i < 70; i++) {
    let t = i / 69;
    fill(0, 0, 0, 26 * (1 - t));
    ellipse(W * 0.55, H * 0.77, 640 + t * 340, 140 + t * 120);
  }

  // Stem (wilted curve)
  let x0 = W * 0.20, y0 = H * 0.70;
  let x1 = W * 0.38, y1 = H * 0.72;
  let x2 = W * 0.56, y2 = H * 0.86;
  let x3 = W * 0.70, y3 = H * 0.82;

  for (let pass = 0; pass < 24; pass++) {
    let w = 18 - pass * 0.5;
    let a = 18 - pass * 0.45;
    stroke(40, 52, 34, a);
    strokeWeight(max(1, w));
    noFill();

    beginShape();
    for (let t = 0; t <= 1.001; t += 0.03) {
      let x = bezierPoint(x0, x1, x2, x3, t);
      let y = bezierPoint(y0, y1, y2, y3, t);
      let n = noise(20 + t * 8, pass * 0.2);
      x += (n - 0.5) * 8;
      y += (noise(60 + t * 7, pass * 0.25) - 0.5) * 10;
      curveVertex(x, y);
    }
    endShape();
  }

  // Lily head position and tilt
  let hx = W * 0.71, hy = H * 0.82;
  let tilt = -0.85;

  // Petals (withered, translucent)
  push();
  translate(hx, hy);
  rotate(tilt);

  // Inner glow (pale life fading)
  noStroke();
  for (let i = 0; i < 60; i++) {
    let t = i / 59;
    fill(220, 225, 230, 18 * (1 - t));
    ellipse(-40, -10, 180 + t * 160, 120 + t * 120);
  }

  // Draw petals in layers
  let petals = [
    {x: -20, y: -10, a: -0.2, s: 1.25},
    {x: -10, y: 10,  a: 0.35, s: 1.15},
    {x: -45, y: 8,   a: -0.85, s: 1.10},
    {x: 15,  y: 5,   a: 0.9,  s: 1.05},
    {x: 30,  y: -15, a: 0.55, s: 0.98},
    {x: -60, y: -22, a: -1.2, s: 0.95}
  ];

  for (let p of petals) {
    drawPetal(p.x, p.y, p.a, p.s);
  }

  // Dark throat and stamens (no sharp biological accuracy, more symbolic)
  noStroke();
  fill(35, 28, 32, 150);
  ellipse(-15, 0, 70, 42);

  stroke(120, 102, 90, 160);
  strokeWeight(3);
  for (let i = 0; i < 6; i++) {
    let ang = -0.9 + i * 0.35;
    let x = -10 + cos(ang) * 70;
    let y = 0 + sin(ang) * 36;
    line(-18, 0, x, y);
    noStroke();
    fill(140, 120, 105, 180);
    ellipse(x, y, 10, 7);
    stroke(120, 102, 90, 160);
  }

  pop();

  // Fallen petals around (separate pieces, like time fragments)
  for (let i = 0; i < 7; i++) {
    let x = W * 0.55 + randomGaussian() * 220;
    let y = H * 0.86 + randomGaussian() * 70;
    let ang = random(-PI, PI);
    let sc = 0.55 + random() * 0.55;
    drawFallenPetal(x, y, ang, sc);
  }
}

function drawPetal(px, py, ang, sc) {
  push();
  translate(px, py);
  rotate(ang);
  scale(sc);

  // Petal body, with bruised edges
  for (let layer = 0; layer < 10; layer++) {
    let t = layer / 9;
    let a = 36 - layer * 2.8;
    let shade = lerp(232, 190, t);
    let cool = lerp(235, 205, t);
    fill(shade, cool, 240, a);
    noStroke();

    beginShape();
    let w = 170 - t * 30;
    let h = 95 - t * 10;
    vertex(-10, 0);
    bezierVertex(30, -h, w, -h * 0.45, w, 0);
    bezierVertex(w, h * 0.55, 40, h, -10, 0);
    endShape(CLOSE);

    // Edge rag (wither)
    fill(70, 60, 65, 10);
    ellipse(w * 0.85, 0, 36 + t * 14, 20 + t * 10);
  }

  // Veins
  stroke(190, 195, 205, 55);
  strokeWeight(2);
  for (let k = 0; k < 9; k++) {
    let t = k / 8;
    let x1 = lerp(5, 140, t);
    let y1 = (noise(10 + t * 3, 50 + k * 0.2) - 0.5) * 18;
    line(0, 0, x1, y1);
  }

  // Bruises
  noStroke();
  for (let i = 0; i < 22; i++) {
    let x = random(25, 140);
    let y = random(-40, 40);
    let n = noise(x * 0.04, y * 0.06);
    fill(120, 105, 112, 18 + 30 * n);
    ellipse(x, y, 6 + 22 * n, 4 + 16 * n);
  }

  pop();
}

function drawFallenPetal(x, y, ang, sc) {
  push();
  translate(x, y);
  rotate(ang);
  scale(sc);

  // Shadow
  noStroke();
  fill(0, 0, 0, 35);
  ellipse(10, 12, 170, 40);

  // Petal
  for (let layer = 0; layer < 9; layer++) {
    let t = layer / 8;
    let a = 30 - layer * 2.4;
    fill(225 - t * 40, 228 - t * 55, 238 - t * 30, a);
    beginShape();
    vertex(-70, 0);
    bezierVertex(-20, -70, 90, -45, 95, 0);
    bezierVertex(85, 55, -10, 65, -70, 0);
    endShape(CLOSE);
  }

  // Dirt smears
  noStroke();
  for (let i = 0; i < 30; i++) {
    let px = random(-40, 70);
    let py = random(-25, 25);
    let n = noise(200 + px * 0.05, 300 + py * 0.08);
    fill(30, 26, 28, 8 + 28 * n);
    ellipse(px, py, 4 + 18 * n, 3 + 14 * n);
  }
  pop();
}

function drawMoth() {
  // A faint moth hovering above: not salvation, just motion persisting
  let cx = W * 0.49;
  let cy = H * 0.46;

  // Glow around moth
  noStroke();
  for (let i = 0; i < 70; i++) {
    let t = i / 69;
    fill(165, 175, 200, 10 * (1 - t));
    ellipse(cx, cy, 240 + t * 320, 160 + t * 260);
  }

  // Wings
  push();
  translate(cx, cy);
  rotate(-0.08);

  // Soft shadow
  noStroke();
  fill(0, 0, 0, 45);
  ellipse(6, 10, 220, 90);

  // Left wing
  drawWing(-58, 0, -1);
  // Right wing
  drawWing(58, 0, 1);

  // Body
  noStroke();
  fill(80, 75, 78, 180);
  ellipse(0, 8, 18, 64);
  fill(120, 115, 118, 130);
  ellipse(0, -6, 14, 28);

  // Antennae
  stroke(120, 120, 125, 120);
  strokeWeight(2);
  noFill();
  beginShape();
  curveVertex(-2, -22);
  curveVertex(-2, -22);
  curveVertex(-20, -44);
  curveVertex(-40, -56);
  curveVertex(-54, -60);
  endShape();

  beginShape();
  curveVertex(2, -22);
  curveVertex(2, -22);
  curveVertex(20, -44);
  curveVertex(40, -56);
  curveVertex(54, -60);
  endShape();

  pop();
}

function drawWing(dx, dy, side) {
  push();
  translate(dx, dy);

  // Wing fill
  for (let layer = 0; layer < 12; layer++) {
    let t = layer / 11;
    let a = 45 - layer * 2.8;
    let r = lerp(170, 110, t);
    let g = lerp(176, 120, t);
    let b = lerp(190, 135, t);
    fill(r, g, b, a);
    noStroke();

    beginShape();
    vertex(0, 0);
    bezierVertex(35 * side, -35, 110 * side, -20, 120 * side, 15);
    bezierVertex(110 * side, 55, 35 * side, 60, 0, 24);
    endShape(CLOSE);
  }

  // Wing veins
  stroke(90, 92, 105, 85);
  strokeWeight(2);
  for (let i = 0; i < 8; i++) {
    let t = i / 7;
    let x = lerp(0, 110 * side, t);
    let y = lerp(10, 20, t) + (noise(10 + i * 0.3, 9) - 0.5) * 10;
    line(0, 8, x, y);
  }

  // Speckles
  noStroke();
  for (let i = 0; i < 120; i++) {
    let x = random(5, 125) * side;
    let y = random(-18, 45);
    let n = noise(500 + x * 0.03, 600 + y * 0.05);
    let a = 10 + 65 * pow(n, 2.2);
    fill(235, 238, 245, a * 0.35);
    ellipse(x, y, 2 + 6 * n, 2 + 5 * n);
  }

  pop();
}

function drawBoneFragment() {
  // Small ambiguous bone shard on soil: understated mortality
  let x = W * 0.36, y = H * 0.86;
  push();
  translate(x, y);
  rotate(-0.35);

  // Shadow
  noStroke();
  fill(0, 0, 0, 40);
  ellipse(10, 14, 260, 60);

  // Bone base
  for (let i = 0; i < 10; i++) {
    let t = i / 9;
    fill(215 - t * 35, 210 - t * 45, 205 - t * 45, 55 - i * 3.2);
    beginShape();
    vertex(-110, 0);
    bezierVertex(-80, -55, -20, -45, 0, -12);
    bezierVertex(30, -40, 90, -35, 120, 0);
    bezierVertex(90, 38, 35, 44, 0, 15);
    bezierVertex(-25, 50, -80, 40, -110, 0);
    endShape(CLOSE);
  }

  // Cracks
  stroke(110, 98, 92, 110);
  strokeWeight(2);
  for (let k = 0; k < 7; k++) {
    let x1 = lerp(-80, 80, k / 6);
    let y1 = (noise(30 + k * 0.6, 90) - 0.5) * 18;
    let x2 = x1 + (noise(80 + k, 20) - 0.5) * 40;
    let y2 = y1 + 18 + (noise(90 + k, 22) - 0.5) * 24;
    line(x1, y1, x2, y2);
  }

  pop();
}

function addGrain(count) {
  // Film grain and dust
  loadPixels();
  for (let i = 0; i < count; i++) {
    let x = int(random(W));
    let y = int(random(H));
    let idx = 4 * (y * W + x);

    let n = noise(x * 0.02, y * 0.02);
    let g = (random() < 0.5 ? -1 : 1) * (6 + 24 * n);

    pixels[idx + 0] = constrain(pixels[idx + 0] + g, 0, 255);
    pixels[idx + 1] = constrain(pixels[idx + 1] + g, 0, 255);
    pixels[idx + 2] = constrain(pixels[idx + 2] + g, 0, 255);
    // alpha untouched
  }
  updatePixels();

  // A few dust motes
  noStroke();
  for (let i = 0; i < 1800; i++) {
    let x = random(W);
    let y = random(H);
    let a = 4 + 14 * noise(900 + x * 0.004, 900 + y * 0.004);
    fill(230, 235, 245, a * 0.22);
    ellipse(x, y, 1.2 + random() * 2.4, 1.2 + random() * 2.4);
  }
}

// p5.js 1.11 - static image, 1600x2000
let W = 1600, H = 2000;

function setup() {
  createCanvas(W, H);
  pixelDensity(2);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  drawBackground();
  drawFaintHalo();
  drawGround();
  drawCracks();
  drawStemAndFlower();
  drawMothsAndAsh();
  addGrain();
  vignette();
}

function drawBackground() {
  // Deep, cold gradient with subtle noise wash
  noStroke();
  for (let y = 0; y < H; y++) {
    let t = y / (H - 1);
    let c1 = color(10, 9, 18);
    let c2 = color(22, 16, 42);
    let c3 = color(7, 7, 10);
    let c = lerpColor(lerpColor(c1, c2, smoothstep(0.0, 0.65, t)), c3, smoothstep(0.65, 1.0, t));
    fill(red(c), green(c), blue(c), 255);
    rect(0, y, W, 1);
  }

  // smoky layers
  for (let i = 0; i < 10; i++) {
    let y0 = lerp(0, H * 0.9, i / 9);
    let amp = lerp(80, 240, i / 9);
    let baseA = lerp(16, 6, i / 9);
    fill(110, 95, 140, baseA);
    beginShape();
    vertex(0, y0);
    for (let x = 0; x <= W; x += 30) {
      let n = noise(x * 0.002, y0 * 0.002, i * 0.2);
      let yy = y0 + (n - 0.5) * amp;
      vertex(x, yy);
    }
    vertex(W, y0 + 200);
    vertex(0, y0 + 200);
    endShape(CLOSE);
  }
}

function drawFaintHalo() {
  // A dim, off-center "afterimage" behind the flower
  push();
  translate(W * 0.52, H * 0.47);
  noStroke();
  for (let r = 20; r < 560; r += 8) {
    let a = map(r, 20, 560, 34, 0);
    fill(200, 190, 205, a);
    ellipse(0, 0, r * 1.05, r * 0.92);
  }
  pop();
}

function drawGround() {
  // dark earth plane
  let horizon = H * 0.72;

  noStroke();
  // base
  fill(18, 14, 16, 255);
  rect(0, horizon, W, H - horizon);

  // layered soil texture
  for (let y = horizon; y < H; y += 2) {
    let t = (y - horizon) / (H - horizon);
    let r = lerp(35, 15, t);
    let g = lerp(26, 13, t);
    let b = lerp(24, 12, t);
    let a = 180;
    fill(r, g, b, a);
    rect(0, y, W, 2);

    // subtle horizontal striations
    if (y % 10 === 0) {
      fill(60, 46, 44, 22);
      rect(0, y + random(-1, 1), W, 1);
    }
  }

  // scattered stones/bone chips
  for (let i = 0; i < 120; i++) {
    let x = random(W);
    let y = random(horizon + 40, H - 40);
    let s = random(6, 26);
    let tint = random();
    let c = lerpColor(color(90, 78, 72, 90), color(205, 198, 186, 70), tint);
    noStroke();
    fill(red(c), green(c), blue(c), alpha(c));
    push();
    translate(x, y);
    rotate(random(-0.8, 0.8));
    beginShape();
    for (let k = 0; k < 7; k++) {
      let ang = (TWO_PI * k) / 7;
      let rr = s * random(0.45, 1.0);
      vertex(cos(ang) * rr, sin(ang) * rr * random(0.6, 1.0));
    }
    endShape(CLOSE);
    pop();
  }
}

function drawCracks() {
  let horizon = H * 0.72;
  stroke(10, 8, 10, 190);
  strokeWeight(2);

  // main crack origins near flower base
  let origins = [
    createVector(W * 0.52, H * 0.79),
    createVector(W * 0.47, H * 0.82),
    createVector(W * 0.58, H * 0.84)
  ];

  for (let o of origins) {
    crackFrom(o.x, o.y, random(260, 520), random(-PI * 0.95, -PI * 0.05), horizon, H);
  }

  // minor cracks scattered
  stroke(12, 10, 12, 120);
  strokeWeight(1.4);
  for (let i = 0; i < 28; i++) {
    let x = random(W);
    let y = random(H * 0.76, H * 0.97);
    crackFrom(x, y, random(120, 260), random(-PI, 0), horizon, H);
  }
}

function crackFrom(x, y, len, ang, yMin, yMax) {
  let steps = int(len / 8);
  let px = x, py = y;
  for (let i = 0; i < steps; i++) {
    let t = i / max(1, steps - 1);
    let wob = (noise(px * 0.004, py * 0.004, 2.0) - 0.5) * 0.7;
    let a = ang + wob;
    let step = lerp(10, 5, t);
    let nx = px + cos(a) * step;
    let ny = py + sin(a) * step;

    if (ny < yMin + 10 || ny > yMax - 10) break;

    line(px, py, nx, ny);

    // occasional branching
    if (random() < 0.08 && i > 5) {
      push();
      strokeWeight(max(0.9, (strokeWeight() || 1.2) - 0.3));
      crackBranch(px, py, random(50, 140), a + random(-0.9, 0.9), yMin, yMax);
      pop();
    }

    px = nx;
    py = ny;
  }
}

function crackBranch(x, y, len, ang, yMin, yMax) {
  let steps = int(len / 7);
  let px = x, py = y;
  for (let i = 0; i < steps; i++) {
    let wob = (noise(px * 0.006, py * 0.006, 5.0) - 0.5) * 0.8;
    let a = ang + wob;
    let step = 7;
    let nx = px + cos(a) * step;
    let ny = py + sin(a) * step;
    if (ny < yMin + 10 || ny > yMax - 10) break;
    line(px, py, nx, ny);
    px = nx;
    py = ny;
  }
}

function drawStemAndFlower() {
  let baseX = W * 0.52;
  let baseY = H * 0.81;
  let topX = W * 0.50;
  let topY = H * 0.38;

  // shadow under stem
  noStroke();
  fill(0, 0, 0, 120);
  ellipse(baseX + 10, baseY + 70, 340, 90);

  // stem path points
  let pts = [];
  for (let i = 0; i <= 24; i++) {
    let t = i / 24;
    let x = lerp(baseX, topX, t) + sin(t * 3.2) * lerp(0, -80, t) + (noise(t * 1.8) - 0.5) * 20;
    let y = lerp(baseY, topY, t) - sin(t * 2.4) * 20;
    pts.push(createVector(x, y));
  }

  // stem thickness taper
  for (let pass = 0; pass < 2; pass++) {
    for (let i = 0; i < pts.length - 1; i++) {
      let t = i / (pts.length - 2);
      let w = lerp(22, 6, t);
      w *= (pass === 0) ? 1.0 : 0.7;

      // bone-like color with bruised undertone
      let cA = color(220, 214, 202, 210);
      let cB = color(160, 150, 155, 190);
      let c = lerpColor(cA, cB, smoothstep(0.2, 0.95, t));

      stroke(red(c), green(c), blue(c), alpha(c));
      strokeWeight(w);
      strokeCap(ROUND);
      line(pts[i].x, pts[i].y, pts[i + 1].x, pts[i + 1].y);
    }
  }

  // subtle fissures on stem
  stroke(120, 112, 110, 110);
  strokeWeight(1.2);
  for (let i = 3; i < pts.length - 5; i += 2) {
    let p = pts[i];
    let q = pts[i + 1];
    let t = i / (pts.length - 1);
    let dx = q.x - p.x, dy = q.y - p.y;
    let ang = atan2(dy, dx) + HALF_PI;
    let l = lerp(10, 24, noise(i * 0.2));
    let cx = lerp(p.x, q.x, 0.5);
    let cy = lerp(p.y, q.y, 0.5);
    line(cx - cos(ang) * l * 0.5, cy - sin(ang) * l * 0.5,
         cx + cos(ang) * l * 0.5, cy + sin(ang) * l * 0.5);
  }

  // flower head: drooping petals like wilted cloth
  let head = pts[pts.length - 1];
  drawCalyx(head.x, head.y);
  drawWiltedPetals(head.x, head.y);
  drawFallingPetals(head.x, head.y);
}

function drawCalyx(x, y) {
  push();
  translate(x, y);
  rotate(-0.15);

  // dark calyx
  noStroke();
  for (let i = 0; i < 10; i++) {
    let t = i / 9;
    fill(60, 52, 65, lerp(90, 10, t));
    ellipse(0, 8, lerp(140, 60, t), lerp(110, 40, t));
  }

  // dried core
  fill(195, 188, 176, 170);
  beginShape();
  for (let i = 0; i < 12; i++) {
    let a = TWO_PI * i / 12;
    let rr = 22 + noise(i * 0.4, 10) * 18;
    vertex(cos(a) * rr, sin(a) * rr * 0.8 + 22);
  }
  endShape(CLOSE);

  pop();
}

function drawWiltedPetals(x, y) {
  push();
  translate(x, y);
  rotate(-0.25);

  let petalCount = 7;
  for (let i = 0; i < petalCount; i++) {
    let a = map(i, 0, petalCount, -PI * 0.95, PI * 0.25) + random(-0.08, 0.08);
    let droop = random(0.9, 1.3);
    let len = random(240, 360);
    let wid = random(110, 170);

    let baseCol = color(210, 204, 196, 150);
    let bruiseCol = color(118, 108, 140, 120);
    let edgeCol = color(235, 232, 226, 140);

    // petal shadow
    noStroke();
    fill(0, 0, 0, 28);
    drawPetal(a, len * 1.02, wid * 1.02, droop * 1.05, 10, 38);

    // petal body gradient by layering
    for (let k = 0; k < 12; k++) {
      let t = k / 11;
      let c = lerpColor(baseCol, bruiseCol, smoothstep(0.2, 1.0, t));
      let alphaBoost = lerp(26, 6, t);
      fill(red(c), green(c), blue(c), alpha(c) + alphaBoost);
      drawPetal(a, len * (1 - t * 0.18), wid * (1 - t * 0.22), droop, 0, 22);
    }

    // pale edge highlight
    fill(red(edgeCol), green(edgeCol), blue(edgeCol), 70);
    drawPetal(a, len * 0.96, wid * 0.94, droop * 0.98, -6, 18);

    // vein lines
    stroke(150, 146, 152, 70);
    strokeWeight(1.0);
    strokeCap(ROUND);
    for (let v = -2; v <= 2; v++) {
      let vv = v * wid * 0.12;
      let p0 = polarToCartesian(a, 10, 30);
      let p1 = polarToCartesian(a, len * 0.45, len * 0.35 * droop);
      let p2 = polarToCartesian(a + 0.05 * v, len * 0.82, len * 0.9 * droop);
      noFill();
      beginShape();
      curveVertex(p0.x + vv, p0.y + vv * 0.15);
      curveVertex(p0.x + vv, p0.y + vv * 0.15);
      curveVertex(p1.x + vv * 0.8, p1.y + vv * 0.15);
      curveVertex(p2.x + vv * 0.35, p2.y + vv * 0.1);
      curveVertex(p2.x + vv * 0.35, p2.y + vv * 0.1);
      endShape();
    }
  }
  pop();
}

function drawPetal(a, len, wid, droop, xOff, yOff) {
  // Petal drawn in local space around origin; droop controls downward sag.
  push();
  rotate(a);

  beginShape();
  // base near calyx
  let bx = xOff;
  let by = yOff;

  // left edge
  vertex(bx, by);
  bezierVertex(bx - wid * 0.35, by + len * 0.12,
               bx - wid * 0.55, by + len * 0.45,
               bx - wid * 0.22, by + len * 0.72 * droop);

  // tip (heavy, curled)
  bezierVertex(bx - wid * 0.10, by + len * 0.88 * droop,
               bx + wid * 0.12, by + len * 0.98 * droop,
               bx + wid * 0.22, by + len * 0.83 * droop);

  // right edge back to base
  bezierVertex(bx + wid * 0.55, by + len * 0.52,
               bx + wid * 0.35, by + len * 0.18,
               bx, by);

  endShape(CLOSE);
  pop();
}

function drawFallingPetals(x, y) {
  // A few detached fragments drifting downward
  for (let i = 0; i < 14; i++) {
    let px = x + random(-260, 260);
    let py = y + random(80, 980);
    let s = random(18, 70);
    let rot = random(-PI, PI);

    let c1 = color(214, 210, 206, 80);
    let c2 = color(120, 112, 140, 60);
    let c = lerpColor(c1, c2, random());

    push();
    translate(px, py);
    rotate(rot);
    noStroke();
    fill(red(c), green(c), blue(c), alpha(c));
    beginShape();
    vertex(-s * 0.55, -s * 0.10);
    bezierVertex(-s * 0.20, -s * 0.55, s * 0.25, -s * 0.40, s * 0.55, 0);
    bezierVertex(s * 0.20, s * 0.55, -s * 0.25, s * 0.40, -s * 0.55, -s * 0.10);
    endShape(CLOSE);

    // small shadow
    fill(0, 0, 0, 22);
    ellipse(0, s * 0.25, s * 0.9, s * 0.32);
    pop();
  }
}

function drawMothsAndAsh() {
  // Moths near the halo + drifting ash upward
  let centerX = W * 0.52, centerY = H * 0.47;

  // ash specks
  noStroke();
  for (let i = 0; i < 2200; i++) {
    let x = random(W);
    let y = random(H);
    let band = exp(-sq((y - centerY) / 520)) * 0.9 + 0.1;
    let a = 18 * band * (0.3 + random());
    fill(210, 206, 214, a);
    let r = random() < 0.8 ? 1 : 2;
    circle(x, y, r);
  }

  // moths (no text, simple silhouettes)
  for (let i = 0; i < 9; i++) {
    let ang = random(TWO_PI);
    let rad = random(120, 520);
    let x = centerX + cos(ang) * rad;
    let y = centerY + sin(ang) * rad * 0.85;
    let s = random(26, 60);

    // avoid too low (keep them in air)
    if (y > H * 0.75) continue;

    push();
    translate(x, y);
    rotate(ang + random(-0.6, 0.6));

    // glow smear
    noStroke();
    fill(240, 236, 244, 10);
    ellipse(0, 0, s * 3.2, s * 2.6);

    // wings
    fill(210, 206, 214, 70);
    beginShape();
    vertex(0, 0);
    bezierVertex(-s * 0.9, -s * 0.2, -s * 1.05, s * 0.55, -s * 0.15, s * 0.75);
    bezierVertex(-s * 0.05, s * 0.45, -s * 0.05, s * 0.25, 0, 0);
    endShape(CLOSE);

    beginShape();
    vertex(0, 0);
    bezierVertex(s * 0.9, -s * 0.2, s * 1.05, s * 0.55, s * 0.15, s * 0.75);
    bezierVertex(s * 0.05, s * 0.45, s * 0.05, s * 0.25, 0, 0);
    endShape(CLOSE);

    // body
    fill(40, 34, 44, 130);
    ellipse(0, s * 0.22, s * 0.22, s * 0.72);

    pop();
  }
}

function addGrain() {
  // Film grain without pixel loops: layered tiny dots
  noStroke();
  for (let i = 0; i < 28000; i++) {
    let x = random(W);
    let y = random(H);
    let n = noise(x * 0.01, y * 0.01, 9.0);
    let a = 10 + 28 * n;
    fill(255, 255, 255, a * 0.18);
    rect(x, y, 1, 1);
  }

  // darker grain
  for (let i = 0; i < 18000; i++) {
    let x = random(W);
    let y = random(H);
    let n = noise(x * 0.013, y * 0.013, 4.0);
    let a = 8 + 24 * n;
    fill(0, 0, 0, a * 0.22);
    rect(x, y, 1, 1);
  }
}

function vignette() {
  // soft dark edges
  push();
  noFill();
  for (let i = 0; i < 24; i++) {
    let t = i / 23;
    let a = lerp(0, 120, t);
    stroke(0, 0, 0, a);
    strokeWeight(lerp(10, 90, t));
    rect(0, 0, W, H, 20);
  }
  pop();
}

function smoothstep(a, b, x) {
  let t = constrain((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
}

function polarToCartesian(a, rx, ry) {
  return { x: cos(a) * rx, y: sin(a) * ry };
}

// p5.js 1.11 - static painting, 1600x2000
// No external assets. No text/letters/numbers drawn.

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  drawBackground();
  drawMoon(1120, 290, 340);
  drawMist();
  drawHorizonAndGround();
  drawDoorGrave(width * 0.53, height * 0.73);
  drawTree(width * 0.20, height * 0.70, 780);
  drawCandle(width * 0.40, height * 0.82, 220);
  drawWiltedFlowers(width * 0.78, height * 0.84, 260);
  drawAsh();
  addVignette();
  addFilmGrain();
  addScratches();
}

function drawBackground() {
  // Deep night gradient
  let topC = color(10, 14, 24);
  let midC = color(17, 18, 28);
  let botC = color(12, 10, 12);

  for (let y = 0; y < height; y += 2) {
    let t = y / height;
    let c;
    if (t < 0.55) c = lerpColor(topC, midC, t / 0.55);
    else c = lerpColor(midC, botC, (t - 0.55) / 0.45);
    stroke(c);
    line(0, y, width, y);
  }

  // Subtle cold bloom at center upper-mid
  noStroke();
  for (let i = 0; i < 9; i++) {
    let a = 18 - i * 2;
    fill(120, 140, 170, a);
    ellipse(width * 0.55, height * 0.38, 980 + i * 120, 820 + i * 90);
  }
}

function drawMoon(cx, cy, r) {
  push();
  noStroke();

  // Halo
  for (let i = 0; i < 10; i++) {
    fill(210, 220, 230, 10 - i);
    ellipse(cx, cy, r * 2.2 + i * 55, r * 2.2 + i * 55);
  }

  // Irregular edge moon body
  let steps = 240;
  fill(210, 214, 216, 235);
  beginShape();
  for (let i = 0; i < steps; i++) {
    let ang = (TWO_PI * i) / steps;
    let n = noise(cos(ang) * 0.8 + 10.2, sin(ang) * 0.8 + 4.7);
    let rr = r * (0.98 + 0.06 * (n - 0.5));
    vertex(cx + cos(ang) * rr, cy + sin(ang) * rr);
  }
  endShape(CLOSE);

  // Terminator shadow (to feel like light is fading)
  fill(25, 28, 40, 70);
  ellipse(cx - r * 0.20, cy + r * 0.05, r * 1.65, r * 1.65);

  // Craters
  for (let i = 0; i < 26; i++) {
    let ang = random(TWO_PI);
    let rad = random(r * 0.10, r * 0.85);
    let x = cx + cos(ang) * rad;
    let y = cy + sin(ang) * rad;
    let cr = random(16, 60);
    let shade = random(170, 210);
    fill(shade, shade + 6, shade + 10, 85);
    ellipse(x, y, cr * 1.15, cr);
    fill(140, 150, 160, 35);
    ellipse(x + cr * 0.08, y + cr * 0.06, cr * 0.75, cr * 0.62);
  }
  pop();
}

function drawMist() {
  // Layered noise fog bands
  push();
  noStroke();
  let baseY = height * 0.58;
  for (let band = 0; band < 9; band++) {
    let y0 = baseY + band * 55;
    let amp = 35 + band * 5;
    let alpha = 32 - band * 2;
    let col = color(160, 175, 190, alpha);

    beginShape();
    fill(col);
    vertex(0, y0 + 220);
    for (let x = 0; x <= width; x += 10) {
      let n = noise(x * 0.002 + band * 0.7, band * 0.35 + 20.0);
      let y = y0 + (n - 0.5) * amp;
      vertex(x, y);
    }
    vertex(width, y0 + 220);
    endShape(CLOSE);
  }

  // Thin veil near bottom
  for (let k = 0; k < 4; k++) {
    fill(170, 185, 200, 18 - k * 3);
    ellipse(width * 0.55, height * 0.76, 1500 + k * 260, 520 + k * 120);
  }
  pop();
}

function drawHorizonAndGround() {
  push();
  noStroke();

  // Distant ridge
  fill(18, 18, 22, 240);
  let hy = height * 0.66;
  beginShape();
  vertex(0, height);
  vertex(0, hy + 120);
  for (let x = 0; x <= width; x += 18) {
    let n = noise(x * 0.003, 50.0);
    let y = hy + 40 + (n - 0.5) * 110;
    vertex(x, y);
  }
  vertex(width, hy + 120);
  vertex(width, height);
  endShape(CLOSE);

  // Foreground ground with subtle texture
  let gy = height * 0.75;
  fill(12, 10, 12, 245);
  beginShape();
  vertex(0, height);
  vertex(0, gy);
  for (let x = 0; x <= width; x += 16) {
    let n = noise(x * 0.004, 90.0);
    let y = gy + (n - 0.5) * 110;
    vertex(x, y);
  }
  vertex(width, gy);
  vertex(width, height);
  endShape(CLOSE);

  // Cold sheen on soil (like faint dew)
  blendMode(SCREEN);
  for (let i = 0; i < 10; i++) {
    fill(90, 120, 140, 7);
    ellipse(width * 0.52, height * 0.86, 1200 + i * 120, 520 + i * 70);
  }
  blendMode(BLEND);

  pop();
}

function drawDoorGrave(cx, cy) {
  push();

  // Mound
  noStroke();
  fill(20, 17, 18, 240);
  ellipse(cx, cy + 210, 860, 420);

  // Dark opening (a door/threshold)
  let w = 380;
  let h = 560;
  let x0 = cx - w * 0.5;
  let y0 = cy - h * 0.5 + 80;

  // Rim shadow
  fill(0, 0, 0, 120);
  rect(x0 - 18, y0 - 18, w + 36, h + 36, 18);

  // Inside darkness with depth
  fill(6, 6, 10, 240);
  rect(x0, y0, w, h, 14);

  // Inner gradient
  for (let i = 0; i < 70; i++) {
    let t = i / 69;
    let a = 50 * (1 - t);
    fill(40, 55, 70, a);
    rect(x0 + 10 + t * 22, y0 + 10 + t * 30, w - 20 - t * 44, h - 20 - t * 60, 12);
  }

  // Faint "retreating light" beam upward (cold, not hopeful)
  blendMode(SCREEN);
  for (let i = 0; i < 12; i++) {
    let a = 20 - i * 1.5;
    fill(140, 170, 190, a);
    let bw = 260 + i * 70;
    let bh = 820 + i * 90;
    ellipse(cx, y0 + h * 0.30, bw, bh);
  }
  blendMode(BLEND);

  // Soil clods around opening
  noStroke();
  for (let i = 0; i < 40; i++) {
    let ang = random(TWO_PI);
    let rr = random(220, 420);
    let px = cx + cos(ang) * rr;
    let py = cy + 210 + sin(ang) * rr * 0.25;
    let s = random(10, 32);
    fill(10, 8, 10, 210);
    ellipse(px, py, s * 1.4, s);
  }

  // A small, plain stone without inscription
  let sx = cx - 420;
  let sy = cy + 105;
  fill(28, 30, 34, 245);
  beginShape();
  vertex(sx - 85, sy + 180);
  vertex(sx - 70, sy + 40);
  vertex(sx - 25, sy - 20);
  vertex(sx + 30, sy - 35);
  vertex(sx + 70, sy + 20);
  vertex(sx + 80, sy + 180);
  endShape(CLOSE);

  // Stone highlight
  fill(120, 130, 140, 28);
  ellipse(sx - 10, sy + 60, 140, 230);

  pop();
}

function drawTree(x, y, h) {
  push();
  strokeCap(ROUND);
  strokeJoin(ROUND);

  // Trunk
  let base = createVector(x, y + 320);
  let top = createVector(x + 40, y - h * 0.45);

  for (let i = 0; i < 10; i++) {
    let t = i / 9;
    let sw = lerp(26, 6, t);
    stroke(22, 19, 20, 220);
    strokeWeight(sw);
    let cx1 = lerp(base.x, top.x, 0.35) - 120 + i * 2;
    let cy1 = lerp(base.y, top.y, 0.35) - 140;
    let cx2 = lerp(base.x, top.x, 0.7) + 120 - i * 2;
    let cy2 = lerp(base.y, top.y, 0.7) - 260;
    noFill();
    bezier(base.x, base.y, cx1, cy1, cx2, cy2, top.x, top.y);
  }

  // Branch generator
  function branch(px, py, ang, len, depth) {
    if (depth <= 0 || len < 35) return;
    let nx = px + cos(ang) * len;
    let ny = py + sin(ang) * len;

    let sw = map(depth, 1, 6, 2, 10);
    stroke(20, 18, 20, 220);
    strokeWeight(sw);
    line(px, py, nx, ny);

    // small twigs
    if (depth < 3) {
      for (let k = 0; k < 2; k++) {
        let ta = ang + random(-0.6, 0.6);
        let tl = len * random(0.22, 0.38);
        strokeWeight(max(1.2, sw * 0.4));
        line(nx, ny, nx + cos(ta) * tl, ny + sin(ta) * tl);
      }
    }

    let n1 = ang + random(-0.55, -0.15);
    let n2 = ang + random(0.15, 0.55);
    branch(nx, ny, n1, len * random(0.62, 0.78), depth - 1);
    branch(nx, ny, n2, len * random(0.62, 0.78), depth - 1);
    if (random() < 0.35) branch(nx, ny, ang + random(-0.25, 0.25), len * random(0.55, 0.7), depth - 1);
  }

  // Main branch root point
  let rootX = x + 30;
  let rootY = y - h * 0.15;
  branch(rootX, rootY, -PI * 0.55, 280, 6);
  branch(rootX + 30, rootY + 40, -PI * 0.35, 260, 5);
  branch(rootX - 10, rootY + 80, -PI * 0.75, 240, 5);

  // Ground roots
  stroke(16, 14, 15, 210);
  strokeWeight(8);
  for (let i = 0; i < 4; i++) {
    let rx = base.x + random(-60, 60);
    let ry = base.y + random(-20, 30);
    let ex = rx + random(-220, 220);
    let ey = ry + random(60, 160);
    bezier(rx, ry, rx + random(-80, 80), ry + random(40, 100), ex + random(-80, 80), ey + random(-40, 60), ex, ey);
  }

  pop();
}

function drawCandle(x, y, s) {
  push();
  noStroke();

  // wax body
  let w = s * 0.38;
  let h = s * 0.75;
  let x0 = x - w * 0.5;
  let y0 = y - h;

  // Shadow on ground
  fill(0, 0, 0, 90);
  ellipse(x + 40, y + 35, 260, 90);

  // Wax
  fill(220, 210, 200, 220);
  rect(x0, y0, w, h, 18);

  // Wax highlight
  fill(255, 255, 255, 40);
  rect(x0 + w * 0.12, y0 + 12, w * 0.22, h - 24, 14);

  // Melted lip
  fill(200, 190, 180, 210);
  ellipse(x, y0 + 12, w * 0.95, 34);

  // Wick (unlit)
  stroke(30, 28, 28, 220);
  strokeWeight(5);
  line(x, y0 - 10, x, y0 + 10);

  // Smoke
  noFill();
  stroke(170, 185, 200, 80);
  strokeWeight(6);
  beginShape();
  for (let i = 0; i < 60; i++) {
    let t = i / 59;
    let px = x + sin(t * 6.5) * (14 + 10 * (1 - t));
    let py = y0 - 20 - t * 250;
    curveVertex(px, py);
  }
  endShape();

  stroke(190, 200, 210, 35);
  strokeWeight(10);
  beginShape();
  for (let i = 0; i < 50; i++) {
    let t = i / 49;
    let px = x + sin(t * 5.1 + 0.8) * (22 + 14 * (1 - t));
    let py = y0 - 30 - t * 300;
    curveVertex(px, py);
  }
  endShape();

  pop();
}

function drawWiltedFlowers(x, y, scaleSize) {
  push();
  strokeCap(ROUND);
  strokeJoin(ROUND);

  // stems
  for (let i = 0; i < 4; i++) {
    let sx = x + i * 40 + random(-10, 10);
    let sy = y + random(-10, 10);
    let len = scaleSize * random(0.9, 1.15);
    let bend = random(-120, 120);

    stroke(35, 48, 40, 200);
    strokeWeight(7);
    noFill();
    beginShape();
    for (let k = 0; k < 26; k++) {
      let t = k / 25;
      let px = lerp(sx, sx + bend, t) + sin(t * 3.2 + i) * 14;
      let py = sy - t * len;
      curveVertex(px, py);
    }
    endShape();

    // drooping head
    let hx = sx + bend + random(-15, 15);
    let hy = sy - len + random(-10, 10);

    // dead petals
    noStroke();
    for (let p = 0; p < 10; p++) {
      let a = random(TWO_PI);
      let rr = random(18, 48);
      let px = hx + cos(a) * rr * 1.0;
      let py = hy + sin(a) * rr * 0.75 + 30;
      fill(85, 55, 55, 120);
      ellipse(px, py, random(14, 40), random(8, 22));
    }

    // center
    fill(35, 25, 25, 200);
    ellipse(hx, hy + 25, 34, 28);
  }

  // fallen petals on ground
  noStroke();
  for (let i = 0; i < 28; i++) {
    let px = x + random(-140, 120);
    let py = y + random(10, 120);
    fill(70, 45, 45, random(70, 130));
    ellipse(px, py, random(10, 34), random(6, 18));
  }

  pop();
}

function drawAsh() {
  push();
  noStroke();
  // ash particles drifting downward
  for (let i = 0; i < 520; i++) {
    let x = random(width);
    let y = random(height * 0.12, height * 0.98);
    let s = random(1.5, 5.5);
    let a = random(10, 50);
    fill(200, 210, 220, a);

    let drift = (noise(x * 0.003, y * 0.003) - 0.5) * 18;
    ellipse(x + drift, y, s * 1.2, s);
  }
  pop();
}

function addVignette() {
  push();
  noStroke();
  // soft vignette
  for (let i = 0; i < 10; i++) {
    let a = 18 + i * 6;
    fill(0, 0, 0, a);
    rect(i * 12, i * 12, width - i * 24, height - i * 24, 40);
  }
  pop();
}

function addFilmGrain() {
  // grain as sparse points, avoids heavy pixel loops
  push();
  blendMode(OVERLAY);
  strokeWeight(1);
  for (let i = 0; i < 180000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.01, y * 0.01);
    let a = 10 + 22 * n;
    stroke(210, 215, 220, a);
    point(x, y);
  }
  blendMode(BLEND);
  pop();
}

function addScratches() {
  push();
  blendMode(SOFT_LIGHT);
  strokeWeight(2);
  for (let i = 0; i < 28; i++) {
    let x = random(width);
    let y1 = random(-200, height * 0.2);
    let y2 = random(height * 0.8, height + 200);
    let wob = random(10, 35);
    stroke(220, 230, 240, random(10, 22));
    noFill();
    beginShape();
    for (let k = 0; k < 40; k++) {
      let t = k / 39;
      let xx = lerp(x, x + random(-wob, wob), t) + sin(t * 8 + i) * 6;
      let yy = lerp(y1, y2, t);
      curveVertex(xx, yy);
    }
    endShape();
  }
  blendMode(BLEND);
  pop();
}

// p5.js 1.11 — static painting, 1600×2000
let W = 1600, H = 2000;

function setup() {
  createCanvas(W, H);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  pixelDensity(2);
  background(10, 12, 16);

  drawSky();
  drawMoon();
  drawFarSilhouettes();
  drawMistBands();
  drawGround();
  drawGrave();
  drawStakeAndShroud();
  drawWiltedFlowers();
  drawMoths();
  addVignette();
  addGrain();
}

function draw() {}

// ---------- scene ----------
function drawSky() {
  // dusk gradient + subtle cloud noise
  noStroke();
  for (let y = 0; y < H; y++) {
    let t = y / H;
    let r = lerp(8, 28, pow(1 - t, 1.2));
    let g = lerp(10, 26, pow(1 - t, 1.2));
    let b = lerp(16, 38, pow(1 - t, 1.2));
    fill(r, g, b);
    rect(0, y, W, 1);
  }

  // cloud veils
  for (let i = 0; i < 900; i++) {
    let x = random(W);
    let y = random(H * 0.65);
    let s = random(120, 520);
    let n = noise(x * 0.0012, y * 0.0015);
    let a = map(n, 0, 1, 5, 28);
    fill(180, 195, 210, a);
    ellipse(x, y, s * 1.2, s * 0.55);
  }
}

function drawMoon() {
  // eclipsed / veiled moon
  push();
  let cx = W * 0.72, cy = H * 0.18;
  noStroke();

  // glow
  for (let i = 10; i >= 1; i--) {
    let a = 10 + i * 2.2;
    fill(210, 220, 235, a);
    ellipse(cx, cy, 320 + i * 55, 320 + i * 55);
  }

  // moon disk
  fill(218, 224, 232, 180);
  ellipse(cx, cy, 280, 280);

  // shadow bite (death as absence)
  fill(10, 12, 16, 230);
  ellipse(cx + 70, cy + 10, 250, 250);

  // thin mist across it
  for (let i = 0; i < 80; i++) {
    let y = cy - 120 + i * 3.0;
    let xoff = noise(i * 0.12) * 60;
    stroke(210, 220, 235, 10);
    strokeWeight(10);
    line(cx - 220 - xoff, y, cx + 220 + xoff, y);
  }
  pop();
}

function drawFarSilhouettes() {
  // far ridge + dead trees as thin silhouettes
  push();
  noStroke();

  let horizon = H * 0.58;
  fill(8, 9, 12, 255);
  beginShape();
  vertex(0, horizon + 120);
  for (let x = 0; x <= W; x += 30) {
    let n = noise(x * 0.002);
    let y = horizon + 80 + n * 110;
    vertex(x, y);
  }
  vertex(W, horizon + 260);
  vertex(W, H);
  vertex(0, H);
  endShape(CLOSE);

  // distant trees
  for (let i = 0; i < 26; i++) {
    let x = random(W);
    let baseY = horizon + 60 + noise(x * 0.003) * 140;
    let h = random(120, 320);
    drawDeadTree(x, baseY, h, 1.5, color(12, 13, 16, 190));
  }
  pop();
}

function drawMistBands() {
  // horizontal fog layers
  push();
  let top = H * 0.34;
  let bottom = H * 0.78;
  for (let k = 0; k < 18; k++) {
    let y = lerp(top, bottom, k / 17);
    let a = map(k, 0, 17, 16, 42);
    let thick = map(k, 0, 17, 26, 90);

    noFill();
    stroke(200, 210, 220, a);
    strokeWeight(thick);
    beginShape();
    for (let x = -120; x <= W + 120; x += 40) {
      let n = noise(x * 0.0016, y * 0.003, k * 0.08);
      let yy = y + (n - 0.5) * 90;
      curveVertex(x, yy);
    }
    endShape();
  }
  pop();
}

function drawGround() {
  // near ground texture
  push();
  let gy = H * 0.62;

  // base
  noStroke();
  fill(18, 16, 18);
  rect(0, gy, W, H - gy);

  // soil gradients
  for (let y = gy; y < H; y++) {
    let t = (y - gy) / (H - gy);
    let r = lerp(20, 10, t);
    let g = lerp(17, 9, t);
    let b = lerp(19, 10, t);
    fill(r, g, b, 130);
    rect(0, y, W, 1);
  }

  // clumps / pebbles
  noStroke();
  for (let i = 0; i < 1800; i++) {
    let x = random(W);
    let y = random(gy, H);
    let n = noise(x * 0.01, y * 0.01);
    let s = map(n, 0, 1, 1, 9);
    let a = map(n, 0, 1, 20, 90);
    fill(0, 0, 0, a);
    ellipse(x, y, s, s * random(0.7, 1.4));
  }

  // subtle reddish clay hints (life/iron/blood memory)
  for (let i = 0; i < 500; i++) {
    let x = random(W);
    let y = random(gy + 120, H);
    let s = random(10, 60);
    fill(70, 35, 30, 10);
    ellipse(x, y, s * 1.2, s * 0.6);
  }
  pop();
}

function drawGrave() {
  // open grave, slightly off-center
  push();
  let cx = W * 0.46;
  let cy = H * 0.80;
  let w = 720;
  let h = 360;

  // pit rim (perspective)
  noStroke();
  fill(26, 22, 24, 220);
  beginShape();
  vertex(cx - w * 0.55, cy - h * 0.25);
  vertex(cx + w * 0.55, cy - h * 0.18);
  vertex(cx + w * 0.38, cy + h * 0.25);
  vertex(cx - w * 0.62, cy + h * 0.18);
  endShape(CLOSE);

  // inner darkness
  fill(6, 7, 10, 255);
  beginShape();
  vertex(cx - w * 0.42, cy - h * 0.15);
  vertex(cx + w * 0.44, cy - h * 0.10);
  vertex(cx + w * 0.30, cy + h * 0.18);
  vertex(cx - w * 0.48, cy + h * 0.12);
  endShape(CLOSE);

  // depth strokes
  for (let i = 0; i < 70; i++) {
    let t = i / 69;
    let x1 = lerp(cx - w * 0.40, cx - w * 0.46, t);
    let y1 = lerp(cy - h * 0.12, cy + h * 0.12, t);
    let x2 = lerp(cx + w * 0.42, cx + w * 0.28, t);
    let y2 = lerp(cy - h * 0.10, cy + h * 0.18, t);
    stroke(20, 22, 30, 18);
    strokeWeight(4);
    line(x1, y1, x2, y2);
  }

  // thrown soil mound
  noStroke();
  fill(14, 12, 14, 255);
  let mx = cx + w * 0.56;
  let my = cy + h * 0.20;
  beginShape();
  vertex(mx - 140, my + 130);
  for (let a = 0; a <= PI; a += PI / 26) {
    let rx = 210 + 35 * noise(a * 1.8);
    let ry = 120 + 30 * noise(20 + a * 1.3);
    vertex(mx + cos(a + PI) * rx, my + sin(a + PI) * ry);
  }
  vertex(mx + 200, my + 160);
  vertex(mx - 140, my + 130);
  endShape(CLOSE);

  // loose clods
  for (let i = 0; i < 520; i++) {
    let x = random(mx - 260, mx + 260);
    let y = random(my - 90, my + 190);
    let n = noise(x * 0.01, y * 0.012);
    let s = map(n, 0, 1, 1.5, 10);
    fill(0, 0, 0, map(n, 0, 1, 25, 95));
    ellipse(x, y, s, s * random(0.6, 1.3));
  }
  pop();
}

function drawStakeAndShroud() {
  // a stake with an empty shroud/coat: presence without body
  push();
  let baseX = W * 0.28;
  let baseY = H * 0.73;

  // stake
  stroke(32, 26, 24, 255);
  strokeWeight(18);
  line(baseX, baseY + 360, baseX + 18, baseY - 260);

  // rough bark highlights
  for (let i = 0; i < 120; i++) {
    let t = i / 119;
    let x = lerp(baseX + 2, baseX + 18, t) + (noise(i * 0.2) - 0.5) * 10;
    let y = lerp(baseY + 350, baseY - 260, t);
    stroke(80, 64, 55, 60);
    strokeWeight(2);
    line(x - 6, y, x + 6, y + random(-3, 3));
  }

  // crossbar
  stroke(30, 24, 22, 255);
  strokeWeight(14);
  line(baseX - 210, baseY - 120, baseX + 200, baseY - 150);

  // shroud shape
  noStroke();
  let cloth = color(210, 212, 216, 190);
  let shadow = color(18, 18, 22, 120);

  // outer cloth
  fill(cloth);
  beginShape();
  vertex(baseX - 170, baseY - 140);
  bezierVertex(baseX - 300, baseY - 40, baseX - 260, baseY + 140, baseX - 140, baseY + 260);
  bezierVertex(baseX - 30, baseY + 370, baseX + 120, baseY + 340, baseX + 160, baseY + 210);
  bezierVertex(baseX + 240, baseY + 40, baseX + 270, baseY - 60, baseX + 150, baseY - 155);
  bezierVertex(baseX + 80, baseY - 215, baseX - 80, baseY - 230, baseX - 170, baseY - 140);
  endShape(CLOSE);

  // inner hollow (where body is missing)
  fill(12, 12, 16, 190);
  beginShape();
  vertex(baseX - 70, baseY - 80);
  bezierVertex(baseX - 160, baseY + 30, baseX - 130, baseY + 170, baseX - 50, baseY + 240);
  bezierVertex(baseX + 20, baseY + 300, baseX + 85, baseY + 260, baseX + 90, baseY + 185);
  bezierVertex(baseX + 100, baseY + 70, baseX + 110, baseY + 10, baseX + 40, baseY - 90);
  bezierVertex(baseX + 10, baseY - 120, baseX - 35, baseY - 120, baseX - 70, baseY - 80);
  endShape(CLOSE);

  // folds
  for (let i = 0; i < 90; i++) {
    let t = i / 89;
    let x = lerp(baseX - 170, baseX + 150, t);
    let y = baseY - 140 + noise(40 + t * 3.2) * 420;
    let len = 70 + noise(90 + t * 5.1) * 210;
    stroke(255, 255, 255, 22);
    strokeWeight(2);
    line(x, y, x + len * 0.15, y + len);
  }

  // shadow cast on ground
  noStroke();
  for (let i = 0; i < 18; i++) {
    let a = 22 - i * 1.0;
    fill(red(shadow), green(shadow), blue(shadow), a);
    ellipse(baseX + 80, baseY + 420, 520 + i * 70, 180 + i * 22);
  }
  pop();
}

function drawWiltedFlowers() {
  // lilies around grave: beauty after life
  push();
  let gy = H * 0.62;

  for (let i = 0; i < 14; i++) {
    let x = random(W * 0.10, W * 0.92);
    let y = random(gy + 120, H - 90);
    let s = random(0.8, 1.4);
    let tilt = random(-0.9, 0.9);
    drawWiltedLily(x, y, s, tilt);
  }

  // petals drifting to soil
  for (let i = 0; i < 180; i++) {
    let x = random(W * 0.12, W * 0.92);
    let y = random(gy + 40, H - 40);
    let a = random(TWO_PI);
    let w = random(10, 30);
    let h = w * random(0.4, 1.1);
    fill(215, 215, 220, random(30, 90));
    noStroke();
    push();
    translate(x, y);
    rotate(a);
    ellipse(0, 0, w, h);
    pop();
  }
  pop();
}

function drawMoths() {
  // pale moths as fragile transitions
  push();
  for (let i = 0; i < 28; i++) {
    let x = random(W * 0.08, W * 0.95);
    let y = random(H * 0.10, H * 0.70);
    let s = random(0.55, 1.2);
    let ang = random(-0.6, 0.6);
    drawMoth(x, y, s, ang);
  }
  pop();
}

// ---------- primitives ----------
function drawDeadTree(x, y, h, w, col) {
  push();
  stroke(col);
  strokeWeight(w);
  noFill();

  let trunkTopX = x + (noise(x * 0.01) - 0.5) * 40;
  let trunkTopY = y - h;

  // trunk
  beginShape();
  for (let i = 0; i <= 18; i++) {
    let t = i / 18;
    let xx = lerp(x, trunkTopX, t) + (noise(x * 0.01, t * 3) - 0.5) * 30 * (1 - t);
    let yy = lerp(y, trunkTopY, t);
    curveVertex(xx, yy);
  }
  endShape();

  // branches
  let nB = int(random(4, 8));
  for (let b = 0; b < nB; b++) {
    let t0 = random(0.15, 0.75);
    let bx = lerp(x, trunkTopX, t0);
    let by = lerp(y, trunkTopY, t0);
    let dir = random([-1, 1]);
    let bl = random(h * 0.18, h * 0.45);
    let ex = bx + dir * bl;
    let ey = by - bl * random(0.4, 0.9);

    strokeWeight(max(0.8, w * random(0.6, 1.2)));
    beginShape();
    for (let i = 0; i <= 10; i++) {
      let t = i / 10;
      let xx = lerp(bx, ex, t) + (noise(100 + b * 10 + t * 2) - 0.5) * 18 * (1 - t);
      let yy = lerp(by, ey, t) + (noise(200 + b * 10 + t * 2) - 0.5) * 12;
      curveVertex(xx, yy);
    }
    endShape();
  }
  pop();
}

function drawWiltedLily(x, y, s, tilt) {
  push();
  translate(x, y);
  rotate(tilt);

  // stem
  stroke(55, 62, 52, 170);
  strokeWeight(5 * s);
  noFill();
  beginShape();
  for (let i = 0; i <= 14; i++) {
    let t = i / 14;
    let xx = (noise(30 + t * 2) - 0.5) * 26 * s;
    let yy = -t * 220 * s;
    curveVertex(xx, yy);
  }
  endShape();

  // leaf
  noStroke();
  fill(50, 56, 48, 110);
  push();
  translate(-12 * s, -120 * s);
  rotate(-0.4);
  ellipse(0, 0, 22 * s, 110 * s);
  pop();

  // flower head (drooping)
  translate(0, -220 * s);
  rotate(0.9);

  // petals
  for (let k = 0; k < 6; k++) {
    push();
    rotate(k * TWO_PI / 6 + random(-0.08, 0.08));
    let pr = 70 * s;
    let pw = 36 * s;
    let ph = 92 * s;

    // petal fill (cold, bruised)
    let base = color(212, 214, 220, 140);
    fill(base);
    noStroke();
    beginShape();
    vertex(0, 0);
    bezierVertex(pw, -ph * 0.15, pw * 0.6, -ph * 0.95, 0, -ph);
    bezierVertex(-pw * 0.6, -ph * 0.95, -pw, -ph * 0.15, 0, 0);
    endShape(CLOSE);

    // bruising edge
    stroke(95, 80, 82, 55);
    strokeWeight(2 * s);
    noFill();
    arc(0, -ph * 0.72, pw * 1.7, ph * 0.8, -PI * 0.9, -PI * 0.1);
    pop();
  }

  // center
  noStroke();
  fill(60, 48, 42, 160);
  ellipse(0, -20 * s, 28 * s, 18 * s);

  // fallen pollen dots
  for (let i = 0; i < 20; i++) {
    fill(120, 95, 60, random(25, 70));
    ellipse(random(-18, 18) * s, random(-55, -5) * s, random(2, 5) * s);
  }

  pop();
}

function drawMoth(x, y, s, ang) {
  push();
  translate(x, y);
  rotate(ang);

  // glow halo
  noStroke();
  for (let i = 7; i >= 1; i--) {
    fill(220, 230, 240, 6 + i * 2);
    ellipse(0, 0, (70 + i * 26) * s, (38 + i * 16) * s);
  }

  // wings
  stroke(230, 235, 242, 70);
  strokeWeight(1.5 * s);
  fill(225, 230, 236, 55);
  beginShape();
  vertex(0, 0);
  bezierVertex(-60 * s, -25 * s, -90 * s, 10 * s, -70 * s, 40 * s);
  bezierVertex(-45 * s, 62 * s, -18 * s, 35 * s, 0, 10 * s);
  endShape(CLOSE);

  beginShape();
  vertex(0, 0);
  bezierVertex(60 * s, -25 * s, 90 * s, 10 * s, 70 * s, 40 * s);
  bezierVertex(45 * s, 62 * s, 18 * s, 35 * s, 0, 10 * s);
  endShape(CLOSE);

  // body
  noStroke();
  fill(30, 32, 40, 150);
  ellipse(0, 18 * s, 10 * s, 34 * s);

  // wing speckles (like dust/ash)
  for (let i = 0; i < 30; i++) {
    let px = random(-70, 70) * s;
    let py = random(-10, 60) * s;
    let d = dist(px, py, 0, 20 * s);
    if (d < 85 * s) {
      fill(250, 250, 252, random(12, 40));
      ellipse(px, py, random(2, 6) * s);
    }
  }

  pop();
}

function addVignette() {
  // darken edges, focusing on grave & shroud
  push();
  noStroke();
  for (let i = 0; i < 22; i++) {
    let t = i / 21;
    let a = lerp(0, 160, t);
    fill(0, 0, 0, a);
    rect(-40 + i * 10, -40 + i * 10, W + 80 - i * 20, H + 80 - i * 20, 120);
  }
  pop();
}

function addGrain() {
  // film grain: stippled points (no text)
  push();
  noStroke();
  let n = 65000;
  for (let i = 0; i < n; i++) {
    let x = random(W);
    let y = random(H);
    let t = noise(x * 0.006, y * 0.006);
    let a = map(t, 0, 1, 6, 28);
    let c = (random() < 0.5) ? 255 : 0;
    fill(c, c, c, a);
    rect(x, y, 1, 1);
  }

  // occasional scratches
  for (let i = 0; i < 24; i++) {
    let x = random(W);
    let y1 = random(H * 0.05, H * 0.95);
    let y2 = y1 + random(120, 560);
    stroke(255, 255, 255, 10);
    strokeWeight(random(1, 3));
    line(x, y1, x + random(-10, 10), y2);
  }
  pop();
}

