function drawSky() {
  let topC = color(5, 7, 13);
  let midC = color(28, 31, 39);
  let lowC = color(73, 65, 60);
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let c = t < 0.55
      ? lerpColor(topC, midC, t / 0.55)
      : lerpColor(midC, lowC, (t - 0.55) / 0.45);
    stroke(c);
    line(0, y, width, y);
  }

  noStroke();
  for (let i = 0; i < 260; i++) {
    let x = random(width);
    let y = random(0, 980);
    let s = random(90, 430);
    let a = random(5, 18);
    fill(20 + random(25), 22 + random(20), 28 + random(25), a);
    ellipse(x, y, s * random(1.1, 2.4), s * random(0.18, 0.55));
  }

  for (let i = 0; i < 1300; i++) {
    let x = random(width);
    let y = random(0, 1200);
    let n = noise(x * 0.002, y * 0.003);
    if (n > 0.47) {
