function radialGlow(cx, cy, r, c, a, steps) {
  noStroke();
  for (let i = steps; i > 0; i--) {
    let t = i / steps;
    let alpha = a * pow(1 - t, 1.5);
    fill(red(c), green(c), blue(c), alpha);
    circle(cx, cy, r * 2 * t);
  }
}

