function riverCenter(t) {
  return 800 + 24 * sin(t * PI * 2.1);
}

function riverHalf(t) {
  return lerp(100, 735, pow(t, 0.95));
}

function riverLeftAtY(y) {
  let t = constrain((y - 850) / 1150, 0, 1);
  return riverCenter(t) - riverHalf(t);
}

function riverRightAtY(y) {
  let t = constrain((y - 850) / 1150, 0, 1);
  return riverCenter(t) + riverHalf(t);
}

function drawRiver() {
  noStroke();
  fill(4, 7, 12, 245);
  beginShape();
  for (let i = 0; i <= 80; i++) {
    let t = i / 80;
    let y = lerp(850, 2000, t);
    vertex(riverLeftAtY(y), y);
  }
  for (let i = 80; i >= 0; i--) {
    let t = i / 80;
    let y = lerp(850, 2000, t);
    vertex(riverRightAtY(y), y);
  }
  endShape(CLOSE);

  for (let i = 0; i < 280; i++) {
    let t = random();
    let y = lerp(860, 1990, t);
    let l = riverLeftAtY(y);
    let r = riverRightAtY(y);
    let x1 = random(l + 15, r - 15);
    let len = random(35, 260) * (0.25 + t);
    stroke(95, 103, 112, random(12, 42));
    strokeWeight(random(1, 4));
    line(x1, y, constrain(x1 + len, l, r), y + random(-6, 6));
  }

  for (let i = 0; i < 80; i++) {
    let y = random(900, 1600);
    let t = constrain((y - 850) / 1150, 0, 1);
    let cx = riverCenter(t) + random(-20, 20);
    let w = random(20, 180) * (1 - t * 0.35);
    stroke(210, 204, 175, random(10, 45));
    strokeWeight(random(1, 5));
    line(cx - w, y, cx + w, y + random(-4, 4));
  }

  noStroke();
  for (let i = 0; i < 24; i++) {
    fill(210, 203, 176, 8);
    ellipse(800 + random(-35, 35), 470 + i * 24, random(30, 170), random(3, 16));
  }

  stroke(68, 64, 58, 110);
  strokeWeight(3);
  for (let y = 880; y < 1990; y += 26) {
    line(riverLeftAtY(y), y, riverLeftAtY(y + 18), y + 18);
    line(riverRightAtY(y), y, riverRightAtY(y + 18), y + 18);
  }
}

function drawShores() {
  noStroke();
  fill(31, 27, 24, 220);
  beginShape();
  vertex(0, 910);
  for (let y = 910; y <= 2000; y += 40) vertex(riverLeftAtY(y), y);
  vertex(0, 2000);
  endShape(CLOSE);

  fill(34, 29, 25, 220);
  beginShape();
  vertex(width, 910);
  for (let y = 910; y <= 2000; y += 40) vertex(riverRightAtY(y), y);
  vertex(width, 2000);
  endShape(CLOSE);

  for (let i = 0; i < 5600; i++) {
    let y = random(930, 1995);
    let l = riverLeftAtY(y);
    let r = riverRightAtY(y);
    let side = random() < 0.5;
    let x = side ? random(0, max(0, l - 8)) : random(min(width, r + 8), width);
    let h = random(14, 80);
    let lean = side ? random(-12, 28) : random(-28, 12);
    stroke(random(55, 95), random(50, 77), random(42, 58), random(35, 115));
    strokeWeight(random(0.7, 2.5));
    line(x, y, x + lean, y - h);
  }

  for (let i = 0; i < 800; i++) {
    let y = random(970, 1990);
    let l = riverLeftAtY(y);
    let r = riverRightAtY(y);
    let x = random() < 0.5 ? random(0, l - 5) : random(r + 5, width);
    stroke(140, 135, 118, random(10, 42));
    strokeWeight(random(1, 3));
    point(x, y);
  }
}

