function branch(x, y, a, len, w, d) {
  let nx = x + cos(a) * len;
  let ny = y + sin(a) * len;
  stroke(9 + d * 2, 7 + d, 6, 230);
  strokeWeight(max(1, w));
  line(x, y, nx, ny);

  if (d <= 0 || len < 18) {
    stroke(65, 60, 52, 120);
    strokeWeight(1);
    point(nx, ny);
    return;
  }

  let count = d > 4 ? 3 : 2;
  for (let i = 0; i < count; i++) {
    let na = a + random(-0.72, 0.72) + (i - 1) * 0.18;
    let nl = len * random(0.52, 0.78);
    let nw = w * random(0.50, 0.68);
    branch(nx, ny, na, nl, nw, d - 1);
  }

  if (random() < 0.45) {
    let px = lerp(x, nx, random(0.25, 0.85));
    let py = lerp(y, ny, random(0.25, 0.85));
    branch(px, py, a + random(-1.2, 1.2), len * random(0.25, 0.45), w * 0.42, d - 2);
  }
}

