function riverLeftX(y) {
  let t = map(y, 920, 2000, 0, 1);
  return lerp(650, 170, t) + sin(y * 0.009) * 40;
}

function riverRightX(y) {
  let t = map(y, 920, 2000, 0, 1);
  return lerp(920, 1450, t) + sin(y * 0.007 + 2.4) * 55;
}

function drawRiver() {
  noStroke();
  beginShape();
  for (let y = 920; y <= height; y += 20) vertex(riverLeftX(y), y);
  for (let y = height; y >= 920; y -= 20) vertex(riverRightX(y), y);
  endShape(CLOSE);

  for (let y = 920; y < height; y += 2) {
    let t = map(y, 920, height, 0, 1);
    stroke(18 + 12 * t, 22 + 14 * t, 30 + 20 * t, 220);
    line(riverLeftX(y), y, riverRightX(y), y);
  }

  for (let i = 0; i < 900; i++) {
    let y = random(930, height);
    let lx = riverLeftX(y);
    let rx = riverRightX(y);
    let x = random(lx, rx);
    let w = random(20, 180) * map(y, 930, height, 0.3, 1.2);
    stroke(150, 165, 175, random(8, 38));
    strokeWeight(random(1, 4));
    line(x - w * 0.5, y, x + w * 0.5, y + random(-2, 2));
  }

  for (let i = 0; i < 260; i++) {
    let y = random(980, height);
    let lx = riverLeftX(y);
    let rx = riverRightX(y);
    let x = random(lx, rx);
    fill(200, 210, 205, random(4, 22));
    noStroke();
