function drawDeadTree() {
  push();
  translate(270, 1180);
  strokeCap(ROUND);

  stroke(10, 9, 8, 245);
  strokeWeight(42);
  line(0, 360, 45, 30);
  strokeWeight(30);
  line(45, 30, 35, -270);

  function branch(x, y, len, ang, thick, depth) {
    if (depth <= 0 || thick < 2) return;
    stroke(10, 9, 8, 235);
    strokeWeight(thick);
    let x2 = x + cos(ang) * len;
    let y2 = y + sin(ang) * len;
    line(x, y, x2, y2);

    let n = floor(random(2, 4));
    for (let i = 0; i < n; i++) {
      let na = ang + random(-0.9, 0.9);
      let nl = len * random(0.45, 0.75);
      branch(x2, y2, nl, na, thick * random(0.45, 0.68), depth - 1);
    }
  }

  branch(35, -260, 230, -2.55, 18, 5);
  branch(35, -230, 280, -1.5, 15, 5);
  branch(40, -190, 250, -0.55, 16, 5);
  branch(30, -70, 210, 0.05, 13, 4);
  branch(18, 20, 190, -3.05, 12, 4);

  stroke(8, 7, 6, 230);
  for (let i = 0; i < 16; i++) {
    strokeWeight(random(8, 18));
    let a = random(2.55, 3.85);
    line(28, 340, cos(a) * random(100, 260), 360 + sin(a) * random(40, 100));
  }

  pop();
}

