function drawSky() {
  noStroke();
  let topC = color(5, 7, 18);
  let midC = color(29, 28, 55);
  let lowC = color(92, 65, 66);
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let c;
    if (t < 0.55) {
      c = lerpColor(topC, midC, t / 0.55);
    } else {
      c = lerpColor(midC, lowC, (t - 0.55) / 0.45);
    }
    stroke(c);
    line(0, y, width, y);
  }

  blendMode(ADD);
  for (let i = 0; i < 4200; i++) {
    let x = random(width);
    let y = random(height * 0.72);
    let n = noise(x * 0.002, y * 0.002);
    let a = map(n, 0, 1, 2, 17);
    stroke(90 + random(50), 85 + random(55), 120 + random(80), a);
    strokeWeight(random(0.4, 2.4));
    point(x, y);
  }
  blendMode(BLEND);
}

