function drawTrunk(x, y, len, ang, sw) {
  stroke(5, 6, 12, 232);
  strokeWeight(sw);
  let nx = x + cos(ang) * len;
  let ny = y + sin(ang) * len;
  line(x, y, nx, ny);

  stroke(19, 15, 19, 105);
  strokeWeight(sw * 0.28);
  line(x + sw * 0.12, y, nx + sw * 0.06, ny);

  branch(nx, ny, len * 0.44, ang - random(0.55, 0.95), sw * 0.48, 0);
  branch(nx, ny, len * 0.42, ang + random(0.52, 0.95), sw * 0.45, 0);
  branch(x + cos(ang) * len * 0.58, y + sin(ang) * len * 0.58, len * 0.36, ang + random(0.35, 0.75), sw * 0.38, 0);
}

function branch(x, y, len, ang, sw, depth) {
  if (len < 18 || sw < 1.1 || depth > 7) return;
  let nx = x + cos(ang) * len;
  let ny = y + sin(ang) * len;
  stroke(5, 6, 12, 225);
  strokeWeight(sw);
  line(x, y, nx, ny);

  if (random() < 0.92) branch(nx, ny, len * random(0.58, 0.78), ang - random(0.22, 0.62), sw * 0.67, depth + 1);
  if (random() < 0.84) branch(nx, ny, len * random(0.50, 0.72), ang + random(0.25, 0.70), sw * 0.62, depth + 1);
  if (random() < 0.28) branch(nx, ny, len * random(0.35, 0.55), ang + random(-0.22, 0.22), sw * 0.50, depth + 1);
}

