function drawSky() {
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(9, 44, pow(t, 1.7));
    let g = lerp(12, 42, pow(t, 1.45));
    let b = lerp(25, 50, pow(t, 1.15));
    stroke(r, g, b);
    line(0, y, width, y);
  }

  noStroke();
  for (let i = 0; i < 8500; i++) {
    let x = random(width);
    let y = random(height * 0.72);
    let n = noise(x * 0.003, y * 0.004);
    let a = map(n, 0, 1, 0, 38) * (1 - y / 1600);
