const W = 1600;
const H = 2000;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
  drawPainting();
}

function drawPainting() {
  background(5, 6, 12);
  drawSky();
  drawMoon();
  drawDistantFog();
  drawDistantShore();
  drawWater();
  drawTrees();
  drawBoat();
  drawForeground();
  addGrain();
}

function drawSky() {
  for (let y = 0; y < H; y += 2) {
    let t = y / H;
    let c1 = color(5, 7, 17);
    let c2 = color(31, 22, 42);
    let c3 = color(10, 11, 17);
    let c = t < 0.55
      ? lerpColor(c1, c2, t / 0.55)
      : lerpColor(c2, c3, (t - 0.55) / 0.45);
    stroke(c);
    strokeWeight(2);
    line(0, y, W, y);
  }

  noStroke();
  for (let i = 0; i < 9000; i++) {
    let x = random(W);
    let y = random(0, 1120);
    let n = noise(x * 0.004, y * 0.004);
    let a = map(n, 0, 1, 0, 28);
    fill(120, 118, 135, a);
    ellipse(x, y, random(0.6, 2.4), random(0.6, 2.4));
  }

  for (let i = 0; i < 180; i++) {
    let x = random(W);
    let y = random(40, 850);
    let s = random(1, 3.5);
    let a = random(18, 65);
    fill(210, 214, 215, a);
    ellipse(x, y, s, s);
  }
}

function drawMoon() {
  push();
  translate(800, 360);

  noStroke();
  for (let r = 390; r > 210; r -= 18) {
    fill(206, 209, 199, map(r, 390, 210, 3, 20));
    ellipse(0, 0, r, r);
  }

  fill(218, 218, 204, 235);
  ellipse(0, 0, 330, 330);

  for (let i = 0; i < 80; i++) {
    let a = random(TWO_PI);
    let rr = random(15, 155);
    let x = cos(a) * rr;
    let y = sin(a) * rr;
    let s = random(8, 38);
    fill(132, 130, 126, random(10, 28));
    ellipse(x, y, s, s * random(0.6, 1.2));
  }

  fill(7, 8, 15, 238);
  ellipse(72, -34, 332, 332);

  noFill();
  stroke(226, 224, 207, 95);
  strokeWeight(5);
  arc(0, 0, 334, 334, HALF_PI + 0.35, PI + HALF_PI - 0.25);

  pop();
}

function drawDistantFog() {
  push();
  noFill();

  for (let band = 0; band < 9; band++) {
    let y = 820 + band * 45;
    stroke(176, 174, 171, 16 + band * 4);
    strokeWeight(20 + band * 5);
    beginShape();
    for (let x = -100; x <= W + 100; x += 60) {
      let yy = y + noise(x * 0.004, band * 2.8) * 45 - 20;
      curveVertex(x, yy);
    }
    endShape();
  }

  for (let band = 0; band < 6; band++) {
    let y = 1040 + band * 24;
    stroke(225, 219, 202, 14);
    strokeWeight(10);
    beginShape();
    for (let x = -100; x <= W + 100; x += 50) {
      let yy = y + noise(x * 0.008, 20 + band) * 26 - 13;
      curveVertex(x, yy);
    }
    endShape();
  }

  pop();
}

function drawDistantShore() {
  push();
  noStroke();
  fill(8, 9, 13, 230);
