function drawWater() {
  push();

  for (let y = 1040; y < H; y += 2) {
    let t = map(y, 1040, H, 0, 1);
    let c = lerpColor(color(8, 10, 17), color(2, 3, 7), t);
    stroke(c);
    strokeWeight(2);
    line(0, y, W, y);
  }

  noStroke();
  for (let i = 0; i < 1200; i++) {
    let y = random(1070, 1940);
    let t = map(y, 1070, 1940, 0, 1);
    let x = random(W);
    let len = random(30, 190) * (1.1 - t * 0.55);
    let a = random(8, 45) * (1 - t * 0.35);
    stroke(97, 104, 119, a);
    strokeWeight(random(1, 4));
    noFill();
    beginShape();
    for (let k = 0; k < 5; k++) {
      let xx = x + k * len / 4;
      let yy = y + sin(k * 1.7 + i) * random(0.5, 4);
      curveVertex(xx, yy);
    }
    endShape();
  }

  for (let i = 0; i < 180; i++) {
    let y = random(1000, 1690);
    let t = map(y, 1000, 1690, 0, 1);
    let w = map(t, 0, 1, 140, 500);
    let x = 800 + random(-w * 0.5, w * 0.5);
    let len = random(25, 135) * (1 - t * 0.35);
    let a = random(12, 70) * (1 - t * 0.4);
    stroke(205, 203, 185, a);
    strokeWeight(random(1.5, 5));
    line(x - len * 0.5, y, x + len * 0.5, y + random(-2, 2));
  }

  fill(2, 3, 6, 80);
  rect(0, 1680, W, 320);

  pop();
}

function drawTrees() {
  push();
  drawDeadTree(95, 1160, 1.1, 1);
  drawDeadTree(1510, 1190, 1.0, -1);
  drawThinBranches();
  pop();
}

function drawDeadTree(x, y, s, flip) {
  push();
  translate(x, y);
  scale(flip * s, s);
  stroke(2, 3, 5, 245);
  noFill();

  strokeWeight(38);
  beginShape();
  curveVertex(0, 0);
  curveVertex(0, 0);
  curveVertex(20, -180);
  curveVertex(-30, -390);
  curveVertex(15, -640);
  curveVertex(-20, -880);
  endShape();

  strokeWeight(24);
  branchCurve(5, -300, 180, -120, 370, -210, 530, -390);
  branchCurve(-10, -460, -135, -550, -250, -650, -370, -820);
  branchCurve(2, -620, 125, -690, 255, -785, 360, -950);
  branchCurve(-5, -760, -80, -850, -130, -970, -110, -1120);

  strokeWeight(14);
  branchCurve(270, -245, 350, -310, 430, -350, 520, -360);
  branchCurve(390, -390, 465, -475, 545, -540, 630, -650);
  branchCurve(-225, -650, -330, -710, -440, -765, -560, -860);
  branchCurve(210, -800, 330, -850, 435, -930, 535, -1060);

  strokeWeight(7);
  for (let i = 0; i < 36; i++) {
    let bx = random(-420, 520);
    let by = random(-1030, -360);
    let ex = bx + random(45, 160) * (random() < 0.5 ? -1 : 1);
    let ey = by - random(40, 170);
    branchCurve(bx, by, lerp(bx, ex, 0.35), by - random(40, 90), lerp(bx, ex, 0.7), ey + random(10, 70), ex, ey);
  }

  pop();
}

function branchCurve(x1, y1, x2, y2, x3, y3, x4, y4) {
  beginShape();
  curveVertex(x1, y1);
  curveVertex(x1, y1);
  curveVertex(x2, y2);
  curveVertex(x3, y3);
  curveVertex(x4, y4);
  curveVertex(x4, y4);
  endShape();
}

function drawThinBranches() {
  stroke(1, 2, 4, 180);
  noFill();

  for (let i = 0; i < 70; i++) {
    let side = random() < 0.5 ? 0 : W;
    let x = side + (side === 0 ? random(-20, 70) : random(-70, 20));
    let y = random(120, 950);
    let dir = side === 0 ? 1 : -1;
    strokeWeight(random(2, 7));
    beginShape();
    curveVertex(x, y);
    curveVertex(x, y);
    curveVertex(x + dir * random(70, 180), y + random(-50, 70));
    curveVertex(x + dir * random(180, 360), y + random(-100, 120));
    curveVertex(x + dir * random(300, 520), y + random(-160, 170));
    endShape();
  }
}

