  endShape(CLOSE);

  fill(223, 220, 203, 180);
  beginShape();
  vertex(570, 1251);
  bezierVertex(590, 1225, 632, 1219, 670, 1235);
  bezierVertex(638, 1250, 607, 1263, 570, 1251);
  endShape(CLOSE);

  noFill();
  stroke(92, 88, 82, 105);
  strokeWeight(3);
  for (let i = 0; i < 13; i++) {
    let x1 = 610 + i * 38 + random(-10, 10);
    let y1 = 1250 + random(-12, 20);
    let x2 = x1 + random(80, 180);
    let y2 = 1300 + random(-8, 28);
    beginShape();
    curveVertex(x1, y1);
    curveVertex(x1, y1);
    curveVertex((x1 + x2) * 0.5, y1 + random(18, 50));
