function drawBackground() {
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let a = color(4, 7, 17);
    let b = color(16, 13, 26);
    let c = color(32, 20, 25);
    let col = t < 0.55 ? lerpColor(a, b, t / 0.55) : lerpColor(b, c, (t - 0.55) / 0.45);
    stroke(col);
    line(0, y, width, y);
  }

  noStroke();
  for (let i = 0; i < 900; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.002, y * 0.002);
    fill(20 + n * 28, 18 + n * 20, 34 + n * 25, random(8, 24));
    ellipse(x, y, random(1, 7), random(1, 7));
  }

  for (let i = 0; i < 140; i++) {
    let x = random(width);
    let y = random(80, 1400);
    stroke(120, 118, 140, random(8, 22));
    strokeWeight(random(0.4, 1.8));
    line(x, y, x + random(-22, 22), y + random(80, 260));
  }
}

