function drawBranches() {
  push();
  strokeCap(ROUND);
  strokeJoin(ROUND);

  for (let i = 0; i < 54; i++) {
    let left = random() < 0.5;
    let x0 = left ? random(-70, 80) : random(width - 80, width + 70);
    let y0 = random(0, 780);
    let x1 = left ? random(180, 760) : random(840, 1420);
    let y1 = y0 + random(60, 350);
    let c1x = lerp(x0, x1, 0.33) + random(-100, 100);
    let c1y = y0 + random(20, 160);
    let c2x = lerp(x0, x1, 0.72) + random(-120, 120);
    let c2y = y1 + random(-120, 80);

    stroke(4, 5, 8, random(150, 230));
    strokeWeight(random(5, 18));
    noFill();
    bezier(x0, y0, c1x, c1y, c2x, c2y, x1, y1);

    let twigs = floor(random(3, 8));
    for (let j = 0; j < twigs; j++) {
      let tt = random(0.25, 0.96);
      let px = bezierPoint(x0, c1x, c2x, x1, tt);
      let py = bezierPoint(y0, c1y, c2y, y1, tt);
      let ang = random(-1.4, 1.4) + (left ? -0.4 : 0.4);
      let len = random(40, 170);
      strokeWeight(random(1.5, 6));
      bezier(px, py, px + cos(ang) * len * 0.35, py + sin(ang) * len * 0.35, px + cos(ang) * len * 0.7, py + sin(ang) * len * 0.7, px + cos(ang) * len, py + sin(ang) * len);
    }
  }
  pop();
}

