function drawVignette() {
  noFill();
  for (let i = 0; i < 130; i++) {
    stroke(0, 0, 0, map(i, 0, 129, 0, 12));
    strokeWeight(18);
    rect(i * 3, i * 3, width - i * 6, height - i * 6);
  }

  noStroke();
  for (let i = 0; i < 180; i++) {
    let r = map(i, 0, 179, 0, 1);
    fill(0, 0, 0, r * 3);
    rect(0, height - i * 6, width, 6);
