function drawSky() {
  noStroke();
  let topC = color(3, 4, 12);
  let midC = color(20, 18, 31);
  let lowC = color(9, 9, 13);

  for (let y = 0; y < height; y += 3) {
    let t = y / height;
    let c = t < 0.55
      ? lerpColor(topC, midC, t / 0.55)
      : lerpColor(midC, lowC, (t - 0.55) / 0.45);
    fill(red(c), green(c), blue(c), 255);
    rect(0, y, width, 4);
  }

  blendMode(ADD);
  for (let i = 0; i < 5200; i++) {
    let x = random(width);
    let y = random(height * 0.66);
    let n = noise(x * 0.002, y * 0.002);
    let a = map(n, 0, 1, 0, 16);
    fill(54, 59, 88, a);
    ellipse(x, y, random(1, 7), random(1, 7));
  }

  for (let i = 0; i < 850; i++) {
    let x = random(width);
    let y = random(80, 1050);
    let w = random(60, 300);
    let h = random(4, 18);
    fill(52, 49, 70, random(6, 18));
    ellipse(x, y, w, h);
  }
  blendMode(BLEND);
}

function drawMoon() {
