    let a = map(r, 420, 110, 2, 20);
    fill(142, 139, 124, a);
    ellipse(0, 0, r, r);
  }

  blendMode(BLEND);
  for (let r = 270; r > 0; r -= 4) {
    let t = r / 270;
    fill(166, 160, 138, 5 + 40 * (1 - t));
    ellipse(0, 0, r, r);
  }

  fill(8, 8, 14, 210);
  ellipse(-42, -20, 238, 250);

  fill(205, 199, 170, 28);
  ellipse(44, 6, 86, 210);

  pop();
}

function drawDistantBank() {
  noStroke();

  for (let x = -30; x < width + 30; x += 18) {
    let n = noise(x * 0.006, 3.1);
    let y = 990 + n * 55;
    fill(4, 5, 8, 235);
    rect(x, y, 24, height - y);
  }

  for (let i = 0; i < 85; i++) {
    let x = random(-80, width + 80);
    let base = random(910, 1070);
    let h = random(120, 420);
    let w = random(24, 70);
    let c = color(2, 4, 7, random(150, 235));
    fill(c);
    beginShape();
    vertex(x, base);
    bezierVertex(x - w * 0.6, base - h * 0.22, x - w * 0.34, base - h * 0.75, x, base - h);
    bezierVertex(x + w * 0.34, base - h * 0.75, x + w * 0.6, base - h * 0.22, x, base);
    endShape(CLOSE);
  }

  fill(13, 13, 17, 230);
  beginShape();
  vertex(0, 1035);
  for (let x = 0; x <= width; x += 60) {
    vertex(x, 1010 + noise(x * 0.004, 9.4) * 65);
  }
  vertex(width, 1160);
  vertex(0, 1160);
  endShape(CLOSE);

  stroke(102, 96, 86, 32);
  strokeWeight(2);
  for (let i = 0; i < 18; i++) {
    let y = 1015 + i * 8;
    line(0, y + random(-6, 6), width, y + random(-6, 6));
  }
}

function drawWater() {
  noStroke();
  let topC = color(8, 9, 14);
  let botC = color(1, 2, 5);

  for (let y = 1050; y < height; y += 4) {
    let t = map(y, 1050, height, 0, 1);
    let c = lerpColor(topC, botC, t);
    fill(c);
    rect(0, y, width, 5);
  }

  blendMode(ADD);
  for (let i = 0; i < 4200; i++) {
    let y = random(1060, height);
    let x = random(-100, width + 100);
    let w = random(25, 260) * map(y, 1060, height, 0.45, 1.25);
