function drawSky() {
  noStroke();
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(7, 11, t);
    let g = lerp(9, 14, t);
    let b = lerp(16, 19, t);
    if (y > 1050) {
      let k = map(y, 1050, height, 0, 1);
      r = lerp(r, 4, k);
      g = lerp(g, 5, k);
      b = lerp(b, 8, k);
    }
    stroke(r, g, b);
    line(0, y, width, y);
  }

  noStroke();
  for (let i = 0; i < 9000; i++) {
    let x = random(width);
    let y = random(height * 0.72);
    let n = noise(x * 0.002, y * 0.002);
    let a = map(n, 0, 1, 0, 18) * random(0.25, 1);
    fill(130, 139, 151, a);
    ellipse(x, y, random(1, 5), random(1, 5));
  }

  for (let i = 0; i < 170; i++) {
    let y = random(130, 1050);
    let h = random(8, 45);
    let a = random(3, 14);
    fill(95, 102, 113, a);
    beginShape();
    for (let x = -80; x <= width + 80; x += 55) {
      let yy = y + noise(x * 0.006, i * 0.17) * h;
      vertex(x, yy);
    }
    vertex(width + 80, y + h + 80);
    vertex(-80, y + h + 80);
    endShape(CLOSE);
  }
}

