function drawDeadTree() {
  push();
  translate(1235, 1485);
  strokeCap(ROUND);

  function branch(x, y, len, ang, sw, depth) {
    let x2 = x + cos(ang) * len;
    let y2 = y + sin(ang) * len;
    stroke(8, 7, 7, 225);
    strokeWeight(sw);
    line(x, y, x2, y2);

    stroke(79, 68, 56, 35);
    strokeWeight(max(1, sw * 0.28));
    line(x + 3, y, x2 + 3, y2);

    if (depth > 0) {
      let n = floor(random(2, 4));
      for (let i = 0; i < n; i++) {
        let na = ang + random(-0.95, 0.82);
        let nl = len * random(0.45, 0.73);
        branch(x2, y2, nl, na, sw * random(0.52, 0.72), depth - 1);
      }
    }
  }

  branch(0, 360, 360, -HALF_PI - 0.05, 45, 7);

  noStroke();
  fill(2, 3, 5, 220);
  ellipse(5, 368, 155, 65);

  for (let i = 0; i < 80; i++) {
    fill(20, 18, 16, random(18, 55));
    ellipse(random(-55, 60), random(70, 350), random(8, 28), random(10, 42));
  }

  pop();
}

