function drawBranch(x, y, len, ang, w, depth) {
  if (depth <= 0 || len < 14) return;

  let bend = map(noise(x * 0.01, y * 0.01, len * 0.01), 0, 1, -0.22, 0.22);
  let a = ang + bend;
  let x2 = x + cos(a) * len;
  let y2 = y + sin(a) * len;

  stroke(4, 4, 7, 245);
  strokeWeight(w);
  line(x, y, x2, y2);

  stroke(45, 35, 32, 60);
  strokeWeight(max(1, w * 0.18));
  line(x + 3, y, x2 + 3, y2);

  let n = depth > 5 ? 3 : 2;
  for (let i = 0; i < n; i++) {
    let side = i % 2 === 0 ? -1 : 1;
    let na = a + side * random(0.38, 0.82) + random(-0.12, 0.12);
    let nl = len * random(0.48, 0.74);
    drawBranch(x2, y2, nl, na, w * random(0.48, 0.68), depth - 1);
  }

  if (depth < 4) {
    stroke(4, 4, 7, 210);
    strokeWeight(max(1, w * 0.55));
    line(x2, y2, x2 + random(-35, 35), y2 + random(-28, 22));
  }
}

