function drawTree(x, y, len, ang, depth, thick) {
  push();
  translate(x, y);
  branch(len, ang, depth, thick);
  pop();
}

function branch(len, ang, depth, thick) {
  if (depth <= 0 || len < 8) return;

  stroke(230, 40, 3, map(depth, 1, 9, 35, 95));
  strokeWeight(thick);
  strokeCap(ROUND);

  let x2 = cos(ang) * len;
  let y2 = sin(ang) * len;
  line(0, 0, x2, y2);

  push();
  translate(x2, y2);

  let n = floor(random(2, 4));
  for (let i = 0; i < n; i++) {
    let a = ang + random(-0.95, 0.95);
    let l = len * random(0.43, 0.72);
    let t = thick * random(0.52, 0.72);
    branch(l, a, depth - 1, t);
  }

  pop();
}

