  drawBoat();
  drawAsh();
  drawGrain();
}

function drawBackground() {
  let topC = color(5, 8, 16);
  let midC = color(27, 34, 49);
  let botC = color(15, 18, 24);

  noFill();
  for (let y = 0; y < height; y++) {
    let c;
    if (y < height * 0.58) {
      c = lerpColor(topC, midC, y / (height * 0.58));
    } else {
      c = lerpColor(midC, botC, (y - height * 0.58) / (height * 0.42));
    }
    stroke(c);
    line(0, y, width, y);
  }

  noStroke();
  for (let i = 0; i < 700; i++) {
    let x = random(width);
    let y = random(height * 0.72);
    let s = random(1, 4);
    let a = random(5, 28);
    fill(170, 185, 200, a);
    ellipse(x, y, s, s);
  }

  for (let i = 0; i < 90; i++) {
    let x = random(-250, width + 250);
    let y = random(250, 1250);
    let w = random(180, 580);
    let h = random(18, 70);
    fill(185, 195, 205, random(5, 18));
    ellipse(x, y, w, h);
  }
}

function drawMoon() {
  push();
  translate(835, 415);

  drawingContext.shadowBlur = 90;
  drawingContext.shadowColor = 'rgba(210,220,220,0.35)';
  noStroke();

  for (let r = 520; r > 290; r -= 18) {
    fill(190, 200, 195, map(r, 520, 290, 6, 28));
    ellipse(0, 0, r, r);
  }

  drawingContext.shadowBlur = 0;
  fill(219, 218, 202, 205);
  ellipse(0, 0, 330, 330);

  for (let i = 0; i < 90; i++) {
    let a = random(TWO_PI);
    let rr = sqrt(random()) * 150;
    let x = cos(a) * rr;
    let y = sin(a) * rr;
    let s = random(8, 34);
    fill(120, 126, 124, random(10, 28));
    ellipse(x, y, s * 1.35, s);
  }

  fill(5, 8, 16, 224);
  ellipse(-68, 14, 342, 342);

  fill(240, 238, 218, 80);
  arc(0, 0, 330, 330, -HALF_PI, HALF_PI, CHORD);

  fill(10, 12, 18, 100);
  ellipse(12, -48, 32, 46);
  ellipse(34, 55, 22, 16);

  pop();
}

function drawFarShore() {
  noStroke();

  for (let i = 0; i < 7; i++) {
    let y = 1050 + i * 28;
    fill(185, 195, 198, 10 - i);
    beginShape();
    vertex(0, y + random(-10, 10));
    for (let x = 0; x <= width; x += 80) {
      curveVertex(x, y + noise(x * 0.006, i) * 38);
    }
    vertex(width, y + 80);
    vertex(0, y + 80);
    endShape(CLOSE);
  }

  fill(8, 10, 14, 190);
  beginShape();
  vertex(0, 1190);
  for (let x = 0; x <= width; x += 70) {
    let y = 1155 + noise(x * 0.006, 9) * 95;
    curveVertex(x, y);
  }
  vertex(width, 1320);
  vertex(0, 1320);
  endShape(CLOSE);

  drawStones();
  drawMist(1160, 1430);
}

function drawStones() {
  push();
  noStroke();
  fill(9, 11, 15, 210);

  for (let i = 0; i < 34; i++) {
    let x = random(900, 1580);
    let y = random(1090, 1250);
    let w = random(18, 55);
    let h = random(55, 145);
    let r = w * 0.5;

    beginShape();
    vertex(x - w / 2, y + h / 2);
    vertex(x - w / 2, y - h / 2 + r);
    bezierVertex(x - w / 2, y - h / 2, x + w / 2, y - h / 2, x + w / 2, y - h / 2 + r);
    vertex(x + w / 2, y + h / 2);
    endShape(CLOSE);
  }

  pop();
}

