function drawWater() {
  push();

  noStroke();
  for (let y = 1250; y < height; y++) {
    let t = map(y, 1250, height, 0, 1);
    let c = lerpColor(color(20, 25, 33), color(3, 5, 8), t);
    stroke(c);
    line(0, y, width, y);
  }

  noStroke();
  for (let i = 0; i < 180; i++) {
    let y = random(1260, height);
    let cx = 835 + random(-170, 170) * map(y, 1260, height, 0.3, 1.4);
