  strokeCap(ROUND);
  for (let i = 0; i < 540; i++) {
    let y = random(1270, 1990);
    let x = random(-70, width + 70);
    let len = random(28, 250);
    let a = random(10, 52);
    let c = random() < 0.22 ? color(190, 200, 200, a) : color(43, 53, 65, a);
    stroke(c);
    strokeWeight(random(1, 3));
    noFill();
    beginShape();
    for (let j = 0; j < 6; j++) {
      let xx = x + (len / 5) * j;
      let yy = y + sin(j * 1.4 + i) * random(1, 8);
      curveVertex(xx, yy);
    }
    endShape();
  }

  pop();
}

function drawDeadTree() {
  push();
  translate(265, 1345);

  stroke(4, 5, 7, 245);
