  bezier(0, -85, 55, -235, 28, -420, 75, -610);

  strokeWeight(32);
  bezier(5, -220, -80, -350, -110, -495, -210, -650);

  randomSeed(11);
  push();
  translate(60, -580);
  rotate(-0.1);
  branch(340, 24);
  pop();

  push();
  translate(-95, -475);
  rotate(-0.72);
  branch(300, 20);
  pop();

  push();
  translate(28, -335);
  rotate(0.78);
  branch(260, 17);
  pop();

  push();
