  let lowC = color(4, 5, 6);
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let c;
    if (t < 0.48) {
      c = lerpColor(topC, midC, t / 0.48);
    } else {
      c = lerpColor(midC, lowC, (t - 0.48) / 0.52);
    }
    stroke(c);
    line(0, y, width, y);
  }

  blendMode(ADD);
  for (let i = 0; i < 85000; i++) {
