  bezier(145, 1690, 120, 1300, 190, 950, 360, 700);
  strokeWeight(24);
  bezier(85, 2000, 120, 1600, 115, 1260, 220, 980);

  strokeWeight(40);
  bezier(1460, 1710, 1500, 1300, 1400, 940, 1245, 695);
  strokeWeight(25);
  bezier(1545, 2000, 1490, 1570, 1500, 1250, 1395, 980);

  drawBranch(355, 708, 330, -2.35, 18, 7);
  drawBranch(278, 920, 280, -2.85, 14, 6);
  drawBranch(226, 1110, 230, -3.15, 11, 5);
  drawBranch(1245, 704, 330, -0.80, 18, 7);
  drawBranch(1325, 920, 280, -0.28, 14, 6);
  drawBranch(1385, 1110, 230, -0.02, 11, 5);

  for (let i = 0; i < 120; i++) {
    let side = random() < 0.5 ? -1 : 1;
    let baseX = side < 0 ? random(80, 330) : random(1270, 1520);
    let baseY = random(720, 1650);
    stroke(6, 6, 7, random(90, 170));
    strokeWeight(random(1, 4));
    let len = random(40, 160);
    let ang = side < 0 ? random(-2.9, -0.9) : random(-2.2, -0.15);
    line(baseX, baseY, baseX + cos(ang) * len, baseY + sin(ang) * len);
  }
}

function drawBranch(x, y, len, ang, w, depth) {
  if (depth <= 0 || w < 0.8) return;

  let bend = random(-0.55, 0.55);
  let x2 = x + cos(ang) * len;
  let y2 = y + sin(ang) * len;
  let cx1 = x + cos(ang + bend) * len * 0.35;
  let cy1 = y + sin(ang + bend) * len * 0.35;
  let cx2 = x + cos(ang - bend * 0.6) * len * 0.72;
  let cy2 = y + sin(ang - bend * 0.6) * len * 0.72;

  stroke(4, 4, 5, 220);
  strokeWeight(w);
  noFill();
  bezier(x, y, cx1, cy1, cx2, cy2, x2, y2);

  let n = depth > 4 ? 3 : 2;
  for (let i = 0; i < n; i++) {
    let na = ang + random(-0.95, 0.95);
    let nl = len * random(0.48, 0.72);
    let nw = w * random(0.52, 0.72);
    drawBranch(x2, y2, nl, na, nw, depth - 1);
  }
}

