function branch(x, y, angle, len, depth) {
  if (depth <= 0 || len < 14) return;

  let x2 = x + cos(angle) * len;
  let y2 = y + sin(angle) * len;

  stroke(10, 12, 16, 245);
  strokeWeight(depth * 7);
  line(x, y, x2, y2);

  if (depth > 2) {
    stroke(84, 57, 51, 100);
    strokeWeight(depth * 1.3);
    line(x + 3, y, x2 + 2, y2);
  }

  let forks = depth > 5 ? 3 : 2;
  for (let i = 0; i < forks; i++) {
    let turn = random(0.25, 0.62) * (i % 2 === 0 ? -1 : 1);
    if (i === 2) turn = random(-0.2, 0.2);
    branch(x2, y2, angle + turn, len * random(0.60, 0.76), depth - 1);
  }
}

