function paintBackground() {
  let topCol = color(13, 12, 22);
  let midCol = color(42, 31, 43);
  let lowCol = color(67, 48, 43);

  noFill();
  for (let y = 0; y < height; y++) {
    let c;
    if (y < 1250) {
      c = lerpColor(topCol, midCol, y / 1250);
    } else {
      c = lerpColor(midCol, lowCol, (y - 1250) / 750);
    }
    stroke(c);
    line(0, y, width, y);
  }

  // Vertical stains and old-paint texture.
  for (let i = 0; i < 260; i++) {
    let x = random(width);
    let w = random(3, 28);
    let a = random(3, 12);
    stroke(random() < 0.55 ? color(185, 136, 105, a) : color(0, 0, 0, a));
    strokeWeight(w);
    line(x, random(-100, 500), x + random(-35, 35), random(1300, 1900));
  }

  // Dim horizontal veils.
  noFill();
  for (let i = 0; i < 30; i++) {
    let y = random(650, 1450);
    stroke(178, 144, 125, random(3, 12));
    strokeWeight(random(8, 35));
    bezier(
      -100, y,
      400, y + random(-100, 100),
      1050, y + random(-90, 90),
      1700, y + random(-50, 50)
    );
  }
}

function paintMoon() {
  push();
  let mx = 835;
  let my = 600;

  noStroke();
  for (let r = 570; r > 355; r -= 6) {
    let a = map(r, 570, 355, 1, 10);
    fill(242, 210, 152, a);
    circle(mx, my, r * 2);
  }

  fill(215, 190, 145, 220);
  circle(mx, my, 690);

  // Uneven lunar glazing.
  for (let i = 0; i < 4200; i++) {
    let ang = random(TWO_PI);
    let rad = sqrt(random()) * 335;
    let x = mx + cos(ang) * rad;
    let y = my + sin(ang) * rad;
    let n = noise(x * 0.007, y * 0.007);
    if (n > 0.52) {
      stroke(73, 62, 65, random(4, 18));
    } else {
      stroke(255, 229, 180, random(4, 16));
    }
    strokeWeight(random(1, 5));
    point(x, y);
  }

  // A faint shadow eating one edge.
  noStroke();
  for (let r = 360; r > 260; r -= 5) {
    fill(24, 20, 29, map(r, 360, 260, 2, 8));
    ellipse(mx - 210, my + 20, r * 1.05, r * 1.75);
  }
  pop();
}

