function branch(x, y, len, angle, weight, depth) {
  let bend = random(-0.09, 0.09);
  let x2 = x + cos(angle + bend) * len;
  let y2 = y + sin(angle + bend) * len;

  stroke(20, 17, 21, 245);
  strokeWeight(max(1.1, weight));
  line(x, y, x2, y2);

  stroke(155, 102, 73, 45);
  strokeWeight(max(0.7, weight * 0.16));
  line(x + 2, y, x2 + 2, y2);

  if (depth <= 0 || len < 18) {
    if (random() < 0.78) paintLeaf(x2, y2, angle);
    return;
  }

  branch(
    x2, y2,
    len * random(0.65, 0.76),
    angle - random(0.27, 0.58),
    weight * 0.68,
    depth - 1
  );

  branch(
    x2, y2,
    len * random(0.64, 0.75),
    angle + random(0.28, 0.59),
    weight * 0.67,
    depth - 1
  );

  if (depth > 3 && random() < 0.26) {
    branch(
      x2, y2,
      len * random(0.48, 0.61),
      angle + random(-0.16, 0.16),
      weight * 0.5,
      depth - 2
    );
  }
}

