    stroke(23, 18, 22, random(125, 235));
    strokeWeight(random(2, 11));
    bezier(
      startX, startY,
      startX + side * random(40, 160), startY + random(25, 120),
      endX - side * random(30, 130), endY + random(-45, 45),
      endX, endY
    );

    stroke(185, 117, 77, random(15, 45));
    strokeWeight(random(0.7, 2.2));
    bezier(
      startX + 2, startY,
      startX + side * random(40, 160), startY + random(25, 120),
      endX - side * random(30, 130), endY + random(-45, 45),
      endX, endY
    );
  }
  pop();
}

