function paintSky() {
  let topCol = color(9, 12, 26);
  let midCol = color(42, 45, 61);
  let lowCol = color(151, 107, 72);

  for (let y = 0; y < 1140; y++) {
    let c;
    if (y < 650) {
      c = lerpColor(topCol, midCol, y / 650);
    } else {
      c = lerpColor(midCol, lowCol, (y - 650) / 490);
    }
    stroke(c);
    line(0, y, width, y);
  }

  noStroke();
  for (let i = 0; i < 9000; i++) {
    let x = random(width);
    let y = random(1120);
    let n = noise(x * 0.004, y * 0.004);
    let a = random(3, 17);
    if (n > 0.57) fill(224, 178, 130, a);
    else fill(25, 29, 43, a);
    ellipse(x, y, random(2, 11), random(1, 4));
  }

  for (let i = 0; i < 180; i++) {
    let x = random(width);
    let y = random(40, 600);
    let a = map(y, 40, 600, 80, 15);
    fill(223, 218, 192, a);
    ellipse(x, y, random(1, 4), random(1, 4));
  }
}

function paintEclipse() {
  push();
  blendMode(SCREEN);
  noStroke();

  for (let r = 390; r > 205; r -= 5) {
    let a = map(r, 390, 205, 1, 15);
    fill(226, 166, 102, a);
    ellipse(800, 420, r, r);
  }

  for (let r = 236; r > 190; r -= 3) {
    fill(255, 211, 139, map(r, 236, 190, 18, 85));
    ellipse(800, 420, r, r);
  }
  pop();

  noStroke();
