function branch(x, y, len, ang, depth, weight) {
  if (depth <= 0 || len < 8) return;

  let x2 = x + cos(ang) * len;
  let y2 = y + sin(ang) * len;

  stroke(8, 12, 17, 220);
  strokeWeight(max(1, weight));
  line(x, y, x2, y2);

  stroke(80, 65, 58, 35);
  strokeWeight(max(1, weight * 0.2));
  line(x + 3, y, x2 + 2, y2);

  let forks = depth > 5 ? 2 : floor(random(1, 3));
  for (let i = 0; i < forks; i++) {
    let bend = random(0.25, 0.62) * (i % 2 === 0 ? -1 : 1);
    branch(
      x2,
      y2,
      len * random(0.58, 0.76),
      ang + bend,
      depth - 1,
      weight * 0.64
    );
  }
}

