function paintSky() {
  const top = color(9, 10, 28);
  const middle = color(45, 34, 60);
  const horizon = color(137, 79, 69);

  strokeWeight(2);
  for (let y = 0; y < 1120; y += 2) {
    let c;
    if (y < 650) {
      c = lerpColor(top, middle, y / 650);
    } else {
      c = lerpColor(middle, horizon, (y - 650) / 470);
    }
    stroke(c);
    line(0, y, width, y);
  }

  noStroke();
  for (let i = 0; i < 7000; i++) {
    const y = random(20, 1110);
    const x = random(-100, width + 100);
    const warm = map(y, 0, 1110, 0, 1);
    fill(
      lerp(70, 220, warm),
      lerp(70, 130, warm),
      lerp(115, 110, warm),
      random(2, 12)
    );
    ellipse(x, y, random(8, 75), random(1, 5));
  }

  for (let i = 0; i < 340; i++) {
    const x = random(width);
    const y = random(40, 900);
    const a = random(30, 145);
    fill(238, 220, 187, a);
    circle(x, y, random(1.2, 4.2));
  }

  for (let i = 0; i < 85; i++) {
    const x = random(width);
    const y = random(200, 1050);
    const w = random(130, 520);
    stroke(185, 119, 112, random(4, 16));
    strokeWeight(random(2, 10));
    line(x - w / 2, y, x + w / 2, y + random(-8, 8));
  }
}

function paintEclipse() {
  const cx = 845;
  const cy = 500;

  noFill();
  for (let d = 1050; d > 610; d -= 5) {
    const t = map(d, 1050, 610, 0, 1);
    stroke(245, 186, 115, 2 + 10 * t);
    strokeWeight(6);
    ellipse(cx, cy, d, d);
  }

  blendMode(SCREEN);
  noStroke();
  for (let i = 0; i < 120; i++) {
    fill(241, 179, 103, 2);
    circle(cx, cy, 640 + i * 3.2);
  }
  blendMode(BLEND);

  noStroke();
  fill(235, 207, 162);
  circle(cx, cy, 610);

  for (let i = 0; i < 1700; i++) {
    const a = random(TWO_PI);
    const r = sqrt(random()) * 292;
    const x = cx + cos(a) * r;
    const y = cy + sin(a) * r;
    fill(
      random(165, 225),
      random(137, 197),
      random(116, 164),
      random(4, 24)
    );
    ellipse(x, y, random(3, 30), random(1, 8));
  }

  fill(12, 12, 25);
  circle(cx + 24, cy - 3, 470);

  noFill();
  stroke(255, 222, 171, 150);
  strokeWeight(10);
  arc(cx + 24, cy - 3, 481, 481, HALF_PI + 0.2, PI + HALF_PI + 0.05);

  stroke(255, 232, 193, 50);
  strokeWeight(3);
  arc(cx + 24, cy - 3, 500, 500, HALF_PI + 0.1, PI + HALF_PI + 0.1);

  for (let i = 0; i < 110; i++) {
    const a = random(HALF_PI + 0.2, PI + HALF_PI);
    const r1 = random(310, 350);
    const r2 = r1 + random(20, 150);
    stroke(245, 191, 125, random(5, 24));
    strokeWeight(random(1, 5));
    line(
      cx + cos(a) * r1,
      cy + sin(a) * r1,
      cx + cos(a) * r2,
      cy + sin(a) * r2
    );
  }
}

