function growBranch(x, y, len, angle, depth) {
  if (depth <= 0 || len < 12) return;

  const bend = random(-0.13, 0.13);
  const x2 = x + cos(angle + bend) * len;
  const y2 = y + sin(angle + bend) * len;

  stroke(9, 11, 18, 235);
  strokeWeight(max(1.2, depth * depth * 0.55));
  strokeCap(ROUND);
  line(x, y, x2, y2);

  stroke(66, 48, 52, 80);
  strokeWeight(max(0.7, depth * 0.65));
  line(x + 2, y, x2 + 2, y2);

  const next = len * random(0.66, 0.79);
  growBranch(x2, y2, next, angle - random(0.22, 0.52), depth - 1);
  growBranch(x2, y2, next * random(0.78, 1.02), angle + random(0.22, 0.55), depth - 1);

  if (depth > 4 && random() < 0.55) {
    growBranch(
      lerp(x, x2, random(0.45, 0.8)),
      lerp(y, y2, random(0.45, 0.8)),
      next * 0.65,
      angle + random(-0.9, 0.9),
      depth - 2
    );
  }

  if (depth <= 2 && random() < 0.36) {
    noStroke();
    fill(205, 160, 126, random(40, 105));
    ellipse(x2, y2, random(5, 12), random(2, 6));
  }
}

