function withAlpha(value, alpha) {
  let c = color(value);
  c.setAlpha(alpha);
  return c;
}

function brushLine(x1, y1, x2, y2, col, weight, repetitions) {
  for (let i = 0; i < repetitions; i++) {
    stroke(withAlpha(col, random(18, 65)));
    strokeWeight(weight * random(0.25, 1));
    line(
      x1 + random(-weight, weight),
      y1 + random(-weight, weight),
      x2 + random(-weight, weight),
      y2 + random(-weight, weight)
    );
  }
}

function brushBezier(points, col, weight, repetitions, alphaMax) {
  noFill();
  for (let i = 0; i < repetitions; i++) {
    stroke(withAlpha(col, random(15, alphaMax)));
    strokeWeight(weight * random(0.3, 1));
    bezier(
      points[0] + random(-weight, weight),
      points[1] + random(-weight, weight),
      points[2] + random(-weight, weight),
      points[3] + random(-weight, weight),
      points[4] + random(-weight, weight),
      points[5] + random(-weight, weight),
      points[6] + random(-weight, weight),
      points[7] + random(-weight, weight)
    );
  }
}

function paintSky() {
  let top = color(13, 18, 27);
  let upper = color(39, 48, 58);
  let lower = color(133, 79, 58);
  let horizon = color(207, 139, 91);

  for (let y = 0; y <= 1110; y += 3) {
    let c;
    if (y < 650) {
      c = lerpColor(top, upper, y / 650);
    } else {
      c = lerpColor(lower, horizon, (y - 650) / 460);
    }
    stroke(c);
    strokeWeight(5);
    line(0, y, width, y);
  }

  for (let i = 0; i < 800; i++) {
    let y = random(40, 1080);
    let x = random(-100, width);
    let len = random(30, 280);
    let palette = [
      color(235, 170, 111),
      color(105, 118, 119),
      color(73, 61, 66),
      color(191, 98, 69),
      color(227, 205, 166)
    ];
    stroke(withAlpha(random(palette), random(5, 23)));
    strokeWeight(random(1, 8));
    line(x, y, x + len, y + random(-5, 5));
  }
}

