function drawTree(x, base, heightValue, lean, depth) {
  push();
  stroke(9, 13, 15, 245);
  drawBranch(x, base, heightValue, -HALF_PI + lean, depth);

  stroke(84, 66, 54, 80);
  strokeWeight(5);
  line(x - 5, base, x + lean * heightValue * 0.5, base - heightValue * 0.7);
  pop();
}

function drawBranch(x, y, len, angle, depth) {
  if (depth <= 0 || len < 10) return;

  let bend = random(-0.08, 0.08);
  let x2 = x + cos(angle + bend) * len;
  let y2 = y + sin(angle + bend) * len;

  strokeWeight(max(1, len * 0.075));
  line(x, y, x2, y2);

  if (depth > 2) {
    drawBranch(
      x2,
      y2,
      len * random(0.61, 0.73),
      angle - random(0.22, 0.52),
      depth - 1
    );
    drawBranch(
      x2,
      y2,
      len * random(0.58, 0.71),
      angle + random(0.25, 0.56),
      depth - 1
    );

    if (random() < 0.38) {
      drawBranch(
        x2,
        y2,
        len * random(0.42, 0.56),
        angle + random(-0.15, 0.15),
        depth - 2
      );
    }
  }
}

