function paintSky() {
  const ctx = drawingContext;
  const g = ctx.createLinearGradient(0, 0, 0, height);
  g.addColorStop(0, "#090b13");
  g.addColorStop(0.36, "#20202a");
  g.addColorStop(0.68, "#3a3030");
  g.addColorStop(1, "#100e12");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);

  noFill();
  for (let i = 0; i < 6500; i++) {
    let y = random(height);
    let x = random(width);
    let n = noise(x * 0.004, y * 0.004);
    let warm = y > 620 && y < 1450;
    stroke(
      warm ? 112 + 30 * n : 60 + 25 * n,
      warm ? 75 + 18 * n : 67 + 20 * n,
      warm ? 70 + 15 * n : 82 + 25 * n,
      random(5, 20)
    );
    strokeWeight(random(1, 5));
    let len = random(8, 75);
    line(x, y, x + len, y + random(-4, 4));
  }

  noStroke();
  for (let i = 0; i < 90; i++) {
    fill(45, 34, 42, random(5, 16));
    ellipse(
      random(width),
      random(300, 1500),
      random(120, 500),
      random(20, 100)
    );
  }
}

