function branch(x, y, len, ang, depth, sw) {
  if (depth <= 0 || len < 12) return;

  let x2 = x + cos(ang) * len;
  let y2 = y + sin(ang) * len;

  stroke(7, 8, 11, 230);
  strokeWeight(sw);
  line(x, y, x2, y2);

  stroke(84, 65, 61, 35);
  strokeWeight(max(1, sw * 0.16));
  line(x - 2, y, x2 - 2, y2);

  let split = depth > 5 ? 2 : 1;
  for (let i = 0; i < split; i++) {
    branch(
      x2,
      y2,
      len * random(0.57, 0.76),
      ang + random(-0.68, 0.68),
      depth - 1,
      sw * 0.66
    );
  }

  if (depth > 3 && random() < 0.8) {
    let t = random(0.45, 0.85);
    let bx = lerp(x, x2, t);
    let by = lerp(y, y2, t);
    branch(
      bx,
      by,
      len * random(0.28, 0.48),
      ang + random(-1.05, 1.05),
      depth - 2,
      sw * 0.43
    );
  }
}

