function crack(x, y, tx, ty, depth) {
  if (depth <= 0) return;
  let mx = lerp(x, tx, random(0.35, 0.7)) + random(-18, 18);
  let my = lerp(y, ty, random(0.35, 0.7));
  line(x, y, mx, my);
  line(mx, my, tx, ty);
  if (random() < 0.75) {
    crack(mx, my, mx + random(-45, 45), my + random(25, 65), depth - 1);
  }
}

