function witheredFlower(x, y, h, s, red) {
  push();
  translate(x, y);
  stroke(42, 54, 38, 220);
  strokeWeight(5 * s);
  noFill();
  bezier(0, 0, -15 * s, -h * 0.35, 20 * s, -h * 0.7, -8 * s, -h);

  translate(-8 * s, -h);
  rotate(random(-0.7, 0.7));
  noStroke();

  let c = red
    ? color(105, 31, 35, 220)
    : color(152, 137, 111, 190);

  for (let i = 0; i < 7; i++) {
    push();
    rotate((TWO_PI * i) / 7 + random(-0.18, 0.18));
    fill(red(c), green(c), blue(c), random(130, 230));
    ellipse(0, -18 * s, random(18, 35) * s, random(30, 58) * s);
    pop();
  }

  fill(25, 20, 18);
  ellipse(0, 0, 25 * s, 25 * s);

  fill(174, 133, 83, 100);
  for (let i = 0; i < 10; i++) {
    let a = random(TWO_PI);
    ellipse(cos(a) * 8 * s, sin(a) * 8 * s, 3 * s, 3 * s);
  }
  pop();
}

function paintVignette() {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(800, 950, 350, 800, 1000, 1150);
  g.addColorStop(0, "rgba(0,0,0,0)");
  g.addColorStop(0.63, "rgba(0,0,0,0.08)");
  g.addColorStop(1, "rgba(0,0,0,0.78)");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);

  noFill();
  stroke(4, 4, 7, 160);
  strokeWeight(36);
  rect(18, 18, width - 36, height - 36);
}

function setup() {
  randomSeed(1);
  noiseSeed(1);

  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();

  paintSky();
  paintEclipse();
  paintDistantHaze();
  paintMountains();
  paintGate();
  paintRiver();
  paintBanks();
  paintReflections();
  paintCypresses();
  paintBoat();
  paintShroud();
  paintMoths();
  paintSurfaceTexture();
}

function paintSky() {
  const topColor = color(9, 13, 25);
  const middleColor = color(45, 48, 62);
  const horizonColor = color(128, 96, 76);

  noFill();
  strokeWeight(2);

  for (let y = 0; y < 1080; y += 2) {
    let c;
    if (y < 650) {
      c = lerpColor(topColor, middleColor, y / 650);
    } else {
      c = lerpColor(middleColor, horizonColor, (y - 650) / 430);
    }
    stroke(c);
    line(0, y, width, y);
  }

  for (let i = 0; i < 6500; i++) {
    const y = random(0, 1080);
    const x = random(-100, width + 100);
    const len = random(12, 130) * map(y, 0, 1080, 0.5, 1.4);
    const palette = [
      color(170, 137, 106, 10),
      color(67, 90, 111, 15),
      color(220, 181, 137, 8),
      color(16, 20, 34, 18)
    ];

    stroke(random(palette));
    strokeWeight(random(1, 5));
    line(x, y, x + len, y + random(-4, 4));
  }

  blendMode(MULTIPLY);
  for (let i = 0; i < 300; i++) {
    const x = random(width);
    const y = random(80, 850);
    const w = random(80, 360);

    noFill();
    stroke(12, 15, 27, random(5, 18));
    strokeWeight(random(8, 30));
    bezier(
      x - w, y + random(-25, 25),
      x - w * 0.3, y - random(20, 90),
      x + w * 0.3, y + random(20, 90),
      x + w, y
    );
  }
  blendMode(BLEND);
}

function paintEclipse() {
  const x = 390;
  const y = 390;

  blendMode(SCREEN);
  noStroke();
  for (let d = 430; d > 230; d -= 8) {
    const a = map(d, 430, 230, 2, 13);
    fill(217, 183, 132, a);
    circle(x, y, d);
  }

  fill(218, 193, 153, 190);
  circle(x, y, 238);

  fill(15, 17, 25, 247);
  circle(x + 25, y - 9, 218);

  noFill();
  stroke(250, 218, 163, 135);
  strokeWeight(6);
  arc(x, y, 238, 238, -HALF_PI, HALF_PI + 0.3);

  for (let i = 0; i < 120; i++) {
    const a = random(-HALF_PI, HALF_PI + 0.35);
    const r = random(120, 180);
    const x1 = x + cos(a) * r;
    const y1 = y + sin(a) * r;

    stroke(246, 207, 151, random(8, 35));
    strokeWeight(random(1, 4));
    line(
      x1,
      y1,
      x1 + cos(a) * random(20, 90),
      y1 + sin(a) * random(20, 90)
    );
  }
  blendMode(BLEND);
}

function paintDistantHaze() {
