function mountainLayer(baseY, peakHeight, c, roughness) {
  fill(c);
  noStroke();
  beginShape();
  vertex(0, 1120);

  for (let x = 0; x <= width; x += 20) {
    const n1 = noise(x * roughness, baseY * 0.001);
    const n2 = noise(x * roughness * 2.7, 40);
    const y = baseY - n1 * peakHeight - n2 * peakHeight * 0.25;
    vertex(x, y);
  }

  vertex(width, 1120);
  endShape(CLOSE);
}

function paintMountains() {
  mountainLayer(960, 235, color(60, 62, 70), 0.0014);
  mountainLayer(1010, 185, color(41, 46, 53), 0.0021);
  mountainLayer(1070, 130, color(25, 31, 37), 0.0032);

  for (let i = 0; i < 700; i++) {
    const x = random(width);
    const y = random(750, 1040);
    stroke(157, 139, 119, random(5, 22));
    strokeWeight(random(1, 5));
    line(x, y, x + random(-20, 70), y + random(-5, 10));
  }
}

function paintGate() {
  const gx = 925;
  const base = 1070;

  drawingContext.shadowColor = color(0, 0, 0, 150);
  drawingContext.shadowBlur = 45;

  noStroke();
  fill(23, 25, 29);
  rect(gx - 148, 790, 296, base - 790);
  ellipse(gx, 790, 296, 296);

  fill(4, 7, 10);
  rect(gx - 94, 800, 188, base - 800);
  ellipse(gx, 800, 188, 188);

  drawingContext.shadowBlur = 0;

  for (let i = 0; i < 160; i++) {
    const side = random() < 0.5 ? -1 : 1;
    const x = gx + side * random(100, 150);
    const y = random(690, base);

    stroke(
      random(48, 79),
      random(48, 69),
      random(48, 65),
      random(20, 80)
    );
    strokeWeight(random(3, 15));
    line(x, y, x + random(-20, 20), y + random(5, 45));
  }

  blendMode(SCREEN);
  for (let i = 0; i < 35; i++) {
    noFill();
    stroke(182, 151, 112, random(3, 17));
    strokeWeight(random(2, 9));
    arc(
      gx,
      793,
      205 + i * 3,
      205 + i * 3,
      PI,
      TWO_PI
    );
  }
  blendMode(BLEND);
}

function riverBounds(y) {
  const t = constrain((y - 1000) / 1000, 0, 1);
  return {
    left: lerp(770, -180, t),
    right: lerp(1080, 1780, t)
  };
}

function paintRiver() {
  noStroke();
  fill(20, 35, 45);
  beginShape();
  vertex(770, 1000);
  vertex(1080, 1000);
  vertex(1780, 2000);
  vertex(-180, 2000);
  endShape(CLOSE);

  for (let y = 1010; y < height; y += 5) {
    const b = riverBounds(y);
    const base = map(y, 1010, height, 50, 15);

    stroke(
      base + random(-8, 15),
      base + random(5, 25),
      base + random(15, 38),
      random(40, 115)
    );
    strokeWeight(random(2, 8));

    const x = random(b.left, b.right);
    const len = random(20, map(y, 1010, height, 100, 420));
    line(x, y, min(x + len, b.right), y + random(-3, 3));
  }
}

function paintBanks() {
  noStroke();

  fill(20, 25, 27);
  beginShape();
  vertex(0, 950);
  vertex(780, 995);
  vertex(655, 1220);
  vertex(390, 1500);
  vertex(0, 1680);
  endShape(CLOSE);

  fill(17, 22, 24);
  beginShape();
  vertex(1600, 930);
  vertex(1060, 995);
  vertex(1190, 1250);
  vertex(1420, 1510);
  vertex(1600, 1620);
  endShape(CLOSE);

  for (let i = 0; i < 1700; i++) {
    const leftSide = random() < 0.52;
    let x;
    let y = random(970, 1580);
    const b = riverBounds(y);

    if (leftSide) {
      x = random(0, max(0, b.left + 35));
    } else {
      x = random(min(width, b.right - 35), width);
    }

    stroke(
      random(32, 74),
      random(36, 69),
      random(35, 57),
      random(20, 100)
    );
    strokeWeight(random(2, 10));
    line(x, y, x + random(-30, 30), y - random(4, 45));
  }
}

function paintReflections() {
  blendMode(SCREEN);

  for (let i = 0; i < 270; i++) {
    const y = random(1020, 1940);
    const b = riverBounds(y);
    const center = lerp(925, 780, (y - 1020) / 980);
    const spread = map(y, 1020, 1940, 30, 360);
    const x = constrain(randomGaussian(center, spread), b.left, b.right);

    stroke(185, 150, 107, random(5, 38));
    strokeWeight(random(1, 7));
    line(x, y, x + random(15, 180), y + random(-3, 3));
  }

  for (let i = 0; i < 120; i++) {
    const y = random(1080, 1990);
    const b = riverBounds(y);
    const x = random(b.left, b.right);

    stroke(99, 137, 151, random(8, 28));
    strokeWeight(random(2, 8));
    line(x, y, min(x + random(35, 260), b.right), y);
  }

  blendMode(BLEND);
}

function paintCypresses() {
  for (let i = 0; i < 19; i++) {
    const side = i < 10 ? -1 : 1;
    const x = side < 0
      ? random(50, 690)
      : random(1130, 1570);
    const ground = random(960, 1260);
    const h = random(160, 470);
    paintCypress(x, ground, h);
  }
}

function paintCypress(x, ground, h) {
  stroke(10, 18, 19, 230);
  strokeWeight(max(5, h * 0.035));
  line(x, ground, x + random(-8, 8), ground - h);

  for (let y = ground - 12; y > ground - h; y -= random(7, 15)) {
    const t = (ground - y) / h;
    const widest = sin(t * PI) * h * 0.13 + 8;

    stroke(
      random(7, 25),
      random(17, 36),
      random(19, 37),
      random(110, 230)
    );
    strokeWeight(random(4, 12));
    line(x, y, x - random(widest * 0.3, widest), y + random(-8, 15));
    line(x, y, x + random(widest * 0.3, widest), y + random(-8, 15));
  }
}

function paintBoat() {
  const cx = 810;
  const cy = 1510;

  drawingContext.shadowColor = color(0, 0, 0, 180);
  drawingContext.shadowBlur = 35;

  noStroke();
  fill(8, 12, 15);
  beginShape();
  vertex(cx - 355, cy - 25);
  bezierVertex(cx - 210, cy + 100, cx + 245, cy + 120, cx + 430, cy - 35);
  bezierVertex(cx + 210, cy + 20, cx - 190, cy + 15, cx - 355, cy - 25);
  endShape(CLOSE);

  fill(34, 35, 33);
  beginShape();
  vertex(cx - 330, cy - 35);
  bezierVertex(cx - 80, cy + 12, cx + 200, cy + 18, cx + 405, cy - 45);
  bezierVertex(cx + 165, cy - 80, cx - 130, cy - 82, cx - 330, cy - 35);
  endShape(CLOSE);

  drawingContext.shadowBlur = 0;

  for (let i = 0; i < 90; i++) {
    stroke(114, 83, 58, random(15, 70));
    strokeWeight(random(1, 7));
    const x = random(cx - 310, cx + 365);
    const y = random(cy - 61, cy + 32);
    line(x, y, x + random(20, 100), y + random(-4, 4));
  }

  stroke(14, 14, 13);
  strokeWeight(13);
  line(cx + 235, cy - 35, cx + 560, cy + 260);

  stroke(75, 59, 45, 150);
  strokeWeight(4);
  line(cx + 240, cy - 39, cx + 560, cy + 256);
}

