function drawMoth(x, y, s, angle) {
  push();
  translate(x, y);
  rotate(angle);
  noStroke();

  fill(235, 216, 174, random(90, 210));
  beginShape();
  vertex(-s * 0.08, 0);
  bezierVertex(-s * 0.6, -s * 0.75, -s, -s * 0.15, -s * 0.28, s * 0.12);
  bezierVertex(-s * 0.8, s * 0.15, -s * 0.5, s * 0.72, -s * 0.05, s * 0.18);
  endShape(CLOSE);

  beginShape();
  vertex(s * 0.08, 0);
  bezierVertex(s * 0.6, -s * 0.75, s, -s * 0.15, s * 0.28, s * 0.12);
  bezierVertex(s * 0.8, s * 0.15, s * 0.5, s * 0.72, s * 0.05, s * 0.18);
  endShape(CLOSE);

  fill(75, 61, 51, 190);
  ellipse(0, 0, s * 0.13, s * 0.65);
  pop();
}

