  let horizonColor = color(130, 73, 61);

  strokeWeight(2);
  for (let y = 0; y < 900; y++) {
    let c;
    if (y < 590) {
      c = lerpColor(topColor, middleColor, y / 590);
    } else {
      c = lerpColor(middleColor, horizonColor, (y - 590) / 310);
    }
    stroke(c);
    line(0, y, width, y);
  }

  for (let i = 0; i < 18000; i++) {
    let x = random(width);
