function riverCenter(y) {
  let t = constrain((y - 850) / 1150, 0, 1);
  return 830 + sin(t * 2.4) * 55 - 35 * t;
}

function riverHalfWidth(y) {
  let t = constrain((y - 850) / 1150, 0, 1);
  return 35 + pow(t, 1.5) * 700;
}

function paintRiver() {
  noStroke();
  fill(28, 38, 50);

  beginShape();
  for (let y = 845; y <= height; y += 18) {
    vertex(riverCenter(y) - riverHalfWidth(y), y);
  }
  for (let y = height; y >= 845; y -= 18) {
    vertex(riverCenter(y) + riverHalfWidth(y), y);
  }
  endShape(CLOSE);

  for (let i = 0; i < 13500; i++) {
    let y = random(860, height);
    let c = riverCenter(y);
    let h = riverHalfWidth(y);
    let x = random(c - h, c + h);
    let glow = exp(-sq((x - 1000) / max(100, h * 0.8)));
    let horizonGlow = map(y, 860, height, 1, 0.15);
    let len = random(5, 65) * map(y, 860, height, 0.25, 1);

    stroke(
      65 + glow * 100,
      73 + glow * 72,
      83 + glow * 48,
      random(8, 48) * horizonGlow + 5
    );
    strokeWeight(random(0.5, 3.5));
    line(x - len * 0.5, y, x + len * 0.5, y + random(-2, 2));
  }

  for (let i = 0; i < 720; i++) {
    let y = random(900, 1900);
    let c = riverCenter(y);
    let h = riverHalfWidth(y);
    let x = random(c - h * 0.65, c + h * 0.65);
    let len = random(12, 100);

    stroke(209, 137, 91, random(4, 28));
    strokeWeight(random(1, 4));
    line(x - len / 2, y, x + len / 2, y);
  }
}

function paintBanks() {
  for (let i = 0; i < 12500; i++) {
    let y = random(880, height);
    let c = riverCenter(y);
    let h = riverHalfWidth(y);
    let leftSide = random() < 0.5;
    let x;

    if (leftSide) {
      x = random(0, max(0, c - h));
    } else {
      x = random(min(width, c + h), width);
    }

    let edgeDistance = leftSide ? c - h - x : x - c - h;
    let edgeLight = exp(-edgeDistance / 90);

    stroke(
      40 + edgeLight * 40,
      38 + edgeLight * 29,
      32 + edgeLight * 20,
      random(8, 38)
    );
    strokeWeight(random(1, 6));
    line(x, y, x + random(-14, 14), y + random(-8, 8));
  }

  strokeCap(ROUND);
  for (let y = 910; y < height; y += random(7, 15)) {
    let c = riverCenter(y);
    let h = riverHalfWidth(y);

    stroke(105, 75, 54, random(20, 60));
    strokeWeight(random(1, 5));
    line(c - h - random(3, 25), y, c - h + random(2, 14), y);
    line(c + h - random(2, 14), y, c + h + random(3, 25), y);
  }
}

function paintTree() {
  strokeCap(ROUND);

  for (let i = 0; i < 24; i++) {
    stroke(8, 9, 11, 150);
    strokeWeight(48 - i * 1.5);
    line(340 + i * 0.7, 1740, 420 - i * 0.4, 1190);
  }

  drawBranch(405, 1290, 240, -1.83, 34, 7);
  drawBranch(392, 1395, 255, -2.3, 28, 7);
  drawBranch(414, 1360, 225, -1.12, 26, 7);
  drawBranch(388, 1500, 235, -2.55, 23, 6);

  noStroke();
  fill(5, 7, 9, 180);
  ellipse(354, 1740, 270, 75);

  for (let i = 0; i < 160; i++) {
    let x = random(230, 500);
    let y = random(1685, 1780);
    stroke(32, 28, 24, random(20, 70));
    strokeWeight(random(2, 8));
    line(x, y, x + random(-35, 35), y + random(-5, 8));
  }
}

function drawBranch(x, y, len, angle, weightValue, depth) {
  if (depth <= 0 || len < 8) return;

  let x2 = x + cos(angle) * len;
  let y2 = y + sin(angle) * len;

  stroke(7, 8, 10, 235);
  strokeWeight(max(1, weightValue));
  line(x, y, x2, y2);

  stroke(78, 59, 47, 35);
  strokeWeight(max(0.7, weightValue * 0.22));
  line(x + 2, y, x2 + 2, y2);

  let split = depth > 3 ? 2 : int(random(1, 3));
  for (let i = 0; i < split; i++) {
    let turn = random(0.28, 0.64) * (i % 2 === 0 ? -1 : 1);
    drawBranch(
      x2,
      y2,
      len * random(0.58, 0.76),
      angle + turn + random(-0.12, 0.12),
      weightValue * 0.62,
      depth - 1
    );
  }

  if (depth > 4 && random() < 0.65) {
    drawBranch(
      lerp(x, x2, random(0.35, 0.7)),
      lerp(y, y2, random(0.35, 0.7)),
      len * random(0.35, 0.5),
      angle + random(-1, 1),
      weightValue * 0.42,
      depth - 2
    );
  }
}

