function mountainLayer(baseY, peakHeight, col, roughness) {
  noStroke();
  fill(col);
  beginShape();
  vertex(0, 1260);
  for (let x = 0; x <= width; x += 28) {
    const edgeRise = pow(abs(x - width / 2) / (width / 2), 1.25);
    const n = noise(x * roughness, baseY * 0.002);
    const y = baseY - edgeRise * peakHeight - n * 90;
    vertex(x, y);
  }
  vertex(width, 1260);
  endShape(CLOSE);
}

function paintMountains() {
  mountainLayer(1220, 510, color(23, 20, 29), 0.003);
  mountainLayer(1245, 350, color(18, 18, 25), 0.005);
  mountainLayer(1260, 210, color(12, 15, 20), 0.008);

  stroke(134, 85, 69, 24);
  for (let i = 0; i < 170; i++) {
    const side = random() < 0.5 ? random(0, 500) : random(1100, 1600);
    const y = random(800, 1210);
    strokeWeight(random(1, 5));
    line(side, y, side + random(-60, 60), y + random(20, 100));
  }
}

function paintWater() {
  noStroke();
  fill(8, 13, 19);
  rect(0, 1210, width, 790);

  for (let y = 1210; y < height; y += 4) {
    const t = map(y, 1210, height, 0, 1);
    const c = lerpColor(color(30, 31, 39), color(5, 9, 13), t);
    stroke(c);
    strokeWeight(5);
    line(0, y, width, y);
  }

  for (let i = 0; i < 1300; i++) {
    const y = random(1220, 1970);
    const x = random(-100, 1600);
    const near = map(y, 1220, 1970, 0.3, 1.6);
    const w = random(15, 150) * near;
    const warm = random() < 0.23;
    if (warm) {
