function paintSky() {
  let top = color(14, 20, 22);
  let middle = color(73, 67, 58);
  let horizon = color(157, 139, 107);

  noStroke();
  for (let y = 0; y < 1260; y += 3) {
    let t = y / 1260;
    let c = t < 0.68
      ? lerpColor(top, middle, t / 0.68)
      : lerpColor(middle, horizon, (t - 0.68) / 0.32);

    fill(red(c), green(c), blue(c), 255);
    rect(0, y, width, 4);
  }

  blendMode(SCREEN);
  for (let i = 0; i < 3000; i++) {
    let y = random(80, 1230);
    let x = random(-100, width);
    let n = noise(x * 0.003, y * 0.006);
    let len = random(15, 170) * n;
    let a = random(2, 13);
    stroke(206, 190, 156, a);
    strokeWeight(random(1, 5));
    line(x, y, x + len, y + random(-5, 5));
  }
  blendMode(BLEND);

  for (let i = 0; i < 700; i++) {
    let x = random(width);
    let y = random(125, 1180);
    let d = random(2, 13);
    noStroke();
    fill(29, 35, 35, random(7, 25));
    ellipse(x, y, d * random(2, 9), d);
  }
}

function paintEclipse() {
  push();
  translate(800, 425);

  noFill();
  for (let r = 420; r > 245; r -= 5) {
    let a = map(r, 420, 245, 0, 24);
    stroke(220, 198, 150, a);
    strokeWeight(random(3, 11));
    arc(
      random(-8, 8),
      random(-8, 8),
      r,
      r,
      random(TWO_PI),
      random(TWO_PI) + random(PI, TWO_PI)
    );
  }

  blendMode(SCREEN);
  noStroke();
  for (let i = 0; i < 800; i++) {
    let a = random(TWO_PI);
    let r = random(128, 220);
    let x = cos(a) * r;
    let y = sin(a) * r;
    fill(237, 211, 157, random(4, 18));
    ellipse(x, y, random(8, 45), random(2, 10));
  }
  blendMode(BLEND);

  noStroke();
  fill(8, 10, 10);
  ellipse(0, 0, 270, 270);

  for (let i = 0; i < 350; i++) {
    let a = random(TWO_PI);
    let r = sqrt(random()) * 128;
    let x = cos(a) * r;
    let y = sin(a) * r;
    fill(42, 42, 38, random(5, 24));
    ellipse(x, y, random(2, 12));
  }
  pop();
}

