function paintRiver() {
  noStroke();
  fill(116, 121, 108, 145);
  beginShape();
  vertex(735, 1040);
  bezierVertex(650, 1190, 860, 1270, 690, 1430);
  bezierVertex(560, 1550, 370, 1700, 170, 2000);
