  blendMode(SCREEN);
  for (let i = 0; i < 1000; i++) {
    let y = random(1070, 1980);
    let t = map(y, 1070, 1980, 0, 1);
    let center = lerp(800, 650, t) + sin(y * 0.013) * 80 * t;
    let halfWidth = lerp(70, 480, t);
    let x = center + random(-halfWidth, halfWidth);
    let edge = abs(x - center) / halfWidth;
    stroke(206, 201, 172, random(4, 30) * (1 - edge));
    strokeWeight(random(1, 5));
    line(x, y, x + random(10, 85), y + random(-4, 4));
