function paintForest() {
  let trees = [
    [80, 1300, 290, -0.08],
    [250, 1260, 340, 0.06],
    [430, 1235, 245, -0.04],
    [1160, 1240, 260, 0.05],
    [1360, 1280, 365, -0.05],
    [1530, 1320, 300, 0.07]
  ];

  for (let i = 0; i < trees.length; i++) {
    push();
    translate(trees[i][0], trees[i][1]);
    rotate(trees[i][3]);
    drawLimb(trees[i][2], 6, 20);
    pop();
  }

  for (let i = 0; i < 12; i++) {
    let x = map(i, 0, 11, 0, width) + random(-55, 55);
    push();
    translate(x, random(1110, 1210));
    drawLimb(random(90, 160), 4, 8);
    pop();
  }
}

function drawLimb(len, depth, weight) {
  stroke(18, 21, 19, 235);
  strokeWeight(weight);
  strokeCap(ROUND);
  line(0, 12, 0, -len);

  stroke(111, 99, 76, 40);
  strokeWeight(max(1, weight * 0.18));
  line(-weight * 0.2, 5, -weight * 0.15, -len);

  translate(0, -len);
  if (depth <= 0) return;

  let branches = depth > 4 ? 3 : 2;
  for (let i = 0; i < branches; i++) {
    push();
    let side = i % 2 === 0 ? -1 : 1;
    rotate(side * random(0.28, 0.72) + random(-0.1, 0.1));
    drawLimb(
      len * random(0.57, 0.76),
      depth - 1,
      max(1, weight * 0.67)
    );
    pop();
  }
}

