    stroke(57, 58, 51, random(8, 42));
    strokeWeight(random(1, 5));
    bezier(
      x,
      y,
      x + random(-30, 30),
      y + random(30, 90),
      x + random(-40, 40),
      y + random(70, 160),
      x + random(-25, 25),
      y + random(100, 220)
    );
  }

  blendMode(SCREEN);
  for (let i = 0; i < 180; i++) {
    let y = random(120, 650);
    let spread = map(y, 120, 650, 45, 170);
    let x = random(-spread, spread);
