function paintAsh() {
  for (let i = 0; i < 900; i++) {
    let t = random();
    let y = lerp(1040, 470, t);
    let spread = lerp(170, 42, t) + sin(t * 10) * 35;
    let x = 800 + randomGaussian() * spread;
    let d = random(1, 8) * (1.2 - t * 0.5);

    noStroke();
    if (random() < 0.25) {
      fill(218, 204, 172, random(20, 90));
    } else {
      fill(35, 37, 34, random(25, 120));
    }
    ellipse(x, y, d * random(0.5, 2.4), d);
  }

  noFill();
  for (let i = 0; i < 90; i++) {
    let x = random(660, 940);
    let y = random(620, 1090);
    stroke(194, 180, 148, random(8, 35));
    strokeWeight(random(1, 3));
    bezier(
      x,
      y,
      x + random(-90, 90),
      y - 90,
      x + random(-120, 120),
      y - 190,
      800 + random(-80, 80),
      y - 300
    );
  }
}

function paintForeground() {
