function paintSurface() {
  blendMode(MULTIPLY);
  for (let i = 0; i < 5000; i++) {
    let x = random(width);
    let y = random(height);
    stroke(40, 29, 21, random(2, 15));
    strokeWeight(random(1, 4));
    line(x, y, x + random(-18, 18), y + random(-3, 3));
  }
  blendMode(BLEND);

  for (let i = 0; i < 9000; i++) {
    let x = random(width);
    let y = random(height);
    let bright = random() < 0.35;
    noStroke();
    if (bright) {
      fill(238, 224, 190, random(2, 12));
    } else {
      fill(5, 7, 7, random(2, 15));
    }
    ellipse(x, y, random(0.5, 3), random(0.5, 3));
  }
