function paintVignette() {
  noFill();
  for (let i = 0; i < 180; i++) {
    let a = map(i, 0, 179, 0, 10);
    stroke(0, 0, 0, a);
    strokeWeight(14);
    rect(i * 3, i * 3, width - i * 6, height - i * 6, 30);
  }

  blendMode(MULTIPLY);
  noStroke();
  fill(7, 9, 8, 75);
  rect(0, 0, width, 35);
  rect(0, height - 45, width, 45);
  rect(0, 0, 35, height);
  rect(width - 35, 0, 35, height);
  blendMode(BLEND);
}

