}

function paintBackground() {
  colorMode(RGB, 255);

  let topColor = color(12, 8, 18);
  let middleColor = color(42, 18, 27);
  let bottomColor = color(8, 9, 14);

  for (let y = 0; y < height; y++) {
    let c;
    if (y < 1150) {
      c = lerpColor(topColor, middleColor, y / 1150);
    } else {
      c = lerpColor(middleColor, bottomColor, (y - 1150) / 850);
    }
    stroke(c);
    line(0, y, width, y);
  }

  noStroke();
  for (let i = 0; i < 520; i++) {
    let x = random(-200, width + 200);
    let y = random(50, 1500);
    let w = random(120, 620);
    let h = random(20, 150);
    let n = noise(x * 0.002, y * 0.002);
    fill(80 + 45 * n, 24 + 20 * n, 36 + 22 * n, random(2, 9));
    ellipse(x, y, w, h);
  }

  strokeWeight(1);
  for (let i = 0; i < 330; i++) {
    let x = random(width);
    let y = random(200, 1420);
    let len = random(40, 280);
    stroke(119, 53, 62, random(3, 14));
    line(x, y, x + random(-10, 10), y + len);
  }

  noStroke();
