    strokeWeight(random(1, 7));
    ellipse(cx, cy, rr * 2, rr * 2);
  }

  for (let i = 0; i < 240; i++) {
    let a = random(TWO_PI);
    let inner = r + random(4, 35);
    let outer = inner + pow(random(1), 2) * 220;
    stroke(
      random(145, 230),
      random(75, 142),
      random(40, 83),
      random(8, 34)
