  blendMode(BLEND);

  noStroke();
  for (let rr = r; rr > 0; rr -= 3) {
    let t = rr / r;
    fill(3 + 7 * t, 3 + 3 * t, 8 + 9 * t);
    ellipse(cx, cy, rr * 2, rr * 2);
