  noFill();
  stroke(237, 176, 103, 180);
  strokeWeight(5);
  ellipse(cx, cy, r * 2 + 7, r * 2 + 7);

  stroke(255, 213, 145, 105);
  strokeWeight(2);
  arc(cx, cy, r * 2 + 15, r * 2 + 15, -1.1, 1.5);

  noStroke();
  for (let i = 0; i < 95; i++) {
    let a = random(TWO_PI);
    let d = sqrt(random()) * (r - 18);
    let s = random(1, 5);
    fill(85, 51, 50, random(8, 38));
