    let x = centerX + randomGaussian() * spread;
    let size = lerp(30, 6, t) * random(0.65, 1.5);
    let a = random(-0.8, 0.8);

    drawMoth(x, y, size, a, random(0.5, 1));
  }

  blendMode(BLEND);

  for (let i = 0; i < 28; i++) {
    let t = random();
    let x = lerp(690, 1080, t) + randomGaussian() * 130;
