function drawMoth(x, y, s, angle, glow) {
  push();
  translate(x, y);
  rotate(angle);

  noStroke();
  fill(248, 198, 119, 22 * glow);
  ellipse(0, 0, s * 3.4, s * 2.2);

  fill(234, 190, 123, 115 + 90 * glow);
  beginShape();
  vertex(-s * 0.08, 0);
  bezierVertex(-s * 0.5, -s * 0.85, -s * 1.15, -s * 0.72, -s, -s * 0.12);
  bezierVertex(-s * 0.82, s * 0.28, -s * 0.35, s * 0.22, -s * 0.08, 0);
  endShape(CLOSE);

  beginShape();
  vertex(s * 0.08, 0);
  bezierVertex(s * 0.5, -s * 0.85, s * 1.15, -s * 0.72, s, -s * 0.12);
  bezierVertex(s * 0.82, s * 0.28, s * 0.35, s * 0.22, s * 0.08, 0);
  endShape(CLOSE);

  fill(194, 127, 80, 180);
  ellipse(0, 0, s * 0.18, s * 0.7);

  stroke(231, 183, 116, 130);
  strokeWeight(max(0.5, s * 0.035));
  line(-s * 0.03, -s * 0.3, -s * 0.22, -s * 0.62);
  line(s * 0.03, -s * 0.3, s * 0.22, -s * 0.62);

  pop();
}

