  for (let x = 0; x <= width; x += 12) {
    let broad = noise(seedOffset + x * 0.0017);
    let fine = noise(seedOffset + 10 + x * 0.007);
    let y = baseY - broad * peakHeight - fine * 45;
    vertex(x, y);
  }

  vertex(width, height);
  endShape(CLOSE);
}

