function branch(x, y, len, angle, weight, depth) {
  if (depth <= 0 || len < 13) return;

  let x2 = x + cos(angle) * len;
  let y2 = y + sin(angle) * len;

  stroke(9, 9, 11, 230);
  strokeWeight(max(2, weight));
  line(x, y, x2, y2);

  let bend = random(0.24, 0.48);
  branch(
    x2,
    y2,
    len * random(0.65, 0.78),
    angle - bend,
    weight * 0.68,
    depth - 1
  );
  branch(
    x2,
    y2,
    len * random(0.6, 0.75),
    angle + bend * random(0.8, 1.35),
    weight * 0.63,
    depth - 1
  );

  if (random() < 0.36) {
    branch(
      x2,
      y2,
      len * 0.5,
      angle + random(-0.18, 0.18),
      weight * 0.45,
      depth - 2
    );
  }
}

