function drawSky() {
  const top = color(8, 10, 18);
  const middle = color(47, 25, 31);
  const bottom = color(111, 49, 35);

  noFill();
  for (let y = 0; y < height; y += 2) {
    let c;
    if (y < 1150) {
      c = lerpColor(top, middle, y / 1150);
    } else {
      c = lerpColor(middle, bottom, (y - 1150) / 850);
    }
    stroke(c);
    strokeWeight(3);
    line(0, y, width, y);
  }

  strokeWeight(2);
  for (let i = 0; i < 330; i++) {
    const x = random(width);
