function drawBranch(x, y, len, angle, depth) {
  if (depth <= 0 || len < 10) return;

  const x2 = x + cos(angle) * len;
  const y2 = y + sin(angle) * len;

  stroke(8, 9, 12, 245);
  strokeWeight(max(2, depth * 3.1));
  line(x, y, x2, y2);

  const spread = random(0.28, 0.58);
  drawBranch(
    x2, y2,
    len * random(0.61, 0.77),
    angle - spread,
    depth - 1
  );
  drawBranch(
    x2, y2,
    len * random(0.58, 0.74),
    angle + spread * random(0.75, 1.2),
    depth - 1
  );

  if (depth > 3 && random() < 0.46) {
    drawBranch(
      lerp(x, x2, 0.62),
      lerp(y, y2, 0.62),
      len * 0.42,
      angle + random(-0.9, 0.9),
      depth - 2
    );
  }
}

