      sin(t * 16.0) * (190 - t * 90) +
      random(-85, 85);
    const s = lerp(27, 9, t) * random(0.7, 1.35);
    moth(x, y, s, random(-0.7, 0.7), 65 + t * 110);
  }

  for (let i = 0; i < 20; i++) {
    const a = random(TWO_PI);
    const r = random(180, 290);
    const x = 795 + cos(a) * r;
    const y = 525 + sin(a) * r;
    moth(x, y, random(5, 11), a + HALF_PI, random(80, 170));
  }

  noStroke();
  for (let i = 0; i < 260; i++) {
    const t = random();
    const x = lerp(520, 800, t) +
      sin(t * 20) * random(20, 170);
    const y = lerp(1580, 600, t) + random(-90, 90);
    fill(219, 183, 125, random(15, 80));
