function moth(x, y, s, angle, alphaValue) {
  push();
  translate(x, y);
  rotate(angle);

  noStroke();
  fill(211, 190, 151, alphaValue);

  beginShape();
  vertex(-1, -1);
  bezierVertex(-s * 0.45, -s * 0.76, -s, -s * 0.55, -s * 0.78, 0);
  bezierVertex(-s * 0.58, s * 0.26, -s * 0.2, s * 0.16, -1, 3);
  endShape(CLOSE);

  beginShape();
  vertex(1, -1);
  bezierVertex(s * 0.45, -s * 0.76, s, -s * 0.55, s * 0.78, 0);
  bezierVertex(s * 0.58, s * 0.26, s * 0.2, s * 0.16, 1, 3);
  endShape(CLOSE);

  fill(20, 18, 19, min(220, alphaValue + 60));
  ellipse(0, 0, max(2, s * 0.14), s * 0.75);
  circle(0, -s * 0.38, max(2, s * 0.18));
  pop();
}

