function branch(len, angle, depth, weight) {
  if (depth <= 0 || len < 10) return;

  push();
  rotate(angle);

  stroke(7, 10, 11, 235);
  strokeWeight(max(1, weight));
  line(0, 0, len, 0);
  translate(len, 0);

  if (depth > 2) {
    noStroke();
    fill(14, 12, 11, 160);
    ellipse(-len * 0.32, 0, len * 0.22, weight * 1.5);
  }

  let split = depth > 5 ? 3 : 2;
  for (let i = 0; i < split; i++) {
    let bend;
    if (i === 0) bend = random(-0.68, -0.22);
    else if (i === 1) bend = random(0.20, 0.64);
    else bend = random(-0.12, 0.15);

    branch(
      len * random(0.58, 0.76),
      bend,
      depth - 1,
      weight * 0.67
    );
  }
  pop();
}

