    );

    let ly = lerp(s[1], s[3], 0.55);
    let lx = lerp(s[0], s[2], 0.55);
    strokeWeight(3);
    line(lx, ly, lx + random(-55, 55), ly - random(8, 35));

    flower(s[2], s[3], random(30, 48), i * 0.7);
