function flower(x, y, r, turn) {
  push();
  translate(x, y);
  rotate(turn);

  noStroke();
  for (let i = 0; i < 7; i++) {
    let a = TWO_PI * i / 7;
    push();
    rotate(a);
    fill(104 + random(-12, 14), 22, 24, 220);
    ellipse(r * 0.45, 0, r, r * 0.55);
    pop();
  }

  fill(45, 18, 17);
  circle(0, 0, r * 0.5);

  fill(178, 126, 67, 180);
  for (let i = 0; i < 11; i++) {
    let a = random(TWO_PI);
    let d = random(r * 0.07, r * 0.2);
    circle(cos(a) * d, sin(a) * d, random(2, 5));
  }
  pop();
}

function paintMoths() {
