    let y = lerp(1390, 260, t) + random(-32, 32);
    let centerX = lerp(660, 1010, pow(t, 0.8));
    let spread = lerp(32, 190, t);
    let x = centerX + randomGaussian() * spread;
    let size = lerp(29, 9, t) * random(0.7, 1.35);
    let angle = random(-0.8, 0.8);
    moth(x, y, size, angle, random(90, 210));
  }

  for (let i = 0; i < 18; i++) {
    let a = random(TWO_PI);
    let r = random(235, 315);
    let x = 1010 + cos(a) * r;
    let y = 570 + sin(a) * r;
    moth(x, y, random(5, 11), a + HALF_PI, random(50, 120));
