}

function moth(x, y, s, angle, alpha) {
  push();
  translate(x, y);
  rotate(angle);

  noStroke();
  fill(225, 217, 188, alpha);

  beginShape();
  vertex(-1, 0);
  bezierVertex(-s * 0.3, -s * 0.95, -s * 1.05, -s * 0.72, -s, -s * 0.08);
  bezierVertex(-s * 0.9, s * 0.42, -s * 0.28, s * 0.35, -1, 0);
  endShape(CLOSE);

  beginShape();
  vertex(1, 0);
  bezierVertex(s * 0.3, -s * 0.95, s * 1.05, -s * 0.72, s, -s * 0.08);
  bezierVertex(s * 0.9, s * 0.42, s * 0.28, s * 0.35, 1, 0);
  endShape(CLOSE);

  fill(45, 41, 35, alpha);
  ellipse(0, 0, s * 0.16, s * 0.9);

  stroke(211, 201, 171, alpha * 0.7);
  strokeWeight(max(0.5, s * 0.035));
  line(-1, -s * 0.4, -s * 0.25, -s * 0.72);
  line(1, -s * 0.4, s * 0.25, -s * 0.72);

  pop();
}

