function paintSky() {
  const top = color(7, 10, 18);
  const middle = color(28, 31, 43);
  const bottom = color(67, 38, 39);

  for (let y = 0; y < 1120; y++) {
    let c;
    if (y < 760) {
      c = lerpColor(top, middle, y / 760);
    } else {
      c = lerpColor(middle, bottom, (y - 760) / 360);
    }
    stroke(c);
    line(0, y, width, y);
  }

  noStroke();
  for (let i = 0; i < 6500; i++) {
    const x = random(width);
    const y = random(1100);
    const n = noise(x * 0.004, y * 0.004);
    fill(105 + 45 * n, 82 + 26 * n, 80 + 30 * n, random(3, 15));
    ellipse(x, y, random(1, 5), random(1, 4));
  }

  for (let i = 0; i < 170; i++) {
    const x = random(width);
    const y = random(40, 830);
    const a = random(18, 70);
    fill(214, 207, 187, a);
    ellipse(x, y, random(1.5, 4.5));
  }
}

