}

function drawTree(x, y, len, angle, depth) {
  if (depth <= 0 || len < 8) return;

  const x2 = x + cos(angle) * len;
  const y2 = y + sin(angle) * len;

  stroke(8, 10, 13, 245);
  strokeWeight(max(1, depth * 2.5));
  line(x, y, x2, y2);

  const branches = depth > 5 ? 3 : 2;
  for (let i = 0; i < branches; i++) {
    const bend = random(0.18, 0.62) * (i % 2 === 0 ? -1 : 1);
    drawTree(
      x2,
      y2,
      len * random(0.58, 0.75),
      angle + bend,
      depth - 1
    );
  }
}

