function paintAscendingMoths() {
  for (let i = 0; i < 185; i++) {
    const t = i / 184;
    const y = lerp(1370, 500, t) + random(-35, 35);
    const centerX = lerp(790, 1080, t);
    const spread = lerp(260, 95, t);
    const x = centerX + randomGaussian() * spread;
    const s = lerp(22, 5, t) * random(0.55, 1.45);
    const a = lerp(205, 70, t);

    if (random() < 0.62) {
      drawMoth(x, y, s, random(-0.8, 0.8), a);
    } else {
      noStroke();
      fill(220, 213, 191, a);
      ellipse(x, y, s * random(0.15, 0.5), s * random(0.15, 0.5));
    }
  }
}

function drawMoth(x, y, s, rot, alphaValue) {
  push();
  translate(x, y);
  rotate(rot);
  noStroke();

  fill(220, 211, 187, alphaValue * 0.75);
  beginShape();
  vertex(-s * 0.08, 0);
  bezierVertex(
    -s * 0.55, -s * 0.72,
    -s, -s * 0.22,
    -s * 0.2, s * 0.17
  );
  endShape(CLOSE);

  beginShape();
  vertex(s * 0.08, 0);
  bezierVertex(
    s * 0.55, -s * 0.72,
    s, -s * 0.22,
    s * 0.2, s * 0.17
  );
  endShape(CLOSE);

  fill(82, 76, 67, alphaValue);
  ellipse(0, 0, s * 0.13, s * 0.55);
  pop();
}

