function setup() {
    createCanvas(1600, 2000);
    randomSeed(1);
    noiseSeed(1);
    noLoop();
}

function draw() {
    background(12, 8, 18);

    // Deep atmospheric gradient
    for (let y = 0; y < height; y += 4) {
        let alpha = map(y, 0, height * 0.7, 25, 0);
        stroke(28, 22, 45, alpha);
        line(0, y, width, y);
    }

    // Golden-black nebula layers
    for (let i = 0; i < 7; i++) {
        let yBase = height * 0.35 + i * 85;
        let noiseScale = 0.003 + i * 0.001;

        beginShape();
        noFill();
        stroke(48, 32, 18, 35 - i * 3);
        strokeWeight(180 - i * 18);
        for (let x = 0; x <= width; x += 12) {
            let y = yBase + noise(x * noiseScale, i) * 280 - 140;
            curveVertex(x, y);
        }
        endShape();
    }

    // Central dissolving figure
    let cx = width / 2;
    let cy = height * 0.48;

    // Outer fading silhouette
    for (let r = 420; r > 60; r -= 18) {
        let alpha = map(r, 420, 60, 8, 65);
        stroke(235, 190, 95, alpha);
        strokeWeight(2.5);
        noFill();

        beginShape();
        for (let a = 0; a < TWO_PI; a += 0.02) {
            let x = cx + cos(a) * r * (0.8 + noise(a * 3, r * 0.01) * 0.4);
            let y = cy + sin(a) * r * (1.1 + noise(a * 2.5, r * 0.015) * 0.35) - r * 0.15;
            vertex(x, y);
        }
        endShape(CLOSE);
    }

    // Inner luminous core
    for (let i = 0; i < 5; i++) {
        stroke(255, 225, 140, 22 - i * 3);
        strokeWeight(35 - i * 6);
        noFill();
        ellipse(cx, cy - 35, 210 - i * 28, 310 - i * 45);
    }

    // Particle dissolution
    for (let i = 0; i < 3800; i++) {
        let a = random(TWO_PI);
        let dist = random(80, 520);
        let x = cx + cos(a) * dist * (0.7 + random(0.6));
        let y = cy - 40 + sin(a) * dist * 1.05 + random(-90, 110);

        let size = random(1.5, 4.5);
        let alpha = map(dist, 80, 520, 180, 12);

        fill(255, 235, 170, alpha);
        noStroke();
        circle(x, y, size);

        // Occasional brighter sparks
        if (random() < 0.07) {
            fill(255, 250, 220, 90);
            circle(x, y, random(0.8, 2.2));
        }
    }

    // Very subtle horizontal light bands
    for (let i = 0; i < 9; i++) {
        let y = height * 0.22 + i * 185;
        let w = map(noise(i * 0.3), 0, 1, 800, 1600);
        stroke(255, 240, 190, 7);
        strokeWeight(2);
        line(width/2 - w/2, y, width/2 + w/2, y);
    }
}

