        fill(185, 215, 255, a);
        beginShape();
        for (let ang = 0; ang < TWO_PI; ang += 0.03) {
            let nx = noise(cos(ang)*2 + 5, sin(ang)*2 + 3) * 28 - 14;
            let radius = r + nx + sin(ang * 6) * 22;
            let x = cos(ang) * radius;
            let y = sin(ang) * radius * 1.35 - 90;
            vertex(x, y);
        }
        endShape(CLOSE);
    }

    // Main figure - fading from solid to cosmic dust
    for (let layer = 0; layer < 7; layer++) {
        let t = layer / 6;
        let alpha = map(layer, 0, 6, 255, 18);
        let shrink = map(layer, 0, 6, 1, 0.6);

        fill(235, 245, 255, alpha);
        if (layer === 0) fill(28, 22, 35);

        beginShape();
        for (let a = 0; a < TWO_PI; a += 0.014) {
            let pulse = sin(a * 7 + layer) * (8 - layer * 1.2);
            let x = cos(a) * (92 * shrink + pulse);
            let y = sin(a) * (178 * shrink + pulse * 1.8) - 95;

            // Dissolving lower half
            if (y > -30) {
                y += noise(a * 3, layer) * (layer * 22);
                x *= map(y, -30, 220, 1, 0.3);
            }
            vertex(x, y);
        }
        endShape(CLOSE);
    }

    // Final cosmic dust release
    fill(255, 248, 230, 35);
    for (let i = 0; i < 380; i++) {
        let a = random(TWO_PI);
        let dist = random(115, 355);
        let x = cos(a) * dist;
        let y = sin(a) * dist * 1.4 - 85;
        let sz = random(2.5, 7);
        ellipse(x, y, sz, sz * random(0.6, 1.8));
    }

    pop();

    // Very faint horizontal light band at horizon of existence
    for (let i = 0; i < 6; i++) {
        let y = 740 + i * 9;
        let a = map(i, 0, 5, 22, 3);
        stroke(210, 225, 255, a);
        strokeWeight(11 - i);
        line(0, y, 1600, y);
    }
}

