function drawPainting() {
    background(12, 14, 28);

    // Deep atmospheric base
    for (let i = 0; i < 800; i++) {
        let y = map(i, 0, 800, 0, height);
        let alpha = map(i, 0, 800, 8, 38);
        fill(18, 22, 45, alpha);
        noStroke();
        rect(0, y, width, 4);
    }

    // Vast dissolving veil
    push();
    translate(width/2, height/2 - 80);
    for (let layer = 0; layer < 7; layer++) {
        let r = map(layer, 0, 6, 620, 1180);
        let alpha = map(layer, 0, 6, 22, 3);

        beginShape();
        for (let a = 0; a < TWO_PI; a += 0.008) {
            let x = cos(a) * r;
            let y = sin(a) * r * 0.68;

            let n = noise(cos(a)*2.3, sin(a)*2.3, layer*0.6) * 68 - 34;
            let nx = x + cos(a) * n * (1 + layer*0.3);
            let ny = y + sin(a) * n * 0.7;

            let edgeFade = map(layer, 0, 6, 1, 0.1);
            fill(245, 252, 255, alpha * edgeFade);
            noStroke();
            vertex(nx, ny);
        }
        endShape(CLOSE);
    }
    pop();

    // Gentle horizontal dissolution bands
    for (let i = 0; i < 28; i++) {
        let y = map(i, 0, 27, 280, 1720);
        let w = map(noise(i*0.1), 0, 1, 620, 1380);
        let a = map(i, 0, 27, 18, 3);

        for (let j = 0; j < 4; j++) {
            fill(232, 245, 255, a - j*3);
            noStroke();
            rect(width/2 - w/2 - j*18, y + j*11, w + j*36, 3.5);
        }
    }

    // Ethereal vertical light threads
    for (let i = 0; i < 120; i++) {
        let x = map(i, 0, 119, 180, width-180);
        let baseNoise = noise(i*0.03);
        let thickness = map(baseNoise, 0, 1, 1.2, 4.8);

        for (let t = 0; t < thickness; t += 0.6) {
            let alpha = map(t, 0, thickness, 28, 0);
            stroke(255, 248, 235, alpha);
            strokeWeight(0.8);

            let sway = sin(i*0.07) * 90;
            let topY = 160 + baseNoise * 380;
            let bottomY = height - 140 - noise(i*0.04 + 5) * 420;

            line(x + t*1.6 + sway, topY, x + t*1.2 + sway*0.6, bottomY);
        }
    }

    // Final soft luminous core
    let coreY = height * 0.46;
    for (let r = 420; r > 10; r -= 7) {
        let alpha = map(r, 420, 10, 0, 26);
        fill(255, 252, 240, alpha);
        noStroke();
        ellipse(width/2, coreY, r*1.8, r*0.7);
    }

    // Micro-particle dust of being
    for (let i = 0; i < 2800; i++) {
        let x = random(width);
        let y = random(height * 0.1, height * 0.92);
        let n = noise(x*0.008, y*0.008);
        let size = n * 2.8;
        let a = map(n, 0, 1, 8, 42);

        fill(255, 250, 230, a);
        noStroke();
        circle(x, y, size);
    }
}

