    for (let i = 0; i < 28; i++) {
        let x = random(120, width-120);
        let y = random(height*0.22, height*0.78);
        let sz = random(90, 380);

        for (let j = 0; j < 6; j++) {
            let alpha = map(j, 0, 5, 28, 0);
            stroke(235, 245, 255, alpha);
            strokeWeight(map(j, 0, 5, 4.5, 28));
            noFill();
            beginShape();
            for (let a = 0; a < TWO_PI; a += 0.1) {
                let nx = x + cos(a) * sz * (0.6 + noise(a*2, i)*0.7);
                let ny = y + sin(a) * sz * 0.45 * (0.7 + noise(a*3, i*2)*0.6);
                vertex(nx, ny);
            }
            endShape(CLOSE);
        }
    }

    // Final absolute void — the last light disappearing
    push();
    translate(width/2, height*0.47);
    for (let i = 0; i < 180; i++) {
        let a = i * 0.12;
        let r = 280 + sin(i*0.07)*90;
        let x = cos(a) * r;
        let y = sin(a) * r * 0.55;
        let brightness = map(i, 0, 140, 255, 12);
        fill(brightness, brightness*0.9, 255, 9);
        noStroke();
        circle(x, y, map(i, 0, 160, 22, 1.2));
    }
    pop();

    // Extremely subtle vertical light rays from above — almost imperceptible
    for (let i = 0; i < 9; i++) {
        let x = 280 + i * 140;
        for (let y = 0; y < height*0.6; y += 6) {
            let alpha = map(y, 0, height*0.55, 11, 0);
            stroke(220, 235, 255, alpha);
            strokeWeight(1.5);
            line(x + noise(y*0.02, i)*38, y, x + noise(y*0.02, i)*38, y+8);
        }
    }

    // Final absolute black veil at the bottom — total dissolution
    for (let i = 0; i < 220; i++) {
        let y = height - 80 - i * 7.2;
        let alpha = map(i, 0, 210, 0, 255);
        fill(3, 4, 9, alpha);
        noStroke();
        rect(0, y, width, 28);
    }
}

