    let y2 = sin(ang) * sz * 0.75;
    ellipse(x2, y2, sz * 0.65, sz * 1.1);
    rotate(0.02);
  }

  // Center void
  fill(4, 2, 7);
  noStroke();
  ellipse(0, 0, sz * 0.38, sz * 0.38);
  pop();
}

