        let alpha = map(i, 0, height * 0.75, 20, 255);
        stroke(3, 2, 12, alpha);
        line(0, i, width, i);
    }

    // Extremely soft glowing membrane / threshold
    let centerY = height * 0.48;
    let horizonNoise = 0;

    for (let x = 0; x < width; x += 1) {
        let yBase = centerY + noise(x * 0.0018, 0) * 280 - 140;
        let thickness = 380 + noise(x * 0.0022) * 190;

        for (let dy = -thickness; dy < thickness; dy += 2) {
            let y = yBase + dy;
            let distFromCenter = abs(dy) / thickness;
            let alpha = pow(1 - distFromCenter, 3.2) * 38;
            let brightness = 255 - distFromCenter * 180;

            if (alpha > 0.5) {
                stroke(brightness + 40, brightness + 55, 255, alpha);
                point(x, y);
            }
        }
    }

    // Dissolving human silhouette - extremely soft and almost disappearing
    let formOpacity = 22;
    let points = [];

    for (let i = 0; i < 520; i++) {
        let t = i / 520;
        let baseX = width * 0.5 + sin(t * PI * 2.8) * 110;
        let baseY = centerY - 80 + cos(t * PI * 1.6) * 260;

        let noiseX = noise(t * 4.2, 1) * 68 - 34;
        let noiseY = noise(t * 3.1, 2) * 95 - 47;

        let x = baseX + noiseX;
        let y = baseY + noiseY;

        points.push({x: x, y: y});
    }

    // Render dissolving form with multiple soft layers
    for (let layer = 0; layer < 7; layer++) {
        let off = layer * 0.8;
        let a = formOpacity * (1 - layer * 0.13);

        beginShape();
        noFill();
        stroke(245, 252, 255, a);
        strokeWeight(9.5 - layer * 0.9);

        for (let p of points) {
            let nx = p.x + noise(p.x * 0.012 + off, p.y * 0.012 + off) * (38 - layer * 4);
            let ny = p.y + noise(p.y * 0.015 + off * 1.3, p.x * 0.009) * (52 - layer * 6);
            curveVertex(nx, ny);
        }
        endShape(CLOSE);
    }

    // Final ethereal dust / memory particles
    for (let i = 0; i < 3800; i++) {
        let x = random(0, width);
        let y = random(centerY - 520, centerY + 680);
        let n = noise(x * 0.008, y * 0.008);
        let size = n * 3.2;
        let a = random(8, 46);

        if (random() < 0.3) {
            stroke(220, 245, 255, a);
            strokeWeight(size);
            point(x, y);
        }
    }

    // Very subtle final glow at the threshold
    drawingContext.shadowBlur = 180;
    drawingContext.shadowColor = "rgba(170, 210, 255, 0.13)";
    noFill();
    stroke(210, 235, 255, 18);
    strokeWeight(240);
    ellipse(width/2, centerY + 30, 920, 680);
}

