        fill(255, 198, 92, a);
        ellipse(820, 980, r * 1.4, r * 1.8);
    }

    // Main overlapping organic forms
    let cx1 = 680, cy1 = 920;
    let cx2 = 950, cy2 = 1080;

    // Left soul
    push();
    translate(cx1, cy1);
    rotate(-0.12);
    for (let i = 0; i < 45; i++) {
        let n = noise(i * 0.08, 0.3);
        let radius = 380 + n * 220;
        let alpha = map(i, 0, 44, 95, 12);
        let hueShift = map(i, 0, 44, -12, 28);

        fill(245 + hueShift, 68, 92, alpha);
        beginShape();
        for (let a = 0; a < TWO_PI; a += 0.04) {
            let x = cos(a) * radius * (0.7 + 0.3 * sin(a * 4 + i));
            let y = sin(a) * radius * (0.8 + 0.3 * cos(a * 3 + i * 0.7));
            vertex(x, y);
        }
        endShape(CLOSE);
    }
    pop();

    // Right soul
    push();
    translate(cx2, cy2);
    rotate(0.18);
    for (let i = 0; i < 48; i++) {
        let n = noise(i * 0.07, 1.1);
        let radius = 410 + n * 190;
        let alpha = map(i, 0, 47, 88, 10);
        let hueShift = map(i, 0, 47, -18, 35);

        fill(252 + hueShift, 55, 105, alpha);
        beginShape();
        for (let a = 0; a < TWO_PI; a += 0.035) {
            let x = cos(a) * radius * (0.75 + 0.35 * sin(a * 5 - i * 0.6));
            let y = sin(a) * radius * (0.85 + 0.25 * cos(a * 3.5 + i));
            vertex(x, y);
        }
        endShape(CLOSE);
    }
    pop();

    // Blooming light petals in the center overlap
    push();
    translate(810, 990);
    for (let layer = 0; layer < 7; layer++) {
        let sz = 280 - layer * 22;
        let a = map(layer, 0, 6, 65, 8);
        fill(255, 215, 175, a);
        rotate(0.07);
        for (let i = 0; i < 13; i++) {
            let ang = i * (TWO_PI / 13) + layer * 0.4;
            let x = cos(ang) * sz * 0.65;
            let y = sin(ang) * sz * 0.9;
            push();
            translate(x, y);
            rotate(ang * 1.6);
            ellipse(0, 0, 95, 215);
            pop();
        }
    }
    pop();

    // Delicate glowing particles / pollen
    for (let i = 0; i < 420; i++) {
        let x = 420 + random(0, 1) * 780 + noise(i * 0.2) * 380;
        let y = 520 + random(0, 1) * 920 + noise(i * 0.15 + 5) * 480;
        let sz = random(2.5, 9);
        let a = random(40, 155);
        fill(255, 225, 140, a);
        noStroke();
        ellipse(x, y, sz, sz);

        if (random() < 0.3) {
            fill(255, 240, 210, a * 0.6);
            ellipse(x + random(-18, 18), y + random(-18, 18), sz * 0.6, sz * 0.6);
        }
    }

    // Very soft highlight veil
    fill(255, 245, 230, 18);
    ellipse(790, 930, 520, 780);
}

