    fill(255, 180, 220, alpha);
    noStroke();
    ellipse(width/2, height/2 - 80, 1400 - i*12, 1600 - i*10);
  }

  // Central rose light core
  let cx = width/2;
  let cy = height/2 - 60;

  // Rose petals - warm glowing layers
  push();
  translate(cx, cy);
  for (let layer = 0; layer < 7; layer++) {
    let petalCount = 12 + layer * 3;
    let radius = 180 + layer * 48;
    let hueShift = layer * 8;

    for (let i = 0; i < petalCount; i++) {
      let angle = (TWO_PI / petalCount) * i + layer * 0.2;
      let x = cos(angle) * radius;
      let y = sin(angle) * radius * 0.75;

      let r = map(noise(i * 0.3, layer), 0, 1, 235, 255);
      let g = map(noise(i * 0.4, layer), 0, 1, 110, 195);
      let b = map(noise(i * 0.2, layer), 0, 1, 160, 225);

      fill(r, g, b, 240 - layer * 18);
      noStroke();

      beginShape();
      for (let v = 0; v < 8; v++) {
        let a = angle + (v * 0.8) - 2.2;
        let rad = radius * (0.6 + 0.4 * sin(v * 1.1));
        let px = cos(a) * rad * (1 + layer * 0.08);
        let py = sin(a) * rad * 0.7 * (1 + layer * 0.06);
        vertex(px, py);
      }
      endShape(CLOSE);
    }
  }
  pop();

  // Two embracing figures of light
  // Left figure
  drawLuminousFigure(cx - 210, cy + 80, -0.6, color(255, 235, 210));
  // Right figure
  drawLuminousFigure(cx + 210, cy + 80, 0.6, color(220, 245, 255));

  // Gentle connecting light between them
  for (let i = 0; i < 120; i++) {
    let t = i / 119;
    let x1 = cx - 160 + sin(t * PI) * 40;
    let y1 = cy + 40 + cos(t * PI * 1.3) * 90;
    let x2 = cx + 160 - sin(t * PI) * 40;
    let y2 = cy + 40 + cos(t * PI * 1.3) * 90;

    let alpha = 80 * (1 - abs(t - 0.5) * 1.6);
    stroke(255, 240, 210, alpha);
    strokeWeight(4 + noise(t * 5) * 7);
    line(x1, y1, x2, y2);
  }

  // Sparkles
  fill(255, 250, 240);
  noStroke();
  for (let i = 0; i < 240; i++) {
    let x = random(width);
    let y = random(height * 0.6, height * 1.05);
    let sz = random(1.5, 5);
    let a = random(40, 160);
    fill(255, 245, 230, a);
    ellipse(x, y, sz, sz);
    if (random() < 0.3) {
      fill(200, 240, 255, a * 0.7);
      ellipse(x + random(-30, 30), y + random(-30, 30), sz * 0.6, sz * 0.6);
    }
  }
}

function drawLuminousFigure(x, y, lean, baseCol) {
  push();
  translate(x, y);
  rotate(lean * 0.12);

  // Soft aura
  for (let i = 5; i > 0; i--) {
    fill(red(baseCol), green(baseCol), blue(baseCol), 18);
    ellipse(0, 0, 220 + i * 38, 380 + i * 55);
  }

  // Main silhouette of light
  fill(baseCol);
  beginShape();
  vertex(-38, -165);
  bezierVertex(-75, -95, -88, -20, -52, 95);
  bezierVertex(-35, 165, 35, 175, 68, 98);
  bezierVertex(95, 25, 72, -92, 48, -158);
  bezierVertex(22, -182, -18, -185, -38, -165);
  endShape(CLOSE);

  // Inner brighter core
  fill(255, 252, 245, 230);
  beginShape();
  vertex(-22, -138);
  bezierVertex(-48, -95, -55, -28, -35, 68);
  bezierVertex(-18, 125, 24, 132, 48, 72);
  bezierVertex(65, 18, 52, -85, 31, -135);
  bezierVertex(15, -155, -8, -158, -22, -138);
  endShape(CLOSE);

  pop();
}

