  }

  // Core light
  let coreX = width/2;
  let coreY = height/2 - 40;

  // Radiating warm nebula
  for (let r = 620; r > 80; r -= 18) {
    let n = map(r, 80, 620, 0.6, 0.02);
    let alpha = map(r, 80, 620, 255, 12);
    for (let a = 0; a < TWO_PI; a += 0.007) {
      let x = coreX + cos(a) * r + noise(cos(a)*3, sin(a)*3) * r * n;
      let y = coreY + sin(a) * r * 0.82 + noise(sin(a)*4, cos(a)*4) * r * n * 0.7;
      let sz = map(r, 80, 620, 2.8, 28);
      fill(255, 215, 160, alpha);
      ellipse(x, y, sz, sz * 1.6);
    }
  }

  // Interwoven luminous threads
  strokeWeight(3.5);
  for (let i = 0; i < 380; i++) {
    let t = i * 0.028;
    let radius = 210 + sin(t * 1.3) * 140 + noise(t * 2.1) * 190;
    let x1 = coreX + cos(t * 1.8) * radius;
    let y1 = coreY + sin(t * 2.3) * radius * 0.78;
    let x2 = coreX + cos(t * 1.8 + 0.7) * (radius * 0.6);
    let y2 = coreY + sin(t * 2.3 + 0.7) * (radius * 0.6) * 0.78;

    let hueShift = noise(i * 0.1) * 40 - 8;
    stroke(255, 175 + hueShift, 130, 160);
    line(x1, y1, x2, y2);
  }

  // Delicate glowing particles / seeds of love
  for (let i = 0; i < 5200; i++) {
    let a = random(TWO_PI);
    let r = random(60, 680);
    let nx = noise(i * 0.03) * 80 - 40;
    let ny = noise(i * 0.07) * 60 - 30;
    let x = coreX + cos(a) * r * 0.9 + nx;
    let y = coreY + sin(a) * r * 0.72 + ny;

    let size = random(1.5, 7);
    let brightness = random(180, 255);

    fill(255, 240, brightness, 255);
    noStroke();
    ellipse(x, y, size, size);

    // tiny halos
    if (random() < 0.15) {
      fill(255, 210, 160, 45);
      ellipse(x, y, size * 3.5, size * 3.5);
    }
  }

  // Soft overlapping orbs of connection
  for (let i = 0; i < 48; i++) {
    let angle = (i * 0.42) % TWO_PI;
    let dist = 240 + i * 11.5;
    let x = coreX + cos(angle * 1.6) * dist;
    let y = coreY + sin(angle * 2.1) * dist * 0.65;
    let sz = 48 + noise(i) * 75;

    let grad = drawingContext.createRadialGradient(x, y, 5, x, y, sz * 1.8);
    grad.addColorStop(0, 'rgba(255, 235, 210, 0.9)');
    grad.addColorStop(0.6, 'rgba(255, 165, 120, 0.25)');
    grad.addColorStop(1, 'rgba(180, 60, 90, 0)');
    drawingContext.fillStyle = grad;
    noStroke();
    ellipse(x, y, sz * 2.2, sz * 1.9);
  }

  // Final unifying warm veil
  noFill();
  for (let i = 0; i < 7; i++) {
    stroke(255, 165, 110, 18 - i * 2);
    strokeWeight(90 - i * 9);
    ellipse(coreX, coreY + 90, 920 - i * 35, 1100 - i * 55);
  }
}

