function drawPainting() {
    background(8, 12, 28);

    // Deep cosmic background gradient
    for (let y = 0; y < height; y++) {
        let inter = map(y, 0, height, 0, 1);
        let c = lerpColor(color(8, 12, 28), color(45, 18, 55), inter * 0.6);
        stroke(c);
        line(0, y, width, y);
    }

    // Soft glowing particles / stardust
    for (let i = 0; i < 18000; i++) {
        let x = random(width);
        let y = random(height);
        let n = noise(x * 0.008, y * 0.008);
        let alpha = map(n, 0, 1, 20, 95);
        stroke(255, 240, 210, alpha);
        strokeWeight(random(0.8, 2.4));
        point(x, y);
    }

    // Central glowing core
    let cx = width / 2;
    let cy = height * 0.48;

    // Multiple layered organic rings representing unity of opposites
    for (let r = 420; r > 40; r -= 18) {
        let intensity = map(r, 40, 420, 255, 30);
        let sat = map(r, 40, 420, 80, 240);

        for (let a = 0; a < TWO_PI; a += 0.004) {
            let x = cx + cos(a) * r;
            let y = cy + sin(a) * r * 0.68;

            let noiseVal = noise(cos(a) * 3, sin(a) * 3);
            let offset = noiseVal * 38 - 19;

            let pulse = sin(a * 7 + r * 0.1) * 12;

            let finalX = x + offset + pulse * 0.6;
            let finalY = y + offset * 0.4;

            let col = lerpColor(
                color(255, 180, 90, intensity),
                color(180, 220, 255, intensity * 0.9),
                (r / 420 + noiseVal * 0.6) % 1
            );

            stroke(col);
            strokeWeight(2.8 + noiseVal * 1.6);
            point(finalX, finalY);
        }
    }

    // Delicate ascending spirals of light (the becoming)
    strokeWeight(3.5);
    for (let s = 0; s < 7; s++) {
        let hueShift = s * 18;
        let spiralOffset = s * 24;

        for (let i = 0; i < 680; i++) {
            let t = i / 680 * PI * 5.8;
            let spiralR = map(i, 0, 680, 35, 680);

            let x = cx + cos(t + s * 1.3) * (spiralR + spiralOffset);
            let y = cy - 80 + sin(t + s * 1.3) * (spiralR * 0.62 + spiralOffset * 0.4) - i * 0.95;

            let alpha = map(i, 0, 680, 240, 0);
            let brightness = map(i, 0, 680, 255, 140);

            stroke(255, 215 - hueShift, 180 + hueShift * 0.6, alpha);
            strokeWeight(map(i, 0, 680, 4.2, 0.6));
            point(x, y);
        }
    }

    // Final soft luminous bloom at the center
    for (let i = 0; i < 420; i++) {
        let angle = random(TWO_PI);
        let dist = random(0, 135);
        let x = cx + cos(angle) * dist;
        let y = cy + sin(angle) * dist * 0.6;

        let alpha = map(dist, 0, 135, 180, 0);
        stroke(255, 245, 220, alpha);
        strokeWeight(map(dist, 0, 135, 13, 0.5));
        point(x, y);
    }

    // Very subtle golden threads connecting everything
    stroke(255, 215, 120, 18);
    strokeWeight(1.2);
    for (let i = 0; i < 280; i++) {
        let x1 = cx + random(-380, 380);
        let y1 = cy + random(-520, 420);
        let x2 = cx + random(-280, 280);
        let y2 = cy + random(-380, 280);
        line(x1, y1, x2, y2);
    }
}

