        // petal gradient
        for (let t = 0; t < petalLength; t += 6) {
            let w = petalWidth * (1 - t/petalLength) * 0.95;
            let hue = 348 + sin(t*0.03)*18;
            let sat = 75 + sin(t*0.04)*18;
            let bri = 92 - t*0.08;
            let alph = map(t, 0, petalLength, 92, 12);

            fill(hue, sat, bri, alph);
            noStroke();
            ellipse(t*0.65, 0, w*1.8, w*0.75);
        }
        pop();
    }

    // inner luminous core
    let coreR = 125;
    for (let r = coreR; r > 10; r -= 7) {
        let alpha = map(r, 10, coreR, 95, 12);
        let hueShift = map(r, 10, coreR, -8, 22);
        fill(22 + hueShift, 68, 100, alpha);
        circle(cx, cy, r*2.1);
