        ellipse(heart1x - 6, heartY + 4, sz, sz*0.78);
        ellipse(heart1x + 19, heartY + 4, sz, sz*0.78);
    }

    // heart 2
    for (let i = 0; i < 4; i++) {
        fill(32, 68, 100, 38 - i*9);
        let sz = 78 - i*13;
        ellipse(heart2x - 19, heartY + 4, sz, sz*0.78);
        ellipse(heart2x + 6, heartY + 4, sz, sz*0.78);
    }

    // final soft center glow
    for (let i = 0; i < 6; i++) {
        fill(28, 40, 100, 22 - i*3);
        circle(cx, cy, 92 + i*28);
    }
}

