function drawHeart(x, y, size, coreColor, glowColor) {
    push();
    translate(x, y);
    rotate(0.08);

    // Outer glow
    for (let r = size * 0.92; r > size * 0.45; r -= 18) {
        let alpha = map(r, size * 0.45, size * 0.92, 6, 22);
        fill(hue(glowColor), saturation(glowColor), brightness(glowColor), alpha);
        beginShape();
        for (let a = 0; a < TWO_PI; a += 0.02) {
            let px = size * 0.48 * pow(sin(a), 3);
            let py = -size * 0.4 * (13 * cos(a) - 5 * cos(2*a) - 2 * cos(3*a) - cos(4*a)) / 16;
            vertex(px * (r / size), py * (r / size));
        }
        endShape(CLOSE);
    }

    // Core heart
    fill(coreColor);
    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.015) {
        let px = size * 0.48 * pow(sin(a), 3);
        let py = -size * 0.4 * (13 * cos(a) - 5 * cos(2*a) - 2 * cos(3*a) - cos(4*a)) / 16;
        vertex(px, py);
    }
    endShape(CLOSE);

    pop();
}

