    endShape(CLOSE);

    // Inner soft glow
    fill(0, 0, 100, 35);
    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.03) {
        let r = size / 2 * 0.68;
        let px = r * (16 * pow(sin(a), 3));
        let py = -r * (13 * cos(a) - 5 * cos(2*a) - 2 * cos(3*a) - cos(4*a));
        vertex(px * 0.42, py * 0.42);
    }
    endShape(CLOSE);
    pop();
}

