const MOON = { x: 1240, y: 430, r: 150 };
let tips = [];

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  const ctx = drawingContext;

  let sky = ctx.createLinearGradient(0, 0, 0, height);
  sky.addColorStop(0, '#04050c');
  sky.addColorStop(0.5, '#0a0d1e');
  sky.addColorStop(0.85, '#131026');
  sky.addColorStop(1, '#1a1430');
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, width, height);

  drawStars(ctx);
  drawMoon(ctx);
  drawHills(ctx);
  drawGround(ctx);
  drawTree();
  drawLightSpill(ctx);
  drawDoor(ctx);
  drawSouls();
  drawMist(ctx);
  drawGrain(ctx);
  drawVignette(ctx);
}

function drawStars(ctx) {
  for (let i = 0; i < 260; i++) {
    let x = random(width);
    let y = random(height * 0.82);
    let r = random(0.6, 2.4);
    let a = random(30, 160) / 255;
    ctx.fillStyle = 'rgba(228,234,255,' + a + ')';
    ctx.beginPath();
    ctx.arc(x, y, r, 0, TWO_PI);
    ctx.fill();
  }
}

function drawMoon(ctx) {
  for (let k = 0; k < 10; k++) {
    let r = MOON.r + 30 + k * 42;
    let a = 0.055 * (1 - k / 11) + 0.004;
    ctx.fillStyle = 'rgba(243,233,210,' + a + ')';
    ctx.beginPath();
    ctx.arc(MOON.x, MOON.y, r, 0, TWO_PI);
    ctx.fill();
  }
  let mg = ctx.createRadialGradient(MOON.x - 40, MOON.y - 40, 20, MOON.x, MOON.y, MOON.r);
  mg.addColorStop(0, '#f8f0dc');
  mg.addColorStop(1, '#e6d9bd');
  ctx.fillStyle = mg;
  ctx.beginPath();
  ctx.arc(MOON.x, MOON.y, MOON.r, 0, TWO_PI);
  ctx.fill();
  for (let i = 0; i < 7; i++) {
    let a = random(TWO_PI);
    let d = random(MOON.r * 0.75);
    ctx.fillStyle = 'rgba(185,175,155,0.14)';
    ctx.beginPath();
    ctx.arc(MOON.x + cos(a) * d, MOON.y + sin(a) * d, random(8, 30), 0, TWO_PI);
    ctx.fill();
  }
  ctx.strokeStyle = 'rgba(243,233,210,0.18)';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(MOON.x, MOON.y, MOON.r + 8, 0, TWO_PI);
  ctx.stroke();
}

function drawHills(ctx) {
  ctx.fillStyle = '#10101f';
  ctx.beginShape();
  ctx.vertex(0, 1740);
  for (let x = 0; x <= width; x += 40) {
    ctx.vertex(x, 1715 - noise(x * 0.004 + 100, 7) * 110);
  }
  ctx.vertex(width, 1740);
  ctx.endShape(CLOSE);

  ctx.fillStyle = '#0a0a17';
  ctx.beginShape();
  ctx.vertex(0, 1760);
  for (let x = 0; x <= width; x += 40) {
    ctx.vertex(x, 1730 - noise(x * 0.005 + 300, 3) * 80);
  }
  ctx.vertex(width, 1760);
  ctx.endShape(CLOSE);
}

function drawGround(ctx) {
  let g = ctx.createLinearGradient(0, 1700, 0, height);
  g.addColorStop(0, '#131022');
  g.addColorStop(1, '#050409');
  ctx.fillStyle = g;
  ctx.fillRect(0, 1700, width, height - 1700);
  for (let i = 0; i < 280; i++) {
    let x = random(-100, width);
    let y = random(1700, height);
    let w = random(30, 170);
    let a = random(0.02, 0.06);
    ctx.fillStyle = random() < 0.5 ? 'rgba(200,200,230,' + a + ')' : 'rgba(0,0,0,' + a + ')';
    ctx.fillRect(x, y, w, 1.6);
  }
}

function drawTree() {
  tips = [];
  strokeCap(ROUND);
  branch(470, 1805, -HALF_PI + random(-0.05, 0.05), 300, 46, 10);

  for (let i = 0; i < 6; i++) {
    let ex = 470 + random(-320, 320);
    let ey = 1820 + random(0, 70);
    stroke(12, 14, 24);
    strokeWeight(random(6, 15));
    noFill();
    beginShape();
    vertex(470, 1795);
    quadraticVertex(470 + (ex - 470) * 0.5 + random(-40, 40), 1805 + random(-8, 25), ex, ey);
    endShape();
  }

  stroke(48, 50, 72, 110);
  strokeWeight(5);
  line(458, 1790, 486, 1500);
  strokeWeight(3);
  line(478, 1600, 500, 1380);

  for (let i = 0; i < tips.length; i++) {
    if (random() < 0.22) {
      let t = tips[i];
      push();
      translate(t.x, t.y);
      rotate(random(TWO_PI));
      fill(200 + random(-30, 30), 120 + random(-20, 20), 40, 200);
      noStroke();
      leafShape(random(7, 12));
      pop();
    }
  }
}

function branch(x, y, angle, len, w, depth) {
  if (depth <= 0 || len < 7) {
    tips.push({ x: x, y: y });
    return;
  }
  let x2 = x + cos(angle) * len;
  let y2 = y + sin(angle) * len;
  stroke(12 + random(-3, 4), 14 + random(-3, 4), 25 + random(-4, 5));
  strokeWeight(w);
  line(x, y, x2, y2);
  let n = 2 + floor(random(2));
  for (let i = 0; i < n; i++) {
    let spread = random(0.25, 0.8);
    let na = angle + random(-spread, spread) + (i - (n - 1) / 2) * random(0.3, 0.7);
    branch(x2, y2, na, len * random(0.6, 0.78), max(w * 0.62, 1.2), depth - 1);
  }
}

function leafShape(s) {
  beginShape();
  vertex(0, -s);
  bezierVertex(s * 0.75, -s * 0.35, s * 0.75, s * 0.35, 0, s);
  bezierVertex(-s * 0.75, s * 0.35, -s * 0.75, -s * 0.35, 0, -s);
  endShape(CLOSE);
}

function drawLightSpill(ctx) {
  const dx = 660, dy = 1800, w = 150;
  let lg = ctx.createLinearGradient(0, dy, 0, height);
  lg.addColorStop(0, 'rgba(255,190,100,0.38)');
  lg.addColorStop(0.6, 'rgba(255,170,80,0.12)');
  lg.addColorStop(1, 'rgba(255,160,70,0)');
  ctx.fillStyle = lg;
  ctx.beginPath();
  ctx.moveTo(dx - w / 2 + 12, dy);
  ctx.lineTo(dx + w / 2 - 12, dy);
  ctx.lineTo(dx + w * 2.4, height);
  ctx.lineTo(dx - w * 2.4, height);
  ctx.closePath();
  ctx.fill();

  ctx.save();
  ctx.translate(dx, dy + 40);
  ctx.scale(1, 0.32);
  let rg = ctx.createRadialGradient(0, 0, 10, 0, 0, 300);
  rg.addColorStop(0, 'rgba(255,200,110,0.4)');
  rg.addColorStop(1, 'rgba(255,180,90,0)');
  ctx.fillStyle = rg;
  ctx.beginPath();
  ctx.arc(0, 0, 300, 0, TWO_PI);
  ctx.fill();
  ctx.restore();
}

function drawDoor(ctx) {
  const dx = 660, dy = 1800, w = 150, h = 250;
  let glow = ctx.createRadialGradient(dx, dy - h / 2, 20, dx, dy - h / 2, 430);
  glow.addColorStop(0, 'rgba(255,195,105,0.32)');
  glow.addColorStop(1, 'rgba(255,180,90,0)');
  ctx.fillStyle = glow;
  ctx.beginPath();
  ctx.arc(dx, dy - h / 2, 430, 0, TWO_PI);
  ctx.fill();

  let dg = ctx.createLinearGradient(0, dy - h, 0, dy);
  dg.addColorStop(0, '#ffe9b3');
  dg.addColorStop(0.55, '#ffc46a');
  dg.addColorStop(1, '#e07b2e');
  ctx.beginPath();
  ctx.moveTo(dx - w / 2, dy);
  ctx.lineTo(dx - w / 2, dy - h + w / 2);
  ctx.arc(dx, dy - h + w / 2, w / 2, Math.PI, 0);
  ctx.lineTo(dx + w / 2, dy);
  ctx.closePath();
  ctx.fillStyle = dg;
  ctx.fill();
  ctx.strokeStyle = '#05050a';
  ctx.lineWidth = 12;
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(dx - w / 2 + 16, dy - 6);
  ctx.lineTo(dx - w / 2 + 16, dy - h + w / 2);
  ctx.arc(dx, dy - h + w / 2, w / 2 - 16, Math.PI, 0);
  ctx.lineTo(dx + w / 2 - 16, dy - 6);
  ctx.closePath();
  let ig = ctx.createLinearGradient(0, dy - h, 0, dy);
  ig.addColorStop(0, 'rgba(255,246,220,0.95)');
  ig.addColorStop(1, 'rgba(255,210,130,0.85)');
  ctx.fillStyle = ig;
  ctx.fill();

  ctx.fillStyle = '#140d07';
  ctx.beginPath();
  ctx.arc(dx + 8, dy - 138, 26, 0, TWO_PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(dx + 8 - 13, dy);
  ctx.quadraticCurveTo(dx + 8 - 11, dy - 90, dx + 8 - 9, dy - 122);
  ctx.lineTo(dx + 8 + 9, dy - 122);
  ctx.quadraticCurveTo(dx + 8 + 11, dy - 90, dx + 8 + 13, dy);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(255,220,150,0.85)';
  ctx.lineWidth = 2.5;
  ctx.beginPath();
  ctx.moveTo(dx + 8 + 9, dy - 122);
  ctx.quadraticCurveTo(dx + 8 + 11, dy - 90, dx + 8 + 13, dy);
  ctx.stroke();
}

function drawSouls() {
  const palette = ['#c96a2b', '#d98e3a', '#b85c38', '#e0a94e', '#a84f2e'].map(c => color(c));
  for (let i = 0; i < 52; i++) {
    let sx, sy;
    if (i < 14) {
      sx = 660 + random(-60, 60);
      sy = 1750 + random(-80, 0);
    } else {
      sx = 500 + random(-380, 430);
      sy = 1000 + random(-360, 500);
    }
    let ang = random(TWO_PI);
    let dist = random(180, 380);
    let ex = constrain(MOON.x + cos(ang) * dist, 60, 1540);
    let ey = constrain(MOON.y + sin(ang) * dist * 0.85, 60, 1050);
    let mx = (sx + ex) / 2 + random(-300, 300);
    let my = (sy + ey) / 2 + random(-320, 120);
    let t = random(0.06, 0.97);
    let s = random(10, 22);
    let col = palette[floor(random(palette.length))];

    let it = 1 - t;
    let x = it * it * sx + 2 * it * t * mx + t * t * ex;
    let y = it * it * sy + 2 * it * t * my + t * t * ey;
    let ddx = 2 * it * (mx - sx) + 2 * t * (ex - mx);
    let ddy = 2 * it * (my - sy) + 2 * t * (ey - my);
    let a = atan2(ddy, ddx);

    let leafA = (1 - t) * 235;
    if (leafA > 10) {
      push();
      translate(x, y);
      rotate(a + HALF_PI);
      noStroke();
      fill(col, leafA);
      leafShape(s);
      pop();
    }
    let birdA = t * 245;
    if (birdA > 10) {
      push();
      translate(x, y);
      rotate(a);
      stroke(242, 240, 232, birdA);
      strokeWeight(2.6);
      noFill();
      beginShape();
      vertex(-s, 0);
      quadraticVertex(-s * 0.5, -s * 0.75, 0, 0);
      quadraticVertex(s * 0.5, -s * 0.75, s, 0);
      endShape();
      pop();
    }
  }
}

function drawMist(ctx) {
  for (let i = 0; i < 7; i++) {
    let x = random(width);
    let y = random(1580, 1920);
    let w = random(420, 950);
    let h = random(36, 90);
    for (let k = 3; k >= 1; k--) {
      ctx.fillStyle = 'rgba(165,175,220,' + (0.028 * k) + ')';
      ctx.beginPath();
      ctx.ellipse(x, y, w * (0.6 + 0.2 * k), h * (0.6 + 0.2 * k), 0, 0, TWO_PI);
      ctx.fill();
    }
  }
}

function drawGrain(ctx) {
  for (let i = 0; i < 5200; i++) {
    let x = random(width);
    let y = random(height);
    let a = random(3, 10) / 255;
    ctx.fillStyle = random() < 0.5 ? 'rgba(255,255,255,' + a + ')' : 'rgba(0,0,0,' + a + ')';
    ctx.fillRect(x, y, 1.6, 1.6);
  }
}

function drawVignette(ctx) {
  let vg = ctx.createRadialGradient(width / 2, height * 0.42, 260, width / 2, height * 0.5, 1450);
  vg.addColorStop(0, 'rgba(0,0,0,0)');
  vg.addColorStop(0.7, 'rgba(2,2,10,0.25)');
  vg.addColorStop(1, 'rgba(2,2,8,0.62)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, width, height);
}

const W = 1600;
const H = 2000;
const HOR = 1260;
const MOON = { x: 1150, y: 470, r: 118 };

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(W, H);
  noLoop();
  paint();
}

function paint() {
  paintSky();
  paintStars();
  paintBirds();
  paintMoon();
  paintWater();
  paintTreeline();
  paintReflection();
  paintMist();
  paintBoat();
  paintReeds();
  paintVignette();
  paintGrain();
}

function paintSky() {
  const ctx = drawingContext;
  let g = ctx.createLinearGradient(0, 0, 0, HOR);
  g.addColorStop(0, '#03040a');
  g.addColorStop(0.5, '#0a0e22');
  g.addColorStop(0.8, '#1a2142');
  g.addColorStop(1, '#2c3156');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, HOR);

  let g2 = ctx.createRadialGradient(MOON.x, MOON.y, 30, MOON.x, MOON.y, 640);
  g2.addColorStop(0, 'rgba(246,228,180,0.50)');
  g2.addColorStop(0.35, 'rgba(222,202,162,0.16)');
  g2.addColorStop(1, 'rgba(222,202,162,0)');
  ctx.fillStyle = g2;
  ctx.fillRect(0, 0, W, HOR);

  noStroke();
  for (let i = 0; i < 30; i++) {
    const y = random(50, HOR - 30);
    const x = random(-250, W);
    const w = random(260, 950);
    const h = random(10, 48);
    const warm = dist(x, y, MOON.x, MOON.y) < 520;
    if (warm) fill(235, 215, 170, random(0.03, 0.06));
    else fill(130, 140, 190, random(0.03, 0.07));
    ellipse(x, y, w, h);
  }
}

function paintStars() {
  for (let i = 0; i < 430; i++) {
    const x = random(W);
    const y = random(0, HOR - 24);
    const d = dist(x, y, MOON.x, MOON.y);
    const fade = map(d, MOON.r + 20, 700, 0.1, 1, true);
    const a = random(0.3, 1) * fade;
    const s = random(0.6, 2.4);
    stroke(220, 228, 255, a * 255);
    strokeWeight(s);
    point(x, y);
    if (random() < 0.06) {
      stroke(230, 236, 255, a * 190);
      strokeWeight(0.8);
      const l = s * random(4, 9);
      line(x - l, y, x + l, y);
      line(x, y - l, x, y + l);
    }
  }
  stroke(235, 240, 255, 80);
  strokeWeight(1.6);
  line(230, 170, 425, 252);
  stroke(235, 240, 255, 190);
  strokeWeight(2.6);
  point(427, 253);
}

function paintBirds() {
  noFill();
  stroke(9, 11, 20, 230);
  strokeWeight(2.4);
  const birds = [[300, 420, 15], [362, 452, 11], [252, 472, 9]];
  for (const b of birds) {
    const x = b[0], y = b[1], s = b[2];
    arc(x - s / 2, y, s, s * 0.7, PI, TWO_PI);
    arc(x + s / 2, y, s, s * 0.7, PI, TWO_PI);
  }
}

function paintMoon() {
  noStroke();
  for (let r = MOON.r + 150; r > MOON.r; r -= 6) {
    const t = (r - MOON.r) / 150;
    fill(243, 231, 195, (1 - t) * 26);
    circle(MOON.x, MOON.y, r * 2);
  }
  fill(243, 231, 195);
  circle(MOON.x, MOON.y, MOON.r * 2);
  fill(216, 201, 162, 55);
  circle(MOON.x - MOON.r * 0.35, MOON.y + MOON.r * 0.32, MOON.r * 1.5);
  fill(206, 190, 150, 65);
  circle(MOON.x - 30, MOON.y - 20, 46);
  circle(MOON.x + 34, MOON.y + 26, 30);
  circle(MOON.x + 8, MOON.y - 50, 22);
  circle(MOON.x - 50, MOON.y + 42, 18);
  noFill();
  stroke(252, 246, 222, 150);
  strokeWeight(2.5);
  arc(MOON.x, MOON.y, MOON.r * 2 - 4, MOON.r * 2 - 4, -PI * 0.85, PI * 0.45);
}

function paintWater() {
  const ctx = drawingContext;
  let g = ctx.createLinearGradient(0, HOR, 0, H);
  g.addColorStop(0, '#323b6b');
  g.addColorStop(0.1, '#1d2347');
  g.addColorStop(0.4, '#0e1229');
  g.addColorStop(1, '#04050c');
  ctx.fillStyle = g;
  ctx.fillRect(0, HOR, W, H - HOR);

  let g2 = ctx.createLinearGradient(0, HOR, 0, HOR + 160);
  g2.addColorStop(0, 'rgba(238,220,175,0.13)');
  g2.addColorStop(1, 'rgba(238,220,175,0)');
  ctx.fillStyle = g2;
  ctx.fillRect(0, HOR, W, 160);

  for (let i = 0; i < 1000; i++) {
    const y = HOR + 4 + random(H - HOR - 8);
    const nearHor = map(y, HOR, H, 1, 0.2, true);
    if (random() > nearHor) continue;
    const x = random(-60, W);
    const len = random(8, 100) * map(y, HOR, H, 0.5, 1.5, true);
    const a = random(0.03, 0.12) * map(y, HOR, H, 1.8, 0.5, true);
    if (random() < 0.82) stroke(140 + random(-20, 20), 158 + random(-20, 20), 214, a * 255);
    else stroke(90, 105, 160, a * 255);
    strokeWeight(random(1, 2.6));
    line(x, y, x + len, y + random(-1, 1));
  }
}

function paintTreeline() {
  noStroke();
  fill(14, 19, 40);
  beginShape();
  vertex(0, HOR + 2);
  for (let x = 0; x <= W; x += 10) {
    vertex(x, HOR - 24 - noise(x * 0.008, 100) * 48);
  }
  vertex(W, HOR + 2);
  endShape(CLOSE);

  fill(6, 8, 17);
  beginShape();
  vertex(0, HOR + 8);
  for (let x = 0; x <= W; x += 8) {
    vertex(x, HOR - 4 - noise(x * 0.012, 200) * 30);
  }
  vertex(W, HOR + 8);
  endShape(CLOSE);

  fill(5, 7, 14);
  for (let x = 0; x < W; x += random(14, 42)) {
    const h = random(18, 56);
    const baseY = HOR - 2 - noise(x * 0.012, 200) * 30;
    triangle(x, baseY - h, x - h * 0.28, baseY, x + h * 0.28, baseY);
  }
}

function paintReflection() {
  const ctx = drawingContext;
  ctx.save();
  ctx.translate(MOON.x, HOR + 170);
  ctx.scale(1, 1.7);
  let g = ctx.createRadialGradient(0, 0, 20, 0, 0, 540);
  g.addColorStop(0, 'rgba(240,222,170,0.20)');
  g.addColorStop(1, 'rgba(240,222,170,0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(0, 0, 540, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();

  for (let y = HOR + 6; y < H; y += random(4, 9)) {
    const t = (y - HOR) / (H - HOR);
    const halfW = lerp(26, 200, t) * (0.55 + noise(y * 0.02) * 0.9);
    const cx = MOON.x + (noise(y * 0.015, 7) - 0.5) * 70 * t;
    const a = lerp(0.5, 0.08, t) * (0.4 + noise(y * 0.05) * 0.8);
    stroke(242, 226, 178, a * 255);
    strokeWeight(random(1.5, 4.5));
    const len = halfW * random(0.3, 1);
    line(cx - len / 2, y, cx + len / 2, y + random(-1.5, 1.5));
  }
}

function paintMist() {
  noStroke();
  for (let i = 0; i < 5; i++) {
    const y = HOR + 12 + i * 26 + random(-8, 8);
    const w = random(700, 1500);
    const x = random(w / 2, W - w / 2);
    for (let k = 0; k < 4; k++) {
      fill(168, 178, 214, 5 - k);
      ellipse(x, y + k * 3, w - k * 130, 26 - k * 4);
    }
  }
}

function paintBoat() {
  const bx = 520, by = 1560;

  noStroke();
  fill(3, 4, 9, 120);
  beginShape();
  vertex(bx - 130, by + 24);
  vertex(bx + 130, by + 24);
  vertex(bx + 100, by + 95);
  vertex(bx - 100, by + 95);
  endShape(CLOSE);

  noFill();
  stroke(150, 165, 215, 38);
  strokeWeight(1.5);
  for (let i = 1; i <= 3; i++) ellipse(bx, by + 16 + i * 12, 330 + i * 60, 16 + i * 6);

  fill(6, 7, 13);
  beginShape();
  vertex(bx - 135, by - 18);
  bezierVertex(bx - 90, by + 34, bx + 90, by + 34, bx + 135, by - 18);
  bezierVertex(bx + 80, by - 2, bx - 80, by - 2, bx - 135, by - 18);
  endShape(CLOSE);

  noFill();
  stroke(238, 222, 176, 150);
  strokeWeight(2.2);
  beginShape();
  vertex(bx + 132, by - 17);
  bezierVertex(bx + 88, by + 30, bx + 40, by + 26, bx + 8, by + 2);
  endShape();

  noStroke();
  fill(3, 4, 8);
  ellipse(bx, by - 4, 190, 26);

  const cx = bx - 30, cy = by - 8;
  fill(216, 205, 176);
  rect(cx - 5, cy - 30, 10, 30, 3);
  fill(150, 140, 118);
  rect(cx - 5, cy - 30, 4, 30, 2);
  fill(226, 216, 190);
  ellipse(cx + 4, cy - 22, 4, 9);
  stroke(20, 16, 12);
  strokeWeight(2);
  line(cx, cy - 30, cx, cy - 36);

  noFill();
  stroke(120, 110, 90, 190);
  strokeWeight(2);
  for (let i = 0; i < 3; i++) ellipse(bx + 45, by - 6, 34 - i * 8, 12 - i * 3);

  stroke(40, 34, 26);
  strokeWeight(5);
  line(bx - 90, by - 2, bx + 70, by - 14);
  noStroke();
  fill(40, 34, 26);
  ellipse(bx + 78, by - 15, 26, 10);

  paintSmoke(cx, cy - 38);

  noStroke();
  for (let i = 0; i < 7; i++) {
    fill(10, 12, 20, 220);
    ellipse(bx + random(-260, 300), by + random(30, 220), random(8, 16), random(4, 7), random(-0.5, 0.5));
  }
}

function paintSmoke(cx, cy) {
  noStroke();
  const steps = 90;
  for (let i = 0; i < steps; i++) {
    const t = i / steps;
    const x = cx + sin(t * 7 + noise(t * 3) * 4) * 26 * t + t * 150;
    const y = cy - t * 560;
    const r = lerp(3, 16, t) * (0.7 + noise(t * 5) * 0.6);
    const a = lerp(0.3, 0, t) * (0.6 + noise(t * 8) * 0.5);
    fill(198, 205, 224, a * 255);
    circle(x, y, r * 2);
  }
  for (let i = 0; i < 26; i++) {
    const t = random(0.55, 1);
    const x = cx + t * 170 + random(-30, 30) + sin(t * 9) * 20;
    const y = cy - t * 640 - random(0, 60);
    const a = (1 - t) * random(0.4, 0.9);
    const warm = random() < 0.3;
    fill(warm ? 246 : 214, warm ? 230 : 222, warm ? 190 : 248, a * 255);
    circle(x, y, random(1.5, 4));
  }
}

function paintReeds() {
  strokeCap(ROUND);
  const clusters = [
    { x0: -40, x1: 380, n: 46 },
    { x0: 1220, x1: 1660, n: 52 },
    { x0: 620, x1: 980, n: 10 }
  ];
  for (const c of clusters) {
    for (let i = 0; i < c.n; i++) {
      const bx = random(c.x0, c.x1);
      const h = random(120, 330);
      const bend = random(-70, 70);
      const w = random(3, 8);
      const shade = random(4, 12);
      stroke(shade, shade + 2, shade + 8);
      strokeWeight(w);
      noFill();
      const tipX = bx + bend;
      const tipY = H - h;
      beginShape();
      vertex(bx, H + 10);
      quadraticVertex(bx + bend * 0.3, H - h * 0.6, tipX, tipY);
      endShape();
      if (random() < 0.3) {
        noStroke();
        fill(8, 9, 15);
        ellipse(tipX, tipY - 14, w * 1.6, 34);
      }
    }
  }
}

function paintVignette() {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(W / 2, H * 0.46, H * 0.28, W / 2, H * 0.5, H * 0.8);
  g.addColorStop(0, 'rgba(0,0,4,0)');
  g.addColorStop(1, 'rgba(0,0,6,0.6)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
}

function paintGrain() {
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    const n = random(-7, 7);
    pixels[i] = constrain(pixels[i] + n, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + n, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + n, 0, 255);
  }
  updatePixels();
}

const HORIZON = 1420;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  paintSky();
  paintStars();
  paintMoon();
  paintHills();
  paintWater();
  paintMist();
  paintFigure();
  paintRising();
  paintReeds();
  paintGrain();
  paintVignette();
}

function radialGlow(x, y, r, c, aMax) {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0, `rgba(${red(c)},${green(c)},${blue(c)},${aMax})`);
  g.addColorStop(1, `rgba(${red(c)},${green(c)},${blue(c)},0)`);
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(x, y, r, 0, TWO_PI);
  ctx.fill();
}

function paintSky() {
  const top = color(5, 8, 18);
  const hor = color(26, 34, 52);
  noStroke();
  for (let y = 0; y <= HORIZON; y += 3) {
    fill(lerpColor(top, hor, y / HORIZON));
    rect(0, y, width, 3);
  }
}

function paintStars() {
  noStroke();
  for (let i = 0; i < 240; i++) {
    const x = random(width);
    const y = pow(random(), 1.7) * 1300;
    const s = random(0.6, 2.4);
    const a = random(40, 170);
    const r = random();
    if (r < 0.7) fill(220, 228, 245, a);
    else if (r < 0.88) fill(245, 232, 200, a);
    else fill(180, 205, 240, a);
    ellipse(x, y, s, s);
  }
  for (let i = 0; i < 14; i++) {
    const x = random(width);
    const y = random(80, 1100);
    radialGlow(x, y, random(14, 34), color(235, 238, 250), 0.5);
    fill(245, 247, 255, 220);
    ellipse(x, y, 2.4, 2.4);
  }
}

function paintMoon() {
  const mx = 1180, my = 470;
  radialGlow(mx, my, 520, color(226, 216, 190), 0.34);
  radialGlow(mx, my, 240, color(238, 230, 206), 0.55);
