  fill(242, 236, 219);
  ellipse(mx, my, 178, 178);
  noStroke();
  fill(210, 205, 190, 40);
  ellipse(mx - 22, my + 14, 90, 70);
  ellipse(mx + 30, my - 26, 60, 48);
  fill(228, 222, 205, 50);
  ellipse(mx + 10, my + 34, 46, 36);
  fill(10, 14, 24, 55);
  ellipse(mx - 50, my + 62, 280, 42);
  ellipse(mx + 60, my + 30, 200, 30);
}

function paintHills() {
  noStroke();
  fill(18, 24, 38);
  beginShape();
  vertex(0, HORIZON + 4);
  for (let x = 0; x <= width; x += 24) {
