function paintWater() {
  const top = color(15, 22, 36);
  const bot = color(3, 5, 10);
  noStroke();
  for (let y = HORIZON; y <= height; y += 3) {
    fill(lerpColor(top, bot, (y - HORIZON) / (height - HORIZON)));
    rect(0, y, width, 3);
  }
  const ctx = drawingContext;
  const g = ctx.createLinearGradient(0, HORIZON, 0, height);
  g.addColorStop(0, 'rgba(216,200,165,0.14)');
  g.addColorStop(0.6, 'rgba(216,200,165,0.04)');
  g.addColorStop(1, 'rgba(216,200,165,0)');
  ctx.fillStyle = g;
  ctx.fillRect(1010, HORIZON, 340, height - HORIZON);
  noStroke();
  for (let i = 0; i < 1000; i++) {
    const y = random(HORIZON + 4, height - 4);
    const x = random(-40, width);
    const w = random(6, 130);
    const a = random(3, 14);
    const r = random();
    if (r < 0.72) fill(130, 160, 195, a);
    else if (r < 0.92) fill(205, 190, 155, a * 1.4);
    else fill(90, 110, 140, a);
    rect(x, y, w, random(1, 2.2));
  }
  for (let i = 0; i < 340; i++) {
    const y = random(HORIZON + 6, height - 30);
    const spread = 30 + (y - HORIZON) * 0.35;
    const x = 1180 + randomGaussian() * spread;
    const w = random(8, 110) * (0.4 + (y - HORIZON) / 600);
    fill(232, 216, 178, random(6, 26));
    rect(x - w / 2, y, w, random(1.2, 2.6));
  }
}

function paintMist() {
  noStroke();
  for (let i = 0; i < 26; i++) {
    fill(150, 170, 205, random(4, 11));
    ellipse(random(0, width), random(HORIZON - 30, HORIZON + 60), random(220, 640), random(12, 38));
