  paintFigureReflection(fx, fy);
  noStroke();
  fill(7, 9, 15);
  beginShape();
  vertex(fx - 62, fy);
  bezierVertex(fx - 70, fy - 120, fx - 52, fy - 210, fx - 40, fy - 250);
  bezierVertex(fx - 34, fy - 285, fx - 20, fy - 300, fx, fy - 302);
  bezierVertex(fx + 22, fy - 300, fx + 38, fy - 282, fx + 42, fy - 248);
  bezierVertex(fx + 48, fy - 205, fx + 66, fy - 120, fx + 64, fy);
  bezierVertex(fx + 40, fy - 14, fx + 20, fy + 6, fx, fy - 8);
  bezierVertex(fx - 22, fy + 8, fx - 44, fy - 12, fx - 62, fy);
  endShape(CLOSE);
  fill(7, 9, 15);
  ellipse(fx, fy - 268, 52, 60);
  fill(3, 4, 8);
  ellipse(fx - 4, fy - 262, 30, 38);
  noFill();
  stroke(238, 226, 196, 60);
  strokeWeight(9);
  beginShape();
  vertex(fx + 24, fy - 296);
  bezierVertex(fx + 34, fy - 282, fx + 40, fy - 250, fx + 42, fy - 220);
  bezierVertex(fx + 46, fy - 180, fx + 60, fy - 100, fx + 62, fy - 6);
  endShape();
  stroke(238, 226, 196, 150);
  strokeWeight(3);
  beginShape();
  vertex(fx + 24, fy - 296);
  bezierVertex(fx + 34, fy - 282, fx + 40, fy - 250, fx + 42, fy - 220);
  bezierVertex(fx + 46, fy - 180, fx + 60, fy - 100, fx + 62, fy - 6);
  endShape();
  stroke(238, 226, 196, 130);
  strokeWeight(2.5);
  arc(fx, fy - 268, 52, 60, -0.9, 0.9);
}

function paintFigureReflection(fx, fy) {
  const ctx = drawingContext;
  const g = ctx.createLinearGradient(0, fy, 0, fy + 320);
  g.addColorStop(0, 'rgba(5,7,12,0.55)');
  g.addColorStop(1, 'rgba(5,7,12,0)');
  ctx.fillStyle = g;
  ctx.fillRect(fx - 80, fy, 160, 320);
  noStroke();
  for (let i = 0; i < 70; i++) {
    const y = fy + random(4, 300);
    const spread = 26 + (y - fy) * 0.22;
    const x = fx + randomGaussian() * spread;
    const w = random(14, 80) * (0.5 + (y - fy) / 320);
    if (random() < 0.75) fill(4, 6, 10, random(14, 40));
    else fill(220, 205, 170, random(8, 22));
    rect(x - w / 2, y, w, random(1.5, 4));
  }
}

function paintRising() {
  noStroke();
  for (let i = 0; i < 460; i++) {
    const t = random(1);
    const y = 1560 - pow(t, 1.35) * 1180;
    const drift = (1180 - 620) * t * 0.65;
    const x = 620 + drift + randomGaussian() * (26 + t * 90) + sin(t * 12 + i * 0.7) * 26 * t;
    const s = random(1, 5.5) * (1 - t * 0.55) + 0.4;
    const a = random(40, 210) * (1 - t * 0.55);
    const r = random();
    if (r < 0.5) fill(248, 244, 232, a);
    else if (r < 0.78) fill(244, 230, 196, a);
    else if (r < 0.92) fill(196, 214, 240, a);
    else fill(255, 246, 220, min(255, a + 40));
    ellipse(x, y, s, s * random(0.7, 1.3));
  }
  strokeWeight(1);
  for (let i = 0; i < 46; i++) {
    const t = random(0.25, 1);
    const y = 1560 - pow(t, 1.35) * 1180;
    const x = 620 + (1180 - 620) * t * 0.65 + randomGaussian() * (30 + t * 80);
    const s = random(3, 9);
    stroke(250, 244, 224, random(60, 160));
    line(x - s, y, x + s, y);
    line(x, y - s, x, y + s);
  }
}

function paintReeds() {
  noFill();
  const clusters = [90, 1510];
  for (const cx of clusters) {
    for (let i = 0; i < 16; i++) {
      const bx = cx + random(-70, 70);
      const h = random(160, 460);
      const bend = random(-70, 70);
      stroke(4, 6, 11, 230);
      strokeWeight(random(3, 7));
      const tx = bx + bend, ty = height - h;
      bezier(bx, height + 10, bx + bend * 0.3, height - h * 0.6, bx + bend * 0.7, height - h * 0.85, tx, ty);
      noStroke();
      fill(6, 8, 13);
      ellipse(tx, ty, random(6, 12), random(14, 24));
    }
  }
}

function paintGrain() {
  noStroke();
  for (let i = 0; i < 8000; i++) {
    const x = random(width), y = random(height);
    if (random() < 0.5) fill(255, 255, 255, random(2, 8));
    else fill(0, 0, 0, random(2, 9));
    rect(x, y, random(0.6, 1.6), random(0.6, 1.6));
  }
}

function paintVignette() {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(width / 2, height * 0.46, height * 0.28, width / 2, height * 0.5, height * 0.85);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(0.72, 'rgba(0,0,0,0.14)');
  g.addColorStop(1, 'rgba(0,0,0,0.62)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
}

let heads = [];
let petalPalette;

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  petalPalette = [
    color(201, 138, 154),
    color(154, 138, 201),
    color(217, 184, 120),
    color(232, 224, 208),
    color(170, 110, 140)
  ];
}

function draw() {
  heads = [];
  gradientSky();
  skyStrokes();
  stars();
  moon();
  clouds();
  hills();
  field();
  grass();
  fallenPetals();
  flowersBack();
  figure();
  flowersFront();
  particles();
