  vignette();
}

function gradientSky() {
  const horizon = 1400;
  const stops = [
    [0.00, color(7, 9, 28)],
    [0.30, color(22, 20, 56)],
    [0.55, color(58, 44, 92)],
    [0.75, color(140, 84, 96)],
    [0.90, color(214, 148, 110)],
    [1.00, color(246, 200, 140)]
  ];
  noStroke();
  for (let y = 0; y < horizon; y += 3) {
    const t = y / horizon;
    let c = stops[stops.length - 1][1];
    for (let i = 0; i < stops.length - 1; i++) {
      const t0 = stops[i][0], c0 = stops[i][1];
      const t1 = stops[i + 1][0], c1 = stops[i + 1][1];
      if (t >= t0 && t <= t1) {
        c = lerpColor(c0, c1, (t - t0) / (t1 - t0));
        break;
      }
    }
    fill(c);
    rect(0, y, width, 3);
  }
}

function skyStrokes() {
  noStroke();
  for (let i = 0; i < 260; i++) {
    const y = random(0, 1400);
    const t = y / 1400;
    let base;
    if (t < 0.55) base = lerpColor(color(22, 20, 56), color(58, 44, 92), t / 0.55);
    else base = lerpColor(color(58, 44, 92), color(246, 200, 140), (t - 0.55) / 0.45);
    let c;
    if (random() < 0.5) c = lerpColor(base, color(255, 255, 255), random(0.05, 0.2));
    else c = lerpColor(base, color(0, 0, 0), random(0.05, 0.25));
    fill(red(c), green(c), blue(c), random(5, 14));
    ellipse(random(width), y + random(-8, 8), random(80, 420), random(6, 18));
  }
}

function stars() {
  noStroke();
  for (let i = 0; i < 240; i++) {
    const x = random(width);
    const y = random(0, 900);
    if (dist(x, y, 800, 980) < 320) continue;
    const a = random(30, 150) * (1 - y / 1000);
    fill(240, 240, 255, a);
    const s = random(1, 3);
    ellipse(x, y, s, s);
    if (random() < 0.12) {
      fill(240, 240, 255, a * 0.3);
      ellipse(x, y, s * 4, s * 4);
    }
  }
}

function moon() {
  const mx = 800, my = 980, mr = 270;
  noStroke();
  for (let i = 30; i >= 0; i--) {
    fill(243, 230, 200, 3 + (30 - i) * 0.4);
    ellipse(mx, my, mr + i * 16, mr + i * 16);
  }
  fill(244, 233, 206);
  ellipse(mx, my, mr * 2, mr * 2);
  fill(210, 190, 165, 55);
  ellipse(mx + 60, my + 40, mr * 1.7, mr * 1.7);
  fill(190, 170, 150, 40);
  const craters = [[-70, -40, 40], [50, -80, 26], [80, 60, 34], [-40, 90, 22], [10, 10, 18]];
  for (let i = 0; i < craters.length; i++) {
    const c = craters[i];
    ellipse(mx + c[0], my + c[1], c[2] * 2, c[2] * 2);
  }
  noFill();
  stroke(255, 220, 170, 70);
  strokeWeight(4);
  arc(mx, my, mr * 2 + 6, mr * 2 + 6, PI * 0.15, PI * 0.85);
}

function clouds() {
  noStroke();
  const defs = [
    { x: 500, y: 900, w: 700, h: 60, dark: true },
    { x: 1150, y: 1050, w: 800, h: 70, dark: true },
    { x: 300, y: 1120, w: 600, h: 55, dark: false },
    { x: 900, y: 830, w: 500, h: 45, dark: false }
  ];
  for (let i = 0; i < defs.length; i++) {
    const cl = defs[i];
    for (let j = 0; j < 46; j++) {
      const px = cl.x + random(-cl.w / 2, cl.w / 2);
      const py = cl.y + random(-cl.h / 2, cl.h / 2) + noise(px * 0.01, cl.y * 0.01) * 30;
      const s = random(30, 90);
      if (cl.dark) fill(16, 14, 38, random(10, 22));
      else fill(238, 200, 160, random(6, 14));
      ellipse(px, py, s * 2, s * 0.7);
    }
  }
}

function hills() {
  noStroke();
  fill(74, 56, 100);
  beginShape();
  vertex(0, 1400);
  for (let x = 0; x <= width; x += 40) vertex(x, 1360 - noise(x * 0.0016, 3.7) * 130);
  vertex(width, 1400);
  endShape(CLOSE);

  fill(44, 34, 72);
  beginShape();
  vertex(0, 1500);
  for (let x = 0; x <= width; x += 40) vertex(x, 1440 - noise(x * 0.002, 8.2) * 110);
  vertex(width, 1500);
  endShape(CLOSE);

  fill(26, 20, 48);
  beginShape();
  vertex(0, 1600);
  for (let x = 0; x <= width; x += 40) vertex(x, 1520 - noise(x * 0.0025, 15.1) * 90);
  vertex(width, 1600);
  endShape(CLOSE);
}

function field() {
  noStroke();
  for (let y = 1450; y < height; y += 4) {
    const t = (y - 1450) / (height - 1450);
    fill(lerpColor(color(30, 23, 54), color(9, 7, 20), t));
    rect(0, y, width, 4);
  }
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(800, 1460, 50, 800, 1460, 700);
  g.addColorStop(0, 'rgba(246, 200, 140, 0.35)');
  g.addColorStop(1, 'rgba(246, 200, 140, 0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 1400, width, 600);
}

function grass() {
  for (let i = 0; i < 1100; i++) {
    const x = random(width);
    const y = random(1470, height - 10);
    const depth = (y - 1450) / (height - 1450);
    const len = random(6, 14) + depth * random(10, 26);
    const sway = noise(x * 0.01, y * 0.01) * 0.6 - 0.3;
    const lit = 1 - constrain(dist(x, y, 800, 1500) / 900, 0, 1);
    const base = lerpColor(color(14, 11, 30), color(96, 74, 96), lit * random(0.4, 1));
    stroke(red(base), green(base), blue(base), random(90, 200));
    strokeWeight(random(1, 1.5 + depth * 2));
    line(x, y, x + sway * len, y - len);
  }
}

function fallenPetals() {
  noStroke();
  for (let i = 0; i < 60; i++) {
    const c = random(petalPalette);
    fill(red(c), green(c), blue(c), random(60, 130));
    push();
    translate(random(width), random(1650, height - 15));
    rotate(random(TWO_PI));
    ellipse(0, 0, random(6, 14), random(3, 6));
    pop();
  }
}

function flower(x, y, s, wiltChance) {
  const depth = (y - 1450) / (height - 1450);
  const h = (random(45, 110) + depth * 60) * s;
  const bend = random(-1, 1) * (20 + depth * 30) * s;
  const topX = x + bend;
  const topY = y - h;
  const wilt = random() < wiltChance;
  noFill();
  stroke(42, 56, 42, 220);
  strokeWeight(random(2, 3.5) * s);
  bezier(x, y, x + bend * 0.2, y - h * 0.4, topX - bend * 0.4, topY + h * 0.25, topX, topY);
  if (random() < 0.6) {
    stroke(48, 64, 46, 200);
    strokeWeight(2 * s);
    const ly = y - h * random(0.3, 0.6);
    const lx = x + bend * 0.4;
    line(lx, ly, lx + random(-26, 26) * s, ly - random(4, 12) * s);
  }
  const pc = random(petalPalette);
  const n = 6;
  const pr = random(9, 15) * s;
  const startA = wilt ? PI * 0.15 : 0;
  const span = wilt ? PI * 0.7 : TWO_PI;
  for (let i = 0; i < n; i++) {
    const a = startA + (span * i) / (n - 1);
    push();
    translate(topX, topY);
    rotate(a);
    noStroke();
    fill(red(pc), green(pc), blue(pc), wilt ? 150 : 235);
    ellipse(pr * 0.6, 0, pr * 1.5, pr * 0.75);
    pop();
  }
  noStroke();
  fill(58, 40, 32, 240);
  ellipse(topX, topY, pr * 0.5, pr * 0.5);
  heads.push({ x: topX, y: topY, phase: random(TWO_PI), c: pc });
}

function flowersBack() {
  for (let i = 0; i < 80; i++) {
    flower(random(width), random(1480, 1720), random(0.5, 0.8), 0.35);
  }
}

function flowersFront() {
  for (let i = 0; i < 110; i++) {
    flower(random(width), random(1680, height - 20), random(0.8, 1.5), 0.25);
  }
}

function robePath() {
  beginShape();
  vertex(688, 1792);
  bezierVertex(696, 1620, 716, 1430, 742, 1300);
  bezierVertex(752, 1240, 758, 1205, 766, 1172);
  bezierVertex(772, 1118, 788, 1092, 806, 1090);
  bezierVertex(826, 1088, 846, 1114, 850, 1162);
  bezierVertex(854, 1205, 862, 1245, 874, 1305);
  bezierVertex(896, 1430, 912, 1630, 920, 1792);
  endShape(CLOSE);
}

function figure() {
  noStroke();
  fill(246, 220, 180, 26);
  ellipse(800, 1400, 560, 760);
  fill(0, 0, 0, 130);
  ellipse(805, 1792, 380, 46);
  noFill();
  stroke(255, 224, 180, 80);
  strokeWeight(3);
  robePath();
  noStroke();
  fill(10, 8, 20);
  robePath();
  fill(4, 3, 10);
  ellipse(806, 1152, 52, 66);
  noStroke();
  fill(10, 8, 20);
  beginShape();
  vertex(846, 1318);
  bezierVertex(892, 1268, 942, 1226, 986, 1190);
  bezierVertex(998, 1180, 1004, 1190, 994, 1202);
  bezierVertex(952, 1240, 906, 1282, 866, 1336);
  endShape(CLOSE);
  noFill();
  stroke(255, 224, 180, 90);
  strokeWeight(2.5);
  beginShape();
  vertex(850, 1314);
  bezierVertex(894, 1264, 944, 1222, 986, 1188);
  endShape();
}

function particles() {
  noStroke();
  for (let i = 0; i < 200; i++) {
    const h = random(heads);
    const t = random(0.1, 1);
    let speed = random(140, 520);
    if (random() < 0.12) speed = random(520, 950);
    const py = h.y - t * speed;
    if (py < 60) continue;
    const px = h.x + sin(t * 5 + h.phase) * 34 * t + random(-14, 14);
    const a = (1 - t) * 190;
    const s = random(2, 6.5) * (1 - t * 0.4) + 1;
    const c = random() < 0.5 ? h.c : color(255, 217, 138);
    fill(red(c), green(c), blue(c), a * 0.3);
    ellipse(px, py, s * 3.2, s * 3.2);
    fill(red(c), green(c), blue(c), a);
    ellipse(px, py, s * 1.6, s);
  }
}

function grain() {
  noStroke();
  for (let i = 0; i < 7000; i++) {
    const x = random(width);
    const y = random(height);
    if (random() < 0.5) fill(255, 250, 240, random(2, 8));
    else fill(0, 0, 10, random(2, 9));
    rect(x, y, random(1, 2.2), random(1, 2.2));
  }
}

function vignette() {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(800, 950, 500, 800, 1000, 1350);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(0.7, 'rgba(4,3,10,0.18)');
  g.addColorStop(1, 'rgba(3,2,8,0.6)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
  const g2 = ctx.createLinearGradient(0, 0, 0, 400);
  g2.addColorStop(0, 'rgba(3,2,8,0.5)');
  g2.addColorStop(1, 'rgba(3,2,8,0)');
  ctx.fillStyle = g2;
  ctx.fillRect(0, 0, width, 400);
}

