function gradColor(t, stops) {
  t = constrain(t, 0, 1);
  for (let i = 0; i < stops.length - 1; i++) {
    const p0 = stops[i][0], c0 = stops[i][1];
    const p1 = stops[i + 1][0], c1 = stops[i + 1][1];
    if (t >= p0 && t <= p1) {
      return lerpColor(c0, c1, (t - p0) / (p1 - p0));
    }
  }
  return stops[stops.length - 1][1];
}

