  ctx.fillRect(MOON.x - MOON.r * 3.4, MOON.y - MOON.r * 3.4, MOON.r * 6.8, MOON.r * 6.8);

  g = ctx.createRadialGradient(MOON.x - 50, MOON.y - 60, 20, MOON.x, MOON.y, MOON.r);
  g.addColorStop(0, '#fff7e4');
  g.addColorStop(0.65, '#ffe9c2');
  g.addColorStop(1, '#f0c496');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(MOON.x, MOON.y, MOON.r, 0, TWO_PI);
  ctx.fill();

  ctx.save();
  ctx.beginPath();
  ctx.arc(MOON.x, MOON.y, MOON.r, 0, TWO_PI);
  ctx.clip();
  noStroke();
  const craters = [[-40, -30, 26], [30, 20, 34], [-10, 50, 18], [55, -35, 16], [-60, 35, 14]];
