function drawReed(x, s) {
  const h = random(170, 540) * s;
  const lean = random(-80, 80);
  const bx = x, by = H + 12;
  const tx = x + lean, ty = by - h;
  const cx = x + lean * 0.3 + random(-24, 24);
  const cy = by - h * 0.55;
  noFill();
  stroke(9, 8, 18, 235);
  strokeWeight(random(2.5, 5.5) * s + 1);
  beginShape();
  vertex(bx, by);
  quadraticVertex(cx, cy, tx, ty);
  endShape();
  const a = atan2(ty - cy, tx - cx);
  if (random() < 0.45) {
    noStroke();
    fill(60, 44, 36, 245);
    push();
    translate(tx, ty);
    rotate(a + HALF_PI);
    ellipse(0, -15, 9, 36);
    pop();
    stroke(9, 8, 18, 210);
    strokeWeight(1.6);
    const sx = tx + Math.cos(a) * 34, sy = ty + Math.sin(a) * 34;
    line(sx, sy, sx + Math.cos(a) * 22, sy + Math.sin(a) * 22);
  } else {
    stroke(24, 30, 34, 170);
    strokeWeight(1.3);
    line(tx, ty, tx + random(-10, 10), ty - random(12, 30));
  }
}

