function branch(x, y, ang, len, w, depth) {
  if (depth <= 0 || len < 8) return;
  const x2 = x + cos(ang) * len;
  const y2 = y + sin(ang) * len;
  const mx = (x + x2) / 2 + cos(ang + HALF_PI) * random(-len * 0.16, len * 0.16);
  const my = (y + y2) / 2 + sin(ang + HALF_PI) * random(-len * 0.16, len * 0.16);
  stroke(12, 9, 7, 240);
  strokeWeight(w);
  noFill();
  beginShape();
  vertex(x, y);
  quadraticVertex(mx, my, x2, y2);
  endShape();
  const n = depth > 5 ? 3 : (random() < 0.7 ? 2 : 3);
  const spread = map(depth, 1, 8, 0.28, 0.62);
  for (let i = 0; i < n; i++) {
    branch(x2, y2, ang + random(-spread, spread) + (i - (n - 1) / 2) * 0.4, len * random(0.64, 0.8), Math.max(w * 0.66, 0.8), depth - 1);
  }
}

