  pixelDensity(1);
  noLoop();
}

let segments = 0;

function draw() {
  const cTop = color(8, 10, 21);
  const cMid = color(16, 18, 35);
  const cBot = color(36, 28, 30);

  for (let y = 0; y < height; y += 3) {
    const t = y / height;
    const c = t < 0.55
      ? lerpColor(cTop, cMid, t / 0.55)
      : lerpColor(cMid, cBot, (t - 0.55) / 0.45);
    const n = (noise(y * 0.008, 7.3) - 0.5) * 16;
    stroke(red(c) + n, green(c) + n, blue(c) + n * 1.2);
    strokeWeight(3);
    line(0, y, width, y);
  }

  noStroke();
  for (let i = 0; i < 300; i++) {
    const x = random(width);
    const y = random(height * 0.6);
    const fade = 1 - y / (height * 0.65);
    fill(236, 231, 212, random(15, 110) * max(0.15, fade));
    circle(x, y, random(0.6, 2.6));
  }

  const mx = 1150, my = 460, mr = 210;
  for (let r = mr * 3.4; r > mr; r -= 5) {
    fill(242, 230, 192, map(r, mr, mr * 3.4, 30, 0));
    circle(mx, my, r * 2);
  }
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(mx - mr * 0.45, my - mr * 0.4, mr * 0.1, mx, my, mr);
  g.addColorStop(0, '#f7efd8');
  g.addColorStop(0.65, '#e9dfc2');
  g.addColorStop(1, '#a9a294');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(mx, my, mr, 0, Math.PI * 2);
  ctx.fill();

  for (let i = 0; i < 16; i++) {
    const a = random(TWO_PI);
    const d = random(mr * 0.1, mr * 0.82);
    const cx = mx + cos(a) * d;
    const cy = my + sin(a) * d;
    const cr = random(5, 24);
    fill(110, 106, 116, random(10, 26));
    circle(cx, cy, cr * 2);
    fill(255, 250, 232, random(6, 16));
    circle(cx - cr * 0.3, cy - cr * 0.3, cr * 1.1);
  }

  noStroke();
  fill(13, 13, 19, 235);
  beginShape();
  vertex(0, height * 0.905);
  for (let x = 0; x <= width; x += 40) {
    vertex(x, height * 0.905 - noise(x * 0.004, 3.1) * 100);
  }
  vertex(width, height);
  vertex(0, height);
  endShape(CLOSE);

  for (let i = 0; i < 70; i++) {
    fill(198, 194, 212, random(3, 11));
    ellipse(random(-250, width + 250), random(height * 0.74, height * 0.99),
      random(320, 950), random(18, 64));
  }
  fill(242, 230, 192, 7);
  ellipse(mx, height * 0.93, 560, 70);

  for (let y = height * 0.9; y < height; y += 4) {
    const t = (y - height * 0.9) / (height * 0.1);
    stroke(lerpColor(color(24, 20, 22), color(7, 7, 11), t));
    strokeWeight(4);
    line(0, y, width, y);
  }

  strokeCap(ROUND);
  segments = 0;
  branch(505, height + 30, -HALF_PI + 0.12, 280, 70, 8);

  for (let i = 0; i < 42; i++) {
    const t = i / 42;
    const x = lerp(600, mx - mr * 0.5, t) + random(-70, 70);
    const y = lerp(1080, my + 85, t) - sin(t * PI) * 160 + random(-35, 35);
    soul(x, y, random(3.5, 9));
  }

  for (let i = 0; i < 110; i++) {
    const x = width * 0.5 + pow(random(-1, 1), 3) * width * 0.48;
    const y = random(height * 0.3, height * 0.93);
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    const s = random(4, 12);
    noStroke();
    fill(random() < 0.5 ? color(158, 96, 52, random(50, 130)) : color(122, 72, 42, random(50, 130)));
    ellipse(0, 0, s * 1.9, s);
    pop();
  }

  watcher(880, 1935, 82);

  const v = ctx.createRadialGradient(width / 2, height * 0.46, height * 0.32,
    width / 2, height * 0.5, height * 0.78);
  v.addColorStop(0, 'rgba(0,0,0,0)');
  v.addColorStop(1, 'rgba(0,0,0,0.6)');
  ctx.fillStyle = v;
  ctx.fillRect(0, 0, width, height);

  noStroke();
  for (let i = 0; i < 24000; i++) {
    if (random() < 0.5) fill(255, 255, 255, random(2, 7));
    else fill(0, 0, 0, random(2, 8));
    rect(random(width), random(height), random(1, 2.4), random(1, 2.4));
  }

  for (let i = 0; i < 130; i++) {
    stroke(random() < 0.5 ? color(255, 255, 255, random(2, 6)) : color(0, 0, 0, random(2, 6)));
    strokeWeight(random(1, 5));
    const y = random(height);
    line(random(-120, width * 0.4), y, random(width * 0.6, width + 120), y + random(-9, 9));
  }
}

function branch(x, y, angle, len, w, depth) {
  if (depth <= 0 || len < 9 || segments > 9000) {
    if (depth <= 0 && random() < 0.8) soul(x, y, random(3, 8));
    return;
  }
  segments++;
  const x2 = x + cos(angle) * len;
  const y2 = y + sin(angle) * len;
  for (let p = 0; p < 3; p++) {
    const sh = random(-9, 9);
    stroke(26 + sh, 21 + sh, 23 + sh, random(190, 255));
    strokeWeight(w * random(0.88, 1.12));
    line(x + random(-2, 2), y + random(-2, 2), x2 + random(-3, 3), y2 + random(-3, 3));
  }
  stroke(226, 208, 168, random(22, 52));
  strokeWeight(max(1, w * 0.2));
  line(x + w * 0.32, y, x2 + w * 0.32, y2);
  const n = depth > 5 ? 2 : int(random(2, 4));
  for (let i = 0; i < n; i++) {
    const na = angle + random(-0.6, 0.6) + (i === 0 ? -0.28 : 0.28);
    branch(x2, y2, na, len * random(0.62, 0.8), w * 0.66, depth - 1);
  }
}

function soul(x, y, s) {
  push();
  translate(x, y);
  rotate(random(-0.9, -0.15));
  noStroke();
  fill(244, 228, 178, random(28, 70));
  ellipse(0, 0, s * 3.4, s * 2.2);
  fill(242, 226, 176, random(130, 220));
  ellipse(-s * 0.7, -s * 0.35, s * 1.7, s * 0.75, -0.55);
  ellipse(s * 0.7, -s * 0.35, s * 1.7, s * 0.75, 0.55);
  ellipse(0, 0, s * 1.0, s * 0.55);
  pop();
}

function watcher(x, y, s) {
  noStroke();
  fill(7, 7, 11, 245);
  beginShape();
  vertex(x - s * 0.6, y);
  bezierVertex(x - s * 0.75, y - s * 1.5, x - s * 0.3, y - s * 2.3, x, y - s * 2.45);
  bezierVertex(x + s * 0.3, y - s * 2.3, x + s * 0.75, y - s * 1.5, x + s * 0.6, y);
  endShape(CLOSE);
  circle(x, y - s * 2.8, s * 0.62);
  noFill();
  stroke(232, 216, 180, 80);
  strokeWeight(2.2);
  arc(x, y - s * 2.8, s * 0.62, s * 0.62, -PI * 0.85, PI * 0.15);
  arc(x + s * 0.12, y - s * 1.2, s * 1.35, s * 2.7, -PI * 0.7, PI * 0.08);
}

