  noStroke();
  for (let r = 470; r > 215; r -= 10) {
    fill(225, 218, 195, map(r, 215, 470, 30, 0));
    circle(1150, 430, r * 2);
  }
  fill(233, 227, 206);
  circle(1150, 430, 420);
  for (let i = 0; i < 16; i++) {
    let a = random(TWO_PI);
    let rr = random(30, 175);
    fill(206, 198, 176, random(70, 130));
    ellipse(1150 + cos(a) * rr, 430 + sin(a) * rr, random(18, 72), random(14, 56), random(TWO_PI));
  }
  fill(14, 16, 32, 30);
  circle(1265, 355, 430);

  noStroke();
  fill(15, 17, 30);
  beginShape();
  vertex(0, height);
  vertex(0, 1620);
  for (let x = 0; x <= width; x += 50) vertex(x, 1600 + noise(x * 0.003, 1) * 120);
  vertex(width, 1620);
  vertex(width, height);
  endShape(CLOSE);

  fill(19, 20, 33);
  beginShape();
  vertex(0, height);
  vertex(0, 1730);
  for (let x = 0; x <= width; x += 50) vertex(x, 1710 + noise(x * 0.004, 9) * 90);
  vertex(width, 1730);
  vertex(width, height);
  endShape(CLOSE);

  fill(11, 10, 14);
  beginShape();
  vertex(0, height);
  vertex(0, 1840);
  for (let x = 0; x <= width; x += 40) vertex(x, 1815 + noise(x * 0.005, 3) * 60);
  vertex(width, 1840);
  vertex(width, height);
  endShape(CLOSE);

  let palette = [[196, 156, 84], [168, 96, 58], [146, 64, 48], [122, 38, 44], [214, 204, 184], [96, 74, 52]];
  for (let i = 0; i < 70; i++) {
    leaf(random(width), random(height * 0.9), random(5, 13), random(TWO_PI), palette[floor(random(palette.length))], 120);
  }

  tips = [];
  branch(520, 2030, -HALF_PI, 430, 42, 9);

  stroke(14, 12, 10);
  noFill();
  for (let i = 0; i < 8; i++) {
    let dir = i < 4 ? -1 : 1;
    let x0 = 520 + dir * random(5, 45);
    let len = random(120, 330);
    strokeWeight(random(6, 15));
    beginShape();
    vertex(x0, 1905);
    for (let s = 1; s <= 6; s++) {
      let t = s / 6;
      vertex(x0 + dir * len * t, 1905 + t * t * 85 + noise(s * 3, i * 7) * 18);
    }
    endShape();
  }

  let upper = tips.filter(function (t) { return t.y < 1150; });
  let tip = upper.length > 0 ? upper[floor(random(upper.length))] : tips[0];
  crow(tip.x, tip.y - 8, 1.15);

  skull(870, 1850, 1.05, -0.12);
  noStroke();
  fill(11, 10, 14);
  ellipse(870, 1908, 200, 62);

  for (let i = 0; i < 80; i++) {
    let x = random(width);
    let y = random() < 0.25 ? random(1820, 1990) : random(height);
    leaf(x, y, random(6, 16), random(TWO_PI), palette[floor(random(palette.length))], random(150, 230));
  }

  noStroke();
  for (let i = 0; i < 6; i++) {
    fill(170, 180, 205, random(8, 16));
    ellipse(random(width), random(1680, 1960), random(1200, 2100), random(50, 110));
  }

  let ctx = drawingContext;
  let g = ctx.createRadialGradient(width / 2, height * 0.45, height * 0.25, width / 2, height * 0.5, height * 0.78);
  g.addColorStop(0, "rgba(0,0,0,0)");
  g.addColorStop(1, "rgba(2,2,6,0.6)");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);

  for (let i = 0; i < 22000; i++) {
    stroke(random() < 0.5 ? 255 : 0, random(3, 9));
    strokeWeight(1);
    point(random(width), random(height));
  }
}

function branch(x, y, ang, len, w, depth) {
  if (depth <= 0 || len < 7) {
    tips.push({ x: x, y: y });
    return;
  }
  let steps = 5;
  let px = x, py = y;
  for (let i = 0; i < steps; i++) {
    let a = ang + (noise(px * 0.008 + depth * 7, py * 0.008) - 0.5) * 0.4;
    let nx = px + cos(a) * (len / steps);
    let ny = py + sin(a) * (len / steps);
    strokeWeight(map(i, 0, steps, w, w * 0.5));
    stroke(16 + random(-5, 7), 13 + random(-4, 5), 11 + random(-4, 5));
    line(px, py, nx, ny);
    px = nx;
    py = ny;
  }
  let n = random() < 0.22 ? 3 : 2;
  for (let i = 0; i < n; i++) {
    let spread = map(i, 0, n - 1, -0.6, 0.6);
    let na = constrain(ang + spread + random(-0.15, 0.15), -PI * 0.92, -PI * 0.08);
    branch(px, py, na, len * random(0.66, 0.78), w * 0.62, depth - 1);
  }
}

function leaf(x, y, s, rot, col, a) {
  push();
  translate(x, y);
  rotate(rot);
  noStroke();
  fill(col[0], col[1], col[2], a);
  beginShape();
  vertex(0, -s);
  bezierVertex(s * 0.9, -s * 0.4, s * 0.7, s * 0.8, 0, s);
  bezierVertex(-s * 0.7, s * 0.8, -s * 0.9, -s * 0.4, 0, -s);
  endShape(CLOSE);
  pop();
}

function crow(x, y, s) {
  push();
  translate(x, y);
  scale(s);
  noStroke();
  fill(6, 6, 9);
  ellipse(0, 0, 36, 22);
  ellipse(15, -11, 19, 17);
  triangle(30, -14, 48, -9, 30, -5);
  quad(-14, 0, -42, 8, -40, 16, -12, 10);
  fill(210, 205, 190, 220);
  circle(19, -13, 3);
  pop();
}

function skull(x, y, s, rot) {
  push();
  translate(x, y);
  rotate(rot);
  scale(s);
  noStroke();
  fill(224, 216, 196);
  ellipse(0, -14, 92, 102);
  rect(-30, 18, 60, 48, 10);
  fill(14, 12, 18);
  ellipse(-21, -16, 27, 33);
  ellipse(21, -16, 27, 33);
  triangle(-5, 6, 5, 6, 0, 24);
  stroke(14, 12, 18);
  strokeWeight(2.5);
  for (let i = -2; i <= 2; i++) line(i * 11, 20, i * 11, 62);
  noStroke();
  fill(190, 182, 162, 90);
  ellipse(-34, 6, 18, 26);
  ellipse(34, 6, 18, 26);
  pop();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function grad(stops, t) {
  for (let i = 0; i < stops.length - 1; i++) {
    if (t >= stops[i][0] && t <= stops[i + 1][0]) {
      let f = (t - stops[i][0]) / (stops[i + 1][0] - stops[i][0]);
      return lerpColor(stops[i][1], stops[i + 1][1], f);
    }
  }
  return stops[stops.length - 1][1];
}

function branch(x, y, ang, len, w, d) {
  if (d <= 0 || len < 5) return;
  let x2 = x + cos(ang) * len;
  let y2 = y + sin(ang) * len;
  stroke(6, 6, 11);
  strokeWeight(w);
  strokeCap(ROUND);
  line(x, y, x2, y2);
  let n = random() < 0.75 ? 2 : 3;
  for (let i = 0; i < n; i++) {
    let na = ang + (i - (n - 1) / 2) * 0.55 + random(-0.3, 0.3);
    branch(x2, y2, na, len * random(0.66, 0.8), w * 0.62, d - 1);
  }
}

function figure(x, y, s, c) {
  noStroke();
  fill(c);
  beginShape();
  vertex(x - s * 0.55, y);
  bezierVertex(x - s * 0.62, y - s * 1.1, x - s * 0.4, y - s * 1.9, x, y - s * 2.2);
  bezierVertex(x + s * 0.4, y - s * 1.9, x + s * 0.62, y - s * 1.1, x + s * 0.55, y);
  endShape(CLOSE);
  circle(x, y - s * 2.28, s * 0.62);
}

function bird(x, y, s, f) {
  stroke(4, 4, 8);
  strokeWeight(3.5);
  strokeCap(ROUND);
  noFill();
  beginShape();
  vertex(x - s, y);
  quadraticVertex(x - s * 0.5, y - s * 0.9 * f, x, y);
  quadraticVertex(x + s * 0.5, y - s * 0.9 * f, x + s, y);
  endShape();
}

function draw() {
  const cx = width * 0.5;
  const cy = height * 0.52;
  const R = 290;
  const gy = height * 0.885;

  // ciel en dégradé
  const stops = [
    [0.00, color(3, 4, 11)],
    [0.38, color(12, 15, 32)],
    [0.60, color(34, 22, 30)],
    [0.78, color(88, 40, 22)],
    [0.92, color(46, 20, 12)],
    [1.00, color(10, 6, 8)]
  ];
  for (let y = 0; y < height; y++) {
    stroke(grad(stops, y / height));
    strokeWeight(1);
    line(0, y, width, y);
  }

  // touches de pinceau dans le ciel
  for (let i = 0; i < 500; i++) {
    let y = random(height * 0.8);
    let x = random(-100, width);
    let len = random(60, 380);
    stroke(random(18, 55), random(14, 38), random(28, 70), random(8, 26));
    strokeWeight(random(2, 9));
    line(x, y, x + len, y + random(-5, 5));
  }

  // étoiles
  for (let i = 0; i < 320; i++) {
    let y = random(height * 0.5);
    let a = map(y, 0, height * 0.5, 150, 8);
    stroke(220, 225, 255, random(a * 0.4, a));
    strokeWeight(random(1, 2.6));
    point(random(width), y);
  }

  // halo chaud
  noStroke();
  for (let r = 1000; r > 0; r -= 10) {
    fill(255, 130, 55, map(r, 0, 1000, 42, 0));
    circle(cx, cy, r * 2);
  }

  // rayons de couronne
  for (let i = 0; i < 240; i++) {
    let a = random(TWO_PI);
    let r1 = R + random(6, 30);
    let r2 = R + random(70, 330);
    stroke(255, 200 + random(55), 140, random(10, 55) * (1 - (r2 - R) / 360));
    strokeWeight(random(1, 3));
    line(cx + cos(a) * r1, cy + sin(a) * r1, cx + cos(a) * r2, cy + sin(a) * r2);
  }

  // disque solaire
  noStroke();
  for (let r = R; r > 0; r -= 5) {
    let t = r / R;
    fill(lerpColor(color(255, 110, 35), color(255, 246, 222), pow(t, 0.6)));
    circle(cx, cy, r * 2);
  }
  noFill();
  stroke(255, 240, 210, 220);
  strokeWeight(5);
  circle(cx, cy, R * 2);

  // disque d'ombre : il ne reste qu'un croissant
  noStroke();
  fill(4, 5, 10);
  circle(cx + 62, cy - 34, R * 2 * 0.985);

  // crête lointaine
  fill(16, 15, 26);
  beginShape();
  vertex(0, height * 0.84);
  for (let x = 0; x <= width; x += 16) vertex(x, height * 0.80 + noise(x * 0.0018, 9.1) * 70 - 35);
  vertex(width, height * 0.84);
  vertex(width, height);
  vertex(0, height);
  endShape(CLOSE);

  // sol sombre, lac
  fill(4, 5, 10);
  beginShape();
  vertex(0, height);
  vertex(0, gy);
  for (let x = 0; x <= width; x += 16) vertex(x, gy + noise(x * 0.002, 4.2) * 26 - 13);
  vertex(width, gy);
  vertex(width, height);
  endShape(CLOSE);

  // reflets du dernier éclat sur l'eau
  noStroke();
  for (let y = gy + 6; y < height; y += 7) {
    let t = (y - gy) / (height - gy);
    let w = (50 + noise(y * 0.012, 1.5) * 220) * (1 - t * 0.55);
    fill(255, 165 + noise(y * 0.02) * 60, 80, 110 * (1 - t) * (1 - t));
    ellipse(cx + (noise(y * 0.02, 7.7) - 0.5) * 90, y, w, 7);
  }

  // brume au-dessus du lac
  for (let i = 0; i < 12; i++) {
    fill(200, 160, 140, random(6, 18));
    ellipse(random(width), gy - random(10, 90), random(200, 600), random(6, 16));
  }

  // arbres morts
  branch(width * 0.22, gy + 30, -PI / 2 + 0.08, 300, 30, 9);
  branch(width * 0.36, gy + 40, -PI / 2 - 0.12, 220, 22, 8);

  // silhouette voilée, lueur chaude sur son bord
  push();
  translate(-7, 0);
  figure(width * 0.68, gy + 6, 120, color(80, 34, 15));
  pop();
  figure(width * 0.68, gy + 6, 120, color(3, 3, 7));

  // oiseaux qui s'en vont
  bird(width * 0.72, height * 0.30, 34, 1);
  bird(width * 0.78, height * 0.26, 26, 0.8);
  bird(width * 0.66, height * 0.22, 20, 1.2);
  bird(width * 0.83, height * 0.34, 30, 0.7);

  // fleur fanée au premier plan
  let fx = width * 0.86;
  stroke(10, 12, 8);
  strokeWeight(5);
  noFill();
  curve(fx, height + 10, fx + 30, height - 120, fx - 10, height - 220, fx + 40, height - 300);
  let hx = fx + 40, hy = height - 300;
  noStroke();
  fill(30, 10, 14);
  circle(hx, hy, 16);
  for (let i = 0; i < 5; i++) {
    push();
    translate(hx, hy);
    rotate(PI / 2 + (i - 2) * 0.5);
    fill(52, 18, 24, 230);
    ellipse(20, 0, 30, 12);
    pop();
  }

  // cendres et pétales qui tombent
  for (let i = 0; i < 260; i++) {
    let x = random(width), y = random(height);
    let s = random(2, 7);
    if (random() < 0.4) fill(255, random(120, 200), 60, random(60, 160));
    else fill(200, 200, 210, random(40, 120));
    noStroke();
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    ellipse(0, 0, s, s * 0.6);
    pop();
  }

  // herbes du premier plan
  for (let i = 0; i < 140; i++) {
    let x = random(width);
    let h = random(30, 140);
    let bend = random(-40, 40);
    stroke(3, 4, 8, random(180, 255));
    strokeWeight(random(1.5, 4));
    noFill();
    curve(x, height + 10, x + bend * 0.3, height - h * 0.6, x + bend * 0.7, height - h * 0.85, x + bend, height - h);
  }

  // grain de toile
  noStroke();
  for (let i = 0; i < 26000; i++) {
    if (random() < 0.5) fill(0, 0, 0, random(4, 14));
    else { let v = random(255); fill(v, v, v, random(3, 12)); }
    rect(random(width), random(height), random(1, 3), random(1, 3));
  }

  // vignettage
  let ctx = drawingContext;
  let g = ctx.createRadialGradient(width / 2, height / 2, height * 0.28, width / 2, height / 2, height * 0.78);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(1, 'rgba(0,0,0,0.6)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

const P0 = { x: 782, y: 1572 };
const P1 = { x: 738, y: 1235 };
const P2 = { x: 905, y: 948 };
const P3 = { x: 1128, y: 1008 };

function bez(t) {
  let u = 1 - t;
  return {
    x: u*u*u*P0.x + 3*u*u*t*P1.x + 3*u*t*t*P2.x + t*t*t*P3.x,
    y: u*u*u*P0.y + 3*u*u*t*P1.y + 3*u*t*t*P2.y + t*t*t*P3.y
  };
}

function petal(x, y, ang, len, w, base, tip) {
  push();
  translate(x, y);
  rotate(ang);
  fill(base);
  noStroke();
  beginShape();
  vertex(0, 0);
  bezierVertex(len*0.28, -w, len*0.72, -w*0.75, len, -w*0.1);
  bezierVertex(len*0.72, w*0.75, len*0.28, w, 0, 0);
  endShape(CLOSE);
  stroke(120, 110, 90, 70);
  strokeWeight(1.2);
  line(6, 0, len*0.85, -2);
  noStroke();
  fill(tip);
  beginShape();
  vertex(len*0.7, -w*0.55);
  bezierVertex(len*0.9, -w*0.5, len*0.98, -w*0.25, len, -w*0.1);
  bezierVertex(len*0.98, w*0.2, len*0.88, w*0.45, len*0.68, w*0.5);
  endShape(CLOSE);
  pop();
}

function leaf(x, y, ang, len, w) {
  push();
  translate(x, y);
  rotate(ang);
  fill(58, 72, 50);
  noStroke();
  beginShape();
  vertex(0, 0);
  bezierVertex(len*0.3, -w, len*0.75, -w*0.6, len, 0);
  bezierVertex(len*0.75, w*0.6, len*0.3, w, 0, 0);
  endShape(CLOSE);
  stroke(30, 40, 26, 120);
  strokeWeight(1.5);
  line(0, 0, len*0.9, 0);
  noStroke();
  fill(120, 100, 70, 140);
  ellipse(len*0.92, 0, w*0.3, w*0.22);
  pop();
}

function paintLedge(ctx) {
  let lg = ctx.createLinearGradient(0, 1560, 0, height);
  lg.addColorStop(0, '#34343f');
  lg.addColorStop(0.1, '#272730');
  lg.addColorStop(1, '#0e0e14');
  ctx.fillStyle = lg;
  ctx.fillRect(0, 1560, width, height - 1560);
  stroke(255, 235, 200, 30);
  strokeWeight(2.5);
  line(0, 1561, width, 1561);
  noStroke();
  for (let i = 0; i < 900; i++) {
    let x = random(width), y = random(1565, height);
    let a = random(0.03, 0.12);
    if (random() < 0.5) fill(0, 0, 0, a * 255);
    else fill(200, 200, 220, a * 255);
    ellipse(x, y, random(1, 4), random(1, 3));
  }
  stroke(0, 0, 0, 60);
  strokeWeight(1.5);
  noFill();
  for (let i = 0; i < 5; i++) {
    let x = random(width), y = random(1580, 1900);
    beginShape();
    vertex(x, y);
    for (let j = 0; j < 6; j++) {
      x += random(-60, 60);
      y += random(10, 70);
      vertex(x, y);
    }
    endShape();
  }
  noStroke();
}

function paintStem() {
  for (let i = 0; i < 48; i++) {
    let a = bez(i / 48), b = bez((i + 1) / 48);
    let w = map(i, 0, 48, 15, 4);
    stroke(64 + noise(i) * 20, 78 + noise(i * 2) * 20, 58 + noise(i * 3) * 16);
    strokeWeight(w);
    line(a.x, a.y, b.x, b.y);
  }
  for (let i = 0; i < 48; i++) {
    let a = bez(i / 48), b = bez((i + 1) / 48);
    let w = map(i, 0, 48, 5, 1.5);
    stroke(150, 168, 128, 55);
    strokeWeight(w);
    line(a.x - 2, a.y - 2, b.x - 2, b.y - 2);
  }
  noStroke();
  fill(20, 18, 16);
  ellipse(782, 1570, 70, 20);
  leaf(768, 1345, -0.9, 150, 42);
  leaf(845, 1090, 0.7, 130, 38);
}

function paintFlower() {
  let c = { x: 1128, y: 1008 };
  petal(c.x, c.y, -0.6, 150, 40, '#cfc8b8', 'rgba(140,115,85,0.6)');
  let angles = [0.45, 0.95, 1.5, 2.05, 2.6];
  let lens = [215, 235, 245, 230, 205];
  let ws = [52, 58, 60, 56, 50];
  for (let i = 0; i < angles.length; i++) {
    petal(c.x, c.y, angles[i], lens[i], ws[i], '#ece6d8', 'rgba(150,122,90,0.55)');
  }
  fill(216, 210, 192);
  ellipse(c.x, c.y, 46, 40);
  fill(190, 180, 158, 120);
  ellipse(c.x + 6, c.y + 8, 30, 24);
  for (let k = 0; k < 6; k++) {
    let a = 1.1 + k * 0.16 + random(-0.05, 0.05);
    let L = 90 + random(50);
    let ex = c.x + cos(a) * L;
    let ey = c.y + sin(a) * L + 18;
    stroke(205, 190, 150, 200);
    strokeWeight(2.2);
    noFill();
    bezier(c.x, c.y,
      c.x + cos(a) * L * 0.4, c.y + sin(a) * L * 0.4 + 10,
      c.x + cos(a) * L * 0.7, c.y + sin(a) * L * 0.7 + 16,
      ex, ey);
    noStroke();
    fill(122, 92, 56);
    ellipse(ex, ey, 9, 7);
  }
}

function paintFallenPetals() {
  let spots = [
    [560, 1620, 2.7, 0.75],
    [880, 1665, 0.5, 0.65],
    [1290, 1600, 1.3, 0.7],
    [720, 1720, 5.6, 0.6],
    [1050, 1590, 2.2, 0.55]
  ];
