  }
}

function paintEmbers() {
  for (let i = 0; i < 14; i++) {
    let x = 800 + random(-1, 1) * random(80, 520);
    let y = random(150, 1450);
    let a = random(0.15, 0.6);
    fill(255, 230, 180, a * 0.5 * 255);
