}

function draw() {
  const ctx = drawingContext;
  let g = ctx.createLinearGradient(0, 0, 0, height);
  g.addColorStop(0, '#04050b');
  g.addColorStop(0.4, '#0c0e1a');
  g.addColorStop(0.72, '#151226');
  g.addColorStop(1, '#0a0812');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);

  noStroke();
  for (let i = 0; i < 55; i++) {
    let x = random(width), y = random(height * 0.9);
    let r = random(120, 420);
    let a = noise(x * 0.0015, y * 0.0015) * 0.06;
    fill(120 + random(60), 110 + random(50), 160 + random(60), a * 255);
    ellipse(x, y, r * 2, r * 1.3);
  }

  let bg = ctx.createLinearGradient(0, 0, 0, height * 0.95);
  bg.addColorStop(0, 'rgba(255,216,150,0.13)');
  bg.addColorStop(0.6, 'rgba(255,210,140,0.05)');
  bg.addColorStop(1, 'rgba(255,210,140,0)');
  ctx.fillStyle = bg;
  beginShape();
  vertex(660, -20);
  vertex(940, -20);
  vertex(1450, 1750);
  vertex(150, 1750);
  endShape(CLOSE);

  let gg = ctx.createRadialGradient(800, 0, 0, 800, 0, 700);
  gg.addColorStop(0, 'rgba(255,230,180,0.35)');
  gg.addColorStop(1, 'rgba(255,230,180,0)');
  ctx.fillStyle = gg;
  ctx.fillRect(0, 0, width, 800);

  for (let i = 0; i < 650; i++) {
    let x = random(width), y = random(height);
    let warm = (x > 150 && x < 1450 && y < 1700);
    let a = random(0.02, 0.14);
    if (warm) fill(255, 220, 170, a * 255);
    else fill(180, 190, 230, a * 255);
    let s = random(1, 3.2);
    ellipse(x, y, s, s);
  }

  paintLedge(ctx);

  fill(0, 0, 0, 90);
  ellipse(1120, 1605, 380, 46);
  fill(0, 0, 0, 60);
  ellipse(790, 1590, 120, 24);

  paintStem();
  paintFlower();
  paintFallenPetals();
  paintEmbers();

  for (let i = 0; i < 16; i++) {
    fill(170, 180, 220, random(0.02, 0.05) * 255);
    ellipse(random(width), random(1450, 2000), random(400, 900), random(80, 200));
  }

  let vg = ctx.createRadialGradient(800, 950, 300, 800, 1000, 1500);
  vg.addColorStop(0, 'rgba(0,0,0,0)');
  vg.addColorStop(1, 'rgba(0,0,0,0.62)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, width, height);
}

const SKY_STOPS = [
  [0.00, [16, 14, 36]],
  [0.34, [50, 36, 72]],
  [0.56, [118, 64, 82]],
  [0.70, [192, 108, 84]],
  [0.78, [233, 160, 98]]
];

const LEAF_RGB = [
  [201, 111, 74],
  [217, 160, 91],
  [163, 74, 63],
  [224, 184, 120],
  [140, 60, 70]
];

let treeBaseX = 0;
let treeBaseY = 0;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  paintSky();
  paintStars();
  paintMoon();
  paintBackHill();
  paintFrontHill();
  paintTree();
  paintFallingLeaves();
  paintGroundLeaves();
  paintWisps();
  paintBirds();
  paintMist();
  paintGrain();
  paintVignette();
}

function skyColorAt(y) {
  const t = constrain(y / height, 0, 1);
  for (let i = 0; i < SKY_STOPS.length - 1; i++) {
    const p0 = SKY_STOPS[i][0], c0 = SKY_STOPS[i][1];
    const p1 = SKY_STOPS[i + 1][0], c1 = SKY_STOPS[i + 1][1];
    if (t >= p0 && t <= p1) {
      const f = (t - p0) / (p1 - p0);
      return color(lerp(c0[0], c1[0], f), lerp(c0[1], c1[1], f), lerp(c0[2], c1[2], f));
    }
  }
  const c = SKY_STOPS[SKY_STOPS.length - 1][1];
  return color(c[0], c[1], c[2]);
}

function paintSky() {
  noStroke();
  for (let y = 0; y < height; y += 2) {
    fill(skyColorAt(y));
    rect(0, y, width, 2);
  }
}

function paintStars() {
  noStroke();
  for (let i = 0; i < 240; i++) {
    const y = random(height * 0.55);
    const a = map(y, 0, height * 0.55, 150, 20);
    fill(232, 228, 244, random(30, a));
    circle(random(width), y, random(1, 3));
  }
}

function paintMoon() {
  const cx = width * 0.60, cy = height * 0.585, r = 235;
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(cx, cy, r * 0.8, cx, cy, r * 3.4);
  g.addColorStop(0, 'rgba(246,228,196,0.38)');
  g.addColorStop(0.5, 'rgba(230,180,140,0.12)');
  g.addColorStop(1, 'rgba(230,180,140,0)');
  ctx.fillStyle = g;
  ctx.fillRect(cx - r * 3.4, cy - r * 3.4, r * 6.8, r * 6.8);

  noStroke();
  fill(243, 231, 204);
  circle(cx, cy, r * 2);
  fill(214, 192, 158, 60);
  ellipse(cx - 60, cy - 40, 70, 56, 0.4);
  ellipse(cx + 50, cy + 30, 46, 38, -0.3);
  ellipse(cx + 10, cy - 90, 34, 28, 0.2);
  ellipse(cx - 20, cy + 80, 52, 40, 0.9);
  fill(180, 140, 120, 40);
  ellipse(cx, cy + r * 0.55, r * 1.7, r * 0.9);
  noFill();
  stroke(246, 228, 196, 40);
  strokeWeight(2);
  circle(cx, cy, r * 2 + 26);
}

function backHillY(x) {
  return height * 0.72 - noise(x * 0.0016, 1.7) * 170 - 40;
}

function frontHillY(x) {
  return height * 0.80 - noise(x * 0.0022, 9.3) * 220 - 30;
}

function paintBackHill() {
  noStroke();
  fill(42, 32, 64);
  beginShape();
  vertex(0, height);
  vertex(0, backHillY(0));
  for (let x = 0; x <= width; x += 32) vertex(x, backHillY(x));
  vertex(width, height);
  endShape(CLOSE);
}

function paintFrontHill() {
  noStroke();
  fill(22, 16, 34);
  beginShape();
  vertex(0, height);
  vertex(0, frontHillY(0));
  for (let x = 0; x <= width; x += 32) vertex(x, frontHillY(x));
  vertex(width, height);
  endShape(CLOSE);
}

function branch(x, y, angle, len, w, depth) {
  if (depth <= 0 || len < 3) return;
  const nx = x + cos(angle) * len;
  const ny = y + sin(angle) * len;
  stroke(13, 10, 22);
  strokeWeight(w);
  strokeCap(ROUND);
  line(x, y, nx, ny);
  if (depth <= 2) {
    const n = floor(random(0, 3));
    for (let i = 0; i < n; i++) {
      const rgb = random(LEAF_RGB);
      noStroke();
      fill(rgb[0], rgb[1], rgb[2], 170);
      ellipse(nx + random(-6, 6), ny + random(-6, 6), random(6, 11), random(4, 7), random(TWO_PI));
    }
    return;
  }
  const n = depth > 6 ? 3 : 2;
  for (let i = 0; i < n; i++) {
    const spread = random(0.25, 0.7);
    const na = angle + random(-spread, spread) + map(i, 0, n - 1, -0.45, 0.45);
    branch(nx, ny, na, len * random(0.66, 0.8), max(w * 0.66, 0.8), depth - 1);
  }
}

function paintTree() {
  treeBaseX = width * 0.38;
  treeBaseY = frontHillY(treeBaseX) + 8;
  stroke(13, 10, 22);
  strokeCap(ROUND);
  strokeWeight(9);
  line(treeBaseX, treeBaseY, treeBaseX - 55, treeBaseY + 18);
  line(treeBaseX, treeBaseY, treeBaseX + 60, treeBaseY + 16);
  strokeWeight(6);
  line(treeBaseX, treeBaseY, treeBaseX - 20, treeBaseY + 26);
  line(treeBaseX, treeBaseY, treeBaseX + 25, treeBaseY + 24);
  branch(treeBaseX, treeBaseY, -HALF_PI + random(-0.06, 0.06), 175, 22, 10);
}

function paintFallingLeaves() {
  noStroke();
  for (let i = 0; i < 170; i++) {
    let x, y;
    if (random() < 0.6) {
      x = treeBaseX + random(-300, 320);
      y = treeBaseY - random(0, 720);
    } else {
      x = random(width);
      y = random(height * 0.2, height * 0.95);
    }
    const rgb = random(LEAF_RGB);
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    fill(rgb[0], rgb[1], rgb[2], random(140, 220));
    ellipse(0, 0, random(8, 17), random(5, 10));
    pop();
  }
}

function paintGroundLeaves() {
  noStroke();
  for (let i = 0; i < 70; i++) {
    const x = random(width * 0.05, width * 0.95);
    const y = frontHillY(x) + random(2, 50);
    const rgb = random(LEAF_RGB);
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    fill(rgb[0], rgb[1], rgb[2], random(110, 180));
    ellipse(0, 0, random(7, 14), random(4, 8));
    pop();
  }
}

function paintWisps() {
  noStroke();
  for (let i = 0; i < 14; i++) {
    const t = i / 13;
    const x = treeBaseX + 26 + sin(t * 6 + i * 1.7) * (30 + 90 * t) + random(-8, 8);
    const y = treeBaseY - 30 - t * random(520, 780);
    const r = lerp(9, 2.2, t);
    fill(255, 226, 170, lerp(14, 4, t));
    circle(x, y, r * 4);
    fill(255, 236, 190, lerp(120, 25, t));
    circle(x, y, r * 1.6);
  }
}

function paintBirds() {
  stroke(24, 18, 38, 150);
  strokeWeight(2.5);
  noFill();
  for (let i = 0; i < 6; i++) {
    const x = random(width * 0.08, width * 0.45);
    const y = random(height * 0.10, height * 0.34);
    const s = random(8, 18);
    beginShape();
    vertex(x - s, y);
    quadraticVertex(x - s * 0.5, y - s * 0.9, x, y);
    quadraticVertex(x + s * 0.5, y - s * 0.9, x + s, y);
    endShape();
  }
}

function paintMist() {
  noStroke();
  for (let i = 0; i < 12; i++) {
    const y = height * 0.68 + random(-40, 140);
    fill(238, 214, 190, random(4, 10));
    ellipse(random(width * 0.2, width * 0.8), y, random(width * 0.7, width * 1.3), random(26, 70));
  }
}

function paintGrain() {
  strokeWeight(1);
  for (let i = 0; i < 14000; i++) {
    const g = random(255);
    stroke(g, g, g, random(3, 10));
    point(random(width), random(height));
  }
}

function paintVignette() {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(width / 2, height * 0.42, width * 0.30, width / 2, height * 0.5, width * 0.95);
  g.addColorStop(0, 'rgba(8,6,16,0)');
  g.addColorStop(1, 'rgba(8,6,16,0.62)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
}

const W = 1600;
const H = 2000;
const HORIZON = 1150;
const MOON = { x: 1130, y: 430, r: 205 };
const LEAF_COLORS = ['#c98a3b', '#a8642c', '#8f4f24', '#d9b36a', '#7c4a2a', '#b5773a'];

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
}

function draw() {
  const ctx = drawingContext;

  // sky
  let sky = ctx.createLinearGradient(0, 0, 0, HORIZON);
  sky.addColorStop(0, '#04061a');
  sky.addColorStop(0.55, '#0b1330');
  sky.addColorStop(1, '#1b2a4e');
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, W, HORIZON);

  // stars
  noStroke();
  for (let i = 0; i < 170; i++) {
    let x = random(W);
    let y = random(HORIZON * 0.9);
    if (dist(x, y, MOON.x, MOON.y) < MOON.r * 1.7) continue;
    let a = random(0.15, 0.85) * (1 - y / HORIZON * 0.45);
    fill(228, 234, 255, a * 255);
    ellipse(x, y, random(1, 2.6), random(1, 2.6));
  }

  // painterly clouds
  for (let i = 0; i < 240; i++) {
    let x = random(W);
    let y = random(HORIZON);
    if (noise(x * 0.0018, y * 0.0018) > 0.52) fill(42, 58, 100, random(5, 16));
    else fill(6, 10, 26, random(5, 14));
    ellipse(x, y, random(90, 340), random(22, 70));
  }

  // moon glow
  let glow = ctx.createRadialGradient(MOON.x, MOON.y, MOON.r * 0.3, MOON.x, MOON.y, MOON.r * 3.4);
  glow.addColorStop(0, 'rgba(246,236,216,0.5)');
  glow.addColorStop(0.35, 'rgba(214,208,196,0.16)');
  glow.addColorStop(1, 'rgba(214,208,196,0)');
  ctx.fillStyle = glow;
  ctx.beginPath();
  ctx.arc(MOON.x, MOON.y, MOON.r * 3.4, 0, TWO_PI);
  ctx.fill();

  // moon disc
  ctx.fillStyle = '#f3ead9';
  ctx.beginPath();
  ctx.arc(MOON.x, MOON.y, MOON.r, 0, TWO_PI);
  ctx.fill();

  // craters + shading
  ctx.save();
  ctx.beginPath();
  ctx.arc(MOON.x, MOON.y, MOON.r, 0, TWO_PI);
  ctx.clip();
  for (let i = 0; i < 30; i++) {
    let a = random(TWO_PI);
    let rr = random(MOON.r * 0.1, MOON.r * 0.88);
    ctx.fillStyle = 'rgba(186,176,158,' + random(0.07, 0.2).toFixed(3) + ')';
    ctx.beginPath();
    ctx.arc(MOON.x + cos(a) * rr, MOON.y + sin(a) * rr, random(9, 52), 0, TWO_PI);
    ctx.fill();
  }
  let shade = ctx.createLinearGradient(MOON.x - MOON.r, MOON.y - MOON.r, MOON.x + MOON.r * 0.8, MOON.y + MOON.r);
  shade.addColorStop(0, 'rgba(255,252,240,0.12)');
  shade.addColorStop(1, 'rgba(110,100,88,0.2)');
  ctx.fillStyle = shade;
  ctx.fillRect(MOON.x - MOON.r, MOON.y - MOON.r, MOON.r * 2, MOON.r * 2);
  ctx.restore();

  // birds crossing the moon
  noFill();
  stroke(30, 26, 22, 210);
  strokeWeight(2.2);
  bird(952, 428, 20);
  bird(995, 402, 15);
  bird(1022, 448, 12);
  noStroke();

  // dark wisp across lower moon
  for (let i = 0; i < 110; i++) {
    let t = i / 110;
    let x = MOON.x - MOON.r * 1.7 + t * MOON.r * 3.4 + random(-26, 26);
    let y = MOON.y + MOON.r * 0.42 + sin(t * PI) * 26 + random(-12, 12);
    fill(9, 13, 30, random(7, 20));
    ellipse(x, y, random(60, 150), random(9, 22));
  }

  // distant treeline
  fill(6, 9, 20, 235);
  beginShape();
  vertex(0, HORIZON + 2);
  for (let x = 0; x <= W; x += 16) {
    let m = map(x, 0, W, 1, 0.2);
    vertex(x, HORIZON - (noise(x * 0.008, 7) * 30 + 4) * m);
  }
  vertex(W, HORIZON + 2);
  endShape(CLOSE);

  // horizon haze
  fill(140, 160, 210, 18);
  rect(0, HORIZON - 8, W, 16);

  // water
  let wat = ctx.createLinearGradient(0, HORIZON, 0, H);
  wat.addColorStop(0, '#17253f');
  wat.addColorStop(0.3, '#0c1630');
  wat.addColorStop(1, '#03050c');
  ctx.fillStyle = wat;
  ctx.fillRect(0, HORIZON, W, H - HORIZON);

  // tree reflection smudge
  for (let i = 0; i < 70; i++) {
    fill(4, 7, 15, random(10, 30));
    ellipse(random(70, 580), random(HORIZON + 8, HORIZON + 340), random(18, 70), random(3, 7));
  }

  // water strokes
  for (let i = 0; i < 950; i++) {
    let y = HORIZON + random(H - HORIZON);
    let x = random(-120, W);
    let len = random(30, 230);
    let depth = (y - HORIZON) / (H - HORIZON);
    let base = lerpColor(color(32, 48, 84), color(5, 8, 17), depth);
    let dm = abs(x + len / 2 - MOON.x);
    let boost = constrain(1 - dm / 520, 0, 1) * (1 - depth * 0.55);
    let c = lerpColor(base, color(233, 223, 200), boost * 0.55);
    fill(red(c), green(c), blue(c), random(12, 38));
    rect(x, y, len, random(1.5, 4));
  }

  // moonlight path on water
  for (let y = HORIZON + 4; y < H; y += random(5, 9)) {
    let depth = (y - HORIZON) / (H - HORIZON);
    let w = 24 + noise(y * 0.02, 1) * 130 + depth * 170;
    let x = MOON.x + (noise(y * 0.05, 3) - 0.5) * (26 + depth * 100);
    let a = 0.32 * (1 - depth * 0.78) * (0.55 + noise(y * 0.03, 5) * 0.7);
    fill(238, 228, 202, a * 255);
    ellipse(x, y, w, random(2.5, 5));
  }

  // mist bands
  for (let i = 0; i < 26; i++) {
    fill(150, 170, 215, random(5, 12));
    ellipse(random(W), random(HORIZON + 20, HORIZON + 420), random(200, 520), random(8, 20));
  }

  // shore
  fill(5, 7, 14);
  beginShape();
  vertex(0, H);
  vertex(0, 1715);
  for (let x = 0; x <= 640; x += 24) {
    vertex(x, 1715 + noise(x * 0.01, 5) * 55 + (x / 640) * 285);
  }
  vertex(640, H);
  endShape(CLOSE);

  // grass
  for (let i = 0; i < 150; i++) {
    let x = random(0, 620);
    let yTop = 1715 + noise(x * 0.01, 5) * 55 + (x / 640) * 285;
    stroke(7, 11, 21, 220);
    strokeWeight(random(1, 2.4));
    line(x, yTop + 5, x + random(-7, 7), yTop - random(8, 30));
  }
  noStroke();

  // tree
  branch(255, 1985, -HALF_PI + 0.06, 330, 46, 8);
  branch(255, 1985, -HALF_PI - 0.22, 210, 26, 6);
  noStroke();

  // boat with lantern
  const BX = 1060;
  const BY = 1490;
  for (let i = 0; i < 16; i++) {
    let y = BY + 26 + i * 15 + random(-3, 3);
    fill(7, 10, 19, max(20, 80 - i * 4));
    ellipse(BX + random(-6, 6), y, 150 * (1 - i / 20) + random(-12, 12), 5);
  }
  for (let y = BY + 22; y < BY + 330; y += random(6, 10)) {
    let depth = (y - BY) / 330;
    let w = 8 + noise(y * 0.05, 9) * 24 + depth * 34;
    fill(255, 178, 96, 0.5 * (1 - depth) * 255);
    ellipse(BX + (noise(y * 0.04, 11) - 0.5) * 26, y, w, 3);
  }
  fill(9, 12, 21);
  beginShape();
  vertex(BX - 95, BY - 8);
  bezierVertex(BX - 55, BY + 26, BX + 55, BY + 26, BX + 95, BY - 8);
  bezierVertex(BX + 55, BY + 2, BX - 55, BY + 2, BX - 95, BY - 8);
  endShape(CLOSE);
  noFill();
  stroke(90, 105, 145, 130);
  strokeWeight(2);
  beginShape();
  vertex(BX - 95, BY - 8);
  bezierVertex(BX - 55, BY + 2, BX + 55, BY + 2, BX + 95, BY - 8);
  endShape();
  noStroke();
  stroke(12, 15, 26);
  strokeWeight(4);
  line(BX, BY - 6, BX, BY - 52);
  noStroke();
  let lg = ctx.createRadialGradient(BX, BY - 60, 2, BX, BY - 60, 70);
  lg.addColorStop(0, 'rgba(255,214,150,0.85)');
  lg.addColorStop(0.25, 'rgba(255,180,95,0.35)');
  lg.addColorStop(1, 'rgba(255,170,80,0)');
  ctx.fillStyle = lg;
  ctx.beginPath();
  ctx.arc(BX, BY - 60, 70, 0, TWO_PI);
  ctx.fill();
  fill(255, 226, 170);
  ellipse(BX, BY - 60, 11, 13);
  fill(60, 40, 25);
  rect(BX - 7, BY - 70, 14, 4);
  rect(BX - 7, BY - 52, 14, 4);

  // floating leaves on water
  for (let i = 0; i < 26; i++) {
    let x = random(60, W - 60);
    let y = HORIZON + random(30, H - HORIZON - 80);
    let s = random(5, 13);
    let c = color(LEAF_COLORS[floor(random(LEAF_COLORS.length))]);
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    scale(1, 0.45);
    fill(red(c), green(c), blue(c), 190);
    ellipse(0, 0, s, s * 0.62);
    pop();
    fill(red(c), green(c), blue(c), 55);
    ellipse(x + random(-2, 2), y + s * 0.9, s * 0.8, 2);
  }

  // falling leaves
  for (let i = 0; i < 60; i++) {
    let x = random() < 0.62 ? random(0, 950) : random(0, W);
    let y = random(180, 1650);
    let s = random(6, 17);
    let c = color(LEAF_COLORS[floor(random(LEAF_COLORS.length))]);
    let a = random(0.55, 0.95);
    if (random() < 0.3) {
      fill(0, 0, 0, 35);
      ellipse(x + 5, y + 6, s * 1.7, s * 1.3);
    }
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    noStroke();
    fill(red(c), green(c), blue(c), a * 255);
    ellipse(0, 0, s, s * 0.55);
    stroke(red(c) * 0.55, green(c) * 0.55, blue(c) * 0.55, a * 220);
    strokeWeight(1);
    line(-s * 0.42, 0, s * 0.42, 0);
    pop();
  }
  noStroke();

  // fireflies
  for (let i = 0; i < 34; i++) {
    let x = random(120, 1450);
    let y = random(480, 1520);
    let a = random(0.25, 0.9);
    fill(255, 208, 138, a * 55);
    ellipse(x, y, 11, 11);
    fill(255, 232, 182, a * 255);
    ellipse(x, y, 2.6, 2.6);
  }

  // grain
  for (let i = 0; i < 7000; i++) {
    if (random() < 0.5) fill(255, 255, 255, random(3, 9));
    else fill(0, 0, 0, random(4, 11));
    rect(random(W), random(H), random(1, 2.2), random(1, 2.2));
  }

  // vignette
  let vig = ctx.createRadialGradient(W / 2, H * 0.46, H * 0.32, W / 2, H * 0.5, H * 0.78);
  vig.addColorStop(0, 'rgba(0,0,8,0)');
  vig.addColorStop(1, 'rgba(0,0,10,0.52)');
  ctx.fillStyle = vig;
  ctx.fillRect(0, 0, W, H);
}

function branch(x, y, angle, len, w, depth) {
  if (depth <= 0 || w < 0.7) return;
  let x2 = x + cos(angle) * len;
  let y2 = y + sin(angle) * len;
  for (let k = 0; k < 3; k++) {
    stroke(6, 9, 17, random(150, 225));
    strokeWeight(w * random(0.85, 1.12));
    line(x + random(-2, 2), y + random(-2, 2), x2 + random(-3, 3), y2 + random(-3, 3));
  }
  stroke(96, 116, 168, 42);
  strokeWeight(max(0.6, w * 0.28));
  line(x + 1.6, y, x2 + 1.6, y2);
  let n = depth > 4 ? 2 : (random() < 0.72 ? 2 : 1);
  for (let i = 0; i < n; i++) {
    let spread = random(0.2, 0.45);
    let na = angle + (i === 0 ? -spread : spread) + random(-0.12, 0.12) - 0.06;
    branch(x2, y2, na, len * random(0.68, 0.8), w * 0.62, depth - 1);
  }
}

function bird(x, y, s) {
  noFill();
  arc(x - s / 2, y, s, s * 0.6, PI, TWO_PI);
  arc(x + s / 2, y, s, s * 0.6, PI, TWO_PI);
}

