function branch(x, y, angle, len, w, depth) {
  if (depth <= 0 || len < 10) return;
  let x2 = x + cos(angle) * len;
  let y2 = y + sin(angle) * len;
  stroke(22, 18, 26);
  strokeWeight(w);
  noFill();
  let mx = (x + x2) / 2 + (noise(x * 0.02, y * 0.02) - 0.5) * 50;
  let my = (y + y2) / 2 + (noise(y * 0.02, x * 0.02) - 0.5) * 50;
  quadraticCurveTo(mx, my, x2, y2);
  if (depth <= 2) {
    noStroke();
    for (let i = 0; i < 3; i++) {
      if (random() < 0.7) {
        let c = leafPalette[floor(random(leafPalette.length))];
        fill(red(c), green(c), blue(c), 200);
        ellipse(x2 + random(-14, 14), y2 + random(-14, 14), random(7, 13), random(5, 9));
      }
    }
  }
  let n = depth > 5 ? 3 : 2;
  let spread = map(depth, 1, 8, 0.25, 0.75);
  for (let i = 0; i < n; i++) {
    let na = angle + random(-spread, spread) + (i - (n - 1) / 2) * spread * 0.9;
    branch(x2, y2, na, len * random(0.66, 0.8), max(w * 0.62, 1.2), depth - 1);
  }
}

