function skyColor(t, stops) {
  for (let i = 0; i < stops.length - 1; i++) {
    if (t >= stops[i][0] && t <= stops[i + 1][0]) {
      let amt = (t - stops[i][0]) / (stops[i + 1][0] - stops[i][0]);
      return lerpColor(stops[i][1], stops[i + 1][1], amt);
    }
  }
  return stops[stops.length - 1][1];
}

function paintSky() {
  noStroke();
  const stops = [
    [0.00, color(9, 11, 32)],
    [0.30, color(30, 27, 66)],
    [0.52, color(66, 44, 92)],
    [0.72, color(128, 70, 88)],
    [0.88, color(196, 116, 74)],
    [1.00, color(232, 156, 84)]
  ];
  for (let y = 0; y < HORIZON; y += 2) {
    fill(skyColor(y / HORIZON, stops));
    rect(0, y, W, 2);
  }
}

