    let y0 = 1470 + b * 42 + random(-8, 8);
    fill(222, 226, 238, 9 + b * 2);
    beginShape();
    vertex(0, y0 + (noise(0, b * 3.1) - 0.5) * 30);
    for (let x = 0; x <= W; x += 24) {
      vertex(x, y0 + (noise(x * 0.006, b * 3.1) - 0.5) * 44);
    }
    vertex(W, y0 + 70 + noise(W * 0.006, b * 3.1) * 30);
    vertex(0, y0 + 80 + noise(0, b * 7.7) * 30);
    endShape(CLOSE);
  }
}

function branch(x, y, angle, len, w, depth, mult) {
  if (depth <= 0 || w < 0.7) return;
  strokeWeight(w * mult);
  let sx = x, sy = y;
  const steps = 3;
  for (let s = 0; s < steps; s++) {
    let a = angle + random(-0.09, 0.09);
    let nx = sx + cos(a) * (len / steps);
    let ny = sy + sin(a) * (len / steps);
    line(sx, sy, nx, ny);
    sx = nx; sy = ny;
  }
  let n = depth > 5 ? 2 : (random() < 0.8 ? 2 : 3);
  for (let i = 0; i < n; i++) {
    let na = angle + random(-0.5, 0.5) + (i - (n - 1) / 2) * 0.5;
    branch(sx, sy, na, len * random(0.66, 0.8), w * random(0.58, 0.7), depth - 1, mult);
  }
}

function paintTree() {
  stroke(10, 8, 20, 80);
  branch(TX, TY, -HALF_PI + 0.06, 175, 34, 9, 2.4);
  stroke(15, 12, 24, 255);
  branch(TX, TY, -HALF_PI + 0.06, 175, 30, 9, 1);
  stroke(236, 186, 116, 60);
  branch(TX + 4, TY - 3, -HALF_PI + 0.06, 175, 12, 9, 0.4);
  noStroke();
  fill(12, 10, 20);
  ellipse(TX, TY + 6, 150, 34);
  fill(28, 22, 40);
  circle(TX - 8, TY - 150, 18);
  fill(10, 8, 18);
  circle(TX - 8, TY - 150, 10);
}

function leafColor() {
  let c1 = color(232, 163, 61);
  let c2 = color(196, 110, 46);
  let c3 = color(140, 74, 40);
  if (random() < 0.5) return lerpColor(c1, c2, random());
  return lerpColor(c2, c3, random());
}

function drawLeaf(x, y, s, rot, col, a) {
  push();
  translate(x, y);
  rotate(rot);
  noStroke();
  fill(red(col), green(col), blue(col), a);
  beginShape();
  vertex(0, -s);
  bezierVertex(s * 0.9, -s * 0.45, s * 0.9, s * 0.45, 0, s);
  bezierVertex(-s * 0.9, s * 0.45, -s * 0.9, -s * 0.45, 0, -s);
  endShape(CLOSE);
  pop();
}

function paintFallingLeaves() {
  for (let i = 0; i < 140; i++) {
    let t = random();
    let sx = random(160, 860);
    let sy = random(520, 1150);
    let x = constrain(sx + random(0, 1) * (200 + 620 * t) + random(-40, 40), 20, W - 20);
    let y = constrain(sy + random(40, 60 + 420 * t), 60, 1560);
    drawLeaf(x, y, random(4, 11), random(TWO_PI), leafColor(), random(110, 220));
  }
}

function paintGroundLeaves() {
  for (let i = 0; i < 55; i++) {
    drawLeaf(TX + random(-260, 420), random(1560, 1960), random(4, 9),
