function paintGrain() {
  loadPixels();
  for (let i = 0; i < pixels.length; i += 8) {
    let n = random(-12, 12);
    for (let j = 0; j < 8; j += 4) {
      pixels[i + j] = constrain(pixels[i + j] + n, 0, 255);
      pixels[i + j + 1] = constrain(pixels[i + j + 1] + n, 0, 255);
      pixels[i + j + 2] = constrain(pixels[i + j + 2] + n, 0, 255);
    }
  }
  updatePixels();
