  for (let y = 0; y < height; y += 5) {
    let n = noise(y * 0.001);
    let c = color(40 + n * 30, 50 + n * 20, 60 + n * 40, 100 - y * 0.05);
    stroke(c);
    strokeWeight(2);
    line(0, y, width, y);
  }

  // Central figure (abstract, dissolving)
  push();
  translate(width / 2, height / 2);
  rotate(PI / 6);
  noStroke();

  // Body (fading into mist)
  for (let i = 0; i < 200; i++) {
    let x = random(-300, 300);
    let y = random(-400, 400);
    let d = dist(x, y, 0, 0);
    let s = map(d, 0, 500, 10, 0);
    let a = map(d, 0, 500, 150, 0);
    fill(200, 220, 255, a);
    ellipse(x, y, s, s * 1.5);
  }

  // Veil (translucent layers)
  for (let i = 0; i < 5; i++) {
    fill(255, 255, 255, 20 - i * 4);
    beginShape();
    vertex(-400, -500);
    vertex(400, -500);
    bezierVertex(300, -300, 200, 0, 400, 500);
    vertex(-400, 500);
    bezierVertex(-200, 0, -300, -300, -400, -500);
    endShape();
  }

  // Light (soft glow)
  for (let i = 0; i < 30; i++) {
    let x = random(-100, 100);
    let y = random(-200, 200);
    let s = random(50, 150);
    fill(255, 250, 220, 30);
    ellipse(x, y, s, s);
  }
  pop();

  // Foreground texture (subtle noise)
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let x = (i / 4) % width;
    let y = floor(i / 4 / width);
    let n = noise(x * 0.01, y * 0.01);
    pixels[i] = pixels[i] * (0.9 + n * 0.1);
    pixels[i + 1] = pixels[i + 1] * (0.9 + n * 0.1);
    pixels[i + 2] = pixels[i + 2] * (0.9 + n * 0.1);
  }
  updatePixels();
}

