  beginShape();
  for (let i = 0; i < TWO_PI; i += 0.1) {
    let r = 150 + noise(i*2, frameCount*0.01) * 30;
    let x = r * cos(i);
    let y = r * sin(i) * 0.8;
    curveVertex(x, y);
  }
  endShape(CLOSE);

  // Spine
  stroke(150, 130, 110, 200);
  strokeWeight(5);
  for (let i = -100; i < 100; i += 20) {
    let x = 0;
    let y = i + noise(i*0.1) * 10;
    line(x, y, x, y + 15);
  }

  // Dissolving limbs
  stroke(180, 160, 140, 100);
  strokeWeight(2);
  for (let i = 0; i < 50; i++) {
    let x1 = random(-200, 200);
    let y1 = random(-100, 300);
    let x2 = x1 + random(-30, 30);
    let y2 = y1 + random(-30, 30);
    line(x1, y1, x2, y2);
  }

  // Glowing core
  noStroke();
  for (let i = 0; i < 50; i++) {
    let r = random(50, 100);
    let alpha = random(50, 150);
    fill(255, 220, 180, alpha);
    ellipse(0, 0, r);
  }

  pop();

  // Distant horizon (trees/roots)
  stroke(80, 60, 40, 100);
  strokeWeight(1);
  for (let i = 0; i < 200; i++) {
    let x = random(width);
    let y = height*0.8 + random(100);
    let h = random(50, 200);
    line(x, y, x, y - h);
    for (let j = 0; j < 3; j++) {
      let branchX = x + random(-20, 20);
      let branchY = y - h * random(0.3, 0.7);
      line(x, y - h * random(0.2, 0.8), branchX, branchY);
    }
  }

  // Fading light rays
  noStroke();
  for (let i = 0; i < 10; i++) {
    let x = width/2 + random(-300, 300);
    let y1 = height*0.2;
    let y2 = height*0.6;
    let alpha = random(30, 80);
    fill(255, 240, 220, alpha);
    beginShape();
    vertex(x - 20, y1);
    vertex(x + 20, y1);
    vertex(x + 50, y2);
    vertex(x - 50, y2);
    endShape(CLOSE);
  }
