function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  background(15, 20, 30);

  // Distant, dying sky
  for (let i = 0; i < 100; i++) {
    let x = random(width);
    let y = random(height * 0.3);
    let d = random(0.5, 2);
    let a = map(y, 0, height * 0.3, 50, 10);
    fill(100 + random(50), 100 + random(50), 120 + random(30), a);
    noStroke();
    circle(x, y, d);
  }

  // Withered trees (left)
  for (let i = 0; i < 5; i++) {
    let x = width * 0.1 + i * 100;
    let y = height * 0.4;
    drawTree(x, y, 200, 0.7, 10);
  }

  // Withered trees (right)
  for (let i = 0; i < 4; i++) {
    let x = width * 0.7 + i * 80;
    let y = height * 0.5;
    drawTree(x, y, 150, 0.5, 8);
  }

  // Fallen petals (foreground)
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = height * 0.6 + random(height * 0.4);
    let s = random(5, 15);
    let rot = random(TWO_PI);
    let c = color(
      120 + random(50),
      80 + random(40),
      90 + random(30),
      150 + random(50)
    );
    drawPetal(x, y, s, rot, c);
  }

  // Faint roots (underground)
  for (let i = 0; i < 200; i++) {
    let x = random(width);
    let y = height * 0.8 + random(height * 0.2);
    let len = random(20, 80);
    let w = random(0.5, 2);
    let a = map(y, height * 0.8, height, 100, 30);
    stroke(100 + random(30), 80 + random(20), 60 + random(20), a);
    strokeWeight(w);
    noFill();
    beginShape();
    for (let j = 0; j < len; j++) {
      let nx = x + j * 0.5;
      let ny = y + noise(x * 0.01, y * 0.01, j * 0.1) * 20 - 10;
      vertex(nx, ny);
    }
    endShape();
  }

  // Moon (fading)
  fill(220, 220, 230, 100);
  noStroke();
  circle(width * 0.8, height * 0.2, 200);
  fill(15, 20, 30, 200);
  circle(width * 0.82, height * 0.18, 180);
}

function drawTree(x, y, h, decay, branches) {
  stroke(80 + random(20), 60 + random(20), 40 + random(20), 150);
  strokeWeight(3 * decay);
  noFill();

  // Trunk
  beginShape();
  vertex(x, y);
  for (let i = 0; i < h; i++) {
    let nx = x + noise(x * 0.01, y * 0.01, i * 0.1) * 10 - 5;
    let ny = y - i;
    vertex(nx, ny);
  }
  endShape();

  // Branches
  for (let i = 0; i < branches; i++) {
    let bx = x + random(-20, 20);
    let by = y - random(h * 0.3, h * 0.8);
    let len = random(30, 80) * decay;
    let angle = random(-PI * 0.3, PI * 0.3);
    let sw = 1.5 * decay;

    strokeWeight(sw);
    beginShape();
    vertex(bx, by);
    for (let j = 0; j < len; j++) {
      let nx = bx + cos(angle) * j;
      let ny = by + sin(angle) * j + noise(bx * 0.01, by * 0.01, j * 0.1) * 5;
      vertex(nx, ny);
    }
    endShape();
  }
}

function drawPetal(x, y, s, rot, c) {
  push();
  translate(x, y);
  rotate(rot);
  fill(c);
  noStroke();
  beginShape();
  for (let i = 0; i < TWO_PI; i += PI / 10) {
    let r = s * (0.5 + 0.5 * sin(i * 3 + random(0.1)));
    vertex(cos(i) * r, sin(i) * r);
  }
  endShape(CLOSE);
  pop();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  background(10, 15, 20);

  // Base mist
  for (let i = 0; i < 5000; i++) {
    let x = random(width);
    let y = random(height);
    let d = dist(x, y, width/2, height/2);
    let alpha = map(d, 0, width/1.5, 20, 0);
    let size = map(d, 0, width/1.5, 0.5, 2);
    fill(200, 200, 220, alpha);
    noStroke();
    ellipse(x, y, size);
  }

  // Central form (hand-like)
  push();
  translate(width/2, height/2);
  rotate(PI/6);
  noFill();
  stroke(180, 180, 200, 150);
  strokeWeight(1.5);

  // Fingers
  for (let i = 0; i < 5; i++) {
    let angle = map(i, 0, 4, -PI/3, PI/3);
    let len = map(i, 0, 4, 300, 400);
    let w = map(i, 0, 4, 15, 8);
    let x1 = cos(angle) * 100;
    let y1 = sin(angle) * 100;
    let x2 = cos(angle) * len;
    let y2 = sin(angle) * len;

    // Bend
    let ctrlX = cos(angle) * (len * 0.6);
    let ctrlY = sin(angle) * (len * 0.6) + random(-50, 50);

    strokeWeight(w);
    bezier(x1, y1, ctrlX, ctrlY, ctrlX, ctrlY, x2, y2);

    // Fading tips
    for (let j = 0; j < 10; j++) {
      let t = map(j, 0, 9, 0.8, 1);
      let px = bezierPoint(x1, ctrlX, ctrlX, x2, t);
      let py = bezierPoint(y1, ctrlY, ctrlY, y2, t);
      let sw = map(j, 0, 9, w, 0.5);
      strokeWeight(sw);
      point(px, py);
    }
  }

  // Palm
  strokeWeight(2);
  beginShape();
  for (let a = -PI/3; a <= PI/3; a += 0.1) {
    let r = 120 + noise(cos(a)*10, sin(a)*10) * 30;
    let x = cos(a) * r;
    let y = sin(a) * r;
    vertex(x, y);
  }
  endShape(CLOSE);

  // Veins/lines
  stroke(150, 150, 180, 100);
  strokeWeight(0.8);
  for (let i = 0; i < 20; i++) {
    let x = random(-100, 100);
    let y = random(-80, 80);
    let x2 = x + random(-30, 30);
    let y2 = y + random(-30, 30);
    line(x, y, x2, y2);
  }
  pop();

  // Distant figures (implied presence)
  for (let i = 0; i < 15; i++) {
    let x = random(width);
    let y = random(height * 0.7, height);
    let w = random(20, 40);
    let h = random(80, 150);
    let alpha = random(30, 80);
    fill(50, 50, 70, alpha);
    noStroke();
    rect(x, y, w, h, 5);
  }

  // Fading horizon
  for (let y = height * 0.8; y < height; y += 5) {
    let alpha = map(y, height * 0.8, height, 50, 0);
    stroke(30, 30, 50, alpha);
    strokeWeight(1);
    line(0, y, width, y);
  }
}

