    let x = voidX + cos(angle) * dist;
    let y = voidY + sin(angle) * dist;
    let sz = random(1, 4);
    let alpha = map(dist, voidSize * 0.3, voidSize * 0.8, 100, 10);
    let c = color(180 + random(50), 190 + random(40), 200 + random(30), alpha);
    fill(c);
    noStroke();
    ellipse(x, y, sz);
  }

  // The void itself (negative space)
  fill(10, 15, 25);
  noStroke();
  beginShape();
  for (let angle = 0; angle < TWO_PI; angle += 0.05) {
    let dist = voidSize * 0.5 * (0.9 + 0.2 * noise(cos(angle) * 5, sin(angle) * 5, 10));
    vertex(voidX + cos(angle) * dist, voidY + sin(angle) * dist);
  }
  endShape(CLOSE);

  // Fading tendrils (death's reach)
  for (let i = 0; i < 15; i++) {
    let x1 = voidX + random(-voidSize * 0.3, voidSize * 0.3);
    let y1 = voidY + random(-voidSize * 0.2, voidSize * 0.2);
    let x2 = x1 + random(-voidSize * 0.4, voidSize * 0.4);
    let y2 = y1 + random(-voidSize * 0.3, voidSize * 0.3);
    let w = random(0.5, 2);
    let c = color(100 + random(50), 120 + random(40), 130 + random(30), 30 + random(20));
    stroke(c);
    strokeWeight(w);
    line(x1, y1, x2, y2);
  }

  // Subtle texture
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let x = (i / 4) % width;
    let y = floor(i / 4 / width);
    let d = dist(x, y, voidX, voidY);
    if (d < voidSize * 0.6) {
      let n = noise(x * 0.01, y * 0.01) * 20;
      pixels[i] = constrain(pixels[i] + n, 0, 255);
      pixels[i + 1] = constrain(pixels[i + 1] + n, 0, 255);
      pixels[i + 2] = constrain(pixels[i + 2] + n, 0, 255);
    }
  }
  updatePixels();
}

