    let n = noise(x * 0.005, y * 0.005) * 255;
    fill(200, 200, 220, n * 0.3);
    circle(x, y, random(2, 6));
  }

  // Ground (cracked earth)
  fill(40, 30, 20);
  beginShape();
  vertex(0, height * 0.6);
  for (let x = 0; x < width; x += 20) {
    let y = height * 0.6 + noise(x * 0.01) * 50;
