    }

    // Branches (skeletal)
    stroke(80, 60, 40);
    strokeWeight(2);
    for (let j = 0; j < 5; j++) {
      let bx = x + random(-trunkWidth, trunkWidth);
      let by = height * 0.6 - random(trunkHeight * 0.3, trunkHeight * 0.9);
