function draw() {
  background(10, 15, 25);

  // Ground cracks (noise-based)
  stroke(40, 50, 60);
  strokeWeight(3);
  noFill();
  for (let y = 1200; y < height; y += 50) {
    beginShape();
    for (let x = 0; x < width; x += 10) {
      let n = noise(x * 0.005, y * 0.002) * 20;
      vertex(x, y + n);
    }
    endShape();
  }

  // Tree trunk (dark, twisted)
  stroke(30, 20, 10);
  strokeWeight(80);
  noFill();
  beginShape();
  vertex(width / 2, height);
  bezierVertex(width / 2 - 100, height - 300, width / 2 + 150, height - 600, width / 2, height - 800);
  bezierVertex(width / 2 - 50, height - 900, width / 2 + 80, height - 1000, width / 2, height - 1200);
  endShape();

  // Branches (recursive, skeletal)
  stroke(50, 40, 30);
  strokeWeight(15);
  drawBranch(width / 2, height - 1200, -PI / 2, 200, 0);

  // Ghost lights (soft circles)
  noStroke();
  for (let i = 0; i < 150; i++) {
    let x = random(width);
    let y = random(height - 1200, height - 200);
    let d = random(10, 40);
    let c = color(200, 220, 255, random(50, 150));
    fill(c);
    circle(x, y, d);
    // Faint glow
    fill(red(c), green(c), blue(c), 10);
    circle(x, y, d * 2);
  }

  // Falling leaves (subtle, scattered)
  stroke(100, 80, 60, 150);
  strokeWeight(1);
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = random(height - 1200, height);
    let size = random(3, 8);
    line(x, y, x + size, y + size * 0.5);
    line(x + size, y, x, y + size * 0.5);
  }
}

function drawBranch(x, y, angle, len, depth) {
  if (len < 5 || depth > 8) return;
  let x2 = x + cos(angle) * len;
  let y2 = y + sin(angle) * len;
  line(x, y, x2, y2);

  let newLen = len * random(0.6, 0.8);
  let angle1 = angle + random(-0.4, 0.4);
  let angle2 = angle + random(-0.4, 0.4);
  drawBranch(x2, y2, angle1, newLen, depth + 1);
  if (random() > 0.7) drawBranch(x2, y2, angle2, newLen * 0.8, depth + 1);
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  background(10, 15, 20);

  // Base layers: cosmic noise and fading threads
  for (let i = 0; i < 5000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.002, y * 0.002) * 255;
    let s = map(n, 0, 255, 0.5, 2);
    stroke(n, n * 0.8, n * 1.2, 30);
    strokeWeight(s);
    point(x, y);
  }

  // Central "unweaving" vortex
  let centerX = width / 2;
  let centerY = height / 2;
  let maxRadius = min(width, height) * 0.45;

  for (let r = maxRadius; r > 0; r -= 0.5) {
    let angleOffset = map(r, 0, maxRadius, 0, TWO_PI * 3);
    let points = 300;
    let alpha = map(r, 0, maxRadius, 200, 0);
    let weight = map(r, 0, maxRadius, 0.3, 1.5);

    beginShape();
    for (let i = 0; i <= points; i++) {
      let angle = map(i, 0, points, 0, TWO_PI);
      let noiseVal = noise(
        cos(angle) * r * 0.01 + angleOffset,
        sin(angle) * r * 0.01 + angleOffset
      );
      let distortion = map(noiseVal, 0, 1, -r * 0.1, r * 0.1);
      let x = centerX + (r + distortion) * cos(angle);
      let y = centerY + (r + distortion) * sin(angle);

      // Fading threads breaking apart
      if (i % 10 === 0 && r < maxRadius * 0.8) {
        let breakLength = random(r * 0.05, r * 0.15);
        let breakX = x + breakLength * cos(angle + random(-0.2, 0.2));
        let breakY = y + breakLength * sin(angle + random(-0.2, 0.2));
        stroke(180, 160, 200, alpha * 0.7);
        strokeWeight(weight * 0.8);
        line(x, y, breakX, breakY);
      }

      // Main spiral
      stroke(220, 200, 240, alpha);
      strokeWeight(weight);
      if (i > 0) vertex(x, y);
    }
    endShape();
  }

  // Dissolving fragments (floating remnants)
  for (let i = 0; i < 200; i++) {
    let x = random(width);
    let y = random(height * 0.3, height * 0.7);
    let size = random(2, 10);
    let angle = random(TWO_PI);
    let speed = random(0.5, 2);
    let life = random(0.3, 1);

    // Fragments are half-erased, half-glowing
    stroke(200, 180, 220, 150 * life);
    strokeWeight(size * 0.3);
    noFill();
    push();
    translate(x, y);
    rotate(angle);
    arc(0, 0, size, size * 0.5, 0, PI * life);
    pop();
  }

  // Subtle radial gradient (light decay)
  for (let r = 0; r < maxRadius * 1.2; r += 5) {
    let alpha = map(r, 0, maxRadius * 1.2, 5, 0);
    stroke(40, 30, 60, alpha);
    noFill();
    strokeWeight(1);
    ellipse(centerX, centerY, r * 2);
  }
}

