  // Central "unweaving" threads
  let centerX = width / 2;
  let centerY = height / 2;
  let threadCount = 120;
  let maxLength = min(width, height) * 0.8;

  for (let i = 0; i < threadCount; i++) {
    let angle = random(TWO_PI);
    let length = random(maxLength * 0.3, maxLength);
    let weight = random(0.5, 3);
    let opacity = random(50, 200);
    let hue = random(30, 60);

    // Thread path (noise-based)
    let points = [];
    let segments = floor(random(10, 30));
    for (let j = 0; j <= segments; j++) {
      let t = j / segments;
      let nx = centerX + cos(angle) * length * t * 0.5;
      let ny = centerY + sin(angle) * length * t * 0.5;
      let offsetX = (noise(i * 0.1, j * 0.1, 0) - 0.5) * 200;
      let offsetY = (noise(i * 0.1, j * 0.1, 100) - 0.5) * 200;
      points.push(createVector(nx + offsetX, ny + offsetY));
    }

    // Draw thread
    stroke(hue, 80, 90, opacity);
    strokeWeight(weight);
    noFill();
    beginShape();
    for (let p of points) {
      curveVertex(p.x, p.y);
    }
    endShape();

    // Frayed ends (particles)
    if (random() > 0.3) {
      let end = points[points.length - 1];
      let particleCount = floor(random(5, 20));
      for (let k = 0; k < particleCount; k++) {
        let px = end.x + random(-30, 30);
        let py = end.y + random(-30, 30);
        let size = random(0.5, 2);
        let pOpacity = random(50, 150);
        fill(hue, 80, 90, pOpacity);
        noStroke();
        ellipse(px, py, size, size);
      }
    }
  }

  // Veil of dissolution (top layer)
  for (let i = 0; i < 5000; i++) {
    let x = random(width);
    let y = random(height);
    let d = dist(x, y, centerX, centerY);
    let size = random(0.5, 2);
    let opacity = map(d, 0, maxLength * 0.5, 200, 0);

    if (opacity > 10) {
      fill(40, 60, 70, opacity);
      noStroke();
      ellipse(x, y, size, size);
    }
  }

  // Core: absence of form
  noStroke();
  fill(10, 15, 20);
  ellipse(centerX, centerY, 150, 150);
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  background(10, 15, 20);

  // Base darkness with subtle noise
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    const x = (i / 4) % width;
    const y = floor(i / 4 / width);
    const n = noise(x * 0.005, y * 0.005) * 0.3 + 0.7;
    pixels[i] = 10 * n;
    pixels[i + 1] = 15 * n;
    pixels[i + 2] = 20 * n;
    pixels[i + 3] = 255;
  }
  updatePixels();

  // Central spiral (the "unweaving")
  push();
  translate(width / 2, height / 2);
  rotate(PI / 4);
  const maxRadius = min(width, height) * 0.45;
  const segments = 200;
  const thickness = maxRadius * 0.08;

  for (let i = 0; i < segments; i++) {
    const t = i / segments;
    const angle = t * TWO_PI * 3;
    const radius = maxRadius * t * (1 - t * 0.5);
    const x = radius * cos(angle);
    const y = radius * sin(angle);

    // Fading threads
    const alpha = 255 * (1 - t) * (0.3 + 0.7 * sin(t * PI * 2));
    const threadWidth = thickness * (0.2 + 0.8 * noise(i * 0.1));

    stroke(200, 200, 220, alpha);
    strokeWeight(threadWidth);
    noFill();

    // Displacement for fraying effect
    const dx = noise(i * 0.05, t * 10) * 10 - 5;
    const dy = noise(i * 0.05 + 100, t * 10) * 10 - 5;

    if (i > 0) {
      const prevT = (i - 1) / segments;
      const prevAngle = prevT * TWO_PI * 3;
      const prevRadius = maxRadius * prevT * (1 - prevT * 0.5);
      const px = prevRadius * cos(prevAngle) + dx * 0.5;
      const py = prevRadius * sin(prevAngle) + dy * 0.5;
      line(px, py, x + dx, y + dy);
    }

    // Scattered particles (residual "vibrations")
    if (random() > 0.7) {
      const pAlpha = alpha * random(0.1, 0.5);
      const pSize = random(1, 3);
      fill(220, 220, 255, pAlpha);
      noStroke();
      ellipse(x + dx * 2, y + dy * 2, pSize);
    }
  }
  pop();

  // Peripheral "echoes" (faint radial lines)
  push();
  translate(width / 2, height / 2);
  const echoCount = 12;
  for (let i = 0; i < echoCount; i++) {
    const angle = (i / echoCount) * TWO_PI;
    const len = maxRadius * 1.2;
    const x1 = len * 0.3 * cos(angle);
    const y1 = len * 0.3 * sin(angle);
    const x2 = len * cos(angle);
    const y2 = len * sin(angle);

    stroke(100, 100, 150, 30);
    strokeWeight(1);
    line(x1, y1, x2, y2);

    // Noise-based distortion
    for (let j = 0; j < 5; j++) {
      const t = j / 5;
      const nx = lerp(x1, x2, t) + noise(i * 10, j * 10) * 20 - 10;
      const ny = lerp(y1, y2, t) + noise(i * 10 + 100, j * 10) * 20 - 10;
      point(nx, ny);
    }
  }
  pop();

  // Final "void" at the center (subtle gradient)
  push();
  translate(width / 2, height / 2);
  const voidRadius = maxRadius * 0.15;
  for (let r = voidRadius; r > 0; r -= 2) {
    const alpha = map(r, 0, voidRadius, 0, 100);
    fill(0, 0, 0, alpha);
    noStroke();
    ellipse(0, 0, r * 2);
  }
  pop();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  background(15, 15, 25);

  // Base layer: cosmic static
  for (let i = 0; i < 20000; i++) {
    let x = random(width);
    let y = random(height);
    let d = dist(x, y, width/2, height/2);
    let alpha = map(d, 0, 1200, 50, 0);
    stroke(180, 180, 220, alpha);
    point(x, y);
  }

  // Warp threads (vertical)
  for (let i = 0; i < 50; i++) {
    let x = width * 0.2 + i * (width * 0.6 / 50);
    let yStart = height * 0.1;
    let yEnd = height * 0.9;
    let weight = map(i, 0, 50, 3, 0.5);
    let fray = map(i, 0, 50, 0.5, 0.1);

    stroke(100, 100, 150, 200);
    strokeWeight(weight);
    noFill();
    beginShape();
    for (let y = yStart; y <= yEnd; y += 5) {
      let offset = noise(x * 0.01, y * 0.01) * 20 * fray;
      vertex(x + offset, y);
    }
    endShape();
  }

  // Weft threads (horizontal, unraveling)
  for (let i = 0; i < 80; i++) {
    let y = height * 0.2 + i * (height * 0.6 / 80);
    let xStart = width * 0.1;
    let xEnd = width * 0.9;
    let weight = map(i, 0, 80, 2, 0.3);
    let dissolve = map(i, 0, 80, 0.1, 0.8);

    stroke(120, 120, 180, 255 * (1 - dissolve));
    strokeWeight(weight);
    noFill();
    beginShape();
    for (let x = xStart; x <= xEnd; x += 5) {
      let offset = noise(x * 0.01, y * 0.01) * 50 * dissolve;
      if (random() > dissolve) {
        vertex(x + offset, y + random(-2, 2));
      }
    }
    endShape();
  }

  // Frayed edges (dissolving matter)
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = random(height);
    let d = dist(x, y, width/2, height/2);
    let size = map(d, 0, 1000, 15, 2);
    let alpha = map(d, 0, 1200, 200, 0);

    if (random() > 0.7) {
      stroke(150, 150, 200, alpha);
      strokeWeight(random(0.5, 2));
      noFill();
      beginShape();
      for (let j = 0; j < 5; j++) {
        let angle = random(TWO_PI);
        let r = random(size * 0.3, size);
        vertex(x + cos(angle) * r, y + sin(angle) * r);
      }
      endShape(CLOSE);
    }
  }

  // Central void (absence)
  noStroke();
  for (let i = 0; i < 100; i++) {
    let x = width/2 + random(-100, 100);
    let y = height/2 + random(-100, 100);
    let d = dist(x, y, width/2, height/2);
    let size = map(d, 0, 100, 0, 50);
    let alpha = map(d, 0, 100, 0, 100);

    fill(10, 10, 20, alpha);
    ellipse(x, y, size, size);
  }

  // Glowing remnants
  for (let i = 0; i < 50; i++) {
    let x = random(width);
    let y = random(height);
    let d = dist(x, y, width/2, height/2);
    let size = map(d, 0, 1200, 8, 2);
    let alpha = map(d, 0, 1200, 150, 0);

    fill(200, 200, 255, alpha);
    noStroke();
    ellipse(x, y, size, size);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  background(10, 15, 20);

  // Base: un voile de bruit organique (l'étoffe du vivant)
  loadPixels();
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let n = noise(x * 0.002, y * 0.002) * 255;
      let idx = (x + y * width) * 4;
      pixels[idx] = n * 0.3;
      pixels[idx + 1] = n * 0.5;
      pixels[idx + 2] = n * 0.8;
      pixels[idx + 3] = 255;
    }
  }
  updatePixels();

  // Filaments de lumière (l'effilochage)
  strokeWeight(1.5);
  for (let i = 0; i < 300; i++) {
    let x1 = random(width);
    let y1 = random(height);
    let x2 = x1 + random(-100, 100);
    let y2 = y1 + random(-100, 100);
    let alpha = random(30, 120);
    let hue = random(180, 220);
    stroke(hue, 80, 90, alpha);
    line(x1, y1, x2, y2);
  }

  // Noyaux de dissolution (points de rupture)
  noStroke();
  for (let i = 0; i < 15; i++) {
    let cx = random(width * 0.2, width * 0.8);
    let cy = random(height * 0.3, height * 0.9);
    let r = random(50, 150);
    for (let j = 0; j < 100; j++) {
      let angle = random(TWO_PI);
      let dist = random(r * 0.2, r);
      let x = cx + cos(angle) * dist;
      let y = cy + sin(angle) * dist;
      let size = random(0.5, 3);
      let alpha = map(dist, r * 0.2, r, 100, 0);
      fill(200, 100, 50, alpha);
      ellipse(x, y, size);
    }
  }

  // Traces résiduelles (mémoire persistante)
  strokeWeight(0.5);
  for (let i = 0; i < 500; i++) {
    let x = random(width);
    let y = random(height);
    let len = random(5, 30);
    let angle = random(PI * 0.2, PI * 0.8);
    let hue = random(200, 240);
    stroke(hue, 60, 80, random(20, 60));
    line(x, y, x + cos(angle) * len, y + sin(angle) * len);
  }

  // Horizon flou (limite indistincte)
  for (let y = height * 0.6; y < height * 0.8; y++) {
    let alpha = map(y, height * 0.6, height * 0.8, 0, 100);
    stroke(180, 50, 30, alpha);
    strokeWeight(2);
    line(0, y, width, y);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  background(10, 20, 30);

  // Base noise for organic shapes
  let noiseScale = 0.01;

  // Draw decaying trees (skeletal)
  for (let i = 0; i < 5; i++) {
    let x = width * 0.2 + i * width * 0.15;
    let y = height * 0.3 + random(-50, 50);
    drawTree(x, y, 200 + i * 50, 10 + i * 2, 0.7);
  }

  // Glowing roots (new life)
  for (let i = 0; i < 3; i++) {
    let x = width * 0.3 + i * width * 0.2;
    let y = height * 0.7 + random(-30, 30);
    drawRoots(x, y, 80 + i * 30, 5 + i * 1.5);
  }

  // Phosphorescent will-o'-wisps
  for (let i = 0; i < 20; i++) {
    let x = random(width * 0.1, width * 0.9);
    let y = random(height * 0.2, height * 0.8);
    let size = random(5, 15);
    drawWisp(x, y, size);
  }

  // Distant mist (depth)
  drawMist();
}

function drawTree(x, y, h, w, decay) {
  push();
  translate(x, y);
  stroke(100 + random(-20, 20), 80 + random(-10, 10), 60 + random(-5, 5));
  strokeWeight(w);
  noFill();

  // Trunk (decayed)
  beginShape();
  for (let i = 0; i <= h; i += 10) {
    let nx = noise(i * 0.02) * 20 - 10;
    let ny = -i + noise(i * 0.03) * 15;
    vertex(nx, ny);
    if (random() < decay) {
      // Branches (broken)
      push();
      translate(nx, ny);
      rotate(random(-0.3, 0.3));
      line(0, 0, random(20, 50), random(-30, 30));
      pop();
    }
  }
  endShape();

  // Base cracks
  for (let i = 0; i < 3; i++) {
    let angle = random(PI/4, PI*3/4);
    let len = random(30, 60);
    strokeWeight(w * 0.3);
    line(0, 0, cos(angle) * len, sin(angle) * len);
  }
  pop();
}

function drawRoots(x, y, h, w) {
  push();
  translate(x, y);
  stroke(50 + random(30), 100 + random(50), 120 + random(30), 200);
  strokeWeight(w);
  noFill();

  // Main root
  beginShape();
  for (let i = 0; i <= h; i += 5) {
    let nx = noise(i * 0.05) * 15 - 7.5;
    let ny = i + noise(i * 0.04) * 10;
    vertex(nx, ny);
    if (i > h * 0.3 && random() < 0.3) {
      // Side roots
      push();
      translate(nx, ny);
      rotate(random(-0.5, 0.5));
      line(0, 0, random(10, 30), random(10, 30));
      pop();
    }
  }
  endShape();

  // Glow effect
  for (let i = 0; i < 5; i++) {
    let px = random(-10, 10);
    let py = random(h * 0.2, h * 0.8);
    let glowSize = random(5, 15);
    fill(100, 200, 255, 50);
    noStroke();
    ellipse(px, py, glowSize, glowSize * 0.7);
  }
  pop();
}

function drawWisp(x, y, size) {
  push();
  translate(x, y);
  noStroke();

  // Core glow
  fill(150, 200, 255, 150);
  ellipse(0, 0, size * 2, size * 1.5);

  // Flicker
  for (let i = 0; i < 3; i++) {
    let flickerSize = size * random(0.5, 1.2);
    fill(200, 220, 255, 80);
    ellipse(random(-5, 5), random(-3, 3), flickerSize, flickerSize * 0.8);
  }
  pop();
}

function drawMist() {
  noStroke();
  for (let i = 0; i < 100; i++) {
    let x = random(width);
    let y = random(height * 0.6, height);
    let w = random(50, 200);
    let h = random(20, 80);
    fill(30, 40, 50, 30);
    ellipse(x, y, w, h);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  background(20, 30, 50);

  // Sky gradient
  for (let y = 0; y < height * 0.6; y++) {
    let inter = map(y, 0, height * 0.6, 0, 1);
    let c = lerpColor(color(20, 30, 50), color(100, 120, 150), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Distant mountains
  drawMountains(0, height * 0.4, width, height * 0.3, 100, 150, 200, 0.3);
  drawMountains(0, height * 0.5, width, height * 0.2, 80, 100, 120, 0.5);

  // Ground (cracked earth)
  fill(120, 110, 100);
  noStroke();
  beginShape();
  vertex(0, height * 0.6);
  for (let x = 0; x < width; x += 50) {
    let y = height * 0.6 + noise(x * 0.01, 100) * 50 - 20;
    vertex(x, y);
  }
  vertex(width, height * 0.6);
  endShape(CLOSE);

  // Cracks in the ground
  stroke(80, 70, 60);
  strokeWeight(3);
  for (let i = 0; i < 15; i++) {
    let x1 = random(width);
    let y1 = height * 0.6 + random(50);
    let x2 = x1 + random(-100, 100);
    let y2 = y1 + random(50, 150);
    drawCrack(x1, y1, x2, y2, 0.5);
  }

  // Dead tree (main subject)
  drawTree(width * 0.6, height * 0.6, 300, 10, 0.7);

  // Fallen leaves
  for (let i = 0; i < 200; i++) {
    let x = random(width);
    let y = height * 0.6 + random(height * 0.4);
    let size = random(5, 15);
    let rot = random(TWO_PI);
    let col = color(random(150, 200), random(80, 120), random(50, 80), random(100, 200));
    drawLeaf(x, y, size, rot, col);
  }

  // New sprouts at the base
  for (let i = 0; i < 10; i++) {
    let angle = random(TWO_PI);
    let dist = random(100, 200);
    let x = width * 0.6 + cos(angle) * dist;
    let y = height * 0.6 + sin(angle) * dist * 0.3;
    let size = random(20, 40);
    let col = color(random(100, 150), random(180, 220), random(80, 120));
    drawSprout(x, y, size, col);
  }

  // Wind trails (subtle)
  stroke(200, 220, 255, 30);
  strokeWeight(1);
  noFill();
  for (let i = 0; i < 5; i++) {
    let x = random(width);
    let y = random(height * 0.2, height * 0.6);
    beginShape();
    for (let j = 0; j < 10; j++) {
      let nx = x + noise(j * 0.1, i * 10) * 200 - 100;
      let ny = y + j * 20;
      curveVertex(nx, ny);
    }
    endShape();
  }
}

function drawMountains(x, y, w, h, r, g, b, noiseScale) {
  fill(r, g, b);
  noStroke();
  beginShape();
  vertex(x, y + h);
  for (let i = 0; i <= w; i += 20) {
    let nx = noise(i * noiseScale, 0) * h * 0.5;
    vertex(x + i, y + h - nx);
  }
  vertex(x + w, y + h);
  endShape(CLOSE);
}

function drawCrack(x1, y1, x2, y2, roughness) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  let dist = sqrt(dx * dx + dy * dy);
  let steps = floor(dist / 5);

  beginShape();
  vertex(x1, y1);
  for (let i = 1; i < steps; i++) {
    let t = i / steps;
    let x = lerp(x1, x2, t) + random(-roughness, roughness) * 20;
    let y = lerp(y1, y2, t) + random(-roughness, roughness) * 10;
    vertex(x, y);
  }
  vertex(x2, y2);
  endShape();
}

function drawTree(x, y, h, trunkWidth, decay) {
  // Trunk (decayed)
  stroke(80, 70, 60);
  strokeWeight(trunkWidth);
  let trunkH = h * 0.6;
  let trunkSegments = floor(trunkH / 20);
  let prevX = x;
  let prevY = y;

  for (let i = 0; i < trunkSegments; i++) {
    let t = i / trunkSegments;
    let nx = x + noise(i * 0.1, 10) * 50 * decay - 25 * decay;
    let ny = y - i * 20;
    line(prevX, prevY, nx, ny);
    prevX = nx;
    prevY = ny;
  }

  // Branches (broken)
  let branchCount = floor(random(5, 10));
  for (let i = 0; i < branchCount; i++) {
    let angle = random(PI * 0.2, PI * 0.8);
    let branchH = random(h * 0.1, h * 0.3);
    let branchX = prevX + cos(angle) * branchH * 0.3;
    let branchY = prevY - sin(angle) * branchH * 0.7;
    strokeWeight(trunkWidth * 0.5);
    line(prevX, prevY, branchX, branchY);

    // Sub-branches (more decay)
    if (random() > 0.3) {
      let subAngle = angle + random(-0.5, 0.5);
      let subH = branchH * random(0.3, 0.7);
      let subX = branchX + cos(subAngle) * subH;
      let subY = branchY - sin(subAngle) * subH;
      strokeWeight(trunkWidth * 0.2);
      line(branchX, branchY, subX, subY);
    }
  }
}

function drawLeaf(x, y, size, rot, col) {
  push();
  translate(x, y);
  rotate(rot);
  fill(col);
  noStroke();
  beginShape();
  for (let i = 0; i < 5; i++) {
    let angle = TWO_PI * i / 5 + rot;
    let r = size * (i % 2 === 0 ? 1 : 0.5);
    vertex(cos(angle) * r, sin(angle) * r);
  }
  endShape(CLOSE);
  pop();
}

function drawSprout(x, y, size, col) {
  // Stem
  stroke(100, 150, 80);
  strokeWeight(2);
  noFill();
  beginShape();
  for (let i = 0; i < 5; i++) {
    let t = i / 4;
    let nx = x + noise(i * 0.2, 100) * 10 - 5;
    let ny = y - t * size;
    curveVertex(nx, ny);
  }
  endShape();

  // Leaves
  fill(col);
  noStroke();
  for (let i = 0; i < 3; i++) {
    let angle = random(-0.3, 0.3);
    let leafX = x + cos(angle) * size * 0.3;
    let leafY = y - size * 0.5 + sin(angle) * size * 0.2;
    ellipse(leafX, leafY, size * 0.4, size * 0.6);
  }
}

function setup() {
  randomSeed(1);
