  strokeWeight(3);
  for (let i = 0; i < 15; i++) {
    let x1 = random(width);
    let y1 = height * 0.6 + random(height * 0.4);
    let x2 = x1 + random(-200, 200);
    let y2 = y1 + random(-50, 50);
    line(x1, y1, x2, y2);
    for (let j = 0; j < 3; j++) {
      let x3 = x2 + random(-50, 50);
      let y3 = y2 + random(-30, 30);
      line(x2, y2, x3, y3);
    }
  }

  // Dead trees (main focus)
  drawTree(width * 0.3, height * 0.6, 300, 0.7);
  drawTree(width * 0.7, height * 0.6, 250, 0.5);
  drawTree(width * 0.5, height * 0.6, 400, 0.9);

  // Falling leaves (subtle movement)
  for (let i = 0; i < 50; i++) {
    let x = random(width);
    let y = random(height * 0.2, height * 0.6);
    let size = random(3, 8);
    fill(150, 100, 50, 150);
    noStroke();
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    beginShape();
    for (let j = 0; j < 5; j++) {
      let angle = map(j, 0, 5, 0, TWO_PI);
      let r = size * (0.5 + 0.5 * sin(angle * 3));
      vertex(r * cos(angle), r * sin(angle));
    }
    endShape(CLOSE);
    pop();
  }

  // New sprouts at the base of trees
  for (let i = 0; i < 3; i++) {
    let x = width * 0.3 + i * 200;
    let y = height * 0.6 + 100;
    drawSprout(x, y, 20);
  }
}

function drawTree(x, y, h, w) {
  // Trunk
  stroke(80, 60, 40);
  strokeWeight(w * 20);
  line(x, y, x, y - h);

  // Branches
  strokeWeight(w * 10);
  for (let i = 0; i < 5; i++) {
    let branchY = y - h * (0.2 + i * 0.15);
    let branchLen = h * (0.3 - i * 0.05);
    let angle = random(-0.3, 0.3);
    let endX = x + cos(angle) * branchLen;
    let endY = branchY - sin(angle) * branchLen;
    line(x, branchY, endX, endY);

    // Sub-branches
    for (let j = 0; j < 2; j++) {
      let subLen = branchLen * random(0.3, 0.6);
      let subAngle = angle + random(-0.5, 0.5);
      let subEndX = endX + cos(subAngle) * subLen;
      let subEndY = endY - sin(subAngle) * subLen;
      strokeWeight(w * 5);
      line(endX, endY, subEndX, subEndY);
    }
  }
}

function drawSprout(x, y, size) {
  // Stem
  stroke(100, 120, 80);
  strokeWeight(2);
  noFill();
  beginShape();
  vertex(x, y);
  for (let i = 0; i < 5; i++) {
    let nx = x + (i + 1) * 5;
    let ny = y - (i + 1) * 10 + noise(i * 0.5) * 10;
    vertex(nx, ny);
  }
  endShape();

  // Leaves
  noStroke();
  fill(120, 150, 100);
  for (let i = 0; i < 3; i++) {
    let angle = PI / 4 + i * PI / 6;
    let leafX = x + cos(angle) * size * 0.8;
    let leafY = y - sin(angle) * size * 0.8 - size * 0.5;
    ellipse(leafX, leafY, size * 0.6, size * 1.2);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  background(10, 20, 30);

  // Ambient glow (moonlight)
  for (let i = 0; i < 5; i++) {
    let x = random(width);
    let y = random(height * 0.3);
    let d = random(300, 800);
    fill(50, 60, 80, 20);
    noStroke();
    ellipse(x, y, d, d * 0.6);
  }

  // Ground (noise-based terrain)
  noFill();
  stroke(40, 50, 60);
  strokeWeight(2);
  beginShape();
  vertex(0, height * 0.7);
  for (let x = 0; x < width; x += 20) {
    let y = height * 0.7 + noise(x * 0.005, 100) * 100 - 50;
    vertex(x, y);
  }
  vertex(width, height * 0.7);
  endShape();

  // Dead trees (fractal branches)
  for (let i = 0; i < 15; i++) {
    let x = random(width);
    let y = height * 0.7 + random(-50, 50);
    let trunkW = random(5, 15);
    let trunkH = random(100, 300);
    let branches = floor(random(3, 8));

    // Trunk
    stroke(80, 70, 60);
    strokeWeight(trunkW);
    line(x, y, x, y - trunkH);

    // Branches
    strokeWeight(trunkW * 0.5);
    for (let j = 0; j < branches; j++) {
      let angle = random(PI * 0.2, PI * 0.8);
      let len = random(30, 150);
      let branchX = x + cos(angle) * len;
      let branchY = y - trunkH + sin(angle) * len;
      line(x, y - trunkH, branchX, branchY);

      // Sub-branches
      if (random() > 0.5) {
        let subAngle = angle + random(-0.5, 0.5);
        let subLen = len * random(0.3, 0.7);
        let subX = branchX + cos(subAngle) * subLen;
        let subY = branchY + sin(subAngle) * subLen;
        strokeWeight(trunkW * 0.2);
        line(branchX, branchY, subX, subY);
      }
    }
  }

  // New sprouts (symbolic rebirth)
  for (let i = 0; i < 30; i++) {
    let x = random(width);
    let y = height * 0.7 + random(-30, 30);
    let size = random(5, 20);
    let leaves = floor(random(3, 6));

    // Stem
    stroke(100, 120, 80);
    strokeWeight(random(1, 2));
    line(x, y, x, y - size);

    // Leaves
    noStroke();
    fill(150, 180, 100, 200);
    for (let j = 0; j < leaves; j++) {
      let leafX = x + random(-10, 10);
      let leafY = y - size + random(-5, 5);
      ellipse(leafX, leafY, random(3, 8), random(3, 8));
    }
  }

  // Falling leaves (memory fragments)
  for (let i = 0; i < 100; i++) {
    let x = random(width);
    let y = random(height);
    let size = random(2, 6);
    let angle = random(TWO_PI);
    let opacity = random(50, 150);

    push();
    translate(x, y);
    rotate(angle);
    noStroke();
    fill(200, 180, 150, opacity);
    ellipse(0, 0, size, size * 0.5);
    pop();
  }

  // Faint horizon glow
  noStroke();
  for (let i = 0; i < 3; i++) {
    fill(100, 120, 150, 10);
    ellipse(width * 0.5, height * 0.3, width * 1.5, height * 0.2);
  }
}

