function drawClockFace(x, y, d) {
  // Outer ring (cracked metal)
  noFill();
  stroke(120, 100, 80, 200);
  strokeWeight(10);
  ellipse(x, y, d, d);

  // Cracks in the metal
  for (let i = 0; i < 15; i++) {
    let angle = random(PI * 2);
    let len = random(d * 0.3, d * 0.5);
    let x1 = x + cos(angle) * d * 0.4;
    let y1 = y + sin(angle) * d * 0.4;
    let x2 = x + cos(angle) * (d * 0.4 + len);
    let y2 = y + sin(angle) * (d * 0.4 + len);
    stroke(80, 60, 40, 150);
    strokeWeight(random(1, 3));
    line(x1, y1, x2, y2);
  }

  // Inner gears (decaying)
  for (let i = 0; i < 5; i++) {
    let gearSize = d * 0.15 * (i + 1);
    let gearX = x + random(-d * 0.1, d * 0.1);
    let gearY = y + random(-d * 0.1, d * 0.1);
    drawGear(gearX, gearY, gearSize, 10 + i * 2, 20 + i * 5);
  }

  // Stopped clock hands
  stroke(150, 120, 100, 200);
  strokeWeight(8);
  let hourAngle = PI / 3;
  let minuteAngle = PI / 2;
  line(x, y, x + cos(hourAngle) * d * 0.3, y + sin(hourAngle) * d * 0.3);
  strokeWeight(5);
  line(x, y, x + cos(minuteAngle) * d * 0.4, y + sin(minuteAngle) * d * 0.4);

  // Center rivet (rusted)
  fill(80, 60, 40);
  noStroke();
  ellipse(x, y, 20, 20);
}

function drawGear(x, y, d, teeth, rot) {
  push();
  translate(x, y);
  rotate(rot);
  noFill();
  stroke(100, 80, 60, 180);
  strokeWeight(2);
  ellipse(0, 0, d, d);

  // Teeth
  for (let i = 0; i < teeth; i++) {
    let angle = map(i, 0, teeth, 0, PI * 2);
    let x1 = cos(angle) * d * 0.45;
    let y1 = sin(angle) * d * 0.45;
    let x2 = cos(angle) * d * 0.55;
    let y2 = sin(angle) * d * 0.55;
    line(x1, y1, x2, y2);
  }

  // Cracks in gear
  for (let i = 0; i < 3; i++) {
    let angle = random(PI * 2);
    let len = random(d * 0.1, d * 0.3);
    let x1 = cos(angle) * d * 0.2;
    let y1 = sin(angle) * d * 0.2;
    let x2 = cos(angle) * (d * 0.2 + len);
    let y2 = sin(angle) * (d * 0.2 + len);
    stroke(60, 40, 20, 150);
    strokeWeight(random(0.5, 1.5));
    line(x1, y1, x2, y2);
  }
  pop();
}

function drawPetal(x, y, size, rot, hue) {
  push();
  translate(x, y);
  rotate(rot);
  noStroke();
  fill(hue + random(-5, 5), 50 + random(10), 30 + random(20), 150);
  beginShape();
  for (let i = 0; i < 5; i++) {
    let angle = map(i, 0, 5, 0, PI * 2);
    let r = size * (i % 2 === 0 ? 0.8 : 0.4);
    vertex(cos(angle) * r, sin(angle) * r);
  }
  endShape(CLOSE);
  pop();
}

function drawRustTexture() {
  noStroke();
  for (let i = 0; i < 5000; i++) {
    let x = random(width);
    let y = random(height);
    let size = random(0.5, 3);
    let hue = random(10, 30);
    let sat = random(50, 80);
    let bri = random(20, 40);
    fill(hue, sat, bri, 50);
    ellipse(x, y, size, size);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  background(10, 15, 25);

  // Central void (death as absence/light)
  const centerX = width / 2;
  const centerY = height / 2;
  const maxRadius = min(width, height) * 0.6;

  // Radial gradient for the void
  for (let r = maxRadius; r > 0; r -= 2) {
    let alpha = map(r, 0, maxRadius, 200, 0);
    let col = color(220, 220, 255, alpha * 0.3);
    fill(col);
    noStroke();
    circle(centerX, centerY, r * 2);
  }

  // Spiral of unraveling (organic decay)
  push();
  translate(centerX, centerY);
  rotate(PI / 4);
  noFill();
  strokeWeight(1.5);

  for (let i = 0; i < 1000; i++) {
    let angle = map(i, 0, 1000, 0, TWO_PI * 10);
    let radius = map(i, 0, 1000, 0, maxRadius * 0.8);
    let noiseVal = noise(i * 0.01, angle * 0.01) * 20;
    let x = radius * cos(angle) + noiseVal;
    let y = radius * sin(angle) + noiseVal;

    // Color shifts from earthy to ethereal
    let colRatio = map(i, 0, 1000, 0, 1);
    let r = lerp(100, 220, colRatio);
    let g = lerp(80, 220, colRatio);
    let b = lerp(60, 255, colRatio);
    let a = map(radius, 0, maxRadius * 0.8, 150, 0);

    stroke(r, g, b, a);
    point(x, y);
  }
  pop();

  // Fractured fragments (memory/dissolution)
  for (let i = 0; i < 200; i++) {
    let x = random(width);
    let y = random(height);
    let size = random(5, 30);
    let distFromCenter = dist(x, y, centerX, centerY);
    let alpha = map(distFromCenter, 0, maxRadius, 0, 100);

    // Only draw fragments outside the void's core
    if (distFromCenter > maxRadius * 0.3) {
      let col = color(
        random(100, 200),
        random(100, 200),
        random(150, 255),
        alpha
      );
      fill(col);
      noStroke();
      beginShape();
      for (let j = 0; j < 5; j++) {
        let angle = TWO_PI * j / 5 + random(-0.1, 0.1);
        let r = size * (0.5 + random(0.3));
        vertex(x + r * cos(angle), y + r * sin(angle));
      }
      endShape(CLOSE);
    }
  }

  // Subtle noise texture (ambient "dust")
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let x = (i / 4) % width;
    let y = floor(i / 4 / width);
    let distFromCenter = dist(x, y, centerX, centerY);
    let noiseVal = noise(x * 0.01, y * 0.01) * 50;

    if (distFromCenter < maxRadius * 0.9) {
      pixels[i] = pixels[i] + noiseVal * 0.3;
      pixels[i + 1] = pixels[i + 1] + noiseVal * 0.3;
      pixels[i + 2] = pixels[i + 2] + noiseVal * 0.5;
    }
  }
  updatePixels();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  background(10, 15, 25);

  // Central void (core of death)
  const centerX = width / 2;
  const centerY = height / 2;
  const maxRadius = min(width, height) * 0.4;

  // Radial gradient for the void
  for (let r = maxRadius; r > 0; r -= 2) {
    let alpha = map(r, 0, maxRadius, 200, 0);
    let hue = map(r, 0, maxRadius, 220, 280);
    let sat = map(r, 0, maxRadius, 80, 30);
    let bri = map(r, 0, maxRadius, 90, 10);
    noStroke();
    fill(hue, sat, bri, alpha);
    circle(centerX, centerY, r * 2);
  }

  // Frayed threads (dissolving existence)
  const threadCount = 300;
  for (let i = 0; i < threadCount; i++) {
    let angle = random(TWO_PI);
    let distance = random(maxRadius * 0.3, maxRadius * 1.2);
    let x1 = centerX + cos(angle) * distance * 0.8;
    let y1 = centerY + sin(angle) * distance * 0.8;
    let x2 = centerX + cos(angle) * distance;
    let y2 = centerY + sin(angle) * distance;

    // Thread properties
    let thickness = random(0.5, 2);
    let hue = random(10, 50);
    let sat = random(60, 90);
    let bri = random(70, 100);
    let alpha = random(50, 150);
    let noiseScale = 0.02;
    let noiseStrength = random(5, 20);

    // Draw frayed thread
    stroke(hue, sat, bri, alpha);
    strokeWeight(thickness);
    noFill();
    beginShape();
    for (let t = 0; t <= 1; t += 0.05) {
      let nx = lerp(x1, x2, t) + noise(t * 10, i) * noiseStrength;
      let ny = lerp(y1, y2, t) + noise(i, t * 10) * noiseStrength;
      vertex(nx, ny);
    }
    endShape();

    // Frayed ends (dissolving into particles)
    if (random() > 0.7) {
      let particleCount = floor(random(3, 8));
      for (let p = 0; p < particleCount; p++) {
        let px = lerp(x1, x2, random(0.8, 1.2));
        let py = lerp(y1, y2, random(0.8, 1.2));
        let pr = random(0.5, 2);
        fill(hue, sat, bri, alpha * 0.8);
        noStroke();
        circle(px + random(-5, 5), py + random(-5, 5), pr);
      }
    }
  }

  // Spiral (cyclical return)
  const spiralTurns = 5;
  const spiralPoints = 500;
  noFill();
  stroke(200, 50, 80, 100);
  strokeWeight(1.5);
  beginShape();
  for (let i = 0; i < spiralPoints; i++) {
    let t = map(i, 0, spiralPoints, 0, spiralTurns * TWO_PI);
    let r = map(i, 0, spiralPoints, maxRadius * 0.1, maxRadius * 0.9);
    let x = centerX + cos(t) * r;
    let y = centerY + sin(t) * r;
    // Add noise to spiral
    x += noise(i * 0.01, 0) * 20;
    y += noise(0, i * 0.01) * 20;
    vertex(x, y);
  }
  endShape();

  // Subtle glow
  drawingContext.shadowBlur = 30;
  drawingContext.shadowColor = color(220, 80, 90, 100);
  noStroke();
  fill(220, 80, 90, 20);
  circle(centerX, centerY, maxRadius * 1.8);
  drawingContext.shadowBlur = 0;
}

function setup() {
