}

function draw() {
  background(10, 20, 30);

  // Base "void" gradient
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(10, 20, 30), color(50, 60, 80), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Central "unraveling" form
  let centerX = width / 2;
  let centerY = height / 2;
  let maxRadius = min(width, height) * 0.4;

  // Threads of existence
  for (let i = 0; i < 300; i++) {
    let angle = random(TWO_PI);
    let dist = random(maxRadius * 0.1, maxRadius * 0.9);
    let x = centerX + cos(angle) * dist;
    let y = centerY + sin(angle) * dist;

    // Noise-based fraying
    let noiseVal = noise(x * 0.01, y * 0.01, i * 0.1);
    let threadLength = map(noiseVal, 0, 1, 5, 50);
    let threadWeight = map(dist, 0, maxRadius, 3, 0.5);
    let threadColor = lerpColor(
      color(200, 180, 120, 150),
      color(100, 150, 200, 50),
      map(dist, 0, maxRadius, 0, 1)
    );

    stroke(threadColor);
    strokeWeight(threadWeight);
    noFill();

    beginShape();
    for (let j = 0; j < threadLength; j++) {
      let t = j / threadLength;
      let nx = x + cos(angle + noiseVal * 5) * j * 0.5;
      let ny = y + sin(angle + noiseVal * 5) * j * 0.5;
      let nz = noise(nx * 0.02, ny * 0.02, j * 0.05) * 10;
      curveVertex(nx + cos(angle) * nz, ny + sin(angle) * nz);
    }
    endShape();
  }

  // Glowing core (the "mask" slipping away)
  for (let r = maxRadius * 0.1; r > 0; r -= 2) {
    let alpha = map(r, 0, maxRadius * 0.1, 200, 0);
    let glowColor = color(255, 220, 150, alpha);
    fill(glowColor);
    noStroke();
    ellipse(centerX, centerY, r * 2, r * 2);
  }

  // Scattered light particles
  for (let i = 0; i < 200; i++) {
    let x = random(width);
    let y = random(height);
    let size = random(1, 3);
    let distFromCenter = dist(x, y, centerX, centerY);
    let alpha = map(distFromCenter, 0, maxRadius, 200, 0);
    let particleColor = color(200, 230, 255, alpha);

    fill(particleColor);
    noStroke();
    ellipse(x, y, size, size);
  }
}

