  for (let r = maxRadius; r > 0; r -= 2) {
    const n = noise(r * 0.01, frameCount * 0.001);
    const hue = map(r, 0, maxRadius, 20, 220); // Blue to orange
    const sat = map(r, 0, maxRadius, 80, 30);
    const bri = map(r, 0, maxRadius, 90, 20);
    const alpha = map(r, 0, maxRadius, 100, 0);
    fill(hue, sat, bri, alpha);
    noStroke();
    circle(centerX, centerY, r * 2);
  }

  // Frayed threads (dissolving existence)
  strokeWeight(1.5);
  for (let i = 0; i < 300; i++) {
    const angle = random(TWO_PI);
    const dist = random(maxRadius * 0.1, maxRadius * 0.9);
    const x1 = centerX + cos(angle) * dist;
    const y1 = centerY + sin(angle) * dist;
    const x2 = x1 + cos(angle + random(-0.3, 0.3)) * random(50, 200);
    const y2 = y1 + sin(angle + random(-0.3, 0.3)) * random(50, 200);
    const hue = map(dist, 0, maxRadius, 20, 220);
    const sat = map(dist, 0, maxRadius, 80, 30);
    const bri = map(dist, 0, maxRadius, 90, 20);
    stroke(hue, sat, bri, random(50, 150));
    line(x1, y1, x2, y2);
  }

  // Spiral (cyclical return)
  noFill();
  stroke(220, 80, 90, 100);
  strokeWeight(2);
  beginShape();
  for (let a = 0; a < TWO_PI * 5; a += 0.05) {
    const r = map(a, 0, TWO_PI * 5, maxRadius * 0.1, maxRadius * 0.8);
    const x = centerX + cos(a) * r;
    const y = centerY + sin(a) * r;
    vertex(x, y);
  }
  endShape();
}

