        150 + random(30),
        100 + random(50),
        a * 0.8
      );
      fill(c);
      noStroke();
      ellipse(nx, ny, random(50, 150), random(50, 150));
    }
  }

  // Intersection glow
  let midX = (shapes[0].x + shapes[1].x) * 0.5;
  let midY = (shapes[0].y + shapes[1].y) * 0.5;
  for (let i = 0; i < 30; i++) {
    let angle = random(TWO_PI);
    let r = random(100, 300);
    let x = midX + cos(angle) * r;
    let y = midY + sin(angle) * r;
