function drawFigure(dir, baseCol, accentCol) {
  // Torso
  fill(baseCol);
  noStroke();
  beginShape();
  vertex(0, -200);
  bezierVertex(dir * 50, -150, dir * 80, 0, dir * 30, 200);
  bezierVertex(dir * 10, 300, -dir * 20, 350, -dir * 50, 400);
  bezierVertex(-dir * 80, 450, -dir * 100, 500, 0, 500);
  bezierVertex(dir * 100, 500, dir * 80, 450, dir * 50, 400);
  bezierVertex(dir * 20, 350, -dir * 10, 300, -dir * 30, 200);
  bezierVertex(-dir * 80, 0, -dir * 50, -150, 0, -200);
  endShape();

  // Head
  push();
  translate(0, -250);
  fill(lerpColor(baseCol, color(255), 0.2));
  ellipse(0, 0, 120, 150);
  pop();

  // Accent (shoulder/arm)
  fill(accentCol);
  beginShape();
  vertex(dir * 30, -100);
  bezierVertex(dir * 100, -50, dir * 150, 50, dir * 100, 150);
  bezierVertex(dir * 80, 200, dir * 50, 250, dir * 30, 300);
  bezierVertex(dir * 10, 250, -dir * 20, 200, -dir * 30, 150);
  bezierVertex(-dir * 50, 100, -dir * 30, 0, dir * 30, -100);
  endShape();
}

