    fill(red(c), green(c), blue(c), a);
    beginShape();
    for (let angle = 0; angle < TWO_PI; angle += PI / 10) {
      let r = sz * n * (0.7 + 0.3 * sin(angle * 3 + i));
      vertex(r * cos(angle), r * sin(angle));
    }
    endShape(CLOSE);
  }
  pop();
}

