function drawSoftForm(x, y, w, h, c) {
  noStroke();
  let steps = 20;
  for (let i = 0; i < steps; i++) {
    let offset = map(i, 0, steps, 0, 50);
    let alpha = map(i, 0, steps, 0, 150);
    fill(red(c), green(c), blue(c), alpha);
    beginShape();
    for (let angle = 0; angle < TWO_PI; angle += 0.1) {
      let nx = cos(angle) * (w * 0.5 + offset * noise(angle * 2, i * 0.1));
      let ny = sin(angle) * (h * 0.5 + offset * noise(angle * 2, i * 0.1 + 10));
      vertex(x + nx, y + ny);
    }
    endShape(CLOSE);
  }
}

