    beginShape();
    for (let j = 0; j < 6; j++) {
      let a = j * (TWO_PI / 6) + random(-0.2, 0.2);
      let r = s * 0.5 + random(-20, 20);
      let x = r * cos(a);
      let y = r * sin(a) * 1.2;
      vertex(x, y);
    }
    endShape(CLOSE);
  }
  pop();

  // Connecting threads
  for (let i = 0; i < 15; i++) {
    let x1 = centerX - offset + random(-100, 100);
    let y1 = centerY + random(-150, 150);
    let x2 = centerX + offset + random(-100, 100);
    let y2 = centerY + random(-150, 150);
    let w = random(0.5, 2);
    let c = color(255, 220, 200, random(50, 150));
    stroke(c);
    strokeWeight(w);
    noFill();
    bezier(x1, y1,
           x1 + random(-50, 50), y1 + random(-100, 100),
           x2 + random(-50, 50), y2 + random(-100, 100),
           x2, y2);
  }

  // Subtle texture
  for (let i = 0; i < 2000; i++) {
    let x = random(width);
    let y = random(height);
    let d = random(1, 3);
    let c = color(255, random(100, 200), random(150, 255), random(20, 80));
    fill(c);
    noStroke();
    ellipse(x, y, d, d);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  background(15, 20, 30);

  // Base glow
  for (let i = 0; i < 50; i++) {
    let x = random(width);
    let y = random(height);
    let d = random(200, 800);
    let c = color(255, 200, 100, 30);
    fill(c);
    noStroke();
    ellipse(x, y, d, d);
  }

  // Central forms (organic, overlapping)
  push();
  translate(width/2, height/2);
  rotate(PI/6);

  // Left form (cool, dense)
  fill(100, 120, 180, 200);
  noStroke();
  beginShape();
  for (let a = 0; a < TWO_PI; a += 0.1) {
    let r = 300 + 100 * noise(0.5 * cos(a), 0.5 * sin(a));
    vertex(r * cos(a), r * sin(a));
  }
  endShape(CLOSE);

  // Right form (warm, porous)
  fill(220, 150, 80, 180);
  beginShape();
  for (let a = 0; a < TWO_PI; a += 0.1) {
    let r = 250 + 120 * noise(1 + 0.5 * cos(a), 1 + 0.5 * sin(a));
    vertex(400 + r * cos(a), r * sin(a));
  }
  endShape(CLOSE);

  // Overlap glow
  fill(255, 220, 150, 100);
  beginShape();
  for (let a = -PI/3; a < PI/3; a += 0.1) {
    let r1 = 300 + 100 * noise(0.5 * cos(a), 0.5 * sin(a));
    let r2 = 250 + 120 * noise(1 + 0.5 * cos(a), 1 + 0.5 * sin(a));
    let x = lerp(r1 * cos(a), 400 + r2 * cos(a), 0.5);
    let y = lerp(r1 * sin(a), r2 * sin(a), 0.5);
    vertex(x, y);
  }
  endShape(CLOSE);

  pop();

  // Scattered particles (connection threads)
  for (let i = 0; i < 200; i++) {
    let x = random(width);
    let y = random(height);
    let d = random(2, 8);
    let c = color(255, 255, 200, random(100, 255));
    fill(c);
    noStroke();
    ellipse(x, y, d, d);

    // Faint lines to nearest neighbor
    let nearestDist = Infinity;
    let nearestX, nearestY;
    for (let j = 0; j < 200; j++) {
      if (i === j) continue;
      let otherX = random(width);
      let otherY = random(height);
      let dist = p5.Vector.dist(createVector(x, y), createVector(otherX, otherY));
      if (dist < nearestDist && dist < 200) {
        nearestDist = dist;
        nearestX = otherX;
        nearestY = otherY;
      }
    }
    if (nearestDist < 200) {
      stroke(255, 255, 200, 50);
      strokeWeight(0.5);
      line(x, y, nearestX, nearestY);
    }
  }

  // Vignette
  noStroke();
  fill(0, 0, 0, 100);
  beginShape();
  vertex(0, 0);
  vertex(width, 0);
  vertex(width, height);
  vertex(0, height);
  beginContour();
  for (let a = 0; a < TWO_PI; a += 0.1) {
    let r = 0.9 * min(width, height) / 2;
    vertex(width/2 + r * cos(a), height/2 + r * sin(a));
  }
  endContour();
  endShape(CLOSE);
}

