  for (let i = 0; i < 20000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.005, y * 0.005) * 255;
    stroke(n, n * 0.8, n * 0.6, 30);
    point(x, y);
  }

  // Formes principales (silhouettes abstraites)
  noStroke();
  for (let i = 0; i < 2; i++) {
    let x = width * (0.3 + i * 0.4);
    let y = height * 0.4;
    let w = width * 0.25;
    let h = height * 0.6;

    // Corps flous (dégradés)
    for (let j = 0; j < 50; j++) {
      let alpha = map(j, 0, 50, 100, 0);
      let col = i === 0 ?
        color(220, 120 + j * 2, 80 + j * 1.5, alpha) :
        color(80 + j * 1.5, 150 + j * 1, 200 + j * 2, alpha);
      fill(col);
      let offsetX = random(-w * 0.1, w * 0.1);
      let offsetY = random(-h * 0.1, h * 0.1);
      ellipse(x + offsetX, y + offsetY, w * (1 - j * 0.01), h * (1 - j * 0.01));
    }
  }

  // Lueurs entrelacées (courbes organiques)
  strokeWeight(3);
  for (let i = 0; i < 15; i++) {
    let x1 = width * 0.4 + random(-50, 50);
    let y1 = height * 0.3 + random(-50, 50);
    let x2 = width * 0.6 + random(-50, 50);
    let y2 = height * 0.5 + random(-50, 50);
    let c = color(
      255 - i * 10,
      180 + i * 5,
      100 + i * 15,
      150 - i * 8
    );
    stroke(c);
    noFill();
    bezier(
      x1, y1,
      x1 + random(-100, 100), y1 + random(-100, 100),
      x2 + random(-100, 100), y2 + random(-100, 100),
      x2, y2
    );
  }

  // Points lumineux (éclats)
  for (let i = 0; i < 30; i++) {
    let x = random(width * 0.3, width * 0.7);
    let y = random(height * 0.2, height * 0.8);
    let s = random(5, 20);
    let c = color(
      255,
      200 + random(-30, 30),
      150 + random(-50, 50),
      200
    );
    fill(c);
    noStroke();
    ellipse(x, y, s, s);
    // Reflets
    fill(255, 255, 255, 100);
    ellipse(x + s * 0.2, y - s * 0.2, s * 0.4, s * 0.4);
  }

  // Ombre portée (unité)
  fill(20, 30, 40, 150);
  noStroke();
  beginShape();
  vertex(width * 0.2, height * 0.8);
  bezierVertex(
    width * 0.3, height * 0.7,
    width * 0.5, height * 0.75,
    width * 0.7, height * 0.7
  );
  bezierVertex(
    width * 0.8, height * 0.75,
    width * 0.9, height * 0.8,
    width * 0.95, height * 0.9
  );
  vertex(width * 0.95, height);
  vertex(width * 0.2, height);
  endShape(CLOSE);
}

