}

function draw() {
  background(10, 20, 30);

  // Fond texturé (bruit + dégradé)
  for (let y = 0; y < height; y += 5) {
    for (let x = 0; x < width; x += 5) {
      let n = noise(x * 0.005, y * 0.005) * 0.3 + 0.7;
      let col = lerpColor(
        color(30, 40, 50, 150 * n),
        color(10, 20, 30, 200 * n),
        y / height
      );
      fill(col);
      noStroke();
      rect(x, y, 5, 5);
    }
  }

  // Silhouettes floues (formes organiques)
  let centerX = width / 2;
  let centerY = height / 2 + 200;

  // Forme gauche (chaude)
  fill(200, 100, 80, 180);
  beginShape();
  for (let a = 0; a < TWO_PI; a += 0.1) {
    let r = 300 + noise(a * 2, 0) * 150;
    let x = centerX - 400 + cos(a) * r;
    let y = centerY - 100 + sin(a) * r * 1.2;
    vertex(x, y);
  }
  endShape(CLOSE);

  // Forme droite (froide)
  fill(80, 120, 180, 180);
  beginShape();
  for (let a = 0; a < TWO_PI; a += 0.1) {
    let r = 350 + noise(a * 2, 10) * 120;
    let x = centerX + 400 + cos(a) * r;
    let y = centerY - 50 + sin(a) * r * 1.1;
    vertex(x, y);
  }
  endShape(CLOSE);

  // Éclats de lumière (particules dorées)
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = random(height);
    let d = dist(x, y, centerX, centerY);
    if (d < 800) {
      let size = random(2, 8);
      let alpha = map(d, 0, 800, 255, 0);
      fill(255, 220, 150, alpha * 0.8);
      noStroke();
      ellipse(x, y, size, size);

      // Traînées lumineuses
      if (random() > 0.7) {
        stroke(255, 220, 150, alpha * 0.5);
        strokeWeight(random(0.5, 2));
        line(x, y, x + random(-20, 20), y + random(-20, 20));
      }
    }
  }

  // Reflets entre les formes (lignes courbes)
  stroke(255, 200, 120, 100);
  strokeWeight(1.5);
  noFill();
  for (let i = 0; i < 10; i++) {
    let x1 = centerX - 300 + random(-50, 50);
    let y1 = centerY - 200 + random(-50, 50);
    let x2 = centerX + 300 + random(-50, 50);
    let y2 = centerY - 150 + random(-50, 50);
    bezier(
      x1, y1,
      x1 + random(-100, 100), y1 + random(-100, 100),
      x2 + random(-100, 100), y2 + random(-100, 100),
      x2, y2
    );
  }

  // Vague de fond (mouvement suggéré)
  noStroke();
  for (let i = 0; i < 5; i++) {
    fill(20, 40, 60, 30);
    beginShape();
    vertex(0, height - 200 + i * 20);
    for (let x = 0; x < width; x += 50) {
      let y = height - 250 + i * 20 + noise(x * 0.01, i) * 50;
      vertex(x, y);
    }
    vertex(width, height - 200 + i * 20);
    endShape(CLOSE);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  background(10, 20, 30);

  // Fond : bruit organique (comme une membrane vivante)
  for (let x = 0; x < width; x += 10) {
    for (let y = 0; y < height; y += 10) {
      let n = noise(x * 0.005, y * 0.005) * 0.3 + 0.7;
      let col = color(
        30 + n * 50,
        40 + n * 60,
        50 + n * 70,
        150 + n * 100
      );
      fill(col);
      noStroke();
      rect(x, y, 12, 12);
    }
  }

  // Lignes de force (attraction/répulsion)
  strokeWeight(1.5);
  for (let i = 0; i < 200; i++) {
    let x1 = random(width);
    let y1 = random(height);
    let x2 = x1 + random(-300, 300);
    let y2 = y1 + random(-300, 300);

    // Déformation par bruit
    x2 += noise(x1 * 0.01, y1 * 0.01) * 200 - 100;
    y2 += noise(y1 * 0.01, x1 * 0.01) * 200 - 100;

    // Couleur dynamique (chaud/froid)
    let dist = sqrt(pow(x2 - x1, 2) + pow(y2 - y1, 2));
    let hue = map(dist, 0, 400, 0, 30);
    let sat = map(dist, 0, 400, 80, 20);
    let bri = map(dist, 0, 400, 90, 50);
    stroke(hue, sat, bri, 150);

    // Courbure aléatoire
    noFill();
    beginShape();
    vertex(x1, y1);
    quadraticVertex(
      (x1 + x2) / 2 + random(-50, 50),
      (y1 + y2) / 2 + random(-50, 50),
      x2, y2
    );
    endShape();
  }

  // Points lumineux (étoiles/étincelles)
  for (let i = 0; i < 150; i++) {
    let x = random(width);
    let y = random(height);
    let size = random(2, 8);
    let n = noise(x * 0.01, y * 0.01);
    let col = color(
      60 + n * 195,
      80 + n * 175,
      100 + n * 155,
      200 + n * 55
    );
    fill(col);
    noStroke();
    ellipse(x, y, size, size);

    // Halo
    for (let j = 0; j < 3; j++) {
      fill(red(col), green(col), blue(col), (200 + n * 55) / (j + 2));
      ellipse(x, y, size * (j + 2), size * (j + 2));
    }
  }

  // Forme centrale : cœur abstrait (déformé par le bruit)
  noStroke();
  fill(255, 100, 120, 200);
  beginShape();
  for (let a = 0; a < TWO_PI; a += 0.1) {
    let r = 200 + noise(a * 2, frameCount * 0.01) * 100;
    let x = width / 2 + cos(a) * r;
    let y = height / 2 + sin(a) * r * 0.8;
    vertex(x, y);
  }
  endShape(CLOSE);

  // Reflets dans la forme
  for (let i = 0; i < 5; i++) {
    fill(255, 200, 220, 30 + i * 10);
    ellipse(
      width / 2 + random(-50, 50),
      height / 2 + random(-30, 30),
      100 + i * 20,
      80 + i * 15
    );
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  background(10, 15, 30);

  // Palette organique et lumineuse
  const palette = [
    color(255, 100, 120, 200),  // Rose chaud
    color(120, 200, 255, 200),  // Bleu froid
    color(255, 220, 100, 200),  // Jaune doré
    color(150, 255, 180, 200),  // Vert tendre
    color(200, 150, 255, 200)   // Mauve
  ];

  // Fond texturé (bruit de Perlin)
  for (let y = 0; y < height; y += 10) {
    for (let x = 0; x < width; x += 10) {
      const n = noise(x * 0.005, y * 0.005) * 0.3;
      fill(20 + n * 50, 30 + n * 30, 50 + n * 20, 50);
      noStroke();
      rect(x, y, 10, 10);
    }
  }

  // Lignes de force (attraction/répulsion)
  const lines = [];
  for (let i = 0; i < 200; i++) {
    const x1 = random(width);
    const y1 = random(height);
    const x2 = x1 + random(-300, 300);
    const y2 = y1 + random(-300, 300);
    const weight = random(0.5, 3);
    const col = random(palette);
    col.setAlpha(150 + random(100));
    lines.push({ x1, y1, x2, y2, weight, col });
  }

  // Dessiner les lignes avec des variations de transparence
  for (const l of lines) {
    stroke(l.col);
    strokeWeight(l.weight);
    drawingContext.shadowBlur = 10;
    drawingContext.shadowColor = color(red(l.col), green(l.col), blue(l.col), 50);
    line(l.x1, l.y1, l.x2, l.y2);
  }

  // Formes organiques (nœuds d'énergie)
  for (let i = 0; i < 15; i++) {
    const cx = random(width * 0.2, width * 0.8);
    const cy = random(height * 0.3, height * 0.7);
    const size = random(100, 300);
    const col = random(palette);
    col.setAlpha(180);

    // Forme irrégulière (bruit + points)
    beginShape();
    fill(col);
    noStroke();
    for (let angle = 0; angle < TWO_PI; angle += 0.1) {
      const r = size * (0.7 + 0.3 * noise(cx * 0.01, cy * 0.01, angle * 2));
      const x = cx + r * cos(angle);
      const y = cy + r * sin(angle);
      vertex(x, y);
    }
    endShape(CLOSE);

    // Éclats lumineux autour
    for (let j = 0; j < 5; j++) {
      const angle = random(TWO_PI);
      const dist = random(size * 0.5, size * 1.5);
      const x = cx + dist * cos(angle);
      const y = cy + dist * sin(angle);
      const s = random(5, 20);
      fill(red(col), green(col), blue(col), 30);
      ellipse(x, y, s, s);
    }
  }

  // Points de connexion (étincelles)
  for (let i = 0; i < 500; i++) {
    const x = random(width);
    const y = random(height);
    const d = random(1, 5);
    const col = random(palette);
    col.setAlpha(random(50, 200));
    fill(col);
    noStroke();
    ellipse(x, y, d, d);
  }

  // Effet de flou directionnel (pour la profondeur)
  drawingContext.filter = 'blur(0.5px)';
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  background(10, 15, 30);

  // Palette
  const warm = [color(220, 100, 80), color(240, 150, 70), color(200, 80, 100)];
  const cool = [color(80, 120, 180), color(100, 150, 200), color(60, 90, 160)];
  const glow = color(255, 230, 200, 150);

  // Fond : bruit organique
  noStroke();
  for (let y = 0; y < height; y += 20) {
    for (let x = 0; x < width; x += 20) {
      const n = noise(x * 0.005, y * 0.005) * 0.3 + 0.7;
      const c = lerpColor(
        color(20, 30, 50),
        color(50, 60, 80),
        n
      );
      fill(red(c), green(c), blue(c), 100);
      ellipse(x, y, 30 * n, 30 * n);
    }
  }

  // Filaments centraux (cœur de l'amour)
  const centerX = width / 2;
  const centerY = height / 2;
  const filamentCount = 120;
  const maxDist = min(width, height) * 0.4;

  for (let i = 0; i < filamentCount; i++) {
    const angle = TWO_PI * (i / filamentCount);
    const dist = maxDist * (0.3 + 0.7 * pow(random(), 2));
    const x = centerX + cos(angle) * dist;
    const y = centerY + sin(angle) * dist;

    // Couleur aléatoire entre chaud et froid
    const c = random() > 0.5 ? random(warm) : random(cool);
    const alpha = 100 + random(150);
    stroke(red(c), green(c), blue(c), alpha);
    noFill();

    // Tracé du filament (courbe organique)
    beginShape();
    const steps = 10 + floor(random(15));
    for (let j = 0; j <= steps; j++) {
      const t = j / steps;
      const nx = x + cos(angle + PI * 0.2 * sin(t * PI)) * dist * 0.2 * t;
      const ny = y + sin(angle + PI * 0.2 * cos(t * PI)) * dist * 0.2 * t;
      const sw = 1 + 4 * pow(1 - t, 2);
      strokeWeight(sw);
      curveVertex(nx, ny);
    }
    endShape();
  }

  // Noyau lumineux (glow)
  noStroke();
  for (let i = 0; i < 30; i++) {
    const r = 100 + random(200);
    const x = centerX + random(-50, 50);
    const y = centerY + random(-50, 50);
    fill(red(glow), green(glow), blue(glow), 20);
    ellipse(x, y, r, r);
  }

  // Particules en suspension (échos)
  const particleCount = 200;
  for (let i = 0; i < particleCount; i++) {
    const x = random(width);
    const y = random(height);
    const d = dist(x, y, centerX, centerY);
    if (d > maxDist * 1.2) continue; // Évite les bords

    const size = 1 + random(3);
    const c = d < maxDist * 0.5 ? random(warm) : random(cool);
    const alpha = 50 + random(100) * (1 - d / (maxDist * 1.2));
    fill(red(c), green(c), blue(c), alpha);
    noStroke();
    ellipse(x, y, size, size);
  }

  // Formes organiques (tension entre union et séparation)
  const organicCount = 5;
  for (let i = 0; i < organicCount; i++) {
    const x = centerX + random(-maxDist * 0.8, maxDist * 0.8);
    const y = centerY + random(-maxDist * 0.8, maxDist * 0.8);
    const w = 100 + random(200);
    const h = 80 + random(150);
    const c = random() > 0.5 ? random(warm) : random(cool);
    fill(red(c), green(c), blue(c), 150);
    noStroke();

    beginShape();
    const points = 10 + floor(random(10));
    for (let j = 0; j < points; j++) {
      const angle = TWO_PI * (j / points);
      const r = w * 0.5 * (0.7 + 0.3 * noise(i * 10 + j * 0.5));
      const px = x + cos(angle) * r;
      const py = y + sin(angle) * r * (h / w);
      curveVertex(px, py);
    }
    endShape(CLOSE);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  background(10, 15, 30);

  // Fond : bruit organique (comme une membrane)
  for (let x = 0; x < width; x += 10) {
    for (let y = 0; y < height; y += 10) {
      let n = noise(x * 0.005, y * 0.005) * 0.3 + 0.7;
      let col = color(20 + n * 10, 30 + n * 20, 50 + n * 30, 150);
      fill(col);
      noStroke();
      rect(x, y, 12, 12);
    }
  }

  // Filaments lumineux (lignes de désir)
  strokeCap(ROUND);
  for (let i = 0; i < 120; i++) {
    let x1 = random(width * 0.2, width * 0.8);
    let y1 = random(height * 0.1, height * 0.9);
    let x2 = x1 + random(-200, 200);
    let y2 = y1 + random(-200, 200);
    let weight = random(0.5, 3);
    let hue = random(30, 60);
    let sat = random(80, 100);
    let bri = random(70, 90);

    for (let j = 0; j < 5; j++) {
      let offset = random(-10, 10);
      stroke(hue, sat - j * 5, bri - j * 10, 150 - j * 30);
      strokeWeight(weight - j * 0.2);
      line(x1 + offset, y1 + offset, x2 + offset, y2 + offset);
    }
  }

  // Ombres portées (vide entre les corps)
  noStroke();
  for (let i = 0; i < 8; i++) {
    let x = random(width * 0.3, width * 0.7);
    let y = random(height * 0.2, height * 0.8);
    let w = random(100, 300);
    let h = random(200, 500);
    let col = color(0, 0, 0, 100);

    for (let j = 0; j < 20; j++) {
      fill(red(col), green(col), blue(col), alpha(col) * (0.9 - j * 0.04));
      ellipse(x + random(-5, 5), y + random(-5, 5), w - j * 5, h - j * 10);
    }
  }

  // Points de lumière (étincelles)
  for (let i = 0; i < 200; i++) {
    let x = random(width);
    let y = random(height);
    let d = random(1, 4);
    let bri = random(70, 100);
    fill(50, 100, bri, 200);
    noStroke();
    ellipse(x, y, d, d);
  }

  // Courbes organiques (mouvements)
  noFill();
  for (let i = 0; i < 5; i++) {
    let x = random(width * 0.1, width * 0.9);
    let y = random(height * 0.1, height * 0.9);
    let hue = random(0, 30);
    let sat = random(70, 90);
    let bri = random(60, 80);

    beginShape();
    for (let t = 0; t < 100; t++) {
      let nx = x + noise(t * 0.05, i) * 400 - 200;
      let ny = y + t * 10 + noise(t * 0.05, i + 10) * 200 - 100;
      stroke(hue, sat, bri, 100);
      strokeWeight(1);
      curveVertex(nx, ny);
    }
    endShape();
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  background(10, 20, 30);

  // Fond : bruit organique (comme une membrane vivante)
  for (let x = 0; x < width; x += 10) {
    for (let y = 0; y < height; y += 10) {
      let n = noise(x * 0.005, y * 0.005) * 0.3;
      let col = color(20 + n * 100, 30 + n * 80, 40 + n * 120, 50);
      fill(col);
      noStroke();
      rect(x, y, 12, 12);
    }
  }

  // Deux "cœurs" abstraits (formes organiques)
  let center1 = createVector(width * 0.4, height * 0.4);
  let center2 = createVector(width * 0.6, height * 0.6);
  let radius = 300;

  // Filaments entre les deux (lignes courbes)
  for (let i = 0; i < 150; i++) {
    let t = i / 150;
    let x1 = center1.x + cos(t * TWO_PI * 3 + frameCount * 0.01) * radius * 0.8;
    let y1 = center1.y + sin(t * TWO_PI * 2 + frameCount * 0.01) * radius * 0.6;
    let x2 = center2.x + cos(t * TWO_PI * 2 + PI + frameCount * 0.01) * radius * 0.7;
    let y2 = center2.y + sin(t * TWO_PI * 3 + PI + frameCount * 0.01) * radius * 0.5;

    let hue = 360 * t;
    let sat = 80 + sin(t * PI) * 20;
    let bri = 90 + cos(t * PI) * 10;
    stroke(color(hue, sat, bri, 150));
    strokeWeight(1 + sin(t * PI * 2) * 2);
    noFill();
    bezier(x1, y1,
           x1 + (x2 - x1) * 0.3 + random(-50, 50), y1 + (y2 - y1) * 0.3 + random(-50, 50),
           x2 + (x1 - x2) * 0.3 + random(-50, 50), y2 + (y1 - y2) * 0.3 + random(-50, 50),
           x2, y2);
  }

  // Particules lumineuses (échos)
  for (let i = 0; i < 200; i++) {
    let x = random(width);
    let y = random(height);
    let d1 = dist(x, y, center1.x, center1.y);
    let d2 = dist(x, y, center2.x, center2.y);
    let d = min(d1, d2);

    if (d < radius * 1.2) {
      let alpha = map(d, 0, radius * 1.2, 200, 0);
      let size = map(d, 0, radius * 1.2, 3, 0.5);
      let hue = 360 * noise(x * 0.01, y * 0.01);
      fill(color(hue, 70, 90, alpha));
      noStroke();
      ellipse(x, y, size, size);
    }
  }

  // Formes principales (cœurs déformés)
  drawOrganicShape(center1, radius, color(350, 80, 90, 100));
  drawOrganicShape(center2, radius, color(210, 80, 90, 100));

  // Reflets dans l'espace
  for (let i = 0; i < 50; i++) {
    let x = random(width);
    let y = random(height * 0.8);
    let d = dist(x, y, center1.x, center1.y) + dist(x, y, center2.x, center2.y);
    if (d < width * 0.6) {
      let alpha = map(d, 0, width * 0.6, 30, 0);
      let size = random(2, 5);
      fill(color(0, 0, 100, alpha));
      noStroke();
      ellipse(x, y, size, size);
    }
  }
}

function drawOrganicShape(center, radius, col) {
  push();
  translate(center.x, center.y);
  fill(col);
  noStroke();
  beginShape();
  for (let a = 0; a < TWO_PI; a += 0.1) {
    let r = radius * (0.7 + 0.3 * noise(cos(a) * 2, sin(a) * 2, frameCount * 0.001));
    let x = r * cos(a);
    let y = r * sin(a) * 1.2;
    vertex(x, y);
  }
  endShape(CLOSE);
  pop();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  background(10, 20, 30);

  // 根系部分（底部）
  push();
  translate(0, height * 0.6);
  for (let i = 0; i < 120; i++) {
    let x = random(width);
    let y = random(height * 0.4);
    let len = random(50, 200);
    let weight = random(0.5, 3);
    let angle = random(PI * 0.2, PI * 0.8);
    let branchProb = random(0.3, 0.7);

    drawRoot(x, y, len, weight, angle, branchProb, 0);
  }
  pop();

  // 光晕部分（顶部）
  push();
  translate(0, -height * 0.2);
  for (let i = 0; i < 80; i++) {
    let x = random(width);
    let y = random(height * 0.5);
    let size = random(30, 120);
    let hue = random(10, 40);
    let sat = random(60, 90);
    let bri = random(70, 95);

    drawGlow(x, y, size, hue, sat, bri);
  }
  pop();

  // 中间过渡区（模糊交汇）
  push();
  for (let i = 0; i < 50; i++) {
    let x = random(width);
    let y = random(height * 0.4, height * 0.6);
    let size = random(20, 80);
    let hue = random(20, 50);
    let alpha = random(30, 80);

    fill(hue, 60, 90, alpha);
    noStroke();
    ellipse(x, y, size, size * random(0.5, 1.5));
  }
  pop();
}

function drawRoot(x, y, len, weight, angle, branchProb, depth) {
  if (depth > 5 || len < 2) return;

  let sw = weight * (1 - depth * 0.15);
  stroke(20 + depth * 5, 30 + depth * 10, 20 + depth * 5, 200);
  strokeWeight(sw);
  noFill();

  let endX = x + cos(angle) * len;
  let endY = y + sin(angle) * len;

  // 绘制主干
  beginShape();
  for (let i = 0; i <= 1; i += 0.1) {
    let nx = lerp(x, endX, i);
    let ny = lerp(y, endY, i);
    let noiseVal = noise(nx * 0.01, ny * 0.01, depth * 10) * 10;
    vertex(nx + cos(angle + PI/2) * noiseVal, ny + sin(angle + PI/2) * noiseVal);
  }
  endShape();

  // 分支
  if (random() < branchProb) {
    let branchAngle = angle + random(-PI/4, PI/4);
    let branchLen = len * random(0.3, 0.7);
    drawRoot(endX, endY, branchLen, weight * 0.8, branchAngle, branchProb * 0.9, depth + 1);
  }

  // 递归绘制主干延伸
  drawRoot(endX, endY, len * random(0.6, 0.9), weight, angle + random(-0.1, 0.1), branchProb, depth + 1);
}

function drawGlow(x, y, size, hue, sat, bri) {
  noStroke();
  for (let i = 0; i < 10; i++) {
    let r = size * (1 - i * 0.1);
    let a = 100 * (1 - i * 0.2);
    fill(hue, sat, bri, a);
    ellipse(x, y, r, r * random(0.7, 1.3));
  }

  // 细小光点
  for (let i = 0; i < 5; i++) {
    let px = x + random(-size * 0.5, size * 0.5);
    let py = y + random(-size * 0.3, size * 0.3);
    let s = random(2, 8);
    fill(hue, sat, bri, random(150, 255));
    ellipse(px, py, s, s);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  background(10, 20, 40);

  // Base glow (subtle ambient light)
  for (let i = 0; i < 5; i++) {
    let x = width * 0.5 + random(-200, 200);
    let y = height * 0.6 + random(-100, 100);
    drawGlow(x, y, 400, color(255, 200, 150, 30));
  }

  // Tree trunks (left and right)
  drawTree(width * 0.35, height * 0.8, 1.2, 0);
  drawTree(width * 0.65, height * 0.8, 0.9, PI);

  // Roots (intertwined underground)
  drawRoots(width * 0.35, height * 0.8, 1.2, 0);
  drawRoots(width * 0.65, height * 0.8, 0.9, PI);

  // Light rays through branches
  drawLightRays();
}

function drawTree(x, y, scale, angleOffset) {
  push();
  translate(x, y);
  scale(scale);
  rotate(angleOffset);

  // Trunk (with cracks and texture)
  stroke(80, 60, 40);
  strokeWeight(30);
  noFill();
  beginShape();
  vertex(0, 0);
  bezierVertex(-20, -50, -40, -150, -30, -300);
  bezierVertex(-20, -350, 20, -380, 0, -400);
  bezierVertex(20, -380, 40, -350, 30, -300);
  bezierVertex(40, -150, 20, -50, 0, 0);
  endShape();

  // Cracks in trunk
  stroke(50, 30, 20);
  strokeWeight(8);
  for (let i = 0; i < 5; i++) {
    let y1 = -100 - i * 60;
    let y2 = y1 - random(30, 80);
    let x1 = random(-20, 20);
    let x2 = x1 + random(-30, 30);
    line(x1, y1, x2, y2);
  }

  // Branches (recursive)
  stroke(80, 60, 40);
  strokeWeight(15);
  drawBranch(0, -400, 120, -PI/2, 5);

  pop();
}

function drawBranch(x, y, len, angle, depth) {
  if (depth <= 0) return;

  push();
  translate(x, y);
  rotate(angle);

  // Branch line
  line(0, 0, 0, -len);

  // Sub-branches
  if (depth > 1) {
    let branchCount = floor(random(2, 4));
    for (let i = 0; i < branchCount; i++) {
      let newLen = len * random(0.5, 0.8);
      let newAngle = random(-PI/4, PI/4);
      drawBranch(0, -len, newLen, newAngle, depth - 1);
    }
  }

  // Leaves (small clusters)
  if (depth <= 2) {
    let leafCount = floor(random(3, 8));
    for (let i = 0; i < leafCount; i++) {
      let leafX = random(-10, 10);
      let leafY = -len + random(-20, 20);
      drawLeaf(leafX, leafY, random(0.5, 1.5));
    }
  }

  pop();
}

function drawLeaf(x, y, size) {
  push();
  translate(x, y);
  scale(size);

  noStroke();
  fill(100 + random(20), 120 + random(30), 80 + random(20), 180);
  beginShape();
  vertex(0, 0);
  bezierVertex(5, -10, 15, -15, 20, 0);
  bezierVertex(15, 10, 5, 15, 0, 0);
  endShape(CLOSE);

  // Veins
  stroke(60, 80, 40, 150);
  strokeWeight(0.5);
  line(0, 0, 10, -5);
  line(0, 0, 10, 5);

  pop();
}

function drawRoots(x, y, scale, angleOffset) {
  push();
  translate(x, y);
  scale(scale);
  rotate(angleOffset);

  // Main roots (intertwined)
  stroke(60, 40, 30);
  strokeWeight(20);
  noFill();

  // Left root (curves toward right tree)
  beginShape();
  vertex(0, 0);
  bezierVertex(-50, 50, -100, 150, -150, 200);
  bezierVertex(-120, 250, 50, 300, 100, 250);
  endShape();

  // Right root (curves toward left tree)
  beginShape();
  vertex(0, 0);
  bezierVertex(50, 50, 100, 150, 150, 200);
  bezierVertex(120, 250, -50, 300, -100, 250);
  endShape();

  // Smaller roots
  for (let i = 0; i < 8; i++) {
    let rootX = random(-100, 100);
    let rootY = random(50, 200);
    let rootLen = random(50, 150);
    let rootAngle = random(-PI/4, PI/4);

    strokeWeight(random(5, 12));
    push();
    translate(rootX, rootY);
    rotate(rootAngle);
    line(0, 0, 0, rootLen);
    pop();
  }

  pop();
}

function drawGlow(x, y, radius, col) {
  noStroke();
  for (let r = radius; r > 0; r -= 10) {
    let alpha = map(r, 0, radius, 0, col.levels[3]);
    fill(red(col), green(col), blue(col), alpha);
    ellipse(x, y, r * 2);
  }
}

function drawLightRays() {
  noStroke();
  for (let i = 0; i < 20; i++) {
    let x = random(width);
    let y = random(height * 0.2, height * 0.6);
    let w = random(20, 80);
    let h = random(100, 300);
    let col = color(255, 220, 180, random(30, 80));

    fill(col);
    beginShape();
    vertex(x - w/2, y);
    vertex(x + w/2, y);
    vertex(x + w/4, y + h);
    vertex(x - w/4, y + h);
    endShape(CLOSE);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  background(10, 20, 40);

  // Light source (warm glow)
  for (let i = 0; i < 50; i++) {
