  drawTree(width * 0.65, height * 0.6, 1.0, 1.0, color(120, 80, 60), color(150, 180, 120, 150));

  // Roots (intertwined)
  drawRoots(width * 0.35, height * 0.6, width * 0.65, height * 0.6, color(80, 60, 40, 200));

