function drawTree(x, y, scaleX, scaleY, trunkCol, leafCol) {
  push();
  translate(x, y);
  scale(scaleX, scaleY);

  // Trunk
  strokeWeight(10);
  stroke(trunkCol);
  noFill();
  beginShape();
  vertex(0, 0);
  bezierVertex(-20, -50, -30, -150, 0, -200);
  bezierVertex(30, -150, 20, -50, 0, 0);
  endShape();

  // Branches
  strokeWeight(5);
  for (let i = 0; i < 5; i++) {
    let angle = random(PI/4, PI*3/4);
    let len = random(80, 150);
    let branchX = cos(angle) * len;
    let branchY = -sin(angle) * len;
    line(0, -200, branchX, branchY - 200);

    // Sub-branches
    for (let j = 0; j < 3; j++) {
      let subAngle = angle + random(-PI/4, PI/4);
      let subLen = random(30, 80);
      let subX = branchX + cos(subAngle) * subLen;
      let subY = branchY + -sin(subAngle) * subLen;
      line(branchX, branchY - 200, subX, subY - 200);
    }
  }

  // Leaves (organic clusters)
  noStroke();
  fill(leafCol);
  for (let i = 0; i < 20; i++) {
    let leafX = random(-50, 50);
    let leafY = random(-250, -100);
    let leafSize = random(20, 50);
    beginShape();
    for (let j = 0; j < 5; j++) {
      let angle = TWO_PI * j / 5;
      let r = leafSize * (0.7 + 0.3 * noise(leafX * 0.01, leafY * 0.01, j));
      vertex(leafX + cos(angle) * r, leafY + sin(angle) * r);
    }
    endShape(CLOSE);
  }

  pop();
}

function drawRoots(x1, y1, x2, y2, rootCol) {
  stroke(rootCol);
  strokeWeight(8);
  noFill();

  // Main roots
  beginShape();
  vertex(x1, y1);
  bezierVertex(x1 - 100, y1 + 100, x1 - 50, y1 + 200, x1 + 50, y1 + 300);
  bezierVertex(x1 + 150, y1 + 400, x2 - 150, y2 + 400, x2 - 50, y2 + 300);
  bezierVertex(x2 + 50, y2 + 200, x2 + 100, y2 + 100, x2, y2);
  endShape();

  // Side roots
  for (let i = 0; i < 4; i++) {
    let rootX = lerp(x1, x2, i / 3);
    let rootY = y1 + 300 + random(-20, 20);
    let rootLen = random(100, 200);
    let rootAngle = random(-PI/6, PI/6);
    let endX = rootX + cos(rootAngle) * rootLen;
    let endY = rootY + sin(rootAngle) * rootLen;
    strokeWeight(random(3, 6));
    line(rootX, rootY, endX, endY);
  }
}

