function drawRoot(x, y, len, weight, angle, col) {
  push();
  translate(x, y);
  rotate(angle);
  stroke(col);
  strokeWeight(weight);
  noFill();

  let segments = floor(random(3, 8));
  let segmentLen = len / segments;
  let noiseScale = 0.02;
  let noiseOffset = random(1000);

  beginShape();
  for (let i = 0; i <= segments; i++) {
    let t = i / segments;
    let nx = noise(noiseOffset + t * 10, noiseOffset) * 2 - 1;
    let ny = noise(noiseOffset, noiseOffset + t * 10) * 2 - 1;
    let xOff = nx * 30 * (1 - t);
    let yOff = ny * 20 * (1 - t) + t * 10;
    curveVertex(
      t * segmentLen * cos(angle) + xOff,
      t * segmentLen * sin(angle) + yOff
    );
  }
  endShape();
  pop();
}

function drawGlow(x, y, r, col) {
  noStroke();
  for (let i = r; i > 0; i -= 5) {
    let alpha = map(i, 0, r, 0, alpha(col));
    fill(red(col), green(col), blue(col), alpha);
    circle(x, y, i);
  }
}

