}

function draw() {
  background(10, 20, 30);

  // Cosmic background
  for (let i = 0; i < 2000; i++) {
    let x = random(width);
    let y = random(height);
    let d = dist(x, y, width/2, height/2);
    let alpha = map(d, 0, height/1.5, 255, 0);
    let size = map(d, 0, height/1.5, 0.5, 2);
    fill(255, 255, 255, alpha * 0.3);
    noStroke();
    circle(x, y, size);
  }

  // Central light fractal
  push();
  translate(width/2, height/2);
  for (let i = 0; i < 12; i++) {
    let angle = TWO_PI * i / 12;
    let len = 400 * pow(0.7, i);
    let sw = map(i, 0, 12, 10, 1);
    stroke(255, 200, 100, 200);
    strokeWeight(sw);
    line(0, 0, cos(angle) * len, sin(angle) * len);

    // Recursive branches
    push();
    translate(cos(angle) * len, sin(angle) * len);
    rotate(angle + PI/6 + random(-0.1, 0.1));
    for (let j = 0; j < 3; j++) {
      let subLen = len * 0.6;
      stroke(255, 150, 50, 150);
      strokeWeight(sw * 0.7);
      line(0, 0, cos(j * PI/3) * subLen, sin(j * PI/3) * subLen);
    }
    pop();
  }
  pop();

  // Organic roots
  for (let i = 0; i < 8; i++) {
    let x = width * (0.2 + i * 0.1);
    let y = height * 0.8;
    let angle = -PI/2 + random(-0.3, 0.3);
    let len = 300 + random(100);
    let sw = 8 + random(4);
    stroke(100, 80, 50, 200);
    strokeWeight(sw);
    noFill();
    beginShape();
    vertex(x, y);
    for (let j = 0; j < 100; j++) {
      let t = j / 100;
      let nx = x + cos(angle) * len * t;
      let ny = y + sin(angle) * len * t + noise(x * 0.01, y * 0.01, t * 10) * 50;
      vertex(nx, ny);
      angle += noise(x * 0.01, y * 0.01, t * 10) * 0.1 - 0.05;
    }
    endShape();
  }

  // Floating orbs (love's echoes)
  for (let i = 0; i < 50; i++) {
    let x = random(width);
    let y = random(height * 0.1, height * 0.7);
    let d = dist(x, y, width/2, height/2);
    let size = map(d, 0, height/2, 30, 5);
    let hue = map(d, 0, height/2, 20, 50);
    fill(hue, 80, 90, 150);
    noStroke();
    circle(x, y, size);

    // Glow effect
    for (let j = 0; j < 3; j++) {
      fill(hue, 80, 90, 20 * (3 - j));
      circle(x, y, size * (1 + j * 0.5));
    }
  }

  // Subtle connection lines
  stroke(255, 255, 255, 30);
  strokeWeight(0.5);
  for (let i = 0; i < 20; i++) {
    let x1 = random(width);
    let y1 = random(height);
    let x2 = random(width);
    let y2 = random(height);
    if (dist(x1, y1, x2, y2) < 300) {
      line(x1, y1, x2, y2);
    }
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  background(10, 15, 30);

  // Base noise for organic texture
  let noiseScale = 0.01;
  let noiseStrength = 50;

  // Draw background "veins" of love
  stroke(255, 200, 150, 30);
  strokeWeight(1);
  noFill();
  for (let i = 0; i < 200; i++) {
    let x1 = random(width);
    let y1 = random(height);
    let x2 = x1 + random(-200, 200);
    let y2 = y1 + random(-200, 200);
    let steps = floor(random(5, 15));
    beginShape();
    for (let j = 0; j <= steps; j++) {
      let t = j / steps;
      let nx = lerp(x1, x2, t) + noise(t * 10) * 100 - 50;
      let ny = lerp(y1, y2, t) + noise(t * 10 + 5) * 100 - 50;
      vertex(nx, ny);
    }
    endShape();
  }

  // Main "nodes" of love (abstract shapes)
  let nodes = [];
  for (let i = 0; i < 8; i++) {
    let x = random(width * 0.2, width * 0.8);
    let y = random(height * 0.2, height * 0.8);
    let size = random(100, 300);
    let hue = random(360);
    nodes.push({ x, y, size, hue });
  }

  // Draw connections between nodes
  strokeWeight(2);
  for (let i = 0; i < nodes.length; i++) {
    for (let j = i + 1; j < nodes.length; j++) {
      let d = dist(nodes[i].x, nodes[i].y, nodes[j].x, nodes[j].y);
      if (d < 600) {
        let alpha = map(d, 0, 600, 100, 10);
        let connectionHue = (nodes[i].hue + nodes[j].hue) / 2;
        stroke(connectionHue, 80, 90, alpha);
        line(nodes[i].x, nodes[i].y, nodes[j].x, nodes[j].y);
      }
    }
  }

  // Draw the nodes themselves
  noStroke();
  for (let node of nodes) {
    let detail = floor(random(3, 8));
    let points = [];
    for (let i = 0; i < detail; i++) {
      let angle = TWO_PI * i / detail;
      let r = node.size * 0.5 * (0.8 + 0.4 * noise(i * 0.5, node.x * 0.01, node.y * 0.01));
      let px = node.x + r * cos(angle);
      let py = node.y + r * sin(angle);
      points.push({ x: px, y: py });
    }

    // Fill with gradient
    for (let i = 0; i < 10; i++) {
      let t = i / 9;
      let c = color(node.hue, 70 + t * 20, 80 + t * 15, 20 + t * 30);
      fill(c);
      beginShape();
      for (let p of points) {
        let nx = p.x + (noise(p.x * noiseScale, p.y * noiseScale) - 0.5) * noiseStrength;
        let ny = p.y + (noise(p.x * noiseScale, p.y * noiseScale + 5) - 0.5) * noiseStrength;
        vertex(nx, ny);
      }
      endShape(CLOSE);
    }

    // Inner glow
    fill(node.hue, 60, 95, 40);
    beginShape();
    for (let p of points) {
      let nx = p.x + (noise(p.x * noiseScale * 2, p.y * noiseScale * 2) - 0.5) * noiseStrength * 0.5;
      let ny = p.y + (noise(p.x * noiseScale * 2, p.y * noiseScale * 2 + 5) - 0.5) * noiseStrength * 0.5;
      vertex(nx, ny);
    }
    endShape(CLOSE);
  }

  // Subtle "pulse" effects
  for (let i = 0; i < 50; i++) {
    let x = random(width);
    let y = random(height);
    let d = random(50, 200);
    let hue = random(360);
    let alpha = random(5, 20);
    noStroke();
    fill(hue, 60, 90, alpha);
    ellipse(x, y, d, d);
  }
}

