function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  background(10, 15, 30);

  // Central glow (core of love)
  let centerX = width / 2;
  let centerY = height / 2;
  let maxRadius = min(width, height) * 0.4;

  // Radial gradient for the glow
  for (let r = maxRadius; r > 0; r -= 2) {
    let alpha = map(r, 0, maxRadius, 100, 0);
    let col = color(255, 200, 150, alpha);
    fill(col);
    noStroke();
    circle(centerX, centerY, r * 2);
  }

  // Fractal-like tendrils (love's reach)
  stroke(255, 200, 150, 150);
  noFill();
  let branches = 12;
  let angleOffset = TWO_PI / branches;

  for (let i = 0; i < branches; i++) {
    let angle = angleOffset * i + random(-0.1, 0.1);
    let x1 = centerX + cos(angle) * maxRadius * 0.3;
    let y1 = centerY + sin(angle) * maxRadius * 0.3;
    let x2 = centerX + cos(angle) * maxRadius * 1.2;
    let y2 = centerY + sin(angle) * maxRadius * 1.2;

    // Main branch
    strokeWeight(3);
    drawBranch(x1, y1, x2, y2, 0.6, 5);

    // Secondary branches (love's echoes)
    if (random() > 0.3) {
      let x3 = x2 + cos(angle + random(-0.5, 0.5)) * maxRadius * 0.5;
      let y3 = y2 + sin(angle + random(-0.5, 0.5)) * maxRadius * 0.5;
      strokeWeight(2);
      drawBranch(x2, y2, x3, y3, 0.4, 3);
    }
  }

  // Floating particles (love's fragments)
  noStroke();
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = random(height);
    let d = dist(x, y, centerX, centerY);
    let size = map(d, 0, maxRadius, 0.5, 3);
    let alpha = map(d, 0, maxRadius, 200, 0);
    let col = color(255, 220, 180, alpha);
    fill(col);
    circle(x, y, size);
  }

  // Subtle noise texture (love's imperfection)
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let x = (i / 4) % width;
    let y = floor(i / 4 / width);
    let d = dist(x, y, centerX, centerY);
    if (d < maxRadius * 1.5) {
      let n = noise(x * 0.01, y * 0.01) * 50;
      pixels[i] = constrain(pixels[i] + n, 0, 255);
      pixels[i + 1] = constrain(pixels[i + 1] + n, 0, 255);
      pixels[i + 2] = constrain(pixels[i + 2] + n, 0, 255);
    }
  }
  updatePixels();
}

function drawBranch(x1, y1, x2, y2, splitChance, depth) {
  line(x1, y1, x2, y2);
  if (depth <= 0) return;

  let angle = atan2(y2 - y1, x2 - x1);
  let len = dist(x1, y1, x2, y2) * 0.7;

  // Left split
  if (random() < splitChance) {
    let newX = x2 + cos(angle - random(0.3, 0.8)) * len;
    let newY = y2 + sin(angle - random(0.3, 0.8)) * len;
    drawBranch(x2, y2, newX, newY, splitChance * 0.8, depth - 1);
  }

  // Right split
  if (random() < splitChance) {
    let newX = x2 + cos(angle + random(0.3, 0.8)) * len;
    let newY = y2 + sin(angle + random(0.3, 0.8)) * len;
    drawBranch(x2, y2, newX, newY, splitChance * 0.8, depth - 1);
  }
}

