function drawFractal(x, y, len, angleFactor, depth) {
  if (depth <= 0) return;
  let angle = noise(x * 0.01, y * 0.01) * PI * 2;
  let x2 = x + cos(angle) * len;
  let y2 = y + sin(angle) * len;
  strokeWeight(map(depth, 1, 5, 0.5, 2));
  line(x, y, x2, y2);
  drawFractal(x2, y2, len * angleFactor, angleFactor, depth - 1);
}

function drawBlob(x, y, size, points) {
  beginShape();
  for (let i = 0; i < points; i++) {
    let angle = map(i, 0, points, 0, TWO_PI);
    let r = size * 0.5 + noise(x * 0.01, y * 0.01, angle) * size * 0.3;
    let px = x + cos(angle) * r;
    let py = y + sin(angle) * r;
    vertex(px, py);
  }
  endShape(CLOSE);
}

function drawVoid(x, y, size) {
  let sides = floor(random(3, 8));
  beginShape();
  for (let i = 0; i < sides; i++) {
