/* ---------- helpers ---------- */
function drawGradient() {
  colorMode(RGB);
  let topCol = color(250, 200, 150);
  let botCol = color(20, 0, 40);
  for (let y = 0; y < height; y++) {
    let inter = pow(map(y, 0, height, 0, 1), 1.2);
    stroke(lerpColor(topCol, botCol, inter));
    line(0, y, width, y);
  }
}

function drawHourglass() {
  let cx = width / 2;
  let topY = height * 0.2;
  let midY = height * 0.5;
  let botY = height * 0.8;
  let topW = width * 0.6;
  let neckW = width * 0.05;

  noStroke();
  fill(15, 5, 25, 240); // deep silhouette

  beginShape();
  vertex(cx - topW / 2, topY);
  vertex(cx + topW / 2, topY);
  vertex(cx + neckW / 2, midY);
  vertex(cx - neckW / 2, midY);
  endShape(CLOSE);

  beginShape();
  vertex(cx - neckW / 2, midY);
  vertex(cx + neckW / 2, midY);
  vertex(cx + topW / 2, botY);
  vertex(cx - topW / 2, botY);
  endShape(CLOSE);
}

function drawSand() {
  let cx = width / 2;
  let topY = height * 0.2;
  let midY = height * 0.5;
  let botY = height * 0.8;
  let topW = width * 0.6;
  let neckW = width * 0.05;

  // falling stream
  stroke(230, 210, 120, 200);
  strokeWeight(2);
  line(cx, midY - 10, cx, midY + 10);

  noStroke();
  fill(230, 210, 120, 220);

  // grains in upper bulb
  for (let i = 0; i < 150; i++) {
    let t = random();
    let y = random(topY + 10, midY - 10);
    let interp = map(y, topY, midY, 0, 1);
    let wHere = lerp(topW, neckW, interp);
    let x = cx + random(-wHere / 2 + 10, wHere / 2 - 10);
    ellipse(x, y, random(4, 8), random(4, 8));
  }

  // grains in lower bulb
  for (let i = 0; i < 400; i++) {
    let y = random(midY + 10, botY - 10);
    let interp = map(y, midY, botY, 0, 1);
    let wHere = lerp(neckW, topW, interp);
    let pileSlope = (botY - y) / (botY - midY); // steeper near bottom
    let xRange = wHere * pileSlope * 0.5;
    let x = cx + random(-xRange, xRange);
    ellipse(x, y, random(4, 8), random(4, 8));
  }

  // drifting motes above
  for (let i = 0; i < 120; i++) {
    let angle = random(TWO_PI);
    let r = random(50, 250);
    let x = cx + cos(angle) * r;
    let y = topY - 60 + sin(angle) * r * 0.4;
    fill(250, 230, 180, 100);
    ellipse(x, y, random(2, 5), random(2, 5));
  }
}

