function drawGround() {
  noStroke();
  beginShape();
  fill(25, 25, 30);
  let horizon = 1200;
  vertex(0, height);
  vertex(0, horizon);
  for (let x = 0; x <= width; x += 20) {
    let n = noise(x * 0.002, 50);
