// ---------- tree ----------
function drawTree(x, y, len, angle, depth) {
  let sw = map(depth, 0, 8, 1, 16);
  stroke(45, 40, 35);
  strokeWeight(sw);
  let nx = x + len * cos(angle);
  let ny = y + len * sin(angle);
  line(x, y, nx, ny);

  if (depth > 0) {
    let branches = floor(random(2, 4));
    for (let i = 0; i < branches; i++) {
      let newLen = len * random(0.6, 0.8);
      let newAng = angle + random(-PI / 4, PI / 4);
      drawTree(nx, ny, newLen, newAng, depth - 1);
    }
  }
}

