    fill(0, 0, 100, alpha);
    ellipse(x, y, random(1, 3));
  }

  // Whispering ribbons
  strokeWeight(1);
  for (let i = 0; i < 400; i++) {
    const baseR = random(maxR * 0.15, maxR * 0.9);
    const len = random(40, 120);
