      let offset = (noise(nx, ny, r * 0.01) - 0.5) * amp;
      let rad = r + offset;
      vertex(rad * cos(a), rad * sin(a));
    }
    endShape(CLOSE);
  }

  // Faint drifting motes
  push();
  translate(-width / 2, -height / 2);
  for (let i = 0; i < 800; i++) {
