  let cy = height * 0.55;

  // Radial dusk-to-void gradient
  let maxR = dist(0, 0, width, height);
  noStroke();
  for (let r = maxR; r > 0; r -= 4) {
    let t = map(r, maxR, 0, 0, 1);
    let col = lerpColor(color(0, 0, 5), color(120, 120, 130), t);
    fill(col);
    ellipse(cx, cy, r * 2, r * 2.4);
  }

  // Swirling veil
  push();
  translate(cx, cy);
  stroke(220, 220, 230, 30);
  noFill();
  for (let i = 0; i < 500; i++) {
    let rad = i * 3;
    let ang = i * 0.08;
    strokeWeight(1 + i / 300);
    arc(0, 0, rad, rad, ang, ang + HALF_PI);
  }
  pop();

  // Distant cold stars
  noStroke();
  for (let i = 0; i < 1500; i++) {
    let sx = random(width);
