function branch(x, y, len, thick, level) {
  if (level <= 0 || len < 2) return;
  let angle = random(-PI * 0.35, -PI * 0.75);
  let nx = x + len * cos(angle);
  let ny = y + len * sin(angle);
  strokeWeight(thick);
  line(x, y, nx, ny);
  let newLen = len * random(0.6, 0.85);
  branch(nx, ny, newLen, thick * 0.7, level - 1);
  if (random() < 0.7) branch(nx, ny, newLen, thick * 0.6, level - 1);
}

