  // Star-like specks
  stroke(0, 0, 100, 80);
  for (let i = 0; i < 4000; i++) {
    let ang = random(TWO_PI);
    let r = random(100, 800);
    let x = cx + cos(ang) * r + random(-2, 2);
    let y = cy + sin(ang) * r + random(-2, 2);
    point(x, y);
  }

  // Vein-like life lines
  stroke(0, 0, 100, 20);
  noFill();
  for (let i = 0; i < 120; i++) {
    let sx = random(width);
    let sy = random(height);
    beginShape();
    let len = random(200, 800);
    for (let t = 0; t < len; t += 20) {
      let ang = noise(sx * 0.005 + t * 0.01, sy * 0.005 + t * 0.01) * TWO_PI * 2;
      let dx = cos(ang) * 10;
      let dy = sin(ang) * 10;
      vertex(sx + dx + t * 0.1, sy + dy + t * 0.1);
    }
    endShape();
  }
}

