    let t = y / height;
    let h = 220 - 154 * t;          // hue fades toward black-violet
    let s = 40 - 40 * t;            // saturation dissolves
    let b = 20 + 60 * (1 - t);      // brightness dims
    fill(h, s, b);
    rect(0, y, width, 1);
  }

  // Pale drifting forms descending into darkness
  let steps = 800;
  let nOff = random(1000);
  for (let i = 0; i < steps; i++) {
    let t = i / steps;
    let x = width * 0.5 + map(noise(nOff + t * 2), 0, 1, -width * 0.3, width * 0.3);
    let y = height * 0.1 + t * height * 0.9;
    let size = map(noise(nOff + t * 2 + 50), 0, 1, 50, 400) * (1 - t * 0.8);
    let alpha = map(i, 0, steps, 50, 5);
    fill(0, 0, 100, alpha);         // translucent white
    ellipse(x, y, size, size * 0.6);
  }

  // Subtle wisps / fractures
  stroke(0, 0, 100, 8);
  strokeWeight(2);
  noFill();
  let cracks = 120;
  for (let i = 0; i < cracks; i++) {
    let startX = random(width);
