function setup() {
  createCanvas(1600, 2000);
  pixelDensity(2);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  background(10, 10, 12);

  // Swirling mist created with Perlin noise
  loadPixels();
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let nx = x * 0.0025;
      let ny = y * 0.0025;
      let n = noise(nx, ny);

      let dx = x - width / 2;
      let dy = y - height / 2;
      let distCenter = sqrt(dx * dx + dy * dy);
      let dNorm = constrain(distCenter / (max(width, height) * 0.55), 0, 1);

      // Base grayscale from noise
      let shade = map(n, 0, 1, 30, 120);
      // Pull toward darkness at the center
      shade = lerp(shade, 0, pow(1 - dNorm, 3));

      let idx = 4 * (y * width + x);
      pixels[idx]     = shade;
      pixels[idx + 1] = shade;
      pixels[idx + 2] = shade;
      pixels[idx + 3] = 255;
    }
  }
  updatePixels();

  // Filament threads dissolving downward
  stroke(255, 255, 255, 40);
  strokeWeight(1);
  noFill();
  for (let i = 0; i < 140; i++) {
    let startX = random(width);
    let phase = random(TWO_PI);
    let amp   = random(120, 380);
    beginShape();
    for (let y = -50; y <= height + 50; y += 45) {
      let x = startX + sin(y * 0.008 + phase) * amp * 0.3;
      vertex(x, y);
    }
    endShape();
  }

  // Central void (elliptical to suggest a well)
  noStroke();
  for (let r = min(width, height) * 0.55; r > 0; r -= 2) {
    let alpha = map(r, 0, min(width, height) * 0.55, 0, 200);
    fill(0, 0, 0, alpha);
    ellipse(width / 2, height * 0.48, r * 1.25, r * 1.6);
  }
}

