function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  // 背景渐变：深夜到灰白
  for (let y = 0; y < height; y++) {
    let inter = y / height;
    let c = lerpColor(color(10, 10, 30), color(220, 220, 230), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // 下方黑色山体
  noStroke();
  fill(0);
  beginShape();
  vertex(0, height);
  for (let x = 0; x <= width; x += 20) {
    let n = noise(x * 0.001);
    let y = height - map(pow(n, 2), 0, 1, 100, 400);
    vertex(x, y);
  }
  vertex(width, height);
  endShape(CLOSE);

  // 枯树
  drawBranch(width * 0.5, height - 250, -PI / 2, 200, 12);

  // 升空的半透明圆环
  for (let i = 0; i < 120; i++) {
    let t = i / 120;
    let x = width * 0.4 + sin(t * 5 + random(-0.2, 0.2)) * 120;
    let y = height * 0.75 - t * height * 0.8 + random(-20, 20);
    let r = map(t, 0, 1, 50, 5);
    fill(255, 100 * (1 - t));
    noStroke();
    ellipse(x, y, r, r);
  }
}

function drawBranch(x, y, angle, len, thick) {
  if (len < 10) return;
  stroke(0);
  strokeWeight(thick);
  let x2 = x + cos(angle) * len;
  let y2 = y + sin(angle) * len;
  line(x, y, x2, y2);

  let newLen = len * random(0.65, 0.8);
  let newThick = thick * 0.65;
  let branches = 2 + floor(random(0, 2)); // 2–3 条分支
  for (let i = 0; i < branches; i++) {
    let a = angle + random(-PI / 3, PI / 3);
    drawBranch(x2, y2, a, newLen, newThick);
  }
}

