// --------- Sky gradient ----------
function drawSky() {
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let c = lerpColor(color(10, 0, 20), color(80, 0, 0), t * 0.8);
    stroke(c);
    line(0, y, width, y);
  }
  // sparse stars
  noStroke();
  for (let i = 0; i < 250; i++) {
    let x = random(width);
    let y = random(height * 0.5);
    fill(255, 255, 255, random(50, 150));
    ellipse(x, y, random(1, 3));
  }
}

// --------- Ground silhouette ----------
function drawGround() {
  noStroke();
  fill(0);
  beginShape();
  for (let x = 0; x <= width; x += 40) {
    let n = noise(x * 0.002, 50);
    let y = height * 0.6 + n * 120;
    vertex(x, y);
  }
  vertex(width, height);
  vertex(0, height);
  endShape(CLOSE);
}

// --------- Moon ----------
function drawMoon() {
  let r = 240;
  let cx = width / 2;
  let cy = height * 0.38;
  for (let i = r; i > 0; i--) {
    let alpha = map(i, r, 0, 180, 10);
    fill(220, 220, 230, alpha);
    noStroke();
    ellipse(cx, cy, i * 2);
  }
}

// --------- Moon cracks ----------
function drawCracks() {
  let cx = width / 2;
  let cy = height * 0.38;
  push();
  stroke(60, 60, 80, 150);
  for (let i = 0; i < 40; i++) {
    let ang = random(TWO_PI);
    let len = random(60, 120);
    strokeWeight(random(0.5, 2));
    line(cx, cy, cx + cos(ang) * len, cy + sin(ang) * len);
  }
  pop();
}

// --------- Recursive tree ----------
function drawTree(x, y, len, angle, depth, sw) {
  if (depth === 0 || len < 2) return;
  stroke(0);
  strokeWeight(sw);
  let nx = x + cos(angle) * len;
  let ny = y + sin(angle) * len;
  line(x, y, nx, ny);

  let branches = 2 + floor(random(0, 2));
  for (let i = 0; i < branches; i++) {
    let newLen = len * random(0.55, 0.75);
    let newAngle = angle + random(-PI / 4, PI / 4);
    drawTree(nx, ny, newLen, newAngle, depth - 1, max(sw * 0.7, 1));
  }
}

// p5.js 1.11  — static sketch 1600 × 2000
function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  drawSky();
  drawSun();
  drawAshes();
  drawGround();
  drawTree();
}

// ---------- background ----------
function drawSky() {
  for (let y = 0; y < height; y++) {
    let inter = y / height;
    let c = lerpColor(color(60, 65, 70), color(0, 0, 0), inter);
    stroke(c);
    line(0, y, width, y);
  }
}

// ---------- sun ----------
function drawSun() {
  noStroke();
  fill(0);
  ellipse(width * 0.5, height * 0.38, 600, 600);

  // subtle halo
  noFill();
  for (let r = 620; r <= 680; r += 10) {
    stroke(20, 20, 20, map(r, 620, 680, 150, 0));
    ellipse(width * 0.5, height * 0.38, r, r);
  }
}

// ---------- drifting ash ----------
function drawAshes() {
  noStroke();
  for (let i = 0; i < 500; i++) {
    let x = random(width);
    let y = random(height * 0.1, height * 0.6);
    let sz = random(1, 4);
    fill(255, 80);
    ellipse(x, y, sz, sz);
  }
}

// ---------- ground silhouette ----------
function drawGround() {
  noStroke();
  fill(0);
  beginShape();
  vertex(0, height);
  for (let x = 0; x <= width; x += 20) {
    let y = height * 0.6 + noise(x * 0.002) * 120;
    vertex(x, y);
  }
  vertex(width, height);
  endShape(CLOSE);
}

// ---------- withered tree ----------
function drawTree() {
  push();
  stroke(0);
  drawBranch(width * 0.75, height * 0.6, 200, -PI / 2, 16);
  pop();
}

function drawBranch(x, y, len, angle, wt) {
  if (len < 8) return;

  let nx = x + cos(angle) * len;
  let ny = y + sin(angle) * len;

  strokeWeight(wt);
  line(x, y, nx, ny);

  let newW = wt * 0.7;
  let factor1 = random(0.4, 0.7);
  let factor2 = random(0.4, 0.7);

  drawBranch(nx, ny, len * factor1, angle + random(-PI / 6, -PI / 12), newW);
  drawBranch(nx, ny, len * factor2, angle + random(PI / 12, PI / 6), newW);

  if (random() < 0.3) {
    drawBranch(nx, ny, len * random(0.3, 0.6), angle + random(-PI / 8, PI / 8), newW);
  }
}

// p5.js 1.11  静态 1600×2000
function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  drawBackground();
  drawMist();
  drawFloor();
  drawSkull();
  drawRose();
  drawPetals();
}

function drawBackground() {
  for (let y = 0; y < height; y++) {
    let inter = y / height;
    let c = lerpColor(color(5, 5, 8), color(25, 25, 28), inter);
    stroke(c);
    line(0, y, width, y);
  }
}

function drawMist() {
  noStroke();
  for (let i = 0; i < 800; i++) {
    let x = random(width);
    let y = random(height * 0.6);
    let s = random(50, 300);
    fill(255, 25);
    ellipse(x, y, s, s);
  }
}

function drawFloor() {
  noStroke();
  fill(20, 20, 20);
  rect(0, 1500, width, 500);
}

function drawSkull() {
  let x = width * 0.4;
  let y = 1300;
  let r = 300;

  // cranium
  noStroke();
  fill(245);
  ellipse(x, y, r, r);

  // jaw
  rectMode(CENTER);
  rect(x, y + r * 0.45, r * 0.8, r * 0.4, 80);

  // eyes
  fill(10);
  ellipse(x - r * 0.22, y - r * 0.1, r * 0.25, r * 0.32);
  ellipse(x + r * 0.22, y - r * 0.1, r * 0.25, r * 0.32);

  // nose
  fill(15);
  triangle(
    x, y + r * 0.02,
    x - r * 0.07, y + r * 0.22,
    x + r * 0.07, y + r * 0.22
  );
}

function drawRose() {
  push();
  noFill();
  stroke(60, 90, 60);
  strokeWeight(8);
  beginShape();
  curveVertex(width * 0.65, 900);
  curveVertex(width * 0.65, 900);
  curveVertex(width * 0.63, 1050);
  curveVertex(width * 0.60, 1200);
  curveVertex(width * 0.56, 1350);
  curveVertex(width * 0.56, 1350);
  endShape();

  // wilted head
  fill(120, 20, 20);
  noStroke();
  ellipse(width * 0.65, 900, 100, 140);
  pop();
}

function drawPetals() {
  noStroke();
  for (let i = 0; i < 40; i++) {
    let px = random(width * 0.5, width * 0.75);
    let py = random(950, 1500);
    let a = random(TWO_PI);
    let s = random(20, 50);
    fill(140 + random(-20, 20), 30, 30, 220);
    push();
    translate(px, py);
    rotate(a);
    ellipse(0, 0, s * 0.6, s);
    pop();
  }
}

// p5.js 1.11
function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  colorMode(HSB, 360, 100, 100, 100);
  noStroke();
  drawScene();
  noLoop();
}

function drawScene() {
  // 夜色渐变背景
  for (let y = 0; y < height; y++) {
    let c = lerpColor(color(220, 20, 5), color(220, 30, 20), y / height);
    stroke(c);
    line(0, y, width, y);
  }

  // 迷雾噪声层
  noStroke();
  for (let y = 0; y < height; y += 4) {
    for (let x = 0; x < width; x += 4) {
      let n = noise(x * 0.002, y * 0.002);
      fill(220, 10, 20 + n * 20, 10);
      rect(x, y, 4, 4);
    }
  }

  // 头骨主体
  push();
  translate(width / 2, height * 0.45);
  let skullW = width * 0.4;
  let skullH = skullW * 1.2;
  fill(0, 0, 95);
  ellipse(0, 0, skullW, skullH * 0.8);          // 颅骨
  rectMode(CENTER);
  rect(0, skullH * 0.25, skullW * 0.6, skullH * 0.4, skullW * 0.1); // 下颌

  // 眼窝
  fill(0, 0, 5);
  ellipse(-skullW * 0.15, -skullH * 0.1, skullW * 0.18, skullW * 0.28);
  ellipse(skullW * 0.15, -skullH * 0.1, skullW * 0.18, skullW * 0.28);

  // 鼻腔
  triangle(0, 0, -skullW * 0.05, skullH * 0.05, skullW * 0.05, skullH * 0.05);

  // 牙缝
  stroke(0, 0, 20, 50);
  strokeWeight(2);
  for (let i = -4; i <= 4; i++) {
    let x = i * skullW * 0.06;
    line(x, skullH * 0.15, x, skullH * 0.35);
  }
  line(-skullW * 0.3, skullH * 0.25, skullW * 0.3, skullH * 0.25);
  pop();

  // 地面阴影
  noStroke();
  for (let i = 0; i < 200; i++) {
    let a = map(i, 0, 199, 20, 0);
    fill(0, 0, 0, a);
    ellipse(width / 2, height * 0.75, width * 0.8 - i * 4, height * 0.1 - i * 0.3);
  }
}

// p5.js 1.11 – static sketch 1600 × 2000
function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  colorMode(HSB, 360, 100, 100, 100);
  background(0, 0, 0);

  translate(width / 2, height / 2);
  let maxR = min(width, height) * 0.55;

  // 雾状内核
  noStroke();
  for (let i = 0; i < 8000; i++) {
    let t = random(1);
    let a = random(TWO_PI);
    let r = pow(t, 0.4) * maxR * (0.5 + 0.5 * noise(t * 5, a));
    let x = cos(a) * r + random(-2, 2);
    let y = sin(a) * r + random(-2, 2);
    let brt = map(r, 0, maxR, 95, 0);
    fill(0, 0, brt, 8);
    ellipse(x, y, random(3, 12));
  }

  // 同心波纹
  noFill();
  for (let i = 0; i < 120; i++) {
    let r = map(i, 0, 119, 0, maxR);
    stroke(0, 0, map(i, 0, 119, 100, 0), 4);
    strokeWeight(map(i, 0, 119, 4, 0.2));
    ellipse(0, 0, r * 2, r * 2);
  }

  // 向外蔓延的裂隙
  strokeWeight(0.7);
  for (let k = 0; k < 260; k++) {
    let ang = random(TWO_PI);
    let len = random(maxR * 0.15, maxR * 0.9);
    let segments = int(random(3, 10));
    beginShape();
    for (let s = 0; s < segments; s++) {
      let rr = map(s, 0, segments - 1, 0, len) + noise(k * 0.1, s * 0.3) * 20;
      let vx = cos(ang) * rr;
      let vy = sin(ang) * rr;
      stroke(0, 0, map(rr, 0, maxR, 80, 10), 20);
      vertex(vx, vy);
    }
    endShape();
  }
}

// p5.js 1.11  – 1600 × 2000  static sketch
function setup() {
  randomSeed(1);
  noiseSeed(1);

  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  colorMode(HSL, 360, 100, 100, 100);
  background(0, 0, 95);          // 轻雾般的底

  const cx = width / 2;
  const cy = height * 0.45;      // 空洞中心
  const maxDist = min(width, height) * 0.45;

  noStroke();
  const step = 4;                // 采样间距
  for (let y = 0; y < height; y += step) {
    for (let x = 0; x < width; x += step) {
      const n = noise(x * 0.005, y * 0.005);   // 漩涡噪声
      let b = map(n, 0, 1, 20, 85);            // 基础亮度

      const d = dist(x, y, cx, cy);            // 深渊衰减
      const edge = constrain(map(d, 0, maxDist, 0, 1), 0, 1);
      b = lerp(b, 0, pow(edge, 2));

      fill(0, 0, b);
      rect(x, y, step, step);
    }
  }

  // 更深的中心黑洞（多层半透明椭圆）
  for (let r = max(width, height) * 0.6; r > 0; r -= 5) {
    const a = map(r, max(width, height) * 0.6, 0, 0, 100);
    fill(0, 0, 0, a);
    ellipse(cx, cy, r, r);
  }

  // 漫游的微光线条
  stroke(0, 0, 100, 15);
  strokeWeight(1);
  for (let i = 0; i < 200; i++) {
    const x = random(width);
    const len = random(50, 400);
    const offset = random(-300, 200);
    line(x, cy + offset, x, cy + offset - len);
  }
}

// p5.js 1.11  静态画布 1600×2000
function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
  colorMode(RGB, 255, 255, 255, 255);

  // 背景：自下而上由暖至黑
  for (let y = 0; y < height; y++) {
    let t = y / height;                     // 0 顶 1 底
    let c = lerpColor(color(0, 0, 0),       // 顶端黑
                      color(230, 180, 80),  // 底端微暖
                      pow(1 - t, 1.5));     // 非线性渐变
    noStroke();
    fill(c);
    rect(0, y, width, 1);
  }

  // 卷旋薄雾
  let cx = width * 0.5;
  let cy = height * 0.4;
  noStroke();
  for (let i = 0; i < 4000; i++) {
    let ang  = random(TWO_PI);
    let dist = pow(random(1), 2.2) * width * 0.5;   // 越靠中心越密
    let wobble = map(noise(dist * 0.002, i * 0.01), 0, 1, -50, 50);
    let x = cx + cos(ang) * (dist + wobble);
    let y = cy + sin(ang) * (dist + wobble);
    let d = map(dist, 0, width * 0.5, 600, 5);
    let a = map(dist, 0, width * 0.5, 20, 2);
    fill(200, a);
    ellipse(x, y, d, d);
  }

  // 中央虚空
  fill(0);
  ellipse(cx, cy, 600, 600);

  // 顶部稀疏光点
  stroke(255, 30);
  strokeWeight(2);
  for (let i = 0; i < 800; i++) {
    point(random(width), random(height * 0.3));
  }
}

