// p5.js 1.11  — 1600 × 2000
function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  background(10, 10, 20);          // 夜色般的基底

  // 环形雾幕：被撕碎的色彩
  push();
  translate(width / 2, height / 2);
  let maxR = max(width, height) * 0.7;
  noStroke();
  for (let r = maxR; r > 0; r -= 4) {
    let n = noise(r * 0.01);
    let alpha = map(r, 0, maxR, 120, 0);
    fill(100 + 50 * n, 110 + 40 * n, 120 + 20 * n, alpha);
    ellipse(0, 0, r * 2);
  }
  pop();

  // 中心黑洞：终点
  noStroke();
  for (let r = 320; r > 0; r -= 6) {
    let alpha = map(r, 320, 0, 0, 255);
    fill(0, 0, 0, alpha);
    ellipse(width / 2, height / 2, r * 2);
  }

  // 飘散尘屑：逐渐撤离的记忆
  for (let i = 0; i < 4000; i++) {
    let angle = random(TWO_PI);
    let rad = random(350, max(width, height) / 2);
    let x = width / 2 + cos(angle) * rad + random(-10, 10);
    let y = height / 2 + sin(angle) * rad + random(-10, 10);
    let b = random(100, 220);
    fill(b, b, b, random(20, 70));
    noStroke();
    ellipse(x, y, random(1, 4));
  }

  // 下落的微光：逝去的余辉
  stroke(200, 200, 220, 40);
  for (let x = 0; x < width; x += 10) {
    let len = random(100, 400);
    line(x, height, x, height - len);
  }
}

/*
  p5.js 1.11  静态图像 1600×2000
  “裂缝之门”
*/
function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();
}

function draw() {
  background(0);

  // 1. 深色垂直渐变背景
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c = lerpColor(color(260, 30, 5), color(260, 30, 0), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // 2. 中央炽白竖缝（微光向外淡出）
  for (let x = width / 2 - 120; x <= width / 2 + 120; x++) {
    let d = abs(x - width / 2);
    let a = map(d, 0, 120, 95, 0);
    stroke(0, 0, 100, a);
    line(x, 0, x, height);
  }

  // 3. 噪声粒线 —— 飘散的“形态”
  strokeWeight(1.2);
  for (let gx = 0; gx < width; gx += 40) {
    for (let gy = 0; gy < height; gy += 40) {
      drawNoisePath(gx + random(-10, 10), gy + random(-10, 10), 100);
    }
  }

  // 4. 四周再覆一层极暗透明罩，使中心更亮
  for (let y = 0; y < height; y++) {
    let a = map(y, 0, height, 40, 90);
    stroke(260, 30, 0, a);
    line(0, y, width, y);
  }
}

// 依据噪声场的细线路径
function drawNoisePath(x, y, len) {
  let px = x;
  let py = y;
  for (let i = 0; i < len; i++) {
    let n = noise(px * 0.002, py * 0.002);
    let ang = n * TAU * 4;
    let nx = px + cos(ang) * 4;
    let ny = py + sin(ang) * 4;

    let dCenter = dist(nx, ny, width / 2, height / 2);
    let brt = map(dCenter, 0, max(width, height) / 2, 80, 20);
    stroke(0, 0, brt, 20);
    line(px, py, nx, ny);

    px = nx;
    py = ny;

    if (px < 0 || px > width || py < 0 || py > height) break;
  }
}

let heartPts = [];

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();
  buildHeartTable();
}

function draw() {
  backgroundGradient();
  translate(width / 2, height * 0.45);

  glowHeart();
  connectiveRibbons();
}

// ---------- background ----------
function backgroundGradient() {
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let col = lerpColor(color(250, 50, 15), color(260, 40, 5), t);
    stroke(col);
    line(0, y, width, y);
  }

  noStroke();
  for (let i = 0; i < 800; i++) {
    let x = random(width);
    let y = random(height);
    fill(260, 30, random(40, 80), random(10, 30));
    ellipse(x, y, random(1, 3), random(1, 3));
  }
}

// ---------- heart construction ----------
function buildHeartTable() {
  heartPts = [];
  for (let a = 0; a < TWO_PI; a += 0.02) {
    let x = 16 * pow(sin(a), 3);
    let y = -(
      13 * cos(a) -
      5 * cos(2 * a) -
      2 * cos(3 * a) -
      cos(4 * a)
    );
    heartPts.push(createVector(x, y));
  }
}

function drawHeart(sz) {
  beginShape();
  for (let v of heartPts) {
    vertex(v.x * sz * 0.05, v.y * sz * 0.05);
  }
  endShape(CLOSE);
}

// ---------- glowing heart ----------
function glowHeart() {
  noStroke();
  for (let i = 0; i < 120; i++) {
    let t = i / 119;
    let h = 340;
    let s = lerp(70, 95, t);
    let b = lerp(95, 60, t);
    let a = lerp(60, 100, t);
    fill(h, s, b, a);
    push();
    scale(1 - t * 0.3);
    rotate(sin(t * PI) * 0.05);
    drawHeart(600 - t * 150);
    pop();
  }
}

// ---------- ribbons ----------
function connectiveRibbons() {
  strokeWeight(2);
  for (let i = 0; i < 180; i++) {
    let baseHue = 340 + random(-10, 10);
    stroke(baseHue, 80, 90, 25);
    let a = random(TWO_PI);
    let startR = random(500, 700);
    beginShape();
    for (let j = 0; j <= 40; j++) {
      let t = j / 40;
      let r = lerp(startR, 0, t);
      let angShift = noise(i * 0.02, t * 2) * PI - PI / 2;
      let ang = a + angShift * (1 - t);
      let x = r * cos(ang);
      let y = r * sin(ang);
      curveVertex(x, y);
    }
    endShape();
  }
}

// p5.js v1.11 – self-contained sketch
function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();
}

function draw() {
  drawBackground();
  drawHeartLayers();
  drawCentralGlow();
}

// -------- background gradient --------
function drawBackground() {
  noStroke();
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let h = lerp(255, 305, t);      // indigo → deep blue
    let s = 60;
    let b = lerp(25, 5, t);         // subtle darkening
    fill(h, s, b);
    rect(0, y, width, 1);
  }
}

// -------- layered heart --------
function drawHeartLayers() {
  const layers = 60;
  push();
  translate(width / 2, height * 0.55);
  scale(40);                        // unit heart → ~640 px wide
  noStroke();
  for (let i = 0; i < layers; i++) {
    let t = i / (layers - 1);
    let sc = lerp(1.35, 0.12, t);   // large → small
    let hueVal = lerp(340, 25, t);  // crimson → golden
    let briVal = lerp(60, 90, t);   // soft → luminous
    fill(hueVal, 80, briVal, 90);
    push();
    scale(sc);
    heartShape();
    pop();
  }
  pop();
}

// -------- inner glow --------
function drawCentralGlow() {
  push();
  translate(width / 2, height * 0.55);
  noStroke();
  for (let r = 280; r > 0; r -= 4) {
    let alpha = map(r, 280, 0, 0, 80);
    fill(50, 5, 100, alpha);
    ellipse(0, 0, r, r);
  }
  pop();
}

// -------- heart path --------
function heartShape() {
  beginShape();
  for (let a = 0; a < TWO_PI; a += 0.05) {
    let x = 16 * pow(sin(a), 3);
    let y = 13 * cos(a) - 5 * cos(2 * a) - 2 * cos(3 * a) - cos(4 * a);
    vertex(x, -y);                  // flip y so tip points downward
  }
  endShape(CLOSE);
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  backgroundGradient();
  centralGlow();
  drawBlob(width * 0.45, height * 0.55, 360, 100, color(255, 180, 200, 190));
  drawBlob(width * 0.55, height * 0.45, 360, 100, color(180, 200, 255, 170));
  highlightOverlap();
  sparkles();
}

function backgroundGradient() {
  let c1 = color(60, 0, 80);
  let c2 = color(255, 110, 150);
  for (let y = 0; y < height; y++) {
    let inter = y / height;
    stroke(lerpColor(c1, c2, inter));
    line(0, y, width, y);
  }
  noStroke();
}

function centralGlow() {
  drawingContext.globalCompositeOperation = 'lighter';
  for (let r = 0; r < 800; r += 20) {
    let a = map(r, 0, 800, 100, 0);
    fill(255, 180, 200, a);
    ellipse(width / 2, height / 2, r * 2.5, r * 2.5);
  }
  drawingContext.globalCompositeOperation = 'source-over';
}

function drawBlob(cx, cy, base, amp, fc) {
  fill(fc);
  beginShape();
  for (let a = 0; a <= 360; a++) {
    let ang = radians(a);
    let n = noise(cos(ang) * 1.5 + 3, sin(ang) * 1.5 + 3);
    let r = base + n * amp;
    let x = cx + cos(ang) * r;
    let y = cy + sin(ang) * r;
    vertex(x, y);
  }
  endShape(CLOSE);
}

function highlightOverlap() {
  fill(255, 250, 230, 120);
  ellipse(width / 2, height / 2, 250, 250);
}

function sparkles() {
