function drawRadialGradient() {
  const center = createVector(width / 2, height / 2);
  const maxR = dist(0, 0, width / 2, height / 2) * 1.4;
  const steps = 800;
  const cEdge = color(30, 0, 60);
  const cCenter = color(255, 150, 180);
  noStroke();
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const r = lerp(maxR, 0, t);
    fill(lerpColor(cEdge, cCenter, 1 - t));
    ellipse(center.x, center.y, r * 2, r * 2.2);
  }
}

function heartShape(sz) {
  beginShape();
  for (let t = 0; t <= TWO_PI; t += 0.05) {
    const x = 16 * pow(sin(t), 3);
    const y =
      13 * cos(t) -
      5 * cos(2 * t) -
      2 * cos(3 * t) -
      cos(4 * t);
    vertex(x * sz, -y * sz);
  }
  endShape(CLOSE);
}

