  background(0, 0, 10);                 // deep night backdrop

  centerX = width / 2;
  centerY = height * 0.55;
  maxR    = min(width, height) * 0.45;

  radiantMist();
  interwovenThreads();
  heartbeatRings();

  noLoop();
}

function radiantMist() {
  noStroke();
  for (let i = 0; i < 10000; i++) {
    let a = random(TWO_PI);
    let r = sqrt(random()) * maxR;
    let x = centerX + r * cos(a);
    let y = centerY + r * sin(a);

    let hueVal = (340 + 40 * (r / maxR)) % 360;                   // warm core → gold edge
    let satVal = map(noise(x * 0.002, y * 0.002), 0, 1, 60, 100);
    let briVal = map(r, 0, maxR, 100, 20);

    fill(hueVal, satVal, briVal, 25);
    let d = random(4, 20);
    ellipse(x, y, d, d);
  }
}

function interwovenThreads() {
  for (let i = 0; i < 600; i++) {
    let p1 = randomPoint(maxR * 0.7);
    let p2 = randomPoint(maxR * 0.7);

    strokeWeight(random(0.5, 3));
    stroke(random([10, 20, 330, 340]), 80, 95, 15);

    bezier(centerX + p1.x, centerY + p1.y,
           centerX + p1.x * random(0.2, 0.6), centerY + p1.y * random(0.2, 0.6),
           centerX + p2.x * random(0.2, 0.6), centerY + p2.y * random(0.2, 0.6),
           centerX + p2.x, centerY + p2.y);
  }
}

function heartbeatRings() {
  noFill();
  stroke(0, 0, 100, 3);
  strokeWeight(2);
  for (let r = 20; r < maxR * 0.9; r += 30) {
    ellipse(centerX, centerY, r * 2, r * 2);
  }
}

function randomPoint(radius) {
  let a = random(TWO_PI);
  let r = sqrt(random()) * radius;
  return createVector(r * cos(a), r * sin(a));
}

