function drawAura() {
  let maxR = dist(0, 0, width / 2, height / 2);
  for (let i = 0; i < 500; i++) {
    let ang = random(TWO_PI);
    let rad = sqrt(random()) * maxR;
    let x = width / 2 + cos(ang) * rad;
    let y = height / 2 + sin(ang) * rad;
    fill(255, 100, 150, 20);
    noStroke();
    ellipse(x, y, random(5, 20));
  }
}

function drawSwirls() {
  for (let k = 0; k < 150; k++) {
    stroke(255, 140, 180, 60);
    strokeWeight(1.5);
    noFill();
    beginShape();
    let o = random(1000);
    for (let t = 0; t < 1.2; t += 0.02) {
      let a = t * TWO_PI * 2;
      let r = map(noise(o + cos(a), o + sin(a)), 0, 1, 80, 220);
      let x = width / 2 + cos(a) * r + random(-5, 5);
      let y = height / 2 + sin(a) * r + random(-5, 5);
      curveVertex(x, y);
    }
    endShape();
  }
}

function drawHeart(cx, cy, size, col, alpha) {
  push();
  translate(cx, cy);
  scale(size);
  noStroke();
  fill(red(col), green(col), blue(col), alpha);
  beginShape();
  for (let a = 0; a < TWO_PI; a += 0.05) {
    let x = 16 * pow(sin(a), 3);
    let y = -(13 * cos(a) - 5 * cos(2 * a) - 2 * cos(3 * a) - cos(4 * a));
    vertex(x, y);
  }
  endShape(CLOSE);
  pop();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  colorMode(HSB, 360, 100, 100, 100);
}

function draw() {
  drawGradient();
  drawNebula();
  drawTranslucentHearts();
  drawMainHearts();
}

function drawGradient() {
  for (let y = 0; y < height; y++) {
    let inter = y / height;
    let c = lerpColor(color(330, 40, 100), color(220, 30, 30), inter);
    stroke(c);
    line(0, y, width, y);
  }
}

function drawNebula() {
  noStroke();
  for (let i = 0; i < 4000; i++) {
    let t = i * 0.05;
    let r = 400 + noise(t, t * 0.3) * 300;
    let ang = t * 0.05;
    let x = width / 2 + r * cos(ang);
    let y = height * 0.5 + r * 0.4 * sin(ang);
    fill(random(0, 360), 30, 100, 8);
    circle(x, y, random(5, 20));
  }
}

function drawTranslucentHearts() {
  for (let i = 0; i < 35; i++) {
    let x = random(width * 0.1, width * 0.9);
    let y = random(height * 0.1, height * 0.9);
    let sz = random(60, 300);
    let h = random(0, 360);
    fill(h, 50, 90, 20);
    push();
    translate(x, y);
    rotate(random(-PI, PI));
    drawHeart(0, 0, sz);
    pop();
  }
}

function drawMainHearts() {
  let c1 = color(350, 80, 90, 70);
  let c2 = color(200, 60, 90, 70);
  drawHeart(width * 0.43, height * 0.55, 500, c1);
  drawHeart(width * 0.57, height * 0.45, 500, c2);
}

function drawHeart(x, y, size, col) {
  push();
  translate(x, y);
  scale(size);
  fill(col);
  noStroke();
  beginShape();
  vertex(0, -0.4);
  bezierVertex(-0.5, -1.1, -1.3, -0.1, 0, 0.7);
  bezierVertex(1.3, -0.1, 0.5, -1.1, 0, -0.4);
  endShape(CLOSE);
  pop();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  colorMode(HSB, 360, 100, 100, 100);
  noStroke();

  // Radial gradient background
  let maxRad = sqrt(sq(width * 0.5) + sq(height * 0.5));
  for (let r = maxRad; r > 0; r -= 8) {
    let t = r / maxRad;
    let h = lerp(330, 200, t);      // magenta to blue
    let s = lerp(90, 60, t);
    let b = lerp(100, 40, t);
    fill(h, s, b, 100);
    ellipse(width * 0.5, height * 0.5, r * 2, r * 2);
  }

  // Swirling ribbons
  drawRibbon(color(350, 80, 100, 60), 0.003, 120); // warm
  drawRibbon(color(200, 70, 100, 60), 0.0025, 140); // cool

  // Sparkles
  drawSparkles(1200, color(60, 20, 100, 40));
}

function drawRibbon(col, nScale, thickness) {
  let path = [];
  for (let y = 0; y <= height; y += 10) {
    let x = width * 0.5 + noise(y * nScale) * 400 - 200;
    path.push({ x: x, y: y });
  }
  noFill();
  stroke(col);
  strokeWeight(thickness);
  beginShape();
  for (let i = 0; i < path.length; i++) {
    curveVertex(path[i].x, path[i].y);
  }
  endShape();
}

function drawSparkles(count, col) {
  noStroke();
  fill(col);
  for (let i = 0; i < count; i++) {
    let x = random(width);
    let y = random(height);
    let s = random(2, 6);
    ellipse(x, y, s, s);
  }
}

