function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();
}

function draw() {
  // Radial background gradient
  let edgeCol = color(210, 80, 15, 100);   // sombre bleu-nuit
  let coreCol = color(350, 30, 100, 100);  // clair rosé
  let maxR = dist(0, 0, width / 2, height / 2);
  noStroke();
  for (let r = maxR; r > 0; r -= 6) {
    let t = r / maxR;
    fill(lerpColor(coreCol, edgeCol, t * t));
    ellipse(width / 2, height / 2, r * 2, r * 2);
  }

  // Nuée de cercles translucides
  for (let i = 0; i < 900; i++) {
    let angle = random(TWO_PI);
    let d = abs(randomGaussian()) * width * 0.25;
    let x = width / 2 + cos(angle) * d;
    let y = height / 2 + sin(angle) * d * 1.2;
    let sz = abs(randomGaussian()) * 300 + 40;

    let n = noise(x * 0.001, y * 0.001);
    let h, s, b;
    if (n < 0.55) {          // gammes chaudes
      h = random(0, 60);
      s = random(60, 100);
      b = random(70, 100);
    } else {                 // touches plus fraîches
      h = random(180, 240);
      s = random(40, 80);
      b = random(40, 90);
    }
    fill(h, s, b, random(10, 35));
    ellipse(x, y, sz, sz);
  }

  // Fins filaments courbes reliant les zones
  strokeWeight(2);
  for (let i = 0; i < 400; i++) {
    let x1 = random(width * 0.2, width * 0.8);
    let y1 = random(height * 0.2, height * 0.8);
    let x2 = random(width * 0.2, width * 0.8);
    let y2 = random(height * 0.2, height * 0.8);
    let midx = (x1 + x2) / 2 + random(-100, 100);
    let midy = (y1 + y2) / 2 + random(-100, 100);

    stroke(color(random(0, 360), 30, 100, 15));
    noFill();
    beginShape();
    curveVertex(x1, y1);
    curveVertex(x1, y1);
    curveVertex(midx, midy);
    curveVertex(x2, y2);
    curveVertex(x2, y2);
    endShape();
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  colorMode(RGB, 255, 255, 255, 255);

  // Background vertical gradient
  for (let y = 0; y < height; y++) {
    let inter = y / height;
    let c = lerpColor(color(255, 140, 160), color(60, 0, 80), inter);
    stroke(c);
    line(0, y, width, y);
  }

  // Subtle noise texture
  noStroke();
  for (let i = 0; i < 40000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.002, y * 0.002);
    fill(255, 40 * n);
    rect(x, y, 1, 1);
  }

  // Central glowing heart
  push();
  translate(width / 2, height * 0.45);
  for (let s = 600; s > 0; s -= 10) {
    let pct = s / 600;
    let col = lerpColor(color(255, 80, 120, 180), color(255, 0, 60, 10), pct);
    drawHeart(0, 0, s, col);
  }
  pop();

  // Outward spiral of hearts
  let total = 160;
  for (let i = 0; i < total; i++) {
    let t = i / total;
    let angle = i * 0.4 * PI;
    let r = 50 + 600 * sqrt(t);
    let x = width / 2 + r * cos(angle);
    let y = height * 0.45 + r * sin(angle);
    let sz = map(i, 0, total, 120, 10);
    let col = lerpColor(color(255, 100, 140, 200), color(255, 220, 240, 80), t);
    drawHeart(x, y, sz, col);
  }
}

function drawHeart(x, y, s, col) {
  push();
  translate(x, y);
  scale(s / 32); // Base size factor for the parametric heart
  beginShape();
  fill(col);
  noStroke();
  for (let a = 0; a <= TWO_PI + 0.01; a += 0.05) {
    let xx = 16 * pow(sin(a), 3);
    let yy = -(13 * cos(a) - 5 * cos(2 * a) - 2 * cos(3 * a) - cos(4 * a));
    vertex(xx, yy);
  }
  endShape(CLOSE);
  pop();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();
  noStroke();
}

function draw() {
  const cx = width / 2;
  const cy = height / 2;

  // Radial gradient background
  const maxR = max(width, height) * 0.8;
  for (let r = maxR; r > 0; r -= 10) {
    const t = r / maxR;
    const edgeCol = color(300, 60, 40, 100); // violet edge
    const centerCol = color(20, 80, 100, 100); // golden center
    fill(lerpColor(centerCol, edgeCol, t));
    ellipse(cx, cy, r * 2, r * 2);
  }

  // Translucent radiating petals
  const petals = 160;
  for (let i = 0; i < petals; i++) {
    const ang = TWO_PI * i / petals;
    const h = map(i, 0, petals, 0, 360);
    fill(h, 60, 90, 25);
    push();
    translate(cx, cy);
    rotate(ang);
    beginShape();
    const len = width * 0.18 + noise(i) * width * 0.04;
    for (let t = 0; t <= 1; t += 0.1) {
      const offset = noise(i * 0.3 + t) * 30;
      const x = lerp(0, len, t);
      const y = sin(t * PI) * (len * 0.35 + offset);
      vertex(x, y);
    }
    for (let t = 1; t >= 0; t -= 0.1) {
      const offset = noise(i * 0.3 + t + 5) * 30;
      const x = lerp(0, len, t);
      const y = -sin(t * PI) * (len * 0.35 + offset);
      vertex(x, y);
    }
    endShape(CLOSE);
    pop();
  }

  // Central glow
  const glowR = width * 0.15;
  for (let r = glowR; r > 0; r -= 5) {
    const alpha = map(r, glowR, 0, 15, 100);
    fill(45, 20, 100, alpha);
    ellipse(cx, cy, r * 2, r * 2);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();
}

function draw() {
  background(0, 0, 0);

  // Radial gradient backdrop
  const cx = width / 2;
  const cy = height / 2;
  const maxR = dist(0, 0, cx, cy);
  const steps = 300;
  noStroke();
  for (let i = steps; i >= 0; i--) {
    const pct = i / steps;
    const h = lerp(20, 280, pct);   // chaud centre → froid bords
    const s = lerp(90, 60, pct);
    const b = lerp(100, 40, pct);
    fill(h, s, b, 100);
    circle(cx, cy, pct * maxR * 2);
  }

  // Swirl of translucent hearts
  const n = 140;
  for (let i = 0; i < n; i++) {
    const frac = i / n;
    const angle = frac * TWO_PI * 5 + noise(i) * TWO_PI;
    const radius = sqrt(frac) * width * 0.45 + random(-30, 30);
    const x = cx + radius * cos(angle);
    const y = cy + radius * sin(angle) * 0.7;
    const rot = angle + random(-PI / 8, PI / 8);
    const sizeFactor = lerp(6, 40, pow(random(), 0.7));
    const hue = lerp(330, 0, frac);
    const sat = lerp(40, 90, sin(frac * PI));
    heartShape(x, y, sizeFactor, rot, color(hue, sat, 100, 30));
  }

  // Central soft glow
  for (let r = 200; r > 0; r -= 10) {
    fill(20, 60, 100, map(r, 200, 0, 10, 60));
    circle(cx, cy, r * 2);
  }
}

function heartShape(x, y, s, rot, col) {
  push();
  translate(x, y);
  rotate(rot);
  scale(s);
  fill(col);
  noStroke();
  beginShape();
  for (let t = 0; t < TWO_PI; t += 0.05) {
    const hx = 16 * pow(sin(t), 3);
    const hy = -(13 * cos(t) - 5 * cos(2 * t) - 2 * cos(3 * t) - cos(4 * t));
    vertex(hx, hy);
  }
  endShape(CLOSE);
  pop();
}

