// p5.js 1.11 sketch – static image 1600 × 2000
function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  colorMode(HSB, 360, 100, 100, 100);
  noStroke();

  drawBackground();
  drawGlow(width / 2, height * 0.4);
  drawLayeredHeart(width / 2 - 220, height * 0.45, 23, 340); // pink-violet
  drawLayeredHeart(width / 2 + 220, height * 0.45, 23, 20);  // warm orange
  sprinkleParticles();
  noLoop();
}

function drawBackground() {
  for (let y = 0; y < height; y++) {
    let inter = y / height;
    let c1 = color(250, 50, 15);
    let c2 = color(330, 40, 10);
    stroke(lerpColor(c1, c2, inter));
    line(0, y, width, y);
  }
}

function drawGlow(cx, cy) {
  for (let r = 700; r > 50; r -= 15) {
    fill(330, 60, 100, map(r, 700, 50, 0, 20));
    ellipse(cx, cy, r, r);
  }
}

function drawLayeredHeart(x, y, baseScale, hueVal) {
  push();
  translate(x, y);
  for (let k = 22; k >= 1; k--) {
    let s = baseScale * (k / 22) * 1.05;
    fill(hueVal, 70, map(k, 1, 22, 95, 75), map(k, 1, 22, 95, 30));
    drawHeartShape(s);
  }
  pop();
}

function drawHeartShape(scaleFactor) {
  beginShape();
  for (let t = 0; t <= TWO_PI + 0.05; t += 0.05) {
    let x = 16 * pow(sin(t), 3);
    let y = -(13 * cos(t) - 5 * cos(2 * t) - 2 * cos(3 * t) - cos(4 * t));
    vertex(x * scaleFactor, y * scaleFactor);
  }
  endShape(CLOSE);
}

function sprinkleParticles() {
  let cx = width / 2;
  let cy = height * 0.4;
  for (let i = 0; i < 1800; i++) {
    let ang = random(TWO_PI);
    let rad = pow(random(), 0.6) * 550;
    let px = cx + cos(ang) * rad;
    let py = cy + sin(ang) * rad;
    let h = lerp(20, 340, noise(px * 0.002, py * 0.002));
    fill(h, 40, 100, random(30, 70));
    ellipse(px, py, random(3, 8), random(3, 8));
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  colorMode(HSL, 360, 100, 100, 1);
  noLoop();

  // 背景柔和渐变
  noStroke();
  for (let y = 0; y < height; y += 2) {
    let h = map(y, 0, height, 350, 310); // 粉至淡紫
    fill(h, 40, 95);
    rect(0, y, width, 2);
  }

  push();
  translate(width / 2, height * 0.45); // 心形中心位置
  drawHeartField();
  pop();

  // 外侧柔光环
  for (let i = 0; i < 300; i++) {
    let ang = random(TWO_PI);
    let r = random(480, 650);
    let x = width / 2 + cos(ang) * r;
    let y = height * 0.45 + sin(ang) * r * 0.8;
    let h = random(330, 350);
    fill(h, 50, 90, 0.08);
    ellipse(x, y, random(60, 160));
  }
}

function drawHeartField() {
  const scl = 460;          // 缩放因子
  const maxDots = 30000;    // 采样次数
  for (let i = 0; i < maxDots; i++) {
    let x = random(-1.35, 1.35);
    let y = random(-1.35, 1.35);
    if (inHeart(x, y)) {
      let d = dist(0, 0, x, y);
      let h = map(d, 0, 1.35, 0, 330);   // 色相：中心红向外紫
      let l = map(d, 0, 1.35, 55, 75);   // 亮度渐增
      fill(h, 70, l, 0.18);
      let sz = random(6, 20);
      ellipse(x * scl, y * scl, sz, sz);
    }
  }
}

// 隐式心形方程
function inHeart(x, y) {
  return pow(x * x + y * y - 1, 3) - x * x * y * y * y <= 0;
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  drawGradient();
  translate(width / 2, height / 2 + 100); // 心形垂直微调居中
  noStroke();

  // 绘制爱心云朵
  for (let i = 0; i < 6000; i++) {
    let t = random(TWO_PI);
    let x = 16 * pow(sin(t), 3);
    let y = -(
      13 * cos(t) -
      5 * cos(2 * t) -
      2 * cos(3 * t) -
      cos(4 * t)
    );

    let scaleFactor = 33; // 控制整体尺寸
    let jitterX = random(-12, 12);
    let jitterY = random(-12, 12);
    let px = x * scaleFactor + jitterX;
    let py = y * scaleFactor + jitterY;

    let hueShift = map(noise(px * 0.005, py * 0.005), 0, 1, 0, 1);
    let c = lerpColor(color("#ffd2dc"), color("#ff3460"), hueShift);
    let dia = random(18, 36);

    fill(red(c), green(c), blue(c), 180);
    ellipse(px, py, dia, dia);
  }

  // 外围轻盈粒子，增加呼吸感
  for (let i = 0; i < 1500; i++) {
    let angle = random(TWO_PI);
    let radius = random(540, 760);
    let px = cos(angle) * radius + random(-10, 10);
    let py = sin(angle) * radius + random(-10, 10);

    let c = lerpColor(color("#ffe8ef"), color("#ff8fa3"), random());
    let dia = random(6, 14);
    fill(red(c), green(c), blue(c), 120);
    ellipse(px, py, dia, dia);
  }
}

function drawGradient() {
  let c1 = color("#ffb3c1");
  let c2 = color("#ff5f7e");
  for (let y = 0; y <= height; y++) {
    let inter = map(y, 0, height, 0, 1);
    stroke(lerpColor(c1, c2, inter));
    line(0, y, width, y);
  }
}

// p5.js 1.11 – 1600 × 2000 static sketch
function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  drawGradientBackground();
  drawHearts();
  drawLightSwirl();
}

function drawGradientBackground() {
  for (let y = 0; y < height; y++) {
    let inter = y / height;
    let c = lerpColor(color(255, 105, 150), color(70, 30, 180), inter);
    stroke(c);
    line(0, y, width, y);
  }
}

function drawHeart(cx, cy, scaleFactor, col, alphaVal) {
  push();
  translate(cx, cy);
  scale(scaleFactor);
  fill(red(col), green(col), blue(col), alphaVal);
  noStroke();
  beginShape();
  for (let a = 0; a < TWO_PI; a += 0.05) {
    let x = 16 * pow(sin(a), 3);
    let y = -(
      13 * cos(a) -
      5 * cos(2 * a) -
      2 * cos(3 * a) -
      cos(4 * a)
    );
    vertex(x, y);
  }
  endShape(CLOSE);
  pop();
}

function drawHearts() {
  drawHeart(width * 0.4, height * 0.45, 20, color(255, 70, 120), 220);
  drawHeart(width * 0.6, height * 0.55, 18, color(255, 200, 220), 200);
}

function drawLightSwirl() {
  noStroke();
  for (let t = 0; t < 10 * PI; t += 0.05) {
    let r = map(t, 0, 10 * PI, 20, 800);
    let angle = t + noise(t) * 0.5;
    let x = width / 2 + r * cos(angle);
    let y = height / 2 + r * sin(angle);
    let sz = map(r, 20, 800, 8, 1);
    fill(255, 240, 250, 150);
    ellipse(x, y, sz, sz);
