    let ang = random(TWO_PI);
    let rad = pow(random(), 0.4) * maxR;      // 中心密集
    let x = rad * cos(ang);
    let y = rad * sin(ang);

    let sz = map(pow(random(), 2), 0, 1, 30, 320);
    let h = map(ang, 0, TWO_PI, 0, 360);      // 角度映射到全色环
    let s = map(rad, 0, maxR, 85, 15);        // 越远越淡
    let b = map(rad, 0, maxR, 100, 65);
    fill(h, s, b, 18);
