      let n = noise(k * 0.3, t * 0.02);
      let rr = baseR + n * 220 + t * 0.25;   // 渐渐舒展
      vertex(rr * cos(ang), rr * sin(ang));
    }
    endShape();
  }

  // 3. 中央辉光——爱的核心
