  colorMode(HSB, 360, 100, 100, 100);
  background(230, 30, 5);          // 深色背景
  noStroke();
  translate(width / 2, height / 2);

  blendMode(ADD);                  // 颜色相加制造光感
  const total = 800;
  for (let i = 0; i < total; i++) {
    let t = i / total;
    let a = t * TAU * 6 + noise(t * 3) * PI;          // 螺旋角度并带噪声
    let r = lerp(60, 820, t) + noise(t * 4) * 200;    // 半径
    let x = cos(a) * r;
    let y = sin(a) * r;
    let s = lerp(200, 20, t) + noise(t * 5) * 30;     // 心形大小
    let h = (360 * t + random(-20, 20)) % 360;        // 色相随位置渐变
    fill(h, 80, 90, 20);                              // 低透明度
    heart(x, y, s, a + PI / 2);
  }

  // 朦胧光晕
  blendMode(SOFT_LIGHT);
  for (let i = 0; i < 300; i++) {
    fill(random(0, 360), 30, 100, 8);
    ellipse(random(-width / 2, width / 2),
            random(-height / 2, height / 2),
