function heart(px, py, size, rot) {
  push();
  translate(px, py);
  rotate(rot);
  beginShape();
  vertex(0, -size * 0.5);
  bezierVertex(size * 0.5, -size * 0.8,
               size * 0.9, -size * 0.1,
               0, size);
  bezierVertex(-size * 0.9, -size * 0.1,
               -size * 0.5, -size * 0.8,
               0, -size * 0.5);
  endShape(CLOSE);
  pop();
}

