}

function draw() {
  background(0, 0, 10);
  translate(width / 2, height / 2);

  // Radial glow
  let maxR = dist(0, 0, width / 2, height / 2) * 1.05;
  for (let i = 350; i >= 0; i--) {
    let t = i / 350;
    let r = t * maxR;
    let h = (340 + t * 80) % 360;          // 从玫瑰粉过渡到金橙
    let s = 40 + 40 * (1 - t);
    let b = 60 + 40 * (1 - t);
    let a = 60 + 40 * (1 - t);
    fill(h, s, b, a);
    noStroke();
    ellipse(0, 0, r * 2, r * 2);
  }

  // Floating translucent blobs
  let blobCount = 800;
  for (let i = 0; i < blobCount; i++) {
    let ang = random(TWO_PI);
    let distFactor = pow(random(1), 1.8) * maxR * 0.6;
    let x = cos(ang) * distFactor;
    let y = sin(ang) * distFactor;
    let sz = random(30, 180);

    let warm = random() < 0.5;
    let h = warm ? random(330, 360) : random(0, 50);
    let s = random(30, 80);
    let b = random(80, 100);
    let a = random(20, 60);
    fill(h, s, b, a);
    noStroke();
    ellipse(x, y, sz, sz);
  }

  // Connecting curves
  strokeCap(ROUND);
  let curveCount = 120;
  for (let i = 0; i < curveCount; i++) {
    let p1 = randomPoint(maxR * 0.4);
    let p2 = randomPoint(maxR * 0.4);
    let ctrl1 = p1.copy().add(random(-200, 200), random(-200, 200));
    let ctrl2 = p2.copy().add(random(-200, 200), random(-200, 200));

    let h = random(340, 30 + 360) % 360;
    let s = random(40, 80);
    let b = random(70, 100);
    let a = random(30, 80);
    stroke(h, s, b, a);
    strokeWeight(random(1, 6));
    noFill();
    bezier(p1.x, p1.y, ctrl1.x, ctrl1.y, ctrl2.x, ctrl2.y, p2.x, p2.y);
  }
}

function randomPoint(r) {
  let ang = random(TWO_PI);
  let d = sqrt(random()) * r;
  return createVector(cos(ang) * d, sin(ang) * d);
}

