  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
  colorMode(HSB, 360, 100, 100, 100);
  drawScene();
}

function drawScene() {
  // background gradient (warm-to-cool)
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let c = lerpColor(color(340, 40, 100), color(210, 30, 90), t);
    stroke(c);
    line(0, y, width, y);
  }

  noStroke();
  translate(width / 2, height / 2);

  // central glow
  for (let r = 600; r > 0; r -= 4) {
    let inter = r / 600;
    fill((340 + inter * 60) % 360, 30, 100, 12);
    ellipse(0, 0, r * 2, r * 2);
  }

  // spiral pulses
  for (let i = 0; i < 600; i++) {
    let a = i * 0.42;
    let rad = 30 + i * 2.2;
    let x = cos(a) * rad + (noise(i * 0.05) - 0.5) * 80;
    let y = sin(a) * rad + (noise(i * 0.05 + 5) - 0.5) * 80;
    let s = map(sin(i * 0.15), -1, 1, 20, 120);
    let h = (340 + i * 0.6) % 360;
    fill(h, 50, 100, 25);
    ellipse(x, y, s, s);
  }

  // translucent ribbons
  let layers = 90;
  for (let j = 0; j < layers; j++) {
    let alp = map(j, 0, layers, 6, 15);
    let h = (210 + j * 1.5) % 360;
    fill(h, 40, 100, alp);
    beginShape();
    for (let k = 0; k <= 360; k += 8) {
      let ang = radians(k);
      let base = 450 + j * 6;
      let r = base + noise(k * 0.02, j * 0.1) * 120;
      vertex(cos(ang) * r, sin(ang) * r);
    }
    endShape(CLOSE);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
  draw();
}

function draw() {
  // Deep dark background
  background(3, 2, 6);

  // Subtle background texture - dark painterly marks
  for (let i = 0; i < 80000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.003, y * 0.003);
    let n2 = noise(x * 0.01, y * 0.01, 100);
    if (n > 0.4 && n2 > 0.5) {
      let r = 5 + n * 15;
      let g = 3 + n * 10;
      let b = 10 + n * 20;
      fill(r, g, b, random(5, 15));
      noStroke();
      let sz = random(2, 8);
      ellipse(x, y, sz, sz * random(0.5, 1.5));
    }
  }

  // Subtle dark blue/purple washes
  for (let i = 0; i < 30; i++) {
    let cx = random(width);
    let cy = random(height);
    let rad = random(200, 600);
    for (let r = rad; r > 0; r -= 3) {
      let alpha = map(r, 0, rad, 3, 0);
      fill(15, 8, 30, alpha);
      ellipse(cx, cy, r * 2, r * 2 * random(0.7, 1.3));
    }
  }

  // Ground/earth tones at the bottom
  for (let i = 0; i < 40000; i++) {
    let x = random(width);
    let y = random(height * 0.65, height);
    let falloff = map(y, height * 0.65, height, 0, 1);
    let n = noise(x * 0.005, y * 0.005, 50);
    if (n > 0.35) {
      let r = 15 + n * 30 * falloff;
      let g = 8 + n * 15 * falloff;
      let b = 5 + n * 10 * falloff;
      fill(r, g, b, random(8, 20));
      noStroke();
      let sz = random(3, 10);
      ellipse(x, y, sz, sz * random(0.4, 1.0));
    }
  }

  // The figure - a reclining form in the lower center
  // Define figure as a series of body regions
  let figCenterX = width * 0.5;
  let figCenterY = height * 0.68;

  // Warm glow emanating from figure
  for (let r = 500; r > 0; r -= 4) {
    let alpha = map(r, 0, 500, 8, 0);
    fill(40, 25, 10, alpha);
    ellipse(figCenterX, figCenterY, r * 2.5, r * 0.8);
  }

  // Draw the reclining figure with painterly strokes
  // Body is horizontal, head to the left, legs to the right
  let bodyParts = [
    // head
    {x: -280, y: -10, w: 70, h: 65, r: 180, g: 140, b: 100, density: 1.0},
    // neck
    {x: -220, y: 5, w: 40, h: 35, r: 170, g: 130, b: 90, density: 0.9},
    // torso
    {x: -120, y: 10, w: 200, h: 80, r: 160, g: 120, b: 85, density: 1.0},
    // chest area
    {x: -80, y: -15, w: 120, h: 60, r: 175, g: 135, b: 100, density: 0.8},
    // hips
    {x: 60, y: 15, w: 100, h: 70, r: 150, g: 110, b: 80, density: 0.9},
    // upper legs
    {x: 160, y: 20, w: 140, h: 50, r: 140, g: 100, b: 75, density: 0.7},
    // lower legs
    {x: 300, y: 25, w: 130, h: 40, r: 130, g: 95, b: 70, density: 0.5},
    // feet
    {x: 420, y: 30, w: 50, h: 30, r: 120, g: 85, b: 65, density: 0.3},
    // arm near
    {x: -50, y: 50, w: 150, h: 30, r: 155, g: 115, b: 82, density: 0.7},
    // arm far (above body)
    {x: -100, y: -40, w: 130, h: 25, r: 145, g: 108, b: 78, density: 0.5},
  ];

  // Render each body part with many small strokes
  for (let part of bodyParts) {
    let count = part.w * part.h * 0.8 * part.density;
    for (let i = 0; i < count; i++) {
      let angle = random(TWO_PI);
      let dist = random(1);
      dist = dist * dist; // concentrate toward center
      let px = figCenterX + part.x + cos(angle) * dist * part.w * 0.5 + random(-5, 5);
      let py = figCenterY + part.y + sin(angle) * dist * part.h * 0.5 + random(-3, 3);

      let n = noise(px * 0.02, py * 0.02, 200);
      let vary = 40;
      let r = part.r + random(-vary, vary) * n;
      let g = part.g + random(-vary, vary) * n * 0.7;
      let b = part.b + random(-vary, vary) * n * 0.5;

      // Fragmentation - upper parts of figure dissolve more
      let dissolve = map(py, figCenterY + 40, figCenterY - 60, 0, 1);
      dissolve = constrain(dissolve, 0, 1);

      // Distance from right edge also dissolves
      let rightDissolve = map(px, figCenterX + 200, figCenterX + 470, 0, 1);
      rightDissolve = constrain(rightDissolve, 0, 1);

      let totalDissolve = max(dissolve * 0.6, rightDissolve * 0.8);

      if (random() > totalDissolve * 0.7) {
        let alpha = random(40, 120) * (1 - totalDissolve * 0.5);
        fill(r, g, b, alpha);
        noStroke();
        let sz = random(2, 6);
        let elongation = random(0.3, 1.5);
        push();
        translate(px, py);
        rotate(random(-0.5, 0.5) + atan2(py - figCenterY, px - figCenterX) * 0.3);
        ellipse(0, 0, sz, sz * elongation);
        pop();
      }
    }
  }

  // Shadow/dark underside of figure
  for (let i = 0; i < 15000; i++) {
    let x = figCenterX + random(-300, 450);
    let y = figCenterY + random(20, 80);
    let n = noise(x * 0.01, y * 0.01, 300);
    if (n > 0.4) {
      fill(5, 2, 8, random(20, 50));
      noStroke();
      ellipse(x, y, random(3, 12), random(2, 6));
    }
  }

  // Rising particles - the soul/unraveling
  // These emanate from the figure and float upward
  let particles = [];

  // Generate particles
  for (let i = 0; i < 5000; i++) {
    let originX = figCenterX + random(-250, 400);
    let originY = figCenterY + random(-50, 40);

    // How far the particle has traveled upward
    let travel = random(0, 1);
    travel = travel * travel * travel; // bias toward short travel

    let riseAmount = travel * (height * 0.6);
    let drift = (noise(originX * 0.005, originY * 0.005) - 0.5) * riseAmount * 0.8;
    drift += sin(originX * 0.01) * riseAmount * 0.15;

    let px = originX + drift;
    let py = originY - riseAmount;

    // Only keep if within canvas
    if (py < 10 || py > height || px < 10 || px > width) continue;

    // Size decreases with height
    let sz = map(travel, 0, 1, 5, 1.5) * random(0.5, 1.5);

    // Color transitions: warm near body -> cool -> white -> fade
    let r, g, b, a;
    if (travel < 0.15) {
      // Very warm - amber/gold
      r = lerp(200, 255, travel / 0.15);
      g = lerp(120, 180, travel / 0.15);
      b = lerp(40, 60, travel / 0.15);
      a = random(80, 160);
    } else if (travel < 0.4) {
      // Transitioning - pale warm to cool
      let t = (travel - 0.15) / 0.25;
      r = lerp(255, 150, t);
      g = lerp(180, 160, t);
      b = lerp(60, 200, t);
      a = random(60, 140);
    } else if (travel < 0.7) {
      // Cool - pale blue/white
      let t = (travel - 0.4) / 0.3;
      r = lerp(150, 200, t);
      g = lerp(160, 210, t);
      b = lerp(200, 240, t);
      a = random(40, 100);
    } else {
      // Fading into nothing
      let t = (travel - 0.7) / 0.3;
      r = lerp(200, 180, t);
      g = lerp(210, 190, t);
      b = lerp(240, 220, t);
      a = lerp(80, 0, t * t);
    }

    particles.push({x: px, y: py, sz: sz, r: r, g: g, b: b, a: a, travel: travel});
  }

  // Sort by travel so further ones draw first (behind)
  particles.sort((a, b) => b.travel - a.travel);

  // Draw particles
  for (let p of particles) {
    // Glow
    if (p.a > 30 && p.sz > 2) {
      fill(p.r, p.g, p.b, p.a * 0.15);
      noStroke();
      ellipse(p.x, p.y, p.sz * 5, p.sz * 5);
    }

    // Core
    fill(p.r, p.g, p.b, p.a);
    noStroke();
    ellipse(p.x, p.y, p.sz, p.sz);

    // Bright center
    if (p.a > 50) {
      fill(255, 255, 240, p.a * 0.5);
      ellipse(p.x, p.y, p.sz * 0.4, p.sz * 0.4);
    }
  }

  // Wispy trails connecting some particles
  noFill();
  for (let i = 0; i < 200; i++) {
    let p = particles[floor(random(particles.length))];
    if (!p || p.travel < 0.1 || p.travel > 0.6) continue;

    stroke(p.r, p.g, p.b, p.a * 0.2);
    strokeWeight(random(0.3, 1.2));
    beginShape();
    let cx = p.x;
    let cy = p.y;
    for (let j = 0; j < 5; j++) {
      curveVertex(cx, cy);
      cx += random(-15, 15);
      cy -= random(5, 20);
    }
    endShape();
  }

  // Final overlay - subtle vignette
  for (let i = 0; i < 50; i++) {
    let alpha = map(i, 0, 50, 0, 40);
    noFill();
    stroke(0, 0, 0, alpha);
    strokeWeight(40);
    let margin = i * 20;
    rect(-margin, -margin, width + margin * 2, height + margin * 2);
  }

  // Soft light on the figure's chest area - last warmth
  for (let r = 150; r > 0; r -= 2) {
    let alpha = map(r, 0, 150, 5, 0);
    fill(255, 200, 100, alpha);
    noStroke();
    ellipse(figCenterX - 80, figCenterY - 5, r * 1.5, r * 0.6);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function draw() {
  // Background gradient - deep void
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(5, 15, t * 0.5);
    let g = lerp(5, 10, t * 0.3);
    let b = lerp(20, 35, t * 0.7 + 0.3 * sin(t * PI));
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Subtle radial glow behind figure area
  noStroke();
  for (let r = 500; r > 0; r -= 2) {
    let alpha = map(r, 0, 500, 30, 0);
    fill(40, 25, 50, alpha);
    ellipse(800, 1350, r * 3, r * 1.8);
  }

  // Figure - reclining form built from painterly strokes
  // Body center around y=1350, spanning horizontally

  // Base body shape layers
  let bodyColors = [
    [139, 90, 70],   // dark sienna
    [160, 100, 75],  // warm brown
    [180, 120, 90],  // light sienna
    [200, 145, 115], // flesh
    [210, 160, 130], // light flesh
    [170, 110, 85],  // mid tone
    [145, 85, 65],   // shadow
  ];

  // Torso and body mass - large organic shapes
  for (let i = 0; i < 3000; i++) {
    let bx = random(350, 1150);
    // Body profile - wider in middle (torso), narrower at head and feet
    let normalizedX = map(bx, 350, 1150, 0, 1);
    let bodyWidth = 180 * sin(normalizedX * PI * 0.85 + 0.2);

    // Head bump on the left
    if (normalizedX < 0.15) {
      bodyWidth = lerp(100, 140, normalizedX / 0.15);
    }

    let centerY = 1370 + noise(bx * 0.005) * 40 - 20;
    let by = centerY + random(-bodyWidth, bodyWidth) * (0.3 + 0.7 * noise(bx * 0.01, i * 0.001));

    // Only within body bounds
    let distFromCenter = abs(by - centerY);
    if (distFromCenter > bodyWidth * 1.2) continue;

    let col = random(bodyColors);
    let alpha = map(distFromCenter, 0, bodyWidth * 1.2, 120, 15);
    alpha *= map(by, centerY - bodyWidth, centerY + bodyWidth, 0.7, 1.0);

    // Add slight warmth variation
    col[0] += random(-15, 15);
    col[1] += random(-10, 10);
    col[2] += random(-10, 10);

    fill(col[0], col[1], col[2], alpha);
    noStroke();

    let sw = random(8, 35);
    let sh = random(4, 18);
    push();
    translate(bx, by);
    rotate(random(-0.5, 0.5) + noise(bx * 0.01) * 0.5);
    ellipse(0, 0, sw, sh);
    pop();
  }

  // Head - more defined round form on left side
  for (let i = 0; i < 800; i++) {
    let angle = random(TWO_PI);
    let r = random(0, 85);
    let hx = 420 + cos(angle) * r * 0.9;
    let hy = 1330 + sin(angle) * r * 1.0;

    let col = random(bodyColors);
    col[0] += 10;
    col[1] -= 5;
    let alpha = map(r, 0, 85, 140, 20);

    fill(col[0], col[1], col[2], alpha);
    let sw = random(6, 22);
    push();
    translate(hx, hy);
    rotate(angle + random(-0.3, 0.3));
    ellipse(0, 0, sw, sw * 0.5);
    pop();
  }

  // Subtle highlight on the upper body - light source from above
  for (let i = 0; i < 400; i++) {
    let bx = random(450, 900);
    let normalizedX = map(bx, 450, 900, 0, 1);
    let bodyWidth = 140 * sin(normalizedX * PI);
    let centerY = 1350;
    let by = centerY - random(0, bodyWidth * 0.4);

    fill(230, 200, 175, random(15, 40));
    let sw = random(10, 25);
    push();
    translate(bx, by);
    rotate(random(-0.4, 0.4));
    ellipse(0, 0, sw, sw * 0.3);
    pop();
  }

  // Arm draped - suggested form
  for (let i = 0; i < 500; i++) {
    let t = random(1);
    let ax = lerp(650, 850, t) + random(-20, 20);
    let ay = lerp(1300, 1450, t) + random(-15, 15) + t * 30;

    let col = random(bodyColors);
    col[0] -= 10;
    col[1] -= 10;
    fill(col[0], col[1], col[2], random(30, 90));
    push();
    translate(ax, ay);
    rotate(lerp(-0.3, 0.8, t));
    ellipse(0, 0, random(8, 20), random(4, 10));
    pop();
  }

  // === PARTICLES - the exhale/dispersal ===
  // Particles emanate upward from the body

  // Define particle origins across the body surface
  for (let p = 0; p < 12000; p++) {
    // Origin on body
    let ox = random(380, 1120);
    let normalizedOX = map(ox, 380, 1120, 0, 1);
    let bodyW = 160 * sin(normalizedOX * PI * 0.85 + 0.2);
    if (normalizedOX < 0.15) bodyW = lerp(90, 130, normalizedOX / 0.15);

    let oy = 1370 + random(-bodyW * 0.5, bodyW * 0.3);

    // How far does this particle travel?
    let travel = random(20, 900);
    let travelFactor = travel / 900;

    // Particles drift upward with noise-based wandering
    let steps = floor(travel / 3);
    let px = ox;
    let py = oy;
    let prevX = px;
    let prevY = py;

    let particleHue = random(1); // 0-1 determines color family
    let pSize = random(1.5, 6) * (1 - travelFactor * 0.5);

    // Draw the particle trail as dots
    let drawEvery = max(1, floor(random(2, 6)));

    for (let s = 0; s < steps; s++) {
      let t = s / steps;
      let noiseScale = 0.003;
      let nAngle = noise(px * noiseScale, py * noiseScale, p * 0.001) * TWO_PI * 2;

      // General upward drift with wandering
      let dx = cos(nAngle) * 3 + random(-0.5, 0.5);
      let dy = -3 + sin(nAngle) * 1.5 + random(-0.3, 0.3);

      prevX = px;
      prevY = py;
      px += dx;
      py += dy;

      if (s % drawEvery !== 0) continue;

      // Color: near body = warm flesh/amber, far = gold/white/lavender
      let r, g, b, a;

      if (particleHue < 0.3) {
        // Gold/amber particles
        r = lerp(210, 255, t);
        g = lerp(160, 220, t);
        b = lerp(80, 160, t);
      } else if (particleHue < 0.55) {
        // Warm white/cream
        r = lerp(220, 255, t);
        g = lerp(190, 245, t);
        b = lerp(170, 235, t);
      } else if (particleHue < 0.75) {
        // Soft lavender
        r = lerp(180, 210, t);
        g = lerp(140, 180, t);
        b = lerp(180, 230, t);
      } else if (particleHue < 0.9) {
        // Rose/pink
        r = lerp(200, 240, t);
        g = lerp(120, 170, t);
        b = lerp(130, 180, t);
      } else {
        // Pale green - life returning
        r = lerp(140, 180, t);
        g = lerp(170, 220, t);
        b = lerp(120, 170, t);
      }

      // Alpha: strong near body, fading as it rises
      let distFromBody = abs(py - 1370);
      a = map(distFromBody, 0, 800, 180, 8);
      a *= map(t, 0, 1, 1, 0.2);
      a *= random(0.5, 1.2);
      a = constrain(a, 2, 180);

      fill(r, g, b, a);
      noStroke();

      // Slight size variation and shape
      let sz = pSize * (1 - t * 0.4) * random(0.7, 1.3);
      push();
      translate(px, py);
      rotate(nAngle);
      ellipse(0, 0, sz, sz * random(0.5, 1.2));
      pop();
    }
  }

  // Larger, more defined "seed" particles scattered throughout
  for (let i = 0; i < 200; i++) {
    let sx = random(100, 1500);
    let sy = random(100, 1300);

    // Density increases toward body
    let distFromBody = abs(sy - 1370);
    if (random() > map(distFromBody, 0, 1200, 1, 0.1)) continue;

    let size = random(3, 12);
    let alpha = map(distFromBody, 0, 1200, 150, 20);

    let colorChoice = random();
    if (colorChoice < 0.4) {
      fill(255, 220, 150, alpha * random(0.3, 1));
    } else if (colorChoice < 0.7) {
      fill(230, 200, 240, alpha * random(0.3, 1));
    } else {
      fill(255, 240, 230, alpha * random(0.3, 1));
    }

    noStroke();
    push();
    translate(sx, sy);
    rotate(random(TWO_PI));
    // Petal/seed shape
    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.3) {
      let r = size * (1 + 0.3 * sin(a * 2 + random(0.5)));
      vertex(cos(a) * r, sin(a) * r * 0.6);
    }
    endShape(CLOSE);
    pop();
  }

  // Ambient dust/atmosphere - very subtle
  for (let i = 0; i < 3000; i++) {
    let dx = random(0, width);
    let dy = random(0, height);
    let da = random(3, 15);
    fill(200, 190, 220, da);
    noStroke();
    circle(dx, dy, random(0.5, 2));
  }

  // Soft glow where particles are densest (just above body)
  for (let r = 300; r > 0; r -= 3) {
    let alpha = map(r, 0, 300, 12, 0);
    fill(180, 150, 120, alpha);
    noStroke();
    ellipse(750, 1200, r * 2.5, r * 1.2);
  }

  // Very subtle dark vignette
  for (let i = 0; i < 40; i++) {
    let t = i / 40;
    noFill();
    stroke(0, 0, 5, map(t, 0, 1, 30, 0));
    strokeWeight(30);
    rect(0, 0, width, height);
    // Scale rect inward
    let m = i * 15;
    rect(m, m, width - 2 * m, height - 2 * m);
  }

  // Final atmospheric wash - very thin layers
  for (let i = 0; i < 5; i++) {
    let gy = random(0, height);
    let gh = random(200, 600);
    for (let y = gy; y < gy + gh; y++) {
      let t = (y - gy) / gh;
      let a = sin(t * PI) * 5;
      stroke(60, 40, 80, a);
      line(0, y, width, y);
    }
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep background gradient
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(5, 12, t);
    let g = lerp(8, 18, t);
    let b = lerp(25, 35, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Subtle cosmic dust in background
  for (let i = 0; i < 3000; i++) {
    let x = random(width);
    let y = random(height * 0.7);
    let n = noise(x * 0.003, y * 0.003);
    if (n > 0.55) {
      let alpha = map(n, 0.55, 0.8, 5, 30);
      let sz = random(0.5, 2);
      fill(180, 200, 255, alpha);
      noStroke();
      ellipse(x, y, sz, sz);
    }
  }

  // Ground plane - dark earth
  for (let y = height * 0.78; y < height; y++) {
    let t = (y - height * 0.78) / (height * 0.22);
    for (let x = 0; x < width; x += 3) {
      let n = noise(x * 0.005, y * 0.008);
      let r = lerp(15, 25, t) + n * 10;
      let g = lerp(12, 18, t) + n * 8;
      let b = lerp(20, 15, t) + n * 5;
      fill(r, g, b, 200);
      noStroke();
      rect(x, y, 4, 2);
    }
  }

  // Central glow behind figure
  let glowX = width * 0.5;
  let glowY = height * 0.65;
  for (let r = 400; r > 0; r -= 2) {
    let alpha = map(r, 0, 400, 40, 0);
    fill(200, 150, 50, alpha * 0.3);
    noStroke();
    ellipse(glowX, glowY, r * 2, r * 1.5);
  }

  // Figure silhouette - built from dense particles
  // Figure center and dimensions
  let figX = width * 0.5;
  let figBaseY = height * 0.88;
  let figTopY = height * 0.42;
  let figHeight = figBaseY - figTopY;

  // Draw figure body with particles
  for (let i = 0; i < 15000; i++) {
    let t = random(); // 0 = top, 1 = bottom
    let yPos = lerp(figTopY, figBaseY, t);

    // Width of figure at this height (body shape)
    let bodyWidth;
    if (t < 0.15) {
      // Head
      bodyWidth = map(t, 0, 0.15, 15, 40);
    } else if (t < 0.2) {
      // Neck
      bodyWidth = map(t, 0.15, 0.2, 40, 20);
    } else if (t < 0.5) {
      // Torso
      bodyWidth = map(t, 0.2, 0.5, 20, 70);
    } else if (t < 0.55) {
      // Waist
      bodyWidth = map(t, 0.5, 0.55, 70, 45);
    } else {
      // Legs
      bodyWidth = map(t, 0.55, 1.0, 45, 30);
    }

    let xOffset = randomGaussian() * bodyWidth * 0.5;
    let xPos = figX + xOffset;

    // Dispersion: particles near top scatter more
    let disperseAmount = pow(1 - t, 2.5) * 300;
    let disperseX = randomGaussian() * disperseAmount;
    let disperseY = -abs(randomGaussian()) * disperseAmount * 0.7;

    xPos += disperseX;
    yPos += disperseY;

    // Color based on position
    let disperseFactor = 1 - t;
    let r, g, b, alpha;

    if (disperseFactor > 0.7) {
      // Dispersing particles - golden/white light
      r = lerp(255, 255, random());
      g = lerp(180, 220, random());
      b = lerp(50, 120, random());
      alpha = map(disperseFactor, 0.7, 1.0, 180, 60);
    } else if (disperseFactor > 0.4) {
      // Transition zone - warm amber
      r = lerp(180, 220, random());
      g = lerp(120, 160, random());
      b = lerp(60, 90, random());
      alpha = map(disperseFactor, 0.4, 0.7, 220, 150);
    } else {
      // Solid body - dark with slight warmth
      r = lerp(30, 60, random());
      g = lerp(25, 45, random());
      b = lerp(40, 60, random());
      alpha = map(disperseFactor, 0, 0.4, 250, 200);
    }

    let sz = random(1.5, 4) * (1 + disperseFactor * 0.5);
    fill(r, g, b, alpha);
    noStroke();
    ellipse(xPos, yPos, sz, sz);
  }

  // Rising particles / embers from the dissolution
  for (let i = 0; i < 2000; i++) {
    let startT = random(0, 0.5);
    let startPosY = lerp(figTopY, figBaseY, startT);
    let startPosX = figX + randomGaussian() * 50;

    // Particle rises and drifts
    let rise = random(50, 600) * (1 - startT);
    let drift = randomGaussian() * rise * 0.5;

    let px = startPosX + drift;
    let py = startPosY - rise;

    if (py < 0) continue;

    let distFromCenter = abs(drift) / 300;
    let alpha = map(rise, 50, 600, 150, 10) * (1 - distFromCenter * 0.5);
    let sz = random(1, 3.5) * map(rise, 50, 600, 1, 0.3);

    let colorChoice = random();
    if (colorChoice < 0.4) {
      fill(255, 200, 80, alpha); // gold
    } else if (colorChoice < 0.7) {
      fill(255, 240, 200, alpha); // warm white
    } else {
      fill(180, 200, 255, alpha * 0.7); // cool blue
    }
    noStroke();
    ellipse(px, py, sz, sz);
  }

  // Flowing streams of particles (noise-based) showing the soul's path upward
  for (let s = 0; s < 40; s++) {
    let sx = figX + randomGaussian() * 60;
    let sy = lerp(figTopY, figTopY + figHeight * 0.3, random());
    let streamAlpha = random(20, 60);

    beginShape();
    noFill();
    stroke(220, 180, 100, streamAlpha);
    strokeWeight(random(0.5, 1.5));
    for (let step = 0; step < 80; step++) {
      let n = noise(sx * 0.003 + s, sy * 0.003, step * 0.05);
      sx += (n - 0.5) * 15;
      sy -= random(3, 8);
      vertex(sx, sy);
    }
    endShape();
  }

  // Scattered light motes across upper canvas
  for (let i = 0; i < 500; i++) {
    let x = random(width);
    let y = random(height * 0.5);
    let n = noise(x * 0.002 + 10, y * 0.002 + 10);
    if (n > 0.6) {
      let alpha = map(n, 0.6, 0.85, 20, 80);
      let sz = random(1, 4);
      fill(255, 230, 180, alpha);
      noStroke();
      ellipse(x, y, sz, sz);
    }
  }

  // Subtle vignette
  for (let i = 0; i < 80; i++) {
    let alpha = map(i, 0, 80, 0, 150);
    noFill();
    stroke(0, 0, 5, alpha);
    strokeWeight(20);
    rect(i * 10, i * 12, width - i * 20, height - i * 24);
  }

  // Final overlay - very subtle warm tone at center bottom
  for (let r = 300; r > 0; r -= 3) {
    let alpha = map(r, 0, 300, 15, 0);
    fill(200, 120, 40, alpha);
    noStroke();
    ellipse(glowX, figBaseY - 50, r * 2, r * 1.2);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  pixelDensity(1);
}

function draw() {
  // Sky gradient
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(8, 20, pow(t, 0.7));
    let g = lerp(5, 15, pow(t, 0.5));
    let b = lerp(30, 22, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Subtle moon glow upper right
  for (let i = 0; i < 800; i++) {
    let angle = random(TWO_PI);
    let rad = random(0, 400);
    let x = 1100 + cos(angle) * rad;
    let y = 300 + sin(angle) * rad;
    let alpha = map(rad, 0, 400, 25, 0);
    noStroke();
    fill(80, 90, 120, alpha);
    ellipse(x, y, random(20, 60), random(20, 60));
  }

  // Moon
  noStroke();
  fill(180, 190, 210, 60);
  ellipse(1100, 300, 80, 80);
  fill(200, 210, 230, 80);
  ellipse(1100, 300, 50, 50);
  fill(220, 225, 240, 100);
  ellipse(1100, 300, 30, 30);

  // Distant treeline
  for (let x = 0; x < width; x += 3) {
    let h = noise(x * 0.003) * 120 + noise(x * 0.01) * 40;
    let baseY = 1350;
    for (let y = baseY - h; y < baseY; y += 2) {
      let t = (baseY - y) / h;
      fill(10 + t * 5, 12 + t * 3, 18 + t * 5, 200);
      rect(x, y, 4, 3);
    }
  }

  // Water/ground reflection
  for (let y = 1350; y < 1600; y++) {
    let t = (y - 1350) / 250;
    for (let x = 0; x < width; x += 4) {
      let n = noise(x * 0.005, y * 0.01);
      let r = lerp(12, 18, t) + n * 5;
      let g = lerp(14, 16, t) + n * 3;
      let b = lerp(25, 20, t) + n * 8;
      fill(r, g, b, 150);
      noStroke();
      rect(x, y, 5, 2);
    }
  }

  // Ground plane
  for (let y = 1550; y < height; y++) {
    let t = (y - 1550) / (height - 1550);
    for (let x = 0; x < width; x += 3) {
      let n = noise(x * 0.008, y * 0.008);
      let r = lerp(18, 25, t) + n * 8;
      let g = lerp(15, 18, t) + n * 5;
      let b = lerp(12, 10, t) + n * 3;
      fill(r, g, b);
      noStroke();
      rect(x, y, 4, 3);
    }
  }

  // Dead grass in foreground
  for (let i = 0; i < 3000; i++) {
    let x = random(width);
    let baseY = random(1600, height);
    let h = random(15, 60);
    let lean = random(-15, 15);
    stroke(30 + random(15), 25 + random(10), 15 + random(8), 150);
    strokeWeight(random(0.5, 1.5));
    let segments = 5;
    noFill();
    beginShape();
    for (let s = 0; s <= segments; s++) {
      let t = s / segments;
      let px = x + lean * t * t + noise(x * 0.01, s) * 5;
      let py = baseY - h * t;
      curveVertex(px, py);
    }
    endShape();
  }

  // Withered flowers
  for (let i = 0; i < 40; i++) {
    let x = random(100, width - 100);
    let baseY = random(1620, height - 50);
    let stemH = random(40, 100);
    // Stem
    stroke(35, 30, 20, 180);
    strokeWeight(1.5);
    let lean = random(-20, 20);
    line(x, baseY, x + lean * 0.5, baseY - stemH);
    // Drooping flower head
    noStroke();
    let fx = x + lean * 0.5;
    let fy = baseY - stemH;
    for (let p = 0; p < 5; p++) {
      let angle = random(TWO_PI);
      let r = random(3, 8);
      fill(50 + random(20), 30 + random(15), 25 + random(10), 150);
      ellipse(fx + cos(angle) * r, fy + sin(angle) * r + 3, random(4, 8), random(3, 6));
    }
  }

  // Figure - silhouette dissolving from top
  let figureX = 750;
  let figureBaseY = 1580;
  let figureTopY = 1100;
  let dissolveY = 1250; // Above this, figure dissolves

  // Lower body (solid)
  noStroke();
  for (let y = figureBaseY; y > dissolveY; y -= 2) {
    let t = (figureBaseY - y) / (figureBaseY - dissolveY);
    let bodyWidth = lerp(60, 45, t);
    let n = noise(y * 0.05) * 8;
    // Body fill with subtle variation
    for (let x = figureX - bodyWidth / 2; x < figureX + bodyWidth / 2; x += 2) {
      let edge = abs(x - figureX) / (bodyWidth / 2);
      let shade = lerp(20, 12, edge) + noise(x * 0.05, y * 0.05) * 5;
      fill(shade, shade * 0.9, shade * 0.85, 240);
      rect(x, y, 3, 3);
    }
  }

  // Shoulders area
  for (let y = dissolveY; y > dissolveY - 50; y -= 2) {
    let t = (dissolveY - y) / 50;
    let bodyWidth = lerp(55, 70, t < 0.5 ? t * 2 : 1) * (1 - t * 0.3);
    for (let x = figureX - bodyWidth / 2; x < figureX + bodyWidth / 2; x += 2) {
      let edge = abs(x - figureX) / (bodyWidth / 2);
      let alpha = lerp(240, 100, t) * (1 - edge * 0.5);
      let shade = lerp(22, 14, edge) + noise(x * 0.05, y * 0.05) * 5;
      fill(shade, shade * 0.9, shade * 0.85, alpha);
      rect(x + noise(x, y) * t * 10, y + noise(y, x) * t * 5, 3, 3);
    }
  }

  // Head area (dissolving)
  for (let y = dissolveY - 50; y > figureTopY; y -= 2) {
    let t = (dissolveY - 50 - y) / (dissolveY - 50 - figureTopY);
    let headWidth = lerp(30, 25, t) * (1 - t * 0.7);
    let scatter = t * 80;
    for (let x = figureX - headWidth / 2; x < figureX + headWidth / 2; x += 3) {
      let alpha = lerp(150, 0, t);
      let shade = 18 + noise(x * 0.05, y * 0.05) * 5;
      fill(shade, shade * 0.9, shade * 0.85, alpha);
      let sx = x + (noise(x * 0.1, y * 0.1) - 0.5) * scatter;
      let sy = y + (noise(y * 0.1, x * 0.1) - 0.5) * scatter * 0.5;
      rect(sx, sy, random(2, 4), random(2, 4));
    }
  }

  // Particles rising from figure (soul/life force)
  for (let i = 0; i < 4000; i++) {
    let startY = random(figureTopY - 100, dissolveY + 50);
    let t = (dissolveY + 50 - startY) / (dissolveY + 50 - figureTopY + 100);
    let spread = t * 300 + 20;
    let x = figureX + (random() - 0.5) * spread;
    let rise = random(0, 500) * t;
    let y = startY - rise;

    if (y < 100) continue;

    let size = lerp(4, 1.5, t) * random(0.5, 1.5);
    let dist = abs(x - figureX);

    // Color transitions from warm amber near figure to cool silver far away
    let colorT = constrain(t + dist / 600, 0, 1);
    let r = lerp(200, 120, colorT) + random(-20, 20);
    let g = lerp(140, 130, colorT) + random(-15, 15);
    let b = lerp(50, 160, colorT) + random(-10, 10);
    let alpha = lerp(180, 30, colorT) * random(0.5, 1.2);

    noStroke();
    fill(r, g, b, alpha);
    ellipse(x + noise(i * 0.01) * 20, y, size, size * random(0.8, 1.3));

    // Glow for brighter particles
    if (random() < 0.1 && colorT < 0.5) {
      fill(r, g, b, alpha * 0.3);
      ellipse(x, y, size * 4, size * 4);
    }
  }

  // Additional atmospheric particles scattered across sky
  for (let i = 0; i < 500; i++) {
    let x = random(width);
    let y = random(100, 1300);
    let size = random(0.5, 2);
    fill(150, 160, 180, random(10, 40));
    noStroke();
    ellipse(x, y, size, size);
  }

  // Fog/mist layers
  for (let i = 0; i < 200; i++) {
    let x = random(-100, width + 100);
    let y = random(1300, 1600);
    let w = random(200, 600);
    let h = random(20, 60);
    fill(20, 22, 35, random(5, 15));
    noStroke();
    ellipse(x, y, w, h);
  }

  // Vignette
  for (let i = 0; i < 100; i++) {
    let t = i / 100;
    noFill();
    stroke(0, 0, 0, t * 3);
    strokeWeight(20);
    let margin = -i * 15;
    rect(margin, margin, width - margin * 2, height - margin * 2);
  }

  // Final overlay - subtle texture
  for (let i = 0; i < 20000; i++) {
    let x = random(width);
    let y = random(height);
    let v = random(255);
    fill(v, v, v, random(2, 6));
    noStroke();
    rect(x, y, 1, 1);
  }
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Dark background gradient
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(8, 3, t);
    let g = lerp(12, 6, t);
    let b = lerp(22, 14, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Subtle atmospheric noise texture
  noStroke();
  for (let i = 0; i < 80000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.003, y * 0.003);
    if (n > 0.52) {
      let a = map(n, 0.52, 0.7, 0, 12);
      fill(30, 40, 60, a);
      ellipse(x, y, random(1, 3));
    }
  }

  // Ground layer - dark earth with texture
  for (let y = 1500; y < height; y++) {
    let t = (y - 1500) / 500;
    for (let x = 0; x < width; x += 2) {
      let n = noise(x * 0.005, y * 0.008);
      let val = n * 20 * (1 - t * 0.3);
      if (random() < 0.3) {
        fill(val + 5, val + 3, val + 8, random(30, 80));
        rect(x, y, 2, 2);
      }
    }
  }

  // Tree trunk and branches using recursive noise-based structure
  drawTree();

  // Ground glow - warm light at the base
  for (let i = 0; i < 200; i++) {
    let x = width / 2 + randomGaussian() * 150;
    let y = 1500 + randomGaussian() * 30;
    let s = random(3, 15);
    let a = random(5, 25);
    fill(200, 150, 60, a);
    ellipse(x, y, s, s * 0.5);
  }

  // Floating particles rising from the tree (souls/light)
  drawRisingParticles();

  // Settled particles on the ground (fallen light)
  drawSettledParticles();

  // Top atmosphere - very faint particles fading into void
  drawFadingParticles();

  // Subtle overall vignette
  drawVignette();
}

function drawTree() {
  // Draw trunk
  let trunkX = width / 2;
  let trunkBase = 1520;
  let trunkTop = 900;

  // Trunk with organic edges
  for (let y = trunkBase; y > trunkTop; y--) {
    let t = (trunkBase - y) / (trunkBase - trunkTop);
    let trunkWidth = lerp(60, 15, t * t);
    let wobble = noise(y * 0.01) * 20 - 10;

    for (let x = trunkX - trunkWidth + wobble; x < trunkX + trunkWidth + wobble; x++) {
      let dx = abs(x - trunkX - wobble) / trunkWidth;
      let n = noise(x * 0.02, y * 0.02);
      let brightness = (1 - dx) * (0.5 + n * 0.5);
      let r = lerp(20, 60, brightness);
      let g = lerp(15, 40, brightness);
      let b = lerp(10, 30, brightness);
      let a = (1 - dx * 0.7) * 255;
      if (random() < 0.8) {
        stroke(r, g, b, a);
        point(x, y);
      }
    }
  }

  // Branches
  noStroke();
  drawBranch(trunkX, trunkTop, -PI / 2, 180, 12, 0);
}

function drawBranch(x, y, angle, len, thickness, depth) {
  if (depth > 7 || len < 8) return;

  let endX = x + cos(angle) * len;
  let endY = y + sin(angle) * len;

  // Draw branch segment with particles
  let steps = len / 2;
  for (let i = 0; i < steps; i++) {
    let t = i / steps;
    let px = lerp(x, endX, t);
    let py = lerp(y, endY, t);
    let wobbleX = noise(px * 0.01, py * 0.01, depth) * 10 - 5;
    let wobbleY = noise(px * 0.01 + 100, py * 0.01, depth) * 10 - 5;

    let thick = thickness * (1 - t * 0.7);
    let n = noise(px * 0.02, py * 0.02);

    // Branch color - warm dark tones
    let r = lerp(30, 80, n);
    let g = lerp(20, 50, n);
    let b = lerp(15, 35, n);

    fill(r, g, b, 180);
    ellipse(px + wobbleX, py + wobbleY, thick, thick);

    // Glow particles along branches
    if (depth > 3 && random() < 0.3) {
      let glowSize = random(3, 12);
      let glowAlpha = random(20, 80);
      let hueChoice = random();
      if (hueChoice < 0.5) {
        fill(255, 200, 80, glowAlpha); // warm gold
      } else if (hueChoice < 0.8) {
        fill(180, 220, 255, glowAlpha); // pale blue
      } else {
        fill(255, 240, 200, glowAlpha); // warm white
      }
      ellipse(px + wobbleX + random(-10, 10), py + wobbleY + random(-10, 10), glowSize);
    }
  }

  // Recursive branching
  let numBranches = depth < 2 ? floor(random(2, 4)) : floor(random(1, 3));
  for (let b = 0; b < numBranches; b++) {
    let newAngle = angle + random(-0.8, 0.8);
    let newLen = len * random(0.55, 0.75);
    let newThick = thickness * 0.65;
    drawBranch(endX, endY, newAngle, newLen, newThick, depth + 1);
  }
}

function drawRisingParticles() {
  // Particles rising from the canopy area
  for (let i = 0; i < 3000; i++) {
    let startX = width / 2 + randomGaussian() * 350;
    let startY = random(400, 1000);

    // Rising path influenced by noise
    let riseHeight = random(100, 800);
    let drift = noise(i * 0.1) * 200 - 100;

    let endX = startX + drift;
    let endY = startY - riseHeight;

    let t = random(); // position along path
    let px = lerp(startX, endX, t);
    let py = lerp(startY, endY, t);

    // Particles higher up are more transparent and smaller
    let heightFactor = 1 - (py / 1200);
    let size = random(2, 10) * (1 - heightFactor * 0.5);
    let alpha = random(30, 180) * (1 - heightFactor * 0.7);

    let hueChoice = random();
    if (hueChoice < 0.4) {
      fill(255, 210, 100, alpha); // gold
    } else if (hueChoice < 0.65) {
      fill(255, 180, 80, alpha); // amber
    } else if (hueChoice < 0.85) {
      fill(200, 230, 255, alpha); // ice blue
    } else {
      fill(255, 250, 230, alpha); // warm white
    }

    noStroke();
    ellipse(px, py, size);

    // Add glow halo to some particles
    if (random() < 0.2) {
      fill(255, 200, 100, alpha * 0.15);
      ellipse(px, py, size * 4);
    }
  }

  // Dense cluster of light at the crown
  for (let i = 0; i < 500; i++) {
    let x = width / 2 + randomGaussian() * 120;
    let y = random(750, 950) + randomGaussian() * 40;
    let s = random(2, 6);
    let a = random(40, 120);
    fill(255, 220, 140, a);
    ellipse(x, y, s);
  }
}

function drawSettledParticles() {
  // Particles resting on the ground - like fallen light
  for (let i = 0; i < 800; i++) {
    let x = width / 2 + randomGaussian() * 400;
    let y = random(1520, 1900);
    let distFromCenter = abs(x - width / 2) / 400;

    let size = random(2, 8);
    let alpha = random(20, 100) * (1 - distFromCenter);

    let hueChoice = random();
    if (hueChoice < 0.5) {
      fill(255, 190, 70, alpha);
    } else if (hueChoice < 0.8) {
      fill(200, 160, 80, alpha);
    } else {
      fill(150, 180, 200, alpha);
    }

    noStroke();
    ellipse(x, y, size, size * 0.6);

    if (random() < 0.15) {
      fill(255, 180, 60, alpha * 0.2);
      ellipse(x, y, size * 3, size * 2);
    }
  }
}

function drawFadingParticles() {
  // Very sparse, faint particles in the upper region
  for (let i = 0; i < 400; i++) {
    let x = random(width);
    let y = random(0, 500);
    let heightFactor = 1 - y / 500;
    let size = random(1, 4);
    let alpha = random(10, 50) * (1 - heightFactor);

    fill(200, 210, 230, alpha);
    noStroke();
    ellipse(x, y, size);
  }
}

function drawVignette() {
  // Radial vignette effect
  let cx = width / 2;
  let cy = height / 2;
  let maxDist = dist(0, 0, cx, cy);

  for (let i = 0; i < 30; i++) {
    let t = i / 30;
    let d = lerp(maxDist * 0.5, maxDist * 1.1, t);
    let alpha = t * t * 120;
    noFill();
    stroke(5, 5, 12, alpha);
    strokeWeight(30);
    ellipse(cx, cy * 0.85, d * 2, d * 2.2);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  background(7, 7, 15);
  let cx = 800;

  noStroke();
  for (let i = 0; i < 60000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.0015, y * 0.0015);
    let bright = n * 18;
    fill(10 + bright * 0.3, 8 + bright * 0.2, 18 + bright * 0.8, random(8, 25));
    ellipse(x, y, random(1, 3.5));
  }

  for (let r = 500; r > 0; r -= 4) {
    let a = map(r, 0, 500, 10, 0);
    fill(50, 30, 15, a);
    ellipse(cx, 650, r * 1.8, r * 2.5);
  }

  for (let i = 0; i < 2000; i++) {
    let y = random(250, 1150);
    let r = formRadius(y);
    let x = cx + randomGaussian() * r * 0.5;
    let dist = abs(x - cx) / max(r, 1);
    if (dist > 1.2) continue;
    let sz = random(30, 80);
    let n = noise(x * 0.004, y * 0.004);
    fill(lerp(140, 190, n), lerp(70, 110, n), lerp(30, 50, n), random(4, 12));
    noStroke();
    ellipse(x, y, sz, sz * random(0.7, 1.3));
  }

  for (let i = 0; i < 30000; i++) {
    let y = random(220, 1500);
    let r = formRadius(constrain(y, 250, 1150));
    let spreadMult = 1 + constrain(map(y, 800, 1500, 0, 3), 0, 3);
    let spread = max(r * spreadMult, r);
    let x = cx + randomGaussian() * spread * 0.45;
    let dist = r > 0 ? abs(x - cx) / r : 3;
    let yDissolve = constrain(map(y, 850, 1500, 0, 1), 0, 1);
    let dissolve = constrain(dist * 0.5 + yDissolve * 0.6, 0, 1);
    if (dissolve > 0.15) {
      let drift = pow(dissolve, 1.5) * 350;
      x += (noise(x * 0.008, y * 0.008) - 0.5) * drift * 2;
      y += random(0, drift * 0.5);
    }
    if (dissolve > 0.92 && random() > 0.08) continue;
    if (dist > 4) continue;
    let n = noise(x * 0.008, y * 0.008, 1);
    let sz = lerp(10, 2, dissolve) * random(0.6, 1.4);
    let cr = lerp(200, 15, dissolve) + n * 30 * (1 - dissolve);
    let cg = lerp(130, 12, dissolve) + n * 20 * (1 - dissolve);
    let cb = lerp(45, 25, dissolve) + n * 25 * (1 - dissolve);
    let ca = lerp(50, 3, dissolve) * random(0.5, 1.5);
    noStroke();
    fill(cr, cg, cb, ca);
    ellipse(x, y, sz, sz * random(0.8, 1.2));
  }

  for (let i = 0; i < 40000; i++) {
    let y = random(300, 950);
    let r = formRadius(y) * 0.7;
    let x = cx + randomGaussian() * r * 0.4;
    if (abs(x - cx) > formRadius(y)) continue;
    let n = noise(x * 0.015, y * 0.015, 2);
    let sz = random(1, 4);
    noStroke();
    fill(lerp(190, 250, n), lerp(130, 190, n), lerp(60, 100, n), random(15, 70) * n);
    ellipse(x, y, sz);
  }

  for (let i = 0; i < 3000; i++) {
    let y = random(350, 900);
    let r = formRadius(y) * 0.6;
    let x = cx + randomGaussian() * r * 0.35;
    if (abs(x - cx) > formRadius(y) * 0.8) continue;
    let len = random(5, 20);
    let angle = noise(x * 0.01, y * 0.01, 3) * TWO_PI;
    let x2 = x + cos(angle) * len;
    let y2 = y + sin(angle) * len;
    let n = noise(x * 0.02, y * 0.02, 4);
    stroke(lerp(180, 240, n), lerp(120, 170, n), lerp(50, 90, n), random(10, 40));
    strokeWeight(random(0.5, 1.5));
    line(x, y, x2, y2);
  }

  noStroke();
  for (let i = 0; i < 8000; i++) {
    let angle = random(TWO_PI);
    let d = random(300, 900);
    let x = cx + cos(angle) * d * random(0.7, 1.3);
    let y = 700 + sin(angle) * d * 1.3 + random(100, 500);
    if (y < 600) continue;
    let fade = map(d, 300, 900, 25, 2);
    let n = noise(x * 0.005, y * 0.005, 5);
    fill(lerp(60, 15, n), lerp(45, 12, n), lerp(55, 25, n), fade * random(0.3, 1));
    ellipse(x, y, random(1, 2.5));
  }

  for (let i = 0; i < 150; i++) {
    let y1 = random(850, 1350);
    let x1 = cx + randomGaussian() * 200;
    let len = random(20, 100);
    let angle = random(PI * 0.3, PI * 0.7);
    let x2 = x1 + cos(angle) * len;
    let y2 = y1 + sin(angle) * len;
    stroke(80, 55, 45, random(3, 10));
    strokeWeight(random(0.3, 0.7));
    line(x1, y1, x2, y2);
  }

  noStroke();
  for (let i = 0; i < 800; i++) {
    let y = random(380, 780);
    let r = formRadius(y) * 0.5;
    let x = cx + random(-r, r);
    let n = noise(x * 0.025, y * 0.025, 6);
    if (n > 0.55) {
      fill(255, 235, 180, random(15, 50) * (n - 0.55) * 5);
      ellipse(x, y, random(1, 3));
    }
  }

  for (let i = 0; i < 200; i++) {
    let x = cx + randomGaussian() * 250;
    let y = random(900, 1600);
    let len = random(30, 150);
    stroke(40, 30, 35, random(2, 8));
    strokeWeight(random(0.3, 1));
    line(x, y, x + random(-5, 5), y + len);
  }
}

function formRadius(y) {
  let top = 250, bot = 1150;
  if (y < top || y > bot) return 0;
  let t = map(y, top, bot, 0, PI);
  let base = 170 * sin(t);
  let nMod = (noise(y * 0.008, 5.5) - 0.5) * 80;
  return max(5, base + nMod);
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  pixelDensity(1);
}

function draw() {
  // Background gradient: deep indigo top → warm dark center → deep blue-black bottom
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r, g, b;
    if (t < 0.25) {
      let lt = t / 0.25;
      r = lerp(6, 18, lt);
      g = lerp(8, 10, lt);
      b = lerp(28, 42, lt);
    } else if (t < 0.55) {
      let lt = (t - 0.25) / 0.3;
      r = lerp(18, 55, lt);
      g = lerp(10, 20, lt);
      b = lerp(42, 38, lt);
    } else if (t < 0.75) {
      let lt = (t - 0.55) / 0.2;
      r = lerp(55, 30, lt);
      g = lerp(20, 12, lt);
      b = lerp(38, 32, lt);
    } else {
      let lt = (t - 0.75) / 0.25;
      r = lerp(30, 8, lt);
      g = lerp(12, 6, lt);
      b = lerp(32, 22, lt);
    }
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Atmospheric noise texture
  noStroke();
  for (let i = 0; i < 80000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.003, y * 0.003);
    let alpha = n * 12;
    fill(180, 160, 200, alpha);
    rect(x, y, 2, 2);
  }

  // Figure center and parameters
  let cx = width / 2;
  let cy = height * 0.58;
  let headY = cy - 260;
  let headR = 55;

  // Warm glow at heart center
  for (let r = 300; r > 0; r -= 2) {
    let alpha = map(r, 0, 300, 25, 0);
    fill(220, 130, 70, alpha);
    ellipse(cx, cy - 80, r * 1.2, r * 1.5);
  }
  for (let r = 180; r > 0; r -= 2) {
    let alpha = map(r, 0, 180, 20, 0);
    fill(255, 180, 100, alpha);
    ellipse(cx, cy - 80, r * 0.8, r);
  }

  // Draw the figure as layered noise-distorted shapes
  // Torso
  drawOrganicShape(cx, cy, 140, 280, 0.008, 35, color(45, 22, 35, 180));
  drawOrganicShape(cx, cy - 10, 120, 250, 0.009, 30, color(70, 35, 45, 160));
  drawOrganicShape(cx, cy - 20, 100, 220, 0.01, 25, color(100, 50, 55, 140));
  drawOrganicShape(cx, cy - 30, 80, 190, 0.012, 20, color(140, 75, 65, 120));
  drawOrganicShape(cx, cy - 40, 60, 150, 0.014, 15, color(180, 100, 80, 100));

  // Shoulders
  drawOrganicShape(cx - 90, cy - 160, 80, 50, 0.012, 20, color(55, 28, 40, 150));
  drawOrganicShape(cx + 90, cy - 160, 80, 50, 0.012, 20, color(55, 28, 40, 150));
  drawOrganicShape(cx - 70, cy - 165, 60, 40, 0.014, 15, color(90, 45, 50, 120));
  drawOrganicShape(cx + 70, cy - 165, 60, 40, 0.014, 15, color(90, 45, 50, 120));

  // Neck
  drawOrganicShape(cx, cy - 210, 35, 60, 0.015, 12, color(80, 40, 50, 160));
  drawOrganicShape(cx, cy - 215, 28, 50, 0.018, 10, color(120, 65, 60, 130));

  // Head
  drawOrganicShape(cx, headY, headR, headR * 1.15, 0.012, 25, color(50, 25, 38, 180));
  drawOrganicShape(cx, headY, headR * 0.8, headR * 0.95, 0.015, 18, color(90, 48, 52, 150));
  drawOrganicShape(cx, headY + 5, headR * 0.55, headR * 0.65, 0.02, 12, color(150, 85, 70, 120));
  drawOrganicShape(cx, headY + 8, headR * 0.3, headR * 0.4, 0.025, 8, color(200, 120, 90, 90));

  // Dissolution particles rising from the figure
  // Upper dissolution — dense near figure, sparse higher up
  for (let i = 0; i < 12000; i++) {
    let baseX = cx + randomGaussian() * 120;
    let baseY = cy - random(100, 500);

    // Distance from figure top determines drift
    let riseAmount = map(baseY, cy - 100, cy - 500, 0, 1);
    let drift = randomGaussian() * (50 + riseAmount * 200);
    let px = baseX + drift;
    let py = baseY - random(0, 200) * riseAmount;

    // Noise-based clustering
    let n = noise(px * 0.005, py * 0.005);
    if (n < 0.35 && py < cy - 300) continue;

    let size = map(riseAmount, 0, 1, 4, 1.5) * (0.5 + random());
    let alpha = map(riseAmount, 0, 1, 120, 15);
    alpha *= (0.3 + n);

    // Color shifts from warm to cool as it rises
    let r = lerp(220, 100, riseAmount);
    let g = lerp(120, 80, riseAmount);
    let b = lerp(80, 160, riseAmount);

    fill(r, g, b, alpha);
    noStroke();
    ellipse(px, py, size, size);
  }

  // Larger dissolution wisps / tendrils
  for (let i = 0; i < 200; i++) {
    let startX = cx + randomGaussian() * 80;
    let startY = cy - random(150, 350);
    let len = random(40, 150);
    let angle = -HALF_PI + randomGaussian() * 0.4;

    stroke(180, 100, 80, random(5, 25));
    strokeWeight(random(0.5, 2));
    noFill();
    beginShape();
    let px = startX, py = startY;
    for (let j = 0; j < len; j += 5) {
      let n = noise(px * 0.01, py * 0.01) * 20 - 10;
      px += cos(angle) * 5 + n * 0.3;
      py += sin(angle) * 5 + n * 0.1;
      curveVertex(px, py);
    }
    endShape();
  }

  // Luminous points scattered in the upper region — "distributed light"
  for (let i = 0; i < 400; i++) {
    let px = random(width * 0.1, width * 0.9);
    let py = random(height * 0.02, height * 0.55);
    let n = noise(px * 0.004, py * 0.004);

    // More points higher up
    let densityFactor = map(py, height * 0.55, height * 0.02, 0, 1);
    if (random() > densityFactor * 0.7 + 0.1) continue;

    let size = random(1.5, 5) * (0.5 + n);
    let brightness = random(150, 255);
    let warmth = random();

    // Glow
    for (let g = size * 6; g > 0; g -= 2) {
      let ga = map(g, 0, size * 6, 30, 0) * (brightness / 255);
      fill(lerp(200, 150, warmth), lerp(180, 160, warmth), lerp(220, 255, warmth), ga);
      noStroke();
      ellipse(px, py, g, g);
    }
    // Core
    fill(brightness, brightness * 0.9, brightness * 0.95, 200);
    noStroke();
    ellipse(px, py, size, size);
  }

  // Subtle lower particles — remnants settling
  for (let i = 0; i < 3000; i++) {
    let px = cx + randomGaussian() * 250;
    let py = cy + random(50, 400);
    let distFromCenter = abs(px - cx) / 250;
    let fallAmount = (py - cy) / 400;

    let size = random(1, 3) * (1 - fallAmount * 0.5);
    let alpha = random(10, 50) * (1 - fallAmount);

    fill(60 + random(40), 30 + random(20), 40 + random(20), alpha);
    noStroke();
    ellipse(px, py, size, size);
  }

  // Final atmospheric veil — very subtle noise overlay
  for (let i = 0; i < 30000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.002 + 100, y * 0.002 + 100);
    if (n > 0.55) {
      fill(140, 120, 160, (n - 0.55) * 30);
      noStroke();
      rect(x, y, 3, 3);
    }
  }

  // Soft vignette
  let vigR = max(width, height) * 0.85;
  for (let r = vigR; r > vigR * 0.5; r -= 3) {
    let alpha = map(r, vigR * 0.5, vigR, 0, 40);
    noFill();
    stroke(5, 5, 15, alpha);
    strokeWeight(4);
    ellipse(width / 2, height / 2, r * 2, r * 2.2);
  }
}

function drawOrganicShape(cx, cy, rx, ry, noiseScale, noiseMag, col) {
  fill(col);
  noStroke();
  beginShape();
  let steps = 60;
  for (let i = 0; i < steps; i++) {
    let angle = (i / steps) * TWO_PI;
    let n = noise(cx * 0.01 + cos(angle) * 2, cy * 0.01 + sin(angle) * 2, i * 0.1) * noiseMag;
    let x = cx + cos(angle) * (rx + n);
    let y = cy + sin(angle) * (ry + n);
    curveVertex(x, y);
  }
  // Close the shape with extra vertices
  for (let i = 0; i < 3; i++) {
    let angle = (i / steps) * TWO_PI;
    let n = noise(cx * 0.01 + cos(angle) * 2, cy * 0.01 + sin(angle) * 2, i * 0.1) * noiseMag;
    let x = cx + cos(angle) * (rx + n);
    let y = cy + sin(angle) * (ry + n);
    curveVertex(x, y);
  }
  endShape(CLOSE);
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
  drawPainting();
}

function drawPainting() {
  // Background gradient - deep to pale
  for (let y = 0; y < 2000; y++) {
    let t = y / 2000;
    let c;
    if (t < 0.3) {
      c = lerpColor(color(18, 22, 36), color(35, 45, 65), t / 0.3);
    } else if (t < 0.6) {
      c = lerpColor(color(35, 45, 65), color(120, 115, 125), (t - 0.3) / 0.3);
    } else {
      c = lerpColor(color(120, 115, 125), color(215, 205, 195), (t - 0.6) / 0.4);
    }
    // Add subtle noise to background
    let nv = noise(y * 0.01) * 8 - 4;
    stroke(red(c) + nv, green(c) + nv, blue(c) + nv);
    line(0, y, 1600, y);
  }

  // Atmospheric glaze layers
  noStroke();
  for (let i = 0; i < 30; i++) {
    let x = random(1600);
    let y = random(2000);
    let s = random(200, 600);
    let t = y / 2000;
    let alpha = random(5, 15) * (1 - t * 0.5);
    if (t < 0.5) {
      fill(60 + random(30), 40 + random(20), 80 + random(40), alpha);
    } else {
      fill(180 + random(30), 170 + random(20), 160 + random(20), alpha);
    }
    ellipse(x, y, s, s * random(0.8, 1.2));
  }

  // Organic branching structures - dense at top, dissolving downward
  strokeWeight(1);
  for (let b = 0; b < 45; b++) {
    let startX = random(200, 1400);
    let startY = random(50, 800);
    drawBranch(startX, startY, random(-PI/2 - 0.5, -PI/2 + 0.5), random(60, 180), 0, b);
  }

  // Flow field lines - representing the current of dissolution
  for (let i = 0; i < 2000; i++) {
    let x = random(1600);
    let y = random(1800);
    let t = y / 2000;
    let len = random(20, 80) * (1 - t * 0.7);
    let coherence = 1 - t; // How much the noise influences direction

    let angle = noise(x * 0.003, y * 0.003) * TWO_PI * 2 * coherence + 
                (1 - coherence) * (PI / 2 + random(-0.3, 0.3));

    let alpha = random(20, 60) * (1 - t * 0.8);

    if (t < 0.4) {
      let hueShift = noise(x * 0.01, y * 0.01);
      if (hueShift < 0.33) {
        stroke(80 + random(40), 50 + random(30), 60 + random(20), alpha);
      } else if (hueShift < 0.66) {
        stroke(40 + random(30), 70 + random(40), 90 + random(30), alpha);
      } else {
        stroke(140 + random(40), 100 + random(30), 50 + random(20), alpha);
      }
    } else {
      let v = 130 + t * 60 + random(-10, 10);
      stroke(v, v - 5, v - 10, alpha);
    }

    strokeWeight(random(0.5, 2.5) * (1 - t * 0.5));
    let ex = x + cos(angle) * len;
    let ey = y + sin(angle) * len;
    line(x, y, ex, ey);
  }

  // Particle dissolution - organized clusters becoming scattered
  noStroke();
  for (let i = 0; i < 8000; i++) {
    let t = random(1);
    let y = t * 2000;
    let x;

    if (t < 0.4) {
      // Clustered particles following structure
      let cx = 800 + noise(i * 0.1) * 600 - 300;
      let cy = noise(i * 0.1 + 100) * 700;
      x = cx + random(-80, 80) * noise(i * 0.5);
      y = cy + random(-80, 80) * noise(i * 0.5 + 50);
    } else if (t < 0.7) {
      // Transitioning - drifting apart
      x = random(1600);
      y = 700 + random(700);
    } else {
      // Scattered, fading
      x = random(1600);
      y = 1400 + random(600);
    }

    let tt = y / 2000;
    let size = random(1, 5) * (1 - tt * 0.6);
    let alpha = random(30, 120) * (1 - tt * 0.85);

    if (tt < 0.35) {
      let r = 150 + random(80);
      let g = 80 + random(60);
      let b = 50 + random(40);
      fill(r, g, b, alpha);
    } else if (tt < 0.6) {
      let v = 100 + random(50);
      fill(v + 20, v, v - 10, alpha);
    } else {
      let v = 170 + random(40);
      fill(v, v - 5, v - 15, alpha * 0.7);
    }

    ellipse(x, y, size, size);
  }

  // Vein-like networks in upper portion
  strokeCap(ROUND);
  for (let v = 0; v < 12; v++) {
    let points = [];
    let px = random(300, 1300);
    let py = random(100, 600);
    let angle = random(TWO_PI);

    for (let s = 0; s < 60; s++) {
      points.push({x: px, y: py});
      angle += random(-0.4, 0.4) + noise(px * 0.01, py * 0.01) * 0.5 - 0.25;
      let step = random(5, 15);
      px += cos(angle) * step;
      py += sin(angle) * step + 2; // Slight downward drift

      if (py > 1200) break;
    }

    for (let s = 0; s < points.length - 1; s++) {
      let t = points[s].y / 2000;
      let alpha = (80 - s * 1.2) * (1 - t);
      if (alpha <= 0) continue;

      let col;
      let hueVal = noise(v * 10 + s * 0.1);
      if (hueVal < 0.3) {
        col = color(60 + random(20), 90 + random(30), 110 + random(20), alpha);
      } else if (hueVal < 0.6) {
        col = color(130 + random(30), 70 + random(20), 50 + random(20), alpha);
      } else {
        col = color(90 + random(20), 60 + random(20), 100 + random(30), alpha);
      }

      stroke(col);
      strokeWeight(random(0.5, 3) * (1 - s / points.length));
      line(points[s].x, points[s].y, points[s+1].x, points[s+1].y);
    }
  }

  // Central luminous form - like a figure dissolving
  noStroke();
  let centerX = 800;
  let centerY = 700;

  for (let i = 0; i < 3000; i++) {
    let angle = random(TWO_PI);
    let r = random(300);
    let x = centerX + cos(angle) * r * (0.6 + noise(angle) * 0.8);
    let y = centerY + sin(angle) * r * 1.4;

    // Elongate downward (dissolving downward)
    let dissolve = max(0, (y - 600) / 800);
    y += dissolve * random(100, 400);
    x += dissolve * random(-150, 150);

    let t = y / 2000;
    let alpha = random(10, 40) * (1 - dissolve * 0.7);
    let size = random(2, 8) * (1 - dissolve * 0.5);

    if (t < 0.5) {
      fill(180 + random(40), 140 + random(30), 100 + random(30), alpha);
    } else {
      let v = 160 + random(40);
      fill(v, v - 5, v - 10, alpha);
    }

    ellipse(x, y, size, size * random(1, 2));
  }

  // Final glaze - unifying warm tone over lower half
  for (let y = 1000; y < 2000; y += 2) {
    let t = (y - 1000) / 1000;
    fill(210, 200, 185, t * 8);
    noStroke();
    rect(0, y, 1600, 2);
  }

  // Soft vignette
  for (let i = 0; i < 50; i++) {
    noFill();
    let t = i / 50;
    stroke(15, 18, 30, t * 12);
    strokeWeight(20);
    rect(i * 15, i * 15, 1600 - i * 30, 2000 - i * 30);
  }
}

function drawBranch(x, y, angle, len, depth, seed) {
  if (depth > 7 || len < 5) return;

  let t = y / 2000;
  if (t > 0.65 && random() > 0.3) return; // Branches don't survive below

  let ex = x + cos(angle) * len;
  let ey = y + sin(angle) * len;

  let alpha = (100 - depth * 12) * (1 - t * 1.2);
  if (alpha <= 0) return;

  let hueShift = noise(seed * 0.3 + depth * 0.2);
  if (hueShift < 0.4) {
    stroke(50 + depth * 8, 70 + depth * 5, 90 + depth * 5, alpha);
  } else if (hueShift < 0.7) {
    stroke(100 + depth * 10, 60 + depth * 5, 45 + depth * 5, alpha);
  } else {
    stroke(70 + depth * 5, 55 + depth * 5, 80 + depth * 8, alpha);
  }

  strokeWeight(max(0.3, (4 - depth * 0.5) * (1 - t)));
  line(x, y, ex, ey);

  let branches = depth < 2 ? floor(random(2, 4)) : floor(random(1, 3));
  for (let i = 0; i < branches; i++) {
    let newAngle = angle + random(-0.8, 0.8);
    let newLen = len * random(0.5, 0.75);
    drawBranch(ex, ey, newAngle, newLen, depth + 1, seed + i * 7);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function draw() {
  // Deep background
  background(12, 14, 28);

  // Subtle background noise texture
  for (let i = 0; i < 80000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.003, y * 0.003);
    let alpha = n * 15;
    let blue = 30 + n * 20;
    fill(15 + n * 10, 15 + n * 8, blue, alpha);
    noStroke();
    ellipse(x, y, random(1, 3), random(1, 3));
  }

  // Create a soft glow behind the figure area
  for (let i = 0; i < 30; i++) {
    let radius = 400 - i * 12;
    let alpha = 3;
    fill(40 + i, 30 + i * 0.5, 50 + i, alpha);
    noStroke();
    ellipse(780, 1200, radius * 2, radius * 3);
  }

  // Define the human form as a series of body regions
  // Using a parametric silhouette
  let bodyPoints = [];

  // Head
  for (let a = 0; a < TWO_PI; a += 0.05) {
    for (let r = 0; r < 85; r += 4) {
      bodyPoints.push({
        x: 780 + cos(a) * r * 0.85,
        y: 750 + sin(a) * r,
        region: 'head'
      });
    }
  }

  // Neck
  for (let y = 830; y < 900; y += 4) {
    for (let x = 740; x < 820; x += 4) {
      bodyPoints.push({x: x, y: y, region: 'neck'});
    }
  }

  // Torso
  for (let y = 900; y < 1350; y += 4) {
    let torsoWidth = map(y, 900, 1350, 160, 130);
    let taper = sin(map(y, 900, 1350, 0, PI)) * 30;
    let w = torsoWidth + taper;
    for (let x = 780 - w; x < 780 + w; x += 4) {
      bodyPoints.push({x: x, y: y, region: 'torso'});
    }
  }

  // Arms (slightly away from body)
  for (let y = 920; y < 1250; y += 5) {
    let armLen = map(y, 920, 1250, 0, 80);
    // Left arm
    for (let x = 780 - 160 - armLen * 0.5; x < 780 - 140 + armLen * 0.3; x += 5) {
      bodyPoints.push({x: x + noise(y * 0.05) * 10, y: y, region: 'arm'});
    }
    // Right arm
    for (let x = 780 + 140 - armLen * 0.3; x < 780 + 160 + armLen * 0.5; x += 5) {
      bodyPoints.push({x: x + noise(y * 0.05 + 100) * 10, y: y, region: 'arm'});
    }
  }

  // Lower body / legs fading out
  for (let y = 1350; y < 1750; y += 5) {
    let fade = map(y, 1350, 1750, 1, 0);
    let legWidth = 60 * fade;
    let gap = 20 * fade;
    // Left leg
    for (let x = 780 - gap - legWidth; x < 780 - gap; x += 5) {
      if (random() < fade) {
        bodyPoints.push({x: x, y: y, region: 'legs'});
      }
    }
    // Right leg
    for (let x = 780 + gap; x < 780 + gap + legWidth; x += 5) {
      if (random() < fade) {
        bodyPoints.push({x: x, y: y, region: 'legs'});
      }
    }
  }

  // Dissolution: based on vertical position, particles scatter
  // The higher up, the more dissolved
  // Dissolution starts strongly from the head and upper body

  let dissolvedParticles = [];
  let coherentParticles = [];

  for (let p of bodyPoints) {
    // Dissolution factor: 0 = fully coherent, 1 = fully dissolved
    // Head and upper body dissolve more
    let dissolveY = map(p.y, 650, 1600, 1, 0);
    dissolveY = constrain(dissolveY, 0, 1);

    // Add noise-based variation
    let noiseFactor = noise(p.x * 0.008, p.y * 0.008);
    let dissolution = dissolveY * 0.7 + noiseFactor * 0.3;

    // Right side dissolves more than left
    let sideBias = map(p.x, 600, 1000, 0, 0.3);
    dissolution += sideBias;
    dissolution = constrain(dissolution, 0, 1);

    if (dissolution > 0.4) {
      // This particle is dissolving - scatter it
      let scatter = pow(dissolution, 1.5);
      let nx = noise(p.x * 0.005, p.y * 0.005) - 0.5;
      let ny = noise(p.x * 0.005 + 50, p.y * 0.005 + 50) - 0.5;

      let driftX = nx * scatter * 500 + scatter * 80; // drift right and up
      let driftY = ny * scatter * 400 - scatter * 200; // drift upward

      let newX = p.x + driftX;
      let newY = p.y + driftY;

      dissolvedParticles.push({
        x: newX,
        y: newY,
        origX: p.x,
        origY: p.y,
        dissolution: dissolution,
        region: p.region
      });
    } else {
      coherentParticles.push({
        x: p.x + random(-2, 2),
        y: p.y + random(-2, 2),
        dissolution: dissolution,
        region: p.region
      });
    }
  }

  // Draw coherent particles (warm, earthy tones)
  for (let p of coherentParticles) {
    let warmth = 1 - p.dissolution;
    let r = lerp(60, 200, warmth) + random(-15, 15);
    let g = lerp(40, 140, warmth) + random(-10, 10);
    let b = lerp(50, 90, warmth) + random(-10, 10);
    let a = map(p.dissolution, 0, 0.4, 220, 120);

    fill(r, g, b, a);
    noStroke();
    let s = random(3, 6) * (1 - p.dissolution * 0.5);
    ellipse(p.x, p.y, s, s * random(0.8, 1.4));
  }

  // Draw dissolving particles - these stream upward and rightward
  // Create trailing streams
  for (let p of dissolvedParticles) {
    let d = p.dissolution;

    // Color shifts from warm to cool as dissolution increases
    let r = lerp(180, 40, d) + random(-10, 10);
    let g = lerp(120, 50, d) + random(-10, 10);
    let b = lerp(80, 100, d) + random(-10, 10);
    let a = map(d, 0.4, 1, 180, 20);

    // Draw trail from original position to scattered position
    let steps = floor(map(d, 0.4, 1, 3, 12));
    for (let s = 0; s < steps; s++) {
      let t = s / steps;
      let tx = lerp(p.origX, p.x, t);
      let ty = lerp(p.origY, p.y, t);
      let trailAlpha = a * (1 - t * 0.7);
      let trailSize = lerp(4, 1.5, t) * map(d, 0.4, 1, 1, 0.5);

      fill(r, g, b, trailAlpha * 0.4);
      noStroke();
      ellipse(tx + random(-3, 3), ty + random(-3, 3), trailSize, trailSize);
    }

    // Final particle
    let finalSize = random(1.5, 4) * (1 - d * 0.5);
    fill(r, g, b, a);
    noStroke();
    ellipse(p.x, p.y, finalSize, finalSize * random(0.7, 1.3));
  }

  // Add flowing dissolution streams - like smoke or energy leaving
  for (let stream = 0; stream < 200; stream++) {
    let startX = random(680, 880);
    let startY = random(700, 1200);
    let streamDissolve = map(startY, 700, 1200, 1, 0.3);

    if (random() > streamDissolve) continue;

    let px = startX;
    let py = startY;
    let len = floor(random(10, 40) * streamDissolve);

    for (let s = 0; s < len; s++) {
      let angle = noise(px * 0.004, py * 0.004, stream * 0.1) * TWO_PI * 2 - PI * 0.7;
      px += cos(angle) * 6;
      py += sin(angle) * 6 - 3; // slight upward bias

      let t = s / len;
      let alpha = (1 - t) * 60 * streamDissolve;
      let r = lerp(160, 50, t);
      let g = lerp(110, 60, t);
      let b = lerp(90, 110, t);

      fill(r, g, b, alpha);
      noStroke();
      ellipse(px, py, random(1, 3), random(1, 3));
    }
  }

  // Bright moments - sparks of gold and pale light scattered in dissolution area
  for (let i = 0; i < 300; i++) {
    let x = random(500, 1200);
    let y = random(300, 1100);
    let n = noise(x * 0.01, y * 0.01);

    if (n > 0.55) {
      let bright = random() > 0.5;
      if (bright) {
        // Gold spark
        fill(255, 220, 120, random(40, 120));
        let s = random(1, 3);
        ellipse(x, y, s, s);
      } else {
        // Pale white/blue spark
        fill(200, 210, 240, random(30, 90));
        let s = random(1, 2.5);
        ellipse(x, y, s, s);
      }
    }
  }

  // Large soft atmospheric marks in the dissolution zone
  for (let i = 0; i < 60; i++) {
    let x = random(400, 1200);
    let y = random(200, 900);
    let size = random(30, 100);
    let n = noise(x * 0.005, y * 0.005, 3);
    let alpha = n * 15;

    fill(60 + n * 40, 50 + n * 30, 80 + n * 40, alpha);
    noStroke();
    ellipse(x, y, size, size * random(0.5, 1.5));
  }

  // Dense cluster at the heart/core area - where life still holds
  for (let i = 0; i < 2000; i++) {
    let angle = random(TWO_PI);
    let radius = random(0, 80);
    let x = 770 + cos(angle) * radius * 0.8;
    let y = 1100 + sin(angle) * radius;

    let distFromCenter = radius / 80;
    let r = lerp(210, 140, distFromCenter) + random(-10, 10);
    let g = lerp(150, 90, distFromCenter) + random(-10, 10);
    let b = lerp(100, 60, distFromCenter) + random(-10, 10);
    let a = lerp(180, 60, distFromCenter);

    fill(r, g, b, a);
    noStroke();
    ellipse(x, y, random(2, 5), random(2, 5));
  }

  // Subtle vignette
  for (let i = 0; i < 40; i++) {
    noFill();
    stroke(5, 5, 15, 8);
    strokeWeight(20);
    let margin = i * 15;
    rect(margin, margin, width - margin * 2, height - margin * 2);
  }

  // Final top layer - very faint noise grain over everything
  for (let i = 0; i < 30000; i++) {
    let x = random(width);
    let y = random(height);
    let v = random(255);
    fill(v, v, v, random(3, 8));
    noStroke();
    rect(x, y, 1, 1);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function draw() {
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(10, 20, t);
    let g = lerp(8, 12, t);
    let b = lerp(16, 18, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  for (let i = 0; i < 3000; i++) {
    let x = random(width);
    let y = random(height * 0.5);
    let a = random(1, 4);
    stroke(80, 80, 100, a);
    strokeWeight(random(0.3, 0.8));
    point(x, y);
  }

  for (let i = 0; i < 800; i++) {
    drawThread(true);
  }

  for (let i = 0; i < 3500; i++) {
    drawThread(false);
  }

  for (let i = 0; i < 60; i++) {
    drawReachingThread();
  }

  noStroke();
  for (let i = 0; i < 150; i++) {
    let nx = width / 2 + randomGaussian() * width * 0.18;
    let ny = height - random(height * 0.45);
    let nodeAlpha = random(30, 120);
    let nodeSize = random(1, 3.5);

    fill(255, 210, 150, nodeAlpha * 0.15);
    ellipse(nx, ny, nodeSize * 6, nodeSize * 6);

    fill(255, 200, 130, nodeAlpha * 0.4);
    ellipse(nx, ny, nodeSize * 3, nodeSize * 3);

    fill(255, 230, 180, nodeAlpha);
    ellipse(nx, ny, nodeSize, nodeSize);
  }
}

function drawThread(isBack) {
  let x = width / 2 + randomGaussian() * width * 0.22;
  let yBias = pow(random(), 0.55);
  let y = height - (1 - yBias) * height * 0.6;

  let startY = y;
  let noiseOff = random(10000);
  let maxSteps = floor(random(120, 600));

  let cType = random();
  let cr, cg, cb;
  if (cType < 0.45) {
    cr = random(180, 240); cg = random(100, 150); cb = random(30, 70);
  } else if (cType < 0.75) {
    cr = random(190, 230); cg = random(80, 120); cb = random(70, 100);
  } else {
    cr = random(150, 190); cg = random(140, 180); cb = random(170, 210);
  }

  let baseWeight = isBack ? random(1.5, 4.0) : random(0.3, 1.6);
  let baseAlpha = isBack ? random(8, 25) : random(20, 80);

  let px = x, py = y;

  for (let s = 0; s < maxSteps; s++) {
    let n = noise(x * 0.002, y * 0.002, noiseOff);
    let angle = n * TWO_PI * 1.5;
    angle = lerp(angle, -HALF_PI, 0.55);

    let step = random(1.5, 3.5);
    x += cos(angle) * step;
    y += sin(angle) * step;

    let distUp = startY - y;
    let fadeT = constrain(distUp / (height * 0.55), 0, 1);

    let alpha = baseAlpha * (1 - pow(fadeT, 1.2));
    let w = baseWeight * (1 - fadeT * 0.5);

    let r = lerp(cr, 150, fadeT * 0.4);
    let g = lerp(cg, 150, fadeT * 0.4);
    let b = lerp(cb, 175, fadeT * 0.4);

    if (alpha > 1.5 && y > 0 && y < height && x > -30 && x < width + 30) {
      stroke(r, g, b, alpha);
      strokeWeight(w);
      line(px, py, x, y);
    }

    px = x;
    py = y;

    if (random() < 0.003 + fadeT * 0.015) break;
  }
}

function drawReachingThread() {
  let x = width / 2 + randomGaussian() * width * 0.15;
  let y = height - random(height * 0.15);

  let startY = y;
  let noiseOff = random(10000);
  let maxSteps = floor(random(600, 1800));

  let cr = random(150, 190);
  let cg = random(120, 160);
  let cb = random(100, 140);

  let baseWeight = random(0.2, 0.7);
  let baseAlpha = random(12, 40);

  let px = x, py = y;

  for (let s = 0; s < maxSteps; s++) {
    let n = noise(x * 0.0015, y * 0.0015, noiseOff);
    let angle = n * TWO_PI * 1.2;
    angle = lerp(angle, -HALF_PI, 0.6);

    let step = random(1.5, 3);
    x += cos(angle) * step;
    y += sin(angle) * step;

    let distUp = startY - y;
    let fadeT = constrain(distUp / (height * 0.85), 0, 1);

    let alpha = baseAlpha * (1 - pow(fadeT, 0.7));
    let w = baseWeight * (1 - fadeT * 0.3);

    if (alpha > 1 && y > 0 && y < height) {
      stroke(cr, cg, cb, alpha);
      strokeWeight(w);
      line(px, py, x, y);
    }

    px = x;
    py = y;

    if (random() < 0.001 + fadeT * 0.004) break;
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function draw() {
  background(8, 6, 14);

  // Deep void gradient background
  for (let y = 0; y < 2000; y++) {
    let t = y / 2000;
    let r = lerp(12, 4, t) + noise(y * 0.01) * 8;
    let g = lerp(4, 8, t) + noise(y * 0.01 + 100) * 4;
    let b = lerp(20, 10, t) + noise(y * 0.01 + 200) * 12;
    stroke(r, g, b);
    line(0, y, 1600, y);
  }

  // Atmospheric glow behind figure
  noStroke();
  for (let i = 30; i > 0; i--) {
    let alpha = map(i, 30, 0, 0, 12);
    let rad = map(i, 30, 0, 600, 50);
    fill(60, 30, 80, alpha);
    ellipse(800, 1000, rad * 2, rad * 3);
  }

  // Ethereal light source from dissolution point
  for (let i = 40; i > 0; i--) {
    let alpha = map(i, 40, 0, 0, 8);
    let rad = map(i, 40, 0, 400, 20);
    fill(120, 160, 200, alpha);
    ellipse(800, 750, rad * 2.5, rad * 1.8);
  }

  // Ground plane - dark earth
  for (let y = 1600; y < 2000; y++) {
    let n = noise(y * 0.02);
    let r = 10 + n * 15;
    let g = 6 + n * 8;
    let b = 12 + n * 10;
    stroke(r, g, b);
    for (let x = 0; x < 1600; x += 2) {
      let nx = noise(x * 0.005, y * 0.01) * 20;
      stroke(r + nx, g + nx * 0.5, b + nx * 0.3);
      point(x, y);
    }
  }

  // Figure body - lower solid portion (torso down)
  drawFigureBase();

  // Dissolution zone - figure breaking into particles
  drawDissolution();

  // Floating particles ascending
  drawAscendingParticles();

  // Subtle organic tendrils of dissolution
  drawTendrils();

  // Final light particles near top
  drawFinalParticles();

  // Vignette
  drawVignette();
}

function drawFigureBase() {
  noStroke();

  // Legs - fading into ground
  for (let i = 0; i < 800; i++) {
    let t = i / 800;
    let y = lerp(1600, 1250, t);
    let spread = lerp(80, 30, t);
    let leftX = 760 - spread * 0.3;
    let rightX = 840 + spread * 0.3;

    let n1 = noise(i * 0.05) * 20 - 10;
    let n2 = noise(i * 0.05 + 50) * 20 - 10;

    let alpha = map(t, 0, 1, 40, 180);
    let r = lerp(20, 70, t);
    let g = lerp(15, 50, t);
    let b = lerp(25, 55, t);

    fill(r, g, b, alpha);
    ellipse(leftX + n1, y, 25 + noise(i * 0.1) * 10, 8);
    ellipse(rightX + n2, y, 25 + noise(i * 0.1 + 30) * 10, 8);
  }

  // Torso - more solid
  for (let i = 0; i < 600; i++) {
    let t = i / 600;
    let y = lerp(1250, 900, t);
    let width = lerp(60, 90, sin(t * PI));
    let n = noise(i * 0.03) * 15 - 7;

    let solidness = t < 0.5 ? 1 : map(t, 0.5, 1, 1, 0.3);
    let alpha = 150 * solidness + noise(i * 0.1) * 50;

    let r = lerp(50, 85, t);
    let g = lerp(35, 60, t);
    let b = lerp(40, 65, t);

    fill(r, g, b, alpha);
    let brushW = width + noise(i * 0.05) * 20;
    ellipse(800 + n, y, brushW, 12);
  }

  // Shoulders and arms
  for (let side = -1; side <= 1; side += 2) {
    for (let i = 0; i < 300; i++) {
      let t = i / 300;
      let startX = 800 + side * 90;
      let endX = 800 + side * 160;
      let x = lerp(startX, endX, t) + noise(i * 0.05 + side * 10) * 15;
      let y = lerp(950, 1150, t) + noise(i * 0.04 + side * 20) * 20;

      let alpha = map(t, 0, 1, 140, 30);
      let r = lerp(65, 30, t);
      let g = lerp(45, 20, t);
      let b = lerp(50, 30, t);

      fill(r, g, b, alpha);
      ellipse(x, y, 18 - t * 8, 10 - t * 5);
    }
  }

  // Neck
  for (let i = 0; i < 150; i++) {
    let t = i / 150;
    let y = lerp(900, 830, t);
    let n = noise(i * 0.05) * 8;
    let alpha = map(t, 0, 1, 160, 100);
    fill(70 + n * 2, 50 + n, 55 + n, alpha);
    ellipse(800 + n, y, 35 - t * 5, 8);
  }

  // Head (lower half - still forming)
  for (let i = 0; i < 200; i++) {
    let t = i / 200;
    let y = lerp(830, 760, t);
    let n = noise(i * 0.04) * 10;
    let width = 50 * sin(t * PI) + 30;
    let alpha = map(t, 0, 1, 150, 80);
    let r = lerp(75, 50, t);
    let g = lerp(55, 35, t);
    let b = lerp(58, 45, t);
    fill(r + n, g + n * 0.7, b + n * 0.5, alpha);
    ellipse(800 + n * 0.5, y, width, 10);
  }
}

function drawDissolution() {
  // Upper portion of figure breaking apart
  for (let i = 0; i < 3000; i++) {
    let t = random();
    let y = lerp(760, 500, t);
    let spread = t * t * 200;
    let x = 800 + (random(-1, 1)) * spread + noise(i * 0.01) * 50;

    let size = lerp(8, 2, t) + random(3);
    let alpha = lerp(120, 15, t * t);

    let r = lerp(70, 100, t) + random(20);
    let g = lerp(50, 80, t) + random(15);
    let b = lerp(55, 120, t) + random(20);

    fill(r, g, b, alpha);
    noStroke();
    ellipse(x, y, size, size);
  }

  // Bright dissolution fragments
  for (let i = 0; i < 500; i++) {
    let t = random();
    let y = lerp(780, 550, t);
    let spread = t * 150;
    let x = 800 + random(-spread, spread);

    let size = random(1, 4);
    let alpha = random(30, 100) * (1 - t);

    fill(180, 200, 230, alpha);
    ellipse(x, y, size, size);
  }
}

function drawAscendingParticles() {
  // Particles rising from the figure into the void
  for (let i = 0; i < 2000; i++) {
    let t = random();
    let baseY = lerp(700, 100, t * t);
    let spread = lerp(50, 500, t);
    let x = 800 + randomGaussian() * spread;
    let y = baseY + random(-30, 30);

    let size = lerp(4, 1, t) * random(0.5, 1.5);
    let alpha = lerp(60, 5, t);

    // Color shifts from warm (body) to cool (void)
    let r = lerp(90, 40, t);
    let g = lerp(60, 50, t);
    let b = lerp(70, 90, t);

    fill(r, g, b, alpha);
    noStroke();
    ellipse(x, y, size, size);
  }

  // Luminous soul particles
  for (let i = 0; i < 200; i++) {
    let t = random();
    let y = lerp(650, 50, t);
    let spread = lerp(30, 300, t);
    let x = 800 + randomGaussian() * spread * 0.5;

    let size = random(1, 3);
    let alpha = random(20, 80) * (1 - t * 0.7);

    let glow = random() > 0.7;
    if (glow) {
      fill(200, 220, 255, alpha * 0.5);
      ellipse(x, y, size * 4, size * 4);
    }
    fill(220, 230, 255, alpha);
    ellipse(x, y, size, size);
  }
}

function drawTendrils() {
  // Organic flowing lines suggesting the unraveling of form
  noFill();
  for (let t = 0; t < 20; t++) {
    let startAlpha = random(20, 50);
    stroke(80, 60, 100, startAlpha);
    strokeWeight(random(0.5, 1.5));

    beginShape();
    let sx = 800 + random(-40, 40);
    let sy = random(700, 800);
    for (let i = 0; i < 50; i++) {
      let progress = i / 50;
      let x = sx + noise(t * 10, i * 0.1) * 200 - 100 + progress * random(-100, 100);
      let y = sy - progress * random(200, 500);
      curveVertex(x, y);
    }
    endShape();
  }

  // Wispy dissolution streams
  for (let s = 0; s < 12; s++) {
    let streamX = 800 + random(-60, 60);
    let streamY = random(750, 820);
    noFill();

    for (let i = 0; i < 80; i++) {
      let progress = i / 80;
      let x = streamX + noise(s * 5, i * 0.08) * 150 - 75 + sin(progress * 3) * 20;
      let y = streamY - progress * random(300, 600);
      let alpha = lerp(40, 2, progress);
      let sz = lerp(6, 1, progress);

      fill(100 + noise(i * 0.1) * 50, 80, 120, alpha);
      noStroke();
      ellipse(x, y, sz, sz);
    }
  }
}

function drawFinalParticles() {
  // Scattered particles at the very top - almost gone
  for (let i = 0; i < 300; i++) {
    let x = random(200, 1400);
    let y = random(20, 300);
    let size = random(0.5, 2);
    let alpha = random(5, 25);

    fill(150, 170, 200, alpha);
    noStroke();
    ellipse(x, y, size, size);
  }

  // A few brighter distant sparks
  for (let i = 0; i < 30; i++) {
    let x = random(300, 1300);
    let y = random(50, 250);
    let size = random(1, 2.5);
    let alpha = random(30, 60);

    fill(200, 210, 240, alpha);
    ellipse(x, y, size, size);
    fill(200, 210, 240, alpha * 0.3);
    ellipse(x, y, size * 3, size * 3);
  }
}

function drawVignette() {
  // Dark vignette around edges
  noStroke();
  for (let i = 0; i < 80; i++) {
    let alpha = map(i, 0, 80, 25, 0);
    fill(5, 3, 10, alpha);

    // Top
    rect(0, i * 3, 1600, 3);
    // Bottom
    rect(0, 2000 - i * 3, 1600, 3);
    // Left
    rect(i * 4, 0, 4, 2000);
    // Right
    rect(1600 - i * 4, 0, 4, 2000);
  }

  // Corner darkening
  for (let corner = 0; corner < 4; corner++) {
    let cx = (corner % 2 === 0) ? 0 : 1600;
    let cy = (corner < 2) ? 0 : 2000;
    for (let r = 400; r > 0; r -= 5) {
      let alpha = map(r, 400, 0, 0, 20);
      fill(3, 2, 8, alpha);
      ellipse(cx, cy, r * 2, r * 2);
    }
  }
}

function setup(){
  createCanvas(1600,2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  pixelDensity(1);
  draw();
}

function draw(){
  background(10,8,7);
  drawSky();
  drawMoon();
  drawDistantHills();
  drawGround();
  drawCrows();
  drawRoots();
  drawSkull();
  drawFlowersFromEyes();
  drawGrain();
  drawVignette();
}

function drawSky(){
  for(let y=0;y<height*0.65;y++){
    let t=y/(height*0.65);
    let r=lerp(18,60,t*t);
    let g=lerp(14,38,t*t);
    let b=lerp(28,52,t*t);
    let n=noise(y*0.01)*10-5;
    stroke(r+n,g+n,b+n);
    line(0,y,width,y);
  }
}

function drawMoon(){
  let mx=width*0.78, my=height*0.22, mr=110;
  noStroke();
  for(let r=mr*4;r>mr;r-=3){
    let a=map(r,mr,mr*4,40,0);
    fill(220,200,170,a*0.15);
    ellipse(mx,my,r*2,r*2);
  }
  fill(230,215,185);
  ellipse(mx,my,mr*2,mr*2);
  for(let i=0;i<30;i++){
    let a=random(TWO_PI), d=random(mr*0.9);
    let x=mx+cos(a)*d, y=my+sin(a)*d;
    fill(180,160,130,random(40,90));
    ellipse(x,y,random(8,25),random(8,25));
  }
  fill(10,8,7,220);
  ellipse(mx+mr*0.55,my-mr*0.1,mr*1.4,mr*1.5);
}

function drawDistantHills(){
  noStroke();
  for(let layer=0;layer<3;layer++){
    let baseY=height*0.55+layer*40;
    let col=[25+layer*8,18+layer*5,30+layer*6];
    fill(col[0],col[1],col[2]);
    beginShape();
    vertex(0,height);
    for(let x=0;x<=width;x+=10){
      let n=noise(x*0.003+layer*10,layer)*80;
      vertex(x,baseY+n);
    }
    vertex(width,height);
    endShape(CLOSE);
  }
}

function drawGround(){
  let topY=height*0.72;
  noStroke();
  for(let y=topY;y<height;y++){
    let t=(y-topY)/(height-topY);
    let r=lerp(75,35,t);
    let g=lerp(50,22,t);
    let b=lerp(35,14,t);
    for(let x=0;x<width;x+=4){
      let n=noise(x*0.01,y*0.01)*20-10;
      fill(r+n,g+n*0.7,b+n*0.4);
      rect(x,y,5,2);
    }
  }
}

function drawCrows(){
  fill(5);
  noStroke();
  let crows=[[300,350,0.9],[500,280,0.6],[850,380,0.7],[1250,450,0.5],[1380,300,0.8],[200,500,0.4]];
  for(let c of crows){
    drawCrow(c[0],c[1],c[2]);
  }
}

function drawCrow(x,y,s){
  push();
  translate(x,y);
  scale(s);
  fill(8,6,5);
  beginShape();
  vertex(-30,0);
  bezierVertex(-20,-12,-5,-10,5,-5);
  bezierVertex(15,-8,25,-5,30,0);
  bezierVertex(20,3,10,2,0,2);
  bezierVertex(-10,4,-20,3,-30,0);
  endShape(CLOSE);
  beginShape();
  vertex(0,-2);
  bezierVertex(-15,-20,-25,-18,-35,-10);
  bezierVertex(-20,-8,-10,-5,0,-2);
  endShape(CLOSE);
  beginShape();
  vertex(0,-2);
  bezierVertex(15,-20,25,-18,35,-10);
  bezierVertex(20,-8,10,-5,0,-2);
  endShape(CLOSE);
  pop();
}

function drawRoots(){
  noFill();
  let cx=width/2, baseY=height*0.78;
  for(let i=0;i<18;i++){
    let startX=cx+random(-180,180);
    let startY=baseY+random(-20,40);
    stroke(40+random(-10,10),25+random(-5,5),15,180);
    strokeWeight(random(1,3));
    beginShape();
    let x=startX,y=startY;
    for(let j=0;j<25;j++){
      curveVertex(x,y);
      x+=random(-20,20);
      y+=random(10,30);
    }
    endShape();
  }
}

function drawSkull(){
  let cx=width/2, cy=height*0.78;
  push();
  translate(cx,cy);
  rotate(-0.04);

  // soft glow behind
  noStroke();
  for(let r=500;r>0;r-=8){
    fill(60,45,30,(500-r)*0.05);
    ellipse(0,-40,r*1.3,r*1.4);
  }

  // main skull shape (cranium)
  let skullW=420, skullH=460;
  // shading layers
  for(let i=0;i<8;i++){
    fill(lerpColor(color(50,35,25),color(210,190,155),i/8));
    let s=1-i*0.04;
    ellipse(0,-60,skullW*s,skullH*s*0.95);
  }

  // top highlight
  for(let i=0;i<5;i++){
    fill(230,215,180,30);
    ellipse(-30-i*10,-160-i*15,250-i*30,180-i*25);
  }

  // jaw
  fill(180,160,130);
  beginShape();
  vertex(-180,120);
  bezierVertex(-200,200,-150,260,-80,280);
  bezierVertex(-30,290,30,290,80,280);
  bezierVertex(150,260,200,200,180,120);
  bezierVertex(150,160,80,180,0,180);
  bezierVertex(-80,180,-150,160,-180,120);
  endShape(CLOSE);

  // jaw shading
  fill(90,65,45,150);
  beginShape();
  vertex(-160,180);
  bezierVertex(-140,240,-80,270,0,275);
  bezierVertex(80,270,140,240,160,180);
  bezierVertex(80,200,0,210,-80,200);
  endShape(CLOSE);

  // eye sockets
  drawEyeSocket(-110,-50,95,110);
  drawEyeSocket(110,-50,95,110);

  // nasal cavity
  fill(15,10,8);
  beginShape();
  vertex(0,50);
  bezierVertex(-40,60,-50,110,-30,150);
  bezierVertex(-15,170,15,170,30,150);
  bezierVertex(50,110,40,60,0,50);
  endShape(CLOSE);
  fill(5,3,2);
  triangle(-10,90,10,90,0,145);

  // teeth row
  for(let i=-5;i<=5;i++){
    let tx=i*22;
    let ty=200+abs(i)*2;
    fill(220,205,170);
    stroke(80,55,35);
    strokeWeight(1.5);
    rect(tx-9,ty,18,35,3);
    // lower teeth
    fill(210,195,160);
    rect(tx-9,ty+38,18,30,3);
  }

  // cracks
  noFill();
  stroke(60,40,25,200);
  strokeWeight(1.8);
  drawCrack(-80,-200,-50,-80,8);
  drawCrack(60,-180,90,-60,7);
  drawCrack(0,-240,20,-140,6);
  stroke(40,25,15,180);
  strokeWeight(1);
  drawCrack(-150,-100,-100,50,5);
  drawCrack(150,-100,100,50,5);

  // texture speckles
  noStroke();
  for(let i=0;i<400;i++){
    let a=random(TWO_PI);
    let r=random(220);
    let x=cos(a)*r*0.9, y=sin(a)*r-60;
    if(abs(x)<200 && y<220 && y>-280){
      fill(80,55,35,random(20,70));
      ellipse(x,y,random(1,4),random(1,4));
    }
  }
  for(let i=0;i<200;i++){
    let x=random(-180,180), y=random(-250,100);
    fill(240,225,190,random(15,40));
    ellipse(x,y,random(1,3),random(1,3));
  }

  pop();
}

function drawEyeSocket(x,y,w,h){
  // outer shadow
  fill(20,12,8);
  ellipse(x,y,w*1.15,h*1.15);
  // deep
  fill(5,3,2);
  ellipse(x,y,w,h);
  // inner highlight
  fill(40,25,15,120);
  ellipse(x-w*0.15,y-h*0.15,w*0.6,h*0.55);
  // rim light
  noFill();
  stroke(200,180,150,80);
  strokeWeight(2);
  arc(x,y,w*1.05,h*1.05,-PI*0.8,-PI*0.2);
  noStroke();
}

function drawCrack(x1,y1,x2,y2,segs){
  beginShape();
  vertex(x1,y1);
  for(let i=1;i<segs;i++){
    let t=i/segs;
    let x=lerp(x1,x2,t)+random(-15,15);
    let y=lerp(y1,y2,t)+random(-8,8);
    vertex(x,y);
  }
  vertex(x2,y2);
  endShape();
}

function drawFlowersFromEyes(){
  let cx=width/2, cy=height*0.78;
  // left eye stems
  drawStemCluster(cx-110-3,cy-55,9,[-0.3,-0.8,0.1]);
  // right eye stems
  drawStemCluster(cx+110+3,cy-55,9,[0.3,-0.8,-0.1]);
}

function drawStemCluster(bx,by,count,angles){
  for(let i=0;i<count;i++){
    let baseAngle=angles[i%3]+random(-0.2,0.2);
    let len=random(180,380);
    let stem=[];
    let x=bx,y=by;
    let a=baseAngle-HALF_PI;
    for(let j=0;j<20;j++){
      stem.push({x,y});
      a+=random(-0.15,0.15);
      x+=cos(a)*len/20;
      y+=sin(a)*len/20;
    }
    // stem
    noFill();
    stroke(60,80,45,220);
    strokeWeight(random(2,4));
    beginShape();
    for(let p of stem) curveVertex(p.x,p.y);
    endShape();

    // leaves
    noStroke();
    for(let k=3;k<stem.length-3;k+=3){
      if(random()>0.5){
        let p=stem[k];
        fill(55,75,40,200);
        push();
        translate(p.x,p.y);
        rotate(a+PI/3*random(-1,1));
        ellipse(0,0,22,8);
        pop();
      }
    }

    // flower at tip
    let tip=stem[stem.length-1];
    drawWitheredFlower(tip.x,tip.y,random(18,32));
  }
}

function drawWitheredFlower(x,y,size){
  push();
  translate(x,y);
  rotate(random(TWO_PI));
  let petals=floor(random(5,8));
  // petals - faded tones
  let palette=[[180,150,110],[160,120,90],[200,170,130],[140,90,70],[170,140,100]];
  let c=palette[floor(random(palette.length))];
  for(let i=0;i<petals;i++){
    push();
    rotate(i*TWO_PI/petals+random(-0.1,0.1));
    fill(c[0],c[1],c[2],220);
    noStroke();
    ellipse(0,-size*0.7,size*0.5,size*1.1);
    // wilted tip
    fill(c[0]*0.7,c[1]*0.6,c[2]*0.5,180);
    ellipse(0,-size*1.1,size*0.3,size*0.3);
    pop();
  }
  // center
  fill(60,40,25);
  ellipse(0,0,size*0.5,size*0.5);
  fill(90,60,35);
  for(let i=0;i<8;i++){
    let a=random(TWO_PI), r=random(size*0.2);
    ellipse(cos(a)*r,sin(a)*r,2,2);
  }
  pop();
}

function drawGrain(){
  noStroke();
  for(let i=0;i<8000;i++){
    let x=random(width), y=random(height);
    let v=random(-30,30);
    fill(v>0?255:0,abs(v)*0.8);
    rect(x,y,1,1);
  }
}

function drawVignette(){
  noFill();
  for(let r=max(width,height);r>0;r-=20){
    let a=map(r,0,max(width,height),120,0);
    stroke(0,0,0,a);
    strokeWeight(25);
    ellipse(width/2,height/2,r*1.1,r*1.2);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noStroke();

  drawSky();
  drawMilkyWay();
  drawStars();
  drawMoon();
  drawHorizonHaze();
  drawLake();
  drawMoonReflection();
  drawLowMist();
  drawBoat();
  drawFigure();
  drawParticles();
  drawParticleReflections();
  drawGrain();

  noLoop();
}

function drawSky() {
  for (let y = 0; y < 1300; y++) {
    let t = y / 1300;
    let tt = pow(t, 0.55);
    let c1 = color(4, 4, 16);
    let c2 = color(55, 22, 55);
    let c = lerpColor(c1, c2, tt);
    let n = noise(y * 0.02) * 6 - 3;
    fill(red(c) + n, green(c) + n, blue(c) + n);
    rect(0, y, width, 1);
  }
}

function drawMilkyWay() {
  // Voie lactée diagonale très subtile
  for (let i = 0; i < 4000; i++) {
    let t = random();
    // ligne diagonale du bas-gauche vers haut-droite
    let x = lerp(-100, 1700, t) + random(-180, 180) * (1 - abs(randomGaussian(0, 0.4)));
    let y = lerp(1100, -50, t) + random(-120, 120) * (1 - abs(randomGaussian(0, 0.3)));
    if (x < 0 || x > width || y < 0 || y > 1280) continue;
    let a = random(8, 22);
    fill(200, 190, 220, a);
    ellipse(x, y, random(0.6, 1.4), random(0.6, 1.4));
  }
}

function drawStars() {
  for (let i = 0; i < 500; i++) {
    let x = random(width);
    let y = random(0, 1260);
    let s = random(0.3, 2.2);
    let bright = random(100, 245);
    if (y > 1000) bright *= (1260 - y) / 260;
    // teintes légèrement variées
    let r = 220 + random(-15, 20);
    let g = 220 + random(-20, 15);
    let b = 210 + random(-10, 30);
    fill(r, g, b, bright);
    ellipse(x, y, s, s);
    if (s > 1.6 && random() < 0.7) {
      fill(r, g, b, 25);
      ellipse(x, y, s * 4.5, s * 4.5);
      fill(r, g, b, 10);
      ellipse(x, y, s * 9, s * 9);
    }
  }
}

function drawMoon() {
  let mx = 1180, my = 330, mr = 115;

  // Halo externe très doux
  for (let r = mr * 5; r > mr; r -= 3) {
    let alpha = map(r, mr, mr * 5, 35, 0);
    fill(235, 225, 200, alpha);
    ellipse(mx, my, r * 2, r * 2);
  }

  // Disque lunaire avec dégradé radial
  for (let r = mr * 2; r > 0; r -= 2) {
    let t = r / (mr * 2);
    let c = lerpColor(color(250, 242, 220), color(215, 205, 180), 1 - t);
    fill(c);
    ellipse(mx, my, r, r);
  }

  // Ombrage de phase (crescent sombre à gauche)
  fill(170, 160, 140, 55);
  ellipse(mx - 25, my + 5, mr * 2, mr * 2);
  fill(248, 240, 218);
  ellipse(mx + 6, my - 3, mr * 1.92, mr * 1.92);

  // Cratères / mers lunaires
  fill(205, 195, 170, 90);
  ellipse(mx - 28, my - 18, 22, 20);
  ellipse(mx + 28, my + 32, 16, 15);
  ellipse(mx + 12, my - 42, 11, 10);
  ellipse(mx - 8, my + 25, 9, 8);
  fill(195, 185, 160, 60);
  ellipse(mx - 45, my + 10, 14, 12);
  ellipse(mx + 45, my - 15, 10, 9);
}

function drawHorizonHaze() {
  for (let y = 1180; y < 1320; y++) {
    let t = (y - 1180) / 140;
    let alpha = sin(t * PI) * 70;
    fill(110, 50, 75, alpha);
    rect(0, y, width, 1);
  }
  // Ligne d'horizon très fine
  fill(180, 110, 130, 40);
  rect(0, 1298, width, 3);
}

function drawLake() {
  for (let y = 1300; y < height; y++) {
    let t = (y - 1300) / (height - 1300);
    let c1 = color(45, 18, 48);
    let c2 = color(2, 2, 8);
    let c = lerpColor(c1, c2, pow(t, 0.6));
    // variation bruitée pour texture d'eau
    let n = noise(y * 0.03) * 5 - 2.5;
    fill(red(c) + n, green(c) + n, blue(c) + n);
    rect(0, y, width, 1);
  }
  // Vaguelettes horizontales
  for (let y = 1318; y < height; y += 6) {
    let distT = (y - 1318) / (height - 1318);
    let alpha = map(distT, 0, 1, 35, 3);
    stroke(120, 70, 95, alpha);
    strokeWeight(0.6);
    let segLen = random(200, 600);
    for (let x = random(-50, 50); x < width; x += segLen + random(40, 120)) {
      line(x, y, x + segLen, y);
    }
  }
  noStroke();
}

function drawMoonReflection() {
  let mx = 1180;
  for (let y = 1305; y < height; y += 2) {
    let d = y - 1305;
    let spread = d * 0.18;
    let alpha = map(y, 1305, height, 95, 8);
    alpha *= noise(y * 0.05) + 0.3;
    let w = 5 + spread + noise(y * 0.04) * 10;
    let xOff = (noise(y * 0.02) - 0.5) * 40;
    fill(230, 220, 190, alpha);
    ellipse(mx + xOff, y, w, 1.6);
    if (d < 300 && random() < 0.4) {
      fill(255, 245, 215, alpha * 0.5);
      ellipse(mx + xOff, y, w * 0.5, 1.2);
    }
  }
}

function drawLowMist() {
  for (let i = 0; i < 60; i++) {
    let x = random(width);
    let y = 1280 + random(-10, 60);
    let w = random(200, 600);
    let h = random(10, 30);
    fill(160, 120, 150, random(5, 15));
    ellipse(x, y, w, h);
  }
}

function drawBoat() {
  let bx = 800, by = 1500;

  // Ombre/reflet sous la barque
  fill(0, 0, 0, 140);
  ellipse(bx, by + 22, 340, 22);
  fill(0, 0, 0, 70);
  ellipse(bx, by + 35, 280, 14);

  // Coque (arc sombre)
  fill(8, 4, 10);
  beginShape();
  vertex(bx - 160, by);
  bezierVertex(bx - 130, by + 42, bx + 130, by + 42, bx + 160, by);
  vertex(bx + 155, by - 4);
  vertex(bx - 155, by - 4);
  endShape(CLOSE);

  // Intérieur plus sombre
  fill(3, 1, 5);
  beginShape();
  vertex(bx - 150, by - 2);
  bezierVertex(bx - 120, by + 12, bx + 120, by + 12, bx + 150, by - 2);
  endShape(CLOSE);

  // Bord supérieur (ligne claire)
  stroke(55, 32, 45);
  strokeWeight(1.6);
  line(bx - 152, by - 3, bx + 152, by - 3);
  noStroke();
}

function drawFigure() {
  let fx = 800, fy = 1498;

  // Cape/robe longue - partie basse solide
  fill(4, 2, 7);
  beginShape();
  vertex(fx - 45, fy - 2);
  vertex(fx - 55, fy - 120);
  vertex(fx - 48, fy - 220);
  vertex(fx - 38, fy - 310);
  vertex(fx - 32, fy - 380);
  vertex(fx + 32, fy - 380);
  vertex(fx + 38, fy - 310);
  vertex(fx + 48, fy - 220);
  vertex(fx + 55, fy - 120);
  vertex(fx + 45, fy - 2);
  endShape(CLOSE);

  // Épaules (fragmentées)
  for (let i = 0; i < 600; i++) {
    let t = random();
    let y = fy - 380 - t * 80;
    let halfW = lerp(42, 20, t);
    let x = fx + random(-halfW, halfW);
    if (random() < t * 0.3) x += random(-20, 20);
    let s = lerp(4, 1.5, t);
    fill(4, 2, 7, map(t, 0, 1, 255, 120));
    ellipse(x, y, s, s);
  }

  // Tête - très fragmentée, à peine suggérée
  for (let i = 0; i < 250; i++) {
    let t = random();
    let y = fy - 460 - t * 60;
    let halfW = lerp(18, 6, t);
    let x = fx + random(-halfW, halfW);
    if (random() < t * 0.5) x += random(-25, 25);
    let s = lerp(3, 1, t);
    fill(4, 2, 7, map(t, 0, 1, 200, 40));
    ellipse(x, y, s, s);
  }
}

function drawParticles() {
  let fx = 800;
  let startY = 1100;
  let moonX = 1180, moonY = 330;

  for (let i = 0; i < 4500; i++) {
    let t = pow(random(), 1.2);
    // Position de départ : autour du haut de la silhouette
    let sx = fx + randomGaussian(0, 18);
    let sy = startY + random(-40, 40);

    // Interpolation vers la lune
    let px = lerp(sx, moonX, t);
    let py = lerp(sy, moonY, t);

    // Dispersion qui augmente
    let spread = t * 160;
    px += randomGaussian(0, spread * 0.4);
    py += randomGaussian(0, spread * 0.15);

    // Oscillation organique
    let n = (noise(px * 0.008, py * 0.008) - 0.5) * 50;
    px += n;

    // Taille et opacité
    let size = lerp(4, 1.2, t) * random(0.6, 1.4);
    let alpha = lerp(230, 70, t);

    // Couleur : or chaud près de la silhouette, blanc froid près de la lune
    let r = lerp(245, 255, t);
    let g = lerp(200, 245, t);
    let b = lerp(130, 230, t);

    fill(r, g, b, alpha);
    ellipse(px, py, size, size);

    if (random() < 0.18) {
      fill(r, g, b, alpha * 0.22);
      ellipse(px, py, size * 4.5, size * 4.5);
    }
    if (size > 2.5 && random() < 0.08) {
      fill(255, 250, 230, alpha * 0.5);
      ellipse(px, py, size * 0.6, size * 0.6);
    }
  }

  // Quelques particules plus grosses, plus rares, pour donner du corps
  for (let i = 0; i < 60; i++) {
    let t = pow(random(), 1.5);
    let px = lerp(fx, moonX, t) + randomGaussian(0, t * 90);
    let py = lerp(startY, moonY, t) + randomGaussian(0, t * 40);
    let size = random(4, 7);
    let alpha = lerp(180, 50, t);
    fill(250, 220, 160, alpha);
    ellipse(px, py, size, size);
    fill(255, 240, 200, alpha * 0.3);
    ellipse(px, py, size * 5, size * 5);
  }
}

function drawParticleReflections() {
  let fx = 800;
  for (let i = 0; i < 250; i++) {
    let x = fx + randomGaussian(0, 150);
    let y = 1520 + random(0, 460);
    let d = y - 1520;
    let alpha = map(d, 0, 460, 100, 8);
    let size = random(1, 3);
    fill(235, 205, 150, alpha);
    ellipse(x + random(-4, 4), y, size * 2.4, size * 0.7);
  }
}

function drawGrain() {
  for (let i = 0; i < 40000; i++) {
    let x = random(width);
    let y = random(height);
    let bright = random() < 0.5 ? 255 : 0;
    fill(bright, bright, bright, random(4, 14));
    rect(x, y, 1, 1);
  }
  // Vignette douce
  for (let r = max(width, height); r > 0; r -= 4) {
    let t = r / max(width, height);
    if (t < 0.7) continue;
    let alpha = map(t, 0.7, 1, 0, 90);
    fill(0, 0, 0, alpha);
    noStroke();
    ellipse(width / 2, height / 2, r, r * 1.1);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function draw() {
  // sky gradient with noise texture
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r, g, b;
    if (t < 0.4) {
      let lt = t / 0.4;
      r = lerp(10, 45, lt); g = lerp(14, 27, lt); b = lerp(42, 78, lt);
    } else if (t < 0.75) {
      let lt = (t - 0.4) / 0.35;
      r = lerp(45, 74, lt); g = lerp(27, 26, lt); b = lerp(78, 42, lt);
    } else {
      let lt = (t - 0.75) / 0.25;
      r = lerp(74, 35, lt); g = lerp(26, 20, lt); b = lerp(42, 35, lt);
    }
    let n = noise(y * 0.02) * 12 - 6;
    stroke(r + n, g + n, b + n);
    line(0, y, width, y);
  }

  // stars
  noStroke();
  for (let i = 0; i < 180; i++) {
    let x = random(width);
    let y = random(height * 0.55);
    let s = random(0.5, 2.2);
    fill(230, 220, 200, random(60, 180));
    ellipse(x, y, s, s);
  }

  drawMoon(width * 0.58, height * 0.3, 260);
  drawHorizon();

  push();
  translate(width * 0.42, height * 0.88);
  branch(300, -HALF_PI, 14, 11);
  pop();

  drawLeaves();
  drawGroundMist();
  drawSouls();
  drawGrain();
}

function drawMoon(cx, cy, r) {
  noStroke();
  for (let i = 80; i > 0; i--) {
    let rr = r + i * 9;
    let a = map(i, 80, 0, 0, 14);
    fill(240, 220, 190, a);
    ellipse(cx, cy, rr * 2, rr * 2);
  }
  fill(244, 232, 208);
  ellipse(cx, cy, r * 2, r * 2);

  for (let i = 0; i < 55; i++) {
    let ang = random(TWO_PI);
    let d = pow(random(), 0.7) * r * 0.9;
    let x = cx + cos(ang) * d;
    let y = cy + sin(ang) * d;
    let sz = random(14, 70);
    let n = noise(x * 0.012, y * 0.012);
    fill(200 - n * 60, 180 - n * 60, 160 - n * 50, 40 + n * 90);
    ellipse(x, y, sz, sz * 0.92);
  }

  for (let i = 0; i < 24; i++) {
    noFill();
    stroke(55, 35, 45, 10);
    strokeWeight(4);
    arc(cx + i * 2, cy, r * 2 - i * 6, r * 2 - i * 6, PI * 0.15, PI * 1.15);
  }

  noStroke();
  for (let i = 20; i > 0; i--) {
    fill(255, 240, 210, (20 - i) * 4);
    ellipse(cx - r * 0.2, cy - r * 0.2, r * 0.9 - i * 4, r * 0.9 - i * 4);
  }
}

function drawHorizon() {
  noStroke();
  for (let i = 0; i < 40; i++) {
    let y = height * 0.72 + i * 3;
    fill(50, 25, 40, 6 + noise(i * 0.2) * 10);
    rect(0, y, width, 4);
  }
}

function branch(len, ang, weight, depth) {
  if (depth <= 0 || len < 3) return;
  strokeWeight(weight);
  stroke(6, 4, 8);
  let x2 = cos(ang) * len;
  let y2 = sin(ang) * len;
  let segs = 7;
  let px = 0, py = 0;
  for (let s = 1; s <= segs; s++) {
    let t = s / segs;
    let wob = (noise(s * 0.4, depth * 0.3, len * 0.01) - 0.5) * len * 0.08 * (1 - t);
    let nx = lerp(0, x2, t) + wob;
    let ny = lerp(0, y2, t);
    line(px, py, nx, ny);
    px = nx; py = ny;
  }
  push();
  translate(x2, y2);
  let spread = 0.42 + noise(depth * 1.7) * 0.28;
  let shrink = 0.66 + noise(depth * 2.3) * 0.14;
  branch(len * shrink, ang - spread, weight * 0.76, depth - 1);
  branch(len * shrink, ang + spread * 0.95, weight * 0.76, depth - 1);
  if (depth > 5 && noise(depth * 3.1) > 0.55) {
    branch(len * 0.65, ang + (noise(depth) - 0.5) * 0.4, weight * 0.55, depth - 2);
  }
  pop();
}

function drawLeaves() {
  noStroke();
  for (let i = 0; i < 520; i++) {
    let x = noise(i * 0.27) * width * 1.1 - width * 0.05;
    let y = noise(i * 0.27 + 100) * height * 1.1;
    let sz = noise(i * 0.4) * 9 + 2.5;
    let bright = noise(i * 0.19 + 50);
    let r, g, b, a;
    if (bright > 0.65) { r = 210; g = 180; b = 115; a = 190; }
    else if (bright > 0.4) { r = 160; g = 100; b = 60; a = 170; }
    else if (bright > 0.2) { r = 90; g = 55; b = 45; a = 180; }
    else { r = 35; g = 22; b = 28; a = 210; }
    fill(r, g, b, a);
    push();
    translate(x, y);
    rotate(noise(i * 1.3) * TWO_PI);
    ellipse(0, 0, sz * 1.6, sz * 0.7);
    pop();
  }
}

function drawGroundMist() {
  noStroke();
  for (let y = height * 0.76; y < height; y += 5) {
    let t = (y - height * 0.76) / (height * 0.24);
    let a = (1 - t) * 20 + t * 70;
    fill(85, 65, 90, a);
    beginShape();
    for (let x = 0; x <= width; x += 30) {
      let yy = y + noise(x * 0.004, y * 0.008) * 35;
      vertex(x, yy);
    }
    vertex(width, height);
    vertex(0, height);
    endShape(CLOSE);
  }

  fill(18, 12, 22, 140);
  for (let i = 0; i < 8; i++) {
    let x = noise(i * 2.1 + 200) * width;
    let baseY = height * 0.91 + noise(i * 3 + 10) * 60;
    let w = 38 + noise(i + 5) * 28;
    let h = 55 + noise(i + 15) * 45;
    rect(x - w / 2, baseY - h, w, h, w * 0.35, w * 0.35, 0, 0);
  }
}

function drawSouls() {
  noStroke();
  for (let i = 0; i < 22; i++) {
    let x = noise(i * 0.71 + 300) * width;
    let y = noise(i * 0.71 + 400) * height * 0.75 + height * 0.1;
    let r = 3.5 + noise(i + 7) * 5;
    for (let j = 12; j > 0; j--) {
      fill(245, 225, 175, (12 - j) * 6);
      ellipse(x, y, r * j * 0.55, r * j * 0.55);
    }
    fill(255, 245, 210);
    ellipse(x, y, r, r);
  }
}

function drawGrain() {
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let n = (random() - 0.5) * 22;
    pixels[i] = constrain(pixels[i] + n, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + n, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + n, 0, 255);
  }
  updatePixels();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  background(0);
  noLoop();

  // Sky gradient - deep indigo to dark blood red at horizon
  for (let y = 0; y < 1400; y++) {
    let inter = y / 1400;
    let r = lerp(8, 80, pow(inter, 0.5));
    let g = lerp(2, 10, pow(inter, 0.6));
    let b = lerp(25, 15, pow(inter, 0.4));
    stroke(r, g, b);
    line(0, y, 1600, y);
  }

  // Horizon glow
  for (let y = 1200; y < 1500; y++) {
    let inter = (y - 1200) / 300;
    let alpha = sin(inter * PI) * 120;
    let r = lerp(80, 160, inter);
    let g = lerp(10, 20, inter);
    let b = lerp(15, 5, inter);
    stroke(r, g, b, alpha);
    line(0, y, 1600, y);
  }

  // Ground - cracked dark earth
  for (let y = 1400; y < 2000; y++) {
    let inter = (y - 1400) / 600;
    let r = lerp(35, 10, inter);
    let g = lerp(12, 5, inter);
    let b = lerp(8, 3, inter);
    stroke(r, g, b);
    line(0, y, 1600, y);
  }

  // Cracks in the earth
  drawCracks();

  // Dying sun at horizon
  drawSun(800, 1380);

  // Dead tree
  drawTree(800, 1500);

  // Dissolving particles rising from tree
  drawParticles();

  // Falling debris near base
  drawFallenLeaves();

  // Subtle stars in upper sky
  drawStars();

  // Vignette
  drawVignette();
}

function drawSun(cx, cy) {
  noStroke();
  // Outer glow
  for (let r = 300; r > 0; r -= 2) {
    let inter = r / 300;
    let alpha = (1 - inter) * 40;
    fill(180, 30, 10, alpha);
    ellipse(cx, cy, r * 2, r * 2);
  }
  // Sun body
  for (let r = 120; r > 0; r -= 1) {
    let inter = r / 120;
    let red = lerp(220, 120, inter);
    let green = lerp(60, 10, inter);
    let blue = lerp(10, 5, inter);
    fill(red, green, blue, 200);
    ellipse(cx, cy, r * 2, r * 2);
  }
  // Corona rays
  for (let i = 0; i < 30; i++) {
    let angle = random(-PI, 0);
    let len = random(150, 400);
    let x2 = cx + cos(angle) * len;
    let y2 = cy + sin(angle) * len;
    stroke(160, 30, 5, random(10, 40));
    strokeWeight(random(1, 4));
    drawNoisyLine(cx, cy, x2, y2, 30);
  }
}

function drawNoisyLine(x1, y1, x2, y2, segments) {
  noFill();
  beginShape();
  for (let i = 0; i <= segments; i++) {
    let t = i / segments;
    let x = lerp(x1, x2, t);
    let y = lerp(y1, y2, t);
    let n = noise(x * 0.01, y * 0.01) * 20 - 10;
    vertex(x + n, y + n);
  }
  endShape();
}

function drawTree(baseX, baseY) {
  // Main trunk
  stroke(20, 10, 8);
  strokeWeight(2);

  drawBranch(baseX, baseY, -PI / 2, 280, 45, 0);
}

function drawBranch(x, y, angle, len, thickness, depth) {
  if (depth > 8 || thickness < 1.5) return;

  let endX = x + cos(angle) * len;
  let endY = y + sin(angle) * len;

  // Draw branch with noise
  stroke(25 + depth * 3, 12 + depth * 2, 8 + depth);
  strokeWeight(thickness);
  noFill();

  beginShape();
  let segments = 12;
  for (let i = 0; i <= segments; i++) {
    let t = i / segments;
    let px = lerp(x, endX, t);
    let py = lerp(y, endY, t);
    let n = noise(px * 0.005, py * 0.005, depth) * thickness * 0.8;
    vertex(px + n, py + n * 0.5);
  }
  endShape();

  // Secondary line for texture
  strokeWeight(thickness * 0.4);
  stroke(35 + depth * 2, 18 + depth, 10);
  beginShape();
  for (let i = 0; i <= segments; i++) {
    let t = i / segments;
    let px = lerp(x, endX, t);
    let py = lerp(y, endY, t);
    let n = noise(px * 0.008 + 100, py * 0.008, depth) * thickness * 0.5;
    vertex(px + n + thickness * 0.2, py + n * 0.3);
  }
  endShape();

  // Branches
  let numBranches = depth < 3 ? floor(random(2, 4)) : floor(random(1, 3));
  for (let i = 0; i < numBranches; i++) {
    let newAngle = angle + random(-0.7, 0.7);
    let newLen = len * random(0.55, 0.8);
    let newThick = thickness * random(0.5, 0.75);
    drawBranch(endX, endY, newAngle, newLen, newThick, depth + 1);
  }
}

function drawParticles() {
  noStroke();
  // Particles dissolving upward from tree canopy area
  for (let i = 0; i < 3000; i++) {
    let startX = 800 + randomGaussian() * 250;
    let startY = random(400, 1200);

    // More particles higher up (more dissolved)
    let heightFactor = map(startY, 1200, 400, 0, 1);
    let spread = lerp(200, 500, heightFactor);
    let px = startX + randomGaussian() * spread * 0.3;
    let py = startY - random(0, 300 * heightFactor);

    if (px < 0 || px > 1600 || py < 0) continue;

    // Size decreases as they rise
    let size = lerp(8, 2, heightFactor) * random(0.5, 1.5);

    // Color: from dark bark to pale ash to faint glow
    let r, g, b, a;
    let colorPhase = noise(px * 0.003, py * 0.003);
    if (colorPhase < 0.3) {
      r = lerp(40, 80, heightFactor);
      g = lerp(20, 30, heightFactor);
      b = lerp(15, 25, heightFactor);
    } else if (colorPhase < 0.6) {
      r = lerp(100, 180, heightFactor);
      g = lerp(60, 100, heightFactor);
      b = lerp(40, 50, heightFactor);
    } else {
      r = lerp(150, 220, heightFactor);
      g = lerp(80, 140, heightFactor);
      b = lerp(50, 80, heightFactor);
    }
    a = lerp(200, 60, heightFactor) * random(0.5, 1);

    fill(r, g, b, a);

    // Shape varies - some are dots, some are elongated
    push();
    translate(px, py);
    rotate(random(TWO_PI));
    let elongation = random(1, 3);
    ellipse(0, 0, size, size * elongation);
    pop();
  }

  // Bright ember particles
  for (let i = 0; i < 200; i++) {
    let px = 800 + randomGaussian() * 350;
    let py = random(300, 1100);
    let heightFactor = map(py, 1100, 300, 0, 1);
    let size = random(1, 4) * (1 - heightFactor * 0.5);

    fill(220 + random(35), 100 + random(80), 20 + random(40), random(80, 200));
    ellipse(px, py, size, size);

    // Glow
    fill(200, 60, 20, random(10, 30));
    ellipse(px, py, size * 4, size * 4);
  }
}

function drawCracks() {
  stroke(15, 5, 3, 150);
  for (let i = 0; i < 40; i++) {
    let sx = random(100, 1500);
    let sy = random(1420, 1950);
    strokeWeight(random(0.5, 2.5));
    let x = sx;
    let y = sy;
    let len = random(50, 200);
    let angle = random(-0.3, 0.3) + (random() > 0.5 ? 0 : PI);
    noFill();
    beginShape();
    vertex(x, y);
    for (let j = 0; j < 8; j++) {
      angle += random(-0.5, 0.5);
      let step = random(10, len / 4);
      x += cos(angle) * step;
      y += sin(angle) * step;
      vertex(x, y);
    }
    endShape();
  }
}

function drawFallenLeaves() {
  noStroke();
  for (let i = 0; i < 60; i++) {
    let px = random(400, 1200);
    let py = random(1480, 1700);
    let size = random(4, 15);
    let angle = random(TWO_PI);

    push();
    translate(px, py);
    rotate(angle);

    let r = random(30, 80);
    let g = random(15, 35);
    let b = random(5, 20);
    fill(r, g, b, random(100, 200));
    beginShape();
    vertex(0, -size);
    bezierVertex(size * 0.6, -size * 0.5, size * 0.6, size * 0.5, 0, size);
    bezierVertex(-size * 0.6, size * 0.5, -size * 0.6, -size * 0.5, 0, -size);
    endShape(CLOSE);
    pop();
  }
}

function drawStars() {
  noStroke();
  for (let i = 0; i < 150; i++) {
    let px = random(0, 1600);
    let py = random(0, 800);
    let size = random(0.5, 3);
    let brightness = random(80, 255);
    let alpha = random(50, 180) * (1 - py / 800);
    fill(brightness, brightness - 20, brightness - 40, alpha);
    ellipse(px, py, size, size);
  }
}

function drawVignette() {
  // Dark edges
  noStroke();
  for (let i = 0; i < 300; i++) {
    let alpha = map(i, 0, 300, 80, 0);
    fill(0, 0, 0, alpha);

    // Top
    rect(0, i * 2, 1600, 3);
    // Bottom
    rect(0, 2000 - i * 2, 1600, 3);
    // Left
    rect(i * 1.5, 0, 2, 2000);
    // Right
    rect(1600 - i * 1.5, 0, 2, 2000);
  }

  // Corner darkening
  for (let corner = 0; corner < 4; corner++) {
    let cx = corner % 2 === 0 ? 0 : 1600;
    let cy = corner < 2 ? 0 : 2000;
    for (let r = 600; r > 0; r -= 3) {
      let alpha = map(r, 0, 600, 0, 40);
      fill(0, 0, 0, alpha);
      ellipse(cx, cy, r * 2, r * 2);
    }
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function draw() {
  background(10, 8, 14);

  // Deep background gradient with noise texture
  loadPixels();
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let t = y / height;
      let n = noise(x * 0.003, y * 0.003) * 0.3;
      let r = lerp(42, 6, t) + n * 15;
      let g = lerp(32, 4, t) + n * 10;
      let b = lerp(48, 16, t) + n * 20;
      let idx = (y * width + x) * 4;
      pixels[idx] = r;
      pixels[idx + 1] = g;
      pixels[idx + 2] = b;
      pixels[idx + 3] = 255;
    }
  }
  updatePixels();

  // Subtle vertical light column
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let colWidth = lerp(300, 800, t * t);
    let alpha = lerp(18, 2, t);
    noStroke();
    for (let i = 0; i < 5; i++) {
      let w = colWidth * (1 - i * 0.18);
      fill(180, 160, 200, alpha * (1 - i * 0.2));
      ellipse(width / 2, y, w, 3);
    }
  }

  // Human silhouette particles - coherent at top, dispersing below
  let cx = width / 2;
  let figureTop = 180;
  let figureBottom = 1600;

  // Generate figure shape points
  let numParticles = 28000;
  for (let i = 0; i < numParticles; i++) {
    let py = random(figureTop, figureBottom);
    let t = (py - figureTop) / (figureBottom - figureTop);

    // Body shape: head, torso, fading legs
    let bodyWidth;
    let localT = (py - figureTop) / (figureBottom - figureTop);

    if (localT < 0.12) {
      // Head
      let ht = localT / 0.12;
      bodyWidth = sin(ht * PI) * 55;
    } else if (localT < 0.18) {
      // Neck
      bodyWidth = 28;
    } else if (localT < 0.55) {
      // Torso
      let tt = (localT - 0.18) / 0.37;
      bodyWidth = lerp(55, 80, sin(tt * PI * 0.5));
    } else if (localT < 0.65) {
      // Hips
      bodyWidth = lerp(80, 70, (localT - 0.55) / 0.1);
    } else {
      // Legs - splitting and fading
      bodyWidth = lerp(70, 30, (localT - 0.65) / 0.35);
    }

    // Add noise-based organic shape
    let noiseVal = noise(i * 0.01, py * 0.005) * 30 - 15;
    bodyWidth += noiseVal;

    // Particle position
    let px;
    let disperse = pow(t, 2.5);

    if (localT > 0.6 && random() < 0.5) {
      // Split into two legs
      let legOffset = lerp(20, 50, (localT - 0.6) / 0.4);
      let side = random() < 0.5 ? -1 : 1;
      px = cx + side * legOffset + random(-bodyWidth * 0.4, bodyWidth * 0.4);
    } else {
      px = cx + random(-bodyWidth, bodyWidth);
    }

    // Arms
    if (localT > 0.2 && localT < 0.52 && random() < 0.3) {
      let armT = (localT - 0.2) / 0.32;
      let armLen = lerp(0, 160, armT);
      let side = random() < 0.5 ? -1 : 1;
      px = cx + side * (bodyWidth + random(0, armLen));
      py += armT * 80;
    }

    // Dispersion: particles drift outward as t increases
    let disperseX = randomGaussian(0, disperse * 350);
    let disperseY = randomGaussian(0, disperse * 120);
    px += disperseX;
    py += disperseY;

    // Color based on position and dispersion
    let coherence = 1 - disperse;
    let r = lerp(180, 60, t) + random(-10, 10);
    let g = lerp(150, 40, t) + random(-10, 10);
    let b = lerp(170, 80, t) + random(-5, 15);
    let a = lerp(200, 8, pow(t, 1.5)) * (coherence * 0.7 + 0.3);

    if (random() < 0.05) {
      // Occasional bright sparks
      r = lerp(255, 150, t);
      g = lerp(230, 120, t);
      b = lerp(240, 180, t);
      a *= 2.5;
    }

    noStroke();
    fill(r, g, b, a);
    let sz = lerp(2.5, 1.2, t) + random(0, 1.5);
    if (random() < 0.02 * coherence) sz *= 2.5;
    ellipse(px, py, sz, sz);
  }

  // Flowing dissolution threads
  for (let i = 0; i < 60; i++) {
    let startX = cx + random(-80, 80);
    let startY = random(400, 1200);
    let t = (startY - figureTop) / (figureBottom - figureTop);

    let col = color(
      lerp(200, 80, t),
      lerp(170, 50, t),
      lerp(190, 100, t),
      lerp(40, 5, t)
    );
    stroke(col);
    strokeWeight(random(0.3, 1.2));
    noFill();
    beginShape();
    let x = startX, y = startY;
    for (let s = 0; s < 80; s++) {
      curveVertex(x, y);
      let angle = noise(x * 0.005, y * 0.005, i * 0.1) * TWO_PI * 2;
      x += cos(angle) * 4 + random(-1, 1);
      y += sin(angle) * 2 + 2;
    }
    endShape();
  }

  // Upper glow - the last warmth of consciousness
  for (let i = 0; i < 15; i++) {
    let glowY = 250 + i * 8;
    let glowW = 120 - i * 5;
    noStroke();
    fill(220, 180, 160, 3 - i * 0.15);
    ellipse(cx, glowY, glowW * 2, 60 - i * 2);
  }

  // Bottom void - subtle horizontal noise bands
  for (let y = 1500; y < height; y++) {
    let t = (y - 1500) / 500;
    let n = noise(y * 0.02) * 20;
    stroke(15 + n * t, 10 + n * t * 0.5, 22 + n * t, 30 * (1 - t));
    strokeWeight(1);
    let xOff = noise(y * 0.01) * 200 - 100;
    line(width * 0.2 + xOff, y, width * 0.8 + xOff, y);
  }

  // Scattered distant particles in the void
  for (let i = 0; i < 2000; i++) {
    let px = random(width);
    let py = random(1200, height);
    let t = (py - 1200) / 800;
    let a = random(5, 25) * (1 - t * 0.7);
    noStroke();
    fill(100 + random(50), 80 + random(40), 120 + random(60), a);
    ellipse(px, py, random(0.5, 2), random(0.5, 2));
  }

  // Fine horizontal lines suggesting the boundary dissolving
  for (let i = 0; i < 40; i++) {
    let ly = random(800, 1600);
    let t = (ly - 800) / 800;
    stroke(140, 120, 160, lerp(15, 2, t));
    strokeWeight(0.5);
    let lx = cx + random(-200, 200);
    let lw = random(50, 400) * (1 - t * 0.5);
    line(lx - lw / 2, ly, lx + lw / 2, ly);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function draw() {
  background(6, 4, 10);

  loadPixels();
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let idx = (y * width + x) * 4;
      let n1 = noise(x * 0.0015, y * 0.0012);
      let n2 = noise(x * 0.005, y * 0.005);
      let n3 = noise(x * 0.018, y * 0.018);

      let dx = (x - width / 2) / (width * 0.4);
      let dy = (y - 400) / 700;
      let glow = max(0, 1 - sqrt(dx * dx + dy * dy));
      glow = pow(glow, 2.5) * 0.4;

      let dx2 = (x - width / 2) / (width * 0.6);
      let dy2 = (y - 600) / 1000;
      let glow2 = max(0, 1 - sqrt(dx2 * dx2 + dy2 * dy2));
      glow2 = pow(glow2, 3) * 0.15;

      pixels[idx] = min(255, 6 + n1 * 14 + n3 * 4 + glow * 50 + glow2 * 30);
      pixels[idx + 1] = min(255, 4 + n1 * 7 + n2 * 3 + glow * 25 + glow2 * 12);
      pixels[idx + 2] = min(255, 12 + n1 * 22 + n2 * 6 + glow * 15 + glow2 * 20);
      pixels[idx + 3] = 255;
    }
  }
  updatePixels();

  let centerX = width / 2;

  loadPixels();
  for (let i = 0; i < 600000; i++) {
    let t = pow(random(), 0.85);
    let y = floor(lerp(80, 1950, t));
    if (y < 0 || y >= height) continue;

    let fw;
    if (t < 0.06) {
      let lt = t / 0.06;
      fw = lerp(40, 65, sin(lt * PI * 0.5));
    } else if (t < 0.09) {
      fw = lerp(65, 35, (t - 0.06) / 0.03);
    } else if (t < 0.17) {
      fw = lerp(35, 120, (t - 0.09) / 0.08);
    } else if (t < 0.42) {
      fw = lerp(120, 105, (t - 0.17) / 0.25);
    } else if (t < 0.52) {
      fw = lerp(105, 75, (t - 0.42) / 0.1);
    } else {
      let dt = (t - 0.52) / 0.48;
      fw = lerp(75, 550, pow(dt, 0.55));
    }

    let dissolution = t > 0.22 ? pow((t - 0.22) / 0.78, 1.8) : 0;

    let xOff = (random() - 0.5) * 2 * fw;
    let noiseX = (noise(y * 0.004, xOff * 0.008 + i * 0.00001) - 0.5);
    xOff += noiseX * dissolution * 450;

    let noiseY = (noise(xOff * 0.008 + 100, y * 0.004) - 0.5);
    let yOff = noiseY * dissolution * 60;

    let x = floor(centerX + xOff);
    let yi = floor(y + yOff);

    if (x < 1 || x >= width - 1 || yi < 1 || yi >= height - 1) continue;
    if (random() < dissolution * 0.75) continue;

    let warmth = constrain(1 - t * 1.15, 0, 1);
    let r, g, b, intensity;

    if (warmth > 0.75) {
      let lt = (warmth - 0.75) / 0.25;
      r = lerp(190, 255, lt);
      g = lerp(140, 235, lt);
      b = lerp(95, 200, lt);
      intensity = lerp(0.1, 0.3, lt);
    } else if (warmth > 0.45) {
      let lt = (warmth - 0.45) / 0.3;
      r = lerp(105, 190, lt);
      g = lerp(60, 140, lt);
      b = lerp(75, 95, lt);
      intensity = lerp(0.06, 0.1, lt);
    } else if (warmth > 0.18) {
      let lt = (warmth - 0.18) / 0.27;
      r = lerp(35, 105, lt);
      g = lerp(28, 60, lt);
      b = lerp(55, 75, lt);
      intensity = lerp(0.03, 0.06, lt);
    } else {
      let lt = warmth / 0.18;
      r = lerp(10, 35, lt);
      g = lerp(7, 28, lt);
      b = lerp(16, 55, lt);
      intensity = lerp(0.01, 0.03, lt);
    }

    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        let px = x + dx;
        let py = yi + dy;
        let falloff = (dx === 0 && dy === 0) ? intensity : intensity * 0.35;
        let pidx = (py * width + px) * 4;
        pixels[pidx] = min(255, pixels[pidx] + r * falloff);
        pixels[pidx + 1] = min(255, pixels[pidx + 1] + g * falloff);
        pixels[pidx + 2] = min(255, pixels[pidx + 2] + b * falloff);
      }
    }
  }
  updatePixels();

  noFill();
  for (let i = 0; i < 350; i++) {
    let startY = random(450, 1900);
    let startT = map(startY, 450, 1900, 0, 1);
    let startX = centerX + (noise(i * 0.13, 50) - 0.5) * lerp(80, 350, startT);

    let cr = lerp(160, 12, startT);
    let cg = lerp(110, 8, startT);
    let cb = lerp(75, 28, startT);
    let ca = lerp(14, 2, startT);

    stroke(cr, cg, cb, ca);
    strokeWeight(random(0.3, 1.0));

    beginShape();
    let px = startX;
    let py = startY;
    for (let j = 0; j < 35; j++) {
      let angle = noise(px * 0.0025, py * 0.0025, i * 0.07) * TWO_PI * 2.5;
      px += cos(angle) * 4 + (noise(i * 0.2, j * 0.1) - 0.5) * 2;
      py += sin(angle) * 3 + 2.5;
      curveVertex(px, py);
    }
    endShape();
  }

  noStroke();
  for (let i = 0; i < 25; i++) {
    let x = centerX + randomGaussian() * 30;
    let y = random(160, 420);
    let sz = random(1.5, 5);

    for (let gr = sz * 5; gr > 0; gr -= 1.5) {
      let alpha = map(gr, 0, sz * 5, 35, 1);
      fill(255, 225, 185, alpha);
      ellipse(x, y, gr, gr);
    }
    fill(255, 245, 225, 70);
    ellipse(x, y, sz, sz);
  }

  for (let i = 0; i < 8; i++) {
    let x = centerX + randomGaussian() * 50;
    let y = random(100, 300);
    let sz = random(0.8, 2.5);
    for (let gr = sz * 8; gr > 0; gr -= 1) {
      let alpha = map(gr, 0, sz * 8, 20, 0.5);
      fill(255, 240, 210, alpha);
      ellipse(x, y, gr, gr);
    }
    fill(255, 252, 245, 90);
    ellipse(x, y, sz, sz);
  }

  loadPixels();
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let idx = (y * width + x) * 4;
      let edgeX = min(x, width - 1 - x) / (width * 0.45);
      let edgeY = min(y, height - 1 - y) / (height * 0.45);
      let vignette = constrain(min(edgeX, edgeY), 0, 1);
      vignette = pow(vignette, 1.5);
      let darkening = lerp(0.3, 1.0, vignette);
      pixels[idx] = floor(pixels[idx] * darkening);
      pixels[idx + 1] = floor(pixels[idx + 1] * darkening);
      pixels[idx + 2] = floor(pixels[idx + 2] * darkening);
    }
  }
  updatePixels();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noStroke();

  background(12, 10, 15);

  for (let i = 0; i < 70000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.004, y * 0.004);
    fill(18 * n + 5, 14 * n + 3, 22 * n + 5, random(6, 18));
    ellipse(x, y, random(0.5, 1.8));
  }

  let cx = 800;
  let cy = 940;

  for (let i = 50; i > 0; i--) {
    fill(42, 30, 40, 3);
    ellipse(cx, cy - 40, i * 42, i * 72);
  }
  for (let i = 30; i > 0; i--) {
    fill(60, 42, 35, 4);
    ellipse(cx, cy, i * 28, i * 48);
  }

  for (let i = 0; i < 90000; i++) {
    let t = random(-1, 1);
    let bw = 105 * (1 - 0.55 * pow(abs(t), 1.9));
    let angle = random(TWO_PI);
    let rad = pow(random(), 0.5);
    let x = cx + cos(angle) * rad * bw;
    let y = cy + t * 370 + sin(angle) * rad * bw * 0.32;
    let n1 = noise(x * 0.018, y * 0.018);
    let n2 = noise(x * 0.018, y * 0.018, 77);
    x += (n1 - 0.5) * 18;
    y += (n2 - 0.5) * 18;
    let d = dist(x, y, cx, cy);
    let c = constrain(1 - d / 340, 0, 1);
    let bright = pow(c, 2.5);
    let r = lerp(175, 235, bright) + random(-12, 12);
    let g = lerp(135, 198, bright) + random(-10, 10);
    let b = lerp(118, 172, bright) + random(-8, 8);
    let a = lerp(40, 170, pow(c, 0.8));
    fill(r, g, b, a);
    ellipse(x, y, random(1.5, 3.8) * (0.5 + c * 0.6));
  }

  for (let i = 0; i < 90000; i++) {
    let t = random(-1.05, 1.05);
    let bw = 125 * (1 - 0.5 * pow(abs(t), 1.4));
    let angle = random(TWO_PI);
    let rad = pow(random(), 0.38);
    let bx = cx + cos(angle) * rad * bw;
    let by = cy + t * 390 + sin(angle) * rad * bw * 0.38;
    let dc = dist(bx, by, cx, cy);
    let dissolve = constrain(dc / 340, 0, 1);
    dissolve *= (0.55 + 0.45 * noise(bx * 0.007, by * 0.007));
    let fa = noise(bx * 0.0035, by * 0.0035, 3.7) * TWO_PI * 2;
    let fm = pow(dissolve, 1.6) * 420;
    let x = bx + cos(fa) * fm;
    let y = by + sin(fa) * fm * 0.65 - dissolve * 280;
    if (x < -50 || x > width + 50 || y < -50 || y > height + 50) continue;
    let r = lerp(205, 32, pow(dissolve, 0.45));
    let g = lerp(170, 28, pow(dissolve, 0.45));
    let b = lerp(150, 48, pow(dissolve, 0.45));
    let a = lerp(110, 0, pow(dissolve, 0.28));
    let sz = lerp(3.2, 0.7, dissolve) * random(0.55, 1.45);
    fill(r + random(-10, 10), g + random(-8, 8), b + random(-6, 6), a);
    ellipse(x, y, sz);
  }

  for (let t = 0; t < 350; t++) {
    let sa = random(TWO_PI);
    let st = random(-0.75, 0.75);
    let bw = 115 * (1 - 0.5 * pow(abs(st), 1.5));
    let x = cx + cos(sa) * bw * random(0.88, 1.12);
    let y = cy + st * 370 + sin(sa) * bw * 0.35 * random(0.88, 1.12);
    for (let step = 0; step < 90; step++) {
      let fa = noise(x * 0.0022, y * 0.0022, 5.3) * TWO_PI * 2.5;
      x += cos(fa) * 4.5;
      y += sin(fa) * 4.2 - 1.8;
      if (x < -20 || x > width + 20 || y < -20 || y > height + 20) break;
      let fade = step / 90;
      let r = lerp(195, 35, fade);
      let g = lerp(158, 30, fade);
      let b = lerp(140, 52, fade);
      let a = lerp(55, 0, pow(fade, 0.45));
      fill(r, g, b, a);
      ellipse(x, y, lerp(2.8, 0.2, fade));
    }
  }

  for (let i = 0; i < 12000; i++) {
    let x = random(width);
    let y = random(height);
    let d = dist(x, y, cx, cy);
    if (d > 350 && d < 900) {
      let n = noise(x * 0.002, y * 0.002, 20);
      if (n > 0.45) {
        let fade = constrain((d - 350) / 550, 0, 1);
        fill(
          55 + random(-15, 15),
          45 + random(-12, 12),
          65 + random(-15, 15),
          lerp(18, 2, fade)
        );
        ellipse(x, y, random(0.5, 2));
      }
    }
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
  background(0);
}

function draw() {
  // Deep background gradient
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(3, 12, t);
    let g = lerp(2, 8, t);
    let b = lerp(8, 5, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Layer 1: Dense organic network at bottom
  strokeWeight(1);
  for (let i = 0; i < 3000; i++) {
    let startX = width / 2 + randomGaussian() * 300;
    let startY = height * random(0.75, 1.0);
    drawFlowingCurve(startX, startY, random(80, 250), true);
  }

  // Layer 2: Mid-section dissolution
  for (let i = 0; i < 2000; i++) {
    let startX = width / 2 + randomGaussian() * 400;
    let startY = height * random(0.45, 0.75);
    drawFlowingCurve(startX, startY, random(40, 150), true);
  }

  // Layer 3: Upper dissolution - sparse fragments
  for (let i = 0; i < 800; i++) {
    let startX = width / 2 + randomGaussian() * 500;
    let startY = height * random(0.15, 0.45);
    drawFlowingCurve(startX, startY, random(20, 80), false);
  }

  // Layer 4: Scattered particles in the void
  for (let i = 0; i < 5000; i++) {
    let x = random(width);
    let y = random(height * 0.8);
    let dissolution = 1 - (y / (height * 0.8));
    if (random() < dissolution * 0.3) {
      let alpha = random(5, 40) * dissolution;
      let warm = random() < 0.3;
      if (warm) {
        fill(140 + random(40), 80 + random(30), 30 + random(20), alpha);
      } else {
        fill(60 + random(40), 60 + random(30), 80 + random(40), alpha);
      }
      noStroke();
      let s = random(0.5, 3) * (1 - dissolution * 0.5);
      ellipse(x, y, s, s);
    }
  }

  // Layer 5: Central column glow at bottom
  for (let i = 0; i < 500; i++) {
    let x = width / 2 + randomGaussian() * 100;
    let y = height * random(0.85, 1.0);
    let alpha = random(3, 15);
    fill(120, 60, 20, alpha);
    noStroke();
    ellipse(x, y, random(10, 60), random(10, 60));
  }

  // Layer 6: Fine detail threads at base
  strokeWeight(0.5);
  for (let i = 0; i < 1500; i++) {
    let x = width / 2 + randomGaussian() * 250;
    let y = height * random(0.88, 1.0);
    let len = random(20, 80);
    let angle = noise(x * 0.005, y * 0.005) * TWO_PI * 2;
    let ex = x + cos(angle) * len;
    let ey = y + sin(angle) * len;
    let alpha = random(20, 80);
    stroke(160 + random(40), 100 + random(30), 40 + random(20), alpha);
    line(x, y, ex, ey);
  }

  // Layer 7: Very faint noise texture overlay
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let noiseVal = random(-8, 8);
    pixels[i] = constrain(pixels[i] + noiseVal, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + noiseVal, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + noiseVal, 0, 255);
  }
  updatePixels();

  // Layer 8: Subtle vignette
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x += 4) {
      let dx = (x - width / 2) / (width / 2);
      let dy = (y - height / 2) / (height / 2);
      let dist = sqrt(dx * dx + dy * dy);
      if (dist > 0.6) {
        let vignette = map(dist, 0.6, 1.5, 0, 60);
        vignette = constrain(vignette, 0, 60);
        stroke(0, 0, 0, vignette);
        strokeWeight(4);
        point(x, y);
      }
    }
  }
}

function drawFlowingCurve(startX, startY, maxLen, continuous) {
  let x = startX;
  let y = startY;
  let steps = floor(maxLen / 2);

  noFill();
  beginShape();

  let totalSteps = steps;
  for (let i = 0; i < steps; i++) {
    let progress = i / steps;
    let yNorm = y / height;

    // Opacity based on height - more visible at bottom, fading upward
    let baseAlpha = map(yNorm, 0, 1, 5, 90);
    // Reduce alpha as curve progresses upward
    if (y < height * 0.5) {
      baseAlpha *= 0.3;
    }

    let noiseScale = 0.003;
    let n = noise(x * noiseScale, y * noiseScale, i * 0.01);
    let angle = n * TWO_PI * 3;

    // Upward bias for dissolution effect
    angle += random(-0.5, 0.5);
    let stepSize = random(2, 5);
    x += cos(angle) * stepSize;
    y += sin(angle) * stepSize - random(0, 2); // slight upward drift

    // Warm colors at bottom, cool/dark at top
    let warm = yNorm;
    let r = lerp(50, 170, warm) + random(-10, 10);
    let g = lerp(50, 90, warm) + random(-10, 10);
    let b = lerp(70, 30, warm) + random(-10, 10);
    let alpha = baseAlpha * (1 - progress * 0.5);

    // Fragmentation: skip some segments in upper regions
    if (yNorm < 0.4 && random() > yNorm * 2) {
      continue;
    }

    stroke(r, g, b, alpha);
    strokeWeight(map(yNorm, 0, 1, 0.3, 1.5));

    if (continuous || yNorm > 0.5) {
      curveVertex(x, y);
    } else {
      point(x, y);
    }

    // Stop if too far from center or out of bounds
    if (abs(x - width / 2) > 700 || y < 0 || y > height) break;
  }
  endShape();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function draw() {
  background(8, 6, 12);

  // Background noise texture
  loadPixels();
  for (let x = 0; x < width; x += 2) {
    for (let y = 0; y < height; y += 2) {
      let n = noise(x * 0.003, y * 0.003);
      let v = n * 15;
      let idx = (y * width + x) * 4;
      pixels[idx] += v;
      pixels[idx + 1] += v * 0.8;
      pixels[idx + 2] += v * 1.2;
      if (x + 1 < width) {
        let idx2 = (y * width + x + 1) * 4;
        pixels[idx2] += v;
        pixels[idx2 + 1] += v * 0.8;
        pixels[idx2 + 2] += v * 1.2;
      }
      if (y + 1 < height) {
        let idx3 = ((y + 1) * width + x) * 4;
        pixels[idx3] += v;
        pixels[idx3 + 1] += v * 0.8;
        pixels[idx3 + 2] += v * 1.2;
      }
    }
  }
  updatePixels();

  // Vertical gradient overlay - darker at bottom
  for (let y = 0; y < height; y++) {
    let alpha = map(y, 0, height, 0, 80);
    stroke(0, 0, 0, alpha);
    strokeWeight(1);
    line(0, y, width, y);
  }

  // Central figure - a humanoid silhouette dissolving
  let cx = width / 2;
  let cy = height * 0.45;

  // Glow behind figure
  for (let r = 400; r > 0; r -= 4) {
    let alpha = map(r, 0, 400, 25, 0);
    noStroke();
    fill(180, 120, 60, alpha);
    ellipse(cx, cy - 100, r * 1.2, r * 1.8);
  }

  // Figure body using noise-distorted shape
  // Head
  drawDissolvingForm(cx, cy - 280, 80, 100, 0.85, true);

  // Neck
  drawDissolvingForm(cx, cy - 190, 35, 50, 0.75, false);

  // Torso
  drawDissolvingForm(cx, cy - 50, 140, 220, 0.7, true);

  // Left arm
  for (let i = 0; i < 8; i++) {
    let t = i / 7;
    let ax = cx - 100 - t * 80 + noise(i * 0.5) * 30;
    let ay = cy - 120 + t * 200;
    let sz = map(t, 0, 1, 40, 20);
    drawDissolvingForm(ax, ay, sz, sz * 1.2, 0.6 - t * 0.3, true);
  }

  // Right arm
  for (let i = 0; i < 8; i++) {
    let t = i / 7;
    let ax = cx + 100 + t * 80 + noise(i * 0.5 + 10) * 30;
    let ay = cy - 120 + t * 200;
    let sz = map(t, 0, 1, 40, 20);
    drawDissolvingForm(ax, ay, sz, sz * 1.2, 0.5 - t * 0.35, true);
  }

  // Lower body - more dissolved
  for (let i = 0; i < 12; i++) {
    let t = i / 11;
    let spread = t * 120;
    let lx = cx - 40 - spread * 0.3 + noise(i * 0.3 + 20) * spread;
    let ly = cy + 120 + t * 300;
    let sz = map(t, 0, 1, 60, 15);
    drawDissolvingForm(lx, ly, sz, sz * 1.5, 0.5 - t * 0.45, true);

    let rx = cx + 40 + spread * 0.3 + noise(i * 0.3 + 30) * spread;
    drawDissolvingForm(rx, ly, sz, sz * 1.5, 0.5 - t * 0.45, true);
  }

  // Dissolving particles emanating from figure
  for (let i = 0; i < 8000; i++) {
    let angle = random(TWO_PI);
    let dist = random(20, 500);
    let originX = cx + noise(i * 0.01) * 100 - 50;
    let originY = cy + noise(i * 0.01 + 100) * 300 - 150;

    let px = originX + cos(angle) * dist;
    let py = originY + sin(angle) * dist * 1.3;

    if (px < 0 || px > width || py < 0 || py > height) continue;

    let distFromCenter = dist / 500;
    let alpha = map(distFromCenter, 0, 1, 120, 5);
    let sz = map(distFromCenter, 0, 1, 4, 1);

    // Color shifts from warm to cold
    let r = lerp(160, 30, distFromCenter);
    let g = lerp(100, 25, distFromCenter);
    let b = lerp(50, 40, distFromCenter);

    noStroke();
    fill(r, g, b, alpha);
    ellipse(px, py, sz, sz);
  }

  // Fine dust particles - entropy
  for (let i = 0; i < 3000; i++) {
    let px = random(width);
    let py = random(height);
    let n = noise(px * 0.005, py * 0.005);

    if (n > 0.5) {
      let alpha = map(n, 0.5, 1, 0, 40);
      let sz = map(n, 0.5, 1, 0.5, 2.5);
      noStroke();
      fill(100, 80, 70, alpha);
      ellipse(px, py, sz, sz);
    }
  }

  // Flowing dissolution lines
  noFill();
  for (let i = 0; i < 60; i++) {
    let startX = cx + random(-150, 150);
    let startY = cy + random(-300, 300);

    strokeWeight(random(0.3, 1.5));
    let col = random(30, 80);
    stroke(col, col * 0.8, col * 0.7, random(20, 60));

    beginShape();
    let px = startX;
    let py = startY;
    for (let j = 0; j < 30; j++) {
      curveVertex(px, py);
      let n1 = noise(px * 0.004, py * 0.004, i * 0.1);
      let n2 = noise(px * 0.004 + 100, py * 0.004 + 100, i * 0.1);
      px += (n1 - 0.5) * 30;
      py += (n2 - 0.3) * 20 + 5;
    }
    endShape();
  }

  // Central void - the absence at the heart
  for (let r = 120; r > 0; r -= 2) {
    let alpha = map(r, 0, 120, 30, 0);
    noStroke();
    fill(0, 0, 5, alpha);
    ellipse(cx, cy - 50, r * 0.8, r * 1.2);
  }

  // Falling fragments at the bottom
  for (let i = 0; i < 2000; i++) {
    let px = random(width * 0.2, width * 0.8);
    let py = random(height * 0.6, height);
    let fallProgress = map(py, height * 0.6, height, 0, 1);

    let n = noise(px * 0.008, py * 0.008);
    if (n > 0.4) {
      let alpha = map(fallProgress, 0, 1, 50, 10) * n;
      let sz = map(fallProgress, 0, 1, 3, 0.5);
      noStroke();
      fill(60 + n * 40, 40 + n * 30, 35 + n * 20, alpha);
      ellipse(px, py, sz, sz * random(1, 2));
    }
  }

  // Subtle light rays from above
  for (let i = 0; i < 15; i++) {
    let x = cx + random(-300, 300);
    let rayWidth = random(20, 80);
    noStroke();
    for (let y = 0; y < cy - 200; y += 2) {
      let alpha = map(y, 0, cy - 200, 3, 0) * noise(i, y * 0.01);
      fill(200, 180, 140, alpha);
      rect(x - rayWidth / 2 + noise(y * 0.01 + i) * 20, y, rayWidth * noise(y * 0.005 + i * 5), 2);
    }
  }

  // Final vignette
  for (let i = 0; i < 200; i++) {
    let alpha = map(i, 0, 200, 0, 3);
    noFill();
    stroke(0, 0, 0, alpha);
    strokeWeight(3);
    rect(i, i, width - i * 2, height - i * 2);
  }
}

function drawDissolvingForm(x, y, w, h, coherence, isBody) {
  // Draw a form that partially dissolves based on coherence (0-1)
  let points = 40;

  // Core shape
  noStroke();
  for (let layer = 3; layer >= 0; layer--) {
    let expand = layer * 3;
    let alpha = map(layer, 0, 3, 180 * coherence, 30 * coherence);

    beginShape();
    for (let i = 0; i <= points; i++) {
      let angle = map(i, 0, points, 0, TWO_PI);
      let baseR = (angle < PI) ? w / 2 + expand : w / 2 + expand;
      let rY = h / 2 + expand;

      let nx = noise(cos(angle) * 2 + x * 0.01, sin(angle) * 2 + y * 0.01, layer * 0.5);
      let dissolve = (1 - coherence) * nx * 60;

      let px = x + cos(angle) * (baseR + dissolve);
      let py = y + sin(angle) * (rY + dissolve * 0.7);

      // Add noise displacement
      px += (noise(i * 0.2, layer) - 0.5) * 20 * (1 - coherence);
      py += (noise(i * 0.2 + 50, layer) - 0.5) * 20 * (1 - coherence);

      curveVertex(px, py);
    }
    endShape(CLOSE);

    // Color based on layer
    let r, g, b;
    if (isBody) {
      r = lerp(90, 50, layer / 3);
      g = lerp(65, 35, layer / 3);
      b = lerp(45, 30, layer / 3);
    } else {
      r = lerp(70, 40, layer / 3);
      g = lerp(55, 30, layer / 3);
      b = lerp(40, 25, layer / 3);
    }
    fill(r, g, b, alpha);
  }

  // Dissolution particles around the form
  let numParticles = floor((1 - coherence) * 80);
  for (let i = 0; i < numParticles; i++) {
    let angle = random(TWO_PI);
    let dist = random(w * 0.5, w * 2);
    let px = x + cos(angle) * dist;
    let py = y + sin(angle) * dist * (h / w);
    let sz = random(1, 4) * (1 - coherence);
    let alpha = random(30, 100) * (1 - coherence);

    noStroke();
    fill(100, 75, 55, alpha);
    ellipse(px, py, sz, sz);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  pixelDensity(1);
}

function draw() {
  background(8, 6, 14);

  // Deep atmospheric background gradient
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(6, 18, t * t);
    let g = lerp(4, 10, t * t);
    let b = lerp(16, 8, t);
    // Add subtle noise variation
    let nv = noise(y * 0.005) * 8;
    stroke(r + nv, g + nv * 0.5, b + nv * 0.3);
    line(0, y, width, y);
  }

  // Subtle vertical light column behind figure
  for (let i = 0; i < 200; i++) {
    let cx = width / 2 + randomGaussian() * 80;
    let cy = height * 0.45 + randomGaussian() * 300;
    let s = random(60, 200);
    let alpha = random(2, 8);
    noStroke();
    fill(180, 140, 80, alpha);
    ellipse(cx, cy, s, s * 1.5);
  }

  // Ground plane - dark earth with noise texture
  drawGround();

  // Root/mycelium network spreading from base
  drawRoots();

  // The dissolving figure
  drawFigure();

  // Rising particles (ash/soul ascending)
  drawRisingParticles();

  // Falling particles (returning to earth)
  drawFallingParticles();

  // Central fading glow (last warmth of life)
  drawCoreGlow();

  // Foreground atmospheric dust
  drawAtmosphericDust();

  // Vignette
  drawVignette();
}

function drawGround() {
  noStroke();
  let groundY = height * 0.72;

  // Layered earth
  for (let layer = 0; layer < 5; layer++) {
    let ly = groundY + layer * 40;
    beginShape();
    vertex(0, height);
    for (let x = 0; x <= width; x += 8) {
      let n = noise(x * 0.003, layer * 10) * 60;
      let yy = ly + n;
      vertex(x, yy);
    }
    vertex(width, height);
    endShape(CLOSE);

    let darkness = map(layer, 0, 4, 25, 10);
    let r = darkness + random(5);
    let g = darkness * 0.7;
    let b = darkness * 0.5;
    fill(r, g, b);
    // Redraw with fill
    beginShape();
    vertex(0, height);
    for (let x = 0; x <= width; x += 8) {
      let n = noise(x * 0.003, layer * 10) * 60;
      let yy = ly + n;
      vertex(x, yy);
    }
    vertex(width, height);
    endShape(CLOSE);
  }

  // Soil texture particles
  for (let i = 0; i < 3000; i++) {
    let x = random(width);
    let baseY = groundY + noise(x * 0.003) * 60;
    let y = random(baseY, height);
    let depth = map(y, baseY, height, 0, 1);
    let sz = random(1, 4) * (1 - depth * 0.5);
    let bright = random(15, 40) * (1 - depth * 0.7);
    fill(bright + random(10), bright * 0.6, bright * 0.4, random(100, 200));
    noStroke();
    ellipse(x, y, sz, sz);
  }
}

function drawRoots() {
  let baseX = width / 2;
  let baseY = height * 0.72;

  // Main root structures
  for (let r = 0; r < 12; r++) {
    let angle = random(-PI * 0.8, -PI * 0.2) + PI;
    if (r < 6) angle = random(PI * 0.15, PI * 0.85);
    drawBranch(baseX + random(-30, 30), baseY + random(-10, 20), angle, random(60, 120), 4, r);
  }

  // Fine mycelium network
  for (let i = 0; i < 80; i++) {
    let sx = baseX + randomGaussian() * 200;
    let sy = baseY + random(20, 200);
    let len = random(30, 100);
    let a = random(TWO_PI);
    stroke(50, 35, 25, random(20, 60));
    strokeWeight(random(0.5, 1.5));
    let ex = sx + cos(a) * len;
    let ey = sy + sin(a) * len * 0.5 + len * 0.3;
    line(sx, sy, ex, ey);
  }
}

function drawBranch(x, y, angle, length, weight, seed) {
  if (weight < 0.5 || length < 5) return;

  let segments = 8;
  let segLen = length / segments;
  let cx = x, cy = y;

  stroke(40 + seed * 3, 28 + seed * 2, 18 + seed, 180);
  strokeWeight(weight);
  noFill();

  beginShape();
  vertex(cx, cy);
  for (let i = 0; i < segments; i++) {
    angle += randomGaussian() * 0.3;
    cx += cos(angle) * segLen;
    cy += sin(angle) * segLen;
    vertex(cx, cy);
  }
  endShape();

  // Sub-branches
  if (random() < 0.7) {
    let branchPoint = floor(random(2, segments - 1));
    let bx = x, by = y;
    let ba = angle;
    for (let i = 0; i < branchPoint; i++) {
      ba += randomGaussian() * 0.3;
      bx += cos(ba) * segLen;
      by += sin(ba) * segLen;
    }
    drawBranch(bx, by, angle + random(-0.8, 0.8), length * random(0.4, 0.7), weight * 0.6, seed + 1);
  }
  if (random() < 0.5) {
    drawBranch(cx, cy, angle + random(-0.6, 0.6), length * random(0.3, 0.5), weight * 0.5, seed + 2);
  }
}

function drawFigure() {
  let centerX = width / 2;
  let topY = height * 0.2;
  let bottomY = height * 0.72;
  let figHeight = bottomY - topY;

  // Figure body as a collection of particles
  // Upper body is more intact, lower body dissolves
  for (let i = 0; i < 15000; i++) {
    let t = random(); // 0 = top, 1 = bottom
    let y = topY + t * figHeight;

    // Body width varies with height (human-ish silhouette)
    let bodyWidth;
    if (t < 0.12) {
      // Head
      bodyWidth = 35 * sin(t / 0.12 * PI);
    } else if (t < 0.18) {
      // Neck
      bodyWidth = 15;
    } else if (t < 0.45) {
      // Torso
      let tt = (t - 0.18) / 0.27;
      bodyWidth = lerp(50, 45, tt);
    } else if (t < 0.5) {
      // Waist
      bodyWidth = 38;
    } else {
      // Legs
      let tt = (t - 0.5) / 0.5;
      bodyWidth = lerp(42, 20, tt);
    }

    let xOffset = randomGaussian() * bodyWidth * 0.5;

    // Dissolution effect - particles spread out more toward bottom
    let dissolution = pow(t, 2.5);
    xOffset += randomGaussian() * dissolution * 150;
    let yOff = randomGaussian() * dissolution * 80;

    // Some particles drift upward (especially from upper body)
    if (random() < 0.3 && t < 0.5) {
      yOff = -random(10, 100) * (1 - t);
      xOffset += randomGaussian() * 40 * (1 - t);
    }

    let px = centerX + xOffset;
    let py = y + yOff;

    // Size decreases with dissolution
    let sz = random(1.5, 4.5) * (1 - dissolution * 0.6);

    // Color: warm life tones fading to cold gray
    let warmth = 1 - dissolution;
    let r = lerp(60, 190, warmth) + random(-10, 10);
    let g = lerp(50, 140, warmth) + random(-10, 10);
    let b = lerp(55, 80, warmth) + random(-10, 10);
    let alpha = lerp(40, 220, 1 - dissolution * 0.5);

    // Some particles are brighter (embers)
    if (random() < 0.05) {
      r = random(200, 255);
      g = random(150, 200);
      b = random(60, 100);
      alpha = random(100, 200);
    }

    noStroke();
    fill(r, g, b, alpha);
    ellipse(px, py, sz, sz);
  }

  // Arms - subtle suggestion
  for (let side = -1; side <= 1; side += 2) {
    for (let i = 0; i < 1500; i++) {
      let t = random();
      let armStartY = topY + figHeight * 0.2;
      let armAngle = side * (0.3 + t * 0.8);
      let armLen = t * 160;

      let ax = centerX + side * 45 + cos(armAngle + PI / 2) * armLen;
      let ay = armStartY + sin(armAngle + PI / 2) * armLen * 0.6;

      // Arms dissolve even more
      let armDissolution = pow(t, 1.5) * 0.8;
      ax += randomGaussian() * armDissolution * 80;
      ay += randomGaussian() * armDissolution * 60;

      let sz = random(1, 3) * (1 - armDissolution * 0.7);
      let warmth = 1 - armDissolution;
      let r = lerp(55, 175, warmth);
      let g = lerp(45, 130, warmth);
      let b = lerp(50, 75, warmth);

      noStroke();
      fill(r, g, b, lerp(30, 180, warmth));
      ellipse(ax, ay, sz, sz);
    }
  }
}

function drawRisingParticles() {
  // Ash and embers rising from the figure
  for (let i = 0; i < 800; i++) {
    let x = width / 2 + randomGaussian() * 200;
    let baseY = height * 0.35;
    let rise = random(50, 500);
    let y = baseY - rise;

    let drift = randomGaussian() * rise * 0.3;
    x += drift;

    let sz = random(1, 5) * map(rise, 0, 500, 1, 0.3);
    let alpha = map(rise, 0, 500, 150, 10);

    // Mix of warm embers and cool ash
    if (random() < 0.3) {
      // Ember
      fill(220 + random(35), 140 + random(60), 50 + random(40), alpha);
    } else {
      // Ash
      let gray = random(80, 160);
      fill(gray, gray * 0.9, gray * 0.85, alpha * 0.7);
    }

    noStroke();
    ellipse(x, y, sz, sz);
  }

  // Larger floating fragments
  for (let i = 0; i < 40; i++) {
    let x = width / 2 + randomGaussian() * 250;
    let y = random(height * 0.05, height * 0.6);
    let sz = random(4, 12);
    let alpha = random(20, 80);

    push();
    translate(x, y);
    rotate(random(TWO_PI));
    fill(120 + random(60), 80 + random(40), 50 + random(30), alpha);
    noStroke();
    // Irregular shape
    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.5) {
      let r = sz * (0.5 + noise(a * 2, i) * 0.5);
      vertex(cos(a) * r, sin(a) * r);
    }
    endShape(CLOSE);
    pop();
  }
}

function drawFallingParticles() {
  // Particles settling into the earth
  for (let i = 0; i < 500; i++) {
    let x = width / 2 + randomGaussian() * 180;
    let y = random(height * 0.6, height * 0.78);
    let sz = random(1, 3.5);
    let alpha = random(40, 150);

    let earthTone = random();
    let r, g, b;
    if (earthTone < 0.5) {
      r = random(60, 100);
      g = random(40, 65);
      b = random(25, 40);
    } else {
      r = random(80, 130);
      g = random(60, 90);
      b = random(40, 60);
    }

    noStroke();
    fill(r, g, b, alpha);
    ellipse(x, y, sz, sz);
  }
}

function drawCoreGlow() {
  // Soft glow at the figure's chest area - last warmth
  let cx = width / 2;
  let cy = height * 0.4;

  for (let i = 0; i < 30; i++) {
    let sz = 30 + i * 15;
    let alpha = map(i, 0, 30, 25, 1);
    noStroke();
    fill(200, 140, 60, alpha);
    ellipse(cx + randomGaussian() * 5, cy + randomGaussian() * 5, sz, sz * 1.2);
  }

  // Bright center point
  for (let i = 0; i < 10; i++) {
    let sz = 5 + i * 4;
    let alpha = map(i, 0, 10, 100, 5);
    fill(255, 200, 120, alpha);
    ellipse(cx, cy, sz, sz);
  }
}

function drawAtmosphericDust() {
  // Very subtle dust particles throughout
  for (let i = 0; i < 400; i++) {
    let x = random(width);
    let y = random(height);
    let sz = random(0.5, 2.5);
    let alpha = random(5, 30);
    let gray = random(100, 200);

    noStroke();
    fill(gray, gray * 0.9, gray * 0.8, alpha);
    ellipse(x, y, sz, sz);
  }

  // Subtle noise texture overlay
  for (let i = 0; i < 2000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.01, y * 0.01);
    let alpha = n * 15;
    fill(200, 180, 150, alpha);
    noStroke();
    ellipse(x, y, random(1, 3), random(1, 3));
  }
}

function drawVignette() {
  // Dark vignette around edges
  noFill();
  for (let i = 0; i < 80; i++) {
    let t = i / 80;
    let alpha = t * t * 180;
    stroke(5, 3, 10, alpha);
    strokeWeight(30);
    let inset = -i * 12;
    rect(inset, inset, width - inset * 2, height - inset * 2);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Sky gradient - warm earth to deep void
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(5, 80, pow(1 - t, 2.5));
    let g = lerp(3, 40, pow(1 - t, 3));
    let b = lerp(15, 35, pow(1 - t, 1.5));
    // Add warmth at the bottom
    if (t > 0.7) {
      let wt = (t - 0.7) / 0.3;
      r = lerp(r, 90, wt);
      g = lerp(g, 45, wt);
      b = lerp(b, 20, wt);
    }
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Subtle stars in upper portion
  noStroke();
  for (let i = 0; i < 200; i++) {
    let x = random(width);
    let y = random(height * 0.5);
    let s = random(1, 3);
    let a = random(30, 100) * (1 - y / (height * 0.5));
    fill(200, 200, 220, a);
    ellipse(x, y, s, s);
  }

  // Ground
  drawGround();

  // Draw the tree and its transformation
  drawTree();

  // Atmospheric mist layers
  drawMist();

  // Falling particles/leaves
  drawFallingElements();
}

function drawGround() {
  noStroke();
  // Layered ground
  for (let layer = 0; layer < 5; layer++) {
    let baseY = height - 150 + layer * 30;
    fill(30 + layer * 5, 20 + layer * 3, 10 + layer * 2, 200);
    beginShape();
    vertex(0, height);
    for (let x = 0; x <= width; x += 20) {
      let ny = baseY + noise(x * 0.003, layer) * 80 - 40;
      vertex(x, ny);
    }
    vertex(width, height);
    endShape(CLOSE);
  }
}

function drawTree() {
  let startX = width / 2;
  let startY = height - 100;

  // Draw trunk
  drawTrunk(startX, startY);

  // Draw branches recursively
  drawBranch(startX - 10, startY - 400, -PI / 2 - 0.15, 200, 18, 0);
  drawBranch(startX + 10, startY - 380, -PI / 2 + 0.1, 220, 16, 0);
  drawBranch(startX, startY - 420, -PI / 2, 180, 14, 0);
}

function drawTrunk(cx, baseY) {
  // Main trunk with organic shape
  let trunkPoints = [];
  let segments = 40;
  for (let i = 0; i <= segments; i++) {
    let t = i / segments;
    let y = baseY - t * 400;
    let w = lerp(60, 15, pow(t, 0.7));
    let offsetX = noise(t * 2) * 30 - 15;
    trunkPoints.push({ x: cx + offsetX, y: y, w: w });
  }

  // Draw trunk fill
  noStroke();
  for (let i = 0; i < trunkPoints.length - 1; i++) {
    let p1 = trunkPoints[i];
    let p2 = trunkPoints[i + 1];
    let t = i / trunkPoints.length;
    let r = lerp(45, 35, t);
    let g = lerp(30, 22, t);
    let b = lerp(20, 18, t);
    fill(r, g, b);
    beginShape();
    vertex(p1.x - p1.w, p1.y);
    vertex(p2.x - p2.w, p2.y);
    vertex(p2.x + p2.w, p2.y);
    vertex(p1.x + p1.w, p1.y);
    endShape(CLOSE);
  }

  // Bark texture
  stroke(30, 20, 12, 80);
  strokeWeight(1);
  for (let i = 0; i < 60; i++) {
    let t = random(1);
    let idx = floor(t * (trunkPoints.length - 1));
    let p = trunkPoints[idx];
    let xOff = random(-p.w * 0.8, p.w * 0.8);
    let len = random(10, 40);
    line(p.x + xOff, p.y, p.x + xOff + random(-3, 3), p.y - len);
  }

  // Roots
  noStroke();
  fill(40, 28, 18);
  for (let i = 0; i < 7; i++) {
    let angle = PI * 0.3 + (PI * 0.4 / 6) * i;
    let rootLen = random(80, 160);
    drawRoot(cx, baseY, angle, rootLen, 12);
  }
}

function drawRoot(x, y, angle, len, thickness) {
  let steps = 15;
  noStroke();
  fill(38, 26, 16);
  beginShape();
  let points = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let cx = x + cos(angle) * len * t + noise(t * 3) * 20 - 10;
    let cy = y + sin(angle) * len * t * 0.3 + t * 20;
    let w = thickness * (1 - t * 0.9);
    points.push({ x: cx, y: cy, w: w });
  }
  for (let p of points) {
    vertex(p.x - p.w, p.y);
  }
  for (let i = points.length - 1; i >= 0; i--) {
    vertex(points[i].x + points[i].w, points[i].y);
  }
  endShape(CLOSE);
}

function drawBranch(x, y, angle, len, thickness, depth) {
  if (depth > 7 || thickness < 1.5) return;

  let steps = 12;
  let points = [];

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let curLen = len * t;
    let wobble = noise(x * 0.01 + t * 2, depth) * 20 - 10;
    let px = x + cos(angle) * curLen + wobble * t;
    let py = y + sin(angle) * curLen + wobble * t * 0.5;
    let w = thickness * (1 - t * 0.7);
    points.push({ x: px, y: py, w: w });
  }

  // Color transitions from brown to dark as it goes up
  let heightRatio = 1 - (y / height);
  let r = lerp(50, 25, heightRatio);
  let g = lerp(35, 15, heightRatio);
  let b = lerp(25, 20, heightRatio);

  // Draw branch
  noStroke();
  fill(r, g, b);
  beginShape();
  for (let p of points) {
    vertex(p.x - p.w, p.y);
  }
  for (let i = points.length - 1; i >= 0; i--) {
    vertex(points[i].x + points[i].w, points[i].y);
  }
  endShape(CLOSE);

  let endPt = points[points.length - 1];

  // At higher depths, draw birds instead of more branches
  if (depth >= 4 && random() > 0.3) {
    drawBird(endPt.x, endPt.y, angle, map(depth, 4, 7, 30, 10), heightRatio);
  }

  if (depth >= 5 && random() > 0.5) {
    // Dissolve into particles
    drawDissolveParticles(endPt.x, endPt.y, map(depth, 5, 7, 10, 25), heightRatio);
  }

  // Continue branching
  if (depth < 6) {
    let numBranches = depth < 3 ? floor(random(2, 4)) : floor(random(1, 3));
    for (let i = 0; i < numBranches; i++) {
      let newAngle = angle + random(-0.6, 0.6);
      let newLen = len * random(0.55, 0.75);
      let newThick = thickness * random(0.5, 0.7);
      drawBranch(endPt.x, endPt.y, newAngle, newLen, newThick, depth + 1);
    }
  }
}

function drawBird(x, y, angle, size, heightRatio) {
  push();
  translate(x, y);
  let birdAngle = angle + random(-0.3, 0.3);
  rotate(birdAngle + PI / 2);

  // Bird color fades into darkness at top
  let alpha = lerp(200, 80, heightRatio);
  let c = lerp(60, 20, heightRatio);

  noStroke();
  fill(c, c * 0.8, c * 0.9, alpha);

  // Bird body
  beginShape();
  vertex(0, -size * 0.3);
  bezierVertex(size * 0.15, -size * 0.4, size * 0.1, -size * 0.1, 0, size * 0.3);
  bezierVertex(-size * 0.1, -size * 0.1, -size * 0.15, -size * 0.4, 0, -size * 0.3);
  endShape(CLOSE);

  // Wings
  let wingSpread = random(0.5, 1.2);
  stroke(c, c * 0.8, c * 0.9, alpha);
  strokeWeight(size * 0.08);
  noFill();

  // Left wing
  bezier(-size * 0.05, 0, -size * 0.4, -size * wingSpread * 0.5,
    -size * 0.7, -size * wingSpread * 0.3, -size * 0.9, -size * wingSpread * 0.1);

  // Right wing
  bezier(size * 0.05, 0, size * 0.4, -size * wingSpread * 0.5,
    size * 0.7, -size * wingSpread * 0.3, size * 0.9, -size * wingSpread * 0.1);

  pop();
}

function drawDissolveParticles(x, y, count, heightRatio) {
  noStroke();
  for (let i = 0; i < count; i++) {
    let px = x + random(-50, 50);
    let py = y + random(-60, 30);
    let s = random(1, 5);
    let alpha = random(30, 120) * (1 - heightRatio * 0.5);
    let c = lerp(80, 30, heightRatio);
    fill(c, c * 0.9, c * 1.1, alpha);
    ellipse(px, py, s, s);
  }
}

function drawMist() {
  noStroke();
  // Horizontal mist bands
  for (let i = 0; i < 8; i++) {
    let y = height * 0.4 + i * height * 0.07;
    let alpha = random(5, 15);
    fill(60, 50, 70, alpha);
    beginShape();
    for (let x = 0; x <= width; x += 30) {
      let ny = y + noise(x * 0.002, i * 10) * 80 - 40;
      vertex(x, ny);
    }
    vertex(width, y + 100);
    vertex(0, y + 100);
    endShape(CLOSE);
  }

  // Light glow at horizon
  for (let r = 400; r > 0; r -= 5) {
    let alpha = map(r, 0, 400, 15, 0);
    fill(100, 60, 30, alpha);
    ellipse(width / 2, height * 0.78, r * 3, r * 1.5);
  }
}

function drawFallingElements() {
  // Falling leaves/petals - sparse, suggesting letting go
  noStroke();
  for (let i = 0; i < 30; i++) {
    let x = width * 0.3 + random(width * 0.4);
    let y = height * 0.3 + random(height * 0.5);
    let s = random(4, 12);
    let angle = random(TWO_PI);
    let alpha = random(40, 120);

    push();
    translate(x, y);
    rotate(angle);
    fill(70, 40, 25, alpha);
    ellipse(0, 0, s, s * 0.5);
    pop();
  }

  // Tiny particles floating upward (souls/spirits)
  for (let i = 0; i < 100; i++) {
    let x = width * 0.2 + random(width * 0.6);
    let y = random(height * 0.7);
    let s = random(1, 3);
    let alpha = random(20, 70);
    let bright = random(100, 180);
    fill(bright, bright * 0.9, bright * 1.1, alpha);
    ellipse(x, y, s, s);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  pixelDensity(1);

  drawSkyGradient();
  addBackgroundTexture();
  drawMoon();
  drawStars();
  drawGround();
  drawRoots();
  drawBodyGlow();
  drawBody();
  drawBotanicals();
  drawParticles();
  drawWisps();
  drawBrightSparks();
  drawAtmosphericFog();
}

function drawSkyGradient() {
  noStroke();
  for (let y = 0; y < 2000; y += 3) {
    let t = y / 2000;
    fill(lerp(6, 14, t), lerp(4, 9, t), lerp(22, 14, t));
    rect(0, y, 1600, 3);
  }
  noStroke();
  for (let i = 0; i < 18; i++) {
    let x = 800 + random(-250, 250);
    let y = random(500, 1450);
    let s = random(200, 700);
    fill(45, 28, 15, 4);
    ellipse(x, y, s, s * 1.6);
  }
}

function addBackgroundTexture() {
  noStroke();
  for (let i = 0; i < 5000; i++) {
    let x = random(1600);
    let y = random(2000);
    let n = noise(x * 0.003, y * 0.003);
    fill(255, 255, 255, n * 12);
    ellipse(x, y, random(1, 2.5), random(1, 2.5));
  }
}

function drawMoon() {
  noStroke();
  for (let i = 6; i > 0; i--) {
    fill(180, 190, 220, 2.5);
    ellipse(1250, 280, 80 + i * 55, 80 + i * 55);
  }
  fill(195, 200, 222, 35);
  ellipse(1250, 280, 85, 85);
  fill(215, 220, 238, 45);
  ellipse(1250, 280, 55, 55);
}

function drawStars() {
  noStroke();
  for (let i = 0; i < 350; i++) {
    let x = random(1600);
    let y = random(1200);
    let s = random(0.5, 2.8);
    let alpha = random(40, 190);
    let tint = random(1);
    if (tint < 0.7) fill(200, 210, 240, alpha);
    else if (tint < 0.9) fill(240, 220, 180, alpha);
    else fill(220, 180, 180, alpha);
    ellipse(x, y, s, s);
  }
}

function drawGround() {
  noStroke();
  fill(14, 10, 7);
  beginShape();
  vertex(0, 2000);
  for (let x = 0; x <= 1600; x += 6) {
    let gy = 1462 + noise(x * 0.004) * 28 - 14;
    vertex(x, gy);
  }
  vertex(1600, 2000);
  endShape(CLOSE);

  for (let i = 0; i < 2500; i++) {
    let x = random(1600);
    let gy = 1462 + noise(x * 0.004) * 28 - 14;
    let y = random(gy - 3, 2000);
    let depth = constrain((y - gy) / 500, 0, 1);
    let n = noise(x * 0.012, y * 0.012);
    fill(18 + n * 22 - depth * 8, 12 + n * 15 - depth * 6, 7 + n * 9 - depth * 3, random(25, 70));
    ellipse(x, y, random(2, 7), random(1.5, 5));
  }
}

function drawRoots() {
  noFill();
  for (let i = 0; i < 45; i++) {
    let sx = random(440, 1220);
    let gy = 1462 + noise(sx * 0.004) * 28 - 14;
    let sy = gy + random(8, 25);
    let alpha = random(25, 75);
    stroke(38, 27, 18, alpha);
    strokeWeight(random(0.5, 1.8));
    beginShape();
    vertex(sx, sy);
    let cx = sx, cy = sy;
    let segs = floor(random(3, 8));
    for (let s = 0; s < segs; s++) {
      cx += random(-22, 22);
      cy += random(14, 38);
      vertex(cx, cy);
    }
    endShape();
    if (random() > 0.4) {
      strokeWeight(random(0.3, 0.8));
      stroke(38, 27, 18, alpha * 0.5);
      line(cx, cy, cx + random(-18, 18), cy + random(8, 22));
    }
  }
}

function drawBodyGlow() {
  noStroke();
  for (let i = 0; i < 30; i++) {
    let x = random(380, 1220);
    let y = random(1370, 1500);
    let s = random(80, 320);
    fill(180, 120, 55, 3);
    ellipse(x, y, s, s * 0.45);
  }
  for (let i = 0; i < 28; i++) {
    let x = random(420, 1180);
    let y = random(450, 1460);
    let s = random(120, 500);
    fill(200, 155, 95, 2);
    ellipse(x, y, s, s * 1.6);
  }
}

function drawBody() {
  noStroke();
  let R = 75, G = 58, B = 48;

  fill(8, 6, 4, 110);
  ellipse(820, 1468, 840, 32);

  fill(R - 5, G - 5, B - 3, 200);
  ellipse(1115, 1448, 145, 42);
  fill(R - 3, G - 3, B - 2, 190);
  ellipse(1200, 1453, 55, 28);

  fill(R, G, B, 210);
  ellipse(985, 1440, 165, 58);

  fill(R + 2, G + 1, B + 1, 215);
  ellipse(882, 1432, 115, 72);

  fill(R + 3, G + 2, B + 1, 220);
  ellipse(782, 1425, 145, 78);

  fill(R + 5, G + 3, B + 2, 225);
  ellipse(662, 1414, 175, 95);

  fill(R + 3, G + 2, B + 1, 210);
  ellipse(567, 1418, 78, 55);

  fill(R + 8, G + 6, B + 4, 230);
  ellipse(497, 1410, 98, 84);

  fill(R, G, B, 170);
  ellipse(705, 1453, 185, 35);
  fill(R + 5, G + 3, B + 2, 160);
  ellipse(602, 1456, 42, 28);

  fill(155, 135, 115, 28);
  ellipse(497, 1383, 72, 16);
  ellipse(662, 1382, 135, 16);
  ellipse(782, 1398, 105, 14);
  ellipse(882, 1408, 82, 13);
  ellipse(985, 1418, 125, 13);
  ellipse(1115, 1432, 105, 11);
}

function drawBotanicals() {
  for (let i = 0; i < 85; i++) {
    let x = random(340, 1260);
    let gy = 1462 + noise(x * 0.004) * 28 - 14;
    let by = gy + random(-8, 4);
    let stemH = random(12, 48);
    let bend = random(-9, 9);
    stroke(32 + random(18), 52 + random(18), 28 + random(12), random(70, 140));
    strokeWeight(random(0.5, 1.2));
    line(x, by, x + bend, by - stemH);
    noStroke();
    let fx = x + bend, fy = by - stemH;
    let fs = random(2.5, 6.5);
    let petals = floor(random(4, 7));
    for (let p = 0; p < petals; p++) {
      let a = (p / petals) * TWO_PI + random(-0.2, 0.2);
      fill(208 + random(22), 203 + random(22), 193 + random(18), random(110, 200));
      ellipse(fx + cos(a) * fs, fy + sin(a) * fs * 0.8, fs * 0.7, fs * 0.7);
    }
    fill(198, 172, 88, 175);
    ellipse(fx, fy, fs * 0.4, fs * 0.4);
  }
  noFill();
  for (let i = 0; i < 280; i++) {
