}

function drawParticles() {
  noStroke();
  let regions = [
    { x: 497, y: 1410, w: 98, h: 84 },
    { x: 567, y: 1418, w: 78, h: 55 },
    { x: 662, y: 1414, w: 175, h: 95 },
    { x: 782, y: 1425, w: 145, h: 78 },
    { x: 882, y: 1432, w: 115, h: 72 },
    { x: 985, y: 1440, w: 165, h: 58 },
    { x: 1115, y: 1448, w: 145, h: 42 },
    { x: 705, y: 1453, w: 185, h: 35 }
  ];

  for (let i = 0; i < 10000; i++) {
    let reg = regions[floor(random(regions.length))];
    let angle = random(TWO_PI);
    let r = sqrt(random(1));
    let sx = reg.x + cos(angle) * r * reg.w / 2;
    let sy = reg.y + sin(angle) * r * reg.h / 2;

    let maxRise = random(180, 1250);
    let t = pow(random(0, 1), 0.65);
    let rise = maxRise * t;

    let driftBase = (noise(sx * 0.0018, sy * 0.0018) - 0.5) * 1.9;
    let wobble = (noise(sx * 0.007 + i * 0.0002, sy * 0.007) - 0.5) * 1.8;

    let px = sx + driftBase * rise * 0.22 + wobble * rise * 0.12;
    let py = sy - rise;

    let size = lerp(3.8, 0.7, t) * random(0.5, 1.5);

    let cr, cg, cb;
    if (t < 0.3) {
      let u = t / 0.3;
      cr = 255; cg = lerp(165, 200, u); cb = lerp(55, 115, u);
    } else if (t < 0.7) {
      let u = (t - 0.3) / 0.4;
      cr = lerp(255, 210, u); cg = lerp(200, 215, u); cb = lerp(115, 232, u);
    } else {
      let u = (t - 0.7) / 0.3;
      cr = lerp(210, 180, u); cg = lerp(215, 200, u); cb = lerp(232, 255, u);
    }

    let alpha = lerp(165, 2, pow(t, 0.75)) * random(0.4, 1.5);
    alpha = constrain(alpha, 0, 220);

    fill(cr, cg, cb, alpha);
    ellipse(px, py, size, size);
  }
}

