function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function draw() {
  // Background gradient - deep dark void
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(5, 12, t);
    let g = lerp(8, 6, t);
    let b = lerp(25, 15, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Noise texture overlay for painterly feel
  loadPixels();
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let n = noise(x * 0.008, y * 0.008) * 20 - 10;
      let idx = (y * width + x) * 4;
      pixels[idx] = constrain(pixels[idx] + n, 0, 255);
      pixels[idx + 1] = constrain(pixels[idx + 1] + n, 0, 255);
      pixels[idx + 2] = constrain(pixels[idx + 2] + n, 0, 255);
    }
  }
  updatePixels();

  // Distant atmospheric glow - upper right
  for (let i = 0; i < 800; i++) {
    let angle = random(TWO_PI);
    let radius = random(300) + random(200);
    let px = 1100 + cos(angle) * radius;
    let py = 400 + sin(angle) * radius * 0.6;
    let alpha = map(radius, 0, 500, 12, 0);
    fill(40, 35, 60, alpha);
    noStroke();
    ellipse(px, py, random(3, 8), random(3, 8));
  }

  // Ground plane - desolate horizon
  let horizonY = 1550;
  for (let y = horizonY; y < height; y++) {
    let t = (y - horizonY) / (height - horizonY);
    let r = lerp(15, 8, t);
    let g = lerp(12, 5, t);
    let b = lerp(18, 10, t);
    for (let x = 0; x < width; x++) {
      let n = noise(x * 0.005, y * 0.01) * 10;
      fill(r + n, g + n * 0.8, b + n * 0.5, 200);
      noStroke();
      rect(x, y, 1, 1);
    }
  }

  // Ground texture lines
  for (let i = 0; i < 200; i++) {
    let x = random(width);
    let y = random(horizonY, height);
    let len = random(20, 80);
    stroke(25, 20, 30, random(30, 80));
    strokeWeight(random(0.5, 1.5));
    line(x, y, x + len, y + random(-2, 2));
  }

  // The figure - positioned lower left of center
  let figX = 580;
  let figBaseY = 1540;
  let figHeight = 600;
  let figTopY = figBaseY - figHeight;

  // Figure body silhouette using bezier shapes
  drawFigure(figX, figTopY, figHeight);

  // Particle dissolution - particles streaming from right side of figure
  // Phase 1: Dense particles near the body edge
  for (let i = 0; i < 5000; i++) {
    let bodyT = random();
    let bodyY = figTopY + bodyT * figHeight;
    let bodyWidth = getFigureWidth(bodyT) * 0.8;
    let startX = figX + bodyWidth * 0.3 + random(-10, 10);

    let dist = random(0, 250);
    let angle = random(-PI * 0.6, -PI * 0.1);
    let drift = random(-30, 50);

    let px = startX + cos(angle) * dist + drift;
    let py = bodyY + sin(angle) * dist * 0.7 + random(-20, 20);

    let t = dist / 250;
    let size = lerp(3.5, 0.8, t);
    let alpha = lerp(220, 20, t * t);

    // Color transition: dark body to amber/warm glow
    let r = lerp(30, 200, t);
    let g = lerp(25, 140, t);
    let b = lerp(35, 50, t);

    fill(r, g, b, alpha);
    noStroke();
    ellipse(px, py, size, size);
  }

  // Phase 2: Medium distance particles - more spread
  for (let i = 0; i < 3000; i++) {
    let bodyT = random(0.1, 0.9);
    let bodyY = figTopY + bodyT * figHeight;
    let startX = figX + random(20, 60);

    let dist = random(100, 500);
    let angle = random(-PI * 0.7, -PI * 0.05);
    let drift = random(-50, 80);

    let px = startX + cos(angle) * dist + drift;
    let py = bodyY + sin(angle) * dist * 0.5 + random(-40, 40);

    let t = dist / 500;
    let size = lerp(2.5, 0.5, t);
    let alpha = lerp(150, 5, t);

    let r = lerp(150, 80, t);
    let g = lerp(100, 60, t);
    let b = lerp(40, 90, t);

    fill(r, g, b, alpha);
    noStroke();
    ellipse(px, py, size, size);
  }

  // Phase 3: Far scattered particles - ethereal
  for (let i = 0; i < 2000; i++) {
    let px = random(figX + 100, width - 100);
    let py = random(figTopY - 200, figBaseY);

    let distFromFig = dist(px, py, figX + 50, figTopY + figHeight * 0.5);
    let t = map(distFromFig, 0, 800, 0, 1, true);

    let size = lerp(2, 0.3, t);
    let alpha = lerp(80, 3, t);

    let r = lerp(180, 60, t);
    let g = lerp(130, 50, t);
    let b = lerp(50, 100, t);

    fill(r, g, b, alpha);
    noStroke();
    ellipse(px, py, size, size);
  }

  // Subtle light rays from dissolution area
  for (let i = 0; i < 15; i++) {
    let startX = figX + random(30, 80);
    let startY = figTopY + random(100, 400);
    let endX = startX + random(200, 600);
    let endY = startY + random(-200, 50);

    stroke(180, 130, 60, random(3, 8));
    strokeWeight(random(0.5, 2));
    line(startX, startY, endX, endY);
  }

  // Falling particles near ground - settling dust
  for (let i = 0; i < 500; i++) {
    let px = random(figX - 100, figX + 500);
    let py = random(figBaseY - 50, figBaseY + 30);
    let size = random(0.5, 2);
    let alpha = random(20, 80);
    fill(60, 45, 40, alpha);
    noStroke();
    ellipse(px, py, size, size);
  }

  // Final atmospheric noise overlay
  for (let i = 0; i < 20000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.003, y * 0.003);
    if (n > 0.55) {
      fill(255, 255, 255, random(1, 3));
      noStroke();
      point(x, y);
    }
  }

  // Vignette
  for (let i = 0; i < 100; i++) {
    let t = i / 100;
    noFill();
    stroke(0, 0, 0, t * 8);
    strokeWeight(20);
    rect(i * 8, i * 10, width - i * 16, height - i * 20);
  }
}

function getFigureWidth(t) {
  // Returns approximate width of figure at normalized height t (0=top, 1=bottom)
  if (t < 0.12) return lerp(20, 50, t / 0.12); // head
  if (t < 0.18) return lerp(50, 35, (t - 0.12) / 0.06); // neck
  if (t < 0.5) return lerp(35, 80, (t - 0.18) / 0.32); // torso widening
  if (t < 0.55) return lerp(80, 70, (t - 0.5) / 0.05); // waist
  if (t < 0.85) return lerp(70, 40, (t - 0.55) / 0.3); // legs
  return lerp(40, 50, (t - 0.85) / 0.15); // feet
}

function drawFigure(cx, topY, h) {
  // Draw a simplified human silhouette
  noStroke();

  // Head
  fill(18, 15, 22);
  ellipse(cx, topY + h * 0.07, 48, 55);

  // Neck
  rect(cx - 12, topY + h * 0.1, 24, h * 0.06);

  // Torso - using bezier for organic shape
  beginShape();
  vertex(cx - 35, topY + h * 0.16);
  bezierVertex(cx - 55, topY + h * 0.25, cx - 60, topY + h * 0.35, cx - 50, topY + h * 0.48);
  vertex(cx - 35, topY + h * 0.52);
  vertex(cx + 35, topY + h * 0.52);
  vertex(cx + 50, topY + h * 0.48);
  bezierVertex(cx + 60, topY + h * 0.35, cx + 55, topY + h * 0.25, cx + 35, topY + h * 0.16);
  endShape(CLOSE);

  // Arms
  // Left arm (intact side)
  beginShape();
  vertex(cx - 50, topY + h * 0.18);
  bezierVertex(cx - 70, topY + h * 0.3, cx - 65, topY + h * 0.45, cx - 55, topY + h * 0.55);
  vertex(cx - 48, topY + h * 0.55);
  bezierVertex(cx - 55, topY + h * 0.45, cx - 58, topY + h * 0.3, cx - 42, topY + h * 0.2);
  endShape(CLOSE);

  // Right arm (dissolving side) - partially drawn
  beginShape();
  vertex(cx + 42, topY + h * 0.2);
  bezierVertex(cx + 58, topY + h * 0.3, cx + 55, topY + h * 0.38, cx + 52, topY + h * 0.42);
  vertex(cx + 48, topY + h * 0.4);
  bezierVertex(cx + 50, topY + h * 0.35, cx + 52, topY + h * 0.28, cx + 38, topY + h * 0.2);
  endShape(CLOSE);

  // Legs
  // Left leg
  beginShape();
  vertex(cx - 30, topY + h * 0.52);
  bezierVertex(cx - 32, topY + h * 0.7, cx - 28, topY + h * 0.85, cx - 25, topY + h * 0.98);
  vertex(cx - 8, topY + h * 0.98);
  bezierVertex(cx - 10, topY + h * 0.85, cx - 8, topY + h * 0.7, cx - 5, topY + h * 0.52);
  endShape(CLOSE);

  // Right leg (partially dissolving at bottom)
  beginShape();
  vertex(cx + 5, topY + h * 0.52);
  bezierVertex(cx + 8, topY + h * 0.65, cx + 10, topY + h * 0.75, cx + 12, topY + h * 0.82);
  vertex(cx + 28, topY + h * 0.82);
  bezierVertex(cx + 28, topY + h * 0.75, cx + 30, topY + h * 0.65, cx + 30, topY + h * 0.52);
  endShape(CLOSE);

  // Dissolving edge effect on the right side of the figure
  for (let i = 0; i < 800; i++) {
    let t = random();
    let fy = topY + t * h * 0.9;
    let fw = getFigureWidth(t);
    let fx = cx + fw * random(0.3, 0.55);
    let size = random(1, 4);
    let alpha = random(80, 200);
    fill(22, 18, 28, alpha);
    noStroke();
    ellipse(fx + random(-5, 15), fy + random(-5, 5), size, size);
  }

  // Shadow beneath figure
  fill(5, 3, 8, 60);
  noStroke();
  ellipse(cx - 10, topY + h + 5, 120, 15);
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function draw() {
  background(10, 12, 25);

  // Sky gradient
  for (let y = 0; y < 900; y++) {
    let t = y / 900;
    let r = lerp(5, 20, t);
    let g = lerp(8, 18, t);
    let b = lerp(22, 45, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Water gradient (mirror, darker)
  for (let y = 900; y < height; y++) {
    let t = (y - 900) / (height - 900);
    let r = lerp(15, 4, t);
    let g = lerp(14, 5, t);
    let b = lerp(38, 15, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Horizon glow
  let glowX = width / 2;
  let glowY = 900;
  for (let radius = 400; radius > 0; radius -= 2) {
    let alpha = map(radius, 0, 400, 60, 0);
    let r = lerp(255, 80, radius / 400);
    let g = lerp(200, 50, radius / 400);
    let b = lerp(100, 30, radius / 400);
    noStroke();
    fill(r, g, b, alpha);
    ellipse(glowX, glowY, radius * 2, radius * 0.5);
  }

  // Bright core of light
  for (let radius = 80; radius > 0; radius -= 1) {
    let alpha = map(radius, 0, 80, 180, 0);
    fill(255, 235, 180, alpha);
    noStroke();
    ellipse(glowX, glowY, radius * 1.5, radius * 0.4);
  }

  // Stars
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = random(0, 850);
    let distToCenter = dist(x, y, glowX, glowY);
    if (distToCenter < 300) continue;
    let sz = random(1, 3.5);
    let bright = random(100, 255);
    let flicker = noise(x * 0.01, y * 0.01) * 80;
    fill(bright - flicker, bright - flicker + 10, bright + 20 - flicker, random(150, 255));
    noStroke();
    ellipse(x, y, sz, sz);
  }

  // Water ripples
  for (let y = 910; y < height; y += 6) {
    let distFromHorizon = y - 900;
    let alpha = map(distFromHorizon, 0, 1100, 40, 5);
    for (let x = 0; x < width; x += random(20, 60)) {
      let waveLen = random(30, 120);
      let n = noise(x * 0.003, y * 0.01);
      if (n > 0.5) {
        let rippleAlpha = alpha * noise(x * 0.005, y * 0.005);
        // Reflection of the light
        let distToGlow = abs(x - glowX);
        if (distToGlow < 300 && distFromHorizon < 500) {
          let refBright = map(distToGlow, 0, 300, 120, 0) * map(distFromHorizon, 0, 500, 1, 0.2);
          stroke(200, 160, 80, refBright * noise(x * 0.01, y * 0.01));
        } else {
          stroke(40, 50, 80, rippleAlpha);
        }
        strokeWeight(1);
        line(x, y, x + waveLen, y + random(-1, 1));
      }
    }
  }

  // Light reflection path on water
  for (let y = 905; y < 1500; y += 3) {
    let distFromHorizon = y - 900;
    let spread = map(distFromHorizon, 0, 600, 10, 120);
    let alpha = map(distFromHorizon, 0, 600, 100, 5);
    for (let i = 0; i < 8; i++) {
      let rx = glowX + random(-spread, spread);
      let rw = random(5, 25);
      let n = noise(rx * 0.01, y * 0.02);
      if (n > 0.35) {
        noStroke();
        fill(255, 200, 100, alpha * n);
        rect(rx, y, rw, 2);
      }
    }
  }

  // Boat
  let boatX = width / 2;
  let boatY = 1400;

  // Boat hull
  noStroke();
  fill(20, 15, 12);
  beginShape();
  vertex(boatX - 90, boatY);
  vertex(boatX - 70, boatY + 25);
  vertex(boatX + 70, boatY + 25);
  vertex(boatX + 90, boatY);
  vertex(boatX + 100, boatY - 5);
  vertex(boatX - 100, boatY - 5);
  endShape(CLOSE);

  // Boat reflection
  fill(10, 10, 20, 60);
  beginShape();
  vertex(boatX - 80, boatY + 26);
  vertex(boatX - 60, boatY + 55);
  vertex(boatX + 60, boatY + 55);
  vertex(boatX + 80, boatY + 26);
  endShape(CLOSE);

  // Figure (standing person with cloak)
  fill(15, 12, 18);
  noStroke();
  // Body/cloak
  beginShape();
  vertex(boatX - 15, boatY - 5);
  vertex(boatX - 25, boatY - 80);
  vertex(boatX - 20, boatY - 130);
  vertex(boatX - 10, boatY - 160);
  vertex(boatX, boatY - 175);
  vertex(boatX + 10, boatY - 160);
  vertex(boatX + 20, boatY - 130);
  vertex(boatX + 25, boatY - 80);
  vertex(boatX + 15, boatY - 5);
  endShape(CLOSE);

  // Head
  fill(12, 10, 15);
  ellipse(boatX, boatY - 185, 22, 26);

  // Figure reflection in water
  fill(10, 10, 20, 40);
  beginShape();
  vertex(boatX - 12, boatY + 26);
  vertex(boatX - 18, boatY + 80);
  vertex(boatX - 14, boatY + 130);
  vertex(boatX, boatY + 160);
  vertex(boatX + 14, boatY + 130);
  vertex(boatX + 18, boatY + 80);
  vertex(boatX + 12, boatY + 26);
  endShape(CLOSE);

  // Pole/oar the figure holds
  stroke(25, 20, 15);
  strokeWeight(3);
  line(boatX + 8, boatY - 160, boatX + 30, boatY + 60);

  // Distant shore silhouette
  noStroke();
  fill(8, 10, 18);
  beginShape();
  vertex(0, 900);
  for (let x = 0; x <= width; x += 20) {
    let h = noise(x * 0.002) * 30 + 5;
    // Gap in the middle for the light
    let distToCenter = abs(x - glowX);
    if (distToCenter < 200) {
      h = h * map(distToCenter, 0, 200, 0, 1);
    }
    vertex(x, 895 - h);
  }
  vertex(width, 900);
  endShape(CLOSE);

  // Mist layers near horizon
  for (let i = 0; i < 15; i++) {
    let mistY = 850 + random(0, 100);
    let mistX = random(0, width);
    let mistW = random(200, 600);
    let mistH = random(20, 50);
    let alpha = random(10, 30);
    fill(80, 90, 120, alpha);
    noStroke();
    ellipse(mistX, mistY, mistW, mistH);
  }

  // Subtle vignette
  for (let i = 0; i < 80; i++) {
    noFill();
    stroke(0, 0, 0, 3);
    strokeWeight(20);
    rect(i * 2, i * 2, width - i * 4, height - i * 4);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();

  background(4, 2, 10);
  noStroke();

  let cx = width / 2;
  let baseY = 1750;

  // Ambient warm glow behind the form
  for (let i = 70; i > 0; i--) {
    let s = i * 14;
    fill(35, 18, 8, map(i, 70, 0, 0, 2.2));
    ellipse(cx, baseY - 300, s * 1.3, s * 2.4);
  }

  // Subtle cool tone upper region
  for (let i = 50; i > 0; i--) {
    let s = i * 16;
    fill(8, 6, 22, map(i, 50, 0, 0, 1.2));
    ellipse(cx, 350, s * 2.0, s * 1.4);
  }

  // === MAIN PARTICLE SYSTEM ===
  for (let i = 0; i < 280000; i++) {
    // life: 1 = coherent base, 0 = fully dissolved top
    let life = pow(random(), 0.45);

    let y = lerp(60, baseY, life);
    y += (noise(i * 0.007, 0) - 0.5) * 130 * (1 - life);

    // Horizontal spread widens as life decreases
    let spread = lerp(680, 65, pow(life, 0.8));
    let x = cx + randomGaussian() * spread * 0.27;

    // Organic turbulence via noise
    let turb = lerp(240, 22, life);
    x += (noise(x * 0.0017, y * 0.0019) - 0.5) * turb * 2;
    y += (noise(x * 0.0017 + 77, y * 0.0019 + 77) - 0.5) * turb * 0.55;

    // Flow field displacement (smoke-like streams)
    let flowN = noise(x * 0.0028, y * 0.0023, 1.5);
    let flowAngle = flowN * TWO_PI * 1.5;
    let flowMag = (1 - life) * 110 * noise(x * 0.004 + 300, y * 0.004);
    x += cos(flowAngle) * flowMag;
    y += sin(flowAngle) * flowMag * 0.4 - flowMag * 0.28;

    if (x < -40 || x > width + 40 || y < -40 || y > height + 40) continue;

    // Sparsity: fewer particles at low life
    if (life < 0.10 && random() > life * 5.5) continue;
    if (life < 0.22 && random() > 0.35 + life * 1.8) continue;

    // Color gradient: warm gold → amber → crimson → dark blue
    let r, g, b;
    if (life > 0.75) {
      let t = (life - 0.75) / 0.25;
      r = lerp(232, 255, t);
      g = lerp(172, 246, t);
      b = lerp(72, 218, t);
    } else if (life > 0.5) {
      let t = (life - 0.5) / 0.25;
      r = lerp(192, 232, t);
      g = lerp(82, 172, t);
      b = lerp(32, 72, t);
    } else if (life > 0.25) {
      let t = (life - 0.25) / 0.25;
      r = lerp(92, 192, t);
      g = lerp(36, 82, t);
      b = lerp(46, 32, t);
    } else {
      let t = life / 0.25;
      r = lerp(20, 92, t);
      g = lerp(18, 36, t);
      b = lerp(40, 46, t);
    }

    // Alpha: opaque at core, transparent when dissolved
    let a;
    if (life > 0.7) {
      a = map(life, 0.7, 1, 20, 62);
    } else if (life > 0.3) {
      a = map(life, 0.3, 0.7, 6, 20);
    } else {
      a = map(life, 0, 0.3, 1.2, 6);
    }
    a *= (0.5 + random() * 1.0);
    a = constrain(a, 0, 78);

    // Size
    let sz = lerp(0.6, 2.8, life) * (0.7 + random() * 0.6);

    fill(r, g, b, a);
    ellipse(x, y, sz, sz);
  }

  // === BRIGHT CORE with additive blending ===
  drawingContext.globalCompositeOperation = 'lighter';
  for (let i = 0; i < 14000; i++) {
    let angle = random(TWO_PI);
    let dist = pow(random(), 2.5) * 95;
    let x = cx + cos(angle) * dist * 0.5;
    let y = baseY - 12 + sin(angle) * dist * 0.25;

    let alpha = map(dist, 0, 95, 45, 0);
    let sz = map(dist, 0, 95, 6, 1.5);

    fill(255, 248, 235, alpha);
    ellipse(x, y, sz, sz);
  }

  // Secondary core glow
  for (let i = 0; i < 3000; i++) {
    let angle = random(TWO_PI);
    let dist = pow(random(), 3) * 60;
    let x = cx + cos(angle) * dist * 0.45;
    let y = baseY - 10 + sin(angle) * dist * 0.2;

    let alpha = map(dist, 0, 60, 25, 0);
    let sz = map(dist, 0, 60, 8, 2);

    fill(255, 220, 180, alpha);
    ellipse(x, y, sz, sz);
  }
  drawingContext.globalCompositeOperation = 'source-over';

  // === SCATTERED REMNANT PARTICLES (far from form) ===
  for (let i = 0; i < 8000; i++) {
    let x = random(width);
    let y = random(height * 0.7);

    // Only keep some based on noise (organic distribution)
    let n = noise(x * 0.002, y * 0.002, 5);
    if (n < 0.45) continue;

    // Distance from center affects visibility
    let dFromCenter = dist(x, y, cx, baseY - 400) / 800;
    let alpha = map(dFromCenter, 0, 1.5, 6, 0.5);
    alpha *= noise(x * 0.01, y * 0.01, 10);
    alpha = constrain(alpha, 0, 8);

    let r = lerp(20, 50, noise(x * 0.005, y * 0.005));
    let g = lerp(18, 35, noise(x * 0.005 + 50, y * 0.005));
    let b = lerp(38, 60, noise(x * 0.005, y * 0.005 + 50));

    fill(r, g, b, alpha);
    ellipse(x, y, random(0.5, 1.5), random(0.5, 1.5));
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  pixelDensity(1);
}

function draw() {
  background(6, 6, 16);

  // Deep atmospheric gradient
  for (let r = 1000; r > 0; r -= 3) {
    let a = map(r, 0, 1000, 12, 0);
    noStroke();
    fill(20, 16, 40, a);
    ellipse(800, 950, r * 2.2, r * 2.8);
  }

  // Warm core glow behind figure
  for (let r = 500; r > 0; r -= 4) {
    let a = map(r, 0, 500, 8, 0);
    fill(60, 45, 25, a);
    ellipse(800, 1100, r * 1.5, r * 2.2);
  }

  // Ambient dispersed particles (matter already returned)
  for (let i = 0; i < 4000; i++) {
    let x = random(width);
    let y = random(height);
    let d = dist(x, y, 800, 700);
    let a = map(d, 0, 1200, 50, 3);
    a = max(0, a) * random(0.3, 1);
    let sz = random(0.5, 2.5);
    fill(190, 170, 140, a);
    noStroke();
    ellipse(x, y, sz, sz);
  }

  // Main dissolving form
  drawForm();

  // Rising detached particles
  drawRisingParticles();

  // Subtle top fade to pure black
  for (let y = 0; y < 300; y++) {
    let a = map(y, 0, 300, 180, 0);
    stroke(6, 6, 16, a);
    line(0, y, width, y);
  }
}

function formHalfWidth(y) {
  let t = constrain(map(y, 320, 1860, 0, 1), 0, 1);
  let w = 0;
  if (t < 0.11) {
    w = sin((t / 0.11) * PI) * 85;
  } else if (t < 0.19) {
    w = lerp(30, 55, (t - 0.11) / 0.08);
  } else if (t < 0.48) {
    let s = (t - 0.19) / 0.29;
    w = 55 + sin(s * PI) * 115;
  } else if (t < 0.54) {
    w = lerp(55, 65, (t - 0.48) / 0.06);
  } else if (t < 0.62) {
    w = lerp(65, 90, (t - 0.54) / 0.08);
  } else {
    w = lerp(90, 70, (t - 0.62) / 0.38);
  }
  w += (noise(y * 0.007) - 0.5) * 22;
  return max(0, w);
}

function drawForm() {
  let cx = 800;
  let points = [];

  for (let i = 0; i < 120000; i++) {
    let y = random(320, 1870);
    let hw = formHalfWidth(y);
    if (hw < 1.5) continue;

    let x = cx + random(-hw, hw);

    // Dissolve factor: 0 at bottom, 1 at top
    let dissolve = constrain(map(y, 1860, 340, 0, 1), 0, 1);
    dissolve = pow(dissolve, 2.2);

    // Probability of point existing drops with dissolve
    if (random() < dissolve * 0.65) continue;

    // Noise-based displacement
    let n1 = noise(x * 0.004, y * 0.004);
    let n2 = noise(x * 0.004 + 77, y * 0.004 + 33);
    let dx = (n1 - 0.5) * dissolve * 550;
    let dy = (n2 - 0.5) * dissolve * 350;
    dy -= dissolve * random(20, 180);

    let fx = x + dx;
    let fy = y + dy;

    // Color: warm core to cooler edges
    let edgeFactor = abs(x - cx) / max(hw, 1);
    let bright = lerp(248, 180, dissolve) + random(-12, 12);
    let warm = lerp(0, 50, dissolve) + edgeFactor * 20;

    let r = constrain(bright + warm * 0.4, 0, 255);
    let g = constrain(bright - warm * 0.15, 0, 255);
    let b = constrain(bright - warm * 0.55, 0, 255);
    let a = lerp(220, 18, dissolve) * random(0.6, 1);

    let sz = lerp(3.8, 1.2, dissolve) * random(0.7, 1.3);

    noStroke();
    fill(r, g, b, a);
    ellipse(fx, fy, sz, sz);
  }
}

function drawRisingParticles() {
  // Fully detached particles rising from the dissolving upper form
  for (let i = 0; i < 6000; i++) {
    let originY = random(320, 800);
    let hw = formHalfWidth(originY);
    if (hw < 8) continue;

    let originX = 800 + random(-hw, hw);
    let rise = random(30, 700);
    let drift = (noise(originX * 0.008, originY * 0.008) - 0.5) * 400;

    let x = originX + drift;
    let y = originY - rise;

    let fadeFactor = rise / 700;
    let a = map(fadeFactor, 0, 1, 90, 2) * random(0.5, 1);
    let sz = map(fadeFactor, 0, 1, 3, 0.4);

    let r = lerp(235, 150, fadeFactor);
    let g = lerp(220, 130, fadeFactor);
    let b = lerp(195, 120, fadeFactor);

    noStroke();
    fill(r, g, b, a);
    ellipse(x, y, sz, sz);
  }

  // Fine dust trails
  for (let i = 0; i < 2000; i++) {
    let x = random(300, 1300);
    let y = random(50, 600);
    let a = random(5, 25);
    let sz = random(0.3, 1.2);
    fill(200, 185, 160, a);
    noStroke();
    ellipse(x, y, sz, sz);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function draw() {
  background(12, 10, 28);

  // Draw subtle background gradient atmosphere
  for (let y = 0; y < 2000; y++) {
    let inter = y / 2000;
    let c = lerpColor(color(8, 6, 22), color(18, 15, 38), inter);
    stroke(c);
    line(0, y, 1600, y);
  }

  // Define silhouette parameters
  let cx = 800;
  let figureTop = 350;
  let figureBottom = 1650;
  let figureHeight = figureBottom - figureTop;

  // Generate silhouette points
  let silhouettePoints = [];
  let numParticles = 35000;

  for (let i = 0; i < numParticles; i++) {
    let px, py;
    let valid = false;
    let attempts = 0;

    while (!valid && attempts < 50) {
      attempts++;
      px = random(cx - 250, cx + 250);
      py = random(figureTop, figureBottom);

      let normalizedY = (py - figureTop) / figureHeight;
      let halfWidth = getWidthAtY(normalizedY, cx, py, figureTop);

      if (abs(px - cx) < halfWidth) {
        valid = true;
      }
    }

    if (valid) {
      silhouettePoints.push({ x: px, y: py });
    }
  }

  // Draw particles
  noStroke();
  for (let i = 0; i < silhouettePoints.length; i++) {
    let pt = silhouettePoints[i];
    let normalizedY = (pt.y - figureTop) / figureHeight; // 0=top, 1=bottom

    // Displacement increases toward top (lower normalizedY)
    let disperseFactor = pow(1 - normalizedY, 2.2);

    let noiseX = noise(pt.x * 0.003, pt.y * 0.003) - 0.5;
    let noiseY = noise(pt.x * 0.003 + 100, pt.y * 0.003 + 100) - 0.5;

    let maxDisplace = 600;
    let dx = noiseX * maxDisplace * disperseFactor;
    let dy = noiseY * maxDisplace * disperseFactor * 0.7;

    // Additional upward drift for dispersed particles
    dy -= disperseFactor * 150 * noise(pt.x * 0.01, pt.y * 0.01);

    let finalX = pt.x + dx;
    let finalY = pt.y + dy;

    // Color based on dispersal
    let warmColor = color(235, 180, 90); // amber/gold
    let midColor = color(200, 160, 170);  // pale rose
    let coolColor = color(60, 55, 100);   // deep indigo
    let voidColor = color(20, 18, 40);    // near background

    let c;
    if (disperseFactor < 0.3) {
      c = lerpColor(warmColor, midColor, disperseFactor / 0.3);
    } else if (disperseFactor < 0.7) {
      c = lerpColor(midColor, coolColor, (disperseFactor - 0.3) / 0.4);
    } else {
      c = lerpColor(coolColor, voidColor, (disperseFactor - 0.7) / 0.3);
    }

    // Alpha decreases with dispersal
    let alpha = map(disperseFactor, 0, 1, 220, 15);
    alpha = max(alpha, 8);

    // Size varies - smaller when dispersed
    let sz = map(disperseFactor, 0, 1, 3.5, 1.2);
    sz += random(-0.5, 0.5);

    fill(red(c), green(c), blue(c), alpha);
    ellipse(finalX, finalY, sz, sz);
  }

  // Add some extra scattered particles drifting far away (already fully dispersed)
  for (let i = 0; i < 3000; i++) {
    let angle = random(TWO_PI);
    let dist = random(200, 700);
    let px = cx + cos(angle) * dist + random(-100, 100);
    let py = figureTop - 100 + sin(angle) * dist * 0.5 + random(-200, 200);

    if (py < figureTop && py > 50) {
      let alpha = map(dist, 200, 700, 40, 5);
      let sz = random(1, 2.5);
      fill(80, 70, 130, alpha);
      ellipse(px, py, sz, sz);
    }
  }

  // Soft glow at the base (remaining warmth)
  for (let r = 200; r > 0; r -= 2) {
    let alpha = map(r, 0, 200, 15, 0);
    fill(200, 140, 60, alpha);
    ellipse(cx, figureBottom - 50, r * 2, r * 1.2);
  }

  // Fine dust settling at bottom
  for (let i = 0; i < 2000; i++) {
    let px = cx + random(-300, 300);
    let py = figureBottom + random(-20, 150);
    let alpha = map(py, figureBottom - 20, figureBottom + 150, 80, 5);
    let sz = random(1, 3);
    fill(180, 130, 70, alpha * 0.5);
    ellipse(px, py, sz, sz);
  }
}

function getWidthAtY(normalizedY, cx, py, figureTop) {
  // Head: 0 - 0.12
  // Neck: 0.12 - 0.18
  // Shoulders/Torso: 0.18 - 0.55
  // Hips: 0.55 - 0.6
  // Legs: 0.6 - 1.0

  let w;
  if (normalizedY < 0.12) {
    // Head - ellipse
    let t = normalizedY / 0.12;
    w = 55 * sin(t * PI);
    w = max(w, 10);
  } else if (normalizedY < 0.18) {
    // Neck
    w = 25;
  } else if (normalizedY < 0.22) {
    // Shoulder transition
    let t = (normalizedY - 0.18) / 0.04;
    w = lerp(25, 130, t);
  } else if (normalizedY < 0.55) {
    // Torso
    let t = (normalizedY - 0.22) / 0.33;
    w = lerp(130, 95, t);
  } else if (normalizedY < 0.6) {
    // Hips
    let t = (normalizedY - 0.55) / 0.05;
    w = lerp(95, 105, t);
  } else if (normalizedY < 0.62) {
    // Leg gap start
    w = 105;
  } else {
    // Legs (two separate columns)
    let t = (normalizedY - 0.62) / 0.38;
    w = lerp(105, 70, t);
  }

  return w;
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function draw() {
  background(8, 6, 12);

  // Deep atmospheric gradient background
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(12, 4, t);
    let g = lerp(8, 3, t);
    let b = lerp(18, 10, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Subtle background noise texture
  loadPixels();
  for (let x = 0; x < width; x += 2) {
    for (let y = 0; y < height; y += 2) {
      let n = noise(x * 0.003, y * 0.003);
      let idx = (y * width + x) * 4;
      let add = (n - 0.5) * 12;
      pixels[idx] = constrain(pixels[idx] + add, 0, 255);
      pixels[idx + 1] = constrain(pixels[idx + 1] + add, 0, 255);
      pixels[idx + 2] = constrain(pixels[idx + 2] + add, 0, 255);
    }
  }
  updatePixels();

  // Central form parameters
  let centerX = width / 2;
  let formTop = 200;
  let formBottom = 1700;
  let formHeight = formBottom - formTop;

  // Draw the coherent form dissolving downward
  // Using many small elements
  noStroke();

  // Layer 1: Deep glow behind the form
  for (let i = 0; i < 800; i++) {
    let t = random(1);
    let y = formTop + t * formHeight;
    let dissolution = pow(t, 1.5);
    let spread = lerp(40, 400, dissolution);
    let x = centerX + randomGaussian() * spread * 0.5;
    let alpha = lerp(20, 3, dissolution);
    let radius = lerp(30, 80, dissolution) * random(0.5, 1.5);
    let warmth = lerp(1, 0, dissolution);
    fill(
      lerp(80, 20, 1 - warmth) + random(-10, 10),
      lerp(50, 15, 1 - warmth) + random(-5, 5),
      lerp(30, 25, 1 - warmth) + random(-5, 5),
      alpha
    );
    ellipse(x, y, radius, radius);
  }

  // Layer 2: The form itself — dense particles at top, scattered at bottom
  for (let i = 0; i < 60000; i++) {
    let t = random(1); // 0 = top (coherent), 1 = bottom (dissolved)
    let y = formTop + t * formHeight;

    // Form width narrows in middle like a figure, widens as it dissolves
    let baseWidth = lerp(80, 30, sin(t * PI * 0.7)) * lerp(1, 1, t < 0.3 ? 1 : 0);
    let formWidthAtY;

    // Shape: head area narrow, body wider, then dissolving
    if (t < 0.08) {
      formWidthAtY = lerp(20, 50, t / 0.08);
    } else if (t < 0.15) {
      formWidthAtY = lerp(50, 35, (t - 0.08) / 0.07);
    } else if (t < 0.5) {
      formWidthAtY = lerp(35, 70, (t - 0.15) / 0.35);
    } else if (t < 0.7) {
      formWidthAtY = lerp(70, 50, (t - 0.5) / 0.2);
    } else {
      formWidthAtY = lerp(50, 20, (t - 0.7) / 0.3);
    }

    let dissolution = pow(t, 2.0);
    let noiseOffset = noise(y * 0.01, i * 0.0001) * 2 - 1;

    // How far from center
    let distFromCenter;
    if (dissolution < 0.3) {
      distFromCenter = randomGaussian() * formWidthAtY * 0.4;
    } else {
      let scatter = lerp(formWidthAtY, 500, (dissolution - 0.3) / 0.7);
      distFromCenter = randomGaussian() * scatter * 0.6;
    }

    let x = centerX + distFromCenter + noiseOffset * dissolution * 100;

    // Skip if too far and too dissolved
    let distRatio = abs(distFromCenter) / max(formWidthAtY, 1);
    if (dissolution < 0.5 && distRatio > 2) continue;

    // Color: warm amber at top, cooling to grey-blue at bottom
    let warmR = lerp(220, 40, dissolution);
    let warmG = lerp(160, 35, dissolution);
    let warmB = lerp(80, 50, dissolution);

    // Add variation
    warmR += random(-15, 15);
    warmG += random(-10, 10);
    warmB += random(-10, 10);

    let alpha;
    if (dissolution < 0.2) {
      alpha = lerp(180, 140, dissolution / 0.2);
    } else if (dissolution < 0.6) {
      alpha = lerp(140, 40, (dissolution - 0.2) / 0.4);
    } else {
      alpha = lerp(40, 5, (dissolution - 0.6) / 0.4);
    }

    let size = lerp(3, 1.5, dissolution) * random(0.6, 1.4);

    fill(warmR, warmG, warmB, alpha);
    ellipse(x, y, size, size);
  }

  // Layer 3: Bright ember particles drifting upward from dissolution zone
  for (let i = 0; i < 3000; i++) {
    let t = random(0.3, 1.0);
    let y = formTop + t * formHeight - random(0, 200) * t;
    let spread = lerp(50, 600, t);
    let x = centerX + randomGaussian() * spread * 0.4;

    let alpha = random(10, 60) * (1 - t);
    let brightness = random(150, 255);
    let size = random(1, 4);

    fill(brightness, brightness * 0.7, brightness * 0.3, alpha);
    ellipse(x, y, size, size);
  }

  // Layer 4: Fine bright core details at top (the "living" part)
  for (let i = 0; i < 15000; i++) {
    let t = random(0, 0.35);
    let y = formTop + t * formHeight;

    let formWidthAtY;
    if (t < 0.08) {
      formWidthAtY = lerp(18, 45, t / 0.08);
    } else if (t < 0.15) {
      formWidthAtY = lerp(45, 32, (t - 0.08) / 0.07);
    } else {
      formWidthAtY = lerp(32, 55, (t - 0.15) / 0.2);
    }

    let distFromCenter = randomGaussian() * formWidthAtY * 0.35;
    if (abs(distFromCenter) > formWidthAtY * 1.2) continue;

    let x = centerX + distFromCenter;

    let n = noise(x * 0.02, y * 0.02);
    let alpha = lerp(100, 30, t / 0.35) * n;

    let r = lerp(255, 200, t / 0.35) + random(-10, 10);
    let g = lerp(200, 140, t / 0.35) + random(-10, 10);
    let b = lerp(120, 70, t / 0.35) + random(-5, 5);

    fill(r, g, b, alpha);
    let size = random(1.5, 3.5);
    ellipse(x, y, size, size);
  }

  // Layer 5: Wisps of dissolution — elongated strokes drifting away
  for (let i = 0; i < 500; i++) {
    let t = random(0.4, 1.0);
    let y = formTop + t * formHeight;
    let x = centerX + randomGaussian() * lerp(60, 350, t);

    let angle = random(-PI, PI);
    let len = random(10, 60) * t;

    let alpha = lerp(30, 3, (t - 0.4) / 0.6);
    let r = lerp(180, 30, t);
    let g = lerp(120, 25, t);
    let b = lerp(60, 40, t);

    stroke(r, g, b, alpha);
    strokeWeight(random(0.5, 2));
    let x2 = x + cos(angle) * len;
    let y2 = y + sin(angle) * len * 0.3 - random(5, 20);
    line(x, y, x2, y2);
  }

  // Layer 6: Very faint large soft circles for atmosphere
  noStroke();
  for (let i = 0; i < 30; i++) {
    let y = random(formTop, formBottom + 200);
    let x = centerX + randomGaussian() * 300;
    let size = random(100, 500);
    let t = (y - formTop) / formHeight;
    let alpha = random(3, 12) * (1 - t * 0.7);
    fill(
      lerp(100, 20, t) + random(-10, 10),
      lerp(60, 15, t),
      lerp(40, 30, t),
      alpha
    );
    ellipse(x, y, size, size);
  }

  // Vignette
  for (let i = 0; i < 50; i++) {
    let t = i / 50;
    let alpha = lerp(0, 120, pow(t, 2));
    noFill();
    stroke(5, 3, 8, alpha);
    strokeWeight(40);
    let margin = -i * 30;
    rect(margin, margin, width - margin * 2, height - margin * 2);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function draw() {
  // Deep void background
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(10, 3, t);
    let g = lerp(6, 2, t);
    let b = lerp(22, 10, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Subtle noise texture on background
  noStroke();
  for (let i = 0; i < 20000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.008, y * 0.008);
    let a = n * 8;
    fill(30, 20, 50, a);
    ellipse(x, y, random(1, 3));
  }

  // Collect all branch segments for layered rendering
  let segments = [];
  let particles = [];

  // Generate branching structure from bottom-left
  function branch(x, y, angle, length, weight, depth, parentId) {
    if (depth > 14 || length < 2) return;

    let steps = max(4, floor(length / 2));
    let px = x;
    let py = y;

    // Distance from origin (bottom-left area)
    let originX = width * 0.12;
    let originY = height * 0.92;

    for (let s = 0; s < steps; s++) {
      let t = s / steps;
      let globalX = lerp(x, x + cos(angle) * length, t);
      let globalY = lerp(y, y + sin(angle) * length, t);

      // How far from origin (normalized)
      let dist = dist(globalX, globalY, originX, originY);
      let dissolve = constrain(map(dist, 100, 1400, 0, 1), 0, 1);
      dissolve = dissolve * dissolve; // ease in

      // Noise-based angle perturbation increasing with dissolve
      let nAngle = noise(px * 0.005, py * 0.005, depth * 0.3) * TWO_PI;
      let perturbAngle = lerp(angle, nAngle, dissolve * 0.6);

      let speed = length / steps;
      let jitter = dissolve * dissolve * 8;
      let nx = px + cos(perturbAngle) * speed + random(-jitter, jitter);
      let ny = py + sin(perturbAngle) * speed + random(-jitter, jitter);

      // Colors: warm gold -> cool blue-violet -> fade
      let r = lerp(255, 60, dissolve);
      let g = lerp(190, 50, dissolve);
      let b = lerp(50, 180, dissolve);
      let a = lerp(200, 8, dissolve * dissolve);

      let w = weight * lerp(1, 0.15, dissolve);

      // Decide if segment breaks (becomes particle)
      if (dissolve > 0.7 && random() < dissolve * 0.4) {
        particles.push({
          x: nx + random(-10, 10) * dissolve,
          y: ny + random(-10, 10) * dissolve,
          size: random(0.5, 2.5) * (1 - dissolve * 0.5),
          r: r, g: g, b: b,
          a: a * 0.7
        });
      } else {
        segments.push({
          x1: px, y1: py, x2: nx, y2: ny,
          r: r, g: g, b: b, a: a,
          w: w
        });
      }

      px = nx;
      py = ny;
    }

    // Branching
    let endX = px;
    let endY = py;
    let distEnd = dist(endX, endY, originX, originY);
    let dissolveEnd = constrain(map(distEnd, 100, 1400, 0, 1), 0, 1);

    let numBranches;
    if (depth < 3) {
      numBranches = floor(random(2, 4));
    } else if (dissolveEnd > 0.6) {
      numBranches = random() < 0.5 ? 1 : 0;
    } else {
      numBranches = floor(random(1, 3));
    }

    for (let i = 0; i < numBranches; i++) {
      let spreadAngle = dissolveEnd * 1.2 + 0.4;
      let newAngle = angle + random(-spreadAngle, spreadAngle);
      // General bias upward and rightward
      newAngle = lerp(newAngle, -PI / 4, 0.15);
      let newLen = length * random(0.55, 0.78);
      let newWeight = weight * random(0.6, 0.85);
      branch(endX, endY, newAngle, newLen, newWeight, depth + 1, parentId);
    }
  }

  // Generate multiple root branches
  let originX = width * 0.12;
  let originY = height * 0.92;

  for (let i = 0; i < 18; i++) {
    let baseAngle = -PI / 2 + random(-0.6, 0.8);
    let baseLen = random(80, 160);
    let baseWeight = random(3, 6);
    branch(originX + random(-30, 30), originY + random(-20, 20), baseAngle, baseLen, baseWeight, 0, i);
  }

  // Draw glow layer for warm segments
  for (let seg of segments) {
    if (seg.a > 80 && seg.w > 1) {
      stroke(seg.r, seg.g, seg.b * 0.5, seg.a * 0.08);
      strokeWeight(seg.w * 6);
      line(seg.x1, seg.y1, seg.x2, seg.y2);
    }
  }

  // Draw mid-glow
  for (let seg of segments) {
    if (seg.a > 40) {
      stroke(seg.r, seg.g, seg.b, seg.a * 0.2);
      strokeWeight(seg.w * 3);
      line(seg.x1, seg.y1, seg.x2, seg.y2);
    }
  }

  // Draw main segments
  for (let seg of segments) {
    stroke(seg.r, seg.g, seg.b, seg.a);
    strokeWeight(seg.w);
    line(seg.x1, seg.y1, seg.x2, seg.y2);
  }

  // Draw particles
  noStroke();
  for (let p of particles) {
    // Glow
    fill(p.r, p.g, p.b, p.a * 0.15);
    ellipse(p.x, p.y, p.size * 5);
    // Core
    fill(p.r, p.g, p.b, p.a);
    ellipse(p.x, p.y, p.size);
  }

  // Ambient floating particles in the void (top-right area)
  for (let i = 0; i < 4000; i++) {
    let x = random(width * 0.25, width * 0.98);
    let y = random(height * 0.02, height * 0.65);
    let n = noise(x * 0.004, y * 0.004, 0.5);
    let originX2 = width * 0.12;
    let originY2 = height * 0.92;
    let d = dist(x, y, originX2, originY2);
    let fade = constrain(map(d, 300, 1600, 0.5, 0), 0, 1);

    if (n > 0.52 && fade > 0) {
      let alpha = map(n, 0.52, 0.85, 0, 40) * fade;
      let sizeVal = random(0.4, 1.8);
      let br = lerp(180, 100, noise(x * 0.01, y * 0.01));
      let bg = lerp(150, 80, noise(x * 0.01 + 50, y * 0.01));
      let bb = lerp(200, 220, noise(x * 0.01 + 100, y * 0.01));
      fill(br, bg, bb, alpha);
      ellipse(x, y, sizeVal);
    }
  }

  // A few bright "last sparks" — isolated bright dots far from origin
  for (let i = 0; i < 30; i++) {
    let x = random(width * 0.5, width * 0.95);
    let y = random(height * 0.05, height * 0.5);
    let brightness = random(80, 180);
    let sparkSize = random(1, 2.5);
    // Glow
    fill(brightness * 0.6, brightness * 0.5, brightness, 8);
    noStroke();
    ellipse(x, y, sparkSize * 10);
    fill(brightness * 0.7, brightness * 0.6, brightness, 15);
    ellipse(x, y, sparkSize * 4);
    fill(brightness, brightness * 0.85, brightness * 0.9, 40);
    ellipse(x, y, sparkSize);
  }
}

function setup() {
