    let n = noise(x * 0.002, y * 0.002);
    let alpha = n * 15;
    fill(30 + n * 20, 10 + n * 15, 40 + n * 30, alpha);
    ellipse(x, y, random(20, 80));
  }

  // Central warm glow behind the meeting point
  for (let r = 500; r > 0; r -= 5) {
    let alpha = map(r, 0, 500, 25, 0);
    fill(60, 20, 50, alpha);
    ellipse(800, 750, r * 2, r * 2.5);
  }

  // Draw the two intertwining forms
  drawFlowingForm(1, true);  // Left form - cool
  drawFlowingForm(2, false); // Right form - warm

  // Draw intertwining overlay strokes
  drawIntertwine();

  // Luminous particles at convergence
  drawParticles();

  // Final top glow at meeting point
  for (let r = 200; r > 0; r -= 3) {
    let alpha = map(r, 0, 200, 12, 0);
    fill(255, 200, 150, alpha);
    ellipse(800, 720, r * 1.5, r * 1.8);
  }
}

function drawFlowingForm(seed, isCool) {
  let baseX = isCool ? 200 : 1400;
  let baseY = 1900;
  let targetX = 800;
  let targetY = 700;

  // Main body - many layered strokes
  for (let layer = 0; layer < 60; layer++) {
    let offsetX = noise(layer * 0.1 + seed * 100) * 200 - 100;
    let offsetY = noise(layer * 0.1 + seed * 100 + 50) * 100 - 50;

    let startX = baseX + offsetX + random(-60, 60);
    let startY = baseY + random(-50, 50);
    let endX = targetX + offsetX * 0.5 + random(-40, 40);
    let endY = targetY + offsetY + random(-30, 30);

    let cp1x = lerp(startX, endX, 0.3) + noise(layer * 0.3) * 300 - 150;
    let cp1y = lerp(startY, endY, 0.3) + noise(layer * 0.3 + 10) * 200 - 100;
    let cp2x = lerp(startX, endX, 0.7) + noise(layer * 0.3 + 20) * 200 - 100;
    let cp2y = lerp(startY, endY, 0.7) + noise(layer * 0.3 + 30) * 150 - 75;

    let t = layer / 60;
    let r, g, b, a;

    if (isCool) {
      r = lerp(20, 80, t) + noise(layer * 0.5) * 30;
      g = lerp(40, 120, t) + noise(layer * 0.5 + 5) * 40;
      b = lerp(100, 200, t) + noise(layer * 0.5 + 10) * 55;
      a = lerp(40, 15, t) + random(-5, 5);
    } else {
      r = lerp(150, 220, t) + noise(layer * 0.5) * 35;
      g = lerp(30, 80, t) + noise(layer * 0.5 + 5) * 30;
      b = lerp(40, 80, t) + noise(layer * 0.5 + 10) * 30;
      a = lerp(40, 15, t) + random(-5, 5);
    }

    stroke(r, g, b, a);
    strokeWeight(random(2, 12));
    noFill();
    bezier(startX, startY, cp1x, cp1y, cp2x, cp2y, endX, endY);
  }

  // Additional flowing tendrils
  for (let tendril = 0; tendril < 25; tendril++) {
    let points = [];
    let numPoints = 30;
    let tOffset = tendril * 0.7 + seed * 50;

    for (let i = 0; i < numPoints; i++) {
      let t = i / (numPoints - 1);
      let x = lerp(baseX, targetX, t);
      let y = lerp(baseY, targetY, t);

      let nx = noise(t * 2 + tOffset) * 300 - 150;
      let ny = noise(t * 2 + tOffset + 100) * 200 - 100;

      // Spiral motion
      let angle = t * TWO_PI * 2 + tendril * 0.5;
      let radius = (1 - t) * 80 + t * 40;
      nx += cos(angle) * radius;
      ny += sin(angle) * radius * 0.6;

      points.push({ x: x + nx, y: y + ny });
    }

    let r, g, b;
    if (isCool) {
      r = 40 + noise(tendril) * 60;
      g = 80 + noise(tendril + 10) * 100;
      b = 150 + noise(tendril + 20) * 105;
    } else {
      r = 180 + noise(tendril) * 75;
      g = 50 + noise(tendril + 10) * 60;
      b = 50 + noise(tendril + 20) * 50;
    }

    stroke(r, g, b, 20);
    strokeWeight(random(1, 5));
    noFill();
    beginShape();
    for (let p of points) {
      curveVertex(p.x, p.y);
    }
    endShape();
  }
}

function drawIntertwine() {
  // Strokes that weave between both forms at the meeting point
  for (let i = 0; i < 80; i++) {
    let angle = noise(i * 0.2) * TWO_PI * 3;
    let radius = noise(i * 0.15) * 250;
    let cx = 800 + cos(angle) * radius * 0.6;
    let cy = 750 + sin(angle) * radius * 0.8;

    let angle2 = angle + noise(i * 0.2 + 50) * PI;
    let radius2 = radius + noise(i * 0.15 + 50) * 100;
    let cx2 = 800 + cos(angle2) * radius2 * 0.5;
    let cy2 = 750 + sin(angle2) * radius2 * 0.7;

    let t = noise(i * 0.3);
    let r = lerp(100, 255, t);
    let g = lerp(50, 180, t);
    let b = lerp(150, 120, t);

    stroke(r, g, b, 18);
    strokeWeight(random(1, 6));
    noFill();
    let cpx = lerp(cx, cx2, 0.5) + random(-50, 50);
    let cpy = lerp(cy, cy2, 0.5) + random(-50, 50);
    bezier(cx, cy, cpx, cpy - 30, cpx, cpy + 30, cx2, cy2);
  }

  // Soft color blending strokes at center
  for (let i = 0; i < 150; i++) {
    let x = 800 + randomGaussian() * 120;
    let y = 740 + randomGaussian() * 150;
    let t = noise(i * 0.1);
    let r = lerp(80, 255, t);
    let g = lerp(40, 130, t * 0.7);
    let b = lerp(180, 100, t);
    noStroke();
    fill(r, g, b, 6);
    ellipse(x, y, random(10, 60), random(10, 60));
  }
}

function drawParticles() {
  // Luminous dots scattered at convergence
  for (let i = 0; i < 400; i++) {
    let angle = random(TWO_PI);
    let dist = random(0, 350);
    let x = 800 + cos(angle) * dist * 0.7;
    let y = 730 + sin(angle) * dist * 0.9;

    let brightness = map(dist, 0, 350, 255, 100);
    let size = map(dist, 0, 350, random(3, 8), random(1, 3));

    // Glow
    noStroke();
    fill(255, 220, 180, 10);
    ellipse(x, y, size * 6);
    fill(255, 240, 200, 20);
    ellipse(x, y, size * 3);

    // Core
    let t = noise(i * 0.05);
    fill(lerp(255, 200, t), lerp(240, 180, t), lerp(220, 255, t), map(dist, 0, 350, 200, 60));
    ellipse(x, y, size);
  }

  // Scattered distant particles (like stars)
  for (let i = 0; i < 200; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.005, y * 0.005);
    if (n > 0.55) {
      let size = random(1, 3);
      fill(200, 200, 255, random(30, 100));
      noStroke();
      ellipse(x, y, size);
    }
  }
}

function setup() {
