function drawOrganicForm(startX, startY, lean, seedOffset, palette) {
  let branches = [];

  // Main trunk
  let segments = 60;
  let points = [];
  let x = startX;
  let y = startY;
  let angle = -PI / 2 + lean;
  let thickness = 45;

  for (let i = 0; i < segments; i++) {
    let t = i / segments;
    let noiseVal = noise((i + seedOffset) * 0.08) - 0.5;
    angle += noiseVal * 0.12;

    // Curve toward center as we go up
    let centerPull = (startX < width / 2 ? 1 : -1) * t * 0.02;
    angle += centerPull;

    let stepLen = 28 + noise((i + seedOffset) * 0.1) * 12;
    x += cos(angle) * stepLen;
    y += sin(angle) * stepLen;
    thickness = lerp(45, 8, t * t);

    points.push({ x, y, thickness, t });

    // Spawn branches
    if (i > 10 && random() < 0.25) {
      let branchAngle = angle + (random() < 0.5 ? -1 : 1) * random(0.4, 1.2);
      branches.push({
        sx: x, sy: y,
        angle: branchAngle,
        len: random(40, 120) * (1 - t * 0.5),
        thickness: thickness * 0.5,
        t: t,
        seed: random(1000)
      });
    }
  }

  // Paint main trunk with brush strokes
  for (let i = 0; i < points.length - 1; i++) {
    let p = points[i];
    let p2 = points[i + 1];
    paintStroke(p.x, p.y, p2.x, p2.y, p.thickness, p.t, palette);
  }

  // Paint branches
  for (let b of branches) {
    let bx = b.sx;
    let by = b.sy;
    let bAngle = b.angle;
    let bSegs = 12;
    for (let i = 0; i < bSegs; i++) {
      let bt = i / bSegs;
      let nv = noise((i + b.seed) * 0.15) - 0.5;
      bAngle += nv * 0.15;
      let step = b.len / bSegs;
      let nx = bx + cos(bAngle) * step;
      let ny = by + sin(bAngle) * step;
      let bt2 = b.t + bt * (1 - b.t);
      let bThick = b.thickness * (1 - bt);
      paintStroke(bx, by, nx, ny, bThick, bt2, palette);
      bx = nx;
      by = ny;
    }
  }
}

function paintStroke(x1, y1, x2, y2, thickness, t, palette) {
  let steps = max(3, floor(dist(x1, y1, x2, y2) / 2));

  for (let i = 0; i < steps; i++) {
    let st = i / steps;
    let px = lerp(x1, x2, st) + random(-thickness * 0.3, thickness * 0.3);
    let py = lerp(y1, y2, st) + random(-thickness * 0.3, thickness * 0.3);
    let size = random(thickness * 0.4, thickness * 1.2);
    let col = getColor(palette, t, random());

    noStroke();
    fill(col[0], col[1], col[2], random(40, 90));
    ellipse(px, py, size, size * random(0.6, 1.4));
  }
}

function getColor(palette, t, variation) {
  if (palette === 'cool') {
    let r = lerp(20, 80, t) + variation * 30;
    let g = lerp(80, 160, t) + variation * 40;
    let b = lerp(120, 200, t) + variation * 30;
    return [r, g, b];
  } else {
    let r = lerp(180, 255, t) + variation * 20;
    let g = lerp(60, 140, t) + variation * 40;
    let b = lerp(40, 80, t) + variation * 30;
    return [r, g, b];
  }
}

function drawIntertwine() {
  // Flowing curves that spiral around each other in the upper portion
  let centerX = width / 2;
  let centerY = height * 0.35;

  for (let strand = 0; strand < 8; strand++) {
    let phaseOffset = strand * PI / 4;
    let radiusBase = 30 + strand * 25;
    let isWarm = strand % 2 === 0;

    let px, py;
    for (let i = 0; i < 80; i++) {
      let t = i / 80;
      let y = lerp(height * 0.65, height * 0.1, t);
      let spiralAngle = t * PI * 4 + phaseOffset;
      let radius = radiusBase * (1 + sin(t * PI) * 0.8);
      let x = centerX + cos(spiralAngle) * radius + noise(i * 0.1 + strand) * 40 - 20;

      if (i > 0) {
        let col = isWarm ?
          [200 + random(55), 80 + random(60), 50 + random(40)] :
          [40 + random(40), 120 + random(60), 170 + random(50)];

        noStroke();
        fill(col[0], col[1], col[2], random(30, 70));
        let size = random(4, 12);
        ellipse(x, y, size, size);

        // Connecting strokes
        stroke(col[0], col[1], col[2], random(20, 50));
        strokeWeight(random(1, 3));
        line(px, py, x, y);
      }
      px = x;
      py = y;
    }
  }
}

function drawMeetingLight() {
  let cx = width / 2;
  let cy = height * 0.35;

  // Large soft glow
  for (let i = 0; i < 2000; i++) {
    let angle = random(TWO_PI);
    let r = pow(random(), 0.5) * 300;
    let x = cx + cos(angle) * r;
    let y = cy + sin(angle) * r * 1.3;
    let alpha = map(r, 0, 300, 20, 0);
    let size = random(3, 15);

    noStroke();
    let choice = random();
    if (choice < 0.33) {
      fill(255, 200, 150, alpha);
    } else if (choice < 0.66) {
      fill(255, 150, 180, alpha);
    } else {
      fill(200, 180, 255, alpha);
    }
    ellipse(x, y, size);
  }

  // Bright core particles
  for (let i = 0; i < 500; i++) {
    let angle = random(TWO_PI);
    let r = pow(random(), 2) * 150;
    let x = cx + cos(angle) * r;
    let y = cy + sin(angle) * r * 1.2;
    let alpha = map(r, 0, 150, 150, 10);
    let size = random(2, 8);

    noStroke();
    fill(255, 240, 220, alpha);
    ellipse(x, y, size);
  }

  // Scattered sparks
  for (let i = 0; i < 200; i++) {
    let angle = random(TWO_PI);
    let r = random(50, 500);
    let x = cx + cos(angle) * r;
    let y = cy + sin(angle) * r * 1.4;
    let alpha = random(50, 200) * (1 - r / 500);
    let size = random(1, 4);

    noStroke();
    fill(255, 230, 200, alpha);
    ellipse(x, y, size);
  }
}

function drawFloatingParticles() {
  for (let i = 0; i < 1500; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.003, y * 0.003, i * 0.01);
    if (n > 0.45) {
      let size = random(1, 4);
      let alpha = random(20, 80) * n;
      noStroke();
      fill(200 + random(55), 180 + random(55), 200 + random(55), alpha);
      ellipse(x, y, size);
    }
  }
}

function drawVignette() {
  // Darken edges
  for (let i = 0; i < 40; i++) {
    noFill();
    stroke(8, 5, 22, 15);
    strokeWeight(30);
    let margin = i * 15;
    rect(margin, margin, width - margin * 2, height - margin * 2);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Deep background
  background(12, 8, 20);

  // Background gradient wash
  for (let y = 0; y < height; y++) {
    let inter = y / height;
    let c = lerpColor(color(8, 5, 18), color(20, 10, 35), sin(inter * PI));
    stroke(c);
    line(0, y, width, y);
  }

  // Subtle background texture
  noStroke();
  for (let i = 0; i < 3000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.003, y * 0.003);
    let alpha = n * 15;
    fill(60, 40, 80, alpha);
    ellipse(x, y, random(2, 8));
  }

  // Distant stars/particles
  for (let i = 0; i < 200; i++) {
    let x = random(width);
    let y = random(height);
    let s = random(1, 3);
    let a = random(30, 100);
    fill(200, 180, 220, a);
    noStroke();
    ellipse(x, y, s);
  }

  // Draw the two intertwining forms
  drawFlowingForms();

  // Draw glow at convergence points
  drawConvergenceGlow();

  // Draw floating light particles
  drawLightParticles();

  // Vignette
  drawVignette();
}

function drawFlowingForms() {
  let numStrands = 12;
  let steps = 300;

  // Form A - rises from bottom-left, warm reds/crimsons
  for (let strand = 0; strand < numStrands; strand++) {
    let offset = strand * 0.7;
    let baseWidth = map(strand, 0, numStrands - 1, 80, 15);
    let baseAlpha = map(strand, 0, numStrands - 1, 25, 60);

    beginShape();
    noFill();

    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let y = height + 100 - t * (height + 400);

      // Base path - flowing upward with sinusoidal movement
      let centerX = width * 0.5;
      let amplitude = 250 + 100 * sin(t * PI);
      let phase = t * TWO_PI * 1.5 + offset;

      let x = centerX + amplitude * sin(phase) + noise(t * 2 + offset, strand * 0.5) * 100 - 50;

      // Width variation
      let w = baseWidth * (1 + 0.5 * sin(t * PI * 3 + offset)) * (0.5 + noise(t * 3 + offset) * 1.0);

      // Color shifts
      let r = map(noise(t * 2 + offset + 10), 0, 1, 160, 230);
      let g = map(noise(t * 2 + offset + 20), 0, 1, 20, 80);
      let b = map(noise(t * 2 + offset + 30), 0, 1, 40, 100);

      stroke(r, g, b, baseAlpha);
      strokeWeight(w);

      // Only plot points, use curveVertex for smoothness
      if (i === 0 || i === steps) {
        curveVertex(x, y);
      }
      curveVertex(x, y);
    }
    endShape();
  }

  // Form B - rises from bottom-right, soft pinks/magentas
  for (let strand = 0; strand < numStrands; strand++) {
    let offset = strand * 0.7 + 3.5;
    let baseWidth = map(strand, 0, numStrands - 1, 80, 15);
    let baseAlpha = map(strand, 0, numStrands - 1, 25, 55);

    beginShape();
    noFill();

    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let y = height + 100 - t * (height + 400);

      let centerX = width * 0.5;
      let amplitude = 250 + 100 * sin(t * PI);
      let phase = t * TWO_PI * 1.5 + offset + PI; // Phase shifted

      let x = centerX + amplitude * sin(phase) + noise(t * 2 + offset + 50, strand * 0.5 + 10) * 100 - 50;

      let w = baseWidth * (1 + 0.5 * sin(t * PI * 3 + offset)) * (0.5 + noise(t * 3 + offset + 50) * 1.0);

      // Pink/magenta tones
      let r = map(noise(t * 2 + offset + 60), 0, 1, 180, 240);
      let g = map(noise(t * 2 + offset + 70), 0, 1, 60, 140);
      let b = map(noise(t * 2 + offset + 80), 0, 1, 120, 190);

      stroke(r, g, b, baseAlpha);
      strokeWeight(w);

      if (i === 0 || i === steps) {
        curveVertex(x, y);
      }
      curveVertex(x, y);
    }
    endShape();
  }

  // Interweaving tendrils - thin connecting strands
  for (let strand = 0; strand < 20; strand++) {
    let offset = random(100);
    beginShape();
    noFill();

    for (let i = 0; i <= 150; i++) {
      let t = i / 150;
      let y = height * 0.1 + t * height * 0.8;

      let n1 = noise(t * 3 + offset, 0);
      let n2 = noise(t * 3 + offset, 100);

      let x = width * 0.2 + n1 * width * 0.6;

      let r = lerp(200, 255, noise(t + offset));
      let g = lerp(100, 180, noise(t + offset + 50));
      let b = lerp(80, 160, noise(t + offset + 100));

      stroke(r, g, b, 20 + noise(t * 5 + offset) * 30);
      strokeWeight(2 + noise(t * 4 + offset) * 5);

      if (i === 0 || i === 150) {
        curveVertex(x, y);
      }
      curveVertex(x, y);
    }
    endShape();
  }
}

function drawConvergenceGlow() {
  // Multiple convergence points where the two forms meet
  let glowPoints = [];

  // Calculate approximate meeting points based on the sinusoidal pattern
  for (let i = 0; i < 5; i++) {
    let t = 0.15 + i * 0.18;
    let y = height + 100 - t * (height + 400);
    let x = width * 0.5 + noise(i * 3.7) * 80 - 40;
    glowPoints.push({ x: x, y: y, size: 200 + random(100) });
  }

  // Draw glows
  for (let gp of glowPoints) {
    // Outer glow
    for (let r = gp.size; r > 0; r -= 3) {
      let alpha = map(r, 0, gp.size, 40, 0);
      let inter = r / gp.size;

      let cr = lerp(255, 255, inter);
      let cg = lerp(200, 140, inter);
      let cb = lerp(100, 60, inter);

      noStroke();
      fill(cr, cg, cb, alpha);
      ellipse(gp.x, gp.y, r * 2, r * 2);
    }

    // Inner bright core
    for (let r = 40; r > 0; r -= 2) {
      let alpha = map(r, 0, 40, 80, 0);
      noStroke();
      fill(255, 240, 200, alpha);
      ellipse(gp.x, gp.y, r * 2, r * 2);
    }
  }

  // Large central glow where forms most intertwine
  let cx = width * 0.5;
  let cy = height * 0.45;

  for (let r = 400; r > 0; r -= 5) {
    let alpha = map(r, 0, 400, 15, 0);
    let inter = r / 400;
    let cr = lerp(255, 180, inter);
    let cg = lerp(220, 80, inter);
    let cb = lerp(150, 60, inter);
    noStroke();
    fill(cr, cg, cb, alpha);
    ellipse(cx, cy, r * 2, r * 2.5);
  }
}

function drawLightParticles() {
  // Luminous particles floating around the convergence areas
  for (let i = 0; i < 500; i++) {
    let x = width * 0.2 + random(width * 0.6);
    let y = height * 0.1 + random(height * 0.8);

    // More particles near center
    let distFromCenter = dist(x, y, width * 0.5, height * 0.45);
    if (random(distFromCenter) > 300 && random() > 0.3) continue;

    let size = random(2, 10);
    let alpha = random(40, 180);

    // Warm golden/white particles
    let r = random(220, 255);
    let g = random(160, 240);
    let b = random(80, 180);

    noStroke();
    fill(r, g, b, alpha * 0.3);
    ellipse(x, y, size * 3);
    fill(r, g, b, alpha);
    ellipse(x, y, size);
    fill(255, 255, 240, alpha * 0.8);
    ellipse(x, y, size * 0.4);
  }

  // Tiny sparkle dots
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.01, y * 0.01);
    if (n > 0.55) {
      let size = random(1, 4);
      let alpha = random(50, 200);
      noStroke();
      fill(255, 230, 200, alpha);
      ellipse(x, y, size);
    }
  }
}

function drawVignette() {
  // Soft vignette effect
  noStroke();
  let maxDist = dist(0, 0, width * 0.5, height * 0.5);

  for (let i = 0; i < 50; i++) {
    let t = i / 50;
    let margin = t * 300;
    let alpha = t * t * 180;
    fill(5, 3, 12, alpha);

    // Top
    rect(0, 0, width, margin);
    // Bottom
    rect(0, height - margin, width, margin);
    // Left
    rect(0, 0, margin, height);
    // Right
    rect(width - margin, 0, margin, height);
  }

  // Corner darkening
  for (let corner of [[0, 0], [width, 0], [0, height], [width, height]]) {
    for (let r = 500; r > 0; r -= 10) {
      let alpha = map(r, 0, 500, 0, 60);
      fill(5, 3, 12, alpha);
      noStroke();
      ellipse(corner[0], corner[1], r * 2);
    }
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function draw() {
  background(15, 10, 25);

  // Deep textured background with noise
  loadPixels();
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let n = noise(x * 0.003, y * 0.003);
      let n2 = noise(x * 0.01, y * 0.01);
      let cx = width / 2;
      let cy = height * 0.45;
      let d = dist(x, y, cx, cy) / 900;
      d = constrain(d, 0, 1.5);

      let idx = (y * width + x) * 4;
      let r = pixels[idx];
      let g = pixels[idx + 1];
      let b = pixels[idx + 2];

      // Base gradient: dark edges, warm center
      let warmth = (1 - d) * 0.5;
      r += warmth * 40 + n * 20;
      g += warmth * 15 + n * 8;
      b += warmth * 30 + n * 25 + n2 * 10;

      // Add painterly noise texture
      let tex = (n2 - 0.5) * 15;
      r += tex;
      g += tex * 0.7;
      b += tex;

      pixels[idx] = constrain(r, 0, 255);
      pixels[idx + 1] = constrain(g, 0, 255);
      pixels[idx + 2] = constrain(b, 0, 255);
    }
  }
  updatePixels();

  // Soft atmospheric glow layers
  noStroke();
  for (let i = 0; i < 20; i++) {
    let gx = width / 2 + random(-200, 200);
    let gy = height * 0.45 + random(-300, 200);
    let gs = random(300, 800);
    let alpha = random(5, 15);
    fill(120 + random(30), 30 + random(20), 60 + random(40), alpha);
    ellipse(gx, gy, gs, gs * random(0.8, 1.2));
  }

  // Central warm glow
  for (let i = 0; i < 30; i++) {
    let gx = width / 2 + random(-100, 100);
    let gy = height * 0.45 + random(-100, 100);
    let gs = random(200, 600);
    fill(180 + random(40), 60 + random(40), 40 + random(30), random(3, 10));
    ellipse(gx, gy, gs, gs * random(0.9, 1.1));
  }

  // Define two flowing forms - left and right
  // Left form: curves from upper-left, flowing down and toward center
  // Right form: curves from upper-right, flowing down and toward center

  drawFlowingForm(width * 0.35, height * 0.25, -1, color(180, 50, 70), color(220, 120, 80));
  drawFlowingForm(width * 0.65, height * 0.25, 1, color(70, 50, 150), color(150, 80, 180));

  // Meeting point - intense warm light
  let meetX = width / 2;
  let meetY = height * 0.45;
  for (let i = 0; i < 40; i++) {
    let gx = meetX + random(-80, 80);
    let gy = meetY + random(-120, 120);
    let gs = random(50, 250);
    let alpha = random(8, 25);
    fill(255, 200 + random(55), 100 + random(80), alpha);
    ellipse(gx, gy, gs, gs * random(0.7, 1.3));
  }

  // Bright core at meeting point
  for (let i = 0; i < 15; i++) {
    let gx = meetX + random(-30, 30);
    let gy = meetY + random(-50, 50);
    let gs = random(20, 100);
    fill(255, 240, 200, random(20, 50));
    ellipse(gx, gy, gs, gs);
  }

  // Flowing connection lines between the forms
  strokeWeight(1);
  for (let i = 0; i < 200; i++) {
    let t = random(1);
    let x1 = lerp(width * 0.35, meetX, t) + random(-60, 60);
    let y1 = lerp(height * 0.3, meetY, t) + random(-80, 80);
    let x2 = lerp(width * 0.65, meetX, t) + random(-60, 60);
    let y2 = lerp(height * 0.3, meetY, t) + random(-80, 80);

    let alpha = map(t, 0, 1, 5, 30);
    let r = lerp(180, 255, t);
    let g = lerp(50, 200, t);
    let b = lerp(70, 100, t);
    stroke(r, g, b, alpha);
    noFill();
    let cpx = (x1 + x2) / 2 + random(-100, 100);
    let cpy = (y1 + y2) / 2 + random(-100, 100);
    bezier(x1, y1, cpx, cpy, cpx, cpy, x2, y2);
  }

  // Painterly brush strokes forming the silhouettes
  drawPaintStrokes(width * 0.33, height * 0.2, -1);
  drawPaintStrokes(width * 0.67, height * 0.2, 1);

  // Downward flowing forms - the bodies extending down
  drawBodyFlow(width * 0.38, height * 0.5, -1, color(160, 40, 60), color(200, 80, 60));
  drawBodyFlow(width * 0.62, height * 0.5, 1, color(60, 40, 130), color(120, 60, 160));

  // Floating particles / bokeh throughout
  noStroke();
  for (let i = 0; i < 400; i++) {
    let px = random(width);
    let py = random(height);
    let ps = random(2, 12);
    let d = dist(px, py, width / 2, height * 0.45);
    let brightness = map(d, 0, 800, 200, 80);
    brightness = constrain(brightness, 60, 200);
    let alpha = random(20, 80);

    if (random() < 0.3) {
      // Warm particles near center
      fill(255, brightness + 50, brightness - 20, alpha);
    } else {
      // Cool particles elsewhere
      fill(brightness, brightness * 0.7, brightness + 40, alpha * 0.5);
    }
    ellipse(px, py, ps, ps);
  }

  // Larger bokeh circles
  for (let i = 0; i < 30; i++) {
    let px = random(width);
    let py = random(height);
    let ps = random(20, 60);
    let d = dist(px, py, width / 2, height * 0.45);
    let alpha = map(d, 0, 900, 20, 5);
    alpha = constrain(alpha, 3, 20);

    noFill();
    strokeWeight(random(1, 3));
    stroke(255, 200 + random(55), 150 + random(50), alpha);
    ellipse(px, py, ps, ps);
  }

  // Final atmospheric overlay - vignette
  for (let i = 0; i < 50; i++) {
    let angle = random(TWO_PI);
    let radius = random(600, 1100);
    let vx = width / 2 + cos(angle) * radius;
    let vy = height * 0.45 + sin(angle) * radius;
    let vs = random(300, 700);
    fill(10, 5, 20, random(20, 50));
    noStroke();
    ellipse(vx, vy, vs, vs * random(0.8, 1.2));
  }

  // Sparkle highlights at the meeting point
  for (let i = 0; i < 50; i++) {
    let sx = meetX + random(-150, 150);
    let sy = meetY + random(-200, 200);
    let ss = random(1, 4);
    fill(255, 255, 240, random(100, 255));
    noStroke();
    ellipse(sx, sy, ss, ss);

    // Tiny cross sparkle
    if (random() < 0.3) {
      stroke(255, 255, 240, random(50, 150));
      strokeWeight(0.5);
      let sl = random(3, 10);
      line(sx - sl, sy, sx + sl, sy);
      line(sx, sy - sl, sx, sy + sl);
    }
  }
}

function drawFlowingForm(cx, cy, side, col1, col2) {
  // Draw organic flowing shape using many layered curves
  for (let i = 0; i < 500; i++) {
    let angle = random(-PI * 0.6, PI * 0.6);
    let radius = random(50, 300);
    let x = cx + cos(angle) * radius * side * 0.5 + side * random(-50, 50);
    let y = cy + sin(angle) * radius + random(-100, 100);

    // Bias toward center
    x = lerp(x, width / 2, random(0, 0.4));
    y = lerp(y, height * 0.45, random(0, 0.3));

    let t = map(y, height * 0.1, height * 0.7, 0, 1);
    let c = lerpColor(col1, col2, t + random(-0.2, 0.2));
    let alpha = random(10, 40);

    noStroke();
    fill(red(c), green(c), blue(c), alpha);
    let s = random(10, 50);
    ellipse(x, y, s, s * random(0.6, 1.4));
  }

  // Head area - more concentrated
  for (let i = 0; i < 100; i++) {
    let x = cx + random(-40, 40) * side;
    let y = cy + random(-50, 30);
    let c = lerpColor(col1, col2, random(0.3, 0.7));
    fill(red(c), green(c), blue(c), random(15, 45));
    noStroke();
    let s = random(8, 30);
    ellipse(x, y, s, s * random(0.8, 1.2));
  }
}

function drawPaintStrokes(cx, cy, side) {
  // Simulate brush strokes with short lines
  for (let i = 0; i < 300; i++) {
    let x = cx + random(-120, 120) * side;
    let y = cy + random(-80, 300);
    let angle = random(-PI / 2, PI / 2) + side * 0.3;
    let len = random(10, 40);
    let x2 = x + cos(angle) * len;
    let y2 = y + sin(angle) * len;

    let d = dist(x, y, width / 2, height * 0.45);
    let warmth = map(d, 0, 400, 1, 0);
    warmth = constrain(warmth, 0, 1);

    let r = lerp(80, 200, warmth) + random(-20, 20);
    let g = lerp(40, 80, warmth) + random(-10, 10);
    let b = lerp(100, 60, warmth) + random(-10, 10);

    stroke(r, g, b, random(15, 50));
    strokeWeight(random(1, 4));
    line(x, y, x2, y2);
  }
}

function drawBodyFlow(cx, cy, side, col1, col2) {
  // Flowing downward extension of the forms
  for (let i = 0; i < 400; i++) {
    let t = random(1);
    let baseX = cx + side * t * 80;
    let baseY = cy + t * random(300, 700);
    let x = baseX + random(-60, 60);
    let y = baseY + random(-30, 30);

    // Fade out toward bottom
    let alpha = map(t, 0, 1, 35, 5);
    let c = lerpColor(col1, col2, t + random(-0.2, 0.2));

    noStroke();
    fill(red(c), green(c), blue(c), alpha);
    let s = random(15, 50) * (1 - t * 0.5);
    ellipse(x, y, s, s * random(1, 2));
  }

  // Merging tendrils toward the other form
  for (let i = 0; i < 100; i++) {
    let t = random(1);
    let x = lerp(cx, width / 2, t * 0.7) + random(-30, 30);
    let y = cy + random(0, 400) + random(-20, 20);
    let alpha = random(5, 25) * (1 - t);

    let c = lerpColor(col1, col2, 0.5 + random(-0.2, 0.2));
    fill(red(c), green(c), blue(c), alpha);
    noStroke();
    let s = random(5, 25);
    ellipse(x, y, s, s * random(0.8, 1.5));
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  pixelDensity(1);
}

function draw() {
  // Deep background
  background(12, 8, 28);

  // Background texture - subtle noise
  for (let i = 0; i < 40000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.003, y * 0.003);
    let r = lerp(8, 30, n);
    let g = lerp(5, 20, n);
    let b = lerp(25, 55, n);
    fill(r, g, b, random(30, 80));
    noStroke();
    let s = random(2, 8);
    ellipse(x, y, s, s * random(0.5, 1.5));
  }

  // Distant stars/particles in background
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = random(height);
    let brightness = random(80, 200);
    fill(brightness * 0.8, brightness * 0.85, brightness, random(100, 200));
    ellipse(x, y, random(1, 4));
  }

  // Central glow behind figures
  for (let r = 500; r > 0; r -= 2) {
    let alpha = map(r, 0, 500, 40, 0);
    fill(60, 30, 50, alpha);
    ellipse(800, 1050, r * 2, r * 2.5);
  }

  // Warm central glow
  for (let r = 300; r > 0; r -= 2) {
    let alpha = map(r, 0, 300, 30, 0);
    fill(180, 100, 50, alpha);
    ellipse(800, 1000, r * 1.8, r * 2.2);
  }

  // Define figure centers
  let fig1x = 620, fig1y = 950;
  let fig2x = 980, fig2y = 950;

  // Draw figure 1 (left, warmer - amber/gold)
  drawFigure(fig1x, fig1y, 1);

  // Draw figure 2 (right, cooler - silver/blue)
  drawFigure(fig2x, fig2y, -1);

  // Draw the merge/overlap glow
  drawMergeGlow(fig1x, fig2x, (fig1y + fig2y) / 2);

  // Floating particles around figures
  drawFloatingParticles();

  // Top and bottom vignette
  drawVignette();
}

function drawFigure(cx, cy, side) {
  // Figure is an organic tall shape
  let particles = 12000;

  for (let i = 0; i < particles; i++) {
    // Organic shape: tall ellipse with noise distortion
    let angle = random(TWO_PI);
    let radV = random(1); // 0 to 1 normalized radius

    // Base shape: taller than wide, like a human silhouette
    let baseW = 200;
    let baseH = 480;

    // Noise-based organic distortion
    let nx = noise(cos(angle) * 2 + side * 10, sin(angle) * 2, radV * 3) * 80;
    let ny = noise(cos(angle) * 2 + 5 + side * 10, sin(angle) * 2 + 5, radV * 3) * 60;

    let px = cx + cos(angle) * radV * baseW + nx * radV;
    let py = cy + sin(angle) * radV * baseH + ny * radV;

    // Head area - make top narrower
    let headFactor = map(py, cy - baseH, cy - baseH * 0.6, 0.3, 1);
    headFactor = constrain(headFactor, 0.3, 1);
    if (py < cy - baseH * 0.6) {
      px = lerp(cx, px, headFactor);
    }

    // Lean toward the other figure
    let leanAmount = map(py, cy + baseH, cy - baseH, 0, 80);
    px += leanAmount * (-side);

    // Color based on which figure
    let r, g, b, a;
    if (side === 1) {
      // Warm figure - amber, gold, warm red
      let warmth = noise(px * 0.01, py * 0.01);
      r = lerp(180, 255, warmth);
      g = lerp(80, 160, warmth);
      b = lerp(30, 80, warmth);
      a = lerp(60, 180, 1 - radV);
    } else {
      // Cool figure - silver, pale blue, soft lavender
      let coolness = noise(px * 0.01 + 100, py * 0.01 + 100);
      r = lerp(120, 190, coolness);
      g = lerp(140, 200, coolness);
      b = lerp(200, 255, coolness);
      a = lerp(60, 180, 1 - radV);
    }

    // Brighter near center
    let centerBright = 1 - radV * 0.5;
    r = min(255, r * centerBright);
    g = min(255, g * centerBright);
    b = min(255, b * centerBright);

    // Near the overlap zone, warm it up
    let distToCenter = abs(px - 800);
    if (distToCenter < 150) {
      let blendFactor = map(distToCenter, 0, 150, 0.7, 0);
      r = lerp(r, 255, blendFactor);
      g = lerp(g, 200, blendFactor);
      b = lerp(b, 100, blendFactor);
      a = lerp(a, 220, blendFactor);
    }

    fill(r, g, b, a);
    noStroke();
    let sz = random(3, 9) * (1 - radV * 0.3);
    ellipse(px, py, sz, sz * random(0.7, 1.4));
  }
}

function drawMergeGlow(x1, x2, y) {
  let mergeX = (x1 + x2) / 2;

  // Intense warm glow where figures meet
  for (let i = 0; i < 3000; i++) {
    let angle = random(TWO_PI);
    let rad = random(1);
    let spread = 120;
    let spreadV = 350;

    let px = mergeX + cos(angle) * rad * spread + random(-20, 20);
    let py = y + sin(angle) * rad * spreadV + random(-30, 30);

    let warmth = noise(px * 0.02, py * 0.02);
    let r = lerp(255, 255, warmth);
    let g = lerp(180, 230, warmth);
    let b = lerp(80, 150, warmth);
    let a = lerp(20, 120, (1 - rad));

    fill(r, g, b, a);
    noStroke();
    let sz = random(2, 7);
    ellipse(px, py, sz, sz * random(0.8, 1.3));
  }

  // Bright core
  for (let r = 80; r > 0; r -= 1) {
    let alpha = map(r, 0, 80, 25, 0);
    fill(255, 230, 180, alpha);
    ellipse(mergeX, y - 50, r * 1.5, r * 3);
  }
}

function drawFloatingParticles() {
  for (let i = 0; i < 500; i++) {
    let x = random(200, 1400);
    let y = random(300, 1700);

    let distFromCenter = dist(x, y, 800, 1000);
    let influence = map(distFromCenter, 0, 600, 1, 0);
    influence = constrain(influence, 0, 1);

    let r = lerp(200, 255, noise(x * 0.01, y * 0.01));
    let g = lerp(150, 220, noise(x * 0.01 + 50, y * 0.01 + 50));
    let b = lerp(100, 200, noise(x * 0.01 + 100, y * 0.01 + 100));
    let a = random(50, 180) * (0.3 + influence * 0.7);

    fill(r, g, b, a);
    noStroke();
    let sz = random(1, 5);
    ellipse(x, y, sz);
  }
}

function drawVignette() {
  // Top fade
  for (let y = 0; y < 400; y++) {
    let alpha = map(y, 0, 400, 200, 0);
    fill(12, 8, 28, alpha);
    noStroke();
    rect(0, y, width, 1);
  }

  // Bottom fade
  for (let y = 1600; y < 2000; y++) {
    let alpha = map(y, 1600, 2000, 0, 220);
    fill(12, 8, 28, alpha);
    noStroke();
    rect(0, y, width, 1);
  }

  // Side vignettes
  for (let x = 0; x < 200; x++) {
    let alpha = map(x, 0, 200, 150, 0);
    fill(12, 8, 28, alpha);
    noStroke();
    rect(x, 0, 1, height);
  }
  for (let x = 1400; x < 1600; x++) {
    let alpha = map(x, 1400, 1600, 0, 150);
    fill(12, 8, 28, alpha);
    noStroke();
    rect(x, 0, 1, height);
  }
}

