function getPathPoint(points, t) {
  t = constrain(t, 0, 1);
  let n = points.length - 1;
  let seg = t * n;
  let i = floor(seg);
  i = constrain(i, 0, n - 1);
  let lt = seg - i;
  let p0 = points[max(0, i - 1)];
  let p1 = points[i];
  let p2 = points[min(n, i + 1)];
  let p3 = points[min(n, i + 2)];
  let t2 = lt * lt;
  let t3 = t2 * lt;
  let x = 0.5 * ((2 * p1.x) + (-p0.x + p2.x) * lt +
    (2 * p0.x - 5 * p1.x + 4 * p2.x - p3.x) * t2 +
    (-p0.x + 3 * p1.x - 3 * p2.x + p3.x) * t3);
  let y = 0.5 * ((2 * p1.y) + (-p0.y + p2.y) * lt +
    (2 * p0.y - 5 * p1.y + 4 * p2.y - p3.y) * t2 +
    (-p0.y + 3 * p1.y - 3 * p2.y + p3.y) * t3);
  return { x, y };
}

function drawForm(points, colors, spread, count) {
  // Large faint layer
  for (let i = 0; i < count; i++) {
    let t = random(0, 1);
    let p = getPathPoint(points, t);
    let p2 = getPathPoint(points, constrain(t + 0.01, 0, 1));
    let angle = atan2(p2.y - p.y, p2.x - p.x);
    let off = random(spread) * random(0.3, 1);
    let a = angle + random(-1.2, 1.2);
    let x = p.x + cos(a) * off;
    let y = p.y + sin(a) * off;
    let s = random(80, 260);
    let c = colors[floor(random(colors.length))];
    fill(c[0], c[1], c[2], random(3, 7));
    noStroke();
    push();
    translate(x, y);
    rotate(angle + random(-0.4, 0.4));
    ellipse(0, 0, s * random(1.2, 2.0), s * random(0.5, 0.8));
    pop();
  }

  // Medium layer
  for (let i = 0; i < count * 0.6; i++) {
    let t = random(0, 1);
    let p = getPathPoint(points, t);
    let p2 = getPathPoint(points, constrain(t + 0.01, 0, 1));
    let angle = atan2(p2.y - p.y, p2.x - p.x);
    let off = random(spread * 0.55) * random(0.3, 1);
    let a = angle + random(-1.0, 1.0);
    let x = p.x + cos(a) * off;
    let y = p.y + sin(a) * off;
    let s = random(40, 130);
    let c = colors[floor(random(colors.length))];
    fill(c[0], c[1], c[2], random(8, 16));
    push();
    translate(x, y);
    rotate(angle + random(-0.3, 0.3));
    ellipse(0, 0, s * random(1.3, 2.0), s * random(0.5, 0.8));
    pop();
  }

  // Fine saturated layer
  for (let i = 0; i < count * 0.3; i++) {
    let t = random(0, 1);
    let p = getPathPoint(points, t);
    let p2 = getPathPoint(points, constrain(t + 0.01, 0, 1));
    let angle = atan2(p2.y - p.y, p2.x - p.x);
    let off = random(spread * 0.3) * random(0.3, 1);
    let a = angle + random(-0.8, 0.8);
    let x = p.x + cos(a) * off;
    let y = p.y + sin(a) * off;
    let s = random(15, 55);
    let c = colors[floor(random(colors.length))];
    fill(min(255, c[0] + 30), min(255, c[1] + 25), min(255, c[2] + 20), random(12, 28));
    push();
    translate(x, y);
    rotate(angle + random(-0.2, 0.2));
    ellipse(0, 0, s * random(1.4, 2.2), s * random(0.5, 0.8));
    pop();
  }
}

function drawSpine(points, col, numLines) {
  noFill();
  for (let n = 0; n < numLines; n++) {
    let alpha = random(8, 20);
    let w = random(0.5, 2.0);
    stroke(col[0], col[1], col[2], alpha);
    strokeWeight(w);
    beginShape();
    for (let t = 0; t <= 1; t += 0.02) {
      let p = getPathPoint(points, t);
      let nx = p.x + (noise(t * 5, n * 10) - 0.5) * 60;
      let ny = p.y + (noise(t * 5 + 100, n * 10) - 0.5) * 60;
      curveVertex(nx, ny);
    }
    endShape();
  }
  noStroke();
}

function drawCore(cx, cy) {
  noStroke();
  // Large soft golden glow
  for (let i = 0; i < 250; i++) {
    let a = random(TWO_PI);
    let d = random(250) * random(0.4, 1);
    let x = cx + cos(a) * d;
    let y = cy + sin(a) * d;
    let s = random(60, 220);
    fill(180, 140, 60, random(2, 5));
    ellipse(x, y, s, s);
  }

  // Medium brighter
  for (let i = 0; i < 180; i++) {
    let a = random(TWO_PI);
    let d = random(140) * random(0.4, 1);
    let x = cx + cos(a) * d;
    let y = cy + sin(a) * d;
    let s = random(25, 90);
    fill(230, 190, 100, random(5, 12));
    ellipse(x, y, s, s);
  }

  // Bright inner
  for (let i = 0; i < 100; i++) {
    let a = random(TWO_PI);
    let d = random(60) * random(0.4, 1);
    let x = cx + cos(a) * d;
    let y = cy + sin(a) * d;
    let s = random(10, 45);
    fill(250, 230, 170, random(10, 22));
    ellipse(x, y, s, s);
  }

  // Hot center
  for (let i = 0; i < 40; i++) {
    let x = cx + random(-25, 25);
    let y = cy + random(-25, 25);
    let s = random(5, 22);
    fill(255, 248, 230, random(15, 35));
    ellipse(x, y, s, s);
  }

  // Radiating light streaks from core
  for (let i = 0; i < 40; i++) {
    let a = random(TWO_PI);
    let len = random(80, 300);
    let sx = cx + cos(a) * 20;
    let sy = cy + sin(a) * 20;
    let ex = cx + cos(a) * len;
    let ey = cy + sin(a) * len;
    stroke(255, 220, 150, random(3, 8));
    strokeWeight(random(0.3, 1.2));
    line(sx, sy, ex, ey);
  }
  noStroke();
}

function drawThreads() {
  noFill();
  // Threads between forms
  for (let i = 0; i < 60; i++) {
    let sx = random(250, 750);
    let sy = random(400, 950);
    let ex = random(850, 1350);
    let ey = random(1050, 1600);
    let c1x = lerp(sx, ex, 0.33) + random(-250, 250);
    let c1y = lerp(sy, ey, 0.33) + random(-250, 250);
    let c2x = lerp(sx, ex, 0.66) + random(-250, 250);
    let c2y = lerp(sy, ey, 0.66) + random(-250, 250);
    let r = lerp(180, 60, random());
    let g = lerp(80, 150, random());
    let b = lerp(95, 190, random());
    stroke(r, g, b, random(6, 16));
    strokeWeight(random(0.3, 1.0));
    bezier(sx, sy, c1x, c1y, c2x, c2y, ex, ey);
  }

  // Outward-reaching threads
  for (let i = 0; i < 40; i++) {
    let a = random(TWO_PI);
    let sx = 800 + cos(a) * random(50, 150);
    let sy = 1000 + sin(a) * random(50, 150);
    let len = random(200, 600);
    let ex = 800 + cos(a) * len + random(-100, 100);
    let ey = 1000 + sin(a) * len + random(-100, 100);
    let mx = (sx + ex) / 2 + random(-150, 150);
    let my = (sy + ey) / 2 + random(-150, 150);
    stroke(200, 180, 140, random(4, 10));
    strokeWeight(random(0.2, 0.7));
    noFill();
    beginShape();
    curveVertex(sx, sy);
    curveVertex(sx, sy);
    curveVertex(mx, my);
    curveVertex(ex, ey);
    curveVertex(ex, ey);
    endShape();
  }
  noStroke();
}

function drawFlowLine(sx, sy, steps, r, g, b, alpha, weight) {
  stroke(r, g, b, alpha);
  strokeWeight(weight);
  noFill();
  beginShape();
  let x = sx, y = sy;
  for (let i = 0; i < steps; i++) {
    let n = noise(x * 0.002, y * 0.002);
    let angle = n * TWO_PI * 2.5;
    x += cos(angle) * 6;
    y += sin(angle) * 6;
    curveVertex(x, y);
  }
  endShape();
  noStroke();
}

function drawParticles() {
  noStroke();
  // Warm particles
  for (let i = 0; i < 250; i++) {
    let x = random(100, 1100);
    let y = random(100, 1300);
    let s = random(1, 4.5);
