function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function draw() {
  background(10, 8, 22);

  noStroke();
  for (let i = 0; i < 5000; i++) {
    let x = random(width);
    let y = random(height);
    fill(random(5, 22), random(5, 18), random(15, 38), random(2, 7));
    ellipse(x, y, random(3, 18), random(3, 18));
  }

  drawNebula(500, 700, 1);
  drawNebula(1100, 1300, 2);
  drawRibbons();
  drawGlow(800, 1000);
  drawBreath();
}

function drawNebula(cx, cy, type) {
  let numMarks = 30000;
  let toCenterAngle = atan2(1000 - cy, 800 - cx);

  for (let i = 0; i < numMarks; i++) {
    let angle = random(TWO_PI);

    let angleDiff = angle - toCenterAngle;
    while (angleDiff > PI) angleDiff -= TWO_PI;
    while (angleDiff < -PI) angleDiff += TWO_PI;
    let elongation = 1 + 0.9 * pow(max(0, cos(angleDiff)), 2.5);

    let n = noise(cos(angle) * 1.8 + type * 7.7, sin(angle) * 1.8 + type * 3.3);
    let baseR = 320 * elongation * (0.3 + n * 0.9);

    let r = pow(random(), 0.6) * baseR;
    if (random() < 0.15) r = random() * baseR * 1.4;

    let x = cx + cos(angle) * r;
    let y = cy + sin(angle) * r * 0.85;

    if (x < -20 || x > width + 20 || y < -20 || y > height + 20) continue;

    let cr, cg, cb, ca;
    let palette = random();

    if (type === 1) {
      if (palette < 0.35) {
        cr = random(130, 190); cg = random(10, 45); cb = random(35, 75);
      } else if (palette < 0.65) {
        cr = random(190, 240); cg = random(50, 100); cb = random(80, 130);
      } else if (palette < 0.88) {
        cr = random(225, 255); cg = random(110, 180); cb = random(45, 90);
      } else {
        cr = random(245, 255); cg = random(190, 240); cb = random(60, 110);
      }
      let d = dist(x, y, 800, 1000);
      let w = constrain(map(d, 0, 500, 0.5, 0), 0, 0.5);
      cr = lerp(cr, 255, w);
      cg = lerp(cg, 210, w);
      cb = lerp(cb, 90, w * 0.5);
    } else {
      if (palette < 0.35) {
        cr = random(20, 65); cg = random(20, 55); cb = random(130, 210);
      } else if (palette < 0.65) {
        cr = random(35, 90); cg = random(90, 170); cb = random(190, 245);
      } else if (palette < 0.88) {
        cr = random(50, 110); cg = random(150, 210); cb = random(195, 240);
      } else {
        cr = random(150, 210); cg = random(110, 170); cb = random(225, 255);
      }
      let d = dist(x, y, 800, 1000);
      let w = constrain(map(d, 0, 500, 0.4, 0), 0, 0.4);
      cr = lerp(cr, 210, w);
      cg = lerp(cg, 225, w);
      cb = lerp(cb, 255, w * 0.5);
    }

    let distFromOwnCenter = dist(x, y, cx, cy) / baseR;
    ca = random(3, 13) * constrain(1.2 - distFromOwnCenter * 0.6, 0.2, 1.2);

    noStroke();
    fill(constrain(cr, 0, 255), constrain(cg, 0, 255), constrain(cb, 0, 255), ca);

    let sz = random(3, 13);
    if (random() < 0.75) {
      ellipse(x, y, sz, sz * random(0.6, 1.5));
    } else {
      stroke(constrain(cr, 0, 255), constrain(cg, 0, 255), constrain(cb, 0, 255), ca * 0.7);
      strokeWeight(random(0.5, 2));
      let a2 = random(TWO_PI);
      let len = random(3, 12);
      line(x - cos(a2) * len, y - sin(a2) * len, x + cos(a2) * len, y + sin(a2) * len);
      noStroke();
    }
  }
}

function drawRibbons() {
  let numRibbons = 25;

  for (let r = 0; r < numRibbons; r++) {
    let numPts = 100;
    let startX = 500 + random(-180, 180);
    let startY = 700 + random(-180, 180);
    let endX = 1100 + random(-180, 180);
    let endY = 1300 + random(-180, 180);
    let noiseOff = random(10000);
    let phaseOff = random(TWO_PI);

    let prevX, prevY;

    for (let i = 0; i < numPts; i++) {
      let t = i / (numPts - 1);
      let baseX = lerp(startX, endX, t);
      let baseY = lerp(startY, endY, t);

      let perpAngle = atan2(endY - startY, endX - startX) + HALF_PI;
      let dev = sin(t * PI * 2 + phaseOff) * 130 * sin(t * PI);
      let nDev = (noise(noiseOff + i * 0.025) - 0.5) * 120 * sin(t * PI);

      let x = baseX + cos(perpAngle) * (dev + nDev);
      let y = baseY + sin(perpAngle) * (dev + nDev);

      if (i > 0) {
        let cr = lerp(230, 70, t) + random(-20, 20);
        let cg = lerp(70, 150, t) + random(-15, 15);
        let cb = lerp(55, 230, t) + random(-20, 20);

        let centerProx = pow(max(0, 1 - abs(t - 0.5) * 2.5), 2);
        cr = lerp(cr, 255, centerProx * 0.7);
        cg = lerp(cg, 230, centerProx * 0.7);
        cb = lerp(cb, 120, centerProx * 0.5);

        let ca = random(4, 12) * (0.4 + centerProx * 0.8);

        stroke(constrain(cr, 0, 255), constrain(cg, 0, 255), constrain(cb, 0, 255), ca);
        strokeWeight(random(0.5, 2.5));
        line(prevX, prevY, x, y);
      }

      prevX = x;
      prevY = y;
    }
  }
}

function drawGlow(cx, cy) {
  noStroke();

  for (let r = 500; r > 0; r -= 5) {
    fill(255, 190, 90, map(r, 0, 500, 4, 0));
    ellipse(cx, cy, r * 1.4, r * 1.7);
  }

  for (let r = 220; r > 0; r -= 3) {
    fill(255, 235, 180, map(r, 0, 220, 7, 0));
    ellipse(cx, cy, r * 1.2, r * 1.5);
  }

  for (let r = 80; r > 0; r -= 2) {
    fill(255, 252, 245, map(r, 0, 80, 14, 0));
    ellipse(cx, cy, r, r * 1.2);
  }

  for (let i = 0; i < 5000; i++) {
    let angle = random(TWO_PI);
    let d = pow(random(), 1.8) * 380;
    let px = cx + cos(angle) * d * random(0.7, 1.3);
    let py = cy + sin(angle) * d * random(0.7, 1.5);

    let dc = dist(px, py, cx, cy);
    let bright = map(dc, 0, 380, 255, 90);
    let alpha = map(dc, 0, 380, 28, 1);

    noStroke();
    fill(255, constrain(180 + random(-30, 60), 120, 255),
      constrain(bright - 40 + random(30), 30, 255), alpha);
    ellipse(px, py, random(0.5, 4), random(0.5, 5));
  }
}

function drawBreath() {
  noStroke();
  for (let i = 0; i < 800; i++) {
    let x = random(width);
    let y = random(height);

    let dc = dist(x, y, 800, 1000);
    if (dc < 250) continue;

    let warm = random() < 0.5;
    let cr, cg, cb;
    if (warm) {
      cr = random(180, 255); cg = random(60, 160); cb = random(40, 100);
    } else {
      cr = random(40, 130); cg = random(80, 180); cb = random(180, 255);
    }

    fill(cr, cg, cb, random(2, 8));
    ellipse(x, y, random(1, 5));
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  pixelDensity(1);
}

function draw() {
  // Deep background
  background(12, 10, 28);

  // Background atmospheric layers
  for (let i = 0; i < 80000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.002, y * 0.002);
    let alpha = n * 15;
    fill(40 + n * 30, 20 + n * 20, 60 + n * 40, alpha);
    noStroke();
    ellipse(x, y, random(2, 6));
  }

  // Warm ambient glow across middle
  for (let r = 600; r > 0; r -= 3) {
    let alpha = map(r, 0, 600, 8, 0);
    fill(80, 30, 20, alpha);
    noStroke();
    ellipse(800, 1000, r * 3, r * 2.5);
  }

  // Form 1 - upper left, warm tones
  drawOrganicForm(620, 780, 380, 'warm');

  // Form 2 - lower right, cool tones
  drawOrganicForm(980, 1220, 360, 'cool');

  // The luminous space between - the heart of the painting
  drawLuminousSpace(780, 980, 850, 1050);

  // Filaments / threads of connection
  drawFilaments(620, 780, 980, 1220);

  // Floating particles in the space between
  drawParticles();

  // Final atmospheric overlay - very subtle
  for (let i = 0; i < 5000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.005 + 100, y * 0.005 + 100);
    if (n > 0.6) {
      fill(200, 180, 140, (n - 0.6) * 20);
      noStroke();
      ellipse(x, y, random(1, 3));
    }
  }

  // Subtle vignette
  for (let i = 0; i < 40; i++) {
    noFill();
    stroke(5, 3, 15, 8);
    strokeWeight(30);
    rect(-i * 15, -i * 15, width + i * 30, height + i * 30, i * 5);
  }
}

function drawOrganicForm(cx, cy, baseRadius, type) {
  let layers = 60;

  for (let l = layers; l > 0; l--) {
    let layerRadius = baseRadius + (layers - l) * 2.5;
    let alpha;
    let r, g, b;

    if (type === 'warm') {
      r = map(l, 0, layers, 180, 60);
      g = map(l, 0, layers, 80, 25);
      b = map(l, 0, layers, 50, 30);
      alpha = map(l, 0, layers, 40, 3);
    } else {
      r = map(l, 0, layers, 40, 20);
      g = map(l, 0, layers, 100, 40);
      b = map(l, 0, layers, 130, 60);
      alpha = map(l, 0, layers, 40, 3);
    }

    fill(r, g, b, alpha);
    noStroke();

    beginShape();
    let points = 120;
    for (let i = 0; i <= points; i++) {
      let angle = map(i, 0, points, 0, TWO_PI);
      let noiseVal = noise(
        cos(angle) * 1.5 + l * 0.05 + cx * 0.01,
        sin(angle) * 1.5 + l * 0.05 + cy * 0.01
      );
      let rad = layerRadius * (0.7 + noiseVal * 0.6);
      let x = cx + cos(angle) * rad;
      let y = cy + sin(angle) * rad;
      vertex(x, y);
    }
    endShape(CLOSE);
  }

  // Inner texture/detail
  for (let i = 0; i < 3000; i++) {
    let angle = random(TWO_PI);
    let dist = random(baseRadius * 0.9);
    let x = cx + cos(angle) * dist;
    let y = cy + sin(angle) * dist;
    let n = noise(x * 0.01, y * 0.01);

    if (n > 0.4) {
      if (type === 'warm') {
        fill(200 + n * 55, 100 + n * 40, 60 + n * 20, n * 20);
      } else {
        fill(50 + n * 30, 120 + n * 50, 160 + n * 40, n * 20);
      }
      noStroke();
      ellipse(x, y, random(1, 4));
    }
  }

  // Soft edge glow
  for (let g2 = 0; g2 < 20; g2++) {
    noFill();
    if (type === 'warm') {
      stroke(200, 100, 60, 3);
    } else {
      stroke(60, 130, 170, 3);
    }
    strokeWeight(2 + g2);
    beginShape();
    let points = 80;
    for (let i = 0; i <= points; i++) {
      let angle = map(i, 0, points, 0, TWO_PI);
      let noiseVal = noise(cos(angle) * 1.5 + cx * 0.01, sin(angle) * 1.5 + cy * 0.01);
      let rad = (baseRadius + g2 * 3) * (0.7 + noiseVal * 0.6);
      let x = cx + cos(angle) * rad;
      let y = cy + sin(angle) * rad;
      vertex(x, y);
    }
    endShape(CLOSE);
  }
}

function drawLuminousSpace(x1, y1, x2, y2) {
  let midX = (x1 + x2) / 2;
  let midY = (y1 + y2) / 2;

  // Core glow - warm gold
  for (let r = 300; r > 0; r -= 2) {
    let t = r / 300;
    let alpha = pow(1 - t, 2) * 12;
    fill(255, 200, 80, alpha);
    noStroke();
    ellipse(midX, midY, r * 1.8, r * 1.4);
  }

  // Secondary warm glow
  for (let r = 200; r > 0; r -= 2) {
    let t = r / 200;
    let alpha = pow(1 - t, 3) * 8;
    fill(255, 160, 100, alpha);
    noStroke();
    ellipse(midX + 20, midY - 10, r * 2, r * 1.6);
  }

  // Bright core
  for (let r = 80; r > 0; r -= 1) {
    let t = r / 80;
    let alpha = pow(1 - t, 2) * 20;
    fill(255, 240, 200, alpha);
    noStroke();
    ellipse(midX, midY, r * 1.5, r * 1.2);
  }

  // Soft light particles emanating
  for (let i = 0; i < 500; i++) {
    let angle = random(TWO_PI);
    let dist = random(200) * pow(random(), 0.5);
    let x = midX + cos(angle) * dist;
    let y = midY + sin(angle) * dist * 0.8;
    let n = noise(x * 0.02, y * 0.02);
    let size = random(1, 4) * n;
    fill(255, 220, 150, n * 40 * (1 - dist / 200));
    noStroke();
    ellipse(x, y, size);
  }
}

function drawFilaments(cx1, cy1, cx2, cy2) {
  let midX = (cx1 + cx2) / 2;
  let midY = (cy1 + cy2) / 2;

  for (let f = 0; f < 40; f++) {
    let startX = cx1 + random(100, 250) * (random() > 0.5 ? 1 : 0.5);
    let startY = cy1 + random(-100, 150);
    let endX = cx2 - random(100, 250) * (random() > 0.5 ? 1 : 0.5);
    let endY = cy2 + random(-150, 100);

    noFill();
    let col = random() > 0.5 ? 
      color(255, 180, 100, random(5, 15)) : 
      color(255, 220, 180, random(3, 10));
    stroke(col);
    strokeWeight(random(0.5, 2));

    beginShape();
    let segments = 40;
    for (let i = 0; i <= segments; i++) {
      let t = i / segments;
      let x = lerp(startX, endX, t);
      let y = lerp(startY, endY, t);
      // Add curve through middle
      let midPull = sin(t * PI) * random(30, 80);
      x += noise(f * 10 + t * 3) * 60 - 30;
      y += midPull + noise(f * 10 + t * 3 + 50) * 40 - 20;
      vertex(x, y);
    }
    endShape();
  }

  // Delicate arcs
  for (let a = 0; a < 15; a++) {
    noFill();
    stroke(255, 200, 140, random(5, 12));
    strokeWeight(random(0.3, 1));

    let arcMidX = midX + random(-80, 80);
    let arcMidY = midY + random(-60, 60);
    let arcWidth = random(100, 300);
    let arcHeight = random(80, 200);

    beginShape();
    for (let i = 0; i <= 30; i++) {
      let t = i / 30;
      let angle = map(t, 0, 1, -PI * 0.3, PI * 0.3);
      let x = arcMidX + cos(angle + random(-0.1, 0.1)) * arcWidth * (0.5 + noise(a, t * 2) * 0.5);
      let y = arcMidY + sin(angle) * arcHeight * noise(a + 5, t * 2);
      vertex(x, y);
    }
    endShape();
  }
}

function drawParticles() {
  let midX = 800;
  let midY = 1000;

  for (let i = 0; i < 800; i++) {
    let x = random(width);
    let y = random(height);
    let distToMid = dist(x, y, midX, midY);
    let proximity = constrain(1 - distToMid / 500, 0, 1);

    if (random() < proximity * 0.8 + 0.05) {
      let n = noise(x * 0.008, y * 0.008);
      let size = random(0.5, 3) * (0.5 + proximity);
      let alpha = random(10, 40) * (0.3 + proximity * 0.7);

      fill(255, 210 + n * 45, 140 + n * 60, alpha);
      noStroke();
      ellipse(x, y, size);
    }
  }

  // A few brighter "stars" near the center
  for (let i = 0; i < 30; i++) {
    let angle = random(TWO_PI);
    let d = random(150) * pow(random(), 2);
    let x = midX + cos(angle) * d;
    let y = midY + sin(angle) * d * 0.8;
    let size = random(1, 4);

    // Glow
    for (let g = 20; g > 0; g--) {
      fill(255, 230, 180, 1);
      noStroke();
      ellipse(x, y, size + g * 2);
    }
    // Core
    fill(255, 250, 230, 150);
    noStroke();
    ellipse(x, y, size);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
  draw();
}

function draw() {
  // Background gradient: deep twilight
  noStroke();
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let c = lerpColor(color(22, 16, 46), color(6, 4, 18), t);
    stroke(c);
    line(0, y, width, y);
  }

  // Distant stars
  noStroke();
  for (let i = 0; i < 500; i++) {
    let x = random(width);
    let y = random(height);
    let s = random(0.4, 2.0);
    fill(255, 240, 220, random(40, 180));
    ellipse(x, y, s, s);
  }

  // Two forms: warm left, cool right
  let lx = width * 0.36;
  let ly = height * 0.5;
  let rx = width * 0.64;
  let ry = height * 0.5;

  blendMode(BLEND);
  drawForm(lx, ly, color(255, 170, 70), color(255, 95, 55), color(255, 225, 170), 460);
  drawForm(rx, ry, color(225, 55, 135), color(255, 145, 180), color(255, 210, 225), 460);

  // Luminous core where they meet (additive blend)
  blendMode(ADD);
  drawCore((lx + rx) / 2, (ly + ry) / 2, 360);
  blendMode(BLEND);

  // Filaments of attention between them
  drawFilaments(lx, ly, rx, ry);

  // Fine particle mist around the meeting
  noStroke();
  for (let i = 0; i < 2500; i++) {
    let a = random(TWO_PI);
    let r = random(20, 360);
    let cx = (lx + rx) / 2 + cos(a) * r * random(0.6, 1.5);
    let cy = (ly + ry) / 2 + sin(a) * r * random(0.7, 1.3);
    let sz = random(0.6, 2.6);
    fill(255, 230, 220, random(15, 90));
    ellipse(cx, cy, sz, sz);
  }

  // Soft vignette
  noFill();
  for (let i = 0; i < 40; i++) {
    stroke(0, 0, 0, 6);
    strokeWeight(60);
    ellipse(width / 2, height / 2, width * 1.55 + i * 35, height * 1.55 + i * 35);
  }
}

function drawForm(cx, cy, c1, c2, c3, radius) {
  noStroke();
  for (let i = 0; i < 2600; i++) {
    let a = random(TWO_PI);
    let r = random(radius);
    let n = noise(0.5 + cos(a) * 0.8, 0.5 + sin(a) * 0.8, i * 0.008);
    r = r * (n * 1.1 + 0.35);
    let x = cx + cos(a) * r;
    let y = cy + sin(a) * r;
    let t = r / radius;
    let inner = lerpColor(c1, c2, random());
    let col = lerpColor(c3, inner, t);
    let al = map(t, 0, 1, 55, 8);
    fill(red(col), green(col), blue(col), al);
    let sz = random(28, 95);
    ellipse(x, y, sz, sz * random(0.85, 1.15));
  }
}

function drawCore(cx, cy, radius) {
  noStroke();
  for (let i = 0; i < 900; i++) {
    let a = random(TWO_PI);
    let r = random(radius) * random(0.15, 1.0);
    let x = cx + cos(a) * r;
    let y = cy + sin(a) * r;
    let al = map(r, 0, radius, 45, 4);
    fill(255, 240, 230, al);
    let sz = random(18, 60);
    ellipse(x, y, sz, sz);
  }
  // bright sparks
  for (let i = 0; i < 120; i++) {
    let a = random(TWO_PI);
    let r = random(10, radius * 0.9);
    let x = cx + cos(a) * r;
    let y = cy + sin(a) * r;
    fill(255, 250, 245, random(60, 180));
    ellipse(x, y, random(1, 3), random(1, 3));
  }
}

function drawFilaments(x1, y1, x2, y2) {
  noFill();
  for (let i = 0; i < 70; i++) {
    let col = lerpColor(color(255, 175, 95), color(255, 140, 180), random());
    stroke(red(col), green(col), blue(col), random(12, 55));
    strokeWeight(random(0.5, 1.7));
    beginShape();
    let steps = 22;
    for (let j = 0; j <= steps; j++) {
      let t = j / steps;
      let baseX = lerp(x1, x2, t);
      let baseY = lerp(y1, y2, t);
      let dx = (noise(i * 0.31, j * 0.22) - 0.5) * 220;
      let dy = (noise(i * 0.31 + 99, j * 0.22) - 0.5) * 320;
      // Taper endpoints toward the masses
      let edge = sin(t * PI);
      curveVertex(baseX + dx * edge, baseY + dy * edge);
    }
    endShape();
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  pixelDensity(1);
}

function draw() {
  // Deep dark background
  background(8, 6, 15);

  // Subtle background atmosphere
  for (let i = 0; i < 8000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.002, y * 0.002);
    let n2 = noise(x * 0.005 + 100, y * 0.005 + 100);
    fill(15 + n * 25, 10 + n2 * 15, 30 + n * 25, random(8, 25));
    noStroke();
    ellipse(x, y, random(2, 8));
  }

  // Background glow - very subtle warm ambient light
  for (let r = 600; r > 0; r -= 3) {
    fill(40, 15, 25, 0.5);
    noStroke();
    ellipse(800, 950, r * 2, r * 2.2);
  }

  // Draw connecting threads/tendrils (behind forms)
  drawThreads();

  // Form 1 - Warm form (lower-left area)
  drawWarmForm();

  // Form 2 - Cool form (upper-right area)
  drawCoolForm();

  // The luminous intersection
  drawIntersection();

  // Floating particles/embers
  drawParticles();

  // Final overlay touches
  drawFinalTouches();
}

function drawThreads() {
  // Delicate connecting threads between the two forms
  for (let i = 0; i < 60; i++) {
    let startX = 450 + random(200);
    let startY = 1000 + random(200);
    let endX = 950 + random(200);
    let endY = 750 + random(200);

    let midX = (startX + endX) / 2 + random(-150, 150);
    let midY = (startY + endY) / 2 + random(-150, 150);

    let t = i / 60;
    let r = lerp(180, 100, t) + random(30);
    let g = lerp(60, 50, t) + random(20);
    let b = lerp(80, 150, t) + random(30);

    stroke(r, g, b, random(15, 40));
    strokeWeight(random(0.5, 2));
    noFill();
    beginShape();
    curveVertex(startX + random(-20, 20), startY + random(-20, 20));
    curveVertex(startX, startY);
    curveVertex(midX, midY);
    curveVertex(endX, endY);
    curveVertex(endX + random(-20, 20), endY + random(-20, 20));
    endShape();
  }

  // More organic flowing threads
  for (let i = 0; i < 30; i++) {
    let points = [];
    let sx = random(400, 600);
    let sy = random(900, 1200);
    let ex = random(900, 1150);
    let ey = random(700, 950);
    let steps = 20;

    for (let j = 0; j <= steps; j++) {
      let t = j / steps;
      let x = lerp(sx, ex, t) + noise(i * 3.7, j * 0.3) * 200 - 100;
      let y = lerp(sy, ey, t) + noise(i * 3.7 + 50, j * 0.3) * 200 - 100;
      points.push({x, y});
    }

    noFill();
    for (let j = 1; j < points.length; j++) {
      let t = j / points.length;
      let alpha = sin(t * PI) * 30;
      stroke(200, 120, 100, alpha);
      strokeWeight(1.5);
      line(points[j-1].x, points[j-1].y, points[j].x, points[j].y);
    }
  }
}

function drawWarmForm() {
  let cx = 520;
  let cy = 1120;

  // Deep base layers
  for (let layer = 0; layer < 5; layer++) {
    for (let i = 0; i < 80; i++) {
      let angle = random(TWO_PI);
      let dist = random(50, 280 + layer * 30);
      let nVal = noise(cos(angle) * 2 + layer, sin(angle) * 2 + layer, i * 0.05);
      let x = cx + cos(angle) * dist * (0.8 + nVal * 0.6);
      let y = cy + sin(angle) * dist * (0.7 + nVal * 0.5) - layer * 20;
      let size = random(40, 120) * (1 - dist / 400);

      let r = 120 + random(60) + layer * 15;
      let g = 20 + random(30) + layer * 8;
      let b = 30 + random(30);
      let a = random(8, 20);

      noStroke();
      fill(r, g, b, a);
      ellipse(x, y, size, size * random(0.8, 1.2));
    }
  }

  // Mid layers - more saturated
  for (let i = 0; i < 200; i++) {
    let angle = random(TWO_PI);
    let maxDist = 250;
    let nVal = noise(cos(angle) * 3 + 10, sin(angle) * 3 + 10);
    let dist = random(20, maxDist) * nVal;
    let x = cx + cos(angle) * dist;
    let y = cy + sin(angle) * dist * 0.85;
    let size = random(20, 80) * (1 - dist / (maxDist * 1.2));

    let r = 160 + random(60);
    let g = 30 + random(40);
    let b = 40 + random(40);
    let a = random(10, 30);

    noStroke();
    fill(r, g, b, a);
    ellipse(x, y, size, size * random(0.7, 1.3));
  }

  // Bright accents
  for (let i = 0; i < 100; i++) {
    let angle = random(TWO_PI);
    let dist = random(20, 180);
    let nVal = noise(cos(angle) * 4 + 20, sin(angle) * 4 + 20);
    if (nVal > 0.4) {
      let x = cx + cos(angle) * dist;
      let y = cy + sin(angle) * dist * 0.85;
      let size = random(10, 40);

      let r = 200 + random(55);
      let g = 60 + random(60);
      let b = 50 + random(40);
      let a = random(15, 35);

      noStroke();
      fill(r, g, b, a);
      ellipse(x, y, size, size * random(0.8, 1.2));
    }
  }

  // Inner glow
  for (let r = 120; r > 0; r -= 4) {
    fill(220, 80, 60, 1.5);
    noStroke();
    ellipse(cx, cy, r * 1.8, r * 1.6);
  }
}

function drawCoolForm() {
  let cx = 1050;
  let cy = 800;

  // Deep base layers
  for (let layer = 0; layer < 5; layer++) {
    for (let i = 0; i < 80; i++) {
      let angle = random(TWO_PI);
      let dist = random(50, 260 + layer * 25);
      let nVal = noise(cos(angle) * 2 + layer + 50, sin(angle) * 2 + layer + 50, i * 0.05);
      let x = cx + cos(angle) * dist * (0.8 + nVal * 0.5);
      let y = cy + sin(angle) * dist * (0.75 + nVal * 0.5) + layer * 15;
      let size = random(40, 110) * (1 - dist / 380);

      let r = 30 + random(30);
      let g = 30 + random(40) + layer * 5;
      let b = 100 + random(60) + layer * 15;
      let a = random(8, 20);

      noStroke();
      fill(r, g, b, a);
      ellipse(x, y, size, size * random(0.8, 1.2));
    }
  }

  // Mid layers
  for (let i = 0; i < 200; i++) {
    let angle = random(TWO_PI);
    let maxDist = 230;
    let nVal = noise(cos(angle) * 3 + 60, sin(angle) * 3 + 60);
    let dist = random(20, maxDist) * nVal;
    let x = cx + cos(angle) * dist;
    let y = cy + sin(angle) * dist * 0.8;
    let size = random(20, 75) * (1 - dist / (maxDist * 1.2));

    let r = 40 + random(40);
    let g = 40 + random(50);
    let b = 130 + random(70);
    let a = random(10, 30);

    noStroke();
    fill(r, g, b, a);
    ellipse(x, y, size, size * random(0.7, 1.3));
  }

  // Violet accents
  for (let i = 0; i < 100; i++) {
    let angle = random(TWO_PI);
    let dist = random(20, 170);
    let nVal = noise(cos(angle) * 4 + 70, sin(angle) * 4 + 70);
    if (nVal > 0.4) {
      let x = cx + cos(angle) * dist;
      let y = cy + sin(angle) * dist * 0.8;
      let size = random(10, 40);

      let r = 80 + random(60);
      let g = 40 + random(50);
      let b = 160 + random(60);
      let a = random(15, 35);

      noStroke();
      fill(r, g, b, a);
      ellipse(x, y, size, size * random(0.8, 1.2));
    }
  }

  // Inner glow
  for (let r = 110; r > 0; r -= 4) {
    fill(50, 50, 180, 1.5);
    noStroke();
    ellipse(cx, cy, r * 1.7, r * 1.5);
  }
}

function drawIntersection() {
  // The sacred space where they meet - golden luminosity
  let icx = 780;
  let icy = 950;

  // Large ambient glow
  for (let r = 400; r > 0; r -= 5) {
    let t = r / 400;
    fill(lerp(255, 180, t), lerp(200, 100, t), lerp(100, 40, t), 0.8);
    noStroke();
    ellipse(icx, icy, r * 1.5, r * 1.8);
  }

  // Overlapping warm/cool particles in the intersection zone
  for (let i = 0; i < 300; i++) {
    let angle = random(TWO_PI);
    let dist = random(20, 200);
    let nVal = noise(cos(angle) * 2.5 + 30, sin(angle) * 2.5 + 30, i * 0.02);
    let x = icx + cos(angle) * dist * nVal;
    let y = icy + sin(angle) * dist * nVal * 1.1;
    let size = random(15, 60);

    // Colors blend from warm to gold to soft white at center
    let centerDist = dist / 200;
    let r, g, b;
    if (random() > 0.5) {
      // Warm side
      r = lerp(255, 200, centerDist) + random(-20, 20);
      g = lerp(200, 80, centerDist) + random(-10, 20);
      b = lerp(120, 40, centerDist) + random(-10, 20);
    } else {
      // Cool side bleeding in
      r = lerp(255, 100, centerDist) + random(-20, 20);
      g = lerp(180, 70, centerDist) + random(-10, 20);
      b = lerp(150, 140, centerDist) + random(-10, 20);
    }
    let a = random(8, 25) * (1 - centerDist * 0.5);

    noStroke();
    fill(r, g, b, a);
    ellipse(x, y, size, size * random(0.8, 1.2));
  }

  // Bright core particles
  for (let i = 0; i < 80; i++) {
    let angle = random(TWO_PI);
    let dist = random(5, 80);
    let x = icx + cos(angle) * dist;
    let y = icy + sin(angle) * dist;
    let size = random(5, 25);

    let r = 255;
    let g = 220 + random(35);
    let b = 150 + random(60);
    let a = random(15, 40) * (1 - dist / 100);

    noStroke();
    fill(r, g, b, a);
    ellipse(x, y, size);
  }

  // Radiant light streaks from center
  for (let i = 0; i < 40; i++) {
    let angle = random(TWO_PI);
    let len = random(80, 250);
    let sx = icx + cos(angle) * 20;
    let sy = icy + sin(angle) * 20;
    let ex = icx + cos(angle) * len;
    let ey = icy + sin(angle) * len;

    let midX = (sx + ex) / 2 + random(-30, 30);
    let midY = (sy + ey) / 2 + random(-30, 30);

    stroke(255, 200, 120, random(5, 15));
    strokeWeight(random(1, 4));
    noFill();
    beginShape();
    curveVertex(sx, sy);
    curveVertex(sx, sy);
    curveVertex(midX, midY);
    curveVertex(ex, ey);
    curveVertex(ex, ey);
    endShape();
  }
}

function drawParticles() {
  // Floating embers/particles scattered throughout
  for (let i = 0; i < 500; i++) {
    let x = random(width);
    let y = random(height);

    // More particles near the forms and intersection
    let d1 = dist(x, y, 520, 1120);
    let d2 = dist(x, y, 1050, 800);
    let d3 = dist(x, y, 780, 950);
    let minD = min(d1, d2, d3);

    let probability = 1 - minD / 800;
    if (random() > probability * 0.7 + 0.15) continue;

    let size = random(1, 5);
    let nVal = noise(x * 0.01, y * 0.01);

    let r, g, b;
    if (nVal > 0.6) {
      r = 255; g = 200 + random(55); b = 120 + random(80);
    } else if (nVal > 0.4) {
      r = 220 + random(35); g = 100 + random(60); b = 80 + random(40);
    } else {
      r = 120 + random(60); g = 100 + random(60); b = 180 + random(60);
    }
    let a = random(30, 100) * (1 - minD / 1000);

    noStroke();
    fill(r, g, b, a);
    ellipse(x, y, size);

    // Some particles have a glow
    if (size > 3 && random() > 0.6) {
      fill(r, g, b, a * 0.2);
      ellipse(x, y, size * 4);
    }
  }
}

function drawFinalTouches() {
  // Subtle vignette
  for (let i = 0; i < 50; i++) {
    let t = i / 50;
    noFill();
    stroke(8, 6, 15, t * 8);
    strokeWeight(40);
    rect(0, 0, width, height);
  }

  // Top and bottom fade to darkness
  for (let y = 0; y < 200; y++) {
    let a = map(y, 0, 200, 180, 0);
    stroke(8, 6, 15, a);
    line(0, y, width, y);
    line(0, height - y, width, height - y);
  }

  // A few bright star-like points
  for (let i = 0; i < 20; i++) {
    let x = random(300, 1300);
    let y = random(600, 1300);
    let size = random(2, 4);

    noStroke();
    fill(255, 240, 200, random(100, 200));
    ellipse(x, y, size);
    fill(255, 240, 200, random(20, 40));
    ellipse(x, y, size * 6);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  pixelDensity(1);
}

function draw() {
  // Deep background gradient
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(8, 25, t);
    let g = lerp(3, 8, t);
    let b = lerp(35, 50, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Subtle background texture
  noStroke();
  for (let i = 0; i < 3000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.003, y * 0.003);
    fill(255, 255, 255, n * 8);
    circle(x, y, random(1, 3));
  }

  // Distant stars
  for (let i = 0; i < 200; i++) {
    let x = random(width);
    let y = random(height * 0.6);
    let s = random(0.5, 2);
    fill(200, 180, 255, random(20, 60));
    circle(x, y, s);
  }

  // Generate two flowing paths using noise
  let path1 = [];
  let path2 = [];
  let numPoints = 600;

  for (let i = 0; i < numPoints; i++) {
    let t = i / numPoints;
    let baseY = lerp(1900, 100, t);

    // Path 1 - starts left, weaves
    let offsetX1 = noise(t * 2.5, 0) * 500 - 250;
    let centerX1 = width * 0.4 + sin(t * PI * 2.5) * 200;
    let x1 = centerX1 + offsetX1;

    // Path 2 - starts right, weaves
    let offsetX2 = noise(t * 2.5, 10) * 500 - 250;
    let centerX2 = width * 0.6 + sin(t * PI * 2.5 + PI) * 200;
    let x2 = centerX2 + offsetX2;

    // Make them converge toward the middle as they rise
    let convergence = pow(t, 1.5);
    x1 = lerp(x1, width * 0.5, convergence * 0.4);
    x2 = lerp(x2, width * 0.5, convergence * 0.4);

    path1.push({ x: x1, y: baseY });
    path2.push({ x: x2, y: baseY });
  }

  // Draw glow behind the forms
  for (let layer = 5; layer >= 1; layer--) {
    let spread = layer * 25;
    let alpha = 3;

    // Glow path 1
    noFill();
    stroke(200, 50, 80, alpha);
    strokeWeight(spread);
    beginShape();
    for (let p of path1) {
      curveVertex(p.x, p.y);
    }
    endShape();

    // Glow path 2
    stroke(220, 150, 50, alpha);
    strokeWeight(spread);
    beginShape();
    for (let p of path2) {
      curveVertex(p.x, p.y);
    }
    endShape();
  }

  // Draw the flowing ribbon forms with varying width
  // Form 1 - deep crimson to rose
  for (let pass = 0; pass < 8; pass++) {
    let offset = (pass - 4) * 8;
    let alphaBase = map(abs(pass - 4), 0, 4, 80, 15);

    noFill();
    beginShape();
    for (let i = 0; i < numPoints; i++) {
      let t = i / numPoints;
      let p = path1[i];
      let nx = noise(t * 3, pass * 5) * 30 - 15;
      let ribbonWidth = sin(t * PI) * 40 + 20;
      let x = p.x + offset + nx + (pass - 4) * (ribbonWidth / 4);

      let r = lerp(180, 255, noise(t * 2, pass));
      let g = lerp(20, 80, t);
      let b = lerp(50, 120, noise(t * 4, pass + 20));

      stroke(r, g, b, alphaBase);
      strokeWeight(2 + noise(t * 5, pass) * 3);
      curveVertex(x, p.y);
    }
    endShape();
  }

  // Form 2 - amber to gold
  for (let pass = 0; pass < 8; pass++) {
    let offset = (pass - 4) * 8;
    let alphaBase = map(abs(pass - 4), 0, 4, 80, 15);

    noFill();
    beginShape();
    for (let i = 0; i < numPoints; i++) {
      let t = i / numPoints;
      let p = path2[i];
      let nx = noise(t * 3, pass * 5 + 50) * 30 - 15;
      let ribbonWidth = sin(t * PI) * 40 + 20;
      let x = p.x + offset + nx + (pass - 4) * (ribbonWidth / 4);

      let r = lerp(220, 255, noise(t * 2, pass + 30));
      let g = lerp(120, 200, noise(t * 3, pass + 40));
      let b = lerp(20, 60, t);

      stroke(r, g, b, alphaBase);
      strokeWeight(2 + noise(t * 5, pass + 50) * 3);
      curveVertex(x, p.y);
    }
    endShape();
  }

  // Draw luminous intersection particles where paths are close
  for (let i = 0; i < numPoints; i += 2) {
    let p1 = path1[i];
    let p2 = path2[i];
    let dist = abs(p1.x - p2.x);

    if (dist < 150) {
      let intensity = map(dist, 0, 150, 1, 0);
      let midX = (p1.x + p2.x) / 2;
      let midY = p1.y;

      // Core glow
      let numDots = floor(intensity * 5);
      for (let d = 0; d < numDots; d++) {
        let ox = random(-30, 30) * (1 - intensity * 0.5);
        let oy = random(-15, 15);
        let size = random(2, 8) * intensity;
        let alpha = random(80, 220) * intensity;

        // Warm white/pink glow
        let cr = lerp(255, 255, random());
        let cg = lerp(180, 240, random());
        let cb = lerp(150, 220, random());

        fill(cr, cg, cb, alpha);
        noStroke();
        circle(midX + ox, midY + oy, size);
      }

      // Larger soft glow at very close points
      if (dist < 60) {
        let glowSize = map(dist, 0, 60, 80, 20);
        for (let g = 4; g >= 1; g--) {
          fill(255, 200, 180, 3 * g);
          circle(midX, midY, glowSize * g * 0.7);
        }
      }
    }
  }

  // Central merging area - intense warm light where they fully converge (upper portion)
  let mergeCenterY = 400;
  let mergeCenterX = width / 2;

  for (let ring = 8; ring >= 1; ring--) {
    let size = ring * 60;
    let alpha = map(ring, 1, 8, 25, 2);
    fill(255, 220, 200, alpha);
    noStroke();
    ellipse(mergeCenterX, mergeCenterY, size, size * 1.3);
  }

  // Bright core
  fill(255, 250, 240, 40);
  ellipse(mergeCenterX, mergeCenterY, 50, 65);
  fill(255, 255, 255, 60);
  ellipse(mergeCenterX, mergeCenterY, 20, 25);

  // Floating ember particles throughout
  for (let i = 0; i < 500; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.005, y * 0.005, 3);

    if (n > 0.5) {
      let distToCenter = dist(x, y, mergeCenterX, mergeCenterY);
      let proximity = constrain(map(distToCenter, 0, 600, 1, 0), 0, 1);

      let size = random(1, 4) * (0.3 + proximity * 0.7);
      let alpha = random(30, 120) * (0.3 + proximity * 0.7);

      let r = lerp(255, 255, random());
      let g = lerp(100, 220, random());
      let b = lerp(50, 180, random());

      fill(r, g, b, alpha);
      noStroke();
      circle(x, y, size);
    }
  }

  // Soft vignette
  for (let i = 0; i < 40; i++) {
    noFill();
    stroke(8, 3, 35, 12);
    strokeWeight(30);
    let margin = i * 15;
    rect(-margin, -margin, width + margin * 2, height + margin * 2, 0);
  }

  // Final soft light rays from the merge point
  for (let i = 0; i < 20; i++) {
    let angle = random(TWO_PI);
    let len = random(200, 500);
    let x2 = mergeCenterX + cos(angle) * len;
    let y2 = mergeCenterY + sin(angle) * len;

    stroke(255, 220, 200, random(3, 8));
    strokeWeight(random(1, 3));
    line(mergeCenterX, mergeCenterY, x2, y2);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  pixelDensity(1);
}

function draw() {
  background(20, 8, 25);

  // Deep gradient background
  for (let y = 0; y < 2000; y++) {
    let inter = map(y, 0, 2000, 0, 1);
    let c1 = color(15, 5, 30);
    let c2 = color(45, 8, 25);
    let c3 = color(25, 5, 40);
    let col;
    if (inter < 0.5) {
      col = lerpColor(c1, c2, inter * 2);
    } else {
      col = lerpColor(c2, c3, (inter - 0.5) * 2);
    }
    // Add noise variation
    let n = noise(y * 0.005, 0.5) * 15 - 7;
    col = color(red(col) + n, green(col) + n * 0.5, blue(col) + n);
    stroke(col);
    strokeWeight(1);
    line(0, y, 1600, y);
  }

  // Atmospheric glow in center
  noStroke();
  for (let i = 40; i > 0; i--) {
    let alpha = map(i, 40, 0, 0, 8);
    fill(80, 20, 40, alpha);
    ellipse(800, 1050, i * 50, i * 60);
  }

  // Warm radiance behind figures
  for (let i = 30; i > 0; i--) {
    let alpha = map(i, 30, 0, 0, 5);
    fill(180, 60, 40, alpha);
    ellipse(780, 1000, i * 35, i * 45);
  }

  // Draw flowing organic forms - the space of love between figures
  drawFlowingForms();

  // Draw the two figures
  drawLeftFigure();
  drawRightFigure();

  // Draw the embrace/connection
  drawEmbrace();

  // Floating particles of light
  drawParticles();

  // Final painterly texture overlay
  drawTexture();
}

function drawFlowingForms() {
  // Organic flowing curves suggesting energy between the two
  noFill();
  for (let k = 0; k < 25; k++) {
    let baseAlpha = 15 + random(20);
    let hueShift = random(-20, 20);
    stroke(180 + hueShift, 80 + hueShift * 0.5, 90 - hueShift * 0.3, baseAlpha);
    strokeWeight(random(1, 4));
    beginShape();
    let startY = 400 + random(800);
    let startX = 500 + random(200);
    for (let t = 0; t < 100; t++) {
      let n1 = noise(k * 0.3, t * 0.02) * 400 - 200;
      let n2 = noise(k * 0.3 + 100, t * 0.02) * 600 - 300;
      let x = startX + n1 + sin(t * 0.05) * 100;
      let y = startY + t * 8 + n2 * 0.3;
      curveVertex(x, y);
    }
    endShape();
  }

  // Sweeping arcs
  for (let k = 0; k < 8; k++) {
    stroke(200, 120, 80, 20 + k * 3);
    strokeWeight(2 + random(3));
    noFill();
    beginShape();
    for (let t = 0; t < TWO_PI; t += 0.05) {
      let r = 250 + k * 30 + noise(k, t * 0.5) * 150;
      let x = 780 + cos(t + k * 0.4) * r * 0.8;
      let y = 950 + sin(t + k * 0.4) * r * 1.1;
      curveVertex(x, y);
    }
    endShape();
  }
}

function drawLeftFigure() {
  // Left figure - slightly cooler tones (deep blue-red)
  push();
  translate(650, 900);

  // Body silhouette built from overlapping ellipses and curves
  noStroke();

  // Torso mass
  for (let i = 20; i > 0; i--) {
    let alpha = map(i, 20, 0, 5, 40);
    fill(120 + i * 3, 40 + i, 50 + i * 2, alpha);
    ellipse(-20, 100, 180 + i * 8, 300 + i * 10);
  }

  // Head
  for (let i = 15; i > 0; i--) {
    let alpha = map(i, 15, 0, 5, 45);
    fill(150 + i * 4, 70 + i * 2, 60 + i, alpha);
    ellipse(-10, -180, 120 + i * 5, 140 + i * 5);
  }

  // Hair flowing
  for (let i = 0; i < 12; i++) {
    fill(60 + i * 5, 20 + i * 2, 35 + i * 3, 30);
    beginShape();
    for (let t = 0; t < 50; t++) {
      let n = noise(i * 0.5, t * 0.05) * 80 - 40;
      let x = -40 + n + sin(t * 0.1 + i) * 30;
      let y = -250 + t * 6;
      vertex(x, y);
    }
    for (let t = 49; t >= 0; t--) {
      let n = noise(i * 0.5 + 50, t * 0.05) * 80 - 40;
      let x = -10 + n + sin(t * 0.1 + i) * 30;
      let y = -250 + t * 6;
      vertex(x, y);
    }
    endShape(CLOSE);
  }

  // Arm reaching toward right figure
  for (let i = 10; i > 0; i--) {
    fill(140 + i * 3, 55 + i, 55, 25 + i * 2);
    beginShape();
    for (let t = 0; t < 30; t++) {
      let n = noise(i, t * 0.1) * 20;
      let x = t * 8 + n;
      let y = 30 + sin(t * 0.15) * 30 + n * 0.5;
      vertex(x, y);
    }
    for (let t = 29; t >= 0; t--) {
      let n = noise(i + 20, t * 0.1) * 20;
      let x = t * 8 + n;
      let y = 60 + sin(t * 0.15) * 30 + n * 0.5;
      vertex(x, y);
    }
    endShape(CLOSE);
  }

  // Shoulder definition
  for (let i = 8; i > 0; i--) {
    fill(135 + i * 4, 50 + i * 2, 55 + i, 30);
    ellipse(-60, -40, 100 + i * 10, 80 + i * 8);
    ellipse(40, -30, 90 + i * 8, 70 + i * 7);
  }

  // Lower body dissolving into flowing forms
  for (let i = 15; i > 0; i--) {
    fill(100 + i * 3, 35 + i, 45 + i, 20);
    beginShape();
    for (let t = 0; t < 40; t++) {
      let n = noise(i * 0.3, t * 0.08) * 100;
      let x = -80 + t * 5 + n * 0.3;
      let y = 250 + t * 8 + sin(t * 0.2) * 40 + n;
      vertex(x, y);
    }
    for (let t = 39; t >= 0; t--) {
      let n = noise(i * 0.3 + 10, t * 0.08) * 100;
      let x = -40 + t * 5 + n * 0.3;
      let y = 280 + t * 8 + sin(t * 0.2) * 40 + n;
      vertex(x, y);
    }
    endShape(CLOSE);
  }

  pop();
}

function drawRightFigure() {
  // Right figure - warmer tones (gold-amber)
  push();
  translate(920, 880);

  noStroke();

  // Torso mass
  for (let i = 20; i > 0; i--) {
    let alpha = map(i, 20, 0, 5, 40);
    fill(180 + i * 2, 100 + i * 3, 50 + i, alpha);
    ellipse(20, 120, 170 + i * 8, 310 + i * 10);
  }

  // Head
  for (let i = 15; i > 0; i--) {
    let alpha = map(i, 15, 0, 5, 45);
    fill(200 + i * 2, 130 + i * 3, 80 + i * 2, alpha);
    ellipse(10, -170, 115 + i * 5, 135 + i * 5);
  }

  // Hair - different texture
  for (let i = 0; i < 10; i++) {
    fill(50 + i * 3, 25 + i * 2, 15 + i, 35);
    beginShape();
    for (let t = 0; t < 45; t++) {
      let n = noise(i * 0.5 + 200, t * 0.04) * 60 - 30;
      let x = 20 + n + sin(t * 0.12 + i * 0.5) * 25;
      let y = -240 + t * 7;
      vertex(x, y);
    }
    for (let t = 44; t >= 0; t--) {
      let n = noise(i * 0.5 + 250, t * 0.04) * 60 - 30;
      let x = 45 + n + sin(t * 0.12 + i * 0.5) * 25;
      let y = -240 + t * 7;
      vertex(x, y);
    }
    endShape(CLOSE);
  }

  // Arm reaching toward left figure
  for (let i = 10; i > 0; i--) {
    fill(190 + i * 2, 110 + i * 2, 60, 25 + i * 2);
    beginShape();
    for (let t = 0; t < 30; t++) {
      let n = noise(i + 100, t * 0.1) * 20;
      let x = -t * 7 + n;
      let y = 20 + sin(t * 0.15) * 25 + n * 0.5;
      vertex(x, y);
    }
    for (let t = 29; t >= 0; t--) {
      let n = noise(i + 120, t * 0.1) * 20;
      let x = -t * 7 + n;
      let y = 55 + sin(t * 0.15) * 25 + n * 0.5;
      vertex(x, y);
    }
    endShape(CLOSE);
  }

  // Shoulder
  for (let i = 8; i > 0; i--) {
    fill(190 + i * 3, 110 + i * 3, 60 + i, 30);
    ellipse(60, -30, 100 + i * 10, 80 + i * 8);
    ellipse(-40, -20, 85 + i * 8, 70 + i * 7);
  }

  // Lower body dissolving
  for (let i = 15; i > 0; i--) {
    fill(160 + i * 2, 80 + i * 2, 40, 20);
    beginShape();
    for (let t = 0; t < 40; t++) {
      let n = noise(i * 0.3 + 100, t * 0.08) * 100;
      let x = -60 + t * 5 + n * 0.3;
      let y = 270 + t * 8 + sin(t * 0.18 + 1) * 40 + n;
      vertex(x, y);
    }
    for (let t = 39; t >= 0; t--) {
      let n = noise(i * 0.3 + 110, t * 0.08) * 100;
      let x = -30 + t * 5 + n * 0.3;
      let y = 300 + t * 8 + sin(t * 0.18 + 1) * 40 + n;
      vertex(x, y);
    }
    endShape(CLOSE);
  }

  pop();
}

function drawEmbrace() {
  // The space where they merge - the most luminous part
  push();
  translate(790, 920);
  noStroke();

  // Central glow of connection
  for (let i = 25; i > 0; i--) {
    let alpha = map(i, 25, 0, 2, 20);
    fill(220, 140, 80, alpha);
    ellipse(0, 50, i * 20, i * 25);
  }

  // Intertwining curves - the physical embrace
  for (let k = 0; k < 15; k++) {
    let r = 140 + noise(k) * 60;
    let g = 70 + noise(k + 50) * 50;
    let b = 50 + noise(k + 100) * 40;
    stroke(r, g, b, 30 + noise(k + 150) * 25);
    strokeWeight(2 + noise(k + 200) * 4);
    noFill();
    beginShape();
    for (let t = 0; t < 60; t++) {
      let n1 = noise(k * 0.2, t * 0.03) * 150 - 75;
      let n2 = noise(k * 0.2 + 500, t * 0.03) * 150 - 75;
      let x = n1 + sin(t * 0.1 + k) * 50;
      let y = -100 + t * 7 + n2 * 0.5;
      curveVertex(x, y);
    }
    endShape();
  }

  // Hands meeting/touching - suggested by concentrated light
  for (let i = 12; i > 0; i--) {
    fill(240, 180, 120, map(i, 12, 0, 3, 15));
    ellipse(0, 60, i * 12, i * 10);
  }

  // Energy lines radiating from the connection point
  for (let k = 0; k < 30; k++) {
    let angle = random(TWO_PI);
    let len = 50 + random(200);
    stroke(220 + random(35), 150 + random(60), 80 + random(40), 15 + random(15));
    strokeWeight(1 + random(2));
    let sx = cos(angle) * 20;
    let sy = sin(angle) * 20 + 50;
    let ex = cos(angle) * len + noise(k) * 30;
    let ey = sin(angle) * len + 50 + noise(k + 300) * 30;
    line(sx, sy, ex, ey);
  }

  pop();
}

function drawParticles() {
  // Floating luminous particles throughout
  noStroke();
  for (let i = 0; i < 300; i++) {
    let x = random(1600);
    let y = random(2000);
    let size = random(2, 8);
    let distFromCenter = dist(x, y, 800, 1000);
    let alpha = map(distFromCenter, 0, 1000, 80, 15);
    alpha = constrain(alpha, 10, 80);

    let r = 200 + random(55);
    let g = 150 + random(80);
    let b = 80 + random(60);

    // Glow
    fill(r, g, b, alpha * 0.3);
    ellipse(x, y, size * 4, size * 4);
    fill(r, g, b, alpha);
    ellipse(x, y, size, size);
  }

  // Larger dreamy orbs
  for (let i = 0; i < 15; i++) {
    let x = random(200, 1400);
    let y = random(300, 1800);
    let size = random(20, 60);
    let r = 180 + random(75);
    let g = 100 + random(80);
    let b = 60 + random(60);
    for (let j = 5; j > 0; j--) {
      fill(r, g, b, map(j, 5, 0, 3, 12));
      ellipse(x, y, size * j * 0.8, size * j * 0.8);
    }
  }
}

function drawTexture() {
  // Painterly grain texture overlay
  loadPixels();
  for (let y = 0; y < 2000; y += 2) {
    for (let x = 0; x < 1600; x += 2) {
      let idx = (y * 1600 + x) * 4;
      let n = noise(x * 0.01, y * 0.01) * 30 - 15;
      let grain = random(-8, 8);
      pixels[idx] = constrain(pixels[idx] + n + grain, 0, 255);
      pixels[idx + 1] = constrain(pixels[idx + 1] + n * 0.7 + grain, 0, 255);
      pixels[idx + 2] = constrain(pixels[idx + 2] + n * 0.5 + grain, 0, 255);

      // Copy to adjacent pixels for 2x2 blocks
      if (x + 1 < 1600) {
        let idx2 = (y * 1600 + x + 1) * 4;
        pixels[idx2] = pixels[idx];
        pixels[idx2 + 1] = pixels[idx + 1];
        pixels[idx2 + 2] = pixels[idx + 2];
      }
      if (y + 1 < 2000) {
        let idx3 = ((y + 1) * 1600 + x) * 4;
        pixels[idx3] = pixels[idx];
        pixels[idx3 + 1] = pixels[idx + 1];
        pixels[idx3 + 2] = pixels[idx + 2];
        if (x + 1 < 1600) {
          let idx4 = ((y + 1) * 1600 + x + 1) * 4;
          pixels[idx4] = pixels[idx];
          pixels[idx4 + 1] = pixels[idx + 1];
          pixels[idx4 + 2] = pixels[idx + 2];
        }
      }
    }
  }
  updatePixels();

  // Subtle vignette
  noFill();
  for (let i = 0; i < 50; i++) {
    stroke(10, 3, 15, map(i, 0, 50, 20, 0));
    strokeWeight(40);
    rect(i * 8, i * 8, 1600 - i * 16, 2000 - i * 16);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
