}

function draw() {
  // Deep background gradient
  for (let y = 0; y < 2000; y++) {
    let t = y / 2000;
    let r = lerp(15, 35, t);
    let g = lerp(5, 8, t);
    let b = lerp(30, 20, t);
    stroke(r, g, b);
    line(0, y, 1600, y);
  }

  // Subtle radial glow in center
  noStroke();
  for (let i = 600; i > 0; i--) {
    let t = i / 600;
    fill(80 * (1 - t), 20 * (1 - t), 50 * (1 - t), 3);
    ellipse(800, 950, i * 3, i * 3.5);
