  // Draw two intertwining flowing forms
  drawFlowingForm(550, 200, 1050, 1800, color(200, 50, 70), color(255, 120, 80), 0);
  drawFlowingForm(1050, 200, 550, 1800, color(180, 40, 100), color(255, 100, 60), 100);

