function drawFlowingForm(xStart, yStart, xEnd, yEnd, col1, col2, offsetSeed) {
  let steps = 120;
  let points = [];

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let baseX = lerp(xStart, xEnd, t);
    let baseY = lerp(yStart, yEnd, t);

    // Add sinusoidal and noise displacement
    let wave = sin(t * PI * 3.5 + offsetSeed * 0.01) * 180;
    let nx = noise(t * 2.5 + offsetSeed, 0) * 200 - 100;
    let ny = noise(t * 2.5 + offsetSeed, 100) * 80 - 40;

    points.push({ x: baseX + wave + nx, y: baseY + ny });
  }

  // Draw multiple layered strokes for organic feel
  for (let layer = 0; layer < 25; layer++) {
    let layerT = layer / 25;
    let thickness = map(layerT, 0, 1, 80, 5);
    let alpha = map(layerT, 0, 1, 8, 30);

    noFill();
    beginShape();
    for (let i = 0; i < points.length; i++) {
      let p = points[i];
      let t = i / points.length;
      let ox = noise(i * 0.1 + layer * 10 + offsetSeed, layer) * 30 - 15;
      let oy = noise(i * 0.1 + layer * 10 + offsetSeed, layer + 50) * 30 - 15;

      let c = lerpColor(col1, col2, t);
      stroke(red(c), green(c), blue(c), alpha);
      strokeWeight(thickness + noise(i * 0.3 + layer) * 15);
      curveVertex(p.x + ox, p.y + oy);
      if (i === 0) curveVertex(p.x + ox, p.y + oy);
    }
    let last = points[points.length - 1];
    curveVertex(last.x, last.y);
    endShape();
  }

  // Bright core
  noFill();
  beginShape();
  for (let i = 0; i < points.length; i++) {
    let p = points[i];
    stroke(255, 220, 200, 20);
    strokeWeight(3);
    curveVertex(p.x, p.y);
    if (i === 0) curveVertex(p.x, p.y);
  }
  let last = points[points.length - 1];
  curveVertex(last.x, last.y);
  endShape();
}

function drawEmbraceZone() {
  // Where the two forms cross/meet - around center
  let cx = 800;
  let cy = 950;

  // Golden radiant glow
  for (let i = 0; i < 400; i++) {
    let angle = random(TWO_PI);
    let dist = random(250);
    let x = cx + cos(angle) * dist * noise(i * 0.1);
    let y = cy + sin(angle) * dist * 1.2 * noise(i * 0.1 + 50);
    let s = random(2, 8);
    let alpha = map(dist, 0, 250, 60, 5);
    noStroke();
    fill(255, 200 + random(55), 100 + random(50), alpha);
    ellipse(x, y, s, s);
  }

  // Flowing light tendrils connecting
  for (let t = 0; t < 30; t++) {
    noFill();
    let startAngle = random(TWO_PI);
    let radius = random(40, 180);
    beginShape();
    for (let i = 0; i <= 20; i++) {
      let tt = i / 20;
      let a = startAngle + tt * PI * random(0.5, 1.5);
      let r = radius * (1 - tt * 0.7) + noise(t + i * 0.5) * 40;
      let x = cx + cos(a) * r;
      let y = cy + sin(a) * r * 1.3;
      stroke(255, 220, 150, 15 - tt * 10);
      strokeWeight(random(1, 3));
      curveVertex(x, y);
      if (i === 0) curveVertex(x, y);
    }
    endShape();
  }

  // Central bright bloom
  for (let i = 100; i > 0; i--) {
    let t = i / 100;
    noStroke();
    fill(255, 230, 180, 2 * (1 - t));
    ellipse(cx, cy, i * 5, i * 6);
  }
}

function drawParticles() {
  // Floating luminous particles throughout
  for (let i = 0; i < 2000; i++) {
    let x = random(1600);
    let y = random(2000);

    // More particles near center
    let distFromCenter = dist(x, y, 800, 950);
    let probability = map(distFromCenter, 0, 1000, 1, 0.2);

    if (random() < probability) {
      let size = random(1, 4);
      let alpha = random(20, 80);
      let warmth = random();

      noStroke();
      if (warmth < 0.5) {
        fill(255, 200 + random(55), 150, alpha);
      } else if (warmth < 0.8) {
        fill(255, 150, 180, alpha * 0.7);
      } else {
        fill(255, 255, 230, alpha * 0.5);
      }
      ellipse(x, y, size, size);

      // Glow around larger particles
      if (size > 2.5) {
        fill(255, 200, 150, alpha * 0.15);
        ellipse(x, y, size * 5, size * 5);
      }
    }
  }
}

function drawVignette() {
  // Soft dark edges
  noStroke();
  // Top
  for (let y = 0; y < 300; y++) {
    let alpha = map(y, 0, 300, 180, 0);
    fill(10, 3, 20, alpha);
    rect(0, y, 1600, 1);
  }
  // Bottom
  for (let y = 1700; y < 2000; y++) {
    let alpha = map(y, 1700, 2000, 0, 180);
    fill(10, 3, 20, alpha);
    rect(0, y, 1600, 1);
  }
  // Left
  for (let x = 0; x < 250; x++) {
    let alpha = map(x, 0, 250, 150, 0);
    fill(10, 3, 20, alpha);
    rect(x, 0, 1, 2000);
  }
  // Right
  for (let x = 1350; x < 1600; x++) {
    let alpha = map(x, 1350, 1600, 0, 150);
    fill(10, 3, 20, alpha);
    rect(x, 0, 1, 2000);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  pixelDensity(1);
}

function draw() {
  background(8, 5, 18);

  // Subtle background texture
  for (let i = 0; i < 5000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.003, y * 0.003);
    let alpha = n * 20;
    fill(30 + n * 40, 10 + n * 20, 50 + n * 60, alpha);
    noStroke();
    ellipse(x, y, random(2, 8), random(2, 8));
  }

  // Stars
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = random(height);
    let s = random(0.5, 2.5);
    let bright = random(100, 255);
    fill(bright, bright, bright * 0.9, random(80, 200));
    ellipse(x, y, s, s);
  }

  // Define meeting point
  let meetX = width * 0.5;
  let meetY = height * 0.48;

  // Form 1 - from bottom-left (warm: amber/gold)
  drawNebulaForm(
    -100, height + 100,
    meetX, meetY,
    [255, 160, 40],
    [255, 100, 30],
    [255, 200, 80],
    1.0
  );

  // Form 2 - from top-right (cool-warm: rose/crimson)
  drawNebulaForm(
    width + 100, -100,
    meetX, meetY,
    [220, 40, 80],
    [180, 20, 100],
    [255, 80, 120],
    -1.0
  );

  // Tendrils connecting the forms
  drawTendrils(meetX, meetY);

  // Central burst of union
  drawUnionBurst(meetX, meetY);

  // Floating particles throughout
  drawFloatingParticles();

  // Vignette
  drawVignette();
}

function drawNebulaForm(startX, startY, endX, endY, col1, col2, col3, dir) {
  let layers = 400;

  for (let i = 0; i < layers; i++) {
    let t = i / layers;
    let tNoise = noise(i * 0.02) * 0.3;
    let progress = t + tNoise * 0.2;
    progress = constrain(progress, 0, 1);

    // Curved path from start to end
    let midX = (startX + endX) / 2 + dir * 200 * sin(progress * PI);
    let midY = (startY + endY) / 2 - 150 * cos(progress * PI * 0.7);

    let x, y;
    if (progress < 0.5) {
      let p = progress * 2;
      x = lerp(startX, midX, p);
      y = lerp(startY, midY, p);
    } else {
      let p = (progress - 0.5) * 2;
      x = lerp(midX, endX, p);
      y = lerp(midY, endY, p);
    }

    // Add organic displacement
    let nx = noise(i * 0.05, 0) * 200 - 100;
    let ny = noise(0, i * 0.05) * 200 - 100;
    x += nx * (1 - t * 0.5);
    y += ny * (1 - t * 0.5);

    // Size decreases toward meeting point
    let baseSize = lerp(180, 40, t * t);
    let sizeVar = noise(i * 0.1) * baseSize * 0.6;
    let s = baseSize + sizeVar;

    // Color interpolation
    let r, g, b;
    if (t < 0.5) {
      r = lerp(col1[0], col2[0], t * 2);
      g = lerp(col1[1], col2[1], t * 2);
      b = lerp(col1[2], col2[2], t * 2);
    } else {
      r = lerp(col2[0], col3[0], (t - 0.5) * 2);
      g = lerp(col2[1], col3[1], (t - 0.5) * 2);
      b = lerp(col2[2], col3[2], (t - 0.5) * 2);
    }

    let alpha = lerp(12, 35, noise(i * 0.03));
    if (t > 0.7) alpha *= lerp(1, 2.5, (t - 0.7) / 0.3);

    noStroke();
    fill(r, g, b, alpha);
    ellipse(x, y, s, s * (0.7 + noise(i * 0.08) * 0.6));
  }

  // Inner glow particles along the form
  for (let i = 0; i < 150; i++) {
    let t = random(0.2, 1.0);
    let progress = t;

    let midX = (startX + endX) / 2 + dir * 200 * sin(progress * PI);
    let midY = (startY + endY) / 2 - 150 * cos(progress * PI * 0.7);

    let x, y;
    if (progress < 0.5) {
      let p = progress * 2;
      x = lerp(startX, midX, p);
      y = lerp(startY, midY, p);
    } else {
      let p = (progress - 0.5) * 2;
      x = lerp(midX, endX, p);
      y = lerp(midY, endY, p);
    }

    let nx = noise(i * 0.1 + 100) * 100 - 50;
    let ny = noise(100 + i * 0.1) * 100 - 50;
    x += nx;
    y += ny;

    let s = random(2, 6);
    fill(col3[0], col3[1], col3[2], random(40, 120));
    ellipse(x, y, s, s);
  }
}

function drawTendrils(mx, my) {
  noFill();

  // Warm tendrils from left form
  for (let i = 0; i < 12; i++) {
    let startX = mx - 200 - random(300);
    let startY = my + random(-200, 400);

    beginShape();
    let segments = 40;
    for (let j = 0; j <= segments; j++) {
      let t = j / segments;
      let x = lerp(startX, mx + random(-50, 50), t);
      let y = lerp(startY, my + random(-50, 50), t);
      x += noise(i * 3, j * 0.1) * 80 - 40;
      y += noise(j * 0.1, i * 3) * 80 - 40;
      let alpha = sin(t * PI) * 25;
      stroke(255, 180, 60, alpha);
      strokeWeight(random(0.5, 2));
      curveVertex(x, y);
    }
    endShape();
  }

  // Cool tendrils from right form
  for (let i = 0; i < 12; i++) {
    let startX = mx + 200 + random(300);
    let startY = my - random(-200, 400);

    beginShape();
    let segments = 40;
    for (let j = 0; j <= segments; j++) {
      let t = j / segments;
      let x = lerp(startX, mx + random(-50, 50), t);
      let y = lerp(startY, my + random(-50, 50), t);
      x += noise(i * 3 + 50, j * 0.1) * 80 - 40;
      y += noise(j * 0.1, i * 3 + 50) * 80 - 40;
      let alpha = sin(t * PI) * 25;
      stroke(240, 60, 100, alpha);
      strokeWeight(random(0.5, 2));
      curveVertex(x, y);
    }
    endShape();
  }

  // Intertwining tendrils at meeting point
  for (let i = 0; i < 20; i++) {
    beginShape();
    let segments = 30;
    let angleOffset = random(TWO_PI);
    let radius = random(30, 150);
    for (let j = 0; j <= segments; j++) {
      let t = j / segments;
      let angle = angleOffset + t * PI * 2;
      let r = radius * (1 - t * 0.5) * noise(i * 2, j * 0.1);
      let x = mx + cos(angle) * r + noise(j * 0.2, i) * 40 - 20;
      let y = my + sin(angle) * r * 0.8 + noise(i, j * 0.2) * 40 - 20;

      let col = lerpColor(
        color(255, 160, 60, sin(t * PI) * 30),
        color(230, 50, 90, sin(t * PI) * 30),
        noise(i * 0.5)
      );
      stroke(col);
      strokeWeight(random(0.3, 1.5));
      curveVertex(x, y);
    }
    endShape();
  }
}

function drawUnionBurst(mx, my) {
  // Outer glow layers
  for (let i = 20; i > 0; i--) {
    let s = i * 25;
    let alpha = map(i, 20, 0, 2, 15);
    noStroke();

    let r = lerp(255, 255, i / 20);
    let g = lerp(100, 220, i / 20);
    let b = lerp(80, 180, i / 20);

    fill(r, g, b, alpha);
    ellipse(mx, my, s, s);
  }

  // Radiating rays
  for (let i = 0; i < 60; i++) {
    let angle = random(TWO_PI);
    let len = random(40, 250) * noise(i * 0.2);
    let x2 = mx + cos(angle) * len;
    let y2 = my + sin(angle) * len;

    let alpha = random(5, 25);
    stroke(255, 230, 200, alpha);
    strokeWeight(random(0.5, 3));
    line(mx, my, x2, y2);
  }

  // Bright core particles
  for (let i = 0; i < 80; i++) {
    let angle = random(TWO_PI);
    let dist = random(0, 60) * noise(i * 0.1);
    let x = mx + cos(angle) * dist;
    let y = my + sin(angle) * dist;
    let s = random(1, 5);

    fill(255, 250, 240, random(80, 200));
    noStroke();
    ellipse(x, y, s, s);
  }

  // Bright white center
  for (let i = 5; i > 0; i--) {
    let s = i * 8;
    let alpha = map(i, 5, 0, 20, 80);
    fill(255, 255, 250, alpha);
    ellipse(mx, my, s, s);
  }
}

function drawFloatingParticles() {
  for (let i = 0; i < 200; i++) {
    let x = random(width);
    let y = random(height);
    let s = random(1, 4);

    let distToCenter = dist(x, y, width / 2, height * 0.48);
    let influence = map(distToCenter, 0, 600, 1, 0);
    influence = constrain(influence, 0, 1);

    let r = lerp(255, 200, random());
    let g = lerp(200, 150, random());
    let b = lerp(150, 220, random());
    let alpha = random(20, 80) * (0.3 + influence * 0.7);

    noStroke();
    fill(r, g, b, alpha);
    ellipse(x, y, s, s);

    // Glow around some particles
    if (random() > 0.7) {
      fill(r, g, b, alpha * 0.2);
      ellipse(x, y, s * 4, s * 4);
    }
  }
}

function drawVignette() {
  // Darken edges
  let cx = width / 2;
  let cy = height / 2;
  let maxDist = dist(0, 0, cx, cy);

  noStroke();
  for (let i = 0; i < 40; i++) {
    let t = i / 40;
    let s = lerp(maxDist * 2.5, maxDist * 0.8, t);
    let alpha = lerp(0, 60, t * t);
    fill(5, 2, 12, alpha);
    ellipse(cx, cy, s * 1.2, s * 1.5);
  }

  // Top and bottom fade
  for (let y = 0; y < 200; y++) {
    let alpha = map(y, 0, 200, 80, 0);
    fill(8, 5, 18, alpha);
    noStroke();
    rect(0, y, width, 1);
    rect(0, height - y - 1, width, 1);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  pixelDensity(1);
}

function draw() {
  drawBackground();
  drawStars();
  drawMoon();
  drawDistantHills();
  drawOrganicShape(width * 0.32, height * 0.52, 560, 720, [212, 130, 106], [245, 180, 150], -1);
  drawOrganicShape(width * 0.68, height * 0.52, 560, 720, [212, 168, 87], [245, 215, 140], 1);
  drawFusion();
  drawForegroundPetals();
  drawReflection();
  drawVignette();
}

function drawBackground() {
  noStroke();
  let steps = 80;
  for (let i = 0; i < steps; i++) {
    let t = i / steps;
    let y = t * height;
    let r = lerp(10, 58, t * 0.85);
    let g = lerp(22, 28, t * 0.9);
    let b = lerp(46, 78, t);
    fill(r, g, b);
    rect(0, y, width, height / steps + 1);
  }
  // Soft horizontal haze
  for (let i = 0; i < 6; i++) {
    let y = height * (0.35 + i * 0.08);
    fill(80, 60, 110, 6);
    ellipse(width / 2, y, width * 1.4, 120);
  }
}

function drawStars() {
  noStroke();
  for (let i = 0; i < 260; i++) {
    let x = random(width);
    let y = random(height * 0.75);
    let n = noise(x * 0.004, y * 0.004, i * 0.05);
    if (n > 0.48) {
      let s = pow(n, 3) * 3.5 + 0.3;
      let a = 180 * pow(n, 2);
      fill(245, 235, 210, a);
      ellipse(x, y, s, s);
      if (s > 2.2) {
        fill(245, 235, 210, a * 0.15);
        ellipse(x, y, s * 5, s * 5);
      }
    }
  }
}

function drawMoon() {
  let mx = width * 0.72;
  let my = height * 0.18;
  let mr = 110;
  // Halo
  noStroke();
  for (let r = mr * 4; r > mr; r -= 12) {
    let t = map(r, mr, mr * 4, 0.9, 0);
    fill(245, 230, 200, 8 * t);
    ellipse(mx, my, r * 2, r * 2);
  }
  // Moon body
  for (let i = 0; i < 30; i++) {
    let t = i / 30;
    let r = lerp(mr, 0, t);
    let c = lerpColor(color(255, 245, 220), color(240, 200, 150), t * t);
    fill(c);
    ellipse(mx, my, r * 2, r * 2);
  }
  // Craters subtle
  for (let i = 0; i < 8; i++) {
    let a = random(TWO_PI);
    let d = random(mr * 0.6);
    let cx = mx + cos(a) * d;
    let cy = my + sin(a) * d;
    fill(200, 170, 130, 40);
    ellipse(cx, cy, random(8, 22), random(8, 22));
  }
}

function drawDistantHills() {
  noStroke();
  fill(20, 25, 55, 180);
  beginShape();
  vertex(0, height);
  for (let x = 0; x <= width; x += 20) {
    let y = height * 0.82 + noise(x * 0.002) * 80 - 40;
    vertex(x, y);
  }
  vertex(width, height);
  endShape(CLOSE);

  fill(35, 30, 65, 160);
  beginShape();
  vertex(0, height);
  for (let x = 0; x <= width; x += 20) {
    let y = height * 0.86 + noise(x * 0.003 + 10) * 70 - 30;
    vertex(x, y);
  }
  vertex(width, height);
  endShape(CLOSE);
}

function buildBlobPath(cx, cy, rx, ry, seedOff, detail) {
  let pts = [];
  let n = detail;
  for (let i = 0; i < n; i++) {
    let ang = (i / n) * TWO_PI;
    let nval = noise(cos(ang) * 1.2 + seedOff + 5, sin(ang) * 1.2 + seedOff + 5, seedOff * 0.3);
    let wobble = map(nval, 0, 1, 0.78, 1.18);
    let px = cx + cos(ang) * rx * wobble;
    let py = cy + sin(ang) * ry * wobble;
    pts.push({ x: px, y: py });
  }
  return pts;
}

function drawBlobFilled(pts, col, alpha) {
  fill(col[0], col[1], col[2], alpha);
  noStroke();
  beginShape();
  for (let i = 0; i < pts.length; i++) {
    let p0 = pts[(i - 1 + pts.length) % pts.length];
    let p1 = pts[i];
    let p2 = pts[(i + 1) % pts.length];
    let p3 = pts[(i + 2) % pts.length];
    curveVertex(p1.x, p1.y);
  }
  // close smoothly
  for (let i = 0; i < 3; i++) {
    curveVertex(pts[i].x, pts[i].y);
  }
  endShape(CLOSE);
}

function drawOrganicShape(cx, cy, rx, ry, coreCol, edgeCol, sideSign) {
  let detail = 120;
  // Outer soft glow
  for (let k = 6; k >= 1; k--) {
    let scale = 1 + k * 0.04;
    let pts = buildBlobPath(cx, cy, rx * scale, ry * scale, 1 + sideSign * 0.5, detail);
    let a = 14 - k * 1.5;
    drawBlobFilled(pts, edgeCol, a);
  }
  // Main body with radial shading via multiple layers
  let layers = 14;
  for (let i = layers; i >= 0; i--) {
    let t = i / layers;
    let shrink = 0.55 + 0.45 * t;
    let pts = buildBlobPath(cx, cy, rx * shrink, ry * shrink, 1 + sideSign * 0.5, detail);
    let col = [
      lerp(coreCol[0], edgeCol[0], t * t),
      lerp(coreCol[1], edgeCol[1], t * t),
      lerp(coreCol[2], edgeCol[2], t * t)
    ];
    let alpha = lerp(220, 40, t);
    drawBlobFilled(pts, col, alpha);
  }
  // Inner light specks
  for (let i = 0; i < 40; i++) {
    let ang = random(TWO_PI);
    let d = random(0.7);
    let n = noise(cos(ang) + sideSign + 10, sin(ang) + 10, i * 0.1);
    if (n > 0.5) {
      let x = cx + cos(ang) * rx * d * 0.85;
      let y = cy + sin(ang) * ry * d * 0.85;
      fill(255, 240, 220, 90 * (n - 0.5) * 2);
      noStroke();
      ellipse(x, y, random(2, 5), random(2, 5));
    }
  }
}

function drawFusion() {
  let cx = width / 2;
  let cy = height * 0.52;
  // Central glow where both shapes meet
  noStroke();
  for (let r = 520; r > 0; r -= 14) {
    let t = 1 - r / 520;
    fill(250, 210, 170, 6 * pow(t, 1.5));
    ellipse(cx, cy, r * 2, r * 2.2);
  }
  // Intertwined filaments
  strokeWeight(1.2);
  for (let i = 0; i < 70; i++) {
    let a = random(TWO_PI);
    let r1 = random(60, 380);
    let r2 = random(60, 380);
    let x1 = cx + cos(a) * r1;
    let y1 = cy + sin(a) * r1 * 1.1;
    let x2 = cx + cos(a + PI + random(-0.4, 0.4)) * r2;
    let y2 = cy + sin(a + PI + random(-0.4, 0.4)) * r2 * 1.1;
    let mid = random(0.7, 1.0);
    let warm = lerpColor(color(245, 180, 150, 80), color(245, 215, 140, 80), random());
    stroke(warm);
    noFill();
    beginShape();
    curveVertex(x1, y1);
    curveVertex(x1, y1);
    curveVertex(lerp(x1, x2, 0.33), lerp(y1, y2, 0.33) + random(-40, 40) * mid);
    curveVertex(lerp(x1, x2, 0.66), lerp(y1, y2, 0.66) + random(-40, 40) * mid);
    curveVertex(x2, y2);
    curveVertex(x2, y2);
    endShape();
  }
  // Small sparks
  noStroke();
  for (let i = 0; i < 120; i++) {
    let ang = random(TWO_PI);
    let d = pow(random(), 1.5) * 280;
    let x = cx + cos(ang) * d;
    let y = cy + sin(ang) * d * 1.1;
    let s = random(1, 3.5);
    fill(255, 235, 200, random(120, 220));
    ellipse(x, y, s, s);
  }
}

function drawForegroundPetals() {
  noStroke();
  // Floating petals / embers drifting between the two forms
  for (let i = 0; i < 90; i++) {
    let x = random(width * 0.15, width * 0.85);
    let y = random(height * 0.25, height * 0.8);
    let s = random(3, 10);
    let n = noise(x * 0.003, y * 0.003, i * 0.05);
    let warm = n > 0.5;
    let col = warm ? [245, 175, 140] : [235, 205, 130];
    fill(col[0], col[1], col[2], 120 * n);
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    ellipse(0, 0, s, s * 0.5);
    pop();
  }
}

function drawReflection() {
  // Water surface at bottom
  let y0 = height * 0.86;
  noStroke();
  for (let y = y0; y < height; y += 2) {
    let t = (y - y0) / (height - y0);
    fill(lerp(30, 10, t), lerp(30, 15, t), lerp(60, 35, t), 220);
    rect(0, y, width, 2);
  }
  // Reflected ripples of light
  for (let i = 0; i < 60; i++) {
    let x = random(width);
    let y = random(y0 + 10, height - 10);
    let w = random(30, 160);
    let a = random(20, 70) * (1 - (y - y0) / (height - y0));
    let warm = noise(x * 0.005, y * 0.01) > 0.5;
    fill(warm ? 240 : 230, warm ? 190 : 210, warm ? 160 : 140, a);
    ellipse(x, y, w, 1.8);
  }
  // Central reflection of fusion glow
  for (let r = 300; r > 0; r -= 15) {
    let t = 1 - r / 300;
    fill(245, 205, 170, 10 * pow(t, 1.8));
    ellipse(width / 2, y0 + 60, r * 2, r * 0.4);
  }
}

function drawVignette() {
  noStroke();
  // Corners
  for (let i = 0; i < 20; i++) {
    let a = map(i, 0, 20, 40, 0);
    fill(5, 10, 25, a);
    let w = width + i * 40;
    let h = height + i * 40;
    ellipse(width / 2, height / 2, w, h);
  }
  // Soft top glow near moon
  noStroke();
  for (let r = 900; r > 0; r -= 30) {
    fill(245, 220, 190, 2 * (1 - r / 900));
    ellipse(width * 0.72, height * 0.18, r * 2, r * 2);
  }
}

