}

function drawMass(cx, cy, rx, ry, palette, seedOff) {
  // Build organic contour points
  let pts = [];
  let steps = 220;
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * TWO_PI;
    let nx = cos(a) * 1.6 + seedOff;
    let ny = sin(a) * 1.6 + seedOff;
    let n = noise(nx, ny, seedOff * 0.1);
    let radX = rx * (0.75 + n * 0.55);
    let radY = ry * (0.75 + n * 0.55);
    pts.push({ x: cx + cos(a) * radX, y: cy + sin(a) * radY });
  }

  // Soft outer halo (many layers)
  for (let k = 0; k < 18; k++) {
    let t = k / 18;
    let c = palette[k % palette.length];
    fill(c[0], c[1], c[2], 6);
    noStroke();
    beginShape();
    for (let p of pts) {
      let dx = p.x - cx, dy = p.y - cy;
      vertex(cx + dx * (1 + t * 0.18), cy + dy * (1 + t * 0.18));
    }
    endShape(CLOSE);
  }

  // Painterly fill: thousands of small ellipses inside the contour
  for (let i = 0; i < 9000; i++) {
    // Random point in bounding ellipse
    let a = random(TWO_PI);
    let rr = sqrt(random());
    let px = cx + cos(a) * rx * rr * 0.95;
    let py = cy + sin(a) * ry * rr * 0.95;

    // Reject if outside contour via noise boundary
    let ang = atan2(py - cy, px - cx);
    let nx = cos(ang) * 1.6 + seedOff;
    let ny = sin(ang) * 1.6 + seedOff;
    let n = noise(nx, ny, seedOff * 0.1);
    let bndX = rx * (0.75 + n * 0.55);
    let bndY = ry * (0.75 + n * 0.55);
    let dx = (px - cx) / bndX;
    let dy = (py - cy) / bndY;
    if (dx * dx + dy * dy > 1) continue;

    let dist = sqrt(dx * dx + dy * dy);
    let c = palette[floor(random(palette.length))];
    // Brighter toward center
    let bright = map(dist, 0, 1, 1.2, 0.7);
    let alpha = map(dist, 0, 1, 180, 60);
    fill(c[0] * bright, c[1] * bright, c[2] * bright, alpha);
    noStroke();
    let s = random(3, 14);
    ellipse(px + random(-3, 3), py + random(-3, 3), s, s);
  }

  // Inner luminous core
  for (let k = 0; k < 20; k++) {
    let t = k / 20;
    let r = 180 * (1 - t);
    fill(255, 245, 235, 10 + t * 8);
    noStroke();
    ellipse(cx, cy, r * 2, r * 2.2);
  }
}

function drawFilaments(x1, y1, x2, y2) {
  noFill();
  for (let i = 0; i < 40; i++) {
    let amp = random(40, 180);
    let freq = random(0.004, 0.012);
    let phase = random(TWO_PI);
    let col = random() < 0.5 ? [255, 200, 180] : [255, 230, 200];
    stroke(col[0], col[1], col[2], random(15, 45));
    strokeWeight(random(0.8, 2.2));
    beginShape();
    for (let t = 0; t <= 1; t += 0.01) {
      let x = lerp(x1, x2, t);
      let y = lerp(y1, y2, t);
      let off = sin(t * TWO_PI * 2 + phase) * amp * sin(t * PI);
      off += (noise(t * 8 + i, i * 0.3) - 0.5) * 60;
      vertex(x, y + off);
    }
    endShape();
  }
  // Brighter central threads
  for (let i = 0; i < 8; i++) {
    let amp = random(20, 60);
    let phase = random(TWO_PI);
    stroke(255, 230, 210, 60);
    strokeWeight(random(1.2, 2.4));
    beginShape();
    for (let t = 0; t <= 1; t += 0.01) {
      let x = lerp(x1, x2, t);
      let y = lerp(y1, y2, t);
      let off = sin(t * TWO_PI * 3 + phase) * amp * sin(t * PI);
      vertex(x, y + off);
    }
    endShape();
  }
}

function drawConfluence(cx, cy) {
  // Warm layered glow
  noStroke();
  for (let k = 60; k > 0; k--) {
    let t = k / 60;
    let r = 60 + k * 12;
    let a = 3 + (1 - t) * 6;
    fill(255, 220, 190, a);
    ellipse(cx, cy, r * 2.2, r * 2.4);
  }
  // Inner bright nucleus blending rose and gold
  for (let k = 30; k > 0; k--) {
    let t = k / 30;
    let r = k * 6;
    let rr = lerp(255, 255, t);
    let gg = lerp(200, 250, t);
    let bb = lerp(180, 240, t);
    fill(rr, gg, bb, 15);
    ellipse(cx + random(-1, 1), cy + random(-1, 1), r * 2, r * 2.1);
  }
  // Sparkling flecks at the meeting point
  for (let i = 0; i < 120; i++) {
    let a = random(TWO_PI);
    let d = random(0, 140);
    let x = cx + cos(a) * d;
    let y = cy + sin(a) * d;
    let s = random(0.8, 2.6);
    fill(255, 250, 240, random(120, 240));
    ellipse(x, y, s, s);
  }
}

function setup() {
  createCanvas(1600, 2000);
