      let x = px + dirX * (s / 60) + nx;
      let y = py + dirY * (s / 60) + ny;
      let alpha = 20 * (1 - s / 60);
      stroke(random(160, 220), random(50, 100), random(60, 100), alpha);
      strokeWeight(random(1, 4));
      point(x, y);
      // Add dots along the path
      fill(random(180, 240), random(60, 120), random(70, 120), alpha * 0.5);
      noStroke();
