    ellipse(x, y, size, size * random(0.7, 1.3));
  }

  // Final luminous accents at center
  for (let i = 0; i < 500; i++) {
    let angle = random(TWO_PI);
    let dist = pow(random(), 3) * 100;
    let x = midX + cos(angle) * dist;
    let y = midY + sin(angle) * dist;
    let size = random(1, 4);
    fill(255, 250, 230, random(20, 80));
    noStroke();
    ellipse(x, y, size);
  }

  // Subtle vignette
  for (let i = 0; i < 50; i++) {
    noFill();
    stroke(5, 3, 15, map(i, 0, 50, 0, 8));
    strokeWeight(40);
    let m = -i * 30;
    rect(m, m, width - m * 2, height - m * 2);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  pixelDensity(1);

  // Two attractors on a diagonal
  const A = { x: 520, y: 640 };
  const B = { x: 1080, y: 1360 };

  // Deep cosmic background with subtle gradient + noise
  background(8, 8, 22);
  for (let y = 0; y < height; y += 4) {
    const t = y / height;
    const r = lerp(14, 28, t) + noise(y * 0.01) * 10;
    const g = lerp(10, 14, t) + noise(y * 0.01 + 10) * 6;
    const b = lerp(32, 48, t) + noise(y * 0.01 + 20) * 12;
    noStroke();
    fill(r, g, b);
    rect(0, y, width, 4);
  }

  // Starfield dust
  for (let i = 0; i < 1800; i++) {
    const x = random(width);
    const y = random(height);
    const s = random(0.4, 1.6);
    const a = random(30, 110) * (1 - abs(noise(x * 0.002, y * 0.002) - 0.5) * 1.2);
    noStroke();
    fill(220, 210, 240, a);
    circle(x, y, s);
  }

  // Large soft glows (halos) behind each soul and at the midpoint
  drawingContext.globalCompositeOperation = 'lighter';

  function glow(cx, cy, radius, c1, c2, c3) {
    for (let r = radius; r > 0; r -= 6) {
      const t = r / radius;
      const a = pow(1 - t, 1.6) * 28;
      fill(lerpColor(color(c1), color(c2), t));
      noStroke();
      const col = lerpColor(color(c1), color(c2), t);
      fill(red(col), green(col), blue(col), a);
      ellipse(cx, cy, r * 2, r * 2);
    }
  }

  // Halo A — rose/coral
  glow(A.x, A.y, 520, color(255, 140, 120), color(120, 20, 60));
  // Halo B — amber/gold
  glow(B.x, B.y, 520, color(255, 210, 120), color(140, 70, 20));
  // Shared midpoint halo — luminous cream
  const mx = (A.x + B.x) / 2;
  const my = (A.y + B.y) / 2;
  glow(mx, my, 360, color(255, 235, 210), color(200, 110, 120));

  drawingContext.globalCompositeOperation = 'source-over';

  // Particle clouds around each attractor
  noStroke();
  const N_A = 3500;
  for (let i = 0; i < N_A; i++) {
    // radius with heavy-tail distribution
    const rr = pow(random(), 0.55) * 560;
    const ang = random(TWO_PI) + noise(i * 0.02) * 0.6;
    const nx = noise(i * 0.01, 0) * 2 - 1;
    const ny = noise(i * 0.01, 100) * 2 - 1;
    let x = A.x + cos(ang) * rr + nx * 40;
    let y = A.y + sin(ang) * rr + ny * 40;

    // Pull slightly toward B when close to the bridge
    const dx = B.x - x, dy = B.y - y;
    const d = sqrt(dx * dx + dy * dy);
    if (d < 900) {
      const pull = pow(1 - d / 900, 2) * 120;
      x += (dx / d) * pull * (0.3 + noise(i * 0.03));
      y += (dy / d) * pull * (0.3 + noise(i * 0.03 + 5));
    }

    const t = rr / 560;
    const col = lerpColor(color(255, 230, 220), color(230, 80, 90), t);
    const alpha = lerp(220, 40, t) * (0.6 + noise(i * 0.05) * 0.6);
    fill(red(col), green(col), blue(col), alpha);
    const sz = lerp(2.4, 0.6, t) + random(-0.3, 0.3);
    circle(x, y, sz);
  }

  const N_B = 3500;
  for (let i = 0; i < N_B; i++) {
    const rr = pow(random(), 0.55) * 560;
    const ang = random(TWO_PI) + noise(i * 0.02 + 50) * 0.6;
    const nx = noise(i * 0.01 + 200, 0) * 2 - 1;
    const ny = noise(i * 0.01 + 200, 100) * 2 - 1;
    let x = B.x + cos(ang) * rr + nx * 40;
    let y = B.y + sin(ang) * rr + ny * 40;

    const dx = A.x - x, dy = A.y - y;
    const d = sqrt(dx * dx + dy * dy);
    if (d < 900) {
      const pull = pow(1 - d / 900, 2) * 120;
      x += (dx / d) * pull * (0.3 + noise(i * 0.03 + 7));
      y += (dy / d) * pull * (0.3 + noise(i * 0.03 + 9));
    }

    const t = rr / 560;
    const col = lerpColor(color(255, 240, 200), color(220, 150, 40), t);
    const alpha = lerp(220, 40, t) * (0.6 + noise(i * 0.05 + 3) * 0.6);
    fill(red(col), green(col), blue(col), alpha);
    const sz = lerp(2.4, 0.6, t) + random(-0.3, 0.3);
    circle(x, y, sz);
  }

  // Filaments — curves threading A and B through the midpoint
  drawingContext.globalCompositeOperation = 'lighter';
  const nFil = 70;
  for (let i = 0; i < nFil; i++) {
    const t0 = i / nFil;
    const angA = random(TWO_PI);
    const rA = random(40, 260);
    const angB = random(TWO_PI);
    const rB = random(40, 260);
    const x1 = A.x + cos(angA) * rA;
    const y1 = A.y + sin(angA) * rA;
    const x2 = B.x + cos(angB) * rB;
    const y2 = B.y + sin(angB) * rB;

    // Two control points near the midpoint, slightly offset by noise
    const off = noise(i * 0.3) * 260 - 130;
    const perpX = -(y2 - y1);
    const perpY = (x2 - x1);
    const plen = sqrt(perpX * perpX + perpY * perpY);
    const cx1 = mx + (perpX / plen) * off + random(-40, 40);
    const cy1 = my + (perpY / plen) * off + random(-40, 40);
    const cx2 = mx + (perpX / plen) * (off * 0.6) + random(-40, 40);
    const cy2 = my + (perpY / plen) * (off * 0.6) + random(-40, 40);

    noFill();
    const col = lerpColor(color(255, 170, 140), color(255, 220, 170), t0);
    stroke(red(col), green(col), blue(col), 40 + noise(i) * 60);
    strokeWeight(random(0.6, 1.8));
    bezier(x1, y1, cx1, cy1, cx2, cy2, x2, y2);
  }

  // Bright sparks along filaments (points of contact)
  noStroke();
  for (let i = 0; i < 220; i++) {
    const t = random();
    const baseX = lerp(A.x, B.x, t);
    const baseY = lerp(A.y, B.y, t);
    const wob = noise(i * 0.1) * 180 - 90;
    const dx = B.x - A.x, dy = B.y - A.y;
    const dl = sqrt(dx * dx + dy * dy);
    const px = baseX + (-dy / dl) * wob;
    const py = baseY + (dx / dl) * wob;
    const col = lerpColor(color(255, 200, 170), color(255, 240, 200), t);
    fill(red(col), green(col), blue(col), 150 + random(100));
    circle(px, py, random(0.8, 2.6));
  }

  // Central nucleus — the "third place" born between them
  drawingContext.globalCompositeOperation = 'lighter';
  for (let i = 0; i < 900; i++) {
    const ang = random(TWO_PI);
    const rr = pow(random(), 0.7) * 180;
    const x = mx + cos(ang) * rr;
    const y = my + sin(ang) * rr;
    const t = rr / 180;
    const col = lerpColor(color(255, 255, 240), color(255, 180, 160), t);
    const a = lerp(220, 20, t);
    fill(red(col), green(col), blue(col), a);
    noStroke();
    circle(x, y, lerp(3.2, 0.8, t));
  }

  // A few bright stars at the core
  for (let i = 0; i < 14; i++) {
    const ang = random(TWO_PI);
    const rr = random(0, 60);
    const x = mx + cos(ang) * rr;
    const y = my + sin(ang) * rr;
    fill(255, 250, 235, 230);
    circle(x, y, random(2, 4));
  }

  drawingContext.globalCompositeOperation = 'source-over';

  // Soft vignette
  for (let i = 0; i < 40; i++) {
    noFill();
    stroke(0, 0, 0, 10);
    strokeWeight(30);
    const m = i * 20;
    rect(m / 2, m / 2, width - m, height - m);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function draw() {
  background(8, 4, 22);

  // Nébuleuse diffuse
  noStroke();
  for (let y = 0; y < 2000; y += 14) {
    for (let x = 0; x < 1600; x += 14) {
      let n = noise(x * 0.0025, y * 0.0025);
      let n2 = noise(x * 0.0012 + 100, y * 0.0012 + 100);
      let d = dist(x, y, 800, 1000) / 1000;
      let alpha = Math.max(0, (1 - d)) * n * 40;
      if (alpha > 2) {
        if (n2 < 0.5) fill(70, 20, 120, alpha);
        else fill(40, 10, 90, alpha);
        rect(x, y, 15, 15);
      }
    }
  }

  // Halo central chaud
  let ctx = drawingContext;
  let grd = ctx.createRadialGradient(800, 980, 60, 800, 980, 780);
  grd.addColorStop(0, 'rgba(255, 190, 130, 0.28)');
  grd.addColorStop(0.25, 'rgba(255, 110, 140, 0.14)');
  grd.addColorStop(0.6, 'rgba(140, 60, 160, 0.06)');
  grd.addColorStop(1, 'rgba(0, 0, 0, 0)');
  ctx.fillStyle = grd;
  ctx.fillRect(0, 0, 1600, 2000);

  // Étoiles lointaines
  for (let i = 0; i < 600; i++) {
    let x = random(1600);
    let y = random(2000);
    let s = random(0.4, 1.8);
    let a = random(50, 200);
    noStroke();
    fill(225, 215, 245, a);
    ellipse(x, y, s, s);
  }

  // Rubans entrelacés
  drawIntertwinedRibbons();

  // Particules flottantes dorées/roses
  for (let i = 0; i < 260; i++) {
    let x = random(1600);
    let y = random(2000);
    let s = random(1, 3.5);
    let c = random();
    noStroke();
    if (c < 0.4) fill(255, 200, 140, random(110, 230));
    else if (c < 0.7) fill(255, 140, 180, random(110, 230));
    else fill(255, 245, 225, random(110, 230));
    ellipse(x, y, s, s);
  }

  // Lueurs aux points d'approche
  drawApproachGlows();

  // Vignette
  let vgrd = ctx.createRadialGradient(800, 1000, 500, 800, 1000, 1350);
  vgrd.addColorStop(0, 'rgba(0,0,0,0)');
  vgrd.addColorStop(1, 'rgba(0,0,0,0.75)');
  ctx.fillStyle = vgrd;
  ctx.fillRect(0, 0, 1600, 2000);
}

function drawIntertwinedRibbons() {
  let pts1 = [], pts2 = [];
  let tours = 3.5;
  let steps = 900;

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let y = lerp(1920, 90, t);
    let bell = sin(t * PI);
    let r = 340 * bell * (0.65 + 0.45 * noise(t * 2.5));
    let nx = noise(t * 3, 0) * 90 - 45;
    let ny = noise(t * 3, 50) * 40 - 20;

    let phase = t * TAU * tours;
    let x1 = 800 + cos(phase) * r + nx;
    let z1 = sin(phase);
    let x2 = 800 + cos(phase + PI) * r + nx;
    let z2 = sin(phase + PI);

    pts1.push({ x: x1, y: y + ny, z: z1, t: t });
    pts2.push({ x: x2, y: y + ny, z: z2, t: t });
  }

  for (let i = 0; i < steps; i++) {
    let p1a = pts1[i], p1b = pts1[i + 1];
    let p2a = pts2[i], p2b = pts2[i + 1];
    let z1 = (p1a.z + p1b.z) / 2;
    let z2 = (p2a.z + p2b.z) / 2;

    if (z1 < z2) {
      drawSegment(p1a, p1b, 0);
      drawSegment(p2a, p2b, 1);
    } else {
      drawSegment(p2a, p2b, 1);
      drawSegment(p1a, p1b, 0);
    }
  }
}

function drawSegment(a, b, type) {
  let zAvg = (a.z + b.z) / 2;
  let thick = 26 + abs(zAvg) * 30;
  let depth = map(zAvg, -1, 1, 0.35, 1);

  let c1, c2;
  if (type === 0) {
    c1 = color(255, 70, 130);
    c2 = color(255, 160, 190);
  } else {
    c1 = color(255, 165, 65);
    c2 = color(255, 225, 150);
  }
  let midT = (a.t + b.t) / 2;
  let midC = lerpColor(c1, c2, midT);

  // Halo externe
  stroke(red(midC), green(midC), blue(midC), 28 * depth);
  strokeWeight(thick * 2.6);
  line(a.x, a.y, b.x, b.y);

  // Corps
  stroke(red(midC) * depth, green(midC) * depth, blue(midC) * depth, 210);
  strokeWeight(thick);
  line(a.x, a.y, b.x, b.y);

  // Reflet lumineux sur la face avant
  let hi = Math.max(0, zAvg);
  stroke(255, 245, 230, 140 * depth * hi);
  strokeWeight(Math.max(1, thick * 0.28));
  line(a.x, a.y, b.x, b.y);
}

function drawApproachGlows() {
  let tours = 3.5;
  let ctx = drawingContext;
  // Points où les deux rubans se croisent (sin(phase)=0)
  for (let k = 0; k < tours * 2; k++) {
    let phase = k * PI;
    let t = phase / (TAU * tours);
    if (t < 0 || t > 1) continue;
    let y = lerp(1920, 90, t);
    let bell = sin(t * PI);
    let r = 340 * bell * (0.65 + 0.45 * noise(t * 2.5));
    let nx = noise(t * 3, 0) * 90 - 45;
    let ny = noise(t * 3, 50) * 40 - 20;
    let x = 800 + nx;
    let yy = y + ny;

    let g = ctx.createRadialGradient(x, yy, 2, x, yy, 90);
    g.addColorStop(0, 'rgba(255, 240, 210, 0.55)');
    g.addColorStop(0.4, 'rgba(255, 180, 150, 0.18)');
    g.addColorStop(1, 'rgba(0, 0, 0, 0)');
    ctx.fillStyle = g;
    ctx.fillRect(x - 100, yy - 100, 200, 200);
  }
}

function setup(){
  createCanvas(1600,2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  pixelDensity(1);
}

function draw(){
  background(28,16,12);

  // --- Fond texturé : paroi ancienne ---
  noStroke();
  for(let y=0;y<height;y+=2){
    for(let x=0;x<width;x+=2){
      let n=noise(x*0.004,y*0.004);
      let n2=noise(x*0.015,y*0.015,3.3);
      let r=28+n*40-n2*15;
      let g=16+n*25-n2*10;
      let b=12+n*18-n2*8;
      fill(r,g,b);
      rect(x,y,2,2);
    }
  }

  // --- Halo diffus derrière les masses (la zone de rencontre) ---
  let cx=width/2, cy=height*0.42;
  noStroke();
  for(let i=40;i>0;i--){
    let a=map(i,40,0,2,18);
    let rad=i*35;
    fill(255,190,110,a);
    ellipse(cx,cy,rad*1.2,rad);
  }
  for(let i=25;i>0;i--){
    let a=map(i,25,0,3,28);
    let rad=i*22;
    fill(255,230,180,a);
    ellipse(cx,cy,rad*1.1,rad*0.95);
  }

  // --- Deux masses organiques (deux présences) ---
  function drawMass(mcx,mcy,baseR,palette,seedOff){
    // plusieurs couches, de la plus sombre (grande) à la plus claire (petite)
    for(let layer=0;layer<7;layer++){
      let r=baseR*(1-layer*0.09);
      let col=palette[min(layer,palette.length-1)];
      let alpha=180-layer*10;
      fill(col[0],col[1],col[2],alpha);
      noStroke();
      beginShape();
      let pts=180;
      for(let i=0;i<=pts;i++){
        let ang=TWO_PI*i/pts;
        let nx=cos(ang)*1.5+seedOff;
        let ny=sin(ang)*1.5+seedOff+layer*0.3;
        let nz=layer*0.7;
        let n=noise(nx+2.1,ny+3.7,nz);
        let rr=r*(0.75+n*0.55);
        let x=mcx+cos(ang)*rr;
        let y=mcy+sin(ang)*rr*0.92;
        curveVertex(x,y);
      }
      endShape(CLOSE);
    }

    // veines internes : lignes douces
    noFill();
    for(let k=0;k<14;k++){
      let col=palette[floor(random(palette.length))];
      stroke(col[0],col[1],col[2],60);
      strokeWeight(random(0.4,1.4));
      beginShape();
      let sx=mcx+random(-baseR*0.6,baseR*0.6);
      let sy=mcy+random(-baseR*0.6,baseR*0.6);
      for(let s=0;s<20;s++){
        let ang=noise(sx*0.003+seedOff,sy*0.003,k*0.5,s*0.1)*TWO_PI*2;
        sx+=cos(ang)*14;
        sy+=sin(ang)*14;
        curveVertex(sx,sy);
      }
      endShape();
    }
  }

  let paletteL=[
    [70,18,22],[110,30,28],[160,55,40],[210,110,75],[240,170,120],[250,210,170],[255,235,200]
  ];
  let paletteR=[
    [55,20,30],[95,32,38],[145,52,50],[195,95,75],[230,150,115],[248,200,165],[255,230,200]
  ];

  let leftX=cx-width*0.22;
  let rightX=cx+width*0.22;
  let leftY=cy+40;
  let rightY=cy-20;

  drawMass(leftX,leftY,360,paletteL,0);
  drawMass(rightX,rightY,340,paletteR,7.7);

  // --- Particules attirées entre les deux masses ---
  noStroke();
  for(let i=0;i<2800;i++){
    let t=random();
    // position de départ aléatoire entre les deux masses, légèrement dispersée
    let px=lerp(leftX,rightX,t)+randomGaussian()*80;
    let py=lerp(leftY,rightY,t)+randomGaussian()*140;
    // attraction vers le centre : rapproche du point de rencontre
    let dx=cx-px, dy=cy-py;
    let d=sqrt(dx*dx+dy*dy);
    let pull=map(d,0,width*0.5,0.9,0.1);
    pull=constrain(pull,0,1);
    let fx=lerp(px,cx,pull*0.55);
    let fy=lerp(py,cy,pull*0.55);
    // taille et couleur selon proximité du centre
    let closeness=1-constrain(d/(width*0.35),0,1);
    let sz=map(closeness,0,1,1.2,5)+random(0,1.5);
    let rC=lerp(120,255,closeness);
    let gC=lerp(60,210,closeness);
    let bC=lerp(50,150,closeness*0.7);
    let aC=map(closeness,0,1,40,220);
    fill(rC,gC,bC,aC);
    ellipse(fx,fy,sz,sz);
  }

  // --- Fils très fins reliant les deux masses, passant près du centre ---
  noFill();
  for(let k=0;k<22;k++){
    let col=[
      lerp(255,255,random()),
      lerp(170,220,random()),
      lerp(110,170,random())
    ];
    stroke(col[0],col[1],col[2],random(40,110));
    strokeWeight(random(0.3,1.2));
    let sx=leftX+random(-80,120);
    let sy=leftY+random(-100,100);
    let ex=rightX+random(-120,80);
    let ey=rightY+random(-100,100);
    // courbe passant par le centre avec dérive noise
    let midX=cx+randomGaussian()*40;
    let midY=cy+randomGaussian()*40;
    beginShape();
    let steps=30;
    for(let s=0;s<=steps;s++){
      let tt=s/steps;
      // interpolation quadratique sx->mid->ex
      let qx=lerp(lerp(sx,midX,tt),lerp(midX,ex,tt),tt);
      let qy=lerp(lerp(sy,midY,tt),lerp(midY,ey,tt),tt);
      let wob=noise(s*0.2,k*0.7)*30-15;
      curveVertex(qx+wob,qy+wob*0.6);
    }
    endShape();
  }

  // --- Point focal : cœur lumineux au centre ---
  noStroke();
  for(let i=18;i>0;i--){
    let a=map(i,18,0,8,55);
    fill(255,240,200,a);
    ellipse(cx,cy,i*8,i*7);
  }
  for(let i=8;i>0;i--){
    let a=map(i,8,0,40,180);
    fill(255,250,230,a);
    ellipse(cx,cy,i*5,i*4.5);
  }

  // --- Poussière flottante dans toute la toile ---
  noStroke();
  for(let i=0;i<600;i++){
    let x=random(width);
    let y=random(height);
    let s=random(0.8,2.2);
    let a=random(30,110);
    fill(255,230,200,a);
    ellipse(x,y,s,s);
  }

  // --- Voile final : vignette sombre et grain ---
  // vignette
  for(let i=0;i<120;i++){
    let a=map(i,0,120,0,50);
    noFill();
    stroke(10,5,3,a);
    strokeWeight(8);
    rect(i*3,i*3,width-i*6,height-i*6);
  }

  // grain
  loadPixels();
  for(let i=0;i<pixels.length;i+=4){
    let g=(noise(i*0.0003)-0.5)*30;
    pixels[i]  =constrain(pixels[i]  +g,0,255);
    pixels[i+1]=constrain(pixels[i+1]+g,0,255);
    pixels[i+2]=constrain(pixels[i+2]+g,0,255);
  }
  updatePixels();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  pixelDensity(1);
}

function draw() {
  // Deep background gradient
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(12, 30, t * t);
    let g = lerp(8, 12, t);
    let b = lerp(45, 25, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Subtle background noise texture
  noStroke();
  for (let i = 0; i < 30000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.003, y * 0.003);
    if (n > 0.55) {
      fill(255, 255, 255, random(3, 8));
      circle(x, y, random(1, 3));
    }
  }

  // Large atmospheric glows
  drawSoftGlow(800, 750, 900, 180, 80, 50, 25);
  drawSoftGlow(800, 900, 600, 150, 50, 80, 18);
  drawSoftGlow(600, 1100, 500, 120, 40, 60, 15);
  drawSoftGlow(1000, 1050, 500, 100, 60, 70, 15);

  // Background flowing lines (distant, subtle)
  for (let i = 0; i < 80; i++) {
    drawFlowLine(
      random(width), random(height),
      random(200, 600), random(-PI, PI),
      color(lerpColor(color(60, 30, 80), color(80, 40, 100), random()), 15),
      random(0.5, 1.5), random(0.002, 0.005)
    );
  }

  // Left form - rising from bottom-left
  drawMainForm(-1);

  // Right form - rising from bottom-right
  drawMainForm(1);

  // Intertwining tendrils in the center
  drawIntertwining();

  // Central radiance
  drawCentralRadiance();

  // Foreground flowing accents
  drawForegroundAccents();

  // Luminous particles
  drawParticles();

  // Final overlay - vignette
  drawVignette();
}

function drawSoftGlow(cx, cy, radius, r, g, b, alpha) {
  noStroke();
  for (let i = radius; i > 0; i -= 2) {
    let t = i / radius;
    fill(r, g, b, alpha * (1 - t) * (1 - t));
    ellipse(cx, cy, i * 2, i * 2);
  }
}

function drawFlowLine(startX, startY, length, angle, col, weight, noiseScale) {
  stroke(col);
  strokeWeight(weight);
  noFill();
  beginShape();
  let x = startX;
  let y = startY;
  let a = angle;
  for (let d = 0; d < length; d += 3) {
    curveVertex(x, y);
    a += (noise(x * noiseScale, y * noiseScale) - 0.5) * 0.3;
    x += cos(a) * 3;
    y += sin(a) * 3;
  }
  endShape();
}

function drawMainForm(side) {
  // side: -1 for left, 1 for right
  let baseX = side === -1 ? 350 : 1250;
  let baseY = 1900;
  let targetX = 800 + side * 50;
  let targetY = 550;

  let hueBase = side === -1 ? 0 : 320; // red vs magenta-pink base

  // Main body curves - many layered strokes
  for (let layer = 0; layer < 200; layer++) {
    let offsetX = random(-180, 180);
    let offsetY = random(-50, 50);
    let spread = random(0.6, 1.4);

    let sx = baseX + offsetX;
    let sy = baseY + offsetY;

    // Control points that curve toward center
    let midX = lerp(sx, targetX, 0.4 + random(-0.1, 0.1)) + side * random(-100, 100) * spread;
    let midY = lerp(sy, targetY, 0.35 + random(-0.1, 0.1));
    let cp1x = sx + side * random(-80, 150) * spread;
    let cp1y = sy - random(200, 500);
    let cp2x = midX + side * random(-50, 100);
    let cp2y = midY + random(-100, 200);

    let t = layer / 200;
    let h = (hueBase + random(-20, 40)) % 360;
    let s = random(60, 100);
    let br = random(50, 100);
    let alpha = random(15, 50);

    colorMode(HSB, 360, 100, 100, 100);
    stroke(h, s, br, alpha);
    strokeWeight(random(1, 4));
    noFill();

    beginShape();
    curveVertex(sx, sy);
    curveVertex(sx, sy);
    curveVertex(cp1x, cp1y);
    curveVertex(midX, midY);
    curveVertex(cp2x, cp2y);
    curveVertex(targetX + random(-60, 60), targetY + random(-80, 80));
    curveVertex(targetX + random(-60, 60), targetY + random(-80, 80));
    endShape();
    colorMode(RGB, 255);
  }

  // Thicker accent strokes
  for (let layer = 0; layer < 40; layer++) {
    let offsetX = random(-120, 120);
    let sx = baseX + offsetX;
    let sy = baseY + random(-30, 30);

    let cp1x = sx + side * random(0, 200);
    let cp1y = sy - random(400, 700);
    let cp2x = targetX + side * random(-150, 50);
    let cp2y = targetY + random(100, 400);
    let ex = targetX + random(-40, 40);
    let ey = targetY + random(-60, 60);

    colorMode(HSB, 360, 100, 100, 100);
    let h = (hueBase + random(-10, 30)) % 360;
    stroke(h, random(70, 95), random(70, 100), random(20, 40));
    strokeWeight(random(3, 8));
    noFill();
    bezier(sx, sy, cp1x, cp1y, cp2x, cp2y, ex, ey);
    colorMode(RGB, 255);
  }

  // Glowing core of the form
  let coreX = lerp(baseX, targetX, 0.4) + side * 30;
  let coreY = lerp(baseY, targetY, 0.4);
  let coreR = side === -1 ? 140 : 50;
  let coreG = side === -1 ? 40 : 30;
  let coreB = side === -1 ? 60 : 80;
  drawSoftGlow(coreX, coreY, 250, coreR, coreG, coreB, 20);

  // Upper portion glow
  let upX = lerp(baseX, targetX, 0.7) + side * 10;
  let upY = lerp(baseY, targetY, 0.7);
  drawSoftGlow(upX, upY, 200, 200, 80, 60, 15);
}

function drawIntertwining() {
  let cx = 800;
  let cy = 650;

  // Spiraling tendrils
  for (let i = 0; i < 60; i++) {
    let startAngle = random(TWO_PI);
    let startR = random(20, 150);
    let spiralTight = random(0.02, 0.06);
    let len = random(100, 300);

    colorMode(HSB, 360, 100, 100, 100);
    let h = random(10, 50); // warm golds and oranges
    stroke(h, random(60, 90), random(80, 100), random(20, 45));
    strokeWeight(random(1, 3));
    noFill();

    beginShape();
    for (let d = 0; d < len; d += 4) {
      let a = startAngle + d * spiralTight;
      let r = startR + d * random(0.3, 0.8);
      let x = cx + cos(a) * r + (noise(d * 0.02, i) - 0.5) * 60;
      let y = cy + sin(a) * r * 0.7 + (noise(d * 0.02 + 100, i) - 0.5) * 60;
      curveVertex(x, y);
    }
    endShape();
    colorMode(RGB, 255);
  }

  // Connecting arcs between the two forms
  for (let i = 0; i < 30; i++) {
    let y = random(500, 900);
    let leftX = random(500, 700);
    let rightX = random(900, 1100);
    let cpY = y - random(50, 200);

    colorMode(HSB, 360, 100, 100, 100);
    stroke(random(20, 50), random(50, 80), random(80, 100), random(15, 35));
    strokeWeight(random(1, 3));
    noFill();
    bezier(leftX, y, leftX + 50, cpY, rightX - 50, cpY, rightX, y);
    colorMode(RGB, 255);
  }
}

function drawCentralRadiance() {
  let cx = 800;
  let cy = 620;

  // Multi-layered glow
  drawSoftGlow(cx, cy, 400, 255, 180, 80, 12);
  drawSoftGlow(cx, cy, 300, 255, 200, 100, 18);
  drawSoftGlow(cx, cy, 200, 255, 220, 140, 25);
  drawSoftGlow(cx, cy, 120, 255, 240, 180, 30);
  drawSoftGlow(cx, cy, 60, 255, 250, 220, 40);

  // Light rays emanating from center
  for (let i = 0; i < 40; i++) {
    let angle = random(TWO_PI);
    let len = random(100, 500);
    let x2 = cx + cos(angle) * len;
    let y2 = cy + sin(angle) * len;

    let gradient = drawingContext;
    let grad = gradient.createLinearGradient(cx, cy, x2, y2);
    colorMode(HSB, 360, 100, 100, 100);
    let h = random(20, 50);
    grad.addColorStop(0, `hsla(${h}, 80%, 90%, 0.3)`);
    grad.addColorStop(1, `hsla(${h}, 80%, 70%, 0)`);
    gradient.strokeStyle = grad;
    gradient.lineWidth = random(1, 4);
    gradient.beginPath();
    gradient.moveTo(cx, cy);
    gradient.lineTo(x2, y2);
    gradient.stroke();
    colorMode(RGB, 255);
  }

  // Bright core dots
  noStroke();
  for (let i = 0; i < 20; i++) {
    let a = random(TWO_PI);
    let r = random(0, 40);
    let x = cx + cos(a) * r;
    let y = cy + sin(a) * r;
    fill(255, 255, 230, random(100, 200));
    circle(x, y, random(2, 6));
  }
}

function drawForegroundAccents() {
  // Floating petal-like shapes
  for (let i = 0; i < 50; i++) {
    let x = random(200, 1400);
    let y = random(200, 1800);
    let size = random(10, 40);
    let angle = random(TWO_PI);

    push();
    translate(x, y);
    rotate(angle);

    colorMode(HSB, 360, 100, 100, 100);
    let h = random(330, 380) % 360;
    if (random() > 0.5) h = random(20, 50);

    noStroke();
    fill(h, random(40, 70), random(70, 100), random(15, 35));

    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.3) {
      let r = size * (0.5 + 0.5 * sin(a * 2 + random(0.5)));
      r += noise(cos(a) * 2 + i, sin(a) * 2 + i) * size * 0.3;
      vertex(cos(a) * r, sin(a) * r);
    }
    endShape(CLOSE);
    colorMode(RGB, 255);
    pop();
  }

  // Delicate flowing lines in foreground
  for (let i = 0; i < 30; i++) {
    let startX = random(300, 1300);
    let startY = random(300, 1700);

    colorMode(HSB, 360, 100, 100, 100);
    stroke(random(0, 60), random(30, 60), random(80, 100), random(10, 25));
    strokeWeight(random(0.5, 2));
    noFill();

    beginShape();
    let x = startX, y = startY;
    let a = random(TWO_PI);
    for (let d = 0; d < random(80, 250); d += 5) {
      curveVertex(x, y);
      a += (noise(x * 0.005, y * 0.005, i * 10) - 0.5) * 0.4;
      x += cos(a) * 5;
      y += sin(a) * 5;
    }
    endShape();
    colorMode(RGB, 255);
  }
}

function drawParticles() {
  noStroke();

  // Large glowing particles
  for (let i = 0; i < 150; i++) {
    let x = random(width);
    let y = random(height);
    let size = random(2, 8);

    // More particles near center
    let distFromCenter = dist(x, y, 800, 700);
    if (distFromCenter > 800 && random() > 0.3) continue;

    let brightness = map(distFromCenter, 0, 800, 255, 150);
    let alpha = map(distFromCenter, 0, 800, 200, 80);

    // Glow around particle
    drawSoftGlow(x, y, size * 4, brightness, brightness * 0.7, brightness * 0.4, alpha * 0.15);

    colorMode(HSB, 360, 100, 100, 100);
    let h = random(20, 55);
    fill(h, random(20, 50), random(90, 100), random(40, 80));
    circle(x, y, size);
    colorMode(RGB, 255);
  }

  // Tiny sparkle dots
  for (let i = 0; i < 500; i++) {
    let x = random(width);
    let y = random(height);
    let alpha = random(30, 150);
    let size = random(0.5, 2.5);

    fill(255, random(200, 255), random(150, 220), alpha);
    circle(x, y, size);
  }
}

function drawVignette() {
  // Darken edges
  let ctx = drawingContext;
  let grad = ctx.createRadialGradient(800, 900, 400, 800, 1000, 1200);
  grad.addColorStop(0, 'rgba(0,0,0,0)');
  grad.addColorStop(0.6, 'rgba(0,0,0,0)');
  grad.addColorStop(1, 'rgba(5,3,20,0.7)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, 1600, 2000);
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function draw() {
  // Background gradient
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(15, 60, t * t);
    let g = lerp(10, 20, t);
    let b = lerp(45, 50, t * 0.5);
    // Add warm glow in center
    let cx = width / 2;
    let cy = height * 0.45;
    for (let x = 0; x < width; x++) {
      let dx = (x - cx) / width;
      let dy = (y - cy) / height;
      let dist = sqrt(dx * dx + dy * dy);
      let glow = exp(-dist * dist * 8) * 40;
      let noiseVal = noise(x * 0.003, y * 0.003) * 20 - 10;
      let fr = constrain(r + glow + noiseVal, 0, 255);
      let fg = constrain(g + glow * 0.4 + noiseVal * 0.5, 0, 255);
      let fb = constrain(b + glow * 0.2 + noiseVal * 0.3, 0, 255);
      stroke(fr, fg, fb);
      point(x, y);
    }
  }

  // Draw soft radial glow at center
  noStroke();
  for (let i = 30; i > 0; i--) {
    let alpha = map(i, 30, 0, 0, 15);
    let radius = map(i, 30, 0, 600, 50);
    fill(255, 200, 120, alpha);
    ellipse(width / 2, height * 0.45, radius * 2, radius * 2.5);
  }

  // Draw two abstract embracing forms
  drawLeftForm();
  drawRightForm();
  drawMergedCenter();
  drawFlowingVines();
  drawPetals();
  drawParticles();
  drawLightRays();
}

function drawLeftForm() {
  push();
  // Left figure - flowing abstract shape curving right
  for (let layer = 0; layer < 12; layer++) {
    let offset = layer * 3;
    let alpha = map(layer, 0, 12, 60, 15);
    beginShape();
    let points = [];
    for (let i = 0; i <= 40; i++) {
      let t = i / 40;
      let baseX = width * 0.35 + sin(t * PI) * 180 - offset;
      let baseY = lerp(height * 0.15, height * 0.85, t);
      let noiseX = noise(t * 2 + layer * 0.3, layer * 0.5) * 80 - 40;
      let noiseY = noise(t * 2 + 100 + layer * 0.3, layer * 0.5) * 30;
      let x = baseX + noiseX + sin(t * PI * 3) * 30;
      let y = baseY + noiseY;
      points.push({x, y});
    }
    // Draw as filled shape with curves
    let col = lerpColor(color(180, 50, 80, alpha), color(220, 100, 60, alpha), layer / 12);
    fill(col);
    noStroke();
    beginShape();
    for (let p of points) {
      curveVertex(p.x, p.y);
    }
    // Close with inner edge
    for (let i = points.length - 1; i >= 0; i--) {
      let p = points[i];
      curveVertex(p.x - 100 - layer * 8 + noise(i * 0.2) * 40, p.y);
    }
    endShape(CLOSE);
  }
  pop();
}

function drawRightForm() {
  push();
  for (let layer = 0; layer < 12; layer++) {
    let offset = layer * 3;
    let alpha = map(layer, 0, 12, 60, 15);
    let points = [];
    for (let i = 0; i <= 40; i++) {
      let t = i / 40;
      let baseX = width * 0.65 - sin(t * PI) * 180 + offset;
      let baseY = lerp(height * 0.15, height * 0.85, t);
      let noiseX = noise(t * 2 + 50 + layer * 0.3, layer * 0.5 + 10) * 80 - 40;
      let noiseY = noise(t * 2 + 150 + layer * 0.3, layer * 0.5 + 10) * 30;
      let x = baseX + noiseX - sin(t * PI * 3) * 30;
      let y = baseY + noiseY;
      points.push({x, y});
    }
    let col = lerpColor(color(100, 40, 120, alpha), color(180, 60, 100, alpha), layer / 12);
    fill(col);
    noStroke();
    beginShape();
    for (let p of points) {
      curveVertex(p.x, p.y);
    }
    for (let i = points.length - 1; i >= 0; i--) {
      let p = points[i];
      curveVertex(p.x + 100 + layer * 8 - noise(i * 0.2 + 50) * 40, p.y);
    }
    endShape(CLOSE);
  }
  pop();
}

function drawMergedCenter() {
  push();
  // Central intertwining organic mass
  for (let layer = 0; layer < 20; layer++) {
    let alpha = map(layer, 0, 20, 40, 8);
    noStroke();
    beginShape();
    for (let i = 0; i <= 50; i++) {
      let t = i / 50;
      let angle = t * TWO_PI * 2 + layer * 0.3;
      let radius = 100 + noise(t * 3, layer * 0.4) * 150 + sin(t * PI) * 80;
      let x = width / 2 + cos(angle) * radius * 0.6;
      let y = height * 0.45 + sin(angle) * radius * 0.8 + (t - 0.5) * 300;
      let col = lerpColor(color(255, 180, 100, alpha), color(255, 100, 120, alpha), t);
      fill(col);
      ellipse(x, y, 20 + noise(i, layer) * 30, 20 + noise(i + 50, layer) * 30);
    }
    endShape();
  }
  pop();
}

function drawFlowingVines() {
  push();
  strokeWeight(2);
  noFill();
  for (let v = 0; v < 30; v++) {
    let startX = width * 0.3 + random(width * 0.4);
    let startY = height * 0.2 + random(height * 0.6);
    let col = lerpColor(
      color(200, 120, 80, 80),
      color(255, 180, 140, 60),
      random()
    );
    stroke(col);
    beginShape();
    let x = startX, y = startY;
    for (let i = 0; i < 20; i++) {
      curveVertex(x, y);
      let angle = noise(x * 0.005, y * 0.005, v * 0.5) * TWO_PI * 2;
      x += cos(angle) * 15;
      y += sin(angle) * 15 + 5;
    }
    endShape();
  }
  pop();
}

function drawPetals() {
  push();
  noStroke();
  for (let i = 0; i < 150; i++) {
    let x = random(width);
    let y = random(height);
    // More petals near center
    let dx = (x - width / 2) / width;
    let dy = (y - height * 0.45) / height;
    let dist = sqrt(dx * dx + dy * dy);
    if (random() > exp(-dist * dist * 4) * 0.7 + 0.3) continue;

    let size = random(8, 35);
    let angle = random(TWO_PI);
    let alpha = random(30, 100);

    push();
    translate(x, y);
    rotate(angle);
    let petalColor = random() > 0.5 ?
      color(255, random(120, 200), random(100, 150), alpha) :
      color(255, random(180, 230), random(160, 200), alpha);
    fill(petalColor);
    // Petal shape
    beginShape();
    vertex(0, 0);
    bezierVertex(size * 0.3, -size * 0.5, size * 0.8, -size * 0.3, size, 0);
    bezierVertex(size * 0.8, size * 0.3, size * 0.3, size * 0.5, 0, 0);
    endShape(CLOSE);
    pop();
  }
  pop();
}

function drawParticles() {
  push();
  noStroke();
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = random(height);
    let size = random(2, 8);
    let alpha = random(40, 150);
    let col = random() > 0.6 ?
      color(255, 230, 180, alpha) :
      color(255, 180, 200, alpha * 0.7);
    fill(col);
    ellipse(x, y, size, size);
    // Glow
    if (size > 5) {
      fill(255, 230, 200, alpha * 0.2);
      ellipse(x, y, size * 3, size * 3);
    }
  }
  pop();
}

function drawLightRays() {
  push();
  // Soft light rays from center
  let cx = width / 2;
  let cy = height * 0.45;
  noStroke();
  for (let i = 0; i < 20; i++) {
    let angle = random(TWO_PI);
    let length = random(300, 800);
    let spread = random(0.02, 0.08);
    let alpha = random(5, 15);

    fill(255, 220, 180, alpha);
    beginShape();
    vertex(cx, cy);
    bezierVertex(
      cx + cos(angle - spread) * length * 0.3,
      cy + sin(angle - spread) * length * 0.3,
      cx + cos(angle - spread * 0.5) * length * 0.7,
      cy + sin(angle - spread * 0.5) * length * 0.7,
      cx + cos(angle) * length,
      cy + sin(angle) * length
    );
    bezierVertex(
      cx + cos(angle + spread * 0.5) * length * 0.7,
      cy + sin(angle + spread * 0.5) * length * 0.7,
      cx + cos(angle + spread) * length * 0.3,
      cy + sin(angle + spread) * length * 0.3,
      cx, cy
    );
    endShape(CLOSE);
  }
  pop();

  // Final soft overlay glow
  push();
  noStroke();
  for (let i = 5; i > 0; i--) {
    fill(255, 200, 150, 5);
    ellipse(cx, cy, i * 200, i * 250);
  }
  pop();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  background(20, 10, 25);

  // Warm gradient background
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let r = lerp(30, 15, inter);
    let g = lerp(12, 8, inter);
    let b = lerp(35, 22, inter);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Soft radial glow in center
  noStroke();
  for (let r = 600; r > 0; r -= 3) {
    let alpha = map(r, 0, 600, 25, 0);
    fill(60, 20, 30, alpha);
    ellipse(width / 2, height * 0.45, r * 2.5, r * 2.2);
  }

  // Draw the two intertwining forms
  drawForm(-1, color(180, 40, 50), color(220, 120, 40), color(255, 180, 80));
  drawForm(1, color(140, 30, 80), color(200, 60, 100), color(255, 140, 160));

  // Draw intertwining details
  drawIntertwine();

  // Floating particles where they meet
  drawParticles();

  // Subtle texture overlay
  drawTexture();

  // Soft vignette
  drawVignette();
}

function drawForm(side, col1, col2, col3) {
  let baseX = width / 2 + side * 180;
  let points = [];

  // Generate main trunk path using noise
  for (let i = 0; i <= 120; i++) {
    let t = i / 120;
    let y = height * 0.95 - t * height * 0.75;
    let noiseVal = noise(t * 2.5 + side * 10, 0.5);
    let sway = (noiseVal - 0.5) * 300 * t;
    let converge = side * 180 * (1 - pow(t, 1.5)) * 0.7;
    let x = width / 2 + converge + sway;

    // Additional organic wobble
    x += sin(t * PI * 3 + side) * 40 * t;

    points.push({ x: x, y: y, t: t });
  }

  // Draw layered organic form around the path
  for (let layer = 0; layer < 8; layer++) {
    let layerOffset = (layer - 4) * 12;
    let layerAlpha = map(layer, 0, 7, 40, 15);

    beginShape();
    noStroke();

    // Right side of form
    for (let i = 0; i < points.length; i++) {
      let p = points[i];
      let thickness = map(p.t, 0, 1, 90, 15) + noise(i * 0.1 + layer, layer) * 40;
      let c = lerpColor(col1, col2, p.t);
      c.setAlpha(layerAlpha + noise(i * 0.05) * 20);
      fill(c);
      ellipse(p.x + thickness + layerOffset, p.y, thickness * 0.6, 25);
    }

    // Left side of form
    for (let i = 0; i < points.length; i++) {
      let p = points[i];
      let thickness = map(p.t, 0, 1, 90, 15) + noise(i * 0.1 + layer + 50, layer) * 40;
      let c = lerpColor(col1, col3, p.t * 0.7);
      c.setAlpha(layerAlpha + noise(i * 0.05 + 100) * 20);
      fill(c);
      ellipse(p.x - thickness - layerOffset, p.y, thickness * 0.6, 25);
    }
  }

  // Core of the form
  for (let i = 0; i < points.length; i++) {
    let p = points[i];
    let thickness = map(p.t, 0, 1, 60, 8);
    let c = lerpColor(col1, col2, p.t);
    c.setAlpha(50 + noise(i * 0.08) * 30);
    fill(c);
    noStroke();
    ellipse(p.x, p.y, thickness * 1.2, 30 + noise(i * 0.1) * 15);
  }

  // Draw branches/extensions at the top
  for (let b = 0; b < 6; b++) {
    let startIdx = floor(80 + b * 5 + noise(b) * 10);
    if (startIdx >= points.length) continue;
    let startP = points[startIdx];

    let branchAngle = (side * 0.3 + (b - 3) * 0.4) + noise(b * 3) * 0.5;
    let branchLen = 80 + noise(b * 7) * 150;

    for (let j = 0; j < branchLen; j += 4) {
      let bt = j / branchLen;
      let bx = startP.x + cos(branchAngle) * j + noise(j * 0.02 + b) * 30;
      let by = startP.y + sin(branchAngle) * j * 0.3 - bt * 60;
      let bSize = map(bt, 0, 1, 20, 3) * (1 + noise(j * 0.05 + b) * 0.5);
      let c = lerpColor(col2, col3, bt);
      c.setAlpha(map(bt, 0, 1, 60, 10));
      fill(c);
      ellipse(bx, by, bSize, bSize * 0.8);
    }
  }

  // Draw roots at the bottom
  for (let r = 0; r < 5; r++) {
    let rootAngle = PI / 2 + side * 0.2 + (r - 2) * 0.3;
    let startX = baseX + (r - 2) * 30;
    let startY = height * 0.93;

    for (let j = 0; j < 120; j += 4) {
      let rt = j / 120;
      let rx = startX + cos(rootAngle) * j * 0.8 + side * j * 0.5 + noise(j * 0.03 + r) * 25;
      let ry = startY + sin(rootAngle) * j * 0.4 + j * 0.3;
      let rSize = map(rt, 0, 1, 25, 3);
      let c = lerpColor(col1, color(40, 20, 15), rt);
      c.setAlpha(map(rt, 0, 1, 70, 5));
      fill(c);
      ellipse(rx, ry, rSize, rSize * 0.7);
    }
  }
}

function drawIntertwine() {
  // Draw connecting tendrils between the two forms in the upper-middle area
  let centerY = height * 0.4;

  for (let i = 0; i < 30; i++) {
    let y = centerY + (noise(i * 0.5) - 0.5) * 300;
    let x1 = width / 2 - 100 - noise(i * 0.3 + 10) * 80;
    let x2 = width / 2 + 100 + noise(i * 0.3 + 20) * 80;

    let midX = width / 2 + (noise(i * 0.7) - 0.5) * 60;
    let midY = y + (noise(i * 0.4 + 5) - 0.5) * 80;

    let c1 = lerpColor(color(220, 80, 60), color(255, 160, 100), noise(i * 0.2));
    let c2 = lerpColor(color(180, 40, 90), color(255, 130, 150), noise(i * 0.2 + 3));

    // Draw flowing connection
    noFill();
    for (let layer = 0; layer < 4; layer++) {
      let offset = (layer - 2) * 3;
      let alpha = map(layer, 0, 3, 30, 10);
      let cMid = lerpColor(c1, c2, 0.5);
      cMid.setAlpha(alpha);
      stroke(cMid);
      strokeWeight(3 + noise(i + layer) * 4);
      bezier(x1, y + offset, midX - 50, midY - 40 + offset, midX + 50, midY + 40 + offset, x2, y + offset);
    }
  }

  // Central merge glow
  noStroke();
  for (let r = 150; r > 0; r -= 2) {
    let alpha = map(r, 0, 150, 12, 0);
    let c = lerpColor(color(255, 120, 60), color(255, 80, 120), r / 150);
    c.setAlpha(alpha);
    fill(c);
    ellipse(width / 2 + noise(r * 0.1) * 20, height * 0.4 + noise(r * 0.1 + 5) * 30, r * 1.5, r * 1.8);
  }
}

function drawParticles() {
  // Small glowing particles concentrated around the merge area
  for (let i = 0; i < 400; i++) {
    let px = width / 2 + (noise(i * 0.1, 0) - 0.5) * 600;
    let py = height * 0.35 + (noise(i * 0.1, 10) - 0.5) * 500;

    // More particles near center
    let distFromCenter = dist(px, py, width / 2, height * 0.4);
    if (distFromCenter > 400 && random() > 0.3) continue;

    let size = noise(i * 0.2) * 8 + 2;
    let alpha = map(distFromCenter, 0, 400, 80, 15);
    alpha *= (0.5 + noise(i * 0.3) * 0.5);

    let colChoice = noise(i * 0.15);
    let c;
    if (colChoice < 0.33) {
      c = color(255, 200, 100, alpha);
    } else if (colChoice < 0.66) {
      c = color(255, 140, 120, alpha);
    } else {
      c = color(255, 220, 180, alpha);
    }

    noStroke();
    fill(c);
    ellipse(px, py, size, size);

    // Glow around particle
    if (size > 5) {
      fill(red(c), green(c), blue(c), alpha * 0.2);
      ellipse(px, py, size * 3, size * 3);
    }
  }

  // Larger soft orbs
  for (let i = 0; i < 20; i++) {
    let px = width / 2 + (noise(i * 0.3, 5) - 0.5) * 350;
    let py = height * 0.4 + (noise(i * 0.3, 15) - 0.5) * 250;
    let size = 20 + noise(i * 0.5) * 40;

    noStroke();
    fill(255, 180, 100, 8);
    ellipse(px, py, size * 3, size * 3);
    fill(255, 200, 140, 15);
    ellipse(px, py, size, size);
    fill(255, 230, 200, 25);
    ellipse(px, py, size * 0.4, size * 0.4);
  }
}

function drawTexture() {
  // Add painterly texture with tiny dots
  for (let i = 0; i < 3000; i++) {
    let px = random(width);
    let py = random(height);
    let n = noise(px * 0.003, py * 0.003);

    if (n > 0.55) {
      let alpha = map(n, 0.55, 0.8, 0, 15);
      fill(255, 240, 220, alpha);
      noStroke();
      ellipse(px, py, 1 + random(2), 1 + random(2));
    }

    if (n < 0.35) {
      let alpha = map(n, 0.35, 0.1, 0, 12);
      fill(0, 0, 0, alpha);
      noStroke();
      ellipse(px, py, 1 + random(3), 1 + random(3));
    }
  }
}

function drawVignette() {
  // Dark vignette around edges
  noFill();
  for (let i = 0; i < 80; i++) {
    let alpha = map(i, 0, 80, 0, 40);
    stroke(10, 5, 15, alpha);
    strokeWeight(20);
    let margin = i * 15;
    rect(margin, margin, width - margin * 2, height - margin * 2);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function draw() {
  background(15, 12, 30);

  // Deep atmospheric background layers
  for (let i = 0; i < 80000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.002, y * 0.002);
    let r = lerp(10, 40, n);
    let g = lerp(8, 25, n);
    let b = lerp(35, 70, n);
    stroke(r, g, b, random(10, 30));
    strokeWeight(random(1, 4));
    point(x, y);
  }

  // Subtle warm glow in center
  for (let i = 0; i < 30000; i++) {
    let angle = random(TWO_PI);
    let radius = random(400) * random(0.3, 1);
    let x = width / 2 + cos(angle) * radius;
    let y = height / 2 - 100 + sin(angle) * radius * 1.2;
    let alpha = map(radius, 0, 400, 15, 0);
    stroke(80, 40, 60, alpha);
    strokeWeight(random(2, 6));
    point(x, y);
  }

  // Define two figure centers
  let leftX = width / 2 - 180;
  let rightX = width / 2 + 180;
  let centerY = height / 2 - 50;

  // Draw left figure (facing right)
  drawFigure(leftX, centerY, 1);

  // Draw right figure (facing left)
  drawFigure(rightX, centerY, -1);

  // Luminous particles between them
  drawConnectionParticles(leftX, rightX, centerY);

  // Floating ambient particles
  drawAmbientParticles();

  // Subtle light rays from center
  drawLightRays(width / 2, centerY);
}

function drawFigure(cx, cy, direction) {
  // Figure made of many small brushstrokes
  // Head
  let headY = cy - 320;
  let headR = 65;

  for (let i = 0; i < 3000; i++) {
    let angle = random(TWO_PI);
    let r = random(headR) * sqrt(random());
    let x = cx + direction * 10 + cos(angle) * r;
    let y = headY + sin(angle) * r * 1.1;
    let n = noise(x * 0.01, y * 0.01);
    let shade = lerp(25, 65, n);
    stroke(shade + 10, shade - 5, shade + 20, random(40, 80));
    strokeWeight(random(1.5, 3.5));
    point(x, y);
  }

  // Neck
  for (let i = 0; i < 800; i++) {
    let x = cx + direction * 10 + randomGaussian() * 18;
    let y = headY + headR + random(50);
    let shade = noise(x * 0.02, y * 0.02) * 40 + 20;
    stroke(shade + 5, shade, shade + 15, random(30, 70));
    strokeWeight(random(1.5, 3));
    point(x, y);
  }

  // Torso
  let torsoTop = headY + headR + 50;
  let torsoBottom = torsoTop + 350;

  for (let i = 0; i < 15000; i++) {
    let t = random();
    let y = lerp(torsoTop, torsoBottom, t);
    let bodyWidth = lerp(70, 90, t) + noise(y * 0.01) * 20;
    let x = cx + direction * 5 + randomGaussian() * bodyWidth * 0.5;

    // Lean slightly toward center
    x += direction * (1 - t) * 20;

    let n = noise(x * 0.008, y * 0.008);
    let shade = lerp(20, 55, n);
    stroke(shade + 8, shade - 3, shade + 18, random(25, 65));
    strokeWeight(random(1.5, 4));
    point(x, y);
  }

  // Arms reaching toward the other figure
  let armStartY = torsoTop + 60;
  for (let i = 0; i < 5000; i++) {
    let t = random();
    let armX = lerp(cx + direction * 60, cx + direction * 160, t);
    let armY = armStartY + t * 80 + randomGaussian() * 20 + sin(t * PI) * -40;
    let spread = lerp(15, 35, t);
    armX += randomGaussian() * spread * 0.4;
    armY += randomGaussian() * spread * 0.3;

    // Particles dissolve at the hand end
    let alpha = lerp(60, 15, t * t);
    let n = noise(armX * 0.01, armY * 0.01);
    let shade = lerp(30, 60, n);
    stroke(shade + 10, shade, shade + 15, alpha);
    strokeWeight(random(1.5, 3.5));
    point(armX, armY);
  }

  // Lower body / legs fading out
  for (let i = 0; i < 8000; i++) {
    let t = random();
    let y = lerp(torsoBottom, torsoBottom + 400, t);
    let legSpread = lerp(30, 80, t);
    let legChoice = random() > 0.5 ? 1 : -1;
    let x = cx + direction * 5 + legChoice * legSpread + randomGaussian() * 25;

    let alpha = lerp(50, 0, t);
    let shade = noise(x * 0.01, y * 0.01) * 35 + 20;
    stroke(shade, shade - 5, shade + 12, alpha);
    strokeWeight(random(1.5, 3.5));
    point(x, y);
  }

  // Edge dissolution particles (right edge of left figure, left edge of right figure)
  let edgeX = cx + direction * 80;
  for (let i = 0; i < 4000; i++) {
    let y = random(torsoTop - 100, torsoBottom + 200);
    let distFromEdge = random(100) * random();
    let x = edgeX + direction * distFromEdge;

    let alpha = map(distFromEdge, 0, 100, 50, 0);
    // Warm golden tones for dissolution
    let warmR = lerp(60, 180, distFromEdge / 100);
    let warmG = lerp(40, 130, distFromEdge / 100);
    let warmB = lerp(50, 60, distFromEdge / 100);
    stroke(warmR, warmG, warmB, alpha);
    strokeWeight(random(1, 3));
    point(x + randomGaussian() * 5, y + randomGaussian() * 5);
  }
}

function drawConnectionParticles(leftX, rightX, cy) {
  let midX = (leftX + rightX) / 2;

  // Dense warm particles in the space between
  for (let i = 0; i < 20000; i++) {
    let t = random();
    let x = lerp(leftX + 80, rightX - 80, t);
    let yCenter = cy - 100;
    let ySpread = 300;
    let y = yCenter + randomGaussian() * ySpread * 0.5;

    // More particles concentrated in center
    let distFromCenter = abs(x - midX) / ((rightX - leftX) / 2);
    if (random() > (1 - distFromCenter * 0.5)) continue;

    let n = noise(x * 0.005, y * 0.005, i * 0.001);

    // Gold, amber, rose palette
    let palette = random();
    let r, g, b;
    if (palette < 0.4) {
      // Gold
      r = lerp(200, 255, n);
      g = lerp(150, 200, n);
      b = lerp(50, 80, n);
    } else if (palette < 0.7) {
      // Rose
      r = lerp(180, 230, n);
      g = lerp(80, 120, n);
      b = lerp(100, 150, n);
    } else {
      // Warm white
      r = lerp(220, 255, n);
      g = lerp(200, 240, n);
      b = lerp(180, 220, n);
    }

    let alpha = map(distFromCenter, 0, 1, 70, 10);
    alpha *= random(0.5, 1.5);

    stroke(r, g, b, alpha);
    strokeWeight(random(1, 4));
    point(x, y);
  }

  // Bright core sparks
  for (let i = 0; i < 3000; i++) {
    let x = midX + randomGaussian() * 50;
    let y = cy - 100 + randomGaussian() * 150;
    let size = random(1, 5);

    stroke(255, 240, 200, random(30, 90));
    strokeWeight(size);
    point(x, y);

    // Glow around bright points
    if (random() < 0.3) {
      stroke(255, 200, 120, random(5, 15));
      strokeWeight(size + random(3, 8));
      point(x, y);
    }
  }
}

function drawAmbientParticles() {
  // Scattered warm particles across the whole canvas
  for (let i = 0; i < 5000; i++) {
    let x = random(width);
    let y = random(height);
    let distFromCenter = dist(x, y, width / 2, height / 2 - 100);
    let maxDist = 800;

    if (distFromCenter > maxDist && random() > 0.3) continue;

    let alpha = map(distFromCenter, 0, maxDist, 40, 5);
    let n = noise(x * 0.003, y * 0.003);

    stroke(200 + n * 55, 160 + n * 40, 100 + n * 80, alpha * random(0.3, 1));
    strokeWeight(random(0.5, 2.5));
    point(x, y);
  }

  // A few bright stars
  for (let i = 0; i < 200; i++) {
    let x = random(width);
    let y = random(height);
    let brightness = random(100, 255);
    stroke(brightness, brightness, brightness + 20, random(20, 60));
    strokeWeight(random(0.5, 2));
    point(x, y);
  }
}

function drawLightRays(cx, cy) {
  // Subtle radial light rays
  for (let i = 0; i < 60; i++) {
    let angle = random(TWO_PI);
    let length = random(200, 600);
    let startR = random(50, 100);

    for (let t = 0; t < 1; t += 0.02) {
      let r = lerp(startR, length, t);
      let x = cx + cos(angle + t * 0.1) * r;
      let y = cy + sin(angle + t * 0.1) * r;
      let alpha = (1 - t) * 8;

      stroke(200, 170, 120, alpha);
      strokeWeight(random(1, 3));
      point(x, y);
    }
  }

  // Central luminous orb suggestion
  for (let i = 0; i < 5000; i++) {
    let angle = random(TWO_PI);
    let r = random(80) * random();
    let x = cx + cos(angle) * r;
    let y = cy - 100 + sin(angle) * r;
    let alpha = map(r, 0, 80, 30, 0);

    stroke(255, 220, 170, alpha * random(0.5, 1.5));
    strokeWeight(random(1, 3));
    point(x, y);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  pixelDensity(1);
}

function draw() {
  // Deep background
  for (let y = 0; y < 2000; y += 4) {
    for (let x = 0; x < 1600; x += 4) {
      let n = noise(x * 0.003, y * 0.003);
      let n2 = noise(x * 0.008 + 100, y * 0.008 + 100);
      let r = lerp(8, 25, n) + n2 * 10;
      let g = lerp(5, 18, n);
      let b = lerp(30, 60, n) + n2 * 15;
      noStroke();
      fill(r, g, b);
      rect(x, y, 4, 4);
    }
  }

  // Soft vignette
  for (let i = 0; i < 200; i++) {
    let alpha = map(i, 0, 200, 0, 3);
    noFill();
    stroke(5, 3, 20, alpha);
    strokeWeight(8);
    ellipse(800, 950, 1600 - i * 4, 2000 - i * 5);
  }

  // Ground area - subtle warm glow at bottom
  for (let y = 1500; y < 2000; y += 3) {
    for (let x = 0; x < 1600; x += 3) {
      let n = noise(x * 0.005, y * 0.005);
      let fade = map(y, 1500, 2000, 0, 1);
      let r = lerp(10, 40, fade) + n * 20;
      let g = lerp(8, 20, fade) + n * 10;
      let b = lerp(35, 30, fade) + n * 10;
      fill(r, g, b, 180);
      noStroke();
      rect(x, y, 3, 3);
    }
  }

  // Central golden glow behind figures
  for (let r = 400; r > 0; r -= 3) {
    let alpha = map(r, 0, 400, 40, 0);
    fill(255, 200, 80, alpha * 0.3);
    noStroke();
    ellipse(800, 900, r * 2, r * 2.5);
  }

  // Draw left figure (warm - coral/rose)
  drawWarmFigure();

  // Draw right figure (cool - teal/indigo)
  drawCoolFigure();

  // Draw the embrace / merging area
  drawEmbrace();

  // Flowing hair/energy lines
  drawFlowingLines();

  // Luminous particles where they meet
  drawParticles();

  // Small flower-like shapes at meeting point
  drawFlowers();

  // Floating ambient particles throughout
  drawAmbientParticles();

  // Final overlay glow at center
  for (let r = 150; r > 0; r -= 2) {
    let alpha = map(r, 0, 150, 25, 0);
    fill(255, 230, 150, alpha * 0.4);
    noStroke();
    ellipse(800, 870, r * 1.5, r * 1.8);
  }
}

function drawWarmFigure() {
  // Main body shape - warm figure leaning right
  let cx = 650;
  let cy = 900;

  // Body mass with organic blobs
  for (let i = 0; i < 800; i++) {
    let angle = random(TWO_PI);
    let radiusX = random(80, 220);
    let radiusY = random(100, 350);
    let px = cx + cos(angle) * radiusX * (0.6 + 0.4 * noise(i * 0.1));
    let py = cy + sin(angle) * radiusY * (0.6 + 0.4 * noise(i * 0.1 + 50));

    // Bias toward center-right (toward embrace)
    px += random(-20, 60);

    if (py < 500 || py > 1600) continue;

    let n = noise(px * 0.01, py * 0.01);
    let r = lerp(160, 220, n);
    let g = lerp(50, 100, n);
    let b = lerp(60, 90, n);
    let sz = random(8, 30);
    fill(r, g, b, random(30, 80));
    noStroke();
    ellipse(px, py, sz, sz * random(0.8, 1.3));
  }

  // Head area
  for (let i = 0; i < 300; i++) {
    let angle = random(TWO_PI);
    let rad = random(10, 70);
    let px = 680 + cos(angle) * rad;
    let py = 580 + sin(angle) * rad * 1.1;
    let n = noise(px * 0.02, py * 0.02);
    let r = lerp(180, 230, n);
    let g = lerp(70, 120, n);
    let b = lerp(70, 100, n);
    fill(r, g, b, random(40, 90));
    noStroke();
    ellipse(px, py, random(6, 20), random(6, 20));
  }

  // Arm reaching right (toward other figure)
  for (let i = 0; i < 200; i++) {
    let t = random(1);
    let px = lerp(720, 820, t) + random(-30, 30) * noise(i * 0.05);
    let py = lerp(750, 850, t * t) + random(-20, 20);
    let n = noise(px * 0.015, py * 0.015);
    fill(lerp(170, 210, n), lerp(60, 100, n), lerp(65, 90, n), random(30, 70));
    noStroke();
    ellipse(px, py, random(8, 22), random(8, 18));
  }

  // Shoulder/torso definition
  beginShape();
  noFill();
  stroke(200, 80, 80, 30);
  strokeWeight(3);
  let points = [];
  for (let a = -PI * 0.8; a < PI * 0.6; a += 0.1) {
    let r = 180 + noise(a * 2) * 60;
    let px = 650 + cos(a) * r * 0.7;
    let py = 850 + sin(a) * r * 1.2;
    points.push({ x: px, y: py });
  }
  for (let p of points) {
    point(p.x + random(-3, 3), p.y + random(-3, 3));
  }
  endShape();
}

function drawCoolFigure() {
  // Main body shape - cool figure leaning left
  let cx = 950;
  let cy = 900;

  // Body mass with organic blobs
  for (let i = 0; i < 800; i++) {
    let angle = random(TWO_PI);
    let radiusX = random(80, 220);
    let radiusY = random(100, 350);
    let px = cx + cos(angle) * radiusX * (0.6 + 0.4 * noise(i * 0.1 + 200));
    let py = cy + sin(angle) * radiusY * (0.6 + 0.4 * noise(i * 0.1 + 250));

    // Bias toward center-left (toward embrace)
    px += random(-60, 20);

    if (py < 500 || py > 1600) continue;

    let n = noise(px * 0.01 + 10, py * 0.01 + 10);
    let r = lerp(30, 70, n);
    let g = lerp(80, 150, n);
    let b = lerp(140, 210, n);
    let sz = random(8, 30);
    fill(r, g, b, random(30, 80));
    noStroke();
    ellipse(px, py, sz, sz * random(0.8, 1.3));
  }

  // Head area
  for (let i = 0; i < 300; i++) {
    let angle = random(TWO_PI);
    let rad = random(10, 70);
    let px = 920 + cos(angle) * rad;
    let py = 590 + sin(angle) * rad * 1.1;
    let n = noise(px * 0.02 + 5, py * 0.02 + 5);
    let r = lerp(40, 90, n);
    let g = lerp(90, 160, n);
    let b = lerp(160, 220, n);
    fill(r, g, b, random(40, 90));
    noStroke();
    ellipse(px, py, random(6, 20), random(6, 20));
  }

  // Arm reaching left (toward other figure)
  for (let i = 0; i < 200; i++) {
    let t = random(1);
    let px = lerp(880, 780, t) + random(-30, 30) * noise(i * 0.05 + 100);
    let py = lerp(760, 860, t * t) + random(-20, 20);
    let n = noise(px * 0.015 + 5, py * 0.015 + 5);
    fill(lerp(40, 80, n), lerp(90, 150, n), lerp(150, 210, n), random(30, 70));
    noStroke();
    ellipse(px, py, random(8, 22), random(8, 18));
  }
}

function drawEmbrace() {
  // The golden merging zone between figures
  let cx = 800;
  let cy = 850;

  // Warm-cool blending particles
  for (let i = 0; i < 500; i++) {
    let angle = random(TWO_PI);
    let radX = random(20, 120);
    let radY = random(30, 200);
    let px = cx + cos(angle) * radX;
    let py = cy + sin(angle) * radY;

    let distFromCenter = dist(px, py, cx, cy);
    let blend = map(distFromCenter, 0, 150, 1, 0);
    blend = constrain(blend, 0, 1);

    let r = lerp(255, 200, blend) * blend + lerp(80, 180, 1 - blend) * (1 - blend);
    let g = lerp(200, 160, blend) * blend + lerp(120, 100, 1 - blend) * (1 - blend);
    let b = lerp(80, 60, blend) * blend + lerp(180, 100, 1 - blend) * (1 - blend);

    fill(r, g, b, random(20, 60) * blend + 10);
    noStroke();
    ellipse(px, py, random(5, 18), random(5, 18));
  }

  // Bright core
  for (let i = 0; i < 150; i++) {
    let angle = random(TWO_PI);
    let rad = random(5, 50);
    let px = cx + cos(angle) * rad;
    let py = (cy - 30) + sin(angle) * rad * 1.2;
    fill(255, 220, 120, random(20, 50));
    noStroke();
    ellipse(px, py, random(4, 14), random(4, 14));
  }
}

function drawFlowingLines() {
  // Warm figure flowing lines (hair/energy flowing left)
  for (let l = 0; l < 12; l++) {
    noFill();
    let startAlpha = random(20, 50);
    stroke(200 + random(-20, 20), 80 + random(-20, 20), 80 + random(-20, 20), startAlpha);
    strokeWeight(random(1, 3));
    beginShape();
    let sx = 680 + random(-30, 30);
    let sy = 550 + random(-20, 20);
    curveVertex(sx, sy);
    curveVertex(sx, sy);
    for (let p = 0; p < 6; p++) {
      let px = sx - p * random(20, 50) + noise(l, p) * 60;
      let py = sy + p * random(20, 40) + noise(l + 10, p) * 40 - 30;
      curveVertex(px, py);
    }
    let ex = sx - 200 + random(-50, 50);
    let ey = sy + 150 + random(-30, 30);
    curveVertex(ex, ey);
    curveVertex(ex, ey);
    endShape();
  }

  // Cool figure flowing lines (hair/energy flowing right)
  for (let l = 0; l < 12; l++) {
    noFill();
    let startAlpha = random(20, 50);
    stroke(50 + random(-10, 20), 120 + random(-20, 20), 200 + random(-20, 20), startAlpha);
    strokeWeight(random(1, 3));
    beginShape();
    let sx = 920 + random(-30, 30);
    let sy = 560 + random(-20, 20);
    curveVertex(sx, sy);
    curveVertex(sx, sy);
    for (let p = 0; p < 6; p++) {
      let px = sx + p * random(20, 50) + noise(l + 20, p) * 60;
      let py = sy + p * random(20, 40) + noise(l + 30, p) * 40 - 30;
      curveVertex(px, py);
    }
    let ex = sx + 200 + random(-50, 50);
    let ey = sy + 150 + random(-30, 30);
    curveVertex(ex, ey);
    curveVertex(ex, ey);
    endShape();
  }
}

function drawParticles() {
  // Golden luminous particles at the meeting point
  for (let i = 0; i < 200; i++) {
    let angle = random(TWO_PI);
    let rad = random(10, 180);
    let px = 800 + cos(angle) * rad;
    let py = 830 + sin(angle) * rad * 1.3;

    let brightness = map(rad, 10, 180, 255, 100);
    let sz = map(rad, 10, 180, random(3, 8), random(1, 4));
    let alpha = map(rad, 10, 180, random(150, 255), random(30, 80));

    // Glow
    fill(255, 220, 100, alpha * 0.3);
    noStroke();
    ellipse(px, py, sz * 4, sz * 4);

    // Core
    fill(brightness, brightness * 0.85, brightness * 0.4, alpha);
    ellipse(px, py, sz, sz);
  }

  // Rising particles (like sparks or fireflies going up)
  for (let i = 0; i < 80; i++) {
    let px = 800 + random(-200, 200);
    let py = random(300, 800);
    let sz = random(2, 6);
    let alpha = map(py, 300, 800, random(30, 80), random(100, 200));
    let distFromCenter = abs(px - 800);
    let warmth = map(distFromCenter, 0, 200, 1, 0);

    let r = lerp(100, 255, warmth);
    let g = lerp(150, 220, warmth);
    let b = lerp(200, 100, warmth);

    fill(r, g, b, alpha * 0.3);
    noStroke();
    ellipse(px, py, sz * 5, sz * 5);
    fill(r, g, b, alpha);
    ellipse(px, py, sz, sz);
  }
}

function drawFlowers() {
  // Small abstract flower shapes at the embrace point
  for (let f = 0; f < 25; f++) {
    let fx = 800 + random(-130, 130);
    let fy = 820 + random(-150, 180);
    let fSize = random(8, 22);
    let petals = floor(random(4, 8));

    push();
    translate(fx, fy);
    rotate(random(TWO_PI));

    // Petals
    for (let p = 0; p < petals; p++) {
      let angle = (TWO_PI / petals) * p;
      let petalLen = fSize * random(0.8, 1.2);
      let px = cos(angle) * petalLen;
      let py = sin(angle) * petalLen;

      let n = noise(fx * 0.01 + p, fy * 0.01);
      let r = lerp(220, 255, n);
      let g = lerp(150, 210, n);
      let b = lerp(80, 140, n);

      fill(r, g, b, random(60, 120));
      noStroke();
      ellipse(px * 0.5, py * 0.5, fSize * 0.5, fSize * 0.3);
    }

    // Center
    fill(255, 230, 120, 150);
    ellipse(0, 0, fSize * 0.3, fSize * 0.3);

    pop();
  }
}

function drawAmbientParticles() {
  // Scattered stars/particles throughout the scene
  for (let i = 0; i < 300; i++) {
    let px = random(1600);
    let py = random(2000);
    let sz = random(1, 4);

    // Avoid being too bright in the center (that's handled separately)
    let distFromCenter = dist(px, py, 800, 850);
    if (distFromCenter < 200) continue;

    let n = noise(px * 0.005, py * 0.005);
    let alpha = random(20, 80) * n;

    // Color based on position - warm on left, cool on right
    let sideBlend = map(px, 0, 1600, 0, 1);
    let r = lerp(200, 80, sideBlend);
    let g = lerp(120, 140, sideBlend);
    let b = lerp(100, 200, sideBlend);

    fill(r, g, b, alpha);
    noStroke();
    ellipse(px, py, sz, sz);

    if (sz > 2.5) {
      fill(r, g, b, alpha * 0.2);
      ellipse(px, py, sz * 4, sz * 4);
    }
  }

  // Subtle connecting curves between the two figures at top
  for (let l = 0; l < 5; l++) {
    noFill();
    stroke(180, 140, 160, 15);
    strokeWeight(1);
    beginShape();
    curveVertex(600, 400 + l * 20);
    curveVertex(600, 400 + l * 20);
    curveVertex(700, 350 + noise(l) * 50);
    curveVertex(800, 320 + noise(l + 1) * 40);
    curveVertex(900, 350 + noise(l + 2) * 50);
    curveVertex(1000, 400 + l * 20);
    curveVertex(1000, 400 + l * 20);
    endShape();
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  background(8, 8, 22);

  // Subtle radial background gradient
  for (let y = 0; y < 2000; y += 4) {
    for (let x = 0; x < 1600; x += 4) {
      let d = dist(x, y, 800, 1000) / 1200;
      let v = map(d, 0, 1, 28, 6);
      v = constrain(v, 4, 30);
      noStroke();
      fill(v, v * 0.9, v * 1.3);
      rect(x, y, 4, 4);
    }
  }

  // Organic blob generator
  function drawBlob(cx, cy, baseR, color1, color2, layers, noiseScale, noiseOff) {
    for (let l = layers; l >= 1; l--) {
      let t = l / layers;
      let r = baseR * (0.3 + 0.7 * t);
      let alpha = map(l, 1, layers, 180, 20);
      let col = lerpColor(color(color1), color(color2), 1 - t);

      // Multiple passes for glow
      for (let pass = 0; pass < 3; pass++) {
        let expandR = r + pass * 15;
        let passAlpha = alpha * (1 - pass * 0.3);

        noStroke();
        fill(red(col), green(col), blue(col), passAlpha * 0.3);
        beginShape();
        let steps = 120;
        for (let i = 0; i <= steps; i++) {
          let angle = map(i, 0, steps, 0, TWO_PI);
          let n = noise(
            cos(angle) * noiseScale + noiseOff,
            sin(angle) * noiseScale + noiseOff,
            l * 0.3 + pass * 0.1
          );
          let rad = expandR * (0.7 + 0.6 * n);
          let px = cx + cos(angle) * rad;
          let py = cy + sin(angle) * rad;
          curveVertex(px, py);
        }
        endShape(CLOSE);
      }
    }
  }

  // Draw tendrils/extensions reaching toward each other
  function drawTendril(sx, sy, ex, ey, col, thickness, noiseOff) {
    let steps = 80;
    noFill();
    for (let pass = 0; pass < 5; pass++) {
      strokeWeight(thickness - pass * 2);
      let a = map(pass, 0, 4, 120, 15);
      stroke(red(col), green(col), blue(col), a);
      beginShape();
      for (let i = 0; i <= steps; i++) {
        let t = i / steps;
        let bx = lerp(sx, ex, t);
        let by = lerp(sy, ey, t);
        // Add curve
        let perp = sin(t * PI) * 120;
        let nx = noise(t * 3 + noiseOff, pass * 0.5) * 2 - 1;
        let ny = noise(t * 3 + noiseOff + 100, pass * 0.5) * 2 - 1;
        bx += nx * perp;
        by += ny * perp * 0.6;
        curveVertex(bx, by);
      }
      endShape();
    }
  }

  let c1 = color(220, 55, 90);    // Warm rose
  let c1b = color(255, 120, 140); // Light rose
  let c2 = color(40, 140, 160);   // Deep teal
  let c2b = color(80, 200, 210);  // Light teal

  // Main blobs
  drawBlob(550, 720, 420, c1, c1b, 8, 1.8, 0);
  drawBlob(1050, 1280, 420, c2, c2b, 8, 1.8, 50);

  // Tendrils reaching toward center
  drawTendril(700, 850, 850, 1050, c1, 12, 10);
  drawTendril(900, 1150, 820, 980, c2, 12, 20);
  drawTendril(600, 900, 780, 1020, c1b, 8, 30);
  drawTendril(1000, 1100, 830, 990, c2b, 8, 40);

  // The luminous "between" — golden light at the meeting point
  let centerX = 800;
  let centerY = 1000;

  // Multiple glowing layers
  for (let l = 20; l >= 1; l--) {
    let r = l * 25;
    let alpha = map(l, 1, 20, 80, 3);
    noStroke();
    let glow = lerpColor(color(255, 220, 100, alpha), color(255, 255, 240, alpha), 0.5);
    fill(red(glow), green(glow), blue(glow), alpha);
    ellipse(centerX, centerY, r * 2, r * 2.4);
  }

  // Core bright light
  for (let l = 10; l >= 1; l--) {
    let r = l * 8;
    let alpha = map(l, 1, 10, 200, 30);
    fill(255, 250, 230, alpha);
    noStroke();
    ellipse(centerX, centerY, r * 2, r * 2.2);
  }
  fill(255, 255, 250, 240);
  noStroke();
  ellipse(centerX, centerY, 18, 20);

  // Particles flowing between the forms
  for (let i = 0; i < 600; i++) {
    let t = random();
    let angle = random(TWO_PI);
    let distFromCenter = random(30, 500);

    // Bias particles toward the connection line
    let px = lerp(550, 1050, t) + random(-200, 200);
    let py = lerp(720, 1280, t) + random(-200, 200);

    // More particles near center
    let dCenter = dist(px, py, centerX, centerY);
    let prob = map(dCenter, 0, 500, 1, 0.2);

    if (random() < prob) {
      let sz = random(1.5, 5);
      let brightness = map(dCenter, 0, 500, 255, 80);
      let warmCool = t;
      let pc;
      if (warmCool < 0.4) {
        pc = lerpColor(c1, color(255, 220, 100), map(dCenter, 0, 400, 0.8, 0));
      } else if (warmCool > 0.6) {
        pc = lerpColor(c2, color(255, 220, 100), map(dCenter, 0, 400, 0.8, 0));
      } else {
        pc = color(255, 240, 180);
      }

      noStroke();
      fill(red(pc), green(pc), blue(pc), random(60, 180));
      ellipse(px, py, sz, sz);
    }
  }

  // Scattered ambient particles across canvas
  for (let i = 0; i < 300; i++) {
    let px = random(1600);
    let py = random(2000);
    let sz = random(0.5, 2.5);
    let alpha = random(20, 80);
    noStroke();
    fill(200, 200, 220, alpha);
    ellipse(px, py, sz, sz);
  }

  // Soft vignette
  for (let i = 0; i < 40; i++) {
    noFill();
    stroke(8, 8, 22, map(i, 0, 39, 0, 12));
    strokeWeight(30);
    let inset = i * 15;
    rect(inset, inset, 1600 - inset * 2, 2000 - inset * 2, 50);
  }

  noLoop();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
  draw();
}

function draw() {
  background(10, 8, 18);

  // Subtle background texture
  for (let i = 0; i < 80000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.003, y * 0.003);
    let a = n * 15;
    fill(40, 20, 60, a);
    noStroke();
    ellipse(x, y, random(1, 3));
  }

  // Define two organic form centers
  let cx1 = 480, cy1 = 950;
  let cx2 = 1120, cy2 = 1050;

  // Draw the connecting threads first (behind forms)
  drawThreads(cx1, cy1, cx2, cy2);

  // Draw glowing particles in the between space
  drawBetweenGlow(cx1, cy1, cx2, cy2);

  // Draw the two organic forms
  drawOrganicForm(cx1, cy1, 280, [180, 80, 50], [220, 120, 70]);
  drawOrganicForm(cx2, cy2, 260, [60, 50, 140], [100, 70, 170]);

  // Draw threads in front (some overlap)
  drawFrontThreads(cx1, cy1, cx2, cy2);

  // Final particles and highlights
  drawFinalParticles(cx1, cy1, cx2, cy2);

  // Vignette
  drawVignette();
}

function drawOrganicForm(cx, cy, baseR, innerCol, outerCol) {
  // Multiple layers of noise-deformed shapes
  for (let layer = 5; layer >= 0; layer--) {
    let r = baseR + layer * 40;
    let points = 120;
    let alpha = layer === 0 ? 180 : 30 + layer * 8;

    beginShape();
    noStroke();

    let col = lerpColor(
      color(outerCol[0], outerCol[1], outerCol[2], alpha),
      color(innerCol[0], innerCol[1], innerCol[2], alpha),
      1 - layer / 5
    );
    fill(col);

    for (let i = 0; i <= points; i++) {
      let angle = map(i, 0, points, 0, TWO_PI);
      let nx = cx + cos(angle) * 0.5;
      let ny = cy + sin(angle) * 0.5;
      let n = noise(nx * 0.8 + layer * 10, ny * 0.8 + layer * 10, layer * 3.7);
      let radius = r * (0.7 + n * 0.6);
      let x = cx + cos(angle) * radius;
      let y = cy + sin(angle) * radius;
      curveVertex(x, y);
    }
    endShape(CLOSE);
  }

  // Inner glow
  for (let i = 0; i < 200; i++) {
    let angle = random(TWO_PI);
    let dist = random(baseR * 0.8);
    let n = noise(cx + cos(angle) * dist * 0.01, cy + sin(angle) * dist * 0.01);
    if (n > 0.4) {
      let x = cx + cos(angle) * dist * n;
      let y = cy + sin(angle) * dist * n;
      let a = map(dist, 0, baseR * 0.8, 60, 5);
      fill(innerCol[0] + 40, innerCol[1] + 40, innerCol[2] + 20, a);
      noStroke();
      ellipse(x, y, random(2, 8));
    }
  }
}

function drawThreads(cx1, cy1, cx2, cy2) {
  let midX = (cx1 + cx2) / 2;
  let midY = (cy1 + cy2) / 2;

  for (let i = 0; i < 600; i++) {
    let angle1 = random(TWO_PI);
    let angle2 = random(TWO_PI);
    let r1 = random(180, 320);
    let r2 = random(160, 300);

    let n1 = noise(cos(angle1) * 2 + 5, sin(angle1) * 2 + 5);
    let n2 = noise(cos(angle2) * 2 + 8, sin(angle2) * 2 + 8);

    let x1 = cx1 + cos(angle1) * r1 * n1;
    let y1 = cy1 + sin(angle1) * r1 * n1;
    let x2 = cx2 + cos(angle2) * r2 * n2;
    let y2 = cy2 + sin(angle2) * r2 * n2;

    let ctrl1x = x1 + (midX - x1) * random(0.3, 0.7) + random(-80, 80);
    let ctrl1y = y1 + (midY - y1) * random(0.3, 0.7) + random(-150, 150);
    let ctrl2x = x2 + (midX - x2) * random(0.3, 0.7) + random(-80, 80);
    let ctrl2y = y2 + (midY - y2) * random(0.3, 0.7) + random(-150, 150);

    let t = random();
    let r = lerp(255, 255, t);
    let g = lerp(180, 220, t);
    let b = lerp(80, 140, t);
    let a = random(8, 35);

    stroke(r, g, b, a);
    strokeWeight(random(0.3, 1.5));
    noFill();
    bezier(x1, y1, ctrl1x, ctrl1y, ctrl2x, ctrl2y, x2, y2);
  }
}

function drawFrontThreads(cx1, cy1, cx2, cy2) {
  for (let i = 0; i < 200; i++) {
    let angle1 = random(TWO_PI);
    let angle2 = random(TWO_PI);
    let r1 = random(200, 300);
    let r2 = random(180, 280);

    let x1 = cx1 + cos(angle1) * r1 * noise(angle1 * 3);
    let y1 = cy1 + sin(angle1) * r1 * noise(angle1 * 3 + 100);
    let x2 = cx2 + cos(angle2) * r2 * noise(angle2 * 3 + 50);
    let y2 = cy2 + sin(angle2) * r2 * noise(angle2 * 3 + 150);

    let midX = (x1 + x2) / 2 + random(-60, 60);
    let midY = (y1 + y2) / 2 + random(-100, 100);

    stroke(255, 220, 120, random(5, 20));
    strokeWeight(random(0.5, 2));
    noFill();
    bezier(x1, y1, midX, midY - random(100), midX, midY + random(100), x2, y2);
  }
}

function drawBetweenGlow(cx1, cy1, cx2, cy2) {
  let midX = (cx1 + cx2) / 2;
  let midY = (cy1 + cy2) / 2;

  // Central glow
  for (let i = 0; i < 3000; i++) {
    let x = midX + randomGaussian() * 200;
    let y = midY + randomGaussian() * 300;
    let distToMid = dist(x, y, midX, midY);
    let a = map(distToMid, 0, 400, 50, 0);
    a = constrain(a, 0, 50);

    let size = random(2, 12);
    fill(255, 200, 100, a * 0.5);
    noStroke();
    ellipse(x, y, size);
  }

  // Bright core particles
  for (let i = 0; i < 1500; i++) {
    let t = random();
    let x = lerp(cx1 + 250, cx2 - 220, t) + randomGaussian() * 60;
    let y = lerp(cy1, cy2, t) + randomGaussian() * 120;

    let distToLine = abs(y - lerp(cy1, cy2, t));
    let a = map(distToLine, 0, 200, 80, 0);
    a = constrain(a, 0, 80);

    let colT = noise(x * 0.005, y * 0.005);
    let r = lerp(255, 255, colT);
    let g = lerp(160, 230, colT);
    let b = lerp(60, 150, colT);

    fill(r, g, b, a);
    noStroke();
    ellipse(x, y, random(1, 5));
  }
}

function drawFinalParticles(cx1, cy1, cx2, cy2) {
  // Scattered luminous particles throughout
  for (let i = 0; i < 2000; i++) {
    let x = random(width);
    let y = random(height);

    let d1 = dist(x, y, cx1, cy1);
    let d2 = dist(x, y, cx2, cy2);
    let dMid = dist(x, y, (cx1 + cx2) / 2, (cy1 + cy2) / 2);

    let inBetween = 1 - constrain(dMid / 500, 0, 1);
    let a = inBetween * random(20, 60) + random(2, 8);

    let n = noise(x * 0.004, y * 0.004);
    if (n > 0.45) {
      fill(255, lerp(180, 240, n), lerp(80, 180, n), a);
      noStroke();
      let s = random(1, 4) * (1 + inBetween);
      ellipse(x, y, s);
    }
  }

  // Bright accent dots in the between
  for (let i = 0; i < 100; i++) {
    let t = random(0.2, 0.8);
    let x = lerp(cx1 + 200, cx2 - 200, t) + randomGaussian() * 40;
    let y = lerp(cy1, cy2, t) + randomGaussian() * 80;

    fill(255, 240, 200, random(40, 90));
    noStroke();
    ellipse(x, y, random(2, 6));

    // Tiny halo
    fill(255, 220, 150, 15);
    ellipse(x, y, random(10, 25));
  }
}

function drawVignette() {
  let cx = width / 2;
  let cy = height / 2;

  for (let i = 0; i < 50; i++) {
    let r = max(width, height) * (0.5 + i * 0.02);
    noFill();
    stroke(10, 8, 18, 20 + i * 3);
    strokeWeight(40);
    ellipse(cx, cy, r * 2, r * 2.5);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  pixelDensity(1);
}

function draw() {
  // Deep background gradient
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(8, 20, t * t);
    let g = lerp(3, 8, t);
    let b = lerp(35, 25, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Subtle background texture
  noStroke();
  for (let i = 0; i < 80000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.003, y * 0.003);
    if (n > 0.5) {
      let alpha = (n - 0.5) * 30;
      fill(40, 20, 70, alpha);
      ellipse(x, y, random(1, 4));
    }
  }

  // Ambient warm glow from center
  for (let i = 50; i > 0; i--) {
    let size = i * 50;
    let alpha = map(i, 50, 0, 1, 8);
    fill(180, 60, 40, alpha);
    noStroke();
    ellipse(width / 2, height * 0.45, size, size * 1.3);
  }

  // Central luminous core
  for (let i = 40; i > 0; i--) {
    let size = i * 20;
    let alpha = map(i, 40, 0, 1, 12);
    fill(255, 200, 120, alpha);
    noStroke();
    ellipse(width / 2, height * 0.43, size * 0.8, size * 1.1);
  }

  // Draw left organic form
  drawForm(-1);

  // Draw right organic form  
  drawForm(1);

  // Flowing connection ribbons
  drawRibbons();

  // Particles in the space between
  drawBetweenParticles();

  // Scattered light motes throughout
  drawLightMotes();

  // Final luminous veil
  drawVeil();
}

function drawForm(side) {
  // side: -1 for left, 1 for right
  let cx = width / 2 + side * 280;
  let cy = height * 0.48;

  // Main body - layered organic blobs
  for (let layer = 0; layer < 12; layer++) {
    let layerT = layer / 12;
    let baseSize = 400 - layer * 15;
    let offsetX = side * (30 + layer * 8);
    let offsetY = layer * 10 - 60;

    // Color shifts from deep burgundy to warm crimson
    let r = lerp(60, 180, layerT);
    let g = lerp(10, 40, layerT);
    let b = lerp(30, 60, layerT);
    let alpha = lerp(40, 15, layerT);

    fill(r, g, b, alpha);
    noStroke();

    beginShape();
    for (let angle = 0; angle < TWO_PI; angle += 0.05) {
      let noiseVal = noise(
        cos(angle) * 1.5 + layer * 0.3 + side * 10,
        sin(angle) * 1.5 + layer * 0.3,
        layer * 0.5
      );
      let radius = baseSize + noiseVal * 180 - 90;

      // Stretch toward center
      let stretchAngle = side === -1 ? 0 : PI;
      let angleDiff = Math.abs(angle - (side === -1 ? 0 : TWO_PI));
      if (angleDiff > PI) angleDiff = TWO_PI - angleDiff;
      let stretch = 1 + (1 - angleDiff / PI) * 0.4;

      let x = cx + offsetX + cos(angle) * radius * stretch * (side === -1 ? 0.9 : 1.1);
      let y = cy + offsetY + sin(angle) * radius * 0.85;

      curveVertex(x, y);
    }
    endShape(CLOSE);
  }

  // Inner warm glow on the side facing center
  for (let i = 20; i > 0; i--) {
    let glowX = cx + side * (-50 + i * 3);
    let glowY = cy - 30;
    let size = i * 25;
    let alpha = map(i, 20, 0, 2, 12);
    fill(220, 100, 50, alpha);
    noStroke();
    ellipse(glowX, glowY, size * 0.7, size);
  }

  // Textural details - small organic marks
  for (let i = 0; i < 3000; i++) {
    let angle = random(TWO_PI);
    let dist = random(350);
    let nx = noise(i * 0.1, 0) * 200 - 100;
    let ny = noise(0, i * 0.1) * 200 - 100;
    let x = cx + side * 30 + cos(angle) * dist + nx;
    let y = cy - 50 + sin(angle) * dist * 0.8 + ny;

    if (dist < 300) {
      let n = noise(x * 0.01, y * 0.01);
      let r = lerp(120, 220, n);
      let g = lerp(30, 80, n);
      let b = lerp(40, 90, n);
      let alpha = map(dist, 0, 300, 30, 5) * random(0.5, 1.5);
      fill(r, g, b, alpha);
      noStroke();
      ellipse(x, y, random(2, 8), random(2, 8));
    }
  }

  // Flowing curves emanating from the form toward center
  for (let i = 0; i < 8; i++) {
    let startY = cy - 200 + i * 50 + random(-30, 30);
    let startX = cx + side * 100;

    noFill();
    let r = lerp(200, 255, random());
    let g = lerp(80, 160, random());
    let b = lerp(50, 100, random());
    stroke(r, g, b, 20);
    strokeWeight(random(1, 3));

    beginShape();
    for (let t = 0; t <= 1; t += 0.02) {
      let x = lerp(startX, width / 2 + side * 20, t);
      let y = startY + sin(t * PI * 3 + i) * 60 * t;
      let nx = noise(t * 3 + i, i) * 80 - 40;
      let ny = noise(i, t * 3 + i) * 80 - 40;
      curveVertex(x + nx, y + ny);
    }
    endShape();
  }
}

function drawRibbons() {
  // Flowing ribbons of light connecting the two forms
  for (let r = 0; r < 15; r++) {
    let startSide = random() > 0.5 ? -1 : 1;
    let startX = width / 2 + startSide * 250;
    let startY = height * 0.48 + random(-300, 200);
    let endX = width / 2 - startSide * 250;
    let endY = startY + random(-100, 100);

    let midX = width / 2 + random(-80, 80);
    let midY = (startY + endY) / 2 + random(-100, 100);

    noFill();
    let ribbonR = lerp(220, 255, random());
    let ribbonG = lerp(120, 200, random());
    let ribbonB = lerp(60, 140, random());

    for (let w = 0; w < 5; w++) {
      stroke(ribbonR, ribbonG, ribbonB, 8 - w);
      strokeWeight(6 - w);

      beginShape();
      for (let t = 0; t <= 1; t += 0.02) {
        let x = bezierPoint(startX, midX - 100, midX + 100, endX, t);
        let y = bezierPoint(startY, midY - 80, midY + 80, endY, t);
        let n = noise(t * 5 + r, r * 0.5) * 40 - 20;
        let wOffset = (w - 2) * 3;
        curveVertex(x + n, y + n + wOffset);
      }
      endShape();
    }
  }
}

function drawBetweenParticles() {
  // Dense field of warm particles in the space between forms
  let centerX = width / 2;
  let centerY = height * 0.45;

  for (let i = 0; i < 5000; i++) {
    let angle = random(TWO_PI);
    let distX = random(250);
    let distY = random(400);
    let x = centerX + cos(angle) * distX * (0.5 + noise(i * 0.01) * 0.5);
    let y = centerY + sin(angle) * distY * (0.5 + noise(i * 0.01 + 100) * 0.5);

    let distFromCenter = Math.sqrt((x - centerX) ** 2 + ((y - centerY) * 0.7) ** 2);
    let maxDist = 350;

    if (distFromCenter < maxDist) {
      let t = 1 - distFromCenter / maxDist;
      let size = random(1, 4) * (1 + t * 2);
      let alpha = t * t * 80 * random(0.5, 1.5);

      let r = lerp(255, 255, t);
      let g = lerp(150, 230, t);
      let b = lerp(50, 180, t);

      // Glow around particle
      fill(r, g, b, alpha * 0.3);
      noStroke();
      ellipse(x, y, size * 4);

      fill(r, g, b, alpha);
      ellipse(x, y, size);

      // Bright core
      fill(255, 255, 240, alpha * 0.8);
      ellipse(x, y, size * 0.4);
    }
  }
}

function drawLightMotes() {
  // Scattered luminous motes throughout the entire canvas
  for (let i = 0; i < 2000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.002, y * 0.002, 0.5);

    if (n > 0.45) {
      let intensity = (n - 0.45) * 5;
      let size = random(1, 3) * intensity;
      let alpha = intensity * 40 * random(0.5, 1.5);

      // Color based on position - warmer near center, cooler at edges
      let distFromCenter = Math.abs(x - width / 2) / (width / 2);
      let r = lerp(255, 150, distFromCenter);
      let g = lerp(200, 100, distFromCenter);
      let b = lerp(150, 200, distFromCenter);

      fill(r, g, b, alpha * 0.4);
      noStroke();
      ellipse(x, y, size * 5);

      fill(r, g, b, alpha);
      ellipse(x, y, size);
    }
  }
}

function drawVeil() {
  // Final soft luminous veil - gives the painting a dreamy quality
  // Soft vignette
  for (let i = 0; i < 30; i++) {
    let margin = i * 30;
    noFill();
    stroke(5, 2, 20, 15);
    strokeWeight(60);
    rect(margin, margin, width - margin * 2, height - margin * 2, 200);
  }

  // Top and bottom fade to dark
  for (let y = 0; y < 200; y++) {
    let alpha = map(y, 0, 200, 60, 0);
    fill(8, 3, 30, alpha);
    noStroke();
    rect(0, y, width, 1);
    rect(0, height - y - 1, width, 1);
  }

  // Central bright bloom
  for (let i = 25; i > 0; i--) {
    let size = i * 30;
    let alpha = map(i, 25, 0, 1, 6);
    fill(255, 220, 180, alpha);
    noStroke();
    ellipse(width / 2, height * 0.43, size * 1.2, size * 1.5);
  }

  // Delicate highlight dots at the very center
  for (let i = 0; i < 200; i++) {
    let angle = random(TWO_PI);
    let dist = random(80);
    let x = width / 2 + cos(angle) * dist;
    let y = height * 0.43 + sin(angle) * dist * 1.2;
    let size = random(1, 3);
    let alpha = map(dist, 0, 80, 60, 5);
    fill(255, 250, 240, alpha);
    noStroke();
    ellipse(x, y, size);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  pixelDensity(1);
}

function draw() {
  background(10, 7, 22);

  // Subtle background dust
  noStroke();
  for (let i = 0; i < 12000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.002, y * 0.002, 3.7);
    if (n > 0.42) {
      let a = map(n, 0.42, 0.85, 0, 22);
      fill(160, 140, 200, constrain(a, 0, 22));
      circle(x, y, random(0.5, 2.2));
    }
  }

  let cx1 = 500, cy1 = 700;
  let cx2 = 1100, cy2 = 1300;

  // Large ambient glows
  drawAmbientGlow(cx1, cy1, 750, 140, 30, 60);
  drawAmbientGlow(cx2, cy2, 750, 20, 50, 140);

  // Internal flowing currents for form 1
  drawInternalFlows(cx1, cy1, 360, color(220, 80, 100), color(255, 170, 110), 0);
  // Internal flowing currents for form 2
  drawInternalFlows(cx2, cy2, 360, color(40, 90, 180), color(90, 200, 220), 100);

  // Organic cloud forms
  drawCloud(cx1, cy1, 400, color(190, 45, 75), color(255, 160, 100), 400);
  drawCloud(cx2, cy2, 400, color(25, 65, 155), color(80, 200, 225), 400);

  // Second layer - softer, larger
  drawCloud(cx1, cy1, 350, color(230, 100, 110), color(255, 200, 150), 200);
  drawCloud(cx2, cy2, 350, color(60, 110, 190), color(140, 220, 240), 200);

  // Connecting threads
  drawThreads(cx1, cy1, cx2, cy2);

  // Intersection glow layers
  let mx = (cx1 + cx2) / 2, my = (cy1 + cy2) / 2;
  drawGlow(mx, my, 350, 255, 200, 120, 1.5);
  drawGlow(mx, my, 220, 255, 230, 170, 2.5);
  drawGlow(mx, my, 120, 255, 250, 220, 3.5);
  drawGlow(mx, my, 50, 255, 255, 245, 5);

  // Small sparks in intersection
  drawSparks(mx, my, 250, 300);

  // Floating particles throughout
  drawFloatingParticles(cx1, cy1, cx2, cy2);
}

function drawAmbientGlow(cx, cy, radius, r, g, b) {
  noStroke();
  for (let rad = radius; rad > 0; rad -= 5) {
    let t = 1 - rad / radius;
    fill(r, g, b, 1.8 * t * t);
    ellipse(cx, cy, rad * 2, rad * 2);
  }
}

function drawCloud(cx, cy, radius, colInner, colOuter, count) {
  noStroke();
  for (let i = 0; i < count; i++) {
    let angle = random(TWO_PI);
    let rawDist = random(1);
    let dist = radius * sqrt(rawDist);
    let ox = cos(angle) * dist;
    let oy = sin(angle) * dist;

    let n = noise((cx + ox) * 0.003, (cy + oy) * 0.003, i * 0.005);
    let size = map(n, 0, 1, 30, 160);
    let t = dist / radius;
    let col = lerpColor(colInner, colOuter, t * t);
    let alpha = map(t, 0, 1, 10, 2);
    alpha *= map(n, 0, 1, 0.5, 1.5);

    fill(red(col), green(col), blue(col), constrain(alpha, 0, 15));
    let stretch = random(0.75, 1.3);
    push();
    translate(cx + ox, cy + oy);
    rotate(angle + noise(i * 0.1) * PI);
    ellipse(0, 0, size, size * stretch);
    pop();
  }
}

function drawInternalFlows(cx, cy, radius, col1, col2, offset) {
  noFill();
  for (let i = 0; i < 60; i++) {
    let startAngle = random(TWO_PI);
    let startDist = random(radius * 0.2, radius * 0.8);
    let x = cx + cos(startAngle) * startDist;
    let y = cy + sin(startAngle) * startDist;

    let col = lerpColor(col1, col2, random());
    stroke(red(col), green(col), blue(col), random(4, 12));
    strokeWeight(random(0.5, 2));

    beginShape();
    for (let j = 0; j < 30; j++) {
      let n1 = noise(x * 0.003 + offset, y * 0.003, j * 0.05 + i * 0.1);
      let n2 = noise(x * 0.003 + offset + 100, y * 0.003 + 100, j * 0.05 + i * 0.1);
      let dx = map(n1, 0, 1, -15, 15);
      let dy = map(n2, 0, 1, -15, 15);
      x += dx;
      y += dy;
      let dFromCenter = dist(x, y, cx, cy);
      if (dFromCenter < radius * 1.1) {
        curveVertex(x, y);
      }
    }
    endShape();
  }
}

function drawThreads(cx1, cy1, cx2, cy2) {
  let mx = (cx1 + cx2) / 2;
  let my = (cy1 + cy2) / 2;

  for (let i = 0; i < 120; i++) {
    let t1 = random(1);
    let angle1 = random(TWO_PI);
    let dist1 = random(80, 350);
    let x1 = cx1 + cos(angle1) * dist1 * 0.9;
    let y1 = cy1 + sin(angle1) * dist1 * 0.9;

    let angle2 = random(TWO_PI);
    let dist2 = random(80, 350);
    let x2 = cx2 + cos(angle2) * dist2 * 0.9;
    let y2 = cy2 + sin(angle2) * dist2 * 0.9;

    let cpx1 = lerp(x1, mx, random(0.3, 0.7)) + random(-150, 150);
    let cpy1 = lerp(y1, my, random(0.3, 0.7)) + random(-150, 150);
    let cpx2 = lerp(x2, mx, random(0.3, 0.7)) + random(-150, 150);
    let cpy2 = lerp(y2, my, random(0.3, 0.7)) + random(-150, 150);

    let r = lerp(200, 100, random());
    let g = lerp(120, 180, random());
    let b = lerp(140, 220, random());
    stroke(r, g, b, random(3, 10));
    strokeWeight(random(0.3, 1.5));
    noFill();
    bezier(x1, y1, cpx1, cpy1, cpx2, cpy2, x2, y2);
  }

  // Brighter threads closer to center
  for (let i = 0; i < 40; i++) {
    let angle1 = random(TWO_PI);
    let dist1 = random(30, 200);
    let x1 = mx + cos(angle1) * dist1 + random(-100, 100);
    let y1 = my + sin(angle1) * dist1 + random(-100, 100);

    let angle2 = random(TWO_PI);
    let dist2 = random(30, 200);
    let x2 = mx + cos(angle2) * dist2 + random(-100, 100);
    let y2 = my + sin(angle2) * dist2 + random(-100, 100);

    let cpx = mx + random(-80, 80);
    let cpy = my + random(-80, 80);

    stroke(255, 220, 160, random(5, 15));
    strokeWeight(random(0.3, 1.2));
    noFill();
    bezier(x1, y1, cpx, cpy, cpx, cpy, x2, y2);
  }
}

function drawGlow(cx, cy, radius, r, g, b, intensity) {
  noStroke();
  for (let rad = radius; rad > 0; rad -= 3) {
    let t = 1 - rad / radius;
    fill(r, g, b, intensity * t * t);
    ellipse(cx, cy, rad * 2, rad * 2);
  }
}

function drawSparks(cx, cy, spread, count) {
  noStroke();
  for (let i = 0; i < count; i++) {
    let angle = random(TWO_PI);
    let d = random(spread) * sqrt(random());
    let x = cx + cos(angle) * d;
    let y = cy + sin(angle) * d;
    let t = d / spread;
    let size = random(1, 4) * (1 - t * 0.5);
    let alpha = map(t, 0, 1, 60, 10) * random(0.5, 1.5);

    fill(255, 245, 210, constrain(alpha, 0, 80));
    circle(x, y, size);

    // Tiny glow around spark
    fill(255, 220, 150, constrain(alpha * 0.2, 0, 15));
    circle(x, y, size * 4);
  }
}

function drawFloatingParticles(cx1, cy1, cx2, cy2) {
  noStroke();
  let mx = (cx1 + cx2) / 2;
  let my = (cy1 + cy2) / 2;

  for (let i = 0; i < 500; i++) {
    let x = random(width);
    let y = random(height);
    let d1 = dist(x, y, cx1, cy1);
    let d2 = dist(x, y, cx2, cy2);
    let dm = dist(x, y, mx, my);

    let nearForm = (d1 < 500 || d2 < 500 || dm < 400);
    if (!nearForm && random() > 0.3) continue;

    let size, r, g, b, alpha;

    if (dm < 300) {
      // Near intersection - warm bright
      size = random(1, 5);
      r = random(230, 255);
      g = random(200, 240);
      b = random(140, 200);
      alpha = random(15, 50);
    } else if (d1 < d2) {
      // Near form 1 - warm
      size = random(0.8, 3);
      r = random(200, 255);
      g = random(100, 170);
      b = random(80, 140);
      alpha = random(8, 30);
    } else {
      // Near form 2 - cool
      size = random(0.8, 3);
      r = random(80, 150);
      g = random(160, 220);
      b = random(200, 255);
      alpha = random(8, 30);
    }

    fill(r, g, b, alpha);
    circle(x, y, size);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function draw() {
  background(8, 6, 20);

  // Subtle background gradient - deep space feel
  for (let y = 0; y < 2000; y++) {
    let inter = y / 2000;
    let r = lerp(8, 15, sin(inter * PI));
    let g = lerp(6, 8, sin(inter * PI));
    let b = lerp(20, 30, sin(inter * PI));
    stroke(r, g, b);
    line(0, y, 1600, y);
  }

  // Background noise texture
  loadPixels();
  for (let x = 0; x < 1600; x += 2) {
    for (let y = 0; y < 2000; y += 2) {
      let n = noise(x * 0.003, y * 0.003);
      let idx = (y * 1600 + x) * 4;
      let add = n * 15;
      pixels[idx] += add;
      pixels[idx+1] += add * 0.5;
      pixels[idx+2] += add * 1.2;
      pixels[idx+3] = 255;
    }
  }
  updatePixels();

  // Define the two forms
  let form1 = { x: 650, y: 450 };  // Upper-left organic mass
  let form2 = { x: 950, y: 1550 }; // Lower-right organic mass
  let meetPoint = { x: 800, y: 1000 };

  // Draw distant ambient glow from each form
  drawAmbientGlow(form1.x, form1.y, 500, [20, 60, 120], 0.02);
  drawAmbientGlow(form2.x, form2.y, 500, [120, 40, 60], 0.02);
  drawAmbientGlow(meetPoint.x, meetPoint.y, 400, [180, 140, 60], 0.03);

  // Draw tendrils/filaments connecting the two forms
  drawTendrils(form1, meetPoint, [40, 100, 160], [220, 180, 80], 80, 0);
  drawTendrils(form2, meetPoint, [160, 60, 80], [220, 180, 80], 80, 100);

  // Draw the organic forms themselves
  drawOrganicForm(form1.x, form1.y, 220, [20, 50, 110], [60, 130, 180], [140, 200, 220]);
  drawOrganicForm(form2.x, form2.y, 220, [100, 30, 50], [180, 70, 100], [220, 160, 170]);

  // Draw inner glow/life of each form
  drawInnerLife(form1.x, form1.y, 150, [80, 160, 220]);
  drawInnerLife(form2.x, form2.y, 150, [220, 100, 140]);

  // Draw the meeting point - the luminous connection
  drawMeetingPoint(meetPoint.x, meetPoint.y);

  // Draw secondary tendrils - thinner, more numerous
  drawFineFilaments(form1, form2, meetPoint);

  // Scattered particles - love's radiation
  drawParticles(meetPoint);

  // Final overlay glow at center
  drawCenterGlow(meetPoint.x, meetPoint.y);

  // Subtle vignette
  drawVignette();
}

function drawAmbientGlow(cx, cy, radius, col, alpha) {
  noStroke();
  for (let r = radius; r > 0; r -= 5) {
    let a = alpha * (1 - r / radius) * 255;
    fill(col[0], col[1], col[2], a);
    ellipse(cx, cy, r * 2, r * 2);
  }
}

function drawOrganicForm(cx, cy, baseRadius, colDeep, colMid, colLight) {
  // Multiple layers of noise-deformed shapes
  for (let layer = 0; layer < 12; layer++) {
    let radiusMult = 1.0 - layer * 0.06;
    let noiseScale = 0.8 + layer * 0.1;
    let noiseOffset = layer * 10;

    let col;
    if (layer < 4) col = colDeep;
    else if (layer < 8) col = colMid;
    else col = colLight;

    let alpha = 30 + layer * 5;

    noStroke();
    fill(col[0], col[1], col[2], alpha);

    beginShape();
    for (let angle = 0; angle < TWO_PI; angle += 0.05) {
      let nx = cos(angle) * noiseScale + noiseOffset;
      let ny = sin(angle) * noiseScale + noiseOffset;
      let n = noise(nx, ny, layer * 3.7);
      let r = baseRadius * radiusMult * (0.6 + n * 0.8);

      // Add secondary noise for more organic feel
      let n2 = noise(nx * 2.5, ny * 2.5, layer * 1.3);
      r += n2 * 30 * radiusMult;

      let x = cx + cos(angle) * r;
      let y = cy + sin(angle) * r;
      vertex(x, y);
    }
    endShape(CLOSE);
  }
}

function drawInnerLife(cx, cy, radius, col) {
  // Bright inner core with noise-based brightness variation
  for (let i = 0; i < 30; i++) {
    let angle = random(TWO_PI);
    let dist = random(radius * 0.7);
    let n = noise(cx * 0.01 + i, cy * 0.01 + i);
    let r = 5 + n * 25;
    let alpha = 10 + n * 30;

    noStroke();
    fill(col[0], col[1], col[2], alpha);
    ellipse(cx + cos(angle) * dist, cy + sin(angle) * dist, r * 2, r * 2);
  }
}

function drawTendrils(from, to, colFrom, colTo, count, seedOffset) {
  for (let i = 0; i < count; i++) {
    let t = i / count;
    let seed = i * 7.3 + seedOffset;

    // Start point with some spread around the form
    let startAngle = noise(seed, 0) * TWO_PI;
    let startDist = 100 + noise(seed, 1) * 120;
    let sx = from.x + cos(startAngle) * startDist;
    let sy = from.y + sin(startAngle) * startDist;

    // End point near the meeting point
    let endAngle = noise(seed, 2) * TWO_PI;
    let endDist = 20 + noise(seed, 3) * 80;
    let ex = to.x + cos(endAngle) * endDist;
    let ey = to.y + sin(endAngle) * endDist;

    // Control points with noise
    let midX = (sx + ex) / 2;
    let midY = (sy + ey) / 2;
    let perpX = -(ey - sy);
    let perpY = (ex - sx);
    let perpLen = sqrt(perpX * perpX + perpY * perpY);
    perpX /= perpLen;
    perpY /= perpLen;

    let offset1 = (noise(seed, 4) - 0.5) * 300;
    let offset2 = (noise(seed, 5) - 0.5) * 300;

    let cp1x = sx + (ex - sx) * 0.3 + perpX * offset1;
    let cp1y = sy + (ey - sy) * 0.3 + perpY * offset1;
    let cp2x = sx + (ex - sx) * 0.7 + perpX * offset2;
    let cp2y = sy + (ey - sy) * 0.7 + perpY * offset2;

    // Draw the tendril as many thin segments
    let steps = 60;
    noFill();
    for (let s = 0; s < steps - 1; s++) {
      let st = s / steps;
      let et = (s + 1) / steps;

      let x1 = bezierPoint(sx, cp1x, cp2x, ex, st);
      let y1 = bezierPoint(sy, cp1y, cp2y, ey, st);
      let x2 = bezierPoint(sx, cp1x, cp2x, ex, et);
      let y2 = bezierPoint(sy, cp1y, cp2y, ey, et);

      // Add noise displacement
      let noiseDisp = noise(x1 * 0.005, y1 * 0.005, seed) * 15 - 7.5;
      x1 += noiseDisp;
      y1 += noiseDisp * 0.7;
      x2 += noiseDisp;
      y2 += noiseDisp * 0.7;

      // Color interpolation
      let r = lerp(colFrom[0], colTo[0], st);
      let g = lerp(colFrom[1], colTo[1], st);
      let b = lerp(colFrom[2], colTo[2], st);

      // Opacity: fade in at start, bright in middle, fade at end
      let a = sin(st * PI) * 40 + 10;
      let w = 0.5 + sin(st * PI) * 2;

      stroke(r, g, b, a);
      strokeWeight(w);
      line(x1, y1, x2, y2);
    }
  }
}

function drawFineFilaments(form1, form2, meetPoint) {
  // Very thin, numerous filaments
  for (let i = 0; i < 150; i++) {
    let seed = i * 13.7 + 500;
    let whichForm = i % 2;
    let from = whichForm === 0 ? form1 : form2;
    let colFrom = whichForm === 0 ? [60, 120, 180] : [180, 80, 110];

    let startAngle = noise(seed) * TWO_PI;
    let startDist = 80 + noise(seed + 1) * 160;
    let sx = from.x + cos(startAngle) * startDist;
    let sy = from.y + sin(startAngle) * startDist;

    // Some go to meeting point, some go partway
    let progress = 0.4 + noise(seed + 2) * 0.6;
    let ex = lerp(sx, meetPoint.x, progress) + (noise(seed + 3) - 0.5) * 100;
    let ey = lerp(sy, meetPoint.y, progress) + (noise(seed + 4) - 0.5) * 100;

    let cp1x = lerp(sx, ex, 0.33) + (noise(seed + 5) - 0.5) * 150;
    let cp1y = lerp(sy, ey, 0.33) + (noise(seed + 6) - 0.5) * 150;
    let cp2x = lerp(sx, ex, 0.66) + (noise(seed + 7) - 0.5) * 150;
    let cp2y = lerp(sy, ey, 0.66) + (noise(seed + 8) - 0.5) * 150;

    noFill();
    let steps = 30;
    for (let s = 0; s < steps - 1; s++) {
      let st = s / steps;
      let et = (s + 1) / steps;

      let x1 = bezierPoint(sx, cp1x, cp2x, ex, st);
      let y1 = bezierPoint(sy, cp1y, cp2y, ey, st);
      let x2 = bezierPoint(sx, cp1x, cp2x, ex, et);
      let y2 = bezierPoint(sy, cp1y, cp2y, ey, et);

      let r = lerp(colFrom[0], 220, st);
      let g = lerp(colFrom[1], 180, st);
      let b = lerp(colFrom[2], 80, st);
      let a = sin(st * PI) * 20;

      stroke(r, g, b, a);
      strokeWeight(0.5);
      line(x1, y1, x2, y2);
    }
  }
}

function drawMeetingPoint(cx, cy) {
  // Layered glowing intersection
  // Outer halo
  for (let r = 300; r > 0; r -= 3) {
    let alpha = (1 - r / 300) * 15;
    let warmth = 1 - r / 300;
    noStroke();
    fill(
      lerp(40, 255, warmth),
      lerp(30, 200, warmth),
      lerp(20, 80, warmth * 0.5),
      alpha
    );
    // Slightly irregular shape
    let nOff = r * 0.1;
    let rx = r * (0.9 + noise(nOff, 0) * 0.2);
    let ry = r * (0.9 + noise(nOff, 1) * 0.2);
    ellipse(cx, cy, rx * 2, ry * 2);
  }

  // Bright inner core
  for (let r = 80; r > 0; r -= 2) {
    let alpha = (1 - r / 80) * 60;
    noStroke();
    fill(255, 240, 200, alpha);
    ellipse(cx, cy, r * 2, r * 2);
  }

  // Hot white center
  for (let r = 30; r > 0; r -= 1) {
    let alpha = (1 - r / 30) * 100;
    noStroke();
    fill(255, 255, 245, alpha);
    ellipse(cx, cy, r * 2, r * 2);
  }

  // Radiating lines from center
  for (let i = 0; i < 60; i++) {
    let angle = noise(i * 5) * TWO_PI;
    let len = 50 + noise(i * 5 + 100) * 250;
    let x2 = cx + cos(angle) * len;
    let y2 = cy + sin(angle) * len;

    let steps = 20;
    for (let s = 0; s < steps; s++) {
      let st = s / steps;
      let et = (s + 1) / steps;
      let x1 = lerp(cx, x2, st);
      let y1 = lerp(cy, y2, st);
      let xx = lerp(cx, x2, et);
      let yy = lerp(cy, y2, et);

      let alpha = (1 - st) * 25;
      stroke(255, 220, 150, alpha);
      strokeWeight(1 - st * 0.8);
      line(x1, y1, xx, yy);
    }
  }
}

function drawParticles(meetPoint) {
  // Floating luminous particles scattered around
  for (let i = 0; i < 400; i++) {
    let angle = noise(i * 3.1) * TWO_PI;
    let dist = noise(i * 3.2) * 800;
    let px = meetPoint.x + cos(angle) * dist;
    let py = meetPoint.y + sin(angle) * dist;

    // More particles near center
    let proximity = 1 - dist / 800;
    let size = 1 + noise(i * 3.3) * 4 * proximity;
    let alpha = 20 + proximity * 150 * noise(i * 3.4);

    // Color varies: golden near center, cool at edges
    let r = lerp(100, 255, proximity);
    let g = lerp(80, 220, proximity);
    let b = lerp(140, 120, proximity);

    noStroke();
    fill(r, g, b, alpha);
    ellipse(px, py, size, size);

    // Glow around brighter particles
    if (proximity > 0.5 && noise(i * 3.5) > 0.5) {
      fill(r, g, b, alpha * 0.2);
      ellipse(px, py, size * 4, size * 4);
    }
  }
}

function drawCenterGlow(cx, cy) {
  // Final soft overlay bloom
  noStroke();
  for (let r = 500; r > 0; r -= 10) {
    let alpha = (1 - r / 500) * 8;
    fill(255, 200, 100, alpha);
    ellipse(cx, cy, r * 2, r * 1.5);
  }
}

function drawVignette() {
  // Dark edges
  noStroke();
  let maxDist = dist(0, 0, 800, 1000);
  for (let i = 0; i < 40; i++) {
    let t = i / 40;
    let alpha = t * t * 180;
    fill(5, 3, 12, alpha);

    // Draw border rectangles
    let margin = (1 - t) * 300;
    // Top
    rect(0, 0, 1600, margin);
    // Bottom
    rect(0, 2000 - margin, 1600, margin);
    // Left
    rect(0, 0, margin * 0.8, 2000);
    // Right
    rect(1600 - margin * 0.8, 0, margin * 0.8, 2000);
  }
}
